	///         Receives strongly typed lifecycle events from
	///         <see cref="M:STS2RitsuLib.RitsuLibFramework.SubscribeLifecycle(STS2RitsuLib.ILifecycleObserver,System.Boolean)" />.
	///     </para>
	///     <para xml:lang="zh-CN">接收来自 <see cref="M:STS2RitsuLib.RitsuLibFramework.SubscribeLifecycle(STS2RitsuLib.ILifecycleObserver,System.Boolean)" /> 的强类型生命周期事件。</para>
	/// </summary>
	public interface ILifecycleObserver
	{
		/// <summary>
		///     <para xml:lang="en">Receives each lifecycle event; implementations usually switch on its concrete type.</para>
		///     <para xml:lang="zh-CN">接收每个生命周期事件；实现通常按其具体类型分支。</para>
		/// </summary>
		/// <param name="evt">
		///     <para xml:lang="en">Lifecycle event instance.</para>
		///     <para xml:lang="zh-CN">生命周期事件实例。</para>
		/// </param>
		void OnEvent(IFrameworkLifecycleEvent evt);
	}
	internal sealed class DelegateLifecycleObserver<TEvent>(Action<TEvent> handler) : ILifecycleObserver where TEvent : IFrameworkLifecycleEvent
	{
		public void OnEvent(IFrameworkLifecycleEvent evt)
		{
			if (evt is TEvent obj)
			{
				handler(obj);
			}
		}
	}
	internal sealed class LifecycleSubscriptionHolder
	{
		public IDisposable Subscription { get; set; }
	}
	internal sealed class DelegateLifecycleObserverWithSubscription<TEvent>(Action<TEvent, IDisposable> handler, LifecycleSubscriptionHolder holder) : ILifecycleObserver where TEvent : IFrameworkLifecycleEvent
	{
		public void OnEvent(IFrameworkLifecycleEvent evt)
		{
			if (evt is TEvent arg)
			{
				handler(arg, holder.Subscription);
			}
		}
	}
	internal sealed class FrameworkLifecycleSubscription(Action unsubscribe) : IDisposable
	{
		private bool _disposed;

		public void Dispose()
		{
			if (!_disposed)
			{
				_disposed = true;
				unsubscribe();
			}
		}
	}
