	internal static class RitsuLibBuildInfo
	{
		internal const string DevPackageVersionPrefix = "9999.0.0-dev.";

		private static readonly Assembly Assembly = typeof(Const).Assembly;

		internal static string InformationalVersion { get; } = Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion ?? "0.5.18";

		internal static IReadOnlyDictionary<string, string> Metadata { get; } = Assembly.GetCustomAttributes<AssemblyMetadataAttribute>().ToDictionary<AssemblyMetadataAttribute, string, string>((AssemblyMetadataAttribute x) => x.Key, (AssemblyMetadataAttribute x) => x.Value ?? "", StringComparer.OrdinalIgnoreCase);

		internal static string Sts2ApiCompat { get; } = (Metadata.TryGetValue("Sts2ApiCompat", out string value) && !string.IsNullOrWhiteSpace(value)) ? value.Trim() : "unknown";

		internal static bool IsDevBuild
		{
			get
			{
				if (!InformationalVersion.StartsWith("9999.0.0-dev.", StringComparison.OrdinalIgnoreCase))
				{
					if (Metadata.TryGetValue("RitsuLibTelemetryBuildChannel", out string value))
					{
						return string.Equals(value.Trim(), "dev", StringComparison.OrdinalIgnoreCase);
					}
					return false;
				}
				return true;
			}
		}
	}
	internal static class RitsuLibExceptionPolicy
	{
		internal static bool IsRecoverable(Exception exception)
		{
			ArgumentNullException.ThrowIfNull(exception, "exception");
			if (!(exception is OutOfMemoryException) && !(exception is StackOverflowException) && !(exception is AccessViolationException) && !(exception is SEHException) && !(exception is OperationCanceledException) && !(exception is ThreadInterruptedException))
			{
				if (!(exception is AggregateException ex))
				{
					if (exception != null)
					{
						Exception innerException = exception.InnerException;
						if (innerException != null)
						{
							return IsRecoverable(innerException);
						}
					}
					return true;
				}
				return ex.InnerExceptions.All(IsRecoverable);
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides shared runtime bootstrap and public integration entry points for RitsuLib and the mods that use it.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为 RitsuLib 及其使用的模组提供共享的运行时启动和公共集成入口。
	///     </para>
	/// </summary>
	[ModInitializer("Initialize")]
	public static class RitsuLibFramework
	{
		private sealed record DeferredContentPackRegistration(string ModId, Action<ModContentPackContext> Apply, string? Description);

		private static class LifecycleEventTypeCache<TEvent> where TEvent : IFrameworkLifecycleEvent
		{
			public static readonly Type EventType = typeof(TEvent);

			public static readonly string EventName = EventType.Name;

			public static readonly bool SupportsTypedDispatch = EventType.IsValueType || EventType.IsSealed;

			public static readonly bool IsReplayable = typeof(IReplayableFrameworkLifecycleEvent).IsAssignableFrom(EventType);

			public static readonly bool InvalidatesProfileDataReady = EventType == typeof(ProfileDataInvalidatedEvent);
		}

		private sealed class LifecycleTopic<TEvent> where TEvent : IFrameworkLifecycleEvent
		{
			private Action<TEvent>[] _handlers = Array.Empty<Action<TEvent>>();

			public Action<TEvent>[] ReadSnapshot()
			{
				return Volatile.Read(in _handlers);
			}

			public void Add(Action<TEvent> handler)
			{
				Action<TEvent>[] array;
				Action<TEvent>[] value;
				do
				{
					array = Volatile.Read(in _handlers);
					value = AppendItem<Action<TEvent>>(array, handler);
				}
				while (Interlocked.CompareExchange(ref _handlers, value, array) != array);
			}

			public void Remove(Action<TEvent> handler)
			{
				Action<TEvent>[] array;
				Action<TEvent>[] array2;
				do
				{
					array = Volatile.Read(in _handlers);
					array2 = RemoveItem<Action<TEvent>>(array, handler);
				}
				while (array2 != array && Interlocked.CompareExchange(ref _handlers, array2, array) != array);
			}
		}

		internal enum FrameworkPatcherArea
		{
			Core,
			SettingsUi,
			ContentAssets,
			CharacterAssets,
			ContentRegistry,
			Persistence,
			Unlocks
		}

		private static readonly Lock SyncRoot;

		private static readonly Dictionary<FrameworkPatcherArea, ModPatcher> FrameworkPatchersByArea;

		private static bool _frameworkPatchesApplied;

		private static bool _frameworkInteropBootstrapRegistered;

		private static bool _profileServicesInitialized;

		private static ILifecycleObserver[] _lifecycleObservers;

		private static readonly ConcurrentDictionary<Type, object> LifecycleTopics;

		private static readonly Dictionary<Type, object> ReplayableLifecycleEvents;

		private static readonly HashSet<string> RegisteredScriptAssemblies;

		private static readonly HashSet<string> RegisteringScriptAssemblies;

		private static readonly Lock DeferredContentPackSync;

		private static readonly List<DeferredContentPackRegistration> DeferredContentPackRegistrations;

		private static bool _deferredContentPacksFlushed;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the framework logger.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取框架的日志记录器。
		///     </para>
		/// </summary>
		public static Logger Logger { get; }

