		static RitsuLibFramework()
		{
			SyncRoot = new Lock();
			FrameworkPatchersByArea = new Dictionary<FrameworkPatcherArea, ModPatcher>();
			_lifecycleObservers = Array.Empty<ILifecycleObserver>();
			LifecycleTopics = new ConcurrentDictionary<Type, object>();
			ReplayableLifecycleEvents = new Dictionary<Type, object>();
			RegisteredScriptAssemblies = new HashSet<string>();
			RegisteringScriptAssemblies = new HashSet<string>();
			DeferredContentPackSync = new Lock();
			DeferredContentPackRegistrations = new List<DeferredContentPackRegistration>();
			Logger = CreateLogger("com.ritsukage.sts2-RitsuLib", (LogType)0);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Subscribes an observer to framework lifecycle events, optionally replaying the current replayable state.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         订阅框架生命周期事件观察者，并可选择回放当前可回放状态。
		///     </para>
		/// </summary>
		/// <param name="observer">
		///     <para xml:lang="en">
		///         Receives lifecycle notifications via <c>OnEvent</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过 <c>OnEvent</c> 接收生命周期通知。
		///     </para>
		/// </param>
		/// <param name="replayCurrentState">
		///     <para xml:lang="en">
		///         When true, dispatches replayable events that already occurred.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <see langword="true" /> 时，派发已经发生过的可回放事件。
		///     </para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         Disposing unsubscribes the observer.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         释放返回值会取消订阅该观察者。
		///     </para>
		/// </returns>
		public static IDisposable SubscribeLifecycle(ILifecycleObserver observer, bool replayCurrentState = true)
		{
			ArgumentNullException.ThrowIfNull(observer, "observer");
			IFrameworkLifecycleEvent[] array;
			using (SyncRoot.EnterScope())
			{
				_lifecycleObservers = AppendItem(_lifecycleObservers, observer);
				array = (replayCurrentState ? (from IFrameworkLifecycleEvent evt in ReplayableLifecycleEvents.Values
					orderby evt.OccurredAtUtc
					select evt).ToArray() : Array.Empty<IFrameworkLifecycleEvent>());
			}
			IFrameworkLifecycleEvent[] array2 = array;
			foreach (IFrameworkLifecycleEvent frameworkLifecycleEvent in array2)
			{
				SafeNotify(observer, frameworkLifecycleEvent, frameworkLifecycleEvent.GetType().Name);
			}
			return new FrameworkLifecycleSubscription(delegate
			{
				using (SyncRoot.EnterScope())
				{
					_lifecycleObservers = RemoveItem(_lifecycleObservers, observer);
				}
			});
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Subscribes a typed callback for a specific <typeparamref name="TEvent" /> lifecycle event.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为特定 <typeparamref name="TEvent" /> 生命周期事件订阅类型化回调。
		///     </para>
		/// </summary>
		/// <typeparam name="TEvent">
		///     <para xml:lang="en">
		///         Concrete lifecycle event type.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         具体的生命周期事件类型。
		///     </para>
		/// </typeparam>
		/// <param name="handler">
		///     <para xml:lang="en">
		///         Invoked for each matching event.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         每次匹配事件到达时调用。
		///     </para>
		/// </param>
		/// <param name="replayCurrentState">
		///     <para xml:lang="en">
		///         When true, invokes <paramref name="handler" /> with the last replayable event if
		///         present.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <see langword="true" /> 时，如果存在最后一个可重放事件，则用它调用
		///         <paramref name="handler" />。
		///     </para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         Disposing unsubscribes the handler.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         释放返回值会取消订阅该回调。
		///     </para>
		/// </returns>
		public static IDisposable SubscribeLifecycle<TEvent>(Action<TEvent> handler, bool replayCurrentState = true) where TEvent : IFrameworkLifecycleEvent
		{
			ArgumentNullException.ThrowIfNull(handler, "handler");
			if (!LifecycleEventTypeCache<TEvent>.SupportsTypedDispatch)
			{
				return SubscribeLifecycle(new DelegateLifecycleObserver<TEvent>(handler), replayCurrentState);
			}
			object value = null;
			LifecycleTopic<TEvent> topic = GetLifecycleTopic<TEvent>();
			using (SyncRoot.EnterScope())
			{
				topic.Add(handler);
				if (replayCurrentState)
				{
					ReplayableLifecycleEvents.TryGetValue(LifecycleEventTypeCache<TEvent>.EventType, out value);
				}
			}
			if (value is TEvent evt)
			{
				SafeNotify(handler, evt, LifecycleEventTypeCache<TEvent>.EventName);
			}
			return new FrameworkLifecycleSubscription(delegate
			{
				using (SyncRoot.EnterScope())
				{
					topic.Remove(handler);
				}
			});
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Subscribes a typed callback for a specific <typeparamref name="TEvent" />, passing the same
		///         <see cref="T:System.IDisposable" /> subscription instance on every invocation (including synchronous replay).
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为特定 <typeparamref name="TEvent" /> 订阅类型化回调，并在每次调用时传入同一个
		///         <see cref="T:System.IDisposable" /> 订阅实例（包括同步重放）。
		///     </para>
		/// </summary>
		/// <typeparam name="TEvent">
		///     <para xml:lang="en">
		///         Concrete lifecycle event type.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         具体的生命周期事件类型。
		///     </para>
		/// </typeparam>
		/// <param name="handler">
		///     <para xml:lang="en">
		///         Invoked for each matching event. The <see cref="T:System.IDisposable" /> argument is the subscription; disposing it
		///         unsubscribes the handler.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         对每个匹配事件调用。<see cref="T:System.IDisposable" /> 参数是订阅；释放它会取消订阅该回调。
		///     </para>
		/// </param>
		/// <param name="replayCurrentState">
		///     <para xml:lang="en">
		///         When true, invokes <paramref name="handler" /> with the last replayable event if present.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <see langword="true" /> 时，如果存在最后一个可重放事件，则用它调用
		///         <paramref name="handler" />。
		///     </para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         Disposing unsubscribes the handler.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         释放返回值会取消订阅该回调。
		///     </para>
		/// </returns>
		public static IDisposable SubscribeLifecycle<TEvent>(Action<TEvent, IDisposable> handler, bool replayCurrentState = true) where TEvent : IFrameworkLifecycleEvent
		{
			ArgumentNullException.ThrowIfNull(handler, "handler");
			if (!LifecycleEventTypeCache<TEvent>.SupportsTypedDispatch)
			{
				LifecycleSubscriptionHolder lifecycleSubscriptionHolder = new LifecycleSubscriptionHolder();
				DelegateLifecycleObserverWithSubscription<TEvent> observer = new DelegateLifecycleObserverWithSubscription<TEvent>(handler, lifecycleSubscriptionHolder);
				IFrameworkLifecycleEvent[] array;
				using (SyncRoot.EnterScope())
				{
					_lifecycleObservers = AppendItem(_lifecycleObservers, observer);
					lifecycleSubscriptionHolder.Subscription = new FrameworkLifecycleSubscription(delegate
					{
						using (SyncRoot.EnterScope())
						{
							_lifecycleObservers = RemoveItem(_lifecycleObservers, observer);
						}
					});
					array = (replayCurrentState ? (from IFrameworkLifecycleEvent frameworkLifecycleEvent2 in ReplayableLifecycleEvents.Values
						orderby frameworkLifecycleEvent2.OccurredAtUtc
						select frameworkLifecycleEvent2).ToArray() : Array.Empty<IFrameworkLifecycleEvent>());
				}
				IFrameworkLifecycleEvent[] array2 = array;
				foreach (IFrameworkLifecycleEvent frameworkLifecycleEvent in array2)
				{
					SafeNotify(observer, frameworkLifecycleEvent, frameworkLifecycleEvent.GetType().Name);
				}
				return lifecycleSubscriptionHolder.Subscription;
			}
			object value = null;
			LifecycleTopic<TEvent> topic = GetLifecycleTopic<TEvent>();
			FrameworkLifecycleSubscription subscription = null;
			using (SyncRoot.EnterScope())
			{
				subscription = new FrameworkLifecycleSubscription(delegate
				{
					using (SyncRoot.EnterScope())
					{
						topic.Remove(Wrapped);
					}
				});
				topic.Add(Wrapped);
				if (replayCurrentState)
				{
					ReplayableLifecycleEvents.TryGetValue(LifecycleEventTypeCache<TEvent>.EventType, out value);
				}
			}
			if (replayCurrentState && value is TEvent evt)
			{
				SafeNotify(Wrapped, evt, LifecycleEventTypeCache<TEvent>.EventName);
			}
			return subscription;
			void Wrapped(TEvent arg)
			{
				try
				{
					handler(arg, subscription);
				}
				catch (Exception ex)
				{
					Logger.Warn("[Lifecycle] Observer callback failed in " + LifecycleEventTypeCache<TEvent>.EventName + ": " + ex.Message, 1);
					DiagnosticsTelemetryCollector.CaptureExceptionForAuthorizedApplicants(ex, "ritsulib_lifecycle_subscription");
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Initializes shared framework services, registers and applies required patches, and publishes lifecycle events.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         初始化共享框架服务，注册并应用必需补丁，然后发布生命周期事件。
		///     </para>
		/// </summary>
		public static void Initialize()
		{
			using (SyncRoot.EnterScope())
			{
				if (IsInitialized)
				{
					Logger.Debug("Framework already initialized, skipping duplicate initialization.", 1);
					return;
				}
				LinuxHarmonyNativePreloader.EnsureLoaded(delegate(string message)
				{
					Logger.Info(message, 1);
				}, delegate(string message)
				{
					Logger.Warn(message, 1);
				});
				StartupModListLogger.Initialize();
				Logger.Info("Framework ID: com.ritsukage.sts2-RitsuLib", 1);
				Logger.Info("Framework Name: RitsuLib", 1);
				Logger.Info(BuildVersionLogText(), 1);
				Logger.Info("Initializing shared framework...", 1);
				RitsuLibStartupAudit.Measure("harmonyPatchAllTypeLoadGuard", delegate
				{
					HarmonyPatchAllTypeLoadGuard.Install(delegate(string message)
					{
						Logger.Warn(message, 1);
					});
				});
				RitsuLibStartupAudit.Measure("harmonyInitSetterCompat", HarmonyInitSetterCompat.Install);
				RitsuLibStartupAudit.Measure("settingsStore", RitsuLibSettingsStore.Initialize);
				RitsuLibStartupAudit.Measure("legacyGeneratedDataCleanup", RitsuLibLegacyGeneratedDataCleanup.RunOnce);
				RitsuLibStartupAudit.Measure("searchExpansion", RitsuSearchService.Initialize);
				RitsuLibStartupAudit.Measure("debugLogViewer", delegate
				{
					RitsuDebugLogPipeline.Initialize(RitsuLibSettingsStore.GetDebugLogViewerOptions());
				});
				RitsuLibStartupAudit.Measure("modSettingsBootstrap", RitsuLibModSettingsBootstrap.Initialize);
				RitsuLibStartupAudit.Measure("telemetryBootstrap", RitsuLibTelemetryBootstrap.Initialize);
				RitsuLibStartupAudit.Measure("frameworkBuiltIns", delegate
				{
					RitsuLibStartupAudit.Measure("mobileSteamRuntime", RitsuLibMobileSteamRuntime.LogSuppressedSteamFeaturesAtStartup);
					RitsuLibStartupAudit.Measure("imageResourceLoader", RitsuLibEmbeddedPngResourceLoader.EnsureRegistered);
					RitsuLibStartupAudit.Measure("godotNodeFactories", RitsuGodotNodeFactoryBootstrap.EnsureRegistered);
					RitsuLibStartupAudit.Measure("modTypeDiscoveryBuiltIns", ModTypeDiscoveryHub.EnsureBuiltInContributorsRegistered);
					RitsuLibStartupAudit.Measure("secondaryResourceLocalization", SecondaryResourceLocalizationBootstrap.Initialize);
					RitsuLibStartupAudit.Measure("secondaryResourceCloneBridge", SecondaryResourceCloneBridge.Initialize);
				});
				PublishLifecycleEvent(new FrameworkInitializingEvent("com.ritsukage.sts2-RitsuLib", "0.5.18", DateTimeOffset.UtcNow), "FrameworkInitializingEvent");
				try
				{
					if (!_frameworkPatchesApplied)
					{
						FrameworkPatchersByArea.Clear();
						RitsuLibStartupAudit.Measure("registerPatches", delegate
						{
							RegisterLifecyclePatches();
							RegisterSettingsUiPatches();
							RegisterContentAssetPatches();
							RegisterCharacterAssetPatches();
							RegisterContentRegistryPatches();
							RegisterPersistencePatches();
							RegisterUnlockPatches();
						});
						if (!RitsuLibStartupAudit.Measure("patchAll", (Func<bool>)PatchAllRequired))
						{
							Logger.ErrorNoTrace("Framework initialization failed: critical framework patches failed.");
							IsActive = false;
							RitsuLibStartupAudit.LogReport("initialization (failed)");
							return;
						}
						_frameworkPatchesApplied = true;
					}
					RitsuLibStartupAudit.Measure("runtimeServices", delegate
					{
						EnsureFrameworkInteropBootstrapRegistered();
						ModCardPilePersistence.Initialize();
						SecondaryResourcePersistence.Initialize();
						RuntimeHotkeyService.Initialize();
						RitsuOverlayHostService.Initialize();
						RitsuToastService.Initialize();
						RitsuCanvasTextureFilterService.Initialize();
						RuntimeDetourCompatibilityScanner.Initialize();
						SteamWorkshopUpdateCoordinator.Initialize();
						RitsuLibUpdateCheckService.Initialize();
					});
					SubscribeLifecycleOnce<MainMenuReadyEvent>(delegate
					{
						//IL_002a: Unknown result type (might be due to invalid IL or missing references)
						//IL_002f: Unknown result type (might be due to invalid IL or missing references)
						RitsuLibStartupAudit.LogReport("launch to main menu");
						ModTypeDiscoveryHub.LogAutoRegistrationModIdMismatchSummary();
						Callable val = Callable.From((Action)PrewarmModSettingsMirrorsForMainMenu);
						((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
						HarmonyPatchDumpCoordinator.TryAutoDumpOnFirstMainMenu();
						SelfCheckBundleCoordinator.TryAutoRunOnFirstMainMenu();
					});
					IsInitialized = true;
					IsActive = true;
					PublishLifecycleEvent(new FrameworkInitializedEvent("com.ritsukage.sts2-RitsuLib", IsActive, DateTimeOffset.UtcNow), "FrameworkInitializedEvent");
					Logger.Info("Shared framework initialization complete.", 1);
				}
				catch (Exception ex)
				{
					Logger.ErrorNoTrace("Framework initialization failed: " + ex.Message);
					Logger.ErrorNoTrace("Stack trace: " + ex.StackTrace);
					DiagnosticsTelemetryCollector.CaptureExceptionForAuthorizedApplicants(ex, "ritsulib_framework_initialize");
					IsActive = false;
				}
			}
		}

		internal static string BuildVersionLogText()
		{
			string compatBranchLabel = GetCompatBranchLabel();
			string value = (RitsuLibBuildInfo.IsDevBuild ? (" [dev build: " + RitsuLibBuildInfo.InformationalVersion + "]") : "");
			return $"Version: {"0.5.18"}{value} [compat branch: {compatBranchLabel}]";
		}

		private static void EnsureFrameworkInteropBootstrapRegistered()
		{
			if (!_frameworkInteropBootstrapRegistered)
			{
				SubscribeLifecycle((Action<DeferredInitializationCompletedEvent>)delegate
				{
					ConfirmExternalFrameworkInterop();
				}, true);
				_frameworkInteropBootstrapRegistered = true;
			}
		}

		private static void ConfirmExternalFrameworkInterop()
		{
			ExternalFrameworkRegistry.RefreshKnownFrameworkPresence("deferred initialization completed");
			BaseLibHealthBarForecastBridge.TryRegister();
			BaseLibVisualGraftBridge.TryRegister();
			BaseLibMaxHandSizeBridge.TryInitialize();
			MaxHandSizePatchInstaller.EnsurePatched();
		}

		private static void PrewarmModSettingsMirrorsForMainMenu()
		{
			try
			{
				RitsuLibModSettingsBootstrap.EnsureFrameworkPagesRegistered();
				int value = ModSettingsMirrorRegistrarBootstrap.PrewarmMirroredPagesForMainMenu();
				RitsuLibModSettingsBootstrap.RefreshDynamicPages();
				Logger.Debug($"Mod settings mirror prewarm complete. Added {value} mirrored page(s).", 1);
			}
			catch (Exception ex)
			{
				Logger.Warn("Mod settings mirror prewarm failed: " + ex.Message, 1);
			}
		}

		internal static string GetCompatBranchLabel()
		{
			return RitsuLibBuildInfo.Sts2ApiCompat;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Ensures profile-bound services (<c>ProfileManager</c>, profile-scoped <c>ModDataStore</c>) are initialized
		///         once.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         确保与配置档绑定的服务（<c>ProfileManager</c>、配置档作用域的 <c>ModDataStore</c>）只初始化一次。
		///     </para>
		/// </summary>
		public static void EnsureProfileServicesInitialized()
		{
			using (SyncRoot.EnterScope())
			{
				if (!_profileServicesInitialized)
				{
					PublishLifecycleEvent(new ProfileServicesInitializingEvent(DateTimeOffset.UtcNow), "ProfileServicesInitializingEvent");
					ModDataRuntimeInterop.EnsureProfileSwitchSyncHook();
					ProfileManager.Instance.Initialize();
					ModDataStore.InitializeAllProfileScoped();
					ModDataRuntimeInterop.PushLoadedDataToAllProviders();
					_profileServicesInitialized = true;
					PublishLifecycleEvent(new ProfileServicesInitializedEvent(ProfileManager.Instance.CurrentProfileId, DateTimeOffset.UtcNow), "ProfileServicesInitializedEvent");
					Logger.Debug("Profile-scoped framework services initialized.", 1);
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Begins a registration scope for the specified mod's <c>ModDataStore</c> entries.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为指定模组的 <c>ModDataStore</c> 条目开启注册作用域。
		///     </para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">
		///         Owning mod identifier.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         所属模组标识符。
		///     </para>
		/// </param>
		/// <param name="initializeProfileIfReady">
		///     <para xml:lang="en">
		///         When true, initializes profile services if the profile is already ready.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <see langword="true" /> 时，如果档案已经就绪，则初始化档案服务。
		///     </para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         Disposing ends the registration scope.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         释放返回值会结束该注册作用域。
		///     </para>
		/// </returns>
		public static IDisposable BeginModDataRegistration(string modId, bool initializeProfileIfReady = true)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			return ModDataStore.For(modId).BeginRegistrationScope(initializeProfileIfReady);
		}

