		internal static void EnqueueDeferredContentPack(string modId, Action<ModContentPackContext> apply, string? description = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentNullException.ThrowIfNull(apply, "apply");
			using (DeferredContentPackSync.EnterScope())
			{
				if (_deferredContentPacksFlushed)
				{
					throw new InvalidOperationException("Content pack registration for mod '" + modId + "' is already closed for this run.");
				}
				DeferredContentPackRegistrations.Add(new DeferredContentPackRegistration(modId, apply, description));
			}
		}

		internal static void FlushDeferredContentPacks()
		{
			List<DeferredContentPackRegistration> list;
			using (DeferredContentPackSync.EnterScope())
			{
				if (_deferredContentPacksFlushed)
				{
					return;
				}
				_deferredContentPacksFlushed = true;
				list = DeferredContentPackRegistrations.ToList();
				DeferredContentPackRegistrations.Clear();
			}
			if (list.Count == 0)
			{
				return;
			}
			list.Sort((DeferredContentPackRegistration x, DeferredContentPackRegistration y) => StringComparer.OrdinalIgnoreCase.Compare(x.ModId, y.ModId));
			foreach (DeferredContentPackRegistration item in list)
			{
				ModContentPackContext obj = new ModContentPackContext(item.ModId, GetContentRegistry(item.ModId), GetKeywordRegistry(item.ModId), GetTimelineRegistry(item.ModId), GetUnlockRegistry(item.ModId), GetCardTagRegistry(item.ModId), GetCardPileRegistry(item.ModId));
				try
				{
					item.Apply(obj);
				}
				catch (Exception ex)
				{
					RegistrationFreezeDiagnostics.RecordFailure("ContentPack", item.ModId, item.Description ?? "deferred content pack", ex);
					Logger.ErrorNoTrace($"[ContentPack] Failed to apply deferred content pack for mod '{item.ModId}'{(string.IsNullOrWhiteSpace(item.Description) ? "" : (" (" + item.Description + ")"))}: {ex.Message}");
				}
			}
			Logger.Info($"[ContentPack] Flushed {list.Count} deferred content pack(s).", 1);
		}

