		/// <summary>
		///     <para xml:lang="en">
		///         Creates a <c>MegaCrit.Sts2.Core.Logging.Logger</c> for <paramref name="modId" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="modId" /> 创建 <c>MegaCrit.Sts2.Core.Logging.Logger</c>。
		///     </para>
		/// </summary>
		public static Logger CreateLogger(string modId, LogType logType = (LogType)0)
		{
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0013: Expected O, but got Unknown
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			return new Logger(modId, logType);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Writes an error message to Godot's standard-error output without automatically appending a stack trace.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将错误消息写入 Godot 的标准错误输出，且不会自动附加堆栈跟踪。
		///     </para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         Include an explicit stack trace in <paramref name="text" /> if one is needed.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         如需堆栈信息，请由调用方将堆栈内容放入 <paramref name="text" />。
		///     </para>
		/// </remarks>
		public static void ErrorNoTrace(this Logger logger, string text)
		{
			ArgumentNullException.ThrowIfNull(logger, "logger");
			if (logger.WillLog((LogLevel)5))
			{
				string text2 = ((logger.Context != null) ? ("[" + logger.Context + "] " + text) : text);
				GD.PrintErr("[ERROR] " + text2);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a <see cref="T:STS2RitsuLib.Patching.Core.ModPatcher" /> with a dedicated logger for the owning mod.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用所属模组的专用日志记录器创建 <see cref="T:STS2RitsuLib.Patching.Core.ModPatcher" />。
		///     </para>
		/// </summary>
		public static ModPatcher CreatePatcher(string ownerModId, string patcherName, string? patcherLabel = null, LogType logType = (LogType)0)
		{
			//IL_0017: Unknown result type (might be due to invalid IL or missing references)
			ArgumentException.ThrowIfNullOrWhiteSpace(ownerModId, "ownerModId");
			ArgumentException.ThrowIfNullOrWhiteSpace(patcherName, "patcherName");
			Logger logger = CreateLogger(ownerModId, logType);
			return new ModPatcher(ownerModId + "." + patcherName, logger, patcherLabel ?? patcherName);
		}

