		/// <summary>
		///     <para xml:lang="en">
		///         Registers C# scripts from <paramref name="assembly" /> with Godot (once per assembly).
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将 <paramref name="assembly" /> 中的 C# 脚本注册到 Godot（每个程序集一次）。
		///     </para>
		/// </summary>
		public static void EnsureGodotScriptsRegistered(Assembly assembly, Logger? logger = null)
		{
			ArgumentNullException.ThrowIfNull(assembly, "assembly");
			string text = assembly.FullName ?? assembly.GetName().Name ?? assembly.ToString();
			using (SyncRoot.EnterScope())
			{
				if (RegisteredScriptAssemblies.Contains(text) || !RegisteringScriptAssemblies.Add(text))
				{
					return;
				}
			}
			try
			{
				Type type = typeof(GodotObject).Assembly.GetType("Godot.Bridge.ScriptManagerBridge");
				MethodInfo methodInfo = type?.GetMethod("LookupScriptsInAssembly", BindingFlags.Static | BindingFlags.Public, null, new Type[1] { typeof(Assembly) }, null);
				if (type == null || methodInfo == null)
				{
					if (logger != null)
					{
						logger.Warn("Godot script registration bridge not found for assembly " + text + ".", 1);
					}
					return;
				}
				if (AreGodotScriptPathsAlreadyRegistered(assembly, type, logger))
				{
					using (SyncRoot.EnterScope())
					{
						RegisteredScriptAssemblies.Add(text);
					}
					if (logger != null)
					{
						logger.Debug("Godot C# scripts already registered for assembly: " + text, 1);
					}
					return;
				}
				methodInfo.CreateDelegate<Action<Assembly>>()(assembly);
				using (SyncRoot.EnterScope())
				{
					RegisteredScriptAssemblies.Add(text);
				}
				if (logger != null)
				{
					logger.Debug("Registered Godot C# scripts for assembly: " + text, 1);
				}
			}
			catch (Exception ex)
			{
				logger?.ErrorNoTrace("Failed to register Godot C# scripts for assembly " + text + ": " + ex.Message);
				logger?.ErrorNoTrace("Stack trace: " + ex.StackTrace);
				DiagnosticsTelemetryCollector.CaptureExceptionForAuthorizedApplicants(ex, "ritsulib_godot_script_registration");
			}
			finally
			{
				using (SyncRoot.EnterScope())
				{
					RegisteringScriptAssemblies.Remove(text);
				}
			}
		}

		private static bool AreGodotScriptPathsAlreadyRegistered(Assembly assembly, Type bridgeType, Logger? logger)
		{
			try
			{
				string[] array = EnumerateGodotScriptPaths(assembly).ToArray();
				if (array.Length == 0)
				{
					return true;
				}
				object pathTypeBiMap = bridgeType.GetField("_pathTypeBiMap", BindingFlags.Static | BindingFlags.NonPublic)?.GetValue(null);
				if (pathTypeBiMap == null)
				{
					return false;
				}
				MethodInfo tryGetScriptType = pathTypeBiMap.GetType().GetMethod("TryGetScriptType", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, new Type[2]
				{
					typeof(string),
					typeof(Type).MakeByRefType()
				}, null);
				if (tryGetScriptType == null)
				{
					return false;
				}
				object obj = bridgeType.GetField("_scriptTypeBiMap", BindingFlags.Static | BindingFlags.NonPublic)?.GetValue(null);
				ReaderWriterLockSlim readerWriterLockSlim = obj?.GetType().GetField("ReadWriteLock", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(obj) as ReaderWriterLockSlim;
				readerWriterLockSlim?.EnterReadLock();
				try
				{
					if (array.Select((string scriptPath) => new object[2] { scriptPath, null }).Any(delegate(object[] args)
					{
						object obj2 = tryGetScriptType.Invoke(pathTypeBiMap, args);
						return !(obj2 is bool) || !(bool)obj2;
					}))
					{
						return false;
					}
				}
				finally
				{
					readerWriterLockSlim?.ExitReadLock();
				}
				return true;
			}
			catch (Exception ex)
			{
				if (logger != null)
				{
					logger.Debug("Could not inspect Godot script registration cache: " + ex.Message, 1);
				}
				return false;
			}
		}

		private static IEnumerable<string> EnumerateGodotScriptPaths(Assembly assembly)
		{
			AssemblyHasScriptsAttribute val = assembly.GetCustomAttributes(inherit: false).OfType<AssemblyHasScriptsAttribute>().FirstOrDefault();
			if (val == null)
			{
				yield break;
			}
			IEnumerable<Type> enumerable2;
			if (!val.RequiresLookup)
			{
				IEnumerable<Type> enumerable = val.ScriptTypes ?? Array.Empty<Type>();
				enumerable2 = enumerable;
			}
			else
			{
				enumerable2 = from type in assembly.GetTypes()
					where !type.IsNested && typeof(GodotObject).IsAssignableFrom(type)
					select type;
			}
			IEnumerable<Type> enumerable3 = enumerable2;
			foreach (Type item in enumerable3)
			{
				ScriptPathAttribute? obj = item.GetCustomAttributes(inherit: false).OfType<ScriptPathAttribute>().FirstOrDefault();
				string text = ((obj != null) ? obj.Path : null);
				if (!string.IsNullOrWhiteSpace(text))
				{
					yield return text;
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Applies all patches on <paramref name="patcher" />; on failure logs, invokes <paramref name="disableMod" />,
		///         and
		///         returns false.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         应用 <paramref name="patcher" /> 上的所有补丁；失败时记录日志，调用 <paramref name="disableMod" />，并
		///         返回 false。
		///     </para>
		/// </summary>
		public static bool ApplyRequiredPatcher(ModPatcher patcher, Action disableMod, string? failureMessage = null)
		{
			ArgumentNullException.ThrowIfNull(patcher, "patcher");
			ArgumentNullException.ThrowIfNull(disableMod, "disableMod");
			if (patcher.PatchAll())
			{
				return true;
			}
			patcher.Logger.ErrorNoTrace(failureMessage ?? ("Required patcher '" + patcher.PatcherName + "' failed. The mod will be disabled."));
			disableMod();
			return false;
		}

		internal static void PublishLifecycleEvent<TEvent>(TEvent evt, string phase) where TEvent : IFrameworkLifecycleEvent
		{
			Action<TEvent>[] array = Array.Empty<Action<TEvent>>();
			ILifecycleObserver[] lifecycleObservers;
			using (SyncRoot.EnterScope())
			{
				if (LifecycleEventTypeCache<TEvent>.InvalidatesProfileDataReady)
				{
					ReplayableLifecycleEvents.Remove(typeof(ProfileDataReadyEvent));
				}
				if (LifecycleEventTypeCache<TEvent>.IsReplayable)
				{
					ReplayableLifecycleEvents[LifecycleEventTypeCache<TEvent>.EventType] = evt;
				}
				lifecycleObservers = _lifecycleObservers;
			}
			if (LifecycleEventTypeCache<TEvent>.SupportsTypedDispatch)
			{
				array = GetLifecycleTopic<TEvent>().ReadSnapshot();
			}
			Action<TEvent>[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				SafeNotify(array2[i], evt, phase);
			}
			ILifecycleObserver[] array3 = lifecycleObservers;
			for (int i = 0; i < array3.Length; i++)
			{
				SafeNotify(array3[i], evt, phase);
			}
		}

		private static T[] AppendItem<T>(T[] source, T item)
		{
			T[] array = new T[source.Length + 1];
			Array.Copy(source, array, source.Length);
			array[^1] = item;
			return array;
		}

		private static T[] RemoveItem<T>(T[] source, T item)
		{
			int num = Array.IndexOf(source, item);
			if (num < 0)
			{
				return source;
			}
			if (source.Length == 1)
			{
				return Array.Empty<T>();
			}
			T[] array = new T[source.Length - 1];
			if (num > 0)
			{
				Array.Copy(source, 0, array, 0, num);
			}
			if (num < source.Length - 1)
			{
				Array.Copy(source, num + 1, array, num, source.Length - num - 1);
			}
			return array;
		}

		private static void SafeNotify<TEvent>(Action<TEvent> handler, TEvent evt, string phase) where TEvent : IFrameworkLifecycleEvent
		{
			try
			{
				handler(evt);
			}
			catch (Exception ex)
			{
				Logger.Warn("[Lifecycle] Observer callback failed in " + phase + ": " + ex.Message, 1);
				DiagnosticsTelemetryCollector.CaptureExceptionForAuthorizedApplicants(ex, "ritsulib_lifecycle_handler");
			}
		}

		private static void SafeNotify<TEvent>(ILifecycleObserver observer, TEvent evt, string phase) where TEvent : IFrameworkLifecycleEvent
		{
			try
			{
				observer.OnEvent(evt);
			}
			catch (Exception ex)
			{
				Logger.Warn("[Lifecycle] Observer callback failed in " + phase + ": " + ex.Message, 1);
				DiagnosticsTelemetryCollector.CaptureExceptionForAuthorizedApplicants(ex, "ritsulib_lifecycle_observer");
			}
		}

		private static LifecycleTopic<TEvent> GetLifecycleTopic<TEvent>() where TEvent : IFrameworkLifecycleEvent
		{
			return (LifecycleTopic<TEvent>)LifecycleTopics.GetOrAdd(LifecycleEventTypeCache<TEvent>.EventType, (Type _) => new LifecycleTopic<TEvent>());
		}

		internal static FrameworkRuntimeSnapshot CaptureRuntimeSnapshot()
		{
			using (SyncRoot.EnterScope())
			{
				FrameworkPatcherSnapshot[] patcherAreas = (from area in Enum.GetValues<FrameworkPatcherArea>()
					select (!FrameworkPatchersByArea.TryGetValue(area, out ModPatcher value)) ? new FrameworkPatcherSnapshot(area.ToString(), IsRegistered: false, IsApplied: false, 0, 0, 0) : new FrameworkPatcherSnapshot(area.ToString(), IsRegistered: true, value.IsApplied, value.RegisteredPatchCount, value.RegisteredDynamicPatchCount, value.AppliedPatchCount)).ToArray();
				return new FrameworkRuntimeSnapshot(IsInitialized, IsActive, _profileServicesInitialized, HasRegisteredModSettings, _lifecycleObservers.Length, RegisteredScriptAssemblies.Count, patcherAreas);
			}
		}

		internal static FrameworkPatchBindingSnapshot[] CapturePatchBindingSnapshot()
		{
			using (SyncRoot.EnterScope())
			{
				return Enum.GetValues<FrameworkPatcherArea>().SelectMany((FrameworkPatcherArea area) => (!FrameworkPatchersByArea.TryGetValue(area, out ModPatcher patcher)) ? Array.Empty<FrameworkPatchBindingSnapshot>() : patcher.RegisteredPatches.Select((ModPatchInfo patchInfo) => CreatePatchBindingSnapshot(area, patcher, patchInfo)).ToArray()).ToArray();
			}
		}

		private static FrameworkPatchBindingSnapshot CreatePatchBindingSnapshot(FrameworkPatcherArea area, ModPatcher patcher, ModPatchInfo patchInfo)
		{
			MethodInfo originalMethod = ResolveOriginalMethod(patchInfo);
			MethodInfo[] expectedPatchMethods = ResolvePatchMethods(patchInfo.PatchType);
			return new FrameworkPatchBindingSnapshot(area.ToString(), patcher.PatcherId, patchInfo.Id, patchInfo.PatchType.FullName ?? patchInfo.PatchType.Name, patchInfo.IsCritical, originalMethod, expectedPatchMethods);
		}

		private static MethodInfo? ResolveOriginalMethod(ModPatchInfo patchInfo)
		{
			if (patchInfo.ParameterTypes != null)
			{
				return patchInfo.TargetType.GetMethod(patchInfo.MethodName, BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, null, patchInfo.ParameterTypes, null);
			}
			try
			{
				return patchInfo.TargetType.GetMethod(patchInfo.MethodName, BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			}
			catch (AmbiguousMatchException)
			{
				return null;
			}
		}

		private static MethodInfo[] ResolvePatchMethods(Type patchType)
		{
			List<MethodInfo> list = new List<MethodInfo>();
			list.AddRange(ResolvePatchMethod(patchType, "Prefix"));
			list.AddRange(ResolvePatchMethod(patchType, "Postfix"));
			list.AddRange(ResolvePatchMethod(patchType, "Transpiler"));
			list.AddRange(ResolvePatchMethod(patchType, "Finalizer"));
			return list.ToArray();
		}

		private static IEnumerable<MethodInfo> ResolvePatchMethod(Type patchType, string methodName)
		{
			MethodInfo method = patchType.GetMethod(methodName, BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			if (!(method == null))
			{
				return new <>z__ReadOnlySingleElementList<MethodInfo>(method);
			}
			return Array.Empty<MethodInfo>();
		}

