		internal static ModPatcher GetFrameworkPatcher(FrameworkPatcherArea area)
		{
			using (SyncRoot.EnterScope())
			{
				if (!FrameworkPatchersByArea.TryGetValue(area, out ModPatcher value))
				{
					throw new InvalidOperationException($"Framework patcher for area '{area}' is not available yet.");
				}
				return value;
			}
		}

		private static bool PatchAllRequired()
		{
			FrameworkPatcherArea[] values = Enum.GetValues<FrameworkPatcherArea>();
			foreach (FrameworkPatcherArea frameworkPatcherArea in values)
			{
				if (!FrameworkPatchersByArea.TryGetValue(frameworkPatcherArea, out ModPatcher value))
				{
					throw new InvalidOperationException($"Framework patcher for area '{frameworkPatcherArea}' was not initialized.");
				}
				if (!RitsuLibStartupAudit.Measure($"patchAll.{frameworkPatcherArea}({value.RegisteredPatchCount})", (Func<bool>)value.PatchAll))
				{
					return false;
				}
			}
			return RitsuLibStartupAudit.Measure("patchAll.messageTailBus", () => RitsuNetMessageBusTailPatches.ApplySerializePatches(GetFrameworkPatcher(FrameworkPatcherArea.Core)));
		}

		private static void RegisterFrameworkPatcher(FrameworkPatcherArea area, ModPatcher patcher)
		{
			if (!FrameworkPatchersByArea.TryAdd(area, patcher))
			{
				throw new InvalidOperationException($"Duplicate framework patcher registration for area '{area}'.");
			}
		}

		private static void RegisterMessageTailPatches(ModPatcher patcher)
		{
			JoinDiagnosticsPayloadCodec.EnsureRegistered();
			StateDivergenceSupplementPayloadCodec.EnsureRegistered();
			RunSavedDataLobbyBeginRunMessageTail.EnsureRegistered();
			RitsuNetMessageBusTailPatches.Register<InitialGameInfoMessage>("join_failure_diagnostics_initial_game_info_bus_serialize", "Append registered RitsuLib join diagnostics at the non-inlined message-bus boundary", (Action?)null, false);
			RitsuNetMessageBusTailPatches.Register<StateDivergenceMessage>("state_divergence_supplement_bus_serialize", "Append registered RitsuLib divergence diagnostics at the non-inlined message-bus boundary", (Action?)null, false);
			RitsuNetMessageBusTailPatches.Register<LobbyBeginRunMessage>("ritsulib_run_saved_data_lobby_begin_run_bus_serialize", "Append registered new-run data at the non-inlined message-bus boundary", (Action?)delegate
			{
				RunSavedDataLobbyBeginRunMessageState.SetPendingPayload(null);
			}, false);
			patcher.RegisterPatch<RitsuNetMessageBusTailDeserializePatch>();
		}

