		/// </summary>
		public static ModUpdateCheckOptions SkipModUpdateCheckWhenLoadedFromSteamWorkshop(ModUpdateCheckOptions options, Assembly installSourceAssembly, ulong workshopItemId)
		{
			ArgumentNullException.ThrowIfNull(options, "options");
			ArgumentNullException.ThrowIfNull(installSourceAssembly, "installSourceAssembly");
			ArgumentOutOfRangeException.ThrowIfZero(workshopItemId, "workshopItemId");
			return options with
			{
				SkipWhenLoadedFromSteamWorkshop = true,
				InstallSourceAssembly = installSourceAssembly,
				InstallSourcePath = null,
				SteamWorkshopItemId = workshopItemId
			};
		}

