		///     <para xml:lang="en">
		///         Returns update-check options that skip the external manifest check when the specified install path is
		///         under Steam Workshop content.
		///     </para>
		///     <para xml:lang="zh-CN">返回更新检查选项；指定安装路径位于 Steam Workshop 内容下时会跳过外部清单检查。</para>
		/// </summary>
		public static ModUpdateCheckOptions SkipModUpdateCheckWhenLoadedFromSteamWorkshop(ModUpdateCheckOptions options, string installSourcePath, ulong workshopItemId)
		{
			ArgumentNullException.ThrowIfNull(options, "options");
			ArgumentException.ThrowIfNullOrWhiteSpace(installSourcePath, "installSourcePath");
			ArgumentOutOfRangeException.ThrowIfZero(workshopItemId, "workshopItemId");
			return options with
			{
				SkipWhenLoadedFromSteamWorkshop = true,
				InstallSourcePath = installSourcePath,
				InstallSourceAssembly = null,
				SteamWorkshopItemId = workshopItemId
			};
		}

