	internal static class RitsuLibEmbeddedPngAssets
	{
		private static readonly Dictionary<string, RitsuLibEmbeddedPngAsset> AssetsByPath = new Dictionary<string, RitsuLibEmbeddedPngAsset>(StringComparer.Ordinal);

		internal static readonly RitsuLibEmbeddedPngAsset CardArtPlaceholder = Add("res://STS2-RitsuLib/card_art_placeholder.png", () => "STS2RitsuLib.Assets.card_art_placeholder.png");

		internal static readonly RitsuLibEmbeddedPngAsset ModImage = Add("res://STS2-RitsuLib/mod_image.png", () => (!RitsuLibEasterEggPolicy.IsJuneTwentySeventhInBeijing()) ? "STS2RitsuLib.Assets.mod_image.png" : "STS2RitsuLib.Assets.mod_image_ex.png");

		internal static bool Contains(string resourcePath)
		{
			return AssetsByPath.ContainsKey(resourcePath);
		}

		internal static bool TryGet(string resourcePath, [NotNullWhen(true)] out RitsuLibEmbeddedPngAsset? asset)
		{
			return AssetsByPath.TryGetValue(resourcePath, out asset);
		}

		private static RitsuLibEmbeddedPngAsset Add(string resourcePath, Func<string> embeddedResourceNameResolver)
		{
			RitsuLibEmbeddedPngAsset ritsuLibEmbeddedPngAsset = new RitsuLibEmbeddedPngAsset(resourcePath, embeddedResourceNameResolver);
			AssetsByPath.Add(resourcePath, ritsuLibEmbeddedPngAsset);
			return ritsuLibEmbeddedPngAsset;
		}
	}
	internal sealed record RitsuLibEmbeddedPngAsset(string ResourcePath, Func<string> EmbeddedResourceNameResolver)
	{
		internal string ResolveEmbeddedResourceName()
		{
			return EmbeddedResourceNameResolver();
		}
	}
