		internal static void EnsureRegistered()
		{
			using (RegistrationLock.EnterScope())
			{
				if (_registeredLoader == null)
				{
					RitsuLibEmbeddedPngResourceLoader ritsuLibEmbeddedPngResourceLoader = new RitsuLibEmbeddedPngResourceLoader();
					ResourceLoader.AddResourceFormatLoader((ResourceFormatLoader)(object)ritsuLibEmbeddedPngResourceLoader, true);
					_registeredLoader = ritsuLibEmbeddedPngResourceLoader;
				}
