			//IL_0052: Unknown result type (might be due to invalid IL or missing references)
			//IL_0053: Unknown result type (might be due to invalid IL or missing references)
			//IL_0068: Unknown result type (might be due to invalid IL or missing references)
			//IL_006f: Expected O, but got Unknown
			//IL_0078: Unknown result type (might be due to invalid IL or missing references)
			//IL_007d: Unknown result type (might be due to invalid IL or missing references)
			//IL_007f: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c6: Unknown result type (might be due to invalid IL or missing references)
			//IL_00dc: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e2: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e4: Unknown result type (might be due to invalid IL or missing references)
			//IL_008a: Unknown result type (might be due to invalid IL or missing references)
			//IL_008f: Unknown result type (might be due to invalid IL or missing references)
			if (!RitsuLibEmbeddedPngAssets.TryGet(path, out RitsuLibEmbeddedPngAsset asset))
			{
				return default(Variant);
			}
			string text = asset.ResolveEmbeddedResourceName();
			try
			{
				using Stream stream = typeof(RitsuLibEmbeddedPngResourceLoader).Assembly.GetManifestResourceStream(text);
				if (stream == null)
				{
					RitsuLibFramework.Logger.Warn("[EmbeddedPng] Resource not found: " + text, 1);
					return default(Variant);
				}
				using MemoryStream memoryStream = new MemoryStream();
				stream.CopyTo(memoryStream);
