				}
				RitsuLibFramework.Logger.Warn($"[EmbeddedPng] Failed to decode '{text}': {val2}", 1);
				return default(Variant);
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[EmbeddedPng] Failed to load '" + text + "': " + ex.Message, 1);
