	/// <summary>
	///     <para xml:lang="en">Provides helpers for appending hover tips to active game UI controls.</para>
	///     <para xml:lang="zh-CN">提供用于向活动游戏界面控件追加悬停提示的辅助方法。</para>
	/// </summary>
	public static class HoverTipHelper
	{
		private const float HoverTipSpacing = 5f;

		private const float HoverTipWidth = 360f;

		/// <summary>
		///     <para xml:lang="en">Appends a text hover tip to <paramref name="owner" />'s active hover-tip set.</para>
		///     <para xml:lang="zh-CN">向 <paramref name="owner" /> 的活动悬停提示集合追加文本悬停提示。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="false" /> when no hover-tip set is bound to the control or the set has no
		///         text-tip container.
		///     </para>
		///     <para xml:lang="zh-CN">该控件未绑定悬停提示集合，或集合没有文本提示容器时为 <see langword="false" />。</para>
		/// </returns>
		public static bool AddTipToOwner(Control owner, string title, string description)
		{
			if (NHoverTipSet._activeHoverTips.TryGetValue(owner, out var value))
			{
				return AddTipToSet(value, owner, title, description);
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Appends card-preview hover tips for <paramref name="cards" /> to <paramref name="owner" />.</para>
		///     <para xml:lang="zh-CN">向 <paramref name="owner" /> 追加 <paramref name="cards" /> 的卡牌预览悬停提示。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en"><see langword="false" /> when no hover-tip set is bound or no tip was added.</para>
		///     <para xml:lang="zh-CN">未绑定悬停提示集合或未追加任何提示时为 <see langword="false" />。</para>
		/// </returns>
		public static bool AddCardTipsToOwner(Control owner, IEnumerable<CardModel> cards)
		{
			if (NHoverTipSet._activeHoverTips.TryGetValue(owner, out var value))
			{
				return AddCardTipsToSet(value, owner, cards);
			}
			return false;
		}

		private static bool AddTipToSet(NHoverTipSet hoverTipSet, Control owner, string title, string description)
		{
			//IL_0093: Unknown result type (might be due to invalid IL or missing references)
			//IL_0098: Unknown result type (might be due to invalid IL or missing references)
			//IL_009c: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a8: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d4: Unknown result type (might be due to invalid IL or missing references)
			//IL_00df: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f0: Unknown result type (might be due to invalid IL or missing references)
			VFlowContainer textHoverTipContainer = hoverTipSet._textHoverTipContainer;
			if (textHoverTipContainer == null)
			{
				return false;
			}
			Control val = PreloadManager.Cache.GetScene("res://scenes/ui/hover_tip.tscn").Instantiate<Control>((GenEditState)0);
			GodotTreeExtensions.AddChildSafely((Node)(object)textHoverTipContainer, (Node)(object)val);
			MegaLabel node = ((Node)val).GetNode<MegaLabel>(NodePath.op_Implicit("%Title"));
			if (string.IsNullOrEmpty(title))
			{
				((CanvasItem)node).Visible = false;
			}
			else
			{
				node.SetTextAutoSize(title);
			}
			((Node)val).GetNode<MegaRichTextLabel>(NodePath.op_Implicit("%Description")).Text = description;
			((Node)val).GetNode<TextureRect>(NodePath.op_Implicit("%Icon")).Texture = null;
			val.ResetSize();
			if (NGame.Instance == null)
			{
				return true;
			}
			Rect2 viewportRect = ((CanvasItem)NGame.Instance).GetViewportRect();
			float y = ((Rect2)(ref viewportRect)).Size.Y;
			if (((Control)textHoverTipContainer).Size.Y + val.Size.Y + 5f < y - 50f)
			{
				((Control)textHoverTipContainer).Size = new Vector2(360f, ((Control)textHoverTipContainer).Size.Y + val.Size.Y + 5f);
			}
			else
			{
				((FlowContainer)textHoverTipContainer).Alignment = (AlignmentMode)1;
			}
			hoverTipSet.SetAlignment(owner, (HoverTipAlignment)0);
			return true;
		}

		private static bool AddCardTipsToSet(NHoverTipSet hoverTipSet, Control owner, IEnumerable<CardModel> cards)
		{
			//IL_00bd: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c7: Expected O, but got Unknown
			NHoverTipCardContainer cardHoverTipContainer = hoverTipSet._cardHoverTipContainer;
			if (cardHoverTipContainer == null)
			{
				return false;
			}
			HashSet<string> hashSet = new HashSet<string>();
			bool flag = false;
			foreach (CardModel card in cards)
			{
				string item = ((card.CurrentUpgradeLevel <= 0) ? ((object)((AbstractModel)card).Id).ToString() : ((card.MaxUpgradeLevel > 1) ? $"{((AbstractModel)card).Id}+{card.CurrentUpgradeLevel}" : $"{((AbstractModel)card).Id}+"));
				if (hashSet.Add(item))
				{
					cardHoverTipContainer.Add(new CardHoverTip(card));
					flag = true;
				}
			}
			if (!flag)
			{
				return false;
			}
			hoverTipSet.SetAlignment(owner, (HoverTipAlignment)0);
			return true;
		}
	}
