		///     <para xml:lang="zh-CN">仅订阅一次，在活动档案变化时将提供程序快照同步到 <see cref="T:STS2RitsuLib.Data.ModDataStore" />。</para>
		/// </summary>
		public static void EnsureProfileSwitchSyncHook()
		{
			RuntimeModDataInteropSource.EnsureProfileChangedHook();
		}
	}
}
namespace STS2RitsuLib.Utils
{
	/// <summary>
	///     <para xml:lang="en">
	///         Centralizes resource-path existence checks and startup-scoped deduplication of missing-path
	///         diagnostics for mod assets.
	///     </para>
	///     <para xml:lang="zh-CN">集中处理模组资源路径的存在性检查，并在启动阶段对缺失路径诊断去重。</para>
	/// </summary>
	internal static class AssetPathDiagnostics
	{
		private static readonly Lock StartupMissingPathCacheGate = new Lock();

		private static readonly HashSet<string> StartupMissingPathCache = new HashSet<string>();

		private static bool _startupMissingPathCacheEnabled = true;

		private static bool _startupMissingPathCacheShutdownRegistered;

		private static bool _startupMissingPathCacheShutdownRegistering;

		internal static bool Exists(string path, object owner, string memberName)
		{
			string ownerLabel = DescribeOwner(owner);
			string cacheKey = BuildMissingPathCacheKey(ownerLabel, memberName, path);
			if (IsCachedStartupMissingPath(cacheKey))
			{
				return false;
			}
			if (GodotResourcePath.ResourceExists(path))
			{
				return true;
			}
			if (ShouldWarnMissingPath(cacheKey))
			{
				WarnMissingPath(ownerLabel, memberName, path);
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Logs an unresolved, non-empty path supplied by a mod character asset profile, with duplicate
		///         diagnostics suppressed during startup.
		///     </para>
		///     <para xml:lang="zh-CN">记录模组角色资源档案中无法解析的非空路径，并在启动阶段抑制重复诊断。</para>
		/// </summary>
		internal static void WarnModCharacterAssetOverrideMissing(object owner, string memberName, string path)
		{
			string text = DescribeOwner(owner);
			if (ShouldWarnMissingPath(BuildMissingPathCacheKey(text, memberName, path)))
			{
				RitsuLibFramework.Logger.Warn($"[Assets] Mod character asset override path not found for {text}.{memberName}: '{path}'. " + "Falling back to the base game asset.", 1);
			}
		}

		internal static string[] CollectExistingPaths(object owner, params (string? Path, string MemberName)[] candidates)
		{
			List<string> list = new List<string>(candidates.Length);
			for (int i = 0; i < candidates.Length; i++)
			{
				var (text, memberName) = candidates[i];
				if (!string.IsNullOrWhiteSpace(text) && Exists(text, owner, memberName))
				{
					list.Add(text);
				}
			}
			return list.ToArray();
		}

		private static void WarnMissingPath(string ownerLabel, string memberName, string path)
		{
			RitsuLibFramework.Logger.Warn($"[Assets] Missing resource path for {ownerLabel}.{memberName}: '{path}'. Falling back to the base asset.", 1);
		}

		private static bool IsCachedStartupMissingPath(string cacheKey)
		{
			EnsureStartupMissingPathCacheShutdownRegistered();
			using (StartupMissingPathCacheGate.EnterScope())
			{
				return _startupMissingPathCacheEnabled && StartupMissingPathCache.Contains(cacheKey);
			}
		}

		private static bool ShouldWarnMissingPath(string cacheKey)
		{
			EnsureStartupMissingPathCacheShutdownRegistered();
			using (StartupMissingPathCacheGate.EnterScope())
			{
				return !_startupMissingPathCacheEnabled || StartupMissingPathCache.Add(cacheKey);
			}
		}

		private static void EnsureStartupMissingPathCacheShutdownRegistered()
		{
			if (_startupMissingPathCacheShutdownRegistered)
			{
				return;
			}
			using (StartupMissingPathCacheGate.EnterScope())
			{
				if (_startupMissingPathCacheShutdownRegistered || _startupMissingPathCacheShutdownRegistering)
				{
					return;
				}
				_startupMissingPathCacheShutdownRegistering = true;
			}
			try
			{
				RitsuLibFramework.SubscribeLifecycleOnce<MainMenuReadyEvent>(delegate
				{
					DisableStartupMissingPathCache();
				});
				using (StartupMissingPathCacheGate.EnterScope())
				{
					_startupMissingPathCacheShutdownRegistered = true;
				}
			}
			finally
			{
				using (StartupMissingPathCacheGate.EnterScope())
				{
					_startupMissingPathCacheShutdownRegistering = false;
				}
			}
		}

		private static void DisableStartupMissingPathCache()
		{
			using (StartupMissingPathCacheGate.EnterScope())
			{
				_startupMissingPathCacheEnabled = false;
				StartupMissingPathCache.Clear();
			}
		}

		private static string BuildMissingPathCacheKey(string ownerLabel, string memberName, string path)
		{
			return $"{ownerLabel}\n{memberName}\n{path}";
		}

		private static string DescribeOwner(object owner)
		{
			try
			{
				AbstractModel val = (AbstractModel)((owner is AbstractModel) ? owner : null);
				if (val != null && !string.IsNullOrWhiteSpace(val.Id.Entry))
				{
					return owner.GetType().Name + "<" + val.Id.Entry + ">";
				}
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
			}
			return owner.GetType().Name;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Stores mod-attached state on arbitrary reference objects without subclassing or boxing through
	///         object APIs.
	///     </para>
	///     <para xml:lang="zh-CN">在任意引用对象上存储模组附加状态，无需子类化，也无需通过 object API 装箱。</para>
	/// </summary>
	/// <param name="valueFactory">
	///     <para xml:lang="en">Optional per-key factory; when null, lazily created values use <c>default(TValue)</c>.</para>
	///     <para xml:lang="zh-CN">可选的按键工厂；为 null 时，惰性创建的值使用 <c>default(TValue)</c>。</para>
	/// </param>
	public sealed class AttachedState<TKey, TValue>(Func<TKey, TValue>? valueFactory) where TKey : class
	{
		private sealed class Box(TValue value)
		{
			public TValue Value { get; } = value;
		}

		private readonly ConditionalWeakTable<TKey, Box> _table = new ConditionalWeakTable<TKey, Box>();

		private readonly Func<TKey, TValue> _valueFactory = valueFactory ?? ((Func<TKey, TValue>)((TKey _) => default(TValue)));

		/// <summary>
		///     <para xml:lang="en">Gets or sets the attached value for <paramref name="key" />.</para>
		///     <para xml:lang="zh-CN">获取或设置 <paramref name="key" /> 的附加值。</para>
		/// </summary>
		public TValue this[TKey key]
		{
			get
			{
				return GetOrCreate(key);
			}
			set
			{
				Set(key, value);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Creates state storage using an optional parameterless factory for default values.</para>
		///     <para xml:lang="zh-CN">使用可选的无参工厂创建具有默认值的状态存储。</para>
		/// </summary>
		public AttachedState(Func<TValue>? defaultValueFactory = null)
			: this((Func<TKey, TValue>?)((TKey _) => (defaultValueFactory == null) ? default(TValue) : defaultValueFactory()))
		{
		}

		/// <summary>
		///     <para xml:lang="en">Determines whether an entry exists for <paramref name="key" /> without creating one.</para>
		///     <para xml:lang="zh-CN">确定 <paramref name="key" /> 是否存在条目，但不创建条目。</para>
		/// </summary>
		public bool ContainsKey(TKey key)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			Box value;
			return _table.TryGetValue(key, out value);
		}

		/// <summary>
		///     <para xml:lang="en">Adds an entry for <paramref name="key" /> if absent.</para>
		///     <para xml:lang="zh-CN">如果 <paramref name="key" /> 缺少条目，则添加条目。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">True if the entry was added; false if <paramref name="key" /> already had a value.</para>
		///     <para xml:lang="zh-CN">已添加条目时为 true；<paramref name="key" /> 已有值时为 false。</para>
		/// </returns>
		public bool TryAdd(TKey key, TValue value)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			return _table.TryAdd(key, new Box(value));
		}

		/// <summary>
		///     <para xml:lang="en">Adds an entry for <paramref name="key" />.</para>
		///     <para xml:lang="zh-CN">为 <paramref name="key" /> 添加条目。</para>
		/// </summary>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">An entry for <paramref name="key" /> already exists.</para>
		///     <para xml:lang="zh-CN"><paramref name="key" /> 的条目已存在。</para>
		/// </exception>
		public void Add(TKey key, TValue value)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			if (!_table.TryAdd(key, new Box(value)))
			{
				throw new ArgumentException("An item with the same key has already been added.", "key");
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the existing value for <paramref name="key" /> or adds <paramref name="value" /> and
		///         returns it.
		///     </para>
		///     <para xml:lang="zh-CN">返回 <paramref name="key" /> 的现有值；不存在时添加并返回 <paramref name="value" />。</para>
		/// </summary>
		public TValue GetOrAdd(TKey key, TValue value)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			return _table.GetValue(key, (TKey _) => new Box(value)).Value;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the existing value for <paramref name="key" /> or creates one with
		///         <paramref name="valueFactory" />.
		///     </para>
		///     <para xml:lang="zh-CN">返回 <paramref name="key" /> 的现有值；不存在时使用 <paramref name="valueFactory" /> 创建一个。</para>
		/// </summary>
		public TValue GetOrAdd(TKey key, Func<TKey, TValue> valueFactory)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			ArgumentNullException.ThrowIfNull(valueFactory, "valueFactory");
			return _table.GetValue(key, (TKey k) => new Box(valueFactory(k))).Value;
		}

		/// <summary>
		///     <para xml:lang="en">Returns the existing value for <paramref name="key" /> or creates and stores one.</para>
		///     <para xml:lang="zh-CN">返回 <paramref name="key" /> 的现有值；不存在时创建并存储一个。</para>
		/// </summary>
		public TValue GetOrCreate(TKey key)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			return _table.GetValue(key, (TKey k) => new Box(_valueFactory(k))).Value;
		}

		/// <summary>
		///     <para xml:lang="en">Returns the value for <paramref name="key" /> if present; otherwise <c>default(TValue)</c>.</para>
		///     <para xml:lang="zh-CN">存在时返回 <paramref name="key" /> 的值；否则返回 <c>default(TValue)</c>。</para>
		/// </summary>
		public TValue? GetValueOrDefault(TKey key)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			if (!TryGetValue(key, out var value))
			{
				return default(TValue);
			}
			return value;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the value for <paramref name="key" /> if present; otherwise
		///         <paramref name="defaultValue" />.
		///     </para>
		///     <para xml:lang="zh-CN">存在时返回 <paramref name="key" /> 的值；否则返回 <paramref name="defaultValue" />。</para>
		/// </summary>
		public TValue GetValueOrDefault(TKey key, TValue defaultValue)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			if (!TryGetValue(key, out var value))
			{
				return defaultValue;
			}
			return value;
		}

		/// <summary>
		///     <para xml:lang="en">Attempts to read the attached value without creating it.</para>
		///     <para xml:lang="zh-CN">尝试读取附加值，但不创建它。</para>
		/// </summary>
		public bool TryGetValue(TKey key, [MaybeNullWhen(false)] out TValue value)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			if (_table.TryGetValue(key, out Box value2))
			{
				value = value2.Value;
				return true;
			}
			value = default(TValue);
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Stores <paramref name="value" /> for <paramref name="key" />, replacing any existing entry, and
		///         returns the value.
		///     </para>
		///     <para xml:lang="zh-CN">为 <paramref name="key" /> 存储 <paramref name="value" />，替换任何现有条目，并返回该值。</para>
		/// </summary>
		public TValue Set(TKey key, TValue value)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			_table.Remove(key);
			_table.Add(key, new Box(value));
			return value;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Updates the stored value using <paramref name="updater" />, creating the entry first when
		///         absent.
		///     </para>
		///     <para xml:lang="zh-CN">使用 <paramref name="updater" /> 更新已存储值；条目不存在时会先创建。</para>
		/// </summary>
		public TValue Update(TKey key, Func<TValue, TValue> updater)
		{
			ArgumentNullException.ThrowIfNull(updater, "updater");
			TValue value = updater(GetOrCreate(key));
			return Set(key, value);
		}

		/// <summary>
		///     <para xml:lang="en">Removes any value attached to <paramref name="key" />.</para>
		///     <para xml:lang="zh-CN">移除附加到 <paramref name="key" /> 的任何值。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">True if an entry was removed.</para>
		///     <para xml:lang="zh-CN">已移除条目时为 true。</para>
		/// </returns>
		public bool Remove(TKey key)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			TValue value;
			return TryRemove(key, out value);
		}

		/// <summary>
		///     <para xml:lang="en">Removes the value attached to <paramref name="key" /> if present.</para>
		///     <para xml:lang="zh-CN">存在时移除附加到 <paramref name="key" /> 的值。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">True if an entry was removed.</para>
		///     <para xml:lang="zh-CN">已移除条目时为 true。</para>
		/// </returns>
		public bool TryRemove(TKey key, [MaybeNullWhen(false)] out TValue value)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			if (!_table.TryGetValue(key, out Box value2))
			{
				value = default(TValue);
				return false;
			}
			TValue value3 = value2.Value;
			if (!_table.Remove(key))
			{
				value = default(TValue);
				return false;
			}
			value = value3;
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Removes all entries from the table without affecting live <typeparamref name="TKey" />
		///         instances.
		///     </para>
		///     <para xml:lang="zh-CN">移除表中的所有条目，但不影响仍存活的 <typeparamref name="TKey" /> 实例。</para>
		/// </summary>
		public void Clear()
		{
			_table.Clear();
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides host-version-stable helpers for checking whether a creature displays infinite HP.</para>
	///     <para xml:lang="zh-CN">提供跨宿主版本保持稳定的辅助方法，用于检查生物是否显示无限生命值。</para>
	/// </summary>
	public static class CreatureHpDisplayExtensions
	{
		/// <summary>
		///     <para xml:lang="en">Returns whether the creature's HP display is currently in infinite mode.</para>
		///     <para xml:lang="zh-CN">返回该生物的生命值显示当前是否处于无限模式。</para>
		/// </summary>
		public static bool IsInfiniteHpDisplayed(this Creature creature)
		{
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(creature, "creature");
			return HpDisplayExtensions.IsInfinite(creature.HpDisplay);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Describes an immutable mod-owned dynamic enum value registered through
	///         <see cref="T:STS2RitsuLib.Utils.DynamicEnumValueRegistry`1" />.
	///     </para>
	///     <para xml:lang="zh-CN">表示通过 <see cref="T:STS2RitsuLib.Utils.DynamicEnumValueRegistry`1" /> 注册的模组归属动态枚举值定义。</para>
	/// </summary>
	public sealed record DynamicEnumValueDefinition<TEnum>(string ModId, string Id, TEnum Value) where TEnum : struct, Enum;
	/// <summary>
	///     <para xml:lang="en">
	///         Deterministically mints 32-bit integer values for string IDs and casts them into
	///         <typeparamref name="TEnum" />. Minted values occupy the reserved high-value band at or above
	///         <see cref="P:STS2RitsuLib.Utils.DynamicEnumValueMinter`1.ReservedFloor" />, leaving the low range for vanilla enum members.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为字符串 ID 确定性地生成 32 位整数值并将其转换为 <typeparamref name="TEnum" />。生成值位于不低于
	///         <see cref="P:STS2RitsuLib.Utils.DynamicEnumValueMinter`1.ReservedFloor" /> 的保留高值区间，低值范围留给原版枚举成员。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Values use <c>ReservedFloor + (XxHash32(utf8(id)) mod (int.MaxValue - ReservedFloor + 1))</c>,
	///         so the same ID has a stable value across processes and runs. Recording a distinct ID that collides with an
	///         existing one is rejected.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         值使用 <c>ReservedFloor + (XxHash32(utf8(id)) mod (int.MaxValue - ReservedFloor + 1))</c>
	///         计算，因此同一 ID 在不同进程和运行中保持稳定。登记不同 ID 时若与现有 ID 发生哈希碰撞，该操作会被拒绝。
	///     </para>
	///     <para xml:lang="en">Only 32-bit-backed <c>int</c> or <c>uint</c> enums are supported.</para>
	///     <para xml:lang="zh-CN">仅支持底层类型为 32 位 <c>int</c> 或 <c>uint</c> 的枚举。</para>
	/// </remarks>
	public sealed class DynamicEnumValueMinter<TEnum> where TEnum : struct, Enum
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Default reserved floor. Minted values land in <c>[0x4000_0000, 0x7FFF_FFFF]</c>, reserving the
		///         lower positive range for vanilla enum members.
		///     </para>
		///     <para xml:lang="zh-CN">默认保留下界。生成值落在 <c>[0x4000_0000, 0x7FFF_FFFF]</c>，为原版枚举成员保留较低的正值范围。</para>
		/// </summary>
		public const int DefaultReservedFloor = 1073741824;

		private readonly Dictionary<string, TEnum> _byId = new Dictionary<string, TEnum>(StringComparer.OrdinalIgnoreCase);

		private readonly Dictionary<TEnum, string> _byValue = new Dictionary<TEnum, string>();

		private readonly Lock _sync = new Lock();

		/// <summary>
		///     <para xml:lang="en">Inclusive lower bound for all minted values; vanilla members below it never collide.</para>
		///     <para xml:lang="zh-CN">所有生成值的包含下界；低于该值的原版成员永不碰撞。</para>
		/// </summary>
		public int ReservedFloor { get; }

		/// <summary>
		///     <para xml:lang="en">Creates a minter using <see cref="F:STS2RitsuLib.Utils.DynamicEnumValueMinter`1.DefaultReservedFloor" />.</para>
		///     <para xml:lang="zh-CN">使用 <see cref="F:STS2RitsuLib.Utils.DynamicEnumValueMinter`1.DefaultReservedFloor" /> 创建生成器。</para>
		/// </summary>
		public DynamicEnumValueMinter()
			: this(1073741824)
		{
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a minter whose integer values are always <c>&gt;= <paramref name="reservedFloor" /></c>
		///         .
		///     </para>
		///     <para xml:lang="zh-CN">创建一个生成器，其整数值始终 <c>&gt;= <paramref name="reservedFloor" /></c>。</para>
		/// </summary>
		/// <param name="reservedFloor">
		///     <para xml:lang="en">
		///         Inclusive lower bound for minted values. It must be <c>&gt;= 0</c>; <c>[0, reservedFloor)</c>
		///         remains available to vanilla enum members.
		///     </para>
		///     <para xml:lang="zh-CN">生成值的包含下界。它必须为 <c>&gt;= 0</c>；<c>[0, reservedFloor)</c> 留给原版枚举成员。</para>
		/// </param>
		public DynamicEnumValueMinter(int reservedFloor)
		{
			if (Unsafe.SizeOf<TEnum>() != 4)
			{
				throw new NotSupportedException($"DynamicEnumValueMinter only supports 32-bit backed enums; '{typeof(TEnum).FullName}' is {Unsafe.SizeOf<TEnum>() * 8}-bit.");
			}
			if (reservedFloor < 0)
			{
				throw new ArgumentOutOfRangeException("reservedFloor", "Reserved floor must be non-negative.");
			}
			ReservedFloor = reservedFloor;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the <typeparamref name="TEnum" /> value for <paramref name="id" />, recording it on
		///         first call. Subsequent case-insensitive uses of the same ID return the same value.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <paramref name="id" /> 对应的 <typeparamref name="TEnum" /> 值，并在首次调用时登记。之后以不区分大小写的相同 ID
		///         调用会返回同一值。
		///     </para>
		/// </summary>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en"><paramref name="id" /> is null or whitespace.</para>
		///     <para xml:lang="zh-CN"><paramref name="id" /> 为 null 或空白。</para>
		/// </exception>
		/// <exception cref="T:System.InvalidOperationException">
		///     <para xml:lang="en">
		///         Two distinct IDs hash to the same <typeparamref name="TEnum" /> value; collision detection
		///         occurs while recording the ID, and callers must choose non-colliding IDs.
		///     </para>
		///     <para xml:lang="zh-CN">两个不同 ID 哈希到同一个 <typeparamref name="TEnum" /> 值；登记 ID 时会检测此碰撞，调用方必须改用不冲突的 ID。</para>
		/// </exception>
		public TEnum Mint(string id)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			string text = Normalize(id);
			using (_sync.EnterScope())
			{
				if (_byId.TryGetValue(text, out var value))
				{
					return value;
				}
				TEnum val = Compute(text);
				if (_byValue.TryGetValue(val, out string value2))
				{
					throw new InvalidOperationException($"DynamicEnumValueMinter<{typeof(TEnum).Name}> hash collision: '{text}' and '{value2}' both map to the same numeric value. " + "Change one of the ids to resolve the clash.");
				}
				_byId[text] = val;
				_byValue[val] = text;
				return val;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Computes the deterministic <typeparamref name="TEnum" /> value for <paramref name="id" />
		///         without registering it or checking whether another ID already owns the numeric value.
		///     </para>
		///     <para xml:lang="zh-CN">计算 <paramref name="id" /> 的确定性 <typeparamref name="TEnum" /> 值，但不注册，也不检查其他 ID 是否已占用该数值。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         Use this only when the raw pre-validation value is required. Its result is not visible to
		///         <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueMinter`1.TryGetId(`0,System.String@)" /> or <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueMinter`1.IsDynamic(`0)" /> unless <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueMinter`1.Mint(System.String)" /> also records it.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         仅在需要碰撞校验前的原始值时使用。除非也通过 <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueMinter`1.Mint(System.String)" /> 登记，否则结果不会出现在 <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueMinter`1.TryGetId(`0,System.String@)" /> 或
		///         <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueMinter`1.IsDynamic(`0)" /> 中。
		///     </para>
		/// </remarks>
		public TEnum ComputeValue(string id)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			return Compute(Normalize(id));
		}

		/// <summary>
		///     <para xml:lang="en">Attempts to resolve the string ID that minted <paramref name="value" />.</para>
		///     <para xml:lang="zh-CN">尝试解析生成 <paramref name="value" /> 的字符串 ID。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en"><c>true</c> when <paramref name="value" /> was produced by an earlier <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueMinter`1.Mint(System.String)" /> call.</para>
		///     <para xml:lang="zh-CN"><paramref name="value" /> 由先前的 <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueMinter`1.Mint(System.String)" /> 调用生成时为 <c>true</c>。</para>
		/// </returns>
		public bool TryGetId(TEnum value, out string id)
		{
			using (_sync.EnterScope())
			{
				if (_byValue.TryGetValue(value, out string value2))
				{
					id = value2;
					return true;
				}
			}
			id = string.Empty;
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the <typeparamref name="TEnum" /> value currently bound to <paramref name="id" />
		///         without registering a new one.
		///     </para>
		///     <para xml:lang="zh-CN">返回当前绑定到 <paramref name="id" /> 的 <typeparamref name="TEnum" /> 值，不注册新值。</para>
		/// </summary>
		public bool TryGetValue(string id, out TEnum value)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			string key = Normalize(id);
			using (_sync.EnterScope())
			{
				return _byId.TryGetValue(key, out value);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Whether <paramref name="value" /> is present in this minter's reverse-lookup table.</para>
		///     <para xml:lang="zh-CN"><paramref name="value" /> 是否存在于此生成器的反向查找表中。</para>
		/// </summary>
		public bool IsDynamic(TEnum value)
		{
			using (_sync.EnterScope())
			{
				return _byValue.ContainsKey(value);
			}
		}

		internal (string Id, TEnum Value)[] GetMintedValuesSnapshot()
		{
			using (_sync.EnterScope())
			{
				return (from pair in _byId.OrderBy<KeyValuePair<string, TEnum>, string>((KeyValuePair<string, TEnum> pair) => pair.Key, StringComparer.Ordinal)
					select (Key: pair.Key, Value: pair.Value)).ToArray();
			}
		}

		private TEnum Compute(string normalizedId)
		{
			uint num = XxHash32.HashToUInt32((ReadOnlySpan<byte>)Encoding.UTF8.GetBytes(normalizedId), 0);
			uint reservedFloor = (uint)ReservedFloor;
			uint num2 = int.MaxValue - reservedFloor + 1;
			int source = (int)(reservedFloor + num % num2);
			return Unsafe.As<int, TEnum>(ref source);
		}

		private static string Normalize(string id)
		{
			return id.Trim().ToLowerInvariant();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Process-wide registration surface for mod-owned dynamic enum values, centralizing deterministic
	///         value allocation, ownership validation, and reverse lookup.
	///     </para>
	///     <para xml:lang="zh-CN">面向模组归属动态枚举值的进程级注册入口，集中处理确定性数值分配、归属校验和反向查找。</para>
	/// </summary>
	/// <typeparam name="TEnum">
	///     <para xml:lang="en">The 32-bit-backed enum type to extend.</para>
	///     <para xml:lang="zh-CN">要扩展的 32 位底层枚举类型。</para>
	/// </typeparam>
	/// <remarks>
	///     <para xml:lang="en">
	///         Prefer a type-specific registry such as <c>ModCardTagRegistry</c> when available, because it
	///         may add metadata or lifecycle rules. Use this generic registry only for extension points that need a stable
	///         value and ownership validation.
	///     </para>
	///     <para xml:lang="zh-CN">存在类型专用注册表时应优先使用，例如 <c>ModCardTagRegistry</c>，因为它可能附加元数据或生命周期规则。仅需要稳定值和归属校验的扩展点才使用此通用注册表。</para>
	/// </remarks>
	public static class DynamicEnumValueRegistry<TEnum> where TEnum : struct, Enum
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly DynamicEnumValueMinter<TEnum> Minter = new DynamicEnumValueMinter<TEnum>();

		private static readonly Dictionary<string, ModDynamicEnumValueRegistry<TEnum>> Registries = new Dictionary<string, ModDynamicEnumValueRegistry<TEnum>>(StringComparer.OrdinalIgnoreCase);

		private static readonly Dictionary<string, DynamicEnumValueDefinition<TEnum>> Definitions = new Dictionary<string, DynamicEnumValueDefinition<TEnum>>(StringComparer.OrdinalIgnoreCase);

		private static readonly Dictionary<TEnum, DynamicEnumValueDefinition<TEnum>> DefinitionsByValue = new Dictionary<TEnum, DynamicEnumValueDefinition<TEnum>>();

		private static string CategoryStem { get; } = ResolveCategoryStem();

		/// <summary>
		///     <para xml:lang="en">Returns the per-mod facade for <paramref name="modId" />, creating it on first use.</para>
		///     <para xml:lang="zh-CN">返回 <paramref name="modId" /> 的逐模组门面，并在首次使用时创建。</para>
		/// </summary>
		public static ModDynamicEnumValueRegistry<TEnum> For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (SyncRoot.EnterScope())
			{
				if (Registries.TryGetValue(modId, out ModDynamicEnumValueRegistry<TEnum> value))
				{
					return value;
				}
				ModDynamicEnumValueRegistry<TEnum> modDynamicEnumValueRegistry = new ModDynamicEnumValueRegistry<TEnum>(modId);
				Registries[modId] = modDynamicEnumValueRegistry;
				return modDynamicEnumValueRegistry;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers a mod-owned value using the enum type's configured category segment.</para>
		///     <para xml:lang="zh-CN">使用该枚举类型配置的类别段注册模组归属值。</para>
		/// </summary>
		public static DynamicEnumValueDefinition<TEnum> RegisterOwned(string modId, string localStem)
		{
			string ownedId = GetOwnedId(modId, localStem);
			return Register(modId, ownedId);
		}

		/// <summary>
		///     <para xml:lang="en">Builds the canonical owned ID for <paramref name="localStem" />.</para>
		///     <para xml:lang="zh-CN">为 <paramref name="localStem" /> 构建规范的归属 ID。</para>
		/// </summary>
		public static string GetOwnedId(string modId, string localStem)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(localStem, "localStem");
			return ModContentRegistry.GetCompoundId(modId, CategoryStem, localStem);
		}

		/// <summary>
		///     <para xml:lang="en">Registers a mod-owned value with an already qualified ID.</para>
		///     <para xml:lang="zh-CN">使用已限定的 ID 注册模组归属值。</para>
		/// </summary>
		public static DynamicEnumValueDefinition<TEnum> Register(string modId, string id)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			return RegisterWithMintKey(modId, id, NormalizeId(id));
		}

		internal static DynamicEnumValueDefinition<TEnum> RegisterWithMintKey(string modId, string id, string mintKey)
		{
			ArgumentNullException.ThrowIfNull(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentException.ThrowIfNullOrWhiteSpace(mintKey, "mintKey");
			string text = NormalizeId(id);
			TEnum val = Minter.Mint(mintKey);
			DynamicEnumValueDefinition<TEnum> dynamicEnumValueDefinition = new DynamicEnumValueDefinition<TEnum>(modId.Trim(), text, val);
			using (SyncRoot.EnterScope())
			{
				if (Definitions.TryGetValue(text, out DynamicEnumValueDefinition<TEnum> value))
				{
					if (!StringComparer.OrdinalIgnoreCase.Equals(value.ModId, dynamicEnumValueDefinition.ModId))
					{
						throw new InvalidOperationException($"Dynamic enum value '{text}' for {typeof(TEnum).Name} is already registered by mod '{value.ModId}'; mod '{dynamicEnumValueDefinition.ModId}' cannot re-register it.");
					}
					return value;
				}
				Definitions[text] = dynamicEnumValueDefinition;
				DefinitionsByValue[val] = dynamicEnumValueDefinition;
				return dynamicEnumValueDefinition;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Tries to resolve a registered definition by ID without minting a new value.</para>
		///     <para xml:lang="zh-CN">尝试按 ID 解析已注册定义，不会生成新值。</para>
		/// </summary>
		public static bool TryGet(string id, out DynamicEnumValueDefinition<TEnum> definition)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			using (SyncRoot.EnterScope())
			{
				return Definitions.TryGetValue(NormalizeId(id), out definition);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Returns the registered definition for <paramref name="id" /> or throws.</para>
		///     <para xml:lang="zh-CN">返回 <paramref name="id" /> 对应的已注册定义；不存在时抛出异常。</para>
		/// </summary>
		public static DynamicEnumValueDefinition<TEnum> Get(string id)
		{
			if (!TryGet(id, out DynamicEnumValueDefinition<TEnum> definition))
			{
				throw new KeyNotFoundException($"Dynamic enum value '{NormalizeId(id)}' for {typeof(TEnum).Name} is not registered.");
			}
			return definition;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the registered dynamic-enum definition represented by <paramref name="value" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 <paramref name="value" /> 所表示的已注册动态枚举定义。
		///     </para>
		/// </summary>
		/// <param name="value">
		///     <para xml:lang="en">The dynamic enum value to resolve.</para>
		///     <para xml:lang="zh-CN">要解析的动态枚举值。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The registered dynamic-enum definition.</para>
		///     <para xml:lang="zh-CN">已注册的动态枚举定义。</para>
		/// </returns>
		/// <exception cref="T:System.Collections.Generic.KeyNotFoundException">
		///     <para xml:lang="en"><paramref name="value" /> is not registered for <typeparamref name="TEnum" />.</para>
		///     <para xml:lang="zh-CN"><paramref name="value" /> 未在 <typeparamref name="TEnum" /> 注册表中注册。</para>
		/// </exception>
		public static DynamicEnumValueDefinition<TEnum> Get(TEnum value)
		{
			if (!TryGetByValue(value, out DynamicEnumValueDefinition<TEnum> definition))
			{
				throw new KeyNotFoundException($"{typeof(TEnum).Name} value '{value}' is not registered.");
			}
			return definition;
		}

		/// <summary>
		///     <para xml:lang="en">Resolves which mod registered <paramref name="id" />, if any.</para>
		///     <para xml:lang="zh-CN">解析 <paramref name="id" /> 由哪个模组注册（如果存在）。</para>
		/// </summary>
		public static bool TryGetOwnerModId(string id, out string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			using (SyncRoot.EnterScope())
			{
				if (Definitions.TryGetValue(NormalizeId(id), out DynamicEnumValueDefinition<TEnum> value))
				{
					modId = value.ModId;
					return true;
				}
			}
			modId = string.Empty;
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Resolves a registered definition by dynamic enum value.</para>
		///     <para xml:lang="zh-CN">通过动态枚举值解析已注册定义。</para>
		/// </summary>
		public static bool TryGetByValue(TEnum value, out DynamicEnumValueDefinition<TEnum> definition)
		{
			using (SyncRoot.EnterScope())
			{
				return DefinitionsByValue.TryGetValue(value, out definition);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Whether <paramref name="value" /> is registered through this central registry.</para>
		///     <para xml:lang="zh-CN"><paramref name="value" /> 是否通过此中央注册表注册。</para>
		/// </summary>
		public static bool IsRegistered(TEnum value)
		{
			using (SyncRoot.EnterScope())
			{
				return DefinitionsByValue.ContainsKey(value);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the deterministic enum value for <paramref name="id" /> without registering a
		///         definition. Unknown IDs are recorded by the minter; prefer <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueRegistry`1.Register(System.String,System.String)" /> or
		///         <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueRegistry`1.RegisterOwned(System.String,System.String)" /> for new public extension values.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <paramref name="id" /> 的确定性枚举值，但不注册定义。未知 ID 会由生成器登记；分配新的公开扩展值时优先使用
		///         <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueRegistry`1.Register(System.String,System.String)" /> 或 <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueRegistry`1.RegisterOwned(System.String,System.String)" />。
		///     </para>
		/// </summary>
		public static TEnum GetValue(string id)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			return GetValueWithMintKey(id, NormalizeId(id));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the deterministic enum value for <paramref name="id" /> without failing on hash
		///         collisions. An unknown ID is computed without registering a definition or adding a minter reverse lookup.
		///     </para>
		///     <para xml:lang="zh-CN">返回 <paramref name="id" /> 的确定性枚举值，且不会因哈希碰撞失败。未知 ID 只计算值，不注册定义，也不加入生成器的反向查找。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         This is an explicit escape hatch for diagnostics and compatibility code that must recover the
		///         raw value an ID would have produced after another ID minted the same numeric value.
		///     </para>
		///     <para xml:lang="zh-CN">这是面向诊断和兼容代码的显式旁路：即使其他 ID 已生成同一数值，也可取回该 ID 本应生成的原始值。</para>
		/// </remarks>
		public static TEnum GetValueIgnoringCollisions(string id)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			return GetValueWithMintKeyIgnoringCollisions(id, NormalizeId(id));
		}

		internal static TEnum GetValueWithMintKey(string id, string mintKey)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentException.ThrowIfNullOrWhiteSpace(mintKey, "mintKey");
			string key = NormalizeId(id);
			using (SyncRoot.EnterScope())
			{
				if (Definitions.TryGetValue(key, out DynamicEnumValueDefinition<TEnum> value))
				{
					return value.Value;
				}
			}
			return Minter.Mint(mintKey);
		}

		internal static TEnum GetValueWithMintKeyIgnoringCollisions(string id, string mintKey)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentException.ThrowIfNullOrWhiteSpace(mintKey, "mintKey");
			string key = NormalizeId(id);
			using (SyncRoot.EnterScope())
			{
				if (Definitions.TryGetValue(key, out DynamicEnumValueDefinition<TEnum> value))
				{
					return value.Value;
				}
			}
			return Minter.ComputeValue(mintKey);
		}

		/// <summary>
		///     <para xml:lang="en">Tries to return or mint the deterministic enum value for <paramref name="id" />.</para>
		///     <para xml:lang="zh-CN">尝试返回或生成 <paramref name="id" /> 的确定性枚举值。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="false" /> only when an unknown ID collides with an ID already recorded by the
		///         minter.
		///     </para>
		///     <para xml:lang="zh-CN">仅当未知 ID 与生成器已登记的 ID 发生哈希碰撞时返回 <see langword="false" />。</para>
		/// </returns>
		public static bool TryGetValue(string id, out TEnum value)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			try
			{
				value = GetValue(id);
				return true;
			}
			catch (InvalidOperationException)
			{
				value = default(TEnum);
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves a registered dynamic ID, a vanilla enum name or numeric literal, or an otherwise
		///         unknown ID by minting its deterministic value, in that order.
		///     </para>
		///     <para xml:lang="zh-CN">依次尝试将输入解析为已注册动态 ID、原版枚举名称或数字字面量；若均不匹配，则为未知 ID 生成确定性值。</para>
		/// </summary>
		public static bool TryResolve(string idOrEnumName, out TEnum value)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(idOrEnumName, "idOrEnumName");
			if (!TryGet(idOrEnumName, out DynamicEnumValueDefinition<TEnum> definition))
			{
				if (!Enum.TryParse<TEnum>(idOrEnumName.Trim(), ignoreCase: true, out value))
				{
					return TryGetValue(idOrEnumName, out value);
				}
				return true;
			}
			value = definition.Value;
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Tries to resolve the registered ID for <paramref name="value" />.</para>
		///     <para xml:lang="zh-CN">尝试解析 <paramref name="value" /> 对应的已注册 ID。</para>
		/// </summary>
		public static bool TryGetId(TEnum value, out string id)
		{
			using (SyncRoot.EnterScope())
			{
				if (DefinitionsByValue.TryGetValue(value, out DynamicEnumValueDefinition<TEnum> value2))
				{
					id = value2.Id;
					return true;
				}
			}
			id = string.Empty;
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Tries to resolve the normalized mint key that produced <paramref name="value" />, including
		///         values minted by <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueRegistry`1.GetValue(System.String)" /> without registration.
		///     </para>
		///     <para xml:lang="zh-CN">尝试解析生成 <paramref name="value" /> 的规范化生成键，包括通过 <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueRegistry`1.GetValue(System.String)" /> 生成但未注册的值。</para>
		/// </summary>
		public static bool TryGetMintedId(TEnum value, out string id)
		{
			return Minter.TryGetId(value, out id);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Whether <paramref name="value" /> is recorded by this registry's minter, including values
		///         minted by <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueRegistry`1.GetValue(System.String)" /> without a registered definition.
		///     </para>
		///     <para xml:lang="zh-CN"><paramref name="value" /> 是否已由此注册表的生成器登记，包括通过 <see cref="M:STS2RitsuLib.Utils.DynamicEnumValueRegistry`1.GetValue(System.String)" /> 生成但未注册定义的值。</para>
		/// </summary>
		public static bool IsMinted(TEnum value)
		{
			return Minter.IsDynamic(value);
		}

		internal static (string Id, TEnum Value)[] GetMintedValuesSnapshot()
		{
			return Minter.GetMintedValuesSnapshot();
		}

		/// <summary>
		///     <para xml:lang="en">Snapshot of all registered dynamic enum definitions, stably ordered by ID.</para>
		///     <para xml:lang="zh-CN">所有已注册动态枚举定义的快照，按 ID 稳定排序。</para>
		/// </summary>
		public static DynamicEnumValueDefinition<TEnum>[] GetDefinitionsSnapshot()
		{
			using (SyncRoot.EnterScope())
			{
				return Definitions.Values.OrderBy<DynamicEnumValueDefinition<TEnum>, string>((DynamicEnumValueDefinition<TEnum> definition) => definition.Id, StringComparer.Ordinal).ToArray();
			}
		}

		private static string NormalizeId(string id)
		{
			return id.Trim();
		}

		private static string ResolveCategoryStem()
		{
			Type typeFromHandle = typeof(TEnum);
			if (typeFromHandle == typeof(CardKeyword))
			{
				return "KEYWORD";
			}
			if (typeFromHandle == typeof(PileType))
			{
				return "CARDPILE";
			}
			if (typeFromHandle == typeof(CardTag))
			{
				return "CARDTAG";
			}
			if (typeFromHandle == typeof(RewardType))
			{
				return "REWARD";
			}
			if (typeFromHandle == typeof(TargetType))
			{
				return "TARGETTYPE";
			}
			return ModContentRegistry.NormalizePublicStem(typeFromHandle.Name);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Builds and caches expression-based delegates for fast reflective method calls, constructor
	///         calls, and instance-member reads.
	///     </para>
	///     <para xml:lang="zh-CN">构建并缓存基于表达式的委托，以快速执行反射方法调用、构造函数调用和实例成员读取。</para>
	/// </summary>
	internal static class FastMethodInvoker
	{
		private static readonly ConcurrentDictionary<MethodInfo, Func<object?, object?>> Invoke0Cache = new ConcurrentDictionary<MethodInfo, Func<object, object>>();

		private static readonly ConcurrentDictionary<MethodInfo, Func<object?, object?, object?>> Invoke1Cache = new ConcurrentDictionary<MethodInfo, Func<object, object, object>>();

		private static readonly ConcurrentDictionary<MethodInfo, Func<object?, object?, object?, object?>> Invoke2Cache = new ConcurrentDictionary<MethodInfo, Func<object, object, object, object>>();

		private static readonly ConcurrentDictionary<MethodInfo, Func<object?, object?, object?, object?, object?>> Invoke3Cache = new ConcurrentDictionary<MethodInfo, Func<object, object, object, object, object>>();

		private static readonly ConcurrentDictionary<MethodInfo, Action<object?, object?>> Invoke1VoidCache = new ConcurrentDictionary<MethodInfo, Action<object, object>>();

		private static readonly ConcurrentDictionary<MethodInfo, Action<object?>> Invoke0VoidCache = new ConcurrentDictionary<MethodInfo, Action<object>>();

		private static readonly ConcurrentDictionary<MethodInfo, Action<object?, object?, object?, object?>> Invoke3VoidCache = new ConcurrentDictionary<MethodInfo, Action<object, object, object, object>>();

		private static readonly ConcurrentDictionary<MethodInfo, Action<object?, object?, object?>> Invoke2VoidCache = new ConcurrentDictionary<MethodInfo, Action<object, object, object>>();

		private static readonly ConcurrentDictionary<ConstructorInfo, Func<object?>> CtorCache = new ConcurrentDictionary<ConstructorInfo, Func<object>>();

		private static readonly ConcurrentDictionary<MemberInfo, Func<object, object?>> InstanceGetterCache = new ConcurrentDictionary<MemberInfo, Func<object, object>>();

		public static TResult? Invoke0<TResult>(MethodInfo method, object? instance)
		{
			object obj = Invoke0(method, instance);
			if (obj != null)
			{
				return (TResult)obj;
			}
			return default(TResult);
		}

		public static object? Invoke0(MethodInfo method, object? instance)
		{
			ArgumentNullException.ThrowIfNull(method, "method");
			return Invoke0Cache.GetOrAdd(method, BuildInvoke0)(instance);
		}

		public static TResult? Invoke1<TArg, TResult>(MethodInfo method, object? instance, TArg arg)
		{
			object obj = Invoke1(method, instance, arg);
			if (obj != null)
			{
				return (TResult)obj;
			}
			return default(TResult);
		}

		public static object? Invoke1(MethodInfo method, object? instance, object? arg)
		{
			ArgumentNullException.ThrowIfNull(method, "method");
			return Invoke1Cache.GetOrAdd(method, BuildInvoke1)(instance, arg);
		}

		public static TResult? Invoke2<TArg1, TArg2, TResult>(MethodInfo method, object? instance, TArg1 arg1, TArg2 arg2)
		{
			object obj = Invoke2(method, instance, arg1, arg2);
			if (obj != null)
			{
				return (TResult)obj;
			}
			return default(TResult);
		}

		public static object? Invoke2(MethodInfo method, object? instance, object? arg1, object? arg2)
		{
			ArgumentNullException.ThrowIfNull(method, "method");
			return Invoke2Cache.GetOrAdd(method, BuildInvoke2)(instance, arg1, arg2);
		}

		public static object? Invoke3(MethodInfo method, object? instance, object? arg1, object? arg2, object? arg3)
		{
			ArgumentNullException.ThrowIfNull(method, "method");
			return Invoke3Cache.GetOrAdd(method, BuildInvoke3)(instance, arg1, arg2, arg3);
		}

		public static void Invoke0Void(MethodInfo method, object? instance)
		{
			ArgumentNullException.ThrowIfNull(method, "method");
			Invoke0VoidCache.GetOrAdd(method, BuildInvoke0Void)(instance);
		}

		public static void Invoke1Void(MethodInfo method, object? instance, object? arg)
		{
			ArgumentNullException.ThrowIfNull(method, "method");
			Invoke1VoidCache.GetOrAdd(method, BuildInvoke1Void)(instance, arg);
		}

		public static void Invoke2Void(MethodInfo method, object? instance, object? arg1, object? arg2)
		{
			ArgumentNullException.ThrowIfNull(method, "method");
			Invoke2VoidCache.GetOrAdd(method, BuildInvoke2Void)(instance, arg1, arg2);
		}

		public static void Invoke3Void(MethodInfo method, object? instance, object? arg1, object? arg2, object? arg3)
		{
			ArgumentNullException.ThrowIfNull(method, "method");
			Invoke3VoidCache.GetOrAdd(method, BuildInvoke3Void)(instance, arg1, arg2, arg3);
		}

		public static object? InvokeStatic0(MethodInfo method)
		{
			return Invoke0(method, null);
		}

		public static object? InvokeStatic1(MethodInfo method, object? arg)
		{
			return Invoke1(method, null, arg);
		}

		public static object? InvokeStatic2(MethodInfo method, object? arg1, object? arg2)
		{
			return Invoke2(method, null, arg1, arg2);
		}

		public static object? InvokeStatic3(MethodInfo method, object? arg1, object? arg2, object? arg3)
		{
			return Invoke3(method, null, arg1, arg2, arg3);
		}

		public static void InvokeStatic0Void(MethodInfo method)
		{
			Invoke0Void(method, null);
		}

		public static void InvokeStatic1Void(MethodInfo method, object? arg)
		{
			Invoke1Void(method, null, arg);
		}

		public static void InvokeStatic2Void(MethodInfo method, object? arg1, object? arg2)
		{
			Invoke2Void(method, null, arg1, arg2);
		}

		public static void InvokeStatic3Void(MethodInfo method, object? arg1, object? arg2, object? arg3)
		{
			Invoke3Void(method, null, arg1, arg2, arg3);
		}

		public static object? CreateWithDefaultCtor(ConstructorInfo ctor)
		{
			ArgumentNullException.ThrowIfNull(ctor, "ctor");
			return CtorCache.GetOrAdd(ctor, BuildCtor)();
		}

		public static Func<object, object?> CreateInstanceGetter(MemberInfo member)
		{
			ArgumentNullException.ThrowIfNull(member, "member");
			return InstanceGetterCache.GetOrAdd(member, BuildInstanceGetter);
		}

		public static object? GetInstanceValue(MemberInfo member, object instance)
		{
			return CreateInstanceGetter(member)(instance);
		}

		public static Func<TDeclaring, TValue> CreateInstanceGetter<TDeclaring, TValue>(MemberInfo member)
		{
			ArgumentNullException.ThrowIfNull(member, "member");
			ParameterExpression parameterExpression = Expression.Parameter(typeof(TDeclaring), "instance");
			Expression expression = BuildInstanceMemberAccess(parameterExpression, member);
			return Expression.Lambda<Func<TDeclaring, TValue>>((expression.Type == typeof(TValue)) ? expression : Expression.Convert(expression, typeof(TValue)), new ParameterExpression[1] { parameterExpression }).Compile();
		}

		private static Func<object?> BuildCtor(ConstructorInfo ctor)
		{
			return Expression.Lambda<Func<object>>(Expression.Convert(Expression.New(ctor), typeof(object)), Array.Empty<ParameterExpression>()).Compile();
		}

		private static Func<object, object?> BuildInstanceGetter(MemberInfo member)
		{
			if (!(member is PropertyInfo property))
			{
				if (member is FieldInfo field)
				{
					return BuildFieldGetter(field);
				}
				throw new ArgumentException($"Member '{member}' is not a field or property.", "member");
			}
			return BuildPropertyGetter(property);
		}

		private static Func<object, object?> BuildPropertyGetter(PropertyInfo property)
		{
			if (property.GetIndexParameters().Length != 0)
			{
				throw new ArgumentException($"Property '{property}' is indexed.", "property");
			}
			ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "instance");
			return Expression.Lambda<Func<object, object>>(Expression.Convert(BuildInstanceMemberAccess(ConvertInstance(parameterExpression, property.DeclaringType), property), typeof(object)), new ParameterExpression[1] { parameterExpression }).Compile();
		}

		private static Func<object, object?> BuildFieldGetter(FieldInfo field)
		{
			if (field.IsStatic)
			{
				throw new ArgumentException($"Field '{field}' is static.", "field");
			}
			ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "instance");
			return Expression.Lambda<Func<object, object>>(Expression.Convert(BuildInstanceMemberAccess(ConvertInstance(parameterExpression, field.DeclaringType), field), typeof(object)), new ParameterExpression[1] { parameterExpression }).Compile();
		}

		private static Expression BuildInstanceMemberAccess(Expression instance, MemberInfo member)
		{
			if (!(member is PropertyInfo propertyInfo))
			{
				if (member is FieldInfo fieldInfo)
				{
					if (!fieldInfo.IsStatic)
					{
						return Expression.Field(ConvertTypedInstance(instance, fieldInfo.DeclaringType), fieldInfo);
					}
					FieldInfo value = fieldInfo;
					throw new ArgumentException($"Field '{value}' is static.", "member");
				}
				throw new ArgumentException($"Member '{member}' is not a field or property.", "member");
			}
			if (propertyInfo.GetIndexParameters().Length != 0)
			{
				throw new ArgumentException($"Property '{propertyInfo}' is indexed.", "member");
			}
			MethodInfo? getMethod = propertyInfo.GetGetMethod(nonPublic: true);
			if (getMethod == null)
			{
				throw new ArgumentException($"Property '{propertyInfo}' has no getter.", "member");
			}
			if (getMethod.IsStatic)
			{
				throw new ArgumentException($"Property '{propertyInfo}' is static.", "member");
			}
			return Expression.Property(ConvertTypedInstance(instance, propertyInfo.DeclaringType), propertyInfo);
		}

		private static Expression ConvertInstance(Expression instance, Type declaringType)
		{
			if (!declaringType.IsValueType)
			{
				return Expression.Convert(instance, declaringType);
			}
			return Expression.Unbox(instance, declaringType);
		}

		private static Expression ConvertTypedInstance(Expression instance, Type declaringType)
		{
			if (!(instance.Type == declaringType))
			{
				return Expression.Convert(instance, declaringType);
			}
			return instance;
		}

		private static Func<object?, object?> BuildInvoke0(MethodInfo method)
		{
			ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "instance");
			MethodCallExpression methodCallExpression = Expression.Call(method.IsStatic ? null : Expression.Convert(parameterExpression, method.DeclaringType), method);
			return Expression.Lambda<Func<object, object>>((method.ReturnType == typeof(void)) ? ((Expression)Expression.Block(methodCallExpression, Expression.Constant(null, typeof(object)))) : ((Expression)Expression.Convert(methodCallExpression, typeof(object))), new ParameterExpression[1] { parameterExpression }).Compile();
		}

		private static Action<object?> BuildInvoke0Void(MethodInfo method)
		{
			ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "instance");
			return Expression.Lambda<Action<object>>(Expression.Call(method.IsStatic ? null : Expression.Convert(parameterExpression, method.DeclaringType), method), new ParameterExpression[1] { parameterExpression }).Compile();
		}

		private static Func<object?, object?, object?> BuildInvoke1(MethodInfo method)
		{
			ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "instance");
			ParameterExpression parameterExpression2 = Expression.Parameter(typeof(object), "arg0");
			Type parameterType = method.GetParameters()[0].ParameterType;
			MethodCallExpression methodCallExpression = Expression.Call(method.IsStatic ? null : Expression.Convert(parameterExpression, method.DeclaringType), method, Expression.Convert(parameterExpression2, parameterType));
			return Expression.Lambda<Func<object, object, object>>((method.ReturnType == typeof(void)) ? ((Expression)Expression.Block(methodCallExpression, Expression.Constant(null, typeof(object)))) : ((Expression)Expression.Convert(methodCallExpression, typeof(object))), new ParameterExpression[2] { parameterExpression, parameterExpression2 }).Compile();
		}

		private static Action<object?, object?> BuildInvoke1Void(MethodInfo method)
		{
			ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "instance");
			ParameterExpression parameterExpression2 = Expression.Parameter(typeof(object), "arg0");
			Type parameterType = method.GetParameters()[0].ParameterType;
			return Expression.Lambda<Action<object, object>>(Expression.Call(method.IsStatic ? null : Expression.Convert(parameterExpression, method.DeclaringType), method, Expression.Convert(parameterExpression2, parameterType)), new ParameterExpression[2] { parameterExpression, parameterExpression2 }).Compile();
		}

		private static Func<object?, object?, object?, object?> BuildInvoke2(MethodInfo method)
		{
			ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "instance");
			ParameterExpression parameterExpression2 = Expression.Parameter(typeof(object), "arg0");
			ParameterExpression parameterExpression3 = Expression.Parameter(typeof(object), "arg1");
			ParameterInfo[] parameters = method.GetParameters();
			MethodCallExpression methodCallExpression = Expression.Call(method.IsStatic ? null : Expression.Convert(parameterExpression, method.DeclaringType), method, Expression.Convert(parameterExpression2, parameters[0].ParameterType), Expression.Convert(parameterExpression3, parameters[1].ParameterType));
			return Expression.Lambda<Func<object, object, object, object>>((method.ReturnType == typeof(void)) ? ((Expression)Expression.Block(methodCallExpression, Expression.Constant(null, typeof(object)))) : ((Expression)Expression.Convert(methodCallExpression, typeof(object))), new ParameterExpression[3] { parameterExpression, parameterExpression2, parameterExpression3 }).Compile();
		}

		private static Func<object?, object?, object?, object?, object?> BuildInvoke3(MethodInfo method)
		{
			ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "instance");
			ParameterExpression parameterExpression2 = Expression.Parameter(typeof(object), "arg0");
			ParameterExpression parameterExpression3 = Expression.Parameter(typeof(object), "arg1");
			ParameterExpression parameterExpression4 = Expression.Parameter(typeof(object), "arg2");
			ParameterInfo[] parameters = method.GetParameters();
			MethodCallExpression methodCallExpression = Expression.Call(method.IsStatic ? null : Expression.Convert(parameterExpression, method.DeclaringType), method, Expression.Convert(parameterExpression2, parameters[0].ParameterType), Expression.Convert(parameterExpression3, parameters[1].ParameterType), Expression.Convert(parameterExpression4, parameters[2].ParameterType));
			return Expression.Lambda<Func<object, object, object, object, object>>((method.ReturnType == typeof(void)) ? ((Expression)Expression.Block(methodCallExpression, Expression.Constant(null, typeof(object)))) : ((Expression)Expression.Convert(methodCallExpression, typeof(object))), new ParameterExpression[4] { parameterExpression, parameterExpression2, parameterExpression3, parameterExpression4 }).Compile();
		}

		private static Action<object?, object?, object?> BuildInvoke2Void(MethodInfo method)
		{
			ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "instance");
			ParameterExpression parameterExpression2 = Expression.Parameter(typeof(object), "arg0");
			ParameterExpression parameterExpression3 = Expression.Parameter(typeof(object), "arg1");
			ParameterInfo[] parameters = method.GetParameters();
			return Expression.Lambda<Action<object, object, object>>(Expression.Call(method.IsStatic ? null : Expression.Convert(parameterExpression, method.DeclaringType), method, Expression.Convert(parameterExpression2, parameters[0].ParameterType), Expression.Convert(parameterExpression3, parameters[1].ParameterType)), new ParameterExpression[3] { parameterExpression, parameterExpression2, parameterExpression3 }).Compile();
		}

		private static Action<object?, object?, object?, object?> BuildInvoke3Void(MethodInfo method)
		{
			ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "instance");
			ParameterExpression parameterExpression2 = Expression.Parameter(typeof(object), "arg0");
			ParameterExpression parameterExpression3 = Expression.Parameter(typeof(object), "arg1");
			ParameterExpression parameterExpression4 = Expression.Parameter(typeof(object), "arg2");
			ParameterInfo[] parameters = method.GetParameters();
			return Expression.Lambda<Action<object, object, object, object>>(Expression.Call(method.IsStatic ? null : Expression.Convert(parameterExpression, method.DeclaringType), method, Expression.Convert(parameterExpression2, parameters[0].ParameterType), Expression.Convert(parameterExpression3, parameters[1].ParameterType), Expression.Convert(parameterExpression4, parameters[2].ParameterType)), new ParameterExpression[4] { parameterExpression, parameterExpression2, parameterExpression3, parameterExpression4 }).Compile();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides Godot <see cref="T:Godot.FileAccess" /> operations with result objects, logging, and optional
	///         backup-and-replace writes.
	///     </para>
	///     <para xml:lang="zh-CN">提供带结果对象和日志记录的 Godot <see cref="T:Godot.FileAccess" /> 操作，并支持可选的备份替换写入。</para>
	/// </summary>
	public static class FileOperations
	{
		/// <summary>
		///     <para xml:lang="en">Represents the result of a file read operation.</para>
		///     <para xml:lang="zh-CN">表示文件读取操作的结果。</para>
		/// </summary>
		public record ReadResult
		{
			/// <summary>
			///     <para xml:lang="en">Indicates whether non-empty file content was read successfully.</para>
			///     <para xml:lang="zh-CN">指示是否成功读取到非空文件内容。</para>
			/// </summary>
			public bool Success { get; init; }

			/// <summary>
			///     <para xml:lang="en">File text when <see cref="P:STS2RitsuLib.Utils.FileOperations.ReadResult.Success" /> is true.</para>
			///     <para xml:lang="zh-CN"><see cref="P:STS2RitsuLib.Utils.FileOperations.ReadResult.Success" /> 为 true 时的文件文本。</para>
			/// </summary>
			public string? Content { get; init; }

			/// <summary>
			///     <para xml:lang="en">Godot error code for a low-level open or read failure.</para>
			///     <para xml:lang="zh-CN">底层打开或读取失败时的 Godot 错误码。</para>
			/// </summary>
			public Error? ErrorCode { get; init; }

			/// <summary>
			///     <para xml:lang="en">Human-readable failure reason when <see cref="P:STS2RitsuLib.Utils.FileOperations.ReadResult.Success" /> is false.</para>
			///     <para xml:lang="zh-CN"><see cref="P:STS2RitsuLib.Utils.FileOperations.ReadResult.Success" /> 为 false 时的可读失败原因。</para>
			/// </summary>
			public string? ErrorMessage { get; init; }

			/// <summary>
			///     <para xml:lang="en">Indicates whether content was recovered from the sibling <c>.backup</c> file.</para>
			///     <para xml:lang="zh-CN">指示内容是否从同级 <c>.backup</c> 文件恢复。</para>
			/// </summary>
			public bool LoadedFromBackup { get; init; }
		}

		/// <summary>
		///     <para xml:lang="en">Represents the result of a mutating file-system operation.</para>
		///     <para xml:lang="zh-CN">表示文件系统修改操作的结果。</para>
		/// </summary>
		public class WriteResult
		{
			/// <summary>
			///     <para xml:lang="en">
			///         Indicates whether the requested operation, including a no-op deletion of a missing target,
			///         completed successfully.
			///     </para>
			///     <para xml:lang="zh-CN">指示请求的操作是否成功完成；删除不存在的目标也视为空操作成功。</para>
			/// </summary>
			public bool Success { get; init; }

			/// <summary>
			///     <para xml:lang="en">Godot error code for a low-level operation failure.</para>
			///     <para xml:lang="zh-CN">底层操作失败时的 Godot 错误码。</para>
			/// </summary>
			public Error? ErrorCode { get; init; }

			/// <summary>
			///     <para xml:lang="en">Human-readable failure reason when <see cref="P:STS2RitsuLib.Utils.FileOperations.WriteResult.Success" /> is false.</para>
			///     <para xml:lang="zh-CN"><see cref="P:STS2RitsuLib.Utils.FileOperations.WriteResult.Success" /> 为 false 时的可读失败原因。</para>
			/// </summary>
			public string? ErrorMessage { get; init; }
		}

		/// <summary>
		///     <para xml:lang="en">Represents the result of a JSON deserialization operation.</para>
		///     <para xml:lang="zh-CN">表示 JSON 反序列化操作的结果。</para>
		/// </summary>
		public class JsonResult<T>
		{
			/// <summary>
			///     <para xml:lang="en">Indicates whether JSON was parsed into a non-null instance.</para>
			///     <para xml:lang="zh-CN">指示 JSON 是否被解析为非 null 实例。</para>
			/// </summary>
			public bool Success { get; init; }

			/// <summary>
			///     <para xml:lang="en">Deserialized object when <see cref="P:STS2RitsuLib.Utils.FileOperations.JsonResult`1.Success" /> is true.</para>
			///     <para xml:lang="zh-CN"><see cref="P:STS2RitsuLib.Utils.FileOperations.JsonResult`1.Success" /> 为 true 时的反序列化对象。</para>
			/// </summary>
			public T? Data { get; init; }

			/// <summary>
			///     <para xml:lang="en">Human-readable failure reason when <see cref="P:STS2RitsuLib.Utils.FileOperations.JsonResult`1.Success" /> is false.</para>
			///     <para xml:lang="zh-CN"><see cref="P:STS2RitsuLib.Utils.FileOperations.JsonResult`1.Success" /> 为 false 时的可读失败原因。</para>
			/// </summary>
			public string? ErrorMessage { get; init; }
		}

		private const string TempSuffix = ".tmp";

		private const string BackupSuffix = ".backup";

		/// <summary>
		///     <para xml:lang="en">Reads text from a file and reports detailed failures.</para>
		///     <para xml:lang="zh-CN">从文件读取文本并报告详细失败原因。</para>
		/// </summary>
		public static ReadResult ReadText(string filePath, string? logContext = null)
		{
			//IL_008f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0094: Unknown result type (might be due to invalid IL or missing references)
			//IL_00db: Unknown result type (might be due to invalid IL or missing references)
			//IL_0107: Unknown result type (might be due to invalid IL or missing references)
			//IL_012c: Unknown result type (might be due to invalid IL or missing references)
			string value = logContext ?? "FileOperations";
			try
			{
				if (!FileAccess.FileExists(filePath))
				{
					RitsuLibFramework.Logger.Debug($"[{value}] File not found at '{filePath}'", 1);
					return new ReadResult
					{
						Success = false,
						ErrorMessage = "File not found"
					};
				}
				FileAccess val = FileAccess.Open(filePath, (ModeFlags)1);
				try
				{
					if (val == null)
					{
						Error openError = FileAccess.GetOpenError();
						RitsuLibFramework.Logger.ErrorNoTrace($"[{value}] Failed to open file '{filePath}' (Error: {openError})");
						return new ReadResult
						{
							Success = false,
							ErrorCode = openError,
							ErrorMessage = $"Failed to open file (Error: {openError})"
						};
					}
					string asText = val.GetAsText(false);
					if (string.IsNullOrWhiteSpace(asText))
					{
						RitsuLibFramework.Logger.Warn($"[{value}] File '{filePath}' is empty", 1);
						return new ReadResult
						{
							Success = false,
							Content = asText,
							ErrorMessage = "File is empty"
						};
					}
					RitsuLibFramework.Logger.Debug($"[{value}] Successfully read file '{filePath}' ({asText.Length} characters)", 1);
					return new ReadResult
					{
						Success = true,
						Content = asText
					};
				}
				finally
				{
					((IDisposable)val)?.Dispose();
				}
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[{value}] Unexpected error reading file '{filePath}': {ex.Message}");
				return new ReadResult
				{
					Success = false,
					ErrorMessage = "Unexpected error: " + ex.Message
				};
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Writes text, optionally by rotating a backup, writing a temporary file, then renaming it into
		///         place.
		///     </para>
		///     <para xml:lang="zh-CN">写入文本；可选地轮换备份、写入临时文件，再将其重命名到目标位置。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         Despite the <paramref name="atomic" /> parameter name, this is a best-effort backup-and-replace
		///         sequence rather than a transactional atomic-write guarantee; each file-system step can fail independently.
		///     </para>
		///     <para xml:lang="zh-CN">尽管参数名为 <paramref name="atomic" />，该流程只是尽力完成的备份替换序列，并不保证事务式原子写入；每个文件系统步骤都可能独立失败。</para>
		/// </remarks>
		public static WriteResult WriteText(string filePath, string content, string? logContext = null, bool atomic = true)
		{
			string text = logContext ?? "FileOperations";
			if (!atomic)
			{
				return WriteTextDirect(filePath, content, text);
			}
			try
			{
				EnsureDirectoryExists(filePath);
				string text2 = filePath + ".tmp";
				string backupPath = filePath + ".backup";
				RotateBackup(filePath, backupPath, text);
				WriteResult writeResult = WriteTextDirect(text2, content, text);
				if (!writeResult.Success)
				{
					RestoreFromBackup(filePath, backupPath, text);
					return writeResult;
				}
				WriteResult writeResult2 = RenameFile(text2, filePath, text);
				if (!writeResult2.Success)
				{
					DeleteFileSilent(text2);
					RestoreFromBackup(filePath, backupPath, text);
					return new WriteResult
					{
						Success = false,
						ErrorMessage = "Failed to rename temp file: " + writeResult2.ErrorMessage
					};
				}
				RitsuLibFramework.Logger.Debug($"[{text}] Atomic write completed for '{filePath}'", 1);
				return new WriteResult
				{
					Success = true
				};
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[{text}] Unexpected error during atomic write to '{filePath}': {ex.Message}");
				return new WriteResult
				{
					Success = false,
					ErrorMessage = "Unexpected error: " + ex.Message
				};
			}
		}

