		/// <summary>
		///     <para xml:lang="en">Reads the backup file when reading the primary file fails.</para>
		///     <para xml:lang="zh-CN">读取主文件失败时读取备份文件。</para>
		/// </summary>
		public static ReadResult ReadTextWithBackupFallback(string filePath, string? logContext = null)
		{
			string text = logContext ?? "FileOperations";
			ReadResult readResult = ReadText(filePath, text);
			if (readResult.Success)
			{
				return readResult;
			}
			string text2 = filePath + ".backup";
			if (!FileAccess.FileExists(text2))
			{
				return readResult;
			}
			RitsuLibFramework.Logger.Info($"[{text}] Attempting to load from backup '{text2}'", 1);
			ReadResult readResult2 = ReadText(text2, text);
			if (!readResult2.Success)
			{
				return readResult2;
			}
			readResult2 = readResult2 with
			{
				LoadedFromBackup = true
			};
			RitsuLibFramework.Logger.Info("[" + text + "] Successfully loaded from backup", 1);
			return readResult2;
		}

		private static void DeleteFileSilent(string filePath)
		{
			//IL_001b: Unknown result type (might be due to invalid IL or missing references)
			try
			{
				if (!FileAccess.FileExists(filePath))
				{
					return;
				}
				DirAccess val = DirAccess.Open(GetDirectoryFromPath(filePath));
				try
				{
					if (val != null)
					{
						val.Remove(filePath);
					}
				}
				finally
				{
					((IDisposable)val)?.Dispose();
				}
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
			}
		}

		private static string GetDirectoryFromPath(string filePath)
		{
			int num = filePath.LastIndexOf('/');
			if (num < 0)
			{
				return "user://";
			}
			int num2 = filePath.IndexOf("://", StringComparison.Ordinal);
			if (num2 >= 0)
			{
				int num3 = num2 + 3;
				if (num >= num3)
				{
					return filePath.Substring(0, num);
				}
				return filePath.Substring(0, num3);
			}
			switch (num)
			{
			case 0:
				return "/";
			case 2:
				if (filePath.Length > 2 && filePath[1] == ':')
				{
					return filePath.Substring(0, 3);
				}
				break;
			}
			return filePath.Substring(0, num);
		}

		/// <summary>
		///     <para xml:lang="en">Ensures that the directory containing a file path exists.</para>
		///     <para xml:lang="zh-CN">确保包含文件路径的目录存在。</para>
		/// </summary>
		private static void EnsureDirectoryExists(string filePath)
		{
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_002f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			//IL_0064: Unknown result type (might be due to invalid IL or missing references)
			int num = filePath.LastIndexOf('/');
			if (num <= 0)
			{
				return;
			}
			string text = filePath.Substring(0, num);
			if (!string.IsNullOrEmpty(text) && !DirAccess.DirExistsAbsolute(text))
			{
				Error val = DirAccess.MakeDirRecursiveAbsolute(text);
				if ((int)val != 0)
				{
					RitsuLibFramework.Logger.Warn($"Failed to create directory '{text}' (Error: {val})", 1);
				}
			}
		}

