				if (val == null)
				{
					RitsuLibFramework.Logger.ErrorNoTrace($"[{text}] Deserialization resulted in null object for file '{filePath}'");
					return new JsonResult<T>
					{
						Success = false,
						ErrorMessage = "Deserialization resulted in null object"
					};
				}
				RitsuLibFramework.Logger.Debug($"[{text}] Successfully deserialized JSON from '{filePath}'", 1);
				return new JsonResult<T>
				{
					Success = true,
					Data = val
				};
			}
			catch (JsonException ex)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[{text}] JSON parsing error in file '{filePath}': {ex.Message}");
				return new JsonResult<T>
				{
					Success = false,
					ErrorMessage = "JSON parsing error: " + ex.Message
				};
			}
			catch (Exception ex2) when (RitsuLibExceptionPolicy.IsRecoverable(ex2))
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[{text}] Unexpected error deserializing file '{filePath}': {ex2.Message}");
				return new JsonResult<T>
				{
					Success = false,
					ErrorMessage = "Unexpected error: " + ex2.Message
				};
			}
		}

