		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to recursively delete a directory and its contents. Child cleanup continues after a
		///         failure, and the first failure is returned.
		///     </para>
		///     <para xml:lang="zh-CN">尝试递归删除目录及其内容。子项清理失败后会继续处理，并返回首个失败。</para>
		/// </summary>
		public static WriteResult DeleteDirectoryRecursive(string directoryPath, string? logContext = null)
		{
			//IL_0083: Unknown result type (might be due to invalid IL or missing references)
			//IL_0088: Unknown result type (might be due to invalid IL or missing references)
			//IL_00cf: Unknown result type (might be due to invalid IL or missing references)
			//IL_00fb: Unknown result type (might be due to invalid IL or missing references)
			//IL_0134: Unknown result type (might be due to invalid IL or missing references)
			//IL_03de: Unknown result type (might be due to invalid IL or missing references)
			//IL_03e3: Unknown result type (might be due to invalid IL or missing references)
			//IL_03e5: Unknown result type (might be due to invalid IL or missing references)
			//IL_02e3: Unknown result type (might be due to invalid IL or missing references)
			//IL_02e8: Unknown result type (might be due to invalid IL or missing references)
			//IL_034f: Unknown result type (might be due to invalid IL or missing references)
			//IL_037c: Unknown result type (might be due to invalid IL or missing references)
			//IL_03b5: Unknown result type (might be due to invalid IL or missing references)
			//IL_0431: Unknown result type (might be due to invalid IL or missing references)
			//IL_045e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0483: Unknown result type (might be due to invalid IL or missing references)
			string text = logContext ?? "FileOperations";
			try
			{
				if (!DirAccess.DirExistsAbsolute(directoryPath))
				{
					RitsuLibFramework.Logger.Debug($"[{text}] Directory '{directoryPath}' does not exist, nothing to delete", 1);
					return new WriteResult
					{
						Success = true
					};
				}
				DirAccess val = DirAccess.Open(directoryPath);
				try
				{
					if (val == null)
					{
						Error openError = DirAccess.GetOpenError();
						RitsuLibFramework.Logger.ErrorNoTrace($"[{text}] Failed to open directory '{directoryPath}' (Error: {openError})");
						return new WriteResult
						{
							Success = false,
							ErrorCode = openError,
							ErrorMessage = $"Failed to open directory '{directoryPath}' (Error: {openError})"
						};
					}
					WriteResult writeResult = null;
					string[] files = val.GetFiles();
					foreach (string text2 in files)
					{
						string text3 = directoryPath + "/" + text2;
						WriteResult writeResult2 = DeleteFile(text3, text);
						if (!writeResult2.Success)
						{
							RitsuLibFramework.Logger.Warn($"[{text}] Failed to delete file '{text3}': {writeResult2.ErrorMessage}", 1);
							if (writeResult == null)
							{
								writeResult = new WriteResult
								{
									Success = false,
									ErrorCode = writeResult2.ErrorCode,
									ErrorMessage = "Failed to delete child file '" + text3 + "': " + writeResult2.ErrorMessage
								};
							}
						}
					}
					files = val.GetDirectories();
					foreach (string text4 in files)
					{
						string text5 = directoryPath + "/" + text4;
						WriteResult writeResult3 = DeleteDirectoryRecursive(text5, text);
						if (!writeResult3.Success && writeResult == null)
						{
							writeResult = new WriteResult
							{
								Success = false,
								ErrorCode = writeResult3.ErrorCode,
								ErrorMessage = "Failed to delete child directory '" + text5 + "': " + writeResult3.ErrorMessage
							};
						}
					}
					if (writeResult != null)
					{
						return writeResult;
					}
					string directoryFromPath = GetDirectoryFromPath(directoryPath);
					DirAccess val2 = DirAccess.Open(directoryFromPath);
					try
					{
						if (val2 == null)
						{
							Error openError2 = DirAccess.GetOpenError();
							RitsuLibFramework.Logger.Warn($"[{text}] Failed to open parent directory '{directoryFromPath}' while deleting '{directoryPath}' (Error: {openError2})", 1);
							return new WriteResult
							{
								Success = false,
								ErrorCode = openError2,
								ErrorMessage = $"Failed to open parent directory '{directoryFromPath}' (Error: {openError2})"
							};
						}
						Error val3 = val2.Remove(directoryPath);
						if ((int)val3 != 0)
						{
							RitsuLibFramework.Logger.Warn($"[{text}] Failed to remove directory '{directoryPath}' (Error: {val3})", 1);
							return new WriteResult
							{
								Success = false,
								ErrorCode = val3,
								ErrorMessage = $"Failed to remove directory (Error: {val3})"
							};
						}
						RitsuLibFramework.Logger.Info($"[{text}] Successfully deleted directory '{directoryPath}'", 1);
						return new WriteResult
						{
							Success = true
						};
					}
					finally
					{
						((IDisposable)val2)?.Dispose();
					}
				}
				finally
				{
					((IDisposable)val)?.Dispose();
				}
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[{text}] Unexpected error deleting directory '{directoryPath}': {ex.Message}");
				return new WriteResult
				{
					Success = false,
					ErrorMessage = "Unexpected error: " + ex.Message
				};
			}
		}
