	/// <summary>
	///     <para xml:lang="en">
	///         Public helpers for Godot project paths: <c>res://</c>, <c>user://</c>, <c>uid://</c> remapping
	///         and resource presence checks aligned with <see cref="T:Godot.ResourceLoader" /> and <see cref="T:Godot.ResourceUid" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供 Godot 项目路径辅助方法，包括 <c>res://</c>、<c>user://</c>、<c>uid://</c> 重映射，以及与
	///         <see cref="T:Godot.ResourceLoader" /> 和 <see cref="T:Godot.ResourceUid" /> 一致的资源存在性检查。
	///     </para>
	/// </summary>
	public static class GodotResourcePath
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Yields paths the engine may use for the same logical asset: the trimmed input, <c>uid://</c> →
		///         <c>res://</c> (when applicable), and <see cref="M:Godot.ResourceUid.EnsurePath(System.String)" /> alternatives.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         生成引擎可能用于同一逻辑资源的路径：修剪后的输入、<c>uid://</c> → <c>res://</c>（适用时），以及
		///         <see cref="M:Godot.ResourceUid.EnsurePath(System.String)" /> 替代路径。
		///     </para>
		/// </summary>
		public static IEnumerable<string> EnumerateCandidatePaths(string? rawPath)
		{
			if (string.IsNullOrWhiteSpace(rawPath))
			{
				yield break;
			}
			foreach (string item in EnumerateEnginePathCandidates(rawPath.Trim()))
			{
				yield return item;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves <paramref name="pathOrUid" /> via <see cref="M:Godot.ResourceUid.EnsurePath(System.String)" /> (UID or path →
		///         project path). Returns <see langword="false" /> when the UID is unknown or resolution fails.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过 <see cref="M:Godot.ResourceUid.EnsurePath(System.String)" /> 将 <paramref name="pathOrUid" />（UID 或路径）解析为项目路径。UID
		///         未知或解析失败时返回 <see langword="false" />。
		///     </para>
		/// </summary>
		public static bool TryEnsurePath(string? pathOrUid, [NotNullWhen(true)] out string? path)
		{
			path = null;
			if (string.IsNullOrWhiteSpace(pathOrUid))
			{
				return false;
			}
			string text = ResourceUid.EnsurePath(pathOrUid.Trim());
			if (string.IsNullOrEmpty(text))
			{
				return false;
			}
			path = text;
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether <see cref="T:Godot.ResourceLoader" /> recognizes any normalized candidate path.
		///         <see cref="M:Godot.ResourceLoader.Exists(System.String,System.String)" /> checks cached and in-memory resources before
		///         the file system.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <see cref="T:Godot.ResourceLoader" /> 是否识别任一规范化候选路径。
		///         <see cref="M:Godot.ResourceLoader.Exists(System.String,System.String)" /> 会先检查缓存和内存资源，再检查文件系统。
		///     </para>
		/// </summary>
		public static bool ResourceExists(string? rawPath)
		{
			if (!string.IsNullOrWhiteSpace(rawPath))
			{
				return EnumerateCandidatePaths(rawPath).Any((string candidate) => ResourceLoader.Exists(candidate, ""));
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Loads the first resolvable candidate assignable to <typeparamref name="T" />. The resource is loaded
		///         without a type hint and then cast, allowing compatible concrete resource types that differ from a
		///         narrower request. Returns <see langword="false" /> without loading when <paramref name="rawPath" />
		///         is null or blank.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         加载第一个可解析且可赋值给 <typeparamref name="T" /> 的候选资源。该方法不带类型提示加载资源后再转型，
		///         因而允许具体资源类型与较窄请求不同但仍然兼容。<paramref name="rawPath" /> 为 null 或空白时不加载，
		///         并返回 <see langword="false" />。
		///     </para>
		/// </summary>
		public static bool TryLoad<T>(string? rawPath, [NotNullWhen(true)] out T? resource) where T : class
		{
			resource = null;
			if (string.IsNullOrWhiteSpace(rawPath))
			{
				return false;
			}
			foreach (string item in EnumerateCandidatePaths(rawPath))
			{
				if (ResourceLoader.Exists(item, "") && ResourceLoader.Load(item, "", (CacheMode)1) is T val)
				{
					resource = val;
					return true;
				}
			}
			return false;
		}

		private static IEnumerable<string> EnumerateEnginePathCandidates(string trimmed)
		{
			yield return trimmed;
			if (trimmed.StartsWith("uid://", StringComparison.OrdinalIgnoreCase))
			{
				string text = ResourceUid.UidToPath(trimmed);
				if (!string.IsNullOrEmpty(text) && !string.Equals(text, trimmed, StringComparison.Ordinal))
				{
					yield return text;
				}
			}
			else
			{
				string text2 = ResourceUid.EnsurePath(trimmed);
				if (!string.IsNullOrEmpty(text2) && !string.Equals(text2, trimmed, StringComparison.Ordinal))
				{
					yield return text2;
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Loads merged JSON translation dictionaries from the file system, embedded resources, and PCK
	///         paths, reacting to game locale changes when possible.
	///     </para>
	///     <para xml:lang="zh-CN">从文件系统、嵌入资源和 PCK 路径加载并合并 JSON 翻译字典，并在可行时响应游戏语言切换。</para>
	/// </summary>
	public class I18N : IDisposable, IEnumerable<KeyValuePair<string, string>>, IEnumerable
	{
		private sealed record LoadedTranslations(string? Language, Dictionary<string, string> Translations, HashSet<string> LocalKeys)
		{
			internal static LoadedTranslations Empty { get; } = new LoadedTranslations(null, new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase), new HashSet<string>(StringComparer.OrdinalIgnoreCase));
		}

		private readonly record struct LanguageLoadStep(string Language, bool IsPrimary);

		private readonly string? _fallbackLanguage;

		private readonly string[] _fsFolders;

		private readonly string _instanceName;

		private readonly string[] _pckFolders;

		private readonly Assembly _resourceAssembly;

		private readonly string[] _resourceFolders;

		private IReadOnlyList<string>? _availableLanguagesCache;

		private bool _disposed;

		private LoadedTranslations _loaded = LoadedTranslations.Empty;

		private bool _subscribed;

		internal bool IsDisposed => Volatile.Read(in _disposed);

		internal event Action<I18N>? Disposed;

		/// <summary>
		///     <para xml:lang="en">
		///         Raised after translations are reloaded, including explicit <see cref="M:STS2RitsuLib.Utils.I18N.ForceReload" /> calls,
		///         subscribed locale-change notifications, and lazily detected locale changes.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         翻译重新加载后触发，包括显式调用 <see cref="M:STS2RitsuLib.Utils.I18N.ForceReload" />、已订阅的语言变化通知，以及延迟检测到的语言变化。
		///     </para>
		/// </summary>
		public event Action? Changed;

		/// <summary>
		///     <para xml:lang="en">Creates an instance, optionally wiring locale change subscription when sources are configured.</para>
		///     <para xml:lang="zh-CN">创建实例；当配置了翻译来源时，可自动接入语言切换订阅。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         This overload falls back from non-English languages to <c>eng</c>, matching the game's
		///         <c>LocTable</c> fallback behavior.
		///     </para>
		///     <para xml:lang="zh-CN">此重载会让非英语语言回退到 <c>eng</c>，与游戏 <c>LocTable</c> 的回退行为一致。</para>
		/// </remarks>
		public I18N(string? instanceName = null, string[]? fsFolders = null, string[]? resourceFolders = null, string[]? pckFolders = null, Assembly? resourceAssembly = null)
			: this(instanceName, fsFolders, resourceFolders, pckFolders, resourceAssembly, null)
		{
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates an instance with an explicit fallback language when
		///         <paramref name="fallbackLanguage" /> is non-blank.
		///     </para>
		///     <para xml:lang="zh-CN">创建实例；<paramref name="fallbackLanguage" /> 非空白时将其用作显式回退语言。</para>
		/// </summary>
		public I18N(string? instanceName, string[]? fsFolders, string[]? resourceFolders, string[]? pckFolders, Assembly? resourceAssembly, string? fallbackLanguage)
		{
			_instanceName = instanceName ?? "I18N";
			_resourceFolders = resourceFolders?.Where((string f) => !string.IsNullOrWhiteSpace(f)).ToArray() ?? Array.Empty<string>();
			_fsFolders = fsFolders?.Where((string f) => !string.IsNullOrWhiteSpace(f)).ToArray() ?? Array.Empty<string>();
			_pckFolders = pckFolders?.Where((string f) => !string.IsNullOrWhiteSpace(f)).ToArray() ?? Array.Empty<string>();
			_resourceAssembly = resourceAssembly ?? Assembly.GetCallingAssembly();
			_fallbackLanguage = (string.IsNullOrWhiteSpace(fallbackLanguage) ? null : NormalizeLanguageCode(fallbackLanguage));
			if (_resourceFolders.Length == 0 && _fsFolders.Length == 0 && _pckFolders.Length == 0)
			{
				RitsuLibFramework.Logger.Warn("[" + _instanceName + "] Initialized with no translation sources", 1);
			}
			else
			{
				Initialize();
			}
		}

		/// <summary>
		///     <para xml:lang="en">Releases subscriptions and clears loaded translations.</para>
		///     <para xml:lang="zh-CN">释放订阅并清空已经加载的翻译。</para>
		/// </summary>
		public void Dispose()
		{
			if (!_disposed)
			{
				_disposed = true;
				Disposed?.Invoke(this);
				TryUnsubscribe();
				Volatile.Write(ref _loaded, LoadedTranslations.Empty);
				Disposed = null;
				Changed = null;
				RitsuLibFramework.Logger.Info("[" + _instanceName + "] Instance disposed and resources released", 1);
				GC.SuppressFinalize(this);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Enumerates the current merged translations as key-value pairs.</para>
		///     <para xml:lang="zh-CN">以键值对形式枚举当前已合并的翻译。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         Enumeration uses a snapshot copy to avoid collection-modified exceptions if a reload occurs
		///         during iteration.
		///     </para>
		///     <para xml:lang="zh-CN">枚举使用快照副本，避免迭代期间重新加载翻译造成集合已修改异常。</para>
		/// </remarks>
		public IEnumerator<KeyValuePair<string, string>> GetEnumerator()
		{
			ObjectDisposedException.ThrowIf(_disposed, this);
			return GetLoadedTranslations().Translations.ToArray().AsEnumerable().GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}

		/// <summary>
		///     <para xml:lang="en">Returns the translation for <paramref name="key" /> or <paramref name="fallback" /> if missing.</para>
		///     <para xml:lang="zh-CN">返回 <paramref name="key" /> 的翻译；缺失时返回 <paramref name="fallback" />。</para>
		/// </summary>
		public string Get(string key, string fallback)
		{
			ObjectDisposedException.ThrowIf(_disposed, this);
			return GetLoadedTranslations().Translations.GetValueOrDefault(key) ?? fallback;
		}

		/// <summary>
		///     <para xml:lang="en">Returns true and outputs the translation when <paramref name="key" /> exists.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="key" /> 存在时返回 true 并输出翻译。</para>
		/// </summary>
		public bool TryGet(string key, out string value)
		{
			ObjectDisposedException.ThrowIf(_disposed, this);
			return GetLoadedTranslations().Translations.TryGetValue(key, out value);
		}

		/// <summary>
		///     <para xml:lang="en">Returns true when <paramref name="key" /> exists in the current merged dictionary.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="key" /> 存在于当前合并字典中时返回 true。</para>
		/// </summary>
		public bool ContainsKey(string key)
		{
			ObjectDisposedException.ThrowIf(_disposed, this);
			return GetLoadedTranslations().Translations.ContainsKey(key);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns true when <paramref name="key" /> exists in the current language before fallback
		///         language entries are considered.
		///     </para>
		///     <para xml:lang="zh-CN">在考虑回退语言条目前，如果 <paramref name="key" /> 已存在于当前语言中，则返回 true。</para>
		/// </summary>
		public bool ContainsLocalKey(string key)
		{
			ObjectDisposedException.ThrowIf(_disposed, this);
			return GetLoadedTranslations().LocalKeys.Contains(key);
		}

		/// <summary>
		///     <para xml:lang="en">Returns a stable snapshot view of the current merged translations.</para>
		///     <para xml:lang="zh-CN">返回当前合并翻译的稳定快照视图。</para>
		/// </summary>
		public IReadOnlyDictionary<string, string> Snapshot()
		{
			ObjectDisposedException.ThrowIf(_disposed, this);
			return new ReadOnlyDictionary<string, string>(GetLoadedTranslations().Translations);
		}

		/// <summary>
		///     <para xml:lang="en">Enumerates translation keys in the current merged dictionary.</para>
		///     <para xml:lang="zh-CN">枚举当前合并字典中的翻译键。</para>
		/// </summary>
		/// <param name="prefix">
		///     <para xml:lang="en">
		///         When non-empty, limits results to keys beginning with this prefix using ordinal
		///         case-insensitive comparison.
		///     </para>
		///     <para xml:lang="zh-CN">非空时，仅返回以此输入前缀开头的键，比较时按序号忽略大小写。</para>
		/// </param>
		/// <param name="orderByKey">
		///     <para xml:lang="en">When true, keys are ordered with ordinal ignore case.</para>
		///     <para xml:lang="zh-CN">为 true 时，按键名以序号忽略大小写排序。</para>
		/// </param>
		public IEnumerable<string> EnumerateKeys(string? prefix = null, bool orderByKey = true)
		{
			ObjectDisposedException.ThrowIf(_disposed, this);
			IEnumerable<string> enumerable = GetLoadedTranslations().Translations.Keys;
			if (!string.IsNullOrWhiteSpace(prefix))
			{
				enumerable = enumerable.Where((string k) => k.StartsWith(prefix, StringComparison.OrdinalIgnoreCase));
			}
			if (!orderByKey)
			{
				return enumerable;
			}
			return enumerable.OrderBy<string, string>((string k) => k, StringComparer.OrdinalIgnoreCase);
		}

		/// <summary>
		///     <para xml:lang="en">Returns all keys from the current merged dictionary as a new list, optionally sorted.</para>
		///     <para xml:lang="zh-CN">将当前合并字典中的全部键作为新列表返回，并可选择排序。</para>
		/// </summary>
		public IReadOnlyList<string> GetAllKeys(bool orderByKey = true)
		{
			List<string> list = new List<string>();
			list.AddRange(EnumerateKeys(null, orderByKey));
			return new <>z__ReadOnlyList<string>(list);
		}

		/// <summary>
		///     <para xml:lang="en">Returns known language codes discoverable from configured sources.</para>
		///     <para xml:lang="zh-CN">返回可从已配置来源中发现的已知语言代码。</para>
		/// </summary>
		public IReadOnlyList<string> EnumerateAvailableLanguages(bool useCache = true)
		{
			ObjectDisposedException.ThrowIf(_disposed, this);
			if (useCache && _availableLanguagesCache != null)
			{
				return _availableLanguagesCache;
			}
			HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			string[] fsFolders = _fsFolders;
			for (int i = 0; i < fsFolders.Length; i++)
			{
				foreach (string item in EnumerateJsonLanguagesInFolder(fsFolders[i]))
				{
					hashSet.Add(item);
				}
			}
			fsFolders = _pckFolders;
			for (int i = 0; i < fsFolders.Length; i++)
			{
				foreach (string item2 in EnumerateJsonLanguagesInFolder(fsFolders[i]))
				{
					hashSet.Add(item2);
				}
			}
			fsFolders = _resourceFolders;
			foreach (string resourceFolder in fsFolders)
			{
				foreach (string item3 in EnumerateEmbeddedLanguages(resourceFolder))
				{
					hashSet.Add(item3);
				}
			}
			return _availableLanguagesCache = (from s in hashSet.Select(NormalizeLanguageCode)
				where !string.IsNullOrWhiteSpace(s)
				select s).Distinct<string>(StringComparer.OrdinalIgnoreCase).OrderBy<string, string>((string s) => s, StringComparer.OrdinalIgnoreCase).ToArray();
		}

		/// <summary>
		///     <para xml:lang="en">Reloads translations for the current resolved language and raises <see cref="E:STS2RitsuLib.Utils.I18N.Changed" />.</para>
		///     <para xml:lang="zh-CN">重新加载当前解析语言的翻译，并触发 <see cref="E:STS2RitsuLib.Utils.I18N.Changed" />。</para>
		/// </summary>
		public void ForceReload()
		{
			ObjectDisposedException.ThrowIf(_disposed, this);
			string text = ResolveLanguage();
			LoadedTranslations loadedTranslations = LoadTranslations(text);
			Volatile.Write(ref _loaded, loadedTranslations);
			_availableLanguagesCache = null;
			RitsuLibFramework.Logger.Debug($"[{_instanceName}] Successfully reloaded translations for language '{text}' ({loadedTranslations.Translations.Count} entries)", 1);
			BroadcastChange();
		}

		internal (Dictionary<string, string> Local, Dictionary<string, string> Fallback) CaptureLocTableData()
		{
			ObjectDisposedException.ThrowIf(_disposed, this);
			LoadedTranslations loadedTranslations = GetLoadedTranslations();
			Dictionary<string, string> dictionary = new Dictionary<string, string>(loadedTranslations.LocalKeys.Count, StringComparer.OrdinalIgnoreCase);
			Dictionary<string, string> dictionary2 = new Dictionary<string, string>(loadedTranslations.Translations.Count - loadedTranslations.LocalKeys.Count, StringComparer.OrdinalIgnoreCase);
			foreach (var (text3, value) in loadedTranslations.Translations)
			{
				if (loadedTranslations.LocalKeys.Contains(text3))
				{
					dictionary.Add(text3, value);
				}
				else
				{
					dictionary2.Add(text3, value);
				}
			}
			return (Local: dictionary, Fallback: dictionary2);
		}

		private void Initialize()
		{
			ObjectDisposedException.ThrowIf(_disposed, this);
			ForceReload();
			TrySubscribe();
		}

		private void TrySubscribe()
		{
			//IL_003d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0047: Expected O, but got Unknown
			if (_subscribed)
			{
				return;
			}
			try
			{
				LocManager instance = LocManager.Instance;
				if (instance == null)
				{
					RitsuLibFramework.Logger.Debug("[" + _instanceName + "] LocManager not available, will detect language changes lazily", 1);
					return;
				}
				instance.SubscribeToLocaleChange(new LocaleChangeCallback(OnLocaleChanged));
				_subscribed = true;
				RitsuLibFramework.Logger.Info("[" + _instanceName + "] Subscribed to locale change notifications", 1);
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[" + _instanceName + "] Unable to subscribe to locale changes, falling back to lazy detection: " + ex.Message, 1);
			}
		}

		private void TryUnsubscribe()
		{
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0027: Expected O, but got Unknown
			if (!_subscribed)
			{
				return;
			}
			try
			{
				LocManager instance = LocManager.Instance;
				if (instance != null)
				{
					instance.UnsubscribeToLocaleChange(new LocaleChangeCallback(OnLocaleChanged));
					_subscribed = false;
					RitsuLibFramework.Logger.Info("[" + _instanceName + "] Successfully unsubscribed from locale change notifications", 1);
				}
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.ErrorNoTrace("[" + _instanceName + "] Error during locale change unsubscription: " + ex.Message);
			}
		}

		private void BroadcastChange()
		{
			Changed?.Invoke();
		}

		private void OnLocaleChanged()
		{
			if (!_disposed)
			{
				string text = ResolveLanguage();
				RitsuLibFramework.Logger.Info("[" + _instanceName + "] Locale change detected, switching to language: " + text, 1);
				ForceReload();
			}
		}

		private LoadedTranslations GetLoadedTranslations()
		{
			EnsureLoaded();
			return Volatile.Read(in _loaded);
		}

		private void EnsureLoaded()
		{
			if (!_subscribed)
			{
				TrySubscribe();
			}
			string text = ResolveLanguage();
			if (!string.Equals(Volatile.Read(in _loaded).Language, text, StringComparison.OrdinalIgnoreCase))
			{
				LoadedTranslations loadedTranslations = LoadTranslations(text);
				Volatile.Write(ref _loaded, loadedTranslations);
				RitsuLibFramework.Logger.Debug($"[{_instanceName}] Successfully loaded translations for language '{text}' ({loadedTranslations.Translations.Count} entries)", 1);
				BroadcastChange();
			}
		}

		private LoadedTranslations LoadTranslations(string language)
		{
			Dictionary<string, string> merged = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
			HashSet<string> localKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			int num = 0;
			int primarySourceCount = 0;
			int fallbackSourceCount = 0;
			string text = null;
			foreach (LanguageLoadStep item in ResolveLanguageLoadSteps(language))
			{
				if (!item.IsPrimary)
				{
					text = item.Language;
				}
				string[] fsFolders = _fsFolders;
				for (int i = 0; i < fsFolders.Length; i++)
				{
					string text2 = fsFolders[i] + "/" + item.Language + ".json";
					Dictionary<string, string> dictionary = TryLoadFromFileSystem(text2);
					if (dictionary != null && dictionary.Count > 0)
					{
						int value = MergeTranslations(dictionary, item.IsPrimary);
						num++;
						CountSource(item.IsPrimary);
						RitsuLibFramework.Logger.Debug($"[{_instanceName}] Merged {DescribeLoadStep(item)} from FS: {text2} ({dictionary.Count} entries, {value} new)", 1);
					}
				}
				fsFolders = _resourceFolders;
				foreach (string text3 in fsFolders)
				{
					Dictionary<string, string> dictionary2 = TryLoadEmbedded(text3, item.Language);
					if (dictionary2 != null && dictionary2.Count > 0)
					{
						int value2 = MergeTranslations(dictionary2, item.IsPrimary);
						num++;
						CountSource(item.IsPrimary);
						RitsuLibFramework.Logger.Debug($"[{_instanceName}] Merged {DescribeLoadStep(item)} from embedded: {text3}.{item.Language}.json ({dictionary2.Count} entries, {value2} new)", 1);
					}
				}
				fsFolders = _pckFolders;
				for (int i = 0; i < fsFolders.Length; i++)
				{
					string text4 = fsFolders[i] + "/" + item.Language + ".json";
					Dictionary<string, string> dictionary3 = TryLoadFromPck(text4);
					if (dictionary3 != null && dictionary3.Count > 0)
					{
						int value3 = MergeTranslations(dictionary3, item.IsPrimary);
						num++;
						CountSource(item.IsPrimary);
						RitsuLibFramework.Logger.Debug($"[{_instanceName}] Merged {DescribeLoadStep(item)} from PCK: {text4} ({dictionary3.Count} entries, {value3} new)", 1);
					}
				}
			}
			if (merged.Count == 0)
			{
				RitsuLibFramework.Logger.Warn($"[{_instanceName}] No translations found for '{language}'", 1);
			}
			else
			{
				RitsuLibFramework.Logger.Info($"[{_instanceName}] Loaded translations: language='{NormalizeLanguageCode(language)}', fallback='{text ?? "<none>"}', entries={merged.Count}, local={localKeys.Count}, fallbackEntries={merged.Count - localKeys.Count}, sources={num} (local={primarySourceCount}, fallback={fallbackSourceCount})", 1);
			}
			return new LoadedTranslations(language, merged, localKeys);
			void CountSource(bool isPrimary)
			{
				if (isPrimary)
				{
					primarySourceCount++;
				}
				else
				{
					fallbackSourceCount++;
				}
			}
			int MergeTranslations(IReadOnlyDictionary<string, string> readOnlyDictionary, bool isPrimary)
			{
				int num2 = 0;
				foreach (KeyValuePair<string, string> item2 in readOnlyDictionary)
				{
					if (isPrimary)
					{
						localKeys.Add(item2.Key);
					}
					if (merged.TryAdd(item2.Key, item2.Value))
					{
						num2++;
					}
				}
				return num2;
			}
		}

		private IEnumerable<LanguageLoadStep> ResolveLanguageLoadSteps(string language)
		{
			string normalizedLanguage = NormalizeLanguageCode(language);
			yield return new LanguageLoadStep(normalizedLanguage, IsPrimary: true);
			string text = ResolveFallbackLanguage(normalizedLanguage);
			if (!string.IsNullOrWhiteSpace(text) && !string.Equals(normalizedLanguage, text, StringComparison.OrdinalIgnoreCase))
			{
				yield return new LanguageLoadStep(text, IsPrimary: false);
			}
		}

		private string? ResolveFallbackLanguage(string language)
		{
			if (_fallbackLanguage != null)
			{
				return _fallbackLanguage;
			}
			if (!string.Equals(language, "eng", StringComparison.OrdinalIgnoreCase))
			{
				return "eng";
			}
			return null;
		}

		private static string DescribeLoadStep(LanguageLoadStep step)
		{
			if (!step.IsPrimary)
			{
				return "fallback language '" + step.Language + "'";
			}
			return "current language";
		}

		private static IReadOnlyList<string> EnumerateJsonLanguagesInFolder(string folder)
		{
			if (string.IsNullOrWhiteSpace(folder))
			{
				return Array.Empty<string>();
			}
			List<string> list = new List<string>();
			try
			{
				DirAccess val = DirAccess.Open(folder);
				try
				{
					if (val == null)
					{
						return Array.Empty<string>();
					}
					list.AddRange(from file in val.GetFiles()
						where file.EndsWith(".json", StringComparison.OrdinalIgnoreCase)
						select file.Substring(0, file.Length - 5) into name
						where !string.IsNullOrWhiteSpace(name)
						select name);
					return list;
				}
				finally
				{
					((IDisposable)val)?.Dispose();
				}
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				return Array.Empty<string>();
			}
		}

		private IReadOnlyList<string> EnumerateEmbeddedLanguages(string resourceFolder)
		{
			if (string.IsNullOrWhiteSpace(resourceFolder))
			{
				return Array.Empty<string>();
			}
			string[] manifestResourceNames;
			try
			{
				manifestResourceNames = _resourceAssembly.GetManifestResourceNames();
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				return Array.Empty<string>();
			}
			string prefix = resourceFolder + ".";
			List<string> list = new List<string>();
			list.AddRange(from core in (from name in manifestResourceNames
					where name.StartsWith(prefix, StringComparison.Ordinal)
					where name.EndsWith(".json", StringComparison.OrdinalIgnoreCase)
					select name).Select(delegate(string name)
				{
					int length = prefix.Length;
					return name.Substring(length, name.Length - 5 - length);
				})
				let dot = core.IndexOf('.')
				where dot < 0
				where !string.IsNullOrWhiteSpace(core)
				select core);
			return new <>z__ReadOnlyList<string>(list);
		}

		private Dictionary<string, string>? TryLoadEmbedded(string resourceFolder, string language)
		{
			string text = resourceFolder + "." + language + ".json";
			try
			{
				using Stream stream = _resourceAssembly.GetManifestResourceStream(text);
				if (stream == null)
				{
					RitsuLibFramework.Logger.Debug($"[{_instanceName}] Embedded resource not found: '{text}' in assembly '{_resourceAssembly.GetName().Name}'", 1);
					return null;
				}
				Dictionary<string, string> dictionary = JsonSerializer.Deserialize<Dictionary<string, string>>(stream);
				if (dictionary != null)
				{
					return dictionary;
				}
				RitsuLibFramework.Logger.ErrorNoTrace($"[{_instanceName}] Deserialization resulted in null object for embedded resource '{text}'");
				return null;
			}
			catch (JsonException ex)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[{_instanceName}] JSON parsing error in embedded resource '{text}': {ex.Message}");
				return null;
			}
			catch (Exception ex2) when (RitsuLibExceptionPolicy.IsRecoverable(ex2))
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[{_instanceName}] Unexpected error loading embedded resource '{text}': {ex2.Message}");
				return null;
			}
		}

		private Dictionary<string, string>? TryLoadFromPck(string path)
		{
			FileOperations.JsonResult<Dictionary<string, string>> jsonResult = FileOperations.ReadJson<Dictionary<string, string>>(path, null, _instanceName);
			if (!jsonResult.Success || jsonResult.Data == null)
			{
				return null;
			}
			return jsonResult.Data;
		}

		private Dictionary<string, string>? TryLoadFromFileSystem(string path)
		{
			if (!FileOperations.FileExists(path))
			{
				RitsuLibFramework.Logger.Debug($"[{_instanceName}] FS file not found: '{path}'", 1);
				return null;
			}
			FileOperations.JsonResult<Dictionary<string, string>> jsonResult = FileOperations.ReadJson<Dictionary<string, string>>(path, null, _instanceName);
			if (!jsonResult.Success || jsonResult.Data == null)
			{
				return null;
			}
			return jsonResult.Data;
		}

		private static string ResolveLanguage()
		{
			return ResolveCurrentLanguageCode();
		}

		/// <summary>
		///     <para xml:lang="en">Resolves the current game locale to a normalized language code.</para>
		///     <para xml:lang="zh-CN">将当前游戏语言设置解析为规范化语言代码。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         Resolution tries <c>LocManager.Instance.Language</c> first, then
		///         <see cref="M:Godot.TranslationServer.GetLocale" />. The result is normalized by
		///         <see cref="M:STS2RitsuLib.Utils.I18N.NormalizeLanguageCode(System.String)" /> and falls back to <c>eng</c> when unavailable or blank.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         解析会先尝试 <c>LocManager.Instance.Language</c>，再尝试
		///         <see cref="M:Godot.TranslationServer.GetLocale" />。结果由 <see cref="M:STS2RitsuLib.Utils.I18N.NormalizeLanguageCode(System.String)" /> 规范化，
		///         无法取得或为空白时回退到 <c>eng</c>。
		///     </para>
		/// </remarks>
		public static string ResolveCurrentLanguageCode()
		{
			string text = null;
			try
			{
				LocManager instance = LocManager.Instance;
				text = ((instance != null) ? instance.Language : null);
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
			}
			if (!string.IsNullOrWhiteSpace(text))
			{
				return NormalizeLanguageCode(text);
			}
			try
			{
				text = TranslationServer.GetLocale();
			}
			catch (Exception exception2) when (RitsuLibExceptionPolicy.IsRecoverable(exception2))
			{
			}
			return NormalizeLanguageCode(text);
		}

		/// <summary>
		///     <para xml:lang="en">Normalizes a locale or language input to RitsuLib's stable language-code identifiers.</para>
		///     <para xml:lang="zh-CN">将区域设置或语言输入规范化为 RitsuLib 使用的稳定语言代码标识符。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         Examples include <c>zh-CN</c> to <c>zhs</c>, <c>en-US</c> to <c>eng</c>, and <c>ja-JP</c> to
		///         <c>jpn</c>. Unrecognized values are lower-cased with <c>-</c> replaced by <c>_</c>; null or
		///         whitespace values fall back to <c>eng</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         例如，<c>zh-CN</c> 会变为 <c>zhs</c>，<c>en-US</c> 会变为 <c>eng</c>，<c>ja-JP</c> 会变为
		///         <c>jpn</c>。无法识别的值会转为小写并将 <c>-</c> 替换为 <c>_</c>；null 或空白值会回退到
		///         <c>eng</c>。
		///     </para>
		/// </remarks>
		public static string NormalizeLanguageCode(string? language)
		{
			if (string.IsNullOrWhiteSpace(language))
			{
				return "eng";
			}
			string text = language.Trim().Replace('-', '_').ToLowerInvariant();
			switch (text)
			{
			case "zh_cn":
			case "zh_sg":
			case "zh":
			case "zh_hans":
				return "zhs";
			case "en_us":
			case "en_gb":
			case "en":
			case "eng":
				return "eng";
			case "ja_jp":
			case "ja":
			case "jpn":
				return "jpn";
			case "ko_kr":
			case "ko":
			case "kor":
				return "kor";
			case "de_de":
			case "de":
			case "deu":
				return "deu";
			case "es_es":
			case "es":
			case "esp":
				return "esp";
			case "fr_fr":
			case "fr":
			case "fra":
				return "fra";
			case "it_it":
			case "it":
			case "ita":
				return "ita";
			case "pl_pl":
			case "pl":
			case "pol":
				return "pol";
			case "pt_br":
			case "pt":
			case "ptb":
				return "ptb";
			case "ru_ru":
			case "ru":
			case "rus":
				return "rus";
			case "th_th":
			case "th":
			case "tha":
				return "tha";
			case "tr_tr":
			case "tr":
			case "tur":
				return "tur";
			default:
				return text;
			}
		}
	}
