		/// </summary>
		[Obsolete("Prefer MaterialUtils.CreateReplaceHueShaderMaterial instead.")]
		public static ShaderMaterial CreateRgbShaderMaterial(float r, float g, float b)
		{
			float num = Math.Max(r, Math.Max(g, b));
			float num2 = Math.Min(r, Math.Min(g, b));
			float num3 = num - num2;
			float h = 0f;
			if (num3 != 0f)
			{
				h = (Mathf.IsEqualApprox(num, r) ? ((g - b) / num3 + (float)((g < b) ? 6 : 0)) : ((!Mathf.IsEqualApprox(num, g)) ? ((r - g) / num3 + 4f) : ((b - r) / num3 + 2f)));
				h /= 6f;
			}
			float s = ((num == 0f) ? 0f : (num3 / num));
			return CreateHsvShaderMaterial(h, s, num);
		}

