	/// <summary>
	///     <para xml:lang="en">
	///         Per-mod facade for registering dynamic enum values without making the internal ID category
	///         segment public.
	///     </para>
	///     <para xml:lang="zh-CN">用于注册动态枚举值的逐模组门面，不向调用方公开内部 ID 类别段。</para>
	/// </summary>
	public sealed class ModDynamicEnumValueRegistry<TEnum> where TEnum : struct, Enum
	{
		/// <summary>
		///     <para xml:lang="en">Owning mod ID.</para>
		///     <para xml:lang="zh-CN">所属模组 ID。</para>
		/// </summary>
		public string ModId { get; }

		internal ModDynamicEnumValueRegistry(string modId)
		{
			ModId = modId;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a value owned by this registry's mod using the enum type's configured category
		///         segment.
		///     </para>
		///     <para xml:lang="zh-CN">使用该枚举类型配置的类别段注册归属此注册表模组的值。</para>
		/// </summary>
		public DynamicEnumValueDefinition<TEnum> RegisterOwned(string localStem)
		{
			return DynamicEnumValueRegistry<TEnum>.RegisterOwned(ModId, localStem);
		}

		/// <summary>
		///     <para xml:lang="en">Builds the canonical owned ID for <paramref name="localStem" />.</para>
		///     <para xml:lang="zh-CN">为 <paramref name="localStem" /> 构建规范的归属 ID。</para>
		/// </summary>
		public string GetOwnedId(string localStem)
		{
			return DynamicEnumValueRegistry<TEnum>.GetOwnedId(ModId, localStem);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns and records the deterministic value for the canonical owned ID without registering a
		///         definition.
		///     </para>
		///     <para xml:lang="zh-CN">返回并登记规范归属 ID 对应的确定性值，但不注册定义。</para>
		/// </summary>
		public TEnum GetOwnedValue(string localStem)
		{
			return DynamicEnumValueRegistry<TEnum>.GetValue(GetOwnedId(localStem));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the registered value for the canonical owned ID, or computes it without failing on hash
		///         collisions or adding a minter reverse lookup.
		///     </para>
		///     <para xml:lang="zh-CN">返回规范归属 ID 的已注册值；未注册时则直接计算，且不会因哈希碰撞而失败，也不会加入生成器的反向查找。</para>
		/// </summary>
		public TEnum GetOwnedValueIgnoringCollisions(string localStem)
		{
			return DynamicEnumValueRegistry<TEnum>.GetValueIgnoringCollisions(GetOwnedId(localStem));
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides helpers that convert ANSI terminal text into plain or segmented styled text.</para>
	///     <para xml:lang="zh-CN">提供将 ANSI 终端文本转换为纯文本或分段样式文本的辅助方法。</para>
	/// </summary>
	public static class RitsuAnsiText
	{
		private struct StyleState
		{
			public string? Color { get; set; }

			public bool Bold { get; set; }

			public bool Dim { get; set; }
		}

		private static readonly string[] NormalPalette = new string[8] { "#2f343f", "#c83d3d", "#1b8554", "#a66a00", "#266dcc", "#9b59b6", "#087a79", "#d7dee8" };

		private static readonly string[] BrightPalette = new string[8] { "#687587", "#ff7777", "#7cda95", "#edba60", "#75aaff", "#c792ea", "#62d3cb", "#ffffff" };

		/// <summary>
		///     <para xml:lang="en">Removes ANSI escape sequences from <paramref name="text" />, including CSI and OSC sequences.</para>
		///     <para xml:lang="zh-CN">移除 <paramref name="text" /> 中的 ANSI 转义序列，包括 CSI 和 OSC 序列。</para>
		/// </summary>
		public static string StripControlSequences(string text)
		{
			ArgumentNullException.ThrowIfNull(text, "text");
			if (text.IndexOf('\u001b') < 0)
			{
				return text;
			}
			StringBuilder stringBuilder = new StringBuilder(text.Length);
			int num = 0;
			while (num < text.Length)
			{
				if (text[num] != '\u001b')
				{
					stringBuilder.Append(text[num]);
					num++;
				}
				else
				{
					num = SkipEscapeSequence(text, num);
				}
			}
			return stringBuilder.ToString();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Parses supported ANSI SGR foreground colors plus bold and dim attributes into styled text
		///         segments.
		///     </para>
		///     <para xml:lang="zh-CN">将受支持的 ANSI SGR 前景色以及粗体和暗淡属性解析为带样式文本片段。</para>
		/// </summary>
		public static IReadOnlyList<RitsuTextSegment> ParseSegments(string text)
		{
			ArgumentNullException.ThrowIfNull(text, "text");
			if (!text.Contains('\u001b'))
			{
				if (!string.IsNullOrEmpty(text))
				{
					return new <>z__ReadOnlySingleElementList<RitsuTextSegment>(new RitsuTextSegment
					{
						Text = text
					});
				}
				return Array.Empty<RitsuTextSegment>();
			}
			List<RitsuTextSegment> list = new List<RitsuTextSegment>();
			StyleState state = default(StyleState);
			int num = 0;
			int num2 = 0;
			while (num < text.Length)
			{
				if (text[num] != '\u001b')
				{
					num++;
					continue;
				}
				int num3 = num2;
				AppendSegment(list, text.Substring(num3, num - num3), state);
				int num4 = num + 1;
				if (num4 >= text.Length)
				{
					num++;
					num2 = num;
					continue;
				}
				if (text[num4] != '[')
				{
					num = SkipEscapeSequence(text, num);
					num2 = num;
					continue;
				}
				int num5 = FindAnsiFinalByte(text, num4 + 1);
				if (num5 < 0)
				{
					num++;
					num2 = num;
					continue;
				}
				if (text[num5] == 'm')
				{
					num3 = num4 + 1;
					ApplySgrValues(text.Substring(num3, num5 - num3), ref state);
				}
				num = num5 + 1;
				num2 = num;
			}
			AppendSegment(list, text.Substring(num2), state);
			if (list.Count != 0)
			{
				return list;
			}
			return new List<RitsuTextSegment>();
		}

		private static void AppendSegment(List<RitsuTextSegment> segments, string text, StyleState state)
		{
			if (!string.IsNullOrEmpty(text))
			{
				object obj;
				if (segments.Count != 0)
				{
					obj = segments[segments.Count - 1];
				}
				else
				{
					obj = null;
				}
				RitsuTextSegment ritsuTextSegment = (RitsuTextSegment)obj;
				if (ritsuTextSegment != null && ritsuTextSegment.Color == state.Color && ritsuTextSegment.Bold == state.Bold && ritsuTextSegment.Dim == state.Dim && ritsuTextSegment.Kind == null)
				{
					segments[segments.Count - 1] = ritsuTextSegment with
					{
						Text = ritsuTextSegment.Text + text
					};
					return;
				}
				segments.Add(new RitsuTextSegment
				{
					Text = text,
					Color = state.Color,
					Bold = state.Bold,
					Dim = state.Dim
				});
			}
		}

		private static int SkipEscapeSequence(string text, int escapeIndex)
		{
			int num = escapeIndex + 1;
			if (num >= text.Length)
			{
				return num;
			}
			return text[num] switch
			{
				'[' => SkipAnsiCsi(text, num + 1), 
				']' => SkipAnsiOsc(text, num + 1), 
				_ => num + 1, 
			};
		}

		private static int SkipAnsiCsi(string text, int index)
		{
			while (index < text.Length)
			{
				char c = text[index++];
				if (c >= '@' && c <= '~')
				{
					break;
				}
			}
			return index;
		}

		private static int SkipAnsiOsc(string text, int index)
		{
			while (index < text.Length)
			{
				switch (text[index++])
				{
				case '\u001b':
					if (index >= text.Length || text[index] != '\\')
					{
						continue;
					}
					index++;
					break;
				default:
					continue;
				case '\a':
					break;
				}
				break;
			}
			return index;
		}

		private static int FindAnsiFinalByte(string text, int index)
		{
			while (index < text.Length)
			{
				char c = text[index];
				if (c >= '@' && c <= '~')
				{
					return index;
				}
				index++;
			}
			return -1;
		}

		private static void ApplySgrValues(string payload, ref StyleState state)
		{
			int[] array = (from value in payload.Split(';')
				select (value.Length != 0) ? ParseSgrNumber(value) : 0).ToArray();
			if (array.Length == 0 || array.Any((int value) => value < 0))
			{
				array = new int[1];
			}
			for (int num = 0; num < array.Length; num++)
			{
				int num2 = array[num];
				switch (num2)
				{
				case 0:
					state = default(StyleState);
					break;
				case 1:
					state.Bold = true;
					break;
				case 2:
					state.Dim = true;
					break;
				case 22:
					state.Bold = false;
					state.Dim = false;
					break;
				case 39:
					state.Color = null;
					break;
				case 30:
				case 31:
				case 32:
				case 33:
				case 34:
				case 35:
				case 36:
				case 37:
					state.Color = NormalPalette[num2 - 30];
					break;
				case 90:
				case 91:
				case 92:
				case 93:
				case 94:
				case 95:
				case 96:
				case 97:
					state.Color = BrightPalette[num2 - 90];
					break;
				case 38:
					if (num + 4 < array.Length && array[num + 1] == 2)
					{
						state.Color = $"rgb({ClampRgb(array[num + 2])}, {ClampRgb(array[num + 3])}, {ClampRgb(array[num + 4])})";
						num += 4;
					}
					break;
				}
			}
		}

		private static int ParseSgrNumber(string value)
		{
			if (!int.TryParse(value, out var result))
			{
				return -1;
			}
			return result;
		}

		private static int ClampRgb(int value)
		{
			return Math.Clamp(value, 0, 255);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides cancellable process-frame waits while validating the scene tree and an optional owner
	///         object.
	///     </para>
	///     <para xml:lang="zh-CN">提供可取消的处理帧等待，并验证场景树和可选所有者对象。</para>
	/// </summary>
	internal static class RitsuGodotAwaitSafety
	{
		internal readonly struct RitsuGodotSignalAwaitable(SignalAwaiter signalAwaiter)
		{
			internal SignalAwaiter GetAwaiter()
			{
				return signalAwaiter;
			}
		}

		internal static async Task AwaitProcessFrameAsync(SceneTree? tree, GodotObject? owner = null, CancellationToken ct = default(CancellationToken))
		{
			ct.ThrowIfCancellationRequested();
			ThrowIfInvalid(owner, ct);
			if (tree == null || !GodotObject.IsInstanceValid((GodotObject)(object)tree))
			{
				await Task.Yield();
				ct.ThrowIfCancellationRequested();
				ThrowIfInvalid(owner, ct);
				return;
			}
			await AwaitProcessFrameSignalAsync(tree).WaitAsync(ct);
			ct.ThrowIfCancellationRequested();
			ThrowIfInvalid(owner, ct);
			if (GodotObject.IsInstanceValid((GodotObject)(object)tree))
			{
				return;
			}
			throw new OperationCanceledException("Scene tree was deleted while awaiting a process frame.", ct);
		}

		private static async Task AwaitProcessFrameSignalAsync(SceneTree tree)
		{
			SignalAwaiter val = ((GodotObject)tree).ToSignal((GodotObject)(object)tree, SignalName.ProcessFrame).AsRitsuAwaitable().GetAwaiter();
			if (!val.IsCompleted)
			{
				await val;
				object obj = default(object);
				val = (SignalAwaiter)obj;
			}
			val.GetResult();
		}

		internal static async Task AwaitProcessFramesAsync(SceneTree? tree, int count, GodotObject? owner = null, CancellationToken ct = default(CancellationToken))
		{
			for (int i = 0; i < count; i++)
			{
				await AwaitProcessFrameAsync(tree, owner, ct);
			}
		}

		private static void ThrowIfInvalid(GodotObject? owner, CancellationToken ct)
		{
			if (owner != null && !GodotObject.IsInstanceValid(owner))
			{
				throw new OperationCanceledException("Godot owner was deleted while awaiting a callback.", ct);
			}
		}

		internal static RitsuGodotSignalAwaitable AsRitsuAwaitable(this SignalAwaiter signalAwaiter)
		{
			return new RitsuGodotSignalAwaitable(signalAwaiter);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Dispatches work to the Godot main thread when a scene tree is available.</para>
	///     <para xml:lang="zh-CN">在场景树可用时将工作调度到 Godot 主线程。</para>
	/// </summary>
	internal static class RitsuMainThread
	{
		internal static Task InvokeAsync(Action action, CancellationToken cancellationToken = default(CancellationToken))
		{
			//IL_007e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0083: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(action, "action");
			if (NGame.IsMainThread())
			{
				action();
				return Task.CompletedTask;
			}
			MainLoop mainLoop = Engine.GetMainLoop();
			MainLoop obj = ((mainLoop is SceneTree) ? mainLoop : null);
			if (((obj != null) ? ((SceneTree)obj).Root : null) == null)
			{
				action();
				return Task.CompletedTask;
			}
			TaskCompletionSource source = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
			Callable val = Callable.From((Action)delegate
			{
				try
				{
					if (cancellationToken.IsCancellationRequested)
					{
						source.TrySetCanceled(cancellationToken);
					}
					else
					{
						action();
						source.TrySetResult();
					}
				}
				catch (Exception exception)
				{
					source.TrySetException(exception);
				}
			});
			((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			if (!cancellationToken.CanBeCanceled)
			{
				return source.Task;
			}
			return source.Task.WaitAsync(cancellationToken);
		}

		internal static Task<T> InvokeAsync<T>(Func<T> action, CancellationToken cancellationToken = default(CancellationToken))
		{
			//IL_007e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0083: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(action, "action");
			if (NGame.IsMainThread())
			{
				return Task.FromResult(action());
			}
			MainLoop mainLoop = Engine.GetMainLoop();
			MainLoop obj = ((mainLoop is SceneTree) ? mainLoop : null);
			if (((obj != null) ? ((SceneTree)obj).Root : null) == null)
			{
				return Task.FromResult(action());
			}
			TaskCompletionSource<T> source = new TaskCompletionSource<T>(TaskCreationOptions.RunContinuationsAsynchronously);
			Callable val = Callable.From((Action)delegate
			{
				try
				{
					if (cancellationToken.IsCancellationRequested)
					{
						source.TrySetCanceled(cancellationToken);
					}
					else
					{
						source.TrySetResult(action());
					}
				}
				catch (Exception exception)
				{
					source.TrySetException(exception);
				}
			});
			((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			if (!cancellationToken.CanBeCanceled)
			{
				return source.Task;
			}
			return source.Task.WaitAsync(cancellationToken);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Represents a styled text span for UI code that renders rich diagnostic text.</para>
	///     <para xml:lang="zh-CN">表示供界面代码渲染富格式诊断文本的带样式文本片段。</para>
	/// </summary>
	public sealed record RitsuTextSegment
	{
		/// <summary>
