	/// <summary>
	///     <para xml:lang="en">
	///         Stores mod-attached state on arbitrary reference objects and bridges it through
	///         <see cref="T:MegaCrit.Sts2.Core.Saves.Runs.SavedProperties" /> for models that participate in vanilla save serialization.
	///     </para>
	///     <para xml:lang="zh-CN">在任意引用对象上存储模组附加状态，并通过 <see cref="T:MegaCrit.Sts2.Core.Saves.Runs.SavedProperties" /> 接入参与原版存档序列化的模型。</para>
	/// </summary>
	public sealed class SavedAttachedState<TKey, TValue> where TKey : class
	{
		private sealed class Box(TValue value)
		{
			public TValue Value { get; } = value;
		}

		private sealed class SavedAttachedStateRegistration<TSavedKey, TSavedValue>(string name, int order, SavedAttachedState<TSavedKey, TSavedValue> owner) : ISavedAttachedState where TSavedKey : class
		{
			public string Name { get; } = name;

			public int Order { get; } = order;

			public Type TargetType { get; } = typeof(TSavedKey);

			public bool Export(object model, SavedProperties props)
			{
				return SavedAttachedStateRegistry.AddToProperties(props, Name, owner.GetOrCreate((TSavedKey)model));
			}

			public void Import(object model, SavedProperties props)
			{
				if (SavedAttachedStateRegistry.TryGetFromProperties<TSavedValue>(props, Name, out TSavedValue value))
				{
					owner.Set((TSavedKey)model, value);
				}
			}
		}

		private readonly ConditionalWeakTable<TKey, Box> _table = new ConditionalWeakTable<TKey, Box>();

		private readonly Func<TKey, TValue> _valueFactory;

		/// <summary>
		///     <para xml:lang="en">Gets or sets the attached value for <paramref name="key" />.</para>
		///     <para xml:lang="zh-CN">获取或设置 <paramref name="key" /> 的附加值。</para>
		/// </summary>
		public TValue this[TKey key]
		{
			get
			{
				return GetOrCreate(key);
			}
			set
			{
				Set(key, value);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Creates persisted attached state using an optional parameterless factory for default values.</para>
		///     <para xml:lang="zh-CN">使用可选的无参工厂创建具有默认值的持久化附加状态。</para>
		/// </summary>
		public SavedAttachedState(string name, Func<TValue>? defaultValueFactory = null, int order = 0)
			: this(name, (Func<TKey, TValue>?)((TKey _) => (defaultValueFactory == null) ? default(TValue) : defaultValueFactory()), order)
