		/// <summary>
		///     <para xml:lang="en">
		///         Positive relative weight used by <c>WeightedList&lt;T&gt;</c> when no explicit weight is
		///         provided.
		///     </para>
		///     <para xml:lang="zh-CN">未提供显式权重时，<c>WeightedList&lt;T&gt;</c> 使用的正相对权重。</para>
		/// </summary>
		int Weight { get; }
	}
	/// <summary>
	///     <para xml:lang="en">Weighted random container with optional draw-without-replacement support.</para>
	///     <para xml:lang="zh-CN">支持可选不放回抽取的加权随机容器。</para>
	/// </summary>
	public class WeightedList<T> : IList<T>, ICollection<T>, IEnumerable<T>, IEnumerable
	{
		private readonly record struct Entry(T Value, int Weight);

		private readonly List<Entry> _entries = new List<Entry>();

		/// <summary>
		///     <para xml:lang="en">Sum of all entry weights, or zero when empty.</para>
		///     <para xml:lang="zh-CN">所有条目权重之和；为空时为零。</para>
		/// </summary>
		public int TotalWeight { get; private set; }

		/// <inheritdoc />
		public bool IsReadOnly => false;

		/// <inheritdoc />
		public int Count => _entries.Count;

		/// <inheritdoc />
		public T this[int index]
		{
			get
			{
				return _entries[index].Value;
			}
			set
			{
				_entries[index] = new Entry(value, _entries[index].Weight);
			}
		}

		/// <inheritdoc />
		public void Add(T item)
		{
			Add(item, (!(item is IWeightedValue weightedValue)) ? 1 : weightedValue.Weight);
		}

		/// <inheritdoc />
		public void Clear()
		{
			_entries.Clear();
			TotalWeight = 0;
		}

		/// <inheritdoc />
		public bool Contains(T item)
		{
			return _entries.Any((Entry entry) => EqualityComparer<T>.Default.Equals(entry.Value, item));
		}

		/// <inheritdoc />
		public void CopyTo(T[] array, int arrayIndex)
		{
			_entries.Select((Entry entry) => entry.Value).ToList().CopyTo(array, arrayIndex);
		}

		/// <inheritdoc />
		public IEnumerator<T> GetEnumerator()
		{
			return _entries.Select((Entry entry) => entry.Value).GetEnumerator();
		}

		/// <inheritdoc />
		public int IndexOf(T item)
		{
			for (int i = 0; i < _entries.Count; i++)
			{
				if (EqualityComparer<T>.Default.Equals(_entries[i].Value, item))
				{
					return i;
				}
			}
			return -1;
		}

		/// <inheritdoc />
		public void Insert(int index, T item)
		{
			Insert(index, item, (!(item is IWeightedValue weightedValue)) ? 1 : weightedValue.Weight);
		}

		/// <inheritdoc />
		public bool Remove(T item)
		{
			int num = IndexOf(item);
			if (num < 0)
			{
				return false;
			}
			RemoveAt(num);
			return true;
		}

		/// <inheritdoc />
		public void RemoveAt(int index)
		{
			Entry entry = _entries[index];
			_entries.RemoveAt(index);
			TotalWeight -= entry.Weight;
		}

		/// <inheritdoc />
		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}

		/// <summary>
		///     <para xml:lang="en">Appends <paramref name="item" /> with an explicit positive <paramref name="weight" />.</para>
		///     <para xml:lang="zh-CN">以显式的正权重 <paramref name="weight" /> 追加 <paramref name="item" />。</para>
		/// </summary>
		/// <exception cref="T:System.OverflowException">
		///     <para xml:lang="en">The resulting total weight exceeds <see cref="F:System.Int32.MaxValue" />.</para>
		///     <para xml:lang="zh-CN">相加后的总权重超过 <see cref="F:System.Int32.MaxValue" />。</para>
		/// </exception>
		public void Add(T item, int weight)
		{
			ArgumentOutOfRangeException.ThrowIfNegativeOrZero(weight, "weight");
			int totalWeight = checked(TotalWeight + weight);
			_entries.Add(new Entry(item, weight));
			TotalWeight = totalWeight;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends each item using <paramref name="weightSelector" />, <see cref="T:STS2RitsuLib.Utils.IWeightedValue" />, or
		///         weight 1.
		///     </para>
		///     <para xml:lang="zh-CN">使用 <paramref name="weightSelector" />、<see cref="T:STS2RitsuLib.Utils.IWeightedValue" /> 或权重 1 追加每一项。</para>
		/// </summary>
		public void AddRange(IEnumerable<T> items, Func<T, int>? weightSelector = null)
		{
			ArgumentNullException.ThrowIfNull(items, "items");
			foreach (T item in items)
			{
				Add(item, weightSelector?.Invoke(item) ?? ((!(item is IWeightedValue weightedValue)) ? 1 : weightedValue.Weight));
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Rolls a weighted random entry using <paramref name="rng" />, optionally removing the chosen
		///         entry.
		///     </para>
		///     <para xml:lang="zh-CN">使用 <paramref name="rng" /> 抽取加权随机条目，并可移除选中的条目。</para>
		/// </summary>
		public T GetRandom(Rng rng, bool remove = false)
		{
			ArgumentNullException.ThrowIfNull(rng, "rng");
			if (_entries.Count == 0 || TotalWeight <= 0)
			{
				throw new InvalidOperationException("Cannot roll from an empty weighted list.");
			}
			int num = rng.NextInt(TotalWeight);
			int num2 = 0;
			for (int i = 0; i < _entries.Count; i++)
			{
				Entry entry = _entries[i];
				num2 += entry.Weight;
				if (num < num2)
				{
					if (remove)
					{
						RemoveAt(i);
					}
					return entry.Value;
				}
			}
			throw new InvalidOperationException($"Weighted roll {num} exceeded total weight {TotalWeight}.");
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns <see langword="false" /> when the list is empty or has non-positive total weight;
		///         otherwise performs a weighted roll like <c>GetRandom</c>.
		///     </para>
		///     <para xml:lang="zh-CN">列表为空或总权重非正时返回 <see langword="false" />；否则执行一次类似 <c>GetRandom</c> 的加权抽取。</para>
		/// </summary>
		public bool TryGetRandom(Rng rng, out T value, bool remove = false)
		{
			if (_entries.Count == 0 || TotalWeight <= 0)
			{
				value = default(T);
				return false;
			}
			value = GetRandom(rng, remove);
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Inserts <paramref name="item" /> at <paramref name="index" /> with explicit positive
		///         <paramref name="weight" />.
		///     </para>
		///     <para xml:lang="zh-CN">以显式的正权重 <paramref name="weight" /> 将 <paramref name="item" /> 插入到 <paramref name="index" />。</para>
		/// </summary>
		/// <exception cref="T:System.OverflowException">
		///     <para xml:lang="en">The resulting total weight exceeds <see cref="F:System.Int32.MaxValue" />.</para>
		///     <para xml:lang="zh-CN">相加后的总权重超过 <see cref="F:System.Int32.MaxValue" />。</para>
		/// </exception>
		public void Insert(int index, T item, int weight)
		{
			ArgumentOutOfRangeException.ThrowIfNegativeOrZero(weight, "weight");
			if ((uint)index > (uint)_entries.Count)
			{
				throw new ArgumentOutOfRangeException("index");
			}
			int totalWeight = checked(TotalWeight + weight);
			_entries.Insert(index, new Entry(item, weight));
			TotalWeight = totalWeight;
		}
	}
}
namespace STS2RitsuLib.Utils.Speculation
{
	/// <summary>
	///     <para xml:lang="en">Severity of a speculative-execution diagnostic.</para>
	///     <para xml:lang="zh-CN">推演执行诊断的严重程度。</para>
	/// </summary>
	public enum SpeculativeDiagnosticSeverity
	{
		/// <summary>
		///     <para xml:lang="en">Informational execution detail.</para>
		///     <para xml:lang="zh-CN">信息性执行详情。</para>
		/// </summary>
		Information,
		/// <summary>
		///     <para xml:lang="en">Recoverable condition that may reduce precision.</para>
		///     <para xml:lang="zh-CN">可能降低精度的可恢复状况。</para>
		/// </summary>
		Warning,
		/// <summary>
		///     <para xml:lang="en">Condition that makes the result incomplete.</para>
		///     <para xml:lang="zh-CN">导致结果不完整的错误状况。</para>
		/// </summary>
		Error
	}
	/// <summary>
	///     <para xml:lang="en">Limits applied to one speculative execution.</para>
	///     <para xml:lang="zh-CN">单次推演执行使用的限制。</para>
	/// </summary>
	public sealed record SpeculativeExecutionBudget
	{
		/// <summary>
		///     <para xml:lang="en">Maximum number of accounted operations.</para>
		///     <para xml:lang="zh-CN">允许计入的最大操作数量。</para>
		/// </summary>
		public int MaxOperations { get; init; } = 100000;

		/// <summary>
		///     <para xml:lang="en">Maximum nested execution-frame depth.</para>
		///     <para xml:lang="zh-CN">允许嵌套的最大执行帧深度。</para>
		/// </summary>
		public int MaxDepth { get; init; } = 128;
	}
	/// <summary>
	///     <para xml:lang="en">One diagnostic emitted during speculative execution.</para>
	///     <para xml:lang="zh-CN">推演执行期间产生的一条诊断。</para>
	/// </summary>
	public sealed record SpeculativeDiagnostic(SpeculativeDiagnosticSeverity Severity, string Code, string Message, MethodBase? Method = null, int? InstructionIndex = null);
	/// <summary>
	///     <para xml:lang="en">One ordered terminal effect recorded by a speculative execution.</para>
	///     <para xml:lang="zh-CN">推演执行记录的一条有序终端效果。</para>
	/// </summary>
	public sealed record SpeculativeEffect(int Sequence, string Kind, object? Source, object? Payload);
	/// <summary>
	///     <para xml:lang="en">
	///         Async-flowing execution context with a shadow-state overlay, ordered effect journal, and
	///         explicit operation and frame-depth budgets.
	///     </para>
	///     <para xml:lang="zh-CN">随异步流传播的执行上下文，包含影子状态覆盖、有序效果日志，以及显式的操作和执行帧深度预算。</para>
	/// </summary>
	public sealed class SpeculativeExecutionSession
	{
		private sealed record AmbientNode(SpeculativeExecutionSession Session, AmbientNode? Previous);

		private readonly record struct StateKey(object Target, object Slot);

		private sealed class StateKeyComparer : IEqualityComparer<StateKey>
		{
			public static StateKeyComparer Instance { get; } = new StateKeyComparer();

			public bool Equals(StateKey x, StateKey y)
			{
				if (x.Target == y.Target)
				{
					return object.Equals(x.Slot, y.Slot);
				}
				return false;
			}

			public int GetHashCode(StateKey obj)
			{
				return HashCode.Combine(RuntimeHelpers.GetHashCode(obj.Target), obj.Slot);
			}
		}

		private sealed class ScopeLease(Action? dispose) : IDisposable
		{
			private Action? _dispose = dispose;

			public static ScopeLease Empty { get; } = new ScopeLease(null);

			public void Dispose()
			{
				Interlocked.Exchange(ref _dispose, null)?.Invoke();
			}
		}

		private static readonly AsyncLocal<AmbientNode?> Ambient = new AsyncLocal<AmbientNode>();

		private readonly List<SpeculativeDiagnostic> _diagnostics = new List<SpeculativeDiagnostic>();

		private readonly List<SpeculativeEffect> _effects = new List<SpeculativeEffect>();

		private readonly Stack<object?> _sources = new Stack<object>();

		private readonly Dictionary<StateKey, object?> _state = new Dictionary<StateKey, object>(StateKeyComparer.Instance);

		private int _depth;

		private bool _depthBudgetReported;

		private bool _operationBudgetReported;

		/// <summary>
		///     <para xml:lang="en">Session currently active in this async control flow, if any.</para>
		///     <para xml:lang="zh-CN">当前异步控制流中处于活动状态的会话；没有时为 null。</para>
		/// </summary>
		public static SpeculativeExecutionSession? Current => Ambient.Value?.Session;

		/// <summary>
		///     <para xml:lang="en">Limits applied to this session.</para>
		///     <para xml:lang="zh-CN">此会话使用的限制。</para>
		/// </summary>
		public SpeculativeExecutionBudget Budget { get; }

		/// <summary>
		///     <para xml:lang="en">Ordered effects recorded by this session.</para>
		///     <para xml:lang="zh-CN">此会话记录的有序效果。</para>
		/// </summary>
		public IReadOnlyList<SpeculativeEffect> Effects => _effects;

		/// <summary>
		///     <para xml:lang="en">Diagnostics recorded by this session.</para>
		///     <para xml:lang="zh-CN">此会话记录的诊断。</para>
		/// </summary>
		public IReadOnlyList<SpeculativeDiagnostic> Diagnostics => _diagnostics;

		/// <summary>
		///     <para xml:lang="en">Number of operations consumed so far.</para>
		///     <para xml:lang="zh-CN">当前已消耗的操作数量。</para>
		/// </summary>
		public int Operations { get; private set; }

		/// <summary>
		///     <para xml:lang="en">True when no error diagnostic was recorded.</para>
		///     <para xml:lang="zh-CN">未记录错误诊断时为 true。</para>
		/// </summary>
		public bool IsComplete => _diagnostics.All((SpeculativeDiagnostic diagnostic) => diagnostic.Severity != SpeculativeDiagnosticSeverity.Error);

		/// <summary>
		///     <para xml:lang="en">Creates an isolated speculative-execution session.</para>
		///     <para xml:lang="zh-CN">创建一个独立的推演执行会话。</para>
		/// </summary>
		public SpeculativeExecutionSession(SpeculativeExecutionBudget? budget = null)
		{
			Budget = budget ?? new SpeculativeExecutionBudget();
			ArgumentOutOfRangeException.ThrowIfLessThan(Budget.MaxOperations, 1, "Budget.MaxOperations");
			ArgumentOutOfRangeException.ThrowIfLessThan(Budget.MaxDepth, 1, "Budget.MaxDepth");
		}

		/// <summary>
		///     <para xml:lang="en">Makes this session current until the returned scope is disposed.</para>
		///     <para xml:lang="zh-CN">在返回的作用域释放前将此会话设为当前会话。</para>
		/// </summary>
		public IDisposable Enter()
		{
			AmbientNode previous = Ambient.Value;
			AmbientNode node = new AmbientNode(this, previous);
			Ambient.Value = node;
			return new ScopeLease(delegate
			{
				if ((object)Ambient.Value != node)
				{
					throw new InvalidOperationException("Speculative execution scopes must be disposed in reverse order.");
				}
				Ambient.Value = previous;
			});
		}

		/// <summary>
		///     <para xml:lang="en">Attempts to enter one nested execution frame.</para>
		///     <para xml:lang="zh-CN">尝试进入一个嵌套执行帧。</para>
		/// </summary>
		/// <param name="method">
		///     <para xml:lang="en">Method represented by the frame, when known.</para>
		///     <para xml:lang="zh-CN">此执行帧所表示的方法（如已知）。</para>
		/// </param>
		/// <param name="scope">
		///     <para xml:lang="en">Scope that leaves the frame when disposed.</para>
		///     <para xml:lang="zh-CN">释放时离开执行帧的作用域。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">True when both operation and depth budgets permit the frame.</para>
		///     <para xml:lang="zh-CN">操作预算与深度预算均允许此执行帧时为 true。</para>
		/// </returns>
		public bool TryEnterFrame(MethodBase? method, out IDisposable scope)
		{
			if (!TryConsumeOperation(method))
			{
				scope = ScopeLease.Empty;
				return false;
			}
			if (_depth >= Budget.MaxDepth)
			{
				if (!_depthBudgetReported)
				{
					_depthBudgetReported = true;
					AddDiagnostic(new SpeculativeDiagnostic(SpeculativeDiagnosticSeverity.Error, "depth_budget_exceeded", $"Execution depth budget {Budget.MaxDepth} was exceeded.", method));
				}
				scope = ScopeLease.Empty;
				return false;
			}
			_depth++;
			scope = new ScopeLease(delegate
			{
				_depth--;
			});
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Accounts one operation and reports whether execution may continue.</para>
		///     <para xml:lang="zh-CN">计入一个操作并报告执行是否可以继续。</para>
		/// </summary>
		public bool TryConsumeOperation(MethodBase? method = null, int? instructionIndex = null)
		{
			if (Operations >= Budget.MaxOperations)
			{
				if (_operationBudgetReported)
				{
					return false;
				}
				_operationBudgetReported = true;
				AddDiagnostic(new SpeculativeDiagnostic(SpeculativeDiagnosticSeverity.Error, "operation_budget_exceeded", $"Operation budget {Budget.MaxOperations} was exceeded.", method, instructionIndex));
				return false;
			}
			Operations++;
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Pushes a causal source used by effects that do not supply an explicit source.</para>
		///     <para xml:lang="zh-CN">压入因果来源，供未显式指定来源的效果使用。</para>
		/// </summary>
		public IDisposable PushSource(object? source)
		{
			_sources.Push(source);
			return new ScopeLease(delegate
			{
				_sources.Pop();
			});
		}

		/// <summary>
		///     <para xml:lang="en">Appends one terminal effect to the ordered journal.</para>
		///     <para xml:lang="zh-CN">向有序日志追加一条终端效果。</para>
		/// </summary>
		public SpeculativeEffect RecordEffect(string kind, object? payload = null, object? source = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(kind, "kind");
			SpeculativeEffect speculativeEffect = new SpeculativeEffect(_effects.Count, kind, source ?? (_sources.TryPeek(out object result) ? result : null), payload);
			_effects.Add(speculativeEffect);
			return speculativeEffect;
		}

		/// <summary>
		///     <para xml:lang="en">Appends a diagnostic.</para>
		///     <para xml:lang="zh-CN">追加一条诊断。</para>
		/// </summary>
		public void AddDiagnostic(SpeculativeDiagnostic diagnostic)
		{
			ArgumentNullException.ThrowIfNull(diagnostic, "diagnostic");
			_diagnostics.Add(diagnostic);
		}

		/// <summary>
		///     <para xml:lang="en">Reads an overlaid value or obtains and caches its original value.</para>
		///     <para xml:lang="zh-CN">读取覆盖值；不存在时读取并缓存原始值。</para>
		/// </summary>
		public T GetState<T>(object target, object slot, Func<T> readOriginal)
		{
			ArgumentNullException.ThrowIfNull(target, "target");
			ArgumentNullException.ThrowIfNull(slot, "slot");
			ArgumentNullException.ThrowIfNull(readOriginal, "readOriginal");
			StateKey key = new StateKey(target, slot);
			if (_state.TryGetValue(key, out object value))
			{
				return CastState<T>(value, slot);
			}
			T val = readOriginal();
			_state.Add(key, val);
			return val;
		}

		/// <summary>
		///     <para xml:lang="en">Writes a value to the session overlay without modifying the target object.</para>
		///     <para xml:lang="zh-CN">将值写入会话覆盖层而不修改目标对象。</para>
		/// </summary>
		public void SetState<T>(object target, object slot, T value)
		{
			ArgumentNullException.ThrowIfNull(target, "target");
			ArgumentNullException.ThrowIfNull(slot, "slot");
			_state[new StateKey(target, slot)] = value;
		}

		/// <summary>
		///     <para xml:lang="en">Returns whether this session contains an overlaid value.</para>
		///     <para xml:lang="zh-CN">返回此会话是否包含指定覆盖值。</para>
		/// </summary>
		public bool HasState(object target, object slot)
		{
			ArgumentNullException.ThrowIfNull(target, "target");
			ArgumentNullException.ThrowIfNull(slot, "slot");
			return _state.ContainsKey(new StateKey(target, slot));
		}

		private static T CastState<T>(object? value, object slot)
		{
			if (!(value is T result))
			{
				if (value == null && default(T) == null)
				{
					return default(T);
				}
				throw new InvalidCastException($"Shadow slot '{slot}' contains {value?.GetType().FullName ?? "null"}, not {typeof(T).FullName}.");
			}
			return result;
		}
	}
}
namespace STS2RitsuLib.Utils.Persistence
{
	/// <summary>
	///     <para xml:lang="en">Indicates whether profile-scoped mod data is ready for safe access.</para>
	///     <para xml:lang="zh-CN">指示档案作用域的模组数据是否已可安全访问。</para>
	/// </summary>
	public enum DataLifecycleState
	{
		/// <summary>
		///     <para xml:lang="en">No active profile context is ready for mod-data persistence.</para>
		///     <para xml:lang="zh-CN">尚无可用于持久化模组数据的活动档案上下文。</para>
		/// </summary>
		WaitingForProfile,
		/// <summary>
		///     <para xml:lang="en">The profile path is initialized and mod-data operations are expected to be valid.</para>
		///     <para xml:lang="zh-CN">档案路径已初始化，模组数据操作预期有效。</para>
		/// </summary>
		Ready
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Published when profile-scoped mod data becomes readable and writable after initialization or
	///         reload.
	///     </para>
	///     <para xml:lang="zh-CN">初始化或重新加载后，档案作用域的模组数据变为可读可写时发布。</para>
	/// </summary>
	/// <param name="ProfileId">
	///     <para xml:lang="en">Active profile identifier.</para>
	///     <para xml:lang="zh-CN">活动档案标识符。</para>
	/// </param>
	/// <param name="Source">
	///     <para xml:lang="en">Subsystem that triggered the notification.</para>
	///     <para xml:lang="zh-CN">触发通知的子系统。</para>
	/// </param>
	/// <param name="IsInitialReady">
	///     <para xml:lang="en">
	///         <see langword="true" /> when this notification transitions the lifecycle from not ready to
	///         ready.
	///     </para>
	///     <para xml:lang="zh-CN">此次通知使生命周期从未就绪转换为就绪时为 <see langword="true" />。</para>
	/// </param>
	/// <param name="IsProfileSwitch">
	///     <para xml:lang="en"><see langword="true" /> when the ready profile ID differs from the preceding ready state.</para>
	///     <para xml:lang="zh-CN">就绪档案 ID 与上一个就绪状态不同时为 <see langword="true" />。</para>
	/// </param>
	/// <param name="DataReloaded">
	///     <para xml:lang="en"><see langword="true" /> when mod data was reloaded because its path or profile changed.</para>
	///     <para xml:lang="zh-CN">模组数据因路径或档案变化而重新加载时为 <see langword="true" />。</para>
	/// </param>
	/// <param name="OccurredAtUtc">
	///     <para xml:lang="en">Timestamp in UTC.</para>
	///     <para xml:lang="zh-CN">UTC 时间戳。</para>
	/// </param>
	public readonly record struct ProfileDataReadyEvent(int ProfileId, string Source, bool IsInitialReady, bool IsProfileSwitch, bool DataReloaded, DateTimeOffset OccurredAtUtc) : IReplayableFrameworkLifecycleEvent, IFrameworkLifecycleEvent;
	/// <summary>
	///     <para xml:lang="en">Published when the active profile ID changes while RitsuLib considers profile data ready.</para>
	///     <para xml:lang="zh-CN">RitsuLib 认为档案数据已就绪时，活动档案 ID 发生变化会发布此事件。</para>
	/// </summary>
	/// <param name="OldProfileId">
	///     <para xml:lang="en">Previous profile identifier.</para>
	///     <para xml:lang="zh-CN">上一个档案标识符。</para>
	/// </param>
	/// <param name="NewProfileId">
	///     <para xml:lang="en">New profile identifier.</para>
	///     <para xml:lang="zh-CN">新档案标识符。</para>
	/// </param>
	/// <param name="Source">
	///     <para xml:lang="en">Subsystem that triggered the notification.</para>
	///     <para xml:lang="zh-CN">触发通知的子系统。</para>
	/// </param>
	/// <param name="OccurredAtUtc">
	///     <para xml:lang="en">Timestamp in UTC.</para>
	///     <para xml:lang="zh-CN">UTC 时间戳。</para>
	/// </param>
	public readonly record struct ProfileDataChangedEvent(int OldProfileId, int NewProfileId, string Source, DateTimeOffset OccurredAtUtc) : IFrameworkLifecycleEvent;
	/// <summary>
	///     <para xml:lang="en">
	///         Published when the currently ready profile context becomes invalid, such as after its profile
	///         is deleted.
	///     </para>
	///     <para xml:lang="zh-CN">当前已就绪的档案上下文失效时发布，例如对应档案被删除后。</para>
	/// </summary>
	/// <param name="ProfileId">
	///     <para xml:lang="en">Profile that was invalidated.</para>
	///     <para xml:lang="zh-CN">已失效的档案。</para>
	/// </param>
	/// <param name="Reason">
	///     <para xml:lang="en">Short diagnostic label.</para>
	///     <para xml:lang="zh-CN">简短诊断标签。</para>
	/// </param>
	/// <param name="OccurredAtUtc">
	///     <para xml:lang="en">Timestamp in UTC.</para>
	///     <para xml:lang="zh-CN">UTC 时间戳。</para>
	/// </param>
	public readonly record struct ProfileDataInvalidatedEvent(int ProfileId, string Reason, DateTimeOffset OccurredAtUtc) : IFrameworkLifecycleEvent;
	/// <summary>
	///     <para xml:lang="en">
	///         Coordinates profile-data readiness and publishes <see cref="T:STS2RitsuLib.Utils.Persistence.ProfileDataReadyEvent" />,
	///         <see cref="T:STS2RitsuLib.Utils.Persistence.ProfileDataChangedEvent" />, and <see cref="T:STS2RitsuLib.Utils.Persistence.ProfileDataInvalidatedEvent" /> lifecycle events.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         协调档案数据的就绪状态，并发布 <see cref="T:STS2RitsuLib.Utils.Persistence.ProfileDataReadyEvent" />、<see cref="T:STS2RitsuLib.Utils.Persistence.ProfileDataChangedEvent" />
	///         和 <see cref="T:STS2RitsuLib.Utils.Persistence.ProfileDataInvalidatedEvent" /> 生命周期事件。
	///     </para>
	/// </summary>
	public static class DataReadyLifecycle
	{
		private static readonly Lock SyncRoot = new Lock();

		private static ProfileDataReadyEvent? _lastReadyEvent;

		/// <summary>
		///     <para xml:lang="en">
		///         <see langword="true" /> when profile-path initialization has completed and the data is
		///         considered safe to use.
		///     </para>
		///     <para xml:lang="zh-CN">档案路径初始化完成且数据可安全使用时为 <see langword="true" />。</para>
		/// </summary>
		public static bool IsReady { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Profile ID associated with the last ready notification, or <c>-1</c> when not ready.</para>
		///     <para xml:lang="zh-CN">与最近一次就绪通知关联的档案 ID；未就绪时为 <c>-1</c>。</para>
		/// </summary>
		public static int ReadyProfileId { get; private set; } = -1;

		/// <summary>
		///     <para xml:lang="en">Lifecycle state derived from <see cref="P:STS2RitsuLib.Utils.Persistence.DataReadyLifecycle.IsReady" />.</para>
		///     <para xml:lang="zh-CN">从 <see cref="P:STS2RitsuLib.Utils.Persistence.DataReadyLifecycle.IsReady" /> 派生的生命周期状态。</para>
		/// </summary>
		public static DataLifecycleState State
		{
			get
			{
				if (!IsReady)
				{
					return DataLifecycleState.WaitingForProfile;
				}
				return DataLifecycleState.Ready;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Refreshes the current profile, ensures profile services, reloads data after path changes, and
		///         publishes lifecycle events when appropriate.
		///     </para>
		///     <para xml:lang="zh-CN">刷新当前档案，确保档案服务可用，在路径变化后重新加载数据，并在适当时发布生命周期事件。</para>
		/// </summary>
		/// <param name="source">
		///     <para xml:lang="en">Diagnostic label for log and event payloads.</para>
		///     <para xml:lang="zh-CN">用于日志和事件载荷的诊断标签。</para>
		/// </param>
		public static void NotifyPotentialReady(string source)
		{
			try
			{
				ProfileManager.Instance.RefreshCurrentProfile();
				int num = ModDataRuntimeInterop.TryRegisterAll();
				if (num > 0)
				{
					RitsuLibFramework.Logger.Debug($"ModData runtime interop: registered {num} provider schema(s) during data-ready refresh.", 1);
				}
				RitsuLibFramework.EnsureProfileServicesInitialized();
				bool flag = ModDataStore.ReloadAllIfPathChanged();
				if (flag)
				{
					ModDataRuntimeInterop.PushLoadedDataToAllProviders();
				}
				int currentProfileId = ProfileManager.Instance.CurrentProfileId;
				bool flag2;
				int readyProfileId;
				bool flag3;
				ProfileDataReadyEvent profileDataReadyEvent;
				using (SyncRoot.EnterScope())
				{
					flag2 = !IsReady;
					readyProfileId = ReadyProfileId;
					flag3 = !flag2 && readyProfileId != currentProfileId;
					IsReady = true;
					ReadyProfileId = currentProfileId;
					profileDataReadyEvent = new ProfileDataReadyEvent(currentProfileId, source, flag2, flag3, flag, DateTimeOffset.UtcNow);
					_lastReadyEvent = profileDataReadyEvent;
				}
				if (flag2 || flag3)
				{
					if (flag3)
					{
						RitsuLibFramework.PublishLifecycleEvent(new ProfileDataChangedEvent(readyProfileId, currentProfileId, source, DateTimeOffset.UtcNow), "ProfileDataChangedEvent");
					}
					if (ModDataStore.HasAnyProfileScopedEntries)
					{
						RitsuLibFramework.Logger.Info($"Data ready for profile {currentProfileId} ({source})", 1);
					}
					RitsuLibFramework.PublishLifecycleEvent(profileDataReadyEvent, "ProfileDataReadyEvent");
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Persistence] Failed to notify data ready lifecycle from '" + source + "': " + ex.Message, 1);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Invalidates the given profile and publishes <see cref="T:STS2RitsuLib.Utils.Persistence.ProfileDataInvalidatedEvent" /> if it
		///         was the active ready profile.
		///     </para>
		///     <para xml:lang="zh-CN">使指定档案失效；如果它是当前已就绪的活动档案，则发布 <see cref="T:STS2RitsuLib.Utils.Persistence.ProfileDataInvalidatedEvent" />。</para>
		/// </summary>
		public static void NotifyProfileInvalidated(int profileId, string reason)
		{
			if (profileId < 0)
			{
				return;
			}
			bool flag = false;
			using (SyncRoot.EnterScope())
			{
				if (IsReady && ReadyProfileId == profileId)
				{
					IsReady = false;
					ReadyProfileId = -1;
					_lastReadyEvent = null;
					flag = true;
				}
			}
			if (flag)
			{
				RitsuLibFramework.PublishLifecycleEvent(new ProfileDataInvalidatedEvent(profileId, reason, DateTimeOffset.UtcNow), "ProfileDataInvalidatedEvent");
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Converts Godot user-data paths under the current account root to account-relative paths.</para>
	///     <para xml:lang="zh-CN">将当前账户根目录下的 Godot 用户数据路径转换为账户相对路径。</para>
	/// </summary>
	internal static class ModAccountRelativePath
	{
		internal static bool TryGetRelativeAccountPath(string godotUserPath, out string relative)
		{
			relative = string.Empty;
			string accountRootPath = ProfileManager.GetAccountRootPath();
			string text = godotUserPath.Replace('\\', '/');
			if (text.Length <= accountRootPath.Length + 1)
			{
				return false;
			}
			if (!text.StartsWith(accountRootPath, StringComparison.Ordinal))
			{
				return false;
			}
			if (text[accountRootPath.Length] != '/')
			{
				return false;
			}
			relative = text.Substring(accountRootPath.Length + 1);
			return true;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Tracks registered mod-data slots and derives the account-relative paths eligible for cloud
	///         synchronization.
	///     </para>
	///     <para xml:lang="zh-CN">跟踪已注册的模组数据槽，并推导可进行云同步的账户相对路径。</para>
	/// </summary>
	internal static class ModCloudSyncPathRegistry
	{
		private readonly record struct Slot(string ModId, string FileName, SaveScope Scope);

		private static readonly Lock Sync = new Lock();

		private static readonly HashSet<Slot> Slots = new HashSet<Slot>();

		internal static void RegisterModDataSlot(string modId, string fileName, SaveScope scope)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(fileName, "fileName");
			using (Sync.EnterScope())
			{
				Slots.Add(new Slot(modId, fileName, scope));
			}
		}

		internal static void CollectRegisteredRelativePaths(int profileId, HashSet<string> sink, ModCloudSyncScope scope = ModCloudSyncScope.All)
		{
			using (Sync.EnterScope())
			{
				foreach (Slot slot in Slots)
				{
					switch (scope)
					{
					case ModCloudSyncScope.GlobalOnly:
						if (slot.Scope != SaveScope.Global)
						{
							continue;
						}
						break;
					case ModCloudSyncScope.ProfileOnly:
						if (slot.Scope != SaveScope.Profile)
						{
							continue;
						}
						break;
					}
					switch (slot.Scope)
					{
					case SaveScope.Global:
					{
						if (ModAccountRelativePath.TryGetRelativeAccountPath(ProfileManager.GetFilePath(slot.FileName, SaveScope.Global, 0, slot.ModId), out string relative2))
						{
							sink.Add(relative2);
						}
						break;
					}
					default:
					{
						if (profileId >= 0 && ModAccountRelativePath.TryGetRelativeAccountPath(ProfileManager.GetFilePath(slot.FileName, SaveScope.Profile, profileId, slot.ModId), out string relative))
						{
							sink.Add(relative);
						}
						break;
					}
					case SaveScope.InMemory:
						break;
					}
				}
			}
		}

		internal static bool IsRegisteredRelativePath(string relativeAccountPath, int activeProfileId)
		{
			using (Sync.EnterScope())
			{
				foreach (Slot slot in Slots)
				{
					string relative2;
					if (slot.Scope == SaveScope.Global)
					{
						if (ModAccountRelativePath.TryGetRelativeAccountPath(ProfileManager.GetFilePath(slot.FileName, SaveScope.Global, 0, slot.ModId), out string relative) && string.Equals(relative, relativeAccountPath, StringComparison.Ordinal))
						{
							return true;
						}
					}
					else if (slot.Scope != SaveScope.InMemory && activeProfileId >= 0 && ModAccountRelativePath.TryGetRelativeAccountPath(ProfileManager.GetFilePath(slot.FileName, SaveScope.Profile, activeProfileId, slot.ModId), out relative2) && string.Equals(relative2, relativeAccountPath, StringComparison.Ordinal))
					{
						return true;
					}
				}
			}
			return false;
		}

		internal static void CollectProfileScopedRegisteredRelativePaths(int profileId, HashSet<string> sink)
		{
			if (profileId < 0)
			{
				return;
			}
			using (Sync.EnterScope())
			{
				foreach (string item in Slots.Where(delegate(Slot slot)
				{
					Slot slot2 = slot;
					return slot2.Scope == SaveScope.Profile;
				}).Select(delegate(Slot slot)
				{
					Slot slot2 = slot;
					string fileName = slot2.FileName;
					int profileId2 = profileId;
					slot2 = slot;
					return ProfileManager.GetFilePath(fileName, SaveScope.Profile, profileId2, slot2.ModId);
				}))
				{
					if (ModAccountRelativePath.TryGetRelativeAccountPath(item, out string relative))
					{
						sink.Add(relative);
					}
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Selects which registered mod-data scopes participate in a cloud synchronization operation.</para>
	///     <para xml:lang="zh-CN">选择哪些已注册模组数据作用域参与云同步操作。</para>
	/// </summary>
	internal enum ModCloudSyncScope
	{
		GlobalOnly,
		ProfileOnly,
		All
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Uses the game's <see cref="T:MegaCrit.Sts2.Core.Saves.CloudSaveStore" /> as the capability boundary for mod-data cloud
	///         synchronization, avoiding dependencies on launcher-specific cloud-storage types.
	///     </para>
	///     <para xml:lang="zh-CN">以游戏的 <see cref="T:MegaCrit.Sts2.Core.Saves.CloudSaveStore" /> 作为模组数据云同步的能力边界，从而避免依赖启动器专用的云存储类型。</para>
	/// </summary>
	internal static class ModDataCloudHost
	{
		internal static bool MayEnumerateNativeSteamRemoteStorage
		{
			get
			{
				if (!RitsuLibMobileSteamRuntime.SuppressNativeSteamIntegration && SteamInitializer.Initialized)
				{
					return RitsuLibSteamworks.IsAvailable;
				}
				return false;
			}
		}

		internal static CloudSaveStore? TryGetCloudSaveStore()
		{
			try
			{
				ISaveStore obj = SaveStore(SaveManager.Instance);
				return (CloudSaveStore?)(object)((obj is CloudSaveStore) ? obj : null);
			}
			catch
			{
				return null;
			}
		}

		internal static bool HasCloudSaveStore()
		{
			return TryGetCloudSaveStore() != null;
		}

		internal static bool CanUseModDataCloud()
		{
			return HasCloudSaveStore();
		}

		[UnsafeAccessor(UnsafeAccessorKind.Field, Name = "_saveStore")]
		private static extern ref readonly ISaveStore SaveStore(SaveManager manager);
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Mirrors registered mod-data files between local account storage and the game's cloud save
	///         store.
	///     </para>
	///     <para xml:lang="zh-CN">在本地账户存储与游戏云存档之间镜像已注册的模组数据文件。</para>
	/// </summary>
	internal static class ModDataCloudMirror
	{
		private const int SteamRemoteScanYieldEvery = 32;

		private const int LocalPathCollectYieldEvery = 64;

		private static bool MayEnumerateSteamRemoteStorage => ModDataCloudHost.MayEnumerateNativeSteamRemoteStorage;

		internal static CloudSaveStore? TryGetCloudSaveStore()
		{
			return ModDataCloudHost.TryGetCloudSaveStore();
		}

		internal static bool ShouldRunCloudMirror()
		{
			if (RitsuLibSettingsStore.IsSyncModDataToCloudEnabled())
			{
				return ModDataCloudHost.CanUseModDataCloud();
			}
			return false;
		}

		internal static void MirrorLocalFileAfterWriteIfEnabled(string godotUserPath)
		{
			//IL_0043: Unknown result type (might be due to invalid IL or missing references)
			//IL_0048: Unknown result type (might be due to invalid IL or missing references)
			if (!ShouldRunCloudMirror() || !ModAccountRelativePath.TryGetRelativeAccountPath(godotUserPath, out string relative))
			{
				return;
			}
			int currentProfileId = ProfileManager.Instance.CurrentProfileId;
			if (ModCloudSyncPathRegistry.IsRegisteredRelativePath(relative, currentProfileId))
			{
				Callable val = Callable.From((Action)delegate
				{
					MirrorAfterWriteOneFileAsync(relative);
				});
				((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			}
		}

		internal static void ScheduleReconcileModDataWithCloud()
		{
			//IL_0023: Unknown result type (might be due to invalid IL or missing references)
			//IL_0028: Unknown result type (might be due to invalid IL or missing references)
			if (ShouldRunCloudMirror())
			{
				Callable val = Callable.From((Action)StartReconcileModDataDeferred);
				((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			}
		}

		private static void StartReconcileModDataDeferred()
		{
			MainLoop mainLoop = Engine.GetMainLoop();
			SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
			if (val != null)
			{
				ReconcileModDataWithCloudAsync(val);
			}
		}

		private static async Task MirrorAfterWriteOneFileAsync(string relative)
		{
			_ = 1;
			try
			{
				MainLoop mainLoop = Engine.GetMainLoop();
				SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
				if (val != null)
				{
					await WaitProcessFramesAsync(val, 1);
				}
				CloudSaveStore val2 = TryGetCloudSaveStore();
				if (val2 != null)
				{
					await QueueCloudWriteFromLocalAsync(val2, relative);
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[ModCloud] push '" + relative + "': " + ex.Message, 1);
			}
		}

		internal static async Task ReconcileModDataWithCloudAsync(SceneTree tree)
		{
			if (!ShouldRunCloudMirror())
			{
				return;
			}
			CloudSaveStore cloud = TryGetCloudSaveStore();
			if (cloud == null)
			{
				return;
			}
			await WaitProcessFramesAsync(tree, 1);
			try
			{
				ProfileManager.Instance.RefreshCurrentProfile();
			}
			catch
			{
			}
			try
			{
				await ReconcileCoreAsync(cloud, tree);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[ModCloud] reconcile failed: " + ex.Message, 1);
			}
			try
			{
				ModDataStore.ReloadAllIfPathChanged();
			}
			catch (Exception ex2)
			{
				RitsuLibFramework.Logger.Warn("[ModCloud] reload mod data after reconcile: " + ex2.Message, 1);
			}
		}

		internal static async Task<List<string>> CollectDistinctLocalModDataPathsAsync(SceneTree tree, ModCloudSyncScope scope, CancellationToken ct = default(CancellationToken))
		{
			int currentProfileId = ProfileManager.Instance.CurrentProfileId;
			return await CollectWhitelistRelativePathsForProfileAsync(tree, currentProfileId, scope, ct);
		}

		internal static async Task<List<string>> CollectDistinctRemoteModDataPathsForPullAsync(SceneTree tree, ModCloudSyncScope scope, CancellationToken ct = default(CancellationToken))
		{
			int currentProfileId = ProfileManager.Instance.CurrentProfileId;
			return await CollectWhitelistRelativePathsForProfileAsync(tree, currentProfileId, scope, ct);
		}

		internal static async Task<List<string>> CollectWhitelistRelativePathsForProfileAsync(SceneTree tree, int profileId, ModCloudSyncScope scope, CancellationToken ct = default(CancellationToken))
		{
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			StorageSyncPathEnumerator.CollectWhitelistedRelativePaths(profileId, hashSet, scope);
			List<string> list = hashSet.ToList();
			for (int i = 0; i < list.Count; i++)
			{
				ct.ThrowIfCancellationRequested();
				if (i > 0 && i % 64 == 0)
				{
					await WaitProcessFramesAsync(tree, 1, ct);
				}
			}
			return list;
		}

		internal static async Task<(int clearedCloud, int fail)> ClearRegisteredPathsFromCloudAsync(SceneTree tree, CloudSaveStore cloud, ModCloudSyncScope scope, CancellationToken ct = default(CancellationToken))
		{
			int clearedCloud = 0;
			int fail = 0;
			int currentProfileId = ProfileManager.Instance.CurrentProfileId;
			List<string> list = await CollectWhitelistRelativePathsForProfileAsync(tree, currentProfileId, scope, ct);
			int i = 0;
			foreach (string path in list)
			{
				ct.ThrowIfCancellationRequested();
				int num = i + 1;
				i = num;
				if (num % 64 == 0)
				{
					await WaitProcessFramesAsync(tree, 1, ct);
				}
				try
				{
					if (((ISaveStore)cloud.CloudStore).FileExists(path))
					{
						((ISaveStore)cloud.CloudStore).DeleteFile(path);
						clearedCloud++;
					}
				}
				catch (Exception ex)
				{
					fail++;
					RitsuLibFramework.Logger.Warn("[ModCloud][ClearCloud] '" + path + "': " + ex.Message, 1);
				}
			}
			return (clearedCloud: clearedCloud, fail: fail);
		}

		internal static async Task<(int queued, int skipped, int fail)> PushPathsAsync(CloudSaveStore cloud, IReadOnlyList<string> paths, SceneTree tree, Action<int, int, string?> reportProgress, CancellationToken ct = default(CancellationToken))
		{
			int queued = 0;
			int skipped = 0;
			int fail = 0;
			int total = paths.Count;
			reportProgress(0, total, (total > 0) ? paths[0] : null);
			for (int i = 0; i < total; i++)
			{
				ct.ThrowIfCancellationRequested();
				string path = paths[i];
				reportProgress(i, total, path);
				try
				{
					if (!cloud.LocalStore.FileExists(path))
					{
						skipped++;
						reportProgress(i + 1, total, path);
						await WaitProcessFramesAsync(tree, 1, ct);
						continue;
					}
					await QueueCloudWriteFromLocalAsync(cloud, path);
					queued++;
				}
				catch (Exception ex)
				{
					fail++;
					RitsuLibFramework.Logger.Warn("[ModCloud][Push] '" + path + "': " + ex.Message, 1);
				}
				reportProgress(i + 1, total, path);
				await WaitProcessFramesAsync(tree, 1, ct);
			}
			return (queued: queued, skipped: skipped, fail: fail);
		}

		internal static async Task<(int ok, int fail)> PullPathsAsync(CloudSaveStore cloud, IReadOnlyList<string> paths, SceneTree tree, Action<int, int, string?> reportProgress, CancellationToken ct = default(CancellationToken))
		{
			int ok = 0;
			int fail = 0;
			int total = paths.Count;
			reportProgress(0, total, (total > 0) ? paths[0] : null);
			for (int i = 0; i < total; i++)
			{
				ct.ThrowIfCancellationRequested();
				string path = paths[i];
				reportProgress(i, total, path);
				try
				{
					if (!((ISaveStore)cloud.CloudStore).FileExists(path))
					{
						reportProgress(i + 1, total, path);
						await WaitProcessFramesAsync(tree, 1, ct);
						continue;
					}
					string text = await ((ISaveStore)cloud.CloudStore).ReadFileAsync(path);
					if (text == null)
					{
						reportProgress(i + 1, total, path);
						await WaitProcessFramesAsync(tree, 1, ct);
						continue;
					}
					await cloud.LocalStore.WriteFileAsync(path, text);
					cloud.LocalStore.SetLastModifiedTime(path, ((ISaveStore)cloud.CloudStore).GetLastModifiedTime(path));
					ok++;
				}
				catch (Exception ex)
				{
					fail++;
					RitsuLibFramework.Logger.Warn("[ModCloud][Pull] '" + path + "': " + ex.Message, 1);
				}
				reportProgress(i + 1, total, path);
				await WaitProcessFramesAsync(tree, 1, ct);
			}
			ReloadModStoresAfterCloudPull();
			return (ok: ok, fail: fail);
		}

		internal static void ReloadModStoresAfterCloudPull()
		{
			try
			{
				ModDataStore.ReloadAllIfPathChanged();
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[ModCloud] reload after pull: " + ex.Message, 1);
			}
		}

		internal static async Task WaitProcessFramesAsync(SceneTree tree, int count, CancellationToken ct = default(CancellationToken))
		{
			await RitsuGodotAwaitSafety.AwaitProcessFramesAsync(tree, count, null, ct);
		}

		internal static void ScheduleDeleteCloudModDataForProfile(int profileId)
		{
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_0026: Unknown result type (might be due to invalid IL or missing references)
			if (TryGetCloudSaveStore() != null)
			{
				Callable val = Callable.From((Action)delegate
				{
					DeleteCloudModDataForProfileAsync(profileId);
				});
				((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			}
		}

		private static async Task DeleteCloudModDataForProfileAsync(int profileId)
		{
			MainLoop mainLoop = Engine.GetMainLoop();
			SceneTree tree = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
			if (tree == null)
			{
				return;
			}
			CloudSaveStore cloud = TryGetCloudSaveStore();
			if (cloud == null)
			{
				return;
			}
			HashSet<string> exact = new HashSet<string>(StringComparer.Ordinal);
			ModCloudSyncPathRegistry.CollectProfileScopedRegisteredRelativePaths(profileId, exact);
			if (!MayEnumerateSteamRemoteStorage)
			{
				foreach (string item in exact)
				{
					try
					{
						if (((ISaveStore)cloud.CloudStore).FileExists(item))
						{
							((ISaveStore)cloud.CloudStore).DeleteFile(item);
						}
					}
					catch (Exception ex)
					{
						RitsuLibFramework.Logger.Warn("[ModCloud] delete cloud '" + item + "' (registered paths only): " + ex.Message, 1);
					}
				}
				return;
			}
			if (!RitsuLibSteamworks.TryGetRemoteFileCount(out var n))
			{
				return;
			}
			for (int i = 0; i < n; i++)
			{
				if (i > 0 && i % 32 == 0)
				{
					await WaitProcessFramesAsync(tree, 1);
				}
				if (!RitsuLibSteamworks.TryGetRemoteFileNameAndSize(i, out string path))
				{
					continue;
				}
				path = path.Replace('\\', '/');
				if (!string.IsNullOrEmpty(path) && path.StartsWith("mod_data/", StringComparison.Ordinal) && exact.Contains(path))
				{
					try
					{
						((ISaveStore)cloud.CloudStore).DeleteFile(path);
					}
					catch (Exception ex2)
					{
						RitsuLibFramework.Logger.Warn("[ModCloud] delete cloud '" + path + "': " + ex2.Message, 1);
					}
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Enumerates every <c>mod_data/</c> path in Steam Remote Storage. Reserved for future cloud-file
		///         management tools.
		///     </para>
		///     <para xml:lang="zh-CN">枚举 Steam 远程存储中的所有 <c>mod_data/</c> 路径，供未来的云文件管理工具使用。</para>
		/// </summary>
		internal static async Task<List<string>> CollectRemoteModDataRelativePathsAsync(SceneTree tree, CancellationToken ct = default(CancellationToken))
		{
			HashSet<string> set = new HashSet<string>(StringComparer.Ordinal);
			if (!MayEnumerateSteamRemoteStorage || !RitsuLibSteamworks.TryGetRemoteFileCount(out var n))
			{
				return new List<string>();
			}
			for (int i = 0; i < n; i++)
			{
				ct.ThrowIfCancellationRequested();
				if (i > 0 && i % 32 == 0)
				{
					await WaitProcessFramesAsync(tree, 1, ct);
				}
				if (RitsuLibSteamworks.TryGetRemoteFileNameAndSize(i, out string path))
				{
					path = path.Replace('\\', '/');
					if (!string.IsNullOrEmpty(path) && path.StartsWith("mod_data/", StringComparison.Ordinal))
					{
						set.Add(path);
					}
				}
			}
			return set.OrderBy<string, string>((string s) => s, StringComparer.Ordinal).ToList();
		}

		private static async Task ReconcileCoreAsync(CloudSaveStore cloud, SceneTree tree)
		{
			int currentProfileId = ProfileManager.Instance.CurrentProfileId;
			foreach (string path in await CollectWhitelistRelativePathsForProfileAsync(tree, currentProfileId, ModCloudSyncScope.All))
			{
				try
				{
					bool num = ((ISaveStore)cloud.CloudStore).FileExists(path);
					bool flag = cloud.LocalStore.FileExists(path);
					if (!num)
					{
						if (!flag)
						{
							await WaitProcessFramesAsync(tree, 1);
							continue;
						}
						if (flag)
						{
							await QueueCloudWriteFromLocalAsync(cloud, path);
							await WaitProcessFramesAsync(tree, 1);
							continue;
						}
					}
					else
					{
						if (!flag)
						{
							string text = await ((ISaveStore)cloud.CloudStore).ReadFileAsync(path);
							if (text == null)
							{
								await WaitProcessFramesAsync(tree, 1);
								continue;
							}
							await cloud.LocalStore.WriteFileAsync(path, text);
							cloud.LocalStore.SetLastModifiedTime(path, ((ISaveStore)cloud.CloudStore).GetLastModifiedTime(path));
							await WaitProcessFramesAsync(tree, 1);
							continue;
						}
						if (flag)
						{
							DateTimeOffset ct = ((ISaveStore)cloud.CloudStore).GetLastModifiedTime(path);
							DateTimeOffset lastModifiedTime = cloud.LocalStore.GetLastModifiedTime(path);
							if (ct > lastModifiedTime)
							{
								string text2 = await ((ISaveStore)cloud.CloudStore).ReadFileAsync(path);
								if (text2 == null)
								{
									await WaitProcessFramesAsync(tree, 1);
									continue;
								}
								await cloud.LocalStore.WriteFileAsync(path, text2);
								cloud.LocalStore.SetLastModifiedTime(path, ct);
							}
							else if (lastModifiedTime > ct)
							{
								await QueueCloudWriteFromLocalAsync(cloud, path);
							}
						}
					}
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn("[ModCloud] reconcile '" + path + "': " + ex.Message, 1);
				}
				await WaitProcessFramesAsync(tree, 1);
			}
		}

		private static async Task QueueCloudWriteFromLocalAsync(CloudSaveStore cloud, string path)
		{
			if (!cloud.LocalStore.FileExists(path))
			{
				throw new FileNotFoundException("Local mod data file not found: " + path);
			}
			string text = await cloud.LocalStore.ReadFileAsync(path);
			if (text == null)
			{
				throw new InvalidOperationException("Local mod data file could not be read: " + path);
			}
			await ((ISaveStore)cloud.CloudStore).WriteFileAsync(path, text);
			TrySyncLocalTimestampFromCloud(cloud, path);
		}

		private static void TrySyncLocalTimestampFromCloud(CloudSaveStore cloud, string path)
		{
			try
			{
				cloud.LocalStore.SetLastModifiedTime(path, ((ISaveStore)cloud.CloudStore).GetLastModifiedTime(path));
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[ModCloud] sync timestamp '" + path + "': " + ex.Message, 1);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Typed JSON persistence wrapper with optional migrations, backup recovery, and change
	///         notifications.
	///     </para>
	///     <para xml:lang="zh-CN">支持可选迁移、备份恢复和变更通知的强类型 JSON 持久化封装。</para>
	/// </summary>
	public class PersistentDataEntry<T> where T : class, new()
	{
		private readonly bool _autoCreateIfMissing;

		private readonly Func<StorageContext>? _contextProvider;

		private readonly T _defaultValues;

		private readonly string _fileName;

		private readonly JsonSerializerOptions _jsonOptions;

		private readonly MigrationManager _migrationManager;

		private readonly string _modId;

		/// <summary>
		///     <para xml:lang="en">
		///         Current deserialized data object; mutate it through <see cref="M:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.Modify(System.Action{`0})" /> to raise change
		///         notifications.
		///     </para>
		///     <para xml:lang="zh-CN">当前反序列化的数据对象；请通过 <see cref="M:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.Modify(System.Action{`0})" /> 修改它以触发变更通知。</para>
		/// </summary>
		public T Data { get; private set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Resolved Godot user-data path for this entry, using the active profile unless its context
		///         supplies another profile ID.
		///     </para>
		///     <para xml:lang="zh-CN">此条目解析后的 Godot 用户数据路径；除非上下文提供其他档案 ID，否则使用活动档案。</para>
		/// </summary>
		public string FilePath => StoragePathResolver.ResolveFilePathUser(_modId, _fileName, Scope, _contextProvider?.Invoke());

		/// <summary>
		///     <para xml:lang="en">Configured storage scope for this entry.</para>
		///     <para xml:lang="zh-CN">此条目配置的存储作用域。</para>
		/// </summary>
		public SaveScope Scope { get; }

		/// <summary>
		///     <para xml:lang="en">Raised after a load attempt or an in-memory modification through <see cref="M:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.Modify(System.Action{`0})" />.</para>
		///     <para xml:lang="zh-CN">尝试加载后，或通过 <see cref="M:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.Modify(System.Action{`0})" /> 修改内存数据后触发。</para>
		/// </summary>
		public event Action? Changed;

		/// <summary>
		///     <para xml:lang="en">
		///         Configures the persistent entry and initializes its in-memory data with a deep copy of
		///         <paramref name="defaultValues" />.
		///     </para>
		///     <para xml:lang="zh-CN">配置持久化条目，并以 <paramref name="defaultValues" /> 的深层副本初始化其内存数据。</para>
		/// </summary>
		public PersistentDataEntry(string modId, string fileName, SaveScope scope, T defaultValues, JsonSerializerOptions jsonOptions, MigrationManager migrationManager, bool autoCreateIfMissing = false, Func<StorageContext>? contextProvider = null)
		{
			_modId = modId;
			_fileName = fileName;
			Scope = scope;
			_defaultValues = defaultValues;
			_jsonOptions = jsonOptions;
			_migrationManager = migrationManager;
			_autoCreateIfMissing = autoCreateIfMissing;
			_contextProvider = contextProvider;
			Data = DeepClone(defaultValues);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Reads JSON from disk (with backup fallback), applies migrations, and updates
		///         <see cref="P:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.Data" />.
		///     </para>
		///     <para xml:lang="zh-CN">从磁盘读取 JSON（带备份回退），应用迁移，并更新 <see cref="P:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.Data" />。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if data was loaded successfully; <see langword="false" /> if defaults
		///         were used because the file was missing or invalid.
		///     </para>
		///     <para xml:lang="zh-CN">成功加载数据时为 <see langword="true" />；因文件缺失或无效而使用默认值时为 <see langword="false" />。</para>
		/// </returns>
		public bool Load()
		{
			string filePath = FilePath;
			RitsuLibFramework.Logger.Debug("[Persistence] [" + _fileName + "] Loading from: " + filePath, 1);
			FileOperations.ReadResult readResult = FileOperations.ReadTextWithBackupFallback(filePath, _fileName);
			if (!readResult.Success || string.IsNullOrEmpty(readResult.Content))
			{
				RitsuLibFramework.Logger.Info("[Persistence] [" + _fileName + "] Using default values: " + readResult.ErrorMessage, 1);
				Data = DeepClone(_defaultValues);
				if (_autoCreateIfMissing && !FileOperations.FileExists(filePath))
				{
					Save();
				}
				Changed?.Invoke();
				return false;
			}
			MigrationResult<T> migrationResult = _migrationManager.Migrate<T>(readResult.Content, _jsonOptions);
			if (!migrationResult.Success)
			{
				RitsuLibFramework.Logger.Warn("[Persistence] [" + _fileName + "] Migration failed: " + migrationResult.ErrorMessage, 1);
				if (migrationResult.RequiresRecovery)
				{
					MarkCorrupt(filePath);
				}
				Data = DeepClone(_defaultValues);
				Changed?.Invoke();
				return false;
			}
			Data = migrationResult.Data;
			if (migrationResult.WasMigrated)
			{
				RitsuLibFramework.Logger.Info($"[Persistence] [{_fileName}] Data migrated to version {migrationResult.FinalVersion}", 1);
				Save();
			}
			if (readResult.LoadedFromBackup)
			{
				Save();
			}
			Changed?.Invoke();
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Serializes <see cref="P:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.Data" /> to <see cref="P:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.FilePath" />.</para>
		///     <para xml:lang="zh-CN">将 <see cref="P:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.Data" /> 序列化到 <see cref="P:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.FilePath" />。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if the file was written successfully; otherwise,
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">文件写入成功时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public bool Save()
		{
			return SaveTo(FilePath);
		}

		/// <summary>
		///     <para xml:lang="en">Serializes <see cref="P:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.Data" /> to an explicit path, such as for an export or test.</para>
		///     <para xml:lang="zh-CN">将 <see cref="P:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.Data" /> 序列化到显式指定的路径，例如用于导出或测试。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if the file was written successfully; otherwise,
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">文件写入成功时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public bool SaveTo(string path)
		{
			try
			{
				RitsuLibFramework.Logger.Debug("[Persistence] [" + _fileName + "] Saving to: " + path, 1);
				string content = JsonSerializer.Serialize(Data, _jsonOptions);
				FileOperations.WriteResult writeResult = FileOperations.WriteText(path, content, _fileName);
				if (writeResult.Success)
				{
					ModDataCloudMirror.MirrorLocalFileAfterWriteIfEnabled(path);
				}
				return writeResult.Success;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[Persistence] [{_fileName}] Save to '{path}' failed: {ex.Message}");
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Applies an in-place mutation to <see cref="P:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.Data" /> and raises <see cref="E:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.Changed" />.</para>
		///     <para xml:lang="zh-CN">对 <see cref="P:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.Data" /> 应用原地修改，并触发 <see cref="E:STS2RitsuLib.Utils.Persistence.PersistentDataEntry`1.Changed" />。</para>
		/// </summary>
		public void Modify(Action<T> modifier)
		{
			modifier(Data);
			Changed?.Invoke();
		}

		private void MarkCorrupt(string path)
		{
			try
			{
				string text = path + ".corrupt";
				FileOperations.RenameFile(path, text, _fileName);
				RitsuLibFramework.Logger.Warn("[Persistence] [" + _fileName + "] Corrupt file renamed to " + text, 1);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.ErrorNoTrace("[Persistence] [" + _fileName + "] Failed to mark corrupt: " + ex.Message);
			}
		}

		private T DeepClone(T source)
		{
			try
			{
				return JsonSerializer.Deserialize<T>(JsonSerializer.Serialize(source, _jsonOptions), _jsonOptions) ?? new T();
			}
			catch
			{
				return new T();
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Tracks the active game profile ID and resolves mod-data paths under Godot <c>user://</c>
	///         storage.
	///     </para>
	///     <para xml:lang="zh-CN">跟踪活动游戏档案 ID，并解析 Godot <c>user://</c> 存储中的模组数据路径。</para>
	/// </summary>
	public class ProfileManager
	{
		private static ProfileManager? _instance;

		private bool _isInitialized;

		/// <summary>
		///     <para xml:lang="en">Gets the shared profile manager.</para>
		///     <para xml:lang="zh-CN">获取共享的档案管理器。</para>
		/// </summary>
		public static ProfileManager Instance => _instance ?? (_instance = new ProfileManager());

		/// <summary>
		///     <para xml:lang="en">Last known game profile ID, or <c>-1</c> before initialization.</para>
		///     <para xml:lang="zh-CN">最后获知的游戏档案 ID；初始化前为 <c>-1</c>。</para>
		/// </summary>
		public int CurrentProfileId { get; private set; } = -1;

		/// <summary>
		///     <para xml:lang="en">Raised with <c>(oldProfileId, newProfileId)</c> after the active profile changes.</para>
		///     <para xml:lang="zh-CN">活动档案变化后以 <c>(oldProfileId, newProfileId)</c> 触发。</para>
		/// </summary>
		public event Action<int, int>? ProfileChanged;

		/// <summary>
		///     <para xml:lang="en">Raised when mod data for a profile is deleted via game APIs.</para>
		///     <para xml:lang="zh-CN">通过游戏 API 删除某个档案的模组数据时触发。</para>
		/// </summary>
		public event Action<int>? ProfileDeleted;

		private ProfileManager()
		{
		}

		/// <summary>
		///     <para xml:lang="en">Subscribes to game profile changes and initializes <see cref="P:STS2RitsuLib.Utils.Persistence.ProfileManager.CurrentProfileId" />.</para>
		///     <para xml:lang="zh-CN">订阅游戏档案变化，并初始化 <see cref="P:STS2RitsuLib.Utils.Persistence.ProfileManager.CurrentProfileId" />。</para>
		/// </summary>
		public void Initialize()
		{
			if (!_isInitialized)
			{
				CurrentProfileId = GetCurrentProfileIdFromGame();
				SaveManager.Instance.ProfileIdChanged += OnGameProfileChanged;
				_isInitialized = true;
				RitsuLibFramework.Logger.Info($"[Persistence] ProfileManager initialized with profile ID: {CurrentProfileId}", 1);
			}
		}

		private void OnGameProfileChanged(int newProfileId)
		{
			OnProfileChanged(newProfileId);
		}

		/// <summary>
		///     <para xml:lang="en">Updates <see cref="P:STS2RitsuLib.Utils.Persistence.ProfileManager.CurrentProfileId" /> and notifies subscribers when the value changes.</para>
		///     <para xml:lang="zh-CN">更新 <see cref="P:STS2RitsuLib.Utils.Persistence.ProfileManager.CurrentProfileId" />，并在值变化时通知订阅者。</para>
		/// </summary>
		public void OnProfileChanged(int newProfileId)
		{
			if (newProfileId != CurrentProfileId)
			{
				int currentProfileId = CurrentProfileId;
				CurrentProfileId = newProfileId;
				if (currentProfileId >= 0)
				{
					RitsuLibFramework.Logger.Info($"[Persistence] Profile changed from {currentProfileId} to {newProfileId}", 1);
				}
				ProfileChanged?.Invoke(currentProfileId, newProfileId);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Re-reads the profile ID from the game and calls <see cref="M:STS2RitsuLib.Utils.Persistence.ProfileManager.OnProfileChanged(System.Int32)" /> if it changed.</para>
		///     <para xml:lang="zh-CN">从游戏重新读取档案 ID，并在值发生变化时调用 <see cref="M:STS2RitsuLib.Utils.Persistence.ProfileManager.OnProfileChanged(System.Int32)" />。</para>
		/// </summary>
		public void RefreshCurrentProfile()
		{
			int currentProfileIdFromGame = GetCurrentProfileIdFromGame();
			if (currentProfileIdFromGame != CurrentProfileId)
			{
				OnProfileChanged(currentProfileIdFromGame);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Returns the account-level, profile-independent mod-data root for <paramref name="modId" />.</para>
		///     <para xml:lang="zh-CN">返回 <paramref name="modId" /> 的账户级模组数据根目录；该目录不属于特定档案。</para>
		/// </summary>
		public static string GetAccountBasePath(string modId = "com.ritsukage.sts2-RitsuLib")
		{
			return GetAccountRootPath() + "/mod_data/" + modId;
		}

		internal static string GetAccountRootPath()
		{
			try
			{
				SaveManager val = MockSaveManager(null) ?? ActiveSaveManager(null);
				if (val != null)
				{
					string fullPath = SaveStore(val).GetFullPath(string.Empty);
					if (!string.IsNullOrWhiteSpace(fullPath))
					{
						return fullPath.Replace('\\', '/').TrimEnd('/');
					}
				}
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
			}
			return UserDataPathProvider.GetAccountScopedBasePath((string)null, (PlatformType?)null, (ulong?)null).Replace('\\', '/').TrimEnd('/');
		}

		/// <summary>
		///     <para xml:lang="en">Returns the profile subdirectory path for <see cref="P:STS2RitsuLib.Utils.Persistence.ProfileManager.CurrentProfileId" />.</para>
		///     <para xml:lang="zh-CN">返回 <see cref="P:STS2RitsuLib.Utils.Persistence.ProfileManager.CurrentProfileId" /> 的档案子目录路径。</para>
		/// </summary>
		public string GetProfileDirectory()
		{
			return GetProfileDirectory(CurrentProfileId);
		}

		/// <summary>
		///     <para xml:lang="en">Returns the game's relative profile directory name for <paramref name="profileId" />.</para>
