		/// <summary>
		///     <para xml:lang="en">
		///         Deletes all profile-scoped mod-data files for <paramref name="profileId" /> and
		///         <paramref name="modId" />.
		///     </para>
		///     <para xml:lang="zh-CN">删除 <paramref name="profileId" /> 和 <paramref name="modId" /> 对应的所有档案作用域模组数据文件。</para>
		/// </summary>
		public static void DeleteProfileData(int profileId, string modId = "com.ritsukage.sts2-RitsuLib")
		{
			string basePath = GetBasePath(SaveScope.Profile, profileId, modId);
			RitsuLibFramework.Logger.Info($"[Persistence] Deleting mod data for profile {profileId} at: {basePath}", 1);
			try
			{
				FileOperations.WriteResult writeResult = FileOperations.DeleteDirectoryRecursive(basePath);
				if (!writeResult.Success)
				{
					RitsuLibFramework.Logger.ErrorNoTrace($"[Persistence] Failed to delete mod data for profile {profileId}: {writeResult.ErrorMessage}");
				}
				else
				{
					RitsuLibFramework.Logger.Info($"[Persistence] Successfully deleted mod data for profile {profileId}", 1);
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[Persistence] Failed to delete mod data for profile {profileId}: {ex.Message}");
			}
		}

