	internal static class RitsuLibDataPaths
	{
		private static readonly Lock StorageDirectoryGate;

		private static readonly string SharedCacheRootPath;

		private static readonly string SessionDirectoryName;

		private static bool _staleSessionsCleaned;

		internal static readonly string SharedCacheDirectory;

		internal static string ModDataDirectory
		{
			get
			{
				string accountBasePath = ProfileManager.GetAccountBasePath();
				if (!accountBasePath.StartsWith("user://", StringComparison.OrdinalIgnoreCase))
				{
					return Path.GetFullPath(accountBasePath);
				}
				return ProjectSettings.GlobalizePath(accountBasePath);
			}
		}

		internal static string TemporaryDirectory { get; }

		static RitsuLibDataPaths()
		{
			StorageDirectoryGate = new Lock();
			SharedCacheRootPath = ResolveSharedCacheRootPath();
			SessionDirectoryName = $"session-{Environment.ProcessId}-{Guid.NewGuid():N}";
			TemporaryDirectory = Path.Combine(SharedCacheRootPath, SessionDirectoryName);
			SharedCacheDirectory = SharedCacheRootPath;
			AppDomain.CurrentDomain.ProcessExit += OnProcessExit;
		}

		internal static string EnsureSharedCacheDirectory()
		{
			using (StorageDirectoryGate.EnterScope())
			{
				EnsurePrivateDirectory(SharedCacheRootPath);
				if (!_staleSessionsCleaned)
				{
					CleanupStaleSessions(SharedCacheRootPath);
					_staleSessionsCleaned = true;
				}
				return SharedCacheRootPath;
			}
		}

		internal static string EnsureTemporaryDirectory()
		{
			EnsureSharedCacheDirectory();
			using (StorageDirectoryGate.EnterScope())
			{
				EnsurePrivateDirectory(TemporaryDirectory);
				return TemporaryDirectory;
			}
		}

		internal static async Task<FileStream> AcquireSharedCacheLockAsync(string fileName, CancellationToken cancellationToken)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(fileName, "fileName");
			string path = Path.Combine(EnsureSharedCacheDirectory(), fileName);
			while (true)
			{
				cancellationToken.ThrowIfCancellationRequested();
				try
				{
					return new FileStream(path, FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.None, 1, FileOptions.Asynchronous);
				}
				catch (IOException)
				{
					await Task.Delay(100, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				}
			}
		}

		internal static string CreateTemporaryDirectory(string prefix)
		{
			string text = Path.Combine(EnsureTemporaryDirectory(), $"{prefix}-{Guid.NewGuid():N}");
			EnsurePrivateDirectory(text);
			return text;
		}

		private static string ResolveSharedCacheRootPath()
		{
			string cacheDir = OS.GetCacheDir();
			if (string.IsNullOrWhiteSpace(cacheDir))
			{
				throw new InvalidOperationException("The operating-system cache directory is unavailable.");
			}
			return Path.Combine(Path.GetFullPath(cacheDir), "com.ritsukage.sts2-RitsuLib");
		}

		private static void CleanupStaleSessions(string root)
		{
			try
			{
				foreach (string item in Directory.EnumerateDirectories(root, "session-*", SearchOption.TopDirectoryOnly))
				{
					string[] array = Path.GetFileName(item).Split('-', 3);
					if (array.Length == 3 && int.TryParse(array[1], out var result) && !IsProcessRunning(result))
					{
						TryDeleteDirectory(item);
					}
				}
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[Storage] Failed to clean stale temporary data: " + ex.Message, 1);
			}
		}

		private static void EnsurePrivateDirectory(string path)
		{
			if (OperatingSystem.IsWindows())
			{
				Directory.CreateDirectory(path);
				return;
			}
			Directory.CreateDirectory(path, UnixFileMode.UserExecute | UnixFileMode.UserWrite | UnixFileMode.UserRead);
			File.SetUnixFileMode(path, UnixFileMode.UserExecute | UnixFileMode.UserWrite | UnixFileMode.UserRead);
		}

		private static bool IsProcessRunning(int processId)
		{
			try
			{
				using Process process = Process.GetProcessById(processId);
				return !process.HasExited;
			}
			catch (ArgumentException)
			{
				return false;
			}
			catch (InvalidOperationException)
			{
				return false;
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				return true;
			}
		}

		private static void OnProcessExit(object? sender, EventArgs args)
		{
			TryDeleteDirectory(TemporaryDirectory);
		}

		private static void TryDeleteDirectory(string path)
		{
			try
			{
				if (Directory.Exists(path))
				{
					Directory.Delete(path, recursive: true);
				}
			}
			catch
			{
			}
		}
	}
	internal static class RitsuLibLegacyGeneratedDataCleanup
	{
		private const string LegacyFmodCachePath = "user://ritsulib/fmod-cache/audio";

		private const string LegacySelfCheckStagingDirectoryName = ".ritsulib-self-check-staging";

		private const string LegacyStateDivergenceStagingDirectoryName = ".ritsulib-state-divergence-staging";

		private const string LegacyCoreDumpPattern = "sts2_coredump_*.core";

		private static readonly TimeSpan ActiveCoreDumpProtection = TimeSpan.FromHours(1);

		private static int _cleanupAttempted;

		internal static void RunOnce()
		{
			if (Interlocked.Exchange(ref _cleanupAttempted, 1) != 1)
			{
				int removedItems = 0;
				CleanupLegacyFmodCache(ref removedItems);
				string text = ResolveLegacyUserDataDirectory();
				CleanupDirectory(Path.Combine(text, ".ritsulib-state-divergence-staging"), ref removedItems);
				CleanupSelfCheckStaging(text, ref removedItems);
				CleanupLegacySteamInputManifest(ref removedItems);
				CleanupLegacyCoreDumps(ref removedItems);
				if (removedItems > 0)
				{
					RitsuLibFramework.Logger.Info($"[Storage] Removed {removedItems} obsolete generated-data item(s) from earlier RitsuLib versions.", 1);
				}
			}
		}

		private static void CleanupLegacyFmodCache(ref int removedItems)
		{
			string path = ProjectSettings.GlobalizePath("user://ritsulib/fmod-cache/audio");
			CleanupDirectory(path, ref removedItems);
			CleanupEmptyDirectory(Path.GetDirectoryName(path));
			CleanupEmptyDirectory(Path.GetDirectoryName(Path.GetDirectoryName(path)));
		}

		private static void CleanupSelfCheckStaging(string userDataDirectory, ref int removedItems)
		{
			CleanupDirectory(Path.Combine(userDataDirectory, ".ritsulib-self-check-staging"), ref removedItems);
			string text = SelfCheckBundleWriter.TryResolveOutputDirectory(RitsuLibSettingsStore.GetSelfCheckOptions().OutputFolder);
			if (text != null)
			{
				CleanupDirectory(Path.Combine(Directory.GetParent(text)?.FullName ?? text, ".ritsulib-self-check-staging"), ref removedItems);
			}
		}

		private static void CleanupLegacySteamInputManifest(ref int removedItems)
		{
			string text = OS.GetUserDataDir();
			if (string.IsNullOrWhiteSpace(text))
			{
				text = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "SlayTheSpire2");
			}
			string text2 = Path.Combine(text, "mods", "RitsuLib");
			CleanupDirectory(Path.Combine(text2, "steam_input"), ref removedItems);
			CleanupEmptyDirectory(text2);
		}

		private static void CleanupLegacyCoreDumps(ref int removedItems)
		{
			DateTime cutoff = DateTime.UtcNow - ActiveCoreDumpProtection;
			try
			{
				foreach (string item in Directory.EnumerateFiles(Path.GetTempPath(), "sts2_coredump_*.core", SearchOption.TopDirectoryOnly))
				{
					CleanupLegacyCoreDump(item, cutoff, ref removedItems);
				}
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				LogCleanupFailure(Path.GetTempPath(), exception);
			}
		}

		private static void CleanupLegacyCoreDump(string path, DateTime cutoff, ref int removedItems)
		{
			try
			{
				if (!(File.GetLastWriteTimeUtc(path) > cutoff))
				{
					File.Delete(path);
					removedItems++;
				}
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				LogCleanupFailure(path, exception);
			}
		}

		private static string ResolveLegacyUserDataDirectory()
		{
			string userDataDir = OS.GetUserDataDir();
			if (!string.IsNullOrWhiteSpace(userDataDir))
			{
				return userDataDir;
			}
			return AppContext.BaseDirectory;
		}

		private static void CleanupDirectory(string path, ref int removedItems)
		{
			try
			{
				if (Directory.Exists(path))
				{
					Directory.Delete(path, recursive: true);
					removedItems++;
				}
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				LogCleanupFailure(path, exception);
			}
		}

		private static void CleanupEmptyDirectory(string? path)
		{
			if (string.IsNullOrWhiteSpace(path))
			{
				return;
			}
			try
			{
				if (Directory.Exists(path) && !Directory.EnumerateFileSystemEntries(path).Any())
				{
					Directory.Delete(path);
				}
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				LogCleanupFailure(path, exception);
			}
		}

		private static void LogCleanupFailure(string path, Exception exception)
		{
			RitsuLibFramework.Logger.Warn("[Storage] Failed to remove obsolete generated data at '" + path + "': " + exception.Message, 1);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Defines the storage scope of saved data.</para>
	///     <para xml:lang="zh-CN">定义存档数据的存储作用域。</para>
	/// </summary>
	public enum SaveScope
	{
		/// <summary>
		///     <para xml:lang="en">Data is shared across all profiles.</para>
		///     <para xml:lang="zh-CN">数据在所有档案之间共享。</para>
		/// </summary>
		Global,
		/// <summary>
		///     <para xml:lang="en">Data is specific to one profile.</para>
		///     <para xml:lang="zh-CN">数据专属于一个档案。</para>
		/// </summary>
		Profile,
		/// <summary>
		///     <para xml:lang="en">Data is held only in memory and is not persisted.</para>
		///     <para xml:lang="zh-CN">数据仅保留在内存中且不会持久化。</para>
		/// </summary>
		InMemory
	}
	/// <summary>
	///     <para xml:lang="en">Resolves local user-storage paths for each <see cref="T:STS2RitsuLib.Utils.Persistence.SaveScope" />.</para>
	///     <para xml:lang="zh-CN">根据 <see cref="T:STS2RitsuLib.Utils.Persistence.SaveScope" /> 解析本地用户存储路径。</para>
	/// </summary>
	internal static class StoragePathResolver
	{
		public static string ResolveBasePathUser(string modId, SaveScope scope, StorageContext? context = null)
		{
			if (context == null)
			{
				context = StorageContext.Empty;
			}
			int profileId = ResolveProfileId(context);
			string accountBasePath = ProfileManager.GetAccountBasePath(modId);
			return scope switch
			{
				SaveScope.Global => accountBasePath, 
				SaveScope.Profile => accountBasePath + "/" + ProfileManager.GetProfileDirectory(profileId), 
				_ => accountBasePath, 
			};
		}

		public static string ResolveFilePathUser(string modId, string fileName, SaveScope scope, StorageContext? context = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(fileName, "fileName");
			return ResolveBasePathUser(modId, scope, context) + "/" + fileName;
		}

		private static int ResolveProfileId(StorageContext context)
		{
			if (!context.TryGet(StorageContextKeys.ProfileId, out var value))
			{
				return ProfileManager.Instance.CurrentProfileId;
			}
			return value;
		}
	}
