	internal static class StorageSyncPathEnumerator
	{
		internal static void CollectWhitelistedRelativePaths(int profileId, HashSet<string> sink, ModCloudSyncScope scope)
		{
			ModCloudSyncPathRegistry.CollectRegisteredRelativePaths(profileId, sink, scope);
		}
	}
}
namespace STS2RitsuLib.Utils.Persistence.Patches
{
	/// <summary>
	///     <para xml:lang="en">Groups game-profile lifecycle patches that schedule reconciliation of local and cloud mod data.</para>
	///     <para xml:lang="zh-CN">汇集在游戏档案生命周期中安排本地与云端模组数据协调同步的补丁。</para>
	/// </summary>
	internal static class ModDataCloudSyncPatches
	{
		internal sealed class AfterInitProfileId : IPatchMethod
		{
			public static string PatchId => "ritsulib_mod_data_cloud_after_init_profile";

			public static bool IsCritical => false;

			public static string Description => "Defer async reconcile of mod_data with Steam cloud after profile id init (non-blocking)";

			public static ModPatchTarget[] GetTargets()
			{
				return new ModPatchTarget[1]
				{
					new ModPatchTarget(typeof(SaveManager), "InitProfileId", new Type[1] { typeof(int?) })
				};
			}

			public static void Postfix()
			{
				ModDataCloudMirror.ScheduleReconcileModDataWithCloud();
			}
		}

		internal sealed class AfterSwitchProfileId : IPatchMethod
		{
			public static string PatchId => "ritsulib_mod_data_cloud_after_switch_profile";

			public static bool IsCritical => false;

			public static string Description => "Defer async reconcile of mod_data with Steam cloud after switching save profile";

			public static ModPatchTarget[] GetTargets()
			{
				return new ModPatchTarget[1]
				{
					new ModPatchTarget(typeof(SaveManager), "SwitchProfileId", new Type[1] { typeof(int) })
				};
			}

			public static void Postfix()
			{
				ModDataCloudMirror.ScheduleReconcileModDataWithCloud();
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Cleans up persistent mod data when the game deletes a save profile.</para>
	///     <para xml:lang="zh-CN">游戏删除档案时清理模组持久化数据。</para>
	/// </summary>
	internal class ProfileDeletePatch : IPatchMethod
	{
		public static string PatchId => "profile_delete";

		public static string Description => "Delete mod data when game profile is deleted";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(SaveManager), "DeleteProfile", new Type[1] { typeof(int) })
			};
		}

		public static void Prefix(int profileId)
		{
			try
			{
				ModDataCloudMirror.ScheduleDeleteCloudModDataForProfile(profileId);
				ModDataStore.DeleteAllProfileData(profileId);
				ProfileManager.Instance.OnProfileDeleted(profileId);
				DataReadyLifecycle.NotifyProfileInvalidated(profileId, "SaveManager.DeleteProfile");
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[Persistence] Failed to delete mod data for profile {profileId}: {ex.Message}", 1);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Notifies <see cref="T:STS2RitsuLib.Utils.Persistence.DataReadyLifecycle" /> after <see cref="T:MegaCrit.Sts2.Core.Saves.SaveManager" /> initializes or
	///         switches the profile path, establishing the trigger point for safe data operations.
	///     </para>
	///     <para xml:lang="zh-CN">在 <see cref="T:MegaCrit.Sts2.Core.Saves.SaveManager" /> 初始化或切换档案路径后通知 <see cref="T:STS2RitsuLib.Utils.Persistence.DataReadyLifecycle" />，作为安全执行数据操作的触发点。</para>
	/// </summary>
	internal class ProfilePathInitializedPatch : IPatchMethod
	{
		public static string PatchId => "profile_path_initialized";

		public static string Description => "Notify safe data-ready lifecycle after profile path initialization";

		public static bool IsCritical => true;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[2]
			{
				new ModPatchTarget(typeof(SaveManager), "InitProfileId", new Type[1] { typeof(int?) }),
				new ModPatchTarget(typeof(SaveManager), "SwitchProfileId", new Type[1] { typeof(int) })
			};
		}

		public static void Postfix()
		{
			try
			{
				DataReadyLifecycle.NotifyPotentialReady("SaveManager.InitProfileId/SwitchProfileId");
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Persistence] Failed to process profile path initialized hook: " + ex.Message, 1);
			}
		}
	}
}
namespace STS2RitsuLib.Utils.Persistence.Migration
{
	/// <summary>
	///     <para xml:lang="en">Defines a JSON-object data migration between two schema versions.</para>
	///     <para xml:lang="zh-CN">定义两个架构版本之间的 JSON 对象数据迁移。</para>
	/// </summary>
	public interface IMigration
	{
		/// <summary>
		///     <para xml:lang="en">Inclusive lower bound of the source schema versions handled by this migration.</para>
		///     <para xml:lang="zh-CN">此迁移可处理的源架构版本下限，包含该版本。</para>
		/// </summary>
		int FromVersion { get; }

		/// <summary>
		///     <para xml:lang="en">Schema version produced by this migration.</para>
		///     <para xml:lang="zh-CN">此迁移生成的架构版本。</para>
		/// </summary>
		int ToVersion { get; }

		/// <summary>
		///     <para xml:lang="en">Performs the migration on the JSON data.</para>
		///     <para xml:lang="zh-CN">对 JSON 数据执行迁移。</para>
		/// </summary>
		/// <param name="data">
		///     <para xml:lang="en">JSON data to migrate.</para>
		///     <para xml:lang="zh-CN">要迁移的 JSON 数据。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> if the migration succeeds; otherwise, <see langword="false" />.</para>
		///     <para xml:lang="zh-CN">迁移成功时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		bool Migrate(JsonObject data);
	}
	/// <summary>
	///     <para xml:lang="en">Coordinates schema-version migrations for persisted data types.</para>
	///     <para xml:lang="zh-CN">协调持久化数据类型的架构版本迁移。</para>
	/// </summary>
	public class MigrationManager
	{
		private class MigrationConfig
		{
			public int CurrentVersion { get; init; }

			public int MinimumSupportedVersion { get; init; }

			public string SchemaVersionProperty { get; init; } = "schema_version";
		}

		private readonly Dictionary<Type, MigrationConfig> _configs = new Dictionary<Type, MigrationConfig>();

		private readonly Dictionary<Type, List<IMigration>> _migrations = new Dictionary<Type, List<IMigration>>();

		/// <summary>
		///     <para xml:lang="en">Registers migration configuration for a data type.</para>
		///     <para xml:lang="zh-CN">为数据类型注册迁移配置。</para>
		/// </summary>
		public void RegisterConfig<T>(int currentVersion, int minimumSupportedVersion, string schemaVersionProperty = "schema_version")
		{
			_configs[typeof(T)] = new MigrationConfig
			{
				CurrentVersion = currentVersion,
				MinimumSupportedVersion = minimumSupportedVersion,
				SchemaVersionProperty = schemaVersionProperty
			};
		}

		/// <summary>
		///     <para xml:lang="en">Registers a migration for a data type.</para>
		///     <para xml:lang="zh-CN">为数据类型注册迁移。</para>
		/// </summary>
		public void RegisterMigration<T>(IMigration migration)
		{
			Type typeFromHandle = typeof(T);
			if (!_migrations.ContainsKey(typeFromHandle))
			{
				_migrations[typeFromHandle] = new List<IMigration>();
			}
			_migrations[typeFromHandle].Add(migration);
			_migrations[typeFromHandle].Sort(delegate(IMigration a, IMigration b)
			{
				int num = a.FromVersion.CompareTo(b.FromVersion);
				return (num == 0) ? a.ToVersion.CompareTo(b.ToVersion) : num;
			});
		}

		/// <summary>
		///     <para xml:lang="en">Attempts to deserialize JSON data and migrate it to the configured current version.</para>
		///     <para xml:lang="zh-CN">尝试反序列化 JSON 数据，并将其迁移到配置的当前版本。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">Result containing the deserialized, optionally migrated data or error information.</para>
		///     <para xml:lang="zh-CN">包含反序列化后（可能已迁移）的数据或错误信息的结果。</para>
		/// </returns>
		public MigrationResult<T> Migrate<T>(string jsonContent, JsonSerializerOptions? options = null) where T : class, new()
		{
			Type typeFromHandle = typeof(T);
			if (!_configs.TryGetValue(typeFromHandle, out MigrationConfig value))
			{
				return DeserializeWithoutMigration<T>(jsonContent, options);
			}
			try
			{
				if (!(JsonNode.Parse(jsonContent) is JsonObject jsonObject))
				{
					return new MigrationResult<T>
					{
						Success = false,
						ErrorMessage = "Invalid JSON: root must be an object"
					};
				}
				int num = GetVersion(jsonObject, value.SchemaVersionProperty);
				if (num < value.MinimumSupportedVersion)
				{
					return new MigrationResult<T>
					{
						Success = false,
						ErrorMessage = $"Data version {num} is below minimum supported version {value.MinimumSupportedVersion}",
						RequiresRecovery = true
					};
				}
				if (num > value.CurrentVersion)
				{
					return new MigrationResult<T>
					{
						Success = false,
						ErrorMessage = $"Data version {num} is newer than current version {value.CurrentVersion}"
					};
				}
				List<IMigration> migrations = (_migrations.TryGetValue(typeFromHandle, out List<IMigration> value2) ? value2 : new List<IMigration>());
				if (!TryBuildShortestMigrationPath(num, value.CurrentVersion, migrations, out List<IMigration> path))
				{
					return new MigrationResult<T>
					{
						Success = false,
						ErrorMessage = $"No migration path from data version {num} to current version {value.CurrentVersion} for {typeFromHandle.Name}."
					};
				}
				for (int i = 0; i < path.Count; i++)
				{
					IMigration migration = path[i];
					RitsuLibFramework.Logger.Info($"Applying migration {migration.FromVersion} -> {migration.ToVersion} for {typeFromHandle.Name} (shortest path: step {i + 1}/{path.Count})", 1);
					if (!migration.Migrate(jsonObject))
					{
						return new MigrationResult<T>
						{
							Success = false,
							ErrorMessage = $"Migration {migration.FromVersion} -> {migration.ToVersion} failed"
						};
					}
					num = migration.ToVersion;
					SetVersion(jsonObject, value.SchemaVersionProperty, num);
				}
				T val = JsonSerializer.Deserialize<T>(jsonObject.ToJsonString(), options);
				if (val == null)
				{
					return new MigrationResult<T>
					{
						Success = false,
						ErrorMessage = "Deserialization resulted in null"
					};
				}
				return new MigrationResult<T>
				{
					Success = true,
					Data = val,
					WasMigrated = (num != GetVersion(JsonNode.Parse(jsonContent) as JsonObject, value.SchemaVersionProperty)),
					FinalVersion = num
				};
			}
			catch (JsonException ex)
			{
				return new MigrationResult<T>
				{
					Success = false,
					ErrorMessage = "JSON parsing error: " + ex.Message,
					RequiresRecovery = true
				};
			}
			catch (Exception ex2)
			{
				return new MigrationResult<T>
				{
					Success = false,
					ErrorMessage = "Migration error: " + ex2.Message
				};
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets the configured current schema version for a data type.</para>
		///     <para xml:lang="zh-CN">获取为数据类型配置的当前架构版本。</para>
		/// </summary>
		public int GetCurrentVersion<T>()
		{
			if (!_configs.TryGetValue(typeof(T), out MigrationConfig value))
			{
				return 0;
			}
			return value.CurrentVersion;
		}

		private static MigrationResult<T> DeserializeWithoutMigration<T>(string jsonContent, JsonSerializerOptions? options) where T : class, new()
		{
			try
			{
				T val = JsonSerializer.Deserialize<T>(jsonContent, options);
				return (val == null) ? new MigrationResult<T>
				{
					Success = false,
					ErrorMessage = "Deserialization resulted in null"
				} : new MigrationResult<T>
				{
					Success = true,
					Data = val
				};
			}
			catch (JsonException ex)
			{
				return new MigrationResult<T>
				{
					Success = false,
					ErrorMessage = "JSON parsing error: " + ex.Message,
					RequiresRecovery = true
				};
			}
			catch (Exception ex2)
			{
				return new MigrationResult<T>
				{
					Success = false,
					ErrorMessage = "Deserialization error: " + ex2.Message
				};
			}
		}

		private static int GetVersion(JsonObject? obj, string propertyName)
		{
			if (obj == null)
			{
				return 0;
			}
			if (!obj.TryGetPropertyValue(propertyName, out JsonNode jsonNode) || jsonNode == null)
			{
				return 0;
			}
			return jsonNode.GetValue<int>();
		}

		private static void SetVersion(JsonObject obj, string propertyName, int version)
		{
			obj[propertyName] = version;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Finds a shortest migration path from <paramref name="startVersion" /> to
		///         <paramref name="targetVersion" /> by breadth-first search. A migration may run when the current version is in
		///         <c>[FromVersion, ToVersion)</c>, and migrations that overshoot the target are ignored. Equally short paths
		///         follow the order of <paramref name="migrations" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过广度优先搜索查找从 <paramref name="startVersion" /> 到 <paramref name="targetVersion" />
		///         的最短迁移路径。当前版本位于 <c>[FromVersion, ToVersion)</c> 时迁移可执行，超过目标版本的迁移会被忽略。长度相同的路径按 <paramref name="migrations" />
		///         中的顺序选择。
		///     </para>
		/// </summary>
		internal static bool TryBuildShortestMigrationPath(int startVersion, int targetVersion, List<IMigration> migrations, out List<IMigration> path)
		{
			path = new List<IMigration>();
			if (startVersion == targetVersion)
			{
				return true;
			}
			Queue<int> queue = new Queue<int>();
			HashSet<int> hashSet = new HashSet<int>();
			Dictionary<int, (int, IMigration)> dictionary = new Dictionary<int, (int, IMigration)>();
			queue.Enqueue(startVersion);
			hashSet.Add(startVersion);
			bool flag = false;
			while (queue.Count > 0 && !flag)
			{
				int num = queue.Dequeue();
				foreach (IMigration migration in migrations)
				{
					if (num < migration.FromVersion || num >= migration.ToVersion)
					{
						continue;
					}
					int toVersion = migration.ToVersion;
					if (toVersion <= targetVersion && hashSet.Add(toVersion))
					{
						dictionary[toVersion] = (num, migration);
						if (toVersion == targetVersion)
						{
							flag = true;
							break;
						}
						queue.Enqueue(toVersion);
					}
				}
			}
			if (!flag)
			{
				return false;
			}
			path = new List<IMigration>();
			int num2 = targetVersion;
			while (num2 != startVersion)
			{
				var (num3, item) = dictionary[num2];
				path.Add(item);
				num2 = num3;
			}
			path.Reverse();
			return true;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Outcome of a JSON deserialization and optional migration operation.</para>
	///     <para xml:lang="zh-CN">JSON 反序列化及可选迁移操作的结果。</para>
	/// </summary>
	public class MigrationResult<T>
	{
		/// <summary>
		///     <para xml:lang="en"><see langword="true" /> when JSON deserialization and any required migrations succeeded.</para>
		///     <para xml:lang="zh-CN">JSON 反序列化及所有必要迁移均成功时为 <see langword="true" />。</para>
		/// </summary>
		public bool Success { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Deserialized, optionally migrated instance when <see cref="P:STS2RitsuLib.Utils.Persistence.Migration.MigrationResult`1.Success" /> is
		///         <see langword="true" />.
		///     </para>
		///     <para xml:lang="zh-CN"><see cref="P:STS2RitsuLib.Utils.Persistence.Migration.MigrationResult`1.Success" /> 为 <see langword="true" /> 时反序列化得到的实例；该实例可能已经迁移。</para>
		/// </summary>
		public T? Data { get; init; }

		/// <summary>
		///     <para xml:lang="en">Failure explanation when <see cref="P:STS2RitsuLib.Utils.Persistence.Migration.MigrationResult`1.Success" /> is <see langword="false" />.</para>
		///     <para xml:lang="zh-CN"><see cref="P:STS2RitsuLib.Utils.Persistence.Migration.MigrationResult`1.Success" /> 为 <see langword="false" /> 时的失败说明。</para>
		/// </summary>
		public string? ErrorMessage { get; init; }

		/// <summary>
		///     <para xml:lang="en"><see langword="true" /> when at least one migration step ran.</para>
		///     <para xml:lang="zh-CN">至少执行了一个迁移步骤时为 <see langword="true" />。</para>
		/// </summary>
		public bool WasMigrated { get; init; }

		/// <summary>
		///     <para xml:lang="en">Final schema version reported for a configured migration operation.</para>
		///     <para xml:lang="zh-CN">已配置迁移操作所报告的最终架构版本。</para>
		/// </summary>
		public int FinalVersion { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         <see langword="true" /> when malformed JSON or an obsolete schema version indicates that the
		///         stored file should be quarantined or reset.
		///     </para>
		///     <para xml:lang="zh-CN">JSON 格式错误或架构版本过旧，表明应隔离或重置存储文件时为 <see langword="true" />。</para>
		/// </summary>
		public bool RequiresRecovery { get; init; }
	}
	/// <summary>
	///     <para xml:lang="en">Declares the JSON schema versions supported by a persistent mod-data type.</para>
	///     <para xml:lang="zh-CN">声明一种持久化模组数据类型所支持的 JSON 架构版本。</para>
	/// </summary>
	public sealed class ModDataMigrationConfig
	{
		/// <summary>
		///     <para xml:lang="en">Current schema version targeted by migration.</para>
		///     <para xml:lang="zh-CN">迁移所面向的当前架构版本。</para>
		/// </summary>
		public required int CurrentDataVersion { get; init; }

		/// <summary>
		///     <para xml:lang="en">Oldest schema version that can still be migrated; older versions require recovery.</para>
		///     <para xml:lang="zh-CN">仍可迁移的最旧架构版本；更早的版本需要执行恢复。</para>
		/// </summary>
		public int MinimumSupportedDataVersion { get; init; }

		/// <summary>
		///     <para xml:lang="en">JSON property name that stores the integer schema version.</para>
		///     <para xml:lang="zh-CN">存储整数架构版本的 JSON 属性名。</para>
		/// </summary>
		public string SchemaVersionProperty { get; init; } = "schema_version";
	}
	/// <summary>
	///     <para xml:lang="en">Provides shared constants for mod-data JSON schema versioning.</para>
	///     <para xml:lang="zh-CN">提供模组数据 JSON 架构版本控制使用的共享常量。</para>
	/// </summary>
	public static class ModDataVersion
	{
		/// <summary>
		///     <para xml:lang="en">Default JSON property name for the persisted schema-version integer.</para>
		///     <para xml:lang="zh-CN">持久化架构版本整数的默认 JSON 属性名。</para>
		/// </summary>
		public const string SchemaVersionProperty = "schema_version";
	}
}
namespace STS2RitsuLib.Utils.Persistence.Interop
{
	/// <summary>
	///     <para xml:lang="en">
	///         Adapts an object that defines <c>FromVersion</c>, <c>ToVersion</c>, and
	///         <c>Migrate(JsonObject)</c> to <see cref="T:STS2RitsuLib.Utils.Persistence.Migration.IMigration" /> without requiring its type to reference RitsuLib.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将定义了 <c>FromVersion</c>、<c>ToVersion</c> 和 <c>Migrate(JsonObject)</c> 的对象适配为
	///         <see cref="T:STS2RitsuLib.Utils.Persistence.Migration.IMigration" />，而无需其类型引用 RitsuLib。
	///     </para>
	/// </summary>
	public sealed class InteropMigrationAdapter : IMigration
	{
		private readonly Func<JsonObject, bool> _migrate;

		/// <inheritdoc />
		public int FromVersion { get; }

		/// <inheritdoc />
		public int ToVersion { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Creates an adapter for an existing migration instance that defines the required version members
		///         and migration method.
		///     </para>
		///     <para xml:lang="zh-CN">为定义了所需版本成员和迁移方法的现有迁移实例创建适配器。</para>
		/// </summary>
		public InteropMigrationAdapter(object instance)
		{
			ArgumentNullException.ThrowIfNull(instance, "instance");
			Type type = instance.GetType();
			FromVersion = ReadIntMember(type, instance, "FromVersion");
			ToVersion = ReadIntMember(type, instance, "ToVersion");
			MethodInfo method = type.GetMethod("Migrate", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, new Type[1] { typeof(JsonObject) });
			if (method == null || method.ReturnType != typeof(bool))
			{
				throw new InvalidOperationException("Migration type '" + type.FullName + "' must declare 'bool Migrate(JsonObject data)'.");
			}
			_migrate = (Func<JsonObject, bool>)Delegate.CreateDelegate(typeof(Func<JsonObject, bool>), instance, method);
		}

		/// <inheritdoc />
		public bool Migrate(JsonObject data)
		{
			return _migrate(data);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to invoke a parameterless constructor for the migration type and wrap the resulting
		///         instance.
		///     </para>
		///     <para xml:lang="zh-CN">尝试调用迁移类型的无参构造函数，并包装所创建的实例。</para>
		/// </summary>
		public static bool TryCreateFromType(Type migrationType, out InteropMigrationAdapter? adapter)
		{
			adapter = null;
			try
			{
				if ((object)migrationType == null || !migrationType.IsClass || migrationType.IsAbstract)
				{
					return false;
				}
				if (migrationType.GetConstructor(Type.EmptyTypes) == null)
				{
					return false;
				}
				object obj = Activator.CreateInstance(migrationType);
				if (obj == null)
				{
					return false;
				}
				adapter = new InteropMigrationAdapter(obj);
				return true;
			}
			catch
			{
				adapter = null;
				return false;
			}
		}

		private static int ReadIntMember(Type type, object instance, string name)
		{
			PropertyInfo property = type.GetProperty(name, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (property != null && property.PropertyType == typeof(int))
			{
				return (int)(property.GetValue(instance) ?? ((object)0));
			}
			FieldInfo field = type.GetField(name, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (field != null && field.FieldType == typeof(int))
			{
				return (int)(field.GetValue(instance) ?? ((object)0));
			}
			throw new InvalidOperationException($"Migration type '{type.FullName}' must expose int '{name}' as property or field.");
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Wraps a JSON DOM for persistence through <see cref="T:STS2RitsuLib.Data.ModDataStore" />.
	///         <see cref="P:STS2RitsuLib.Utils.Persistence.Interop.ModDataInteropJsonDocument.Root" /> contains the logical document, while the serialized wrapper may also contain schema-version
	///         metadata.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         封装通过 <see cref="T:STS2RitsuLib.Data.ModDataStore" /> 持久化的 JSON DOM。<see cref="P:STS2RitsuLib.Utils.Persistence.Interop.ModDataInteropJsonDocument.Root" />
	///         保存逻辑文档，序列化后的包装器还可包含架构版本元数据。
	///     </para>
	/// </summary>
	public sealed class ModDataInteropJsonDocument
	{
		/// <summary>
		///     <para xml:lang="en">Logical JSON DOM migrated and synchronized with interoperability providers.</para>
		///     <para xml:lang="zh-CN">参与迁移并与互操作提供程序同步的逻辑 JSON DOM。</para>
		/// </summary>
		public JsonNode? Root { get; set; } = new JsonObject();
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides JSON Pointer and JSON Merge Patch primitives used by runtime mod-data
	///         interoperability.
	///     </para>
	///     <para xml:lang="zh-CN">提供运行时模组数据互操作所用的 JSON 指针和 JSON 合并补丁基础操作。</para>
	/// </summary>
	internal static class ModDataJsonInteropPrimitives
	{
		internal static bool IsRootPointer(string? pointer)
		{
			return JsonPointer.IsRoot(pointer);
		}

		internal static JsonNode? GetNodeAt(JsonNode root, string jsonPointer)
		{
			return JsonPointer.Get(root, jsonPointer);
		}

		internal static void SetNodeAt(JsonObject documentRoot, string jsonPointer, JsonNode? value)
		{
			JsonPointer.Set(documentRoot, jsonPointer, value);
		}

		internal static void MergeObjectAt(JsonObject documentRoot, string jsonPointer, JsonObject mergePatch)
		{
			if (IsRootPointer(jsonPointer))
			{
				MergePatch7386(documentRoot, mergePatch);
				return;
			}
			if (GetNodeAt(documentRoot, jsonPointer) is JsonObject target)
			{
				MergePatch7386(target, mergePatch);
				return;
			}
			JsonObject jsonObject = new JsonObject();
			MergePatch7386(jsonObject, mergePatch);
			SetNodeAt(documentRoot, jsonPointer, jsonObject);
		}

		internal static void MergePatch7386(JsonObject target, JsonObject patch)
		{
			JsonMergePatch.ApplyInPlace(target, patch);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Discovers runtime mod-data interoperability providers and connects their data slots to RitsuLib
	///         persistence.
	///     </para>
	///     <para xml:lang="zh-CN">发现运行时模组数据互操作提供程序，并将其数据槽接入 RitsuLib 持久化系统。</para>
	/// </summary>
	internal static class RuntimeModDataInteropSource
	{
