		public static int TryRegisterAll()
		{
			using (Gate.EnterScope())
			{
				List<InteropProvider> list = DiscoverProviders();
				if (list.Count == 0)
				{
					return 0;
				}
				int num = 0;
				foreach (InteropProvider item2 in list)
				{
					try
					{
						string item = item2.ProviderType.FullName ?? item2.ProviderType.Name;
						if (!ProcessedProviderNames.Contains(item) && TryReadSchema(item2, out InteropSchemaRoot schema) && TryRegisterFromSchema(item2, schema))
						{
							ProcessedProviderNames.Add(item);
							num++;
						}
					}
					catch (Exception ex)
					{
						RitsuLibFramework.Logger.Warn("[RuntimeModDataInteropSource] Provider '" + item2.ProviderType.FullName + "' failed but was isolated: " + ex.Message, 1);
					}
				}
				return num;
			}
		}

		public static void SyncAllFromProviders()
		{
			InteropSlot[] array;
			using (Gate.EnterScope())
			{
				array = Slots.ToArray();
			}
			InteropSlot[] array2 = array;
			foreach (InteropSlot interopSlot in array2)
			{
				try
				{
					if (!ProviderAccessors.TryGetValue(interopSlot.ProviderKey, out ReflectionStaticChannel value))
					{
						continue;
					}
					ModDataStore modDataStore = ModDataStore.For(interopSlot.ModId);
					if (interopSlot.Scope != SaveScope.Profile || modDataStore.IsProfileInitialized)
					{
						if (interopSlot.IsJsonChannel)
						{
							SyncJsonSlot(modDataStore, interopSlot, value);
						}
						else
						{
							SyncTypedSlot(modDataStore, interopSlot.ModId, interopSlot.Key, interopSlot.DataType, value);
						}
					}
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[RuntimeModDataInteropSource] Sync failed for '{interopSlot.ModId}'::{interopSlot.Key}: {ex.Message}", 1);
				}
			}
		}

		public static void PushLoadedDataToAllProviders()
		{
			InteropSlot[] array;
			using (Gate.EnterScope())
			{
				array = Slots.ToArray();
			}
			InteropSlot[] array2 = array;
			foreach (InteropSlot interopSlot in array2)
			{
				try
				{
					if (!ProviderAccessors.TryGetValue(interopSlot.ProviderKey, out ReflectionStaticChannel value))
					{
						continue;
					}
					ModDataStore modDataStore = ModDataStore.For(interopSlot.ModId);
					if (interopSlot.Scope != SaveScope.Profile || modDataStore.IsProfileInitialized)
					{
						if (interopSlot.IsJsonChannel)
						{
							PushJsonChannel(modDataStore, interopSlot, value);
							continue;
						}
						object arg = CallGenericGet(modDataStore, interopSlot.Key, interopSlot.DataType);
						value.SetObject(interopSlot.Key, arg);
					}
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[RuntimeModDataInteropSource] Push-after-load failed for '{interopSlot.ModId}'::{interopSlot.Key}: {ex.Message}", 1);
				}
			}
			ApplyLoadedDataHooks();
		}

		private static void OnProfileChangedSyncFromProviders(int oldProfileId, int newProfileId)
