					Type type = assembly.GetType(item3, throwOnError: false);
					if (type == null)
					{
						RitsuLibFramework.Logger.Warn("[RuntimeModDataInteropSource] Provider type not found: " + assembly.GetName().Name + "::" + item3, 1);
						continue;
