					if (method == null)
					{
						RitsuLibFramework.Logger.Warn($"[RuntimeModDataInteropSource] Missing static method '{"CreateRitsuLibModDataSchema"}' on {type.FullName}.", 1);
					}
					else
					{
						string item = type.FullName ?? type.Name;
						if (hashSet.Add(item))
						{
							list.Add(new InteropProvider(type, method));
						}
					}
				}
			}
			foreach (var (providerTypeName, assemblyName) in RuntimeRegisteredProviderTypes)
			{
				Type type2 = ResolveProviderType(providerTypeName, assemblyName);
				if (type2 == null)
				{
					continue;
				}
				MethodInfo method2 = type2.GetMethod("CreateRitsuLibModDataSchema", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
				if (!(method2 == null))
				{
					string item2 = type2.FullName ?? type2.Name;
					if (hashSet.Add(item2))
					{
						list.Add(new InteropProvider(type2, method2));
					}
				}
			}
			return list;
		}

		private static Type? ResolveProviderType(string providerTypeName, string? assemblyName)
		{
			if (string.IsNullOrWhiteSpace(assemblyName))
			{
				return (from asm in AppDomain.CurrentDomain.GetAssemblies()
					select asm.GetType(providerTypeName, throwOnError: false)).OfType<Type>().FirstOrDefault();
			}
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly assembly in assemblies)
			{
				if (string.Equals(assembly.GetName().Name, assemblyName, StringComparison.OrdinalIgnoreCase))
				{
					Type type = assembly.GetType(providerTypeName, throwOnError: false);
					if (type != null)
					{
						return type;
					}
				}
			}
			return (from asm in AppDomain.CurrentDomain.GetAssemblies()
				select asm.GetType(providerTypeName, throwOnError: false)).OfType<Type>().FirstOrDefault();
		}

