		private static bool TryResolveMigrationTypeName(object? raw, out string? typeName)
		{
			typeName = null;
			if (raw is string text && !string.IsNullOrWhiteSpace(text))
			{
				typeName = text.Trim();
				return true;
			}
			if (raw == null || !TryAsMap(raw, out IDictionary<string, object> map))
			{
				return false;
			}
			if (!TryGetString(map, "type", out string value) || string.IsNullOrWhiteSpace(value))
			{
				return false;
			}
			typeName = value.Trim();
			return true;
		}

		private static Type? ResolveExternalType(string typeName)
		{
			if (ResolvedExternalTypeByName.TryGetValue(typeName, out Type value))
			{
				return value;
			}
			Type type = (from asm in AppDomain.CurrentDomain.GetAssemblies()
				select asm.GetType(typeName, throwOnError: false)).OfType<Type>().FirstOrDefault();
			if (type != null)
			{
				ResolvedExternalTypeByName.TryAdd(typeName, type);
			}
			return type;
		}

		private static SaveScope ParseScope(string? value)
		{
			switch (value?.Trim().ToLowerInvariant())
			{
			case "profile":
				return SaveScope.Profile;
			case "inmemory":
			case "in-memory":
			case "in_memory":
				return SaveScope.InMemory;
			default:
				return SaveScope.Global;
			}
		}

		private static bool TryRegisterFromSchema(InteropProvider provider, InteropSchemaRoot schema)
		{
			if (schema.SyntaxVersion != 2)
			{
				return TryRegisterFromSchemaV1(provider, schema);
			}
			return TryRegisterFromSchemaV2(provider, schema);
		}

		private static bool TryRegisterFromSchemaV1(InteropProvider provider, InteropSchemaRoot schema)
		{
			ReflectionStaticChannel reflectionStaticChannel = ReflectionStaticChannelBinder.Bind(provider.ProviderType, ReflectionInteropConvention.ModData);
			string text = provider.ProviderType.FullName ?? provider.ProviderType.Name;
			using (Gate.EnterScope())
			{
				ProviderAccessors[text] = reflectionStaticChannel;
			}
			ModDataStore store = ModDataStore.For(schema.ModId);
			bool flag = false;
			using (RitsuLibFramework.BeginModDataRegistration(schema.ModId))
			{
				foreach (InteropEntry entry in schema.Entries)
				{
					string item = schema.ModId + "\u001f" + entry.Key;
					using (Gate.EnterScope())
					{
						if (RegisteredInteropSlotKeys.Contains(item))
						{
