		private static void RegisterJsonEntry(ModDataStore store, string modId, string providerKey, InteropEntry entry, ReflectionStaticChannel channel)
		{
			Func<ModDataInteropJsonDocument> func = () => new ModDataInteropJsonDocument();
			if (!string.IsNullOrWhiteSpace(entry.DefaultFactoryMethodName))
			{
				MethodInfo factoryMethod = ResolveStaticFactory(providerKey, entry.DefaultFactoryMethodName, typeof(ModDataInteropJsonDocument));
				if (factoryMethod != null)
				{
					try
					{
						func = (Func<ModDataInteropJsonDocument>)Delegate.CreateDelegate(typeof(Func<ModDataInteropJsonDocument>), factoryMethod);
					}
					catch (ArgumentException)
					{
						func = () => (factoryMethod.Invoke(null, Array.Empty<object>()) as ModDataInteropJsonDocument) ?? new ModDataInteropJsonDocument();
					}
				}
			}
			RegisterJsonDocumentClosed.Invoke(store, new object[8] { entry.Key, entry.FileName, entry.Scope, entry.SyncToCloud, func, entry.AutoCreateIfMissing, entry.MigrationConfig, entry.Migrations });
			using (Gate.EnterScope())
			{
				Slots.Add(new InteropSlot(modId, entry.Key, providerKey, typeof(ModDataInteropJsonDocument), IsJsonChannel: true, entry.Scope, entry.JsonPathPull, entry.JsonPathPush, entry.JsonPathMergePush));
			}
		}

		private static void RegisterTypedEntry(ModDataStore store, string modId, Type providerType, string providerKey, InteropEntry entry, Type dataType, ReflectionStaticChannel? channel, bool patchStubs)
		{
			if ((object)dataType == null || !dataType.IsClass || dataType.IsAbstract)
			{
				throw new InvalidOperationException("dataType must be a concrete class: " + dataType.FullName);
			}
			if (dataType.GetConstructor(Type.EmptyTypes) == null && string.IsNullOrWhiteSpace(entry.DefaultFactoryMethodName))
			{
				throw new InvalidOperationException("dataType '" + dataType.FullName + "' requires a parameterless ctor or defaultFactory method.");
			}
			MethodInfo orAdd = RegisterClosedByDataType.GetOrAdd(dataType, (Type t) => ModDataStoreRegisterWithCloudOpen.MakeGenericMethod(t));
			Delegate obj = BuildDefaultFactory(providerType, dataType, entry.DefaultFactoryMethodName);
			orAdd.Invoke(store, new object[8] { entry.Key, entry.FileName, entry.Scope, entry.SyncToCloud, obj, entry.AutoCreateIfMissing, entry.MigrationConfig, entry.Migrations });
			if (patchStubs)
			{
				int num = RuntimeModDataStubPatcher.TryPatchEntry(providerType, modId, entry.Key, dataType, entry.GetMethodName, entry.ModifyMethodName, entry.SaveMethodName);
				if (num == 0)
				{
					RitsuLibFramework.Logger.Warn($"[RuntimeModDataInteropSource] No ModData stub methods were patched for '{modId}'::{entry.Key} on {providerType.FullName}.", 1);
				}
				else
				{
					RitsuLibFramework.Logger.Debug($"[RuntimeModDataInteropSource] Patched {num} ModData stub method(s) for '{modId}'::{entry.Key} on {providerType.FullName}.", 1);
				}
			}
			RegisterApplyHook(modId, providerKey, entry, providerType);
			if (channel == null)
			{
				return;
			}
			using (Gate.EnterScope())
			{
				Slots.Add(new InteropSlot(modId, entry.Key, providerKey, dataType, IsJsonChannel: false, entry.Scope, null, null, null));
			}
		}

		private static void RegisterApplyHook(string modId, string providerKey, InteropEntry entry, Type providerType)
		{
			if (string.IsNullOrWhiteSpace(entry.ApplyMethodName))
			{
				return;
			}
			MethodInfo method = providerType.GetMethod(entry.ApplyMethodName.Trim(), BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			if (method == null || method.ReturnType != typeof(void) || method.GetParameters().Length != 0)
			{
				RitsuLibFramework.Logger.Warn($"[RuntimeModDataInteropSource] Invalid applyMethod on {providerType.FullName}: expected static void {entry.ApplyMethodName}().", 1);
				return;
			}
			using (Gate.EnterScope())
			{
				if (!ApplyHooks.Any((InteropApplyHook h) => h.ModId == modId && h.Key == entry.Key && h.ProviderKey == providerKey && h.Method == method))
				{
					ApplyHooks.Add(new InteropApplyHook(modId, entry.Key, providerKey, entry.Scope, method));
				}
			}
		}

		private static Delegate BuildDefaultFactory(Type providerType, Type dataType, string? defaultFactoryMethodName)
		{
			if (string.IsNullOrWhiteSpace(defaultFactoryMethodName))
			{
				return CreateDefaultDelegate(dataType);
			}
			MethodInfo method = providerType.GetMethod(defaultFactoryMethodName.Trim(), BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			if (method == null || method.GetParameters().Length != 0)
			{
				throw new InvalidOperationException($"defaultFactory '{defaultFactoryMethodName}' must be static parameterless on '{providerType.FullName}'.");
			}
			object obj = method.Invoke(null, Array.Empty<object>());
			if (obj == null || !dataType.IsInstanceOfType(obj))
			{
				throw new InvalidOperationException($"defaultFactory '{defaultFactoryMethodName}' must return non-null '{dataType.FullName}'.");
			}
			return Delegate.CreateDelegate(typeof(Func<>).MakeGenericType(dataType), method);
		}

		private static Delegate CreateDefaultDelegate(Type dataType)
		{
			ConstructorInfo? constructor = dataType.GetConstructor(Type.EmptyTypes);
			if (constructor == null)
			{
				throw new InvalidOperationException("Type '" + dataType.FullName + "' requires a parameterless constructor.");
			}
			NewExpression body = Expression.New(constructor);
			return Expression.Lambda(typeof(Func<>).MakeGenericType(dataType), body).Compile();
		}

		private static MethodInfo? ResolveStaticFactory(string providerKey, string methodName, Type expectedReturn)
		{
			using (Gate.EnterScope())
			{
				if (!ProviderAccessors.TryGetValue(providerKey, out ReflectionStaticChannel value))
				{
					return null;
				}
				MethodInfo method = value.ProviderType.GetMethod(methodName.Trim(), BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
				if (method == null || method.GetParameters().Length != 0)
				{
					return null;
				}
				return (!expectedReturn.IsAssignableFrom(method.ReturnType)) ? null : method;
			}
		}

		private static void PushLoadedForMod(string modId, string providerKey)
		{
			InteropSlot[] array;
			using (Gate.EnterScope())
			{
				array = Slots.Where((InteropSlot s) => s.ModId == modId && s.ProviderKey == providerKey).ToArray();
			}
			if (!ProviderAccessors.TryGetValue(providerKey, out ReflectionStaticChannel value))
			{
				return;
			}
			ModDataStore modDataStore = ModDataStore.For(modId);
			InteropSlot[] array2 = array;
			foreach (InteropSlot interopSlot in array2)
			{
				try
				{
					if (interopSlot.Scope != SaveScope.Profile || modDataStore.IsProfileInitialized)
					{
						if (interopSlot.IsJsonChannel)
						{
							PushJsonChannel(modDataStore, interopSlot, value);
							continue;
						}
						object arg = CallGenericGet(modDataStore, interopSlot.Key, interopSlot.DataType);
						value.SetObject(interopSlot.Key, arg);
					}
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[RuntimeModDataInteropSource] Initial push to provider failed for '{modId}'::{interopSlot.Key}: {ex.Message}", 1);
				}
			}
		}

		private static void ApplyLoadedForMod(string modId, string providerKey)
		{
			InteropApplyHook[] hooks;
			using (Gate.EnterScope())
			{
				hooks = ApplyHooks.Where((InteropApplyHook h) => h.ModId == modId && h.ProviderKey == providerKey).ToArray();
			}
			ApplyLoadedDataHooks(hooks);
		}

		private static void ApplyLoadedDataHooks()
		{
			InteropApplyHook[] hooks;
			using (Gate.EnterScope())
			{
				hooks = ApplyHooks.ToArray();
			}
			ApplyLoadedDataHooks(hooks);
		}

		private static void ApplyLoadedDataHooks(InteropApplyHook[] hooks)
		{
			foreach (InteropApplyHook interopApplyHook in hooks)
			{
				try
				{
					ModDataStore modDataStore = ModDataStore.For(interopApplyHook.ModId);
					if (interopApplyHook.Scope != SaveScope.Profile || modDataStore.IsProfileInitialized)
					{
						interopApplyHook.Method.Invoke(null, Array.Empty<object>());
					}
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[RuntimeModDataInteropSource] applyMethod failed for '{interopApplyHook.ModId}'::{interopApplyHook.Key}: {ex.Message}", 1);
				}
			}
		}

		private static object? CallGenericGet(ModDataStore store, string key, Type dataType)
		{
			return GetClosedByDataType.GetOrAdd(dataType, (Type t) => ModDataStoreGetOpen.MakeGenericMethod(t)).Invoke(store, new object[1] { key });
		}

		private static void SyncJsonSlot(ModDataStore store, InteropSlot slot, ReflectionStaticChannel channel)
		{
			KeyedJsonPathRouting routing = new KeyedJsonPathRouting(slot.JsonPathPull, slot.JsonPathPush, slot.JsonPathMergePush);
			store.Modify(slot.Key, delegate(ModDataInteropJsonDocument holder)
			{
				holder.Root = KeyedJsonDomTransport.PullFromProviderIntoRoot(slot.Key, channel, holder.Root, routing);
			});
		}

		private static void PushJsonChannel(ModDataStore store, InteropSlot slot, ReflectionStaticChannel channel)
		{
			ModDataInteropJsonDocument modDataInteropJsonDocument = store.Get<ModDataInteropJsonDocument>(slot.Key);
			KeyedJsonPathRouting pathRouting = new KeyedJsonPathRouting(slot.JsonPathPull, slot.JsonPathPush, slot.JsonPathMergePush);
			KeyedJsonDomTransport.PushRootToProvider(slot.Key, channel, modDataInteropJsonDocument.Root, pathRouting);
		}

		private static void SyncTypedSlot(ModDataStore store, string modId, string key, Type dataType, ReflectionStaticChannel channel)
		{
			object obj = channel.GetObject(key);
			if (obj == null)
			{
				return;
			}
			if (!dataType.IsInstanceOfType(obj))
			{
				RitsuLibFramework.Logger.Warn($"[RuntimeModDataInteropSource] Provider returned incompatible type for '{modId}'::{key}: expected '{dataType.FullName}', got '{obj.GetType().FullName}'.", 1);
			}
			else
			{
				ApplySyncTypedClosedByDataType.GetOrAdd(dataType, (Type t) => ApplySyncTypedCoreOpen.MakeGenericMethod(t)).Invoke(null, new object[3] { store, key, obj });
			}
		}

		private static void ApplySyncTypedCore<T>(ModDataStore store, string key, object raw) where T : class, new()
		{
			T typed = raw as T;
			if (typed != null)
			{
				store.Modify(key, delegate(T data)
				{
					CopySerializableProperties(typed, data);
				});
			}
		}

