	/// <summary>
	///     <para xml:lang="en">
	///         Installs Harmony prefixes that route compatible provider stub methods through RitsuLib mod-data
	///         storage.
	///     </para>
	///     <para xml:lang="zh-CN">安装 Harmony 前置补丁，将兼容提供程序的存根方法路由到 RitsuLib 模组数据存储。</para>
	/// </summary>
	internal static class RuntimeModDataStubPatcher
	{
		private readonly record struct StubRoute(string ModId, string Key, Type DataType);

		private const BindingFlags StaticMethodFlags = BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic;

		private static readonly Lock Gate;

		private static readonly Harmony Harmony;

		private static readonly HashSet<MethodBase> PatchedMethods;

		private static readonly Dictionary<MethodBase, StubRoute> Routes;

		private static readonly MethodInfo GetPrefixOpen;

		private static readonly MethodInfo ModifyPrefixOpen;

		private static readonly MethodInfo SavePrefixMethod;

		public static int TryPatchEntry(Type providerType, string modId, string key, Type dataType, string? getMethodName, string? modifyMethodName, string? saveMethodName)
		{
			string text = ToPascalIdentifier(key);
			int num = 0;
			if (TryResolveGetMethod(providerType, dataType, getMethodName ?? ("Get" + text), getMethodName != null, out MethodInfo method))
			{
				num += PatchOnce(method, GetPrefixOpen.MakeGenericMethod(dataType, method.ReturnType), new StubRoute(modId, key, dataType));
			}
			if (TryResolveModifyMethod(providerType, dataType, modifyMethodName ?? ("Modify" + text), modifyMethodName != null, out MethodInfo method2))
			{
				num += PatchOnce(method2, ModifyPrefixOpen.MakeGenericMethod(dataType), new StubRoute(modId, key, dataType));
			}
			if (TryResolveSaveMethod(providerType, saveMethodName ?? ("Save" + text), saveMethodName != null, out MethodInfo method3))
			{
				num += PatchOnce(method3, SavePrefixMethod, new StubRoute(modId, key, dataType));
			}
			return num;
		}

		private static int PatchOnce(MethodInfo original, MethodInfo prefix, StubRoute route)
		{
			//IL_002f: Unknown result type (might be due to invalid IL or missing references)
			//IL_003c: Expected O, but got Unknown
			using (Gate.EnterScope())
			{
				if (!PatchedMethods.Add(original))
				{
					return 0;
				}
				Routes[original] = route;
				try
				{
					Harmony.Patch((MethodBase)original, new HarmonyMethod(prefix), (HarmonyMethod)null, (HarmonyMethod)null, (HarmonyMethod)null);
					return 1;
				}
				catch (Exception ex)
				{
					PatchedMethods.Remove(original);
					Routes.Remove(original);
					RitsuLibFramework.Logger.Warn("[RuntimeModDataInteropSource] Failed to patch ModData stub method " + FormatMethod(original) + ": " + ex.Message, 1);
					return 0;
				}
			}
		}

		private static bool TryResolveGetMethod(Type providerType, Type dataType, string methodName, bool warnIfInvalid, out MethodInfo method)
		{
			method = null;
			MethodInfo method2 = providerType.GetMethod(methodName, BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, Array.Empty<Type>());
			if (method2 == null)
			{
				if (warnIfInvalid)
				{
					WarnInvalid(providerType, methodName, $"expected static {methodName}() returning {dataType.FullName} or one of its base types, but the method was not found.");
				}
				return false;
			}
			if (method2.ReturnType == typeof(void) || !method2.ReturnType.IsAssignableFrom(dataType))
			{
				if (warnIfInvalid)
				{
					WarnInvalid(providerType, methodName, $"expected static {methodName}() returning {dataType.FullName} or one of its base types.");
				}
				return false;
			}
			method = method2;
			return true;
		}

		private static bool TryResolveModifyMethod(Type providerType, Type dataType, string methodName, bool warnIfInvalid, out MethodInfo method)
		{
			method = null;
			Type type = typeof(Action<>).MakeGenericType(dataType);
			MethodInfo method2 = providerType.GetMethod(methodName, BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, new Type[1] { type });
			if (method2 == null)
			{
				if (warnIfInvalid)
				{
					WarnInvalid(providerType, methodName, $"expected static void {methodName}(Action<{dataType.FullName}>), but the method was not found.");
				}
				return false;
			}
			if (method2.ReturnType != typeof(void))
			{
				if (warnIfInvalid)
				{
					WarnInvalid(providerType, methodName, $"expected static void {methodName}(Action<{dataType.FullName}>).");
				}
				return false;
			}
			method = method2;
			return true;
		}

		private static bool TryResolveSaveMethod(Type providerType, string methodName, bool warnIfInvalid, out MethodInfo method)
		{
			method = null;
			MethodInfo method2 = providerType.GetMethod(methodName, BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, Array.Empty<Type>());
			if (method2 == null)
			{
				if (warnIfInvalid)
				{
					WarnInvalid(providerType, methodName, "expected static void " + methodName + "(), but the method was not found.");
				}
				return false;
			}
			if (method2.ReturnType != typeof(void))
			{
				if (warnIfInvalid)
				{
					WarnInvalid(providerType, methodName, "expected static void " + methodName + "().");
				}
				return false;
			}
			method = method2;
			return true;
		}

		private static bool GetPrefix<TData, TResult>(MethodBase __originalMethod, ref TResult __result) where TData : class, new() where TResult : class
		{
			if (!TryGetRoute(__originalMethod, out var route))
			{
				return true;
			}
			__result = (TResult)(object)ModDataStore.For(route.ModId).Get<TData>(route.Key);
			return false;
		}

		private static bool ModifyPrefix<TData>(MethodBase __originalMethod, Action<TData> __0) where TData : class, new()
		{
			if (!TryGetRoute(__originalMethod, out var route))
			{
				return true;
			}
			ModDataStore.For(route.ModId).Modify(route.Key, __0);
			return false;
		}

		private static bool SavePrefix(MethodBase __originalMethod)
		{
			if (!TryGetRoute(__originalMethod, out var route))
			{
				return true;
			}
			ModDataStore.For(route.ModId).Save(route.Key);
			return false;
		}

		private static bool TryGetRoute(MethodBase originalMethod, out StubRoute route)
		{
			using (Gate.EnterScope())
			{
				return Routes.TryGetValue(originalMethod, out route);
			}
		}

		private static string ToPascalIdentifier(string key)
		{
			List<char> list = new List<char>(key.Length);
			bool flag = true;
			foreach (char c in key)
			{
				if (!char.IsLetterOrDigit(c))
				{
					flag = true;
					continue;
				}
				list.Add(flag ? char.ToUpperInvariant(c) : c);
				flag = false;
			}
			if (list.Count != 0)
			{
				return new string(new ReadOnlySpan<char>(list.ToArray()));
			}
			return "Data";
		}

		private static void WarnInvalid(Type providerType, string methodName, string detail)
		{
			RitsuLibFramework.Logger.Warn("[RuntimeModDataInteropSource] Invalid ModData stub method on " + providerType.FullName + ": " + detail, 1);
		}

		private static string FormatMethod(MethodBase method)
		{
			return (method.DeclaringType?.FullName ?? "<unknown>") + "." + method.Name;
		}

		static RuntimeModDataStubPatcher()
		{
			//IL_000f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0019: Expected O, but got Unknown
			Gate = new Lock();
			Harmony = new Harmony("com.ritsukage.sts2-RitsuLib.mod-data-interop");
			PatchedMethods = new HashSet<MethodBase>();
			Routes = new Dictionary<MethodBase, StubRoute>();
			GetPrefixOpen = typeof(RuntimeModDataStubPatcher).GetMethod("GetPrefix", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			ModifyPrefixOpen = typeof(RuntimeModDataStubPatcher).GetMethod("ModifyPrefix", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			SavePrefixMethod = typeof(RuntimeModDataStubPatcher).GetMethod("SavePrefix", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
		}
	}
}
namespace STS2RitsuLib.Utils.Persistence.Context
{
	/// <summary>
	///     <para xml:lang="en">Carries extensible storage-addressing values alongside persistence operations.</para>
	///     <para xml:lang="zh-CN">在持久化操作中携带可扩展的存储寻址值。</para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         This type is intentionally generic because some <see cref="T:STS2RitsuLib.Utils.Persistence.SaveScope" /> values may require
	///         additional addressing information, such as a run fingerprint. Add each new value as a
	///         <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContextKey`1" /> rather than another method parameter.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         此类型刻意保持通用，因为部分 <see cref="T:STS2RitsuLib.Utils.Persistence.SaveScope" /> 值可能需要额外的寻址信息，例如一局游戏的指纹。应以
	///         <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContextKey`1" /> 表示每个新增值，而不是继续增加方法参数。
	///     </para>
	/// </remarks>
	public sealed class StorageContext
	{
		private readonly ImmutableDictionary<string, object?> _values;

		/// <summary>
		///     <para xml:lang="en">Empty context.</para>
		///     <para xml:lang="zh-CN">空上下文。</para>
		/// </summary>
		public static StorageContext Empty { get; } = new StorageContext(ImmutableDictionary<string, object>.Empty);

		private StorageContext(ImmutableDictionary<string, object?> values)
		{
			_values = values;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns <see langword="true" /> and assigns <paramref name="value" /> when the key exists and
		///         its value is a <typeparamref name="TValue" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         键存在且对应值为 <typeparamref name="TValue" /> 时，返回 <see langword="true" /> 并为
		///         <paramref name="value" /> 赋值。
		///     </para>
		/// </summary>
		public bool TryGet<TValue>(StorageContextKey<TValue> key, out TValue value)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			if (_values.TryGetValue(key.Id, out object value2) && value2 is TValue val)
			{
				value = val;
				return true;
			}
			value = default(TValue);
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns a new <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContext" /> with <paramref name="value" /> stored under
		///         <paramref name="key" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回一个新的 <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContext" />，其中 <paramref name="value" /> 存储在
		///         <paramref name="key" /> 下。
		///     </para>
		/// </summary>
		public StorageContext With<TValue>(StorageContextKey<TValue> key, TValue value)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			return new StorageContext(_values.SetItem(key.Id, value));
		}

		/// <summary>
		///     <para xml:lang="en">Returns a new <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContext" /> without <paramref name="key" />.</para>
		///     <para xml:lang="zh-CN">返回一个不含 <paramref name="key" /> 的新 <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContext" />。</para>
		/// </summary>
		public StorageContext Without<TValue>(StorageContextKey<TValue> key)
		{
			ArgumentNullException.ThrowIfNull(key, "key");
			return new StorageContext(_values.Remove(key.Id));
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Represents a strongly typed key used to store and retrieve a value in
	///         <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContext" />.
	///     </para>
	///     <para xml:lang="zh-CN">表示在 <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContext" /> 中存取值时使用的强类型键。</para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">Each key has a stable string identifier for cross-assembly lookup and diagnostics.</para>
	///     <para xml:lang="zh-CN">每个键都有稳定的字符串标识符，可用于跨程序集查找和诊断。</para>
	/// </remarks>
	public sealed class StorageContextKey<TValue>
	{
		/// <summary>
		///     <para xml:lang="en">Stable identifier for this context key.</para>
		///     <para xml:lang="zh-CN">此上下文键的稳定标识符。</para>
		/// </summary>
		public string Id { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Represents a strongly typed key used to store and retrieve a value in
		///         <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContext" />.
		///     </para>
		///     <para xml:lang="zh-CN">表示在 <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContext" /> 中存取值时使用的强类型键。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">Each key has a stable string identifier for cross-assembly lookup and diagnostics.</para>
		///     <para xml:lang="zh-CN">每个键都有稳定的字符串标识符，可用于跨程序集查找和诊断。</para>
		/// </remarks>
		public StorageContextKey(string id)
		{
			if (string.IsNullOrWhiteSpace(id))
			{
				throw new ArgumentException("Context key id must not be empty.", "id");
			}
			Id = id.Trim();
			base..ctor();
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides built-in <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContextKey`1" /> values used by RitsuLib persistence.</para>
	///     <para xml:lang="zh-CN">提供 RitsuLib 持久化所用的内置 <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContextKey`1" /> 值。</para>
	/// </summary>
	public static class StorageContextKeys
	{
		/// <summary>
		///     <para xml:lang="en">Overrides the active game profile ID for a persistence operation.</para>
		///     <para xml:lang="zh-CN">覆盖持久化操作的活动游戏档案 ID。</para>
		/// </summary>
		public static StorageContextKey<int> ProfileId { get; } = new StorageContextKey<int>("sts2ritsulib.profileId");
	}
}
namespace STS2RitsuLib.Utils.Json
{
	/// <summary>
	///     <para xml:lang="en">
	///         Implements the JSON Canonicalization Scheme (JCS, RFC 8785) for <see cref="T:System.Text.Json.Nodes.JsonNode" /> DOM values.
	///         See <see href="https://www.rfc-editor.org/rfc/rfc8785" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为 <see cref="T:System.Text.Json.Nodes.JsonNode" /> DOM 值实现 JSON 规范化方案（JCS，RFC 8785）。
	///         参见 <see href="https://www.rfc-editor.org/rfc/rfc8785" />。
	///     </para>
	/// </summary>
	public static class JsonCanonicalizer
	{
		private sealed class Utf16CodeUnitComparer : IComparer<string>
		{
			public static Utf16CodeUnitComparer Instance { get; } = new Utf16CodeUnitComparer();

			public int Compare(string? x, string? y)
			{
				if ((object)x == y)
				{
					return 0;
				}
				if (x == null)
				{
					return -1;
				}
				if (y == null)
				{
					return 1;
				}
				int num = Math.Min(x.Length, y.Length);
				for (int i = 0; i < num; i++)
				{
					int num2 = x[i].CompareTo(y[i]);
					if (num2 != 0)
					{
						return num2;
					}
				}
				return x.Length.CompareTo(y.Length);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Canonicalizes a JSON DOM node into JCS JSON text. Encode the returned .NET string as UTF-8 to
		///         obtain the RFC 8785 byte representation.
		///     </para>
		///     <para xml:lang="zh-CN">将 JSON DOM 节点规范化为 JCS JSON 文本。将返回的 .NET 字符串编码为 UTF-8，即可得到 RFC 8785 字节表示。</para>
		/// </summary>
		/// <exception cref="T:System.InvalidOperationException">
		///     <para xml:lang="en">
		///         The DOM contains a value that JCS cannot represent, such as a non-finite IEEE 754 binary64
		///         number, an unpaired surrogate, or a Unicode noncharacter.
		///     </para>
		///     <para xml:lang="zh-CN">DOM 包含 JCS 无法表示的值，例如非有限 IEEE 754 binary64 数值、未配对代理项或 Unicode 非字符码点。</para>
		/// </exception>
		public static string Canonicalize(JsonNode? node)
		{
			StringBuilder stringBuilder = new StringBuilder();
			WriteCanonical(stringBuilder, node);
			return stringBuilder.ToString();
		}

		private static void WriteCanonical(StringBuilder output, JsonNode? node)
		{
			if (node == null)
			{
				output.Append("null");
				return;
			}
			if (!(node is JsonObject source))
			{
				if (node is JsonArray jsonArray)
				{
					output.Append('[');
					for (int i = 0; i < jsonArray.Count; i++)
					{
						if (i > 0)
						{
							output.Append(',');
						}
						WriteCanonical(output, jsonArray[i]);
					}
					output.Append(']');
				}
				else
				{
					WritePrimitiveCanonical(output, node);
				}
				return;
			}
			output.Append('{');
			bool flag = true;
			foreach (var (value, node2) in source.OrderBy<KeyValuePair<string, JsonNode>, string>((KeyValuePair<string, JsonNode> p) => p.Key, Utf16CodeUnitComparer.Instance))
			{
				if (!flag)
				{
					output.Append(',');
				}
				flag = false;
				WriteString(output, value);
				output.Append(':');
				WriteCanonical(output, node2);
			}
			output.Append('}');
		}

		private static void WritePrimitiveCanonical(StringBuilder output, JsonNode node)
		{
			switch (node.GetValueKind())
			{
			case JsonValueKind.String:
				WriteString(output, GetStringValue(node));
				break;
			case JsonValueKind.Number:
			{
				if (!TryGetFiniteDouble(node, out var value))
				{
					throw new InvalidOperationException("JCS requires every number to be a finite IEEE 754 binary64 value.");
				}
				output.Append(FormatFiniteNumber(value));
				break;
			}
			case JsonValueKind.True:
				output.Append("true");
				break;
			case JsonValueKind.False:
				output.Append("false");
				break;
			case JsonValueKind.Null:
				output.Append("null");
				break;
			default:
				throw new InvalidOperationException($"JCS cannot serialize a JSON value of kind {node.GetValueKind()}.");
			}
		}

		private static string GetStringValue(JsonNode node)
		{
			if (node is JsonValue jsonValue && jsonValue.TryGetValue<string>(out string value))
			{
				return value;
			}
			JsonElement jsonElement = JsonSerializer.SerializeToElement(node);
			if (jsonElement.ValueKind != JsonValueKind.String)
			{
				throw new InvalidOperationException("The JSON DOM value did not serialize as a string.");
			}
			return jsonElement.GetString();
		}

		private static void WriteString(StringBuilder output, string value)
		{
			output.Append('"');
			for (int i = 0; i < value.Length; i++)
			{
				char c = value[i];
				switch (c)
				{
				case '"':
					output.Append("\\\"");
					continue;
				case '\\':
					output.Append("\\\\");
					continue;
				case '\b':
					output.Append("\\b");
					continue;
				case '\t':
					output.Append("\\t");
					continue;
				case '\n':
					output.Append("\\n");
					continue;
				case '\f':
					output.Append("\\f");
					continue;
				case '\r':
					output.Append("\\r");
					continue;
				}
				if (c <= '\u001f')
				{
					output.Append("\\u00");
					output.Append(ToLowerHex((int)c >> 4));
					output.Append(ToLowerHex(c & 0xF));
				}
				else if (char.IsHighSurrogate(c))
				{
					if (i + 1 >= value.Length || !char.IsLowSurrogate(value[i + 1]))
					{
						throw InvalidUnicode(c, i);
					}
					char c2 = value[++i];
					int codePoint = char.ConvertToUtf32(c, c2);
					if (IsNoncharacter(codePoint))
					{
						throw InvalidUnicode(codePoint, i - 1);
					}
					output.Append(c);
					output.Append(c2);
				}
				else
				{
					if (char.IsLowSurrogate(c) || IsNoncharacter(c))
					{
						throw InvalidUnicode(c, i);
					}
					output.Append(c);
				}
			}
			output.Append('"');
		}

		private static InvalidOperationException InvalidUnicode(int codePoint, int index)
		{
			return new InvalidOperationException($"JCS forbids Unicode surrogate and noncharacter code points; found U+{codePoint:X4} at UTF-16 index {index}.");
		}

		private static char ToLowerHex(int value)
		{
			return (char)((value < 10) ? (48 + value) : (97 + value - 10));
		}

		private static bool IsNoncharacter(int codePoint)
		{
			bool flag = codePoint >= 64976 && codePoint <= 65007;
			if (!flag)
			{
				int num = codePoint & 0xFFFF;
				bool flag2 = (uint)(num - 65534) <= 1u;
				flag = flag2;
			}
			return flag;
		}

		private static bool TryGetFiniteDouble(JsonNode node, out double value)
		{
			value = 0.0;
			if (!(node is JsonValue jsonValue))
			{
				return false;
			}
			if (jsonValue.TryGetValue<JsonElement>(out var value2))
			{
				if (value2.ValueKind == JsonValueKind.Number && value2.TryGetDouble(out value))
				{
					return double.IsFinite(value);
				}
				return false;
			}
			if (jsonValue.TryGetValue<double>(out value))
			{
				return double.IsFinite(value);
			}
			if (jsonValue.TryGetValue<float>(out var value3))
			{
				value = value3;
				return float.IsFinite(value3);
			}
			string s;
			try
			{
				s = node.ToJsonString();
			}
			catch (ArgumentException)
			{
				return false;
			}
			catch (InvalidOperationException)
			{
				return false;
			}
			catch (NotSupportedException)
			{
				return false;
			}
			if (double.TryParse(s, NumberStyles.Float, CultureInfo.InvariantCulture, out value))
			{
				return double.IsFinite(value);
			}
			return false;
		}

		internal static string FormatFiniteNumber(double value)
		{
			if (!double.IsFinite(value))
			{
				throw new ArgumentOutOfRangeException("value", "The number must be finite.");
			}
			if (value == 0.0)
			{
				return "0";
			}
			string text = value.ToString("R", CultureInfo.InvariantCulture);
			bool flag = text[0] == '-';
			int num = (flag ? 1 : 0);
			int num2 = text.IndexOfAny(new char[2] { 'E', 'e' }, num);
			int num3 = ((num2 < 0) ? text.Length : num2);
			int num4 = ((num2 >= 0) ? int.Parse(text.AsSpan(num2 + 1), NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture) : 0);
			int num5 = text.IndexOf('.', num, num3 - num);
			int num6 = ((num5 < 0) ? (num3 - num) : (num5 - num));
			StringBuilder stringBuilder = new StringBuilder(num3 - num);
			for (int i = num; i < num3; i++)
			{
				if (text[i] != '.')
				{
					stringBuilder.Append(text[i]);
				}
			}
			int j;
			for (j = 0; j < stringBuilder.Length - 1 && stringBuilder[j] == '0'; j++)
			{
			}
			if (j > 0)
			{
				stringBuilder.Remove(0, j);
				num6 -= j;
			}
			while (stringBuilder.Length > 1)
			{
				if (stringBuilder[stringBuilder.Length - 1] != '0')
				{
					break;
				}
				stringBuilder.Length--;
			}
			int num7 = num6 + num4;
			StringBuilder stringBuilder2 = new StringBuilder(stringBuilder.Length + 16);
			if (flag)
			{
				stringBuilder2.Append('-');
			}
			if (num7 > 0 && num7 <= 21)
			{
				if (stringBuilder.Length <= num7)
				{
					stringBuilder2.Append(stringBuilder);
					stringBuilder2.Append('0', num7 - stringBuilder.Length);
				}
				else
				{
					stringBuilder2.Append(stringBuilder, 0, num7);
					stringBuilder2.Append('.');
					stringBuilder2.Append(stringBuilder, num7, stringBuilder.Length - num7);
				}
			}
			else if (num7 > -6 && num7 <= 0)
			{
				stringBuilder2.Append("0.");
				stringBuilder2.Append('0', -num7);
				stringBuilder2.Append(stringBuilder);
			}
			else
			{
				stringBuilder2.Append(stringBuilder[0]);
				if (stringBuilder.Length > 1)
				{
					stringBuilder2.Append('.');
					stringBuilder2.Append(stringBuilder, 1, stringBuilder.Length - 1);
				}
				int num8 = num7 - 1;
				stringBuilder2.Append('e');
				if (num8 >= 0)
				{
					stringBuilder2.Append('+');
				}
				stringBuilder2.Append(num8.ToString(CultureInfo.InvariantCulture));
			}
			return stringBuilder2.ToString();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Validates the DOM-level I-JSON constraints of <see cref="T:System.Text.Json.Nodes.JsonNode" /> values (RFC 7493), including
	///         Unicode scalar and noncharacter restrictions plus finite IEEE 754 binary64-compatible numbers. See
	///         <see href="https://www.rfc-editor.org/rfc/rfc7493" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         验证 <see cref="T:System.Text.Json.Nodes.JsonNode" /> 值在 DOM 层面的 I-JSON（RFC 7493）约束，包括 Unicode 标量和非字符限制，
	///         以及与有限 IEEE 754 binary64 数值的兼容性。参见 <see href="https://www.rfc-editor.org/rfc/rfc7493" />。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         A DOM cannot reveal the original byte encoding or duplicate object names discarded before
	///         construction; validate those properties while parsing the source JSON.
	///     </para>
	///     <para xml:lang="zh-CN">DOM 无法反映原始字节编码，也无法发现构建前已被丢弃的重复对象成员名；这些属性应在解析源 JSON 时验证。</para>
	/// </remarks>
	public static class JsonIJsonValidator
	{
		/// <summary>
		///     <para xml:lang="en">Attempts to validate the DOM node against the representable I-JSON constraints.</para>
		///     <para xml:lang="zh-CN">尝试验证 DOM 节点是否符合可在 DOM 中检查的 I-JSON 约束。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> with a null <paramref name="error" /> when validation succeeds;
		///         otherwise <see langword="false" /> with a diagnostic.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         验证成功时返回 <see langword="true" />，且 <paramref name="error" /> 为 null；否则返回
		///         <see langword="false" /> 并提供诊断。
		///     </para>
		/// </returns>
		public static bool TryValidate(JsonNode? node, out string? error)
		{
			error = null;
			try
			{
				return ValidateCore(node, "$", ref error);
			}
			catch (ArgumentException ex)
			{
				error = "Invalid JSON DOM value: " + ex.Message;
				return false;
			}
			catch (InvalidOperationException ex2)
			{
				error = "Invalid JSON DOM value: " + ex2.Message;
				return false;
			}
			catch (JsonException ex3)
			{
				error = "Invalid JSON DOM value: " + ex3.Message;
				return false;
			}
			catch (NotSupportedException ex4)
			{
				error = "Unsupported JSON DOM value: " + ex4.Message;
				return false;
			}
		}

		private static bool ValidateCore(JsonNode? node, string path, ref string? error)
		{
			if (node == null)
			{
				return true;
			}
			if (!(node is JsonObject jsonObject))
			{
				if (node is JsonArray jsonArray)
				{
					for (int i = 0; i < jsonArray.Count; i++)
					{
						if (!ValidateCore(jsonArray[i], path + "/" + i, ref error))
						{
							return false;
						}
					}
					return true;
				}
				JsonValueKind valueKind = node.GetValueKind();
				switch (valueKind)
				{
				case JsonValueKind.String:
				{
					if (TryValidateUnicode(GetStringValue(node), out var invalidCodePoint, out var invalidIndex))
					{
						return true;
					}
					error = $"I-JSON forbids Unicode surrogate and noncharacter code points in string values at {path}; found U+{invalidCodePoint:X4} at UTF-16 index {invalidIndex}.";
					return false;
				}
				case JsonValueKind.Number:
					return ValidateNumber(node, path, ref error);
				case JsonValueKind.True:
				case JsonValueKind.False:
				case JsonValueKind.Null:
					return true;
				default:
					error = $"Unsupported JSON value kind {valueKind} at {path}.";
					return false;
				}
			}
			foreach (var (text2, node2) in jsonObject)
			{
				if (!TryValidateUnicode(text2, out var invalidCodePoint2, out var invalidIndex2))
				{
					error = $"I-JSON forbids Unicode surrogate and noncharacter code points in property names at {path}; found U+{invalidCodePoint2:X4} at UTF-16 index {invalidIndex2}.";
					return false;
				}
				if (!ValidateCore(node2, path + "/" + EscapePointerSegment(text2), ref error))
				{
					return false;
				}
			}
			return true;
		}

		private static bool ValidateNumber(JsonNode node, string path, ref string? error)
		{
			if (!TryGetFiniteDouble(node, out var _))
			{
				error = "I-JSON requires a finite IEEE 754 binary64 number at " + path + ".";
				return false;
			}
			return true;
		}

		private static bool TryGetFiniteDouble(JsonNode node, out double value)
		{
			value = 0.0;
			if (!(node is JsonValue jsonValue))
			{
				return false;
			}
			if (jsonValue.TryGetValue<JsonElement>(out var value2))
			{
				if (value2.ValueKind == JsonValueKind.Number && value2.TryGetDouble(out value))
				{
					return double.IsFinite(value);
				}
				return false;
			}
			if (jsonValue.TryGetValue<double>(out value) && !double.IsFinite(value))
			{
				return false;
			}
			if (jsonValue.TryGetValue<float>(out var value3) && !float.IsFinite(value3))
			{
				return false;
			}
			try
			{
				return double.TryParse(node.ToJsonString(), NumberStyles.Float, CultureInfo.InvariantCulture, out value) && double.IsFinite(value);
			}
			catch (ArgumentException)
			{
				return false;
			}
			catch (InvalidOperationException)
			{
				return false;
			}
			catch (NotSupportedException)
			{
				return false;
			}
		}

		private static string GetStringValue(JsonNode node)
		{
			if (node is JsonValue jsonValue && jsonValue.TryGetValue<string>(out string value))
			{
				return value;
			}
			JsonElement jsonElement = JsonSerializer.SerializeToElement(node);
			if (jsonElement.ValueKind != JsonValueKind.String)
			{
				throw new InvalidOperationException("The JSON DOM value did not serialize as a string.");
			}
			return jsonElement.GetString();
		}

		private static bool TryValidateUnicode(string value, out int invalidCodePoint, out int invalidIndex)
		{
			invalidCodePoint = 0;
			invalidIndex = -1;
			for (int i = 0; i < value.Length; i++)
			{
				char c = value[i];
				if (char.IsHighSurrogate(c))
				{
					if (i + 1 >= value.Length || !char.IsLowSurrogate(value[i + 1]))
					{
						invalidCodePoint = c;
						invalidIndex = i;
						return false;
					}
					int num = char.ConvertToUtf32(c, value[i + 1]);
					if (IsNoncharacter(num))
					{
						invalidCodePoint = num;
						invalidIndex = i;
						return false;
					}
					i++;
				}
				else if (char.IsLowSurrogate(c) || IsNoncharacter(c))
				{
					invalidCodePoint = c;
					invalidIndex = i;
					return false;
				}
			}
			return true;
		}

		private static bool IsNoncharacter(int codePoint)
		{
			bool flag = codePoint >= 64976 && codePoint <= 65007;
			if (!flag)
			{
				int num = codePoint & 0xFFFF;
				bool flag2 = (uint)(num - 65534) <= 1u;
				flag = flag2;
			}
			return flag;
		}

		private static string EscapePointerSegment(string segment)
		{
			return segment.Replace("~", "~0", StringComparison.Ordinal).Replace("/", "~1", StringComparison.Ordinal);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides RFC 7386 JSON Merge Patch operations for <see cref="T:System.Text.Json.Nodes.JsonNode" /> DOM values.</para>
	///     <para xml:lang="zh-CN">为 <see cref="T:System.Text.Json.Nodes.JsonNode" /> DOM 值提供 RFC 7386 JSON 合并补丁操作。</para>
	/// </summary>
	public static class JsonMergePatch
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Applies an RFC 7386 merge patch to <paramref name="target" /> and returns the merged result. A
		///         non-object <paramref name="patch" /> replaces the target.
		///     </para>
		///     <para xml:lang="zh-CN">将 RFC 7386 合并补丁应用于 <paramref name="target" /> 并返回合并结果。非对象的 <paramref name="patch" /> 会替换目标。</para>
		/// </summary>
		public static JsonNode? Apply(JsonNode? target, JsonNode? patch)
		{
			if (!TryGetObject(patch, out JsonObject obj))
			{
				if (!IsJsonNull(patch))
				{
					return patch?.DeepClone();
				}
				return null;
			}
			JsonObject obj2 = (TryGetObject(target, out JsonObject obj3) ? ((obj3.DeepClone() as JsonObject) ?? new JsonObject()) : new JsonObject());
			ApplyInPlace(obj2, obj);
			return obj2;
		}

		/// <summary>
		///     <para xml:lang="en">Applies an RFC 7386 merge patch to <paramref name="target" /> in place.</para>
		///     <para xml:lang="zh-CN">将 RFC 7386 合并补丁原地应用于 <paramref name="target" />。</para>
		/// </summary>
		public static void ApplyInPlace(JsonObject target, JsonObject patch)
		{
			ArgumentNullException.ThrowIfNull(target, "target");
			ArgumentNullException.ThrowIfNull(patch, "patch");
			foreach (KeyValuePair<string, JsonNode> item in patch)
			{
				JsonObject obj;
				if (IsJsonNull(item.Value))
				{
					target.Remove(item.Key);
				}
				else if (TryGetObject(item.Value, out obj))
				{
					JsonObject jsonObject;
					if (target.TryGetPropertyValue(item.Key, out JsonNode jsonNode) && TryGetObject(jsonNode, out JsonObject obj2))
					{
						jsonObject = obj2;
					}
					else
					{
						jsonObject = new JsonObject();
						target[item.Key] = jsonObject;
					}
					ApplyInPlace(jsonObject, obj);
				}
				else
				{
					target[item.Key] = item.Value.DeepClone();
				}
			}
		}

		private static bool TryGetObject(JsonNode? node, out JsonObject obj)
		{
			obj = (node as JsonObject) ?? null;
			return node is JsonObject;
		}

		private static bool IsJsonNull(JsonNode? node)
		{
			if (node == null)
			{
				return true;
			}
			return node.GetValueKind() == JsonValueKind.Null;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Implements JSON Patch (RFC 6902) operations for <see cref="T:System.Text.Json.Nodes.JsonNode" /> DOM values.
	///         See <see href="https://www.rfc-editor.org/rfc/rfc6902" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为 <see cref="T:System.Text.Json.Nodes.JsonNode" /> DOM 值实现 JSON 补丁（RFC 6902）操作。
	///         参见 <see href="https://www.rfc-editor.org/rfc/rfc6902" />。
	///     </para>
	/// </summary>
	public static class JsonPatch
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Applies a JSON Patch (RFC 6902) document to <paramref name="target" /> and returns the patched
		///         result. The document must be an array of operation objects.
		///     </para>
		///     <para xml:lang="zh-CN">将 JSON 补丁（RFC 6902）文档应用于 <paramref name="target" /> 并返回应用后的结果。该文档必须是操作对象数组。</para>
		/// </summary>
		/// <exception cref="T:STS2RitsuLib.Utils.Json.JsonPatchException">
		///     <para xml:lang="en">Thrown when the patch document is malformed or cannot be applied.</para>
		///     <para xml:lang="zh-CN">当补丁文档格式错误或无法应用时引发。</para>
		/// </exception>
		public static JsonNode? Apply(JsonNode? target, JsonNode? patchDocument)
		{
			if (patchDocument == null)
			{
				throw new JsonPatchException("JSON Patch document must be an array.");
			}
			if (patchDocument is JsonArray arr)
			{
				return Apply(target, ParseOperations(arr));
			}
			throw new JsonPatchException("JSON Patch document must be an array.");
		}

		/// <summary>
		///     <para xml:lang="en">Applies a JSON Patch document to <paramref name="target" /> and returns the patched result.</para>
		///     <para xml:lang="zh-CN">将 JSON Patch 文档应用于 <paramref name="target" /> 并返回应用后的结果。</para>
		/// </summary>
		/// <exception cref="T:STS2RitsuLib.Utils.Json.JsonPatchException">
		///     <para xml:lang="en">Thrown when an operation cannot be applied.</para>
		///     <para xml:lang="zh-CN">当某项操作无法应用时引发。</para>
		/// </exception>
		public static JsonNode? Apply(JsonNode? target, IEnumerable<JsonPatchOperation> operations)
		{
			ArgumentNullException.ThrowIfNull(operations, "operations");
			JsonNode seed = target?.DeepClone();
			return operations.Aggregate(seed, ApplyOne);
		}

		private static JsonNode? ApplyOne(JsonNode? root, JsonPatchOperation op)
		{
			if (op == null)
			{
				throw new JsonPatchException("JSON Patch operations cannot be null.");
			}
			string text = op.Op ?? throw new JsonPatchException("Missing required member 'op'.");
			string text2 = op.Path ?? throw new JsonPatchException("Missing required member 'path'.");
			string[] array = ParsePointer(text2, "path");
			switch (text)
			{
			case "add":
				return Add(root, text2, array, op.Value);
			case "remove":
				return Remove(root, text2, array);
			case "replace":
				return Replace(root, text2, array, op.Value);
			case "move":
				return Move(root, text2, array, op.From);
			case "copy":
				return Copy(root, text2, array, op.From);
			case "test":
				Test(root, text2, array, op.Value);
				return root;
			default:
				throw new JsonPatchException("Unsupported JSON Patch operation: '" + op.Op + "'.");
			}
		}

		private static JsonNode? Add(JsonNode? root, string path, IReadOnlyList<string> segments, JsonNode? value)
		{
			if (segments.Count == 0)
			{
				return value?.DeepClone();
			}
			(JsonNode parent, string segment) tuple = ResolveParent(root, path, segments);
			JsonNode item = tuple.parent;
			string item2 = tuple.segment;
			JsonNode jsonNode = item;
			if (!(jsonNode is JsonObject jsonObject))
			{
				if (jsonNode is JsonArray jsonArray)
				{
					if (item2 == "-")
					{
						jsonArray.Add(value?.DeepClone());
						return root;
					}
					JsonArray jsonArray2 = jsonArray;
					if (!TryParseArrayIndex(item2, out var index) || index > jsonArray2.Count)
					{
						throw new JsonPatchException("Invalid array index for add: '" + item2 + "'.");
					}
					jsonArray2.Insert(index, value?.DeepClone());
					return root;
				}
				throw new JsonPatchException("Cannot add at path '" + path + "': parent is not a container.");
			}
			jsonObject[item2] = value?.DeepClone();
			return root;
		}

		private static JsonNode? Remove(JsonNode? root, string path, IReadOnlyList<string> segments)
		{
			if (segments.Count == 0)
			{
				return null;
			}
			(JsonNode parent, string segment) tuple = ResolveParent(root, path, segments);
			JsonNode item = tuple.parent;
			string item2 = tuple.segment;
			JsonNode jsonNode = item;
			if (!(jsonNode is JsonObject jsonObject))
			{
				if (jsonNode is JsonArray jsonArray)
				{
					if (!TryParseArrayIndex(item2, out var index) || index >= jsonArray.Count)
					{
						throw new JsonPatchException("Invalid array index for remove: '" + item2 + "'.");
					}
					jsonArray.RemoveAt(index);
					return root;
				}
				throw new JsonPatchException("Cannot remove at path '" + path + "': parent is not a container.");
			}
			if (!jsonObject.Remove(item2))
			{
				throw new JsonPatchException("Path not found for remove: '" + path + "'.");
			}
			return root;
		}

		private static JsonNode? Replace(JsonNode? root, string path, IReadOnlyList<string> segments, JsonNode? value)
		{
			if (segments.Count == 0)
			{
				return value?.DeepClone();
			}
			(JsonNode parent, string segment) tuple = ResolveParent(root, path, segments);
			JsonNode item = tuple.parent;
			string item2 = tuple.segment;
			JsonNode jsonNode = item;
			if (!(jsonNode is JsonObject jsonObject))
			{
				if (jsonNode is JsonArray jsonArray)
				{
					if (!TryParseArrayIndex(item2, out var index) || index >= jsonArray.Count)
					{
						throw new JsonPatchException("Invalid array index for replace: '" + item2 + "'.");
					}
					jsonArray[index] = value?.DeepClone();
					return root;
				}
				throw new JsonPatchException("Cannot replace at path '" + path + "': parent is not a container.");
			}
			if (!jsonObject.ContainsKey(item2))
			{
				throw new JsonPatchException("Path not found for replace: '" + path + "'.");
			}
			jsonObject[item2] = value?.DeepClone();
			return root;
		}

		private static JsonNode? Move(JsonNode? root, string path, IReadOnlyList<string> pathSegments, string? fromRaw)
		{
			if (fromRaw == null)
			{
				throw new JsonPatchException("Missing 'from' for move operation.");
			}
			string[] array = ParsePointer(fromRaw, "from");
			if (IsProperPrefix(array, pathSegments))
			{
				throw new JsonPatchException("The 'path' of a move operation cannot be a child of its 'from' path.");
			}
			JsonNode value = GetRequired(root, fromRaw, array)?.DeepClone();
			root = Remove(root, fromRaw, array);
			return Add(root, path, pathSegments, value);
		}

		private static JsonNode? Copy(JsonNode? root, string path, IReadOnlyList<string> pathSegments, string? fromRaw)
		{
			if (fromRaw == null)
			{
				throw new JsonPatchException("Missing 'from' for copy operation.");
			}
			string[] segments = ParsePointer(fromRaw, "from");
			JsonNode value = GetRequired(root, fromRaw, segments)?.DeepClone();
			return Add(root, path, pathSegments, value);
		}

		private static void Test(JsonNode? root, string path, IReadOnlyList<string> segments, JsonNode? expected)
		{
			if (!TryGetAtPath(root, segments, out JsonNode value) || !JsonNode.DeepEquals(value, expected))
			{
				throw new JsonPatchException("Test operation failed at '" + path + "'.");
			}
		}

		private static JsonNode? GetRequired(JsonNode? root, string path, IReadOnlyList<string> segments)
		{
			if (!TryGetAtPath(root, segments, out JsonNode value))
			{
				throw new JsonPatchException("Path not found: '" + path + "'.");
			}
			return value;
		}

		private static (JsonNode parent, string segment) ResolveParent(JsonNode? root, string path, IReadOnlyList<string> segments)
		{
			if (segments.Count == 0)
			{
				throw new JsonPatchException("Invalid path: '" + path + "'.");
			}
			JsonNode jsonNode = root ?? throw new JsonPatchException("Cannot traverse path '" + path + "': encountered a non-container node.");
			for (int i = 0; i < segments.Count - 1; i++)
			{
				string text = segments[i];
				JsonNode jsonNode2 = jsonNode;
				if (!(jsonNode2 is JsonObject jsonObject))
				{
					if (!(jsonNode2 is JsonArray jsonArray))
					{
						throw new JsonPatchException("Cannot traverse path '" + path + "': encountered a non-container node.");
					}
					JsonArray jsonArray2 = jsonArray;
					if (!TryParseArrayIndex(text, out var index) || index >= jsonArray2.Count)
					{
						throw new JsonPatchException("Invalid array index: '" + text + "'.");
					}
					jsonNode = jsonArray2[index] ?? throw new JsonPatchException("Cannot traverse path '" + path + "': encountered a non-container node.");
				}
				else
				{
					if (!jsonObject.TryGetPropertyValue(text, out JsonNode jsonNode3))
					{
						throw new JsonPatchException("Path not found: '" + path + "'.");
					}
					jsonNode = jsonNode3 ?? throw new JsonPatchException("Cannot traverse path '" + path + "': encountered a non-container node.");
				}
			}
			return (parent: jsonNode, segment: segments[segments.Count - 1]);
		}

		private static bool TryGetAtPath(JsonNode? root, IReadOnlyList<string> segments, out JsonNode? value)
		{
			value = root;
			foreach (string segment in segments)
			{
				JsonNode jsonNode = value;
				JsonNode jsonNode2;
				if (!(jsonNode is JsonObject jsonObject))
				{
					if (jsonNode is JsonArray jsonArray)
					{
						JsonArray jsonArray2 = jsonArray;
						if (TryParseArrayIndex(segment, out var index) && index < jsonArray2.Count)
						{
							value = jsonArray2[index];
							continue;
						}
					}
				}
				else if (jsonObject.TryGetPropertyValue(segment, out jsonNode2))
				{
					value = jsonNode2;
					continue;
				}
				value = null;
				return false;
			}
			return true;
		}

		private static string[] ParsePointer(string pointer, string memberName)
		{
			if (pointer.Length == 0)
			{
				return Array.Empty<string>();
			}
			if (pointer[0] != '/')
			{
				throw new JsonPatchException("Member '" + memberName + "' must be an RFC 6901 JSON Pointer.");
			}
			return (from segment in pointer.Substring(1).Split('/')
				select DecodePointerSegment(segment, memberName)).ToArray();
		}

		private static string DecodePointerSegment(string segment, string memberName)
		{
			if (!segment.Contains('~'))
			{
				return segment;
			}
			StringBuilder stringBuilder = new StringBuilder(segment.Length);
			for (int i = 0; i < segment.Length; i++)
			{
				char c = segment[i];
				if (c != '~')
				{
					stringBuilder.Append(c);
					continue;
				}
				if (++i >= segment.Length)
				{
					throw new JsonPatchException("Member '" + memberName + "' contains an invalid JSON Pointer escape.");
				}
				StringBuilder stringBuilder2 = stringBuilder;
				stringBuilder2.Append(segment[i] switch
				{
					'0' => '~', 
					'1' => '/', 
					_ => throw new JsonPatchException("Member '" + memberName + "' contains an invalid JSON Pointer escape."), 
				});
			}
			return stringBuilder.ToString();
		}

		private static bool TryParseArrayIndex(string segment, out int index)
		{
			index = 0;
			if (segment.Length == 0 || (segment.Length > 1 && segment[0] == '0'))
			{
				return false;
			}
			foreach (char c in segment)
			{
				if ((c < '0' || c > '9') ? true : false)
				{
					return false;
				}
				int num = c - 48;
				if (index > (int.MaxValue - num) / 10)
				{
					return false;
				}
				index = index * 10 + num;
			}
			return true;
		}

		private static bool IsProperPrefix(IReadOnlyList<string> candidate, IReadOnlyList<string> path)
		{
			if (candidate.Count >= path.Count)
			{
				return false;
			}
			for (int i = 0; i < candidate.Count; i++)
			{
				if (!string.Equals(candidate[i], path[i], StringComparison.Ordinal))
				{
					return false;
				}
			}
			return true;
		}

		private static IEnumerable<JsonPatchOperation> ParseOperations(JsonArray arr)
		{
			foreach (JsonNode item in arr)
			{
				if (!(item is JsonObject jsonObject))
				{
					throw new JsonPatchException("JSON Patch array elements must be objects.");
				}
				string text = ReadRequiredString(jsonObject, "op");
				string path = ReadRequiredString(jsonObject, "path");
				string text2 = null;
				JsonNode jsonNode = null;
				switch (text)
				{
				case "add":
				case "replace":
				case "test":
					if (!jsonObject.TryGetPropertyValue("value", out jsonNode))
					{
						throw new JsonPatchException("Missing required member 'value' for '" + text + "' operation.");
					}
					break;
				case "move":
				case "copy":
					text2 = ReadRequiredString(jsonObject, "from");
					break;
				}
				yield return new JsonPatchOperation(text, path, text2, jsonNode?.DeepClone());
			}
		}

		private static string ReadRequiredString(JsonObject obj, string key)
		{
			if (!obj.TryGetPropertyValue(key, out JsonNode jsonNode) || !(jsonNode is JsonValue jsonValue))
			{
				throw new JsonPatchException("Missing required member '" + key + "'.");
			}
			try
			{
				return jsonValue.GetValue<string>();
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				throw new JsonPatchException("Member '" + key + "' must be a string.");
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Represents one JSON Patch operation object (RFC 6902).</para>
	///     <para xml:lang="zh-CN">表示一个 JSON 补丁操作对象（RFC 6902）。</para>
	/// </summary>
	public sealed record JsonPatchOperation(string Op, string Path, string? From = null, JsonNode? Value = null);
	/// <summary>
	///     <para xml:lang="en">Represents an error raised when a JSON Patch cannot be applied.</para>
