	/// <summary>
	///     <para xml:lang="en">
	///         Provides RFC 6901 JSON Pointer helpers for <see cref="T:System.Text.Json.Nodes.JsonNode" /> DOM navigation and mutation.
	///         The empty string selects the document root; <c>/</c> selects an object member whose key is empty.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为 <see cref="T:System.Text.Json.Nodes.JsonNode" /> DOM 导航和修改提供 RFC 6901 JSON 指针辅助方法。空字符串选择文档根；
	///         <c>/</c> 选择键为空字符串的对象成员。
	///     </para>
	/// </summary>
	public static class JsonPointer
	{
		/// <summary>
		///     <para xml:lang="en">Checks whether the pointer is empty and therefore selects the document root.</para>
		///     <para xml:lang="zh-CN">检查指针是否为空，从而选择文档根。</para>
		/// </summary>
		public static bool IsRoot(string? pointer)
		{
			if (string.IsNullOrEmpty(pointer))
			{
				return true;
			}
			return pointer.Trim().Length == 0;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Normalizes a JSON Pointer fragment for DOM navigation. Empty input remains empty; authors may
		///         omit the leading slash for non-root pointers.
		///     </para>
		///     <para xml:lang="zh-CN">规范化用于 DOM 导航的 JSON 指针片段。空输入保持为空；非根指针编写时可省略前导斜杠。</para>
		/// </summary>
		public static string Normalize(string rawPointer)
		{
			string text = rawPointer.Trim();
			if (text.Length == 0)
			{
				return string.Empty;
			}
			if (!text.StartsWith('/'))
			{
				return "/" + text;
			}
			return text;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves a node under <paramref name="root" /> by JSON Pointer, or returns
		///         <see langword="null" /> when no node exists at the pointer.
		///     </para>
		///     <para xml:lang="zh-CN">通过 JSON 指针解析 <paramref name="root" /> 下的节点；该指针位置不存在节点时返回 <see langword="null" />。</para>
		/// </summary>
		public static JsonNode? Get(JsonNode root, string jsonPointer)
		{
			if (IsRoot(jsonPointer))
			{
				return root;
			}
			JsonNode jsonNode = root;
			foreach (string item in EnumerateSegments(jsonPointer))
			{
				JsonNode jsonNode2 = jsonNode;
				if (!(jsonNode2 is JsonObject jsonObject))
				{
					if (jsonNode2 is JsonArray jsonArray)
					{
						JsonArray jsonArray2 = jsonArray;
						if (int.TryParse(item, out var result) && result >= 0 && result < jsonArray2.Count)
						{
							jsonNode = jsonArray2[result];
							continue;
						}
					}
					return null;
				}
				if (!jsonObject.TryGetPropertyValue(item, out jsonNode))
				{
					return null;
				}
			}
			return jsonNode;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets <paramref name="value" /> at <paramref name="jsonPointer" /> under an object root. A
		///         <see langword="null" /> value removes a targeted object property; the empty pointer replaces or
		///         clears the root object's members.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在对象根下的 <paramref name="jsonPointer" /> 位置设置 <paramref name="value" />。
		///         <see langword="null" /> 值会移除目标对象属性；空指针会替换或清空根对象的成员。
		///     </para>
		/// </summary>
		public static void Set(JsonObject documentRoot, string jsonPointer, JsonNode? value)
		{
			if (IsRoot(jsonPointer))
			{
				if (!(value is JsonObject jsonObject))
				{
					if (value == null)
					{
						documentRoot.Clear();
					}
					return;
				}
				documentRoot.Clear();
				{
					foreach (KeyValuePair<string, JsonNode> item in jsonObject)
					{
						documentRoot[item.Key] = item.Value?.DeepClone();
					}
					return;
				}
			}
			string[] array = EnumerateSegments(jsonPointer).ToArray();
			if (array.Length == 0)
			{
				return;
			}
			JsonNode jsonNode = documentRoot;
			for (int i = 0; i < array.Length - 1; i++)
			{
				string segment = array[i];
				jsonNode = EnsureWalk(jsonNode, segment);
				if (jsonNode == null)
				{
					return;
				}
			}
			string text = array[^1];
			JsonNode jsonNode2 = jsonNode;
			if (!(jsonNode2 is JsonObject jsonObject2))
			{
				if (!(jsonNode2 is JsonArray jsonArray))
				{
					return;
				}
				JsonArray jsonArray2 = jsonArray;
				if (int.TryParse(text, out var result))
				{
					while (jsonArray2.Count <= result)
					{
						jsonArray2.Add(null);
					}
					jsonArray2[result] = value?.DeepClone();
				}
			}
			else
			{
				JsonObject jsonObject3 = jsonObject2;
				if (value == null)
				{
					jsonObject3.Remove(text);
				}
				else
				{
					jsonObject2[text] = value.DeepClone();
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">Enumerates decoded JSON Pointer segments. In particular, <c>/</c> yields one empty segment.</para>
		///     <para xml:lang="zh-CN">枚举已解码的 JSON 指针段。特别地，<c>/</c> 会产生一个空段。</para>
		/// </summary>
		public static IEnumerable<string> EnumerateSegments(string jsonPointer)
		{
			string text = jsonPointer.TrimStart();
			if (text.Length != 0)
			{
				if (text[0] == '/')
				{
					text = text.Substring(1);
				}
				string[] array = text.Split('/');
				foreach (string segment in array)
				{
					yield return DecodeSegment(segment);
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">Decodes the RFC 6901 <c>~0</c> and <c>~1</c> segment escapes.</para>
		///     <para xml:lang="zh-CN">解码 RFC 6901 的 <c>~0</c> 和 <c>~1</c> 段转义。</para>
		/// </summary>
		public static string DecodeSegment(string segment)
		{
			return segment.Replace("~1", "/", StringComparison.Ordinal).Replace("~0", "~", StringComparison.Ordinal);
		}

		private static JsonNode? EnsureWalk(JsonNode parent, string segment)
		{
			if (!(parent is JsonObject jsonObject))
			{
				if (parent is JsonArray jsonArray)
				{
					JsonArray jsonArray2 = jsonArray;
					if (int.TryParse(segment, out var result))
					{
						while (jsonArray2.Count <= result)
						{
							jsonArray2.Add(null);
						}
						if (jsonArray2[result] is JsonObject result2)
						{
							return result2;
						}
						return jsonArray2[result] = new JsonObject();
					}
				}
				return null;
			}
			if (jsonObject.TryGetPropertyValue(segment, out JsonNode jsonNode2) && jsonNode2 != null)
			{
				return jsonNode2;
			}
			return jsonObject[segment] = new JsonObject();
		}
	}
