		/// </summary>
		public static HarmonyAsyncAwaitSites FindAwaitSiteMatches(IReadOnlyList<CodeInstruction> code, string description = "async await sites")
		{
			return new HarmonyAsyncAwaitSites(description, FindAwaitSites(code));
