		}

		/// <summary>
		///     <para xml:lang="en">Redirects calls that are immediately awaited by the state machine.</para>
		///     <para xml:lang="zh-CN">重定向被状态机直接等待的调用。</para>
		/// </summary>
		public static HarmonyIlRewriteReport RedirectAwaitedCalls(IList<CodeInstruction> code, string operation, MethodInfo fromMethod, MethodInfo toMethod, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null)
		{
			ArgumentNullException.ThrowIfNull(code, "code");
