		///     <para xml:lang="zh-CN">替换被状态机直接等待的调用。</para>
		/// </summary>
		public static HarmonyIlRewriteReport ReplaceAwaitedCalls(IList<CodeInstruction> code, string operation, MethodInfo fromMethod, Func<HarmonyAsyncAwaitSite, IReadOnlyList<CodeInstruction>> buildReplacement, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null)
		{
			ArgumentNullException.ThrowIfNull(code, "code");
