		/// </summary>
		public static void EnsureCompatibleAwaitedCallReplacement(MethodInfo fromMethod, MethodInfo toMethod)
		{
			ArgumentNullException.ThrowIfNull(fromMethod, "fromMethod");
			ArgumentNullException.ThrowIfNull(toMethod, "toMethod");
			if (fromMethod.ReturnType != toMethod.ReturnType)
			{
				throw new ArgumentException($"Awaited-call replacement must return exactly {fromMethod.ReturnType}; got {toMethod.ReturnType}.", "toMethod");
			}
			Type[] array = (from parameter in fromMethod.GetParameters()
				select parameter.ParameterType).ToArray();
			Type[] array2 = (from parameter in toMethod.GetParameters()
				select parameter.ParameterType).ToArray();
			if (fromMethod.IsStatic)
			{
				if (!toMethod.IsStatic || !Enumerable.SequenceEqual(array, array2))
				{
					throw NewSignatureException(fromMethod, toMethod);
				}
				return;
			}
			if (!toMethod.IsStatic)
			{
				if (Enumerable.SequenceEqual(array, array2))
				{
					return;
				}
				throw NewSignatureException(fromMethod, toMethod);
			}
			Type c = fromMethod.DeclaringType ?? throw new ArgumentException("Cannot redirect an instance method with no declaring type.", "fromMethod");
			if (array2.Length == array.Length + 1 && array2[0].IsAssignableFrom(c) && array.SequenceEqual(array2.Skip(1)))
			{
				return;
			}
			throw NewSignatureException(fromMethod, toMethod);
		}

		private static void ValidateAwaitedCallReplacement(HarmonyAsyncAwaitSite site, IReadOnlyList<CodeInstruction> replacement)
		{
			if (replacement.Count == 0)
			{
				throw new ArgumentException("Awaited-call replacement cannot be empty.", "replacement");
			}
			if (!TryGetPushedType(replacement[replacement.Count - 1], out Type type) || !site.AwaitableType.IsAssignableFrom(type))
			{
				throw new ArgumentException($"Awaited-call replacement must leave an awaitable assignable to {site.AwaitableType} on the stack.");
			}
		}

		private static bool TryReadAwaitSite(IReadOnlyList<CodeInstruction> code, int getAwaiterIndex, out HarmonyAsyncAwaitSite site)
		{
			site = null;
			if (!TryGetAwaiterMethod(code[getAwaiterIndex], out MethodInfo getAwaiterMethod))
			{
				return false;
			}
			Type returnType = getAwaiterMethod.ReturnType;
			Type awaitableType = getAwaiterMethod.DeclaringType ?? typeof(object);
			int num = FindAwaitableProducerIndex(code, getAwaiterIndex, awaitableType);
			if (num < 0)
			{
				return false;
			}
			if (!TryFindAwaiterStore(code, getAwaiterIndex + 1, out var storeIndex, out var awaiterLocal))
			{
				return false;
			}
			if (!TryFindIsCompletedCheck(code, storeIndex + 1, awaiterLocal, returnType, out int isCompletedIndex, out MethodInfo isCompletedGetter))
			{
				return false;
			}
			int? awaitOnCompletedIndex = (TryFindAwaitOnCompleted(code, isCompletedIndex + 1, returnType, out (int, MethodInfo) method) ? new int?(method.Item1) : ((int?)null));
			if (!TryFindGetResult(code, isCompletedIndex + 1, awaiterLocal, returnType, out int getResultIndex, out MethodInfo getResultMethod))
			{
				return false;
			}
			site = new HarmonyAsyncAwaitSite(num, getAwaiterIndex, storeIndex, isCompletedIndex, awaitOnCompletedIndex, getResultIndex, awaiterLocal, awaitableType, returnType, getResultMethod.ReturnType, GetCallOperand(code[num]), getAwaiterMethod, isCompletedGetter, method.Item2, getResultMethod, (!awaitOnCompletedIndex.HasValue) ? ((int?)null) : TryFindSuspendedState(code, isCompletedIndex + 1, awaitOnCompletedIndex.Value));
			return true;
		}

		private static bool TryGetAwaiterMethod(CodeInstruction instruction, out MethodInfo getAwaiterMethod)
		{
			if (IsCallInstruction(instruction) && instruction.operand is MethodInfo { Name: "GetAwaiter" } methodInfo && IsAwaiterType(methodInfo.ReturnType))
			{
				getAwaiterMethod = methodInfo;
				return true;
			}
			getAwaiterMethod = null;
			return false;
		}

		private static bool IsAwaiterType(Type? type)
		{
			if (type == null)
			{
				return false;
			}
			MethodInfo methodInfo = AccessTools.PropertyGetter(type, "IsCompleted");
			if ((object)methodInfo != null)
			{
				Type returnType = methodInfo.ReturnType;
				if ((object)returnType != null && returnType == typeof(bool))
				{
					return AccessTools.Method(type, "GetResult", (Type[])null, (Type[])null) != null;
				}
			}
			return false;
		}

		private static int FindAwaitableProducerIndex(IReadOnlyList<CodeInstruction> code, int getAwaiterIndex, Type awaitableType)
		{
			for (int num = getAwaiterIndex - 1; num >= Math.Max(0, getAwaiterIndex - 12); num--)
			{
				if (TryGetPushedType(code[num], out Type type) && awaitableType.IsAssignableFrom(type))
				{
					return num;
				}
			}
			return -1;
		}

		private static bool TryFindAwaiterStore(IReadOnlyList<CodeInstruction> code, int startIndex, out int storeIndex, out HarmonyIlLocalRef awaiterLocal)
		{
			for (int i = startIndex; i < Math.Min(code.Count, startIndex + 4); i++)
			{
				if (HarmonyIl.TryGetLocalStore(code[i], out awaiterLocal))
				{
					storeIndex = i;
					return true;
				}
			}
			storeIndex = -1;
			awaiterLocal = default(HarmonyIlLocalRef);
			return false;
		}

		private static bool TryFindIsCompletedCheck(IReadOnlyList<CodeInstruction> code, int startIndex, HarmonyIlLocalRef awaiterLocal, Type awaiterType, out int isCompletedIndex, out MethodInfo isCompletedGetter)
		{
			int num = Math.Min(code.Count, startIndex + 12);
			for (int i = startIndex; i < num; i++)
			{
				if (IsAwaiterIsCompletedCall(code[i], awaiterType, out isCompletedGetter) && i != 0 && LoadsLocalOrAddress(code[i - 1], awaiterLocal))
				{
					isCompletedIndex = i;
					return true;
