	/// <summary>
	///     <para xml:lang="en">A collection of async await-site matches with assertion helpers.</para>
	///     <para xml:lang="zh-CN">带断言辅助方法的异步等待点匹配集合。</para>
	/// </summary>
	public sealed class HarmonyAsyncAwaitSites
	{
		/// <summary>
		///     <para xml:lang="en">Human-readable description used in assertion errors.</para>
		///     <para xml:lang="zh-CN">断言错误中使用的可读描述。</para>
		/// </summary>
		public string Description { get; }

		/// <summary>
		///     <para xml:lang="en">Matched await sites.</para>
		///     <para xml:lang="zh-CN">已匹配的等待点。</para>
		/// </summary>
		public IReadOnlyList<HarmonyAsyncAwaitSite> Items { get; }

		/// <summary>
		///     <para xml:lang="en">Number of matched await sites.</para>
		///     <para xml:lang="zh-CN">匹配到的等待点数量。</para>
		/// </summary>
		public int Count => Items.Count;

		/// <summary>
		///     <para xml:lang="en">Returns true when at least one await site exists.</para>
		///     <para xml:lang="zh-CN">存在至少一个等待点时返回 true。</para>
		/// </summary>
		public bool Any => Items.Count > 0;

		internal HarmonyAsyncAwaitSites(string description, IEnumerable<HarmonyAsyncAwaitSite> items)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(description, "description");
			ArgumentNullException.ThrowIfNull(items, "items");
			Description = description;
			List<HarmonyAsyncAwaitSite> list = new List<HarmonyAsyncAwaitSite>();
			list.AddRange(items);
			Items = new <>z__ReadOnlyList<HarmonyAsyncAwaitSite>(list);
		}

		/// <summary>
		///     <para xml:lang="en">Requires exactly one await site and returns it.</para>
		///     <para xml:lang="zh-CN">要求恰好一个等待点并返回它。</para>
		/// </summary>
		public HarmonyAsyncAwaitSite RequireSingle()
		{
			if (Items.Count != 1)
			{
				throw NewCountException("exactly 1");
			}
			return Items[0];
		}

		/// <summary>
		///     <para xml:lang="en">Requires an exact await-site count.</para>
		///     <para xml:lang="zh-CN">要求精确的等待点数量。</para>
		/// </summary>
		public HarmonyAsyncAwaitSites RequireExactly(int count)
		{
			if (Items.Count != count)
			{
				throw NewCountException($"exactly {count}");
			}
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Requires at least <paramref name="count" /> await sites.</para>
		///     <para xml:lang="zh-CN">要求至少 <paramref name="count" /> 个等待点。</para>
		/// </summary>
		public HarmonyAsyncAwaitSites RequireAtLeast(int count)
		{
			if (Items.Count < count)
			{
				throw NewCountException($"at least {count}");
			}
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Returns a compact diagnostic string.</para>
		///     <para xml:lang="zh-CN">返回紧凑诊断字符串。</para>
		/// </summary>
		public string Describe()
		{
			return $"{Description}: count={Items.Count}, getAwaiterIndexes=[{string.Join(", ", Items.Select((HarmonyAsyncAwaitSite site) => site.GetAwaiterIndex))}]";
		}

		private InvalidOperationException NewCountException(string expected)
		{
			return new InvalidOperationException($"{Description} matched {Items.Count} await site(s), expected {expected}. getAwaiterIndexes=[{string.Join(", ", Items.Select((HarmonyAsyncAwaitSite site) => site.GetAwaiterIndex))}].");
		}
	}
	/// <summary>
	///     <para xml:lang="en">Safe wrappers for Harmony patches that replace or compose asynchronous return values.</para>
	///     <para xml:lang="zh-CN">用于 Harmony 补丁替换或组合异步返回值的安全包装器。</para>
	/// </summary>
	public static class HarmonyAsyncTaskBridge
	{
		private const string TelemetrySurface = "ritsulib_harmony_async_task_bridge";

		/// <summary>
		///     <para xml:lang="en">Awaits <paramref name="continuation" /> before awaiting the original task.</para>
		///     <para xml:lang="zh-CN">在等待原始任务前等待 <paramref name="continuation" /> 完成。</para>
		/// </summary>
		public static async Task Before(Task originalTask, Func<Task> continuation)
		{
			ArgumentNullException.ThrowIfNull(originalTask, "originalTask");
			ArgumentNullException.ThrowIfNull(continuation, "continuation");
			await InvokeContinuation(continuation);
			await originalTask;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Runs <paramref name="continuation" /> before awaiting the original task and returns the
		///         original result.
		///     </para>
		///     <para xml:lang="zh-CN">在等待原始任务前运行 <paramref name="continuation" />，并返回原始结果。</para>
		/// </summary>
		public static async Task<T> Before<T>(Task<T> originalTask, Func<Task> continuation)
		{
			ArgumentNullException.ThrowIfNull(originalTask, "originalTask");
			ArgumentNullException.ThrowIfNull(continuation, "continuation");
			await InvokeContinuation(continuation);
			return await originalTask;
		}

		/// <summary>
		///     <para xml:lang="en">Runs <paramref name="continuation" /> after the original task completes.</para>
		///     <para xml:lang="zh-CN">在原始任务完成后运行 <paramref name="continuation" />。</para>
		/// </summary>
		public static async Task After(Task originalTask, Action continuation)
		{
			ArgumentNullException.ThrowIfNull(originalTask, "originalTask");
			ArgumentNullException.ThrowIfNull(continuation, "continuation");
			await originalTask;
			InvokeContinuation(continuation);
		}

		/// <summary>
		///     <para xml:lang="en">Runs <paramref name="continuation" /> after the original task completes.</para>
		///     <para xml:lang="zh-CN">在原始任务完成后运行 <paramref name="continuation" />。</para>
		/// </summary>
		public static async Task After(Task originalTask, Func<Task> continuation)
		{
			ArgumentNullException.ThrowIfNull(originalTask, "originalTask");
			ArgumentNullException.ThrowIfNull(continuation, "continuation");
			await originalTask;
			await InvokeContinuation(continuation);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Runs <paramref name="continuation" /> after the original task completes and returns the
		///         original result.
		///     </para>
		///     <para xml:lang="zh-CN">在原始任务完成后运行 <paramref name="continuation" />，并返回原始结果。</para>
		/// </summary>
		public static async Task<T> After<T>(Task<T> originalTask, Action<T> continuation)
		{
			ArgumentNullException.ThrowIfNull(originalTask, "originalTask");
			ArgumentNullException.ThrowIfNull(continuation, "continuation");
			T result = await originalTask;
			InvokeContinuation(delegate
			{
				continuation(result);
			});
			return result;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Runs <paramref name="continuation" /> after the original task completes and returns the
		///         original result.
		///     </para>
		///     <para xml:lang="zh-CN">在原始任务完成后运行 <paramref name="continuation" />，并返回原始结果。</para>
		/// </summary>
		public static async Task<T> After<T>(Task<T> originalTask, Func<T, Task> continuation)
		{
			ArgumentNullException.ThrowIfNull(originalTask, "originalTask");
			ArgumentNullException.ThrowIfNull(continuation, "continuation");
			T result = await originalTask;
			await InvokeContinuation(() => continuation(result));
			return result;
		}

		/// <summary>
		///     <para xml:lang="en">Replaces the original task with <paramref name="replacement" />.</para>
		///     <para xml:lang="zh-CN">使用 <paramref name="replacement" /> 替换原始任务。</para>
		/// </summary>
		public static async Task Replace(Task originalTask, Func<Task, Task> replacement)
		{
			ArgumentNullException.ThrowIfNull(originalTask, "originalTask");
			ArgumentNullException.ThrowIfNull(replacement, "replacement");
			await InvokeContinuation(() => replacement(originalTask));
		}

		/// <summary>
		///     <para xml:lang="en">Replaces the original task with <paramref name="replacement" />.</para>
		///     <para xml:lang="zh-CN">使用 <paramref name="replacement" /> 替换原始任务。</para>
		/// </summary>
		public static async Task<T> Replace<T>(Task<T> originalTask, Func<Task<T>, Task<T>> replacement)
		{
			ArgumentNullException.ThrowIfNull(originalTask, "originalTask");
			ArgumentNullException.ThrowIfNull(replacement, "replacement");
			return await InvokeContinuation(() => replacement(originalTask));
		}

		private static void InvokeContinuation(Action continuation)
		{
			try
			{
				continuation();
			}
			catch (Exception exception)
			{
				DiagnosticsTelemetryCollector.CaptureExceptionForAuthorizedApplicants(exception, "ritsulib_harmony_async_task_bridge");
				throw;
			}
		}

		private static async Task InvokeContinuation(Func<Task> continuation)
		{
			try
			{
				await continuation();
			}
			catch (Exception exception)
			{
				DiagnosticsTelemetryCollector.CaptureExceptionForAuthorizedApplicants(exception, "ritsulib_harmony_async_task_bridge");
				throw;
			}
		}

		private static async Task<T> InvokeContinuation<T>(Func<Task<T>> continuation)
		{
			try
			{
				return await continuation();
			}
			catch (Exception exception)
			{
				DiagnosticsTelemetryCollector.CaptureExceptionForAuthorizedApplicants(exception, "ritsulib_harmony_async_task_bridge");
				throw;
			}
		}
	}
