		/// <summary>
		///     <para xml:lang="en">Converts a local-store instruction to the corresponding local-load instruction.</para>
		///     <para xml:lang="zh-CN">将本地变量存储指令转换为对应的本地变量读取指令。</para>
		/// </summary>
		public static CodeInstruction LoadLocalFromStore(CodeInstruction store)
		{
			//IL_0023: Unknown result type (might be due to invalid IL or missing references)
			//IL_0029: Expected O, but got Unknown
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			//IL_0047: Expected O, but got Unknown
			//IL_005f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0065: Expected O, but got Unknown
			//IL_007d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0083: Expected O, but got Unknown
			//IL_00a0: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a6: Expected O, but got Unknown
			//IL_00c3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c9: Expected O, but got Unknown
			ArgumentNullException.ThrowIfNull(store, "store");
			if (store.opcode == OpCodes.Stloc_0)
			{
				return new CodeInstruction(OpCodes.Ldloc_0, (object)null);
			}
			if (store.opcode == OpCodes.Stloc_1)
			{
				return new CodeInstruction(OpCodes.Ldloc_1, (object)null);
			}
			if (store.opcode == OpCodes.Stloc_2)
			{
				return new CodeInstruction(OpCodes.Ldloc_2, (object)null);
			}
			if (store.opcode == OpCodes.Stloc_3)
			{
				return new CodeInstruction(OpCodes.Ldloc_3, (object)null);
			}
			if (store.opcode == OpCodes.Stloc_S)
			{
				return new CodeInstruction(OpCodes.Ldloc_S, store.operand);
			}
			if (store.opcode == OpCodes.Stloc)
			{
				return new CodeInstruction(OpCodes.Ldloc, store.operand);
			}
			throw new ArgumentException($"Instruction '{store}' is not a stloc instruction.", "store");
		}

		/// <summary>
		///     <para xml:lang="en">Converts a local-load instruction to the corresponding local-store instruction.</para>
