		public static Func<CodeInstruction, bool> IsCall(MethodInfo? method)
		{
			return (CodeInstruction instruction) => IsCallTo(instruction, method);
		}

		/// <summary>
		///     <para xml:lang="en">Matches a call/callvirt instruction using a method predicate.</para>
		///     <para xml:lang="zh-CN">使用方法谓词匹配 call/callvirt 指令。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsCall(Func<MethodInfo, bool> predicate)
		{
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			return (CodeInstruction instruction) => IsAnyCallInstruction(instruction) && instruction.operand is MethodInfo arg && predicate(arg);
		}

		/// <summary>
		///     <para xml:lang="en">Matches a call/callvirt to a method declared on the supplied type with the supplied name.</para>
		///     <para xml:lang="zh-CN">匹配对指定类型上指定名称方法的 call/callvirt。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsCallTo(Type declaringType, string methodName)
		{
			ArgumentNullException.ThrowIfNull(declaringType, "declaringType");
			ArgumentException.ThrowIfNullOrWhiteSpace(methodName, "methodName");
			return IsCall((MethodInfo method) => method.DeclaringType == declaringType && string.Equals(method.Name, methodName, StringComparison.Ordinal));
		}

		/// <summary>
		///     <para xml:lang="en">Matches a call/callvirt to a method with the supplied name.</para>
		///     <para xml:lang="zh-CN">匹配对指定名称方法的 call/callvirt。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsCallTo(string methodName)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(methodName, "methodName");
			return IsCall((MethodInfo method) => string.Equals(method.Name, methodName, StringComparison.Ordinal));
		}

		/// <summary>
		///     <para xml:lang="en">Matches a call/callvirt whose return type is the supplied type.</para>
		///     <para xml:lang="zh-CN">匹配返回类型为指定类型的 call/callvirt。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsCallReturning(Type returnType)
		{
			ArgumentNullException.ThrowIfNull(returnType, "returnType");
			return IsCall((MethodInfo method) => method.ReturnType == returnType);
		}

		/// <summary>
		///     <para xml:lang="en">Matches a call/callvirt whose parameter types match the supplied sequence.</para>
		///     <para xml:lang="zh-CN">匹配参数类型序列等于指定序列的 call/callvirt。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsCallWithParameters(params Type[] parameterTypes)
		{
			ArgumentNullException.ThrowIfNull(parameterTypes, "parameterTypes");
			return IsCall((MethodInfo method) => (from parameter in method.GetParameters()
				select parameter.ParameterType).SequenceEqual(parameterTypes));
		}

		/// <summary>
		///     <para xml:lang="en">Matches any call/callvirt instruction.</para>
		///     <para xml:lang="zh-CN">匹配任意 call/callvirt 指令。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsAnyCall()
		{
			return (CodeInstruction instruction) => instruction.opcode == OpCodes.Call || instruction.opcode == OpCodes.Callvirt;
		}

		/// <summary>
		///     <para xml:lang="en">Matches a newobj instruction for the supplied constructor.</para>
		///     <para xml:lang="zh-CN">匹配指定构造函数的 newobj 指令。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsNewobj(ConstructorInfo? constructor = null)
		{
			return (CodeInstruction instruction) => instruction.opcode == OpCodes.Newobj && (constructor == null || object.Equals(instruction.operand, constructor));
		}

		/// <summary>
		///     <para xml:lang="en">Matches a field instruction.</para>
		///     <para xml:lang="zh-CN">匹配字段指令。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsField(OpCode opcode, FieldInfo? field = null)
		{
			return (CodeInstruction instruction) => instruction.opcode == opcode && (field == null || object.Equals(instruction.operand, field));
		}

		/// <summary>
		///     <para xml:lang="en">Matches an instance-field load instruction.</para>
		///     <para xml:lang="zh-CN">匹配实例字段读取指令。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsLdfld(FieldInfo? field = null)
		{
			return IsField(OpCodes.Ldfld, field);
		}

		/// <summary>
		///     <para xml:lang="en">Matches an instance-field store instruction.</para>
		///     <para xml:lang="zh-CN">匹配实例字段存储指令。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsStfld(FieldInfo? field = null)
		{
			return IsField(OpCodes.Stfld, field);
		}

		/// <summary>
		///     <para xml:lang="en">Matches a static-field load instruction.</para>
		///     <para xml:lang="zh-CN">匹配静态字段读取指令。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsLdsfld(FieldInfo? field = null)
		{
			return IsField(OpCodes.Ldsfld, field);
		}

		/// <summary>
		///     <para xml:lang="en">Matches any field access instruction for the supplied field.</para>
		///     <para xml:lang="zh-CN">匹配对指定字段的任意字段访问指令。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsFieldAccess(FieldInfo? field = null)
		{
			return (CodeInstruction instruction) => IsFieldAccessInstruction(instruction) && (field == null || object.Equals(instruction.operand, field));
		}

		/// <summary>
		///     <para xml:lang="en">Matches any field access instruction using a field predicate.</para>
		///     <para xml:lang="zh-CN">使用字段谓词匹配任意字段访问指令。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsFieldAccess(Func<FieldInfo, bool> predicate)
		{
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			return (CodeInstruction instruction) => IsFieldAccessInstruction(instruction) && instruction.operand is FieldInfo arg && predicate(arg);
		}

		/// <summary>
		///     <para xml:lang="en">Matches any field access instruction whose field type is the supplied type.</para>
		///     <para xml:lang="zh-CN">匹配字段类型为指定类型的任意字段访问指令。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsFieldOfType(Type fieldType)
		{
			ArgumentNullException.ThrowIfNull(fieldType, "fieldType");
			return IsFieldAccess((FieldInfo field) => field.FieldType == fieldType);
		}

		/// <summary>
		///     <para xml:lang="en">Matches any field access instruction for a named field on the supplied declaring type.</para>
		///     <para xml:lang="zh-CN">匹配指定类型上指定名称字段的任意字段访问指令。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsFieldNamed(Type declaringType, string fieldName)
		{
			ArgumentNullException.ThrowIfNull(declaringType, "declaringType");
			ArgumentException.ThrowIfNullOrWhiteSpace(fieldName, "fieldName");
			return IsFieldAccess((FieldInfo field) => field.DeclaringType == declaringType && string.Equals(field.Name, fieldName, StringComparison.Ordinal));
		}

		/// <summary>
		///     <para xml:lang="en">Matches a branch instruction.</para>
		///     <para xml:lang="zh-CN">匹配分支指令。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsBranch()
		{
			return (CodeInstruction instruction) =>
			{
				Label? label = default(Label?);
				return CodeInstructionExtensions.Branches(instruction, ref label);
			};
		}

		/// <summary>
		///     <para xml:lang="en">Matches a ret instruction.</para>
		///     <para xml:lang="zh-CN">匹配 ret 指令。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> IsRet()
		{
			return (CodeInstruction instruction) => instruction.opcode == OpCodes.Ret;
		}

		/// <summary>
		///     <para xml:lang="en">Returns true when the instruction calls the supplied method via call or callvirt.</para>
		///     <para xml:lang="zh-CN">当指令通过 call 或 callvirt 调用指定方法时返回 true。</para>
		/// </summary>
		public static bool IsCallTo(CodeInstruction instruction, MethodInfo? method)
		{
			if (method != null && (instruction.opcode == OpCodes.Call || instruction.opcode == OpCodes.Callvirt) && instruction.operand is MethodInfo methodInfo)
			{
				return methodInfo == method;
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Tries to read the target method from a call/callvirt instruction.</para>
		///     <para xml:lang="zh-CN">尝试从 call/callvirt 指令读取目标方法。</para>
		/// </summary>
		public static bool TryGetCalledMethod(CodeInstruction instruction, out MethodInfo method)
		{
			ArgumentNullException.ThrowIfNull(instruction, "instruction");
			if (IsAnyCallInstruction(instruction) && instruction.operand is MethodInfo methodInfo)
			{
				method = methodInfo;
				return true;
			}
			method = null;
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Returns true when the instruction calls the supplied generic method definition.</para>
		///     <para xml:lang="zh-CN">当指令调用指定泛型方法定义时返回 true。</para>
		/// </summary>
		public static bool IsCallToGenericDefinition(CodeInstruction instruction, MethodInfo? genericDefinition)
		{
			if (genericDefinition != null && genericDefinition.IsGenericMethodDefinition && (instruction.opcode == OpCodes.Call || instruction.opcode == OpCodes.Callvirt) && instruction.operand is MethodInfo { IsGenericMethod: not false } methodInfo)
			{
				return methodInfo.GetGenericMethodDefinition() == genericDefinition;
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns true when the instruction calls a method declared on <paramref name="declaringType" />
		///         with <paramref name="methodName" />.
		///     </para>
		///     <para xml:lang="zh-CN">当指令调用 <paramref name="declaringType" /> 上名为 <paramref name="methodName" /> 的方法时返回 true。</para>
		/// </summary>
		public static bool IsCallNamed(CodeInstruction instruction, Type declaringType, string methodName)
		{
			ArgumentNullException.ThrowIfNull(declaringType, "declaringType");
			ArgumentException.ThrowIfNullOrWhiteSpace(methodName, "methodName");
			if ((instruction.opcode == OpCodes.Call || instruction.opcode == OpCodes.Callvirt) && instruction.operand is MethodInfo methodInfo && methodInfo.DeclaringType == declaringType)
			{
				return string.Equals(methodInfo.Name, methodName, StringComparison.Ordinal);
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Returns true when the instruction loads the supplied 32-bit integer constant.</para>
		///     <para xml:lang="zh-CN">当指令加载指定 32 位整数常量时返回 true。</para>
		/// </summary>
		public static bool LoadsInt32(CodeInstruction instruction, int value)
		{
			if (TryGetInt32(instruction, out var value2))
			{
				return value2 == value;
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Reads a typed operand from an instruction.</para>
		///     <para xml:lang="zh-CN">从指令读取指定类型的操作数。</para>
		/// </summary>
		public static bool TryGetOperand<T>(CodeInstruction instruction, out T operand)
		{
			ArgumentNullException.ThrowIfNull(instruction, "instruction");
			if (instruction.operand is T val)
			{
				operand = val;
				return true;
			}
			operand = default(T);
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Returns true when the instruction operand equals the supplied operand.</para>
		///     <para xml:lang="zh-CN">当指令操作数等于指定操作数时返回 true。</para>
		/// </summary>
		public static bool OperandEquals(CodeInstruction instruction, object? operand)
		{
			ArgumentNullException.ThrowIfNull(instruction, "instruction");
			return object.Equals(instruction.operand, operand);
		}

		/// <summary>
		///     <para xml:lang="en">Returns true when a typed operand satisfies the supplied predicate.</para>
		///     <para xml:lang="zh-CN">当指定类型的操作数满足谓词时返回 true。</para>
		/// </summary>
		public static bool OperandMatches<T>(CodeInstruction instruction, Func<T, bool> predicate)
		{
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			if (TryGetOperand<T>(instruction, out var operand))
			{
				return predicate(operand);
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Matches instructions whose typed operand satisfies the supplied predicate.</para>
		///     <para xml:lang="zh-CN">匹配指定类型的操作数满足谓词的指令。</para>
		/// </summary>
		public static Func<CodeInstruction, bool> HasOperand<T>(Func<T, bool>? predicate = null)
		{
			return (CodeInstruction instruction) => TryGetOperand<T>(instruction, out var operand) && (predicate == null || predicate(operand));
		}

		/// <summary>
		///     <para xml:lang="en">Reads a local reference from a local-load instruction.</para>
		///     <para xml:lang="zh-CN">从本地变量读取指令读取本地变量引用。</para>
		/// </summary>
		public static bool TryGetLocalLoad(CodeInstruction instruction, out HarmonyIlLocalRef local)
		{
			if (!TryGetLocalLoadIndex(instruction, out var index))
			{
				local = default(HarmonyIlLocalRef);
				return false;
			}
			local = CreateLocalRef(index, instruction.operand);
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Reads a local reference from a local-store instruction.</para>
		///     <para xml:lang="zh-CN">从本地变量存储指令读取本地变量引用。</para>
		/// </summary>
		public static bool TryGetLocalStore(CodeInstruction instruction, out HarmonyIlLocalRef local)
		{
			if (!TryGetLocalStoreIndex(instruction, out var index))
			{
				local = default(HarmonyIlLocalRef);
				return false;
			}
			local = CreateLocalRef(index, instruction.operand);
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Reads a local reference from a local load or store instruction.</para>
		///     <para xml:lang="zh-CN">从本地变量读取或存储指令读取本地变量引用。</para>
		/// </summary>
		public static bool TryGetLocal(CodeInstruction instruction, out HarmonyIlLocalRef local)
		{
			if (!TryGetLocalLoad(instruction, out local))
			{
				return TryGetLocalStore(instruction, out local);
			}
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Reads the argument index from an argument-load instruction.</para>
		///     <para xml:lang="zh-CN">从参数读取指令中读取参数索引。</para>
		/// </summary>
		public static bool TryGetArgumentIndex(CodeInstruction instruction, out int index)
		{
			if (instruction.opcode == OpCodes.Ldarg_0)
			{
				index = 0;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldarg_1)
			{
				index = 1;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldarg_2)
			{
				index = 2;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldarg_3)
			{
				index = 3;
				return true;
			}
			if (instruction.opcode != OpCodes.Ldarg && instruction.opcode != OpCodes.Ldarg_S)
			{
				index = -1;
				return false;
			}
			return TryGetNumericIndex(instruction.operand, out index);
		}

		/// <summary>
		///     <para xml:lang="en">Reads the local index from a local-load instruction.</para>
		///     <para xml:lang="zh-CN">从本地变量读取指令中读取本地变量索引。</para>
		/// </summary>
		public static bool TryGetLocalLoadIndex(CodeInstruction instruction, out int index)
		{
			if (instruction.opcode == OpCodes.Ldloc_0)
			{
				index = 0;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldloc_1)
			{
				index = 1;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldloc_2)
			{
				index = 2;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldloc_3)
			{
				index = 3;
				return true;
			}
			if (instruction.opcode != OpCodes.Ldloc && instruction.opcode != OpCodes.Ldloc_S)
			{
				index = -1;
				return false;
			}
			return TryGetNumericIndex(instruction.operand, out index);
		}

		/// <summary>
		///     <para xml:lang="en">Reads the local index from a local-store instruction.</para>
		///     <para xml:lang="zh-CN">从本地变量存储指令中读取本地变量索引。</para>
		/// </summary>
		public static bool TryGetLocalStoreIndex(CodeInstruction instruction, out int index)
		{
			if (instruction.opcode == OpCodes.Stloc_0)
			{
				index = 0;
				return true;
			}
			if (instruction.opcode == OpCodes.Stloc_1)
			{
				index = 1;
				return true;
			}
			if (instruction.opcode == OpCodes.Stloc_2)
			{
				index = 2;
				return true;
			}
			if (instruction.opcode == OpCodes.Stloc_3)
			{
				index = 3;
				return true;
			}
			if (instruction.opcode != OpCodes.Stloc && instruction.opcode != OpCodes.Stloc_S)
			{
				index = -1;
				return false;
			}
			return TryGetNumericIndex(instruction.operand, out index);
		}

		/// <summary>
		///     <para xml:lang="en">Reads the int32 constant from an integer-load instruction.</para>
		///     <para xml:lang="zh-CN">从整数加载指令中读取 32 位整数常量。</para>
		/// </summary>
		public static bool TryGetInt32(CodeInstruction instruction, out int value)
		{
			if (instruction.opcode == OpCodes.Ldc_I4 && instruction.operand is int num)
			{
				value = num;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldc_I4_S && instruction.operand is sbyte b)
			{
				value = b;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldc_I4_M1)
			{
				value = -1;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldc_I4_0)
			{
				value = 0;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldc_I4_1)
			{
				value = 1;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldc_I4_2)
			{
				value = 2;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldc_I4_3)
			{
				value = 3;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldc_I4_4)
			{
				value = 4;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldc_I4_5)
			{
				value = 5;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldc_I4_6)
			{
				value = 6;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldc_I4_7)
			{
				value = 7;
				return true;
			}
			if (instruction.opcode == OpCodes.Ldc_I4_8)
			{
				value = 8;
				return true;
			}
			value = 0;
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Returns true when the instruction has Harmony labels or exception blocks.</para>
		///     <para xml:lang="zh-CN">当指令带有 Harmony 标签或异常块时返回 true。</para>
		/// </summary>
		public static bool HasMetadata(CodeInstruction instruction)
		{
			ArgumentNullException.ThrowIfNull(instruction, "instruction");
			if (instruction.labels.Count <= 0)
			{
				return instruction.blocks.Count > 0;
			}
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Moves labels and exception blocks from <paramref name="source" /> to the first replacement
		///         instruction.
		///     </para>
		///     <para xml:lang="zh-CN">将 <paramref name="source" /> 的标签和异常块转移到第一条替换指令上。</para>
		/// </summary>
		public static IReadOnlyList<CodeInstruction> MoveMetadataToFirst(CodeInstruction source, IReadOnlyList<CodeInstruction> replacement)
		{
			ArgumentNullException.ThrowIfNull(source, "source");
			ArgumentNullException.ThrowIfNull(replacement, "replacement");
			if (replacement.Count == 0)
			{
				return replacement;
			}
			CodeInstruction obj = replacement[0];
			obj.labels.AddRange(source.labels);
			obj.blocks.AddRange(source.blocks);
			source.labels.Clear();
			source.blocks.Clear();
			return replacement;
		}

		/// <summary>
		///     <para xml:lang="en">Clones every instruction in order.</para>
		///     <para xml:lang="zh-CN">按顺序克隆每条指令。</para>
		/// </summary>
		public static CodeInstruction[] CloneAll(IEnumerable<CodeInstruction> instructions)
		{
			ArgumentNullException.ThrowIfNull(instructions, "instructions");
			return instructions.Select((CodeInstruction instruction) => instruction.Clone()).ToArray();
		}

		private static bool TryGetNumericIndex(object? operand, out int index)
		{
			if (!(operand is int num))
			{
				if (!(operand is byte b))
				{
					if (!(operand is sbyte b2))
					{
						if (!(operand is short num2))
						{
							if (!(operand is ushort num3))
							{
								if (!(operand is LocalBuilder localBuilder))
								{
									if (!(operand is LocalVariableInfo localVariableInfo))
									{
										if (operand is ParameterInfo parameterInfo)
										{
											index = parameterInfo.Position;
											return true;
										}
										index = -1;
										return false;
									}
									index = localVariableInfo.LocalIndex;
									return true;
								}
								index = localBuilder.LocalIndex;
								return true;
							}
							index = num3;
							return true;
						}
						index = num2;
						return true;
					}
					index = b2;
					return true;
				}
				index = b;
				return true;
			}
			index = num;
			return true;
		}

		private static HarmonyIlLocalRef CreateLocalRef(int index, object? operand)
		{
			if (!(operand is LocalBuilder localBuilder))
			{
				if (operand is LocalVariableInfo localVariableInfo)
				{
					return new HarmonyIlLocalRef(index, null, localVariableInfo.LocalType);
				}
				return new HarmonyIlLocalRef(index);
			}
			return new HarmonyIlLocalRef(index, localBuilder, localBuilder.LocalType);
		}

		private static bool IsAnyCallInstruction(CodeInstruction instruction)
		{
			if (!(instruction.opcode == OpCodes.Call))
			{
				return instruction.opcode == OpCodes.Callvirt;
			}
			return true;
		}

		private static bool IsFieldAccessInstruction(CodeInstruction instruction)
		{
			if (!(instruction.opcode == OpCodes.Ldfld) && !(instruction.opcode == OpCodes.Ldflda) && !(instruction.opcode == OpCodes.Ldsfld) && !(instruction.opcode == OpCodes.Stfld))
			{
				return instruction.opcode == OpCodes.Stsfld;
			}
			return true;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Kind of a directed edge in a Harmony IL control-flow graph.</para>
	///     <para xml:lang="zh-CN">Harmony IL 控制流图中的有向边类型。</para>
	/// </summary>
	public enum HarmonyIlFlowEdgeKind
	{
		/// <summary>
		///     <para xml:lang="en">Sequential flow into the next basic block.</para>
		///     <para xml:lang="zh-CN">顺序进入下一个基本块。</para>
		/// </summary>
		FallThrough,
		/// <summary>
		///     <para xml:lang="en">Conditional or unconditional branch flow.</para>
		///     <para xml:lang="zh-CN">条件或无条件分支流。</para>
		/// </summary>
		Branch,
		/// <summary>
		///     <para xml:lang="en">One target of a switch instruction.</para>
		///     <para xml:lang="zh-CN">switch 指令的一个目标分支。</para>
		/// </summary>
		Switch,
		/// <summary>
		///     <para xml:lang="en">Flow leaving a protected exception region.</para>
		///     <para xml:lang="zh-CN">离开受保护异常区域的控制流。</para>
		/// </summary>
		Leave
	}
	/// <summary>
	///     <para xml:lang="en">A directed edge between two basic blocks.</para>
	///     <para xml:lang="zh-CN">两个基本块之间的有向边。</para>
	/// </summary>
	public sealed record HarmonyIlFlowEdge(int SourceBlockIndex, int TargetBlockIndex, HarmonyIlFlowEdgeKind Kind);
	/// <summary>
	///     <para xml:lang="en">One diagnostic produced while constructing a control-flow graph.</para>
	///     <para xml:lang="zh-CN">构建控制流图时产生的一条诊断。</para>
	/// </summary>
	public sealed record HarmonyIlControlFlowDiagnostic(int InstructionIndex, string Message);
	/// <summary>
	///     <para xml:lang="en">A contiguous basic block in a <see cref="T:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlControlFlowGraph" />.</para>
	///     <para xml:lang="zh-CN"><see cref="T:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlControlFlowGraph" /> 中连续的基本块。</para>
	/// </summary>
	public sealed class HarmonyIlBasicBlock
	{
		private readonly List<HarmonyIlFlowEdge> _incomingEdges = new List<HarmonyIlFlowEdge>();

		private readonly List<HarmonyIlFlowEdge> _outgoingEdges = new List<HarmonyIlFlowEdge>();

		/// <summary>
		///     <para xml:lang="en">Stable zero-based index of this block in its graph.</para>
		///     <para xml:lang="zh-CN">此基本块在所属图中的稳定零基索引。</para>
		/// </summary>
		public int Index { get; }

		/// <summary>
		///     <para xml:lang="en">Index of the first instruction in this block.</para>
		///     <para xml:lang="zh-CN">此基本块第一条指令的索引。</para>
		/// </summary>
		public int StartInstructionIndex { get; }

		/// <summary>
		///     <para xml:lang="en">Exclusive index immediately after the last instruction in this block.</para>
		///     <para xml:lang="zh-CN">此基本块最后一条指令之后的排他索引。</para>
		/// </summary>
		public int EndInstructionIndexExclusive { get; }

		/// <summary>
		///     <para xml:lang="en">Number of instructions in this block.</para>
		///     <para xml:lang="zh-CN">此基本块中的指令数量。</para>
		/// </summary>
		public int InstructionCount => EndInstructionIndexExclusive - StartInstructionIndex;

		/// <summary>
		///     <para xml:lang="en">Incoming control-flow edges.</para>
		///     <para xml:lang="zh-CN">传入此基本块的控制流边。</para>
		/// </summary>
		public IReadOnlyList<HarmonyIlFlowEdge> IncomingEdges => _incomingEdges;

		/// <summary>
		///     <para xml:lang="en">Outgoing control-flow edges.</para>
		///     <para xml:lang="zh-CN">从此基本块传出的控制流边。</para>
		/// </summary>
		public IReadOnlyList<HarmonyIlFlowEdge> OutgoingEdges => _outgoingEdges;

		internal HarmonyIlBasicBlock(int index, int startInstructionIndex, int endInstructionIndexExclusive)
		{
			Index = index;
			StartInstructionIndex = startInstructionIndex;
			EndInstructionIndexExclusive = endInstructionIndexExclusive;
		}

		internal void AddIncoming(HarmonyIlFlowEdge edge)
		{
			_incomingEdges.Add(edge);
		}

		internal void AddOutgoing(HarmonyIlFlowEdge edge)
		{
			_outgoingEdges.Add(edge);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Basic-block control-flow graph built from a <see cref="T:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlMethodBody" />.</para>
	///     <para xml:lang="zh-CN">从 <see cref="T:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlMethodBody" /> 构建的基本块控制流图。</para>
	/// </summary>
	public sealed class HarmonyIlControlFlowGraph
	{
		/// <summary>
		///     <para xml:lang="en">IL body represented by this graph.</para>
		///     <para xml:lang="zh-CN">此图所表示的 IL 方法体。</para>
		/// </summary>
		public HarmonyIlMethodBody MethodBody { get; }

		/// <summary>
		///     <para xml:lang="en">Basic blocks in instruction order.</para>
		///     <para xml:lang="zh-CN">按指令顺序排列的基本块。</para>
		/// </summary>
		public IReadOnlyList<HarmonyIlBasicBlock> Blocks { get; }

		/// <summary>
		///     <para xml:lang="en">Directed control-flow edges.</para>
		///     <para xml:lang="zh-CN">有向控制流边。</para>
		/// </summary>
		public IReadOnlyList<HarmonyIlFlowEdge> Edges { get; }

		/// <summary>
		///     <para xml:lang="en">Non-fatal construction diagnostics.</para>
		///     <para xml:lang="zh-CN">构建过程中产生的非致命诊断。</para>
		/// </summary>
		public IReadOnlyList<HarmonyIlControlFlowDiagnostic> Diagnostics { get; }

		/// <summary>
		///     <para xml:lang="en">Basic-block index for every instruction index.</para>
		///     <para xml:lang="zh-CN">每个指令索引对应的基本块索引。</para>
		/// </summary>
		public IReadOnlyList<int> InstructionBlockIndexes { get; }

		/// <summary>
		///     <para xml:lang="en">True when all branch targets were resolved.</para>
		///     <para xml:lang="zh-CN">所有分支目标均已解析时为 true。</para>
		/// </summary>
		public bool IsComplete => Diagnostics.Count == 0;

		private HarmonyIlControlFlowGraph(HarmonyIlMethodBody methodBody, IReadOnlyList<HarmonyIlBasicBlock> blocks, IReadOnlyList<HarmonyIlFlowEdge> edges, IReadOnlyList<HarmonyIlControlFlowDiagnostic> diagnostics, IReadOnlyList<int> instructionBlockIndexes)
		{
			MethodBody = methodBody;
			Blocks = blocks;
			Edges = edges;
			Diagnostics = diagnostics;
			InstructionBlockIndexes = instructionBlockIndexes;
		}

		/// <summary>
		///     <para xml:lang="en">Builds a basic-block control-flow graph from original Harmony instructions.</para>
		///     <para xml:lang="zh-CN">从原始 Harmony 指令构建基本块控制流图。</para>
		/// </summary>
		public static HarmonyIlControlFlowGraph Build(HarmonyIlMethodBody methodBody)
		{
			ArgumentNullException.ThrowIfNull(methodBody, "methodBody");
			IReadOnlyList<CodeInstruction> code = methodBody.Instructions;
			if (code.Count == 0)
			{
				return new HarmonyIlControlFlowGraph(methodBody, Array.Empty<HarmonyIlBasicBlock>(), Array.Empty<HarmonyIlFlowEdge>(), Array.Empty<HarmonyIlControlFlowDiagnostic>(), Array.Empty<int>());
			}
			List<HarmonyIlControlFlowDiagnostic> diagnostics = new List<HarmonyIlControlFlowDiagnostic>();
			Dictionary<Label, int> labelTargets = BuildLabelTargets(code);
			SortedSet<int> sortedSet = new SortedSet<int> { 0 };
			for (int i = 0; i < code.Count; i++)
			{
				AddExceptionRegionLeaders(code, i, sortedSet);
				AddBranchTargetLeaders(code[i], i, labelTargets, sortedSet, diagnostics);
				if (EndsBasicBlock(code[i]) && i + 1 < code.Count)
				{
					sortedSet.Add(i + 1);
				}
			}
			int[] array = sortedSet.Where((int index) => index >= 0 && index < code.Count).ToArray();
			List<HarmonyIlBasicBlock> list = new List<HarmonyIlBasicBlock>(array.Length);
			int[] array2 = new int[code.Count];
			for (int num = 0; num < array.Length; num++)
			{
				int num2 = array[num];
				int num3 = ((num + 1 < array.Length) ? array[num + 1] : code.Count);
				HarmonyIlBasicBlock item = new HarmonyIlBasicBlock(num, num2, num3);
				list.Add(item);
				for (int num4 = num2; num4 < num3; num4++)
				{
					array2[num4] = num;
				}
			}
			List<HarmonyIlFlowEdge> edges = new List<HarmonyIlFlowEdge>();
			HashSet<HarmonyIlFlowEdge> seenEdges = new HashSet<HarmonyIlFlowEdge>();
			foreach (HarmonyIlBasicBlock item2 in list)
			{
				int num5 = item2.EndInstructionIndexExclusive - 1;
				AddTerminatorEdges(code[num5], num5, item2, list, labelTargets, array2, edges, seenEdges, diagnostics);
			}
			return new HarmonyIlControlFlowGraph(methodBody, list, edges, diagnostics, array2);
		}

		private static Dictionary<Label, int> BuildLabelTargets(IReadOnlyList<CodeInstruction> code)
		{
			Dictionary<Label, int> dictionary = new Dictionary<Label, int>();
			for (int i = 0; i < code.Count; i++)
			{
				foreach (Label label in code[i].labels)
				{
					dictionary[label] = i;
				}
			}
			return dictionary;
		}

		private static void AddExceptionRegionLeaders(IReadOnlyList<CodeInstruction> code, int instructionIndex, ISet<int> leaders)
		{
			if (code[instructionIndex].blocks.Count != 0)
			{
				leaders.Add(instructionIndex);
				if (instructionIndex + 1 < code.Count && code[instructionIndex].blocks.Any(delegate(ExceptionBlock block)
				{
					//IL_0001: Unknown result type (might be due to invalid IL or missing references)
					//IL_0007: Invalid comparison between Unknown and I4
					return (int)block.blockType == 5;
				}))
				{
					leaders.Add(instructionIndex + 1);
				}
			}
		}

		private static void AddBranchTargetLeaders(CodeInstruction instruction, int instructionIndex, IReadOnlyDictionary<Label, int> labelTargets, ISet<int> leaders, ICollection<HarmonyIlControlFlowDiagnostic> diagnostics)
		{
			if (instruction.opcode.OperandType == OperandType.InlineSwitch)
			{
				if (!(instruction.operand is Label[] array))
				{
					diagnostics.Add(new HarmonyIlControlFlowDiagnostic(instructionIndex, "Switch operand has unsupported type " + (instruction.operand?.GetType().FullName ?? "<null>") + "."));
					return;
				}
				Label[] array2 = array;
				for (int i = 0; i < array2.Length; i++)
				{
					AddLabelTarget(array2[i], instructionIndex, labelTargets, leaders, diagnostics);
				}
				return;
			}
			OperandType operandType = instruction.opcode.OperandType;
			if ((operandType == OperandType.InlineBrTarget || operandType == OperandType.ShortInlineBrTarget) ? true : false)
			{
				if (instruction.operand is Label label)
				{
					AddLabelTarget(label, instructionIndex, labelTargets, leaders, diagnostics);
				}
				else
				{
					diagnostics.Add(new HarmonyIlControlFlowDiagnostic(instructionIndex, "Branch operand has unsupported type " + (instruction.operand?.GetType().FullName ?? "<null>") + "."));
				}
			}
		}

		private static void AddLabelTarget(Label label, int instructionIndex, IReadOnlyDictionary<Label, int> labelTargets, ISet<int> leaders, ICollection<HarmonyIlControlFlowDiagnostic> diagnostics)
		{
			if (labelTargets.TryGetValue(label, out var value))
			{
				leaders.Add(value);
			}
			else
			{
				diagnostics.Add(new HarmonyIlControlFlowDiagnostic(instructionIndex, "Branch target label was not found in the instruction list."));
			}
		}

		private static bool EndsBasicBlock(CodeInstruction instruction)
		{
			FlowControl flowControl = instruction.opcode.FlowControl;
			if (flowControl == FlowControl.Branch || flowControl == FlowControl.Cond_Branch || (uint)(flowControl - 7) <= 1u)
			{
				return true;
			}
			return false;
		}

		private static void AddTerminatorEdges(CodeInstruction terminator, int terminatorIndex, HarmonyIlBasicBlock source, IReadOnlyList<HarmonyIlBasicBlock> blocks, IReadOnlyDictionary<Label, int> labelTargets, IReadOnlyList<int> instructionBlockIndexes, ICollection<HarmonyIlFlowEdge> edges, ISet<HarmonyIlFlowEdge> seenEdges, ICollection<HarmonyIlControlFlowDiagnostic> diagnostics)
		{
			switch (terminator.opcode.FlowControl)
			{
			case FlowControl.Cond_Branch:
			{
				HarmonyIlFlowEdgeKind kind2 = ((!(terminator.opcode == OpCodes.Switch)) ? HarmonyIlFlowEdgeKind.Branch : HarmonyIlFlowEdgeKind.Switch);
				AddBranchEdges(terminator, terminatorIndex, source, kind2, blocks, labelTargets, instructionBlockIndexes, edges, seenEdges, diagnostics);
				AddFallThroughEdge(source, blocks, edges, seenEdges);
				break;
			}
			case FlowControl.Branch:
			{
				HarmonyIlFlowEdgeKind kind = ((!(terminator.opcode == OpCodes.Leave) && !(terminator.opcode == OpCodes.Leave_S)) ? HarmonyIlFlowEdgeKind.Branch : HarmonyIlFlowEdgeKind.Leave);
				AddBranchEdges(terminator, terminatorIndex, source, kind, blocks, labelTargets, instructionBlockIndexes, edges, seenEdges, diagnostics);
				break;
			}
			case FlowControl.Return:
			case FlowControl.Throw:
				break;
			default:
				AddFallThroughEdge(source, blocks, edges, seenEdges);
				break;
			}
		}

		private static void AddBranchEdges(CodeInstruction instruction, int instructionIndex, HarmonyIlBasicBlock source, HarmonyIlFlowEdgeKind kind, IReadOnlyList<HarmonyIlBasicBlock> blocks, IReadOnlyDictionary<Label, int> labelTargets, IReadOnlyList<int> instructionBlockIndexes, ICollection<HarmonyIlFlowEdge> edges, ISet<HarmonyIlFlowEdge> seenEdges, ICollection<HarmonyIlControlFlowDiagnostic> diagnostics)
		{
			object operand = instruction.operand;
			Label[] array = ((operand is Label label) ? new Label[1] { label } : ((!(operand is Label[] array2)) ? Array.Empty<Label>() : array2));
			bool flag = false;
			foreach (Label item in (IEnumerable<Label>)array)
			{
				flag = true;
				if (!labelTargets.TryGetValue(item, out var value))
				{
					diagnostics.Add(new HarmonyIlControlFlowDiagnostic(instructionIndex, "Branch target label was not found in the instruction list."));
					continue;
				}
				int index = instructionBlockIndexes[value];
				AddEdge(source, blocks[index], kind, edges, seenEdges);
			}
			if (!flag && instruction.opcode != OpCodes.Jmp)
			{
				diagnostics.Add(new HarmonyIlControlFlowDiagnostic(instructionIndex, $"No supported target was found for branch opcode {instruction.opcode}."));
			}
		}

		private static void AddFallThroughEdge(HarmonyIlBasicBlock source, IReadOnlyList<HarmonyIlBasicBlock> blocks, ICollection<HarmonyIlFlowEdge> edges, ISet<HarmonyIlFlowEdge> seenEdges)
		{
			if (source.Index + 1 < blocks.Count)
			{
				AddEdge(source, blocks[source.Index + 1], HarmonyIlFlowEdgeKind.FallThrough, edges, seenEdges);
			}
		}

		private static void AddEdge(HarmonyIlBasicBlock source, HarmonyIlBasicBlock target, HarmonyIlFlowEdgeKind kind, ICollection<HarmonyIlFlowEdge> edges, ISet<HarmonyIlFlowEdge> seenEdges)
		{
			HarmonyIlFlowEdge harmonyIlFlowEdge = new HarmonyIlFlowEdge(source.Index, target.Index, kind);
			if (seenEdges.Add(harmonyIlFlowEdge))
			{
				edges.Add(harmonyIlFlowEdge);
				source.AddOutgoing(harmonyIlFlowEdge);
				target.AddIncoming(harmonyIlFlowEdge);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Named terminal method predicate used by <see cref="T:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlEffectAnalyzer" />.</para>
	///     <para xml:lang="zh-CN"><see cref="T:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlEffectAnalyzer" /> 使用的具名终点方法谓词。</para>
	/// </summary>
	public sealed record HarmonyIlEffectSink(string Id, Func<MethodInfo, bool> IsMatch)
	{
		/// <summary>
		///     <para xml:lang="en">Creates a sink that matches one exact method.</para>
		///     <para xml:lang="zh-CN">创建匹配一个确切方法的效果终点。</para>
		/// </summary>
		public static HarmonyIlEffectSink ForMethod(string id, MethodInfo method)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentNullException.ThrowIfNull(method, "method");
			return new HarmonyIlEffectSink(id, (MethodInfo candidate) => candidate == method);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Limits and traversal policy for an IL effect analysis.</para>
	///     <para xml:lang="zh-CN">IL 效果分析的限制与遍历策略。</para>
	/// </summary>
	public sealed record HarmonyIlEffectAnalysisOptions
	{
		/// <summary>
		///     <para xml:lang="en">Maximum number of traversed calls from a root.</para>
		///     <para xml:lang="zh-CN">从根方法开始允许下钻的最大调用层数。</para>
		/// </summary>
		public int MaxDepth { get; init; } = 16;

		/// <summary>
		///     <para xml:lang="en">Maximum number of distinct logical methods inspected.</para>
		///     <para xml:lang="zh-CN">允许检查的最大不同逻辑方法数量。</para>
		/// </summary>
		public int MaxMethods { get; init; } = 4096;

		/// <summary>
		///     <para xml:lang="en">Resolve async logical methods to compiler-generated <c>MoveNext</c> bodies.</para>
		///     <para xml:lang="zh-CN">将异步逻辑方法解析到编译器生成的 <c>MoveNext</c> 方法体。</para>
		/// </summary>
		public bool ResolveAsync { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">Selects non-sink calls whose bodies may be inspected. Null keeps analysis direct-call-only.</para>
		///     <para xml:lang="zh-CN">选择允许继续检查方法体的非终点调用；为 null 时仅分析直接调用。</para>
		/// </summary>
		public Func<MethodInfo, bool>? ShouldTraverse { get; init; }
	}
	/// <summary>
	///     <para xml:lang="en">Severity of an IL effect-analysis diagnostic.</para>
	///     <para xml:lang="zh-CN">IL 效果分析诊断的严重程度。</para>
	/// </summary>
	public enum HarmonyIlEffectDiagnosticSeverity
	{
		/// <summary>
		///     <para xml:lang="en">Informational analysis detail.</para>
		///     <para xml:lang="zh-CN">信息性分析详情。</para>
		/// </summary>
		Information,
		/// <summary>
		///     <para xml:lang="en">Recoverable condition that may reduce completeness.</para>
		///     <para xml:lang="zh-CN">可能降低完整性的可恢复状况。</para>
		/// </summary>
		Warning,
		/// <summary>
		///     <para xml:lang="en">Condition that prevents complete analysis.</para>
		///     <para xml:lang="zh-CN">阻止完整分析的错误状况。</para>
		/// </summary>
		Error
	}
	/// <summary>
	///     <para xml:lang="en">One diagnostic emitted by <see cref="T:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlEffectAnalyzer" />.</para>
	///     <para xml:lang="zh-CN"><see cref="T:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlEffectAnalyzer" /> 产生的一条诊断。</para>
	/// </summary>
	public sealed record HarmonyIlEffectDiagnostic(HarmonyIlEffectDiagnosticSeverity Severity, MethodBase? Method, string Message);
	/// <summary>
	///     <para xml:lang="en">A call site that directly reaches a sink or another effect-relevant method.</para>
	///     <para xml:lang="zh-CN">直接到达效果终点或另一个效果相关方法的调用点。</para>
	/// </summary>
	public sealed record HarmonyIlEffectCallSite(int InstructionIndex, MethodInfo CalledMethod, string? SinkId, bool ReachesRelevantMethod)
	{
		/// <summary>
		///     <para xml:lang="en">True when this call directly matches a configured sink.</para>
		///     <para xml:lang="zh-CN">此调用直接匹配已配置效果终点时为 true。</para>
		/// </summary>
		public bool IsDirectSink => SinkId != null;
	}
	/// <summary>
	///     <para xml:lang="en">Conservative control-flow slice for one effect-relevant logical method.</para>
	///     <para xml:lang="zh-CN">一个效果相关逻辑方法的保守控制流切片。</para>
	/// </summary>
	public sealed class HarmonyIlEffectMethodSlice
	{
		/// <summary>
		///     <para xml:lang="en">Logical method represented by this slice.</para>
		///     <para xml:lang="zh-CN">此切片所表示的逻辑方法。</para>
		/// </summary>
		public MethodBase Method { get; }

		/// <summary>
		///     <para xml:lang="en">Resolved original IL body.</para>
		///     <para xml:lang="zh-CN">解析后的原始 IL 方法体。</para>
		/// </summary>
		public HarmonyIlMethodBody Body { get; }

		/// <summary>
		///     <para xml:lang="en">Full basic-block graph of <see cref="P:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlEffectMethodSlice.Body" />.</para>
		///     <para xml:lang="zh-CN"><see cref="P:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlEffectMethodSlice.Body" /> 的完整基本块图。</para>
		/// </summary>
		public HarmonyIlControlFlowGraph ControlFlow { get; }

		/// <summary>
		///     <para xml:lang="en">Effect-relevant calls in instruction order.</para>
		///     <para xml:lang="zh-CN">按指令顺序排列的效果相关调用。</para>
		/// </summary>
		public IReadOnlyList<HarmonyIlEffectCallSite> EffectCallSites { get; }

		/// <summary>
		///     <para xml:lang="en">Blocks that can reach an effect call through normal control flow.</para>
		///     <para xml:lang="zh-CN">可通过普通控制流到达效果调用的基本块。</para>
		/// </summary>
		public IReadOnlySet<int> RetainedBlockIndexes { get; }

		internal HarmonyIlEffectMethodSlice(MethodBase method, HarmonyIlMethodBody body, HarmonyIlControlFlowGraph controlFlow, IReadOnlyList<HarmonyIlEffectCallSite> effectCallSites, IReadOnlySet<int> retainedBlockIndexes)
		{
			Method = method;
			Body = body;
			ControlFlow = controlFlow;
			EffectCallSites = effectCallSites;
			RetainedBlockIndexes = retainedBlockIndexes;
		}

		/// <summary>
		///     <para xml:lang="en">Returns true when an instruction belongs to a retained block.</para>
		///     <para xml:lang="zh-CN">指令属于保留基本块时返回 true。</para>
		/// </summary>
		public bool RetainsInstruction(int instructionIndex)
		{
			ArgumentOutOfRangeException.ThrowIfNegative(instructionIndex, "instructionIndex");
			if (instructionIndex >= ControlFlow.InstructionBlockIndexes.Count)
			{
				throw new ArgumentOutOfRangeException("instructionIndex");
			}
			return RetainedBlockIndexes.Contains(ControlFlow.InstructionBlockIndexes[instructionIndex]);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Result of an interprocedural effect reachability and control-flow slicing pass.</para>
	///     <para xml:lang="zh-CN">跨方法效果可达性与控制流切片分析结果。</para>
	/// </summary>
	public sealed class HarmonyIlEffectAnalysisResult
	{
		/// <summary>
		///     <para xml:lang="en">Logical root methods supplied to the analysis.</para>
		///     <para xml:lang="zh-CN">提供给分析器的逻辑根方法。</para>
		/// </summary>
		public IReadOnlyList<MethodBase> Roots { get; }

		/// <summary>
		///     <para xml:lang="en">Effect-relevant method slices keyed by logical method.</para>
		///     <para xml:lang="zh-CN">以逻辑方法为键的效果相关方法切片。</para>
		/// </summary>
		public IReadOnlyDictionary<MethodBase, HarmonyIlEffectMethodSlice> Slices { get; }

		/// <summary>
		///     <para xml:lang="en">Analysis diagnostics.</para>
		///     <para xml:lang="zh-CN">分析诊断。</para>
		/// </summary>
		public IReadOnlyList<HarmonyIlEffectDiagnostic> Diagnostics { get; }

		/// <summary>
		///     <para xml:lang="en">True when analysis completed without error diagnostics or incomplete control-flow graphs.</para>
		///     <para xml:lang="zh-CN">分析未产生错误诊断且所有控制流图完整时为 true。</para>
		/// </summary>
		public bool IsComplete
		{
			get
			{
				if (Diagnostics.All((HarmonyIlEffectDiagnostic diagnostic) => diagnostic.Severity != HarmonyIlEffectDiagnosticSeverity.Error))
				{
					return Slices.Values.All((HarmonyIlEffectMethodSlice slice) => slice.ControlFlow.IsComplete);
				}
				return false;
			}
		}

		internal HarmonyIlEffectAnalysisResult(IReadOnlyList<MethodBase> roots, IReadOnlyDictionary<MethodBase, HarmonyIlEffectMethodSlice> slices, IReadOnlyList<HarmonyIlEffectDiagnostic> diagnostics)
		{
			Roots = roots;
			Slices = slices;
			Diagnostics = diagnostics;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Discovers calls that can reach configured effect sinks and creates conservative per-method
	///         control slices.
	///     </para>
	///     <para xml:lang="zh-CN">发现可到达已配置效果终点的调用，并为每个相关方法创建保守控制切片。</para>
	/// </summary>
	public static class HarmonyIlEffectAnalyzer
	{
		private sealed record MethodNode(MethodBase Method, HarmonyIlMethodBody Body, IReadOnlyList<DiscoveredCall> Calls);

		private sealed record DiscoveredCall(int InstructionIndex, MethodInfo CalledMethod, string? SinkId);

		/// <summary>
		///     <para xml:lang="en">Analyzes logical root methods against named effect sinks.</para>
		///     <para xml:lang="zh-CN">按具名效果终点分析逻辑根方法。</para>
		/// </summary>
		public static HarmonyIlEffectAnalysisResult Analyze(IEnumerable<MethodBase> roots, IEnumerable<HarmonyIlEffectSink> sinks, HarmonyIlEffectAnalysisOptions? options = null)
		{
			ArgumentNullException.ThrowIfNull(roots, "roots");
			ArgumentNullException.ThrowIfNull(sinks, "sinks");
			MethodBase[] roots2 = roots.Distinct().ToArray();
			HarmonyIlEffectSink[] array = sinks.ToArray();
			if (array.Any((HarmonyIlEffectSink sink) => string.IsNullOrWhiteSpace(sink.Id) || sink.IsMatch == null))
			{
				throw new ArgumentException("Every effect sink must have an id and a predicate.", "sinks");
			}
			if (array.Select((HarmonyIlEffectSink sink) => sink.Id).Distinct<string>(StringComparer.Ordinal).Count() != array.Length)
			{
				throw new ArgumentException("Effect sink ids must be unique.", "sinks");
			}
			if ((object)options == null)
			{
				options = new HarmonyIlEffectAnalysisOptions();
			}
			ArgumentOutOfRangeException.ThrowIfNegative(options.MaxDepth, "options.MaxDepth");
			ArgumentOutOfRangeException.ThrowIfLessThan(options.MaxMethods, 1, "options.MaxMethods");
			List<HarmonyIlEffectDiagnostic> diagnostics = new List<HarmonyIlEffectDiagnostic>();
			Dictionary<MethodBase, MethodNode> nodes = DiscoverMethods(roots2, array, options, diagnostics);
			HashSet<MethodBase> relevantMethods = FindRelevantMethods(nodes);
			IReadOnlyDictionary<MethodBase, HarmonyIlEffectMethodSlice> slices = BuildSlices(nodes, relevantMethods, diagnostics);
			return new HarmonyIlEffectAnalysisResult(roots2, slices, diagnostics);
		}

		private static Dictionary<MethodBase, MethodNode> DiscoverMethods(IReadOnlyList<MethodBase> roots, IReadOnlyList<HarmonyIlEffectSink> sinks, HarmonyIlEffectAnalysisOptions options, ICollection<HarmonyIlEffectDiagnostic> diagnostics)
		{
			Dictionary<MethodBase, MethodNode> dictionary = new Dictionary<MethodBase, MethodNode>();
			Queue<(MethodBase, int)> queue = new Queue<(MethodBase, int)>(roots.Select((MethodBase method) => (method: method, 0)));
			HashSet<MethodBase> hashSet = roots.ToHashSet();
			(MethodBase, int) result;
			while (queue.TryDequeue(out result))
			{
				if (dictionary.Count >= options.MaxMethods)
				{
					diagnostics.Add(new HarmonyIlEffectDiagnostic(HarmonyIlEffectDiagnosticSeverity.Error, result.Item1, $"Method budget {options.MaxMethods} was exceeded."));
					break;
				}
				HarmonyIlMethodBody originalIl;
				try
				{
					originalIl = result.Item1.GetOriginalIl(options.ResolveAsync);
				}
				catch (Exception ex)
				{
					diagnostics.Add(new HarmonyIlEffectDiagnostic(HarmonyIlEffectDiagnosticSeverity.Error, result.Item1, "Could not read original IL: " + ex.Message));
					continue;
				}
				IReadOnlyList<DiscoveredCall> readOnlyList = ReadCalls(originalIl, sinks);
				dictionary[result.Item1] = new MethodNode(result.Item1, originalIl, readOnlyList);
				if (result.Item2 >= options.MaxDepth || options.ShouldTraverse == null)
				{
					continue;
				}
				foreach (DiscoveredCall item in readOnlyList)
				{
					if (item.SinkId == null && options.ShouldTraverse(item.CalledMethod) && hashSet.Add(item.CalledMethod))
					{
						queue.Enqueue((item.CalledMethod, result.Item2 + 1));
					}
				}
			}
			return dictionary;
		}

		private static IReadOnlyList<DiscoveredCall> ReadCalls(HarmonyIlMethodBody body, IReadOnlyList<HarmonyIlEffectSink> sinks)
		{
			List<DiscoveredCall> list = new List<DiscoveredCall>();
			for (int i = 0; i < body.Instructions.Count; i++)
			{
				if (HarmonyIl.TryGetCalledMethod(body.Instructions[i], out MethodInfo calledMethod))
				{
					string sinkId = sinks.FirstOrDefault((HarmonyIlEffectSink sink) => sink.IsMatch(calledMethod))?.Id;
					list.Add(new DiscoveredCall(i, calledMethod, sinkId));
				}
			}
			return list;
		}

		private static HashSet<MethodBase> FindRelevantMethods(IReadOnlyDictionary<MethodBase, MethodNode> nodes)
		{
			HashSet<MethodBase> relevant = (from node in nodes.Values
				where node.Calls.Any((DiscoveredCall call) => call.SinkId != null)
				select node.Method).ToHashSet();
			bool flag = true;
			while (flag)
			{
				flag = false;
				foreach (MethodNode value in nodes.Values)
				{
					if (!relevant.Contains(value.Method) && value.Calls.Any((DiscoveredCall call) => relevant.Contains(call.CalledMethod)))
					{
						relevant.Add(value.Method);
						flag = true;
					}
				}
			}
			return relevant;
		}

		private static IReadOnlyDictionary<MethodBase, HarmonyIlEffectMethodSlice> BuildSlices(IReadOnlyDictionary<MethodBase, MethodNode> nodes, IReadOnlySet<MethodBase> relevantMethods, ICollection<HarmonyIlEffectDiagnostic> diagnostics)
		{
			Dictionary<MethodBase, HarmonyIlEffectMethodSlice> dictionary = new Dictionary<MethodBase, HarmonyIlEffectMethodSlice>();
			foreach (MethodBase relevantMethod in relevantMethods)
			{
				MethodNode methodNode = nodes[relevantMethod];
				HarmonyIlControlFlowGraph harmonyIlControlFlowGraph = HarmonyIlControlFlowGraph.Build(methodNode.Body);
				foreach (HarmonyIlControlFlowDiagnostic diagnostic in harmonyIlControlFlowGraph.Diagnostics)
				{
					diagnostics.Add(new HarmonyIlEffectDiagnostic(HarmonyIlEffectDiagnosticSeverity.Warning, relevantMethod, $"IL {diagnostic.InstructionIndex}: {diagnostic.Message}"));
				}
				HarmonyIlEffectCallSite[] array = (from call in methodNode.Calls
					where call.SinkId != null || relevantMethods.Contains(call.CalledMethod)
					select new HarmonyIlEffectCallSite(call.InstructionIndex, call.CalledMethod, call.SinkId, relevantMethods.Contains(call.CalledMethod))).ToArray();
				IReadOnlySet<int> retainedBlockIndexes = FindPredecessorClosure(harmonyIlControlFlowGraph, array);
				dictionary[relevantMethod] = new HarmonyIlEffectMethodSlice(relevantMethod, methodNode.Body, harmonyIlControlFlowGraph, array, retainedBlockIndexes);
			}
			return dictionary;
		}

		private static IReadOnlySet<int> FindPredecessorClosure(HarmonyIlControlFlowGraph graph, IReadOnlyList<HarmonyIlEffectCallSite> effectCalls)
		{
			HashSet<int> hashSet = new HashSet<int>();
			Queue<int> queue = new Queue<int>();
			foreach (HarmonyIlEffectCallSite effectCall in effectCalls)
			{
				int item = graph.InstructionBlockIndexes[effectCall.InstructionIndex];
				if (hashSet.Add(item))
				{
					queue.Enqueue(item);
				}
			}
			int result;
			while (queue.TryDequeue(out result))
			{
				foreach (HarmonyIlFlowEdge incomingEdge in graph.Blocks[result].IncomingEdges)
				{
					if (hashSet.Add(incomingEdge.SourceBlockIndex))
					{
						queue.Enqueue(incomingEdge.SourceBlockIndex);
					}
				}
			}
			return hashSet;
		}
	}
	/// <summary>
	///     <para xml:lang="en">A snapshot of the original IL body selected for a logical method.</para>
	///     <para xml:lang="zh-CN">为逻辑方法选定的原始 IL 方法体快照。</para>
	/// </summary>
	public sealed class HarmonyIlMethodBody
	{
		/// <summary>
		///     <para xml:lang="en">Logical method requested by the caller.</para>
		///     <para xml:lang="zh-CN">调用方请求检查的逻辑方法。</para>
		/// </summary>
		public MethodBase SourceMethod { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Method that owns <see cref="P:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlMethodBody.Instructions" />. For a resolved async method this is its generated
		///         <c>MoveNext</c> method.
		///     </para>
		///     <para xml:lang="zh-CN">拥有 <see cref="P:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlMethodBody.Instructions" /> 的方法。解析异步方法时，这是编译器生成的 <c>MoveNext</c> 方法。</para>
		/// </summary>
		public MethodBase BodyMethod { get; }

		/// <summary>
		///     <para xml:lang="en">True when the logical method was resolved to an async state-machine body.</para>
		///     <para xml:lang="zh-CN">逻辑方法已解析为异步状态机方法体时为 true。</para>
		/// </summary>
		public bool IsAsyncStateMachineBody => SourceMethod != BodyMethod;

		/// <summary>
		///     <para xml:lang="en">Original Harmony instructions for <see cref="P:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlMethodBody.BodyMethod" />.</para>
		///     <para xml:lang="zh-CN"><see cref="P:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlMethodBody.BodyMethod" /> 的 Harmony 原始指令。</para>
		/// </summary>
		public IReadOnlyList<CodeInstruction> Instructions { get; }

		/// <summary>
		///     <para xml:lang="en">Call/callvirt targets in instruction order. Repeated call sites are preserved.</para>
		///     <para xml:lang="zh-CN">按指令顺序排列的 call/callvirt 目标；重复调用点会被保留。</para>
		/// </summary>
		public IReadOnlyList<MethodInfo> CalledMethods { get; }

		internal HarmonyIlMethodBody(MethodBase sourceMethod, MethodBase bodyMethod, IReadOnlyList<CodeInstruction> instructions)
		{
			SourceMethod = sourceMethod;
			BodyMethod = bodyMethod;
			Instructions = instructions;
			List<MethodInfo> list = new List<MethodInfo>();
			list.AddRange((from instruction in instructions
				select (!HarmonyIl.TryGetCalledMethod(instruction, out MethodInfo method)) ? null : method into method
				where method != null
				select method).Cast<MethodInfo>());
			CalledMethods = new <>z__ReadOnlyList<MethodInfo>(list);
		}

		/// <summary>
		///     <para xml:lang="en">Creates an isolated mutable rewriter over cloned instructions.</para>
		///     <para xml:lang="zh-CN">基于克隆指令创建独立的可变改写器。</para>
		/// </summary>
		public HarmonyIlRewriter CreateRewriter()
		{
			return HarmonyIlRewriter.From(HarmonyIl.CloneAll(Instructions), BodyMethod);
		}

		/// <summary>
		///     <para xml:lang="en">Returns true when any call/callvirt target satisfies <paramref name="predicate" />.</para>
		///     <para xml:lang="zh-CN">任一 call/callvirt 目标满足 <paramref name="predicate" /> 时返回 true。</para>
		/// </summary>
		public bool HasCall(Func<MethodInfo, bool> predicate)
		{
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			return CalledMethods.Any(predicate);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         A shortest call path found by
	///         <see cref="M:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlInspectionExtensions.FindOriginalIlCallPath(System.Reflection.MethodBase,System.Func{System.Reflection.MethodInfo,System.Boolean},System.Func{System.Reflection.MethodInfo,System.Boolean},System.Int32,System.Boolean)" />.
	///     </para>
	///     <para xml:lang="zh-CN"><see cref="M:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlInspectionExtensions.FindOriginalIlCallPath(System.Reflection.MethodBase,System.Func{System.Reflection.MethodInfo,System.Boolean},System.Func{System.Reflection.MethodInfo,System.Boolean},System.Int32,System.Boolean)" /> 找到的最短调用路径。</para>
	/// </summary>
	public sealed class HarmonyIlCallPath
	{
		/// <summary>
		///     <para xml:lang="en">Logical methods from the root through the matched call target.</para>
		///     <para xml:lang="zh-CN">从根方法到匹配调用目标的逻辑方法序列。</para>
		/// </summary>
		public IReadOnlyList<MethodBase> Methods { get; }

		/// <summary>
		///     <para xml:lang="en">Root logical method.</para>
		///     <para xml:lang="zh-CN">根逻辑方法。</para>
		/// </summary>
		public MethodBase Root => Methods[0];

		/// <summary>
		///     <para xml:lang="en">Matched call target.</para>
		///     <para xml:lang="zh-CN">匹配到的调用目标。</para>
		/// </summary>
		public MethodInfo Target
		{
			get
			{
				IReadOnlyList<MethodBase> methods = Methods;
				return (MethodInfo)methods[methods.Count - 1];
			}
		}

		/// <summary>
		///     <para xml:lang="en">Number of traversed intermediate methods. A direct call has depth zero.</para>
		///     <para xml:lang="zh-CN">已下钻的中间方法数量；直接调用的深度为零。</para>
		/// </summary>
		public int TraversalDepth => Math.Max(0, Methods.Count - 2);

		internal HarmonyIlCallPath(IReadOnlyList<MethodBase> methods)
		{
			Methods = methods;
		}

		/// <inheritdoc />
		public override string ToString()
		{
			return string.Join(" -> ", Methods.Select(FormatMethod));
		}

		private static string FormatMethod(MethodBase method)
		{
			return (method.DeclaringType?.FullName ?? "<global>") + "." + method.Name;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Convenience extensions for inspecting original Harmony IL and following explicitly selected
	///         calls.
	///     </para>
	///     <para xml:lang="zh-CN">用于检查 Harmony 原始 IL 并沿显式选定调用下钻的快捷扩展。</para>
	/// </summary>
	public static class HarmonyIlInspectionExtensions
	{
		private sealed record CallGraphNode(MethodBase Method, IReadOnlyList<MethodBase> Path, int TraversalDepth);

		/// <summary>
		///     <para xml:lang="en">
		///         Reads the original IL for a logical method. Async methods resolve to their generated
		///         <c>MoveNext</c> body by default.
		///     </para>
		///     <para xml:lang="zh-CN">读取逻辑方法的原始 IL。默认将异步方法解析到编译器生成的 <c>MoveNext</c> 方法体。</para>
		/// </summary>
		/// <param name="method">
		///     <para xml:lang="en">Logical method to inspect.</para>
		///     <para xml:lang="zh-CN">要检查的逻辑方法。</para>
		/// </param>
		/// <param name="resolveAsync">
		///     <para xml:lang="en">Resolve an async method to its generated state-machine body.</para>
		///     <para xml:lang="zh-CN">将异步方法解析到生成的状态机方法体。</para>
		/// </param>
		public static HarmonyIlMethodBody GetOriginalIl(this MethodBase method, bool resolveAsync = true)
		{
			ArgumentNullException.ThrowIfNull(method, "method");
			MethodBase methodBase = (resolveAsync ? (AccessTools.AsyncMoveNext(method) ?? method) : method);
			IReadOnlyList<CodeInstruction> instructions;
			try
			{
				ILGenerator iLGenerator = default(ILGenerator);
				instructions = PatchProcessor.GetOriginalInstructions(methodBase, ref iLGenerator);
			}
			catch (NotSupportedException)
			{
				instructions = HarmonyIlMethodReader.Read(methodBase);
			}
			return new HarmonyIlMethodBody(method, methodBase, instructions);
		}

		/// <summary>
		///     <para xml:lang="en">Returns true when the selected original IL call graph contains a matching call target.</para>
		///     <para xml:lang="zh-CN">选定的原始 IL 调用图包含匹配调用目标时返回 true。</para>
		/// </summary>
		/// <param name="method">
		///     <para xml:lang="en">Root logical method.</para>
		///     <para xml:lang="zh-CN">根逻辑方法。</para>
		/// </param>
		/// <param name="isTarget">
		///     <para xml:lang="en">Identifies a target call. This predicate runs before traversal filtering.</para>
		///     <para xml:lang="zh-CN">识别目标调用；此谓词先于下钻过滤执行。</para>
		/// </param>
		/// <param name="shouldTraverse">
		///     <para xml:lang="en">Selects helper methods whose bodies may be inspected. Null performs a direct-call-only query.</para>
		///     <para xml:lang="zh-CN">选择允许继续检查方法体的辅助方法；为 null 时仅查询直接调用。</para>
		/// </param>
		/// <param name="maxDepth">
		///     <para xml:lang="en">Maximum number of intermediate helper methods. A direct call has depth zero.</para>
		///     <para xml:lang="zh-CN">最大中间辅助方法数量；直接调用的深度为零。</para>
		/// </param>
		/// <param name="resolveAsync">
		///     <para xml:lang="en">Resolves each inspected async method to its generated state-machine body.</para>
		///     <para xml:lang="zh-CN">将每个被检查的异步方法解析到生成的状态机方法体。</para>
		/// </param>
		public static bool HasOriginalIlCall(this MethodBase method, Func<MethodInfo, bool> isTarget, Func<MethodInfo, bool>? shouldTraverse = null, int maxDepth = 8, bool resolveAsync = true)
		{
			return method.FindOriginalIlCallPath(isTarget, shouldTraverse, maxDepth, resolveAsync) != null;
		}

		/// <summary>
		///     <para xml:lang="en">Finds the shortest path to a matching call target in the selected original IL call graph.</para>
		///     <para xml:lang="zh-CN">在选定的原始 IL 调用图中查找到匹配调用目标的最短路径。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         Traversal is opt-in. The helper does not infer virtual dispatch, delegate targets, reflection
		///         calls, or methods not accepted by <paramref name="shouldTraverse" />.
		///     </para>
		///     <para xml:lang="zh-CN">下钻需显式启用。本工具不会推断虚调用分派、委托目标或反射调用，也不会检查未被 <paramref name="shouldTraverse" /> 接受的方法。</para>
		/// </remarks>
		/// <param name="method">
		///     <para xml:lang="en">Root logical method.</para>
		///     <para xml:lang="zh-CN">根逻辑方法。</para>
		/// </param>
		/// <param name="isTarget">
		///     <para xml:lang="en">Identifies a target call. This predicate runs before traversal filtering.</para>
		///     <para xml:lang="zh-CN">识别目标调用；此谓词先于下钻过滤执行。</para>
		/// </param>
		/// <param name="shouldTraverse">
		///     <para xml:lang="en">Selects helper methods whose bodies may be inspected. Null performs a direct-call-only query.</para>
		///     <para xml:lang="zh-CN">选择允许继续检查方法体的辅助方法；为 null 时仅查询直接调用。</para>
		/// </param>
		/// <param name="maxDepth">
		///     <para xml:lang="en">Maximum number of intermediate helper methods. A direct call has depth zero.</para>
		///     <para xml:lang="zh-CN">最大中间辅助方法数量；直接调用的深度为零。</para>
		/// </param>
		/// <param name="resolveAsync">
		///     <para xml:lang="en">Resolve each inspected async method to its generated state-machine body.</para>
		///     <para xml:lang="zh-CN">将每个被检查的异步方法解析到生成的状态机方法体。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The shortest matching path, or null when no selected path reaches a target.</para>
		///     <para xml:lang="zh-CN">最短匹配路径；没有选定路径到达目标时为 null。</para>
		/// </returns>
		public static HarmonyIlCallPath? FindOriginalIlCallPath(this MethodBase method, Func<MethodInfo, bool> isTarget, Func<MethodInfo, bool>? shouldTraverse = null, int maxDepth = 8, bool resolveAsync = true)
		{
			ArgumentNullException.ThrowIfNull(method, "method");
			ArgumentNullException.ThrowIfNull(isTarget, "isTarget");
			ArgumentOutOfRangeException.ThrowIfNegative(maxDepth, "maxDepth");
			Queue<CallGraphNode> queue = new Queue<CallGraphNode>();
			queue.Enqueue(new CallGraphNode(method, new <>z__ReadOnlySingleElementList<MethodBase>(method), 0));
			HashSet<MethodBase> hashSet = new HashSet<MethodBase>();
			CallGraphNode result;
			while (queue.TryDequeue(out result))
			{
				if (!hashSet.Add(result.Method))
				{
					continue;
				}
				foreach (MethodInfo calledMethod in result.Method.GetOriginalIl(resolveAsync).CalledMethods)
				{
					IReadOnlyList<MethodBase> readOnlyList = Append(result.Path, calledMethod);
					if (isTarget(calledMethod))
					{
						return new HarmonyIlCallPath(readOnlyList);
					}
					if (shouldTraverse != null && result.TraversalDepth < maxDepth && shouldTraverse(calledMethod))
					{
						queue.Enqueue(new CallGraphNode(calledMethod, readOnlyList, result.TraversalDepth + 1));
					}
				}
			}
			return null;
		}

		private static IReadOnlyList<MethodBase> Append(IReadOnlyList<MethodBase> path, MethodBase calledMethod)
		{
			MethodBase[] array = new MethodBase[path.Count + 1];
			for (int i = 0; i < path.Count; i++)
			{
				array[i] = path[i];
			}
			array[^1] = calledMethod;
			return array;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Decodes a method body into Harmony <see cref="T:HarmonyLib.CodeInstruction" /> values and resolves branch
	///         targets.
	///     </para>
	///     <para xml:lang="zh-CN">将方法体解码为 Harmony <see cref="T:HarmonyLib.CodeInstruction" /> 值，并解析分支目标。</para>
	/// </summary>
	internal static class HarmonyIlMethodReader
	{
		private sealed record DecodedInstruction(int Offset, CodeInstruction Instruction);

		private readonly record struct BranchTarget(int Offset);

		private static readonly OpCode[] SingleByteOpCodes;

		private static readonly OpCode[] MultiByteOpCodes;

		static HarmonyIlMethodReader()
		{
			SingleByteOpCodes = new OpCode[256];
			MultiByteOpCodes = new OpCode[256];
			FieldInfo[] fields = typeof(OpCodes).GetFields(BindingFlags.Static | BindingFlags.Public);
			for (int i = 0; i < fields.Length; i++)
			{
				if (fields[i].GetValue(null) is OpCode opCode)
				{
					ushort num = (ushort)opCode.Value;
					if (num < 256)
					{
						SingleByteOpCodes[num] = opCode;
					}
					else if ((num & 0xFF00) == 65024)
					{
						MultiByteOpCodes[num & 0xFF] = opCode;
					}
				}
			}
		}

		public static IReadOnlyList<CodeInstruction> Read(MethodBase method)
		{
			MethodBody methodBody = method.GetMethodBody() ?? throw new NotSupportedException("The method does not have an IL body.");
			byte[] bytes = methodBody.GetILAsByteArray() ?? throw new NotSupportedException("The method does not expose IL bytes.");
			List<DecodedInstruction> list = Decode(method, methodBody, bytes);
			ResolveBranches(list);
			List<CodeInstruction> list2 = new List<CodeInstruction>();
			list2.AddRange(list.Select((DecodedInstruction instruction) => instruction.Instruction));
			return new <>z__ReadOnlyList<CodeInstruction>(list2);
		}

		private static List<DecodedInstruction> Decode(MethodBase method, MethodBody body, byte[] bytes)
		{
			//IL_0069: Unknown result type (might be due to invalid IL or missing references)
			//IL_0073: Expected O, but got Unknown
			Module module = method.Module;
			Type[] typeArguments = method.DeclaringType?.GetGenericArguments();
			Type[] methodArguments = ((method is MethodInfo methodInfo) ? methodInfo.GetGenericArguments() : Type.EmptyTypes);
			List<DecodedInstruction> list = new List<DecodedInstruction>();
			int position = 0;
			while (position < bytes.Length)
			{
				int offset = position;
				OpCode opCode = ReadOpCode(bytes, ref position);
				object obj = ReadOperand(bytes, ref position, opCode, module, body.LocalVariables, typeArguments, methodArguments);
				list.Add(new DecodedInstruction(offset, new CodeInstruction(opCode, obj)));
			}
			return list;
		}

		private static OpCode ReadOpCode(byte[] bytes, ref int position)
		{
			byte b = bytes[position++];
			OpCode result = ((b == 254) ? MultiByteOpCodes[bytes[position++]] : SingleByteOpCodes[b]);
			if (result.Size != 0)
			{
				return result;
			}
			throw new BadImageFormatException($"Unknown IL opcode at offset {position - 1}.");
		}

		private static object? ReadOperand(byte[] bytes, ref int position, OpCode opCode, Module module, IList<LocalVariableInfo> locals, Type[]? typeArguments, Type[] methodArguments)
		{
			switch (opCode.OperandType)
			{
			case OperandType.InlineNone:
				return null;
			case OperandType.ShortInlineI:
				if (!(opCode == OpCodes.Ldc_I4_S))
				{
					return bytes[position++];
				}
				return (sbyte)bytes[position++];
			case OperandType.InlineI:
				return ReadInt32(bytes, ref position);
			case OperandType.InlineI8:
			{
				long num5 = BitConverter.ToInt64(bytes, position);
				position += 8;
				return num5;
			}
			case OperandType.ShortInlineR:
			{
				float num4 = BitConverter.ToSingle(bytes, position);
				position += 4;
				return num4;
			}
			case OperandType.InlineR:
			{
				double num3 = BitConverter.ToDouble(bytes, position);
				position += 8;
				return num3;
			}
			case OperandType.InlineString:
				return module.ResolveString(ReadInt32(bytes, ref position));
			case OperandType.InlineMethod:
				return module.ResolveMethod(ReadInt32(bytes, ref position), typeArguments, methodArguments);
			case OperandType.InlineField:
				return module.ResolveField(ReadInt32(bytes, ref position), typeArguments, methodArguments);
			case OperandType.InlineType:
				return module.ResolveType(ReadInt32(bytes, ref position), typeArguments, methodArguments);
			case OperandType.InlineTok:
				return module.ResolveMember(ReadInt32(bytes, ref position), typeArguments, methodArguments);
			case OperandType.InlineSig:
				return module.ResolveSignature(ReadInt32(bytes, ref position));
			case OperandType.ShortInlineVar:
				return ResolveVariable(bytes[position++], locals);
			case OperandType.InlineVar:
			{
				ushort index = BitConverter.ToUInt16(bytes, position);
				position += 2;
				return ResolveVariable(index, locals);
			}
			case OperandType.ShortInlineBrTarget:
				return new BranchTarget(position + 1 + (sbyte)bytes[position++]);
			case OperandType.InlineBrTarget:
				return new BranchTarget(position + 4 + ReadInt32(bytes, ref position));
			case OperandType.InlineSwitch:
			{
				int num = ReadInt32(bytes, ref position);
				int num2 = position + num * 4;
				BranchTarget[] array = new BranchTarget[num];
				for (int i = 0; i < num; i++)
				{
					array[i] = new BranchTarget(num2 + ReadInt32(bytes, ref position));
				}
				return array;
			}
			default:
				throw new NotSupportedException($"Unsupported IL operand type {opCode.OperandType}.");
			}
		}

		private static void ResolveBranches(IReadOnlyList<DecodedInstruction> decoded)
		{
			if (decoded.Count == 0)
			{
				return;
			}
			ILGenerator generator = new DynamicMethod("RitsuLibHarmonyIlLabels", typeof(void), Type.EmptyTypes).GetILGenerator();
			int[] source = decoded.SelectMany(delegate(DecodedInstruction decodedInstruction)
			{
				object operand3 = decodedInstruction.Instruction.operand;
				if (operand3 is BranchTarget branchTarget2)
				{
					return new <>z__ReadOnlySingleElementList<int>(branchTarget2.Offset);
				}
				return (operand3 is BranchTarget[] source3) ? source3.Select((BranchTarget target) => target.Offset) : Array.Empty<int>();
			}).Distinct().ToArray();
			Dictionary<int, Label> labels = source.ToDictionary((int offset) => offset, (int _) => generator.DefineLabel());
			Dictionary<int, DecodedInstruction> dictionary = decoded.ToDictionary((DecodedInstruction decodedInstruction) => decodedInstruction.Offset);
			foreach (var (num2, item) in labels)
			{
				if (!dictionary.TryGetValue(num2, out var value))
				{
					throw new BadImageFormatException($"IL branch target offset {num2} does not identify an instruction.");
				}
				value.Instruction.labels.Add(item);
			}
			foreach (DecodedInstruction item2 in decoded)
			{
				CodeInstruction instruction = item2.Instruction;
				object operand = item2.Instruction.operand;
				object operand2 = ((operand is BranchTarget branchTarget) ? ((object)labels[branchTarget.Offset]) : ((!(operand is BranchTarget[] source2)) ? operand : source2.Select((BranchTarget target) => labels[target.Offset]).ToArray()));
				instruction.operand = operand2;
			}
		}

		private static int ReadInt32(byte[] bytes, ref int position)
		{
			int result = BitConverter.ToInt32(bytes, position);
			position += 4;
			return result;
		}

		private static object ResolveVariable(int index, IList<LocalVariableInfo> locals)
		{
			if (index >= locals.Count)
			{
				return index;
			}
			return locals[index];
		}
	}
	/// <summary>
	///     <para xml:lang="en">A small sequential IL pattern used by RitsuLib transpiler wrappers.</para>
	///     <para xml:lang="zh-CN">供 RitsuLib 转译器包装器使用的小型顺序 IL 模式。</para>
	/// </summary>
	public sealed class HarmonyIlPattern
	{
		private readonly Func<CodeInstruction, bool>[] _parts;

		/// <summary>
		///     <para xml:lang="en">Number of instructions matched by this pattern.</para>
		///     <para xml:lang="zh-CN">此模式匹配的指令数量。</para>
		/// </summary>
		public int Length => _parts.Length;

		private HarmonyIlPattern(Func<CodeInstruction, bool>[] parts)
		{
			if (parts.Length == 0)
			{
				throw new ArgumentException("Pattern must contain at least one matcher.", "parts");
			}
			if (parts.Any((Func<CodeInstruction, bool> part) => part == null))
			{
				throw new ArgumentException("Pattern cannot contain null matchers.", "parts");
			}
			_parts = parts;
		}

		/// <summary>
		///     <para xml:lang="en">Creates a sequential pattern.</para>
		///     <para xml:lang="zh-CN">创建顺序模式。</para>
		/// </summary>
		public static HarmonyIlPattern Sequence(params Func<CodeInstruction, bool>[] parts)
		{
			ArgumentNullException.ThrowIfNull(parts, "parts");
			return new HarmonyIlPattern(parts);
		}

		/// <summary>
		///     <para xml:lang="en">Finds the first occurrence of this pattern.</para>
		///     <para xml:lang="zh-CN">查找此模式第一次出现的位置。</para>
		/// </summary>
		public bool TryFind(IReadOnlyList<CodeInstruction> code, out HarmonyIlMatch match)
		{
			return TryFind(code, 0, out match);
		}

		/// <summary>
		///     <para xml:lang="en">Finds the first occurrence of this pattern at or after <paramref name="startIndex" />.</para>
		///     <para xml:lang="zh-CN">从 <paramref name="startIndex" /> 起查找此模式第一次出现的位置。</para>
		/// </summary>
		public bool TryFind(IReadOnlyList<CodeInstruction> code, int startIndex, out HarmonyIlMatch match)
		{
			return TryFind(code, startIndex, code?.Count ?? 0, out match);
		}

		/// <summary>
		///     <para xml:lang="en">Finds the first occurrence of this pattern inside a bounded range.</para>
		///     <para xml:lang="zh-CN">在给定边界内查找此模式第一次出现的位置。</para>
		/// </summary>
		public bool TryFind(IReadOnlyList<CodeInstruction> code, int startIndex, int endExclusive, out HarmonyIlMatch match)
		{
			ArgumentNullException.ThrowIfNull(code, "code");
			int num = Math.Max(0, startIndex);
			int num2 = Math.Min(code.Count, endExclusive);
			for (int i = num; i <= num2 - _parts.Length; i++)
			{
				if (MatchesAt(code, i))
				{
					match = new HarmonyIlMatch(i, _parts.Length);
					return true;
				}
			}
			match = default(HarmonyIlMatch);
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Finds the last occurrence of this pattern.</para>
		///     <para xml:lang="zh-CN">查找此模式最后一次出现的位置。</para>
		/// </summary>
		public bool TryFindLast(IReadOnlyList<CodeInstruction> code, out HarmonyIlMatch match)
		{
			ArgumentNullException.ThrowIfNull(code, "code");
			for (int num = code.Count - _parts.Length; num >= 0; num--)
			{
				if (MatchesAt(code, num))
				{
					match = new HarmonyIlMatch(num, _parts.Length);
					return true;
				}
			}
			match = default(HarmonyIlMatch);
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Finds all non-overlapping occurrences of this pattern.</para>
		///     <para xml:lang="zh-CN">查找此模式的所有非重叠匹配。</para>
		/// </summary>
		public IReadOnlyList<HarmonyIlMatch> FindAll(IReadOnlyList<CodeInstruction> code)
		{
			ArgumentNullException.ThrowIfNull(code, "code");
			List<HarmonyIlMatch> list = new List<HarmonyIlMatch>();
			int startIndex = 0;
			HarmonyIlMatch match;
			while (TryFind(code, startIndex, out match))
			{
				list.Add(match);
				startIndex = match.EndExclusive;
			}
			return list;
		}

		/// <summary>
		///     <para xml:lang="en">Finds all non-overlapping occurrences of this pattern and returns assertion helpers.</para>
		///     <para xml:lang="zh-CN">查找此模式的所有非重叠匹配并返回断言辅助对象。</para>
		/// </summary>
		public HarmonyIlMatches FindMatches(IReadOnlyList<CodeInstruction> code, string description = "IL pattern")
		{
			return new HarmonyIlMatches(description, FindAll(code));
		}

		/// <summary>
		///     <para xml:lang="en">Returns true when this pattern matches at <paramref name="index" />.</para>
		///     <para xml:lang="zh-CN">当此模式在 <paramref name="index" /> 处匹配时返回 true。</para>
		/// </summary>
		public bool MatchesAt(IReadOnlyList<CodeInstruction> code, int index)
		{
			ArgumentNullException.ThrowIfNull(code, "code");
			if (index >= 0 && index <= code.Count - _parts.Length)
			{
				return MatchesAtCore(code, index);
			}
			return false;
		}

		private bool MatchesAtCore(IReadOnlyList<CodeInstruction> code, int index)
		{
			return !_parts.Where((Func<CodeInstruction, bool> t, int offset) => !t(code[index + offset])).Any();
		}
	}
	/// <summary>
	///     <para xml:lang="en">A collection of IL matches with assertion helpers.</para>
	///     <para xml:lang="zh-CN">带断言辅助方法的 IL 匹配集合。</para>
	/// </summary>
	public sealed class HarmonyIlMatches
	{
		/// <summary>
		///     <para xml:lang="en">Human-readable description used in assertion errors.</para>
		///     <para xml:lang="zh-CN">断言错误中使用的可读描述。</para>
		/// </summary>
		public string Description { get; }

		/// <summary>
		///     <para xml:lang="en">Number of matches.</para>
		///     <para xml:lang="zh-CN">匹配数量。</para>
		/// </summary>
		public int Count => Items.Count;

		/// <summary>
		///     <para xml:lang="en">Matched spans.</para>
		///     <para xml:lang="zh-CN">已匹配区间。</para>
		/// </summary>
		public IReadOnlyList<HarmonyIlMatch> Items { get; }

		/// <summary>
		///     <para xml:lang="en">Returns true when at least one match exists.</para>
		///     <para xml:lang="zh-CN">存在至少一个匹配时返回 true。</para>
		/// </summary>
		public bool Any => Items.Count > 0;

		/// <summary>
		///     <para xml:lang="en">Creates a match collection.</para>
		///     <para xml:lang="zh-CN">创建匹配集合。</para>
		/// </summary>
		public HarmonyIlMatches(string description, IEnumerable<HarmonyIlMatch> matches)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(description, "description");
			ArgumentNullException.ThrowIfNull(matches, "matches");
			Description = description;
			List<HarmonyIlMatch> list = new List<HarmonyIlMatch>();
			list.AddRange(matches);
			Items = new <>z__ReadOnlyList<HarmonyIlMatch>(list);
		}

		/// <summary>
		///     <para xml:lang="en">Returns the first match and throws when none exist.</para>
		///     <para xml:lang="zh-CN">返回第一个匹配；不存在匹配时抛出异常。</para>
		/// </summary>
		public HarmonyIlMatch First()
		{
			if (Items.Count <= 0)
			{
				throw NewCountException("at least 1");
			}
			return Items[0];
		}

		/// <summary>
		///     <para xml:lang="en">Returns the last match and throws when none exist.</para>
		///     <para xml:lang="zh-CN">返回最后一个匹配；不存在匹配时抛出异常。</para>
		/// </summary>
		public HarmonyIlMatch Last()
		{
			if (Items.Count <= 0)
			{
				throw NewCountException("at least 1");
			}
			IReadOnlyList<HarmonyIlMatch> items = Items;
			return items[items.Count - 1];
		}

		/// <summary>
		///     <para xml:lang="en">Requires exactly one match and returns it.</para>
		///     <para xml:lang="zh-CN">要求恰好一个匹配并返回它。</para>
		/// </summary>
		public HarmonyIlMatch RequireSingle()
		{
			if (Items.Count != 1)
			{
				throw NewCountException("exactly 1");
			}
			return Items[0];
		}

		/// <summary>
		///     <para xml:lang="en">Requires an exact match count.</para>
		///     <para xml:lang="zh-CN">要求精确匹配数量。</para>
		/// </summary>
		public HarmonyIlMatches RequireExactly(int count)
		{
			if (Items.Count != count)
			{
				throw NewCountException($"exactly {count}");
			}
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Requires at least <paramref name="count" /> matches.</para>
		///     <para xml:lang="zh-CN">要求至少 <paramref name="count" /> 个匹配。</para>
		/// </summary>
		public HarmonyIlMatches RequireAtLeast(int count)
		{
			if (Items.Count < count)
			{
				throw NewCountException($"at least {count}");
			}
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Requires no matches.</para>
		///     <para xml:lang="zh-CN">要求没有匹配。</para>
		/// </summary>
		public HarmonyIlMatches RequireNone()
		{
			return RequireExactly(0);
		}

		/// <summary>
		///     <para xml:lang="en">Returns a compact diagnostic string.</para>
		///     <para xml:lang="zh-CN">返回紧凑诊断字符串。</para>
		/// </summary>
		public string Describe()
		{
			return $"{Description}: count={Items.Count}, indexes=[{string.Join(", ", Items.Select((HarmonyIlMatch match) => match.Index))}]";
		}

		private InvalidOperationException NewCountException(string expected)
		{
			return new InvalidOperationException($"{Description} matched {Items.Count} span(s), expected {expected}. indexes=[{string.Join(", ", Items.Select((HarmonyIlMatch match) => match.Index))}].");
		}
	}
