		}

		/// <summary>
		///     <para xml:lang="en">Reads a string operand from the matched instruction at <paramref name="offset" />.</para>
		///     <para xml:lang="zh-CN">从匹配区间中 <paramref name="offset" /> 处的指令读取字符串操作数。</para>
