		/// <summary>
		///     <para xml:lang="en">Insert before the last <see cref="F:System.Reflection.Emit.OpCodes.Ret" />.</para>
		///     <para xml:lang="zh-CN">插入到最后一条 <see cref="F:System.Reflection.Emit.OpCodes.Ret" /> 之前。</para>
		/// </summary>
		BeforeLastRet,
		/// <summary>
		///     <para xml:lang="en">Insert before every <see cref="F:System.Reflection.Emit.OpCodes.Ret" />.</para>
		///     <para xml:lang="zh-CN">插入到每条 <see cref="F:System.Reflection.Emit.OpCodes.Ret" /> 之前。</para>
		/// </summary>
		BeforeEachRet
	}
	/// <summary>
	///     <para xml:lang="en">Handle for a generated IL payload transpiler.</para>
	///     <para xml:lang="zh-CN">生成式 IL 载荷转译器的句柄。</para>
	/// </summary>
	public sealed class HarmonyIlPayloadTranspilerHandle : IDisposable
	{
		private IDisposable? _lifetimeLease;

		/// <summary>
		///     <para xml:lang="en">Stable payload id used by the generated transpiler method.</para>
		///     <para xml:lang="zh-CN">生成的转译器方法使用的稳定载荷 ID。</para>
		/// </summary>
		public string PayloadId { get; }

		/// <summary>
		///     <para xml:lang="en">Harmony method that can be passed as a transpiler.</para>
		///     <para xml:lang="zh-CN">可作为转译器传给 Harmony 的方法。</para>
		/// </summary>
		public HarmonyMethod HarmonyMethod { get; }

		internal HarmonyIlPayloadTranspilerHandle(string payloadId, HarmonyMethod harmonyMethod, IDisposable lifetimeLease)
		{
			PayloadId = payloadId;
			HarmonyMethod = harmonyMethod;
			_lifetimeLease = lifetimeLease;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Removes the payload from the static registry. Call only after the owning Harmony patch is
		///         removed.
		///     </para>
		///     <para xml:lang="zh-CN">从静态注册表移除此载荷。仅应在所属 Harmony 补丁已移除后调用。</para>
		/// </summary>
		public void Dispose()
		{
			Interlocked.Exchange(ref _lifetimeLease, null)?.Dispose();
		}
	}
	/// <summary>
	///     <para xml:lang="en">Builds per-payload Harmony transpilers for generated IL rewrites.</para>
	///     <para xml:lang="zh-CN">为生成式 IL 改写创建逐载荷的 Harmony 转译器。</para>
	/// </summary>
	public static class HarmonyIlPayloadTranspiler
	{
		private sealed record Payload(string Id, IReadOnlyList<CodeInstruction> Instructions, string Operation, HarmonyIlReturnInsertionMode Mode, bool MoveLabelsAndBlocksToInserted, bool ValidateOutput);

		private sealed class PayloadRegistration(Payload payload, HarmonyMethod harmonyMethod)
		{
			private sealed class PayloadLease(PayloadRegistration registration) : IDisposable
			{
				private PayloadRegistration? _registration = registration;

				public void Dispose()
				{
					Interlocked.Exchange(ref _registration, null)?.Release();
				}
			}

			private int _leaseCount;

			public Payload Payload { get; } = payload;

			public HarmonyMethod HarmonyMethod { get; } = harmonyMethod;

			public IDisposable Acquire()
			{
				using (Gate.EnterScope())
				{
					if (_leaseCount == int.MaxValue)
					{
						throw new InvalidOperationException("Harmony IL payload '" + Payload.Id + "' has too many active owners.");
					}
					if (_leaseCount == 0)
					{
						Payloads.Add(Payload.Id, this);
					}
					_leaseCount++;
				}
				return new PayloadLease(this);
			}

			private void Release()
			{
				using (Gate.EnterScope())
				{
					if (_leaseCount <= 0)
					{
						throw new InvalidOperationException("Harmony IL payload '" + Payload.Id + "' has no active owner.");
					}
					_leaseCount--;
					if (_leaseCount == 0)
					{
						Payloads.Remove(Payload.Id);
					}
				}
			}
		}

		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<string, PayloadRegistration> Payloads = new Dictionary<string, PayloadRegistration>();

		private static int _nextPayloadId;

		/// <summary>
		///     <para xml:lang="en">Creates a Harmony transpiler that inserts <paramref name="payload" /> at return sites.</para>
		///     <para xml:lang="zh-CN">创建一个在返回点插入 <paramref name="payload" /> 的 Harmony 转译器。</para>
		/// </summary>
		public static HarmonyIlPayloadTranspilerHandle CreateReturnInsertion(IEnumerable<CodeInstruction> payload, string operation = "Harmony IL payload return insertion", HarmonyIlReturnInsertionMode mode = HarmonyIlReturnInsertionMode.BeforeSingleRet, bool moveLabelsAndBlocksToInserted = false, bool validateOutput = true)
		{
			ArgumentNullException.ThrowIfNull(payload, "payload");
			ArgumentException.ThrowIfNullOrWhiteSpace(operation, "operation");
			PayloadRegistration payloadRegistration = CreateRegistration(payload, operation, mode, moveLabelsAndBlocksToInserted, validateOutput);
			return new HarmonyIlPayloadTranspilerHandle(payloadRegistration.Payload.Id, payloadRegistration.HarmonyMethod, payloadRegistration.Acquire());
		}

		/// <summary>
		///     <para xml:lang="en">Creates a <see cref="T:STS2RitsuLib.Patching.Models.DynamicPatchInfo" /> using a generated return-insertion transpiler.</para>
		///     <para xml:lang="zh-CN">使用生成式返回点插入转译器创建 <see cref="T:STS2RitsuLib.Patching.Models.DynamicPatchInfo" />。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         Apply the result through <see cref="T:STS2RitsuLib.Patching.Core.ModPatcher" />, which owns the generated payload
		///         for the
		///         applied patch's lifetime. For direct Harmony calls, use <see cref="M:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlPayloadTranspiler.CreateReturnInsertion(System.Collections.Generic.IEnumerable{HarmonyLib.CodeInstruction},System.String,STS2RitsuLib.Utils.HarmonyIl.HarmonyIlReturnInsertionMode,System.Boolean,System.Boolean)" /> or
		///         <see cref="M:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlPayloadTranspiler.PatchReturnInsertion(HarmonyLib.Harmony,System.Reflection.MethodBase,System.Collections.Generic.IEnumerable{HarmonyLib.CodeInstruction},System.String,STS2RitsuLib.Utils.HarmonyIl.HarmonyIlReturnInsertionMode,System.Boolean,System.Boolean)" /> and retain the returned handle until the patch is removed.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         请通过 <see cref="T:STS2RitsuLib.Patching.Core.ModPatcher" /> 应用返回结果，由补丁器在补丁生效期间持有生成的载荷。直接调用
		///         Harmony 时，请使用 <see cref="M:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlPayloadTranspiler.CreateReturnInsertion(System.Collections.Generic.IEnumerable{HarmonyLib.CodeInstruction},System.String,STS2RitsuLib.Utils.HarmonyIl.HarmonyIlReturnInsertionMode,System.Boolean,System.Boolean)" /> 或 <see cref="M:STS2RitsuLib.Utils.HarmonyIl.HarmonyIlPayloadTranspiler.PatchReturnInsertion(HarmonyLib.Harmony,System.Reflection.MethodBase,System.Collections.Generic.IEnumerable{HarmonyLib.CodeInstruction},System.String,STS2RitsuLib.Utils.HarmonyIl.HarmonyIlReturnInsertionMode,System.Boolean,System.Boolean)" />，
		///         并保留返回的句柄直至补丁被移除。
		///     </para>
		/// </remarks>
		public static DynamicPatchInfo CreateReturnInsertionPatch(string id, MethodBase originalMethod, IEnumerable<CodeInstruction> payload, string? description = null, bool isCritical = true, string operation = "Harmony IL payload return insertion", HarmonyIlReturnInsertionMode mode = HarmonyIlReturnInsertionMode.BeforeSingleRet, bool moveLabelsAndBlocksToInserted = false, bool validateOutput = true)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentNullException.ThrowIfNull(originalMethod, "originalMethod");
			PayloadRegistration payloadRegistration = CreateRegistration(payload, operation, mode, moveLabelsAndBlocksToInserted, validateOutput);
			DynamicPatchInfo dynamicPatchInfo = new DynamicPatchInfo(id, originalMethod, null, null, payloadRegistration.HarmonyMethod, null, isCritical, description);
			dynamicPatchInfo.SetLifetimeLeaseFactory(payloadRegistration.Acquire);
			return dynamicPatchInfo;
		}

		/// <summary>
		///     <para xml:lang="en">Applies a generated return-insertion transpiler directly to <paramref name="originalMethod" />.</para>
		///     <para xml:lang="zh-CN">将生成式返回点插入转译器直接应用到 <paramref name="originalMethod" />。</para>
		/// </summary>
		public static HarmonyIlPayloadTranspilerHandle PatchReturnInsertion(Harmony harmony, MethodBase originalMethod, IEnumerable<CodeInstruction> payload, string operation = "Harmony IL payload return insertion", HarmonyIlReturnInsertionMode mode = HarmonyIlReturnInsertionMode.BeforeSingleRet, bool moveLabelsAndBlocksToInserted = false, bool validateOutput = true)
		{
			ArgumentNullException.ThrowIfNull(harmony, "harmony");
			ArgumentNullException.ThrowIfNull(originalMethod, "originalMethod");
			HarmonyIlPayloadTranspilerHandle harmonyIlPayloadTranspilerHandle = CreateReturnInsertion(payload, operation, mode, moveLabelsAndBlocksToInserted, validateOutput);
			try
			{
				harmony.Patch(originalMethod, (HarmonyMethod)null, (HarmonyMethod)null, harmonyIlPayloadTranspilerHandle.HarmonyMethod, (HarmonyMethod)null);
				return harmonyIlPayloadTranspilerHandle;
			}
			catch
			{
				harmonyIlPayloadTranspilerHandle.Dispose();
				throw;
			}
		}

		private static PayloadRegistration CreateRegistration(IEnumerable<CodeInstruction> payload, string operation, HarmonyIlReturnInsertionMode mode, bool moveLabelsAndBlocksToInserted, bool validateOutput)
		{
			//IL_0033: Unknown result type (might be due to invalid IL or missing references)
			//IL_003d: Expected O, but got Unknown
			ArgumentNullException.ThrowIfNull(payload, "payload");
			ArgumentException.ThrowIfNullOrWhiteSpace(operation, "operation");
			string text = AllocatePayloadId();
			return new PayloadRegistration(new Payload(text, HarmonyIl.CloneAll(payload), operation, mode, moveLabelsAndBlocksToInserted, validateOutput), new HarmonyMethod(CreateFactoryMethod(text)));
		}

		private static IEnumerable<CodeInstruction> Transpile(IEnumerable<CodeInstruction> instructions, string payloadId)
		{
			PayloadRegistration value;
			using (Gate.EnterScope())
			{
				Payloads.TryGetValue(payloadId, out value);
			}
			if (value == null)
			{
				throw new InvalidOperationException("Harmony IL payload '" + payloadId + "' is not registered.");
			}
			Payload payload = value.Payload;
			CodeInstruction[] prefix = HarmonyIl.CloneAll(payload.Instructions);
			HarmonyIlRewriter harmonyIlRewriter = HarmonyIlRewriter.From(instructions);
			HarmonyIlRewriteReport harmonyIlRewriteReport = payload.Mode switch
			{
				HarmonyIlReturnInsertionMode.BeforeFirstRet => harmonyIlRewriter.InsertBeforeFirstRet(payload.Operation, prefix, null, payload.MoveLabelsAndBlocksToInserted), 
				HarmonyIlReturnInsertionMode.BeforeSingleRet => harmonyIlRewriter.InsertBeforeSingleRet(payload.Operation, prefix, null, payload.MoveLabelsAndBlocksToInserted), 
				HarmonyIlReturnInsertionMode.BeforeLastRet => harmonyIlRewriter.InsertBeforeLastRet(payload.Operation, prefix, null, payload.MoveLabelsAndBlocksToInserted), 
				HarmonyIlReturnInsertionMode.BeforeEachRet => harmonyIlRewriter.InsertBeforeEachRet(payload.Operation, prefix, null, payload.MoveLabelsAndBlocksToInserted), 
				_ => throw new ArgumentOutOfRangeException("Mode", payload.Mode, null), 
			};
			harmonyIlRewriteReport.RequireSucceeded();
			harmonyIlRewriteReport.RequireApplied();
			if (!payload.ValidateOutput)
			{
				return harmonyIlRewriter.Instructions();
			}
			return harmonyIlRewriter.InstructionsChecked(payload.Operation);
		}

		private static string AllocatePayloadId()
		{
			using (Gate.EnterScope())
			{
				return $"ritsulib_il_payload_{++_nextPayloadId:D6}";
			}
		}

		private static ModuleBuilder CreateFactoryModule(string payloadId)
		{
			string text = typeof(HarmonyIlPayloadTranspiler).Assembly.GetName().Name ?? throw new InvalidOperationException("RitsuLib assembly has no simple name.");
			AssemblyName assemblyName = new AssemblyName(text + ".HarmonyIlPayloadFactory." + payloadId);
			AssemblyBuilder assemblyBuilder = AssemblyBuilder.DefineDynamicAssembly(assemblyName, AssemblyBuilderAccess.RunAndCollect);
			ConstructorInfo con = typeof(IgnoresAccessChecksToAttribute).GetConstructor(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, new Type[1] { typeof(string) }, null) ?? throw new MissingMethodException(typeof(IgnoresAccessChecksToAttribute).FullName, ".ctor");
			assemblyBuilder.SetCustomAttribute(new CustomAttributeBuilder(con, new object[1] { text }));
			return assemblyBuilder.DefineDynamicModule(assemblyName.Name);
		}

		private static MethodInfo CreateFactoryMethod(string payloadId)
		{
			TypeBuilder typeBuilder = CreateFactoryModule(payloadId).DefineType("RitsuLibHarmonyIlPayloadFactory_" + payloadId, TypeAttributes.Public | TypeAttributes.Abstract | TypeAttributes.Sealed);
			MethodBuilder methodBuilder = typeBuilder.DefineMethod("CreateTranspiler", MethodAttributes.Public | MethodAttributes.Static | MethodAttributes.HideBySig, typeof(DynamicMethod), new Type[1] { typeof(MethodBase) });
			ILGenerator iLGenerator = methodBuilder.GetILGenerator();
			iLGenerator.Emit(OpCodes.Ldstr, payloadId);
			iLGenerator.Emit(OpCodes.Call, AccessTools.DeclaredMethod(typeof(HarmonyIlPayloadTranspiler), "CreateDynamicTranspiler", (Type[])null, (Type[])null));
			iLGenerator.Emit(OpCodes.Ret);
			return typeBuilder.CreateType().GetMethod(methodBuilder.Name, BindingFlags.Static | BindingFlags.Public) ?? throw new MissingMethodException(typeBuilder.FullName, methodBuilder.Name);
		}

		private static DynamicMethod CreateDynamicTranspiler(string payloadId)
		{
			DynamicMethod dynamicMethod = new DynamicMethod("RitsuLibHarmonyIlPayloadTranspiler_" + payloadId, typeof(IEnumerable<CodeInstruction>), new Type[1] { typeof(IEnumerable<CodeInstruction>) }, typeof(HarmonyIlPayloadTranspiler).Module, skipVisibility: true);
			ILGenerator iLGenerator = dynamicMethod.GetILGenerator();
			iLGenerator.Emit(OpCodes.Ldarg_0);
			iLGenerator.Emit(OpCodes.Ldstr, payloadId);
			iLGenerator.Emit(OpCodes.Call, AccessTools.DeclaredMethod(typeof(HarmonyIlPayloadTranspiler), "Transpile", (Type[])null, (Type[])null));
			iLGenerator.Emit(OpCodes.Ret);
			return dynamicMethod;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Method context used for IL queries that need local variable metadata.</para>
	///     <para xml:lang="zh-CN">需要本地变量元数据的 IL 查询使用的方法上下文。</para>
	/// </summary>
	public sealed class HarmonyIlContext
	{
		/// <summary>
		///     <para xml:lang="en">Original method supplied by Harmony, when available.</para>
		///     <para xml:lang="zh-CN">Harmony 提供的原始方法（如果可用）。</para>
		/// </summary>
		public MethodBase? OriginalMethod { get; }

		/// <summary>
		///     <para xml:lang="en">Local variables declared by the original method body.</para>
		///     <para xml:lang="zh-CN">原始方法体声明的本地变量。</para>
		/// </summary>
		public IReadOnlyList<LocalVariableInfo> Locals { get; }

		private HarmonyIlContext(MethodBase? originalMethod, IReadOnlyList<LocalVariableInfo> locals)
		{
			OriginalMethod = originalMethod;
			Locals = locals;
		}

		/// <summary>
		///     <para xml:lang="en">Creates context from an original method.</para>
		///     <para xml:lang="zh-CN">根据原始方法创建上下文。</para>
		/// </summary>
		public static HarmonyIlContext From(MethodBase? originalMethod)
		{
			List<LocalVariableInfo> locals = originalMethod?.GetMethodBody()?.LocalVariables.ToList() ?? new List<LocalVariableInfo>();
			return new HarmonyIlContext(originalMethod, locals);
		}

		/// <summary>
		///     <para xml:lang="en">Tries to resolve a local variable type by index.</para>
		///     <para xml:lang="zh-CN">尝试按索引解析本地变量类型。</para>
		/// </summary>
		public bool TryGetLocalType(int index, out Type localType)
		{
			LocalVariableInfo localVariableInfo = Locals.FirstOrDefault((LocalVariableInfo variable) => variable.LocalIndex == index);
			if (localVariableInfo != null)
			{
				localType = localVariableInfo.LocalType;
				return true;
			}
			localType = null;
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Mutable instruction-list wrapper for small, auditable Harmony transpiler rewrites.</para>
	///     <para xml:lang="zh-CN">用于小型、可审计 Harmony 转译器改写的可变指令列表包装器。</para>
	/// </summary>
	public sealed class HarmonyIlRewriter
	{
		private readonly List<CodeInstruction> _code;

		/// <summary>
		///     <para xml:lang="en">Current mutable instruction list.</para>
		///     <para xml:lang="zh-CN">当前可变指令列表。</para>
		/// </summary>
		public IReadOnlyList<CodeInstruction> Code => _code;

		/// <summary>
		///     <para xml:lang="en">Optional method context used by type-aware local queries.</para>
		///     <para xml:lang="zh-CN">类型感知本地变量查询使用的可选方法上下文。</para>
		/// </summary>
		public HarmonyIlContext? Context { get; }

		private HarmonyIlRewriter(IEnumerable<CodeInstruction> instructions, HarmonyIlContext? context = null)
		{
			ArgumentNullException.ThrowIfNull(instructions, "instructions");
			_code = instructions.ToList();
			Context = context;
		}

		/// <summary>
		///     <para xml:lang="en">Creates a rewriter over <paramref name="instructions" />.</para>
		///     <para xml:lang="zh-CN">基于 <paramref name="instructions" /> 创建改写器。</para>
		/// </summary>
		public static HarmonyIlRewriter From(IEnumerable<CodeInstruction> instructions)
		{
			return new HarmonyIlRewriter(instructions);
		}

		/// <summary>
		///     <para xml:lang="en">Creates a rewriter with method context from Harmony's original method parameter.</para>
		///     <para xml:lang="zh-CN">使用 Harmony 原始方法参数提供的方法上下文创建改写器。</para>
		/// </summary>
		public static HarmonyIlRewriter From(IEnumerable<CodeInstruction> instructions, MethodBase? originalMethod)
		{
			return new HarmonyIlRewriter(instructions, HarmonyIlContext.From(originalMethod));
		}

		/// <summary>
		///     <para xml:lang="en">Creates a rewriter with explicit method context.</para>
		///     <para xml:lang="zh-CN">使用显式方法上下文创建改写器。</para>
		/// </summary>
		public static HarmonyIlRewriter From(IEnumerable<CodeInstruction> instructions, HarmonyIlContext? context)
		{
			return new HarmonyIlRewriter(instructions, context);
		}

		/// <summary>
		///     <para xml:lang="en">Returns the rewritten instruction list.</para>
		///     <para xml:lang="zh-CN">返回改写后的指令列表。</para>
		/// </summary>
		public List<CodeInstruction> Instructions()
		{
			return _code;
		}

		/// <summary>
		///     <para xml:lang="en">Validates and returns the rewritten instruction list.</para>
		///     <para xml:lang="zh-CN">验证并返回改写后的指令列表。</para>
		/// </summary>
		public List<CodeInstruction> InstructionsChecked(string operation = "Harmony IL rewrite")
		{
			Validate(operation).ThrowIfInvalid();
			return _code;
		}

		/// <summary>
		///     <para xml:lang="en">Validates required rewrite reports and the resulting instruction list, then returns it.</para>
		///     <para xml:lang="zh-CN">验证所需改写报告与最终指令列表，然后返回该列表。</para>
		/// </summary>
		public List<CodeInstruction> InstructionsChecked(IEnumerable<HarmonyIlRewriteReport> reports, int expectedSites = 1)
		{
			ArgumentNullException.ThrowIfNull(reports, "reports");
			HarmonyIlRewriteReport[] array = reports.ToArray();
			HarmonyIlRewriteReport[] array2 = array;
			foreach (HarmonyIlRewriteReport harmonyIlRewriteReport in array2)
			{
				harmonyIlRewriteReport.RequireExactSitesOrAlreadySatisfied(expectedSites);
			}
			string operation = ((array.Length == 0) ? "Harmony IL rewrite" : string.Join("; ", array.Select((HarmonyIlRewriteReport report) => report.Operation)));
			return InstructionsChecked(operation);
		}

		/// <summary>
		///     <para xml:lang="en">Validates one required rewrite report and the resulting instruction list, then returns it.</para>
		///     <para xml:lang="zh-CN">验证一个所需改写报告与最终指令列表，然后返回该列表。</para>
		/// </summary>
		public List<CodeInstruction> InstructionsChecked(HarmonyIlRewriteReport report, int expectedSites = 1)
		{
			return InstructionsChecked(new <>z__ReadOnlySingleElementList<HarmonyIlRewriteReport>(report), expectedSites);
		}

		/// <summary>
		///     <para xml:lang="en">Validates the current instruction list.</para>
		///     <para xml:lang="zh-CN">验证当前指令列表。</para>
		/// </summary>
		public HarmonyIlValidationReport Validate(string operation = "Harmony IL rewrite")
		{
			return HarmonyIlValidation.Validate(_code, operation);
		}

		/// <summary>
		///     <para xml:lang="en">Returns true when any instruction satisfies <paramref name="predicate" />.</para>
		///     <para xml:lang="zh-CN">任一指令满足 <paramref name="predicate" /> 时返回 true。</para>
		/// </summary>
		public bool Contains(Func<CodeInstruction, bool> predicate)
		{
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			return _code.Any(predicate);
		}

		/// <summary>
		///     <para xml:lang="en">Counts instructions that satisfy <paramref name="predicate" />.</para>
		///     <para xml:lang="zh-CN">统计满足 <paramref name="predicate" /> 的指令数量。</para>
		/// </summary>
		public int Count(Func<CodeInstruction, bool> predicate)
		{
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			return _code.Count(predicate);
		}

		/// <summary>
		///     <para xml:lang="en">Finds a sequential pattern.</para>
		///     <para xml:lang="zh-CN">查找顺序模式。</para>
		/// </summary>
		public bool TryFind(HarmonyIlPattern pattern, out HarmonyIlMatch match)
		{
			ArgumentNullException.ThrowIfNull(pattern, "pattern");
			return pattern.TryFind(_code, out match);
		}

		/// <summary>
		///     <para xml:lang="en">Finds a sequential pattern at or after <paramref name="startIndex" />.</para>
		///     <para xml:lang="zh-CN">从 <paramref name="startIndex" /> 起查找顺序模式。</para>
		/// </summary>
		public bool TryFind(HarmonyIlPattern pattern, int startIndex, out HarmonyIlMatch match)
		{
			ArgumentNullException.ThrowIfNull(pattern, "pattern");
			return pattern.TryFind(_code, startIndex, out match);
		}

		/// <summary>
		///     <para xml:lang="en">Finds the last occurrence of a sequential pattern.</para>
		///     <para xml:lang="zh-CN">查找顺序模式最后一次出现的位置。</para>
		/// </summary>
		public bool TryFindLast(HarmonyIlPattern pattern, out HarmonyIlMatch match)
		{
			ArgumentNullException.ThrowIfNull(pattern, "pattern");
			return pattern.TryFindLast(_code, out match);
		}

		/// <summary>
		///     <para xml:lang="en">Finds a pattern after an anchor match, optionally within a limited instruction distance.</para>
		///     <para xml:lang="zh-CN">在锚点匹配之后查找模式，可限制最大指令距离。</para>
		/// </summary>
		public bool TryFindAfter(HarmonyIlMatch anchor, HarmonyIlPattern pattern, out HarmonyIlMatch match, int maxDistance = int.MaxValue)
		{
			ArgumentNullException.ThrowIfNull(pattern, "pattern");
			ValidateMatch(anchor);
			int endExclusive = anchor.EndExclusive;
			int endExclusive2 = ((maxDistance == int.MaxValue) ? _code.Count : Math.Min(_code.Count, endExclusive + Math.Max(0, maxDistance)));
			return pattern.TryFind(_code, endExclusive, endExclusive2, out match);
		}

		/// <summary>
		///     <para xml:lang="en">Finds a pattern before an anchor match, optionally within a limited instruction distance.</para>
		///     <para xml:lang="zh-CN">在锚点匹配之前查找模式，可限制最大指令距离。</para>
		/// </summary>
		public bool TryFindBefore(HarmonyIlMatch anchor, HarmonyIlPattern pattern, out HarmonyIlMatch match, int maxDistance = int.MaxValue)
		{
			ArgumentNullException.ThrowIfNull(pattern, "pattern");
			ValidateMatch(anchor);
			int startIndex = ((maxDistance != int.MaxValue) ? Math.Max(0, anchor.Index - Math.Max(0, maxDistance)) : 0);
			return pattern.TryFind(_code, startIndex, anchor.Index, out match);
		}

		/// <summary>
		///     <para xml:lang="en">Finds the nearest instruction before an anchor that satisfies <paramref name="predicate" />.</para>
		///     <para xml:lang="zh-CN">查找锚点前最近一条满足 <paramref name="predicate" /> 的指令。</para>
		/// </summary>
		public bool TryFindBefore(HarmonyIlMatch anchor, Func<CodeInstruction, bool> predicate, out HarmonyIlMatch match, int maxDistance = int.MaxValue)
		{
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			ValidateMatch(anchor);
			int num = ((maxDistance != int.MaxValue) ? Math.Max(0, anchor.Index - Math.Max(0, maxDistance)) : 0);
			for (int num2 = anchor.Index - 1; num2 >= num; num2--)
			{
				if (predicate(_code[num2]))
				{
					match = new HarmonyIlMatch(num2, 1);
					return true;
				}
			}
			match = default(HarmonyIlMatch);
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Finds the first instruction that satisfies <paramref name="predicate" />.</para>
		///     <para xml:lang="zh-CN">查找第一条满足 <paramref name="predicate" /> 的指令。</para>
		/// </summary>
		public bool TryFindFirst(Func<CodeInstruction, bool> predicate, out HarmonyIlMatch match)
		{
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			for (int i = 0; i < _code.Count; i++)
			{
				if (predicate(_code[i]))
				{
					match = new HarmonyIlMatch(i, 1);
					return true;
				}
			}
			match = default(HarmonyIlMatch);
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Finds the last instruction that satisfies <paramref name="predicate" />.</para>
		///     <para xml:lang="zh-CN">查找最后一条满足 <paramref name="predicate" /> 的指令。</para>
		/// </summary>
		public bool TryFindLast(Func<CodeInstruction, bool> predicate, out HarmonyIlMatch match)
		{
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			for (int num = _code.Count - 1; num >= 0; num--)
			{
				if (predicate(_code[num]))
				{
					match = new HarmonyIlMatch(num, 1);
					return true;
				}
			}
			match = default(HarmonyIlMatch);
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Finds all instructions that satisfy <paramref name="predicate" />.</para>
		///     <para xml:lang="zh-CN">查找所有满足 <paramref name="predicate" /> 的指令。</para>
		/// </summary>
		public HarmonyIlMatches FindAll(Func<CodeInstruction, bool> predicate, string description = "IL instruction")
		{
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			List<HarmonyIlMatch> list = new List<HarmonyIlMatch>();
			for (int i = 0; i < _code.Count; i++)
			{
				if (predicate(_code[i]))
				{
					list.Add(new HarmonyIlMatch(i, 1));
				}
			}
			return new HarmonyIlMatches(description, list);
		}

		/// <summary>
		///     <para xml:lang="en">Finds all occurrences of a sequential pattern.</para>
		///     <para xml:lang="zh-CN">查找顺序模式的所有匹配。</para>
		/// </summary>
		public HarmonyIlMatches FindMatches(HarmonyIlPattern pattern, string description = "IL pattern")
		{
			ArgumentNullException.ThrowIfNull(pattern, "pattern");
			return pattern.FindMatches(_code, description);
		}

