		private bool TryGetLocalLoad(CodeInstruction instruction, out HarmonyIlLocalRef local)
		{
			if (HarmonyIl.TryGetLocalLoad(instruction, out local))
			{
				return TryEnrichLocal(ref local);
			}
			return false;
		}

		private bool TryGetLocalStore(CodeInstruction instruction, out HarmonyIlLocalRef local)
		{
			if (HarmonyIl.TryGetLocalStore(instruction, out local))
			{
				return TryEnrichLocal(ref local);
			}
			return false;
		}

		private bool TryEnrichLocal(ref HarmonyIlLocalRef local)
		{
			if (!(local.LocalType != null))
			{
				HarmonyIlContext? context = Context;
				if (context != null && context.TryGetLocalType(local.Index, out Type localType))
				{
					local = local with
					{
						LocalType = localType
					};
					return true;
				}
			}
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Inserts instructions immediately before a matched span.</para>
		///     <para xml:lang="zh-CN">在已匹配区间前插入指令。</para>
		/// </summary>
		public void InsertBefore(HarmonyIlMatch match, IEnumerable<CodeInstruction> instructions, bool moveLabelsAndBlocksToInserted = false)
		{
			ValidateMatch(match);
			InsertAt(match.Index, instructions, moveLabelsAndBlocksToInserted ? _code[match.Index] : null);
		}

		/// <summary>
		///     <para xml:lang="en">Inserts instructions immediately after a matched span.</para>
		///     <para xml:lang="zh-CN">在已匹配区间后插入指令。</para>
		/// </summary>
		public void InsertAfter(HarmonyIlMatch match, IEnumerable<CodeInstruction> instructions)
		{
			ValidateMatch(match);
			InsertAt(match.EndExclusive, instructions, null);
		}

		/// <summary>
		///     <para xml:lang="en">Inserts before the first matched pattern and returns a rewrite report.</para>
		///     <para xml:lang="zh-CN">在第一个匹配模式前插入并返回改写报告。</para>
		/// </summary>
		public HarmonyIlRewriteReport TryInsertBeforeFirst(string operation, HarmonyIlPattern pattern, IEnumerable<CodeInstruction> instructions, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null, bool moveLabelsAndBlocksToInserted = false)
		{
			return TryInsertAroundFirst(operation, pattern, instructions, insertAfter: false, alreadySatisfied, moveLabelsAndBlocksToInserted);
		}

		/// <summary>
		///     <para xml:lang="en">Inserts after the first matched pattern and returns a rewrite report.</para>
		///     <para xml:lang="zh-CN">在第一个匹配模式后插入并返回改写报告。</para>
		/// </summary>
		public HarmonyIlRewriteReport TryInsertAfterFirst(string operation, HarmonyIlPattern pattern, IEnumerable<CodeInstruction> instructions, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null)
		{
			return TryInsertAroundFirst(operation, pattern, instructions, insertAfter: true, alreadySatisfied);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Replaces a matched span with new instructions. For a non-empty replacement, labels and exception
		///         blocks on the first replaced instruction move to the first replacement instruction.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         用新指令替换已匹配区间。替换指令非空时，第一条被替换指令上的标签和异常块会转移到
		///         第一条替换指令。
		///     </para>
		/// </summary>
		/// <param name="match">
		///     <para xml:lang="en">The non-empty span to replace.</para>
		///     <para xml:lang="zh-CN">要替换的非空区间。</para>
		/// </param>
		/// <param name="replacement">
		///     <para xml:lang="en">The replacement instructions.</para>
		///     <para xml:lang="zh-CN">替换指令。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="replacement" /> is <see langword="null" />.</para>
		///     <para xml:lang="zh-CN"><paramref name="replacement" /> 为 <see langword="null" />。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentOutOfRangeException">
		///     <para xml:lang="en"><paramref name="match" /> is outside the current instruction list or is empty.</para>
		///     <para xml:lang="zh-CN"><paramref name="match" /> 超出当前指令列表范围或为空。</para>
		/// </exception>
		/// <exception cref="T:System.InvalidOperationException">
		///     <para xml:lang="en">
		///         The span contains control-flow metadata that cannot be preserved, or an empty replacement would
		///         remove metadata from its first instruction.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         区间包含无法保留的控制流元数据，或空替换会移除其第一条指令上的元数据。
		///     </para>
		/// </exception>
		public void Replace(HarmonyIlMatch match, IEnumerable<CodeInstruction> replacement)
		{
			ValidateMatch(match);
			ArgumentNullException.ThrowIfNull(replacement, "replacement");
			EnsureSafeToReplace(match);
			List<CodeInstruction> list = replacement.ToList();
			if (list.Count == 0 && HarmonyIl.HasMetadata(_code[match.Index]))
			{
				throw new InvalidOperationException("Cannot remove a replacement span whose first instruction has labels or exception blocks.");
			}
			if (list.Count > 0)
			{
				HarmonyIl.MoveMetadataToFirst(_code[match.Index], list);
			}
			_code.RemoveRange(match.Index, match.Length);
			_code.InsertRange(match.Index, list);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Replaces the first span matched by <paramref name="pattern" /> and reports the rewrite result.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         替换 <paramref name="pattern" /> 匹配的第一个区间，并报告改写结果。
		///     </para>
		/// </summary>
		/// <param name="operation">
		///     <para xml:lang="en">The operation name recorded in the report.</para>
		///     <para xml:lang="zh-CN">记录在报告中的操作名称。</para>
		/// </param>
		/// <param name="pattern">
		///     <para xml:lang="en">The pattern used to find replacement spans.</para>
		///     <para xml:lang="zh-CN">用于查找替换区间的模式。</para>
		/// </param>
		/// <param name="replacement">
		///     <para xml:lang="en">The instructions used to replace the first matching span.</para>
		///     <para xml:lang="zh-CN">用于替换第一个匹配区间的指令。</para>
		/// </param>
		/// <param name="alreadySatisfied">
		///     <para xml:lang="en">An optional predicate that detects an already-applied rewrite.</para>
		///     <para xml:lang="zh-CN">用于检测改写是否已经应用的可选谓词。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A report describing the matches and whether a replacement was applied.</para>
		///     <para xml:lang="zh-CN">描述匹配情况及是否应用替换的报告。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en"><paramref name="operation" /> is empty or consists only of white-space characters.</para>
		///     <para xml:lang="zh-CN"><paramref name="operation" /> 为空或仅包含空白字符。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">
		///         <paramref name="operation" /> or <paramref name="pattern" /> is <see langword="null" />, or a match
		///         is found and <paramref name="replacement" /> is <see langword="null" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         <paramref name="operation" /> 或 <paramref name="pattern" /> 为 <see langword="null" />，
		///         或找到匹配项时 <paramref name="replacement" /> 为 <see langword="null" />。
		///     </para>
		/// </exception>
		/// <exception cref="T:System.InvalidOperationException">
		///     <para xml:lang="en">
		///         The matched span contains control-flow metadata that cannot be preserved, or an empty replacement
		///         would remove metadata from its first instruction.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         匹配区间包含无法保留的控制流元数据，或空替换会移除其第一条指令上的元数据。
		///     </para>
		/// </exception>
		public HarmonyIlRewriteReport TryReplaceFirst(string operation, HarmonyIlPattern pattern, IEnumerable<CodeInstruction> replacement, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(operation, "operation");
			ArgumentNullException.ThrowIfNull(pattern, "pattern");
			int count = _code.Count;
			if (alreadySatisfied != null && alreadySatisfied(_code))
			{
				return new HarmonyIlRewriteReport(operation, 0, 0, count, count, AlreadySatisfied: true);
			}
			IReadOnlyList<HarmonyIlMatch> readOnlyList = pattern.FindAll(_code);
			if (readOnlyList.Count == 0)
			{
				return NewReport(operation, Array.Empty<int>(), Array.Empty<int>(), count, alreadySatisfied);
			}
			HarmonyIlMatch match = readOnlyList[0];
			Replace(match, replacement);
			return new HarmonyIlRewriteReport(operation, readOnlyList.Count, 1, count, _code.Count, AlreadySatisfied: false, MatchIndexes(readOnlyList), new <>z__ReadOnlySingleElementList<int>(match.Index));
		}

		/// <summary>
		///     <para xml:lang="en">Replaces every instruction whose site predicate matches.</para>
		///     <para xml:lang="zh-CN">替换每个满足站点谓词的指令。</para>
		/// </summary>
		public int ReplaceEach(Func<IReadOnlyList<CodeInstruction>, int, bool> isMatch, Func<IReadOnlyList<CodeInstruction>, int, IReadOnlyList<CodeInstruction>> buildReplacement)
		{
			return ReplaceEach("Harmony IL replace-each", isMatch, buildReplacement).Applied;
		}

		/// <summary>
		///     <para xml:lang="en">Replaces every instruction whose site predicate matches and returns a rewrite report.</para>
		///     <para xml:lang="zh-CN">替换每个满足站点谓词的指令并返回改写报告。</para>
		/// </summary>
		public HarmonyIlRewriteReport ReplaceEach(string operation, Func<IReadOnlyList<CodeInstruction>, int, bool> isMatch, Func<IReadOnlyList<CodeInstruction>, int, IReadOnlyList<CodeInstruction>> buildReplacement, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(operation, "operation");
			ArgumentNullException.ThrowIfNull(isMatch, "isMatch");
			ArgumentNullException.ThrowIfNull(buildReplacement, "buildReplacement");
			int count = _code.Count;
			List<int> list = new List<int>();
			List<int> list2 = new List<int>();
			for (int i = 0; i < _code.Count; i++)
			{
				if (isMatch(_code, i))
				{
					list.Add(i);
					List<CodeInstruction> list3 = buildReplacement(_code, i).ToList();
					if (list3.Count != 0)
					{
						list2.Add(i);
						HarmonyIl.MoveMetadataToFirst(_code[i], list3);
						_code.RemoveAt(i);
						_code.InsertRange(i, list3);
						i += list3.Count - 1;
					}
				}
			}
			return NewReport(operation, list, list2, count, alreadySatisfied);
		}

		/// <summary>
		///     <para xml:lang="en">Redirects call/callvirt instructions using <paramref name="resolveReplacement" />.</para>
		///     <para xml:lang="zh-CN">使用 <paramref name="resolveReplacement" /> 重定向 call/callvirt 指令。</para>
		/// </summary>
		public int RedirectCalls(Func<MethodInfo, MethodInfo?> resolveReplacement)
		{
			return RedirectCalls("Harmony IL redirect-calls", resolveReplacement).Applied;
		}

		/// <summary>
		///     <para xml:lang="en">Redirects call/callvirt instructions and returns a rewrite report.</para>
		///     <para xml:lang="zh-CN">重定向 call/callvirt 指令并返回改写报告。</para>
		/// </summary>
		public HarmonyIlRewriteReport RedirectCalls(string operation, Func<MethodInfo, MethodInfo?> resolveReplacement, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(operation, "operation");
			ArgumentNullException.ThrowIfNull(resolveReplacement, "resolveReplacement");
			int count = _code.Count;
			List<int> list = new List<int>();
			List<int> list2 = new List<int>();
			for (int i = 0; i < _code.Count; i++)
			{
				CodeInstruction val = _code[i];
				if ((!(val.opcode != OpCodes.Call) || !(val.opcode != OpCodes.Callvirt)) && val.operand is MethodInfo arg)
				{
					MethodInfo methodInfo = resolveReplacement(arg);
					if (!(methodInfo == null))
					{
						list.Add(i);
						list2.Add(i);
						val.opcode = OpCodes.Call;
						val.operand = methodInfo;
					}
				}
			}
			return NewReport(operation, list, list2, count, alreadySatisfied);
		}

		/// <summary>
		///     <para xml:lang="en">Inserts instructions before the first ret opcode.</para>
		///     <para xml:lang="zh-CN">在第一条 ret 指令前插入指令。</para>
		/// </summary>
		public bool TryInsertBeforeFirstRet(IReadOnlyList<CodeInstruction> prefix, bool moveLabelsAndBlocksToInserted = false)
		{
			return InsertBeforeFirstRet("Harmony IL insert-before-ret", prefix, null, moveLabelsAndBlocksToInserted).Applied > 0;
		}

		/// <summary>
		///     <para xml:lang="en">Inserts instructions before the first ret opcode and returns a rewrite report.</para>
		///     <para xml:lang="zh-CN">在第一条 ret 指令前插入指令并返回改写报告。</para>
		/// </summary>
		public HarmonyIlRewriteReport InsertBeforeFirstRet(string operation, IReadOnlyList<CodeInstruction> prefix, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null, bool moveLabelsAndBlocksToInserted = false)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(operation, "operation");
			ArgumentNullException.ThrowIfNull(prefix, "prefix");
			int count = _code.Count;
			if (prefix.Count == 0)
			{
				return NewReport(operation, Array.Empty<int>(), Array.Empty<int>(), count, alreadySatisfied);
			}
			List<int> list = new List<int>();
			for (int i = 0; i < _code.Count; i++)
			{
				if (!(_code[i].opcode != OpCodes.Ret))
				{
					list.Add(i);
					InsertAt(i, prefix, moveLabelsAndBlocksToInserted ? _code[i] : null);
					return new HarmonyIlRewriteReport(operation, list.Count, 1, count, _code.Count, AlreadySatisfied: false, list, new <>z__ReadOnlySingleElementList<int>(i));
				}
			}
			return NewReport(operation, list, Array.Empty<int>(), count, alreadySatisfied);
		}

		/// <summary>
		///     <para xml:lang="en">Inserts instructions before every ret opcode and returns a rewrite report.</para>
		///     <para xml:lang="zh-CN">在每条 ret 指令前插入指令并返回改写报告。</para>
		/// </summary>
		public HarmonyIlRewriteReport InsertBeforeEachRet(string operation, IReadOnlyList<CodeInstruction> prefix, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null, bool moveLabelsAndBlocksToInserted = false)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(operation, "operation");
			ArgumentNullException.ThrowIfNull(prefix, "prefix");
			int count = _code.Count;
			if (prefix.Count == 0)
			{
				return NewReport(operation, Array.Empty<int>(), Array.Empty<int>(), count, alreadySatisfied);
			}
			List<int> list = new List<int>();
			List<int> list2 = new List<int>();
			for (int i = 0; i < _code.Count; i++)
			{
				if (!(_code[i].opcode != OpCodes.Ret))
				{
					list.Add(i);
					list2.Add(i);
					InsertAt(i, HarmonyIl.CloneAll(prefix), moveLabelsAndBlocksToInserted ? _code[i] : null);
					i += prefix.Count;
				}
			}
			return NewReport(operation, list, list2, count, alreadySatisfied);
		}

		/// <summary>
		///     <para xml:lang="en">Inserts instructions before the last ret opcode and returns a rewrite report.</para>
		///     <para xml:lang="zh-CN">在最后一条 ret 指令前插入指令并返回改写报告。</para>
		/// </summary>
		public HarmonyIlRewriteReport InsertBeforeLastRet(string operation, IReadOnlyList<CodeInstruction> prefix, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null, bool moveLabelsAndBlocksToInserted = false)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(operation, "operation");
			ArgumentNullException.ThrowIfNull(prefix, "prefix");
			int count = _code.Count;
			if (prefix.Count == 0)
			{
				return NewReport(operation, Array.Empty<int>(), Array.Empty<int>(), count, alreadySatisfied);
			}
			List<int> list = FindAll(HarmonyIl.IsRet(), operation).Items.Select((HarmonyIlMatch match) => match.Index).ToList();
			if (list.Count == 0)
			{
				return NewReport(operation, list, Array.Empty<int>(), count, alreadySatisfied);
			}
			int num = list[list.Count - 1];
			InsertAt(num, prefix, moveLabelsAndBlocksToInserted ? _code[num] : null);
			return new HarmonyIlRewriteReport(operation, list.Count, 1, count, _code.Count, AlreadySatisfied: false, list, new <>z__ReadOnlySingleElementList<int>(num));
		}

		/// <summary>
		///     <para xml:lang="en">Inserts instructions before the only ret opcode and returns a rewrite report.</para>
		///     <para xml:lang="zh-CN">在唯一一条 ret 指令前插入指令并返回改写报告。</para>
		/// </summary>
		public HarmonyIlRewriteReport InsertBeforeSingleRet(string operation, IReadOnlyList<CodeInstruction> prefix, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null, bool moveLabelsAndBlocksToInserted = false)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(operation, "operation");
			ArgumentNullException.ThrowIfNull(prefix, "prefix");
			int count = _code.Count;
			if (prefix.Count == 0)
			{
				return NewReport(operation, Array.Empty<int>(), Array.Empty<int>(), count, alreadySatisfied);
			}
			HarmonyIlMatches harmonyIlMatches = FindAll(HarmonyIl.IsRet(), operation);
			HarmonyIlMatch harmonyIlMatch = harmonyIlMatches.RequireSingle();
			InsertAt(harmonyIlMatch.Index, prefix, moveLabelsAndBlocksToInserted ? _code[harmonyIlMatch.Index] : null);
			int count2 = harmonyIlMatches.Count;
			int count3 = _code.Count;
			List<int> list = new List<int>();
			list.AddRange(harmonyIlMatches.Items.Select((HarmonyIlMatch match) => match.Index));
			return new HarmonyIlRewriteReport(operation, count2, 1, count, count3, AlreadySatisfied: false, new <>z__ReadOnlyList<int>(list), new <>z__ReadOnlySingleElementList<int>(harmonyIlMatch.Index));
		}

		/// <summary>
		///     <para xml:lang="en">Inserts instructions before the first call/callvirt to a method.</para>
		///     <para xml:lang="zh-CN">在第一次调用指定方法前插入指令。</para>
		/// </summary>
		public HarmonyIlRewriteReport InsertBeforeCall(string operation, MethodInfo method, IEnumerable<CodeInstruction> instructions, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null, bool moveLabelsAndBlocksToInserted = false)
		{
			ArgumentNullException.ThrowIfNull(method, "method");
			return TryInsertBeforeFirst(operation, HarmonyIlPattern.Sequence(HarmonyIl.IsCall(method)), instructions, alreadySatisfied, moveLabelsAndBlocksToInserted);
		}

		/// <summary>
		///     <para xml:lang="en">Inserts instructions after the first call/callvirt to a method.</para>
		///     <para xml:lang="zh-CN">在第一次调用指定方法后插入指令。</para>
		/// </summary>
		public HarmonyIlRewriteReport InsertAfterCall(string operation, MethodInfo method, IEnumerable<CodeInstruction> instructions, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null)
		{
			ArgumentNullException.ThrowIfNull(method, "method");
			return TryInsertAfterFirst(operation, HarmonyIlPattern.Sequence(HarmonyIl.IsCall(method)), instructions, alreadySatisfied);
		}

		/// <summary>
		///     <para xml:lang="en">Replaces calls to one method with calls to another method.</para>
		///     <para xml:lang="zh-CN">将一个方法调用替换为另一个方法调用。</para>
		/// </summary>
		public HarmonyIlRewriteReport ReplaceCall(string operation, MethodInfo fromMethod, MethodInfo toMethod, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null)
		{
			ArgumentNullException.ThrowIfNull(fromMethod, "fromMethod");
			ArgumentNullException.ThrowIfNull(toMethod, "toMethod");
			return RedirectCalls(operation, (MethodInfo called) => (!(called == fromMethod)) ? null : toMethod, alreadySatisfied);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Replaces every instruction that satisfies <paramref name="isMatch" /> with the supplied
		///         replacement instructions.
		///     </para>
		///     <para xml:lang="zh-CN">将每条满足 <paramref name="isMatch" /> 的指令替换为指定指令。</para>
		/// </summary>
		public HarmonyIlRewriteReport ReplaceInstructions(string operation, Func<CodeInstruction, bool> isMatch, IEnumerable<CodeInstruction> replacement, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(operation, "operation");
			ArgumentNullException.ThrowIfNull(isMatch, "isMatch");
			ArgumentNullException.ThrowIfNull(replacement, "replacement");
			List<CodeInstruction> template = replacement.ToList();
			return ReplaceEach(operation, (IReadOnlyList<CodeInstruction> code, int index) => isMatch(code[index]), (IReadOnlyList<CodeInstruction> _, int _) => HarmonyIl.CloneAll(template), alreadySatisfied);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Replaces every instruction that satisfies <paramref name="isMatch" /> using a per-instruction
		///         replacement builder.
		///     </para>
		///     <para xml:lang="zh-CN">使用逐指令替换构造器替换每条满足 <paramref name="isMatch" /> 的指令。</para>
		/// </summary>
		public HarmonyIlRewriteReport ReplaceInstructions(string operation, Func<CodeInstruction, bool> isMatch, Func<CodeInstruction, IReadOnlyList<CodeInstruction>> buildReplacement, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(operation, "operation");
			ArgumentNullException.ThrowIfNull(isMatch, "isMatch");
			ArgumentNullException.ThrowIfNull(buildReplacement, "buildReplacement");
			return ReplaceEach(operation, (IReadOnlyList<CodeInstruction> code, int index) => isMatch(code[index]), (IReadOnlyList<CodeInstruction> code, int index) => buildReplacement(code[index]), alreadySatisfied);
		}

		private HarmonyIlRewriteReport TryInsertAroundFirst(string operation, HarmonyIlPattern pattern, IEnumerable<CodeInstruction> instructions, bool insertAfter, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied = null, bool moveLabelsAndBlocksToInserted = false)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(operation, "operation");
			ArgumentNullException.ThrowIfNull(pattern, "pattern");
			int count = _code.Count;
			if (alreadySatisfied != null && alreadySatisfied(_code))
			{
				return new HarmonyIlRewriteReport(operation, 0, 0, count, count, AlreadySatisfied: true);
			}
			IReadOnlyList<HarmonyIlMatch> readOnlyList = pattern.FindAll(_code);
			if (readOnlyList.Count == 0)
			{
				return NewReport(operation, Array.Empty<int>(), Array.Empty<int>(), count, alreadySatisfied);
			}
			HarmonyIlMatch match = readOnlyList[0];
			if (insertAfter)
			{
				InsertAfter(match, instructions);
			}
			else
			{
				InsertBefore(match, instructions, moveLabelsAndBlocksToInserted);
			}
			return new HarmonyIlRewriteReport(operation, readOnlyList.Count, 1, count, _code.Count, AlreadySatisfied: false, MatchIndexes(readOnlyList), new <>z__ReadOnlySingleElementList<int>(match.Index));
		}

		private HarmonyIlRewriteReport NewReport(string operation, IReadOnlyList<int> matchedIndexes, IReadOnlyList<int> appliedIndexes, int before, Func<IReadOnlyList<CodeInstruction>, bool>? alreadySatisfied)
		{
			return new HarmonyIlRewriteReport(operation, matchedIndexes.Count, appliedIndexes.Count, before, _code.Count, appliedIndexes.Count == 0 && (alreadySatisfied?.Invoke(_code) ?? false), matchedIndexes, appliedIndexes);
		}

		private static int[] MatchIndexes(IReadOnlyList<HarmonyIlMatch> matches)
		{
			return matches.Select((HarmonyIlMatch match) => match.Index).ToArray();
		}

		private void InsertAt(int index, IEnumerable<CodeInstruction> instructions, CodeInstruction? metadataSource)
		{
			ArgumentNullException.ThrowIfNull(instructions, "instructions");
			if (index < 0 || index > _code.Count)
			{
				throw new ArgumentOutOfRangeException("index");
			}
			List<CodeInstruction> list = instructions.ToList();
			if (list.Count != 0)
			{
				if (metadataSource != null)
				{
					HarmonyIl.MoveMetadataToFirst(metadataSource, list);
				}
				_code.InsertRange(index, list);
			}
		}

		private void ValidateMatch(HarmonyIlMatch match)
		{
			if (match.Index < 0 || match.Length <= 0 || match.EndExclusive > _code.Count)
			{
				throw new ArgumentOutOfRangeException("match", $"Invalid IL match span index={match.Index}, length={match.Length}, codeCount={_code.Count}.");
			}
		}

		private void EnsureSafeToReplace(HarmonyIlMatch match)
		{
			if (HarmonyIlValidation.CanReplaceSpan(_code, match, out string reason))
			{
				return;
			}
			throw new InvalidOperationException(reason);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Result metadata for an IL rewrite operation.</para>
	///     <para xml:lang="zh-CN">IL 改写操作的结果元数据。</para>
	/// </summary>
	public readonly record struct HarmonyIlRewriteReport(string Operation, int Matches, int Applied, int BeforeCount, int AfterCount, bool AlreadySatisfied = false, IReadOnlyList<int>? MatchedIndexes = null, IReadOnlyList<int>? AppliedIndexes = null)
	{
		/// <summary>
		///     <para xml:lang="en">True when this operation emitted a changed instruction list.</para>
		///     <para xml:lang="zh-CN">当此操作实际改写了指令列表时为 true。</para>
		/// </summary>
		public bool Changed => Applied > 0;

		/// <summary>
		///     <para xml:lang="en">
		///         True when this operation either changed IL or detected that the requested IL is already
		///         present.
		///     </para>
		///     <para xml:lang="zh-CN">当此操作实际改写了 IL，或检测到目标 IL 已存在时为 true。</para>
		/// </summary>
		public bool Succeeded
		{
			get
			{
				if (!Changed)
				{
					return AlreadySatisfied;
				}
				return true;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Throws when the operation did not change IL and did not detect equivalent existing IL.</para>
		///     <para xml:lang="zh-CN">当操作既未改写 IL，也未检测到等价已有 IL 时抛出异常。</para>
		/// </summary>
		public void RequireSucceeded()
		{
			if (Succeeded)
			{
				return;
			}
			throw new InvalidOperationException($"{Operation} did not match the target IL. before={BeforeCount}, after={AfterCount}, matchedIndexes={FormatIndexes(MatchedIndexes)}.");
		}

		/// <summary>
		///     <para xml:lang="en">Throws when the number of applied rewrites is outside the expected range.</para>
		///     <para xml:lang="zh-CN">当实际改写次数不在预期范围内时抛出异常。</para>
		/// </summary>
		public void RequireApplied(int min = 1, int? max = null)
		{
			if (Applied >= min && (!max.HasValue || Applied <= max.Value))
			{
				return;
			}
			string value = max?.ToString() ?? "unbounded";
			throw new InvalidOperationException($"{Operation} applied {Applied} rewrite(s), expected range [{min}, {value}]. matches={Matches}, alreadySatisfied={AlreadySatisfied}, before={BeforeCount}, after={AfterCount}, matchedIndexes={FormatIndexes(MatchedIndexes)}, appliedIndexes={FormatIndexes(AppliedIndexes)}.");
		}

		/// <summary>
		///     <para xml:lang="en">Throws when the number of applied rewrites is not exactly <paramref name="count" />.</para>
		///     <para xml:lang="zh-CN">当实际改写次数不等于 <paramref name="count" /> 时抛出异常。</para>
		/// </summary>
		public void RequireExactly(int count)
		{
			RequireApplied(count, count);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Requires an exact target-site and rewrite count, or accepts an equivalent rewrite that was
		///         already present.
		///     </para>
		///     <para xml:lang="zh-CN">要求精确的目标点与改写次数，或接受已经存在的等价改写。</para>
		/// </summary>
		public void RequireExactSitesOrAlreadySatisfied(int count = 1)
		{
			if (!AlreadySatisfied)
			{
				if (Matches != count)
				{
					throw new InvalidOperationException($"{Operation} matched {Matches} target site(s), expected exactly {count}. {Describe()}");
				}
				RequireExactly(count);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Returns a compact diagnostic string.</para>
		///     <para xml:lang="zh-CN">返回紧凑诊断字符串。</para>
		/// </summary>
		public string Describe()
		{
			return $"{Operation}: matches={Matches}, applied={Applied}, alreadySatisfied={AlreadySatisfied}, before={BeforeCount}, after={AfterCount}, matchedIndexes={FormatIndexes(MatchedIndexes)}, appliedIndexes={FormatIndexes(AppliedIndexes)}";
		}

		private static string FormatIndexes(IReadOnlyList<int>? indexes)
		{
			if (indexes != null)
			{
				return "[" + string.Join(", ", indexes) + "]";
			}
			return "[]";
		}
	}
	/// <summary>
	///     <para xml:lang="en">One structural IL validation issue.</para>
	///     <para xml:lang="zh-CN">一个结构性 IL 验证问题。</para>
	/// </summary>
	public readonly record struct HarmonyIlValidationIssue(int Index, string Message);
	/// <summary>
	///     <para xml:lang="en">Structural validation report for a Harmony instruction list.</para>
	///     <para xml:lang="zh-CN">Harmony 指令列表的结构性验证报告。</para>
	/// </summary>
	public sealed class HarmonyIlValidationReport
	{
		/// <summary>
		///     <para xml:lang="en">Operation name supplied by the caller.</para>
		///     <para xml:lang="zh-CN">调用方提供的操作名称。</para>
		/// </summary>
		public string Operation { get; }

		/// <summary>
		///     <para xml:lang="en">Validation issues found in the instruction list.</para>
		///     <para xml:lang="zh-CN">在指令列表中发现的验证问题。</para>
		/// </summary>
		public IReadOnlyList<HarmonyIlValidationIssue> Issues { get; }

		/// <summary>
		///     <para xml:lang="en">True when no structural issues were found.</para>
		///     <para xml:lang="zh-CN">未发现结构性问题时为 true。</para>
		/// </summary>
		public bool IsValid => Issues.Count == 0;

		internal HarmonyIlValidationReport(string operation, IReadOnlyList<HarmonyIlValidationIssue> issues)
		{
			Operation = operation;
			Issues = issues;
		}

		/// <summary>
		///     <para xml:lang="en">Throws when the report contains structural issues.</para>
		///     <para xml:lang="zh-CN">当报告包含结构性问题时抛出异常。</para>
		/// </summary>
		public void ThrowIfInvalid()
		{
			if (IsValid)
			{
				return;
			}
			string text = string.Join("; ", from issue in Issues.Take(5)
				select $"#{issue.Index}: {issue.Message}");
			throw new InvalidOperationException(Operation + " produced invalid IL: " + text);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Structural checks for Harmony instruction lists produced by wrapper-based transpilers.</para>
	///     <para xml:lang="zh-CN">面向包装式转译器输出的 Harmony 指令列表结构检查。</para>
	/// </summary>
	public static class HarmonyIlValidation
	{
		/// <summary>
		///     <para xml:lang="en">Validates branch labels and common reflection operands.</para>
		///     <para xml:lang="zh-CN">验证分支标签与常见反射操作数。</para>
		/// </summary>
		public static HarmonyIlValidationReport Validate(IReadOnlyList<CodeInstruction> code, string operation = "Harmony IL rewrite")
		{
			ArgumentNullException.ThrowIfNull(code, "code");
			List<HarmonyIlValidationIssue> list = new List<HarmonyIlValidationIssue>();
			HashSet<Label> hashSet = new HashSet<Label>();
			for (int i = 0; i < code.Count; i++)
			{
				if (code[i] == null)
				{
					list.Add(new HarmonyIlValidationIssue(i, "Instruction is null."));
					continue;
				}
				foreach (Label label in code[i].labels)
				{
					hashSet.Add(label);
				}
			}
			for (int j = 0; j < code.Count; j++)
			{
				CodeInstruction val = code[j];
				if (val != null)
				{
					ValidateOperand(j, val, hashSet, list);
				}
			}
			return new HarmonyIlValidationReport(operation, list);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns true when a matched span can be replaced without moving labels or exception blocks from
		///         the interior of the span.
		///     </para>
		///     <para xml:lang="zh-CN">当匹配区间可在不移动其内部标签或异常块的情况下安全替换时返回 true。</para>
		/// </summary>
		public static bool CanReplaceSpan(IReadOnlyList<CodeInstruction> code, HarmonyIlMatch match, out string? reason)
		{
			ArgumentNullException.ThrowIfNull(code, "code");
			if (match.Index < 0 || match.Length <= 0 || match.EndExclusive > code.Count)
			{
				reason = $"Invalid match span index={match.Index}, length={match.Length}, codeCount={code.Count}.";
				return false;
			}
			for (int i = match.Index + 1; i < match.EndExclusive; i++)
			{
				if (HarmonyIl.HasMetadata(code[i]))
				{
					reason = $"Instruction #{i} inside the replacement span has labels or exception blocks. " + "Use a narrower anchor, insert around the span, or rewrite the pattern to preserve control-flow metadata.";
					return false;
				}
			}
			reason = null;
			return true;
		}

		private static void ValidateOperand(int index, CodeInstruction instruction, HashSet<Label> definedLabels, List<HarmonyIlValidationIssue> issues)
		{
			OpCode opcode = instruction.opcode;
			if (opcode == OpCodes.Call && !(instruction.operand is MethodBase))
			{
				issues.Add(new HarmonyIlValidationIssue(index, "call operand must be MethodBase."));
				return;
			}
			if (opcode == OpCodes.Callvirt && !(instruction.operand is MethodInfo))
			{
				issues.Add(new HarmonyIlValidationIssue(index, "callvirt operand must be MethodInfo."));
				return;
			}
			if (opcode == OpCodes.Newobj && !(instruction.operand is ConstructorInfo))
			{
				issues.Add(new HarmonyIlValidationIssue(index, "newobj operand must be ConstructorInfo."));
				return;
			}
			if ((opcode == OpCodes.Ldfld || opcode == OpCodes.Ldflda || opcode == OpCodes.Ldsfld || opcode == OpCodes.Stfld || opcode == OpCodes.Stsfld) && !(instruction.operand is FieldInfo))
			{
				issues.Add(new HarmonyIlValidationIssue(index, $"{opcode} operand must be FieldInfo."));
				return;
			}
			if (opcode == OpCodes.Ldstr && !(instruction.operand is string))
			{
				issues.Add(new HarmonyIlValidationIssue(index, "ldstr operand must be string."));
				return;
			}
			if (opcode == OpCodes.Ldc_I4 && !(instruction.operand is int))
			{
				issues.Add(new HarmonyIlValidationIssue(index, "ldc.i4 operand must be int."));
				return;
			}
			if (opcode == OpCodes.Ldc_I4_S && !(instruction.operand is sbyte))
			{
				issues.Add(new HarmonyIlValidationIssue(index, "ldc.i4.s operand must be sbyte."));
				return;
			}
			switch (opcode.OperandType)
			{
			case OperandType.InlineBrTarget:
			case OperandType.ShortInlineBrTarget:
				ValidateBranchTarget(index, instruction.operand, definedLabels, issues);
				break;
			case OperandType.InlineSwitch:
				ValidateSwitchTargets(index, instruction.operand, definedLabels, issues);
				break;
			}
		}

		private static void ValidateBranchTarget(int index, object? operand, HashSet<Label> definedLabels, List<HarmonyIlValidationIssue> issues)
		{
			if (!(operand is Label item))
			{
				issues.Add(new HarmonyIlValidationIssue(index, "Branch operand must be a Label."));
			}
			else if (!definedLabels.Contains(item))
			{
				issues.Add(new HarmonyIlValidationIssue(index, "Branch target label is not attached to any instruction."));
			}
		}

		private static void ValidateSwitchTargets(int index, object? operand, HashSet<Label> definedLabels, List<HarmonyIlValidationIssue> issues)
		{
			if (!(operand is Label[] source))
			{
				issues.Add(new HarmonyIlValidationIssue(index, "switch operand must be a Label array."));
				return;
			}
			issues.AddRange(from label in source
				where !definedLabels.Contains(label)
				select new HarmonyIlValidationIssue(index, "Switch target label is not attached to any instruction."));
		}
	}
}
namespace STS2RitsuLib.Updates
{
	/// <summary>
	///     <para xml:lang="en">
	///         Schedules registered automatic update checks and defers their execution while the player is in
	///         combat.
	///     </para>
	///     <para xml:lang="zh-CN">调度已注册的自动更新检查，并在玩家处于战斗中时延后执行。</para>
	/// </summary>
	internal static class AutomaticUpdateCheckScheduler
	{
		private sealed class Registration(ScheduledCheck check) : IDisposable
		{
			private bool _disposed;

			public void Dispose()
			{
				if (_disposed)
				{
					return;
				}
				_disposed = true;
				using (SyncRoot.EnterScope())
				{
					if (Checks.TryGetValue(check.Id, out ScheduledCheck value) && (object)value == check)
					{
						Checks.Remove(check.Id);
					}
				}
			}
		}

		private sealed record ScheduledCheck(string Id, string DisplayName, Func<bool> IsEnabled, Func<CancellationToken, Task> CheckAsync, int Order);

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, ScheduledCheck> Checks = new Dictionary<string, ScheduledCheck>(StringComparer.Ordinal);

		private static int _cycleRunning;

		private static int? _deferredFromOrder;

		private static int _nextOrder;

		private static bool _initialized;

		private static bool _initializing;

		private static bool _loopStarted;

		internal static IDisposable Register(string id, string displayName, Func<bool> isEnabled, Func<CancellationToken, Task> checkAsync)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentException.ThrowIfNullOrWhiteSpace(displayName, "displayName");
			ArgumentNullException.ThrowIfNull(isEnabled, "isEnabled");
			ArgumentNullException.ThrowIfNull(checkAsync, "checkAsync");
			Initialize();
			ScheduledCheck scheduledCheck = new ScheduledCheck(id.Trim(), displayName.Trim(), isEnabled, checkAsync, Interlocked.Increment(ref _nextOrder));
			using (SyncRoot.EnterScope())
			{
				Checks[scheduledCheck.Id] = scheduledCheck;
			}
			return new Registration(scheduledCheck);
		}

		private static void Initialize()
		{
			using (SyncRoot.EnterScope())
			{
				if (_initialized || _initializing)
				{
					return;
				}
				_initializing = true;
			}
			List<IDisposable> list = new List<IDisposable>();
			try
			{
				UpdateCheckSessionState.Initialize();
				list.Add(RitsuLibFramework.SubscribeLifecycle((Action<EssentialInitializationStartingEvent>)delegate
				{
					StartLoop("essential initialization starting");
				}, true));
				list.Add(RitsuLibFramework.SubscribeLifecycle((Action<MainMenuReadyEvent>)delegate
				{
					StartLoop("first main menu fallback");
				}, true));
				list.Add(RitsuLibFramework.SubscribeLifecycle((Action<MainMenuReadyEvent>)delegate
				{
					TryRunDeferredCycle();
				}, true));
				list.Add(RitsuLibFramework.SubscribeLifecycle((Action<RoomExitedEvent>)delegate
				{
					TryRunDeferredCycle();
				}, true));
				list.Add(RitsuLibFramework.SubscribeLifecycle((Action<RunEndedEvent>)delegate
				{
					TryRunDeferredCycle();
				}, true));
				using (SyncRoot.EnterScope())
				{
					_initialized = true;
				}
			}
			catch
			{
				for (int num = list.Count - 1; num >= 0; num--)
				{
					list[num].Dispose();
				}
				throw;
			}
			finally
			{
				using (SyncRoot.EnterScope())
				{
					_initializing = false;
				}
			}
		}

		internal static void StartForGameStartupError()
		{
			StartLoop("game startup error");
		}

		private static void StartLoop(string trigger)
		{
			using (SyncRoot.EnterScope())
			{
				if (_loopStarted)
				{
					return;
				}
				_loopStarted = true;
			}
			RitsuLibFramework.Logger.Info("[UpdateCheck] Automatic scheduler started: " + trigger + ".", 1);
			Task.Run((Func<Task?>)RunLoopAsync);
		}

		private static async Task RunLoopAsync()
		{
			while (true)
			{
				await TryRunCycleAsync("scheduled").ConfigureAwait(continueOnCapturedContext: false);
				TimeSpan updateCheckInterval = RitsuLibSettingsStore.GetUpdateCheckInterval();
				try
				{
					await Task.Delay(updateCheckInterval).ConfigureAwait(continueOnCapturedContext: false);
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn("[UpdateCheck] Automatic scheduler delay failed: " + ex.Message, 1);
				}
			}
		}

		private static async Task TryRunCycleAsync(string source)
		{
			if (ShouldDeferForCombat())
			{
				RequestDeferredCycle(source + " cycle reached a combat room", 0);
				return;
			}
			if (Interlocked.Exchange(ref _cycleRunning, 1) != 0)
			{
				RequestDeferredCycle(source + " cycle overlapped another update check cycle", 0);
				return;
			}
			try
			{
				await RunCycleCoreAsync(0).ConfigureAwait(continueOnCapturedContext: false);
			}
			finally
			{
				Interlocked.Exchange(ref _cycleRunning, 0);
				TryRunDeferredCycle();
			}
		}

		private static async Task RunCycleCoreAsync(int resumeFromOrder)
		{
			bool deferInCombat = RitsuLibSettingsStore.ShouldDeferUpdateChecksInCombat();
			ScheduledCheck[] array;
			using (SyncRoot.EnterScope())
			{
				array = (from scheduledCheck in Checks.Values
					where scheduledCheck.Order >= resumeFromOrder
					orderby scheduledCheck.Order
					select scheduledCheck).ToArray();
			}
			ScheduledCheck[] array2 = array;
			foreach (ScheduledCheck check in array2)
			{
				if (deferInCombat && UpdateCheckSessionState.IsCombatRoomActive)
				{
					RequestDeferredCycle("entered a combat room during update check cycle", check.Order);
					break;
				}
				try
				{
					if (check.IsEnabled())
					{
						RitsuLibFramework.Logger.Debug("[UpdateCheck] Running automatic check: " + check.DisplayName + ".", 1);
						await check.CheckAsync(CancellationToken.None).ConfigureAwait(continueOnCapturedContext: false);
					}
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn("[UpdateCheck] Automatic check '" + check.DisplayName + "' failed: " + ex.Message, 1);
				}
			}
		}

		private static bool ShouldDeferForCombat()
		{
			if (RitsuLibSettingsStore.ShouldDeferUpdateChecksInCombat())
			{
				return UpdateCheckSessionState.IsCombatRoomActive;
			}
			return false;
		}

		private static void RequestDeferredCycle(string reason, int resumeFromOrder)
		{
			using (SyncRoot.EnterScope())
			{
				int? deferredFromOrder = _deferredFromOrder;
				int value;
				if (deferredFromOrder.HasValue)
				{
					int valueOrDefault = deferredFromOrder.GetValueOrDefault();
					value = Math.Min(valueOrDefault, resumeFromOrder);
				}
				else
				{
					value = resumeFromOrder;
				}
				_deferredFromOrder = value;
			}
			RitsuLibFramework.Logger.Debug("[UpdateCheck] Automatic check cycle deferred: " + reason + ".", 1);
		}

		private static void TryRunDeferredCycle()
		{
			int resumeFromOrder;
			using (SyncRoot.EnterScope())
			{
				int? deferredFromOrder = _deferredFromOrder;
				if (!deferredFromOrder.HasValue)
				{
					return;
				}
				int valueOrDefault = deferredFromOrder.GetValueOrDefault();
				resumeFromOrder = valueOrDefault;
			}
			if (ShouldDeferForCombat() || Interlocked.CompareExchange(ref _cycleRunning, 1, 0) != 0)
			{
				return;
			}
			using (SyncRoot.EnterScope())
			{
				if (_deferredFromOrder == resumeFromOrder)
				{
					_deferredFromOrder = null;
				}
			}
			Task.Run(async delegate
			{
				try
				{
					RitsuLibFramework.Logger.Debug($"[UpdateCheck] Resuming deferred automatic check cycle from order {resumeFromOrder}.", 1);
					await RunCycleCoreAsync(resumeFromOrder).ConfigureAwait(continueOnCapturedContext: false);
				}
				finally
				{
					Interlocked.Exchange(ref _cycleRunning, 0);
					TryRunDeferredCycle();
				}
			});
		}
	}
	/// <summary>
	///     <para xml:lang="en">Checks self-hosted or mirrored release manifests for available mod updates.</para>
	///     <para xml:lang="zh-CN">检查自托管或镜像发布清单中是否有可用的模组更新。</para>
	/// </summary>
	public static class ModUpdateChecker
	{
		private sealed class NoopDisposable : IDisposable
		{
			public void Dispose()
			{
			}
		}

		private sealed class RegisteredSessionCheck(string key, IDisposable inner) : IDisposable
		{
			private bool _disposed;

			public void Dispose()
			{
				if (_disposed)
				{
					return;
				}
				_disposed = true;
				inner.Dispose();
				using (SessionLock.EnterScope())
				{
					ScheduledSessionChecks.Remove(key);
				}
			}
		}

		private const string ExpectedSchema = "ritsulib.update.v1";

		private const int MaxManifestBytes = 524288;

		private static readonly HttpClient Client = new HttpClient();

		private static readonly JsonSerializerOptions JsonOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

		private static readonly Lock SessionLock = new Lock();

		private static readonly HashSet<string> ScheduledSessionChecks = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a periodic automatic update check. Checks start before essential game initialization, and
		///         notifications are deferred until the main menu is active.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册周期性自动更新检查。检查会在游戏必要初始化之前开始，通知会延后到主菜单处于活动状态时显示。
		///     </para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">A disposable registration. Disposing it stops later automatic checks for this mod.</para>
		///     <para xml:lang="zh-CN">可释放的注册。释放后会停止该模组后续的自动检查。</para>
		/// </returns>
		public static IDisposable RegisterOnFirstMainMenu(ModUpdateCheckOptions options)
		{
			ValidateOptions(options);
			string key = NormalizeSessionKey(options.ModId);
			using (SessionLock.EnterScope())
			{
				if (!ScheduledSessionChecks.Add(key))
				{
					return new NoopDisposable();
				}
			}
			try
			{
				IDisposable inner = AutomaticUpdateCheckScheduler.Register("mod-update:" + key, options.DisplayName, () => true, (CancellationToken cancellationToken) => CheckAndToastAsync(options, showCompletionToast: false, deferToastToMainMenu: true, "mod-update:" + key, cancellationToken));
				return new RegisteredSessionCheck(key, inner);
			}
			catch
			{
				using (SessionLock.EnterScope())
				{
					ScheduledSessionChecks.Remove(key);
				}
				throw;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers a periodic update check using string URLs for the common call path.</para>
		///     <para xml:lang="zh-CN">使用字符串 URL 为常见调用路径注册周期性更新检查。</para>
		/// </summary>
		public static IDisposable RegisterOnFirstMainMenu(string modId, string displayName, string currentVersion, string manifestUrl, string? releasePageUrl = null)
		{
			return RegisterOnFirstMainMenu(ModUpdateCheckOptions.Create(modId, displayName, currentVersion, manifestUrl, releasePageUrl));
		}

		/// <summary>
		///     <para xml:lang="en">Runs the update check immediately without showing UI notifications.</para>
		///     <para xml:lang="zh-CN">立即运行更新检查，但不显示界面通知。</para>
		/// </summary>
		public static async Task<ModUpdateCheckResult> CheckAsync(ModUpdateCheckOptions options, CancellationToken cancellationToken = default(CancellationToken))
		{
			ValidateOptions(options);
			if (TryGetManagedSteamWorkshopItemId(options, out var itemId))
			{
				return new ModUpdateCheckResult(ModUpdateCheckStatus.Skipped, options.CurrentVersion, null, null, null, $"External update check skipped because this install is managed by Steam Workshop item {itemId}.");
			}
			if (ShouldSkipForSteamWorkshop(options))
			{
				return new ModUpdateCheckResult(ModUpdateCheckStatus.Skipped, options.CurrentVersion, null, null, null, "External update check skipped because this install is managed by Steam Workshop.");
			}
			if (!SimpleSemanticVersion.TryParse(options.CurrentVersion, out var currentVersion))
			{
				return new ModUpdateCheckResult(ModUpdateCheckStatus.InvalidData, options.CurrentVersion, null, null, null, "Current version is not a supported semantic version: " + options.CurrentVersion);
			}
			ModUpdateCheckManifest modUpdateCheckManifest;
			try
			{
				modUpdateCheckManifest = await FetchManifestAsync(options, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			}
			catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
			{
				throw;
			}
			catch (Exception ex2) when (((ex2 is HttpRequestException || ex2 is IOException || ex2 is TaskCanceledException || ex2 is OperationCanceledException) ? 1 : 0) != 0)
			{
				return new ModUpdateCheckResult(ModUpdateCheckStatus.RequestFailed, options.CurrentVersion, null, null, null, ex2.Message);
			}
			catch (JsonException ex3)
			{
				return new ModUpdateCheckResult(ModUpdateCheckStatus.InvalidData, options.CurrentVersion, null, null, null, "Update manifest JSON is invalid: " + ex3.Message);
			}
			if (modUpdateCheckManifest == null)
			{
				return new ModUpdateCheckResult(ModUpdateCheckStatus.InvalidData, options.CurrentVersion, null, null, null, "Update manifest is empty.");
			}
			if (!string.IsNullOrWhiteSpace(modUpdateCheckManifest.Schema) && !string.Equals(modUpdateCheckManifest.Schema.Trim(), "ritsulib.update.v1", StringComparison.Ordinal))
			{
				return new ModUpdateCheckResult(ModUpdateCheckStatus.InvalidData, options.CurrentVersion, null, null, null, "Unsupported update manifest schema: " + modUpdateCheckManifest.Schema);
			}
			if (string.IsNullOrWhiteSpace(modUpdateCheckManifest.LatestVersion) || !SimpleSemanticVersion.TryParse(modUpdateCheckManifest.LatestVersion, out var version))
			{
				return new ModUpdateCheckResult(ModUpdateCheckStatus.InvalidData, options.CurrentVersion, null, null, null, "Update manifest latest_version is missing or invalid.");
			}
			if (version.CompareTo(currentVersion) <= 0)
			{
				return new ModUpdateCheckResult(ModUpdateCheckStatus.UpToDate, options.CurrentVersion, modUpdateCheckManifest.LatestVersion);
			}
			Uri uri = ResolveReleasePageUri(options, modUpdateCheckManifest);
			if (uri == null)
			{
				return new ModUpdateCheckResult(ModUpdateCheckStatus.InvalidData, options.CurrentVersion, modUpdateCheckManifest.LatestVersion, null, null, "Update is available, but no release page URL was provided.");
			}
			return new ModUpdateCheckResult(ModUpdateCheckStatus.UpdateAvailable, options.CurrentVersion, modUpdateCheckManifest.LatestVersion, uri, BuildToastTitle(options, modUpdateCheckManifest), BuildToastMessage(options, modUpdateCheckManifest));
		}

		/// <summary>
		///     <para xml:lang="en">Runs the update check immediately from string URLs without showing UI notifications.</para>
		///     <para xml:lang="zh-CN">使用字符串 URL 立即运行更新检查，但不显示界面通知。</para>
		/// </summary>
		public static Task<ModUpdateCheckResult> CheckAsync(string modId, string displayName, string currentVersion, string manifestUrl, string? releasePageUrl = null, CancellationToken cancellationToken = default(CancellationToken))
		{
			return CheckAsync(ModUpdateCheckOptions.Create(modId, displayName, currentVersion, manifestUrl, releasePageUrl), cancellationToken);
		}

		/// <summary>
		///     <para xml:lang="en">Runs the update check immediately and shows a toast when a newer version is available.</para>
		///     <para xml:lang="zh-CN">立即运行更新检查；发现新版本时显示浮动通知。</para>
		/// </summary>
		public static Task<ModUpdateCheckResult> CheckAndToastAsync(ModUpdateCheckOptions options, bool showCompletionToast = false, CancellationToken cancellationToken = default(CancellationToken))
		{
			ValidateOptions(options);
			return CheckAndToastAsync(options, showCompletionToast, deferToastToMainMenu: false, null, cancellationToken);
		}

		private static async Task<ModUpdateCheckResult> CheckAndToastAsync(ModUpdateCheckOptions options, bool showCompletionToast, bool deferToastToMainMenu, string? notificationKey, CancellationToken cancellationToken)
		{
			if (TryGetManagedSteamWorkshopItemId(options, out var workshopItemId))
			{
				bool automatic = deferToastToMainMenu && !string.IsNullOrWhiteSpace(notificationKey);
				await SteamWorkshopUpdateCoordinator.CheckItemAsync(workshopItemId, automatic, deferToastToMainMenu, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				return new ModUpdateCheckResult(ModUpdateCheckStatus.Skipped, options.CurrentVersion, null, null, null, $"External update check skipped because this install is managed by Steam Workshop item {workshopItemId}; checked that Workshop item instead.");
			}
			ModUpdateCheckResult result = await CheckAsync(options, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			bool isAutomaticCheck = deferToastToMainMenu && !string.IsNullOrWhiteSpace(notificationKey);
			LogResult(options, result, isAutomaticCheck);
			if (result.Status != ModUpdateCheckStatus.UpdateAvailable || result.ReleasePageUri == null)
			{
				if (showCompletionToast)
				{
					ShowToast(deferToastToMainMenu, notificationKey, delegate
					{
						ShowCompletionToast(options, result);
					});
				}
				return result;
			}
			ShowToast(deferToastToMainMenu, notificationKey, delegate
			{
				ShowUpdateToastOnce(options, result, isAutomaticCheck);
			});
			return result;
		}

		/// <summary>
		///     <para xml:lang="en">Runs the update check from string URLs and shows a toast when a newer version is available.</para>
		///     <para xml:lang="zh-CN">使用字符串 URL 运行更新检查；发现新版本时显示浮动通知。</para>
		/// </summary>
		public static Task<ModUpdateCheckResult> CheckAndToastAsync(string modId, string displayName, string currentVersion, string manifestUrl, string? releasePageUrl = null, bool showCompletionToast = false, CancellationToken cancellationToken = default(CancellationToken))
		{
			return CheckAndToastAsync(ModUpdateCheckOptions.Create(modId, displayName, currentVersion, manifestUrl, releasePageUrl), showCompletionToast, cancellationToken);
		}

		private static async Task<ModUpdateCheckManifest?> FetchManifestAsync(ModUpdateCheckOptions options, CancellationToken cancellationToken)
		{
			using CancellationTokenSource timeout = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
			timeout.CancelAfter(options.Timeout);
			using HttpRequestMessage request = new HttpRequestMessage(HttpMethod.Get, options.ManifestUri);
			request.Headers.Accept.ParseAdd("application/json");
			request.Headers.UserAgent.ParseAdd("STS2-RitsuLib/0.5.18");
			if (options.Headers != null)
			{
				foreach (KeyValuePair<string, string> header in options.Headers)
				{
					request.Headers.TryAddWithoutValidation(header.Key, header.Value);
				}
			}
			using HttpResponseMessage response = await Client.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, timeout.Token).ConfigureAwait(continueOnCapturedContext: false);
			if (response.StatusCode == HttpStatusCode.NotModified)
			{
				return null;
			}
			response.EnsureSuccessStatusCode();
			long? contentLength = response.Content.Headers.ContentLength;
			if (contentLength.HasValue && contentLength.GetValueOrDefault() > 524288)
			{
				throw new JsonException($"Update manifest is too large: {contentLength} bytes.");
			}
			ModUpdateCheckManifest result;
			await using (Stream stream = await response.Content.ReadAsStreamAsync(timeout.Token).ConfigureAwait(continueOnCapturedContext: false))
			{
				result = JsonSerializer.Deserialize<ModUpdateCheckManifest>(await ReadManifestBytesAsync(stream, timeout.Token).ConfigureAwait(continueOnCapturedContext: false), JsonOptions);
			}
			return result;
		}

		private static async Task<byte[]> ReadManifestBytesAsync(Stream stream, CancellationToken cancellationToken)
		{
			byte[] buffer = new byte[8192];
			using MemoryStream content = new MemoryStream();
			while (true)
			{
				int num = await stream.ReadAsync(buffer.AsMemory(), cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (num == 0)
				{
					break;
				}
				if (content.Length + num > 524288)
				{
					throw new JsonException($"Update manifest is too large: more than {524288} bytes.");
				}
				content.Write(buffer, 0, num);
			}
			return content.ToArray();
		}

		private static Uri? ResolveReleasePageUri(ModUpdateCheckOptions options, ModUpdateCheckManifest manifest)
		{
			if (!string.IsNullOrWhiteSpace(manifest.ReleasePageUrl) && Uri.TryCreate(manifest.ReleasePageUrl.Trim(), UriKind.Absolute, out Uri result) && IsWebUri(result))
			{
				return result;
			}
			return options.ReleasePageUri;
		}

		private static string BuildToastMessage(ModUpdateCheckOptions options, ModUpdateCheckManifest manifest)
		{
			if (!string.IsNullOrWhiteSpace(options.ToastBody))
			{
				return FormatTemplate(options.ToastBody.Trim(), options, manifest);
			}
			ModUpdateCheckLocalizedText modUpdateCheckLocalizedText = ResolveLocalizedText(manifest);
			if (!string.IsNullOrWhiteSpace(modUpdateCheckLocalizedText?.Message))
			{
				return FormatTemplate(modUpdateCheckLocalizedText.Message.Trim(), options, manifest);
			}
			if (!string.IsNullOrWhiteSpace(manifest.Message))
			{
				return FormatTemplate(manifest.Message.Trim(), options, manifest);
			}
			return (string.IsNullOrWhiteSpace(manifest.LatestVersion) ? "a newer version" : ("version " + manifest.LatestVersion.Trim())) + " of " + options.DisplayName.Trim() + " is available. Click to open the release page.";
		}

		private static string BuildToastTitle(ModUpdateCheckOptions options, ModUpdateCheckManifest manifest)
		{
			if (!string.IsNullOrWhiteSpace(options.ToastTitle))
			{
				return FormatTemplate(options.ToastTitle.Trim(), options, manifest);
			}
			ModUpdateCheckLocalizedText modUpdateCheckLocalizedText = ResolveLocalizedText(manifest);
			if (!string.IsNullOrWhiteSpace(modUpdateCheckLocalizedText?.Title))
			{
				return FormatTemplate(modUpdateCheckLocalizedText.Title.Trim(), options, manifest);
			}
			if (string.IsNullOrWhiteSpace(manifest.Title))
			{
				return options.DisplayName.Trim() + " update available";
			}
			return FormatTemplate(manifest.Title.Trim(), options, manifest);
		}

		private static string FormatTemplate(string template, ModUpdateCheckOptions options, ModUpdateCheckManifest manifest)
		{
			return template.Replace("{display_name}", options.DisplayName.Trim(), StringComparison.OrdinalIgnoreCase).Replace("{current_version}", options.CurrentVersion.Trim(), StringComparison.OrdinalIgnoreCase).Replace("{latest_version}", manifest.LatestVersion?.Trim() ?? "", StringComparison.OrdinalIgnoreCase);
		}

		private static void ShowUpdateToast(ModUpdateCheckOptions options, ModUpdateCheckResult result)
		{
			if (!(result.ReleasePageUri == null))
			{
				RitsuToastService.Show(new RitsuToastRequest(result.Message ?? (options.DisplayName.Trim() + " update available."), result.Title ?? (options.DisplayName.Trim() + " update available"), null, RitsuToastLevel.Info, options.ToastDurationSeconds, delegate
				{
					OpenReleasePage(result.ReleasePageUri);
				})
				{
					IsPersistent = false
				});
			}
		}

		private static void ShowCompletionToast(ModUpdateCheckOptions options, ModUpdateCheckResult result)
		{
			switch (result.Status)
			{
			case ModUpdateCheckStatus.UpToDate:
				RitsuToastService.ShowInfo(options.DisplayName.Trim() + " is up to date (" + result.CurrentVersion + ").", options.DisplayName.Trim() + " update check");
				break;
			case ModUpdateCheckStatus.InvalidData:
			case ModUpdateCheckStatus.RequestFailed:
				RitsuToastService.ShowWarning(result.Message ?? "Update check failed.", options.DisplayName.Trim() + " update check");
				break;
			case ModUpdateCheckStatus.Skipped:
				break;
			}
		}

		private static ModUpdateCheckLocalizedText? ResolveLocalizedText(ModUpdateCheckManifest manifest)
		{
			Dictionary<string, ModUpdateCheckLocalizedText> localized = manifest.Localized;
			if (localized == null || localized.Count <= 0)
			{
				return null;
			}
			string text = I18N.ResolveCurrentLanguageCode();
			if (TryGetLocalized(text, out var text2))
			{
				return text2;
			}
			string text3 = text;
			if (!(text3 == "zhs"))
			{
				if (text3 == "eng")
				{
					if (TryGetLocalized("en", out var text4))
					{
						return text4;
					}
					if (TryGetLocalized("en-US", out var text5))
					{
						return text5;
					}
				}
			}
			else
			{
				if (TryGetLocalized("zh-CN", out var text6))
				{
					return text6;
				}
				if (TryGetLocalized("zh", out var text7))
				{
					return text7;
				}
			}
			ModUpdateCheckLocalizedText text8;
			ModUpdateCheckLocalizedText text9;
			return TryGetLocalized("eng", out text8) ? text8 : (TryGetLocalized("en", out text9) ? text9 : null);
			bool TryGetLocalized(string key, out ModUpdateCheckLocalizedText? reference)
			{
				if (manifest.Localized.TryGetValue(key, out reference))
				{
					return true;
				}
				string normalized = I18N.NormalizeLanguageCode(key);
				using (IEnumerator<KeyValuePair<string, ModUpdateCheckLocalizedText>> enumerator = manifest.Localized.Where<KeyValuePair<string, ModUpdateCheckLocalizedText>>((KeyValuePair<string, ModUpdateCheckLocalizedText> pair) => string.Equals(I18N.NormalizeLanguageCode(pair.Key), normalized, StringComparison.OrdinalIgnoreCase)).GetEnumerator())
				{
					if (enumerator.MoveNext())
					{
						reference = enumerator.Current.Value;
						return true;
					}
				}
				reference = null;
				return false;
			}
		}

		private static void OpenReleasePage(Uri releasePageUri)
		{
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_000b: Unknown result type (might be due to invalid IL or missing references)
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0040: Unknown result type (might be due to invalid IL or missing references)
			Error val = OS.ShellOpen(releasePageUri.ToString());
			if ((int)val != 0)
			{
				RitsuLibFramework.Logger.Warn($"[UpdateCheck] Failed to open release page '{releasePageUri}': {val}", 1);
			}
		}

		private static void ShowUpdateToastOnce(ModUpdateCheckOptions options, ModUpdateCheckResult result, bool automatic)
		{
			if (!automatic || UpdateCheckSessionHistory.TryRecordNotifiedVersion(options.ModId, result.LatestVersion))
			{
				ShowUpdateToast(options, result);
			}
		}

		private static void LogResult(ModUpdateCheckOptions options, ModUpdateCheckResult result, bool automatic)
		{
			switch (result.Status)
			{
			case ModUpdateCheckStatus.UpdateAvailable:
				if (!automatic || UpdateCheckSessionHistory.TryRecordLoggedVersion(options.ModId, result.LatestVersion))
				{
					RitsuLibFramework.Logger.Info($"[UpdateCheck] Update available for {options.ModId}: {result.CurrentVersion} -> {result.LatestVersion ?? "<unknown>"}; release={result.ReleasePageUri?.ToString() ?? "<none>"}.", 1);
				}
				break;
			case ModUpdateCheckStatus.UpToDate:
				RitsuLibFramework.Logger.Debug($"[UpdateCheck] {options.ModId} is up to date ({result.CurrentVersion}).", 1);
				break;
			case ModUpdateCheckStatus.Skipped:
				RitsuLibFramework.Logger.Debug("[UpdateCheck] " + options.ModId + " skipped: " + (result.Message ?? result.Status.ToString()), 1);
				break;
			case ModUpdateCheckStatus.InvalidData:
			case ModUpdateCheckStatus.RequestFailed:
				RitsuLibFramework.Logger.Warn("[UpdateCheck] " + options.ModId + " check skipped: " + (result.Message ?? result.Status.ToString()), 1);
				break;
			}
		}

		private static void PostToMainLoop(Action action)
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			if (Engine.GetMainLoop() is SceneTree)
			{
				Callable val = Callable.From(action);
				((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			}
			else
			{
				action();
			}
		}

		private static void ShowToast(bool deferToMainMenu, string? notificationKey, Action action)
		{
			if (deferToMainMenu)
			{
				UpdateCheckNotificationQueue.ShowWhenMainMenu(string.IsNullOrWhiteSpace(notificationKey) ? "mod-update:unknown" : notificationKey, action);
			}
			else
			{
				PostToMainLoop(action);
			}
		}

		private static void ValidateOptions(ModUpdateCheckOptions options)
		{
			ArgumentNullException.ThrowIfNull(options, "options");
			ArgumentException.ThrowIfNullOrWhiteSpace(options.ModId, "options.ModId");
			ArgumentException.ThrowIfNullOrWhiteSpace(options.DisplayName, "options.DisplayName");
			ArgumentException.ThrowIfNullOrWhiteSpace(options.CurrentVersion, "options.CurrentVersion");
			ArgumentNullException.ThrowIfNull(options.ManifestUri, "options.ManifestUri");
			if (!options.ManifestUri.IsAbsoluteUri)
			{
				throw new ArgumentException("ManifestUri must be absolute.", "options");
			}
			string scheme = options.ManifestUri.Scheme;
			if ((!(scheme == "http") && !(scheme == "https")) || 1 == 0)
			{
				throw new ArgumentException("ManifestUri must use http or https.", "options");
			}
			Uri releasePageUri = options.ReleasePageUri;
			if ((object)releasePageUri != null && !releasePageUri.IsAbsoluteUri)
			{
				throw new ArgumentException("ReleasePageUri must be absolute when provided.", "options");
			}
			if (options.ReleasePageUri != null && !IsWebUri(options.ReleasePageUri))
			{
				throw new ArgumentException("ReleasePageUri must use http or https when provided.", "options");
			}
			if (options.Timeout <= TimeSpan.Zero)
			{
				throw new ArgumentOutOfRangeException("options", "Timeout must be positive.");
			}
			double? toastDurationSeconds = options.ToastDurationSeconds;
			if (toastDurationSeconds.HasValue)
			{
				double valueOrDefault = toastDurationSeconds.GetValueOrDefault();
				if (!double.IsFinite(valueOrDefault) || valueOrDefault <= 0.0)
				{
					throw new ArgumentOutOfRangeException("options", "ToastDurationSeconds must be finite and positive when provided.");
				}
			}
			ulong? steamWorkshopItemId = options.SteamWorkshopItemId;
			if (steamWorkshopItemId.HasValue && steamWorkshopItemId.GetValueOrDefault() == 0L)
			{
				throw new ArgumentOutOfRangeException("options", "SteamWorkshopItemId must be positive when provided.");
			}
		}

		private static bool IsWebUri(Uri uri)
		{
			if ((object)uri != null && uri.IsAbsoluteUri)
			{
				string scheme = uri.Scheme;
				if (scheme == "http" || scheme == "https")
				{
					return true;
				}
			}
			return false;
		}

		private static bool ShouldSkipForSteamWorkshop(ModUpdateCheckOptions options)
		{
			if (!options.SkipWhenLoadedFromSteamWorkshop)
			{
				return false;
			}
			if (TryGetManagedSteamWorkshopItemId(options, out var _))
			{
				return true;
			}
			ulong? steamWorkshopItemId = options.SteamWorkshopItemId;
			if (steamWorkshopItemId.HasValue)
			{
				ulong valueOrDefault = steamWorkshopItemId.GetValueOrDefault();
				if (!string.IsNullOrWhiteSpace(options.InstallSourcePath))
				{
					return SteamWorkshopInstallSource.IsPathLoadedFromSteamWorkshopItem(options.InstallSourcePath, valueOrDefault);
				}
				if (options.InstallSourceAssembly != null)
				{
					return SteamWorkshopInstallSource.IsAssemblyLoadedFromSteamWorkshopItem(options.InstallSourceAssembly, valueOrDefault);
				}
				return false;
			}
			if (!string.IsNullOrWhiteSpace(options.InstallSourcePath))
			{
				return SteamWorkshopInstallSource.IsPathLoadedFromSteamWorkshop(options.InstallSourcePath);
			}
			if (options.InstallSourceAssembly != null)
			{
				return SteamWorkshopInstallSource.IsAssemblyLoadedFromSteamWorkshop(options.InstallSourceAssembly);
			}
			return false;
		}

		private static bool TryGetManagedSteamWorkshopItemId(ModUpdateCheckOptions options, out ulong itemId)
		{
			itemId = 0uL;
			if (!options.SkipWhenLoadedFromSteamWorkshop)
			{
				return false;
			}
			ulong? steamWorkshopItemId = options.SteamWorkshopItemId;
			if (steamWorkshopItemId.HasValue)
			{
				ulong valueOrDefault = steamWorkshopItemId.GetValueOrDefault();
				return TryMatchConfiguredWorkshopItem(options, valueOrDefault, out itemId);
			}
			if (!string.IsNullOrWhiteSpace(options.InstallSourcePath))
			{
				return SteamWorkshopInstallSource.TryGetWorkshopItemIdFromPath(options.InstallSourcePath, out itemId);
			}
			if (options.InstallSourceAssembly != null)
			{
				return SteamWorkshopInstallSource.TryGetWorkshopItemIdFromAssembly(options.InstallSourceAssembly, out itemId);
			}
			return false;
		}

		private static bool TryMatchConfiguredWorkshopItem(ModUpdateCheckOptions options, ulong configuredItemId, out ulong itemId)
		{
			itemId = 0uL;
			if (!string.IsNullOrWhiteSpace(options.InstallSourcePath))
			{
				if (!SteamWorkshopInstallSource.IsPathLoadedFromSteamWorkshopItem(options.InstallSourcePath, configuredItemId))
				{
					return false;
				}
				itemId = configuredItemId;
				return true;
			}
			if (options.InstallSourceAssembly == null || !SteamWorkshopInstallSource.IsAssemblyLoadedFromSteamWorkshopItem(options.InstallSourceAssembly, configuredItemId))
			{
				return false;
			}
			itemId = configuredItemId;
			return true;
		}

		private static string NormalizeSessionKey(string modId)
		{
			return modId.Trim();
		}
	}
	/// <summary>
	///     <para xml:lang="en">Configures a non-blocking mod update check.</para>
	///     <para xml:lang="zh-CN">配置非阻塞的模组更新检查。</para>
	/// </summary>
	public sealed record ModUpdateCheckOptions
	{
		/// <summary>
		///     <para xml:lang="en">Stable mod ID used for diagnostics and one-check-per-session de-duplication.</para>
		///     <para xml:lang="zh-CN">用于诊断和每会话单次检查去重的稳定模组 ID。</para>
		/// </summary>
		public required string ModId { get; init; }

		/// <summary>
		///     <para xml:lang="en">Display name shown in the default update notification.</para>
		///     <para xml:lang="zh-CN">默认更新通知中显示的名称。</para>
		/// </summary>
		public required string DisplayName { get; init; }

		/// <summary>
		///     <para xml:lang="en">Currently installed version, for example <c>1.2.3</c> or <c>v1.2.3-beta.1</c>.</para>
		///     <para xml:lang="zh-CN">当前安装的版本，例如 <c>1.2.3</c> 或 <c>v1.2.3-beta.1</c>。</para>
		/// </summary>
		public required string CurrentVersion { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Absolute URL of the compact JSON update manifest. Use a mirror or self-hosted endpoint when
		///         broad player reachability matters.
		///     </para>
		///     <para xml:lang="zh-CN">精简 JSON 更新清单的绝对 URL。需要覆盖更广泛的玩家网络环境时，应使用镜像或自托管端点。</para>
		/// </summary>
		public required Uri ManifestUri { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Fallback release page opened when the update notification is selected; the manifest can
		///         override it per release.
		///     </para>
		///     <para xml:lang="zh-CN">选中更新通知时打开的回退发布页；清单可按发布版本覆盖此页。</para>
		/// </summary>
		public Uri? ReleasePageUri { get; init; }

		/// <summary>
		///     <para xml:lang="en">Optional request headers for mirrors or self-hosted endpoints.</para>
		///     <para xml:lang="zh-CN">镜像或自托管端点使用的可选请求头。</para>
		/// </summary>
		public IReadOnlyDictionary<string, string>? Headers { get; init; }

		/// <summary>
		///     <para xml:lang="en">Network timeout; defaults to eight seconds.</para>
		///     <para xml:lang="zh-CN">网络超时时间；默认八秒。</para>
		/// </summary>
		public TimeSpan Timeout { get; init; } = TimeSpan.FromSeconds(8.0);

		/// <summary>
		///     <para xml:lang="en">
		///         Optional notification duration override in seconds. Leave null to use RitsuLib's default
		///         duration.
		///     </para>
		///     <para xml:lang="zh-CN">可选通知显示时长覆盖值，单位秒；为 null 时使用 RitsuLib 默认时长。</para>
		/// </summary>
		public double? ToastDurationSeconds { get; init; }

		/// <summary>
		///     <para xml:lang="en">Optional title override. Leave null to use the manifest title or the default title.</para>
		///     <para xml:lang="zh-CN">可选标题覆盖值；为 null 时使用清单标题或默认标题。</para>
		/// </summary>
		public string? ToastTitle { get; init; }

		/// <summary>
		///     <para xml:lang="en">Optional body override. Leave null to use the manifest message or the default body.</para>
		///     <para xml:lang="zh-CN">可选正文覆盖值；为 null 时使用清单消息或默认正文。</para>
		/// </summary>
		public string? ToastBody { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         When true, skips the external manifest check when the configured installation source came from
		///         Steam Workshop.
		///     </para>
		///     <para xml:lang="zh-CN">为 true 时，若配置的安装来源来自 Steam Workshop，则跳过外部清单检查。</para>
		/// </summary>
		public bool SkipWhenLoadedFromSteamWorkshop { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Steam Workshop item ID that owns this update check. When set, Workshop skipping applies only
		///         when the installation source path belongs to this item.
		///     </para>
		///     <para xml:lang="zh-CN">拥有此更新检查的 Steam Workshop 条目 ID。设置后，仅当安装来源路径属于该条目时才跳过外部检查。</para>
		/// </summary>
		public ulong? SteamWorkshopItemId { get; init; }

		/// <summary>
		///     <para xml:lang="en">Optional assembly used to determine whether this mod was loaded from Steam Workshop.</para>
		///     <para xml:lang="zh-CN">用于确定此模组是否从 Steam Workshop 加载的可选程序集。</para>
		/// </summary>
		public Assembly? InstallSourceAssembly { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional path used to determine whether this mod was loaded from Steam Workshop. When set, it
		///         takes precedence over <see cref="P:STS2RitsuLib.Updates.ModUpdateCheckOptions.InstallSourceAssembly" />.
		///     </para>
		///     <para xml:lang="zh-CN">用于确定此模组是否从 Steam Workshop 加载的可选路径。设置后优先于 <see cref="P:STS2RitsuLib.Updates.ModUpdateCheckOptions.InstallSourceAssembly" />。</para>
		/// </summary>
		public string? InstallSourcePath { get; init; }

		/// <summary>
		///     <para xml:lang="en">Creates update-check options from string URLs for the common call path.</para>
		///     <para xml:lang="zh-CN">从字符串 URL 创建常用调用路径所需的更新检查选项。</para>
		/// </summary>
		public static ModUpdateCheckOptions Create(string modId, string displayName, string currentVersion, string manifestUrl, string? releasePageUrl = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(manifestUrl, "manifestUrl");
			return Create(modId, displayName, currentVersion, new Uri(manifestUrl.Trim(), UriKind.Absolute), string.IsNullOrWhiteSpace(releasePageUrl) ? null : new Uri(releasePageUrl.Trim(), UriKind.Absolute));
		}

		/// <summary>
		///     <para xml:lang="en">Creates update-check options for the common call path.</para>
		///     <para xml:lang="zh-CN">创建常用调用路径所需的更新检查选项。</para>
		/// </summary>
		public static ModUpdateCheckOptions Create(string modId, string displayName, string currentVersion, Uri manifestUri, Uri? releasePageUri = null)
		{
			return new ModUpdateCheckOptions
			{
				ModId = modId,
				DisplayName = displayName,
				CurrentVersion = currentVersion,
				ManifestUri = manifestUri,
				ReleasePageUri = releasePageUri
			};
		}

		[CompilerGenerated]
		[SetsRequiredMembers]
		private ModUpdateCheckOptions(ModUpdateCheckOptions original)
		{
			ModId = original.ModId;
			DisplayName = original.DisplayName;
			CurrentVersion = original.CurrentVersion;
			ManifestUri = original.ManifestUri;
			ReleasePageUri = original.ReleasePageUri;
			Headers = original.Headers;
			Timeout = original.Timeout;
			ToastDurationSeconds = original.ToastDurationSeconds;
			ToastTitle = original.ToastTitle;
			ToastBody = original.ToastBody;
			SkipWhenLoadedFromSteamWorkshop = original.SkipWhenLoadedFromSteamWorkshop;
			SteamWorkshopItemId = original.SteamWorkshopItemId;
			InstallSourceAssembly = original.InstallSourceAssembly;
			InstallSourcePath = original.InstallSourcePath;
		}
	}
