	///     <para xml:lang="zh-CN">包含已完成更新检查的结果及可选发布详情。</para>
	/// </summary>
	public sealed record ModUpdateCheckResult(ModUpdateCheckStatus Status, string CurrentVersion, string? LatestVersion = null, Uri? ReleasePageUri = null, string? Title = null, string? Message = null);
	/// <summary>
	///     <para xml:lang="en">
	///         Integrates RitsuLib's own release-manifest update check with settings, Steam Workshop routing,
	///         and user notifications.
	///     </para>
	///     <para xml:lang="zh-CN">将 RitsuLib 自身的发布清单更新检查与设置、Steam 创意工坊路由及用户通知集成。</para>
	/// </summary>
	internal static class RitsuLibUpdateCheckService
	{
		private const double UpdateCheckToastDurationSeconds = 8.0;

		private static readonly Uri ManifestUri = new Uri("https://sts2-ritsulib.ritsukage.com/ritsulib-update.json");

		private static readonly Uri ReleasePageFallbackUri = new Uri("https://sts2-ritsulib.ritsukage.com/");

		private static readonly Lock SyncRoot = new Lock();

		private static int _devBuildAutoToastShown;

		private static bool _initialized;

		internal static void Initialize()
		{
			using (SyncRoot.EnterScope())
			{
				if (!_initialized)
				{
					AutomaticUpdateCheckScheduler.Register("ritsulib", "RitsuLib", RitsuLibSettingsStore.IsUpdateCheckEnabled, CheckAutoAsync);
					_initialized = true;
				}
			}
		}

		internal static void CheckNowFromSettings()
		{
			if (IsLoadedFromSteamWorkshop())
			{
				RitsuLibFramework.Logger.Info("[UpdateCheck] RitsuLib manual external update check routed to its Steam Workshop item: loaded from Steam Workshop.", 1);
				SteamWorkshopUpdateCoordinator.CheckRitsuLibNowFromSettings();
			}
			else if (RitsuLibBuildInfo.IsDevBuild)
			{
				PostToMainLoop(ShowDevBuildToast);
			}
			else
			{
				CheckAsync(showCompletionToast: true, deferToastToMainMenu: false);
			}
		}

		private static async Task CheckAutoAsync(CancellationToken cancellationToken)
		{
			if (IsLoadedFromSteamWorkshop())
			{
				RitsuLibFramework.Logger.Info("[UpdateCheck] RitsuLib external update check skipped: loaded from Steam Workshop.", 1);
			}
			else if (RitsuLibBuildInfo.IsDevBuild)
			{
				if (Interlocked.Exchange(ref _devBuildAutoToastShown, 1) == 0)
				{
					ShowToast(deferToMainMenu: true, "ritsulib-dev-build", ShowDevBuildToast);
				}
			}
			else
			{
				await CheckAsync(showCompletionToast: false, deferToastToMainMenu: true).ConfigureAwait(continueOnCapturedContext: false);
			}
		}

		private static async Task CheckAsync(bool showCompletionToast, bool deferToastToMainMenu)
		{
			try
			{
				ModUpdateCheckOptions options = BuildOptions();
				ModUpdateCheckResult result = await ModUpdateChecker.CheckAsync(options).ConfigureAwait(continueOnCapturedContext: false);
				LogResult(result, deferToastToMainMenu);
				ShowToast(deferToastToMainMenu && (object)result != null && result.Status == ModUpdateCheckStatus.UpdateAvailable && (object)result.ReleasePageUri != null, "ritsulib-update", delegate
				{
					ShowResultToastOnce(options, result, showCompletionToast, deferToastToMainMenu);
				});
			}
			catch (Exception ex)
			{
				Exception ex2 = ex;
				Exception ex3 = ex2;
				RitsuLibFramework.Logger.Warn("[UpdateCheck] RitsuLib update check failed: " + ex3.Message, 1);
				if (showCompletionToast)
				{
					PostToMainLoop(delegate
					{
						ShowUpdateCheckToast(Format("ritsulib.updateCheck.toast.failed", "Update check failed: {0}", ex3.Message), L("ritsulib.updateCheck.toast.title", "RitsuLib update check"), RitsuToastLevel.Warning);
					});
				}
			}
		}

		private static void ShowResultToast(ModUpdateCheckOptions options, ModUpdateCheckResult result, bool showCompletionToast)
		{
			switch (result.Status)
			{
			case ModUpdateCheckStatus.UpdateAvailable:
				if (result.ReleasePageUri != null)
				{
					RitsuToastService.Show(new RitsuToastRequest(result.Message ?? Format("ritsulib.updateCheck.toast.availableBody", "Version {0} of RitsuLib is available. Click to open the release page.", result.LatestVersion ?? ""), result.Title ?? L("ritsulib.updateCheck.toast.availableTitle", "RitsuLib update available"), null, RitsuToastLevel.Info, options.ToastDurationSeconds, delegate
					{
						OpenReleasePage(result.ReleasePageUri);
					})
					{
						IsPersistent = false
					});
				}
				break;
			case ModUpdateCheckStatus.UpToDate:
				if (showCompletionToast)
				{
					ShowUpdateCheckToast(Format("ritsulib.updateCheck.toast.upToDateBody", "RitsuLib is up to date ({0}).", result.CurrentVersion), L("ritsulib.updateCheck.toast.title", "RitsuLib update check"), RitsuToastLevel.Info);
				}
				break;
			case ModUpdateCheckStatus.InvalidData:
			case ModUpdateCheckStatus.RequestFailed:
				if (showCompletionToast)
				{
					ShowUpdateCheckToast(Format("ritsulib.updateCheck.toast.failed", "Update check failed: {0}", result.Message ?? result.Status.ToString()), L("ritsulib.updateCheck.toast.title", "RitsuLib update check"), RitsuToastLevel.Warning);
				}
				break;
			}
		}

		private static void ShowResultToastOnce(ModUpdateCheckOptions options, ModUpdateCheckResult result, bool showCompletionToast, bool automatic)
		{
			if (!automatic || result.Status != ModUpdateCheckStatus.UpdateAvailable || UpdateCheckSessionHistory.TryRecordNotifiedVersion("com.ritsukage.sts2-RitsuLib", result.LatestVersion))
			{
				ShowResultToast(options, result, showCompletionToast);
			}
		}

		private static void LogResult(ModUpdateCheckResult result, bool automatic)
		{
			switch (result.Status)
			{
			case ModUpdateCheckStatus.UpdateAvailable:
				if (!automatic || UpdateCheckSessionHistory.TryRecordLoggedVersion("com.ritsukage.sts2-RitsuLib", result.LatestVersion))
				{
					RitsuLibFramework.Logger.Info($"[UpdateCheck] RitsuLib update available: {result.CurrentVersion} -> {result.LatestVersion ?? "<unknown>"}; release={result.ReleasePageUri?.ToString() ?? "<none>"}.", 1);
				}
				break;
			case ModUpdateCheckStatus.UpToDate:
				RitsuLibFramework.Logger.Debug("[UpdateCheck] RitsuLib is up to date (" + result.CurrentVersion + ").", 1);
				break;
			case ModUpdateCheckStatus.Skipped:
				RitsuLibFramework.Logger.Debug("[UpdateCheck] RitsuLib check skipped: " + (result.Message ?? result.Status.ToString()), 1);
				break;
			case ModUpdateCheckStatus.InvalidData:
			case ModUpdateCheckStatus.RequestFailed:
				RitsuLibFramework.Logger.Warn("[UpdateCheck] RitsuLib check failed: " + (result.Message ?? result.Status.ToString()), 1);
				break;
			}
		}

		private static void ShowUpdateCheckToast(string body, string title, RitsuToastLevel level)
		{
			RitsuToastService.Show(new RitsuToastRequest(body, title, null, level, 8.0));
		}

