	/// <summary>
	///     <para xml:lang="en">Represents and compares a permissive semantic version with numeric and prerelease identifiers.</para>
	///     <para xml:lang="zh-CN">表示并比较包含数字及预发布标识符的宽松语义版本。</para>
	/// </summary>
	internal readonly record struct SimpleSemanticVersion(IReadOnlyList<long> Numbers, IReadOnlyList<string> Prerelease) : IComparable<SimpleSemanticVersion>
	{
		public int CompareTo(SimpleSemanticVersion other)
		{
			int num = Math.Max(Numbers.Count, other.Numbers.Count);
			for (int i = 0; i < num; i++)
			{
				long num2 = ((i < Numbers.Count) ? Numbers[i] : 0);
				long value = ((i < other.Numbers.Count) ? other.Numbers[i] : 0);
				int num3 = num2.CompareTo(value);
				if (num3 != 0)
				{
					return num3;
				}
			}
			if (Prerelease.Count == 0)
			{
				if (other.Prerelease.Count == 0)
				{
					return 0;
				}
				return 1;
			}
			if (other.Prerelease.Count == 0)
			{
				return -1;
			}
			num = Math.Max(Prerelease.Count, other.Prerelease.Count);
			for (int j = 0; j < num; j++)
			{
				if (j >= Prerelease.Count)
				{
					return -1;
				}
				if (j >= other.Prerelease.Count)
				{
					return 1;
				}
				int num4 = ComparePrereleaseIdentifier(Prerelease[j], other.Prerelease[j]);
				if (num4 != 0)
				{
					return num4;
				}
			}
			return 0;
		}

		public static bool TryParse(string? text, out SimpleSemanticVersion version)
		{
			version = default(SimpleSemanticVersion);
			if (text == null)
			{
				return false;
			}
			string text2 = text.Trim();
			if (text2.Length == 0)
			{
				return false;
			}
			char c = text2[0];
			if ((c == 'V' || c == 'v') ? true : false)
			{
				text2 = text2.Substring(1);
			}
			int num = text2.IndexOf('+', StringComparison.Ordinal);
			if (num >= 0)
			{
				if (!IsValidIdentifierList(text2.Substring(num + 1)))
				{
					return false;
				}
				text2 = text2.Substring(0, num);
			}
			string[] prerelease = Array.Empty<string>();
			int num2 = text2.IndexOf('-', StringComparison.Ordinal);
			if (num2 >= 0)
			{
				string text3 = text2.Substring(num2 + 1);
				text2 = text2.Substring(0, num2);
				if (!IsValidIdentifierList(text3))
				{
					return false;
				}
				prerelease = text3.Split('.');
			}
			string[] array = text2.Split('.');
			if (array.Length == 0)
			{
				return false;
			}
			long[] array2 = new long[array.Length];
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i].Length == 0 || !array[i].All(char.IsAsciiDigit) || !long.TryParse(array[i], out var result))
				{
					return false;
				}
				array2[i] = result;
			}
			version = new SimpleSemanticVersion(array2, prerelease);
			return true;
		}

		private static bool IsValidIdentifierList(string text)
		{
			if (text.Length == 0)
			{
				return false;
			}
			return text.Split('.').All((string identifier) => identifier.Length > 0 && identifier.All((char character) => char.IsAsciiLetterOrDigit(character) || character == '-'));
		}

		private static int ComparePrereleaseIdentifier(string left, string right)
		{
			bool num = left.All(char.IsAsciiDigit);
			bool flag = right.All(char.IsAsciiDigit);
			if (num)
			{
				if (flag)
				{
					return CompareNumericIdentifiers(left, right);
				}
				return -1;
			}
			return flag ? 1 : string.Compare(left, right, StringComparison.Ordinal);
		}

		private static int CompareNumericIdentifiers(string left, string right)
		{
			string text = left.TrimStart('0');
			string text2 = right.TrimStart('0');
			if (text.Length == 0)
			{
				text = "0";
			}
			if (text2.Length == 0)
			{
				text2 = "0";
			}
			int num = text.Length.CompareTo(text2.Length);
			if (num == 0)
			{
				return string.Compare(text, text2, StringComparison.Ordinal);
			}
			return num;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Defers keyed update-notification actions until a main-menu scene is active.</para>
	///     <para xml:lang="zh-CN">将带键的更新通知操作延后到主菜单场景处于活动状态时执行。</para>
	/// </summary>
	internal static class UpdateCheckNotificationQueue
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, Action> PendingByKey = new Dictionary<string, Action>(StringComparer.Ordinal);

		internal static void ShowWhenMainMenu(string key, Action action)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			ArgumentNullException.ThrowIfNull(action, "action");
			UpdateCheckSessionState.Initialize();
			if (UpdateCheckSessionState.IsMainMenuActive)
			{
				PostToMainLoop(action);
				return;
			}
			using (SyncRoot.EnterScope())
			{
				PendingByKey[key] = action;
			}
		}

		internal static void FlushPending()
		{
			Action[] array;
			using (SyncRoot.EnterScope())
			{
				if (PendingByKey.Count == 0)
				{
					return;
				}
				array = PendingByKey.Values.ToArray();
				PendingByKey.Clear();
			}
			Action[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				PostToMainLoop(array2[i]);
			}
		}

		private static void PostToMainLoop(Action action)
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			if (Engine.GetMainLoop() is SceneTree)
			{
				Callable val = Callable.From(action);
				((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			}
			else
			{
				action();
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Tracks update versions already logged or notified during the current process session.</para>
	///     <para xml:lang="zh-CN">跟踪当前进程会话中已记录日志或已通知的更新版本。</para>
	/// </summary>
	internal static class UpdateCheckSessionHistory
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly HashSet<string> LoggedVersions = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

		private static readonly HashSet<string> NotifiedVersions = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

		internal static bool TryRecordLoggedVersion(string modId, string? version)
		{
			return TryRecordVersion(LoggedVersions, modId, version);
		}

		internal static bool TryRecordNotifiedVersion(string modId, string? version)
		{
			return TryRecordVersion(NotifiedVersions, modId, version);
		}

		private static bool TryRecordVersion(HashSet<string> versions, string modId, string? version)
		{
			string text = modId.Trim();
			string text2 = version?.Trim();
			if (text.Length == 0 || string.IsNullOrEmpty(text2))
			{
				return false;
			}
			string item = text + "\n" + text2;
			using (SyncRoot.EnterScope())
			{
				return versions.Add(item);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Tracks whether the current session is at the main menu or in a combat room for update-check
	///         scheduling.
	///     </para>
	///     <para xml:lang="zh-CN">跟踪当前会话是否位于主菜单或战斗房间，以供更新检查调度使用。</para>
	/// </summary>
	internal static class UpdateCheckSessionState
	{
		private static int _initialized;

		private static volatile bool _isCombatRoomActive;

		private static volatile bool _isMainMenuActive;

		internal static bool IsCombatRoomActive
		{
			get
			{
				Initialize();
				return _isCombatRoomActive;
			}
		}

		internal static bool IsMainMenuActive
		{
			get
			{
				Initialize();
				return _isMainMenuActive;
			}
		}

		internal static void Initialize()
		{
			if (Interlocked.CompareExchange(ref _initialized, 1, 0) != 0)
			{
				return;
			}
			List<IDisposable> list = new List<IDisposable>();
			try
			{
				list.Add(RitsuLibFramework.SubscribeLifecycle((Action<MainMenuReadyEvent>)delegate
				{
					_isCombatRoomActive = false;
					_isMainMenuActive = true;
					UpdateCheckNotificationQueue.FlushPending();
				}, true));
				list.Add(RitsuLibFramework.SubscribeLifecycle((Action<RunStartedEvent>)delegate
				{
					_isMainMenuActive = false;
				}, true));
				list.Add(RitsuLibFramework.SubscribeLifecycle((Action<RunLoadedEvent>)delegate
				{
					_isMainMenuActive = false;
				}, true));
				list.Add(RitsuLibFramework.SubscribeLifecycle(delegate(RoomEnteringEvent evt)
				{
					_isMainMenuActive = false;
					if (evt.Room is CombatRoom)
					{
						_isCombatRoomActive = true;
					}
				}));
				list.Add(RitsuLibFramework.SubscribeLifecycle(delegate(RoomExitedEvent evt)
				{
					if (evt.Room is CombatRoom)
					{
						_isCombatRoomActive = false;
					}
				}));
				list.Add(RitsuLibFramework.SubscribeLifecycle((Action<RunEndedEvent>)delegate
				{
					_isCombatRoomActive = false;
				}, true));
				Volatile.Write(ref _initialized, 2);
			}
			catch
			{
				for (int num = list.Count - 1; num >= 0; num--)
				{
					list[num].Dispose();
				}
				Volatile.Write(ref _initialized, 0);
				throw;
			}
		}
	}
}
namespace STS2RitsuLib.Unlocks
{
	internal static class EpochRuntimeCompatibility
	{
		private static readonly Lock WarnLock = new Lock();

		private static readonly HashSet<string> WarnedMissingEpochs = new HashSet<string>();

		internal static bool CanUseEpochId(string epochId, string context)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(epochId, "epochId");
			ArgumentException.ThrowIfNullOrWhiteSpace(context, "context");
			if (EpochModel.IsValid(epochId))
			{
				return true;
			}
			if (!RitsuLibSettingsStore.IsUnlockEpochCompatEnabled())
			{
				return true;
			}
			WarnMissingEpochOnce(epochId, context);
			return false;
		}

		private static void WarnMissingEpochOnce(string epochId, string context)
		{
			string item = epochId + ":" + context;
			using (WarnLock.EnterScope())
			{
				if (!WarnedMissingEpochs.Add(item))
				{
					return;
				}
			}
			RitsuLibFramework.Logger.Warn($"[Unlocks][DebugCompat] Missing epoch '{epochId}' during {context}. " + "Skipping this unlock attempt and continuing execution.", 1);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Emits at most one warning per key, keeping mod characters with missing unlock-rule registration playable
	///         without repeating the warning every combat or frame.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         每个键最多发出一次警告，使缺少解锁规则注册的模组角色仍可游玩，同时避免每场战斗或每帧重复记录。
	///     </para>
	/// </summary>
	internal static class ModUnlockMissingRuleWarnings
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly HashSet<string> WarnedKeys = new HashSet<string>();

		internal static void WarnOnce(string key, string message)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			ArgumentException.ThrowIfNullOrWhiteSpace(message, "message");
			using (SyncRoot.EnterScope())
			{
				if (!WarnedKeys.Add(key))
				{
					return;
				}
			}
			RitsuLibFramework.Logger.Warn(message, 1);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Registers a mod's epoch requirements and its post-run or combat-derived unlock rules.
	///     </para>
	///     <para xml:lang="zh-CN">注册模组的纪元要求，以及一局游戏结束后或由战斗结果触发的解锁规则。</para>
	/// </summary>
	public sealed class ModUnlockRegistry
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, ModUnlockRegistry> Registries = new Dictionary<string, ModUnlockRegistry>(StringComparer.OrdinalIgnoreCase);

		private static readonly Dictionary<ModelId, string> RequiredEpochsByModelId = new Dictionary<ModelId, string>();

		private static readonly List<PostRunEpochUnlockRule> PostRunRules = new List<PostRunEpochUnlockRule>();

		private static readonly Dictionary<ModelId, EliteEpochUnlockRule> EliteEpochRulesByCharacterId = new Dictionary<ModelId, EliteEpochUnlockRule>();

		private static readonly Dictionary<ModelId, CountedEpochUnlockRule> BossEpochRulesByCharacterId = new Dictionary<ModelId, CountedEpochUnlockRule>();

		private static readonly Dictionary<ModelId, string> AscensionOneEpochsByCharacterId = new Dictionary<ModelId, string>();

		private static readonly Dictionary<ModelId, string> AscensionRevealEpochsByCharacterId = new Dictionary<ModelId, string>();

		private static readonly Dictionary<ModelId, List<string>> PostRunCharacterUnlockEpochsByCharacterId = new Dictionary<ModelId, List<string>>();

		private static readonly HashSet<string> ModIdsIgnoringEpochRequirements = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

		private string? _freezeReason;

		/// <summary>
		///     <para xml:lang="en">Gets the ID of the mod that owns this registry.</para>
		///     <para xml:lang="zh-CN">获取拥有此注册表的模组 ID。</para>
		/// </summary>
		public string ModId { get; }

		/// <summary>
		///     <para xml:lang="en">Gets whether the framework has frozen further unlock-rule registration.</para>
		///     <para xml:lang="zh-CN">获取框架是否已冻结后续解锁规则注册。</para>
		/// </summary>
		public static bool IsFrozen { get; private set; }

		private ModUnlockRegistry(string modId)
		{
			ModId = modId;
		}

		/// <summary>
		///     <para xml:lang="en">Returns the unlock registry for <paramref name="modId" />.</para>
		///     <para xml:lang="zh-CN">返回 <paramref name="modId" /> 对应的解锁注册表。</para>
		/// </summary>
		public static ModUnlockRegistry For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (SyncRoot.EnterScope())
			{
				if (Registries.TryGetValue(modId, out ModUnlockRegistry value))
				{
					return value;
				}
				value = new ModUnlockRegistry(modId);
				Registries[modId] = value;
				return value;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Configures whether models owned by <paramref name="modId" /> bypass
		///         <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.RequireEpoch(System.Type,System.String)" /> requirements at runtime. Ascension reveal rules for those
		///         characters honor the same bypass.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         配置 <paramref name="modId" /> 所属模型是否在运行时跳过
		///         <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.RequireEpoch(System.Type,System.String)" /> 要求。相应角色的进阶显示规则也会遵循此设置。
		///     </para>
		/// </summary>
		public static void SetEpochRequirementsIgnoredForMod(string modId, bool ignored = true)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (SyncRoot.EnterScope())
			{
				if (ignored)
				{
					ModIdsIgnoringEpochRequirements.Add(modId);
				}
				else
				{
					ModIdsIgnoringEpochRequirements.Remove(modId);
				}
			}
		}

		internal static bool IsEpochRequirementIgnoredForModelType(Type modelType)
		{
			ArgumentNullException.ThrowIfNull(modelType, "modelType");
			if (!ModContentRegistry.TryGetOwnerModId(modelType, out string modId))
			{
				return false;
			}
			using (SyncRoot.EnterScope())
			{
				return ModIdsIgnoringEpochRequirements.Contains(modId);
			}
		}

		internal static string[] GetEffectiveRequiredEpochIds(ProgressState progress)
		{
			ArgumentNullException.ThrowIfNull(progress, "progress");
			KeyValuePair<ModelId, string>[] source;
			using (SyncRoot.EnterScope())
			{
				source = RequiredEpochsByModelId.ToArray();
			}
			return (from entry in source
				where progress.IsEpochObtained(entry.Value)
				select entry.Value).Distinct<string>(StringComparer.Ordinal).ToArray();
		}

		internal static UnlockState IncludeObtainedRequiredEpochs(UnlockState unlockState, ProgressState progress)
		{
			//IL_006f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0075: Expected O, but got Unknown
			ArgumentNullException.ThrowIfNull(unlockState, "unlockState");
			ArgumentNullException.ThrowIfNull(progress, "progress");
			string[] effectiveRequiredEpochIds = GetEffectiveRequiredEpochIds(progress);
			if (effectiveRequiredEpochIds.Length == 0)
			{
				return unlockState;
			}
			SerializableUnlockState val = unlockState.ToSerializable();
			HashSet<string> unlockedEpochs = val.UnlockedEpochs.ToHashSet<string>(StringComparer.Ordinal);
			if (!effectiveRequiredEpochIds.Aggregate(seed: false, (bool current, string epochId) => current | unlockedEpochs.Add(epochId)))
			{
				return unlockState;
			}
			return new UnlockState((IEnumerable<string>)unlockedEpochs, (IEnumerable<ModelId>)val.EncountersSeen, val.NumberOfRuns);
		}

