		private void RequireEpochCore(Type modelType, string epochId, bool overwrite)
		{
			EnsureModelType(modelType, typeof(AbstractModel), "modelType");
			ArgumentException.ThrowIfNullOrWhiteSpace(epochId, "epochId");
			EnsureMutable("register unlock requirement for '" + modelType.Name + "'");
			RegistrationConflictDetector.ThrowIfModelIdConflicts(modelType);
			ModelId id = ModelDb.GetId(modelType);
			using (SyncRoot.EnterScope())
			{
				if (overwrite || !RequiredEpochsByModelId.ContainsKey(id))
				{
					RequiredEpochsByModelId[id] = epochId;
				}
			}
		}

