		///     <para xml:lang="zh-CN">
		///         注册一局游戏结束后角色解锁检查为 <paramref name="characterId" /> 授予的纪元。
		///     </para>
		/// </summary>
		public void RegisterPostRunCharacterUnlockEpoch(ModelId characterId, string epochId)
		{
			EnsureMutable("register post-run character unlock epoch '" + epochId + "'");
			ArgumentException.ThrowIfNullOrWhiteSpace(epochId, "epochId");
			using (SyncRoot.EnterScope())
			{
				if (!PostRunCharacterUnlockEpochsByCharacterId.TryGetValue(characterId, out List<string> value))
				{
					value = new List<string>();
					PostRunCharacterUnlockEpochsByCharacterId[characterId] = value;
				}
				if (!value.Contains<string>(epochId, StringComparer.Ordinal))
				{
					value.Add(epochId);
				}
			}
		}

		internal static void FreezeRegistrations(string reason)
		{
			using (SyncRoot.EnterScope())
			{
				if (IsFrozen)
				{
					return;
				}
				IsFrozen = true;
				foreach (ModUnlockRegistry value in Registries.Values)
				{
					value._freezeReason = reason;
				}
			}
		}

		internal static void ValidateFrozenModelReferences()
		{
			ModelId[] array;
			ModelId[] array2;
			ModelId[] array3;
			ModelId[] array4;
			ModelId[] array5;
			ModelId[] array6;
			using (SyncRoot.EnterScope())
			{
				array = RequiredEpochsByModelId.Keys.ToArray();
				array2 = EliteEpochRulesByCharacterId.Keys.ToArray();
				array3 = BossEpochRulesByCharacterId.Keys.ToArray();
				array4 = AscensionOneEpochsByCharacterId.Keys.ToArray();
				array5 = AscensionRevealEpochsByCharacterId.Keys.ToArray();
				array6 = PostRunCharacterUnlockEpochsByCharacterId.Keys.ToArray();
			}
			ModelId[] array7 = array;
			foreach (ModelId modelId in array7)
			{
				RegistrationFreezeDiagnostics.WarnMissingModelId("Unlocks", null, "RequireEpoch model", modelId, typeof(AbstractModel));
			}
			array7 = array2;
			foreach (ModelId characterId in array7)
			{
				WarnMissingCharacterId("elite epoch rule character", characterId);
			}
			array7 = array3;
			foreach (ModelId characterId2 in array7)
			{
				WarnMissingCharacterId("boss epoch rule character", characterId2);
			}
			array7 = array4;
			foreach (ModelId characterId3 in array7)
			{
				WarnMissingCharacterId("ascension-one epoch character", characterId3);
			}
			array7 = array5;
			foreach (ModelId characterId4 in array7)
			{
				WarnMissingCharacterId("ascension reveal character", characterId4);
			}
			array7 = array6;
			foreach (ModelId characterId5 in array7)
			{
				WarnMissingCharacterId("post-run character unlock character", characterId5);
			}
			static void WarnMissingCharacterId(string description, ModelId modelId2)
			{
				RegistrationFreezeDiagnostics.WarnMissingModelId("Unlocks", null, description, modelId2, typeof(CharacterModel));
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether <paramref name="model" /> satisfies its epoch requirement in
		///         <paramref name="unlockState" />. Content generation may use a multiplayer-merged
		///         <see cref="T:MegaCrit.Sts2.Core.Unlocks.UnlockState" />, so this check does not read the local profile.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <paramref name="model" /> 是否满足 <paramref name="unlockState" /> 中的纪元要求。内容生成可能使用
		///         多人游戏合并后的 <see cref="T:MegaCrit.Sts2.Core.Unlocks.UnlockState" />，因此此检查不会直接读取本机档案。
		///     </para>
		/// </summary>
		internal static bool IsUnlocked(AbstractModel model, UnlockState unlockState)
		{
			using (SyncRoot.EnterScope())
			{
				if (!RequiredEpochsByModelId.TryGetValue(model.Id, out string value))
				{
					return true;
				}
				if (ModContentRegistry.TryGetOwnerModId(((object)model).GetType(), out string modId) && ModIdsIgnoringEpochRequirements.Contains(modId))
				{
					return true;
				}
				return unlockState.ToSerializable().UnlockedEpochs.Contains(value);
			}
		}

		internal static IEnumerable<TModel> FilterUnlocked<TModel>(IEnumerable<TModel> source, UnlockState unlockState) where TModel : AbstractModel
		{
			List<TModel> list = new List<TModel>();
			list.AddRange(source.Where((TModel model) => IsUnlocked((AbstractModel)(object)model, unlockState)));
			return new <>z__ReadOnlyList<TModel>(list);
		}

