		internal static void ProcessRunEnded(RunManager runManager, SerializableRun serializableRun, bool isVictory, bool isAbandoned)
		{
			ArgumentNullException.ThrowIfNull(runManager, "runManager");
			ArgumentNullException.ThrowIfNull(serializableRun, "serializableRun");
			if (!Sts2RunGameModeCompat.IsStandardSerializableRunForEpochUnlocks(serializableRun))
			{
				return;
			}
			SerializablePlayer me = LocalContext.GetMe(serializableRun);
			if (me == null)
			{
				return;
			}
			PostRunEpochUnlockRule[] array;
			using (SyncRoot.EnterScope())
			{
				array = PostRunRules.ToArray();
			}
			if (array.Length == 0 || me.CharacterId == (ModelId)null)
			{
				return;
			}
			PostRunUnlockContext arg = new PostRunUnlockContext(serializableRun, me, isVictory, isAbandoned, SaveManager.Instance.Progress.NumberOfRuns, SaveManager.Instance.Progress.Wins, me.CharacterId, serializableRun.Ascension);
			bool flag = false;
			PostRunEpochUnlockRule[] array2 = array;
			foreach (PostRunEpochUnlockRule postRunEpochUnlockRule in array2)
			{
				if (SaveManager.Instance.Progress.IsEpochObtained(postRunEpochUnlockRule.EpochId))
				{
					continue;
				}
				try
				{
					if (!postRunEpochUnlockRule.ShouldUnlock(arg))
					{
						continue;
					}
				}
				catch (Exception value)
				{
					RitsuLibFramework.Logger.Warn($"[Unlocks] Post-run rule '{postRunEpochUnlockRule.Description}' failed and was skipped: {value}", 1);
					continue;
				}
				if (EpochRuntimeCompatibility.CanUseEpochId(postRunEpochUnlockRule.EpochId, "post-run epoch rule '" + postRunEpochUnlockRule.Description + "'"))
				{
					flag = true;
					SaveManager.Instance.ObtainEpoch(postRunEpochUnlockRule.EpochId);
					NGame instance = NGame.Instance;
					if (instance != null)
					{
						GodotTreeExtensions.AddChildSafely((Node)(object)instance, (Node)(object)NGainEpochVfx.Create(EpochModel.Get(postRunEpochUnlockRule.EpochId)));
					}
					if (!me.DiscoveredEpochs.Contains<string>(postRunEpochUnlockRule.EpochId, StringComparer.Ordinal))
					{
						me.DiscoveredEpochs.Add(postRunEpochUnlockRule.EpochId);
					}
					Player me2 = LocalContext.GetMe((IPlayerCollection)(object)runManager.State);
					if (me2 != null && !me2.DiscoveredEpochs.Contains<string>(postRunEpochUnlockRule.EpochId, StringComparer.Ordinal))
					{
						me2.DiscoveredEpochs.Add(postRunEpochUnlockRule.EpochId);
					}
					RitsuLibFramework.Logger.Info("[Unlocks] Obtained epoch '" + postRunEpochUnlockRule.EpochId + "' via post-run rule: " + postRunEpochUnlockRule.Description, 1);
				}
			}
			if (flag)
			{
				SaveManager.Instance.SaveProgressFile();
			}
		}

		private void EnsureMutable(string operation)
		{
			if (!IsFrozen)
			{
				return;
			}
			throw new InvalidOperationException($"Cannot {operation} after unlock registration has been frozen ({_freezeReason ?? "unknown"}). " + "Register unlock rules from your mod initializer before model initialization.");
		}

		private static void ValidateRule(string epochId, string description)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(epochId, "epochId");
			ArgumentException.ThrowIfNullOrWhiteSpace(description, "description");
		}

		private static void EnsureModelType(Type type, Type expectedBaseType, string paramName)
		{
			ArgumentNullException.ThrowIfNull(type, paramName);
			ArgumentNullException.ThrowIfNull(expectedBaseType, "expectedBaseType");
			if (type.IsInterface || type.ContainsGenericParameters || !expectedBaseType.IsAssignableFrom(type))
			{
				throw new ArgumentException($"Type '{type.FullName}' must be a closed subtype of '{expectedBaseType.FullName}'.", paramName);
			}
		}
	}
