namespace STS2RitsuLib.Unlocks.Patches
{
	/// <summary>
	///     <para xml:lang="en">
	///         Replaces the base game's Ascension 1 epoch check for mod characters with registered epoch grants.
	///     </para>
	///     <para xml:lang="zh-CN">将模组角色的游戏本体进阶 1 纪元检查替换为注册表中声明的纪元授予规则。</para>
	/// </summary>
	internal class AscensionOneEpochCompatibilityPatch : IPatchMethod
	{
		public static string PatchId => "ascension_one_epoch_compatibility";

		public static string Description => "Handle ascension-one epoch unlock checks for mod characters via registered RitsuLib unlock rules";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ProgressSaveManager), "CheckAscensionOneCompleted", new Type[2]
				{
					typeof(SerializablePlayer),
					typeof(SerializableRun)
				}, ignoreIfMissing: true)
			};
		}

		public static bool Prefix(SerializablePlayer serializablePlayer, SerializableRun serializableRun)
		{
			ArgumentNullException.ThrowIfNull(serializablePlayer, "serializablePlayer");
			ArgumentNullException.ThrowIfNull(serializableRun, "serializableRun");
			if (serializableRun.Ascension != 1)
			{
				return true;
			}
			ArgumentNullException.ThrowIfNull(serializablePlayer.CharacterId, "serializablePlayer.CharacterId");
			CharacterModel byId = ModelDb.GetById<CharacterModel>(serializablePlayer.CharacterId);
			if (!ModCharacterTimelinePolicy.IsOwnedOrUsesTimelinePolicy(byId))
			{
				return true;
			}
			if (!Sts2RunGameModeCompat.IsStandardSerializableRunForEpochUnlocks(serializableRun))
			{
				return true;
			}
			if (!ModUnlockRegistry.TryGetAscensionOneEpoch(((AbstractModel)byId).Id, out string epochId))
			{
				if (ModCharacterTimelinePolicy.DoesNotRequireEpochAndTimeline(byId))
				{
					return false;
				}
				ModUnlockMissingRuleWarnings.WarnOnce($"ascension_one_epoch:{((AbstractModel)byId).Id}", $"[Unlocks] Mod character '{((AbstractModel)byId).Id}' has no registered ascension-one win epoch (UnlockEpochAfterAscensionOneWin / RegisterAscensionOneEpoch). " + "Leaving vanilla post-run check in place (no-op for this character).");
				return true;
			}
			if (SaveManager.Instance.Progress.IsEpochObtained(epochId))
			{
				return false;
			}
			if (!EpochRuntimeCompatibility.CanUseEpochId(epochId, $"ascension-one epoch rule for mod character '{((AbstractModel)byId).Id}'"))
			{
				return false;
			}
			SaveManager.Instance.ObtainEpoch(epochId);
			NGame instance = NGame.Instance;
			if (instance != null)
			{
				GodotTreeExtensions.AddChildSafely((Node)(object)instance, (Node)(object)NGainEpochVfx.Create(EpochModel.Get(epochId)));
			}
			if (!serializablePlayer.DiscoveredEpochs.Contains<string>(epochId, StringComparer.Ordinal))
			{
				serializablePlayer.DiscoveredEpochs.Add(epochId);
			}
			RitsuLibFramework.Logger.Info($"[Unlocks] Obtained epoch '{epochId}' after ascension-1 win for mod character '{((AbstractModel)byId).Id}'.", 1);
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Extends the base game's post-run character-unlock check with registered and template-derived mod epochs.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         使用已注册及由模板推导出的模组纪元扩展游戏本体的一局游戏结束后角色解锁检查。
	///     </para>
	/// </summary>
	internal class PostRunCharacterUnlockEpochCompatibilityPatch : IPatchMethod
	{
		public static string PatchId => "postrun_character_unlock_epoch_compatibility";

		public static string Description => "Handle registered or template-derived post-run character unlock epochs without blocking vanilla chains";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ProgressSaveManager), "PostRunUnlockCharacterEpochCheck", new Type[2]
				{
					typeof(SerializablePlayer),
					typeof(SerializableRun)
				}, ignoreIfMissing: true)
			};
		}

		public static bool Prefix(SerializablePlayer serializablePlayer, SerializableRun serializableRun)
		{
			ArgumentNullException.ThrowIfNull(serializablePlayer, "serializablePlayer");
			ArgumentNullException.ThrowIfNull(serializableRun, "serializableRun");
			ArgumentNullException.ThrowIfNull(serializablePlayer.CharacterId, "serializablePlayer.CharacterId");
			CharacterModel character = ModelDb.GetById<CharacterModel>(serializablePlayer.CharacterId);
			bool flag = ModCharacterTimelinePolicy.IsOwnedOrUsesTimelinePolicy(character);
			if (!Sts2RunGameModeCompat.IsStandardSerializableRunForEpochUnlocks(serializableRun))
			{
				return true;
			}
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			string[] postRunCharacterUnlockEpochs = ModUnlockRegistry.GetPostRunCharacterUnlockEpochs(((AbstractModel)character).Id);
			foreach (string item in postRunCharacterUnlockEpochs)
			{
				hashSet.Add(item);
			}
			foreach (string modCharacterRootEpochIdsUnlockedAfterRunA in ModTimelineNeowCoExpansion.GetModCharacterRootEpochIdsUnlockedAfterRunAs(((AbstractModel)character).Id))
			{
				hashSet.Add(modCharacterRootEpochIdsUnlockedAfterRunA);
			}
			if (hashSet.Count == 0)
			{
				if (!flag)
				{
					return true;
				}
				if (ModCharacterTimelinePolicy.DoesNotRequireEpochAndTimeline(character))
				{
					return false;
				}
				ModUnlockMissingRuleWarnings.WarnOnce($"postrun_char_unlock_epoch:{((AbstractModel)character).Id}", $"[Unlocks] Mod character '{((AbstractModel)character).Id}' has no registered post-run character-unlock epoch (UnlocksAfterRunAsType / UnlockCharacterAfterRunAs / RegisterPostRunCharacterUnlockEpoch). " + "Leaving vanilla post-run check in place (no-op for this character).");
				return true;
			}
			foreach (string item2 in from epochId in hashSet
				where !SaveManager.Instance.Progress.IsEpochObtained(epochId)
				where EpochRuntimeCompatibility.CanUseEpochId(epochId, $"post-run character unlock epoch rule after run as '{((AbstractModel)character).Id}'")
				select epochId)
			{
				SaveManager.Instance.ObtainEpoch(item2);
				NGame instance = NGame.Instance;
				if (instance != null)
				{
					GodotTreeExtensions.AddChildSafely((Node)(object)instance, (Node)(object)NGainEpochVfx.Create(EpochModel.Get(item2)));
				}
				if (!serializablePlayer.DiscoveredEpochs.Contains<string>(item2, StringComparer.Ordinal))
				{
					serializablePlayer.DiscoveredEpochs.Add(item2);
				}
				RitsuLibFramework.Logger.Info($"[Unlocks] Obtained post-run character unlock epoch '{item2}' after run as '{((AbstractModel)character).Id}'.", 1);
			}
			return !flag;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Overrides Ascension reveal queries for characters with a registered prerequisite epoch.
	///     </para>
	///     <para xml:lang="zh-CN">覆盖已注册前置纪元的角色进阶显示查询。</para>
	/// </summary>
	internal class AscensionEpochRevealCompatibilityPatch : IPatchMethod
	{
		public static string PatchId => "ascension_epoch_reveal_compatibility";

		public static string Description => "Handle ascension reveal checks for mod characters via registered RitsuLib unlock rules";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(StartRunLobby), "IsAscensionEpochRevealed", new Type[1] { typeof(ModelId) })
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Uses progression data when a custom Ascension reveal epoch is registered.
		///     </para>
		///     <para xml:lang="zh-CN">注册自定义进阶显示纪元后，根据进度数据设置查询结果。</para>
		/// </summary>
		[HarmonyPriority(800)]
		public static bool Prefix(ModelId characterId, ref bool __result)
		{
			CharacterModel byId = ModelDb.GetById<CharacterModel>(characterId);
			if (!ModUnlockRegistry.TryGetAscensionRevealEpoch(characterId, out string epochId))
			{
				if (!ModCharacterTimelinePolicy.DoesNotRequireEpochAndTimeline(byId))
				{
					return true;
				}
				__result = true;
				return false;
			}
			if (ModUnlockRegistry.IsEpochRequirementIgnoredForModelType(((object)byId).GetType()))
			{
				__result = true;
				return false;
			}
			__result = SaveManager.Instance.IsEpochRevealed(epochId);
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Applies registered boss-victory epoch rules instead of the base game's fifteen-boss rule for mod
	///         characters.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         对模组角色应用已注册的首领战胜利纪元规则，取代游戏本体的十五次首领战规则。
	///     </para>
	/// </summary>
	internal class BossEpochCompatibilityPatch : IPatchMethod
	{
		public static string PatchId => "boss_epoch_compatibility";

		public static string Description => "Handle boss-win epoch unlock checks for mod characters via registered RitsuLib unlock rules";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ProgressSaveManager), "CheckFifteenBossesDefeatedEpoch", new Type[1] { typeof(Player) })
			};
		}

		public static bool Prefix(ProgressSaveManager __instance, Player localPlayer)
		{
			ArgumentNullException.ThrowIfNull(__instance, "__instance");
			ArgumentNullException.ThrowIfNull(localPlayer, "localPlayer");
			CharacterModel character = localPlayer.Character;
			if (!ModCharacterTimelinePolicy.IsOwnedOrUsesTimelinePolicy(character))
			{
				return true;
			}
			if (!ModUnlockRegistry.TryGetBossEpochRule(((AbstractModel)character).Id, out CountedEpochUnlockRule rule))
			{
				if (ModCharacterTimelinePolicy.DoesNotRequireEpochAndTimeline(character))
				{
					return false;
				}
				ModUnlockMissingRuleWarnings.WarnOnce($"boss_epoch_rule:{((AbstractModel)character).Id}", $"[Unlocks] Mod character '{((AbstractModel)character).Id}' has no registered boss-win epoch rule (UnlockEpochAfterBossVictories / RegisterBossEpochRule). " + "Skipping vanilla boss epoch logic for this character so the run can continue.");
				return false;
			}
			if (SaveManager.Instance.Progress.IsEpochObtained(rule.EpochId))
			{
				return false;
			}
			if (Sts2RunGameModeCompat.AreMidRunEpochsLockedFor(localPlayer))
			{
				return false;
			}
			HashSet<ModelId> encounterIds = ModelDb.Acts.SelectMany((ActModel act) => act.AllBossEncounters.Select((EncounterModel encounter) => ((AbstractModel)encounter).Id)).ToHashSet();
			int num = CountEncounterWins(__instance, ((AbstractModel)character).Id, encounterIds);
			if (num < rule.RequiredWins)
			{
				return false;
			}
			if (!EpochRuntimeCompatibility.CanUseEpochId(rule.EpochId, $"boss-win epoch rule for mod character '{((AbstractModel)character).Id}'"))
			{
				return false;
			}
			SaveManager.Instance.ObtainEpoch(rule.EpochId);
			NGame instance = NGame.Instance;
			if (instance != null)
			{
				GodotTreeExtensions.AddChildSafely((Node)(object)instance, (Node)(object)NGainEpochVfx.Create(EpochModel.Get(rule.EpochId)));
			}
			if (!localPlayer.DiscoveredEpochs.Contains<string>(rule.EpochId, StringComparer.Ordinal))
			{
				localPlayer.DiscoveredEpochs.Add(rule.EpochId);
			}
			RitsuLibFramework.Logger.Info($"[Unlocks] Obtained epoch '{rule.EpochId}' after {num} boss win(s) using registered rule: {rule.Description}", 1);
			return false;
		}

		internal static int CountEncounterWins(ProgressSaveManager progressSaveManager, ModelId characterId, HashSet<ModelId> encounterIds)
		{
			ArgumentNullException.ThrowIfNull(progressSaveManager, "progressSaveManager");
			ArgumentNullException.ThrowIfNull(encounterIds, "encounterIds");
			int num = 0;
			foreach (EncounterStats value in progressSaveManager.Progress.EncounterStats.Values)
			{
				if (!encounterIds.Contains(value.Id))
				{
					continue;
				}
				using IEnumerator<FightStats> enumerator2 = value.FightStats.Where((FightStats fightStat) => fightStat.Character == characterId).GetEnumerator();
				if (enumerator2.MoveNext())
				{
					FightStats current2 = enumerator2.Current;
					num += current2.Wins;
				}
			}
			return num;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Skips a base-game-style character-unlock grant when its inferred epoch ID is unavailable for a mod
	///         character.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         模组角色按游戏本体规则推导出的纪元 ID 不可用时，跳过该角色解锁纪元的授予。
	///     </para>
	/// </summary>
	internal class CharacterUnlockEpochRuntimeCompatibilityPatch : IPatchMethod
	{
		public static string PatchId => "character_unlock_epoch_runtime_compatibility";

		public static string Description => "Prevent missing vanilla-style character unlock epochs from aborting runs for mod characters";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ProgressSaveManager), "ObtainCharUnlockEpoch", new Type[2]
				{
					typeof(Player),
					typeof(int)
				}, ignoreIfMissing: true)
			};
		}

		public static bool Prefix(Player localPlayer, int act)
		{
			ArgumentNullException.ThrowIfNull(localPlayer, "localPlayer");
			CharacterModel character = localPlayer.Character;
			if (!ModCharacterTimelinePolicy.IsOwnedOrUsesTimelinePolicy(character))
			{
				return true;
			}
			string text = act switch
			{
				0 => ((AbstractModel)character).Id.Entry.ToUpperInvariant() + "2_EPOCH", 
				1 => ((AbstractModel)character).Id.Entry.ToUpperInvariant() + "3_EPOCH", 
				2 => ((AbstractModel)character).Id.Entry.ToUpperInvariant() + "4_EPOCH", 
				_ => null, 
			};
			if (text == null)
			{
				return true;
			}
			if (ModCharacterTimelinePolicy.DoesNotRequireEpochAndTimeline(character) && !EpochModel.IsValid(text))
			{
				return false;
			}
			return EpochRuntimeCompatibility.CanUseEpochId(text, $"vanilla character unlock epoch grant for mod character '{((AbstractModel)character).Id}' after Act {act + 1}");
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Handles game versions whose elite-epoch check exists only inside
	///         <see cref="M:MegaCrit.Sts2.Core.Saves.Managers.ProgressSaveManager.UpdateAfterCombatWon(MegaCrit.Sts2.Core.Entities.Players.Player,MegaCrit.Sts2.Core.Rooms.CombatRoom)" />. The postfix handles normal completion without
	///         suppressing failures from a partially completed base-game update.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         兼容只在 <see cref="M:MegaCrit.Sts2.Core.Saves.Managers.ProgressSaveManager.UpdateAfterCombatWon(MegaCrit.Sts2.Core.Entities.Players.Player,MegaCrit.Sts2.Core.Rooms.CombatRoom)" /> 内执行精英纪元检查的游戏版本。后置补丁处理
	///         正常完成的情况，且不会吞掉游戏本体更新只完成一部分时产生的异常。
	///     </para>
	/// </summary>
	internal class EliteEpochAfterCombatFallbackPatch : IPatchMethod
	{
		public static string PatchId => "elite_epoch_after_combat_fallback";

		public static string Description => "Elite epoch unlock fallback when CheckFifteenElitesDefeatedEpoch is missing (stable vs beta)";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ProgressSaveManager), "UpdateAfterCombatWon", new Type[2]
				{
					typeof(Player),
					typeof(CombatRoom)
				})
			};
		}

		public static void Postfix(ProgressSaveManager __instance, Player localPlayer, CombatRoom room)
		{
			//IL_0009: Unknown result type (might be due to invalid IL or missing references)
			//IL_000f: Invalid comparison between Unknown and I4
			if (!EliteEpochModHandling.HasDedicatedEliteEpochCheckMethod && (int)((AbstractRoom)room).RoomType == 2 && ModCharacterTimelinePolicy.IsOwnedOrUsesTimelinePolicy(localPlayer.Character))
			{
				EliteEpochModHandling.TryHandleModEliteEpoch(__instance, localPlayer);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Routes elite-epoch handling for mod characters through <c>EliteEpochModHandling</c> when the game exposes
	///         a dedicated check method.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         游戏提供专用检查方法时，通过 <c>EliteEpochModHandling</c> 处理模组角色的精英纪元。
	///     </para>
	/// </summary>
	internal class EliteEpochCompatibilityPatch : IPatchMethod
	{
		public static string PatchId => "elite_epoch_compatibility";

		public static string Description => "Handle elite-win epoch unlock checks for mod characters via registered RitsuLib unlock rules";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ProgressSaveManager), "CheckFifteenElitesDefeatedEpoch", new Type[1] { typeof(Player) }, ignoreIfMissing: true)
			};
		}

		public static bool Prefix(ProgressSaveManager __instance, Player localPlayer)
		{
			ArgumentNullException.ThrowIfNull(__instance, "__instance");
			ArgumentNullException.ThrowIfNull(localPlayer, "localPlayer");
			if (!ModCharacterTimelinePolicy.IsOwnedOrUsesTimelinePolicy(localPlayer.Character))
			{
				return true;
			}
			EliteEpochModHandling.TryHandleModEliteEpoch(__instance, localPlayer);
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides shared elite-epoch unlock logic and detects whether the game exposes
	///         <c>CheckFifteenElitesDefeatedEpoch</c> or performs that check inside
	///         <see cref="M:MegaCrit.Sts2.Core.Saves.Managers.ProgressSaveManager.UpdateAfterCombatWon(MegaCrit.Sts2.Core.Entities.Players.Player,MegaCrit.Sts2.Core.Rooms.CombatRoom)" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供共用的精英纪元解锁逻辑，并检测游戏是提供 <c>CheckFifteenElitesDefeatedEpoch</c>，还是在
	///         <see cref="M:MegaCrit.Sts2.Core.Saves.Managers.ProgressSaveManager.UpdateAfterCombatWon(MegaCrit.Sts2.Core.Entities.Players.Player,MegaCrit.Sts2.Core.Rooms.CombatRoom)" /> 内执行该检查。
	///     </para>
	/// </summary>
	internal static class EliteEpochModHandling
	{
		internal static readonly bool HasDedicatedEliteEpochCheckMethod = typeof(ProgressSaveManager).GetMethod("CheckFifteenElitesDefeatedEpoch", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, new Type[1] { typeof(Player) }, null) != null;

		/// <summary>
		///     <para xml:lang="en">
		///         Applies the game's mid-run epoch restriction without depending on the same helper method being
		///         available in every supported build. Nonstandard game modes do not grant epochs.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在不依赖所有受支持版本都提供同一辅助方法的前提下，应用游戏的局内纪元限制。非标准游戏模式不会授予纪元。
		///     </para>
		/// </summary>
		internal static bool AreMidRunEpochsLockedFor(Player localPlayer)
		{
			ArgumentNullException.ThrowIfNull(localPlayer, "localPlayer");
			return Sts2RunGameModeCompat.AreMidRunEpochsLockedFor(localPlayer);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Applies a mod character's registered elite-epoch rule in place of base-game logic that rejects unknown
		///         <see cref="T:MegaCrit.Sts2.Core.Models.CharacterModel" /> types.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         应用模组角色已注册的精英纪元规则，取代会拒绝未知 <see cref="T:MegaCrit.Sts2.Core.Models.CharacterModel" /> 类型的游戏本体逻辑。
		///     </para>
		/// </summary>
		internal static void TryHandleModEliteEpoch(ProgressSaveManager progressSaveManager, Player localPlayer)
		{
			ArgumentNullException.ThrowIfNull(progressSaveManager, "progressSaveManager");
			ArgumentNullException.ThrowIfNull(localPlayer, "localPlayer");
			CharacterModel character = localPlayer.Character;
			if (!ModCharacterTimelinePolicy.IsOwnedOrUsesTimelinePolicy(character))
			{
				return;
			}
			if (!ModUnlockRegistry.TryGetEliteEpochRule(((AbstractModel)character).Id, out EliteEpochUnlockRule rule))
			{
				if (!ModCharacterTimelinePolicy.DoesNotRequireEpochAndTimeline(character))
				{
					ModUnlockMissingRuleWarnings.WarnOnce($"elite_epoch_rule:{((AbstractModel)character).Id}", $"[Unlocks] Mod character '{((AbstractModel)character).Id}' has no registered elite-win epoch rule (UnlockEpochAfterEliteVictories / RegisterEliteEpochRule). " + "Skipping vanilla elite epoch logic for this character so the run can continue.");
				}
			}
			else
			{
				if (AreMidRunEpochsLockedFor(localPlayer) || SaveManager.Instance.Progress.IsEpochObtained(rule.EpochId))
				{
					return;
				}
				int num = CountEliteWinsForCharacter(progressSaveManager, ((AbstractModel)character).Id);
				if (num >= rule.RequiredEliteWins && EpochRuntimeCompatibility.CanUseEpochId(rule.EpochId, $"elite-win epoch rule for mod character '{((AbstractModel)character).Id}'"))
				{
					SaveManager.Instance.ObtainEpoch(rule.EpochId);
					NGame instance = NGame.Instance;
					if (instance != null)
					{
						GodotTreeExtensions.AddChildSafely((Node)(object)instance, (Node)(object)NGainEpochVfx.Create(EpochModel.Get(rule.EpochId)));
					}
					if (!localPlayer.DiscoveredEpochs.Contains<string>(rule.EpochId, StringComparer.Ordinal))
					{
						localPlayer.DiscoveredEpochs.Add(rule.EpochId);
					}
					RitsuLibFramework.Logger.Info($"[Unlocks] Obtained epoch '{rule.EpochId}' after {num} elite win(s) using registered rule: {rule.Description}", 1);
				}
			}
		}

		internal static int CountEliteWinsForCharacter(ProgressSaveManager progressSaveManager, ModelId characterId)
		{
			HashSet<ModelId> hashSet = (HashSet<ModelId>)(typeof(ProgressSaveManager).GetMethod("GetEliteEncounters", BindingFlags.Static | BindingFlags.NonPublic) ?? throw new MissingMethodException(typeof(ProgressSaveManager).FullName, "GetEliteEncounters")).Invoke(null, null);
			ProgressState progress = progressSaveManager.Progress;
			int num = 0;
			foreach (EncounterStats value in progress.EncounterStats.Values)
			{
				if (!hashSet.Contains(value.Id))
				{
					continue;
				}
				using IEnumerator<FightStats> enumerator2 = value.FightStats.Where((FightStats fightStat) => fightStat.Character == characterId).GetEnumerator();
				if (enumerator2.MoveNext())
				{
					FightStats current2 = enumerator2.Current;
					num += current2.Wins;
				}
			}
			return num;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Backfills mod character root epochs from existing run history for their prerequisite characters.
	///     </para>
	///     <para xml:lang="zh-CN">根据前置角色已有的游戏记录补发模组角色的根纪元。</para>
	/// </summary>
	internal sealed class ModCharacterRootEpochBackfillPatch : IPatchMethod
	{
		public static string PatchId => "mod_character_root_epoch_backfill";

		public static string Description => "Backfill mod character root unlock epochs when prerequisite character runs already exist";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[2]
			{
				new ModPatchTarget(typeof(SaveManager), "InitProgressData", Type.EmptyTypes),
				new ModPatchTarget(typeof(SaveManager), "GenerateUnlockStateFromProgress", Type.EmptyTypes)
			};
		}

		public static void Prefix(MethodBase __originalMethod, SaveManager __instance)
		{
			if (__originalMethod.Name == "GenerateUnlockStateFromProgress")
			{
				ModCharacterRootEpochBackfill.TryBackfill(__instance);
			}
		}

		public static void Postfix(MethodBase __originalMethod, SaveManager __instance)
		{
			if (__originalMethod.Name == "InitProgressData")
			{
				ModCharacterRootEpochBackfill.TryBackfill(__instance);
			}
		}
	}
	internal static class ModCharacterRootEpochBackfill
	{
		private readonly record struct BackfillCandidate(string EpochId, ModelId CharacterId);

		internal static void TryBackfill(SaveManager saveManager)
		{
			ArgumentNullException.ThrowIfNull(saveManager, "saveManager");
			List<string> list = new List<string>();
			foreach (BackfillCandidate item in EnumerateBackfillCandidates(saveManager.Progress))
			{
				if (EpochRuntimeCompatibility.CanUseEpochId(item.EpochId, $"mod character root epoch backfill for '{item.CharacterId}'"))
				{
					saveManager.ObtainEpoch(item.EpochId);
					list.Add(item.EpochId);
				}
			}
			if (list.Count != 0)
			{
				saveManager.SaveProgressFile();
				RitsuLibFramework.Logger.Info("[Unlocks] Backfilled mod character root epoch(s) from prerequisite run history: " + string.Join(", ", list), 1);
			}
		}

		private static IEnumerable<BackfillCandidate> EnumerateBackfillCandidates(ProgressState progress)
		{
			foreach (string allEpochId in EpochModel.AllEpochIds)
			{
				EpochModel val;
				try
				{
					val = EpochModel.Get(allEpochId);
				}
				catch (Exception value)
				{
					RitsuLibFramework.Logger.Warn($"[Unlocks] Could not resolve epoch '{allEpochId}' while scanning root-epoch backfill candidates: {value}", 1);
					continue;
				}
				if (!(val is ModEpochTemplate) || progress.IsEpochObtained(val.Id) || !TryGetCharacterUnlockType(((object)val).GetType(), out Type characterType))
				{
					continue;
				}
				CharacterModel byId;
				try
				{
					byId = ModelDb.GetById<CharacterModel>(ModelDb.GetId(characterType));
				}
				catch (Exception value2)
				{
					RitsuLibFramework.Logger.Warn($"[Unlocks] Could not resolve character type '{characterType.FullName}' for root-epoch backfill: {value2}", 1);
					continue;
				}
				if (!ModCharacterTimelinePolicy.IsOwnedOrUsesTimelinePolicy(byId) || ModCharacterTimelinePolicy.DoesNotRequireEpochAndTimeline(byId) || !(byId is IModCharacterUnlockPrerequisite modCharacterUnlockPrerequisite))
				{
					continue;
				}
				Type unlocksAfterRunAsType = modCharacterUnlockPrerequisite.UnlocksAfterRunAsType;
				if ((object)unlocksAfterRunAsType != null)
				{
					ModelId id;
					try
					{
						id = ModelDb.GetId(unlocksAfterRunAsType);
					}
					catch (Exception value3)
					{
						RitsuLibFramework.Logger.Warn($"[Unlocks] Could not resolve prerequisite character type '{unlocksAfterRunAsType.FullName}' for root-epoch backfill: {value3}", 1);
						continue;
					}
					if (HasAnyPrerequisiteCharacterProgress(progress.GetStatsForCharacter(id)))
					{
						yield return new BackfillCandidate(val.Id, ((AbstractModel)byId).Id);
					}
				}
			}
		}

		private static bool HasAnyPrerequisiteCharacterProgress(CharacterStats? stats)
		{
			if (stats != null && (stats.TotalWins > 0 || stats.TotalLosses > 0 || stats.MaxAscension > 0 || stats.PreferredAscension > 0 || stats.Playtime > 0 || stats.FastestWinTime >= 0 || stats.BestWinStreak > 0 || stats.CurrentWinStreak > 0))
			{
				return true;
			}
			return false;
		}

		private static bool TryGetCharacterUnlockType(Type epochType, out Type characterType)
		{
			Type type = epochType;
			while (type != null)
			{
				if (type.IsGenericType && !(type.GetGenericTypeDefinition() != typeof(CharacterUnlockEpochTemplate<>)))
				{
					characterType = type.GetGenericArguments()[0];
					return true;
				}
				type = type.BaseType;
			}
			characterType = typeof(CharacterModel);
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Adds obtained RitsuLib requirement epochs to <see cref="T:MegaCrit.Sts2.Core.Unlocks.UnlockState" /> before multiplayer lobby
	///         synchronization and run setup serialize it.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在多人游戏大厅同步和开局设置序列化 <see cref="T:MegaCrit.Sts2.Core.Unlocks.UnlockState" /> 前，将已获得的 RitsuLib 要求纪元加入其中。
