	///         <see cref="M:MegaCrit.Sts2.Core.Saves.SaveManager.GenerateUnlockStateFromProgress" /> 时，将已获得的要求纪元加入本地主机的大厅状态。
	///     </para>
	/// </summary>
	internal sealed class StartRunLobbyLocalHostUnlockStatePatch : IPatchMethod
	{
		public static string PatchId => "start_run_lobby_local_host_unlock_state";

		public static string Description => "Include obtained mod requirement epochs when serializing the local host player's lobby unlock state";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(StartRunLobby), "AddLocalHostPlayer", new Type[2]
