	/// <summary>
	///     <para xml:lang="en">
	///         Adds obtained mod epoch templates omitted by the base game's Neow-rooted expansion traversal to
	///         <see cref="M:MegaCrit.Sts2.Core.Saves.Managers.ProgressSaveManager.GetRevealableEpochs" />. This lets independent mod story roots contribute to
	///         discovery counts and timeline notifications.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将游戏本体以涅奥为根的扩展遍历所遗漏、但已获得的模组纪元模板加入
	///         <see cref="M:MegaCrit.Sts2.Core.Saves.Managers.ProgressSaveManager.GetRevealableEpochs" />，使独立的模组故事根节点可计入发现数量和时间线通知。
	///     </para>
	/// </summary>
	internal sealed class ProgressSaveManagerGetRevealableEpochsModTemplatePatch : IPatchMethod
	{
		public static string PatchId => "progress_save_manager_get_revealable_epochs_mod_template";

		public static string Description => "Union ModEpochTemplate rows in Obtained/ObtainedNoSlot into GetRevealableEpochs when vanilla omits them";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ProgressSaveManager), "GetRevealableEpochs", Type.EmptyTypes)
			};
		}

		public static IEnumerable<SerializableEpoch> Postfix(IEnumerable<SerializableEpoch> __result, ProgressSaveManager __instance)
		{
			//IL_0050: Unknown result type (might be due to invalid IL or missing references)
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			//IL_0057: Unknown result type (might be due to invalid IL or missing references)
			//IL_005a: Invalid comparison between Unknown and I4
			//IL_005c: Unknown result type (might be due to invalid IL or missing references)
			//IL_005f: Invalid comparison between Unknown and I4
			List<SerializableEpoch> list = __result.ToList();
			HashSet<string> hashSet = new HashSet<string>(list.Select((SerializableEpoch e) => e.Id));
			foreach (SerializableEpoch epoch in __instance.Progress.Epochs)
			{
				EpochState state = epoch.State;
				if (((int)state == 4 || (int)state == 3) && hashSet.Add(epoch.Id))
				{
					EpochModel val;
					try
					{
						val = EpochModel.Get(epoch.Id);
					}
					catch (Exception value)
					{
						RitsuLibFramework.Logger.Warn($"[Unlocks] Could not resolve obtained epoch '{epoch.Id}' while extending revealable epochs: {value}", 1);
						hashSet.Remove(epoch.Id);
						continue;
					}
					if (!(val is ModEpochTemplate))
					{
						hashSet.Remove(epoch.Id);
					}
					else
					{
						list.Add(epoch);
					}
				}
			}
			return list;
		}
	}
