	/// <summary>
	///     <para xml:lang="en">
	///         Removes locked mod events from a generated act's room set when at least one event remains.
	///     </para>
	///     <para xml:lang="zh-CN">生成章节房间集合后，在至少仍保留一个事件的前提下移除已锁定的模组事件。</para>
	/// </summary>
	internal class GeneratedRoomEventUnlockFilterPatch : IPatchMethod
	{
		public static string PatchId => "generated_room_event_unlock_filter";

		public static string Description => "Remove locked mod events after act rooms are generated";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ActModel), "GenerateRooms", new Type[3]
				{
					typeof(Rng),
					typeof(UnlockState),
					typeof(bool)
				})
			};
		}

		public static void Postfix(ActModel __instance, UnlockState unlockState)
		{
			RoomSet val = Rooms(__instance);
			EventModel[] array = val.events.ToArray();
			EventModel[] array2 = array.Where((EventModel eventModel) => ModUnlockRegistry.IsUnlocked((AbstractModel)(object)eventModel, unlockState)).ToArray();
			if (array2.Length != array.Length)
			{
				if (array2.Length == 0)
				{
					RitsuLibFramework.Logger.Warn($"[Unlocks] Filtering generated events for act '{((AbstractModel)__instance).Id}' would leave the pool empty. " + "Keeping the unfiltered pool to avoid a hard failure; ensure at least one event remains unlocked.", 1);
				}
				else
				{
					val.events.Clear();
					val.events.AddRange(array2);
				}
			}
		}

		[UnsafeAccessor(UnsafeAccessorKind.Field, Name = "_rooms")]
		private static extern ref RoomSet Rooms(ActModel instance);
	}
