					return EqualityComparer<RitsuToastVisualStyle>.Default.Equals(StyleOverride, other.StyleOverride);
				}
				return false;
			}
			return true;
		}

		[CompilerGenerated]
		private RitsuToastRequest(RitsuToastRequest original)
		{
			_body = original._body;
			Title = original.Title;
			Image = original.Image;
			Level = original.Level;
			DurationSeconds = original.DurationSeconds;
			OnClick = original.OnClick;
			AnimationOverride = original.AnimationOverride;
			IsPersistent = original.IsPersistent;
			ProgressFraction = original.ProgressFraction;
			DismissOnClick = original.DismissOnClick;
			StyleOverride = original.StyleOverride;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides the global entry point for displaying and managing RitsuLib toast notifications.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供显示和管理 RitsuLib 浮动通知的全局入口。
	///     </para>
	/// </summary>
	public static class RitsuToastService
	{
		private sealed class PendingToast(Guid id, RitsuToastRequest request)
		{
			public Guid Id { get; } = id;

			public RitsuToastRequest Request { get; set; } = request;
		}

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Queue<PendingToast> PendingBeforeHost = new Queue<PendingToast>();

		private static RitsuToastHost? _host;

		private static IDisposable? _lifecycleSubscription;

		private static bool _initialized;

		private static bool _initializing;

		private static bool _themeChangedSubscribed;

		private static RitsuToastSettings _settings = RitsuToastSettings.Default;

		internal static void Initialize()
		{
			using (SyncRoot.EnterScope())
			{
				if (_initialized || _initializing)
				{
					return;
				}
				_initializing = true;
				try
				{
					_settings = RitsuLibSettingsStore.GetToastSettings();
					if (_lifecycleSubscription == null)
					{
						_lifecycleSubscription = RitsuLibFramework.SubscribeLifecycle(delegate(GameReadyEvent evt)
						{
							using (SyncRoot.EnterScope())
							{
								EnsureHostAttached((Node?)(object)evt.Game);
							}
						}, replayCurrentState: false);
					}
					if (!_themeChangedSubscribed)
					{
						RitsuShellThemeRuntime.ThemeChanged += HandleThemeChanged;
						_themeChangedSubscribed = true;
					}
					EnsureHostAttached((Node?)(object)NGame.Instance);
					_initialized = true;
				}
				finally
				{
					_initializing = false;
				}
			}
		}

		internal static void ApplySettings(RitsuToastSettings settings)
		{
			using (SyncRoot.EnterScope())
			{
				_settings = settings;
				if (!settings.Enabled)
				{
					PendingBeforeHost.Clear();
				}
				EnsureHostAttached((Node?)(object)NGame.Instance);
				_host?.ApplySettings(settings);
			}
		}

		internal static void RefreshSettingsFromStore()
		{
			ApplySettings(RitsuLibSettingsStore.GetToastSettings());
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Enqueues a request for display. When toast notifications are enabled but the game host is not ready,
		///         the request remains queued until the host is attached.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将请求加入显示队列。若浮动通知已启用但游戏宿主尚未就绪，请求会保留至宿主挂载完成。
		///     </para>
		/// </summary>
		/// <param name="request">
		///     <para xml:lang="en">The request to display.</para>
		///     <para xml:lang="zh-CN">要显示的请求。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="request" /> is <see langword="null" />.</para>
		///     <para xml:lang="zh-CN"><paramref name="request" /> 为 <see langword="null" />。</para>
		/// </exception>
		public static void Show(RitsuToastRequest request)
		{
			ArgumentNullException.ThrowIfNull(request, "request");
			Initialize();
			using (SyncRoot.EnterScope())
			{
				EnsureHostAttached((Node?)(object)NGame.Instance);
				EnqueueOrStore(Guid.NewGuid(), request);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Enqueues a request and returns a handle for managing the toast.</para>
		///     <para xml:lang="zh-CN">将请求加入队列，并返回用于管理该浮动通知的句柄。</para>
		/// </summary>
		/// <param name="request">
		///     <para xml:lang="en">The request to display.</para>
		///     <para xml:lang="zh-CN">要显示的请求。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         A handle associated with the request. If toast notifications are disabled, the returned handle is
		///         not alive.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         与该请求关联的句柄。若浮动通知已禁用，返回的句柄不会处于有效状态。
		///     </para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="request" /> is <see langword="null" />.</para>
		///     <para xml:lang="zh-CN"><paramref name="request" /> 为 <see langword="null" />。</para>
		/// </exception>
		public static RitsuToastHandle ShowTracked(RitsuToastRequest request)
		{
			ArgumentNullException.ThrowIfNull(request, "request");
			Initialize();
			RitsuToastHandle ritsuToastHandle = new RitsuToastHandle(Guid.NewGuid());
			using (SyncRoot.EnterScope())
			{
				EnsureHostAttached((Node?)(object)NGame.Instance);
				EnqueueOrStore(ritsuToastHandle.Id, request);
				return ritsuToastHandle;
			}
		}

