		/// <summary>
		///     <para xml:lang="en">Restarts a tracked toast timer and optionally replaces its per-toast duration.</para>
		///     <para xml:lang="zh-CN">重新开始已跟踪浮动通知的计时，并可选择替换其单条持续时间。</para>
		/// </summary>
		/// <param name="handle">
		///     <para xml:lang="en">The handle of the toast to reset.</para>
		///     <para xml:lang="zh-CN">要重新计时的浮动通知句柄。</para>
		/// </param>
		/// <param name="durationSeconds">
		///     <para xml:lang="en">
		///         The new duration in seconds, or <see langword="null" /> to reuse the request or global duration.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         新的持续时间（秒）；传入 <see langword="null" /> 可继续使用请求值或全局值。
		///     </para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> if the service found the toast; otherwise, <see langword="false" />.</para>
		///     <para xml:lang="zh-CN">若服务找到了该浮动通知则为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="handle" /> is <see langword="null" />.</para>
		///     <para xml:lang="zh-CN"><paramref name="handle" /> 为 <see langword="null" />。</para>
		/// </exception>
		public static bool ResetDuration(RitsuToastHandle handle, double? durationSeconds = null)
		{
			ArgumentNullException.ThrowIfNull(handle, "handle");
			using (SyncRoot.EnterScope())
			{
				PendingToast pendingToast = FindPending(handle.Id);
				if (pendingToast == null)
				{
					return _host?.ResetDuration(handle.Id, durationSeconds) ?? false;
				}
				if (durationSeconds.HasValue)
				{
					pendingToast.Request = pendingToast.Request.WithDuration(durationSeconds);
				}
				return true;
			}
		}

		private static void EnsureHostAttached(Node? gameNode)
		{
			if ((_host == null || !GodotObject.IsInstanceValid((GodotObject)(object)_host)) && gameNode != null && GodotObject.IsInstanceValid((GodotObject)(object)gameNode))
			{
				_host = new RitsuToastHost();
				gameNode.AddChild((Node)(object)_host, false, (InternalMode)0);
				_host.ApplySettings(_settings);
				while (PendingBeforeHost.Count > 0)
				{
					PendingToast pendingToast = PendingBeforeHost.Dequeue();
					_host.Enqueue(pendingToast.Id, pendingToast.Request);
				}
			}
		}

		private static void HandleThemeChanged()
		{
			using (SyncRoot.EnterScope())
			{
				_host?.RefreshTheme();
			}
		}

		private static void EnqueueOrStore(Guid id, RitsuToastRequest request)
		{
			if (_settings.Enabled)
			{
				if (_host != null && GodotObject.IsInstanceValid((GodotObject)(object)_host))
				{
					_host.Enqueue(id, request);
				}
				else
				{
					PendingBeforeHost.Enqueue(new PendingToast(id, request));
				}
			}
		}

		private static PendingToast? FindPending(Guid id)
		{
			return PendingBeforeHost.FirstOrDefault((PendingToast pending) => pending.Id == id);
		}

		private static bool RemovePending(Guid id)
		{
			bool result = false;
			int count = PendingBeforeHost.Count;
			for (int i = 0; i < count; i++)
			{
				PendingToast pendingToast = PendingBeforeHost.Dequeue();
				if (pendingToast.Id == id)
				{
					result = true;
				}
				else
				{
					PendingBeforeHost.Enqueue(pendingToast);
				}
			}
			return result;
		}
	}
