	/// <summary>
	///     <para xml:lang="en">
	///         Caches parameter-free style boxes and a small number of fixed variants. Each cache is associated
	///         with an immutable <see cref="T:STS2RitsuLib.Ui.Shell.Theme.RitsuShellTheme" /> snapshot, so entries from a replaced theme become
	///         eligible for collection with that snapshot.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         缓存无参数样式框及少量固定变体。每份缓存都与一个不可变的 <see cref="T:STS2RitsuLib.Ui.Shell.Theme.RitsuShellTheme" /> 快照关联，
	///         因此主题被替换后，旧主题的缓存项会随对应快照一起进入可回收状态。
	///     </para>
	///     <para xml:lang="en">
	///         Callers must treat the returned instance as read-only. Any factory whose result is subsequently
	///         modified, such as when deriving a hover variant, must not use this cache.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         调用方必须将返回的实例视为只读。若工厂的结果之后还会被修改（例如用于派生悬停变体），则不得使用此缓存。
	///     </para>
	/// </summary>
	internal static class RitsuShellStyleCache
	{
		private static readonly ConditionalWeakTable<RitsuShellTheme, ConcurrentDictionary<string, StyleBoxFlat>> Cache = new ConditionalWeakTable<RitsuShellTheme, ConcurrentDictionary<string, StyleBoxFlat>>();

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the shared style box identified by <paramref name="key" /> for the current theme, creating
		///         it with <paramref name="build" /> when necessary.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取当前主题中由 <paramref name="key" /> 标识的共享样式框，并在需要时通过
		///         <paramref name="build" /> 创建该样式框。
		///     </para>
		/// </summary>
		/// <param name="key">
		///     <para xml:lang="en">The style key within the current theme snapshot.</para>
		///     <para xml:lang="zh-CN">当前主题快照内的样式键。</para>
		/// </param>
		/// <param name="build">
		///     <para xml:lang="en">The factory used when the key has no cached style box.</para>
		///     <para xml:lang="zh-CN">该键尚无缓存样式框时使用的工厂。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The shared, read-only style-box instance.</para>
		///     <para xml:lang="zh-CN">共享的只读样式框实例。</para>
		/// </returns>
		internal static StyleBoxFlat GetOrBuild(string key, Func<StyleBoxFlat> build)
		{
			ConcurrentDictionary<string, StyleBoxFlat> value = Cache.GetValue(RitsuShellTheme.Current, (RitsuShellTheme _) => new ConcurrentDictionary<string, StyleBoxFlat>(StringComparer.Ordinal));
			if (!value.TryGetValue(key, out var value2))
			{
				return value.GetOrAdd(key, (string _, Func<StyleBoxFlat> factory) => factory(), build);
			}
			return value2;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides paths to the shell-theme directory within global mod data.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供全局模组数据中 Shell 主题目录的路径。
	///     </para>
	/// </summary>
	public static class RitsuShellThemePaths
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets the virtual <c>user://</c> path to the shell-theme directory.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 Shell 主题目录的虚拟 <c>user://</c> 路径。
		///     </para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">The virtual path to the shell-theme directory.</para>
		///     <para xml:lang="zh-CN">Shell 主题目录的虚拟路径。</para>
		/// </returns>
		public static string GetShellThemesDirectoryVirtual()
		{
			return ProfileManager.GetBasePath(SaveScope.Global, 0) + "/shell_themes";
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves the shell-theme directory to an absolute path and creates the directory when necessary.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将 Shell 主题目录解析为绝对路径，并在需要时创建该目录。
		///     </para>
		/// </summary>
		/// <param name="absolutePath">
		///     <para xml:lang="en">
		///         Receives the resolved absolute path. The value may contain the attempted path when the method
		///         returns <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         接收解析后的绝对路径。方法返回 <see langword="false" /> 时，该值仍可能包含尝试使用的路径。
		///     </para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if the directory is available; otherwise, <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若目录可用，则为 <see langword="true" />；否则为 <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool TryEnsureShellThemesDirectory(out string absolutePath)
		{
			absolutePath = "";
			try
			{
				string shellThemesDirectoryVirtual = GetShellThemesDirectoryVirtual();
				absolutePath = ProjectSettings.GlobalizePath(shellThemesDirectoryVirtual);
				Directory.CreateDirectory(absolutePath);
				return true;
			}
			catch
			{
				return false;
			}
		}
	}
