			//IL_0017: Expected O, but got Unknown
			//IL_003d: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ad: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b3: Expected O, but got Unknown
			ArgumentNullException.ThrowIfNull(root, "root");
			RitsuShellTheme current = RitsuShellTheme.Current;
			Theme val = new Theme();
			val.SetStylebox(PanelStyle, TooltipPanelClass, (StyleBox)(object)RitsuShellChromeStyles.CreateTooltipPanelStyle());
			val.SetColor(FontColor, TooltipLabelClass, current.Text.Hint);
			val.SetFont(NormalFont, TooltipLabelClass, current.Font.Body);
			int num = current.Metric.FontSize.Tooltip;
			if (num <= 0)
			{
				num = current.Metric.FontSize.PopupRow;
			}
			val.SetFontSize(FontSize, TooltipLabelClass, num);
			Theme val2;
			if (root.Theme != null)
			{
				val2 = (Theme)((Resource)root.Theme).Duplicate(false);
				val2.MergeWith(val);
			}
			else
			{
				val2 = val;
			}
			root.Theme = val2;
		}

