	internal static class RitsuShellTooltipTiming
	{
		private sealed class Lease(long requestId) : IDisposable
		{
			private long _requestId = requestId;

			public void Dispose()
			{
				long num = Interlocked.Exchange(ref _requestId, 0L);
				if (num != 0L)
				{
					Release(num);
				}
			}
		}

		private const double DefaultDelaySeconds = 0.5;

		private const string TooltipDelaySetting = "gui/timers/tooltip_delay_sec";

		internal const double StandardDelaySeconds = 0.18;

		private static readonly Dictionary<long, double> Requests = new Dictionary<long, double>();

		private static readonly Lock SyncRoot = new Lock();

		private static double _baselineDelay;

		private static double _managedDelay;

		private static bool _settingManaged;

		private static long _nextRequestId;

		internal static IDisposable Acquire(double delaySeconds)
		{
			ArgumentOutOfRangeException.ThrowIfLessThan(delaySeconds, 0.0, "delaySeconds");
			ArgumentOutOfRangeException.ThrowIfGreaterThan(delaySeconds, 0.5, "delaySeconds");
			using (SyncRoot.EnterScope())
			{
				long num = ++_nextRequestId;
				Requests.Add(num, delaySeconds);
				ApplyCurrentRequest();
				return new Lease(num);
			}
		}

		private static void ApplyCurrentRequest()
		{
			//IL_004b: Unknown result type (might be due to invalid IL or missing references)
			//IL_007e: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ad: Unknown result type (might be due to invalid IL or missing references)
			double num = ReadCurrentDelay();
			bool flag = _settingManaged && ApproximatelyEqual(num, _managedDelay);
			if (_settingManaged && !flag)
			{
				_baselineDelay = num;
				_settingManaged = false;
			}
			if (Requests.Count == 0)
			{
				if (flag)
				{
					ProjectSettings.SetSetting("gui/timers/tooltip_delay_sec", Variant.op_Implicit(_baselineDelay));
				}
				_settingManaged = false;
				return;
			}
			double num2 = Requests.Values.Min();
			if (flag)
			{
				if (!ApproximatelyEqual(num, num2))
				{
					ProjectSettings.SetSetting("gui/timers/tooltip_delay_sec", Variant.op_Implicit(num2));
				}
				_managedDelay = num2;
				return;
			}
			if (!_settingManaged)
			{
				_baselineDelay = num;
			}
			if (num <= num2)
			{
				_settingManaged = false;
				return;
			}
			ProjectSettings.SetSetting("gui/timers/tooltip_delay_sec", Variant.op_Implicit(num2));
			_managedDelay = num2;
			_settingManaged = true;
		}

		private static double ReadCurrentDelay()
		{
			//IL_000e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			Variant setting = ProjectSettings.GetSetting("gui/timers/tooltip_delay_sec", Variant.op_Implicit(0.5));
			return ((Variant)(ref setting)).AsDouble();
		}

		private static bool ApproximatelyEqual(double left, double right)
		{
			return Math.Abs(left - right) <= 0.0001;
		}

		private static void Release(long requestId)
		{
			using (SyncRoot.EnterScope())
			{
				if (Requests.Remove(requestId))
				{
					ApplyCurrentRequest();
				}
			}
		}
	}
