	/// <summary>
	///     <para xml:lang="en">
	///         Loads embedded and on-disk <c>.theme.json</c> documents into a catalog, then resolves inheritance,
	///         scope overlays, and token references when building a snapshot.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将内嵌及磁盘上的 <c>.theme.json</c> 文档加载到主题目录，并在构建快照时解析继承关系、
	///         作用域覆盖及令牌引用。
	///     </para>
	/// </summary>
	public static class RitsuShellThemeCatalog
	{
		private const string DefaultThemeId = "default";

		private static readonly Lock Gate = new Lock();

		private static Dictionary<string, RitsuShellThemeDocument>? _byId;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets a new ordinally sorted list of the normalized theme identifiers in the current catalog.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取当前目录中规范化主题标识符的新列表，并按序数顺序排列。
		///     </para>
		/// </summary>
		public static IReadOnlyList<string> RegisteredThemeIds
		{
			get
			{
				string[] array = GetLoadedCatalogSnapshot().Keys.ToArray();
				Array.Sort(array, (IComparer<string>?)StringComparer.Ordinal);
				return array;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Invalidates the in-memory catalog so the next access reloads all themes.</para>
		///     <para xml:lang="zh-CN">使内存中的主题目录失效，以便下次访问时重新加载全部主题。</para>
		/// </summary>
		public static void InvalidateCache()
		{
			using (Gate.EnterScope())
			{
				_byId = null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Loads embedded themes and theme files from disk. Missing embedded files are extracted beside
		///         user-authored themes, and newer embedded revisions replace older disk copies after a
		///         best-effort backup.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         加载内嵌主题及磁盘主题文件。缺失的内嵌主题会提取到用户主题所在目录；若内嵌修订较新，
		///         则会在尽力备份后替换磁盘上的旧副本。
		///     </para>
		/// </summary>
		public static void EnsureLoaded()
		{
			using (Gate.EnterScope())
			{
				if (_byId != null)
				{
					return;
				}
				Dictionary<string, RitsuShellThemeDocument> dictionary = new Dictionary<string, RitsuShellThemeDocument>(StringComparer.Ordinal);
				Assembly assembly = typeof(RitsuShellThemeCatalog).Assembly;
				List<(string, byte[], int)> list = new List<(string, byte[], int)>();
				string[] manifestResourceNames = assembly.GetManifestResourceNames();
				foreach (string text in manifestResourceNames)
				{
					if (!text.EndsWith(".theme.json", StringComparison.OrdinalIgnoreCase))
					{
						continue;
					}
					try
					{
						using Stream stream = assembly.GetManifestResourceStream(text);
						if (stream == null)
						{
							continue;
						}
						using MemoryStream memoryStream = new MemoryStream();
						stream.CopyTo(memoryStream);
						byte[] array = memoryStream.ToArray();
						RitsuShellThemeDocument ritsuShellThemeDocument = RitsuShellThemeDocument.Deserialize(new MemoryStream(array));
						if (ritsuShellThemeDocument != null && !string.IsNullOrWhiteSpace(ritsuShellThemeDocument.Id))
						{
							string text2 = ritsuShellThemeDocument.Id.Trim().ToLowerInvariant();
							dictionary[text2] = ritsuShellThemeDocument;
							list.Add((text2, array, NormalizeThemeVersion(ritsuShellThemeDocument)));
						}
					}
					catch (Exception value)
					{
						RitsuLibFramework.Logger.Warn($"[ShellTheme] Could not load embedded theme resource '{text}': {value}", 1);
					}
				}
				if (RitsuShellThemePaths.TryEnsureShellThemesDirectory(out string absolutePath))
				{
					foreach (var (text3, bytes, embeddedVersion) in list)
					{
						try
						{
							string path = Path.Combine(absolutePath, text3 + ".theme.json");
							if (!File.Exists(path))
							{
								File.WriteAllBytes(path, bytes);
							}
							else if (ShouldOverwriteDiskTheme(path, embeddedVersion))
							{
								TryBackupThemeFile(path);
								File.WriteAllBytes(path, bytes);
							}
						}
						catch (Exception value2)
						{
							RitsuLibFramework.Logger.Warn($"[ShellTheme] Could not extract embedded theme '{text3}' to '{absolutePath}': {value2}", 1);
						}
					}
					try
					{
						foreach (string item in Directory.EnumerateFiles(absolutePath, "*.theme.json", SearchOption.TopDirectoryOnly))
						{
							try
							{
								using FileStream stream2 = File.OpenRead(item);
								RitsuShellThemeDocument ritsuShellThemeDocument2 = RitsuShellThemeDocument.Deserialize(stream2);
								if (ritsuShellThemeDocument2 != null && !string.IsNullOrWhiteSpace(ritsuShellThemeDocument2.Id))
								{
									string key = ritsuShellThemeDocument2.Id.Trim().ToLowerInvariant();
									dictionary[key] = ritsuShellThemeDocument2;
								}
							}
							catch (Exception value3)
							{
								RitsuLibFramework.Logger.Warn($"[ShellTheme] Could not load disk theme '{item}': {value3}", 1);
							}
						}
					}
					catch (Exception value4)
					{
						RitsuLibFramework.Logger.Warn($"[ShellTheme] Could not enumerate disk themes in '{absolutePath}': {value4}", 1);
					}
				}
				_byId = dictionary;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Tries to build a merged, reference-resolved <see cref="T:STS2RitsuLib.Ui.Shell.Theme.RitsuShellTheme" /> snapshot for
		///         <paramref name="themeId" />, including registered mod defaults.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试为 <paramref name="themeId" /> 构建已合并并完成引用解析的
		///         <see cref="T:STS2RitsuLib.Ui.Shell.Theme.RitsuShellTheme" /> 快照，其中包含已注册的模组默认令牌。
		///     </para>
		/// </summary>
		/// <param name="themeId">
		///     <para xml:lang="en">
		///         The case-insensitive theme identifier. A blank value selects <c>default</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         不区分大小写的主题标识符；空白值选择 <c>default</c>。
		///     </para>
		/// </param>
		/// <param name="modRegistrations">
		///     <para xml:lang="en">The registered mod token contributions to merge before theme documents.</para>
		///     <para xml:lang="zh-CN">在主题文档之前合并的已注册模组令牌贡献。</para>
		/// </param>
		/// <param name="resolvedId">
		///     <para xml:lang="en">
		///         Receives the normalized requested identifier, including when the build fails.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         接收规范化后的请求标识符，包括构建失败时。
		///     </para>
		/// </param>
		/// <param name="theme">
		///     <para xml:lang="en">
		///         Receives the completed snapshot on success, or <see langword="null" /> on failure.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         成功时接收构建完成的快照；失败时为 <see langword="null" />。
		///     </para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if the target exists, its inheritance chain is valid, and all token
		///         references resolve; otherwise, <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若目标存在、继承链有效且所有令牌引用均可解析，则为 <see langword="true" />；否则为
		///         <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool TryBuildSnapshot(string themeId, IReadOnlyList<RitsuShellThemeModRegistration> modRegistrations, out string resolvedId, out RitsuShellTheme? theme)
		{
			resolvedId = (string.IsNullOrWhiteSpace(themeId) ? "default" : themeId.Trim().ToLowerInvariant());
			theme = null;
			IReadOnlyDictionary<string, RitsuShellThemeDocument> loadedCatalogSnapshot = GetLoadedCatalogSnapshot();
			if (!loadedCatalogSnapshot.TryGetValue(resolvedId, out var value))
			{
				return false;
			}
			if (!TryResolveInheritanceChain(loadedCatalogSnapshot, value, out List<RitsuShellThemeDocument> chain))
			{
				return false;
			}
			Dictionary<string, object> dictionary = new Dictionary<string, object>(StringComparer.Ordinal);
			Dictionary<string, JsonElement> dictionary2 = new Dictionary<string, JsonElement>(StringComparer.Ordinal);
			foreach (RitsuShellThemeModRegistration modRegistration in modRegistrations)
			{
				if (modRegistration.Defaults.HasValue)
				{
					RitsuShellThemeMerger.MergeInto(dictionary, modRegistration.Defaults.Value);
				}
			}
			foreach (RitsuShellThemeDocument item in chain)
			{
				if (item.Core.HasValue)
				{
					MergeBranch(dictionary, "core", item.Core.Value);
				}
				if (item.Semantic.HasValue)
				{
					MergeBranch(dictionary, "semantic", item.Semantic.Value);
				}
				if (item.Components.HasValue)
				{
					MergeBranch(dictionary, "components", item.Components.Value);
				}
				if (item.Extensions != null)
				{
					foreach (KeyValuePair<string, JsonElement> extension in item.Extensions)
					{
						dictionary2[extension.Key] = extension.Value;
					}
				}
				MergeScopeIfPresent(dictionary, item, "global");
				MergeScopeIfPresent(dictionary, item, "shell");
				MergeScopeIfPresent(dictionary, item, "modSettings");
				if (item.Scopes == null)
				{
					continue;
				}
				foreach (KeyValuePair<string, JsonElement> item2 in item.Scopes.Where<KeyValuePair<string, JsonElement>>((KeyValuePair<string, JsonElement> pair) => pair.Key.StartsWith("mod:", StringComparison.Ordinal)))
				{
					MergeScopeBlock(dictionary, item2.Value, dictionary2);
				}
			}
			List<string> list = new List<string>();
			RitsuShellThemeReferenceResolver.ResolveAll(dictionary, list);
			if (list.Count > 0)
			{
				foreach (string item3 in list)
				{
					RitsuLibFramework.Logger.Warn("[ShellTheme:" + resolvedId + "] " + item3, 1);
				}
				return false;
			}
			theme = RitsuShellThemeBuilder.Build(resolvedId, dictionary, dictionary2);
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Tries to replace one disk theme file with its embedded counterpart.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试使用对应的内嵌主题替换一个磁盘主题文件。
		///     </para>
		/// </summary>
		/// <param name="themeId">
		///     <para xml:lang="en">
		///         The case-insensitive theme identifier to restore. A blank value selects <c>default</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         要恢复的不区分大小写主题标识符；空白值选择 <c>default</c>。
		///     </para>
		/// </param>
		/// <param name="restoredPath">
		///     <para xml:lang="en">
		///         Receives the absolute path of the restored file on success, or an empty string on failure.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         成功时接收已恢复文件的绝对路径；失败时为空字符串。
		///     </para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if an embedded counterpart exists and is written successfully;
		///         otherwise, <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若存在内嵌对应项且成功写入，则为 <see langword="true" />；否则为
		///         <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool TryRestoreDiskThemeFromEmbedded(string themeId, out string restoredPath)
		{
			restoredPath = "";
			string text = (string.IsNullOrWhiteSpace(themeId) ? "default" : themeId.Trim().ToLowerInvariant());
			if (!TryLoadEmbeddedThemeBytes(text, out byte[] bytes))
			{
				return false;
			}
			if (!RitsuShellThemePaths.TryEnsureShellThemesDirectory(out string absolutePath))
			{
				return false;
			}
			try
			{
				restoredPath = Path.Combine(absolutePath, text + ".theme.json");
				File.WriteAllBytes(restoredPath, bytes);
				InvalidateCache();
				return true;
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.Warn($"[ShellTheme] Could not restore embedded theme '{text}': {value}", 1);
				restoredPath = "";
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Tries to replace every existing disk theme that has an embedded counterpart.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试替换所有存在内嵌对应项的现有磁盘主题。
		///     </para>
		/// </summary>
		/// <param name="restoredCount">
		///     <para xml:lang="en">
		///         Receives the number of files replaced before the method completes or fails.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         接收方法完成或失败前已替换的文件数。
		///     </para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if enumeration and all required writes complete; otherwise,
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若枚举及所有必要写入均完成，则为 <see langword="true" />；否则为 <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool TryRestoreAllExistingDiskThemesFromEmbedded(out int restoredCount)
		{
			restoredCount = 0;
			if (!RitsuShellThemePaths.TryEnsureShellThemesDirectory(out string absolutePath))
			{
				return false;
			}
			try
			{
				foreach (var item3 in EnumerateEmbeddedThemeDocuments())
				{
					string item = item3.Id;
					byte[] item2 = item3.Bytes;
					string path = Path.Combine(absolutePath, item + ".theme.json");
					if (File.Exists(path))
					{
						File.WriteAllBytes(path, item2);
						restoredCount++;
					}
				}
				InvalidateCache();
				return true;
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.Warn($"[ShellTheme] Could not restore existing disk themes in '{absolutePath}': {value}", 1);
				return false;
			}
		}

		private static void MergeBranch(Dictionary<string, object?> root, string branchName, JsonElement branch)
		{
			if (branch.ValueKind != JsonValueKind.Object)
			{
				return;
			}
			Dictionary<string, object> dictionary;
			if (root.TryGetValue(branchName, out object value))
			{
				dictionary = value as Dictionary<string, object>;
				if (dictionary != null)
				{
					goto IL_0033;
				}
			}
			dictionary = (Dictionary<string, object>)(root[branchName] = new Dictionary<string, object>(StringComparer.Ordinal));
			goto IL_0033;
			IL_0033:
			RitsuShellThemeMerger.MergeInto(dictionary, branch);
		}

		private static void MergeScopeIfPresent(Dictionary<string, object?> root, RitsuShellThemeDocument doc, string scopeId)
		{
			if (doc.Scopes != null && doc.Scopes.TryGetValue(scopeId, out var value))
			{
				MergeScopeBlock(root, value, null);
			}
		}

		private static void MergeScopeBlock(Dictionary<string, object?> root, JsonElement scope, Dictionary<string, JsonElement>? extensions)
		{
			if (scope.ValueKind != JsonValueKind.Object)
			{
				return;
			}
			foreach (JsonProperty item in scope.EnumerateObject())
			{
				switch (item.Name)
				{
				case "core":
				case "semantic":
				case "components":
					MergeBranch(root, item.Name, item.Value);
					break;
				case "extensions":
					if (extensions == null || item.Value.ValueKind != JsonValueKind.Object)
					{
						break;
					}
					foreach (JsonProperty item2 in item.Value.EnumerateObject())
					{
						extensions[item2.Name] = item2.Value;
					}
					break;
				}
			}
		}

		private static bool TryResolveInheritanceChain(IReadOnlyDictionary<string, RitsuShellThemeDocument> catalog, RitsuShellThemeDocument leaf, out List<RitsuShellThemeDocument> chain)
		{
			chain = new List<RitsuShellThemeDocument>();
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			Stack<RitsuShellThemeDocument> stack = new Stack<RitsuShellThemeDocument>();
			RitsuShellThemeDocument ritsuShellThemeDocument = leaf;
			while (true)
			{
				string item = ritsuShellThemeDocument.Id.Trim().ToLowerInvariant();
				if (!hashSet.Add(item))
				{
					return false;
				}
				stack.Push(ritsuShellThemeDocument);
				if (string.IsNullOrWhiteSpace(ritsuShellThemeDocument.Inherits))
				{
					break;
				}
				string key = ritsuShellThemeDocument.Inherits.Trim().ToLowerInvariant();
				if (!catalog.TryGetValue(key, out RitsuShellThemeDocument value))
				{
					return false;
				}
				ritsuShellThemeDocument = value;
			}
			while (stack.Count > 0)
			{
				chain.Add(stack.Pop());
			}
			return true;
		}

		private static IReadOnlyDictionary<string, RitsuShellThemeDocument> GetLoadedCatalogSnapshot()
		{
			while (true)
			{
				EnsureLoaded();
				using (Gate.EnterScope())
				{
					if (_byId != null)
					{
						return _byId;
					}
				}
			}
		}

		private static bool TryLoadEmbeddedThemeBytes(string normalizedThemeId, out byte[] bytes)
		{
			bytes = Array.Empty<byte>();
			Assembly assembly = typeof(RitsuShellThemeCatalog).Assembly;
			string[] manifestResourceNames = assembly.GetManifestResourceNames();
			foreach (string text in manifestResourceNames)
			{
				if (!text.EndsWith(".theme.json", StringComparison.OrdinalIgnoreCase))
				{
					continue;
				}
				try
				{
					using Stream stream = assembly.GetManifestResourceStream(text);
					if (stream == null)
					{
						continue;
					}
					using MemoryStream memoryStream = new MemoryStream();
					stream.CopyTo(memoryStream);
					byte[] array = memoryStream.ToArray();
					RitsuShellThemeDocument ritsuShellThemeDocument = RitsuShellThemeDocument.Deserialize(new MemoryStream(array));
					if (ritsuShellThemeDocument == null || string.IsNullOrWhiteSpace(ritsuShellThemeDocument.Id) || !string.Equals(ritsuShellThemeDocument.Id.Trim().ToLowerInvariant(), normalizedThemeId, StringComparison.Ordinal))
					{
						continue;
					}
					bytes = array;
					return true;
				}
				catch (Exception value)
				{
					RitsuLibFramework.Logger.Warn($"[ShellTheme] Could not inspect embedded theme resource '{text}': {value}", 1);
				}
			}
			return false;
		}

		private static IEnumerable<(string Id, byte[] Bytes)> EnumerateEmbeddedThemeDocuments()
		{
			Assembly asm = typeof(RitsuShellThemeCatalog).Assembly;
			string[] manifestResourceNames = asm.GetManifestResourceNames();
			foreach (string text in manifestResourceNames)
			{
				if (!text.EndsWith(".theme.json", StringComparison.OrdinalIgnoreCase))
				{
					continue;
				}
				byte[] array;
				RitsuShellThemeDocument ritsuShellThemeDocument;
				try
				{
					using Stream stream = asm.GetManifestResourceStream(text);
					if (stream == null)
					{
						continue;
					}
					using (MemoryStream memoryStream = new MemoryStream())
					{
						stream.CopyTo(memoryStream);
						array = memoryStream.ToArray();
						ritsuShellThemeDocument = RitsuShellThemeDocument.Deserialize(new MemoryStream(array));
					}
					goto IL_010e;
				}
				catch (Exception value)
				{
					RitsuLibFramework.Logger.Warn($"[ShellTheme] Could not enumerate embedded theme resource '{text}': {value}", 1);
				}
				continue;
				IL_010e:
				if (ritsuShellThemeDocument != null && !string.IsNullOrWhiteSpace(ritsuShellThemeDocument.Id))
				{
					yield return (Id: ritsuShellThemeDocument.Id.Trim().ToLowerInvariant(), Bytes: array);
				}
			}
		}

		private static int NormalizeThemeVersion(RitsuShellThemeDocument? doc)
		{
			int? num = doc?.ThemeVersion;
			if (num.HasValue)
			{
				int valueOrDefault = num.GetValueOrDefault();
				if (valueOrDefault > 0)
				{
					return valueOrDefault;
				}
			}
			num = doc?.ThemeFormatVersion;
			if (num.HasValue)
			{
				int valueOrDefault2 = num.GetValueOrDefault();
				if (valueOrDefault2 > 0)
				{
					return valueOrDefault2;
				}
			}
			return 0;
		}

		private static bool ShouldOverwriteDiskTheme(string path, int embeddedVersion)
		{
			if (embeddedVersion <= 0)
			{
				return false;
			}
			try
			{
				using FileStream stream = File.OpenRead(path);
				int num = NormalizeThemeVersion(RitsuShellThemeDocument.Deserialize(stream));
				return embeddedVersion > num;
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.Warn($"[ShellTheme] Could not read disk theme version from '{path}'; the embedded copy will replace it: {value}", 1);
				return true;
			}
		}

		private static void TryBackupThemeFile(string path)
		{
			try
			{
				if (File.Exists(path))
				{
					string destFileName = BuildTimestampedBackupPath(path);
					File.Copy(path, destFileName, overwrite: false);
				}
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.Warn($"[ShellTheme] Could not back up disk theme '{path}' before replacement: {value}", 1);
			}
		}

		private static string BuildTimestampedBackupPath(string originalPath)
		{
			for (int i = 0; i <= 100; i++)
			{
				string text = ((i == 0) ? $"{originalPath}.backup.{DateTime.UtcNow:yyyyMMddHHmmssfff}" : $"{originalPath}.backup.{DateTime.UtcNow:yyyyMMddHHmmssfff}.{i}");
				if (!File.Exists(text))
				{
					return text;
				}
			}
			return $"{originalPath}.backup.{DateTime.UtcNow:yyyyMMddHHmmssfff}.fallback";
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Represents a shell-theme document based on the W3C Design Tokens Format Module. Token groups are
	///         stored as nested JSON objects, and leaf tokens contain <c>$value</c>, <c>$type</c>, and optional
	///         <c>$description</c> properties.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         表示基于 W3C 设计令牌格式模块的 Shell 主题文档。令牌组存储为嵌套 JSON 对象，叶令牌包含
	///         <c>$value</c>、<c>$type</c> 及可选的 <c>$description</c> 属性。
	///     </para>
	/// </summary>
	public sealed class RitsuShellThemeDocument
	{
		private static readonly Lazy<JsonSerializerOptions> DefaultJsonOptions = new Lazy<JsonSerializerOptions>(() => new JsonSerializerOptions
		{
			PropertyNameCaseInsensitive = true
		});

		/// <summary>
		///     <para xml:lang="en">Gets or sets the optional <c>$schema</c> URL used by editors.</para>
		///     <para xml:lang="zh-CN">获取或设置供编辑器使用的可选 <c>$schema</c> URL。</para>
		/// </summary>
		[JsonPropertyName("$schema")]
		public string? SchemaReference { get; set; }

		/// <summary>
		///     <para xml:lang="en">Gets or sets the theme format version, currently <c>1</c>.</para>
		///     <para xml:lang="zh-CN">获取或设置主题格式版本，当前为 <c>1</c>。</para>
		/// </summary>
		[JsonPropertyName("themeFormatVersion")]
		public int? ThemeFormatVersion { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or sets the content revision used to upgrade extracted theme files. A newer embedded
		///         revision replaces an older disk copy.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或设置用于升级已提取主题文件的内容修订号。内嵌主题的修订号较新时会替换磁盘上的旧副本。
		///     </para>
		/// </summary>
		[JsonPropertyName("themeVersion")]
		public int? ThemeVersion { get; set; }

		/// <summary>
		///     <para xml:lang="en">Gets or sets the theme's lowercase identifier.</para>
		///     <para xml:lang="zh-CN">获取或设置主题的小写标识符。</para>
		/// </summary>
		[JsonPropertyName("id")]
		public string Id { get; set; } = "";

		/// <summary>
		///     <para xml:lang="en">Gets or sets the human-readable name shown in theme selectors.</para>
		///     <para xml:lang="zh-CN">获取或设置在主题选择器中显示的易读名称。</para>
		/// </summary>
		[JsonPropertyName("displayName")]
		public string? DisplayName { get; set; }

		/// <summary>
		///     <para xml:lang="en">Gets or sets the optional parent theme over which this theme is layered.</para>
		///     <para xml:lang="zh-CN">获取或设置可选的父主题；当前主题将叠加在该主题之上。</para>
		/// </summary>
		[JsonPropertyName("inherits")]
		public string? Inherits { get; set; }

		/// <summary>
		///     <para xml:lang="en">Gets or sets the primitive token group.</para>
		///     <para xml:lang="zh-CN">获取或设置基础令牌组。</para>
		/// </summary>
		[JsonPropertyName("core")]
		public JsonElement? Core { get; set; }

		/// <summary>
		///     <para xml:lang="en">Gets or sets the semantic and alias token group.</para>
		///     <para xml:lang="zh-CN">获取或设置语义令牌及别名令牌组。</para>
		/// </summary>
		[JsonPropertyName("semantic")]
		public JsonElement? Semantic { get; set; }

		/// <summary>
		///     <para xml:lang="en">Gets or sets component tokens organized by component, variant, and state.</para>
		///     <para xml:lang="zh-CN">获取或设置按组件、变体及状态组织的组件令牌。</para>
		/// </summary>
		[JsonPropertyName("components")]
		public JsonElement? Components { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or sets overrides keyed by scope, including <c>shell</c>, <c>modSettings</c>, and
		///         <c>mod:&lt;modId&gt;</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或设置按作用域索引的覆盖，包括 <c>shell</c>、<c>modSettings</c> 和
		///         <c>mod:&lt;modId&gt;</c>。
		///     </para>
		/// </summary>
		[JsonPropertyName("scopes")]
		public Dictionary<string, JsonElement>? Scopes { get; set; }

		/// <summary>
		///     <para xml:lang="en">Gets or sets free-form extension data keyed by mod identifier.</para>
		///     <para xml:lang="zh-CN">获取或设置按模组标识符索引的自由格式扩展数据。</para>
		/// </summary>
		[JsonPropertyName("extensions")]
		public Dictionary<string, JsonElement>? Extensions { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Deserializes a <see cref="T:STS2RitsuLib.Ui.Shell.Theme.RitsuShellThemeDocument" /> from JSON, matching property names
		///         case-insensitively.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从 JSON 反序列化 <see cref="T:STS2RitsuLib.Ui.Shell.Theme.RitsuShellThemeDocument" />，匹配属性名时不区分大小写。
		///     </para>
		/// </summary>
		/// <param name="stream">
		///     <para xml:lang="en">The readable stream containing the JSON document.</para>
		///     <para xml:lang="zh-CN">包含 JSON 文档的可读流。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         The deserialized document, or <see langword="null" /> if the JSON root is <c>null</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         反序列化后的文档；JSON 根值为 <c>null</c> 时为 <see langword="null" />。
		///     </para>
		/// </returns>
		/// <exception cref="T:System.Text.Json.JsonException">
		///     <para xml:lang="en">The JSON is invalid or cannot be converted to a theme document.</para>
		///     <para xml:lang="zh-CN">JSON 无效或无法转换为主题文档。</para>
		/// </exception>
		public static RitsuShellThemeDocument? Deserialize(Stream stream)
		{
			return JsonSerializer.Deserialize<RitsuShellThemeDocument>(stream, DefaultJsonOptions.Value);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Stores resolved left, top, right, and bottom edge values.</para>
	///     <para xml:lang="zh-CN">存储已解析的左、上、右、下边缘值。</para>
	/// </summary>
	internal readonly record struct BoxEdges(int Left, int Top, int Right, int Bottom);
	/// <summary>
	///     <para xml:lang="en">
	///         Stores the resolved top-left, top-right, bottom-right, and bottom-left corner radii of a
	///         <see cref="T:Godot.StyleBoxFlat" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         存储 <see cref="T:Godot.StyleBoxFlat" /> 已解析的左上、右上、右下及左下圆角半径。
	///     </para>
	/// </summary>
	internal readonly record struct BoxCorners(int TopLeft, int TopRight, int BottomRight, int BottomLeft);
	/// <summary>
	///     <para xml:lang="en">
	///         Resolves optional layout tokens against fallback values for the current shell theme.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         根据当前 Shell 主题解析可选布局令牌，并在令牌不可用时使用备用值。
	///     </para>
	/// </summary>
	internal static class RitsuShellThemeLayoutResolver
	{
		private readonly record struct BoxMemoKey(string BasePath, int Fallback);

		private sealed class ThemeBoxMemo
		{
			public readonly ConcurrentDictionary<BoxMemoKey, BoxCorners> Corners = new ConcurrentDictionary<BoxMemoKey, BoxCorners>();

			public readonly ConcurrentDictionary<BoxMemoKey, BoxEdges> Edges = new ConcurrentDictionary<BoxMemoKey, BoxEdges>();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Caches resolved edge and corner sets by theme snapshot, token path, and fallback value. When a
		///         snapshot is replaced, its cache becomes eligible for collection with the snapshot.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         按主题快照、令牌路径及备用值缓存已解析的边缘和圆角集合。主题快照被替换后，对应缓存会随快照一起
		///         进入可回收状态。
		///     </para>
		/// </summary>
		private static readonly ConditionalWeakTable<RitsuShellTheme, ThemeBoxMemo> BoxMemos = new ConditionalWeakTable<RitsuShellTheme, ThemeBoxMemo>();

		private static ThemeBoxMemo MemoFor(RitsuShellTheme theme)
		{
			return BoxMemos.GetValue(theme, (RitsuShellTheme _) => new ThemeBoxMemo());
		}

		internal static int ResolveInt(string path, int fallback)
		{
			if (RitsuShellTheme.Current.TryGetNumber(path, out var value))
			{
				double num = Math.Round(value);
				if (num >= -2147483648.0 && num <= 2147483647.0)
				{
					return (int)num;
				}
			}
			return fallback;
		}

		internal static float ResolveFloat(string path, float fallback)
		{
			if (!RitsuShellTheme.Current.TryGetNumber(path, out var value) || !(value >= -3.4028234663852886E+38) || !(value <= 3.4028234663852886E+38))
			{
				return fallback;
			}
			return (float)value;
		}

		internal static BoxEdges ResolveEdges(string basePath, int fallbackAll)
		{
			return MemoFor(RitsuShellTheme.Current).Edges.GetOrAdd(new BoxMemoKey(basePath, fallbackAll), (BoxMemoKey key) => ComputeEdges(key.BasePath, key.Fallback));
		}

		private static BoxEdges ComputeEdges(string basePath, int fallbackAll)
		{
			int fallback = ResolveInt(basePath, fallbackAll);
			fallback = ResolveInt(basePath + ".all", fallback);
			int left = ResolveInt(basePath + ".left", fallback);
			int top = ResolveInt(basePath + ".top", fallback);
			int right = ResolveInt(basePath + ".right", fallback);
			int bottom = ResolveInt(basePath + ".bottom", fallback);
			return new BoxEdges(left, top, right, bottom);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves corner radii beneath <paramref name="basePath" />, applying an optional <c>all</c>
		///         value before the individual corner values.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         解析 <paramref name="basePath" /> 下的圆角半径，先应用可选的 <c>all</c> 值，再应用各个角的值。
		///     </para>
		/// </summary>
		/// <param name="basePath">
		///     <para xml:lang="en">The base path of the corner-radius token group.</para>
		///     <para xml:lang="zh-CN">圆角半径令牌组的基础路径。</para>
		/// </param>
		/// <param name="fallbackUniform">
		///     <para xml:lang="en">The value used for all corners when no applicable token exists.</para>
		///     <para xml:lang="zh-CN">没有适用令牌时用于全部圆角的值。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The resolved radii for all four corners.</para>
		///     <para xml:lang="zh-CN">四个角的已解析半径。</para>
		/// </returns>
		internal static BoxCorners ResolveCornerRadii(string basePath, int fallbackUniform)
		{
			return MemoFor(RitsuShellTheme.Current).Corners.GetOrAdd(new BoxMemoKey(basePath, fallbackUniform), (BoxMemoKey key) => ComputeCornerRadii(key.BasePath, key.Fallback));
		}

		private static BoxCorners ComputeCornerRadii(string basePath, int fallbackUniform)
		{
			int fallback = ResolveInt(basePath, fallbackUniform);
			fallback = ResolveInt(basePath + ".all", fallback);
			int topLeft = ResolveInt(basePath + ".topLeft", fallback);
			int topRight = ResolveInt(basePath + ".topRight", fallback);
			int bottomRight = ResolveInt(basePath + ".bottomRight", fallback);
			int bottomLeft = ResolveInt(basePath + ".bottomLeft", fallback);
			return new BoxCorners(topLeft, topRight, bottomRight, bottomLeft);
		}

		internal static Vector2 ResolveMinSize(string basePath, Vector2 fallback, bool allowOverride = true)
		{
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			//IL_0039: Unknown result type (might be due to invalid IL or missing references)
			//IL_0059: Unknown result type (might be due to invalid IL or missing references)
			//IL_0003: Unknown result type (might be due to invalid IL or missing references)
			if (!allowOverride)
			{
				return fallback;
			}
			float fallback2 = ResolveFloat(basePath + ".width", fallback.X);
			fallback2 = ResolveFloat(basePath + ".minWidth", fallback2);
			float fallback3 = ResolveFloat(basePath + ".height", fallback.Y);
			fallback3 = ResolveFloat(basePath + ".minHeight", fallback3);
			return new Vector2(fallback2, fallback3);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Deep-merges Design Tokens Format Module token trees while preserving leaf-token boundaries.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         深度合并设计令牌格式模块令牌树，同时保留叶令牌边界。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Group objects without <c>$value</c> are merged recursively. Leaf objects containing
	///         <c>$value</c>, arrays, and scalar values replace the corresponding base value as a unit.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         不含 <c>$value</c> 的分组对象会递归合并；含 <c>$value</c> 的叶对象、数组及标量值会整体替换
	///         基础树中的对应值。
	///     </para>
	/// </remarks>
	internal static class RitsuShellThemeMerger
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Merges <paramref name="overlay" /> over <paramref name="baseTree" /> in place. New keys are
		///         added; overlapping groups are merged recursively, while leaves and other values are replaced.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将 <paramref name="overlay" /> 原地叠加到 <paramref name="baseTree" />。新键会被添加；
		///         重叠的分组会递归合并，叶令牌及其他值则会被替换。
		///     </para>
		/// </summary>
		/// <param name="baseTree">
		///     <para xml:lang="en">The mutable base tree to update.</para>
		///     <para xml:lang="zh-CN">要更新的可变基础树。</para>
		/// </param>
		/// <param name="overlay">
		///     <para xml:lang="en">
		///         The overlay JSON object. A non-object value leaves <paramref name="baseTree" /> unchanged.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         用作覆盖的 JSON 对象；若不是对象，则不会更改 <paramref name="baseTree" />。
		///     </para>
		/// </param>
		public static void MergeInto(Dictionary<string, object?> baseTree, JsonElement overlay)
		{
			if (overlay.ValueKind != JsonValueKind.Object)
			{
				return;
			}
			foreach (JsonProperty item in overlay.EnumerateObject())
			{
				string name = item.Name;
				JsonElement value = item.Value;
				if (IsLeafToken(value))
				{
					baseTree[name] = CloneLeaf(value);
					continue;
				}
				if (value.ValueKind != JsonValueKind.Object)
				{
					baseTree[name] = ClonePrimitive(value);
					continue;
				}
				if (baseTree.TryGetValue(name, out object value2) && value2 is Dictionary<string, object> baseTree2)
				{
					MergeInto(baseTree2, value);
					continue;
				}
				Dictionary<string, object> dictionary = new Dictionary<string, object>(StringComparer.Ordinal);
				MergeInto(dictionary, value);
				baseTree[name] = dictionary;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Determines whether <paramref name="element" /> is an object containing <c>$value</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         确定 <paramref name="element" /> 是否为包含 <c>$value</c> 的对象。
		///     </para>
		/// </summary>
		/// <param name="element">
		///     <para xml:lang="en">The JSON element to inspect.</para>
		///     <para xml:lang="zh-CN">要检查的 JSON 元素。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if the element is a leaf token; otherwise, <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若该元素为叶令牌，则为 <see langword="true" />；否则为 <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool IsLeafToken(JsonElement element)
		{
			JsonElement value;
			if (element.ValueKind == JsonValueKind.Object)
			{
				return element.TryGetProperty("$value", out value);
			}
			return false;
		}

		private static object? ClonePrimitive(JsonElement element)
		{
			long value;
			return element.ValueKind switch
			{
				JsonValueKind.String => element.GetString(), 
				JsonValueKind.Number => element.TryGetInt64(out value) ? ((double)value) : element.GetDouble(), 
				JsonValueKind.True => true, 
				JsonValueKind.False => false, 
				JsonValueKind.Null => null, 
				_ => element.Clone(), 
			};
		}

		private static LeafToken CloneLeaf(JsonElement element)
		{
			string type = null;
			string description = null;
			object value = null;
			JsonElement? extensions = null;
			foreach (JsonProperty item in element.EnumerateObject())
			{
				switch (item.Name)
				{
				case "$type":
					type = item.Value.GetString();
					break;
				case "$description":
					description = item.Value.GetString();
					break;
				case "$value":
					value = ClonePrimitive(item.Value);
					break;
				case "$extensions":
					extensions = item.Value.Clone();
					break;
				}
			}
			return new LeafToken(value, type, description, extensions);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Represents a cloned leaf token after merging. Scalar <c>$value</c> properties are stored as CLR
	///         values, while composite values and extension data retain independent <see cref="T:System.Text.Json.JsonElement" />
	///         clones.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         表示合并后克隆的叶令牌。标量 <c>$value</c> 属性存储为 CLR 值，复合值及扩展数据则保留为独立的
	///         <see cref="T:System.Text.Json.JsonElement" /> 克隆。
	///     </para>
	/// </summary>
	/// <param name="Value">
	///     <para xml:lang="en">
	///         The raw token value: a string, number, Boolean, <see langword="null" />, or cloned composite JSON.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         原始令牌值：字符串、数值、布尔值、<see langword="null" /> 或克隆后的复合 JSON。
	///     </para>
	/// </param>
	/// <param name="Type">
	///     <para xml:lang="en">
	///         The optional token type, such as <c>color</c>, <c>dimension</c>, or <c>fontFamily</c>.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         可选的令牌类型，例如 <c>color</c>、<c>dimension</c> 或 <c>fontFamily</c>。
	///     </para>
	/// </param>
	/// <param name="Description">
	///     <para xml:lang="en">The optional human-readable description.</para>
	///     <para xml:lang="zh-CN">可选的易读说明。</para>
	/// </param>
	/// <param name="Extensions">
	///     <para xml:lang="en">The optional cloned <c>$extensions</c> vendor metadata.</para>
	///     <para xml:lang="zh-CN">可选的已克隆 <c>$extensions</c> 供应方元数据。</para>
	/// </param>
	internal sealed record LeafToken(object? Value, string? Type, string? Description, JsonElement? Extensions);
	/// <summary>
	///     <para xml:lang="en">
	///         Describes a mod's default token contribution and optional callback for newly published
	///         shell-theme snapshots.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         描述模组贡献的默认令牌，以及可选的 Shell 主题新快照发布回调。
	///     </para>
	/// </summary>
	/// <param name="ModId">
	///     <para xml:lang="en">
	///         The mod identifier used by <c>scopes.mod:&lt;modId&gt;</c> and extension data.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         <c>scopes.mod:&lt;modId&gt;</c> 及扩展数据使用的模组标识符。
	///     </para>
	/// </param>
	/// <param name="Defaults">
	///     <para xml:lang="en">
	///         The optional Design Tokens Format Module object merged before the selected theme's inheritance
	///         chain.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         可选的设计令牌格式模块对象，会在所选主题的继承链之前合并。
	///     </para>
	/// </param>
	/// <param name="OnApply">
	///     <para xml:lang="en">The optional callback invoked after a rebuilt snapshot is published.</para>
	///     <para xml:lang="zh-CN">重建后的快照发布后调用的可选回调。</para>
	/// </param>
	public sealed record RitsuShellThemeModRegistration(string ModId, JsonElement? Defaults, Action<RitsuShellTheme>? OnApply);
	/// <summary>
	///     <para xml:lang="en">
	///         Resolves whole-value W3C Design Tokens references such as <c>{path.to.token}</c> within a merged
	///         token tree. Each reference must identify a leaf token.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在合并后的令牌树中解析形如 <c>{path.to.token}</c> 的 W3C 设计令牌整值引用。
	///         每个引用都必须指向一个叶令牌。
	///     </para>
	/// </summary>
	internal static class RitsuShellThemeReferenceResolver
	{
		private static readonly Regex SingleReferenceRegex = GetSingleReferenceRegex();

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves all whole-value references in <paramref name="root" /> in place. Missing targets and
		///         cycles append diagnostics to <paramref name="errors" /> and leave the affected reference
		///         unresolved.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         原地解析 <paramref name="root" /> 中的所有整值引用。目标缺失或出现循环引用时，会向
		///         <paramref name="errors" /> 添加诊断，并保留受影响的未解析引用。
		///     </para>
		/// </summary>
		/// <param name="root">
		///     <para xml:lang="en">The merged token tree to update.</para>
		///     <para xml:lang="zh-CN">要更新的合并令牌树。</para>
		/// </param>
		/// <param name="errors">
		///     <para xml:lang="en">The collection that receives reference diagnostics.</para>
		///     <para xml:lang="zh-CN">接收引用诊断的集合。</para>
		/// </param>
		public static void ResolveAll(Dictionary<string, object?> root, IList<string> errors)
		{
			HashSet<string> visiting = new HashSet<string>(StringComparer.Ordinal);
			ResolveGroup(root, root, "", visiting, errors);
		}

		private static void ResolveGroup(Dictionary<string, object?> root, Dictionary<string, object?> group, string path, HashSet<string> visiting, IList<string> errors)
		{
			foreach (string item in group.Keys.ToList())
			{
				object obj = group[item];
				string text = ((path.Length == 0) ? item : (path + "." + item));
				if (!(obj is LeafToken leaf))
				{
					if (obj is Dictionary<string, object> dictionary)
					{
						ResolveGroup(root, dictionary, text, visiting, errors);
					}
				}
				else
				{
					group[item] = ResolveLeaf(root, leaf, text, visiting, errors);
				}
			}
		}

		private static LeafToken ResolveLeaf(Dictionary<string, object?> root, LeafToken leaf, string ownPath, HashSet<string> visiting, IList<string> errors)
		{
			if (!(leaf.Value is string input))
			{
				return leaf;
			}
			Match match = SingleReferenceRegex.Match(input);
			if (!match.Success)
			{
				return leaf;
			}
			string text = match.Groups[1].Value.Trim();
			if (!visiting.Add(ownPath))
			{
				errors.Add("Theme reference cycle at '" + ownPath + "'.");
				return leaf;
			}
			try
			{
				if (!TryFindLeaf(root, text, out LeafToken leaf2))
				{
					errors.Add($"Theme reference '{text}' (from '{ownPath}') did not resolve to a leaf.");
					return leaf;
				}
				LeafToken leafToken = ResolveLeaf(root, leaf2, text, visiting, errors);
				return leaf with
				{
					Value = leafToken.Value,
					Type = (leaf.Type ?? leafToken.Type)
				};
			}
			finally
			{
				visiting.Remove(ownPath);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Tries to find a leaf token by dotted path, such as <c>core.color.amber.500</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试按点分路径查找叶令牌，例如 <c>core.color.amber.500</c>。
		///     </para>
		/// </summary>
		/// <param name="root">
		///     <para xml:lang="en">The token tree to search.</para>
		///     <para xml:lang="zh-CN">要搜索的令牌树。</para>
		/// </param>
		/// <param name="path">
		///     <para xml:lang="en">The dotted path to the expected leaf.</para>
		///     <para xml:lang="zh-CN">指向预期叶令牌的点分路径。</para>
		/// </param>
		/// <param name="leaf">
		///     <para xml:lang="en">
		///         Receives the matching leaf token, or <see langword="null" /> when the lookup fails.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         接收匹配的叶令牌；查找失败时为 <see langword="null" />。
		///     </para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if the path resolves to a leaf token; otherwise,
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若路径解析到叶令牌，则为 <see langword="true" />；否则为 <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool TryFindLeaf(Dictionary<string, object?> root, string path, out LeafToken? leaf)
		{
			leaf = null;
			object value = root;
			string[] array = path.Split('.', StringSplitOptions.RemoveEmptyEntries);
			foreach (string key in array)
			{
				if (!(value is Dictionary<string, object> dictionary))
				{
					return false;
				}
				if (!dictionary.TryGetValue(key, out value))
				{
					return false;
				}
			}
			if (!(value is LeafToken leafToken))
			{
				return false;
			}
			leaf = leafToken;
			return true;
		}

		/// <remarks>
		/// Pattern:<br />
		/// <code>^\\s*\\{\\s*([^{}]+?)\\s*\\}\\s*$</code><br />
		/// Options:<br />
		/// <code>RegexOptions.Compiled</code><br />
		/// Explanation:<br />
		/// <code>
		/// ○ Match if at the beginning of the string.<br />
		/// ○ Match a whitespace character atomically any number of times.<br />
		/// ○ Match '{'.<br />
		/// ○ Match a whitespace character greedily any number of times.<br />
		/// ○ 1st capture group.<br />
		///     ○ Match a character in the set [^{}] lazily at least once.<br />
		/// ○ Match a whitespace character atomically any number of times.<br />
		/// ○ Match '}'.<br />
		/// ○ Match a whitespace character greedily any number of times.<br />
		/// ○ Match if at the end of the string or if before an ending newline.<br />
		/// </code>
		/// </remarks>
		[GeneratedRegex("^\\s*\\{\\s*([^{}]+?)\\s*\\}\\s*$", RegexOptions.Compiled)]
		[GeneratedCode("System.Text.RegularExpressions.Generator", "9.0.14.31522")]
		private static Regex GetSingleReferenceRegex()
		{
			return <RegexGenerator_g>F7F0BFA5D4E3AD299CF17F00EC305F23D34F417D205E2CC8C3F49C1C369614C75__GetSingleReferenceRegex_6.Instance;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Manages the current shell-theme snapshot, theme application and reloads, change notifications,
	///         and mod token registrations. Public state transitions are synchronized.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         管理当前 Shell 主题快照、主题应用与重新加载、变更通知及模组令牌注册。公开的状态转换均会同步。
	///     </para>
	/// </summary>
	public static class RitsuShellThemeRuntime
	{
		private const string DefaultThemeId = "default";

		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<string, RitsuShellThemeModRegistration> ModRegistrations = new Dictionary<string, RitsuShellThemeModRegistration>(StringComparer.OrdinalIgnoreCase);

		private static RitsuShellTheme? _current;

		private static bool _fontSnapshotInvalidated;

		private static bool _fontRefreshQueued;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the normalized identifier of the active snapshot. The initial value is <c>default</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取当前活动快照的规范化标识符；初始值为 <c>default</c>。
		///     </para>
		/// </summary>
		public static string ActiveThemeId { get; private set; } = "default";

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the current theme snapshot. The first access builds <c>default</c> when necessary, and
		///         later accesses rebuild invalidated font resources lazily.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取当前主题快照。首次访问会在需要时构建 <c>default</c>；后续访问会延迟重建已失效的字体资源。
		///     </para>
		/// </summary>
		public static RitsuShellTheme Current
		{
			get
			{
				EnsureBaseline();
				EnsureCurrentSnapshotResourcesValid();
				return _current;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Occurs after <see cref="M:STS2RitsuLib.Ui.Shell.Theme.RitsuShellThemeRuntime.ApplyThemeId(System.String)" /> successfully publishes a snapshot.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <see cref="M:STS2RitsuLib.Ui.Shell.Theme.RitsuShellThemeRuntime.ApplyThemeId(System.String)" /> 成功发布主题快照后发生。
		///     </para>
		/// </summary>
		public static event Action? ThemeChanged;

		/// <summary>
		///     <para xml:lang="en">
		///         Builds and publishes the <c>default</c> baseline snapshot if no snapshot exists.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若尚无主题快照，则构建并发布 <c>default</c> 基线快照。
		///     </para>
		/// </summary>
		public static void EnsureBaseline()
		{
			using (Gate.EnterScope())
			{
				if (_current == null && TryBuildSnapshotLocked("default", out string resolvedId, out RitsuShellTheme theme))
				{
					_current = theme;
					ActiveThemeId = resolvedId;
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Applies a theme by identifier. A <see langword="null" /> or blank value selects
		///         <c>default</c>. If the requested theme cannot be built, the method tries <c>default</c>;
		///         if that also fails, the current snapshot is preserved.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         按标识符应用主题。<see langword="null" /> 或空白值选择 <c>default</c>。请求的主题无法构建时，
		///         方法会尝试 <c>default</c>；若后者也失败，则保留当前快照。
		///     </para>
		/// </summary>
		/// <param name="themeId">
		///     <para xml:lang="en">The case-insensitive theme identifier to apply.</para>
		///     <para xml:lang="zh-CN">要应用的不区分大小写主题标识符。</para>
		/// </param>
		public static void ApplyThemeId(string? themeId)
		{
			RitsuShellTheme theme;
			using (Gate.EnterScope())
			{
				if (!TryBuildSnapshotLocked(themeId ?? "default", out string resolvedId, out theme) && !TryBuildSnapshotLocked("default", out resolvedId, out theme))
				{
					return;
				}
				_current = theme;
				ActiveThemeId = resolvedId;
				_fontSnapshotInvalidated = false;
			}
			NotifyChanged(theme);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Clears cached fonts and reapplies <see cref="P:STS2RitsuLib.Ui.Shell.Theme.RitsuShellThemeRuntime.ActiveThemeId" />, optionally invalidating the
		///         catalog first so disk changes are loaded.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         清除缓存的字体并重新应用 <see cref="P:STS2RitsuLib.Ui.Shell.Theme.RitsuShellThemeRuntime.ActiveThemeId" />；可选择先使主题目录失效，以加载磁盘变更。
		///     </para>
		/// </summary>
		/// <param name="forceReloadCatalog">
		///     <para xml:lang="en">
		///         <see langword="true" /> to reload embedded and on-disk theme documents.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若要重新加载内嵌及磁盘主题文档，则为 <see langword="true" />。
		///     </para>
		/// </param>
		public static void ReapplyActiveTheme(bool forceReloadCatalog)
		{
			if (forceReloadCatalog)
			{
				RitsuShellThemeCatalog.InvalidateCache();
			}
			RitsuShellThemeValueCoerce.InvalidateFontCache();
			ApplyThemeId(ActiveThemeId);
		}

		internal static void NotifyExternalFontCacheCleared()
		{
			//IL_004e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0053: Unknown result type (might be due to invalid IL or missing references)
			using (Gate.EnterScope())
			{
				_fontSnapshotInvalidated = true;
				RitsuShellThemeValueCoerce.InvalidateFontCache();
				if (_fontRefreshQueued)
				{
					return;
				}
				_fontRefreshQueued = true;
			}
			try
			{
				Callable val = Callable.From((Action)FlushExternalFontCacheCleared);
				((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			}
			catch (Exception value)
			{
				using (Gate.EnterScope())
				{
					_fontRefreshQueued = false;
				}
				RitsuLibFramework.Logger.Warn($"[ShellTheme] Could not defer the external font-cache refresh: {value}", 1);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers or replaces a mod's default token contribution and optional apply callback, then
		///         reapplies the active theme. Registered defaults are merged before the selected theme's
		///         inheritance chain.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册或替换模组的默认令牌贡献及可选应用回调，然后重新应用当前主题。已注册的默认令牌会在所选主题的
		///         继承链之前合并。
		///     </para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">
		///         The case-insensitive mod identifier. Surrounding whitespace is removed; a blank value is ignored.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         不区分大小写的模组标识符。首尾空白会被移除；空白值会被忽略。
