		///     </para>
		/// </param>
		public static void RegisterModTokens(string modId, JsonElement? defaults, Action<RitsuShellTheme>? onApply = null)
		{
			if (!string.IsNullOrWhiteSpace(modId))
			{
				string text = modId.Trim();
				JsonElement? defaults2 = defaults?.Clone();
				using (Gate.EnterScope())
				{
					ModRegistrations[text] = new RitsuShellThemeModRegistration(text, defaults2, onApply);
				}
				ReapplyActiveTheme(forceReloadCatalog: false);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Removes a mod token registration and reapplies the active theme when an entry was present.
		///     </para>
		///     <para xml:lang="zh-CN">
