		///     </para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">
		///         The case-insensitive mod identifier. Surrounding whitespace is removed; a blank value is ignored.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         不区分大小写的模组标识符。首尾空白会被移除；空白值会被忽略。
		///     </para>
		/// </param>
		public static void UnregisterModTokens(string modId)
		{
			if (string.IsNullOrWhiteSpace(modId))
			{
				return;
			}
			string key = modId.Trim();
			using (Gate.EnterScope())
			{
				if (!ModRegistrations.Remove(key))
				{
					return;
				}
			}
			ReapplyActiveTheme(forceReloadCatalog: false);
		}

		private static bool TryBuildSnapshotLocked(string themeId, out string resolvedId, out RitsuShellTheme? theme)
		{
			RitsuShellThemeModRegistration[] modRegistrations = ModRegistrations.Values.ToArray();
			return RitsuShellThemeCatalog.TryBuildSnapshot(themeId, modRegistrations, out resolvedId, out theme);
		}

		private static void EnsureCurrentSnapshotResourcesValid()
		{
			using (Gate.EnterScope())
			{
				if (_current != null && (_fontSnapshotInvalidated || !AreThemeFontsValid(_current.Font) || !RitsuShellThemeValueCoerce.AreFontTokensCurrent(_current.Font)))
				{
					if (TryBuildSnapshotLocked(ActiveThemeId, out string resolvedId, out RitsuShellTheme theme) && theme != null)
					{
						_current = theme;
						ActiveThemeId = resolvedId;
						_fontSnapshotInvalidated = false;
					}
					else if (TryBuildSnapshotLocked("default", out resolvedId, out theme) && theme != null)
					{
						_current = theme;
						ActiveThemeId = resolvedId;
						_fontSnapshotInvalidated = false;
					}
				}
			}
		}

		private static bool AreThemeFontsValid(FontTokens fonts)
		{
			if (GodotObject.IsInstanceValid((GodotObject)(object)fonts.Body) && GodotObject.IsInstanceValid((GodotObject)(object)fonts.BodyBold))
			{
				return GodotObject.IsInstanceValid((GodotObject)(object)fonts.Button);
			}
			return false;
		}

		private static void NotifyChanged(RitsuShellTheme snapshot)
		{
			RitsuShellThemeModRegistration[] array;
			using (Gate.EnterScope())
			{
				array = ModRegistrations.Values.ToArray();
			}
			Delegate[] array2 = ThemeChanged?.GetInvocationList();
			if (array2 != null)
			{
				Delegate[] array3 = array2;
				foreach (Delegate obj in array3)
				{
					try
					{
						((Action)obj)();
					}
					catch (Exception value)
					{
						RitsuLibFramework.Logger.Warn($"[ShellTheme] ThemeChanged callback failed: {value}", 1);
					}
				}
			}
			RitsuShellThemeModRegistration[] array4 = array;
			foreach (RitsuShellThemeModRegistration ritsuShellThemeModRegistration in array4)
			{
				try
				{
					ritsuShellThemeModRegistration.OnApply?.Invoke(snapshot);
				}
				catch (Exception value2)
				{
					RitsuLibFramework.CreateLogger(ritsuShellThemeModRegistration.ModId, (LogType)0).Warn($"[ShellTheme] Theme apply callback failed: {value2}", 1);
				}
			}
		}

		private static void FlushExternalFontCacheCleared()
		{
			using (Gate.EnterScope())
			{
				_fontRefreshQueued = false;
			}
			ReapplyActiveTheme(forceReloadCatalog: false);
		}
	}
