		/// <summary>
		///     <para xml:lang="en">
		///         Tries to parse an <c>RRGGBB</c> or <c>RRGGBBAA</c> hexadecimal color, with an optional leading
		///         number sign.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试解析 <c>RRGGBB</c> 或 <c>RRGGBBAA</c> 十六进制颜色，可带前导井号。
		///     </para>
		/// </summary>
		/// <param name="raw">
		///     <para xml:lang="en">The hexadecimal color text.</para>
		///     <para xml:lang="zh-CN">十六进制颜色文本。</para>
		/// </param>
		/// <param name="color">
		///     <para xml:lang="en">
		///         Receives the parsed color, or <see cref="P:Godot.Colors.Transparent" /> on failure.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         接收解析出的颜色；解析失败时为 <see cref="P:Godot.Colors.Transparent" />。
		///     </para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if <paramref name="raw" /> has a supported valid format; otherwise,
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若 <paramref name="raw" /> 为受支持的有效格式，则为 <see langword="true" />；否则为
		///         <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool TryParseHexColor(string raw, out Color color)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e4: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e9: Unknown result type (might be due to invalid IL or missing references)
			color = Colors.Transparent;
			string text = raw.Trim();
			if (text.Length > 0 && text[0] == '#')
			{
				text = text.Substring(1);
			}
			if (text.Length != 6 && text.Length != 8)
			{
				return false;
			}
			if (!byte.TryParse(text.Substring(0, 2), NumberStyles.HexNumber, CultureInfo.InvariantCulture, out var result) || !byte.TryParse(text.Substring(2, 2), NumberStyles.HexNumber, CultureInfo.InvariantCulture, out var result2) || !byte.TryParse(text.Substring(4, 2), NumberStyles.HexNumber, CultureInfo.InvariantCulture, out var result3))
			{
				return false;
			}
			byte result4 = byte.MaxValue;
			if (text.Length == 8 && !byte.TryParse(text.Substring(6, 2), NumberStyles.HexNumber, CultureInfo.InvariantCulture, out result4))
			{
				return false;
			}
			color = new Color((float)(int)result / 255f, (float)(int)result2 / 255f, (float)(int)result3 / 255f, (float)(int)result4 / 255f);
			return true;
		}

		private static Font TryLoadFont(string? rawPath)
		{
			Font fallbackFont = GetFallbackFont();
			if (string.IsNullOrWhiteSpace(rawPath))
			{
				return fallbackFont;
			}
			string path = rawPath.Trim();
			if (!TryNormalizeFontPath(ref path))
			{
				return fallbackFont;
			}
			using (FontGate.EnterScope())
			{
				if (FontCache.TryGetValue(path, out Font value) && GodotObject.IsInstanceValid((GodotObject)(object)value))
				{
					return value;
				}
				Font val = ResourceLoader.Load<Font>(path, (string)null, (CacheMode)1);
				if (val == null || !GodotObject.IsInstanceValid((GodotObject)(object)val))
				{
					val = fallbackFont;
				}
				ApplyGameFallbacks(val);
				FontCache[path] = val;
				return val;
			}
		}

		private static bool TryGetExternalFontSubstitution(FontType fontType, out Font font)
		{
			//IL_0031: Unknown result type (might be due to invalid IL or missing references)
			font = null;
			if (!HasExternalFontSubstitutionPatch())
			{
				return false;
			}
			LocManager instance = LocManager.Instance;
			string text = ((instance != null) ? instance.Language : null);
			if (string.IsNullOrWhiteSpace(text) || !FontManager.NeedsFontSubstitution(text))
			{
				return false;
			}
			Font substituteFont = FontManager.GetSubstituteFont(text, fontType);
			if (substituteFont == null || !GodotObject.IsInstanceValid((GodotObject)(object)substituteFont))
			{
				return false;
			}
			if (IsGameLocaleFontResource(substituteFont))
			{
				return false;
			}
			ApplyGameFallbacks(substituteFont);
			font = substituteFont;
			return true;
		}

		private static bool IsFontTokenCurrent(Font font, FontType fontType)
		{
			//IL_002e: Unknown result type (might be due to invalid IL or missing references)
			if (!HasExternalFontSubstitutionPatch())
			{
				return true;
			}
			LocManager instance = LocManager.Instance;
			string text = ((instance != null) ? instance.Language : null);
			if (string.IsNullOrWhiteSpace(text) || !FontManager.NeedsFontSubstitution(text))
			{
				return true;
			}
			Font substituteFont = FontManager.GetSubstituteFont(text, fontType);
			if (substituteFont != null && IsGameLocaleFontResource(substituteFont))
			{
				return true;
			}
			if (substituteFont != null)
			{
				return substituteFont == font;
			}
			return true;
		}

		private static bool HasExternalFontSubstitutionPatch()
		{
			if (!HasHarmonyPatch(AccessTools.Method(typeof(FontManager), "GetFontForLanguage", new Type[2]
			{
				typeof(string),
				typeof(FontType)
			}, (Type[])null)))
			{
				return HasHarmonyPatch(AccessTools.Method(typeof(FontManager), "GetSubstituteFont", new Type[2]
				{
					typeof(string),
					typeof(FontType)
				}, (Type[])null));
			}
			return true;
			static bool HasHarmonyPatch(MethodBase? method)
			{
				if (method == null)
				{
					return false;
				}
				Patches patchInfo = Harmony.GetPatchInfo(method);
				if (patchInfo != null)
				{
					if (patchInfo.Prefixes.Count <= 0 && patchInfo.Postfixes.Count <= 0 && patchInfo.Transpilers.Count <= 0)
					{
						return patchInfo.Finalizers.Count > 0;
					}
					return true;
				}
				return false;
			}
		}

		private static bool IsGameLocaleFontResource(Font font)
		{
			while (true)
			{
				string resourcePath = ((Resource)font).ResourcePath;
				if (!string.IsNullOrWhiteSpace(resourcePath) && GameLocaleFontResourcePaths.Contains(resourcePath))
				{
					return true;
				}
				FontVariation val = (FontVariation)(object)((font is FontVariation) ? font : null);
				if (val == null)
				{
					break;
				}
				Font baseFont = val.BaseFont;
				if (baseFont == null)
				{
					break;
				}
				font = baseFont;
			}
			FontFile val2 = (FontFile)(object)((font is FontFile) ? font : null);
			if (val2 == null)
			{
				return false;
			}
			string resourcePath2 = ((Resource)val2).ResourcePath;
			if (!string.IsNullOrWhiteSpace(resourcePath2))
			{
				return GameLocaleFontResourcePaths.Contains(resourcePath2);
			}
			return false;
		}

		private static void ApplyGameFallbacks(Font font)
		{
			FontFile val = FindBaseFontFile(font);
			if (val != null)
			{
				AddGameFallbacks(val);
			}
		}

		private static FontFile? FindBaseFontFile(Font font)
		{
			HashSet<Font> hashSet = new HashSet<Font>(ReferenceEqualityComparer.Instance);
			while (hashSet.Add(font))
			{
				FontFile val = (FontFile)(object)((font is FontFile) ? font : null);
				if (val != null)
				{
					return val;
				}
				FontVariation val2 = (FontVariation)(object)((font is FontVariation) ? font : null);
				if (val2 != null)
				{
					Font baseFont = val2.BaseFont;
					if (baseFont != null)
					{
						font = baseFont;
						continue;
					}
				}
				return null;
			}
			return null;
		}

		private static void AddGameFallbacks(FontFile baseFont)
		{
			//IL_008b: Unknown result type (might be due to invalid IL or missing references)
			if (((GodotObject)baseFont).HasMeta(StringName.op_Implicit("_ritsulib_game_font_fallbacks_applied")))
			{
				return;
			}
			Array<Font> val = new Array<Font>();
			Array<Font> fallbacks = ((Font)baseFont).GetFallbacks();
			if (fallbacks != null)
			{
				foreach (Font item in fallbacks)
				{
					val.Add(item);
				}
			}
			string[] gameFallbackFontPaths = GameFallbackFontPaths;
			foreach (string path in gameFallbackFontPaths)
			{
				AddFontFallbackIfAvailable(baseFont, val, path);
			}
			((Font)baseFont).SetFallbacks(val);
			((GodotObject)baseFont).SetMeta(StringName.op_Implicit("_ritsulib_game_font_fallbacks_applied"), Variant.op_Implicit(true));
		}

		private static void AddFontFallbackIfAvailable(FontFile baseFont, Array<Font> target, string path)
		{
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			//IL_002f: Expected O, but got Unknown
			//IL_0031: Unknown result type (might be due to invalid IL or missing references)
			if (TryLoadFontResource(path, out Font font))
			{
				if ((object)font != baseFont && FindBaseFontFile(font) != baseFont)
				{
					target.Add(font);
				}
			}
			else if (RawFontFileExists(path))
			{
				FontFile val = new FontFile();
				if ((int)val.LoadDynamicFont(path) == 0)
				{
					target.Add((Font)(object)val);
				}
				else
				{
					((GodotObject)val).Dispose();
				}
			}
		}

		private static bool TryLoadFontResource(string path, out Font font)
		{
			font = null;
			if (!IsGodotPath(path) || !ResourceLoader.Exists(path, ""))
			{
				return false;
			}
			Font val = ResourceLoader.Load<Font>(path, (string)null, (CacheMode)1);
			if (val == null || !GodotObject.IsInstanceValid((GodotObject)(object)val))
			{
				return false;
			}
			font = val;
			return true;
		}

		private static bool RawFontFileExists(string path)
		{
			if (!IsGodotPath(path))
			{
				return File.Exists(path);
			}
			return FileAccess.FileExists(path);
		}

		private static bool IsGodotPath(string path)
		{
			if (!path.StartsWith("res://", StringComparison.OrdinalIgnoreCase))
			{
				return path.StartsWith("user://", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}

		private static Font GetFallbackFont()
		{
			//IL_003f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0045: Expected O, but got Unknown
			using (FontGate.EnterScope())
			{
				if (_fallbackFont != null && GodotObject.IsInstanceValid((GodotObject)(object)_fallbackFont))
				{
					return _fallbackFont;
				}
				Font val = ResourceLoader.Load<Font>("res://themes/kreon_regular_shared.tres", (string)null, (CacheMode)1);
				if (val == null || !GodotObject.IsInstanceValid((GodotObject)(object)val))
				{
					val = (Font)new FontVariation();
				}
				ApplyGameFallbacks(val);
				_fallbackFont = val;
				FontCache["res://themes/kreon_regular_shared.tres"] = val;
				return val;
			}
		}

		private static bool TryNormalizeFontPath(ref string path)
		{
			if (path.StartsWith("res://", StringComparison.OrdinalIgnoreCase) || path.StartsWith("user://", StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}
			if (!RitsuShellThemePaths.TryEnsureShellThemesDirectory(out string absolutePath))
			{
				return false;
			}
			try
			{
				if (Path.IsPathRooted(path))
				{
					return false;
				}
				string fullPath = Path.GetFullPath(absolutePath);
				string fullPath2 = Path.GetFullPath(Path.Combine(fullPath, path));
				string relativePath = Path.GetRelativePath(fullPath, fullPath2);
				if (relativePath == ".." || relativePath.StartsWith($"..{Path.DirectorySeparatorChar}", StringComparison.Ordinal) || Path.IsPathRooted(relativePath))
				{
					return false;
				}
				path = ProjectSettings.LocalizePath(fullPath2);
				return true;
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.Warn($"[ShellTheme] Could not resolve theme-relative font path '{path}': {value}", 1);
				return false;
			}
		}
	}
