namespace STS2RitsuLib.Ui.Shell.Theme.Patches
{
	internal sealed class FontManagerClearCacheShellThemePatch : IPatchMethod
	{
		public static string PatchId => "font_manager_clear_cache_shell_theme_refresh";

		public static bool IsCritical => false;

		public static string Description => "Refresh RitsuLib shell theme fonts when the game font cache is cleared";

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(FontManager), "ClearCache", Type.EmptyTypes)
			};
		}

		public static void Postfix()
		{
			RitsuShellThemeRuntime.NotifyExternalFontCacheCleared();
		}
	}
}
namespace STS2RitsuLib.Ui.RichTextEffects
{
	/// <summary>
	///     <para xml:lang="en">Contains the metadata and effect instance of a registered mod rich-text effect.</para>
	///     <para xml:lang="zh-CN">包含已注册模组富文本特效的元数据与特效实例。</para>
	/// </summary>
	/// <param name="ModId">
	///     <para xml:lang="en">ID of the mod that owns the registration.</para>
	///     <para xml:lang="zh-CN">拥有该注册项的模组 ID。</para>
	/// </param>
	/// <param name="Bbcode">
	///     <para xml:lang="en">Global BBCode tag name handled by the effect.</para>
	///     <para xml:lang="zh-CN">该特效处理的全局 BBCode 标签名。</para>
	/// </param>
	/// <param name="Effect">
	///     <para xml:lang="en">Registered effect instance.</para>
	///     <para xml:lang="zh-CN">已注册的特效实例。</para>
	/// </param>
	public sealed record ModRichTextEffectRegistration(string ModId, string Bbcode, RichTextEffect Effect);
	/// <summary>
	///     <para xml:lang="en">
	///         Registers custom <see cref="T:Godot.RichTextEffect" /> instances for
	///         <see cref="T:MegaCrit.Sts2.addons.mega_text.MegaRichTextLabel" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为 <see cref="T:MegaCrit.Sts2.addons.mega_text.MegaRichTextLabel" /> 注册自定义 <see cref="T:Godot.RichTextEffect" /> 实例。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         BBCode tag names are global. Repeating a registration returns the existing definition only
	///         when the owning mod and effect instance are the same; every other collision fails.
	///     </para>
	///     <para xml:lang="en">
	///         RitsuLib installs registered effects into BBCode-enabled labels when they become ready, after
	///         text updates, and after the Godot editor restores scene data following a save.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         BBCode 标签名属于全局命名空间。仅当所属模组和特效实例都相同时，重复注册才会返回已有定义；
	///         其他冲突都会失败。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         RitsuLib 会在启用 BBCode 的标签进入就绪状态、文本更新后，以及 Godot 编辑器在保存后恢复
	///         场景数据时安装已注册特效。
	///     </para>
	/// </remarks>
	public static class ModRichTextEffectRegistry
	{
		private const string QualifiedBbcodeTypeSegment = "RICHTEXT";

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, ModRichTextEffectRegistration> Registrations = new Dictionary<string, ModRichTextEffectRegistration>(StringComparer.Ordinal);

		/// <summary>
		///     <para xml:lang="en">
		///         Builds a lowercase, mod-qualified BBCode tag name from <paramref name="localTagStem" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         根据 <paramref name="localTagStem" /> 构建小写且包含模组限定信息的 BBCode 标签名。
		///     </para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         The result follows RitsuLib's compound-ID convention; for example, mod ID
		///         <c>My Mod</c> and local stem <c>Glitch</c> produce <c>mymod_richtext_glitch</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         结果遵循 RitsuLib 的复合 ID 约定。例如，模组 ID <c>My Mod</c> 和本地名称
		///         <c>Glitch</c> 会生成 <c>mymod_richtext_glitch</c>。
		///     </para>
		/// </remarks>
		public static string GetQualifiedBbcode(string modId, string localTagStem)
		{
			return ModContentRegistry.GetCompoundId(modId, "RICHTEXT", localTagStem).ToLowerInvariant();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates and registers <typeparamref name="TEffect" /> under the mod-qualified tag derived
		///         from <paramref name="localTagStem" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建 <typeparamref name="TEffect" />，并使用根据 <paramref name="localTagStem" /> 派生的
		///         模组限定标签进行注册。
		///     </para>
		/// </summary>
		public static ModRichTextEffectRegistration RegisterOwned<TEffect>(string modId, string localTagStem) where TEffect : RichTextEffect, new()
		{
			return RegisterOwned(modId, localTagStem, (RichTextEffect)(object)new TEffect());
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers <paramref name="effect" /> under the mod-qualified tag derived from
		///         <paramref name="localTagStem" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用根据 <paramref name="localTagStem" /> 派生且包含模组限定信息的标签注册
		///         <paramref name="effect" />。
		///     </para>
		/// </summary>
		public static ModRichTextEffectRegistration RegisterOwned(string modId, string localTagStem, RichTextEffect effect)
		{
			return Register(modId, GetQualifiedBbcode(modId, localTagStem), effect);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates and registers <typeparamref name="TEffect" /> using the global tag name exposed by
		///         its <c>bbcode</c> field or property. Prefer <see cref="M:STS2RitsuLib.Ui.RichTextEffects.ModRichTextEffectRegistry.RegisterOwned``1(System.String,System.String)" /> for
		///         mod-owned effects.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建 <typeparamref name="TEffect" />，并使用其 <c>bbcode</c> 字段或属性公开的全局标签名
		///         进行注册。模组自有特效建议使用 <see cref="M:STS2RitsuLib.Ui.RichTextEffects.ModRichTextEffectRegistry.RegisterOwned``1(System.String,System.String)" />。
		///     </para>
		/// </summary>
		public static ModRichTextEffectRegistration Register<TEffect>(string modId) where TEffect : RichTextEffect, new()
		{
			return Register(modId, (RichTextEffect)(object)new TEffect());
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates and registers <typeparamref name="TEffect" /> under an explicit global
		///         <paramref name="bbcode" /> tag. Prefer <see cref="M:STS2RitsuLib.Ui.RichTextEffects.ModRichTextEffectRegistry.RegisterOwned``1(System.String,System.String)" /> for
		///         mod-owned effects.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建 <typeparamref name="TEffect" />，并使用显式全局 <paramref name="bbcode" /> 标签
		///         进行注册。模组自有特效建议使用 <see cref="M:STS2RitsuLib.Ui.RichTextEffects.ModRichTextEffectRegistry.RegisterOwned``1(System.String,System.String)" />。
		///     </para>
		/// </summary>
		public static ModRichTextEffectRegistration Register<TEffect>(string modId, string bbcode) where TEffect : RichTextEffect, new()
		{
			return Register(modId, bbcode, (RichTextEffect)(object)new TEffect());
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers <paramref name="effect" /> using the global tag name exposed by its
		///         <c>bbcode</c> field or property. Prefer
		///         <see cref="M:STS2RitsuLib.Ui.RichTextEffects.ModRichTextEffectRegistry.RegisterOwned(System.String,System.String,Godot.RichTextEffect)" /> for mod-owned effects.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用 <paramref name="effect" /> 的 <c>bbcode</c> 字段或属性公开的全局标签名注册该特效。
		///         模组自有特效建议使用 <see cref="M:STS2RitsuLib.Ui.RichTextEffects.ModRichTextEffectRegistry.RegisterOwned(System.String,System.String,Godot.RichTextEffect)" />。
		///     </para>
		/// </summary>
		public static ModRichTextEffectRegistration Register(string modId, RichTextEffect effect)
		{
			ArgumentNullException.ThrowIfNull(effect, "effect");
			string bbcode = ResolveBbcode(effect) ?? throw new ArgumentException("Rich text effect '" + ((object)effect).GetType().FullName + "' does not expose a non-empty bbcode field or property.", "effect");
			return Register(modId, bbcode, effect);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers <paramref name="effect" /> under an explicit global <paramref name="bbcode" />
		///         tag. The effect must expose a writable string <c>bbcode</c> member or already use the
		///         requested name.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用显式全局 <paramref name="bbcode" /> 标签注册 <paramref name="effect" />。
		///         该特效必须公开可写的字符串 <c>bbcode</c> 成员，或已经使用所请求的名称。
		///     </para>
		/// </summary>
		public static ModRichTextEffectRegistration Register(string modId, string bbcode, RichTextEffect effect)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(bbcode, "bbcode");
			ArgumentNullException.ThrowIfNull(effect, "effect");
			string text = ModRichTextTag.NormalizeName(bbcode, "BBCode tag");
			EnsureEffectBbcode(effect, text);
			ModRichTextEffectRegistration modRichTextEffectRegistration = new ModRichTextEffectRegistration(modId.Trim(), text, effect);
			using (SyncRoot.EnterScope())
			{
				if (Registrations.TryGetValue(text, out ModRichTextEffectRegistration value))
				{
					if (StringComparer.OrdinalIgnoreCase.Equals(value.ModId, modRichTextEffectRegistration.ModId) && value.Effect == modRichTextEffectRegistration.Effect)
					{
						return value;
					}
					throw new InvalidOperationException($"Rich text effect '[{text}]' is already registered by mod '{value.ModId}'.");
				}
				Registrations[text] = modRichTextEffectRegistration;
			}
			RitsuLibFramework.CreateLogger(modRichTextEffectRegistration.ModId, (LogType)0).Info($"[RichTextEffects] Registered [{modRichTextEffectRegistration.Bbcode}] ({((object)effect).GetType().FullName}).", 1);
			return modRichTextEffectRegistration;
		}

		/// <summary>
		///     <para xml:lang="en">Attempts to find a registered effect by global BBCode tag name.</para>
		///     <para xml:lang="zh-CN">尝试按全局 BBCode 标签名查找已注册特效。</para>
