		public static bool TryGet(string bbcode, out ModRichTextEffectRegistration registration)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(bbcode, "bbcode");
			string key = ModRichTextTag.NormalizeName(bbcode, "BBCode tag");
			using (SyncRoot.EnterScope())
