		internal static bool InstallInto(MegaRichTextLabel label)
		{
			//IL_006e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0082: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(label, "label");
			if (!((RichTextLabel)label).BbcodeEnabled)
			{
				return false;
			}
			ModRichTextEffectRegistration[] array;
			using (SyncRoot.EnterScope())
			{
				if (Registrations.Count == 0)
				{
					return false;
				}
				array = Registrations.Values.ToArray();
			}
			Array customEffects = ((RichTextLabel)label).CustomEffects;
			bool flag = false;
			ModRichTextEffectRegistration[] array2 = array;
			foreach (ModRichTextEffectRegistration modRichTextEffectRegistration in array2)
			{
				if (!customEffects.Contains(Variant.op_Implicit((GodotObject)(object)modRichTextEffectRegistration.Effect)))
				{
					customEffects.Add(Variant.op_Implicit((GodotObject)(object)modRichTextEffectRegistration.Effect));
					flag = true;
				}
			}
			if (!flag)
			{
				return false;
			}
			((RichTextLabel)label).CustomEffects = customEffects;
			((RichTextLabel)label).ParseBbcode(label.Text);
			return true;
		}

		private static string? ResolveBbcode(RichTextEffect effect)
		{
			//IL_006c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0071: Unknown result type (might be due to invalid IL or missing references)
			//IL_0074: Unknown result type (might be due to invalid IL or missing references)
			//IL_007b: Invalid comparison between Unknown and I8
			Type type = ((object)effect).GetType();
			if (type.GetField("bbcode", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(effect) is string text && !string.IsNullOrWhiteSpace(text))
			{
				return text;
			}
			if (type.GetProperty("bbcode", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(effect) is string text2 && !string.IsNullOrWhiteSpace(text2))
			{
				return text2;
			}
			Variant val = ((GodotObject)effect).Get(StringName.op_Implicit("bbcode"));
			if ((long)((Variant)(ref val)).VariantType != 4)
			{
				return null;
			}
			string text3 = ((Variant)(ref val)).AsString();
			if (!string.IsNullOrWhiteSpace(text3))
			{
				return text3;
			}
			return null;
		}

		private static void EnsureEffectBbcode(RichTextEffect effect, string bbcode)
		{
			if (TrySetBbcode(effect, bbcode) || string.Equals(ResolveBbcode(effect), bbcode, StringComparison.Ordinal))
			{
				return;
			}
			throw new InvalidOperationException($"Rich text effect '{((object)effect).GetType().FullName}' cannot be registered as '[{bbcode}]' because its " + "bbcode field or property is not writable. Expose a writable string bbcode member, or construct the effect with the same bbcode before registering it.");
		}

		private static bool TrySetBbcode(RichTextEffect effect, string bbcode)
		{
			Type type = ((object)effect).GetType();
			FieldInfo field = type.GetField("bbcode", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if ((object)field != null && !field.IsInitOnly && field.FieldType == typeof(string))
			{
				field.SetValue(effect, bbcode);
				return true;
			}
			PropertyInfo property = type.GetProperty("bbcode", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if ((object)property != null && property.CanWrite && property.PropertyType == typeof(string))
			{
				property.SetValue(effect, bbcode);
				return true;
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Builds BBCode tags for mod rich-text effects.</para>
	///     <para xml:lang="zh-CN">为模组富文本特效构建 BBCode 标签。</para>
	/// </summary>
	public static class ModRichTextTag
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Creates a rich-text tag parameter. Its name is validated when the tag is built.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建富文本标签参数。参数名会在构建标签时进行验证。
		///     </para>
		/// </summary>
		public static ModRichTextTagParameter Param(string name, object? value)
		{
			return new ModRichTextTagParameter(name, value);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Wraps <paramref name="text" /> in a BBCode tag with the supplied parameters.
		///         Parameter values are formatted with culture-invariant syntax; <see langword="null" /> values
		///         are omitted.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用带有指定参数的 BBCode 标签包裹 <paramref name="text" />。
		///         参数值使用与区域性无关的格式；值为 <see langword="null" /> 的参数会被省略。
		///     </para>
		/// </summary>
		public static string Wrap(string bbcode, string text, params ModRichTextTagParameter[] parameters)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(bbcode, "bbcode");
			ArgumentNullException.ThrowIfNull(text, "text");
			ArgumentNullException.ThrowIfNull(parameters, "parameters");
			string text2 = NormalizeName(bbcode, "BBCode tag");
			string value = BuildOpeningTag(text2, parameters);
			return $"{value}{text}[/{text2}]";
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Wraps <paramref name="text" /> in a BBCode tag with parameters from an enumerable sequence.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用带有可枚举参数序列的 BBCode 标签包裹 <paramref name="text" />。
		///     </para>
		/// </summary>
		public static string Wrap(string bbcode, string text, IEnumerable<ModRichTextTagParameter> parameters)
		{
			ArgumentNullException.ThrowIfNull(parameters, "parameters");
			return Wrap(bbcode, text, parameters.ToArray());
		}

		internal static string NormalizeName(string value, string label)
		{
			string text = value.Trim();
			if (text.Length == 0)
			{
				throw new ArgumentException(label + " must not be empty.", "value");
			}
			using IEnumerator<char> enumerator = text.Where(delegate(char ch)
			{
				bool flag = !char.IsLetterOrDigit(ch);
				if (flag)
				{
					bool flag2;
					switch (ch)
					{
					case '-':
					case '.':
					case ':':
					case '_':
						flag2 = true;
						break;
					default:
						flag2 = false;
						break;
					}
					flag = !flag2;
				}
				return flag;
			}).GetEnumerator();
			if (enumerator.MoveNext())
			{
				char current = enumerator.Current;
				throw new ArgumentException($"{label} '{text}' contains unsupported character '{current}'.", "value");
			}
			return text;
		}

		private static string BuildOpeningTag(string tag, IReadOnlyList<ModRichTextTagParameter> parameters)
		{
			if (parameters.Count == 0)
			{
				return "[" + tag + "]";
			}
			List<string> list = new List<string>(parameters.Count);
			foreach (ModRichTextTagParameter parameter in parameters)
			{
				if (parameter.Value != null)
				{
					string text = NormalizeName(parameter.Name, "BBCode parameter");
					list.Add(text + "=" + FormatValue(parameter.Value));
				}
			}
			if (list.Count != 0)
			{
				return $"[{tag} {string.Join(' ', list)}]";
			}
			return "[" + tag + "]";
		}

		private static string FormatValue(object value)
		{
			//IL_0072: Unknown result type (might be due to invalid IL or missing references)
			//IL_0077: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a0: Unknown result type (might be due to invalid IL or missing references)
			if (!(value is bool))
			{
				if (!(value is byte) && !(value is sbyte) && !(value is short) && !(value is ushort) && !(value is int) && !(value is uint) && !(value is long) && !(value is ulong) && !(value is float) && !(value is double) && !(value is decimal))
				{
					if (value is Color color)
					{
						return FormatColor(color);
					}
					return FormatString(value.ToString() ?? string.Empty);
				}
				return ((IFormattable)value).ToString(null, CultureInfo.InvariantCulture);
			}
			return ((bool)value) ? "true" : "false";
		}

		private static string FormatColor(Color color)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			//IL_0024: Unknown result type (might be due to invalid IL or missing references)
			int value = ToByte(color.R);
			int value2 = ToByte(color.G);
			int value3 = ToByte(color.B);
			int num = ToByte(color.A);
			if (num == 255)
			{
				return $"#{value:X2}{value2:X2}{value3:X2}";
			}
			return $"#{value:X2}{value2:X2}{value3:X2}{num:X2}";
		}

		private static int ToByte(float value)
		{
			return Mathf.Clamp(Mathf.RoundToInt(value * 255f), 0, 255);
		}

		private static string FormatString(string value)
		{
			if (value.Length > 0 && value.All(IsBareValueChar))
			{
				return value;
			}
			return "\"" + value.Replace("\\", "\\\\", StringComparison.Ordinal).Replace("\"", "\\\"", StringComparison.Ordinal).Replace("]", "\\]", StringComparison.Ordinal) + "\"";
		}

		private static bool IsBareValueChar(char ch)
		{
			bool flag = char.IsLetterOrDigit(ch);
			if (!flag)
			{
				bool flag2;
				switch (ch)
				{
				case '#':
				case '+':
				case '-':
				case '.':
				case ':':
				case '_':
					flag2 = true;
					break;
				default:
					flag2 = false;
					break;
				}
				flag = flag2;
			}
			return flag;
		}
	}
	/// <summary>
	///     <para xml:lang="en">BBCode parameter used by <see cref="T:STS2RitsuLib.Ui.RichTextEffects.ModRichTextTag" />.</para>
	///     <para xml:lang="zh-CN"><see cref="T:STS2RitsuLib.Ui.RichTextEffects.ModRichTextTag" /> 使用的 BBCode 参数。</para>
	/// </summary>
	/// <param name="Name">
	///     <para xml:lang="en">Parameter name, such as <c>seed</c> in <c>[glitch seed=123]</c>.</para>
	///     <para xml:lang="zh-CN">参数名，例如 <c>[glitch seed=123]</c> 中的 <c>seed</c>。</para>
	/// </param>
	/// <param name="Value">
	///     <para xml:lang="en">Parameter value. <see langword="null" /> values are omitted.</para>
	///     <para xml:lang="zh-CN">参数值。值为 <see langword="null" /> 时会被省略。</para>
	/// </param>
	public readonly record struct ModRichTextTagParameter(string Name, object? Value);
}
