		internal static bool TryOpenSettings(out RitsuModSettingsSubmenu submenu, out string error)
		{
			using (SyncRoot.EnterScope())
			{
				EnsureAttached((Node?)(object)NGame.Instance);
				if (_host == null || !GodotObject.IsInstanceValid((GodotObject)(object)_host))
				{
					submenu = null;
					error = ModSettingsLocalization.Get("ritsulib.settings.notAvailableYet", "RitsuLib settings are not available yet. Try again after the current screen finishes loading.");
					return false;
