		internal static bool TryOpenDebugTools(out string message)
		{
			if (!RitsuLibSettingsStore.AreDeveloperToolsEnabled())
			{
				message = ModSettingsLocalization.Get("ritsulib.debugTools.disabled", "Enable developer tools in RitsuLib settings before opening this workspace.");
				return false;
			}
			using (SyncRoot.EnterScope())
			{
				EnsureAttached((Node?)(object)NGame.Instance);
				if (_host == null || !GodotObject.IsInstanceValid((GodotObject)(object)_host))
				{
					message = ModSettingsLocalization.Get("ritsulib.debugTools.notAvailableYet", "RitsuLib developer tools are not available yet. Try again after the current screen finishes loading.");
					return false;
				}
				_host.OpenDebugTools();
				message = ModSettingsLocalization.Get("ritsulib.debugTools.opened", "Opened RitsuLib developer tools.");
				return true;
			}
		}

