		private static void EnsureHotkeysRegistered()
		{
			if (_settingsHotkey == null)
			{
				try
				{
					_settingsHotkey = RuntimeHotkeyService.Register(RitsuLibSettingsStore.GetSettingsOpenHotkey(), delegate
					{
						ModSettingsNavigator.RequestOpenByIds("com.ritsukage.sts2-RitsuLib", null, null, null);
					}, new RuntimeHotkeyOptions
					{
						Id = "ritsulib.settings.open",
						DisplayName = RuntimeHotkeyText.Dynamic(() => ModSettingsLocalization.Get("ritsulib.settings.hotkey.label", "Open mod settings")),
						Description = RuntimeHotkeyText.Dynamic(() => ModSettingsLocalization.Get("ritsulib.settings.hotkey.description", "Open the independent mod settings center.")),
						Category = RuntimeHotkeyText.Dynamic(() => ModSettingsLocalization.Get("ritsulib.category.core.label", "Core settings")),
						Purpose = "settings",
						SuppressWhenTextInputFocused = true,
						SuppressWhenDevConsoleVisible = true,
						MarkInputHandled = true,
						DebugName = "RitsuLib mod settings"
					});
				}
				catch (InvalidOperationException)
				{
				}
			}
			if (_debugToolsHotkey == null)
			{
				try
				{
					_debugToolsHotkey = RuntimeHotkeyService.Register(RitsuLibSettingsStore.GetDebugToolsOpenHotkey(), delegate
					{
						using (SyncRoot.EnterScope())
						{
							EnsureAttached((Node?)(object)NGame.Instance);
							RitsuOverlayHost host = _host;
							if (host != null && GodotObject.IsInstanceValid((GodotObject)(object)host))
							{
								if (!RitsuLibSettingsStore.AreDeveloperToolsEnabled())
								{
									RitsuToastService.ShowWarning(ModSettingsLocalization.Get("ritsulib.debugTools.disabled", "Enable developer tools in RitsuLib settings before opening this workspace."), ModSettingsLocalization.Get("ritsulib.debugTools.toastTitle", "Developer tools"));
								}
								else
								{
									host.ToggleDebugTools();
								}
							}
						}
					}, new RuntimeHotkeyOptions
					{
						Id = "ritsulib.debug-tools.open",
						DisplayName = RuntimeHotkeyText.Dynamic(() => ModSettingsLocalization.Get("ritsulib.debugTools.hotkey.label", "Toggle developer tools")),
						Description = RuntimeHotkeyText.Dynamic(() => ModSettingsLocalization.Get("ritsulib.debugTools.hotkey.description", "Show or close the developer tools workspace.")),
						Category = RuntimeHotkeyText.Dynamic(() => ModSettingsLocalization.Get("ritsulib.category.developerTools.label", "Developer tools")),
						Purpose = "debug-tools",
						SuppressWhenTextInputFocused = false,
						SuppressWhenDevConsoleVisible = true,
						MarkInputHandled = true,
						DebugName = "RitsuLib developer tools"
					});
				}
				catch (InvalidOperationException)
				{
				}
			}
			if (_creaturePickerHotkey != null)
			{
				return;
			}
			try
			{
				_creaturePickerHotkey = RuntimeHotkeyService.Register(RitsuLibSettingsStore.GetCreaturePickerHotkey(), delegate
				{
					using (SyncRoot.EnterScope())
					{
						EnsureAttached((Node?)(object)NGame.Instance);
						RitsuOverlayHost host = _host;
						if (host != null && GodotObject.IsInstanceValid((GodotObject)(object)host))
						{
							if (!RitsuLibSettingsStore.AreDeveloperToolsEnabled())
							{
								RitsuToastService.ShowWarning(ModSettingsLocalization.Get("ritsulib.debugTools.disabled", "Enable developer tools in RitsuLib settings before using this shortcut."), ModSettingsLocalization.Get("ritsulib.debugTools.toastTitle", "Developer tools"));
							}
							else
							{
								host.ToggleCreaturePicking();
							}
						}
					}
				}, new RuntimeHotkeyOptions
				{
					Id = "ritsulib.debug-tools.pick-creature",
					DisplayName = RuntimeHotkeyText.Dynamic(() => ModSettingsLocalization.Get("ritsulib.debugTools.creaturePickerHotkey.label", "Pick a combat creature")),
					Description = RuntimeHotkeyText.Dynamic(() => ModSettingsLocalization.Get("ritsulib.debugTools.creaturePickerHotkey.description", "Start creature picking directly during combat.")),
					Category = RuntimeHotkeyText.Dynamic(() => ModSettingsLocalization.Get("ritsulib.category.developerTools.label", "Developer tools")),
					Purpose = "debug-tools",
					SuppressWhenTextInputFocused = false,
					SuppressWhenDevConsoleVisible = true,
					MarkInputHandled = true,
					DebugName = "RitsuLib combat creature picker"
				});
			}
			catch (InvalidOperationException)
			{
			}
		}
	}
