		internal IScreenContext? ActiveScreen
		{
			get
			{
				RitsuOverlaySubmenuStack fixedStack = _fixedStack;
				if (fixedStack != null && ((NSubmenuStack)fixedStack).SubmenusOpen)
				{
					return (IScreenContext?)(object)((NSubmenuStack)_fixedStack).Peek();
				}
				RitsuDebugToolsDock debugToolsDock = _debugToolsDock;
				if (debugToolsDock == null || !debugToolsDock.Expanded)
				{
					return null;
				}
				return (IScreenContext?)(object)_debugToolsPanel;
			}
		}

		public override void _Ready()
		{
			BuildLayout();
			ActiveScreenContext.Instance.Updated += RefreshCombatFloatingLayerVisibility;
			RefreshCombatFloatingLayerVisibility();
		}

		public override void _ExitTree()
		{
			//IL_002b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0035: Expected O, but got Unknown
			ActiveScreenContext.Instance.Updated -= RefreshCombatFloatingLayerVisibility;
			if (_fixedStack != null)
			{
				((NSubmenuStack)_fixedStack).StackModified -= new StackModifiedEventHandler(OnFixedStackModified);
			}
			if (_debugToolsDock != null && GodotObject.IsInstanceValid((GodotObject)(object)_debugToolsDock))
			{
				_debugToolsDock.Expanding -= OnDebugToolsExpanding;
				_debugToolsDock.Collapsed -= OnDebugToolsCollapsed;
			}
			RitsuOverlayHostService.NotifyHostExited(this);
			((Node)this)._ExitTree();
		}

		public override void _UnhandledInput(InputEvent @event)
		{
			if (@event.IsEcho() || (!@event.IsActionPressed(MegaInput.cancel, false, false) && !@event.IsActionPressed(MegaInput.pauseAndBack, false, false)))
			{
				return;
			}
			if (((NSubmenuStack)_fixedStack).SubmenusOpen)
			{
				((NSubmenuStack)_fixedStack).Pop();
				((Node)this).GetViewport().SetInputAsHandled();
				return;
			}
			RitsuDebugToolsDock debugToolsDock = _debugToolsDock;
			if (debugToolsDock != null && debugToolsDock.Expanded)
			{
				_debugToolsDock.Collapse();
				((Node)this).GetViewport().SetInputAsHandled();
			}
		}

		internal RitsuModSettingsSubmenu OpenSettings()
		{
			CaptureBackgroundFocus();
			_switchingWorkspace = true;
			try
			{
				_debugToolsDock?.SetSuppressed(suppressed: true);
				((CanvasItem)_fixedBackdrop).Show();
				((CanvasItem)_fixedStack).Show();
				RitsuModSettingsSubmenu result = _fixedStack.PushSubmenuType<RitsuModSettingsSubmenu>();
				ScheduleFocusRefresh();
				return result;
			}
			finally
			{
				_switchingWorkspace = false;
			}
		}

		internal void OpenDebugTools(string? pageId = null)
		{
			RitsuDebugToolsDock ritsuDebugToolsDock = EnsureDebugToolsDock();
			ritsuDebugToolsDock.SetSuppressed(suppressed: false);
			_debugToolsPanel?.Refresh();
			ritsuDebugToolsDock.Expand(pageId);
			RefreshCombatFloatingLayerVisibility();
		}

		internal void ToggleDebugTools()
		{
			RitsuDebugToolsDock ritsuDebugToolsDock = EnsureDebugToolsDock();
			if (ritsuDebugToolsDock.SessionVisible)
			{
				ritsuDebugToolsDock.HideForSession();
			}
			else
			{
				OpenDebugTools();
			}
		}

		internal void ToggleCreaturePicking()
		{
			EnsureDebugToolsDock().SetSuppressed(suppressed: false);
			if (_debugToolsPanel == null)
			{
				return;
			}
			_switchingWorkspace = true;
			try
			{
				CloseFixedWorkspace();
				_debugToolsPanel.ToggleCreaturePicking();
			}
			finally
			{
				_switchingWorkspace = false;
			}
		}

		internal void OpenMonsterIntentWindow(uint combatId, ulong requesterNetId, ulong targetPlayerNetId)
		{
			//IL_00c7: Unknown result type (might be due to invalid IL or missing references)
			//IL_00dc: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f1: Unknown result type (might be due to invalid IL or missing references)
			//IL_01b6: Unknown result type (might be due to invalid IL or missing references)
			//IL_01bb: Unknown result type (might be due to invalid IL or missing references)
			if (_monsterIntentWindows.TryGetValue(combatId, out RitsuFloatingWindow value))
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)value))
				{
					((CanvasItem)value).Show();
					((CanvasItem)value).MoveToFront();
					_debugToolsDock?.HideForSession(remember: false);
					RefreshCombatFloatingLayerVisibility();
					return;
				}
				_monsterIntentWindows.Remove(combatId);
			}
			Creature? obj = RitsuDebugCombatActions.FindCreature(combatId);
			string text = ((obj != null) ? obj.Name : null);
			string title = string.Format(ModSettingsLocalization.Get("ritsulib.debugTools.intentWindowTitle", "{0} · Intent map"), string.IsNullOrWhiteSpace(text) ? ModSettingsLocalization.Get("ritsulib.debugTools.creature", "Creature") : text);
			RitsuFloatingWindow ritsuFloatingWindow = new RitsuFloatingWindow(new RitsuFloatingWindowOptions
			{
				Title = title,
				InitialSize = new Vector2(350f, 216f),
				MinimumSize = new Vector2(350f, 216f),
				MaximumSize = new Vector2(760f, 560f),
				Movable = true,
				Resizable = true,
				Closable = true,
				StartCentered = true,
				ConstrainToViewport = true,
				CompactChrome = true
			});
			((CanvasItem)ritsuFloatingWindow).ZIndex = 20;
			RitsuFloatingWindow window = ritsuFloatingWindow;
			window.SetContent((Control)(object)new RitsuDebugMonsterIntentWindow(combatId, requesterNetId, targetPlayerNetId));
			window.Closed += OnMonsterIntentWindowClosed;
			((Node)_combatFloatingLayer).AddChild((Node)(object)window, false, (InternalMode)0);
			_monsterIntentWindows[combatId] = window;
			_debugToolsDock?.HideForSession(remember: false);
			RefreshCombatFloatingLayerVisibility();
			Callable val = Callable.From((Action)delegate
			{
				PositionMonsterIntentWindow(window, combatId);
			});
			((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
		}

