	/// <summary>
	///     <para xml:lang="en">Selects the item layout used by a <see cref="T:STS2RitsuLib.Ui.Catalog.RitsuCatalogBrowser" />.</para>
	///     <para xml:lang="zh-CN">选择 <see cref="T:STS2RitsuLib.Ui.Catalog.RitsuCatalogBrowser" /> 使用的目录项布局。</para>
	/// </summary>
	public enum RitsuCatalogPresentation
	{
		/// <summary>
		///     <para xml:lang="en">Shows one full-width item per row.</para>
		///     <para xml:lang="zh-CN">每行显示一个占满宽度的目录项。</para>
		/// </summary>
		List,
		/// <summary>
		///     <para xml:lang="en">Shows compact icon tiles in an adaptive multi-column grid.</para>
		///     <para xml:lang="zh-CN">以自适应多列网格显示紧凑图标卡片。</para>
		/// </summary>
		Grid
	}
	/// <summary>
	///     <para xml:lang="en">Selects how selected-item details are presented by a <see cref="T:STS2RitsuLib.Ui.Catalog.RitsuCatalogBrowser" />.</para>
	///     <para xml:lang="zh-CN">选择 <see cref="T:STS2RitsuLib.Ui.Catalog.RitsuCatalogBrowser" /> 呈现所选目录项详情的方式。</para>
	/// </summary>
	public enum RitsuCatalogDetailPresentation
	{
		/// <summary>
		///     <para xml:lang="en">Keeps a compact catalog beside an always-visible detail pane.</para>
		///     <para xml:lang="zh-CN">在常驻详情面板旁保留紧凑目录。</para>
		/// </summary>
		Inline,
		/// <summary>
		///     <para xml:lang="en">Uses the full browser for items and slides details over its right edge on demand.</para>
		///     <para xml:lang="zh-CN">让目录占满浏览器，并在需要时从右侧滑入覆盖式详情抽屉。</para>
		/// </summary>
		Drawer
	}
	/// <summary>
	///     <para xml:lang="en">Selects the visual tone of a catalog item's explicit quick action.</para>
	///     <para xml:lang="zh-CN">选择目录项显式快捷操作的视觉色调。</para>
	/// </summary>
	public enum RitsuCatalogItemActionTone
	{
		/// <summary>
		///     <para xml:lang="en">Uses the normal neutral action style.</para>
		///     <para xml:lang="zh-CN">使用普通的中性操作样式。</para>
		/// </summary>
		Normal,
		/// <summary>
		///     <para xml:lang="en">Uses the destructive-action style.</para>
		///     <para xml:lang="zh-CN">使用破坏性操作样式。</para>
		/// </summary>
		Danger
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Describes one discoverable icon action rendered directly on a catalog item. Selecting the item remains a
	///         separate operation.
	///     </para>
	///     <para xml:lang="zh-CN">描述直接呈现在目录项上的一个易发现图标操作；选择目录项仍是独立操作。</para>
	/// </summary>
	public sealed class RitsuCatalogItemAction
	{
		/// <summary>
		///     <para xml:lang="en">Gets the action icon.</para>
		///     <para xml:lang="zh-CN">获取操作图标。</para>
		/// </summary>
		public Texture2D Icon { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the accessible action description.</para>
		///     <para xml:lang="zh-CN">获取无障碍操作说明。</para>
		/// </summary>
		public string Tooltip { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the synchronous main-thread action.</para>
		///     <para xml:lang="zh-CN">获取同步的主线程操作。</para>
		/// </summary>
		public Action Action { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the action tone.</para>
		///     <para xml:lang="zh-CN">获取操作色调。</para>
		/// </summary>
		public RitsuCatalogItemActionTone Tone { get; }

		/// <summary>
		///     <para xml:lang="en">Creates an icon action.</para>
		///     <para xml:lang="zh-CN">创建图标操作。</para>
		/// </summary>
		/// <param name="icon">
		///     <para xml:lang="en">The live icon texture. The caller retains ownership.</para>
		///     <para xml:lang="zh-CN">仍然有效的图标纹理；调用方保留所有权。</para>
		/// </param>
		/// <param name="tooltip">
		///     <para xml:lang="en">The non-empty accessible action description.</para>
		///     <para xml:lang="zh-CN">非空的无障碍操作说明。</para>
		/// </param>
		/// <param name="action">
		///     <para xml:lang="en">The synchronous action invoked on the Godot main thread.</para>
		///     <para xml:lang="zh-CN">在 Godot 主线程同步调用的操作。</para>
		/// </param>
		/// <param name="tone">
		///     <para xml:lang="en">The visual tone; the default is neutral.</para>
		///     <para xml:lang="zh-CN">视觉色调；默认为中性。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">Thrown when <paramref name="tooltip" /> is empty or too long.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="tooltip" /> 为空或过长时抛出。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">Thrown when <paramref name="action" /> is null.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="action" /> 为 null 时抛出。</para>
		/// </exception>
		/// <exception cref="T:System.ObjectDisposedException">
		///     <para xml:lang="en">Thrown when <paramref name="icon" /> is no longer valid.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="icon" /> 不再有效时抛出。</para>
		/// </exception>
		public RitsuCatalogItemAction(Texture2D icon, string tooltip, Action action, RitsuCatalogItemActionTone tone = RitsuCatalogItemActionTone.Normal)
		{
			ArgumentNullException.ThrowIfNull(icon, "icon");
			ArgumentException.ThrowIfNullOrWhiteSpace(tooltip, "tooltip");
			ArgumentNullException.ThrowIfNull(action, "action");
			if (!GodotObject.IsInstanceValid((GodotObject)(object)icon))
			{
				throw new ObjectDisposedException("icon");
			}
			if (tooltip.Length > 2048)
			{
				throw new ArgumentException("The action tooltip is too long.", "tooltip");
			}
			if (!Enum.IsDefined(tone))
			{
				throw new ArgumentOutOfRangeException("tone");
			}
			Icon = icon;
			Tooltip = tooltip;
			Action = action;
			Tone = tone;
		}
	}
