		///     <para xml:lang="en">Gets the optional secondary display text.</para>
		///     <para xml:lang="zh-CN">获取可选的次要显示文本。</para>
		/// </summary>
		public string? Subtitle { get; }

		/// <summary>
		///     <para xml:lang="en">Gets optional additional searchable text that is not rendered.</para>
		///     <para xml:lang="zh-CN">获取不会显示、但可参与搜索的可选附加文本。</para>
		/// </summary>
		public string? SearchText { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional icon texture. The caller remains responsible for its lifetime.</para>
		///     <para xml:lang="zh-CN">获取可选图标纹理；调用方仍负责其生命周期。</para>
		/// </summary>
		public Texture2D? Icon { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the optional lazy icon factory. The browser invokes it synchronously on the Godot main thread;
		///         the caller retains ownership of returned textures.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取可选的惰性图标工厂；浏览器会在 Godot 主线程同步调用它，返回纹理仍由调用方持有。
		///     </para>
		/// </summary>
		public Func<Texture2D?>? IconFactory { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional short row badge.</para>
		///     <para xml:lang="zh-CN">获取可选的行尾短徽标。</para>
		/// </summary>
		public string? Badge { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional complete hover text.</para>
		///     <para xml:lang="zh-CN">获取可选的完整悬浮提示文本。</para>
		/// </summary>
		public string? Tooltip { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional color used by the browser's non-text accent marker.</para>
		///     <para xml:lang="zh-CN">获取浏览器非文本强调标记使用的可选颜色。</para>
		/// </summary>
		public Color? AccentColor { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional explicit icon action displayed directly on the item.</para>
		///     <para xml:lang="zh-CN">获取直接显示在目录项上的可选显式图标操作。</para>
		/// </summary>
		public RitsuCatalogItemAction? QuickAction { get; }

		/// <summary>
		///     <para xml:lang="en">Creates an immutable catalog item.</para>
		///     <para xml:lang="zh-CN">创建一个不可变目录项。</para>
		/// </summary>
		/// <param name="id">
		///     <para xml:lang="en">A non-empty stable ID unique within the browser.</para>
		///     <para xml:lang="zh-CN">在浏览器中唯一且非空的稳定 ID。</para>
		/// </param>
		/// <param name="title">
		///     <para xml:lang="en">The primary display title.</para>
		///     <para xml:lang="zh-CN">主要显示标题。</para>
		/// </param>
		/// <param name="subtitle">
		///     <para xml:lang="en">Optional secondary display text.</para>
		///     <para xml:lang="zh-CN">可选的次要显示文本。</para>
		/// </param>
		/// <param name="searchText">
		///     <para xml:lang="en">Optional additional searchable text that is not rendered.</para>
		///     <para xml:lang="zh-CN">不会显示、但可参与搜索的可选附加文本。</para>
		/// </param>
		/// <param name="icon">
		///     <para xml:lang="en">Optional icon texture. The browser does not take ownership of the texture.</para>
		///     <para xml:lang="zh-CN">可选图标纹理；浏览器不取得该纹理的所有权。</para>
		/// </param>
		/// <param name="badge">
		///     <para xml:lang="en">Optional short badge displayed at the end of the row.</para>
		///     <para xml:lang="zh-CN">显示在行尾的可选短徽标。</para>
		/// </param>
		/// <param name="iconFactory">
		///     <para xml:lang="en">
		///         Optional side-effect-free factory that supplies an icon when the item needs to be displayed. Do not
		///         provide both <paramref name="icon" /> and this factory. The caller retains ownership of each returned
		///         texture and must keep it valid while the item may be displayed.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选且无副作用的图标工厂，在需要显示该项时提供图标。不得同时提供 <paramref name="icon" /> 和此工厂；
		///         调用方仍持有每次返回的纹理，并须在该项可能显示期间保持纹理有效。
		///     </para>
		/// </param>
		/// <param name="tooltip">
		///     <para xml:lang="en">
		///         Optional complete hover text. When omitted, the browser derives a hover tip from the title,
		///         subtitle, and ID.
		///     </para>
		///     <para xml:lang="zh-CN">可选的完整悬浮提示文本；省略时浏览器会根据标题、副标题和 ID 生成提示。</para>
		/// </param>
		/// <param name="quickAction">
		///     <para xml:lang="en">
		///         Optional explicit icon action rendered on the item. The browser does not treat it as item selection.
		///     </para>
		///     <para xml:lang="zh-CN">呈现在目录项上的可选显式图标操作；浏览器不会将其视为目录项选择。</para>
		/// </param>
		/// <param name="accentColor">
		///     <para xml:lang="en">
		///         Optional normalized color for the item's non-text accent marker. Text and icons should still identify
		///         the item's meaning without relying on color alone.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         目录项非文本强调标记使用的可选标准化颜色。文字和图标仍应在不依赖颜色的情况下表达目录项含义。
		///     </para>
		/// </param>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">Thrown when an ID or required title is invalid, or text exceeds its limit.</para>
		///     <para xml:lang="zh-CN">ID、必需标题无效或文本超过限制时抛出。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentOutOfRangeException">
		///     <para xml:lang="en">
		///         Thrown when <paramref name="accentColor" /> contains a non-finite component, a component outside zero
		///         through one, or a fully transparent alpha value.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当 <paramref name="accentColor" /> 包含非有限分量、超出零至一范围的分量或完全透明的 Alpha 值时抛出。
		///     </para>
		/// </exception>
		/// <exception cref="T:System.ObjectDisposedException">
		///     <para xml:lang="en">Thrown when <paramref name="icon" /> is no longer a valid Godot object.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="icon" /> 不再是有效的 Godot 对象时抛出。</para>
		/// </exception>
		public RitsuCatalogItem(string id, string title, string? subtitle = null, string? searchText = null, Texture2D? icon = null, string? badge = null, Func<Texture2D?>? iconFactory = null, string? tooltip = null, RitsuCatalogItemAction? quickAction = null, Color? accentColor = null)
		{
			//IL_008c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0091: Unknown result type (might be due to invalid IL or missing references)
			//IL_009d: Unknown result type (might be due to invalid IL or missing references)
			//IL_00aa: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b7: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d9: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c4: Unknown result type (might be due to invalid IL or missing references)
			//IL_0103: Unknown result type (might be due to invalid IL or missing references)
			//IL_012f: Unknown result type (might be due to invalid IL or missing references)
			//IL_015d: Unknown result type (might be due to invalid IL or missing references)
			base..ctor();
			Id = ValidateRequired(id, "id", 256);
			Title = ValidateRequired(title, "title", 2048);
			Subtitle = ValidateOptional(subtitle, "subtitle");
			SearchText = ValidateOptional(searchText, "searchText");
			Badge = ValidateOptional(badge, "badge");
			Tooltip = ValidateOptional(tooltip, "tooltip");
			QuickAction = quickAction;
			Color valueOrDefault = default(Color);
			int num;
			if (accentColor.HasValue)
			{
				valueOrDefault = accentColor.GetValueOrDefault();
				num = 1;
			}
			else
			{
				num = 0;
			}
			bool flag = (byte)num != 0;
			if (flag)
			{
				bool flag2 = !float.IsFinite(valueOrDefault.R) || !float.IsFinite(valueOrDefault.G) || !float.IsFinite(valueOrDefault.B) || !float.IsFinite(valueOrDefault.A);
				if (!flag2)
				{
					float r = valueOrDefault.R;
					flag2 = ((r < 0f || r > 1f) ? true : false);
				}
				bool flag3 = flag2;
				if (!flag3)
				{
					float r = valueOrDefault.G;
					flag3 = ((r < 0f || r > 1f) ? true : false);
				}
				bool flag4 = flag3;
				if (!flag4)
				{
					float r = valueOrDefault.B;
					flag4 = ((r < 0f || r > 1f) ? true : false);
				}
				bool flag5 = flag4;
				if (!flag5)
				{
					float r = valueOrDefault.A;
					flag5 = ((r <= 0f || r > 1f) ? true : false);
				}
				flag = flag5;
			}
			if (flag)
			{
				throw new ArgumentOutOfRangeException("accentColor");
			}
			AccentColor = accentColor;
			if (icon != null && iconFactory != null)
			{
				throw new ArgumentException("Provide either an icon or an icon factory, not both.", "iconFactory");
			}
			if (icon != null && !GodotObject.IsInstanceValid((GodotObject)(object)icon))
			{
				throw new ObjectDisposedException("icon");
			}
			Icon = icon;
			IconFactory = iconFactory;
		}

		internal bool Matches(string[] terms)
		{
			if (terms.Length != 0)
			{
				return terms.All(Matches);
			}
			return true;
		}

		private bool Matches(string term)
		{
			if (!Title.Contains(term, StringComparison.CurrentCultureIgnoreCase))
			{
				string? subtitle = Subtitle;
				if (subtitle == null || !subtitle.Contains(term, StringComparison.CurrentCultureIgnoreCase))
				{
					string? searchText = SearchText;
					if ((searchText == null || !searchText.Contains(term, StringComparison.CurrentCultureIgnoreCase)) && !Id.Contains(term, StringComparison.OrdinalIgnoreCase))
					{
						RitsuSearchPreparedText ritsuSearchPreparedText = Volatile.Read(in _preparedSearchText);
						if (ritsuSearchPreparedText == null)
						{
							global::<>y__InlineArray4<string> buffer = default(global::<>y__InlineArray4<string>);
							buffer[0] = Title;
							buffer[1] = Subtitle ?? string.Empty;
							buffer[2] = SearchText ?? string.Empty;
							buffer[3] = Id;
							RitsuSearchPreparedText ritsuSearchPreparedText2 = new RitsuSearchPreparedText(string.Join('\n', (ReadOnlySpan<string?>)buffer));
							ritsuSearchPreparedText = Interlocked.CompareExchange(ref _preparedSearchText, ritsuSearchPreparedText2, null) ?? ritsuSearchPreparedText2;
						}
						return ritsuSearchPreparedText.ScoreExpansion(term) >= 0;
					}
				}
			}
			return true;
		}

		private static string ValidateRequired(string value, string parameterName, int maximumLength)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(value, parameterName);
			if (value.Length > maximumLength)
			{
				throw new ArgumentException($"Text cannot exceed {maximumLength} characters.", parameterName);
			}
			return value;
		}

		private static string? ValidateOptional(string? value, string parameterName)
		{
			if (value == null)
			{
				return null;
			}
			if (value.Length > 2048)
			{
				throw new ArgumentException($"Text cannot exceed {2048} characters.", parameterName);
			}
			return value;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Describes one selectable option in a catalog filter group.
	///     </para>
	///     <para xml:lang="zh-CN">描述目录筛选组中的一个可选项。</para>
	/// </summary>
	public sealed class RitsuCatalogFilterOption
	{
		/// <summary>
		///     <para xml:lang="en">Gets the stable option ID.</para>
		///     <para xml:lang="zh-CN">获取稳定的选项 ID。</para>
		/// </summary>
		public string Id { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the displayed option label.</para>
		///     <para xml:lang="zh-CN">获取显示的选项标签。</para>
		/// </summary>
		public string Label { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the predicate used to include matching items.</para>
		///     <para xml:lang="zh-CN">获取用于包含匹配目录项的谓词。</para>
		/// </summary>
		public Func<RitsuCatalogItem, bool> Matches { get; }

		/// <summary>
		///     <para xml:lang="en">Creates a filter option backed by a side-effect-free predicate.</para>
		///     <para xml:lang="zh-CN">创建由无副作用谓词支持的筛选项。</para>
		/// </summary>
		/// <param name="id">
		///     <para xml:lang="en">A non-empty stable ID unique within the filter group.</para>
		///     <para xml:lang="zh-CN">在筛选组中唯一且非空的稳定 ID。</para>
		/// </param>
		/// <param name="label">
		///     <para xml:lang="en">The option label shown to the user.</para>
		///     <para xml:lang="zh-CN">向用户显示的选项标签。</para>
		/// </param>
		/// <param name="matches">
		///     <para xml:lang="en">
		///         A fast, side-effect-free predicate. Recoverable callback failures exclude the item and are logged.
		///     </para>
		///     <para xml:lang="zh-CN">快速且无副作用的谓词；可恢复的回调失败会排除该项并写入日志。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">Thrown when the ID or label is empty or exceeds the supported limit.</para>
		///     <para xml:lang="zh-CN">ID 或标签为空或超过支持的限制时抛出。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">Thrown when <paramref name="matches" /> is null.</para>
		///     <para xml:lang="zh-CN"><paramref name="matches" /> 为 null 时抛出。</para>
		/// </exception>
		public RitsuCatalogFilterOption(string id, string label, Func<RitsuCatalogItem, bool> matches)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentException.ThrowIfNullOrWhiteSpace(label, "label");
			ArgumentNullException.ThrowIfNull(matches, "matches");
			if (id.Length > 256)
			{
				throw new ArgumentException("Filter option ID is too long.", "id");
			}
			if (label.Length > 2048)
			{
				throw new ArgumentException("Filter option label is too long.", "label");
			}
			Id = id;
			Label = label;
			Matches = matches;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Describes one single-choice filter group. The browser automatically adds an unfiltered first option.
	///     </para>
	///     <para xml:lang="zh-CN">描述一个单选筛选组；浏览器会自动添加不筛选的首个选项。</para>
	/// </summary>
	public sealed class RitsuCatalogFilter
	{
		/// <summary>
		///     <para xml:lang="en">Gets the stable filter-group ID.</para>
		///     <para xml:lang="zh-CN">获取稳定的筛选组 ID。</para>
		/// </summary>
		public string Id { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the displayed filter-group label.</para>
		///     <para xml:lang="zh-CN">获取显示的筛选组标签。</para>
		/// </summary>
		public string Label { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the label for the unfiltered option.</para>
		///     <para xml:lang="zh-CN">获取不筛选选项的标签。</para>
		/// </summary>
		public string AllLabel { get; }

		/// <summary>
		///     <para xml:lang="en">Gets an immutable snapshot of the filter options.</para>
		///     <para xml:lang="zh-CN">获取筛选项的不可变快照。</para>
		/// </summary>
		public IReadOnlyList<RitsuCatalogFilterOption> Options { get; }

		/// <summary>
		///     <para xml:lang="en">Creates a filter group from an immutable snapshot of its options.</para>
		///     <para xml:lang="zh-CN">根据筛选项的不可变快照创建筛选组。</para>
		/// </summary>
		/// <param name="id">
		///     <para xml:lang="en">A non-empty stable ID unique within the browser.</para>
		///     <para xml:lang="zh-CN">在浏览器中唯一且非空的稳定 ID。</para>
		/// </param>
		/// <param name="label">
		///     <para xml:lang="en">The filter-group label.</para>
		///     <para xml:lang="zh-CN">筛选组标签。</para>
		/// </param>
		/// <param name="allLabel">
		///     <para xml:lang="en">The label used by the automatically supplied unfiltered option.</para>
		///     <para xml:lang="zh-CN">自动提供的不筛选选项所使用的标签。</para>
		/// </param>
		/// <param name="options">
		///     <para xml:lang="en">One or more options with unique IDs.</para>
		///     <para xml:lang="zh-CN">一个或多个具有唯一 ID 的筛选项。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">Thrown for invalid text, no options, too many options, or duplicate option IDs.</para>
		///     <para xml:lang="zh-CN">文本无效、没有筛选项、筛选项过多或选项 ID 重复时抛出。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">Thrown when <paramref name="options" /> is null.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="options" /> 为 null 时抛出。</para>
		/// </exception>
		public RitsuCatalogFilter(string id, string label, string allLabel, IReadOnlyList<RitsuCatalogFilterOption> options)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentException.ThrowIfNullOrWhiteSpace(label, "label");
			ArgumentException.ThrowIfNullOrWhiteSpace(allLabel, "allLabel");
			ArgumentNullException.ThrowIfNull(options, "options");
			if (id.Length > 256)
			{
				throw new ArgumentException("Filter ID is too long.", "id");
			}
			if (label.Length > 2048)
			{
				throw new ArgumentException("Filter label is too long.", "label");
			}
			if (allLabel.Length > 2048)
			{
				throw new ArgumentException("Unfiltered-option label is too long.", "allLabel");
			}
			int count = options.Count;
			if ((count <= 0 || count > 64) ? true : false)
			{
				throw new ArgumentException("A filter must contain between 1 and 64 options.", "options");
			}
			if (options.Any((RitsuCatalogFilterOption option) => option == null))
			{
				throw new ArgumentException("Filter options cannot contain null.", "options");
			}
			if (options.Select((RitsuCatalogFilterOption option) => option.Id).Distinct<string>(StringComparer.Ordinal).Count() != options.Count)
			{
				throw new ArgumentException("Filter option IDs must be unique.", "options");
			}
			Id = id;
			Label = label;
			AllLabel = allLabel;
			Options = Array.AsReadOnly(options.ToArray());
		}
	}
	/// <summary>
	///     <para xml:lang="en">Configures presentation and callbacks for a <see cref="T:STS2RitsuLib.Ui.Catalog.RitsuCatalogBrowser" />.</para>
	///     <para xml:lang="zh-CN">配置 <see cref="T:STS2RitsuLib.Ui.Catalog.RitsuCatalogBrowser" /> 的呈现和回调。</para>
	/// </summary>
	public sealed class RitsuCatalogBrowserOptions
	{
		/// <summary>
		///     <para xml:lang="en">Gets or initializes the item presentation; the default is a list.</para>
		///     <para xml:lang="zh-CN">获取或初始化目录项呈现方式；默认为列表。</para>
		/// </summary>
		public RitsuCatalogPresentation Presentation { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes how details are presented. The default is an on-demand drawer that does not
		///         reduce the catalog's layout width.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化详情呈现方式；默认使用不会缩减目录布局宽度的按需抽屉。</para>
		/// </summary>
		public RitsuCatalogDetailPresentation DetailPresentation { get; init; } = RitsuCatalogDetailPresentation.Drawer;

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the search-field placeholder.</para>
		///     <para xml:lang="zh-CN">获取或初始化搜索框占位文本。</para>
		/// </summary>
		public string SearchPlaceholder { get; init; } = "Search";

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the text displayed when no item matches.</para>
		///     <para xml:lang="zh-CN">获取或初始化没有匹配项时显示的文本。</para>
		/// </summary>
		public string EmptyText { get; init; } = "No matching items";

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the text displayed before an item is selected.</para>
		///     <para xml:lang="zh-CN">获取或初始化选择目录项前显示的文本。</para>
		/// </summary>
		public string DetailPlaceholderText { get; init; } = "Select an item to view details";

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the text displayed when an item's details cannot be shown.</para>
		///     <para xml:lang="zh-CN">获取或初始化无法显示目录项详情时使用的文本。</para>
		/// </summary>
		public string DetailUnavailableText { get; init; } = "Details are unavailable for this item";

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the browser's minimum height, from 240 through 1200 pixels.</para>
		///     <para xml:lang="zh-CN">获取或初始化浏览器最小高度，范围为 240 至 1200 像素。</para>
		/// </summary>
		public float MinimumHeight { get; init; } = 560f;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes the catalog width in list presentation, from 220 through 720 pixels. Grid
		///         presentation instead expands the catalog to the available space.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或初始化列表呈现下的目录宽度，范围为 220 至 720 像素；网格呈现会改为占用全部可用空间。
		///     </para>
		/// </summary>
		public float CatalogWidth { get; init; } = 380f;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes the inline detail-pane minimum width or drawer width, from 280 through 720 pixels.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化常驻详情面板的最小宽度或抽屉宽度，范围为 280 至 720 像素。</para>
		/// </summary>
		public float DetailMinimumWidth { get; init; } = 360f;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes the maximum drawer width, from 320 through 960 pixels. The value must not be
		///         smaller than <see cref="P:STS2RitsuLib.Ui.Catalog.RitsuCatalogBrowserOptions.DetailMinimumWidth" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或初始化详情抽屉的最大宽度，范围为 320 至 960 像素；该值不得小于 <see cref="P:STS2RitsuLib.Ui.Catalog.RitsuCatalogBrowserOptions.DetailMinimumWidth" />。
		///     </para>
		/// </summary>
		public float DetailMaximumWidth { get; init; } = 640f;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes the preferred fraction of available width used by a detail drawer, from 0.3
		///         through 0.75. The browser still applies the configured minimum, maximum, and catalog reservation.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或初始化详情抽屉优先使用的可用宽度比例，范围为 0.3 至 0.75；浏览器仍会应用配置的最小值、最大值和目录预留宽度。
		///     </para>
		/// </summary>
		public float DetailPreferredWidthFraction { get; init; } = 0.44f;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes the width kept visible for the catalog beside a drawer, from 220 through 720
		///         pixels, whenever the workspace is large enough.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或初始化详情抽屉旁为目录保留的可见宽度；范围为 220 至 720 像素，并在工作区足够宽时生效。
		///     </para>
		/// </summary>
		public float MinimumVisibleCatalogWidth { get; init; } = 300f;

		/// <summary>
		///     <para xml:lang="en">Gets or initializes each catalog item's row height, from 48 through 120 pixels.</para>
		///     <para xml:lang="zh-CN">获取或初始化每个目录项的行高，范围为 48 至 120 像素。</para>
		/// </summary>
		public float RowHeight { get; init; } = 64f;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes the preferred minimum grid-tile width, from 72 through 320 pixels. The browser
		///         derives the column count from the available viewport width.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或初始化网格卡片的首选最小宽度，范围为 72 至 320 像素；浏览器会按可用视口宽度计算列数。
		///     </para>
		/// </summary>
		public float GridTileMinimumWidth { get; init; } = 112f;

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the grid-tile height, from 72 through 240 pixels.</para>
		///     <para xml:lang="zh-CN">获取或初始化网格卡片高度，范围为 72 至 240 像素。</para>
		/// </summary>
		public float GridTileHeight { get; init; } = 104f;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes the optional factory for selected-item detail content. Each returned control must
		///         be a live, unattached node; the browser owns and frees it after replacement.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或初始化可选的选中项详情工厂。每次返回的控件必须仍然有效且没有父节点；浏览器会取得所有权并在替换后释放。
		///     </para>
		/// </summary>
		public Func<RitsuCatalogItem, Control>? DetailFactory { get; init; }

		internal void Validate()
		{
			ValidateText(SearchPlaceholder, "SearchPlaceholder");
			ValidateText(EmptyText, "EmptyText");
			ValidateText(DetailPlaceholderText, "DetailPlaceholderText");
			ValidateText(DetailUnavailableText, "DetailUnavailableText");
			float minimumHeight = MinimumHeight;
			bool flag = ((minimumHeight < 240f || minimumHeight > 1200f) ? true : false);
			if (flag || !float.IsFinite(MinimumHeight))
			{
				throw new ArgumentOutOfRangeException("MinimumHeight");
			}
			minimumHeight = CatalogWidth;
			flag = ((minimumHeight < 220f || minimumHeight > 720f) ? true : false);
			if (flag || !float.IsFinite(CatalogWidth))
			{
				throw new ArgumentOutOfRangeException("CatalogWidth");
			}
			minimumHeight = DetailMinimumWidth;
			flag = ((minimumHeight < 280f || minimumHeight > 720f) ? true : false);
			if (flag || !float.IsFinite(DetailMinimumWidth))
			{
				throw new ArgumentOutOfRangeException("DetailMinimumWidth");
			}
			minimumHeight = DetailMaximumWidth;
			flag = ((minimumHeight < 320f || minimumHeight > 960f) ? true : false);
			if (flag || !float.IsFinite(DetailMaximumWidth) || DetailMaximumWidth < DetailMinimumWidth)
			{
				throw new ArgumentOutOfRangeException("DetailMaximumWidth");
			}
			minimumHeight = DetailPreferredWidthFraction;
			flag = ((minimumHeight < 0.3f || minimumHeight > 0.75f) ? true : false);
			if (flag || !float.IsFinite(DetailPreferredWidthFraction))
			{
				throw new ArgumentOutOfRangeException("DetailPreferredWidthFraction");
			}
			minimumHeight = MinimumVisibleCatalogWidth;
			flag = ((minimumHeight < 220f || minimumHeight > 720f) ? true : false);
			if (flag || !float.IsFinite(MinimumVisibleCatalogWidth))
			{
				throw new ArgumentOutOfRangeException("MinimumVisibleCatalogWidth");
			}
			minimumHeight = RowHeight;
			flag = ((minimumHeight < 48f || minimumHeight > 120f) ? true : false);
			if (flag || !float.IsFinite(RowHeight))
			{
				throw new ArgumentOutOfRangeException("RowHeight");
			}
			if (!Enum.IsDefined(Presentation))
			{
				throw new ArgumentOutOfRangeException("Presentation");
			}
			if (!Enum.IsDefined(DetailPresentation))
			{
				throw new ArgumentOutOfRangeException("DetailPresentation");
			}
			minimumHeight = GridTileMinimumWidth;
			flag = ((minimumHeight < 72f || minimumHeight > 320f) ? true : false);
			if (flag || !float.IsFinite(GridTileMinimumWidth))
			{
				throw new ArgumentOutOfRangeException("GridTileMinimumWidth");
			}
			minimumHeight = GridTileHeight;
			flag = ((minimumHeight < 72f || minimumHeight > 240f) ? true : false);
			if (flag || !float.IsFinite(GridTileHeight))
			{
				throw new ArgumentOutOfRangeException("GridTileHeight");
			}
		}

		private static void ValidateText(string value, string parameterName)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(value, parameterName);
			if (value.Length > 2048)
			{
				throw new ArgumentException("Text is too long.", parameterName);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides data for a catalog selection change.</para>
	///     <para xml:lang="zh-CN">提供目录选择变更的数据。</para>
	/// </summary>
	public sealed class RitsuCatalogSelectionChangedEventArgs : EventArgs
	{
		/// <summary>
		///     <para xml:lang="en">Gets the selected item, or null when the selection was cleared.</para>
		///     <para xml:lang="zh-CN">获取选中的目录项；清除选择时为 null。</para>
		/// </summary>
		public RitsuCatalogItem? Item { get; }

		internal RitsuCatalogSelectionChangedEventArgs(RitsuCatalogItem? item)
		{
			Item = item;
		}
	}
}
namespace STS2RitsuLib.TopBar
{
	/// <summary>
	///     <para xml:lang="en">
	///         Defines the behavior of a type registered with
	///         <see cref="T:STS2RitsuLib.Interop.AutoRegistration.RegisterOwnedTopBarButtonAttribute" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义带有 <see cref="T:STS2RitsuLib.Interop.AutoRegistration.RegisterOwnedTopBarButtonAttribute" />
	///         特性的类型在自动注册顶部栏按钮时使用的行为。
	///     </para>
	/// </summary>
	public interface IModTopBarButtonHandler
	{
		/// <summary>
		///     <para xml:lang="en">Invoked when the button is released, after its click animation starts.</para>
		///     <para xml:lang="zh-CN">按钮释放且点击动画开始后调用。</para>
		/// </summary>
		void OnClick(ModTopBarButtonContext context);

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether the button should be visible. This method runs during
		///         <c>_Process</c> and should remain inexpensive. The default is <see langword="true" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回按钮是否应当可见。此方法会在 <c>_Process</c> 中调用，应避免耗时操作。
		///         默认返回 <see langword="true" />。
		///     </para>
		/// </summary>
		bool IsVisible(ModTopBarButtonContext context)
		{
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether the associated screen or mode is open. An open button uses the selected-state
		///         tilt of vanilla top-bar buttons. This method runs during <c>_Process</c>; the default is
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回关联界面或模式是否打开。打开的按钮会使用原版顶部栏按钮的选中状态倾斜效果。
		///         此方法会在 <c>_Process</c> 中调用；默认返回 <see langword="false" />。
		///     </para>
		/// </summary>
		bool IsOpen(ModTopBarButtonContext context)
		{
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the count displayed below the icon. Negative values hide the label. This method runs
		///         during <c>_Process</c>; the default is <c>-1</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回显示在图标下方的数量。负数会隐藏标签。此方法会在 <c>_Process</c> 中调用；
		///         默认值为 <c>-1</c>。
		///     </para>
		/// </summary>
		int GetCount(ModTopBarButtonContext context)
		{
			return -1;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Context passed to top-bar button callbacks. It exposes the registered definition, the local
	///         player, the mounted button, and helpers for managing capstone screens.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         传给顶部栏按钮回调的上下文。它提供已注册定义、本地玩家、已挂载按钮和管理 Capstone 屏幕的辅助方法。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         A new context is created for each callback. <see cref="P:STS2RitsuLib.TopBar.ModTopBarButtonContext.Player" /> is
	///         <see langword="null" /> until a local player is bound, including between runs.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         每次回调都会创建新的上下文。本地玩家尚未绑定时（包括两局游戏之间），
	///         <see cref="P:STS2RitsuLib.TopBar.ModTopBarButtonContext.Player" /> 为 <see langword="null" />。
	///     </para>
	/// </remarks>
	public sealed class ModTopBarButtonContext
	{
		/// <summary>
		///     <para xml:lang="en">Registered definition that produced the callback.</para>
		///     <para xml:lang="zh-CN">产生此次回调的已注册定义。</para>
		/// </summary>
		public ModTopBarButtonDefinition Definition { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Local player currently bound to the button, or <see langword="null" /> before initialization.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当前绑定到按钮的本地玩家；尚未初始化时为 <see langword="null" />。
		///     </para>
		/// </summary>
		public Player? Player { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Mounted Godot button node, or <see langword="null" /> when no UI node supplied the callback.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         已挂载的 Godot 按钮节点；回调并非由界面节点触发时为 <see langword="null" />。
		///     </para>
		/// </summary>
		public NModCardPileButton? Button { get; }

		internal ModTopBarButtonContext(ModTopBarButtonDefinition definition, Player? player, NModCardPileButton? button)
		{
			Definition = definition;
			Player = player;
			Button = button;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Opens <paramref name="screen" /> through <see cref="M:STS2RitsuLib.Screens.ModScreenService.Open(MegaCrit.Sts2.Core.Nodes.Screens.Capstones.ICapstoneScreen)" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过 <see cref="M:STS2RitsuLib.Screens.ModScreenService.Open(MegaCrit.Sts2.Core.Nodes.Screens.Capstones.ICapstoneScreen)" /> 打开 <paramref name="screen" />。
		///     </para>
		/// </summary>
		public bool OpenCapstoneScreen(ICapstoneScreen screen)
		{
			return ModScreenService.Open(screen);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Opens <paramref name="screen" /> when it is not current; otherwise closes it.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         <paramref name="screen" /> 不是当前 Capstone 屏幕时将其打开，否则将其关闭。
		///     </para>
		/// </summary>
		public bool ToggleCapstoneScreen(ICapstoneScreen screen)
		{
			return ModScreenService.Toggle(screen);
		}

		/// <summary>
		///     <para xml:lang="en">Closes the current capstone screen, if any.</para>
		///     <para xml:lang="zh-CN">关闭当前 Capstone 屏幕（如果存在）。</para>
		/// </summary>
		public bool CloseCapstoneScreen()
		{
			return ModScreenService.Close();
		}
	}
	/// <summary>
	///     <para xml:lang="en">Immutable definition of a registered mod top-bar button.</para>
	///     <para xml:lang="zh-CN">已注册的模组顶部栏按钮的不可变定义。</para>
	/// </summary>
	public sealed record ModTopBarButtonDefinition
	{
		/// <summary>
		///     <para xml:lang="en">ID of the owning mod.</para>
		///     <para xml:lang="zh-CN">所属模组的 ID。</para>
		/// </summary>
		public string ModId { get; }

		/// <summary>
		///     <para xml:lang="en">Trimmed global ID, for example <c>MYMOD_TOPBARBUTTON_RECIPES</c>.</para>
		///     <para xml:lang="zh-CN">去除首尾空白后的全局 ID，例如 <c>MYMOD_TOPBARBUTTON_RECIPES</c>。</para>
		/// </summary>
		public string Id { get; }

		/// <summary>
		///     <para xml:lang="en">Godot resource path for the icon, or <see langword="null" />.</para>
		///     <para xml:lang="zh-CN">图标的 Godot 资源路径；未指定时为 <see langword="null" />。</para>
		/// </summary>
		public string? IconPath { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Global sort order among registered action buttons. Lower values appear closer to the
		///         vanilla deck button.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         已注册操作按钮之间的全局排序值；值越小越靠近原版牌组按钮。
		///     </para>
		/// </summary>
		public int Order { get; }

		/// <summary>
		///     <para xml:lang="en">Additional visual offset from the automatically arranged slot.</para>
		///     <para xml:lang="zh-CN">相对于自动排列槽位的额外视觉偏移。</para>
		/// </summary>
		public Vector2 Offset { get; }

		/// <summary>
		///     <para xml:lang="en">Click handler. See <see cref="P:STS2RitsuLib.TopBar.ModTopBarButtonSpec.OnClick" />.</para>
		///     <para xml:lang="zh-CN">点击回调。参见 <see cref="P:STS2RitsuLib.TopBar.ModTopBarButtonSpec.OnClick" />。</para>
		/// </summary>
		public Action<ModTopBarButtonContext> OnClick { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional visibility predicate. See <see cref="P:STS2RitsuLib.TopBar.ModTopBarButtonSpec.VisibleWhen" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的可见性谓词。参见 <see cref="P:STS2RitsuLib.TopBar.ModTopBarButtonSpec.VisibleWhen" />。
		///     </para>
		/// </summary>
		public Func<ModTopBarButtonContext, bool>? VisibleWhen { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional predicate for the selected/open visual state. See
		///         <see cref="P:STS2RitsuLib.TopBar.ModTopBarButtonSpec.IsOpenWhen" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         控制选中或打开状态视觉效果的可选谓词。参见
		///         <see cref="P:STS2RitsuLib.TopBar.ModTopBarButtonSpec.IsOpenWhen" />。
		///     </para>
		/// </summary>
		public Func<ModTopBarButtonContext, bool>? IsOpenWhen { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional count provider for the label. See <see cref="P:STS2RitsuLib.TopBar.ModTopBarButtonSpec.CountProvider" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         计数标签的可选数量提供器。参见 <see cref="P:STS2RitsuLib.TopBar.ModTopBarButtonSpec.CountProvider" />。
		///     </para>
		/// </summary>
		public Func<ModTopBarButtonContext, int>? CountProvider { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Hover-tip title read from <c>static_hover_tips</c> under key <c>{Id}.title</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从 <c>static_hover_tips</c> 的 <c>{Id}.title</c> 键读取的悬停提示标题。
		///     </para>
		/// </summary>
		public LocString Title
		{
			get
			{
				//IL_0015: Unknown result type (might be due to invalid IL or missing references)
				//IL_001b: Expected O, but got Unknown
				return new LocString("static_hover_tips", Id + ".title");
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Hover-tip description read from <c>static_hover_tips</c> under key
		///         <c>{Id}.description</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从 <c>static_hover_tips</c> 的 <c>{Id}.description</c> 键读取的悬停提示描述。
		///     </para>
		/// </summary>
		public LocString Description
		{
			get
			{
				//IL_0015: Unknown result type (might be due to invalid IL or missing references)
				//IL_001b: Expected O, but got Unknown
				return new LocString("static_hover_tips", Id + ".description");
			}
		}

		internal ModTopBarButtonDefinition(string modId, string id, string? iconPath, int order, Vector2 offset, Action<ModTopBarButtonContext> onClick, Func<ModTopBarButtonContext, bool>? visibleWhen, Func<ModTopBarButtonContext, bool>? isOpenWhen, Func<ModTopBarButtonContext, int>? countProvider)
		{
			ModId = modId;
			Id = id;
			IconPath = iconPath;
			Order = order;
			Offset = offset;
			OnClick = onClick;
			VisibleWhen = visibleWhen;
			IsOpenWhen = isOpenWhen;
			CountProvider = countProvider;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Creates hover tips for registered mod top-bar buttons.</para>
	///     <para xml:lang="zh-CN">为已注册的模组顶部栏按钮创建悬停提示。</para>
	/// </summary>
	public static class ModTopBarButtonHoverTipFactory
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Creates a <see cref="T:MegaCrit.Sts2.Core.HoverTips.HoverTip" /> from the definition's localized title, description, and
		///         optional icon. An empty or unavailable icon path produces a text-only tip.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用定义中的本地化标题、描述和可选图标创建 <see cref="T:MegaCrit.Sts2.Core.HoverTips.HoverTip" />。
		///         图标路径为空或资源不可用时创建纯文本提示。
		///     </para>
		/// </summary>
		public static HoverTip Create(ModTopBarButtonDefinition definition)
		{
			//IL_0048: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(definition, "definition");
			Texture2D val = null;
			if (!string.IsNullOrWhiteSpace(definition.IconPath) && ResourceLoader.Exists(definition.IconPath, ""))
			{
				val = ResourceLoader.Load<Texture2D>(definition.IconPath, (string)null, (CacheMode)1);
			}
			return new HoverTip(definition.Title, definition.Description, val);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Registers mod-owned action buttons in the vanilla top bar.</para>
	///     <para xml:lang="zh-CN">在原版顶部栏中注册归属于模组的操作按钮。</para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         <see cref="M:STS2RitsuLib.TopBar.ModTopBarButtonRegistry.RegisterOwned(System.String,STS2RitsuLib.TopBar.ModTopBarButtonSpec)" /> derives IDs through
	///         <see cref="M:STS2RitsuLib.Content.ModContentRegistry.GetQualifiedTopBarButtonId(System.String,System.String)" />. The resulting ID is also used
	///         for <c>static_hover_tips</c> keys <c>{id}.title</c> and <c>{id}.description</c>.
	///     </para>
	///     <para xml:lang="en">
	///         Register buttons before <see cref="M:MegaCrit.Sts2.Core.Nodes.CommonUi.NTopBar._Ready" /> creates
	///         the current top bar. Repeating an ID for the same mod returns its existing definition; a
	///         different mod cannot claim that ID.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         <see cref="M:STS2RitsuLib.TopBar.ModTopBarButtonRegistry.RegisterOwned(System.String,STS2RitsuLib.TopBar.ModTopBarButtonSpec)" /> 通过
	///         <see cref="M:STS2RitsuLib.Content.ModContentRegistry.GetQualifiedTopBarButtonId(System.String,System.String)" /> 派生 ID。所得 ID 同时用于
	///         <c>static_hover_tips</c> 中的 <c>{id}.title</c> 和 <c>{id}.description</c> 键。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         请在 <see cref="M:MegaCrit.Sts2.Core.Nodes.CommonUi.NTopBar._Ready" /> 创建当前顶部栏前完成注册。
	///         同一模组重复注册同一 ID 时返回已有定义；其他模组不能占用该 ID。
	///     </para>
	/// </remarks>
	public sealed class ModTopBarButtonRegistry
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, ModTopBarButtonRegistry> Registries = new Dictionary<string, ModTopBarButtonRegistry>(StringComparer.OrdinalIgnoreCase);

		private static readonly Dictionary<string, ModTopBarButtonDefinition> Definitions = new Dictionary<string, ModTopBarButtonDefinition>(StringComparer.OrdinalIgnoreCase);

		private readonly Logger _logger;

		private readonly string _modId;

		private ModTopBarButtonRegistry(string modId)
		{
			_modId = modId;
			_logger = RitsuLibFramework.CreateLogger(modId, (LogType)0);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the registry for <paramref name="modId" />, creating it on first use.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 <paramref name="modId" /> 的注册表；首次使用时创建该注册表。
		///     </para>
		/// </summary>
		public static ModTopBarButtonRegistry For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			modId = modId.Trim();
			using (SyncRoot.EnterScope())
			{
				if (Registries.TryGetValue(modId, out ModTopBarButtonRegistry value))
				{
					return value;
				}
				ModTopBarButtonRegistry modTopBarButtonRegistry = new ModTopBarButtonRegistry(modId);
				Registries[modId] = modTopBarButtonRegistry;
				return modTopBarButtonRegistry;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a button whose global ID is derived from this registry's mod ID and
		///         <paramref name="localStem" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册一个全局 ID 由当前注册表的模组 ID 和 <paramref name="localStem" /> 派生的按钮。
		///     </para>
		/// </summary>
		public ModTopBarButtonDefinition RegisterOwned(string localStem, ModTopBarButtonSpec spec)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(localStem, "localStem");
			ArgumentNullException.ThrowIfNull(spec, "spec");
			string qualifiedTopBarButtonId = ModContentRegistry.GetQualifiedTopBarButtonId(_modId, localStem);
			return RegisterCore(qualifiedTopBarButtonId, spec);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a top-bar button with a global ID. Prefer <see cref="M:STS2RitsuLib.TopBar.ModTopBarButtonRegistry.RegisterOwned(System.String,STS2RitsuLib.TopBar.ModTopBarButtonSpec)" /> to derive
		///         a mod-qualified ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用全局 ID 注册顶部栏按钮。建议使用 <see cref="M:STS2RitsuLib.TopBar.ModTopBarButtonRegistry.RegisterOwned(System.String,STS2RitsuLib.TopBar.ModTopBarButtonSpec)" /> 派生带模组限定的 ID。
		///     </para>
		/// </summary>
		public ModTopBarButtonDefinition Register(string id, ModTopBarButtonSpec spec)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentNullException.ThrowIfNull(spec, "spec");
			return RegisterCore(id, spec);
		}

		/// <summary>
		///     <para xml:lang="en">Looks up a definition by ID.</para>
		///     <para xml:lang="zh-CN">按 ID 查找定义。</para>
		/// </summary>
		public static bool TryGet(string id, out ModTopBarButtonDefinition definition)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			using (SyncRoot.EnterScope())
			{
				return Definitions.TryGetValue(id.Trim(), out definition);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns a snapshot of all registered buttons, ordered by
		///         <see cref="P:STS2RitsuLib.TopBar.ModTopBarButtonDefinition.Order" /> and then ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回所有已注册按钮的快照，依次按 <see cref="P:STS2RitsuLib.TopBar.ModTopBarButtonDefinition.Order" /> 和 ID 排序。
		///     </para>
		/// </summary>
		public static ModTopBarButtonDefinition[] GetDefinitionsSnapshot()
		{
			using (SyncRoot.EnterScope())
			{
				return Definitions.Values.OrderBy((ModTopBarButtonDefinition def) => def.Order).ThenBy<ModTopBarButtonDefinition, string>((ModTopBarButtonDefinition def) => def.Id, StringComparer.Ordinal).ToArray();
			}
		}

		private ModTopBarButtonDefinition RegisterCore(string id, ModTopBarButtonSpec spec)
		{
			string text = id.Trim();
			if (spec.OnClick == null)
			{
				throw new InvalidOperationException("Top-bar button '" + text + "' must provide a non-null OnClick handler.");
			}
			ModTopBarButtonDefinition modTopBarButtonDefinition = new ModTopBarButtonDefinition(_modId, text, spec.IconPath, spec.Order, spec.Offset, spec.OnClick, spec.VisibleWhen, spec.IsOpenWhen, spec.CountProvider);
			using (SyncRoot.EnterScope())
			{
				if (Definitions.TryGetValue(text, out ModTopBarButtonDefinition value))
				{
					if (!StringComparer.OrdinalIgnoreCase.Equals(value.ModId, modTopBarButtonDefinition.ModId))
					{
						throw new InvalidOperationException($"Top-bar button '{text}' is already registered by mod '{value.ModId}'; mod '{modTopBarButtonDefinition.ModId}' cannot re-register it.");
					}
					return value;
				}
				Definitions[text] = modTopBarButtonDefinition;
			}
			_logger.Info($"[TopBar] Registered top-bar button: {text} (Order={spec.Order})", 1);
			return modTopBarButtonDefinition;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Describes a mod-owned action button shown in the vanilla top bar.</para>
	///     <para xml:lang="zh-CN">描述显示在原版顶部栏中、归属于模组的操作按钮。</para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Hover-tip localization uses <c>static_hover_tips</c> keys <c>{id}.title</c> and
	///         <c>{id}.description</c>, where <c>id</c> is the registered global button ID.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         悬停提示本地化使用 <c>static_hover_tips</c> 中的 <c>{id}.title</c> 和
	///         <c>{id}.description</c> 键，其中 <c>id</c> 是已注册的全局按钮 ID。
	///     </para>
	/// </remarks>
	public sealed record ModTopBarButtonSpec
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Godot resource path for the button icon, for example <c>res://my_mod/icon.png</c>.
		///         When omitted, RitsuLib attempts to clone the vanilla deck icon.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         按钮图标的 Godot 资源路径，例如 <c>res://my_mod/icon.png</c>。
		///         未指定时，RitsuLib 会尝试克隆原版牌组图标。
		///     </para>
		/// </summary>
		public string? IconPath { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Global sort order among registered action buttons. Lower values appear closer to the
		///         vanilla deck button.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         已注册操作按钮之间的全局排序值；值越小越靠近原版牌组按钮。
		///     </para>
		/// </summary>
		public int Order { get; init; }

		/// <summary>
		///     <para xml:lang="en">Additional visual offset from the automatically arranged slot, in pixels.</para>
		///     <para xml:lang="zh-CN">相对于自动排列槽位的额外视觉像素偏移。</para>
		/// </summary>
		public Vector2 Offset { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Required click handler. Registration fails if this property is <see langword="null" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         必需的点击回调。此属性为 <see langword="null" /> 时注册失败。
		///     </para>
		/// </summary>
		public Action<ModTopBarButtonContext>? OnClick { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional visibility predicate evaluated during <see cref="M:Godot.Node._Process(System.Double)" />.
		///         <see langword="null" /> keeps the button visible.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <see cref="M:Godot.Node._Process(System.Double)" /> 中求值的可选可见性谓词。
		///         为 <see langword="null" /> 时按钮保持可见。
		///     </para>
		/// </summary>
		public Func<ModTopBarButtonContext, bool>? VisibleWhen { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional predicate evaluated during <see cref="M:Godot.Node._Process(System.Double)" /> to control the
		///         selected/open tilt used by vanilla top-bar buttons. <see langword="null" /> keeps the
		///         button closed.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <see cref="M:Godot.Node._Process(System.Double)" /> 中求值的可选谓词，用于控制原版顶部栏按钮使用的
		///         选中或打开状态倾斜效果。为 <see langword="null" /> 时按钮保持关闭状态。
		///     </para>
		/// </summary>
		public Func<ModTopBarButtonContext, bool>? IsOpenWhen { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional count provider evaluated during <see cref="M:Godot.Node._Process(System.Double)" />.
		///         <see langword="null" /> or a negative result hides the count label. Increases use the
		///         vanilla count-bump animation.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <see cref="M:Godot.Node._Process(System.Double)" /> 中求值的可选数量提供器。
		///         为 <see langword="null" /> 或返回负数时隐藏数量标签；数值增加时使用原版数量弹起动画。
		///     </para>
		/// </summary>
		public Func<ModTopBarButtonContext, int>? CountProvider { get; init; }

		/// <summary>
		///     <para xml:lang="en">Localization table used by the button's hover tip.</para>
		///     <para xml:lang="zh-CN">按钮悬停提示使用的本地化表。</para>
		/// </summary>
		public const string HoverTipLocTable = "static_hover_tips";
	}
	/// <summary>
	///     <para xml:lang="en">Localization constants used by mod top-bar buttons.</para>
	///     <para xml:lang="zh-CN">模组顶部栏按钮使用的本地化常量。</para>
	/// </summary>
	internal static class ModTopBarButtonLocConstants
	{
		public const string HoverTipLocTable = "static_hover_tips";
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Places mod card-pile and action buttons in the vanilla top bar relative to the deck slot.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         相对于原版牌组槽位放置模组牌堆按钮和操作按钮。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         The right-side controls are children of an <see cref="T:Godot.HBoxContainer" /> rather than direct
	///         children of <see cref="T:MegaCrit.Sts2.Core.Nodes.CommonUi.NTopBar" />. This helper reparents each button and adjusts its child
	///         index; the container then determines its screen position.
	///     </para>
	///     <para xml:lang="en">
	///         Repeated calls that place a button before the same anchor put the most recently placed
	///         button closest to that anchor. Callers should therefore place ordered items in reverse.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         顶部栏右侧控件是 <see cref="T:Godot.HBoxContainer" /> 的子节点，并非
	///         <see cref="T:MegaCrit.Sts2.Core.Nodes.CommonUi.NTopBar" /> 的直接子节点。此辅助类会重新设置按钮的父节点并调整子节点索引，
	///         再由容器决定实际屏幕位置。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         连续将按钮放在同一锚点之前时，最后放置的按钮最靠近锚点。因此调用方应按目标顺序的
	///         逆序放置。
	///     </para>
	/// </remarks>
	public static class ModTopBarLayout
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Finds the nearest <see cref="T:Godot.HBoxContainer" /> containing <see cref="P:MegaCrit.Sts2.Core.Nodes.CommonUi.NTopBar.Deck" />,
		///         or the deck button's immediate parent when no such container exists.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         查找包含 <see cref="P:MegaCrit.Sts2.Core.Nodes.CommonUi.NTopBar.Deck" /> 的最近 <see cref="T:Godot.HBoxContainer" />；
		///         不存在时返回牌组按钮的直接父控件。
		///     </para>
		/// </summary>
		public static Control? GetRightAlignedContainer(NTopBar topBar)
		{
			ArgumentNullException.ThrowIfNull(topBar, "topBar");
			NTopBarDeckButton deck = topBar.Deck;
			if (deck == null)
			{
				return null;
			}
			Node parent = ((Node)deck).GetParent();
			while (parent != null)
			{
				Node val = parent;
				HBoxContainer val2 = (HBoxContainer)(object)((val is HBoxContainer) ? val : null);
				if (val2 != null)
				{
					return (Control?)(object)val2;
				}
				parent = val.GetParent();
			}
			Node parent2 = ((Node)deck).GetParent();
			return (Control?)(object)((parent2 is Control) ? parent2 : null);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the direct child of the right-aligned container that contains
		///         <see cref="P:MegaCrit.Sts2.Core.Nodes.CommonUi.NTopBar.Deck" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回右对齐容器中包含 <see cref="P:MegaCrit.Sts2.Core.Nodes.CommonUi.NTopBar.Deck" /> 的直接子节点。
		///     </para>
		/// </summary>
		public static Node? GetDeckSlotAnchor(NTopBar topBar)
		{
			Control rightAlignedContainer = GetRightAlignedContainer(topBar);
			NTopBarDeckButton deck = topBar.Deck;
			if (rightAlignedContainer == null || deck == null)
			{
				return null;
			}
			Node val = (Node)(object)deck;
			while (true)
			{
				Node parent = val.GetParent();
				if (parent == null || (object)parent == rightAlignedContainer)
				{
					break;
				}
				val = parent;
			}
			if ((object)val.GetParent() != rightAlignedContainer)
			{
				return null;
			}
			return val;
		}

		/// <summary>
		///     <para xml:lang="en">Places <paramref name="button" /> immediately before the deck slot.</para>
		///     <para xml:lang="zh-CN">将 <paramref name="button" /> 放在牌组槽位之前的相邻位置。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="false" /> when the deck container is unavailable; otherwise
		///         <see langword="true" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         牌组容器不可用时为 <see langword="false" />；否则为 <see langword="true" />。
		///     </para>
		/// </returns>
		public static bool Place(NTopBar topBar, NModCardPileButton button, Vector2 offset = default(Vector2))
		{
			//IL_002f: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(topBar, "topBar");
			ArgumentNullException.ThrowIfNull(button, "button");
			Control rightAlignedContainer = GetRightAlignedContainer(topBar);
			Node deckSlotAnchor = GetDeckSlotAnchor(topBar);
			if (rightAlignedContainer == null || deckSlotAnchor == null)
			{
				return false;
			}
			return PlaceBeforeAnchor(rightAlignedContainer, deckSlotAnchor, button, offset);
		}

		/// <summary>
		///     <para xml:lang="en">Places <paramref name="button" /> immediately after the deck slot.</para>
		///     <para xml:lang="zh-CN">将 <paramref name="button" /> 放在牌组槽位之后的相邻位置。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="false" /> when the deck container is unavailable; otherwise
		///         <see langword="true" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         牌组容器不可用时为 <see langword="false" />；否则为 <see langword="true" />。
		///     </para>
		/// </returns>
		public static bool PlaceAfterDeck(NTopBar topBar, NModCardPileButton button, Vector2 offset = default(Vector2))
		{
			//IL_002f: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(topBar, "topBar");
			ArgumentNullException.ThrowIfNull(button, "button");
			Control rightAlignedContainer = GetRightAlignedContainer(topBar);
			Node deckSlotAnchor = GetDeckSlotAnchor(topBar);
			if (rightAlignedContainer == null || deckSlotAnchor == null)
			{
				return false;
			}
			return PlaceAfterAnchor(rightAlignedContainer, deckSlotAnchor, button, offset);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Places <paramref name="button" /> immediately before the modifiers slot, falling back to
		///         the position before the deck slot.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将 <paramref name="button" /> 放在特效槽位之前；该槽位不可用时回退到牌组槽位之前。
		///     </para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="false" /> when neither anchor is available; otherwise
		///         <see langword="true" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         两个锚点都不可用时为 <see langword="false" />；否则为 <see langword="true" />。
		///     </para>
		/// </returns>
		public static bool PlaceBeforeModifiers(NTopBar topBar, NModCardPileButton button, Vector2 offset = default(Vector2))
		{
			//IL_0038: Unknown result type (might be due to invalid IL or missing references)
			//IL_0068: Unknown result type (might be due to invalid IL or missing references)
			//IL_005f: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(topBar, "topBar");
			ArgumentNullException.ThrowIfNull(button, "button");
			Control rightAlignedContainer = GetRightAlignedContainer(topBar);
			if (rightAlignedContainer == null)
			{
				return false;
			}
			Control nodeOrNull = ((Node)topBar).GetNodeOrNull<Control>(NodePath.op_Implicit("%Modifiers"));
			if (nodeOrNull == null)
			{
				return Place(topBar, button, offset);
			}
			Node val = (Node)(object)nodeOrNull;
			while (true)
			{
				Node parent = val.GetParent();
				if (parent == null || (object)parent == rightAlignedContainer)
				{
					break;
				}
				val = parent;
			}
			if ((object)val.GetParent() == rightAlignedContainer)
			{
				return PlaceBeforeAnchor(rightAlignedContainer, val, button, offset);
			}
			return Place(topBar, button, offset);
		}

		private static bool PlaceBeforeAnchor(Control container, Node anchor, NModCardPileButton button, Vector2 offset)
		{
			//IL_002d: Unknown result type (might be due to invalid IL or missing references)
			AttachToContainer(container, button);
			int index = anchor.GetIndex(false);
			int index2 = ((Node)button).GetIndex(false);
			int num = ((index2 < index) ? (index - 1) : index);
			if (index2 != num)
			{
				((Node)container).MoveChild((Node)(object)button, num);
			}
			button.ApplyVisualOffset(offset);
			return true;
		}

		private static bool PlaceAfterAnchor(Control container, Node anchor, NModCardPileButton button, Vector2 offset)
		{
			//IL_002d: Unknown result type (might be due to invalid IL or missing references)
			AttachToContainer(container, button);
			int index = anchor.GetIndex(false);
			int index2 = ((Node)button).GetIndex(false);
			int num = ((index2 < index) ? index : (index + 1));
			if (index2 != num)
			{
				((Node)container).MoveChild((Node)(object)button, num);
			}
			button.ApplyVisualOffset(offset);
			return true;
		}

		private static void AttachToContainer(Control container, NModCardPileButton button)
		{
			//IL_0023: Unknown result type (might be due to invalid IL or missing references)
			//IL_002e: Unknown result type (might be due to invalid IL or missing references)
			if ((object)((Node)button).GetParent() != container)
			{
				Node parent = ((Node)button).GetParent();
				if (parent != null)
				{
					parent.RemoveChild((Node)(object)button);
				}
				GodotTreeExtensions.AddChildSafely((Node)(object)container, (Node)(object)button);
			}
			((Control)button).Position = Vector2.Zero;
			((Control)button).Scale = Vector2.One;
		}

		/// <summary>
		///     <para xml:lang="en">Places a button using a <see cref="T:System.Numerics.Vector2" /> visual offset.</para>
		///     <para xml:lang="zh-CN">使用 <see cref="T:System.Numerics.Vector2" /> 类型的视觉偏移放置按钮。</para>
		/// </summary>
		public static bool Place(NTopBar topBar, NModCardPileButton button, Vector2 offset)
		{
			//IL_000e: Unknown result type (might be due to invalid IL or missing references)
			return Place(topBar, button, new Vector2(offset.X, offset.Y));
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Declares a top-bar button registration row for content packs. Registering the row with
	///         <see cref="T:STS2RitsuLib.TopBar.ModTopBarButtonRegistry" /> performs the corresponding button registration.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         声明内容包的顶部栏按钮注册行。将该行注册到 <see cref="T:STS2RitsuLib.TopBar.ModTopBarButtonRegistry" /> 时会执行对应的按钮注册。
	///     </para>
	/// </summary>
	public sealed record TopBarButtonRegistrationEntry
	{
		/// <summary>
		///     <para xml:lang="en">Gets the button ID supplied by this row.</para>
		///     <para xml:lang="zh-CN">获取此注册行提供的按钮 ID。</para>
		/// </summary>
		public string Id { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the button metadata and click behavior applied during registration.</para>
		///     <para xml:lang="zh-CN">获取注册期间应用的按钮元数据和点击行为。</para>
		/// </summary>
		public ModTopBarButtonSpec Spec { get; }

		/// <summary>
		///     <para xml:lang="en">Creates a registration row for a provided global top-bar button ID.</para>
		///     <para xml:lang="zh-CN">为给定的全局顶部栏按钮 ID 创建注册行。</para>
		/// </summary>
		/// <param name="id">
		///     <para xml:lang="en">The button ID to register.</para>
		///     <para xml:lang="zh-CN">要注册的按钮 ID。</para>
		/// </param>
		/// <param name="spec">
		///     <para xml:lang="en">The button metadata and click behavior.</para>
		///     <para xml:lang="zh-CN">按钮元数据和点击行为。</para>
		/// </param>
		public TopBarButtonRegistrationEntry(string id, ModTopBarButtonSpec spec)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentNullException.ThrowIfNull(spec, "spec");
			Id = id;
			Spec = spec;
		}

		/// <summary>
		///     <para xml:lang="en">Registers this row with <paramref name="registry" />.</para>
		///     <para xml:lang="zh-CN">将此行注册到 <paramref name="registry" />。</para>
		/// </summary>
		public void Register(ModTopBarButtonRegistry registry)
		{
			ArgumentNullException.ThrowIfNull(registry, "registry");
			registry.Register(Id, Spec);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a registration row whose global button ID is qualified from <paramref name="modId" /> and
		///         <paramref name="localButtonStem" /> through <see cref="M:STS2RitsuLib.Content.ModContentRegistry.GetQualifiedTopBarButtonId(System.String,System.String)" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过 <see cref="M:STS2RitsuLib.Content.ModContentRegistry.GetQualifiedTopBarButtonId(System.String,System.String)" />，使用 <paramref name="modId" />
		///         和 <paramref name="localButtonStem" /> 限定全局按钮 ID 后创建注册行。
		///     </para>
		/// </summary>
		public static TopBarButtonRegistrationEntry Owned(string modId, string localButtonStem, ModTopBarButtonSpec spec)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(localButtonStem, "localButtonStem");
			ArgumentNullException.ThrowIfNull(spec, "spec");
			return new TopBarButtonRegistrationEntry(ModContentRegistry.GetQualifiedTopBarButtonId(modId, localButtonStem), spec);
		}
	}
}
namespace STS2RitsuLib.TopBar.Patches
{
	/// <summary>
	///     <para xml:lang="en">
	///         Creates registered action buttons after the vanilla deck slot becomes available in
	///         <see cref="M:MegaCrit.Sts2.Core.Nodes.CommonUi.NTopBar._Ready" />, then places them in their defined sort order.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         原版牌组槽位在 <see cref="M:MegaCrit.Sts2.Core.Nodes.CommonUi.NTopBar._Ready" /> 中可用后，创建已注册的操作按钮，并按规定的排序值放置。
	///     </para>
	/// </summary>
	internal sealed class ModTopBarActionButtonReadyPatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_top_bar_ready_action_inject";

		public static string Description => "Inject mod action buttons into NTopBar";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NTopBar), "_Ready")
			};
		}

		public static void Postfix(NTopBar __instance)
		{
			ModTopBarButtonDefinition[] definitionsSnapshot = ModTopBarButtonRegistry.GetDefinitionsSnapshot();
			if (definitionsSnapshot.Length != 0)
			{
				for (int num = definitionsSnapshot.Length - 1; num >= 0; num--)
				{
					ModTopBarButtonDefinition modTopBarButtonDefinition = definitionsSnapshot[num];
					NModCardPileButton nModCardPileButton = NModCardPileButton.CreateAction(modTopBarButtonDefinition);
					GodotTreeExtensions.AddChildSafely((Node)(object)__instance, (Node)(object)nModCardPileButton);
					ModTopBarLayout.Place(__instance, nModCardPileButton, modTopBarButtonDefinition.Offset);
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Binds injected action buttons to the local <see cref="T:MegaCrit.Sts2.Core.Entities.Players.Player" /> after
	///         <see cref="M:MegaCrit.Sts2.Core.Nodes.CommonUi.NTopBar.Initialize(MegaCrit.Sts2.Core.Runs.IRunState)" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在 <see cref="M:MegaCrit.Sts2.Core.Nodes.CommonUi.NTopBar.Initialize(MegaCrit.Sts2.Core.Runs.IRunState)" /> 后，将已注入的操作按钮绑定到本地
	///         <see cref="T:MegaCrit.Sts2.Core.Entities.Players.Player" />。
	///     </para>
	/// </summary>
	internal sealed class ModTopBarActionButtonInitializePatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_top_bar_initialize_action_bind";

		public static string Description => "Bind mod action buttons to the local player on NTopBar.Initialize";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NTopBar), "Initialize", new Type[1] { typeof(IRunState) })
			};
		}

		public static void Postfix(NTopBar __instance, IRunState runState)
		{
			Player me = LocalContext.GetMe((IPlayerCollection)(object)runState);
			if (me == null)
			{
				return;
			}
			Control rightAlignedContainer = ModTopBarLayout.GetRightAlignedContainer(__instance);
			if (rightAlignedContainer == null)
			{
				return;
			}
			foreach (NModCardPileButton item in ((IEnumerable)((Node)rightAlignedContainer).GetChildren(false)).OfType<NModCardPileButton>())
			{
				if (item.IsActionMode)
				{
					item.Initialize(me);
				}
			}
		}
	}
}
namespace STS2RitsuLib.Timeline
{
	/// <summary>
	///     <para xml:lang="en">
	///         Maps epoch IDs to card and relic CLR types gated by those epochs. Content-pack flows such as
	///         <see cref="T:STS2RitsuLib.Scaffolding.Content.TimelineColumnPackEntry`1" /> populate the registry, and pack-declared unlock epoch templates
	///         consume it. Potion gating is registered directly with
	///         <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.RequireEpoch(System.Type,System.String)" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将纪元 ID 映射到受其限制的卡牌和遗物 CLR 类型。<see cref="T:STS2RitsuLib.Scaffolding.Content.TimelineColumnPackEntry`1" /> 等内容包流程
	///         会填充此注册表，再由内容包声明的解锁纪元模板使用。药水的纪元限制则直接通过
	///         <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.RequireEpoch(System.Type,System.String)" /> 注册。
	///     </para>
	/// </summary>
	public static class ModEpochGatedContentRegistry
	{
		/// <summary>
		///     <para xml:lang="en">Contains a snapshot of the types registered for one epoch by its owning mod.</para>
		///     <para xml:lang="zh-CN">包含所属模组为一个纪元注册的类型快照。</para>
		/// </summary>
		public sealed record EpochGatedContentEntry(string ModId, IReadOnlyList<Type> CardTypes, IReadOnlyList<Type> RelicTypes);

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, EpochGatedContentEntry> ByEpochId = new Dictionary<string, EpochGatedContentEntry>(StringComparer.Ordinal);

		private static bool _isFrozen;

		/// <summary>
		///     <para xml:lang="en">Gets whether registration has been frozen.</para>
		///     <para xml:lang="zh-CN">获取注册是否已被冻结。</para>
		/// </summary>
		public static bool IsFrozen
		{
			get
			{
				using (SyncRoot.EnterScope())
				{
					return _isFrozen;
				}
			}
		}

		internal static void FreezeRegistrations(string reason)
		{
			using (SyncRoot.EnterScope())
			{
				if (!_isFrozen)
				{
					_isFrozen = true;
				}
			}
		}

		internal static void ValidateFrozenModelReferences()
		{
			EpochGatedContentEntry[] array;
			using (SyncRoot.EnterScope())
			{
				array = ByEpochId.Values.ToArray();
			}
			EpochGatedContentEntry[] array2 = array;
			foreach (EpochGatedContentEntry epochGatedContentEntry in array2)
			{
				foreach (Type cardType in epochGatedContentEntry.CardTypes)
				{
					RegistrationFreezeDiagnostics.WarnMissingModelType("EpochGatedContent", epochGatedContentEntry.ModId, "epoch-gated card", cardType, typeof(CardModel));
				}
				foreach (Type relicType in epochGatedContentEntry.RelicTypes)
				{
					RegistrationFreezeDiagnostics.WarnMissingModelType("EpochGatedContent", epochGatedContentEntry.ModId, "epoch-gated relic", relicType, typeof(RelicModel));
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers the model types gated by the unique <paramref name="epochId" />. At least one card or relic type is
		///         required.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册受唯一 <paramref name="epochId" /> 限制的模型类型。必须至少提供一个卡牌或遗物类型。
		///     </para>
		/// </summary>
		public static void Register(string modId, string epochId, IReadOnlyList<Type>? cardTypes, IReadOnlyList<Type>? relicTypes)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(epochId, "epochId");
			IReadOnlyList<Type> readOnlyList = SnapshotTypes<CardModel>(cardTypes, "cardTypes");
			IReadOnlyList<Type> readOnlyList2 = SnapshotTypes<RelicModel>(relicTypes, "relicTypes");
			if (readOnlyList.Count == 0 && readOnlyList2.Count == 0)
			{
				throw new ArgumentException("Gated content for epoch '" + epochId + "' must include at least one card or relic type.", "cardTypes");
			}
			using (SyncRoot.EnterScope())
			{
				EnsureMutable("register gated content for epoch '" + epochId + "'");
				if (ByEpochId.ContainsKey(epochId))
				{
					throw new InvalidOperationException("Epoch gated content was already registered for id '" + epochId + "'.");
				}
				ByEpochId[epochId] = new EpochGatedContentEntry(modId, readOnlyList, readOnlyList2);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether a content pack registered gated types for <paramref name="epochId" />.
		///     </para>
		///     <para xml:lang="zh-CN">返回内容包是否为 <paramref name="epochId" /> 注册了受限类型。</para>
		/// </summary>
		public static bool TryGet(string epochId, out EpochGatedContentEntry entry)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(epochId, "epochId");
			using (SyncRoot.EnterScope())
			{
				return ByEpochId.TryGetValue(epochId, out entry);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Resolves the <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> instances gated by an epoch ID.</para>
		///     <para xml:lang="zh-CN">解析受指定纪元 ID 限制的 <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> 实例。</para>
		/// </summary>
		public static IReadOnlyList<CardModel> ResolveCards(string epochId)
		{
			if (!TryGet(epochId, out EpochGatedContentEntry entry))
			{
				return Array.Empty<CardModel>();
			}
			List<CardModel> list = new List<CardModel>();
			list.AddRange(entry.CardTypes.Select((Type type) => ModelDb.GetById<CardModel>(ModelDb.GetId(type))));
			return new <>z__ReadOnlyList<CardModel>(list);
		}

		/// <summary>
		///     <para xml:lang="en">Resolves the <see cref="T:MegaCrit.Sts2.Core.Models.RelicModel" /> instances gated by an epoch ID.</para>
		///     <para xml:lang="zh-CN">解析受指定纪元 ID 限制的 <see cref="T:MegaCrit.Sts2.Core.Models.RelicModel" /> 实例。</para>
		/// </summary>
		public static IReadOnlyList<RelicModel> ResolveRelics(string epochId)
		{
			if (!TryGet(epochId, out EpochGatedContentEntry entry))
			{
				return Array.Empty<RelicModel>();
			}
			List<RelicModel> list = new List<RelicModel>();
			list.AddRange(entry.RelicTypes.Select((Type type) => ModelDb.GetById<RelicModel>(ModelDb.GetId(type))));
			return new <>z__ReadOnlyList<RelicModel>(list);
		}

		private static void EnsureMutable(string operation)
		{
			if (!_isFrozen)
			{
				return;
			}
			throw new InvalidOperationException("Cannot " + operation + " after epoch gated content registration has been frozen.");
		}

		private static IReadOnlyList<Type> SnapshotTypes<TModel>(IReadOnlyList<Type>? types, string paramName) where TModel : AbstractModel
		{
			if (types == null || types.Count == 0)
			{
				return Array.AsReadOnly(Array.Empty<Type>());
			}
			Type[] array = types.ToArray();
			HashSet<Type> hashSet = new HashSet<Type>();
			Type[] array2 = array;
			foreach (Type type in array2)
			{
				if (type == null || type.IsAbstract || type.IsInterface || type.ContainsGenericParameters || !typeof(TModel).IsAssignableFrom(type))
				{
					throw new ArgumentException($"Type '{type?.FullName ?? "<null>"}' must be a closed concrete {typeof(TModel).Name} subtype.", paramName);
				}
				if (!hashSet.Add(type))
				{
					throw new ArgumentException("Type '" + type.FullName + "' is listed more than once.", paramName);
				}
			}
			return Array.AsReadOnly(array);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Collects ordered epoch CLR types for each concrete <see cref="T:MegaCrit.Sts2.Core.Timeline.StoryModel" /> type.
	///         <see cref="M:STS2RitsuLib.Timeline.ModTimelineRegistry.RegisterStoryEpoch``2" /> adds entries, and
	///         <see cref="T:STS2RitsuLib.Timeline.Scaffolding.ModStoryTemplate" /> reads them instead of using a hard-coded type list.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为每个具体 <see cref="T:MegaCrit.Sts2.Core.Timeline.StoryModel" /> 类型收集有序的纪元 CLR 类型。
	///         <see cref="M:STS2RitsuLib.Timeline.ModTimelineRegistry.RegisterStoryEpoch``2" /> 会添加条目，
	///         <see cref="T:STS2RitsuLib.Timeline.Scaffolding.ModStoryTemplate" /> 则读取这些条目，而非使用硬编码的类型列表。
	///     </para>
	/// </summary>
	public static class ModStoryEpochBindings
	{
		private static readonly Lock Sync = new Lock();

		private static readonly Dictionary<Type, List<Type>> StoryToEpochs = new Dictionary<Type, List<Type>>();

		private static readonly Dictionary<Type, Type> EpochToStory = new Dictionary<Type, Type>();

		private static bool _frozen;

		/// <summary>
		///     <para xml:lang="en">
		///         Appends <paramref name="epochType" /> to <paramref name="storyType" />'s column in registration order.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         按注册顺序将 <paramref name="epochType" /> 追加到 <paramref name="storyType" /> 的列中。
		///     </para>
		/// </summary>
		/// <exception cref="T:System.InvalidOperationException">
		///     <para xml:lang="en">
		///         Registration is frozen, the epoch is already present in this story, or the epoch belongs to another story.
		///     </para>
		///     <para xml:lang="zh-CN">注册已被冻结、该纪元已存在于此故事中，或该纪元已属于另一个故事。</para>
		/// </exception>
		public static void Append(Type storyType, Type epochType)
		{
			ArgumentNullException.ThrowIfNull(storyType, "storyType");
			ArgumentNullException.ThrowIfNull(epochType, "epochType");
			if (!typeof(StoryModel).IsAssignableFrom(storyType) || storyType.IsAbstract || storyType.IsInterface || storyType.ContainsGenericParameters || storyType.GetConstructor(Type.EmptyTypes) == null)
			{
				throw new ArgumentException("Type '" + storyType.FullName + "' must be a closed concrete StoryModel subtype with a public parameterless constructor.", "storyType");
			}
			if (!typeof(EpochModel).IsAssignableFrom(epochType) || epochType.IsAbstract || epochType.IsInterface || epochType.ContainsGenericParameters || epochType.GetConstructor(Type.EmptyTypes) == null)
			{
				throw new ArgumentException("Type '" + epochType.FullName + "' must be a closed concrete EpochModel subtype with a public parameterless constructor.", "epochType");
			}
			using (Sync.EnterScope())
			{
				ThrowIfFrozen();
				if (EpochToStory.TryGetValue(epochType, out Type value) && value != storyType)
				{
					throw new InvalidOperationException($"Epoch type '{epochType.Name}' is already bound to story '{value.Name}'; cannot bind to '{storyType.Name}'.");
				}
				if (!StoryToEpochs.TryGetValue(storyType, out List<Type> value2))
				{
					value2 = new List<Type>();
				}
				if (value2.Contains(epochType))
				{
					throw new InvalidOperationException($"Epoch type '{epochType.Name}' is already listed for story '{storyType.Name}'.");
				}
				EpochToStory[epochType] = storyType;
				StoryToEpochs.TryAdd(storyType, value2);
				value2.Add(epochType);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the ordered epoch types for a concrete story type, or an empty list when none are bound.
		///     </para>
		///     <para xml:lang="zh-CN">返回具体故事类型的有序纪元类型；没有绑定时返回空列表。</para>
		/// </summary>
		public static IReadOnlyList<Type> GetOrderedEpochTypes(Type storyConcreteType)
		{
			ArgumentNullException.ThrowIfNull(storyConcreteType, "storyConcreteType");
			using (Sync.EnterScope())
			{
				List<Type> value;
				return StoryToEpochs.TryGetValue(storyConcreteType, out value) ? value.ToArray() : Array.Empty<Type>();
			}
		}

		internal static void Freeze()
		{
			using (Sync.EnterScope())
			{
				_frozen = true;
			}
		}

		private static void ThrowIfFrozen()
		{
			if (_frozen)
			{
				throw new InvalidOperationException("Story–epoch bindings are frozen; register before model initialization.");
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Registers timeline-axis icon policies by era.</para>
	///     <para xml:lang="zh-CN">按时代注册时间线坐标轴图标策略。</para>
	/// </summary>
	public static class ModTimelineEraIconRegistry
	{
		private readonly record struct EraIconRule(bool? Enabled, string? TexturePath);

		private static readonly Lock Sync = new Lock();

		private static readonly Dictionary<long, EraIconRule> RulesByEra = new Dictionary<long, EraIconRule>();

		/// <summary>
		///     <para xml:lang="en">Configures the icon policy for an <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochEra" /> value.</para>
		///     <para xml:lang="zh-CN">为 <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochEra" /> 值配置图标策略。</para>
		/// </summary>
		public static void Configure(EpochEra era, bool? enabled = null, string? texturePath = null)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			Configure((long)era, enabled, texturePath);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Configures the icon policy for an era's integer value, including custom values absent from the enum.
		///     </para>
		///     <para xml:lang="zh-CN">为时代的整数值配置图标策略，也支持未在枚举中定义的自定义值。</para>
		/// </summary>
		public static void Configure(long eraValue, bool? enabled = null, string? texturePath = null)
		{
			ValidateEraValue(eraValue);
			using (Sync.EnterScope())
			{
				RulesByEra[eraValue] = new EraIconRule(enabled, string.IsNullOrWhiteSpace(texturePath) ? null : texturePath.Trim());
			}
		}

		/// <summary>
		///     <para xml:lang="en">Clears the icon policy for an <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochEra" /> value.</para>
		///     <para xml:lang="zh-CN">清除 <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochEra" /> 值的图标策略。</para>
		/// </summary>
		public static void Clear(EpochEra era)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			Clear((long)era);
		}

		/// <summary>
		///     <para xml:lang="en">Clears the icon policy for an era's integer value.</para>
		///     <para xml:lang="zh-CN">清除时代整数值的图标策略。</para>
		/// </summary>
		public static void Clear(long eraValue)
		{
			ValidateEraValue(eraValue);
			using (Sync.EnterScope())
			{
				RulesByEra.Remove(eraValue);
			}
		}

		private static void ValidateEraValue(long eraValue)
		{
			if ((eraValue < int.MinValue || eraValue > int.MaxValue) ? true : false)
			{
				throw new ArgumentOutOfRangeException("eraValue", eraValue, "EpochEra uses 32-bit integer values.");
			}
		}

		internal static bool TryResolve(EpochEra era, out bool? enabled, out string? texturePath)
		{
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			using (Sync.EnterScope())
			{
				if (!RulesByEra.TryGetValue((long)era, out var value))
				{
					enabled = null;
					texturePath = null;
					return false;
				}
				enabled = value.Enabled;
				texturePath = value.TexturePath;
				return true;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Registers the <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochEra" /> column and <c>EraPosition</c> used to place each
	///         <see cref="T:STS2RitsuLib.Timeline.Scaffolding.ModEpochTemplate" />. Base-game <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochModel" /> instances reserve their cells first,
	///         preventing
	///         mod slots from silently overlapping them.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         注册各 <see cref="T:STS2RitsuLib.Timeline.Scaffolding.ModEpochTemplate" /> 在时间线中使用的 <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochEra" /> 列和列内
	///         <c>EraPosition</c>。游戏本体的 <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochModel" /> 实例会先占用其格位，避免模组槽位与之静默重叠。
	///     </para>
	/// </summary>
	public static class ModTimelineLayoutRegistry
