		internal static void FreezeAndValidate()
		{
			using (Sync.EnterScope())
			{
				if (!_frozen)
				{
					EnsureVanillaOccupancySeededLocked();
					AssertEveryModEpochTemplateHasLayoutLocked();
					_frozen = true;
				}
			}
		}

		private static void ThrowIfFrozen()
		{
