			//IL_0075: Expected O, but got Unknown
			//IL_007b: Unknown result type (might be due to invalid IL or missing references)
			if (_vanillaSeeded)
			{
				return;
			}
			Type[] types = typeof(EpochModel).Assembly.GetTypes();
			foreach (Type type in types)
			{
				if ((object)type != null && type.IsClass && !type.IsAbstract && typeof(EpochModel).IsAssignableFrom(type))
				{
					EpochModel val = (EpochModel)(Activator.CreateInstance(type) ?? throw new InvalidOperationException("Could not construct built-in Epoch type '" + type.FullName + "'."));
					Occupied.Add(ToOccupancyKey(val.Era, val.EraPosition));
				}
			}
			_vanillaSeeded = true;
		}

		private static void AssertEveryModEpochTemplateHasLayoutLocked()
		{
			foreach (Type item in GetRegisteredEpochTypesFromGameDictionary())
			{
				if (typeof(ModEpochTemplate).IsAssignableFrom(item) && !LayoutByEpochType.ContainsKey(item))
				{
					throw new InvalidOperationException($"Epoch type '{item.Name}' inherits {"ModEpochTemplate"} but has no timeline layout. " + "Add .TimelineSlot, .AutoTimelineSlot, .AutoTimelineSlotBeforeColumn / AfterColumn, or BeforeEpoch / AfterEpoch in your timeline column pack.");
				}
			}
		}

		private static IEnumerable<Type> GetRegisteredEpochTypesFromGameDictionary()
		{
			if ((typeof(EpochModel).GetField("_typeToIdDictionary", BindingFlags.Static | BindingFlags.NonPublic) ?? throw new MissingFieldException(typeof(EpochModel).FullName, "_typeToIdDictionary")).GetValue(null) is Dictionary<Type, string> dictionary)
			{
				return dictionary.Keys;
			}
			throw new InvalidOperationException("EpochModel._typeToIdDictionary is unavailable.");
		}

		private static void ThrowIfLayoutAlreadyRegistered(Type epochType)
