	internal static class ModTimelineNeowCoExpansion
	{
		private static int _neowQueueUnlocksDepth;

		private static int _pendingNeowAnimatedSlotMerge;

		private static readonly Lock ExpansionInspectionWarningLock = new Lock();

		private static readonly HashSet<string> WarnedExpansionInspectionFailures = new HashSet<string>();

		private static bool IsInsideNeowQueueUnlocks => Volatile.Read(in _neowQueueUnlocksDepth) > 0;

		internal static void EnterNeowQueueUnlocks()
		{
			Interlocked.Increment(ref _neowQueueUnlocksDepth);
		}

		internal static void ExitNeowQueueUnlocks()
		{
			Interlocked.Decrement(ref _neowQueueUnlocksDepth);
		}

		internal static bool TryConsumePendingNeowAnimatedSlotMerge()
		{
			return Interlocked.Exchange(ref _pendingNeowAnimatedSlotMerge, 0) != 0;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether Neow's primary base-game expansion has begun writing slots to progression data, as indicated
		///         by <see cref="T:MegaCrit.Sts2.Core.Timeline.Epochs.Colorless1Epoch" />. This prevents a cold-open timeline from displaying every mod story column
		///         before the expansion.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         根据 <see cref="T:MegaCrit.Sts2.Core.Timeline.Epochs.Colorless1Epoch" /> 判断涅奥的游戏本体主扩展是否已开始将槽位写入进度数据。
		///         这可避免在扩展发生前首次打开时间线时便显示所有模组故事列。
		///     </para>
		/// </summary>
		internal static bool HasVanillaNeowTimelineExpansionStarted(ProgressState? progress)
		{
			if (progress != null)
			{
				return progress.HasEpoch(EpochModel.GetId<Colorless1Epoch>());
			}
			return false;
		}

		internal static bool IsNeowPrimaryTimelineExpansion(EpochModel[] epochs)
		{
			if (epochs == null || epochs.Length < 8)
			{
				return false;
			}
			HashSet<string> hashSet = epochs.Select((EpochModel e) => e.Id).ToHashSet();
			if (hashSet.Contains(EpochModel.GetId<Colorless1Epoch>()))
			{
				return hashSet.Contains(EpochModel.GetId<Silent1Epoch>());
			}
			return false;
		}

		internal static bool IsNeowPrimaryTimelineExpansionSlots(IReadOnlyList<EpochSlotData> slots)
		{
			if (slots == null || slots.Count < 8)
			{
				return false;
			}
			HashSet<string> hashSet = slots.Select((EpochSlotData s) => s.Model.Id).ToHashSet();
			if (hashSet.Contains(EpochModel.GetId<Colorless1Epoch>()))
			{
				return hashSet.Contains(EpochModel.GetId<Silent1Epoch>());
			}
			return false;
		}

		internal static IReadOnlyList<string> GetModCharacterRootEpochIdsUnlockedAfterRunAs(ModelId prerequisiteCharacterId)
		{
			List<string> list = new List<string>();
