		///         处理 <see cref="M:MegaCrit.Sts2.Core.Timeline.EpochModel.QueueTimelineExpansion(MegaCrit.Sts2.Core.Timeline.EpochModel[])" /> 的后置补丁。当主扩展由
		///         <see cref="M:MegaCrit.Sts2.Core.Timeline.Epochs.NeowEpoch.QueueUnlocks" /> 发起时，为符合条件的模组纪元解锁槽位，并安排其动画合并。
		///     </para>
		/// </summary>
		internal static void OnQueueTimelineExpansionPostfix(EpochModel[] vanillaEpochs)
		{
			if (IsInsideNeowQueueUnlocks && IsNeowPrimaryTimelineExpansion(vanillaEpochs))
			{
				UnlockModEpochSlotsCore(vanillaEpochs);
				Interlocked.Exchange(ref _pendingNeowAnimatedSlotMerge, 1);
			}
		}

		private static void UnlockModEpochSlotsCore(EpochModel[] vanillaEpochs)
		{
			//IL_00ae: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b4: Invalid comparison between Unknown and I4
			ProgressState progress = SaveManager.Instance.Progress;
			HashSet<string> hashSet = vanillaEpochs.Select((EpochModel e) => e.Id).ToHashSet();
			foreach (string id in EpochModel.AllEpochIds)
			{
				if (hashSet.Contains(id))
				{
					continue;
				}
				EpochModel val;
				try
				{
					val = EpochModel.Get(id);
				}
				catch
				{
					continue;
				}
				if (val is ModEpochTemplate && !TryPromoteNeowCharacterRootUnlock(val, progress))
				{
					SerializableEpoch val2 = progress.Epochs.FirstOrDefault((SerializableEpoch e) => e.Id == id);
					if ((val2 != null && (int)val2.State == 3) || (val2 == null && IsModTimelineRootSlot(id)))
					{
						SaveManager.Instance.UnlockSlot(id);
					}
				}
			}
		}

