				if (val.Model is ModEpochTemplate && (int)ResolveMergedModSlotState(val.Model.Id, progress) == 3 && !ShouldShowUnobtainedModSlot(val.Model.Id, progress))
				{
					slotsToAdd.RemoveAt(num);
				}
			}
		}

		private static bool ShouldShowUnobtainedModSlot(string id, ProgressState? progress)
		{
			if (!IsModTimelineRootSlot(id))
			{
				return IsParentVisibleUnobtainedModSlot(id, progress);
			}
			return true;
		}

		private static bool ShouldObtainWithNeow(EpochModel model)
		{
			if (TryGetCharacterRootUnlockPrerequisite(model, out ModelId prerequisiteId))
			{
				return prerequisiteId == ModelDb.GetId<Ironclad>();
			}
			return false;
		}

		private static bool TryGetCharacterRootUnlockPrerequisite(EpochModel model, out ModelId prerequisiteId)
		{
			prerequisiteId = null;
			if (!(model is ModEpochTemplate))
			{
				return false;
			}
			if (!IsModTimelineRootSlot(model.Id))
			{
				return false;
			}
			if (!TryGetCharacterUnlockType(((object)model).GetType(), out Type characterType))
			{
				return false;
			}
			CharacterModel byIdOrNull;
			try
			{
				byIdOrNull = ModelDb.GetByIdOrNull<CharacterModel>(ModelDb.GetId(characterType));
			}
			catch
			{
				return false;
			}
			if (byIdOrNull == null || ModCharacterTimelinePolicy.DoesNotRequireEpochAndTimeline(byIdOrNull))
			{
				return false;
			}
			if (byIdOrNull is IModCharacterUnlockPrerequisite modCharacterUnlockPrerequisite)
			{
				Type unlocksAfterRunAsType = modCharacterUnlockPrerequisite.UnlocksAfterRunAsType;
				if ((object)unlocksAfterRunAsType != null)
				{
					try
					{
						prerequisiteId = ModelDb.GetId(unlocksAfterRunAsType);
						return true;
					}
					catch
					{
						return false;
					}
				}
			}
			return false;
		}

		private static bool TryGetCharacterUnlockType(Type epochType, out Type characterType)
		{
			Type type = epochType;
			while (type != null)
			{
				if (type.IsGenericType && !(type.GetGenericTypeDefinition() != typeof(CharacterUnlockEpochTemplate<>)))
				{
					characterType = type.GetGenericArguments()[0];
					return true;
				}
				type = type.BaseType;
			}
			characterType = typeof(CharacterModel);
			return false;
		}

		private static bool IsModTimelineRootSlot(string id)
		{
			foreach (string allEpochId in EpochModel.AllEpochIds)
			{
				if (!(allEpochId == id))
				{
					EpochModel parent;
					try
					{
						parent = EpochModel.Get(allEpochId);
					}
					catch
					{
						continue;
					}
					if (!TryHasExpansionChild(parent, id, out var hasChild))
					{
						return false;
					}
					if (hasChild)
					{
						return false;
					}
				}
			}
			return true;
		}

		private static bool IsParentVisibleUnobtainedModSlot(string id, ProgressState? progress)
		{
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			//IL_0036: Invalid comparison between Unknown and I4
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			//IL_005b: Invalid comparison between Unknown and I4
			if (progress == null)
			{
				return false;
			}
			SerializableEpoch? obj = progress.Epochs.FirstOrDefault((SerializableEpoch e) => e.Id == id);
			if (obj == null || (int)obj.State != 2)
			{
				return false;
			}
			foreach (SerializableEpoch epoch in progress.Epochs)
			{
				if ((int)epoch.State >= 5)
				{
					EpochModel parent;
					try
					{
						parent = EpochModel.Get(epoch.Id);
					}
					catch
					{
						continue;
					}
					if (TryHasExpansionChild(parent, id, out var hasChild) & hasChild)
					{
						return true;
					}
				}
			}
			return false;
		}

		private static bool TryHasExpansionChild(EpochModel parent, string childId, out bool hasChild)
		{
			try
			{
				hasChild = parent.GetTimelineExpansion().Any((EpochModel child) => child.Id == childId);
				return true;
			}
			catch (Exception ex)
			{
				using (ExpansionInspectionWarningLock.EnterScope())
				{
					if (!WarnedExpansionInspectionFailures.Add(parent.Id))
					{
						hasChild = false;
						return false;
					}
				}
				RitsuLibFramework.Logger.Warn("[Timeline] Failed to inspect expansion children for Epoch '" + parent.Id + "': " + ex.Message, 1);
				hasChild = false;
				return false;
			}
		}

		private static EpochSlotState ResolveMergedModSlotState(string id, ProgressState? progress)
		{
