			SerializableEpoch val = progress.Epochs.FirstOrDefault((SerializableEpoch e) => e.Id == id);
			if (val == null)
			{
				return (EpochSlotState)3;
			}
			EpochState state = val.State;
			return (EpochSlotState)((state - 3) switch
			{
				2 => 1, 
				1 => 2, 
				0 => 2, 
				_ => 3, 
			});
		}

