	/// <summary>
	///     <para xml:lang="en">
	///         Adds a mod's custom <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochModel" /> and <see cref="T:MegaCrit.Sts2.Core.Timeline.StoryModel" /> types to the game's timeline
	///         dictionaries. An epoch represents one unlock slot; a story groups ordered epochs under one progression column.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将模组自定义的 <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochModel" /> 和 <see cref="T:MegaCrit.Sts2.Core.Timeline.StoryModel" /> 类型加入游戏的时间线字典。
	///         一个纪元表示一个解锁槽位；一个故事会将有序纪元归入同一进度列。
	///     </para>
	/// </summary>
	public sealed class ModTimelineRegistry
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, ModTimelineRegistry> Registries = new Dictionary<string, ModTimelineRegistry>(StringComparer.OrdinalIgnoreCase);

		private static readonly HashSet<Type> RegisteredEpochTypes = new HashSet<Type>();

		private static readonly HashSet<Type> RegisteredStoryTypes = new HashSet<Type>();

		private readonly Logger _logger;

		private readonly string _modId;

		private string? _freezeReason;

		/// <summary>
		///     <para xml:lang="en">Gets whether the framework has frozen further epoch and story registration.</para>
		///     <para xml:lang="zh-CN">获取框架是否已冻结后续纪元与故事注册。</para>
		/// </summary>
		public static bool IsFrozen { get; private set; }

		private ModTimelineRegistry(string modId)
		{
			_modId = modId;
			_logger = RitsuLibFramework.CreateLogger(modId, (LogType)0);
		}

		/// <summary>
		///     <para xml:lang="en">Returns the timeline registry for <paramref name="modId" />.</para>
		///     <para xml:lang="zh-CN">返回 <paramref name="modId" /> 对应的时间线注册表。</para>
		/// </summary>
		public static ModTimelineRegistry For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (SyncRoot.EnterScope())
			{
				if (Registries.TryGetValue(modId, out ModTimelineRegistry value))
				{
					return value;
				}
				value = new ModTimelineRegistry(modId);
				Registries[modId] = value;
				return value;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers a concrete epoch type with the game's epoch discovery.</para>
		///     <para xml:lang="zh-CN">向游戏的纪元发现机制注册具体纪元类型。</para>
		/// </summary>
		public void RegisterEpoch<TEpoch>() where TEpoch : EpochModel, new()
		{
			RegisterEpoch(typeof(TEpoch));
		}

		/// <summary>
		///     <para xml:lang="en">Registers <paramref name="epochType" /> with the game's epoch discovery.</para>
		///     <para xml:lang="zh-CN">向游戏的纪元发现机制注册 <paramref name="epochType" />。</para>
		/// </summary>
		public void RegisterEpoch(Type epochType)
		{
			EnsureSubtype(epochType, typeof(EpochModel), "epochType");
			EnsureMutable("register epoch '" + epochType.Name + "'");
			string epochId = GetEpochId(epochType);
			using (SyncRoot.EnterScope())
			{
				RegistrationConflictDetector.ThrowIfEpochIdConflicts(epochId, epochType, GetKnownEpochTypes());
				if (RegisteredEpochTypes.Contains(epochType))
				{
					_logger.Debug($"[Timeline] Skipping duplicate epoch registration: {epochType.Name} (id={epochId})", 1);
					return;
				}
				Dictionary<string, Type> staticField = GetStaticField<Dictionary<string, Type>>(typeof(EpochModel), "_epochTypeDictionary");
				Dictionary<Type, string> staticField2 = GetStaticField<Dictionary<Type, string>>(typeof(EpochModel), "_typeToIdDictionary");
				staticField.Add(epochId, epochType);
				bool flag = false;
				try
				{
					staticField2.Add(epochType, epochId);
					flag = AddEpochTypeToAllEpochsLocked(epochType);
					RefreshAllEpochIdsSnapshotLocked();
					RegisteredEpochTypes.Add(epochType);
				}
				catch
				{
					staticField.Remove(epochId);
					staticField2.Remove(epochType);
					if (flag)
					{
						RemoveEpochTypeFromAllEpochsLocked(epochType);
					}
					RefreshAllEpochIdsSnapshotLocked();
					throw;
				}
			}
			_logger.Info($"[Timeline] Registered epoch: {epochType.Name} (id={epochId})", 1);
		}

		/// <summary>
		///     <para xml:lang="en">Registers a concrete story type in the game's story-type dictionary.</para>
		///     <para xml:lang="zh-CN">向游戏的故事类型字典注册具体故事类型。</para>
		/// </summary>
		public void RegisterStory<TStory>() where TStory : StoryModel, new()
		{
			RegisterStory(typeof(TStory));
		}

		/// <summary>
		///     <para xml:lang="en">Registers <paramref name="storyType" /> in the game's story-type dictionary.</para>
		///     <para xml:lang="zh-CN">向游戏的故事类型字典注册 <paramref name="storyType" />。</para>
		/// </summary>
		public void RegisterStory(Type storyType)
		{
			EnsureSubtype(storyType, typeof(StoryModel), "storyType");
			EnsureMutable("register story '" + storyType.Name + "'");
			string storyId = GetStoryId(storyType);
			using (SyncRoot.EnterScope())
			{
				RegistrationConflictDetector.ThrowIfStoryIdConflicts(storyId, storyType, GetKnownStoryTypes());
				if (RegisteredStoryTypes.Contains(storyType))
				{
					_logger.Debug($"[Timeline] Skipping duplicate story registration: {storyType.Name} (id={storyId})", 1);
					return;
				}
				GetStaticField<Dictionary<string, Type>>(typeof(StoryModel), "_storyTypeDictionary").Add(storyId, storyType);
				RegisteredStoryTypes.Add(storyType);
			}
			_logger.Info($"[Timeline] Registered story: {storyType.Name} (id={storyId})", 1);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers <typeparamref name="TEpoch" /> with the game's epoch discovery and appends it to
		///         <typeparamref name="TStory" />'s ordered column through <see cref="T:STS2RitsuLib.Timeline.ModStoryEpochBindings" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         向游戏的纪元发现机制注册 <typeparamref name="TEpoch" />，并通过 <see cref="T:STS2RitsuLib.Timeline.ModStoryEpochBindings" />
		///         将其追加到 <typeparamref name="TStory" /> 的有序列。
		///     </para>
		/// </summary>
		public void RegisterStoryEpoch<TStory, TEpoch>() where TStory : StoryModel, new() where TEpoch : EpochModel, new()
		{
			RegisterStoryEpoch(typeof(TStory), typeof(TEpoch));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers <paramref name="epochType" /> and binds it to <paramref name="storyType" />'s story column.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册 <paramref name="epochType" />，并将其绑定到 <paramref name="storyType" /> 的故事列。
		///     </para>
		/// </summary>
		public void RegisterStoryEpoch(Type storyType, Type epochType)
		{
			EnsureSubtype(storyType, typeof(StoryModel), "storyType");
			EnsureSubtype(epochType, typeof(EpochModel), "epochType");
			EnsureMutable($"register story-epoch binding '{storyType.Name}' ← '{epochType.Name}'");
			RegisterEpoch(epochType);
			ModStoryEpochBindings.Append(storyType, epochType);
			_logger.Info("[Timeline] Story-epoch binding: " + storyType.Name + " ← " + epochType.Name, 1);
		}

		internal static void FreezeRegistrations(string reason)
		{
			using (SyncRoot.EnterScope())
			{
				if (IsFrozen)
				{
					return;
				}
				IsFrozen = true;
				ModStoryEpochBindings.Freeze();
				foreach (ModTimelineRegistry value in Registries.Values)
				{
					value._freezeReason = reason;
				}
			}
			ModTimelineLayoutRegistry.FreezeAndValidate();
		}

		internal static int RegisteredEpochCount()
		{
			using (SyncRoot.EnterScope())
			{
				return RegisteredEpochTypes.Count;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Rebuilds <see cref="P:MegaCrit.Sts2.Core.Timeline.EpochModel.AllEpochIds" /> from the live <c>_epochTypeDictionary</c>, keeping
		///         <see cref="M:MegaCrit.Sts2.Core.Timeline.EpochModel.IsValid(System.String)" /> consistent with <see cref="M:MegaCrit.Sts2.Core.Timeline.EpochModel.Get(System.String)" /> after third-party dictionary
		///         edits or early initialization of the base-game ID cache.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         根据实时 <c>_epochTypeDictionary</c> 重建 <see cref="P:MegaCrit.Sts2.Core.Timeline.EpochModel.AllEpochIds" />，使第三方修改字典或
		///         游戏本体过早初始化 ID 缓存后，<see cref="M:MegaCrit.Sts2.Core.Timeline.EpochModel.IsValid(System.String)" /> 仍与 <see cref="M:MegaCrit.Sts2.Core.Timeline.EpochModel.Get(System.String)" /> 保持一致。
		///     </para>
		/// </summary>
		internal static void EnsureAllEpochIdsSyncedWithDictionary()
		{
			using (SyncRoot.EnterScope())
			{
				RefreshAllEpochIdsSnapshotLocked();
			}
		}

		internal static string GetEpochId(Type epochType)
		{
			EnsureSubtype(epochType, typeof(EpochModel), "epochType");
			object? obj = Activator.CreateInstance(epochType);
			EpochModel val = (EpochModel)(((obj is EpochModel) ? obj : null) ?? throw new InvalidOperationException("Could not construct epoch type '" + epochType.FullName + "'."));
			if (!string.IsNullOrWhiteSpace(val.Id))
			{
				return val.Id.Trim();
			}
			throw new InvalidOperationException("Epoch type '" + epochType.FullName + "' returned an empty Id.");
		}

		private void EnsureMutable(string operation)
		{
			if (!IsFrozen)
			{
				return;
			}
			throw new InvalidOperationException($"Cannot {operation} after timeline registration has been frozen ({_freezeReason ?? "unknown"}). " + "Register custom stories and epochs from your mod initializer before model initialization.");
		}

		private static void EnsureSubtype(Type type, Type expectedBaseType, string paramName)
		{
			ArgumentNullException.ThrowIfNull(type, paramName);
			ArgumentNullException.ThrowIfNull(expectedBaseType, "expectedBaseType");
			if (type.IsAbstract || type.IsInterface || type.ContainsGenericParameters || type.GetConstructor(Type.EmptyTypes) == null || !expectedBaseType.IsAssignableFrom(type))
			{
				throw new ArgumentException($"Type '{type.FullName}' must be a closed concrete subtype of '{expectedBaseType.FullName}' " + "with a public parameterless constructor.", paramName);
			}
		}

		private static Type[] GetKnownEpochTypes()
		{
			return GetStaticField<Dictionary<Type, string>>(typeof(EpochModel), "_typeToIdDictionary").Keys.ToArray();
		}

		private static Type[] GetKnownStoryTypes()
		{
			return GetStaticField<Dictionary<string, Type>>(typeof(StoryModel), "_storyTypeDictionary").Values.ToArray();
		}

		private static string GetStoryId(Type storyType)
		{
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_000c: Expected O, but got Unknown
			StoryModel obj = (StoryModel)Activator.CreateInstance(storyType);
			string text = (storyType.GetProperty("Id", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(obj) as string) ?? throw new InvalidOperationException("Story type '" + storyType.FullName + "' does not expose a string Id property.");
			if (!string.IsNullOrWhiteSpace(text))
			{
				return text.Trim();
			}
			throw new InvalidOperationException("Story type '" + storyType.FullName + "' returned an empty Id.");
		}

		private static TField GetStaticField<TField>(Type ownerType, string fieldName) where TField : class
		{
			return (TField)((ownerType.GetField(fieldName, BindingFlags.Static | BindingFlags.NonPublic) ?? throw new MissingFieldException(ownerType.FullName, fieldName)).GetValue(null) ?? throw new InvalidOperationException($"Static field '{ownerType.FullName}.{fieldName}' is null."));
		}

		private static void SetStaticField(Type ownerType, string fieldName, object? value)
		{
			(ownerType.GetField(fieldName, BindingFlags.Static | BindingFlags.NonPublic) ?? throw new MissingFieldException(ownerType.FullName, fieldName)).SetValue(null, value);
		}

		private static void RefreshAllEpochIdsSnapshotLocked()
		{
			List<string> list = GetStaticField<Dictionary<string, Type>>(typeof(EpochModel), "_epochTypeDictionary").Keys.OrderBy<string, string>((string id) => id, StringComparer.Ordinal).ToList();
			FieldInfo fieldInfo = typeof(EpochModel).GetField("_allEpochIds", BindingFlags.Static | BindingFlags.NonPublic) ?? throw new MissingFieldException(typeof(EpochModel).FullName, "_allEpochIds");
			fieldInfo.SetValue(null, (fieldInfo.FieldType == typeof(List<string>)) ? ((object?)list) : ((object?)list.ToArray()));
			typeof(EpochModel).GetField("_epochIdsHashSet", BindingFlags.Static | BindingFlags.NonPublic)?.SetValue(null, null);
		}

		private static bool AddEpochTypeToAllEpochsLocked(Type epochType)
		{
			List<Type> staticField = GetStaticField<List<Type>>(typeof(EpochModel), "_allEpochs");
			if (staticField.Contains(epochType))
			{
				return false;
			}
			staticField.Add(epochType);
			return true;
		}

		private static void RemoveEpochTypeFromAllEpochsLocked(Type epochType)
		{
			GetStaticField<List<Type>>(typeof(EpochModel), "_allEpochs").Remove(epochType);
		}
	}
}
namespace STS2RitsuLib.Timeline.Scaffolding
{
	/// <summary>
	///     <para xml:lang="en">
	///         Provides an <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochModel" /> base that unlocks cards declared by CLR type and optionally expands
	///         the timeline.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供按 CLR 类型声明并解锁卡牌的 <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochModel" /> 基类，也可选择扩展时间线。
	///     </para>
	/// </summary>
	public abstract class CardUnlockEpochTemplate : ModEpochTemplate
	{
		/// <summary>
		///     <para xml:lang="en">Gets the <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> instances resolved from <see cref="P:STS2RitsuLib.Timeline.Scaffolding.CardUnlockEpochTemplate.CardTypes" />.</para>
		///     <para xml:lang="zh-CN">获取从 <see cref="P:STS2RitsuLib.Timeline.Scaffolding.CardUnlockEpochTemplate.CardTypes" /> 解析出的 <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> 实例。</para>
		/// </summary>
		public IReadOnlyList<CardModel> Cards
		{
			get
			{
				List<CardModel> list = new List<CardModel>();
				list.AddRange(CardTypes.Select((Type type) => ModelDb.GetById<CardModel>(ModelDb.GetId(type))));
				return RequireUnlockPresentationItems(new <>z__ReadOnlyList<CardModel>(list), "CardTypes");
			}
		}

		/// <inheritdoc />
		public override string UnlockText => ((EpochModel)this).CreateCardUnlockText(Cards.ToList());

		/// <summary>
		///     <para xml:lang="en">Gets the CLR types of cards to unlock; each must be registered in <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" />.</para>
		///     <para xml:lang="zh-CN">获取要解锁的卡牌 CLR 类型；每种类型都必须已注册到 <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" />。</para>
		/// </summary>
		protected abstract IEnumerable<Type> CardTypes { get; }

		/// <summary>
		///     <para xml:lang="en">Gets additional epoch types appended when this epoch unlocks.</para>
		///     <para xml:lang="zh-CN">获取此纪元解锁时追加的其他纪元类型。</para>
		/// </summary>
		protected virtual IEnumerable<Type> ExpansionEpochTypes => Array.Empty<Type>();

		/// <summary>
		///     <para xml:lang="en">
		///         Enumerates <see cref="P:STS2RitsuLib.Timeline.Scaffolding.CardUnlockEpochTemplate.CardTypes" /> for batch
		///         <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.RequireEpoch(System.Type,System.String)" /> registration by a content pack.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         枚举 <see cref="P:STS2RitsuLib.Timeline.Scaffolding.CardUnlockEpochTemplate.CardTypes" />，供内容包批量调用
		///         <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.RequireEpoch(System.Type,System.String)" /> 注册。
		///     </para>
		/// </summary>
		public IEnumerable<Type> EnumerateUnlockCardTypes()
		{
			List<Type> list = new List<Type>();
			list.AddRange(CardTypes);
			return new <>z__ReadOnlyList<Type>(list);
		}

		/// <inheritdoc />
		public override EpochModel[] GetTimelineExpansion()
		{
			return ExpansionEpochTypes.Select((Type type) => EpochModel.Get(EpochModel.GetId(type))).ToArray();
		}

		/// <inheritdoc />
		public override void QueueUnlocks()
		{
			IReadOnlyList<CardModel> cards = Cards;
			NTimelineScreen.Instance.QueueCardUnlock(cards);
			EpochModel[] timelineExpansion = ((EpochModel)this).GetTimelineExpansion();
			if (timelineExpansion.Length != 0)
			{
				EpochModel.QueueTimelineExpansion(timelineExpansion);
			}
		}
	}
