	/// <summary>
	///     <para xml:lang="en">
	///         Provides a mod <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochModel" /> base with optional timeline portrait overrides. The unlock-epoch
	///         templates in this namespace inherit from it.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供可选时间线肖像覆盖的模组 <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochModel" /> 基类。此命名空间中的解锁纪元模板均继承此类。
	///     </para>
	/// </summary>
	public abstract class ModEpochTemplate : EpochModel, IModEpochAssetOverrides
	{
		/// <inheritdoc />
		public sealed override EpochEra Era
		{
			get
			{
				//IL_0006: Unknown result type (might be due to invalid IL or missing references)
				return ModTimelineLayoutRegistry.ResolveEra(((object)this).GetType());
			}
		}

		/// <inheritdoc />
		public sealed override int EraPosition => ModTimelineLayoutRegistry.ResolveEraPosition(((object)this).GetType());

		/// <inheritdoc />
		public virtual EpochAssetProfile AssetProfile => EpochAssetProfile.Empty;

		/// <inheritdoc />
		public virtual string? CustomPackedPortraitPath => AssetProfile.PackedPortraitPath;

		/// <inheritdoc />
		public virtual string? CustomBigPortraitPath => AssetProfile.BigPortraitPath;

		/// <summary>
		///     <para xml:lang="en">
		///         Validates content passed to the base game's unlock-text formatter, which reads the first three items.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         验证传给原版解锁文本格式化方法的内容；该方法会读取前三项。
		///     </para>
		/// </summary>
		protected IReadOnlyList<TModel> RequireUnlockPresentationItems<TModel>(IReadOnlyList<TModel> items, string sourceName)
		{
			ArgumentNullException.ThrowIfNull(items, "items");
			ArgumentException.ThrowIfNullOrWhiteSpace(sourceName, "sourceName");
			if (items.Count < 3)
			{
				throw new InvalidOperationException($"Epoch '{((EpochModel)this).Id}' requires at least three {typeof(TModel).Name} entries from {sourceName}; " + "the built-in timeline unlock text reads the first three items.");
			}
			return items;
		}
	}
