	///     <para xml:lang="zh-CN">
	///         提供按 CLR 类型声明并解锁遗物的 <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochModel" /> 基类，也可选择扩展时间线。
	///     </para>
	/// </summary>
	public abstract class RelicUnlockEpochTemplate : ModEpochTemplate
	{
		/// <summary>
		///     <para xml:lang="en">Gets the <see cref="T:MegaCrit.Sts2.Core.Models.RelicModel" /> instances resolved from <see cref="P:STS2RitsuLib.Timeline.Scaffolding.RelicUnlockEpochTemplate.RelicTypes" />.</para>
		///     <para xml:lang="zh-CN">获取从 <see cref="P:STS2RitsuLib.Timeline.Scaffolding.RelicUnlockEpochTemplate.RelicTypes" /> 解析出的 <see cref="T:MegaCrit.Sts2.Core.Models.RelicModel" /> 实例。</para>
		/// </summary>
		public IReadOnlyList<RelicModel> Relics
		{
			get
			{
				List<RelicModel> list = new List<RelicModel>();
				list.AddRange(RelicTypes.Select((Type type) => ModelDb.GetById<RelicModel>(ModelDb.GetId(type))));
				return RequireUnlockPresentationItems(new <>z__ReadOnlyList<RelicModel>(list), "RelicTypes");
			}
		}

		/// <inheritdoc />
		public override string UnlockText => ((EpochModel)this).CreateRelicUnlockText(Relics.ToList());

		/// <summary>
		///     <para xml:lang="en">Gets the CLR types of relics to unlock; each must be registered in <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" />.</para>
		///     <para xml:lang="zh-CN">获取要解锁的遗物 CLR 类型；每种类型都必须已注册到 <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" />。</para>
		/// </summary>
		protected abstract IEnumerable<Type> RelicTypes { get; }

		/// <summary>
		///     <para xml:lang="en">Gets additional epoch types appended when this epoch unlocks.</para>
		///     <para xml:lang="zh-CN">获取此纪元解锁时追加的其他纪元类型。</para>
		/// </summary>
		protected virtual IEnumerable<Type> ExpansionEpochTypes => Array.Empty<Type>();

		/// <summary>
		///     <para xml:lang="en">
		///         Enumerates <see cref="P:STS2RitsuLib.Timeline.Scaffolding.RelicUnlockEpochTemplate.RelicTypes" /> for batch
		///         <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.RequireEpoch(System.Type,System.String)" /> registration by a content pack.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         枚举 <see cref="P:STS2RitsuLib.Timeline.Scaffolding.RelicUnlockEpochTemplate.RelicTypes" />，供内容包批量调用
		///         <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.RequireEpoch(System.Type,System.String)" /> 注册。
		///     </para>
		/// </summary>
		public IEnumerable<Type> EnumerateUnlockRelicTypes()
		{
			List<Type> list = new List<Type>();
			list.AddRange(RelicTypes);
			return new <>z__ReadOnlyList<Type>(list);
		}

		/// <inheritdoc />
		public override EpochModel[] GetTimelineExpansion()
		{
			return ExpansionEpochTypes.Select((Type type) => EpochModel.Get(EpochModel.GetId(type))).ToArray();
		}

		/// <inheritdoc />
		public override void QueueUnlocks()
		{
			IReadOnlyList<RelicModel> relics = Relics;
			NTimelineScreen.Instance.QueueRelicUnlock(relics.ToList());
			EpochModel[] timelineExpansion = ((EpochModel)this).GetTimelineExpansion();
			if (timelineExpansion.Length != 0)
			{
				EpochModel.QueueTimelineExpansion(timelineExpansion);
			}
		}
	}
}
namespace STS2RitsuLib.Timeline.Patches
{
	/// <summary>
	///     <para xml:lang="en">
	///         Limits mod timeline co-expansion to <see cref="M:MegaCrit.Sts2.Core.Timeline.Epochs.NeowEpoch.QueueUnlocks" />, preventing unrelated
	///         <see cref="M:MegaCrit.Sts2.Core.Timeline.EpochModel.QueueTimelineExpansion(MegaCrit.Sts2.Core.Timeline.EpochModel[])" /> calls from unlocking or
	///         animating every <see cref="T:STS2RitsuLib.Timeline.Scaffolding.ModEpochTemplate" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将模组时间线的共同扩展限制在 <see cref="M:MegaCrit.Sts2.Core.Timeline.Epochs.NeowEpoch.QueueUnlocks" /> 流程内，避免无关的
	///         <see cref="M:MegaCrit.Sts2.Core.Timeline.EpochModel.QueueTimelineExpansion(MegaCrit.Sts2.Core.Timeline.EpochModel[])" /> 调用解锁或播放所有
	///         <see cref="T:STS2RitsuLib.Timeline.Scaffolding.ModEpochTemplate" /> 的动画。
	///     </para>
	/// </summary>
	internal sealed class NeowEpochQueueUnlocksCoExpansionScopePatch : IPatchMethod
	{
		public static string PatchId => "neow_epoch_queue_unlocks_co_expansion_scope";

		public static string Description => "Track NeowEpoch.QueueUnlocks so QueueTimelineExpansion postfix only co-unlocks mod slots in that flow";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NeowEpoch), "QueueUnlocks", Type.EmptyTypes)
			};
		}

		public static void Prefix()
		{
			ModTimelineNeowCoExpansion.EnterNeowQueueUnlocks();
		}

		public static void Finalizer(Exception? __exception)
		{
			ModTimelineNeowCoExpansion.ExitNeowQueueUnlocks();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Merges eligible mod epoch slots into <c>NTimelineScreen.AddEpochSlots</c>. On a nonanimated screen open,
	///         merging begins only after Neow's primary expansion has started. During an animated expansion, merging
	///         occurs only for the batch queued by <see cref="M:MegaCrit.Sts2.Core.Timeline.Epochs.NeowEpoch.QueueUnlocks" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将符合条件的模组纪元槽位合并到 <c>NTimelineScreen.AddEpochSlots</c>。非动画方式打开界面时，仅在涅奥的
	///         主扩展开始后合并；播放扩展动画时，则只合并由 <see cref="M:MegaCrit.Sts2.Core.Timeline.Epochs.NeowEpoch.QueueUnlocks" /> 入队的批次。
	///     </para>
	/// </summary>
	internal sealed class NTimelineScreenAddEpochSlotsMergeModTemplatesPatch : IPatchMethod
	{
		public static string PatchId => "n_timeline_screen_add_epoch_slots_merge_mod_templates";

		public static string Description => "Merge obtained, Neow-unlocked root, or parent-visible ModEpochTemplate slots after Neow expansion";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NTimelineScreen), "AddEpochSlots", new Type[2]
				{
					typeof(List<EpochSlotData>),
					typeof(bool)
				})
			};
		}

		public static void Prefix(List<EpochSlotData> slotsToAdd, bool isAnimated)
		{
			SaveManager instance = SaveManager.Instance;
			ProgressState progress = ((instance != null) ? instance.Progress : null);
			if (!isAnimated)
			{
				if (ModTimelineNeowCoExpansion.HasVanillaNeowTimelineExpansionStarted(progress))
				{
					ModTimelineNeowCoExpansion.MergeModEpochTemplateSlotsInto(slotsToAdd, progress);
				}
			}
			else if ((slotsToAdd.Count != 1 || !(slotsToAdd[0].Model.Id == EpochModel.GetId<NeowEpoch>())) && ModTimelineNeowCoExpansion.IsNeowPrimaryTimelineExpansionSlots(slotsToAdd) && ModTimelineNeowCoExpansion.TryConsumePendingNeowAnimatedSlotMerge())
			{
				ModTimelineNeowCoExpansion.MergeModEpochTemplateSlotsInto(slotsToAdd, progress);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Applies timeline-axis icon policies, hiding a custom era's icon by default when no texture is available.
	///     </para>
	///     <para xml:lang="zh-CN">应用时间线坐标轴图标策略；自定义时代没有可用纹理时，默认隐藏其图标。</para>
	/// </summary>
	internal sealed class NTimelineScreenGetEraIconPolicyPatch : IPatchMethod
	{
		public static string PatchId => "n_timeline_screen_get_era_icon_policy";

		public static string Description => "Apply configurable era-axis icon policy and default-hide missing custom era icons";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NTimelineScreen), "GetEraIcon", new Type[1] { typeof(EpochEra) })
			};
		}

		public static bool Prefix(EpochEra era, ref (Texture2D Texture, string Name) __result)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0069: Unknown result type (might be due to invalid IL or missing references)
			//IL_0075: Unknown result type (might be due to invalid IL or missing references)
			//IL_0026: Unknown result type (might be due to invalid IL or missing references)
			//IL_0057: Unknown result type (might be due to invalid IL or missing references)
			if (ModTimelineEraIconRegistry.TryResolve(era, out bool? enabled, out string texturePath))
			{
				if (enabled == false)
				{
					__result = (Texture: null, Name: ResolveEraLocKey(era));
					return false;
				}
				if (!string.IsNullOrWhiteSpace(texturePath) && ResourceLoader.Exists(texturePath, ""))
				{
					__result = (Texture: ResourceLoader.Load<Texture2D>(texturePath, (string)null, (CacheMode)1), Name: ResolveEraLocKey(era));
					return false;
				}
			}
			if (HasVanillaEraIconResource(era))
			{
				return true;
			}
			__result = (Texture: null, Name: ResolveEraLocKey(era));
			return false;
		}

		private static bool HasVanillaEraIconResource(EpochEra era)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0008: Unknown result type (might be due to invalid IL or missing references)
			if (Enum.IsDefined<EpochEra>(era))
			{
				return ResourceLoader.Exists(GetEraTexturePath(era), "");
			}
			return false;
		}

		private unsafe static string ResolveEraLocKey(EpochEra era)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_001b: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Invalid comparison between Unknown and I4
			//IL_0027: Unknown result type (might be due to invalid IL or missing references)
			if (Enum.IsDefined<EpochEra>(era))
			{
				return StringHelper.Slugify(((object)(*(EpochEra*)(&era))/*cast due to constrained. prefix*/).ToString());
			}
			return StringHelper.Slugify(((object)(EpochEra)(((int)era < 0) ? (-20000) : 0)/*cast due to constrained. prefix*/).ToString());
		}

		private static string GetEraTexturePath(EpochEra era)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0002: Expected I4, but got Unknown
			int num = (int)era;
			if (num >= 0)
			{
				return $"res://images/atlases/era_atlas.sprites/era_{num}.tres";
			}
			return $"res://images/atlases/era_atlas.sprites/era_minus_{Math.Abs(num)}.tres";
		}
	}
	/// <summary>
