	/// <summary>
	///     <para xml:lang="en">
	///         Sorts timeline expansion slots by <see cref="P:MegaCrit.Sts2.Core.Timeline.EpochSlotData.Era" /> and then
	///         <see cref="P:MegaCrit.Sts2.Core.Timeline.EpochSlotData.EraPosition" />, avoiding collisions between equal positions in different eras.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         先按 <see cref="P:MegaCrit.Sts2.Core.Timeline.EpochSlotData.Era" />、再按 <see cref="P:MegaCrit.Sts2.Core.Timeline.EpochSlotData.EraPosition" /> 对时间线扩展槽位排序，
	///         避免不同时代中相同位置发生排序冲突。
	///     </para>
	/// </summary>
	internal class NUnlockTimelineScreenExpansionSlotSortPatch : IPatchMethod
	{
		public static string PatchId => "n_unlock_timeline_screen_expansion_slot_sort";

		public static string Description => "Sort timeline expansion slots by Era then EraPosition for mod-compatible column ordering";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NUnlockTimelineScreen), "SetUnlocks", new Type[1] { typeof(List<EpochSlotData>) })
			};
		}

		public static void Postfix(NUnlockTimelineScreen __instance, List<EpochSlotData> eras)
		{
			ArgumentNullException.ThrowIfNull(eras, "eras");
			FieldInfo fieldInfo = AccessTools.Field(typeof(NUnlockTimelineScreen), "_erasToUnlock");
			if (!(fieldInfo == null))
			{
				List<EpochSlotData> value = eras.OrderBy(delegate(EpochSlotData a)
				{
					//IL_0001: Unknown result type (might be due to invalid IL or missing references)
					return a.Era;
				}).ThenBy((EpochSlotData a) => a.EraPosition).ToList();
				fieldInfo.SetValue(__instance, value);
			}
		}
	}
