namespace STS2RitsuLib.Telemetry
{
	/// <summary>
	///     <para xml:lang="en">
	///         Represents a disabled telemetry destination for an applicant whose backend is not configured.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         表示遥测后端尚未配置时为申请方使用的禁用遥测目标。
	///     </para>
	/// </summary>
	public sealed class DisabledTelemetryAdapter : ITelemetryAdapter
	{
		/// <inheritdoc />
		public string AdapterId => "disabled";

		/// <inheritdoc />
		public string EndpointDescription { get; }

		/// <summary>
		///     <para xml:lang="en">Creates a disabled adapter with a user-visible reason.</para>
		///     <para xml:lang="zh-CN">创建禁用的适配器，并提供向用户显示的原因。</para>
		/// </summary>
		public DisabledTelemetryAdapter(string reason)
		{
			EndpointDescription = (string.IsNullOrWhiteSpace(reason) ? "Telemetry backend is not configured." : reason);
		}

		/// <inheritdoc />
		public ValueTask<TelemetrySendResult> SendAsync(TelemetryApplicant applicant, IReadOnlyList<TelemetryEnvelope> events, CancellationToken cancellationToken = default(CancellationToken))
		{
			return ValueTask.FromResult(TelemetrySendResult.Fail(EndpointDescription));
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Sends telemetry batches as JSON over HTTP to a self-hosted mod endpoint.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过 HTTP 将遥测批次以 JSON 格式发送到模组自行托管的端点。
	///     </para>
	/// </summary>
	public sealed class HttpJsonTelemetryAdapter : ITelemetryAdapter
	{
		private static readonly HttpClient Client = new HttpClient
		{
			Timeout = TimeSpan.FromSeconds(60L)
		};

		private readonly IReadOnlyDictionary<string, string> _headers;

		/// <summary>
		///     <para xml:lang="en">Gets the absolute endpoint URI that receives telemetry batches.</para>
		///     <para xml:lang="zh-CN">获取接收遥测批次的绝对端点 URI。</para>
		/// </summary>
		public Uri Endpoint { get; }

		/// <inheritdoc />
		public string AdapterId => "http_json";

		/// <inheritdoc />
		public string EndpointDescription => Endpoint.ToString();

		/// <summary>
		///     <para xml:lang="en">
		///         Creates an adapter that sends batches to <paramref name="endpoint" /> with HTTP POST requests.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建通过 HTTP POST 请求向 <paramref name="endpoint" /> 发送批次的适配器。
		///     </para>
		/// </summary>
		public HttpJsonTelemetryAdapter(string endpoint, IReadOnlyDictionary<string, string>? headers = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(endpoint, "endpoint");
			Endpoint = new Uri(endpoint, UriKind.Absolute);
			string scheme = Endpoint.Scheme;
			if ((!(scheme == "http") && !(scheme == "https")) || 1 == 0)
			{
				throw new ArgumentException("The telemetry endpoint must use HTTP or HTTPS.", "endpoint");
			}
			_headers = ((headers == null) ? new Dictionary<string, string>() : new Dictionary<string, string>(headers, StringComparer.OrdinalIgnoreCase));
		}

		/// <inheritdoc />
		public async ValueTask<TelemetrySendResult> SendAsync(TelemetryApplicant applicant, IReadOnlyList<TelemetryEnvelope> events, CancellationToken cancellationToken = default(CancellationToken))
		{
			string content = JsonSerializer.Serialize(new
			{
				schema = "ritsulib.telemetry.batch.v1",
				applicant_id = applicant.ApplicantId,
				events = events
			}, TelemetryJson.Options);
			try
			{
				using HttpRequestMessage request = new HttpRequestMessage(HttpMethod.Post, Endpoint);
				request.Content = new StringContent(content, Encoding.UTF8, "application/json");
				foreach (KeyValuePair<string, string> header in _headers)
				{
					request.Headers.TryAddWithoutValidation(header.Key, header.Value);
				}
				using HttpResponseMessage response = await Client.SendAsync(request, cancellationToken);
				if (response.IsSuccessStatusCode)
				{
					return TelemetrySendResult.Ok();
				}
				string value = await response.Content.ReadAsStringAsync(cancellationToken);
				return TelemetrySendResult.Fail(string.IsNullOrWhiteSpace(value) ? $"{(int)response.StatusCode} {response.ReasonPhrase}" : $"{(int)response.StatusCode} {response.ReasonPhrase}: {value}");
			}
			catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
			{
				return TelemetrySendResult.Fail($"Timed out posting telemetry to {Endpoint}.");
			}
			catch (OperationCanceledException)
			{
				throw;
			}
			catch (Exception ex3)
			{
				return TelemetrySendResult.Fail(ex3.Message);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Sends one applicant's authorized telemetry events to that applicant's fixed backend.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将一个申请方已获授权的遥测事件发送到该申请方的固定后端。
	///     </para>
	/// </summary>
	public interface ITelemetryAdapter
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets the stable adapter ID, such as <c>http_json</c> or <c>posthog</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取稳定的适配器 ID，例如 <c>http_json</c> 或 <c>posthog</c>。
		///     </para>
		/// </summary>
		string AdapterId { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the human-readable endpoint description shown in settings.</para>
		///     <para xml:lang="zh-CN">获取设置界面中显示的端点说明。</para>
		/// </summary>
		string EndpointDescription { get; }

		/// <summary>
		///     <para xml:lang="en">Sends one event batch for <paramref name="applicant" />.</para>
		///     <para xml:lang="zh-CN">为 <paramref name="applicant" /> 发送一个事件批次。</para>
		/// </summary>
		ValueTask<TelemetrySendResult> SendAsync(TelemetryApplicant applicant, IReadOnlyList<TelemetryEnvelope> events, CancellationToken cancellationToken = default(CancellationToken));
	}
	/// <summary>
	///     <para xml:lang="en">Represents the result of a telemetry adapter's send attempt.</para>
	///     <para xml:lang="zh-CN">表示遥测适配器一次发送尝试的结果。</para>
	/// </summary>
	public readonly record struct TelemetrySendResult
	{
		/// <summary>
		///     <para xml:lang="en">Gets whether the adapter accepted the batch.</para>
		///     <para xml:lang="zh-CN">获取适配器是否接受了该批次。</para>
		/// </summary>
		public bool Success { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the error message when <see cref="P:STS2RitsuLib.Telemetry.TelemetrySendResult.Success" /> is <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 <see cref="P:STS2RitsuLib.Telemetry.TelemetrySendResult.Success" /> 为 <see langword="false" /> 时的错误信息。
		///     </para>
		/// </summary>
		public string? ErrorMessage { get; }

		/// <summary>
		///     <para xml:lang="en">Initializes a send result.</para>
		///     <para xml:lang="zh-CN">初始化发送结果。</para>
		/// </summary>
		public TelemetrySendResult(bool success, string? errorMessage = null)
		{
			Success = success;
			ErrorMessage = errorMessage;
		}

		/// <summary>
		///     <para xml:lang="en">Creates a successful send result.</para>
		///     <para xml:lang="zh-CN">创建表示发送成功的结果。</para>
		/// </summary>
		public static TelemetrySendResult Ok()
		{
			return new TelemetrySendResult(success: true);
		}

		/// <summary>
		///     <para xml:lang="en">Creates a failed send result with an error message.</para>
		///     <para xml:lang="zh-CN">创建带错误信息的发送失败结果。</para>
		/// </summary>
		public static TelemetrySendResult Fail(string errorMessage)
		{
			return new TelemetrySendResult(success: false, errorMessage);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Sends telemetry through the PostHog batch API.</para>
	///     <para xml:lang="zh-CN">通过 PostHog 批量 API 发送遥测数据。</para>
	/// </summary>
	public sealed class PostHogTelemetryAdapter : ITelemetryAdapter
	{
		private static readonly HttpClient Client = new HttpClient
		{
			Timeout = TimeSpan.FromSeconds(60L)
		};

		private readonly Uri _batchEndpoint;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the PostHog host root, such as <c>https://us.i.posthog.com</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 PostHog 主机根地址，例如 <c>https://us.i.posthog.com</c>。
		///     </para>
		/// </summary>
		public Uri Host { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the PostHog project API key.</para>
		///     <para xml:lang="zh-CN">获取 PostHog 项目 API 密钥。</para>
		/// </summary>
		public string ProjectApiKey { get; }

		/// <inheritdoc />
		public string AdapterId => "posthog";

		/// <inheritdoc />
		public string EndpointDescription => _batchEndpoint.ToString();

		/// <summary>
		///     <para xml:lang="en">Creates a PostHog adapter for a fixed host and project API key.</para>
		///     <para xml:lang="zh-CN">使用固定主机地址和项目 API 密钥创建 PostHog 适配器。</para>
		/// </summary>
		public PostHogTelemetryAdapter(string host, string projectApiKey)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(host, "host");
			Host = new Uri(host.TrimEnd('/'), UriKind.Absolute);
			string scheme = Host.Scheme;
			if ((!(scheme == "http") && !(scheme == "https")) || 1 == 0)
			{
				throw new ArgumentException("The PostHog host must use HTTP or HTTPS.", "host");
			}
			_batchEndpoint = new Uri(Host, "/batch/");
			ArgumentException.ThrowIfNullOrWhiteSpace(projectApiKey, "projectApiKey");
			ProjectApiKey = projectApiKey;
		}

		/// <inheritdoc />
		public async ValueTask<TelemetrySendResult> SendAsync(TelemetryApplicant applicant, IReadOnlyList<TelemetryEnvelope> events, CancellationToken cancellationToken = default(CancellationToken))
		{
			var batch = events.Select((TelemetryEnvelope evt) => new
			{
				@event = evt.EventName,
				distinct_id = evt.Properties.GetValueOrDefault("anonymous_install_id"),
				properties = BuildProperties(evt),
				timestamp = evt.TimestampUtc
			}).ToArray();
			string content = JsonSerializer.Serialize(new
			{
				api_key = ProjectApiKey,
				batch = batch
			}, TelemetryJson.Options);
			try
			{
				using HttpResponseMessage httpResponseMessage = await Client.PostAsync(_batchEndpoint, new StringContent(content, Encoding.UTF8, "application/json"), cancellationToken);
				return httpResponseMessage.IsSuccessStatusCode ? TelemetrySendResult.Ok() : TelemetrySendResult.Fail($"{(int)httpResponseMessage.StatusCode} {httpResponseMessage.ReasonPhrase}");
			}
			catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
			{
				return TelemetrySendResult.Fail($"Timed out posting telemetry to {Host}.");
			}
			catch (OperationCanceledException)
			{
				throw;
			}
			catch (Exception ex3)
			{
				return TelemetrySendResult.Fail(ex3.Message);
			}
		}

		private static Dictionary<string, object?> BuildProperties(TelemetryEnvelope evt)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>(evt.Properties, StringComparer.OrdinalIgnoreCase)
			{
				["schema"] = evt.Schema,
				["applicant_id"] = evt.ApplicantId,
				["request_id"] = evt.RequestId,
				["category"] = evt.Category.ToString()
			};
			if (evt.Payload != null)
			{
				dictionary["payload"] = evt.Payload;
			}
			return dictionary;
		}
	}
	internal sealed class TelemetryConsentDocument
	{
		[JsonPropertyName("schema_version")]
		public int SchemaVersion { get; set; } = 1;

		[JsonPropertyName("applicants")]
		public Dictionary<string, TelemetryApplicantConsent> Applicants { get; set; } = new Dictionary<string, TelemetryApplicantConsent>(StringComparer.OrdinalIgnoreCase);
	}
	internal sealed class TelemetryApplicantConsent
	{
		[JsonPropertyName("consent")]
		public TelemetryConsentState Consent { get; set; }

		[JsonPropertyName("granted_requests")]
		public HashSet<string> GrantedRequests { get; set; } = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

		[JsonPropertyName("shared_contribution_sources")]
		public Dictionary<string, HashSet<string>> SharedContributionSources { get; set; } = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
	}
	internal static class TelemetryConsentStore
	{
		private static readonly Lock Sync = new Lock();

		private static TelemetryConsentDocument? _document;

		internal static TelemetryConsentDocument Snapshot()
		{
			using (Sync.EnterScope())
			{
				EnsureLoaded();
				return Normalize(_document);
			}
		}

		internal static TelemetryApplicantConsent GetApplicantConsent(string applicantId)
		{
			using (Sync.EnterScope())
			{
				EnsureLoaded();
				return CloneConsent(GetOrCreate(applicantId));
			}
		}

		internal static bool IsRequestGranted(TelemetryApplicant applicant, TelemetryRequest request)
		{
			using (Sync.EnterScope())
			{
				EnsureLoaded();
				TelemetryApplicantConsent orCreate = GetOrCreate(applicant.ApplicantId);
				return orCreate.Consent == TelemetryConsentState.Granted && orCreate.GrantedRequests.Contains(request.RequestId);
			}
		}

		internal static bool IsSharedContributionGranted(string applicantId, string contributorModId, string contributionId)
		{
			using (Sync.EnterScope())
			{
				EnsureLoaded();
				TelemetryApplicantConsent orCreate = GetOrCreate(applicantId);
				HashSet<string> value;
				return orCreate.Consent == TelemetryConsentState.Granted && orCreate.SharedContributionSources.TryGetValue(contributorModId, out value) && value.Contains(contributionId);
			}
		}

		public static void SetApplicantConsent(string applicantId, TelemetryConsentState state, IEnumerable<string>? grantedRequests = null)
		{
			using (Sync.EnterScope())
			{
				EnsureLoaded();
				TelemetryConsentDocument document = Normalize(_document);
				TelemetryApplicantConsent orCreate = GetOrCreate(applicantId);
				orCreate.Consent = state;
				orCreate.GrantedRequests = ((grantedRequests == null) ? new HashSet<string>() : new HashSet<string>(grantedRequests, StringComparer.OrdinalIgnoreCase));
				if (state != TelemetryConsentState.Granted)
				{
					orCreate.SharedContributionSources.Clear();
				}
				try
				{
					Save();
				}
				catch
				{
					_document = document;
					throw;
				}
				RitsuLibFramework.Logger.Info($"[Telemetry] Applicant consent updated: {applicantId} -> {state} ({orCreate.GrantedRequests.Count} granted request(s)).", 1);
			}
			if (state == TelemetryConsentState.Granted)
			{
				TelemetryRuntime.ReplayStartupSnapshotToApplicant(applicantId);
				TelemetryTaskRunner.Forget(TelemetryQueue.FlushApplicantAsync(applicantId), "flush_applicant_after_consent");
			}
		}

		public static void SetSharedContributionConsent(string applicantId, string contributorModId, string contributionId, bool granted)
		{
			using (Sync.EnterScope())
			{
				EnsureLoaded();
				TelemetryConsentDocument document = Normalize(_document);
				TelemetryApplicantConsent orCreate = GetOrCreate(applicantId);
				if (!orCreate.SharedContributionSources.TryGetValue(contributorModId, out HashSet<string> value))
				{
					value = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
					orCreate.SharedContributionSources[contributorModId] = value;
				}
				if (granted)
				{
					value.Add(contributionId);
				}
				else
				{
					value.Remove(contributionId);
				}
				if (value.Count == 0)
				{
					orCreate.SharedContributionSources.Remove(contributorModId);
				}
				try
				{
					Save();
				}
				catch
				{
					_document = document;
					throw;
				}
				RitsuLibFramework.Logger.Info($"[Telemetry] Shared contribution consent updated: applicant={applicantId}, source={contributorModId}/{contributionId}, granted={granted}.", 1);
			}
		}

		private static void EnsureLoaded()
		{
			if (_document == null)
			{
				FileOperations.JsonResult<TelemetryConsentDocument> jsonResult = FileOperations.ReadJson<TelemetryConsentDocument>(TelemetryPaths.ConsentPath, TelemetryJson.Options, "TelemetryConsent");
				_document = Normalize((jsonResult != null && jsonResult.Success && jsonResult.Data != null) ? jsonResult.Data : new TelemetryConsentDocument());
			}
		}

		private static TelemetryApplicantConsent GetOrCreate(string applicantId)
		{
			if (_document.Applicants.TryGetValue(applicantId, out TelemetryApplicantConsent value))
			{
				return value;
			}
			value = new TelemetryApplicantConsent();
			_document.Applicants[applicantId] = value;
			return value;
		}

		private static void Save()
		{
			FileOperations.WriteResult writeResult = FileOperations.WriteJson(TelemetryPaths.ConsentPath, _document, TelemetryJson.Options, "TelemetryConsent");
			if (!writeResult.Success)
			{
				throw new InvalidOperationException("Failed to persist telemetry consent: " + writeResult.ErrorMessage);
			}
		}

		private static TelemetryConsentDocument Normalize(TelemetryConsentDocument document)
		{
			Dictionary<string, TelemetryApplicantConsent> dictionary = new Dictionary<string, TelemetryApplicantConsent>(StringComparer.OrdinalIgnoreCase);
			foreach (KeyValuePair<string, TelemetryApplicantConsent> item in document.Applicants ?? new Dictionary<string, TelemetryApplicantConsent>())
			{
				item.Deconstruct(out var key, out var value);
				string text = key;
				TelemetryApplicantConsent telemetryApplicantConsent = value;
				if (string.IsNullOrWhiteSpace(text) || telemetryApplicantConsent == null)
				{
					continue;
				}
				Dictionary<string, HashSet<string>> dictionary2 = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
				foreach (KeyValuePair<string, HashSet<string>> item2 in telemetryApplicantConsent.SharedContributionSources ?? new Dictionary<string, HashSet<string>>())
				{
					item2.Deconstruct(out key, out var value2);
					string text2 = key;
					HashSet<string> hashSet = value2;
					if (!string.IsNullOrWhiteSpace(text2))
					{
						dictionary2[text2] = new HashSet<string>((hashSet ?? new HashSet<string>()).Where((string id) => !string.IsNullOrWhiteSpace(id)), StringComparer.OrdinalIgnoreCase);
					}
				}
				dictionary[text] = new TelemetryApplicantConsent
				{
					Consent = (Enum.IsDefined(telemetryApplicantConsent.Consent) ? telemetryApplicantConsent.Consent : TelemetryConsentState.Unknown),
					GrantedRequests = new HashSet<string>((telemetryApplicantConsent.GrantedRequests ?? new HashSet<string>()).Where((string id) => !string.IsNullOrWhiteSpace(id)), StringComparer.OrdinalIgnoreCase),
					SharedContributionSources = dictionary2
				};
			}
			return new TelemetryConsentDocument
			{
				SchemaVersion = 1,
				Applicants = dictionary
			};
		}

		private static TelemetryApplicantConsent CloneConsent(TelemetryApplicantConsent consent)
		{
			Dictionary<string, HashSet<string>> dictionary = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
			foreach (var (key, collection) in consent.SharedContributionSources)
			{
				dictionary[key] = new HashSet<string>(collection, StringComparer.OrdinalIgnoreCase);
			}
			return new TelemetryApplicantConsent
			{
				Consent = consent.Consent,
				GrantedRequests = new HashSet<string>(consent.GrantedRequests, StringComparer.OrdinalIgnoreCase),
				SharedContributionSources = dictionary
			};
		}
	}
