		///     </para>
		/// </summary>
		bool IsEnabled(string requestId);

		/// <summary>
		///     <para xml:lang="en">Captures a properties-only event for an authorized request.</para>
		///     <para xml:lang="zh-CN">为已获授权的申请项采集仅包含属性的事件。</para>
		/// </summary>
		void Capture(string eventName, string requestId, IReadOnlyDictionary<string, object?>? properties = null);

		/// <summary>
		///     <para xml:lang="en">
		///         Captures an event with a structured applicant payload for an authorized request.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为已获授权的申请项采集带有结构化申请方负载的事件。
		///     </para>
		/// </summary>
		void CapturePayload(string eventName, string requestId, JsonNode payload, IReadOnlyDictionary<string, object?>? properties = null);

		/// <summary>
		///     <para xml:lang="en">Captures an exception under the <c>diagnostics</c> request.</para>
		///     <para xml:lang="zh-CN">在 <c>diagnostics</c> 申请项下采集异常。</para>
		/// </summary>
		void CaptureException(Exception exception, IReadOnlyDictionary<string, object?>? properties = null);
	}
