	/// <summary>
	///     <para xml:lang="en">Provides public helper entry points for the telemetry framework.</para>
	///     <para xml:lang="zh-CN">提供遥测框架的公共辅助入口。</para>
	/// </summary>
	public static class TelemetryApi
	{
		/// <summary>
		///     <para xml:lang="en">Creates an applicant-scoped telemetry client.</para>
		///     <para xml:lang="zh-CN">创建以申请方为作用域的遥测客户端。</para>
		/// </summary>
		public static ITelemetryClient GetClient(string applicantId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(applicantId, "applicantId");
			return new TelemetryClient(applicantId);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Captures a complete base-game run-history JSON payload for an applicant.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为申请方采集完整的原版游戏历史记录 JSON 负载。
		///     </para>
		/// </summary>
		public static void CaptureVanillaRunHistory(string applicantId, JsonNode runHistory, JsonNode? applicantPayload = null, IReadOnlyDictionary<string, object?>? properties = null)
		{
			RunHistoryTelemetryCollector.CaptureVanillaRunHistory(applicantId, runHistory, applicantPayload, properties);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Declares a telemetry applicant, including who requests data, where it is sent, and which requests are
	///         presented to users.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         声明一个遥测申请方，包括数据申请者、发送目标以及向用户展示的申请项。
	///     </para>
	/// </summary>
	public sealed class TelemetryApplicant
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets the stable applicant ID, which is usually the owning mod's ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取稳定的申请方 ID，通常与所属模组的 ID 相同。
		///     </para>
		/// </summary>
		public required string ApplicantId { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the ID of the mod that owns this applicant declaration.</para>
		///     <para xml:lang="zh-CN">获取拥有此申请方声明的模组 ID。</para>
		/// </summary>
		public required string OwnerModId { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the human-readable name shown in the telemetry settings UI.</para>
		///     <para xml:lang="zh-CN">获取遥测设置界面中显示的可读名称。</para>
		/// </summary>
		public required string DisplayName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets an optional localized display name for the consent prompt and settings UI.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取用于授权提示和设置界面的可选本地化显示名称。
		///     </para>
		/// </summary>
		public ModSettingsText? DisplayNameText { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the fixed adapter and endpoint used for this applicant.</para>
		///     <para xml:lang="zh-CN">获取此申请方使用的固定适配器和端点。</para>
		/// </summary>
		public required ITelemetryAdapter Adapter { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the data requests presented to the user for consent.</para>
		///     <para xml:lang="zh-CN">获取向用户展示以请求授权的数据申请项。</para>
		/// </summary>
		public IReadOnlyList<TelemetryRequest> Requests { get; init; } = Array.Empty<TelemetryRequest>();

		internal string ResolveDisplayName()
		{
			return DisplayNameText?.Resolve() ?? DisplayName;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Describes one telemetry event before RitsuLib builds contributions or queues the event.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         描述一项尚未由 RitsuLib 构建数据贡献或加入队列的遥测事件。
	///     </para>
	/// </summary>
	public readonly record struct TelemetryCaptureContext
	{
		/// <summary>
		///     <para xml:lang="en">Gets the stable telemetry event name.</para>
		///     <para xml:lang="zh-CN">获取稳定的遥测事件名称。</para>
		/// </summary>
		public string EventName { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the request ID whose consent authorizes this event.</para>
		///     <para xml:lang="zh-CN">获取授权此事件的申请项 ID。</para>
		/// </summary>
		public string RequestId { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the event's data category.</para>
		///     <para xml:lang="zh-CN">获取事件的数据类别。</para>
		/// </summary>
		public TelemetryDataCategory Category { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the capture-source identifier. Automatic sources use RitsuLib-defined values; direct client
		///         captures use <c>applicant</c> unless a more specific source is supplied internally.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取采集源标识符。自动采集源使用 RitsuLib 定义的值；客户端直接采集在未由内部提供更具体
		///         来源时使用 <c>applicant</c>。
		///     </para>
		/// </summary>
		public string Source { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets optional source data available before payload generation. Filters must treat it as borrowed,
		///         read-only data and must not retain it after returning.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取负载生成前可用的可选来源数据。筛选器必须将其视为借用的只读数据，且不得在返回后继续
		///         持有它。
		///     </para>
		/// </summary>
		public object? SourceData { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the exception for an exception event, or <see langword="null" /> for another event type.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取异常事件对应的异常；其他事件类型则为 <see langword="null" />。
		///     </para>
		/// </summary>
		public Exception? Exception => SourceData as Exception;

		/// <summary>
		///     <para xml:lang="en">Creates a telemetry capture context.</para>
		///     <para xml:lang="zh-CN">创建遥测采集上下文。</para>
		/// </summary>
		/// <param name="eventName">
		///     <para xml:lang="en">Stable telemetry event name.</para>
		///     <para xml:lang="zh-CN">稳定的遥测事件名称。</para>
		/// </param>
		/// <param name="requestId">
		///     <para xml:lang="en">Request ID whose consent authorizes the event.</para>
		///     <para xml:lang="zh-CN">授权该事件的申请项 ID。</para>
		/// </param>
		/// <param name="category">
		///     <para xml:lang="en">Data category associated with the request.</para>
		///     <para xml:lang="zh-CN">申请项对应的数据类别。</para>
		/// </param>
		/// <param name="source">
		///     <para xml:lang="en">RitsuLib capture-source identifier.</para>
		///     <para xml:lang="zh-CN">RitsuLib 采集源标识符。</para>
		/// </param>
		/// <param name="sourceData">
		///     <para xml:lang="en">
		///         Optional source object available before payload generation, such as an exception or
		///         <see cref="T:STS2RitsuLib.RunEndedEvent" />. The filter must not mutate it or retain it after returning.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         负载生成前可用的可选来源对象，例如异常或 <see cref="T:STS2RitsuLib.RunEndedEvent" />。筛选器不得修改该对象，
		///         也不得在返回后继续持有它。
		///     </para>
		/// </param>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">
		///         <paramref name="eventName" />, <paramref name="requestId" />, or <paramref name="source" /> is
		///         empty, or <paramref name="category" /> is unsupported.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         <paramref name="eventName" />、<paramref name="requestId" /> 或 <paramref name="source" /> 为空，
		///         或 <paramref name="category" /> 不受支持。
		///     </para>
		/// </exception>
		public TelemetryCaptureContext(string eventName, string requestId, TelemetryDataCategory category, string source, object? sourceData = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(eventName, "eventName");
			ArgumentException.ThrowIfNullOrWhiteSpace(requestId, "requestId");
			if (category == TelemetryDataCategory.None || !Enum.IsDefined(category))
			{
				throw new ArgumentOutOfRangeException("category", category, "Unsupported telemetry category.");
			}
			ArgumentException.ThrowIfNullOrWhiteSpace(source, "source");
			EventName = eventName;
			RequestId = requestId;
			Category = category;
			Source = source;
			SourceData = sourceData;
		}
	}
	internal static class TelemetryCaptureFilter
	{
		internal static bool ShouldCapture(TelemetryRequest request, TelemetryCaptureContext context, string applicantId)
		{
			Func<TelemetryCaptureContext, bool> captureFilter = request.CaptureFilter;
			if (captureFilter == null)
			{
				return true;
			}
			try
			{
				return captureFilter(context);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[Telemetry] Capture filter failed for applicant '{applicantId}' and event '{context.EventName}': {ex.Message}", 1);
				return false;
			}
		}
	}
	internal sealed class TelemetryClient(string applicantId) : ITelemetryClient
	{
		public string ApplicantId { get; } = applicantId;

		public bool IsEnabled(string requestId)
		{
			if (TryResolveRequest(requestId, out TelemetryApplicant applicant, out TelemetryRequest request))
			{
				return TelemetryConsentStore.IsRequestGranted(applicant, request);
			}
			return false;
		}

		public void Capture(string eventName, string requestId, IReadOnlyDictionary<string, object?>? properties = null)
		{
			CapturePayload(eventName, requestId, new JsonObject(), properties);
		}

		public void CapturePayload(string eventName, string requestId, JsonNode payload, IReadOnlyDictionary<string, object?>? properties = null)
		{
			TryCapturePayload(eventName, requestId, payload, properties);
		}

		public void CaptureException(Exception exception, IReadOnlyDictionary<string, object?>? properties = null)
		{
			TryCaptureException(exception, properties);
		}

		internal bool TryCapturePayload(string eventName, string requestId, JsonNode payload, IReadOnlyDictionary<string, object?>? properties = null, TelemetryCaptureContext? captureContext = null, bool filterAlreadyApplied = false)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(eventName, "eventName");
			ArgumentException.ThrowIfNullOrWhiteSpace(requestId, "requestId");
			ArgumentNullException.ThrowIfNull(payload, "payload");
			if (!TryResolveRequest(requestId, out TelemetryApplicant applicant, out TelemetryRequest request))
			{
				RitsuLibFramework.Logger.Warn($"[Telemetry] Dropped event '{eventName}' for applicant '{ApplicantId}': request '{requestId}' is not registered.", 1);
				return false;
			}
			if (!TelemetryConsentStore.IsRequestGranted(applicant, request))
			{
				RitsuLibFramework.Logger.Debug($"[Telemetry] Dropped event '{eventName}' for applicant '{ApplicantId}': request '{requestId}' is not authorized.", 1);
				return false;
			}
			TelemetryCaptureContext valueOrDefault = captureContext.GetValueOrDefault();
			if (!captureContext.HasValue)
			{
				valueOrDefault = new TelemetryCaptureContext(eventName, requestId, request.Category, ResolveCaptureSource(properties));
				captureContext = valueOrDefault;
			}
			if (!filterAlreadyApplied && !TelemetryCaptureFilter.ShouldCapture(request, captureContext.Value, applicant.ApplicantId))
			{
				return false;
			}
			try
			{
				TelemetryQueue.Enqueue(TelemetryEnvelopeFactory.Create(applicant, request, eventName, payload, properties));
				TelemetryTaskRunner.Forget(TelemetryQueue.FlushApplicantAsync(applicant.ApplicantId), "flush_applicant");
				return true;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[Telemetry] Capture failed for event '{eventName}' and applicant '{ApplicantId}': {ex.Message}", 1);
				return false;
			}
		}

		internal async Task<bool> TryCapturePayloadAsync(string eventName, string requestId, JsonNode payload, IReadOnlyDictionary<string, object?>? properties = null, TelemetryCaptureContext? captureContext = null, bool filterAlreadyApplied = false, CancellationToken cancellationToken = default(CancellationToken))
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(eventName, "eventName");
			ArgumentException.ThrowIfNullOrWhiteSpace(requestId, "requestId");
			ArgumentNullException.ThrowIfNull(payload, "payload");
			if (!TryResolveRequest(requestId, out TelemetryApplicant applicant, out TelemetryRequest request))
			{
				RitsuLibFramework.Logger.Warn($"[Telemetry] Dropped event '{eventName}' for applicant '{ApplicantId}': request '{requestId}' is not registered.", 1);
				return false;
			}
			if (!TelemetryConsentStore.IsRequestGranted(applicant, request))
			{
				RitsuLibFramework.Logger.Debug($"[Telemetry] Dropped event '{eventName}' for applicant '{ApplicantId}': request '{requestId}' is not authorized.", 1);
				return false;
			}
			captureContext.GetValueOrDefault();
			if (!captureContext.HasValue)
			{
				TelemetryCaptureContext value = new TelemetryCaptureContext(eventName, requestId, request.Category, ResolveCaptureSource(properties));
				captureContext = value;
			}
			if (!filterAlreadyApplied && !TelemetryCaptureFilter.ShouldCapture(request, captureContext.Value, applicant.ApplicantId))
			{
				return false;
			}
			try
			{
				TelemetryEnvelope envelope = null;
				await RitsuMainThread.InvokeAsync(() => envelope = TelemetryEnvelopeFactory.Create(applicant, request, eventName, payload, properties), cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				await TelemetryQueue.EnqueueAsync(envelope, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				await TelemetryQueue.FlushApplicantAsync(applicant.ApplicantId, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				return true;
			}
			catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
			{
				throw;
			}
			catch (Exception ex2)
			{
				RitsuLibFramework.Logger.Warn($"[Telemetry] Async capture failed for event '{eventName}' and applicant '{ApplicantId}': {ex2.Message}", 1);
				return false;
			}
		}

		internal bool TryCaptureException(Exception exception, IReadOnlyDictionary<string, object?>? properties = null)
		{
			ArgumentNullException.ThrowIfNull(exception, "exception");
			if (!TryResolveRequest("diagnostics", out TelemetryApplicant applicant, out TelemetryRequest request) || !TelemetryConsentStore.IsRequestGranted(applicant, request))
			{
				return false;
			}
			TelemetryCaptureContext telemetryCaptureContext = new TelemetryCaptureContext("exception", "diagnostics", request.Category, ResolveCaptureSource(properties), exception);
			if (!TelemetryCaptureFilter.ShouldCapture(request, telemetryCaptureContext, applicant.ApplicantId))
			{
				return false;
			}
			JsonObject payload = DiagnosticsTelemetryCollector.BuildExceptionPayload(exception);
			return TryCapturePayload("exception", "diagnostics", payload, properties, telemetryCaptureContext, filterAlreadyApplied: true);
		}

		private static string ResolveCaptureSource(IReadOnlyDictionary<string, object?>? properties)
		{
			if (properties == null || !properties.TryGetValue("capture_source", out object value) || !(value is string text) || string.IsNullOrWhiteSpace(text))
			{
				return "applicant";
			}
			return text;
		}

		private bool TryResolveRequest(string requestId, out TelemetryApplicant applicant, out TelemetryRequest request)
		{
			request = null;
			if (TelemetryRegistry.TryGetApplicant(ApplicantId, out applicant))
			{
				return TelemetryRegistry.TryGetRequest(applicant, requestId, out request);
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Specifies the user's consent state for one telemetry applicant.</para>
	///     <para xml:lang="zh-CN">指定用户对一个遥测申请方的授权状态。</para>
	/// </summary>
	[JsonConverter(typeof(JsonStringEnumConverter))]
	public enum TelemetryConsentState
	{
		/// <summary>
		///     <para xml:lang="en">The user has not made a decision; telemetry is not sent.</para>
		///     <para xml:lang="zh-CN">用户尚未作出决定；不会发送遥测数据。</para>
		/// </summary>
		Unknown,
		/// <summary>
		///     <para xml:lang="en">The user denied this applicant; telemetry is not sent.</para>
		///     <para xml:lang="zh-CN">用户拒绝了此申请方；不会发送遥测数据。</para>
		/// </summary>
		Denied,
		/// <summary>
		///     <para xml:lang="en">The user granted at least one request for this applicant.</para>
		///     <para xml:lang="zh-CN">用户已授权此申请方的至少一个申请项。</para>
		/// </summary>
		Granted
	}
	/// <summary>
	///     <para xml:lang="en">Specifies broad data categories used by telemetry requests and user consent.</para>
	///     <para xml:lang="zh-CN">指定遥测申请项和用户授权所使用的概括性数据类别。</para>
	/// </summary>
	[Flags]
	[JsonConverter(typeof(JsonStringEnumConverter))]
	public enum TelemetryDataCategory
	{
		/// <summary>
		///     <para xml:lang="en">No data category.</para>
		///     <para xml:lang="zh-CN">不包含任何数据类别。</para>
		/// </summary>
		None = 0,
		/// <summary>
		///     <para xml:lang="en">
		///         Session-start and environment metadata, such as versions, platform, and anonymous installation ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         会话启动和环境元数据，例如版本、平台和匿名安装 ID。
		///     </para>
		/// </summary>
		BasicUsage = 1,
		/// <summary>
		///     <para xml:lang="en">Loaded-mod inventory and mod metadata.</para>
		///     <para xml:lang="zh-CN">已加载模组的清单和模组元数据。</para>
		/// </summary>
		ModInventory = 2,
		/// <summary>
		///     <para xml:lang="en">Base-game run-history payloads preserved without removing fields.</para>
		///     <para xml:lang="zh-CN">保留全部字段的原版游戏历史记录负载。</para>
		/// </summary>
		RunHistory = 4,
		/// <summary>
		///     <para xml:lang="en">Exceptions, stack traces, runtime snapshots, and related diagnostic context.</para>
		///     <para xml:lang="zh-CN">异常、堆栈跟踪、运行时快照及相关诊断上下文。</para>
		/// </summary>
		Diagnostics = 8,
		/// <summary>
		///     <para xml:lang="en">Applicant-defined custom events or payloads.</para>
		///     <para xml:lang="zh-CN">申请方定义的自定义事件或负载。</para>
		/// </summary>
		Custom = 0x10
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Represents a serialized telemetry event after consent, routing, and payload assembly.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         表示经过授权、路由和负载组装后的序列化遥测事件。
	///     </para>
	/// </summary>
	public sealed class TelemetryEnvelope
	{
		/// <summary>
		///     <para xml:lang="en">Gets the envelope schema ID.</para>
		///     <para xml:lang="zh-CN">获取信封格式的架构 ID。</para>
		/// </summary>
		public string Schema { get; init; } = "ritsulib.telemetry.v1";

		/// <summary>
		///     <para xml:lang="en">Gets the applicant that owns this event's destination adapter.</para>
		///     <para xml:lang="zh-CN">获取拥有此事件目标适配器的申请方。</para>
		/// </summary>
		public required string ApplicantId { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the stable event name.</para>
		///     <para xml:lang="zh-CN">获取稳定的事件名称。</para>
		/// </summary>
		public required string EventName { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the ID of the request whose consent authorized this event.</para>
		///     <para xml:lang="zh-CN">获取授权此事件的申请项 ID。</para>
		/// </summary>
		public required string RequestId { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the event's data category.</para>
		///     <para xml:lang="zh-CN">获取此事件的数据类别。</para>
		/// </summary>
		public required TelemetryDataCategory Category { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the event's creation time in UTC.</para>
		///     <para xml:lang="zh-CN">获取此事件的 UTC 创建时间。</para>
		/// </summary>
		public DateTimeOffset TimestampUtc { get; init; } = DateTimeOffset.UtcNow;

		/// <summary>
		///     <para xml:lang="en">Gets flat metadata sent with the event.</para>
		///     <para xml:lang="zh-CN">获取随事件发送的扁平元数据。</para>
		/// </summary>
		public Dictionary<string, object?> Properties { get; init; } = new Dictionary<string, object>();

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the structured payload, usually divided into a base payload, private and shared contributions,
		///         and an applicant payload.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取结构化负载，通常包含基础负载、私有和共享数据贡献以及申请方负载。
		///     </para>
		/// </summary>
		public JsonNode? Payload { get; init; }
	}
	internal static class TelemetryEnvelopeFactory
	{
		internal const string BasePayloadOverrideKey = "__ritsulib_base_payload";

		private static readonly string SessionId = Guid.NewGuid().ToString("N");

		internal static TelemetryEnvelope Create(TelemetryApplicant applicant, TelemetryRequest request, string eventName, JsonNode? applicantPayload, IReadOnlyDictionary<string, object?>? properties)
		{
			Dictionary<string, object> properties2 = ((properties == null) ? new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase) : new Dictionary<string, object>(properties, StringComparer.OrdinalIgnoreCase));
			AddCommonProperties(properties2, applicant);
			JsonObject payload = BuildPayload(applicant, request, eventName, applicantPayload);
			return new TelemetryEnvelope
			{
				ApplicantId = applicant.ApplicantId,
				EventName = eventName,
				RequestId = request.RequestId,
				Category = request.Category,
				Properties = properties2,
				Payload = payload
			};
		}

		private static void AddCommonProperties(Dictionary<string, object?> properties, TelemetryApplicant applicant)
		{
			foreach (KeyValuePair<string, object> item in BuildCommonProperties(applicant))
			{
				properties[item.Key] = item.Value;
			}
		}

		private static Dictionary<string, object?> BuildCommonProperties(TelemetryApplicant applicant)
		{
			return new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
			{
				["anonymous_install_id"] = TelemetryIdentityStore.AnonymousInstallId,
				["session_id"] = SessionId,
				["ritsulib_version"] = "0.5.18",
				["ritsulib_informational_version"] = RitsuLibBuildInfo.InformationalVersion,
				["ritsulib_build_channel"] = ResolveBuildChannel(),
				["ritsulib_build_configuration"] = ResolveBuildConfiguration(),
				["applicant_id"] = applicant.ApplicantId,
				["owner_mod_id"] = applicant.OwnerModId,
				["applicant_display_name"] = applicant.ResolveDisplayName(),
				["game_version"] = ResolveGameVersion(),
				["game_release_label"] = Sts2HostVersion.ReleaseLabel,
				["platform"] = Environment.OSVersion.Platform.ToString(),
				["os_name"] = ResolveGodotOsName(),
				["os_version"] = Environment.OSVersion.VersionString,
				["process_architecture"] = RuntimeInformation.ProcessArchitecture.ToString(),
				["dotnet_runtime"] = RuntimeInformation.FrameworkDescription,
				["game_language"] = ResolveGameLanguage()
			};
		}

		private static string? ResolveGameVersion()
		{
			return Sts2HostVersion.Numeric?.ToString() ?? Sts2HostVersion.ReleaseLabel;
		}

		private static string? ResolveGodotOsName()
		{
			try
			{
				return OS.GetName();
			}
			catch
			{
				return null;
			}
		}

		private static string? ResolveGameLanguage()
		{
			try
			{
				return I18N.ResolveCurrentLanguageCode();
			}
			catch
			{
				return null;
			}
		}

		private static string ResolveBuildChannel()
		{
			if (RitsuLibBuildInfo.Metadata.TryGetValue("RitsuLibTelemetryBuildChannel", out string value) && !string.IsNullOrWhiteSpace(value))
			{
				return value;
			}
			if (RitsuLibBuildInfo.IsDevBuild)
			{
				return "dev";
			}
			return "release";
		}

		private static string ResolveBuildConfiguration()
		{
			if (RitsuLibBuildInfo.Metadata.TryGetValue("RitsuLibTelemetryBuildConfiguration", out string value) && !string.IsNullOrWhiteSpace(value))
			{
				return value;
			}
			return "Release";
		}

		private static JsonObject BuildPayload(TelemetryApplicant applicant, TelemetryRequest request, string eventName, JsonNode? applicantPayload)
		{
			JsonObject jsonObject = new JsonObject();
			JsonNode jsonNode = applicantPayload?.DeepClone();
			JsonObject jsonObject2 = ExtractBasePayloadOverride(jsonNode) ?? BuildBasePayload(request);
			if (jsonObject2.Count > 0)
			{
				jsonObject["base_payload"] = jsonObject2;
			}
			JsonObject jsonObject3 = BuildContributions(TelemetryRegistry.ResolvePrivateContributions(applicant, request), applicant, request, eventName, jsonObject2, "Private");
			if (jsonObject3.Count > 0)
			{
				jsonObject["private_contributions"] = jsonObject3;
			}
			JsonObject jsonObject4 = BuildContributions(TelemetryRegistry.ResolveSharedContributions(applicant, request), applicant, request, eventName, jsonObject2, "Shared");
			if (jsonObject4.Count > 0)
			{
				jsonObject["shared_contributions"] = jsonObject4;
			}
			if (jsonNode is JsonObject { Count: 0 })
			{
				return jsonObject;
			}
			if (jsonNode != null)
			{
				jsonObject["applicant_payload"] = jsonNode;
			}
			return jsonObject;
		}

		private static JsonObject? ExtractBasePayloadOverride(JsonNode? payload)
		{
			if (!(payload is JsonObject jsonObject))
			{
				return null;
			}
			if (!(jsonObject["__ritsulib_base_payload"] is JsonObject jsonObject2))
			{
				return null;
			}
			jsonObject.Remove("__ritsulib_base_payload");
			return jsonObject2.DeepClone().AsObject();
		}

		private static JsonObject BuildBasePayload(TelemetryRequest request)
		{
			if (request.Category == TelemetryDataCategory.ModInventory)
			{
				return new JsonObject
				{
					["mods"] = RunHistoryTelemetryCollector.BuildModInventoryList(),
					["loaded_mods"] = RunHistoryTelemetryCollector.BuildLoadedModList()
				};
			}
			return new JsonObject();
		}

		private static JsonObject BuildContributions(IReadOnlyList<ITelemetryContributionProvider> providers, TelemetryApplicant applicant, TelemetryRequest request, string eventName, JsonNode? basePayload, string logPrefix)
		{
			JsonObject jsonObject = new JsonObject();
			foreach (ITelemetryContributionProvider provider in providers)
			{
				JsonNode jsonNode;
				try
				{
					jsonNode = provider.Build(new TelemetryContributionContext
					{
						ApplicantId = applicant.ApplicantId,
						RequestId = request.RequestId,
						EventName = eventName,
						BasePayload = basePayload
					});
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[Telemetry] {logPrefix} contribution '{provider.ContributorModId}/{provider.ContributionId}' failed: {ex.Message}", 1);
					continue;
				}
				if (jsonNode != null)
				{
					JsonObject jsonObject2 = jsonObject[provider.ContributorModId] as JsonObject;
					if (jsonObject2 == null)
					{
						jsonObject2 = new JsonObject();
						jsonObject[provider.ContributorModId] = jsonObject2;
					}
					jsonObject2[provider.ContributionId] = jsonNode.DeepClone();
				}
			}
			return jsonObject;
		}
	}
	internal static class TelemetryJson
	{
		internal static JsonSerializerOptions Options { get; } = new JsonSerializerOptions
		{
			WriteIndented = false,
			PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
			PropertyNameCaseInsensitive = true,
			DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
			IncludeFields = false,
			Converters = { (JsonConverter)new JsonStringEnumConverter() }
		};
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Stores telemetry applicants and contribution providers for the current process.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         存储当前进程中的遥测申请方和数据贡献提供程序。
	///     </para>
	/// </summary>
	public static class TelemetryRegistry
	{
		private static readonly Lock Sync = new Lock();

		private static readonly Dictionary<string, TelemetryApplicant> Applicants = new Dictionary<string, TelemetryApplicant>(StringComparer.OrdinalIgnoreCase);

		private static readonly Dictionary<string, ITelemetryContributionProvider> ContributionProviders = new Dictionary<string, ITelemetryContributionProvider>(StringComparer.OrdinalIgnoreCase);

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a telemetry applicant.</para>
		///     <para xml:lang="zh-CN">注册或替换一个遥测申请方。</para>
		/// </summary>
		public static void RegisterApplicant(TelemetryApplicant applicant)
		{
			ArgumentNullException.ThrowIfNull(applicant, "applicant");
			applicant = NormalizeApplicant(applicant);
			using (Sync.EnterScope())
			{
				Applicants[applicant.ApplicantId] = applicant;
			}
			RitsuLibFramework.Logger.Info($"[Telemetry] Registered applicant '{applicant.ApplicantId}' -> {applicant.Adapter.EndpointDescription} ({applicant.Requests.Count} request(s)).", 1);
			try
			{
				TelemetrySettingsPages.RegisterApplicantPage(applicant);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Telemetry] Failed to refresh settings page for applicant '" + applicant.ApplicantId + "': " + ex.Message, 1);
				DiagnosticsTelemetryCollector.CaptureExceptionForAuthorizedApplicants(ex, "telemetry_settings_page_refresh");
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a telemetry contribution provider.</para>
		///     <para xml:lang="zh-CN">注册或替换一个遥测数据贡献提供程序。</para>
		/// </summary>
		public static void RegisterContributionProvider(ITelemetryContributionProvider provider)
		{
			ArgumentNullException.ThrowIfNull(provider, "provider");
			ArgumentException.ThrowIfNullOrWhiteSpace(provider.ContributorModId, "provider.ContributorModId");
			ArgumentException.ThrowIfNullOrWhiteSpace(provider.ContributionId, "provider.ContributionId");
			ValidateCategory(provider.Category, "provider");
			if (!Enum.IsDefined(provider.Visibility))
			{
				throw new ArgumentOutOfRangeException("provider", provider.Visibility, "The contribution visibility is not supported.");
			}
			using (Sync.EnterScope())
			{
				ContributionProviders[BuildContributionKey(provider.ContributorModId, provider.ContributionId)] = provider;
			}
			RitsuLibFramework.Logger.Info($"[Telemetry] Registered contribution '{provider.ContributorModId}/{provider.ContributionId}' ({provider.Category}, {provider.Visibility}).", 1);
		}

		/// <summary>
		///     <para xml:lang="en">Returns a snapshot of the registered telemetry applicants.</para>
		///     <para xml:lang="zh-CN">返回已注册遥测申请方的快照。</para>
		/// </summary>
		public static IReadOnlyList<TelemetryApplicant> GetApplicants()
		{
			using (Sync.EnterScope())
			{
				List<TelemetryApplicant> list = new List<TelemetryApplicant>();
				list.AddRange(Applicants.Values.OrderBy<TelemetryApplicant, string>((TelemetryApplicant x) => x.DisplayName, StringComparer.OrdinalIgnoreCase).ThenBy<TelemetryApplicant, string>((TelemetryApplicant x) => x.ApplicantId, StringComparer.OrdinalIgnoreCase));
				return new <>z__ReadOnlyList<TelemetryApplicant>(list);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Returns a snapshot of the registered contribution providers.</para>
		///     <para xml:lang="zh-CN">返回已注册数据贡献提供程序的快照。</para>
		/// </summary>
		public static IReadOnlyList<ITelemetryContributionProvider> GetContributionProviders()
		{
			using (Sync.EnterScope())
			{
				List<ITelemetryContributionProvider> list = new List<ITelemetryContributionProvider>();
				list.AddRange(ContributionProviders.Values.OrderBy<ITelemetryContributionProvider, string>((ITelemetryContributionProvider x) => x.ContributorModId, StringComparer.OrdinalIgnoreCase).ThenBy<ITelemetryContributionProvider, string>((ITelemetryContributionProvider x) => x.ContributionId, StringComparer.OrdinalIgnoreCase));
				return new <>z__ReadOnlyList<ITelemetryContributionProvider>(list);
			}
		}

		internal static bool TryGetApplicant(string applicantId, out TelemetryApplicant applicant)
		{
			using (Sync.EnterScope())
			{
				return Applicants.TryGetValue(applicantId, out applicant);
			}
		}

		internal static bool TryGetRequest(TelemetryApplicant applicant, string requestId, out TelemetryRequest request)
		{
			request = applicant.Requests.FirstOrDefault((TelemetryRequest r) => string.Equals(r.RequestId, requestId, StringComparison.OrdinalIgnoreCase));
			return request != null;
		}

		internal static IReadOnlyList<ITelemetryContributionProvider> ResolveSharedContributions(TelemetryApplicant applicant, TelemetryRequest request)
		{
			IReadOnlyList<string> subscriptions = request.ContributionSubscriptions;
			if (subscriptions.Count == 0)
			{
				return Array.Empty<ITelemetryContributionProvider>();
			}
			using (Sync.EnterScope())
			{
				List<ITelemetryContributionProvider> list = new List<ITelemetryContributionProvider>();
				list.AddRange(from provider in ContributionProviders.Values
					where provider.Visibility == TelemetryContributionVisibility.SharedToAuthorizedSubscribers
					where provider.Category == request.Category
					where SubscriptionMatches(provider, applicant, subscriptions, allowUnqualifiedOwnedContribution: false)
					where TelemetryConsentStore.IsSharedContributionGranted(applicant.ApplicantId, provider.ContributorModId, provider.ContributionId)
					select provider);
				return new <>z__ReadOnlyList<ITelemetryContributionProvider>(list);
			}
		}

		internal static IReadOnlyList<ITelemetryContributionProvider> ResolvePrivateContributions(TelemetryApplicant applicant, TelemetryRequest request)
		{
			IReadOnlyList<string> subscriptions = request.ContributionSubscriptions;
			if (subscriptions.Count == 0)
			{
				return Array.Empty<ITelemetryContributionProvider>();
			}
			using (Sync.EnterScope())
			{
				List<ITelemetryContributionProvider> list = new List<ITelemetryContributionProvider>();
				list.AddRange(from provider in ContributionProviders.Values
					where provider.Visibility == TelemetryContributionVisibility.PrivateToApplicant
					where provider.Category == request.Category
					where SubscriptionMatches(provider, applicant, subscriptions, allowUnqualifiedOwnedContribution: true)
					where IsOwnedByApplicant(provider, applicant)
					select provider);
				return new <>z__ReadOnlyList<ITelemetryContributionProvider>(list);
			}
		}

		internal static IReadOnlyList<ITelemetryContributionProvider> GetRequestedSharedContributions(TelemetryApplicant applicant)
		{
			using (Sync.EnterScope())
			{
				List<ITelemetryContributionProvider> list = new List<ITelemetryContributionProvider>();
				list.AddRange((from provider in ContributionProviders.Values
					where provider.Visibility == TelemetryContributionVisibility.SharedToAuthorizedSubscribers
					where applicant.Requests.Any((TelemetryRequest request) => request.Category == provider.Category && SubscriptionMatches(provider, applicant, request.ContributionSubscriptions, allowUnqualifiedOwnedContribution: false))
					select provider).OrderBy<ITelemetryContributionProvider, string>((ITelemetryContributionProvider provider) => provider.ContributorModId, StringComparer.OrdinalIgnoreCase).ThenBy<ITelemetryContributionProvider, string>((ITelemetryContributionProvider provider) => provider.ContributionId, StringComparer.OrdinalIgnoreCase));
				return new <>z__ReadOnlyList<ITelemetryContributionProvider>(list);
			}
		}

		private static bool IsOwnedByApplicant(ITelemetryContributionProvider provider, TelemetryApplicant applicant)
		{
			if (!string.Equals(provider.ContributorModId, applicant.OwnerModId, StringComparison.OrdinalIgnoreCase))
			{
				return string.Equals(provider.ContributorModId, applicant.ApplicantId, StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}

		private static bool SubscriptionMatches(ITelemetryContributionProvider provider, TelemetryApplicant applicant, IReadOnlyList<string> subscriptions, bool allowUnqualifiedOwnedContribution)
		{
			foreach (string subscription in subscriptions)
			{
				string text = subscription.Trim();
				if (!string.IsNullOrEmpty(text))
				{
					if (allowUnqualifiedOwnedContribution && IsOwnedByApplicant(provider, applicant) && string.Equals(text, provider.ContributionId, StringComparison.OrdinalIgnoreCase))
					{
						return true;
					}
					if (string.Equals(text, provider.ContributorModId + "/" + provider.ContributionId, StringComparison.OrdinalIgnoreCase) || string.Equals(text, provider.ContributorModId + ":" + provider.ContributionId, StringComparison.OrdinalIgnoreCase))
					{
						return true;
					}
				}
			}
			return false;
		}

		private static string BuildContributionKey(string contributorModId, string contributionId)
		{
			return $"{contributorModId.Length}:{contributorModId}{contributionId}";
		}

		private static TelemetryApplicant NormalizeApplicant(TelemetryApplicant applicant)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(applicant.ApplicantId, "applicant.ApplicantId");
			ArgumentException.ThrowIfNullOrWhiteSpace(applicant.OwnerModId, "applicant.OwnerModId");
			ArgumentException.ThrowIfNullOrWhiteSpace(applicant.DisplayName, "applicant.DisplayName");
			ArgumentNullException.ThrowIfNull(applicant.Adapter, "applicant.Adapter");
			ArgumentNullException.ThrowIfNull(applicant.Requests, "applicant.Requests");
			List<TelemetryRequest> list = new List<TelemetryRequest>(applicant.Requests.Count);
			HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			foreach (TelemetryRequest request in applicant.Requests)
			{
				if (request == null)
				{
					throw new ArgumentException("Telemetry request collections cannot contain null entries.", "applicant");
				}
				ArgumentException.ThrowIfNullOrWhiteSpace(request.RequestId, "request.RequestId");
				ArgumentNullException.ThrowIfNull(request.Description, "request.Description");
				ValidateCategory(request.Category, "applicant");
				if (!hashSet.Add(request.RequestId))
				{
					throw new ArgumentException($"Telemetry request id '{request.RequestId}' is registered more than once for applicant '{applicant.ApplicantId}'.", "applicant");
				}
				IReadOnlyList<string> source = request.ContributionSubscriptions ?? throw new ArgumentException("Telemetry request '" + request.RequestId + "' has a null contribution subscription collection.", "applicant");
				TelemetryRequest obj = new TelemetryRequest
				{
					RequestId = request.RequestId,
					Category = request.Category,
					Description = request.Description,
					DescriptionText = request.DescriptionText
				};
				List<string> list2 = new List<string>();
				list2.AddRange((from subscription in source
					where !string.IsNullOrWhiteSpace(subscription)
					select subscription.Trim()).Distinct<string>(StringComparer.OrdinalIgnoreCase));
				obj.ContributionSubscriptions = new <>z__ReadOnlyList<string>(list2);
				obj.CaptureFilter = request.CaptureFilter;
				list.Add(obj);
			}
			return new TelemetryApplicant
			{
				ApplicantId = applicant.ApplicantId,
				OwnerModId = applicant.OwnerModId,
				DisplayName = applicant.DisplayName,
				DisplayNameText = applicant.DisplayNameText,
				Adapter = applicant.Adapter,
				Requests = list
			};
		}

		private static void ValidateCategory(TelemetryDataCategory category, string paramName)
		{
			if (category == TelemetryDataCategory.None || !Enum.IsDefined(category))
			{
				throw new ArgumentOutOfRangeException(paramName, category, "A telemetry request or contribution must use one supported data category.");
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Describes one user-visible telemetry request made by an applicant.</para>
	///     <para xml:lang="zh-CN">描述申请方向用户展示的一个遥测数据申请项。</para>
	/// </summary>
	public sealed class TelemetryRequest
	{
		private readonly Func<TelemetryCaptureContext, bool>? _captureFilter;

		private Func<RunEndedEvent, bool>? _runHistoryCaptureFilter;

		/// <summary>
		///     <para xml:lang="en">Gets the request's stable ID within the applicant.</para>
		///     <para xml:lang="zh-CN">获取此申请项在申请方内部的稳定 ID。</para>
		/// </summary>
		public required string RequestId { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the data category covered by this request.</para>
		///     <para xml:lang="zh-CN">获取此申请项涵盖的数据类别。</para>
		/// </summary>
		public required TelemetryDataCategory Category { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the human-readable explanation shown before consent.</para>
		///     <para xml:lang="zh-CN">获取授权前向用户显示的可读说明。</para>
		/// </summary>
		public required string Description { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets an optional localized explanation shown before consent.</para>
		///     <para xml:lang="zh-CN">获取授权前向用户显示的可选本地化说明。</para>
		/// </summary>
		public ModSettingsText? DescriptionText { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the contribution IDs this request subscribes to. Private contributions are attached only to
		///         their owning applicant. Shared contributions additionally require explicit source consent and
		///         should use <c>contributorModId/contributionId</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取此申请项订阅的数据贡献 ID。私有数据贡献只会附加到其所属申请方；共享数据贡献还需要针对
		///         来源的明确授权，并应使用 <c>contributorModId/contributionId</c>。
		///     </para>
		/// </summary>
		public IReadOnlyList<string> ContributionSubscriptions { get; init; } = Array.Empty<string>();

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the obsolete alias of <see cref="P:STS2RitsuLib.Telemetry.TelemetryRequest.ContributionSubscriptions" /> retained for source
		///         compatibility.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取为源代码兼容性保留的 <see cref="P:STS2RitsuLib.Telemetry.TelemetryRequest.ContributionSubscriptions" /> 旧别名。
		///     </para>
		/// </summary>
		[Obsolete("Use ContributionSubscriptions.")]
		public IReadOnlyList<string> SharedContributionSubscriptions
		{
			get
			{
				return ContributionSubscriptions;
			}
			init
			{
				ContributionSubscriptions = value;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the legacy predicate for automatic run-history capture. Use <see cref="P:STS2RitsuLib.Telemetry.TelemetryRequest.CaptureFilter" /> and
		///         inspect <see cref="P:STS2RitsuLib.Telemetry.TelemetryCaptureContext.SourceData" /> as a <see cref="T:STS2RitsuLib.RunEndedEvent" /> instead.
		///         RitsuLib exposes this predicate only through the common capture-filter path.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取自动采集游戏历史记录时使用的旧版谓词。请改用 <see cref="P:STS2RitsuLib.Telemetry.TelemetryRequest.CaptureFilter" />，并将
		///         <see cref="P:STS2RitsuLib.Telemetry.TelemetryCaptureContext.SourceData" /> 作为 <see cref="T:STS2RitsuLib.RunEndedEvent" /> 检查。
		///         RitsuLib 只会通过通用采集筛选路径使用此谓词。
		///     </para>
		/// </summary>
		[Obsolete("Use CaptureFilter and inspect TelemetryCaptureContext.SourceData as RunEndedEvent.")]
		public Func<RunEndedEvent, bool>? RunHistoryCaptureFilter
		{
			get
			{
				return _runHistoryCaptureFilter;
			}
			init
			{
				_runHistoryCaptureFilter = value;
				_captureFilter = WrapRunHistoryCaptureFilter(value);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets an optional predicate applied to every event authorized by this request. RitsuLib invokes it
		///         synchronously before building contributions or queuing the event. Automatic collectors also invoke
		///         it before expensive source payload generation. Returning <see langword="false" />, or throwing an
		///         exception, rejects that capture for this applicant. The predicate runs on the capture source's
		///         current thread, may run concurrently, and must be fast, non-blocking, and reentrant.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取应用于此申请项所授权每个事件的可选谓词。RitsuLib 会在构建数据贡献或将事件加入队列
		///         前同步调用；自动采集器还会在生成开销较大的来源负载前调用。返回 <see langword="false" /> 或
		///         抛出异常时，会为此申请方拒绝该次采集。谓词在采集源的当前线程执行，可能被并发调用，因此
		///         必须快速、非阻塞且可重入。
		///     </para>
		/// </summary>
		public Func<TelemetryCaptureContext, bool>? CaptureFilter
		{
			get
			{
				return _captureFilter;
			}
			init
			{
				_captureFilter = value;
				_runHistoryCaptureFilter = null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a copy of this request with the supplied common event capture filter. This allows every
		///         built-in and custom request factory to opt into per-event filtering without making registered
		///         requests mutable.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建此申请项的副本并设置所提供的通用事件采集筛选器。借此，每个内置或自定义申请项工厂
		///         都能启用逐事件筛选，同时不会使已注册的申请项变为可变对象。
		///     </para>
		/// </summary>
		/// <param name="captureFilter">
		///     <para xml:lang="en">Fast, non-blocking, reentrant event predicate.</para>
		///     <para xml:lang="zh-CN">快速、非阻塞且可重入的事件谓词。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A new request carrying the supplied capture filter.</para>
		///     <para xml:lang="zh-CN">包含所提供采集筛选器的新申请项。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="captureFilter" /> is null.</para>
		///     <para xml:lang="zh-CN"><paramref name="captureFilter" /> 为 null。</para>
		/// </exception>
		public TelemetryRequest WithCaptureFilter(Func<TelemetryCaptureContext, bool> captureFilter)
		{
			ArgumentNullException.ThrowIfNull(captureFilter, "captureFilter");
			return new TelemetryRequest
			{
				RequestId = RequestId,
				Category = Category,
				Description = Description,
				DescriptionText = DescriptionText,
				ContributionSubscriptions = ContributionSubscriptions,
				CaptureFilter = captureFilter
			};
		}

