		/// <summary>
		///     <para xml:lang="en">
		///         Creates a run-history request with the legacy strongly typed capture predicate.
		///     </para>
		///     <para xml:lang="zh-CN">创建带旧版强类型采集谓词的游戏历史记录申请项。</para>
		/// </summary>
		[Obsolete("Use RunHistoryFiltered with TelemetryCaptureContext.SourceData.")]
		public static TelemetryRequest RunHistory(string description, IReadOnlyList<string>? sharedContributionSubscriptions, Func<RunEndedEvent, bool>? captureFilter)
		{
			ArgumentNullException.ThrowIfNull(description, "description");
			if (captureFilter == null)
			{
				return RunHistory(description, sharedContributionSubscriptions);
			}
			TelemetryRequest telemetryRequest = RunHistoryFiltered(description, WrapRunHistoryCaptureFilter(captureFilter), sharedContributionSubscriptions);
			telemetryRequest._runHistoryCaptureFilter = captureFilter;
			return telemetryRequest;
		}

