		internal string ResolveDescription()
		{
			return DescriptionText?.Resolve() ?? Description;
		}

		private static Func<TelemetryCaptureContext, bool>? WrapRunHistoryCaptureFilter(Func<RunEndedEvent, bool>? captureFilter)
		{
			if (captureFilter != null)
			{
				return (TelemetryCaptureContext context) => context.SourceData is RunEndedEvent arg && captureFilter(arg);
			}
			return null;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Captures process-level telemetry facts once and replays them to applicants after explicit consent.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         采集一次进程级遥测信息，并在用户明确授权后将其回放给各申请方。
	///     </para>
	/// </summary>
	internal static class TelemetryRuntime
	{
		private sealed record StartupTelemetrySnapshot(DateTimeOffset CapturedAtUtc, JsonArray Mods)
		{
			/// <summary>
			///     <para xml:lang="en">
			///         Builds the lightweight session-start payload. Common envelope properties carry version,
			///         platform, and identity fields.
			///     </para>
			///     <para xml:lang="zh-CN">
			///         构建轻量的会话启动负载。版本、平台和身份字段由信封的通用属性携带。
			///     </para>
			/// </summary>
			public JsonObject BuildSessionStartPayload()
			{
				return new JsonObject { ["captured_at_utc"] = CapturedAtUtc.ToString("O") };
			}

			/// <summary>
			///     <para xml:lang="en">
			///         Builds query-friendly session-start metadata from the captured startup snapshot.
			///     </para>
			///     <para xml:lang="zh-CN">
			///         根据采集的启动快照构建便于查询的会话启动元数据。
			///     </para>
			/// </summary>
			public Dictionary<string, object?> BuildSessionStartProperties()
			{
				return new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
				{
					["capture_source"] = "startup_snapshot",
					["startup_snapshot_at_utc"] = CapturedAtUtc.ToString("O"),
					["registered_mod_count"] = CountMods(),
					["loaded_mod_count"] = CountMods("Loaded"),
					["gameplay_mod_count"] = CountGameplayLoadedMods()
				};
			}

			/// <summary>
			///     <para xml:lang="en">
			///         Builds the mod-inventory event payload from the captured mod inventory.
			///     </para>
			///     <para xml:lang="zh-CN">
			///         根据采集的模组清单构建模组清单事件负载。
			///     </para>
			/// </summary>
			public JsonObject BuildModInventoryPayload()
			{
				JsonObject value = new JsonObject
				{
					["mods"] = Mods.DeepClone(),
					["loaded_mods"] = RunHistoryTelemetryCollector.FilterLoadedMods(Mods)
				};
				return new JsonObject
				{
					["captured_at_utc"] = CapturedAtUtc.ToString("O"),
					["__ritsulib_base_payload"] = value
				};
			}

			/// <summary>
			///     <para xml:lang="en">Builds query-friendly mod-inventory metadata.</para>
			///     <para xml:lang="zh-CN">构建便于查询的模组清单元数据。</para>
			/// </summary>
			public Dictionary<string, object?> BuildModInventoryProperties()
			{
				return new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
				{
					["capture_source"] = "startup_snapshot",
					["startup_snapshot_at_utc"] = CapturedAtUtc.ToString("O"),
					["registered_mod_count"] = CountMods(),
					["loaded_mod_count"] = CountMods("Loaded"),
					["disabled_mod_count"] = CountMods("Disabled"),
					["failed_mod_count"] = CountMods("Failed"),
					["added_at_runtime_mod_count"] = CountMods("AddedAtRuntime"),
					["gameplay_mod_count"] = CountGameplayLoadedMods()
				};
			}

			private int CountMods(string? loadState = null)
			{
				int num = 0;
				foreach (JsonNode mod in Mods)
				{
					if (mod is JsonObject jsonObject && (loadState == null || string.Equals(jsonObject["state"]?.GetValue<string>(), loadState, StringComparison.OrdinalIgnoreCase)))
					{
						num++;
					}
				}
				return num;
			}

			private int CountGameplayLoadedMods()
			{
				int num = 0;
				foreach (JsonNode mod in Mods)
				{
					if (mod is JsonObject jsonObject && string.Equals(jsonObject["state"]?.GetValue<string>(), "Loaded", StringComparison.OrdinalIgnoreCase))
					{
						JsonNode? jsonNode = jsonObject["affects_gameplay"];
						if (jsonNode == null || jsonNode.GetValue<bool>())
						{
							num++;
						}
					}
				}
				return num;
			}
		}

		private static readonly Lock Sync = new Lock();

		private static readonly HashSet<string> DeliveredStartupKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

		private static readonly HashSet<string> ConfirmedStartupKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

		private static StartupTelemetrySnapshot? _startupSnapshot;

		/// <summary>
		///     <para xml:lang="en">
		///         Captures the startup snapshot once and publishes a replayable lifecycle event for other tasks.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         采集一次启动快照，并发布可重放的生命周期事件供其他任务使用。
		///     </para>
		/// </summary>
		internal static void CaptureStartupSnapshot()
		{
			using (Sync.EnterScope())
			{
				if (_startupSnapshot != null)
				{
					return;
				}
				_startupSnapshot = new StartupTelemetrySnapshot(DateTimeOffset.UtcNow, RunHistoryTelemetryCollector.BuildModInventoryList());
			}
			RitsuLibFramework.Logger.Debug("[Telemetry] Captured persistent startup telemetry snapshot.", 1);
			RitsuLibFramework.PublishLifecycleEvent(new TelemetryStartupSnapshotReadyEvent(_startupSnapshot.CapturedAtUtc, DateTimeOffset.UtcNow), "TelemetryStartupSnapshotReadyEvent");
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Replays cached startup events to every currently authorized applicant.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将缓存的启动事件回放给当前已获授权的所有申请方。
		///     </para>
		/// </summary>
		internal static void ReplayStartupSnapshotToAuthorizedApplicants()
		{
			foreach (TelemetryApplicant applicant in TelemetryRegistry.GetApplicants())
			{
				ReplayStartupSnapshotToApplicant(applicant.ApplicantId);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Refreshes the cached mod inventory after the host finishes mod initialization.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在宿主完成模组初始化后刷新缓存的模组清单。
		///     </para>
		/// </summary>
		internal static void RefreshStartupModInventorySnapshot(string reason)
		{
			using (Sync.EnterScope())
			{
				if (_startupSnapshot == null)
				{
					return;
				}
				_startupSnapshot = _startupSnapshot with
				{
					Mods = RunHistoryTelemetryCollector.BuildModInventoryList()
				};
			}
			RitsuLibFramework.Logger.Debug("[Telemetry] Refreshed startup mod inventory snapshot (" + reason + ").", 1);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Replays cached startup events to one applicant when the user has authorized the matching requests.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         用户已授权对应申请项时，将缓存的启动事件回放给一个申请方。
		///     </para>
		/// </summary>
		internal static void ReplayStartupSnapshotToApplicant(string applicantId)
		{
			StartupTelemetrySnapshot startupSnapshot;
			using (Sync.EnterScope())
			{
				if (_startupSnapshot == null)
				{
					return;
				}
				startupSnapshot = _startupSnapshot;
			}
			if (TelemetryRegistry.TryGetApplicant(applicantId, out TelemetryApplicant applicant))
			{
				TryReplayStartupEvent(applicant, "basic_usage", "session_start", startupSnapshot.BuildSessionStartPayload, startupSnapshot.BuildSessionStartProperties);
				TryReplayStartupEvent(applicant, "mod_inventory", "mod_inventory", startupSnapshot.BuildModInventoryPayload, startupSnapshot.BuildModInventoryProperties);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Clears delivery markers for queued startup events discarded before transmission.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         清除排队后在发送前被丢弃的启动事件投递标记。
		///     </para>
		/// </summary>
		internal static void ResetStartupDeliveryForDiscardedEvents(IEnumerable<TelemetryEnvelope> events)
		{
			string[] array = (from key in events.Select(BuildStartupDeliveryKey)
				where key != null
				select key).ToArray();
			if (array.Length == 0)
			{
				return;
			}
			using (Sync.EnterScope())
			{
				string[] array2 = array;
				foreach (string item in array2)
				{
					if (!ConfirmedStartupKeys.Contains(item))
					{
						DeliveredStartupKeys.Remove(item);
					}
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Marks startup events as successfully delivered to the applicant's backend.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将启动事件标记为已成功送达申请方后端。
		///     </para>
		/// </summary>
		internal static void MarkStartupDeliveryConfirmed(IEnumerable<TelemetryEnvelope> events)
		{
			string[] array = (from key in events.Select(BuildStartupDeliveryKey)
				where key != null
				select key).ToArray();
			if (array.Length == 0)
			{
				return;
			}
			using (Sync.EnterScope())
			{
				string[] array2 = array;
				foreach (string item in array2)
				{
					ConfirmedStartupKeys.Add(item);
					DeliveredStartupKeys.Add(item);
				}
			}
		}

		private static void TryReplayStartupEvent(TelemetryApplicant applicant, string requestId, string eventName, Func<JsonNode> buildPayload, Func<IReadOnlyDictionary<string, object?>?> buildProperties)
		{
			if (!TelemetryRegistry.TryGetRequest(applicant, requestId, out TelemetryRequest request) || !TelemetryConsentStore.IsRequestGranted(applicant, request))
			{
				return;
			}
			TelemetryCaptureContext telemetryCaptureContext = new TelemetryCaptureContext(eventName, requestId, request.Category, "startup_snapshot");
			if (!TelemetryCaptureFilter.ShouldCapture(request, telemetryCaptureContext, applicant.ApplicantId))
			{
				return;
			}
			string item = BuildStartupDeliveryKey(applicant.ApplicantId, requestId, eventName);
			using (Sync.EnterScope())
			{
				if (!DeliveredStartupKeys.Add(item))
				{
					return;
				}
			}
			RitsuLibFramework.Logger.Debug($"[Telemetry] Replaying startup event '{eventName}' to applicant '{applicant.ApplicantId}'.", 1);
			if (!new TelemetryClient(applicant.ApplicantId).TryCapturePayload(eventName, requestId, buildPayload(), buildProperties(), telemetryCaptureContext, filterAlreadyApplied: true))
			{
				using (Sync.EnterScope())
				{
					DeliveredStartupKeys.Remove(item);
				}
				RitsuLibFramework.Logger.Warn($"[Telemetry] Failed to queue startup event '{eventName}' for applicant '{applicant.ApplicantId}'.", 1);
			}
		}

		private static string? BuildStartupDeliveryKey(TelemetryEnvelope envelope)
		{
			string eventName = envelope.EventName;
			if ((!(eventName == "session_start") && !(eventName == "mod_inventory")) || 1 == 0)
			{
				return null;
			}
			return BuildStartupDeliveryKey(envelope.ApplicantId, envelope.RequestId, envelope.EventName);
		}

		private static string BuildStartupDeliveryKey(string applicantId, string requestId, string eventName)
		{
			return $"{applicantId}\n{requestId}\n{eventName}";
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides stable telemetry schema identifiers.</para>
	///     <para xml:lang="zh-CN">提供稳定的遥测架构标识符。</para>
	/// </summary>
	public static class TelemetrySchemas
	{
		/// <summary>
		///     <para xml:lang="en">The version 1 telemetry event-envelope schema.</para>
		///     <para xml:lang="zh-CN">第一版遥测事件信封架构。</para>
		/// </summary>
		public const string EventV1 = "ritsulib.telemetry.v1";
	}
	internal static class TelemetryTaskRunner
	{
		internal static void Forget(Task task, string operation)
		{
			ArgumentNullException.ThrowIfNull(task, "task");
			ObserveAsync(task, operation);
		}

		private static async Task ObserveAsync(Task task, string operation)
		{
			try
			{
				await task.ConfigureAwait(continueOnCapturedContext: false);
			}
			catch (OperationCanceledException ex)
			{
				RitsuLibFramework.Logger.Debug("[Telemetry] Background task '" + operation + "' was canceled: " + ex.Message, 1);
			}
			catch (Exception ex2)
			{
				RitsuLibFramework.Logger.Warn("[Telemetry] Background task '" + operation + "' failed: " + ex2.Message, 1);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Bootstraps RitsuLib's built-in telemetry applicant and runtime hooks.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         引导初始化 RitsuLib 内置的遥测申请方和运行时钩子。
	///     </para>
	/// </summary>
	internal static class RitsuLibTelemetryBootstrap
	{
		private static bool _initialized;

		private static bool _mainMenuInitialized;

		/// <summary>
		///     <para xml:lang="en">
		///         Attaches telemetry runtime callbacks. Registration of the user-visible applicant is deferred until
		///         the first main menu.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         挂接遥测运行时回调。向用户显示的申请方会延迟到首次进入主菜单时注册。
		///     </para>
		/// </summary>
		internal static void Initialize()
		{
			if (_initialized)
			{
				return;
			}
			DiagnosticsTelemetryCollector.InitializeGlobalExceptionHandlers();
			IDisposable disposable = null;
			IDisposable disposable2 = null;
			try
			{
				disposable = RitsuLibFramework.SubscribeLifecycle<RunEndedEvent>(RunHistoryTelemetryCollector.CaptureEndedRun);
				disposable2 = RitsuLibFramework.SubscribeLifecycleOnce<MainMenuReadyEvent>(delegate
				{
					InitializeMainMenuTelemetry();
				});
				_initialized = true;
			}
			catch
			{
				disposable2?.Dispose();
				disposable?.Dispose();
				throw;
			}
		}

		private static void InitializeMainMenuTelemetry()
		{
			if (!_mainMenuInitialized)
			{
				_mainMenuInitialized = true;
				RunMainMenuStep("register_applicant", RegisterRitsuLibApplicant);
				RunMainMenuStep("ensure_settings_page", TelemetrySettingsPages.EnsureRootPage);
				RunMainMenuStep("capture_startup_snapshot", TelemetryRuntime.CaptureStartupSnapshot);
				RunMainMenuStep("first_main_menu_flow", TelemetryConsentPromptCoordinator.TryRunFirstMainMenuFlow);
			}
		}

		private static void RunMainMenuStep(string operation, Action action)
		{
			try
			{
				action();
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Telemetry] Main menu step '" + operation + "' failed: " + ex.Message, 1);
				DiagnosticsTelemetryCollector.CaptureExceptionForAuthorizedApplicants(ex, "telemetry_" + operation);
			}
		}

		private static void RegisterRitsuLibApplicant()
		{
			TelemetryRegistry.RegisterApplicant(new TelemetryApplicant
			{
				ApplicantId = "com.ritsukage.sts2-RitsuLib",
				OwnerModId = "com.ritsukage.sts2-RitsuLib",
				DisplayName = "RitsuLib",
				Adapter = RitsuLibTelemetryConfiguration.CreateAdapter(),
				Requests = new global::<>z__ReadOnlyArray<TelemetryRequest>(new TelemetryRequest[3]
				{
					TelemetryRequest.BasicUsage(T("ritsulib.telemetry.request.basicUsage.description", "Session start time, framework and game versions, build channel, platform, language, and anonymous install ID.")),
					TelemetryRequest.ModInventory(T("ritsulib.telemetry.request.modInventory.description", "Registered mod inventory, load states, versions, and gameplay flags for compatibility analysis.")),
					TelemetryRequest.Diagnostics(T("ritsulib.telemetry.request.diagnostics.description", "Exception reports and framework runtime diagnostics."))
				})
			});
		}

		private static ModSettingsText T(string key, string fallback)
		{
			return ModSettingsLocalization.Text(key, fallback);
		}
	}
	internal static class RitsuLibTelemetryConfiguration
	{
		private const string DefaultIngestEndpoint = "https://ritsulib-telemetry.ritsukage.com/v1/ingest";

		internal static ITelemetryAdapter CreateAdapter()
		{
			return new HttpJsonTelemetryAdapter("https://ritsulib-telemetry.ritsukage.com/v1/ingest");
		}
	}
	internal static class TelemetryQueue
	{
		private const int MaxEventsPerApplicant = 2000;

		private const int MaxEventsPerFlush = 1000;

		private static readonly Lock Sync = new Lock();

		private static readonly Dictionary<string, TaskCompletionSource> ActiveFlushes = new Dictionary<string, TaskCompletionSource>(StringComparer.OrdinalIgnoreCase);

		internal static void Enqueue(TelemetryEnvelope envelope)
		{
			using (Sync.EnterScope())
			{
				TelemetryQueueDocument telemetryQueueDocument = ReadQueue(envelope.ApplicantId);
				telemetryQueueDocument.Events.Add(envelope);
				TelemetryEnvelope[] events = Array.Empty<TelemetryEnvelope>();
				if (telemetryQueueDocument.Events.Count > 2000)
				{
					int count = telemetryQueueDocument.Events.Count - 2000;
					events = telemetryQueueDocument.Events.Take(count).ToArray();
					telemetryQueueDocument.Events.RemoveRange(0, count);
				}
				FileOperations.WriteResult writeResult = WriteQueue(envelope.ApplicantId, telemetryQueueDocument);
				if (!writeResult.Success)
				{
					TelemetryRuntime.ResetStartupDeliveryForDiscardedEvents(new <>z__ReadOnlySingleElementList<TelemetryEnvelope>(envelope));
					throw new InvalidOperationException("Failed to persist telemetry queue for '" + envelope.ApplicantId + "': " + writeResult.ErrorMessage);
				}
				TelemetryRuntime.ResetStartupDeliveryForDiscardedEvents(events);
				RitsuLibFramework.Logger.Debug($"[Telemetry] Queued event '{envelope.EventName}' for applicant '{envelope.ApplicantId}'. Queue size: {telemetryQueueDocument.Events.Count}.", 1);
			}
		}

		internal static Task EnqueueAsync(TelemetryEnvelope envelope, CancellationToken cancellationToken = default(CancellationToken))
		{
			ArgumentNullException.ThrowIfNull(envelope, "envelope");
			return Task.Run(delegate
			{
				Enqueue(envelope);
			}, cancellationToken);
		}

		public static async Task FlushApplicantAsync(string applicantId, CancellationToken cancellationToken = default(CancellationToken))
		{
			TelemetryApplicant applicant;
			TaskCompletionSource ownedFlush;
			while (true)
			{
				Task task;
				using (Sync.EnterScope())
				{
					if (!TelemetryRegistry.TryGetApplicant(applicantId, out applicant))
					{
						RitsuLibFramework.Logger.Warn("[Telemetry] Flush skipped: unknown applicant '" + applicantId + "'.", 1);
						return;
					}
					if (ActiveFlushes.TryGetValue(applicantId, out TaskCompletionSource value))
					{
						task = value.Task;
						goto IL_00e1;
					}
					ownedFlush = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
					ActiveFlushes.Add(applicantId, ownedFlush);
				}
				break;
				IL_00e1:
				RitsuLibFramework.Logger.Debug("[Telemetry] Waiting for the active flush for '" + applicantId + "'.", 1);
				await task.WaitAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			}
			try
			{
				object obj;
				int num;
				try
				{
					while (true)
					{
						TelemetryEnvelope[] batch = await Task.Run(() => PrepareBatch(applicantId, applicant), cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						if (batch.Length == 0)
						{
							break;
						}
						RitsuLibFramework.Logger.Debug($"[Telemetry] Sending {batch.Length} queued event(s) for applicant '{applicantId}' via {applicant.Adapter.AdapterId}.", 1);
						TelemetrySendResult result;
						try
						{
							result = await applicant.Adapter.SendAsync(applicant, batch, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						}
						catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
						{
							throw;
						}
						catch (Exception ex2)
						{
							result = TelemetrySendResult.Fail(ex2.Message);
						}
						if (!(await Task.Run(() => CommitBatchResult(applicantId, batch, result), CancellationToken.None).ConfigureAwait(continueOnCapturedContext: false)))
						{
							break;
						}
					}
					return;
				}
				catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
				{
					throw;
				}
				catch (Exception ex4)
				{
					obj = ex4;
					num = 1;
				}
				if (num == 1)
				{
					Exception ex5 = (Exception)obj;
					await Task.Run(delegate
					{
						RecordFlushFailure(applicantId, ex5);
					}, CancellationToken.None).ConfigureAwait(continueOnCapturedContext: false);
				}
			}
			finally
			{
				using (Sync.EnterScope())
				{
					if (ActiveFlushes.TryGetValue(applicantId, out TaskCompletionSource value2) && value2 == ownedFlush)
					{
						ActiveFlushes.Remove(applicantId);
					}
				}
				ownedFlush.TrySetResult();
			}
		}

		public static async Task FlushAllAsync(CancellationToken cancellationToken = default(CancellationToken))
		{
			foreach (TelemetryApplicant applicant in TelemetryRegistry.GetApplicants())
			{
				await FlushApplicantAsync(applicant.ApplicantId, cancellationToken);
			}
		}

		public static void ClearApplicant(string applicantId)
		{
			using (Sync.EnterScope())
			{
				TelemetryQueueDocument telemetryQueueDocument = ReadQueue(applicantId);
				FileOperations.WriteResult writeResult = WriteQueue(applicantId, new TelemetryQueueDocument());
				if (!writeResult.Success)
				{
					throw new InvalidOperationException("Failed to clear telemetry queue for '" + applicantId + "': " + writeResult.ErrorMessage);
				}
				TelemetryRuntime.ResetStartupDeliveryForDiscardedEvents(telemetryQueueDocument.Events);
				RitsuLibFramework.Logger.Info("[Telemetry] Cleared queue for applicant '" + applicantId + "'.", 1);
			}
		}

		public static int GetQueuedEventCount(string applicantId)
		{
			using (Sync.EnterScope())
			{
				return ReadQueue(applicantId).Events.Count;
			}
		}

		private static TelemetryEnvelope[] PrepareBatch(string applicantId, TelemetryApplicant applicant)
		{
			using (Sync.EnterScope())
			{
				TelemetryQueueDocument telemetryQueueDocument = ReadQueue(applicantId);
				List<TelemetryEnvelope> list = DropUnauthorizedEvents(applicant, telemetryQueueDocument);
				if (list.Count > 0)
				{
					FileOperations.WriteResult writeResult = WriteQueue(applicantId, telemetryQueueDocument);
					if (!writeResult.Success)
					{
						throw new InvalidOperationException("Failed to persist unauthorized telemetry removal for '" + applicantId + "': " + writeResult.ErrorMessage);
					}
					TelemetryRuntime.ResetStartupDeliveryForDiscardedEvents(list);
					RitsuLibFramework.Logger.Info($"[Telemetry] Dropped {list.Count} unauthorized queued event(s) for applicant '{applicantId}'.", 1);
				}
				if (telemetryQueueDocument.Events.Count != 0)
				{
					return telemetryQueueDocument.Events.Take(1000).ToArray();
				}
				RitsuLibFramework.Logger.Debug("[Telemetry] Flush skipped for '" + applicantId + "': queue is empty.", 1);
				return Array.Empty<TelemetryEnvelope>();
			}
		}

		private static bool CommitBatchResult(string applicantId, IReadOnlyList<TelemetryEnvelope> batch, TelemetrySendResult result)
		{
			using (Sync.EnterScope())
			{
				TelemetryQueueState telemetryQueueState = ReadState(applicantId);
				telemetryQueueState.LastSendUtc = DateTimeOffset.UtcNow;
				if (result.Success)
				{
					TelemetryQueueDocument telemetryQueueDocument = ReadQueue(applicantId);
					if (!TryRemoveSentPrefix(telemetryQueueDocument, batch))
					{
						RitsuLibFramework.Logger.Warn($"[Telemetry] Sent {batch.Count} event(s) for applicant '{applicantId}', but queue changed unexpectedly. Keeping queued events to avoid data loss.", 1);
						return false;
					}
					FileOperations.WriteResult writeResult = WriteQueue(applicantId, telemetryQueueDocument);
					if (!writeResult.Success)
					{
						RitsuLibFramework.Logger.Warn($"[Telemetry] Sent {batch.Count} event(s) for applicant '{applicantId}', but failed to persist queue removal: {writeResult.ErrorMessage}", 1);
						telemetryQueueState.LastError = writeResult.ErrorMessage;
						telemetryQueueState.FailureCount++;
						WriteStateWithWarning(applicantId, telemetryQueueState);
						return false;
					}
					TelemetryRuntime.MarkStartupDeliveryConfirmed(batch);
					telemetryQueueState.LastError = null;
					telemetryQueueState.FailureCount = 0;
					RitsuLibFramework.Logger.Debug($"[Telemetry] Sent {batch.Count} event(s) for applicant '{applicantId}'. Remaining queue size: {telemetryQueueDocument.Events.Count}.", 1);
					WriteStateWithWarning(applicantId, telemetryQueueState);
					return true;
				}
				telemetryQueueState.LastError = result.ErrorMessage;
				telemetryQueueState.FailureCount++;
				WriteStateWithWarning(applicantId, telemetryQueueState);
				RitsuLibFramework.Logger.Warn("[Telemetry] Send failed for applicant '" + applicantId + "': " + result.ErrorMessage, 1);
				return false;
			}
		}

		private static TelemetryQueueDocument ReadQueue(string applicantId)
		{
			string text = TelemetryPaths.QueuePath(applicantId);
			FileOperations.JsonResult<TelemetryQueueDocument> jsonResult = FileOperations.ReadJson<TelemetryQueueDocument>(text, TelemetryJson.Options, "TelemetryQueue");
			bool flag = false;
			if (jsonResult == null || !jsonResult.Success || jsonResult.Data == null)
			{
				string text2 = TelemetryPaths.LegacyQueuePath(applicantId);
				if (!string.Equals(text, text2, StringComparison.Ordinal))
				{
					jsonResult = FileOperations.ReadJson<TelemetryQueueDocument>(text2, TelemetryJson.Options, "TelemetryQueueLegacy");
					flag = jsonResult != null && jsonResult.Success && jsonResult.Data != null;
				}
			}
			TelemetryQueueDocument telemetryQueueDocument = ((jsonResult != null && jsonResult.Success && jsonResult.Data != null) ? jsonResult.Data : new TelemetryQueueDocument());
			TelemetryQueueDocument telemetryQueueDocument2 = telemetryQueueDocument;
			if (telemetryQueueDocument2.Events == null)
			{
				List<TelemetryEnvelope> list = (telemetryQueueDocument2.Events = new List<TelemetryEnvelope>());
			}
			if (flag)
			{
				telemetryQueueDocument.Events = telemetryQueueDocument.Events.Where((TelemetryEnvelope evt) => evt != null && string.Equals(evt.ApplicantId, applicantId, StringComparison.OrdinalIgnoreCase)).ToList();
				FileOperations.WriteResult writeResult = WriteQueue(applicantId, telemetryQueueDocument);
				if (!writeResult.Success)
				{
					RitsuLibFramework.Logger.Warn("[Telemetry] Failed to persist migrated queue for applicant '" + applicantId + "': " + writeResult.ErrorMessage, 1);
				}
			}
			return telemetryQueueDocument;
		}

		private static FileOperations.WriteResult WriteQueue(string applicantId, TelemetryQueueDocument doc)
		{
			return FileOperations.WriteJson(TelemetryPaths.QueuePath(applicantId), doc, TelemetryJson.Options, "TelemetryQueue");
		}

		private static TelemetryQueueState ReadState(string applicantId)
		{
			string text = TelemetryPaths.StatePath(applicantId);
			FileOperations.JsonResult<TelemetryQueueState> jsonResult = FileOperations.ReadJson<TelemetryQueueState>(text, TelemetryJson.Options, "TelemetryQueueState");
			bool flag = false;
			if (jsonResult == null || !jsonResult.Success || jsonResult.Data == null)
			{
				string text2 = TelemetryPaths.LegacyStatePath(applicantId);
				if (!string.Equals(text, text2, StringComparison.Ordinal))
				{
					jsonResult = FileOperations.ReadJson<TelemetryQueueState>(text2, TelemetryJson.Options, "TelemetryQueueStateLegacy");
					flag = jsonResult != null && jsonResult.Success && jsonResult.Data != null;
				}
			}
			TelemetryQueueState telemetryQueueState = ((jsonResult != null && jsonResult.Success && jsonResult.Data != null) ? jsonResult.Data : new TelemetryQueueState());
			telemetryQueueState.FailureCount = Math.Max(0, telemetryQueueState.FailureCount);
			if (flag)
			{
				WriteStateWithWarning(applicantId, telemetryQueueState);
			}
			return telemetryQueueState;
		}

		private static FileOperations.WriteResult WriteState(string applicantId, TelemetryQueueState state)
		{
			return FileOperations.WriteJson(TelemetryPaths.StatePath(applicantId), state, TelemetryJson.Options, "TelemetryQueueState");
		}

		private static void WriteStateWithWarning(string applicantId, TelemetryQueueState state)
		{
			FileOperations.WriteResult writeResult = WriteState(applicantId, state);
			if (!writeResult.Success)
			{
				RitsuLibFramework.Logger.Warn("[Telemetry] Failed to persist queue state for applicant '" + applicantId + "': " + writeResult.ErrorMessage, 1);
			}
		}

		private static void RecordFlushFailure(string applicantId, Exception exception)
		{
			RitsuLibFramework.Logger.Warn("[Telemetry] Flush failed for applicant '" + applicantId + "': " + exception.Message, 1);
			try
			{
				using (Sync.EnterScope())
				{
					TelemetryQueueState telemetryQueueState = ReadState(applicantId);
					telemetryQueueState.LastSendUtc = DateTimeOffset.UtcNow;
					telemetryQueueState.LastError = exception.Message;
					telemetryQueueState.FailureCount++;
					WriteStateWithWarning(applicantId, telemetryQueueState);
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Telemetry] Failed to record flush failure for applicant '" + applicantId + "': " + ex.Message, 1);
			}
		}

		private static List<TelemetryEnvelope> DropUnauthorizedEvents(TelemetryApplicant applicant, TelemetryQueueDocument queue)
		{
			List<TelemetryEnvelope> list = new List<TelemetryEnvelope>();
			for (int num = queue.Events.Count - 1; num >= 0; num--)
			{
				TelemetryEnvelope telemetryEnvelope = queue.Events[num];
				if (telemetryEnvelope == null || !string.Equals(telemetryEnvelope.Schema, "ritsulib.telemetry.v1", StringComparison.Ordinal) || !string.Equals(telemetryEnvelope.ApplicantId, applicant.ApplicantId, StringComparison.OrdinalIgnoreCase) || string.IsNullOrWhiteSpace(telemetryEnvelope.EventName) || telemetryEnvelope.Properties == null || !TelemetryRegistry.TryGetRequest(applicant, telemetryEnvelope.RequestId, out TelemetryRequest request) || request.Category != telemetryEnvelope.Category || !TelemetryConsentStore.IsRequestGranted(applicant, request))
				{
					if (telemetryEnvelope != null)
					{
						list.Add(telemetryEnvelope);
					}
					queue.Events.RemoveAt(num);
				}
			}
			list.Reverse();
			return list;
		}

		private static bool TryRemoveSentPrefix(TelemetryQueueDocument queue, IReadOnlyList<TelemetryEnvelope> sent)
		{
			if (sent.Count > queue.Events.Count)
			{
				return false;
			}
			if (sent.Where((TelemetryEnvelope t, int i) => !IsSameQueuedEvent(queue.Events[i], t)).Any())
			{
				return false;
			}
			queue.Events.RemoveRange(0, sent.Count);
			return true;
		}

		private static bool IsSameQueuedEvent(TelemetryEnvelope left, TelemetryEnvelope right)
		{
			if (left.Schema == right.Schema && left.ApplicantId == right.ApplicantId && left.EventName == right.EventName && left.RequestId == right.RequestId && left.Category == right.Category)
			{
				return left.TimestampUtc == right.TimestampUtc;
			}
			return false;
		}
	}
