	internal static class TelemetryIdentityStore
	{
		private static readonly Lock Sync = new Lock();

		private static TelemetryIdentityDocument? _document;

		internal static string AnonymousInstallId
		{
			get
			{
				using (Sync.EnterScope())
				{
					EnsureLoaded();
					return _document.AnonymousInstallId;
				}
			}
		}

		private static void EnsureLoaded()
		{
			if (_document != null)
			{
				return;
			}
			FileOperations.JsonResult<TelemetryIdentityDocument> jsonResult = FileOperations.ReadJson<TelemetryIdentityDocument>(TelemetryPaths.IdentityPath, TelemetryJson.Options, "TelemetryIdentity");
			if (jsonResult != null && jsonResult.Success && jsonResult.Data != null && Guid.TryParseExact(jsonResult.Data.AnonymousInstallId, "N", out var result))
			{
				_document = new TelemetryIdentityDocument
				{
					SchemaVersion = 1,
					AnonymousInstallId = result.ToString("N")
				};
				return;
			}
			TelemetryIdentityDocument telemetryIdentityDocument = new TelemetryIdentityDocument();
			FileOperations.WriteResult writeResult = FileOperations.WriteJson(TelemetryPaths.IdentityPath, telemetryIdentityDocument, TelemetryJson.Options, "TelemetryIdentity");
			if (!writeResult.Success)
			{
				throw new InvalidOperationException("Failed to persist telemetry identity: " + writeResult.ErrorMessage);
			}
			_document = telemetryIdentityDocument;
		}
	}
	internal static class TelemetryPaths
	{
		internal static string Root => ProfileManager.GetAccountBasePath() + "/telemetry";

		internal static string ConsentPath => Root + "/consent.json";

		internal static string IdentityPath => Root + "/identity.json";

		internal static string QueuePath(string applicantId)
		{
			return Root + "/applicants/" + BuildUniqueSegment(applicantId) + "/queue.json";
		}

		internal static string StatePath(string applicantId)
		{
			return Root + "/applicants/" + BuildUniqueSegment(applicantId) + "/state.json";
		}

		internal static string LegacyQueuePath(string applicantId)
		{
			return Root + "/applicants/" + BuildLegacySegment(applicantId) + "/queue.json";
		}

		internal static string LegacyStatePath(string applicantId)
		{
			return Root + "/applicants/" + BuildLegacySegment(applicantId) + "/state.json";
		}

		internal static string BuildUniqueSegment(string value)
		{
			string text = BuildLegacySegment(value);
			if (string.Equals(text, value, StringComparison.Ordinal))
			{
				return text;
			}
			string text2 = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).Substring(0, 12).ToLowerInvariant();
			return text + "-" + text2;
		}

		private static string BuildLegacySegment(string value)
		{
			string text = new string(value.Select(delegate(char ch)
			{
				bool flag = char.IsLetterOrDigit(ch);
				if (!flag)
				{
					bool flag2 = ((ch == '-' || ch == '.' || ch == '_') ? true : false);
					flag = flag2;
				}
				return (!flag) ? '_' : ch;
			}).ToArray()).Trim('_');
			if (!string.IsNullOrWhiteSpace(text))
			{
				return text;
			}
			return "unknown";
		}
	}
}
