		internal static JsonArray BuildModInventoryList()
		{
			JsonArray jsonArray = new JsonArray();
			foreach (Sts2ModInventoryEntry item in Sts2ModManagerCompat.BuildModInventoryEntries())
			{
				JsonObject jsonObject = new JsonObject
				{
					["id"] = item.Id,
					["name"] = item.Name,
					["version"] = item.Version,
					["state"] = item.State,
					["source"] = item.Source,
					["affects_gameplay"] = item.AffectsGameplay,
					["assembly"] = item.AssemblyName,
					["assembly_version"] = item.AssemblyVersion,
					["error_count"] = item.Errors.Count,
					["errors"] = BuildModErrors(item.Errors)
				};
				if (item.WorkshopItemId.HasValue)
				{
					jsonObject["workshop_id"] = item.WorkshopItemId.Value;
				}
				jsonArray.Add(jsonObject);
			}
			return jsonArray;
		}

		private static object? ReadMemberValue(object? source, string name)
		{
			if (source == null)
			{
				return null;
			}
			Type type = source.GetType();
			FieldInfo field = type.GetField(name, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (field != null)
			{
				return field.GetValue(source);
			}
			return type.GetProperty(name, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(source);
		}

		internal static JsonArray BuildLoadedModList()
		{
			return FilterLoadedMods(BuildModInventoryList());
		}

		internal static JsonArray FilterLoadedMods(JsonArray mods)
		{
			JsonArray jsonArray = new JsonArray();
			foreach (JsonNode mod in mods)
			{
				if (mod is JsonObject jsonObject && string.Equals(jsonObject["state"]?.GetValue<string>(), "Loaded", StringComparison.OrdinalIgnoreCase))
				{
					jsonArray.Add(jsonObject.DeepClone());
				}
			}
			return jsonArray;
		}

		private static JsonArray BuildModErrors(IEnumerable<LocString>? errors)
		{
			JsonArray jsonArray = new JsonArray();
			if (errors == null)
			{
				return jsonArray;
			}
			foreach (LocString error in errors)
			{
				JsonObject jsonObject = new JsonObject();
				foreach (KeyValuePair<string, object> variable in error.Variables)
				{
					if (!MayContainLocalPath(variable.Key, variable.Value))
					{
						jsonObject[variable.Key] = BuildSafeVariableNode(variable.Value);
					}
				}
				jsonArray.Add(new JsonObject
				{
					["table"] = error.LocTable,
					["key"] = error.LocEntryKey,
					["variables"] = jsonObject
				});
			}
			return jsonArray;
		}

