		private static JsonNode? SerializeVariableNode(object value)
		{
			try
			{
				return JsonSerializer.SerializeToNode(value, value.GetType(), TelemetryJson.Options);
			}
			catch
			{
				return JsonValue.Create(value.ToString());
			}
		}

		private static bool MayContainLocalPath(string key, object? value)
		{
			if (key.Contains("path", StringComparison.OrdinalIgnoreCase) || key.Contains("folder", StringComparison.OrdinalIgnoreCase) || key.Contains("directory", StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}
			if (value is string text)
			{
				if (!text.Contains(":\\", StringComparison.Ordinal) && !text.Contains(":/", StringComparison.Ordinal))
				{
					return text.Contains("\\Users\\", StringComparison.OrdinalIgnoreCase);
				}
				return true;
			}
			return false;
		}

		public static void CaptureVanillaRunHistory(string applicantId, JsonNode runHistory, JsonNode? applicantPayload = null, IReadOnlyDictionary<string, object?>? properties = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(applicantId, "applicantId");
			ArgumentNullException.ThrowIfNull(runHistory, "runHistory");
			JsonObject jsonObject = new JsonObject { ["run_history"] = runHistory.DeepClone() };
			if (applicantPayload != null)
			{
				jsonObject["mod_payload"] = applicantPayload.DeepClone();
			}
			Dictionary<string, object> dictionary = ((properties == null) ? new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase) : new Dictionary<string, object>(properties, StringComparer.OrdinalIgnoreCase));
			dictionary["payload_kind"] = "vanilla_run_history";
			dictionary["json_indented"] = false;
			new TelemetryClient(applicantId).CapturePayload("run_history.completed", "run_history", jsonObject, dictionary);
		}

		internal static void CaptureEndedRun(RunEndedEvent evt)
		{
			//IL_0154: Unknown result type (might be due to invalid IL or missing references)
			//IL_0159: Unknown result type (might be due to invalid IL or missing references)
			//IL_017a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0180: Invalid comparison between Unknown and I4
			TelemetryCaptureContext telemetryCaptureContext = new TelemetryCaptureContext("run_history.completed", "run_history", TelemetryDataCategory.RunHistory, "run_ended", evt);
			List<string> list = new List<string>();
			foreach (TelemetryApplicant applicant in TelemetryRegistry.GetApplicants())
			{
				if (TelemetryRegistry.TryGetRequest(applicant, "run_history", out TelemetryRequest request) && TelemetryConsentStore.IsRequestGranted(applicant, request) && TelemetryCaptureFilter.ShouldCapture(request, telemetryCaptureContext, applicant.ApplicantId))
				{
					list.Add(applicant.ApplicantId);
				}
			}
			if (list.Count == 0)
			{
				return;
			}
			JsonNode jsonNode;
			try
			{
				jsonNode = JsonSerializer.SerializeToNode(evt.Run, JsonSerializationUtility.GetTypeInfo<SerializableRun>());
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Telemetry] Failed to serialize ended run history: " + ex.Message, 1);
				return;
			}
			if (jsonNode == null)
			{
				RitsuLibFramework.Logger.Warn("[Telemetry] Failed to serialize ended run history: result is null.", 1);
				return;
			}
			Dictionary<string, object> properties = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
			{
				["capture_source"] = "run_ended",
				["is_victory"] = evt.IsVictory,
				["is_abandoned"] = evt.IsAbandoned,
				["occurred_at_utc"] = evt.OccurredAtUtc.ToString("O"),
				["run_game_mode"] = ((object)evt.Run.GameMode/*cast due to constrained. prefix*/).ToString(),
				["run_is_daily"] = (int)evt.Run.GameMode == 2 || evt.Run.DailyTime.HasValue,
				["run_player_count"] = evt.Run.Players.Count,
				["run_floor_reached"] = ReadMemberValue(evt.Run, "FloorReached"),
				["run_ascension"] = evt.Run.Ascension,
				["run_time_seconds"] = evt.Run.RunTime,
				["run_win_time_seconds"] = evt.Run.WinTime,
				["run_reload_count"] = ReadMemberValue(evt.Run, "NumReloads"),
				["run_character_ids"] = evt.Run.Players.Select((SerializablePlayer player) => ((object)player.CharacterId)?.ToString() ?? "<unknown>").ToArray()
			};
			JsonObject payload = new JsonObject { ["run_history"] = jsonNode };
			List<string> list2 = new List<string>();
			foreach (string item in list)
			{
				if (new TelemetryClient(item).TryCapturePayload("run_history.completed", "run_history", payload, properties, telemetryCaptureContext, filterAlreadyApplied: true))
				{
					list2.Add(item);
				}
			}
			RitsuLibFramework.Logger.Info($"[Telemetry] Captured ended run history for {list2.Count} authorized applicant(s); abandoned={evt.IsAbandoned}, victory={evt.IsVictory}.", 1);
			foreach (string item2 in list2)
			{
				TelemetryTaskRunner.Forget(TelemetryQueue.FlushApplicantAsync(item2), "flush_applicant_after_run_history");
			}
		}
	}
