namespace STS2RitsuLib.Telemetry.Integration
{
	/// <summary>
	///     <para xml:lang="en">
	///         Shows the telemetry consent notification on the first main menu and starts delivery of authorized
	///         startup data.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         首次进入主菜单时显示遥测授权通知，并开始投递已获授权的启动数据。
	///     </para>
	/// </summary>
	internal static class TelemetryConsentPromptCoordinator
	{
		private static bool _handledFirstMainMenu;

		/// <summary>
		///     <para xml:lang="en">Runs the first-main-menu flow at most once per process.</para>
		///     <para xml:lang="zh-CN">每个进程最多运行一次首次主菜单流程。</para>
		/// </summary>
		internal static void TryRunFirstMainMenuFlow()
		{
			if (!_handledFirstMainMenu)
			{
				_handledFirstMainMenu = true;
				TelemetryRuntime.RefreshStartupModInventorySnapshot("MainMenuReadyEvent");
				TelemetryRuntime.ReplayStartupSnapshotToAuthorizedApplicants();
				TelemetryApplicant[] array = (from applicant in TelemetryRegistry.GetApplicants()
					where TelemetryConsentStore.GetApplicantConsent(applicant.ApplicantId).Consent == TelemetryConsentState.Unknown
					select applicant).ToArray();
				if (array.Length == 0)
				{
					RitsuLibFramework.Logger.Debug("[Telemetry] No pending first-run consent prompt; flushing authorized startup telemetry.", 1);
					TelemetryTaskRunner.Forget(TelemetryQueue.FlushAllAsync(), "flush_all_after_startup");
					return;
				}
				if (ResolveHostNode() == null)
				{
					RitsuLibFramework.Logger.Warn("[Telemetry] Cannot show consent prompt: no active Godot scene tree host was found.", 1);
					return;
				}
				RitsuLibFramework.Logger.Debug($"[Telemetry] Showing persistent consent toast for {array.Length} applicant(s).", 1);
				ShowPendingConsentToast();
			}
		}

		private static void ShowPendingConsentToast()
		{
			TelemetryApplicant[] array = ResolvePendingApplicants();
			if (array.Length != 0)
			{
				RitsuToastService.Show(new RitsuToastRequest(string.Format(L("ritsulib.telemetry.toast.body", "{0} telemetry applicant(s) need review."), array.Length), L("ritsulib.telemetry.toast.title", "Telemetry permission"), null, RitsuToastLevel.Warning, null, ShowPendingConsentPrompt)
				{
					IsPersistent = true
				});
			}
		}

		private static void ShowPendingConsentPrompt()
		{
			TelemetryApplicant[] array = ResolvePendingApplicants();
			if (array.Length == 0)
			{
				return;
			}
			TelemetryApplicant applicant = array[0];
			Node val = ResolveHostNode();
			if (val == null)
			{
				RitsuLibFramework.Logger.Warn("[Telemetry] Cannot show consent prompt: no active Godot scene tree host was found.", 1);
				return;
			}
			RitsuLibFramework.Logger.Debug("[Telemetry] Showing consent prompt for applicant '" + applicant.ApplicantId + "'.", 1);
			ModSettingsUiFactory.ShowStyledConfirm(val, L("ritsulib.telemetry.prompt.title", "Telemetry consent"), BuildPromptBody(applicant), L("ritsulib.telemetry.prompt.cancel", "Reject this applicant"), L("ritsulib.telemetry.prompt.confirm", "Allow this applicant"), confirmIsDanger: false, delegate
			{
				GrantApplicant(applicant);
			}, showCancel: true, delegate
			{
				DenyApplicant(applicant);
			}, ShowPendingConsentToast, escapeTriggersCancel: false, cancelIsDanger: true);
		}

		private static TelemetryApplicant[] ResolvePendingApplicants()
		{
			return (from applicant in TelemetryRegistry.GetApplicants()
				where TelemetryConsentStore.GetApplicantConsent(applicant.ApplicantId).Consent == TelemetryConsentState.Unknown
				select applicant).ToArray();
		}

		private static void GrantApplicant(TelemetryApplicant applicant)
		{
			GrantRequestedSharedContributions(applicant);
			TelemetryConsentStore.SetApplicantConsent(applicant.ApplicantId, TelemetryConsentState.Granted, applicant.Requests.Select((TelemetryRequest r) => r.RequestId));
			RitsuLibFramework.Logger.Info("[Telemetry] User granted first-run telemetry consent for applicant '" + applicant.ApplicantId + "'.", 1);
			ShowPendingConsentToast();
		}

		private static void DenyApplicant(TelemetryApplicant applicant)
		{
			TelemetryConsentStore.SetApplicantConsent(applicant.ApplicantId, TelemetryConsentState.Denied);
			TelemetryQueue.ClearApplicant(applicant.ApplicantId);
			RitsuLibFramework.Logger.Info("[Telemetry] User rejected first-run telemetry consent for applicant '" + applicant.ApplicantId + "'.", 1);
			ShowPendingConsentToast();
		}

		private static string BuildPromptBody(TelemetryApplicant applicant)
		{
			List<string> list = new List<string>
			{
				L("ritsulib.telemetry.prompt.bodyIntro", "This mod requests permission to send telemetry to its fixed endpoint. Startup information has already been sampled locally and will only be sent after consent."),
				"",
				applicant.ResolveDisplayName() + " (" + applicant.ApplicantId + ")",
				string.Format(L("ritsulib.telemetry.prompt.endpoint", "Endpoint: {0}"), applicant.Adapter.EndpointDescription)
			};
			list.AddRange(applicant.Requests.Select((TelemetryRequest request) => string.Format(L("ritsulib.telemetry.prompt.requestLine", "- {0}: {1}"), ResolveCategory(request.Category), request.ResolveDescription())));
			IReadOnlyList<ITelemetryContributionProvider> requestedSharedContributions = TelemetryRegistry.GetRequestedSharedContributions(applicant);
			if (requestedSharedContributions.Count > 0)
			{
				list.Add("");
				list.Add(L("ritsulib.telemetry.prompt.shared.heading", "Additional shared data sources:"));
				list.AddRange(requestedSharedContributions.Select((ITelemetryContributionProvider provider) => string.Format(L("ritsulib.telemetry.prompt.shared.line", "- {0}/{1} ({2})"), provider.ContributorModId, provider.ContributionId, ResolveCategory(provider.Category))));
			}
			list.Add("");
			list.Add(L("ritsulib.telemetry.prompt.footer", "You can manage each applicant later from RitsuLib > Telemetry."));
			return string.Join("\n", list);
		}

		private static void GrantRequestedSharedContributions(TelemetryApplicant applicant)
		{
			foreach (ITelemetryContributionProvider requestedSharedContribution in TelemetryRegistry.GetRequestedSharedContributions(applicant))
			{
				TelemetryConsentStore.SetSharedContributionConsent(applicant.ApplicantId, requestedSharedContribution.ContributorModId, requestedSharedContribution.ContributionId, granted: true);
			}
		}

		private static Node? ResolveHostNode()
		{
			if (NGame.Instance != null)
			{
				return (Node?)(object)NGame.Instance;
			}
			MainLoop mainLoop = Engine.GetMainLoop();
			SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
			if (val == null)
			{
				return null;
			}
			return (Node?)(object)val.Root;
		}

		private static string L(string key, string fallback)
		{
			return ModSettingsLocalization.Get(key, fallback);
		}

		private static string ResolveCategory(TelemetryDataCategory category)
		{
			return L($"ritsulib.telemetry.category.{category}", category.ToString());
		}
	}
	/// <summary>
	///     <para xml:lang="en">Registers the single-page telemetry permission manager.</para>
	///     <para xml:lang="zh-CN">注册单页遥测权限管理界面。</para>
	/// </summary>
	internal static class TelemetrySettingsPages
	{
		private const string RootPageId = "telemetry";

		private static readonly Lock Sync = new Lock();

		private static bool _rootRegistered;

		/// <summary>
		///     <para xml:lang="en">Ensures that the telemetry settings page is registered.</para>
		///     <para xml:lang="zh-CN">确保遥测设置页面已注册。</para>
		/// </summary>
		internal static void EnsureRootPage()
		{
			bool flag = false;
			using (Sync.EnterScope())
			{
				if (!_rootRegistered)
				{
					_rootRegistered = true;
					flag = true;
				}
			}
			if (!flag)
			{
				return;
			}
			try
			{
				RegisterRootPage();
			}
			catch
			{
				using (Sync.EnterScope())
				{
					_rootRegistered = false;
				}
				throw;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Re-registers the telemetry settings page after an applicant is registered.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册申请方后重新注册遥测设置页面。
		///     </para>
		/// </summary>
		internal static void RegisterApplicantPage(TelemetryApplicant applicant)
		{
			ArgumentNullException.ThrowIfNull(applicant, "applicant");
			EnsureRootPage();
			RegisterRootPage();
		}

		private static void RegisterRootPage()
		{
			IReadOnlyList<TelemetryApplicant> applicants = TelemetryRegistry.GetApplicants();
			RitsuLibFramework.RegisterModSettings("com.ritsukage.sts2-RitsuLib", delegate(ModSettingsPageBuilder page)
			{
				page.AsChildOf("com.ritsukage.sts2-RitsuLib").WithSortOrder(-240).WithTitle(T("ritsulib.telemetry.page.title", "Telemetry"))
					.WithDescription(T("ritsulib.telemetry.page.description", "Manage data sharing permissions."));
				if (applicants.Count == 0)
				{
					page.AddSection("empty", delegate(ModSettingsSectionBuilder section)
					{
						section.AddParagraph("empty", T("ritsulib.telemetry.applicants.empty", "No telemetry applicants are registered."));
					});
					return;
				}
				foreach (TelemetryApplicant item in applicants)
				{
					string applicantId = item.ApplicantId;
					page.AddSection("applicant_" + BuildSafeId(applicantId), delegate(ModSettingsSectionBuilder section)
					{
						section.WithTitle(ModSettingsText.DynamicFullRefreshOnly(() => BuildApplicantSectionTitle(applicantId))).WithDescription(ModSettingsText.DynamicFullRefreshOnly(() => BuildApplicantSectionDescription(applicantId))).Collapsible(!string.Equals(applicantId, "com.ritsukage.sts2-RitsuLib", StringComparison.OrdinalIgnoreCase))
							.AddCustom("actions", T("ritsulib.telemetry.actions.label", "Permission"), (IModSettingsUiActionHost host) => BuildApplicantActionButtons(applicantId, host))
							.AddParagraph("status", ModSettingsText.DynamicFullRefreshOnly(() => BuildApplicantStatus(applicantId)))
							.AddParagraph("requests", ModSettingsText.DynamicFullRefreshOnly(() => BuildApplicantRequests(applicantId)));
					});
				}
			}, "telemetry");
		}

		private static Control BuildApplicantActionButtons(string applicantId, IModSettingsUiActionHost host)
		{
			//IL_0014: Unknown result type (might be due to invalid IL or missing references)
			//IL_0019: Unknown result type (might be due to invalid IL or missing references)
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			//IL_0036: Expected O, but got Unknown
			HBoxContainer row = new HBoxContainer
			{
				SizeFlagsHorizontal = (SizeFlags)3,
				Alignment = (AlignmentMode)2,
				MouseFilter = (MouseFilterEnum)2
			};
			((Control)row).AddThemeConstantOverride(StringName.op_Implicit("separation"), 10);
			RefreshActionRow();
			return (Control)(object)row;
			void RefreshActionRow()
			{
				ClearChildren((Node)(object)row);
				TelemetryConsentState consent = TelemetryConsentStore.GetApplicantConsent(applicantId).Consent;
				bool isGranted = consent == TelemetryConsentState.Granted;
				ModSettingsTextButton modSettingsTextButton = new ModSettingsTextButton(isGranted ? L("ritsulib.telemetry.revoke.button", "Revoke") : L("ritsulib.telemetry.allow.button", "Allow"), (!isGranted) ? ModSettingsButtonTone.Accent : ModSettingsButtonTone.Danger, delegate
				{
					if (isGranted)
					{
						Revoke(applicantId);
					}
					else
					{
						GrantAll(applicantId);
					}
					RefreshActionRow();
					host.RequestRefresh();
				});
				((Node)row).AddChild((Node)(object)modSettingsTextButton, false, (InternalMode)0);
				if (TelemetryQueue.GetQueuedEventCount(applicantId) > 0)
				{
					ModSettingsTextButton modSettingsTextButton2 = new ModSettingsTextButton(L("ritsulib.telemetry.retry.button", "Retry now"), ModSettingsButtonTone.Normal, delegate
					{
						TelemetryTaskRunner.Forget(TelemetryQueue.FlushApplicantAsync(applicantId), "flush_applicant_from_settings");
						RefreshActionRow();
						host.RequestRefresh();
					});
					((Node)row).AddChild((Node)(object)modSettingsTextButton2, false, (InternalMode)0);
				}
			}
		}

		private static void ClearChildren(Node node)
		{
			while (node.GetChildCount(false) > 0)
			{
				Node child = node.GetChild(0, false);
				node.RemoveChild(child);
				child.QueueFree();
			}
		}

		private static string BuildApplicantSectionTitle(string applicantId)
		{
			if (!TelemetryRegistry.TryGetApplicant(applicantId, out TelemetryApplicant applicant))
			{
				return applicantId;
			}
			return string.Format(L("ritsulib.telemetry.applicant.row.label", "{0}"), applicant.ResolveDisplayName());
		}

		private static string BuildApplicantSectionDescription(string applicantId)
		{
			if (!TelemetryRegistry.TryGetApplicant(applicantId, out TelemetryApplicant applicant))
			{
				return L("ritsulib.telemetry.applicant.missing", "Telemetry applicant is no longer registered.");
			}
			TelemetryConsentState consent = TelemetryConsentStore.GetApplicantConsent(applicantId).Consent;
			return string.Format(L("ritsulib.telemetry.applicant.row.description", "{0} · {1} request(s)"), ResolveConsent(consent), applicant.Requests.Count);
		}

		private static string BuildApplicantStatus(string applicantId)
		{
			if (!TelemetryRegistry.TryGetApplicant(applicantId, out TelemetryApplicant applicant))
			{
				return L("ritsulib.telemetry.applicant.missing", "Telemetry applicant is no longer registered.");
			}
			TelemetryApplicantConsent applicantConsent = TelemetryConsentStore.GetApplicantConsent(applicantId);
			string value = ((applicantConsent.GrantedRequests.Count == 0) ? L("empty.none", "None") : string.Join(", ", applicantConsent.GrantedRequests.OrderBy<string, string>((string x) => x, StringComparer.OrdinalIgnoreCase)));
			string value2 = CountGrantedSharedContributions(applicantConsent).ToString();
			<>y__InlineArray5<string> buffer = default(<>y__InlineArray5<string>);
			buffer[0] = FormatLine("ritsulib.telemetry.field.consent", "Consent", ResolveConsent(applicantConsent.Consent));
			buffer[1] = FormatLine("ritsulib.telemetry.field.endpoint", "Endpoint", applicant.Adapter.EndpointDescription);
			buffer[2] = FormatLine("ritsulib.telemetry.field.grantedRequests", "Granted requests", value);
			buffer[3] = FormatLine("ritsulib.telemetry.field.grantedSharedContributions", "Shared sources", value2);
			buffer[4] = FormatLine("ritsulib.telemetry.field.queuedEvents", "Queued events", TelemetryQueue.GetQueuedEventCount(applicantId).ToString());
			return string.Join("\n", (ReadOnlySpan<string?>)buffer);
		}

		private static string BuildApplicantRequests(string applicantId)
		{
			if (!TelemetryRegistry.TryGetApplicant(applicantId, out TelemetryApplicant applicant))
			{
				return L("ritsulib.telemetry.applicant.missing", "Telemetry applicant is no longer registered.");
			}
			string text = string.Join("\n", applicant.Requests.Select((TelemetryRequest request) => string.Format(L("ritsulib.telemetry.request.line", "- {0} ({1}): {2}"), ResolveCategory(request.Category), request.RequestId, request.ResolveDescription())));
			string text2 = BuildSharedContributionRequests(applicantId, applicant);
			string text3 = string.Join("\n\n", new string[2] { text, text2 }.Where((string value) => !string.IsNullOrWhiteSpace(value)));
			if (!string.IsNullOrWhiteSpace(text3))
			{
				return text3;
			}
			return L("ritsulib.telemetry.requests.empty", "This applicant has no data requests.");
		}

		private static void GrantAll(string applicantId)
		{
			if (TelemetryRegistry.TryGetApplicant(applicantId, out TelemetryApplicant applicant))
			{
				GrantRequestedSharedContributions(applicant);
				TelemetryConsentStore.SetApplicantConsent(applicantId, TelemetryConsentState.Granted, applicant.Requests.Select((TelemetryRequest r) => r.RequestId));
			}
		}

		private static void Revoke(string applicantId)
		{
			TelemetryConsentStore.SetApplicantConsent(applicantId, TelemetryConsentState.Denied);
			TelemetryQueue.ClearApplicant(applicantId);
		}

		private static string BuildSafeId(string value)
		{
			return TelemetryPaths.BuildUniqueSegment(value);
		}

		private static string FormatLine(string key, string fallbackLabel, string value)
		{
			return string.Format(L("ritsulib.telemetry.field.line", "{0}: {1}"), L(key, fallbackLabel), value);
		}

		private static string ResolveConsent(TelemetryConsentState state)
		{
			return state switch
			{
				TelemetryConsentState.Granted => L("ritsulib.telemetry.consent.granted", "Granted"), 
				TelemetryConsentState.Denied => L("ritsulib.telemetry.consent.denied", "Denied"), 
				_ => L("ritsulib.telemetry.consent.unknown", "Not decided"), 
			};
		}

		private static string ResolveCategory(TelemetryDataCategory category)
		{
			return L($"ritsulib.telemetry.category.{category}", category.ToString());
		}

		private static string BuildSharedContributionRequests(string applicantId, TelemetryApplicant applicant)
		{
			IReadOnlyList<ITelemetryContributionProvider> requestedSharedContributions = TelemetryRegistry.GetRequestedSharedContributions(applicant);
			if (requestedSharedContributions.Count == 0)
			{
				return "";
			}
			TelemetryApplicantConsent consent = TelemetryConsentStore.GetApplicantConsent(applicantId);
			List<string> list = new List<string> { L("ritsulib.telemetry.shared.heading", "Additional shared data sources:") };
			list.AddRange(requestedSharedContributions.Select(delegate(ITelemetryContributionProvider provider)
			{
				string format = L("ritsulib.telemetry.shared.line", "- {0}/{1} ({2}): {3}");
				global::<>y__InlineArray4<object> buffer = default(global::<>y__InlineArray4<object>);
				buffer[0] = provider.ContributorModId;
				buffer[1] = provider.ContributionId;
				buffer[2] = ResolveCategory(provider.Category);
				buffer[3] = ResolveSharedContributionState(consent, provider);
				return string.Format(format, (ReadOnlySpan<object?>)buffer);
			}));
			return string.Join("\n", list);
		}

		private static string ResolveSharedContributionState(TelemetryApplicantConsent consent, ITelemetryContributionProvider provider)
		{
			if (consent.Consent != TelemetryConsentState.Granted || !consent.SharedContributionSources.TryGetValue(provider.ContributorModId, out HashSet<string> value) || !value.Contains(provider.ContributionId))
			{
				return L("ritsulib.telemetry.shared.notGranted", "Not granted");
			}
			return L("ritsulib.telemetry.shared.granted", "Granted");
		}

		private static int CountGrantedSharedContributions(TelemetryApplicantConsent consent)
		{
			return consent.SharedContributionSources.Values.Sum((HashSet<string> ids) => ids.Count);
		}

		private static void GrantRequestedSharedContributions(TelemetryApplicant applicant)
		{
			foreach (ITelemetryContributionProvider requestedSharedContribution in TelemetryRegistry.GetRequestedSharedContributions(applicant))
			{
				TelemetryConsentStore.SetSharedContributionConsent(applicant.ApplicantId, requestedSharedContribution.ContributorModId, requestedSharedContribution.ContributionId, granted: true);
			}
		}

		private static ModSettingsText T(string key, string fallback)
		{
			return ModSettingsLocalization.Text(key, fallback);
		}

		private static string L(string key, string fallback)
		{
			return ModSettingsLocalization.Get(key, fallback);
		}
	}
