namespace STS2RitsuLib.Telemetry.Diagnostics
{
	internal static class DiagnosticsTelemetryCollector
	{
		private const int MaxRecentFingerprints = 128;

		private static readonly Lock Sync = new Lock();

		private static readonly Queue<string> RecentFingerprintOrder = new Queue<string>();

		private static readonly HashSet<string> RecentFingerprints = new HashSet<string>(StringComparer.Ordinal);

		private static bool _globalHandlersInitialized;

		internal static JsonObject BuildExceptionPayload(Exception exception)
		{
			return new JsonObject
			{
				["exception"] = BuildExceptionNode(exception),
				["framework_runtime"] = BuildFrameworkRuntimeNode()
			};
		}

		private static JsonObject BuildExceptionNode(Exception exception)
		{
			JsonObject jsonObject = new JsonObject
			{
				["type"] = exception.GetType().FullName ?? exception.GetType().Name,
				["message"] = exception.Message,
				["stack_trace"] = exception.StackTrace
			};
			if (exception.InnerException != null)
			{
				jsonObject["inner"] = BuildExceptionNode(exception.InnerException);
			}
			return jsonObject;
		}

		private static JsonObject BuildFrameworkRuntimeNode()
		{
			FrameworkRuntimeSnapshot frameworkRuntimeSnapshot = RitsuLibFramework.CaptureRuntimeSnapshot();
			return new JsonObject
			{
				["is_initialized"] = frameworkRuntimeSnapshot.IsInitialized,
				["is_active"] = frameworkRuntimeSnapshot.IsActive,
				["profile_services_initialized"] = frameworkRuntimeSnapshot.ProfileServicesInitialized,
				["has_registered_mod_settings"] = frameworkRuntimeSnapshot.HasRegisteredModSettings,
				["lifecycle_observer_count"] = frameworkRuntimeSnapshot.LifecycleObserverCount,
				["registered_script_assembly_count"] = frameworkRuntimeSnapshot.RegisteredScriptAssemblyCount,
				["patcher_areas"] = new JsonArray(new ReadOnlySpan<JsonNode>(((IEnumerable<JsonNode>)frameworkRuntimeSnapshot.PatcherAreas.Select((FrameworkPatcherSnapshot area) => new JsonObject
				{
					["area_name"] = area.AreaName,
					["is_registered"] = area.IsRegistered,
					["is_applied"] = area.IsApplied,
					["registered_patch_count"] = area.RegisteredPatchCount,
					["registered_dynamic_patch_count"] = area.RegisteredDynamicPatchCount,
					["applied_patch_count"] = area.AppliedPatchCount
				})).ToArray()))
			};
		}

		internal static void CaptureExceptionForAuthorizedApplicants(Exception exception, string source)
		{
			ArgumentNullException.ThrowIfNull(exception, "exception");
			ArgumentException.ThrowIfNullOrWhiteSpace(source, "source");
			try
			{
				if (!TryMarkRecent(exception, source))
				{
					return;
				}
				Dictionary<string, object> properties = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
				{
					["payload_kind"] = "exception",
					["capture_source"] = source,
					["exception_type"] = exception.GetType().FullName ?? exception.GetType().Name
				};
				List<string> list = new List<string>();
				foreach (TelemetryApplicant applicant in TelemetryRegistry.GetApplicants())
				{
					if (TelemetryRegistry.TryGetRequest(applicant, "diagnostics", out TelemetryRequest request) && TelemetryConsentStore.IsRequestGranted(applicant, request) && new TelemetryClient(applicant.ApplicantId).TryCaptureException(exception, properties))
					{
						list.Add(applicant.ApplicantId);
					}
				}
				RitsuLibFramework.Logger.Debug($"[Telemetry] Captured exception diagnostics from '{source}' for {list.Count} authorized applicant(s): {exception.GetType().Name}.", 1);
				foreach (string item in list)
				{
					TelemetryTaskRunner.Forget(TelemetryQueue.FlushApplicantAsync(item), "flush_applicant_after_diagnostics");
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Telemetry] Exception diagnostics capture failed: " + ex.Message, 1);
			}
		}

		internal static void InitializeGlobalExceptionHandlers()
		{
			using (Sync.EnterScope())
			{
				if (_globalHandlersInitialized)
				{
					return;
				}
				try
				{
					AppDomain.CurrentDomain.UnhandledException += OnUnhandledException;
					TaskScheduler.UnobservedTaskException += OnUnobservedTaskException;
					_globalHandlersInitialized = true;
				}
				catch
				{
					AppDomain.CurrentDomain.UnhandledException -= OnUnhandledException;
					TaskScheduler.UnobservedTaskException -= OnUnobservedTaskException;
					throw;
				}
			}
		}

		private static void OnUnhandledException(object sender, UnhandledExceptionEventArgs args)
		{
			if (args.ExceptionObject is Exception exception)
			{
				CaptureExceptionForAuthorizedApplicants(exception, "dotnet_unhandled_exception");
			}
		}

		private static void OnUnobservedTaskException(object? sender, UnobservedTaskExceptionEventArgs args)
		{
			CaptureExceptionForAuthorizedApplicants(args.Exception, "dotnet_unobserved_task_exception");
			args.SetObserved();
		}

		private static bool TryMarkRecent(Exception exception, string source)
		{
			string text = exception.StackTrace?.Split('\n').FirstOrDefault()?.Trim() ?? "";
			global::<>y__InlineArray4<string> buffer = default(global::<>y__InlineArray4<string>);
			buffer[0] = source;
			buffer[1] = exception.GetType().FullName ?? exception.GetType().Name;
			buffer[2] = exception.Message;
			buffer[3] = text;
			string item = string.Join("\n", (ReadOnlySpan<string?>)buffer);
			using (Sync.EnterScope())
			{
				if (!RecentFingerprints.Add(item))
				{
					return false;
				}
				RecentFingerprintOrder.Enqueue(item);
				while (RecentFingerprintOrder.Count > 128)
				{
					RecentFingerprints.Remove(RecentFingerprintOrder.Dequeue());
				}
				return true;
			}
		}
	}
	internal static class StateDivergenceTelemetryCollector
	{
		private sealed record StateDivergenceTelemetryCapture(JsonObject Payload, IReadOnlyDictionary<string, object?> Properties, int BundleByteCount);

		private const string EventName = "state_divergence.bundle";

		private const string RequestId = "state_divergence";

		private const string Source = "state_divergence";

		internal static void CaptureForAuthorizedApplicants(StateDivergenceDiagnosticReport report, string? bundlePath, string trigger)
		{
			ArgumentNullException.ThrowIfNull(report, "report");
			ArgumentException.ThrowIfNullOrWhiteSpace(trigger, "trigger");
			if (string.IsNullOrWhiteSpace(bundlePath) || !StateDivergenceLogBundleWriter.IsPublishedBundlePath(bundlePath))
			{
				return;
			}
			TelemetryCaptureContext context = new TelemetryCaptureContext("state_divergence.bundle", "state_divergence", TelemetryDataCategory.Diagnostics, "state_divergence");
			List<string> list = new List<string>();
			foreach (TelemetryApplicant applicant in TelemetryRegistry.GetApplicants())
			{
				if (TelemetryRegistry.TryGetRequest(applicant, "state_divergence", out TelemetryRequest request) && TelemetryConsentStore.IsRequestGranted(applicant, request) && TelemetryCaptureFilter.ShouldCapture(request, context, applicant.ApplicantId))
				{
					list.Add(applicant.ApplicantId);
				}
			}
			if (list.Count != 0)
			{
				TelemetryTaskRunner.Forget(CaptureAsync(report, bundlePath, trigger, context, list), "capture_state_divergence_bundle");
			}
		}

		private static async Task CaptureAsync(StateDivergenceDiagnosticReport report, string bundlePath, string trigger, TelemetryCaptureContext context, IReadOnlyList<string> applicantIds)
		{
			StateDivergenceTelemetryCapture capture = await Task.Run(() => BuildCapture(report, bundlePath, trigger)).ConfigureAwait(continueOnCapturedContext: false);
			int capturedCount = 0;
			foreach (string applicantId in applicantIds)
			{
				if (await new TelemetryClient(applicantId).TryCapturePayloadAsync("state_divergence.bundle", "state_divergence", capture.Payload, capture.Properties, context, filterAlreadyApplied: true).ConfigureAwait(continueOnCapturedContext: false))
				{
					capturedCount++;
				}
			}
			RitsuLibFramework.Logger.Info($"[Telemetry] Captured state divergence bundle for {capturedCount} authorized applicant(s); bytes={capture.BundleByteCount}.", 1);
		}

		private static StateDivergenceTelemetryCapture BuildCapture(StateDivergenceDiagnosticReport report, string bundlePath, string trigger)
		{
			byte[] array = StateDivergenceLogBundleWriter.BuildSanitizedSubmissionBundle(bundlePath);
			JsonObject payload = new JsonObject { ["bundle"] = new JsonObject
			{
				["file_name"] = "state-divergence-diagnostics.zip",
				["content_type"] = "application/zip",
				["content_encoding"] = "base64",
				["content"] = Convert.ToBase64String(array),
				["byte_count"] = array.Length
