		private static IReadOnlyList<string> ParseOrderText(string text)
		{
			try
			{
				string[] array = JsonSerializer.Deserialize<string[]>(text);
				if (array != null && array.Length > 0)
				{
					return NormalizeIds(array);
				}
			}
			catch
			{
			}
			return NormalizeIds(text.Split(new char[5] { '\r', '\n', ',', ';', '\t' }, StringSplitOptions.RemoveEmptyEntries));
		}

		private static IReadOnlyList<string> NormalizeIds(IEnumerable<string> ids)
		{
			List<string> list = new List<string>();
			list.AddRange((from id in ids
				select id.Trim() into id
				where !string.IsNullOrWhiteSpace(id)
				select id).Distinct<string>(StringComparer.Ordinal));
			return new <>z__ReadOnlyList<string>(list);
		}

		private static string FormatOrderPreview(IReadOnlyList<string> orderedIds)
		{
			if (orderedIds.Count == 0)
			{
				return L("ritsulib.contentModLoadOrder.preview.empty", "No relevant mods were found.");
			}
			Dictionary<string, string> namesById = ContentModLoadOrderInventory.BuildCurrentOrder().GroupBy<ContentModLoadOrderInventory.CurrentModEntry, string>((ContentModLoadOrderInventory.CurrentModEntry entry) => entry.Id, StringComparer.Ordinal).ToDictionary<IGrouping<string, ContentModLoadOrderInventory.CurrentModEntry>, string, string>((IGrouping<string, ContentModLoadOrderInventory.CurrentModEntry> group) => group.Key, (IGrouping<string, ContentModLoadOrderInventory.CurrentModEntry> group) => group.First().DisplayName, StringComparer.Ordinal);
			return string.Join('\n', orderedIds.Select(delegate(string id, int index)
			{
				string valueOrDefault = namesById.GetValueOrDefault(id, id);
				return string.Equals(valueOrDefault, id, StringComparison.Ordinal) ? $"{index + 1:00}. {id}" : $"{index + 1:00}. {valueOrDefault} ({id})";
			}));
		}

		private static string FormatLogOrder(IEnumerable<ContentModLoadOrderInventory.CurrentModEntry> entries)
		{
			return string.Join(", ", entries.Select((ContentModLoadOrderInventory.CurrentModEntry entry) => entry.Id));
		}

