		private void Submit(Func<Player, Player, RitsuDebugActionSubmission> action)
		{
			if (!TryResolvePlayers(out Player requester, out Player target))
			{
				ShowFailure(L("ritsulib.debugTools.localPlayerMissing", "The local or target player is unavailable."));
				return;
			}
			try
			{
				RitsuDebugActionSubmission ritsuDebugActionSubmission = action(requester, target);
				if (!ritsuDebugActionSubmission.Accepted)
				{
					ShowFailure(ritsuDebugActionSubmission.Message);
				}
				else
				{
					SetStatus(ritsuDebugActionSubmission.Message, failure: false);
				}
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn($"[DebugToolsUi] Floating intent action failed: {ex}", 1);
				ShowFailure(L("ritsulib.debugTools.requestFailed", "The requested change could not be submitted. See the game log for details."));
			}
		}

		private bool TryResolvePlayers(out Player requester, out Player target)
		{
			RunManager instance = RunManager.Instance;
			object obj;
			if (instance == null)
			{
				obj = null;
			}
			else
			{
				RunState obj2 = instance.DebugOnlyGetState();
				obj = ((obj2 != null) ? obj2.Players : null);
			}
			IReadOnlyList<Player> readOnlyList = (IReadOnlyList<Player>)obj;
			requester = readOnlyList?.FirstOrDefault((Player player) => player.NetId == _requesterNetId);
			target = readOnlyList?.FirstOrDefault((Player player) => player.NetId == _targetPlayerNetId);
			if (requester != null)
			{
				return target != null;
			}
			return false;
		}

		private void OnActionExecuted(RitsuDebugActionExecutionResult result)
		{
			if (result.TargetPlayerNetId == _targetPlayerNetId && RitsuDebugCombatActions.IsMonsterIntentActionFor(result, _combatId))
			{
				if (result.Success)
				{
					SetStatus(L("ritsulib.debugTools.changeApplied", "The requested change was applied."), failure: false);
				}
				else
				{
					ShowFailure(result.Message);
				}
				QueueRefresh();
			}
		}

		private void OnCombatStateChanged(CombatState _)
		{
			QueueRefresh();
		}

		private void OnCombatEnded(CombatRoom _)
		{
			QueueRefresh();
		}

		private void QueueRefresh()
		{
			//IL_0024: Unknown result type (might be due to invalid IL or missing references)
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			if (_refreshQueued || !((Node)this).IsInsideTree())
			{
				return;
			}
			_refreshQueued = true;
			Callable val = Callable.From((Action)delegate
			{
				_refreshQueued = false;
				if (((Node)this).IsInsideTree())
				{
					RefreshTarget();
