			});
			((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
		}

		private void RefreshTarget()
		{
			Creature val = RitsuDebugCombatActions.FindCreature(_combatId);
			_graph.Refresh(val);
			Label identity = _identity;
			string text;
			if (val != null)
			{
				string format = L("ritsulib.debugTools.intentWindowIdentity", "HP {0}/{1} · Block {2} · Current intent: {3}");
				global::<>y__InlineArray4<object> buffer = default(global::<>y__InlineArray4<object>);
				buffer[0] = val.CurrentHp;
				buffer[1] = val.MaxHp;
				buffer[2] = val.Block;
				buffer[3] = _graph.CurrentMoveTitle;
				text = string.Format(format, (ReadOnlySpan<object?>)buffer);
			}
			else
			{
				text = L("ritsulib.debugTools.intentTargetUnavailable", "The selected monster is no longer available.");
			}
			identity.Text = text;
			object obj;
			if (val == null)
			{
				obj = null;
			}
			else
			{
				MonsterModel monster = val.Monster;
				obj = ((monster != null) ? monster.MoveStateMachine : null);
			}
			bool flag = obj != null && !val.IsDead;
			if (!flag)
			{
				SetStatus(L("ritsulib.debugTools.intentTargetUnavailable", "The selected monster is no longer available."), failure: true);
			}
			else if (!_targetAvailable)
			{
				SetStatus(string.Empty, failure: false);
			}
			_targetAvailable = flag;
		}

		private void ShowFailure(string message)
		{
			SetStatus(message, failure: true);
			RitsuToastService.ShowWarning(message, L("ritsulib.debugTools.toastTitle", "Developer tools"));
		}

		private void SetStatus(string message, bool failure)
		{
			//IL_0058: Unknown result type (might be due to invalid IL or missing references)
			//IL_003d: Unknown result type (might be due to invalid IL or missing references)
			_status.Text = message;
			((CanvasItem)_status).Visible = !string.IsNullOrWhiteSpace(message);
			((Control)_status).AddThemeColorOverride(StringName.op_Implicit("font_color"), failure ? RitsuShellTheme.Current.Component.TextButton.Danger.Fg : RitsuShellTheme.Current.Text.LabelSecondary);
		}

		private static string L(string key, string fallback)
		{
			return ModSettingsLocalization.Get(key, fallback);
		}

