		private static string BuildTooltip(RitsuDebugStatePresetCard card)
		{
			List<string> list = new List<string>
			{
				card.CardId,
				$"×{card.Count}",
				L("ritsulib.debugTools.statePresets.dragCardHint", "Drag cards to reorder.")
			};
			if (card.UpgradeLevels > 0)
			{
				list.Add($"+{card.UpgradeLevels}");
			}
			if (card.BaseCost.HasValue)
			{
				list.Add(string.Format(L("ritsulib.debugTools.statePresets.tooltipCost", "Cost {0}"), card.BaseCost.Value));
			}
			if (card.ReplayCount.HasValue)
			{
				list.Add(string.Format(L("ritsulib.debugTools.statePresets.tooltipReplay", "Replay {0}"), card.ReplayCount.Value));
			}
			Dictionary<string, int> dynamicVars = card.DynamicVars;
			if (dynamicVars != null && dynamicVars.Count > 0)
			{
				list.Add(string.Join(", ", card.DynamicVars.Select<KeyValuePair<string, int>, string>((KeyValuePair<string, int> pair) => $"{pair.Key}={pair.Value}")));
			}
			return string.Join('\n', list);
		}

