		private static string CreateUniqueName(string requested)
		{
			HashSet<string> hashSet = (from preset in RitsuDebugStatePresetStore.GetSnapshot()
				select preset.Name).ToHashSet<string>(StringComparer.OrdinalIgnoreCase);
			string text = requested.Trim();
			if (text.Length == 0)
			{
				text = L("ritsulib.debugTools.statePresets.fallbackName", "Preset");
			}
			text = text.Substring(0, Math.Min(text.Length, 80));
			string text2 = text;
			int num = 2;
			while (hashSet.Contains(text2))
			{
				string text3 = $" {num}";
				text2 = text.Substring(0, Math.Min(text.Length, 80 - text3.Length)) + text3;
				num++;
			}
			return text2;
		}

