		private static string SafeTitle(AbstractModel model)
		{
			try
			{
				if (!model.TryResolveTitle(out LocString title))
				{
					return model.Id.Entry;
				}
				string text = title.GetFormattedText()?.Trim();
				return string.IsNullOrWhiteSpace(text) ? model.Id.Entry : text;
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				return model.Id.Entry;
			}
		}

