			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				return null;
			}
		}

		private unsafe static string PileLabel(PileType pileType)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0067: Unknown result type (might be due to invalid IL or missing references)
			if (ModCardPileRegistry.TryGetByPileType(pileType, out ModCardPileDefinition definition))
			{
				try
				{
					string text = definition.Title.GetFormattedText().Trim();
					return string.IsNullOrWhiteSpace(text) ? definition.Id : text;
				}
				catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
				{
					return definition.Id;
				}
			}
			return L($"ritsulib.debugTools.enum.PileType.{pileType}", ((object)(*(PileType*)(&pileType))/*cast due to constrained. prefix*/).ToString());
		}

