		private static string PresetSummary(RitsuDebugStatePreset preset)
		{
			List<string> list = new List<string>();
			if (preset.CardPiles.Count > 0)
			{
				list.Add(string.Format(L("ritsulib.debugTools.statePresets.summaryCards", "{0} cards"), preset.CardPiles.Sum((RitsuDebugStatePresetCardPile pile) => pile.Cards.Sum((RitsuDebugStatePresetCard card) => card.Count))));
			}
			if (preset.Relics != null)
			{
				list.Add(string.Format(L("ritsulib.debugTools.statePresets.summaryRelics", "{0} relics"), preset.Relics.ModelIds.Count));
			}
			if (preset.Potions != null)
			{
				list.Add(string.Format(L("ritsulib.debugTools.statePresets.summaryPotions", "{0} potions"), preset.Potions.Items.Count));
			}
			if (preset.Powers != null)
			{
				list.Add(string.Format(L("ritsulib.debugTools.statePresets.summaryPowers", "{0} powers"), preset.Powers.Items.Count));
			}
			if (preset.Player != null)
			{
				list.Add(L("ritsulib.debugTools.statePresets.summaryPlayer", "player values"));
			}
			Dictionary<string, int> secondaryResources = preset.SecondaryResources;
			if (secondaryResources != null && secondaryResources.Count > 0)
			{
				list.Add(string.Format(L("ritsulib.debugTools.statePresets.summarySecondaryResources", "{0} secondary resources"), secondaryResources.Count));
			}
			List<RitsuDebugStatePresetCapabilityTarget> capabilityTargets = preset.CapabilityTargets;
			if (capabilityTargets != null && capabilityTargets.Count > 0)
			{
				list.Add(string.Format(L("ritsulib.debugTools.statePresets.summaryCapabilities", "{0} capability targets"), capabilityTargets.Count));
			}
			if (list.Count != 0)
			{
				return string.Join(" · ", list);
			}
			return "—";
		}

