		private bool MovePresetCard(RitsuDebugStatePresetCardPile pile, int sourceIndex, int destinationIndex)
		{
			if (sourceIndex < 0 || sourceIndex >= pile.Cards.Count || destinationIndex < 0 || destinationIndex >= pile.Cards.Count || sourceIndex == destinationIndex)
			{
				return false;
			}
			RitsuDebugStatePresetCard item = pile.Cards[sourceIndex];
			pile.Cards.RemoveAt(sourceIndex);
			pile.Cards.Insert(destinationIndex, item);
			MarkDirty();
			_cardGrid?.SetCards(pile.Cards, destinationIndex);
			return true;
		}

