			AddCreatureOperationEditor(val, creature, RitsuDebugCreatureOperation.SetBlock, L("ritsulib.debugTools.field.block", "Block"), creature.Block.ToString(), 0, 999999999, L("ritsulib.debugTools.action.set", "Set"));
			((Node)ritsuDebugLiveDetailContainer).AddChild((Node)(object)AdjustmentSection(L("ritsulib.debugTools.action.creatureValues", "Creature values"), (Control)(object)val), false, (InternalMode)0);
			VBoxContainer val2 = CreateAdjustmentContent();
			List<(string, ModSettingsButtonTone, Action)> list = new List<(string, ModSettingsButtonTone, Action)> { (L("ritsulib.debugTools.action.fullHeal", "Restore full HP"), ModSettingsButtonTone.Accent, delegate
			{
				SubmitCreatureOperation(creature, RitsuDebugCreatureOperation.Heal, creature.MaxHp);
