			((Node)ritsuDebugLiveDetailContainer).AddChild((Node)(object)AdjustmentSection(L("ritsulib.debugTools.action.creatureActions", "Quick actions"), (Control)(object)val2), false, (InternalMode)0);
			if (creature != null && !creature.IsPlayer)
			{
