				if (monster != null && monster.MoveStateMachine != null)
				{
					AddMonsterIntentManager(ritsuDebugLiveDetailContainer, creature);
				}
			}
			AddCreaturePresetManager(ritsuDebugLiveDetailContainer, creature);
			AddCurrentPowerManager(ritsuDebugLiveDetailContainer, () => combatId, includePowerLibraryButton: true);
			List<(string, ModSettingsButtonTone, Action)> list2 = new List<(string, ModSettingsButtonTone, Action)>();
