						}
					}));
				}
				list2.Add((L("ritsulib.debugTools.action.defeatAllEnemies", "Defeat all enemies"), ModSettingsButtonTone.Danger, delegate
				{
					if (TryGetActionContext(out Player requester, out Player target))
