						string text = SafeDescription(delegate
						{
							LocString title = option.Title;
							return (title == null) ? null : title.GetFormattedText();
						});
						return (token: ancientOptionToken, string.IsNullOrWhiteSpace(text) ? ancientOptionToken : text);
					}).ToArray();
				}
				if (feedback.IsValid())
				{
					RitsuLibFramework.Logger.Warn($"[DebugToolsUi] Could not list options for '{((AbstractModel)val).Id}': " + feedback.GetEnglishText(), 1);
					AddHint((VBoxContainer)(object)ritsuDebugLiveDetailContainer, L("ritsulib.debugTools.ancientOptionsUnavailable", "Available options could not be determined for the selected player."));
				}
				if (array.Length != 0)
				{
					(string Value, string Label)[] selectableOptions = array;
					Control?[] optionFieldHolder = (Control?[])(object)new Control[1];
					ModSettingsToggleControl editor = ModSettingsUiControlTheming.CreateCompactStateToggle(initialValue: false, delegate(bool enabled)
					{
						ancientOption = (enabled ? selectableOptions[0].Value : null);
						if (optionFieldHolder[0] != null)
						{
							((CanvasItem)optionFieldHolder[0]).Visible = enabled;
						}
					});
					((Node)ritsuDebugLiveDetailContainer).AddChild((Node)(object)Field(L("ritsulib.debugTools.field.specifyAncientOption", "Specify option"), (Control)(object)editor), false, (InternalMode)0);
					Control val2 = DropdownField(L("ritsulib.debugTools.field.ancientOption", "Ancient option"), selectableOptions, selectableOptions[0].Value, delegate(string value)
					{
						ancientOption = value;
					});
					optionFieldHolder[0] = val2;
					((CanvasItem)val2).Hide();
					((Node)ritsuDebugLiveDetailContainer).AddChild((Node)(object)val2, false, (InternalMode)0);
				}
			}
			((Node)ritsuDebugLiveDetailContainer).AddChild((Node)(object)ActionButton(L("ritsulib.debugTools.action.enterEvent", "Enter event"), ModSettingsButtonTone.Danger, delegate
			{
				if (TryGetActionContext(out Player requester, out Player target2))
				{
					RunAction(() => RitsuDebugRunActions.SubmitEnterEvent(requester, target2, ((object)((AbstractModel)eventModel).Id).ToString(), ancientOption));
				}
			}), false, (InternalMode)0);
			return (Control)(object)ritsuDebugLiveDetailContainer;
		}

