			Player target2 = GetPlayers().FirstOrDefault((Player player) => player.NetId == targetNetId);
			if (target2 == null)
			{
				SetStatus(L("ritsulib.debugTools.targetChanged", "The selected target is no longer available."), error: true);
				return;
			}
			RunAction(() => action(requester, target2));
		}

		private void AddPotionDiscardButtons(VBoxContainer root, Player player)
		{
			(int, PotionModel)[] array = (from index in Enumerable.Range(0, player.MaxPotionCount)
				select (Index: index, Potion: player.GetPotionAtSlotIndex(index)) into tuple
				where tuple.Potion != null
				select tuple).ToArray();
			if (array.Length == 0)
			{
				return;
			}
			(int, PotionModel)[] array2 = array;
			for (int num = 0; num < array2.Length; num++)
			{
				(int Index, PotionModel Potion) entry = array2[num];
				PotionModel potion = entry.Potion;
				((Node)root).AddChild((Node)(object)ActionButton($"#{entry.Index + 1} · {SafeTitle((AbstractModel)(object)potion)}", ModSettingsButtonTone.Danger, delegate
				{
					SubmitTargetedAction(player.NetId, (Player requester, Player target) => RitsuDebugInventoryActions.SubmitDiscardPotion(requester, target, entry.Index, ((object)((AbstractModel)potion).Id).ToString()));
				}), false, (InternalMode)0);
			}
		}

