		private void RefreshCapabilityEditor(CapabilityEditorBinding binding)
		{
			if (GodotObject.IsInstanceValid((GodotObject)(object)binding.Content))
			{
				int capabilityStateHash = GetCapabilityStateHash(binding.Model);
				if (binding.StateHash != capabilityStateHash)
				{
					binding.StateHash = capabilityStateHash;
					RebuildCapabilityEditor(binding.Content, binding.Target, binding.Model);
				}
			}
		}

		private Control CreateCapabilitySection(RitsuDebugCapabilityTarget target, AbstractModel model, string? title, out VBoxContainer content)
		{
			content = CreateAdjustmentContent();
			RebuildCapabilityEditor(content, target, model);
			return AdjustmentSection(title ?? L("ritsulib.debugTools.capabilities.section", "Capabilities"), (Control)(object)content, RitsuDebugToolsGlyph.Puzzle);
		}

		private static bool CanManageCapabilities(AbstractModel model)
		{
			if (SafeGetCapabilities(model).Count <= 0)
			{
				return ModelCapabilityRegistry.GetRegistrationsSnapshot().Any((ModelCapabilityRegistration registration) => ModelCapabilityRegistry.IsCompatibleWith(registration.CapabilityType, model));
			}
			return true;
		}

		private void RebuildCapabilityEditor(VBoxContainer content, RitsuDebugCapabilityTarget target, AbstractModel model)
		{
			//IL_0181: Unknown result type (might be due to invalid IL or missing references)
			foreach (Node child in ((Node)content).GetChildren(false))
			{
				((Node)content).RemoveChild(child);
				child.QueueFree();
			}
			IReadOnlyList<IModelCapability> readOnlyList = SafeGetCapabilities(model);
			if (readOnlyList.Count == 0)
			{
				AddHint(content, L("ritsulib.debugTools.capabilities.noneAttached", "This model has no attached capabilities."));
			}
			else
			{
				foreach (CapabilityDisplayRow item in CreateCapabilityDisplayRows(readOnlyList))
				{
					((Node)content).AddChild((Node)(object)CreateCapabilityRow(target, item.Capability, item.Index, item.Count, item.StateText), false, (InternalMode)0);
