			}
			ModelCapabilityRegistration[] array = (from registration in ModelCapabilityRegistry.GetRegistrationsSnapshot()
				where ModelCapabilityRegistry.IsCompatibleWith(registration.CapabilityType, model)
				select registration).ToArray();
			if (array.Length != 0)
