		private static string CreatureDetailDescription(Creature creature)
		{
			Player owner = creature.PetOwner;
			if (owner == null)
			{
				return creature.LogName;
			}
			int num = Array.FindIndex(GetPlayers(), (Player player) => player.NetId == owner.NetId);
			string arg = ((num >= 0) ? PlayerLabel(owner, num) : ((object)((AbstractModel)owner.Character).Id).ToString());
			return string.Format(L("ritsulib.debugTools.petOwnerDetail", "Owner: {0} · {1}"), arg, creature.LogName);
		}

