		internal bool SelectPage(string pageId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(pageId, "pageId");
			RitsuDebugToolsPageView ritsuDebugToolsPageView = _pages.FirstOrDefault((RitsuDebugToolsPageView page) => page.Id.Equals(pageId, StringComparison.OrdinalIgnoreCase));
			if (ritsuDebugToolsPageView == null)
			{
				return false;
			}
			bool flag = !_contextualPageSelection && ResetBuiltInCatalogMode(ritsuDebugToolsPageView.Id);
			if (CurrentPageId.Equals(ritsuDebugToolsPageView.Id, StringComparison.OrdinalIgnoreCase))
			{
				if (flag)
				{
					RebuildBrowser();
				}
				return true;
			}
			CurrentPageId = ritsuDebugToolsPageView.Id;
			RefreshHeaderTarget();
			RebuildBrowser();
			PageChanged?.Invoke(ritsuDebugToolsPageView);
			return true;
		}

		private bool ResetBuiltInCatalogMode(string pageId)
		{
			if (pageId.Equals("com.ritsukage.sts2-RitsuLib:relics", StringComparison.OrdinalIgnoreCase))
			{
				bool result = _relicCatalogMode != RelicCatalogMode.Library;
				_relicCatalogMode = RelicCatalogMode.Library;
				return result;
			}
			if (pageId.Equals("com.ritsukage.sts2-RitsuLib:potions", StringComparison.OrdinalIgnoreCase))
			{
				bool result2 = _potionCatalogMode != PotionCatalogMode.Library;
				_potionCatalogMode = PotionCatalogMode.Library;
				return result2;
			}
			if (!pageId.Equals("com.ritsukage.sts2-RitsuLib:powers", StringComparison.OrdinalIgnoreCase))
			{
				return false;
			}
			bool result3 = _powerCatalogMode != PowerCatalogMode.Library;
			_powerCatalogMode = PowerCatalogMode.Library;
			return result3;
		}

		private void RefreshAll()
		{
			Player[] players = GetPlayers();
			if (players.All((Player player) => player.NetId != _targetPlayerNetId))
			{
				Player? obj = players.FirstOrDefault();
				_targetPlayerNetId = ((obj != null) ? new ulong?(obj.NetId) : ((ulong?)null));
			}
			UpdateTargetDropdown(players, force: true);
			RefreshPages();
			RebuildBrowser();
		}

		private void RefreshPages()
		{
			RitsuDebugToolsPageContext context = CreatePageContext();
			List<RitsuDebugToolsPageView> list = new List<RitsuDebugToolsPageView>(16);
			AddBuiltInPages(list);
			foreach (RitsuDebugToolsPageDefinition definition in RitsuDebugToolsPageRegistry.GetPages())
			{
				if (IsExternalPageVisible(definition, context))
				{
					string title = ResolveExternalPageTitle(definition);
					Texture2D icon = ResolveExternalPageIcon(definition);
					list.Add(new RitsuDebugToolsPageView(definition.QualifiedId, title, definition.SortOrder, definition.PreferredWidthFraction, icon, () => CreateExternalPage(definition)));
				}
			}
			_pages = list.OrderBy((RitsuDebugToolsPageView page) => page.SortOrder).ThenBy<RitsuDebugToolsPageView, string>((RitsuDebugToolsPageView page) => page.Id, StringComparer.OrdinalIgnoreCase).ToArray();
			if (_pages.All((RitsuDebugToolsPageView page) => !page.Id.Equals(CurrentPageId, StringComparison.OrdinalIgnoreCase)))
			{
				CurrentPageId = _pages.FirstOrDefault()?.Id ?? string.Empty;
			}
			RefreshHeaderTarget();
			PagesChanged?.Invoke(Array.AsReadOnly(_pages));
			RitsuDebugToolsPageView currentPage = GetCurrentPage();
			if (currentPage != null)
			{
				PageChanged?.Invoke(currentPage);
			}
		}

