		private void RebuildBrowser()
		{
			if (_browserHost == null)
			{
				return;
			}
			if (_currentBrowser != null && GodotObject.IsInstanceValid((GodotObject)(object)_currentBrowser))
			{
				if ((object)((Node)_currentBrowser).GetParent() == _browserHost)
				{
					((Node)_browserHost).RemoveChild((Node)(object)_currentBrowser);
				}
				((Node)_currentBrowser).QueueFree();
			}
			_currentBrowser = CreateBrowser();
			((Node)_browserHost).AddChild((Node)(object)_currentBrowser, false, (InternalMode)0);
			_currentBrowser.SetAnchorsAndOffsetsPreset((LayoutPreset)15, (LayoutPresetMode)0, 0);
		}

		private Control CreateBrowser()
		{
			if (!RitsuLibSettingsStore.AreDeveloperToolsEnabled())
			{
				return (Control)(object)EmptyBrowser(L("ritsulib.debugTools.disabled", "Enable developer tools in RitsuLib settings before opening this workspace."));
			}
			if (ResolvedModelCache.Phase < ContentRegistryPhase.Resolved)
			{
				return (Control)(object)EmptyBrowser(L("ritsulib.debugTools.notAvailableYet", "RitsuLib developer tools are not available yet. Try again after the current screen finishes loading."));
			}
			return (Control)(((object)GetCurrentPage()?.ContentFactory()) ?? ((object)EmptyBrowser(L("ritsulib.debugTools.noMatches", "No matching items"))));
		}

