		private Control CreateSecondaryResourceCatalog()
		{
			if (!TryGetTargetPlayer(out Player target) || !HasActiveCombatState(target))
			{
				return (Control)(object)EmptyBrowser(L("ritsulib.debugTools.empty.secondaryResourcesCombat", "Start a combat to inspect and change secondary resources."));
			}
			SecondaryResourceDefinition[] definitionsSnapshot = ModSecondaryResourceRegistry.GetDefinitionsSnapshot();
			if (definitionsSnapshot.Length == 0)
			{
				return (Control)(object)EmptyBrowser(L("ritsulib.debugTools.empty.secondaryResources", "No mods have registered secondary resources."));
			}
			Dictionary<string, SecondaryResourceDefinition> byId = definitionsSnapshot.ToDictionary<SecondaryResourceDefinition, string>((SecondaryResourceDefinition definition) => definition.Id, StringComparer.Ordinal);
			Dictionary<string, ContentSourceDescriptor> sourceByItemId = definitionsSnapshot.ToDictionary<SecondaryResourceDefinition, string, ContentSourceDescriptor>((SecondaryResourceDefinition definition) => definition.Id, (SecondaryResourceDefinition definition) => new ContentSourceDescriptor(definition.ModId, definition.ModId), StringComparer.Ordinal);
			RitsuCatalogBrowser ritsuCatalogBrowser = Browser(L("ritsulib.debugTools.search.secondaryResources", "Search secondary resources by name, owner, or ID"), (RitsuCatalogItem item) => CreateSecondaryResourceDetail(byId[item.Id]), new <>z__ReadOnlySingleElementList<RitsuCatalogFilter>(CreateContentSourceFilter(sourceByItemId.Values, (RitsuCatalogItem item) => (!sourceByItemId.TryGetValue(item.Id, out var value)) ? ((ContentSourceDescriptor?)null) : new ContentSourceDescriptor?(value))), RitsuCatalogPresentation.List, 112f, 104f, RitsuCatalogDetailPresentation.Drawer, 260f, 520f);
			ritsuCatalogBrowser.SetItems(CreateSecondaryResourceItems(target, definitionsSnapshot));
			return (Control)(object)ritsuCatalogBrowser;
		}

		private RitsuCatalogItem[] CreateSecondaryResourceItems(Player target, IEnumerable<SecondaryResourceDefinition> definitions)
		{
			return (from definition in definitions.OrderBy<SecondaryResourceDefinition, string>(SecondaryResourceTitle, StringComparer.CurrentCultureIgnoreCase)
				select CreateSecondaryResourceItem(target, definition)).ToArray();
		}

		private RitsuCatalogItem CreateSecondaryResourceItem(Player target, SecondaryResourceDefinition definition)
		{
			int amount = SecondaryResourceCmd.Get(target, definition.Id);
			int? max = SecondaryResourceCmd.GetMax(target, definition.Id);
			return new RitsuCatalogItem(definition.Id, SecondaryResourceTitle(definition), string.Format(L("ritsulib.debugTools.secondaryResource.owner", "Owner: {0}"), definition.ModId), $"{definition.Id} {definition.ModId} {definition.LocalId}", null, SecondaryResourceAmountText(amount, max), () => SecondaryResourceIcon(definition));
		}

		private Control CreateSecondaryResourceDetail(SecondaryResourceDefinition definition)
		{
			//IL_013e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0148: Expected O, but got Unknown
			if (!TryGetTargetPlayer(out Player target) || !HasActiveCombatState(target))
			{
				return (Control)(object)EmptyBrowser(L("ritsulib.debugTools.empty.secondaryResourcesCombat", "Start a combat to inspect and change secondary resources."));
			}
			RitsuDebugLiveDetailContainer ritsuDebugLiveDetailContainer = DetailShell(definition.Id, () => SecondaryResourceIcon(definition), SecondaryResourceMetadata(target, definition), SecondaryResourceDescription(target, definition), () => (!TryGetTargetPlayer(out Player target2)) ? SecondaryResourceTitle(definition) : SecondaryResourceMetadata(target2, definition), () => (!TryGetTargetPlayer(out Player target2)) ? string.Empty : SecondaryResourceDescription(target2, definition));
			VBoxContainer val = CreateAdjustmentContent();
			AddIntegerActionRow(val, L("ritsulib.debugTools.secondaryResource.gainAmount", "Gain"), "1", 1, int.MaxValue, delegate(int value)
			{
				SubmitSecondaryResource(definition, RitsuDebugSecondaryResourceOperation.Gain, value);
			}, L("ritsulib.debugTools.action.gain", "Gain"));
			AddIntegerActionRow(val, L("ritsulib.debugTools.secondaryResource.loseAmount", "Lose"), "1", 1, int.MaxValue, delegate(int value)
			{
				SubmitSecondaryResource(definition, RitsuDebugSecondaryResourceOperation.Lose, value);
			}, L("ritsulib.debugTools.action.lose", "Lose"));
			LineEdit setAmount = CreateIntegerEdit(SecondaryResourceCmd.Get(target, definition.Id).ToString());
			bool setAmountChanged = false;
			setAmount.TextChanged += (TextChangedEventHandler)delegate
			{
				setAmountChanged = true;
			};
			((Node)val).AddChild((Node)(object)ActionField(L("ritsulib.debugTools.secondaryResource.setAmount", "Set amount"), (Control)(object)setAmount, ActionButton(L("ritsulib.debugTools.action.set", "Set"), ModSettingsButtonTone.Accent, delegate
			{
				if (TryReadInt(setAmount, definition.MinAmount, definition.HardMaxAmount, out var value))
				{
					SubmitSecondaryResource(definition, RitsuDebugSecondaryResourceOperation.Set, value);
				}
			})), false, (InternalMode)0);
			ritsuDebugLiveDetailContainer.RegisterRefresh(delegate
			{
				if (!setAmountChanged && !((Control)setAmount).HasFocus() && TryGetTargetPlayer(out Player target2))
				{
					setAmount.Text = SecondaryResourceCmd.Get(target2, definition.Id).ToString();
					setAmountChanged = false;
				}
			});
			List<(string, ModSettingsButtonTone, Action)> list = new List<(string, ModSettingsButtonTone, Action)> { (L("ritsulib.debugTools.action.resetDefault", "Reset to default"), ModSettingsButtonTone.Normal, delegate
			{
				SubmitSecondaryResource(definition, RitsuDebugSecondaryResourceOperation.Reset);
			}) };
			if (SecondaryResourceCmd.GetMax(target, definition.Id).HasValue)
			{
				list.Add((L("ritsulib.debugTools.action.resetMaximum", "Reset to maximum"), ModSettingsButtonTone.Normal, delegate
				{
					SubmitSecondaryResource(definition, RitsuDebugSecondaryResourceOperation.ResetToMax);
				}));
			}
			((Node)val).AddChild((Node)(object)ActionGrid(list), false, (InternalMode)0);
			((Node)ritsuDebugLiveDetailContainer).AddChild((Node)(object)AdjustmentSection(L("ritsulib.debugTools.secondaryResource.change", "Change amount"), (Control)(object)val), false, (InternalMode)0);
			return (Control)(object)ritsuDebugLiveDetailContainer;
		}

		private void SubmitSecondaryResource(SecondaryResourceDefinition definition, RitsuDebugSecondaryResourceOperation operation, int value = 0)
		{
			if (TryGetActionContext(out Player requester, out Player target))
			{
				RunAction(() => RitsuDebugSecondaryResourceActions.Submit(requester, target, definition.Id, operation, value));
			}
		}

		private static string SecondaryResourceMetadata(Player target, SecondaryResourceDefinition definition)
		{
			int amount = SecondaryResourceCmd.Get(target, definition.Id);
			int? max = SecondaryResourceCmd.GetMax(target, definition.Id);
			string value = (max.HasValue ? string.Format(L("ritsulib.debugTools.secondaryResource.boundsWithMaximum", "Range {0}–{1} · Current max {2}"), definition.MinAmount, definition.HardMaxAmount, max.Value) : string.Format(L("ritsulib.debugTools.secondaryResource.bounds", "Range {0}–{1} · No current max"), definition.MinAmount, definition.HardMaxAmount));
			return $"{SecondaryResourceTitle(definition)} · {SecondaryResourceAmountText(amount, max)}\n{value}";
		}

		private static string SecondaryResourceDescription(Player target, SecondaryResourceDefinition definition)
		{
			try
			{
				int amount = SecondaryResourceCmd.Get(target, definition.Id);
				int? max = SecondaryResourceCmd.GetMax(target, definition.Id);
				LocString? description = SecondaryResourceText.GetDescription(definition, amount, max);
				return ((description != null) ? description.GetFormattedText() : null) ?? definition.EffectiveDescriptionKey;
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				return definition.EffectiveDescriptionKey;
			}
		}

		private static string SecondaryResourceTitle(SecondaryResourceDefinition definition)
		{
			try
			{
				return SecondaryResourceText.GetTitleText(definition);
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				return definition.Id;
			}
		}

		private static string SecondaryResourceAmountText(int amount, int? maximum)
		{
			if (!maximum.HasValue)
			{
				return amount.ToString();
			}
			return string.Format(L("ritsulib.debugTools.secondaryResource.amountWithMaximum", "{0}/{1}"), amount, maximum.Value);
		}

		private static Texture2D? SecondaryResourceIcon(SecondaryResourceDefinition definition)
		{
			//IL_00c2: Unknown result type (might be due to invalid IL or missing references)
			string text = definition.LargeIconPath ?? definition.SmallIconPath;
			if (!string.IsNullOrWhiteSpace(text))
			{
				try
				{
					Texture2D val = ResourceLoader.Load<Texture2D>(text.Trim(), (string)null, (CacheMode)1);
					if (val != null)
					{
						return val;
					}
				}
				catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
				{
					RitsuLibFramework.Logger.Warn($"[DebugToolsUi] Could not load secondary-resource icon '{text}' for '{definition.Id}': {ex.Message}", 1);
				}
			}
			return (Texture2D?)(object)RitsuDebugToolsIcons.Get(RitsuDebugToolsGlyph.Sliders, 32, RitsuShellTheme.Current.Text.LabelPrimary);
		}

