			private void PrepareSearchResults(RitsuSteamWorkshopSearchResult result)
			{
				//IL_0153: Unknown result type (might be due to invalid IL or missing references)
				if (!SteamWorkshopManager.Instance.IsAvailable)
				{
					_searchList?.SetItems(Array.Empty<RitsuSteamWorkshopItem>());
					SetSearchPagination(null, canPrevious: false, canNext: false);
					SetSearchStatus(L("ritsulib.steamWorkshopManagement.status.unavailable", "Steam Workshop is not available in this session."), warning: true);
					return;
				}
				if (!SteamWorkshopManager.Instance.IsSearchAvailable)
				{
					LineEdit? searchEdit = _searchEdit;
					if (!SteamWorkshopManager.TryExtractWorkshopItemId(((searchEdit != null) ? searchEdit.Text : null) ?? string.Empty, out var _))
					{
						_searchList?.SetItems(Array.Empty<RitsuSteamWorkshopItem>());
						SetSearchPagination(null, canPrevious: false, canNext: false);
						SetSearchStatus(L("ritsulib.steamWorkshopManagement.search.unavailable", "Workshop text search is not available with the current Steamworks runtime."), warning: true);
						return;
					}
				}
				_searchPage = result.Page;
				_searchHasPreviousPage = result.HasPreviousPage;
				_searchHasNextPage = result.HasNextPage;
				SetSearchPagination(result, result.HasPreviousPage, result.HasNextPage);
				SetSearchStatus(FormatSearchResultStatus(result), warning: false);
				if (result.Items.Count == 0)
				{
					_searchList?.SetItems(Array.Empty<RitsuSteamWorkshopItem>());
					_searchList?.SetMessage(L("ritsulib.steamWorkshopManagement.search.noResults", "No Workshop items were found."));
					return;
				}
				_searchList?.SetMessage(null);
				ScrollContainer? searchScroll = _searchScroll;
				if (searchScroll != null)
				{
					((GodotObject)searchScroll).SetDeferred(PropertyName.ScrollVertical, Variant.op_Implicit(0));
				}
				_searchList?.SetItems(result.Items);
			}

			private static string FormatSearchResultStatus(RitsuSteamWorkshopSearchResult result)
			{
				uint? totalMatchingResults = result.TotalMatchingResults;
				if (totalMatchingResults.HasValue)
				{
					uint valueOrDefault = totalMatchingResults.GetValueOrDefault();
					uint num = ((result.Items.Count != 0) ? ((result.Page - 1) * result.PageSize + 1) : 0u);
					uint num2 = ((num != 0) ? ((uint)((int)num + result.Items.Count - 1)) : 0u);
					return string.Format(L("ritsulib.steamWorkshopManagement.search.countPaged", "Search results: {0}-{1} of {2}"), num, num2, valueOrDefault);
				}
				return string.Format(L("ritsulib.steamWorkshopManagement.search.countPagedUnknownTotal", "Search results: page {0}, {1} item(s)"), result.Page, result.Items.Count);
			}

