			private void SubscribeFromInput()
			{
				LineEdit? searchEdit = _searchEdit;
				if (!SteamWorkshopManager.TryExtractWorkshopItemId(((searchEdit == null) ? null : searchEdit.Text?.Trim()) ?? string.Empty, out var itemId))
				{
					SetSearchStatus(L("ritsulib.steamWorkshopManagement.status.invalidId", "Enter a positive numeric Workshop item id or Steam Workshop link."), warning: true);
				}
				else if (SteamWorkshopUpdateCoordinator.SubscribeItemFromUi(itemId).Accepted)
				{
					RefreshSubscribedItemsDelayed();
				}
			}

			private void RefreshSubscribedItems()
			{
				if (_subscribedContentBuilt)
				{
					int generation = ++_refreshGeneration;
					_subscribedList?.SetMessage(null);
					_subscribedList?.SetItems(Array.Empty<RitsuSteamWorkshopItem>());
					SetSubscribedStatus(L("ritsulib.steamWorkshopManagement.status.loading", "Loading Workshop items..."), warning: false);
					RefreshSubscribedItemsAsync(generation);
				}
			}

			private async Task RefreshSubscribedItemsAsync(int generation)
			{
				try
				{
					IReadOnlyList<RitsuSteamWorkshopItem> cachedItems = await SteamWorkshopManager.Instance.ListSubscribedItemsFromCacheAsync().ConfigureAwait(continueOnCapturedContext: false);
					Post(delegate
					{
						if (generation == _refreshGeneration)
						{
							PrepareSubscribedItems(cachedItems);
						}
					});
					IReadOnlyList<RitsuSteamWorkshopItem> items = await SteamWorkshopManager.Instance.ListSubscribedItemsAsync().ConfigureAwait(continueOnCapturedContext: false);
					Post(delegate
					{
						if (generation == _refreshGeneration)
						{
							PrepareSubscribedItems(items);
						}
					});
				}
				catch (Exception ex)
				{
					Exception ex2 = ex;
					Exception ex3 = ex2;
					Post(delegate
					{
						if (generation == _refreshGeneration)
						{
							SetSubscribedStatus(string.Format(L("ritsulib.steamWorkshopManagement.status.failed", "Could not read Workshop subscriptions: {0}"), ex3.Message), warning: true);
						}
					});
				}
			}

			private void PrepareSubscribedItems(IReadOnlyList<RitsuSteamWorkshopItem> items)
			{
				_subscribedItems = items;
				if (!SteamWorkshopManager.Instance.IsAvailable)
				{
					_subscribedList?.SetItems(Array.Empty<RitsuSteamWorkshopItem>());
					SetSubscribedStatus(L("ritsulib.steamWorkshopManagement.status.unavailable", "Steam Workshop is not available in this session."), warning: true);
					return;
				}
				SetSubscribedStatus(string.Format(L("ritsulib.steamWorkshopManagement.status.count", "Subscribed Workshop items: {0}"), items.Count), warning: false);
				if (items.Count == 0)
				{
					_subscribedList?.SetItems(Array.Empty<RitsuSteamWorkshopItem>());
					_subscribedList?.SetMessage(L("ritsulib.steamWorkshopManagement.empty", "No subscribed Workshop items were found."));
				}
				else
				{
					_subscribedList?.SetMessage(null);
					_subscribedList?.SetItems(items);
				}
			}

			private void CopySubscribedItems()
			{
				ulong[] array = (from item in _subscribedItems
					select item.Id into id
					where id != 0
					select id).Distinct().ToArray();
				if (array.Length == 0)
				{
					RitsuToastService.ShowWarning(L("ritsulib.steamWorkshopManagement.copy.empty", "No loaded Workshop subscriptions are available to copy."), L("ritsulib.steamWorkshop.toast.title", "Steam Workshop updates"));
					return;
				}
				DisplayServer.ClipboardSet(SteamWorkshopManager.FormatWorkshopItemIdList(array));
				ModSettingsClipboardAccess.InvalidateCache();
				RitsuToastService.ShowInfo(string.Format(L("ritsulib.steamWorkshopManagement.copy.done", "Copied {0} Workshop item id(s) to the clipboard."), array.Length), L("ritsulib.steamWorkshop.toast.title", "Steam Workshop updates"));
			}

			private void ImportSubscribedItemsFromClipboard()
			{
				if (!ModSettingsClipboardAccess.TryGetText(out string text) || string.IsNullOrWhiteSpace(text))
				{
					RitsuToastService.ShowWarning(L("ritsulib.steamWorkshopManagement.import.clipboardEmpty", "Clipboard is empty or unavailable."), L("ritsulib.steamWorkshop.toast.title", "Steam Workshop updates"));
				}
				else if (!SteamWorkshopImportDialog.Show(text, (Node?)(object)this, RefreshSubscribedItemsDelayed))
				{
					RitsuToastService.ShowWarning(L("ritsulib.steamWorkshopManagement.import.noIds", "Clipboard does not contain any Workshop item ids."), L("ritsulib.steamWorkshop.toast.title", "Steam Workshop updates"));
				}
			}

			private void OnOpenItem(RitsuSteamWorkshopItem item)
			{
				SteamWorkshopManager.Instance.TryOpenWorkshopPage(item.Id);
			}

			private void OnToggleSubscription(RitsuSteamWorkshopItem item)
			{
				if ((item.IsSubscribed ? SteamWorkshopUpdateCoordinator.UnsubscribeItemFromUi(item.Id, item.DisplayName) : SteamWorkshopUpdateCoordinator.SubscribeItemFromUi(item.Id, item.DisplayName)).Accepted)
				{
					RefreshSubscribedItemsDelayed();
				}
			}

			private void RefreshSubscribedItemsDelayed()
			{
				RefreshSubscribedItemsDelayedAsync();
			}

			private async Task RefreshSubscribedItemsDelayedAsync()
			{
				await Task.Delay(1200).ConfigureAwait(continueOnCapturedContext: false);
				Post(RefreshSubscribedItems);
			}

