		private static void RegisterCategorySettingsPages(RitsuLibModSettingsUiBindings ui)
		{
			RegisterCoreSettingsPage(ui);
			RegisterCompatibilitySettingsPage(ui);
			RegisterUpdateSettingsPage(ui);
			RegisterCloudSettingsPage(ui);
			RegisterDeveloperToolsSettingsPage(ui);
		}

		private static void RegisterCoreSettingsPage(RitsuLibModSettingsUiBindings ui)
		{
			RitsuLibFramework.RegisterModSettings("com.ritsukage.sts2-RitsuLib", delegate(ModSettingsPageBuilder page)
			{
				page.AsChildOf("com.ritsukage.sts2-RitsuLib").WithSortOrder(-990).WithTitle(T("ritsulib.category.core.label", "Core settings"))
					.WithDescription(T("ritsulib.category.core.description", "Interface theme and main menu shortcut."))
					.AddSection("core", delegate(ModSettingsSectionBuilder section)
					{
						ConfigureCoreSettingsSection(section, ui);
					});
			}, "core");
		}

		private static void ConfigureCoreSettingsSection(ModSettingsSectionBuilder section, RitsuLibModSettingsUiBindings ui)
		{
			section.WithTitle(T("ritsulib.category.core.label", "Core settings"));
			ModSettingsText label = T("ritsulib.uiShellTheme.label", "Interface theme");
			IModSettingsValueBinding<string> uiShellThemeId = ui.UiShellThemeId;
			List<ModSettingsChoiceOption<string>> list = new List<ModSettingsChoiceOption<string>>();
			list.AddRange(RitsuShellThemeCatalog.RegisteredThemeIds.Select((string id) => new ModSettingsChoiceOption<string>(id, T("ritsulib.uiShellTheme.option." + id, id))));
			section.AddChoice("ui_shell_theme_id", label, uiShellThemeId, new <>z__ReadOnlyList<ModSettingsChoiceOption<string>>(list), T("ritsulib.uiShellTheme.description", "Applies a built-in color theme to the Ritsu settings UI shell (sidebars, rows, and modals)."), ModSettingsChoicePresentation.Dropdown);
			section.AddKeyBinding("settings_open_hotkey", T("ritsulib.settings.hotkey.label", "Open mod settings"), ui.SettingsOpenHotkey, allowModifierCombos: true, allowModifierOnly: false, distinguishModifierSides: false, T("ritsulib.settings.hotkey.description", "Opens the independent mod settings center from anywhere in the game."));
			section.AddButton("ui_shell_theme_reset_file", T("ritsulib.uiShellTheme.resetFile.label", "Reset existing theme files"), T("ritsulib.uiShellTheme.resetFile.button", "Reset theme files"), TryResetExistingThemeFiles, ModSettingsButtonTone.Normal, T("ritsulib.uiShellTheme.resetFile.description", "Overwrite existing built-in theme files on disk with their embedded default versions."));
			section.AddChoice("canvas_texture_filter_mode", T("ritsulib.canvasTextureFilter.label", "2D texture filtering"), ui.CanvasTextureFilterMode, new global::<>z__ReadOnlyArray<ModSettingsChoiceOption<string>>(new ModSettingsChoiceOption<string>[4]
			{
				new ModSettingsChoiceOption<string>("nearest", T("ritsulib.canvasTextureFilter.option.nearest", "Nearest")),
				new ModSettingsChoiceOption<string>("linear", T("ritsulib.canvasTextureFilter.option.linear", "Linear")),
				new ModSettingsChoiceOption<string>("nearest_mipmap", T("ritsulib.canvasTextureFilter.option.nearestMipmap", "Nearest with mipmaps")),
				new ModSettingsChoiceOption<string>("linear_mipmap", T("ritsulib.canvasTextureFilter.option.linearMipmap", "Linear with mipmaps"))
			}), T("ritsulib.canvasTextureFilter.description", "Sets the default filter inherited by 2D canvas items. Mipmap modes use mip levels when the texture contains them."), ModSettingsChoicePresentation.Dropdown);
			section.AddToggle("main_menu_mod_settings_button_enabled", T("ritsulib.mainMenuModSettingsButton.enabled.label", "Show main menu settings shortcut"), ui.MainMenuModSettingsButtonEnabled, T("ritsulib.mainMenuModSettingsButton.enabled.description", "Shows a RitsuLib settings shortcut under the patch notes button on the main menu."));
		}

		private static void RegisterCompatibilitySettingsPage(RitsuLibModSettingsUiBindings ui)
		{
			RitsuLibFramework.RegisterModSettings("com.ritsukage.sts2-RitsuLib", delegate(ModSettingsPageBuilder page)
			{
				page.AsChildOf("com.ritsukage.sts2-RitsuLib").WithSortOrder(-700).WithTitle(T("ritsulib.category.compatibility.label", "Compatibility fallbacks"))
					.WithDescription(T("ritsulib.category.compatibility.description", "Debug compatibility mode and fallback shims."))
					.AddSection("debug_compatibility", delegate(ModSettingsSectionBuilder section)
					{
						section.WithTitle(T("ritsulib.debugCompatibility.label", "Debug compatibility mode")).AddToggle("debug_compatibility_mode", T("ritsulib.debugCompatibility.label", "Debug compatibility mode"), ui.DebugCompatibility, T("ritsulib.debugCompatibility.description", "Enable compatibility fallbacks for localization, unlock, and The Architect dialogue edge cases. Per-feature toggles default to on."));
					})
					.AddSection("debug_compat_shims", delegate(ModSettingsSectionBuilder section)
					{
						section.WithVisibleWhen(RitsuLibSettingsStore.IsDebugCompatibilityMasterEnabled).WithTitle(T("ritsulib.section.debugCompatShims.title", "Compatibility fallbacks")).Collapsible()
							.AddToggle("debug_compat_loc_table", T("ritsulib.debugCompatLocTable.label", "LocTable missing keys"), ui.DebugCompatLocTable, T("ritsulib.debugCompatLocTable.description", "Resolve missing keys to placeholder LocString values and log one [Localization][DebugCompat] warning per key."))
							.AddToggle("debug_compat_unlock_epoch", T("ritsulib.debugCompatUnlockEpoch.label", "Invalid epoch grants"), ui.DebugCompatUnlockEpoch, T("ritsulib.debugCompatUnlockEpoch.description", "Skip invalid epoch grants on RitsuLib-registered unlock paths and log one [Unlocks][DebugCompat] warning per stable key."))
							.AddToggle("debug_compat_ancient_architect", T("ritsulib.debugCompatAncientArchitect.label", "The Architect missing dialogue"), ui.DebugCompatAncientArchitect, T("ritsulib.debugCompatAncientArchitect.description", "Inject a dialogue entry with no lines when The Architect has no vanilla dialogue for a ModContentRegistry character."));
					});
			}, "compatibility");
		}

		private static void RegisterUpdateSettingsPage(RitsuLibModSettingsUiBindings ui)
		{
			RitsuLibFramework.RegisterModSettings("com.ritsukage.sts2-RitsuLib", delegate(ModSettingsPageBuilder page)
			{
				page.AsChildOf("com.ritsukage.sts2-RitsuLib").WithSortOrder(-600).WithTitle(CreateUpdatesCategoryTitle())
					.WithDescription(T("ritsulib.category.updates.description", "RitsuLib and Steam Workshop update checks."))
					.AddSection("steam_workshop_updates", delegate(ModSettingsSectionBuilder section)
					{
						section.WithVisibleWhen(SteamWorkshopUpdateCoordinator.CanUseSteamWorkshopUpdates).WithTitle(T("ritsulib.section.steamWorkshopUpdates.title", "Steam Workshop updates")).Collapsible()
							.AddSubpage("steam_workshop_management_open", T("ritsulib.steamWorkshopManagement.pageLink.label", "Steam Workshop management"), "steam-workshop-management", T("button.open", "Open"), T("ritsulib.steamWorkshopManagement.pageLink.description", "Subscribe, unsubscribe, and inspect Workshop item states."))
							.AddToggle("steam_workshop_auto_update_check_enabled", T("ritsulib.steamWorkshop.autoUpdateCheck.label", "Auto-check Workshop updates"), ui.SteamWorkshopAutoUpdateCheckEnabled, T("ritsulib.steamWorkshop.autoUpdateCheck.description", "Periodically checks subscribed Workshop items and asks Steam to queue available updates. Notifications are shown on the main menu."))
							.AddButton("steam_workshop_check_now", T("ritsulib.steamWorkshop.checkNow.label", "Check Workshop updates now"), T("ritsulib.steamWorkshop.checkNow.button", "Check Workshop"), SteamWorkshopUpdateCoordinator.CheckNowFromSettings, ModSettingsButtonTone.Normal, T("ritsulib.steamWorkshop.checkNow.description", "Checks subscribed Workshop item states immediately and asks Steam to download any items with available updates."));
					})
					.AddSection("ritsulib_updates", delegate(ModSettingsSectionBuilder section)
					{
						section.WithTitle(T("ritsulib.section.updateChecks.title", "RitsuLib updates")).Collapsible().AddToggle("update_check_enabled", T("ritsulib.updateCheck.enabled.label", "Check for RitsuLib updates"), ui.UpdateCheckEnabled, T("ritsulib.updateCheck.enabled.description", "Checks for RitsuLib updates periodically. Update notifications are shown on the main menu."))
							.AddSlider("update_check_interval_minutes", T("ritsulib.updateCheck.interval.label", "Automatic check interval (minutes)"), ui.UpdateCheckIntervalMinutes, 5.0, 360.0, 5.0, (double value) => value.ToString("0"), T("ritsulib.updateCheck.interval.description", "Controls how often automatic RitsuLib, Workshop, and registered mod update checks run."))
							.AddToggle("update_check_skip_in_combat", T("ritsulib.updateCheck.skipInCombat.label", "Defer automatic checks in combat rooms"), ui.UpdateCheckSkipInCombat, T("ritsulib.updateCheck.skipInCombat.description", "When enabled, automatic update checks pause while the run is in a combat room and resume after leaving it."))
							.AddButton("update_check_now", T("ritsulib.updateCheck.now.label", "Check now"), T("ritsulib.updateCheck.now.button", "Check for updates"), RitsuLibUpdateCheckService.CheckNowFromSettings, ModSettingsButtonTone.Normal, T("ritsulib.updateCheck.now.description", "Checks the bundled RitsuLib update source immediately and shows a toast with the result."));
					});
			}, "updates");
		}

		private static ModSettingsText CreateUpdatesCategoryTitle()
		{
			return ModSettingsText.Dynamic(() => (!SteamWorkshopUpdateCoordinator.CanUseSteamWorkshopUpdates()) ? L("ritsulib.category.updates.label", "Updates") : L("ritsulib.category.updatesWithWorkshop.label", "Updates & Workshop"));
		}

		private static void RegisterCloudSettingsPage(RitsuLibModSettingsUiBindings ui)
		{
