		private static void TryOpenDebugToolsWorkspace()
		{
			if (!RitsuOverlayHostService.TryOpenDebugTools(out string message))
			{
				RitsuToastService.ShowWarning(message, L("ritsulib.debugTools.toastTitle", "Developer tools"));
			}
		}

