			AddToggle("potions", "Potions", ui.ModSourceHoverTipsPotions);
			AddToggle("powers", "Powers", ui.ModSourceHoverTipsPowers);
			AddToggle("orbs", "Orbs", ui.ModSourceHoverTipsOrbs);
