			}
		}

		internal static void Initialize()
		{
			using (InitLock.EnterScope())
			{
				if (!_initialized)
				{
					RitsuLibModSettingsUiBindings ui = RitsuLibModSettingsUiBindings.Create();
					RegisterMainSettingsPage(ui);
					RegisterCategorySettingsPages(ui);
					RegisterSearchSettingsPage(ui);
					RegisterContentSourceHoverTipsPage(ui);
					RegisterContentModLoadOrderPage();
					RegisterSteamWorkshopManagementPage();
					RegisterToastSettingsPage(ui);
					RegisterDebugLogViewerPage(ui);
					RegisterHarmonySelfCheckAndCompendiumPages(ui);
					RegisterImagePngExportPage(ui);
					RefreshDynamicPages();
					RegisterDebugShowcasePage(ui);
					_initialized = true;
				}
			}
		}

		internal static void EnsureFrameworkPagesRegistered()
		{
			if (ModSettingsRegistry.TryGetPage("com.ritsukage.sts2-RitsuLib", "com.ritsukage.sts2-RitsuLib", out ModSettingsPage page))
			{
				return;
			}
			using (InitLock.EnterScope())
			{
				if (!ModSettingsRegistry.TryGetPage("com.ritsukage.sts2-RitsuLib", "com.ritsukage.sts2-RitsuLib", out page))
				{
					RitsuLibModSettingsUiBindings ui = RitsuLibModSettingsUiBindings.Create();
					RegisterMainSettingsPage(ui);
					RegisterCategorySettingsPages(ui);
					RegisterSearchSettingsPage(ui);
					RegisterContentSourceHoverTipsPage(ui);
					RegisterContentModLoadOrderPage();
					RegisterSteamWorkshopManagementPage();
					RegisterToastSettingsPage(ui);
					RegisterDebugLogViewerPage(ui);
					RegisterHarmonySelfCheckAndCompendiumPages(ui);
					RegisterImagePngExportPage(ui);
					RefreshDynamicPages();
					RegisterDebugShowcasePage(ui);
					_initialized = true;
				}
			}
		}

		internal static void RefreshDynamicPages()
		{
			RitsuLibFramework.RegisterModSettings("com.ritsukage.sts2-RitsuLib", delegate(ModSettingsPageBuilder page)
			{
				ConfigureRuntimeHotkeysPage(page, RuntimeHotkeyCategoryOrder);
			}, "runtime-hotkeys");
		}

