		private static ModSettingsChoiceOption<string>[] CreateShowcaseThousandItemDropdownOptions()
		{
			ModSettingsChoiceOption<string>[] array = new ModSettingsChoiceOption<string>[1000];
			for (int i = 0; i < array.Length; i++)
			{
				int value = i + 1;
				array[i] = new ModSettingsChoiceOption<string>($"preview_dd_{i}", ModSettingsText.Literal($"Large list item {value}"));
			}
			return array;
		}

