		private static string BuildRandomToastBody(int actionCount)
		{
			string text = string.Format(L("ritsulib.showcase.toast.body", "Queue and layout test entry from the control preview page. Count: {0}."), actionCount);
			int num = Random.Shared.Next(0, 5);
			if (num == 0)
			{
				return text;
			}
			string text2 = L("ritsulib.showcase.toast.bodyChunk", "Overflow probe sentence for wrapping and height checks.");
			StringBuilder stringBuilder = new StringBuilder(text.Length + (text2.Length + 1) * num);
			stringBuilder.Append(text);
			for (int i = 0; i < num; i++)
			{
				stringBuilder.Append(' ');
				stringBuilder.Append(text2);
			}
			return stringBuilder.ToString();
		}

