		private static void RequestPinyinInitialization(IModSettingsUiActionHost host)
		{
			PinyinSearchDataSource current = PinyinSearchDataSource.Current;
			ShowPinyinConfirmation(host, L("ritsulib.searchExtensions.pinyin.initialize.dialog.title", "Initialize Mandarin pinyin?"), string.Format(L("ritsulib.searchExtensions.pinyin.initialize.dialog.body", "Download {1} of official Unicode {0} data to enable pinyin search?"), current.UnicodeVersion, FormatBytes(current.ExpectedLength)), L("ritsulib.searchExtensions.pinyin.initialize.dialog.confirm", "Download and enable"), confirmIsDanger: false, delegate
			{
				RunPinyinOperation(host, (CancellationToken token) => PinyinSearchDataManager.DownloadAndInstallAsync(force: false, token), delegate
				{
					RitsuSearchSettingsStore.SetProviderEnabled("ritsulib.pinyin", enabled: true);
				});
			});
		}

