		private static void ShowPinyinConfirmation(IModSettingsUiActionHost host, string title, string body, string confirmText, bool confirmIsDanger, Action onConfirm)
		{
			if (!(host is ModSettingsUiContext modSettingsUiContext))
			{
				RitsuLibFramework.Logger.Warn("[Search/Pinyin] Settings confirmation has no compatible UI host.", 1);
			}
			else
			{
				ModSettingsUiFactory.ShowStyledConfirm(modSettingsUiContext.ModalHost, title, body, L("button.cancel", "Cancel"), confirmText, confirmIsDanger, onConfirm);
			}
		}

		private static async void RunPinyinOperation(IModSettingsUiActionHost host, Func<CancellationToken, Task> operation, Action? onSuccess = null)
		{
			ArgumentNullException.ThrowIfNull(host, "host");
			ArgumentNullException.ThrowIfNull(operation, "operation");
			if (PinyinSearchDataManager.GetStatus().IsBusy)
			{
				return;
			}
			try
			{
				host.RequestRefresh();
				await PinyinSearchOperationRunner.RunAsync(() => operation(CancellationToken.None), onSuccess, host.RequestRefresh);
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[Search/Pinyin] Settings operation failed: " + ex.Message, 1);
			}
			finally
			{
				host.RequestRefresh();
			}
		}

		private static bool HasPinyinCache()
		{
			PinyinSearchDataStatus status = PinyinSearchDataManager.GetStatus();
			if (PinyinSearchDataManager.Data == null && status.CacheBytes <= 0)
			{
				return status.SourceArchiveCached;
			}
			return true;
		}

		private static string FormatPinyinStatus()
		{
			PinyinSearchDataStatus status = PinyinSearchDataManager.GetStatus();
			object obj = status.State switch
			{
				PinyinSearchDataState.NotInstalled => L("ritsulib.searchExtensions.status.notInstalled", "Not set up"), 
				PinyinSearchDataState.Loading => L("ritsulib.searchExtensions.status.loading", "Loading"), 
				PinyinSearchDataState.Downloading => string.Format(L("ritsulib.searchExtensions.status.downloading", "Downloading: {0} / {1}"), FormatBytes(status.BytesReceived), FormatBytes(status.TotalBytes)), 
				PinyinSearchDataState.Generating => L("ritsulib.searchExtensions.status.generating", "Finishing setup"), 
				PinyinSearchDataState.Ready => L("ritsulib.searchExtensions.status.ready", "Ready"), 
				PinyinSearchDataState.Failed => string.Format(L("ritsulib.searchExtensions.status.failed", "Unavailable: {0}"), status.Error ?? L("ritsulib.searchExtensions.status.unknownError", "unknown error")), 
				_ => status.State.ToString(), 
			};
			string text = ((PinyinSearchDataManager.Data != null && RitsuSearchSettingsStore.IsProviderEnabled("ritsulib.pinyin", defaultValue: false)) ? L("ritsulib.searchExtensions.status.searchEnabled", "Enabled") : L("ritsulib.searchExtensions.status.searchDisabled", "Disabled"));
			return (string?)obj + "\n" + text;
		}

		private static string FormatPinyinSource()
		{
			PinyinSearchDataSource current = PinyinSearchDataSource.Current;
			return string.Format(L("ritsulib.searchExtensions.source.description", "Unicode {0} · Unihan.zip · {1}\n{2} · Integrity checked automatically"), current.UnicodeVersion, FormatBytes(current.ExpectedLength), current.SourceUri.Host);
		}

		private static string FormatBytes(long bytes)
		{
			if (bytes >= 1024)
			{
				if (bytes < 1048576)
				{
					return $"{(double)bytes / 1024.0:F1} KiB";
				}
				return $"{(double)bytes / 1048576.0:F1} MiB";
			}
			return $"{bytes} B";
		}

		private static ModSettingsPageBuilder ConfigureRuntimeHotkeysPage(ModSettingsPageBuilder page, IReadOnlyList<string> categoryOrder)
		{
			page.AsChildOf("com.ritsukage.sts2-RitsuLib").WithSortOrder(-175).WithMenuCapabilities(ModSettingsMenuCapabilities.Copy)
				.WithTitle(T("ritsulib.page.runtimeHotkeys.title", "Registered hotkeys"))
				.WithDescription(T("ritsulib.page.runtimeHotkeys.description", "Inspect currently registered runtime hotkeys and their active bindings."))
				.AddSection("runtime_hotkeys_overview", delegate(ModSettingsSectionBuilder section)
				{
					section.WithMenuCapabilities(ModSettingsMenuCapabilities.Copy).WithTitle(T("ritsulib.section.runtimeHotkeys.title", "Runtime hotkeys")).WithDescription(T("ritsulib.section.runtimeHotkeys.description", "Lists active runtime hotkey registrations grouped by category."))
						.AddParagraph("runtime_hotkeys_summary", ModSettingsText.Dynamic(delegate
						{
							IReadOnlyList<RuntimeHotkeyRegistrationInfo> registeredHotkeys = RuntimeHotkeyService.GetRegisteredHotkeys();
							return (registeredHotkeys.Count != 0) ? string.Format(L("ritsulib.runtimeHotkeys.summary", "{0} runtime hotkeys are currently registered."), registeredHotkeys.Count) : L("ritsulib.runtimeHotkeys.empty", "No runtime hotkeys are currently registered.");
						}))
						.AddParagraph("runtime_hotkeys_intro", T("ritsulib.runtimeHotkeys.groups.description", "Each entry shows the current binding, display name, optional description, and registration id."));
				});
			List<RuntimeHotkeyCategoryGroup> orderedRuntimeHotkeyGroups = GetOrderedRuntimeHotkeyGroups(categoryOrder);
			if (orderedRuntimeHotkeyGroups.Count == 0)
			{
				page.AddSection("runtime_hotkeys_empty", delegate(ModSettingsSectionBuilder section)
				{
					section.WithMenuCapabilities(ModSettingsMenuCapabilities.Copy).WithTitle(T("ritsulib.section.runtimeHotkeys.empty.title", "No registered hotkeys")).AddParagraph("runtime_hotkeys_empty_text", T("ritsulib.runtimeHotkeys.empty", "No runtime hotkeys are currently registered."));
				});
				return page;
			}
			foreach (RuntimeHotkeyCategoryGroup item in orderedRuntimeHotkeyGroups)
			{
				string category;
				List<RuntimeHotkeyRegistrationInfo> runtimeHotkeyRegistrationInfos;
				(category, runtimeHotkeyRegistrationInfos) = item;
				string id = "runtime_hotkeys_group_" + SanitizeRuntimeHotkeySectionId(category);
				page.AddSection(id, delegate(ModSettingsSectionBuilder section)
				{
					section.WithMenuCapabilities(ModSettingsMenuCapabilities.Copy).WithTitle(ModSettingsText.Literal(category)).WithDescription(ModSettingsText.Dynamic(() => string.Format(L("ritsulib.runtimeHotkeys.groupSummary", "{0} hotkeys in this category."), CountRuntimeHotkeysInCategory(category))))
						.Collapsible(startCollapsed: true);
					for (int num = 0; num < runtimeHotkeyRegistrationInfos.Count; num++)
					{
						RuntimeHotkeyRegistrationInfo hotkey = runtimeHotkeyRegistrationInfos[num];
						string text2 = $"{num}_{SanitizeRuntimeHotkeySectionId(GetRuntimeHotkeyStableKey(hotkey))}";
						section.AddRuntimeHotkeySummary(text2 + "_card", ModSettingsText.Dynamic(() => GetRuntimeHotkeyCardTitle(hotkey)), ModSettingsText.Dynamic(() => FormatRuntimeHotkeyDetails(hotkey.Id, hotkey.CurrentBinding, hotkey.DisplayName)), GetRuntimeHotkeyBindingTexts(hotkey));
					}
				});
			}
			return page;
		}

		private static List<RuntimeHotkeyCategoryGroup> GetOrderedRuntimeHotkeyGroups(IReadOnlyList<string> categoryOrder)
		{
			return (from @group in (from info in RuntimeHotkeyService.GetRegisteredHotkeys()
					group info by (!string.IsNullOrWhiteSpace(info.Category)) ? info.Category : L("ritsulib.runtimeHotkeys.category.other", "Other")).OrderBy(delegate(IGrouping<string, RuntimeHotkeyRegistrationInfo> @group)
				{
					int num = -1;
					for (int i = 0; i < categoryOrder.Count; i++)
					{
						if (string.Equals(categoryOrder[i], @group.Key, StringComparison.Ordinal))
						{
							num = i;
							break;
						}
					}
					return (num >= 0) ? num : int.MaxValue;
				}).ThenBy<IGrouping<string, RuntimeHotkeyRegistrationInfo>, string>((IGrouping<string, RuntimeHotkeyRegistrationInfo> @group) => @group.Key, StringComparer.OrdinalIgnoreCase)
				select new RuntimeHotkeyCategoryGroup(@group.Key, @group.OrderBy<RuntimeHotkeyRegistrationInfo, string>((RuntimeHotkeyRegistrationInfo info) => info.DisplayName ?? info.Id ?? info.CurrentBinding, StringComparer.OrdinalIgnoreCase).ToList())).ToList();
		}

		private static int CountRuntimeHotkeysInCategory(string category)
		{
			return RuntimeHotkeyService.GetRegisteredHotkeys().Count((RuntimeHotkeyRegistrationInfo info) => string.Equals(string.IsNullOrWhiteSpace(info.Category) ? L("ritsulib.runtimeHotkeys.category.other", "Other") : info.Category, category, StringComparison.Ordinal));
		}

		private static string GetRuntimeHotkeyCardTitle(RuntimeHotkeyRegistrationInfo hotkey)
		{
			RuntimeHotkeyRegistrationInfo runtimeHotkeyRegistrationInfo = FindRuntimeHotkey(hotkey.Id, hotkey.CurrentBinding, hotkey.DisplayName);
			object obj;
			if ((object)runtimeHotkeyRegistrationInfo == null)
			{
				obj = hotkey.DisplayName;
				if (obj == null)
				{
					obj = hotkey.Id;
					if (obj == null)
					{
						return hotkey.CurrentBinding;
					}
				}
			}
			else
			{
				obj = runtimeHotkeyRegistrationInfo.DisplayName ?? runtimeHotkeyRegistrationInfo.Id ?? runtimeHotkeyRegistrationInfo.CurrentBinding;
			}
			return (string)obj;
		}

		private static IReadOnlyList<ModSettingsText> GetRuntimeHotkeyBindingTexts(RuntimeHotkeyRegistrationInfo hotkey)
		{
			List<ModSettingsText> list = new List<ModSettingsText>();
			list.AddRange(hotkey.CurrentBindings.Select((string binding) => ModSettingsText.Dynamic(() => FormatRuntimeHotkeyBindingChip(hotkey.Id, binding, hotkey.DisplayName))));
			return new <>z__ReadOnlyList<ModSettingsText>(list);
		}

		private static string GetRuntimeHotkeyStableKey(RuntimeHotkeyRegistrationInfo hotkey)
		{
			return hotkey.Id ?? hotkey.DisplayName ?? hotkey.CurrentBinding;
		}

		private static string FormatRuntimeHotkeyBindingChip(string? id, string binding, string? displayName)
		{
			return binding;
		}

		private static string FormatRuntimeHotkeyDetails(string? id, string binding, string? displayName)
		{
			RuntimeHotkeyRegistrationInfo runtimeHotkeyRegistrationInfo = FindRuntimeHotkey(id, binding, displayName);
			if (runtimeHotkeyRegistrationInfo == null)
			{
				return string.Empty;
			}
			List<string> list = new List<string>();
			if (!string.IsNullOrWhiteSpace(runtimeHotkeyRegistrationInfo.Description))
			{
				list.Add(runtimeHotkeyRegistrationInfo.Description);
			}
			if (!string.IsNullOrWhiteSpace(runtimeHotkeyRegistrationInfo.Purpose))
			{
				list.Add(string.Format(L("ritsulib.runtimeHotkeys.purposeLine", "Purpose: {0}"), runtimeHotkeyRegistrationInfo.Purpose));
			}
			if (!string.IsNullOrWhiteSpace(runtimeHotkeyRegistrationInfo.Id))
			{
				list.Add(string.Format(L("ritsulib.runtimeHotkeys.idLine", "Id: {0}"), runtimeHotkeyRegistrationInfo.Id));
			}
			return string.Join("\n", list);
		}

		private static RuntimeHotkeyRegistrationInfo? FindRuntimeHotkey(string? id, string binding, string? displayName)
		{
			IReadOnlyList<RuntimeHotkeyRegistrationInfo> registeredHotkeys = RuntimeHotkeyService.GetRegisteredHotkeys();
			if (!string.IsNullOrWhiteSpace(id))
			{
				foreach (RuntimeHotkeyRegistrationInfo item in registeredHotkeys)
				{
					if (string.Equals(item.Id, id, StringComparison.Ordinal))
					{
						return item;
					}
				}
			}
			foreach (RuntimeHotkeyRegistrationInfo item2 in registeredHotkeys)
			{
				if (string.Equals(item2.CurrentBinding, binding, StringComparison.Ordinal) && string.Equals(item2.DisplayName, displayName, StringComparison.Ordinal))
				{
					return item2;
				}
			}
			return registeredHotkeys.FirstOrDefault((RuntimeHotkeyRegistrationInfo info) => string.Equals(info.CurrentBinding, binding, StringComparison.Ordinal));
		}

		private static string SanitizeRuntimeHotkeySectionId(string? value)
		{
			if (string.IsNullOrWhiteSpace(value))
			{
				return "other";
			}
			string text = new string(value.Select((char ch) => (!char.IsLetterOrDigit(ch)) ? '_' : char.ToLowerInvariant(ch)).ToArray()).Trim('_');
			if (!string.IsNullOrWhiteSpace(text))
			{
				return text;
			}
			return "other";
		}

