		private static bool HasAdditionalSearchProviders()
		{
			return RitsuSearchExpansionRegistry.GetProviderSnapshots().Any((RitsuSearchExpansionRegistry.ProviderSnapshot provider) => !string.Equals(provider.Id, "ritsulib.pinyin", StringComparison.OrdinalIgnoreCase));
		}

		private static Control CreateAdditionalProviderControls(IModSettingsUiActionHost host)
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			//IL_001b: Expected O, but got Unknown
			VBoxContainer val = new VBoxContainer
			{
				SizeFlagsHorizontal = (SizeFlags)3
			};
			((Control)val).AddThemeConstantOverride(StringName.op_Implicit("separation"), 8);
			foreach (RitsuSearchExpansionRegistry.ProviderSnapshot provider in from providerSnapshot in RitsuSearchExpansionRegistry.GetProviderSnapshots()
				where !string.Equals(providerSnapshot.Id, "ritsulib.pinyin", StringComparison.OrdinalIgnoreCase)
				select providerSnapshot)
			{
