								new ModSettingsChoiceOption<string>("topright", T("ritsulib.toast.anchor.topright", "Top Right")),
								new ModSettingsChoiceOption<string>("middleleft", T("ritsulib.toast.anchor.middleleft", "Middle Left")),
								new ModSettingsChoiceOption<string>("middlecenter", T("ritsulib.toast.anchor.middlecenter", "Middle Center")),
								new ModSettingsChoiceOption<string>("middleright", T("ritsulib.toast.anchor.middleright", "Middle Right")),
								new ModSettingsChoiceOption<string>("bottomleft", T("ritsulib.toast.anchor.bottomleft", "Bottom Left")),
								new ModSettingsChoiceOption<string>("bottomcenter", T("ritsulib.toast.anchor.bottomcenter", "Bottom Center")),
								new ModSettingsChoiceOption<string>("bottomright", T("ritsulib.toast.anchor.bottomright", "Bottom Right"))
