		internal static bool Show(string workshopItemIdText, Node? attachParent = null, Action? onSubscriptionsChanged = null)
		{
			IReadOnlyList<ulong> readOnlyList = SteamWorkshopManager.ParseWorkshopItemIds(workshopItemIdText);
			if (readOnlyList.Count == 0)
