		private async Task LoadItemsAsync()
		{
			IReadOnlyList<RitsuSteamWorkshopItem> items = Array.Empty<RitsuSteamWorkshopItem>();
			string error = null;
			try
			{
				items = await SteamWorkshopManager.Instance.QueryItemsAsync(_itemIds).ConfigureAwait(continueOnCapturedContext: false);
			}
			catch (Exception ex)
			{
				error = ex.Message;
			}
			Callable val = Callable.From((Action)delegate
			{
				if (((Node)this).IsInsideTree())
				{
					_itemsById.Clear();
					foreach (RitsuSteamWorkshopItem item in items)
					{
						if (item.Id != 0L)
						{
							_itemsById[item.Id] = item;
						}
					}
					RebuildRows();
					if (error == null)
					{
						UpdateSelectionStatus();
					}
					else
					{
						SetStatus(string.Format(L("ritsulib.steamWorkshopManagement.import.detailsFailed", "Could not load Workshop details: {0}. Showing item ids only."), error), warning: true);
					}
				}
			});
			((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
		}

		private void RebuildRows()
		{
			//IL_0062: Unknown result type (might be due to invalid IL or missing references)
			//IL_0067: Unknown result type (might be due to invalid IL or missing references)
			if (_itemCanvas != null)
			{
				RitsuSteamWorkshopItem[] items = (from itemId in _itemIds
					select _itemsById.GetValueOrDefault(itemId) ?? CreatePlaceholderItem(itemId) into item
					orderby item.Id
					select item).ToArray();
				_itemCanvas.SetItems(items);
				Callable val = Callable.From((Action)GrabInitialFocus);
				((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			}
		}

		private void SubscribeSelected()
		{
			if (_submitting)
			{
				return;
			}
			RitsuSteamWorkshopItem[] array = _itemCanvas?.GetSelectedItems() ?? Array.Empty<RitsuSteamWorkshopItem>();
			if (array.Length == 0)
			{
				SetStatus(L("ritsulib.steamWorkshopManagement.import.noneSelected", "Select at least one Workshop item to subscribe."), warning: true);
				return;
			}
			_submitting = true;
			if (_confirmButton != null)
			{
				((BaseButton)_confirmButton).Disabled = true;
			}
			if (array.Select((RitsuSteamWorkshopItem item) => SteamWorkshopUpdateCoordinator.SubscribeItemFromUi(item.Id, item.DisplayName)).Count((RitsuSteamWorkshopActionResult result) => result.Accepted) == 0)
			{
				_submitting = false;
				if (_confirmButton != null)
				{
					((BaseButton)_confirmButton).Disabled = false;
				}
				SetStatus(L("ritsulib.steamWorkshopManagement.import.noneAccepted", "Steam did not accept any subscription requests."), warning: true);
			}
			else
			{
				_onSubscriptionsChanged?.Invoke();
				CloseDialog();
			}
		}

		private void UpdateSelectionStatus()
		{
			int num = _itemCanvas?.SelectedCount ?? _itemIds.Count;
			int num2 = _itemCanvas?.PendingCount ?? 0;
			WorkshopImportItemCanvas itemCanvas = _itemCanvas;
			if (itemCanvas != null && itemCanvas.TotalCount > 0 && num2 == 0)
			{
				SetStatus(L("ritsulib.steamWorkshopManagement.import.allSubscribed", "All imported Workshop items are already subscribed."), warning: false);
				_confirmButton?.Configure(L("ritsulib.steamWorkshopManagement.import.allSubscribedButton", "All subscribed"), ModSettingsButtonTone.Normal, null);
				if (_confirmButton != null)
				{
					((BaseButton)_confirmButton).Disabled = true;
				}
			}
			else
			{
				if (_confirmButton != null && !_submitting)
				{
					((BaseButton)_confirmButton).Disabled = false;
				}
				SetStatus(string.Format(L("ritsulib.steamWorkshopManagement.import.previewCount", "Previewing {0} Workshop item(s). Selected for subscription: {1}."), _itemIds.Count, num), warning: false);
			}
		}

