	/// <summary>
	///     <para xml:lang="en">
	///         Provides embedded JSON localization for the mod settings UI and resolves mod and page display names.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为模组设置界面提供嵌入式 JSON 本地化，并解析模组和页面的显示名称。
	///     </para>
	/// </summary>
	internal static class ModSettingsLocalization
	{
		private static readonly Lazy<I18N> InstanceFactory = new Lazy<I18N>(() => new I18N("RitsuLib-ModSettings", null, new string[1] { "STS2RitsuLib.Settings.Localization.ModSettingsUi" }, null, Assembly.GetExecutingAssembly()));

		public static I18N Instance => InstanceFactory.Value;

		public static string Get(string key, string fallback)
		{
			return Instance.Get(key, fallback);
		}

		public static ModSettingsText Text(string key, string fallback)
		{
			return ModSettingsText.DeferredI18N(() => Instance, key, fallback);
		}

		public static string ResolveModName(string modId, string fallback)
		{
			string text = ModSettingsRegistry.GetModDisplayName(modId)?.Resolve();
			if (!string.IsNullOrWhiteSpace(text))
			{
				return text;
			}
			return Sts2ModManagerCompat.EnumerateModsForManifestLookup().FirstOrDefault((Mod mod) => string.Equals(mod.manifest?.id, modId, StringComparison.OrdinalIgnoreCase))?.manifest?.name ?? fallback;
		}

		public static string ResolveModNameFallback(string modId, string fallback)
		{
			string text = ModSettingsRegistry.GetModDisplayName(modId)?.FallbackText;
			if (!string.IsNullOrWhiteSpace(text))
			{
				return text;
			}
			return Sts2ModManagerCompat.EnumerateModsForManifestLookup().FirstOrDefault((Mod mod) => string.Equals(mod.manifest?.id, modId, StringComparison.OrdinalIgnoreCase))?.manifest?.name ?? fallback;
		}

		public static string ResolvePageDisplayName(ModSettingsPage page)
		{
			string text = page.Title?.Resolve();
			if (string.IsNullOrWhiteSpace(text))
			{
				return page.Id;
			}
			return text;
		}
	}
	internal static class RitsuLibEasterEggLocalization
	{
		private static readonly Lazy<I18N> InstanceFactory = new Lazy<I18N>(() => new I18N("RitsuLib-EasterEggs", null, new string[1] { "STS2RitsuLib.Settings.Localization.EasterEggs" }, null, Assembly.GetExecutingAssembly()));

		public static string Get(string key, string fallback)
		{
			return InstanceFactory.Value.Get(key, fallback);
		}
	}
