		internal static void ApplyEnabledRecursive(Node node, object gate, bool enabled)
		{
			Control val = (Control)(object)((node is Control) ? node : null);
			if (val != null)
			{
				ApplyEnabledToControl(val, gate, enabled);
			}
			foreach (Node child in node.GetChildren(false))
			{
				if (child != null)
				{
					ApplyEnabledRecursive(child, gate, enabled);
				}
			}
		}

		internal static void ClearEnabledStateRecursive(Node node)
		{
			Control val = (Control)(object)((node is Control) ? node : null);
			if (val != null && ControlEnablementStates.TryGetValue(val, out ControlEnablementState value))
			{
				if (!value.IsEnabledApplied)
				{
					value.Restore(val);
				}
				ControlEnablementStates.Remove(val);
			}
			foreach (Node child in node.GetChildren(false))
			{
				if (child != null)
				{
					ClearEnabledStateRecursive(child);
				}
			}
		}

		private static void ApplyEnabledToControl(Control control, object gate, bool enabled)
		{
			//IL_00a2: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a7: Unknown result type (might be due to invalid IL or missing references)
			if (!GodotObject.IsInstanceValid((GodotObject)(object)control))
			{
				return;
			}
			ControlEnablementState value = ControlEnablementStates.GetValue(control, (Control current) => new ControlEnablementState(current));
			bool flag = value.SetGate(gate, enabled);
			if (flag == value.IsEnabledApplied)
			{
				return;
			}
			if (flag)
			{
				value.Restore(control);
				return;
			}
			value.Capture(control);
			if (control is ModSettingsActionsButton modSettingsActionsButton)
			{
				modSettingsActionsButton.ForceCloseDropdown();
			}
			if (control is IModSettingsTransientPopupOwner modSettingsTransientPopupOwner)
			{
				modSettingsTransientPopupOwner.ForceCloseTransientUi();
			}
			if (control.HasFocus())
			{
				control.ReleaseFocus();
			}
			((Node)control).ProcessMode = (ProcessModeEnum)4;
			control.MouseFilter = (MouseFilterEnum)2;
			control.FocusMode = (FocusModeEnum)0;
			((CanvasItem)control).Modulate = ResolveDisabledModulate(control, value.Modulate);
			BaseButton val = (BaseButton)(object)((control is BaseButton) ? control : null);
			if (val == null)
			{
				LineEdit val2 = (LineEdit)(object)((control is LineEdit) ? control : null);
				if (val2 == null)
				{
					TextEdit val3 = (TextEdit)(object)((control is TextEdit) ? control : null);
					if (val3 != null)
					{
						val3.Editable = false;
					}
				}
				else
				{
					val2.Editable = false;
				}
			}
			else
			{
				val.Disabled = true;
			}
			value.IsEnabledApplied = false;
		}

