			{
				return false;
			}
			if (!((CanvasItem)button).IsVisibleInTree() || ((BaseButton)button).Disabled || (long)((Node)button).ProcessMode == 4)
			{
				return false;
			}
			return !IsControlEffectivelyDisabled(target);
		}

		private static bool IsControlEffectivelyDisabled(Control control)
