		}

		internal static Control? CreateEntryActionsButton<TValue>(ModSettingsUiContext context, IModSettingsValueBinding<TValue> binding, ModSettingsMenuCapabilities capabilities = ModSettingsMenuCapabilities.All)
		{
			if (!HasBindingActions(binding, capabilities))
			{
				return null;
			}
			return (Control?)(object)new ModSettingsActionsButton(() => BuildBindingActions(context, binding, capabilities), context.RequestRefresh);
		}

		private static bool HasBindingActions<TValue>(IModSettingsValueBinding<TValue> binding, ModSettingsMenuCapabilities capabilities)
		{
			if (capabilities.HasFlag(ModSettingsMenuCapabilities.Copy) || capabilities.HasFlag(ModSettingsMenuCapabilities.Paste))
			{
				return true;
			}
			if (capabilities.HasFlag(ModSettingsMenuCapabilities.ResetToDefault) && binding is IDefaultModSettingsValueBinding<TValue>)
			{
				return true;
			}
			return ModSettingsUiActionRegistry.HasBindingActionAppender<TValue>();
		}

		private static List<ModSettingsMenuAction> BuildBindingActions<TValue>(ModSettingsUiContext context, IModSettingsValueBinding<TValue> binding, ModSettingsMenuCapabilities capabilities)
		{
			List<ModSettingsMenuAction> list = new List<ModSettingsMenuAction>();
			if (capabilities.HasFlag(ModSettingsMenuCapabilities.ResetToDefault))
			{
				IDefaultModSettingsValueBinding<TValue> defaults = binding as IDefaultModSettingsValueBinding<TValue>;
				if (defaults != null)
				{
					list.Add(new ModSettingsMenuAction("ritsulib.settings.resetDefault", ModSettingsLocalization.Get("button.resetDefault", "Reset to default"), enabled: true, delegate
					{
						binding.Write(defaults.CreateDefaultValue());
						context.MarkDirty(binding);
						context.RequestRefresh();
					}));
				}
			}
			if (capabilities.HasFlag(ModSettingsMenuCapabilities.Copy))
			{
				list.Add(new ModSettingsMenuAction("ritsulib.settings.copy", ModSettingsLocalization.Get("button.copy", "Copy data"), enabled: true, delegate
				{
					CopyBindingValueToClipboard(binding);
					context.RequestRefresh();
				}));
			}
			if (capabilities.HasFlag(ModSettingsMenuCapabilities.Paste))
			{
				list.Add(new ModSettingsMenuAction("ritsulib.settings.paste", ModSettingsLocalization.Get("button.paste", "Paste data"), () => CanPasteBindingValueFromClipboard(binding), delegate
				{
					if (TryPasteBindingValueFromClipboard(context, binding))
					{
						context.MarkDirty(binding);
						context.RequestRefresh();
					}
				}));
			}
			ModSettingsUiActionRegistry.AppendBindingActions(context, binding, list);
			return list;
		}

		internal static List<ModSettingsMenuAction> BuildListItemMenuActions<TItem>(ModSettingsUiContext context, ModSettingsListItemContext<TItem> itemContext, ModSettingsMenuCapabilities capabilities)
		{
			List<ModSettingsMenuAction> list = new List<ModSettingsMenuAction>
			{
				new ModSettingsMenuAction("ritsulib.settings.moveUp", ModSettingsLocalization.Get("button.moveUp", "Move up"), itemContext.CanMoveUp, itemContext.MoveUp),
				new ModSettingsMenuAction("ritsulib.settings.moveDown", ModSettingsLocalization.Get("button.moveDown", "Move down"), itemContext.CanMoveDown, itemContext.MoveDown),
				new ModSettingsMenuAction("ritsulib.settings.duplicate", ModSettingsLocalization.Get("button.duplicate", "Duplicate"), itemContext.SupportsStructuredClipboard, itemContext.Duplicate),
				new ModSettingsMenuAction("ritsulib.settings.remove", ModSettingsLocalization.Get("button.remove", "Remove"), enabled: true, itemContext.Remove)
			};
			if (capabilities.HasFlag(ModSettingsMenuCapabilities.Copy))
			{
				list.Insert(list.Count - 1, new ModSettingsMenuAction("ritsulib.settings.copy", ModSettingsLocalization.Get("button.copy", "Copy data"), itemContext.SupportsStructuredClipboard, delegate
				{
					itemContext.TryCopyToClipboard();
				}));
			}
			if (capabilities.HasFlag(ModSettingsMenuCapabilities.Paste))
			{
				list.Insert(list.Count - 1, new ModSettingsMenuAction("ritsulib.settings.paste", ModSettingsLocalization.Get("button.paste", "Paste data"), itemContext.CanPasteFromClipboard, delegate
				{
					itemContext.TryPasteFromClipboard();
				}));
			}
			ModSettingsUiActionRegistry.AppendListItemActions(context, itemContext, list);
			return list;
		}

		internal static List<ModSettingsMenuAction> BuildPageMenuActions(ModSettingsUiContext context, ModSettingsPageUiContext pageContext)
		{
			List<ModSettingsMenuAction> list = new List<ModSettingsMenuAction>();
			if (pageContext.Page.MenuCapabilities.HasFlag(ModSettingsMenuCapabilities.Copy))
			{
				list.Add(new ModSettingsMenuAction("ritsulib.settings.page.copy", ModSettingsLocalization.Get("button.copy", "Copy data"), enabled: true, delegate
				{
					ModSettingsUiChromeClipboard.TryCopyPage(pageContext);
					context.RequestRefresh();
				}));
			}
			if (pageContext.Page.MenuCapabilities.HasFlag(ModSettingsMenuCapabilities.Paste))
			{
				list.Add(new ModSettingsMenuAction("ritsulib.settings.page.paste", ModSettingsLocalization.Get("button.paste", "Paste data"), () => ModSettingsInteractionPolicy.CanMutateAnyEntry(pageContext.Page) && ModSettingsUiChromeClipboard.CanPastePage(pageContext), delegate
				{
					ModSettingsUiChromeClipboard.TryPastePage(pageContext);
					context.RequestRefresh();
				}));
			}
			if (pageContext.Page.MenuCapabilities.HasFlag(ModSettingsMenuCapabilities.ResetToDefault) && PageHasResettableEntries(pageContext.Page))
			{
				list.Add(new ModSettingsMenuAction("ritsulib.settings.page.resetDefault", ModSettingsLocalization.Get("button.resetPageDefaults", "Reset page to defaults"), () => PageCanResetToDefault(pageContext.Page), delegate
				{
					ResetPageToDefaults(pageContext);
				}));
			}
			ModSettingsUiActionRegistry.AppendPageActions(context, pageContext, list);
			return list;
		}

		internal static List<ModSettingsMenuAction> BuildSectionMenuActions(ModSettingsUiContext context, ModSettingsSectionUiContext sectionContext)
		{
			List<ModSettingsMenuAction> list = new List<ModSettingsMenuAction>();
			if (sectionContext.Section.MenuCapabilities.HasFlag(ModSettingsMenuCapabilities.Copy))
			{
				list.Add(new ModSettingsMenuAction("ritsulib.settings.section.copy", ModSettingsLocalization.Get("button.copy", "Copy data"), enabled: true, delegate
				{
					ModSettingsUiChromeClipboard.TryCopySection(sectionContext);
					context.RequestRefresh();
				}));
			}
			if (sectionContext.Section.MenuCapabilities.HasFlag(ModSettingsMenuCapabilities.Paste))
			{
				list.Add(new ModSettingsMenuAction("ritsulib.settings.section.paste", ModSettingsLocalization.Get("button.paste", "Paste data"), () => ModSettingsInteractionPolicy.CanMutateAnyEntry(sectionContext.Page, sectionContext.Section) && ModSettingsUiChromeClipboard.CanPasteSection(sectionContext), delegate
				{
					ModSettingsUiChromeClipboard.TryPasteSection(sectionContext);
					context.RequestRefresh();
				}));
			}
			if (sectionContext.Section.MenuCapabilities.HasFlag(ModSettingsMenuCapabilities.ResetToDefault) && SectionHasResettableEntries(sectionContext.Section))
			{
				list.Add(new ModSettingsMenuAction("ritsulib.settings.section.resetDefault", ModSettingsLocalization.Get("button.resetSectionDefaults", "Reset section to defaults"), () => SectionCanResetToDefault(sectionContext.Page, sectionContext.Section), delegate
				{
					ResetSectionToDefaults(sectionContext);
				}));
			}
			ModSettingsUiActionRegistry.AppendSectionActions(context, sectionContext, list);
			return list;
		}

		private static bool PageCanResetToDefault(ModSettingsPage page)
		{
			return page.Sections.Any((ModSettingsSection section) => SectionCanResetToDefault(page, section));
		}

		private static bool PageHasResettableEntries(ModSettingsPage page)
		{
			return page.Sections.Any(SectionHasResettableEntries);
		}

		private static bool SectionCanResetToDefault(ModSettingsPage page, ModSettingsSection section)
		{
			return section.Entries.Any((ModSettingsEntryDefinition entry) => entry.CanResetToDefault && ModSettingsInteractionPolicy.CanMutateEntry(page, section, entry));
		}

		private static bool SectionHasResettableEntries(ModSettingsSection section)
		{
			return section.Entries.Any((ModSettingsEntryDefinition entry) => entry.CanResetToDefault);
		}

		private static void ResetPageToDefaults(ModSettingsPageUiContext pageContext)
		{
			if (pageContext.Page.Sections.Sum((ModSettingsSection section) => ResetSectionEntriesToDefaults(pageContext.Host, pageContext.Page, section)) > 0)
			{
				pageContext.Host.RequestRefreshAfterDataModelBatchChange();
			}
		}

		private static void ResetSectionToDefaults(ModSettingsSectionUiContext sectionContext)
		{
			if (ResetSectionEntriesToDefaults(sectionContext.Host, sectionContext.Page, sectionContext.Section) > 0)
			{
				sectionContext.Host.RequestRefreshAfterDataModelBatchChange();
			}
		}

		private static int ResetSectionEntriesToDefaults(IModSettingsUiActionHost host, ModSettingsPage page, ModSettingsSection section)
		{
			return section.Entries.Count((ModSettingsEntryDefinition entry) => ModSettingsInteractionPolicy.CanMutateEntry(page, section, entry) && entry.TryResetToDefault(host));
		}

		private static void CopyBindingValueToClipboard<TValue>(IModSettingsValueBinding<TValue> binding)
		{
			IStructuredModSettingsValueAdapter<TValue> adapter = ResolveClipboardAdapter(binding);
			ModSettingsClipboardOperations.InvokeCopy(binding, ModSettingsClipboardScope.Self, adapter, binding.Read());
		}

		private static bool CanPasteBindingValueFromClipboard<TValue>(IModSettingsValueBinding<TValue> binding)
		{
			IStructuredModSettingsValueAdapter<TValue> adapter = ResolveClipboardAdapter(binding);
			return ModSettingsClipboardOperations.CanPasteBindingValue(binding, adapter);
		}

		private static bool TryPasteBindingValueFromClipboard<TValue>(ModSettingsUiContext context, IModSettingsValueBinding<TValue> binding)
		{
			IStructuredModSettingsValueAdapter<TValue> adapter = ResolveClipboardAdapter(binding);
			if (!ModSettingsClipboardOperations.TryPasteBindingValue(binding, adapter, out var value, out var failureReason))
			{
				context.NotifyPasteFailure(failureReason);
				return false;
			}
			binding.Write(value);
			return true;
		}

		internal static IStructuredModSettingsValueAdapter<TValue> ResolveClipboardAdapter<TValue>(IModSettingsValueBinding<TValue> binding)
		{
			if (!(binding is IStructuredModSettingsValueBinding<TValue> structuredModSettingsValueBinding))
			{
				return ModSettingsStructuredData.Json<TValue>();
			}
			return structuredModSettingsValueBinding.Adapter;
		}

		internal static string ResolveEntryLabelDisplay(ModSettingsText? label)
		{
			string text = ModSettingsUiContext.Resolve(label);
			if (!string.IsNullOrWhiteSpace(text))
			{
				return text;
			}
			return ModSettingsLocalization.Get("entry.label.empty", "—");
		}

		private static string ResolveSectionTitleText(ModSettingsSection section)
		{
			if (section.Title == null)
			{
				return ModSettingsLocalization.Get("section.default", "Section");
			}
			return ResolveEntryLabelDisplay(section.Title);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Synchronizes a control's visibility with a predicate immediately and on each settings refresh,
		///         treating predicate failures as hidden.
		///     </para>
		///     <para xml:lang="zh-CN">立即并在每次设置刷新时根据谓词同步控件可见性；谓词失败时按不可见处理。</para>
		/// </summary>
		/// <param name="context">
		///     <para xml:lang="en">The UI context that owns refresh registration.</para>
		///     <para xml:lang="zh-CN">负责注册刷新操作的界面上下文。</para>
		/// </param>
		/// <param name="inner">
		///     <para xml:lang="en">The control whose visibility is synchronized.</para>
		///     <para xml:lang="zh-CN">要同步可见性的控件。</para>
		/// </param>
		/// <param name="predicate">
		///     <para xml:lang="en">The optional visibility predicate; <see langword="null" /> leaves the control unchanged.</para>
		///     <para xml:lang="zh-CN">可选的可见性谓词；传入 <see langword="null" /> 时保持控件不变。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The same control instance.</para>
		///     <para xml:lang="zh-CN">传入的同一控件实例。</para>
		/// </returns>
		internal static Control MaybeWrapDynamicVisibility(ModSettingsUiContext context, Control inner, Func<bool>? predicate)
		{
			if (predicate == null)
			{
				return inner;
			}
			Apply();
			context.RegisterDynamicVisibility(inner, predicate);
			return inner;
			void Apply()
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)inner))
				{
					bool flag = ModSettingsPredicate.Evaluate(predicate);
					if (((CanvasItem)inner).Visible != flag)
					{
						((CanvasItem)inner).Visible = flag;
						FastVerticalStack.RequestAncestorLayouts(inner);
					}
				}
			}
		}

