		private static PageBuildItem CreateEntryBuildItem(ModSettingsUiContext context, ModSettingsPage page, ModSettingsSection section, ModSettingsEntryDefinition entry, SectionBuildPlan sectionPlan, ModSettingsReusableEntryNodePool? entryNodePool)
		{
