					canApply = () => reusable.ReuseVersion == reuseVersion;
				}
				val = MaybeWrapDynamicVisibility(context, val, CreateEntryVisibilityPredicate(page, entry));
				AttachHostSurfaceReadOnlySync(context, val, context.GetSectionHostReadOnlyMask(), canApply);
				val = MaybeWrapDynamicEnabled(context, val, entry.EnabledPredicate, canApply);
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.Warn($"[Settings] Failed to build entry '{page.ModId}:{page.Id}:{section.Id}:{entry.Id}': {value}", 1);
				val = CreateBuildErrorPlaceholder(ModSettingsLocalization.Get("entry.failed.title", "Setting failed to load"), string.Format(ModSettingsLocalization.Get("entry.failed.body", "Failed to build setting '{0}'."), entry.Id));
			}
			finally
			{
				context.EndEntrySurfaceScope();
				context.EndSectionSurfaceScope();
			}
			return new PageBuildItem(val, sectionPlan.EntryHost, delegate(Control added)
			{
				context.RegisterEntryAnchor(page, section, entry, added);
				if (sectionPlan.EnableGate != null)
				{
					ApplyEnabledRecursive((Node)(object)added, sectionPlan.EnableGate, ModSettingsPredicate.Evaluate(section.EnabledWhen));
				}
				if (context.PageEnableGate != null)
				{
