		private static float ResolveDisabledNumber(string basePath, string suffix, string fallbackPath, float fallback)
		{
			RitsuShellTheme current = RitsuShellTheme.Current;
			if (!string.IsNullOrWhiteSpace(basePath) && current.TryGetNumber(basePath + suffix, out var value) && value > 0.05 && value <= 1.0)
			{
				return (float)value;
			}
			if (current.TryGetNumber(fallbackPath, out var value2) && value2 > 0.05 && value2 <= 1.0)
			{
				return (float)value2;
			}
			return fallback;
		}

