			((Control)val).AddThemeFontSizeOverride(StringName.op_Implicit("bold_font_size"), RitsuShellTheme.Current.Metric.FontSize.PageDescription);
			((Control)val).AddThemeFontSizeOverride(StringName.op_Implicit("italics_font_size"), RitsuShellTheme.Current.Metric.FontSize.PageDescription);
			((Control)val).AddThemeFontSizeOverride(StringName.op_Implicit("bold_italics_font_size"), RitsuShellTheme.Current.Metric.FontSize.PageDescription);
			((Control)val).AddThemeFontSizeOverride(StringName.op_Implicit("mono_font_size"), RitsuShellTheme.Current.Metric.FontSize.PageDescription);
