		internal static void RegisterRefreshWhenAlive(ModSettingsUiContext context, GodotObject? node, Action action, ModSettingsUiRefreshSpec spec)
		{
			if (spec.IsStaticDisplay)
			{
				return;
			}
			if (node == null)
			{
				context.RegisterRefresh(action, spec);
				return;
			}
			context.RegisterRefresh(delegate
			{
				if (GodotObject.IsInstanceValid(node))
				{
					action();
				}
			}, spec);
		}

		internal static Control CreatePageContent(ModSettingsUiContext context, ModSettingsPage page)
		{
			FastVerticalStack fastVerticalStack = CreatePageContentHost(page);
			foreach (PageBuildItem item in CreatePageBuildItems(context, page))
			{
				((Node)(((object)item.Parent) ?? ((object)fastVerticalStack))).AddChild((Node)(object)item.Control, false, (InternalMode)0);
				item.AfterAdded?.Invoke(item.Control);
			}
			return MaybeWrapDynamicVisibility(context, (Control)(object)fastVerticalStack, page.VisibleWhen);
		}

		internal static FastVerticalStack CreatePageContentHost(ModSettingsPage page)
		{
			FastVerticalStack fastVerticalStack = new FastVerticalStack(RitsuShellThemeLayoutResolver.ResolveInt("components.page.layout.sectionSeparation", 8));
			((Node)fastVerticalStack).Name = StringName.op_Implicit("Page_" + SanitizeName(page.ModId) + "_" + SanitizeName(page.Id));
			((Control)fastVerticalStack).SizeFlagsHorizontal = (SizeFlags)3;
			((Control)fastVerticalStack).MouseFilter = (MouseFilterEnum)2;
			return fastVerticalStack;
		}

		internal static IEnumerable<PageBuildItem> CreatePageBuildItems(ModSettingsUiContext context, ModSettingsPage page, ModSettingsReusableEntryNodePool? entryNodePool = null)
		{
			Func<bool>?[] sectionVisible = new Func<bool>[page.Sections.Count];
			for (int i = 0; i < page.Sections.Count; i++)
			{
				sectionVisible[i] = ModSettingsVisibility.CreateSectionVisibilityPredicate(page, page.Sections[i]);
			}
			for (int index = 0; index < page.Sections.Count; index++)
			{
				ModSettingsSection section = page.Sections[index];
				if (index > 0)
				{
					Func<bool> predicate = CreateDividerVisibilityPredicate(sectionVisible, index);
					yield return new PageBuildItem(MaybeWrapDynamicVisibility(context, (Control)(object)CreateDivider(), predicate));
				}
				SectionBuildPlan builtSection = null;
				PageBuildItem pageBuildItem = null;
				try
				{
					builtSection = CreateSectionShell(context, page, section);
				}
				catch (Exception value)
				{
					RitsuLibFramework.Logger.Warn($"[Settings] Failed to build section '{page.ModId}:{page.Id}:{section.Id}': {value}", 1);
					pageBuildItem = new PageBuildItem(CreateBuildErrorPlaceholder(ModSettingsLocalization.Get("section.failed.title", "Section failed to load"), string.Format(ModSettingsLocalization.Get("section.failed.body", "Failed to build section '{0}'."), section.Id)));
				}
				if (pageBuildItem != null)
				{
					yield return pageBuildItem;
					continue;
				}
				yield return new PageBuildItem(builtSection.Control);
				if (builtSection.LazyContentSection != null)
				{
					SectionBuildPlan sectionPlan = builtSection;
					builtSection.LazyContentSection.SetLazyContentBuilder(delegate
					{
						using (FastVerticalStack.DeferLayoutRequests())
						{
							foreach (ModSettingsEntryDefinition entry in section.Entries)
							{
								PageBuildItem pageBuildItem2 = CreateEntryBuildItem(context, page, section, entry, sectionPlan, entryNodePool);
								((Node)(pageBuildItem2.Parent ?? sectionPlan.EntryHost)).AddChild((Node)(object)pageBuildItem2.Control, false, (InternalMode)0);
								pageBuildItem2.AfterAdded?.Invoke(pageBuildItem2.Control);
							}
						}
						if (sectionPlan.EnableGate != null)
						{
							ApplyEnabledRecursive((Node)(object)sectionPlan.EntryHost, sectionPlan.EnableGate, ModSettingsPredicate.Evaluate(section.EnabledWhen));
						}
						if (context.PageEnableGate != null)
						{
							ApplyEnabledRecursive((Node)(object)sectionPlan.EntryHost, context.PageEnableGate, ModSettingsPredicate.Evaluate(page.EnabledWhen));
						}
					});
					continue;
				}
				foreach (ModSettingsEntryDefinition entry2 in section.Entries)
				{
					yield return CreateEntryBuildItem(context, page, section, entry2, builtSection, entryNodePool);
				}
			}
		}

		private static Func<bool>? CreateDividerVisibilityPredicate(IReadOnlyList<Func<bool>?> sectionVisible, int index)
		{
			if (sectionVisible[index] == null && AllBeforeAlwaysVisible(sectionVisible, index))
			{
				return null;
			}
			return () => IsSectionVisible(sectionVisible[index]) && AnyVisibleBefore(sectionVisible, index);
		}

		private static bool AllBeforeAlwaysVisible(IReadOnlyList<Func<bool>?> sectionVisible, int index)
		{
			for (int i = 0; i < index; i++)
			{
				if (sectionVisible[i] != null)
				{
					return false;
				}
			}
			return true;
		}

		private static bool AnyVisibleBefore(IReadOnlyList<Func<bool>?> sectionVisible, int index)
		{
			for (int i = 0; i < index; i++)
			{
				if (IsSectionVisible(sectionVisible[i]))
				{
					return true;
				}
			}
			return false;
		}

		private static bool IsSectionVisible(Func<bool>? predicate)
		{
			return predicate?.Invoke() ?? true;
		}

