		{
			ModSettingsSliderControl controlSlot = null;
			ModSettingsSliderControl control = new ModSettingsSliderControl(entry.Binding.Read(), entry.MinValue, entry.MaxValue, entry.Step, FormatValue, delegate(double value)
			{
				entry.Binding.Write(value);
				context.MarkDirty(entry.Binding);
				controlSlot.SetValue(entry.Binding.Read());
				context.RequestRefresh();
			});
			controlSlot = control;
			RegisterRefreshWhenAlive(context, (GodotObject?)(object)control, delegate
			{
