		internal static Control CreateChoiceEntry<TValue>(ModSettingsUiContext context, ChoiceModSettingsEntryDefinition<TValue> entry)
		{
			(TValue, string)[] options = ResolveOptions();
			Control val;
			Action action;
			if (entry.Presentation == ModSettingsChoicePresentation.Dropdown)
			{
				ModSettingsDropdownChoiceControl<TValue> dropdown = new ModSettingsDropdownChoiceControl<TValue>(options, entry.Binding.Read(), delegate(TValue value)
				{
					entry.Binding.Write(value);
					context.MarkDirty(entry.Binding);
					context.RequestRefresh();
				});
				if (entry.OptionsProvider != null)
				{
					dropdown.Opening += delegate
					{
						dropdown.SetOptions(ResolveOptions(), entry.Binding.Read());
					};
				}
				val = (Control)(object)dropdown;
				action = delegate
				{
					if (entry.OptionsProvider == null)
					{
						dropdown.SetValue(entry.Binding.Read());
					}
					else
					{
						dropdown.SetOptions(ResolveOptions(), entry.Binding.Read());
					}
				};
			}
			else
			{
				ModSettingsChoiceControl<TValue> stepper = new ModSettingsChoiceControl<TValue>(options, entry.Binding.Read(), delegate(TValue value)
				{
					entry.Binding.Write(value);
					context.MarkDirty(entry.Binding);
					context.RequestRefresh();
				});
				val = (Control)(object)stepper;
				action = delegate
				{
					if (entry.OptionsProvider == null)
					{
						stepper.SetValue(entry.Binding.Read());
					}
					else
					{
						stepper.SetOptions(ResolveOptions(), entry.Binding.Read());
					}
				};
			}
			RegisterRefreshWhenAlive(context, (GodotObject?)(object)val, action, (entry.OptionsProvider == null) ? ModSettingsUiRefreshSpec.ForBinding(entry.Binding) : ModSettingsUiRefreshSpec.Always);
			return CreateSettingLine(context, () => ModSettingsUiContext.Resolve(entry.Label), () => ModSettingsUiControlFactoryHelper.ResolveDescription(entry.Description), val, entry.Binding, entry.MenuCapabilities, entry.Label, entry.Description);
			(TValue Value, string Label)[] ResolveOptions()
			{
				return (from option in entry.ResolveOptions()
					select (Value: option.Value, Label: ModSettingsUiContext.Resolve(option.Label))).ToArray();
			}
		}

