	internal sealed class ModSettingsReusableEntryNodePool
	{
		private const int WarmRetainedPerKind = 24;

		private const ulong IdleReleaseMsec = 20000uL;

		private readonly Dictionary<ModSettingsReusableEntryKind, Queue<ModSettingsUiFactory.ReusableSettingLine>> _buckets = new Dictionary<ModSettingsReusableEntryKind, Queue<ModSettingsUiFactory.ReusableSettingLine>>();

		internal ModSettingsUiFactory.ReusableSettingLine Rent(ModSettingsReusableEntryKind kind)
		{
			Sweep();
			if (!_buckets.TryGetValue(kind, out Queue<ModSettingsUiFactory.ReusableSettingLine> value))
			{
				return new ModSettingsUiFactory.ReusableSettingLine(kind);
			}
			while (value.Count > 0)
			{
				ModSettingsUiFactory.ReusableSettingLine reusableSettingLine = value.Dequeue();
				if (GodotObject.IsInstanceValid((GodotObject)(object)reusableSettingLine))
				{
					return reusableSettingLine;
				}
			}
			return new ModSettingsUiFactory.ReusableSettingLine(kind);
		}

		internal void Return(ModSettingsUiFactory.ReusableSettingLine line)
		{
			if (GodotObject.IsInstanceValid((GodotObject)(object)line))
			{
				line.ReleaseForPool();
				Sweep();
				if (!_buckets.TryGetValue(line.Kind, out Queue<ModSettingsUiFactory.ReusableSettingLine> value))
				{
					value = new Queue<ModSettingsUiFactory.ReusableSettingLine>();
					_buckets[line.Kind] = value;
				}
				line.LastUsedMsec = Time.GetTicksMsec();
				value.Enqueue(line);
				Sweep();
			}
		}

		internal void Sweep()
		{
			ulong ticksMsec = Time.GetTicksMsec();
			foreach (KeyValuePair<ModSettingsReusableEntryKind, Queue<ModSettingsUiFactory.ReusableSettingLine>> bucket in _buckets)
			{
				List<ModSettingsUiFactory.ReusableSettingLine> list = new List<ModSettingsUiFactory.ReusableSettingLine>(bucket.Value.Count);
				while (bucket.Value.Count > 0)
				{
					ModSettingsUiFactory.ReusableSettingLine reusableSettingLine = bucket.Value.Dequeue();
					if (GodotObject.IsInstanceValid((GodotObject)(object)reusableSettingLine))
					{
						list.Add(reusableSettingLine);
					}
				}
				list.Sort((ModSettingsUiFactory.ReusableSettingLine left, ModSettingsUiFactory.ReusableSettingLine right) => left.LastUsedMsec.CompareTo(right.LastUsedMsec));
				Queue<ModSettingsUiFactory.ReusableSettingLine> queue = new Queue<ModSettingsUiFactory.ReusableSettingLine>(list.Count);
				int num = Math.Max(0, list.Count - 24);
				for (int num2 = 0; num2 < list.Count; num2++)
				{
					ModSettingsUiFactory.ReusableSettingLine reusableSettingLine2 = list[num2];
					bool flag = ticksMsec >= reusableSettingLine2.LastUsedMsec && ticksMsec - reusableSettingLine2.LastUsedMsec >= 20000;
					if ((num2 < num) & flag)
					{
						((Node)reusableSettingLine2).QueueFree();
					}
					else
					{
						queue.Enqueue(reusableSettingLine2);
					}
				}
				_buckets[bucket.Key] = queue;
			}
		}
	}
