			Dictionary<string, Dictionary<string, ModSettingsChromeBindingSnapshot>> dictionary = new Dictionary<string, Dictionary<string, ModSettingsChromeBindingSnapshot>>(StringComparer.OrdinalIgnoreCase);
			foreach (ModSettingsSection section in context.Page.Sections)
