			ModSettingsClipboardData.WriteClipboardEnvelope(new ModSettingsClipboardEnvelope("ritsulib.settings.ui.page", "ritsulib.settings.ui.page.data.v1", context.Page.ModId + "|" + context.Page.Id, string.Empty, ModSettingsClipboardScope.Self, JsonSerializer.Serialize(value)));
