		private static bool TryApplyDefaultPageDataPaste(ModSettingsPageUiContext target, ModSettingsPageDataClipboardPayload? payload)
		{
			Dictionary<string, Dictionary<string, ModSettingsChromeBindingSnapshot>> dictionary = payload?.Sections;
			if (dictionary == null || dictionary.Count <= 0 || !IsPagePayloadForTarget(payload, target))
			{
				return false;
			}
			bool result = false;
			foreach (ModSettingsSection section in target.Page.Sections)
			{
				if (!payload.Sections.TryGetValue(section.Id, out Dictionary<string, ModSettingsChromeBindingSnapshot> value) || value == null || value.Count <= 0)
				{
					continue;
				}
				foreach (ModSettingsEntryDefinition entry in section.Entries)
				{
					if (value.TryGetValue(entry.Id, out var value2) && !(value2 == null) && ModSettingsInteractionPolicy.CanMutateEntry(target.Page, section, entry) && entry.TryPasteChromeBindingSnapshot(value2, target.Host))
					{
						result = true;
					}
				}
			}
			return result;
		}

		private static bool TryApplyDefaultSectionDataPaste(ModSettingsSectionUiContext target, ModSettingsSectionDataClipboardPayload? payload)
		{
			Dictionary<string, ModSettingsChromeBindingSnapshot> dictionary = payload?.Bindings;
			if (dictionary == null || dictionary.Count <= 0 || !IsSectionPayloadForTarget(payload, target))
			{
				return false;
			}
			bool result = false;
			foreach (ModSettingsEntryDefinition entry in target.Section.Entries)
			{
				if (payload.Bindings.TryGetValue(entry.Id, out ModSettingsChromeBindingSnapshot value) && !(value == null) && ModSettingsInteractionPolicy.CanMutateEntry(target.Page, target.Section, entry) && entry.TryPasteChromeBindingSnapshot(value, target.Host))
				{
					result = true;
				}
			}
			return result;
		}

		private static bool IsPagePayloadForTarget(ModSettingsPageDataClipboardPayload payload, ModSettingsPageUiContext target)
		{
			if (string.Equals(payload.ModId, target.Page.ModId, StringComparison.OrdinalIgnoreCase))
			{
				return string.Equals(payload.PageId, target.Page.Id, StringComparison.OrdinalIgnoreCase);
			}
			return false;
		}

		private static bool IsSectionPayloadForTarget(ModSettingsSectionDataClipboardPayload payload, ModSettingsSectionUiContext target)
		{
			if (string.Equals(payload.ModId, target.Page.ModId, StringComparison.OrdinalIgnoreCase) && string.Equals(payload.PageId, target.Page.Id, StringComparison.OrdinalIgnoreCase))
			{
				return string.Equals(payload.SectionId, target.Section.Id, StringComparison.OrdinalIgnoreCase);
			}
			return false;
		}

		private static bool TryNormalizeSections(Dictionary<string, Dictionary<string, ModSettingsChromeBindingSnapshot>> source, out Dictionary<string, Dictionary<string, ModSettingsChromeBindingSnapshot>> sections)
		{
			sections = new Dictionary<string, Dictionary<string, ModSettingsChromeBindingSnapshot>>(StringComparer.OrdinalIgnoreCase);
			foreach (var (text2, dictionary2) in source)
			{
				if (string.IsNullOrWhiteSpace(text2) || dictionary2 == null || !TryNormalizeBindings(dictionary2, out Dictionary<string, ModSettingsChromeBindingSnapshot> bindings) || !sections.TryAdd(text2, bindings))
				{
					return false;
				}
			}
			return true;
		}

		private static bool TryNormalizeBindings(Dictionary<string, ModSettingsChromeBindingSnapshot> source, out Dictionary<string, ModSettingsChromeBindingSnapshot> bindings)
		{
			bindings = new Dictionary<string, ModSettingsChromeBindingSnapshot>(StringComparer.OrdinalIgnoreCase);
			foreach (var (text2, modSettingsChromeBindingSnapshot2) in source)
			{
				if (string.IsNullOrWhiteSpace(text2) || (object)modSettingsChromeBindingSnapshot2 == null || modSettingsChromeBindingSnapshot2.TypeFullName == null || modSettingsChromeBindingSnapshot2.SchemaSignature == null || modSettingsChromeBindingSnapshot2.JsonPayload == null || !bindings.TryAdd(text2, modSettingsChromeBindingSnapshot2))
				{
					return false;
				}
			}
			return true;
		}
	}
