	internal static class ModSettingsLocalizedFormatting
	{
		private static readonly ConcurrentDictionary<string, CompositeFormat> Cache = new ConcurrentDictionary<string, CompositeFormat>(StringComparer.Ordinal);

		internal static string Format(string format, object? argument)
		{
			CompositeFormat orAdd = Cache.GetOrAdd(format, (string value) => CompositeFormat.Parse(value));
			return string.Format(CultureInfo.CurrentCulture, orAdd, (object)argument);
		}
	}
