			if (num < 0)
			{
				return;
			}
			_suppressCallbacks = true;
			try
			{
				_selectedIndex = num;
				RefreshFaceLabel();
				if (_dropOpen)
				{
					SyncVirtualDropdownRows();
					WireRowFocusNeighbors();
