			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Replaces the displayed binding without normalizing it, entering capture mode, or invoking the
		///         change callback.
		///     </para>
		///     <para xml:lang="zh-CN">替换显示的绑定，但不将其规范化、不进入捕获模式，也不调用变更回调。</para>
		/// </summary>
		/// <param name="value">
		///     <para xml:lang="en">The binding text to display.</para>
		///     <para xml:lang="zh-CN">要显示的绑定文本。</para>
		/// </param>
		public void SetValue(string value)
		{
			_currentValue = value;
			if (!_capturing)
			{
				RefreshText();
			}
		}

		/// <inheritdoc />
		public override void _UnhandledKeyInput(InputEvent @event)
		{
			//IL_0032: Unknown result type (might be due to invalid IL or missing references)
			//IL_0037: Unknown result type (might be due to invalid IL or missing references)
			//IL_0038: Unknown result type (might be due to invalid IL or missing references)
			//IL_003f: Invalid comparison between Unknown and I8
			//IL_0115: Unknown result type (might be due to invalid IL or missing references)
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			//IL_0048: Invalid comparison between Unknown and I8
			//IL_004a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0051: Invalid comparison between Unknown and I8
			//IL_008e: Unknown result type (might be due to invalid IL or missing references)
			if (!_capturing)
			{
				return;
			}
