			if (val.Pressed)
			{
				Key keycode = val.Keycode;
				if ((long)keycode != 4194305)
				{
					if ((long)keycode == 4194308 || (long)keycode == 4194312)
					{
						ApplyBinding(string.Empty, notify: true);
						_capturing = false;
						_pendingModifierBindings.Clear();
						return;
					}
					if (IsModifierKey(val.Keycode))
					{
						if (_allowModifierCombos || _allowModifierOnly)
						{
							_pendingModifierBindings.Add(GetRecordedKeyName(val, _distinguishModifierSides));
							RefreshText();
						}
						return;
					}
					string value = BuildBindingFromPendingModifiers(val, _allowModifierCombos, _distinguishModifierSides, _pendingModifierBindings);
					if (!string.IsNullOrWhiteSpace(value))
					{
						ApplyBinding(value, notify: true);
						_capturing = false;
						_pendingModifierBindings.Clear();
					}
				}
				else
				{
					_capturing = false;
					_pendingModifierBindings.Clear();
					RefreshText();
				}
			}
