					ApplyBinding(string.Join('+', OrderedModifierTokens(_pendingModifierBindings)), notify: true);
				}
				_capturing = false;
				_pendingModifierBindings.Clear();
				RefreshText();
			}
		}

		/// <inheritdoc />
		public override void _UnhandledInput(InputEvent @event)
		{
			if (!_allowActionBindings || !_capturing)
			{
				return;
			}
			InputEventAction val = (InputEventAction)(object)((@event is InputEventAction) ? @event : null);
			if (val != null && val.Pressed && !((InputEvent)val).IsEcho())
			{
				string value = RuntimeHotkeyService.ActionBinding(((object)val.Action).ToString());
				if (!string.IsNullOrWhiteSpace(value))
				{
					((Node)this).GetViewport().SetInputAsHandled();
					ApplyBinding(value, notify: true);
					_capturing = false;
					_pendingModifierBindings.Clear();
				}
			}
		}

		private void BeginCapture()
		{
			_capturing = true;
			_pendingModifierBindings.Clear();
			RefreshText();
			Button? captureButton = _captureButton;
			if (captureButton != null)
			{
				((Control)captureButton).GrabFocus();
			}
		}

		private void ApplyBinding(string value, bool notify)
		{
			_currentValue = value;
			RefreshText();
			if (notify)
			{
				InvokeOnChanged(value);
			}
		}

		private void InvokeOnChanged(string value)
		{
			_onChanged?.Invoke(value);
		}

		private void RefreshText()
		{
			string text = ((_pendingModifierBindings.Count == 0) ? string.Empty : string.Join('+', OrderedModifierTokens(_pendingModifierBindings)));
			string text2 = ((!_capturing) ? (string.IsNullOrWhiteSpace(_currentValue) ? ModSettingsLocalization.Get("keybinding.unbound", "Unbound") : _currentValue) : (string.IsNullOrWhiteSpace(text) ? ModSettingsLocalization.Get("keybinding.capturing", "Press combination...") : (text + "+...")));
			if (_captureButton != null)
			{
				_captureButton.Text = text2;
			}
			string text3 = ((!_capturing) ? (_allowActionBindings ? ModSettingsLocalization.Get("keybinding.hint.input", "Click to record. Supports key combinations and controller actions.") : ((!_allowModifierCombos) ? ModSettingsLocalization.Get("keybinding.hint.single", "Click to record a single key.") : (_allowModifierOnly ? ModSettingsLocalization.Get("keybinding.hint.combo", "Click to record. Supports key combinations.") : ModSettingsLocalization.Get("keybinding.hint.comboNonModifier", "Click to record. Supports key combinations and requires a non-modifier key.")))) : (string.IsNullOrWhiteSpace(text) ? ModSettingsLocalization.Get("keybinding.hint.capturing", _allowActionBindings ? "Press a key combination or controller action. Esc cancels, Backspace/Delete clears." : "Press a key combination. Esc cancels, Backspace/Delete clears.") : ModSettingsLocalization.Get("keybinding.hint.capturingPending", "Modifier keys recorded. Press another key to complete, or release to keep a modifier-only binding.")));
			if (_hintLabel != null)
			{
				_hintLabel.Text = text3;
			}
		}

		internal static string BuildBindingFromPendingModifiers(InputEventKey keyEvent, bool allowModifierCombos, bool distinguishModifierSides, IEnumerable<string> pendingModifiers)
		{
			List<string> list = (allowModifierCombos ? OrderedModifierTokens(pendingModifiers).ToList() : new List<string>());
			list.Add(GetRecordedKeyName(keyEvent, distinguishModifierSides));
			return string.Join('+', list);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Converts a captured key event to a binding token, using <see cref="P:Godot.InputEventKey.Location" /> to
		///         qualify left- and right-side modifier keys when requested.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将捕获的按键事件转换为绑定标记，并在需要时根据 <see cref="P:Godot.InputEventKey.Location" /> 标明修饰键的左、右侧。
		///     </para>
		/// </summary>
		/// <param name="keyEvent">
		///     <para xml:lang="en">The captured keyboard event.</para>
		///     <para xml:lang="zh-CN">捕获的键盘事件。</para>
		/// </param>
		/// <param name="distinguishModifierSides">
		///     <para xml:lang="en">Whether modifier locations should be preserved in the returned token.</para>
		///     <para xml:lang="zh-CN">返回标记中是否应保留修饰键侧别。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A key token accepted by the runtime hotkey parser.</para>
		///     <para xml:lang="zh-CN">运行时热键解析器可接受的按键标记。</para>
		/// </returns>
		internal unsafe static string GetRecordedKeyName(InputEventKey keyEvent, bool distinguishModifierSides)
