			//IL_0076: Unknown result type (might be due to invalid IL or missing references)
			//IL_006e: Unknown result type (might be due to invalid IL or missing references)
			//IL_000e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			//IL_0014: Unknown result type (might be due to invalid IL or missing references)
			//IL_0017: Invalid comparison between Unknown and I8
			//IL_007b: Unknown result type (might be due to invalid IL or missing references)
			//IL_007c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0019: Unknown result type (might be due to invalid IL or missing references)
			//IL_001c: Invalid comparison between Unknown and I8
			//IL_0080: Unknown result type (might be due to invalid IL or missing references)
			//IL_0085: Unknown result type (might be due to invalid IL or missing references)
			if (distinguishModifierSides)
			{
				ModifierKind modifierKindForKeyEvent = RuntimeHotkeyParser.GetModifierKindForKeyEvent(keyEvent);
				if (modifierKindForKeyEvent != ModifierKind.None)
				{
					KeyLocation location = keyEvent.Location;
					if ((long)location == 1)
					{
						return $"Left{modifierKindForKeyEvent}";
					}
					if ((long)location == 2)
					{
						return $"Right{modifierKindForKeyEvent}";
					}
				}
			}
			Key val = (distinguishModifierSides ? keyEvent.PhysicalKeycode : keyEvent.Keycode);
			if ((int)val == 0)
			{
				val = keyEvent.Keycode;
			}
			return ((object)(*(Key*)(&val))/*cast due to constrained. prefix*/).ToString();
		}

		internal static IEnumerable<string> OrderedModifierTokens(IEnumerable<string> tokens)
		{
			return tokens.OrderBy(GetModifierSortOrder).ThenBy<string, string>((string t) => t, StringComparer.OrdinalIgnoreCase);
		}

		private static int GetModifierSortOrder(string token)
		{
			string text = token.ToLowerInvariant();
			if (text.Contains("ctrl") || text.Contains("control"))
			{
				return 0;
			}
			if (text.Contains("alt"))
			{
				return 1;
			}
			if (text.Contains("shift"))
			{
				return 2;
			}
			if (text.Contains("meta") || text.Contains("cmd") || text.Contains("command"))
			{
				return 3;
			}
			return 100;
		}

		internal unsafe static bool IsModifierKey(Key key)
		{
			string text = ((object)(*(Key*)(&key))/*cast due to constrained. prefix*/).ToString().ToLowerInvariant();
			if (!text.Contains("shift") && !text.Contains("ctrl") && !text.Contains("control") && !text.Contains("alt") && !text.Contains("meta") && !text.Contains("cmd"))
			{
				return text.Contains("command");
			}
			return true;
