		private void OpenDropdown()
		{
			_openActions = GetActions();
			if (_openActions.Count == 0)
			{
				_openActions = null;
				return;
			}
			try
			{
				SharedDropdown.Open(this);
			}
			finally
			{
				if (!_dropOpen)
				{
					_openActions = null;
				}
			}
		}

		private void CloseDropdown()
		{
			if (_dropOpen)
			{
				SharedDropdown.Close(this, restoreFocus: true);
			}
		}

		private void OnSharedDropdownOpened()
		{
			_dropOpen = true;
			((CanvasItem)this).QueueRedraw();
			((Node)this).SetProcessInput(true);
			((Node)this).SetProcessUnhandledInput(true);
		}

		private void OnSharedDropdownClosed(bool restoreFocus)
		{
			_dropOpen = false;
			((CanvasItem)this).QueueRedraw();
			((Node)this).SetProcessInput(false);
			((Node)this).SetProcessUnhandledInput(false);
			_preferredPopupPosition = null;
			_openActions = null;
			if (restoreFocus && GodotObject.IsInstanceValid((GodotObject)(object)this) && ((CanvasItem)this).IsVisibleInTree())
			{
				((Control)this).GrabFocus();
			}
		}

		private IReadOnlyList<ModSettingsMenuAction> GetActions()
		{
			if (_actionsProvider == null)
