		private void ActivateRow(int index)
		{
			IReadOnlyList<ModSettingsMenuAction> readOnlyList = _openActions ?? GetActions();
			if (index < 0 || index >= readOnlyList.Count)
			{
				return;
			}
			ModSettingsMenuAction modSettingsMenuAction = readOnlyList[index];
			if (!IsActionEnabled(modSettingsMenuAction))
			{
				return;
			}
			try
			{
				modSettingsMenuAction.Action();
				_afterAction?.Invoke();
			}
			finally
			{
				CloseDropdown();
			}
		}

		private static bool IsActionEnabled(ModSettingsMenuAction action)
		{
			try
			{
				return action.IsEnabled();
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.Warn($"[ModSettingsActionsButton] IsEnabled failed: {value}", 1);
				return false;
			}
		}

