		private static List<string> NormalizeBindings(IEnumerable<string>? values)
		{
			List<string> list = new List<string>();
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			foreach (string item in values ?? Array.Empty<string>())
			{
				if (RuntimeHotkeyService.TryNormalizeBinding(item, out string normalizedBinding) && hashSet.Add(normalizedBinding))
				{
					list.Add(normalizedBinding);
				}
			}
			return list;
		}

