	internal static class ModSettingsInteractionPolicy
	{
		public static bool CanMutateAnyEntry(ModSettingsPage page)
		{
			return page.Sections.Any((ModSettingsSection section) => section.Entries.Any((ModSettingsEntryDefinition entry) => CanMutateEntry(page, section, entry)));
		}

		public static bool CanMutateAnyEntry(ModSettingsPage page, ModSettingsSection section)
		{
			return section.Entries.Any((ModSettingsEntryDefinition entry) => CanMutateEntry(page, section, entry));
		}

		public static bool CanMutateEntry(ModSettingsPage page, ModSettingsSection section, ModSettingsEntryDefinition entry)
		{
			if (ModSettingsHostSurfaceResolver.IsVisibleOnCurrentHost(page.VisibleOnHostSurfaces) && ModSettingsPredicate.Evaluate(page.VisibleWhen) && ModSettingsHostSurfaceResolver.IsVisibleOnCurrentHost(section.VisibleOnHostSurfaces) && ModSettingsPredicate.Evaluate(section.VisibleWhen) && ModSettingsVisibility.IsEntryVisible(page, entry) && ModSettingsPredicate.Evaluate(page.EnabledWhen) && ModSettingsPredicate.Evaluate(section.EnabledWhen) && ModSettingsPredicate.Evaluate(entry.EnabledPredicate))
			{
				return !ModSettingsHostSurfaceResolver.IsReadOnlyOnCurrentHost(ModSettingsUiHostSurfacePolicy.MergeReadOnlyMask(page, section, entry));
			}
			return false;
		}
	}
