		internal static IReadOnlyList<ModSettingsSearchResult> Search(IReadOnlyList<ModSettingsSearchResult> index, string query, int limit)
		{
			ArgumentNullException.ThrowIfNull(index, "index");
			ArgumentNullException.ThrowIfNull(query, "query");
			ArgumentOutOfRangeException.ThrowIfNegativeOrZero(limit, "limit");
			string[] terms = query.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
			if (terms.Length == 0)
			{
				return Array.Empty<ModSettingsSearchResult>();
			}
			List<ModSettingsSearchResult> list = new List<ModSettingsSearchResult>();
			list.AddRange(from match in (from result in index
					select (Result: result, Score: Score(result, terms)) into match
					where match.Score >= 0
					orderby match.Score, match.Result.Order
					select match).Take(limit)
				select match.Result);
			return new <>z__ReadOnlyList<ModSettingsSearchResult>(list);
		}

		internal static async Task<ModSettingsSearchBatch> SearchAsync(IReadOnlyList<ModSettingsSearchResult> index, string query, int limit, CancellationToken cancellationToken = default(CancellationToken))
		{
			ModSettingsSearchBatch completed = null;
			await foreach (ModSettingsSearchBatch item in SearchStreamAsync(index, query, limit, cancellationToken).ConfigureAwait(continueOnCapturedContext: false))
			{
				completed = item;
			}
			return completed ?? new ModSettingsSearchBatch(Array.Empty<ModSettingsSearchResult>(), 0, index.Count, IsComplete: true, HasMore: false);
		}

		internal static async IAsyncEnumerable<ModSettingsSearchBatch> SearchStreamAsync(IReadOnlyList<ModSettingsSearchResult> index, string query, int limit, [EnumeratorCancellation] CancellationToken cancellationToken = default(CancellationToken))
		{
			ArgumentNullException.ThrowIfNull(index, "index");
			ArgumentNullException.ThrowIfNull(query, "query");
			ArgumentOutOfRangeException.ThrowIfNegativeOrZero(limit, "limit");
			string[] terms = query.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
			if (terms.Length == 0)
			{
				yield return new ModSettingsSearchBatch(Array.Empty<ModSettingsSearchResult>(), 0, index.Count, IsComplete: true, HasMore: false);
				yield break;
			}
			List<(ModSettingsSearchResult Result, int Score)> matches = new List<(ModSettingsSearchResult, int)>();
			for (int indexPosition = 0; indexPosition < index.Count; indexPosition++)
			{
				cancellationToken.ThrowIfCancellationRequested();
				ModSettingsSearchResult result = index[indexPosition];
				int num = await ScoreAsync(result, terms, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (num >= 0)
				{
					matches.Add((result, num));
				}
				int num2 = indexPosition + 1;
				if (matches.Count > limit)
				{
					yield return CreateBatch(matches, limit, num2, index.Count, isComplete: true, hasMore: true);
					yield break;
				}
				if (num2 % 12 == 0)
				{
					yield return CreateBatch(matches, limit, num2, index.Count, isComplete: false, hasMore: false);
				}
			}
			yield return CreateBatch(matches, limit, index.Count, index.Count, isComplete: true, hasMore: false);
		}

		private static ModSettingsSearchResult CreateResult(string title, string path, string? description, ModSettingsLocation location, int order, IReadOnlyList<string> alternateTexts, params string[] ids)
		{
			string text = (string.IsNullOrWhiteSpace(title) ? ids[^1] : title.Trim());
			List<string> list = new List<string>();
			list.Add(text);
			list.Add(path);
			list.Add(description ?? string.Empty);
			list.AddRange(alternateTexts);
			list.AddRange(ids);
			string[] source = list.ToArray();
			string searchText = string.Join('\n', source.Where((string value) => !string.IsNullOrWhiteSpace(value)));
			return new ModSettingsSearchResult(text, path, searchText, location, order);
		}

		private static int Score(ModSettingsSearchResult result, IReadOnlyList<string> terms)
		{
			int num = 0;
			foreach (string term in terms)
			{
				int num2 = result.Title.IndexOf(term, StringComparison.OrdinalIgnoreCase);
				if (num2 >= 0)
				{
					num += ((num2 != 0) ? (12 + num2) : 0);
					continue;
				}
				int num3 = result.Path.IndexOf(term, StringComparison.OrdinalIgnoreCase);
				if (num3 >= 0)
				{
					num += 40 + num3;
					continue;
				}
				int num4 = result.SearchText.IndexOf(term, StringComparison.OrdinalIgnoreCase);
				if (num4 >= 0)
				{
					num += 80 + num4;
					continue;
				}
				int num5 = result.PreparedTitle.ScoreExpansion(term);
				if (num5 >= 0)
				{
					num += 100 + num5;
					continue;
				}
				int num6 = result.PreparedPath.ScoreExpansion(term);
				if (num6 >= 0)
				{
					num += 140 + num6;
					continue;
				}
				int num7 = result.PreparedSearchText.ScoreExpansion(term);
				if (num7 < 0)
				{
					return -1;
				}
				num += 180 + num7;
			}
			return num;
		}

