		private static ModSettingsSearchBatch CreateBatch(IReadOnlyList<(ModSettingsSearchResult Result, int Score)> matches, int limit, int processedCount, int totalCount, bool isComplete, bool hasMore)
		{
			List<ModSettingsSearchResult> list = new List<ModSettingsSearchResult>();
			list.AddRange(from match in (from match in matches
					orderby match.Score, match.Result.Order
					select match).Take(limit)
				select match.Result);
			return new ModSettingsSearchBatch(new <>z__ReadOnlyList<ModSettingsSearchResult>(list), processedCount, totalCount, isComplete, hasMore);
		}

		private static IReadOnlyList<string> ResolvePageTitles(ModSettingsPage page, IReadOnlyDictionary<string, ModSettingsPage> pageMap, bool useFallbackText)
		{
			List<string> list = new List<string>();
			HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			ModSettingsPage modSettingsPage = page;
			while (modSettingsPage != null)
			{
				string item = CreatePageKey(modSettingsPage.ModId, modSettingsPage.Id);
				if (!hashSet.Add(item))
				{
					break;
				}
				list.Add(useFallbackText ? (modSettingsPage.Title?.FallbackText ?? modSettingsPage.Id) : ModSettingsLocalization.ResolvePageDisplayName(modSettingsPage));
				modSettingsPage = ((string.IsNullOrWhiteSpace(modSettingsPage.ParentPageId) || !pageMap.TryGetValue(CreatePageKey(modSettingsPage.ModId, modSettingsPage.ParentPageId), out ModSettingsPage value)) ? null : value);
			}
			list.Reverse();
			return list;
		}

		private static string ResolveSectionTitle(ModSettingsSection section)
		{
			string text = section.Title?.Resolve();
			if (!string.IsNullOrWhiteSpace(text))
			{
				return text;
