		///     <para xml:lang="zh-CN">选择该操作时调用的回调。</para>
		/// </param>
		public ModSettingsMenuAction(string? id, string label, bool enabled, Action action)
			: this(id, label, () => enabled, action)
		{
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Registers callbacks that append custom actions to menus for setting rows, list items, pages, and
	///         sections. Each menu build invokes a stable registration snapshot outside the registry lock; callbacks
	///         registered during that invocation participate in later builds. Appender exceptions propagate.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         注册向设置行、列表项、页面与节菜单追加自定义操作的回调。每次构建菜单时都会在注册表锁外调用稳定的注册快照；
	///         调用期间新增的回调从后续构建开始生效。追加回调抛出的异常会继续传播。
	///     </para>
	/// </summary>
	public static class ModSettingsUiActionRegistry
	{
		private sealed class BindingAppenderBag
		{
			private readonly List<Delegate> _delegates = new List<Delegate>();

			private readonly Lock _lock = new Lock();

			public void Add<TValue>(Action<IModSettingsUiActionHost, IModSettingsValueBinding<TValue>, List<ModSettingsMenuAction>> d)
			{
				using (_lock.EnterScope())
				{
					_delegates.Add(d);
				}
			}

			public void Invoke<TValue>(IModSettingsUiActionHost host, IModSettingsValueBinding<TValue> binding, List<ModSettingsMenuAction> sink)
			{
				Delegate[] array;
				using (_lock.EnterScope())
				{
					array = _delegates.ToArray();
				}
				Delegate[] array2 = array;
				for (int i = 0; i < array2.Length; i++)
				{
					((Action<IModSettingsUiActionHost, IModSettingsValueBinding<TValue>, List<ModSettingsMenuAction>>)array2[i])(host, binding, sink);
				}
			}
		}

		private sealed class ListItemAppenderBag
		{
			private readonly List<Delegate> _delegates = new List<Delegate>();

			private readonly Lock _lock = new Lock();

			public void Add<TItem>(Action<IModSettingsUiActionHost, ModSettingsListItemContext<TItem>, List<ModSettingsMenuAction>> d)
			{
				using (_lock.EnterScope())
				{
					_delegates.Add(d);
				}
			}

			public void Invoke<TItem>(IModSettingsUiActionHost host, ModSettingsListItemContext<TItem> itemContext, List<ModSettingsMenuAction> sink)
			{
				Delegate[] array;
				using (_lock.EnterScope())
				{
					array = _delegates.ToArray();
				}
				Delegate[] array2 = array;
				for (int i = 0; i < array2.Length; i++)
				{
					((Action<IModSettingsUiActionHost, ModSettingsListItemContext<TItem>, List<ModSettingsMenuAction>>)array2[i])(host, itemContext, sink);
				}
			}
		}

		private sealed class PageAppenderBag
		{
			private readonly List<Action<IModSettingsUiActionHost, ModSettingsPageUiContext, List<ModSettingsMenuAction>>> _delegates = new List<Action<IModSettingsUiActionHost, ModSettingsPageUiContext, List<ModSettingsMenuAction>>>();

			private readonly Lock _lock = new Lock();

			public void Add(Action<IModSettingsUiActionHost, ModSettingsPageUiContext, List<ModSettingsMenuAction>> d)
			{
