		private sealed class SectionAppenderBag
		{
			private readonly List<Action<IModSettingsUiActionHost, ModSettingsSectionUiContext, List<ModSettingsMenuAction>>> _delegates = new List<Action<IModSettingsUiActionHost, ModSettingsSectionUiContext, List<ModSettingsMenuAction>>>();

