		private static readonly ConcurrentDictionary<Type, BindingAppenderBag> BindingAppenders = new ConcurrentDictionary<Type, BindingAppenderBag>();

		private static readonly ConcurrentDictionary<Type, ListItemAppenderBag> ListItemAppenders = new ConcurrentDictionary<Type, ListItemAppenderBag>();

		private static readonly PageAppenderBag PageAppenders = new PageAppenderBag();

		private static readonly SectionAppenderBag SectionAppenders = new SectionAppenderBag();

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a callback that appends actions for setting bindings whose value type is
		///         <typeparamref name="TValue" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册一个回调，为值类型为 <typeparamref name="TValue" /> 的设置绑定追加操作。
		///     </para>
		/// </summary>
		/// <typeparam name="TValue">
		///     <para xml:lang="en">The exact value type handled by the callback.</para>
		///     <para xml:lang="zh-CN">回调处理的确切值类型。</para>
		/// </typeparam>
		/// <param name="append">
		///     <para xml:lang="en">
		///         The callback that receives the host, target binding, and mutable action list when a menu is built.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         构建菜单时接收宿主、目标绑定与可变操作列表的回调。
		///     </para>
		/// </param>
		public static void RegisterBindingActionAppender<TValue>(Action<IModSettingsUiActionHost, IModSettingsValueBinding<TValue>, List<ModSettingsMenuAction>> append)
		{
			ArgumentNullException.ThrowIfNull(append, "append");
			BindingAppenders.GetOrAdd(typeof(TValue), (Type _) => new BindingAppenderBag()).Add(append);
		}

