		internal static void AppendBindingActions<TValue>(IModSettingsUiActionHost host, IModSettingsValueBinding<TValue> binding, List<ModSettingsMenuAction> list)
		{
			if (BindingAppenders.TryGetValue(typeof(TValue), out BindingAppenderBag value))
			{
				value.Invoke(host, binding, list);
			}
		}

		internal static bool HasBindingActionAppender<TValue>()
		{
			return BindingAppenders.ContainsKey(typeof(TValue));
		}

		internal static void AppendListItemActions<TItem>(IModSettingsUiActionHost host, ModSettingsListItemContext<TItem> itemContext, List<ModSettingsMenuAction> list)
		{
			if (ListItemAppenders.TryGetValue(typeof(TItem), out ListItemAppenderBag value))
			{
				value.Invoke(host, itemContext, list);
			}
		}

		internal static void AppendPageActions(IModSettingsUiActionHost host, ModSettingsPageUiContext pageContext, List<ModSettingsMenuAction> list)
		{
			PageAppenders.Invoke(host, pageContext, list);
		}

		internal static void AppendSectionActions(IModSettingsUiActionHost host, ModSettingsSectionUiContext sectionContext, List<ModSettingsMenuAction> list)
		{
			SectionAppenders.Invoke(host, sectionContext, list);
		}
