	internal sealed class ModSettingsUiContext(RitsuModSettingsSubmenu submenu, string? pageScopeId = null, object? pageEnableGate = null) : IModSettingsUiActionHost
	{
		private readonly Dictionary<string, Dictionary<string, object?>> _rowUiState = new Dictionary<string, Dictionary<string, object>>();

		private ModSettingsEntryDefinition? _sectionBuildEntry;

		private ModSettingsPage? _sectionBuildPage;

		private ModSettingsSection? _sectionBuildSection;

		internal object? PageEnableGate => pageEnableGate;

		internal Node ModalHost => (Node)(object)submenu;

		public void MarkDirty(IModSettingsBinding binding)
		{
			submenu.MarkDirty(binding);
		}

		public void RequestRefresh()
		{
			submenu.RequestRefresh();
		}

		public void RequestRefreshAfterDataModelBatchChange()
		{
			submenu.RequestRefreshAfterDataModelBatchChange();
		}

		public static string Resolve(ModSettingsText? text, string fallback = "")
		{
			ArgumentNullException.ThrowIfNull(fallback, "fallback");
			return text?.Resolve() ?? fallback;
		}

		public static string ResolvePageTitle(ModSettingsPage page)
		{
			return ModSettingsLocalization.ResolvePageDisplayName(page);
		}

		public static string? ResolvePageDescription(ModSettingsPage page)
		{
			if (page.HideDescription)
			{
				return null;
			}
			string text = page.Description?.Resolve();
			if (!string.IsNullOrWhiteSpace(text))
			{
				return text;
			}
			return Sts2ModManagerCompat.EnumerateModsForManifestLookup().FirstOrDefault((Mod mod) => string.Equals(mod.manifest?.id, page.ModId, StringComparison.OrdinalIgnoreCase))?.manifest?.description;
		}

		public static string ResolveBindingDescriptionBody(ModSettingsText? description)
		{
			return NormalizeDescriptionRichText(Resolve(description));
		}

		private static string NormalizeDescriptionRichText(string s)
		{
			if (!string.IsNullOrEmpty(s))
			{
				return LegacyCodeTagRegex().Replace(s, "[code]$1[/code]");
			}
			return s;
		}

		/// <remarks>
		/// Pattern:<br />
		/// <code>&lt;c&gt;(.*?)&lt;/c&gt;</code><br />
		/// Options:<br />
		/// <code>RegexOptions.Singleline</code><br />
		/// Explanation:<br />
		/// <code>
		/// ○ Match the string "&lt;c&gt;".<br />
		/// ○ 1st capture group.<br />
		///     ○ Match any character lazily any number of times.<br />
		/// ○ Match the string "&lt;/c&gt;".<br />
		/// </code>
		/// </remarks>
		[GeneratedRegex("<c>(.*?)</c>", RegexOptions.Singleline)]
		[GeneratedCode("System.Text.RegularExpressions.Generator", "9.0.14.31522")]
		private static Regex LegacyCodeTagRegex()
		{
			return <RegexGenerator_g>F7F0BFA5D4E3AD299CF17F00EC305F23D34F417D205E2CC8C3F49C1C369614C75__LegacyCodeTagRegex_5.Instance;
		}

		/// <summary>
