		public bool TryGetRowState<TValue>(string rowKey, string stateKey, out TValue? value)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(rowKey, "rowKey");
			ArgumentException.ThrowIfNullOrWhiteSpace(stateKey, "stateKey");
			value = default(TValue);
			if (!_rowUiState.TryGetValue(rowKey, out Dictionary<string, object> value2) || !value2.TryGetValue(stateKey, out var value3))
			{
				return false;
			}
			if (!(value3 is TValue val))
			{
				return false;
			}
			value = val;
			return true;
		}

		public void SetRowState<TValue>(string rowKey, string stateKey, TValue value)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(rowKey, "rowKey");
			ArgumentException.ThrowIfNullOrWhiteSpace(stateKey, "stateKey");
			if (!_rowUiState.TryGetValue(rowKey, out Dictionary<string, object> value2))
			{
				value2 = new Dictionary<string, object>();
				_rowUiState[rowKey] = value2;
			}
			value2[stateKey] = value;
		}

		internal void MigrateRowState(string fromRowKey, string toRowKey)
		{
			if (string.Equals(fromRowKey, toRowKey, StringComparison.Ordinal) || !_rowUiState.TryGetValue(fromRowKey, out Dictionary<string, object> value) || value.Count == 0)
			{
				return;
			}
			if (!_rowUiState.TryGetValue(toRowKey, out Dictionary<string, object> value2))
			{
				value2 = new Dictionary<string, object>();
				_rowUiState[toRowKey] = value2;
			}
			foreach (KeyValuePair<string, object> item in value)
			{
				value2[item.Key] = item.Value;
			}
			_rowUiState.Remove(fromRowKey);
		}
	}
	internal static class ModSettingsUiHostSurfacePolicy
	{
		public static ModSettingsHostSurface MergeReadOnlyMask(ModSettingsPage? page, ModSettingsSection? section, ModSettingsEntryDefinition? entry)
		{
			ModSettingsHostSurface modSettingsHostSurface = ModSettingsHostSurface.None;
			if (page != null)
			{
				modSettingsHostSurface |= page.ReadOnlyOnHostSurfaces;
			}
			if (section != null)
			{
				modSettingsHostSurface |= section.ReadOnlyOnHostSurfaces;
			}
			if (entry != null)
			{
				modSettingsHostSurface |= entry.ReadOnlyOnHostSurfaces;
			}
			return modSettingsHostSurface;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Allows a binding to propagate <see cref="M:STS2RitsuLib.Settings.RitsuModSettingsSubmenu.MarkDirty(STS2RitsuLib.Settings.IModSettingsBinding)" /> to related bindings so
	///         selective refresh and autosave observe the same invalidation. Examples include a projected field and its
	///         list root, or a decorator and its inner binding.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         允许绑定将 <see cref="M:STS2RitsuLib.Settings.RitsuModSettingsSubmenu.MarkDirty(STS2RitsuLib.Settings.IModSettingsBinding)" /> 传播到相关绑定，使选择性刷新和自动保存观察到
	///         相同的失效关系，例如投影字段与列表根绑定，或装饰器与内部绑定。
	///     </para>
	/// </summary>
	internal interface IModSettingsUiRefreshPropagation
	{
		IEnumerable<IModSettingsBinding> ExtraBindingsToMarkDirtyForUi { get; }
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Identifies bindings that participate in UI refresh invalidation as one equivalent group.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         标识在界面刷新失效判断中视为同一等价组的绑定。
	///     </para>
	/// </summary>
	internal interface IModSettingsUiRefreshEquivalence
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets other binding instances treated as the same selective-refresh target, such as the inner binding
		///         wrapped by <see cref="T:STS2RitsuLib.Settings.ModSettingsDebugShowcaseBinding`1" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取在选择性刷新中视为同一目标的其他绑定实例，例如
		///         <see cref="T:STS2RitsuLib.Settings.ModSettingsDebugShowcaseBinding`1" /> 所包装的内部绑定。
		///     </para>
		/// </summary>
		IReadOnlyList<IModSettingsBinding> UiRefreshAlsoTreatAsDirty { get; }
	}
	internal enum ModSettingsRefreshRegistrationKind
	{
		Always,
		AnyBindingDirtyThisFlush,
		SpecificBindings
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Declares when a registered settings UI refresh callback runs, based on bindings marked dirty since the
	///         previous refresh flush.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         根据上一次刷新队列执行后被标记为脏的绑定，声明已注册的设置界面刷新回调何时运行。
	///     </para>
	/// </summary>
	internal readonly record struct ModSettingsUiRefreshSpec(ModSettingsRefreshRegistrationKind Kind, ImmutableArray<IModSettingsBinding> Bindings)
	{
		public static ModSettingsUiRefreshSpec Always { get; } = new ModSettingsUiRefreshSpec(ModSettingsRefreshRegistrationKind.Always, default(ImmutableArray<IModSettingsBinding>));

		public static ModSettingsUiRefreshSpec AnyBindingDirty { get; } = new ModSettingsUiRefreshSpec(ModSettingsRefreshRegistrationKind.AnyBindingDirtyThisFlush, default(ImmutableArray<IModSettingsBinding>));

		public static ModSettingsUiRefreshSpec StaticDisplay { get; } = new ModSettingsUiRefreshSpec(ModSettingsRefreshRegistrationKind.SpecificBindings, ImmutableArray<IModSettingsBinding>.Empty);

		internal bool IsStaticDisplay
		{
			get
			{
				if (Kind == ModSettingsRefreshRegistrationKind.SpecificBindings)
				{
					return Bindings.IsDefaultOrEmpty;
				}
				return false;
			}
		}

		public static ModSettingsUiRefreshSpec ForBinding(IModSettingsBinding binding)
		{
			ArgumentNullException.ThrowIfNull(binding, "binding");
			return new ModSettingsUiRefreshSpec(ModSettingsRefreshRegistrationKind.SpecificBindings, ImmutableCollectionsMarshal.AsImmutableArray(new IModSettingsBinding[1] { binding }));
		}

		public static ModSettingsUiRefreshSpec ForBindings(params IModSettingsBinding[] bindings)
		{
			ArgumentNullException.ThrowIfNull(bindings, "bindings");
			if (bindings.Any((IModSettingsBinding binding) => binding == null))
			{
				throw new ArgumentException("Refresh bindings cannot contain null.", "bindings");
			}
			return new ModSettingsUiRefreshSpec(ModSettingsRefreshRegistrationKind.SpecificBindings, ImmutableCollectionsMarshal.AsImmutableArray(bindings.ToArray()));
		}

		internal static bool ShouldRun(ModSettingsUiRefreshSpec spec, bool treatAsFullPass, HashSet<IModSettingsBinding> dirtyBindings)
		{
			return spec.Kind switch
			{
				ModSettingsRefreshRegistrationKind.Always => true, 
				ModSettingsRefreshRegistrationKind.AnyBindingDirtyThisFlush => treatAsFullPass || dirtyBindings.Count > 0, 
				ModSettingsRefreshRegistrationKind.SpecificBindings => spec.Bindings.IsDefaultOrEmpty ? treatAsFullPass : (treatAsFullPass || Overlaps(dirtyBindings, spec.Bindings)), 
				_ => true, 
			};
		}

		private static bool Overlaps(HashSet<IModSettingsBinding> dirty, ImmutableArray<IModSettingsBinding> bindings)
		{
			if (bindings.IsDefaultOrEmpty || dirty.Count == 0)
			{
				return false;
			}
			foreach (IModSettingsBinding item in bindings)
			{
				if (dirty.Contains(item))
				{
					return true;
				}
				if (item is IModSettingsUiRefreshEquivalence modSettingsUiRefreshEquivalence && modSettingsUiRefreshEquivalence.UiRefreshAlsoTreatAsDirty.Any(dirty.Contains))
				{
					return true;
				}
			}
			foreach (IModSettingsBinding item2 in dirty)
			{
				if (item2 is IModSettingsUiRefreshEquivalence modSettingsUiRefreshEquivalence2 && (from alias in modSettingsUiRefreshEquivalence2.UiRefreshAlsoTreatAsDirty
					from reg in bindings
					where reg == alias
					select alias).Any())
				{
					return true;
				}
			}
			HashSet<IModSettingsBinding> dirtyExpanded = ModSettingsBindingInvalidationTopology.ExpandUnion(dirty);
			return Enumerable.Any(bindings, (IModSettingsBinding registered) => ModSettingsBindingInvalidationTopology.ExpandClosure(registered).Any(dirtyExpanded.Contains));
		}
	}
	internal readonly record struct ModSettingsRefreshRegistration(Action Action, ModSettingsUiRefreshSpec Spec);
