		private void TryStartShellThemeWatcher()
		{
			if (_shellThemeWatcher != null || !RitsuShellThemePaths.TryEnsureShellThemesDirectory(out string absolutePath))
			{
				return;
			}
			FileSystemWatcher fileSystemWatcher = null;
			try
			{
				fileSystemWatcher = new FileSystemWatcher(absolutePath, "*.theme.json")
				{
					IncludeSubdirectories = false,
					NotifyFilter = (NotifyFilters.FileName | NotifyFilters.Size | NotifyFilters.LastWrite)
				};
				fileSystemWatcher.Changed += OnShellThemeFileChanged;
				fileSystemWatcher.Created += OnShellThemeFileChanged;
				fileSystemWatcher.Deleted += OnShellThemeFileChanged;
				fileSystemWatcher.Renamed += OnShellThemeFileRenamed;
				fileSystemWatcher.EnableRaisingEvents = true;
				_shellThemeWatcher = fileSystemWatcher;
			}
			catch (Exception value)
			{
				try
				{
					fileSystemWatcher?.Dispose();
					_shellThemeWatcher = null;
				}
				catch (Exception value2)
				{
					_shellThemeWatcher = fileSystemWatcher;
					RitsuLibFramework.Logger.Warn($"[Settings] Failed to dispose the inactive shell-theme watcher: {value2}", 1);
				}
				RitsuLibFramework.Logger.Warn($"[Settings] Live shell-theme reload is unavailable: {value}", 1);
			}
		}

		private void StopShellThemeWatcher()
		{
			if (_shellThemeWatcher != null)
			{
				try
				{
					_shellThemeWatcher.EnableRaisingEvents = false;
					_shellThemeWatcher.Changed -= OnShellThemeFileChanged;
					_shellThemeWatcher.Created -= OnShellThemeFileChanged;
					_shellThemeWatcher.Deleted -= OnShellThemeFileChanged;
					_shellThemeWatcher.Renamed -= OnShellThemeFileRenamed;
					_shellThemeWatcher.Dispose();
				}
				catch (Exception value)
				{
					RitsuLibFramework.Logger.Warn($"[Settings] Failed to stop the live shell-theme watcher: {value}", 1);
					return;
				}
				_shellThemeWatcher = null;
				_shellThemeWatcherQueued = false;
			}
		}

