			return result;
		}

		internal void ShowPasteFailure(ModSettingsPasteFailureReason reason)
		{
			string text;
			switch (reason)
			{
			case ModSettingsPasteFailureReason.None:
				return;
			case ModSettingsPasteFailureReason.ClipboardEmpty:
				text = "clipboard.pasteFailedEmpty";
				break;
			case ModSettingsPasteFailureReason.PasteRuleDenied:
				text = "clipboard.pasteFailedBlocked";
				break;
			default:
				text = "clipboard.pasteFailedIncompatible";
				break;
			}
			string key = text;
			string fallback = reason switch
			{
				ModSettingsPasteFailureReason.ClipboardEmpty => "Clipboard is empty or unavailable.", 
				ModSettingsPasteFailureReason.PasteRuleDenied => "Paste was blocked by a custom rule.", 
				_ => "Clipboard contents are not compatible with this setting.", 
			};
			EnsurePasteErrorDialog();
			((Window)_pasteErrorDialog).Title = ModSettingsLocalization.Get("clipboard.pasteFailedTitle", "Paste failed");
			_pasteErrorDialog.OkButtonText = ModSettingsLocalization.Get("clipboard.pasteErrorOk", "OK");
			_pasteErrorDialog.DialogText = ModSettingsLocalization.Get(key, fallback);
			((Window)_pasteErrorDialog).PopupCentered((Vector2I?)null);
		}

