		///         selected.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在当前模组中选择页面并刷新界面；未选择模组时忽略该请求。
		///     </para>
		/// </summary>
		/// <param name="pageId">
		///     <para xml:lang="en">The ID of the page to select.</para>
		///     <para xml:lang="zh-CN">要选择的页面 ID。</para>
		/// </param>
		public void NavigateToPage(string pageId)
		{
			if (!string.IsNullOrWhiteSpace(_selectedModId))
			{
				_selectedPageId = pageId;
				_selectedSectionId = null;
				_sidebarStructureDirty = true;
				_selectionDirty = true;
				_contentOnlyRebuildNeedsContentFocus = false;
				EnsureUiUpToDate();
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Selects a page and section within the current mod, then scrolls the selected section into view and
		///         updates focus navigation. The request is ignored when no mod is selected.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在当前模组中选择页面与节，然后将所选节滚动到可见区域并更新焦点导航；
		///         未选择模组时忽略该请求。
		///     </para>
		/// </summary>
		/// <param name="pageId">
		///     <para xml:lang="en">The ID of the page that contains the section.</para>
		///     <para xml:lang="zh-CN">节所在页面的 ID。</para>
		/// </param>
		/// <param name="sectionId">
		///     <para xml:lang="en">The ID of the section to reveal.</para>
		///     <para xml:lang="zh-CN">要显示的节 ID。</para>
		/// </param>
		public void NavigateToSection(string pageId, string sectionId)
		{
			if (string.IsNullOrWhiteSpace(_selectedModId))
			{
				return;
			}
			CancelPendingContentScrollReset();
			if (string.Equals(_selectedPageId, pageId, StringComparison.OrdinalIgnoreCase) && string.Equals(_selectedSectionId, sectionId, StringComparison.OrdinalIgnoreCase))
			{
				CallDeferredIfAlive(ScrollToSelectedAnchor);
				RefreshFocusNavigation();
				CallDeferredIfAlive(delegate
				{
					if (GodotObject.IsInstanceValid((GodotObject)(object)_modButtonList) && ((CanvasItem)_modButtonList).IsVisibleInTree())
					{
						((Control)_modButtonList).GrabFocus();
					}
				});
				return;
			}
			bool flag = !string.Equals(_selectedPageId, pageId, StringComparison.OrdinalIgnoreCase);
			if (!flag)
			{
				_selectedSectionId = sectionId;
				RefreshSelectionState();
				CallDeferredIfAlive(ScrollToSelectedAnchor);
				RefreshFocusNavigation();
			}
			else
			{
				_selectedPageId = pageId;
				_selectedSectionId = sectionId;
				_sidebarStructureDirty = true;
				_selectionDirty = true;
				_contentOnlyRebuildNeedsContentFocus = true;
				EnsureUiUpToDate(forceStructure: false, flag);
			}
		}

		internal async Task<ModSettingsOpenResult> OpenToAsync(ModSettingsLocation location, ModSettingsOpenOptions options)
		{
			ArgumentNullException.ThrowIfNull(location, "location");
			ArgumentNullException.ThrowIfNull(options, "options");
			if (!GodotObject.IsInstanceValid((GodotObject)(object)this))
			{
				return ModSettingsOpenResult.Error("ui-not-available", "The mod settings UI is not available.", location);
			}
			ModSettingsOpenResult modSettingsOpenResult = ModSettingsNavigator.ResolveLocation(location);
			if (!modSettingsOpenResult.Success)
			{
				return modSettingsOpenResult;
			}
			ModSettingsLocation target = new ModSettingsLocation(modSettingsOpenResult.ModId, modSettingsOpenResult.PageId, modSettingsOpenResult.SectionId, modSettingsOpenResult.EntryId);
			SelectMod(target.ModId, target.PageId);
			await WaitForInitialUiReadyAsync();
			if (!GodotObject.IsInstanceValid((GodotObject)(object)this))
			{
				return ModSettingsOpenResult.Error("ui-not-available", "The mod settings UI was closed.", target);
			}
			await WaitForSelectedPageContentReadyAsync();
			if (!GodotObject.IsInstanceValid((GodotObject)(object)this))
			{
				return ModSettingsOpenResult.Error("ui-not-available", "The mod settings UI was closed.", target);
			}
			Control val = null;
			if (!string.IsNullOrWhiteSpace(target.SectionId))
			{
				_selectedSectionId = target.SectionId;
				RefreshSelectionState();
				Control val2 = await ResolveSectionAnchorForOpenAsync(target.SectionId);
				if (val2 == null)
				{
					return ModSettingsOpenResult.Error("section-not-found", "Settings section '" + target.SectionId + "' was not found after the page loaded.", target);
				}
				if (options.ExpandCollapsedSection)
				{
					ExpandSectionAnchor(val2);
				}
				else if (!string.IsNullOrWhiteSpace(target.EntryId))
				{
					EnsureSectionContentBuilt(val2);
				}
				val = val2;
			}
			if (!string.IsNullOrWhiteSpace(target.EntryId))
			{
				if (string.IsNullOrWhiteSpace(target.SectionId))
				{
					return ModSettingsOpenResult.Error("section-not-found", "A resolved section id is required before opening an entry.", target);
				}
				Control val3 = await ResolveEntryAnchorForOpenAsync(target.SectionId, target.EntryId);
				if (val3 == null)
				{
					return ModSettingsOpenResult.Error("entry-not-found", "Settings entry '" + target.EntryId + "' was not found after the page loaded.", target);
				}
				if (!((CanvasItem)val3).IsVisibleInTree())
				{
					return ModSettingsOpenResult.Error("entry-hidden", "Settings entry '" + target.EntryId + "' is currently hidden.", target);
				}
				val = val3;
			}
			if (val != null)
			{
				CancelPendingContentScrollReset();
				AlignScrollToAnchor(val);
				if (options.Focus)
				{
					FocusTarget(val);
				}
				if (options.Highlight)
				{
					PulseTarget(val);
				}
			}
			else
			{
				_scrollContainer.ScrollVertical = 0;
			}
			return ModSettingsOpenResult.Ok("opened", "Opened settings location '" + ModSettingsNavigator.FormatLocation(target) + "'.", target);
		}

		private async Task<Control?> ResolveSectionAnchorForOpenAsync(string sectionId)
		{
			if (TryFindSectionAnchorOnSelectedPage(sectionId, out Control anchor))
			{
				return anchor;
			}
			await WaitForSelectedPageContentReadyAsync();
			return TryFindSectionAnchorOnSelectedPage(sectionId, out anchor) ? anchor : null;
		}

		private async Task<Control?> ResolveEntryAnchorForOpenAsync(string sectionId, string entryId)
		{
			if (TryFindEntryAnchorOnSelectedPage(sectionId, entryId, out Control anchor))
			{
				return anchor;
			}
			if (TryFindSectionAnchorOnSelectedPage(sectionId, out Control anchor2))
			{
				EnsureSectionContentBuilt(anchor2);
			}
			await WaitForSelectedPageContentReadyAsync();
			return TryFindEntryAnchorOnSelectedPage(sectionId, entryId, out anchor) ? anchor : null;
		}

		internal void RegisterEntryAnchor(ModSettingsPage page, ModSettingsSection section, ModSettingsEntryDefinition entry, Control control)
		{
			string key = CreatePageCacheKey(page.ModId, page.Id);
			if (_pageContentCaches.TryGetValue(key, out PageContentCache value))
			{
				value.EntryAnchors[CreateEntryCacheKey(page.ModId, page.Id, section.Id, entry.Id)] = control;
			}
		}

