		private void EnsureUiUpToDate(bool forceStructure = false, bool includeAllPagesRefresh = false)
		{
			RefreshPageRegistryForUi();
			ApplyStaticTexts();
			RefreshPageSnapshots();
			EnsureSelectionIsValid();
			if (forceStructure)
			{
				_sidebarStructureDirty = true;
				_contentStructureDirty = true;
			}
			if (_sidebarStructureDirty)
			{
				RebuildSidebar();
			}
			EnsureSelectedPageContentStructure();
			RefreshSelectionState();
			RefreshVisibleContent(includeAllPagesRefresh);
			RefreshContentBuildOverlayVisibility();
			IsInitialUiReady = true;
			QueueDeferredContentLayoutRefresh();
		}

		private async Task EnsureOpenContentReadyAsync()
		{
			await RitsuGodotAwaitSafety.AwaitProcessFrameAsync(((Node)this).GetTree(), (GodotObject?)(object)this);
			if (GodotObject.IsInstanceValid((GodotObject)(object)this))
			{
				EnsureUiUpToDate(forceStructure: true, includeAllPagesRefresh: true);
				EnsureSelectedPageContentStructure();
				RefreshSelectionState();
				RefreshVisibleContent(includeAllPagesRefresh: true);
				RefreshContentBuildOverlayVisibility();
				QueueResizeLayoutRefresh();
			}
		}

		private async Task WaitForSelectedPageContentReadyAsync()
		{
			EnsureSelectedPageContentStructure();
			RefreshVisibleContent(includeAllPagesRefresh: true);
			ModSettingsPage modSettingsPage = ResolveSelectedPage();
			if (modSettingsPage == null)
			{
				return;
			}
			PageContentCache cache = EnsurePageContentCache(modSettingsPage);
			PageBuildState state = cache.State;
			if ((uint)(state - 2) > 1u)
			{
				StartBuildPage(modSettingsPage, cache);
			}
			if (cache.BuildTask != null)
			{
				await cache.BuildTask;
			}
			if (GodotObject.IsInstanceValid((GodotObject)(object)this) && IsPageCurrentlySelected(cache))
			{
				RefreshPageHostLayout(cache);
				await RitsuGodotAwaitSafety.AwaitProcessFrameAsync(((Node)this).GetTree(), (GodotObject?)(object)this);
				if (GodotObject.IsInstanceValid((GodotObject)(object)this) && IsPageCurrentlySelected(cache))
				{
					RefreshPageHostLayout(cache);
				}
			}
		}

		private void RefreshPageSnapshots()
		{
			IReadOnlyList<ModSettingsPage> pages = ModSettingsRegistry.GetPages();
			Dictionary<string, PageSnapshot> next = pages.ToDictionary<ModSettingsPage, string, PageSnapshot>((ModSettingsPage page) => CreatePageCacheKey(page.ModId, page.Id), (ModSettingsPage page) => new PageSnapshot(page.Id, page.ModId, page.ParentPageId, CreatePageStructureSignature(page)), StringComparer.OrdinalIgnoreCase);
			if (_pageSnapshots.Count != next.Count || _pageSnapshots.Any<KeyValuePair<string, PageSnapshot>>((KeyValuePair<string, PageSnapshot> pair) => !next.TryGetValue(pair.Key, out var value) || value != pair.Value))
			{
				_sidebarStructureDirty = true;
				_contentStructureDirty = true;
			}
			_pageSnapshots.Clear();
			foreach (KeyValuePair<string, PageSnapshot> item in next)
			{
				_pageSnapshots[item.Key] = item.Value;
			}
		}

		private bool EnsureSelectionIsValid()
		{
			string previousModId = _selectedModId;
			string previousPageId = _selectedPageId;
			string previousSectionId = _selectedSectionId;
			IGrouping<string, ModSettingsPage>[] array = (from @group in (from page in ModSettingsRegistry.GetPages()
					where string.IsNullOrWhiteSpace(page.ParentPageId) && IsPageVisibleOnCurrentHost(page)
					select page).GroupBy<ModSettingsPage, string>((ModSettingsPage page) => page.ModId, StringComparer.OrdinalIgnoreCase)
				orderby ModSettingsRegistry.GetModSidebarOrder(@group.Key)
				select @group).ThenBy<IGrouping<string, ModSettingsPage>, string>((IGrouping<string, ModSettingsPage> group) => ModSettingsLocalization.ResolveModName(group.Key, group.Key), StringComparer.OrdinalIgnoreCase).ThenBy<IGrouping<string, ModSettingsPage>, string>((IGrouping<string, ModSettingsPage> group) => group.Key, StringComparer.OrdinalIgnoreCase).ToArray();
			if (array.Length == 0)
			{
				_selectedModId = null;
				_selectedPageId = null;
				_selectedSectionId = null;
				return SelectionChanged();
			}
			if (string.IsNullOrWhiteSpace(_selectedModId) || array.All((IGrouping<string, ModSettingsPage> group) => !string.Equals(group.Key, _selectedModId, StringComparison.OrdinalIgnoreCase)))
			{
				_selectedModId = array[0].Key;
				_selectionDirty = true;
				ExpandOnlyMod(_selectedModId);
			}
			ModSettingsPage[] source = (from page in ModSettingsRegistry.GetPages()
				where string.Equals(page.ModId, _selectedModId, StringComparison.OrdinalIgnoreCase) && IsPageVisibleOnCurrentHost(page)
				select page).OrderBy(ModSettingsRegistry.GetEffectivePageSortOrder).ThenBy<ModSettingsPage, string>((ModSettingsPage page) => page.Id, StringComparer.OrdinalIgnoreCase).ToArray();
			ModSettingsPage[] array2 = source.Where((ModSettingsPage page) => string.IsNullOrWhiteSpace(page.ParentPageId)).ToArray();
			if (array2.Length == 0)
			{
				_selectedPageId = null;
				_selectedSectionId = null;
				return SelectionChanged();
			}
			if (!string.IsNullOrWhiteSpace(_selectedPageId) && source.Any((ModSettingsPage page) => string.Equals(page.Id, _selectedPageId, StringComparison.OrdinalIgnoreCase)))
			{
				return SelectionChanged();
			}
			_selectedPageId = array2[0].Id;
			_selectedSectionId = null;
			_selectionDirty = true;
			return SelectionChanged();
			bool SelectionChanged()
			{
				if (string.Equals(previousModId, _selectedModId, StringComparison.OrdinalIgnoreCase) && string.Equals(previousPageId, _selectedPageId, StringComparison.OrdinalIgnoreCase))
				{
					return !string.Equals(previousSectionId, _selectedSectionId, StringComparison.OrdinalIgnoreCase);
				}
				return true;
			}
		}

		private void RebuildSidebar()
		{
			_modButtonList.ClearRows();
			IGrouping<string, ModSettingsPage>[] rootPages = (from @group in (from page in ModSettingsRegistry.GetPages()
					where string.IsNullOrWhiteSpace(page.ParentPageId) && CanPageAppearOnCurrentHost(page)
					select page).GroupBy<ModSettingsPage, string>((ModSettingsPage page) => page.ModId, StringComparer.OrdinalIgnoreCase)
				orderby ModSettingsRegistry.GetModSidebarOrder(@group.Key)
				select @group).ThenBy<IGrouping<string, ModSettingsPage>, string>((IGrouping<string, ModSettingsPage> group) => ModSettingsLocalization.ResolveModName(group.Key, group.Key), StringComparer.OrdinalIgnoreCase).ThenBy<IGrouping<string, ModSettingsPage>, string>((IGrouping<string, ModSettingsPage> group) => group.Key, StringComparer.OrdinalIgnoreCase).ToArray();
			_modButtonList.SetRows(BuildSidebarRows(rootPages));
			_sidebarStructureDirty = false;
			_selectionDirty = true;
		}

		private List<ModSettingsSidebarRow> BuildSidebarRows(IReadOnlyList<IGrouping<string, ModSettingsPage>> rootPages)
		{
			List<ModSettingsSidebarRow> list = new List<ModSettingsSidebarRow>();
			foreach (IGrouping<string, ModSettingsPage> rootPage in rootPages)
			{
				string modId = rootPage.Key;
				ModSettingsPage[] pages = (from modSettingsPage in ModSettingsRegistry.GetPages()
					where string.Equals(modSettingsPage.ModId, modId, StringComparison.OrdinalIgnoreCase) && CanPageAppearOnCurrentHost(modSettingsPage)
					select modSettingsPage).OrderBy(ModSettingsRegistry.GetEffectivePageSortOrder).ThenBy<ModSettingsPage, string>((ModSettingsPage modSettingsPage) => modSettingsPage.Id, StringComparer.OrdinalIgnoreCase).ToArray();
				ModSettingsPage[] array = pages.Where((ModSettingsPage modSettingsPage) => string.IsNullOrWhiteSpace(modSettingsPage.ParentPageId)).ToArray();
				bool flag = ShouldShowExpandedModNav(modId);
				ModSettingsPage[] pages2 = ((array.Length != 0) ? array : pages);
				string text = ResolveSidebarModTitle(pages2);
				string meta = string.Format(ModSettingsLocalization.Get("sidebar.modMeta", "{0} pages"), pages.Length);
				list.Add(new ModSettingsSidebarRow(ModSettingsSidebarItemKind.ModGroup, modId, null, null, modId, text, flag ? "▼" : "▶", 0, meta, delegate
				{
					ActivateSidebarMod(modId);
				}, () => pages.Any(IsPageVisibleOnCurrentHost))
				{
					TooltipInfo = ResolveSidebarModTooltipInfo(modId, text, pages2)
				});
				if (flag)
				{
					ModSettingsPage[] array2 = array;
					foreach (ModSettingsPage page in array2)
					{
						AddSidebarPageRows(list, pages, page, 1);
					}
				}
			}
			return list;
		}

		private static bool CanPageAppearOnCurrentHost(ModSettingsPage page)
		{
			if (ModSettingsHostSurfaceResolver.IsVisibleOnCurrentHost(page.VisibleOnHostSurfaces))
			{
				return page.Sections.Any((ModSettingsSection section) => ModSettingsHostSurfaceResolver.IsVisibleOnCurrentHost(section.VisibleOnHostSurfaces) && section.Entries.Count > 0);
			}
			return false;
		}

		private void AddSidebarPageRows(List<ModSettingsSidebarRow> rows, IReadOnlyList<ModSettingsPage> pages, ModSettingsPage page, int depth)
		{
			string key = CreatePageCacheKey(page.ModId, page.Id);
			rows.Add(new ModSettingsSidebarRow(ModSettingsSidebarItemKind.Page, page.ModId, page.Id, null, key, ResolvePageTabTitle(page), "◦", Math.Max(0, depth - 1), null, delegate
			{
				ActivateSidebarPage(page.ModId, page.Id);
			}, CreateSidebarPageVisibilityPredicate(page, pages)));
			if (string.Equals(page.Id, _selectedPageId, StringComparison.OrdinalIgnoreCase))
			{
				rows.AddRange(from section in page.Sections
					let sectionKey = CreateSectionCacheKey(page.ModId, page.Id, section.Id)
					select new ModSettingsSidebarRow(ModSettingsSidebarItemKind.Section, page.ModId, page.Id, section.Id, sectionKey, ResolveSectionTitle(section), "·", depth + 1, null, delegate
					{
						ActivateSidebarSection(page.ModId, page.Id, section.Id);
					}, CreateSidebarSectionVisibilityPredicate(page, section)));
			}
			if (IsSelectedPageInNavSubtree(_selectedPageId, page, pages))
			{
				ModSettingsPage[] array = pages.Where((ModSettingsPage candidate) => string.Equals(candidate.ParentPageId, page.Id, StringComparison.OrdinalIgnoreCase)).OrderBy(ModSettingsRegistry.GetEffectivePageSortOrder).ThenBy<ModSettingsPage, string>((ModSettingsPage candidate) => candidate.Id, StringComparer.OrdinalIgnoreCase)
					.ToArray();
				foreach (ModSettingsPage page2 in array)
				{
					AddSidebarPageRows(rows, pages, page2, depth + 1);
				}
			}
		}

		private void ActivateSidebarMod(string modId)
		{
			if (_expandedModIds.Remove(modId))
			{
				_sidebarStructureDirty = true;
				_selectionDirty = true;
				EnsureUiUpToDate();
				return;
			}
			if (!string.Equals(_selectedModId, modId, StringComparison.OrdinalIgnoreCase))
			{
				_selectedModId = modId;
				_selectedPageId = (from page in (from page in ModSettingsRegistry.GetPages()
						where string.Equals(page.ModId, modId, StringComparison.OrdinalIgnoreCase) && string.IsNullOrWhiteSpace(page.ParentPageId) && IsPageVisibleOnCurrentHost(page)
						select page).OrderBy(ModSettingsRegistry.GetEffectivePageSortOrder).ThenBy<ModSettingsPage, string>((ModSettingsPage page) => page.Id, StringComparer.OrdinalIgnoreCase)
					select page.Id).FirstOrDefault();
				_selectedSectionId = null;
				_focusSelectedPageButtonOnNextRefresh = true;
			}
			ExpandOnlyMod(modId);
			_sidebarStructureDirty = true;
			_selectionDirty = true;
			EnsureUiUpToDate();
		}

		private void ActivateSidebarPage(string modId, string pageId)
		{
			bool num = string.Equals(_selectedPageId, pageId, StringComparison.OrdinalIgnoreCase);
			_selectedModId = modId;
			_selectedPageId = pageId;
			if (!num)
			{
				_selectedSectionId = null;
			}
			ExpandOnlyMod(modId);
			_sidebarStructureDirty = true;
			_selectionDirty = true;
			EnsureUiUpToDate();
		}

		private void ActivateSidebarSection(string modId, string pageId, string sectionId)
		{
			_selectedModId = modId;
			NavigateToSection(pageId, sectionId);
		}

		private void EnsureSelectedPageContentStructure()
		{
			EnsurePageContentCacheStructure();
			ModSettingsPage modSettingsPage = ResolveSelectedPage();
			if (modSettingsPage != null)
			{
				EnsurePageContentCache(modSettingsPage);
			}
		}

		private void EnsureAllPageContentCacheStructure()
		{
			EnsurePageContentCacheStructure();
			foreach (ModSettingsPage page in ModSettingsRegistry.GetPages())
			{
				EnsurePageContentCache(page);
			}
		}

		private void EnsurePageContentCacheStructure()
		{
			if (!_contentStructureDirty)
			{
				return;
			}
			HashSet<string> livePageKeys = new HashSet<string>(from page in ModSettingsRegistry.GetPages()
				select CreatePageCacheKey(page.ModId, page.Id), StringComparer.OrdinalIgnoreCase);
			string[] array = _pageContentCaches.Keys.Where((string key) => !livePageKeys.Contains(key)).ToArray();
			foreach (string text in array)
			{
				if (_pageContentCaches.TryGetValue(text, out PageContentCache value))
				{
					ReleasePageContentCache(text, value);
				}
			}
			foreach (PageContentCache value2 in _pageContentCaches.Values)
			{
				CancelPageBuild(value2);
				if (GodotObject.IsInstanceValid((GodotObject)(object)value2.Root))
				{
					((CanvasItem)value2.Root).Visible = false;
				}
			}
			_globalRefreshRegistrations.Clear();
			HideTransientContentState();
			_contentStructureDirty = false;
		}

		private PageContentCache EnsurePageContentCache(ModSettingsPage pageToRender)
		{
			string text = CreatePageCacheKey(pageToRender.ModId, pageToRender.Id);
			if (_pageContentCaches.TryGetValue(text, out PageContentCache value))
			{
				if ((object)((Node)value.Root).GetParent() != _contentList)
				{
					((Node)_contentList).AddChild((Node)(object)value.Root, false, (InternalMode)0);
				}
				return value;
			}
			ModSettingsUiFactory.FastVerticalStack fastVerticalStack = new ModSettingsUiFactory.FastVerticalStack(8);
			((Node)fastVerticalStack).Name = StringName.op_Implicit("CachedPage_" + SanitizePageNodeName(text));
			((Control)fastVerticalStack).SizeFlagsHorizontal = (SizeFlags)3;
			((Control)fastVerticalStack).MouseFilter = (MouseFilterEnum)2;
			((CanvasItem)fastVerticalStack).Visible = false;
			ModSettingsUiFactory.FastVerticalStack fastVerticalStack2 = fastVerticalStack;
			ModSettingsUiFactory.FastVerticalStack fastVerticalStack3 = new ModSettingsUiFactory.FastVerticalStack(8);
			((Node)fastVerticalStack3).Name = StringName.op_Implicit("PageHeader_" + SanitizePageNodeName(text));
			((Control)fastVerticalStack3).SizeFlagsHorizontal = (SizeFlags)3;
			((Control)fastVerticalStack3).MouseFilter = (MouseFilterEnum)2;
			ModSettingsUiFactory.FastVerticalStack fastVerticalStack4 = fastVerticalStack3;
			ModSettingsUiFactory.FastVerticalStack fastVerticalStack5 = ModSettingsUiFactory.CreatePageContentHost(pageToRender);
			((Node)_contentList).AddChild((Node)(object)fastVerticalStack2, false, (InternalMode)0);
			((Node)fastVerticalStack2).AddChild((Node)(object)fastVerticalStack4, false, (InternalMode)0);
			((Node)fastVerticalStack2).AddChild((Node)(object)fastVerticalStack5, false, (InternalMode)0);
			PageContentCache pageContentCache = new PageContentCache
			{
				PageId = pageToRender.Id,
				PageKey = text,
				Root = (Control)(object)fastVerticalStack2,
				HeaderHost = (Control)(object)fastVerticalStack4,
				ContentHost = (Control)(object)fastVerticalStack5,
				State = PageBuildState.NotBuilt,
				BuildVersion = 0,
				LastUsedMsec = Time.GetTicksMsec()
			};
			_pageContentCaches[text] = pageContentCache;
			return pageContentCache;
		}

		private void RefreshSelectionState()
		{
			string selectedPageKey = GetSelectedPageKey();
			string selectedSectionKey = GetSelectedSectionKey();
			_modButtonList.SyncSelection(_selectedModId, selectedPageKey, selectedSectionKey);
			_selectionDirty = false;
		}

		private void RefreshVisibleContent(bool includeAllPagesRefresh, bool flushRefreshActions = true)
		{
			foreach (PageContentCache value2 in _pageContentCaches.Values)
			{
				((CanvasItem)value2.Root).Visible = false;
			}
			HideTransientContentState();
			if (string.IsNullOrWhiteSpace(_selectedModId))
			{
				_lastVisibleContentPageKey = null;
				ShowTransientContentState(ModSettingsLocalization.Get("empty.none", "No mod settings pages are currently registered."));
				RefreshFocusNavigation();
				return;
			}
			if ((from page in ModSettingsRegistry.GetPages()
				where string.Equals(page.ModId, _selectedModId, StringComparison.OrdinalIgnoreCase) && string.IsNullOrWhiteSpace(page.ParentPageId) && IsPageVisibleOnCurrentHost(page)
				select page).OrderBy(ModSettingsRegistry.GetEffectivePageSortOrder).ThenBy<ModSettingsPage, string>((ModSettingsPage page) => page.Id, StringComparer.OrdinalIgnoreCase).ToArray()
				.Length == 0)
			{
				_lastVisibleContentPageKey = null;
				ShowTransientContentState(ModSettingsLocalization.Get("empty.mod", "This mod does not currently expose a settings page."));
				RefreshFocusNavigation();
				return;
			}
			ModSettingsPage modSettingsPage = ResolveSelectedPage();
			if (modSettingsPage == null)
			{
				_lastVisibleContentPageKey = null;
				ShowTransientContentState(ModSettingsLocalization.Get("empty.page", "The selected settings page could not be found."));
				RefreshFocusNavigation();
				return;
			}
			string text = CreatePageCacheKey(modSettingsPage.ModId, modSettingsPage.Id);
			if (!_pageContentCaches.TryGetValue(text, out PageContentCache value))
			{
				RefreshFocusNavigation();
				return;
			}
			value.LastUsedMsec = Time.GetTicksMsec();
			RequestMirrorVisibilitySyncRefreshIfNeeded(text);
			bool num = !string.Equals(_lastVisibleContentPageKey, text, StringComparison.OrdinalIgnoreCase);
			_lastVisibleContentPageKey = text;
			if (num && string.IsNullOrWhiteSpace(_selectedSectionId))
			{
				ScheduleContentScrollResetToTop();
			}
			((CanvasItem)value.Root).Visible = true;
			switch (value.State)
			{
			case PageBuildState.NotBuilt:
			case PageBuildState.Failed:
				StartBuildPage(modSettingsPage, value);
				break;
			case PageBuildState.Building:
				ShowContentBuildOverlay();
				RefreshPageHostLayout(value);
				break;
			case PageBuildState.Ready:
				RefreshPageHostLayout(value);
				if (flushRefreshActions)
				{
					FlushRefreshActionsImmediate(includeAllPagesRefresh);
				}
				break;
			}
			RefreshFocusNavigation();
			if (!string.IsNullOrWhiteSpace(_selectedSectionId))
			{
				CallDeferredIfAlive(ScrollToSelectedAnchor);
			}
			SweepPageContentCachePool(text);
		}

		private void SweepPageContentCachePool(string selectedPageKey)
		{
			ulong ticksMsec = Time.GetTicksMsec();
			KeyValuePair<string, PageContentCache>[] array = (from pair in _pageContentCaches
				where !string.Equals(pair.Key, selectedPageKey, StringComparison.OrdinalIgnoreCase)
				orderby pair.Value.LastUsedMsec
				select pair).ToArray();
			int num = Math.Max(0, 1);
			int num2 = Math.Max(0, array.Length - num);
			for (int num3 = 0; num3 < array.Length; num3++)
			{
				KeyValuePair<string, PageContentCache> keyValuePair = array[num3];
				var (pageKey, pageContentCache2) = keyValuePair;
				bool num4 = num3 < num2;
				bool flag = ticksMsec >= pageContentCache2.LastUsedMsec && ticksMsec - pageContentCache2.LastUsedMsec >= 5000;
				if (num4 && flag)
				{
					ReleasePageContentCache(pageKey, pageContentCache2);
				}
			}
		}

		private void ReleasePageContentCache(string pageKey, PageContentCache cache)
		{
			CancelPageBuild(cache);
			cache.RefreshRegistrations.Clear();
			cache.VisibilityTargets.Clear();
			if (GodotObject.IsInstanceValid((GodotObject)(object)cache.Root))
			{
				RecycleReusableEntryNodes((Node)(object)cache.Root);
				((Node)cache.Root).QueueFree();
			}
			_pageContentCaches.Remove(pageKey);
			_reusableEntryNodePool.Sweep();
		}

		private void RequestMirrorVisibilitySyncRefreshIfNeeded(string? selectedPageKey = null)
		{
			if (!TryGetSelectedMirrorSyncPolicy(out var policy) || policy.HasStableExternalSync)
			{
				return;
			}
			string text = selectedPageKey;
			if (string.IsNullOrWhiteSpace(text))
			{
				if (string.IsNullOrWhiteSpace(_selectedModId) || string.IsNullOrWhiteSpace(_selectedPageId))
				{
					return;
				}
				text = CreatePageCacheKey(_selectedModId, _selectedPageId);
			}
			if (!string.Equals(_lastVisibleMirrorRefreshPageKey, text, StringComparison.OrdinalIgnoreCase))
			{
				_lastVisibleMirrorRefreshPageKey = text;
				RequestRefreshAfterDataModelBatchChange();
			}
		}

		private bool TryGetSelectedMirrorSyncPolicy(out ModSettingsMirrorSyncPolicy policy)
		{
			policy = default(ModSettingsMirrorSyncPolicy);
			if (!string.IsNullOrWhiteSpace(_selectedModId) && !string.IsNullOrWhiteSpace(_selectedPageId))
			{
				return ModSettingsMirrorSyncPolicyRegistry.TryGetPolicy(_selectedModId, _selectedPageId, out policy);
			}
			return false;
		}

		private void ShowTransientContentState(string text)
		{
			if (_contentEmptyStateLabel == null || !GodotObject.IsInstanceValid((GodotObject)(object)_contentEmptyStateLabel))
			{
				_contentEmptyStateLabel = CreateEmptyStateLabel(text);
				((Node)_contentList).AddChild((Node)(object)_contentEmptyStateLabel, false, (InternalMode)0);
			}
			else if ((object)((Node)_contentEmptyStateLabel).GetParent() != _contentList)
			{
				((Node)_contentList).AddChild((Node)(object)_contentEmptyStateLabel, false, (InternalMode)0);
			}
			_contentEmptyStateLabel.SetTextAutoSize(text);
			((CanvasItem)_contentEmptyStateLabel).Visible = true;
			foreach (PageContentCache value in _pageContentCaches.Values)
			{
				((CanvasItem)value.Root).Visible = false;
			}
		}

		private void HideTransientContentState()
		{
			if (_contentEmptyStateLabel != null && GodotObject.IsInstanceValid((GodotObject)(object)_contentEmptyStateLabel))
			{
				((CanvasItem)_contentEmptyStateLabel).Visible = false;
			}
		}

		private void ShowContentBuildOverlay()
		{
			if (_contentBuildOverlay != null && GodotObject.IsInstanceValid((GodotObject)(object)_contentBuildOverlay))
			{
				((CanvasItem)_contentBuildOverlay).Visible = true;
				((CanvasItem)_contentBuildOverlay).MoveToFront();
				if (_contentBuildOverlay is ContentBuildOverlay contentBuildOverlay)
				{
					contentBuildOverlay.SetActive(active: true);
				}
				Viewport viewport = ((Node)this).GetViewport();
				Control val = ((viewport != null) ? viewport.GuiGetFocusOwner() : null);
				if (val != null && GodotObject.IsInstanceValid((GodotObject)(object)val) && ((Node)_contentPanelRoot).IsAncestorOf((Node)(object)val))
				{
					GrabControlDeferred(ResolveSidebarTargetMatchingContent());
				}
			}
		}

		private void HideContentBuildOverlay()
		{
			if (_contentBuildOverlay != null && GodotObject.IsInstanceValid((GodotObject)(object)_contentBuildOverlay))
			{
				((CanvasItem)_contentBuildOverlay).Visible = false;
				if (_contentBuildOverlay is ContentBuildOverlay contentBuildOverlay)
				{
					contentBuildOverlay.SetActive(active: false);
				}
			}
		}

		private void RefreshContentBuildOverlayVisibility()
		{
			PageContentCache cache;
			if (!((CanvasItem)this).Visible || !((Node)this).IsInsideTree())
			{
				HideContentBuildOverlay();
			}
			else if (TryGetSelectedPageContentCache(out cache) && cache.State == PageBuildState.Building)
			{
				ShowContentBuildOverlay();
			}
			else
			{
				HideContentBuildOverlay();
			}
		}

		private bool IsContentBuildOverlayVisible()
		{
			if (_contentBuildOverlay != null && GodotObject.IsInstanceValid((GodotObject)(object)_contentBuildOverlay))
			{
				return ((CanvasItem)_contentBuildOverlay).Visible;
			}
			return false;
		}

		private static bool IsSelectedPageInNavSubtree(string? selectedPageId, ModSettingsPage subtreeRoot, IReadOnlyList<ModSettingsPage> pages)
		{
			if (string.IsNullOrWhiteSpace(selectedPageId))
			{
				return false;
			}
			Dictionary<string, ModSettingsPage> dictionary = new Dictionary<string, ModSettingsPage>(StringComparer.OrdinalIgnoreCase);
			foreach (ModSettingsPage page in pages)
			{
				dictionary[page.Id] = page;
			}
			if (!dictionary.TryGetValue(selectedPageId, out var _))
			{
				return false;
			}
			if (string.Equals(selectedPageId, subtreeRoot.Id, StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}
			ModSettingsPage value2 = dictionary[selectedPageId];
			while (!string.IsNullOrWhiteSpace(value2.ParentPageId))
			{
				if (string.Equals(value2.ParentPageId, subtreeRoot.Id, StringComparison.OrdinalIgnoreCase))
				{
					return true;
				}
				if (!dictionary.TryGetValue(value2.ParentPageId, out value2))
				{
					break;
				}
			}
			return false;
		}

		private Func<bool>? CreateSidebarPageVisibilityPredicate(ModSettingsPage page, IReadOnlyList<ModSettingsPage> pages)
		{
			if (page != null && page.VisibleOnHostSurfaces == ModSettingsHostSurface.All && !page.SidebarVisibleOnlyWhenActive && page.VisibleWhen == null)
			{
				IReadOnlyList<ModSettingsSection> sections = page.Sections;
				if (sections != null && sections.Count > 0 && page.Sections.All(delegate(ModSettingsSection section)
				{
					if (section != null && section.VisibleWhen == null && section.VisibleOnHostSurfaces == ModSettingsHostSurface.All)
					{
						IReadOnlyList<ModSettingsEntryDefinition> entries = section.Entries;
						if (entries != null && entries.Count > 0)
						{
							return section.Entries.All((ModSettingsEntryDefinition entry) => !ModSettingsVisibility.RequiresDynamicEvaluation(entry));
						}
					}
					return false;
				}))
				{
					return null;
				}
			}
			return () => IsPageVisibleOnCurrentHost(page) && (!page.SidebarVisibleOnlyWhenActive || IsSelectedPageInNavSubtree(_selectedPageId, page, pages));
		}

		private static Func<bool>? CreateSidebarSectionVisibilityPredicate(ModSettingsPage page, ModSettingsSection section)
		{
			return ModSettingsVisibility.CreateSectionVisibilityPredicate(page, section);
		}

		private void StartBuildPage(ModSettingsPage page, PageContentCache cache)
		{
			PageBuildState state = cache.State;
			if ((uint)(state - 1) > 1u)
			{
				CancelPageBuild(cache);
				cache.State = PageBuildState.Building;
				if (IsPageCurrentlySelected(cache))
				{
					ShowContentBuildOverlay();
				}
				int buildVersion = cache.BuildVersion;
				CancellationTokenSource cts = (cache.BuildCancellation = new CancellationTokenSource());
				cache.BuildTask = BuildPageAsync(page, cache, buildVersion, cts);
				ObserveBackgroundUiTask(cache.BuildTask, "build_page:" + page.ModId + ":" + page.Id);
			}
		}

		private async Task BuildPageAsync(ModSettingsPage page, PageContentCache cache, int buildVersion, CancellationTokenSource cts)
		{
			CancellationToken ct = cts.Token;
			IDisposable layoutDefer = null;
			try
			{
				await YieldPageBuildAsync(cache, buildVersion, ct);
				cache.RefreshRegistrations.Clear();
				cache.VisibilityTargets.Clear();
				cache.EntryAnchors.Clear();
				ClearHostChildren((Node)(object)cache.HeaderHost);
				ClearHostChildren((Node)(object)cache.ContentHost);
				ModSettingsUiContext context = new ModSettingsUiContext(this, cache.PageKey, cache.EnableGate);
				bool flag = !string.IsNullOrWhiteSpace(page.ParentPageId);
				Action onBack = (flag ? ((Action)delegate
				{
					_selectedPageId = page.ParentPageId;
					_selectionDirty = true;
					EnsureUiUpToDate();
				}) : ((Action)delegate
				{
				}));
				try
				{
					Control val = ModSettingsUiFactory.CreateModSettingsPageHeaderBar(context, page, flag, onBack);
					val.SizeFlagsHorizontal = (SizeFlags)3;
					((Node)cache.HeaderHost).AddChild((Node)(object)val, false, (InternalMode)0);
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[Settings] Failed to build page header '{page.ModId}:{page.Id}': {ex.Message}", 1);
					((Node)cache.HeaderHost).AddChild((Node)(object)ModSettingsUiFactory.CreateBuildErrorPlaceholder(ModSettingsLocalization.Get("page.failed.title", "Page failed to load"), string.Format(ModSettingsLocalization.Get("page.failed.body", "Failed to build page '{0}'."), page.Id)), false, (InternalMode)0);
				}
				layoutDefer = ModSettingsUiFactory.FastVerticalStack.DeferLayoutRequests();
				ulong ticksMsec = Time.GetTicksMsec();
				foreach (ModSettingsUiFactory.PageBuildItem item in ModSettingsUiFactory.CreatePageBuildItems(context, page, _reusableEntryNodePool))
				{
					ThrowIfPageBuildCanceled(cache, buildVersion, ct);
					((Node)(item.Parent ?? cache.ContentHost)).AddChild((Node)(object)item.Control, false, (InternalMode)0);
					item.AfterAdded?.Invoke(item.Control);
					if (Time.GetTicksMsec() - ticksMsec >= 6)
					{
						layoutDefer.Dispose();
						layoutDefer = null;
						RefreshPageHostLayout(cache);
						await YieldPageBuildAsync(cache, buildVersion, ct);
						layoutDefer = ModSettingsUiFactory.FastVerticalStack.DeferLayoutRequests();
						ticksMsec = Time.GetTicksMsec();
					}
				}
				layoutDefer.Dispose();
				layoutDefer = null;
				ThrowIfPageBuildCanceled(cache, buildVersion, ct);
				if (IsPageCurrentlySelected(cache))
				{
					((CanvasItem)cache.Root).Visible = true;
					((CanvasItem)cache.Root).Modulate = Colors.White;
				}
				else
				{
					((CanvasItem)cache.Root).Visible = false;
				}
				RefreshPageHostLayout(cache);
				CompletePageBuild(page, cache);
			}
			catch (OperationCanceledException)
			{
				if (cache.BuildCancellation == cts && cache.State == PageBuildState.Building)
				{
					cache.State = PageBuildState.NotBuilt;
				}
			}
			catch (Exception ex3)
			{
				if (cache.BuildCancellation != cts)
				{
					return;
				}
				cache.State = PageBuildState.Failed;
				RitsuLibFramework.Logger.Warn($"[Settings] Failed to build page '{page.ModId}:{page.Id}': {ex3.Message}", 1);
				ClearHostChildren((Node)(object)cache.ContentHost);
				((Node)cache.ContentHost).AddChild((Node)(object)ModSettingsUiFactory.CreateBuildErrorPlaceholder(ModSettingsLocalization.Get("page.failed.title", "Page failed to load"), string.Format(ModSettingsLocalization.Get("page.failed.body", "Failed to build page '{0}'."), page.Id)), false, (InternalMode)0);
				if (IsPageCurrentlySelected(cache))
				{
					((CanvasItem)cache.Root).Visible = true;
					((CanvasItem)cache.Root).Modulate = Colors.White;
					RefreshPageHostLayout(cache);
					FlushRefreshActionsImmediate();
					RefreshSelectionState();
				}
				else
				{
					if (GodotObject.IsInstanceValid((GodotObject)(object)cache.Root))
					{
						((CanvasItem)cache.Root).Visible = false;
					}
					RefreshPageHostLayout(cache);
				}
			}
			finally
			{
				layoutDefer?.Dispose();
				if (cache.BuildCancellation == cts)
				{
					cache.BuildCancellation = null;
					cache.BuildTask = null;
				}
				cts.Dispose();
				RefreshContentBuildOverlayVisibility();
			}
		}

		private void ClearHostChildren(Node host)
		{
			Node[] array = ((IEnumerable<Node>)host.GetChildren(false)).ToArray();
			foreach (Node val in array)
			{
				if (val is ModSettingsUiFactory.ReusableSettingLine line)
				{
					_reusableEntryNodePool.Return(line);
					continue;
				}
				if (val != null)
				{
					RecycleReusableEntryNodes(val);
				}
				if (((val != null) ? val.GetParent() : null) == host)
				{
					host.RemoveChild(val);
				}
				if (val != null)
				{
					val.QueueFree();
				}
			}
		}

		private static void CancelPageBuild(PageContentCache cache)
		{
			cache.BuildVersion++;
			cache.BuildCancellation?.Cancel();
			if (cache.State == PageBuildState.Building)
			{
				cache.State = PageBuildState.NotBuilt;
			}
		}

		private async Task YieldPageBuildAsync(PageContentCache cache, int buildVersion, CancellationToken ct)
		{
			ThrowIfPageBuildCanceled(cache, buildVersion, ct);
			await RitsuGodotAwaitSafety.AwaitProcessFrameAsync(((Node)this).GetTree(), (GodotObject?)(object)this, ct);
			ThrowIfPageBuildCanceled(cache, buildVersion, ct);
		}

		private static void ThrowIfPageBuildCanceled(PageContentCache cache, int buildVersion, CancellationToken ct)
		{
			ct.ThrowIfCancellationRequested();
			if (buildVersion != cache.BuildVersion || !GodotObject.IsInstanceValid((GodotObject)(object)cache.Root))
			{
				throw new OperationCanceledException(ct);
			}
		}

		private void CompletePageBuild(ModSettingsPage page, PageContentCache cache)
		{
			cache.State = PageBuildState.Ready;
			if (page.EnabledWhen != null)
			{
				bool enabled = ModSettingsPredicate.Evaluate(page.EnabledWhen);
				ModSettingsUiFactory.ApplyEnabledRecursive((Node)(object)cache.HeaderHost, cache.EnableGate, enabled);
				ModSettingsUiFactory.ApplyEnabledRecursive((Node)(object)cache.ContentHost, cache.EnableGate, enabled);
				RegisterRefreshAction(delegate
				{
					bool enabled2 = ModSettingsPredicate.Evaluate(page.EnabledWhen);
					ModSettingsUiFactory.ApplyEnabledRecursive((Node)(object)cache.HeaderHost, cache.EnableGate, enabled2);
					ModSettingsUiFactory.ApplyEnabledRecursive((Node)(object)cache.ContentHost, cache.EnableGate, enabled2);
				}, ModSettingsUiRefreshSpec.Always, cache.PageKey);
			}
			if (IsPageCurrentlySelected(cache))
			{
				FlushRefreshActionsImmediate(includeAllPages: false, emptyDirtyIsFullPass: false);
				RefreshSelectionState();
				RefreshFocusNavigation();
				CallDeferredIfAlive(ScrollToSelectedAnchor);
			}
		}

		private ModSettingsPage? ResolveSelectedPage()
		{
			return ModSettingsRegistry.GetPages().FirstOrDefault((ModSettingsPage page) => string.Equals(page.ModId, _selectedModId, StringComparison.OrdinalIgnoreCase) && string.Equals(page.Id, _selectedPageId, StringComparison.OrdinalIgnoreCase) && IsPageVisibleOnCurrentHost(page));
		}

		private static bool IsPageVisibleOnCurrentHost(ModSettingsPage page)
		{
			return ModSettingsVisibility.IsPageVisible(page);
		}

		private void RefreshPageHostLayout(PageContentCache cache)
		{
			if (GodotObject.IsInstanceValid((GodotObject)(object)cache.Root))
			{
				cache.HeaderHost.UpdateMinimumSize();
				cache.ContentHost.UpdateMinimumSize();
				if (cache.HeaderHost is ModSettingsUiFactory.FastVerticalStack fastVerticalStack)
				{
					fastVerticalStack.RequestLayout();
				}
				if (cache.ContentHost is ModSettingsUiFactory.FastVerticalStack fastVerticalStack2)
				{
					fastVerticalStack2.RequestLayout();
				}
				if (cache.Root is ModSettingsUiFactory.FastVerticalStack fastVerticalStack3)
				{
					fastVerticalStack3.RequestLayout();
				}
				ApplyContentViewportWidth();
				_contentList.RequestLayout();
				((Container)_scrollContainer).QueueSort();
				RefreshContentLayout();
				QueueDeferredContentLayoutRefresh();
			}
		}

		private void RecycleReusableEntryNodes(Node root)
		{
			Node[] array = ((IEnumerable<Node>)root.GetChildren(false)).ToArray();
			foreach (Node val in array)
			{
				if (val is ModSettingsUiFactory.ReusableSettingLine line)
				{
					_reusableEntryNodePool.Return(line);
				}
				else if (val != null)
				{
					RecycleReusableEntryNodes(val);
				}
			}
		}

		private static string ResolvePageTabTitle(ModSettingsPage page)
		{
			return ModSettingsLocalization.ResolvePageDisplayName(page);
		}

		private static string ResolveSidebarModTitle(IReadOnlyList<ModSettingsPage> pages)
		{
			string modId = pages[0].ModId;
			return ModSettingsLocalization.ResolveModName(modId, modId);
		}

		private static ModSettingsSidebarTooltipInfo ResolveSidebarModTooltipInfo(string modId, string displayName, IReadOnlyList<ModSettingsPage> pages)
		{
			foreach (Assembly item in (from page in pages
				where page.UseSourceAssemblyManifestLookup && page.SourceAssembly != null
				select page.SourceAssembly).Distinct())
			{
				if (Sts2ModManagerCompat.TryGetBestModPresentationInfoForAssembly(item, out RitsuModPresentationInfo info) && info != null)
				{
					return new ModSettingsSidebarTooltipInfo(modId, string.IsNullOrWhiteSpace(info.Name) ? displayName : info.Name, info.Author, info.Version, info.Description, info.ModImagePath);
				}
			}
			if (!Sts2ModManagerCompat.TryGetBestModPresentationInfo(modId, out RitsuModPresentationInfo info2) || !(info2 != null))
			{
				return new ModSettingsSidebarTooltipInfo(modId, displayName, null, null, null, null);
			}
			return new ModSettingsSidebarTooltipInfo(modId, string.IsNullOrWhiteSpace(info2.Name) ? displayName : info2.Name, info2.Author, info2.Version, info2.Description, info2.ModImagePath);
		}

