		private void RefreshQuickSearchResults()
		{
			if (_quickSearchResultsHost != null && _quickSearchEdit != null)
			{
				CancelQuickSearch();
				ClearQuickSearchResults();
				string text = _quickSearchEdit.Text.Trim();
				if (text.Length == 0)
				{
					_quickSearchResults = Array.Empty<ModSettingsSearchResult>();
					_quickSearchSelectedIndex = -1;
					AddQuickSearchStatus(ModSettingsLocalization.Get("search.start", "Type a setting name or description to find its destination."));
				}
				else
				{
					int quickSearchRefreshEpoch = _quickSearchRefreshEpoch;
					_quickSearchCancellation = new CancellationTokenSource();
					AddQuickSearchStatus(FormatQuickSearchProgress(0, _quickSearchIndex.Count));
					ObserveBackgroundUiTask(RefreshQuickSearchResultsAsync(text, quickSearchRefreshEpoch, _quickSearchCancellation.Token), "quick_search:" + text);
				}
			}
		}

		private async Task RefreshQuickSearchResultsAsync(string query, int epoch, CancellationToken cancellationToken)
		{
			await foreach (ModSettingsSearchBatch item in ModSettingsSearchIndex.SearchStreamAsync(_quickSearchIndex, query, 40, cancellationToken))
			{
				if (_quickSearchOpen && epoch == _quickSearchRefreshEpoch && !cancellationToken.IsCancellationRequested)
				{
					RenderQuickSearchBatch(item);
					continue;
				}
				break;
			}
		}

		private void RenderQuickSearchBatch(ModSettingsSearchBatch batch)
		{
			//IL_00bd: Unknown result type (might be due to invalid IL or missing references)
			if (_quickSearchResultsHost == null)
			{
				return;
			}
			ClearQuickSearchResults();
			_quickSearchResults = batch.Results;
			if (_quickSearchResults.Count == 0)
			{
				_quickSearchSelectedIndex = -1;
				AddQuickSearchStatus(batch.IsComplete ? ModSettingsLocalization.Get("search.empty", "No matching settings found.") : FormatQuickSearchProgress(batch.ProcessedCount, batch.TotalCount));
				return;
			}
			for (int i = 0; i < _quickSearchResults.Count; i++)
			{
				int capturedIndex = i;
				ModSettingsSearchResult modSettingsSearchResult = _quickSearchResults[i];
				ModSettingsSidebarButton modSettingsSidebarButton = new ModSettingsSidebarButton(modSettingsSearchResult.Title + "\n" + modSettingsSearchResult.Path, delegate
				{
					OpenQuickSearchResult(capturedIndex);
				}, ModSettingsSidebarItemKind.Utility);
				((Control)modSettingsSidebarButton).CustomMinimumSize = new Vector2(0f, 62f);
				((Control)modSettingsSidebarButton).TooltipText = modSettingsSearchResult.Title + "\n" + modSettingsSearchResult.Path;
				ModSettingsSidebarButton modSettingsSidebarButton2 = modSettingsSidebarButton;
				((Control)modSettingsSidebarButton2).MouseEntered += delegate
				{
					SetQuickSearchSelection(capturedIndex, ensureVisible: false);
				};
				((Node)_quickSearchResultsHost).AddChild((Node)(object)modSettingsSidebarButton2, false, (InternalMode)0);
				_quickSearchResultButtons.Add(modSettingsSidebarButton2);
			}
			SetQuickSearchSelection(0, ensureVisible: false);
			if (!batch.IsComplete)
			{
				AddQuickSearchStatus(FormatQuickSearchProgress(batch.ProcessedCount, batch.TotalCount));
			}
			else if (batch.HasMore)
			{
				AddQuickSearchStatus(string.Format(ModSettingsLocalization.Get("search.more", "Showing the first {0} matches. More are available."), 40));
			}
		}

