	internal sealed class AutoSaveModSettingsValueBinding<TValue>(IModSettingsValueBinding<TValue> inner) : IModSettingsValueBinding<TValue>, IModSettingsBinding, IModSettingsUiRefreshEquivalence, IModSettingsBindingSaveDispatch
	{
		IReadOnlyList<IModSettingsBinding> IModSettingsBindingSaveDispatch.ImmediateSaveTargets => new <>z__ReadOnlySingleElementList<IModSettingsBinding>(inner);

		public IReadOnlyList<IModSettingsBinding> UiRefreshAlsoTreatAsDirty { get; } = BuildUiRefreshEquivalenceChain(inner);

		public SaveScope Scope => inner.Scope;

		public string ModId => inner.ModId;

		public string DataKey => inner.DataKey;

		public TValue Read()
		{
			return inner.Read();
		}

		public void Write(TValue value)
		{
			inner.Write(value);
			ModSettingsBindingWriteEvents.NotifyValueWritten(this);
			if (!(inner is ITransientModSettingsBinding))
			{
				inner.Save();
			}
		}

		public void Save()
		{
			if (!(inner is ITransientModSettingsBinding))
			{
				inner.Save();
			}
		}

		private static IReadOnlyList<IModSettingsBinding> BuildUiRefreshEquivalenceChain(IModSettingsValueBinding<TValue> root)
		{
			List<IModSettingsBinding> list = new List<IModSettingsBinding>(8);
			Append(root);
			return list;
			void Append(IModSettingsBinding node)
			{
				if (!list.Contains(node))
				{
					list.Add(node);
					if (node is IModSettingsUiRefreshEquivalence modSettingsUiRefreshEquivalence)
					{
						foreach (IModSettingsBinding item in modSettingsUiRefreshEquivalence.UiRefreshAlsoTreatAsDirty)
						{
							Append(item);
						}
					}
				}
			}
		}
	}
