	internal static class ModSettingsBindingFlushPlanner
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Selects dirty bindings that are not immediate save targets of another dirty binding. Saving only
		///         these roots prevents decorator chains from persisting the same logical setting more than once.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         选择不是其他脏绑定直接保存目标的脏绑定。仅保存这些根绑定可避免装饰器链重复持久化同一逻辑设置。
		///     </para>
		/// </summary>
		internal static List<IModSettingsBinding> SelectEffectiveSaveRoots(HashSet<IModSettingsBinding> dirty)
		{
			if (dirty.Count == 0)
			{
				return new List<IModSettingsBinding>();
			}
			HashSet<IModSettingsBinding> covered = new HashSet<IModSettingsBinding>(ModSettingsBindingReferenceEquality.Instance);
			foreach (IModSettingsBinding item in dirty)
			{
				if (!(item is IModSettingsBindingSaveDispatch modSettingsBindingSaveDispatch))
				{
					continue;
				}
				foreach (IModSettingsBinding immediateSaveTarget in modSettingsBindingSaveDispatch.ImmediateSaveTargets)
				{
					if (dirty.Contains(immediateSaveTarget))
					{
						covered.Add(immediateSaveTarget);
					}
				}
			}
			List<IModSettingsBinding> list = new List<IModSettingsBinding>(dirty.Count);
			list.AddRange(dirty.Where((IModSettingsBinding binding) => !covered.Contains(binding)));
			return list;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Expands refresh invalidation through binding-equivalence and UI-propagation relationships so selective
	///         refresh rules account for related decorators without listing each one explicitly.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         沿绑定等价关系和界面传播关系扩展刷新失效集合，使选择性刷新规则无须逐一列出即可涵盖相关装饰器。
	///     </para>
	/// </summary>
	internal static class ModSettingsBindingInvalidationTopology
	{
		internal static HashSet<IModSettingsBinding> ExpandClosure(IModSettingsBinding seed)
		{
			HashSet<IModSettingsBinding> hashSet = new HashSet<IModSettingsBinding>(ModSettingsBindingReferenceEquality.Instance);
			Queue<IModSettingsBinding> queue = new Queue<IModSettingsBinding>();
			queue.Enqueue(seed);
			while (queue.Count > 0)
			{
				IModSettingsBinding modSettingsBinding = queue.Dequeue();
				if (!hashSet.Add(modSettingsBinding))
				{
					continue;
				}
				if (modSettingsBinding is IModSettingsUiRefreshEquivalence modSettingsUiRefreshEquivalence)
				{
					foreach (IModSettingsBinding item in modSettingsUiRefreshEquivalence.UiRefreshAlsoTreatAsDirty)
					{
						queue.Enqueue(item);
					}
				}
				if (!(modSettingsBinding is IModSettingsUiRefreshPropagation modSettingsUiRefreshPropagation))
				{
					continue;
				}
				foreach (IModSettingsBinding item2 in modSettingsUiRefreshPropagation.ExtraBindingsToMarkDirtyForUi)
				{
					queue.Enqueue(item2);
				}
			}
			return hashSet;
		}

		internal static HashSet<IModSettingsBinding> ExpandUnion(IEnumerable<IModSettingsBinding> seeds)
		{
			HashSet<IModSettingsBinding> hashSet = new HashSet<IModSettingsBinding>(ModSettingsBindingReferenceEquality.Instance);
			foreach (IModSettingsBinding seed in seeds)
			{
				foreach (IModSettingsBinding item in ExpandClosure(seed))
				{
					hashSet.Add(item);
				}
			}
			return hashSet;
		}
	}
