	/// <summary>
	///     <para xml:lang="en">
	///         Publishes notifications after built-in <see cref="T:STS2RitsuLib.Settings.IModSettingsValueBinding`1" /> implementations
	///         finish writing their backing values. This supports settings UI refresh and external value mirrors.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在内置 <see cref="T:STS2RitsuLib.Settings.IModSettingsValueBinding`1" /> 实现完成底层值写入后发布通知，
	///         用于设置界面刷新以及与外部值保持同步。
	///     </para>
	/// </summary>
	public static class ModSettingsBindingWriteEvents
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Occurs synchronously after a binding updates its backing value. Subscriber failures are logged and do
		///         not prevent later subscribers from running.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在绑定更新底层值后同步发生。订阅者失败会被记录，且不会阻止后续订阅者运行。
		///     </para>
		/// </summary>
		public static event Action<IModSettingsBinding>? ValueWritten;

		internal static void NotifyValueWritten(IModSettingsBinding binding)
		{
			Delegate[] array = ValueWritten?.GetInvocationList();
			if (array == null)
			{
				return;
			}
			Delegate[] array2 = array;
			foreach (Delegate obj in array2)
			{
				try
				{
					((Action<IModSettingsBinding>)obj)(binding);
				}
				catch (Exception value)
				{
					RitsuLibFramework.Logger.Warn($"[ModSettings] ValueWritten callback failed for '{binding.GetType().FullName}': {value}", 1);
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Subscribes a listener while a Godot node remains in the scene tree and automatically removes the same
		///         delegate when that node exits the tree.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 Godot 节点留在场景树中期间订阅监听器，并在该节点退出场景树时自动移除同一委托。
		///     </para>
		/// </summary>
		/// <param name="anchor">
		///     <para xml:lang="en">The node whose scene-tree lifetime controls the subscription.</para>
		///     <para xml:lang="zh-CN">以其场景树生命周期控制订阅的节点。</para>
		/// </param>
		/// <param name="listener">
		///     <para xml:lang="en">The listener invoked after a binding value is written.</para>
		///     <para xml:lang="zh-CN">绑定值写入后调用的监听器。</para>
		/// </param>
		public static void SubscribeValueWrittenWhileNodeAlive(Node anchor, Action<IModSettingsBinding> listener)
		{
			//IL_005c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0062: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(anchor, "anchor");
			ArgumentNullException.ThrowIfNull(listener, "listener");
			ValueWritten += Wrapped;
			try
			{
				((GodotObject)anchor).Connect(SignalName.TreeExiting, Callable.From((Action)delegate
				{
					ValueWritten -= Wrapped;
				}), 4u);
			}
			catch
			{
				ValueWritten -= Wrapped;
				throw;
			}
			void Wrapped(IModSettingsBinding binding)
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)anchor))
				{
					listener(binding);
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Binds a mod setting to custom read, write, and save callbacks instead of
	///         <see cref="M:STS2RitsuLib.RitsuLibFramework.GetDataStore(System.String)" />, for example when using a BaseLib JSON configuration or a
	///         third-party store.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过自定义读取、写入和保存回调绑定模组设置，而不使用
	///         <see cref="M:STS2RitsuLib.RitsuLibFramework.GetDataStore(System.String)" />；例如可用于 BaseLib JSON 配置或第三方存储。
	///     </para>
	/// </summary>
	/// <typeparam name="T">
	///     <para xml:lang="en">The setting value type.</para>
	///     <para xml:lang="zh-CN">设置值类型。</para>
	/// </typeparam>
	/// <param name="modId">
	///     <para xml:lang="en">The ID of the mod that owns the setting.</para>
	///     <para xml:lang="zh-CN">所属模组的 ID。</para>
	/// </param>
	/// <param name="dataKey">
	///     <para xml:lang="en">The stable key that identifies the setting within the mod.</para>
	///     <para xml:lang="zh-CN">在模组内标识该设置的稳定键。</para>
	/// </param>
	/// <param name="scope">
	///     <para xml:lang="en">The save scope represented by the binding.</para>
	///     <para xml:lang="zh-CN">该绑定所表示的保存作用域。</para>
	/// </param>
	/// <param name="read">
	///     <para xml:lang="en">The callback that reads the current value.</para>
	///     <para xml:lang="zh-CN">读取当前值的回调。</para>
	/// </param>
	/// <param name="write">
	///     <para xml:lang="en">The callback that writes a new value.</para>
	///     <para xml:lang="zh-CN">写入新值的回调。</para>
	/// </param>
	/// <param name="save">
	///     <para xml:lang="en">The callback that persists the current value.</para>
	///     <para xml:lang="zh-CN">持久化当前值的回调。</para>
	/// </param>
	public sealed class ModSettingsCallbackValueBinding<T>(string modId, string dataKey, SaveScope scope, Func<T> read, Action<T> write, Action save) : IModSettingsValueBinding<T>, IModSettingsBinding
	{
		private readonly Func<T> _read = ModSettingsBindingValidation.RequireNonNull(read, "read");

		private readonly Action _save = ModSettingsBindingValidation.RequireNonNull(save, "save");

		private readonly Action<T> _write = ModSettingsBindingValidation.RequireNonNull(write, "write");

		/// <inheritdoc />
		public string ModId { get; } = ModSettingsBindingValidation.RequireNonEmpty(modId, "modId");

		/// <inheritdoc />
		public string DataKey { get; } = ModSettingsBindingValidation.RequireNonEmpty(dataKey, "dataKey");

		/// <inheritdoc />
		public SaveScope Scope { get; } = scope;

		/// <inheritdoc />
		public T Read()
		{
			return _read();
		}

		/// <inheritdoc />
		public void Write(T value)
		{
			_write(value);
			ModSettingsBindingWriteEvents.NotifyValueWritten(this);
		}

		/// <inheritdoc />
		public void Save()
		{
			_save();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Adapts an <see cref="T:System.Int32" /> binding to the <see cref="T:System.Double" /> slider API on
	///         <see cref="T:STS2RitsuLib.Settings.ModSettingsSectionBuilder" />, rounding each written value to an integer.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将 <see cref="T:System.Int32" /> 绑定适配到 <see cref="T:STS2RitsuLib.Settings.ModSettingsSectionBuilder" /> 的
	///         <see cref="T:System.Double" /> 滑块 API，并将每个写入值舍入为整数。
	///     </para>
	/// </summary>
	/// <param name="inner">
	///     <para xml:lang="en">The integer binding to adapt.</para>
	///     <para xml:lang="zh-CN">要适配的整数绑定。</para>
	/// </param>
	public sealed class ModSettingsDoubleFromIntBinding(IModSettingsValueBinding<int> inner) : IModSettingsValueBinding<double>, IModSettingsBinding, IModSettingsBindingSaveDispatch
	{
		private readonly IModSettingsValueBinding<int> _inner = ModSettingsBindingValidation.RequireNonNull(inner, "inner");

		IReadOnlyList<IModSettingsBinding> IModSettingsBindingSaveDispatch.ImmediateSaveTargets => new <>z__ReadOnlySingleElementList<IModSettingsBinding>(_inner);

		/// <inheritdoc />
		public string ModId => _inner.ModId;

		/// <inheritdoc />
		public string DataKey => _inner.DataKey;

		/// <inheritdoc />
