		{
			_inner.Save();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Adapts a <see cref="T:System.Double" /> binding to
	///         <see cref="M:STS2RitsuLib.Settings.ModSettingsSectionBuilder.AddIntSlider(System.String,STS2RitsuLib.Settings.ModSettingsText,STS2RitsuLib.Settings.IModSettingsValueBinding{System.Int32},System.Int32,System.Int32,System.Int32,System.Func{System.Int32,System.String},STS2RitsuLib.Settings.ModSettingsText)" />, rounding reads to an integer and writing integer
	///         values back as doubles.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将 <see cref="T:System.Double" /> 绑定适配到 <see cref="M:STS2RitsuLib.Settings.ModSettingsSectionBuilder.AddIntSlider(System.String,STS2RitsuLib.Settings.ModSettingsText,STS2RitsuLib.Settings.IModSettingsValueBinding{System.Int32},System.Int32,System.Int32,System.Int32,System.Func{System.Int32,System.String},STS2RitsuLib.Settings.ModSettingsText)" />；
	///         读取时舍入为整数，写入时将整数值作为双精度值传回。
	///     </para>
	/// </summary>
	/// <param name="inner">
	///     <para xml:lang="en">The double binding to adapt.</para>
	///     <para xml:lang="zh-CN">要适配的双精度浮点绑定。</para>
