	public sealed class ModSettingsIntFromDoubleBinding(IModSettingsValueBinding<double> inner) : IModSettingsValueBinding<int>, IModSettingsBinding, IModSettingsBindingSaveDispatch
	{
		private readonly IModSettingsValueBinding<double> _inner = ModSettingsBindingValidation.RequireNonNull(inner, "inner");

		IReadOnlyList<IModSettingsBinding> IModSettingsBindingSaveDispatch.ImmediateSaveTargets => new <>z__ReadOnlySingleElementList<IModSettingsBinding>(_inner);

		/// <inheritdoc />
		public string ModId => _inner.ModId;

		/// <inheritdoc />
