		{
			_inner.Save();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Reads and writes one value in a persisted <typeparamref name="TModel" /> through the owning mod's data
	///         store.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过所属模组的数据存储读写持久化 <typeparamref name="TModel" /> 中的一个值。
	///     </para>
	/// </summary>
	/// <typeparam name="TModel">
	///     <para xml:lang="en">The persisted model type.</para>
	///     <para xml:lang="zh-CN">持久化模型类型。</para>
	/// </typeparam>
	/// <typeparam name="TValue">
	///     <para xml:lang="en">The bound value type.</para>
	///     <para xml:lang="zh-CN">绑定值类型。</para>
	/// </typeparam>
	/// <param name="modId">
	///     <para xml:lang="en">The ID of the mod that owns the model.</para>
	///     <para xml:lang="zh-CN">所属模组的 ID。</para>
	/// </param>
	/// <param name="dataKey">
	///     <para xml:lang="en">The persisted model's data key.</para>
	///     <para xml:lang="zh-CN">持久化模型的数据键。</para>
	/// </param>
	/// <param name="scope">
	///     <para xml:lang="en">The model's save scope.</para>
	///     <para xml:lang="zh-CN">模型的保存作用域。</para>
	/// </param>
	/// <param name="getter">
	///     <para xml:lang="en">The function that reads the value from the model.</para>
	///     <para xml:lang="zh-CN">从模型读取值的函数。</para>
	/// </param>
	/// <param name="setter">
	///     <para xml:lang="en">The callback that writes the value into the model.</para>
	///     <para xml:lang="zh-CN">将值写入模型的回调。</para>
	/// </param>
	public sealed class ModSettingsValueBinding<TModel, TValue>(string modId, string dataKey, SaveScope scope, Func<TModel, TValue> getter, Action<TModel, TValue> setter) : IModSettingsValueBinding<TValue>, IModSettingsBinding where TModel : class, new()
	{
		private readonly Func<TModel, TValue> _getter = ModSettingsBindingValidation.RequireNonNull(getter, "getter");

		private readonly Action<TModel, TValue> _setter = ModSettingsBindingValidation.RequireNonNull(setter, "setter");

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the mod ID used to resolve <see cref="M:STS2RitsuLib.RitsuLibFramework.GetDataStore(System.String)" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取用于解析 <see cref="M:STS2RitsuLib.RitsuLibFramework.GetDataStore(System.String)" /> 的模组 ID。
		///     </para>
		/// </summary>
		public string ModId { get; } = ModSettingsBindingValidation.RequireNonEmpty(modId, "modId");

		/// <summary>
		///     <para xml:lang="en">Gets the persisted model's data key.</para>
		///     <para xml:lang="zh-CN">获取持久化模型的数据键。</para>
		/// </summary>
		public string DataKey { get; } = ModSettingsBindingValidation.RequireNonEmpty(dataKey, "dataKey");

		/// <summary>
		///     <para xml:lang="en">Gets the save scope of the backing data-store entry.</para>
		///     <para xml:lang="zh-CN">获取底层数据存储条目的保存作用域。</para>
		/// </summary>
		public SaveScope Scope { get; } = scope;

		/// <summary>
		///     <para xml:lang="en">Reads the current value from the stored model.</para>
		///     <para xml:lang="zh-CN">从已存储的模型读取当前值。</para>
		/// </summary>
		public TValue Read()
		{
			ModDataStore dataStore = RitsuLibFramework.GetDataStore(ModId);
			return _getter(dataStore.Get<TModel>(DataKey));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Writes the value to the in-memory model. Call <see cref="M:STS2RitsuLib.Settings.ModSettingsValueBinding`2.Save" /> to persist the model's data key.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将值写入内存中的模型。调用 <see cref="M:STS2RitsuLib.Settings.ModSettingsValueBinding`2.Save" /> 可持久化该模型的数据键。
		///     </para>
		/// </summary>
		public void Write(TValue value)
		{
			RitsuLibFramework.GetDataStore(ModId).Modify(DataKey, delegate(TModel model)
			{
				_setter(model, value);
			});
			ModSettingsBindingWriteEvents.NotifyValueWritten(this);
		}

		/// <summary>
		///     <para xml:lang="en">Persists this binding's data key through the owning mod's data store.</para>
		///     <para xml:lang="zh-CN">通过所属模组的数据存储持久化该绑定的数据键。</para>
		/// </summary>
		public void Save()
		{
			RitsuLibFramework.GetDataStore(ModId).Save(DataKey);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Stores a transient setting in memory for previews, tests, or temporary UI and provides a JSON adapter for
	///         cloning and clipboard operations.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为预览、测试或临时界面在内存中保存瞬时设置，并提供用于克隆与剪贴板操作的 JSON 适配器。
	///     </para>
	/// </summary>
	/// <typeparam name="TValue">
	///     <para xml:lang="en">The setting value type.</para>
	///     <para xml:lang="zh-CN">设置值类型。</para>
	/// </typeparam>
	/// <param name="modId">
	///     <para xml:lang="en">The logical owning mod ID used for UI identity.</para>
	///     <para xml:lang="zh-CN">用于界面标识的逻辑所属模组 ID。</para>
	/// </param>
	/// <param name="dataKey">
	///     <para xml:lang="en">The logical data key used for UI identity.</para>
	///     <para xml:lang="zh-CN">用于界面标识的逻辑数据键。</para>
	/// </param>
	/// <param name="initialValue">
	///     <para xml:lang="en">The initial value and source for future default-value clones.</para>
	///     <para xml:lang="zh-CN">初始值，也是之后创建默认值副本的来源。</para>
	/// </param>
	public sealed class InMemoryModSettingsValueBinding<TValue>(string modId, string dataKey, TValue initialValue) : IStructuredModSettingsValueBinding<TValue>, IModSettingsValueBinding<TValue>, IModSettingsBinding, ITransientModSettingsBinding, IDefaultModSettingsValueBinding<TValue>
	{
		private readonly TValue _defaultValue = initialValue;

		private TValue _value = initialValue;

		/// <summary>
		///     <para xml:lang="en">Gets the logical mod ID used for UI identity; it is not persisted.</para>
		///     <para xml:lang="zh-CN">获取用于界面标识的逻辑模组 ID；该 ID 不会被持久化。</para>
		/// </summary>
		public string ModId { get; } = ModSettingsBindingValidation.RequireNonEmpty(modId, "modId");

		/// <summary>
		///     <para xml:lang="en">Gets the logical data key used for UI identity.</para>
		///     <para xml:lang="zh-CN">获取用于界面标识的逻辑数据键。</para>
		/// </summary>
		public string DataKey { get; } = ModSettingsBindingValidation.RequireNonEmpty(dataKey, "dataKey");

		/// <summary>
		///     <para xml:lang="en">
		///         Gets <see cref="F:STS2RitsuLib.Utils.Persistence.SaveScope.Global" /> for interface compatibility. <see cref="M:STS2RitsuLib.Settings.InMemoryModSettingsValueBinding`1.Save" /> performs no
		///         operation.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为满足接口约定而返回 <see cref="F:STS2RitsuLib.Utils.Persistence.SaveScope.Global" />；<see cref="M:STS2RitsuLib.Settings.InMemoryModSettingsValueBinding`1.Save" /> 不执行任何操作。
		///     </para>
		/// </summary>
		public SaveScope Scope => SaveScope.Global;

		/// <summary>
		///     <para xml:lang="en">Gets the JSON adapter used for cloning and clipboard operations.</para>
		///     <para xml:lang="zh-CN">获取用于克隆与剪贴板操作的 JSON 适配器。</para>
		/// </summary>
		public IStructuredModSettingsValueAdapter<TValue> Adapter { get; } = ModSettingsStructuredData.Json<TValue>();

		/// <inheritdoc />
		public TValue CreateDefaultValue()
		{
			return Adapter.Clone(_defaultValue);
		}

		/// <summary>
		///     <para xml:lang="en">Reads the current in-memory value.</para>
		///     <para xml:lang="zh-CN">读取当前内存值。</para>
		/// </summary>
		public TValue Read()
		{
			return _value;
		}

		/// <summary>
		///     <para xml:lang="en">Writes the current in-memory value and publishes a value-written notification.</para>
		///     <para xml:lang="zh-CN">写入当前内存值并发布值写入通知。</para>
		/// </summary>
		public void Write(TValue value)
		{
			_value = value;
			ModSettingsBindingWriteEvents.NotifyValueWritten(this);
		}

		/// <inheritdoc />
		public void Save()
		{
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Adds a structured value adapter to an existing binding while forwarding its reads, writes, and
	///         persistence.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为现有绑定添加结构化值适配器，同时转发其读取、写入与持久化操作。
	///     </para>
	/// </summary>
	/// <typeparam name="TValue">
	///     <para xml:lang="en">The bound value type.</para>
	///     <para xml:lang="zh-CN">绑定值类型。</para>
	/// </typeparam>
	/// <param name="inner">
	///     <para xml:lang="en">The binding to decorate.</para>
	///     <para xml:lang="zh-CN">要装饰的绑定。</para>
	/// </param>
	/// <param name="adapter">
	///     <para xml:lang="en">The structured value adapter to expose.</para>
	///     <para xml:lang="zh-CN">要公开的结构化值适配器。</para>
	/// </param>
	public sealed class StructuredModSettingsValueBinding<TValue>(IModSettingsValueBinding<TValue> inner, IStructuredModSettingsValueAdapter<TValue> adapter) : IStructuredModSettingsValueBinding<TValue>, IModSettingsValueBinding<TValue>, IModSettingsBinding, IModSettingsUiRefreshPropagation, IModSettingsUiRefreshEquivalence, IModSettingsBindingSaveDispatch
	{
		private readonly IModSettingsValueBinding<TValue> _inner = ModSettingsBindingValidation.RequireNonNull(inner, "inner");

		IReadOnlyList<IModSettingsBinding> IModSettingsBindingSaveDispatch.ImmediateSaveTargets => new <>z__ReadOnlySingleElementList<IModSettingsBinding>(_inner);

		/// <inheritdoc />
		public IReadOnlyList<IModSettingsBinding> UiRefreshAlsoTreatAsDirty => new <>z__ReadOnlySingleElementList<IModSettingsBinding>(_inner);

		/// <inheritdoc />
