		/// <summary>
		///     <para xml:lang="en">Gets the adapter used for cloning, serialization, and clipboard operations.</para>
		///     <para xml:lang="zh-CN">获取用于克隆、序列化与剪贴板操作的适配器。</para>
		/// </summary>
		public IStructuredModSettingsValueAdapter<TValue> Adapter { get; } = ModSettingsBindingValidation.RequireNonNull(adapter, "adapter");

		/// <inheritdoc />
		public TValue Read()
