	/// <summary>
	///     <para xml:lang="en">
	///         Projects a child value from a parent binding, such as one field of a settings record, and writes changes
	///         back by replacing the parent value.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         从父绑定投影子值（例如设置记录中的一个字段），并通过替换父值写回更改。
	///     </para>
	/// </summary>
	/// <typeparam name="TSource">
	///     <para xml:lang="en">The parent value type.</para>
	///     <para xml:lang="zh-CN">父值类型。</para>
	/// </typeparam>
	/// <typeparam name="TValue">
	///     <para xml:lang="en">The projected value type.</para>
	///     <para xml:lang="zh-CN">投影值类型。</para>
	/// </typeparam>
	/// <param name="parent">
	///     <para xml:lang="en">The parent binding.</para>
	///     <para xml:lang="zh-CN">父绑定。</para>
	/// </param>
	/// <param name="dataKey">
	///     <para xml:lang="en">The optional child segment appended to the parent data key.</para>
	///     <para xml:lang="zh-CN">追加到父数据键的可选子片段。</para>
	/// </param>
	/// <param name="getter">
	///     <para xml:lang="en">The function that reads the projected value.</para>
	///     <para xml:lang="zh-CN">读取投影值的函数。</para>
	/// </param>
	/// <param name="setter">
	///     <para xml:lang="en">The function that returns a parent value containing the projected change.</para>
	///     <para xml:lang="zh-CN">返回包含投影更改的父值的函数。</para>
	/// </param>
	/// <param name="adapter">
	///     <para xml:lang="en">An optional adapter for the projected value type.</para>
	///     <para xml:lang="zh-CN">投影值类型的可选适配器。</para>
	/// </param>
	public sealed class ProjectedModSettingsValueBinding<TSource, TValue>(IModSettingsValueBinding<TSource> parent, string dataKey, Func<TSource, TValue> getter, Func<TSource, TValue, TSource> setter, IStructuredModSettingsValueAdapter<TValue>? adapter = null) : IStructuredModSettingsValueBinding<TValue>, IModSettingsValueBinding<TValue>, IModSettingsBinding, IModSettingsUiRefreshPropagation, IModSettingsBindingSaveDispatch
	{
		private readonly Func<TSource, TValue> _getter = ModSettingsBindingValidation.RequireNonNull(getter, "getter");

		private readonly IModSettingsValueBinding<TSource> _parent = ModSettingsBindingValidation.RequireNonNull(parent, "parent");

		private readonly Func<TSource, TValue, TSource> _setter = ModSettingsBindingValidation.RequireNonNull(setter, "setter");

		IReadOnlyList<IModSettingsBinding> IModSettingsBindingSaveDispatch.ImmediateSaveTargets => new <>z__ReadOnlySingleElementList<IModSettingsBinding>(_parent);

		/// <inheritdoc />
		public IEnumerable<IModSettingsBinding> ExtraBindingsToMarkDirtyForUi => new <>z__ReadOnlySingleElementList<IModSettingsBinding>(_parent);

		/// <inheritdoc />
		public string ModId => _parent.ModId;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets <c>parent.DataKey.{segment}</c> when the child segment is not blank; otherwise, gets the parent's
		///         data key.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         子片段非空白时获取 <c>parent.DataKey.{segment}</c>；否则获取父绑定的数据键。
		///     </para>
		/// </summary>
		public string DataKey
		{
			get
			{
				if (!string.IsNullOrWhiteSpace(dataKey))
				{
					return _parent.DataKey + "." + dataKey;
				}
				return _parent.DataKey;
			}
		}

		/// <inheritdoc />
		public SaveScope Scope => _parent.Scope;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the projected value adapter, using the built-in JSON adapter when none was supplied.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取投影值适配器；未提供时使用内置 JSON 适配器。
		///     </para>
		/// </summary>
		public IStructuredModSettingsValueAdapter<TValue> Adapter { get; } = adapter ?? ModSettingsStructuredData.Json<TValue>();

		/// <inheritdoc />
		public TValue Read()
		{
			return _getter(_parent.Read());
		}

		/// <inheritdoc />
		public void Write(TValue value)
		{
			TSource arg = _parent.Read();
			_parent.Write(_setter(arg, value));
			ModSettingsBindingWriteEvents.NotifyValueWritten(this);
		}

		/// <inheritdoc />
		public void Save()
		{
			_parent.Save();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Adds a reset default-value factory to a binding and exposes the structured adapter used by clipboard
	///         operations.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为绑定添加供重置使用的默认值工厂，并公开剪贴板操作使用的结构化适配器。
	///     </para>
	/// </summary>
	/// <typeparam name="TValue">
	///     <para xml:lang="en">The bound value type.</para>
	///     <para xml:lang="zh-CN">绑定值类型。</para>
	/// </typeparam>
	/// <param name="inner">
	///     <para xml:lang="en">The binding to decorate.</para>
	///     <para xml:lang="zh-CN">要装饰的绑定。</para>
	/// </param>
	/// <param name="defaultValueFactory">
	///     <para xml:lang="en">The function that creates a value for each reset operation.</para>
	///     <para xml:lang="zh-CN">为每次重置操作创建值的函数。</para>
	/// </param>
	/// <param name="adapter">
	///     <para xml:lang="en">
	///         The fallback structured adapter when the inner binding does not already provide one.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         内部绑定尚未提供结构化适配器时使用的回退适配器。
	///     </para>
	/// </param>
	public sealed class DefaultModSettingsValueBinding<TValue>(IModSettingsValueBinding<TValue> inner, Func<TValue> defaultValueFactory, IStructuredModSettingsValueAdapter<TValue>? adapter = null) : IStructuredModSettingsValueBinding<TValue>, IModSettingsValueBinding<TValue>, IModSettingsBinding, IDefaultModSettingsValueBinding<TValue>, IModSettingsUiRefreshPropagation, IModSettingsUiRefreshEquivalence, IModSettingsBindingSaveDispatch
	{
		private readonly Func<TValue> _defaultValueFactory = ModSettingsBindingValidation.RequireNonNull(defaultValueFactory, "defaultValueFactory");

		private readonly IModSettingsValueBinding<TValue> _inner = ModSettingsBindingValidation.RequireNonNull(inner, "inner");

		IReadOnlyList<IModSettingsBinding> IModSettingsBindingSaveDispatch.ImmediateSaveTargets => new <>z__ReadOnlySingleElementList<IModSettingsBinding>(_inner);

		/// <inheritdoc />
		public IReadOnlyList<IModSettingsBinding> UiRefreshAlsoTreatAsDirty => new <>z__ReadOnlySingleElementList<IModSettingsBinding>(_inner);

		/// <inheritdoc />
		public IEnumerable<IModSettingsBinding> ExtraBindingsToMarkDirtyForUi => new <>z__ReadOnlySingleElementList<IModSettingsBinding>(_inner);

		/// <inheritdoc />
		public string ModId => _inner.ModId;

		/// <inheritdoc />
		public string DataKey => _inner.DataKey;

		/// <inheritdoc />
		public SaveScope Scope => _inner.Scope;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the inner binding's structured adapter when available; otherwise, gets the supplied fallback or
		///         the built-in JSON adapter.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         内部绑定提供结构化适配器时获取该适配器；否则获取所提供的回退适配器或内置 JSON 适配器。
		///     </para>
		/// </summary>
		public IStructuredModSettingsValueAdapter<TValue> Adapter { get; } = (IStructuredModSettingsValueAdapter<TValue>)((inner is IStructuredModSettingsValueBinding<TValue> structuredModSettingsValueBinding) ? ((object)structuredModSettingsValueBinding.Adapter) : ((object)(adapter ?? ModSettingsStructuredData.Json<TValue>())));

		/// <inheritdoc />
		public TValue CreateDefaultValue()
		{
			return _defaultValueFactory();
		}

		/// <inheritdoc />
		public TValue Read()
		{
			return _inner.Read();
		}

		/// <inheritdoc />
		public void Write(TValue value)
		{
			_inner.Write(value);
			ModSettingsBindingWriteEvents.NotifyValueWritten(this);
		}

		/// <inheritdoc />
		public void Save()
		{
			_inner.Save();
		}
	}
	internal sealed class JsonStructuredValueAdapter<TValue>(JsonSerializerOptions? options) : IStructuredModSettingsValueAdapter<TValue>
	{
		public TValue Clone(TValue value)
		{
			return JsonSerializer.Deserialize<TValue>(JsonSerializer.Serialize(value, options), options);
		}

		public string Serialize(TValue value)
		{
			return JsonSerializer.Serialize(value, options);
		}

		public bool TryDeserialize(string text, out TValue value)
		{
			try
			{
				value = JsonSerializer.Deserialize<TValue>(text, options);
				return true;
			}
			catch (JsonException)
			{
				value = default(TValue);
				return false;
			}
			catch (NotSupportedException)
			{
				value = default(TValue);
				return false;
			}
		}
	}
	internal sealed class ListStructuredValueAdapter<TItem>(IStructuredModSettingsValueAdapter<TItem>? itemAdapter, JsonSerializerOptions? options) : IStructuredModSettingsValueAdapter<List<TItem>>
	{
		public List<TItem> Clone(List<TItem> value)
		{
			if (itemAdapter != null)
			{
				return value.Select(itemAdapter.Clone).ToList();
			}
			return JsonSerializer.Deserialize<List<TItem>>(JsonSerializer.Serialize(value, options), options) ?? new List<TItem>();
		}

		public string Serialize(List<TItem> value)
		{
			return JsonSerializer.Serialize(value, options);
		}

		public bool TryDeserialize(string text, out List<TItem> value)
		{
			try
			{
				value = JsonSerializer.Deserialize<List<TItem>>(text, options) ?? new List<TItem>();
				return true;
			}
			catch (JsonException)
			{
				value = new List<TItem>();
				return false;
			}
			catch (NotSupportedException)
			{
				value = new List<TItem>();
				return false;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Builds a mod settings page by configuring its metadata, hierarchy, host-surface behavior, and sections.
	///     </para>
	///     <para xml:lang="zh-CN">用于配置元数据、页面层级、宿主界面行为及节的模组设置页面构建器。</para>
	/// </summary>
	public sealed class ModSettingsPageBuilder
	{
		private readonly HashSet<string> _sectionIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

		private readonly List<ModSettingsSection> _sections = new List<ModSettingsSection>();

		private bool _hideDescription;

		private ModSettingsMenuCapabilities _menuCapabilities = ModSettingsMenuCapabilities.All;

		private int? _modSidebarOrder;

		private Func<bool>? _pageEnabledWhen;

		private ModSettingsHostSurface _pageReadOnlyOnHostSurfaces;

		private ModSettingsHostSurface _pageVisibleOnHostSurfaces = ModSettingsHostSurface.All;

		private Func<bool>? _pageVisibleWhen;

		private bool _sidebarVisibleOnlyWhenActive;

		private bool _useSourceAssemblyManifest = true;

		/// <summary>
		///     <para xml:lang="en">Gets the owning mod ID.</para>
		///     <para xml:lang="zh-CN">获取所属模组 ID。</para>
		/// </summary>
		public string ModId { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the stable page ID used for navigation and page-level clipboard snapshots.</para>
		///     <para xml:lang="zh-CN">获取用于导航及页面级剪贴板快照的稳定页面 ID。</para>
		/// </summary>
		public string PageId { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the assembly that registered the page, if known. It can be used to locate the owning ModManager
		///         manifest for sidebar presentation.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取注册此页面的程序集（如已知）；该程序集可用于查找所属 ModManager 清单并生成侧边栏展示信息。
		///     </para>
		/// </summary>
		public Assembly? SourceAssembly { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional ID of the page under which this page is nested.</para>
		///     <para xml:lang="zh-CN">获取此页面所隶属父页面的可选 ID。</para>
		/// </summary>
		public string? ParentPageId { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional localized page title displayed in navigation and headers.</para>
		///     <para xml:lang="zh-CN">获取在导航及标题区域显示的可选本地化页面标题。</para>
		/// </summary>
		public ModSettingsText? Title { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional localized page description.</para>
		///     <para xml:lang="zh-CN">获取可选的本地化页面说明。</para>
		/// </summary>
		public ModSettingsText? Description { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional mod display name used by the settings sidebar.</para>
		///     <para xml:lang="zh-CN">获取设置侧边栏使用的可选模组显示名称。</para>
		/// </summary>
		public ModSettingsText? ModDisplayName { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Gets the sort order among sibling pages; lower values appear first.</para>
		///     <para xml:lang="zh-CN">获取同级页面之间的排序值；数值较小的页面排在前面。</para>
		/// </summary>
		public int SortOrder { get; private set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Initializes a builder for <paramref name="modId" />. A null or whitespace
		///         <paramref name="pageId" /> defaults to the mod ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="modId" /> 初始化构建器；<paramref name="pageId" /> 为 null 或空白时默认使用模组 ID。
		///     </para>
		/// </summary>
		public ModSettingsPageBuilder(string modId, string? pageId = null)
			: this(modId, pageId, null)
		{
		}

		internal ModSettingsPageBuilder(string modId, string? pageId, Assembly? sourceAssembly)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ModId = modId;
			PageId = (string.IsNullOrWhiteSpace(pageId) ? modId : pageId);
			SourceAssembly = sourceAssembly;
		}

		/// <summary>
		///     <para xml:lang="en">Nests the page under <paramref name="parentPageId" /> in the settings hierarchy.</para>
		///     <para xml:lang="zh-CN">在设置页面层级中将此页面置于 <paramref name="parentPageId" /> 之下。</para>
		/// </summary>
		public ModSettingsPageBuilder AsChildOf(string parentPageId)
		{
			ParentPageId = parentPageId;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Sets the localized page title.</para>
		///     <para xml:lang="zh-CN">设置本地化页面标题。</para>
		/// </summary>
		public ModSettingsPageBuilder WithTitle(ModSettingsText title)
		{
			Title = title;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Sets the localized page description.</para>
		///     <para xml:lang="zh-CN">设置本地化页面说明。</para>
		/// </summary>
		public ModSettingsPageBuilder WithDescription(ModSettingsText description)
		{
			Description = description;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Controls whether the page header omits its description and the manifest-description fallback.
		///     </para>
		///     <para xml:lang="zh-CN">控制页面标题区域是否隐藏说明并禁用清单说明回退。</para>
		/// </summary>
		public ModSettingsPageBuilder WithDescriptionHidden(bool hidden = true)
		{
			_hideDescription = hidden;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets the mod display name that <see cref="M:STS2RitsuLib.Settings.ModSettingsPageBuilder.Build" /> registers with
		///         <see cref="T:STS2RitsuLib.Settings.ModSettingsRegistry" /> for the sidebar.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         设置模组显示名称；<see cref="M:STS2RitsuLib.Settings.ModSettingsPageBuilder.Build" /> 会将其注册到 <see cref="T:STS2RitsuLib.Settings.ModSettingsRegistry" /> 供侧边栏使用。
		///     </para>
		/// </summary>
		public ModSettingsPageBuilder WithModDisplayName(ModSettingsText displayName)
		{
			ModDisplayName = displayName;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Sets <see cref="P:STS2RitsuLib.Settings.ModSettingsPageBuilder.SortOrder" />.</para>
		///     <para xml:lang="zh-CN">设置 <see cref="P:STS2RitsuLib.Settings.ModSettingsPageBuilder.SortOrder" />。</para>
		/// </summary>
		public ModSettingsPageBuilder WithSortOrder(int sortOrder)
		{
			SortOrder = sortOrder;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets the mod-group sidebar order that <see cref="M:STS2RitsuLib.Settings.ModSettingsPageBuilder.Build" /> registers for <see cref="P:STS2RitsuLib.Settings.ModSettingsPageBuilder.ModId" />.
		///         Repeated registrations for the same mod must use the same value.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         设置 <see cref="M:STS2RitsuLib.Settings.ModSettingsPageBuilder.Build" /> 为 <see cref="P:STS2RitsuLib.Settings.ModSettingsPageBuilder.ModId" /> 注册的模组分组侧边栏排序值；同一模组的重复注册必须使用相同值。
		///     </para>
		/// </summary>
		public ModSettingsPageBuilder WithModSidebarOrder(int order)
		{
			_modSidebarOrder = order;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets a predicate that is re-evaluated on settings UI refresh. A false result hides the page from
		///         both the sidebar and main content.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         设置在设置界面刷新时重新求值的谓词；结果为 false 时，在侧边栏及主内容中隐藏此页面。
		///     </para>
		/// </summary>
		public ModSettingsPageBuilder WithVisibleWhen(Func<bool> predicate)
		{
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			_pageVisibleWhen = predicate;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets a predicate whose false result dims the page and disables interaction.
		///     </para>
		///     <para xml:lang="zh-CN">设置启用状态谓词；结果为 false 时页面会变暗且不可交互。</para>
		/// </summary>
		public ModSettingsPageBuilder WithEnabledWhen(Func<bool> predicate)
		{
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			_pageEnabledWhen = predicate;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets the host surfaces on which the page is visible. Pages are visible on all surfaces by default.
		///     </para>
		///     <para xml:lang="zh-CN">设置此页面可见的宿主界面；默认在所有宿主界面中可见。</para>
		/// </summary>
		public ModSettingsPageBuilder WithVisibleOnHostSurfaces(ModSettingsHostSurface surfaces)
		{
			_pageVisibleOnHostSurfaces = surfaces;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Makes the sidebar item visible only while this page or one of its descendants is active.
		///     </para>
		///     <para xml:lang="zh-CN">使侧边栏条目仅在此页面或其后代页面处于活动状态时可见。</para>
		/// </summary>
		public ModSettingsPageBuilder WithSidebarVisibleOnlyWhenActive()
		{
			_sidebarVisibleOnlyWhenActive = true;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Controls whether the sidebar may use <see cref="P:STS2RitsuLib.Settings.ModSettingsPageBuilder.SourceAssembly" /> to locate the ModManager manifest
		///         for this page's mod group. Lookup is enabled by default.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         控制侧边栏是否可以通过 <see cref="P:STS2RitsuLib.Settings.ModSettingsPageBuilder.SourceAssembly" /> 查找此页面所属模组分组的 ModManager 清单；默认启用。
		///     </para>
		/// </summary>
		public ModSettingsPageBuilder WithSourceAssemblyManifestLookup(bool enabled = true)
		{
			_useSourceAssemblyManifest = enabled;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Disables sidebar manifest lookup through this page's source assembly.</para>
		///     <para xml:lang="zh-CN">禁用通过此页面来源程序集进行的侧边栏清单查找。</para>
		/// </summary>
		public ModSettingsPageBuilder WithoutSourceAssemblyManifestLookup()
		{
			return WithSourceAssemblyManifestLookup(enabled: false);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets the host surfaces on which the page's value controls are read-only. This mask is combined with
		///         each section's read-only mask.
		///     </para>
		///     <para xml:lang="zh-CN">设置此页面数值控件处于只读状态的宿主界面；该掩码会与各节的只读掩码合并。</para>
		/// </summary>
		public ModSettingsPageBuilder WithReadOnlyOnHostSurfaces(ModSettingsHostSurface surfaces)
		{
			_pageReadOnlyOnHostSurfaces = surfaces;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Sets the context-menu actions exposed for the page itself.</para>
		///     <para xml:lang="zh-CN">设置页面自身上下文菜单公开的操作。</para>
		/// </summary>
		public ModSettingsPageBuilder WithMenuCapabilities(ModSettingsMenuCapabilities capabilities)
		{
			_menuCapabilities = capabilities;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Configures and adds a section. <paramref name="id" /> must be unique within this page,
		///         case-insensitively.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         配置并添加节；<paramref name="id" /> 在此页面内必须不区分大小写地保持唯一。
		///     </para>
		/// </summary>
		public ModSettingsPageBuilder AddSection(string id, Action<ModSettingsSectionBuilder> configure)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentNullException.ThrowIfNull(configure, "configure");
			if (!_sectionIds.Add(id))
			{
				throw new InvalidOperationException($"Duplicate settings section id '{id}' for mod '{ModId}'.");
			}
			ModSettingsSectionBuilder modSettingsSectionBuilder = new ModSettingsSectionBuilder(id);
			configure(modSettingsSectionBuilder);
			_sections.Add(modSettingsSectionBuilder.Build());
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Materializes the page and performs pending mod-display and sidebar-order registrations. At least one
		///         section must have been added.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         生成页面并执行待处理的模组显示名称及侧边栏排序注册；必须已添加至少一个节。
		///     </para>
		/// </summary>
		public ModSettingsPage Build()
		{
			if (_sections.Count == 0)
			{
				throw new InvalidOperationException($"Settings page '{PageId}' for mod '{ModId}' has no sections.");
			}
			if (ModDisplayName != null)
			{
				ModSettingsRegistry.RegisterModDisplayName(ModId, ModDisplayName);
			}
			int? modSidebarOrder = _modSidebarOrder;
			if (modSidebarOrder.HasValue)
			{
				int valueOrDefault = modSidebarOrder.GetValueOrDefault();
				ModSettingsRegistry.RegisterModSidebarOrder(ModId, valueOrDefault);
			}
			return new ModSettingsPage(ModId, PageId, ParentPageId, Title, Description, SortOrder, new global::<>z__ReadOnlyArray<ModSettingsSection>(_sections.ToArray()), _pageVisibleWhen, _pageEnabledWhen, _menuCapabilities, _pageVisibleOnHostSurfaces, _pageReadOnlyOnHostSurfaces, _sidebarVisibleOnlyWhenActive, _hideDescription, SourceAssembly, _useSourceAssemblyManifest);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Builds a settings section by configuring its display, availability, host-surface behavior, and typed
	///         entries.
	///     </para>
	///     <para xml:lang="zh-CN">用于配置显示内容、可用状态、宿主界面行为及类型化条目的设置节构建器。</para>
	/// </summary>
	public sealed class ModSettingsSectionBuilder
	{
		private readonly List<ModSettingsEntryDefinition> _entries = new List<ModSettingsEntryDefinition>();

		private readonly Dictionary<string, Func<bool>> _entryEnabledWhen = new Dictionary<string, Func<bool>>(StringComparer.OrdinalIgnoreCase);

		private readonly HashSet<string> _entryIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

		private readonly Dictionary<string, Func<bool>> _entryVisibleWhen = new Dictionary<string, Func<bool>>(StringComparer.OrdinalIgnoreCase);

		private ModSettingsMenuCapabilities _menuCapabilities = ModSettingsMenuCapabilities.All;

		private Func<bool>? _sectionEnabledWhen;

		private ModSettingsHostSurface _sectionReadOnlyOnHostSurfaces;

		private ModSettingsHostSurface _sectionVisibleOnHostSurfaces = ModSettingsHostSurface.All;

		private Func<bool>? _sectionVisibleWhen;

		/// <summary>
		///     <para xml:lang="en">Gets the stable section ID within its page.</para>
		///     <para xml:lang="zh-CN">获取节在所属页面内的稳定 ID。</para>
		/// </summary>
		public string Id { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional localized section title.</para>
		///     <para xml:lang="zh-CN">获取可选的本地化节标题。</para>
		/// </summary>
		public ModSettingsText? Title { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional localized description displayed below the title.</para>
		///     <para xml:lang="zh-CN">获取标题下方显示的可选本地化说明。</para>
		/// </summary>
		public ModSettingsText? Description { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Gets whether the section can be collapsed.</para>
		///     <para xml:lang="zh-CN">获取此节是否可以折叠。</para>
		/// </summary>
		public bool IsCollapsible { get; private set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether the section initially starts collapsed when <see cref="P:STS2RitsuLib.Settings.ModSettingsSectionBuilder.IsCollapsible" /> is enabled.
		///     </para>
		///     <para xml:lang="zh-CN">获取启用 <see cref="P:STS2RitsuLib.Settings.ModSettingsSectionBuilder.IsCollapsible" /> 时此节是否初始折叠。</para>
		/// </summary>
		public bool StartCollapsed { get; private set; }

		internal ModSettingsSectionBuilder(string id)
		{
			Id = id;
		}

		/// <summary>
		///     <para xml:lang="en">Sets the localized section title.</para>
		///     <para xml:lang="zh-CN">设置本地化节标题。</para>
		/// </summary>
		public ModSettingsSectionBuilder WithTitle(ModSettingsText title)
		{
			Title = title;
			return this;
		}

