		/// </summary>
		public ModSettingsSectionBuilder WithMenuCapabilities(ModSettingsMenuCapabilities capabilities)
		{
			_menuCapabilities = capabilities;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Adds a non-interactive heading row.</para>
		///     <para xml:lang="zh-CN">添加不带交互控件的标题行。</para>
		/// </summary>
		public ModSettingsSectionBuilder AddHeader(string id, ModSettingsText label, ModSettingsText? description = null)
		{
			AddEntry(id, new HeaderModSettingsEntryDefinition(id, label, description));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds a read-only rich-text paragraph with an optional maximum body height for scrolling.
		///     </para>
		///     <para xml:lang="zh-CN">添加只读富文本段落，并可指定启用滚动的正文最大高度。</para>
		/// </summary>
		public ModSettingsSectionBuilder AddParagraph(string id, ModSettingsText text, ModSettingsText? description = null, float? maxBodyHeight = null)
		{
			AddEntry(id, new ParagraphModSettingsEntryDefinition(id, text, description, maxBodyHeight));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Adds a read-only information card with a title, optional subtitle, and rich-text body.</para>
		///     <para xml:lang="zh-CN">添加包含标题、可选副标题及富文本正文的只读信息卡。</para>
		/// </summary>
		public ModSettingsSectionBuilder AddInfoCard(string id, ModSettingsText label, ModSettingsText body, ModSettingsText? description = null)
		{
			AddEntry(id, new InfoCardModSettingsEntryDefinition(id, label, body, description));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds a read-only runtime hotkey summary with descriptive text on the left and binding labels on the
		///         right.
		///     </para>
		///     <para xml:lang="zh-CN">添加只读的运行时热键摘要，左侧显示说明文本，右侧显示绑定标签。</para>
		/// </summary>
		public ModSettingsSectionBuilder AddRuntimeHotkeySummary(string id, ModSettingsText label, ModSettingsText body, IReadOnlyList<ModSettingsText> bindings, ModSettingsText? idSuffix = null)
		{
			AddEntry(id, new RuntimeHotkeySummaryModSettingsEntryDefinition(id, label, body, bindings, idSuffix));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Adds an image preview resolved from <paramref name="textureProvider" /> when created.</para>
		///     <para xml:lang="zh-CN">添加创建时通过 <paramref name="textureProvider" /> 解析的图像预览。</para>
		/// </summary>
		public ModSettingsSectionBuilder AddImage(string id, ModSettingsText label, Func<Texture2D?> textureProvider, float previewHeight = 160f, ModSettingsText? description = null)
		{
			ArgumentNullException.ThrowIfNull(textureProvider, "textureProvider");
			if (!float.IsFinite(previewHeight) || previewHeight <= 0f)
			{
				throw new ArgumentOutOfRangeException("previewHeight", "Image previewHeight must be finite and > 0.");
			}
			AddEntry(id, new ImageModSettingsEntryDefinition(id, label, textureProvider, previewHeight, description));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds an editable list backed by <paramref name="binding" />, using
		///         <paramref name="itemEditorFactory" /> for each item when provided.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         添加由 <paramref name="binding" /> 支持的可编辑列表；提供 <paramref name="itemEditorFactory" />
		///         时使用该工厂创建各列表项编辑器。
		///     </para>
		/// </summary>
		public ModSettingsSectionBuilder AddList<TItem>(string id, ModSettingsText label, IModSettingsValueBinding<List<TItem>> binding, Func<TItem> createItem, Func<TItem, ModSettingsText> itemLabel, Func<TItem, ModSettingsText?>? itemDescription = null, Func<ModSettingsListItemContext<TItem>, Control>? itemEditorFactory = null, IStructuredModSettingsValueAdapter<TItem>? itemDataAdapter = null, ModSettingsText? addButtonText = null, ModSettingsText? description = null)
		{
			return AddList(id, label, binding, createItem, itemLabel, itemDescription, itemEditorFactory, itemDataAdapter, addButtonText, description, collapsibleItems: false, startItemsCollapsed: false, null);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds an editable list backed by <paramref name="binding" />, with optional collapsible item cards and
		///         compact controls in each item header.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         添加由 <paramref name="binding" /> 支持的可编辑列表，并可启用可折叠列表项卡片及标题栏紧凑控件。
		///     </para>
		/// </summary>
		public ModSettingsSectionBuilder AddList<TItem>(string id, ModSettingsText label, IModSettingsValueBinding<List<TItem>> binding, Func<TItem> createItem, Func<TItem, ModSettingsText> itemLabel, Func<TItem, ModSettingsText?>? itemDescription, Func<ModSettingsListItemContext<TItem>, Control>? itemEditorFactory, IStructuredModSettingsValueAdapter<TItem>? itemDataAdapter, ModSettingsText? addButtonText, ModSettingsText? description, bool collapsibleItems, bool startItemsCollapsed, Func<ModSettingsListItemContext<TItem>, Control?>? itemHeaderAccessoryFactory)
		{
			ArgumentNullException.ThrowIfNull(createItem, "createItem");
			ArgumentNullException.ThrowIfNull(itemLabel, "itemLabel");
			AddEntry(id, new ListModSettingsEntryDefinition<TItem>(id, label, binding, createItem, itemLabel, itemDescription, itemEditorFactory, itemDataAdapter, addButtonText ?? ModSettingsLocalization.Text("button.add", "Add"), description, collapsibleItems, startItemsCollapsed, itemHeaderAccessoryFactory));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Adds a boolean toggle.</para>
		///     <para xml:lang="zh-CN">添加布尔开关。</para>
		/// </summary>
		public ModSettingsSectionBuilder AddToggle(string id, ModSettingsText label, IModSettingsValueBinding<bool> binding, ModSettingsText? description = null, Func<bool>? visibleWhen = null)
		{
			AddEntry(id, new ToggleModSettingsEntryDefinition(id, label, binding, description, visibleWhen));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Adds an integer slider over an inclusive range with a positive step.</para>
		///     <para xml:lang="zh-CN">添加在闭区间内按正步长调整数值的整数滑块。</para>
		/// </summary>
		public ModSettingsSectionBuilder AddIntSlider(string id, ModSettingsText label, IModSettingsValueBinding<int> binding, int minValue, int maxValue, int step = 1, Func<int, string>? valueFormatter = null, ModSettingsText? description = null)
		{
			if (maxValue < minValue)
			{
				throw new ArgumentOutOfRangeException("maxValue", "Slider maxValue must be >= minValue.");
			}
			if (step <= 0)
			{
				throw new ArgumentOutOfRangeException("step", "Slider step must be > 0.");
			}
			AddEntry(id, new IntSliderModSettingsEntryDefinition(id, label, binding, minValue, maxValue, step, valueFormatter, description));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds a <see cref="T:System.Double" /> slider over a finite inclusive range with a finite positive step.
		///     </para>
		///     <para xml:lang="zh-CN">添加在有限闭区间内按有限正步长调整数值的 <see cref="T:System.Double" /> 滑块。</para>
		/// </summary>
		public ModSettingsSectionBuilder AddSlider(string id, ModSettingsText label, IModSettingsValueBinding<double> binding, double minValue, double maxValue, double step = 1.0, Func<double, string>? valueFormatter = null, ModSettingsText? description = null)
		{
			if (!double.IsFinite(minValue))
			{
				throw new ArgumentOutOfRangeException("minValue", "Slider minValue must be finite.");
			}
			if (!double.IsFinite(maxValue))
			{
				throw new ArgumentOutOfRangeException("maxValue", "Slider maxValue must be finite.");
			}
			if (maxValue < minValue)
			{
				throw new ArgumentOutOfRangeException("maxValue", "Slider maxValue must be >= minValue.");
			}
			if (!double.IsFinite(step) || step <= 0.0)
			{
				throw new ArgumentOutOfRangeException("step", "Slider step must be finite and > 0.");
			}
			AddEntry(id, new SliderModSettingsEntryDefinition(id, label, binding, minValue, maxValue, step, valueFormatter, description));
			return this;
		}

		internal ModSettingsSectionBuilder AddFloatSlider(string id, ModSettingsText label, IModSettingsValueBinding<float> binding, float minValue, float maxValue, float step = 1f, Func<float, string>? valueFormatter = null, ModSettingsText? description = null)
		{
			ArgumentNullException.ThrowIfNull(binding, "binding");
			if (!float.IsFinite(minValue))
			{
				throw new ArgumentOutOfRangeException("minValue", "Slider minValue must be finite.");
			}
			if (!float.IsFinite(maxValue))
			{
				throw new ArgumentOutOfRangeException("maxValue", "Slider maxValue must be finite.");
			}
			if (maxValue < minValue)
			{
				throw new ArgumentOutOfRangeException("maxValue", "Slider maxValue must be >= minValue.");
			}
			if (!float.IsFinite(step) || step <= 0f)
			{
				throw new ArgumentOutOfRangeException("step", "Slider step must be finite and > 0.");
			}
			AddEntry(id, new FloatSliderModSettingsEntryDefinition(id, label, binding, minValue, maxValue, step, valueFormatter, description));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds a non-empty fixed option set using the specified <paramref name="presentation" />.
		///     </para>
		///     <para xml:lang="zh-CN">使用指定的 <paramref name="presentation" /> 添加非空的固定选项集。</para>
		/// </summary>
		public ModSettingsSectionBuilder AddChoice<TValue>(string id, ModSettingsText label, IModSettingsValueBinding<TValue> binding, IEnumerable<ModSettingsChoiceOption<TValue>> options, ModSettingsText? description = null, ModSettingsChoicePresentation presentation = ModSettingsChoicePresentation.Stepper)
		{
			ArgumentNullException.ThrowIfNull(options, "options");
			ModSettingsChoiceOption<TValue>[] array = options.ToArray();
			if (array.Length == 0)
			{
				throw new InvalidOperationException("Choice setting '" + id + "' requires at least one option.");
			}
			AddEntry(id, new ChoiceModSettingsEntryDefinition<TValue>(id, label, binding, array, presentation, description));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds options that are re-evaluated on settings UI refresh and immediately before a drop-down list
		///         opens. An empty result temporarily disables the control without changing the bound value.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         添加在设置界面刷新及下拉列表展开前重新计算的选项；空结果会暂时禁用控件，但不会更改绑定值。
		///     </para>
		/// </summary>
		/// <param name="id">
		///     <para xml:lang="en">The stable entry ID within the section.</para>
		///     <para xml:lang="zh-CN">条目在节内的稳定 ID。</para>
		/// </param>
		/// <param name="label">
		///     <para xml:lang="en">The visible row label.</para>
		///     <para xml:lang="zh-CN">可见的行标签。</para>
		/// </param>
		/// <param name="binding">
		///     <para xml:lang="en">The binding that stores the selected value.</para>
		///     <para xml:lang="zh-CN">存储所选值的绑定。</para>
		/// </param>
		/// <param name="optionsProvider">
		///     <para xml:lang="en">
		///         The provider invoked when the entry is added, when the control is created, on UI refresh, and before
		///         a drop-down list opens.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         添加条目、创建控件、界面刷新以及下拉列表展开前调用的选项提供器。
		///     </para>
		/// </param>
		/// <param name="description">
		///     <para xml:lang="en">The optional secondary description.</para>
		///     <para xml:lang="zh-CN">可选的次级说明。</para>
		/// </param>
		/// <param name="presentation">
		///     <para xml:lang="en">The visual presentation for the choices.</para>
		///     <para xml:lang="zh-CN">选项使用的视觉呈现方式。</para>
		/// </param>
		public ModSettingsSectionBuilder AddDynamicChoice<TValue>(string id, ModSettingsText label, IModSettingsValueBinding<TValue> binding, Func<IReadOnlyList<ModSettingsChoiceOption<TValue>>> optionsProvider, ModSettingsText? description = null, ModSettingsChoicePresentation presentation = ModSettingsChoicePresentation.Stepper)
		{
			ArgumentNullException.ThrowIfNull(optionsProvider, "optionsProvider");
			IReadOnlyList<ModSettingsChoiceOption<TValue>> options = optionsProvider() ?? throw new InvalidOperationException("Dynamic choice setting '" + id + "' returned a null option list.");
			ChoiceModSettingsEntryDefinition<TValue> entry = new ChoiceModSettingsEntryDefinition<TValue>(id, label, binding, options, presentation, description)
			{
				OptionsProvider = optionsProvider
			};
			AddEntry(id, entry);
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds a fixed choice control containing every value of <typeparamref name="TEnum" />, with optional
		///         custom labels.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         添加包含 <typeparamref name="TEnum" /> 所有枚举值的固定选项控件，并可指定自定义标签。
		///     </para>
		/// </summary>
		public ModSettingsSectionBuilder AddEnumChoice<TEnum>(string id, ModSettingsText label, IModSettingsValueBinding<TEnum> binding, Func<TEnum, ModSettingsText>? optionLabelFactory = null, ModSettingsText? description = null, ModSettingsChoicePresentation presentation = ModSettingsChoicePresentation.Stepper) where TEnum : struct, Enum
		{
			if (optionLabelFactory == null)
			{
				optionLabelFactory = (TEnum value) => ModSettingsText.Literal(value.ToString());
			}
			return AddChoice(id, label, binding, from value in Enum.GetValues<TEnum>()
				select new ModSettingsChoiceOption<TEnum>(value, optionLabelFactory(value)), description, presentation);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds the binary-compatible serialized-string color picker with alpha editing enabled and intensity
		///         editing disabled.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         添加保持二进制兼容的序列化字符串颜色选择器；启用透明度编辑并禁用强度编辑。
		///     </para>
		/// </summary>
		/// <param name="id">
		///     <para xml:lang="en">The stable entry ID within the section.</para>
		///     <para xml:lang="zh-CN">条目在节内的稳定 ID。</para>
		/// </param>
		/// <param name="label">
		///     <para xml:lang="en">The visible row label.</para>
		///     <para xml:lang="zh-CN">可见的行标签。</para>
		/// </param>
		/// <param name="binding">
		///     <para xml:lang="en">
		///         The binding that stores the serialized color; hexadecimal strings are preferred.
		///     </para>
		///     <para xml:lang="zh-CN">存储序列化颜色的绑定；建议使用十六进制字符串。</para>
		/// </param>
		/// <param name="description">
		///     <para xml:lang="en">The optional secondary description.</para>
		///     <para xml:lang="zh-CN">可选的次级说明。</para>
		/// </param>
		public ModSettingsSectionBuilder AddColor(string id, ModSettingsText label, IModSettingsValueBinding<string> binding, ModSettingsText? description = null)
		{
			return AddColor(id, label, binding, description, editAlpha: true, editIntensity: false);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds a serialized-string color picker with explicit alpha and intensity editing options.
		///     </para>
		///     <para xml:lang="zh-CN">添加由序列化字符串支持的颜色选择器，并明确指定透明度及强度编辑选项。</para>
		/// </summary>
		/// <param name="id">
		///     <para xml:lang="en">The stable entry ID within the section.</para>
		///     <para xml:lang="zh-CN">条目在节内的稳定 ID。</para>
		/// </param>
		/// <param name="label">
		///     <para xml:lang="en">The visible row label.</para>
		///     <para xml:lang="zh-CN">可见的行标签。</para>
		/// </param>
		/// <param name="binding">
		///     <para xml:lang="en">
		///         The binding that stores the serialized color; hexadecimal strings are preferred.
		///     </para>
		///     <para xml:lang="zh-CN">存储序列化颜色的绑定；建议使用十六进制字符串。</para>
		/// </param>
		/// <param name="description">
		///     <para xml:lang="en">The optional secondary description.</para>
		///     <para xml:lang="zh-CN">可选的次级说明。</para>
		/// </param>
		/// <param name="editAlpha">
		///     <para xml:lang="en">Whether the picker allows editing the alpha channel.</para>
		///     <para xml:lang="zh-CN">颜色选择器是否允许编辑透明度通道。</para>
		/// </param>
		/// <param name="editIntensity">
		///     <para xml:lang="en">
		///         Whether the picker enables HDR intensity editing through Godot
		///         <c>ColorPicker.EditIntensity</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         颜色选择器是否通过 Godot <c>ColorPicker.EditIntensity</c> 启用 HDR 强度编辑。
		///     </para>
		/// </param>
		public ModSettingsSectionBuilder AddColor(string id, ModSettingsText label, IModSettingsValueBinding<string> binding, ModSettingsText? description, bool editAlpha, bool editIntensity)
		{
			AddEntry(id, new ColorModSettingsEntryDefinition(id, label, binding, description, editAlpha, editIntensity));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Adds a single-line text field.</para>
		///     <para xml:lang="zh-CN">添加单行文本字段。</para>
		/// </summary>
		public ModSettingsSectionBuilder AddString(string id, ModSettingsText label, IModSettingsValueBinding<string> binding, ModSettingsText? placeholder = null, int? maxLength = null, ModSettingsText? description = null)
		{
			return AddString(id, label, binding, placeholder, maxLength, description, null);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds a single-line text field with optional invalid-state styling. A false validation result does
		///         not block committing the value.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         添加可提供无效状态样式的单行文本字段；校验结果为 false 不会阻止提交该值。
		///     </para>
		/// </summary>
		public ModSettingsSectionBuilder AddString(string id, ModSettingsText label, IModSettingsValueBinding<string> binding, ModSettingsText? placeholder, int? maxLength, ModSettingsText? description, Func<string, bool>? valueValidationVisual)
		{
			return AddString(id, label, binding, placeholder, maxLength, description, valueValidationVisual, null);
		}

		internal ModSettingsSectionBuilder AddString(string id, ModSettingsText label, IModSettingsValueBinding<string> binding, ModSettingsText? placeholder, int? maxLength, ModSettingsText? description, Func<string, bool>? valueValidationVisual, Func<string, bool>? valueValidationCommit)
		{
			if (maxLength.HasValue && maxLength.GetValueOrDefault() < 1)
			{
				throw new ArgumentOutOfRangeException("maxLength", "maxLength must be null or >= 1.");
			}
			AddEntry(id, new StringModSettingsEntryDefinition(id, label, binding, placeholder, maxLength, description)
			{
				ValueValidationVisual = valueValidationVisual,
				ValueValidationCommit = valueValidationCommit
			});
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Adds a multiline text field.</para>
		///     <para xml:lang="zh-CN">添加多行文本字段。</para>
		/// </summary>
		public ModSettingsSectionBuilder AddMultilineString(string id, ModSettingsText label, IModSettingsValueBinding<string> binding, ModSettingsText? placeholder = null, int? maxLength = null, ModSettingsText? description = null)
		{
			if (maxLength.HasValue && maxLength.GetValueOrDefault() < 1)
			{
				throw new ArgumentOutOfRangeException("maxLength", "maxLength must be null or >= 1.");
			}
			AddEntry(id, new MultilineStringModSettingsEntryDefinition(id, label, binding, placeholder, maxLength, description));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Adds a keyboard binding capture row.</para>
		///     <para xml:lang="zh-CN">添加键盘绑定捕获行。</para>
		/// </summary>
		public ModSettingsSectionBuilder AddKeyBinding(string id, ModSettingsText label, IModSettingsValueBinding<string> binding, bool allowModifierCombos = true, bool allowModifierOnly = true, bool distinguishModifierSides = false, ModSettingsText? description = null)
		{
			KeyBindingModSettingsEntryDefinition entry = new KeyBindingModSettingsEntryDefinition(id, label, binding, allowModifierCombos, allowModifierOnly, distinguishModifierSides, description)
			{
				MenuCapabilities = (ModSettingsMenuCapabilities.Copy | ModSettingsMenuCapabilities.ResetToDefault)
			};
			AddEntry(id, entry);
			return this;
		}

		/// <summary>
