		///     </para>
		/// </summary>
		public ModSettingsSectionBuilder AddInputBinding(string id, ModSettingsText label, IModSettingsValueBinding<string> binding, bool allowModifierCombos = true, bool allowModifierOnly = true, bool distinguishModifierSides = false, bool allowActionBindings = true, ModSettingsText? description = null)
		{
