		public ModSettingsSectionBuilder AddKeyBinding(string id, ModSettingsText label, IModSettingsValueBinding<List<string>> binding, bool allowMultipleBindings, bool allowModifierCombos = true, bool allowModifierOnly = true, bool distinguishModifierSides = false, ModSettingsText? description = null)
		{
			if (!allowMultipleBindings)
			{
				throw new InvalidOperationException("List<string> key binding rows require allowMultipleBindings=true to opt into native multi-binding support.");
			}
