		/// </summary>
		public ModSettingsSectionBuilder AddButton(string id, ModSettingsText label, ModSettingsText buttonText, Action<IModSettingsUiActionHost> action, ModSettingsButtonTone tone = ModSettingsButtonTone.Normal, ModSettingsText? description = null)
		{
			ArgumentNullException.ThrowIfNull(action, "action");
			AddEntry(id, new HostContextButtonModSettingsEntryDefinition(id, label, buttonText, action, tone, description));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Adds a row that navigates to the registered page <paramref name="targetPageId" />.</para>
		///     <para xml:lang="zh-CN">添加导航到已注册页面 <paramref name="targetPageId" /> 的行。</para>
		/// </summary>
		public ModSettingsSectionBuilder AddSubpage(string id, ModSettingsText label, string targetPageId, ModSettingsText? buttonText = null, ModSettingsText? description = null)
		{
			AddEntry(id, new SubpageModSettingsEntryDefinition(id, label, targetPageId, buttonText ?? ModSettingsText.Literal(">"), description));
			return this;
		}

