		///     <para xml:lang="en">Adds a custom row created by <paramref name="controlFactory" />.</para>
		///     <para xml:lang="zh-CN">添加由 <paramref name="controlFactory" /> 创建的自定义行。</para>
		/// </summary>
		public ModSettingsSectionBuilder AddCustom(string id, ModSettingsText label, Func<IModSettingsUiActionHost, Control> controlFactory, ModSettingsText? description = null, Func<bool>? visibleWhen = null)
		{
			ArgumentNullException.ThrowIfNull(controlFactory, "controlFactory");
			AddEntry(id, new CustomModSettingsEntryDefinition(id, label, controlFactory, description, visibleWhen));
			return this;
		}

		internal ModSettingsSection Build()
		{
			if (_entries.Count != 0)
			{
				return new ModSettingsSection(Id, Title, Description, IsCollapsible, StartCollapsed, BuildEntries(), _sectionVisibleWhen, _sectionEnabledWhen, _menuCapabilities, _sectionVisibleOnHostSurfaces, _sectionReadOnlyOnHostSurfaces);
			}
			throw new InvalidOperationException("Settings section '" + Id + "' has no entries.");
		}

		/// <summary>
		///     <para xml:lang="en">Sets the context-menu actions exposed for one previously added entry.</para>
		///     <para xml:lang="zh-CN">设置先前已添加条目所公开的上下文菜单操作。</para>
		/// </summary>
		public ModSettingsSectionBuilder ConfigureEntryMenu(string id, ModSettingsMenuCapabilities capabilities)
		{
			(_entries.FirstOrDefault((ModSettingsEntryDefinition existing) => string.Equals(existing.Id, id, StringComparison.OrdinalIgnoreCase)) ?? throw new InvalidOperationException($"Settings entry '{id}' does not exist in section '{Id}'.")).MenuCapabilities = capabilities;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets the host surfaces on which one previously added entry's interactive controls are read-only.
		///     </para>
		///     <para xml:lang="zh-CN">设置先前已添加条目的交互控件处于只读状态的宿主界面。</para>
		/// </summary>
		public ModSettingsSectionBuilder WithEntryReadOnlyOnHostSurfaces(string id, ModSettingsHostSurface surfaces)
		{
			(_entries.FirstOrDefault((ModSettingsEntryDefinition existing) => string.Equals(existing.Id, id, StringComparison.OrdinalIgnoreCase)) ?? throw new InvalidOperationException($"Settings entry '{id}' does not exist in section '{Id}'.")).ReadOnlyOnHostSurfaces = surfaces;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets a visibility predicate for one previously added entry. It applies to every entry type and is
		///         re-evaluated on settings UI refresh.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为先前已添加的条目设置可见性谓词；该谓词适用于所有条目类型，并会在设置界面刷新时重新求值。
		///     </para>
		/// </summary>
		public ModSettingsSectionBuilder WithEntryVisibleWhen(string id, Func<bool> predicate)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			if (!_entryIds.Contains(id))
			{
				throw new InvalidOperationException($"Settings entry '{id}' does not exist in section '{Id}'.");
			}
			_entryVisibleWhen[id] = predicate;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets an enabled-state predicate for one previously added entry. A false result dims the row and
		///         disables interaction.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为先前已添加的条目设置启用状态谓词；结果为 false 时该行会变暗且不可交互。
		///     </para>
		/// </summary>
		public ModSettingsSectionBuilder WithEntryEnabledWhen(string id, Func<bool> predicate)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			if (!_entryIds.Contains(id))
			{
				throw new InvalidOperationException($"Settings entry '{id}' does not exist in section '{Id}'.");
			}
			_entryEnabledWhen[id] = predicate;
			return this;
		}

		private void AddEntry(string id, ModSettingsEntryDefinition entry)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			if (!_entryIds.Add(id))
			{
				throw new InvalidOperationException($"Duplicate settings entry id '{id}' in section '{Id}'.");
			}
			_entries.Add(entry);
		}

		private ModSettingsEntryDefinition[] BuildEntries()
		{
			ModSettingsEntryDefinition[] array = new ModSettingsEntryDefinition[_entries.Count];
			for (int i = 0; i < _entries.Count; i++)
			{
				ModSettingsEntryDefinition modSettingsEntryDefinition = _entries[i];
				if (_entryEnabledWhen.TryGetValue(modSettingsEntryDefinition.Id, out Func<bool> value))
				{
					modSettingsEntryDefinition = new ModSettingsEntryEnabledWrapper(modSettingsEntryDefinition, value)
					{
						MenuCapabilities = modSettingsEntryDefinition.MenuCapabilities,
						ReadOnlyOnHostSurfaces = modSettingsEntryDefinition.ReadOnlyOnHostSurfaces
					};
				}
				if (_entryVisibleWhen.TryGetValue(modSettingsEntryDefinition.Id, out Func<bool> value2))
				{
					ModSettingsEntryVisibilityWrapper modSettingsEntryVisibilityWrapper = new ModSettingsEntryVisibilityWrapper(modSettingsEntryDefinition, value2)
					{
						MenuCapabilities = modSettingsEntryDefinition.MenuCapabilities,
						ReadOnlyOnHostSurfaces = modSettingsEntryDefinition.ReadOnlyOnHostSurfaces
					};
					array[i] = modSettingsEntryVisibilityWrapper;
				}
				else
				{
					array[i] = modSettingsEntryDefinition;
				}
			}
			return array;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Captures one setting value in a page or section snapshot. Restoring it uses the same type, schema, and
	///         scalar-conversion rules as a single-value clipboard operation.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         捕获页面或节快照中的一个设置值。恢复时采用与单值剪贴板操作相同的类型、架构与标量转换规则。
	///     </para>
	/// </summary>
	/// <param name="TypeFullName">
	///     <para xml:lang="en">The captured value type's CLR full name.</para>
