	/// <summary>
	///     <para xml:lang="en">
	///         Contains all setting snapshots on one page, keyed first by section ID and then by entry ID.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         包含一个页面中的全部设置快照，先按节 ID、再按条目 ID 索引。
	///     </para>
	/// </summary>
	/// <param name="ModId">
	///     <para xml:lang="en">The owning mod ID.</para>
	///     <para xml:lang="zh-CN">所属模组 ID。</para>
	/// </param>
	/// <param name="PageId">
	///     <para xml:lang="en">The source page ID.</para>
	///     <para xml:lang="zh-CN">源页面 ID。</para>
	/// </param>
	/// <param name="Sections">
	///     <para xml:lang="en">The setting snapshots keyed by section ID and then entry ID.</para>
	///     <para xml:lang="zh-CN">先按节 ID、再按条目 ID 索引的设置快照。</para>
	/// </param>
	public sealed record ModSettingsPageDataClipboardPayload(string ModId, string PageId, Dictionary<string, Dictionary<string, ModSettingsChromeBindingSnapshot>> Sections);
	internal static class ModSettingsClipboardData
	{
		private sealed record ClipboardSerializableMember(string JsonName, Type ValueType);

		private const string ClipboardKind = "ritsulib.settings.value";

		private static readonly ConcurrentDictionary<Type, string> SchemaSignatureCache = new ConcurrentDictionary<Type, string>();

		private static readonly ConcurrentDictionary<Type, ClipboardSerializableMember[]> SerializableMemberCache = new ConcurrentDictionary<Type, ClipboardSerializableMember[]>();

		/// <summary>
		///     <para xml:lang="en">
		///         Maps CLR full names accepted as numeric source types in
		///         <see cref="P:STS2RitsuLib.Settings.ModSettingsClipboardEnvelope.TypeName" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         映射 <see cref="P:STS2RitsuLib.Settings.ModSettingsClipboardEnvelope.TypeName" /> 中可作为数值源类型接受的 CLR 全名。
		///     </para>
		/// </summary>
		private static readonly FrozenDictionary<string, Type> NumericEnvelopeTypes = new Type[11]
		{
			typeof(byte),
			typeof(sbyte),
			typeof(short),
			typeof(ushort),
			typeof(int),
			typeof(uint),
			typeof(long),
			typeof(ulong),
			typeof(float),
			typeof(double),
			typeof(decimal)
		}.ToFrozenDictionary<Type, string>((Type type) => type.FullName, StringComparer.Ordinal);

		public static void CopyValue<TValue>(IModSettingsBinding binding, ModSettingsClipboardScope scope, IStructuredModSettingsValueAdapter<TValue> adapter, TValue value)
		{
			WriteClipboardEnvelope(new ModSettingsClipboardEnvelope("ritsulib.settings.value", typeof(TValue).FullName ?? typeof(TValue).Name, CreateTargetSignature(binding), GetSchemaSignature(typeof(TValue)), scope, adapter.Serialize(value)));
		}

		internal static void WriteClipboardEnvelope(ModSettingsClipboardEnvelope envelope)
		{
			DisplayServer.ClipboardSet(JsonSerializer.Serialize(envelope));
			ModSettingsClipboardAccess.InvalidateCache();
		}

		public static bool TryReadValue<TValue>(IModSettingsBinding binding, IStructuredModSettingsValueAdapter<TValue> adapter, out TValue value)
		{
			return TryReadValue(binding, adapter, out value, requireMatchingSourceBinding: false);
		}

		internal static string GetSchemaSignatureForType(Type type)
		{
			return GetSchemaSignature(type);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Reads a value captured in <see cref="T:STS2RitsuLib.Settings.ModSettingsChromeBindingSnapshot" /> for the target binding,
		///         applying the single-value clipboard compatibility rules without requiring a matching source-binding
		///         signature.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为目标绑定读取 <see cref="T:STS2RitsuLib.Settings.ModSettingsChromeBindingSnapshot" /> 中捕获的值，
		///         采用单值剪贴板兼容规则，但不要求源绑定签名匹配。
		///     </para>
		/// </summary>
		internal static bool TryApplySerializedValueToBinding<TValue>(IModSettingsValueBinding<TValue> binding, IStructuredModSettingsValueAdapter<TValue> adapter, ModSettingsChromeBindingSnapshot snap, out TValue value)
		{
			ModSettingsClipboardEnvelope envelope = new ModSettingsClipboardEnvelope("ritsulib.settings.value", snap.TypeFullName, string.Empty, snap.SchemaSignature, ModSettingsClipboardScope.Self, snap.JsonPayload);
			if (!TryReadEnvelopePayloadForTarget<TValue>(binding, envelope, requireMatchingSourceBinding: false, out string payload))
			{
				return TryReadCoercedScalarFromEnvelope<TValue>(binding, envelope, requireMatchingSourceBinding: false, out value);
			}
			if (adapter.TryDeserialize(payload, out value))
			{
				return true;
			}
			if (TryCoerceJsonPayloadToValue<TValue>(payload, out value))
			{
				return true;
			}
			value = default(TValue);
			return false;
		}

		internal static void AddChromeBindingSnapshot<T>(Dictionary<string, ModSettingsChromeBindingSnapshot> target, string entryId, IModSettingsValueBinding<T> binding)
		{
			IStructuredModSettingsValueAdapter<T> structuredModSettingsValueAdapter = ((binding is IStructuredModSettingsValueBinding<T> structuredModSettingsValueBinding) ? structuredModSettingsValueBinding.Adapter : ModSettingsStructuredData.Json<T>());
			Type typeFromHandle = typeof(T);
			target[entryId] = new ModSettingsChromeBindingSnapshot(typeFromHandle.FullName ?? typeFromHandle.Name, GetSchemaSignature(typeFromHandle), structuredModSettingsValueAdapter.Serialize(binding.Read()));
		}

		internal static bool TryReadValue<TValue>(IModSettingsBinding binding, IStructuredModSettingsValueAdapter<TValue> adapter, out TValue value, bool requireMatchingSourceBinding)
		{
			if (!ModSettingsClipboardAccess.TryGetText(out string text))
			{
				value = default(TValue);
				return false;
			}
			if (TryDeserializeEnvelope(text, out ModSettingsClipboardEnvelope envelope) && envelope != null && string.Equals(envelope.Kind, "ritsulib.settings.value", StringComparison.Ordinal))
			{
				if (TryReadEnvelopePayloadForTarget<TValue>(binding, envelope, requireMatchingSourceBinding, out string payload))
				{
					if (adapter.TryDeserialize(payload, out value))
					{
						return true;
					}
					if (TryCoerceJsonPayloadToValue<TValue>(payload, out value))
					{
						return true;
					}
					value = default(TValue);
					return false;
				}
				if (TryReadCoercedScalarFromEnvelope<TValue>(binding, envelope, requireMatchingSourceBinding, out value))
				{
					return true;
				}
				value = default(TValue);
				return false;
			}
			if (MatchesJsonShape(typeof(TValue), text))
			{
				return adapter.TryDeserialize(text, out value);
			}
			value = default(TValue);
			return false;
		}

		internal static bool TryDeserializeEnvelope(string clipboard, out ModSettingsClipboardEnvelope? envelope)
		{
			try
			{
				envelope = JsonSerializer.Deserialize<ModSettingsClipboardEnvelope>(clipboard);
				ModSettingsClipboardEnvelope modSettingsClipboardEnvelope = envelope;
				int result;
				if ((object)modSettingsClipboardEnvelope != null)
				{
					string kind = modSettingsClipboardEnvelope.Kind;
					if (kind != null && kind.Length > 0 && modSettingsClipboardEnvelope.TypeName != null && modSettingsClipboardEnvelope.TargetSignature != null && modSettingsClipboardEnvelope.SchemaSignature != null)
					{
						result = ((modSettingsClipboardEnvelope.Payload != null) ? 1 : 0);
						goto IL_0046;
					}
				}
				result = 0;
				goto IL_0046;
				IL_0046:
				return (byte)result != 0;
			}
			catch (JsonException)
			{
				envelope = null;
				return false;
			}
		}

		internal static bool TryReadEnvelopePayloadForTarget<TValue>(IModSettingsBinding binding, ModSettingsClipboardEnvelope? envelope, bool requireMatchingSourceBinding, out string payload)
		{
			payload = string.Empty;
			if ((object)envelope != null)
			{
				string kind = envelope.Kind;
				if (string.Equals(kind, "ritsulib.settings.value", StringComparison.Ordinal))
				{
					if (!string.Equals(envelope.TypeName, typeof(TValue).FullName ?? typeof(TValue).Name, StringComparison.Ordinal))
					{
						return false;
					}
					if (requireMatchingSourceBinding && !string.Equals(envelope.TargetSignature, CreateTargetSignature(binding), StringComparison.Ordinal))
					{
						return false;
					}
					if (!string.Equals(envelope.SchemaSignature, GetSchemaSignature(typeof(TValue)), StringComparison.Ordinal))
					{
						return false;
					}
					payload = envelope.Payload;
					return true;
				}
			}
			return false;
		}

		private static string CreateTargetSignature(IModSettingsBinding binding)
		{
			return $"{binding.ModId}:{binding.Scope}:{NormalizeDataKey(binding.DataKey)}";
		}

		private static string NormalizeDataKey(string dataKey)
		{
			if (string.IsNullOrWhiteSpace(dataKey))
			{
				return string.Empty;
			}
			StringBuilder stringBuilder = new StringBuilder(dataKey.Length);
			for (int i = 0; i < dataKey.Length; i++)
			{
				if (dataKey[i] != '[')
				{
					stringBuilder.Append(dataKey[i]);
					continue;
				}
				stringBuilder.Append("[]");
				for (; i + 1 < dataKey.Length && dataKey[i + 1] != ']'; i++)
				{
				}
				if (i + 1 < dataKey.Length && dataKey[i + 1] == ']')
				{
					i++;
				}
			}
			return stringBuilder.ToString();
		}

		private static string GetSchemaSignature(Type type)
		{
			return SchemaSignatureCache.GetOrAdd(type, (Type targetType) => BuildSchemaSignature(targetType, new HashSet<Type>()));
		}

		private static string BuildSchemaSignature(Type type, HashSet<Type> activeTypes)
		{
			Type type2 = Nullable.GetUnderlyingType(type) ?? type;
			if (!activeTypes.Add(type2))
			{
				return type2.FullName ?? type2.Name;
			}
			try
			{
				if (type2 == typeof(string))
				{
					return "string";
				}
				if (type2 == typeof(bool))
				{
					return "bool";
				}
				if (type2.IsEnum)
				{
					return "enum:" + type2.FullName + ":" + string.Join(',', Enum.GetNames(type2));
				}
				if (IsNumericType(type2))
				{
					return "number:" + type2.FullName;
				}
				if (TryGetCollectionElementType(type2, out Type elementType))
				{
					return "array<" + BuildSchemaSignature(elementType, activeTypes) + ">";
				}
				ClipboardSerializableMember[] serializableMembers = GetSerializableMembers(type2);
				if (serializableMembers.Length == 0)
				{
					return type2.FullName ?? type2.Name;
				}
				return $"object:{type2.FullName}{{{string.Join(',', serializableMembers.Select((ClipboardSerializableMember member) => member.JsonName + ":" + BuildSchemaSignature(member.ValueType, activeTypes)))}}}";
			}
			finally
			{
				activeTypes.Remove(type2);
			}
		}

		private static bool MatchesJsonShape(Type type, string json)
		{
			try
			{
				using JsonDocument jsonDocument = JsonDocument.Parse(json);
				return MatchesElement(type, jsonDocument.RootElement);
			}
			catch (JsonException)
			{
				return false;
			}
		}

		private static bool MatchesElement(Type type, JsonElement element)
		{
			Type type2 = Nullable.GetUnderlyingType(type) ?? type;
			if (element.ValueKind == JsonValueKind.Null)
			{
				return CanBeNull(type);
			}
			if (type2 == typeof(string))
			{
				return element.ValueKind == JsonValueKind.String;
			}
			if (type2 == typeof(bool))
			{
				JsonValueKind valueKind = element.ValueKind;
				if (valueKind - 5 <= JsonValueKind.Object)
				{
					return true;
				}
				return false;
			}
			if (type2.IsEnum)
			{
				JsonValueKind valueKind = element.ValueKind;
				if (valueKind - 3 <= JsonValueKind.Object)
				{
					return true;
				}
				return false;
			}
			if (IsNumericType(type2))
			{
				return element.ValueKind == JsonValueKind.Number;
			}
			if (TryGetCollectionElementType(type2, out Type elementType))
			{
				if (element.ValueKind == JsonValueKind.Array)
				{
					return element.EnumerateArray().All((JsonElement child) => MatchesElement(elementType, child));
				}
				return false;
			}
			if (element.ValueKind != JsonValueKind.Object)
			{
				return false;
			}
			ClipboardSerializableMember[] serializableMembers = GetSerializableMembers(type2);
			if (serializableMembers.Length == 0)
			{
				return false;
			}
			Dictionary<string, JsonElement> dictionary = new Dictionary<string, JsonElement>(StringComparer.Ordinal);
			foreach (JsonProperty item in element.EnumerateObject())
			{
				if (!dictionary.TryAdd(item.Name, item.Value))
				{
					return false;
				}
			}
			ClipboardSerializableMember[] array = serializableMembers;
			foreach (ClipboardSerializableMember clipboardSerializableMember in array)
			{
				if (!dictionary.Remove(clipboardSerializableMember.JsonName, out var value))
				{
					return false;
				}
				if (!MatchesElement(clipboardSerializableMember.ValueType, value))
				{
					return false;
				}
			}
			return dictionary.Count == 0;
		}

		private static ClipboardSerializableMember[] GetSerializableMembers(Type type)
		{
			return SerializableMemberCache.GetOrAdd(type, delegate(Type targetType)
			{
				Dictionary<string, ClipboardSerializableMember> dictionary = new Dictionary<string, ClipboardSerializableMember>(StringComparer.Ordinal);
				PropertyInfo[] properties = targetType.GetProperties(BindingFlags.Instance | BindingFlags.Public);
				foreach (PropertyInfo propertyInfo in properties)
				{
					if (propertyInfo.GetIndexParameters().Length == 0 && !(propertyInfo.GetMethod == null) && propertyInfo.GetMethod.IsPublic)
					{
						JsonIgnoreAttribute? customAttribute = propertyInfo.GetCustomAttribute<JsonIgnoreAttribute>();
						if (customAttribute == null || customAttribute.Condition != JsonIgnoreCondition.Always)
						{
							string text = propertyInfo.GetCustomAttribute<JsonPropertyNameAttribute>()?.Name ?? propertyInfo.Name;
							dictionary[text] = new ClipboardSerializableMember(text, propertyInfo.PropertyType);
						}
					}
				}
				FieldInfo[] fields = targetType.GetFields(BindingFlags.Instance | BindingFlags.Public);
				foreach (FieldInfo fieldInfo in fields)
				{
					if (!fieldInfo.IsStatic)
					{
						JsonIgnoreAttribute? customAttribute2 = fieldInfo.GetCustomAttribute<JsonIgnoreAttribute>();
						if (customAttribute2 == null || customAttribute2.Condition != JsonIgnoreCondition.Always)
						{
							string text2 = fieldInfo.GetCustomAttribute<JsonPropertyNameAttribute>()?.Name ?? fieldInfo.Name;
							dictionary.TryAdd(text2, new ClipboardSerializableMember(text2, fieldInfo.FieldType));
						}
					}
				}
				return dictionary.Values.OrderBy<ClipboardSerializableMember, string>((ClipboardSerializableMember member) => member.JsonName, StringComparer.Ordinal).ToArray();
			});
		}

		private static bool CanBeNull(Type type)
		{
			if (type.IsValueType)
			{
				return Nullable.GetUnderlyingType(type) != null;
			}
			return true;
		}

		private static bool IsNumericType(Type type)
		{
			TypeCode typeCode = Type.GetTypeCode(type);
			if ((uint)(typeCode - 5) <= 10u)
			{
				return true;
			}
			return false;
		}

		private static bool TryGetCollectionElementType(Type type, out Type elementType)
		{
			if (type.IsArray)
			{
				elementType = type.GetElementType();
				return true;
			}
			if (type.IsGenericType)
			{
				Type genericTypeDefinition = type.GetGenericTypeDefinition();
				if (genericTypeDefinition == typeof(List<>) || genericTypeDefinition == typeof(IList<>) || genericTypeDefinition == typeof(IReadOnlyList<>))
				{
					elementType = type.GetGenericArguments()[0];
					return true;
				}
			}
			elementType = null;
			return false;
		}

		private static bool TryReadCoercedScalarFromEnvelope<TValue>(IModSettingsBinding binding, ModSettingsClipboardEnvelope envelope, bool requireMatchingSourceBinding, out TValue value)
		{
			value = default(TValue);
			if (!IsCoercibleScalarTarget(typeof(TValue)))
			{
				return false;
			}
			if (requireMatchingSourceBinding && !string.Equals(envelope.TargetSignature, CreateTargetSignature(binding), StringComparison.Ordinal))
			{
				return false;
			}
			if (CanCoerceClipboardEnvelopeScalarTo(typeof(TValue), envelope.TypeName) && IsEnvelopeScalarPayloadValid(envelope.TypeName, envelope.Payload))
			{
				return TryCoerceJsonPayloadToValue<TValue>(envelope.Payload, out value);
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Allows scalar fallback for the same declared CLR type, lossless numeric widening, and supported
		///         numeric-to-enum or numeric-to-Boolean conversions. It deliberately rejects unrelated values such as a
		///         copied <see cref="T:System.Double" /> slider value becoming a <see cref="T:System.String" /> choice key.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         允许相同 CLR 声明类型、无损数值拓宽，以及受支持的数值到枚举或布尔值转换作为标量回退。
		///         此规则会明确拒绝无关值，例如不会把复制的 <see cref="T:System.Double" /> 滑块值转换成
		///         <see cref="T:System.String" /> 选项键。
		///     </para>
		/// </summary>
		private static bool CanCoerceClipboardEnvelopeScalarTo(Type targetValueType, string envelopeTypeName)
		{
			if (string.IsNullOrEmpty(envelopeTypeName))
			{
				return false;
			}
			Type type = Nullable.GetUnderlyingType(targetValueType) ?? targetValueType;
			string b = type.FullName ?? type.Name;
			if (string.Equals(envelopeTypeName, b, StringComparison.Ordinal))
			{
				return true;
			}
			if (type == typeof(string))
			{
				return false;
			}
			if (IsNumericType(type) && NumericEnvelopeTypes.TryGetValue(envelopeTypeName, out Type value))
			{
				return CanWidenNumericWithoutLoss(value, type);
			}
			if (type.IsEnum)
			{
				if (!NumericEnvelopeTypes.ContainsKey(envelopeTypeName))
				{
					return string.Equals(envelopeTypeName, type.FullName ?? type.Name, StringComparison.Ordinal);
				}
				return true;
			}
			if (type == typeof(bool))
			{
				if (!NumericEnvelopeTypes.ContainsKey(envelopeTypeName))
				{
					return string.Equals(envelopeTypeName, typeof(bool).FullName, StringComparison.Ordinal);
				}
				return true;
			}
			return false;
		}

		private static bool CanWidenNumericWithoutLoss(Type sourceType, Type targetType)
		{
			if (sourceType == targetType)
			{
				return true;
			}
			switch (Type.GetTypeCode(sourceType))
			{
			case TypeCode.SByte:
				return targetType == typeof(short) || targetType == typeof(int) || targetType == typeof(long) || targetType == typeof(float) || targetType == typeof(double) || targetType == typeof(decimal);
			case TypeCode.Byte:
				return targetType == typeof(short) || targetType == typeof(ushort) || targetType == typeof(int) || targetType == typeof(uint) || targetType == typeof(long) || targetType == typeof(ulong) || targetType == typeof(float) || targetType == typeof(double) || targetType == typeof(decimal);
			case TypeCode.Int16:
				return targetType == typeof(int) || targetType == typeof(long) || targetType == typeof(float) || targetType == typeof(double) || targetType == typeof(decimal);
			case TypeCode.UInt16:
				return targetType == typeof(int) || targetType == typeof(uint) || targetType == typeof(long) || targetType == typeof(ulong) || targetType == typeof(float) || targetType == typeof(double) || targetType == typeof(decimal);
			case TypeCode.Int32:
				return targetType == typeof(long) || targetType == typeof(double) || targetType == typeof(decimal);
			case TypeCode.UInt32:
				return targetType == typeof(long) || targetType == typeof(ulong) || targetType == typeof(double) || targetType == typeof(decimal);
			case TypeCode.Int64:
			case TypeCode.UInt64:
				return targetType == typeof(decimal);
			case TypeCode.Single:
				return targetType == typeof(double);
			default:
				return false;
			}
		}

		private static bool IsCoercibleScalarTarget(Type type)
		{
			Type type2 = Nullable.GetUnderlyingType(type) ?? type;
			if (!(type2 == typeof(string)) && !(type2 == typeof(bool)) && !type2.IsEnum)
			{
				return IsNumericType(type2);
			}
			return true;
		}

		private static bool IsEnvelopeScalarPayloadValid(string envelopeTypeName, string json)
		{
			if (!NumericEnvelopeTypes.TryGetValue(envelopeTypeName, out Type value))
			{
				return true;
			}
			try
			{
				using JsonDocument jsonDocument = JsonDocument.Parse(json);
				object converted;
				return TryConvertNumericElement(jsonDocument.RootElement, value, out converted);
			}
			catch (JsonException)
			{
				return false;
			}
		}

		private static bool TryCoerceJsonPayloadToValue<TValue>(string json, out TValue value)
		{
			value = default(TValue);
			try
			{
				using JsonDocument jsonDocument = JsonDocument.Parse(json);
				return TryCoerceJsonElement<TValue>(jsonDocument.RootElement, out value);
			}
			catch (JsonException)
			{
				return false;
			}
		}

		private static bool TryCoerceJsonElement<TValue>(JsonElement element, out TValue value)
		{
			value = default(TValue);
			Type typeFromHandle = typeof(TValue);
			Type type = Nullable.GetUnderlyingType(typeFromHandle) ?? typeFromHandle;
			try
			{
				if (type == typeof(string))
				{
					value = (TValue)(element.ValueKind switch
					{
						JsonValueKind.String => element.GetString() ?? string.Empty, 
						JsonValueKind.Number => element.GetRawText(), 
						JsonValueKind.True => "true", 
						JsonValueKind.False => "false", 
						JsonValueKind.Null => string.Empty, 
						_ => element.GetRawText(), 
					});
					return true;
				}
				if (type == typeof(bool))
				{
					switch (element.ValueKind)
					{
					case JsonValueKind.True:
						value = (TValue)(object)true;
						return true;
					case JsonValueKind.False:
						value = (TValue)(object)false;
						return true;
					case JsonValueKind.String:
					{
						if (!bool.TryParse(element.GetString(), out var result))
						{
							return false;
						}
						value = (TValue)(object)result;
						return true;
					}
					case JsonValueKind.Number:
					{
						if (!element.TryGetInt64(out var value2))
						{
							return false;
						}
						value = (TValue)(object)(value2 != 0);
						return true;
					}
					default:
						return false;
					}
				}
				if (IsNumericType(type))
				{
					if (!TryConvertNumericElement(element, type, out object converted))
					{
						return false;
					}
					value = (TValue)converted;
					return true;
				}
				if (!type.IsEnum)
				{
					return false;
				}
				switch (element.ValueKind)
				{
				case JsonValueKind.String:
				{
					string value4 = element.GetString();
					if (string.IsNullOrEmpty(value4))
					{
						return false;
					}
					if (!Enum.TryParse(type, value4, ignoreCase: true, out object result2))
					{
						return false;
					}
					value = (TValue)result2;
					return true;
				}
				case JsonValueKind.Number:
				{
					if (!element.TryGetInt64(out var value3))
					{
						return false;
					}
					value = (TValue)Enum.ToObject(type, value3);
					return true;
				}
				default:
					return false;
				}
			}
			catch (InvalidCastException)
			{
				return false;
			}
			catch (OverflowException)
			{
				return false;
			}
		}

		private static bool TryConvertNumericElement(JsonElement element, Type targetType, out object converted)
		{
			converted = null;
			try
			{
				switch (element.ValueKind)
				{
				case JsonValueKind.Number:
					converted = JsonSerializer.Deserialize(element.GetRawText(), targetType);
					return converted != null;
				case JsonValueKind.String:
				{
					string value = element.GetString();
					if (string.IsNullOrWhiteSpace(value))
					{
						return false;
					}
					converted = Convert.ChangeType(value, targetType, CultureInfo.InvariantCulture);
					object obj = converted;
					return (obj is float f) ? float.IsFinite(f) : (!(obj is double d) || double.IsFinite(d));
				}
				default:
					return false;
				}
			}
			catch (JsonException)
			{
				converted = null;
				return false;
			}
			catch (FormatException)
			{
				converted = null;
				return false;
			}
			catch (InvalidCastException)
			{
				converted = null;
				return false;
			}
			catch (OverflowException)
			{
				converted = null;
				return false;
			}
		}
	}
	internal sealed record ModSettingsClipboardEnvelope(string Kind, string TypeName, string TargetSignature, string SchemaSignature, ModSettingsClipboardScope Scope, string Payload);
	/// <summary>
	///     <para xml:lang="en">
	///         Provides non-throwing clipboard text reads cached for one Godot process frame. This avoids repeatedly
	///         opening the operating-system clipboard when several menus query paste availability in the same frame.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供不会抛出异常且按 Godot 进程帧缓存的剪贴板文本读取，避免多个菜单在同一帧检查粘贴可用性时反复访问系统剪贴板。
	///     </para>
	/// </summary>
	public static class ModSettingsClipboardAccess
	{
		private static ulong _cacheFrame = ulong.MaxValue;

		private static string _cacheText = string.Empty;

		/// <summary>
		///     <para xml:lang="en">
		///         Invalidates the in-memory cache so the next read accesses the operating-system clipboard.
		///     </para>
		///     <para xml:lang="zh-CN">使内存缓存失效，以便下一次读取重新访问系统剪贴板。</para>
		/// </summary>
		public static void InvalidateCache()
		{
			_cacheFrame = ulong.MaxValue;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to read non-whitespace clipboard text, returning false when the clipboard is empty,
		///         unavailable, or cannot be read.
		///     </para>
		///     <para xml:lang="zh-CN">尝试读取非空白剪贴板文本；剪贴板为空、不可用或无法读取时返回 false。</para>
		/// </summary>
		public static bool TryGetText(out string text)
		{
			text = string.Empty;
			ulong processFrames = Engine.GetProcessFrames();
			if (_cacheFrame == processFrames)
			{
				if (string.IsNullOrWhiteSpace(_cacheText))
				{
					return false;
				}
				text = _cacheText;
				return true;
			}
			_cacheFrame = processFrames;
			try
			{
				_cacheText = DisplayServer.ClipboardGet() ?? string.Empty;
			}
			catch
			{
				_cacheText = string.Empty;
			}
			if (string.IsNullOrWhiteSpace(_cacheText))
			{
				return false;
			}
			text = _cacheText;
			return true;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Describes a binding copy request before the default clipboard envelope is written. A handler can set
	///         <see cref="P:STS2RitsuLib.Settings.ModSettingsCopyActionEventArgs.SuppressDefaultClipboardWrite" /> after performing its own clipboard write.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         描述默认剪贴板信封写入前的绑定复制请求；处理器自行写入剪贴板后可设置
	///         <see cref="P:STS2RitsuLib.Settings.ModSettingsCopyActionEventArgs.SuppressDefaultClipboardWrite" />。
	///     </para>
	/// </summary>
	public sealed class ModSettingsCopyActionEventArgs(IModSettingsBinding binding, Type valueType, object? value, ModSettingsClipboardScope scope) : EventArgs
	{
		/// <summary>
		///     <para xml:lang="en">Gets the binding whose value is being copied.</para>
		///     <para xml:lang="zh-CN">获取正在复制其值的绑定。</para>
		/// </summary>
		public IModSettingsBinding Binding { get; } = binding ?? throw new ArgumentNullException("binding");

		/// <summary>
		///     <para xml:lang="en">Gets the CLR type of the copied value.</para>
		///     <para xml:lang="zh-CN">获取所复制值的 CLR 类型。</para>
		/// </summary>
		public Type ValueType { get; } = valueType ?? throw new ArgumentNullException("valueType");

		/// <summary>
		///     <para xml:lang="en">Gets the current value snapshot supplied to copy handlers and serializers.</para>
		///     <para xml:lang="zh-CN">获取传给复制处理器及序列化器的当前值快照。</para>
		/// </summary>
		public object? Value { get; } = value;

		/// <summary>
		///     <para xml:lang="en">Gets whether the request copies only the value itself or its supported subtree.</para>
		///     <para xml:lang="zh-CN">获取此次请求复制的范围是仅值自身还是其支持的子树。</para>
		/// </summary>
		public ModSettingsClipboardScope Scope { get; } = scope;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or sets whether the default JSON envelope write is skipped. If a handler throws, changes made
		///         by that handler to this property are rolled back.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或设置是否跳过默认 JSON 信封写入；处理器抛出异常时，该处理器对此属性所作的更改会被撤销。
		///     </para>
		/// </summary>
		public bool SuppressDefaultClipboardWrite { get; set; }
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Exposes an immutable clipboard-envelope snapshot to paste validation rules without exposing internal
	///         serialization types.
	///     </para>
	///     <para xml:lang="zh-CN">向粘贴校验规则公开不可变的剪贴板信封快照，同时隐藏内部序列化类型。</para>
	/// </summary>
	/// <param name="Kind">
	///     <para xml:lang="en">The envelope discriminator, such as a binding value or UI snapshot.</para>
	///     <para xml:lang="zh-CN">信封判别符，例如绑定值或界面快照。</para>
	/// </param>
	/// <param name="TypeName">
	///     <para xml:lang="en">The serialized CLR or logical type name for the payload.</para>
	///     <para xml:lang="zh-CN">载荷的序列化 CLR 类型名或逻辑类型名。</para>
	/// </param>
	/// <param name="TargetSignature">
	///     <para xml:lang="en">The source binding signature recorded for a copied setting.</para>
	///     <para xml:lang="zh-CN">为所复制设置记录的源绑定签名。</para>
	/// </param>
	/// <param name="SchemaSignature">
	///     <para xml:lang="en">The adapter schema signature used for compatibility checks.</para>
	///     <para xml:lang="zh-CN">用于兼容性检查的适配器架构签名。</para>
	/// </param>
	/// <param name="Scope">
	///     <para xml:lang="en">Whether the envelope represents only the target itself or its supported subtree.</para>
	///     <para xml:lang="zh-CN">信封表示仅目标自身还是其支持的子树。</para>
	/// </param>
	/// <param name="Payload">
	///     <para xml:lang="en">The JSON or adapter-defined opaque payload.</para>
	///     <para xml:lang="zh-CN">JSON 或由适配器定义的不透明载荷。</para>
	/// </param>
	public sealed record ModSettingsClipboardEnvelopeView(string Kind, string TypeName, string TargetSignature, string SchemaSignature, ModSettingsClipboardScope Scope, string Payload);
	/// <summary>
	///     <para xml:lang="en">Identifies why a binding paste was not applied, for settings UI feedback.</para>
	///     <para xml:lang="zh-CN">标识绑定粘贴未应用的原因，供设置界面反馈使用。</para>
	/// </summary>
	public enum ModSettingsPasteFailureReason
	{
		/// <summary>
		///     <para xml:lang="en">The paste succeeded, or no failure has been classified.</para>
		///     <para xml:lang="zh-CN">粘贴成功，或尚未归类失败原因。</para>
		/// </summary>
		None,
		/// <summary>
		///     <para xml:lang="en">Clipboard text was empty, unavailable, or unreadable.</para>
		///     <para xml:lang="zh-CN">剪贴板文本为空、不可用或无法读取。</para>
		/// </summary>
		ClipboardEmpty,
		/// <summary>
		///     <para xml:lang="en">
		///         A registered paste rule returned <see cref="F:STS2RitsuLib.Settings.ModSettingsPasteVerdict.Deny" /> or threw an exception.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         已注册的粘贴规则返回 <see cref="F:STS2RitsuLib.Settings.ModSettingsPasteVerdict.Deny" /> 或抛出异常。
		///     </para>
		/// </summary>
		PasteRuleDenied,
		/// <summary>
		///     <para xml:lang="en">No custom parser or default adapter accepted the clipboard payload.</para>
		///     <para xml:lang="zh-CN">没有自定义解析器或默认适配器接受剪贴板载荷。</para>
		/// </summary>
		TypeOrShapeMismatch
	}
	/// <summary>
	///     <para xml:lang="en">Specifies whether a paste rule allows default validation to continue or vetoes the paste.</para>
	///     <para xml:lang="zh-CN">指定粘贴规则是允许继续默认校验，还是拒绝此次粘贴。</para>
	/// </summary>
	public enum ModSettingsPasteVerdict
	{
		/// <summary>
		///     <para xml:lang="en">Allows remaining rules, custom parsers, and default adapter validation to continue.</para>
		///     <para xml:lang="zh-CN">允许继续执行其余规则、自定义解析器及默认适配器校验。</para>
		/// </summary>
		UseDefault,
		/// <summary>
		///     <para xml:lang="en">Rejects the paste before any value is written to the target binding.</para>
		///     <para xml:lang="zh-CN">在向目标绑定写入任何值之前拒绝粘贴。</para>
		/// </summary>
		Deny
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Supplies the target and clipboard data to a paste validation rule. <see cref="P:STS2RitsuLib.Settings.ModSettingsPasteValidationContext.Envelope" /> is null when
	///         the text is not a recognized RitsuLib settings envelope.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         向粘贴校验规则提供目标及剪贴板数据；文本不是可识别的 RitsuLib 设置信封时，
	///         <see cref="P:STS2RitsuLib.Settings.ModSettingsPasteValidationContext.Envelope" /> 为 null。
	///     </para>
	/// </summary>
	public sealed class ModSettingsPasteValidationContext
	{
		/// <summary>
		///     <para xml:lang="en">Gets the binding that would receive the pasted value.</para>
		///     <para xml:lang="zh-CN">获取将接收粘贴值的绑定。</para>
		/// </summary>
		public required IModSettingsBinding TargetBinding { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the value type expected by <see cref="P:STS2RitsuLib.Settings.ModSettingsPasteValidationContext.TargetBinding" />.</para>
		///     <para xml:lang="zh-CN">获取 <see cref="P:STS2RitsuLib.Settings.ModSettingsPasteValidationContext.TargetBinding" /> 期望的值类型。</para>
		/// </summary>
		public required Type TargetValueType { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the raw clipboard text, whether or not it is a recognized envelope.</para>
		///     <para xml:lang="zh-CN">获取原始剪贴板文本，无论其是否为可识别的信封。</para>
		/// </summary>
		public required string ClipboardText { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the parsed metadata when <see cref="P:STS2RitsuLib.Settings.ModSettingsPasteValidationContext.ClipboardText" /> is a recognized RitsuLib settings
		///         envelope.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当 <see cref="P:STS2RitsuLib.Settings.ModSettingsPasteValidationContext.ClipboardText" /> 是可识别的 RitsuLib 设置信封时，获取解析出的元数据。
		///     </para>
		/// </summary>
		public ModSettingsClipboardEnvelopeView? Envelope { get; init; }
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Attempts to parse clipboard text into <typeparamref name="TValue" /> before the built-in envelope and
	///         adapter path. Returning true accepts <c>value</c> and skips default deserialization.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在内置信封及适配器路径之前尝试将剪贴板文本解析为 <typeparamref name="TValue" />；返回 true
	///         时接受 <c>value</c> 并跳过默认反序列化。
	///     </para>
	/// </summary>
	public delegate bool ModSettingsTryPasteApplier<TValue>(IModSettingsValueBinding<TValue> binding, IStructuredModSettingsValueAdapter<TValue> adapter, string clipboardText, out TValue value);
	/// <summary>
	///     <para xml:lang="en">
	///         Coordinates binding copy and paste through default envelopes, copy handlers, paste rules, custom parsers,
	///         and optional strict source-binding matching.
	///     </para>
	///     <para xml:lang="zh-CN">通过默认信封、复制处理器、粘贴规则、自定义解析器及可选的严格源绑定匹配来协调绑定复制与粘贴。</para>
	/// </summary>
	public static class ModSettingsClipboardOperations
	{
		private static readonly List<Func<ModSettingsPasteValidationContext, ModSettingsPasteVerdict>> PasteRules = new List<Func<ModSettingsPasteValidationContext, ModSettingsPasteVerdict>>();

		private static readonly Lock PasteRulesLock = new Lock();

		private static readonly Dictionary<Type, List<Delegate>> PasteAppliers = new Dictionary<Type, List<Delegate>>();

		private static readonly Lock PasteAppliersLock = new Lock();

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or sets whether default envelope deserialization requires the source
		///         <c>TargetSignature</c> to match the target binding. Disabled by default.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或设置默认信封反序列化是否要求源 <c>TargetSignature</c> 与目标绑定匹配；默认禁用。
		///     </para>
		/// </summary>
		public static bool RequireMatchingSourceBindingForPaste { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Occurs before a binding's default clipboard envelope is written. Handlers run in subscription order,
		///         and one handler's exception is logged without preventing later handlers.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在写入绑定的默认剪贴板信封之前发生；处理器按订阅顺序执行，单个处理器抛出的异常会被记录且不会阻止后续处理器。
		///     </para>
		/// </summary>
		public static event Action<ModSettingsCopyActionEventArgs>? BindingValueCopyRequested;

		/// <summary>
		///     <para xml:lang="en">
		///         Appends a paste validation rule. Rules run in registration order; a deny result or exception rejects
		///         the paste before parsing.
		///     </para>
		///     <para xml:lang="zh-CN">追加粘贴校验规则；规则按注册顺序执行，拒绝结果或异常都会在解析前终止粘贴。</para>
		/// </summary>
		public static void RegisterPasteRule(Func<ModSettingsPasteValidationContext, ModSettingsPasteVerdict> rule)
		{
			ArgumentNullException.ThrowIfNull(rule, "rule");
			using (PasteRulesLock.EnterScope())
			{
				PasteRules.Add(rule);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends a custom parser for <typeparamref name="TValue" />. Parsers run in registration order before
		///         built-in envelope handling; a parser exception is logged and the next parser is tried.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <typeparamref name="TValue" /> 追加自定义解析器；解析器在内置信封处理前按注册顺序执行，
		///         单个解析器抛出异常时会记录异常并继续尝试下一个解析器。
		///     </para>
		/// </summary>
		public static void RegisterPasteApplier<TValue>(ModSettingsTryPasteApplier<TValue> applier)
		{
			ArgumentNullException.ThrowIfNull(applier, "applier");
			using (PasteAppliersLock.EnterScope())
			{
				if (!PasteAppliers.TryGetValue(typeof(TValue), out List<Delegate> value))
				{
					value = new List<Delegate>();
					PasteAppliers.Add(typeof(TValue), value);
				}
				value.Add(applier);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Runs binding copy handlers and then writes the default clipboard envelope unless a successful handler
		///         suppresses it.
		///     </para>
		///     <para xml:lang="zh-CN">执行绑定复制处理器，随后写入默认剪贴板信封，除非成功完成的处理器将其抑制。</para>
		/// </summary>
		public static void InvokeCopy<TValue>(IModSettingsValueBinding<TValue> binding, ModSettingsClipboardScope scope, IStructuredModSettingsValueAdapter<TValue> adapter, TValue value)
		{
			ArgumentNullException.ThrowIfNull(binding, "binding");
			ArgumentNullException.ThrowIfNull(adapter, "adapter");
			ModSettingsCopyActionEventArgs e = new ModSettingsCopyActionEventArgs(binding, typeof(TValue), value, scope);
			Action<ModSettingsCopyActionEventArgs> bindingValueCopyRequested = BindingValueCopyRequested;
			if (bindingValueCopyRequested != null)
			{
				Delegate[] invocationList = bindingValueCopyRequested.GetInvocationList();
				foreach (Delegate obj in invocationList)
				{
					bool suppressDefaultClipboardWrite = e.SuppressDefaultClipboardWrite;
					try
					{
						((Action<ModSettingsCopyActionEventArgs>)obj)(e);
					}
					catch (Exception value2)
					{
						e.SuppressDefaultClipboardWrite = suppressDefaultClipboardWrite;
						Type type = binding.GetType();
						RitsuLibFramework.Logger.Warn($"[Settings] A binding copy handler failed for '{type.FullName ?? type.Name}': {value2}", 1);
					}
				}
			}
			if (!e.SuppressDefaultClipboardWrite)
			{
				ModSettingsClipboardData.CopyValue(binding, scope, adapter, value);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Determines whether the current clipboard is accepted for <paramref name="binding" /> by all paste
		///         rules and by either a custom parser or the default adapter path.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         确定当前剪贴板是否通过所有粘贴规则，并被自定义解析器或默认适配器路径接受用于
		///         <paramref name="binding" />。
		///     </para>
		/// </summary>
		public static bool CanPasteBindingValue<TValue>(IModSettingsValueBinding<TValue> binding, IStructuredModSettingsValueAdapter<TValue> adapter)
		{
			ArgumentNullException.ThrowIfNull(binding, "binding");
			ArgumentNullException.ThrowIfNull(adapter, "adapter");
			if (!ModSettingsClipboardAccess.TryGetText(out string text))
			{
				return false;
			}
			ModSettingsClipboardEnvelopeView view = TryCreateEnvelopeView(text);
			if (!RunPasteRules(binding, typeof(TValue), text, view))
			{
				return false;
			}
			if (!TryInvokePasteApplier(binding, adapter, text, out var value))
			{
				return ModSettingsClipboardData.TryReadValue(binding, adapter, out value, RequireMatchingSourceBindingForPaste);
			}
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to parse a value for <paramref name="binding" /> from the current clipboard. This method
		///         does not write the returned value to the binding.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试从当前剪贴板解析适用于 <paramref name="binding" /> 的值；此方法不会将返回值写入绑定。
		///     </para>
		/// </summary>
		public static bool TryPasteBindingValue<TValue>(IModSettingsValueBinding<TValue> binding, IStructuredModSettingsValueAdapter<TValue> adapter, out TValue value)
		{
			ModSettingsPasteFailureReason failureReason;
			return TryPasteBindingValue(binding, adapter, out value, out failureReason);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to parse a value for <paramref name="binding" /> from the current clipboard and classifies a
		///         false result in <paramref name="failureReason" />. This method does not write to the binding.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试从当前剪贴板解析适用于 <paramref name="binding" /> 的值，并通过
		///         <paramref name="failureReason" /> 对失败结果进行分类；此方法不会写入绑定。
		///     </para>
		/// </summary>
		public static bool TryPasteBindingValue<TValue>(IModSettingsValueBinding<TValue> binding, IStructuredModSettingsValueAdapter<TValue> adapter, out TValue value, out ModSettingsPasteFailureReason failureReason)
		{
			ArgumentNullException.ThrowIfNull(binding, "binding");
			ArgumentNullException.ThrowIfNull(adapter, "adapter");
			failureReason = ModSettingsPasteFailureReason.None;
			value = default(TValue);
			if (!ModSettingsClipboardAccess.TryGetText(out string text))
			{
				failureReason = ModSettingsPasteFailureReason.ClipboardEmpty;
				return false;
			}
			ModSettingsClipboardEnvelopeView view = TryCreateEnvelopeView(text);
			if (!RunPasteRules(binding, typeof(TValue), text, view))
			{
				failureReason = ModSettingsPasteFailureReason.PasteRuleDenied;
				return false;
			}
			if (TryInvokePasteApplier(binding, adapter, text, out value))
			{
				return true;
			}
			if (ModSettingsClipboardData.TryReadValue(binding, adapter, out value, RequireMatchingSourceBindingForPaste))
			{
				return true;
			}
			failureReason = ModSettingsPasteFailureReason.TypeOrShapeMismatch;
			return false;
		}

		private static bool TryInvokePasteApplier<TValue>(IModSettingsValueBinding<TValue> binding, IStructuredModSettingsValueAdapter<TValue> adapter, string clipboardText, out TValue value)
		{
			Delegate[] array;
			using (PasteAppliersLock.EnterScope())
			{
				if (!PasteAppliers.TryGetValue(typeof(TValue), out List<Delegate> value2) || value2.Count == 0)
				{
					value = default(TValue);
					return false;
				}
				array = value2.ToArray();
			}
			Delegate[] array2 = array;
			foreach (Delegate obj in array2)
			{
				try
				{
					if (((ModSettingsTryPasteApplier<TValue>)obj)(binding, adapter, clipboardText, out value))
					{
						return true;
					}
				}
				catch (Exception value3)
				{
					Type type = binding.GetType();
					RitsuLibFramework.Logger.Warn($"[Settings] A custom paste parser failed for '{type.FullName ?? type.Name}': {value3}", 1);
				}
			}
			value = default(TValue);
			return false;
		}

		internal static ModSettingsClipboardEnvelopeView? TryCreateEnvelopeView(string clipboardText)
		{
			if (!ModSettingsClipboardData.TryDeserializeEnvelope(clipboardText, out ModSettingsClipboardEnvelope envelope) || envelope == null)
			{
				return null;
			}
			return new ModSettingsClipboardEnvelopeView(envelope.Kind, envelope.TypeName, envelope.TargetSignature, envelope.SchemaSignature, envelope.Scope, envelope.Payload);
		}

		private static bool RunPasteRules(IModSettingsBinding binding, Type targetValueType, string clipboardText, ModSettingsClipboardEnvelopeView? view)
		{
			ModSettingsPasteValidationContext arg = new ModSettingsPasteValidationContext
			{
				TargetBinding = binding,
				TargetValueType = targetValueType,
				ClipboardText = clipboardText,
				Envelope = view
			};
			List<Func<ModSettingsPasteValidationContext, ModSettingsPasteVerdict>> list;
			using (PasteRulesLock.EnterScope())
			{
				list = PasteRules.ToList();
			}
			foreach (Func<ModSettingsPasteValidationContext, ModSettingsPasteVerdict> item in list)
			{
				try
				{
					if (item(arg) == ModSettingsPasteVerdict.Deny)
					{
						return false;
					}
				}
				catch (Exception value)
				{
					Type type = binding.GetType();
					RitsuLibFramework.Logger.Warn($"[Settings] A paste validation rule failed for '{type.FullName ?? type.Name}': {value}", 1);
					return false;
				}
			}
			return true;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Identifies a mod setting by its owning mod, data key, and <see cref="T:STS2RitsuLib.Utils.Persistence.SaveScope" /> and exposes its save
	///         operation.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过所属模组、数据键与 <see cref="T:STS2RitsuLib.Utils.Persistence.SaveScope" /> 标识模组设置，并公开其保存操作。
	///     </para>
	/// </summary>
	public interface IModSettingsBinding
	{
		/// <summary>
		///     <para xml:lang="en">Gets the owning mod ID used for binding identity and UI grouping.</para>
		///     <para xml:lang="zh-CN">获取用于绑定标识与界面分组的所属模组 ID。</para>
		/// </summary>
		string ModId { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the stable key that identifies the setting within the mod and, when applicable, its persistence
		///         store.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取在模组内标识该设置的稳定键；适用时，该键也用于其持久化存储。
		///     </para>
		/// </summary>
		string DataKey { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the declared global, profile, or in-memory save scope.</para>
		///     <para xml:lang="zh-CN">获取声明的全局、档案或内存保存作用域。</para>
		/// </summary>
		SaveScope Scope { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Requests that the binding save its current state. An implementation may persist through RitsuLib,
		///         delegate to another store, or perform no operation for transient state.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         请求绑定保存其当前状态。具体实现可通过 RitsuLib 持久化、转交其他存储，或对瞬时状态不执行操作。
		///     </para>
		/// </summary>
		void Save();
	}
	/// <summary>
	///     <para xml:lang="en">Reads and writes one setting value of type <typeparamref name="TValue" />.</para>
	///     <para xml:lang="zh-CN">读写一个 <typeparamref name="TValue" /> 类型的设置值。</para>
	/// </summary>
	/// <typeparam name="TValue">
	///     <para xml:lang="en">The setting value type.</para>
	///     <para xml:lang="zh-CN">设置值类型。</para>
	/// </typeparam>
	public interface IModSettingsValueBinding<TValue> : IModSettingsBinding
	{
		/// <summary>
		///     <para xml:lang="en">Reads the binding's current value from its backing source.</para>
		///     <para xml:lang="zh-CN">从绑定的底层来源读取当前值。</para>
		/// </summary>
		TValue Read();

		/// <summary>
		///     <para xml:lang="en">
		///         Writes the binding's current value. Persistence may be deferred or immediate depending on the
		///         implementation; callers can request it explicitly through <see cref="M:STS2RitsuLib.Settings.IModSettingsBinding.Save" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         写入绑定的当前值。持久化可由实现延后或立即执行；调用方也可通过
		///         <see cref="M:STS2RitsuLib.Settings.IModSettingsBinding.Save" /> 显式请求保存。
		///     </para>
		/// </summary>
		/// <param name="value">
		///     <para xml:lang="en">The value to write.</para>
		///     <para xml:lang="zh-CN">要写入的值。</para>
		/// </param>
		void Write(TValue value);
	}
	/// <summary>
	///     <para xml:lang="en">Creates values for explicit reset-to-default operations.</para>
	///     <para xml:lang="zh-CN">为显式恢复默认值操作创建值。</para>
	/// </summary>
	/// <typeparam name="TValue">
	///     <para xml:lang="en">The setting value type.</para>
	///     <para xml:lang="zh-CN">设置值类型。</para>
	/// </typeparam>
	public interface IDefaultModSettingsValueBinding<TValue> : IModSettingsValueBinding<TValue>, IModSettingsBinding
	{
		/// <summary>
		///     <para xml:lang="en">Creates a value for one explicit reset operation.</para>
		///     <para xml:lang="zh-CN">为一次显式恢复默认值操作创建值。</para>
		/// </summary>
		TValue CreateDefaultValue();
	}
	/// <summary>
	///     <para xml:lang="en">Marks a binding as transient and not written to persistent storage.</para>
	///     <para xml:lang="zh-CN">将绑定标记为瞬时绑定，不写入持久化存储。</para>
	/// </summary>
	public interface ITransientModSettingsBinding : IModSettingsBinding
	{
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Clones structured setting values and converts them to and from text for editing and clipboard operations.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         克隆结构化设置值，并在值与编辑、剪贴板操作所用文本之间进行转换。
	///     </para>
	/// </summary>
	/// <typeparam name="TValue">
	///     <para xml:lang="en">The structured setting value type.</para>
	///     <para xml:lang="zh-CN">结构化设置值类型。</para>
	/// </typeparam>
	public interface IStructuredModSettingsValueAdapter<TValue>
	{
		/// <summary>
		///     <para xml:lang="en">Creates an independent or defensive copy for an editing session.</para>
		///     <para xml:lang="zh-CN">为编辑会话创建独立副本或防御性副本。</para>
		/// </summary>
		/// <param name="value">
		///     <para xml:lang="en">The value to clone.</para>
		///     <para xml:lang="zh-CN">要克隆的值。</para>
		/// </param>
		TValue Clone(TValue value);

		/// <summary>
		///     <para xml:lang="en">Serializes a value to one text payload, such as JSON.</para>
		///     <para xml:lang="zh-CN">将值序列化为一段文本载荷，例如 JSON。</para>
		/// </summary>
		/// <param name="value">
		///     <para xml:lang="en">The value to serialize.</para>
		///     <para xml:lang="zh-CN">要序列化的值。</para>
		/// </param>
		string Serialize(TValue value);

		/// <summary>
		///     <para xml:lang="en">Attempts to parse a text payload into a structured value.</para>
		///     <para xml:lang="zh-CN">尝试将文本载荷解析为结构化值。</para>
		/// </summary>
		/// <param name="text">
		///     <para xml:lang="en">The text payload to parse.</para>
		///     <para xml:lang="zh-CN">要解析的文本载荷。</para>
		/// </param>
		/// <param name="value">
		///     <para xml:lang="en">The parsed value when successful.</para>
		///     <para xml:lang="zh-CN">成功时解析出的值。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when parsing succeeds; otherwise, <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         解析成功时为 <see langword="true" />；否则为 <see langword="false" />。
		///     </para>
		/// </returns>
		bool TryDeserialize(string text, out TValue value);
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Exposes an <see cref="T:STS2RitsuLib.Settings.IStructuredModSettingsValueAdapter`1" /> for a value binding's clone,
	///         serialization, and clipboard operations.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为值绑定的克隆、序列化与剪贴板操作公开
	///         <see cref="T:STS2RitsuLib.Settings.IStructuredModSettingsValueAdapter`1" />。
	///     </para>
	/// </summary>
	/// <typeparam name="TValue">
	///     <para xml:lang="en">The structured setting value type.</para>
	///     <para xml:lang="zh-CN">结构化设置值类型。</para>
	/// </typeparam>
	public interface IStructuredModSettingsValueBinding<TValue> : IModSettingsValueBinding<TValue>, IModSettingsBinding
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets the adapter used for clone, serialization, and deserialization operations.
		///     </para>
		///     <para xml:lang="zh-CN">获取用于克隆、序列化与反序列化操作的适配器。</para>
		/// </summary>
		IStructuredModSettingsValueAdapter<TValue> Adapter { get; }
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Forwards every entry behavior to an inner definition so a section builder can decorate one concern
	///         without discarding the others.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将条目的全部行为转发到内部定义，使节构建器能够装饰单项功能而不丢失其他功能。
	///     </para>
	/// </summary>
	/// <param name="inner">
	///     <para xml:lang="en">The entry definition whose behavior is forwarded.</para>
	///     <para xml:lang="zh-CN">其行为将被转发的条目定义。</para>
	/// </param>
	internal abstract class ModSettingsEntryDecorator(ModSettingsEntryDefinition inner) : ModSettingsEntryDefinition(inner.Id, inner.Label, inner.Description)
	{
		internal ModSettingsEntryDefinition Inner { get; } = inner;

		public override Func<bool>? VisibilityPredicate => Inner.VisibilityPredicate;

		public override Func<bool>? EnabledPredicate => Inner.EnabledPredicate;

		internal override string? VisibilityTargetPageId => Inner.VisibilityTargetPageId;

		internal override bool CanResetToDefault => Inner.CanResetToDefault;

		internal override Control CreateControl(ModSettingsUiContext context)
		{
			return Inner.CreateControl(context);
		}

		internal override void CollectChromeBindingSnapshots(Dictionary<string, ModSettingsChromeBindingSnapshot> target)
		{
			Inner.CollectChromeBindingSnapshots(target);
		}

		internal override bool TryPasteChromeBindingSnapshot(ModSettingsChromeBindingSnapshot snap, IModSettingsUiActionHost host)
		{
			return Inner.TryPasteChromeBindingSnapshot(snap, host);
		}

		internal override bool TryResetToDefault(IModSettingsUiActionHost host)
		{
			return Inner.TryResetToDefault(host);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines the identity, display text, availability, menu capabilities, and UI construction contract for
	///         one settings row.
	///     </para>
	///     <para xml:lang="zh-CN">定义单个设置行的标识、显示文本、可用状态、菜单能力及界面构建契约。</para>
	/// </summary>
	public abstract class ModSettingsEntryDefinition
	{
		/// <summary>
		///     <para xml:lang="en">Gets the actions exposed by this entry's context menu.</para>
		///     <para xml:lang="zh-CN">获取此条目上下文菜单公开的操作。</para>
		/// </summary>
		public ModSettingsMenuCapabilities MenuCapabilities { get; internal set; } = ModSettingsMenuCapabilities.All;

		/// <summary>
		///     <para xml:lang="en">Gets the host surfaces on which this entry's interactive controls are read-only.</para>
		///     <para xml:lang="zh-CN">获取此条目的交互控件处于只读状态的宿主界面。</para>
		/// </summary>
		public ModSettingsHostSurface ReadOnlyOnHostSurfaces { get; internal set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the entry ID, which is unique within its section and is used by clipboard snapshots and UI
		///         anchors.
		///     </para>
		///     <para xml:lang="zh-CN">获取条目 ID；该 ID 在所属节内唯一，并用于剪贴板快照及界面锚点。</para>
		/// </summary>
		public string Id { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the primary label or body text, depending on the entry type.</para>
		///     <para xml:lang="zh-CN">获取主要标签或正文文本，具体含义取决于条目类型。</para>
		/// </summary>
		public ModSettingsText Label { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional secondary description displayed by the UI.</para>
		///     <para xml:lang="zh-CN">获取界面显示的可选次级说明。</para>
		/// </summary>
		public ModSettingsText? Description { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the optional visibility predicate. It is re-evaluated on UI refresh, and a false result hides
		///         the row.
		///     </para>
		///     <para xml:lang="zh-CN">获取可选的可见性谓词；界面刷新时会重新求值，结果为 false 时隐藏该行。</para>
		/// </summary>
		public virtual Func<bool>? VisibilityPredicate => null;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the optional enabled-state predicate. It is re-evaluated on UI refresh, and a false result
		///         dims the row and disables interaction.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取可选的启用状态谓词；界面刷新时会重新求值，结果为 false 时该行会变暗且不可交互。
		///     </para>
		/// </summary>
		public virtual Func<bool>? EnabledPredicate => null;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets an optional destination page whose visibility also controls this entry. Entry decorators must
		///         preserve this value.
		///     </para>
		///     <para xml:lang="zh-CN">获取可选的目标页面；该页面的可见性也会控制此条目，且条目装饰器必须保留该值。</para>
		/// </summary>
		internal virtual string? VisibilityTargetPageId => null;

		internal virtual bool CanResetToDefault => false;

		/// <summary>
		///     <para xml:lang="en">
		///         Initializes an entry definition with a stable ID, primary label, and optional description.
		///     </para>
		///     <para xml:lang="zh-CN">使用稳定 ID、主要标签及可选说明初始化条目定义。</para>
		/// </summary>
		protected ModSettingsEntryDefinition(string id, ModSettingsText label, ModSettingsText? description)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentNullException.ThrowIfNull(label, "label");
			Id = id;
			Label = label;
			Description = description;
		}

		internal abstract Control CreateControl(ModSettingsUiContext context);

		internal virtual void CollectChromeBindingSnapshots(Dictionary<string, ModSettingsChromeBindingSnapshot> target)
		{
		}

		internal virtual bool TryPasteChromeBindingSnapshot(ModSettingsChromeBindingSnapshot snap, IModSettingsUiActionHost host)
		{
			return false;
		}

		internal virtual bool TryResetToDefault(IModSettingsUiActionHost host)
		{
			return false;
		}

		private protected static bool BindingCanResetToDefault<TValue>(IModSettingsValueBinding<TValue> binding)
		{
			return binding is IDefaultModSettingsValueBinding<TValue>;
		}

		private protected static bool TryResetBindingToDefault<TValue>(IModSettingsValueBinding<TValue> binding, IModSettingsUiActionHost host)
		{
			if (!(binding is IDefaultModSettingsValueBinding<TValue> defaultModSettingsValueBinding))
			{
				return false;
			}
			binding.Write(defaultModSettingsValueBinding.CreateDefaultValue());
			host.MarkDirty(binding);
			return true;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Defines an on/off toggle backed by <see cref="P:STS2RitsuLib.Settings.ToggleModSettingsEntryDefinition.Binding" />.</para>
	///     <para xml:lang="zh-CN">定义由 <see cref="P:STS2RitsuLib.Settings.ToggleModSettingsEntryDefinition.Binding" /> 支持的开关控件。</para>
	/// </summary>
	public sealed class ToggleModSettingsEntryDefinition(string id, ModSettingsText label, IModSettingsValueBinding<bool> binding, ModSettingsText? description, Func<bool>? visibilityPredicate = null) : ModSettingsEntryDefinition(id, label, description)
	{
		/// <summary>
		///     <para xml:lang="en">Gets the binding that stores the toggle state.</para>
		///     <para xml:lang="zh-CN">获取存储开关状态的绑定。</para>
		/// </summary>
		public IModSettingsValueBinding<bool> Binding { get; } = binding ?? throw new ArgumentNullException("binding");

		/// <inheritdoc />
		public override Func<bool>? VisibilityPredicate => visibilityPredicate;

		internal override bool CanResetToDefault => ModSettingsEntryDefinition.BindingCanResetToDefault(Binding);

		internal override void CollectChromeBindingSnapshots(Dictionary<string, ModSettingsChromeBindingSnapshot> target)
		{
			ModSettingsClipboardData.AddChromeBindingSnapshot(target, base.Id, Binding);
		}

		internal override bool TryPasteChromeBindingSnapshot(ModSettingsChromeBindingSnapshot snap, IModSettingsUiActionHost host)
		{
			IStructuredModSettingsValueAdapter<bool> adapter = ModSettingsUiFactory.ResolveClipboardAdapter(Binding);
			if (!ModSettingsClipboardData.TryApplySerializedValueToBinding(Binding, adapter, snap, out var value))
			{
				return false;
			}
			Binding.Write(value);
			host.MarkDirty(Binding);
			return true;
		}

		internal override Control CreateControl(ModSettingsUiContext context)
		{
			return ModSettingsUiFactory.CreateToggleEntry(context, this);
		}

		internal override bool TryResetToDefault(IModSettingsUiActionHost host)
		{
			return ModSettingsEntryDefinition.TryResetBindingToDefault(Binding, host);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines a <see cref="T:System.Double" /> slider over an inclusive range with a positive step and an optional
	///         display formatter.
	///     </para>
	///     <para xml:lang="zh-CN">定义在闭区间内按正步长调整数值的 <see cref="T:System.Double" /> 滑块，并可指定显示格式化器。</para>
	/// </summary>
	public sealed class SliderModSettingsEntryDefinition : ModSettingsEntryDefinition
	{
		/// <summary>
		///     <para xml:lang="en">Gets the binding that stores the slider value.</para>
		///     <para xml:lang="zh-CN">获取存储滑块数值的绑定。</para>
		/// </summary>
		public IModSettingsValueBinding<double> Binding { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the finite inclusive minimum value.</para>
		///     <para xml:lang="zh-CN">获取有限的闭区间最小值。</para>
		/// </summary>
		public double MinValue { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the finite inclusive maximum value.</para>
		///     <para xml:lang="zh-CN">获取有限的闭区间最大值。</para>
		/// </summary>
		public double MaxValue { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the finite positive step between selectable values.</para>
		///     <para xml:lang="zh-CN">获取可选数值之间有限的正步长。</para>
		/// </summary>
		public double Step { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional formatter for the displayed value.</para>
		///     <para xml:lang="zh-CN">获取显示数值使用的可选格式化器。</para>
		/// </summary>
		public Func<double, string>? ValueFormatter { get; }

		internal override bool CanResetToDefault => ModSettingsEntryDefinition.BindingCanResetToDefault(Binding);

		/// <summary>
		///     <para xml:lang="en">
		///         Defines a <see cref="T:System.Double" /> slider over an inclusive range with a positive step and an optional
		///         display formatter.
		///     </para>
		///     <para xml:lang="zh-CN">定义在闭区间内按正步长调整数值的 <see cref="T:System.Double" /> 滑块，并可指定显示格式化器。</para>
		/// </summary>
		public SliderModSettingsEntryDefinition(string id, ModSettingsText label, IModSettingsValueBinding<double> binding, double minValue, double maxValue, double step, Func<double, string>? valueFormatter, ModSettingsText? description)
		{
			Binding = binding ?? throw new ArgumentNullException("binding");
			if (!double.IsFinite(minValue))
			{
				throw new ArgumentOutOfRangeException("minValue", "Slider minValue must be finite.");
			}
			MinValue = minValue;
			if (double.IsFinite(maxValue))
			{
				if (!(maxValue >= minValue))
				{
					throw new ArgumentOutOfRangeException("maxValue", "Slider maxValue must be >= minValue.");
				}
				MaxValue = maxValue;
				if (!double.IsFinite(step) || !(step > 0.0))
				{
					throw new ArgumentOutOfRangeException("step", "Slider step must be finite and > 0.");
				}
				Step = step;
				ValueFormatter = valueFormatter;
				base..ctor(id, label, description);
				return;
			}
			throw new ArgumentOutOfRangeException("maxValue", "Slider maxValue must be finite.");
		}

		internal override void CollectChromeBindingSnapshots(Dictionary<string, ModSettingsChromeBindingSnapshot> target)
		{
			ModSettingsClipboardData.AddChromeBindingSnapshot(target, base.Id, Binding);
		}

		internal override bool TryPasteChromeBindingSnapshot(ModSettingsChromeBindingSnapshot snap, IModSettingsUiActionHost host)
		{
			IStructuredModSettingsValueAdapter<double> adapter = ModSettingsUiFactory.ResolveClipboardAdapter(Binding);
			if (!ModSettingsClipboardData.TryApplySerializedValueToBinding(Binding, adapter, snap, out var value))
			{
				return false;
			}
			Binding.Write(value);
			host.MarkDirty(Binding);
			return true;
		}

		internal override Control CreateControl(ModSettingsUiContext context)
		{
			return ModSettingsUiFactory.CreateSliderEntry(context, this);
		}

		internal override bool TryResetToDefault(IModSettingsUiActionHost host)
		{
			return ModSettingsEntryDefinition.TryResetBindingToDefault(Binding, host);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines the legacy <see cref="T:System.Single" /> slider used by the obsolete
	///         <c>ModSettingsSectionBuilder.AddSlider</c> overload. Its separate value path avoids float-to-double
	///         conversion drift and refresh feedback loops.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义已过时 <c>ModSettingsSectionBuilder.AddSlider</c> 重载使用的旧版 <see cref="T:System.Single" />
	///         滑块。独立的数值路径可避免 float 与 double 转换造成的偏差及刷新反馈循环。
	///     </para>
	/// </summary>
	public sealed class FloatSliderModSettingsEntryDefinition : ModSettingsEntryDefinition
	{
		/// <summary>
		///     <para xml:lang="en">Gets the binding that stores the slider value.</para>
		///     <para xml:lang="zh-CN">获取存储滑块数值的绑定。</para>
		/// </summary>
		public IModSettingsValueBinding<float> Binding { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the finite inclusive minimum value.</para>
		///     <para xml:lang="zh-CN">获取有限的闭区间最小值。</para>
		/// </summary>
		public float MinValue { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the finite inclusive maximum value.</para>
		///     <para xml:lang="zh-CN">获取有限的闭区间最大值。</para>
		/// </summary>
		public float MaxValue { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the finite positive step between selectable values.</para>
		///     <para xml:lang="zh-CN">获取可选数值之间有限的正步长。</para>
		/// </summary>
		public float Step { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional formatter for the displayed value.</para>
		///     <para xml:lang="zh-CN">获取显示数值使用的可选格式化器。</para>
		/// </summary>
		public Func<float, string>? ValueFormatter { get; }

		internal override bool CanResetToDefault => ModSettingsEntryDefinition.BindingCanResetToDefault(Binding);

		/// <summary>
		///     <para xml:lang="en">
		///         Defines the legacy <see cref="T:System.Single" /> slider used by the obsolete
		///         <c>ModSettingsSectionBuilder.AddSlider</c> overload. Its separate value path avoids float-to-double
		///         conversion drift and refresh feedback loops.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         定义已过时 <c>ModSettingsSectionBuilder.AddSlider</c> 重载使用的旧版 <see cref="T:System.Single" />
		///         滑块。独立的数值路径可避免 float 与 double 转换造成的偏差及刷新反馈循环。
		///     </para>
		/// </summary>
		public FloatSliderModSettingsEntryDefinition(string id, ModSettingsText label, IModSettingsValueBinding<float> binding, float minValue, float maxValue, float step, Func<float, string>? valueFormatter, ModSettingsText? description)
		{
			Binding = binding ?? throw new ArgumentNullException("binding");
			if (!float.IsFinite(minValue))
			{
				throw new ArgumentOutOfRangeException("minValue", "Slider minValue must be finite.");
			}
			MinValue = minValue;
			if (float.IsFinite(maxValue))
			{
				if (!(maxValue >= minValue))
				{
					throw new ArgumentOutOfRangeException("maxValue", "Slider maxValue must be >= minValue.");
				}
				MaxValue = maxValue;
				if (!float.IsFinite(step) || !(step > 0f))
				{
					throw new ArgumentOutOfRangeException("step", "Slider step must be finite and > 0.");
				}
				Step = step;
				ValueFormatter = valueFormatter;
				base..ctor(id, label, description);
				return;
			}
			throw new ArgumentOutOfRangeException("maxValue", "Slider maxValue must be finite.");
		}

		internal override void CollectChromeBindingSnapshots(Dictionary<string, ModSettingsChromeBindingSnapshot> target)
		{
			ModSettingsClipboardData.AddChromeBindingSnapshot(target, base.Id, Binding);
		}

		internal override bool TryPasteChromeBindingSnapshot(ModSettingsChromeBindingSnapshot snap, IModSettingsUiActionHost host)
		{
			IStructuredModSettingsValueAdapter<float> adapter = ModSettingsUiFactory.ResolveClipboardAdapter(Binding);
			if (!ModSettingsClipboardData.TryApplySerializedValueToBinding(Binding, adapter, snap, out var value))
			{
				return false;
			}
			Binding.Write(value);
			host.MarkDirty(Binding);
			return true;
		}

		internal override Control CreateControl(ModSettingsUiContext context)
		{
			return ModSettingsUiFactory.CreateFloatSliderEntry(context, this);
		}

		internal override bool TryResetToDefault(IModSettingsUiActionHost host)
		{
			return ModSettingsEntryDefinition.TryResetBindingToDefault(Binding, host);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines a discrete choice control over <typeparamref name="TValue" /> using either fixed
	///         <see cref="P:STS2RitsuLib.Settings.ChoiceModSettingsEntryDefinition`1.Options" /> or a dynamic <see cref="P:STS2RitsuLib.Settings.ChoiceModSettingsEntryDefinition`1.OptionsProvider" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义 <typeparamref name="TValue" /> 的离散选项控件，可使用固定 <see cref="P:STS2RitsuLib.Settings.ChoiceModSettingsEntryDefinition`1.Options" /> 或动态
	///         <see cref="P:STS2RitsuLib.Settings.ChoiceModSettingsEntryDefinition`1.OptionsProvider" />。
	///     </para>
	/// </summary>
	public sealed class ChoiceModSettingsEntryDefinition<TValue>(string id, ModSettingsText label, IModSettingsValueBinding<TValue> binding, IReadOnlyList<ModSettingsChoiceOption<TValue>> options, ModSettingsChoicePresentation presentation, ModSettingsText? description) : ModSettingsEntryDefinition(id, label, description)
	{
		/// <summary>
		///     <para xml:lang="en">Gets the binding that stores the selected option value.</para>
		///     <para xml:lang="zh-CN">获取存储所选选项值的绑定。</para>
		/// </summary>
		public IModSettingsValueBinding<TValue> Binding { get; } = binding ?? throw new ArgumentNullException("binding");

		/// <summary>
		///     <para xml:lang="en">
		///         Gets an immutable snapshot of the initial ordered options. When <see cref="P:STS2RitsuLib.Settings.ChoiceModSettingsEntryDefinition`1.OptionsProvider" /> is
		///         absent, this is the complete fixed option set.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取初始有序选项的不可变快照；未提供 <see cref="P:STS2RitsuLib.Settings.ChoiceModSettingsEntryDefinition`1.OptionsProvider" /> 时，此快照即为完整的固定选项集。
		///     </para>
		/// </summary>
		public IReadOnlyList<ModSettingsChoiceOption<TValue>> Options { get; } = ValidateAndSnapshotOptions(options, "options");

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the optional provider used to re-evaluate available options on settings UI refresh and before
		///         a drop-down list opens.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取可选的选项提供器；设置界面刷新以及下拉列表展开前会通过该提供器重新计算可用选项。
		///     </para>
		/// </summary>
		public Func<IReadOnlyList<ModSettingsChoiceOption<TValue>>>? OptionsProvider { get; internal set; }

		/// <summary>
		///     <para xml:lang="en">Gets the visual presentation used for the choices.</para>
		///     <para xml:lang="zh-CN">获取选项使用的视觉呈现方式。</para>
		/// </summary>
		public ModSettingsChoicePresentation Presentation { get; } = presentation;

		internal override bool CanResetToDefault => ModSettingsEntryDefinition.BindingCanResetToDefault(Binding);

		internal IReadOnlyList<ModSettingsChoiceOption<TValue>> ResolveOptions()
		{
			if (OptionsProvider == null)
			{
				return Options;
			}
			return ValidateAndSnapshotOptions(OptionsProvider() ?? throw new InvalidOperationException("Dynamic choice setting '" + base.Id + "' returned a null option list."), "OptionsProvider");
		}

		internal override void CollectChromeBindingSnapshots(Dictionary<string, ModSettingsChromeBindingSnapshot> target)
		{
			ModSettingsClipboardData.AddChromeBindingSnapshot(target, base.Id, Binding);
		}

		internal override bool TryPasteChromeBindingSnapshot(ModSettingsChromeBindingSnapshot snap, IModSettingsUiActionHost host)
		{
			IStructuredModSettingsValueAdapter<TValue> adapter = ModSettingsUiFactory.ResolveClipboardAdapter(Binding);
			if (!ModSettingsClipboardData.TryApplySerializedValueToBinding(Binding, adapter, snap, out var value))
			{
				return false;
			}
			Binding.Write(value);
			host.MarkDirty(Binding);
			return true;
		}

		internal override Control CreateControl(ModSettingsUiContext context)
		{
			return ModSettingsUiFactory.CreateChoiceEntry(context, this);
		}

		internal override bool TryResetToDefault(IModSettingsUiActionHost host)
		{
			return ModSettingsEntryDefinition.TryResetBindingToDefault(Binding, host);
		}

		private static IReadOnlyList<ModSettingsChoiceOption<TValue>> ValidateAndSnapshotOptions(IReadOnlyList<ModSettingsChoiceOption<TValue>>? options, string parameterName)
		{
			ArgumentNullException.ThrowIfNull(options, parameterName);
			ModSettingsChoiceOption<TValue>[] array = options.ToArray();
			if (array.Any((ModSettingsChoiceOption<TValue> option) => option.Label == null))
			{
				throw new ArgumentException("Choice option labels cannot be null.", parameterName);
			}
			return Array.AsReadOnly(array);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines a color picker backed by a serialized string, such as a hexadecimal color or engine
	///         serialization.
	///     </para>
	///     <para xml:lang="zh-CN">定义由序列化字符串支持的颜色选择器，例如十六进制颜色或引擎序列化文本。</para>
	/// </summary>
	public sealed class ColorModSettingsEntryDefinition : ModSettingsEntryDefinition
	{
		/// <summary>
		///     <para xml:lang="en">Gets the binding that stores the serialized color string.</para>
		///     <para xml:lang="zh-CN">获取存储序列化颜色字符串的绑定。</para>
		/// </summary>
		public IModSettingsValueBinding<string> Binding { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether the picker exposes alpha-channel editing, corresponding to BaseLib
		///         <c>ConfigColorPickerAttribute.EditAlpha</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取颜色选择器是否提供透明度通道编辑，对应 BaseLib 的
		///         <c>ConfigColorPickerAttribute.EditAlpha</c>。
		///     </para>
		/// </summary>
		public bool EditAlpha { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether the Godot picker enables HDR intensity editing. BaseLib applies this option only to
		///         <see cref="T:Godot.Color" /> properties.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 Godot 颜色选择器是否启用 HDR 强度编辑；BaseLib 仅对 <see cref="T:Godot.Color" /> 属性应用此选项。
		///     </para>
		/// </summary>
		public bool EditIntensity { get; }

		internal override bool CanResetToDefault => ModSettingsEntryDefinition.BindingCanResetToDefault(Binding);

		/// <summary>
		///     <para xml:lang="en">Initializes a color entry with explicit alpha and intensity editing options.</para>
		///     <para xml:lang="zh-CN">使用明确的透明度及强度编辑选项初始化颜色条目。</para>
		/// </summary>
		public ColorModSettingsEntryDefinition(string id, ModSettingsText label, IModSettingsValueBinding<string> binding, ModSettingsText? description, bool editAlpha = true, bool editIntensity = false)
			: base(id, label, description)
		{
			ArgumentNullException.ThrowIfNull(binding, "binding");
			Binding = binding;
			EditAlpha = editAlpha;
			EditIntensity = editIntensity;
		}

		internal override void CollectChromeBindingSnapshots(Dictionary<string, ModSettingsChromeBindingSnapshot> target)
		{
			ModSettingsClipboardData.AddChromeBindingSnapshot(target, base.Id, Binding);
		}

		internal override bool TryPasteChromeBindingSnapshot(ModSettingsChromeBindingSnapshot snap, IModSettingsUiActionHost host)
		{
			IStructuredModSettingsValueAdapter<string> adapter = ModSettingsUiFactory.ResolveClipboardAdapter(Binding);
			if (!ModSettingsClipboardData.TryApplySerializedValueToBinding(Binding, adapter, snap, out var value))
			{
				return false;
			}
			Binding.Write(value);
			host.MarkDirty(Binding);
			return true;
		}

		internal override Control CreateControl(ModSettingsUiContext context)
		{
			return ModSettingsUiFactory.CreateColorEntry(context, this);
		}

		internal override bool TryResetToDefault(IModSettingsUiActionHost host)
		{
			return ModSettingsEntryDefinition.TryResetBindingToDefault(Binding, host);
		}
