	/// <summary>
	///     <para xml:lang="en">Provides the shared binding, placeholder, and length contract for text entries.</para>
	///     <para xml:lang="zh-CN">为文本条目提供共享的绑定、占位文本及长度契约。</para>
	/// </summary>
	public abstract class StringFieldModSettingsEntryDefinition : ModSettingsEntryDefinition
	{
		/// <summary>
		///     <para xml:lang="en">Gets the binding that stores the text value.</para>
		///     <para xml:lang="zh-CN">获取存储文本值的绑定。</para>
		/// </summary>
		public IModSettingsValueBinding<string> Binding { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional placeholder displayed while the field is empty.</para>
		///     <para xml:lang="zh-CN">获取字段为空时显示的可选占位文本。</para>
		/// </summary>
		public ModSettingsText? Placeholder { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional positive maximum character count.</para>
		///     <para xml:lang="zh-CN">获取可选的正数最大字符数。</para>
		/// </summary>
		public int? MaxLength { get; }

		internal override bool CanResetToDefault => ModSettingsEntryDefinition.BindingCanResetToDefault(Binding);

		/// <summary>
		///     <para xml:lang="en">Provides the shared binding, placeholder, and length contract for text entries.</para>
		///     <para xml:lang="zh-CN">为文本条目提供共享的绑定、占位文本及长度契约。</para>
		/// </summary>
		protected StringFieldModSettingsEntryDefinition(string id, ModSettingsText label, IModSettingsValueBinding<string> binding, ModSettingsText? placeholder, int? maxLength, ModSettingsText? description)
		{
			Binding = binding ?? throw new ArgumentNullException("binding");
			Placeholder = placeholder;
			if (((!maxLength.HasValue || maxLength.GetValueOrDefault() >= 1) ? 1 : 0) == 0)
			{
				throw new ArgumentOutOfRangeException("maxLength", "maxLength must be null or >= 1.");
			}
			MaxLength = maxLength;
			base..ctor(id, label, description);
		}

		internal override void CollectChromeBindingSnapshots(Dictionary<string, ModSettingsChromeBindingSnapshot> target)
		{
			ModSettingsClipboardData.AddChromeBindingSnapshot(target, base.Id, Binding);
		}

		internal override bool TryPasteChromeBindingSnapshot(ModSettingsChromeBindingSnapshot snap, IModSettingsUiActionHost host)
		{
			IStructuredModSettingsValueAdapter<string> adapter = ModSettingsUiFactory.ResolveClipboardAdapter(Binding);
			if (!ModSettingsClipboardData.TryApplySerializedValueToBinding(Binding, adapter, snap, out var value))
			{
				return false;
			}
			Binding.Write(value);
			host.MarkDirty(Binding);
			return true;
		}

		internal override bool TryResetToDefault(IModSettingsUiActionHost host)
		{
			return ModSettingsEntryDefinition.TryResetBindingToDefault(Binding, host);
		}
	}
