	///     <para xml:lang="zh-CN">定义只读的运行时热键摘要，左侧显示说明文本，右侧显示绑定标签。</para>
	/// </summary>
	public sealed class RuntimeHotkeySummaryModSettingsEntryDefinition(string id, ModSettingsText label, ModSettingsText body, IReadOnlyList<ModSettingsText> bindings, ModSettingsText? idSuffix = null) : ModSettingsEntryDefinition(id, label, idSuffix)
	{
		/// <summary>
		///     <para xml:lang="en">Gets the descriptive body displayed below the title.</para>
		///     <para xml:lang="zh-CN">获取标题下方显示的说明正文。</para>
		/// </summary>
		public ModSettingsText Body { get; } = body ?? throw new ArgumentNullException("body");

		/// <summary>
		///     <para xml:lang="en">Gets an immutable snapshot of the binding labels shown in the right column.</para>
		///     <para xml:lang="zh-CN">获取右侧栏所显示绑定标签的不可变快照。</para>
		/// </summary>
		public IReadOnlyList<ModSettingsText> Bindings { get; } = ValidateAndSnapshotBindings(bindings);

		internal override Control CreateControl(ModSettingsUiContext context)
		{
			return ModSettingsUiFactory.CreateRuntimeHotkeySummaryEntry(context, this);
		}

		private static IReadOnlyList<ModSettingsText> ValidateAndSnapshotBindings(IReadOnlyList<ModSettingsText>? bindings)
		{
			ArgumentNullException.ThrowIfNull(bindings, "bindings");
			ModSettingsText[] array = bindings.ToArray();
			if (array.Any((ModSettingsText binding) => binding == null))
			{
				throw new ArgumentException("Runtime hotkey binding labels cannot be null.", "bindings");
			}
			return Array.AsReadOnly(array);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Defines an image preview sourced from <see cref="P:STS2RitsuLib.Settings.ImageModSettingsEntryDefinition.TextureProvider" /> when it is created.</para>
	///     <para xml:lang="zh-CN">定义创建时由 <see cref="P:STS2RitsuLib.Settings.ImageModSettingsEntryDefinition.TextureProvider" /> 提供内容的图像预览。</para>
	/// </summary>
	public sealed class ImageModSettingsEntryDefinition : ModSettingsEntryDefinition
	{
		/// <summary>
		///     <para xml:lang="en">Gets the texture provider invoked when the preview is created.</para>
		///     <para xml:lang="zh-CN">获取创建预览时调用的纹理提供器。</para>
		/// </summary>
		public Func<Texture2D?> TextureProvider { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the finite positive preview height in pixels.</para>
		///     <para xml:lang="zh-CN">获取以像素为单位的有限正数预览高度。</para>
		/// </summary>
		public float PreviewHeight { get; }

		/// <summary>
		///     <para xml:lang="en">Defines an image preview sourced from <see cref="P:STS2RitsuLib.Settings.ImageModSettingsEntryDefinition.TextureProvider" /> when it is created.</para>
		///     <para xml:lang="zh-CN">定义创建时由 <see cref="P:STS2RitsuLib.Settings.ImageModSettingsEntryDefinition.TextureProvider" /> 提供内容的图像预览。</para>
		/// </summary>
		public ImageModSettingsEntryDefinition(string id, ModSettingsText label, Func<Texture2D?> textureProvider, float previewHeight, ModSettingsText? description)
		{
			TextureProvider = textureProvider ?? throw new ArgumentNullException("textureProvider");
			if (!float.IsFinite(previewHeight) || !(previewHeight > 0f))
			{
				throw new ArgumentOutOfRangeException("previewHeight", "Image previewHeight must be finite and > 0.");
			}
			PreviewHeight = previewHeight;
			base..ctor(id, label, description);
