	public sealed class CustomModSettingsEntryDefinition(string id, ModSettingsText label, Func<IModSettingsUiActionHost, Control> controlFactory, ModSettingsText? description, Func<bool>? visibilityPredicate = null) : ModSettingsEntryDefinition(id, label, description)
	{
		/// <summary>
		///     <para xml:lang="en">Gets the factory that creates the row control.</para>
		///     <para xml:lang="zh-CN">获取创建行控件的工厂。</para>
		/// </summary>
		public Func<IModSettingsUiActionHost, Control> ControlFactory { get; } = controlFactory ?? throw new ArgumentNullException("controlFactory");

		/// <inheritdoc />
		public override Func<bool>? VisibilityPredicate => visibilityPredicate;

		internal override Control CreateControl(ModSettingsUiContext context)
		{
			return ModSettingsUiFactory.CreateCustomEntry(context, this);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines a reorderable editor for a bound list of <typeparamref name="TItem" /> values, with optional
	///         structured clipboard support for each item.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义 <typeparamref name="TItem" /> 绑定列表的可重排编辑器，并可为各列表项提供结构化剪贴板支持。
	///     </para>
	/// </summary>
	public sealed class ListModSettingsEntryDefinition<TItem>(string id, ModSettingsText label, IModSettingsValueBinding<List<TItem>> binding, Func<TItem> createItem, Func<TItem, ModSettingsText> itemLabel, Func<TItem, ModSettingsText?>? itemDescription, Func<ModSettingsListItemContext<TItem>, Control>? itemEditorFactory, IStructuredModSettingsValueAdapter<TItem>? itemDataAdapter, ModSettingsText addButtonText, ModSettingsText? description, bool collapsibleItems, bool startItemsCollapsed, Func<ModSettingsListItemContext<TItem>, Control?>? itemHeaderAccessoryFactory) : ModSettingsEntryDefinition(id, label, description)
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets the list binding. A binding without structured data support is wrapped with a list adapter.
		///     </para>
		///     <para xml:lang="zh-CN">获取列表绑定。不支持结构化数据的绑定会由列表适配器包装。</para>
		/// </summary>
		public IModSettingsValueBinding<List<TItem>> Binding { get; } = (!((binding ?? throw new ArgumentNullException("binding")) is IStructuredModSettingsValueBinding<List<TItem>>)) ? ModSettingsBindings.WithAdapter<List<TItem>>(binding, ModSettingsStructuredData.List(itemDataAdapter)) : binding;

		/// <summary>
		///     <para xml:lang="en">Gets the factory invoked to create an item when the add button is pressed.</para>
		///     <para xml:lang="zh-CN">获取按下添加按钮时用于创建列表项的工厂。</para>
		/// </summary>
		public Func<TItem> CreateItem { get; } = createItem ?? throw new ArgumentNullException("createItem");

		/// <summary>
		///     <para xml:lang="en">Gets the display-label resolver for each list item.</para>
		///     <para xml:lang="zh-CN">获取各列表项的显示标签解析器。</para>
		/// </summary>
		public Func<TItem, ModSettingsText> ItemLabel { get; } = itemLabel ?? throw new ArgumentNullException("itemLabel");

		/// <summary>
		///     <para xml:lang="en">Gets the optional display-description resolver for each list item.</para>
		///     <para xml:lang="zh-CN">获取各列表项的可选显示说明解析器。</para>
		/// </summary>
		public Func<TItem, ModSettingsText?>? ItemDescription { get; } = itemDescription;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the optional factory for a list item's detail editor. When absent, the UI uses its default item
		///         layout.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取列表项详情编辑器的可选工厂；未提供时，界面使用默认的列表项布局。
		///     </para>
		/// </summary>
		public Func<ModSettingsListItemContext<TItem>, Control>? ItemEditorFactory { get; } = itemEditorFactory;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the optional structured-data adapter used for individual items. When absent, the list adapter
		///         uses its JSON-based default.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取单个列表项使用的可选结构化数据适配器；未提供时，列表适配器使用默认的 JSON 实现。
		///     </para>
		/// </summary>
		public IStructuredModSettingsValueAdapter<TItem>? ItemDataAdapter { get; } = itemDataAdapter;

		/// <summary>
		///     <para xml:lang="en">Gets the localized text displayed on the add button.</para>
		///     <para xml:lang="zh-CN">获取添加按钮显示的本地化文本。</para>
		/// </summary>
		public ModSettingsText AddButtonText { get; } = addButtonText ?? throw new ArgumentNullException("addButtonText");

		/// <summary>
		///     <para xml:lang="en">Gets whether each list item can collapse its detail editor.</para>
		///     <para xml:lang="zh-CN">获取各列表项是否可以折叠其详情编辑器。</para>
		/// </summary>
		public bool CollapsibleItems { get; } = collapsibleItems;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether item detail editors initially start collapsed when <see cref="P:STS2RitsuLib.Settings.ListModSettingsEntryDefinition`1.CollapsibleItems" /> is
		///         enabled.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取启用 <see cref="P:STS2RitsuLib.Settings.ListModSettingsEntryDefinition`1.CollapsibleItems" /> 时列表项详情编辑器是否初始折叠。
		///     </para>
		/// </summary>
		public bool StartItemsCollapsed { get; } = startItemsCollapsed;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the optional factory for compact controls placed in the always-visible item header.
		///     </para>
		///     <para xml:lang="zh-CN">获取在始终可见的列表项标题栏中放置紧凑控件的可选工厂。</para>
		/// </summary>
		public Func<ModSettingsListItemContext<TItem>, Control?>? ItemHeaderAccessoryFactory { get; } = itemHeaderAccessoryFactory;

		internal override bool CanResetToDefault => ModSettingsEntryDefinition.BindingCanResetToDefault(Binding);

		internal override void CollectChromeBindingSnapshots(Dictionary<string, ModSettingsChromeBindingSnapshot> target)
		{
			ModSettingsClipboardData.AddChromeBindingSnapshot(target, base.Id, Binding);
		}

		internal override bool TryPasteChromeBindingSnapshot(ModSettingsChromeBindingSnapshot snap, IModSettingsUiActionHost host)
		{
			IStructuredModSettingsValueAdapter<List<TItem>> adapter = ModSettingsUiFactory.ResolveClipboardAdapter(Binding);
			if (!ModSettingsClipboardData.TryApplySerializedValueToBinding(Binding, adapter, snap, out var value))
			{
				return false;
			}
			Binding.Write(value);
			host.MarkDirty(Binding);
			return true;
		}

		internal override Control CreateControl(ModSettingsUiContext context)
		{
			return ModSettingsUiFactory.CreateListEntry(context, this);
		}

		internal override bool TryResetToDefault(IModSettingsUiActionHost host)
		{
			return ModSettingsEntryDefinition.TryResetBindingToDefault(Binding, host);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Defines an integer slider over an inclusive range with discrete steps.</para>
	///     <para xml:lang="zh-CN">定义在闭区间内按离散步长调整数值的整数滑块。</para>
	/// </summary>
	public sealed class IntSliderModSettingsEntryDefinition : ModSettingsEntryDefinition
	{
		/// <summary>
		///     <para xml:lang="en">Gets the binding that stores the integer value.</para>
		///     <para xml:lang="zh-CN">获取存储整数值的绑定。</para>
		/// </summary>
		public IModSettingsValueBinding<int> Binding { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the inclusive minimum value.</para>
		///     <para xml:lang="zh-CN">获取闭区间的最小值。</para>
		/// </summary>
		public int MinValue { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the inclusive maximum value.</para>
		///     <para xml:lang="zh-CN">获取闭区间的最大值。</para>
		/// </summary>
		public int MaxValue { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the positive step between selectable values.</para>
		///     <para xml:lang="zh-CN">获取可选数值之间的正步长。</para>
		/// </summary>
		public int Step { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional formatter for the displayed value.</para>
		///     <para xml:lang="zh-CN">获取显示数值使用的可选格式化器。</para>
		/// </summary>
		public Func<int, string>? ValueFormatter { get; }

		internal override bool CanResetToDefault => ModSettingsEntryDefinition.BindingCanResetToDefault(Binding);

		/// <summary>
		///     <para xml:lang="en">Defines an integer slider over an inclusive range with discrete steps.</para>
		///     <para xml:lang="zh-CN">定义在闭区间内按离散步长调整数值的整数滑块。</para>
		/// </summary>
		public IntSliderModSettingsEntryDefinition(string id, ModSettingsText label, IModSettingsValueBinding<int> binding, int minValue, int maxValue, int step, Func<int, string>? valueFormatter, ModSettingsText? description)
		{
			Binding = binding ?? throw new ArgumentNullException("binding");
			MinValue = minValue;
			if (maxValue < minValue)
			{
				throw new ArgumentOutOfRangeException("maxValue", "Slider maxValue must be >= minValue.");
			}
			MaxValue = maxValue;
			if (step <= 0)
			{
				throw new ArgumentOutOfRangeException("step", "Slider step must be > 0.");
			}
			Step = step;
			ValueFormatter = valueFormatter;
			base..ctor(id, label, description);
		}

		internal override void CollectChromeBindingSnapshots(Dictionary<string, ModSettingsChromeBindingSnapshot> target)
		{
			ModSettingsClipboardData.AddChromeBindingSnapshot(target, base.Id, Binding);
		}

		internal override bool TryPasteChromeBindingSnapshot(ModSettingsChromeBindingSnapshot snap, IModSettingsUiActionHost host)
		{
			IStructuredModSettingsValueAdapter<int> adapter = ModSettingsUiFactory.ResolveClipboardAdapter(Binding);
			if (!ModSettingsClipboardData.TryApplySerializedValueToBinding(Binding, adapter, snap, out var value))
			{
				return false;
			}
			Binding.Write(value);
			host.MarkDirty(Binding);
			return true;
		}

		internal override Control CreateControl(ModSettingsUiContext context)
		{
			return ModSettingsUiFactory.CreateIntSliderEntry(context, this);
		}

		internal override bool TryResetToDefault(IModSettingsUiActionHost host)
		{
			return ModSettingsEntryDefinition.TryResetBindingToDefault(Binding, host);
		}
	}
