		public ModSettingsText ButtonText { get; }

		/// <summary>
		///     <para xml:lang="en">Defines a navigation row that opens another registered settings page.</para>
		///     <para xml:lang="zh-CN">定义用于打开另一个已注册设置页面的导航行。</para>
		/// </summary>
