	internal sealed class ModSettingsEntryEnabledWrapper(ModSettingsEntryDefinition inner, Func<bool> enabledPredicate) : ModSettingsEntryDecorator(inner)
	{
		public override Func<bool> EnabledPredicate => EvaluateEnabled;

		private bool EvaluateEnabled()
		{
			if (ModSettingsPredicate.Evaluate(base.Inner.EnabledPredicate))
			{
				return ModSettingsPredicate.Evaluate(enabledPredicate);
			}
			return false;
		}
	}
	internal sealed class ModSettingsEntryVisibilityWrapper(ModSettingsEntryDefinition inner, Func<bool> visibilityPredicate) : ModSettingsEntryDecorator(inner)
	{
		public override Func<bool> VisibilityPredicate => EvaluateVisibility;

		private bool EvaluateVisibility()
		{
			if (ModSettingsPredicate.Evaluate(base.Inner.VisibilityPredicate))
			{
				return ModSettingsPredicate.Evaluate(visibilityPredicate);
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Identifies the game context from which the RitsuLib mod settings UI is opened. Pages and sections can use
	///         it to control visibility and editability.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         标识打开 RitsuLib 模组设置界面时所在的游戏上下文。页面与节可据此控制可见性和可编辑性。
	///     </para>
	/// </summary>
	[Flags]
	public enum ModSettingsHostSurface
	{
		/// <summary>
		///     <para xml:lang="en">No host context. A mask containing only this value never matches a resolved host.</para>
		///     <para xml:lang="zh-CN">无宿主上下文。仅包含此值的掩码不会匹配任何已解析的宿主。</para>
		/// </summary>
		None = 0,
		/// <summary>
		///     <para xml:lang="en">Settings opened from the main menu while no run is in progress.</para>
		///     <para xml:lang="zh-CN">未进行对局时从主菜单打开的设置。</para>
		/// </summary>
		MainMenu = 1,
		/// <summary>
		///     <para xml:lang="en">Settings opened during a run while no combat is in progress.</para>
		///     <para xml:lang="zh-CN">对局进行中但当前不在战斗内时打开的设置。</para>
		/// </summary>
		RunPause = 2,
		/// <summary>
		///     <para xml:lang="en">Settings opened while combat is in progress.</para>
		///     <para xml:lang="zh-CN">战斗进行中打开的设置。</para>
		/// </summary>
		CombatPause = 4,
		/// <summary>
		///     <para xml:lang="en">A mask containing every built-in host context.</para>
		///     <para xml:lang="zh-CN">包含所有内置宿主上下文的掩码。</para>
		/// </summary>
		All = MainMenu | RunPause | CombatPause
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Resolves the active <see cref="T:STS2RitsuLib.Settings.ModSettingsHostSurface" /> from the run and combat managers.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         根据对局与战斗管理器解析当前的 <see cref="T:STS2RitsuLib.Settings.ModSettingsHostSurface" />。
	///     </para>
	/// </summary>
	public static class ModSettingsHostSurfaceResolver
	{
		/// <summary>
		///     <para xml:lang="en">Returns exactly one flag describing the current settings host context.</para>
		///     <para xml:lang="zh-CN">返回且仅返回一个用于描述当前设置宿主上下文的标志。</para>
		/// </summary>
		public static ModSettingsHostSurface ResolveCurrent()
		{
			RunManager instance = RunManager.Instance;
			if (instance == null || !instance.IsInProgress)
			{
				return ModSettingsHostSurface.MainMenu;
			}
			CombatManager instance2 = CombatManager.Instance;
			if (instance2 == null || !instance2.IsInProgress)
			{
				return ModSettingsHostSurface.RunPause;
			}
			return ModSettingsHostSurface.CombatPause;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Determines whether a host mask includes the context returned by <see cref="M:STS2RitsuLib.Settings.ModSettingsHostSurfaceResolver.ResolveCurrent" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         确定宿主掩码是否包含 <see cref="M:STS2RitsuLib.Settings.ModSettingsHostSurfaceResolver.ResolveCurrent" /> 返回的上下文。
		///     </para>
		/// </summary>
		/// <param name="mask">
		///     <para xml:lang="en">The allowed host contexts.</para>
		///     <para xml:lang="zh-CN">允许的宿主上下文。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">Whether the current host is included.</para>
		///     <para xml:lang="zh-CN">当前宿主是否包含在内。</para>
		/// </returns>
		public static bool IsVisibleOnCurrentHost(ModSettingsHostSurface mask)
		{
			ModSettingsHostSurface modSettingsHostSurface = ResolveCurrent();
			return (mask & modSettingsHostSurface) != 0;
		}

		/// <summary>
		///     <para xml:lang="en">Determines whether a read-only mask includes the current host context.</para>
		///     <para xml:lang="zh-CN">确定只读掩码是否包含当前宿主上下文。</para>
		/// </summary>
		/// <param name="readOnlyMask">
		///     <para xml:lang="en">The host contexts in which inputs should be read-only.</para>
		///     <para xml:lang="zh-CN">输入应为只读的宿主上下文。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">Whether the current host is read-only.</para>
		///     <para xml:lang="zh-CN">当前宿主是否为只读。</para>
		/// </returns>
		public static bool IsReadOnlyOnCurrentHost(ModSettingsHostSurface readOnlyMask)
		{
			ModSettingsHostSurface modSettingsHostSurface = ResolveCurrent();
			return (readOnlyMask & modSettingsHostSurface) != 0;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Combines an optional existing predicate and a host-context predicate with logical AND. A missing
		///         existing predicate is treated as <see langword="true" />; any evaluated predicate that throws is
		///         logged and treated as <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         以逻辑与组合可选的现有谓词与宿主上下文谓词。缺少现有谓词时按
		///         <see langword="true" /> 处理；任何已求值谓词抛出的异常都会被记录并按
		///         <see langword="false" /> 处理。
		///     </para>
		/// </summary>
		/// <param name="existing">
		///     <para xml:lang="en">The optional existing visibility predicate.</para>
		///     <para xml:lang="zh-CN">可选的现有可见性谓词。</para>
		/// </param>
		/// <param name="hostPredicate">
		///     <para xml:lang="en">The required host-context predicate.</para>
		///     <para xml:lang="zh-CN">必需的宿主上下文谓词。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A predicate that requires both conditions to pass.</para>
		///     <para xml:lang="zh-CN">要求两个条件均通过的谓词。</para>
		/// </returns>
		public static Func<bool> CombineVisibility(Func<bool>? existing, Func<bool> hostPredicate)
		{
			ArgumentNullException.ThrowIfNull(hostPredicate, "hostPredicate");
			return () => ModSettingsPredicate.Evaluate(existing) && ModSettingsPredicate.Evaluate(hostPredicate);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides the current item, list operations, structured clipboard access, transient UI state, and nested
	///         entry helpers to a custom list-item editor.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为自定义列表项编辑器提供当前列表项、列表操作、结构化剪贴板、临时界面状态及嵌套条目辅助方法。
	///     </para>
	/// </summary>
	public sealed class ModSettingsListItemContext<TItem>
	{
		internal sealed class ListRowLiveIndex
		{
			public int Value;
		}

		private readonly Action? _duplicate;

		private readonly ListRowLiveIndex _liveIndex;

		private readonly Action? _moveDown;

		private readonly Action? _moveUp;

		private readonly Action _remove;

		private readonly Action _requestRefresh;

		private readonly ModSettingsUiContext _uiContext;

		private readonly Action<TItem> _update;

		/// <summary>
		///     <para xml:lang="en">Gets the key assigned to this row's transient UI state.</para>
		///     <para xml:lang="zh-CN">获取分配给此行临时界面状态的键。</para>
		/// </summary>
		public string RowStateKey { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the row's current zero-based list index.</para>
		///     <para xml:lang="zh-CN">获取此行当前在列表中的从零开始索引。</para>
		/// </summary>
		public int Index => _liveIndex.Value;

		/// <summary>
		///     <para xml:lang="en">Gets the current number of items in the list.</para>
		///     <para xml:lang="zh-CN">获取列表当前包含的列表项数量。</para>
		/// </summary>
		public int ItemCount { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Gets the item snapshot currently represented by this row.</para>
		///     <para xml:lang="zh-CN">获取此行当前表示的列表项快照。</para>
		/// </summary>
		public TItem Item { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Gets whether the row can move one position toward the start of the list.</para>
		///     <para xml:lang="zh-CN">获取此行是否可以向列表开头移动一个位置。</para>
		/// </summary>
		public bool CanMoveUp => Index > 0;

		/// <summary>
		///     <para xml:lang="en">Gets whether the row can move one position toward the end of the list.</para>
		///     <para xml:lang="zh-CN">获取此行是否可以向列表末尾移动一个位置。</para>
		/// </summary>
		public bool CanMoveDown => Index < ItemCount - 1;

		/// <summary>
		///     <para xml:lang="en">Gets the binding scoped to this row's current list item.</para>
		///     <para xml:lang="zh-CN">获取作用域限定为此行当前列表项的绑定。</para>
		/// </summary>
		public IModSettingsValueBinding<TItem> Binding { get; }

		/// <summary>
		///     <para xml:lang="en">Gets whether <see cref="P:STS2RitsuLib.Settings.ModSettingsListItemContext`1.Binding" /> supports structured copy and paste.</para>
		///     <para xml:lang="zh-CN">获取 <see cref="P:STS2RitsuLib.Settings.ModSettingsListItemContext`1.Binding" /> 是否支持结构化复制与粘贴。</para>
		/// </summary>
		public bool SupportsStructuredClipboard => Binding is IStructuredModSettingsValueBinding<TItem>;

		internal ModSettingsListItemContext(ModSettingsUiContext uiContext, IModSettingsValueBinding<TItem> binding, string rowStateKey, ListRowLiveIndex liveIndex, int itemCount, TItem item, Action<TItem> update, Action? moveUp, Action? moveDown, Action? duplicate, Action remove, Action requestRefresh)
		{
			_uiContext = uiContext;
			Binding = binding;
			RowStateKey = rowStateKey;
			_liveIndex = liveIndex;
			ItemCount = itemCount;
			Item = item;
			_update = update;
			_moveUp = moveUp;
			_moveDown = moveDown;
			_duplicate = duplicate;
			_remove = remove;
			_requestRefresh = requestRefresh;
		}

		internal void SyncRowListState(int index, int itemCount, TItem item)
		{
			_liveIndex.Value = index;
			ItemCount = itemCount;
			Item = item;
		}

		/// <summary>
		///     <para xml:lang="en">Writes <paramref name="item" /> to the row's current <see cref="P:STS2RitsuLib.Settings.ModSettingsListItemContext`1.Index" />.</para>
		///     <para xml:lang="zh-CN">将 <paramref name="item" /> 写入此行当前的 <see cref="P:STS2RitsuLib.Settings.ModSettingsListItemContext`1.Index" /> 位置。</para>
		/// </summary>
		public void Update(TItem item)
		{
			_update(item);
		}

		/// <summary>
		///     <para xml:lang="en">Removes this row's current item from the list.</para>
		///     <para xml:lang="zh-CN">从列表中移除此行当前表示的列表项。</para>
		/// </summary>
		public void Remove()
		{
			_remove();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Moves the row one position toward the start when <see cref="P:STS2RitsuLib.Settings.ModSettingsListItemContext`1.CanMoveUp" /> is true.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当 <see cref="P:STS2RitsuLib.Settings.ModSettingsListItemContext`1.CanMoveUp" /> 为 <see langword="true" /> 时，将此行向列表开头移动一个位置。
		///     </para>
		/// </summary>
		public void MoveUp()
		{
			_moveUp?.Invoke();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Moves the row one position toward the end when <see cref="P:STS2RitsuLib.Settings.ModSettingsListItemContext`1.CanMoveDown" /> is true.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当 <see cref="P:STS2RitsuLib.Settings.ModSettingsListItemContext`1.CanMoveDown" /> 为 <see langword="true" /> 时，将此行向列表末尾移动一个位置。
		///     </para>
		/// </summary>
		public void MoveDown()
		{
			_moveDown?.Invoke();
		}

		/// <summary>
		///     <para xml:lang="en">Duplicates this row when the list host provides duplication support.</para>
		///     <para xml:lang="zh-CN">当列表宿主提供复制支持时复制此行。</para>
		/// </summary>
		public void Duplicate()
		{
			_duplicate?.Invoke();
		}

		/// <summary>
		///     <para xml:lang="en">Requests a deferred rebuild of the list UI.</para>
		///     <para xml:lang="zh-CN">请求延迟重建列表界面。</para>
		/// </summary>
		public void RequestRefresh()
		{
			_requestRefresh();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Reads a typed value from this row's transient state for the current settings UI session.
		///     </para>
		///     <para xml:lang="zh-CN">从当前设置界面会话中此行的临时状态读取类型化值。</para>
		/// </summary>
		public TValue GetRowState<TValue>(string key, TValue fallback = default(TValue))
		{
			if (_uiContext.TryGetRowState<TValue>(RowStateKey, key, out TValue value) && value != null)
			{
				return value;
			}
			return fallback;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Stores a typed value in this row's transient state for the current settings UI session.
		///     </para>
		///     <para xml:lang="zh-CN">在当前设置界面会话中此行的临时状态内存储类型化值。</para>
		/// </summary>
		public void SetRowState<TValue>(string key, TValue value)
		{
			_uiContext.SetRowState(RowStateKey, key, value);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Copies <see cref="P:STS2RitsuLib.Settings.ModSettingsListItemContext`1.Item" /> through the binding's structured adapter when one is available.
		///     </para>
		///     <para xml:lang="zh-CN">当绑定提供结构化适配器时，通过该适配器复制 <see cref="P:STS2RitsuLib.Settings.ModSettingsListItemContext`1.Item" />。</para>
		/// </summary>
		public bool TryCopyToClipboard(ModSettingsClipboardScope scope = ModSettingsClipboardScope.Self)
		{
			if (!(Binding is IStructuredModSettingsValueBinding<TItem> structuredModSettingsValueBinding))
			{
				return false;
			}
			ModSettingsClipboardOperations.InvokeCopy(Binding, scope, structuredModSettingsValueBinding.Adapter, Item);
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Determines whether the current clipboard payload can be pasted through this row's structured
		///         adapter.
		///     </para>
		///     <para xml:lang="zh-CN">确定当前剪贴板载荷是否可通过此行的结构化适配器粘贴。</para>
		/// </summary>
		public bool CanPasteFromClipboard()
		{
			if (Binding is IStructuredModSettingsValueBinding<TItem> structuredModSettingsValueBinding)
			{
				return ModSettingsClipboardOperations.CanPasteBindingValue(Binding, structuredModSettingsValueBinding.Adapter);
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to paste a structured value into this row, calls <see cref="M:STS2RitsuLib.Settings.ModSettingsListItemContext`1.Update(`0)" /> on success, and
		///         reports a rejected payload through the settings UI.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试将结构化值粘贴到此行；成功时调用 <see cref="M:STS2RitsuLib.Settings.ModSettingsListItemContext`1.Update(`0)" />，载荷被拒绝时通过设置界面报告原因。
		///     </para>
		/// </summary>
		public bool TryPasteFromClipboard()
		{
			if (!(Binding is IStructuredModSettingsValueBinding<TItem> structuredModSettingsValueBinding))
			{
				return false;
			}
			if (!ModSettingsClipboardOperations.TryPasteBindingValue(Binding, structuredModSettingsValueBinding.Adapter, out var value, out var failureReason))
			{
				_uiContext.NotifyPasteFailure(failureReason);
				return false;
			}
			Update(value);
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Projects a value within <typeparamref name="TItem" /> as a child binding for a nested editor.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将 <typeparamref name="TItem" /> 内的值投影为供嵌套编辑器使用的子绑定。
		///     </para>
		/// </summary>
		public IModSettingsValueBinding<TValue> Project<TValue>(string dataKey, Func<TItem, TValue> getter, Func<TItem, TValue, TItem> setter, IStructuredModSettingsValueAdapter<TValue>? adapter = null)
		{
			return ModSettingsBindings.Project(Binding, dataKey, getter, setter, adapter);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates the control for <paramref name="entry" /> within this row's settings UI context.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在此行的设置界面上下文中为 <paramref name="entry" /> 创建控件。
		///     </para>
		/// </summary>
		public Control CreateEntry(ModSettingsEntryDefinition entry)
		{
			ArgumentNullException.ThrowIfNull(entry, "entry");
			return entry.CreateControl(_uiContext);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds and creates a nested list editor for <typeparamref name="TChild" /> values.
		///     </para>
		///     <para xml:lang="zh-CN">构建并创建用于编辑 <typeparamref name="TChild" /> 值的嵌套列表编辑器。</para>
		/// </summary>
		public Control CreateListEditor<TChild>(string id, ModSettingsText label, IModSettingsValueBinding<List<TChild>> binding, Func<TChild> createItem, Func<TChild, ModSettingsText> itemLabel, Func<TChild, ModSettingsText?>? itemDescription = null, Func<ModSettingsListItemContext<TChild>, Control>? itemEditorFactory = null, ModSettingsText? addButtonText = null, ModSettingsText? description = null)
		{
			return CreateEntry(new ListModSettingsEntryDefinition<TChild>(id, label, binding, createItem, itemLabel, itemDescription, itemEditorFactory, null, addButtonText ?? ModSettingsLocalization.Text("button.add", "Add"), description, collapsibleItems: false, startItemsCollapsed: false, null));
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Identifies a stable location in the RitsuLib mod settings UI, from a mod down to an optional entry.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         标识 RitsuLib 模组设置界面中从模组到可选条目的稳定位置。
	///     </para>
	/// </summary>
	/// <param name="ModId">
	///     <para xml:lang="en">The target mod ID.</para>
	///     <para xml:lang="zh-CN">目标模组 ID。</para>
	/// </param>
	/// <param name="PageId">
	///     <para xml:lang="en">The optional target page ID.</para>
	///     <para xml:lang="zh-CN">可选的目标页面 ID。</para>
	/// </param>
	/// <param name="SectionId">
	///     <para xml:lang="en">The optional target section ID.</para>
	///     <para xml:lang="zh-CN">可选的目标节 ID。</para>
	/// </param>
	/// <param name="EntryId">
	///     <para xml:lang="en">The optional target entry ID.</para>
	///     <para xml:lang="zh-CN">可选的目标条目 ID。</para>
	/// </param>
	public sealed record ModSettingsLocation(string ModId, string? PageId = null, string? SectionId = null, string? EntryId = null);
	/// <summary>
	///     <para xml:lang="en">Configures presentation behavior when opening a settings location.</para>
	///     <para xml:lang="zh-CN">配置打开设置位置时的呈现行为。</para>
	/// </summary>
	public sealed class ModSettingsOpenOptions
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes whether to briefly pulse-highlight the target section or entry after navigation.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化导航后是否短暂脉冲高亮目标节或条目。</para>
		/// </summary>
		public bool Highlight { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">Gets or initializes whether to move UI focus into the target area when possible.</para>
		///     <para xml:lang="zh-CN">获取或初始化是否在可行时将界面焦点移入目标区域。</para>
		/// </summary>
		public bool Focus { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes whether to expand a collapsed target section before scrolling to an entry inside
		///         it.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或初始化滚动到折叠目标节中的条目前是否先展开该节。
		///     </para>
		/// </summary>
		public bool ExpandCollapsedSection { get; init; } = true;
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Describes the acceptance, resolution, or completion of a mod settings navigation request.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         描述模组设置导航请求的接受、解析或完成结果。
	///     </para>
	/// </summary>
	public sealed class ModSettingsOpenResult
	{
		/// <summary>
		///     <para xml:lang="en">Gets whether the reported navigation stage succeeded.</para>
		///     <para xml:lang="zh-CN">获取所报告的导航阶段是否成功。</para>
		/// </summary>
		public bool Success { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the stable machine-readable result code.</para>
		///     <para xml:lang="zh-CN">获取稳定的机器可读结果代码。</para>
		/// </summary>
		public string Code { get; init; } = "";

		/// <summary>
		///     <para xml:lang="en">Gets a human-readable result message.</para>
		///     <para xml:lang="zh-CN">获取便于阅读的结果消息。</para>
		/// </summary>
		public string Message { get; init; } = "";

		/// <summary>
		///     <para xml:lang="en">Gets the target mod ID reported for this stage.</para>
		///     <para xml:lang="zh-CN">获取此阶段所报告的目标模组 ID。</para>
		/// </summary>
		public string ModId { get; init; } = "";

		/// <summary>
		///     <para xml:lang="en">Gets the reported target page ID, when present.</para>
		///     <para xml:lang="zh-CN">获取所报告的目标页面 ID（如果存在）。</para>
		/// </summary>
		public string? PageId { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the reported target section ID, when present.</para>
		///     <para xml:lang="zh-CN">获取所报告的目标节 ID（如果存在）。</para>
		/// </summary>
		public string? SectionId { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the reported target entry ID, when present.</para>
		///     <para xml:lang="zh-CN">获取所报告的目标条目 ID（如果存在）。</para>
		/// </summary>
		public string? EntryId { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets whether navigation was queued for later completion.</para>
		///     <para xml:lang="zh-CN">获取导航是否已排队等待稍后完成。</para>
		/// </summary>
		public bool IsDeferred { get; init; }

		internal static ModSettingsOpenResult Ok(string code, string message, ModSettingsLocation location, bool isDeferred = false)
		{
			return new ModSettingsOpenResult
			{
				Success = true,
				Code = code,
				Message = message,
				ModId = location.ModId,
				PageId = location.PageId,
				SectionId = location.SectionId,
				EntryId = location.EntryId,
				IsDeferred = isDeferred
			};
		}

		internal static ModSettingsOpenResult Error(string code, string message, ModSettingsLocation location)
		{
			return new ModSettingsOpenResult
			{
				Success = false,
				Code = code,
				Message = message,
				ModId = location.ModId,
				PageId = location.PageId,
				SectionId = location.SectionId,
				EntryId = location.EntryId
			};
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides public entry points for opening RitsuLib mod settings locations from mods, reflection, or
	///         console commands.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供从模组、反射调用或控制台命令打开 RitsuLib 模组设置位置的公共入口。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Call these UI navigation entry points on the Godot main thread. Resolution is synchronous; methods ending
	///         in <c>Async</c> additionally wait for the visible navigation to finish.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         请在 Godot 主线程调用这些界面导航入口。位置解析会同步完成；名称以 <c>Async</c> 结尾的方法还会等待可见界面完成导航。
	///     </para>
	/// </remarks>
	public static class ModSettingsNavigator
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Resolves a location supplied as individual IDs, opens an available settings host, and queues the
		///         visible navigation for a later frame. Pass <see langword="null" /> for unspecified IDs.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         解析以各个 ID 提供的位置，打开可用的设置宿主，并将可见界面的导航排到后续帧执行。
		///         未指定的 ID 应传入 <see langword="null" />。
		///     </para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">The target mod ID.</para>
		///     <para xml:lang="zh-CN">目标模组 ID。</para>
		/// </param>
		/// <param name="pageId">
		///     <para xml:lang="en">The optional target page ID.</para>
		///     <para xml:lang="zh-CN">可选的目标页面 ID。</para>
		/// </param>
		/// <param name="sectionId">
		///     <para xml:lang="en">The optional target section ID.</para>
		///     <para xml:lang="zh-CN">可选的目标节 ID。</para>
		/// </param>
		/// <param name="entryId">
		///     <para xml:lang="en">The optional target entry ID.</para>
		///     <para xml:lang="zh-CN">可选的目标条目 ID。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         A deferred success result when the location is resolved and queued; otherwise, an input, registry,
		///         resolution, or host error. Deferred execution failures are logged and are not reflected in this
		///         immediate result.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         位置成功解析并排队时返回延迟成功结果；否则返回输入、注册表、位置解析或宿主错误。
		///         延迟执行期间的失败只会被记录，不会反映在此即时结果中。
		///     </para>
		/// </returns>
		public static ModSettingsOpenResult RequestOpenByIds(string modId, string? pageId, string? sectionId, string? entryId)
		{
			//IL_005d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0062: Unknown result type (might be due to invalid IL or missing references)
			ModSettingsOpenResult modSettingsOpenResult = ResolveLocation(Normalize(new ModSettingsLocation(modId, pageId, sectionId, entryId)));
			if (!modSettingsOpenResult.Success)
			{
				return modSettingsOpenResult;
			}
			ModSettingsLocation location = ToResolvedLocation(modSettingsOpenResult);
			if (!TryOpenHost(out RitsuModSettingsSubmenu submenu, out string error))
			{
				return ModSettingsOpenResult.Error("no-settings-host", error, location);
			}
			Callable val = Callable.From((Action)delegate
			{
				RunDeferredOpenAsync(submenu, location);
			});
			((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			return ModSettingsOpenResult.Ok("requested", "Requested to open settings location '" + FormatLocation(location) + "'.", location, isDeferred: true);
		}

		private static async Task RunDeferredOpenAsync(RitsuModSettingsSubmenu submenu, ModSettingsLocation location)
		{
			try
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)submenu))
				{
					await submenu.OpenToAsync(location, new ModSettingsOpenOptions());
				}
			}
			catch (OperationCanceledException)
			{
			}
			catch (Exception ex2) when (RitsuLibExceptionPolicy.IsRecoverable(ex2))
			{
				RitsuLibFramework.Logger.Warn($"[Settings] Deferred navigation failed: {ex2}", 1);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Opens a settings location supplied as individual IDs and waits for the visible UI to finish navigating
		///         to it.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         打开以各个 ID 提供的设置位置，并等待可见界面完成导航。
		///     </para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">The target mod ID.</para>
		///     <para xml:lang="zh-CN">目标模组 ID。</para>
		/// </param>
		/// <param name="pageId">
		///     <para xml:lang="en">The optional target page ID.</para>
		///     <para xml:lang="zh-CN">可选的目标页面 ID。</para>
		/// </param>
		/// <param name="sectionId">
		///     <para xml:lang="en">The optional target section ID.</para>
		///     <para xml:lang="zh-CN">可选的目标节 ID。</para>
		/// </param>
		/// <param name="entryId">
		///     <para xml:lang="en">The optional target entry ID.</para>
		///     <para xml:lang="zh-CN">可选的目标条目 ID。</para>
		/// </param>
		/// <param name="options">
		///     <para xml:lang="en">Optional navigation presentation behavior.</para>
		///     <para xml:lang="zh-CN">可选的导航呈现行为。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A task whose result describes resolution, host opening, and visible navigation.</para>
		///     <para xml:lang="zh-CN">其结果描述位置解析、宿主打开与可见界面导航的任务。</para>
		/// </returns>
		public static Task<ModSettingsOpenResult> OpenByIdsAsync(string modId, string? pageId = null, string? sectionId = null, string? entryId = null, ModSettingsOpenOptions? options = null)
		{
			return OpenAsync(new ModSettingsLocation(modId, pageId, sectionId, entryId), options);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves and opens a settings location, then waits for the visible UI to finish navigating to it.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         解析并打开设置位置，然后等待可见界面完成导航。
		///     </para>
		/// </summary>
		/// <param name="location">
		///     <para xml:lang="en">The settings location to open.</para>
		///     <para xml:lang="zh-CN">要打开的设置位置。</para>
		/// </param>
		/// <param name="options">
		///     <para xml:lang="en">Optional navigation presentation behavior.</para>
		///     <para xml:lang="zh-CN">可选的导航呈现行为。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A task whose result describes resolution, host opening, and visible navigation.</para>
		///     <para xml:lang="zh-CN">其结果描述位置解析、宿主打开与可见界面导航的任务。</para>
		/// </returns>
		public static async Task<ModSettingsOpenResult> OpenAsync(ModSettingsLocation location, ModSettingsOpenOptions? options = null)
		{
			ArgumentNullException.ThrowIfNull(location, "location");
			ModSettingsOpenResult modSettingsOpenResult = ResolveLocation(Normalize(location));
			if (!modSettingsOpenResult.Success)
			{
				return modSettingsOpenResult;
			}
			ModSettingsLocation location2 = ToResolvedLocation(modSettingsOpenResult);
			if (!TryOpenHost(out RitsuModSettingsSubmenu submenu, out string error))
			{
				return ModSettingsOpenResult.Error("no-settings-host", error, location2);
			}
			return await submenu.OpenToAsync(location2, options ?? new ModSettingsOpenOptions());
		}

		internal static ModSettingsOpenResult ResolveLocation(ModSettingsLocation requested)
		{
			if (string.IsNullOrWhiteSpace(requested.ModId))
			{
				return ModSettingsOpenResult.Error("invalid-location", "A mod id is required.", requested);
			}
			if (string.IsNullOrWhiteSpace(requested.PageId) && (!string.IsNullOrWhiteSpace(requested.SectionId) || !string.IsNullOrWhiteSpace(requested.EntryId)))
			{
				return ModSettingsOpenResult.Error("invalid-location", "A page id is required when opening a section or entry.", requested);
			}
			try
			{
				RitsuLibModSettingsBootstrap.EnsureFrameworkPagesRegistered();
				ModSettingsMirrorRegistrarBootstrap.TryRegisterMirroredPages();
				RitsuLibModSettingsBootstrap.RefreshDynamicPages();
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn($"[Settings] Failed to refresh page registry before navigation: {ex}", 1);
				return ModSettingsOpenResult.Error("registry-refresh-failed", "Settings pages could not be refreshed.", requested);
			}
			ModSettingsPage[] array = (from modSettingsPage in ModSettingsRegistry.GetPages()
				where string.Equals(modSettingsPage.ModId, requested.ModId, StringComparison.OrdinalIgnoreCase)
				select modSettingsPage).Where(IsPageCurrentlyVisible).ToArray();
			if (array.Length == 0)
			{
				return ModSettingsOpenResult.Error("mod-not-found", "No visible settings pages were found for mod '" + requested.ModId + "'.", requested);
			}
			ModSettingsPage page;
			if (string.IsNullOrWhiteSpace(requested.PageId))
			{
				page = array.Where((ModSettingsPage p) => string.IsNullOrWhiteSpace(p.ParentPageId)).OrderBy(ModSettingsRegistry.GetEffectivePageSortOrder).ThenBy<ModSettingsPage, string>((ModSettingsPage p) => p.Id, StringComparer.OrdinalIgnoreCase)
					.FirstOrDefault() ?? array[0];
			}
			else
			{
				page = array.FirstOrDefault((ModSettingsPage p) => string.Equals(p.Id, requested.PageId, StringComparison.OrdinalIgnoreCase));
				if (page == null)
				{
					return ModSettingsOpenResult.Error("page-not-found", $"Settings page '{requested.ModId}:{requested.PageId}' was not found or is hidden here.", requested);
				}
			}
			ModSettingsSection modSettingsSection = null;
			if (!string.IsNullOrWhiteSpace(requested.SectionId))
			{
				modSettingsSection = page.Sections.FirstOrDefault((ModSettingsSection s) => string.Equals(s.Id, requested.SectionId, StringComparison.OrdinalIgnoreCase));
				if (modSettingsSection == null || !IsSectionCurrentlyVisible(page, modSettingsSection))
				{
					return ModSettingsOpenResult.Error("section-not-found", "Settings section '" + requested.SectionId + "' was not found or is hidden.", requested with
					{
						PageId = page.Id
					});
				}
			}
			if (!string.IsNullOrWhiteSpace(requested.EntryId))
			{
				IReadOnlyList<ModSettingsSection> source;
				if (modSettingsSection != null)
				{
					IReadOnlyList<ModSettingsSection> readOnlyList = new <>z__ReadOnlySingleElementList<ModSettingsSection>(modSettingsSection);
					source = readOnlyList;
				}
				else
				{
					source = page.Sections;
				}
				(ModSettingsSection, ModSettingsEntryDefinition)[] array2 = source.Where((ModSettingsSection s) => IsSectionCurrentlyVisible(page, s)).SelectMany((ModSettingsSection s) => from e in s.Entries
					where string.Equals(e.Id, requested.EntryId, StringComparison.OrdinalIgnoreCase)
					select (Section: s, Entry: e)).ToArray();
				int num = array2.Length;
				if (num > 1)
				{
					return ModSettingsOpenResult.Error("entry-ambiguous", "Settings entry '" + requested.EntryId + "' exists in multiple sections; pass a section id.", requested with
					{
						PageId = page.Id
					});
				}
				if (num == 0)
				{
					return ModSettingsOpenResult.Error("entry-not-found", "Settings entry '" + requested.EntryId + "' was not found.", requested with
					{
						PageId = page.Id,
						SectionId = modSettingsSection?.Id
					});
				}
				modSettingsSection = array2[0].Item1;
				if (!IsEntryCurrentlyVisible(page, array2[0].Item2))
				{
					return ModSettingsOpenResult.Error("entry-hidden", "Settings entry '" + requested.EntryId + "' is currently hidden.", requested with
					{
						PageId = page.Id,
						SectionId = modSettingsSection.Id
					});
				}
			}
			ModSettingsLocation location = requested with
			{
				PageId = page.Id,
				SectionId = (modSettingsSection?.Id ?? requested.SectionId)
			};
			return ModSettingsOpenResult.Ok("resolved", "Resolved settings location '" + FormatLocation(location) + "'.", location);
		}

		internal static string FormatLocation(ModSettingsLocation location)
		{
			return string.Join("/", new string[4] { location.ModId, location.PageId, location.SectionId, location.EntryId }.Where((string part) => !string.IsNullOrWhiteSpace(part)));
		}

		private static ModSettingsLocation Normalize(ModSettingsLocation location)
		{
			return new ModSettingsLocation(location.ModId?.Trim() ?? "", NormalizeOptional(location.PageId), NormalizeOptional(location.SectionId), NormalizeOptional(location.EntryId));
		}

		private static string? NormalizeOptional(string? value)
		{
			if (!string.IsNullOrWhiteSpace(value))
			{
				return value.Trim();
			}
			return null;
		}

		private static ModSettingsLocation ToResolvedLocation(ModSettingsOpenResult result)
		{
			return new ModSettingsLocation(result.ModId, result.PageId, result.SectionId, result.EntryId);
		}

		private static bool TryOpenHost(out RitsuModSettingsSubmenu submenu, out string error)
		{
			return RitsuOverlayHostService.TryOpenSettings(out submenu, out error);
		}

		private static bool IsPageCurrentlyVisible(ModSettingsPage page)
		{
			return ModSettingsVisibility.IsPageVisible(page);
		}

		private static bool IsSectionCurrentlyVisible(ModSettingsPage page, ModSettingsSection section)
		{
			return ModSettingsVisibility.IsSectionVisible(page, section);
		}

		private static bool IsEntryCurrentlyVisible(ModSettingsPage page, ModSettingsEntryDefinition entry)
		{
			return ModSettingsVisibility.IsEntryVisible(page, entry);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Specifies the standard context-menu actions exposed for pages, sections, and entries.</para>
	///     <para xml:lang="zh-CN">指定页面、节及条目所公开的标准上下文菜单操作。</para>
	/// </summary>
	[Flags]
	public enum ModSettingsMenuCapabilities
	{
		/// <summary>
		///     <para xml:lang="en">Exposes no standard context-menu actions.</para>
		///     <para xml:lang="zh-CN">不公开任何标准上下文菜单操作。</para>
		/// </summary>
		None = 0,
		/// <summary>
		///     <para xml:lang="en">Allows copying the current value or supported subtree.</para>
		///     <para xml:lang="zh-CN">允许复制当前值或其支持的子树。</para>
		/// </summary>
		Copy = 1,
		/// <summary>
		///     <para xml:lang="en">Allows pasting compatible clipboard content.</para>
		///     <para xml:lang="zh-CN">允许粘贴兼容的剪贴板内容。</para>
		/// </summary>
		Paste = 2,
		/// <summary>
		///     <para xml:lang="en">Allows explicitly resetting supported values to their defaults.</para>
		///     <para xml:lang="zh-CN">允许将支持的值显式重置为默认值。</para>
		/// </summary>
		ResetToDefault = 4,
		/// <summary>
		///     <para xml:lang="en">Exposes all standard context-menu actions.</para>
		///     <para xml:lang="zh-CN">公开所有标准上下文菜单操作。</para>
		/// </summary>
		All = Copy | Paste | ResetToDefault
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Represents one immutable settings page definition, including its sidebar metadata, hierarchy,
	///         availability, host-surface behavior, and ordered sections.
	///     </para>
	///     <para xml:lang="zh-CN">表示不可变的设置页面定义，包括侧边栏元数据、页面层级、可用状态、宿主界面行为及有序节。</para>
	/// </summary>
	public sealed class ModSettingsPage
	{
		/// <summary>
		///     <para xml:lang="en">Gets the owning mod ID.</para>
		///     <para xml:lang="zh-CN">获取所属模组 ID。</para>
		/// </summary>
		public string ModId { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the stable page ID within the mod.</para>
		///     <para xml:lang="zh-CN">获取页面在模组内的稳定 ID。</para>
		/// </summary>
		public string Id { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional parent page ID; root pages have no parent.</para>
		///     <para xml:lang="zh-CN">获取可选的父页面 ID；根页面没有父页面。</para>
		/// </summary>
		public string? ParentPageId { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional localized page title displayed by the settings UI.</para>
		///     <para xml:lang="zh-CN">获取设置界面显示的可选本地化页面标题。</para>
		/// </summary>
		public ModSettingsText? Title { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional localized page description shown above its sections.</para>
		///     <para xml:lang="zh-CN">获取在页面各节上方显示的可选本地化页面说明。</para>
