		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether the sidebar may use <see cref="P:STS2RitsuLib.Settings.ModSettingsPage.SourceAssembly" /> to locate ModManager presentation
		///         metadata.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取侧边栏是否可以通过 <see cref="P:STS2RitsuLib.Settings.ModSettingsPage.SourceAssembly" /> 查找 ModManager 展示元数据。
		///     </para>
		/// </summary>
		public bool UseSourceAssemblyManifestLookup { get; }

		internal ModSettingsPage(string modId, string id, string? parentPageId, ModSettingsText? title, ModSettingsText? description, int sortOrder, IReadOnlyList<ModSettingsSection> sections, Func<bool>? visibleWhen = null, Func<bool>? enabledWhen = null, ModSettingsMenuCapabilities menuCapabilities = ModSettingsMenuCapabilities.All, ModSettingsHostSurface visibleOnHostSurfaces = ModSettingsHostSurface.All, ModSettingsHostSurface readOnlyOnHostSurfaces = ModSettingsHostSurface.None, bool sidebarVisibleOnlyWhenActive = false, bool hideDescription = false, Assembly? sourceAssembly = null, bool useSourceAssemblyManifestLookup = true)
		{
			ModId = modId;
			Id = id;
			ParentPageId = parentPageId;
			Title = title;
			Description = description;
			SortOrder = sortOrder;
			Sections = Array.AsReadOnly((sections ?? throw new ArgumentNullException("sections")).ToArray());
			VisibleWhen = visibleWhen;
			EnabledWhen = enabledWhen;
			MenuCapabilities = menuCapabilities;
			VisibleOnHostSurfaces = visibleOnHostSurfaces;
			ReadOnlyOnHostSurfaces = readOnlyOnHostSurfaces;
			SidebarVisibleOnlyWhenActive = sidebarVisibleOnlyWhenActive;
			HideDescription = hideDescription;
			SourceAssembly = sourceAssembly;
			UseSourceAssemblyManifestLookup = useSourceAssemblyManifestLookup;
		}
	}
