		internal ModSettingsSection(string id, ModSettingsText? title, ModSettingsText? description, bool isCollapsible, bool startCollapsed, IReadOnlyList<ModSettingsEntryDefinition> entries, Func<bool>? visibleWhen = null, Func<bool>? enabledWhen = null, ModSettingsMenuCapabilities menuCapabilities = ModSettingsMenuCapabilities.All, ModSettingsHostSurface visibleOnHostSurfaces = ModSettingsHostSurface.All, ModSettingsHostSurface readOnlyOnHostSurfaces = ModSettingsHostSurface.None)
