	internal static class ModSettingsPredicate
	{
		internal static bool Evaluate(Func<bool>? predicate)
		{
			if (predicate == null)
			{
				return true;
			}
			try
			{
				return predicate();
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				MethodInfo method = predicate.Method;
				string value = (method.DeclaringType?.FullName ?? "<unknown>") + "." + method.Name;
				RitsuLibFramework.Logger.Warn($"[Settings] Predicate '{value}' failed and was treated as false: {ex}", 1);
				return false;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Pairs one choice or enum value with its display text.</para>
	///     <para xml:lang="zh-CN">将一个选项或枚举值与其显示文本配对。</para>
	/// </summary>
	/// <typeparam name="TValue">
	///     <para xml:lang="en">The option value type.</para>
	///     <para xml:lang="zh-CN">选项值类型。</para>
	/// </typeparam>
	/// <param name="Value">
	///     <para xml:lang="en">The value written to the binding when selected.</para>
	///     <para xml:lang="zh-CN">选中时写入绑定的值。</para>
	/// </param>
	/// <param name="Label">
	///     <para xml:lang="en">The text displayed for the option.</para>
	///     <para xml:lang="zh-CN">为选项显示的文本。</para>
	/// </param>
	public readonly record struct ModSettingsChoiceOption<TValue>(TValue Value, ModSettingsText Label);
	/// <summary>
	///     <para xml:lang="en">
	///         Specifies how a setting with multiple choices is rendered in the value column.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         指定具有多个候选项的设置在值列中的呈现方式。
	///     </para>
	/// </summary>
	public enum ModSettingsChoicePresentation
	{
		/// <summary>
		///     <para xml:lang="en">A left/right stepper with a centered label.</para>
		///     <para xml:lang="zh-CN">标签居中的左右步进器。</para>
		/// </summary>
		Stepper,
		/// <summary>
		///     <para xml:lang="en">A drop-down list.</para>
		///     <para xml:lang="zh-CN">下拉列表。</para>
		/// </summary>
		Dropdown
	}
	/// <summary>
	///     <para xml:lang="en">Specifies the semantic visual tone of a settings action button.</para>
	///     <para xml:lang="zh-CN">指定设置操作按钮的语义视觉色调。</para>
	/// </summary>
	public enum ModSettingsButtonTone
	{
		/// <summary>
		///     <para xml:lang="en">A neutral visual style.</para>
		///     <para xml:lang="zh-CN">中性视觉样式。</para>
		/// </summary>
		Normal,
		/// <summary>
		///     <para xml:lang="en">Primary or positive emphasis.</para>
		///     <para xml:lang="zh-CN">主要或正向强调。</para>
		/// </summary>
		Accent,
		/// <summary>
		///     <para xml:lang="en">Destructive or high-attention emphasis.</para>
		///     <para xml:lang="zh-CN">破坏性或需要高度注意的强调。</para>
		/// </summary>
		Danger
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Stores mod settings pages together with optional mod display names, mod-group sidebar orders, and page
	///         sort-order overrides.
	///     </para>
	///     <para xml:lang="zh-CN">存储模组设置页面，以及可选的模组显示名称、模组分组侧边栏排序和页面排序覆盖值。</para>
	/// </summary>
	public static class ModSettingsRegistry
	{
		private static readonly Dictionary<string, ModSettingsText> ModDisplayNames = new Dictionary<string, ModSettingsText>(StringComparer.OrdinalIgnoreCase);

		/// <summary>
		///     <para xml:lang="en">
		///         Stores the optional sidebar group order for each mod. Lower values appear first; unregistered mods
		///         use zero.
		///     </para>
		///     <para xml:lang="zh-CN">存储各模组可选的侧边栏分组排序；数值较小的分组排在前面，未注册的模组使用零。</para>
		/// </summary>
		private static readonly Dictionary<string, int> ModSidebarOrders = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

		/// <summary>
		///     <para xml:lang="en">Stores page sort-order overrides by composite mod and page ID.</para>
		///     <para xml:lang="zh-CN">按模组 ID 与页面 ID 的复合键存储页面排序覆盖值。</para>
		/// </summary>
		private static readonly Dictionary<string, int> PageSortOverrides = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, ModSettingsPage> PagesById = new Dictionary<string, ModSettingsPage>(StringComparer.OrdinalIgnoreCase);

		/// <summary>
		///     <para xml:lang="en">
		///         Caches the fully ordered <see cref="M:STS2RitsuLib.Settings.ModSettingsRegistry.GetPages" /> snapshot until page registration, display-name
		///         fallback, or an ordering input changes.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         缓存完全排序后的 <see cref="M:STS2RitsuLib.Settings.ModSettingsRegistry.GetPages" /> 快照，直至页面注册、显示名称回退或排序输入发生变化。
		///     </para>
		/// </summary>
		private static IReadOnlyList<ModSettingsPage>? _sortedPagesCache;

		/// <summary>
		///     <para xml:lang="en">Gets whether at least one page is currently registered.</para>
		///     <para xml:lang="zh-CN">获取当前是否至少注册了一个页面。</para>
		/// </summary>
		public static bool HasPages
		{
			get
			{
				using (SyncRoot.EnterScope())
				{
					return PagesById.Count > 0;
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds or replaces a built page using its composite mod and page ID.
		///     </para>
		///     <para xml:lang="zh-CN">按页面的模组 ID 与页面 ID 复合键添加或替换已构建页面。</para>
		/// </summary>
		public static void Register(ModSettingsPage page)
		{
			ArgumentNullException.ThrowIfNull(page, "page");
			using (SyncRoot.EnterScope())
			{
				PagesById[CreateCompositeId(page.ModId, page.Id)] = page;
				_sortedPagesCache = null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Invalidates the ordered page snapshot so the next <see cref="M:STS2RitsuLib.Settings.ModSettingsRegistry.GetPages" /> call rebuilds it. Use this
		///         when an external display-name fallback or other ordering input changes.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使有序页面快照失效，以便下一次 <see cref="M:STS2RitsuLib.Settings.ModSettingsRegistry.GetPages" /> 调用重新构建；外部显示名称回退或其他排序输入变化时使用。
		///     </para>
		/// </summary>
		public static void InvalidateOrderingCache()
		{
			using (SyncRoot.EnterScope())
			{
				_sortedPagesCache = null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds or replaces the localized or literal display text for <paramref name="modId" />.
		///     </para>
		///     <para xml:lang="zh-CN">添加或替换 <paramref name="modId" /> 的本地化或字面显示文本。</para>
		/// </summary>
		public static void RegisterModDisplayName(string modId, ModSettingsText displayName)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentNullException.ThrowIfNull(displayName, "displayName");
			using (SyncRoot.EnterScope())
			{
				ModDisplayNames[modId] = displayName;
				_sortedPagesCache = null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets the registered display text for <paramref name="modId" />, if any.</para>
		///     <para xml:lang="zh-CN">获取 <paramref name="modId" /> 已注册的显示文本（如有）。</para>
		/// </summary>
		public static ModSettingsText? GetModDisplayName(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (SyncRoot.EnterScope())
			{
				return ModDisplayNames.GetValueOrDefault(modId);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds or replaces the sidebar group order for <paramref name="modId" />. Lower values appear first;
		///         unregistered mods use zero.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         添加或替换 <paramref name="modId" /> 的侧边栏分组排序值；数值较小的分组排在前面，未注册的模组使用零。
		///     </para>
		/// </summary>
		public static void RegisterModSidebarOrder(string modId, int order)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (SyncRoot.EnterScope())
			{
				ModSidebarOrders[modId] = order;
				_sortedPagesCache = null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds or replaces a page sort-order override. The override may be registered before or after the page;
		///         lower values place sibling pages earlier.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         添加或替换页面排序覆盖值；可在页面注册前或注册后设置，数值较小的同级页面排在前面。
		///     </para>
		/// </summary>
		public static void RegisterPageSortOrder(string modId, string pageId, int sortOrder)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(pageId, "pageId");
			using (SyncRoot.EnterScope())
			{
				PageSortOverrides[CreateCompositeId(modId, pageId)] = sortOrder;
				_sortedPagesCache = null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets <paramref name="pageId" />'s effective order to the positive <paramref name="gap" /> immediately
		///         after <paramref name="afterPageId" /> in the same mod.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将同一模组中 <paramref name="pageId" /> 的有效排序设为紧随 <paramref name="afterPageId" />
		///         之后的正数 <paramref name="gap" />。
		///     </para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when <paramref name="afterPageId" /> is registered; otherwise
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         <paramref name="afterPageId" /> 已注册时为 <see langword="true" />，否则为
		///         <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool TryRegisterPageSortOrderAfter(string modId, string pageId, string afterPageId, int gap = 1)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(pageId, "pageId");
			ArgumentException.ThrowIfNullOrWhiteSpace(afterPageId, "afterPageId");
			if (gap <= 0)
			{
				throw new ArgumentOutOfRangeException("gap", "Page sort-order gap must be greater than zero.");
			}
			using (SyncRoot.EnterScope())
			{
				if (!PagesById.TryGetValue(CreateCompositeId(modId, afterPageId), out ModSettingsPage value))
				{
					return false;
				}
				int valueOrDefault = PageSortOverrides.GetValueOrDefault(CreateCompositeId(modId, afterPageId), value.SortOrder);
				PageSortOverrides[CreateCompositeId(modId, pageId)] = checked(valueOrDefault + gap);
				_sortedPagesCache = null;
				return true;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets <paramref name="pageId" />'s effective order to the positive <paramref name="gap" /> immediately
		///         before <paramref name="beforePageId" /> in the same mod.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将同一模组中 <paramref name="pageId" /> 的有效排序设为紧邻 <paramref name="beforePageId" />
		///         之前的正数 <paramref name="gap" />。
		///     </para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when <paramref name="beforePageId" /> is registered; otherwise
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         <paramref name="beforePageId" /> 已注册时为 <see langword="true" />，否则为
		///         <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool TryRegisterPageSortOrderBefore(string modId, string pageId, string beforePageId, int gap = 1)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(pageId, "pageId");
			ArgumentException.ThrowIfNullOrWhiteSpace(beforePageId, "beforePageId");
			if (gap <= 0)
			{
				throw new ArgumentOutOfRangeException("gap", "Page sort-order gap must be greater than zero.");
			}
			using (SyncRoot.EnterScope())
			{
				if (!PagesById.TryGetValue(CreateCompositeId(modId, beforePageId), out ModSettingsPage value))
				{
					return false;
				}
				int valueOrDefault = PageSortOverrides.GetValueOrDefault(CreateCompositeId(modId, beforePageId), value.SortOrder);
				PageSortOverrides[CreateCompositeId(modId, pageId)] = checked(valueOrDefault - gap);
				_sortedPagesCache = null;
				return true;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets the sidebar group order for <paramref name="modId" />, or zero when unset.</para>
		///     <para xml:lang="zh-CN">获取 <paramref name="modId" /> 的侧边栏分组排序值；未设置时为零。</para>
		/// </summary>
		public static int GetModSidebarOrder(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (SyncRoot.EnterScope())
			{
				return ModSidebarOrders.GetValueOrDefault(modId, 0);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the registered override for <paramref name="page" />, or its
		///         <see cref="P:STS2RitsuLib.Settings.ModSettingsPage.SortOrder" /> when no override exists.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 <paramref name="page" /> 已注册的排序覆盖值；没有覆盖值时返回
		///         <see cref="P:STS2RitsuLib.Settings.ModSettingsPage.SortOrder" />。
		///     </para>
		/// </summary>
		public static int GetEffectivePageSortOrder(ModSettingsPage page)
		{
			ArgumentNullException.ThrowIfNull(page, "page");
			using (SyncRoot.EnterScope())
			{
				return PageSortOverrides.GetValueOrDefault(CreateCompositeId(page.ModId, page.Id), page.SortOrder);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Builds a page through <paramref name="configure" /> and registers the result.</para>
		///     <para xml:lang="zh-CN">通过 <paramref name="configure" /> 构建页面并注册结果。</para>
		/// </summary>
		public static void Register(string modId, Action<ModSettingsPageBuilder> configure, string? pageId = null)
		{
			RegisterCore(modId, configure, pageId, null);
		}

		internal static void RegisterWithSourceAssembly(string modId, Action<ModSettingsPageBuilder> configure, string? pageId, Assembly? sourceAssembly)
		{
			RegisterCore(modId, configure, pageId, sourceAssembly);
		}

		private static void RegisterCore(string modId, Action<ModSettingsPageBuilder> configure, string? pageId, Assembly? sourceAssembly)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentNullException.ThrowIfNull(configure, "configure");
			ModSettingsPageBuilder modSettingsPageBuilder = new ModSettingsPageBuilder(modId, pageId, sourceAssembly);
			configure(modSettingsPageBuilder);
			Register(modSettingsPageBuilder.Build());
		}

		/// <summary>
		///     <para xml:lang="en">Looks up a page by mod ID and page ID, case-insensitively.</para>
		///     <para xml:lang="zh-CN">按模组 ID 与页面 ID 查找页面，不区分大小写。</para>
		/// </summary>
		public static bool TryGetPage(string modId, string pageId, out ModSettingsPage? page)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(pageId, "pageId");
			using (SyncRoot.EnterScope())
			{
				return PagesById.TryGetValue(CreateCompositeId(modId, pageId), out page);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets a cached immutable snapshot of all registered pages, ordered by mod-group order, mod display-name
		///         fallback, mod ID, effective page order, and page ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取所有已注册页面的缓存不可变快照，依次按模组分组排序、模组显示名称回退、模组 ID、页面有效排序及页面 ID 排列。
		///     </para>
		/// </summary>
		public static IReadOnlyList<ModSettingsPage> GetPages()
		{
			using (SyncRoot.EnterScope())
			{
				return _sortedPagesCache ?? (_sortedPagesCache = Array.AsReadOnly(PagesById.Values.OrderBy((ModSettingsPage page) => ModSidebarOrders.GetValueOrDefault(page.ModId, 0)).ThenBy<ModSettingsPage, string>((ModSettingsPage page) => ModSettingsLocalization.ResolveModNameFallback(page.ModId, page.ModId), StringComparer.OrdinalIgnoreCase).ThenBy<ModSettingsPage, string>((ModSettingsPage page) => page.ModId, StringComparer.OrdinalIgnoreCase)
					.ThenBy((ModSettingsPage page) => PageSortOverrides.GetValueOrDefault(CreateCompositeId(page.ModId, page.Id), page.SortOrder))
					.ThenBy<ModSettingsPage, string>((ModSettingsPage page) => page.Id, StringComparer.OrdinalIgnoreCase)
					.ToArray()));
			}
		}

		private static string CreateCompositeId(string modId, string pageId)
		{
			return modId + "::" + pageId;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides optional global presentation overrides for the RitsuLib mod settings screen. These values may be
	///         configured during mod loading.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供 RitsuLib 模组设置屏幕的可选全局呈现覆盖项，可在模组加载期间配置。
	///     </para>
	/// </summary>
	public static class ModSettingsUiPresentation
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets or sets the default maximum body height for paragraph entries and info cards before they use
		///         internal vertical scrolling. Only positive finite values impose a limit; <see langword="null" />,
		///         zero, negative, and non-finite values leave the height unrestricted. For paragraph entries, an
		///         entry-specific <see cref="P:STS2RitsuLib.Settings.ParagraphModSettingsEntryDefinition.MaxBodyHeight" /> takes precedence.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或设置段落条目与信息卡在启用内部垂直滚动前的默认正文最大高度。只有有限正值会施加限制；
		///         <see langword="null" />、零、负值与非有限值均表示不限制高度。对于段落条目，其自身的
		///         <see cref="P:STS2RitsuLib.Settings.ParagraphModSettingsEntryDefinition.MaxBodyHeight" /> 设置具有更高优先级。
		///     </para>
		/// </summary>
		public static float? ParagraphMaxBodyHeight { get; set; }
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Classifies how a setting value relates to persistence and run state. The settings UI uses this metadata
	///         for scope badges.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         对设置值与持久化及对局状态之间的关系进行分类。设置界面使用此元数据显示作用域徽标。
	///     </para>
	/// </summary>
	public enum ModSettingsValueSemantics
	{
		/// <summary>
		///     <para xml:lang="en">A normal global or profile JSON data-store binding.</para>
		///     <para xml:lang="zh-CN">普通的全局或档案 JSON 数据存储绑定。</para>
		/// </summary>
		Standard,
		/// <summary>
		///     <para xml:lang="en">
		///         A value owned by the current run that the mod is responsible for including in run save data.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         属于当前对局的值，模组负责将其写入对局存档数据。
		///     </para>
		/// </summary>
		RunSnapshot,
		/// <summary>
		///     <para xml:lang="en">
		///         A value limited to the current combat or session and not intended for global or profile storage.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         仅限当前战斗或会话的值，不用于全局或档案存储。
		///     </para>
		/// </summary>
		SessionCombat
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Optionally supplies semantic metadata for an <see cref="T:STS2RitsuLib.Settings.IModSettingsBinding" /> so the settings UI can
	///         refine its scope badge.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         可选地为 <see cref="T:STS2RitsuLib.Settings.IModSettingsBinding" /> 提供语义元数据，使设置界面能够细化其作用域徽标。
	///     </para>
	/// </summary>
	public interface IModSettingsBindingSemantics
	{
		/// <summary>
		///     <para xml:lang="en">Gets the semantic classification displayed by the settings UI.</para>
		///     <para xml:lang="zh-CN">获取设置界面显示的语义分类。</para>
		/// </summary>
		ModSettingsValueSemantics Semantics { get; }
	}
	internal static class ModSettingsVisibility
	{
		internal static bool IsPageVisible(ModSettingsPage page)
		{
			return IsPageVisible(page, new HashSet<string>());
		}

		internal static bool IsSectionVisible(ModSettingsPage page, ModSettingsSection section)
		{
			return IsSectionVisible(page, section, new HashSet<string>());
		}

		internal static bool IsEntryVisible(ModSettingsPage page, ModSettingsEntryDefinition entry)
		{
			return IsEntryVisible(page, entry, new HashSet<string>());
		}

		internal static Func<bool>? CreateSectionVisibilityPredicate(ModSettingsPage page, ModSettingsSection section)
		{
			if (section != null && section.VisibleWhen == null && section.VisibleOnHostSurfaces == ModSettingsHostSurface.All)
			{
				IReadOnlyList<ModSettingsEntryDefinition> entries = section.Entries;
				if (entries != null && entries.Count > 0 && section.Entries.All((ModSettingsEntryDefinition entry) => !RequiresDynamicEvaluation(entry)))
				{
					return null;
				}
			}
			return () => IsSectionVisible(page, section);
		}

		private static bool IsPageVisible(ModSettingsPage page, HashSet<string> visitingPages)
		{
			string item = CreatePageKey(page.ModId, page.Id);
			if (!visitingPages.Add(item))
			{
				return true;
			}
			try
			{
				return ModSettingsHostSurfaceResolver.IsVisibleOnCurrentHost(page.VisibleOnHostSurfaces) && ModSettingsPredicate.Evaluate(page.VisibleWhen) && page.Sections.Any((ModSettingsSection section) => IsSectionVisible(page, section, visitingPages));
			}
			finally
			{
				visitingPages.Remove(item);
			}
		}

		private static bool IsSectionVisible(ModSettingsPage page, ModSettingsSection section, HashSet<string> visitingPages)
		{
			if (ModSettingsHostSurfaceResolver.IsVisibleOnCurrentHost(section.VisibleOnHostSurfaces) && ModSettingsPredicate.Evaluate(section.VisibleWhen))
			{
				return section.Entries.Any((ModSettingsEntryDefinition entry) => IsEntryVisible(page, entry, visitingPages));
			}
			return false;
		}

		private static bool IsEntryVisible(ModSettingsPage page, ModSettingsEntryDefinition entry, HashSet<string> visitingPages)
		{
