					RitsuModSettingsSubmenu ritsuModSettingsSubmenu = ModSettingsMirrorUiActions.FindRitsuModSettingsSubmenu((Node)(object)root);
					ModSettingsUiFactory.ShowStyledNotice((Node)(object)((ritsuModSettingsSubmenu != null) ? ritsuModSettingsSubmenu : ((RitsuModSettingsSubmenu)(object)root)), title, body, InvokeJmcUiText("Close") ?? "Close");
				}
			}
		}

