		private static string? InvokeConfigLocalization(string methodName, object?[] args)
		{
			try
			{
				IEnumerable<MethodInfo> enumerable = ExternalFrameworkRegistry.ResolveType("JmcModLib.Config.ConfigLocalization")?.GetMethods(BindingFlags.Static | BindingFlags.Public).Where((MethodInfo method) => method.Name == methodName && method.GetParameters().Length == args.Length);
				if (enumerable == null)
				{
					return null;
				}
				foreach (MethodInfo item in enumerable)
				{
					object[] array = CoerceLocalizationArgs(item, args);
					if (array != null)
					{
						return item.Invoke(null, array)?.ToString();
					}
				}
				return null;
			}
			catch
			{
				return null;
			}
		}

		private static string? InvokeJmcUiText(string methodName, params object?[] args)
		{
			try
			{
				return (ExternalFrameworkRegistry.ResolveType("JmcModLib.Config.UI.ModSettingsText")?.GetMethods(BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic).FirstOrDefault((MethodInfo candidate) => candidate.Name == methodName && candidate.GetParameters().Length == args.Length))?.Invoke(null, args)?.ToString();
			}
			catch
			{
				return null;
			}
		}

		private static object?[]? CoerceLocalizationArgs(MethodInfo method, object?[] args)
		{
			ParameterInfo[] parameters = method.GetParameters();
			object[] array = new object[args.Length];
			for (int i = 0; i < args.Length; i++)
			{
				object obj = args[i];
				Type parameterType = parameters[i].ParameterType;
				if (obj == null || parameterType.IsInstanceOfType(obj))
				{
					array[i] = obj;
					continue;
				}
				if (obj is IEnumerable<object> source && parameterType.IsGenericType)
				{
					Type[] genericArguments = parameterType.GetGenericArguments();
					if (genericArguments != null && genericArguments.Length == 1)
					{
						Type itemType = genericArguments[0];
						if ((object)itemType != null && !(parameterType.GetGenericTypeDefinition() != typeof(IReadOnlyCollection<>)))
						{
							object[] array2 = source.Where((object item) => itemType.IsInstanceOfType(item)).ToArray();
							Array array3 = Array.CreateInstance(itemType, array2.Length);
							for (int num = 0; num < array2.Length; num++)
							{
								array3.SetValue(array2[num], num);
							}
							array[i] = array3;
							continue;
						}
					}
				}
				return null;
			}
			return array;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Configures how ModConfig key binding entries are mirrored into RitsuLib settings.</para>
	///     <para xml:lang="zh-CN">配置如何将 ModConfig 的按键绑定条目镜像到 RitsuLib 设置。</para>
	/// </summary>
	public sealed class ModConfigMirrorRegistrationOptions
	{
		/// <summary>
		///     <para xml:lang="en">Gets the shared default option set.</para>
		///     <para xml:lang="zh-CN">获取共享的默认选项集。</para>
		/// </summary>
		public static ModConfigMirrorRegistrationOptions Default { get; } = new ModConfigMirrorRegistrationOptions();

		/// <summary>
		///     <para xml:lang="en">Gets whether mirrored key bindings allow modifier-and-key combinations.</para>
		///     <para xml:lang="zh-CN">获取镜像按键绑定是否允许修饰键与普通按键的组合。</para>
		/// </summary>
		public bool KeyBindAllowModifierCombos { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets whether mirrored key bindings allow a modifier key by itself.</para>
		///     <para xml:lang="zh-CN">获取镜像按键绑定是否允许单独使用修饰键。</para>
		/// </summary>
		public bool KeyBindAllowModifierOnly { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets whether mirrored key bindings distinguish left and right modifier keys.</para>
		///     <para xml:lang="zh-CN">获取镜像按键绑定是否区分左侧与右侧修饰键。</para>
		/// </summary>
		public bool KeyBindDistinguishModifierSides { get; init; }
	}
	internal static class ModConfigMirrorSource
	{
		private sealed class ModConfigMirrorSectionPlan(string id, ModSettingsText? title)
		{
			public string Id { get; } = id;

			public ModSettingsText? Title { get; set; } = title;

			public List<ModConfigMappedEntry> Entries { get; } = new List<ModConfigMappedEntry>();
		}

		private readonly record struct ModConfigMappedEntry(object Entry, int SourceIndex);

		private const string ApiTypeName = "ModConfig.ModConfigApi";

		private const string ManagerTypeName = "ModConfig.ModConfigManager";

		private const string I18NTypeName = "ModConfig.I18n";

		private static readonly Lock Gate = new Lock();

		private static Type? _cachedApiType;

		private static MethodInfo? _cachedGetValueOpen;

		private static MethodInfo? _cachedSetValue;

		private static MethodInfo? _cachedResetDefaults;

		private static MethodInfo? _cachedI18NGet;

		private static PropertyInfo? _cachedRegistrationsProp;

		public static bool IsModConfigPresent => ResolveType("ModConfig.ModConfigApi") != null;

		public static int TryRegisterMirroredPages(string pageId = "modconfig", int sortOrder = 10020, ModSettingsText? pageTitle = null)
		{
			return TryRegisterMirroredPages(pageId, sortOrder, pageTitle, null);
		}

		public static int TryRegisterMirroredPages(string pageId, int sortOrder, ModSettingsText? pageTitle, ModConfigMirrorRegistrationOptions? options)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(pageId, "pageId");
			ModConfigMirrorRegistrationOptions mirrorOptions = options ?? ModConfigMirrorRegistrationOptions.Default;
			using (Gate.EnterScope())
			{
				if (!TryResolveInterop(out Type _, out MethodInfo getValueOpen, out MethodInfo setValue, out MethodInfo resetDefaults, out PropertyInfo registrationsProp, out MethodInfo i18NGet))
				{
					return 0;
				}
				if (!(registrationsProp.GetValue(null) is IEnumerable enumerable))
				{
					return 0;
				}
				ModSettingsText pageDescription = ModSettingsLocalization.Text("modconfig.mirroredPage.description", "This page mirrors ModConfig-registered settings into the RitsuLib settings UI.");
				int num = 0;
				foreach (object item in enumerable)
				{
					if (TryUnwrapDictionaryItem(item, out string modId, out object reg) && ModSettingsMirrorInteropPolicy.ShouldMirror(ModSettingsMirrorSource.ModConfig, modId) && !ModSettingsRegistry.TryGetPage(modId, pageId, out ModSettingsPage _) && TryRegisterOneMod(modId, pageId, sortOrder, pageTitle, pageDescription, reg, getValueOpen, setValue, resetDefaults, i18NGet, mirrorOptions))
					{
						num++;
					}
				}
				return num;
			}
		}

		public static void ClearModConfigReflectionCache()
		{
			using (Gate.EnterScope())
			{
				_cachedApiType = null;
				_cachedGetValueOpen = null;
				_cachedSetValue = null;
				_cachedResetDefaults = null;
				_cachedRegistrationsProp = null;
				_cachedI18NGet = null;
			}
		}

		private static bool TryResolveInterop(out Type apiType, out MethodInfo getValueOpen, out MethodInfo setValue, out MethodInfo resetDefaults, out PropertyInfo registrationsProp, out MethodInfo? i18NGet)
		{
			if (_cachedApiType != null && _cachedGetValueOpen != null && _cachedSetValue != null && _cachedResetDefaults != null && _cachedRegistrationsProp != null)
			{
				apiType = _cachedApiType;
				getValueOpen = _cachedGetValueOpen;
				setValue = _cachedSetValue;
				resetDefaults = _cachedResetDefaults;
				registrationsProp = _cachedRegistrationsProp;
				i18NGet = _cachedI18NGet;
				return true;
			}
			Type type = ResolveType("ModConfig.ModConfigApi");
			if (type == null)
			{
				apiType = null;
				getValueOpen = null;
				setValue = null;
				resetDefaults = null;
				registrationsProp = null;
				i18NGet = null;
				return false;
			}
			apiType = type;
			Assembly assembly = apiType.Assembly;
			MethodInfo methodInfo = apiType.GetMethods(BindingFlags.Static | BindingFlags.Public).FirstOrDefault(delegate(MethodInfo m)
			{
				if ((object)m != null && m.Name == "GetValue" && m.IsGenericMethodDefinition)
				{
					ParameterInfo[] parameters = m.GetParameters();
					if (parameters != null && parameters.Length == 2)
					{
						ParameterInfo parameterInfo = parameters[0];
						if (parameterInfo != null)
						{
							Type parameterType = parameterInfo.ParameterType;
							ParameterInfo parameterInfo2 = parameters[1];
							if (parameterInfo2 != null)
							{
								Type parameterType2 = parameterInfo2.ParameterType;
								if (parameterType == typeof(string))
								{
									return parameterType2 == typeof(string);
								}
							}
						}
					}
				}
				return false;
			});
			MethodInfo method = apiType.GetMethod("SetValue", BindingFlags.Static | BindingFlags.Public, null, new Type[3]
			{
				typeof(string),
				typeof(string),
				typeof(object)
			}, null);
			Type type2 = assembly.GetType("ModConfig.ModConfigManager");
			MethodInfo methodInfo2 = type2?.GetMethod("ResetToDefaults", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, null, new Type[1] { typeof(string) }, null);
			PropertyInfo propertyInfo = type2?.GetProperty("Registrations", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			if (methodInfo == null || method == null || methodInfo2 == null || propertyInfo == null)
			{
				getValueOpen = null;
				setValue = null;
				resetDefaults = null;
				registrationsProp = null;
				i18NGet = null;
				return false;
			}
			getValueOpen = methodInfo;
			setValue = method;
			resetDefaults = methodInfo2;
			registrationsProp = propertyInfo;
			i18NGet = assembly.GetType("ModConfig.I18n")?.GetMethod("Get", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, null, new Type[2]
			{
				typeof(string),
				typeof(string)
			}, null);
			_cachedApiType = apiType;
			_cachedGetValueOpen = getValueOpen;
			_cachedSetValue = setValue;
			_cachedResetDefaults = resetDefaults;
			_cachedRegistrationsProp = registrationsProp;
			_cachedI18NGet = i18NGet;
			return true;
		}

		private static bool TryUnwrapDictionaryItem(object item, out string modId, out object reg)
		{
			modId = "";
			reg = null;
			if (item is DictionaryEntry dictionaryEntry)
			{
				if (!(dictionaryEntry.Key is string text) || string.IsNullOrWhiteSpace(text) || dictionaryEntry.Value == null)
				{
					return false;
				}
				modId = text;
				reg = dictionaryEntry.Value;
			}
			else
			{
				Type type = item.GetType();
				if (!type.IsGenericType || !type.Name.StartsWith("KeyValuePair`", StringComparison.Ordinal))
				{
					return false;
				}
				string text2 = type.GetProperty("Key")?.GetValue(item) as string;
				object obj = type.GetProperty("Value")?.GetValue(item);
				if (string.IsNullOrWhiteSpace(text2) || obj == null)
				{
					return false;
				}
				modId = text2;
				reg = obj;
			}
			return true;
		}

		private static bool TryRegisterOneMod(string modId, string pageId, int sortOrder, ModSettingsText? pageTitle, ModSettingsText? pageDescription, object registration, MethodInfo getValueOpen, MethodInfo setValue, MethodInfo resetDefaults, MethodInfo? i18NGet, ModConfigMirrorRegistrationOptions mirrorOptions)
		{
			if (!(registration.GetType().GetProperty("Entries")?.GetValue(registration) is Array { Length: not 0 } array))
			{
				return false;
			}
			List<ModConfigMirrorSectionPlan> sectionPlans = BuildMirroredSectionPlans(array, i18NGet);
			if (sectionPlans.Count == 0)
			{
				return false;
			}
			bool flag = false;
			for (int i = 0; i < array.Length; i++)
			{
				object value = array.GetValue(i);
				if (value != null && IsRenderableConfigEntry(value))
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				return false;
			}
			try
			{
				ModSettingsRegistry.Register(modId, delegate(ModSettingsPageBuilder builder)
				{
					ModSettingsText modSettingsText = ModSettingsText.Dynamic(() => ResolveRegistrationDisplayName(registration, i18NGet));
					builder.WithTitle(pageTitle ?? modSettingsText).WithSortOrder(sortOrder).WithModDisplayName(modSettingsText);
					if (pageDescription != null)
					{
						builder.WithDescription(pageDescription);
					}
					for (int num = 0; num < sectionPlans.Count; num++)
					{
						ModConfigMirrorSectionPlan plan = sectionPlans[num];
						bool appendRestoreDefaults = num == sectionPlans.Count - 1;
						builder.AddSection(plan.Id, delegate(ModSettingsSectionBuilder section)
						{
							if (plan.Title != null)
							{
								section.WithTitle(plan.Title);
							}
							foreach (ModConfigMappedEntry entry in plan.Entries)
							{
								AppendConfigEntry(section, modId, entry.Entry, entry.SourceIndex, getValueOpen, setValue, i18NGet, mirrorOptions);
							}
							if (appendRestoreDefaults)
							{
								section.AddButton("modconfig_restore_defaults", ModSettingsText.Literal(ModSettingsLocalization.Get("modconfig.restoreDefaults.row", "Defaults")), ModSettingsText.Literal(ModSettingsLocalization.Get("modconfig.restoreDefaults.button", "Restore defaults")), (Action)delegate
								{
									ConfirmAndResetModConfig(modId, resetDefaults);
								}, ModSettingsButtonTone.Danger, (ModSettingsText?)null);
							}
						});
					}
				}, pageId);
				ModSettingsMirrorSyncPolicyRegistry.RegisterPage(modId, pageId, ModSettingsMirrorSource.ModConfig);
				return true;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[ModConfigMirrorSource] Failed to register page '{modId}::{pageId}': {ex.Message}", 1);
				return false;
			}
		}

		private static bool IsRenderableConfigEntry(object entry)
		{
			string text = ResolveModConfigEntryTypeName(entry);
			bool flag = (((text != null && text.Length == 0) || text == "Header" || text == "Separator") ? true : false);
			return !flag;
		}

		private static List<ModConfigMirrorSectionPlan> BuildMirroredSectionPlans(Array entries, MethodInfo? i18NGet)
		{
			List<ModConfigMirrorSectionPlan> list = new List<ModConfigMirrorSectionPlan>();
			int num = 0;
			ModConfigMirrorSectionPlan modConfigMirrorSectionPlan = new ModConfigMirrorSectionPlan("modconfig_main", ModSettingsText.Literal(ModSettingsLocalization.Get("modconfig.section.main", "General")));
			list.Add(modConfigMirrorSectionPlan);
			for (int i = 0; i < entries.Length; i++)
			{
				object entry = entries.GetValue(i);
				if (entry == null)
				{
					continue;
				}
				if (ResolveModConfigEntryTypeName(entry) == "Header")
				{
					ModSettingsText title = ModSettingsText.Dynamic(() => ResolveEntryLabel(entry, i18NGet));
					if (modConfigMirrorSectionPlan.Entries.Count == 0)
					{
						modConfigMirrorSectionPlan.Title = title;
						continue;
					}
					num++;
					modConfigMirrorSectionPlan = new ModConfigMirrorSectionPlan($"modconfig_sec_{num}", title);
					list.Add(modConfigMirrorSectionPlan);
				}
				else
				{
					modConfigMirrorSectionPlan.Entries.Add(new ModConfigMappedEntry(entry, i));
				}
			}
			list.RemoveAll((ModConfigMirrorSectionPlan plan) => plan.Entries.Count == 0);
			return list;
		}

		private static string ResolveModConfigEntryTypeName(object entry)
		{
			object obj = entry.GetType().GetProperty("Type")?.GetValue(entry);
			if (obj != null)
			{
				if (obj is Enum obj2 && Enum.IsDefined(obj2.GetType(), obj2))
				{
					return obj2.ToString();
				}
				string text = obj.ToString();
				if (!string.IsNullOrEmpty(text) && int.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out var result))
				{
					return MapModConfigTypeCodeToName(result);
				}
				return text ?? "";
			}
			return "";
		}

		private static string MapModConfigTypeCodeToName(int code)
		{
			return code switch
			{
				0 => "Toggle", 
				1 => "Slider", 
				2 => "Dropdown", 
				3 => "KeyBind", 
				4 => "TextInput", 
				5 => "Header", 
				6 => "Separator", 
				7 => "Button", 
				8 => "ColorPicker", 
