			}
		}

		private unsafe static long ParseBindingStringToKeyCode(string s)
		{
			//IL_0047: Unknown result type (might be due to invalid IL or missing references)
			//IL_0038: Unknown result type (might be due to invalid IL or missing references)
			//IL_003a: Expected I8, but got Unknown
			//IL_005f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0062: Expected I8, but got Unknown
			//IL_0063: Unknown result type (might be due to invalid IL or missing references)
			//IL_0080: Unknown result type (might be due to invalid IL or missing references)
			//IL_0084: Expected I8, but got Unknown
			if (string.IsNullOrWhiteSpace(s))
			{
				return 0L;
			}
			string text = (s.Contains('+', StringComparison.Ordinal) ? s.Split('+', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).Last() : s.Trim());
			if (Enum.TryParse<Key>(text, true, out Key result))
			{
				return (long)result;
			}
			Key[] values = Enum.GetValues<Key>();
			for (int i = 0; i < values.Length; i++)
			{
				Key val = values[i];
				if (string.Equals(((object)(*(Key*)(&val))/*cast due to constrained. prefix*/).ToString(), text, StringComparison.OrdinalIgnoreCase))
				{
					return (long)val;
				}
				try
				{
					string keycodeString = OS.GetKeycodeString(val);
					if (!string.IsNullOrEmpty(keycodeString) && string.Equals(keycodeString, text, StringComparison.OrdinalIgnoreCase))
					{
						return (long)val;
					}
				}
				catch
				{
				}
			}
			return 0L;
		}

