	internal static class ModSettingsMirrorEntryAppender
	{
		public static void Append(ModSettingsSectionBuilder section, ModSettingsMirrorEntryDefinition entry)
		{
			switch (entry.Kind)
			{
			case ModSettingsMirrorEntryKind.Header:
				section.AddHeader(entry.Id, entry.Label, entry.Description);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.Paragraph:
				section.AddParagraph(entry.Id, entry.Label, entry.Description, entry.MaxBodyHeight);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.Toggle:
				section.AddToggle(entry.Id, entry.Label, (IModSettingsValueBinding<bool>)entry.Binding, entry.Description);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.Slider:
			{
				object binding = entry.Binding;
				if (!(binding is IModSettingsValueBinding<double> binding2))
				{
					if (!(binding is IModSettingsValueBinding<float> binding3))
					{
						break;
					}
					ModSettingsMirrorNumericOptions numeric = entry.Numeric;
					section.AddFloatSlider(entry.Id, entry.Label, binding3, (float)numeric.Min, (float)numeric.Max, (float)numeric.Step, numeric.FormatFloat, entry.Description);
					ApplyVisibility(section, entry);
					return;
				}
				ModSettingsMirrorNumericOptions numeric2 = entry.Numeric;
				section.AddSlider(entry.Id, entry.Label, binding2, numeric2.Min, numeric2.Max, numeric2.Step, numeric2.FormatDouble, entry.Description);
				ApplyVisibility(section, entry);
				return;
			}
			case ModSettingsMirrorEntryKind.IntSlider:
			{
				ModSettingsMirrorNumericOptions numeric3 = entry.Numeric;
				section.AddIntSlider(entry.Id, entry.Label, (IModSettingsValueBinding<int>)entry.Binding, (int)Math.Round(numeric3.Min), (int)Math.Round(numeric3.Max), Math.Max(1, (int)Math.Round(numeric3.Step)), null, entry.Description);
				ApplyVisibility(section, entry);
				return;
			}
			case ModSettingsMirrorEntryKind.Choice:
				if (entry.ChoiceOptionsProvider == null)
				{
					string id = entry.Id;
					ModSettingsText label = entry.Label;
					IModSettingsValueBinding<string> binding4 = (IModSettingsValueBinding<string>)entry.Binding;
					List<ModSettingsChoiceOption<string>> list = new List<ModSettingsChoiceOption<string>>();
					list.AddRange(entry.ChoiceOptions.Select((ModSettingsMirrorChoiceOption option) => new ModSettingsChoiceOption<string>(option.Value, option.Label)));
					section.AddChoice(id, label, binding4, new <>z__ReadOnlyList<ModSettingsChoiceOption<string>>(list), entry.Description, entry.ChoicePresentation);
				}
				else
				{
					section.AddDynamicChoice(entry.Id, entry.Label, (IModSettingsValueBinding<string>)entry.Binding, delegate
					{
						List<ModSettingsChoiceOption<string>> list2 = new List<ModSettingsChoiceOption<string>>();
						list2.AddRange(from option in entry.ChoiceOptionsProvider()
							select new ModSettingsChoiceOption<string>(option.Value, option.Label));
						return new <>z__ReadOnlyList<ModSettingsChoiceOption<string>>(list2);
					}, entry.Description, entry.ChoicePresentation);
				}
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.EnumChoice:
				AppendEnumChoice(section, entry);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.Color:
				section.AddColor(entry.Id, entry.Label, (IModSettingsValueBinding<string>)entry.Binding, entry.Description, entry.EditAlpha, entry.EditIntensity);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.String:
				section.AddString(entry.Id, entry.Label, (IModSettingsValueBinding<string>)entry.Binding, entry.Placeholder, entry.MaxLength, entry.Description, entry.ValidationVisual, entry.ValidationCommit);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.MultilineString:
				section.AddMultilineString(entry.Id, entry.Label, (IModSettingsValueBinding<string>)entry.Binding, entry.Placeholder, entry.MaxLength, entry.Description);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.KeyBinding:
				section.AddKeyBinding(entry.Id, entry.Label, (IModSettingsValueBinding<string>)entry.Binding, entry.AllowModifierCombos, entry.AllowModifierOnly, entry.DistinguishModifierSides, entry.Description);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.InputBinding:
				section.AddInputBinding(entry.Id, entry.Label, (IModSettingsValueBinding<string>)entry.Binding, entry.AllowModifierCombos, entry.AllowModifierOnly, entry.DistinguishModifierSides, entry.AllowActionBindings, entry.Description);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.MultiKeyBinding:
				section.AddKeyBinding(entry.Id, entry.Label, (IModSettingsValueBinding<List<string>>)entry.Binding, allowMultipleBindings: true, entry.AllowModifierCombos, entry.AllowModifierOnly, entry.DistinguishModifierSides, entry.Description);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.InfoCard:
				section.AddInfoCard(entry.Id, entry.Label, entry.Body ?? ModSettingsText.Literal(string.Empty), entry.Description);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.RuntimeHotkeySummary:
				section.AddRuntimeHotkeySummary(entry.Id, entry.Label, entry.Body ?? ModSettingsText.Literal(string.Empty), entry.HotkeyBindings ?? new <>z__ReadOnlySingleElementList<ModSettingsText>(ModSettingsText.Literal(string.Empty)), entry.HotkeyIdSuffix);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.Image:
				section.AddImage(entry.Id, entry.Label, entry.TextureProvider, entry.PreviewHeight, entry.Description);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.Button:
				section.AddButton(entry.Id, entry.Label, entry.ButtonLabel ?? entry.Label, entry.OnClick, entry.ButtonTone, entry.Description);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.HostContextButton:
				section.AddButton(entry.Id, entry.Label, entry.ButtonLabel ?? entry.Label, entry.HostContextOnClick, entry.ButtonTone, entry.Description);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.Subpage:
				section.AddSubpage(entry.Id, entry.Label, entry.TargetPageId, entry.ButtonLabel, entry.Description);
				ApplyVisibility(section, entry);
				return;
			case ModSettingsMirrorEntryKind.Custom:
				section.AddCustom(entry.Id, entry.Label, entry.CustomControlFactory, entry.Description);
				ApplyVisibility(section, entry);
				return;
			}
			throw new InvalidOperationException($"Unsupported mirror entry kind '{entry.Kind}'.");
		}

		public static void AppendButton(ModSettingsSectionBuilder section, ModSettingsMirrorButtonDefinition button)
		{
			section.AddButton(button.Id, button.RowLabel, button.ButtonLabel, button.OnClick, button.Tone, button.Description);
		}

		private static void AppendEnumChoice(ModSettingsSectionBuilder section, ModSettingsMirrorEntryDefinition entry)
		{
			if (entry.EnumType == null)
			{
				throw new InvalidOperationException("EnumType is required for enum entry '" + entry.Id + "'.");
			}
			typeof(ModSettingsMirrorEntryAppender).GetMethod("AppendEnumChoiceGeneric", BindingFlags.Static | BindingFlags.NonPublic).MakeGenericMethod(entry.EnumType).Invoke(null, new object[2] { section, entry });
		}

		private static void AppendEnumChoiceGeneric<TEnum>(ModSettingsSectionBuilder section, ModSettingsMirrorEntryDefinition entry) where TEnum : struct, Enum
		{
			Func<TEnum, ModSettingsText> optionLabelFactory = ((entry.EnumOptionLabel == null) ? null : ((Func<TEnum, ModSettingsText>)((TEnum value) => entry.EnumOptionLabel(value))));
			section.AddEnumChoice(entry.Id, entry.Label, (IModSettingsValueBinding<TEnum>)entry.Binding, optionLabelFactory, entry.Description, entry.ChoicePresentation);
		}

		private static void ApplyVisibility(ModSettingsSectionBuilder section, ModSettingsMirrorEntryDefinition entry)
		{
			if (entry.VisibleWhen != null)
			{
				section.WithEntryVisibleWhen(entry.Id, entry.VisibleWhen);
			}
			if (entry.ReadOnlyOnHostSurfaces != ModSettingsHostSurface.None)
			{
				section.WithEntryReadOnlyOnHostSurfaces(entry.Id, entry.ReadOnlyOnHostSurfaces);
			}
		}
	}
