	internal enum ModSettingsMirrorSource
	{
		BaseLib,
		BaseLibToRitsuGenerated,
		JmcModLib,
		ModConfig,
		RuntimeInterop,
		RuntimeReflection
	}
	internal static class ModSettingsMirrorInteropPolicy
	{
		private const string DirectivePrefix = "RitsuLib.ModSettingsMirror.";

		private const string GlobalScope = "Global";

		private const string ModScope = "Mod";

		private const string TypeScope = "Type";

		private const string DisableSourcesField = "DisableSources";

		private const string PreferredSourceField = "PreferredSource";

		public static bool ShouldMirror(ModSettingsMirrorSource source, string modId, Type? settingsType = null)
		{
			if (string.IsNullOrWhiteSpace(modId))
			{
				return true;
			}
			if (CollectDisabledSources(modId, settingsType).Contains(source))
			{
				return false;
			}
			ModSettingsMirrorSource? modSettingsMirrorSource = ResolvePreferredSource(modId, settingsType);
			if (modSettingsMirrorSource.HasValue)
			{
				ModSettingsMirrorSource valueOrDefault = modSettingsMirrorSource.GetValueOrDefault();
				return valueOrDefault == source;
			}
			return true;
		}

		private static HashSet<ModSettingsMirrorSource> CollectDisabledSources(string modId, Type? settingsType)
		{
			HashSet<ModSettingsMirrorSource> hashSet = new HashSet<ModSettingsMirrorSource>();
			MergeDisabled(hashSet, BuildTypeDirectiveKey(settingsType, "DisableSources"));
			MergeDisabled(hashSet, BuildModDirectiveKey(modId, "DisableSources"));
			MergeDisabled(hashSet, BuildGlobalDirectiveKey("DisableSources"));
			return hashSet;
		}

		private static void MergeDisabled(HashSet<ModSettingsMirrorSource> bucket, string? key)
		{
			if (string.IsNullOrWhiteSpace(key))
			{
				return;
			}
			foreach (string item in ReadDirectiveValues(key))
			{
				foreach (ModSettingsMirrorSource item2 in ParseSourceList(item))
				{
					bucket.Add(item2);
				}
			}
		}

		private static ModSettingsMirrorSource? ResolvePreferredSource(string modId, Type? settingsType)
		{
			return ResolvePreferredSourceByKey(BuildTypeDirectiveKey(settingsType, "PreferredSource")) ?? ResolvePreferredSourceByKey(BuildModDirectiveKey(modId, "PreferredSource")) ?? ResolvePreferredSourceByKey(BuildGlobalDirectiveKey("PreferredSource"));
		}

		private static ModSettingsMirrorSource? ResolvePreferredSourceByKey(string? key)
		{
			if (string.IsNullOrWhiteSpace(key))
			{
				return null;
			}
			foreach (string item in ReadDirectiveValues(key))
			{
				ModSettingsMirrorSource? result = ParseSingleSource(item);
				if (result.HasValue)
				{
					return result;
				}
			}
			return null;
		}

		private static IEnumerable<string> ReadDirectiveValues(string key)
		{
			List<string> list = new List<string>();
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly assembly in assemblies)
			{
				object[] customAttributes;
				try
				{
					customAttributes = assembly.GetCustomAttributes(typeof(AssemblyMetadataAttribute), inherit: false);
				}
				catch
				{
					continue;
				}
				object[] array = customAttributes;
				for (int j = 0; j < array.Length; j++)
				{
					if (array[j] is AssemblyMetadataAttribute assemblyMetadataAttribute && string.Equals(assemblyMetadataAttribute.Key, key, StringComparison.OrdinalIgnoreCase) && !string.IsNullOrWhiteSpace(assemblyMetadataAttribute.Value))
					{
						list.Add(assemblyMetadataAttribute.Value);
					}
				}
			}
			return list;
		}

		private static HashSet<ModSettingsMirrorSource> ParseSourceList(string value)
		{
			HashSet<ModSettingsMirrorSource> hashSet = new HashSet<ModSettingsMirrorSource>();
			if (string.IsNullOrWhiteSpace(value))
			{
				return hashSet;
			}
			string[] array = value.Split(new char[4] { ',', ';', '|', ' ' }, StringSplitOptions.RemoveEmptyEntries);
			foreach (string text in array)
			{
				ModSettingsMirrorSource source;
				if (text.Equals("all", StringComparison.OrdinalIgnoreCase) || text.Equals("*", StringComparison.OrdinalIgnoreCase))
				{
					hashSet.Add(ModSettingsMirrorSource.BaseLib);
					hashSet.Add(ModSettingsMirrorSource.BaseLibToRitsuGenerated);
					hashSet.Add(ModSettingsMirrorSource.JmcModLib);
					hashSet.Add(ModSettingsMirrorSource.ModConfig);
					hashSet.Add(ModSettingsMirrorSource.RuntimeInterop);
					hashSet.Add(ModSettingsMirrorSource.RuntimeReflection);
				}
				else if (TryParseSourceToken(text, out source))
				{
					hashSet.Add(source);
				}
			}
			return hashSet;
		}

		private static ModSettingsMirrorSource? ParseSingleSource(string value)
		{
			if (string.IsNullOrWhiteSpace(value))
			{
				return null;
			}
			if (!TryParseSourceToken(value.Trim(), out var source))
			{
				return null;
			}
			return source;
		}

		private static bool TryParseSourceToken(string token, out ModSettingsMirrorSource source)
		{
			source = ModSettingsMirrorSource.BaseLib;
			if (string.IsNullOrWhiteSpace(token))
			{
				return false;
			}
			if (token.Equals("baselib", StringComparison.OrdinalIgnoreCase) || token.Equals("base_lib", StringComparison.OrdinalIgnoreCase) || token.Equals("base-lib", StringComparison.OrdinalIgnoreCase))
			{
				source = ModSettingsMirrorSource.BaseLib;
				return true;
			}
			if (token.Equals("generated", StringComparison.OrdinalIgnoreCase) || token.Equals("baselibtoritsugenerated", StringComparison.OrdinalIgnoreCase) || token.Equals("base_lib_to_ritsu_generated", StringComparison.OrdinalIgnoreCase) || token.Equals("base-lib-to-ritsu-generated", StringComparison.OrdinalIgnoreCase) || token.Equals("baselib-generated", StringComparison.OrdinalIgnoreCase))
			{
				source = ModSettingsMirrorSource.BaseLibToRitsuGenerated;
				return true;
			}
			if (token.Equals("modconfig", StringComparison.OrdinalIgnoreCase) || token.Equals("mod_config", StringComparison.OrdinalIgnoreCase) || token.Equals("mod-config", StringComparison.OrdinalIgnoreCase) || token.Equals("modsettings", StringComparison.OrdinalIgnoreCase) || token.Equals("mod_settings", StringComparison.OrdinalIgnoreCase) || token.Equals("mod-settings", StringComparison.OrdinalIgnoreCase))
			{
				source = ModSettingsMirrorSource.ModConfig;
				return true;
			}
			if (token.Equals("jmc", StringComparison.OrdinalIgnoreCase) || token.Equals("jml", StringComparison.OrdinalIgnoreCase) || token.Equals("jmcmodlib", StringComparison.OrdinalIgnoreCase) || token.Equals("jmc_mod_lib", StringComparison.OrdinalIgnoreCase) || token.Equals("jmc-mod-lib", StringComparison.OrdinalIgnoreCase))
			{
				source = ModSettingsMirrorSource.JmcModLib;
				return true;
			}
			if (token.Equals("runtimeinterop", StringComparison.OrdinalIgnoreCase) || token.Equals("runtime_interop", StringComparison.OrdinalIgnoreCase) || token.Equals("runtime-interop", StringComparison.OrdinalIgnoreCase))
			{
				source = ModSettingsMirrorSource.RuntimeInterop;
				return true;
			}
			if (!token.Equals("reflection", StringComparison.OrdinalIgnoreCase) && !token.Equals("reflectioninterop", StringComparison.OrdinalIgnoreCase) && !token.Equals("reflection_interop", StringComparison.OrdinalIgnoreCase) && !token.Equals("reflection-interop", StringComparison.OrdinalIgnoreCase) && !token.Equals("runtimereflection", StringComparison.OrdinalIgnoreCase) && !token.Equals("runtime_reflection", StringComparison.OrdinalIgnoreCase) && !token.Equals("runtime-reflection", StringComparison.OrdinalIgnoreCase))
			{
				return false;
			}
			source = ModSettingsMirrorSource.RuntimeReflection;
			return true;
		}

		private static string BuildGlobalDirectiveKey(string field)
		{
			return "RitsuLib.ModSettingsMirror.Global." + field;
		}

		private static string BuildModDirectiveKey(string modId, string field)
		{
			return $"{"RitsuLib.ModSettingsMirror."}{"Mod"}.{modId}.{field}";
		}

		private static string? BuildTypeDirectiveKey(Type? settingsType, string field)
		{
			if ((object)settingsType != null && settingsType.FullName != null)
			{
				return $"{"RitsuLib.ModSettingsMirror."}{"Type"}.{settingsType.FullName}.{field}";
			}
			return null;
		}
	}
