	internal static class ModSettingsMirrorRegistrar
	{
		public static bool TryRegister(ModSettingsMirrorPageDefinition page, ModSettingsMirrorSource source, bool hasStableExternalSync = false)
		{
			if (ModSettingsRegistry.TryGetPage(page.ModId, page.PageId, out ModSettingsPage _))
			{
				return false;
			}
			try
			{
				ModSettingsRegistry.Register(page.ModId, delegate(ModSettingsPageBuilder builder)
				{
					if (page.Title != null)
					{
						builder.WithTitle(page.Title);
					}
					if (page.Description != null)
					{
						builder.WithDescription(page.Description);
					}
					builder.WithSortOrder(page.SortOrder);
					if (page.ModDisplayName != null)
					{
						builder.WithModDisplayName(page.ModDisplayName);
					}
					int? modSidebarOrder = page.ModSidebarOrder;
					if (modSidebarOrder.HasValue)
					{
						int valueOrDefault = modSidebarOrder.GetValueOrDefault();
						builder.WithModSidebarOrder(valueOrDefault);
					}
					if (!string.IsNullOrWhiteSpace(page.ParentPageId))
					{
						builder.AsChildOf(page.ParentPageId);
					}
					for (int i = 0; i < page.Sections.Count; i++)
					{
						ModSettingsMirrorSectionDefinition sectionDefinition = page.Sections[i];
						ModSettingsMirrorButtonDefinition appendRestoreDefaults = ((i == page.Sections.Count - 1) ? page.RestoreDefaultsButton : null);
						builder.AddSection(sectionDefinition.Id, delegate(ModSettingsSectionBuilder section)
						{
							if (sectionDefinition.Title != null)
							{
								section.WithTitle(sectionDefinition.Title);
							}
							if (sectionDefinition.Description != null)
							{
								section.WithDescription(sectionDefinition.Description);
							}
							if (sectionDefinition.IsCollapsible)
							{
								section.Collapsible(sectionDefinition.StartCollapsed);
							}
							if (sectionDefinition.VisibleWhen != null)
							{
								section.WithVisibleWhen(sectionDefinition.VisibleWhen);
							}
							foreach (ModSettingsMirrorEntryDefinition entry in sectionDefinition.Entries)
							{
								ModSettingsMirrorEntryAppender.Append(section, entry);
							}
							if (appendRestoreDefaults != null)
							{
								ModSettingsMirrorEntryAppender.AppendButton(section, appendRestoreDefaults);
							}
						});
					}
				}, page.PageId);
				ModSettingsMirrorSyncPolicyRegistry.RegisterPage(page.ModId, page.PageId, source, hasStableExternalSync);
				return true;
			}
			catch
			{
				return false;
			}
		}
	}
	internal static class ModSettingsMirrorRegistrarBootstrap
	{
		private static readonly Lock Gate = new Lock();

		private static bool _mainMenuPrewarmCompleted;

		public static int TryRegisterMirroredPages()
		{
			using (Gate.EnterScope())
			{
				if (_mainMenuPrewarmCompleted)
				{
					return 0;
				}
			}
			return TryRegisterMirroredPagesCore();
		}

		public static int PrewarmMirroredPagesForMainMenu()
		{
			using (Gate.EnterScope())
			{
				if (_mainMenuPrewarmCompleted)
				{
					return 0;
				}
			}
			int result = TryRegisterMirroredPagesCore();
			using (Gate.EnterScope())
			{
				_mainMenuPrewarmCompleted = true;
				return result;
			}
		}

		private static int TryRegisterMirroredPagesCore()
		{
			return 0 + BaseLibMirrorSource.TryRegisterMirroredPages() + JmcModLibMirrorSource.TryRegisterMirroredPages() + ModConfigMirrorSource.TryRegisterMirroredPages() + RuntimeInteropMirrorSource.TryRegisterMirroredPages() + RuntimeReflectionMirrorSource.TryRegisterMirroredPages() + BaseLibToRitsuGeneratedMirrorSource.TryRegisterMirroredPages();
		}
	}
	internal readonly record struct ModSettingsMirrorSyncPolicy(ModSettingsMirrorSource Source, bool HasStableExternalSync);
	internal static class ModSettingsMirrorSyncPolicyRegistry
	{
		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<string, ModSettingsMirrorSyncPolicy> Policies = new Dictionary<string, ModSettingsMirrorSyncPolicy>(StringComparer.OrdinalIgnoreCase);

		public static void RegisterPage(string modId, string pageId, ModSettingsMirrorSource source, bool hasStableExternalSync = false)
		{
			if (string.IsNullOrWhiteSpace(modId) || string.IsNullOrWhiteSpace(pageId))
			{
				return;
			}
			using (Gate.EnterScope())
			{
				Policies[CreateCompositeId(modId, pageId)] = new ModSettingsMirrorSyncPolicy(source, hasStableExternalSync);
			}
		}

		public static bool TryGetPolicy(string modId, string pageId, out ModSettingsMirrorSyncPolicy policy)
		{
			using (Gate.EnterScope())
			{
				return Policies.TryGetValue(CreateCompositeId(modId, pageId), out policy);
			}
		}

		private static string CreateCompositeId(string modId, string pageId)
		{
			return modId + "::" + pageId;
		}
	}
	internal static class ModSettingsMirrorUiActions
	{
		public static void ConfirmAndRestoreDefaults(Action restoreDefaults, Action? afterRestore, string header, string body, string cancelText, string confirmText)
		{
			MainLoop mainLoop = Engine.GetMainLoop();
			SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
			if (val != null)
			{
				Window root = val.Root;
				if (root != null)
				{
					RitsuModSettingsSubmenu submenu = FindRitsuModSettingsSubmenu((Node)(object)root);
					ModSettingsUiFactory.ShowStyledConfirm((Node)(((object)submenu) ?? ((object)root)), header, body, cancelText, confirmText, confirmIsDanger: true, delegate
					{
						restoreDefaults();
						afterRestore?.Invoke();
						submenu?.RequestRefresh();
					});
					return;
				}
			}
			restoreDefaults();
			afterRestore?.Invoke();
		}

		public static RitsuModSettingsSubmenu? FindRitsuModSettingsSubmenu(Node root)
		{
			Queue<Node> queue = new Queue<Node>();
			queue.Enqueue(root);
			while (queue.Count > 0)
			{
				Node val = queue.Dequeue();
				if (val is RitsuModSettingsSubmenu result)
				{
					return result;
				}
				foreach (Node child in val.GetChildren(false))
				{
					queue.Enqueue(child);
				}
			}
			return null;
		}

		public static string GetLocalizedOrFallback(string key, string fallback)
		{
			LocString ifExists = LocString.GetIfExists("settings_ui", key);
			return ((ifExists != null) ? ifExists.GetFormattedText() : null) ?? fallback;
		}
	}
