	internal static class RuntimeInteropMirrorSource
	{
		private sealed record InteropProvider(Type ProviderType, MethodInfo SchemaMethod);

		private sealed record InteropSchemaRoot(string ModId, ModSettingsText? ModDisplayName, int? ModSidebarOrder, List<InteropPage> Pages);

		private sealed record InteropPage(string PageId, string? ParentPageId, ModSettingsText Title, ModSettingsText? Description, int SortOrder, List<InteropSection> Sections, bool HideDescription);

		private sealed record InteropSection(string Id, ModSettingsText? Title, ModSettingsText? Description, List<InteropEntry> Entries);

		private sealed record InteropEntry(string Id, InteropEntryType Type, string Key, ModSettingsText Label, ModSettingsText? Description, double Min, double Max, double Step, int? MaxLength, float? MaxBodyHeight, List<InteropChoiceOption> Options, ModSettingsText? ButtonText, string? TargetPageId, ModSettingsButtonTone ButtonTone, SaveScope Scope, string ChoicePresentation, ModSettingsText? Body, bool? EditAlpha, bool? EditIntensity, bool? AllowModifierCombos, bool? AllowModifierOnly, bool? DistinguishModifierSides, ModSettingsText? Placeholder, List<ModSettingsText> HotkeyBindings, ModSettingsText? SummaryIdSuffix, object? DefaultValue, string? VisibleWhenMethod, string? OptionsMethod);

		private sealed record InteropChoiceOption(string Value, ModSettingsText Label);

		private enum InteropEntryType
		{
			Header,
			Paragraph,
			Subpage,
			Toggle,
			Slider,
			IntSlider,
			Choice,
			String,
			MultilineString,
			Color,
			KeyBinding,
			InfoCard,
			RuntimeHotkeySummary,
			Button
		}

		private sealed record InteropAccessor(Type ProviderType, Func<string, object?> GetObject, Action<string, object?> SetObject, Func<string, bool>? GetBool, Action<string, bool>? SetBool, Func<string, double>? GetDouble, Action<string, double>? SetDouble, Func<string, int>? GetInt, Action<string, int>? SetInt, Func<string, string?>? GetString, Action<string, string>? SetString, Action SaveAction, Action<string> InvokeAction);

		private const string ProviderTypeMetadataKey = "RitsuLib.ModSettingsInterop.ProviderType";

		private const string SchemaMethodName = "CreateRitsuLibSettingsSchema";

		private const string ResolverGetMethodName = "GetRitsuLibSettingValue";

		private const string ResolverSetMethodName = "SetRitsuLibSettingValue";

		private const string ResolverSaveMethodName = "SaveRitsuLibSettings";

		private const string ActionInvokeMethodName = "InvokeRitsuLibSettingAction";

		private const string TypedGetBoolMethodName = "GetRitsuLibSettingBool";

		private const string TypedSetBoolMethodName = "SetRitsuLibSettingBool";

		private const string TypedGetDoubleMethodName = "GetRitsuLibSettingDouble";

		private const string TypedSetDoubleMethodName = "SetRitsuLibSettingDouble";

		private const string TypedGetIntMethodName = "GetRitsuLibSettingInt";

		private const string TypedSetIntMethodName = "SetRitsuLibSettingInt";

		private const string TypedGetStringMethodName = "GetRitsuLibSettingString";

		private const string TypedSetStringMethodName = "SetRitsuLibSettingString";

		private static readonly Lock Gate = new Lock();

		private static readonly HashSet<string> SchemaPayloadWarningDedup = new HashSet<string>(StringComparer.Ordinal);

		private static readonly HashSet<string> InteropMethodWarningDedup = new HashSet<string>(StringComparer.Ordinal);

		private static readonly Lock DefaultWriteGate = new Lock();

		private static readonly HashSet<string> DefaultWriteDedup = new HashSet<string>(StringComparer.Ordinal);

		private static readonly Dictionary<string, string?> RuntimeRegisteredProviderTypes = new Dictionary<string, string>(StringComparer.Ordinal);

		private static List<InteropProvider>? _cachedDiscoveredProviders;

		private static int _cachedDiscoveryAssemblyCount = -1;

		private static readonly HashSet<string> ProcessedProviderNames = new HashSet<string>(StringComparer.Ordinal);

		public static bool RegisterProviderType(string providerTypeFullName, string? assemblyName = null)
		{
			if (string.IsNullOrWhiteSpace(providerTypeFullName))
			{
				return false;
			}
			using (Gate.EnterScope())
			{
				RuntimeRegisteredProviderTypes[providerTypeFullName.Trim()] = (string.IsNullOrWhiteSpace(assemblyName) ? null : assemblyName.Trim());
				_cachedDiscoveredProviders = null;
				_cachedDiscoveryAssemblyCount = -1;
				return true;
			}
		}

		public static bool RegisterProviderType(Type providerType)
		{
			ArgumentNullException.ThrowIfNull(providerType, "providerType");
			if (!string.IsNullOrWhiteSpace(providerType.FullName))
			{
				return RegisterProviderType(providerType.FullName, providerType.Assembly.GetName().Name);
			}
			return false;
		}

		public static bool RegisterProviderType<TProvider>()
		{
			return RegisterProviderType(typeof(TProvider));
		}

		public static int RegisterProviderTypeAndTryRegister(string providerTypeFullName, string? assemblyName = null)
		{
			if (RegisterProviderType(providerTypeFullName, assemblyName))
			{
				return TryRegisterMirroredPages();
			}
			return 0;
		}

		public static int RegisterProviderTypeAndTryRegister(Type providerType)
		{
			if (RegisterProviderType(providerType))
			{
				return TryRegisterMirroredPages();
			}
			return 0;
		}

		public static int RegisterProviderTypeAndTryRegister<TProvider>()
		{
			return RegisterProviderTypeAndTryRegister(typeof(TProvider));
		}

		public static int TryRegisterMirroredPages()
		{
			using (Gate.EnterScope())
			{
				List<InteropProvider> list = DiscoverProviders();
				return (list.Count != 0) ? ((IEnumerable<InteropProvider>)list).Sum((Func<InteropProvider, int>)TryRegisterProvider) : 0;
			}
		}

		private static List<InteropProvider> DiscoverProviders()
		{
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			if (_cachedDiscoveredProviders != null && _cachedDiscoveryAssemblyCount == assemblies.Length)
			{
				return _cachedDiscoveredProviders.ToList();
			}
			List<InteropProvider> list = new List<InteropProvider>();
			HashSet<string> seen = new HashSet<string>(StringComparer.Ordinal);
			Assembly[] array = assemblies;
			for (int i = 0; i < array.Length; i++)
			{
				DiscoverAssemblyProviders(array[i], list, seen);
			}
			foreach (var (providerTypeName, assemblyName) in RuntimeRegisteredProviderTypes)
			{
				AddRuntimeRegisteredProvider(providerTypeName, assemblyName, list, seen);
			}
			CacheDiscoveredProviders(list, assemblies.Length);
			return list;
		}

		private static void DiscoverAssemblyProviders(Assembly asm, List<InteropProvider> providers, HashSet<string> seen)
		{
			HashSet<string> hashSet = ReadProviderTypeNames(asm);
			if (hashSet.Count == 0)
			{
				return;
			}
			foreach (string item in hashSet)
			{
				if (!string.IsNullOrWhiteSpace(item))
				{
					Type type = asm.GetType(item, throwOnError: false);
					if (type == null)
					{
						RitsuLibFramework.Logger.Warn("[RuntimeInteropMirrorSource] Provider type not found: " + asm.GetName().Name + "::" + item, 1);
					}
					else
					{
						AddProvider(type, providers, seen, warnMissingSchema: true);
					}
				}
			}
		}

		private static void AddRuntimeRegisteredProvider(string providerTypeName, string? assemblyName, List<InteropProvider> providers, HashSet<string> seen)
		{
			Type type = ResolveProviderType(providerTypeName, assemblyName);
			if (!(type == null))
			{
				AddProvider(type, providers, seen, warnMissingSchema: false);
			}
		}

		private static void AddProvider(Type providerType, List<InteropProvider> providers, HashSet<string> seen, bool warnMissingSchema)
		{
			MethodInfo method = providerType.GetMethod("CreateRitsuLibSettingsSchema", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			if (method == null)
			{
				if (warnMissingSchema)
				{
					RitsuLibFramework.Logger.Warn($"[RuntimeInteropMirrorSource] Missing static method '{"CreateRitsuLibSettingsSchema"}' on {providerType.FullName}.", 1);
				}
			}
			else
			{
				string item = providerType.FullName ?? providerType.Name;
				if (seen.Add(item))
				{
					providers.Add(new InteropProvider(providerType, method));
				}
			}
		}

		private static void CacheDiscoveredProviders(List<InteropProvider> providers, int assemblyCount)
		{
			_cachedDiscoveredProviders = providers.ToList();
			_cachedDiscoveryAssemblyCount = assemblyCount;
		}

		private static int TryRegisterProvider(InteropProvider provider)
		{
			string item = provider.ProviderType.FullName ?? provider.ProviderType.Name;
			if (ProcessedProviderNames.Contains(item))
			{
				return 0;
			}
			try
			{
				if (!TryReadSchema(provider, out InteropSchemaRoot schema))
				{
					return 0;
				}
				if (!TryRegisterFromSchema(provider, schema))
				{
					return 0;
				}
				ProcessedProviderNames.Add(item);
				return 1;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[RuntimeInteropMirrorSource] Provider '" + provider.ProviderType.FullName + "' failed but was isolated: " + ex.Message, 1);
				return 0;
			}
		}

		private static Type? ResolveProviderType(string providerTypeName, string? assemblyName)
		{
			if (string.IsNullOrWhiteSpace(assemblyName))
			{
				return (from asm in AppDomain.CurrentDomain.GetAssemblies()
					select asm.GetType(providerTypeName, throwOnError: false)).OfType<Type>().FirstOrDefault();
			}
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly assembly in assemblies)
			{
				if (string.Equals(assembly.GetName().Name, assemblyName, StringComparison.OrdinalIgnoreCase))
				{
					Type type = assembly.GetType(providerTypeName, throwOnError: false);
					if (type != null)
					{
						return type;
					}
				}
			}
			return (from asm in AppDomain.CurrentDomain.GetAssemblies()
				select asm.GetType(providerTypeName, throwOnError: false)).OfType<Type>().FirstOrDefault();
		}

		private static HashSet<string> ReadProviderTypeNames(Assembly asm)
		{
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			object[] customAttributes;
			try
			{
				customAttributes = asm.GetCustomAttributes(typeof(AssemblyMetadataAttribute), inherit: false);
			}
			catch
			{
				return hashSet;
			}
			object[] array = customAttributes;
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i] is AssemblyMetadataAttribute assemblyMetadataAttribute && string.Equals(assemblyMetadataAttribute.Key, "RitsuLib.ModSettingsInterop.ProviderType", StringComparison.OrdinalIgnoreCase) && !string.IsNullOrWhiteSpace(assemblyMetadataAttribute.Value))
				{
					hashSet.Add(assemblyMetadataAttribute.Value.Trim());
				}
			}
			return hashSet;
		}

		private static bool TryReadSchema(InteropProvider provider, out InteropSchemaRoot schema)
		{
			schema = null;
			object rawSchema;
			try
			{
				rawSchema = provider.SchemaMethod.Invoke(null, Array.Empty<object>());
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[RuntimeInteropMirrorSource] Schema invoke failed for " + provider.ProviderType.FullName + ": " + ex.Message, 1);
				return false;
			}
			if (!TryResolveSchemaRoot(rawSchema, out IDictionary<string, object> root))
			{
				WarnSchemaPayloadInvalidOnce(provider.ProviderType);
				return false;
			}
			if (TryParseSchema(root, provider.ProviderType, out schema))
			{
				return true;
			}
			RitsuLibFramework.Logger.Warn("[RuntimeInteropMirrorSource] Schema parse failed for " + provider.ProviderType.FullName + ".", 1);
			return false;
		}

		private static void WarnSchemaPayloadInvalidOnce(Type providerType)
		{
			string text = providerType.FullName ?? providerType.Name;
			if (SchemaPayloadWarningDedup.Add(text))
			{
				RitsuLibFramework.Logger.Warn("[RuntimeInteropMirrorSource] Schema payload is null/invalid for " + text + ".", 1);
			}
		}

		private static bool TryRegisterFromSchema(InteropProvider provider, InteropSchemaRoot schema)
		{
			if (!ModSettingsMirrorInteropPolicy.ShouldMirror(ModSettingsMirrorSource.RuntimeInterop, schema.ModId, provider.ProviderType))
			{
				return false;
			}
			InteropAccessor access = BuildAccessor(provider.ProviderType);
			Action saveAction = access.SaveAction;
			bool result = false;
			foreach (InteropPage pageSchema in schema.Pages.Where((InteropPage interopPage) => !ModSettingsRegistry.TryGetPage(schema.ModId, interopPage.PageId, out ModSettingsPage _)))
			{
				try
				{
					ModSettingsRegistry.Register(schema.ModId, delegate(ModSettingsPageBuilder page)
					{
						page.WithTitle(pageSchema.Title);
						if (pageSchema.Description != null)
						{
							page.WithDescription(pageSchema.Description);
						}
						page.WithSortOrder(pageSchema.SortOrder);
						if (!string.IsNullOrWhiteSpace(pageSchema.ParentPageId))
						{
							page.AsChildOf(pageSchema.ParentPageId);
						}
						if (pageSchema.HideDescription)
						{
							page.WithDescriptionHidden();
						}
						if (schema.ModDisplayName != null)
						{
							page.WithModDisplayName(schema.ModDisplayName);
						}
						int? modSidebarOrder = schema.ModSidebarOrder;
						if (modSidebarOrder.HasValue)
						{
							int valueOrDefault = modSidebarOrder.GetValueOrDefault();
							page.WithModSidebarOrder(valueOrDefault);
						}
						foreach (InteropSection section in pageSchema.Sections)
						{
							page.AddSection(section.Id, delegate(ModSettingsSectionBuilder sb)
							{
								if (section.Title != null)
								{
									sb.WithTitle(section.Title);
								}
								if (section.Description != null)
								{
									sb.WithDescription(section.Description);
								}
								foreach (InteropEntry entry in section.Entries)
								{
									AppendEntry(sb, schema.ModId, entry, access, saveAction);
								}
							});
						}
					}, pageSchema.PageId);
					ModSettingsMirrorSyncPolicyRegistry.RegisterPage(schema.ModId, pageSchema.PageId, ModSettingsMirrorSource.RuntimeInterop);
					result = true;
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[RuntimeInteropMirrorSource] Register failed for {schema.ModId}::{pageSchema.PageId}: {ex.Message}", 1);
				}
			}
			return result;
		}

		private static void AppendEntry(ModSettingsSectionBuilder section, string modId, InteropEntry entry, InteropAccessor access, Action saveAction)
		{
			ModSettingsText label = entry.Label;
			ModSettingsText description = entry.Description;
			string dataKey = "interop::" + entry.Key;
			string defaultWriteKey = $"{modId}::{entry.Scope}::{entry.Key}";
			switch (entry.Type)
			{
			case InteropEntryType.Header:
				section.AddHeader(entry.Id, label, description);
				ApplyEntryVisibilityHook(section, entry, access);
				break;
			case InteropEntryType.Paragraph:
				section.AddParagraph(entry.Id, label, description, entry.MaxBodyHeight);
				ApplyEntryVisibilityHook(section, entry, access);
				break;
			case InteropEntryType.Subpage:
				if (string.IsNullOrWhiteSpace(entry.TargetPageId))
				{
					RitsuLibFramework.Logger.Warn("[RuntimeInteropMirrorSource] Skipping subpage entry '" + entry.Id + "' because targetPageId is missing.", 1);
					break;
				}
				section.AddSubpage(entry.Id, label, entry.TargetPageId, entry.ButtonText, description);
				ApplyEntryVisibilityHook(section, entry, access);
				break;
			case InteropEntryType.Toggle:
			{
				IModSettingsValueBinding<bool> binding2 = ModSettingsBindings.Callback(modId, dataKey, () => ReadBoolWithDefault(defaultWriteKey, entry, access, saveAction), delegate(bool value)
				{
					WriteBool(entry.Key, value, access);
				}, saveAction, entry.Scope);
				binding2 = WithDefaultIfPresent(binding2, entry);
				section.AddToggle(entry.Id, label, binding2, description);
				ApplyEntryVisibilityHook(section, entry, access);
				break;
			}
			case InteropEntryType.Slider:
			{
				IModSettingsValueBinding<double> binding = ModSettingsBindings.Callback(modId, dataKey, () => ReadDoubleWithDefault(defaultWriteKey, entry, access, saveAction), delegate(double value)
				{
					WriteDouble(entry.Key, value, access);
				}, saveAction, entry.Scope);
				binding = WithDefaultIfPresent(binding, entry);
				section.AddSlider(entry.Id, label, binding, entry.Min, entry.Max, entry.Step, null, description);
				ApplyEntryVisibilityHook(section, entry, access);
				break;
			}
			case InteropEntryType.IntSlider:
			{
				IModSettingsValueBinding<int> binding7 = ModSettingsBindings.Callback(modId, dataKey, () => ReadIntWithDefault(defaultWriteKey, entry, access, saveAction), delegate(int value)
				{
					WriteInt(entry.Key, value, access);
				}, saveAction, entry.Scope);
				binding7 = WithDefaultIfPresent(binding7, entry);
				section.AddIntSlider(entry.Id, label, binding7, (int)Math.Round(entry.Min), (int)Math.Round(entry.Max), Math.Max(1, (int)Math.Round(entry.Step)), null, description);
				ApplyEntryVisibilityHook(section, entry, access);
				break;
			}
			case InteropEntryType.String:
			{
				IModSettingsValueBinding<string> binding5 = ModSettingsBindings.Callback(modId, dataKey, () => ReadStringWithDefault(defaultWriteKey, entry, access, saveAction), delegate(string value)
				{
					WriteString(entry.Key, value, access);
				}, saveAction, entry.Scope);
				binding5 = WithDefaultIfPresent(binding5, entry);
				section.AddString(entry.Id, label, binding5, entry.Placeholder, NormalizeMaxLength(entry.MaxLength), description);
				ApplyEntryVisibilityHook(section, entry, access);
				break;
			}
			case InteropEntryType.MultilineString:
			{
				IModSettingsValueBinding<string> binding4 = ModSettingsBindings.Callback(modId, dataKey, () => ReadStringWithDefault(defaultWriteKey, entry, access, saveAction), delegate(string value)
				{
					WriteString(entry.Key, value, access);
				}, saveAction, entry.Scope);
				binding4 = WithDefaultIfPresent(binding4, entry);
				section.AddMultilineString(entry.Id, label, binding4, entry.Placeholder, NormalizeMaxLength(entry.MaxLength), description);
				ApplyEntryVisibilityHook(section, entry, access);
				break;
			}
			case InteropEntryType.Color:
			{
				IModSettingsValueBinding<string> binding6 = ModSettingsBindings.Callback(modId, dataKey, () => ReadStringWithDefault(defaultWriteKey, entry, access, saveAction), delegate(string value)
				{
					WriteString(entry.Key, value, access);
				}, saveAction, entry.Scope);
				binding6 = WithDefaultIfPresent(binding6, entry);
				bool editAlpha = entry.EditAlpha ?? true;
				bool valueOrDefault2 = entry.EditIntensity == true;
				section.AddColor(entry.Id, label, binding6, description, editAlpha, valueOrDefault2);
				ApplyEntryVisibilityHook(section, entry, access);
				break;
			}
			case InteropEntryType.KeyBinding:
			{
				IModSettingsValueBinding<string> binding3 = ModSettingsBindings.Callback(modId, dataKey, () => ReadStringWithDefault(defaultWriteKey, entry, access, saveAction), delegate(string value)
				{
					WriteString(entry.Key, value, access);
				}, saveAction, entry.Scope);
				binding3 = WithDefaultIfPresent(binding3, entry);
				bool allowModifierCombos = entry.AllowModifierCombos ?? true;
				bool allowModifierOnly = entry.AllowModifierOnly ?? true;
				bool valueOrDefault = entry.DistinguishModifierSides == true;
				section.AddKeyBinding(entry.Id, label, binding3, allowModifierCombos, allowModifierOnly, valueOrDefault, description);
				ApplyEntryVisibilityHook(section, entry, access);
				break;
			}
			case InteropEntryType.InfoCard:
			{
				ModSettingsText body = entry.Body ?? ModSettingsText.Literal(string.Empty);
				section.AddInfoCard(entry.Id, label, body, description);
				ApplyEntryVisibilityHook(section, entry, access);
				break;
			}
			case InteropEntryType.RuntimeHotkeySummary:
			{
				if (entry.HotkeyBindings.Count == 0)
				{
					RitsuLibFramework.Logger.Warn("[RuntimeInteropMirrorSource] Skipping runtime-hotkey-summary entry '" + entry.Id + "' because bindings is empty.", 1);
					break;
				}
				ModSettingsText body2 = entry.Body ?? ModSettingsText.Literal(string.Empty);
				ModSettingsText[] bindings = entry.HotkeyBindings.ToArray();
				ModSettingsText summaryIdSuffix = entry.SummaryIdSuffix;
				section.AddRuntimeHotkeySummary(entry.Id, label, body2, bindings, summaryIdSuffix);
				ApplyEntryVisibilityHook(section, entry, access);
				break;
			}
			case InteropEntryType.Choice:
			{
				List<InteropChoiceOption> list = ResolveChoiceOptions(entry, access);
				if (list.Count == 0)
				{
					break;
				}
				ModSettingsChoiceOption<string>[] options = list.Select((InteropChoiceOption o) => new ModSettingsChoiceOption<string>(o.Value, o.Label)).ToArray();
				string firstValue = options[0].Value;
				IModSettingsValueBinding<string> modSettingsValueBinding = ModSettingsBindings.Callback(modId, dataKey, () => ReadChoiceWithDefault(defaultWriteKey, entry, options, firstValue, access, saveAction), delegate(string value)
				{
					WriteString(entry.Key, string.IsNullOrWhiteSpace(value) ? firstValue : value, access);
				}, saveAction, entry.Scope);
				if (TryResolveChoiceDefault(entry, options, out string defaultChoice))
				{
					modSettingsValueBinding = ModSettingsBindings.WithDefault(modSettingsValueBinding, () => defaultChoice);
				}
				section.AddChoice(entry.Id, label, modSettingsValueBinding, options, description, (entry.ChoicePresentation == "dropdown") ? ModSettingsChoicePresentation.Dropdown : ModSettingsChoicePresentation.Stepper);
				ApplyEntryVisibilityHook(section, entry, access);
				break;
			}
			case InteropEntryType.Button:
			{
				ModSettingsText buttonText = entry.ButtonText ?? label;
				section.AddButton(entry.Id, label, buttonText, (Action)delegate
				{
					access.InvokeAction(entry.Key);
				}, entry.ButtonTone, description);
				ApplyEntryVisibilityHook(section, entry, access);
				break;
			}
			}
		}

		private static IModSettingsValueBinding<bool> WithDefaultIfPresent(IModSettingsValueBinding<bool> binding, InteropEntry entry)
		{
			if (!TryCoerceDefaultBool(entry.DefaultValue, out var defaultValue))
			{
				return binding;
			}
			return ModSettingsBindings.WithDefault(binding, () => defaultValue);
		}

		private static IModSettingsValueBinding<double> WithDefaultIfPresent(IModSettingsValueBinding<double> binding, InteropEntry entry)
		{
			if (!TryCoerceDefaultDouble(entry.DefaultValue, out var defaultValue))
			{
				return binding;
			}
			return ModSettingsBindings.WithDefault(binding, () => defaultValue);
		}

		private static IModSettingsValueBinding<int> WithDefaultIfPresent(IModSettingsValueBinding<int> binding, InteropEntry entry)
		{
			if (!TryCoerceDefaultInt(entry.DefaultValue, out var defaultValue))
			{
				return binding;
			}
			return ModSettingsBindings.WithDefault(binding, () => defaultValue);
		}

		private static IModSettingsValueBinding<string> WithDefaultIfPresent(IModSettingsValueBinding<string> binding, InteropEntry entry)
		{
			if (!TryCoerceDefaultString(entry.DefaultValue, out string defaultValue))
			{
				return binding;
			}
			return ModSettingsBindings.WithDefault(binding, () => defaultValue);
		}

		private static void ApplyEntryVisibilityHook(ModSettingsSectionBuilder section, InteropEntry entry, InteropAccessor access)
		{
			if (!string.IsNullOrWhiteSpace(entry.VisibleWhenMethod))
			{
				section.WithEntryVisibleWhen(entry.Id, () => EvaluateVisibleWhen(entry, access));
			}
		}

		private static bool EvaluateVisibleWhen(InteropEntry entry, InteropAccessor access)
		{
			if (!TryResolveInteropMethod(access.ProviderType, entry.VisibleWhenMethod, out MethodInfo method))
			{
				return true;
			}
			try
			{
				object obj = ((method.GetParameters().Length == 0) ? FastMethodInvoker.InvokeStatic0(method) : FastMethodInvoker.InvokeStatic1(method, entry.Key));
				return (obj is bool flag) ? flag : CoerceBool(obj);
			}
			catch (Exception ex)
			{
				WarnInteropMethodOnce(access.ProviderType, $"visibleWhenMethod '{entry.VisibleWhenMethod}' for entry '{entry.Id}' failed: {ex.Message}");
				return true;
			}
		}

		private static List<InteropChoiceOption> ResolveChoiceOptions(InteropEntry entry, InteropAccessor access)
		{
			if (string.IsNullOrWhiteSpace(entry.OptionsMethod) || !TryResolveInteropMethod(access.ProviderType, entry.OptionsMethod, out MethodInfo method))
			{
				return entry.Options;
			}
			try
			{
				List<InteropChoiceOption> list = ParseOptionsFromRaw((method.GetParameters().Length == 0) ? FastMethodInvoker.InvokeStatic0(method) : FastMethodInvoker.InvokeStatic1(method, entry.Key));
				if (list.Count > 0)
				{
					return list;
				}
				WarnInteropMethodOnce(access.ProviderType, $"optionsMethod '{entry.OptionsMethod}' for entry '{entry.Id}' returned no valid options; falling back to static options.");
				return entry.Options;
			}
			catch (Exception ex)
			{
				WarnInteropMethodOnce(access.ProviderType, $"optionsMethod '{entry.OptionsMethod}' for entry '{entry.Id}' failed: {ex.Message}");
				return entry.Options;
			}
		}

