	internal static class RuntimeReflectionMethodBinder
	{
		public static MethodInfo Resolve(MemberInfo member, object? instance, string methodName, string propertyName)
		{
			Type type = member.DeclaringType ?? throw ModSettingsMirrorDiagnostics.InvalidConfig("Member has no declaring type.");
			MethodInfo? method = type.GetMethod(methodName, BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			if (method == null)
			{
				throw ModSettingsMirrorDiagnostics.InvalidConfig($"'{propertyName}' references missing method '{type.FullName}.{methodName}'.");
			}
			if (!method.IsStatic && instance == null)
			{
				throw ModSettingsMirrorDiagnostics.InvalidConfig($"'{propertyName}' references instance method '{type.FullName}.{methodName}', but provider instance is null.");
			}
			return method;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Specifies how a member exposed by the runtime-reflection mirror stores its value.</para>
	///     <para xml:lang="zh-CN">指定运行时反射镜像所公开成员的值存储方式。</para>
	/// </summary>
	public enum ModSettingsReflectionBindingSource
	{
		/// <summary>
		///     <para xml:lang="en">Uses the framework default, which currently behaves like <see cref="F:STS2RitsuLib.Settings.ModSettingsReflectionBindingSource.Global" />.</para>
		///     <para xml:lang="zh-CN">使用框架默认方式；当前行为与 <see cref="F:STS2RitsuLib.Settings.ModSettingsReflectionBindingSource.Global" /> 相同。</para>
		/// </summary>
		Auto = 0,
		/// <summary>
		///     <para xml:lang="en">Persists the value in the mod's global data store.</para>
		///     <para xml:lang="zh-CN">将值持久化到模组的全局数据存储中。</para>
		/// </summary>
		Global = 1,
		/// <summary>
		///     <para xml:lang="en">Persists the value in the mod's profile-scoped data store.</para>
		///     <para xml:lang="zh-CN">将值持久化到模组的玩家档案数据存储中。</para>
		/// </summary>
		Profile = 2,
		/// <summary>
		///     <para xml:lang="en">Keeps the value in memory for the current process only.</para>
		///     <para xml:lang="zh-CN">仅在当前进程的内存中保存值。</para>
		/// </summary>
		InMemory = 4,
		/// <summary>
		///     <para xml:lang="en">Uses caller-provided read, write, and optional save callbacks.</para>
		///     <para xml:lang="zh-CN">使用调用方提供的读取、写入及可选保存回调。</para>
		/// </summary>
		Callback = 5,
		/// <summary>
		///     <para xml:lang="en">Projects this value from a parent value managed through callbacks.</para>
		///     <para xml:lang="zh-CN">从由回调管理的父值中投影出此值。</para>
		/// </summary>
		Project = 6
	}
	/// <summary>
