	internal static class RuntimeReflectionMirrorSource
	{
		private sealed class ReflectionBindingBox<TValue>
		{
			public TValue Value { get; set; }
		}

		private sealed class MutableSection(ModSettingsSectionAttribute source)
		{
			public string Id { get; } = source.Id;

			public int SortOrder { get; } = source.SortOrder;

			public ModSettingsText? Title { get; } = ToTextOrNull(source, "Title", source.Title);

			public ModSettingsText? Description { get; } = ToTextOrNull(source, "Description", source.Description);

			public bool IsCollapsible { get; } = source.IsCollapsible;

			public bool StartCollapsed { get; } = source.StartCollapsed;

			public List<EntryWithOrder> Entries { get; } = new List<EntryWithOrder>();

			public ModSettingsMirrorSectionDefinition Build()
			{
				ModSettingsMirrorEntryDefinition[] entries = (from e in Entries
					orderby e.Order
					select e.Entry).ToArray();
				return new ModSettingsMirrorSectionDefinition(Id, entries, Title, Description, IsCollapsible, StartCollapsed);
			}
		}

		private sealed record EntryWithOrder(int Order, ModSettingsMirrorEntryDefinition Entry);

		private const string ProviderTypeMetadataKey = "RitsuLib.ModSettingsReflection.ProviderType";

		private const string DefaultLocTable = "settings_ui";

		private static readonly Lock Gate = new Lock();

		[ThreadStatic]
		private static string? _currentReflectionModId;

		[ThreadStatic]
		private static I18N? _currentReflectionI18N;

		[ThreadStatic]
		private static Type? _currentProviderType;

		[ThreadStatic]
		private static object? _currentProviderInstance;

		private static readonly Dictionary<string, string?> RuntimeRegisteredProviderTypes = new Dictionary<string, string>(StringComparer.Ordinal);

		private static List<Type>? _cachedDiscoveredProviders;

		private static int _cachedDiscoveryAssemblyCount = -1;

		public static bool RegisterProviderType(string providerTypeFullName, string? assemblyName = null)
		{
			if (string.IsNullOrWhiteSpace(providerTypeFullName))
			{
				return false;
			}
			using (Gate.EnterScope())
			{
				RuntimeRegisteredProviderTypes[providerTypeFullName.Trim()] = (string.IsNullOrWhiteSpace(assemblyName) ? null : assemblyName.Trim());
				_cachedDiscoveredProviders = null;
				_cachedDiscoveryAssemblyCount = -1;
				return true;
			}
		}

		public static bool RegisterProviderType(Type providerType)
		{
			ArgumentNullException.ThrowIfNull(providerType, "providerType");
			if (!string.IsNullOrWhiteSpace(providerType.FullName))
			{
				return RegisterProviderType(providerType.FullName, providerType.Assembly.GetName().Name);
			}
			return false;
		}

		public static bool RegisterProviderType<TProvider>()
		{
			return RegisterProviderType(typeof(TProvider));
		}

		public static int RegisterProviderTypeAndTryRegister(Type providerType)
		{
			if (RegisterProviderType(providerType))
			{
				return TryRegisterMirroredPages();
			}
			return 0;
		}

		public static int RegisterProviderTypeAndTryRegister<TProvider>()
		{
			return RegisterProviderTypeAndTryRegister(typeof(TProvider));
		}

		public static int TryRegisterMirroredPages()
		{
			using (Gate.EnterScope())
			{
				List<Type> list = DiscoverProviders();
				return (list.Count != 0) ? ((IEnumerable<Type>)list).Sum((Func<Type, int>)TryRegisterProvider) : 0;
			}
		}

		private static List<Type> DiscoverProviders()
		{
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			if (_cachedDiscoveredProviders != null && _cachedDiscoveryAssemblyCount == assemblies.Length)
			{
				return _cachedDiscoveredProviders.ToList();
			}
			List<Type> list = new List<Type>();
			HashSet<string> seen = new HashSet<string>(StringComparer.Ordinal);
			Assembly[] array = assemblies;
			for (int i = 0; i < array.Length; i++)
			{
				DiscoverAssemblyProviders(array[i], list, seen);
			}
			foreach (var (providerTypeName, assemblyName) in RuntimeRegisteredProviderTypes)
			{
				AddRuntimeRegisteredProvider(providerTypeName, assemblyName, list, seen);
			}
			CacheDiscoveredProviders(list, assemblies.Length);
			return list;
		}

		private static void DiscoverAssemblyProviders(Assembly asm, List<Type> providers, HashSet<string> seen)
		{
			foreach (Type item in from typeName in ReadProviderTypeNames(asm)
				select asm.GetType(typeName, throwOnError: false))
			{
				if (item?.GetCustomAttribute<ModSettingsPageAttribute>() != null && seen.Add(item.FullName ?? item.Name))
				{
					providers.Add(item);
				}
			}
			foreach (Type item2 in SafeGetTypes(asm))
			{
				if (item2.GetCustomAttribute<ModSettingsPageAttribute>() != null && seen.Add(item2.FullName ?? item2.Name))
				{
					providers.Add(item2);
				}
			}
		}

		private static void AddRuntimeRegisteredProvider(string providerTypeName, string? assemblyName, List<Type> providers, HashSet<string> seen)
		{
			Type type = ResolveProviderType(providerTypeName, assemblyName);
			if (type?.GetCustomAttribute<ModSettingsPageAttribute>() != null && seen.Add(type.FullName ?? type.Name))
			{
				providers.Add(type);
			}
		}

		private static void CacheDiscoveredProviders(List<Type> providers, int assemblyCount)
		{
			_cachedDiscoveredProviders = providers.ToList();
			_cachedDiscoveryAssemblyCount = assemblyCount;
		}

		private static int TryRegisterProvider(Type provider)
		{
			try
			{
				if (!TryCreateMirror(provider, out ModSettingsMirrorPageDefinition page))
				{
					return 0;
				}
				if (!ModSettingsMirrorInteropPolicy.ShouldMirror(ModSettingsMirrorSource.RuntimeReflection, page.ModId, provider))
				{
					return 0;
				}
				return ModSettingsMirrorRegistrar.TryRegister(page, ModSettingsMirrorSource.RuntimeReflection) ? 1 : 0;
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.Warn($"[RuntimeReflectionMirrorSource] Register failed for '{provider.FullName}': {value}", 1);
				return 0;
			}
		}

		private static IEnumerable<Type> SafeGetTypes(Assembly asm)
		{
			try
			{
				return asm.GetTypes();
			}
			catch (ReflectionTypeLoadException ex)
			{
				Type[] array = ex.Types.OfType<Type>().ToArray();
				string[] array2 = (from exception in ex.LoaderExceptions.OfType<Exception>()
					select exception.Message).Distinct<string>(StringComparer.Ordinal).ToArray();
				string value = ((array2.Length == 0) ? "No loader details were provided." : string.Join(" | ", array2));
				RitsuLibFramework.Logger.Warn($"[RuntimeReflectionMirrorSource] Partially enumerated assembly '{asm.FullName}': recovered {array.Length} of {ex.Types.Length} type(s); skipped unloadable types. {value}", 1);
				return array;
			}
			catch (Exception value2)
			{
				RitsuLibFramework.Logger.Warn($"[RuntimeReflectionMirrorSource] Failed to enumerate types from assembly '{asm.FullName}': {value2}", 1);
				return Array.Empty<Type>();
			}
		}

		private static HashSet<string> ReadProviderTypeNames(Assembly asm)
		{
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			object[] customAttributes;
			try
			{
				customAttributes = asm.GetCustomAttributes(typeof(AssemblyMetadataAttribute), inherit: false);
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.Warn($"[RuntimeReflectionMirrorSource] Failed to read provider metadata from assembly '{asm.FullName}': {value}", 1);
				return hashSet;
			}
			object[] array = customAttributes;
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i] is AssemblyMetadataAttribute assemblyMetadataAttribute && string.Equals(assemblyMetadataAttribute.Key, "RitsuLib.ModSettingsReflection.ProviderType", StringComparison.OrdinalIgnoreCase) && !string.IsNullOrWhiteSpace(assemblyMetadataAttribute.Value))
				{
					hashSet.Add(assemblyMetadataAttribute.Value.Trim());
				}
			}
			return hashSet;
		}

		private static Type? ResolveProviderType(string providerTypeName, string? assemblyName)
		{
			if (string.IsNullOrWhiteSpace(assemblyName))
			{
				return (from asm in AppDomain.CurrentDomain.GetAssemblies()
					select asm.GetType(providerTypeName, throwOnError: false)).OfType<Type>().FirstOrDefault();
			}
			return (from asm in AppDomain.CurrentDomain.GetAssemblies()
				where string.Equals(asm.GetName().Name, assemblyName, StringComparison.OrdinalIgnoreCase)
				select asm.GetType(providerTypeName, throwOnError: false)).FirstOrDefault();
		}

		private static bool TryCreateMirror(Type providerType, out ModSettingsMirrorPageDefinition page)
		{
			page = null;
			ModSettingsPageAttribute customAttribute = providerType.GetCustomAttribute<ModSettingsPageAttribute>();
			if (customAttribute == null || string.IsNullOrWhiteSpace(customAttribute.ModId))
			{
				return false;
			}
			string pageId = (string.IsNullOrWhiteSpace(customAttribute.PageId) ? customAttribute.ModId : customAttribute.PageId.Trim());
			if (ModSettingsRegistry.TryGetPage(customAttribute.ModId, pageId, out ModSettingsPage _))
			{
				return false;
			}
			if (!TryCreateProviderInstance(providerType, out object instance))
			{
				return false;
			}
			string currentReflectionModId = _currentReflectionModId;
			I18N currentReflectionI18N = _currentReflectionI18N;
			Type currentProviderType = _currentProviderType;
			object currentProviderInstance = _currentProviderInstance;
			_currentReflectionModId = customAttribute.ModId;
			_currentProviderType = providerType;
			_currentProviderInstance = instance;
			_currentReflectionI18N = ResolvePageI18NProvider(providerType, instance, customAttribute);
			try
			{
				Dictionary<string, MutableSection> dictionary = new Dictionary<string, MutableSection>(StringComparer.OrdinalIgnoreCase);
				foreach (ModSettingsSectionAttribute customAttribute2 in providerType.GetCustomAttributes<ModSettingsSectionAttribute>())
				{
					dictionary[customAttribute2.Id] = new MutableSection(customAttribute2);
				}
				AppendPropertyEntries(providerType, instance, customAttribute.ModId, dictionary);
				AppendMethodEntries(providerType, instance, customAttribute.ModId, dictionary);
				ModSettingsMirrorSectionDefinition[] array = (from section in (from section in dictionary.Values
						where section.Entries.Count > 0
						orderby section.SortOrder
						select section).ThenBy<MutableSection, string>((MutableSection section) => section.Id, StringComparer.OrdinalIgnoreCase)
					select section.Build()).ToArray();
				if (array.Length == 0)
				{
					return false;
				}
				page = new ModSettingsMirrorPageDefinition(customAttribute.ModId, pageId, customAttribute.SortOrder, array, ToTextOrNull(customAttribute, "Title", customAttribute.Title), ToTextOrNull(customAttribute, "Description", customAttribute.Description), ToTextOrNull(customAttribute, "ModDisplayName", customAttribute.ModDisplayName), customAttribute.ModSidebarOrder, customAttribute.ParentPageId);
				return true;
			}
			finally
			{
				_currentReflectionModId = currentReflectionModId;
				_currentReflectionI18N = currentReflectionI18N;
				_currentProviderType = currentProviderType;
				_currentProviderInstance = currentProviderInstance;
			}
		}

		private static I18N? ResolvePageI18NProvider(Type providerType, object? instance, ModSettingsPageAttribute pageAttr)
		{
			if (string.IsNullOrWhiteSpace(pageAttr.I18NProviderUsing))
			{
				return null;
			}
			string text = pageAttr.I18NProviderUsing.Trim();
			MethodInfo method = providerType.GetMethod(text, BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			if (method == null)
			{
				throw new InvalidOperationException($"I18N provider method '{text}' was not found on '{providerType.FullName}'.");
			}
			if (method.ReturnType != typeof(I18N) || method.GetParameters().Length != 0)
			{
				throw new InvalidOperationException($"I18N provider method '{providerType.FullName}.{method.Name}' must have signature 'I18N ()'.");
			}
			if (!method.IsStatic && instance == null)
			{
				throw new InvalidOperationException($"I18N provider method '{providerType.FullName}.{method.Name}' requires instance context.");
			}
			return FastMethodInvoker.Invoke0<I18N>(method, instance);
		}

		private static bool TryCreateProviderInstance(Type providerType, out object? instance)
		{
			instance = null;
			if ((object)providerType != null && providerType.IsAbstract && providerType.IsSealed)
			{
				return true;
			}
			ConstructorInfo constructor = providerType.GetConstructor(Type.EmptyTypes);
			if (constructor == null)
			{
				RitsuLibFramework.Logger.Warn("[RuntimeReflectionMirrorSource] Type '" + providerType.FullName + "' needs parameterless ctor or be static.", 1);
				return false;
			}
			instance = FastMethodInvoker.CreateWithDefaultCtor(constructor);
			return true;
		}

		private static void AppendPropertyEntries(Type providerType, object? instance, string modId, IDictionary<string, MutableSection> sections)
		{
			PropertyInfo[] properties = providerType.GetProperties(BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			foreach (PropertyInfo propertyInfo in properties)
			{
				if (!propertyInfo.CanRead || !propertyInfo.CanWrite)
				{
					continue;
				}
				ModSettingsToggleAttribute customAttribute = propertyInfo.GetCustomAttribute<ModSettingsToggleAttribute>();
				if (customAttribute != null && propertyInfo.PropertyType == typeof(bool))
				{
					IModSettingsValueBinding<bool> binding = CreateBinding<bool>(modId, propertyInfo, instance);
					string sectionId = customAttribute.SectionId;
					int order = customAttribute.Order;
					string id = customAttribute.Id;
					ModSettingsText label = ToText(customAttribute, "Label", customAttribute.Label, propertyInfo.Name);
					ModSettingsText? description = ToTextOrNull(customAttribute, "Description", customAttribute.Description);
					Func<bool> visibleWhen = BuildVisibleWhen(providerType, instance, customAttribute.VisibleWhen);
					AddEntry(sections, sectionId, order, new ModSettingsMirrorEntryDefinition(id, ModSettingsMirrorEntryKind.Toggle, label, binding, description, null, null, ModSettingsChoicePresentation.Stepper, null, null, null, null, null, AllowModifierCombos: true, AllowModifierOnly: true, DistinguishModifierSides: false, AllowActionBindings: true, null, null, null, ModSettingsButtonTone.Normal, null, null, null, null, null, 160f, EditAlpha: true, EditIntensity: false, null, null, null, ModSettingsHostSurface.None, visibleWhen));
					continue;
				}
				ModSettingsSliderAttribute customAttribute2 = propertyInfo.GetCustomAttribute<ModSettingsSliderAttribute>();
				if (customAttribute2 != null && (propertyInfo.PropertyType == typeof(double) || propertyInfo.PropertyType == typeof(float)))
				{
					object binding2 = ((propertyInfo.PropertyType == typeof(float)) ? ((IModSettingsBinding)CreateBinding<float>(modId, propertyInfo, instance)) : ((IModSettingsBinding)CreateBinding<double>(modId, propertyInfo, instance)));
					string sectionId2 = customAttribute2.SectionId;
					int order2 = customAttribute2.Order;
					string id2 = customAttribute2.Id;
					ModSettingsText label2 = ToText(customAttribute2, "Label", customAttribute2.Label, propertyInfo.Name);
					ModSettingsText? description2 = ToTextOrNull(customAttribute2, "Description", customAttribute2.Description);
					ModSettingsMirrorNumericOptions numeric = new ModSettingsMirrorNumericOptions(customAttribute2.Min, customAttribute2.Max, customAttribute2.Step);
					Func<bool> visibleWhen = BuildVisibleWhen(providerType, instance, customAttribute2.VisibleWhen);
					AddEntry(sections, sectionId2, order2, new ModSettingsMirrorEntryDefinition(id2, ModSettingsMirrorEntryKind.Slider, label2, binding2, description2, numeric, null, ModSettingsChoicePresentation.Stepper, null, null, null, null, null, AllowModifierCombos: true, AllowModifierOnly: true, DistinguishModifierSides: false, AllowActionBindings: true, null, null, null, ModSettingsButtonTone.Normal, null, null, null, null, null, 160f, EditAlpha: true, EditIntensity: false, null, null, null, ModSettingsHostSurface.None, visibleWhen));
