		private static ModSettingsText BuildMethodBackedMirrorText(object attribute, string textFieldName, string? configuredRawText, MethodInfo method, object? instance)
		{
			if (!string.IsNullOrWhiteSpace(configuredRawText) || TryGetLocStringSource(attribute, textFieldName, out string _, out string key) || TryGetI18NKey(attribute, textFieldName, out key))
			{
				return ToText(attribute, textFieldName, configuredRawText, InvokeText(method, instance) ?? method.Name);
			}
			return ModSettingsText.Dynamic(() => InvokeText(method, instance) ?? string.Empty);
		}

		private static ModSettingsText ToText(string? raw, string fallback)
		{
			if (string.IsNullOrWhiteSpace(raw) && TryResolveDefaultSlugLocString(fallback, isDescription: false, out ModSettingsText text))
			{
				return text;
			}
			return ModSettingsText.Literal(string.IsNullOrWhiteSpace(raw) ? fallback : raw);
		}

		private static ModSettingsText ToText(object source, string textFieldName, string? raw, string fallback)
		{
			if (TryGetLocStringSource(source, textFieldName, out string table, out string key))
			{
				return ModSettingsText.LocString(table, key, string.IsNullOrWhiteSpace(raw) ? fallback : raw);
			}
			if (TryGetI18NKey(source, textFieldName, out key))
			{
				return ModSettingsText.I18N(ResolveI18NForSource(source, textFieldName, null), key, string.IsNullOrWhiteSpace(raw) ? fallback : raw);
			}
			return ToText(raw, fallback);
		}

		private static ModSettingsText? ToTextOrNull(string? raw)
