			return null;
		}

		private static ModSettingsText? ToTextOrNull(object source, string textFieldName, string? raw)
		{
			if (TryGetLocStringSource(source, textFieldName, out string table, out string key))
			{
				string fallback = (string.IsNullOrWhiteSpace(raw) ? key : raw);
				return ModSettingsText.LocString(table, key, fallback);
			}
			if (TryGetI18NKey(source, textFieldName, out key))
			{
				return ModSettingsText.I18N(ResolveI18NForSource(source, textFieldName, null), fallback: string.IsNullOrWhiteSpace(raw) ? key : raw, key: key);
			}
			if (string.IsNullOrWhiteSpace(raw) && TryResolveDefaultSlugLocString(GetSlugSeedFor(source, textFieldName), IsDescriptionField(textFieldName), out ModSettingsText text))
			{
				return text;
			}
