		private static bool TryResolveDefaultSlugLocString(string? seed, bool isDescription, out ModSettingsText text)
		{
			if (string.IsNullOrWhiteSpace(seed) || string.IsNullOrWhiteSpace(_currentReflectionModId))
			{
				text = null;
				return false;
			}
			string text2 = ModSettingsMirrorSlugPolicy.PrefixForModId(_currentReflectionModId);
			string text3 = ModSettingsMirrorIds.Slug(seed);
			if (string.IsNullOrWhiteSpace(text3))
			{
				text = null;
				return false;
			}
			string[] array = ((!isDescription) ? new string[1] { ".title" } : new string[2] { ".description", ".hover.desc" });
			foreach (string text4 in array)
			{
				string text5 = text2 + text3 + text4;
				if (LocString.Exists("settings_ui", text5))
				{
					text = ModSettingsText.LocString("settings_ui", text5, seed);
					return true;
				}
			}
			text = null;
			return false;
		}

		private static bool IsDescriptionField(string fieldName)
		{
			if (!fieldName.EndsWith("Description", StringComparison.OrdinalIgnoreCase))
			{
				return fieldName.EndsWith("Body", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}

