		private static string BuildI18NMissingMessage(object source, string fieldName, int? index, string? providerMethod)
		{
			string text = (index.HasValue ? $"{source.GetType().Name}.{fieldName}Keys[{index.Value}]" : (source.GetType().Name + "." + fieldName + "Key"));
			string text2 = (string.IsNullOrWhiteSpace(providerMethod) ? "Set I18NProviderUsing on the page or current attribute." : ("Configured I18NProviderUsing '" + providerMethod + "' returned null or could not be resolved."));
			return "I18N key path '" + text + "' is invalid because no I18N instance is available. " + text2;
