			}
			if (!method.IsStatic && _currentProviderInstance == null)
			{
				throw new InvalidOperationException($"I18N provider method '{type.FullName}.{method.Name}' requires instance context.");
			}
			return FastMethodInvoker.Invoke0<I18N>(method, _currentProviderInstance);
		}

		private static Func<bool>? BuildVisibleWhen(Type providerType, object? instance, string? methodName)
		{
			if (string.IsNullOrWhiteSpace(methodName))
			{
				return null;
			}
			MethodInfo method = providerType.GetMethod(methodName.Trim(), BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			if (method == null || method.ReturnType != typeof(bool) || method.GetParameters().Length != 0)
			{
				return null;
			}
			return () => FastMethodInvoker.Invoke0<bool>(method, instance);
		}

		private static Func<string, bool>? BuildStringValidator(Type providerType, object? instance, string? methodName)
		{
			if (string.IsNullOrWhiteSpace(methodName))
			{
				return null;
			}
			MethodInfo method = providerType.GetMethod(methodName.Trim(), BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			if (method == null || method.ReturnType != typeof(bool))
			{
				return null;
			}
			ParameterInfo[] parameters = method.GetParameters();
			if (parameters.Length != 1 || parameters[0].ParameterType != typeof(string))
			{
				return null;
			}
			return (string value) => FastMethodInvoker.Invoke1<string, bool>(method, instance, value);
		}

