		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether the provider is active until the user stores an explicit per-provider preference. The
		///         value is captured once during registration.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取用户尚未保存此提供器的明确偏好时，提供器是否默认启用；该值会在注册时读取一次。
		///     </para>
		/// </summary>
		bool EnabledByDefault { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Produces alternate searchable forms for <paramref name="text" />. Return an empty list when the text
		///         or locale is unsupported. RitsuLib accepts at most 64 unique expansions and 8,192 total expansion
		///         characters per provider call; excess and case-insensitive duplicates are ignored, and result ordering
		///         is not a public contract. Callbacks may run concurrently and must not retain or mutate
		///         <paramref name="context" />. Recoverable failures are logged and treated as no expansions;
		///         non-recoverable exceptions are preserved.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="text" /> 生成可选搜索形式。文本或语言环境不受支持时返回空列表。RitsuLib 每次
		///         调用最多接受 64 个唯一扩展和总计 8,192 个扩展字符；超出部分及不区分大小写的重复项会被忽略，
		///         结果顺序不属于公开契约。回调可能并发执行，且不得保留或修改 <paramref name="context" />。可恢复
		///         故障会写入日志并按无扩展处理；不可恢复异常会继续传播。
		///     </para>
		/// </summary>
		/// <param name="text">
		///     <para xml:lang="en">The immutable source text being indexed.</para>
		///     <para xml:lang="zh-CN">正在建立索引的不可变源文本。</para>
		/// </param>
		/// <param name="context">
		///     <para xml:lang="en">The current search expansion context.</para>
		///     <para xml:lang="zh-CN">当前搜索扩展上下文。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A non-null, finite list of searchable expansions.</para>
		///     <para xml:lang="zh-CN">非 null 且数量有限的可搜索扩展列表。</para>
		/// </returns>
		IReadOnlyList<RitsuSearchExpansion> Expand(string text, RitsuSearchExpansionContext context);
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides read-only access to RitsuLib's local text matching for mod-owned search controls.
	///     </para>
	///     <para xml:lang="zh-CN">为模组自己的搜索控件提供对 RitsuLib 本地文本匹配的只读访问。</para>
	/// </summary>
	public static class RitsuSearch
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Tests whether <paramref name="text" /> contains <paramref name="term" /> directly or through an enabled
		///         search expansion provider. Provider callbacks may run synchronously on the calling thread; this method
		///         does not download or initialize provider data.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         测试 <paramref name="text" /> 是否直接或通过已启用的搜索扩展提供器包含
		///         <paramref name="term" />。提供器回调可能在调用线程上同步执行；本方法不会下载或初始化提供器数据。
		///     </para>
		/// </summary>
		/// <param name="text">
		///     <para xml:lang="en">The source text to search.</para>
		///     <para xml:lang="zh-CN">要搜索的源文本。</para>
		/// </param>
		/// <param name="term">
		///     <para xml:lang="en">The substring or alternate representation to find.</para>
		///     <para xml:lang="zh-CN">要查找的子串或可选表示。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when a case-insensitive direct or expanded match exists; otherwise,
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         存在不区分大小写的直接匹配或扩展匹配时为 <see langword="true" />；否则为
		///         <see langword="false" />。
		///     </para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="text" /> or <paramref name="term" /> is null.</para>
		///     <para xml:lang="zh-CN"><paramref name="text" /> 或 <paramref name="term" /> 为 null。</para>
		/// </exception>
		public static bool Contains(string text, string term)
		{
			return Prepare(text).Contains(term);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Asynchronously tests one source text. Expansion work is cached and performed away from the calling
		///         thread; cancellation stops this caller's wait without discarding work shared by another caller.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         异步测试一个源文本。扩展工作会被缓存并在调用线程之外执行；取消只停止当前调用方的等待，不会丢弃
		///         其他调用方正在共享的工作。
		///     </para>
		/// </summary>
		/// <param name="text">
		///     <para xml:lang="en">The source text to search.</para>
		///     <para xml:lang="zh-CN">要搜索的源文本。</para>
		/// </param>
		/// <param name="term">
		///     <para xml:lang="en">The substring or alternate representation to find.</para>
		///     <para xml:lang="zh-CN">要查找的子串或可选表示。</para>
		/// </param>
		/// <param name="cancellationToken">
		///     <para xml:lang="en">A token that stops waiting for the result.</para>
		///     <para xml:lang="zh-CN">用于停止等待结果的取消令牌。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A task whose result indicates whether the text matches.</para>
		///     <para xml:lang="zh-CN">结果指示文本是否匹配的任务。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="text" /> or <paramref name="term" /> is null.</para>
		///     <para xml:lang="zh-CN"><paramref name="text" /> 或 <paramref name="term" /> 为 null。</para>
		/// </exception>
		/// <exception cref="T:System.OperationCanceledException">
		///     <para xml:lang="en"><paramref name="cancellationToken" /> is canceled.</para>
		///     <para xml:lang="zh-CN"><paramref name="cancellationToken" /> 已取消。</para>
		/// </exception>
		public static ValueTask<bool> ContainsAsync(string text, string term, CancellationToken cancellationToken = default(CancellationToken))
		{
			return Prepare(text).ContainsAsync(term, cancellationToken);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Searches a sequence asynchronously and returns one complete, source-ordered result list. At most
		///         <paramref name="maximumResults" /> matches are requested; enumeration stops after that requirement is
		///         satisfied. Use <see cref="M:STS2RitsuLib.Search.RitsuSearch.SearchStreamAsync``1(System.Collections.Generic.IEnumerable{``0},System.Func{``0,System.String},System.String,System.Int32,System.Threading.CancellationToken)" /> when results should appear progressively.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         异步搜索序列并一次返回按源顺序排列的完整结果列表。最多请求
		///         <paramref name="maximumResults" /> 个匹配项，达到该需求后停止枚举。需要逐步显示结果时使用
		///         <see cref="M:STS2RitsuLib.Search.RitsuSearch.SearchStreamAsync``1(System.Collections.Generic.IEnumerable{``0},System.Func{``0,System.String},System.String,System.Int32,System.Threading.CancellationToken)" />。
		///     </para>
		/// </summary>
		/// <typeparam name="T">
		///     <para xml:lang="en">The source item type.</para>
		///     <para xml:lang="zh-CN">源项目类型。</para>
		/// </typeparam>
		/// <param name="source">
		///     <para xml:lang="en">The finite sequence to search once in enumeration order.</para>
		///     <para xml:lang="zh-CN">按枚举顺序搜索一次的有限序列。</para>
		/// </param>
		/// <param name="textSelector">
		///     <para xml:lang="en">A thread-safe callback that returns non-null searchable text for each item.</para>
		///     <para xml:lang="zh-CN">为每个项目返回非 null 可搜索文本的线程安全回调。</para>
		/// </param>
		/// <param name="term">
		///     <para xml:lang="en">The substring or alternate representation to find.</para>
		///     <para xml:lang="zh-CN">要查找的子串或可选表示。</para>
		/// </param>
		/// <param name="maximumResults">
		///     <para xml:lang="en">The positive number of matches required before enumeration may stop.</para>
		///     <para xml:lang="zh-CN">达到后可以停止枚举的正数匹配项数量。</para>
		/// </param>
		/// <param name="cancellationToken">
		///     <para xml:lang="en">A token that cancels enumeration and waiting.</para>
		///     <para xml:lang="zh-CN">用于取消枚举和等待的令牌。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A task containing up to the requested number of matching source items.</para>
		///     <para xml:lang="zh-CN">包含不超过请求数量的匹配源项目的任务。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="source" />, <paramref name="textSelector" />, or <paramref name="term" /> is null.</para>
		///     <para xml:lang="zh-CN"><paramref name="source" />、<paramref name="textSelector" /> 或 <paramref name="term" /> 为 null。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentOutOfRangeException">
		///     <para xml:lang="en"><paramref name="maximumResults" /> is not positive.</para>
		///     <para xml:lang="zh-CN"><paramref name="maximumResults" /> 不是正数。</para>
		/// </exception>
		/// <exception cref="T:System.InvalidOperationException">
		///     <para xml:lang="en"><paramref name="textSelector" /> returns null.</para>
		///     <para xml:lang="zh-CN"><paramref name="textSelector" /> 返回 null。</para>
		/// </exception>
		/// <exception cref="T:System.OperationCanceledException">
		///     <para xml:lang="en"><paramref name="cancellationToken" /> is canceled.</para>
		///     <para xml:lang="zh-CN"><paramref name="cancellationToken" /> 已取消。</para>
		/// </exception>
		public static async Task<IReadOnlyList<T>> SearchAsync<T>(IEnumerable<T> source, Func<T, string> textSelector, string term, int maximumResults, CancellationToken cancellationToken = default(CancellationToken))
		{
			List<T> results = new List<T>();
			await foreach (T item in SearchStreamAsync(source, textSelector, term, maximumResults, cancellationToken).ConfigureAwait(continueOnCapturedContext: false))
			{
				results.Add(item);
			}
			return results.AsReadOnly();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Searches a sequence asynchronously and yields each match as it becomes available in source order.
		///         Enumeration stops when the source ends, cancellation is requested, or
		///         <paramref name="maximumResults" /> matches have been yielded. Text expansions are cached for the
		///         duration of this enumeration.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         异步搜索序列，并按源顺序在每个匹配项可用时立即生成。源结束、请求取消或已生成
		///         <paramref name="maximumResults" /> 个匹配项时停止枚举。文本扩展会在本次枚举期间缓存。
		///     </para>
		/// </summary>
		/// <typeparam name="T">
		///     <para xml:lang="en">The source item type.</para>
		///     <para xml:lang="zh-CN">源项目类型。</para>
		/// </typeparam>
		/// <param name="source">
		///     <para xml:lang="en">The finite sequence to search once in enumeration order.</para>
		///     <para xml:lang="zh-CN">按枚举顺序搜索一次的有限序列。</para>
		/// </param>
		/// <param name="textSelector">
		///     <para xml:lang="en">A thread-safe callback that returns non-null searchable text for each item.</para>
		///     <para xml:lang="zh-CN">为每个项目返回非 null 可搜索文本的线程安全回调。</para>
		/// </param>
		/// <param name="term">
		///     <para xml:lang="en">The substring or alternate representation to find.</para>
		///     <para xml:lang="zh-CN">要查找的子串或可选表示。</para>
		/// </param>
		/// <param name="maximumResults">
		///     <para xml:lang="en">The positive number of matches required before enumeration stops.</para>
		///     <para xml:lang="zh-CN">达到后停止枚举的正数匹配项数量。</para>
		/// </param>
		/// <param name="cancellationToken">
		///     <para xml:lang="en">A token that cancels enumeration and waiting.</para>
		///     <para xml:lang="zh-CN">用于取消枚举和等待的令牌。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">An asynchronous stream of matching source items.</para>
		///     <para xml:lang="zh-CN">匹配源项目的异步流。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="source" />, <paramref name="textSelector" />, or <paramref name="term" /> is null.</para>
		///     <para xml:lang="zh-CN"><paramref name="source" />、<paramref name="textSelector" /> 或 <paramref name="term" /> 为 null。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentOutOfRangeException">
		///     <para xml:lang="en"><paramref name="maximumResults" /> is not positive.</para>
		///     <para xml:lang="zh-CN"><paramref name="maximumResults" /> 不是正数。</para>
		/// </exception>
		/// <exception cref="T:System.InvalidOperationException">
		///     <para xml:lang="en"><paramref name="textSelector" /> returns null.</para>
		///     <para xml:lang="zh-CN"><paramref name="textSelector" /> 返回 null。</para>
		/// </exception>
		/// <exception cref="T:System.OperationCanceledException">
		///     <para xml:lang="en"><paramref name="cancellationToken" /> is canceled.</para>
		///     <para xml:lang="zh-CN"><paramref name="cancellationToken" /> 已取消。</para>
		/// </exception>
		public static async IAsyncEnumerable<T> SearchStreamAsync<T>(IEnumerable<T> source, Func<T, string> textSelector, string term, int maximumResults, [EnumeratorCancellation] CancellationToken cancellationToken = default(CancellationToken))
		{
			ArgumentNullException.ThrowIfNull(source, "source");
			ArgumentNullException.ThrowIfNull(textSelector, "textSelector");
			ArgumentNullException.ThrowIfNull(term, "term");
			ArgumentOutOfRangeException.ThrowIfNegativeOrZero(maximumResults, "maximumResults");
			Dictionary<string, RitsuSearchText> preparedTexts = new Dictionary<string, RitsuSearchText>(StringComparer.Ordinal);
			int resultCount = 0;
			int processedCount = 0;
			foreach (T item in source)
			{
				cancellationToken.ThrowIfCancellationRequested();
				string text = textSelector(item) ?? throw new InvalidOperationException("The search text selector returned null.");
				if (!preparedTexts.TryGetValue(text, out RitsuSearchText value))
				{
					value = Prepare(text);
					preparedTexts.Add(text, value);
				}
				int num;
				if (await value.ContainsAsync(term, cancellationToken).ConfigureAwait(continueOnCapturedContext: false))
				{
					yield return item;
					num = resultCount + 1;
					resultCount = num;
					if (num == maximumResults)
					{
						yield break;
					}
				}
				num = processedCount + 1;
				processedCount = num;
				if (num % 32 == 0)
				{
					await Task.Yield();
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Prepares immutable source text for repeated matching. The returned object is thread-safe and refreshes
		///         its bounded expansions automatically after language, provider registration, provider data, or user
		///         enablement changes. Preparation itself does not invoke providers or perform I/O.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为重复匹配准备不可变源文本。返回对象是线程安全的，并会在语言、提供器注册、提供器数据或用户启用
		///         状态变化后自动刷新受限扩展。准备过程本身不会调用提供器或执行 I/O。
		///     </para>
		/// </summary>
		/// <param name="text">
		///     <para xml:lang="en">
		///         The source text retained by the returned object until that object is no longer referenced.
		///     </para>
		///     <para xml:lang="zh-CN">返回对象在不再被引用前会保留的源文本。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A reusable search-text object owned by the caller.</para>
		///     <para xml:lang="zh-CN">由调用方持有的可复用搜索文本对象。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="text" /> is null.</para>
		///     <para xml:lang="zh-CN"><paramref name="text" /> 为 null。</para>
		/// </exception>
		public static RitsuSearchText Prepare(string text)
		{
			ArgumentNullException.ThrowIfNull(text, "text");
			return new RitsuSearchText(text);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Holds immutable source text and a lazily refreshed, bounded expansion cache for repeated local searches.
	///         Instances are thread-safe and do not require disposal.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         保存不可变源文本及用于重复本地搜索、按需刷新的受限扩展缓存。实例是线程安全的，且无需释放。
	///     </para>
	/// </summary>
	public sealed class RitsuSearchText
	{
		private readonly RitsuSearchPreparedText _preparedText;

		private readonly string _text;

		internal RitsuSearchText(string text)
		{
			_text = text;
			_preparedText = new RitsuSearchPreparedText(text);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Tests whether the prepared source text contains <paramref name="term" /> directly or through an enabled
		///         search expansion provider. Provider callbacks run lazily and may execute synchronously on the calling
		///         thread; this method does not download or initialize provider data.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         测试已准备的源文本是否直接或通过已启用的搜索扩展提供器包含 <paramref name="term" />。提供器回调
		///         按需运行，并可能在调用线程上同步执行；本方法不会下载或初始化提供器数据。
		///     </para>
		/// </summary>
		/// <param name="term">
		///     <para xml:lang="en">The substring or alternate representation to find.</para>
		///     <para xml:lang="zh-CN">要查找的子串或可选表示。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when a case-insensitive direct or expanded match exists; otherwise,
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         存在不区分大小写的直接匹配或扩展匹配时为 <see langword="true" />；否则为
		///         <see langword="false" />。
		///     </para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="term" /> is null.</para>
		///     <para xml:lang="zh-CN"><paramref name="term" /> 为 null。</para>
		/// </exception>
		public bool Contains(string term)
		{
			ArgumentNullException.ThrowIfNull(term, "term");
			return RitsuSearchMatcher.Contains(_text, term, _preparedText);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Asynchronously tests the prepared text, sharing its expansion cache with synchronous and concurrent
		///         asynchronous calls. Cancellation stops this caller's wait without canceling shared cache generation.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         异步测试已准备文本，并与同步及并发异步调用共享扩展缓存。取消只停止当前调用方的等待，不会取消共享
		///         缓存的生成。
		///     </para>
		/// </summary>
		/// <param name="term">
		///     <para xml:lang="en">The substring or alternate representation to find.</para>
		///     <para xml:lang="zh-CN">要查找的子串或可选表示。</para>
		/// </param>
		/// <param name="cancellationToken">
		///     <para xml:lang="en">A token that stops waiting for the result.</para>
		///     <para xml:lang="zh-CN">用于停止等待结果的取消令牌。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A task whose result indicates whether the text matches.</para>
		///     <para xml:lang="zh-CN">结果指示文本是否匹配的任务。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="term" /> is null.</para>
		///     <para xml:lang="zh-CN"><paramref name="term" /> 为 null。</para>
		/// </exception>
		/// <exception cref="T:System.OperationCanceledException">
		///     <para xml:lang="en"><paramref name="cancellationToken" /> is canceled.</para>
		///     <para xml:lang="zh-CN"><paramref name="cancellationToken" /> 已取消。</para>
		/// </exception>
		public ValueTask<bool> ContainsAsync(string term, CancellationToken cancellationToken = default(CancellationToken))
		{
			ArgumentNullException.ThrowIfNull(term, "term");
			return RitsuSearchMatcher.ContainsAsync(_text, term, _preparedText, cancellationToken);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Represents one bounded alternate form that can participate in local text search.</para>
	///     <para xml:lang="zh-CN">表示一个可参与本地文本搜索、长度受限的可选形式。</para>
	/// </summary>
	public sealed class RitsuSearchExpansion
	{
		/// <summary>
		///     <para xml:lang="en">The maximum accepted expansion length.</para>
		///     <para xml:lang="zh-CN">允许的扩展文本最大长度。</para>
		/// </summary>
		public const int MaximumTextLength = 512;

		/// <summary>
		///     <para xml:lang="en">Gets the alternate searchable text.</para>
		///     <para xml:lang="zh-CN">获取可选搜索文本。</para>
		/// </summary>
		public string Text { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the expansion category.</para>
		///     <para xml:lang="zh-CN">获取扩展类别。</para>
		/// </summary>
		public RitsuSearchExpansionKind Kind { get; }

		/// <summary>
		///     <para xml:lang="en">Creates a searchable expansion.</para>
		///     <para xml:lang="zh-CN">创建一个可搜索扩展。</para>
		/// </summary>
		/// <param name="text">
		///     <para xml:lang="en">Non-empty alternate text of at most 512 characters.</para>
		///     <para xml:lang="zh-CN">非空且不超过 512 个字符的可选文本。</para>
		/// </param>
		/// <param name="kind">
		///     <para xml:lang="en">The expansion category used by RitsuLib to rank matches.</para>
		///     <para xml:lang="zh-CN">RitsuLib 用于排列匹配结果的扩展类别。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en"><paramref name="text" /> is empty, whitespace, or too long.</para>
		///     <para xml:lang="zh-CN"><paramref name="text" /> 为空、仅含空白或过长。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentOutOfRangeException">
		///     <para xml:lang="en"><paramref name="kind" /> is not defined.</para>
		///     <para xml:lang="zh-CN"><paramref name="kind" /> 不是已定义的值。</para>
		/// </exception>
		public RitsuSearchExpansion(string text, RitsuSearchExpansionKind kind)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(text, "text");
			if (text.Length > 512)
			{
				throw new ArgumentException($"Search expansion text cannot exceed {512} characters.", "text");
			}
			if (!Enum.IsDefined(kind))
			{
				throw new ArgumentOutOfRangeException("kind");
			}
			Text = text.Trim();
			Kind = kind;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Describes the locale context used while preparing alternate search text.</para>
	///     <para xml:lang="zh-CN">描述准备可选搜索文本时使用的语言环境上下文。</para>
	/// </summary>
	public sealed class RitsuSearchExpansionContext
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets RitsuLib's normalized current game language code, such as <c>zhs</c>, <c>jpn</c>, or
		///         <c>eng</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 RitsuLib 规范化后的当前游戏语言代码，例如 <c>zhs</c>、<c>jpn</c> 或 <c>eng</c>。
		///     </para>
		/// </summary>
		public string LanguageCode { get; }

		internal RitsuSearchExpansionContext(string languageCode)
		{
			LanguageCode = languageCode;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Classifies an alternate searchable representation supplied by a search expansion provider.</para>
	///     <para xml:lang="zh-CN">对搜索扩展提供器给出的可选搜索表示形式进行分类。</para>
	/// </summary>
	public enum RitsuSearchExpansionKind
	{
		/// <summary>
		///     <para xml:lang="en">A provider's preferred full transliteration.</para>
		///     <para xml:lang="zh-CN">提供器首选的完整转写。</para>
		/// </summary>
		Transliteration,
		/// <summary>
		///     <para xml:lang="en">A valid but non-preferred reading or transliteration.</para>
		///     <para xml:lang="zh-CN">有效但非首选的读音或转写。</para>
		/// </summary>
		AlternateReading,
		/// <summary>
		///     <para xml:lang="en">An abbreviated representation such as transliterated initials.</para>
		///     <para xml:lang="zh-CN">转写首字母等缩略表示。</para>
		/// </summary>
		Initialism
	}
	/// <summary>
	///     <para xml:lang="en">Owns one registered search expansion provider and supports cache invalidation.</para>
	///     <para xml:lang="zh-CN">持有一个已注册的搜索扩展提供器，并支持缓存失效通知。</para>
	/// </summary>
	public sealed class RitsuSearchExpansionRegistration : IDisposable
	{
		private readonly long _token;

		private int _disposed;

		/// <summary>
		///     <para xml:lang="en">Gets the registered provider ID.</para>
		///     <para xml:lang="zh-CN">获取已注册的提供器 ID。</para>
		/// </summary>
		public string ProviderId { get; }

		internal RitsuSearchExpansionRegistration(string providerId, long token)
		{
			ProviderId = providerId;
			_token = token;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Invalidates cached expansions after the provider's already-local data changes. Calling this method
		///         after disposal has no effect. The provider must complete downloads and file work before calling it.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在提供器已有的本地数据发生变化后使扩展缓存失效。释放后调用不会产生效果。提供器必须先完成下载和
		///         文件操作，再调用此方法。
		///     </para>
		/// </summary>
		public void Invalidate()
		{
			if (Volatile.Read(in _disposed) == 0)
			{
				RitsuSearchExpansionRegistry.Invalidate(ProviderId, _token);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Unregisters the provider. Repeated disposal has no effect. A callback already captured by a concurrent
		///         search may finish after this method returns, so the owner must keep its provider safe for such calls.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注销提供器；重复释放不会产生效果。并发搜索已经取得的回调可能会在本方法返回后才结束，因此所属方
		///         必须保证提供器仍能安全完成此类调用。
		///     </para>
		/// </summary>
		public void Dispose()
		{
			if (Interlocked.Exchange(ref _disposed, 1) == 0)
			{
				RitsuSearchExpansionRegistry.Unregister(ProviderId, _token);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Registers optional transliteration and search-text expansion providers.</para>
	///     <para xml:lang="zh-CN">注册可选的转写和搜索文本扩展提供器。</para>
	/// </summary>
	public static class RitsuSearchExpansionRegistry
	{
		internal sealed record ProviderSnapshot(string Id, string ModId, string DisplayName, bool Enabled);

		private sealed record ProviderEntry(string Id, string ModId, IRitsuSearchExpansionProvider Provider, bool EnabledByDefault, long Token);

		private const int MaximumExpansionsPerCall = 64;

		private const int MaximumModIdLength = 128;

		private const int MaximumProviderIdLength = 128;

		private const int MaximumDisplayNameLength = 256;

		private const int MaximumTotalExpansionCharacters = 8192;

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, ProviderEntry> Providers = new Dictionary<string, ProviderEntry>(StringComparer.OrdinalIgnoreCase);

		private static long _generation;

		private static long _nextToken;

		internal static long Generation
		{
			get
			{
				using (SyncRoot.EnterScope())
				{
					return _generation;
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a case-insensitively unique provider owned by <paramref name="modId" />. Registration reads
		///         provider metadata but does not call <see cref="M:STS2RitsuLib.Search.IRitsuSearchExpansionProvider.Expand(System.String,STS2RitsuLib.Search.RitsuSearchExpansionContext)" />. Dispose the
		///         returned handle before the owner unloads.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册由 <paramref name="modId" /> 持有且 ID 不区分大小写全局唯一的提供器。注册会读取提供器元数据，
		///         但不会调用 <see cref="M:STS2RitsuLib.Search.IRitsuSearchExpansionProvider.Expand(System.String,STS2RitsuLib.Search.RitsuSearchExpansionContext)" />。所属 mod 卸载前应释放返回的句柄。
		///     </para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">The non-empty owning mod ID, at most 128 characters.</para>
		///     <para xml:lang="zh-CN">非空且不超过 128 个字符的所属 mod ID。</para>
		/// </param>
		/// <param name="provider">
		///     <para xml:lang="en">The provider instance. The registry does not take ownership of it.</para>
		///     <para xml:lang="zh-CN">提供器实例；注册表不会取得其所有权。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A handle that invalidates caches or unregisters this exact registration.</para>
		///     <para xml:lang="zh-CN">用于使缓存失效或注销本次确切注册的句柄。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">The mod ID or provider metadata is invalid.</para>
		///     <para xml:lang="zh-CN">mod ID 或提供器元数据无效。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="provider" /> is null.</para>
		///     <para xml:lang="zh-CN"><paramref name="provider" /> 为 null。</para>
		/// </exception>
		/// <exception cref="T:System.InvalidOperationException">
		///     <para xml:lang="en">The provider ID is already registered.</para>
		///     <para xml:lang="zh-CN">提供器 ID 已被注册。</para>
		/// </exception>
		public static RitsuSearchExpansionRegistration Register(string modId, IRitsuSearchExpansionProvider provider)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentNullException.ThrowIfNull(provider, "provider");
			string text = modId.Trim();
			if (text.Length > 128)
			{
				throw new ArgumentException($"Owning mod IDs cannot exceed {128} characters.", "modId");
			}
			string text2 = ValidateProviderId(provider.Id);
			ValidateDisplayName(provider.DisplayName);
			bool enabledByDefault = provider.EnabledByDefault;
			using (SyncRoot.EnterScope())
			{
				if (Providers.ContainsKey(text2))
				{
					throw new InvalidOperationException("Search expansion provider '" + text2 + "' is already registered.");
				}
				long token = ++_nextToken;
				Providers.Add(text2, new ProviderEntry(text2, text, provider, enabledByDefault, token));
				_generation++;
				return new RitsuSearchExpansionRegistration(text2, token);
			}
		}

		internal static IReadOnlyList<RitsuSearchExpansion> Expand(string text, string languageCode)
		{
			ProviderEntry[] source;
			using (SyncRoot.EnterScope())
			{
				source = Providers.Values.ToArray();
			}
			source = source.Where((ProviderEntry entry) => RitsuSearchSettingsStore.IsProviderEnabled(entry.Id, entry.EnabledByDefault)).ToArray();
			if (source.Length == 0)
			{
				return Array.Empty<RitsuSearchExpansion>();
			}
			RitsuSearchExpansionContext context = new RitsuSearchExpansionContext(languageCode);
			List<RitsuSearchExpansion> list = new List<RitsuSearchExpansion>();
			HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			int num = 0;
			ProviderEntry[] array = source;
			foreach (ProviderEntry providerEntry in array)
			{
				IReadOnlyList<RitsuSearchExpansion> readOnlyList;
				try
				{
					readOnlyList = providerEntry.Provider.Expand(text, context);
				}
				catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
				{
					RitsuLibFramework.Logger.Warn($"[Search] Expansion provider '{providerEntry.Id}' from '{providerEntry.ModId}' failed: {ex.Message}", 1);
					continue;
				}
				if (readOnlyList == null)
				{
					RitsuLibFramework.Logger.Warn($"[Search] Expansion provider '{providerEntry.Id}' from '{providerEntry.ModId}' returned null.", 1);
					continue;
				}
				int num3 = 0;
				foreach (RitsuSearchExpansion item in readOnlyList)
				{
					if (num3 >= 64 || num >= 8192)
					{
						break;
					}
					if (item != null && !string.Equals(item.Text, text, StringComparison.OrdinalIgnoreCase) && hashSet.Add(item.Text))
					{
						if (num + item.Text.Length > 8192)
						{
							break;
						}
						list.Add(item);
						num3++;
						num += item.Text.Length;
					}
				}
			}
			return list;
		}

		internal static IReadOnlyList<ProviderSnapshot> GetProviderSnapshots()
		{
			ProviderEntry[] source;
			using (SyncRoot.EnterScope())
			{
				source = Providers.Values.OrderBy<ProviderEntry, string>((ProviderEntry entry) => entry.Id, StringComparer.OrdinalIgnoreCase).ToArray();
			}
			List<ProviderSnapshot> list = new List<ProviderSnapshot>();
			list.AddRange(source.Select((ProviderEntry entry) => new ProviderSnapshot(entry.Id, entry.ModId, ResolveDisplayName(entry), RitsuSearchSettingsStore.IsProviderEnabled(entry.Id, entry.EnabledByDefault))));
			return new <>z__ReadOnlyList<ProviderSnapshot>(list);
		}

		internal static void NotifyConfigurationChanged()
		{
			using (SyncRoot.EnterScope())
			{
				_generation++;
			}
		}

		internal static void Invalidate(string providerId, long token)
		{
			using (SyncRoot.EnterScope())
			{
				if (Providers.TryGetValue(providerId, out ProviderEntry value) && value.Token == token)
				{
					_generation++;
				}
			}
		}

		internal static void Unregister(string providerId, long token)
		{
			using (SyncRoot.EnterScope())
			{
				if (Providers.TryGetValue(providerId, out ProviderEntry value) && value.Token == token)
				{
					Providers.Remove(providerId);
					_generation++;
				}
			}
		}

		private static string ResolveDisplayName(ProviderEntry entry)
		{
			try
			{
				string displayName = entry.Provider.DisplayName;
				return (string.IsNullOrWhiteSpace(displayName) || displayName.Length > 256) ? entry.Id : displayName.Trim();
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[Search] Could not resolve display name for provider '" + entry.Id + "': " + ex.Message, 1);
				return entry.Id;
			}
		}

		private static string ValidateProviderId(string value)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(value, "value");
			string text = value.Trim();
			if (text.Length > 128 || text.Any((char character) => !IsProviderIdCharacter(character)))
			{
				throw new ArgumentException("Search expansion provider IDs may contain at most 128 ASCII letters, digits, periods, hyphens, or underscores.", "value");
			}
			return text;
		}

		private static void ValidateDisplayName(string value)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(value, "value");
			if (value.Length > 256)
			{
				throw new ArgumentException($"Search expansion provider display names cannot exceed {256} characters.", "value");
			}
		}

		private static bool IsProviderIdCharacter(char character)
		{
			switch (character)
			{
			case '-':
			case '.':
			case '0':
			case '1':
			case '2':
			case '3':
			case '4':
			case '5':
			case '6':
			case '7':
			case '8':
			case '9':
			case 'A':
			case 'B':
			case 'C':
			case 'D':
			case 'E':
			case 'F':
			case 'G':
			case 'H':
			case 'I':
			case 'J':
			case 'K':
			case 'L':
			case 'M':
			case 'N':
			case 'O':
			case 'P':
			case 'Q':
			case 'R':
			case 'S':
			case 'T':
			case 'U':
			case 'V':
			case 'W':
			case 'X':
			case 'Y':
			case 'Z':
			case '_':
			case 'a':
			case 'b':
			case 'c':
			case 'd':
			case 'e':
			case 'f':
			case 'g':
			case 'h':
			case 'i':
			case 'j':
			case 'k':
			case 'l':
			case 'm':
			case 'n':
			case 'o':
			case 'p':
			case 'q':
			case 'r':
			case 's':
			case 't':
			case 'u':
			case 'v':
			case 'w':
			case 'x':
			case 'y':
			case 'z':
				return true;
			default:
				return false;
			}
		}
	}
	internal sealed class RitsuSearchPreparedText
	{
		private readonly Lock _lock = new Lock();

		private readonly string _text;

		private IReadOnlyList<RitsuSearchExpansion> _expansions = Array.Empty<RitsuSearchExpansion>();

		private Task<IReadOnlyList<RitsuSearchExpansion>>? _expansionTask;

		private long _expansionTaskGeneration = -1L;

		private string _expansionTaskLanguageCode = string.Empty;

		private long _generation = -1L;

		private string _languageCode = string.Empty;

		internal RitsuSearchPreparedText(string text)
		{
			_text = text;
		}

		internal int ScoreExpansion(string term)
		{
			ArgumentNullException.ThrowIfNull(term, "term");
			EnsureCurrent();
			int num = int.MaxValue;
			foreach (RitsuSearchExpansion expansion in _expansions)
			{
				int num2 = expansion.Text.IndexOf(term, StringComparison.OrdinalIgnoreCase);
				if (num2 >= 0)
				{
					num = Math.Min(num, expansion.Kind switch
					{
						RitsuSearchExpansionKind.Transliteration => 0, 
						RitsuSearchExpansionKind.AlternateReading => 30, 
						RitsuSearchExpansionKind.Initialism => 60, 
						_ => 90, 
					} + num2);
				}
			}
			if (num != int.MaxValue)
			{
				return num;
			}
			return -1;
		}

		internal async ValueTask<int> ScoreExpansionAsync(string term, CancellationToken cancellationToken = default(CancellationToken))
		{
			ArgumentNullException.ThrowIfNull(term, "term");
			return ScoreExpansion(await EnsureCurrentAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false), term);
		}

		private void EnsureCurrent()
		{
			long generation = RitsuSearchExpansionRegistry.Generation;
			string text = I18N.ResolveCurrentLanguageCode();
			using (_lock.EnterScope())
			{
				if (_generation != generation || !string.Equals(_languageCode, text, StringComparison.Ordinal))
				{
					_expansions = RitsuSearchExpansionRegistry.Expand(_text, text);
					_generation = generation;
					_languageCode = text;
					_expansionTask = null;
				}
			}
		}

		private async ValueTask<IReadOnlyList<RitsuSearchExpansion>> EnsureCurrentAsync(CancellationToken cancellationToken)
		{
			long generation;
			string languageCode;
			Task<IReadOnlyList<RitsuSearchExpansion>> expansionTask;
			IReadOnlyList<RitsuSearchExpansion> readOnlyList;
			while (true)
			{
				cancellationToken.ThrowIfCancellationRequested();
				generation = RitsuSearchExpansionRegistry.Generation;
				languageCode = I18N.ResolveCurrentLanguageCode();
				using (_lock.EnterScope())
				{
					if (_generation == generation && string.Equals(_languageCode, languageCode, StringComparison.Ordinal))
					{
						return _expansions;
					}
					if (_expansionTaskGeneration != generation || !string.Equals(_expansionTaskLanguageCode, languageCode, StringComparison.Ordinal) || _expansionTask == null)
					{
						_expansionTaskGeneration = generation;
						_expansionTaskLanguageCode = languageCode;
						_expansionTask = Task.Run(() => RitsuSearchExpansionRegistry.Expand(_text, languageCode), CancellationToken.None);
					}
					expansionTask = _expansionTask;
				}
				readOnlyList = await expansionTask.WaitAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (generation == RitsuSearchExpansionRegistry.Generation && string.Equals(languageCode, I18N.ResolveCurrentLanguageCode(), StringComparison.Ordinal))
				{
					break;
				}
			}
			using (_lock.EnterScope())
			{
				if (_expansionTask == expansionTask)
				{
					_expansions = readOnlyList;
					_generation = generation;
					_languageCode = languageCode;
					_expansionTask = null;
				}
				return (_generation == generation && string.Equals(_languageCode, languageCode, StringComparison.Ordinal)) ? _expansions : readOnlyList;
			}
		}

		private static int ScoreExpansion(IReadOnlyList<RitsuSearchExpansion> expansions, string term)
		{
			int num = int.MaxValue;
			foreach (RitsuSearchExpansion expansion in expansions)
			{
				int num2 = expansion.Text.IndexOf(term, StringComparison.OrdinalIgnoreCase);
				if (num2 >= 0)
				{
					num = Math.Min(num, expansion.Kind switch
					{
						RitsuSearchExpansionKind.Transliteration => 0, 
						RitsuSearchExpansionKind.AlternateReading => 30, 
						RitsuSearchExpansionKind.Initialism => 60, 
						_ => 90, 
					} + num2);
				}
			}
			if (num != int.MaxValue)
			{
				return num;
			}
			return -1;
		}
	}
	internal static class RitsuSearchMatcher
	{
		internal static bool Contains(string text, string term, RitsuSearchPreparedText? prepared = null)
		{
			if (!text.Contains(term, StringComparison.CurrentCultureIgnoreCase))
			{
				return (prepared ?? new RitsuSearchPreparedText(text)).ScoreExpansion(term) >= 0;
			}
			return true;
		}

		internal static async ValueTask<bool> ContainsAsync(string text, string term, RitsuSearchPreparedText? prepared = null, CancellationToken cancellationToken = default(CancellationToken))
		{
			if (text.Contains(term, StringComparison.CurrentCultureIgnoreCase))
			{
				return true;
			}
			return await (prepared ?? new RitsuSearchPreparedText(text)).ScoreExpansionAsync(term, cancellationToken).ConfigureAwait(continueOnCapturedContext: false) >= 0;
		}
	}
	internal static class RitsuSearchService
	{
		private static readonly Lock SyncRoot = new Lock();

		private static RitsuSearchExpansionRegistration? _pinyinRegistration;

		private static bool _initialized;

		internal static void Initialize()
		{
			using (SyncRoot.EnterScope())
			{
				if (_initialized)
				{
					return;
				}
				_pinyinRegistration = RitsuSearchExpansionRegistry.Register("com.ritsukage.sts2-RitsuLib", new PinyinSearchExpansionProvider());
				PinyinSearchDataManager.DataChanged += OnPinyinDataChanged;
				_initialized = true;
			}
			Task.Run((Func<Task?>)InitializePinyinDataAsync);
		}

		private static async Task InitializePinyinDataAsync()
		{
			_ = 1;
			try
			{
				await PinyinSearchDataManager.TryLoadCachedAsync().ConfigureAwait(continueOnCapturedContext: false);
				if (PinyinSearchDataManager.Data == null && RitsuSearchSettingsStore.IsProviderEnabled("ritsulib.pinyin", defaultValue: false) && RitsuSearchSettingsStore.GetAutomaticPinyinDataDownloads())
				{
					await PinyinSearchOperationRunner.RunAsync(() => PinyinSearchDataManager.DownloadAndInstallAsync(force: false)).ConfigureAwait(continueOnCapturedContext: false);
				}
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[Search/Pinyin] Background initialization failed: " + ex.Message, 1);
			}
		}

		private static void OnPinyinDataChanged()
		{
			_pinyinRegistration?.Invalidate();
		}
	}
	internal sealed class RitsuSearchSettings
	{
		internal const int CurrentSchemaVersion = 1;

		[JsonPropertyName("schema_version")]
		public int SchemaVersion { get; set; } = 1;

		[JsonPropertyName("provider_enabled")]
		public Dictionary<string, bool> ProviderEnabled { get; set; } = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase);

		[JsonPropertyName("automatic_pinyin_data_downloads")]
		public bool AutomaticPinyinDataDownloads { get; set; }

		[JsonPropertyName("keep_pinyin_source_archive")]
		public bool KeepPinyinSourceArchive { get; set; }
	}
	internal static class RitsuSearchSettingsStore
	{
		internal const string DataKey = "search-settings";

		internal const string FileName = "ritsulib-search-settings.json";

		private static readonly Lock SyncRoot = new Lock();

		private static ModDataStore? _store;

		internal static void Register(ModDataStore store)
		{
			ArgumentNullException.ThrowIfNull(store, "store");
			using (SyncRoot.EnterScope())
			{
				if (_store == null)
				{
					store.Register("search-settings", "ritsulib-search-settings.json", SaveScope.Global, () => new RitsuSearchSettings(), autoCreateIfMissing: true, new ModDataMigrationConfig
					{
						CurrentDataVersion = 1,
						MinimumSupportedDataVersion = 1
					});
					_store = store;
				}
			}
		}

		internal static bool IsProviderEnabled(string providerId, bool defaultValue)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(providerId, "providerId");
			using (SyncRoot.EnterScope())
			{
				RitsuSearchSettings settings = GetSettings();
				if (settings.ProviderEnabled.TryGetValue(providerId, out var value))
				{
					return value;
				}
				foreach (var (a, result) in settings.ProviderEnabled)
				{
					if (string.Equals(a, providerId, StringComparison.OrdinalIgnoreCase))
					{
						return result;
					}
				}
				return defaultValue;
			}
		}

		internal static void SetProviderEnabled(string providerId, bool enabled)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(providerId, "providerId");
			using (SyncRoot.EnterScope())
			{
				RitsuSearchSettings settings = GetSettings();
				string text = settings.ProviderEnabled.Keys.FirstOrDefault((string id) => string.Equals(id, providerId, StringComparison.OrdinalIgnoreCase));
				if (text != null && !string.Equals(text, providerId, StringComparison.Ordinal))
				{
					settings.ProviderEnabled.Remove(text);
				}
				settings.ProviderEnabled[providerId] = enabled;
				Save();
			}
			RitsuSearchExpansionRegistry.NotifyConfigurationChanged();
		}

		internal static bool GetAutomaticPinyinDataDownloads()
		{
			using (SyncRoot.EnterScope())
			{
				return GetSettings().AutomaticPinyinDataDownloads;
			}
		}

		internal static void SetAutomaticPinyinDataDownloads(bool value)
		{
			using (SyncRoot.EnterScope())
			{
				RitsuSearchSettings settings = GetSettings();
				if (settings.AutomaticPinyinDataDownloads != value)
				{
					settings.AutomaticPinyinDataDownloads = value;
					Save();
				}
			}
		}

		internal static bool GetKeepPinyinSourceArchive()
		{
			using (SyncRoot.EnterScope())
			{
				return GetSettings().KeepPinyinSourceArchive;
			}
		}

		internal static void SetKeepPinyinSourceArchive(bool value)
		{
			using (SyncRoot.EnterScope())
			{
				RitsuSearchSettings settings = GetSettings();
				if (settings.KeepPinyinSourceArchive != value)
				{
					settings.KeepPinyinSourceArchive = value;
					Save();
				}
			}
		}

		private static RitsuSearchSettings GetSettings()
		{
			if (_store == null)
			{
				throw new InvalidOperationException("Ritsu search settings have not been registered.");
			}
			return _store.Get<RitsuSearchSettings>("search-settings");
		}

		private static void Save()
		{
			_store.Save("search-settings");
		}
	}
