	internal static class PinyinSearchDataCompiler
	{
		private sealed class ReadingAccumulator
		{
			private readonly List<string> _readings = new List<string>();

			private readonly HashSet<string> _seen = new HashSet<string>(StringComparer.Ordinal);

			private string? _primary;

			internal void Add(string value, bool preferred)
			{
				int length = value.Length;
				if ((length <= 24 && length != 0) || 1 == 0)
				{
					if (preferred && _primary == null)
					{
						_primary = value;
					}
					if (_seen.Add(value) && _readings.Count < 32)
					{
						_readings.Add(value);
					}
				}
			}

			internal string[] Build()
			{
				if (_readings.Count == 0)
				{
					return Array.Empty<string>();
				}
				string primary = _primary ?? _readings[0];
				List<string> list = new List<string>();
				list.Add(primary);
				list.AddRange(_readings.Where((string reading) => !string.Equals(reading, primary, StringComparison.Ordinal)).Take(31));
				return list.ToArray();
			}
		}

		private const int MaximumArchiveEntries = 64;

		private const long MaximumArchiveUncompressedBytes = 134217728L;

		private const int MaximumInputLineLength = 8192;

		private const int MaximumReadingsPerCodePoint = 32;

		private static readonly HashSet<string> SupportedProperties = new HashSet<string> { "kMandarin", "kHanyuPinyin", "kXHC1983" };

		internal static IReadOnlyDictionary<int, string[]> Compile(string archivePath)
		{
			using ZipArchive zipArchive = ZipFile.OpenRead(archivePath);
			int key = zipArchive.Entries.Count;
			bool flag = ((key > 64 || key == 0) ? true : false);
			if (flag || zipArchive.Entries.Sum((ZipArchiveEntry entry) => entry.Length) > 134217728)
			{
				throw new InvalidDataException("The Unihan archive has invalid resource bounds.");
			}
			Dictionary<int, ReadingAccumulator> dictionary = new Dictionary<int, ReadingAccumulator>();
			foreach (ZipArchiveEntry entry in zipArchive.Entries)
			{
				if (entry.Name.StartsWith("Unihan_", StringComparison.Ordinal) && entry.Name.EndsWith(".txt", StringComparison.OrdinalIgnoreCase))
				{
					ParseEntry(entry, dictionary);
				}
			}
			Dictionary<int, string[]> dictionary2 = new Dictionary<int, string[]>(dictionary.Count);
			foreach (KeyValuePair<int, ReadingAccumulator> item in dictionary)
			{
				item.Deconstruct(out key, out var value);
				int key2 = key;
				string[] array = value.Build();
				if (array.Length != 0)
				{
					dictionary2.Add(key2, array);
				}
			}
			if (dictionary2.Count == 0)
			{
				throw new InvalidDataException("The Unihan archive did not contain supported Mandarin readings.");
			}
			return dictionary2;
		}

		private static void ParseEntry(ZipArchiveEntry entry, IDictionary<int, ReadingAccumulator> entries)
		{
			using Stream stream = entry.Open();
			using StreamReader streamReader = new StreamReader(stream, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false, throwOnInvalidBytes: true), true, 65536, false);
			while (true)
			{
				string text = streamReader.ReadLine();
				if (text == null)
				{
					break;
				}
				if (text.Length == 0 || text[0] == '#')
				{
					continue;
				}
				if (text.Length > 8192)
				{
					throw new InvalidDataException("The Unihan archive contains an overlong input line.");
				}
				string[] array = text.Split('\t');
				if (array.Length == 3 && SupportedProperties.Contains(array[1]))
				{
					if (!array[0].StartsWith("U+", StringComparison.Ordinal) || !int.TryParse(array[0].AsSpan(2), NumberStyles.AllowHexSpecifier, CultureInfo.InvariantCulture, out var result) || !Rune.IsValid(result))
					{
						throw new InvalidDataException("The Unihan archive contains an invalid code point.");
					}
					if (!entries.TryGetValue(result, out ReadingAccumulator value))
					{
						value = new ReadingAccumulator();
						entries.Add(result, value);
					}
					AddPropertyReadings(value, array[1], array[2]);
				}
			}
		}

		private static void AddPropertyReadings(ReadingAccumulator accumulator, string property, string value)
		{
			string[] array;
			if (property == "kMandarin")
			{
				bool preferred = true;
				array = value.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
				foreach (string value2 in array)
				{
					accumulator.Add(NormalizeReading(value2), preferred);
					preferred = false;
				}
				return;
			}
			array = value.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
			foreach (string text in array)
			{
				int num = text.IndexOf(':');
				if (num >= 0 && num != text.Length - 1)
				{
					string[] array2 = text.Substring(num + 1).Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
					foreach (string value3 in array2)
					{
						accumulator.Add(NormalizeReading(value3), preferred: false);
					}
				}
			}
		}

		private static string NormalizeReading(string value)
		{
			string text = value.Replace('ü', 'v').Replace('ǖ', 'v').Replace('ǘ', 'v')
				.Replace('ǚ', 'v')
				.Replace('ǜ', 'v')
				.Normalize(NormalizationForm.FormD);
			StringBuilder stringBuilder = new StringBuilder(text.Length);
			string text2 = text;
			foreach (char c in text2)
			{
				if (CharUnicodeInfo.GetUnicodeCategory(c) != UnicodeCategory.NonSpacingMark)
				{
					char c2 = char.ToLowerInvariant(c);
					if (c2 >= 'a' && c2 <= 'z')
					{
						stringBuilder.Append(c2);
					}
				}
			}
			return stringBuilder.ToString();
		}
	}
