		internal static async Task DownloadAndInstallAsync(bool force, CancellationToken cancellationToken = default(CancellationToken))
		{
			await OperationGate.WaitAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			try
			{
				await using (await RitsuLibDataPaths.AcquireSharedCacheLockAsync("pinyin-data.lock", cancellationToken).ConfigureAwait(continueOnCapturedContext: false))
				{
					PinyinSearchDataSource source = PinyinSearchDataSource.Current;
					RitsuLibDataPaths.EnsureSharedCacheDirectory();
					RitsuLibDataPaths.EnsureTemporaryDirectory();
					string compiledPath = GetCachePath("pinyin-data.v1.bin");
					if (!force && File.Exists(compiledPath))
					{
						try
						{
							Volatile.Write(ref _data, await Task.Run(() => PinyinSearchData.Load(compiledPath, source), cancellationToken).ConfigureAwait(continueOnCapturedContext: false));
							SetReadyStatus();
							DataChanged?.Invoke();
						}
						catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
						{
