					string temporaryGeneratedPath = GetTemporaryPath("pinyin-data.generate.tmp");
					DeleteIfExists(temporaryDownloadPath);
					DeleteIfExists(temporaryGeneratedPath);
					string generationSourcePath = await AcquireSourceArchiveAsync(sourceArchivePath, temporaryDownloadPath, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
