						}, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						PinyinSearchData pinyinSearchData = await Task.Run(() => PinyinSearchData.Load(temporaryGeneratedPath, source), cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
