						}
						SetReadyStatus();
						DataChanged?.Invoke();
						RitsuLibFramework.Logger.Info($"[Search/Pinyin] Unicode {source.UnicodeVersion} data is ready ({pinyinSearchData.Count} code points).", 1);
					}
					finally
					{
						DeleteIfExists(temporaryDownloadPath);
						DeleteIfExists(temporaryGeneratedPath);
					}
				}
			}
			catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
			{
