					{
						IReadOnlyDictionary<int, string[]> readings = await Task.Run(() => PinyinSearchDataCompiler.Compile(sourcePath), cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						await Task.Run(delegate
						{
							PinyinSearchData.Write(temporaryGeneratedPath, source, readings);
						}, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						PinyinSearchData value = PinyinSearchData.Load(temporaryGeneratedPath, source);
						PublishTemporaryFile(temporaryGeneratedPath, compiledPath);
						Volatile.Write(ref _data, value);
						SetReadyStatus();
						DataChanged?.Invoke();
					}
					finally
					{
						DeleteIfExists(temporaryGeneratedPath);
					}
				}
			}
			catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
			{
				throw;
			}
			catch (Exception ex2) when (RitsuLibExceptionPolicy.IsRecoverable(ex2))
			{
				SetFailure(ex2);
				throw;
			}
			finally
			{
				OperationGate.Release();
			}
		}

		internal static async Task DeleteCachedDataAsync(CancellationToken cancellationToken = default(CancellationToken))
		{
			await OperationGate.WaitAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			try
			{
				await using (await RitsuLibDataPaths.AcquireSharedCacheLockAsync("pinyin-data.lock", cancellationToken).ConfigureAwait(continueOnCapturedContext: false))
				{
					Volatile.Write(ref _data, null);
					string[] array = new string[2] { "pinyin-data.v1.bin", "pinyin-unihan.zip" };
					for (int i = 0; i < array.Length; i++)
					{
						DeleteIfExists(GetCachePath(array[i]));
					}
					array = new string[2] { "pinyin-unihan.download.tmp", "pinyin-data.generate.tmp" };
					for (int i = 0; i < array.Length; i++)
					{
						DeleteIfExists(GetTemporaryPath(array[i]));
					}
					SetStatus(PinyinSearchDataState.NotInstalled, 0L, 0L, 0L);
					DataChanged?.Invoke();
				}
			}
			finally
			{
				OperationGate.Release();
			}
		}

		private static async Task<string> AcquireSourceArchiveAsync(string cachedPath, string temporaryPath, CancellationToken cancellationToken)
		{
			if (File.Exists(cachedPath))
			{
				try
				{
					await ValidateSourceArchiveAsync(cachedPath, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					return cachedPath;
				}
				catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
				{
					RitsuLibFramework.Logger.Warn("[Search/Pinyin] Cached Unicode source is invalid and will be replaced: " + ex.Message, 1);
				}
			}
			PinyinSearchDataSource source = PinyinSearchDataSource.Current;
			SetStatus(PinyinSearchDataState.Downloading, 0L, source.ExpectedLength, 0L);
			using HttpResponseMessage response = await Client.GetAsync(source.SourceUri, HttpCompletionOption.ResponseHeadersRead, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			response.EnsureSuccessStatusCode();
			long? contentLength = response.Content.Headers.ContentLength;
			bool flag;
			if (contentLength.HasValue)
			{
				long valueOrDefault = contentLength.GetValueOrDefault();
				if (valueOrDefault <= 0 || valueOrDefault > 16777216)
				{
					flag = true;
					goto IL_020e;
				}
			}
			flag = false;
			goto IL_020e;
			IL_020e:
			if (flag)
			{
				throw new InvalidDataException("The Unicode source download has an invalid content length.");
			}
			string result;
			await using (Stream input = await response.Content.ReadAsStreamAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false))
			{
				string text;
				await using (FileStream output = new FileStream(temporaryPath, FileMode.CreateNew, FileAccess.Write, FileShare.None, 65536, FileOptions.Asynchronous | FileOptions.SequentialScan))
				{
					using IncrementalHash hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
					byte[] buffer = new byte[65536];
					long total = 0L;
					while (true)
					{
						int num = await input.ReadAsync(buffer, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						if (num == 0)
						{
							break;
						}
						total += num;
						if (total > 16777216)
						{
							throw new InvalidDataException("The Unicode source download exceeded the size limit.");
						}
						hash.AppendData(buffer, 0, num);
						await output.WriteAsync(buffer.AsMemory(0, num), cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						SetStatus(PinyinSearchDataState.Downloading, total, source.ExpectedLength, 0L);
					}
					await output.FlushAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					output.Flush(flushToDisk: true);
					string a = Convert.ToHexString(hash.GetHashAndReset());
					if (total != source.ExpectedLength || !string.Equals(a, source.ExpectedSha256, StringComparison.OrdinalIgnoreCase))
					{
						throw new InvalidDataException("The Unicode source download failed its pinned integrity check.");
					}
					if (RitsuSearchSettingsStore.GetKeepPinyinSourceArchive())
					{
						PublishTemporaryFile(temporaryPath, cachedPath);
						text = cachedPath;
					}
					else
					{
						text = temporaryPath;
					}
				}
				result = text;
			}
			return result;
		}

		private static async Task ValidateSourceArchiveAsync(string path, CancellationToken cancellationToken)
		{
			PinyinSearchDataSource source = PinyinSearchDataSource.Current;
			FileInfo fileInfo = new FileInfo(path);
			if (!fileInfo.Exists || fileInfo.Length != source.ExpectedLength)
			{
				throw new InvalidDataException("The cached Unicode source has an invalid size.");
			}
			await using FileStream stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read, 65536, FileOptions.Asynchronous | FileOptions.SequentialScan);
			if (!string.Equals(Convert.ToHexString(await SHA256.HashDataAsync(stream, cancellationToken).ConfigureAwait(continueOnCapturedContext: false)), source.ExpectedSha256, StringComparison.OrdinalIgnoreCase))
			{
				throw new InvalidDataException("The cached Unicode source failed its pinned integrity check.");
			}
		}

		private static HttpClient CreateClient()
		{
			return new HttpClient
			{
				Timeout = TimeSpan.FromSeconds(90L),
				DefaultRequestHeaders = 
				{
					UserAgent = 
					{
						new ProductInfoHeaderValue("STS2-RitsuLib", "0.5.18")
					}
				}
			};
		}

		private static string GetCacheDirectory()
		{
			return RitsuLibDataPaths.SharedCacheDirectory;
		}

		private static string GetCachePath(string fileName)
		{
			return Path.Combine(GetCacheDirectory(), fileName);
		}

		private static string GetTemporaryPath(string fileName)
		{
			return Path.Combine(RitsuLibDataPaths.TemporaryDirectory, fileName);
		}

		private static void SetReadyStatus()
		{
			string cachePath = GetCachePath("pinyin-data.v1.bin");
			string cachePath2 = GetCachePath("pinyin-unihan.zip");
			long cacheBytes = GetFileLength(cachePath) + GetFileLength(cachePath2);
			SetStatus(PinyinSearchDataState.Ready, 0L, 0L, cacheBytes, File.Exists(cachePath2));
		}

		private static void SetNotInstalledStatus()
		{
			string cachePath = GetCachePath("pinyin-unihan.zip");
			SetStatus(PinyinSearchDataState.NotInstalled, 0L, 0L, GetFileLength(cachePath), File.Exists(cachePath));
		}

		private static void SetFailure(Exception exception)
		{
			string cachePath = GetCachePath("pinyin-unihan.zip");
			SetStatus(PinyinSearchDataState.Failed, 0L, 0L, GetFileLength(GetCachePath("pinyin-data.v1.bin")) + GetFileLength(cachePath), File.Exists(cachePath), exception.Message);
		}

		private static void SetStatus(PinyinSearchDataState state, long bytesReceived = 0L, long totalBytes = 0L, long cacheBytes = 0L, bool sourceArchiveCached = false, string? error = null)
		{
			using (StateLock.EnterScope())
			{
				_status = new PinyinSearchDataStatus(state, PinyinSearchDataSource.Current.UnicodeVersion, bytesReceived, totalBytes, cacheBytes, sourceArchiveCached, error);
			}
		}

		private static long GetFileLength(string path)
		{
			if (!File.Exists(path))
			{
				return 0L;
			}
			return new FileInfo(path).Length;
		}

		private static void EnsureCachedDataStillInstalled(bool force)
		{
			PinyinSearchData pinyinSearchData = Volatile.Read(in _data);
			if (pinyinSearchData == null)
			{
				return;
			}
			long tickCount = Environment.TickCount64;
			long num = Volatile.Read(in _nextCachePresenceCheck);
			if (!force)
			{
				if (tickCount < num || Interlocked.CompareExchange(ref _nextCachePresenceCheck, tickCount + 1000, num) != num)
				{
					return;
				}
			}
			else
			{
				Volatile.Write(ref _nextCachePresenceCheck, tickCount + 1000);
			}
			if (!File.Exists(GetCachePath("pinyin-data.v1.bin")) && Interlocked.CompareExchange(ref _data, null, pinyinSearchData) == pinyinSearchData)
			{
				SetNotInstalledStatus();
				DataChanged?.Invoke();
				RitsuLibFramework.Logger.Warn("[Search/Pinyin] Generated cache disappeared; the provider returned to the uninitialized state.", 1);
			}
		}

		private static void DeleteIfExists(string path)
		{
			if (File.Exists(path))
			{
				File.Delete(path);
			}
		}

		private static void PublishTemporaryFile(string temporaryPath, string destinationPath)
		{
			try
			{
				File.Copy(temporaryPath, destinationPath, overwrite: true);
			}
			catch
			{
				DeleteIfExists(destinationPath);
				throw;
			}
			DeleteIfExists(temporaryPath);
		}
	}
	internal static class PinyinSearchOperationRunner
	{
		private sealed class ProgressToast
		{
			private readonly Lock _syncRoot = new Lock();

			private bool _completed;

			private RitsuToastHandle? _handle;

			private PinyinSearchDataStatus? _latestStatus;

			private bool _updateQueued;

			internal void Start()
			{
				PostToMainLoop(delegate
				{
					using (_syncRoot.EnterScope())
					{
						if (!_completed)
						{
							_handle = RitsuToastService.ShowTracked(BuildProgressRequest(PinyinSearchDataManager.GetStatus()));
							PinyinSearchDataStatus latestStatus = _latestStatus;
							if ((object)latestStatus != null)
							{
								UpdateNow(latestStatus);
							}
						}
					}
				});
			}

			internal void Report(PinyinSearchDataStatus status)
			{
				using (_syncRoot.EnterScope())
				{
					if (_completed)
					{
						return;
					}
					_latestStatus = status;
					if (_updateQueued)
					{
						return;
					}
					_updateQueued = true;
				}
				PostToMainLoop(delegate
				{
					using (_syncRoot.EnterScope())
					{
						_updateQueued = false;
						if (!_completed)
						{
							PinyinSearchDataStatus latestStatus = _latestStatus;
							if ((object)latestStatus != null)
							{
								if (_handle == null)
								{
									_handle = RitsuToastService.ShowTracked(BuildProgressRequest(latestStatus));
								}
								else
								{
									UpdateNow(latestStatus);
								}
							}
						}
					}
				});
			}

			internal void CompleteSuccess()
			{
				Complete(new RitsuToastRequest(L("ritsulib.searchExtensions.operation.success", "Pinyin search is ready."), L("ritsulib.searchExtensions.pinyin.toast.title", "Mandarin pinyin")).WithProgress(1f).Persistent(isPersistent: false));
			}

			internal void CompleteFailure(Exception exception)
			{
				string body = string.Format(L("ritsulib.searchExtensions.operation.failed", "Pinyin search could not be prepared: {0}"), exception.Message);
				Complete(RitsuToastRequest.Warning(body, L("ritsulib.searchExtensions.pinyin.toast.title", "Mandarin pinyin")).WithProgress(null).Persistent(isPersistent: false));
			}

			private void Complete(RitsuToastRequest request)
			{
				PostToMainLoop(delegate
				{
					using (_syncRoot.EnterScope())
					{
						_completed = true;
						RitsuToastHandle? handle = _handle;
						if (handle == null || !handle.Update(request))
						{
							RitsuToastService.Show(request);
						}
					}
				});
			}

			private void UpdateNow(PinyinSearchDataStatus status)
			{
				_handle?.Update(BuildProgressRequest(status), resetDuration: false);
			}

			private static RitsuToastRequest BuildProgressRequest(PinyinSearchDataStatus status)
			{
				string body = status.State switch
				{
					PinyinSearchDataState.Downloading => string.Format(L("ritsulib.searchExtensions.pinyin.toast.downloading", "Downloading: {1} / {2}"), status.UnicodeVersion, FormatBytes(status.BytesReceived), FormatBytes(status.TotalBytes)), 
					PinyinSearchDataState.Generating => L("ritsulib.searchExtensions.pinyin.toast.generating", "Finishing setup..."), 
					PinyinSearchDataState.Loading => L("ritsulib.searchExtensions.pinyin.toast.loading", "Loading pinyin search..."), 
					_ => L("ritsulib.searchExtensions.pinyin.toast.preparing", "Preparing pinyin search..."), 
				};
				float num;
				switch (status.State)
				{
				case PinyinSearchDataState.Downloading:
					if (status.TotalBytes > 0)
					{
						num = 0.05f + 0.8f * Mathf.Clamp((float)status.BytesReceived / (float)status.TotalBytes, 0f, 1f);
						break;
					}
					goto default;
				case PinyinSearchDataState.Generating:
					num = 0.9f;
					break;
				case PinyinSearchDataState.Ready:
					num = 1f;
					break;
				default:
					num = 0f;
					break;
				}
				float value = num;
				return new RitsuToastRequest(body, L("ritsulib.searchExtensions.pinyin.toast.title", "Mandarin pinyin")).Persistent().WithDismissOnClick(dismissOnClick: false).WithProgress(value);
			}
		}

		private static readonly TimeSpan RefreshInterval = TimeSpan.FromMilliseconds(150L, 0L);

		internal static async Task RunAsync(Func<Task> operation, Action? onSuccess = null, Action? onStatusUpdated = null)
		{
			ArgumentNullException.ThrowIfNull(operation, "operation");
			ProgressToast progressToast = new ProgressToast();
			progressToast.Start();
			try
			{
				Task task = operation() ?? throw new InvalidOperationException("The pinyin data operation returned no task.");
				while (!task.IsCompleted)
				{
					progressToast.Report(PinyinSearchDataManager.GetStatus());
					onStatusUpdated?.Invoke();
					await Task.WhenAny(task, Task.Delay(RefreshInterval));
				}
				await task;
				onSuccess?.Invoke();
				onStatusUpdated?.Invoke();
				progressToast.CompleteSuccess();
			}
			catch (Exception exception)
			{
				progressToast.CompleteFailure(exception);
				throw;
			}
		}

		private static string L(string key, string fallback)
		{
			return ModSettingsLocalization.Get(key, fallback);
		}

		private static string FormatBytes(long bytes)
		{
			if (bytes >= 1024)
			{
				if (bytes < 1048576)
				{
					return $"{(double)bytes / 1024.0:F1} KiB";
				}
				return $"{(double)bytes / 1048576.0:F1} MiB";
			}
			return $"{bytes} B";
		}

		private static void PostToMainLoop(Action action)
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			if (Engine.GetMainLoop() is SceneTree)
			{
				Callable val = Callable.From(action);
				((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			}
			else
			{
				action();
			}
		}
	}
	internal sealed record PinyinSearchDataSource(string UnicodeVersion, Uri SourceUri, long ExpectedLength, string ExpectedSha256)
	{
		internal static PinyinSearchDataSource Current { get; } = new PinyinSearchDataSource("17.0.0", new Uri("https://www.unicode.org/Public/17.0.0/ucd/Unihan.zip"), 8518517L, "F7A48B2B545ACFAA77B2D607AE28747404CE02BAEFEE16396C5D2D7A8EF34B5E");
	}
	internal sealed class PinyinSearchExpansionProvider : IRitsuSearchExpansionProvider
	{
		private sealed record Variant(string Full, string Initials);

		internal const string ProviderId = "ritsulib.pinyin";

		private const int MaximumVariantsPerRun = 24;

		private const int MaximumRunesPerRun = 64;

		public string Id => "ritsulib.pinyin";

		public string DisplayName => ModSettingsLocalization.Get("ritsulib.searchProviders.pinyin.name", "Mandarin pinyin");

		public bool EnabledByDefault => false;

		public IReadOnlyList<RitsuSearchExpansion> Expand(string text, RitsuSearchExpansionContext context)
		{
			ArgumentNullException.ThrowIfNull(text, "text");
			ArgumentNullException.ThrowIfNull(context, "context");
			PinyinSearchData data = PinyinSearchDataManager.Data;
			if (data == null || text.Length == 0)
			{
				return Array.Empty<RitsuSearchExpansion>();
			}
			List<RitsuSearchExpansion> list = new List<RitsuSearchExpansion>();
			HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			List<string[]> list2 = new List<string[]>();
			List<string[]> list3 = new List<string[]>();
			int num = 0;
			foreach (Rune item in text.EnumerateRunes())
			{
				if (data.TryGetReadings(item, out string[] readings))
				{
					list2.Add(readings);
					list3.Add(readings);
					if (list2.Count == 64)
					{
						FlushRun(list2, list, seen);
						num++;
					}
					if (list3.Count == 64)
					{
						FlushRun(list3, list, seen);
					}
				}
				else
				{
					if (list2.Count > 0)
					{
						num++;
					}
					FlushRun(list2, list, seen);
				}
			}
			if (list2.Count > 0)
			{
				num++;
			}
			FlushRun(list2, list, seen);
			if (num > 1)
			{
				FlushRun(list3, list, seen);
			}
			return list;
		}

		private static void FlushRun(List<string[]> run, ICollection<RitsuSearchExpansion> expansions, ISet<string> seen)
		{
			if (run.Count == 0)
			{
				return;
			}
			int num = 1;
			List<Variant> list = new List<Variant>(num);
			CollectionsMarshal.SetCount(list, num);
			CollectionsMarshal.AsSpan(list)[0] = new Variant(string.Empty, string.Empty);
			List<Variant> list2 = list;
			foreach (string[] item2 in run)
			{
				List<Variant> list3 = new List<Variant>(Math.Min(24, list2.Count * item2.Length));
				foreach (Variant item3 in list2)
				{
					string[] array = item2;
					foreach (string text in array)
					{
						Variant item = new Variant(item3.Full + text, item3.Initials + text[0]);
						if (!list3.Contains(item))
						{
							list3.Add(item);
						}
						if (list3.Count >= 24)
						{
							break;
						}
					}
					if (list3.Count >= 24)
					{
						break;
					}
				}
				list2 = list3;
			}
			for (int i = 0; i < list2.Count; i++)
			{
				Variant variant = list2[i];
				AddExpansion(variant.Full, (i != 0) ? RitsuSearchExpansionKind.AlternateReading : RitsuSearchExpansionKind.Transliteration, expansions, seen);
				AddExpansion(variant.Initials, RitsuSearchExpansionKind.Initialism, expansions, seen);
				if (variant.Full.Contains('v'))
				{
					AddExpansion(variant.Full.Replace('v', 'u'), (i != 0) ? RitsuSearchExpansionKind.AlternateReading : RitsuSearchExpansionKind.Transliteration, expansions, seen);
				}
			}
			run.Clear();
		}

		private static void AddExpansion(string value, RitsuSearchExpansionKind kind, ICollection<RitsuSearchExpansion> expansions, ISet<string> seen)
		{
			if (value.Length != 0 && value.Length <= 512 && seen.Add(value))
			{
				expansions.Add(new RitsuSearchExpansion(value, kind));
			}
		}
	}
}
namespace STS2RitsuLib.Screens
{
	/// <summary>
	///     <para xml:lang="en">
	///         Opens, closes, and queries custom <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.Capstones.ICapstoneScreen" /> instances through
	///         <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.Capstones.NCapstoneContainer" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过 <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.Capstones.NCapstoneContainer" /> 打开、关闭和查询自定义
	///         <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.Capstones.ICapstoneScreen" /> 实例。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Operations return <see langword="false" /> when the scene-owned container is unavailable. Opening a
	///         screen replaces a different current screen and leaves an already-current instance unchanged.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         场景持有的容器不可用时，操作返回 <see langword="false" />。打开屏幕会替换其他当前屏幕；
	///         已是当前屏幕的实例保持不变。
	///     </para>
	/// </remarks>
	public static class ModScreenService
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets the current Capstone screen, or <see langword="null" /> when the container is idle or
		///         unavailable.
		///     </para>
		///     <para xml:lang="zh-CN">获取当前 Capstone 屏幕；容器空闲或不可用时为 <see langword="null" />。</para>
		/// </summary>
		public static ICapstoneScreen? CurrentCapstoneScreen
		{
			get
			{
				NCapstoneContainer instance = NCapstoneContainer.Instance;
				if (instance == null)
				{
					return null;
				}
				return instance.CurrentCapstoneScreen;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether a Capstone screen is currently open.</para>
		///     <para xml:lang="zh-CN">获取当前是否打开了 Capstone 屏幕。</para>
		/// </summary>
		public static bool IsCapstoneOpen
		{
			get
			{
				NCapstoneContainer instance = NCapstoneContainer.Instance;
				if (instance != null)
				{
					return instance.InUse;
				}
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Mounts <paramref name="screen" /> in <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.Capstones.NCapstoneContainer" />. Opening the screen
		///         replaces a different current screen; opening the already current instance is a no-op.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将 <paramref name="screen" /> 挂载到 <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.Capstones.NCapstoneContainer" /> 中。打开该屏幕会替换不同的
		///         当前屏幕；打开已是当前实例的屏幕时不执行任何操作。
		///     </para>
		/// </summary>
		/// <param name="screen">
		///     <para xml:lang="en">The screen to mount, which must also be a Godot <see cref="T:Godot.Node" />.</para>
		///     <para xml:lang="zh-CN">要挂载的屏幕，且其也必须是 Godot <see cref="T:Godot.Node" />。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if <paramref name="screen" /> is current after the call; otherwise,
		///         <see langword="false" /> when the container is unavailable.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         调用后 <paramref name="screen" /> 为当前屏幕时返回 <see langword="true" />；容器不可用时返回
		///         <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool Open(ICapstoneScreen screen)
		{
			ArgumentNullException.ThrowIfNull(screen, "screen");
			NCapstoneContainer instance = NCapstoneContainer.Instance;
			if (instance == null)
			{
				return false;
			}
			if (instance.CurrentCapstoneScreen == screen)
			{
				return true;
			}
			instance.Open(screen);
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Closes the current Capstone screen, if any.</para>
		///     <para xml:lang="zh-CN">关闭当前 Capstone 屏幕（如果存在）。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> if an open screen was closed; otherwise, <see langword="false" />.</para>
		///     <para xml:lang="zh-CN">关闭了已打开的屏幕时返回 <see langword="true" />；否则返回 <see langword="false" />。</para>
		/// </returns>
		public static bool Close()
		{
			NCapstoneContainer instance = NCapstoneContainer.Instance;
			if (instance == null || !instance.InUse)
			{
				return false;
			}
			instance.Close();
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Closes <paramref name="screen" /> when it is current; otherwise opens it.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="screen" /> 为当前屏幕时将其关闭；否则打开它。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if the requested open or close operation succeeded; otherwise,
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         请求的打开或关闭操作成功时返回 <see langword="true" />；否则返回 <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool Toggle(ICapstoneScreen screen)
		{
			ArgumentNullException.ThrowIfNull(screen, "screen");
			if (CurrentCapstoneScreen != screen)
			{
				return Open(screen);
			}
			return Close();
		}
	}
}
