		internal bool TryStart(Sprite2D sprite, VisualFrameSequence sequence)
		{
			StopAndReset();
			if (sequence.Frames.Count == 0)
			{
				return false;
			}
			VisualFrame[] array = new VisualFrame[sequence.Frames.Count];
			for (int i = 0; i < sequence.Frames.Count; i++)
			{
				VisualFrame visualFrame = sequence.Frames[i];
				if (string.IsNullOrWhiteSpace(visualFrame.TexturePath))
				{
					return false;
				}
				array[i] = visualFrame;
			}
			_sprite = sprite;
			_frames = array;
