			_loadFailed = new bool[array.Length];
			_loop = sequence.Loop;
			_index = 0;
			_carry = 0.0;
			_frameDurationSeconds = ClampFrameDuration(array[0].DurationSeconds);
			if (!ApplyFrame(0))
			{
				StopAndReset();
				return false;
			}
			_active = true;
			((Node)this).SetProcess(true);
			return true;
		}

		internal bool TryGetRemaining(out float seconds)
		{
			seconds = 0f;
			if (!_active || _frames.Length == 0 || _index < 0 || _index >= _frames.Length)
			{
				return false;
