			double num = Math.Max(0.0, _frameDurationSeconds - _carry);
			for (int i = _index + 1; i < _frames.Length; i++)
			{
				num += ClampFrameDuration(_frames[i].DurationSeconds);
			}
			if (!double.IsFinite(num) || num < 0.0 || num > 3.4028234663852886E+38)
			{
				return false;
