				_frameDurationSeconds = ClampFrameDuration(_frames[_index].DurationSeconds);
			}
			else if (_loop)
			{
				_index = 0;
				ApplyFrame(0);
				_frameDurationSeconds = ClampFrameDuration(_frames[0].DurationSeconds);
			}
			else
			{
				_active = false;
				((Node)this).SetProcess(false);
				((GodotObject)this).EmitSignal(SignalName.Finished, Array.Empty<Variant>());
			}
