		private static double ClampFrameDuration(float seconds)
		{
			if (float.IsFinite(seconds) && !(seconds <= 0f))
			{
				return seconds;
			}
			return 1.0 / 60.0;
		}

		private bool ApplyFrame(int i)
		{
			if (_sprite == null || i < 0 || i >= _frames.Length)
			{
				return false;
			}
			Texture2D val = _cache[i];
			if (val == null)
			{
				if (_loadFailed[i])
				{
					return false;
				}
				val = ResourceLoader.Load<Texture2D>(_frames[i].TexturePath, (string)null, (CacheMode)1);
				if (val == null)
				{
					_loadFailed[i] = true;
					return false;
				}
				_cache[i] = val;
