			_sprite.Texture = val;
			(((_frameStyles.Length > i) ? _frameStyles[i] : null) ?? _defaultStyle).ApplyTo((Node?)(object)_sprite);
			return true;
		}

		private static VisualNodeStyle?[] BuildFrameStyleArray(VisualFrameSequence sequence, int frameCount)
		{
			if (frameCount == 0)
			{
				return Array.Empty<VisualNodeStyle>();
			}
			IReadOnlyList<VisualNodeStyle> frameStyles = sequence.FrameStyles;
			if (frameStyles == null || frameStyles.Count == 0)
			{
				return new VisualNodeStyle[frameCount];
			}
			VisualNodeStyle[] array = new VisualNodeStyle[frameCount];
			int num = Math.Min(frameCount, frameStyles.Count);
			for (int i = 0; i < num; i++)
			{
				array[i] = frameStyles[i];
			}
			return array;
		}

