namespace STS2RitsuLib.Scaffolding.Visuals.StateMachine
{
	/// <summary>
	///     <para xml:lang="en">
	///         Builds animation backends from nodes beneath a visuals root, in priority order: cue frames or static textures,
	///         Spine, a Godot animation-tree state machine, a Godot animation player, and a Godot animated sprite.
	///         Multiple discovered backends are combined into <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CompositeAnimationBackend" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         按优先级从视觉效果根节点下构建动画后端：视觉提示帧或静态纹理、Spine、Godot 动画树状态机、
	///         Godot 动画播放器和 Godot 动画精灵。发现多个后端时，会将其组合为
	///         <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CompositeAnimationBackend" />。
	///     </para>
	/// </summary>
	public static class CompositeBackendFactory
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Builds the available backends, returning the sole backend directly or a composite when multiple backends
		///         are found. Throws when no supported backend is available.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         构建可用的动画后端；仅发现一个时直接返回该后端，发现多个时返回组合后端。
		///         没有任何受支持的后端时抛出异常。
		///     </para>
		/// </summary>
		/// <param name="visualsRoot">
		///     <para xml:lang="en">The root beneath which backends are discovered.</para>
		///     <para xml:lang="zh-CN">用于发现动画后端的根节点。</para>
		/// </param>
		/// <param name="character">
		///     <para xml:lang="en">
		///         An optional character model from which to obtain a <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSet" /> when
		///         <paramref name="cueSet" /> is <see langword="null" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的角色模型；当 <paramref name="cueSet" /> 为 <see langword="null" /> 时从中获取
		///         <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSet" />。
		///     </para>
		/// </param>
		/// <param name="cueSet">
		///     <para xml:lang="en">An optional explicit cue set, which takes precedence over character-derived cues.</para>
		///     <para xml:lang="zh-CN">可选的显式视觉提示集，优先于从角色模型取得的视觉提示。</para>
		/// </param>
		public static IAnimationBackend Build(Node visualsRoot, CharacterModel? character = null, VisualCueSet? cueSet = null)
		{
			ArgumentNullException.ThrowIfNull(visualsRoot, "visualsRoot");
			VisualCueSet visualCueSet = cueSet ?? TryGetCharacterCueSet(character);
			Sprite2D val = FindPrimarySprite2D(visualsRoot);
			List<IAnimationBackend> list = new List<IAnimationBackend>();
			if (visualCueSet != null && val != null)
			{
				list.Add(new CueAnimationBackend(visualsRoot, val, visualCueSet));
			}
			NCreatureVisuals val2 = (NCreatureVisuals)(object)((visualsRoot is NCreatureVisuals) ? visualsRoot : null);
			if (val2 != null && val2.HasSpineAnimation)
			{
				MegaSprite spineBody = val2.SpineBody;
				if (spineBody != null)
				{
					list.Add(new SpineAnimationBackend(spineBody));
				}
			}
			AnimationTree val3 = FindNode<AnimationTree>(visualsRoot) ?? SearchRecursive<AnimationTree>(visualsRoot);
			if (val3 != null && val3.TreeRoot is AnimationNodeStateMachine)
			{
				list.Add(new AnimationTreeStateMachineBackend(val3));
			}
			AnimationPlayer val4 = FindNode<AnimationPlayer>(visualsRoot) ?? SearchRecursive<AnimationPlayer>(visualsRoot);
			if (val4 != null)
			{
				list.Add(new GodotAnimationPlayerBackend(val4));
			}
			AnimatedSprite2D val5 = FindNode<AnimatedSprite2D>(visualsRoot) ?? SearchRecursive<AnimatedSprite2D>(visualsRoot);
			if (val5 != null)
			{
				list.Add(new AnimatedSprite2DBackend(val5));
			}
			if (list.Count == 0)
			{
				throw new InvalidOperationException($"No animation backend could be built for '{visualsRoot.Name}' (no cues, Spine, AnimationTree, AnimationPlayer or AnimatedSprite2D).");
			}
			if (list.Count != 1)
			{
				return new CompositeAnimationBackend(list, visualsRoot);
			}
			return list[0];
		}

		private static VisualCueSet? TryGetCharacterCueSet(CharacterModel? character)
		{
			object obj;
			if (character is IModCharacterAssetOverrides modCharacterAssetOverrides)
			{
				obj = modCharacterAssetOverrides.VisualCues;
				if (obj == null)
				{
					return modCharacterAssetOverrides.WorldProceduralVisuals?.Merchant?.CueSet;
				}
			}
			else
			{
				obj = null;
			}
			return (VisualCueSet?)obj;
		}

		private static Sprite2D? FindPrimarySprite2D(Node root)
		{
			Node obj = root.GetNodeOrNull(NodePath.op_Implicit("%Visuals")) ?? root.GetNodeOrNull(NodePath.op_Implicit("Visuals"));
			Sprite2D val = (Sprite2D)(object)((obj is Sprite2D) ? obj : null);
			if (val != null)
			{
				return val;
			}
			Sprite2D val2 = (Sprite2D)(object)((root is Sprite2D) ? root : null);
			if (val2 != null)
			{
				return val2;
			}
			return SearchRecursive<Sprite2D>(root);
		}

		private static T? FindNode<T>(Node root) where T : class
		{
			string name = typeof(T).Name;
			return (root.GetNodeOrNull(NodePath.op_Implicit(name)) ?? root.GetNodeOrNull(NodePath.op_Implicit("Visuals/" + name)) ?? root.GetNodeOrNull(NodePath.op_Implicit("Body/" + name))) as T;
		}

		private static T? SearchRecursive<T>(Node parent) where T : class
		{
			foreach (Node child in parent.GetChildren(false))
			{
				if (child is T result)
				{
					return result;
				}
				T val = SearchRecursive<T>(child);
				if (val != null)
				{
					return val;
				}
			}
			return null;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines the uniform playback contract required by <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine" />, allowing the same state
	///         graph to drive Spine (<c>MegaSprite</c>), Godot <c>AnimationPlayer</c>, <c>AnimatedSprite2D</c>, or cue-frame
	///         playback through <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSet" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine" /> 所需的统一播放契约，使同一状态图可以驱动 Spine
	///         （<c>MegaSprite</c>）、Godot <c>AnimationPlayer</c>、<c>AnimatedSprite2D</c>，或通过
	///         <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSet" /> 定义的视觉提示帧播放。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Implementations raise <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Started" />, <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Completed" />, and <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Interrupted" />
	///         when the underlying system reports the corresponding events, allowing the state machine to advance to
	///         <see cref="P:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState.NextState" />.
	///     </para>
	///     <para xml:lang="en">
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Queue(System.String,System.Boolean)" /> is most meaningful for backends with native queue semantics, such as Spine.
	///         Other backends may forward it to <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Play(System.String,System.Boolean)" /> or defer it until <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Completed" /> fires.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         当底层系统报告对应事件时，实现会触发 <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Started" />、<see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Completed" /> 和
	///         <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Interrupted" />，使状态机可以推进到 <see cref="P:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState.NextState" />。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Queue(System.String,System.Boolean)" /> 对 Spine 等原生支持队列语义的后端最有意义；其他后端可以将其转发到
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Play(System.String,System.Boolean)" />，或延迟到 <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Completed" /> 触发后处理。
	///     </para>
	/// </remarks>
	public interface IAnimationBackend
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets the backend's owner node, such as a visuals or merchant root; returns
		///         <see langword="null" /> when not applicable.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取后端的所有者节点，例如视觉效果或商人的根节点；不适用时返回 <see langword="null" />。
		///     </para>
		/// </summary>
		Node? OwnerNode { get; }

		/// <summary>
		///     <para xml:lang="en">Occurs when the backend reports that an animation ID has started playing.</para>
		///     <para xml:lang="zh-CN">当后端报告某个动画 ID 开始播放时发生。</para>
		/// </summary>
		event Action<string>? Started;

		/// <summary>
		///     <para xml:lang="en">
		///         Occurs when the backend reports the end of a loop cycle or one-shot animation.
		///     </para>
		///     <para xml:lang="zh-CN">当后端报告一次循环周期或单次动画结束时发生。</para>
		/// </summary>
		event Action<string>? Completed;

		/// <summary>
		///     <para xml:lang="en">Occurs when the backend reports that an animation was interrupted.</para>
		///     <para xml:lang="zh-CN">当后端报告动画播放被中断时发生。</para>
		/// </summary>
		event Action<string>? Interrupted;

		/// <summary>
		///     <para xml:lang="en">Returns whether the backend can play <paramref name="id" />.</para>
		///     <para xml:lang="zh-CN">返回后端是否能够播放 <paramref name="id" />。</para>
		/// </summary>
		bool HasAnimation(string id);

		/// <summary>
		///     <para xml:lang="en">Plays <paramref name="id" /> immediately, replacing any active animation.</para>
		///     <para xml:lang="zh-CN">立即播放 <paramref name="id" />，并替换当前活动的动画。</para>
		/// </summary>
		/// <param name="id">
		///     <para xml:lang="en">The animation ID, which must be accepted by <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.HasAnimation(System.String)" />.</para>
		///     <para xml:lang="zh-CN">动画 ID，必须能通过 <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.HasAnimation(System.String)" /> 检查。</para>
		/// </param>
		/// <param name="loop">
		///     <para xml:lang="en">
		///         Whether looping is requested. Backends without loop control treat this as a best-effort hint.
		///     </para>
		///     <para xml:lang="zh-CN">是否请求循环；无法控制循环的后端会尽可能遵循此提示。</para>
		/// </param>
		void Play(string id, bool loop);

		/// <summary>
		///     <para xml:lang="en">
		///         Queues <paramref name="id" /> after the active animation. Backends without native queues may defer
		///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Play(System.String,System.Boolean)" /> until the next <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Completed" /> event.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将 <paramref name="id" /> 排在当前动画之后。没有原生队列的后端可以将
		///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Play(System.String,System.Boolean)" /> 延迟到下一次 <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Completed" /> 事件发生时执行。
		///     </para>
		/// </summary>
		void Queue(string id, bool loop);

		/// <summary>
		///     <para xml:lang="en">
		///         Silently stops active playback without raising <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Interrupted" /> or <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Completed" />,
		///         and clears queued animation. This allows callers such as
		///         <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CompositeAnimationBackend" /> to
		///         relinquish one backend before activating another.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         静默停止当前播放，不触发 <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Interrupted" /> 或 <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Completed" />，并清除排队的动画。
		///         这使 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CompositeAnimationBackend" />
		///         等调用方能够在激活另一个后端之前释放当前后端。
		///     </para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         The default implementation does nothing. Backends that drive visible nodes should override it to halt
		///         playback and suppress lifecycle events caused by the stop.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         默认实现不执行任何操作。驱动可见节点的后端应重写此方法，以停止播放并抑制停止操作引发的生命周期事件。
		///     </para>
		/// </remarks>
		void Stop()
		{
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines optional timing information for animation backends that can report clip duration and remaining playback
	///         time. Existing <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend" /> implementations do not need to implement this interface.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义可选的动画计时信息，供能够报告片段总时长和剩余播放时间的后端实现。
	///         现有的 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend" /> 实现无需实现此接口。
	///     </para>
	/// </summary>
	public interface IAnimationTimingProvider
	{
		/// <summary>
		///     <para xml:lang="en">Tries to get the total playback duration of <paramref name="id" /> in real seconds.</para>
		///     <para xml:lang="zh-CN">尝试获取 <paramref name="id" /> 以实际秒数表示的总播放时长。</para>
		/// </summary>
		bool TryGetAnimationDuration(string id, out float seconds);

		/// <summary>
		///     <para xml:lang="en">Tries to get the remaining real seconds of the active animation.</para>
		///     <para xml:lang="zh-CN">尝试获取当前活动动画剩余的实际秒数。</para>
		/// </summary>
		bool TryGetCurrentAnimationRemaining(out float seconds);
	}
	/// <summary>
	///     <para xml:lang="en">Represents one backend-agnostic animation state for an <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend" />.</para>
	///     <para xml:lang="zh-CN">表示 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend" /> 的一个与后端无关的动画状态。</para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         When the backend reports completion, <see cref="P:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState.NextState" /> is entered if it is not <see langword="null" />.
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState.CallTrigger(System.String)" /> chooses the first branch registered for the trigger whose optional predicate passes.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         后端报告完成时，若 <see cref="P:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState.NextState" /> 不为 <see langword="null" />，状态机会进入该状态。
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState.CallTrigger(System.String)" /> 选择为触发器注册且可选谓词通过的第一个分支。
	///     </para>
	/// </remarks>
	public sealed class ModAnimState
	{
		private readonly record struct Branch(ModAnimState Target, Func<bool>? Condition);

		private readonly Dictionary<string, List<Branch>> _branches = new Dictionary<string, List<Branch>>(StringComparer.Ordinal);

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the backend animation ID, such as a Spine track, Godot animation name, cue key, or
		///         SpriteFrames animation name.
		///     </para>
		///     <para xml:lang="zh-CN">获取后端动画 ID，例如 Spine 轨道、Godot 动画名、视觉提示键或 SpriteFrames 动画名。</para>
		/// </summary>
		public string Id { get; }

		/// <summary>
		///     <para xml:lang="en">Gets whether this state requests looping while active.</para>
		///     <para xml:lang="zh-CN">获取此状态激活时是否请求循环播放。</para>
		/// </summary>
		public bool IsLooping { get; }

		/// <summary>
		///     <para xml:lang="en">Gets or sets the optional state entered after this state completes.</para>
		///     <para xml:lang="zh-CN">获取或设置此状态完成后进入的可选状态。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">Leave this <see langword="null" /> for terminal states, so completion does not advance.</para>
		///     <para xml:lang="zh-CN">终止状态应保持为 <see langword="null" />，使完成事件不再推进状态机。</para>
		/// </remarks>
		public ModAnimState? NextState { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets an optional bounds-container tag reported through
		///         <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine.BoundsUpdated" />.
		///     </para>
		///     <para xml:lang="zh-CN">获取通过 <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine.BoundsUpdated" /> 报告的可选边界容器标签。</para>
		/// </summary>
		public string? BoundsContainer { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets whether the state has completed at least one loop iteration.</para>
		///     <para xml:lang="zh-CN">获取该状态是否已完成至少一次循环迭代。</para>
		/// </summary>
		public bool HasLooped { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Creates a state bound to backend animation <paramref name="id" />.</para>
		///     <para xml:lang="zh-CN">创建绑定到后端动画 <paramref name="id" /> 的状态。</para>
		/// </summary>
		/// <param name="id">
		///     <para xml:lang="en">An animation ID accepted by <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.HasAnimation(System.String)" />.</para>
		///     <para xml:lang="zh-CN">可由 <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.HasAnimation(System.String)" /> 接受的动画 ID。</para>
		/// </param>
		/// <param name="isLooping">
		///     <para xml:lang="en">Whether the backend should be asked to loop playback.</para>
		///     <para xml:lang="zh-CN">是否请求后端循环播放。</para>
		/// </param>
		public ModAnimState(string id, bool isLooping = false)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			Id = id;
			IsLooping = isLooping;
		}

		/// <summary>
		///     <para xml:lang="en">Adds a branch to <paramref name="target" /> for <paramref name="trigger" />.</para>
		///     <para xml:lang="zh-CN">为 <paramref name="trigger" /> 添加通向 <paramref name="target" /> 的分支。</para>
		/// </summary>
		/// <param name="trigger">
		///     <para xml:lang="en">The trigger name compared ordinally by <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState.CallTrigger(System.String)" />.</para>
		///     <para xml:lang="zh-CN">由 <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState.CallTrigger(System.String)" /> 按序数比较的触发器名称。</para>
		/// </param>
		/// <param name="target">
		///     <para xml:lang="en">The state entered when the trigger fires and <paramref name="condition" /> passes.</para>
		///     <para xml:lang="zh-CN">触发器触发且 <paramref name="condition" /> 通过时进入的状态。</para>
		/// </param>
		/// <param name="condition">
		///     <para xml:lang="en">An optional predicate evaluated at trigger time; <see langword="null" /> always passes.</para>
		///     <para xml:lang="zh-CN">在触发时求值的可选谓词；<see langword="null" /> 始终通过。</para>
		/// </param>
		public void AddBranch(string trigger, ModAnimState target, Func<bool>? condition = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(trigger, "trigger");
			ArgumentNullException.ThrowIfNull(target, "target");
			if (!_branches.TryGetValue(trigger, out List<Branch> value))
			{
				value = new List<Branch>();
				_branches[trigger] = value;
			}
			value.Add(new Branch(target, condition));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the first branch for <paramref name="trigger" /> whose predicate passes, or
		///         <see langword="null" />.
		///     </para>
		///     <para xml:lang="zh-CN">返回 <paramref name="trigger" /> 的第一个谓词通过的分支；没有时返回 <see langword="null" />。</para>
		/// </summary>
		public ModAnimState? CallTrigger(string trigger)
		{
			if (_branches.TryGetValue(trigger, out List<Branch> value))
			{
				return value.Where(delegate(Branch branch)
				{
					Branch branch2 = branch;
					if (branch2.Condition != null)
					{
						branch2 = branch;
						return branch2.Condition();
					}
					return true;
				}).Select(delegate(Branch branch)
				{
					Branch branch2 = branch;
					return branch2.Target;
				}).FirstOrDefault();
			}
			return null;
		}

		/// <summary>
		///     <para xml:lang="en">Returns whether at least one branch is registered for <paramref name="trigger" />.</para>
		///     <para xml:lang="zh-CN">返回是否至少有一个分支注册到 <paramref name="trigger" />。</para>
		/// </summary>
		public bool HasTrigger(string trigger)
		{
			return _branches.ContainsKey(trigger);
		}

		/// <summary>
		///     <para xml:lang="en">Marks the state as having completed one loop iteration.</para>
		///     <para xml:lang="zh-CN">将该状态标记为已完成一次循环迭代。</para>
		/// </summary>
		public void MarkHasLooped()
		{
			HasLooped = true;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Drives <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState" /> transitions through any <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend" />.</para>
	///     <para xml:lang="zh-CN">通过任意 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend" /> 驱动 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState" /> 转换。</para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Triggers prefer any-state branches to current-state branches. A terminal state leaves
	///         <see cref="P:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState.NextState" /> <see langword="null" />, so completion does not advance.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         触发器优先匹配任意状态分支，再匹配当前状态分支。终止状态的 <see cref="P:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState.NextState" /> 保持为
	///         <see langword="null" />，因此完成时不会推进。
	///     </para>
	/// </remarks>
	public sealed class ModAnimStateMachine
	{
		private readonly ModAnimState _anyState = new ModAnimState("__anyState");

		private bool _disposed;

		private bool _nextStateQueued;

		private ModAnimState? _queuedFromState;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the active state, or <see langword="null" /> before <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine.Start(STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState)" /> and after
		///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine.Dispose" />.
		///     </para>
		///     <para xml:lang="zh-CN">获取活动状态；在 <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine.Start(STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState)" /> 前和 <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine.Dispose" /> 后为 <see langword="null" />。</para>
		/// </summary>
		public ModAnimState? Current { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Gets the backend driven by this state machine.</para>
		///     <para xml:lang="zh-CN">获取由此状态机驱动的后端。</para>
		/// </summary>
		public IAnimationBackend Backend { get; }

		/// <summary>
		///     <para xml:lang="en">Occurs when the current state's bounds-container tag should be applied.</para>
		///     <para xml:lang="zh-CN">当应应用当前状态的边界容器标签时发生。</para>
		/// </summary>
		public event Action<string>? BoundsUpdated;

		/// <summary>
		///     <para xml:lang="en">Occurs when the backend reports playback started for the current state.</para>
		///     <para xml:lang="zh-CN">当后端报告当前状态开始播放时发生。</para>
		/// </summary>
		public event Action<ModAnimState>? AnimationStarted;

		/// <summary>
		///     <para xml:lang="en">Occurs when the backend reports playback completed for the current state.</para>
		///     <para xml:lang="zh-CN">当后端报告当前状态播放完成时发生。</para>
		/// </summary>
		public event Action<ModAnimState>? AnimationCompleted;

		/// <summary>
		///     <para xml:lang="en">Occurs when the backend reports playback interrupted for the current state.</para>
		///     <para xml:lang="zh-CN">当后端报告当前状态播放中断时发生。</para>
		/// </summary>
		public event Action<ModAnimState>? AnimationInterrupted;

		/// <summary>
		///     <para xml:lang="en">Wraps <paramref name="backend" /> and subscribes to its playback events.</para>
		///     <para xml:lang="zh-CN">包装 <paramref name="backend" /> 并订阅其播放事件。</para>
		/// </summary>
		public ModAnimStateMachine(IAnimationBackend backend)
		{
			ArgumentNullException.ThrowIfNull(backend, "backend");
			Backend = backend;
			Backend.Started += OnBackendStarted;
			Backend.Completed += OnBackendCompleted;
			Backend.Interrupted += OnBackendInterrupted;
		}

		/// <summary>
		///     <para xml:lang="en">Registers a branch on the synthetic any-state, which is evaluated before the current state.</para>
		///     <para xml:lang="zh-CN">在合成的任意状态上注册分支；该状态会先于当前状态求值。</para>
		/// </summary>
		public void AddAnyState(string trigger, ModAnimState state, Func<bool>? condition = null)
		{
			_anyState.AddBranch(trigger, state, condition);
		}

		/// <summary>
		///     <para xml:lang="en">Enters <paramref name="initial" /> and starts backend playback unless the machine is disposed.</para>
		///     <para xml:lang="zh-CN">进入 <paramref name="initial" /> 并启动后端播放，除非状态机已释放。</para>
		/// </summary>
		public void Start(ModAnimState initial)
		{
			ArgumentNullException.ThrowIfNull(initial, "initial");
			if (!_disposed)
			{
				EnterState(initial);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Returns whether the synthetic any-state has a branch for <paramref name="trigger" />.</para>
		///     <para xml:lang="zh-CN">返回合成的任意状态是否有 <paramref name="trigger" /> 的分支。</para>
		/// </summary>
		public bool HasTrigger(string trigger)
		{
			return _anyState.HasTrigger(trigger);
		}

		/// <summary>
		///     <para xml:lang="en">Tries to get the current state's total duration when the backend provides timing.</para>
		///     <para xml:lang="zh-CN">当后端提供计时时，尝试获取当前状态的总时长。</para>
		/// </summary>
		public bool TryGetCurrentAnimationDuration(out float seconds)
		{
			seconds = 0f;
			ModAnimState current = Current;
			if (current != null && Backend is IAnimationTimingProvider animationTimingProvider)
			{
				return animationTimingProvider.TryGetAnimationDuration(current.Id, out seconds);
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Tries to get the current animation's remaining duration when the backend provides timing.</para>
		///     <para xml:lang="zh-CN">当后端提供计时时，尝试获取当前动画的剩余时长。</para>
		/// </summary>
		public bool TryGetCurrentAnimationRemaining(out float seconds)
		{
			seconds = 0f;
			if (Backend is IAnimationTimingProvider animationTimingProvider)
			{
				return animationTimingProvider.TryGetCurrentAnimationRemaining(out seconds);
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Evaluates <paramref name="trigger" /> against any-state, then the current state, and enters the
		///         first matching target.
		///     </para>
		///     <para xml:lang="zh-CN">先对任意状态、再对当前状态求值 <paramref name="trigger" />，并进入第一个匹配的目标。</para>
		/// </summary>
		public void SetTrigger(string trigger)
		{
			if (!_disposed && !string.IsNullOrWhiteSpace(trigger))
			{
				ModAnimState modAnimState = _anyState.CallTrigger(trigger) ?? Current?.CallTrigger(trigger);
				if (modAnimState != null)
				{
					EnterState(modAnimState);
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">Detaches from backend events. Repeated calls are safe.</para>
		///     <para xml:lang="zh-CN">断开后端事件；可安全地重复调用。</para>
		/// </summary>
		public void Dispose()
		{
			if (!_disposed)
			{
				_disposed = true;
				Backend.Started -= OnBackendStarted;
				Backend.Completed -= OnBackendCompleted;
				Backend.Interrupted -= OnBackendInterrupted;
				Current = null;
			}
		}

		private void EnterState(ModAnimState state)
		{
			if (!Backend.HasAnimation(state.Id))
			{
				Logger logger = RitsuLibFramework.Logger;
				DefaultInterpolatedStringHandler defaultInterpolatedStringHandler = new DefaultInterpolatedStringHandler(58, 2);
				defaultInterpolatedStringHandler.AppendLiteral("[ModAnimStateMachine] Backend has no animation '");
				defaultInterpolatedStringHandler.AppendFormatted(state.Id);
				defaultInterpolatedStringHandler.AppendLiteral("' (owner=");
				Node? ownerNode = Backend.OwnerNode;
				defaultInterpolatedStringHandler.AppendFormatted<StringName>((ownerNode != null) ? ownerNode.Name : null);
				defaultInterpolatedStringHandler.AppendLiteral(")");
				logger.Warn(defaultInterpolatedStringHandler.ToStringAndClear(), 1);
				return;
			}
			Current = state;
			_nextStateQueued = false;
			_queuedFromState = null;
			Backend.Play(state.Id, state.IsLooping);
			if (Current == state)
			{
				if (state.BoundsContainer != null)
				{
					BoundsUpdated?.Invoke(state.BoundsContainer);
				}
				QueueNextState(state);
			}
		}

		private void QueueNextState(ModAnimState state)
		{
			if (_queuedFromState == state)
			{
				return;
			}
			_queuedFromState = state;
			ModAnimState nextState = state.NextState;
			if (nextState != null)
			{
				if (!Backend.HasAnimation(nextState.Id))
				{
					Logger logger = RitsuLibFramework.Logger;
					DefaultInterpolatedStringHandler defaultInterpolatedStringHandler = new DefaultInterpolatedStringHandler(65, 2);
					defaultInterpolatedStringHandler.AppendLiteral("[ModAnimStateMachine] Backend has no queued animation '");
					defaultInterpolatedStringHandler.AppendFormatted(nextState.Id);
					defaultInterpolatedStringHandler.AppendLiteral("' ");
					defaultInterpolatedStringHandler.AppendLiteral("(owner=");
					Node? ownerNode = Backend.OwnerNode;
					defaultInterpolatedStringHandler.AppendFormatted<StringName>((ownerNode != null) ? ownerNode.Name : null);
					defaultInterpolatedStringHandler.AppendLiteral(")");
					logger.Warn(defaultInterpolatedStringHandler.ToStringAndClear(), 1);
				}
				else
				{
					Backend.Queue(nextState.Id, nextState.IsLooping);
					_nextStateQueued = true;
				}
			}
		}

		private void OnBackendStarted(string _)
		{
			ModAnimState current = Current;
			if (current != null)
			{
				if (current != null && !current.HasLooped && current.BoundsContainer != null)
				{
					BoundsUpdated?.Invoke(current.BoundsContainer);
				}
				AnimationStarted?.Invoke(current);
				if (Current == current)
				{
					QueueNextState(current);
				}
			}
		}

		private void OnBackendCompleted(string _)
		{
			ModAnimState current = Current;
			if (current != null)
			{
				if (current != null && !current.HasLooped && current.BoundsContainer != null)
				{
					BoundsUpdated?.Invoke(current.BoundsContainer);
				}
				if (current != null && current.IsLooping && !current.HasLooped)
				{
					current.MarkHasLooped();
				}
				AnimationCompleted?.Invoke(current);
				if (Current == current && current.NextState != null && _queuedFromState == current && _nextStateQueued)
				{
					Current = current.NextState;
					_nextStateQueued = false;
					_queuedFromState = null;
				}
			}
		}

		private void OnBackendInterrupted(string _)
		{
			ModAnimState current = Current;
			if (current != null)
			{
				if (current.BoundsContainer != null)
				{
					BoundsUpdated?.Invoke(current.BoundsContainer);
				}
				AnimationInterrupted?.Invoke(current);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Fluently declares states and transitions, then builds and starts a
	///         <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine" />.
	///     </para>
	///     <para xml:lang="zh-CN">以流式方式声明状态和转换，然后构建并启动 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine" />。</para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         The builder does not validate IDs against backend availability. Entering an unavailable state
	///         logs a warning and leaves the current state unchanged.
	///     </para>
	///     <para xml:lang="zh-CN">构建器不会根据后端可用性验证 ID。进入不可用状态时会记录警告，并保持当前状态不变。</para>
	/// </remarks>
	public sealed class ModAnimStateMachineBuilder
	{
		internal sealed class StateDraft(string id, bool loop)
		{
			public string Id { get; } = id;

			public bool Loop { get; } = loop;

			public string? NextStateId { get; set; }

			public string? BoundsContainer { get; set; }

			public List<BranchDraft> Branches { get; } = new List<BranchDraft>();
		}

		internal readonly record struct BranchDraft(string Trigger, string ToId, Func<bool>? Condition);

		private readonly record struct AnyBranchDraft(string Trigger, string ToId, Func<bool>? Condition);

		/// <summary>
		///     <para xml:lang="en">
		///         Fluently configures metadata for a state declared by
		///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachineBuilder.AddState(System.String,System.Boolean)" />.
		///     </para>
		///     <para xml:lang="zh-CN">以流式方式配置由 <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachineBuilder.AddState(System.String,System.Boolean)" /> 声明的状态元数据。</para>
		/// </summary>
		public sealed class StateScope
		{
			private readonly StateDraft _draft;

			private readonly ModAnimStateMachineBuilder _owner;

			internal StateScope(ModAnimStateMachineBuilder owner, StateDraft draft)
			{
				_owner = owner;
				_draft = draft;
			}

			/// <summary>
			///     <para xml:lang="en">Sets the current state's next-state ID.</para>
			///     <para xml:lang="zh-CN">设置当前状态的下一状态 ID。</para>
			/// </summary>
			public StateScope WithNext(string nextStateId)
			{
				ArgumentException.ThrowIfNullOrWhiteSpace(nextStateId, "nextStateId");
				_draft.NextStateId = nextStateId;
				return this;
			}

			/// <summary>
			///     <para xml:lang="en">Sets the bounds-container tag reported when this state is entered.</para>
			///     <para xml:lang="zh-CN">设置进入此状态时报告的边界容器标签。</para>
			/// </summary>
			public StateScope WithBounds(string boundsContainer)
			{
				ArgumentException.ThrowIfNullOrWhiteSpace(boundsContainer, "boundsContainer");
				_draft.BoundsContainer = boundsContainer;
				return this;
			}

			/// <summary>
			///     <para xml:lang="en">Marks the current state as initial, replacing the default first declared state.</para>
			///     <para xml:lang="zh-CN">将当前状态标记为初始状态，替代默认的第一个已声明状态。</para>
			/// </summary>
			public StateScope AsInitial()
			{
				_owner._initialStateId = _draft.Id;
				return this;
			}

			/// <summary>
			///     <para xml:lang="en">Returns the owning builder.</para>
			///     <para xml:lang="zh-CN">返回所属构建器。</para>
			/// </summary>
			public ModAnimStateMachineBuilder Done()
			{
				return _owner;
			}
		}

		private readonly List<AnyBranchDraft> _anyBranches = new List<AnyBranchDraft>();

		private readonly Dictionary<string, StateDraft> _states = new Dictionary<string, StateDraft>(StringComparer.Ordinal);

		private string? _initialStateId;

		private ModAnimStateMachineBuilder()
		{
		}

		/// <summary>
		///     <para xml:lang="en">Creates a new builder.</para>
		///     <para xml:lang="zh-CN">创建新的构建器。</para>
		/// </summary>
		public static ModAnimStateMachineBuilder Create()
		{
			return new ModAnimStateMachineBuilder();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Declares a state with backend animation <paramref name="id" /> and loop request
		///         <paramref name="loop" />.
		///     </para>
		///     <para xml:lang="zh-CN">声明使用后端动画 <paramref name="id" /> 和循环请求 <paramref name="loop" /> 的状态。</para>
		/// </summary>
		public StateScope AddState(string id, bool loop = false)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			if (_states.ContainsKey(id))
			{
				throw new InvalidOperationException("State '" + id + "' already declared.");
			}
			StateDraft stateDraft = new StateDraft(id, loop);
			_states[id] = stateDraft;
			if (_initialStateId == null)
			{
				_initialStateId = id;
			}
			return new StateScope(this, stateDraft);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds a trigger branch from <paramref name="fromId" /> to <paramref name="toId" />, guarded by
		///         <paramref name="condition" /> when supplied.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         添加从 <paramref name="fromId" /> 到 <paramref name="toId" /> 的触发器分支；提供时由
		///         <paramref name="condition" /> 守卫。
		///     </para>
		/// </summary>
		public ModAnimStateMachineBuilder AddBranch(string fromId, string trigger, string toId, Func<bool>? condition = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(fromId, "fromId");
			ArgumentException.ThrowIfNullOrWhiteSpace(trigger, "trigger");
			ArgumentException.ThrowIfNullOrWhiteSpace(toId, "toId");
			if (!_states.TryGetValue(fromId, out StateDraft value))
			{
				throw new InvalidOperationException("Source state '" + fromId + "' not declared.");
			}
			value.Branches.Add(new BranchDraft(trigger, toId, condition));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds an any-state branch to <paramref name="toId" />, optionally guarded by
		///         <paramref name="condition" />.
		///     </para>
		///     <para xml:lang="zh-CN">添加指向 <paramref name="toId" /> 的任意状态分支，可选地由 <paramref name="condition" /> 守卫。</para>
		/// </summary>
		public ModAnimStateMachineBuilder AddAnyState(string trigger, string toId, Func<bool>? condition = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(trigger, "trigger");
			ArgumentException.ThrowIfNullOrWhiteSpace(toId, "toId");
			_anyBranches.Add(new AnyBranchDraft(trigger, toId, condition));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Materializes the graph against <paramref name="backend" /> and starts the resulting state
		///         machine.
		///     </para>
		///     <para xml:lang="zh-CN">针对 <paramref name="backend" /> 实例化状态图，并启动所得状态机。</para>
		/// </summary>
		public ModAnimStateMachine Build(IAnimationBackend backend)
		{
			ArgumentNullException.ThrowIfNull(backend, "backend");
			ModAnimStateMachine modAnimStateMachine = BuildCore(backend, out ModAnimState initial);
			modAnimStateMachine.Start(initial);
			return modAnimStateMachine;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Wraps <paramref name="controller" /> in a <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.SpineAnimationBackend" /> and builds the
		///         state machine.
		///     </para>
		///     <para xml:lang="zh-CN">将 <paramref name="controller" /> 包装为 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.SpineAnimationBackend" /> 并构建状态机。</para>
		/// </summary>
		public ModAnimStateMachine BuildSpine(MegaSprite controller)
		{
			return Build(new SpineAnimationBackend(controller));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Discovers cue, Spine, Godot AnimationPlayer, and AnimatedSprite2D backends under
		///         <paramref name="visualsRoot" />, then builds the state machine.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <paramref name="visualsRoot" /> 下发现视觉提示、Spine、Godot AnimationPlayer 和 AnimatedSprite2D
		///         后端，再构建状态机。
		///     </para>
		/// </summary>
		/// <param name="visualsRoot">
		///     <para xml:lang="en">The visuals root, typically an <see cref="T:MegaCrit.Sts2.Core.Nodes.Combat.NCreatureVisuals" />.</para>
		///     <para xml:lang="zh-CN">视觉根节点，通常为 <see cref="T:MegaCrit.Sts2.Core.Nodes.Combat.NCreatureVisuals" />。</para>
		/// </param>
		/// <param name="character">
		///     <para xml:lang="en">
		///         An optional character used to obtain cues when <paramref name="cueSet" /> is
		///         <see langword="null" />.
		///     </para>
		///     <para xml:lang="zh-CN">可选角色；当 <paramref name="cueSet" /> 为 <see langword="null" /> 时用于获取视觉提示。</para>
		/// </param>
		/// <param name="cueSet">
		///     <para xml:lang="en">An optional explicit cue set, which takes precedence over character-derived cues.</para>
		///     <para xml:lang="zh-CN">可选的显式视觉提示集，优先于从角色获得的视觉提示。</para>
		/// </param>
		public ModAnimStateMachine BuildForVisualsRoot(Node visualsRoot, CharacterModel? character = null, VisualCueSet? cueSet = null)
		{
			IAnimationBackend backend = CompositeBackendFactory.Build(visualsRoot, character, cueSet);
			return Build(backend);
		}

		private ModAnimStateMachine BuildCore(IAnimationBackend backend, out ModAnimState initial)
		{
			if (_initialStateId == null)
			{
				throw new InvalidOperationException("No states declared.");
			}
			Dictionary<string, ModAnimState> dictionary = new Dictionary<string, ModAnimState>(StringComparer.Ordinal);
			string key;
			StateDraft value;
			foreach (KeyValuePair<string, StateDraft> state in _states)
			{
				state.Deconstruct(out key, out value);
				string key2 = key;
				StateDraft stateDraft = value;
				dictionary[key2] = new ModAnimState(stateDraft.Id, stateDraft.Loop)
				{
					BoundsContainer = stateDraft.BoundsContainer
				};
			}
			foreach (KeyValuePair<string, StateDraft> state2 in _states)
			{
				state2.Deconstruct(out key, out value);
				string text = key;
				StateDraft stateDraft2 = value;
				ModAnimState modAnimState = dictionary[text];
				if (stateDraft2.NextStateId != null)
				{
					if (!dictionary.TryGetValue(stateDraft2.NextStateId, out var value2))
					{
						throw new InvalidOperationException($"Next state '{stateDraft2.NextStateId}' referenced by '{text}' was not declared.");
					}
					modAnimState.NextState = value2;
				}
				foreach (BranchDraft branch in stateDraft2.Branches)
				{
					if (!dictionary.TryGetValue(branch.ToId, out var value3))
					{
						throw new InvalidOperationException($"Branch target state '{branch.ToId}' referenced by '{text}' was not declared.");
					}
					modAnimState.AddBranch(branch.Trigger, value3, branch.Condition);
				}
			}
			initial = dictionary[_initialStateId];
			ModAnimStateMachine modAnimStateMachine = new ModAnimStateMachine(backend);
			foreach (AnyBranchDraft anyBranch in _anyBranches)
			{
				if (!dictionary.TryGetValue(anyBranch.ToId, out var value4))
				{
					throw new InvalidOperationException("Any-state branch target '" + anyBranch.ToId + "' was not declared.");
				}
				modAnimStateMachine.AddAnyState(anyBranch.Trigger, value4, anyBranch.Condition);
			}
			return modAnimStateMachine;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides convenience factories for the standard creature-animation state graph. They mirror baselib's
	///         <c>CustomCharacterModel.SetupAnimationState</c> shape for Spine and for the non-Spine backends selected
	///         from a visuals root.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为标准生物动画状态图提供便捷工厂。它们既适用于 Spine，也适用于从视觉根节点选择的非 Spine 后端，
	///         状态图结构与 baselib 的 <c>CustomCharacterModel.SetupAnimationState</c> 对应。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachines.Standard(MegaCrit.Sts2.Core.Bindings.MegaSpine.MegaSprite,System.String,System.String,System.Boolean,System.String,System.Boolean,System.String,System.Boolean,System.String,System.Boolean,System.String,System.Boolean)" /> produces a vanilla <see cref="T:MegaCrit.Sts2.Core.Animation.CreatureAnimator" /> so callers can return it
	///         directly from <c>CharacterModel.GenerateAnimator</c>; this is the closest drop-in replacement for the
	///         baselib helper.
	///     </para>
	///     <para xml:lang="en">
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachines.StandardCue(Godot.Node,MegaCrit.Sts2.Core.Models.CharacterModel,System.String,System.String,System.Boolean,System.String,System.Boolean,System.String,System.Boolean,System.String,System.Boolean,System.String,System.Boolean,STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSet)" /> produces a backend-agnostic <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine" /> for
	///         non-Spine visuals rooted at a <see cref="T:Godot.Node" /> (cue frame sequences, Godot animation player,
	///         animated sprite).
	///     </para>
	///     <para xml:lang="en">
	///         Terminal states (<c>Dead</c>) leave <see cref="P:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState.NextState" /> / <c>AnimState.NextState</c>
	///         unset so completion does not auto-return to idle, matching the vanilla behaviour.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachines.Standard(MegaCrit.Sts2.Core.Bindings.MegaSpine.MegaSprite,System.String,System.String,System.Boolean,System.String,System.Boolean,System.String,System.Boolean,System.String,System.Boolean,System.String,System.Boolean)" /> 会生成原版 <see cref="T:MegaCrit.Sts2.Core.Animation.CreatureAnimator" />，调用方可以直接从
	///         <c>CharacterModel.GenerateAnimator</c> 返回它；这是最接近 baselib 辅助方法的直接替代方案。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachines.StandardCue(Godot.Node,MegaCrit.Sts2.Core.Models.CharacterModel,System.String,System.String,System.Boolean,System.String,System.Boolean,System.String,System.Boolean,System.String,System.Boolean,System.String,System.Boolean,STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSet)" /> 会为以 <see cref="T:Godot.Node" /> 为根的非 Spine 视觉生成
	///         与后端无关的 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine" />（视觉提示帧序列、Godot 动画播放器、
	///         动画精灵）。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         终止状态（<c>Dead</c>）会让 <see cref="P:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimState.NextState" /> / <c>AnimState.NextState</c>
	///         保持未设置，因此完成后不会自动回到 idle，与原版行为一致。
	///     </para>
	/// </remarks>
	public static class ModAnimStateMachines
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Builds a Spine <see cref="T:MegaCrit.Sts2.Core.Animation.CreatureAnimator" /> with the standard idle, dead, hit, attack, cast, and
		///         relaxed triggers. An optional <see langword="null" /> name reuses the idle state.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         构建带有待机、死亡、受击、攻击、施放和放松触发器的 Spine <see cref="T:MegaCrit.Sts2.Core.Animation.CreatureAnimator" />。
		///         可选动画名为 <see langword="null" /> 时复用待机状态。
		///     </para>
		/// </summary>
		public static CreatureAnimator Standard(MegaSprite controller, string idleName, string? deadName = null, bool deadLoop = false, string? hitName = null, bool hitLoop = false, string? attackName = null, bool attackLoop = false, string? castName = null, bool castLoop = false, string? relaxedName = null, bool relaxedLoop = true)
		{
			//IL_0053: Unknown result type (might be due to invalid IL or missing references)
			//IL_0059: Expected O, but got Unknown
			//IL_005e: Unknown result type (might be due to invalid IL or missing references)
			//IL_006f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0074: Unknown result type (might be due to invalid IL or missing references)
			//IL_0087: Unknown result type (might be due to invalid IL or missing references)
			//IL_008c: Unknown result type (might be due to invalid IL or missing references)
			//IL_009f: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a4: Unknown result type (might be due to invalid IL or missing references)
			//IL_00bd: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c4: Expected O, but got Unknown
			//IL_00d4: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d9: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e6: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f3: Unknown result type (might be due to invalid IL or missing references)
			//IL_0100: Unknown result type (might be due to invalid IL or missing references)
			//IL_010d: Unknown result type (might be due to invalid IL or missing references)
			//IL_011b: Unknown result type (might be due to invalid IL or missing references)
			//IL_012a: Expected O, but got Unknown
			ArgumentNullException.ThrowIfNull(controller, "controller");
			ArgumentException.ThrowIfNullOrWhiteSpace(idleName, "idleName");
			ValidateOptionalAnimationName(deadName, "deadName");
			ValidateOptionalAnimationName(hitName, "hitName");
			ValidateOptionalAnimationName(attackName, "attackName");
			ValidateOptionalAnimationName(castName, "castName");
			ValidateOptionalAnimationName(relaxedName, "relaxedName");
			AnimState val = new AnimState(idleName, true);
			AnimState val2 = (AnimState)((deadName == null) ? ((object)val) : ((object)new AnimState(deadName, deadLoop)));
			AnimState val3 = (AnimState)((hitName == null) ? ((object)val) : ((object)new AnimState(hitName, hitLoop)
			{
				NextState = val
			}));
			AnimState val4 = (AnimState)((attackName == null) ? ((object)val) : ((object)new AnimState(attackName, attackLoop)
			{
				NextState = val
			}));
			AnimState val5 = (AnimState)((castName == null) ? ((object)val) : ((object)new AnimState(castName, castLoop)
			{
				NextState = val
			}));
			AnimState val6;
			if (relaxedName == null)
			{
				val6 = val;
			}
			else
			{
				val6 = new AnimState(relaxedName, relaxedLoop);
				val6.AddBranch("Idle", val, (Func<bool>)null);
			}
			CreatureAnimator val7 = new CreatureAnimator(val, controller);
			val7.AddAnyState("Idle", val, (Func<bool>)null);
			val7.AddAnyState("Dead", val2, (Func<bool>)null);
			val7.AddAnyState("Hit", val3, (Func<bool>)null);
			val7.AddAnyState("Attack", val4, (Func<bool>)null);
			val7.AddAnyState("Cast", val5, (Func<bool>)null);
			val7.AddAnyState("Relaxed", val6, (Func<bool>)null);
			return val7;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds a non-Spine <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine" /> over <paramref name="visualsRoot" /> with the
		///         standard idle, dead, hit, attack, cast, and relaxed triggers; optional <see langword="null" /> names
		///         target the idle state.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <paramref name="visualsRoot" /> 上构建非 Spine <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine" />，含有标准的待机、
		///         死亡、受击、攻击、施放和放松触发器；可选名称为 <see langword="null" /> 时会指向待机状态。
		///     </para>
		/// </summary>
		/// <param name="visualsRoot">
		///     <para xml:lang="en">Visual root node used by <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.CompositeBackendFactory" />.</para>
		///     <para xml:lang="zh-CN"><see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.CompositeBackendFactory" /> 使用的视觉根节点。</para>
		/// </param>
		/// <param name="character">
		///     <para xml:lang="en">Optional character model used to discover cue sets.</para>
		///     <para xml:lang="zh-CN">用于发现动画提示集合的可选角色模型。</para>
		/// </param>
		/// <param name="idleName">
		///     <para xml:lang="en">Required looping idle animation ID.</para>
		///     <para xml:lang="zh-CN">必填且循环播放的待机动画 ID。</para>
		/// </param>
		/// <param name="deadName">
		///     <para xml:lang="en">Optional death animation ID; <see langword="null" /> targets idle.</para>
		///     <para xml:lang="zh-CN">可选的死亡动画 ID；<see langword="null" /> 时指向待机动画。</para>
		/// </param>
		/// <param name="deadLoop">
		///     <para xml:lang="en">Whether the death animation should loop.</para>
		///     <para xml:lang="zh-CN">死亡动画是否循环。</para>
		/// </param>
		/// <param name="hitName">
		///     <para xml:lang="en">Optional hit animation ID; <see langword="null" /> targets idle.</para>
		///     <para xml:lang="zh-CN">可选的受击动画 ID；<see langword="null" /> 时指向待机动画。</para>
		/// </param>
		/// <param name="hitLoop">
		///     <para xml:lang="en">Whether the hit animation should loop.</para>
		///     <para xml:lang="zh-CN">受击动画是否循环。</para>
		/// </param>
		/// <param name="attackName">
		///     <para xml:lang="en">Optional attack animation ID; <see langword="null" /> targets idle.</para>
		///     <para xml:lang="zh-CN">可选的攻击动画 ID；<see langword="null" /> 时指向待机动画。</para>
		/// </param>
		/// <param name="attackLoop">
		///     <para xml:lang="en">Whether the attack animation should loop.</para>
		///     <para xml:lang="zh-CN">攻击动画是否循环。</para>
		/// </param>
		/// <param name="castName">
		///     <para xml:lang="en">Optional cast animation ID; <see langword="null" /> targets idle.</para>
		///     <para xml:lang="zh-CN">可选的施放动画 ID；<see langword="null" /> 时指向待机动画。</para>
		/// </param>
		/// <param name="castLoop">
		///     <para xml:lang="en">Whether the cast animation should loop.</para>
		///     <para xml:lang="zh-CN">施放动画是否循环。</para>
		/// </param>
		/// <param name="relaxedName">
		///     <para xml:lang="en">Optional relaxed animation ID; <see langword="null" /> targets idle.</para>
		///     <para xml:lang="zh-CN">可选的放松动画 ID；<see langword="null" /> 时指向待机动画。</para>
		/// </param>
		/// <param name="relaxedLoop">
		///     <para xml:lang="en">Whether the relaxed animation should loop.</para>
		///     <para xml:lang="zh-CN">放松动画是否循环。</para>
		/// </param>
		/// <param name="cueSet">
		///     <para xml:lang="en">Optional explicit cue set, which takes precedence over character-derived cues.</para>
		///     <para xml:lang="zh-CN">可选的显式视觉提示集，优先于从角色取得的视觉提示集。</para>
		/// </param>
		public static ModAnimStateMachine StandardCue(Node visualsRoot, CharacterModel? character, string idleName, string? deadName = null, bool deadLoop = false, string? hitName = null, bool hitLoop = false, string? attackName = null, bool attackLoop = false, string? castName = null, bool castLoop = false, string? relaxedName = null, bool relaxedLoop = true, VisualCueSet? cueSet = null)
		{
			ArgumentNullException.ThrowIfNull(visualsRoot, "visualsRoot");
			ArgumentException.ThrowIfNullOrWhiteSpace(idleName, "idleName");
			ValidateOptionalAnimationName(deadName, "deadName");
			ValidateOptionalAnimationName(hitName, "hitName");
			ValidateOptionalAnimationName(attackName, "attackName");
			ValidateOptionalAnimationName(castName, "castName");
			ValidateOptionalAnimationName(relaxedName, "relaxedName");
			ModAnimStateMachineBuilder modAnimStateMachineBuilder = ModAnimStateMachineBuilder.Create().AddState(idleName, loop: true).AsInitial()
				.Done();
			AddOptional(modAnimStateMachineBuilder, deadName, deadLoop, idleName, hasNext: false);
			AddOptional(modAnimStateMachineBuilder, hitName, hitLoop, idleName, hasNext: true);
			AddOptional(modAnimStateMachineBuilder, attackName, attackLoop, idleName, hasNext: true);
			AddOptional(modAnimStateMachineBuilder, castName, castLoop, idleName, hasNext: true);
			string toId = idleName;
			if (relaxedName != null && !string.Equals(relaxedName, idleName, StringComparison.Ordinal))
			{
				modAnimStateMachineBuilder.AddState(relaxedName, relaxedLoop).Done();
				modAnimStateMachineBuilder.AddBranch(relaxedName, "Idle", idleName);
				toId = relaxedName;
			}
			modAnimStateMachineBuilder.AddAnyState("Idle", idleName);
			modAnimStateMachineBuilder.AddAnyState("Dead", deadName ?? idleName);
			modAnimStateMachineBuilder.AddAnyState("Hit", hitName ?? idleName);
			modAnimStateMachineBuilder.AddAnyState("Attack", attackName ?? idleName);
			modAnimStateMachineBuilder.AddAnyState("Cast", castName ?? idleName);
			modAnimStateMachineBuilder.AddAnyState("Relaxed", toId);
			return modAnimStateMachineBuilder.BuildForVisualsRoot(visualsRoot, character, cueSet);
		}

		/// <summary>
		///     <para xml:lang="en">Builds the standard graph, preferring the character's merchant visual cue set.</para>
		///     <para xml:lang="zh-CN">构建标准状态图，并优先使用角色的商店视觉提示集。</para>
		/// </summary>
		public static ModAnimStateMachine StandardMerchantCue(Node visualsRoot, CharacterModel? character, string idleName, string? deadName = null, bool deadLoop = false, string? hitName = null, bool hitLoop = false, string? attackName = null, bool attackLoop = false, string? castName = null, bool castLoop = false, string? relaxedName = null, bool relaxedLoop = true, VisualCueSet? cueSet = null)
		{
			return StandardCue(visualsRoot, character, idleName, deadName, deadLoop, hitName, hitLoop, attackName, attackLoop, castName, castLoop, relaxedName, relaxedLoop, cueSet ?? TryGetMerchantCueSet(character));
		}

		/// <summary>
		///     <para xml:lang="en">Builds the standard graph, preferring the character's rest-site visual cue set.</para>
		///     <para xml:lang="zh-CN">构建标准状态图，并优先使用角色的休息处视觉提示集。</para>
		/// </summary>
		public static ModAnimStateMachine StandardRestSiteCue(Node visualsRoot, CharacterModel? character, string idleName, string? deadName = null, bool deadLoop = false, string? hitName = null, bool hitLoop = false, string? attackName = null, bool attackLoop = false, string? castName = null, bool castLoop = false, string? relaxedName = null, bool relaxedLoop = true, VisualCueSet? cueSet = null)
		{
			return StandardCue(visualsRoot, character, idleName, deadName, deadLoop, hitName, hitLoop, attackName, attackLoop, castName, castLoop, relaxedName, relaxedLoop, cueSet ?? TryGetRestSiteCueSet(character));
		}

		private static void AddOptional(ModAnimStateMachineBuilder builder, string? name, bool loop, string idleName, bool hasNext)
		{
			if (name != null && !string.Equals(name, idleName, StringComparison.Ordinal))
			{
				ModAnimStateMachineBuilder.StateScope stateScope = builder.AddState(name, loop);
				if (hasNext)
				{
					stateScope.WithNext(idleName);
				}
			}
		}

		private static void ValidateOptionalAnimationName(string? name, string paramName)
		{
			if (name != null && string.IsNullOrWhiteSpace(name))
			{
				throw new ArgumentException("Optional animation names must not be empty or whitespace.", paramName);
			}
		}

		private static VisualCueSet? TryGetMerchantCueSet(CharacterModel? character)
		{
			object obj;
			if (character is IModCharacterAssetOverrides modCharacterAssetOverrides)
			{
				obj = modCharacterAssetOverrides.WorldProceduralVisuals?.Merchant?.CueSet;
				if (obj == null)
				{
					return modCharacterAssetOverrides.VisualCues;
				}
			}
			else
			{
				obj = null;
			}
			return (VisualCueSet?)obj;
		}

		private static VisualCueSet? TryGetRestSiteCueSet(CharacterModel? character)
		{
			object obj;
			if (character is IModCharacterAssetOverrides modCharacterAssetOverrides)
			{
				obj = modCharacterAssetOverrides.WorldProceduralVisuals?.RestSite?.CueSet;
				if (obj == null)
				{
					return modCharacterAssetOverrides.VisualCues;
				}
			}
			else
			{
				obj = null;
			}
			return (VisualCueSet?)obj;
		}
	}
}
namespace STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends
{
	/// <summary>
	///     <para xml:lang="en">Drives a Godot <see cref="T:Godot.AnimatedSprite2D" /> through <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend" />.</para>
	///     <para xml:lang="zh-CN">通过 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend" /> 驱动 Godot <see cref="T:Godot.AnimatedSprite2D" />。</para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         When the requested loop flag differs from the value stored in <see cref="T:Godot.SpriteFrames" />, the backend updates
	///         the resource to honor the state-machine request. Completion is reported through
	///         <see cref="E:Godot.AnimatedSprite2D.AnimationFinished" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         当请求的循环标记与 <see cref="T:Godot.SpriteFrames" /> 中存储的值不同时，后端会更新该资源以遵循状态机请求。
	///         播放完成通过 <see cref="E:Godot.AnimatedSprite2D.AnimationFinished" /> 报告。
	///     </para>
	/// </remarks>
	public sealed class AnimatedSprite2DBackend : IAnimationBackend, IAnimationTimingProvider
	{
		private readonly Callable _finishedCallable;

		private readonly AnimatedSprite2D _sprite;

		private string? _currentId;

		private string? _queuedId;

		private bool _queuedLoop;

		/// <inheritdoc />
		public Node OwnerNode => (Node)(object)_sprite;

		/// <inheritdoc />
		public event Action<string>? Started;

		/// <inheritdoc />
		public event Action<string>? Completed;

		/// <inheritdoc />
		public event Action<string>? Interrupted;

		/// <summary>
		///     <para xml:lang="en">
		///         Wraps <paramref name="sprite" /> and connects to <see cref="E:Godot.AnimatedSprite2D.AnimationFinished" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         包装 <paramref name="sprite" />，并连接 <see cref="E:Godot.AnimatedSprite2D.AnimationFinished" /> 信号。
		///     </para>
		/// </summary>
		public AnimatedSprite2DBackend(AnimatedSprite2D sprite)
		{
			//IL_0025: Unknown result type (might be due to invalid IL or missing references)
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			base..ctor();
			ArgumentNullException.ThrowIfNull(sprite, "sprite");
			_sprite = sprite;
			_finishedCallable = Callable.From((Action)OnAnimationFinished);
			((GodotObject)_sprite).Connect(SignalName.AnimationFinished, _finishedCallable, 0u);
		}

		/// <inheritdoc />
		public bool HasAnimation(string id)
		{
			if (!string.IsNullOrWhiteSpace(id) && _sprite.SpriteFrames != null)
			{
				return _sprite.SpriteFrames.HasAnimation(StringName.op_Implicit(id));
			}
			return false;
		}

		/// <inheritdoc />
		public void Play(string id, bool loop)
		{
			if (HasAnimation(id))
			{
				if (_currentId != null && _sprite.IsPlaying())
				{
					Interrupted?.Invoke(_currentId);
				}
				_queuedId = null;
				_currentId = id;
				SpriteFrames spriteFrames = _sprite.SpriteFrames;
				if (spriteFrames != null && spriteFrames.GetAnimationLoop(StringName.op_Implicit(id)) != loop)
				{
					spriteFrames.SetAnimationLoop(StringName.op_Implicit(id), loop);
				}
				_sprite.Play(StringName.op_Implicit(id), 1f, false);
				Started?.Invoke(id);
			}
		}

		/// <inheritdoc />
		public void Queue(string id, bool loop)
		{
			if (HasAnimation(id))
			{
				if (_currentId == null || !_sprite.IsPlaying())
				{
					Play(id, loop);
					return;
				}
				_queuedId = id;
				_queuedLoop = loop;
			}
		}

		/// <inheritdoc />
		public void Stop()
		{
			_queuedId = null;
			_currentId = null;
			if (_sprite.IsPlaying())
			{
				_sprite.Stop();
			}
		}

		/// <inheritdoc />
		public bool TryGetAnimationDuration(string id, out float seconds)
		{
			seconds = 0f;
			SpriteFrames spriteFrames = _sprite.SpriteFrames;
			if (string.IsNullOrWhiteSpace(id) || spriteFrames == null || !spriteFrames.HasAnimation(StringName.op_Implicit(id)))
			{
				return false;
			}
			float animationPlaybackSpeed = GetAnimationPlaybackSpeed(spriteFrames, id, useLiveSpeed: false);
			if (animationPlaybackSpeed <= 0f)
			{
				return false;
			}
			int frameCount = spriteFrames.GetFrameCount(StringName.op_Implicit(id));
			for (int i = 0; i < frameCount; i++)
			{
				seconds += spriteFrames.GetFrameDuration(StringName.op_Implicit(id), i);
			}
			seconds /= animationPlaybackSpeed;
			if (seconds > 0f)
			{
				return float.IsFinite(seconds);
			}
			return false;
		}

		/// <inheritdoc />
		public bool TryGetCurrentAnimationRemaining(out float seconds)
		{
			seconds = 0f;
			SpriteFrames spriteFrames = _sprite.SpriteFrames;
			string text = _currentId ?? ((object)_sprite.Animation).ToString();
			if (string.IsNullOrWhiteSpace(text) || spriteFrames == null || !spriteFrames.HasAnimation(StringName.op_Implicit(text)))
			{
				return false;
			}
			float animationPlaybackSpeed = GetAnimationPlaybackSpeed(spriteFrames, text, useLiveSpeed: true);
			if (animationPlaybackSpeed <= 0f)
			{
				return false;
			}
			int frameCount = spriteFrames.GetFrameCount(StringName.op_Implicit(text));
			int num = Math.Clamp(_sprite.Frame, 0, Math.Max(0, frameCount - 1));
			float num2 = Math.Clamp(_sprite.FrameProgress, 0f, 1f);
			for (int i = num; i < frameCount; i++)
			{
				float frameDuration = spriteFrames.GetFrameDuration(StringName.op_Implicit(text), i);
				seconds += ((i == num) ? (frameDuration * (1f - num2)) : frameDuration);
			}
			seconds /= animationPlaybackSpeed;
			if (seconds >= 0f)
			{
				return float.IsFinite(seconds);
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Disconnects the signal handler. Repeated calls are safe.</para>
		///     <para xml:lang="zh-CN">断开信号处理程序；可安全地重复调用。</para>
		/// </summary>
		public void Dispose()
		{
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0024: Unknown result type (might be due to invalid IL or missing references)
			if (((GodotObject)_sprite).IsConnected(SignalName.AnimationFinished, _finishedCallable))
			{
				((GodotObject)_sprite).Disconnect(SignalName.AnimationFinished, _finishedCallable);
			}
		}

		private void OnAnimationFinished()
		{
			Completed?.Invoke(_currentId ?? ((object)_sprite.Animation).ToString());
			string queuedId = _queuedId;
			if (queuedId != null)
			{
				bool queuedLoop = _queuedLoop;
				_queuedId = null;
				Play(queuedId, queuedLoop);
			}
		}

		private float GetAnimationPlaybackSpeed(SpriteFrames frames, string id, bool useLiveSpeed)
		{
			if (useLiveSpeed && _sprite.IsPlaying())
			{
				float num = Math.Abs(_sprite.GetPlayingSpeed());
				if (num > 0f)
				{
					return num;
				}
			}
			float num2 = (float)Math.Abs(frames.GetAnimationSpeed(StringName.op_Implicit(id)) * (double)_sprite.SpeedScale);
			if (!(num2 > 0f))
			{
				return (float)Math.Abs(frames.GetAnimationSpeed(StringName.op_Implicit(id)));
			}
			return num2;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Drives a Godot <see cref="T:Godot.AnimationTree" /> whose root is an
	///         <see cref="T:Godot.AnimationNodeStateMachine" /> through <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend" /> 驱动以 <see cref="T:Godot.AnimationNodeStateMachine" /> 为根节点的
	///         Godot <see cref="T:Godot.AnimationTree" />。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         State IDs map to state-machine node names, and <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.AnimationTreeStateMachineBackend.Play(System.String,System.Boolean)" /> transitions through
	///         <see cref="M:Godot.AnimationNodeStateMachinePlayback.Travel(Godot.StringName,System.Boolean)" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         状态 ID 对应状态机节点名称，<see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.AnimationTreeStateMachineBackend.Play(System.String,System.Boolean)" /> 通过
	///         <see cref="M:Godot.AnimationNodeStateMachinePlayback.Travel(Godot.StringName,System.Boolean)" /> 切换状态。
	///     </para>
	/// </remarks>
	public sealed class AnimationTreeStateMachineBackend : IAnimationBackend
	{
		private readonly Callable _finishedCallable;

		private readonly AnimationNodeStateMachinePlayback _playback;

		private readonly AnimationPlayer? _player;

		private readonly AnimationTree _tree;

		private readonly AnimationNodeStateMachine _treeRoot;

		private string? _currentId;

		private string? _queuedId;

		private bool _queuedLoop;

		private bool _suppressEvents;

		/// <inheritdoc />
		public Node OwnerNode => (Node)(object)_tree;

		/// <inheritdoc />
		public event Action<string>? Started;

		/// <inheritdoc />
		public event Action<string>? Completed;

		/// <inheritdoc />
		public event Action<string>? Interrupted;

		/// <summary>
		///     <para xml:lang="en">Wraps <paramref name="tree" /> and binds to its state-machine playback object.</para>
		///     <para xml:lang="zh-CN">包装 <paramref name="tree" />，并绑定其状态机播放对象。</para>
		/// </summary>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">
		///         Thrown when <paramref name="tree" /> is not configured with a valid state-machine root and playback object.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当 <paramref name="tree" /> 未配置有效的状态机根节点和播放对象时抛出。
		///     </para>
		/// </exception>
		public AnimationTreeStateMachineBackend(AnimationTree tree)
		{
			//IL_0049: Unknown result type (might be due to invalid IL or missing references)
			//IL_004e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0088: Unknown result type (might be due to invalid IL or missing references)
			//IL_008d: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a9: Unknown result type (might be due to invalid IL or missing references)
			base..ctor();
			ArgumentNullException.ThrowIfNull(tree, "tree");
			_tree = tree;
			AnimationRootNode treeRoot = tree.TreeRoot;
			_treeRoot = (AnimationNodeStateMachine)(object)(((treeRoot is AnimationNodeStateMachine) ? treeRoot : null) ?? throw new ArgumentException("AnimationTree.TreeRoot must be AnimationNodeStateMachine.", "tree"));
			Variant val = ((GodotObject)tree).Get(StringName.op_Implicit("parameters/playback"));
			_playback = ((Variant)(ref val)).As<AnimationNodeStateMachinePlayback>() ?? throw new ArgumentException("AnimationTree is missing a valid parameters/playback object.", "tree");
			_player = ResolveAnimationPlayer(tree);
			_finishedCallable = Callable.From<StringName>((Action<StringName>)OnAnimationFinished);
			AnimationPlayer? player = _player;
			if (player != null)
			{
				((GodotObject)player).Connect(SignalName.AnimationFinished, _finishedCallable, 0u);
			}
		}

		/// <inheritdoc />
		public bool HasAnimation(string id)
		{
			if (!string.IsNullOrWhiteSpace(id))
			{
				return _treeRoot.HasNode(StringName.op_Implicit(id));
			}
			return false;
		}

		/// <inheritdoc />
		public void Play(string id, bool loop)
		{
			if (HasAnimation(id))
			{
				EnsureTreeActive();
				if (_currentId != null)
				{
					Interrupted?.Invoke(_currentId);
				}
				_queuedId = null;
				_currentId = id;
				_playback.Travel(StringName.op_Implicit(id), true);
				Started?.Invoke(id);
			}
		}

		/// <inheritdoc />
		public void Queue(string id, bool loop)
		{
			if (HasAnimation(id))
			{
				if (_currentId == null)
				{
					Play(id, loop);
					return;
				}
				_queuedId = id;
				_queuedLoop = loop;
			}
		}

		/// <inheritdoc />
		public void Stop()
		{
			_suppressEvents = true;
			try
			{
				_queuedId = null;
				_currentId = null;
				((AnimationMixer)_tree).Active = false;
			}
			finally
			{
				_suppressEvents = false;
