		/// <summary>
		///     <para xml:lang="en">Disconnects the optional player signal handler. Repeated calls are safe.</para>
		///     <para xml:lang="zh-CN">断开可选的播放器信号处理程序；可安全地重复调用。</para>
		/// </summary>
		public void Dispose()
		{
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_002d: Unknown result type (might be due to invalid IL or missing references)
			if (_player != null && ((GodotObject)_player).IsConnected(SignalName.AnimationFinished, _finishedCallable))
			{
				((GodotObject)_player).Disconnect(SignalName.AnimationFinished, _finishedCallable);
			}
		}

		private void OnAnimationFinished(StringName animName)
		{
			if (!_suppressEvents && !string.IsNullOrEmpty(_currentId))
			{
				string currentId = _currentId;
				_currentId = null;
				Completed?.Invoke(currentId);
				string queuedId = _queuedId;
				if (queuedId != null)
				{
					bool queuedLoop = _queuedLoop;
					_queuedId = null;
					Play(queuedId, queuedLoop);
				}
			}
		}

		private void EnsureTreeActive()
		{
			if (!((AnimationMixer)_tree).Active)
			{
				((AnimationMixer)_tree).Active = true;
			}
		}

		private static AnimationPlayer? ResolveAnimationPlayer(AnimationTree tree)
		{
			NodePath animPlayer = tree.AnimPlayer;
			if (!animPlayer.IsEmpty)
			{
				return ((Node)tree).GetNodeOrNull<AnimationPlayer>(animPlayer);
			}
			return null;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Routes each animation ID to the first child <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend" /> that supports it.</para>
	///     <para xml:lang="zh-CN">将每个动画 ID 路由至第一个支持它的子 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend" />。</para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Priority follows insertion order. Typical wiring (cue frame sequences and static textures first,
	///         then Spine, then Godot animation player, then animated sprite) is produced by
	///         <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachineBuilder" />.
	///     </para>
	///     <para xml:lang="en">
	///         Only one child is <c>active</c> at a time. Switching to a different backend during
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CompositeAnimationBackend.Play(System.String,System.Boolean)" /> raises <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CompositeAnimationBackend.Interrupted" /> for the previously active id and
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Stop" />s the outgoing backend so it does not continue playing
	///         alongside the newly activated one. <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CompositeAnimationBackend.Queue(System.String,System.Boolean)" /> across backends is deferred until the
	///         current backend reports <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CompositeAnimationBackend.Completed" />, at which point the stashed
	///         <c>(backend, id, loop)</c> triple is activated.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         优先级遵循插入顺序。典型接线（先是 cue 帧序列和静态纹理，
	///         然后是 Spine、Godot animation player、animated sprite）由
	///         <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachineBuilder" /> 生成。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         同一时间只有一个子项为 <c>active</c>。在 <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CompositeAnimationBackend.Play(System.String,System.Boolean)" /> 期间切换到不同后端时，
	///         会为先前活动的 id 触发 <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CompositeAnimationBackend.Interrupted" />，并对即将离开的后端调用
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend.Stop" />，使其不会继续与新激活的后端
	///         同时播放。跨后端的 <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CompositeAnimationBackend.Queue(System.String,System.Boolean)" /> 会延迟到当前后端报告
	///         <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CompositeAnimationBackend.Completed" /> 后再执行，此时会激活暂存的
	///         <c>(backend, id, loop)</c> 三元组。
	///     </para>
	/// </remarks>
	public sealed class CompositeAnimationBackend : IAnimationBackend, IAnimationTimingProvider
	{
		private readonly IReadOnlyList<IAnimationBackend> _backends;

		private IAnimationBackend? _active;

		private string? _currentId;

		private IAnimationBackend? _queuedBackend;

		private string? _queuedId;

		private bool _queuedLoop;

		/// <inheritdoc />
		public Node? OwnerNode { get; }

		/// <inheritdoc />
		public event Action<string>? Started;

		/// <inheritdoc />
		public event Action<string>? Completed;

		/// <inheritdoc />
		public event Action<string>? Interrupted;

		/// <summary>
		///     <para xml:lang="en">Creates a composite from <paramref name="backends" /> in priority order.</para>
		///     <para xml:lang="zh-CN">按优先级顺序从 <paramref name="backends" /> 创建组合后端。</para>
		/// </summary>
		public CompositeAnimationBackend(IReadOnlyList<IAnimationBackend> backends, Node? ownerNode = null)
		{
			ArgumentNullException.ThrowIfNull(backends, "backends");
			if (backends.Count == 0)
			{
				throw new ArgumentException("At least one backend is required.", "backends");
			}
			_backends = backends;
			OwnerNode = ownerNode ?? backends[0].OwnerNode;
			foreach (IAnimationBackend backend in _backends)
			{
				backend.Started += delegate(string id)
				{
					OnChildStarted(backend, id);
				};
				backend.Completed += delegate(string id)
				{
					OnChildCompleted(backend, id);
				};
				backend.Interrupted += delegate(string id)
				{
					OnChildInterrupted(backend, id);
				};
			}
		}

		/// <inheritdoc />
		public bool HasAnimation(string id)
		{
			return _backends.Any((IAnimationBackend backend) => backend.HasAnimation(id));
		}

		/// <inheritdoc />
		public void Play(string id, bool loop)
		{
			IAnimationBackend animationBackend = Resolve(id);
			if (animationBackend == null)
			{
				return;
			}
			int num;
			if (_active != null)
			{
				num = ((_active != animationBackend) ? 1 : 0);
				if (num != 0 && _currentId != null)
				{
					Interrupted?.Invoke(_currentId);
				}
			}
			else
			{
				num = 0;
			}
			if (num != 0)
			{
				_active.Stop();
			}
			ClearQueued();
			_active = animationBackend;
			_currentId = id;
			animationBackend.Play(id, loop);
		}

		/// <inheritdoc />
		public void Queue(string id, bool loop)
		{
			IAnimationBackend animationBackend = Resolve(id);
			if (animationBackend != null)
			{
				if (_active == null)
				{
					Play(id, loop);
				}
				else if (_active == animationBackend)
				{
					ClearQueued();
					animationBackend.Queue(id, loop);
				}
				else
				{
					_queuedBackend = animationBackend;
					_queuedId = id;
					_queuedLoop = loop;
				}
			}
		}

		/// <inheritdoc />
		public void Stop()
		{
			ClearQueued();
			IAnimationBackend? active = _active;
			_active = null;
			_currentId = null;
			active?.Stop();
		}

		/// <inheritdoc />
		public bool TryGetAnimationDuration(string id, out float seconds)
		{
			seconds = 0f;
			if (Resolve(id) is IAnimationTimingProvider animationTimingProvider)
			{
				return animationTimingProvider.TryGetAnimationDuration(id, out seconds);
			}
			return false;
		}

		/// <inheritdoc />
		public bool TryGetCurrentAnimationRemaining(out float seconds)
		{
			seconds = 0f;
			if (_active is IAnimationTimingProvider animationTimingProvider)
			{
				return animationTimingProvider.TryGetCurrentAnimationRemaining(out seconds);
			}
			return false;
		}

		private IAnimationBackend? Resolve(string id)
		{
			return _backends.FirstOrDefault((IAnimationBackend backend) => backend.HasAnimation(id));
		}

		private void ClearQueued()
		{
			_queuedBackend = null;
			_queuedId = null;
			_queuedLoop = false;
		}

		private void OnChildStarted(IAnimationBackend backend, string id)
		{
			if (backend == _active)
			{
				Started?.Invoke(id);
			}
		}

		private void OnChildCompleted(IAnimationBackend backend, string id)
		{
			if (backend != _active)
			{
				return;
			}
			Completed?.Invoke(id);
			if (backend != _active)
			{
				return;
			}
			IAnimationBackend queuedBackend = _queuedBackend;
			if (queuedBackend != null)
			{
				string queuedId = _queuedId;
				if (queuedId != null)
				{
					bool queuedLoop = _queuedLoop;
					ClearQueued();
					backend.Stop();
					_active = queuedBackend;
					_currentId = queuedId;
					queuedBackend.Play(queuedId, queuedLoop);
				}
			}
		}

		private void OnChildInterrupted(IAnimationBackend backend, string id)
		{
			if (backend == _active)
			{
				Interrupted?.Invoke(id);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Drives cue-based visuals from static textures and <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualFrameSequence" /> data.</para>
	///     <para xml:lang="zh-CN">从静态纹理和 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualFrameSequence" /> 数据驱动基于视觉提示的效果。</para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Animation ids map to cue keys in <see cref="P:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSet.FrameSequenceByCue" /> (preferred) or
	///         <see cref="P:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSet.TexturePathByCue" /> (fallback static texture). Frame sequences are played
	///         through <see cref="T:STS2RitsuLib.Scaffolding.Visuals.CueFrameSequencePlayer" />; its <c>Finished</c> signal is converted to
	///         <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CueAnimationBackend.Completed" />.
	///     </para>
	///     <para xml:lang="en">
	///         Non-looping static cues raise <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CueAnimationBackend.Completed" /> on the next idle frame so the state machine
	///         can advance without re-entering the caller synchronously.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         动画 id 映射到 <see cref="P:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSet.FrameSequenceByCue" /> 中的 cue 键（优先）或
	///         <see cref="P:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSet.TexturePathByCue" />（回退静态纹理）。帧序列通过
	///         <see cref="T:STS2RitsuLib.Scaffolding.Visuals.CueFrameSequencePlayer" /> 播放；其 <c>Finished</c> 信号会转换为
	///         <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CueAnimationBackend.Completed" />。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         非循环静态 cue 会在下一次 idle 帧触发 <see cref="E:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.CueAnimationBackend.Completed" />，使状态机
	///         可以继续推进，而不会同步重入调用方。
	///     </para>
	/// </remarks>
	public sealed class CueAnimationBackend : IAnimationBackend, IAnimationTimingProvider
	{
		private readonly VisualCueSet _cues;

		private readonly Callable _finishedCallable;

		private readonly Sprite2D _sprite;

		private string? _currentId;

		private string? _queuedId;

		private bool _queuedLoop;

		private CueFrameSequencePlayer? _subscribedPlayer;

		/// <inheritdoc />
		public Node OwnerNode { get; }

		/// <inheritdoc />
		public event Action<string>? Started;

		/// <inheritdoc />
		public event Action<string>? Completed;

		/// <inheritdoc />
		public event Action<string>? Interrupted;

		/// <summary>
		///     <para xml:lang="en">Binds <paramref name="cues" /> to <paramref name="sprite" /> under <paramref name="root" />.</para>
		///     <para xml:lang="zh-CN">将 <paramref name="cues" /> 绑定到 <paramref name="root" /> 下的 <paramref name="sprite" />。</para>
		/// </summary>
		public CueAnimationBackend(Node root, Sprite2D sprite, VisualCueSet cues)
		{
			//IL_0049: Unknown result type (might be due to invalid IL or missing references)
			//IL_004e: Unknown result type (might be due to invalid IL or missing references)
			base..ctor();
			ArgumentNullException.ThrowIfNull(root, "root");
			ArgumentNullException.ThrowIfNull(sprite, "sprite");
			ArgumentNullException.ThrowIfNull(cues, "cues");
			OwnerNode = root;
			_sprite = sprite;
			_cues = cues;
			_finishedCallable = Callable.From((Action)OnSequenceFinished);
		}

		/// <inheritdoc />
		public bool HasAnimation(string id)
		{
			if (string.IsNullOrWhiteSpace(id))
			{
				return false;
			}
			IReadOnlyDictionary<string, VisualFrameSequence> frameSequenceByCue = _cues.FrameSequenceByCue;
			if (frameSequenceByCue != null && frameSequenceByCue.Count > 0 && TryGetOrdinalIgnoreCase(frameSequenceByCue, id, out VisualFrameSequence value) && (object)value != null)
			{
				IReadOnlyList<VisualFrame> frames = value.Frames;
				if (frames != null && frames.Count > 0)
				{
					return true;
				}
			}
			IReadOnlyDictionary<string, string> texturePathByCue = _cues.TexturePathByCue;
			if (texturePathByCue != null && texturePathByCue.Count > 0 && TryGetOrdinalIgnoreCase(texturePathByCue, id, out string value2))
			{
				return !string.IsNullOrWhiteSpace(value2);
			}
			return false;
		}

		/// <inheritdoc />
		public void Play(string id, bool loop)
		{
			if (!HasAnimation(id))
			{
				return;
			}
			if (_currentId != null)
			{
				Interrupted?.Invoke(_currentId);
			}
			UnsubscribeActivePlayer();
			CueFrameSequencePlayer.StopUnder(OwnerNode);
			_queuedId = null;
			_currentId = null;
			IReadOnlyDictionary<string, VisualFrameSequence> frameSequenceByCue = _cues.FrameSequenceByCue;
			if (frameSequenceByCue != null && frameSequenceByCue.Count > 0 && TryGetOrdinalIgnoreCase(frameSequenceByCue, id, out VisualFrameSequence value) && (object)value != null)
			{
				IReadOnlyList<VisualFrame> frames = value.Frames;
				if (frames != null && frames.Count > 0)
				{
					CueFrameSequencePlayer cueFrameSequencePlayer = CueFrameSequencePlayer.EnsureUnder(OwnerNode);
					VisualFrameSequence sequence = ((value.Loop == loop) ? value : value with
					{
						Loop = loop
					});
					if (cueFrameSequencePlayer.TryStart(_sprite, sequence))
					{
						_currentId = id;
						SubscribePlayer(cueFrameSequencePlayer);
						Started?.Invoke(id);
					}
					return;
				}
			}
			IReadOnlyDictionary<string, string> texturePathByCue = _cues.TexturePathByCue;
			if (texturePathByCue == null || texturePathByCue.Count <= 0 || !TryGetOrdinalIgnoreCase(texturePathByCue, id, out string value2) || string.IsNullOrWhiteSpace(value2))
			{
				return;
			}
			Texture2D val = ResourceLoader.Load<Texture2D>(value2, (string)null, (CacheMode)1);
			if (val != null)
			{
				_currentId = id;
				_sprite.Texture = val;
				IReadOnlyDictionary<string, VisualNodeStyle> textureStyleByCue = _cues.TextureStyleByCue;
				if (textureStyleByCue != null && textureStyleByCue.Count > 0 && TryGetOrdinalIgnoreCase(textureStyleByCue, id, out VisualNodeStyle value3))
				{
					value3.ApplyTo((Node?)(object)_sprite);
				}
				Started?.Invoke(id);
				if (!loop)
				{
					DeferCompletion(id);
				}
			}
		}

		/// <inheritdoc />
		public void Queue(string id, bool loop)
		{
			if (HasAnimation(id))
			{
				if (_currentId == null)
				{
					Play(id, loop);
					return;
				}
				_queuedId = id;
				_queuedLoop = loop;
			}
		}

		/// <inheritdoc />
		public void Stop()
		{
			_queuedId = null;
			_currentId = null;
			UnsubscribeActivePlayer();
			CueFrameSequencePlayer.StopUnder(OwnerNode);
		}

		/// <inheritdoc />
		public bool TryGetAnimationDuration(string id, out float seconds)
		{
			seconds = 0f;
			if (string.IsNullOrWhiteSpace(id))
			{
				return false;
			}
			IReadOnlyDictionary<string, VisualFrameSequence> frameSequenceByCue = _cues.FrameSequenceByCue;
			if (frameSequenceByCue != null && frameSequenceByCue.Count > 0 && TryGetOrdinalIgnoreCase(frameSequenceByCue, id, out VisualFrameSequence value) && (object)value != null)
			{
				IReadOnlyList<VisualFrame> frames = value.Frames;
				if (frames != null && frames.Count > 0)
				{
					seconds = GetSequenceDuration(value);
					return seconds > 0f;
				}
			}
			return false;
		}

		/// <inheritdoc />
		public bool TryGetCurrentAnimationRemaining(out float seconds)
		{
			seconds = 0f;
			if (GodotObject.IsInstanceValid((GodotObject)(object)_subscribedPlayer))
			{
				return _subscribedPlayer.TryGetRemaining(out seconds);
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Stops active playback and detaches any frame-sequence signal handler.</para>
		///     <para xml:lang="zh-CN">停止当前播放并断开所有帧序列信号处理程序。</para>
		/// </summary>
		public void Dispose()
		{
			UnsubscribeActivePlayer();
			CueFrameSequencePlayer.StopUnder(OwnerNode);
		}

		private void SubscribePlayer(CueFrameSequencePlayer player)
		{
			//IL_000e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0014: Unknown result type (might be due to invalid IL or missing references)
			_subscribedPlayer = player;
			((GodotObject)player).Connect(CueFrameSequencePlayer.SignalName.Finished, _finishedCallable, 0u);
		}

		private void UnsubscribeActivePlayer()
		{
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_003a: Unknown result type (might be due to invalid IL or missing references)
			if (_subscribedPlayer != null)
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)_subscribedPlayer) && ((GodotObject)_subscribedPlayer).IsConnected(CueFrameSequencePlayer.SignalName.Finished, _finishedCallable))
				{
					((GodotObject)_subscribedPlayer).Disconnect(CueFrameSequencePlayer.SignalName.Finished, _finishedCallable);
				}
				_subscribedPlayer = null;
			}
		}

		private void OnSequenceFinished()
		{
			UnsubscribeActivePlayer();
			string obj = _currentId ?? string.Empty;
			_currentId = null;
			Completed?.Invoke(obj);
			ConsumeQueue();
		}

		private void DeferCompletion(string id)
		{
			if (!GodotObject.IsInstanceValid((GodotObject)(object)OwnerNode))
			{
				return;
			}
			SceneTree tree = OwnerNode.GetTree();
			if (tree == null)
			{
				_currentId = null;
				Completed?.Invoke(id);
				ConsumeQueue();
				return;
			}
			tree.CreateTimer(0.0, true, false, false).Timeout += delegate
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)OwnerNode) && GodotObject.IsInstanceValid((GodotObject)(object)_sprite) && !(_currentId != id))
				{
					_currentId = null;
					Completed?.Invoke(id);
					ConsumeQueue();
				}
			};
		}

		private void ConsumeQueue()
		{
			string queuedId = _queuedId;
			if (queuedId != null)
			{
				bool queuedLoop = _queuedLoop;
				_queuedId = null;
				Play(queuedId, queuedLoop);
			}
		}

		private static bool TryGetOrdinalIgnoreCase<TValue>(IReadOnlyDictionary<string, TValue> map, string key, out TValue? value)
		{
			if (map.TryGetValue(key, out TValue value2))
			{
				value = value2;
				return true;
			}
			foreach (KeyValuePair<string, TValue> item in map)
			{
				if (string.Equals(item.Key, key, StringComparison.OrdinalIgnoreCase))
				{
					value = item.Value;
					return true;
				}
			}
			value = default(TValue);
			return false;
		}

		private static float GetSequenceDuration(VisualFrameSequence sequence)
		{
			return (from frame in sequence.Frames
				select frame.DurationSeconds into seconds
				select (float.IsFinite(seconds) && !(seconds <= 0f)) ? seconds : (1f / 60f)).Sum();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Multiplexes per-form <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend" /> instances, keeping one active while allowing
	///         runtime form changes beneath a persistent <see cref="T:MegaCrit.Sts2.Core.Nodes.Combat.NCreatureVisuals" /> root.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         复用各形态的 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.IAnimationBackend" /> 实例；在持久的
	///         <see cref="T:MegaCrit.Sts2.Core.Nodes.Combat.NCreatureVisuals" /> 根节点下切换形态时仅保持一个后端活动。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         This backend is intended for the "single visuals root, switch child form" pattern: each form gets its
	///         own child backend (Spine, animated sprite, animation player, ...), and
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.FormSwitchingAnimationBackend.SwitchForm(System.String,System.Boolean)" /> swaps the active backend without rebuilding the creature node.
	///     </para>
	///     <para xml:lang="en">
	///         If <c>replayCurrent</c> is <see langword="true" />, switching replays the current logical
	///         animation id on the newly selected form when possible; otherwise callers typically follow with an
	///         explicit trigger (for example <c>SetTrigger("Idle")</c>).
	///     </para>
	///     <para xml:lang="zh-CN">
	///         此后端用于“单一视觉根节点、切换子形态”模式：每个形态都有自己的
	///         子后端（Spine、动画精灵、动画播放器等），并由
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.Backends.FormSwitchingAnimationBackend.SwitchForm(System.String,System.Boolean)" /> 在不重建生物节点的情况下切换活动后端。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         如果 <c>replayCurrent</c> 为 <see langword="true" />，切换时会在可能的情况下于新选中的形态上重放当前逻辑
	///         动画 ID；否则调用方通常会紧接着显式触发一次状态切换（例如 <c>SetTrigger("Idle")</c>）。
	///     </para>
	/// </remarks>
	public sealed class FormSwitchingAnimationBackend : IAnimationBackend, IAnimationTimingProvider
	{
		private readonly Dictionary<string, IAnimationBackend> _backendsByForm;

		private readonly Dictionary<string, bool> _loopByAnimationId = new Dictionary<string, bool>(StringComparer.Ordinal);

		private string? _currentId;

		private bool _currentLoop;

		private string? _queuedId;

		private bool _queuedLoop;

		/// <summary>
		///     <para xml:lang="en">Gets the active form ID.</para>
		///     <para xml:lang="zh-CN">获取当前激活的形态 ID。</para>
		/// </summary>
		public string ActiveFormId { get; private set; }

		private IAnimationBackend CurrentBackend => _backendsByForm[ActiveFormId];

		/// <inheritdoc />
		public Node? OwnerNode { get; }

		/// <inheritdoc />
		public event Action<string>? Started;

		/// <inheritdoc />
		public event Action<string>? Completed;

		/// <inheritdoc />
		public event Action<string>? Interrupted;

		/// <summary>
		///     <para xml:lang="en">Creates a switchable backend over prebuilt per-form backends.</para>
		///     <para xml:lang="zh-CN">从预先构建的各形态后端创建可切换后端。</para>
		/// </summary>
		/// <param name="backendsByForm">
		///     <para xml:lang="en">Maps stable form IDs to backend instances.</para>
		///     <para xml:lang="zh-CN">从稳定形态 ID 到后端实例的映射。</para>
		/// </param>
		/// <param name="initialFormId">
		///     <para xml:lang="en">The initially active form ID.</para>
		///     <para xml:lang="zh-CN">初始激活的形态 ID。</para>
		/// </param>
		/// <param name="ownerNode">
		///     <para xml:lang="en">Optional owner-node override.</para>
		///     <para xml:lang="zh-CN">可选的所有者节点覆盖。</para>
		/// </param>
		public FormSwitchingAnimationBackend(IReadOnlyDictionary<string, IAnimationBackend> backendsByForm, string initialFormId, Node? ownerNode = null)
		{
			ArgumentNullException.ThrowIfNull(backendsByForm, "backendsByForm");
			ArgumentException.ThrowIfNullOrWhiteSpace(initialFormId, "initialFormId");
			if (backendsByForm.Count == 0)
			{
				throw new ArgumentException("At least one form backend is required.", "backendsByForm");
			}
			_backendsByForm = new Dictionary<string, IAnimationBackend>(StringComparer.Ordinal);
			foreach (KeyValuePair<string, IAnimationBackend> item in backendsByForm)
			{
				var (text2, backend) = item;
				if (string.IsNullOrWhiteSpace(text2))
				{
					throw new ArgumentException("Form id cannot be null or whitespace.", "backendsByForm");
				}
				ArgumentNullException.ThrowIfNull(backend, "backend");
				if (!_backendsByForm.TryAdd(text2, backend))
				{
					throw new ArgumentException("Duplicate form id '" + text2 + "'.", "backendsByForm");
				}
				backend.Started += delegate(string id)
				{
					OnChildStarted(backend, id);
				};
				backend.Completed += delegate(string id)
				{
					OnChildCompleted(backend, id);
				};
				backend.Interrupted += delegate(string id)
				{
					OnChildInterrupted(backend, id);
				};
			}
			if (!_backendsByForm.ContainsKey(initialFormId))
			{
				throw new ArgumentException("Initial form '" + initialFormId + "' is missing from the backend map.", "initialFormId");
			}
			ActiveFormId = initialFormId;
			OwnerNode = ownerNode ?? _backendsByForm[ActiveFormId].OwnerNode;
		}

