		public void Play(string id, bool loop)
		{
			if (CurrentBackend.HasAnimation(id))
			{
				_queuedId = null;
				_currentId = id;
				_currentLoop = loop;
				_loopByAnimationId[id] = loop;
				CurrentBackend.Play(id, loop);
			}
		}

		/// <inheritdoc />
		public void Queue(string id, bool loop)
		{
			if (CurrentBackend.HasAnimation(id))
			{
				_queuedId = id;
				_queuedLoop = loop;
				_loopByAnimationId[id] = loop;
				CurrentBackend.Queue(id, loop);
			}
		}

