		{
			track.SetTimeScale(Rng.Chaotic.NextFloat(0.9f, 1.1f));
			float animationEnd = track.GetAnimationEnd();
			track.SetTrackTime((animationEnd + Rng.Chaotic.NextFloat(-0.1f, 0.1f)) % animationEnd);
		}
	}
}
namespace STS2RitsuLib.Scaffolding.Visuals.Definition
{
	/// <summary>
	///     <para xml:lang="en">
	///         Defines immutable visuals for named cues, with one static texture, one <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualFrameSequence" />,
	///         or both for each cue. Cue sets support combat, game-over screens, merchant and rest-site characters,
	///         Ancient foreground layers, and similar contexts.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义按名称索引的不可变视觉提示；每个提示可包含一张静态纹理、一个
	///         <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualFrameSequence" />，或同时包含两者。视觉提示集可用于战斗、游戏结束界面、
	///         商人和休息处角色、先古事件前景图层等场景。
	///     </para>
	/// </summary>
	/// <param name="TexturePathByCue">
	///     <para xml:lang="en">The texture path associated with each cue key.</para>
	///     <para xml:lang="zh-CN">与每个视觉提示键关联的纹理路径。</para>
	/// </param>
	/// <param name="FrameSequenceByCue">
	///     <para xml:lang="en">
	///         The frame sequence associated with each cue key. A sequence takes precedence over
	///         <paramref name="TexturePathByCue" /> for the same key.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         与每个视觉提示键关联的帧序列。同一键同时存在时，帧序列优先于
	///         <paramref name="TexturePathByCue" />。
	///     </para>
	/// </param>
	public sealed record VisualCueSet(IReadOnlyDictionary<string, string>? TexturePathByCue = null, IReadOnlyDictionary<string, VisualFrameSequence>? FrameSequenceByCue = null)
	{
		/// <summary>
		///     <para xml:lang="en">Gets the optional per-cue style applied when a static texture is shown.</para>
		///     <para xml:lang="zh-CN">获取显示静态纹理时按视觉提示应用的可选样式。</para>
		/// </summary>
		public IReadOnlyDictionary<string, VisualNodeStyle>? TextureStyleByCue { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Initializes a cue set with optional style metadata. The two-parameter constructor remains available for
		///         binary compatibility with older mods.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用可选的样式元数据初始化视觉提示集。为保持与旧版模组的二进制兼容性，双参数构造函数仍然可用。
		///     </para>
		/// </summary>
		public VisualCueSet(IReadOnlyDictionary<string, string>? TexturePathByCue, IReadOnlyDictionary<string, VisualFrameSequence>? FrameSequenceByCue, IReadOnlyDictionary<string, VisualNodeStyle>? TextureStyleByCue)
			: this(TexturePathByCue, FrameSequenceByCue)
		{
			this.TextureStyleByCue = TextureStyleByCue;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides a fluent builder for <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSet" /> instances containing static textures or frame
	///         sequences for named cues.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSet" /> 的流式构建器，可为具名视觉提示配置静态纹理或帧序列。
	///     </para>
	/// </summary>
	public sealed class VisualCueSetBuilder
	{
		private readonly Dictionary<string, VisualFrameSequence> _sequences = new Dictionary<string, VisualFrameSequence>(StringComparer.OrdinalIgnoreCase);

		private readonly Dictionary<string, VisualNodeStyle> _textureStyles = new Dictionary<string, VisualNodeStyle>(StringComparer.OrdinalIgnoreCase);

		private readonly Dictionary<string, string> _textures = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

		private VisualCueSetBuilder()
		{
		}

		/// <summary>
		///     <para xml:lang="en">Starts a new cue-set definition.</para>
		///     <para xml:lang="zh-CN">开始定义新的视觉提示集。</para>
		/// </summary>
		public static VisualCueSetBuilder Create()
		{
			return new VisualCueSetBuilder();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Binds one static texture to a cue such as <c>idle</c> or <c>die</c>, replacing any frame sequence
		///         registered for the same key.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将一张静态纹理绑定到 <c>idle</c> 或 <c>die</c> 等视觉提示，并替换同一键下已有的帧序列。
		///     </para>
		/// </summary>
		public VisualCueSetBuilder Single(string cueKey, string texturePath)
		{
			return Single(cueKey, texturePath, null);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Binds one static texture to a cue and optionally applies style overrides while that cue is shown.
		///     </para>
		///     <para xml:lang="zh-CN">将一张静态纹理绑定到视觉提示，并可在显示该提示时应用样式覆盖。</para>
		/// </summary>
		public VisualCueSetBuilder Single(string cueKey, string texturePath, VisualNodeStyle? style)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(cueKey, "cueKey");
			ArgumentException.ThrowIfNullOrWhiteSpace(texturePath, "texturePath");
			_textures[cueKey] = texturePath;
			if (style != null)
			{
				_textureStyles[cueKey] = style;
			}
			else
			{
				_textureStyles.Remove(cueKey);
			}
			_sequences.Remove(cueKey);
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Binds one texture to a non-looping timed cue. The cue completes after its effective
		///         <paramref name="durationSeconds" />, allowing state machines to advance.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将一张纹理绑定到非循环的定时视觉提示。提示会在有效的 <paramref name="durationSeconds" />
		///         结束后完成，使状态机能够推进。
		///     </para>
		/// </summary>
		public VisualCueSetBuilder Single(string cueKey, string texturePath, float durationSeconds)
		{
			return Single(cueKey, texturePath, durationSeconds, null);
		}

		/// <summary>
		///     <para xml:lang="en">Binds one texture to a non-looping timed cue with optional style overrides.</para>
		///     <para xml:lang="zh-CN">将一张纹理绑定到非循环的定时视觉提示，并可应用样式覆盖。</para>
		/// </summary>
		public VisualCueSetBuilder Single(string cueKey, string texturePath, float durationSeconds, VisualNodeStyle? style)
		{
			return Sequence(cueKey, VisualFrameSequenceBuilder.Create().Frame(texturePath, durationSeconds, style).Build());
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Binds a completed frame sequence to a cue, replacing any static texture registered for the same key.
		///     </para>
		///     <para xml:lang="zh-CN">将已构建的帧序列绑定到视觉提示，并替换同一键下已有的静态纹理。</para>
		/// </summary>
		public VisualCueSetBuilder Sequence(string cueKey, VisualFrameSequence sequence)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(cueKey, "cueKey");
			ArgumentNullException.ThrowIfNull(sequence, "sequence");
			_sequences[cueKey] = sequence;
			_textures.Remove(cueKey);
			_textureStyles.Remove(cueKey);
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Binds a frame sequence configured through <paramref name="configure" />.</para>
		///     <para xml:lang="zh-CN">绑定通过 <paramref name="configure" /> 配置的帧序列。</para>
		/// </summary>
		public VisualCueSetBuilder Sequence(string cueKey, Action<VisualFrameSequenceBuilder> configure)
		{
			ArgumentNullException.ThrowIfNull(configure, "configure");
			VisualFrameSequenceBuilder visualFrameSequenceBuilder = VisualFrameSequenceBuilder.Create();
			configure(visualFrameSequenceBuilder);
			return Sequence(cueKey, visualFrameSequenceBuilder.Build());
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds an immutable cue set, using <see langword="null" /> for empty dictionaries.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         构建不可变的视觉提示集；空字典对应的字段会设为 <see langword="null" />。
		///     </para>
		/// </summary>
		public VisualCueSet Build()
		{
			return new VisualCueSet((_textures.Count > 0) ? new ReadOnlyDictionary<string, string>(new Dictionary<string, string>(_textures, StringComparer.OrdinalIgnoreCase)) : null, (_sequences.Count > 0) ? new ReadOnlyDictionary<string, VisualFrameSequence>(new Dictionary<string, VisualFrameSequence>(_sequences, StringComparer.OrdinalIgnoreCase)) : null, (_textureStyles.Count > 0) ? new ReadOnlyDictionary<string, VisualNodeStyle>(new Dictionary<string, VisualNodeStyle>(_textureStyles, StringComparer.OrdinalIgnoreCase)) : null);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Defines one texture frame and its hold duration in a <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualFrameSequence" />.</para>
	///     <para xml:lang="zh-CN">定义 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualFrameSequence" /> 中的一帧纹理及其保持时长。</para>
	/// </summary>
	/// <param name="TexturePath">
	///     <para xml:lang="en">The Godot resource path of a <see cref="T:Godot.Texture2D" />.</para>
	///     <para xml:lang="zh-CN"><see cref="T:Godot.Texture2D" /> 的 Godot 资源路径。</para>
	/// </param>
	/// <param name="DurationSeconds">
	///     <para xml:lang="en">The display time before advancing; non-positive values are clamped at runtime.</para>
	///     <para xml:lang="zh-CN">切换到下一帧之前的显示时长；运行时会限制非正值的最小值。</para>
	/// </param>
	public readonly record struct VisualFrame(string TexturePath, float DurationSeconds);
	/// <summary>
	///     <para xml:lang="en">
	///         Defines an immutable ordered frame sequence for one logical cue, such as combat, a merchant room,
	///         or an Ancient event stage.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为一个逻辑视觉提示定义不可变的有序帧序列，例如战斗、商人房间或先古事件舞台。
	///     </para>
	/// </summary>
	/// <param name="Frames">
	///     <para xml:lang="en">The ordered frames. Playback requires at least one entry.</para>
	///     <para xml:lang="zh-CN">有序帧列表；播放时至少需要一个条目。</para>
	/// </param>
	/// <param name="Loop">
	///     <para xml:lang="en">Whether playback restarts after the last frame.</para>
	///     <para xml:lang="zh-CN">播放到最后一帧后是否重新开始。</para>
	/// </param>
	public sealed record VisualFrameSequence(IReadOnlyList<VisualFrame> Frames, bool Loop = false)
	{
		/// <summary>
		///     <para xml:lang="en">Gets the optional style applied to frames that do not define their own style.</para>
		///     <para xml:lang="zh-CN">获取应用于未单独定义样式之帧的可选默认样式。</para>
		/// </summary>
		public VisualNodeStyle? DefaultStyle { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional style entries aligned by index with <see cref="P:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualFrameSequence.Frames" />.</para>
		///     <para xml:lang="zh-CN">获取按索引与 <see cref="P:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualFrameSequence.Frames" /> 对齐的可选样式条目。</para>
		/// </summary>
		public IReadOnlyList<VisualNodeStyle?>? FrameStyles { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Initializes a frame sequence with optional style metadata. The two-parameter constructor remains available
		///         for binary compatibility with older mods.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用可选的样式元数据初始化帧序列。为保持与旧版模组的二进制兼容性，双参数构造函数仍然可用。
		///     </para>
		/// </summary>
		public VisualFrameSequence(IReadOnlyList<VisualFrame> Frames, bool Loop, VisualNodeStyle? DefaultStyle, IReadOnlyList<VisualNodeStyle?>? FrameStyles)
			: this(Frames, Loop)
		{
			this.DefaultStyle = DefaultStyle;
			this.FrameStyles = FrameStyles;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides a fluent builder for <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualFrameSequence" /> instances with per-frame durations.
	///     </para>
	///     <para xml:lang="zh-CN">提供可配置逐帧时长的 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualFrameSequence" /> 流式构建器。</para>
	/// </summary>
	public sealed class VisualFrameSequenceBuilder
	{
		private readonly List<VisualNodeStyle?> _frameStyles = new List<VisualNodeStyle>();

		private readonly List<VisualFrame> _frames = new List<VisualFrame>();

		private VisualNodeStyle? _defaultStyle;

		private bool _loop;

		private VisualFrameSequenceBuilder()
		{
		}

		/// <summary>
		///     <para xml:lang="en">Starts a new frame-sequence definition.</para>
		///     <para xml:lang="zh-CN">开始定义新的帧序列。</para>
		/// </summary>
		public static VisualFrameSequenceBuilder Create()
		{
			return new VisualFrameSequenceBuilder();
		}

		/// <summary>
		///     <para xml:lang="en">Appends a frame.</para>
		///     <para xml:lang="zh-CN">追加一帧。</para>
		/// </summary>
		public VisualFrameSequenceBuilder Frame(string texturePath, float durationSeconds)
		{
			return Frame(texturePath, durationSeconds, null);
		}

		/// <summary>
		///     <para xml:lang="en">Appends a frame with optional style overrides applied while it is visible.</para>
		///     <para xml:lang="zh-CN">追加一帧，并可在该帧可见期间应用样式覆盖。</para>
		/// </summary>
		public VisualFrameSequenceBuilder Frame(string texturePath, float durationSeconds, VisualNodeStyle? style)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(texturePath, "texturePath");
			if (!float.IsFinite(durationSeconds))
			{
				throw new ArgumentOutOfRangeException("durationSeconds", durationSeconds, "Frame duration must be a finite value.");
			}
			_frames.Add(new VisualFrame(texturePath, durationSeconds));
			_frameStyles.Add(style);
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Sets the default style applied to frames that do not define their own style.</para>
		///     <para xml:lang="zh-CN">设置应用于未单独定义样式之帧的默认样式。</para>
		/// </summary>
		public VisualFrameSequenceBuilder DefaultStyle(VisualNodeStyle style)
		{
			ArgumentNullException.ThrowIfNull(style, "style");
			_defaultStyle = style;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets whether the sequence loops after its last frame. The default is <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         设置序列在最后一帧之后是否循环；默认值为 <see langword="false" />。
		///     </para>
		/// </summary>
		public VisualFrameSequenceBuilder Loop(bool loop = true)
		{
			_loop = loop;
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Builds an immutable sequence. At least one frame is required.</para>
		///     <para xml:lang="zh-CN">构建不可变序列；序列必须至少包含一帧。</para>
		/// </summary>
		public VisualFrameSequence Build()
		{
			if (_frames.Count != 0)
			{
				return new VisualFrameSequence(new global::<>z__ReadOnlyArray<VisualFrame>(_frames.ToArray()), _loop, _defaultStyle, _frameStyles.Any((VisualNodeStyle s) => s != null) ? _frameStyles.ToArray() : null);
			}
			throw new InvalidOperationException("Frame sequence must contain at least one frame.");
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines optional style overrides for procedural visual nodes created by RitsuLib factories and cue playback.
	///         Unset properties leave the target node unchanged.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义 RitsuLib 工厂和视觉提示播放所创建程序化视觉节点的可选样式覆盖。
	///         未设置的属性不会改变目标节点。
	///     </para>
	/// </summary>
	public sealed record VisualNodeStyle
	{
		/// <summary>
		///     <para xml:lang="en">Gets an empty style that does not change the target node when applied.</para>
		///     <para xml:lang="zh-CN">获取应用后不会改变目标节点的空样式。</para>
		/// </summary>
		public static VisualNodeStyle Empty { get; } = new VisualNodeStyle();

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the absolute local position. When unset, the current position is preserved unless the caller supplies
		///         a base position.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取绝对局部位置。未设置时会保留节点的当前位置，除非调用方提供了基准位置。
		///     </para>
		/// </summary>
		public Vector2? Position { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the local position delta applied after <see cref="P:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualNodeStyle.Position" /> or a caller-supplied base position.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取在 <see cref="P:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualNodeStyle.Position" /> 或调用方提供的基准位置之后叠加的局部位置偏移。
		///     </para>
		/// </summary>
		public Vector2? Offset { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the local scale for <see cref="T:Godot.Node2D" /> and <see cref="T:Godot.Control" /> targets.</para>
		///     <para xml:lang="zh-CN">获取 <see cref="T:Godot.Node2D" /> 和 <see cref="T:Godot.Control" /> 目标的局部缩放。</para>
		/// </summary>
		public Vector2? Scale { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the local rotation in radians, matching Godot's native rotation unit.</para>
		///     <para xml:lang="zh-CN">获取以弧度表示的局部旋转，与 Godot 的原生旋转单位一致。</para>
		/// </summary>
		public float? RotationRadians { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the local skew for <see cref="T:Godot.Node2D" /> targets.</para>
		///     <para xml:lang="zh-CN">获取 <see cref="T:Godot.Node2D" /> 目标的局部倾斜。</para>
		/// </summary>
		public float? Skew { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the pivot offset for <see cref="T:Godot.Control" /> targets.</para>
		///     <para xml:lang="zh-CN">获取 <see cref="T:Godot.Control" /> 目标的枢轴偏移。</para>
		/// </summary>
		public Vector2? PivotOffset { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the <see cref="P:Godot.CanvasItem.Modulate" /> color.</para>
		///     <para xml:lang="zh-CN">获取 <see cref="P:Godot.CanvasItem.Modulate" /> 颜色。</para>
		/// </summary>
		public Color? Modulate { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the <see cref="P:Godot.CanvasItem.SelfModulate" /> color.</para>
		///     <para xml:lang="zh-CN">获取 <see cref="P:Godot.CanvasItem.SelfModulate" /> 颜色。</para>
		/// </summary>
		public Color? SelfModulate { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the <see cref="P:Godot.CanvasItem.ZIndex" /> value.</para>
		///     <para xml:lang="zh-CN">获取 <see cref="P:Godot.CanvasItem.ZIndex" /> 值。</para>
		/// </summary>
		public int? ZIndex { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the <see cref="P:Godot.CanvasItem.Visible" /> value.</para>
		///     <para xml:lang="zh-CN">获取 <see cref="P:Godot.CanvasItem.Visible" /> 值。</para>
		/// </summary>
		public bool? Visible { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the centering flag for <see cref="T:Godot.Sprite2D" /> targets.</para>
		///     <para xml:lang="zh-CN">获取 <see cref="T:Godot.Sprite2D" /> 目标的居中标记。</para>
		/// </summary>
		public bool? Centered { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the horizontal flip flag for <see cref="T:Godot.Sprite2D" /> targets.</para>
		///     <para xml:lang="zh-CN">获取 <see cref="T:Godot.Sprite2D" /> 目标的水平翻转标记。</para>
		/// </summary>
		public bool? FlipH { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the vertical flip flag for <see cref="T:Godot.Sprite2D" /> targets.</para>
		///     <para xml:lang="zh-CN">获取 <see cref="T:Godot.Sprite2D" /> 目标的垂直翻转标记。</para>
		/// </summary>
		public bool? FlipV { get; init; }

		/// <summary>
		///     <para xml:lang="en">Creates a style using degrees as the mod-facing rotation unit.</para>
		///     <para xml:lang="zh-CN">使用更便于模组作者配置的角度制旋转值创建样式。</para>
		/// </summary>
		public static VisualNodeStyle Create(Vector2? position = null, Vector2? offset = null, Vector2? scale = null, float? rotationDegrees = null, float? skew = null, Vector2? pivotOffset = null, Color? modulate = null, Color? selfModulate = null, int? zIndex = null, bool? visible = null, bool? centered = null, bool? flipH = null, bool? flipV = null)
		{
			return new VisualNodeStyle
			{
				Position = position,
				Offset = offset,
				Scale = scale,
				RotationRadians = (rotationDegrees.HasValue ? new float?(Mathf.DegToRad(rotationDegrees.Value)) : ((float?)null)),
				Skew = skew,
				PivotOffset = pivotOffset,
				Modulate = modulate,
				SelfModulate = selfModulate,
				ZIndex = zIndex,
				Visible = visible,
				Centered = centered,
				FlipH = flipH,
				FlipV = flipV
			};
		}

		/// <summary>
		///     <para xml:lang="en">Creates a style using radians for rotation, matching Godot's native API.</para>
