	/// <summary>
	///     <para xml:lang="en">Provides Godot node helpers for packed-scene conversion and procedural roots.</para>
	///     <para xml:lang="zh-CN">提供用于场景打包转换和程序化根节点的 Godot 节点方法。</para>
	/// </summary>
	public static class RitsuGodotNodeExtensions
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Adds <paramref name="child" />, assigns <paramref name="owner" /> as its owner, and enables
		///         <see cref="P:Godot.Node.UniqueNameInOwner" /> so it can be resolved through <c>GetNode("%Name")</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         添加 <paramref name="child" />，将 <paramref name="owner" /> 指定为其所有者，并启用
		///         <see cref="P:Godot.Node.UniqueNameInOwner" />，使其可通过 <c>GetNode("%Name")</c> 解析。
		///     </para>
		/// </summary>
		public static void AddUniqueChild(this Node owner, Node child, string? name = null)
		{
			ArgumentNullException.ThrowIfNull(owner, "owner");
			ArgumentNullException.ThrowIfNull(child, "child");
			if (name != null)
			{
				child.Name = StringName.op_Implicit(name);
			}
			child.UniqueNameInOwner = true;
			owner.AddChild(child, false, (InternalMode)0);
			child.Owner = owner;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides explicitly invoked Godot node construction APIs. These methods do not patch
	///         <c>PackedScene.Instantiate</c>, so BaseLib scene conversion and base-game loading retain control of their
	///         own hooks.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供需要显式调用的 Godot 节点构造 API。这些方法不会修补 <c>PackedScene.Instantiate</c>，
	///         因此 BaseLib 的场景转换和游戏的资源加载仍由各自的钩子控制。
	///     </para>
	/// </summary>
	public static class RitsuGodotNodeFactories
	{
		private sealed class PublicRitsuGodotNodeFactoryAdapter<TNode>(IRitsuGodotNodeFactory<TNode> factory) : RitsuGodotNodeFactory where TNode : Node
		{
			public override Node CreateFromNode(Node source)
			{
				return CreateFromNode(source, null);
			}

			public override Node CreateFromNode(Node source, VisualNodeStyle? style)
			{
				return (Node)(object)RequireCreatedNode(factory.CreateFromNode(source, style), "CreateFromNode");
			}

			public override Node CreateBareFromResource(object resource)
			{
				return CreateFromResource(resource, null);
			}

			public override Node CreateFromResource(object resource, VisualNodeStyle? style)
			{
				return (Node)(object)RequireCreatedNode(factory.CreateFromResource(resource, style), "CreateFromResource");
			}

			public override void CompleteBareRoot(Node bare)
			{
			}
		}

		private sealed class DelegateRitsuGodotNodeFactory<TNode>(Func<Node, VisualNodeStyle?, TNode> createFromNode, Func<object, VisualNodeStyle?, TNode>? createFromResource) : RitsuGodotNodeFactory where TNode : Node
		{
			public override Node CreateFromNode(Node source)
			{
				return CreateFromNode(source, null);
			}

			public override Node CreateFromNode(Node source, VisualNodeStyle? style)
			{
				return (Node)(object)RequireCreatedNode(createFromNode(source, style), "createFromNode");
			}

			public override Node CreateBareFromResource(object resource)
			{
				return CreateFromResource(resource, null);
			}

			public override Node CreateFromResource(object resource, VisualNodeStyle? style)
			{
				if (createFromResource == null)
				{
					throw new NotSupportedException("No resource factory was registered for " + typeof(TNode).FullName + ".");
				}
				return (Node)(object)RequireCreatedNode(createFromResource(resource, style), "createFromResource");
			}

			public override void CompleteBareRoot(Node bare)
			{
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a typed factory used by explicit <see cref="M:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactories.CreateFromScene``1(Godot.PackedScene)" /> and
		///         <see cref="M:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactories.CreateFromResource``1(System.Object)" /> calls.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册供显式调用 <see cref="M:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactories.CreateFromScene``1(Godot.PackedScene)" /> 和
		///         <see cref="M:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactories.CreateFromResource``1(System.Object)" /> 时使用的强类型工厂。
		///     </para>
		/// </summary>
		public static void RegisterFactory<TNode>(IRitsuGodotNodeFactory<TNode> factory, bool replaceExisting = false) where TNode : Node, new()
		{
			ArgumentNullException.ThrowIfNull(factory, "factory");
			RitsuGodotNodeFactoryRegistry.RegisterFactory<TNode>(new PublicRitsuGodotNodeFactoryAdapter<TNode>(factory), replaceExisting);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers delegate-based conversion for <typeparamref name="TNode" />. If
		///         <paramref name="createFromResource" /> is omitted, <see cref="M:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactories.CreateFromResource``1(System.Object)" /> throws
		///         <see cref="T:System.NotSupportedException" /> for this node type.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <typeparamref name="TNode" /> 注册基于委托的转换。如果省略
		///         <paramref name="createFromResource" />，则对此节点类型调用
		///         <see cref="M:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactories.CreateFromResource``1(System.Object)" /> 时会抛出 <see cref="T:System.NotSupportedException" />。
		///     </para>
		/// </summary>
		public static void RegisterFactory<TNode>(Func<Node, VisualNodeStyle?, TNode> createFromNode, Func<object, VisualNodeStyle?, TNode>? createFromResource = null, bool replaceExisting = false) where TNode : Node, new()
		{
			ArgumentNullException.ThrowIfNull(createFromNode, "createFromNode");
			RitsuGodotNodeFactoryRegistry.RegisterFactory<TNode>(new DelegateRitsuGodotNodeFactory<TNode>(createFromNode, createFromResource), replaceExisting);
		}

