		private static TNode RequireCreatedNode<TNode>(TNode? node, string factoryMember) where TNode : Node
		{
			if (GodotObject.IsInstanceValid((GodotObject)(object)node))
			{
				return node;
			}
			throw new InvalidOperationException($"Registered Godot node factory member '{factoryMember}' returned a null or invalid node for {typeof(TNode).FullName}.");
		}
	}
	/// <summary>
	///     <para xml:lang="en">Defines the non-generic factory contract used by <see cref="T:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactoryRegistry" />.</para>
	///     <para xml:lang="zh-CN">定义 <see cref="T:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactoryRegistry" /> 使用的非泛型工厂契约。</para>
	/// </summary>
	internal abstract class RitsuGodotNodeFactory
	{
		public abstract Node CreateFromNode(Node source);

		public virtual Node CreateFromNode(Node source, VisualNodeStyle? style)
		{
			Node val = CreateFromNode(source);
			style.ApplyTo(val);
			return val;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds a root node without running <see cref="M:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactory.CompleteBareRoot(Godot.Node)" />, for example when creating
		///         visuals from a <see cref="T:Godot.Texture2D" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         构建根节点，但不运行 <see cref="M:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactory.CompleteBareRoot(Godot.Node)" />；例如，从 <see cref="T:Godot.Texture2D" />
		///         创建视觉节点时会使用此方法。
		///     </para>
		/// </summary>
		public abstract Node CreateBareFromResource(object resource);

		public virtual Node CreateFromResource(object resource, VisualNodeStyle? style)
		{
			Node val = CreateBareFromResource(resource);
			try
			{
				CompleteBareRoot(val, style);
				return val;
			}
			catch
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)val))
				{
					((GodotObject)val).Free();
				}
				throw;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Fills the required named slots and children of a bare root, equivalent to
		///         <c>ConvertScene(target, null)</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         填充裸根节点所需的具名槽位和子节点，等同于调用 <c>ConvertScene(target, null)</c>。
		///     </para>
		/// </summary>
		public abstract void CompleteBareRoot(Node bare);

		public virtual void CompleteBareRoot(Node bare, VisualNodeStyle? style)
		{
			CompleteBareRoot(bare);
			style.ApplyTo(bare);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Describes a named child expected beneath a converted Godot scene root, resolved by a unique
	///         <c>%Name</c> or a node path.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         描述转换后的 Godot 场景根节点下所需的具名子节点，可通过唯一名称 <c>%Name</c> 或节点路径解析。
	///     </para>
	/// </summary>
	internal interface IRitsuGodotNodeSlot
	{
		string Path { get; }

		bool UniqueName { get; }

		bool MakeNameUnique { get; }

		Type ExpectedNodeType { get; }

		bool IsValidName(Node node);

		bool IsValidType(Node node);

		bool IsValidUnique(Node node);
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Stores named-slot metadata for <see cref="T:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactory`1" />, corresponding to BaseLib's
	///         <c>NodeInfo&lt;T&gt;</c>.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         存储 <see cref="T:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactory`1" /> 的具名槽位元数据，对应 BaseLib 的
	///         <c>NodeInfo&lt;T&gt;</c>。
	///     </para>
	/// </summary>
	internal sealed record RitsuGodotNodeSlot<TExpected>(string Path, bool MakeNameUnique = true) : IRitsuGodotNodeSlot where TExpected : Node
	{
		public StringName StringName { get; }

		public bool UniqueName { get; }

		public Type ExpectedNodeType => typeof(TExpected);

		public bool IsValidType(Node node)
		{
			return node is TExpected;
		}

		public bool IsValidName(Node node)
		{
			return node.Name.Equals(StringName);
		}

		public bool IsValidUnique(Node node)
		{
			if (UniqueName && node is TExpected)
			{
				return node.Name.Equals(StringName);
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides a base class for typed procedural-node and scene-conversion factories.</para>
	///     <para xml:lang="zh-CN">提供强类型程序化节点及场景转换工厂的基类。</para>
	/// </summary>
	internal abstract class RitsuGodotNodeFactory<T> : RitsuGodotNodeFactory where T : Node, new()
	{
		protected readonly bool FlexibleStructure;

		protected readonly List<IRitsuGodotNodeSlot> NamedNodes;

		protected RitsuGodotNodeFactory(IEnumerable<IRitsuGodotNodeSlot> namedNodes)
		{
			NamedNodes = namedNodes.ToList();
			FlexibleStructure = NamedNodes.Count == 0 || NamedNodes.All((IRitsuGodotNodeSlot s) => s.UniqueName);
			RitsuGodotNodeFactoryRegistry.RegisterFactory<T>(this);
		}

		public override Node CreateFromNode(Node source)
		{
			T val = (T)(object)((source is T) ? source : null);
			if (val != null)
			{
				CompleteBareRoot((Node)(object)val);
				return (Node)(object)val;
			}
			T val2 = new T();
			try
			{
				ConvertScene(val2, source);
				return (Node)(object)val2;
			}
			catch
			{
				FreeFailedConversion(val2, source);
				throw;
			}
		}

		public override Node CreateFromNode(Node source, VisualNodeStyle? style)
		{
			T val = (T)(object)((source is T) ? source : null);
			if (val != null)
			{
				CompleteBareRoot((Node)(object)val);
				ApplyStyle(val, fromResource: false, style);
				return (Node)(object)val;
			}
			T val2 = new T();
			try
			{
				ConvertScene(val2, source);
				ApplyStyle(val2, fromResource: false, style);
				return (Node)(object)val2;
			}
			catch
			{
				FreeFailedConversion(val2, source);
				throw;
			}
		}

		public override Node CreateBareFromResource(object resource)
		{
			return (Node)(object)CreateBareFromResourceImpl(resource);
		}

		public override void CompleteBareRoot(Node bare)
		{
			ConvertScene((T)(object)bare, null);
		}

		public override void CompleteBareRoot(Node bare, VisualNodeStyle? style)
		{
			CompleteBareRoot(bare);
			ApplyStyle((T)(object)bare, fromResource: true, style);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a bare root from <paramref name="resource" />. Implementations should throw a descriptive exception
		///         for unsupported resource types.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从 <paramref name="resource" /> 创建裸根节点。实现应在资源类型不受支持时抛出说明明确的异常。
		///     </para>
		/// </summary>
		protected abstract T CreateBareFromResourceImpl(object resource);

		protected virtual Node? ResolveDefaultStyleTarget(T root, bool fromResource)
		{
