				else
				{
					GenerateNode(target, namedNode);
				}
			}
			Dictionary<IRitsuGodotNodeSlot, Node> dictionary = new Dictionary<IRitsuGodotNodeSlot, Node>();
			foreach (Node item in NodeUtil.GetChildrenRecursive<Node>((Node)(object)target))
			{
				for (int i = 0; i < list.Count; i++)
				{
					IRitsuGodotNodeSlot ritsuGodotNodeSlot = list[i];
					if (ritsuGodotNodeSlot.IsValidName(item))
					{
						dictionary[ritsuGodotNodeSlot] = item;
					}
					if (ritsuGodotNodeSlot.IsValidUnique(item))
					{
						item.UniqueNameInOwner = true;
						item.Owner = (Node)(object)target;
						list.RemoveAt(i);
						break;
					}
				}
			}
			foreach (IRitsuGodotNodeSlot item2 in list)
			{
				if (dictionary.TryGetValue(item2, out var value))
				{
					if (!item2.IsValidType(value))
					{
						value.ReplaceBy(val, false);
						value = ConvertNodeTypeAndFreeUnusedSource(value, item2.ExpectedNodeType);
						val.ReplaceBy(value, false);
					}
					value.UniqueNameInOwner = true;
					value.Owner = (Node)(object)target;
				}
				else
				{
					GenerateNode(target, item2);
				}
			}
			val.QueueFree();
		}

		private Node ConvertNodeTypeAndFreeUnusedSource(Node source, Type targetType)
		{
			Type type = ((object)source).GetType();
			StringName name = source.Name;
			Node obj = ConvertNodeType(source, targetType);
			if (!GodotObject.IsInstanceValid((GodotObject)(object)obj))
			{
				throw new InvalidOperationException($"Factory for {typeof(T).Name} returned a null or invalid {targetType.Name} replacement for {type.Name} '{name}'.");
			}
			if (obj != source && GodotObject.IsInstanceValid((GodotObject)(object)source) && source.GetParent() == null)
			{
				((GodotObject)source).Free();
			}
			return obj;
		}

		protected virtual Node ConvertNodeType(Node node, Type targetType)
		{
			throw new InvalidOperationException($"Factory for {typeof(T).Name} cannot convert {((object)node).GetType().Name} '{node.Name}' to {targetType.Name}.");
		}

		protected abstract void GenerateNode(T target, IRitsuGodotNodeSlot required);

		private static void FreeFailedConversion(T target, Node source)
		{
			if (GodotObject.IsInstanceValid((GodotObject)(object)target))
			{
				((GodotObject)(object)target).Free();
			}
			if (GodotObject.IsInstanceValid((GodotObject)(object)source))
			{
