		}

		/// <summary>
		///     <para xml:lang="en">
		///         Clears owners before reparenting because packed-scene children can retain the old root as
		///         <see cref="P:Godot.Node.Owner" /> after <c>RemoveChild</c>. Leaving those owners in place can produce Godot
		///         “inconsistent owner” warnings and break unique-name resolution beneath the new root.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在重新设置父节点之前清除所有者，因为打包场景中的子节点在调用 <c>RemoveChild</c> 后仍可能以旧根节点
		///         作为 <see cref="P:Godot.Node.Owner" />。保留这些所有者会产生 Godot“所有者不一致”警告，并可能破坏新根节点下
		///         的唯一名称解析。
		///     </para>
		/// </summary>
		private static void ClearSubtreeOwnersForReparent(Node node)
		{
			foreach (Node child in node.GetChildren(false))
			{
				ClearSubtreeOwnersForReparent(child);
			}
			node.Owner = null;
		}

		protected static void SetChildrenOwner(Node target, Node child)
		{
			foreach (Node child2 in child.GetChildren(false))
			{
				child2.Owner = target;
				SetChildrenOwner(target, child2);
			}
		}

