	/// <summary>
	///     <para xml:lang="en">
	///         Registers the built-in <see cref="T:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactory`1" /> instances once per process for explicit
	///         <see cref="T:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactories" /> calls.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         每个进程注册一次内置 <see cref="T:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactory`1" /> 实例，供显式调用
	///         <see cref="T:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactories" /> 时使用。
	///     </para>
	/// </summary>
	internal static class RitsuGodotNodeFactoryBootstrap
	{
		private static readonly Lock SyncRoot = new Lock();

		private static bool _initialized;

		/// <summary>
		///     <para xml:lang="en">
		///         Ensures the factories are registered before runtime asset hooks run. Repeated calls have no effect.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         确保在运行时资源钩子执行前注册所有工厂；重复调用不会产生额外效果。
		///     </para>
		/// </summary>
		internal static void EnsureRegistered()
		{
			using (SyncRoot.EnterScope())
			{
				if (!_initialized)
				{
					new RitsuNCreatureVisualsNodeFactory();
					new RitsuNMerchantCharacterNodeFactory();
					new RitsuNRestSiteCharacterNodeFactory();
					new RitsuNode2DSceneRootFactory();
					new RitsuTextureRectControlNodeFactory();
					new RitsuNEnergyCounterNodeFactory();
					new RitsuNCardTrailVfxNodeFactory();
					_initialized = true;
					RitsuLibFramework.Logger.Info("[Godot] RitsuGodot node factories initialized.", 1);
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides internal factory lookup for <see cref="T:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactories" />. Conversion runs only through
	///         explicit factory calls; no global <c>PackedScene.Instantiate</c> postfix is installed, so BaseLib and
	///         base-game scene loading are unaffected.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为 <see cref="T:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactories" /> 提供内部工厂查找。转换仅在显式调用工厂 API 时运行；
	///         此注册表不会安装全局 <c>PackedScene.Instantiate</c> 后缀，因此不会影响 BaseLib 和游戏的场景加载。
	///     </para>
	/// </summary>
	internal static class RitsuGodotNodeFactoryRegistry
	{
		private static readonly ConcurrentDictionary<Type, RitsuGodotNodeFactory> Factories = new ConcurrentDictionary<Type, RitsuGodotNodeFactory>();

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a factory instance for <typeparamref name="TNode" />, normally from the factory constructor.
		///         Existing registrations are replaced.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <typeparamref name="TNode" /> 注册工厂实例，通常由工厂构造函数调用。已有注册会被替换。
		///     </para>
		/// </summary>
		public static void RegisterFactory<TNode>(RitsuGodotNodeFactory factory) where TNode : Node
		{
			RegisterFactory<TNode>(factory, replaceExisting: true);
		}

		internal static void RegisterFactory<TNode>(RitsuGodotNodeFactory factory, bool replaceExisting) where TNode : Node
		{
			ArgumentNullException.ThrowIfNull(factory, "factory");
			if (replaceExisting)
			{
				Factories[typeof(TNode)] = factory;
			}
			else if (!Factories.TryAdd(typeof(TNode), factory))
			{
				throw new InvalidOperationException("A node factory is already registered for " + typeof(TNode).FullName + ". Pass replaceExisting: true to replace it.");
			}
		}

		internal static TNode CreateFromScene<TNode>(PackedScene scene) where TNode : Node, new()
		{
			return CreateFromScene<TNode>(scene, null, null);
		}

		internal static TNode CreateFromScene<TNode>(PackedScene scene, GenEditState? editState) where TNode : Node, new()
		{
			return CreateFromScene<TNode>(scene, editState, null);
		}

		internal static TNode CreateFromScene<TNode>(PackedScene scene, VisualNodeStyle? style) where TNode : Node, new()
		{
			return CreateFromScene<TNode>(scene, null, style);
		}

		internal static TNode CreateFromScene<TNode>(PackedScene scene, GenEditState? editState, VisualNodeStyle? style) where TNode : Node, new()
		{
			//IL_0093: Unknown result type (might be due to invalid IL or missing references)
			//IL_0098: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a6: Unknown result type (might be due to invalid IL or missing references)
			if (!GodotObject.IsInstanceValid((GodotObject)(object)scene))
			{
				throw new ArgumentException("PackedScene is null or the native instance is invalid (freed).", "scene");
			}
			RequireMainThread("CreateFromScene");
			RitsuLibFramework.Logger.Debug("[Godot] Creating " + typeof(TNode).Name + " from scene " + ((Resource)scene).ResourcePath, 1);
			if (!Factories.TryGetValue(typeof(TNode), out RitsuGodotNodeFactory value))
			{
				throw new InvalidOperationException("No node factory registered for " + typeof(TNode).Name);
			}
			Node obj;
			if (editState.HasValue)
			{
				GenEditState valueOrDefault = editState.GetValueOrDefault();
				obj = scene.Instantiate(valueOrDefault);
			}
			else
			{
				obj = scene.Instantiate((GenEditState)0);
			}
			Node val = obj;
			if (val == null)
			{
				throw new InvalidOperationException("PackedScene.Instantiate returned null for '" + ((Resource)scene).ResourcePath + "'.");
			}
			try
			{
				Node val2 = value.CreateFromNode(val, style);
				if (!GodotObject.IsInstanceValid((GodotObject)(object)val2))
				{
					throw new InvalidOperationException("Factory for " + typeof(TNode).FullName + " returned a null or invalid Godot node.");
				}
				FreeUnusedSceneRoot(val, val2);
				return (TNode)(object)val2;
			}
			catch
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)val))
				{
					((GodotObject)val).Free();
				}
				throw;
			}
		}

		internal static TNode CreateFromScenePath<TNode>(string scenePath) where TNode : Node, new()
		{
			return CreateFromScenePath<TNode>(scenePath, null, null);
		}

		internal static TNode CreateFromScenePath<TNode>(string scenePath, GenEditState? editState) where TNode : Node, new()
		{
			return CreateFromScenePath<TNode>(scenePath, editState, null);
		}

		internal static TNode CreateFromScenePath<TNode>(string scenePath, VisualNodeStyle? style) where TNode : Node, new()
		{
			return CreateFromScenePath<TNode>(scenePath, null, style);
		}

		internal static TNode CreateFromScenePath<TNode>(string scenePath, GenEditState? editState, VisualNodeStyle? style) where TNode : Node, new()
		{
			return CreateFromScene<TNode>(PreloadManager.Cache.GetScene(scenePath), editState, style);
		}

		internal static TNode CreateFromResource<TNode>(object resource) where TNode : Node, new()
		{
			return CreateFromResource<TNode>(resource, null);
		}

		internal static TNode CreateFromResource<TNode>(object resource, VisualNodeStyle? style) where TNode : Node, new()
		{
			ArgumentNullException.ThrowIfNull(resource, "resource");
			GodotObject val = (GodotObject)((resource is GodotObject) ? resource : null);
			if (val != null && !GodotObject.IsInstanceValid(val))
