			if (!Factories.TryGetValue(typeof(TNode), out RitsuGodotNodeFactory value))
			{
				throw new InvalidOperationException("No node factory registered for " + typeof(TNode).Name);
			}
			if (resource is string text && ResourceLoader.Exists(text, ""))
			{
				resource = ResourceLoader.Load(text, "", (CacheMode)1) ?? throw new InvalidOperationException("ResourceLoader.Load returned null for path: " + text);
			}
			RitsuLibFramework.Logger.Debug("[Godot] Creating " + typeof(TNode).Name + " from " + resource.GetType().Name, 1);
			Node obj = value.CreateFromResource(resource, style);
			if (!GodotObject.IsInstanceValid((GodotObject)(object)obj))
			{
				throw new InvalidOperationException("Factory for " + typeof(TNode).FullName + " returned a null or invalid Godot node.");
			}
			return (TNode)(object)obj;
		}

		private static void FreeUnusedSceneRoot(Node root, Node created)
		{
			if (GodotObject.IsInstanceValid((GodotObject)(object)root) && ((GodotObject)root).GetInstanceId() != ((GodotObject)created).GetInstanceId() && !root.IsAncestorOf(created) && root.GetParent() == null)
