		public static CardPoolAssetProfile Empty { get; } = new CardPoolAssetProfile();
	}
	/// <summary>
	///     <para xml:lang="en">Provides merge operations for <see cref="T:STS2RitsuLib.Scaffolding.Content.CardPoolAssetProfile" />.</para>
	///     <para xml:lang="zh-CN">提供 <see cref="T:STS2RitsuLib.Scaffolding.Content.CardPoolAssetProfile" /> 的合并操作。</para>
	/// </summary>
	public static class CardPoolAssetProfiles
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Merges profiles field by field, preferring non-null values from <paramref name="profile" /> and
		///         falling back to <paramref name="fallback" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         逐字段合并配置，优先使用 <paramref name="profile" /> 中的非空值，否则回退到
		///         <paramref name="fallback" />。
		///     </para>
		/// </summary>
		public static CardPoolAssetProfile Merge(CardPoolAssetProfile? fallback, CardPoolAssetProfile? profile)
		{
			if ((object)fallback == null)
			{
				fallback = CardPoolAssetProfile.Empty;
			}
			if ((object)profile == null)
			{
				profile = CardPoolAssetProfile.Empty;
			}
			return new CardPoolAssetProfile(MergeDeckViewStyle(fallback.DeckViewStyle, profile.DeckViewStyle));
		}

		private static CardPoolDeckViewStyle? MergeDeckViewStyle(CardPoolDeckViewStyle? fallback, CardPoolDeckViewStyle? profile)
		{
			if (fallback == null)
			{
				return profile;
			}
			if (profile == null)
			{
				return fallback;
			}
			return new CardPoolDeckViewStyle
			{
				ToolbarBackgroundTexturePath = (profile.ToolbarBackgroundTexturePath ?? fallback.ToolbarBackgroundTexturePath),
				ToolbarBackgroundMaterial = (profile.ToolbarBackgroundMaterial ?? fallback.ToolbarBackgroundMaterial),
				ToolbarBackgroundMaterialProvider = (profile.ToolbarBackgroundMaterialProvider ?? fallback.ToolbarBackgroundMaterialProvider),
				SortButtonHueMaterial = (profile.SortButtonHueMaterial ?? fallback.SortButtonHueMaterial),
				SortButtonHueMaterialProvider = (profile.SortButtonHueMaterialProvider ?? fallback.SortButtonHueMaterialProvider),
				DisableSortButtonHue = (profile.DisableSortButtonHue ?? fallback.DisableSortButtonHue),
				SortButtonBackgroundTexturePath = (profile.SortButtonBackgroundTexturePath ?? fallback.SortButtonBackgroundTexturePath),
				SortButtonBackgroundMaterial = (profile.SortButtonBackgroundMaterial ?? fallback.SortButtonBackgroundMaterial),
				SortButtonBackgroundMaterialProvider = (profile.SortButtonBackgroundMaterialProvider ?? fallback.SortButtonBackgroundMaterialProvider),
				UpgradePreviewLabelColor = (profile.UpgradePreviewLabelColor ?? fallback.UpgradePreviewLabelColor),
				UpgradePreviewLabelOutlineColor = (profile.UpgradePreviewLabelOutlineColor ?? fallback.UpgradePreviewLabelOutlineColor)
			};
		}
	}
