	/// <summary>
	///     <para xml:lang="en">
	///         Provides factories that build base-game <c>res://</c> asset paths from base-game folder and atlas-entry
	///         names. These methods do not infer mod asset paths from model IDs; mod-owned assets should be supplied
	///         explicitly through profiles.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供根据游戏本体的文件夹名称和图集条目名称创建 <c>res://</c> 资源路径的工厂。这些方法不会根据
	///         模型 ID 推断模组资源路径；模组自有资源应通过配置显式提供。
	///     </para>
	/// </summary>
	public static class ContentAssetProfiles
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Builds base-game-style portrait, beta-art, and overlay paths for
		///         <paramref name="cardEntry" /> in <paramref name="poolEntry" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="poolEntry" /> 中的 <paramref name="cardEntry" /> 创建游戏本体风格的肖像、
		///         测试版卡图和覆盖层路径。
		///     </para>
		/// </summary>
		public static CardAssetProfile Card(string poolEntry, string cardEntry)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(poolEntry, "poolEntry");
			ArgumentException.ThrowIfNullOrWhiteSpace(cardEntry, "cardEntry");
			string value = Normalize(poolEntry);
			string text = Normalize(cardEntry);
			return new CardAssetProfile(ImageHelper.GetImagePath($"packed/card_portraits/{value}/{text}.png"), ImageHelper.GetImagePath($"packed/card_portraits/{value}/beta/{text}.png"), null, null, null, null, SceneHelper.GetScenePath("cards/overlays/" + text));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds base-game-style portrait, overlay, border, title-banner, and text-background paths for an
		///         Ancient card.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为先古卡牌创建游戏本体风格的肖像、覆盖层、边框、标题横幅和文本背景路径。
		///     </para>
		/// </summary>
		public static CardAssetProfile AncientCard(string poolEntry, string cardEntry, CardType cardType)
		{
			//IL_0024: Unknown result type (might be due to invalid IL or missing references)
			ArgumentException.ThrowIfNullOrWhiteSpace(poolEntry, "poolEntry");
			ArgumentException.ThrowIfNullOrWhiteSpace(cardEntry, "cardEntry");
			string value = Normalize(poolEntry);
			string text = Normalize(cardEntry);
			string text2 = NormalizeAncientCardType(cardType);
			return new CardAssetProfile(ImageHelper.GetImagePath($"packed/card_portraits/{value}/{text}.png"), ImageHelper.GetImagePath($"packed/card_portraits/{value}/beta/{text}.png"), null, null, null, null, SceneHelper.GetScenePath("cards/overlays/" + text), null, null, null, null, null, null, ImageHelper.GetImagePath("atlases/compressed_atlas.sprites/ancient_card_border.png.tres"), ImageHelper.GetImagePath("atlases/compressed_atlas.sprites/ancient_text_bg_" + text2 + ".png.tres"), null, null, null, null, null, null, null, null, ImageHelper.GetImagePath("atlases/ui_atlas.sprites/card/ancient_banner.tres"), null, null, CardVisualStyle.Ancient);
		}

		/// <summary>
		///     <para xml:lang="en">Builds base-game-style relic icon paths for <paramref name="relicEntry" />.</para>
		///     <para xml:lang="zh-CN">为 <paramref name="relicEntry" /> 创建游戏本体风格的遗物图标路径。</para>
		/// </summary>
		public static RelicAssetProfile Relic(string relicEntry)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(relicEntry, "relicEntry");
			string text = Normalize(relicEntry);
			return new RelicAssetProfile(ImageHelper.GetImagePath("atlases/relic_atlas.sprites/" + text + ".tres"), ImageHelper.GetImagePath("atlases/relic_outline_atlas.sprites/" + text + ".tres"), ImageHelper.GetImagePath("relics/" + text + ".png"));
		}

		/// <summary>
		///     <para xml:lang="en">Builds base-game-style power icon paths for <paramref name="powerEntry" />.</para>
		///     <para xml:lang="zh-CN">为 <paramref name="powerEntry" /> 创建游戏本体风格的能力图标路径。</para>
		/// </summary>
		public static PowerAssetProfile Power(string powerEntry)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(powerEntry, "powerEntry");
			string text = Normalize(powerEntry);
			return new PowerAssetProfile(ImageHelper.GetImagePath("atlases/power_atlas.sprites/" + text + ".tres"), ImageHelper.GetImagePath("powers/" + text + ".png"));
		}

		/// <summary>
