			return new PotionAssetProfile(ImageHelper.GetImagePath("atlases/potion_atlas.sprites/" + text + ".tres"), ImageHelper.GetImagePath("atlases/potion_outline_atlas.sprites/" + text + ".tres"));
		}

		/// <summary>
		///     <para xml:lang="en">
