		{
			ArgumentException.ThrowIfNullOrWhiteSpace(enchantmentEntry, "enchantmentEntry");
			string text = Normalize(enchantmentEntry);
			return new EnchantmentAssetProfile(ImageHelper.GetImagePath("enchantments/" + text + ".png"));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds a base-game-style run-modifier icon path for <paramref name="modifierEntry" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="modifierEntry" /> 创建游戏本体风格的一局游戏修正项图标路径。
		///     </para>
		/// </summary>
		public static ModifierAssetProfile Modifier(string modifierEntry)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modifierEntry, "modifierEntry");
