		/// <summary>
		///     <para xml:lang="en">
		///         Builds a complete <see cref="T:STS2RitsuLib.Scaffolding.Content.ActAssetProfile" /> for a base-game act folder, including the main
		///         background, layer directory, map textures, rest site, and chest Spine resource. The argument is a
		///         base-game folder name such as <c>hive</c>, not a mod model ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为游戏本体的章节文件夹创建完整 <see cref="T:STS2RitsuLib.Scaffolding.Content.ActAssetProfile" />，包括主背景、图层目录、地图纹理、
		///         休息处和宝箱 Spine 资源。参数应为 <c>hive</c> 等游戏本体文件夹名称，而不是模组模型 ID。
		///     </para>
		/// </summary>
		public static ActAssetProfile FromVanillaActId(string vanillaActId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(vanillaActId, "vanillaActId");
			string text = Normalize(vanillaActId);
			return new ActAssetProfile(SceneHelper.GetScenePath($"backgrounds/{text}/{text}_background"), SceneHelper.GetScenePath("rest_site/" + text + "_rest_site"), ImageHelper.GetImagePath($"packed/map/map_bgs/{text}/map_top_{text}.png"), ImageHelper.GetImagePath($"packed/map/map_bgs/{text}/map_middle_{text}.png"), ImageHelper.GetImagePath($"packed/map/map_bgs/{text}/map_bottom_{text}.png"), "res://animations/backgrounds/treasure_room/chest_room_act_" + text + "_skel_data.tres", ActVanillaBackgroundLayersDirectory(text));
		}

		/// <summary>
		///     <para xml:lang="en">Calls <see cref="M:STS2RitsuLib.Scaffolding.Content.ContentAssetProfiles.FromVanillaActId(System.String)" />.</para>
		///     <para xml:lang="zh-CN">调用 <see cref="M:STS2RitsuLib.Scaffolding.Content.ContentAssetProfiles.FromVanillaActId(System.String)" />。</para>
		/// </summary>
		public static ActAssetProfile Act(string actEntry)
		{
			return FromVanillaActId(actEntry);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds the base-game combat-background layer directory for
		///         <paramref name="vanillaActFolderName" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="vanillaActFolderName" /> 创建游戏本体的战斗背景图层目录。
		///     </para>
		/// </summary>
		/// <param name="vanillaActFolderName">
		///     <para xml:lang="en">The base-game act folder name, such as <c>hive</c>.</para>
		///     <para xml:lang="zh-CN">游戏本体的章节文件夹名称，例如 <c>hive</c>。</para>
		/// </param>
		public static string ActVanillaBackgroundLayersDirectory(string vanillaActFolderName)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(vanillaActFolderName, "vanillaActFolderName");
			return "res://scenes/backgrounds/" + Normalize(vanillaActFolderName) + "/layers";
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds base-game-style scene, background, boss-node, and game-history paths for
		///         <paramref name="encounterEntry" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="encounterEntry" /> 创建游戏本体风格的场景、背景、首领节点和游戏历史路径。
		///     </para>
		/// </summary>
		/// <param name="encounterEntry">
		///     <para xml:lang="en">The base-game encounter folder and animation slug.</para>
		///     <para xml:lang="zh-CN">游戏本体的遭遇文件夹和动画短名称。</para>
		/// </param>
		/// <param name="runHistoryIconPath">
		///     <para xml:lang="en">
		///         An optional main game-history icon path. When <see langword="null" />, the path is derived from
		///         <paramref name="encounterEntry" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的游戏历史主图标路径。值为 <see langword="null" /> 时，根据
		///         <paramref name="encounterEntry" /> 推导路径。
		///     </para>
		/// </param>
		/// <param name="runHistoryIconOutlinePath">
		///     <para xml:lang="en">
		///         An optional game-history outline path. When <see langword="null" />, the path is derived from
		///         <paramref name="encounterEntry" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的游戏历史轮廓路径。值为 <see langword="null" /> 时，根据
		///         <paramref name="encounterEntry" /> 推导路径。
		///     </para>
		/// </param>
		public static EncounterAssetProfile Encounter(string encounterEntry, string? runHistoryIconPath = null, string? runHistoryIconOutlinePath = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(encounterEntry, "encounterEntry");
			string text = Normalize(encounterEntry);
			string runHistoryIconPath2 = runHistoryIconPath ?? ImageHelper.GetImagePath("ui/run_history/" + text + ".png");
			string runHistoryIconOutlinePath2 = runHistoryIconOutlinePath ?? ImageHelper.GetImagePath("ui/run_history/" + text + "_outline.png");
			return new EncounterAssetProfile(SceneHelper.GetScenePath("encounters/" + text), SceneHelper.GetScenePath($"backgrounds/{text}/{text}_background"), "res://scenes/backgrounds/" + text + "/layers", $"res://animations/map/{text}/{text}_node_skel_data.tres", null, null, runHistoryIconPath2, runHistoryIconOutlinePath2);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds the base-game combat-background layer directory for an encounter.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建游戏本体的遭遇战斗背景图层目录。
		///     </para>
		/// </summary>
		public static string EncounterVanillaBackgroundLayersDirectory(string encounterEntry)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(encounterEntry, "encounterEntry");
			return "res://scenes/backgrounds/" + Normalize(encounterEntry) + "/layers";
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds a base-game-style creature-visuals path for <paramref name="monsterEntry" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="monsterEntry" /> 创建游戏本体风格的生物形象路径。
		///     </para>
		/// </summary>
		public static MonsterAssetProfile Monster(string monsterEntry)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(monsterEntry, "monsterEntry");
			return new MonsterAssetProfile(SceneHelper.GetScenePath("creature_visuals/" + Normalize(monsterEntry)));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds base-game-style portrait, background, and VFX paths for a default-layout or combat-style
		///         event.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为使用默认布局或战斗风格的事件创建游戏本体风格的肖像、背景和特效路径。
		///     </para>
		/// </summary>
		public static EventAssetProfile Event(string eventEntry)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(eventEntry, "eventEntry");
			string text = Normalize(eventEntry);
			return new EventAssetProfile(null, ImageHelper.GetImagePath("events/" + text + ".png"), SceneHelper.GetScenePath("events/background_scenes/" + text), SceneHelper.GetScenePath("vfx/events/" + text + "_vfx"));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds the base-game custom-layout scene path for <paramref name="eventEntry" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="eventEntry" /> 创建游戏本体的自定义布局场景路径。
		///     </para>
		/// </summary>
		public static string EventCustomLayoutScenePath(string eventEntry)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(eventEntry, "eventEntry");
			return SceneHelper.GetScenePath("events/custom/" + Normalize(eventEntry));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds base-game-style map and game-history paths for <paramref name="ancientEntry" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="ancientEntry" /> 创建游戏本体风格的先古之民地图和游戏历史路径。
		///     </para>
		/// </summary>
		public static AncientEventPresentationAssetProfile AncientPresentation(string ancientEntry)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(ancientEntry, "ancientEntry");
			string text = Normalize(ancientEntry);
			return new AncientEventPresentationAssetProfile(ImageHelper.GetImagePath("packed/map/ancients/ancient_node_" + text + ".png"), ImageHelper.GetImagePath("packed/map/ancients/ancient_node_" + text + "_outline.png"), ImageHelper.GetImagePath("ui/run_history/" + text + ".png"), ImageHelper.GetImagePath("ui/run_history/" + text + "_outline.png"));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds base-game-style timeline portrait paths for <paramref name="epochId" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="epochId" /> 创建游戏本体风格的时间线纪元肖像路径。
		///     </para>
		/// </summary>
		public static EpochAssetProfile Epoch(string epochId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(epochId, "epochId");
			string text = Normalize(epochId);
			return new EpochAssetProfile(ImageHelper.GetImagePath("atlases/epoch_atlas.sprites/" + text + ".tres"), ImageHelper.GetImagePath("timeline/epoch_portraits/" + text + ".png"));
		}

		private static string Normalize(string value)
		{
			return value.Trim().ToLowerInvariant();
		}

		private unsafe static string NormalizeAncientCardType(CardType cardType)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Expected I4, but got Unknown
			//IL_0046: Unknown result type (might be due to invalid IL or missing references)
			switch ((int)cardType)
			{
			case 0:
			case 4:
			case 5:
				return "skill";
			case 1:
			case 2:
			case 3:
			case 6:
				return ((object)(*(CardType*)(&cardType))/*cast due to constrained. prefix*/).ToString().ToLowerInvariant();
			default:
				throw new ArgumentOutOfRangeException("cardType", cardType, null);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Represents a declarative manifest entry that registers content with a
	///         <see cref="T:STS2RitsuLib.Content.ModContentRegistry" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         表示向 <see cref="T:STS2RitsuLib.Content.ModContentRegistry" /> 注册内容的声明式清单条目。
	///     </para>
	/// </summary>
	public interface IContentRegistrationEntry
	{
		/// <summary>
		///     <para xml:lang="en">Registers this entry with <paramref name="registry" />.</para>
		///     <para xml:lang="zh-CN">向 <paramref name="registry" /> 注册此条目。</para>
		/// </summary>
		void Register(ModContentRegistry registry);
	}
	/// <summary>
	///     <para xml:lang="en">Registers a mod character model type.</para>
	///     <para xml:lang="zh-CN">注册模组角色模型类型。</para>
	/// </summary>
	/// <typeparam name="TCharacter">
	///     <para xml:lang="en">The concrete <see cref="T:MegaCrit.Sts2.Core.Models.CharacterModel" /> type to register.</para>
	///     <para xml:lang="zh-CN">要注册的具体 <see cref="T:MegaCrit.Sts2.Core.Models.CharacterModel" /> 类型。</para>
	/// </typeparam>
	public sealed class CharacterRegistrationEntry<TCharacter> : IContentRegistrationEntry where TCharacter : CharacterModel
	{
		private readonly List<Action<ModContentRegistry>> _starterRegistrations = new List<Action<ModContentRegistry>>();

		/// <inheritdoc />
		public void Register(ModContentRegistry registry)
		{
			registry.RegisterCharacter<TCharacter>();
			foreach (Action<ModContentRegistry> starterRegistration in _starterRegistrations)
			{
				starterRegistration(registry);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends <paramref name="count" /> copies of <typeparamref name="TCard" /> to the starting deck when
		///         this character entry is registered.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册此角色条目时，向初始牌组追加 <paramref name="count" /> 张
		///         <typeparamref name="TCard" />。
		///     </para>
		/// </summary>
		public CharacterRegistrationEntry<TCharacter> AddStartingCard<TCard>(int count = 1) where TCard : CardModel
		{
			return AddStartingCard<TCard>(count, 0);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends <paramref name="count" /> copies of <typeparamref name="TCard" /> to the starting deck at
		///         the specified registration <paramref name="order" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         按指定注册顺序 <paramref name="order" />，向初始牌组追加 <paramref name="count" /> 张
		///         <typeparamref name="TCard" />。
		///     </para>
		/// </summary>
		public CharacterRegistrationEntry<TCharacter> AddStartingCard<TCard>(int count, int order) where TCard : CardModel
		{
			_starterRegistrations.Add(delegate(ModContentRegistry registry)
			{
				registry.RegisterCharacterStarterCard<TCharacter, TCard>(count, order);
			});
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends <paramref name="count" /> copies of <typeparamref name="TRelic" /> to the starting relics
		///         when this character entry is registered.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册此角色条目时，向初始遗物追加 <paramref name="count" /> 个
		///         <typeparamref name="TRelic" />。
		///     </para>
		/// </summary>
		public CharacterRegistrationEntry<TCharacter> AddStartingRelic<TRelic>(int count = 1) where TRelic : RelicModel
		{
			return AddStartingRelic<TRelic>(count, 0);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends <paramref name="count" /> copies of <typeparamref name="TRelic" /> to the starting relics at
		///         the specified registration <paramref name="order" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         按指定注册顺序 <paramref name="order" />，向初始遗物追加 <paramref name="count" /> 个
		///         <typeparamref name="TRelic" />。
		///     </para>
		/// </summary>
		public CharacterRegistrationEntry<TCharacter> AddStartingRelic<TRelic>(int count, int order) where TRelic : RelicModel
		{
			_starterRegistrations.Add(delegate(ModContentRegistry registry)
			{
				registry.RegisterCharacterStarterRelic<TCharacter, TRelic>(count, order);
			});
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends <paramref name="count" /> copies of <typeparamref name="TPotion" /> to the starting potions
		///         when this character entry is registered.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册此角色条目时，向初始药水追加 <paramref name="count" /> 瓶
		///         <typeparamref name="TPotion" />。
		///     </para>
		/// </summary>
		public CharacterRegistrationEntry<TCharacter> AddStartingPotion<TPotion>(int count = 1) where TPotion : PotionModel
		{
			return AddStartingPotion<TPotion>(count, 0);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends <paramref name="count" /> copies of <typeparamref name="TPotion" /> to the starting potions
		///         at the specified registration <paramref name="order" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         按指定注册顺序 <paramref name="order" />，向初始药水追加 <paramref name="count" /> 瓶
		///         <typeparamref name="TPotion" />。
		///     </para>
		/// </summary>
		public CharacterRegistrationEntry<TCharacter> AddStartingPotion<TPotion>(int count, int order) where TPotion : PotionModel
		{
			_starterRegistrations.Add(delegate(ModContentRegistry registry)
			{
				registry.RegisterCharacterStarterPotion<TCharacter, TPotion>(count, order);
			});
			return this;
		}
	}
