	/// <summary>
	///     <para xml:lang="en">
	///         Controls whether a registered mod act can appear in vanilla act-list randomization.
	///     </para>
	///     <para xml:lang="zh-CN">控制已注册的模组章节是否可出现在游戏本体随机生成的章节列表中。</para>
	/// </summary>
	public interface IModActRandomListPolicy
	{
		/// <summary>
		///     <para xml:lang="en">True when this act is safe to appear organically in generated run act lists.</para>
		///     <para xml:lang="zh-CN">
		///         为 <see langword="true" /> 时，该章节可以自然出现在一局游戏中随机生成的章节列表里。
		///     </para>
		/// </summary>
		bool AllowInRandomActList { get; }
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Optionally determines whether a mod <see cref="T:MegaCrit.Sts2.Core.Models.AncientEventModel" /> can enter the Ancient selection
	///         pool for a particular <see cref="T:MegaCrit.Sts2.Core.Models.ActModel" /> during room generation.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         可选地决定模组 <see cref="T:MegaCrit.Sts2.Core.Models.AncientEventModel" /> 在生成房间时能否进入指定
	///         <see cref="T:MegaCrit.Sts2.Core.Models.ActModel" /> 的先古之民选择池。
	///     </para>
	/// </summary>
	public interface IModAncientActValidity
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether this Ancient is valid for <paramref name="act" />. A value of
		///         <see langword="false" /> excludes it from <see cref="M:MegaCrit.Sts2.Core.Models.ActModel.GetUnlockedAncients(MegaCrit.Sts2.Core.Unlocks.UnlockState)" /> and the
		///         shared-Ancient subset used by <see cref="M:MegaCrit.Sts2.Core.Models.ActModel.GenerateRooms(MegaCrit.Sts2.Core.Random.Rng,MegaCrit.Sts2.Core.Unlocks.UnlockState,System.Boolean)" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回此先古之民是否适用于 <paramref name="act" />。返回 <see langword="false" /> 时，它会从
		///         <see cref="M:MegaCrit.Sts2.Core.Models.ActModel.GetUnlockedAncients(MegaCrit.Sts2.Core.Unlocks.UnlockState)" /> 的结果以及
		///         <see cref="M:MegaCrit.Sts2.Core.Models.ActModel.GenerateRooms(MegaCrit.Sts2.Core.Random.Rng,MegaCrit.Sts2.Core.Unlocks.UnlockState,System.Boolean)" /> 使用的共享先古之民子集中排除。
		///     </para>
		/// </summary>
		bool IsValidForAct(ActModel act);
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Represents a declarative content-pack step for timelines, unlocks, or other
	///         <see cref="T:STS2RitsuLib.Scaffolding.Content.ModContentPackContext" /> features. Unlike <see cref="T:STS2RitsuLib.Scaffolding.Content.IContentRegistrationEntry" />, it
	///         receives the complete pack context.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         表示用于时间线、解锁或其他 <see cref="T:STS2RitsuLib.Scaffolding.Content.ModContentPackContext" /> 功能的声明式内容包步骤。与
	///         <see cref="T:STS2RitsuLib.Scaffolding.Content.IContentRegistrationEntry" /> 不同，它会接收完整的内容包上下文。
	///     </para>
	/// </summary>
	public interface IModContentPackEntry
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Applies this step during <see cref="M:STS2RitsuLib.Scaffolding.Content.ModContentPackBuilder.Apply" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <see cref="M:STS2RitsuLib.Scaffolding.Content.ModContentPackBuilder.Apply" /> 期间应用此步骤。
		///     </para>
		/// </summary>
		void Apply(ModContentPackContext context);
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Optionally determines whether a mod <see cref="T:MegaCrit.Sts2.Core.Models.EncounterModel" /> can enter the encounter pool for a
	///         particular <see cref="T:MegaCrit.Sts2.Core.Models.ActModel" /> during room generation.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         可选地决定模组 <see cref="T:MegaCrit.Sts2.Core.Models.EncounterModel" /> 在生成房间时能否进入指定
	///         <see cref="T:MegaCrit.Sts2.Core.Models.ActModel" /> 的遭遇池。
	///     </para>
	/// </summary>
	public interface IModEncounterActValidity
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether this encounter is valid for <paramref name="act" />. A value of
		///         <see langword="false" /> excludes it from <see cref="M:MegaCrit.Sts2.Core.Models.ActModel.GenerateAllEncounters" />, including
		///         normal, elite, and boss encounter pools.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回此遭遇是否适用于 <paramref name="act" />。返回 <see langword="false" /> 时，它会从
		///         <see cref="M:MegaCrit.Sts2.Core.Models.ActModel.GenerateAllEncounters" /> 的普通、精英和首领遭遇池中排除。
		///     </para>
		/// </summary>
		bool IsValidForAct(ActModel act);
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides a base <see cref="T:MegaCrit.Sts2.Core.Models.ActModel" /> for mods with chest Spine replacement, scene and map asset
	///         overrides, and an optional combat-background layer directory containing <c>_bg_</c> and <c>_fg_</c>
	///         scenes.
	///     </para>
	///     <para xml:lang="en">
	///         To reuse an existing act's assets, return a profile created by
	///         <see cref="M:STS2RitsuLib.Scaffolding.Content.ContentAssetProfiles.FromVanillaActId(System.String)" /> from <see cref="P:STS2RitsuLib.Scaffolding.Content.ModActTemplate.AssetProfile" />, using the
	///         base-game asset folder name rather than this model's ID.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为模组提供基础 <see cref="T:MegaCrit.Sts2.Core.Models.ActModel" />，支持替换宝箱 Spine 资源、场景和地图资源，以及指定包含
	///         <c>_bg_</c> 与 <c>_fg_</c> 场景的可选战斗背景图层目录。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         若要复用现有章节的资源，请让 <see cref="P:STS2RitsuLib.Scaffolding.Content.ModActTemplate.AssetProfile" /> 返回由
	///         <see cref="M:STS2RitsuLib.Scaffolding.Content.ContentAssetProfiles.FromVanillaActId(System.String)" /> 创建的配置，并使用游戏本体的资源文件夹名称，
	///         而不是此模型的 ID。
	///     </para>
	/// </summary>
	public abstract class ModActTemplate : ActModel, IModActAssetOverrides, IModActRandomListPolicy
	{
		/// <inheritdoc />
		public override string ChestSpineResourcePath => CustomChestSpineResourcePath ?? ((ActModel)this).ChestSpineResourcePath;

		/// <inheritdoc />
		public virtual ActAssetProfile AssetProfile => ActAssetProfile.Empty;

		/// <inheritdoc />
		public virtual string? CustomBackgroundScenePath => AssetProfile.BackgroundScenePath;

		/// <inheritdoc />
		public virtual string? CustomRestSiteBackgroundPath => AssetProfile.RestSiteBackgroundPath;

		/// <inheritdoc />
		public virtual string? CustomMapTopBgPath => AssetProfile.MapTopBgPath;

		/// <inheritdoc />
		public virtual string? CustomMapMidBgPath => AssetProfile.MapMidBgPath;

		/// <inheritdoc />
		public virtual string? CustomMapBotBgPath => AssetProfile.MapBotBgPath;

		/// <inheritdoc />
		public virtual string? CustomChestSpineResourcePath => AssetProfile.ChestSpineResourcePath;

		/// <inheritdoc />
		public virtual string? CustomBackgroundLayersDirectoryPath => AssetProfile.BackgroundLayersDirectoryPath;

		/// <inheritdoc />
		public virtual bool AllowInRandomActList => false;
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides a base <see cref="T:MegaCrit.Sts2.Core.Models.AfflictionModel" /> for mods with keyword hover tips and an
	///         <see cref="T:STS2RitsuLib.Scaffolding.Content.Patches.IModAfflictionAssetOverrides" /> overlay-scene replacement.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为模组提供基础 <see cref="T:MegaCrit.Sts2.Core.Models.AfflictionModel" />，支持关键词悬浮提示和
	///         <see cref="T:STS2RitsuLib.Scaffolding.Content.Patches.IModAfflictionAssetOverrides" /> 覆盖层场景替换。
	///     </para>
	/// </summary>
	public abstract class ModAfflictionTemplate : AfflictionModel, IModAfflictionAssetOverrides
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets the keyword IDs shown as hover tips for this affliction. These IDs are display-only:
		///         <see cref="T:MegaCrit.Sts2.Core.Models.AfflictionModel" /> has no gameplay keyword collection, so each ID is resolved through
		///         <see cref="T:STS2RitsuLib.Keywords.ModKeywordRegistry" /> only to create a hover tip. Any gameplay behavior must be
		///         implemented by the affliction itself.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取显示为此侵蚀悬浮提示的关键词 ID。这些 ID 仅用于显示：<see cref="T:MegaCrit.Sts2.Core.Models.AfflictionModel" />
		///         没有参与游戏逻辑的关键词集合，因此每个 ID 只会通过 <see cref="T:STS2RitsuLib.Keywords.ModKeywordRegistry" /> 解析为
		///         悬浮提示。任何游戏行为都必须由侵蚀自身实现。
		///     </para>
		/// </summary>
		protected virtual IEnumerable<string> RegisteredKeywordIds => Array.Empty<string>();

		/// <summary>
		///     <para xml:lang="en">Gets additional hover tips included with the keyword-derived tips.</para>
		///     <para xml:lang="zh-CN">获取与关键词生成的提示一同显示的额外悬浮提示。</para>
		/// </summary>
		protected virtual IEnumerable<IHoverTip> AdditionalHoverTips => Array.Empty<IHoverTip>();

		/// <inheritdoc />
		protected sealed override IEnumerable<IHoverTip> ExtraHoverTips
		{
			get
			{
				List<IHoverTip> list = new List<IHoverTip>();
				list.AddRange(AdditionalHoverTips);
				list.AddRange(RegisteredKeywordIds.ToHoverTips());
				list.AddRange(this.GetModKeywordHoverTips());
				return new <>z__ReadOnlyList<IHoverTip>(list);
			}
		}

		/// <inheritdoc />
		public virtual AfflictionAssetProfile AssetProfile => AfflictionAssetProfile.Empty;

		/// <inheritdoc />
		public virtual string? CustomOverlayScenePath => AssetProfile.OverlayScenePath;
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Applies <see cref="T:STS2RitsuLib.Scaffolding.Content.IModAncientActValidity" /> when building each act's Ancient candidate pool.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         创建各章节的先古之民候选池时应用 <see cref="T:STS2RitsuLib.Scaffolding.Content.IModAncientActValidity" />。
	///     </para>
	/// </summary>
	public static class ModAncientActValidityFilter
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether <paramref name="ancient" /> can appear in <paramref name="act" />. Ancients that do
		///         not implement <see cref="T:STS2RitsuLib.Scaffolding.Content.IModAncientActValidity" /> are allowed.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <paramref name="ancient" /> 能否出现在 <paramref name="act" /> 中。未实现
		///         <see cref="T:STS2RitsuLib.Scaffolding.Content.IModAncientActValidity" /> 的先古之民默认允许出现。
		///     </para>
		/// </summary>
		public static bool IsValidForAct(ActModel act, AncientEventModel ancient)
		{
			ArgumentNullException.ThrowIfNull(act, "act");
			ArgumentNullException.ThrowIfNull(ancient, "ancient");
			if (ancient is IModAncientActValidity modAncientActValidity)
			{
				return modAncientActValidity.IsValidForAct(act);
			}
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Keeps only the Ancients for which <see cref="M:STS2RitsuLib.Scaffolding.Content.ModAncientActValidityFilter.IsValidForAct(MegaCrit.Sts2.Core.Models.ActModel,MegaCrit.Sts2.Core.Models.AncientEventModel)" /> returns
		///         <see langword="true" /> for <paramref name="act" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         只保留针对 <paramref name="act" /> 调用 <see cref="M:STS2RitsuLib.Scaffolding.Content.ModAncientActValidityFilter.IsValidForAct(MegaCrit.Sts2.Core.Models.ActModel,MegaCrit.Sts2.Core.Models.AncientEventModel)" /> 时返回
		///         <see langword="true" /> 的先古之民。
		///     </para>
		/// </summary>
		public static IEnumerable<AncientEventModel> FilterForAct(ActModel act, IEnumerable<AncientEventModel> ancients)
		{
			ArgumentNullException.ThrowIfNull(act, "act");
			ArgumentNullException.ThrowIfNull(ancients, "ancients");
			return ancients.Where((AncientEventModel ancient) => IsValidForAct(act, ancient));
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides a base <see cref="T:MegaCrit.Sts2.Core.Models.AncientEventModel" /> with namespaced option keys, relic options that can
	///         complete the event, presentation-asset overrides, and dialogue loaded from the <c>ancients</c>
	///         localization table through <see cref="M:STS2RitsuLib.Localization.AncientDialogueLocalization.BuildDialogueSetForModAncient(System.String)" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供基础 <see cref="T:MegaCrit.Sts2.Core.Models.AncientEventModel" />，支持带命名空间的选项键、可完成事件的遗物选项、表现资源
	///         替换，以及通过 <see cref="M:STS2RitsuLib.Localization.AncientDialogueLocalization.BuildDialogueSetForModAncient(System.String)" /> 从
	///         <c>ancients</c> 本地化表加载的对话。
	///     </para>
	/// </summary>
	public abstract class ModAncientEventTemplate : AncientEventModel, IModAncientEventAssetOverrides, IModEventAssetOverrides, IModAncientActValidity
	{
		/// <inheritdoc />
		public virtual EventAssetProfile AssetProfile => EventAssetProfile.Empty;

		/// <inheritdoc />
		public virtual string? CustomLayoutScenePath => AssetProfile.LayoutScenePath;

		/// <inheritdoc />
		public virtual string? CustomInitialPortraitPath => AssetProfile.InitialPortraitPath;

		/// <inheritdoc />
		public virtual string? CustomBackgroundScenePath => AssetProfile.BackgroundScenePath;

		/// <inheritdoc />
		public virtual string? CustomVfxScenePath => AssetProfile.VfxScenePath;

		/// <inheritdoc />
		public virtual AncientEventPresentationAssetProfile AncientPresentationAssetProfile => AncientEventPresentationAssetProfile.Empty;

		/// <inheritdoc />
		public virtual string? CustomMapIconPath => AncientPresentationAssetProfile?.MapIconPath;

		/// <inheritdoc />
		public virtual string? CustomMapIconOutlinePath => AncientPresentationAssetProfile?.MapIconOutlinePath;

		/// <inheritdoc />
		public virtual string? CustomRunHistoryIconPath => AncientPresentationAssetProfile?.RunHistoryIconPath;

		/// <inheritdoc />
		public virtual string? CustomRunHistoryIconOutlinePath => AncientPresentationAssetProfile?.RunHistoryIconOutlinePath;

		/// <inheritdoc />
		public virtual bool IsValidForAct(ActModel act)
		{
			return true;
		}

		/// <inheritdoc />
		/// <remarks>
		///     <para xml:lang="en">
		///         The default implementation scans loaded localization data, including <c>ancients</c> JSON, for
		///         this Ancient's <c>talk</c> keys. Override it for a non-localized or custom dialogue structure.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         默认实现会扫描已加载的本地化数据（包括 <c>ancients</c> JSON），查找此先古之民的
		///         <c>talk</c> 键。如需使用非本地化或自定义对话结构，请重写此方法。
		///     </para>
		/// </remarks>
		protected override AncientDialogueSet DefineDialogues()
		{
			return AncientDialogueLocalization.BuildDialogueSetForModAncient(((AbstractModel)this).Id.Entry);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds an option-localization key from this Ancient's ID, <paramref name="pageName" />, and
		///         <paramref name="optionName" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用此先古之民的 ID、<paramref name="pageName" /> 和 <paramref name="optionName" />
		///         创建选项本地化键。
		///     </para>
		/// </summary>
		protected string ModOptionKey(string pageName, string optionName)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(pageName, "pageName");
			ArgumentException.ThrowIfNullOrWhiteSpace(optionName, "optionName");
			return $"{((AbstractModel)this).Id.Entry}.pages.{pageName}.options.{optionName}";
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds an option-localization key for the <c>INITIAL</c> page.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建 <c>INITIAL</c> 页面的选项本地化键。
		///     </para>
		/// </summary>
		protected string InitialOptionKey(string optionName)
		{
			return ModOptionKey("INITIAL", optionName);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a relic option that grants a mutable copy of the specified relic type to the event owner
		///         and then calls <see cref="M:MegaCrit.Sts2.Core.Models.AncientEventModel.Done" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建一个遗物选项，将指定遗物类型的可变副本授予事件拥有者，然后调用
		///         <see cref="M:MegaCrit.Sts2.Core.Models.AncientEventModel.Done" />。
		///     </para>
		/// </summary>
		protected EventOption CreateModRelicOption<T>(string pageName = "INITIAL") where T : RelicModel
		{
			return CreateModRelicOption(((RelicModel)ModelDb.Relic<T>()).ToMutable(), pageName);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a relic option that grants <paramref name="relic" /> to the event owner and completes the
		///         Ancient event.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建一个遗物选项，将 <paramref name="relic" /> 授予事件拥有者并完成先古之民事件。
		///     </para>
		/// </summary>
		protected EventOption CreateModRelicOption(RelicModel relic, string pageName = "INITIAL")
		{
			return CreateModRelicOption(relic, async delegate
			{
				Player val = ((EventModel)this).Owner ?? throw new InvalidOperationException("Ancient '" + ((AbstractModel)this).Id.Entry + "' had no owner when a relic option was chosen.");
				relic.Owner = val;
				await RelicCmd.Obtain(relic, val, -1);
				((AncientEventModel)this).Done();
			}, pageName);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a relic option with an explicit post-selection callback and a localization key derived
		///         from <paramref name="pageName" /> and the relic ID. If <see cref="P:MegaCrit.Sts2.Core.Models.EventModel.Owner" /> is not yet
		///         assigned, the relic owner remains unset.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建带显式选择后回调的遗物选项，其本地化键由 <paramref name="pageName" /> 和遗物 ID 生成。如果
		///         <see cref="P:MegaCrit.Sts2.Core.Models.EventModel.Owner" /> 尚未设置，则遗物拥有者保持未设置。
		///     </para>
		/// </summary>
		protected EventOption CreateModRelicOption(RelicModel relic, Func<Task>? onChosen, string pageName = "INITIAL")
		{
			((AbstractModel)relic).AssertMutable();
			if (((EventModel)this).Owner != null)
			{
				relic.Owner = ((EventModel)this).Owner;
			}
			return EventOption.FromRelic(relic, (EventModel)(object)this, onChosen, ModOptionKey(pageName, ((AbstractModel)relic).Id.Entry));
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides a base badge type for mods.</para>
	///     <para xml:lang="zh-CN">提供模组徽章的基础类型。</para>
	/// </summary>
	public abstract class ModBadgeTemplate
	{
		/// <summary>
		///     <para xml:lang="en">Gets whether obtaining this badge requires a victory.</para>
		///     <para xml:lang="zh-CN">获取获得此徽章是否需要取得胜利。</para>
		/// </summary>
		public virtual bool RequiresWin => false;

		/// <summary>
		///     <para xml:lang="en">Gets whether this badge is available only in multiplayer.</para>
		///     <para xml:lang="zh-CN">获取此徽章是否仅在多人模式中可用。</para>
		/// </summary>
		public virtual bool MultiplayerOnly => false;

		/// <summary>
		///     <para xml:lang="en">Gets the optional badge-icon replacement path.</para>
		///     <para xml:lang="zh-CN">获取可选的徽章图标替换路径。</para>
		/// </summary>
		public virtual string? CustomBadgeIconPath => null;

		/// <summary>
		///     <para xml:lang="en">Gets the stable badge ID derived from the template type name.</para>
		///     <para xml:lang="zh-CN">获取根据模板类型名称生成的稳定徽章 ID。</para>
		/// </summary>
		public virtual string Id => BuildDefaultRegistrationId(GetType().Name);

		/// <summary>
		///     <para xml:lang="en">Returns the badge rarity for the supplied run and player.</para>
		///     <para xml:lang="zh-CN">返回指定游戏记录和玩家对应的徽章稀有度。</para>
		/// </summary>
		public abstract BadgeRarity Rarity(SerializableRun run, SerializablePlayer player);

		/// <summary>
		///     <para xml:lang="en">Returns whether the player obtained this badge in the supplied run.</para>
		///     <para xml:lang="zh-CN">返回玩家是否在指定游戏记录中获得此徽章。</para>
		/// </summary>
		public abstract bool IsObtained(SerializableRun run, SerializablePlayer player);

		internal static string BuildDefaultRegistrationId(string typeName)
		{
			if (!string.IsNullOrWhiteSpace(typeName))
			{
				return ModContentRegistry.NormalizePublicStem(typeName);
			}
			return string.Empty;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides a base <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> for mods with additional hover tips and optional card-asset
	///         overrides. Gold and red hand glows can be supplied through <see cref="T:STS2RitsuLib.Scaffolding.Cards.HandGlow.ModCardHandGlowRegistry" />;
	///         arbitrary outline colors use <see cref="T:STS2RitsuLib.Scaffolding.Cards.HandOutline.ModCardHandOutlineRegistry" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为模组提供基础 <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" />，支持额外悬浮提示和可选的卡牌资源替换。金色与红色手牌
	///         发光可以通过 <see cref="T:STS2RitsuLib.Scaffolding.Cards.HandGlow.ModCardHandGlowRegistry" /> 提供；任意描边颜色则使用
	///         <see cref="T:STS2RitsuLib.Scaffolding.Cards.HandOutline.ModCardHandOutlineRegistry" />。
	///     </para>
	/// </summary>
