		/// </summary>
		public static ModContentPackBuilder For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			return new ModContentPackBuilder(modId.Trim());
		}

		/// <summary>
		///     <para xml:lang="en">Queues <see cref="M:STS2RitsuLib.Content.ModContentRegistry.RegisterCharacter``1" />.</para>
