		/// </summary>
		public ModContentPackBuilder Character<TCharacter>() where TCharacter : CharacterModel
		{
			return AddStep(delegate(ModContentPackContext ctx)
			{
				ctx.Content.RegisterCharacter<TCharacter>();
			});
		}

