		/// </summary>
		public ModContentPackBuilder Character<TCharacter>(Action<CharacterRegistrationEntry<TCharacter>> configure) where TCharacter : CharacterModel
		{
			ArgumentNullException.ThrowIfNull(configure, "configure");
			CharacterRegistrationEntry<TCharacter> entry = new CharacterRegistrationEntry<TCharacter>();
			configure(entry);
			return AddStep(delegate(ModContentPackContext ctx)
			{
				entry.Register(ctx.Content);
			});
		}

