		/// <summary>
		///     <para xml:lang="en">Queues optional content and keyword manifests.</para>
		///     <para xml:lang="zh-CN">将可选的内容和关键词清单加入队列。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         <see cref="T:STS2RitsuLib.Scaffolding.Content.IContentRegistrationEntry" /> may include
		///         <see cref="T:STS2RitsuLib.Scaffolding.Content.ArchaicToothTranscendenceRegistrationEntry`2" />,
		///         <see cref="T:STS2RitsuLib.Scaffolding.Content.TouchOfOrobasRefinementRegistrationEntry`2" />, and related Orobas
		///         entries alongside cards/relics/etc. Keywords use a different registry; prefer
		///         <see cref="M:STS2RitsuLib.Scaffolding.Content.ModContentPackBuilder.ContentManifest(System.Collections.Generic.IEnumerable{STS2RitsuLib.Scaffolding.Content.IContentRegistrationEntry})" /> / <see cref="M:STS2RitsuLib.Scaffolding.Content.ModContentPackBuilder.KeywordManifest(System.Collections.Generic.IEnumerable{STS2RitsuLib.Keywords.KeywordRegistrationEntry})" /> / <see cref="M:STS2RitsuLib.Scaffolding.Content.ModContentPackBuilder.PackManifest(System.Collections.Generic.IEnumerable{STS2RitsuLib.Scaffolding.Content.IModContentPackEntry})" /> when you want
		///         that split to be explicit.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         <see cref="T:STS2RitsuLib.Scaffolding.Content.IContentRegistrationEntry" /> 可以包含
		///         <see cref="T:STS2RitsuLib.Scaffolding.Content.ArchaicToothTranscendenceRegistrationEntry`2" />、
		///         <see cref="T:STS2RitsuLib.Scaffolding.Content.TouchOfOrobasRefinementRegistrationEntry`2" />，以及与卡牌 / 遗物等并列的相关 Orobas
		///         条目。关键词使用不同的注册表；当你希望这种拆分显式可见时，优先使用 <see cref="M:STS2RitsuLib.Scaffolding.Content.ModContentPackBuilder.ContentManifest(System.Collections.Generic.IEnumerable{STS2RitsuLib.Scaffolding.Content.IContentRegistrationEntry})" /> / <see cref="M:STS2RitsuLib.Scaffolding.Content.ModContentPackBuilder.KeywordManifest(System.Collections.Generic.IEnumerable{STS2RitsuLib.Keywords.KeywordRegistrationEntry})" /> /
		///         <see cref="M:STS2RitsuLib.Scaffolding.Content.ModContentPackBuilder.PackManifest(System.Collections.Generic.IEnumerable{STS2RitsuLib.Scaffolding.Content.IModContentPackEntry})" />。
		///     </para>
		/// </remarks>
		public ModContentPackBuilder Manifest(IEnumerable<IContentRegistrationEntry>? contentEntries = null, IEnumerable<KeywordRegistrationEntry>? keywordEntries = null)
		{
			if (contentEntries != null)
			{
				Entries(contentEntries);
			}
			if (keywordEntries != null)
			{
				Keywords(keywordEntries);
			}
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Queues optional content, keyword, and content-pack manifests.</para>
		///     <para xml:lang="zh-CN">将可选的内容、关键词和内容包清单加入队列。</para>
		/// </summary>
		public ModContentPackBuilder Manifest(IEnumerable<IContentRegistrationEntry>? contentEntries, IEnumerable<KeywordRegistrationEntry>? keywordEntries, IEnumerable<IModContentPackEntry>? packEntries)
		{
			Manifest(contentEntries, keywordEntries);
			if (packEntries != null)
			{
				PackEntries(packEntries);
			}
			return this;
		}

