		/// <summary>
		///     <para xml:lang="en">Appends a custom delegate to execute during <see cref="M:STS2RitsuLib.Scaffolding.Content.ModContentPackBuilder.Apply" />.</para>
		///     <para xml:lang="zh-CN">追加一个在 <see cref="M:STS2RitsuLib.Scaffolding.Content.ModContentPackBuilder.Apply" /> 期间执行的自定义委托。</para>
		/// </summary>
		public ModContentPackBuilder Custom(Action<ModContentPackContext> step)
		{
			return AddStep(step);
		}

		/// <summary>
		///     <para xml:lang="en">Creates the registry context without running queued steps.</para>
		///     <para xml:lang="zh-CN">创建注册表上下文，但不执行队列中的步骤。</para>
		/// </summary>
		public ModContentPackContext BuildContext()
		{
			return new ModContentPackContext(_modId, RitsuLibFramework.GetContentRegistry(_modId), RitsuLibFramework.GetKeywordRegistry(_modId), RitsuLibFramework.GetTimelineRegistry(_modId), RitsuLibFramework.GetUnlockRegistry(_modId), RitsuLibFramework.GetCardTagRegistry(_modId), RitsuLibFramework.GetCardPileRegistry(_modId));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Schedules all queued registration steps for the framework discovery window and returns the
		///         materialized context.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         安排所有队列中的注册步骤在框架发现窗口执行，并返回已创建的上下文。
		///     </para>
		///     <para xml:lang="en">A failed step is reported and skipped without preventing later steps from running.</para>
		///     <para xml:lang="zh-CN">失败的步骤会被报告并跳过，不会阻止后续步骤继续执行。</para>
		/// </summary>
		public ModContentPackContext Apply()
		{
			ModContentPackContext result = BuildContext();
			Action<ModContentPackContext>[] steps = _steps.ToArray();
			RitsuLibFramework.EnqueueDeferredContentPack(_modId, delegate(ModContentPackContext ctx)
			{
				Logger val = RitsuLibFramework.CreateLogger(_modId, (LogType)0);
				int num = 0;
				int num2 = 0;
				for (int i = 0; i < steps.Length; i++)
				{
					try
					{
						steps[i](ctx);
						num++;
					}
					catch (Exception ex)
					{
						num2++;
						string text = $"deferred content pack step {i + 1} of {steps.Length}";
						RegistrationFreezeDiagnostics.RecordFailure("ContentPack", _modId, text, ex);
						val.ErrorNoTrace($"[ContentPack] Failed {text} for mod '{_modId}': {ex.GetType().Name}: {ex.Message}");
					}
				}
				val.Info($"[ContentPack] Applied {num} deferred registration step(s); {num2} failed.", 1);
			}, $"{_modId}:{steps.Length} step(s)");
			return result;
		}

		private ModContentPackBuilder AddStep(Action<ModContentPackContext> step)
		{
			ArgumentNullException.ThrowIfNull(step, "step");
			_steps.Add(step);
			return this;
		}
	}
