		/// <summary>
		///     <para xml:lang="en">
		///         Returns a runtime-provided VFX root when <see cref="P:STS2RitsuLib.Scaffolding.Content.ModEventTemplate.SuppliesCustomEventVfx" /> is enabled, or
		///         <see langword="null" /> to continue with path loading.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         启用 <see cref="P:STS2RitsuLib.Scaffolding.Content.ModEventTemplate.SuppliesCustomEventVfx" /> 时返回运行时提供的特效根节点；返回
		///         <see langword="null" /> 时继续从路径加载。
		///     </para>
		/// </summary>
		protected virtual Node2D? TryCreateEventVfx()
		{
			return null;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds an option-localization key from this event's ID, <paramref name="pageName" />, and
		///         <paramref name="optionName" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用此事件的 ID、<paramref name="pageName" /> 和 <paramref name="optionName" />
		///         创建选项本地化键。
		///     </para>
		/// </summary>
		protected string ModOptionKey(string pageName, string optionName)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(pageName, "pageName");
			ArgumentException.ThrowIfNullOrWhiteSpace(optionName, "optionName");
			return $"{((AbstractModel)this).Id.Entry}.pages.{pageName}.options.{optionName}";
		}

		/// <summary>
		///     <para xml:lang="en">Builds an option-localization key for the <c>INITIAL</c> page.</para>
		///     <para xml:lang="zh-CN">创建 <c>INITIAL</c> 页面的选项本地化键。</para>
		/// </summary>
		protected string InitialOptionKey(string optionName)
		{
			return ModOptionKey("INITIAL", optionName);
		}

		/// <summary>
		///     <para xml:lang="en">Returns the localized description for <paramref name="pageName" />.</para>
		///     <para xml:lang="zh-CN">返回 <paramref name="pageName" /> 对应的本地化描述。</para>
		/// </summary>
		protected LocString PageDescription(string pageName)
		{
			return ((EventModel)this).L10NLookup(((AbstractModel)this).Id.Entry + ".pages." + pageName + ".description");
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a relic option from a mutable copy of <typeparamref name="T" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用 <typeparamref name="T" /> 的可变副本创建遗物选项。
		///     </para>
		/// </summary>
		protected EventOption CreateModRelicOption<T>(Func<Task>? onChosen, string pageName = "INITIAL") where T : RelicModel
		{
			return CreateModRelicOption(((RelicModel)ModelDb.Relic<T>()).ToMutable(), onChosen, pageName);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a relic option with a custom <paramref name="onChosen" /> callback and a localization key
		///         derived from the page and relic ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建带自定义 <paramref name="onChosen" /> 回调的遗物选项，其本地化键由页面和遗物 ID 生成。
		///     </para>
		/// </summary>
		protected EventOption CreateModRelicOption(RelicModel relic, Func<Task>? onChosen, string pageName = "INITIAL")
		{
			((AbstractModel)relic).AssertMutable();
			relic.Owner = ((EventModel)this).Owner ?? throw new InvalidOperationException("Event '" + ((AbstractModel)this).Id.Entry + "' tried to create a relic option before the event owner was assigned.");
			return EventOption.FromRelic(relic, (EventModel)(object)this, onChosen, ModOptionKey(pageName, ((AbstractModel)relic).Id.Entry));
		}
	}
