	internal static class ModEpochGatedContentPackHelper
	{
		internal static void ApplyExplicitTypes<TEpoch>(ModContentPackContext context, IReadOnlyList<Type> cardTypes, IReadOnlyList<Type> relicTypes) where TEpoch : EpochModel, new()
		{
			ApplyExplicitTypes(typeof(TEpoch), context, cardTypes, relicTypes);
		}

		internal static void ApplyExplicitTypes(Type epochType, ModContentPackContext context, IReadOnlyList<Type> cardTypes, IReadOnlyList<Type> relicTypes)
		{
			IReadOnlyList<Type> readOnlyList = SnapshotConcreteModelTypes<CardModel>(cardTypes ?? Array.Empty<Type>(), "cardTypes");
			IReadOnlyList<Type> readOnlyList2 = SnapshotConcreteModelTypes<RelicModel>(relicTypes ?? Array.Empty<Type>(), "relicTypes");
			if (readOnlyList.Count == 0 && readOnlyList2.Count == 0)
			{
				throw new ArgumentException("Epoch gated content for '" + epochType.Name + "' needs at least one card or relic type.");
			}
			string epochId = ModTimelineRegistry.GetEpochId(epochType);
			ModEpochGatedContentRegistry.Register(context.ModId, epochId, readOnlyList, readOnlyList2);
			foreach (Type item in readOnlyList)
			{
				context.Unlocks.RequireEpoch(item, epochId);
			}
			foreach (Type item2 in readOnlyList2)
			{
				context.Unlocks.RequireEpoch(item2, epochId);
			}
		}

		internal static void ApplyRelicsFromPool<TEpoch, TRelicPool>(ModContentPackContext context) where TEpoch : EpochModel, new() where TRelicPool : RelicPoolModel
		{
			ApplyRelicsFromPool(typeof(TEpoch), typeof(TRelicPool), context);
		}

		internal static void ApplyRelicsFromPool(Type epochType, Type relicPoolType, ModContentPackContext context)
		{
			Type[] array = (from t in ModContentRegistry.GetRegisteredModelsInPool(context.ModId, relicPoolType)
				where typeof(RelicModel).IsAssignableFrom(t)
				select t).ToArray();
			if (array.Length == 0)
			{
				throw new InvalidOperationException($"Epoch gated relics: no relic types in pool '{relicPoolType.Name}' for mod '{context.ModId}'.");
			}
			string epochId = ModTimelineRegistry.GetEpochId(epochType);
			ModEpochGatedContentRegistry.Register(context.ModId, epochId, null, array);
			Type[] array2 = array;
			foreach (Type modelType in array2)
			{
				context.Unlocks.RequireEpoch(modelType, epochId);
			}
		}

		internal static void ApplyCardsFromPool<TEpoch, TCardPool>(ModContentPackContext context) where TEpoch : EpochModel, new() where TCardPool : CardPoolModel
		{
			ApplyCardsFromPool(typeof(TEpoch), typeof(TCardPool), context);
		}

		internal static void ApplyCardsFromPool(Type epochType, Type cardPoolType, ModContentPackContext context)
		{
			Type[] array = (from t in ModContentRegistry.GetRegisteredModelsInPool(context.ModId, cardPoolType)
				where typeof(CardModel).IsAssignableFrom(t)
				select t).ToArray();
			if (array.Length == 0)
			{
				throw new InvalidOperationException($"Epoch gated cards: no card types in pool '{cardPoolType.Name}' for mod '{context.ModId}'.");
			}
			string epochId = ModTimelineRegistry.GetEpochId(epochType);
			ModEpochGatedContentRegistry.Register(context.ModId, epochId, array, null);
			Type[] array2 = array;
			foreach (Type modelType in array2)
			{
				context.Unlocks.RequireEpoch(modelType, epochId);
			}
		}

		internal static void ApplyRequireAllPoolCards<TEpoch, TPool>(ModContentPackContext context) where TEpoch : EpochModel, new() where TPool : CardPoolModel
		{
			ApplyRequireAllPoolCards(typeof(TEpoch), typeof(TPool), context);
		}

		internal static void ApplyRequireAllPoolCards(Type epochType, Type poolType, ModContentPackContext context)
		{
			string epochId = ModTimelineRegistry.GetEpochId(epochType);
			foreach (Type item in ModContentRegistry.GetRegisteredModelsInPool(context.ModId, poolType))
			{
				if (typeof(CardModel).IsAssignableFrom(item))
				{
					context.Unlocks.RequireEpochIfUnset(item, epochId);
				}
			}
		}

		internal static void ApplyRequireAllPoolRelics<TEpoch, TPool>(ModContentPackContext context) where TEpoch : EpochModel, new() where TPool : RelicPoolModel
		{
			ApplyRequireAllPoolRelics(typeof(TEpoch), typeof(TPool), context);
		}

		internal static void ApplyRequireAllPoolRelics(Type epochType, Type poolType, ModContentPackContext context)
		{
			string epochId = ModTimelineRegistry.GetEpochId(epochType);
			foreach (Type item in ModContentRegistry.GetRegisteredModelsInPool(context.ModId, poolType))
			{
				if (typeof(RelicModel).IsAssignableFrom(item))
				{
					context.Unlocks.RequireEpochIfUnset(item, epochId);
				}
			}
		}

		internal static void ApplyRequireAllPoolPotions<TEpoch, TPool>(ModContentPackContext context) where TEpoch : EpochModel, new() where TPool : PotionPoolModel
		{
			ApplyRequireAllPoolPotions(typeof(TEpoch), typeof(TPool), context);
		}

		internal static void ApplyRequireAllPoolPotions(Type epochType, Type poolType, ModContentPackContext context)
		{
			string epochId = ModTimelineRegistry.GetEpochId(epochType);
			foreach (Type item in ModContentRegistry.GetRegisteredModelsInPool(context.ModId, poolType))
			{
				if (typeof(PotionModel).IsAssignableFrom(item))
				{
					context.Unlocks.RequireEpochIfUnset(item, epochId);
				}
			}
		}

		internal static void ApplyExplicitPotions<TEpoch>(ModContentPackContext context, IReadOnlyList<Type> types) where TEpoch : EpochModel, new()
		{
			ApplyExplicitPotions(typeof(TEpoch), context, types);
		}

		internal static void ApplyExplicitPotions(Type epochType, ModContentPackContext context, IReadOnlyList<Type> types)
		{
			IReadOnlyList<Type> readOnlyList = SnapshotConcreteModelTypes<PotionModel>(types, "types");
			if (readOnlyList.Count == 0)
			{
				throw new ArgumentException("Epoch potion gating for '" + epochType.Name + "' needs at least one potion type.");
			}
			string epochId = ModTimelineRegistry.GetEpochId(epochType);
			foreach (Type item in readOnlyList)
			{
				context.Unlocks.RequireEpoch(item, epochId);
			}
		}

		private static IReadOnlyList<Type> SnapshotConcreteModelTypes<TModel>(IReadOnlyList<Type> types, string paramName) where TModel : AbstractModel
		{
			ArgumentNullException.ThrowIfNull(types, paramName);
			Type[] array = types.ToArray();
			Type[] array2 = array;
			foreach (Type type in array2)
			{
				if (type == null || type.IsAbstract || type.IsInterface || type.ContainsGenericParameters || !typeof(TModel).IsAssignableFrom(type))
				{
					throw new ArgumentException($"Type '{type?.FullName ?? "<null>"}' must be a closed concrete {typeof(TModel).Name} subtype.", paramName);
				}
			}
			return Array.AsReadOnly(array);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Registers an <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochModel" /> type with the base game's epoch discovery.</para>
