				list.AddRange(AdditionalHoverTips);
				list.AddRange(RegisteredKeywordIds.ToHoverTips());
				list.AddRange(this.GetModKeywordHoverTips());
				return new <>z__ReadOnlyList<IHoverTip>(list);
