	/// <summary>
	///     <para xml:lang="en">Provides model extension methods for requesting runtime visual reloads.</para>
	///     <para xml:lang="zh-CN">提供用于请求运行时视觉重载的模型扩展方法。</para>
	/// </summary>
	public static class RuntimeAssetReloadExtensions
	{
		/// <summary>
		///     <para xml:lang="en">Requests card-node reloads matching this card by reference or ID.</para>
		///     <para xml:lang="zh-CN">请求重新加载引用或 ID 与此卡牌匹配的卡牌节点。</para>
		/// </summary>
		public static void RequestVisualReload(this CardModel model)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			RuntimeAssetRefreshCoordinator.RequestCardsWhere((CardModel candidate) => candidate == model || ((AbstractModel)candidate).Id == ((AbstractModel)model).Id);
		}

		/// <summary>
		///     <para xml:lang="en">Requests relic-node reloads matching this relic by reference or ID.</para>
		///     <para xml:lang="zh-CN">请求重新加载引用或 ID 与此遗物匹配的遗物节点。</para>
		/// </summary>
		public static void RequestVisualReload(this RelicModel model)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			RuntimeAssetRefreshCoordinator.RequestRelicsWhere((RelicModel candidate) => candidate == model || ((AbstractModel)candidate).Id == ((AbstractModel)model).Id);
		}

		/// <summary>
		///     <para xml:lang="en">Requests potion-node reloads matching this potion by reference or ID.</para>
		///     <para xml:lang="zh-CN">请求重新加载引用或 ID 与此药水匹配的药水节点。</para>
		/// </summary>
		public static void RequestVisualReload(this PotionModel model)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			RuntimeAssetRefreshCoordinator.RequestPotionsWhere((PotionModel candidate) => candidate == model || ((AbstractModel)candidate).Id == ((AbstractModel)model).Id);
		}

		/// <summary>
		///     <para xml:lang="en">Requests power-node reloads matching this power by reference or ID.</para>
		///     <para xml:lang="zh-CN">请求重新加载引用或 ID 与此能力匹配的能力节点。</para>
		/// </summary>
		public static void RequestVisualReload(this PowerModel model)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			RuntimeAssetRefreshCoordinator.RequestPowersWhere((PowerModel candidate) => candidate == model || ((AbstractModel)candidate).Id == ((AbstractModel)model).Id);
		}

		/// <summary>
		///     <para xml:lang="en">Requests visual updates for orb nodes matching this orb by reference or ID.</para>
		///     <para xml:lang="zh-CN">请求更新引用或 ID 与此充能球匹配的充能球节点视觉效果。</para>
		/// </summary>
		public static void RequestVisualReload(this OrbModel model)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			RuntimeAssetRefreshCoordinator.RequestOrbsWhere((OrbModel candidate) => candidate == model || ((AbstractModel)candidate).Id == ((AbstractModel)model).Id);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Declares one <see cref="T:MegaCrit.Sts2.Core.Timeline.StoryModel" /> timeline column, including its epoch order, per-epoch unlock bindings,
	///         and story registration, as one content-pack entry.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将一个 <see cref="T:MegaCrit.Sts2.Core.Timeline.StoryModel" /> 时间线列的纪元顺序、逐纪元解锁绑定和故事注册声明为一个内容包条目。
	///     </para>
	/// </summary>
	public sealed class TimelineColumnPackEntry<TStory> : IModContentPackEntry where TStory : StoryModel, new()
	{
		private readonly Action<TimelineColumnBuilder<TStory>> _configure;

		/// <summary>
		///     <para xml:lang="en">Creates an entry that invokes <paramref name="configure" /> when the content pack is applied.</para>
		///     <para xml:lang="zh-CN">创建一个在应用内容包时调用 <paramref name="configure" /> 的条目。</para>
		/// </summary>
		public TimelineColumnPackEntry(Action<TimelineColumnBuilder<TStory>> configure)
		{
			ArgumentNullException.ThrowIfNull(configure, "configure");
			_configure = configure;
		}

		/// <inheritdoc />
		public void Apply(ModContentPackContext context)
		{
			TimelineColumnBuilder<TStory> timelineColumnBuilder = new TimelineColumnBuilder<TStory>(context);
			_configure(timelineColumnBuilder);
			timelineColumnBuilder.Run();
		}
	}
	/// <summary>
	///     <para xml:lang="en">Fluently queues the registrations performed by <see cref="T:STS2RitsuLib.Scaffolding.Content.TimelineColumnPackEntry`1" />.</para>
	///     <para xml:lang="zh-CN">以流式方式排入 <see cref="T:STS2RitsuLib.Scaffolding.Content.TimelineColumnPackEntry`1" /> 要执行的注册操作。</para>
	/// </summary>
	public sealed class TimelineColumnBuilder<TStory> where TStory : StoryModel, new()
	{
		private readonly ModContentPackContext _context;

		private readonly List<Action> _steps = new List<Action>();

		internal TimelineColumnBuilder(ModContentPackContext context)
		{
			_context = context;
		}

		internal void Run()
		{
			Logger logger = RitsuLibFramework.CreateLogger(_context.ModId, (LogType)0);
			for (int i = 0; i < _steps.Count; i++)
			{
				try
				{
					_steps[i]();
				}
				catch (Exception ex)
				{
					string text = $"timeline column '{typeof(TStory).FullName}' step {i + 1} of {_steps.Count}";
					RegistrationFreezeDiagnostics.RecordFailure("ContentPack", _context.ModId, text, ex);
					logger.ErrorNoTrace($"[ContentPack] Failed {text} for mod '{_context.ModId}': {ex.GetType().Name}: {ex.Message}");
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Queues optional slot and unlock configuration, then registers <typeparamref name="TEpoch" /> in this story
		///         column. For <see cref="T:STS2RitsuLib.Timeline.Scaffolding.ModEpochTemplate" /> epochs, register a timeline layout before the timeline freezes,
		///         normally through <paramref name="slot" />; conflicts with base-game layout are reported during application.
		///         Operations run in call order, and a later epoch requirement for the same model replaces an earlier one.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         先排入可选的槽位和解锁配置，再将 <typeparamref name="TEpoch" /> 注册到此故事列。对于
		///         <see cref="T:STS2RitsuLib.Timeline.Scaffolding.ModEpochTemplate" /> 纪元，必须在时间线冻结前注册布局，通常应通过
		///         <paramref name="slot" /> 完成；与游戏本体布局冲突会在应用时报告。操作按调用顺序执行，
		///         同一模型后续的纪元要求会替代较早的要求。
		///     </para>
		/// </summary>
		public TimelineColumnBuilder<TStory> Epoch<TEpoch>(Action<EpochSlotBuilder<TEpoch>>? slot = null) where TEpoch : EpochModel, new()
		{
			if (slot != null)
			{
				EpochSlotBuilder<TEpoch> epochSlotBuilder = new EpochSlotBuilder<TEpoch>(_context);
				slot(epochSlotBuilder);
				foreach (Action item in epochSlotBuilder.DrainSteps())
				{
					_steps.Add(item);
				}
			}
			_steps.Add(delegate
			{
				_context.Timeline.RegisterStoryEpoch<TStory, TEpoch>();
			});
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Queues <typeparamref name="TStory" /> for base-game story discovery; call it once at the end of
		///         the column.
		///     </para>
		///     <para xml:lang="zh-CN">排入 <typeparamref name="TStory" /> 的游戏本体故事发现注册；应在列末尾调用一次。</para>
		/// </summary>
		public TimelineColumnBuilder<TStory> RegisterStory()
		{
			_steps.Add(delegate
			{
				_context.Timeline.RegisterStory<TStory>();
			});
			return this;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Configures timeline placement, axis icons, and unlock bindings for one epoch callback.</para>
	///     <para xml:lang="zh-CN">为一个纪元回调配置时间线位置、轴图标和解锁绑定。</para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         You can call these methods multiple times inside one epoch slot; they run in order. A later
	///         <c>RequireEpoch</c> for the same model replaces the earlier epoch binding.
	///         Content registered through <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.RequireEpoch(System.Type,System.String)" /> is gated by
	///         <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.FilterUnlocked``1(System.Collections.Generic.IEnumerable{``0},MegaCrit.Sts2.Core.Unlocks.UnlockState)" /> /
	///         <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.IsUnlocked(MegaCrit.Sts2.Core.Models.AbstractModel,MegaCrit.Sts2.Core.Unlocks.UnlockState)" />. Integrations include
	///         <see cref="T:STS2RitsuLib.Unlocks.Patches.CharacterUnlockFilterPatch" />, <see cref="T:STS2RitsuLib.Unlocks.Patches.SharedAncientUnlockFilterPatch" />,
	///         <see cref="T:STS2RitsuLib.Unlocks.Patches.CardUnlockFilterPatch" />, <see cref="T:STS2RitsuLib.Unlocks.Patches.RelicUnlockFilterPatch" />,
	///         <see cref="T:STS2RitsuLib.Unlocks.Patches.PotionUnlockFilterPatch" />, and <see cref="T:STS2RitsuLib.Unlocks.Patches.GeneratedRoomEventUnlockFilterPatch" />.
	///         <list type="bullet">
	///             <item>
	///                 Cards · gate an entire pool behind this epoch: <c>RequireAllCardsInPool&lt;TCardPool&gt;()</c> (only
	///                 <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.RequireEpoch(System.Type,System.String)" />; does not register
	///                 <see cref="T:STS2RitsuLib.Timeline.ModEpochGatedContentRegistry" />).
	///             </item>
	///             <item>
	///                 Cards · explicit list + pack-declared unlock UI: <c>Cards(types)</c>; whole pool into the registry:
	///                 <c>CardsFromPool&lt;TCardPool&gt;()</c>.
	///             </item>
	///             <item>
	///                 Relics · whole pool: <c>RequireAllRelicsInPool&lt;TRelicPool&gt;()</c>.
	///             </item>
	///             <item>
	///                 Relics · explicit types or pool + registry: <c>Relics(types)</c>,
	///                 <c>RelicsFromPool&lt;TRelicPool&gt;()</c>.
	///             </item>
	///             <item>
	///                 Potions · whole pool: <c>RequireAllPotionsInPool&lt;TPotionPool&gt;()</c> (<c>RequireEpoch</c> only;
	///                 does
	///                 not register <see cref="T:STS2RitsuLib.Timeline.ModEpochGatedContentRegistry" />).
	///             </item>
	///             <item>
	///                 Potions · explicit types: <c>Potions(types)</c>. For timeline potion presentation, subclass
	///                 <see cref="T:STS2RitsuLib.Timeline.Scaffolding.PotionUnlockEpochTemplate" /> for your <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochModel" /> and implement
	///                 <c>PotionTypes</c>; keep those CLR types aligned with <c>Potions</c> / <c>RequireEpoch</c> (this
	///                 method already applies <c>RequireEpoch</c>).
	///             </item>
	///         </list>
	///     </para>
	///     <para xml:lang="zh-CN">
	///         可以在一个纪元槽位内多次调用这些方法；它们会按顺序运行。后续针对同一模型的
	///         <c>RequireEpoch</c> 会替换较早的纪元绑定。
	///         通过 <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.RequireEpoch(System.Type,System.String)" /> 注册的内容，会受到
	///         <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.FilterUnlocked``1(System.Collections.Generic.IEnumerable{``0},MegaCrit.Sts2.Core.Unlocks.UnlockState)" /> /
	///         <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.IsUnlocked(MegaCrit.Sts2.Core.Models.AbstractModel,MegaCrit.Sts2.Core.Unlocks.UnlockState)" /> 门控。集成点包括
	///         <see cref="T:STS2RitsuLib.Unlocks.Patches.CharacterUnlockFilterPatch" />、<see cref="T:STS2RitsuLib.Unlocks.Patches.SharedAncientUnlockFilterPatch" />、
	///         <see cref="T:STS2RitsuLib.Unlocks.Patches.CardUnlockFilterPatch" />、<see cref="T:STS2RitsuLib.Unlocks.Patches.RelicUnlockFilterPatch" />、
	///         <see cref="T:STS2RitsuLib.Unlocks.Patches.PotionUnlockFilterPatch" /> 和 <see cref="T:STS2RitsuLib.Unlocks.Patches.GeneratedRoomEventUnlockFilterPatch" />。
	///         <list type="bullet">
	///             <item>
	///                 卡牌 · 将整个池门控在此纪元之后：<c>RequireAllCardsInPool&lt;TCardPool&gt;()</c>（仅注册
	///                 <see cref="M:STS2RitsuLib.Unlocks.ModUnlockRegistry.RequireEpoch(System.Type,System.String)" />；不会注册
	///                 <see cref="T:STS2RitsuLib.Timeline.ModEpochGatedContentRegistry" />）。
	///             </item>
	///             <item>
	///                 卡牌 · 显式列表加包声明的解锁界面：<c>Cards(types)</c>；将整个池加入注册表：
	///                 <c>CardsFromPool&lt;TCardPool&gt;()</c>。
	///             </item>
	///             <item>
	///                 遗物 · 整个池：<c>RequireAllRelicsInPool&lt;TRelicPool&gt;()</c>。
	///             </item>
	///             <item>
	///                 遗物 · 显式类型或池加注册表：<c>Relics(types)</c>、
	///                 <c>RelicsFromPool&lt;TRelicPool&gt;()</c>。
	///             </item>
	///             <item>
	///                 药水 · 整个池：<c>RequireAllPotionsInPool&lt;TPotionPool&gt;()</c>（仅应用 <c>RequireEpoch</c>；
	///                 不注册 <see cref="T:STS2RitsuLib.Timeline.ModEpochGatedContentRegistry" />）。
	///             </item>
	///             <item>
	///                 药水 · 显式类型：<c>Potions(types)</c>。如需时间线药水表现，请为你的
	///                 <see cref="T:MegaCrit.Sts2.Core.Timeline.EpochModel" /> 派生 <see cref="T:STS2RitsuLib.Timeline.Scaffolding.PotionUnlockEpochTemplate" /> 并实现
	///                 <c>PotionTypes</c>；保持这些 CLR 类型与 <c>Potions</c> / <c>RequireEpoch</c> 对齐（此方法已
