				}
				List<string> bgLayers = SelectRandomBackgroundLayers(rng, dictionary);
				string fgLayer = rng.NextItem<string>((IEnumerable<string>)new global::<>z__ReadOnlyArray<string>(list.ToArray()));
				return CombatBackgroundAssetsFactory.Construct(mainBackgroundScenePath, bgLayers, fgLayer);
			}
			finally
			{
				((IDisposable)val)?.Dispose();
			}
		}

		private static List<string> SelectRandomBackgroundLayers(Rng rng, Dictionary<string, List<string>> bgLayers)
		{
			return (from kv in bgLayers.OrderBy<KeyValuePair<string, List<string>>, string>((KeyValuePair<string, List<string>> k) => k.Key, StringComparer.Ordinal)
				select rng.NextItem<string>((IEnumerable<string>)kv.Value) into item
				select (item)).ToList();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Allows mod acts to generate background assets from a custom <c>res://</c> layer directory.
	///     </para>
	///     <para xml:lang="zh-CN">允许模组章节从自定义 <c>res://</c> 图层目录生成背景资源。</para>
	/// </summary>
	internal class ActGenerateBackgroundAssetsPatch : IPatchMethod
	{
		public static string PatchId => "content_asset_override_act_generate_background_assets";

		public static string Description => "Allow mod acts to build BackgroundAssets from a custom layers directory";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ActModel), "GenerateBackgroundAssets")
			};
		}

		public static bool Prefix(ActModel __instance, Rng rng, ref BackgroundAssets __result)
		{
			if (!(__instance is IModActAssetOverrides modActAssetOverrides))
			{
				return true;
			}
			string customBackgroundLayersDirectoryPath = modActAssetOverrides.CustomBackgroundLayersDirectoryPath;
			if (string.IsNullOrWhiteSpace(customBackgroundLayersDirectoryPath))
			{
				return true;
			}
			string text = customBackgroundLayersDirectoryPath.TrimEnd('/');
			DirAccess val = DirAccess.Open(text);
			try
			{
				if (val == null)
				{
					RitsuLibFramework.Logger.Warn($"[Assets] Mod act '{((AbstractModel)__instance).Id.Entry}' CustomBackgroundLayersDirectoryPath does not open: '{text}'. " + "Falling back to vanilla layers path.", 1);
					return true;
				}
			}
			finally
			{
				((IDisposable)val)?.Dispose();
			}
			try
			{
				__result = ActBackgroundLayersFactory.CreateFromCustomLayersDirectory(text, __instance.BackgroundScenePath, rng);
				return false;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[Assets] Mod act '{((AbstractModel)__instance).Id.Entry}' custom background layers failed ({ex.GetType().Name}: {ex.Message}). " + "Falling back to vanilla layers path.", 1);
				return true;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Adds every <c>.tscn</c> file in the custom layer directory to <see cref="P:MegaCrit.Sts2.Core.Models.ActModel.AssetPaths" /> for
	///         preloading.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将自定义图层目录中的所有 <c>.tscn</c> 文件添加到 <see cref="P:MegaCrit.Sts2.Core.Models.ActModel.AssetPaths" />，以供预加载。
	///     </para>
	/// </summary>
	internal class ActAssetPathsBackgroundLayersPatch : IPatchMethod
	{
		public static string PatchId => "content_asset_override_act_asset_paths_background_layers";

		public static string Description => "Include custom act layer scenes in ActModel.AssetPaths";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ActModel), "AssetPaths", (MethodType)1)
			};
		}

		public static void Postfix(ActModel __instance, ref IEnumerable<string> __result)
		{
			//IL_0038: Unknown result type (might be due to invalid IL or missing references)
			if (!(__instance is IModActAssetOverrides modActAssetOverrides))
			{
				return;
			}
			string customBackgroundLayersDirectoryPath = modActAssetOverrides.CustomBackgroundLayersDirectoryPath;
			if (string.IsNullOrWhiteSpace(customBackgroundLayersDirectoryPath))
			{
				return;
			}
			string text = customBackgroundLayersDirectoryPath.TrimEnd('/');
			DirAccess val = DirAccess.Open(text);
			try
			{
				if (val == null)
				{
					return;
				}
				List<string> list = new List<string>();
				val.ListDirBegin();
				string next = val.GetNext();
				while (next != "")
				{
					if (!val.CurrentIsDir() && next.EndsWith(".tscn", StringComparison.OrdinalIgnoreCase))
					{
						list.Add(text + "/" + next);
					}
					next = val.GetNext();
				}
				if (list.Count != 0)
				{
					__result = __result.Concat(list);
				}
			}
			finally
			{
				((IDisposable)val)?.Dispose();
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Appends registered mod options to an <see cref="T:MegaCrit.Sts2.Core.Models.AncientEventModel" /> after the base game generates its
	///         initial options.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在原版游戏生成 <see cref="T:MegaCrit.Sts2.Core.Models.AncientEventModel" /> 的初始选项后，追加已注册的模组选项。
	///     </para>
	/// </summary>
	internal class AncientEventInitialOptionsRegistryPatch : IPatchMethod
	{
		private static readonly MethodInfo RelicOptionMethod = typeof(AncientEventModel).GetMethods(BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.NonPublic).Single(delegate(MethodInfo method)
		{
			if (method.Name != "RelicOption" || method.IsGenericMethodDefinition)
			{
				return false;
			}
			ParameterInfo[] parameters = method.GetParameters();
			return parameters.Length == 3 && parameters[0].ParameterType == typeof(RelicModel) && parameters[1].ParameterType == typeof(string) && parameters[2].ParameterType == typeof(string);
		});

		public static string PatchId => "ancient_event_initial_options_registry";

		public static string Description => "Append ModAncientOptionRegistry results into AncientEventModel initial option list";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(AncientEventModel), "GenerateInitialOptionsWrapper")
			};
		}

		public static void Postfix(AncientEventModel __instance, ref IReadOnlyList<EventOption> __result)
		{
			ReplaceDebugRelicOptionWithPreparedOption(__instance, ref __result);
			if (!ShouldSkipInjection(__result))
			{
				List<EventOption> list = (__result as List<EventOption>) ?? __result.ToList();
				int count = list.Count;
				ModAncientOptionRegistry.AppendRegisteredOptions(__instance, list);
				if (list.Count != count)
				{
					GeneratedOptions(__instance) = list;
					__result = list;
				}
			}
		}

		private static bool ShouldSkipInjection(IReadOnlyList<EventOption> options)
		{
			if (options.Count != 1)
			{
				return false;
			}
			EventOption val = options[0];
			if (val.IsProceed)
			{
				return string.Equals(val.TextKey, "PROCEED", StringComparison.OrdinalIgnoreCase);
			}
			return false;
		}

		private static void ReplaceDebugRelicOptionWithPreparedOption(AncientEventModel ancient, ref IReadOnlyList<EventOption> options)
		{
			if (!string.IsNullOrWhiteSpace(ancient.DebugOption) && options.Count != 0)
			{
				EventOption val = options[0];
				if (val.Relic != null && TextKeyMatchesDebugOption(val.TextKey, ancient.DebugOption) && TryPrepareDebugRelicOption(ancient, val.Relic, out RelicModel preparedRelic))
				{
					EventOption value = CreateRelicOption(ancient, preparedRelic);
					List<EventOption> list = (options as List<EventOption>) ?? options.ToList();
					list[0] = value;
					GeneratedOptions(ancient) = list;
					options = list;
				}
			}
		}

		private static bool TextKeyMatchesDebugOption(string textKey, string debugOption)
		{
			return textKey.Contains(debugOption, StringComparison.OrdinalIgnoreCase);
		}

		private static bool TryPrepareDebugRelicOption(AncientEventModel ancient, RelicModel sourceRelic, out RelicModel preparedRelic)
		{
			preparedRelic = sourceRelic;
			Player owner = ((EventModel)ancient).Owner;
			if (owner == null)
			{
				return false;
			}
			MethodInfo method = ((object)sourceRelic).GetType().GetMethod("SetupForPlayer", BindingFlags.Instance | BindingFlags.Public, new Type[1] { typeof(Player) });
			if (method == null)
			{
				return false;
			}
			preparedRelic = (RelicModel)(((AbstractModel)sourceRelic).IsMutable ? ((object)sourceRelic) : ((object)sourceRelic.ToMutable()));
			preparedRelic.Owner = owner;
			try
			{
				object obj = method.Invoke(preparedRelic, new object[1] { owner });
				bool flag = default(bool);
				int num;
				if (obj is bool)
				{
					flag = (bool)obj;
					num = ((1 == 0) ? 1 : 0);
				}
				else
				{
					num = 1;
				}
				return (byte)((uint)num | (flag ? 1u : 0u)) != 0;
			}
			catch (TargetInvocationException ex)
			{
				RitsuLibFramework.Logger.Warn($"[AncientOption] Failed to prepare debug relic option '{((AbstractModel)sourceRelic).Id}' for ancient '{((AbstractModel)ancient).Id}': {ex.InnerException ?? ex}", 1);
				return false;
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.Warn($"[AncientOption] Failed to prepare debug relic option '{((AbstractModel)sourceRelic).Id}' for ancient '{((AbstractModel)ancient).Id}': {value}", 1);
				return false;
			}
		}

		private static EventOption CreateRelicOption(AncientEventModel ancient, RelicModel relic)
		{
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0023: Expected O, but got Unknown
			return (EventOption)RelicOptionMethod.Invoke(ancient, new object[3] { relic, "INITIAL", null });
		}

		[UnsafeAccessor(UnsafeAccessorKind.Field, Name = "_generatedOptions")]
		private static extern ref List<EventOption>? GeneratedOptions(AncientEventModel instance);
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Supplies a minimal placeholder <see cref="T:Godot.PackedScene" /> for Ancient events that use
	///         <see cref="P:STS2RitsuLib.Scaffolding.Content.AncientEventPresentationAssetProfile.StageProcedural" />, avoiding the need for a background
	///         <c>.tscn</c> file.
