		///     <para xml:lang="zh-CN">先古事件使用程序化舞台图层时，跳过背景场景加载。</para>
		/// </summary>
		[HarmonyPriority(800)]
		public static bool Prefix(EventModel __instance, ref PackedScene __result)
		{
			if (!(__instance is AncientEventModel))
			{
