	/// <summary>
	///     <para xml:lang="en">
	///         Provides externally registered badge icon-path overrides, keyed by provider registration key.
	///     </para>
	///     <para xml:lang="zh-CN">提供外部注册的徽章图标路径覆盖，并按提供器注册键索引。</para>
	/// </summary>
	public static class ExternalBadgeIconOverrideRegistry
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, Func<string, string?>> IconPathProviders = new Dictionary<string, Func<string, string>>(StringComparer.OrdinalIgnoreCase);

		/// <summary>
		///     <para xml:lang="en">Registers or replaces an icon-path provider.</para>
		///     <para xml:lang="zh-CN">注册或替换图标路径提供器。</para>
		/// </summary>
		public static void RegisterIconPathProvider(string key, Func<string, string?> provider)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			ArgumentNullException.ThrowIfNull(provider, "provider");
			using (SyncRoot.EnterScope())
			{
				IconPathProviders[key] = provider;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Removes the provider with the specified registration key.</para>
		///     <para xml:lang="zh-CN">移除具有指定注册键的提供器。</para>
		/// </summary>
		public static bool UnregisterIconPathProvider(string key)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			using (SyncRoot.EnterScope())
			{
				return IconPathProviders.Remove(key);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Removes all registered providers.</para>
		///     <para xml:lang="zh-CN">移除所有已注册的提供器。</para>
		/// </summary>
		public static void Clear()
		{
			using (SyncRoot.EnterScope())
			{
				IconPathProviders.Clear();
			}
		}

		internal static bool TryGetIconPath(string badgeId, [NotNullWhen(true)] out string? iconPath)
		{
			KeyValuePair<string, Func<string, string>>[] array = Snapshot();
			for (int i = 0; i < array.Length; i++)
			{
				KeyValuePair<string, Func<string, string>> keyValuePair = array[i];
				string text;
				try
				{
					text = keyValuePair.Value(badgeId);
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[Assets] Badge icon provider '{keyValuePair.Key}' failed for '{badgeId}': {ex.Message}", 1);
					continue;
				}
				if (!string.IsNullOrWhiteSpace(text))
				{
					iconPath = text;
					return true;
				}
			}
			iconPath = string.Empty;
			return false;
		}

		private static KeyValuePair<string, Func<string, string?>>[] Snapshot()
		{
			using (SyncRoot.EnterScope())
			{
				return IconPathProviders.ToArray();
			}
		}
	}
	internal static class ModBadgeRegistry
	{
		private static readonly Lock SyncRoot = new Lock();

		private static List<Type> _badgeTypes = new List<Type>();

		internal static IReadOnlyList<Type> GetRegisteredBadgeTypes()
		{
			using (SyncRoot.EnterScope())
			{
				_badgeTypes = ModContentRegistry.GetRegisteredBadgeTypes().ToList();
				return new global::<>z__ReadOnlyArray<Type>(_badgeTypes.ToArray());
			}
		}

		internal static bool TryGetBadgeTemplateByRegistrationId(string id, out ModBadgeTemplate template)
		{
			foreach (Type registeredBadgeType in GetRegisteredBadgeTypes())
			{
				ModBadgeTemplate modBadgeTemplate = CreateTemplateInstance(registeredBadgeType);
				if (modBadgeTemplate != null && string.Equals(modBadgeTemplate.Id, id, StringComparison.OrdinalIgnoreCase))
				{
					template = modBadgeTemplate;
					return true;
				}
			}
			template = null;
			return false;
		}

		internal static ModBadgeTemplate? CreateTemplateInstance(Type type)
		{
			try
			{
				return Activator.CreateInstance(type, nonPublic: true) as ModBadgeTemplate;
			}
			catch
			{
				return null;
			}
		}
	}
