	internal class NBadgeCreateIconPatch : IPatchMethod
	{
		public static string PatchId => "content_asset_override_nbadge_create_icon";

		public static string Description => "Apply mod badge icon overrides for NBadge.Create";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NBadge), "Create", new Type[2]
				{
					typeof(string),
					typeof(BadgeRarity)
				}, ignoreIfMissing: true)
			};
		}

		public static void Postfix(NBadge __result, string id)
		{
			if (__result != null && !string.IsNullOrWhiteSpace(id) && TryResolveCustomIconPath(id, out string iconPath) && ResourceLoader.Exists(iconPath, ""))
			{
				Texture2D val = ResourceLoader.Load<Texture2D>(iconPath, (string)null, (CacheMode)1);
				if (val != null)
				{
					((Node)__result).GetNode<TextureRect>(NodePath.op_Implicit("%Icon")).Texture = val;
				}
			}
		}

		private static bool TryResolveCustomIconPath(string badgeId, [NotNullWhen(true)] out string? iconPath)
		{
			if (ExternalBadgeIconOverrideRegistry.TryGetIconPath(badgeId, out iconPath))
			{
				return true;
			}
			if (!ModBadgeRegistry.TryGetBadgeTemplateByRegistrationId(badgeId, out ModBadgeTemplate template) || string.IsNullOrWhiteSpace(template.CustomBadgeIconPath))
			{
				iconPath = string.Empty;
				return false;
			}
			iconPath = template.CustomBadgeIconPath;
			return true;
		}
