	internal class BadgeIconGetterPatch : IPatchMethod
	{
		public static string PatchId => "content_asset_override_badge_icon_getter";

		public static string Description => "Allow runtime mod badges to override BadgeIcon texture";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(Badge), "BadgeIcon", null, IgnoreIfMissing: true, (MethodType)1)
			};
		}

		public static bool Prefix(Badge __instance, ref Texture2D __result)
		{
			if (!TryResolveCustomIconPath(__instance, out string iconPath))
			{
				return true;
			}
			if (!ResourceLoader.Exists(iconPath, ""))
			{
				return true;
			}
			Texture2D val = ResourceLoader.Load<Texture2D>(iconPath, (string)null, (CacheMode)1);
			if (val == null)
			{
				return true;
			}
			__result = val;
			return false;
		}

		private static bool TryResolveCustomIconPath(Badge badge, [NotNullWhen(true)] out string? iconPath)
		{
			if (ExternalBadgeIconOverrideRegistry.TryGetIconPath(badge.Id, out iconPath))
			{
				return true;
			}
			if (!(badge is RuntimeTemplateBadge runtimeTemplateBadge) || string.IsNullOrWhiteSpace(runtimeTemplateBadge.Template.CustomBadgeIconPath))
			{
				iconPath = string.Empty;
				return false;
			}
			iconPath = runtimeTemplateBadge.Template.CustomBadgeIconPath;
			return true;
		}
	}
