		public static void Postfix(NDeckViewScreen __instance)
		{
			Player val = PlayerRef.Invoke(__instance);
			CharacterModel character = val.Character;
			CardPoolModel cardPool = character.CardPool;
			if (CardPoolDeckViewStyleRegistry.TryGetStyle(cardPool, out CardPoolDeckViewStyle style))
			{
				CardPoolDeckViewStyleContext context = new CardPoolDeckViewStyleContext(val, character, cardPool, __instance);
				ApplyToolbarBackground(__instance, cardPool, style, context);
				ApplySortButtons(__instance, cardPool, style, context);
				ApplyUpgradeLabel(__instance, style);
			}
		}

		private static void ApplyToolbarBackground(NDeckViewScreen screen, CardPoolModel cardPool, CardPoolDeckViewStyle style, CardPoolDeckViewStyleContext context)
		{
			Control nodeOrNull = ((Node)screen).GetNodeOrNull<Control>(NodePath.op_Implicit("%SortingBg"));
			if (nodeOrNull != null)
			{
				if (!string.IsNullOrWhiteSpace(style.ToolbarBackgroundTexturePath))
				{
					ApplyToolbarBackgroundTexture(nodeOrNull, cardPool, style.ToolbarBackgroundTexturePath);
				}
				Material val = ResolveToolbarBackgroundMaterial(cardPool, style, context);
				if (val != null)
				{
					((CanvasItem)nodeOrNull).Material = val;
				}
			}
		}

		private static void ApplyToolbarBackgroundTexture(Control background, CardPoolModel cardPool, string path)
		{
			TextureRect val = (TextureRect)(object)((background is TextureRect) ? background : null);
			if (val == null)
			{
				RitsuLibFramework.Logger.Warn("[Assets] Deck-view toolbar background for '" + ((object)cardPool).GetType().Name + "' is not a TextureRect; texture override skipped.", 1);
				return;
			}
			try
			{
				val.Texture = PreloadManager.Cache.GetAsset<Texture2D>(path);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[Assets] Could not load deck-view toolbar background texture '{path}' for '{((object)cardPool).GetType().Name}': {ex.Message}", 1);
			}
		}

		private static void ApplySortButtons(NDeckViewScreen screen, CardPoolModel cardPool, CardPoolDeckViewStyle style, CardPoolDeckViewStyleContext context)
		{
			string[] array = new string[4] { "%ObtainedSorter", "%CardTypeSorter", "%CostSorter", "%AlphabeticalSorter" };
			foreach (string text in array)
			{
				NCardViewSortButton nodeOrNull = ((Node)screen).GetNodeOrNull<NCardViewSortButton>(NodePath.op_Implicit(text));
				if (nodeOrNull != null)
				{
					ApplySortButtonBackground(nodeOrNull, cardPool, style, context);
					ApplySortButtonHue(nodeOrNull, cardPool, style, context);
				}
			}
		}

		private static void ApplySortButtonBackground(NCardViewSortButton button, CardPoolModel cardPool, CardPoolDeckViewStyle style, CardPoolDeckViewStyleContext context)
		{
			if (string.IsNullOrWhiteSpace(style.SortButtonBackgroundTexturePath) && style.SortButtonBackgroundMaterial == null && style.SortButtonBackgroundMaterialProvider == null)
			{
				return;
			}
			TextureRect nodeOrNull = ((Node)button).GetNodeOrNull<TextureRect>(NodePath.op_Implicit("%ButtonImage"));
			if (nodeOrNull == null)
			{
				return;
			}
			if (!string.IsNullOrWhiteSpace(style.SortButtonBackgroundTexturePath))
			{
				try
				{
					nodeOrNull.Texture = PreloadManager.Cache.GetAsset<Texture2D>(style.SortButtonBackgroundTexturePath);
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[Assets] Could not load deck-view sort button background texture '{style.SortButtonBackgroundTexturePath}' for '{((object)cardPool).GetType().Name}': {ex.Message}", 1);
				}
			}
			Material val = ResolveSortButtonBackgroundMaterial(cardPool, style, context);
			if (val != null)
			{
				((CanvasItem)nodeOrNull).Material = val;
			}
		}

		private static void ApplySortButtonHue(NCardViewSortButton button, CardPoolModel cardPool, CardPoolDeckViewStyle style, CardPoolDeckViewStyleContext context)
		{
			if (style.DisableSortButtonHue != true)
			{
				ShaderMaterial val = ResolveSortButtonHueMaterial(cardPool, style, context);
				if (val != null)
				{
					button.SetHue(val);
				}
			}
		}

		private static void ApplyUpgradeLabel(NDeckViewScreen screen, CardPoolDeckViewStyle style)
		{
			//IL_0027: Unknown result type (might be due to invalid IL or missing references)
			//IL_002c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0038: Unknown result type (might be due to invalid IL or missing references)
			//IL_0050: Unknown result type (might be due to invalid IL or missing references)
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
