			MegaLabel nodeOrNull = ((Node)screen).GetNodeOrNull<MegaLabel>(NodePath.op_Implicit("%ViewUpgradesLabel"));
			if (nodeOrNull != null)
			{
				Color? upgradePreviewLabelColor = style.UpgradePreviewLabelColor;
				if (upgradePreviewLabelColor.HasValue)
				{
					Color valueOrDefault = upgradePreviewLabelColor.GetValueOrDefault();
					((Control)nodeOrNull).AddThemeColorOverride(StringName.op_Implicit("font_color"), valueOrDefault);
				}
				upgradePreviewLabelColor = style.UpgradePreviewLabelOutlineColor;
				if (upgradePreviewLabelColor.HasValue)
				{
					Color valueOrDefault2 = upgradePreviewLabelColor.GetValueOrDefault();
					((Control)nodeOrNull).AddThemeColorOverride(StringName.op_Implicit("font_outline_color"), valueOrDefault2);
				}
			}
		}

		private static Material? ResolveToolbarBackgroundMaterial(CardPoolModel cardPool, CardPoolDeckViewStyle style, CardPoolDeckViewStyleContext context)
		{
			if (style.ToolbarBackgroundMaterialProvider == null)
			{
				return GetValidMaterial<Material>(cardPool, style.ToolbarBackgroundMaterial, "ToolbarBackgroundMaterial");
			}
			try
			{
				return GetValidMaterial<Material>(cardPool, style.ToolbarBackgroundMaterialProvider(context), "ToolbarBackgroundMaterialProvider") ?? GetValidMaterial<Material>(cardPool, style.ToolbarBackgroundMaterial, "ToolbarBackgroundMaterial");
			}
