		private static ShaderMaterial ResolveVanillaDeckViewHueMaterial(Material material, NDeckViewScreen screen)
		{
			//IL_00fd: Unknown result type (might be due to invalid IL or missing references)
			//IL_0103: Expected O, but got Unknown
			ShaderMaterial val = (ShaderMaterial)(object)((material is ShaderMaterial) ? material : null);
			if (val != null && GodotObject.IsInstanceValid((GodotObject)(object)val))
			{
				return val;
			}
			CardPoolModel cardPool = PlayerRef.Invoke(screen).Character.CardPool;
			try
			{
				Material material2 = PreloadManager.Cache.GetMaterial("res://materials/cards/frames/card_frame_colorless_mat.tres");
				ShaderMaterial val2 = (ShaderMaterial)(object)((material2 is ShaderMaterial) ? material2 : null);
				if (val2 != null && GodotObject.IsInstanceValid((GodotObject)(object)val2))
				{
					return val2;
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Assets] Could not load safe deck-view hue fallback for '" + ((object)cardPool).GetType().Name + "': " + ex.Message, 1);
			}
			string value = ((material == null || !GodotObject.IsInstanceValid((GodotObject)(object)material)) ? "invalid" : ((object)material).GetType().Name);
			RitsuLibFramework.Logger.Warn($"[Assets] Deck-view frame material for '{((object)cardPool).GetType().Name}' is {value}, not a valid ShaderMaterial. Using an empty ShaderMaterial fallback.", 1);
			return new ShaderMaterial();
		}

		private static TMaterial? GetValidMaterial<TMaterial>(CardPoolModel cardPool, TMaterial? material, string memberName) where TMaterial : Material
		{
			if (material == null)
			{
				return default(TMaterial);
			}
			if (GodotObject.IsInstanceValid((GodotObject)(object)material))
			{
				return material;
			}
			RitsuLibFramework.Logger.Warn($"[Assets] Deck-view style {memberName} returned an invalid {typeof(TMaterial).Name} for '{((object)cardPool).GetType().Name}'. Ignoring it.", 1);
			return default(TMaterial);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides external card-pool deck-view style overrides for pools that cannot implement RitsuLib
	///         interfaces directly, including base-game pools.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为无法直接实现 RitsuLib 接口的卡池（包括原版卡池）提供外部牌组查看界面样式覆盖。
	///     </para>
	/// </summary>
	public static class CardPoolDeckViewStyleRegistry
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, Func<CardPoolModel, CardPoolDeckViewStyle?>> Providers = new Dictionary<string, Func<CardPoolModel, CardPoolDeckViewStyle>>(StringComparer.Ordinal);

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a deck-view style provider.</para>
		///     <para xml:lang="zh-CN">注册或替换牌组查看界面样式提供器。</para>
		/// </summary>
		public static void RegisterProvider(string key, Func<CardPoolModel, CardPoolDeckViewStyle?> provider)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			ArgumentNullException.ThrowIfNull(provider, "provider");
			using (SyncRoot.EnterScope())
			{
				Providers[key] = provider;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Removes a deck-view style provider by key.</para>
		///     <para xml:lang="zh-CN">按键移除牌组查看界面样式提供器。</para>
		/// </summary>
		public static bool UnregisterProvider(string key)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			using (SyncRoot.EnterScope())
			{
				return Providers.Remove(key);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Removes all registered deck-view style providers.</para>
		///     <para xml:lang="zh-CN">移除所有已注册的牌组查看界面样式提供器。</para>
		/// </summary>
		public static void Clear()
		{
			using (SyncRoot.EnterScope())
			{
				Providers.Clear();
			}
		}

		internal static bool TryGetStyle(CardPoolModel pool, out CardPoolDeckViewStyle style)
		{
			if (ModContentRegistry.TryGetEffectiveCardPoolAssetReplacement(((AbstractModel)pool).Id.Entry, out CardPoolAssetProfile assetProfile) && assetProfile.DeckViewStyle != null)
			{
				style = assetProfile.DeckViewStyle;
				return true;
			}
			if (pool is IModCardPoolDeckViewStyle { DeckViewStyle: not null } modCardPoolDeckViewStyle)
			{
				style = modCardPoolDeckViewStyle.DeckViewStyle;
				return true;
			}
			if (pool is IModCardPoolAssetOverrides modCardPoolAssetOverrides)
			{
				CardPoolAssetProfile assetProfile2 = modCardPoolAssetOverrides.AssetProfile;
				if ((object)assetProfile2 != null)
				{
					CardPoolDeckViewStyle deckViewStyle = assetProfile2.DeckViewStyle;
					if ((object)deckViewStyle != null)
					{
						style = deckViewStyle;
						return true;
					}
				}
			}
			Func<CardPoolModel, CardPoolDeckViewStyle>[] array = Snapshot();
			foreach (Func<CardPoolModel, CardPoolDeckViewStyle> func in array)
			{
				CardPoolDeckViewStyle cardPoolDeckViewStyle;
				try
				{
					cardPoolDeckViewStyle = func(pool);
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn("[Assets] Card-pool deck-view style provider failed for '" + ((object)pool).GetType().Name + "': " + ex.Message, 1);
					continue;
				}
				if (!(cardPoolDeckViewStyle == null))
				{
					style = cardPoolDeckViewStyle;
					return true;
				}
			}
			style = null;
			return false;
		}

		private static Func<CardPoolModel, CardPoolDeckViewStyle?>[] Snapshot()
		{
			using (SyncRoot.EnterScope())
			{
				return Providers.Values.ToArray();
			}
		}
	}
