	/// <summary>
	///     <para xml:lang="en">
	///         Applies direct, external, character-owned, and path-based frame-material overrides to
	///         <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将直接、外部、角色所属和基于路径的边框材质覆盖应用到 <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" />。
	///     </para>
	/// </summary>
	internal class CardFrameMaterialPatch : IPatchMethod
	{
		public static string PatchId => "content_asset_override_card_frame_material";

		public static string Description => "Allow mod cards to override card frame materials";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(CardModel), "FrameMaterial", (MethodType)1)
			};
		}

		public static bool Prefix(CardModel __instance, ref Material __result)
		{
			if (!ContentAssetOverridePatchHelper.TryUseDirectMaterialOverride(__instance, ref __result, (IModCardFrameMaterialOverride overrides) => overrides.CustomFrameMaterial, "CustomFrameMaterial"))
			{
				return false;
			}
			if (ExternalCardMaterialOverrideRegistry.TryGetFrameMaterial(__instance, out Material material))
			{
				__result = material;
				return false;
			}
			if (!ModCharacterOwnedVisualOverrideHelper.TryCardFrameMaterial(__instance, ref __result))
			{
				return false;
			}
			return ContentAssetOverridePatchHelper.TryUseMaterialOverride(__instance, ref __result, (IModCardAssetOverrides o) => o.CustomFrameMaterialPath, "CustomFrameMaterialPath");
		}
	}
