	/// <summary>
	///     <para xml:lang="en">
	///         Applies explicit standard or Ancient card visual styles after the base game reloads a card's visuals.
	///     </para>
	///     <para xml:lang="zh-CN">在原版游戏重载卡牌视觉后，应用明确指定的标准或先古卡牌视觉样式。</para>
	/// </summary>
	internal class CardVisualStylePatch : IPatchMethod
	{
		private const string CanvasGroupBlurMaterialPath = "res://scenes/cards/card_canvas_group_blur_material.tres";

		private const string CanvasGroupMaskBlurMaterialPath = "res://scenes/cards/card_canvas_group_mask_blur_material.tres";

		private const string CanvasGroupMaskMaterialPath = "res://scenes/cards/card_canvas_group_mask_material.tres";

		private const string PortraitBlurMaterialPath = "res://scenes/cards/card_portrait_blur_material.tres";

		public static string PatchId => "content_asset_override_card_visual_style";

		public static string Description => "Allow CardAssetProfile to force standard or ancient card visuals";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NCard), "Reload")
			};
		}

		public static void Postfix(NCard __instance)
		{
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_0028: Invalid comparison between Unknown and I4
			CardModel model = __instance.Model;
			if (model != null)
			{
				if (TryResolveVisualStyle(model, out var style))
				{
					ApplyVisualStyle(__instance, model, style == CardVisualStyle.Ancient);
				}
				else if ((int)model.Rarity == 5)
				{
					SetTexture(__instance, NodePath.op_Implicit("%AncientBanner"), ResolveAncientBannerTexture(model));
				}
			}
		}

		internal static bool UsesAncientVisualStyle(CardModel model)
		{
			//IL_000b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0011: Invalid comparison between Unknown and I4
			if (!TryResolveVisualStyle(model, out var style))
			{
				return (int)model.Rarity == 5;
			}
			return style == CardVisualStyle.Ancient;
		}

		private static bool TryResolveVisualStyle(CardModel model, out CardVisualStyle style)
		{
			if (ModCharacterOwnedVisualOverrideHelper.TryCardVisualStyle(model, out style))
			{
				return true;
			}
			if (model is IModCardAssetOverrides { CustomVisualStyle: not CardVisualStyle.Default } modCardAssetOverrides)
			{
				style = modCardAssetOverrides.CustomVisualStyle;
				return true;
			}
			style = CardVisualStyle.Default;
			return false;
		}

		private static void ApplyVisualStyle(NCard card, CardModel model, bool ancient)
		{
			SetVisible(card, NodePath.op_Implicit("%PortraitBorder"), !ancient);
			SetVisible(card, NodePath.op_Implicit("%Portrait"), !ancient);
			SetVisible(card, NodePath.op_Implicit("%Frame"), !ancient);
			SetVisible(card, NodePath.op_Implicit("%AncientPortrait"), ancient);
			SetVisible(card, NodePath.op_Implicit("%AncientBorderGlassOverlay"), ancient);
			SetVisible(card, NodePath.op_Implicit("%AncientBorder"), ancient);
			SetVisible(card, NodePath.op_Implicit("%AncientTextBg"), ancient);
			SetVisible(card, NodePath.op_Implicit("%AncientBanner"), ancient);
			SetVisible(card, NodePath.op_Implicit("%TitleBanner"), !ancient);
			ApplyPortraitCanvasMaterials(card, ancient);
			if (ancient)
			{
				SetTexture(card, NodePath.op_Implicit("%AncientBorder"), ResolveAncientBorderTexture(model));
				SetTexture(card, NodePath.op_Implicit("%AncientTextBg"), ResolveAncientTextBgTexture(model));
				SetTexture(card, NodePath.op_Implicit("%AncientPortrait"), model.Portrait);
				SetTexture(card, NodePath.op_Implicit("%AncientBanner"), ResolveAncientBannerTexture(model));
				SetMaterial(card, NodePath.op_Implicit("%TitleBanner"), null);
			}
			else
			{
				SetTexture(card, NodePath.op_Implicit("%Portrait"), model.Portrait);
				SetTexture(card, NodePath.op_Implicit("%PortraitBorder"), ResolveStandardPortraitBorderTexture(model));
				SetMaterial(card, NodePath.op_Implicit("%PortraitBorder"), ResolveStandardBannerMaterial(model));
				SetTexture(card, NodePath.op_Implicit("%Frame"), ResolveStandardFrameTexture(model));
				SetMaterial(card, NodePath.op_Implicit("%Frame"), model.FrameMaterial);
				SetTexture(card, NodePath.op_Implicit("%TitleBanner"), ResolveStandardBannerTexture());
				SetMaterial(card, NodePath.op_Implicit("%TitleBanner"), ResolveStandardBannerMaterial(model));
			}
		}

		private static void ApplyPortraitCanvasMaterials(NCard card, bool ancient)
		{
			//IL_0034: Unknown result type (might be due to invalid IL or missing references)
			//IL_003a: Invalid comparison between Unknown and I4
			CanvasItem nodeOrNull = ((Node)card).GetNodeOrNull<CanvasItem>(NodePath.op_Implicit("%PortraitCanvasGroup"));
			CanvasItem nodeOrNull2 = ((Node)card).GetNodeOrNull<CanvasItem>(NodePath.op_Implicit("%Portrait"));
			CanvasItem nodeOrNull3 = ((Node)card).GetNodeOrNull<CanvasItem>(NodePath.op_Implicit("%AncientPortrait"));
			if ((int)card.Visibility != 1)
			{
				if (nodeOrNull != null)
				{
					nodeOrNull.Material = LoadMaterial(ancient ? "res://scenes/cards/card_canvas_group_mask_blur_material.tres" : "res://scenes/cards/card_canvas_group_blur_material.tres");
				}
				Material material = LoadMaterial("res://scenes/cards/card_portrait_blur_material.tres");
				if (nodeOrNull2 != null)
				{
					nodeOrNull2.Material = material;
				}
				if (nodeOrNull3 != null)
				{
					nodeOrNull3.Material = material;
				}
			}
			else
			{
				if (nodeOrNull != null)
				{
					nodeOrNull.Material = (ancient ? LoadMaterial("res://scenes/cards/card_canvas_group_mask_material.tres") : null);
				}
				if (nodeOrNull2 != null)
				{
					nodeOrNull2.Material = null;
				}
				if (nodeOrNull3 != null)
				{
					nodeOrNull3.Material = null;
				}
			}
		}

		private static Texture2D ResolveAncientBorderTexture(CardModel model)
		{
			Texture2D result = null;
			if (!CardTextureOverridePatch.TryCardAncientBorderTexture(model, ref result))
			{
				return result;
			}
			return model.AncientBorder;
		}

		private static Texture2D ResolveAncientTextBgTexture(CardModel model)
		{
			//IL_000f: Unknown result type (might be due to invalid IL or missing references)
			Texture2D result = null;
			if (!CardTextureOverridePatch.TryCardAncientTextBgTexture(model, ref result))
			{
				return result;
			}
			return LoadTexture(AncientTextBgPath(model.Type));
		}

		private static Texture2D ResolveAncientBannerTexture(CardModel model)
		{
			Texture2D result = null;
			if (!ModCharacterOwnedVisualOverrideHelper.TryCardAncientBannerTexture(model, ref result) || !ContentAssetOverridePatchHelper.TryUseTextureOverride(model, ref result, (IModCardAssetOverrides o) => o.CustomAncientBannerPath, "CustomAncientBannerPath"))
			{
				return result;
			}
			return LoadTexture(ImageHelper.GetImagePath("atlases/ui_atlas.sprites/card/ancient_banner.tres"));
		}

		private static Texture2D ResolveStandardFrameTexture(CardModel model)
		{
			//IL_000f: Unknown result type (might be due to invalid IL or missing references)
			Texture2D result = null;
			if (!CardTextureOverridePatch.TryCardFrameTexture(model, ref result))
			{
				return result;
			}
			return LoadTexture(StandardFramePath(model.Type));
		}

		private static Texture2D ResolveStandardPortraitBorderTexture(CardModel model)
		{
			//IL_000f: Unknown result type (might be due to invalid IL or missing references)
			Texture2D result = null;
			if (!CardTextureOverridePatch.TryCardPortraitBorderTexture(model, ref result))
			{
				return result;
			}
