		}

		private static Texture2D ResolveStandardBannerTexture()
		{
			return LoadTexture(ImageHelper.GetImagePath("atlases/ui_atlas.sprites/card/card_banner.tres"));
		}

		private static Material ResolveStandardBannerMaterial(CardModel model)
		{
			//IL_0079: Unknown result type (might be due to invalid IL or missing references)
			Material __result = null;
			if (!ContentAssetOverridePatchHelper.TryUseDirectMaterialOverride(model, ref __result, (IModCardBannerMaterialOverride overrides) => overrides.CustomBannerMaterial, "CustomBannerMaterial"))
			{
				return __result;
			}
			if (ExternalCardMaterialOverrideRegistry.TryGetBannerMaterial(model, out Material material))
			{
				return material;
			}
			if (!ModCharacterOwnedVisualOverrideHelper.TryCardBannerMaterial(model, ref __result) || !ContentAssetOverridePatchHelper.TryUseMaterialOverride(model, ref __result, (IModCardAssetOverrides o) => o.CustomBannerMaterialPath, "CustomBannerMaterialPath"))
			{
				return __result;
			}
			return LoadMaterial(StandardBannerMaterialPath(model.Rarity));
		}

		private static string StandardFramePath(CardType type)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			string text = Normalize(StandardFrameCardType(type));
			return ImageHelper.GetImagePath("atlases/ui_atlas.sprites/card/card_frame_" + text + "_s.tres");
		}

		private static string StandardPortraitBorderPath(CardType type)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			string text = Normalize(StandardPortraitBorderCardType(type));
			return ImageHelper.GetImagePath("atlases/ui_atlas.sprites/card/card_portrait_border_" + text + "_s.tres");
		}

		private static string AncientTextBgPath(CardType type)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			string text = Normalize(AncientTextBgCardType(type));
			return ImageHelper.GetImagePath("atlases/compressed_atlas.sprites/ancient_text_bg_" + text + ".png.tres");
		}

		private static string StandardBannerMaterialPath(CardRarity rarity)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0002: Unknown result type (might be due to invalid IL or missing references)
			//IL_0028: Expected I4, but got Unknown
			return (rarity - 3) switch
			{
				0 => "res://materials/cards/banners/card_banner_uncommon_mat.tres", 
				1 => "res://materials/cards/banners/card_banner_rare_mat.tres", 
				6 => "res://materials/cards/banners/card_banner_curse_mat.tres", 
				5 => "res://materials/cards/banners/card_banner_status_mat.tres", 
				3 => "res://materials/cards/banners/card_banner_event_mat.tres", 
				7 => "res://materials/cards/banners/card_banner_quest_mat.tres", 
				_ => "res://materials/cards/banners/card_banner_common_mat.tres", 
			};
		}

		private static CardType StandardFrameCardType(CardType type)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0002: Unknown result type (might be due to invalid IL or missing references)
