	/// <summary>
	///     <para xml:lang="en">
	///         Applies custom card-portrait <see cref="T:Godot.Material" /> overrides after <see cref="T:MegaCrit.Sts2.Core.Nodes.Cards.NCard" /> reloads its
	///         base-game visuals.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在 <see cref="T:MegaCrit.Sts2.Core.Nodes.Cards.NCard" /> 重载原版视觉后，应用自定义卡图 <see cref="T:Godot.Material" /> 覆盖。
	///     </para>
	/// </summary>
	internal class CardPortraitMaterialPatch : IPatchMethod
	{
		public static string PatchId => "content_asset_override_card_portrait_material";

		public static string Description => "Allow mod cards to override the NCard portrait material";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NCard), "Reload")
			};
		}

		public static void Postfix(NCard __instance)
		{
			//IL_000b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0011: Invalid comparison between Unknown and I4
			CardModel model = __instance.Model;
			if (model != null && (int)__instance.Visibility == 1 && TryGetPortraitMaterial(model, out Material material))
			{
				TextureRect portraitNode = GetPortraitNode(__instance, model);
				if (portraitNode != null)
				{
					((CanvasItem)portraitNode).Material = material;
				}
			}
		}

		private static TextureRect? GetPortraitNode(NCard card, CardModel model)
		{
			string text = (CardVisualStylePatch.UsesAncientVisualStyle(model) ? "%AncientPortrait" : "%Portrait");
			return ((Node)card).GetNodeOrNull<TextureRect>(NodePath.op_Implicit(text));
		}

		private static bool TryGetPortraitMaterial(CardModel card, out Material material)
		{
			material = null;
			if (!ContentAssetOverridePatchHelper.TryUseDirectMaterialOverride(card, ref material, (IModCardPortraitMaterialOverride overrides) => overrides.CustomPortraitMaterial, "CustomPortraitMaterial"))
			{
				return true;
			}
			if (ExternalCardMaterialOverrideRegistry.TryGetPortraitMaterial(card, out material))
			{
				return true;
			}
			if (!ModCharacterOwnedVisualOverrideHelper.TryCardPortraitMaterial(card, ref material))
			{
				return true;
			}
			return !ContentAssetOverridePatchHelper.TryUseMaterialOverride(card, ref material, (IModCardAssetOverrides o) => o.CustomPortraitMaterialPath, "CustomPortraitMaterialPath");
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Applies custom visual overrides to card subnodes that do not expose corresponding model properties.
	///     </para>
	///     <para xml:lang="zh-CN">将自定义视觉覆盖应用到没有对应模型属性的卡牌子节点。</para>
	/// </summary>
	internal class CardNodeMaterialPatch : IPatchMethod
	{
		private delegate bool TryCharacterOwnedMaterialOverride(CardModel model, ref Material material);

		private delegate bool TryCharacterOwnedTextureOverride(CardModel model, ref Texture2D texture);

		private sealed class CardNodeOverrideState
		{
			public ResourceOverrideState<Texture2D> AncientBorderTexture { get; } = new ResourceOverrideState<Texture2D>();

			public ResourceOverrideState<Texture2D> AncientBannerTexture { get; } = new ResourceOverrideState<Texture2D>();

			public ResourceOverrideState<Texture2D> BannerTexture { get; } = new ResourceOverrideState<Texture2D>();

			public ResourceOverrideState<Material> PortraitBorderMaterial { get; } = new ResourceOverrideState<Material>();

			public ResourceOverrideState<Material> EnergyIconMaterial { get; } = new ResourceOverrideState<Material>();

			public ResourceOverrideState<Material> AncientBorderMaterial { get; } = new ResourceOverrideState<Material>();

			public ResourceOverrideState<Material> AncientTextBgMaterial { get; } = new ResourceOverrideState<Material>();

			public ResourceOverrideState<Material> AncientBannerMaterial { get; } = new ResourceOverrideState<Material>();
		}

		private sealed class ResourceOverrideState<T> where T : Resource
		{
			private T? _baseValue;

			private T? _overrideValue;

			private bool _hasOverride;

			public void Apply(T? currentValue, T overrideValue, Action<T?> setter)
			{
				if (!_hasOverride || !IsSameResource(currentValue, _overrideValue))
				{
					_baseValue = currentValue;
				}
				setter(overrideValue);
				_overrideValue = overrideValue;
				_hasOverride = true;
			}

			public void Restore(T? currentValue, Action<T?> setter)
			{
				if (_hasOverride)
				{
					if (IsSameResource(currentValue, _overrideValue))
					{
						setter(_baseValue);
					}
					_baseValue = default(T);
					_overrideValue = default(T);
					_hasOverride = false;
				}
			}

			private static bool IsSameResource(T? left, T? right)
			{
				if (left != null)
				{
					if (right != null)
					{
						return ((GodotObject)(object)left).GetInstanceId() == ((GodotObject)(object)right).GetInstanceId();
					}
					return false;
				}
				return right == null;
			}
		}

