		private static void ApplyTexture(NCard card, CardModel model, NodePath nodePath, Func<IModCardAssetOverrides, string?> pathSelector, string memberName, TryCharacterOwnedTextureOverride tryCharacterOwned, ResourceOverrideState<Texture2D> state, bool allowOverride)
		{
			TextureRect node = ((Node)card).GetNodeOrNull<TextureRect>(nodePath);
			if (node == null)
			{
				return;
			}
			if (allowOverride && TryGetTexture(model, pathSelector, memberName, tryCharacterOwned, out Texture2D texture))
			{
				state.Apply(node.Texture, texture, delegate(Texture2D? value)
				{
					node.Texture = value;
				});
			}
			else
			{
				state.Restore(node.Texture, delegate(Texture2D? value)
				{
					node.Texture = value;
				});
			}
		}

		private static void ApplyMaterial<TDirectOverride>(NCard card, CardModel model, NodePath nodePath, Func<TDirectOverride, Material?> directSelector, string directMemberName, Func<IModCardAssetOverrides, string?> pathSelector, string memberName, TryCharacterOwnedMaterialOverride tryCharacterOwned, ResourceOverrideState<Material> state, bool allowOverride) where TDirectOverride : class
		{
			CanvasItem node = ((Node)card).GetNodeOrNull<CanvasItem>(nodePath);
			if (node == null)
			{
				return;
			}
			if (allowOverride && TryGetMaterial(model, directSelector, directMemberName, pathSelector, memberName, tryCharacterOwned, out Material material))
			{
				state.Apply(node.Material, material, delegate(Material? value)
				{
					node.Material = value;
				});
			}
			else
			{
				state.Restore(node.Material, delegate(Material? value)
				{
					node.Material = value;
				});
			}
		}

		private static bool TryGetMaterial<TDirectOverride>(CardModel model, Func<TDirectOverride, Material?> directSelector, string directMemberName, Func<IModCardAssetOverrides, string?> pathSelector, string memberName, TryCharacterOwnedMaterialOverride tryCharacterOwned, out Material material) where TDirectOverride : class
		{
			material = null;
			if (!ContentAssetOverridePatchHelper.TryUseDirectMaterialOverride(model, ref material, directSelector, directMemberName))
			{
				return true;
			}
			if (!tryCharacterOwned(model, ref material))
			{
				return true;
			}
			return !ContentAssetOverridePatchHelper.TryUseMaterialOverride(model, ref material, pathSelector, memberName);
		}

		private static bool TryGetTexture(CardModel model, Func<IModCardAssetOverrides, string?> pathSelector, string memberName, TryCharacterOwnedTextureOverride tryCharacterOwned, out Texture2D texture)
		{
			texture = null;
