		/// <summary>
		///     <para xml:lang="en">
		///         Resolves a <see cref="T:Godot.PackedScene" /> from a defined path, preferring the preload cache and falling
		///         back to <see cref="T:Godot.ResourceLoader" />. Candidate enumeration supports <c>uid://</c> and remapped paths.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从已定义路径解析 <see cref="T:Godot.PackedScene" />，优先使用预加载缓存，并回退到
		///         <see cref="T:Godot.ResourceLoader" />。候选路径枚举支持 <c>uid://</c> 和重映射路径。
		///     </para>
		/// </summary>
		internal static PackedScene? ResolveScene(string definedPath)
		{
			foreach (string item in GodotResourcePath.EnumerateCandidatePaths(definedPath))
			{
				if (ResourceLoader.Exists(item, ""))
				{
					if (TryGetCachedResource<PackedScene>(item, out PackedScene resource))
					{
						return resource;
					}
					Resource obj = ResourceLoader.Load(item, "", (CacheMode)1);
					PackedScene val = (PackedScene)(object)((obj is PackedScene) ? obj : null);
					if (val != null)
					{
						return val;
					}
				}
			}
			return null;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves a <see cref="T:Godot.Texture2D" /> from a defined path, preferring the preload cache and falling
		///         back to <see cref="T:Godot.ResourceLoader" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从已定义路径解析 <see cref="T:Godot.Texture2D" />，优先使用预加载缓存，并回退到
		///         <see cref="T:Godot.ResourceLoader" />。
		///     </para>
		/// </summary>
		internal static Texture2D? ResolveTexture2D(string definedPath)
		{
			foreach (string item in GodotResourcePath.EnumerateCandidatePaths(definedPath))
			{
				if (ResourceLoader.Exists(item, ""))
				{
					if (TryGetCachedResource<Texture2D>(item, out Texture2D resource))
					{
						return resource;
					}
					Resource obj = ResourceLoader.Load(item, "", (CacheMode)1);
					Texture2D val = (Texture2D)(object)((obj is Texture2D) ? obj : null);
					if (val != null)
					{
						return val;
					}
				}
			}
			return null;
		}

		private static bool TryGetCachedResource<TResource>(string path, out TResource resource) where TResource : Resource
		{
			resource = default(TResource);
			try
			{
				object obj = ((typeof(TResource) == typeof(PackedScene)) ? PreloadManager.Cache.GetScene(path) : ((typeof(TResource) == typeof(Texture2D)) ? ((object)PreloadManager.Cache.GetTexture2D(path)) : ((object)ResourceLoader.Load(path, "", (CacheMode)1))));
				TResource val = (TResource)((obj is TResource) ? obj : null);
				if (val == null)
				{
					return false;
				}
				resource = val;
				return true;
			}
			catch (InvalidCastException)
			{
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Reports a defined override path that is missing or cannot be loaded as the expected resource type.
		///         Undefined overrides do not produce warnings.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         报告已定义但不存在或无法按预期资源类型加载的覆盖路径。未定义的覆盖不会产生警告。
		///     </para>
		/// </summary>
		internal static void WarnOverrideUnavailable(object instance, string memberName, string path, string expectedType)
		{
			if (AssetPathDiagnostics.Exists(path, instance, memberName))
			{
				LogLoadFailure(instance, memberName, path, expectedType);
			}
		}

		internal static void LogLoadFailure(object instance, string memberName, string path, string expectedType)
		{
			RitsuLibFramework.Logger.Warn($"[Assets] Resource exists but failed to load as {expectedType} for {DescribeOwner(instance)}.{memberName}: '{path}'. Falling back to the base asset.", 1);
		}

		internal static bool IsPackedSceneOverrideAvailable(object instance, PackedScene? scene, string memberName, string source)
		{
			if (scene != null && GodotObject.IsInstanceValid((GodotObject)(object)scene))
			{
				return true;
			}
			RitsuLibFramework.Logger.Warn($"[Assets] PackedScene override is invalid for {DescribeOwner(instance)}.{memberName} from {source}. Ignoring the override.", 1);
			return false;
		}

		internal static bool IsPackedScenePathOverrideAvailable(object instance, string path, string memberName)
		{
			PackedScene val = ResolveScene(path);
			if (val == null)
			{
				WarnOverrideUnavailable(instance, memberName, path, "PackedScene");
				return false;
			}
			return IsPackedSceneOverrideAvailable(instance, val, memberName, "path '" + path + "'");
		}

		internal static bool TryInstantiatePackedSceneOverride(object instance, PackedScene? scene, string memberName, string source, out Control result)
		{
			return ContentAssetOverridePatchHelper.TryInstantiatePackedSceneOverride<Control>(instance, scene, memberName, source, out result);
		}

		internal static bool TryInstantiatePackedSceneOverride<TNode>(object instance, PackedScene? scene, string memberName, string source, out TNode result) where TNode : Node
		{
			result = default(TNode);
			if (!IsPackedSceneOverrideAvailable(instance, scene, memberName, source))
			{
				return false;
			}
			try
			{
				Node val = scene.Instantiate((GenEditState)0);
				TNode val2 = (TNode)(object)((val is TNode) ? val : null);
				if (val2 != null)
				{
					result = val2;
					return true;
				}
				if (val != null && GodotObject.IsInstanceValid((GodotObject)(object)val))
				{
					val.QueueFree();
				}
				RitsuLibFramework.Logger.Warn($"[Assets] PackedScene override for {DescribeOwner(instance)}.{memberName} from {source} instantiated '{((object)val)?.GetType().FullName ?? "null"}' instead of {typeof(TNode).Name}. Falling back to the base asset.", 1);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[Assets] Failed to instantiate PackedScene override for {DescribeOwner(instance)}.{memberName} from {source}: {ex.Message}. Falling back to the base asset.", 1);
			}
			return false;
		}

		internal static bool TryInstantiatePackedScenePathOverride(object instance, string path, string memberName, out Control result)
		{
			return ContentAssetOverridePatchHelper.TryInstantiatePackedScenePathOverride<Control>(instance, path, memberName, out result);
		}

		internal static bool TryInstantiatePackedScenePathOverride<TNode>(object instance, string path, string memberName, out TNode result) where TNode : Node
		{
			result = default(TNode);
			PackedScene val = ResolveScene(path);
			if (val == null)
			{
				WarnOverrideUnavailable(instance, memberName, path, "PackedScene");
				return false;
			}
			return TryInstantiatePackedSceneOverride(instance, val, memberName, "path '" + path + "'", out result);
		}

		private static string DescribeOwner(object owner)
		{
			try
			{
				AbstractModel val = (AbstractModel)((owner is AbstractModel) ? owner : null);
				if (val != null && !string.IsNullOrWhiteSpace(val.Id.Entry))
				{
					return owner.GetType().Name + "<" + val.Id.Entry + ">";
				}
			}
			catch
			{
			}
			return owner.GetType().Name;
		}

