	/// <summary>
	///     <para xml:lang="en">Applies external and interface overrides to the orb HUD icon.</para>
	///     <para xml:lang="zh-CN">将外部和接口覆盖应用到充能球 HUD 图标。</para>
	/// </summary>
	internal class OrbIconPatch : IPatchMethod
	{
		public static string PatchId => "content_asset_override_orb_icon";

		public static string Description => "Allow mod orbs to override icon textures";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(OrbModel), "Icon", (MethodType)1)
			};
		}

		/// <summary>
		///     <para xml:lang="en">Applies the first available orb HUD icon override.</para>
		///     <para xml:lang="zh-CN">应用首个可用的充能球 HUD 图标覆盖。</para>
		/// </summary>
		public static bool Prefix(OrbModel __instance, ref CompressedTexture2D __result)
		{
			if (ExternalAssetOverrideRegistry.TryGetOrbIconTexture(__instance, out CompressedTexture2D value))
			{
				__result = value;
				return false;
			}
			if (!ContentAssetOverridePatchHelper.TryUseExternalCompressedTexturePathOverride(__instance, ref __result, () => (!ExternalAssetOverrideRegistry.TryGetOrbIconPath(__instance, out string value2)) ? null : value2, "ExternalAssetOverrideRegistry.OrbIconPath"))
			{
				return false;
			}
			return ContentAssetOverridePatchHelper.TryUseCompressedTextureOverride(__instance, ref __result, (IModOrbAssetOverrides o) => o.CustomIconPath, "CustomIconPath");
		}
	}
	/// <summary>
	///     <para xml:lang="en">Applies external and interface overrides to the orb combat-visual scene path.</para>
	///     <para xml:lang="zh-CN">将外部和接口覆盖应用到充能球战斗视觉场景路径。</para>
	/// </summary>
	internal class OrbSpritePathPatch : IPatchMethod
	{
		public static string PatchId => "content_asset_override_orb_sprite_path";

		public static string Description => "Allow mod orbs to override visuals scene paths";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(OrbModel), "SpritePath", (MethodType)1)
			};
		}

		/// <summary>
		///     <para xml:lang="en">Applies the first available orb combat-visual scene-path override.</para>
		///     <para xml:lang="zh-CN">应用首个可用的充能球战斗视觉场景路径覆盖。</para>
		/// </summary>
		public static bool Prefix(OrbModel __instance, ref string __result)
		{
			if (ExternalAssetOverrideRegistry.TryGetOrbVisualsScenePath(__instance, out string value) && AssetPathDiagnostics.Exists(value, __instance, "ExternalAssetOverrideRegistry.OrbVisualsScenePath"))
			{
				__result = value;
				return false;
			}
			return ContentAssetOverridePatchHelper.TryUseStringOverride(__instance, ref __result, (IModOrbAssetOverrides o) => o.CustomVisualsScenePath, "CustomVisualsScenePath");
