	/// <summary>
	///     <para xml:lang="en">Adds custom orb icon and combat-visual paths to preload enumeration.</para>
	///     <para xml:lang="zh-CN">将自定义充能球图标和战斗视觉路径添加到预加载枚举。</para>
	/// </summary>
	internal class OrbAssetPathsPatch : IPatchMethod
	{
		public static string PatchId => "content_asset_override_orb_asset_paths";

		public static string Description => "Allow mod orbs to advertise custom asset paths";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(OrbModel), "AssetPaths", (MethodType)1)
			};
		}

		/// <summary>
		///     <para xml:lang="en">Builds the effective custom orb asset-path enumeration.</para>
		///     <para xml:lang="zh-CN">构建有效的自定义充能球资源路径枚举。</para>
		/// </summary>
		public static bool Prefix(OrbModel __instance, ref IEnumerable<string> __result)
		{
			if (!(__instance is IModOrbAssetOverrides modOrbAssetOverrides))
			{
				return !TryBuildOrbAssetPathsFromExternal(__instance, out __result);
			}
			string[] array = AssetPathDiagnostics.CollectExistingPaths(__instance, (modOrbAssetOverrides.CustomIconPath, "CustomIconPath"), (modOrbAssetOverrides.CustomVisualsScenePath, "CustomVisualsScenePath"));
			if (TryBuildOrbAssetPathsFromExternal(__instance, out IEnumerable<string> paths))
			{
				array = array.Concat(paths).Distinct<string>(StringComparer.Ordinal).ToArray();
			}
			if (array.Length == 0)
			{
				return true;
			}
			__result = array;
			return false;
		}

		private static bool TryBuildOrbAssetPathsFromExternal(OrbModel instance, out IEnumerable<string> paths)
		{
			List<string> list = new List<string>(2);
			if (ExternalAssetOverrideRegistry.TryGetOrbIconPath(instance, out string value) && AssetPathDiagnostics.Exists(value, instance, "ExternalAssetOverrideRegistry.OrbIconPath"))
			{
				list.Add(value);
			}
			if (ExternalAssetOverrideRegistry.TryGetOrbVisualsScenePath(instance, out string value2) && AssetPathDiagnostics.Exists(value2, instance, "ExternalAssetOverrideRegistry.OrbVisualsScenePath"))
			{
				list.Add(value2);
			}
			paths = list;
			return list.Count > 0;
		}
	}
