	/// <summary>
	///     <para xml:lang="en">
	///         Makes <c>EncounterModel.CreateBackgroundAssetsForCustom</c> honor custom background scenes, layer
	///         directories, and programmatic backgrounds.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         使 <c>EncounterModel.CreateBackgroundAssetsForCustom</c> 识别自定义背景场景、图层目录和程序化背景。
	///     </para>
	/// </summary>
	internal class EncounterCreateBackgroundAssetsForCustomPatch : IPatchMethod
	{
		public static string PatchId => "content_asset_override_encounter_create_background_assets_custom";

		public static string Description => "Allow mod encounters to customize BackgroundAssets (path-based or programmatic via ModEncounterTemplate)";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(EncounterModel), "CreateBackgroundAssetsForCustom", new Type[1] { typeof(Rng) })
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Tries path-based overrides first, then a prepared programmatic background, and finally the base-game
		///         implementation.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         依次尝试基于路径的覆盖、预先准备的程序化背景和原版游戏实现。
		///     </para>
		/// </summary>
		public static bool Prefix(EncounterModel __instance, Rng rng, ref BackgroundAssets __result)
		{
			IModEncounterAssetOverrides modEncounterAssetOverrides = __instance as IModEncounterAssetOverrides;
			bool flag = ExternalAssetOverrideRegistry.TryGetEncounterBackgroundLayersDirectory(__instance, out string value);
			bool flag2 = ExternalAssetOverrideRegistry.TryGetEncounterBackgroundScenePath(__instance, out string value2);
			if ((modEncounterAssetOverrides != null) | flag | flag2)
			{
				string text = (flag ? value : modEncounterAssetOverrides?.CustomBackgroundLayersDirectoryPath);
				string text2 = (flag2 ? value2 : modEncounterAssetOverrides?.CustomBackgroundScenePath);
				if (!string.IsNullOrWhiteSpace(text) || !string.IsNullOrWhiteSpace(text2))
				{
					string text3 = ((AbstractModel)__instance).Id.Entry.ToLowerInvariant();
					string layersDirectoryResPath = (string.IsNullOrWhiteSpace(text) ? ("res://scenes/backgrounds/" + text3 + "/layers") : text.TrimEnd('/'));
					string mainBackgroundScenePath = (string.IsNullOrWhiteSpace(text2) ? SceneHelper.GetScenePath($"backgrounds/{text3}/{text3}_background") : text2);
					try
					{
						__result = ActBackgroundLayersFactory.CreateFromCustomLayersDirectory(layersDirectoryResPath, mainBackgroundScenePath, rng);
						if (__instance is ModEncounterTemplate modEncounterTemplate)
						{
							modEncounterTemplate.AbandonProgrammaticCombatBackgroundSlot();
						}
						return false;
					}
					catch (Exception ex)
					{
						RitsuLibFramework.Logger.Warn($"[Assets] Mod encounter '{((AbstractModel)__instance).Id.Entry}' custom BackgroundAssets failed ({ex.GetType().Name}: {ex.Message}). " + "Trying programmatic or vanilla encounter background.", 1);
					}
				}
			}
			if (!(__instance is ModEncounterTemplate modEncounterTemplate2))
			{
				return true;
			}
			BackgroundAssets val = modEncounterTemplate2.ConsumeProgrammaticCombatBackgroundSlot();
			if (val != null)
			{
				__result = val;
				return false;
			}
			if (modEncounterTemplate2.UsesProgrammaticCombatBackground)
			{
				RitsuLibFramework.Logger.Warn("[Assets] Mod encounter '" + ((AbstractModel)__instance).Id.Entry + "' has UseProgrammaticCombatBackground but BuildProgrammaticCombatBackground returned null; using vanilla per-encounter background layout.", 1);
			}
			return true;
		}
	}
