		public static string Description => "Allow mod encounters to override MapNodeAssetPaths";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(EncounterModel), "MapNodeAssetPaths", (MethodType)1)
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Applies available paths from the registered enumeration, then the model-provided enumeration;
		///         if neither contains an available resource, retains the base-game enumeration.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         依次应用已注册枚举和模型提供枚举中的可用路径；两者均不含可用资源时保留原版游戏枚举。
		///     </para>
		/// </summary>
		public static bool Prefix(EncounterModel __instance, ref IEnumerable<string> __result)
		{
			if (ExternalAssetOverrideRegistry.TryGetEncounterMapNodeAssetPaths(__instance, out IEnumerable<string> values) && TryCollectExistingPaths(values, "ExternalAssetOverrideRegistry.EncounterMapNodeAssetPaths", out __result))
			{
				return false;
			}
			return !TryCollectExistingPaths((__instance as IModEncounterAssetOverrides)?.CustomMapNodeAssetPaths, "CustomMapNodeAssetPaths", out __result);
			bool TryCollectExistingPaths(IEnumerable<string>? raw, string memberLabel, out IEnumerable<string> paths)
			{
				paths = Array.Empty<string>();
				if (raw == null)
				{
					return false;
				}
				(string, string)[] array = (from path in raw
					where !string.IsNullOrWhiteSpace(path)
					select (path, memberLabel: memberLabel)).ToArray();
				if (array.Length == 0)
				{
					return false;
				}
				string[] array2 = AssetPathDiagnostics.CollectExistingPaths(__instance, array);
				if (array2.Length == 0)
				{
					return false;
				}
				paths = array2;
				return true;
			}
		}
	}
