				new ModPatchTarget(typeof(EncounterModel), "GetAssetPaths")
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds the encounter scene, extra paths, background scene, and layer-directory scenes to the preload
		///         enumeration.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将遭遇场景、额外路径、背景场景和图层目录中的场景添加到预加载枚举。
		///     </para>
		/// </summary>
		public static void Postfix(EncounterModel __instance, IRunState runState, ref IEnumerable<string> __result)
		{
			IModEncounterAssetOverrides modEncounterAssetOverrides = __instance as IModEncounterAssetOverrides;
			bool flag = ExternalAssetOverrideRegistry.TryGetEncounterScenePath(__instance, out string value) && ResourceLoader.Exists(value, "");
			bool flag2 = ExternalAssetOverrideRegistry.TryGetEncounterBackgroundLayersDirectory(__instance, out string value2);
			bool flag3 = ExternalAssetOverrideRegistry.TryGetEncounterBackgroundScenePath(__instance, out string value3) && ResourceLoader.Exists(value3, "");
			if (modEncounterAssetOverrides == null && !flag && !flag2 && !flag3)
			{
				return;
			}
			List<string> list = CollectEncounterExtraAssetPaths(__instance, modEncounterAssetOverrides, flag ? value : null, flag2 ? value2 : null, flag3 ? value3 : null);
			string syntheticEncounterScene = SceneHelper.GetScenePath("encounters/" + ((AbstractModel)__instance).Id.Entry.ToLowerInvariant());
			string text = (flag ? value : modEncounterAssetOverrides?.CustomEncounterScenePath);
			bool num = !string.IsNullOrWhiteSpace(text) && ResourceLoader.Exists(text, "");
			bool flag4 = __instance is IModEncounterCombatSceneFactory modEncounterCombatSceneFactory && modEncounterCombatSceneFactory.SuppliesEncounterCombatSceneFromFactory;
			if ((num && !ResPathEquals(syntheticEncounterScene, text)) | flag4)
			{
				List<string> list2 = new List<string>();
				list2.AddRange(__result.Where((string p) => !ResPathEquals(p, syntheticEncounterScene)));
				__result = new <>z__ReadOnlyList<string>(list2);
			}
			if (list.Count != 0)
			{
				__result = __result.Concat(list);
			}
		}

		private static bool ResPathEquals(string a, string b)
		{
			return string.Equals(a.TrimEnd('/'), b.TrimEnd('/'), StringComparison.OrdinalIgnoreCase);
		}

		private static List<string> CollectEncounterExtraAssetPaths(EncounterModel instance, IModEncounterAssetOverrides? overrides, string? externalScenePath, string? externalLayersDirectory, string? externalBackgroundPath)
		{
			//IL_00c9: Unknown result type (might be due to invalid IL or missing references)
			List<string> list = new List<string>();
			string text = externalScenePath ?? overrides?.CustomEncounterScenePath;
			if (!string.IsNullOrWhiteSpace(text) && AssetPathDiagnostics.Exists(text, instance, "CustomEncounterScenePath"))
			{
				list.Add(text);
			}
			IEnumerable<string> enumerable = overrides?.CustomExtraAssetPaths;
			if (enumerable != null)
			{
				list.AddRange(from p in enumerable
					where !string.IsNullOrWhiteSpace(p)
					where AssetPathDiagnostics.Exists(p, instance, "CustomExtraAssetPaths")
					select p);
			}
			string text2 = externalLayersDirectory ?? overrides?.CustomBackgroundLayersDirectoryPath;
			if (!string.IsNullOrWhiteSpace(text2))
			{
				string text3 = text2.TrimEnd('/');
				DirAccess val = DirAccess.Open(text3);
				try
				{
					if (val != null)
					{
						val.ListDirBegin();
						string next = val.GetNext();
						while (next != "")
						{
							if (!val.CurrentIsDir() && next.EndsWith(".tscn", StringComparison.OrdinalIgnoreCase))
							{
								list.Add(text3 + "/" + next);
							}
							next = val.GetNext();
						}
					}
				}
				finally
				{
					((IDisposable)val)?.Dispose();
				}
			}
			string text4 = externalBackgroundPath ?? overrides?.CustomBackgroundScenePath;
			if (!string.IsNullOrWhiteSpace(text4) && AssetPathDiagnostics.Exists(text4, instance, "CustomBackgroundScenePath"))
			{
				list.Add(text4);
			}
			return list;
		}
	}
