	/// <summary>
	///     <para xml:lang="en">
	///         Replaces the base game's rich-text energy-icon path after
	///         <c>EnergyIconsFormatter.TryEvaluateFormat</c> builds its image tag, using mappings supplied by
	///         <see cref="T:STS2RitsuLib.Scaffolding.Content.Patches.IModTextEnergyIconPool" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在 <c>EnergyIconsFormatter.TryEvaluateFormat</c> 构建图像标签后，使用
	///         <see cref="T:STS2RitsuLib.Scaffolding.Content.Patches.IModTextEnergyIconPool" /> 提供的映射替换原版游戏的富文本能量图标路径。
	///     </para>
	/// </summary>
	internal class EnergyIconFormatterPatch : IPatchMethod
	{
		public static string PatchId => "energy_icon_formatter_text_icon_override";

		public static string Description => "Allow mod card pools to override the small energy icon path in rich-text card descriptions";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(EnergyIconsFormatter), "TryEvaluateFormat")
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Inserts <see cref="M:STS2RitsuLib.Scaffolding.Content.Patches.ModTextEnergyIconHelper.OverrideTextIconTag(System.String,System.String)" /> immediately after the formatter
		///         stores its assembled rich-text image tag.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在格式化器保存组装完成的富文本图像标签后，立即插入
		///         <see cref="M:STS2RitsuLib.Scaffolding.Content.Patches.ModTextEnergyIconHelper.OverrideTextIconTag(System.String,System.String)" /> 调用。
		///     </para>
		/// </summary>
		[HarmonyAfter(new string[] { "BaseLib" })]
		[HarmonyPriority(0)]
		public static IEnumerable<CodeInstruction> Transpiler(IEnumerable<CodeInstruction> instructions)
		{
			MethodInfo method = AccessTools.Method(typeof(string), "Concat", new Type[3]
			{
				typeof(string),
				typeof(string),
				typeof(string)
			}, (Type[])null);
			MethodInfo overrideMethod = AccessTools.Method(typeof(ModTextEnergyIconHelper), "OverrideTextIconTag", (Type[])null, (Type[])null);
			HarmonyIlRewriter harmonyIlRewriter = HarmonyIlRewriter.From(instructions);
			HarmonyIlPattern pattern = HarmonyIlPattern.Sequence(HarmonyIl.IsLdstr("[img]res://images/packed/sprite_fonts/"), HarmonyIl.IsLdloc(), HarmonyIl.IsLdstr(), HarmonyIl.IsCall(method), HarmonyIl.IsStloc());
			if (!harmonyIlRewriter.TryFind(pattern, out var match))
			{
				if (!harmonyIlRewriter.Contains((CodeInstruction instruction) => HarmonyIl.IsCallTo(instruction, overrideMethod)))
				{
					RitsuLibFramework.Logger.Warn("[EnergyIconFormatter] Could not find text energy icon concat pattern; override patch skipped.", 1);
				}
				return harmonyIlRewriter.Instructions();
			}
			HarmonyIlLocalRef localLoad = match.GetLocalLoad(harmonyIlRewriter.Code, 1);
			HarmonyIlLocalRef localStore = match.GetLocalStore(harmonyIlRewriter.Code, 4);
			HarmonyIlRewriteReport harmonyIlRewriteReport = harmonyIlRewriter.TryInsertAfterFirst("[EnergyIconFormatter] Insert text energy icon override", pattern, new global::<>z__ReadOnlyArray<CodeInstruction>((CodeInstruction[])(object)new CodeInstruction[4]
			{
				localLoad.Load(),
				localStore.Load(),
				HarmonyIl.Call(overrideMethod),
				localStore.Store()
			}), (IReadOnlyList<CodeInstruction> code) => code.Any((CodeInstruction instruction) => HarmonyIl.IsCallTo(instruction, overrideMethod)));
			harmonyIlRewriteReport.RequireSucceeded();
			if (harmonyIlRewriteReport.Applied > 0)
			{
				harmonyIlRewriteReport.RequireExactly(1);
			}
			return harmonyIlRewriter.InstructionsChecked("[EnergyIconFormatter] Insert text energy icon override");
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Resolves rich-text energy-icon paths from registered pools that implement
	///         <see cref="T:STS2RitsuLib.Scaffolding.Content.Patches.IModTextEnergyIconPool" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         从实现 <see cref="T:STS2RitsuLib.Scaffolding.Content.Patches.IModTextEnergyIconPool" /> 的已注册内容池中解析富文本能量图标路径。
	///     </para>
	/// </summary>
	internal static class ModTextEnergyIconHelper
	{
		private static Dictionary<string, string>? _cache;

		public static string OverrideTextIconTag(string prefix, string defaultTag)
		{
			if (_cache == null)
			{
				_cache = BuildCache();
			}
			if (!_cache.TryGetValue(prefix, out string value))
			{
				return defaultTag;
			}
			return "[img]" + value + "[/img]";
		}

		private static Dictionary<string, string> BuildCache()
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
			foreach (CharacterModel modCharacter in ModContentRegistry.GetModCharacters())
			{
				AddPoolIfMapped(dictionary, (IPoolModel)(object)modCharacter.CardPool);
			}
			foreach (CardPoolModel item in ModelDb.AllCards.Select((CardModel c) => c.Pool).Distinct())
			{
				AddPoolIfMapped(dictionary, (IPoolModel)(object)item);
			}
			foreach (RelicPoolModel allRelicPool in ModelDb.AllRelicPools)
			{
				AddPoolIfMapped(dictionary, (IPoolModel)(object)allRelicPool);
			}
			foreach (PotionPoolModel allPotionPool in ModelDb.AllPotionPools)
			{
				AddPoolIfMapped(dictionary, (IPoolModel)(object)allPotionPool);
			}
			return dictionary;
		}

		private static void AddPoolIfMapped(Dictionary<string, string> dict, IPoolModel pool)
		{
			if (pool is IModTextEnergyIconPool modTextEnergyIconPool && !string.IsNullOrWhiteSpace(modTextEnergyIconPool.TextEnergyIconPath) && AssetPathDiagnostics.Exists(modTextEnergyIconPool.TextEnergyIconPath, pool, "TextEnergyIconPath"))
			{
				dict.TryAdd(pool.EnergyColorName, modTextEnergyIconPool.TextEnergyIconPath);
			}
		}
	}
