		/// <summary>
		///     <para xml:lang="en">Removes every provider registered with the specified key.</para>
		///     <para xml:lang="zh-CN">移除使用指定键注册的所有提供器。</para>
		/// </summary>
		public static bool Unregister(string key)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			bool flag;
			RuntimeAssetRefreshScope scope;
			using (SyncRoot.EnterScope())
			{
				flag = UnregisterFromAllBuckets(key, out scope);
			}
			if (flag && scope != RuntimeAssetRefreshScope.None)
			{
				RuntimeAssetRefreshCoordinator.Request(scope);
			}
			return flag;
		}

		/// <summary>
		///     <para xml:lang="en">Removes all registered external providers.</para>
		///     <para xml:lang="zh-CN">移除所有已注册的外部提供器。</para>
		/// </summary>
		public static void Clear()
		{
			RuntimeAssetRefreshScope runtimeAssetRefreshScope;
			using (SyncRoot.EnterScope())
			{
				runtimeAssetRefreshScope = ClearAllBuckets();
			}
			if (runtimeAssetRefreshScope != RuntimeAssetRefreshScope.None)
			{
				RuntimeAssetRefreshCoordinator.Request(runtimeAssetRefreshScope);
			}
		}

		private static bool UnregisterFromAllBuckets(string key, out RuntimeAssetRefreshScope scope)
		{
			scope = RuntimeAssetRefreshScope.None;
			bool result = false;
			(IDictionary, RuntimeAssetRefreshScope)[] providerMaps = ProviderMaps;
			for (int i = 0; i < providerMaps.Length; i++)
			{
				var (dictionary, runtimeAssetRefreshScope) = providerMaps[i];
				if (dictionary.Contains(key))
				{
					dictionary.Remove(key);
					result = true;
					scope |= runtimeAssetRefreshScope;
				}
			}
			return result;
		}

		private static RuntimeAssetRefreshScope ClearAllBuckets()
		{
			RuntimeAssetRefreshScope runtimeAssetRefreshScope = RuntimeAssetRefreshScope.None;
			(IDictionary, RuntimeAssetRefreshScope)[] providerMaps = ProviderMaps;
			for (int i = 0; i < providerMaps.Length; i++)
			{
				var (dictionary, runtimeAssetRefreshScope2) = providerMaps[i];
				if (dictionary.Count != 0)
				{
					dictionary.Clear();
					runtimeAssetRefreshScope |= runtimeAssetRefreshScope2;
				}
			}
			return runtimeAssetRefreshScope;
		}

