		internal static bool TryGetEncounterMapNodeAssetPaths(EncounterModel model, out IEnumerable<string> values)
		{
			if (!TryGet<EncounterModel, IEnumerable<string>>(EncounterMapNodeAssetPathProviders, model, out IEnumerable<string> value, out string providerKey) || value == null)
			{
				values = Array.Empty<string>();
				return false;
			}
			try
			{
				List<string> list = new List<string>();
				list.AddRange(value);
				values = new <>z__ReadOnlyList<string>(list);
				return true;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Assets] External provider '" + providerKey + "' failed while enumerating encounter map-node asset paths: " + ex.Message, 1);
				values = Array.Empty<string>();
				return false;
			}
		}

