		private static void Register<TModel, TValue>(Dictionary<string, Func<TModel, TValue?>> map, string key, Func<TModel, TValue?> provider) where TModel : class where TValue : class
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			ArgumentNullException.ThrowIfNull(provider, "provider");
			using (SyncRoot.EnterScope())
			{
				map[key] = provider;
			}
			RuntimeAssetRefreshScope scopeForMap = GetScopeForMap(map);
			if (scopeForMap != RuntimeAssetRefreshScope.None)
			{
				RuntimeAssetRefreshCoordinator.Request(scopeForMap);
			}
		}

		private static RuntimeAssetRefreshScope GetScopeForMap(IDictionary map)
		{
			(IDictionary, RuntimeAssetRefreshScope)[] providerMaps = ProviderMaps;
			for (int i = 0; i < providerMaps.Length; i++)
			{
				var (dictionary, result) = providerMaps[i];
				if (dictionary == map)
				{
					return result;
				}
			}
			return RuntimeAssetRefreshScope.None;
		}

		private static bool TryGet<TModel>(Dictionary<string, Func<TModel, string?>> map, TModel model, out string value) where TModel : class
		{
			string providerKey;
			return TryGet(map, model, out value, out providerKey);
		}

		private static bool TryGet<TModel>(Dictionary<string, Func<TModel, string?>> map, TModel model, out string value, out string providerKey) where TModel : class
		{
			KeyValuePair<string, Func<TModel, string>>[] array = SnapshotWithKeys(map);
			for (int i = 0; i < array.Length; i++)
			{
				KeyValuePair<string, Func<TModel, string>> keyValuePair = array[i];
				string text;
				try
				{
					text = keyValuePair.Value(model);
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn("[Assets] External provider '" + keyValuePair.Key + "' failed: " + ex.Message, 1);
					continue;
				}
				if (!string.IsNullOrWhiteSpace(text))
				{
					value = text;
					providerKey = keyValuePair.Key;
					return true;
				}
			}
			value = string.Empty;
			providerKey = string.Empty;
			return false;
		}

		private static bool TryGet<TModel, TValue>(Dictionary<string, Func<TModel, TValue?>> map, TModel model, out TValue value) where TModel : class where TValue : class
		{
			string providerKey;
			return TryGet(map, model, out value, out providerKey);
		}

		private static bool TryGet<TModel, TValue>(Dictionary<string, Func<TModel, TValue?>> map, TModel model, out TValue value, out string providerKey) where TModel : class where TValue : class
		{
			KeyValuePair<string, Func<TModel, TValue>>[] array = SnapshotWithKeys(map);
			for (int i = 0; i < array.Length; i++)
			{
				KeyValuePair<string, Func<TModel, TValue>> keyValuePair = array[i];
				TValue val;
				try
				{
					val = keyValuePair.Value(model);
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn("[Assets] External provider '" + keyValuePair.Key + "' failed: " + ex.Message, 1);
					continue;
				}
				if (val != null)
				{
					value = val;
					providerKey = keyValuePair.Key;
					return true;
				}
			}
			value = null;
			providerKey = string.Empty;
			return false;
		}

		private static KeyValuePair<string, Func<TModel, TValue?>>[] SnapshotWithKeys<TModel, TValue>(Dictionary<string, Func<TModel, TValue?>> providers) where TModel : class
		{
			using (SyncRoot.EnterScope())
			{
				return providers.ToArray();
			}
		}
	}
