		internal static bool TryGetFrameMaterial(CardModel card, out Material material)
		{
			Func<CardModel, Material>[] array = Snapshot(FrameProviders);
			foreach (Func<CardModel, Material> func in array)
			{
				Material val;
				try
				{
					val = func(card);
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn("[Assets] External frame material provider failed for '" + ((object)card).GetType().Name + "': " + ex.Message, 1);
					continue;
				}
				if (val != null)
				{
					if (GodotObject.IsInstanceValid((GodotObject)(object)val))
					{
						material = val;
						return true;
					}
					RitsuLibFramework.Logger.Warn("[Assets] External frame material provider returned an invalid Material for '" + ((object)card).GetType().Name + "'. Ignoring it.", 1);
				}
			}
			material = null;
			return false;
		}

