	///     </para>
	/// </summary>
	[HarmonyAfter(new string[] { "BaseLib" })]
	[HarmonyPriority(0)]
	internal class ImageHelperAncientModRunHistoryIconPathPatch : IPatchMethod
	{
		public static string PatchId => "image_helper_ancient_mod_run_history_icon_path";

		public static string Description => "Route Ancient+Event run-history icon paths through IModAncientEventAssetOverrides when resources exist";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[2]
			{
				new ModPatchTarget(typeof(ImageHelper), "GetRoomIconPath"),
				new ModPatchTarget(typeof(ImageHelper), "GetRoomIconOutlinePath")
			};
		}

		public static bool Prefix(MethodBase __originalMethod, MapPointType mapPointType, RoomType roomType, ModelId? modelId, ref string? __result)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0002: Invalid comparison between Unknown and I4
			//IL_0004: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Invalid comparison between Unknown and I4
			if ((int)mapPointType != 8 || (int)roomType != 6 || modelId == null)
			{
				return true;
			}
			AncientEventModel byIdOrNull = ModelDb.GetByIdOrNull<AncientEventModel>(modelId);
			if (byIdOrNull == null)
			{
				return true;
			}
			string name = __originalMethod.Name;
