			if (string.IsNullOrWhiteSpace(text2) || !AssetPathDiagnostics.Exists(text2, byIdOrNull, memberName))
			{
				return true;
			}
			__result = text2;
			return false;
		}

		private static string? ResolveMainIconPath(AncientEventModel ancient)
		{
			if (ExternalAssetOverrideRegistry.TryGetAncientRunHistoryIconPath(ancient, out string value) && AssetPathDiagnostics.Exists(value, ancient, "ExternalAssetOverrideRegistry.AncientRunHistoryIconPath"))
			{
				return value;
			}
