		public static void Prefix(ActModel __instance, List<AncientEventModel>? ____sharedAncientSubset)
		{
			if (____sharedAncientSubset != null && ____sharedAncientSubset.Count > 0)
			{
				____sharedAncientSubset.RemoveAll((AncientEventModel ancient) => !ModAncientActValidityFilter.IsValidForAct(__instance, ancient));
			}
		}
