			public RelicAssetProfile? TryGetVanillaRelicVisualOverrideForOwnedRelic(RelicModel relic)
			{
				CharacterVanillaRelicVisualOverride[] vanillaRelicVisualOverrides = AssetProfile.VanillaRelicVisualOverrides;
				if (vanillaRelicVisualOverrides == null || vanillaRelicVisualOverrides.Length <= 0)
				{
					return null;
				}
				return (from entry in vanillaRelicVisualOverrides
					where ((AbstractModel)relic).Id.Entry.Equals(entry.RelicModelIdEntry, StringComparison.OrdinalIgnoreCase)
					select entry.Assets).FirstOrDefault();
			}

			public PotionAssetProfile? TryGetVanillaPotionVisualOverrideForContext(PotionModel potion)
			{
				CharacterVanillaPotionVisualOverride[] vanillaPotionVisualOverrides = AssetProfile.VanillaPotionVisualOverrides;
				if (vanillaPotionVisualOverrides == null || vanillaPotionVisualOverrides.Length <= 0)
				{
					return null;
				}
				return (from entry in vanillaPotionVisualOverrides
					where ((AbstractModel)potion).Id.Entry.Equals(entry.PotionModelIdEntry, StringComparison.OrdinalIgnoreCase)
					select entry.Assets).FirstOrDefault();
			}

			public CardAssetProfile? TryGetVanillaCardVisualOverrideForContext(CardModel card)
			{
				CharacterVanillaCardVisualOverride[] vanillaCardVisualOverrides = AssetProfile.VanillaCardVisualOverrides;
				if (vanillaCardVisualOverrides == null || vanillaCardVisualOverrides.Length <= 0)
				{
					return null;
				}
				return (from entry in vanillaCardVisualOverrides
					where ((AbstractModel)card).Id.Entry.Equals(entry.CardModelIdEntry, StringComparison.OrdinalIgnoreCase)
					select entry.Assets).FirstOrDefault();
			}
		}

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, IModCharacterAssetOverrides> RegisteredProfileAdapters = new Dictionary<string, IModCharacterAssetOverrides>(StringComparer.OrdinalIgnoreCase);

		private static IModCharacterAssetOverrides? _cachedGlobalProfileAdapter;

		/// <summary>
		///     <para xml:lang="en">
		///         Drops the cached adapter for <paramref name="normalizedCharacterEntry" /> after its
		///         programmatic owned-visual registrations change. The entry is expected to be the canonical uppercase ID.
		///     </para>
		///     <para xml:lang="zh-CN"><paramref name="normalizedCharacterEntry" /> 的编程式所属视觉注册发生变化后，丢弃其缓存适配器。该条目应为规范化的大写 ID。</para>
		/// </summary>
		internal static void InvalidateCachesForCharacterEntry(string normalizedCharacterEntry)
		{
			using (SyncRoot.EnterScope())
			{
				RegisteredProfileAdapters.Remove(normalizedCharacterEntry);
			}
		}

		internal static void InvalidateAllCaches()
		{
			using (SyncRoot.EnterScope())
			{
				RegisteredProfileAdapters.Clear();
				_cachedGlobalProfileAdapter = null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves a relic profile in increasing precedence order: the character's inline profile,
		///         programmatic owned-visual registrations, then registered character and global asset replacements.
		///     </para>
		///     <para xml:lang="zh-CN">按优先级从低到高解析遗物配置：角色内联配置、编程式所属视觉注册，最后是已注册的角色级和全局资源替换。</para>
		/// </summary>
		internal static RelicAssetProfile? ResolveOwnedRelicVisualOverride(CharacterModel owner, RelicModel relic)
		{
			RelicAssetProfile preferred = TryProgrammaticRelic(((AbstractModel)owner).Id.Entry, relic);
			RelicAssetProfile preferred2 = TryRegistryRelic(((AbstractModel)owner).Id.Entry, relic);
			return CharacterAssetProfiles.MergeRelicAssetProfilesPreferSecond(CharacterAssetProfiles.MergeRelicAssetProfilesPreferSecond(TryInlineRelic(owner, relic), preferred), preferred2);
		}

		internal static PotionAssetProfile? ResolveOwnedPotionVisualOverride(CharacterModel owner, PotionModel potion)
		{
			PotionAssetProfile preferred = TryProgrammaticPotion(((AbstractModel)owner).Id.Entry, potion);
			PotionAssetProfile preferred2 = TryRegistryPotion(((AbstractModel)owner).Id.Entry, potion);
			return CharacterAssetProfiles.MergePotionAssetProfilesPreferSecond(CharacterAssetProfiles.MergePotionAssetProfilesPreferSecond(TryInlinePotion(owner, potion), preferred), preferred2);
		}

		internal static CardAssetProfile? ResolveOwnedCardVisualOverride(CharacterModel owner, CardModel card)
		{
			CardAssetProfile preferred = TryProgrammaticCard(((AbstractModel)owner).Id.Entry, card);
			CardAssetProfile preferred2 = TryRegistryCard(((AbstractModel)owner).Id.Entry, card);
			return CharacterAssetProfiles.MergeCardAssetProfilesPreferSecond(CharacterAssetProfiles.MergeCardAssetProfilesPreferSecond(TryInlineCard(owner, card), preferred), preferred2);
		}

		private static RelicAssetProfile? TryProgrammaticRelic(string characterEntry, RelicModel relic)
		{
			if (!ModContentRegistry.TryBuildProgrammaticCharacterOwnedVisualProfile(characterEntry, out CharacterAssetProfile assetProfile))
			{
				return null;
			}
			return SelectRelic(assetProfile, relic);
		}

		private static RelicAssetProfile? TryRegistryRelic(string characterEntry, RelicModel relic)
		{
			if (!ModContentRegistry.TryGetRegistryOnlyEffectiveCharacterAssetReplacement(characterEntry, out CharacterAssetProfile assetProfile))
			{
				return null;
			}
			return SelectRelic(assetProfile, relic);
		}

		private static RelicAssetProfile? TryInlineRelic(CharacterModel owner, RelicModel relic)
		{
			if (!(owner is IModCharacterAssetOverrides modCharacterAssetOverrides))
			{
				return null;
			}
			return SelectRelic(CharacterAssetProfiles.Resolve(modCharacterAssetOverrides.AssetProfile, modCharacterAssetOverrides.CharacterAssetPlaceholderCharacterId), relic);
		}

