		private static RelicAssetProfile? SelectRelic(CharacterAssetProfile profile, RelicModel relic)
		{
			CharacterVanillaRelicVisualOverride[] vanillaRelicVisualOverrides = profile.VanillaRelicVisualOverrides;
			if (vanillaRelicVisualOverrides == null || vanillaRelicVisualOverrides.Length <= 0)
			{
				return null;
			}
			string entry = ((AbstractModel)relic).Id.Entry;
			CharacterVanillaRelicVisualOverride[] array = vanillaRelicVisualOverrides;
			for (int i = 0; i < array.Length; i++)
			{
				var (value, relicAssetProfile2) = array[i];
				if (entry.Equals(value, StringComparison.OrdinalIgnoreCase))
				{
					if (string.IsNullOrWhiteSpace(relicAssetProfile2.IconPath) && string.IsNullOrWhiteSpace(relicAssetProfile2.IconOutlinePath) && string.IsNullOrWhiteSpace(relicAssetProfile2.BigIconPath))
					{
						return null;
					}
					return relicAssetProfile2;
				}
			}
			return null;
		}

		private static PotionAssetProfile? SelectPotion(CharacterAssetProfile profile, PotionModel potion)
		{
			CharacterVanillaPotionVisualOverride[] vanillaPotionVisualOverrides = profile.VanillaPotionVisualOverrides;
			if (vanillaPotionVisualOverrides == null || vanillaPotionVisualOverrides.Length <= 0)
			{
				return null;
			}
			string entry = ((AbstractModel)potion).Id.Entry;
			CharacterVanillaPotionVisualOverride[] array = vanillaPotionVisualOverrides;
			for (int i = 0; i < array.Length; i++)
			{
				var (value, potionAssetProfile2) = array[i];
				if (entry.Equals(value, StringComparison.OrdinalIgnoreCase))
				{
					if (string.IsNullOrWhiteSpace(potionAssetProfile2.ImagePath) && string.IsNullOrWhiteSpace(potionAssetProfile2.OutlinePath))
					{
						return null;
					}
					return potionAssetProfile2;
				}
			}
			return null;
		}

		private static CardAssetProfile? SelectCard(CharacterAssetProfile profile, CardModel card)
		{
			CharacterVanillaCardVisualOverride[] vanillaCardVisualOverrides = profile.VanillaCardVisualOverrides;
			if (vanillaCardVisualOverrides == null || vanillaCardVisualOverrides.Length <= 0)
			{
				return null;
			}
			string entry = ((AbstractModel)card).Id.Entry;
			CharacterVanillaCardVisualOverride[] array = vanillaCardVisualOverrides;
			for (int i = 0; i < array.Length; i++)
			{
				var (value, cardAssetProfile2) = array[i];
				if (entry.Equals(value, StringComparison.OrdinalIgnoreCase))
				{
					if (string.IsNullOrWhiteSpace(cardAssetProfile2.PortraitPath) && string.IsNullOrWhiteSpace(cardAssetProfile2.BetaPortraitPath) && string.IsNullOrWhiteSpace(cardAssetProfile2.FramePath) && string.IsNullOrWhiteSpace(cardAssetProfile2.PortraitBorderPath) && string.IsNullOrWhiteSpace(cardAssetProfile2.EnergyIconPath) && string.IsNullOrWhiteSpace(cardAssetProfile2.FrameMaterialPath) && string.IsNullOrWhiteSpace(cardAssetProfile2.AncientBorderPath) && string.IsNullOrWhiteSpace(cardAssetProfile2.AncientTextBgPath) && string.IsNullOrWhiteSpace(cardAssetProfile2.AncientBannerPath) && string.IsNullOrWhiteSpace(cardAssetProfile2.OverlayScenePath) && string.IsNullOrWhiteSpace(cardAssetProfile2.BannerTexturePath) && string.IsNullOrWhiteSpace(cardAssetProfile2.BannerMaterialPath) && cardAssetProfile2.FrameMaterial == null && cardAssetProfile2.BannerMaterial == null && string.IsNullOrWhiteSpace(cardAssetProfile2.PortraitMaterialPath) && cardAssetProfile2.PortraitMaterial == null && string.IsNullOrWhiteSpace(cardAssetProfile2.PortraitBorderMaterialPath) && cardAssetProfile2.PortraitBorderMaterial == null && string.IsNullOrWhiteSpace(cardAssetProfile2.EnergyIconMaterialPath) && cardAssetProfile2.EnergyIconMaterial == null && string.IsNullOrWhiteSpace(cardAssetProfile2.AncientBorderMaterialPath) && cardAssetProfile2.AncientBorderMaterial == null && string.IsNullOrWhiteSpace(cardAssetProfile2.AncientTextBgMaterialPath) && cardAssetProfile2.AncientTextBgMaterial == null && string.IsNullOrWhiteSpace(cardAssetProfile2.AncientBannerMaterialPath) && cardAssetProfile2.AncientBannerMaterial == null && cardAssetProfile2.VisualStyle == CardVisualStyle.Default)
					{
						return null;
					}
					return cardAssetProfile2;
				}
			}
			return null;
		}

		internal static bool TryCardVisualStyle(CardModel instance, out CardVisualStyle style)
		{
			style = CardVisualStyle.Default;
			CardVisualStyle? cardVisualStyle = (TryGetOwningCharacterOverrides(instance)?.TryGetVanillaCardVisualOverrideForContext(instance))?.VisualStyle;
			if (cardVisualStyle.HasValue)
			{
				CardVisualStyle valueOrDefault = cardVisualStyle.GetValueOrDefault();
				if (valueOrDefault != CardVisualStyle.Default)
				{
					style = valueOrDefault;
					return true;
				}
			}
			return false;
		}

		private static bool TryLoadResource<TResource>(string? path, object instance, string memberName, out TResource resource) where TResource : Resource
		{
			resource = default(TResource);
			if (string.IsNullOrWhiteSpace(path))
			{
				return false;
			}
			if (GodotResourcePath.TryLoad<TResource>(path, out TResource resource2) && resource2 != null)
			{
				resource = resource2;
				return true;
			}
			ContentAssetOverridePatchHelper.WarnOverrideUnavailable(instance, memberName, path, typeof(TResource).Name);
			return false;
		}

		internal static bool TryRelicIconPath(RelicModel instance, ref string result)
		{
			RelicAssetProfile relicAssetProfile = TryGetOwningCharacterOverrides(instance)?.TryGetVanillaRelicVisualOverrideForOwnedRelic(instance);
			if (relicAssetProfile == null)
			{
				return true;
			}
			string iconPath = relicAssetProfile.IconPath;
			if (string.IsNullOrWhiteSpace(iconPath) || !AssetPathDiagnostics.Exists(iconPath, instance, "IconPath"))
			{
				return true;
			}
			result = iconPath;
			return false;
		}

