			CardAssetProfile cardAssetProfile = TryGetOwningCharacterOverrides(instance)?.TryGetVanillaCardVisualOverrideForContext(instance);
			if (cardAssetProfile == null)
			{
				return false;
			}
			if (!string.IsNullOrWhiteSpace(cardAssetProfile.PortraitPath) && AssetPathDiagnostics.Exists(cardAssetProfile.PortraitPath, instance, "PortraitPath"))
			{
				portraitPath = cardAssetProfile.PortraitPath;
			}
			if (!string.IsNullOrWhiteSpace(cardAssetProfile.BetaPortraitPath) && AssetPathDiagnostics.Exists(cardAssetProfile.BetaPortraitPath, instance, "BetaPortraitPath"))
			{
				betaPortraitPath = cardAssetProfile.BetaPortraitPath;
			}
			if (portraitPath == null)
			{
				return betaPortraitPath != null;
			}
			return true;
		}

		private static IModCharacterAssetOverrides? TryGetOwningCharacterOverrides(RelicModel instance)
		{
			object owner2;
			if (!((AbstractModel)instance).IsCanonical)
			{
				Player owner = instance.Owner;
				owner2 = ((owner != null) ? owner.Character : null);
			}
			else
			{
				owner2 = null;
			}
			return ResolveOwningCharacterOverrides((CharacterModel?)owner2);
		}

		private static IModCharacterAssetOverrides? TryGetOwningCharacterOverrides(PotionModel instance)
		{
			object owner2;
			if (!((AbstractModel)instance).IsCanonical)
			{
				Player owner = instance.Owner;
				owner2 = ((owner != null) ? owner.Character : null);
			}
			else
			{
				owner2 = null;
			}
			return ResolveOwningCharacterOverrides((CharacterModel?)owner2);
		}

		private static IModCharacterAssetOverrides? TryGetOwningCharacterOverrides(CardModel instance)
		{
			object owner2;
			if (!((AbstractModel)instance).IsCanonical)
			{
				Player owner = instance.Owner;
				owner2 = ((owner != null) ? owner.Character : null);
			}
			else
			{
				owner2 = null;
			}
			return ResolveOwningCharacterOverrides((CharacterModel?)owner2);
		}

		private static IModCharacterAssetOverrides? ResolveOwningCharacterOverrides(CharacterModel? owner)
		{
			using (SyncRoot.EnterScope())
			{
				if (!(owner is IModCharacterAssetOverrides result))
				{
					if (owner == null)
					{
						if (!ModContentRegistry.TryGetGlobalCharacterAssetReplacement(out CharacterAssetProfile assetProfile))
						{
							return null;
						}
						return _cachedGlobalProfileAdapter ?? (_cachedGlobalProfileAdapter = new RegisteredCharacterAssetOverrideAdapter(assetProfile));
					}
					if (!ModContentRegistry.TryGetEffectiveCharacterAssetReplacement(((AbstractModel)owner).Id.Entry, out CharacterAssetProfile assetProfile2))
					{
						return null;
					}
					if (RegisteredProfileAdapters.TryGetValue(((AbstractModel)owner).Id.Entry, out IModCharacterAssetOverrides value))
					{
						return value;
					}
					RegisteredCharacterAssetOverrideAdapter registeredCharacterAssetOverrideAdapter = new RegisteredCharacterAssetOverrideAdapter(assetProfile2);
					RegisteredProfileAdapters[((AbstractModel)owner).Id.Entry] = registeredCharacterAssetOverrideAdapter;
					return registeredCharacterAssetOverrideAdapter;
				}
				return result;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Replaces saved boss selections that no longer satisfy
	///         <see cref="M:STS2RitsuLib.Scaffolding.Content.IModEncounterActValidity.IsValidForAct(MegaCrit.Sts2.Core.Models.ActModel)" />, when a valid alternative is available.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         已保存的首领选择不再满足 <see cref="M:STS2RitsuLib.Scaffolding.Content.IModEncounterActValidity.IsValidForAct(MegaCrit.Sts2.Core.Models.ActModel)" /> 时，
	///         若存在有效替代项则将其替换。
	///     </para>
	/// </summary>
	internal class ModEncounterActValidityPatch : IPatchMethod
	{
		public static string PatchId => "mod_encounter_act_validity";

		public static string Description => "Validate saved boss encounters against IModEncounterActValidity after run load";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ActModel), "ValidateRoomsAfterLoad", new Type[1] { typeof(Rng) })
			};
		}

		public static void Postfix(ActModel __instance, Rng rng)
		{
			ArgumentNullException.ThrowIfNull(__instance, "__instance");
			ArgumentNullException.ThrowIfNull(rng, "rng");
			RepairBoss(__instance, rng);
			RepairSecondBoss(__instance, rng);
		}

		private static void RepairBoss(ActModel act, Rng rng)
		{
			if (!ModEncounterActValidityFilter.IsValidForAct(act, act.BossEncounter))
			{
				EncounterModel[] array = GetValidBossCandidates(act).Where(delegate(EncounterModel encounter)
				{
					ModelId id = ((AbstractModel)encounter).Id;
					EncounterModel secondBossEncounter = act.SecondBossEncounter;
					return id != ((secondBossEncounter != null) ? ((AbstractModel)secondBossEncounter).Id : null);
				}).ToArray();
				if (array.Length == 0)
				{
					RitsuLibFramework.Logger.Warn($"[Content] Saved boss '{((AbstractModel)act.BossEncounter).Id}' is invalid for act '{((AbstractModel)act).Id}', but no valid replacement boss was available.", 1);
				}
				else
				{
					EncounterModel val = rng.NextItem<EncounterModel>((IEnumerable<EncounterModel>)array);
					RitsuLibFramework.Logger.Info($"[Content] Replaced invalid saved boss '{((AbstractModel)act.BossEncounter).Id}' with '{((AbstractModel)val).Id}' for act '{((AbstractModel)act).Id}'.", 1);
					act.SetBossEncounter(val);
				}
			}
		}

		private static void RepairSecondBoss(ActModel act, Rng rng)
		{
			if (act.SecondBossEncounter != null && !ModEncounterActValidityFilter.IsValidForAct(act, act.SecondBossEncounter))
			{
				EncounterModel[] array = (from encounter in GetValidBossCandidates(act)
					where ((AbstractModel)encounter).Id != ((AbstractModel)act.BossEncounter).Id
					select encounter).ToArray();
				if (array.Length == 0)
				{
					RitsuLibFramework.Logger.Warn($"[Content] Saved second boss '{((AbstractModel)act.SecondBossEncounter).Id}' is invalid for act '{((AbstractModel)act).Id}', but no valid replacement boss was available.", 1);
				}
				else
				{
					EncounterModel val = rng.NextItem<EncounterModel>((IEnumerable<EncounterModel>)array);
					RitsuLibFramework.Logger.Info($"[Content] Replaced invalid saved second boss '{((AbstractModel)act.SecondBossEncounter).Id}' with '{((AbstractModel)val).Id}' for act '{((AbstractModel)act).Id}'.", 1);
					act.SetSecondBossEncounter(val);
				}
			}
		}

		private static EncounterModel[] GetValidBossCandidates(ActModel act)
		{
			return act.AllBossEncounters.Where((EncounterModel encounter) => ModEncounterActValidityFilter.IsValidForAct(act, encounter)).ToArray();
		}
	}
	/// <summary>
	///     <para xml:lang="en">Defines optional icon-path overrides for <see cref="T:MegaCrit.Sts2.Core.Models.ModifierModel" />.</para>
	///     <para xml:lang="zh-CN">定义 <see cref="T:MegaCrit.Sts2.Core.Models.ModifierModel" /> 的可选图标路径覆盖。</para>
	/// </summary>
	public interface IModModifierAssetOverrides
	{
