		///     <para xml:lang="zh-CN">获取修饰符资源配置。</para>
		/// </summary>
		ModifierAssetProfile AssetProfile => ModifierAssetProfile.Empty;

		/// <summary>
		///     <para xml:lang="en">Gets the icon-path override used by custom-run and daily-run UI.</para>
		///     <para xml:lang="zh-CN">获取自定义模式和每日挑战界面使用的图标路径覆盖。</para>
		/// </summary>
		string? CustomIconPath => AssetProfile.IconPath;
	}
	/// <summary>
	///     <para xml:lang="en">Applies external and interface icon-path overrides to <see cref="T:MegaCrit.Sts2.Core.Models.ModifierModel" />.</para>
	///     <para xml:lang="zh-CN">将外部和接口图标路径覆盖应用到 <see cref="T:MegaCrit.Sts2.Core.Models.ModifierModel" />。</para>
	/// </summary>
	internal sealed class ModifierIconPathPatch : IPatchMethod
	{
		public static string PatchId => "content_asset_override_modifier_icon_path";

		public static string Description => "Allow mod modifiers to override IconPath";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ModifierModel), "IconPath", (MethodType)1)
			};
		}

		/// <summary>
		///     <para xml:lang="en">Applies the first available modifier icon-path override.</para>
		///     <para xml:lang="zh-CN">应用首个可用的修饰符图标路径覆盖。</para>
		/// </summary>
		[HarmonyAfter(new string[] { "BaseLib" })]
		[HarmonyPriority(0)]
		public static bool Prefix(ModifierModel __instance, ref string __result)
		{
			if (!ContentAssetOverridePatchHelper.TryUseExternalPathOverride(__instance, ref __result, () => (!ExternalAssetOverrideRegistry.TryGetModifierIconPath(__instance, out string value)) ? null : value, "ExternalAssetOverrideRegistry.ModifierIconPath"))
			{
				return false;
			}
			return ContentAssetOverridePatchHelper.TryUseStringOverride(__instance, ref __result, (IModModifierAssetOverrides o) => o.CustomIconPath, "CustomIconPath");
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Supplies Harmony prefixes that invoke mod runtime Godot factories from vanilla model entry points.
	///         A factory returning <see langword="null" />, throwing, or producing an invalid Godot object leaves the
	///         original path available to later override patches and the base game.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供从原版模型入口调用模组运行时 Godot 工厂的 Harmony 前缀。工厂返回 <see langword="null" />、抛出异常或
	///         产生无效的 Godot 对象时，后续覆盖补丁和游戏本体仍可使用原有路径。
	///     </para>
	/// </summary>
	internal static class ModModelRuntimeGodotFactoryPatches
	{
		/// <summary>
		///     <para xml:lang="en">Integrates runtime creature-visual factories with <see cref="M:MegaCrit.Sts2.Core.Models.MonsterModel.CreateVisuals" />.</para>
		///     <para xml:lang="zh-CN">将运行时生物视觉工厂接入 <see cref="M:MegaCrit.Sts2.Core.Models.MonsterModel.CreateVisuals" />。</para>
		/// </summary>
		internal class MonsterCreatureVisualsRuntimeFactoryPatch : IPatchMethod
		{
			public static string PatchId => "runtime_godot_factory_monster_creature_visuals";

			public static bool IsCritical => false;

			public static string Description => "Allow mod monsters to supply NCreatureVisuals from code before VisualsPath load";

			public static ModPatchTarget[] GetTargets()
			{
				return new ModPatchTarget[1]
				{
					new ModPatchTarget(typeof(MonsterModel), "CreateVisuals")
				};
			}

			/// <summary>
			///     <para xml:lang="en">
			///         Uses a valid result from <see cref="M:STS2RitsuLib.Scaffolding.Content.IModCreatureVisualsFactory.TryCreateCreatureVisuals" />; otherwise
			///         attempts the obsolete monster-specific factory, then permits the original method to run.
			///     </para>
			///     <para xml:lang="zh-CN">
			///         使用 <see cref="M:STS2RitsuLib.Scaffolding.Content.IModCreatureVisualsFactory.TryCreateCreatureVisuals" /> 的有效结果；否则尝试已过时的
			///         怪物专用工厂，仍无结果时让原方法继续执行。
			///     </para>
			/// </summary>
			[HarmonyPriority(800)]
			public static bool Prefix(MonsterModel __instance, ref NCreatureVisuals __result)
			{
				if (__instance is IModCreatureVisualsFactory modCreatureVisualsFactory && ModModelRuntimeGodotFactoryPatches.TryInvokeGodotFactory<NCreatureVisuals>((object)__instance, "TryCreateCreatureVisuals", (Func<NCreatureVisuals?>)modCreatureVisualsFactory.TryCreateCreatureVisuals, out NCreatureVisuals created))
				{
					return UseCreatedVisuals(created, out __result);
				}
				if (__instance is IModMonsterCreatureVisualsFactory modMonsterCreatureVisualsFactory && ModModelRuntimeGodotFactoryPatches.TryInvokeGodotFactory<NCreatureVisuals>((object)__instance, "TryCreateCreatureVisuals", (Func<NCreatureVisuals?>)modMonsterCreatureVisualsFactory.TryCreateCreatureVisuals, out created))
				{
					return UseCreatedVisuals(created, out __result);
				}
				return true;
				static bool UseCreatedVisuals(NCreatureVisuals val, out NCreatureVisuals result)
				{
					ModCreatureVisualPlayback.RegisterRitsuCreatureVisual((Node)(object)val);
					result = val;
					return false;
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Integrates creature-visual factories and profile resources with
		///         <see cref="M:MegaCrit.Sts2.Core.Models.CharacterModel.CreateVisuals" />.
		///     </para>
		///     <para xml:lang="zh-CN">将生物视觉工厂和配置资源接入 <see cref="M:MegaCrit.Sts2.Core.Models.CharacterModel.CreateVisuals" />。</para>
		/// </summary>
		internal class CharacterCreatureVisualsRuntimeFactoryPatch : IPatchMethod
		{
			public static string PatchId => "runtime_godot_factory_character_creature_visuals";

			public static bool IsCritical => false;

			public static string Description => "Allow mod characters to supply or auto-convert NCreatureVisuals before VisualsPath load";

			public static ModPatchTarget[] GetTargets()
			{
				return new ModPatchTarget[1]
				{
					new ModPatchTarget(typeof(CharacterModel), "CreateVisuals")
				};
			}

			/// <summary>
			///     <para xml:lang="en">
			///         Prefers a valid general factory result, then the obsolete character-specific factory, then a configured
			///         visuals scene or texture (including the placeholder-character fallback) before the original method.
			///     </para>
			///     <para xml:lang="zh-CN">
			///         依次优先使用通用工厂的有效结果、已过时的角色专用工厂，以及已配置的视觉场景或纹理（包括占位角色回退）；
			///         都不可用时再执行原方法。
			///     </para>
			/// </summary>
			[HarmonyPriority(800)]
			public static bool Prefix(CharacterModel __instance, ref NCreatureVisuals __result)
			{
				if (__instance is IModCreatureVisualsFactory modCreatureVisualsFactory && ModModelRuntimeGodotFactoryPatches.TryInvokeGodotFactory<NCreatureVisuals>((object)__instance, "TryCreateCreatureVisuals", (Func<NCreatureVisuals?>)modCreatureVisualsFactory.TryCreateCreatureVisuals, out NCreatureVisuals created))
				{
					return UseCreatedVisuals(created, out __result);
				}
				if (__instance is IModCharacterCreatureVisualsFactory modCharacterCreatureVisualsFactory && ModModelRuntimeGodotFactoryPatches.TryInvokeGodotFactory<NCreatureVisuals>((object)__instance, "TryCreateCreatureVisuals", (Func<NCreatureVisuals?>)modCharacterCreatureVisualsFactory.TryCreateCreatureVisuals, out created))
				{
					return UseCreatedVisuals(created, out __result);
				}
				if (!TryCreateCharacterResourceVisuals(__instance, out created))
				{
					return true;
				}
				return UseCreatedVisuals(created, out __result);
				static bool UseCreatedVisuals(NCreatureVisuals val, out NCreatureVisuals result)
