		/// <summary>
		///     <para xml:lang="en">
		///         Integrates orb sprite factories and mod scene conversion with
		///         <see cref="M:MegaCrit.Sts2.Core.Models.OrbModel.CreateSprite" />.
		///     </para>
		///     <para xml:lang="zh-CN">将充能球精灵工厂和模组场景转换接入 <see cref="M:MegaCrit.Sts2.Core.Models.OrbModel.CreateSprite" />。</para>
		/// </summary>
		internal class OrbSpriteRuntimeFactoryPatch : IPatchMethod
		{
			public static string PatchId => "runtime_godot_factory_orb_sprite";

			public static bool IsCritical => false;

			public static string Description => "Mod orbs: code factory first, then Ritsu Godot Node2D scene conversion (baselib-style tscn) before raw vanilla load";

			public static ModPatchTarget[] GetTargets()
			{
				return new ModPatchTarget[1]
				{
					new ModPatchTarget(typeof(OrbModel), "CreateSprite")
				};
			}

			/// <summary>
			///     <para xml:lang="en">
			///         Uses a valid sprite-factory result first. For an orb asset override, it next attempts to instantiate the
			///         configured sprite path as a <see cref="T:Godot.Node2D" /> before allowing the original path.
			///     </para>
			///     <para xml:lang="zh-CN">
			///         首先使用有效的精灵工厂结果。对于充能球资源覆盖，接着尝试将配置的精灵路径实例化为
			///         <see cref="T:Godot.Node2D" />，失败后才让原始路径继续执行。
			///     </para>
			/// </summary>
			[HarmonyPriority(800)]
			public static bool Prefix(OrbModel __instance, ref Node2D __result)
			{
				//IL_0159: Unknown result type (might be due to invalid IL or missing references)
				//IL_015e: Unknown result type (might be due to invalid IL or missing references)
				if (__instance is IModOrbSpriteFactory modOrbSpriteFactory && ModModelRuntimeGodotFactoryPatches.TryInvokeGodotFactory<Node2D>((object)__instance, "TryCreateOrbSprite", (Func<Node2D?>)modOrbSpriteFactory.TryCreateOrbSprite, out Node2D created))
				{
					__result = created;
					return false;
				}
				if (!(__instance is IModOrbAssetOverrides))
				{
					return true;
				}
				string spritePath = __instance.SpritePath;
				if (string.IsNullOrEmpty(spritePath) || !GodotResourcePath.ResourceExists(spritePath))
				{
					return true;
				}
				PackedScene val = ContentAssetOverridePatchHelper.ResolveScene(spritePath);
				if (val == null)
				{
					ContentAssetOverridePatchHelper.LogLoadFailure(__instance, "CustomVisualsScenePath", spritePath, "PackedScene");
					return true;
				}
				Node2D val2;
				try
				{
					val2 = RitsuGodotNodeFactories.CreateFromScene<Node2D>(val, (GenEditState)0);
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[Godot] Failed to instantiate {((object)__instance).GetType().Name}.{"CustomVisualsScenePath"} '{spritePath}' as {"Node2D"}: {ex.Message}. Falling back.", 1);
					return true;
				}
				if (!GodotObject.IsInstanceValid((GodotObject)(object)val2))
				{
					ContentAssetOverridePatchHelper.LogLoadFailure(__instance, "CustomVisualsScenePath", spritePath, "Node2D");
					return true;
				}
				Node nodeOrNull = ((Node)val2).GetNodeOrNull(NodePath.op_Implicit("SpineSkeleton"));
				if (nodeOrNull != null)
				{
					new MegaSprite(Variant.op_Implicit((GodotObject)(object)nodeOrNull)).GetAnimationState().SetAnimation("idle_loop", true, 0);
				}
				__result = val2;
				return false;
			}
		}

		private static bool TryCreateCharacterResourceVisuals(CharacterModel character, out NCreatureVisuals created)
		{
			created = null;
			if (!CharacterAssetOverridePatchHelper.TryResolveOverridePath(character, (IModCharacterAssetOverrides o) => o.CustomVisualsPath, "CustomVisualsPath", out string path))
			{
				return false;
			}
			if (!TryCreateCreatureVisualsFromSceneOrTexture(character, path, "CustomVisualsPath", out created))
			{
				return TryCreateFallbackCharacterVisuals(character, out created);
			}
			return true;
		}

		private static bool TryCreateCreatureVisualsFromSceneOrTexture(CharacterModel character, string path, string memberName, out NCreatureVisuals created)
		{
			created = null;
			try
			{
				PackedScene val = ContentAssetOverridePatchHelper.ResolveScene(path);
				if (val != null)
				{
					created = RitsuGodotNodeFactories.CreateFromScene<NCreatureVisuals>(val, (GenEditState)0);
					return true;
				}
				Texture2D val2 = ContentAssetOverridePatchHelper.ResolveTexture2D(path);
				if (val2 != null)
				{
					created = RitsuGodotNodeFactories.CreateFromResource<NCreatureVisuals>((object)val2);
					return true;
				}
				ContentAssetOverridePatchHelper.WarnOverrideUnavailable(character, memberName, path, "PackedScene or Texture2D");
				return false;
			}
			catch (Exception ex)
			{
				LogFactoryConversionFailure(character, memberName, path, "NCreatureVisuals", ex);
				return false;
			}
		}

		private static bool TryCreateCharacterIconFromSceneOrTexture(CharacterModel character, string path, string memberName, out Control created)
		{
			created = null;
			try
			{
				PackedScene val = ContentAssetOverridePatchHelper.ResolveScene(path);
				if (val != null)
				{
					created = RitsuGodotNodeFactories.CreateFromScene<Control>(val, (GenEditState)0);
					return true;
				}
				Texture2D val2 = ContentAssetOverridePatchHelper.ResolveTexture2D(path);
				if (val2 != null)
				{
					created = (Control)(object)CreateCharacterIconFromTexture(val2);
					return true;
				}
				ContentAssetOverridePatchHelper.WarnOverrideUnavailable(character, memberName, path, "PackedScene or Texture2D");
				return false;
			}
			catch (Exception ex)
			{
				LogFactoryConversionFailure(character, memberName, path, "Control", ex);
				return false;
			}
		}

		private static bool TryCreateFallbackCharacterVisuals(CharacterModel character, out NCreatureVisuals created)
		{
			created = null;
			foreach (string item in EnumerateFallbackCharacterAssetPaths(character, (CharacterAssetProfile profile) => profile.Scenes?.VisualsPath))
			{
				PackedScene val = ContentAssetOverridePatchHelper.ResolveScene(item);
				if (val != null)
				{
					try
					{
						created = RitsuGodotNodeFactories.CreateFromScene<NCreatureVisuals>(val, (GenEditState)0);
						RitsuLibFramework.Logger.Warn($"[Godot] Falling back to character visuals scene '{item}' for {DescribeCharacter(character)}.", 1);
						return true;
					}
					catch (Exception ex)
					{
						LogFactoryConversionFailure(character, "CustomVisualsPath", item, "NCreatureVisuals", ex);
					}
				}
			}
			return false;
		}

		private static bool TryCreateFallbackCharacterIcon(CharacterModel character, out Control created)
		{
			created = null;
			foreach (string item in EnumerateFallbackCharacterAssetPaths(character, (CharacterAssetProfile profile) => profile.Ui?.IconPath))
			{
				try
				{
					PackedScene val = ContentAssetOverridePatchHelper.ResolveScene(item);
					if (val != null)
					{
						created = RitsuGodotNodeFactories.CreateFromScene<Control>(val, (GenEditState)0);
						RitsuLibFramework.Logger.Warn($"[Godot] Falling back to character icon scene '{item}' for {DescribeCharacter(character)}.", 1);
						return true;
					}
					Texture2D val2 = ContentAssetOverridePatchHelper.ResolveTexture2D(item);
					if (val2 == null)
					{
						continue;
					}
					created = (Control)(object)CreateCharacterIconFromTexture(val2);
					RitsuLibFramework.Logger.Warn($"[Godot] Falling back to character icon texture '{item}' for {DescribeCharacter(character)}.", 1);
					return true;
				}
				catch (Exception ex)
				{
					LogFactoryConversionFailure(character, "CustomIconPath", item, "Control", ex);
				}
			}
			return false;
		}

		private static TextureRect CreateCharacterIconFromTexture(Texture2D texture)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_0020: Unknown result type (might be due to invalid IL or missing references)
