			//IL_0036: Unknown result type (might be due to invalid IL or missing references)
			//IL_003e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0046: Unknown result type (might be due to invalid IL or missing references)
			//IL_004e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			//IL_005d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0066: Expected O, but got Unknown
			return new TextureRect
			{
				Name = StringName.op_Implicit(StableTextureRectNodeName(((Resource)texture).ResourcePath, "CharacterIcon")),
				AnchorRight = 1f,
				AnchorBottom = 1f,
				GrowHorizontal = (GrowDirection)2,
				GrowVertical = (GrowDirection)2,
				MouseFilter = (MouseFilterEnum)2,
				Texture = texture,
				ExpandMode = (ExpandModeEnum)1,
				StretchMode = (StretchModeEnum)5
			};
		}

		private static string StableTextureRectNodeName(string? resourcePath, string fallback)
		{
			if (string.IsNullOrEmpty(resourcePath))
			{
				return fallback;
			}
			ReadOnlySpan<char> span = resourcePath.AsSpan();
			int num = span.LastIndexOf('/');
			if (num >= 0)
			{
				span = span.Slice(num + 1);
			}
			int num2 = span.LastIndexOf('.');
			if (num2 > 0)
			{
				span = span.Slice(0, num2);
			}
			if (span.IsEmpty)
			{
				return fallback;
			}
			Span<char> span2 = stackalloc char[span.Length];
			for (int i = 0; i < span.Length; i++)
			{
				char c = span[i];
				span2[i] = ((char.IsAsciiLetterOrDigit(c) || c == '_') ? c : '_');
			}
			return new string(span2);
		}

		private static IEnumerable<string> EnumerateFallbackCharacterAssetPaths(CharacterModel character, Func<CharacterAssetProfile, string?> selector)
		{
			string entry = ((AbstractModel)character).Id.Entry;
			if (!string.IsNullOrWhiteSpace(entry))
			{
				string text = selector(CharacterAssetProfiles.FromCharacterId(entry));
				if (!string.IsNullOrWhiteSpace(text))
				{
					yield return text;
				}
			}
			if (!string.Equals(entry, "ironclad", StringComparison.OrdinalIgnoreCase))
			{
				string text2 = selector(CharacterAssetProfiles.FromCharacterId("ironclad"));
				if (!string.IsNullOrWhiteSpace(text2))
				{
					yield return text2;
				}
			}
		}

		private static void LogFactoryConversionFailure(CharacterModel character, string memberName, string path, string targetType, Exception ex)
		{
			RitsuLibFramework.Logger.Warn($"[Godot] Failed to auto-convert {DescribeCharacter(character)}.{memberName} '{path}' to {targetType}: {ex.Message}. Falling back.", 1);
		}

		private static string DescribeCharacter(CharacterModel character)
		{
			try
			{
				return ((object)character).GetType().Name + "<" + ((AbstractModel)character).Id.Entry + ">";
			}
			catch
			{
				return ((object)character).GetType().Name;
			}
		}

		private static bool TryInvokeGodotFactory<TResult>(object owner, string memberName, Func<TResult?> factory, out TResult created) where TResult : GodotObject
		{
			created = default(TResult);
			TResult val;
			try
			{
				val = factory();
			}
			catch (Exception ex)
			{
				LogRuntimeFactoryFailure(owner, memberName, ex);
				return false;
			}
			if (val == null)
			{
				return false;
			}
			if (!GodotObject.IsInstanceValid((GodotObject)(object)val))
			{
				RitsuLibFramework.Logger.Warn($"[Godot] Runtime factory {DescribeFactoryOwner(owner)}.{memberName} returned an invalid {typeof(TResult).Name}. Falling back.", 1);
				return false;
			}
			created = val;
			return true;
		}

		private static bool TryInvokeFactory<TResult>(object owner, string memberName, Func<TResult?> factory, out TResult created) where TResult : class
		{
			created = null;
			try
			{
				TResult val = factory();
				if (val == null)
				{
					return false;
				}
				created = val;
				return true;
			}
			catch (Exception ex)
			{
				LogRuntimeFactoryFailure(owner, memberName, ex);
				return false;
			}
		}

		private static bool TryGetFactoryFlag(object owner, string memberName, Func<bool> accessor)
		{
			try
			{
				return accessor();
			}
			catch (Exception ex)
			{
				LogRuntimeFactoryFailure(owner, memberName, ex);
				return false;
			}
		}

		private static void LogRuntimeFactoryFailure(object owner, string memberName, Exception ex)
		{
			RitsuLibFramework.Logger.Warn($"[Godot] Runtime factory {DescribeFactoryOwner(owner)}.{memberName} failed: {ex.Message}. Falling back.", 1);
		}

		private static string DescribeFactoryOwner(object owner)
		{
			return owner.GetType().FullName ?? owner.GetType().Name;
		}
	}
	internal static class ModOrbRandomPoolPolicyRuntime
	{
		private static readonly FieldInfo? VanillaValidOrbsField = AccessTools.Field(typeof(OrbModel), "_validOrbs");

		public static bool HasModdedCandidates()
		{
			ModelId[] vanillaIds = GetVanillaRandomOrbIds();
			if (vanillaIds.Length != 0)
			{
				return ModelDb.Orbs.Any((OrbModel orb) => ShouldAddFromModelDbOrbs(vanillaIds, orb));
			}
			return false;
		}

		public static bool TryGetRandomOrb(Rng rng, out OrbModel orb)
		{
			ModelId[] vanillaRandomOrbIds = GetVanillaRandomOrbIds();
			if (vanillaRandomOrbIds.Length == 0)
			{
				orb = null;
				return false;
			}
			OrbModel[] array = BuildCandidates(vanillaRandomOrbIds);
			OrbModel val = rng.NextItem<OrbModel>((IEnumerable<OrbModel>)array);
			if (val == null)
			{
				orb = null;
				return false;
			}
			orb = val;
			return true;
		}

		private static ModelId[] GetVanillaRandomOrbIds()
		{
			return (VanillaValidOrbsField?.GetValue(null) as ModelId[]) ?? Array.Empty<ModelId>();
		}

		private static OrbModel[] BuildCandidates(IReadOnlyCollection<ModelId> vanillaIds)
		{
			return vanillaIds.Select((ModelId id) => ModelDb.GetByIdOrNull<OrbModel>(id)).OfType<OrbModel>().Concat(ModelDb.Orbs.Where((OrbModel orb) => ShouldAddFromModelDbOrbs(vanillaIds, orb)))
				.DistinctBy((OrbModel orb) => ((AbstractModel)orb).Id)
				.ToArray();
		}

		private static bool ShouldAddFromModelDbOrbs(IReadOnlyCollection<ModelId> vanillaIds, OrbModel orb)
		{
			if (!vanillaIds.Contains(((AbstractModel)orb).Id))
			{
				if (orb is IModOrbRandomPoolPolicy modOrbRandomPoolPolicy)
				{
					return modOrbRandomPoolPolicy.AllowInRandomOrbPool;
				}
				return false;
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Replaces <see cref="M:MegaCrit.Sts2.Core.Models.OrbModel.GetRandomOrb(MegaCrit.Sts2.Core.Random.Rng)" /> only when registered mod orbs opt in to the random pool.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         仅当已注册的模组充能球选择加入随机池时替换 <see cref="M:MegaCrit.Sts2.Core.Models.OrbModel.GetRandomOrb(MegaCrit.Sts2.Core.Random.Rng)" />。
	///     </para>
	/// </summary>
	internal sealed class OrbModelRandomPoolPolicyPatch : IPatchMethod
	{
		public static string PatchId => "orb_model_random_pool_policy";

		public static bool IsCritical => false;

		public static string Description => "Include opt-in mod orbs in OrbModel.GetRandomOrb";

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(OrbModel), "GetRandomOrb", new Type[1] { typeof(Rng) })
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Uses the vanilla random pool plus registered <see cref="T:STS2RitsuLib.Scaffolding.Content.IModOrbRandomPoolPolicy" /> opt-in candidates.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用原版随机池，并加入已注册且通过 <see cref="T:STS2RitsuLib.Scaffolding.Content.IModOrbRandomPoolPolicy" /> 选择加入的候选项。
		///     </para>
		/// </summary>
		[HarmonyAfter(new string[] { "BaseLib", "com.ritsukage.sts2-RitsuLib.framework-content-registry" })]
		[HarmonyPriority(0)]
		public static bool Prefix(Rng rng, ref OrbModel __result)
		{
			if (!ModOrbRandomPoolPolicyRuntime.HasModdedCandidates())
			{
				return true;
			}
			if (!ModOrbRandomPoolPolicyRuntime.TryGetRandomOrb(rng, out OrbModel orb))
			{
				return true;
			}
			__result = orb;
			return false;
		}
	}
	internal static class ModOrbValueDisplayPolicyRuntime
	{
		private static readonly FieldInfo? PassiveLabelField = AccessTools.Field(typeof(NOrb), "_passiveLabel");

		private static readonly FieldInfo? EvokeLabelField = AccessTools.Field(typeof(NOrb), "_evokeLabel");

		public static void Apply(NOrb node, bool isEvoking)
		{
			OrbModel model = node.Model;
			if (model == null)
			{
				return;
			}
			object? obj = PassiveLabelField?.GetValue(node);
			object obj2 = EvokeLabelField?.GetValue(node);
			MegaLabel val = (MegaLabel)((obj is MegaLabel) ? obj : null);
			if (val == null)
			{
				return;
			}
			MegaLabel val2 = (MegaLabel)((obj2 is MegaLabel) ? obj2 : null);
			if (val2 == null)
			{
				return;
			}
			string text = model.PassiveVal.ToString("0", CultureInfo.InvariantCulture);
			string text2 = model.EvokeVal.ToString("0", CultureInfo.InvariantCulture);
			OrbValueDisplayState orbValueDisplayState = ((model is IModOrbValueDisplayPolicy modOrbValueDisplayPolicy) ? new OrbValueDisplayState(modOrbValueDisplayPolicy.ValueDisplayMode, modOrbValueDisplayPolicy.PassiveValueDisplayText, modOrbValueDisplayPolicy.EvokeValueDisplayText) : new OrbValueDisplayState(ModOrbValueDisplayMode.Vanilla, text, text2));
			OrbValueDisplayState orbValueDisplayState2 = ModelCapabilityHost.ApplyOrbValueDisplay(new OrbValueDisplayContext(model, isEvoking, orbValueDisplayState.DisplayMode, orbValueDisplayState.PassiveText, orbValueDisplayState.EvokeText));
			if (orbValueDisplayState2.DisplayMode != ModOrbValueDisplayMode.Vanilla || !string.Equals(orbValueDisplayState2.PassiveText, text, StringComparison.Ordinal) || !string.Equals(orbValueDisplayState2.EvokeText, text2, StringComparison.Ordinal))
			{
				if (orbValueDisplayState2.DisplayMode != ModOrbValueDisplayMode.Vanilla)
				{
					var (visible, visible2) = orbValueDisplayState2.DisplayMode switch
					{
						ModOrbValueDisplayMode.Hidden => (false, false), 
						ModOrbValueDisplayMode.Contextual => (!isEvoking, isEvoking), 
						ModOrbValueDisplayMode.SinglePassive => (true, false), 
						ModOrbValueDisplayMode.SingleEvoke => (false, true), 
						ModOrbValueDisplayMode.Both => (true, true), 
						_ => (((CanvasItem)val).Visible, ((CanvasItem)val2).Visible), 
					};
					((CanvasItem)val).Visible = visible;
					((CanvasItem)val2).Visible = visible2;
				}
				if (((CanvasItem)val).Visible)
				{
					val.SetTextAutoSize(orbValueDisplayState2.PassiveText);
				}
				if (((CanvasItem)val2).Visible)
				{
					val2.SetTextAutoSize(orbValueDisplayState2.EvokeText);
				}
			}
		}
	}
