	/// <summary>
	///     <para xml:lang="en">
	///         Replaces an Ancient event's initialized background subtree with configured procedural stage layers.
	///     </para>
	///     <para xml:lang="zh-CN">使用已配置的程序化舞台图层替换先古事件初始化后的背景子树。</para>
	/// </summary>
	internal class NAncientEventLayoutProceduralStagePatch : IPatchMethod
	{
		public static string PatchId => "n_ancient_event_layout_procedural_stage";

		public static string Description => "Mount AncientEventStageProceduralVisualSet layers on NAncientBgContainer after layout init";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NAncientEventLayout), "InitializeVisuals")
			};
		}

		public static void Postfix(NAncientEventLayout __instance)
		{
			AncientEventModel val = AncientEvent(__instance);
			if (!(val is IModAncientEventAssetOverrides modAncientEventAssetOverrides))
			{
				return;
			}
			AncientEventStageProceduralVisualSet ancientEventStageProceduralVisualSet = modAncientEventAssetOverrides.AncientPresentationAssetProfile?.StageProcedural;
			if (ancientEventStageProceduralVisualSet == null)
			{
				return;
			}
			if (string.IsNullOrWhiteSpace(ancientEventStageProceduralVisualSet.BackgroundVideoPath) && ancientEventStageProceduralVisualSet.BackgroundCueSet == null)
			{
				RitsuLibFramework.Logger.Warn($"[AncientStage] Could not mount StageProcedural for '{((AbstractModel)val).Id}' because no background video or cue set was configured.", 1);
				return;
			}
			NAncientBgContainer val2 = AncientBgContainer(__instance);
			if (val2 == null || !GodotObject.IsInstanceValid((GodotObject)(object)val2))
			{
				RitsuLibFramework.Logger.Warn("[AncientStage] Could not mount StageProcedural because NAncientEventLayout._ancientBgContainer is not available.", 1);
				return;
			}
			List<Node> list = ((IEnumerable<Node>)((Node)val2).GetChildren(false)).ToList();
			HashSet<ulong> originalInstanceIds = (from child in ((IEnumerable<Node>)list).Where((Func<Node, bool>)GodotObject.IsInstanceValid)
				select ((GodotObject)child).GetInstanceId()).ToHashSet();
			try
			{
				AncientStageProceduralRootFactory.BuildAndMount(val2, ancientEventStageProceduralVisualSet);
			}
			catch (Exception ex)
			{
				RemoveNewChildren(val2, originalInstanceIds);
				RitsuLibFramework.Logger.Warn($"[AncientStage] Failed to mount StageProcedural for '{((AbstractModel)val).Id}': {ex.Message}. Keeping the existing background.", 1);
				return;
			}
			foreach (Node item in list)
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)item) && (object)item.GetParent() == val2)
				{
					GodotTreeExtensions.RemoveChildSafely((Node)(object)val2, item);
					GodotTreeExtensions.QueueFreeSafely(item);
				}
			}
		}

		private static void RemoveNewChildren(NAncientBgContainer container, HashSet<ulong> originalInstanceIds)
		{
			foreach (Node item in ((IEnumerable<Node>)((Node)container).GetChildren(false)).ToList())
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)item) && !originalInstanceIds.Contains(((GodotObject)item).GetInstanceId()))
				{
					GodotTreeExtensions.RemoveChildSafely((Node)(object)container, item);
					GodotTreeExtensions.QueueFreeSafely(item);
				}
			}
		}

		[UnsafeAccessor(UnsafeAccessorKind.Field, Name = "_ancientEvent")]
		private static extern ref AncientEventModel AncientEvent(NAncientEventLayout instance);

		[UnsafeAccessor(UnsafeAccessorKind.Field, Name = "_ancientBgContainer")]
		private static extern ref NAncientBgContainer AncientBgContainer(NAncientEventLayout instance);
	}
