	internal static class ModBigEnergyIconHelper
	{
		private static readonly Lock UnmappedContentWarningGate = new Lock();

		private static readonly HashSet<string> UnmappedContentWarningLoggedKeys = new HashSet<string>(StringComparer.Ordinal);

		private static Dictionary<string, string>? _cache;

		public static bool TryOverridePath(string prefix, ref string result)
		{
			if (_cache == null)
			{
				_cache = BuildCache();
			}
			if (!_cache.TryGetValue(prefix, out string value))
			{
				return true;
			}
			result = value;
			return false;
		}

		private static Dictionary<string, string> BuildCache()
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
			foreach (CharacterModel modCharacter in ModContentRegistry.GetModCharacters())
			{
				AddPoolIfMapped(dictionary, (IPoolModel)(object)modCharacter.CardPool);
			}
			CardPoolModel[] array = ModelDb.AllCardPools.ToArray();
			CardPoolModel[] array2 = array;
			foreach (CardPoolModel pool in array2)
			{
				AddPoolIfMapped(dictionary, (IPoolModel)(object)pool);
			}
			WarnUnmappedCards(array);
			RelicPoolModel[] array3 = ModelDb.AllRelicPools.ToArray();
			RelicPoolModel[] array4 = array3;
			foreach (RelicPoolModel pool2 in array4)
			{
				AddPoolIfMapped(dictionary, (IPoolModel)(object)pool2);
			}
			WarnUnmappedRelics(array3);
			PotionPoolModel[] array5 = ModelDb.AllPotionPools.ToArray();
			PotionPoolModel[] array6 = array5;
			foreach (PotionPoolModel pool3 in array6)
			{
				AddPoolIfMapped(dictionary, (IPoolModel)(object)pool3);
			}
			WarnUnmappedPotions(array5);
			return dictionary;
		}

		private static void WarnUnmappedCards(CardPoolModel[] pools)
		{
			foreach (CardModel card in ModelDb.AllCards)
			{
				if (!pools.Any((CardPoolModel pool) => pool.AllCardIds.Contains(((AbstractModel)card).Id)))
				{
					WarnUnmappedContentOnce("card", ((AbstractModel)card).Id);
				}
			}
		}

		private static void WarnUnmappedRelics(RelicPoolModel[] pools)
		{
			foreach (RelicModel relic in ModelDb.AllRelics)
			{
				if (!pools.Any((RelicPoolModel pool) => pool.AllRelicIds.Contains(((AbstractModel)relic).Id)))
				{
					WarnUnmappedContentOnce("relic", ((AbstractModel)relic).Id);
				}
			}
		}

		private static void WarnUnmappedPotions(PotionPoolModel[] pools)
		{
			foreach (PotionModel potion in ModelDb.AllPotions)
			{
				if (!pools.Any((PotionPoolModel pool) => pool.AllPotionIds.Contains(((AbstractModel)potion).Id)))
				{
					WarnUnmappedContentOnce("potion", ((AbstractModel)potion).Id);
				}
			}
		}

		private static void WarnUnmappedContentOnce(string contentType, ModelId id)
		{
			string item = contentType + "\0" + (object)id;
			using (UnmappedContentWarningGate.EnterScope())
			{
				if (!UnmappedContentWarningLoggedKeys.Add(item))
				{
					return;
				}
			}
			RitsuLibFramework.Logger.Warn($"[Content] {contentType} '{id}' is registered in ModelDb but is not contained in any {contentType} pool. " + "Skipping it while building energy icon overrides.", 1);
		}

		private static void AddPoolIfMapped(Dictionary<string, string> dict, IPoolModel pool)
		{
			if (pool is IModBigEnergyIconPool modBigEnergyIconPool && !string.IsNullOrWhiteSpace(modBigEnergyIconPool.BigEnergyIconPath) && AssetPathDiagnostics.Exists(modBigEnergyIconPool.BigEnergyIconPath, pool, "BigEnergyIconPath"))
			{
				dict.TryAdd(pool.EnergyColorName, modBigEnergyIconPool.BigEnergyIconPath);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Replaces the base game's hard-coded act list for Ancient relic categories with the runtime
	///         <see cref="P:MegaCrit.Sts2.Core.Models.ModelDb.Acts" /> sequence, allowing registered mod acts to contribute their own categories.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将游戏中用于先古遗物分类的硬编码章节列表替换为运行时 <see cref="P:MegaCrit.Sts2.Core.Models.ModelDb.Acts" /> 序列，
	///         使已注册的模组章节能够提供自己的分类。
	///     </para>
	/// </summary>
	internal class RelicCollectionActListPatch : IPatchMethod
	{
		private static readonly MethodInfo ModelDbActsGetter = AccessTools.PropertyGetter(typeof(ModelDb), "Acts");

		private static readonly MethodInfo RuntimeActListMethod = AccessTools.DeclaredMethod(typeof(RelicCollectionActListPatch), "GetRuntimeActList", (Type[])null, (Type[])null);

		public static string PatchId => "relic_collection_runtime_act_list";

		public static string Description => "Use runtime ModelDb.Acts for relic collection ancient categories";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NRelicCollectionCategory), "LoadRelics")
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Stores the runtime act list in the local variable that the base game later uses to generate Ancient categories.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将运行时章节列表存入游戏随后用于生成先古分类的局部变量。
		///     </para>
		/// </summary>
		[HarmonyAfter(new string[] { "BaseLib" })]
		[HarmonyPriority(0)]
		public static IEnumerable<CodeInstruction> Transpiler(IEnumerable<CodeInstruction> instructions)
		{
			HarmonyIlRewriter harmonyIlRewriter = HarmonyIlRewriter.From(instructions);
			if (harmonyIlRewriter.Contains((CodeInstruction instruction) => HarmonyIl.IsCallTo(instruction, RuntimeActListMethod)))
			{
				return harmonyIlRewriter.InstructionsChecked("[RelicCollection] Replace hard-coded ancient act list");
			}
			if (TryFindVanillaActListStore(harmonyIlRewriter, out var match))
			{
				harmonyIlRewriter.InsertBefore(match, new global::<>z__ReadOnlyArray<CodeInstruction>((CodeInstruction[])(object)new CodeInstruction[2]
				{
					HarmonyIl.Pop(),
					HarmonyIl.Call(RuntimeActListMethod)
				}));
				return harmonyIlRewriter.InstructionsChecked("[RelicCollection] Replace hard-coded ancient act list");
			}
			if (!harmonyIlRewriter.Contains(IsActListErrorString) && harmonyIlRewriter.Contains(IsModelDbActsCall))
			{
				return harmonyIlRewriter.InstructionsChecked("[RelicCollection] Replace hard-coded ancient act list");
			}
			RitsuLibFramework.Logger.Warn("[RelicCollection] Could not find vanilla act-list validation pattern; runtime act list patch skipped.", 1);
			return harmonyIlRewriter.Instructions();
		}

		private static List<ActModel> GetRuntimeActList()
		{
			return (from item in ModelDb.Acts.DistinctBy((ActModel act) => ((AbstractModel)act).Id).Select((ActModel act, int index) => new
				{
					Act = act,
					Index = index
				})
				orderby GetVanillaActOrder(item.Act), item.Index
				select item.Act).ToList();
		}

		private static int GetVanillaActOrder(ActModel act)
		{
			if (!(act is Overgrowth))
			{
				if (!(act is Underdocks))
				{
					if (!(act is Hive))
					{
						if (act is Glory)
						{
							return 3;
						}
						return 4;
					}
					return 2;
				}
				return 1;
			}
			return 0;
		}

		private static bool IsModelDbActsCall(CodeInstruction instruction)
		{
			return HarmonyIl.IsCall(ModelDbActsGetter)(instruction);
		}

		private static bool IsLinqCall(CodeInstruction instruction, string methodName)
		{
			return HarmonyIl.IsCall((MethodInfo method) => method.DeclaringType == typeof(Enumerable) && method.Name == methodName && (!method.IsGenericMethod || Enumerable.Contains<Type>(method.GetGenericArguments(), typeof(ActModel))))(instruction);
		}

		private static bool IsActListErrorString(CodeInstruction instruction)
		{
			return HarmonyIl.OperandMatches(instruction, (string value) => value.Contains("act list", StringComparison.OrdinalIgnoreCase));
		}

		private static bool TryFindVanillaActListStore(HarmonyIlRewriter rewriter, out HarmonyIlMatch match)
		{
			foreach (HarmonyIlMatch item in rewriter.FindAll(IsActListErrorString, "relic collection act-list error string").Items)
			{
				if (rewriter.TryFindBefore(item, (CodeInstruction instruction) => IsLinqCall(instruction, "Any"), out var match2) && rewriter.TryFindBefore(match2, (CodeInstruction instruction) => IsLinqCall(instruction, "Except"), out var match3) && rewriter.TryFindBefore(match3, IsModelDbActsCall, out var match4) && rewriter.TryFindBefore(match4, (CodeInstruction instruction) => CodeInstructionExtensions.IsStloc(instruction, (LocalBuilder)null), out match))
				{
					return true;
				}
			}
			match = default(HarmonyIlMatch);
			return false;
		}
	}
