	/// <summary>
	///     <para xml:lang="en">Defines runtime refresh categories for supported node-level visual reloads.</para>
	///     <para xml:lang="zh-CN">定义运行时支持按节点重新加载视觉效果的刷新类别。</para>
	/// </summary>
	[Flags]
	public enum RuntimeAssetRefreshScope
	{
		/// <summary>
		///     <para xml:lang="en">Requests no refresh.</para>
		///     <para xml:lang="zh-CN">不请求刷新。</para>
		/// </summary>
		None = 0,
		/// <summary>
		///     <para xml:lang="en">Reloads card visuals.</para>
		///     <para xml:lang="zh-CN">重新加载卡牌视觉效果。</para>
		/// </summary>
		Cards = 1,
		/// <summary>
		///     <para xml:lang="en">Reloads relic visuals.</para>
		///     <para xml:lang="zh-CN">重新加载遗物视觉效果。</para>
		/// </summary>
		Relics = 2,
		/// <summary>
		///     <para xml:lang="en">Reloads potion visuals.</para>
		///     <para xml:lang="zh-CN">重新加载药水视觉效果。</para>
		/// </summary>
		Potions = 4,
		/// <summary>
		///     <para xml:lang="en">Reloads power visuals.</para>
		///     <para xml:lang="zh-CN">重新加载能力视觉效果。</para>
		/// </summary>
		Powers = 8,
		/// <summary>
		///     <para xml:lang="en">Reloads orb visuals.</para>
		///     <para xml:lang="zh-CN">重新加载充能球视觉效果。</para>
		/// </summary>
		Orbs = 0x10,
		/// <summary>
		///     <para xml:lang="en">Refreshes every category currently supported by the runtime coordinator.</para>
		///     <para xml:lang="zh-CN">刷新运行时协调器当前支持的所有类别。</para>
		/// </summary>
		AllSafe = Cards | Relics | Potions | Powers | Orbs
	}
	/// <summary>
	///     <para xml:lang="en">Coalesces runtime visual refresh requests for supported node types.</para>
	///     <para xml:lang="zh-CN">合并针对受支持节点类型的运行时视觉刷新请求。</para>
	/// </summary>
	public static class RuntimeAssetRefreshCoordinator
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly Action<NCard>? ReloadCard = AccessTools.Method(typeof(NCard), "Reload", (Type[])null, (Type[])null)?.CreateDelegate<Action<NCard>>();

		private static RuntimeAssetRefreshScope _pendingScope;

		private static bool _flushScheduled;

		private static readonly List<Predicate<CardModel>> PendingCardRules = new List<Predicate<CardModel>>();

		private static readonly List<Predicate<RelicModel>> PendingRelicRules = new List<Predicate<RelicModel>>();

		private static readonly List<Predicate<PotionModel>> PendingPotionRules = new List<Predicate<PotionModel>>();

		private static readonly List<Predicate<PowerModel>> PendingPowerRules = new List<Predicate<PowerModel>>();

		private static readonly List<Predicate<OrbModel>> PendingOrbRules = new List<Predicate<OrbModel>>();

		/// <summary>
		///     <para xml:lang="en">Requests a deferred refresh pass for the specified <paramref name="scope" />.</para>
		///     <para xml:lang="zh-CN">为指定的 <paramref name="scope" /> 请求一次延迟刷新。</para>
		/// </summary>
		public static void Request(RuntimeAssetRefreshScope scope = RuntimeAssetRefreshScope.AllSafe)
		{
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			//IL_005a: Unknown result type (might be due to invalid IL or missing references)
			if (scope == RuntimeAssetRefreshScope.None)
			{
				return;
			}
			bool flag;
			using (SyncRoot.EnterScope())
			{
				_pendingScope |= scope;
				if (_flushScheduled)
				{
					return;
				}
				_flushScheduled = true;
				flag = true;
			}
			if (flag)
			{
				Callable val = Callable.From((Action)FlushPending);
				((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			}
		}

		/// <summary>
		///     <para xml:lang="en">Requests card-node reloads for cards matched by <paramref name="rule" />.</para>
		///     <para xml:lang="zh-CN">请求重新加载 <paramref name="rule" /> 所匹配卡牌的节点。</para>
		/// </summary>
		public static void RequestCardsWhere(Predicate<CardModel> rule)
		{
			ArgumentNullException.ThrowIfNull(rule, "rule");
			EnqueueRule(PendingCardRules, rule, RuntimeAssetRefreshScope.Cards);
		}

		/// <summary>
		///     <para xml:lang="en">Requests relic-node reloads for relics matched by <paramref name="rule" />.</para>
		///     <para xml:lang="zh-CN">请求重新加载 <paramref name="rule" /> 所匹配遗物的节点。</para>
		/// </summary>
		public static void RequestRelicsWhere(Predicate<RelicModel> rule)
		{
			ArgumentNullException.ThrowIfNull(rule, "rule");
			EnqueueRule(PendingRelicRules, rule, RuntimeAssetRefreshScope.Relics);
		}

		/// <summary>
		///     <para xml:lang="en">Requests potion-node reloads for potions matched by <paramref name="rule" />.</para>
		///     <para xml:lang="zh-CN">请求重新加载 <paramref name="rule" /> 所匹配药水的节点。</para>
		/// </summary>
		public static void RequestPotionsWhere(Predicate<PotionModel> rule)
		{
			ArgumentNullException.ThrowIfNull(rule, "rule");
			EnqueueRule(PendingPotionRules, rule, RuntimeAssetRefreshScope.Potions);
		}

		/// <summary>
		///     <para xml:lang="en">Requests power-node reloads for powers matched by <paramref name="rule" />.</para>
		///     <para xml:lang="zh-CN">请求重新加载 <paramref name="rule" /> 所匹配能力的节点。</para>
		/// </summary>
		public static void RequestPowersWhere(Predicate<PowerModel> rule)
		{
			ArgumentNullException.ThrowIfNull(rule, "rule");
			EnqueueRule(PendingPowerRules, rule, RuntimeAssetRefreshScope.Powers);
		}

		/// <summary>
		///     <para xml:lang="en">Requests orb-node visual updates for orbs matched by <paramref name="rule" />.</para>
		///     <para xml:lang="zh-CN">请求更新 <paramref name="rule" /> 所匹配充能球的节点视觉效果。</para>
		/// </summary>
		public static void RequestOrbsWhere(Predicate<OrbModel> rule)
		{
			ArgumentNullException.ThrowIfNull(rule, "rule");
			EnqueueRule(PendingOrbRules, rule, RuntimeAssetRefreshScope.Orbs);
		}

		private static void FlushPending()
		{
			RuntimeAssetRefreshScope pendingScope;
			Predicate<CardModel>[] rules;
			Predicate<RelicModel>[] rules2;
			Predicate<PotionModel>[] rules3;
			Predicate<PowerModel>[] rules4;
			Predicate<OrbModel>[] rules5;
			using (SyncRoot.EnterScope())
			{
				pendingScope = _pendingScope;
				_pendingScope = RuntimeAssetRefreshScope.None;
				_flushScheduled = false;
				rules = PendingCardRules.ToArray();
				rules2 = PendingRelicRules.ToArray();
				rules3 = PendingPotionRules.ToArray();
				rules4 = PendingPowerRules.ToArray();
				rules5 = PendingOrbRules.ToArray();
				PendingCardRules.Clear();
				PendingRelicRules.Clear();
				PendingPotionRules.Clear();
				PendingPowerRules.Clear();
				PendingOrbRules.Clear();
			}
			if (pendingScope == RuntimeAssetRefreshScope.None)
			{
				return;
			}
			MainLoop mainLoop = Engine.GetMainLoop();
			SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
			if (val == null || !GodotObject.IsInstanceValid((GodotObject)(object)val.Root))
			{
				return;
			}
			foreach (Node item in EnumerateDescendants((Node)(object)val.Root))
			{
				if ((pendingScope & RuntimeAssetRefreshScope.Cards) != RuntimeAssetRefreshScope.None)
				{
					NCard val2 = (NCard)(object)((item is NCard) ? item : null);
					if (val2 != null)
					{
						if (val2.Model != null && ShouldApply(val2.Model, rules))
						{
							ReloadCard?.Invoke(val2);
						}
						continue;
					}
				}
				if ((pendingScope & RuntimeAssetRefreshScope.Relics) != RuntimeAssetRefreshScope.None)
				{
					NRelic val3 = (NRelic)(object)((item is NRelic) ? item : null);
					if (val3 != null)
					{
						if (ShouldApply(val3.Model, rules2))
						{
							val3.Model = val3.Model;
						}
						continue;
					}
				}
				if ((pendingScope & RuntimeAssetRefreshScope.Potions) != RuntimeAssetRefreshScope.None)
				{
					NPotion val4 = (NPotion)(object)((item is NPotion) ? item : null);
					if (val4 != null)
					{
						if (ShouldApply(val4.Model, rules3))
						{
							val4.Model = val4.Model;
						}
						continue;
					}
				}
				if ((pendingScope & RuntimeAssetRefreshScope.Powers) != RuntimeAssetRefreshScope.None)
				{
					NPower val5 = (NPower)(object)((item is NPower) ? item : null);
					if (val5 != null)
					{
						if (ShouldApply(val5.Model, rules4))
						{
							val5.Model = val5.Model;
						}
						continue;
					}
				}
				if ((pendingScope & RuntimeAssetRefreshScope.Orbs) != RuntimeAssetRefreshScope.None)
				{
					NOrb val6 = (NOrb)(object)((item is NOrb) ? item : null);
					if (val6 != null && ShouldApply(val6.Model, rules5))
					{
						val6.UpdateVisuals(false);
					}
				}
			}
		}

		private static void EnqueueRule<TModel>(List<Predicate<TModel>> bucket, Predicate<TModel> rule, RuntimeAssetRefreshScope scope) where TModel : class
		{
			//IL_0058: Unknown result type (might be due to invalid IL or missing references)
			//IL_005d: Unknown result type (might be due to invalid IL or missing references)
			bool flag;
			using (SyncRoot.EnterScope())
			{
				bucket.Add(rule);
				_pendingScope |= scope;
				if (_flushScheduled)
				{
					return;
				}
				_flushScheduled = true;
				flag = true;
			}
			if (flag)
			{
				Callable val = Callable.From((Action)FlushPending);
				((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			}
		}

		private static bool ShouldApply<TModel>(TModel? model, IReadOnlyList<Predicate<TModel>> rules) where TModel : class
		{
			if (model == null)
			{
				return false;
			}
			if (rules.Count == 0)
			{
				return true;
			}
			foreach (Predicate<TModel> rule in rules)
			{
				try
				{
					if (rule(model))
					{
						return true;
					}
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn("[Assets] Refresh rule failed: " + ex.Message, 1);
				}
			}
			return false;
		}

		private static IEnumerable<Node> EnumerateDescendants(Node root)
		{
			Stack<Node> stack = new Stack<Node>();
			stack.Push(root);
			while (stack.Count > 0)
			{
				Node current = stack.Pop();
				if (!GodotObject.IsInstanceValid((GodotObject)(object)current))
				{
					continue;
				}
				yield return current;
				for (int num = current.GetChildCount(false) - 1; num >= 0; num--)
				{
					Node child = current.GetChild(num, false);
					if (child != null)
					{
						stack.Push(child);
					}
				}
			}
		}
	}
}
namespace STS2RitsuLib.Scaffolding.Combat
{
	/// <summary>
	///     <para xml:lang="en">
	///         Provides compatibility extensions for querying the current player turn phase.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供用于查询当前玩家回合阶段的兼容扩展方法。
	///     </para>
	/// </summary>
	public static class CombatTurnPhaseExtensions
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether the owner of <paramref name="model" /> is currently in the
		///         <see cref="F:MegaCrit.Sts2.Core.Combat.PlayerTurnPhase.Play" /> phase.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <paramref name="model" /> 的拥有者当前是否处于
		///         <see cref="F:MegaCrit.Sts2.Core.Combat.PlayerTurnPhase.Play" /> 阶段。
		///     </para>
		/// </summary>
		public static bool IsOwnerPlayPhase(this CardModel model)
		{
			//IL_002b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0038: Unknown result type (might be due to invalid IL or missing references)
			//IL_003e: Invalid comparison between Unknown and I4
			ArgumentNullException.ThrowIfNull(model, "model");
			Player owner = model.Owner;
			if (owner == null)
			{
				return false;
			}
			PlayerCombatState playerCombatState = owner.PlayerCombatState;
			return (int)((playerCombatState != null) ? new PlayerTurnPhase?(playerCombatState.Phase) : ((PlayerTurnPhase?)null)).GetValueOrDefault() == 3;
		}
	}
}
namespace STS2RitsuLib.Scaffolding.Characters
{
	/// <summary>
	///     <para xml:lang="en">
	///         Builds vanilla-layout resource paths from a character model entry.
	///     </para>
	///     <para xml:lang="zh-CN">根据角色模型条目构建符合原版布局的资源路径。</para>
	/// </summary>
	public static class CharacterAssetPathHelper
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets the energy icon path for <paramref name="energyColorName" /> through
		///         <see cref="T:MegaCrit.Sts2.Core.Helpers.EnergyIconHelper" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过 <see cref="T:MegaCrit.Sts2.Core.Helpers.EnergyIconHelper" /> 获取 <paramref name="energyColorName" /> 的能量图标路径。
		///     </para>
		/// </summary>
		public static string GetEnergyIconPath(string energyColorName)
		{
			return EnergyIconHelper.GetPath(energyColorName);
		}

		/// <summary>
		///     <para xml:lang="en">Gets the combat energy counter scene path.</para>
		///     <para xml:lang="zh-CN">获取战斗能量计数器的场景路径。</para>
		/// </summary>
		public static string GetEnergyCounterPath(string characterEntry)
		{
			return SceneHelper.GetScenePath("combat/energy_counters/" + Normalize(characterEntry) + "_energy_counter");
		}

		/// <summary>
		///     <para xml:lang="en">Gets the combat creature-visuals scene path.</para>
		///     <para xml:lang="zh-CN">获取战斗生物视觉节点的场景路径。</para>
		/// </summary>
		public static string GetVisualsPath(string characterEntry)
		{
			return SceneHelper.GetScenePath("creature_visuals/" + Normalize(characterEntry));
		}

		/// <summary>
		///     <para xml:lang="en">Gets the character-select background scene path.</para>
		///     <para xml:lang="zh-CN">获取角色选择背景的场景路径。</para>
		/// </summary>
		public static string GetCharacterSelectBackgroundPath(string characterEntry)
		{
			return SceneHelper.GetScenePath("screens/char_select/char_select_bg_" + Normalize(characterEntry));
		}

		/// <summary>
		///     <para xml:lang="en">Gets the unlocked character-select portrait path.</para>
		///     <para xml:lang="zh-CN">获取已解锁角色选择肖像的路径。</para>
		/// </summary>
		public static string GetCharacterSelectIconPath(string characterEntry)
		{
			return ImageHelper.GetImagePath("packed/character_select/char_select_" + Normalize(characterEntry) + ".png");
		}

		/// <summary>
		///     <para xml:lang="en">Gets the locked character-select portrait path.</para>
		///     <para xml:lang="zh-CN">获取未解锁角色选择肖像的路径。</para>
		/// </summary>
		public static string GetCharacterSelectLockedIconPath(string characterEntry)
		{
			return ImageHelper.GetImagePath("packed/character_select/char_select_" + Normalize(characterEntry) + "_locked.png");
		}

		/// <summary>
		///     <para xml:lang="en">Gets the character's map marker path.</para>
		///     <para xml:lang="zh-CN">获取角色的地图标记路径。</para>
		/// </summary>
		public static string GetMapMarkerPath(string characterEntry)
		{
			return ImageHelper.GetImagePath("packed/map/icons/map_marker_" + Normalize(characterEntry) + ".png");
		}

		/// <summary>
		///     <para xml:lang="en">Gets the character's card-trail VFX scene path.</para>
		///     <para xml:lang="zh-CN">获取角色卡牌轨迹特效的场景路径。</para>
		/// </summary>
		public static string GetTrailPath(string characterEntry)
		{
			return SceneHelper.GetScenePath("vfx/card_trail_" + Normalize(characterEntry));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Enumerates the standard character asset paths derived from <paramref name="characterEntry" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         枚举根据 <paramref name="characterEntry" /> 派生的标准角色资源路径。
		///     </para>
		/// </summary>
		public static IEnumerable<string> EnumerateDefaultCharacterAssets(string characterEntry)
		{
			yield return GetVisualsPath(characterEntry);
			yield return GetCharacterSelectBackgroundPath(characterEntry);
			yield return GetCharacterSelectIconPath(characterEntry);
			yield return GetCharacterSelectLockedIconPath(characterEntry);
			yield return GetMapMarkerPath(characterEntry);
			yield return GetTrailPath(characterEntry);
			yield return GetEnergyCounterPath(characterEntry);
		}

		private static string Normalize(string value)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(value, "value");
			return value.Trim().ToLowerInvariant();
		}
	}
