	/// <summary>
	///     <para xml:lang="en">
	///         Provides common power, orb, and energy queries for <see cref="T:MegaCrit.Sts2.Core.Entities.Creatures.Creature" /> and <see cref="T:MegaCrit.Sts2.Core.Entities.Players.Player" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供用于查询 <see cref="T:MegaCrit.Sts2.Core.Entities.Creatures.Creature" /> 与 <see cref="T:MegaCrit.Sts2.Core.Entities.Players.Player" /> 能力、充能球和能量的常用方法。
	///     </para>
	/// </summary>
	public static class CharacterCombatExtensions
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Returns the first power of type <typeparamref name="TPower" />, or <see langword="null" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回第一个 <typeparamref name="TPower" /> 类型的能力；不存在时返回
		///         <see langword="null" />。
		///     </para>
		/// </summary>
		public static TPower? FindPower<TPower>(this Creature creature) where TPower : PowerModel
		{
			ArgumentNullException.ThrowIfNull(creature, "creature");
			return creature.Powers.OfType<TPower>().FirstOrDefault();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether the creature has at least <paramref name="minimumAmount" /> stacks of
		///         <typeparamref name="TPower" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回生物是否至少拥有 <paramref name="minimumAmount" /> 层
		///         <typeparamref name="TPower" />。
		///     </para>
		/// </summary>
		public static bool HasPower<TPower>(this Creature creature, int minimumAmount = 1) where TPower : PowerModel
		{
			ArgumentNullException.ThrowIfNull(creature, "creature");
			object obj = creature.FindPower<TPower>();
			if (obj == null)
			{
				return false;
			}
			return ((PowerModel)obj).Amount >= minimumAmount;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the current <typeparamref name="TPower" /> amount, or zero when absent.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <typeparamref name="TPower" /> 的当前层数；不存在时返回零。
		///     </para>
		/// </summary>
		public static int GetPowerAmount<TPower>(this Creature creature) where TPower : PowerModel
		{
			ArgumentNullException.ThrowIfNull(creature, "creature");
			object obj = creature.FindPower<TPower>();
			if (obj == null)
			{
				return 0;
			}
			return ((PowerModel)obj).Amount;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether the player's orb queue contains an orb of type <typeparamref name="TOrb" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回玩家的充能球队列中是否包含 <typeparamref name="TOrb" /> 类型的充能球。
		///     </para>
		/// </summary>
		public static bool HasOrb<TOrb>(this Player player) where TOrb : OrbModel
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			PlayerCombatState playerCombatState = player.PlayerCombatState;
			if (playerCombatState == null)
			{
				return false;
			}
			return playerCombatState.OrbQueue.Orbs.OfType<TOrb>().Any();
		}

		/// <summary>
		///     <para xml:lang="en">Counts <typeparamref name="TOrb" /> instances in the player's orb queue.</para>
		///     <para xml:lang="zh-CN">
		///         统计玩家充能球队列中 <typeparamref name="TOrb" /> 类型的充能球数量。
		///     </para>
		/// </summary>
		public static int GetOrbCount<TOrb>(this Player player) where TOrb : OrbModel
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			PlayerCombatState playerCombatState = player.PlayerCombatState;
			if (playerCombatState == null)
			{
				return 0;
			}
			return playerCombatState.OrbQueue.Orbs.OfType<TOrb>().Count();
		}

		/// <summary>
		///     <para xml:lang="en">Returns current combat energy, or zero outside combat.</para>
		///     <para xml:lang="zh-CN">返回当前战斗能量；不在战斗中时返回零。</para>
		/// </summary>
		public static int GetEnergy(this Player player)
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			PlayerCombatState playerCombatState = player.PlayerCombatState;
			if (playerCombatState == null)
			{
				return 0;
			}
			return playerCombatState.Energy;
		}

		/// <summary>
		///     <para xml:lang="en">Returns maximum combat energy, or zero outside combat.</para>
		///     <para xml:lang="zh-CN">返回战斗中的最大能量；不在战斗中时返回零。</para>
		/// </summary>
		public static int GetMaxEnergy(this Player player)
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			PlayerCombatState playerCombatState = player.PlayerCombatState;
			if (playerCombatState == null)
			{
				return 0;
			}
			return playerCombatState.MaxEnergy;
		}

		/// <summary>
		///     <para xml:lang="en">Returns combat orb capacity, or zero outside combat.</para>
		///     <para xml:lang="zh-CN">返回战斗中的充能球槽位数；不在战斗中时返回零。</para>
		/// </summary>
		public static int GetOrbCapacity(this Player player)
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			PlayerCombatState playerCombatState = player.PlayerCombatState;
			if (playerCombatState == null)
			{
				return 0;
			}
			return playerCombatState.OrbQueue.Capacity;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Allows a character to customize the placement of its card-pool filter in the Card Library compendium.
	///     </para>
	///     <para xml:lang="zh-CN">允许角色自定义其牌池筛选项在卡牌总览中的位置。</para>
	/// </summary>
	public interface IModCharacterCardLibraryCompendiumPlacement
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Placement rules in priority order. The first resolvable base-game anchor determines the initial
		///         index, after which constraints relative to other mod characters are applied. A
		///         <see langword="null" /> or empty list uses the default character rules.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         按优先级排列的位置规则。首个可解析的原版锚点决定初始索引，之后再应用相对于其他模组角色
		///         的约束；列表为 <see langword="null" /> 或空时使用默认角色规则。
		///     </para>
		/// </summary>
		IReadOnlyList<CardLibraryCompendiumPlacementRule>? CardLibraryCompendiumPlacementRules { get; }
	}
