	///     <para xml:lang="en">Registered potion pool type.</para>
	///     <para xml:lang="zh-CN">已注册的药水池类型。</para>
	/// </typeparam>
	public abstract class ModCharacterTemplate<TCardPool, TRelicPool, TPotionPool> : CharacterModel, IModCharacterAssetOverrides, IModCreatureVisualsFactory, IModCharacterCreatureVisualsFactory, IModCreatureAnimatorFactory, IModCharacterCreatureAnimatorFactory, IModCreatureCombatAnimationStateMachineFactory, IModNonSpineAnimationStateMachineFactory, IModCharacterMerchantAnimationStateMachineFactory, IModCharacterRestSiteAnimationStateMachineFactory, IModCharacterEpochTimelineRequirement, IModCharacterVanillaSelectionPolicy, IModCharacterCardLibraryCompendiumPlacement, IModCharacterUnlockPrerequisite where TCardPool : CardPoolModel where TRelicPool : RelicPoolModel where TPotionPool : PotionPoolModel
	{
		/// <inheritdoc />
		public override string CharacterSelectSfx => CustomCharacterSelectSfx ?? ((CharacterModel)this).CharacterSelectSfx;

		/// <inheritdoc />
		public override string CharacterTransitionSfx => CustomCharacterTransitionSfx ?? ((CharacterModel)this).CharacterTransitionSfx;

		/// <inheritdoc />
		protected override string CharacterSelectIconPath => CustomCharacterSelectIconPath ?? ((CharacterModel)this).CharacterSelectIconPath;

		/// <inheritdoc />
		protected override string CharacterSelectLockedIconPath => CustomCharacterSelectLockedIconPath ?? ((CharacterModel)this).CharacterSelectLockedIconPath;

		/// <inheritdoc />
