		///     <para xml:lang="zh-CN">获取已注册的 <typeparamref name="TPotionPool" /> 实例。</para>
		/// </summary>
		public sealed override PotionPoolModel PotionPool => ModelDb.GetById<PotionPoolModel>(ModelDb.GetId<TPotionPool>());

		/// <inheritdoc />
		public sealed override IEnumerable<CardModel> StartingDeck => ResolveStartingDeck();

		/// <inheritdoc />
		public sealed override IReadOnlyList<RelicModel> StartingRelics => ResolveStartingRelics();

		/// <inheritdoc />
		public sealed override IReadOnlyList<PotionModel> StartingPotions => ResolveStartingPotions();

		/// <inheritdoc />
		protected sealed override CharacterModel? UnlocksAfterRunAs
		{
			get
			{
				if (!(UnlocksAfterRunAsType == null))
				{
					return ModelDb.GetById<CharacterModel>(ModelDb.GetId(UnlocksAfterRunAsType));
				}
				return null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Starting deck supplied by the character class. Registered additions are appended afterward.
		///     </para>
		///     <para xml:lang="zh-CN">角色类提供的初始牌组；之后会追加通过注册表添加的卡牌。</para>
		/// </summary>
		protected virtual IEnumerable<CardModel> LocalStartingDeck
		{
			get
			{
				List<CardModel> list = new List<CardModel>();
				list.AddRange(from type in StartingDeckEntries.SelectMany((StartingDeckEntry entry) => Enumerable.Repeat(entry.CardType, Math.Max(entry.Count, 0)))
					select ModelDb.GetById<CardModel>(ModelDb.GetId(type)));
				return new <>z__ReadOnlyList<CardModel>(list);
			}
		}

