		/// <summary>
		///     <para xml:lang="en">Resolves model types to registered <typeparamref name="TModel" /> instances.</para>
		///     <para xml:lang="zh-CN">将模型类型解析为已注册的 <typeparamref name="TModel" /> 实例。</para>
		/// </summary>
		protected static IEnumerable<TModel> ResolveModels<TModel>(IEnumerable<Type> types) where TModel : AbstractModel
		{
			List<TModel> list = new List<TModel>();
			list.AddRange(types.Select((Type type) => ModelDb.GetById<TModel>(ModelDb.GetId(type))));
			return new <>z__ReadOnlyList<TModel>(list);
		}

		private IEnumerable<CardModel> ResolveStartingDeck()
		{
			Type[] registeredCharacterStarterCards = ModContentRegistry.GetRegisteredCharacterStarterCards(((object)this).GetType());
			List<CardModel> list = new List<CardModel>();
			list.AddRange(LocalStartingDeck);
			list.AddRange(ResolveModels<CardModel>((IEnumerable<Type>)registeredCharacterStarterCards));
			return new <>z__ReadOnlyList<CardModel>(list);
		}

		private IReadOnlyList<RelicModel> ResolveStartingRelics()
		{
			Type[] registeredCharacterStarterRelics = ModContentRegistry.GetRegisteredCharacterStarterRelics(((object)this).GetType());
			List<RelicModel> list = new List<RelicModel>();
			list.AddRange(LocalStartingRelics);
			list.AddRange(ResolveModels<RelicModel>((IEnumerable<Type>)registeredCharacterStarterRelics));
			return new <>z__ReadOnlyList<RelicModel>(list);
		}

		private IReadOnlyList<PotionModel> ResolveStartingPotions()
		{
			Type[] registeredCharacterStarterPotions = ModContentRegistry.GetRegisteredCharacterStarterPotions(((object)this).GetType());
			List<PotionModel> list = new List<PotionModel>();
			list.AddRange(LocalStartingPotions);
			list.AddRange(ResolveModels<PotionModel>((IEnumerable<Type>)registeredCharacterStarterPotions));
			return new <>z__ReadOnlyList<PotionModel>(list);
		}
	}
	internal static class ModCharacterTimelinePolicy
	{
		private static readonly Lock Gate = new Lock();

		private static readonly HashSet<Type> WarnedUnregisteredTypes = new HashSet<Type>();

		internal static bool IsOwnedOrUsesTimelinePolicy(CharacterModel character)
		{
			ArgumentNullException.ThrowIfNull(character, "character");
			if (ModContentRegistry.TryGetOwnerModId(((object)character).GetType(), out string _))
			{
				return true;
			}
			if (!(character is IModCharacterEpochTimelineRequirement))
			{
				return false;
			}
			WarnUnregisteredInterfaceUse(character);
			return true;
		}

		internal static bool TryGetRequiresEpochAndTimeline(CharacterModel character, out bool requires)
		{
			ArgumentNullException.ThrowIfNull(character, "character");
			if (character is IModCharacterEpochTimelineRequirement modCharacterEpochTimelineRequirement)
			{
				WarnUnregisteredInterfaceUse(character);
				requires = modCharacterEpochTimelineRequirement.RequiresEpochAndTimeline;
				return true;
			}
			requires = true;
			return false;
		}

		internal static bool DoesNotRequireEpochAndTimeline(CharacterModel character)
		{
			if (TryGetRequiresEpochAndTimeline(character, out var requires))
			{
				return !requires;
			}
			return false;
		}

		private static void WarnUnregisteredInterfaceUse(CharacterModel character)
		{
			Type type = ((object)character).GetType();
			if (ModContentRegistry.TryGetOwnerModId(type, out string _))
			{
				return;
			}
			using (Gate.EnterScope())
			{
				if (!WarnedUnregisteredTypes.Add(type))
				{
					return;
				}
			}
			RitsuLibFramework.Logger.Warn($"[Content] Unregistered character uses RitsuLib timeline policy: {((AbstractModel)character).Id} type={type.FullName}", 1);
		}
	}
}
namespace STS2RitsuLib.Scaffolding.Characters.Visuals
{
	/// <summary>
	///     <para xml:lang="en">
	///         Provides shared animation playback for mod creature visuals. It first checks textures and data-driven
	///         frame sequences in <see cref="P:STS2RitsuLib.Scaffolding.Characters.IModCharacterAssetOverrides.VisualCues" />, then tries Spine tracks or
	///         Godot <see cref="T:Godot.AnimationPlayer" />, <see cref="T:Godot.AnimationTree" />, and
	///         <see cref="T:Godot.AnimatedSprite2D" /> nodes as appropriate.
	///     </para>
	///     <para xml:lang="en">
	///         Procedural roots created through <see cref="T:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactories" /> use the same cue aliases and
	///         trigger mapping as the patched <see cref="M:MegaCrit.Sts2.Core.Nodes.Combat.NCreature.SetAnimationTrigger(System.String)" /> path.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为模组生物形象提供统一的动画播放入口。它会先检查
	///         <see cref="P:STS2RitsuLib.Scaffolding.Characters.IModCharacterAssetOverrides.VisualCues" /> 中的纹理和数据驱动帧序列，再根据情况尝试
	///         Spine 轨道或 Godot 的 <see cref="T:Godot.AnimationPlayer" />、<see cref="T:Godot.AnimationTree" /> 及
	///         <see cref="T:Godot.AnimatedSprite2D" /> 节点。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过 <see cref="T:STS2RitsuLib.Scaffolding.Godot.RitsuGodotNodeFactories" /> 创建的程序化根节点，与已补丁处理的
	///         <see cref="M:MegaCrit.Sts2.Core.Nodes.Combat.NCreature.SetAnimationTrigger(System.String)" /> 路径使用相同的提示别名和触发器映射。
	///     </para>
	/// </summary>
	public static class ModCreatureVisualPlayback
	{
		private sealed class RitsuCreatureVisualRegistration
		{
		}

		private sealed class FakeMerchantPlayerVisualSlot
		{
			internal readonly List<NMerchantCharacter> Visuals = new List<NMerchantCharacter>();
		}

		private static readonly ConditionalWeakTable<Node, Func<string[], bool>> GodotAnimHandlers = new ConditionalWeakTable<Node, Func<string[], bool>>();

		private static readonly ConditionalWeakTable<Node, RitsuCreatureVisualRegistration> RitsuCreatureVisuals = new ConditionalWeakTable<Node, RitsuCreatureVisualRegistration>();

		private static readonly FieldRef<NMerchantRoom, List<Player>> MerchantRoomPlayersRef = AccessTools.FieldRefAccess<NMerchantRoom, List<Player>>("_players");

		private static readonly ConditionalWeakTable<NFakeMerchant, FakeMerchantPlayerVisualSlot> FakeMerchantVisualSlots = new ConditionalWeakTable<NFakeMerchant, FakeMerchantPlayerVisualSlot>();

		private static readonly ConditionalWeakTable<NMerchantCharacter, CharacterModel> FakeMerchantBoothCharacter = new ConditionalWeakTable<NMerchantCharacter, CharacterModel>();

		private static readonly string[] DieCueNames = new string[4] { "die", "death", "dead", "Dead" };

		private static readonly string[] IdleCueNames = new string[3] { "idle", "Idle", "relaxed_loop" };

		private static readonly string[] RelaxedCueNames = new string[5] { "relaxed", "Relaxed", "relaxed_loop", "idle", "Idle" };

		private static readonly string[] RestSiteLoopCueNames = new string[5] { "relaxed", "Relaxed", "relaxed_loop", "idle", "Idle" };

		private static readonly string[] HurtCueNames = new string[3] { "hurt", "hit", "Hit" };

		private static readonly string[] AttackCueNames = new string[2] { "attack", "Attack" };

		private static readonly string[] CastCueNames = new string[2] { "cast", "Cast" };

		private static readonly string[] ReviveCueNames = new string[2] { "revive", "Revive" };

		private static readonly string[] StunCueNames = new string[2] { "stun", "Stun" };

		internal static void RegisterRitsuCreatureVisual(Node visual)
		{
			RitsuCreatureVisuals.Remove(visual);
			RitsuCreatureVisuals.Add(visual, new RitsuCreatureVisualRegistration());
		}

		private static bool ShouldOwnCreatureVisualPlayback(NCreature creature)
		{
			NCreatureVisuals visuals = creature.Visuals;
			if (visuals != null && RitsuCreatureVisuals.TryGetValue((Node)(object)visuals, out RitsuCreatureVisualRegistration _))
			{
				return true;
			}
			Creature entity = creature.Entity;
			object obj;
			if (entity == null)
			{
				obj = null;
			}
			else
			{
				Player player = entity.Player;
				obj = ((player != null) ? player.Character : null);
			}
			if (obj is IModCharacterAssetOverrides modCharacterAssetOverrides)
			{
				return (object)modCharacterAssetOverrides.VisualCues != null;
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to play a logical animation cue on combat <see cref="T:MegaCrit.Sts2.Core.Nodes.Combat.NCreatureVisuals" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试在战斗 <see cref="T:MegaCrit.Sts2.Core.Nodes.Combat.NCreatureVisuals" /> 上播放逻辑动画提示。
		///     </para>
		/// </summary>
		/// <param name="visuals">
		///     <para xml:lang="en">The creature-visuals root.</para>
		///     <para xml:lang="zh-CN">生物形象根节点。</para>
		/// </param>
		/// <param name="character">
		///     <para xml:lang="en">The owning character model used to resolve visual cues.</para>
		///     <para xml:lang="zh-CN">用于解析形象提示的所属角色模型。</para>
		/// </param>
		/// <param name="primaryCue">
		///     <para xml:lang="en">The primary cue name, such as <c>die</c>.</para>
		///     <para xml:lang="zh-CN">主要提示名称，例如 <c>die</c>。</para>
		/// </param>
		/// <param name="alternateCueNames">
		///     <para xml:lang="en">Optional cue aliases to try instead of the default aliases.</para>
		///     <para xml:lang="zh-CN">用于替代默认别名进行尝试的可选提示别名。</para>
		/// </param>
		/// <param name="loop">
		///     <para xml:lang="en">Whether Spine playback should loop.</para>
		///     <para xml:lang="zh-CN">Spine 动画是否循环播放。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if any supported playback path applied the cue; otherwise,
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         任一受支持的播放路径成功应用提示时返回 <see langword="true" />；否则返回
		///         <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool TryPlayCue(NCreatureVisuals visuals, CharacterModel? character, string primaryCue, ReadOnlySpan<string> alternateCueNames = default(ReadOnlySpan<string>), bool loop = false)
		{
			if (!GodotObject.IsInstanceValid((GodotObject)(object)visuals) || string.IsNullOrWhiteSpace(primaryCue))
			{
				return false;
			}
			ReadOnlySpan<string> names = ((alternateCueNames.Length > 0) ? alternateCueNames : BuildDefaultAlternateNames(primaryCue));
			CueFrameSequencePlayer.StopUnder((Node?)(object)visuals);
			if (TryApplyVisualCues((Node)(object)visuals, character, names, null))
			{
				return true;
			}
			if (!TryPlaySpine(visuals, names, loop))
			{
				return TryPlayGodotAnimations((Node)(object)visuals, names);
			}
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to play a world-scene animation or static cue on an arbitrary visual root, such as an
		///         <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.Shops.NMerchantCharacter" /> or rest-site character.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试在任意世界场景形象根节点上播放动画或静态提示，例如 <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.Shops.NMerchantCharacter" /> 或
		///         休息处角色。
		///     </para>
		/// </summary>
		/// <param name="root">
		///     <para xml:lang="en">The visual root.</para>
		///     <para xml:lang="zh-CN">形象根节点。</para>
		/// </param>
		/// <param name="character">
		///     <para xml:lang="en">The character model used to resolve visual cues.</para>
		///     <para xml:lang="zh-CN">用于解析形象提示的角色模型。</para>
		/// </param>
		/// <param name="animName">
		///     <para xml:lang="en">The logical animation or cue name.</para>
		///     <para xml:lang="zh-CN">逻辑动画或提示名称。</para>
		/// </param>
		/// <param name="loop">
		///     <para xml:lang="en">Whether Spine playback should loop.</para>
		///     <para xml:lang="zh-CN">Spine 动画是否循环播放。</para>
		/// </param>
		/// <param name="cueSetOverride">
		///     <para xml:lang="en">
		///         An optional cue set to use instead of <see cref="P:STS2RitsuLib.Scaffolding.Characters.IModCharacterAssetOverrides.VisualCues" />, such
		///         as a merchant or rest-site cue set from
		///         <see cref="P:STS2RitsuLib.Scaffolding.Characters.IModCharacterAssetOverrides.WorldProceduralVisuals" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         用于替代 <see cref="P:STS2RitsuLib.Scaffolding.Characters.IModCharacterAssetOverrides.VisualCues" /> 的可选提示集合，例如
		///         <see cref="P:STS2RitsuLib.Scaffolding.Characters.IModCharacterAssetOverrides.WorldProceduralVisuals" /> 中的商人或休息处提示集合。
		///     </para>
		/// </param>
		public static bool TryPlayOnVisualRoot(Node root, CharacterModel? character, string animName, bool loop = false, VisualCueSet? cueSetOverride = null)
		{
			if (!GodotObject.IsInstanceValid((GodotObject)(object)root) || string.IsNullOrWhiteSpace(animName))
			{
				return false;
			}
			ReadOnlySpan<string> names = BuildDefaultAlternateNames(animName);
			CueFrameSequencePlayer.StopUnder(root);
			if (!TryApplyVisualCues(root, character, names, cueSetOverride))
			{
				return TryPlayGodotAnimations(root, names);
			}
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         For a RitsuLib-managed creature without a Spine animator, maps an animator trigger to a cue and
		///         attempts to play it on <see cref="P:MegaCrit.Sts2.Core.Nodes.Combat.NCreature.Visuals" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         对由 RitsuLib 管理且没有 Spine 动画器的生物，将动画器触发器映射为提示，并尝试在
		///         <see cref="P:MegaCrit.Sts2.Core.Nodes.Combat.NCreature.Visuals" /> 上播放。
		///     </para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if the mapped cue was played; otherwise, <see langword="false" />. A
		///         Spine-backed or unmanaged creature always returns <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         成功播放映射后的提示时返回 <see langword="true" />；否则返回 <see langword="false" />。基于 Spine
		///         或不由 RitsuLib 管理的生物始终返回 <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool TryPlayFromCreatureAnimatorTrigger(NCreature creature, string trigger)
		{
			if (creature.HasSpineAnimation || !ShouldOwnCreatureVisualPlayback(creature))
			{
				return false;
			}
			string primaryCue = MapAnimatorTriggerToCue(trigger);
			Creature entity = creature.Entity;
			object obj;
			if (entity == null)
			{
				obj = null;
			}
			else
			{
				Player player = entity.Player;
				obj = ((player != null) ? player.Character : null);
			}
			CharacterModel character = (CharacterModel)obj;
			return TryPlayCue(creature.Visuals, character, primaryCue);
		}

		internal static bool TryGetDurationFromCreatureAnimatorTrigger(NCreature creature, string trigger, out float seconds)
		{
			seconds = 0f;
			if (creature.HasSpineAnimation || !GodotObject.IsInstanceValid((GodotObject)(object)creature.Visuals) || !ShouldOwnCreatureVisualPlayback(creature))
			{
				return false;
			}
			ReadOnlySpan<string> names = BuildDefaultAlternateNames(MapAnimatorTriggerToCue(trigger));
			Creature entity = creature.Entity;
			object character;
			if (entity == null)
			{
				character = null;
			}
			else
			{
				Player player = entity.Player;
				character = ((player != null) ? player.Character : null);
			}
			bool result = TryGetVisualCueDuration((CharacterModel?)character, names, out seconds, out var matched);
			if (!matched)
			{
				return TryGetGodotAnimationDuration((Node)(object)creature.Visuals, names, out seconds);
			}
			return result;
		}

		internal static bool TryResolveMerchantCharacterModel(NMerchantRoom? room, NMerchantCharacter visual, out CharacterModel? character)
		{
			character = null;
			if (room == null)
			{
				return false;
			}
			IReadOnlyList<NMerchantCharacter> playerVisuals = room.PlayerVisuals;
			for (int i = 0; i < playerVisuals.Count; i++)
			{
				if (playerVisuals[i] == visual)
				{
					List<Player> list = MerchantRoomPlayersRef.Invoke(room);
					if (list == null || i >= list.Count)
					{
						return false;
					}
					character = list[i].Character;
					return true;
				}
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves the owning <see cref="T:MegaCrit.Sts2.Core.Models.CharacterModel" /> for a merchant-booth
		///         <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.Shops.NMerchantCharacter" /> in either <see cref="T:MegaCrit.Sts2.Core.Nodes.Rooms.NMerchantRoom" /> or the Fake Merchant event.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         解析 <see cref="T:MegaCrit.Sts2.Core.Nodes.Rooms.NMerchantRoom" /> 或“伪装商人”事件中摊位
		///         <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.Shops.NMerchantCharacter" /> 所属的 <see cref="T:MegaCrit.Sts2.Core.Models.CharacterModel" />。
		///     </para>
		/// </summary>
		internal static bool TryResolveMerchantCharacterModel(NMerchantCharacter visual, out CharacterModel? character)
		{
			if (TryResolveMerchantCharacterModel(NMerchantRoom.Instance, visual, out character))
			{
				return true;
			}
			if (!FakeMerchantBoothCharacter.TryGetValue(visual, out CharacterModel value))
			{
				character = null;
				return false;
			}
			character = value;
			return true;
		}

		internal static void RegisterFakeMerchantPlayerVisuals(NFakeMerchant screen, List<NMerchantCharacter> ordered, IReadOnlyList<Player> players)
		{
			FakeMerchantPlayerVisualSlot value = FakeMerchantVisualSlots.GetValue(screen, (NFakeMerchant _) => new FakeMerchantPlayerVisualSlot());
			value.Visuals.Clear();
			value.Visuals.AddRange(ordered);
			int num = Math.Min(ordered.Count, players.Count);
			for (int num2 = 0; num2 < num; num2++)
			{
				FakeMerchantBoothCharacter.Remove(ordered[num2]);
				FakeMerchantBoothCharacter.Add(ordered[num2], players[num2].Character);
			}
		}

		internal static IReadOnlyList<NMerchantCharacter>? TryGetFakeMerchantPlayerVisuals(NFakeMerchant screen)
		{
			if (!FakeMerchantVisualSlots.TryGetValue(screen, out FakeMerchantPlayerVisualSlot value))
			{
				return null;
			}
			return value.Visuals;
		}

		internal static string MapWorldAnimationToStateMachineTrigger(string animName)
		{
			if (string.IsNullOrWhiteSpace(animName))
			{
				return animName;
			}
			switch (animName.ToLowerInvariant())
			{
			case "idle":
				return "Idle";
			case "relaxed":
			case "relaxed_loop":
			case "overgrowth_loop":
			case "hive_loop":
			case "glory_loop":
				return "Relaxed";
			case "dead":
			case "die":
			case "death":
				return "Dead";
			case "hurt":
			case "hit":
				return "Hit";
			case "attack":
				return "Attack";
			case "cast":
				return "Cast";
			case "revive":
				return "Revive";
			case "stun":
				return "Stun";
			default:
				return animName;
			}
		}

		private static string MapAnimatorTriggerToCue(string trigger)
		{
			switch (trigger)
			{
			case "Idle":
				return "idle";
			case "Attack":
				return "attack";
			case "Cast":
				return "cast";
			case "Hit":
				return "hurt";
			case "Dead":
				return "die";
			case "Revive":
				return "revive";
			case "Stun":
			case "stun":
				return "stun";
			default:
				return trigger.ToLowerInvariant();
			}
		}

		private static ReadOnlySpan<string> BuildDefaultAlternateNames(string primaryCue)
		{
			string[] array;
			switch (primaryCue.ToLowerInvariant())
			{
			case "die":
				array = DieCueNames;
				break;
			case "idle":
				array = IdleCueNames;
				break;
			case "relaxed":
			case "relaxed_loop":
				array = RelaxedCueNames;
				break;
			case "overgrowth_loop":
			case "hive_loop":
			case "glory_loop":
				array = RestSiteLoopFallback(primaryCue);
				break;
			case "hurt":
				array = HurtCueNames;
				break;
			case "attack":
				array = AttackCueNames;
				break;
			case "cast":
				array = CastCueNames;
				break;
			case "revive":
				array = ReviveCueNames;
				break;
			case "stun":
				array = StunCueNames;
				break;
			default:
				array = TwoNameFallback(primaryCue);
				break;
			}
			return array;
		}

		private static string[] TwoNameFallback(string primaryCue)
		{
			string text = primaryCue.ToLowerInvariant();
			if (string.Equals(primaryCue, text, StringComparison.Ordinal))
			{
				return new string[1] { primaryCue };
			}
			return new string[2] { primaryCue, text };
		}

		private static string[] RestSiteLoopFallback(string primaryCue)
		{
			string[] restSiteLoopCueNames = RestSiteLoopCueNames;
			int num = 0;
			string[] array = new string[1 + restSiteLoopCueNames.Length];
			array[num] = primaryCue;
			num++;
			ReadOnlySpan<string> readOnlySpan = new ReadOnlySpan<string>(restSiteLoopCueNames);
			readOnlySpan.CopyTo(new Span<string>(array).Slice(num, readOnlySpan.Length));
			num += readOnlySpan.Length;
			return array;
		}

		private static bool TryApplyVisualCues(Node visualsRoot, CharacterModel? character, ReadOnlySpan<string> names, VisualCueSet? cueOverride)
		{
			VisualCueSet visualCueSet = cueOverride;
			if (visualCueSet == null && character is IModCharacterAssetOverrides modCharacterAssetOverrides)
			{
				VisualCueSet visualCues = modCharacterAssetOverrides.VisualCues;
				if ((object)visualCues != null)
				{
					visualCueSet = visualCues;
				}
			}
			if (visualCueSet == null)
			{
				return false;
			}
			if (!TryApplyFrameSequences(visualsRoot, visualCueSet, names))
			{
				return TryApplySingleTextureCues(visualsRoot, visualCueSet, names);
			}
			return true;
		}

		private static bool TryApplyFrameSequences(Node visualsRoot, VisualCueSet cues, ReadOnlySpan<string> names)
		{
			IReadOnlyDictionary<string, VisualFrameSequence> frameSequenceByCue = cues.FrameSequenceByCue;
			if (frameSequenceByCue == null || frameSequenceByCue.Count == 0)
			{
				return false;
			}
			Sprite2D val = FindPrimarySprite2D(visualsRoot);
			if (val == null)
			{
				return false;
			}
			ReadOnlySpan<string> readOnlySpan = names;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				string text = readOnlySpan[i];
