			{
				VisualCueSet visualCues = modCharacterAssetOverrides.VisualCues;
				if ((object)visualCues != null)
				{
					IReadOnlyDictionary<string, VisualFrameSequence> frameSequenceByCue = visualCues.FrameSequenceByCue;
					if (frameSequenceByCue != null && frameSequenceByCue.Count > 0)
					{
						ReadOnlySpan<string> readOnlySpan = names;
						for (int i = 0; i < readOnlySpan.Length; i++)
						{
							string text = readOnlySpan[i];
							if (!string.IsNullOrWhiteSpace(text) && TryGetFrameSequence(frameSequenceByCue, text, out VisualFrameSequence sequence) && !(sequence == null))
							{
								seconds = GetSequenceDuration(sequence);
								if (!(seconds <= 0f))
								{
									matched = true;
									return true;
								}
							}
						}
					}
					IReadOnlyDictionary<string, string> texturePathByCue = visualCues.TexturePathByCue;
					if (texturePathByCue == null || texturePathByCue.Count <= 0)
					{
						return false;
					}
					ReadOnlySpan<string> readOnlySpan2 = names;
					for (int i = 0; i < readOnlySpan2.Length; i++)
					{
						string text2 = readOnlySpan2[i];
						if (!string.IsNullOrWhiteSpace(text2) && TryGetCuePath(texturePathByCue, text2, out string path) && !string.IsNullOrWhiteSpace(path))
						{
							matched = true;
							return false;
						}
					}
					return false;
				}
			}
			return false;
		}

		private static bool TryApplySingleTextureCues(Node visualsRoot, VisualCueSet cues, ReadOnlySpan<string> names)
		{
			IReadOnlyDictionary<string, string> texturePathByCue = cues.TexturePathByCue;
			if (texturePathByCue == null || texturePathByCue.Count == 0)
			{
				return false;
			}
			Sprite2D val = FindPrimarySprite2D(visualsRoot);
			if (val == null)
			{
				return false;
			}
			ReadOnlySpan<string> readOnlySpan = names;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				string text = readOnlySpan[i];
				if (string.IsNullOrWhiteSpace(text) || !TryGetCuePath(texturePathByCue, text, out string path) || string.IsNullOrWhiteSpace(path))
				{
					continue;
				}
				Texture2D val2 = ResourceLoader.Load<Texture2D>(path, (string)null, (CacheMode)1);
				if (val2 != null)
				{
					val.Texture = val2;
					IReadOnlyDictionary<string, VisualNodeStyle> textureStyleByCue = cues.TextureStyleByCue;
					if (textureStyleByCue != null && textureStyleByCue.Count > 0 && TryGetCueStyle(textureStyleByCue, text, out VisualNodeStyle style))
					{
						style.ApplyTo((Node?)(object)val);
					}
					return true;
				}
			}
			return false;
		}

		private static bool TryGetFrameSequence(IReadOnlyDictionary<string, VisualFrameSequence> map, string key, out VisualFrameSequence? sequence)
