				{
					path = item.Value;
					return !string.IsNullOrWhiteSpace(path);
				}
			}
			path = null;
			return false;
		}

		private static bool TryGetCueStyle(IReadOnlyDictionary<string, VisualNodeStyle> map, string key, out VisualNodeStyle? style)
