		}

		private static bool TryPlaySpine(NCreatureVisuals visuals, ReadOnlySpan<string> names, bool loop)
		{
			if (!visuals.HasSpineAnimation)
			{
				return false;
			}
			MegaSprite spineBody = visuals.SpineBody;
			if (spineBody == null)
			{
				return false;
			}
			ReadOnlySpan<string> readOnlySpan = names;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				string text = readOnlySpan[i];
				if (!string.IsNullOrWhiteSpace(text))
				{
					try
					{
						spineBody.GetAnimationState().SetAnimation(text, loop, 0);
						return true;
					}
					catch
					{
					}
				}
			}
			return false;
		}

		private static bool TryPlayGodotAnimations(Node root, ReadOnlySpan<string> names)
		{
			if (GodotAnimHandlers.TryGetValue(root, out Func<string[], bool> value))
			{
				return value(NamesToArray(names));
			}
			value = BuildGodotAnimHandler(root);
			if (value == null)
			{
				return false;
			}
			GodotAnimHandlers.Add(root, value);
			return value(NamesToArray(names));
		}

		private static bool TryGetGodotAnimationDuration(Node root, ReadOnlySpan<string> names, out float seconds)
		{
			seconds = 0f;
			AnimationPlayer val = FindNode<AnimationPlayer>(root) ?? SearchRecursive<AnimationPlayer>(root);
			if (val != null && TryGetAnimationPlayerDuration(val, names, out seconds))
			{
				return true;
			}
			AnimatedSprite2D val2 = FindNode<AnimatedSprite2D>(root) ?? SearchRecursive<AnimatedSprite2D>(root);
			if (val2 != null)
			{
				return TryGetAnimatedSpriteDuration(val2, names, out seconds);
			}
			return false;
		}

		private static string[] NamesToArray(ReadOnlySpan<string> names)
		{
			string[] array = new string[names.Length];
			names.CopyTo(array);
			return array;
		}

		private static Func<string[], bool>? BuildGodotAnimHandler(Node root)
		{
			AnimationTree? obj = FindNode<AnimationTree>(root);
			object obj2 = ((obj != null) ? obj.UseAnimationTree() : null);
			if (obj2 == null)
			{
				AnimationTree? obj3 = SearchRecursive<AnimationTree>(root);
				obj2 = ((obj3 != null) ? obj3.UseAnimationTree() : null);
				if (obj2 == null)
				{
					AnimationPlayer? obj4 = FindNode<AnimationPlayer>(root);
					obj2 = ((obj4 != null) ? obj4.UseAnimationPlayer() : null);
					if (obj2 == null)
					{
						AnimatedSprite2D? obj5 = FindNode<AnimatedSprite2D>(root);
						obj2 = ((obj5 != null) ? obj5.UseAnimatedSprite2D() : null);
						if (obj2 == null)
						{
							AnimationPlayer? obj6 = SearchRecursive<AnimationPlayer>(root);
							obj2 = ((obj6 != null) ? obj6.UseAnimationPlayer() : null);
							if (obj2 == null)
							{
								AnimatedSprite2D? obj7 = SearchRecursive<AnimatedSprite2D>(root);
								if (obj7 == null)
								{
									return null;
								}
								obj2 = obj7.UseAnimatedSprite2D();
							}
						}
					}
				}
			}
			return (Func<string[], bool>?)obj2;
		}

		private static Func<string[], bool>? UseAnimationTree(this AnimationTree animationTree)
		{
			//IL_0040: Unknown result type (might be due to invalid IL or missing references)
			//IL_0045: Unknown result type (might be due to invalid IL or missing references)
			AnimationRootNode treeRoot = animationTree.TreeRoot;
			AnimationNodeStateMachine treeRoot2 = (AnimationNodeStateMachine)(object)((treeRoot is AnimationNodeStateMachine) ? treeRoot : null);
			if (treeRoot2 == null)
			{
				return null;
			}
			Variant val = ((GodotObject)animationTree).Get(StringName.op_Implicit("parameters/playback"));
			AnimationNodeStateMachinePlayback playback = ((Variant)(ref val)).As<AnimationNodeStateMachinePlayback>();
			if (playback == null)
			{
				return null;
			}
			return delegate(string[] animNames)
			{
				foreach (string text in animNames)
				{
					if (!string.IsNullOrWhiteSpace(text) && treeRoot2.HasNode(StringName.op_Implicit(text)))
					{
						((AnimationMixer)animationTree).Active = true;
						playback.Travel(StringName.op_Implicit(text), true);
						return true;
					}
				}
				return false;
			};
		}

		private static Func<string[], bool> UseAnimatedSprite2D(this AnimatedSprite2D animSprite)
		{
			return delegate(string[] animNames)
			{
				foreach (string text in animNames)
				{
					if (!string.IsNullOrWhiteSpace(text) && animSprite.SpriteFrames != null && animSprite.SpriteFrames.HasAnimation(StringName.op_Implicit(text)))
					{
						animSprite.Play(StringName.op_Implicit(text), 1f, false);
						return true;
					}
				}
				return false;
			};
		}

		private static Func<string[], bool> UseAnimationPlayer(this AnimationPlayer animPlayer)
		{
			return delegate(string[] animNames)
			{
				foreach (string text in animNames)
				{
					if (!string.IsNullOrWhiteSpace(text) && ((AnimationMixer)animPlayer).HasAnimation(StringName.op_Implicit(text)))
					{
						if (animPlayer.CurrentAnimation == text)
						{
							animPlayer.Stop(false);
						}
						animPlayer.Play(StringName.op_Implicit(text), -1.0, 1f, false);
						return true;
					}
				}
				return false;
			};
		}

		private static bool TryGetAnimationPlayerDuration(AnimationPlayer player, ReadOnlySpan<string> names, out float seconds)
		{
			seconds = 0f;
			ReadOnlySpan<string> readOnlySpan = names;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				string text = readOnlySpan[i];
				if (!string.IsNullOrWhiteSpace(text) && ((AnimationMixer)player).HasAnimation(StringName.op_Implicit(text)))
				{
					Animation animation = ((AnimationMixer)player).GetAnimation(StringName.op_Implicit(text));
					if (animation != null)
					{
						seconds = ScaleDuration(animation.Length, player.SpeedScale);
						return seconds > 0f;
					}
				}
			}
			return false;
		}

		private static bool TryGetAnimatedSpriteDuration(AnimatedSprite2D sprite, ReadOnlySpan<string> names, out float seconds)
		{
			seconds = 0f;
			SpriteFrames spriteFrames = sprite.SpriteFrames;
			if (spriteFrames == null)
			{
				return false;
			}
			ReadOnlySpan<string> readOnlySpan = names;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				string text = readOnlySpan[i];
				if (!string.IsNullOrWhiteSpace(text) && spriteFrames.HasAnimation(StringName.op_Implicit(text)))
				{
					seconds = GetAnimatedSpriteDuration(sprite, spriteFrames, text);
					return seconds > 0f;
				}
			}
			return false;
		}

		private static float GetSequenceDuration(VisualFrameSequence sequence)
		{
			return (from frame in sequence.Frames
				select frame.DurationSeconds into seconds
				select (float.IsFinite(seconds) && !(seconds <= 0f)) ? seconds : (1f / 60f)).Sum();
		}

		private static float GetAnimatedSpriteDuration(AnimatedSprite2D sprite, SpriteFrames frames, string name)
		{
			float num = (float)Math.Abs(frames.GetAnimationSpeed(StringName.op_Implicit(name)) * (double)sprite.SpeedScale);
			if (num <= 0f)
			{
				return 0f;
			}
			float num2 = 0f;
			int frameCount = frames.GetFrameCount(StringName.op_Implicit(name));
			for (int i = 0; i < frameCount; i++)
			{
				num2 += frames.GetFrameDuration(StringName.op_Implicit(name), i);
			}
			return num2 / num;
		}

		private static float ScaleDuration(float seconds, float speedScale)
		{
			if (!float.IsFinite(seconds) || seconds <= 0f)
			{
				return 0f;
			}
			float num = Math.Abs(speedScale);
			if (!(num <= 0f))
			{
				return seconds / num;
			}
			return seconds;
		}

		private static T? FindNode<T>(Node root) where T : class
		{
			string name = typeof(T).Name;
			return (root.GetNodeOrNull(NodePath.op_Implicit(name)) ?? root.GetNodeOrNull(NodePath.op_Implicit("Visuals/" + name)) ?? root.GetNodeOrNull(NodePath.op_Implicit("Body/" + name))) as T;
		}

		private static T? SearchRecursive<T>(Node parent) where T : class
		{
			foreach (Node child in parent.GetChildren(false))
			{
				if (child is T result)
				{
					return result;
				}
				T val = SearchRecursive<T>(child);
				if (val != null)
				{
					return val;
				}
			}
			return null;
		}
	}
