		private static readonly ConditionalWeakTable<NCreature, DelaySlot> Delays = new ConditionalWeakTable<NCreature, DelaySlot>();

		private readonly Task _delayTask;

		private RitsuNonSpineDeathAnimationDelayer(float seconds)
		{
			((Node)this).Name = StringName.op_Implicit("RitsuNonSpineDeathAnimationDelayer");
			_delayTask = Cmd.Wait(Math.Clamp(seconds, 0f, 30f), true);
		}

		public RitsuNonSpineDeathAnimationDelayer()
		{
			_delayTask = Task.CompletedTask;
		}

		public Task GetDelayTask()
		{
			return _delayTask;
		}

		internal static void Install(NCreature creature, float seconds)
		{
			if (!(seconds <= 0f) && float.IsFinite(seconds) && GodotObject.IsInstanceValid((GodotObject)(object)creature))
			{
				seconds = Math.Clamp(seconds, 0f, 30f);
				Delays.GetValue(creature, (NCreature _) => new DelaySlot()).Seconds = seconds;
				if (!(((Node)creature).GetNodeOrNull(NodePath.op_Implicit("RitsuNonSpineDeathAnimationDelayer")) is RitsuNonSpineDeathAnimationDelayer))
				{
					((Node)creature).AddChild((Node)(object)new RitsuNonSpineDeathAnimationDelayer(seconds), false, (InternalMode)0);
				}
			}
		}

		internal static bool TryGetDelaySeconds(NCreature creature, out float seconds)
		{
			seconds = 0f;
			if (!GodotObject.IsInstanceValid((GodotObject)(object)creature) || !Delays.TryGetValue(creature, out DelaySlot value))
			{
				return false;
			}
			seconds = value.Seconds;
			if (seconds > 0f)
			{
				return float.IsFinite(seconds);
			}
			return false;
		}

