namespace STS2RitsuLib.Scaffolding.Characters.Visuals.Definition
{
	/// <summary>
	///     <para xml:lang="en">
	///         Defines data-driven merchant and rest-site visuals, allowing mods to omit dedicated <c>tscn</c>
	///         scenes. Instances can be built through <see cref="T:STS2RitsuLib.Scaffolding.Characters.Visuals.Definition.CharacterWorldProceduralVisualSetBuilder" /> or
	///         <see cref="T:STS2RitsuLib.Scaffolding.Characters.Visuals.Definition.ModCharacterWorldSceneVisuals" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义由数据驱动的商人和休息处形象，使模组无需提供专用 <c>tscn</c> 场景。可以通过
	///         <see cref="T:STS2RitsuLib.Scaffolding.Characters.Visuals.Definition.CharacterWorldProceduralVisualSetBuilder" /> 或
	///         <see cref="T:STS2RitsuLib.Scaffolding.Characters.Visuals.Definition.ModCharacterWorldSceneVisuals" /> 创建实例。
	///     </para>
	/// </summary>
	/// <param name="Merchant">
	///     <para xml:lang="en">The merchant-room visual definition.</para>
	///     <para xml:lang="zh-CN">商人房间形象定义。</para>
	/// </param>
	/// <param name="RestSite">
	///     <para xml:lang="en">The rest-site visual definition.</para>
	///     <para xml:lang="zh-CN">休息处形象定义。</para>
	/// </param>
	public sealed record CharacterWorldProceduralVisualSet(CharacterMerchantWorldDefinition? Merchant = null, CharacterRestSiteWorldDefinition? RestSite = null);
	/// <summary>
	///     <para xml:lang="en">
	///         Defines merchant-room visuals through textures or frame sequences in a <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSet" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSet" /> 中的纹理或帧序列定义商人房间形象。
	///     </para>
	/// </summary>
	/// <param name="CueSet">
	///     <para xml:lang="en">The visual cues keyed by animation name.</para>
	///     <para xml:lang="zh-CN">以动画名称为键的形象提示集合。</para>
	/// </param>
	public sealed record CharacterMerchantWorldDefinition(VisualCueSet CueSet);
	/// <summary>
	///     <para xml:lang="en">
	///         Defines rest-site visuals whose cue keys correspond to the base game's act-specific Spine loop names.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义休息处形象，其提示键与游戏本体各章节对应的 Spine 循环动画名称一致。
	///     </para>
	/// </summary>
	/// <param name="CueSet">
	///     <para xml:lang="en">
	///         The visual cues, typically including <c>overgrowth_loop</c>, <c>hive_loop</c>, and
	///         <c>glory_loop</c>.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         形象提示集合，通常包含 <c>overgrowth_loop</c>、<c>hive_loop</c> 和 <c>glory_loop</c>。
	///     </para>
	/// </param>
	public sealed record CharacterRestSiteWorldDefinition(VisualCueSet CueSet);
	/// <summary>
	///     <para xml:lang="en">
	///         Provides a fluent builder for <see cref="T:STS2RitsuLib.Scaffolding.Characters.Visuals.Definition.CharacterWorldProceduralVisualSet" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供 <see cref="T:STS2RitsuLib.Scaffolding.Characters.Visuals.Definition.CharacterWorldProceduralVisualSet" /> 的流式构建器。
	///     </para>
	/// </summary>
	public sealed class CharacterWorldProceduralVisualSetBuilder
	{
		private CharacterMerchantWorldDefinition? _merchant;

		private CharacterRestSiteWorldDefinition? _restSite;

		private CharacterWorldProceduralVisualSetBuilder()
		{
		}

		/// <summary>
		///     <para xml:lang="en">Creates an empty world-scene visual builder.</para>
		///     <para xml:lang="zh-CN">创建空的世界场景形象构建器。</para>
		/// </summary>
		public static CharacterWorldProceduralVisualSetBuilder Create()
		{
			return new CharacterWorldProceduralVisualSetBuilder();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Configures a procedural merchant-room character with the supplied cue set and no merchant
		///         <c>tscn</c> scene.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用指定的形象提示集合配置程序化商人房间角色，无需商人 <c>tscn</c> 场景。
		///     </para>
		/// </summary>
		public CharacterWorldProceduralVisualSetBuilder Merchant(VisualCueSet cueSet)
		{
			ArgumentNullException.ThrowIfNull(cueSet, "cueSet");
			_merchant = new CharacterMerchantWorldDefinition(cueSet);
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Configures merchant-room cues through a <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSetBuilder" /> callback.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSetBuilder" /> 回调配置商人房间的形象提示。
		///     </para>
		/// </summary>
		public CharacterWorldProceduralVisualSetBuilder Merchant(Action<VisualCueSetBuilder> configure)
		{
			ArgumentNullException.ThrowIfNull(configure, "configure");
			VisualCueSetBuilder visualCueSetBuilder = VisualCueSetBuilder.Create();
			configure(visualCueSetBuilder);
			return Merchant(visualCueSetBuilder.Build());
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Configures a procedural rest-site character with the supplied cue set and no rest-site character
		///         <c>tscn</c> scene.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用指定的形象提示集合配置程序化休息处角色，无需休息处角色 <c>tscn</c> 场景。
		///     </para>
		/// </summary>
		public CharacterWorldProceduralVisualSetBuilder RestSite(VisualCueSet cueSet)
		{
			ArgumentNullException.ThrowIfNull(cueSet, "cueSet");
			_restSite = new CharacterRestSiteWorldDefinition(cueSet);
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Configures rest-site cues through a <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSetBuilder" /> callback.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.Definition.VisualCueSetBuilder" /> 回调配置休息处的形象提示。
		///     </para>
		/// </summary>
		public CharacterWorldProceduralVisualSetBuilder RestSite(Action<VisualCueSetBuilder> configure)
		{
			ArgumentNullException.ThrowIfNull(configure, "configure");
			VisualCueSetBuilder visualCueSetBuilder = VisualCueSetBuilder.Create();
			configure(visualCueSetBuilder);
			return RestSite(visualCueSetBuilder.Build());
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds the configured visual set. Unconfigured components remain <see langword="null" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建已配置的形象集合；未配置的组成部分保持为 <see langword="null" />。
		///     </para>
		/// </summary>
		public CharacterWorldProceduralVisualSet Build()
		{
			return new CharacterWorldProceduralVisualSet(_merchant, _restSite);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides the entry point for procedural merchant and rest-site visuals that do not require custom
	///         <c>tscn</c> scenes.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供程序化商人和休息处形象的入口，使其无需自定义 <c>tscn</c> 场景。
	///     </para>
	/// </summary>
	public static class ModCharacterWorldSceneVisuals
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Creates a builder for <see cref="T:STS2RitsuLib.Scaffolding.Characters.Visuals.Definition.CharacterWorldProceduralVisualSet" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建 <see cref="T:STS2RitsuLib.Scaffolding.Characters.Visuals.Definition.CharacterWorldProceduralVisualSet" /> 构建器。
		///     </para>
		/// </summary>
		public static CharacterWorldProceduralVisualSetBuilder Procedural()
		{
			return CharacterWorldProceduralVisualSetBuilder.Create();
		}
	}
}
namespace STS2RitsuLib.Scaffolding.Characters.Patches
{
	/// <summary>
	///     <para xml:lang="en">
	///         Adds card-pool filter buttons for registered mod characters and shared pools to the card library
	///         compendium. Characters hidden by
	///         <see cref="P:STS2RitsuLib.Scaffolding.Characters.IModCharacterVanillaSelectionPolicy.HideInCardLibraryCompendium" /> are skipped.
	///     </para>
	///     <para xml:lang="en">
	///         Existing filter icons are synchronized with <see cref="P:MegaCrit.Sts2.Core.Models.CharacterModel.IconTexture" /> so that
	///         replacements registered through
	///         <see cref="M:STS2RitsuLib.Content.ModContentRegistry.RegisterCharacterAssetReplacement(System.String,STS2RitsuLib.Scaffolding.Characters.CharacterAssetProfile)" />
	///         are reflected in the compendium. Character rows use
	///         <see cref="P:STS2RitsuLib.Content.CardLibraryCompendiumPlacementDefaults.DefaultCharacterRowRules" /> unless the character
	///         implements <see cref="T:STS2RitsuLib.Scaffolding.Characters.IModCharacterCardLibraryCompendiumPlacement" />. Shared-pool filters without
	///         placement rules are appended to the end of the filter strip.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在卡牌总览中为已注册的模组角色和共享牌池添加牌池筛选按钮。由
	///         <see cref="P:STS2RitsuLib.Scaffolding.Characters.IModCharacterVanillaSelectionPolicy.HideInCardLibraryCompendium" />
	///         隐藏的角色会被跳过。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将现有筛选按钮的图标与 <see cref="P:MegaCrit.Sts2.Core.Models.CharacterModel.IconTexture" /> 同步，使通过
	///         <see cref="M:STS2RitsuLib.Content.ModContentRegistry.RegisterCharacterAssetReplacement(System.String,STS2RitsuLib.Scaffolding.Characters.CharacterAssetProfile)" />
	///         注册的替换也能反映在卡牌总览中。除非角色实现了
	///         <see cref="T:STS2RitsuLib.Scaffolding.Characters.IModCharacterCardLibraryCompendiumPlacement" />，否则角色行使用
	///         <see cref="P:STS2RitsuLib.Content.CardLibraryCompendiumPlacementDefaults.DefaultCharacterRowRules" />。未指定放置规则的共享牌池
	///         筛选按钮会追加到筛选栏末尾。
	///     </para>
	/// </summary>
	[HarmonyAfter(new string[] { "BaseLib" })]
	[HarmonyPriority(0)]
	internal class CardLibraryCompendiumPatch : IPatchMethod
	{
		private const float DefaultFilterSize = 64f;

		private const float DefaultImageSize = 56f;

		private const float FilterGridHeightLimit = 192f;

		private const int DefaultColumnCount = 4;

		public static string PatchId => "card_library_compendium_mod_character_filter";

		public static string Description => "Sync card library compendium pool-filter icons to CharacterModel.IconTexture; add mod character filter buttons";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NCardLibrary), "_Ready")
			};
		}

		public static void Postfix(NCardLibrary __instance, Dictionary<NCardPoolFilter, Func<CardModel, bool>> ____poolFilters, Dictionary<CharacterModel, NCardPoolFilter> ____cardPoolFilters)
		{
			//IL_00ad: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b2: Unknown result type (might be due to invalid IL or missing references)
			//IL_016c: Unknown result type (might be due to invalid IL or missing references)
			SyncExistingFilterIcons(____cardPoolFilters);
			if (!TryGetCompendiumTemplateFilter(__instance, ____cardPoolFilters, out NCardPoolFilter referenceFilter))
			{
				return;
			}
			Node parent = ((Node)referenceFilter).GetParent();
			if (parent == null)
			{
				return;
			}
			CharacterModel[] array = (from character in ModContentRegistry.GetModCharacters()
				where !____cardPoolFilters.ContainsKey(character)
				select character).ToArray();
			IReadOnlyList<CardLibraryCompendiumSharedPoolFilterRegistration> cardLibraryCompendiumSharedPoolFilters = ModContentRegistry.GetCardLibraryCompendiumSharedPoolFilters();
			if (array.Length == 0 && cardLibraryCompendiumSharedPoolFilters.Count == 0)
			{
				QueueFinalFilterLayout(parent);
				return;
			}
			ShaderMaterial referenceMat = null;
			Control nodeOrNull = ((Node)referenceFilter).GetNodeOrNull<Control>(NodePath.op_Implicit("Image"));
			if (nodeOrNull != null)
			{
				Material material = ((CanvasItem)nodeOrNull).Material;
				ShaderMaterial val = (ShaderMaterial)(object)((material is ShaderMaterial) ? material : null);
				if (val != null)
				{
					referenceMat = val;
				}
			}
			Texture2D referenceIcon = TryGetReferenceFilterTexture(referenceFilter);
			Callable updateCallable = Callable.From<NCardPoolFilter>((Action<NCardPoolFilter>)__instance.UpdateCardPoolFilter);
			List<CardLibraryCompendiumPlacementResolver.PlannedRow> list = CardLibraryCompendiumPlacementResolver.BuildPlannedRows(array, cardLibraryCompendiumSharedPoolFilters, RitsuLibFramework.Logger);
			if (list.Count == 0)
			{
				QueueFinalFilterLayout(parent);
				return;
			}
			CardLibraryCompendiumStripSnapshot strip = CardLibraryCompendiumStripSnapshot.Capture(parent);
			CardLibraryCompendiumPlacementResolver.AssignTargetsAndSort(__instance, parent, strip, list, RitsuLibFramework.Logger);
			foreach (CardLibraryCompendiumPlacementResolver.PlannedRow item in list)
			{
				TryBuildFilter(item, referenceMat, referenceIcon, referenceFilter);
			}
			CardLibraryCompendiumPlacementResolver.InsertRowsInOrder(parent, strip, list);
			QueueFinalFilterLayout(parent);
			foreach (CardLibraryCompendiumPlacementResolver.PlannedRow item2 in list)
			{
				NCardPoolFilter builtFilter = item2.BuiltFilter;
				if (builtFilter != null)
				{
					CardPoolModel resolvedPool = item2.ResolvedPool;
					if (resolvedPool != null)
					{
						TryRegisterFilter(__instance, item2, builtFilter, resolvedPool, ____poolFilters, ____cardPoolFilters, updateCallable);
					}
				}
			}
		}

		private static void QueueFinalFilterLayout(Node filterParent)
		{
			//IL_0017: Unknown result type (might be due to invalid IL or missing references)
			//IL_001c: Unknown result type (might be due to invalid IL or missing references)
			Callable val = Callable.From((Action)delegate
			{
				ApplyFinalFilterLayout(filterParent);
			});
			((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
		}

		private static void SyncExistingFilterIcons(Dictionary<CharacterModel, NCardPoolFilter> cardPoolFilters)
		{
			foreach (var (character, val3) in cardPoolFilters)
			{
				try
				{
					TextureRect nodeOrNull = ((Node)val3).GetNodeOrNull<TextureRect>(NodePath.op_Implicit("Image"));
					if (nodeOrNull != null)
					{
						Texture2D val4 = TryGetCharacterIconTexture(character);
						if (val4 != null)
						{
							nodeOrNull.Texture = val4;
						}
					}
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn("[CardLibrary] Failed to sync compendium icon for " + DescribeCharacter(character) + ": " + ex.Message, 1);
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Finds a pool-filter control whose Image <see cref="T:Godot.ShaderMaterial" /> can be cloned and whose icon
		///         can serve as the fallback for shared-pool filters. If the base game has already created character
		///         filters, the leftmost such filter is selected; otherwise, the first available vanilla filter in
		///         <see cref="P:STS2RitsuLib.Content.CardLibraryCompendiumVanillaFilterNames.AllInStripOrder" /> is used.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         查找一个牌池筛选控件，以便克隆其 Image <see cref="T:Godot.ShaderMaterial" />，并将其图标用作共享牌池
		///         筛选按钮的回退图标。如果游戏本体已创建角色筛选按钮，则选择其中最靠左的一个；否则使用
		///         <see cref="P:STS2RitsuLib.Content.CardLibraryCompendiumVanillaFilterNames.AllInStripOrder" />
		///         中第一个实际存在的原版筛选按钮。
		///     </para>
		/// </summary>
		private static bool TryGetCompendiumTemplateFilter(NCardLibrary library, Dictionary<CharacterModel, NCardPoolFilter> cardPoolFilters, out NCardPoolFilter referenceFilter)
		{
			if (cardPoolFilters.Count > 0)
			{
				referenceFilter = GetLeftmostPoolFilterInStripModSubset(cardPoolFilters);
				return true;
			}
			ReadOnlySpan<string> allInStripOrder = CardLibraryCompendiumVanillaFilterNames.AllInStripOrder;
			for (int i = 0; i < allInStripOrder.Length; i++)
			{
				string text = allInStripOrder[i];
				NCardPoolFilter nodeOrNull = ((Node)library).GetNodeOrNull<NCardPoolFilter>(NodePath.op_Implicit(text));
				if (nodeOrNull != null)
				{
					referenceFilter = nodeOrNull;
					return true;
				}
			}
			referenceFilter = null;
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the leftmost <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.CardLibrary.NCardPoolFilter" /> in the compendium filter strip that also appears
		///         in <paramref name="cardPoolFilters" />. Falls back to <c>Values.First()</c> when the strip cannot be
		///         inspected or contains none of those filters.
		///     </para>
		///     <para xml:lang="zh-CN">
