		private static void TryBuildFilter(CardLibraryCompendiumPlacementResolver.PlannedRow row, ShaderMaterial? referenceMat, Texture2D? referenceIcon, NCardPoolFilter referenceFilter)
		{
			try
			{
				CharacterModel character = row.Character;
				if (character != null)
				{
					string iconTexturePath = null;
					if (character is IModCharacterAssetOverrides modCharacterAssetOverrides)
					{
						iconTexturePath = modCharacterAssetOverrides.CustomIconTexturePath;
					}
					row.BuiltFilter = CreateFilter(character, iconTexturePath, referenceMat, referenceIcon);
				}
				else
				{
					CardLibraryCompendiumSharedPoolFilterRegistration shared = row.Shared;
					if (shared != null)
					{
						row.BuiltFilter = CreateSharedPoolFilter(shared, referenceMat, referenceIcon ?? TryGetReferenceFilterTexture(referenceFilter));
					}
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[CardLibrary] Skipping compendium filter '" + row.StableKey + "': failed to create button. " + ex.Message, 1);
				row.BuiltFilter = null;
			}
		}

		private static void TryRegisterFilter(NCardLibrary library, CardLibraryCompendiumPlacementResolver.PlannedRow row, NCardPoolFilter filter, CardPoolModel pool, Dictionary<NCardPoolFilter, Func<CardModel, bool>> poolFilters, Dictionary<CharacterModel, NCardPoolFilter> cardPoolFilters, Callable updateCallable)
