		private static Texture2D? TryLoadTexture(string? path, object owner, string memberName, string ownerLabel)
		{
			if (string.IsNullOrWhiteSpace(path))
			{
				return null;
			}
			try
			{
				if (!AssetPathDiagnostics.Exists(path, owner, memberName))
				{
					return null;
				}
				if (GodotResourcePath.TryLoad<Texture2D>(path, out Texture2D resource))
				{
					return resource;
				}
				RitsuLibFramework.Logger.Warn($"[CardLibrary] Could not load Texture2D for {ownerLabel}.{memberName}: '{path}'.", 1);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[CardLibrary] Failed to load Texture2D for {ownerLabel}.{memberName}: '{path}'. {ex.Message}", 1);
			}
			return null;
		}

		private static string DescribeCharacter(CharacterModel character)
		{
			try
			{
				return ((object)((AbstractModel)character).Id).ToString();
			}
			catch
			{
				return ((object)character).GetType().Name;
			}
		}
