	internal static class CardLibraryCompendiumPlacementResolver
	{
		internal sealed class PlannedRow
		{
			public required string StableKey { get; init; }

			public CharacterModel? Character { get; init; }

			public CardLibraryCompendiumSharedPoolFilterRegistration? Shared { get; init; }

			public required IReadOnlyList<CardLibraryCompendiumPlacementRule> ActiveRules { get; init; }

			public required bool IsCharacter { get; init; }

			public bool AppendToStripEnd { get; set; }

			public required int RegistrationSequence { get; init; }

			public int EffectiveTarget { get; set; }

			public NCardPoolFilter? BuiltFilter { get; set; }

			public CardPoolModel? ResolvedPool { get; set; }
		}

		private readonly record struct ModConstraint(string FromKey, string OtherKey, bool ItemMustBeAfterOther);

		private const int MaxRelaxationRounds = 64;

		internal static string StableKeyForCharacter(string modelIdEntry)
		{
			return "CMP_CHAR:" + modelIdEntry;
		}

		internal static string StableKeyForShared(string stableId)
		{
			return "CMP_SHARED:" + stableId;
		}

		internal static List<PlannedRow> BuildPlannedRows(IReadOnlyList<CharacterModel> modCharacters, IReadOnlyList<CardLibraryCompendiumSharedPoolFilterRegistration> sharedRegs, Logger log)
		{
			int seq = 0;
			List<PlannedRow> list = (from character in modCharacters
				where !(character is IModCharacterVanillaSelectionPolicy modCharacterVanillaSelectionPolicy) || !modCharacterVanillaSelectionPolicy.HideInCardLibraryCompendium
				let rules = GetCharacterPlacementRules(character)
				select new PlannedRow
				{
					StableKey = StableKeyForCharacter(((AbstractModel)character).Id.Entry),
					Character = character,
					Shared = null,
					ActiveRules = rules,
					IsCharacter = true,
					AppendToStripEnd = false,
					RegistrationSequence = seq++,
					ResolvedPool = character.CardPool
				}).ToList();
			foreach (CardLibraryCompendiumSharedPoolFilterRegistration sharedReg in sharedRegs)
			{
				CardPoolModel byId;
				try
				{
					byId = ModelDb.GetById<CardPoolModel>(ModelDb.GetId(sharedReg.CardPoolType));
				}
				catch (Exception ex)
				{
					log.Warn($"[CardLibrary] Skipping compendium filter '{sharedReg.StableId}': could not resolve {sharedReg.CardPoolType.Name} — {ex.Message}", 1);
					continue;
				}
				IReadOnlyList<CardLibraryCompendiumPlacementRule> placementRules = sharedReg.PlacementRules;
				IReadOnlyList<CardLibraryCompendiumPlacementRule>? readOnlyList;
				if (placementRules == null || placementRules.Count <= 0)
				{
					placementRules = Array.Empty<CardLibraryCompendiumPlacementRule>();
					readOnlyList = placementRules;
				}
				else
				{
					readOnlyList = sharedReg.PlacementRules;
				}
				IReadOnlyList<CardLibraryCompendiumPlacementRule> activeRules = readOnlyList;
				list.Add(new PlannedRow
				{
					StableKey = StableKeyForShared(sharedReg.StableId),
					Character = null,
					Shared = sharedReg,
					ActiveRules = activeRules,
					IsCharacter = false,
					AppendToStripEnd = false,
					RegistrationSequence = seq++,
					ResolvedPool = byId
				});
			}
			return list;
		}

		private static IReadOnlyList<CardLibraryCompendiumPlacementRule> GetCharacterPlacementRules(CharacterModel character)
		{
			if (!(character is IModCharacterCardLibraryCompendiumPlacement modCharacterCardLibraryCompendiumPlacement))
			{
				return CardLibraryCompendiumPlacementDefaults.DefaultCharacterRowRules;
			}
			IReadOnlyList<CardLibraryCompendiumPlacementRule> cardLibraryCompendiumPlacementRules = modCharacterCardLibraryCompendiumPlacement.CardLibraryCompendiumPlacementRules;
			if (cardLibraryCompendiumPlacementRules == null || cardLibraryCompendiumPlacementRules.Count <= 0)
			{
				return CardLibraryCompendiumPlacementDefaults.DefaultCharacterRowRules;
			}
			return cardLibraryCompendiumPlacementRules;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves logical insertion indices in <paramref name="strip" />, applies constraints between mod
		///         rows, identifies shared rows that should be appended to the filter strip, and sorts all rows by
		///         placement and registration order before insertion.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <paramref name="strip" /> 中解析逻辑插入位置，应用模组行之间的约束，识别应追加到筛选栏
		///         末尾的共享行，并在插入前按放置位置和注册顺序排列所有行。
		///     </para>
		/// </summary>
		internal static void AssignTargetsAndSort(NCardLibrary library, Node filterParent, CardLibraryCompendiumStripSnapshot strip, List<PlannedRow> rows, Logger log)
		{
			if (rows.Count == 0)
			{
				return;
			}
			int count = strip.Count;
