				row2.EffectiveTarget = (row2.IsCharacter ? ResolveInitialCharacterTarget(library, filterParent, strip, row2.ActiveRules) : ResolveInitialSharedTarget(library, filterParent, strip, row2.ActiveRules));
			}
			List<ModConstraint> list = CollectModConstraints(rows, log);
			RelaxTargets(keyToRow, count, list, log);
			foreach (PlannedRow row3 in rows)
			{
				row3.EffectiveTarget = Math.Clamp(row3.EffectiveTarget, 0, count);
			}
			foreach (PlannedRow row in rows.Where((PlannedRow plannedRow) => !plannedRow.IsCharacter))
			{
				if (row.ActiveRules.Count == 0)
				{
					row.AppendToStripEnd = true;
					continue;
				}
				bool flag = TryFirstMatchingVanillaRule(library, filterParent, strip, row.ActiveRules, out var _);
				bool flag2 = list.Exists((ModConstraint c) => c.FromKey == row.StableKey);
				row.AppendToStripEnd = !flag && !flag2;
			}
			SortPlannedRowsForStableInsertion(rows);
		}

		private static void SortPlannedRowsForStableInsertion(List<PlannedRow> rows)
		{
			rows.Sort(delegate(PlannedRow a, PlannedRow b)
			{
				int num = ((a != null && !a.IsCharacter && a.AppendToStripEnd) ? 1 : 0);
				int num2 = ((b != null && !b.IsCharacter && b.AppendToStripEnd) ? 1 : 0);
				if (num != num2)
				{
					return num.CompareTo(num2);
				}
				int num3 = a.EffectiveTarget.CompareTo(b.EffectiveTarget);
				return (num3 == 0) ? a.RegistrationSequence.CompareTo(b.RegistrationSequence) : num3;
			});
		}

		private static int ResolveInitialCharacterTarget(NCardLibrary library, Node filterParent, CardLibraryCompendiumStripSnapshot strip, IReadOnlyList<CardLibraryCompendiumPlacementRule> rules)
		{
			if (!TryFirstMatchingVanillaRule(library, filterParent, strip, rules, out var targetIndex))
			{
				return ResolveDefaultCharacterFallback(library, filterParent, strip);
			}
			return Math.Clamp(targetIndex, 0, strip.Count);
		}

		private static int ResolveInitialSharedTarget(NCardLibrary library, Node filterParent, CardLibraryCompendiumStripSnapshot strip, IReadOnlyList<CardLibraryCompendiumPlacementRule> rules)
		{
			if (TryFirstMatchingVanillaRule(library, filterParent, strip, rules, out var targetIndex))
			{
				return Math.Clamp(targetIndex, 0, strip.Count);
			}
			if (rules.Count == 0)
			{
				return strip.Count;
			}
			if (!HasAnyModAnchorRule(rules))
			{
				return strip.Count;
			}
			return 0;
		}

		private static bool HasAnyModAnchorRule(IReadOnlyList<CardLibraryCompendiumPlacementRule> rules)
		{
			foreach (CardLibraryCompendiumPlacementRule rule in rules)
			{
				if (!string.IsNullOrWhiteSpace(rule.ModCharacterModelIdEntry))
				{
					return true;
				}
				if (!string.IsNullOrWhiteSpace(rule.ModSharedCompendiumFilterStableId))
				{
					return true;
				}
			}
			return false;
		}

		private static bool TryFirstMatchingVanillaRule(NCardLibrary library, Node filterParent, CardLibraryCompendiumStripSnapshot strip, IReadOnlyList<CardLibraryCompendiumPlacementRule> rules, out int targetIndex)
		{
			foreach (CardLibraryCompendiumPlacementRule rule in rules)
			{
				if (!string.IsNullOrWhiteSpace(rule.VanillaFilterAnchorUniqueName))
				{
					NCardPoolFilter nodeOrNull = ((Node)library).GetNodeOrNull<NCardPoolFilter>(NodePath.op_Implicit(rule.VanillaFilterAnchorUniqueName));
					if (nodeOrNull != null && ((Node)nodeOrNull).GetParent() == filterParent && strip.TryGetIndexOfNode((Node?)(object)nodeOrNull, out var index))
					{
						targetIndex = ((rule.Relation == CardLibraryCompendiumFilterInsertRelation.Before) ? index : (index + 1));
						return true;
					}
				}
			}
			targetIndex = 0;
			return false;
		}

		private static int ResolveDefaultCharacterFallback(NCardLibrary library, Node filterParent, CardLibraryCompendiumStripSnapshot strip)
		{
			if (!TryFirstMatchingVanillaRule(library, filterParent, strip, CardLibraryCompendiumPlacementDefaults.DefaultCharacterRowRules, out var targetIndex))
			{
				return strip.Count;
			}
			return Math.Clamp(targetIndex, 0, strip.Count);
		}

		private static List<ModConstraint> CollectModConstraints(List<PlannedRow> rows, Logger log)
		{
			List<ModConstraint> list = new List<ModConstraint>();
			foreach (PlannedRow row in rows)
			{
				foreach (CardLibraryCompendiumPlacementRule activeRule in row.ActiveRules)
				{
					if (!string.IsNullOrWhiteSpace(activeRule.ModCharacterModelIdEntry))
					{
						string entry = activeRule.ModCharacterModelIdEntry.Trim();
						PlannedRow plannedRow = rows.FirstOrDefault((PlannedRow r) => r.Character != null && string.Equals(((AbstractModel)r.Character).Id.Entry, entry, StringComparison.OrdinalIgnoreCase));
						if (plannedRow == null)
						{
							log.Warn($"[CardLibrary] Placement rule on '{row.StableKey}' references unknown mod character entry '{activeRule.ModCharacterModelIdEntry}' (that edge is ignored).", 1);
						}
						else
						{
							list.Add(new ModConstraint(row.StableKey, plannedRow.StableKey, activeRule.Relation == CardLibraryCompendiumFilterInsertRelation.After));
						}
					}
					else if (!string.IsNullOrWhiteSpace(activeRule.ModSharedCompendiumFilterStableId))
					{
						string sid = activeRule.ModSharedCompendiumFilterStableId.Trim();
						PlannedRow plannedRow2 = rows.FirstOrDefault((PlannedRow r) => r.Shared != null && string.Equals(r.Shared.StableId, sid, StringComparison.OrdinalIgnoreCase));
						if (plannedRow2 == null)
						{
							log.Warn($"[CardLibrary] Placement rule on '{row.StableKey}' references unknown shared filter '{activeRule.ModSharedCompendiumFilterStableId}'.", 1);
						}
						else
						{
							list.Add(new ModConstraint(row.StableKey, plannedRow2.StableKey, activeRule.Relation == CardLibraryCompendiumFilterInsertRelation.After));
						}
					}
				}
			}
			return list;
		}

		private static void RelaxTargets(IReadOnlyDictionary<string, PlannedRow> keyToRow, int maxSlot, List<ModConstraint> constraints, Logger log)
		{
			if (constraints.Count == 0)
			{
				return;
			}
			for (int i = 0; i < 64; i++)
			{
				bool flag = false;
				foreach (ModConstraint constraint in constraints)
				{
					if (keyToRow.TryGetValue(constraint.FromKey, out PlannedRow value) && keyToRow.TryGetValue(constraint.OtherKey, out PlannedRow value2))
					{
						int effectiveTarget = value.EffectiveTarget;
						value.EffectiveTarget = (constraint.ItemMustBeAfterOther ? Math.Max(value.EffectiveTarget, value2.EffectiveTarget + 1) : Math.Min(value.EffectiveTarget, value2.EffectiveTarget - 1));
						value.EffectiveTarget = Math.Clamp(value.EffectiveTarget, 0, maxSlot);
						if (value.EffectiveTarget != effectiveTarget)
						{
							flag = true;
						}
					}
				}
				if (!flag)
				{
					return;
				}
			}
			log.Warn("[CardLibrary] Compendium placement constraints did not stabilize within " + $"{64} relaxation rounds; order may be ambiguous. Check for cycles or conflicting rules.", 1);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Inserts each successfully built mod pool-filter node into the sibling order captured by
		///         <paramref name="strip" />, preserving the order established by
		///         <see cref="M:STS2RitsuLib.Scaffolding.Characters.Patches.CardLibraryCompendiumPlacementResolver.SortPlannedRowsForStableInsertion(System.Collections.Generic.List{STS2RitsuLib.Scaffolding.Characters.Patches.CardLibraryCompendiumPlacementResolver.PlannedRow})" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将每个成功创建的模组牌池筛选节点插入 <paramref name="strip" /> 记录的同级节点顺序，并保留
		///         <see cref="M:STS2RitsuLib.Scaffolding.Characters.Patches.CardLibraryCompendiumPlacementResolver.SortPlannedRowsForStableInsertion(System.Collections.Generic.List{STS2RitsuLib.Scaffolding.Characters.Patches.CardLibraryCompendiumPlacementResolver.PlannedRow})" /> 确定的排列顺序。
		///     </para>
		/// </summary>
		internal static void InsertRowsInOrder(Node filterParent, CardLibraryCompendiumStripSnapshot strip, List<PlannedRow> orderedRows)
		{
			List<Node> list = new List<Node>(strip.OriginalSiblingsInOrder);
			for (int i = 0; i < orderedRows.Count; i++)
			{
				PlannedRow plannedRow = orderedRows[i];
				NCardPoolFilter builtFilter = plannedRow.BuiltFilter;
				if (builtFilter == null)
				{
					continue;
				}
				int num;
				if (plannedRow != null && !plannedRow.IsCharacter && plannedRow.AppendToStripEnd)
				{
					num = list.Count;
				}
				else
				{
					int num2 = 0;
					for (int j = 0; j < i; j++)
					{
						if (orderedRows[j].EffectiveTarget == plannedRow.EffectiveTarget)
						{
							PlannedRow plannedRow2 = orderedRows[j];
							if (plannedRow2 == null || plannedRow2.IsCharacter || !plannedRow2.AppendToStripEnd)
							{
								num2++;
							}
						}
					}
					num = Math.Clamp(plannedRow.EffectiveTarget + num2, 0, list.Count);
				}
				list.Insert(num, (Node)(object)builtFilter);
				filterParent.AddChild((Node)(object)builtFilter, true, (InternalMode)0);
				filterParent.MoveChild((Node)(object)builtFilter, num);
			}
		}
	}
	internal static class CharacterAssetOverridePatchHelper
	{
		internal static bool TryUseOverride(CharacterModel instance, ref string __result, Func<IModCharacterAssetOverrides, string?> selector, string memberName, bool requireExistingResource = true)
		{
			string text = ResolveOverride(instance, selector, memberName);
			if (string.IsNullOrWhiteSpace(text))
			{
				return true;
			}
			if (requireExistingResource && !IsCompatibleResource(instance, memberName, text))
			{
				return true;
			}
			__result = text;
			return false;
		}

		internal static bool TryResolveOverridePath(CharacterModel instance, Func<IModCharacterAssetOverrides, string?> selector, string memberName, out string path)
		{
			path = ResolveOverride(instance, selector, memberName) ?? string.Empty;
			return !string.IsNullOrWhiteSpace(path);
		}

		internal static string? ResolveCombatSpineSkeletonDataPath(CharacterModel instance)
		{
			if (TryResolveRegisteredProfile(instance, out CharacterAssetProfile profile) && !string.IsNullOrWhiteSpace(profile.Spine?.CombatSkeletonDataPath))
			{
				return profile.Spine?.CombatSkeletonDataPath;
			}
			if (instance is IModCharacterAssetOverrides modCharacterAssetOverrides && !string.IsNullOrWhiteSpace(modCharacterAssetOverrides.CustomCombatSpineSkeletonDataPath))
			{
				return modCharacterAssetOverrides.CustomCombatSpineSkeletonDataPath;
			}
			return null;
		}

		private static string? ResolveOverride(CharacterModel instance, Func<IModCharacterAssetOverrides, string?> selector, string memberName)
		{
			if (TryResolveRegisteredProfile(instance, out CharacterAssetProfile profile))
			{
				string text = memberName switch
				{
					"CustomVisualsPath" => profile.Scenes?.VisualsPath, 
					"CustomEnergyCounterPath" => profile.Scenes?.EnergyCounterPath, 
					"CustomMerchantAnimPath" => profile.Scenes?.MerchantAnimPath, 
					"CustomRestSiteAnimPath" => profile.Scenes?.RestSiteAnimPath, 
					"CustomIconTexturePath" => profile.Ui?.IconTexturePath, 
					"CustomIconOutlineTexturePath" => profile.Ui?.IconOutlineTexturePath, 
					"CustomIconPath" => profile.Ui?.IconPath, 
					"CustomCharacterSelectBgPath" => profile.Ui?.CharacterSelectBgPath, 
					"CustomCharacterSelectIconPath" => profile.Ui?.CharacterSelectIconPath, 
					"CustomCharacterSelectLockedIconPath" => profile.Ui?.CharacterSelectLockedIconPath, 
					"CustomCharacterSelectTransitionPath" => profile.Ui?.CharacterSelectTransitionPath, 
					"CustomMapMarkerPath" => profile.Ui?.MapMarkerPath, 
					"CustomTrailPath" => profile.Vfx?.TrailPath, 
					"CustomAttackSfx" => profile.Audio?.AttackSfx, 
					"CustomCastSfx" => profile.Audio?.CastSfx, 
					"CustomDeathSfx" => profile.Audio?.DeathSfx, 
					"CustomArmPointingTexturePath" => profile.Multiplayer?.ArmPointingTexturePath, 
					"CustomArmRockTexturePath" => profile.Multiplayer?.ArmRockTexturePath, 
					"CustomArmPaperTexturePath" => profile.Multiplayer?.ArmPaperTexturePath, 
					"CustomArmScissorsTexturePath" => profile.Multiplayer?.ArmScissorsTexturePath, 
					_ => null, 
				};
				if (!string.IsNullOrWhiteSpace(text))
				{
					return text;
				}
			}
			if (!(instance is IModCharacterAssetOverrides arg))
			{
				return null;
			}
			string text2 = selector(arg);
			if (string.IsNullOrWhiteSpace(text2))
			{
				return null;
			}
			return text2;
		}

		private static bool IsCompatibleResource(CharacterModel instance, string memberName, string path)
		{
			if (!GodotResourcePath.ResourceExists(path))
			{
				AssetPathDiagnostics.WarnModCharacterAssetOverrideMissing(instance, memberName, path);
				return false;
			}
			return memberName switch
			{
				"CustomVisualsPath" => IsLoadableAsAny(instance, memberName, path, "PackedScene", typeof(PackedScene), typeof(Texture2D)), 
				"CustomIconPath" => IsLoadableAsAny(instance, memberName, path, "PackedScene", typeof(PackedScene), typeof(Texture2D)), 
				"CustomEnergyCounterPath" => IsLoadable<PackedScene>(instance, memberName, path), 
				"CustomMerchantAnimPath" => IsLoadableAsAny(instance, memberName, path, "PackedScene", typeof(PackedScene), typeof(Texture2D)), 
				"CustomRestSiteAnimPath" => IsLoadableAsAny(instance, memberName, path, "PackedScene", typeof(PackedScene), typeof(Texture2D)), 
				"CustomCharacterSelectBgPath" => IsLoadableAsAny(instance, memberName, path, "PackedScene", typeof(PackedScene), typeof(Texture2D)), 
				"CustomTrailPath" => IsLoadable<PackedScene>(instance, memberName, path), 
				"CustomIconTexturePath" => IsLoadable<Texture2D>(instance, memberName, path), 
				"CustomIconOutlineTexturePath" => IsLoadable<Texture2D>(instance, memberName, path), 
				"CustomCharacterSelectIconPath" => IsLoadable<Texture2D>(instance, memberName, path), 
				"CustomCharacterSelectLockedIconPath" => IsLoadable<Texture2D>(instance, memberName, path), 
				"CustomMapMarkerPath" => IsLoadable<Texture2D>(instance, memberName, path), 
				"CustomArmPointingTexturePath" => IsLoadable<Texture2D>(instance, memberName, path), 
				"CustomArmRockTexturePath" => IsLoadable<Texture2D>(instance, memberName, path), 
				"CustomArmPaperTexturePath" => IsLoadable<Texture2D>(instance, memberName, path), 
				"CustomArmScissorsTexturePath" => IsLoadable<Texture2D>(instance, memberName, path), 
				"CustomCharacterSelectTransitionPath" => IsLoadable<Material>(instance, memberName, path), 
				"CustomCombatSpineSkeletonDataPath" => IsLoadable<Resource>(instance, memberName, path), 
				_ => true, 
			};
		}

		private static bool IsLoadable<T>(CharacterModel instance, string memberName, string path) where T : class
		{
			if (GodotResourcePath.TryLoad<T>(path, out T _))
			{
				return true;
			}
			ContentAssetOverridePatchHelper.LogLoadFailure(instance, memberName, path, typeof(T).Name);
			return false;
		}

		private static bool IsLoadableAsAny(CharacterModel instance, string memberName, string path, string expectedTypeLabel, params Type[] allowedTypes)
		{
			if ((from candidate in GodotResourcePath.EnumerateCandidatePaths(path)
				where ResourceLoader.Exists(candidate, "")
				select ResourceLoader.Load(candidate, "", (CacheMode)1)).Any((Resource resource) => allowedTypes.Any((Type type) => type.IsInstanceOfType(resource))))
			{
				return true;
			}
			ContentAssetOverridePatchHelper.LogLoadFailure(instance, memberName, path, expectedTypeLabel + " or Texture2D");
			return false;
		}

		private static bool TryResolveRegisteredProfile(CharacterModel instance, out CharacterAssetProfile profile)
		{
			return ModContentRegistry.TryGetEffectiveCharacterAssetReplacement(((AbstractModel)instance).Id.Entry, out profile);
		}
	}
