	///         Converts a mod character's compatible legacy energy-counter scene into an
	///         <see cref="T:MegaCrit.Sts2.Core.Nodes.Combat.NEnergyCounter" /> before the base game attempts to instantiate the scene as that type.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在游戏本体尝试将场景直接实例化为 <see cref="T:MegaCrit.Sts2.Core.Nodes.Combat.NEnergyCounter" /> 前，将模组角色兼容的旧版能量计数器
	///         场景转换为该类型。
	///     </para>
	/// </summary>
	internal class CharacterEnergyCounterRuntimeFactoryPatch : IPatchMethod
	{
		private static readonly FieldInfo PlayerField = AccessTools.Field(typeof(NEnergyCounter), "_player");

		public static string PatchId => "character_energy_counter_runtime_factory";

		public static string Description => "Allow mod characters to supply NEnergyCounter via Ritsu scene conversion before direct scene instantiate";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NEnergyCounter), "Create")
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Converts a mod energy-counter scene into <see cref="T:MegaCrit.Sts2.Core.Nodes.Combat.NEnergyCounter" /> and assigns its owning
		///         player before the base game performs direct scene instantiation.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将模组能量计数器场景转换为 <see cref="T:MegaCrit.Sts2.Core.Nodes.Combat.NEnergyCounter" /> 并设置其所属玩家，然后跳过游戏本体的
		///         直接场景实例化。
		///     </para>
		/// </summary>
		[HarmonyPriority(800)]
		public static bool Prefix(Player player, ref NEnergyCounter? __result)
		{
			if (!CharacterAssetOverridePatchHelper.TryResolveOverridePath(player.Character, (IModCharacterAssetOverrides o) => o.CustomEnergyCounterPath, "CustomEnergyCounterPath", out string path))
			{
				return true;
			}
			PackedScene val = ContentAssetOverridePatchHelper.ResolveScene(path);
			if (val == null)
			{
				return true;
			}
			try
			{
				NEnergyCounter val2 = RitsuGodotNodeFactories.CreateFromScene<NEnergyCounter>(val, (GenEditState)0);
				PlayerField.SetValue(val2, player);
				__result = val2;
				return false;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[Godot] Failed to auto-convert energy counter '{path}' for character {((AbstractModel)player.Character).Id.Entry}: {ex.Message}. Falling back.", 1);
				return true;
			}
		}
	}
