	/// <summary>
	///     <para xml:lang="en">
	///         After a combat creature node becomes ready, applies the mod character's Spine skeleton data from
	///         <see cref="P:STS2RitsuLib.Scaffolding.Characters.IModCharacterAssetOverrides.CustomCombatSpineSkeletonDataPath" /> when its visuals support
	///         skeleton replacement.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         战斗生物节点准备就绪后，如果其形象支持替换骨骼，则应用模组角色通过
	///         <see cref="P:STS2RitsuLib.Scaffolding.Characters.IModCharacterAssetOverrides.CustomCombatSpineSkeletonDataPath" /> 指定的 Spine 骨骼数据。
	///     </para>
	/// </summary>
	internal class CharacterCombatSpineOverridePatch : IPatchMethod
	{
		public static string PatchId => "character_combat_spine_override";

		public static string Description => "Allow mod characters to replace combat Spine skeleton data while reusing existing visuals scenes";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NCreature), "_Ready")
			};
		}

		public static void Postfix(NCreature __instance)
		{
			Creature entity = __instance.Entity;
			Player obj = ((entity != null) ? entity.Player : null);
			CharacterModel val = ((obj != null) ? obj.Character : null);
			if (val == null)
			{
				return;
			}
			string text = CharacterAssetOverridePatchHelper.ResolveCombatSpineSkeletonDataPath(val);
			if (string.IsNullOrWhiteSpace(text) || !AssetPathDiagnostics.Exists(text, val, "CustomCombatSpineSkeletonDataPath"))
			{
				return;
			}
			NCreatureVisuals visuals = __instance.Visuals;
			if (visuals == null || !visuals.HasSpineAnimation || !NCreatureVisualsSpineCompat.HasSpineTargetForOverride(visuals))
			{
				return;
			}
			try
			{
				Resource val2 = ResourceLoader.Load<Resource>(text, (string)null, (CacheMode)1);
				if (val2 == null)
				{
					RitsuLibFramework.Logger.Warn("[Visuals] Failed to load combat spine data: " + text, 1);
				}
				else if (!NCreatureVisualsSpineCompat.TryApplyCombatSkeletonOverride(visuals, val2))
				{
					RitsuLibFramework.Logger.Warn("[Visuals] Could not apply combat spine override (no Body/SpineBody target): " + text, 1);
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.ErrorNoTrace("[Visuals] Failed to apply combat spine override '" + text + "': " + ex.Message);
			}
		}
	}
