			try
			{
				NCardTrailVfx val2 = RitsuGodotNodeFactories.CreateFromScene<NCardTrailVfx>(val, (GenEditState)0);
				NodeToFollowRef.Invoke(val2) = card;
				__result = val2;
				return false;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[Godot] Failed to auto-convert card trail scene '{characterTrailPath}' to {"NCardTrailVfx"}: {ex.Message}. Falling back.", 1);
				return true;
			}
		}

		public static void Postfix(Control card, ref NCardTrailVfx? __result)
		{
			if (__result == null)
			{
				return;
			}
			NCard val = (NCard)(object)((card is NCard) ? card : null);
			if (val != null)
			{
				CardModel model = val.Model;
				object obj;
				if (model == null)
				{
					obj = null;
				}
				else
				{
					Player owner = model.Owner;
					obj = ((owner != null) ? owner.Character : null);
				}
				CharacterTrailStyle characterTrailStyle = (obj as IModCharacterAssetOverrides)?.CustomTrailStyle;
				if (!(characterTrailStyle == null))
				{
					ApplyLineStyle((Node)(object)__result, "Trails/OuterTrail", characterTrailStyle.OuterTrailModulate, characterTrailStyle.OuterTrailWidth);
					ApplyLineStyle((Node)(object)__result, "Trails/InnerTrail", characterTrailStyle.InnerTrailModulate, characterTrailStyle.InnerTrailWidth);
					ApplyParticleColor((Node)(object)__result, "Sprites/BigSparks", characterTrailStyle.BigSparksColor);
					ApplyParticleColor((Node)(object)__result, "Sprites/LittleSparks", characterTrailStyle.LittleSparksColor);
					ApplySpriteStyle((Node)(object)__result, "Sprites/Sprite2D2", characterTrailStyle.PrimarySpriteModulate, characterTrailStyle.PrimarySpriteScale);
					ApplySpriteStyle((Node)(object)__result, "Sprites/Sprite2D3", characterTrailStyle.SecondarySpriteModulate, characterTrailStyle.SecondarySpriteScale);
				}
			}
		}

		private static void ApplyLineStyle(Node root, string nodePath, Color? modulate, float? width)
		{
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			Line2D nodeOrNull = root.GetNodeOrNull<Line2D>(NodePath.op_Implicit(nodePath));
			if (nodeOrNull != null)
			{
				if (modulate.HasValue)
				{
					((CanvasItem)nodeOrNull).Modulate = modulate.Value;
				}
				if (width.HasValue)
				{
					nodeOrNull.Width = width.Value;
				}
			}
		}

		private static void ApplyParticleColor(Node root, string nodePath, Color? color)
		{
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			if (color.HasValue)
			{
				CpuParticles2D nodeOrNull = root.GetNodeOrNull<CpuParticles2D>(NodePath.op_Implicit(nodePath));
				if (nodeOrNull != null)
				{
					nodeOrNull.Color = color.Value;
				}
			}
		}

		private static void ApplySpriteStyle(Node root, string nodePath, Color? modulate, Vector2? scale)
		{
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0033: Unknown result type (might be due to invalid IL or missing references)
			Sprite2D nodeOrNull = root.GetNodeOrNull<Sprite2D>(NodePath.op_Implicit(nodePath));
			if (nodeOrNull != null)
			{
				if (modulate.HasValue)
				{
					((CanvasItem)nodeOrNull).Modulate = modulate.Value;
				}
				if (scale.HasValue)
				{
					((Node2D)nodeOrNull).Scale = scale.Value;
				}
			}
		}
	}
	internal static class CharacterVanillaSelectionPolicyScope
	{
		private enum SelectionScope
		{
			None,
			Visible,
			RandomEligible
		}

		[ThreadStatic]
		private static Stack<SelectionScope>? _scopeStack;

		public static void Enter(MethodBase originalMethod)
		{
			SelectionScope selectionScope = ResolveScope(originalMethod);
			if (selectionScope != SelectionScope.None)
			{
				(_scopeStack ?? (_scopeStack = new Stack<SelectionScope>())).Push(selectionScope);
			}
		}

		public static void Exit(MethodBase originalMethod)
		{
			if (ResolveScope(originalMethod) == SelectionScope.None)
			{
				return;
			}
			Stack<SelectionScope> scopeStack = _scopeStack;
			if (scopeStack != null && scopeStack.Count > 0)
			{
				_scopeStack.Pop();
				if (_scopeStack.Count == 0)
				{
					_scopeStack = null;
				}
			}
		}

		public static IEnumerable<CharacterModel> Apply(IEnumerable<CharacterModel> source)
		{
			Stack<SelectionScope> scopeStack = _scopeStack;
			return ((scopeStack != null && scopeStack.Count > 0) ? _scopeStack.Peek() : SelectionScope.None) switch
			{
				SelectionScope.Visible => source.Where((CharacterModel character) => !(character is IModCharacterVanillaSelectionPolicy modCharacterVanillaSelectionPolicy) || !modCharacterVanillaSelectionPolicy.HideFromVanillaCharacterSelect), 
				SelectionScope.RandomEligible => source.Where((CharacterModel character) => !(character is IModCharacterVanillaSelectionPolicy modCharacterVanillaSelectionPolicy) || modCharacterVanillaSelectionPolicy.AllowInVanillaRandomCharacterSelect), 
				_ => source, 
			};
		}

		private static SelectionScope ResolveScope(MethodBase originalMethod)
		{
			if (originalMethod.DeclaringType == typeof(NCharacterSelectScreen) && originalMethod.Name == "InitCharacterButtons")
			{
				return SelectionScope.Visible;
			}
			if ((originalMethod.DeclaringType == typeof(NCharacterSelectScreen) && originalMethod.Name == "UpdateRandomCharacterVisibility") || (originalMethod.DeclaringType == typeof(NCharacterSelectButton) && originalMethod.Name == "Init") || (originalMethod.DeclaringType == typeof(StartRunLobby) && originalMethod.Name == "BeginRunLocally"))
			{
				return SelectionScope.RandomEligible;
			}
			return SelectionScope.None;
		}
	}
