	internal static class CharacterWorldScenePathFactoryHelper
	{
		internal static TNode CreateFromSceneOrTexture<TNode>(CharacterModel character, string path, string memberName, GenEditState editState) where TNode : Node, new()
		{
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			Exception innerException = null;
			foreach (string item in EnumerateCandidatePaths(character, path, memberName))
			{
				try
				{
					if (TryCreate<TNode>(item, editState, out var created))
					{
						if (!string.Equals(item, path, StringComparison.Ordinal))
						{
							RitsuLibFramework.Logger.Warn($"[Godot] Falling back to character world asset '{item}' for {DescribeCharacter(character)}.{memberName}.", 1);
						}
						return created;
					}
					RitsuLibFramework.Logger.Warn($"[Godot] Character world asset '{item}' for {DescribeCharacter(character)}.{memberName} did not resolve as {"PackedScene"} or {"Texture2D"}.", 1);
				}
				catch (Exception ex)
				{
					innerException = ex;
					RitsuLibFramework.Logger.Warn($"[Godot] Failed to auto-convert {DescribeCharacter(character)}.{memberName} '{item}' to {typeof(TNode).Name}: {ex.Message}.", 1);
				}
			}
			throw new InvalidOperationException($"Could not create {typeof(TNode).Name} for {DescribeCharacter(character)}.{memberName} from '{path}'.", innerException);
		}

		private static bool TryCreate<TNode>(string path, GenEditState editState, out TNode created) where TNode : Node, new()
		{
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			PackedScene val = ContentAssetOverridePatchHelper.ResolveScene(path);
			if (val != null)
			{
				created = RitsuGodotNodeFactories.CreateFromScene<TNode>(val, editState);
				return true;
			}
			Texture2D val2 = ContentAssetOverridePatchHelper.ResolveTexture2D(path);
			if (val2 != null)
			{
				created = RitsuGodotNodeFactories.CreateFromResource<TNode>(val2);
				return true;
			}
			created = default(TNode);
			return false;
		}

		private static IEnumerable<string> EnumerateCandidatePaths(CharacterModel character, string path, string memberName)
		{
			if (!string.IsNullOrWhiteSpace(path))
			{
				yield return path;
			}
			string entry = ((AbstractModel)character).Id.Entry;
			if (!string.IsNullOrWhiteSpace(entry))
			{
				string text = SelectPath(CharacterAssetProfiles.FromCharacterId(entry), memberName);
				if (!string.IsNullOrWhiteSpace(text) && !string.Equals(text, path, StringComparison.Ordinal))
				{
					yield return text;
				}
			}
			if (!string.Equals(entry, "ironclad", StringComparison.OrdinalIgnoreCase))
			{
				string text2 = SelectPath(CharacterAssetProfiles.FromCharacterId("ironclad"), memberName);
				if (!string.IsNullOrWhiteSpace(text2) && !string.Equals(text2, path, StringComparison.Ordinal))
				{
					yield return text2;
				}
			}
		}

		private static string? SelectPath(CharacterAssetProfile profile, string memberName)
		{
			if (!(memberName == "CustomMerchantAnimPath"))
			{
				if (memberName == "CustomRestSiteAnimPath")
				{
					return profile.Scenes?.RestSiteAnimPath;
				}
				return null;
			}
			return profile.Scenes?.MerchantAnimPath;
		}

		private static string DescribeCharacter(CharacterModel character)
		{
			try
			{
				return ((object)character).GetType().Name + "<" + ((AbstractModel)character).Id.Entry + ">";
			}
			catch
			{
				return ((object)character).GetType().Name;
			}
		}
	}
