	/// <summary>
	///     <para xml:lang="en">
	///         Routes <see cref="M:MegaCrit.Sts2.Core.Nodes.Combat.NCreature.SetAnimationTrigger(System.String)" /> to a <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine" /> when the
	///         creature model provides one through <see cref="T:STS2RitsuLib.Scaffolding.Content.IModCreatureCombatAnimationStateMachineFactory" /> or
	///         the legacy <see cref="T:STS2RitsuLib.Scaffolding.Content.IModNonSpineAnimationStateMachineFactory" />. This also supports Spine-backed
	///         visuals when the factory returns a state machine, such as one created by
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachineBuilder.BuildSpine(MegaCrit.Sts2.Core.Bindings.MegaSpine.MegaSprite)" />.
	///     </para>
	///     <para xml:lang="en">
	///         When no state machine is available and the creature has no Spine animator, animation triggers fall
	///         back to <see cref="M:STS2RitsuLib.Scaffolding.Characters.Visuals.ModCreatureVisualPlayback.TryPlayFromCreatureAnimatorTrigger(MegaCrit.Sts2.Core.Nodes.Combat.NCreature,System.String)" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         当生物模型通过 <see cref="T:STS2RitsuLib.Scaffolding.Content.IModCreatureCombatAnimationStateMachineFactory" /> 或旧版
	///         <see cref="T:STS2RitsuLib.Scaffolding.Content.IModNonSpineAnimationStateMachineFactory" /> 提供 <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine" /> 时，
	///         将 <see cref="M:MegaCrit.Sts2.Core.Nodes.Combat.NCreature.SetAnimationTrigger(System.String)" /> 路由到该状态机。如果工厂返回了状态机，例如通过
	///         <see cref="M:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachineBuilder.BuildSpine(MegaCrit.Sts2.Core.Bindings.MegaSpine.MegaSprite)" /> 创建的状态机，则同样支持基于 Spine 的形象。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         没有可用状态机且生物没有 Spine 动画器时，动画触发器会回退到
	///         <see cref="M:STS2RitsuLib.Scaffolding.Characters.Visuals.ModCreatureVisualPlayback.TryPlayFromCreatureAnimatorTrigger(MegaCrit.Sts2.Core.Nodes.Combat.NCreature,System.String)" />。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         State machines are cached per visuals root via a
	///         <see cref="T:System.Runtime.CompilerServices.ConditionalWeakTable`2" /> so factories run at most once per combat lifetime.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         状态机通过 <see cref="T:System.Runtime.CompilerServices.ConditionalWeakTable`2" /> 按形象根节点缓存，因此每场战斗中每个根节点
	///         最多调用一次工厂。
	///     </para>
	/// </remarks>
	[HarmonyBefore(new string[] { "BaseLib" })]
	internal class ModCreatureCombatAnimationPlaybackPatch : IPatchMethod
	{
		private sealed class StateMachineSlot
		{
			private bool _built;

			public ModAnimStateMachine? StateMachine { get; private set; }

			public void EnsureBuilt(CharacterModel? character, MonsterModel? monster, Node visuals)
			{
				if (!_built)
				{
					StateMachine = BuildFrom(character, monster, visuals);
					_built = true;
				}
			}

			private static ModAnimStateMachine? BuildFrom(CharacterModel? character, MonsterModel? monster, Node visuals)
			{
				if (character is IModCreatureCombatAnimationStateMachineFactory modCreatureCombatAnimationStateMachineFactory)
				{
					ModAnimStateMachine modAnimStateMachine = modCreatureCombatAnimationStateMachineFactory.TryCreateCombatAnimationStateMachine(visuals);
					if (modAnimStateMachine != null)
					{
						return modAnimStateMachine;
					}
				}
				if (character is IModNonSpineAnimationStateMachineFactory modNonSpineAnimationStateMachineFactory)
				{
					ModAnimStateMachine modAnimStateMachine2 = modNonSpineAnimationStateMachineFactory.TryCreateNonSpineAnimationStateMachine(visuals);
					if (modAnimStateMachine2 != null)
					{
						return modAnimStateMachine2;
					}
				}
				if (monster is IModCreatureCombatAnimationStateMachineFactory modCreatureCombatAnimationStateMachineFactory2)
				{
					ModAnimStateMachine modAnimStateMachine3 = modCreatureCombatAnimationStateMachineFactory2.TryCreateCombatAnimationStateMachine(visuals);
					if (modAnimStateMachine3 != null)
					{
						return modAnimStateMachine3;
					}
				}
				if (monster is IModNonSpineAnimationStateMachineFactory modNonSpineAnimationStateMachineFactory2)
				{
					return modNonSpineAnimationStateMachineFactory2.TryCreateNonSpineAnimationStateMachine(visuals);
				}
				return null;
			}
		}

		private static readonly ConditionalWeakTable<Node, StateMachineSlot> StateMachinesByVisuals = new ConditionalWeakTable<Node, StateMachineSlot>();

		public static string PatchId => "mod_creature_combat_animation_playback";

		public static string Description => "Route NCreature.SetAnimationTrigger through ModAnimStateMachine when opted in (Spine or non-Spine); otherwise cue playback for non-Spine";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NCreature), "SetAnimationTrigger")
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the cached combat <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine" /> for <paramref name="creature" /> when
		///         its model's factory produced one; otherwise, returns <see langword="null" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当 <paramref name="creature" /> 所属模型的工厂生成了状态机时，返回缓存的战斗
		///         <see cref="T:STS2RitsuLib.Scaffolding.Visuals.StateMachine.ModAnimStateMachine" />；否则返回 <see langword="null" />。
		///     </para>
		/// </summary>
		internal static ModAnimStateMachine? TryGetCombatAnimationStateMachine(NCreature creature)
		{
			NCreatureVisuals visuals = creature.Visuals;
			if (visuals == null || !GodotObject.IsInstanceValid((GodotObject)(object)visuals))
			{
				return null;
			}
			Creature entity = creature.Entity;
			if (entity == null)
			{
				return null;
			}
			StateMachineSlot value = StateMachinesByVisuals.GetValue((Node)(object)visuals, (Node _) => new StateMachineSlot());
			Player player = entity.Player;
			value.EnsureBuilt((player != null) ? player.Character : null, entity.Monster, (Node)(object)visuals);
			return value.StateMachine;
		}

		internal static bool TryGetCurrentCombatAnimationDuration(NCreature creature, string trigger, out float seconds)
		{
			seconds = 0f;
			ModAnimStateMachine modAnimStateMachine = TryGetCombatAnimationStateMachine(creature);
			if (modAnimStateMachine != null)
			{
				if ((modAnimStateMachine.TryGetCurrentAnimationRemaining(out seconds) || modAnimStateMachine.TryGetCurrentAnimationDuration(out seconds)) && seconds > 0f)
				{
					return float.IsFinite(seconds);
				}
				return false;
			}
			if (ModCreatureVisualPlayback.TryGetDurationFromCreatureAnimatorTrigger(creature, trigger, out seconds) && seconds > 0f)
			{
				return float.IsFinite(seconds);
			}
			return false;
		}

		public static bool Prefix(NCreature __instance, string trigger)
		{
			if (TryRouteToStateMachine(__instance, trigger))
			{
				return false;
			}
			if (__instance.HasSpineAnimation)
			{
				return true;
			}
			return !ModCreatureVisualPlayback.TryPlayFromCreatureAnimatorTrigger(__instance, trigger);
		}

		private static bool TryRouteToStateMachine(NCreature creature, string trigger)
		{
			NCreatureVisuals visuals = creature.Visuals;
			if (visuals == null || !GodotObject.IsInstanceValid((GodotObject)(object)visuals))
			{
				return false;
			}
			Creature entity = creature.Entity;
			if (entity == null)
			{
				return false;
			}
			StateMachineSlot value = StateMachinesByVisuals.GetValue((Node)(object)visuals, (Node _) => new StateMachineSlot());
			Player player = entity.Player;
			value.EnsureBuilt((player != null) ? player.Character : null, entity.Monster, (Node)(object)visuals);
			if (value.StateMachine == null)
			{
				return false;
			}
			value.StateMachine.SetTrigger(trigger);
			return true;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Routes <see cref="M:MegaCrit.Sts2.Core.Nodes.Screens.Shops.NMerchantCharacter.PlayAnimation(System.String,System.Boolean)" /> for registered non-Spine merchant visuals
	///         through a mod state machine or <see cref="T:STS2RitsuLib.Scaffolding.Characters.Visuals.ModCreatureVisualPlayback" />, including texture,
	///         <see cref="T:Godot.AnimationPlayer" />, and <see cref="T:Godot.AnimatedSprite2D" /> playback.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         对已注册的非 Spine 商人形象，将 <see cref="M:MegaCrit.Sts2.Core.Nodes.Screens.Shops.NMerchantCharacter.PlayAnimation(System.String,System.Boolean)" /> 路由到模组状态机或
	///         <see cref="T:STS2RitsuLib.Scaffolding.Characters.Visuals.ModCreatureVisualPlayback" />，以支持纹理、<see cref="T:Godot.AnimationPlayer" /> 和
	///         <see cref="T:Godot.AnimatedSprite2D" /> 动画。
	///     </para>
	/// </summary>
	[HarmonyBefore(new string[] { "BaseLib" })]
	internal class ModMerchantCharacterVisualPlaybackPatch : IPatchMethod
	{
		private sealed class StateMachineSlot
		{
			private bool _built;

			public ModAnimStateMachine? StateMachine { get; private set; }

			public void EnsureBuilt(IModCharacterMerchantAnimationStateMachineFactory factory, Node root, CharacterModel character)
			{
				if (!_built)
				{
					StateMachine = factory.TryCreateMerchantAnimationStateMachine(root, character);
					_built = true;
				}
			}
		}

		private sealed class RegisteredMerchantVisual(CharacterModel character)
		{
