		public static string PatchId => "mod_merchant_character_visual_playback";

		public static string Description => "Play non-Spine merchant character animations via ModCreatureVisualPlayback";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NMerchantCharacter), "PlayAnimation")
			};
		}

		public static bool Prefix(NMerchantCharacter __instance, string anim, bool loop)
		{
			if (!TryGetRegisteredMerchantCharacter(__instance, out CharacterModel character))
			{
				return true;
			}
			if (((Node)__instance).GetChildCount(false) == 0)
			{
				return false;
			}
			if (TryRouteToStateMachine(__instance, character, anim))
			{
				return false;
			}
			if (IsFirstChildSpine(__instance))
			{
				return true;
			}
			VisualCueSet cueSetOverride = TryGetMerchantWorldCueSet(character);
			if (ModCreatureVisualPlayback.TryPlayOnVisualRoot((Node)(object)__instance, character, anim, loop, cueSetOverride))
			{
				return false;
			}
			return false;
		}

		internal static void RegisterRitsuMerchantVisual(NMerchantCharacter visual, CharacterModel character)
		{
			RitsuMerchantVisuals.Remove(visual);
			RitsuMerchantVisuals.Add(visual, new RegisteredMerchantVisual(character));
		}

		internal static bool IsFirstChildSpine(NMerchantCharacter visual)
		{
			if (((Node)visual).GetChildCount(false) > 0)
			{
				return ((GodotObject)((Node)visual).GetChild(0, false)).GetClass() == "SpineSprite";
			}
			return false;
		}

		internal static bool TryGetRegisteredMerchantCharacter(NMerchantCharacter visual, out CharacterModel? character)
		{
			if (RitsuMerchantVisuals.TryGetValue(visual, out RegisteredMerchantVisual value))
			{
				character = value.Character;
				return true;
			}
			character = null;
			return false;
		}

		private static bool TryRouteToStateMachine(NMerchantCharacter merchant, CharacterModel? character, string anim)
		{
			if (!(character is IModCharacterMerchantAnimationStateMachineFactory factory))
			{
				return false;
			}
			StateMachineSlot value = StateMachinesByRoot.GetValue((Node)(object)merchant, (Node _) => new StateMachineSlot());
			value.EnsureBuilt(factory, (Node)(object)merchant, character);
			if (value.StateMachine == null)
			{
				return false;
			}
			value.StateMachine.SetTrigger(ModCreatureVisualPlayback.MapWorldAnimationToStateMachineTrigger(anim));
			return true;
		}

		private static VisualCueSet? TryGetMerchantWorldCueSet(CharacterModel? character)
		{
			if (character is IModCharacterAssetOverrides modCharacterAssetOverrides)
			{
				CharacterWorldProceduralVisualSet worldProceduralVisuals = modCharacterAssetOverrides.WorldProceduralVisuals;
				if ((object)worldProceduralVisuals != null)
				{
					CharacterMerchantWorldDefinition merchant = worldProceduralVisuals.Merchant;
					if ((object)merchant != null)
					{
						VisualCueSet cueSet = merchant.CueSet;
						if ((object)cueSet != null)
						{
							return cueSet;
						}
					}
				}
			}
			return null;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Skips the base <see cref="M:MegaCrit.Sts2.Core.Nodes.Screens.Shops.NMerchantCharacter._Ready" /> implementation for registered non-Spine
	///         merchant visuals so its <see cref="T:MegaCrit.Sts2.Core.Bindings.MegaSpine.MegaSprite" /> construction does not reject procedural or
	///         Godot-animation roots.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         对已注册的非 Spine 商人形象跳过游戏本体的 <see cref="M:MegaCrit.Sts2.Core.Nodes.Screens.Shops.NMerchantCharacter._Ready" /> 实现，避免其中的
	///         <see cref="T:MegaCrit.Sts2.Core.Bindings.MegaSpine.MegaSprite" /> 创建过程拒绝程序化根节点或 Godot 动画根节点。
	///     </para>
	/// </summary>
	internal class ModMerchantCharacterReadyPlaybackPatch : IPatchMethod
	{
		public static string PatchId => "mod_merchant_character_ready_visual_playback";

		public static string Description => "Initialize non-Spine merchant character visuals without constructing MegaSprite";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NMerchantCharacter), "_Ready")
			};
		}

		public static bool Prefix(NMerchantCharacter __instance)
		{
			if (!ModMerchantCharacterVisualPlaybackPatch.TryGetRegisteredMerchantCharacter(__instance, out CharacterModel _))
			{
				return true;
			}
			if (ModMerchantCharacterVisualPlaybackPatch.IsFirstChildSpine(__instance))
			{
				return true;
			}
			__instance.PlayAnimation("relaxed_loop", true);
			return false;
		}
	}
