	internal readonly record struct CharacterButtonStripScrollOptions(int VisibleButtons, float ViewportWidth, float ViewportHeight, float OffsetTop, float OffsetBottom, bool PreserveRootLayout = false);
	/// <summary>
	///     <para xml:lang="en">
	///         Includes RitsuLib-managed non-Spine death-animation durations when calculating the delay before combat
	///         rewards are offered.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         计算战斗奖励出现前的等待时间时，计入由 RitsuLib 管理的非 Spine 死亡动画时长。
	///     </para>
	/// </summary>
	internal class NCombatUiNonSpineDeathAnimationRewardDelayPatch : IPatchMethod
	{
		private static readonly FieldRef<NCombatUi, CancellationTokenSource> CtsRef = AccessTools.FieldRefAccess<NCombatUi, CancellationTokenSource>("_cts");

		private static readonly FieldInfo? IsDebugSlowRewardsField = AccessTools.Field(typeof(NCombatUi), "_isDebugSlowRewards");

		public static string PatchId => "ncombat_ui_non_spine_death_animation_reward_delay";

		public static string Description => "Include RitsuLib-managed non-Spine death animation durations when delaying combat rewards";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NCombatUi), "ShowRewards", new Type[1] { typeof(CombatRoom) })
			};
		}

		public static bool Prefix(NCombatUi __instance, CombatRoom room, ref Task __result)
		{
			__result = ShowRewards(__instance, room);
			return false;
		}

		private static async Task ShowRewards(NCombatUi ui, CombatRoom room)
		{
			float removingCreatureRewardDelay = GetRemovingCreatureRewardDelay();
			CancellationToken token = CtsRef.Invoke(ui).Token;
			if (IsDebugSlowRewards())
			{
				await Cmd.Wait(removingCreatureRewardDelay + 3f, token, false);
			}
			else if ((int)((AbstractRoom)room).RoomType != 3)
			{
				await Cmd.CustomScaledWait(0.5f, removingCreatureRewardDelay + 1f, false, token);
			}
			else
			{
				await Cmd.CustomScaledWait(removingCreatureRewardDelay * 0.5f, removingCreatureRewardDelay + 1f, false, token);
			}
			await OfferRoomEndRewards(ui, room);
		}

		private static Task OfferRoomEndRewards(NCombatUi ui, CombatRoom room)
		{
			return room.OfferRoomEndRewards();
		}

		private static float GetRemovingCreatureRewardDelay()
		{
			float num = 0f;
			NCombatRoom instance = NCombatRoom.Instance;
			if (instance == null)
			{
				return num;
			}
			foreach (NCreature removingCreatureNode in instance.RemovingCreatureNodes)
			{
				if (!GodotObject.IsInstanceValid((GodotObject)(object)removingCreatureNode))
				{
					continue;
				}
				if (removingCreatureNode != null && removingCreatureNode.HasSpineAnimation && removingCreatureNode.IsPlayingDeathAnimation)
				{
					num = Math.Max(num, removingCreatureNode.GetCurrentAnimationTimeRemaining());
					continue;
				}
				if (RitsuNonSpineDeathAnimationDelayer.TryGetDelaySeconds(removingCreatureNode, out var seconds))
				{
					num = Math.Max(num, seconds);
				}
				MonsterModel monster = removingCreatureNode.Entity.Monster;
				if (monster != null && monster.HasDeathAnimLengthOverride)
				{
					num = Math.Max(num, monster.DeathAnimLengthOverride);
				}
			}
			return num;
		}

		private static bool IsDebugSlowRewards()
		{
			object obj = IsDebugSlowRewardsField?.GetValue(null);
			if (obj is bool)
			{
				return (bool)obj;
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Eagerly builds combat animation state machines after the combat visuals are ready for creature models
	///         that provide a compatible state-machine factory.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         对提供兼容状态机工厂的生物模型，在战斗形象准备就绪后立即创建战斗动画状态机。
	///     </para>
	/// </summary>
	internal class NCreatureCombatAnimationInitialBootstrapPatch : IPatchMethod
	{
		public static string PatchId => "ncreature_combat_animation_initial_bootstrap";

		public static string Description => "Build combat animation state machine at NCreature._Ready for opted-in models";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NCreature), "_Ready")
			};
		}

		public static void Postfix(NCreature __instance)
		{
			if (HasCombatStateMachineFactory(__instance))
			{
				ModCreatureCombatAnimationPlaybackPatch.TryGetCombatAnimationStateMachine(__instance);
			}
		}

		private static bool HasCombatStateMachineFactory(NCreature creature)
		{
			Creature entity = creature.Entity;
			if (entity == null)
			{
				return false;
			}
			Player player = entity.Player;
			CharacterModel val = ((player != null) ? player.Character : null);
			if ((val is IModCreatureCombatAnimationStateMachineFactory || val is IModNonSpineAnimationStateMachineFactory) ? true : false)
			{
				return true;
			}
			MonsterModel monster = entity.Monster;
			if (monster is IModCreatureCombatAnimationStateMachineFactory || monster is IModNonSpineAnimationStateMachineFactory)
			{
				return true;
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Dispatches the <c>Dead</c> animation trigger after <see cref="M:MegaCrit.Sts2.Core.Nodes.Combat.NCreature.StartDeathAnim(System.Boolean)" /> for
	///         RitsuLib-managed creatures without a Spine animator. The base implementation only dispatches this
	///         trigger through its Spine path, so non-Spine animation backends would otherwise receive no death
	///         trigger.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         对由 RitsuLib 管理且没有 Spine 动画器的生物，在 <see cref="M:MegaCrit.Sts2.Core.Nodes.Combat.NCreature.StartDeathAnim(System.Boolean)" /> 后派发
	///         <c>Dead</c> 动画触发器。游戏本体只会通过 Spine 路径派发该触发器，因此其他动画后端原本无法收到
	///         死亡触发器。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         The patch applies only when the creature has no Spine animator and its character or monster model
	///         provides a RitsuLib animation-state-machine factory, or its player character implements
	///         <see cref="T:STS2RitsuLib.Scaffolding.Characters.IModCharacterAssetOverrides" />. Other creatures are unaffected.
	///     </para>
	///     <para xml:lang="en">
	///         When a finite animation duration is available, the returned duration is raised to that value, capped
	///         at 30 seconds. Creatures scheduled for removal also receive a matching
	///         <see cref="T:STS2RitsuLib.Scaffolding.Characters.Visuals.RitsuNonSpineDeathAnimationDelayer" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         此补丁仅适用于没有 Spine 动画器，且其角色或怪物模型提供 RitsuLib 动画状态机工厂的生物；玩家角色
	///         实现 <see cref="T:STS2RitsuLib.Scaffolding.Characters.IModCharacterAssetOverrides" /> 时也适用。其他生物不受影响。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         能够取得有效动画时长时，方法返回的时长会提高到该值，但最多为 30 秒。计划移除的生物还会获得时长
	///         相同的 <see cref="T:STS2RitsuLib.Scaffolding.Characters.Visuals.RitsuNonSpineDeathAnimationDelayer" />。
	///     </para>
	/// </remarks>
	internal class NCreatureNonSpineDeathAnimationTriggerPatch : IPatchMethod
	{
		public static string PatchId => "ncreature_non_spine_death_animation_trigger";

		public static string Description => "Dispatch the Dead animation trigger for RitsuLib-managed non-Spine creatures so StartDeathAnim animates correctly";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NCreature), "StartDeathAnim")
			};
		}

		public static void Postfix(NCreature __instance, bool shouldRemove, ref float __result)
		{
			if (!CombatAnimationStateMachineTriggerScope.AppliesToDeathPostfix(__instance))
			{
				return;
			}
			__instance.SetAnimationTrigger("Dead");
			if (ModCreatureCombatAnimationPlaybackPatch.TryGetCurrentCombatAnimationDuration(__instance, "Dead", out var seconds))
			{
				seconds = Math.Min(seconds, 30f);
				if (seconds > __result)
				{
					__result = seconds;
				}
				if (shouldRemove)
				{
					RitsuNonSpineDeathAnimationDelayer.Install(__instance, seconds);
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Dispatches the <c>Revive</c> animation trigger after <see cref="M:MegaCrit.Sts2.Core.Nodes.Combat.NCreature.StartReviveAnim" /> for
	///         RitsuLib-managed creatures when the base implementation did not dispatch it.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         对由 RitsuLib 管理的生物，在游戏本体没有派发 <c>Revive</c> 动画触发器时，于
	///         <see cref="M:MegaCrit.Sts2.Core.Nodes.Combat.NCreature.StartReviveAnim" /> 后补充派发该触发器。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         For non-Spine creatures, the scope matches
	///         <see cref="T:STS2RitsuLib.Scaffolding.Characters.Patches.NCreatureNonSpineDeathAnimationTriggerPatch" />. A Spine-backed creature is included only
	///         when its mod combat state machine declares <c>Revive</c> and the base animator does not.
	///     </para>
	///     <para xml:lang="en">
	///         If the base implementation also ran <c>AnimTempRevive</c>, its fade tween continues alongside the mod
	///         animation.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         对非 Spine 生物，适用范围与 <see cref="T:STS2RitsuLib.Scaffolding.Characters.Patches.NCreatureNonSpineDeathAnimationTriggerPatch" /> 相同。对于
	///         基于 Spine 的生物，仅当模组战斗状态机声明了 <c>Revive</c> 而游戏本体动画器没有该触发器时才适用。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         如果游戏本体同时运行了 <c>AnimTempRevive</c>，其淡入淡出补间动画仍会与模组动画并行播放。
	///     </para>
	/// </remarks>
	internal class NCreatureNonSpineReviveAnimationTriggerPatch : IPatchMethod
	{
		private static readonly FieldRef<NCreature, CreatureAnimator?> SpineAnimatorRef = AccessTools.FieldRefAccess<NCreature, CreatureAnimator>("_spineAnimator");

		public static string PatchId => "ncreature_non_spine_revive_animation_trigger";

		public static string Description => "Dispatch the Revive animation trigger for RitsuLib-managed creatures so StartReviveAnim animates correctly";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NCreature), "StartReviveAnim")
			};
		}

		public static void Postfix(NCreature __instance)
		{
			if (!CombatAnimationStateMachineTriggerScope.AppliesToRevivePostfix(__instance))
			{
				return;
			}
			if (__instance.HasSpineAnimation)
			{
				CreatureAnimator val = SpineAnimatorRef.Invoke(__instance);
				if (val != null && val.HasTrigger("Revive"))
				{
					return;
				}
			}
			__instance.SetAnimationTrigger("Revive");
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines the shared eligibility checks used by the <see cref="M:MegaCrit.Sts2.Core.Nodes.Combat.NCreature.StartDeathAnim(System.Boolean)" /> and
	///         <see cref="M:MegaCrit.Sts2.Core.Nodes.Combat.NCreature.StartReviveAnim" /> postfixes.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义 <see cref="M:MegaCrit.Sts2.Core.Nodes.Combat.NCreature.StartDeathAnim(System.Boolean)" /> 与 <see cref="M:MegaCrit.Sts2.Core.Nodes.Combat.NCreature.StartReviveAnim" /> 后置补丁
	///         共用的适用条件。
	///     </para>
	/// </summary>
	internal static class CombatAnimationStateMachineTriggerScope
	{
		public static bool AppliesToDeathPostfix(NCreature creature)
		{
			if (!creature.HasSpineAnimation)
			{
				return AppliesToRitsuLibVisuals(creature);
			}
			return false;
		}

		public static bool AppliesToRevivePostfix(NCreature creature)
		{
			if (!creature.HasSpineAnimation)
			{
				return AppliesToRitsuLibVisuals(creature);
			}
			return ModCreatureCombatAnimationPlaybackPatch.TryGetCombatAnimationStateMachine(creature)?.HasTrigger("Revive") ?? false;
		}

		private static bool AppliesToRitsuLibVisuals(NCreature creature)
		{
			Creature entity = creature.Entity;
			if (entity == null)
			{
				return false;
			}
			Player player = entity.Player;
			CharacterModel val = ((player != null) ? player.Character : null);
			MonsterModel monster = entity.Monster;
			if (val is IModCreatureCombatAnimationStateMachineFactory || val is IModNonSpineAnimationStateMachineFactory)
			{
				return true;
			}
			if (monster is IModCreatureCombatAnimationStateMachineFactory || monster is IModNonSpineAnimationStateMachineFactory)
			{
				return true;
			}
			return val is IModCharacterAssetOverrides;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Reimplements <c>NFakeMerchant.AfterRoomIsLoaded</c> when any player has a RitsuLib merchant-visual
	///         override. Player booth visuals are then created as <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.Shops.NMerchantCharacter" /> nodes through
	///         <see cref="T:STS2RitsuLib.Scaffolding.Characters.Patches.NMerchantRoomProceduralCharacterInstantiationPatch" />, including procedural visuals and
	///         world-animation cues.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         当任一玩家具有 RitsuLib 商人形象替换时，重新实现 <c>NFakeMerchant.AfterRoomIsLoaded</c>。随后通过
	///         <see cref="T:STS2RitsuLib.Scaffolding.Characters.Patches.NMerchantRoomProceduralCharacterInstantiationPatch" /> 将所有玩家的摊位形象创建为
	///         <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.Shops.NMerchantCharacter" /> 节点，并支持程序化形象和世界场景动画提示。
	///     </para>
	/// </summary>
	internal class NFakeMerchantProceduralCharacterInstantiationPatch : IPatchMethod
	{
		private static readonly FieldRef<NFakeMerchant, List<Player>> PlayersRef = AccessTools.FieldRefAccess<NFakeMerchant, List<Player>>("_players");

		private static readonly FieldRef<NFakeMerchant, Control> CharacterContainerRef = AccessTools.FieldRefAccess<NFakeMerchant, Control>("_characterContainer");

		private static readonly FieldRef<NFakeMerchant, FakeMerchant> EventRef = AccessTools.FieldRefAccess<NFakeMerchant, FakeMerchant>("_event");

		private static readonly Func<NFakeMerchant, Task> ShowWelcomeDialogueInvoker = AccessTools.MethodDelegate<Func<NFakeMerchant, Task>>(AccessTools.Method(typeof(NFakeMerchant), "ShowWelcomeDialogue", (Type[])null, (Type[])null), (object)null, true, (Type[])null);

		public static string PatchId => "n_fake_merchant_procedural_character_instantiation";

		public static string Description => "Instantiate fake-merchant event player visuals via merchant character path when mod merchant visuals apply";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NFakeMerchant), "AfterRoomIsLoaded")
			};
		}

		public static bool Prefix(NFakeMerchant __instance)
		{
			if (!PlayersRef.Invoke(__instance).Any((Player player) => NMerchantRoomProceduralCharacterInstantiationPatch.HasRitsuMerchantVisualOverride(player.Character)))
			{
				return true;
			}
			RunAfterRoomIsLoaded(__instance);
			return false;
		}

		private static void RunAfterRoomIsLoaded(NFakeMerchant screen)
		{
			//IL_00c7: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ec: Unknown result type (might be due to invalid IL or missing references)
			List<Player> list = PlayersRef.Invoke(screen);
			Control parent = CharacterContainerRef.Invoke(screen);
			FakeMerchant val = EventRef.Invoke(screen);
			Player me = LocalContext.GetMe((IEnumerable<Player>)list);
			ArgumentNullException.ThrowIfNull(me, "me");
			list.Remove(me);
			list.Insert(0, me);
			List<NMerchantCharacter> list2 = new List<NMerchantCharacter>();
			int num = Mathf.CeilToInt(Mathf.Sqrt((float)list.Count));
			for (int i = 0; i < num; i++)
			{
				float num2 = -75f * (float)i;
				for (int j = 0; j < num; j++)
				{
					int num3 = i * num + j;
					if (num3 >= list.Count)
					{
						break;
					}
					NMerchantCharacter val2 = NMerchantRoomProceduralCharacterInstantiationPatch.CreateMerchantCharacter(list[num3].Character);
					RitsuGodotTreeCompat.AddChildSafely((Node)(object)parent, (Node?)(object)val2);
					RitsuGodotTreeCompat.MoveChildSafely((Node)(object)parent, (Node?)(object)val2, 0);
					((Node2D)val2).Position = new Vector2(num2, -50f * (float)i);
					if (i > 0)
					{
						((CanvasItem)val2).Modulate = new Color(0.5f, 0.5f, 0.5f, 1f);
					}
					num2 -= 275f;
					list2.Add(val2);
				}
			}
			ModCreatureVisualPlayback.RegisterFakeMerchantPlayerVisuals(screen, list2, list);
			if (!val.StartedFight)
			{
				TaskHelper.RunSafely(ShowWelcomeDialogueInvoker(screen));
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Replaces only the base game's merchant-character instantiation so RitsuLib procedural or resource
	///         overrides can supply the node while the base game retains room setup, layout, and ready-time animation
	///         startup.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         仅替换游戏本体创建商人角色的步骤，使 RitsuLib 的程序化形象或资源替换能够提供节点，而房间初始化、
	///         布局及节点准备就绪时的动画启动仍由游戏本体负责。
	///     </para>
	/// </summary>
	internal class NMerchantRoomProceduralCharacterInstantiationPatch : IPatchMethod
	{
		private static readonly MethodInfo? InstantiateMerchantCharacterMethod = ResolveInstantiateMerchantMethod();

		private static readonly MethodInfo? PreloadManagerCacheGetter = AccessTools.DeclaredPropertyGetter(typeof(PreloadManager), "Cache");

		private static readonly MethodInfo? GetSceneMethod = AccessTools.DeclaredMethod(typeof(AssetCache), "GetScene", new Type[1] { typeof(string) }, (Type[])null);

		private static readonly MethodInfo? PlayerCharacterGetter = AccessTools.DeclaredPropertyGetter(typeof(Player), "Character");

		private static readonly FieldInfo? PlayersField = AccessTools.DeclaredField(typeof(NMerchantRoom), "_players");

		private static readonly MethodInfo? PlayerListItemGetter = AccessTools.DeclaredPropertyGetter(typeof(List<Player>), "Item");

		private static readonly MethodInfo? MerchantAnimPathGetter = AccessTools.DeclaredPropertyGetter(typeof(CharacterModel), "MerchantAnimPath");

		private static readonly MethodInfo CreateMerchantCharacterMethod = AccessTools.DeclaredMethod(typeof(NMerchantRoomProceduralCharacterInstantiationPatch), "CreateMerchantCharacter", (Type[])null, (Type[])null);

		public static string PatchId => "n_merchant_room_procedural_character_instantiation";

		public static string Description => "Instantiate only RitsuLib-owned merchant character overrides while preserving vanilla room setup";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NMerchantRoom), "AfterRoomIsLoaded")
			};
		}

		public static IEnumerable<CodeInstruction> Transpiler(IEnumerable<CodeInstruction> instructions)
		{
			HarmonyIlRewriter harmonyIlRewriter = HarmonyIlRewriter.From(instructions);
			if (PreloadManagerCacheGetter == null || GetSceneMethod == null || PlayerCharacterGetter == null || PlayersField == null || PlayerListItemGetter == null || MerchantAnimPathGetter == null || InstantiateMerchantCharacterMethod == null)
			{
				RitsuLibFramework.Logger.Warn("[WorldVisuals] Merchant character runtime factory could not resolve required reflection handles; patch skipped.", 1);
				return harmonyIlRewriter.InstructionsChecked("[WorldVisuals] Merchant character runtime factory");
			}
			IReadOnlyList<HarmonyIlMatch> readOnlyList = HarmonyIlPattern.Sequence(HarmonyIl.IsCall(PreloadManagerCacheGetter), HarmonyIl.IsLdarg(), HarmonyIl.IsLdfld(PlayersField), HarmonyIl.IsLdloc(), HarmonyIl.IsCall(PlayerListItemGetter), HarmonyIl.IsCall(PlayerCharacterGetter), HarmonyIl.IsCall(MerchantAnimPathGetter), HarmonyIl.IsCall(GetSceneMethod), HarmonyIl.IsLdcI4(0), HarmonyIl.Is(OpCodes.Conv_I8), HarmonyIl.IsCall(InstantiateMerchantCharacterMethod)).FindAll(harmonyIlRewriter.Code);
			if (readOnlyList.Count != 1)
			{
				if (!harmonyIlRewriter.Contains((CodeInstruction instruction) => HarmonyIl.IsCallTo(instruction, CreateMerchantCharacterMethod)))
				{
					RitsuLibFramework.Logger.Warn($"{"[WorldVisuals] Merchant character runtime factory"} expected one merchant scene instantiation, found {readOnlyList.Count}; patch skipped.", 1);
				}
				return harmonyIlRewriter.InstructionsChecked("[WorldVisuals] Merchant character runtime factory");
			}
			HarmonyIlMatch match = readOnlyList[0];
			harmonyIlRewriter.Replace(match, new global::<>z__ReadOnlyArray<CodeInstruction>((CodeInstruction[])(object)new CodeInstruction[6]
			{
				harmonyIlRewriter.Code[match.Index + 1].Clone(),
				harmonyIlRewriter.Code[match.Index + 2].Clone(),
				harmonyIlRewriter.Code[match.Index + 3].Clone(),
				harmonyIlRewriter.Code[match.Index + 4].Clone(),
				harmonyIlRewriter.Code[match.Index + 5].Clone(),
				HarmonyIl.Call(CreateMerchantCharacterMethod)
			}));
			return harmonyIlRewriter.InstructionsChecked("[WorldVisuals] Merchant character runtime factory");
		}

		internal static bool HasRitsuMerchantVisualOverride(CharacterModel character)
		{
			if (character is IModCharacterAssetOverrides modCharacterAssetOverrides)
			{
				CharacterWorldProceduralVisualSet worldProceduralVisuals = modCharacterAssetOverrides.WorldProceduralVisuals;
				if ((object)worldProceduralVisuals != null && (object)worldProceduralVisuals.Merchant != null)
				{
					return true;
				}
			}
			string path;
			return CharacterAssetOverridePatchHelper.TryResolveOverridePath(character, (IModCharacterAssetOverrides overrides) => overrides.CustomMerchantAnimPath, "CustomMerchantAnimPath", out path);
		}

		internal static NMerchantCharacter CreateMerchantCharacter(CharacterModel character)
		{
			NMerchantCharacter val = ModWorldSceneVisualNodeFactory.TryInstantiateMerchantCharacter(character);
			if (val == null && CharacterAssetOverridePatchHelper.TryResolveOverridePath(character, (IModCharacterAssetOverrides overrides) => overrides.CustomMerchantAnimPath, "CustomMerchantAnimPath", out string path))
			{
				val = CharacterWorldScenePathFactoryHelper.CreateFromSceneOrTexture<NMerchantCharacter>(character, path, "CustomMerchantAnimPath", (GenEditState)0);
			}
			if (val == null)
			{
				return PreloadManager.Cache.GetScene(character.MerchantAnimPath).Instantiate<NMerchantCharacter>((GenEditState)0);
			}
			ModMerchantCharacterVisualPlaybackPatch.RegisterRitsuMerchantVisual(val, character);
			return val;
		}

		private static MethodInfo? ResolveInstantiateMerchantMethod()
		{
			return (from method in (from method in typeof(PackedScene).GetMethods(BindingFlags.Instance | BindingFlags.Public)
					where method.Name == "Instantiate" && (object)method != null && method.IsGenericMethodDefinition && method.GetGenericArguments().Length == 1
					select method).Where(delegate(MethodInfo method)
				{
					ParameterInfo[] parameters = method.GetParameters();
					return parameters.Length == 1 && parameters[0].ParameterType == typeof(GenEditState);
				})
				select method.MakeGenericMethod(typeof(NMerchantCharacter))).FirstOrDefault();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Creates <see cref="T:MegaCrit.Sts2.Core.Nodes.RestSite.NRestSiteCharacter" /> nodes through the procedural rest-site definition when one
	///         is available; otherwise, creates a compatible node from the character's rest-site scene or texture.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         有可用的程序化休息处定义时，通过该定义创建 <see cref="T:MegaCrit.Sts2.Core.Nodes.RestSite.NRestSiteCharacter" /> 节点；否则从角色的
	///         休息处场景或纹理创建兼容节点。
	///     </para>
	/// </summary>
	internal class NRestSiteCharacterCreateProceduralPatch : IPatchMethod
	{
		private static readonly FieldRef<NRestSiteCharacter, int> RestSiteCharacterIndexRef = AccessTools.FieldRefAccess<NRestSiteCharacter, int>("_characterIndex");

		public static string PatchId => "n_rest_site_character_create_procedural";

		public static string Description => "Build procedural NRestSiteCharacter when WorldProceduralVisuals.RestSite is defined";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NRestSiteCharacter), "Create")
			};
		}

		public static bool Prefix(Player player, int characterIndex, ref NRestSiteCharacter __result)
		{
			NRestSiteCharacter val = ModWorldSceneVisualNodeFactory.TryCreateRestSiteCharacter(player, characterIndex);
			if (val != null)
			{
				__result = val;
				return false;
			}
			__result = CharacterWorldScenePathFactoryHelper.CreateFromSceneOrTexture<NRestSiteCharacter>(player.Character, player.Character.RestSiteAnimPath, "CustomRestSiteAnimPath", (GenEditState)0);
			__result.Player = player;
			RestSiteCharacterIndexRef.Invoke(__result) = characterIndex;
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         After the rest-site room finishes layout, starts the act-specific loop on character visuals backed by
	///         a rest-site state machine or
	///         <see cref="P:STS2RitsuLib.Scaffolding.Characters.IModCharacterAssetOverrides.WorldProceduralVisuals" /><c>.RestSite</c>.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         休息处房间完成布局后，对由休息处状态机或
	///         <see cref="P:STS2RitsuLib.Scaffolding.Characters.IModCharacterAssetOverrides.WorldProceduralVisuals" /><c>.RestSite</c>
	///         驱动的角色形象播放当前章节对应的循环动画。
	///     </para>
	/// </summary>
	internal class NRestSiteRoomProceduralVisualPlaybackPatch : IPatchMethod
	{
		private sealed class StateMachineSlot
		{
			private bool _built;

			public ModAnimStateMachine? StateMachine { get; private set; }

			public void EnsureBuilt(IModCharacterRestSiteAnimationStateMachineFactory factory, Node root, CharacterModel character)
			{
				if (!_built)
				{
					StateMachine = factory.TryCreateRestSiteAnimationStateMachine(root, character);
					_built = true;
				}
			}
		}

		private static readonly ConditionalWeakTable<NRestSiteCharacter, StateMachineSlot> StateMachinesByRoot = new ConditionalWeakTable<NRestSiteCharacter, StateMachineSlot>();

		public static string PatchId => "n_rest_site_room_procedural_visual_playback";

		public static string Description => "Apply procedural rest-site frame / texture cues after NRestSiteRoom._Ready";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NRestSiteRoom), "_Ready")
			};
		}

		public static void Postfix(NRestSiteRoom __instance)
		{
			foreach (NRestSiteCharacter character in __instance.Characters)
			{
				Player player = character.Player;
				CharacterModel val = ((player != null) ? player.Character : null);
				if (val == null)
				{
					continue;
				}
				string text = RestSiteActLoopCue(player.RunState.CurrentActIndex);
				if (TryRouteToStateMachine(character, val, text) || !(val is IModCharacterAssetOverrides modCharacterAssetOverrides))
				{
					continue;
				}
				CharacterWorldProceduralVisualSet worldProceduralVisuals = modCharacterAssetOverrides.WorldProceduralVisuals;
				if ((object)worldProceduralVisuals == null)
				{
					continue;
				}
				CharacterRestSiteWorldDefinition restSite = worldProceduralVisuals.RestSite;
				if ((object)restSite != null)
				{
					VisualCueSet cueSet = restSite.CueSet;
					if ((object)cueSet != null)
					{
						ModCreatureVisualPlayback.TryPlayOnVisualRoot((Node)(object)character, val, text, loop: true, cueSet);
					}
				}
			}
		}

		private static bool TryRouteToStateMachine(NRestSiteCharacter restSiteCharacter, CharacterModel character, string anim)
		{
			if (!(character is IModCharacterRestSiteAnimationStateMachineFactory factory))
			{
				return false;
			}
			StateMachineSlot value = StateMachinesByRoot.GetValue(restSiteCharacter, (NRestSiteCharacter _) => new StateMachineSlot());
			value.EnsureBuilt(factory, (Node)(object)restSiteCharacter, character);
			if (value.StateMachine == null)
			{
				return false;
			}
			value.StateMachine.SetTrigger(ModCreatureVisualPlayback.MapWorldAnimationToStateMachineTrigger(anim));
			return true;
		}

		private static string RestSiteActLoopCue(int actIndex)
		{
			return actIndex switch
			{
				0 => "overgrowth_loop", 
				1 => "hive_loop", 
				2 => "glory_loop", 
				_ => "overgrowth_loop", 
			};
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Appends saved statistics for playable mod characters to the general statistics screen. The base
	///         <see cref="M:MegaCrit.Sts2.Core.Nodes.Screens.StatsScreen.NGeneralStatsGrid.LoadStats" /> implementation creates sections only for the five built-in
	///         characters.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将可玩模组角色的已保存统计数据追加到综合统计界面。游戏本体的
	///         <see cref="M:MegaCrit.Sts2.Core.Nodes.Screens.StatsScreen.NGeneralStatsGrid.LoadStats" /> 实现只会为五名内置角色创建区段。
	///     </para>
	/// </summary>
	internal class StatsScreenCharacterStatsPatch : IPatchMethod
	{
		private static readonly StringName RitsuLibCharacterStatsIdMeta;

		private static readonly FieldRef<NGeneralStatsGrid, Control> CharacterStatContainerRef;

		private static readonly FieldRef<NCharacterStats, CharacterStats> CharacterStatsRef;

		public static string PatchId => "stats_screen_mod_character_sections";

		public static string Description => "Append playable non-vanilla character progress records to NGeneralStatsGrid character history sections";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NGeneralStatsGrid), "LoadStats")
			};
		}

		[HarmonyPriority(0)]
		public static void Postfix(NGeneralStatsGrid __instance)
		{
			//IL_00b9: Unknown result type (might be due to invalid IL or missing references)
			ProgressState progress = SaveManager.Instance.Progress;
			Control val = CharacterStatContainerRef.Invoke(__instance);
			if (val == null)
			{
				return;
			}
			HashSet<ModelId> visibleCharacterIds = GetVisibleCharacterIds((Node)(object)val);
			foreach (CharacterStats item in progress.CharacterStats.Values.OrderBy<CharacterStats, string>(delegate(CharacterStats stats)
			{
				ModelId id2 = stats.Id;
				return (id2 == null) ? null : id2.Entry;
			}, StringComparer.Ordinal))
			{
				ModelId id = item.Id;
				if (id != null && !(id == ModelId.none) && !visibleCharacterIds.Contains(id))
				{
					CharacterModel byIdOrNull = ModelDb.GetByIdOrNull<CharacterModel>(id);
					if (byIdOrNull != null && byIdOrNull.IsPlayable)
					{
						NCharacterStats val2 = NCharacterStats.Create(item);
						((GodotObject)val2).SetMeta(RitsuLibCharacterStatsIdMeta, Variant.op_Implicit(((object)id).ToString()));
						RitsuGodotTreeCompat.AddChildSafely((Node)(object)val, (Node?)(object)val2);
						visibleCharacterIds.Add(id);
					}
				}
			}
		}

		private static HashSet<ModelId> GetVisibleCharacterIds(Node container)
		{
			HashSet<ModelId> hashSet = new HashSet<ModelId>();
			foreach (Node child in container.GetChildren(false))
			{
				NCharacterStats val = (NCharacterStats)(object)((child is NCharacterStats) ? child : null);
				if (val != null)
				{
					CharacterStats obj = CharacterStatsRef.Invoke(val);
					ModelId val2 = ((obj != null) ? obj.Id : null);
					if (val2 != null && val2 != ModelId.none)
					{
						hashSet.Add(val2);
					}
				}
			}
			return hashSet;
		}

		static StatsScreenCharacterStatsPatch()
		{
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_000f: Expected O, but got Unknown
			RitsuLibCharacterStatsIdMeta = new StringName("RitsuLibCharacterStatsId");
			CharacterStatContainerRef = AccessTools.FieldRefAccess<NGeneralStatsGrid, Control>("_characterStatContainer");
			CharacterStatsRef = AccessTools.FieldRefAccess<NCharacterStats, CharacterStats>("_characterStats");
		}
	}
}
