		/// <summary>
		///     <para xml:lang="en">Registers an untyped rule set for a <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> subtype.</para>
		///     <para xml:lang="zh-CN">为 <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> 子类型注册非泛型规则集。</para>
		/// </summary>
		public static void Register(Type cardType, ModCardHandOutlineRules rules)
		{
			ValidateRegistration(cardType);
			foreach (ModCardHandOutlineSwitchRule item in rules.Enumerate())
			{
				Register(cardType, item);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers an untyped rule for a <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> subtype.</para>
		///     <para xml:lang="zh-CN">为 <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> 子类型注册非泛型规则。</para>
		/// </summary>
		public static void Register(Type cardType, ModCardHandOutlineSwitchRule rule)
		{
			ArgumentNullException.ThrowIfNull(rule.ColorWhen, "rule.ColorWhen");
			ValidateRegistration(cardType);
			int sequence = Interlocked.Increment(ref _sequence);
			RegisteredRule wrapped = new RegisteredRule(rule, sequence);
			RulesByCardType.AddOrUpdate(cardType, delegate
			{
				int num = 1;
				List<RegisteredRule> list = new List<RegisteredRule>(num);
				CollectionsMarshal.SetCount(list, num);
				CollectionsMarshal.AsSpan(list)[0] = wrapped;
				return list;
			}, (Type _, List<RegisteredRule> existing) => new List<RegisteredRule>(existing) { wrapped });
			Volatile.Write(ref _hasAny, 1);
		}

