		/// </summary>
		public static void ClearForTests()
		{
			RulesByCardType.Clear();
			LoggedRuleFailures.Clear();
			Volatile.Write(ref _hasAny, 0);
		}

		/// <summary>
		///     <para xml:lang="en">Applies the highest-priority matching outline to a hand-card holder.</para>
		///     <para xml:lang="zh-CN">将优先级最高的匹配描边应用到手牌容器。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> if an outline was applied.</para>
		///     <para xml:lang="zh-CN">成功应用描边时为 <see langword="true" />。</para>
		/// </returns>
		public static bool TryRefreshOutlineForHolder(NHandCardHolder? holder)
		{
			if (!ModCardHandOutlinePatchHelper.TryGetRule(holder, out CardModel model, out ModCardHandOutlineEvaluation evaluation))
			{
				return false;
			}
			return ModCardHandOutlinePatchHelper.ApplyHighlight(holder, model, evaluation);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Applies the highest-priority matching outline only when its rule requests per-frame refresh.
		///     </para>
		///     <para xml:lang="zh-CN">仅当优先级最高的匹配规则要求逐帧刷新时应用描边。</para>
		/// </summary>
		public static bool TryRefreshDynamicOutlineForHolder(NHandCardHolder? holder)
		{
			if (!ModCardHandOutlinePatchHelper.TryGetRule(holder, out CardModel model, out ModCardHandOutlineEvaluation evaluation) || !evaluation.Rule.RefreshEveryFrame)
			{
				return false;
			}
			return ModCardHandOutlinePatchHelper.ApplyHighlight(holder, model, evaluation);
		}

		internal static ModCardHandOutlineEvaluation? EvaluateBest(CardModel model)
		{
			//IL_000a: Unknown result type (might be due to invalid IL or missing references)
			//IL_016c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0101: Unknown result type (might be due to invalid IL or missing references)
			//IL_0106: Unknown result type (might be due to invalid IL or missing references)
			RegisteredRule? registeredRule = null;
			Color color = default(Color);
			Type type = ((object)model).GetType();
			while (type != null && typeof(CardModel).IsAssignableFrom(type))
			{
				if (RulesByCardType.TryGetValue(type, out List<RegisteredRule> value))
				{
					foreach (RegisteredRule item in value)
					{
						Color? val;
						try
						{
							val = item.Rule.ResolveColor(model);
						}
						catch (Exception value2)
						{
							if (LoggedRuleFailures.TryAdd(item.Sequence, 0))
							{
								RitsuLibFramework.Logger.Warn($"[CardHandOutline] Rule {item.Sequence} for {type.FullName} threw and was ignored: {value2}", 1);
							}
							continue;
						}
						if (val.HasValue && (!registeredRule.HasValue || !IsLowerPriority(item, registeredRule.Value)))
						{
							registeredRule = item;
							color = val.Value;
						}
					}
				}
				type = type.BaseType;
			}
			if (!registeredRule.HasValue)
			{
				return null;
			}
			return new ModCardHandOutlineEvaluation(registeredRule.Value.Rule, color);
		}

		private static bool IsLowerPriority(RegisteredRule candidate, RegisteredRule best)
		{
			if (candidate.Rule.Priority >= best.Rule.Priority)
			{
				if (candidate.Rule.Priority == best.Rule.Priority)
				{
					return candidate.Sequence <= best.Sequence;
				}
				return false;
			}
			return true;
		}

		private static void ValidateRegistration(Type cardType)
		{
			ArgumentNullException.ThrowIfNull(cardType, "cardType");
			if (ModContentRegistry.IsFrozen)
			{
				throw new InvalidOperationException("Cannot register card hand outline rules after content registration has been frozen. Register from your mod initializer before ModelDb initializes.");
			}
			if (cardType.IsInterface || cardType.ContainsGenericParameters || !typeof(CardModel).IsAssignableFrom(cardType))
			{
				throw new ArgumentException($"Type '{cardType.FullName}' must be a closed subtype of {typeof(CardModel).FullName}.", "cardType");
			}
		}
	}
