	internal static class ModCardHandOutlinePatchHelper
	{
		private static readonly FieldInfo? HandField = AccessTools.Field(typeof(NHandCardHolder), "_hand");

		internal static bool TryGetRule(NHandCardHolder? holder, out CardModel model, out ModCardHandOutlineEvaluation evaluation)
		{
			model = null;
			evaluation = default(ModCardHandOutlineEvaluation);
			if (!TryGetCardModel(holder, out CardModel model2))
			{
				return false;
			}
			ModCardHandOutlineEvaluation? modCardHandOutlineEvaluation = ModCardHandOutlineRegistry.EvaluateBest(model2);
			if (modCardHandOutlineEvaluation.HasValue)
			{
				ModCardHandOutlineEvaluation valueOrDefault = modCardHandOutlineEvaluation.GetValueOrDefault();
				model = model2;
				evaluation = valueOrDefault;
				return true;
			}
			return false;
		}

		internal static bool ApplyHighlight(NHandCardHolder? holder, CardModel model, ModCardHandOutlineEvaluation evaluation)
		{
			//IL_008c: Unknown result type (might be due to invalid IL or missing references)
			CombatManager instance = CombatManager.Instance;
			if (instance == null || !instance.IsInProgress || !TryGetCardModel(holder, out CardModel model2) || model2 != model)
			{
				return false;
			}
			try
			{
				NCard cardNode = ((NCardHolder)holder).CardNode;
				if (cardNode == null || !GodotObject.IsInstanceValid((GodotObject)(object)cardNode) || !GodotObject.IsInstanceValid((GodotObject)(object)cardNode.CardHighlight))
				{
					return false;
				}
				bool flag = ShouldShowBuiltInHighlight(holder, model);
				bool flag2 = evaluation.Rule.VisibleWhenUnplayable && !flag;
				if (!flag && !flag2)
				{
					return false;
				}
				NCardHighlight cardHighlight = cardNode.CardHighlight;
				if (flag2)
				{
					cardHighlight.AnimShow();
				}
				((CanvasItem)cardHighlight).Modulate = evaluation.Color;
				return true;
			}
			catch (ObjectDisposedException)
			{
				return false;
			}
		}

		internal static void ApplyFlash(NHandCardHolder? holder, CardModel model, ModCardHandOutlineEvaluation evaluation)
		{
			//IL_006a: Unknown result type (might be due to invalid IL or missing references)
			if (!IsHolderUsable(holder))
			{
				return;
			}
			try
			{
				object? obj = AccessTools.Field(typeof(NHandCardHolder), "_flash")?.GetValue(holder);
				Control val = (Control)((obj is Control) ? obj : null);
				if (val != null && GodotObject.IsInstanceValid((GodotObject)(object)val))
				{
					bool flag = ShouldShowBuiltInHighlight(holder, model);
					bool flag2 = evaluation.Rule.VisibleWhenUnplayable && !flag;
					if (flag || flag2)
					{
						((CanvasItem)val).Modulate = evaluation.Color;
					}
				}
			}
			catch (ObjectDisposedException)
			{
			}
		}

		private static bool TryGetCardModel(NHandCardHolder? holder, out CardModel model)
		{
			model = null;
			if (!IsHolderUsable(holder))
			{
				return false;
			}
			try
			{
				NCard cardNode = ((NCardHolder)holder).CardNode;
				if (cardNode != null && GodotObject.IsInstanceValid((GodotObject)(object)cardNode))
				{
					CardModel model2 = cardNode.Model;
					if (model2 != null)
					{
						model = model2;
						return true;
					}
				}
				return false;
			}
			catch (ObjectDisposedException)
			{
				return false;
			}
		}

		private static bool ShouldShowBuiltInHighlight(NHandCardHolder holder, CardModel model)
		{
			bool flag = model.CanPlay();
			bool flag2 = model.IsOwnerPlayPhase();
			bool flag3 = flag2 && model.ShouldGlowRed;
			object? obj = HandField?.GetValue(holder);
			object? obj2 = ((obj is NPlayerHand) ? obj : null);
			bool flag4 = ((obj2 != null) ? ((NPlayerHand)obj2).SelectModeGoldGlowOverride : null)?.Invoke(model) ?? ((flag2 & flag) && model.ShouldGlowGold);
			return flag | flag3 | flag4;
		}

		private static bool IsHolderUsable(NHandCardHolder? holder)
		{
			if (holder == null || !GodotObject.IsInstanceValid((GodotObject)(object)holder))
			{
				return false;
			}
			try
			{
				return ((Node)holder).IsNodeReady() && ((Node)holder).IsInsideTree();
			}
			catch (ObjectDisposedException)
			{
				return false;
			}
		}
	}
