		}

		/// <inheritdoc cref="M:STS2RitsuLib.Scaffolding.Cards.HandGlow.ModCardHandGlowPredicates.ThisCardNotFinishedPlayThisTurn(MegaCrit.Sts2.Core.Models.CardModel)" />
		public static bool ModHandGlowThisCardNotFinishedPlayThisTurn(this CardModel card)
		{
			return ModCardHandGlowPredicates.ThisCardNotFinishedPlayThisTurn(card);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Combines <see cref="T:STS2RitsuLib.Scaffolding.Cards.HandGlow.ModCardHandGlowRules" /> predicates.</para>
	///     <para xml:lang="zh-CN">组合 <see cref="T:STS2RitsuLib.Scaffolding.Cards.HandGlow.ModCardHandGlowRules" /> 使用的谓词。</para>
	/// </summary>
	public static class ModCardHandGlowCombine
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Returns the logical OR of all non-<see langword="null" /> predicates, or a predicate that returns
		///         <see langword="false" /> when none are supplied.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回所有非 <see langword="null" /> 谓词的逻辑或；未提供此类谓词时，所得谓词返回
		///         <see langword="false" />。
		///     </para>
		/// </summary>
		public static Func<CardModel, bool> Or(params Func<CardModel, bool>?[] parts)
		{
			ArgumentNullException.ThrowIfNull(parts, "parts");
			Func<CardModel, bool>[] filtered = parts.OfType<Func<CardModel, bool>>().ToArray();
			if (filtered.Length != 0)
			{
				return (CardModel card) => filtered.Any((Func<CardModel, bool> predicate) => predicate(card));
			}
			return (CardModel _) => false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the logical AND of all non-<see langword="null" /> predicates, or a predicate that returns
		///         <see langword="true" /> when none are supplied.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回所有非 <see langword="null" /> 谓词的逻辑与；未提供此类谓词时，所得谓词返回
		///         <see langword="true" />。
		///     </para>
		/// </summary>
		public static Func<CardModel, bool> And(params Func<CardModel, bool>?[] parts)
		{
			ArgumentNullException.ThrowIfNull(parts, "parts");
			Func<CardModel, bool>[] filtered = parts.Where((Func<CardModel, bool> p) => p != null).Cast<Func<CardModel, bool>>().ToArray();
			if (filtered.Length == 0)
			{
				return (CardModel _) => true;
			}
			return (CardModel card) => filtered.All((Func<CardModel, bool> p) => p(card));
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides reusable hand-glow conditions derived from vanilla card behavior.</para>
	///     <para xml:lang="zh-CN">提供依据原版卡牌行为实现的可复用手牌发光条件。</para>
	/// </summary>
	public static class ModCardHandGlowPredicates
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether the card owner's Osty is missing, as used by vanilla Osty attack cards.
		///     </para>
		///     <para xml:lang="zh-CN">返回卡牌拥有者的奥斯提是否缺席，与原版奥斯提攻击牌一致。</para>
		/// </summary>
		public static bool OwnerCompanionOstyMissing(CardModel card)
		{
			Player owner = card.Owner;
			if (owner == null)
			{
				return false;
			}
			return owner.IsOstyMissing;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether the card's owner exhausted a card this turn, matching
		///         <see cref="T:MegaCrit.Sts2.Core.Models.Cards.EvilEye" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回卡牌拥有者本回合是否消耗过卡牌，与
		///         <see cref="T:MegaCrit.Sts2.Core.Models.Cards.EvilEye" /> 一致。
		///     </para>
		/// </summary>
		public static bool AnyOfOwnersCardsExhaustedThisTurn(CardModel card)
		{
			Player owner = card.Owner;
			ICombatState combat = card.CombatState;
			CombatManager instance = CombatManager.Instance;
			CombatHistory val = ((instance != null) ? instance.History : null);
			if (owner == null || combat == null || val == null)
			{
				return false;
			}
			return val.Entries.OfType<CardExhaustedEntry>().Any((CardExhaustedEntry e) => ((CombatHistoryEntry)e).HappenedThisTurn(combat) && ((CombatHistoryEntry)e).Actor == owner.Creature);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether this card has not finished a play this turn, matching the gold-glow condition of
		///         <see cref="T:MegaCrit.Sts2.Core.Models.Cards.Fetch" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回此卡本回合是否尚未完成一次打出，与
		///         <see cref="T:MegaCrit.Sts2.Core.Models.Cards.Fetch" /> 的金色发光条件一致。
		///     </para>
		/// </summary>
		public static bool ThisCardNotFinishedPlayThisTurn(CardModel card)
		{
			ICombatState combat = card.CombatState;
			CombatManager instance = CombatManager.Instance;
			CombatHistory val = ((instance != null) ? instance.History : null);
			if (combat == null || val == null)
			{
				return false;
			}
			return !val.CardPlaysFinished.Any((CardPlayFinishedEntry e) => e.CardPlay.Card == card && ((CombatHistoryEntry)e).HappenedThisTurn(combat));
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Registers card-type rules that contribute to <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.ShouldGlowGold" /> and
	///         <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.ShouldGlowRed" />. Rules registered for a base card type also apply to derived types.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         注册参与计算 <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.ShouldGlowGold" /> 与 <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.ShouldGlowRed" />
	///         的卡牌类型规则；为卡牌基类注册的规则也适用于其派生类型。
	///     </para>
	/// </summary>
	public static class ModCardHandGlowRegistry
	{
		private readonly record struct RegisteredRules(ModCardHandGlowRules Rules, int Sequence);

		private static readonly ConcurrentDictionary<string, byte> LoggedRuleFailures = new ConcurrentDictionary<string, byte>(StringComparer.Ordinal);

		private static readonly ConcurrentDictionary<Type, List<RegisteredRules>> RulesByCardType = new ConcurrentDictionary<Type, List<RegisteredRules>>();

		private static int _sequence;

		private static readonly Func<ModCardHandGlowRules, Func<CardModel, bool>?> GoldSelector = (ModCardHandGlowRules rules) => rules.GoldWhenBonusActive;

		private static readonly Func<ModCardHandGlowRules, Func<CardModel, bool>?> RedSelector = (ModCardHandGlowRules rules) => rules.RedWhenHandWarning;

		/// <summary>
		///     <para xml:lang="en">
		///         Registers rules for <typeparamref name="TCard" />. Every matching registration is evaluated until
		///         one returns <see langword="true" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <typeparamref name="TCard" /> 注册规则。所有匹配的注册会依次评估，直至其中一项返回
		///         <see langword="true" />。
		///     </para>
		/// </summary>
		public static void Register<TCard>(ModCardHandGlowRules rules) where TCard : CardModel
		{
			Register(typeof(TCard), rules);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers rules for a concrete <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> subtype.
		///     </para>
		///     <para xml:lang="zh-CN">为具体的 <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> 子类型注册规则。</para>
		/// </summary>
		public static void Register(Type cardType, ModCardHandGlowRules rules)
		{
			ArgumentNullException.ThrowIfNull(cardType, "cardType");
			if (ModContentRegistry.IsFrozen)
			{
				throw new InvalidOperationException("Cannot register card hand glow rules after content registration has been frozen. Register from your mod initializer before ModelDb initializes.");
			}
			if (cardType.IsAbstract || cardType.IsInterface || cardType.ContainsGenericParameters || !typeof(CardModel).IsAssignableFrom(cardType))
			{
				throw new ArgumentException($"Type '{cardType.FullName}' must be a closed concrete subtype of {typeof(CardModel).FullName}.", "cardType");
			}
			RegisteredRules registered = new RegisteredRules(rules, Interlocked.Increment(ref _sequence));
			RulesByCardType.AddOrUpdate(cardType, delegate
			{
				int num = 1;
				List<RegisteredRules> list = new List<RegisteredRules>(num);
				CollectionsMarshal.SetCount(list, num);
				CollectionsMarshal.AsSpan(list)[0] = registered;
				return list;
			}, delegate(Type _, List<RegisteredRules> existing)
			{
				int num = 1 + existing.Count;
				List<RegisteredRules> list = new List<RegisteredRules>(num);
				CollectionsMarshal.SetCount(list, num);
				Span<RegisteredRules> span = CollectionsMarshal.AsSpan(list);
				int num2 = 0;
				Span<RegisteredRules> span2 = CollectionsMarshal.AsSpan(existing);
				span2.CopyTo(span.Slice(num2, span2.Length));
				num2 += span2.Length;
				span[num2] = registered;
				return list;
			});
		}

		/// <summary>
		///     <para xml:lang="en">Clears all rules for tests or hot-reload tooling.</para>
		///     <para xml:lang="zh-CN">清除所有规则，供测试或热重载工具使用。</para>
		/// </summary>
		public static void ClearForTests()
		{
			RulesByCardType.Clear();
			LoggedRuleFailures.Clear();
		}

		internal static bool EvaluateRegistryGold(CardModel card)
		{
			return EvaluateChannel(card, GoldSelector, "gold");
		}

		internal static bool EvaluateRegistryRed(CardModel card)
		{
			return EvaluateChannel(card, RedSelector, "red");
		}

		private static bool EvaluateChannel(CardModel card, Func<ModCardHandGlowRules, Func<CardModel, bool>?> selector, string channel)
		{
			Type type = ((object)card).GetType();
			while (type != null && typeof(CardModel).IsAssignableFrom(type))
			{
				if (RulesByCardType.TryGetValue(type, out List<RegisteredRules> value))
				{
					foreach (RegisteredRules item in value)
					{
						Func<CardModel, bool> func = selector(item.Rules);
						if (func == null)
						{
							continue;
						}
						try
						{
							if (func(card))
							{
								return true;
							}
						}
						catch (Exception value2)
						{
							string key = $"{item.Sequence}|{channel}";
							if (LoggedRuleFailures.TryAdd(key, 0))
							{
								RitsuLibFramework.Logger.Warn($"[CardHandGlow] {channel} rule {item.Sequence} for {type.FullName} threw and was ignored: {value2}", 1);
							}
						}
					}
				}
				type = type.BaseType;
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines optional predicates for the game's gold and red card-glow channels.
	///     </para>
	///     <para xml:lang="zh-CN">定义游戏金色与红色卡牌发光通道使用的可选谓词。</para>
	/// </summary>
	public readonly record struct ModCardHandGlowRules
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Predicate that contributes to <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.ShouldGlowGold" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         参与计算 <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.ShouldGlowGold" /> 的谓词。
		///     </para>
		/// </summary>
		public Func<CardModel, bool>? GoldWhenBonusActive { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Predicate that contributes to <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.ShouldGlowRed" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         参与计算 <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.ShouldGlowRed" /> 的谓词。
		///     </para>
		/// </summary>
		public Func<CardModel, bool>? RedWhenHandWarning { get; init; }

		/// <summary>
		///     <para xml:lang="en">Creates a rule set with only a gold-glow predicate.</para>
		///     <para xml:lang="zh-CN">创建仅包含金色发光谓词的规则集。</para>
		/// </summary>
		public static ModCardHandGlowRules Gold(Func<CardModel, bool> whenBonusActive)
		{
			ArgumentNullException.ThrowIfNull(whenBonusActive, "whenBonusActive");
			return new ModCardHandGlowRules
			{
				GoldWhenBonusActive = whenBonusActive
			};
		}

		/// <summary>
		///     <para xml:lang="en">Creates a rule set with only a red-glow predicate.</para>
		///     <para xml:lang="zh-CN">创建仅包含红色发光谓词的规则集。</para>
		/// </summary>
		public static ModCardHandGlowRules Red(Func<CardModel, bool> whenHandWarning)
		{
			ArgumentNullException.ThrowIfNull(whenHandWarning, "whenHandWarning");
			return new ModCardHandGlowRules
			{
				RedWhenHandWarning = whenHandWarning
			};
		}

		/// <summary>
		///     <para xml:lang="en">Creates a rule set for both glow channels.</para>
		///     <para xml:lang="zh-CN">创建同时包含两个发光通道的规则集。</para>
		/// </summary>
		public static ModCardHandGlowRules GoldAndRed(Func<CardModel, bool>? goldWhenBonusActive, Func<CardModel, bool>? redWhenHandWarning)
		{
			return new ModCardHandGlowRules
			{
				GoldWhenBonusActive = goldWhenBonusActive,
				RedWhenHandWarning = redWhenHandWarning
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns a rule set that combines corresponding predicates with logical OR.
		///     </para>
		///     <para xml:lang="zh-CN">返回将对应通道谓词按逻辑或组合后的规则集。</para>
		/// </summary>
		public ModCardHandGlowRules Or(ModCardHandGlowRules other)
		{
			return new ModCardHandGlowRules
			{
				GoldWhenBonusActive = CombineOr(GoldWhenBonusActive, other.GoldWhenBonusActive),
				RedWhenHandWarning = CombineOr(RedWhenHandWarning, other.RedWhenHandWarning)
			};
		}

		private static Func<CardModel, bool>? CombineOr(Func<CardModel, bool>? a, Func<CardModel, bool>? b)
		{
			if (a == null)
			{
				return b;
			}
			if (b != null)
			{
				return (CardModel c) => a(c) || b(c);
			}
			return a;
		}
	}
}
namespace STS2RitsuLib.Scaffolding.Cards.HandGlow.Patches
{
	/// <summary>
	///     <para xml:lang="en">
	///         Adds <see cref="T:STS2RitsuLib.Scaffolding.Cards.HandGlow.ModCardHandGlowRegistry" /> gold rules to
	///         <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.ShouldGlowGold" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将 <see cref="T:STS2RitsuLib.Scaffolding.Cards.HandGlow.ModCardHandGlowRegistry" /> 的金色规则加入
	///         <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.ShouldGlowGold" /> 的计算。
	///     </para>
	/// </summary>
	internal sealed class CardModelShouldGlowGoldRegistryPatch : IPatchMethod
	{
		public static string PatchId => "card_model_should_glow_gold_registry";

		public static string Description => "Merge ModCardHandGlowRegistry gold predicates into CardModel.ShouldGlowGold";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(CardModel), "ShouldGlowGold", null, IgnoreIfMissing: true, (MethodType)1)
			};
		}

		public static void Postfix(CardModel __instance, ref bool __result)
		{
			if (!__result && ModCardHandGlowRegistry.EvaluateRegistryGold(__instance))
			{
				__result = true;
			}
		}
	}
