namespace STS2RitsuLib.Scaffolding.Ancients.Options
{
	/// <summary>
	///     <para xml:lang="en">Registers rules that add choices to an Ancient's initial option list.</para>
	///     <para xml:lang="zh-CN">注册向先古之民初始选项列表添加选项的规则。</para>
	/// </summary>
	public static class ModAncientOptionRegistry
	{
		private readonly record struct RegisteredRule(string OwnerModId, ModAncientOptionRule Rule, long RegistrationOrder);

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<Type, List<RegisteredRule>> RulesByAncientType = new Dictionary<Type, List<RegisteredRule>>();

		private static long _registrationCounter;

		/// <summary>
		///     <para xml:lang="en">
		///         Registers an option rule for <typeparamref name="TAncient" /> and its derived types.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <typeparamref name="TAncient" /> 及其派生类型注册选项规则。
		///     </para>
		/// </summary>
		public static void Register<TAncient>(string ownerModId, ModAncientOptionRule rule) where TAncient : AncientEventModel
		{
			Register(typeof(TAncient), ownerModId, rule);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers an option rule for <paramref name="ancientType" /> and its derived types.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="ancientType" /> 及其派生类型注册选项规则。
		///     </para>
		/// </summary>
		public static void Register(Type ancientType, string ownerModId, ModAncientOptionRule rule)
		{
			ArgumentNullException.ThrowIfNull(ancientType, "ancientType");
			ArgumentException.ThrowIfNullOrWhiteSpace(ownerModId, "ownerModId");
			ArgumentNullException.ThrowIfNull(rule, "rule");
			if (ModContentRegistry.IsFrozen)
			{
				throw new InvalidOperationException("Cannot register ancient option rules after content registration has been frozen. Register from your mod initializer before ModelDb initializes.");
			}
			if (ancientType.IsAbstract || ancientType.IsInterface || ancientType.ContainsGenericParameters || !typeof(AncientEventModel).IsAssignableFrom(ancientType))
			{
				throw new ArgumentException($"Type '{ancientType.FullName}' must be a closed concrete subtype of {typeof(AncientEventModel).FullName}.", "ancientType");
			}
			RegisteredRule item = new RegisteredRule(ownerModId.Trim(), rule, Interlocked.Increment(ref _registrationCounter));
			using (SyncRoot.EnterScope())
			{
				if (!RulesByAncientType.TryGetValue(ancientType, out List<RegisteredRule> value))
				{
					value = new List<RegisteredRule>();
					RulesByAncientType[ancientType] = value;
				}
				value.Add(item);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Clears all registered rules for tests or hot-reload tooling.</para>
		///     <para xml:lang="zh-CN">清除所有已注册规则，供测试或热重载工具使用。</para>
		/// </summary>
		public static void ClearForTests()
		{
			using (SyncRoot.EnterScope())
			{
				RulesByAncientType.Clear();
				_registrationCounter = 0L;
			}
		}

		internal static void AppendRegisteredOptions(AncientEventModel ancient, List<EventOption> options)
		{
			ArgumentNullException.ThrowIfNull(ancient, "ancient");
			ArgumentNullException.ThrowIfNull(options, "options");
			HashSet<string> hashSet = new HashSet<string>(from option in options
				select option.TextKey into textKey
				where !string.IsNullOrWhiteSpace(textKey)
				select textKey, StringComparer.OrdinalIgnoreCase);
			RegisteredRule[] applicableRulesSnapshot = GetApplicableRulesSnapshot(((object)ancient).GetType());
			for (int num = 0; num < applicableRulesSnapshot.Length; num++)
			{
				RegisteredRule registration = applicableRulesSnapshot[num];
				if (!ShouldApply(registration, ancient))
				{
					continue;
				}
				EventOption[] array;
				try
				{
					array = registration.Rule.OptionFactory(ancient)?.ToArray();
				}
				catch (Exception value)
				{
					RitsuLibFramework.CreateLogger(registration.OwnerModId, (LogType)0).Warn($"[AncientOption] OptionFactory threw for ancient '{((AbstractModel)ancient).Id.Entry}': {value}", 1);
					continue;
				}
				if (array == null)
				{
					continue;
				}
				EventOption[] array2 = array;
				foreach (EventOption val in array2)
				{
					if (val == null)
					{
						continue;
					}
					if (!string.IsNullOrWhiteSpace(val.TextKey))
					{
						bool flag = hashSet.Add(val.TextKey);
						if (registration.Rule.SkipDuplicateTextKeys && !flag)
						{
							continue;
						}
					}
					options.Add(val);
				}
			}
		}

		private static bool ShouldApply(RegisteredRule registration, AncientEventModel ancient)
		{
			Func<AncientEventModel, bool> condition = registration.Rule.Condition;
			if (condition == null)
			{
				return true;
			}
			try
			{
				return condition(ancient);
			}
			catch (Exception value)
			{
				RitsuLibFramework.CreateLogger(registration.OwnerModId, (LogType)0).Warn($"[AncientOption] Condition threw for ancient '{((AbstractModel)ancient).Id.Entry}': {value}", 1);
				return false;
			}
		}

		private static RegisteredRule[] GetApplicableRulesSnapshot(Type ancientType)
		{
			List<RegisteredRule> list = new List<RegisteredRule>();
			using (SyncRoot.EnterScope())
			{
				Type type = ancientType;
				while (type != null && typeof(AncientEventModel).IsAssignableFrom(type))
				{
					if (RulesByAncientType.TryGetValue(type, out List<RegisteredRule> value))
					{
						list.AddRange(value);
					}
					type = type.BaseType;
				}
			}
			return (from rule in list
				orderby rule.Rule.Priority descending, rule.RegistrationOrder
				select rule).ToArray();
		}
	}
	/// <summary>
	///     <para xml:lang="en">Describes additional choices for an Ancient's initial option list.</para>
	///     <para xml:lang="zh-CN">描述要添加到先古之民初始选项列表中的额外选项。</para>
	/// </summary>
	public sealed class ModAncientOptionRule
	{
		/// <summary>
		///     <para xml:lang="en">Produces options to append for a matching Ancient instance.</para>
		///     <para xml:lang="zh-CN">为匹配的先古之民实例生成要追加的选项。</para>
		/// </summary>
		public Func<AncientEventModel, IEnumerable<EventOption>> OptionFactory { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional condition evaluated before the option factory. A <see langword="null" /> condition
		///         always passes.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         调用选项工厂前评估的可选条件；为 <see langword="null" /> 时始终通过。
		///     </para>
		/// </summary>
		public Func<AncientEventModel, bool>? Condition { get; init; }

		/// <summary>
		///     <para xml:lang="en">Higher-priority rules run first; ties preserve registration order.</para>
		///     <para xml:lang="zh-CN">优先级较高的规则先运行；优先级相同时保留注册顺序。</para>
		/// </summary>
		public int Priority { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Whether to skip an option whose non-empty <see cref="P:MegaCrit.Sts2.Core.Events.EventOption.TextKey" /> has already appeared.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         是否跳过非空 <see cref="P:MegaCrit.Sts2.Core.Events.EventOption.TextKey" /> 已出现过的选项。
		///     </para>
		/// </summary>
		public bool SkipDuplicateTextKeys { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">Creates a rule with the specified option factory.</para>
		///     <para xml:lang="zh-CN">使用指定的选项工厂创建规则。</para>
		/// </summary>
		/// <param name="optionFactory">
		///     <para xml:lang="en">Produces zero or more options for the current Ancient instance.</para>
		///     <para xml:lang="zh-CN">为当前先古之民实例生成零个或多个选项。</para>
		/// </param>
		public ModAncientOptionRule(Func<AncientEventModel, IEnumerable<EventOption>> optionFactory)
		{
			ArgumentNullException.ThrowIfNull(optionFactory, "optionFactory");
			OptionFactory = optionFactory;
		}

		/// <summary>
		///     <para xml:lang="en">Creates a rule whose factory returns at most one option.</para>
		///     <para xml:lang="zh-CN">创建选项工厂至多返回一个选项的规则。</para>
		/// </summary>
		public static ModAncientOptionRule Single(Func<AncientEventModel, EventOption?> optionFactory, Func<AncientEventModel, bool>? condition = null, int priority = 0, bool skipDuplicateTextKeys = true)
		{
			ArgumentNullException.ThrowIfNull(optionFactory, "optionFactory");
			return new ModAncientOptionRule(delegate(AncientEventModel ancient)
			{
				EventOption val = optionFactory(ancient);
				return (val != null) ? ((IEnumerable<EventOption>)new <>z__ReadOnlySingleElementList<EventOption>(val)) : ((IEnumerable<EventOption>)Array.Empty<EventOption>());
			})
			{
				Condition = condition,
				Priority = priority,
				SkipDuplicateTextKeys = skipDuplicateTextKeys
			};
		}
	}
}
namespace STS2RitsuLib.Saves
{
	/// <summary>
	///     <para xml:lang="en">
	///         Preserves progress-save entries whose model IDs are unavailable with the current set of mods, allowing the
	///         entries to be written back without exposing them to runtime progress logic.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         保留模型 ID 在当前模组集合中不可用的进度存档条目，使其不会参与运行时进度逻辑，但仍可在保存时写回。
	///     </para>
	/// </summary>
	public sealed class PreservedProgressRecords
	{
		private static readonly ConditionalWeakTable<ProgressState, PreservedProgressRecords> RecordsByProgress = new ConditionalWeakTable<ProgressState, PreservedProgressRecords>();

		private static readonly HashSet<string> KnownAchievementNames = BuildKnownAchievementNames();

		private static readonly FieldInfo? ValidationErrorsField = typeof(DeserializationContext).GetField("_errors", BindingFlags.Instance | BindingFlags.NonPublic);

		private readonly List<AncientStats> _ancientStats = new List<AncientStats>();

		private readonly List<CardStats> _cardStats = new List<CardStats>();

		private readonly List<CharacterStats> _characterStats = new List<CharacterStats>();

		private readonly List<ModelId> _discoveredActs = new List<ModelId>();

		private readonly List<ModelId> _discoveredCards = new List<ModelId>();

		private readonly List<ModelId> _discoveredEvents = new List<ModelId>();

		private readonly List<ModelId> _discoveredPotions = new List<ModelId>();

		private readonly List<ModelId> _discoveredRelics = new List<ModelId>();

		private readonly List<EncounterStats> _encounterStats = new List<EncounterStats>();

		private readonly List<EnemyStats> _enemyStats = new List<EnemyStats>();

		private readonly List<SerializableEpoch> _epochs = new List<SerializableEpoch>();

		private readonly List<SerializableUnlockedAchievement> _unlockedAchievements = new List<SerializableUnlockedAchievement>();

		private ModelId? _pendingCharacterUnlock;

		private bool HasAny
		{
			get
			{
				if (_characterStats.Count <= 0 && _cardStats.Count <= 0 && _encounterStats.Count <= 0 && _enemyStats.Count <= 0 && _ancientStats.Count <= 0 && _discoveredCards.Count <= 0 && _discoveredRelics.Count <= 0 && _discoveredPotions.Count <= 0 && _discoveredEvents.Count <= 0 && _discoveredActs.Count <= 0 && _epochs.Count <= 0 && _unlockedAchievements.Count <= 0)
				{
					return IsSavableModelId(_pendingCharacterUnlock);
				}
				return true;
			}
		}

		internal static PreservedProgressRecords? Capture(SerializableProgress save)
		{
			ArgumentNullException.ThrowIfNull(save, "save");
			PreservedProgressRecords preservedProgressRecords = new PreservedProgressRecords();
			preservedProgressRecords.CaptureCharacterStats(save.CharStats);
			preservedProgressRecords.CaptureCardStats(save.CardStats);
			preservedProgressRecords.CaptureEncounterStats(save.EncounterStats);
			preservedProgressRecords.CaptureEnemyStats(save.EnemyStats);
			preservedProgressRecords.CaptureAncientStats(save.AncientStats);
			preservedProgressRecords.CaptureDiscoveredSet<CardModel>(save.DiscoveredCards, preservedProgressRecords._discoveredCards);
			preservedProgressRecords.CaptureDiscoveredSet<RelicModel>(save.DiscoveredRelics, preservedProgressRecords._discoveredRelics);
			preservedProgressRecords.CaptureDiscoveredSet<PotionModel>(save.DiscoveredPotions, preservedProgressRecords._discoveredPotions);
			preservedProgressRecords.CaptureDiscoveredSet<EventModel>(save.DiscoveredEvents, preservedProgressRecords._discoveredEvents);
			preservedProgressRecords.CaptureDiscoveredSet<ActModel>(save.DiscoveredActs, preservedProgressRecords._discoveredActs);
			preservedProgressRecords.CaptureEpochs(save.Epochs);
			preservedProgressRecords.CaptureAchievements(save.UnlockedAchievements);
			if (IsUnknownModel<CharacterModel>(save.PendingCharacterUnlock))
			{
				preservedProgressRecords._pendingCharacterUnlock = save.PendingCharacterUnlock;
			}
			if (!preservedProgressRecords.HasAny)
			{
				return null;
			}
			return preservedProgressRecords;
		}

		internal static void Attach(ProgressState? progress, PreservedProgressRecords? records)
		{
			if (progress != null && records != null && records.HasAny)
			{
				RecordsByProgress.Remove(progress);
				RecordsByProgress.Add(progress, records);
				RitsuLibFramework.Logger.Info("[Saves] Preserving unavailable progress records: " + records.FormatCounts(), 1);
			}
		}

		internal int SuppressExpectedWarnings(DeserializationContext ctx)
		{
			if (!(ValidationErrorsField?.GetValue(ctx) is List<ValidationError> list))
			{
				return 0;
			}
			HashSet<string> preservedIdentifiers = GetPreservedIdentifierStrings();
			HashSet<string> preservedAchievements = _unlockedAchievements.Select((SerializableUnlockedAchievement item) => item.Achievement).ToHashSet<string>(StringComparer.Ordinal);
			int num = list.RemoveAll((ValidationError error) => IsExpectedPreservedWarning(error, preservedIdentifiers, preservedAchievements));
			if (num > 0)
			{
				RitsuLibFramework.Logger.Info($"[Saves] Suppressed {num} expected progress validation warning(s) for unavailable preserved records", 1);
			}
			return num;
		}

		internal static void MergeInto(ProgressState? progress, SerializableProgress? save)
		{
			if (progress != null && save != null && RecordsByProgress.TryGetValue(progress, out PreservedProgressRecords value))
			{
				value.MergeInto(save);
			}
		}

		internal static bool MergeUnavailableRecords(SerializableProgress target, SerializableProgress source)
		{
			ArgumentNullException.ThrowIfNull(target, "target");
			ArgumentNullException.ThrowIfNull(source, "source");
			PreservedProgressRecords preservedProgressRecords = Capture(source);
			if (preservedProgressRecords == null)
			{
				return false;
			}
			preservedProgressRecords.MergeInto(target);
			return true;
		}

		private void CaptureCharacterStats(List<CharacterStats> source)
		{
			foreach (CharacterStats item in source.Where((CharacterStats stats) => IsUnknownModel<CharacterModel>(stats.Id)))
			{
				_characterStats.Add(Clone(item));
			}
		}

		private void CaptureCardStats(List<CardStats> source)
		{
			foreach (CardStats item in source.Where((CardStats stats) => IsUnknownModel<CardModel>(stats.Id)))
			{
				_cardStats.Add(Clone(item));
			}
		}

		private void CaptureEncounterStats(List<EncounterStats> source)
		{
			//IL_00a3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a8: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b4: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c0: Expected O, but got Unknown
			foreach (EncounterStats item in source)
			{
				if (!IsSavableModelId(item.Id))
				{
					continue;
				}
				if (IsUnknownModel<EncounterModel>(item.Id))
				{
					_encounterStats.Add(Clone(item));
					continue;
				}
				List<FightStats> list = item.FightStats.Where((FightStats fight) => IsUnknownModel<CharacterModel>(fight.Character)).Select(Clone).ToList();
				if (list.Count > 0)
				{
					List<EncounterStats> encounterStats = _encounterStats;
					EncounterStats val = new EncounterStats();
					val.set_Id(item.Id);
					val.set_FightStats(list);
					encounterStats.Add(val);
				}
			}
		}

		private void CaptureEnemyStats(List<EnemyStats> source)
		{
			//IL_00a3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a8: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b4: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c0: Expected O, but got Unknown
			foreach (EnemyStats item in source)
			{
				if (!IsSavableModelId(item.Id))
				{
					continue;
				}
				if (IsUnknownModel<MonsterModel>(item.Id))
				{
					_enemyStats.Add(Clone(item));
					continue;
				}
				List<FightStats> list = item.FightStats.Where((FightStats fight) => IsUnknownModel<CharacterModel>(fight.Character)).Select(Clone).ToList();
				if (list.Count > 0)
				{
					List<EnemyStats> enemyStats = _enemyStats;
					EnemyStats val = new EnemyStats();
					val.set_Id(item.Id);
					val.set_FightStats(list);
					enemyStats.Add(val);
				}
			}
		}

		private void CaptureAncientStats(List<AncientStats> source)
		{
			//IL_00a3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a8: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b4: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c0: Expected O, but got Unknown
			foreach (AncientStats item in source)
			{
				if (!IsSavableModelId(item.Id))
				{
					continue;
				}
				if (IsUnknownModel<EventModel>(item.Id))
				{
					_ancientStats.Add(Clone(item));
					continue;
				}
				List<AncientCharacterStats> list = item.CharStats.Where((AncientCharacterStats charStats) => IsUnknownModel<CharacterModel>(charStats.Character)).Select(Clone).ToList();
				if (list.Count > 0)
				{
					List<AncientStats> ancientStats = _ancientStats;
					AncientStats val = new AncientStats();
					val.set_Id(item.Id);
					val.set_CharStats(list);
					ancientStats.Add(val);
				}
			}
		}

		private void CaptureDiscoveredSet<TModel>(List<ModelId> source, List<ModelId> target) where TModel : AbstractModel
		{
			HashSet<ModelId> hashSet = target.ToHashSet();
			target.AddRange(source.Where(IsUnknownModel<TModel>).Where(hashSet.Add));
		}

		private void CaptureEpochs(List<SerializableEpoch> source)
		{
			//IL_0061: Unknown result type (might be due to invalid IL or missing references)
			//IL_006e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0074: Invalid comparison between Unknown and I4
			HashSet<string> hashSet = _epochs.Select((SerializableEpoch epoch) => epoch.Id).ToHashSet<string>(StringComparer.Ordinal);
			foreach (SerializableEpoch item in source)
			{
				if (!string.IsNullOrWhiteSpace(item.Id) && !EpochModel.IsValid(item.Id) && Enum.IsDefined<EpochState>(item.State) && (int)item.State >= 2 && hashSet.Add(item.Id))
				{
					_epochs.Add(Clone(item));
				}
			}
		}

		private void CaptureAchievements(List<SerializableUnlockedAchievement>? source)
		{
			if (source == null)
			{
				return;
			}
			HashSet<string> hashSet = _unlockedAchievements.Select((SerializableUnlockedAchievement achievement) => achievement.Achievement).ToHashSet<string>(StringComparer.Ordinal);
			foreach (SerializableUnlockedAchievement item in source)
			{
				if (!string.IsNullOrWhiteSpace(item.Achievement) && !KnownAchievementNames.Contains(item.Achievement) && hashSet.Add(item.Achievement))
				{
					_unlockedAchievements.Add(Clone(item));
				}
			}
		}

		private void MergeInto(SerializableProgress save)
		{
			AppendMissingById(save.CharStats, _characterStats, (CharacterStats stats) => stats.Id, Clone);
			AppendMissingById(save.CardStats, _cardStats, (CardStats stats) => stats.Id, Clone);
			MergeEncounterStats(save.EncounterStats);
			MergeEnemyStats(save.EnemyStats);
			MergeAncientStats(save.AncientStats);
			AppendMissingIds(save.DiscoveredCards, _discoveredCards);
			AppendMissingIds(save.DiscoveredRelics, _discoveredRelics);
			AppendMissingIds(save.DiscoveredPotions, _discoveredPotions);
			AppendMissingIds(save.DiscoveredEvents, _discoveredEvents);
			AppendMissingIds(save.DiscoveredActs, _discoveredActs);
			AppendMissingById(save.Epochs, _epochs, (SerializableEpoch epoch) => epoch.Id, Clone);
			AppendMissingById(save.UnlockedAchievements, _unlockedAchievements, (SerializableUnlockedAchievement achievement) => achievement.Achievement, Clone);
			ModelId pendingCharacterUnlock = _pendingCharacterUnlock;
			if (save.PendingCharacterUnlock == ModelId.none && pendingCharacterUnlock != (ModelId)null && pendingCharacterUnlock != ModelId.none)
			{
				save.PendingCharacterUnlock = pendingCharacterUnlock;
			}
		}

		private void MergeEncounterStats(List<EncounterStats> target)
		{
			foreach (EncounterStats preserved in _encounterStats)
			{
				EncounterStats val = target.FirstOrDefault((EncounterStats stats) => stats.Id == preserved.Id);
				if (val == null)
				{
					target.Add(Clone(preserved));
					continue;
				}
				AppendMissingById(val.FightStats, preserved.FightStats, (FightStats fight) => fight.Character, Clone);
			}
		}

		private void MergeEnemyStats(List<EnemyStats> target)
		{
			foreach (EnemyStats preserved in _enemyStats)
			{
				EnemyStats val = target.FirstOrDefault((EnemyStats stats) => stats.Id == preserved.Id);
				if (val == null)
				{
					target.Add(Clone(preserved));
					continue;
				}
				AppendMissingById(val.FightStats, preserved.FightStats, (FightStats fight) => fight.Character, Clone);
			}
		}

		private void MergeAncientStats(List<AncientStats> target)
		{
			foreach (AncientStats preserved in _ancientStats)
			{
				AncientStats val = target.FirstOrDefault((AncientStats stats) => stats.Id == preserved.Id);
				if (val == null)
				{
					target.Add(Clone(preserved));
					continue;
				}
				AppendMissingById(val.CharStats, preserved.CharStats, (AncientCharacterStats stats) => stats.Character, Clone);
			}
		}

		private string FormatCounts()
		{
			return string.Join(", ", new string[9]
			{
				FormatCount("characters", _characterStats.Count),
				FormatCount("cards", _cardStats.Count),
				FormatCount("encounters", _encounterStats.Count),
				FormatCount("enemies", _enemyStats.Count),
				FormatCount("ancients", _ancientStats.Count),
				FormatCount("discoveries", _discoveredCards.Count + _discoveredRelics.Count + _discoveredPotions.Count + _discoveredEvents.Count + _discoveredActs.Count),
				FormatCount("epochs", _epochs.Count),
				FormatCount("achievements", _unlockedAchievements.Count),
				FormatCount("pendingUnlock", IsSavableModelId(_pendingCharacterUnlock) ? 1 : 0)
			}.Where((string part) => part.Length > 0));
		}

		private static string FormatCount(string label, int count)
		{
			if (count <= 0)
			{
				return "";
			}
			return $"{label}={count}";
		}

		private static bool IsExpectedPreservedWarning(ValidationError error, HashSet<string> preservedIdentifiers, HashSet<string> preservedAchievements)
		{
			if (error.IsFatal || !error.Message.StartsWith("Unknown ", StringComparison.Ordinal))
			{
				return false;
			}
			int length;
			if (error.Message.StartsWith("Unknown achievement \"", StringComparison.Ordinal))
			{
				int num = error.Message.LastIndexOf("\" at index ", StringComparison.Ordinal);
				if (num > "Unknown achievement \"".Length)
				{
					string message = error.Message;
					length = "Unknown achievement \"".Length;
					return preservedAchievements.Contains(message.Substring(length, num - length));
				}
				return false;
			}
			int num2 = error.Message.IndexOf(": ", StringComparison.Ordinal);
			if (num2 < 0)
			{
				return false;
			}
			num2 += 2;
			int num3 = error.Message.Length;
			if (error.Message.EndsWith(", removing", StringComparison.Ordinal))
			{
				num3 -= ", removing".Length;
			}
			else if (error.Message.EndsWith(", resetting to none", StringComparison.Ordinal))
			{
				num3 -= ", resetting to none".Length;
			}
			string message2 = error.Message;
			length = num2;
			return preservedIdentifiers.Contains(message2.Substring(length, num3 - length));
		}

		private HashSet<string> GetPreservedIdentifierStrings()
		{
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			AddIds(hashSet, _characterStats.Select((CharacterStats stats) => stats.Id));
			AddIds(hashSet, _cardStats.Select((CardStats stats) => stats.Id));
			AddIds(hashSet, _encounterStats.Select((EncounterStats stats) => stats.Id));
			AddIds(hashSet, _enemyStats.Select((EnemyStats stats) => stats.Id));
			AddIds(hashSet, _ancientStats.Select((AncientStats stats) => stats.Id));
			AddIds(hashSet, _encounterStats.SelectMany((EncounterStats stats) => stats.FightStats.Select((FightStats fight) => fight.Character)));
			AddIds(hashSet, _enemyStats.SelectMany((EnemyStats stats) => stats.FightStats.Select((FightStats fight) => fight.Character)));
			AddIds(hashSet, _ancientStats.SelectMany((AncientStats stats) => stats.CharStats.Select((AncientCharacterStats charStats) => charStats.Character)));
			AddIds(hashSet, _discoveredCards);
			AddIds(hashSet, _discoveredRelics);
			AddIds(hashSet, _discoveredPotions);
			AddIds(hashSet, _discoveredEvents);
			AddIds(hashSet, _discoveredActs);
			foreach (SerializableEpoch epoch in _epochs)
			{
				hashSet.Add(epoch.Id);
			}
			ModelId pendingCharacterUnlock = _pendingCharacterUnlock;
			if (pendingCharacterUnlock != null && pendingCharacterUnlock != ModelId.none)
			{
				hashSet.Add(((object)pendingCharacterUnlock).ToString());
			}
			return hashSet;
		}

		private static void AddIds(HashSet<string> target, IEnumerable<ModelId?> source)
		{
			foreach (ModelId item in source)
			{
				if (item != (ModelId)null && item != ModelId.none)
				{
					target.Add(((object)item).ToString());
				}
			}
		}

		private static bool IsUnknownModel<TModel>(ModelId? id) where TModel : AbstractModel
		{
			if (id == (ModelId)null || id == ModelId.none)
			{
				return false;
			}
			return ModelDb.GetByIdOrNull<TModel>(id) == null;
		}

		private static bool IsSavableModelId(ModelId? id)
		{
			if (id != (ModelId)null)
			{
				return id != ModelId.none;
			}
			return false;
		}

		private static void AppendMissingIds(List<ModelId> target, IEnumerable<ModelId> source)
		{
			HashSet<ModelId> hashSet = target.ToHashSet();
			foreach (ModelId item in source)
			{
				if (hashSet.Add(item))
				{
					target.Add(item);
				}
			}
		}

		private static void AppendMissingById<T, TKey>(List<T> target, IEnumerable<T> source, Func<T, TKey?> keySelector, Func<T, T> clone)
		{
			HashSet<TKey> hashSet = (from key in target.Select(keySelector)
				where key != null
				select key).ToHashSet();
			foreach (T item in source)
			{
				TKey val = keySelector(item);
				if (val != null && hashSet.Add(val))
				{
					target.Add(clone(item));
				}
			}
		}

		private static CharacterStats Clone(CharacterStats stats)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			//IL_0035: Unknown result type (might be due to invalid IL or missing references)
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			//IL_004d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0059: Unknown result type (might be due to invalid IL or missing references)
			//IL_0065: Unknown result type (might be due to invalid IL or missing references)
			//IL_0071: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a3: Expected O, but got Unknown
			CharacterStats val = new CharacterStats();
			val.set_Id(stats.Id);
			val.MaxAscension = stats.MaxAscension;
			val.PreferredAscension = stats.PreferredAscension;
			val.TotalWins = stats.TotalWins;
			val.TotalLosses = stats.TotalLosses;
			val.FastestWinTime = stats.FastestWinTime;
			val.BestWinStreak = stats.BestWinStreak;
			val.CurrentWinStreak = stats.CurrentWinStreak;
			val.Playtime = stats.Playtime;
			val.Badges = stats.Badges.Select(Clone).ToList();
			return val;
