	internal static class ProgressMirrorStore
	{
		private const string FileName = "progress_records_mirror.save";

		private const string LogContext = "ProgressMirror";

		private static bool _isRefreshingFromProgress;

		private static bool _isSavingMirror;

		internal static void MergeMirrorInto(SerializableProgress save)
		{
			ArgumentNullException.ThrowIfNull(save, "save");
			SerializableProgress val = LoadMirror();
			if (val != null)
			{
				if (!IsSameProgress(save, val))
				{
					RitsuLibFramework.Logger.Info("[Saves] Progress mirror ignored because unique_id differs: save=" + save.UniqueId + ", mirror=" + val.UniqueId, 1);
				}
				else if (PreservedProgressRecords.MergeUnavailableRecords(save, val))
				{
					RitsuLibFramework.Logger.Info("[Saves] Unavailable progress records restored from progress mirror", 1);
				}
			}
		}

		internal static void RefreshFromProgress(ProgressState progress)
		{
			if (_isRefreshingFromProgress)
			{
				return;
			}
			try
			{
				_isRefreshingFromProgress = true;
				progress.ToSerializable();
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[Saves] Failed to refresh progress mirror from progress: " + ex.Message, 1);
			}
			finally
			{
				_isRefreshingFromProgress = false;
			}
		}

		internal static void SaveMirror(SerializableProgress save, string? serializedJson = null)
		{
			if (_isSavingMirror || string.IsNullOrWhiteSpace(save.UniqueId))
			{
				return;
			}
			try
			{
				_isSavingMirror = true;
				string content = serializedJson ?? JsonSerializationUtility.ToJson<SerializableProgress>(save);
				FileOperations.WriteResult writeResult = FileOperations.WriteText(GetMirrorPath(), content, "ProgressMirror");
				if (!writeResult.Success)
				{
					RitsuLibFramework.Logger.Warn("[Saves] Failed to write progress mirror: " + (writeResult.ErrorMessage ?? "unknown error"), 1);
				}
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[Saves] Failed to write progress mirror: " + ex.Message, 1);
			}
			finally
			{
				_isSavingMirror = false;
			}
		}

		private static SerializableProgress? LoadMirror()
		{
			//IL_0062: Unknown result type (might be due to invalid IL or missing references)
			//IL_0067: Unknown result type (might be due to invalid IL or missing references)
			FileOperations.ReadResult readResult = FileOperations.ReadTextWithBackupFallback(GetMirrorPath(), "ProgressMirror");
			if (!readResult.Success || string.IsNullOrWhiteSpace(readResult.Content))
			{
				return null;
			}
			ReadSaveResult<SerializableProgress> val = JsonSerializationUtility.FromJson<SerializableProgress>(readResult.Content);
			if (val != null && val.Success && val.SaveData != null)
			{
				return val.SaveData;
			}
			RitsuLibFramework.Logger.Warn("[Saves] Failed to parse progress mirror: " + (val.ErrorMessage ?? ((object)val.Status/*cast due to constrained. prefix*/).ToString()), 1);
			return null;
		}

		private static bool IsSameProgress(SerializableProgress save, SerializableProgress mirror)
		{
			if (!string.IsNullOrWhiteSpace(save.UniqueId))
			{
				return string.Equals(save.UniqueId, mirror.UniqueId, StringComparison.Ordinal);
			}
			return false;
		}

		private static string GetMirrorPath()
		{
			return ProfileManager.GetFilePath("progress_records_mirror.save", SaveScope.Profile, GetCurrentProfileId(), "com.ritsukage.sts2-RitsuLib");
		}

		private static int GetCurrentProfileId()
		{
			try
			{
				return SaveManager.Instance.CurrentProfileId;
			}
			catch
			{
				int currentProfileId = ProfileManager.Instance.CurrentProfileId;
				return (currentProfileId <= 0) ? 1 : currentProfileId;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Resolves acts and characters referenced by run history, using the base game's deprecated-model placeholders
	///         when the owning mod is unavailable.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         解析游戏历史引用的章节与角色；当所属模组不可用时，改用原版游戏的已弃用模型占位项。
	///     </para>
	/// </summary>
	internal static class RunHistoryMissingModelSupport
	{
		internal static CharacterModel CharacterForRunHistory(ModelId id)
		{
			CharacterModel byIdOrNull = ModelDb.GetByIdOrNull<CharacterModel>(id);
			if (byIdOrNull != null)
			{
				return byIdOrNull;
			}
			RitsuLibFramework.Logger.Warn("[Saves] Run history references character not in ModelDb (mod likely unloaded): " + ((object)id)?.ToString() + ". Using DeprecatedCharacter for preview UI.", 1);
			return SaveUtil.CharacterOrDeprecated(id);
		}

		internal static ActModel ActForRunHistory(ModelId id)
		{
			ActModel byIdOrNull = ModelDb.GetByIdOrNull<ActModel>(id);
			if (byIdOrNull != null)
			{
				return byIdOrNull;
			}
			RitsuLibFramework.Logger.Warn("[Saves] Run history references act not in ModelDb (mod likely unloaded): " + ((object)id)?.ToString() + ". Using DeprecatedAct for section header.", 1);
			return SaveUtil.ActOrDeprecated(id);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Detects missing <see cref="T:MegaCrit.Sts2.Core.Models.CharacterModel" /> instances when resuming a run and presents the base game's
	///         invalid-save dialog without deleting the run save.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         恢复跑局时检测缺失的 <see cref="T:MegaCrit.Sts2.Core.Models.CharacterModel" />，并显示原版游戏的无效存档对话框，而不删除局内存档。
	///     </para>
	/// </summary>
	internal static class RunResumeMissingCharacterSupport
	{
		internal static bool AnyPlayerMissingRegisteredCharacter(SerializableRun run)
		{
			return run.Players.Select((SerializablePlayer p) => p.CharacterId).Any((ModelId cid) => cid == (ModelId)null || ModelDb.GetByIdOrNull<CharacterModel>(cid) == null);
		}

		internal static void TryShowInvalidRunSaveModal()
		{
			//IL_000a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0019: Unknown result type (might be due to invalid IL or missing references)
			//IL_0028: Unknown result type (might be due to invalid IL or missing references)
			//IL_0033: Expected O, but got Unknown
			//IL_0033: Expected O, but got Unknown
			//IL_0033: Expected O, but got Unknown
			try
			{
				NErrorPopup val = NErrorPopup.Create(new LocString("main_menu_ui", "INVALID_SAVE_POPUP.title"), new LocString("main_menu_ui", "INVALID_SAVE_POPUP.description_run"), new LocString("main_menu_ui", "INVALID_SAVE_POPUP.dismiss"), true);
				if (val != null && NModalContainer.Instance != null)
				{
					NModalContainer.Instance.Add((Node)(object)val, true);
					NModalContainer.Instance.ShowBackstop();
				}
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.ErrorNoTrace("[Saves] Failed to show invalid-run modal: " + ex.Message);
			}
		}
	}
