				OwnerId = original.OwnerId;
				SchemaVersion = original.SchemaVersion;
				TransactionId = original.TransactionId;
				ProfileId = original.ProfileId;
				IsModded = original.IsModded;
				ProgressUniqueId = original.ProgressUniqueId;
				Stage = original.Stage;
				OriginalRawJson = original.OriginalRawJson;
				OriginalSha256 = original.OriginalSha256;
				ProposedSha256 = original.ProposedSha256;
				LocalReadBackSha256 = original.LocalReadBackSha256;
				CloudReadBackSha256 = original.CloudReadBackSha256;
				LiveKnownProjectionSha256 = original.LiveKnownProjectionSha256;
			}
		}

		private sealed class RecoveryJournal
		{
			private string BasePath { get; }

			private string WritePath { get; }

			private bool CanUpdate { get; }

			internal RecoveryJournalData Data { get; private set; }

			internal string RecoveryToken => ComputeSha256(JsonSerializer.Serialize(Data, JournalJsonOptions));

			internal bool Exists
			{
				get
				{
					if (!FileOperations.FileExists(BasePath) && !FileOperations.FileExists(BasePath + ".backup"))
					{
						return FileOperations.FileExists(BasePath + ".backup.backup");
					}
					return true;
				}
			}

			private RecoveryJournal(string basePath, string writePath, RecoveryJournalData data, bool canUpdate = true)
			{
				BasePath = basePath;
				WritePath = writePath;
				Data = data;
				CanUpdate = canUpdate;
			}

			internal static RecoveryJournal Create(RawProgressCommitRequest request, string originalRawJson)
			{
				string recoveryPath = GetRecoveryPath(request.OwnerId, request.TransactionId);
				return new RecoveryJournal(recoveryPath, recoveryPath, new RecoveryJournalData
				{
					JournalProtocolVersion = 1,
					OwnerId = request.OwnerId,
					SchemaVersion = request.SchemaVersion,
					TransactionId = request.TransactionId,
					ProfileId = request.ExpectedGeneration.ProfileId,
					IsModded = request.ExpectedGeneration.IsModded,
					ProgressUniqueId = request.ExpectedGeneration.ProgressUniqueId,
					Stage = "prepared",
					OriginalRawJson = originalRawJson,
					OriginalSha256 = ComputeSha256(originalRawJson),
					ProposedSha256 = request.ProposedSha256
				});
			}

			internal static RawProgressRecoveryReadResult ReadAll(string ownerId)
			{
				string ownerStorageId = ComputeOwnerStorageId(ownerId);
				if (!TryEnumerateJournalKeys(out HashSet<RecoveryJournalKey> journalKeys, out HashSet<string> invalidFiles))
				{
					return new RawProgressRecoveryReadResult
					{
						OwnerId = ownerId,
						Outcome = RawProgressRecoveryReadOutcome.StorageUnavailable,
						Records = Array.Empty<RawProgressRecoveryRecord>(),
						InvalidEntryCount = CountInvalidOwnerFiles(invalidFiles, ownerStorageId)
					};
				}
				RecoveryJournalKey[] array = journalKeys.Where((RecoveryJournalKey key) => string.Equals(key.OwnerStorageId, ownerStorageId, StringComparison.OrdinalIgnoreCase)).ToArray();
				int num = CountInvalidOwnerFiles(invalidFiles, ownerStorageId);
				List<RawProgressRecoveryRecord> list = new List<RawProgressRecoveryRecord>(array.Length);
				RecoveryJournalKey[] array2 = array;
				for (int num2 = 0; num2 < array2.Length; num2++)
				{
					if (TryLoadKey(array2[num2], ownerId, out RecoveryJournal journal) != RecoveryJournalLoadOutcome.Succeeded || journal == null)
					{
						num++;
					}
					else
					{
						list.Add(journal.ToRecord());
					}
				}
				list.Sort((RawProgressRecoveryRecord left, RawProgressRecoveryRecord right) => left.TransactionId.CompareTo(right.TransactionId));
				return new RawProgressRecoveryReadResult
				{
					OwnerId = ownerId,
					Outcome = ((num != 0) ? RawProgressRecoveryReadOutcome.InvalidEntriesIgnored : RawProgressRecoveryReadOutcome.Succeeded),
					Records = list.AsReadOnly(),
					InvalidEntryCount = num
				};
			}

			internal static RecoveryJournalLoadOutcome TryLoad(string ownerId, Guid transactionId, out RecoveryJournal? journal)
			{
				if (!IsValidOwnerId(ownerId) || transactionId == Guid.Empty)
				{
					journal = null;
					return RecoveryJournalLoadOutcome.Invalid;
				}
				return TryLoadKey(new RecoveryJournalKey(ComputeOwnerStorageId(ownerId), transactionId), ownerId, out journal);
			}

			private static RecoveryJournalLoadOutcome TryLoadKey(RecoveryJournalKey key, string? expectedOwnerId, out RecoveryJournal? journal)
			{
				journal = null;
				string recoveryPath = GetRecoveryPath(key);
				bool flag = FileOperations.FileExists(recoveryPath);
				string text = recoveryPath + ".backup";
				bool flag2 = FileOperations.FileExists(text);
				string text2 = text + ".backup";
				bool flag3 = FileOperations.FileExists(text2);
				if (!flag && !flag2 && !flag3)
				{
					return RecoveryJournalLoadOutcome.NotFound;
				}
				if (flag && TryReadData(recoveryPath, key, expectedOwnerId, out RecoveryJournalData data))
				{
					journal = new RecoveryJournal(recoveryPath, recoveryPath, data);
					return RecoveryJournalLoadOutcome.Succeeded;
				}
				if (flag2 && TryReadData(text, key, expectedOwnerId, out RecoveryJournalData data2))
				{
					journal = new RecoveryJournal(recoveryPath, text, data2);
					return RecoveryJournalLoadOutcome.Succeeded;
				}
				if (flag3 && TryReadData(text2, key, expectedOwnerId, out RecoveryJournalData data3))
				{
					journal = new RecoveryJournal(recoveryPath, text2, data3, canUpdate: false);
					return RecoveryJournalLoadOutcome.Succeeded;
				}
				return RecoveryJournalLoadOutcome.Invalid;
			}

			internal bool TryPrepare()
			{
				if (!TryMaintainAndCountRetainedJournals(out var retainedJournalCount) || Exists || retainedJournalCount >= 8)
				{
					return false;
				}
				return TryWrite();
			}

			internal void TryUpdate(string stage, string? localReadBackSha256, string? cloudReadBackSha256, string? liveKnownProjectionSha256)
			{
				if (CanUpdate)
				{
					Data = Data with
					{
						Stage = stage,
						LocalReadBackSha256 = localReadBackSha256,
						CloudReadBackSha256 = cloudReadBackSha256,
						LiveKnownProjectionSha256 = liveKnownProjectionSha256
					};
					TryWrite();
				}
			}

			internal bool TryDelete()
			{
				string[] obj = new string[7]
				{
					BasePath,
					BasePath + ".backup",
					BasePath + ".tmp",
					BasePath + ".backup.backup",
					BasePath + ".backup.tmp",
					BasePath + ".backup.backup.backup",
					BasePath + ".backup.backup.tmp"
				};
				bool flag = true;
				string[] array = obj;
				foreach (string filePath in array)
				{
					flag &= FileOperations.DeleteFile(filePath, "RawProgressRecovery").Success;
				}
				if (flag)
				{
					return !Exists;
				}
				return false;
			}

			private bool TryWrite()
			{
				try
				{
					string content = JsonSerializer.Serialize(Data, JournalJsonOptions);
					return FileOperations.WriteText(WritePath, content, "RawProgressRecovery").Success;
				}
				catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
				{
					RitsuLibFramework.Logger.ErrorNoTrace("[RawProgress] Failed to serialize recovery metadata: " + ex.Message);
					return false;
				}
			}

			private RawProgressRecoveryRecord ToRecord()
			{
				TryParseStage(Data.Stage, out var stage);
				return new RawProgressRecoveryRecord
				{
					OwnerId = Data.OwnerId,
					SchemaVersion = Data.SchemaVersion,
					TransactionId = Data.TransactionId,
					ProfileId = Data.ProfileId,
					IsModded = Data.IsModded,
					ProgressUniqueId = Data.ProgressUniqueId,
					Stage = stage,
					OriginalSha256 = Data.OriginalSha256,
					ProposedSha256 = Data.ProposedSha256,
					RecoveryToken = RecoveryToken
				};
			}

			private static bool TryMaintainAndCountRetainedJournals(out int retainedJournalCount)
			{
				retainedJournalCount = 0;
				if (!TryEnumerateJournalKeys(out HashSet<RecoveryJournalKey> journalKeys, out HashSet<string> invalidFiles))
				{
					return false;
				}
				string recoveryDirectory = GetRecoveryDirectory();
				foreach (string item in invalidFiles)
				{
					TryQuarantineFile(recoveryDirectory + "/" + item);
				}
				foreach (RecoveryJournalKey item2 in journalKeys)
				{
					RecoveryJournal journal;
					switch (TryLoadKey(item2, null, out journal))
					{
					case RecoveryJournalLoadOutcome.Succeeded:
						retainedJournalCount++;
						break;
					case RecoveryJournalLoadOutcome.Invalid:
						TryQuarantineJournal(item2);
						break;
					}
				}
				return true;
			}

			private static void TryQuarantineJournal(RecoveryJournalKey key)
			{
				string recoveryPath = GetRecoveryPath(key);
				string[] array = new string[7]
				{
					recoveryPath,
					recoveryPath + ".backup",
					recoveryPath + ".tmp",
					recoveryPath + ".backup.backup",
					recoveryPath + ".backup.tmp",
					recoveryPath + ".backup.backup.backup",
					recoveryPath + ".backup.backup.tmp"
				};
				for (int i = 0; i < array.Length; i++)
				{
					TryQuarantineFile(array[i]);
				}
			}

			private static bool TryQuarantineFile(string sourcePath)
			{
				//IL_010d: Unknown result type (might be due to invalid IL or missing references)
				//IL_0112: Unknown result type (might be due to invalid IL or missing references)
				//IL_0114: Unknown result type (might be due to invalid IL or missing references)
				//IL_005b: Unknown result type (might be due to invalid IL or missing references)
				//IL_0060: Unknown result type (might be due to invalid IL or missing references)
				//IL_0062: Unknown result type (might be due to invalid IL or missing references)
				//IL_0155: Unknown result type (might be due to invalid IL or missing references)
				//IL_0083: Unknown result type (might be due to invalid IL or missing references)
				if (!FileOperations.FileExists(sourcePath))
				{
					return true;
				}
				if (!TryGetFileLength(sourcePath, out var length) || !TryGetQuarantineUsage(out var fileCount, out var totalBytes) || fileCount >= 64 || length > 67108864 - totalBytes)
				{
					RitsuLibFramework.Logger.Warn("[RawProgress] Could not quarantine invalid recovery data at '" + sourcePath + "' within limits.", 1);
					return false;
				}
				string recoveryQuarantineDirectory = GetRecoveryQuarantineDirectory();
				if (!DirAccess.DirExistsAbsolute(recoveryQuarantineDirectory))
				{
					Error val = DirAccess.MakeDirRecursiveAbsolute(recoveryQuarantineDirectory);
					if ((int)val != 0)
					{
						RitsuLibFramework.Logger.Warn($"[RawProgress] Could not create the recovery quarantine (Error: {val}).", 1);
						return false;
					}
				}
				string text = $"{recoveryQuarantineDirectory}/{DateTime.UtcNow.Ticks}-{Guid.NewGuid():N}.invalid";
				Error val2 = DirAccess.RenameAbsolute(sourcePath, text);
				if ((int)val2 != 0)
				{
					RitsuLibFramework.Logger.Warn($"[RawProgress] Could not quarantine invalid recovery data at '{sourcePath}' (Error: {val2}).", 1);
					return false;
				}
				RitsuLibFramework.Logger.Warn("[RawProgress] Quarantined invalid recovery data from '" + sourcePath + "'.", 1);
				return true;
			}

			private static bool TryGetQuarantineUsage(out int fileCount, out long totalBytes)
			{
				fileCount = 0;
				totalBytes = 0L;
				string recoveryQuarantineDirectory = GetRecoveryQuarantineDirectory();
				if (!DirAccess.DirExistsAbsolute(recoveryQuarantineDirectory))
				{
					return true;
				}
				try
				{
					DirAccess val = DirAccess.Open(recoveryQuarantineDirectory);
					try
					{
						if (val == null)
						{
							return false;
						}
						string[] files = val.GetFiles();
						foreach (string text in files)
						{
							fileCount++;
							if (fileCount > 64 || !TryGetFileLength(recoveryQuarantineDirectory + "/" + text, out var length) || length > 67108864 - totalBytes)
							{
								return false;
							}
							totalBytes += length;
						}
						return true;
					}
					finally
					{
						((IDisposable)val)?.Dispose();
					}
				}
				catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
				{
					RitsuLibFramework.Logger.Warn("[RawProgress] Could not inspect the recovery quarantine: " + ex.Message, 1);
					return false;
				}
			}

			private static bool TryGetFileLength(string path, out long length)
			{
				length = 0L;
				try
				{
					FileAccess val = FileAccess.Open(path, (ModeFlags)1);
					try
					{
						if (val == null)
						{
							return false;
						}
						ulong length2 = val.GetLength();
						if (length2 > long.MaxValue)
						{
							return false;
						}
						length = (long)length2;
						return true;
					}
					finally
					{
						((IDisposable)val)?.Dispose();
					}
				}
				catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
				{
					RitsuLibFramework.Logger.Warn("[RawProgress] Could not inspect recovery data at '" + path + "': " + ex.Message, 1);
					return false;
				}
			}

			private static int CountInvalidOwnerFiles(IEnumerable<string> invalidFiles, string ownerStorageId)
			{
				string ownerPrefix = ownerStorageId + "-";
				return invalidFiles.Count((string file) => TryStripRecoverySuffix(file, out string stem) && stem.StartsWith(ownerPrefix, StringComparison.OrdinalIgnoreCase));
			}

			private static bool TryReadData(string path, RecoveryJournalKey key, string? expectedOwnerId, out RecoveryJournalData data)
			{
				data = null;
				FileOperations.ReadResult readResult = FileOperations.ReadText(path, "RawProgressRecovery");
				if (!readResult.Success || readResult.Content == null)
				{
					return false;
				}
				try
				{
					RecoveryJournalData recoveryJournalData = JsonSerializer.Deserialize<RecoveryJournalData>(readResult.Content, JournalJsonOptions);
					if (!IsValid(recoveryJournalData, key, expectedOwnerId))
					{
						return false;
					}
					data = recoveryJournalData;
					return true;
				}
				catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
				{
					RitsuLibFramework.Logger.Warn("[RawProgress] Failed to read recovery metadata at '" + path + "': " + ex.Message, 1);
					return false;
				}
			}

			private static bool IsValid(RecoveryJournalData? data, RecoveryJournalKey key, string? expectedOwnerId)
			{
				bool flag = (object)data == null || data.JournalProtocolVersion != 1 || !IsValidOwnerId(data.OwnerId) || !string.Equals(ComputeOwnerStorageId(data.OwnerId), key.OwnerStorageId, StringComparison.OrdinalIgnoreCase) || (expectedOwnerId != null && !string.Equals(data.OwnerId, expectedOwnerId, StringComparison.Ordinal)) || data.SchemaVersion < 1 || data.TransactionId != key.TransactionId;
				if (!flag)
				{
					int profileId = data.ProfileId;
					bool flag2 = ((profileId < 1 || profileId > 3) ? true : false);
					flag = flag2;
				}
				if (flag || string.IsNullOrWhiteSpace(data.ProgressUniqueId) || data.ProgressUniqueId.Length > 256 || !TryParseStage(data.Stage, out var _) || string.IsNullOrWhiteSpace(data.OriginalRawJson) || (long)data.OriginalRawJson.Length > 16777216L || !IsSha256(data.OriginalSha256) || !IsSha256(data.ProposedSha256) || (data.LocalReadBackSha256 != null && !IsSha256(data.LocalReadBackSha256)) || (data.CloudReadBackSha256 != null && !IsSha256(data.CloudReadBackSha256)) || (data.LiveKnownProjectionSha256 != null && !IsSha256(data.LiveKnownProjectionSha256)) || !TryInspectExistingDocument(data.OriginalRawJson, out int schema, out string uniqueId, out byte[] utf8Bytes) || schema != data.SchemaVersion || utf8Bytes.LongLength > 16777216 || !HashEquals(ComputeSha256(utf8Bytes), data.OriginalSha256) || !string.Equals(uniqueId, data.ProgressUniqueId, StringComparison.Ordinal))
				{
					return false;
				}
				return true;
			}

			private static bool TryParseStage(string? value, out RawProgressRecoveryStage stage)
			{
				stage = value switch
				{
					"prepared" => RawProgressRecoveryStage.Prepared, 
					"local_unverified" => RawProgressRecoveryStage.LocalUnverified, 
					"local_verified" => RawProgressRecoveryStage.LocalVerified, 
					"verification_incomplete" => RawProgressRecoveryStage.VerificationIncomplete, 
					_ => RawProgressRecoveryStage.Prepared, 
				};
				switch (value)
				{
				case "prepared":
				case "local_unverified":
				case "local_verified":
				case "verification_incomplete":
					return true;
				default:
					return false;
				}
			}

			private static bool TryStripRecoverySuffix(string fileName, out string stem)
			{
				string[] array = new string[7] { ".json.backup.backup.backup", ".json.backup.backup.tmp", ".json.backup.backup", ".json.backup.tmp", ".json.backup", ".json.tmp", ".json" };
				foreach (string text in array)
				{
					if (fileName.EndsWith(text, StringComparison.OrdinalIgnoreCase))
					{
						int length = text.Length;
						stem = fileName.Substring(0, fileName.Length - length);
						return true;
					}
				}
				stem = string.Empty;
				return false;
			}

			private static bool TryParseJournalKey(string stem, out RecoveryJournalKey key)
			{
				key = default(RecoveryJournalKey);
				if (stem.Length != 97 || stem[64] != '-')
				{
					return false;
				}
				string text = stem.Substring(0, 64);
				if (!IsSha256(text) || !Guid.TryParseExact(stem.Substring(65), "N", out var result))
				{
					return false;
				}
				key = new RecoveryJournalKey(text.ToLowerInvariant(), result);
				return true;
			}

			private static bool TryEnumerateJournalKeys(out HashSet<RecoveryJournalKey> journalKeys, out HashSet<string> invalidFiles)
			{
				journalKeys = new HashSet<RecoveryJournalKey>();
				invalidFiles = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
				string recoveryDirectory = GetRecoveryDirectory();
				try
				{
					if (!DirAccess.DirExistsAbsolute(recoveryDirectory))
					{
						return true;
					}
					DirAccess val = DirAccess.Open(recoveryDirectory);
					try
					{
						if (val == null)
						{
							return false;
						}
						int num = 0;
						string[] files = val.GetFiles();
						foreach (string text in files)
						{
							num++;
							if (num > 128)
							{
								return false;
							}
							RecoveryJournalKey key;
							if (!TryStripRecoverySuffix(text, out string stem))
							{
								invalidFiles.Add(text);
							}
							else if (TryParseJournalKey(stem, out key))
							{
								journalKeys.Add(key);
							}
							else
							{
								invalidFiles.Add(text);
							}
						}
						return true;
					}
					finally
					{
						((IDisposable)val)?.Dispose();
					}
				}
				catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
				{
					RitsuLibFramework.Logger.Warn("[RawProgress] Failed to enumerate retained recovery journals: " + ex.Message, 1);
					return false;
				}
			}
		}

		internal const int ProtocolVersion = 1;

		internal const long MaxDocumentUtf8Bytes = 16777216L;

		internal const int MaxRecoveryOwnerIdUtf8Bytes = 256;

		private const int MaxRetainedRecoveryJournals = 8;

		private const int MaxRecoveryDirectoryFiles = 128;

		private const int MaxQuarantinedRecoveryFiles = 64;

		private const long MaxQuarantinedRecoveryBytes = 67108864L;

		private const string RecoveryLogContext = "RawProgressRecovery";

		private const string RecoveryDirectoryName = "recovery/raw-progress";

		private const string RecoveryQuarantineDirectoryName = "recovery/raw-progress-quarantine";

		private static readonly object SaveWindow = new object();

		private static readonly UTF8Encoding StrictUtf8 = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false, throwOnInvalidBytes: true);

		private static readonly Dictionary<RecoveryTransactionKey, CompletedTransaction> CompletedTransactions = new Dictionary<RecoveryTransactionKey, CompletedTransaction>();

		private static readonly Queue<RecoveryTransactionKey> CompletedTransactionOrder = new Queue<RecoveryTransactionKey>();

		private static int _observedRuntimeSchema;

		private static readonly JsonSerializerOptions JournalJsonOptions = new JsonSerializerOptions
		{
			WriteIndented = true,
			MaxDepth = 32,
			UnmappedMemberHandling = JsonUnmappedMemberHandling.Disallow
		};

		private readonly RawProgressBridgeFeature _features;

		[field: ThreadStatic]
		internal static bool IsPreparingCommitProjection { get; private set; }

		[field: ThreadStatic]
		internal static bool IsSavingOrdinaryProgress { get; private set; }

		internal static RawProgressCommitBridge Instance { get; } = new RawProgressCommitBridge();

		private RawProgressCommitBridge()
		{
			_features = RawProgressBridgeFeature.UnknownJsonPassThrough | RawProgressBridgeFeature.LiveGameStoreCommit | RawProgressBridgeFeature.DurableLocalReplacement | RawProgressBridgeFeature.CloudSaveBatch | RawProgressBridgeFeature.ConditionalGenerationCheck | RawProgressBridgeFeature.ExclusiveSaveWindow | RawProgressBridgeFeature.LocalOnlyRecoveryJournal | RawProgressBridgeFeature.StructuredRecoveryOutcome | RawProgressBridgeFeature.StablePublicContract | RawProgressBridgeFeature.CloudReadBackVerification | RawProgressBridgeFeature.LiveProgressStateSynchronization | RawProgressBridgeFeature.SubsequentSaveUnknownJsonPreservation | RawProgressBridgeFeature.ActiveProgressSnapshot | RawProgressBridgeFeature.RecoveryJournalManagement | RawProgressBridgeFeature.RecoveryJournalOwnership | RawProgressBridgeFeature.RecoveryJournalDisposition | RawProgressBridgeFeature.InvalidRecoveryJournalQuarantine;
		}

		public RawProgressBridgeDescriptor Describe()
		{
			int num = Volatile.Read(in _observedRuntimeSchema);
			return new RawProgressBridgeDescriptor
