			{
				try
				{
					ProgressState progress = manager.Progress;
					bool isSavingOrdinaryProgress = IsSavingOrdinaryProgress;
					SerializableProgress val;
					try
					{
						IsSavingOrdinaryProgress = true;
						val = progress.ToSerializable();
					}
					finally
					{
						IsSavingOrdinaryProgress = isSavingOrdinaryProgress;
					}
					val.SchemaVersion = GetSupportedSchema(manager);
					string text = JsonSerializationUtility.ToJson<SerializableProgress>(val);
					ProgressMirrorStore.SaveMirror(val, text);
