		internal static LoadCapture? BeginProgressLoad(ProgressSaveManager manager)
		{
			Monitor.Enter(SaveWindow);
			try
			{
				string progressPathForProfile = ProgressSaveManager.GetProgressPathForProfile(ProfileIdProvider(manager).CurrentProfileId, (bool?)null);
				string text = SaveStore(manager).ReadFile(progressPathForProfile);
				return string.IsNullOrWhiteSpace(text) ? null : new LoadCapture(text);
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[RawProgress] Could not capture the raw document before load: " + ex.Message, 1);
				return null;
