		}

		internal static void CompleteProgressLoad(ProgressSaveManager manager, ReadSaveResult<SerializableProgress> result, LoadCapture? capture)
		{
			try
			{
				if (capture == null || result == null || !result.Success || result.SaveData == null)
				{
					return;
				}
				int supportedSchema = GetSupportedSchema(manager);
				if (!TryReadSchema(capture.RawJson, out var schema) || schema != supportedSchema)
				{
					return;
				}
				ReadSaveResult<SerializableProgress> val = JsonSerializationUtility.FromJson<SerializableProgress>(capture.RawJson);
				if (val != null && val.Success && val.SaveData != null)
				{
					val.SaveData.SchemaVersion = supportedSchema;
					string knownJson = JsonSerializationUtility.ToJson<SerializableProgress>(val.SaveData);
					if (!RawProgressJsonPreservation.TryAttach(manager.Progress, capture.RawJson, knownJson))
					{
						RitsuLibFramework.Logger.Warn("[RawProgress] The loaded document contains unknown properties that could not be matched safely; ordinary saves will use the known game projection.", 1);
					}
				}
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[RawProgress] Failed to install preservation state after progress load: " + ex.Message, 1);
			}
		}

