		private static RawProgressCommitResult CommitOnMainThread(RawProgressCommitRequest request, CancellationToken cancellationToken)
		{
			if (request.ProtocolVersion != 1 || !TryGetSupportedSchema(out var supportedSchema))
			{
				return CreateResult(RawProgressCommitOutcome.ProviderIncompatible);
			}
			if (request.SchemaVersion != supportedSchema)
			{
				return CreateResult(RawProgressCommitOutcome.SchemaUnsupported);
			}
			if (cancellationToken.IsCancellationRequested)
			{
				return CreateResult(RawProgressCommitOutcome.CancelledBeforeCommit);
			}
			if (!TryValidateProposedDocument(request, out ValidatedDocument proposed))
			{
				return CreateResult(RawProgressCommitOutcome.ValidationFailed);
			}
			if (cancellationToken.IsCancellationRequested)
			{
				return CreateResult(RawProgressCommitOutcome.CancelledBeforeCommit);
			}
			lock (SaveWindow)
			{
				if (TryGetCompletedTransaction(request, out RawProgressCommitResult result))
				{
					return result;
				}
				if (cancellationToken.IsCancellationRequested)
				{
					return Remember(request, CreateResult(RawProgressCommitOutcome.CancelledBeforeCommit));
				}
				CapturedProgress capturedProgress = CaptureCore();
				if (capturedProgress.Result.Outcome != RawProgressReadOutcome.Succeeded || capturedProgress.Result.Snapshot == null)
				{
					return Remember(request, MapCaptureFailure(capturedProgress.Result.Outcome));
				}
				RawProgressSnapshot snapshot = capturedProgress.Result.Snapshot;
				if (snapshot.Generation.ProfileId != request.ExpectedGeneration.ProfileId || snapshot.Generation.IsModded != request.ExpectedGeneration.IsModded)
				{
					return Remember(request, CreateResult(RawProgressCommitOutcome.ActiveProfileChanged));
				}
				if (!GenerationMatches(snapshot.Generation, request.ExpectedGeneration))
				{
					return Remember(request, CreateResult(RawProgressCommitOutcome.GenerationConflict));
				}
				if (!string.Equals(proposed.ProgressUniqueId, snapshot.Generation.ProgressUniqueId, StringComparison.Ordinal))
				{
					return Remember(request, CreateResult(RawProgressCommitOutcome.ValidationFailed));
				}
				RecoveryJournal recoveryJournal = RecoveryJournal.Create(request, snapshot.RawJson);
				if (!recoveryJournal.TryPrepare())
				{
					return Remember(request, CreateResult(RawProgressCommitOutcome.RecoveryRequired, null, CloudReadBackStatus.NotRequired, null, null, unknownJsonContinuationInstalled: false, null, destinationMayHaveChanged: false, verifiedBackupAvailable: false, recoveryJournal.Exists));
				}
				if (cancellationToken.IsCancellationRequested)
				{
					bool flag = recoveryJournal.TryDelete();
					return Remember(request, CreateResult(RawProgressCommitOutcome.CancelledBeforeCommit, null, CloudReadBackStatus.NotRequired, null, null, unknownJsonContinuationInstalled: false, null, destinationMayHaveChanged: false, !flag, !flag));
				}
				return Remember(request, CommitPrepared(request.ProposedRawJson, request.ProposedSha256, proposed, capturedProgress, recoveryJournal));
			}
		}

		private static RawProgressCommitResult RestoreRecoveryOnMainThread(RawProgressRecoveryRequest request, CancellationToken cancellationToken)
		{
			if (!IsValidRecoveryRequest(request))
			{
				return CreateResult(RawProgressCommitOutcome.ValidationFailed);
