						if (!TryGetSupportedSchema(out var supportedSchema))
						{
							return CreateResult(RawProgressCommitOutcome.ProviderIncompatible, null, CloudReadBackStatus.NotRequired, null, null, unknownJsonContinuationInstalled: false, null, destinationMayHaveChanged: false, verifiedBackupAvailable: true, journal.Exists);
						}
