							return CreateResult(RawProgressCommitOutcome.SchemaUnsupported, null, CloudReadBackStatus.NotRequired, null, null, unknownJsonContinuationInstalled: false, null, destinationMayHaveChanged: false, verifiedBackupAvailable: true, journal.Exists);
						}
						ProgressGeneration expectedGeneration = request.ExpectedGeneration;
						if (data.ProfileId != expectedGeneration.ProfileId || data.IsModded != expectedGeneration.IsModded || !string.Equals(data.ProgressUniqueId, expectedGeneration.ProgressUniqueId, StringComparison.Ordinal))
						{
							return CreateResult(RawProgressCommitOutcome.ActiveProfileChanged, null, CloudReadBackStatus.NotRequired, null, null, unknownJsonContinuationInstalled: false, null, destinationMayHaveChanged: false, verifiedBackupAvailable: true, journal.Exists);
						}
						CapturedProgress capturedProgress = CaptureCore();
						if (capturedProgress.Result.Outcome != RawProgressReadOutcome.Succeeded || capturedProgress.Result.Snapshot == null)
						{
							return CreateResult(MapCaptureFailure(capturedProgress.Result.Outcome).Outcome, null, CloudReadBackStatus.NotRequired, null, null, unknownJsonContinuationInstalled: false, null, destinationMayHaveChanged: false, verifiedBackupAvailable: true, journal.Exists);
						}
						ProgressGeneration generation = capturedProgress.Result.Snapshot.Generation;
						if (generation.ProfileId != data.ProfileId || generation.IsModded != data.IsModded || !string.Equals(generation.ProgressUniqueId, data.ProgressUniqueId, StringComparison.Ordinal))
						{
							return CreateResult(RawProgressCommitOutcome.ActiveProfileChanged, null, CloudReadBackStatus.NotRequired, null, null, unknownJsonContinuationInstalled: false, null, destinationMayHaveChanged: false, verifiedBackupAvailable: true, journal.Exists);
						}
						if (!GenerationMatches(generation, expectedGeneration))
						{
							return CreateResult(RawProgressCommitOutcome.GenerationConflict, null, CloudReadBackStatus.NotRequired, null, null, unknownJsonContinuationInstalled: false, null, destinationMayHaveChanged: false, verifiedBackupAvailable: true, journal.Exists);
						}
						if (cancellationToken.IsCancellationRequested)
						{
							return CreateResult(RawProgressCommitOutcome.CancelledBeforeCommit, null, CloudReadBackStatus.NotRequired, null, null, unknownJsonContinuationInstalled: false, null, destinationMayHaveChanged: false, verifiedBackupAvailable: true, journal.Exists);
						}
						if (!TryGetUtf8Bytes(data.OriginalRawJson, out byte[] bytes))
						{
							return CreateResult(RawProgressCommitOutcome.RecoveryJournalInvalid, null, CloudReadBackStatus.NotRequired, null, null, unknownJsonContinuationInstalled: false, null, destinationMayHaveChanged: false, verifiedBackupAvailable: true, journal.Exists);
						}
						if (!TryValidateProposedDocument(new RawProgressCommitRequest
						{
							ProtocolVersion = 1,
							SchemaVersion = data.SchemaVersion,
							OwnerId = data.OwnerId,
							TransactionId = data.TransactionId,
							ExpectedGeneration = expectedGeneration,
							ProposedRawJson = data.OriginalRawJson,
							ProposedSha256 = data.OriginalSha256,
							ProposedUtf8Length = bytes.LongLength
						}, out ValidatedDocument proposed))
						{
							return CreateResult(RawProgressCommitOutcome.RecoveryJournalInvalid, null, CloudReadBackStatus.NotRequired, null, null, unknownJsonContinuationInstalled: false, null, destinationMayHaveChanged: false, verifiedBackupAvailable: true, journal.Exists);
						}
						return CommitPrepared(data.OriginalRawJson, data.OriginalSha256, proposed, capturedProgress, journal);
					}
					goto default;
				default:
					return CreateResult(RawProgressCommitOutcome.RecoveryJournalInvalid);
				}
			}
		}

		private static RawProgressRecoveryDiscardResult DiscardRecoveryOnMainThread(RawProgressRecoveryRequest request, CancellationToken cancellationToken)
		{
			if (!IsValidRecoveryRequest(request))
			{
				return CreateDiscardResult(RawProgressRecoveryDiscardOutcome.ValidationFailed);
			}
			if (cancellationToken.IsCancellationRequested)
			{
				return CreateDiscardResult(RawProgressRecoveryDiscardOutcome.Cancelled);
			}
			lock (SaveWindow)
			{
				if (cancellationToken.IsCancellationRequested)
				{
					return CreateDiscardResult(RawProgressRecoveryDiscardOutcome.Cancelled);
				}
				RecoveryJournal journal;
				switch (RecoveryJournal.TryLoad(request.OwnerId, request.TransactionId, out journal))
				{
				case RecoveryJournalLoadOutcome.NotFound:
					return CreateDiscardResult(RawProgressRecoveryDiscardOutcome.RecoveryJournalNotFound);
				case RecoveryJournalLoadOutcome.Succeeded:
					if (journal != null)
					{
						if (!HashEquals(journal.RecoveryToken, request.RecoveryToken))
						{
							return CreateDiscardResult(RawProgressRecoveryDiscardOutcome.RecoveryJournalChanged, journal.Exists);
						}
						RecoveryJournalData data = journal.Data;
						ProgressGeneration expectedGeneration = request.ExpectedGeneration;
						if (data.ProfileId != expectedGeneration.ProfileId || data.IsModded != expectedGeneration.IsModded || !string.Equals(data.ProgressUniqueId, expectedGeneration.ProgressUniqueId, StringComparison.Ordinal))
						{
							return CreateDiscardResult(RawProgressRecoveryDiscardOutcome.ActiveProfileChanged, journal.Exists);
						}
						CapturedProgress capturedProgress = CaptureCore();
						if (capturedProgress.Result.Outcome != RawProgressReadOutcome.Succeeded || capturedProgress.Result.Snapshot == null)
						{
							return CreateDiscardResult((capturedProgress.Result.Outcome == RawProgressReadOutcome.ActiveProfileUnavailable) ? RawProgressRecoveryDiscardOutcome.ActiveProfileChanged : RawProgressRecoveryDiscardOutcome.DestinationUnavailable, journal.Exists);
						}
						ProgressGeneration generation = capturedProgress.Result.Snapshot.Generation;
						if (generation.ProfileId != data.ProfileId || generation.IsModded != data.IsModded || !string.Equals(generation.ProgressUniqueId, data.ProgressUniqueId, StringComparison.Ordinal))
						{
							return CreateDiscardResult(RawProgressRecoveryDiscardOutcome.ActiveProfileChanged, journal.Exists);
						}
						if (!GenerationMatches(generation, expectedGeneration))
						{
							return CreateDiscardResult(RawProgressRecoveryDiscardOutcome.GenerationConflict, journal.Exists);
						}
						if (cancellationToken.IsCancellationRequested)
						{
							return CreateDiscardResult(RawProgressRecoveryDiscardOutcome.Cancelled, journal.Exists);
						}
						return CreateDiscardResult((!journal.TryDelete()) ? RawProgressRecoveryDiscardOutcome.StorageFailure : RawProgressRecoveryDiscardOutcome.Discarded, journal.Exists);
					}
					goto default;
				default:
					return CreateDiscardResult(RawProgressRecoveryDiscardOutcome.RecoveryJournalInvalid);
				}
			}
		}

