			}
			ReadSaveResult<SerializableProgress> val = JsonSerializationUtility.FromJson<SerializableProgress>(request.ProposedRawJson);
			if (val == null || !val.Success || val.SaveData == null || val.SaveData.SchemaVersion != request.SchemaVersion || string.IsNullOrWhiteSpace(val.SaveData.UniqueId) || !string.Equals(val.SaveData.UniqueId, request.ExpectedGeneration.ProgressUniqueId, StringComparison.Ordinal))
			{
