					obj.SchemaVersion = request.SchemaVersion;
					string text = JsonSerializationUtility.ToJson<SerializableProgress>(obj);
					proposed = new ValidatedDocument(val.SaveData.UniqueId, val3, text, ComputeSha256(text));
					flag = true;
				}
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[RawProgress] Proposed document validation failed: " + ex.Message, 1);
				flag = false;
