		private static bool TryValidateJsonShape(string json, out int schema)
		{
			schema = 0;
			try
			{
				using JsonDocument jsonDocument = JsonDocument.Parse(json, new JsonDocumentOptions
				{
					AllowTrailingCommas = false,
					CommentHandling = JsonCommentHandling.Disallow,
					MaxDepth = 128
				});
				if (jsonDocument.RootElement.ValueKind != JsonValueKind.Object || !jsonDocument.RootElement.TryGetProperty("schema_version", out var value) || !value.TryGetInt32(out schema) || schema < 1)
				{
					return false;
				}
				return HasUniquePropertyNames(jsonDocument.RootElement);
			}
			catch (JsonException)
			{
				return false;
			}
		}

		private static bool HasUniquePropertyNames(JsonElement element)
		{
			switch (element.ValueKind)
			{
			case JsonValueKind.Object:
			{
				HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
				foreach (JsonProperty item in element.EnumerateObject())
				{
					if (!hashSet.Add(item.Name) || !HasUniquePropertyNames(item.Value))
					{
						return false;
					}
				}
				break;
			}
			case JsonValueKind.Array:
				foreach (JsonElement item2 in element.EnumerateArray())
				{
					if (!HasUniquePropertyNames(item2))
					{
						return false;
					}
				}
				break;
			}
			return true;
		}

		private static bool TryReadSchema(string json, out int schema)
