			{
				return actual.CloudLastModifiedUtcTicks == expected.CloudLastModifiedUtcTicks;
			}
			return false;
		}

		private static (CloudReadBackStatus Status, string? Hash) VerifyCloudReadBack(ISaveStore saveStore, string path, string expectedHash, bool batchFailure)
		{
			CloudSaveStore val = (CloudSaveStore)(object)((saveStore is CloudSaveStore) ? saveStore : null);
			if (val == null)
			{
				return (Status: CloudReadBackStatus.NotRequired, Hash: null);
			}
			if (batchFailure)
			{
				return (Status: CloudReadBackStatus.FailureObserved, Hash: null);
			}
			try
			{
				ICloudSaveStore cloudStore = val.CloudStore;
				if (!cloudStore.IsFilePersisted(path))
				{
					return (Status: CloudReadBackStatus.Unavailable, Hash: null);
				}
				string text = ((ISaveStore)cloudStore).ReadFile(path);
				if (text == null || !TryGetUtf8Bytes(text, out byte[] bytes))
				{
					return (Status: CloudReadBackStatus.Unavailable, Hash: null);
				}
				string text2 = ComputeSha256(bytes);
				return HashEquals(text2, expectedHash) ? (Status: CloudReadBackStatus.Succeeded, Hash: text2) : (Status: CloudReadBackStatus.Mismatch, Hash: text2);
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[RawProgress] Cloud read-back failed: " + ex.Message, 1);
				return (Status: CloudReadBackStatus.FailureObserved, Hash: null);
			}
		}

		private static bool VerifyGameBackup(ISaveStore localStore, string path, string originalRawJson)
		{
			try
			{
