				return text != null && HashEquals(ComputeSha256(text), ComputeSha256(originalRawJson));
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[RawProgress] Could not verify the game backup: " + ex.Message, 1);
				return false;
			}
		}

