		private static bool TryGetCompletedTransaction(RawProgressCommitRequest request, out RawProgressCommitResult result)
		{
			RecoveryTransactionKey key = new RecoveryTransactionKey(request.OwnerId, request.TransactionId);
			if (!CompletedTransactions.TryGetValue(key, out CompletedTransaction value))
			{
				result = null;
				return false;
			}
			result = (HashEquals(value.ProposedSha256, request.ProposedSha256) ? value.Result : CreateResult(RawProgressCommitOutcome.ValidationFailed));
			return true;
		}

		private static RawProgressCommitResult Remember(RawProgressCommitRequest request, RawProgressCommitResult result)
		{
			RecoveryTransactionKey recoveryTransactionKey = new RecoveryTransactionKey(request.OwnerId, request.TransactionId);
			if (!CompletedTransactions.ContainsKey(recoveryTransactionKey))
			{
				CompletedTransactions.Add(recoveryTransactionKey, new CompletedTransaction(request.ProposedSha256, result));
				CompletedTransactionOrder.Enqueue(recoveryTransactionKey);
				while (CompletedTransactionOrder.Count > 256)
				{
					CompletedTransactions.Remove(CompletedTransactionOrder.Dequeue());
				}
			}
			return result;
		}

