		private sealed class PreservationState
		{
			private readonly Lock _syncRoot = new Lock();

			private JsonNode _knownBaseline;

			private JsonNode _rawDocument;

			private PreservationState(JsonNode rawDocument, JsonNode knownBaseline)
			{
				_rawDocument = rawDocument;
				_knownBaseline = knownBaseline;
			}

			internal static PreservationState Create(string rawJson, string knownJson)
			{
				JsonNode? rawDocument = JsonNode.Parse(rawJson) ?? throw new JsonException("The raw progress document parsed as null.");
				JsonNode knownBaseline = JsonNode.Parse(knownJson) ?? throw new JsonException("The known progress projection parsed as null.");
				return new PreservationState(rawDocument, knownBaseline);
			}

			internal bool CanReconstructRawDocument()
			{
				using (_syncRoot.EnterScope())
				{
					JsonNode current = _knownBaseline.DeepClone();
					MergeUnknown(_rawDocument, _knownBaseline, current);
