				}
			}

			internal string PreserveAndAdvance(string knownJson)
			{
				JsonNode jsonNode = JsonNode.Parse(knownJson) ?? throw new JsonException("The current known progress projection parsed as null.");
				using (_syncRoot.EnterScope())
