					}
					JsonNode rawDocument = jsonNode2.DeepClone();
					string result = jsonNode2.ToJsonString(WriteOptions);
					_rawDocument = rawDocument;
					_knownBaseline = jsonNode;
					return result;
				}
			}
		}

		private static readonly ConditionalWeakTable<ProgressState, PreservationState> States = new ConditionalWeakTable<ProgressState, PreservationState>();

		private static readonly JsonSerializerOptions WriteOptions = new JsonSerializerOptions
		{
