		private static readonly string[] IdentityPropertyNames = new string[7] { "id", "character", "achievement", "key", "name", "player_id", "slot" };

		internal static bool TryAttach(ProgressState progress, string rawJson, string knownJson)
		{
			ArgumentNullException.ThrowIfNull(progress, "progress");
			States.Remove(progress);
			if (string.Equals(rawJson, knownJson, StringComparison.Ordinal))
			{
				return true;
			}
			try
			{
				PreservationState preservationState = PreservationState.Create(rawJson, knownJson);
				if (!preservationState.HasUnknownProperties())
				{
					return true;
				}
				if (!preservationState.CanReconstructRawDocument())
				{
					return false;
				}
				States.Add(progress, preservationState);
				return true;
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[RawProgress] Failed to install unknown-property preservation: " + ex.Message, 1);
				return false;
			}
		}

		internal static string PreserveAndAdvance(ProgressState progress, string knownJson)
		{
			ArgumentNullException.ThrowIfNull(progress, "progress");
			ArgumentNullException.ThrowIfNull(knownJson, "knownJson");
			if (!States.TryGetValue(progress, out PreservationState value))
			{
				return knownJson;
			}
			try
			{
				return value.PreserveAndAdvance(knownJson);
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[RawProgress] Failed to preserve unknown properties during an ordinary save: " + ex.Message, 1);
				throw;
			}
		}

