			//IL_0190: Unknown result type (might be due to invalid IL or missing references)
			//IL_0162: Unknown result type (might be due to invalid IL or missing references)
			//IL_00fc: Unknown result type (might be due to invalid IL or missing references)
			//IL_0155: Unknown result type (might be due to invalid IL or missing references)
			//IL_0148: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d8: Unknown result type (might be due to invalid IL or missing references)
			//IL_013b: Unknown result type (might be due to invalid IL or missing references)
			binding = default(RuntimeHotkeyBinding);
			normalized = string.Empty;
			if (string.IsNullOrWhiteSpace(text))
			{
				return false;
			}
			if (TryParseActionBinding(text, out binding, out normalized))
			{
				return true;
			}
			string[] array = text.Split('+', StringSplitOptions.TrimEntries);
			if (array.Length == 0 || array.Any(string.IsNullOrEmpty))
			{
				return false;
			}
			ModifierRequirement modifierRequirement = ModifierRequirement.NotPressed;
			ModifierRequirement modifierRequirement2 = ModifierRequirement.NotPressed;
			ModifierRequirement modifierRequirement3 = ModifierRequirement.NotPressed;
			ModifierRequirement modifierRequirement4 = ModifierRequirement.NotPressed;
			Key? val = null;
			HashSet<ModifierKind> hashSet = new HashSet<ModifierKind>();
			string[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				string token = array2[i].Trim();
				if (TryParseModifierToken(token, out var kind, out var requirement))
				{
					if (!hashSet.Add(kind))
					{
						return false;
					}
					switch (kind)
					{
					case ModifierKind.Ctrl:
						modifierRequirement = requirement;
						break;
					case ModifierKind.Alt:
						modifierRequirement2 = requirement;
						break;
					case ModifierKind.Shift:
						modifierRequirement3 = requirement;
						break;
					case ModifierKind.Meta:
						modifierRequirement4 = requirement;
						break;
					}
