					}
					val = key;
				}
			}
			Key? val2 = val;
			if (!val2.HasValue)
			{
				val = ((modifierRequirement != ModifierRequirement.NotPressed) ? new Key?(ModifierKindToPrimaryKey(ModifierKind.Ctrl)) : ((modifierRequirement2 != ModifierRequirement.NotPressed) ? new Key?(ModifierKindToPrimaryKey(ModifierKind.Alt)) : ((modifierRequirement3 != ModifierRequirement.NotPressed) ? new Key?(ModifierKindToPrimaryKey(ModifierKind.Shift)) : ((modifierRequirement4 != ModifierRequirement.NotPressed) ? new Key?(ModifierKindToPrimaryKey(ModifierKind.Meta)) : ((Key?)null)))));
			}
			if (!val.HasValue)
			{
				return false;
			}
			normalized = BuildCanonicalString(val.Value, modifierRequirement, modifierRequirement2, modifierRequirement3, modifierRequirement4);
			binding = new RuntimeHotkeyBinding(RuntimeHotkeyBindingKind.Key, val.Value, modifierRequirement, modifierRequirement2, modifierRequirement3, modifierRequirement4, null, normalized);
			return true;
		}

		public static string ActionBinding(string actionName)
		{
			string text = NormalizeActionName(actionName);
			if (!string.IsNullOrWhiteSpace(text))
			{
				return "action:" + text;
			}
			return string.Empty;
		}

		public static string NormalizeOrDefault(string? text, string fallback)
		{
			if (!TryParse(text, out RuntimeHotkeyBinding _, out string normalized))
			{
