			}
			return normalized;
		}

		internal static bool IsModifierKey(Key key)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			return GetModifierKind(key) != ModifierKind.None;
		}

		internal unsafe static ModifierKind GetModifierKind(Key key)
		{
			string text = ((object)(*(Key*)(&key))/*cast due to constrained. prefix*/).ToString().ToLowerInvariant();
			if (text.Contains("ctrl") || text.Contains("control"))
			{
				return ModifierKind.Ctrl;
			}
			if (text.Contains("alt"))
			{
				return ModifierKind.Alt;
			}
			if (text.Contains("shift"))
			{
				return ModifierKind.Shift;
			}
			if (text.Contains("meta") || text.Contains("cmd") || text.Contains("command"))
			{
				return ModifierKind.Meta;
			}
			return ModifierKind.None;
		}

		internal static ModifierKind GetModifierKindForKeyEvent(InputEventKey keyEvent)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			ModifierKind modifierKind = GetModifierKind(keyEvent.PhysicalKeycode);
			if (modifierKind == ModifierKind.None)
			{
				return GetModifierKind(keyEvent.Keycode);
			}
			return modifierKind;
		}

		internal static bool ModifierStateMatches(ModifierKind kind, ModifierRequirement requirement, InputEventKey keyEvent, RuntimeModifierSideState modifierSides)
		{
			switch (requirement)
			{
			case ModifierRequirement.NotPressed:
				return !IsModifierPressed(kind, keyEvent);
			case ModifierRequirement.AnySide:
				return IsModifierPressed(kind, keyEvent);
			case ModifierRequirement.LeftOnly:
			case ModifierRequirement.RightOnly:
				return IsModifierPressed(kind, keyEvent) && modifierSides.IsPressed(kind, requirement);
			default:
				return false;
			}
		}

		private static bool IsModifierPressed(ModifierKind kind, InputEventKey keyEvent)
		{
			if (GetModifierKindForKeyEvent(keyEvent) == kind)
			{
				return true;
			}
			return kind switch
			{
				ModifierKind.Ctrl => ((InputEventWithModifiers)keyEvent).CtrlPressed, 
				ModifierKind.Alt => ((InputEventWithModifiers)keyEvent).AltPressed, 
				ModifierKind.Shift => ((InputEventWithModifiers)keyEvent).ShiftPressed, 
				ModifierKind.Meta => ((InputEventWithModifiers)keyEvent).MetaPressed, 
				_ => false, 
			};
		}

		private static bool TryParseModifierToken(string token, out ModifierKind kind, out ModifierRequirement requirement)
		{
			switch (token.Replace("_", string.Empty, ignoreCase: true, CultureInfo.InvariantCulture).Replace("-", string.Empty, ignoreCase: true, CultureInfo.InvariantCulture).ToLowerInvariant())
			{
			case "ctrl":
			case "control":
				kind = ModifierKind.Ctrl;
				requirement = ModifierRequirement.AnySide;
				return true;
			case "leftctrl":
			case "lcontrol":
			case "leftcontrol":
			case "lctrl":
				kind = ModifierKind.Ctrl;
				requirement = ModifierRequirement.LeftOnly;
				return true;
			case "rcontrol":
			case "rctrl":
			case "rightctrl":
			case "rightcontrol":
				kind = ModifierKind.Ctrl;
				requirement = ModifierRequirement.RightOnly;
				return true;
			case "alt":
				kind = ModifierKind.Alt;
				requirement = ModifierRequirement.AnySide;
				return true;
			case "lalt":
			case "leftalt":
				kind = ModifierKind.Alt;
				requirement = ModifierRequirement.LeftOnly;
				return true;
			case "ralt":
			case "rightalt":
				kind = ModifierKind.Alt;
				requirement = ModifierRequirement.RightOnly;
				return true;
			case "shift":
				kind = ModifierKind.Shift;
				requirement = ModifierRequirement.AnySide;
				return true;
			case "leftshift":
			case "lshift":
				kind = ModifierKind.Shift;
				requirement = ModifierRequirement.LeftOnly;
				return true;
			case "rshift":
			case "rightshift":
				kind = ModifierKind.Shift;
				requirement = ModifierRequirement.RightOnly;
				return true;
			case "meta":
			case "command":
			case "cmd":
				kind = ModifierKind.Meta;
				requirement = ModifierRequirement.AnySide;
				return true;
			case "lcmd":
			case "leftcmd":
			case "leftmeta":
			case "leftcommand":
			case "lmeta":
				kind = ModifierKind.Meta;
				requirement = ModifierRequirement.LeftOnly;
				return true;
			case "rcmd":
			case "rightcmd":
			case "rmeta":
			case "rightmeta":
			case "rightcommand":
				kind = ModifierKind.Meta;
				requirement = ModifierRequirement.RightOnly;
				return true;
			default:
				kind = ModifierKind.None;
				requirement = ModifierRequirement.NotPressed;
				return false;
			}
		}

		private static bool TryParseKeyToken(string token, out Key key)
		{
			//IL_0019: Unknown result type (might be due to invalid IL or missing references)
			//IL_001a: Unknown result type (might be due to invalid IL or missing references)
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_002c: Expected I8, but got Unknown
			if (Enum.TryParse<Key>(token, true, out key))
			{
				return true;
			}
			Key[] values = Enum.GetValues<Key>();
			foreach (Key val in values)
			{
				if (string.Equals(OS.GetKeycodeString(val), token, StringComparison.OrdinalIgnoreCase))
				{
					key = (Key)(long)val;
					return true;
				}
			}
			return false;
		}

		private static bool TryParseActionBinding(string text, out RuntimeHotkeyBinding binding, out string normalized)
		{
			binding = default(RuntimeHotkeyBinding);
			normalized = string.Empty;
			string text2 = text.Trim();
			if (!text2.StartsWith("action:", StringComparison.OrdinalIgnoreCase))
			{
				return false;
			}
			string text3 = NormalizeActionName(text2.Substring("action:".Length));
			if (string.IsNullOrWhiteSpace(text3))
			{
				return false;
			}
			normalized = "action:" + text3;
			binding = new RuntimeHotkeyBinding(RuntimeHotkeyBindingKind.Action, (Key)0, ModifierRequirement.NotPressed, ModifierRequirement.NotPressed, ModifierRequirement.NotPressed, ModifierRequirement.NotPressed, text3, normalized);
			return true;
		}

		private static string NormalizeActionName(string? actionName)
		{
			return actionName?.Trim() ?? string.Empty;
		}

		private static string BuildCanonicalString(Key primaryKey, ModifierRequirement ctrl, ModifierRequirement alt, ModifierRequirement shift, ModifierRequirement meta)
		{
			//IL_0009: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			//IL_006d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			List<string> list = new List<string>();
			if (ctrl != ModifierRequirement.NotPressed && !SameModifierAsPrimary(primaryKey, ModifierKind.Ctrl))
			{
				list.Add(RequirementToken(ModifierKind.Ctrl, ctrl));
			}
			if (alt != ModifierRequirement.NotPressed && !SameModifierAsPrimary(primaryKey, ModifierKind.Alt))
			{
				list.Add(RequirementToken(ModifierKind.Alt, alt));
			}
			if (shift != ModifierRequirement.NotPressed && !SameModifierAsPrimary(primaryKey, ModifierKind.Shift))
			{
				list.Add(RequirementToken(ModifierKind.Shift, shift));
			}
			if (meta != ModifierRequirement.NotPressed && !SameModifierAsPrimary(primaryKey, ModifierKind.Meta))
			{
				list.Add(RequirementToken(ModifierKind.Meta, meta));
			}
			list.Add(PrimaryKeyToken(primaryKey, ctrl, alt, shift, meta));
			return string.Join('+', list);
		}

		private static bool SameModifierAsPrimary(Key primaryKey, ModifierKind kind)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			return GetModifierKind(primaryKey) == kind;
		}

		private static string RequirementToken(ModifierKind kind, ModifierRequirement requirement)
		{
			return requirement switch
			{
				ModifierRequirement.AnySide => kind.ToString(), 
				ModifierRequirement.LeftOnly => $"Left{kind}", 
				ModifierRequirement.RightOnly => $"Right{kind}", 
				_ => string.Empty, 
			};
		}

		private unsafe static string PrimaryKeyToken(Key key, ModifierRequirement ctrl, ModifierRequirement alt, ModifierRequirement shift, ModifierRequirement meta)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			return GetModifierKind(key) switch
			{
				ModifierKind.Ctrl => RequirementToken(ModifierKind.Ctrl, ctrl), 
				ModifierKind.Alt => RequirementToken(ModifierKind.Alt, alt), 
				ModifierKind.Shift => RequirementToken(ModifierKind.Shift, shift), 
				ModifierKind.Meta => RequirementToken(ModifierKind.Meta, meta), 
				_ => ((object)(*(Key*)(&key))/*cast due to constrained. prefix*/).ToString(), 
			};
		}

		private static Key ModifierKindToPrimaryKey(ModifierKind kind)
		{
			//IL_0020: Unknown result type (might be due to invalid IL or missing references)
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			//IL_0032: Unknown result type (might be due to invalid IL or missing references)
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			//IL_0040: Unknown result type (might be due to invalid IL or missing references)
			return (Key)(kind switch
			{
				ModifierKind.Ctrl => 4194326, 
				ModifierKind.Alt => 4194328, 
				ModifierKind.Shift => 4194325, 
				ModifierKind.Meta => 4194327, 
				_ => 0, 
			});
		}
	}
