				if (ShouldConsider(runtimeHotkeyRegistration.Options) && runtimeHotkeyRegistration.Matches(val, _modifierSides))
				{
					runtimeHotkeyRegistration.Callback();
					if (runtimeHotkeyRegistration.Options.MarkInputHandled)
					{
						Viewport viewport = ((Node)this).GetViewport();
						if (viewport != null)
						{
							viewport.SetInputAsHandled();
						}
					}
					break;
				}
			}
		}

		public override void _UnhandledInput(InputEvent @event)
		{
			InputEventAction val = (InputEventAction)(object)((@event is InputEventAction) ? @event : null);
			if (val == null || !val.Pressed || ((InputEvent)val).IsEcho())
			{
				return;
			}
			for (int num = _registrations.Count - 1; num >= 0; num--)
			{
				RuntimeHotkeyRegistration runtimeHotkeyRegistration = _registrations[num];
				if (ShouldConsider(runtimeHotkeyRegistration.Options) && runtimeHotkeyRegistration.Matches(val))
				{
					runtimeHotkeyRegistration.Callback();
					if (runtimeHotkeyRegistration.Options.MarkInputHandled)
					{
						Viewport viewport = ((Node)this).GetViewport();
						if (viewport != null)
						{
							viewport.SetInputAsHandled();
						}
					}
					break;
				}
			}
		}

		private static bool ShouldConsider(RuntimeHotkeyOptions options)
		{
			if (options.SuppressWhenDevConsoleVisible && ((CanvasItem)NDevConsole.Instance).Visible)
			{
				return false;
			}
			if (!options.SuppressWhenTextInputFocused)
			{
				return true;
			}
			MainLoop mainLoop = Engine.GetMainLoop();
			SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
			if (val != null)
			{
				Window root = val.Root;
				if (root != null)
				{
					Viewport viewport = ((Node)root).GetViewport();
					Control val2 = ((viewport != null) ? viewport.GuiGetFocusOwner() : null);
					if (val2 != null)
					{
						LineEdit val3 = (LineEdit)(object)((val2 is LineEdit) ? val2 : null);
						if (val3 == null || !val3.IsEditing())
						{
							NMegaTextEdit val4 = (NMegaTextEdit)(object)((val2 is NMegaTextEdit) ? val2 : null);
							if (val4 != null)
							{
								return !val4.IsEditing();
							}
							return true;
						}
						return false;
					}
					return true;
				}
			}
			return true;
		}

