	internal sealed class RuntimeHotkeyRegistration(IReadOnlyList<RuntimeHotkeyBinding> bindings, Action callback, RuntimeHotkeyOptions options)
	{
		private readonly List<RuntimeHotkeyBinding> _bindings = bindings.ToList();

		private readonly List<IDisposable> _steamInputRegistrations = new List<IDisposable>();

		public IReadOnlyList<RuntimeHotkeyBinding> Bindings => _bindings;

		public Action Callback { get; } = callback;

		public RuntimeHotkeyOptions Options { get; } = options;

		public void InitializeOptionalSteamInputActions()
		{
			SyncOptionalSteamInputActions();
		}

		public void SetBindings(IEnumerable<RuntimeHotkeyBinding> bindings)
		{
			_bindings.Clear();
			_bindings.AddRange(bindings);
			SyncOptionalSteamInputActions();
		}

		public bool Matches(InputEventKey keyEvent, RuntimeModifierSideState modifierSides)
		{
			for (int i = 0; i < _bindings.Count; i++)
			{
				if (_bindings[i].Matches(keyEvent, modifierSides))
				{
					return true;
				}
			}
			return false;
		}

		public bool Matches(InputEventAction actionEvent)
		{
			for (int i = 0; i < _bindings.Count; i++)
			{
				if (_bindings[i].Matches(actionEvent))
				{
					return true;
				}
			}
			return false;
		}

		public RuntimeHotkeyRegistrationDetails ToRegistrationDetails()
		{
			string[] currentBindings = _bindings.Select((RuntimeHotkeyBinding binding) => binding.CanonicalString).ToArray();
			bool[] bindingModifierOnlyStates = _bindings.Select((RuntimeHotkeyBinding binding) => binding.IsModifierOnly).ToArray();
			return new RuntimeHotkeyRegistrationDetails(currentBindings, bindingModifierOnlyStates, Options.Id, ResolveText(Options.DisplayName), ResolveText(Options.Description), Options.Purpose, ResolveText(Options.Category), Options.MarkInputHandled, Options.SuppressWhenTextInputFocused, Options.SuppressWhenDevConsoleVisible, Options.DebugName);
		}

		public RuntimeHotkeyRegistrationInfo ToRegistrationInfo()
		{
			return ToRegistrationDetails().ToRegistrationInfo();
		}

		private static string? ResolveText(RuntimeHotkeyText? text)
		{
			return text?.Resolve();
		}

		private void SyncOptionalSteamInputActions()
		{
			foreach (IDisposable steamInputRegistration in _steamInputRegistrations)
			{
				steamInputRegistration.Dispose();
			}
			_steamInputRegistrations.Clear();
			if (!Options.ExposeToSteamInput)
			{
				return;
			}
			RuntimeHotkeyText displayName = Options.DisplayName ?? RuntimeHotkeyText.Literal(Options.DebugName ?? Options.Id ?? "RitsuLib action");
			foreach (RuntimeHotkeyBinding binding in _bindings)
			{
				if (binding.Kind == RuntimeHotkeyBindingKind.Action && !string.IsNullOrWhiteSpace(binding.ActionName))
				{
					_steamInputRegistrations.Add(RitsuSteamInputActionRegistry.RegisterAction(binding.ActionName, displayName, Options.Description, Options.Id));
				}
			}
		}
	}
	internal sealed class RuntimeHotkeyHandle(RuntimeHotkeyRouterNode owner, RuntimeHotkeyRegistration registration) : IRuntimeHotkeyHandle, IDisposable
	{
		private RuntimeHotkeyRouterNode? _owner = owner;

		private RuntimeHotkeyRegistration? _registration = registration;

		public string CurrentBinding => CurrentBindings.FirstOrDefault() ?? string.Empty;

		public IReadOnlyList<string> CurrentBindings => _registration?.Bindings.Select((RuntimeHotkeyBinding binding) => binding.CanonicalString).ToArray() ?? Array.Empty<string>();

		public bool IsRegistered
		{
			get
			{
				if (_owner != null)
				{
					return _registration != null;
				}
				return false;
			}
		}

		public bool TryRebind(string bindingText, out string normalizedBinding)
		{
			if (_owner != null && _registration != null)
			{
				return _owner.TryRebind(_registration, bindingText, out normalizedBinding);
			}
			normalizedBinding = string.Empty;
			return false;
		}

		public bool TryRebind(IEnumerable<string> bindingTexts, out IReadOnlyList<string> normalizedBindings)
		{
			ArgumentNullException.ThrowIfNull(bindingTexts, "bindingTexts");
			if (_owner != null && _registration != null)
			{
				return _owner.TryRebind(_registration, bindingTexts, out normalizedBindings);
			}
			normalizedBindings = Array.Empty<string>();
			return false;
		}

		public bool TryGetRegistrationInfo(out RuntimeHotkeyRegistrationInfo registrationInfo)
		{
			if (_owner != null && _registration != null)
			{
				return _owner.TryGetRegistrationInfo(_registration, out registrationInfo);
			}
			registrationInfo = null;
			return false;
		}

		public void Unregister()
		{
			if (_owner != null && _registration != null)
			{
				_registration.SetBindings(Array.Empty<RuntimeHotkeyBinding>());
				_owner.Unregister(_registration);
				_owner = null;
				_registration = null;
			}
		}

		public void Dispose()
		{
			Unregister();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides a settings-independent runtime hotkey API that parses persisted bindings and routes callbacks through
	///         a shared input node.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供独立于设置系统的运行时热键 API，用于解析持久化绑定，并通过共享输入节点路由回调。
	///     </para>
	/// </summary>
	public static class RuntimeHotkeyService
	{
		private static readonly Lock SyncRoot = new Lock();

		private static RuntimeHotkeyRouterNode? _router;

		private static IDisposable? _lifecycleSubscription;

		/// <summary>
		///     <para xml:lang="en">Schedules the shared router to be attached when the game root becomes ready.</para>
		///     <para xml:lang="zh-CN">安排在游戏根节点就绪时附加共享路由器。</para>
		/// </summary>
		public static void Initialize()
		{
			using (SyncRoot.EnterScope())
			{
				if (_lifecycleSubscription == null)
				{
					_lifecycleSubscription = RitsuLibFramework.SubscribeLifecycle(delegate(GameReadyEvent evt)
					{
						EnsureRouterAttached((Node?)(object)evt.Game);
					});
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets compatibility snapshots for all registered runtime hotkeys.</para>
		///     <para xml:lang="zh-CN">获取所有已注册运行时热键的兼容快照。</para>
		/// </summary>
		public static IReadOnlyList<RuntimeHotkeyRegistrationInfo> GetRegisteredHotkeys()
		{
			using (SyncRoot.EnterScope())
			{
				return _router?.GetRegistrationInfos() ?? Array.Empty<RuntimeHotkeyRegistrationInfo>();
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets detailed snapshots for all registered runtime hotkeys and their bindings.</para>
		///     <para xml:lang="zh-CN">获取所有已注册运行时热键及其绑定的详细快照。</para>
		/// </summary>
		public static IReadOnlyList<RuntimeHotkeyRegistrationDetails> GetRegisteredHotkeyDetails()
		{
			using (SyncRoot.EnterScope())
			{
				return _router?.GetRegistrationDetails() ?? Array.Empty<RuntimeHotkeyRegistrationDetails>();
			}
		}

		/// <summary>
		///     <para xml:lang="en">Tries to find a registered hotkey by its stable identifier.</para>
		///     <para xml:lang="zh-CN">尝试按稳定标识符查找已注册热键。</para>
		/// </summary>
		/// <param name="id">
		///     <para xml:lang="en">The stable registration identifier to find.</para>
		///     <para xml:lang="zh-CN">要查找的稳定注册标识符。</para>
		/// </param>
		/// <param name="registrationInfo">
		///     <para xml:lang="en">Receives the matching registration snapshot.</para>
		///     <para xml:lang="zh-CN">接收匹配的注册快照。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if a matching registration was found; otherwise,
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若找到匹配的注册，则返回 <see langword="true" />；否则返回
		///         <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool TryGetRegisteredHotkey(string id, out RuntimeHotkeyRegistrationInfo registrationInfo)
		{
			using (SyncRoot.EnterScope())
			{
				RuntimeHotkeyRegistrationInfo runtimeHotkeyRegistrationInfo = _router?.GetRegistrationInfoById(id);
				if (runtimeHotkeyRegistrationInfo != null)
				{
					registrationInfo = runtimeHotkeyRegistrationInfo;
					return true;
				}
				registrationInfo = null;
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Tries to parse a persisted binding into its canonical form.</para>
		///     <para xml:lang="zh-CN">尝试将持久化绑定解析为规范形式。</para>
		/// </summary>
		/// <param name="bindingText">
		///     <para xml:lang="en">The binding text to normalize.</para>
		///     <para xml:lang="zh-CN">要规范化的绑定文本。</para>
		/// </param>
		/// <param name="normalizedBinding">
		///     <para xml:lang="en">Receives the canonical binding when parsing succeeds.</para>
		///     <para xml:lang="zh-CN">解析成功时接收规范化绑定。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if the binding was parsed; otherwise,
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若成功解析绑定，则返回 <see langword="true" />；否则返回
		///         <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool TryNormalizeBinding(string? bindingText, out string normalizedBinding)
		{
			RuntimeHotkeyBinding binding;
			return RuntimeHotkeyParser.TryParse(bindingText, out binding, out normalizedBinding);
		}

		/// <summary>
		///     <para xml:lang="en">Creates the canonical runtime binding for a Godot input action.</para>
		///     <para xml:lang="zh-CN">为 Godot 输入动作创建规范化运行时绑定。</para>
		/// </summary>
		/// <param name="actionName">
		///     <para xml:lang="en">The input action name, such as <c>accept</c> or <c>view_map</c>.</para>
		///     <para xml:lang="zh-CN">输入动作名称，例如 <c>accept</c> 或 <c>view_map</c>。</para>
		/// </param>
		public static string ActionBinding(string actionName)
		{
			return RuntimeHotkeyParser.ActionBinding(actionName);
		}

		/// <summary>
		///     <para xml:lang="en">Normalizes a binding, returning <paramref name="fallback" /> if parsing fails.</para>
		///     <para xml:lang="zh-CN">规范化绑定；解析失败时返回 <paramref name="fallback" />。</para>
		/// </summary>
		/// <param name="bindingText">
		///     <para xml:lang="en">The binding text to normalize.</para>
		///     <para xml:lang="zh-CN">要规范化的绑定文本。</para>
		/// </param>
		/// <param name="fallback">
		///     <para xml:lang="en">The value returned when parsing fails.</para>
		///     <para xml:lang="zh-CN">解析失败时返回的值。</para>
		/// </param>
		public static string NormalizeOrDefault(string? bindingText, string fallback)
		{
			return RuntimeHotkeyParser.NormalizeOrDefault(bindingText, fallback);
		}

		/// <summary>
		///     <para xml:lang="en">Registers one runtime hotkey from a persisted binding.</para>
		///     <para xml:lang="zh-CN">从一个持久化绑定注册运行时热键。</para>
		/// </summary>
		/// <param name="bindingText">
		///     <para xml:lang="en">The persisted binding to parse.</para>
		///     <para xml:lang="zh-CN">要解析的持久化绑定。</para>
		/// </param>
		/// <param name="callback">
		///     <para xml:lang="en">The callback invoked when the hotkey matches.</para>
		///     <para xml:lang="zh-CN">热键匹配时调用的回调。</para>
		/// </param>
		/// <param name="options">
		///     <para xml:lang="en">Optional routing and presentation settings.</para>
		///     <para xml:lang="zh-CN">可选的路由与显示设置。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A handle for rebinding or unregistering the hotkey.</para>
		///     <para xml:lang="zh-CN">用于重新绑定或注销热键的句柄。</para>
		/// </returns>
		/// <exception cref="T:System.FormatException">
		///     <para xml:lang="en">Thrown when <paramref name="bindingText" /> is invalid.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="bindingText" /> 无效时引发。</para>
		/// </exception>
		public static IRuntimeHotkeyHandle Register(string bindingText, Action callback, RuntimeHotkeyOptions? options = null)
		{
			return Register(new <>z__ReadOnlySingleElementList<string>(bindingText), callback, options);
		}

		/// <summary>
		///     <para xml:lang="en">Registers one runtime hotkey with multiple persisted bindings.</para>
		///     <para xml:lang="zh-CN">使用多个持久化绑定注册一个运行时热键。</para>
		/// </summary>
		/// <param name="bindingTexts">
		///     <para xml:lang="en">The persisted bindings to parse.</para>
		///     <para xml:lang="zh-CN">要解析的持久化绑定。</para>
		/// </param>
		/// <param name="callback">
		///     <para xml:lang="en">The callback invoked when any binding matches.</para>
		///     <para xml:lang="zh-CN">任一绑定匹配时调用的回调。</para>
		/// </param>
		/// <param name="options">
		///     <para xml:lang="en">Optional routing and presentation settings.</para>
		///     <para xml:lang="zh-CN">可选的路由与显示设置。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A handle for rebinding or unregistering the hotkey.</para>
		///     <para xml:lang="zh-CN">用于重新绑定或注销热键的句柄。</para>
		/// </returns>
		/// <exception cref="T:System.FormatException">
		///     <para xml:lang="en">Thrown when any binding is invalid or no binding is provided.</para>
		///     <para xml:lang="zh-CN">当任一绑定无效或未提供任何绑定时引发。</para>
		/// </exception>
		public static IRuntimeHotkeyHandle Register(IEnumerable<string> bindingTexts, Action callback, RuntimeHotkeyOptions? options = null)
		{
			ArgumentNullException.ThrowIfNull(bindingTexts, "bindingTexts");
			ArgumentNullException.ThrowIfNull(callback, "callback");
			Initialize();
			List<RuntimeHotkeyBinding> list = ParseBindings(bindingTexts);
			if (list.Count == 0)
			{
				throw new FormatException("Runtime hotkey registration requires at least one valid binding.");
			}
			using (SyncRoot.EnterScope())
			{
				EnsureRouterAttached((Node?)(object)NGame.Instance);
				if (_router == null)
				{
					throw new InvalidOperationException("Runtime hotkey router is not available.");
				}
				RuntimeHotkeyHandle result = _router.Register(list, callback, options);
				RitsuLibFramework.Logger.Info("[RuntimeHotkey] Registered '" + string.Join("', '", list.Select((RuntimeHotkeyBinding b) => b.CanonicalString)) + "'" + FormatDebugName(options), 1);
				return result;
			}
		}

		private static List<RuntimeHotkeyBinding> ParseBindings(IEnumerable<string> bindingTexts)
		{
			List<RuntimeHotkeyBinding> list = new List<RuntimeHotkeyBinding>();
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			foreach (string bindingText in bindingTexts)
			{
				if (!RuntimeHotkeyParser.TryParse(bindingText, out RuntimeHotkeyBinding binding, out string normalized))
				{
					throw new FormatException("Invalid runtime hotkey binding '" + bindingText + "'.");
				}
				if (hashSet.Add(normalized))
				{
					list.Add(binding);
				}
			}
			return list;
		}

		private static void EnsureRouterAttached(Node? gameNode)
		{
			if ((_router == null || !GodotObject.IsInstanceValid((GodotObject)(object)_router)) && gameNode != null)
			{
				RuntimeHotkeyRouterNode runtimeHotkeyRouterNode = new RuntimeHotkeyRouterNode();
				((Node)runtimeHotkeyRouterNode).Name = StringName.op_Implicit("RitsuRuntimeHotkeyRouter");
				_router = runtimeHotkeyRouterNode;
				gameNode.AddChild((Node)(object)_router, false, (InternalMode)0);
			}
		}

		private static string FormatDebugName(RuntimeHotkeyOptions? options)
		{
			if (!string.IsNullOrWhiteSpace(options?.DebugName))
			{
				return " for " + options.DebugName;
			}
			return string.Empty;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Represents fixed or dynamically resolved runtime hotkey metadata text.</para>
	///     <para xml:lang="zh-CN">表示固定或动态解析的运行时热键元数据文本。</para>
	/// </summary>
	public abstract class RuntimeHotkeyText
	{
		private sealed class LiteralRuntimeHotkeyText(string text) : RuntimeHotkeyText
		{
			public override string Resolve()
			{
				return text;
			}
		}

		private sealed class DynamicRuntimeHotkeyText(Func<string> resolver) : RuntimeHotkeyText
		{
			public override string Resolve()
			{
				return resolver();
			}
		}

		/// <summary>
		///     <para xml:lang="en">Resolves the text for the current locale and runtime state.</para>
		///     <para xml:lang="zh-CN">根据当前区域设置与运行时状态解析文本。</para>
		/// </summary>
		public abstract string Resolve();

		/// <summary>
		///     <para xml:lang="en">Creates fixed text.</para>
		///     <para xml:lang="zh-CN">创建固定文本。</para>
		/// </summary>
		public static RuntimeHotkeyText Literal(string text)
		{
			return new LiteralRuntimeHotkeyText(text);
		}

		/// <summary>
		///     <para xml:lang="en">Creates text that is resolved each time the metadata is read.</para>
		///     <para xml:lang="zh-CN">创建每次读取元数据时动态解析的文本。</para>
		/// </summary>
		public static RuntimeHotkeyText Dynamic(Func<string> resolver)
		{
			ArgumentNullException.ThrowIfNull(resolver, "resolver");
			return new DynamicRuntimeHotkeyText(resolver);
		}

		/// <summary>
		///     <para xml:lang="en">Wraps a fixed string.</para>
		///     <para xml:lang="zh-CN">包装固定字符串。</para>
		/// </summary>
		public static implicit operator RuntimeHotkeyText(string text)
		{
			return Literal(text);
		}

		/// <summary>
		///     <para xml:lang="en">Wraps deferred mod settings text.</para>
		///     <para xml:lang="zh-CN">包装延迟解析的模组设置文本。</para>
		/// </summary>
		public static implicit operator RuntimeHotkeyText(ModSettingsText text)
		{
			ArgumentNullException.ThrowIfNull(text, "text");
			return Dynamic(text.Resolve);
		}

		/// <summary>
		///     <para xml:lang="en">Wraps a deferred string resolver.</para>
		///     <para xml:lang="zh-CN">包装延迟执行的字符串解析器。</para>
		/// </summary>
		public static implicit operator RuntimeHotkeyText(Func<string> resolver)
		{
			return Dynamic(resolver);
		}
	}
	internal sealed record RitsuSteamInputActionDescriptor(string InputActionName, string SteamActionId, RuntimeHotkeyText DisplayName, RuntimeHotkeyText? Description, string? RegistrationId);
	/// <summary>
	///     <para xml:lang="en">Registers optional Steam Input actions for runtime hotkeys.</para>
	///     <para xml:lang="zh-CN">为运行时热键注册可选的 Steam Input 动作。</para>
	/// </summary>
	public static class RitsuSteamInputActionRegistry
	{
		private sealed record Registration(string InputActionName, string SteamActionId, RuntimeHotkeyText DisplayName, RuntimeHotkeyText? Description, string? RegistrationId)
		{
			public RitsuSteamInputActionDescriptor ToDescriptor()
			{
				return new RitsuSteamInputActionDescriptor(InputActionName, SteamActionId, DisplayName, Description, RegistrationId);
			}
		}

		private sealed class RegistrationHandle(string actionName) : IDisposable
		{
			private string? _actionName = actionName;

			public void Dispose()
			{
				string text = Interlocked.Exchange(ref _actionName, null);
				if (text != null)
				{
					Unregister(text);
				}
			}
		}

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, Registration> Registrations = new Dictionary<string, Registration>(StringComparer.Ordinal);

		private static readonly Dictionary<string, int> ReferenceCounts = new Dictionary<string, int>(StringComparer.Ordinal);

		internal static event Action? ActionsChanged;

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a Godot input action for exposure as a Steam Input digital action when Steam is available.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册一个 Godot 输入动作，以便在 Steam 可用时将其公开为 Steam Input 数字动作。
		///     </para>
		/// </summary>
		public static IDisposable RegisterAction(string actionName, RuntimeHotkeyText displayName, RuntimeHotkeyText? description = null, string? registrationId = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(actionName, "actionName");
			ArgumentNullException.ThrowIfNull(displayName, "displayName");
			string text = actionName.Trim();
			using (SyncRoot.EnterScope())
			{
				if (Registrations.TryGetValue(text, out Registration _))
				{
					ReferenceCounts[text]++;
					return new RegistrationHandle(text);
				}
				string steamActionId = BuildSteamActionId(text);
				if (Registrations.Values.Any((Registration existing) => string.Equals(existing.SteamActionId, steamActionId, StringComparison.Ordinal)))
				{
					throw new InvalidOperationException("Steam Input action id collision for '" + text + "'.");
				}
				Registrations[text] = new Registration(text, steamActionId, displayName, description, registrationId);
				ReferenceCounts[text] = 1;
			}
			ActionsChanged?.Invoke();
			return new RegistrationHandle(text);
		}

		internal static IReadOnlyList<RitsuSteamInputActionDescriptor> GetActions()
		{
			using (SyncRoot.EnterScope())
			{
				List<RitsuSteamInputActionDescriptor> list = new List<RitsuSteamInputActionDescriptor>();
				list.AddRange(Registrations.Values.Select((Registration registration) => registration.ToDescriptor()).OrderBy<RitsuSteamInputActionDescriptor, string>((RitsuSteamInputActionDescriptor action) => action.SteamActionId, StringComparer.Ordinal));
				return new <>z__ReadOnlyList<RitsuSteamInputActionDescriptor>(list);
			}
		}

		private static void Unregister(string actionName)
		{
			bool flag;
			using (SyncRoot.EnterScope())
			{
				if (!ReferenceCounts.TryGetValue(actionName, out var value))
				{
					return;
				}
				if (value > 1)
				{
					ReferenceCounts[actionName] = value - 1;
					return;
				}
				ReferenceCounts.Remove(actionName);
				Registrations.Remove(actionName);
				flag = true;
			}
			if (flag)
			{
				ActionsChanged?.Invoke();
			}
		}

		private static string BuildSteamActionId(string actionName)
		{
			StringBuilder stringBuilder = new StringBuilder();
			foreach (char c in actionName)
			{
				if (char.IsAsciiLetterOrDigit(c))
				{
					stringBuilder.Append(char.ToLowerInvariant(c));
				}
				else
				{
					stringBuilder.Append('_');
				}
			}
			string text = string.Join('_', stringBuilder.ToString().Split('_', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries));
			if (string.Equals(text, actionName, StringComparison.Ordinal))
			{
				return "ritsu_" + text;
			}
			if (text.Length == 0)
			{
				text = "action";
			}
			if (text.Length > 32)
			{
				text = text.Substring(0, 32).TrimEnd('_');
			}
			ulong value = XxHash64.HashToUInt64((ReadOnlySpan<byte>)Encoding.UTF8.GetBytes(actionName), 0L);
			IFormatProvider invariantCulture = CultureInfo.InvariantCulture;
			DefaultInterpolatedStringHandler handler = new DefaultInterpolatedStringHandler(7, 2, invariantCulture);
			handler.AppendLiteral("ritsu_");
			handler.AppendFormatted(text);
			handler.AppendLiteral("_");
			handler.AppendFormatted(value, "x16");
			return string.Create(invariantCulture, ref handler);
		}
	}
	internal static class RitsuSteamInputBackend
	{
		private static readonly Dictionary<string, object> ActionHandles;

		private static readonly Dictionary<string, string> PressedActions;

		private static bool _handleCacheDirty;

		private static bool _disabled;

		private static int _unavailableLogged;

		static RitsuSteamInputBackend()
		{
			ActionHandles = new Dictionary<string, object>(StringComparer.Ordinal);
			PressedActions = new Dictionary<string, string>(StringComparer.Ordinal);
			_handleCacheDirty = true;
			RitsuSteamInputActionRegistry.ActionsChanged += delegate
			{
				_handleCacheDirty = true;
			};
		}

		public static void Process()
		{
			if (_disabled || !RitsuSteamInputManifestInstaller.IsManifestInstalled || !RitsuSteamInputInterop.IsSteamAvailable)
			{
				ReleaseAll();
				return;
			}
			IReadOnlyList<RitsuSteamInputActionDescriptor> actions = RitsuSteamInputActionRegistry.GetActions();
			ReleaseMissingActions(actions);
			if (actions.Count == 0)
			{
				ReleaseAll();
				return;
			}
			try
			{
				if (!RitsuSteamInputInterop.TryGetFirstController(out object controllerHandle))
				{
					ReleaseAll();
					return;
				}
				EnsureActionHandles(actions);
				foreach (RitsuSteamInputActionDescriptor item in actions)
				{
					if (!ActionHandles.TryGetValue(item.SteamActionId, out object value))
					{
						continue;
					}
					bool flag = RitsuSteamInputInterop.IsDigitalActionPressed(controllerHandle, value);
					bool flag2 = PressedActions.ContainsKey(item.SteamActionId);
					if (flag != flag2)
					{
						if (flag)
						{
							PressedActions[item.SteamActionId] = item.InputActionName;
						}
						else
						{
							PressedActions.Remove(item.SteamActionId);
						}
						EmitAction(item.InputActionName, flag);
					}
				}
			}
			catch (Exception ex)
			{
				_disabled = true;
				ReleaseAll();
				if (Interlocked.Exchange(ref _unavailableLogged, 1) == 0)
				{
					RitsuLibFramework.Logger.Warn("[SteamInput] Optional backend disabled for this session; falling back to normal input. " + ex.Message, 1);
				}
			}
		}

		private static void EnsureActionHandles(IReadOnlyList<RitsuSteamInputActionDescriptor> actions)
		{
			if (!_handleCacheDirty)
			{
				return;
			}
			ActionHandles.Clear();
			foreach (RitsuSteamInputActionDescriptor action in actions)
			{
				if (RitsuSteamInputInterop.TryGetDigitalActionHandle(action.SteamActionId, out object actionHandle))
				{
					ActionHandles[action.SteamActionId] = actionHandle;
				}
			}
			_handleCacheDirty = false;
		}

		private static void ReleaseAll()
		{
			string[] array = PressedActions.Values.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				EmitAction(array[i], pressed: false);
			}
			PressedActions.Clear();
		}

		private static void ReleaseMissingActions(IReadOnlyList<RitsuSteamInputActionDescriptor> actions)
		{
			if (PressedActions.Count == 0)
			{
				return;
			}
			HashSet<string> hashSet = actions.Select((RitsuSteamInputActionDescriptor action) => action.SteamActionId).ToHashSet<string>(StringComparer.Ordinal);
			KeyValuePair<string, string>[] array = PressedActions.ToArray();
			for (int num = 0; num < array.Length; num++)
			{
				KeyValuePair<string, string> keyValuePair = array[num];
				var (text3, inputActionName) = keyValuePair;
				if (!hashSet.Contains(text3))
				{
					EmitAction(inputActionName, pressed: false);
					PressedActions.Remove(text3);
				}
			}
		}

		private static void EmitAction(string inputActionName, bool pressed)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Expected O, but got Unknown
			//IL_0008: Unknown result type (might be due to invalid IL or missing references)
			//IL_0012: Expected O, but got Unknown
			InputEventAction val = new InputEventAction();
			try
			{
				val.Action = new StringName(inputActionName);
				val.Pressed = pressed;
				Input.ParseInputEvent((InputEvent)(object)val);
			}
			finally
			{
				((IDisposable)val)?.Dispose();
			}
		}
	}
	internal static class RitsuSteamInputInterop
	{
		private const int MaxControllers = 16;

		private static readonly Lazy<Type?> SteamInputType = new Lazy<Type>(() => Type.GetType("Steamworks.SteamInput, Steamworks.NET", throwOnError: false));

		private static readonly Lazy<Type?> InputHandleType = new Lazy<Type>(() => Type.GetType("Steamworks.InputHandle_t, Steamworks.NET", throwOnError: false));

		private static readonly Lazy<Type?> InputDigitalActionHandleType = new Lazy<Type>(() => Type.GetType("Steamworks.InputDigitalActionHandle_t, Steamworks.NET", throwOnError: false));

		public static bool IsSteamAvailable
		{
			get
			{
				if (SteamInitializer.Initialized)
				{
					return SteamInputType.Value != null;
				}
				return false;
			}
		}

		public static bool SetInputActionManifestFilePath(string path)
		{
			return InvokeStatic<bool>("SetInputActionManifestFilePath", new object[1] { path });
		}

		public static bool TryGetFirstController(out object controllerHandle)
		{
			controllerHandle = null;
			if (!IsSteamAvailable || InputHandleType.Value == null)
			{
				return false;
			}
			Array array = Array.CreateInstance(InputHandleType.Value, 16);
			if (InvokeStatic<int>("GetConnectedControllers", new object[1] { array }) <= 0)
			{
				return false;
			}
			controllerHandle = array.GetValue(0);
			return !IsDefaultStruct(controllerHandle);
		}

		public static bool TryGetDigitalActionHandle(string actionId, out object actionHandle)
		{
			actionHandle = null;
			if (!IsSteamAvailable)
			{
				return false;
			}
			actionHandle = InvokeStatic<object>("GetDigitalActionHandle", new object[1] { actionId });
			if (actionHandle != null)
			{
				return !IsDefaultStruct(actionHandle);
			}
			return false;
		}

		public static bool IsDigitalActionPressed(object controllerHandle, object actionHandle)
		{
			object obj = InvokeStatic<object>("GetDigitalActionData", new object[2] { controllerHandle, actionHandle });
			if (obj == null)
			{
				return false;
			}
			object obj2 = obj.GetType().GetField("bState", BindingFlags.Instance | BindingFlags.Public)?.GetValue(obj);
			if (!(obj2 is bool result))
			{
				if (!(obj2 is byte b))
				{
					if (obj2 is int num)
					{
						return num != 0;
					}
					return false;
				}
				return b != 0;
			}
			return result;
		}

		private static T InvokeStatic<T>(string methodName, object?[] args)
		{
			MethodInfo methodInfo = ResolveMethod(methodName, args.Length);
			if (methodInfo == null)
			{
				return default(T);
			}
			try
			{
				return (methodInfo.Invoke(null, args) is T val) ? val : default(T);
			}
			catch (TargetInvocationException ex) when (ex.InnerException != null)
			{
				throw ex.InnerException;
			}
		}

		private static MethodInfo? ResolveMethod(string methodName, int argumentCount)
		{
			return SteamInputType.Value?.GetMethods(BindingFlags.Static | BindingFlags.Public).FirstOrDefault((MethodInfo method) => method.Name == methodName && method.GetParameters().Length == argumentCount);
		}

		private static bool IsDefaultStruct(object value)
		{
			Type type = value.GetType();
			if (!type.IsValueType)
			{
				return value == null;
			}
			object objB = Activator.CreateInstance(type);
			return object.Equals(value, objB);
		}
	}
	internal static class RitsuSteamInputManifestInstaller
	{
		private readonly record struct VdfBlock(string Name, int NameStart, int OpenBrace, int CloseBrace);

		private const string OriginalManifestFileName = "game_actions_2868840.vdf";

		private const string GeneratedManifestFileName = "steam_input_manifest.ritsulib.vdf";

		private static int _installAttempted;

		private static int _actionsChangedAfterInstallLogged;

		public static bool IsManifestInstalled { get; private set; }

		public static string? GeneratedManifestPath { get; private set; }

		static RitsuSteamInputManifestInstaller()
		{
			RitsuSteamInputActionRegistry.ActionsChanged += OnActionsChanged;
		}

		public static void InstallBeforeSteamInputInit()
		{
			if (Interlocked.Exchange(ref _installAttempted, 1) == 1)
			{
				return;
			}
			if (!RitsuSteamInputInterop.IsSteamAvailable)
			{
				RitsuLibFramework.Logger.Debug("[SteamInput] Steam is not available; optional RitsuLib actions are disabled.", 1);
				return;
			}
			IReadOnlyList<RitsuSteamInputActionDescriptor> actions = RitsuSteamInputActionRegistry.GetActions();
			if (actions.Count == 0)
			{
				RitsuLibFramework.Logger.Debug("[SteamInput] No RitsuLib actions requested; using the game manifest.", 1);
				return;
			}
			try
			{
				if (!TryFindOriginalManifest(out string path))
				{
					RitsuLibFramework.Logger.Warn("[SteamInput] Original game action manifest was not found; optional RitsuLib Steam Input actions are disabled.", 1);
					return;
				}
				if (!TryMerge(File.ReadAllText(path, Encoding.UTF8), actions, out string mergedText))
				{
					RitsuLibFramework.Logger.Warn("[SteamInput] Original manifest shape was not recognized; optional RitsuLib Steam Input actions are disabled.", 1);
					return;
				}
				string text = ResolveGeneratedManifestPath();
				Directory.CreateDirectory(Path.GetDirectoryName(text));
				File.WriteAllText(text, mergedText.ReplaceLineEndings("\r\n"), new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
				if (!RitsuSteamInputInterop.SetInputActionManifestFilePath(Path.GetFullPath(text)))
				{
					RitsuLibFramework.Logger.Warn("[SteamInput] Steam rejected the generated RitsuLib action manifest.", 1);
					return;
				}
				GeneratedManifestPath = text;
				IsManifestInstalled = true;
				RitsuLibFramework.Logger.Info($"[SteamInput] Installed optional RitsuLib action manifest: {text} ({actions.Count} action(s)).", 1);
			}
			catch (Exception ex)
			{
				IsManifestInstalled = false;
				RitsuLibFramework.Logger.Warn("[SteamInput] Optional manifest install failed; falling back to normal input. " + ex.Message, 1);
			}
		}

		private static bool TryMerge(string originalText, IReadOnlyList<RitsuSteamInputActionDescriptor> actions, out string mergedText)
		{
			mergedText = originalText;
			if (!TryFindNamedBlock(mergedText, "actions", 0, mergedText.Length, out var block) || !TryFindNamedBlock(mergedText, "Controls", block.OpenBrace, block.CloseBrace, out var block2) || !TryFindNamedBlock(mergedText, "Button", block2.OpenBrace, block2.CloseBrace, out var block3))
			{
				return false;
			}
			string text = BuildActionLines(actions, mergedText);
			if (text.Length > 0)
			{
				mergedText = mergedText.Insert(block3.CloseBrace, text);
			}
			if (TryFindNamedBlock(mergedText, "localization", 0, mergedText.Length, out var block4))
			{
				foreach (VdfBlock item in from vdfBlock in FindChildBlocks(mergedText, block4.OpenBrace, block4.CloseBrace)
					orderby vdfBlock.CloseBrace descending
					select vdfBlock)
				{
					string text2 = BuildLocalizationLines(actions, mergedText, item.Name);
					if (text2.Length > 0)
					{
						mergedText = mergedText.Insert(item.CloseBrace, text2);
					}
				}
			}
			else
			{
				string value = BuildLocalizationBlock(actions);
				if (TryFindLastTopLevelCloseBrace(mergedText, out var closeBrace))
				{
					mergedText = mergedText.Insert(closeBrace, value);
				}
			}
			return true;
		}

		private static string BuildActionLines(IReadOnlyList<RitsuSteamInputActionDescriptor> actions, string text)
		{
			StringBuilder stringBuilder = new StringBuilder();
			foreach (RitsuSteamInputActionDescriptor action in actions)
			{
				if (!text.Contains("\"" + action.SteamActionId + "\"", StringComparison.Ordinal))
				{
					stringBuilder.Append('\t').Append('\t').Append('\t')
						.Append('"')
						.Append(EscapeVdf(action.SteamActionId))
						.Append('"')
						.Append('\t')
						.Append('"')
						.Append(EscapeVdf(LocalizationReference(action)))
						.Append('"')
						.AppendLine();
				}
			}
			return stringBuilder.ToString();
		}

		private static string BuildLocalizationLines(IReadOnlyList<RitsuSteamInputActionDescriptor> actions, string text, string language)
		{
			StringBuilder stringBuilder = new StringBuilder();
			foreach (RitsuSteamInputActionDescriptor action in actions)
			{
				string text2 = LocalizationKey(action);
				if (!text.Contains("\"" + text2 + "\"", StringComparison.Ordinal))
				{
					stringBuilder.Append('\t').Append('\t').Append('"')
						.Append(EscapeVdf(text2))
						.Append('"')
						.Append('\t')
						.Append('"')
						.Append(EscapeVdf(ResolveDisplayName(action)))
						.Append('"')
						.AppendLine();
				}
			}
			return stringBuilder.ToString();
		}

		private static string BuildLocalizationBlock(IReadOnlyList<RitsuSteamInputActionDescriptor> actions)
		{
			StringBuilder stringBuilder = new StringBuilder().AppendLine().Append('\t').AppendLine("\"localization\"")
				.Append('\t')
				.AppendLine("{")
				.Append('\t')
				.Append('\t')
				.AppendLine("\"english\"")
				.Append('\t')
				.Append('\t')
				.AppendLine("{");
			foreach (RitsuSteamInputActionDescriptor action in actions)
			{
				stringBuilder.Append('\t').Append('\t').Append('\t')
					.Append('"')
					.Append(EscapeVdf(LocalizationKey(action)))
					.Append('"')
					.Append('\t')
					.Append('"')
					.Append(EscapeVdf(ResolveDisplayName(action)))
					.Append('"')
					.AppendLine();
			}
			return stringBuilder.Append('\t').Append('\t').AppendLine("}")
				.Append('\t')
				.AppendLine("}")
				.ToString();
		}

		private static string LocalizationReference(RitsuSteamInputActionDescriptor action)
		{
			return "#" + LocalizationKey(action);
		}

		private static string LocalizationKey(RitsuSteamInputActionDescriptor action)
		{
			return "RitsuLib_" + action.SteamActionId;
		}

		private static string ResolveDisplayName(RitsuSteamInputActionDescriptor action)
		{
			try
			{
				string text = action.DisplayName.Resolve();
				return string.IsNullOrWhiteSpace(text) ? action.InputActionName : text;
			}
			catch
			{
				return action.InputActionName;
			}
		}

		private static bool TryFindOriginalManifest(out string path)
		{
			foreach (string item in EnumerateSearchRoots())
			{
				foreach (string item2 in WalkUp(item, 6))
				{
					string text = Path.Combine(item2, "controller_config", "game_actions_2868840.vdf");
					if (File.Exists(text))
					{
						path = text;
						return true;
					}
				}
			}
			path = string.Empty;
			return false;
		}

		private static IEnumerable<string> EnumerateSearchRoots()
		{
			yield return AppContext.BaseDirectory;
			string directoryName = Path.GetDirectoryName(typeof(SteamControllerInputStrategy).Assembly.Location);
			if (!string.IsNullOrWhiteSpace(directoryName))
			{
				yield return directoryName;
			}
			string currentDirectory = Directory.GetCurrentDirectory();
			if (!string.IsNullOrWhiteSpace(currentDirectory))
			{
				yield return currentDirectory;
			}
		}

		private static IEnumerable<string> WalkUp(string root, int maxDepth)
		{
			DirectoryInfo directory = (Directory.Exists(root) ? new DirectoryInfo(root) : new DirectoryInfo(Path.GetDirectoryName(root) ?? root));
			int i = 0;
			while (directory != null && i <= maxDepth)
			{
				yield return directory.FullName;
				directory = directory.Parent;
				i++;
			}
		}

		private static string ResolveGeneratedManifestPath()
		{
			return Path.Combine(RitsuLibDataPaths.EnsureTemporaryDirectory(), "steam_input_manifest.ritsulib.vdf");
		}

		private static bool TryFindNamedBlock(string text, string name, int start, int end, out VdfBlock block)
		{
			string text2 = "\"" + name + "\"";
			int num = text.IndexOf(text2, start, StringComparison.Ordinal);
			while (num >= 0 && num < end)
			{
				int num2 = text.IndexOf('{', num + text2.Length);
				if (num2 < 0 || num2 >= end)
				{
					break;
				}
				int num3 = FindMatchingBrace(text, num2);
				if (num3 >= 0 && num3 <= end)
				{
					block = new VdfBlock(name, num, num2, num3);
					return true;
				}
				num = text.IndexOf(text2, num + text2.Length, StringComparison.Ordinal);
			}
			block = default(VdfBlock);
			return false;
		}

		private static List<VdfBlock> FindChildBlocks(string text, int openBrace, int closeBrace)
		{
			List<VdfBlock> list = new List<VdfBlock>();
			int num = openBrace + 1;
			while (num < closeBrace)
			{
				int num2 = text.IndexOf('"', num);
				if (num2 < 0 || num2 >= closeBrace)
				{
					break;
				}
				int num3 = text.IndexOf('"', num2 + 1);
				if (num3 < 0 || num3 >= closeBrace)
				{
					break;
				}
				int num4 = text.IndexOf('{', num3 + 1);
				if (num4 < 0 || num4 >= closeBrace)
				{
					break;
				}
				int num5 = FindMatchingBrace(text, num4);
				if (num5 < 0 || num5 > closeBrace)
				{
					break;
				}
				int num6 = num2 + 1;
				list.Add(new VdfBlock(text.Substring(num6, num3 - num6), num2, num4, num5));
				num = num5 + 1;
			}
			return list;
		}

		private static int FindMatchingBrace(string text, int openBrace)
		{
			int num = 0;
			bool flag = false;
			for (int i = openBrace; i < text.Length; i++)
			{
				char c = text[i];
				if (c == '"' && (i == 0 || text[i - 1] != '\\'))
				{
					flag = !flag;
				}
				if (flag)
				{
					continue;
				}
				switch (c)
				{
				case '{':
					num++;
					break;
				case '}':
					if (--num == 0)
					{
						return i;
					}
					break;
				}
			}
			return -1;
		}

		private static bool TryFindLastTopLevelCloseBrace(string text, out int closeBrace)
		{
			closeBrace = text.LastIndexOf('}');
			return closeBrace >= 0;
		}

		private static string EscapeVdf(string value)
		{
			return value.Replace("\\", "\\\\", StringComparison.Ordinal).Replace("\"", "\\\"", StringComparison.Ordinal);
		}

		private static void OnActionsChanged()
		{
			if (IsManifestInstalled && Interlocked.Exchange(ref _actionsChangedAfterInstallLogged, 1) != 1)
			{
				RitsuLibFramework.Logger.Warn("[SteamInput] RitsuLib Steam Input actions changed after manifest install; restart the game for Steam Overlay to see new actions.", 1);
			}
		}
	}
