namespace STS2RitsuLib.RunRngs
{
	/// <summary>
	///     <para xml:lang="en">
	///         Provides persistent independent random-number streams for mods, scoped either to a run or to a player
	///         within that run.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为模组提供可持久化的独立随机数流，作用域可以是整局游戏，也可以是该局中的单个玩家。
	///     </para>
	/// </summary>
	public static class ModRunRngRegistry
	{
		private sealed class RuntimeState
		{
			private readonly Dictionary<PlayerStreamKey, Rng> _playerRngs = new Dictionary<PlayerStreamKey, Rng>();

			private readonly Dictionary<StreamKey, Rng> _runRngs = new Dictionary<StreamKey, Rng>();

			private readonly Lock _syncRoot = new Lock();

			public bool IsEmpty
			{
				get
				{
					using (_syncRoot.EnterScope())
					{
						return _runRngs.Count == 0 && _playerRngs.Count == 0;
					}
				}
			}

			public Rng GetOrCreate(RunState runState, string modId, string streamId)
			{
				StreamKey key = new StreamKey(modId, streamId);
				using (_syncRoot.EnterScope())
				{
					if (_runRngs.TryGetValue(key, out Rng value))
					{
						return value;
					}
					value = CreateRunRng(runState, key);
					_runRngs[key] = value;
					return value;
				}
			}

			public Rng GetOrCreate(Player player, string modId, string streamId)
			{
				PlayerStreamKey key = new PlayerStreamKey(player.NetId, modId, streamId);
				using (_syncRoot.EnterScope())
				{
					if (_playerRngs.TryGetValue(key, out Rng value))
					{
						return value;
					}
					value = CreatePlayerRng(player, key);
					_playerRngs[key] = value;
					return value;
				}
			}

			public void CopyStateTo(ModRunRngState state)
			{
				using (_syncRoot.EnterScope())
				{
					Rng value;
					foreach (KeyValuePair<StreamKey, Rng> runRng in _runRngs)
					{
						runRng.Deconstruct(out var key, out value);
						StreamKey streamKey = key;
						Rng rng = value;
						state.SetRunCounter(streamKey.ModId, streamKey.StreamId, rng.GetCounter());
						state.SetRunRngState(streamKey.ModId, streamKey.StreamId, ModRunRngSnapshot.From(rng));
					}
					foreach (KeyValuePair<PlayerStreamKey, Rng> playerRng in _playerRngs)
					{
						playerRng.Deconstruct(out var key2, out value);
						PlayerStreamKey playerStreamKey = key2;
						Rng rng2 = value;
						state.SetPlayerCounter(playerStreamKey.NetId, playerStreamKey.ModId, playerStreamKey.StreamId, rng2.GetCounter());
						state.SetPlayerRngState(playerStreamKey.NetId, playerStreamKey.ModId, playerStreamKey.StreamId, ModRunRngSnapshot.From(rng2));
					}
				}
			}

			private static Rng CreateRunRng(RunState runState, StreamKey key)
			{
				//IL_0080: Unknown result type (might be due to invalid IL or missing references)
				//IL_0086: Expected O, but got Unknown
				//IL_00ae: Unknown result type (might be due to invalid IL or missing references)
				//IL_00ba: Expected O, but got Unknown
				string text = $"{"ritsulib.mod_run_rng"}/run/{key.ModId}/{key.StreamId}";
				bool flag = SavedData.TryGet(runState, out ModRunRngState value);
				if (flag && value.TryGetRunRngState(key.ModId, key.StreamId, out ModRunRngSnapshot state))
				{
					return new Rng(state.ToSerializable());
				}
				int counter = (flag ? value.GetRunCounter(key.ModId, key.StreamId) : 0);
				return ModRunRngExtensions.FastForwarded(new Rng(runState.Rng.Seed, text), counter);
			}

			private static Rng CreatePlayerRng(Player player, PlayerStreamKey key)
			{
				//IL_009d: Unknown result type (might be due to invalid IL or missing references)
				//IL_00a3: Expected O, but got Unknown
				//IL_00d2: Unknown result type (might be due to invalid IL or missing references)
				//IL_00de: Expected O, but got Unknown
				string text = $"{"ritsulib.mod_run_rng"}/player/{key.ModId}/{key.StreamId}";
				ModRunRngState value = null;
				IRunState runState = player.RunState;
				RunState val = (RunState)(object)((runState is RunState) ? runState : null);
				bool flag = val != null && SavedData.TryGet(val, out value);
				if (flag && value.TryGetPlayerRngState(key.NetId, key.ModId, key.StreamId, out ModRunRngSnapshot state))
				{
					return new Rng(state.ToSerializable());
				}
				int counter = (flag ? value.GetPlayerCounter(key.NetId, key.ModId, key.StreamId) : 0);
				return ModRunRngExtensions.FastForwarded(new Rng(player.PlayerRng.Seed, text), counter);
			}
		}

		private readonly record struct StreamKey(string ModId, string StreamId);

		private readonly record struct PlayerStreamKey(ulong NetId, string ModId, string StreamId);

		private const string SaveKey = "mod_run_rng";

		private const string StreamSeedPrefix = "ritsulib.mod_run_rng";

		private static readonly RunSavedData<ModRunRngState> SavedData = RunSavedDataStore.For("com.ritsukage.sts2-RitsuLib").Register("mod_run_rng", () => new ModRunRngState(), new RunSavedDataOptions
		{
			WritePolicy = RunSavedDataWritePolicy.WhenNonDefault
		});

		private static readonly ConditionalWeakTable<RunState, RuntimeState> Runtimes = new ConditionalWeakTable<RunState, RuntimeState>();

		/// <summary>
		///     <para xml:lang="en">Gets a persistent independent RNG stream for the specified run, mod ID, and stream ID.</para>
		///     <para xml:lang="zh-CN">获取指定局内状态、模组 ID 和流 ID 的可持久化独立 RNG 流。</para>
		/// </summary>
		public static Rng Get(RunState runState, string modId, string streamId)
		{
			ArgumentNullException.ThrowIfNull(runState, "runState");
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(streamId, "streamId");
			return Runtimes.GetValue(runState, (RunState _) => new RuntimeState()).GetOrCreate(runState, modId, streamId);
		}

		/// <summary>
		///     <para xml:lang="en">Gets a persistent independent RNG stream scoped to <paramref name="player" /> within its run.</para>
		///     <para xml:lang="zh-CN">获取在 <paramref name="player" /> 所在局内以该玩家为作用域的可持久化独立 RNG 流。</para>
		/// </summary>
		public static Rng Get(Player player, string modId, string streamId)
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(streamId, "streamId");
			IRunState runState = player.RunState;
			RunState val = (RunState)(object)((runState is RunState) ? runState : null);
			if (val == null)
			{
				throw new InvalidOperationException("Player does not belong to a concrete RunState.");
			}
			return Runtimes.GetValue(val, (RunState _) => new RuntimeState()).GetOrCreate(player, modId, streamId);
		}

		internal static void SyncToSavedData(RunState runState)
		{
			if (Runtimes.TryGetValue(runState, out RuntimeState value) && !value.IsEmpty)
			{
				ModRunRngState modRunRngState = SavedData.Get(runState);
				value.CopyStateTo(modRunRngState);
				SavedData.Set(runState, modRunRngState);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Persisted counter and state data for mod RNG streams.</para>
	///     <para xml:lang="zh-CN">模组 RNG 流的持久化计数器与状态数据。</para>
	/// </summary>
	public sealed class ModRunRngState
	{
		/// <summary>
		///     <para xml:lang="en">Counter values grouped by mod ID and stream ID.</para>
		///     <para xml:lang="zh-CN">按模组 ID 和流 ID 分组的计数器值。</para>
		/// </summary>
		public Dictionary<string, Dictionary<string, int>> Counters { get; set; } = new Dictionary<string, Dictionary<string, int>>(StringComparer.OrdinalIgnoreCase);

		/// <summary>
		///     <para xml:lang="en">Player-scoped counter values grouped by network ID, mod ID, and stream ID.</para>
		///     <para xml:lang="zh-CN">按网络 ID、模组 ID 和流 ID 分组的玩家作用域计数器值。</para>
		/// </summary>
		public Dictionary<ulong, Dictionary<string, Dictionary<string, int>>> PlayerCounters { get; set; } = new Dictionary<ulong, Dictionary<string, Dictionary<string, int>>>();

		/// <summary>
		///     <para xml:lang="en">Complete RNG states grouped by mod ID and stream ID.</para>
		///     <para xml:lang="zh-CN">按模组 ID 和流 ID 分组的完整 RNG 状态。</para>
		/// </summary>
		public Dictionary<string, Dictionary<string, ModRunRngSnapshot>> RngStates { get; set; } = new Dictionary<string, Dictionary<string, ModRunRngSnapshot>>(StringComparer.OrdinalIgnoreCase);

		/// <summary>
		///     <para xml:lang="en">Player-scoped complete RNG states grouped by network ID, mod ID, and stream ID.</para>
		///     <para xml:lang="zh-CN">按网络 ID、模组 ID 和流 ID 分组的玩家作用域完整 RNG 状态。</para>
		/// </summary>
		public Dictionary<ulong, Dictionary<string, Dictionary<string, ModRunRngSnapshot>>> PlayerRngStates { get; set; } = new Dictionary<ulong, Dictionary<string, Dictionary<string, ModRunRngSnapshot>>>();

		internal int GetRunCounter(string modId, string streamId)
		{
			if (!Counters.TryGetValue(modId, out Dictionary<string, int> value) || !value.TryGetValue(streamId, out var value2) || value2 <= 0)
			{
				return 0;
			}
			return value2;
		}

		internal int GetPlayerCounter(ulong netId, string modId, string streamId)
		{
			if (!PlayerCounters.TryGetValue(netId, out Dictionary<string, Dictionary<string, int>> value) || !value.TryGetValue(modId, out var value2) || !value2.TryGetValue(streamId, out var value3) || value3 <= 0)
			{
				return 0;
			}
			return value3;
		}

		internal bool TryGetRunRngState(string modId, string streamId, out ModRunRngSnapshot state)
		{
			if (RngStates.TryGetValue(modId, out Dictionary<string, ModRunRngSnapshot> value) && value.TryGetValue(streamId, out var value2) && value2 != null && value2.IsValid)
			{
				state = value2;
				return true;
			}
			state = null;
			return false;
		}

		internal bool TryGetPlayerRngState(ulong netId, string modId, string streamId, out ModRunRngSnapshot state)
		{
			if (PlayerRngStates.TryGetValue(netId, out Dictionary<string, Dictionary<string, ModRunRngSnapshot>> value) && value.TryGetValue(modId, out var value2) && value2.TryGetValue(streamId, out var value3) && value3 != null && value3.IsValid)
			{
				state = value3;
				return true;
			}
			state = null;
			return false;
		}

		internal void SetRunCounter(string modId, string streamId, int counter)
		{
			if (!Counters.TryGetValue(modId, out Dictionary<string, int> value))
			{
				value = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
				Counters[modId] = value;
			}
			value[streamId] = Math.Max(0, counter);
		}

		internal void SetPlayerCounter(ulong netId, string modId, string streamId, int counter)
		{
			if (!PlayerCounters.TryGetValue(netId, out Dictionary<string, Dictionary<string, int>> value))
			{
				value = new Dictionary<string, Dictionary<string, int>>(StringComparer.OrdinalIgnoreCase);
				PlayerCounters[netId] = value;
			}
			if (!value.TryGetValue(modId, out var value2))
			{
				value2 = (value[modId] = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase));
			}
			value2[streamId] = Math.Max(0, counter);
		}

		internal void SetRunRngState(string modId, string streamId, ModRunRngSnapshot state)
		{
			if (!RngStates.TryGetValue(modId, out Dictionary<string, ModRunRngSnapshot> value))
			{
				value = new Dictionary<string, ModRunRngSnapshot>(StringComparer.OrdinalIgnoreCase);
				RngStates[modId] = value;
			}
			value[streamId] = state;
		}

		internal void SetPlayerRngState(ulong netId, string modId, string streamId, ModRunRngSnapshot state)
		{
			if (!PlayerRngStates.TryGetValue(netId, out Dictionary<string, Dictionary<string, ModRunRngSnapshot>> value))
			{
				value = new Dictionary<string, Dictionary<string, ModRunRngSnapshot>>(StringComparer.OrdinalIgnoreCase);
				PlayerRngStates[netId] = value;
			}
			if (!value.TryGetValue(modId, out var value2))
			{
				value2 = (value[modId] = new Dictionary<string, ModRunRngSnapshot>(StringComparer.OrdinalIgnoreCase));
			}
			value2[streamId] = state;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Serializable complete state of one mod RNG stream.</para>
	///     <para xml:lang="zh-CN">一个模组 RNG 流的可序列化完整状态。</para>
	/// </summary>
	public sealed class ModRunRngSnapshot
	{
		/// <summary>
		///     <para xml:lang="en">Gets or sets the number of values generated by the stream.</para>
		///     <para xml:lang="zh-CN">获取或设置该随机数流已生成的值数量。</para>
		/// </summary>
		public int Counter { get; set; }

		/// <summary>
		///     <para xml:lang="en">Gets or sets the first word of the generator state.</para>
		///     <para xml:lang="zh-CN">获取或设置生成器状态的第一个字。</para>
		/// </summary>
		public ulong State0 { get; set; }

		/// <summary>
		///     <para xml:lang="en">Gets or sets the second word of the generator state.</para>
		///     <para xml:lang="zh-CN">获取或设置生成器状态的第二个字。</para>
		/// </summary>
		public ulong State1 { get; set; }

		/// <summary>
		///     <para xml:lang="en">Gets or sets the third word of the generator state.</para>
		///     <para xml:lang="zh-CN">获取或设置生成器状态的第三个字。</para>
		/// </summary>
		public ulong State2 { get; set; }

		/// <summary>
		///     <para xml:lang="en">Gets or sets the fourth word of the generator state.</para>
		///     <para xml:lang="zh-CN">获取或设置生成器状态的第四个字。</para>
		/// </summary>
		public ulong State3 { get; set; }

		internal bool IsValid
		{
			get
			{
				if (Counter >= 0)
				{
					if (State0 == 0L && State1 == 0L && State2 == 0L)
					{
						return State3 != 0;
					}
					return true;
				}
				return false;
			}
		}

		internal static ModRunRngSnapshot From(Rng rng)
		{
			SerializableRng val = rng.ToSerializable();
			return new ModRunRngSnapshot
			{
				Counter = val.counter,
				State0 = val.state0,
				State1 = val.state1,
				State2 = val.state2,
				State3 = val.state3
			};
		}

		internal SerializableRng ToSerializable()
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			//IL_0035: Unknown result type (might be due to invalid IL or missing references)
			//IL_0042: Expected O, but got Unknown
			return new SerializableRng
			{
				counter = Counter,
				state0 = State0,
				state1 = State1,
				state2 = State2,
				state3 = State3
			};
		}
	}
	internal static class ModRunRngExtensions
	{
		public static int GetCounter(this Rng rng)
		{
			return rng.ToSerializable().counter;
		}

		public static Rng FastForwarded(this Rng rng, int counter)
		{
			for (int i = 0; i < counter; i++)
			{
				rng.NextUnsignedLong();
			}
			return rng;
		}
	}
}
namespace STS2RitsuLib.RunData
{
	/// <summary>
	///     <para xml:lang="en">Provides access to a saved-data slot shared by the whole run.</para>
	///     <para xml:lang="zh-CN">提供对整局游戏共享的保存数据槽位的访问。</para>
	/// </summary>
	public sealed class RunSavedData<T> where T : class, new()
	{
		private readonly RunSavedDataRunSlot<T> _slot;

		/// <summary>
		///     <para xml:lang="en">Gets the lobby staging accessor used before the run snapshot is committed.</para>
		///     <para xml:lang="zh-CN">获取局内快照提交前使用的大厅暂存访问器。</para>
		/// </summary>
		public RunSavedDataLobbyScope<T> Lobby { get; }

		internal RunSavedData(RunSavedDataRunSlot<T> slot)
		{
			_slot = slot;
			Lobby = new RunSavedDataLobbyScope<T>(slot);
		}

		/// <summary>
		///     <para xml:lang="en">Gets the current value, creating a default value if none exists.</para>
		///     <para xml:lang="zh-CN">获取当前值；若不存在，则创建默认值。</para>
		/// </summary>
		public T Get(RunState runState)
		{
			return _slot.GetOrCreate(runState);
		}

		/// <summary>
		///     <para xml:lang="en">Tries to get an existing value without creating one.</para>
		///     <para xml:lang="zh-CN">尝试获取现有值，而不创建新值。</para>
		/// </summary>
		public bool TryGet(RunState runState, out T value)
		{
