		private static bool TryLocateRootProperty(ReadOnlySpan<byte> json, out int insertionPoint, out bool hasRootProperties, out int existingValueStart, out int existingValueEnd)
		{
			insertionPoint = -1;
			hasRootProperties = false;
			existingValueStart = -1;
			existingValueEnd = -1;
			Utf8JsonReader utf8JsonReader = new Utf8JsonReader(json);
			if (!utf8JsonReader.Read() || utf8JsonReader.TokenType != JsonTokenType.StartObject)
			{
