							}
							existingValueStart = (int)utf8JsonReader.TokenStartIndex;
							utf8JsonReader.Skip();
							existingValueEnd = (int)utf8JsonReader.BytesConsumed;
						}
						break;
					case JsonTokenType.EndObject:
						if (utf8JsonReader.CurrentDepth == 0)
						{
							insertionPoint = (int)utf8JsonReader.TokenStartIndex;
						}
						break;
					}
				}
				if (insertionPoint < 0)
				{
