		public bool TryGet(StartRunLobby lobby, ulong netId, out T value)
		{
			if (RunSavedDataLobbyRuntime.TryGetSession(lobby, out RunSavedDataLobbySession session) && session.TryGetPlayer(_slot.SlotKey, netId, out object value2) && value2 is T val)
			{
				value = val;
				return true;
			}
			value = null;
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Sets a player's staged value.</para>
		///     <para xml:lang="zh-CN">设置玩家的暂存值。</para>
		/// </summary>
		public void Set(StartRunLobby lobby, ulong netId, T value)
		{
			ArgumentNullException.ThrowIfNull(value, "value");
			RunSavedDataLobbyRuntime.GetSession(lobby).SetPlayer(_slot.SlotKey, netId, value);
			MaybeSync(lobby);
		}

		/// <summary>
		///     <para xml:lang="en">Sets a player's staged value.</para>
		///     <para xml:lang="zh-CN">设置玩家的暂存值。</para>
		/// </summary>
		public void Set(StartRunLobby lobby, Player player, T value)
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			Set(lobby, player.NetId, value);
		}

		/// <summary>
		///     <para xml:lang="en">Removes a player's staged value.</para>
		///     <para xml:lang="zh-CN">移除玩家的暂存值。</para>
		/// </summary>
		public bool Remove(StartRunLobby lobby, ulong netId)
		{
			int num;
			if (RunSavedDataLobbyRuntime.TryGetSession(lobby, out RunSavedDataLobbySession session))
			{
				num = (session.RemovePlayer(_slot.SlotKey, netId) ? 1 : 0);
				if (num != 0)
				{
					MaybeSync(lobby);
				}
			}
			else
			{
				num = 0;
			}
			return (byte)num != 0;
		}

		/// <summary>
		///     <para xml:lang="en">Mutates and stores a player's staged value.</para>
		///     <para xml:lang="zh-CN">修改并存储玩家的暂存值。</para>
		/// </summary>
		public T Modify(StartRunLobby lobby, ulong netId, Action<T> mutate)
		{
			ArgumentNullException.ThrowIfNull(mutate, "mutate");
			T orCreate = GetOrCreate(lobby, netId);
			mutate(orCreate);
			Set(lobby, netId, orCreate);
			return orCreate;
		}

		/// <summary>
		///     <para xml:lang="en">Mutates and stores a player's staged value.</para>
		///     <para xml:lang="zh-CN">修改并存储玩家的暂存值。</para>
		/// </summary>
		public T Modify(StartRunLobby lobby, Player player, Action<T> mutate)
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			return Modify(lobby, player.NetId, mutate);
		}
	}
	internal static class RunSavedDataLobbyRuntime
	{
		private static readonly ConditionalWeakTable<StartRunLobby, RunSavedDataLobbySession> Sessions = new ConditionalWeakTable<StartRunLobby, RunSavedDataLobbySession>();

		public static RunSavedDataLobbySession GetSession(StartRunLobby lobby)
		{
			ArgumentNullException.ThrowIfNull(lobby, "lobby");
			return Sessions.GetValue(lobby, (StartRunLobby _) => new RunSavedDataLobbySession());
		}

		public static bool TryGetSession(StartRunLobby lobby, out RunSavedDataLobbySession session)
		{
			ArgumentNullException.ThrowIfNull(lobby, "lobby");
			return Sessions.TryGetValue(lobby, out session);
		}

		public static void ClearSession(StartRunLobby lobby)
		{
			ArgumentNullException.ThrowIfNull(lobby, "lobby");
			if (Sessions.TryGetValue(lobby, out RunSavedDataLobbySession value))
			{
				value.Clear();
			}
		}

		public static void RemoveSession(StartRunLobby lobby)
		{
			ArgumentNullException.ThrowIfNull(lobby, "lobby");
			Sessions.Remove(lobby);
		}
	}
	internal sealed class RunSavedDataLobbySession
	{
		private readonly Dictionary<RunSavedDataSlotKey, Dictionary<ulong, object>> _playerValues = new Dictionary<RunSavedDataSlotKey, Dictionary<ulong, object>>();

		private readonly Dictionary<RunSavedDataSlotKey, object> _runValues = new Dictionary<RunSavedDataSlotKey, object>();

		public bool TryGetRun(RunSavedDataSlotKey key, out object? value)
		{
			return _runValues.TryGetValue(key, out value);
		}

		public void SetRun(RunSavedDataSlotKey key, object value)
		{
			_runValues[key] = value;
		}

		public bool RemoveRun(RunSavedDataSlotKey key)
		{
			return _runValues.Remove(key);
		}

		public bool TryGetPlayer(RunSavedDataSlotKey key, ulong netId, out object? value)
		{
			value = null;
			if (_playerValues.TryGetValue(key, out Dictionary<ulong, object> value2))
			{
				return value2.TryGetValue(netId, out value);
			}
			return false;
		}

		public bool HasPlayers(RunSavedDataSlotKey key)
		{
			if (_playerValues.TryGetValue(key, out Dictionary<ulong, object> value))
			{
				return value.Count > 0;
			}
			return false;
		}

		public void SetPlayer(RunSavedDataSlotKey key, ulong netId, object value)
		{
			if (!_playerValues.TryGetValue(key, out Dictionary<ulong, object> value2))
			{
				value2 = new Dictionary<ulong, object>();
				_playerValues[key] = value2;
			}
			value2[netId] = value;
		}

		public bool RemovePlayer(RunSavedDataSlotKey key, ulong netId)
		{
			if (!_playerValues.TryGetValue(key, out Dictionary<ulong, object> value))
			{
				return false;
			}
			bool result = value.Remove(netId);
			if (value.Count == 0)
			{
				_playerValues.Remove(key);
			}
			return result;
		}

		public bool RemovePlayer(ulong netId)
		{
			bool flag = false;
			RunSavedDataSlotKey[] array = _playerValues.Keys.ToArray();
			foreach (RunSavedDataSlotKey key in array)
			{
				Dictionary<ulong, object> dictionary = _playerValues[key];
				flag |= dictionary.Remove(netId);
				if (dictionary.Count == 0)
				{
					_playerValues.Remove(key);
				}
			}
			return flag;
		}

		public bool RemovePlayersExcept(HashSet<ulong> activeNetIds)
		{
			bool flag = false;
			RunSavedDataSlotKey[] array = _playerValues.Keys.ToArray();
			foreach (RunSavedDataSlotKey key in array)
			{
				Dictionary<ulong, object> players = _playerValues[key];
				flag = (from netId in players.Keys.ToArray()
					where !activeNetIds.Contains(netId)
					select netId).Aggregate(flag, (bool current, ulong netId) => current | players.Remove(netId));
				if (players.Count == 0)
				{
					_playerValues.Remove(key);
				}
			}
			return flag;
		}

		public IEnumerable<KeyValuePair<RunSavedDataSlotKey, object>> RunEntries()
		{
			return _runValues;
		}

		public IEnumerable<KeyValuePair<RunSavedDataSlotKey, Dictionary<ulong, object>>> PlayerEntries()
		{
			return _playerValues;
		}

		public void Clear()
		{
			_runValues.Clear();
			_playerValues.Clear();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Notifies mods that start-run lobby staging data can be read or changed before it is committed to the run.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通知模组可在开局大厅暂存数据提交到一局游戏前读取或修改这些数据。
	///     </para>
	/// </summary>
	public sealed record RunSavedDataLobbyStagingEvent(StartRunLobby Lobby, bool IsMultiplayer, bool IsHost, RunSavedDataLobbyStagingReason Reason, DateTimeOffset OccurredAtUtc) : IFrameworkLifecycleEvent;
	/// <summary>
	///     <para xml:lang="en">Identifies why a <see cref="T:STS2RitsuLib.RunData.RunSavedDataLobbyStagingEvent" /> was published.</para>
	///     <para xml:lang="zh-CN">标识发布 <see cref="T:STS2RitsuLib.RunData.RunSavedDataLobbyStagingEvent" /> 的原因。</para>
	/// </summary>
	public enum RunSavedDataLobbyStagingReason
	{
		/// <summary>
		///     <para xml:lang="en">A local or remote player's contribution was merged into the host's lobby session.</para>
		///     <para xml:lang="zh-CN">本地或远程玩家的贡献已合并到主机的大厅会话中。</para>
		/// </summary>
		ContributionMerged,
		/// <summary>
		///     <para xml:lang="en">A player slot was added to the lobby.</para>
		///     <para xml:lang="zh-CN">大厅中新增了一个玩家槽位。</para>
		/// </summary>
		PlayerJoined,
		/// <summary>
		///     <para xml:lang="en"><see cref="M:STS2RitsuLib.RunData.RunSavedDataLobby.NotifyStagingChanged(MegaCrit.Sts2.Core.Multiplayer.Game.Lobby.StartRunLobby)" /> was called explicitly.</para>
		///     <para xml:lang="zh-CN">显式调用了 <see cref="M:STS2RitsuLib.RunData.RunSavedDataLobby.NotifyStagingChanged(MegaCrit.Sts2.Core.Multiplayer.Game.Lobby.StartRunLobby)" />。</para>
		/// </summary>
		Manual,
		/// <summary>
		///     <para xml:lang="en">The host is about to construct the new-run snapshot.</para>
		///     <para xml:lang="zh-CN">主机即将构建新一局游戏快照。</para>
		/// </summary>
		Committing,
		/// <summary>
		///     <para xml:lang="en">A player slot was removed from the lobby.</para>
		///     <para xml:lang="zh-CN">大厅中移除了一个玩家槽位。</para>
		/// </summary>
		PlayerLeft
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Synchronizes lobby contributions through trailers appended to base-game messages, without custom network
	///         messages or sidecar envelopes.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过附加到原版游戏消息的尾部数据同步大厅贡献，不使用自定义网络消息或 Sidecar 信封。
	///     </para>
	/// </summary>
	internal static class RunSavedDataLobbySync
	{
		private sealed class OutboundPayloadScope(Stack<string?> stack) : IDisposable
		{
			private bool _disposed;

			public void Dispose()
			{
				if (!_disposed)
				{
					_disposed = true;
					if (stack.Count > 0)
					{
						stack.Pop();
					}
				}
			}
		}

		private static readonly AsyncLocal<Stack<string?>?> OutboundPayloads = new AsyncLocal<Stack<string>>();

		/// <summary>
		///     <para xml:lang="en">Pushes the local staged contribution to the authoritative host lobby session.</para>
		///     <para xml:lang="zh-CN">将本地暂存贡献推送到作为权威端的主机大厅会话。</para>
		/// </summary>
		public static bool TryPushContribution(StartRunLobby lobby)
		{
			ArgumentNullException.ThrowIfNull(lobby, "lobby");
			if (!RunSavedDataRegistry.HasSlots)
			{
				return false;
			}
			ulong netId = lobby.NetService.NetId;
			string payload = RunSavedDataRegistry.BuildLobbyContributionPayload(lobby, netId);
			return PushContributionCore(lobby, netId, payload);
		}

		internal static void AppendVanillaTrailer(StartRunLobby? lobby, PacketWriter writer)
		{
			if (TryPeekOutboundPayload(out string payload))
			{
				RunSavedDataPatchHelpers.WritePayload(writer, payload);
			}
			else if (lobby != null && RunSavedDataRegistry.HasSlots)
			{
				string payload2 = RunSavedDataRegistry.BuildLobbyContributionPayload(lobby, lobby.NetService.NetId);
				RunSavedDataPatchHelpers.WritePayload(writer, payload2);
			}
		}

		internal static void TryMergeVanillaTrailer(StartRunLobby lobby, ulong senderId)
		{
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_000c: Invalid comparison between Unknown and I4
			if ((int)lobby.NetService.Type == 2 && RunSavedDataLobbyContributionState.TryConsume(out string payload))
			{
				RunSavedDataRegistry.MergeLobbyContribution(lobby, senderId, payload);
			}
		}

		internal static IDisposable? PushOutboundContribution(StartRunLobby lobby)
		{
			ArgumentNullException.ThrowIfNull(lobby, "lobby");
			if (!RunSavedDataRegistry.HasSlots)
			{
				return null;
			}
			return PushOutboundPayload(RunSavedDataRegistry.BuildLobbyContributionPayload(lobby, lobby.NetService.NetId));
		}

		private static bool PushContributionCore(StartRunLobby lobby, ulong netId, string? payload)
		{
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_000b: Unknown result type (might be due to invalid IL or missing references)
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			//IL_000e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0010: Invalid comparison between Unknown and I4
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			//IL_0014: Invalid comparison between Unknown and I4
			NetGameType type = lobby.NetService.Type;
			if (type - 1 > 1)
			{
				if ((int)type == 3)
				{
					return TrySendVanillaContributionMessage(lobby, payload);
				}
				return false;
			}
			RunSavedDataRegistry.MergeLobbyContribution(lobby, netId, payload);
			return true;
		}

		private static bool TrySendVanillaContributionMessage(StartRunLobby lobby, string? payload)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			try
			{
				CharacterModel character = lobby.LocalPlayer.character;
				if (character == null)
				{
					return false;
				}
				using (PushOutboundPayload(payload))
				{
					lobby.NetService.SendMessage<LobbyPlayerChangedCharacterMessage>(new LobbyPlayerChangedCharacterMessage
					{
						character = character
					});
				}
				return true;
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[RunSavedData] Failed to push lobby contribution: " + ex.Message, 1);
				return false;
			}
		}

		private static IDisposable PushOutboundPayload(string? payload)
		{
			Stack<string> stack = OutboundPayloads.Value;
			if (stack == null)
			{
				stack = new Stack<string>();
				OutboundPayloads.Value = stack;
			}
			stack.Push(payload);
			return new OutboundPayloadScope(stack);
		}

		private static bool TryPeekOutboundPayload(out string? payload)
		{
			Stack<string> value = OutboundPayloads.Value;
			if (value != null && value.Count > 0)
			{
				payload = value.Peek();
				return true;
			}
			payload = null;
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Configures a run saved-data slot.</para>
	///     <para xml:lang="zh-CN">配置跑局保存数据槽位。</para>
	/// </summary>
	public sealed class RunSavedDataOptions
	{
		/// <summary>
		///     <para xml:lang="en">Gets the current schema version written for this slot.</para>
		///     <para xml:lang="zh-CN">获取此槽位写入数据时使用的当前架构版本。</para>
		/// </summary>
		public int SchemaVersion { get; init; } = 1;

		/// <summary>
		///     <para xml:lang="en">Gets the policy that determines when this slot is written.</para>
		///     <para xml:lang="zh-CN">获取决定何时写入此槽位的策略。</para>
		/// </summary>
		public RunSavedDataWritePolicy WritePolicy { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether writes through <see cref="T:STS2RitsuLib.RunData.RunSavedDataLobbyScope`1" /> or
		///         <see cref="T:STS2RitsuLib.RunData.PlayerRunSavedDataLobbyScope`1" /> push a contribution update in multiplayer.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取多人游戏中通过 <see cref="T:STS2RitsuLib.RunData.RunSavedDataLobbyScope`1" /> 或
		///         <see cref="T:STS2RitsuLib.RunData.PlayerRunSavedDataLobbyScope`1" /> 写入后是否推送贡献更新。
		///     </para>
