	/// <summary>
	///     <para xml:lang="en">
	///         Notifies mods before run saved data is exported for authoritative new-run initialization.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在为权威端的新一局游戏初始化导出局内保存数据前通知模组。
	///     </para>
	/// </summary>
	public sealed record RunSavedDataPreparingEvent(RunState RunState, bool IsMultiplayer, DateTimeOffset OccurredAtUtc) : IFrameworkLifecycleEvent;
	internal static class RunSavedDataRegistry
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, IRunSavedDataSlot> Slots = new Dictionary<string, IRunSavedDataSlot>(StringComparer.OrdinalIgnoreCase);

		public static bool HasSlots
		{
			get
			{
				using (SyncRoot.EnterScope())
				{
					return Slots.Count > 0;
				}
			}
		}

		public static void Register(IRunSavedDataSlot slot)
		{
			ArgumentNullException.ThrowIfNull(slot, "slot");
			string slotId = GetSlotId(slot.ModId, slot.Key);
			using (SyncRoot.EnterScope())
			{
				if (!Slots.TryAdd(slotId, slot))
				{
					throw new InvalidOperationException("RunSavedData slot is already registered: " + slot.ModId + "::" + slot.Key);
				}
			}
		}

		public static void Import(SerializableRun save, RunState runState)
		{
			if (RunSavedDataRuntime.TryGetDocument(save, out RunSavedDataDocument document))
			{
				RunSavedDataRuntime.GetBag(runState).PreservedDocument = document.Clone();
				IRunSavedDataSlot[] slotsSnapshot = GetSlotsSnapshot();
				for (int i = 0; i < slotsSnapshot.Length; i++)
				{
					slotsSnapshot[i].Import(runState, document);
				}
			}
		}

		public static RunSavedDataDocument? Export(RunState runState)
		{
			ModCardPilePersistence.SyncToSavedData(runState);
			ModRunRngRegistry.SyncToSavedData(runState);
			RunSavedDataDocument runSavedDataDocument = ((RunSavedDataRuntime.TryGetBag(runState, out RunSavedDataBag bag) && bag.PreservedDocument != null) ? bag.PreservedDocument.Clone() : new RunSavedDataDocument());
			IRunSavedDataSlot[] slotsSnapshot = GetSlotsSnapshot();
			for (int i = 0; i < slotsSnapshot.Length; i++)
			{
				slotsSnapshot[i].Export(runState, runSavedDataDocument);
			}
			if (!runSavedDataDocument.IsEmpty)
			{
				return runSavedDataDocument;
			}
			return null;
		}

		public static void AttachDocumentFromJson(SerializableRun? save, string? json)
		{
			if (save != null)
			{
				RunSavedDataDocument document = RunSavedDataDocument.FromJson(json);
				RunSavedDataRuntime.AttachDocument(save, document);
			}
		}

		public static void AttachDocument(SerializableRun? save, RunSavedDataDocument? document)
		{
			if (save != null)
			{
				RunSavedDataRuntime.AttachDocument(save, document);
			}
		}

		public static RunSavedDataDocument? BuildDocumentFromRun(RunState? runState)
		{
			if (runState != null)
			{
				return Export(runState);
			}
			return null;
		}

		public static byte[] InjectIntoUtf8Json(byte[] json, SerializableRun save)
		{
			if (!RunSavedDataRuntime.TryGetDocument(save, out RunSavedDataDocument document))
			{
				return json;
			}
			return RunSavedDataDocument.InjectIntoUtf8Json(json, document);
		}

		public static bool HasDocument(SerializableRun save)
		{
			if (RunSavedDataRuntime.TryGetDocument(save, out RunSavedDataDocument document))
			{
				return !document.IsEmpty;
			}
			return false;
		}

		public static void MergeDocuments(SerializableRun target, SerializableRun source)
		{
			if (RunSavedDataRuntime.TryGetDocument(source, out RunSavedDataDocument document))
			{
				RunSavedDataRuntime.AttachDocument(target, document.Clone());
			}
		}

		public static void ImportPayloadIntoRun(RunState runState, string? payload)
		{
			if (string.IsNullOrWhiteSpace(payload))
			{
				return;
			}
			RunSavedDataDocument runSavedDataDocument = RunSavedDataDocument.FromJson(payload);
			if (runSavedDataDocument != null)
			{
				RunSavedDataRuntime.GetBag(runState).PreservedDocument = runSavedDataDocument.Clone();
				IRunSavedDataSlot[] slotsSnapshot = GetSlotsSnapshot();
				for (int i = 0; i < slotsSnapshot.Length; i++)
				{
					slotsSnapshot[i].Import(runState, runSavedDataDocument);
				}
			}
		}

		public static string? BuildPayload(RunState? runState)
		{
			RunSavedDataDocument runSavedDataDocument = BuildDocumentFromRun(runState);
			if (runSavedDataDocument == null || runSavedDataDocument.IsEmpty)
			{
				return null;
			}
			return runSavedDataDocument.ToRootObject().ToJsonString(new JsonSerializerOptions
			{
				WriteIndented = false
			});
		}

		public static string? BuildPayloadFromSerializable(SerializableRun save)
		{
			if (!RunSavedDataRuntime.TryGetDocument(save, out RunSavedDataDocument document))
			{
				return null;
			}
			RunSavedDataDocument runSavedDataDocument = new RunSavedDataDocument();
			foreach (var (modId, key, jsonObject) in document.Entries())
			{
				runSavedDataDocument.SetRaw(modId, key, jsonObject.DeepClone().AsObject());
			}
			if (!runSavedDataDocument.IsEmpty)
			{
				return runSavedDataDocument.ToRootObject().ToJsonString(new JsonSerializerOptions
				{
					WriteIndented = false
				});
			}
			return null;
		}

		public static string? BuildLobbyContributionPayload(StartRunLobby lobby, ulong contributorNetId)
		{
			if (!IsActiveLobbyPlayer(lobby, contributorNetId) || !RunSavedDataLobbyRuntime.TryGetSession(lobby, out RunSavedDataLobbySession session))
			{
				return null;
			}
			bool isHostNetId = contributorNetId == lobby.NetService.NetId;
			RunSavedDataDocument runSavedDataDocument = new RunSavedDataDocument();
			IRunSavedDataSlot[] slotsSnapshot = GetSlotsSnapshot();
			for (int i = 0; i < slotsSnapshot.Length; i++)
			{
				slotsSnapshot[i].TryExportLobbyContribution(session, contributorNetId, isHostNetId, runSavedDataDocument);
			}
			if (!runSavedDataDocument.IsEmpty)
			{
				return runSavedDataDocument.ToRootObject().ToJsonString(new JsonSerializerOptions
				{
					WriteIndented = false
				});
			}
			return null;
		}

		public static string? BuildLobbyStagingPayload(StartRunLobby lobby)
		{
			if (!RunSavedDataLobbyRuntime.TryGetSession(lobby, out RunSavedDataLobbySession session))
			{
				return null;
			}
			session.RemovePlayersExcept(GetActiveLobbyPlayerIds(lobby));
			RunSavedDataDocument runSavedDataDocument = new RunSavedDataDocument();
			IRunSavedDataSlot[] slotsSnapshot = GetSlotsSnapshot();
			for (int i = 0; i < slotsSnapshot.Length; i++)
			{
				slotsSnapshot[i].TryExportLobbyStaging(session, runSavedDataDocument);
			}
			if (!runSavedDataDocument.IsEmpty)
			{
				return runSavedDataDocument.ToRootObject().ToJsonString(new JsonSerializerOptions
				{
					WriteIndented = false
				});
			}
			return null;
		}

		public static void MergeLobbyContribution(StartRunLobby lobby, ulong contributorNetId, string? payload)
		{
			if (string.IsNullOrWhiteSpace(payload) || !IsActiveLobbyPlayer(lobby, contributorNetId))
			{
				return;
			}
			RunSavedDataDocument runSavedDataDocument = RunSavedDataDocument.FromJson(payload);
			if (runSavedDataDocument == null)
			{
				return;
			}
			RunSavedDataLobbySession session = RunSavedDataLobbyRuntime.GetSession(lobby);
			bool isHostNetId = contributorNetId == lobby.NetService.NetId;
			foreach (var (modId, key, entry) in runSavedDataDocument.Entries())
			{
				TryGetSlot(modId, key)?.ImportLobbyContribution(session, contributorNetId, isHostNetId, entry);
			}
			RunSavedDataLobby.PublishStagingEvent(lobby, RunSavedDataLobbyStagingReason.ContributionMerged);
		}

		private static IRunSavedDataSlot? TryGetSlot(string modId, string key)
		{
			using (SyncRoot.EnterScope())
			{
				return Slots.GetValueOrDefault(GetSlotId(modId, key));
			}
		}

		private static bool IsActiveLobbyPlayer(StartRunLobby lobby, ulong netId)
		{
			return lobby.Players.Any(delegate(StartRunLobbyPlayer player)
			{
				//IL_0000: Unknown result type (might be due to invalid IL or missing references)
				return player.id == netId;
			});
		}

		private static HashSet<ulong> GetActiveLobbyPlayerIds(StartRunLobby lobby)
		{
			HashSet<ulong> hashSet = new HashSet<ulong>();
			foreach (ulong item in lobby.Players.Select(delegate(StartRunLobbyPlayer player)
			{
				//IL_0000: Unknown result type (might be due to invalid IL or missing references)
				return player.id;
			}))
			{
				hashSet.Add(item);
			}
			return hashSet;
		}

		internal static IRunSavedDataSlot[] GetRegisteredSlots()
		{
			return GetSlotsSnapshot();
		}

		private static IRunSavedDataSlot[] GetSlotsSnapshot()
		{
			using (SyncRoot.EnterScope())
			{
				return Slots.Values.ToArray();
			}
		}

		private static string GetSlotId(string modId, string key)
		{
			return modId + "\u001f" + key;
		}
	}
	internal sealed class RunSavedDataBag
	{
		private readonly HashSet<RunSavedDataSlotKey> _dirty = new HashSet<RunSavedDataSlotKey>();

		private readonly Dictionary<RunSavedDataSlotKey, object> _values = new Dictionary<RunSavedDataSlotKey, object>();

		public RunSavedDataDocument? PreservedDocument { get; set; }

		public bool TryGet(RunSavedDataSlotKey key, out object value)
		{
			return _values.TryGetValue(key, out value);
		}

		public void Set(RunSavedDataSlotKey key, object value, bool dirty = true)
		{
			_values[key] = value;
			if (dirty)
			{
				_dirty.Add(key);
			}
		}

		public bool Remove(RunSavedDataSlotKey key)
		{
			_dirty.Add(key);
			return _values.Remove(key);
		}

		public bool IsDirty(RunSavedDataSlotKey key)
		{
			return _dirty.Contains(key);
		}
	}
	internal readonly record struct RunSavedDataSlotKey(string ModId, string Key, RunSavedDataKind Kind);
	internal enum RunSavedDataKind
	{
		Run,
