	internal static class RunSavedDataRuntime
	{
		private sealed class RunSavedDataDocumentBox(RunSavedDataDocument document)
		{
			public RunSavedDataDocument Document { get; } = document;
		}

		private static readonly ConditionalWeakTable<RunState, RunSavedDataBag> RunBags = new ConditionalWeakTable<RunState, RunSavedDataBag>();

		private static readonly ConditionalWeakTable<SerializableRun, RunSavedDataDocumentBox> SerializableDocuments = new ConditionalWeakTable<SerializableRun, RunSavedDataDocumentBox>();

		public static RunSavedDataBag GetBag(RunState runState)
		{
			ArgumentNullException.ThrowIfNull(runState, "runState");
			return RunBags.GetValue(runState, (RunState _) => new RunSavedDataBag());
		}

		public static bool TryGetBag(RunState runState, out RunSavedDataBag bag)
		{
			ArgumentNullException.ThrowIfNull(runState, "runState");
			return RunBags.TryGetValue(runState, out bag);
		}

		public static void AttachDocument(SerializableRun save, RunSavedDataDocument? document)
		{
			ArgumentNullException.ThrowIfNull(save, "save");
			SerializableDocuments.Remove(save);
			if (document != null && !document.IsEmpty)
			{
				SerializableDocuments.Add(save, new RunSavedDataDocumentBox(document));
			}
		}

		public static bool TryGetDocument(SerializableRun save, out RunSavedDataDocument document)
		{
			ArgumentNullException.ThrowIfNull(save, "save");
			if (SerializableDocuments.TryGetValue(save, out RunSavedDataDocumentBox value))
			{
				document = value.Document;
				return true;
			}
			document = null;
			return false;
		}
	}
