	internal abstract class RunSavedDataSlot<T>(string modId, string key, Func<T>? defaultFactory, RunSavedDataOptions? options, RunSavedDataKind kind) : IRunSavedDataSlot where T : class, new()
	{
		private const string SchemaPropertyName = "schema";

		private const string KindPropertyName = "kind";

		private const string DataPropertyName = "data";

		private const string PlayersPropertyName = "players";

		private readonly Func<T> _defaultFactory = defaultFactory ?? ((Func<T>)(() => new T()));

		public string ModId { get; } = modId;

		public string Key { get; } = key;

		public RunSavedDataKind Kind { get; } = kind;

		public RunSavedDataOptions Options { get; } = options ?? new RunSavedDataOptions();

		public RunSavedDataSlotKey SlotKey { get; } = new RunSavedDataSlotKey(modId, key, kind);

		public void Import(RunState runState, RunSavedDataDocument document)
		{
			if (!document.TryGetRaw(ModId, Key, out JsonObject entry))
			{
				return;
			}
			try
			{
				ImportCore(runState, entry);
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn($"[RunSavedData] Failed to import '{ModId}'::{Key}: {ex.Message}", 1);
			}
		}

		public virtual bool TryExportLobbyContribution(RunSavedDataLobbySession session, ulong netId, bool isHostNetId, RunSavedDataDocument document)
		{
			return false;
		}

		public virtual void ImportLobbyContribution(RunSavedDataLobbySession session, ulong netId, bool isHostNetId, JsonObject entry)
		{
		}

		public virtual bool TryExportLobbyStaging(RunSavedDataLobbySession session, RunSavedDataDocument document)
		{
			return false;
		}

		public virtual void CommitLobbyStaging(RunSavedDataLobbySession session, RunState runState)
		{
		}

		public void Export(RunState runState, RunSavedDataDocument document)
		{
			if (!RunSavedDataRuntime.TryGetBag(runState, out RunSavedDataBag bag))
			{
				return;
			}
			if (!TryBuildEntry(runState, bag, out JsonObject entry))
			{
				if (bag.IsDirty(SlotKey))
				{
					document.Remove(ModId, Key);
				}
			}
			else
			{
				document.SetRaw(ModId, Key, entry);
			}
		}

		public T GetOrCreate(RunState runState)
		{
			RunSavedDataBag bag = RunSavedDataRuntime.GetBag(runState);
			if (bag.TryGet(SlotKey, out object value) && value is T result)
			{
				return result;
			}
			T val = CreateDefaultValue();
			bag.Set(SlotKey, val, dirty: false);
			return val;
		}

		internal T CreateDefaultValue()
		{
			return _defaultFactory() ?? throw new InvalidOperationException("RunSavedData default factory returned null: " + ModId + "::" + Key);
		}

		public bool TryGet(RunState runState, out T value)
		{
			if (RunSavedDataRuntime.TryGetBag(runState, out RunSavedDataBag bag) && bag.TryGet(SlotKey, out object value2) && value2 is T val)
			{
				value = val;
				return true;
			}
			value = null;
			return false;
		}

		public void Set(RunState runState, T value)
		{
			RunSavedDataRuntime.GetBag(runState).Set(SlotKey, value);
		}

		public bool Remove(RunState runState)
		{
			return RunSavedDataRuntime.GetBag(runState).Remove(SlotKey);
		}

		protected abstract bool TryBuildEntry(RunState runState, RunSavedDataBag bag, out JsonObject entry);

		protected abstract void ImportCore(RunState runState, JsonObject entry);

		protected JsonObject CreateRunEntry(T value)
		{
			return new JsonObject
			{
				["schema"] = Options.SchemaVersion,
				["kind"] = "run",
				["data"] = JsonSerializer.SerializeToNode(value, RunSavedDataJson.Options)
			};
		}

		protected JsonObject CreatePlayerEntry(JsonObject players)
		{
			return new JsonObject
			{
				["schema"] = Options.SchemaVersion,
				["kind"] = "player",
				["players"] = players
			};
		}

		protected bool TryReadData(JsonObject entry, out T value)
		{
			value = null;
			if (!TryPrepareEntry(entry, out JsonObject migrated))
			{
				return false;
			}
			JsonNode? jsonNode = migrated["data"];
			T val = ((jsonNode != null) ? jsonNode.Deserialize<T>(RunSavedDataJson.Options) : null);
			if (val == null)
			{
				return false;
			}
			value = val;
			return true;
		}

		protected bool TryReadPlayer(JsonNode? node, out T value)
		{
			value = null;
			T val = ((node != null) ? node.Deserialize<T>(RunSavedDataJson.Options) : null);
			if (val == null)
			{
				return false;
			}
			value = val;
			return true;
		}

		protected JsonNode? ToNode(T value)
		{
			return JsonSerializer.SerializeToNode(value, RunSavedDataJson.Options);
		}

		protected bool ShouldWrite(RunSavedDataBag bag, object? value)
		{
			return Options.WritePolicy switch
			{
				RunSavedDataWritePolicy.AlwaysWhenRegistered => value != null, 
				RunSavedDataWritePolicy.WhenNonDefault => value != null && !IsDefaultValue((T)value), 
				_ => bag.IsDirty(SlotKey) && value != null, 
			};
		}

		protected static string PlayerKey(ulong netId)
		{
			return netId.ToString();
		}

		protected bool TryReadPlayers(JsonObject entry, out JsonObject players)
		{
			if (TryPrepareEntry(entry, out JsonObject migrated) && migrated["players"] is JsonObject jsonObject)
			{
				players = jsonObject;
				return true;
			}
			players = null;
			return false;
		}

		private bool TryPrepareEntry(JsonObject entry, out JsonObject migrated)
		{
			migrated = entry;
			int num = entry["schema"]?.GetValue<int>() ?? 1;
			if (num == Options.SchemaVersion)
			{
				return true;
			}
			if (num < 0 || num > Options.SchemaVersion)
			{
				return false;
			}
			if (Options.Migrations == null || Options.Migrations.Count == 0)
			{
				return false;
			}
			migrated = entry.DeepClone().AsObject();
			List<IMigration> migrations = (from migration in Options.Migrations
				orderby migration.FromVersion, migration.ToVersion
				select migration).ToList();
			if (!MigrationManager.TryBuildShortestMigrationPath(num, Options.SchemaVersion, migrations, out List<IMigration> path))
			{
				return false;
			}
			foreach (IMigration item in path)
			{
				if (!item.Migrate(migrated))
				{
					return false;
				}
				migrated["schema"] = item.ToVersion;
			}
			return true;
		}

		private bool IsDefaultValue(T value)
		{
			try
			{
				string a = JsonSerializer.SerializeToNode(value, RunSavedDataJson.Options)?.ToJsonString();
				string b = JsonSerializer.SerializeToNode(_defaultFactory(), RunSavedDataJson.Options)?.ToJsonString();
				return string.Equals(a, b, StringComparison.Ordinal);
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				return false;
			}
		}
	}
	internal sealed class RunSavedDataRunSlot<T> : RunSavedDataSlot<T> where T : class, new()
	{
		public RunSavedDataRunSlot(string modId, string key, Func<T>? defaultFactory, RunSavedDataOptions? options)
			: base(modId, key, defaultFactory, options, RunSavedDataKind.Run)
		{
		}

		protected override bool TryBuildEntry(RunState runState, RunSavedDataBag bag, out JsonObject entry)
		{
			entry = null;
			if (!bag.TryGet(base.SlotKey, out object value) || !(value is T value2) || !ShouldWrite(bag, value2))
			{
				return false;
			}
			entry = CreateRunEntry(value2);
			return true;
		}

		protected override void ImportCore(RunState runState, JsonObject entry)
		{
			if (TryReadData(entry, out var value))
			{
				RunSavedDataRuntime.GetBag(runState).Set(base.SlotKey, value, dirty: false);
				return;
			}
			RitsuLibFramework.Logger.Warn($"[RunSavedData] Failed to read run data '{base.ModId}'::{base.Key}.", 1);
		}

		public override bool TryExportLobbyContribution(RunSavedDataLobbySession session, ulong netId, bool isHostNetId, RunSavedDataDocument document)
		{
			if (!isHostNetId || !session.TryGetRun(base.SlotKey, out object value) || !(value is T value2))
			{
				return false;
			}
			document.SetRaw(base.ModId, base.Key, CreateRunEntry(value2));
			return true;
		}

		public override void ImportLobbyContribution(RunSavedDataLobbySession session, ulong netId, bool isHostNetId, JsonObject entry)
		{
			if (isHostNetId && TryReadData(entry, out var value))
			{
				session.SetRun(base.SlotKey, value);
			}
		}

		public override bool TryExportLobbyStaging(RunSavedDataLobbySession session, RunSavedDataDocument document)
		{
			if (!session.TryGetRun(base.SlotKey, out object value) || !(value is T value2))
			{
				return false;
			}
			document.SetRaw(base.ModId, base.Key, CreateRunEntry(value2));
			return true;
		}

		public override void CommitLobbyStaging(RunSavedDataLobbySession session, RunState runState)
		{
			if (session.TryGetRun(base.SlotKey, out object value) && value is T value2)
			{
				RunSavedDataRuntime.GetBag(runState).Set(base.SlotKey, value2, dirty: false);
			}
		}
	}
	internal sealed class RunSavedDataPlayerSlot<T>(string modId, string key, Func<T>? defaultFactory, RunSavedDataOptions? options) : RunSavedDataSlot<Dictionary<ulong, T>>(modId, key, (Func<Dictionary<ulong, T>>?)null, options, RunSavedDataKind.Player) where T : class, new()
	{
		private readonly Func<T> _defaultFactory = defaultFactory ?? ((Func<T>)(() => new T()));

		public T GetOrCreate(RunState runState, ulong netId)
		{
			Dictionary<ulong, T> orCreate = GetOrCreate(runState);
			if (orCreate.TryGetValue(netId, out var value))
			{
				return value;
			}
			return orCreate[netId] = CreatePlayerDefaultValue();
		}

		internal T CreatePlayerDefaultValue()
		{
			return _defaultFactory() ?? throw new InvalidOperationException("RunSavedData player default factory returned null: " + base.ModId + "::" + base.Key);
		}

		public bool TryGet(RunState runState, ulong netId, out T value)
		{
			if (TryGet(runState, out Dictionary<ulong, T> value2) && value2.TryGetValue(netId, out value))
			{
				return true;
			}
			value = null;
			return false;
		}

		public void Set(RunState runState, ulong netId, T value)
		{
			Dictionary<ulong, T> orCreate = GetOrCreate(runState);
			orCreate[netId] = value;
			RunSavedDataRuntime.GetBag(runState).Set(base.SlotKey, orCreate);
		}

		public bool Remove(RunState runState, ulong netId)
		{
			if (!TryGet(runState, out Dictionary<ulong, T> value))
			{
				return false;
			}
			bool num = value.Remove(netId);
			if (num)
			{
				RunSavedDataRuntime.GetBag(runState).Set(base.SlotKey, value);
			}
			return num;
		}

		public T Modify(Player player, Action<T> mutate)
		{
			return Modify(GetRunState(player), player.NetId, mutate);
		}

		public T Modify(RunState runState, ulong netId, Action<T> mutate)
		{
			ArgumentNullException.ThrowIfNull(mutate, "mutate");
			T orCreate = GetOrCreate(runState, netId);
			mutate(orCreate);
			Set(runState, netId, orCreate);
			return orCreate;
		}

		protected override bool TryBuildEntry(RunState runState, RunSavedDataBag bag, out JsonObject entry)
		{
			entry = null;
			if (!bag.TryGet(base.SlotKey, out object value) || !(value is Dictionary<ulong, T> { Count: not 0 } dictionary) || !ShouldWrite(bag, dictionary))
			{
				return false;
			}
			JsonObject jsonObject = new JsonObject();
			foreach (var (netId, value2) in dictionary.OrderBy((KeyValuePair<ulong, T> pair) => pair.Key))
			{
				jsonObject[RunSavedDataSlot<Dictionary<ulong, T>>.PlayerKey(netId)] = JsonSerializer.SerializeToNode(value2, RunSavedDataJson.Options);
			}
			entry = CreatePlayerEntry(jsonObject);
			return true;
		}

		protected override void ImportCore(RunState runState, JsonObject entry)
		{
			if (!TryReadPlayers(entry, out JsonObject players))
			{
				return;
			}
			Dictionary<ulong, T> dictionary = new Dictionary<ulong, T>();
			foreach (var (s, node) in players)
			{
				if (ulong.TryParse(s, out var result) && TryReadPlayerValue(node, out var value))
				{
					dictionary[result] = value;
				}
			}
			if (dictionary.Count > 0)
			{
				RunSavedDataRuntime.GetBag(runState).Set(base.SlotKey, dictionary, dirty: false);
			}
		}

		public override bool TryExportLobbyContribution(RunSavedDataLobbySession session, ulong netId, bool isHostNetId, RunSavedDataDocument document)
		{
			if (!session.TryGetPlayer(base.SlotKey, netId, out object value) || !(value is T value2))
			{
				return false;
			}
			JsonObject players = new JsonObject { [RunSavedDataSlot<Dictionary<ulong, T>>.PlayerKey(netId)] = JsonSerializer.SerializeToNode(value2, RunSavedDataJson.Options) };
			document.SetRaw(base.ModId, base.Key, CreatePlayerEntry(players));
			return true;
		}

		public override void ImportLobbyContribution(RunSavedDataLobbySession session, ulong netId, bool isHostNetId, JsonObject entry)
		{
			if (TryReadPlayers(entry, out JsonObject players) && players.TryGetPropertyValue(RunSavedDataSlot<Dictionary<ulong, T>>.PlayerKey(netId), out JsonNode jsonNode) && TryReadPlayerValue(jsonNode, out var value))
			{
				session.SetPlayer(base.SlotKey, netId, value);
			}
		}

		public override bool TryExportLobbyStaging(RunSavedDataLobbySession session, RunSavedDataDocument document)
		{
			if (!session.HasPlayers(base.SlotKey))
			{
				return false;
			}
			JsonObject jsonObject = new JsonObject();
			foreach (var (runSavedDataSlotKey2, source) in session.PlayerEntries())
			{
				if (runSavedDataSlotKey2 != base.SlotKey)
				{
					continue;
				}
				foreach (var (netId, obj2) in source.OrderBy((KeyValuePair<ulong, object> pair) => pair.Key))
				{
					if (obj2 is T value)
					{
						jsonObject[RunSavedDataSlot<Dictionary<ulong, T>>.PlayerKey(netId)] = JsonSerializer.SerializeToNode(value, RunSavedDataJson.Options);
					}
				}
			}
			if (jsonObject.Count == 0)
			{
				return false;
			}
			document.SetRaw(base.ModId, base.Key, CreatePlayerEntry(jsonObject));
			return true;
		}

		public override void CommitLobbyStaging(RunSavedDataLobbySession session, RunState runState)
		{
			if (!session.HasPlayers(base.SlotKey))
			{
				return;
			}
			Dictionary<ulong, T> dictionary = new Dictionary<ulong, T>();
			foreach (var (runSavedDataSlotKey2, dictionary3) in session.PlayerEntries())
			{
				if (runSavedDataSlotKey2 != base.SlotKey)
				{
					continue;
				}
				foreach (var (key, obj2) in dictionary3)
				{
					if (obj2 is T value)
					{
						dictionary[key] = value;
					}
				}
			}
			if (dictionary.Count > 0)
			{
				RunSavedDataRuntime.GetBag(runState).Set(base.SlotKey, dictionary, dirty: false);
			}
		}

		private bool TryReadPlayerValue(JsonNode? node, out T value)
		{
			value = null;
			T val = ((node != null) ? node.Deserialize<T>(RunSavedDataJson.Options) : null);
			if (val == null)
			{
				return false;
			}
			value = val;
			return true;
		}

		private static RunState GetRunState(Player player)
		{
			IRunState runState = player.RunState;
			RunState val = (RunState)(object)((runState is RunState) ? runState : null);
			if (val != null)
			{
				return val;
			}
			throw new InvalidOperationException("Player does not belong to a concrete RunState.");
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides a per-mod registry of run saved-data slots.</para>
	///     <para xml:lang="zh-CN">提供按模组划分的局内保存数据槽位注册表。</para>
	/// </summary>
	public sealed class RunSavedDataStore
	{
		private static readonly Lock StoresLock = new Lock();

		private static readonly Dictionary<string, RunSavedDataStore> Stores = new Dictionary<string, RunSavedDataStore>(StringComparer.OrdinalIgnoreCase);

		private readonly Dictionary<string, IRunSavedDataSlot> _slots = new Dictionary<string, IRunSavedDataSlot>(StringComparer.OrdinalIgnoreCase);

		/// <summary>
		///     <para xml:lang="en">Gets the identifier of the mod that owns this store.</para>
		///     <para xml:lang="zh-CN">获取此存储所属模组的标识符。</para>
		/// </summary>
		public string ModId { get; }

		private RunSavedDataStore(string modId)
		{
			ModId = modId;
		}

		/// <summary>
		///     <para xml:lang="en">Gets the process-wide store for <paramref name="modId" />.</para>
		///     <para xml:lang="zh-CN">获取 <paramref name="modId" /> 对应的进程级存储。</para>
		/// </summary>
		public static RunSavedDataStore For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (StoresLock.EnterScope())
			{
				if (Stores.TryGetValue(modId, out RunSavedDataStore value))
				{
					return value;
				}
				value = new RunSavedDataStore(modId);
				Stores[modId] = value;
				return value;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers saved data shared by the whole run.</para>
		///     <para xml:lang="zh-CN">注册由整局游戏共享的保存数据。</para>
		/// </summary>
		public RunSavedData<T> Register<T>(string key, Func<T>? defaultFactory = null, RunSavedDataOptions? options = null) where T : class, new()
		{
			RunSavedDataRunSlot<T> slot = new RunSavedDataRunSlot<T>(ModId, key, defaultFactory, options);
			RegisterSlot(slot);
			return new RunSavedData<T>(slot);
		}

		/// <summary>
		///     <para xml:lang="en">Registers run saved data stored separately for each player.</para>
		///     <para xml:lang="zh-CN">注册为每名玩家分别存储的局内保存数据。</para>
		/// </summary>
		public PlayerRunSavedData<T> RegisterPerPlayer<T>(string key, Func<T>? defaultFactory = null, RunSavedDataOptions? options = null) where T : class, new()
		{
			RunSavedDataPlayerSlot<T> slot = new RunSavedDataPlayerSlot<T>(ModId, key, defaultFactory, options);
			RegisterSlot(slot);
			return new PlayerRunSavedData<T>(slot);
		}

		private void RegisterSlot(IRunSavedDataSlot slot)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(slot.Key, "slot.Key");
			lock (_slots)
			{
				if (!_slots.TryAdd(slot.Key, slot))
				{
					throw new InvalidOperationException("RunSavedData key is already registered: " + ModId + "::" + slot.Key);
				}
				try
				{
					RunSavedDataRegistry.Register(slot);
				}
				catch
				{
					if (_slots.TryGetValue(slot.Key, out IRunSavedDataSlot value) && value == slot)
					{
						_slots.Remove(slot.Key);
					}
					throw;
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Specifies when a run saved-data slot is written.</para>
	///     <para xml:lang="zh-CN">指定何时写入局内保存数据槽位。</para>
	/// </summary>
	public enum RunSavedDataWritePolicy
	{
		/// <summary>
		///     <para xml:lang="en">Writes only values explicitly set or modified through the API.</para>
		///     <para xml:lang="zh-CN">仅写入通过 API 显式设置或修改的值。</para>
		/// </summary>
		WhenSet,
		/// <summary>
		///     <para xml:lang="en">Writes values that differ from a newly created default value.</para>
		///     <para xml:lang="zh-CN">写入与新建默认值不同的值。</para>
		/// </summary>
		WhenNonDefault,
		/// <summary>
		///     <para xml:lang="en">Writes the slot whenever it is registered and can be resolved for a run.</para>
		///     <para xml:lang="zh-CN">只要槽位已注册且可为一局游戏解析，就写入此槽位。</para>
		/// </summary>
		AlwaysWhenRegistered
	}
}
namespace STS2RitsuLib.RunData.Patches
{
	internal static class RunSavedDataPatchHelpers
	{
		internal const string TailExtensionId = "ritsulib.runSavedData";

		internal const int PayloadVersion = 2;

		private const int LegacyStringPayloadVersion = 1;

		private const int MaxPayloadBytes = 4194304;

		private static readonly AsyncLocal<Stack<RunSavedDataSaveRunCapture>?> ActiveSaveRunCaptures = new AsyncLocal<Stack<RunSavedDataSaveRunCapture>>();

		public static string GetRunSavePath(RunSaveManager manager, bool isMultiplayer)
		{
			string text = (isMultiplayer ? "current_run_mp.save" : "current_run.save");
			return RunSaveManager.GetRunSavePath(RunSavedDataRunSaveManagerAccess.ProfileIdProvider(manager).CurrentProfileId, text, (bool?)null);
		}

		public static void AttachDocumentFromCurrentFile(RunSaveManager manager, SerializableRun? save, bool isMultiplayer)
		{
			if (save == null)
			{
				return;
			}
			try
			{
				string json = RunSavedDataRunSaveManagerAccess.SaveStore(manager).ReadFile(GetRunSavePath(manager, isMultiplayer));
				RunSavedDataRegistry.AttachDocumentFromJson(save, json);
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[RunSavedData] Failed to read run extension data: " + ex.Message, 1);
			}
		}

		public static RunSavedDataSaveRunCapture BeginSaveRunCapture(RunSaveManager manager, SerializableRun? save = null, bool? isMultiplayer = null)
		{
			RunSavedDataSaveRunCapture runSavedDataSaveRunCapture = new RunSavedDataSaveRunCapture(manager, isMultiplayer ?? TryGetCurrentRunIsMultiplayerHost())
			{
				Save = save
			};
			AsyncLocal<Stack<RunSavedDataSaveRunCapture>> activeSaveRunCaptures = ActiveSaveRunCaptures;
			(activeSaveRunCaptures.Value ?? (activeSaveRunCaptures.Value = new Stack<RunSavedDataSaveRunCapture>())).Push(runSavedDataSaveRunCapture);
			return runSavedDataSaveRunCapture;
		}

		public static void CaptureCurrentSave(SerializableRun save)
		{
			Stack<RunSavedDataSaveRunCapture> value = ActiveSaveRunCaptures.Value;
			if (value != null && value.Count > 0)
			{
				value.Peek().Save = save;
			}
		}

		public static Task EndSaveRunCaptureAfter(Task originalTask, RunSavedDataSaveRunCapture capture)
		{
			return EndSaveRunCaptureAfterAsync(originalTask, capture);
		}

		public static bool TryInjectCurrentSaveBytes(string path, byte[] bytes, out byte[] injectedBytes)
		{
			injectedBytes = bytes;
			Stack<RunSavedDataSaveRunCapture> value = ActiveSaveRunCaptures.Value;
			RunSavedDataSaveRunCapture runSavedDataSaveRunCapture = ((value != null && value.Count > 0) ? value.Peek() : null);
			if (runSavedDataSaveRunCapture != null)
			{
				SerializableRun save = runSavedDataSaveRunCapture.Save;
				if (save != null && RunSavedDataRegistry.HasDocument(save) && string.Equals(path, runSavedDataSaveRunCapture.SavePath, StringComparison.OrdinalIgnoreCase))
				{
					try
					{
						byte[] array = RunSavedDataRegistry.InjectIntoUtf8Json(bytes, save);
						if (array == bytes)
						{
							return false;
						}
						injectedBytes = array;
						return true;
					}
					catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
					{
						RitsuLibFramework.Logger.Warn("[RunSavedData] Failed to inject run extension data: " + ex.Message, 1);
						return false;
					}
				}
			}
			return false;
		}

		private static async Task EndSaveRunCaptureAfterAsync(Task originalTask, RunSavedDataSaveRunCapture capture)
		{
			ArgumentNullException.ThrowIfNull(originalTask, "originalTask");
			try
			{
				await originalTask;
			}
			finally
			{
				EndSaveRunCapture(capture);
			}
		}

		private static void EndSaveRunCapture(RunSavedDataSaveRunCapture capture)
		{
			Stack<RunSavedDataSaveRunCapture> value = ActiveSaveRunCaptures.Value;
			if (value != null && value.Count > 0)
			{
				if (value.Peek() == capture)
				{
					value.Pop();
				}
				if (value.Count == 0)
				{
					ActiveSaveRunCaptures.Value = null;
				}
			}
		}

		private static bool TryGetCurrentRunIsMultiplayerHost()
		{
			//IL_0016: Unknown result type (might be due to invalid IL or missing references)
			//IL_001c: Invalid comparison between Unknown and I4
			try
			{
				return RunManager.Instance.ShouldSave && (int)RunManager.Instance.NetService.Type == 2;
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				return false;
			}
		}

		public static void WritePayload(PacketWriter writer, string? payload)
		{
			RitsuNetMessageTailExtensions.WriteLegacySingleBytes(writer, "ritsulib.runSavedData", 2, EncodePayload(payload));
		}

		internal static byte[]? EncodePayload(string? payload)
		{
			try
			{
				if (!string.IsNullOrWhiteSpace(payload))
				{
					int byteCount = Encoding.UTF8.GetByteCount(payload);
					if (byteCount <= 4194304)
					{
						return RitsuLibSidecarCompression.BrotliCompress(Encoding.UTF8.GetBytes(payload));
					}
					RitsuLibFramework.Logger.Warn($"[RunSavedData] Synchronized payload is {byteCount} UTF-8 bytes; maximum is {4194304} bytes.", 1);
				}
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[RunSavedData] Failed to encode synchronized payload: " + ex.Message, 1);
			}
			return null;
		}

		internal static string DecodePayload(ReadOnlySpan<byte> payload)
		{
			return Encoding.UTF8.GetString(Unbrotli(payload));
		}

		public static string? PrepareNewRunPayload(StartRunLobby lobby, string seed, IReadOnlyList<ModifierModel> modifiers)
		{
			try
			{
				RunSavedDataLobby.PublishStagingEvent(lobby, RunSavedDataLobbyStagingReason.Committing);
				return RunSavedDataRegistry.BuildLobbyStagingPayload(lobby);
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[RunSavedData] Failed to prepare new-run payload: " + ex.Message, 1);
				return null;
			}
		}

		public static string? TryReadPayload(PacketReader reader)
		{
			try
			{
				byte[] array = RitsuNetMessageTailExtensions.TryReadLegacySingleBytes(reader, "ritsulib.runSavedData", 2, 1, out var wasLegacyString);
				if (array == null)
				{
					return null;
				}
				return wasLegacyString ? Encoding.UTF8.GetString(array) : Encoding.UTF8.GetString(Unbrotli(array));
			}
			catch (InvalidDataException ex)
			{
				RitsuLibFramework.Logger.Warn("[RunSavedData] Failed to read synchronized payload: " + ex.Message, 1);
				return null;
			}
		}

		private static byte[] Unbrotli(ReadOnlySpan<byte> data)
		{
			if (RitsuLibSidecarCompression.TryBrotliDecompress(data, out byte[] decompressed))
			{
				return decompressed;
			}
			throw new InvalidDataException($"The synchronized payload is invalid or exceeds {4194304} decompressed bytes.");
		}
	}
