	internal static class RunSavedDataStartRunLobbyAccess
	{
		private static readonly ConditionalWeakTable<INetGameService, StartRunLobby> LobbyByNetService = new ConditionalWeakTable<INetGameService, StartRunLobby>();

		private static readonly Lock ActiveLobbySync = new Lock();

		private static readonly List<WeakReference<StartRunLobby>> ActiveLobbies = new List<WeakReference<StartRunLobby>>();

		private static readonly Func<string, ActModel?> GetActAccessor = AccessTools.MethodDelegate<Func<string, ActModel>>(AccessTools.DeclaredMethod(typeof(StartRunLobby), "GetAct", new Type[1] { typeof(string) }, (Type[])null), (object)null, true, (Type[])null);

		internal static void Track(StartRunLobby lobby)
		{
			LobbyByNetService.Remove(lobby.NetService);
			LobbyByNetService.Add(lobby.NetService, lobby);
			using (ActiveLobbySync.EnterScope())
			{
				ActiveLobbies.RemoveAll((WeakReference<StartRunLobby> reference) => !reference.TryGetTarget(out StartRunLobby target) || target == lobby);
				ActiveLobbies.Add(new WeakReference<StartRunLobby>(lobby));
			}
		}

		internal static void Untrack(StartRunLobby lobby)
		{
			LobbyByNetService.Remove(lobby.NetService);
			using (ActiveLobbySync.EnterScope())
			{
				ActiveLobbies.RemoveAll((WeakReference<StartRunLobby> reference) => !reference.TryGetTarget(out StartRunLobby target) || target == lobby);
			}
			RunSavedDataLobbyRuntime.RemoveSession(lobby);
		}

		internal static StartRunLobby? TryGetCurrentLobby()
		{
			INetGameService netService = RunManager.Instance.NetService;
			if (netService == null || !LobbyByNetService.TryGetValue(netService, out StartRunLobby value))
			{
				return null;
			}
			return value;
		}

		internal static StartRunLobby? TryFindSingleplayerLobby(CharacterModel character)
		{
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			//IL_0047: Invalid comparison between Unknown and I4
			//IL_0057: Unknown result type (might be due to invalid IL or missing references)
			using (ActiveLobbySync.EnterScope())
			{
				for (int num = ActiveLobbies.Count - 1; num >= 0; num--)
				{
					if (!ActiveLobbies[num].TryGetTarget(out StartRunLobby target))
					{
						ActiveLobbies.RemoveAt(num);
					}
					else if ((int)target.NetService.Type == 1 && target.Players.Count != 0 && IsSameCharacter(target.LocalPlayer.character, character))
					{
						return target;
					}
				}
			}
			return null;
		}

		private static bool IsSameCharacter(CharacterModel? left, CharacterModel right)
		{
			if (left != null)
			{
				if (left != right)
				{
					return ((AbstractModel)left).Id == ((AbstractModel)right).Id;
				}
				return true;
			}
			return false;
		}

		[UnsafeAccessor(UnsafeAccessorKind.Method, Name = "GetUnlockState")]
		internal static extern UnlockState GetUnlockState(StartRunLobby lobby);

		internal static ActModel? GetAct(string act1Key)
		{
			return GetActAccessor(act1Key);
		}
	}
