namespace STS2RitsuLib.Relics
{
	/// <summary>
	///     <para xml:lang="en">
	///         Stores mod-provided card candidates for Dusty Tome, which take precedence over the base game's unlocked
	///         Ancient card candidates.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         保存模组为尘封之书提供的候选卡牌；这些卡牌的优先级高于游戏本体已解锁的先古卡牌候选项。
	///     </para>
	/// </summary>
	internal static class DustyTomeCardRegistry
	{
		private sealed record DustyTomeCardMapping(ModelId? CharacterId, Type? CharacterType, Type CardType, string? ModId, long RegistrationOrder)
		{
			public string CharacterDescription => CharacterType?.FullName ?? ((object)CharacterId)?.ToString() ?? "<unknown>";

			public ModelId ResolveCharacterId()
			{
				return CharacterId ?? ModelDb.GetId(CharacterType);
			}
		}

		private sealed record DustyTomeCardCandidate(CardModel Card, long RegistrationOrder);

		private static readonly Lock Sync = new Lock();

		private static readonly List<DustyTomeCardMapping> ExplicitMappings = new List<DustyTomeCardMapping>();

		private static Dictionary<ModelId, IReadOnlyList<CardModel>>? _cacheByCharacter;

		private static long _nextRegistrationOrder;

		internal static bool TryGetPreferredCards(ModelId characterId, [NotNullWhen(true)] out IReadOnlyList<CardModel>? cards)
		{
			if (GetCache().TryGetValue(characterId, out cards) && cards.Count > 0)
			{
				return true;
			}
			cards = null;
			return false;
		}

		internal static void Register(ModelId characterId, Type ancientCardType, string? modIdForLog)
		{
			EnsureModelType(ancientCardType, typeof(CardModel), "ancientCardType");
			using (Sync.EnterScope())
			{
				ExplicitMappings.Add(new DustyTomeCardMapping(characterId, null, ancientCardType, modIdForLog, _nextRegistrationOrder++));
				_cacheByCharacter = null;
			}
		}

		internal static void Register(Type characterType, Type ancientCardType, string? modIdForLog)
		{
			EnsureModelType(characterType, typeof(CharacterModel), "characterType");
			EnsureModelType(ancientCardType, typeof(CardModel), "ancientCardType");
			using (Sync.EnterScope())
			{
				ExplicitMappings.Add(new DustyTomeCardMapping(null, characterType, ancientCardType, modIdForLog, _nextRegistrationOrder++));
				_cacheByCharacter = null;
			}
		}

		internal static void ValidateFrozenRegistrations()
		{
			DustyTomeCardMapping[] array;
			using (Sync.EnterScope())
			{
				array = ExplicitMappings.ToArray();
			}
			DustyTomeCardMapping[] array2 = array;
			foreach (DustyTomeCardMapping dustyTomeCardMapping in array2)
			{
				if (dustyTomeCardMapping.CharacterType != null)
				{
					RegistrationFreezeDiagnostics.WarnMissingModelType("DustyTomeCards", dustyTomeCardMapping.ModId, "Dusty Tome character", dustyTomeCardMapping.CharacterType, typeof(CharacterModel));
				}
				else
				{
					ModelId characterId = dustyTomeCardMapping.CharacterId;
					if (characterId != null)
					{
						RegistrationFreezeDiagnostics.WarnMissingModelId("DustyTomeCards", dustyTomeCardMapping.ModId, "Dusty Tome character", characterId, typeof(CharacterModel));
					}
				}
				RegistrationFreezeDiagnostics.WarnMissingModelType("DustyTomeCards", dustyTomeCardMapping.ModId, "Dusty Tome card for " + dustyTomeCardMapping.CharacterDescription, dustyTomeCardMapping.CardType, typeof(CardModel));
			}
		}

		private static Dictionary<ModelId, IReadOnlyList<CardModel>> GetCache()
		{
			using (Sync.EnterScope())
			{
				return _cacheByCharacter ?? (_cacheByCharacter = BuildCacheLocked());
			}
		}

		private static Dictionary<ModelId, IReadOnlyList<CardModel>> BuildCacheLocked()
		{
			Dictionary<ModelId, List<DustyTomeCardCandidate>> dictionary = new Dictionary<ModelId, List<DustyTomeCardCandidate>>();
			foreach (DustyTomeCardMapping explicitMapping in ExplicitMappings)
			{
				CardModel byIdOrNull = ModelDb.GetByIdOrNull<CardModel>(ModelDb.GetId(explicitMapping.CardType));
				if (byIdOrNull != null)
				{
					AddCandidate(dictionary, explicitMapping.ResolveCharacterId(), byIdOrNull, explicitMapping.RegistrationOrder, explicitMapping.ModId ?? explicitMapping.CardType.FullName ?? explicitMapping.CardType.Name);
				}
			}
			return ((IEnumerable<KeyValuePair<ModelId, List<DustyTomeCardCandidate>>>)dictionary).ToDictionary((Func<KeyValuePair<ModelId, List<DustyTomeCardCandidate>>, ModelId>)((KeyValuePair<ModelId, List<DustyTomeCardCandidate>> pair) => pair.Key), (Func<KeyValuePair<ModelId, List<DustyTomeCardCandidate>>, IReadOnlyList<CardModel>>)delegate(KeyValuePair<ModelId, List<DustyTomeCardCandidate>> pair)
			{
				List<CardModel> list = new List<CardModel>();
				list.AddRange((from candidate in pair.Value
					group candidate by ((AbstractModel)candidate.Card).Id into @group
					select @group.OrderBy((DustyTomeCardCandidate candidate) => candidate.RegistrationOrder).First().Card).OrderBy<CardModel, string>((CardModel card) => ((object)((AbstractModel)card).Id).ToString(), StringComparer.Ordinal));
				return new <>z__ReadOnlyList<CardModel>(list);
			});
		}

		private static void AddCandidate(Dictionary<ModelId, List<DustyTomeCardCandidate>> candidates, ModelId characterId, CardModel card, long registrationOrder, string source)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Invalid comparison between Unknown and I4
			if ((int)card.Rarity != 5)
			{
				RitsuLibFramework.Logger.Warn($"[DustyTomeCards] Ignoring non-Ancient Dusty Tome candidate {((AbstractModel)card).Id} from {source}.", 1);
			}
			else
			{
				if (!candidates.TryGetValue(characterId, out List<DustyTomeCardCandidate> value))
				{
					value = (candidates[characterId] = new List<DustyTomeCardCandidate>());
				}
				value.Add(new DustyTomeCardCandidate(card, registrationOrder));
			}
		}

		private static void EnsureModelType(Type modelType, Type requiredBase, string paramName)
		{
			ArgumentNullException.ThrowIfNull(modelType, paramName);
			ArgumentNullException.ThrowIfNull(requiredBase, "requiredBase");
			if (modelType.IsAbstract || modelType.IsInterface || modelType.ContainsGenericParameters || !requiredBase.IsAssignableFrom(modelType))
			{
				throw new ArgumentException($"Type '{modelType.FullName}' must be a closed concrete subtype of '{requiredBase.FullName}'.", paramName);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Stores mod-provided mappings for <see cref="T:MegaCrit.Sts2.Core.Models.Relics.ArchaicTooth" /> transcendence and
	///         <see cref="T:MegaCrit.Sts2.Core.Models.Relics.TouchOfOrobas" /> refinement.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         保存模组为 <see cref="T:MegaCrit.Sts2.Core.Models.Relics.ArchaicTooth" /> 超越和 <see cref="T:MegaCrit.Sts2.Core.Models.Relics.TouchOfOrobas" /> 精炼提供的映射。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Target models are stored as CLR <see cref="T:System.Type" /> values and resolved through
	///         <see cref="M:MegaCrit.Sts2.Core.Models.ModelDb.GetByIdOrNull``1(MegaCrit.Sts2.Core.Models.ModelId)" /> when a patch runs. Registration can therefore occur during a mod's
	///         <c>Apply()</c> method, before <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" /> has added mod content to <c>_contentById</c>. Starter keys
	///         use the metadata-only <see cref="M:MegaCrit.Sts2.Core.Models.ModelDb.GetId``1" /> method.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         目标模型以 CLR <see cref="T:System.Type" /> 值保存，并在补丁运行时通过 <see cref="M:MegaCrit.Sts2.Core.Models.ModelDb.GetByIdOrNull``1(MegaCrit.Sts2.Core.Models.ModelId)" />
	///         解析。因此，模组可在 <c>Apply()</c> 方法中、<see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" /> 尚未将模组内容加入
	///         <c>_contentById</c> 前完成注册。起始卡牌或遗物的键则通过仅使用元数据的
	///         <see cref="M:MegaCrit.Sts2.Core.Models.ModelDb.GetId``1" /> 方法取得。
	///     </para>
	/// </remarks>
	internal static class OrobasAncientUpgradeRegistry
	{
		private sealed record OrobasUpgradeMapping(ModelId? StarterId, Type? StarterType, Type TargetType, string? ModId, long RegistrationOrder)
		{
			public string StarterDescription => StarterType?.FullName ?? ((object)StarterId)?.ToString() ?? "<unknown>";

			public ModelId ResolveStarterId()
			{
				return StarterId ?? ModelDb.GetId(StarterType);
			}
		}

		private static readonly Lock Sync = new Lock();

		private static readonly List<OrobasUpgradeMapping> TranscendenceMappings = new List<OrobasUpgradeMapping>();

		private static readonly List<OrobasUpgradeMapping> RefinementMappings = new List<OrobasUpgradeMapping>();

		private static long _nextRegistrationOrder;

		internal static bool TryGetTranscendenceAncient(ModelId starterCardId, [NotNullWhen(true)] out CardModel? ancientTemplate)
		{
			//IL_004a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0050: Invalid comparison between Unknown and I4
			OrobasUpgradeMapping orobasUpgradeMapping;
			using (Sync.EnterScope())
			{
				orobasUpgradeMapping = FindLatestMappingLocked(TranscendenceMappings, starterCardId);
				if (orobasUpgradeMapping == null)
				{
					ancientTemplate = null;
					return false;
				}
			}
			ancientTemplate = ModelDb.GetByIdOrNull<CardModel>(ModelDb.GetId(orobasUpgradeMapping.TargetType));
			CardModel val = ancientTemplate;
			if (val != null && (int)val.Rarity == 5)
			{
				return true;
			}
			ancientTemplate = null;
			return false;
		}

		internal static bool TryGetRefinementUpgrade(ModelId starterRelicId, [NotNullWhen(true)] out RelicModel? upgradedTemplate)
		{
			OrobasUpgradeMapping orobasUpgradeMapping;
			using (Sync.EnterScope())
			{
				orobasUpgradeMapping = FindLatestMappingLocked(RefinementMappings, starterRelicId);
				if (orobasUpgradeMapping == null)
				{
					upgradedTemplate = null;
					return false;
				}
			}
			upgradedTemplate = ModelDb.GetByIdOrNull<RelicModel>(ModelDb.GetId(orobasUpgradeMapping.TargetType));
			return upgradedTemplate != null;
		}

		internal static bool HasTranscendenceStarter(ModelId starterCardId)
		{
			//IL_003f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0045: Invalid comparison between Unknown and I4
			OrobasUpgradeMapping orobasUpgradeMapping;
			using (Sync.EnterScope())
			{
				orobasUpgradeMapping = FindLatestMappingLocked(TranscendenceMappings, starterCardId);
			}
			if (orobasUpgradeMapping != null)
			{
				CardModel byIdOrNull = ModelDb.GetByIdOrNull<CardModel>(ModelDb.GetId(orobasUpgradeMapping.TargetType));
				if (byIdOrNull != null)
				{
					return (int)byIdOrNull.Rarity == 5;
				}
				return false;
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the distinct Ancient card templates registered by mods for
		///         <see cref="P:MegaCrit.Sts2.Core.Models.Relics.ArchaicTooth.TranscendenceCards" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回模组为 <see cref="P:MegaCrit.Sts2.Core.Models.Relics.ArchaicTooth.TranscendenceCards" /> 注册的、不重复的先古卡牌模板。
		///     </para>
		/// </summary>
		internal static IReadOnlyList<CardModel> GetRegisteredTranscendenceAncientTemplates()
		{
			Type[] source;
			using (Sync.EnterScope())
			{
				source = TranscendenceMappings.Select((OrobasUpgradeMapping mapping) => mapping.TargetType).Distinct().OrderBy<Type, string>((Type t) => t.FullName ?? t.Name, StringComparer.Ordinal)
					.ToArray();
			}
			HashSet<ModelId> seen = new HashSet<ModelId>();
			return (from card in source.Select((Type ancientType) => ModelDb.GetByIdOrNull<CardModel>(ModelDb.GetId(ancientType))).OfType<CardModel>().Where(delegate(CardModel card)
				{
					//IL_0001: Unknown result type (might be due to invalid IL or missing references)
					//IL_0007: Invalid comparison between Unknown and I4
					return (int)card.Rarity == 5;
				})
				where seen.Add(((AbstractModel)card).Id)
				select card).ToList();
		}

		internal static void RegisterTranscendence(ModelId starterCardId, Type ancientCardType, string? modIdForLog)
		{
			EnsureModelType(ancientCardType, typeof(CardModel), "ancientCardType");
			using (Sync.EnterScope())
			{
				OrobasUpgradeMapping orobasUpgradeMapping = FindLatestExactMappingLocked(TranscendenceMappings, starterCardId, null);
				if (orobasUpgradeMapping != null && orobasUpgradeMapping.TargetType != ancientCardType)
				{
					RitsuLibFramework.Logger.Warn($"[OrobasAncientUpgrades] Transcendence mapping for starter card {starterCardId} was replaced{(string.IsNullOrEmpty(modIdForLog) ? "" : (" (mod " + modIdForLog + ")"))}.", 1);
				}
				RemoveExactMappingsLocked(TranscendenceMappings, starterCardId, null);
				TranscendenceMappings.Add(new OrobasUpgradeMapping(starterCardId, null, ancientCardType, modIdForLog, _nextRegistrationOrder++));
			}
		}

		internal static void RegisterTranscendence(Type starterCardType, Type ancientCardType, string? modIdForLog)
		{
			EnsureModelType(starterCardType, typeof(CardModel), "starterCardType");
			EnsureModelType(ancientCardType, typeof(CardModel), "ancientCardType");
			using (Sync.EnterScope())
			{
				OrobasUpgradeMapping orobasUpgradeMapping = FindLatestExactMappingLocked(TranscendenceMappings, null, starterCardType);
				if (orobasUpgradeMapping != null && orobasUpgradeMapping.TargetType != ancientCardType)
				{
					RitsuLibFramework.Logger.Warn($"[OrobasAncientUpgrades] Transcendence mapping for starter card type {starterCardType.FullName} was replaced{(string.IsNullOrEmpty(modIdForLog) ? "" : (" (mod " + modIdForLog + ")"))}.", 1);
				}
				RemoveExactMappingsLocked(TranscendenceMappings, null, starterCardType);
				TranscendenceMappings.Add(new OrobasUpgradeMapping(null, starterCardType, ancientCardType, modIdForLog, _nextRegistrationOrder++));
			}
		}

		internal static void RegisterRefinement(ModelId starterRelicId, Type upgradedRelicType, string? modIdForLog)
		{
			EnsureModelType(upgradedRelicType, typeof(RelicModel), "upgradedRelicType");
			using (Sync.EnterScope())
			{
				OrobasUpgradeMapping orobasUpgradeMapping = FindLatestExactMappingLocked(RefinementMappings, starterRelicId, null);
				if (orobasUpgradeMapping != null && orobasUpgradeMapping.TargetType != upgradedRelicType)
				{
					RitsuLibFramework.Logger.Warn($"[OrobasAncientUpgrades] Refinement mapping for starter relic {starterRelicId} was replaced{(string.IsNullOrEmpty(modIdForLog) ? "" : (" (mod " + modIdForLog + ")"))}.", 1);
				}
				RemoveExactMappingsLocked(RefinementMappings, starterRelicId, null);
				RefinementMappings.Add(new OrobasUpgradeMapping(starterRelicId, null, upgradedRelicType, modIdForLog, _nextRegistrationOrder++));
			}
		}

		internal static void RegisterRefinement(Type starterRelicType, Type upgradedRelicType, string? modIdForLog)
		{
			EnsureModelType(starterRelicType, typeof(RelicModel), "starterRelicType");
			EnsureModelType(upgradedRelicType, typeof(RelicModel), "upgradedRelicType");
			using (Sync.EnterScope())
			{
				OrobasUpgradeMapping orobasUpgradeMapping = FindLatestExactMappingLocked(RefinementMappings, null, starterRelicType);
				if (orobasUpgradeMapping != null && orobasUpgradeMapping.TargetType != upgradedRelicType)
				{
					RitsuLibFramework.Logger.Warn($"[OrobasAncientUpgrades] Refinement mapping for starter relic type {starterRelicType.FullName} was replaced{(string.IsNullOrEmpty(modIdForLog) ? "" : (" (mod " + modIdForLog + ")"))}.", 1);
				}
				RemoveExactMappingsLocked(RefinementMappings, null, starterRelicType);
				RefinementMappings.Add(new OrobasUpgradeMapping(null, starterRelicType, upgradedRelicType, modIdForLog, _nextRegistrationOrder++));
			}
		}

		internal static void ValidateFrozenRegistrations()
		{
			//IL_0074: Unknown result type (might be due to invalid IL or missing references)
			//IL_007a: Invalid comparison between Unknown and I4
			OrobasUpgradeMapping[] array;
			OrobasUpgradeMapping[] array2;
			using (Sync.EnterScope())
			{
				array = TranscendenceMappings.ToArray();
				array2 = RefinementMappings.ToArray();
			}
			OrobasUpgradeMapping[] array3 = array;
			foreach (OrobasUpgradeMapping orobasUpgradeMapping in array3)
			{
				ValidateMapping(orobasUpgradeMapping, "Transcendence", typeof(CardModel), typeof(CardModel));
				CardModel byIdOrNull = ModelDb.GetByIdOrNull<CardModel>(ModelDb.GetId(orobasUpgradeMapping.TargetType));
				if (byIdOrNull != null && (int)byIdOrNull.Rarity != 5)
				{
					RitsuLibFramework.Logger.Warn($"[OrobasAncientUpgrades] Ignoring non-Ancient transcendence target {((AbstractModel)byIdOrNull).Id} for {orobasUpgradeMapping.StarterDescription}.", 1);
				}
			}
			array3 = array2;
			for (int i = 0; i < array3.Length; i++)
			{
				ValidateMapping(array3[i], "Refinement", typeof(RelicModel), typeof(RelicModel));
			}
		}

		private static void ValidateMapping(OrobasUpgradeMapping mapping, string kind, Type starterBaseType, Type targetBaseType)
		{
			if (mapping.StarterType != null)
			{
				RegistrationFreezeDiagnostics.WarnMissingModelType("OrobasAncientUpgrades", mapping.ModId, kind + " starter", mapping.StarterType, starterBaseType);
			}
			else
			{
				ModelId starterId = mapping.StarterId;
				if (starterId != null)
				{
					RegistrationFreezeDiagnostics.WarnMissingModelId("OrobasAncientUpgrades", mapping.ModId, kind + " starter", starterId, starterBaseType);
				}
			}
			RegistrationFreezeDiagnostics.WarnMissingModelType("OrobasAncientUpgrades", mapping.ModId, kind + " target for " + mapping.StarterDescription, mapping.TargetType, targetBaseType);
		}

		private static OrobasUpgradeMapping? FindLatestMappingLocked(IEnumerable<OrobasUpgradeMapping> mappings, ModelId starterId)
		{
			return (from mapping in mappings
				where mapping.ResolveStarterId() == starterId
				orderby mapping.RegistrationOrder descending
				select mapping).FirstOrDefault();
		}

		private static OrobasUpgradeMapping? FindLatestExactMappingLocked(IEnumerable<OrobasUpgradeMapping> mappings, ModelId? starterId, Type? starterType)
		{
			return (from mapping in mappings
				where mapping.StarterId == starterId && mapping.StarterType == starterType
				orderby mapping.RegistrationOrder descending
				select mapping).FirstOrDefault();
		}

		private static void RemoveExactMappingsLocked(List<OrobasUpgradeMapping> mappings, ModelId? starterId, Type? starterType)
		{
			mappings.RemoveAll((OrobasUpgradeMapping mapping) => mapping.StarterId == starterId && mapping.StarterType == starterType);
		}

		private static void EnsureModelType(Type modelType, Type requiredBase, string paramName)
		{
			ArgumentNullException.ThrowIfNull(modelType, paramName);
			ArgumentNullException.ThrowIfNull(requiredBase, "requiredBase");
			if (modelType.IsAbstract || modelType.IsInterface || modelType.ContainsGenericParameters || !requiredBase.IsAssignableFrom(modelType))
			{
				throw new ArgumentException($"Type '{modelType.FullName}' must be a closed concrete subtype of '{requiredBase.FullName}'.", paramName);
			}
		}
	}
}
namespace STS2RitsuLib.Relics.Visibility
{
	/// <summary>
	///     <para xml:lang="en">
	///         Implement on a <see cref="T:MegaCrit.Sts2.Core.Models.RelicModel" /> to control whether RitsuLib creates ordinary relic UI for it.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在 <see cref="T:MegaCrit.Sts2.Core.Models.RelicModel" /> 上实现此接口，以控制 RitsuLib 是否为该遗物创建常规遗物界面。
	///     </para>
	/// </summary>
	public interface IModRelicVisibility
	{
		/// <summary>
		///     <para xml:lang="en">Gets whether the relic should appear in ordinary relic UI.</para>
		///     <para xml:lang="zh-CN">获取该遗物是否应显示在常规遗物界面中。</para>
		/// </summary>
		bool IsRelicVisible { get; }
	}
	/// <summary>
	///     <para xml:lang="en">Provides a runtime registry of mod-defined relic visibility rules.</para>
	///     <para xml:lang="zh-CN">提供模组自定义遗物可见性规则的运行时注册表。</para>
	/// </summary>
	public static class ModRelicVisibilityRegistry
	{
		private sealed class VisibilityRuleRegistration(string modId, Func<RelicModel, bool> isVisible) : IDisposable
		{
			private bool _disposed;

			public string ModId { get; } = modId;

			public Func<RelicModel, bool> IsVisible { get; } = isVisible;

			public void Dispose()
			{
				if (_disposed)
				{
					return;
				}
				_disposed = true;
				using (SyncRoot.EnterScope())
				{
					Rules.Remove(this);
				}
			}
		}

		private static readonly Lock SyncRoot = new Lock();

		private static readonly List<VisibilityRuleRegistration> Rules = new List<VisibilityRuleRegistration>();

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a visibility rule. Returning <see langword="false" /> from the rule hides the relic.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册可见性规则。规则返回 <see langword="false" /> 时会隐藏相应遗物。
		///     </para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">A handle whose disposal unregisters the rule.</para>
		///     <para xml:lang="zh-CN">释放后会注销该规则的句柄。</para>
		/// </returns>
		public static IDisposable Register(string modId, Func<RelicModel, bool> isVisible)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentNullException.ThrowIfNull(isVisible, "isVisible");
			VisibilityRuleRegistration visibilityRuleRegistration = new VisibilityRuleRegistration(modId, isVisible);
			using (SyncRoot.EnterScope())
			{
				Rules.Add(visibilityRuleRegistration);
				return visibilityRuleRegistration;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Returns whether a relic should appear in ordinary relic UI.</para>
		///     <para xml:lang="zh-CN">返回遗物是否应显示在常规遗物界面中。</para>
		/// </summary>
		public static bool IsVisible(RelicModel relic)
		{
			ArgumentNullException.ThrowIfNull(relic, "relic");
			if (relic is IModRelicVisibility { IsRelicVisible: false })
			{
				return false;
			}
			VisibilityRuleRegistration[] array;
			using (SyncRoot.EnterScope())
			{
				array = Rules.ToArray();
			}
			VisibilityRuleRegistration[] array2 = array;
			foreach (VisibilityRuleRegistration visibilityRuleRegistration in array2)
			{
				try
				{
					if (!visibilityRuleRegistration.IsVisible(relic))
					{
						return false;
					}
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[RelicVisibility] Rule from '{visibilityRuleRegistration.ModId}' failed for relic '{((AbstractModel)relic).Id}': {ex.Message}", 1);
				}
			}
			return true;
		}

		internal static int GetVisibleIndex(RelicModel relic, int vanillaIndex)
		{
			if (vanillaIndex <= 0)
			{
				return vanillaIndex;
			}
			try
			{
				IReadOnlyList<RelicModel> relics = relic.Owner.Relics;
				int num = Math.Min(vanillaIndex, relics.Count);
				int num2 = 0;
				for (int i = 0; i < num; i++)
				{
					if (IsVisible(relics[i]))
					{
						num2++;
					}
				}
				return num2;
			}
			catch
			{
				return vanillaIndex;
			}
		}
	}
	internal static class ModRelicVisibilityUi
	{
		private delegate void InventoryAddDelegate(NRelicInventory inventory, RelicModel relic, bool startsShown, int index);

		private static readonly FieldRef<NRelicInventory, Player?> PlayerRef = AccessTools.FieldRefAccess<NRelicInventory, Player>("_player");

		private static readonly FieldRef<NRelicInventory, List<NRelicInventoryHolder>> RelicNodesRef = AccessTools.FieldRefAccess<NRelicInventory, List<NRelicInventoryHolder>>("_relicNodes");

		private static readonly InventoryAddDelegate? AddRelic = AccessTools.Method(typeof(NRelicInventory), "Add", new Type[3]
		{
			typeof(RelicModel),
			typeof(bool),
			typeof(int)
		}, (Type[])null)?.CreateDelegate<InventoryAddDelegate>();

		private static readonly Action<NRelicInventory>? UpdateNavigation = AccessTools.Method(typeof(NRelicInventory), "UpdateNavigation", (Type[])null, (Type[])null)?.CreateDelegate<Action<NRelicInventory>>();

		public static bool Contains(NRelicInventory inventory, RelicModel relic)
		{
			return RelicNodesRef.Invoke(inventory).Any((NRelicInventoryHolder holder) => holder.Relic.Model == relic);
		}

		public static bool Refresh(NRelicInventory? inventory)
		{
			//IL_00fa: Unknown result type (might be due to invalid IL or missing references)
			if (inventory == null || AddRelic == null)
			{
				return false;
			}
			Player val = PlayerRef.Invoke(inventory);
			if (val == null)
			{
				return false;
			}
			List<NRelicInventoryHolder> list = RelicNodesRef.Invoke(inventory);
			bool flag = RemoveHiddenNodes(inventory, list);
			int num = 0;
			foreach (RelicModel relic in val.Relics)
			{
				if (!ModRelicVisibilityRegistry.IsVisible(relic))
				{
					continue;
				}
				NRelicInventoryHolder val2 = list.FirstOrDefault((NRelicInventoryHolder node) => node.Relic.Model == relic);
				bool flag2 = false;
				if (val2 == null)
				{
					AddRelic(inventory, relic, startsShown: true, -1);
					val2 = list.FirstOrDefault((NRelicInventoryHolder node) => node.Relic.Model == relic);
					flag2 = val2 != null;
				}
				if (val2 != null)
				{
					flag |= flag2;
					flag |= MoveToVisibleIndex(inventory, list, val2, num);
					num++;
				}
			}
			if (!flag)
			{
				return false;
			}
			((GodotObject)inventory).EmitSignal(SignalName.RelicsChanged, Array.Empty<Variant>());
			UpdateNavigation?.Invoke(inventory);
			return true;
		}

		private static bool RemoveHiddenNodes(NRelicInventory inventory, List<NRelicInventoryHolder> nodes)
		{
			bool result = false;
			NRelicInventoryHolder[] array = nodes.ToArray();
			foreach (NRelicInventoryHolder val in array)
			{
				if (!ModRelicVisibilityRegistry.IsVisible(val.Relic.Model))
				{
					nodes.Remove(val);
					((Node)inventory).RemoveChild((Node)(object)val);
					((Node)val).QueueFree();
					result = true;
				}
			}
			return result;
		}

		private static bool MoveToVisibleIndex(NRelicInventory inventory, List<NRelicInventoryHolder> nodes, NRelicInventoryHolder holder, int visibleIndex)
		{
			int num = nodes.IndexOf(holder);
			if (num == visibleIndex)
			{
				return false;
			}
			if (num >= 0)
			{
				nodes.RemoveAt(num);
			}
			int num2 = Math.Clamp(visibleIndex, 0, nodes.Count);
			nodes.Insert(num2, holder);
			((Node)inventory).MoveChild((Node)(object)holder, num2);
			return true;
		}
	}
}
namespace STS2RitsuLib.Relics.Visibility.Patches
{
	internal sealed class NRelicInventoryAddVisibilityPatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_relic_visibility_inventory_add";

		public static bool IsCritical => false;

		public static string Description => "Skip hidden relics in the local relic inventory";

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NRelicInventory), "Add", new Type[3]
				{
					typeof(RelicModel),
					typeof(bool),
					typeof(int)
				})
			};
		}

		public static bool Prefix(RelicModel relic, ref int index)
		{
			if (!ModRelicVisibilityRegistry.IsVisible(relic))
			{
				return false;
			}
			if (index >= 0)
			{
				index = ModRelicVisibilityRegistry.GetVisibleIndex(relic, index);
			}
			return true;
		}
	}
	internal sealed class NRelicInventoryRemoveVisibilityPatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_relic_visibility_inventory_remove";

		public static bool IsCritical => false;

		public static string Description => "Skip hidden relic removal from the local relic inventory";

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NRelicInventory), "Remove", new Type[1] { typeof(RelicModel) })
			};
		}

		public static bool Prefix(NRelicInventory __instance, RelicModel relic)
		{
			if (!ModRelicVisibilityRegistry.IsVisible(relic))
			{
				return ModRelicVisibilityUi.Contains(__instance, relic);
			}
			return true;
		}
	}
