	/// <summary>
	///     <para xml:lang="en">
	///         Applies mod-provided transcendence templates while preserving upgrades and enchantments as the base game does.
	///     </para>
	///     <para xml:lang="zh-CN">应用模组提供的超越模板，并依照游戏本体的方式继承升级与附魔。</para>
	/// </summary>
	internal sealed class ArchaicToothGetTranscendenceTransformedCardPatch : IPatchMethod
	{
		public static string PatchId => "archaic_tooth_transcendence_transform_mod";

		public static string Description => "Apply RitsuLib-registered ArchaicTooth transcendence card transforms";

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ArchaicTooth), "GetTranscendenceTransformedCard", new Type[1] { typeof(CardModel) })
			};
		}

		public static bool Prefix(CardModel starterCard, ref CardModel __result)
		{
			//IL_005c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0062: Expected O, but got Unknown
			if (!OrobasAncientUpgradeRegistry.TryGetTranscendenceAncient(((AbstractModel)starterCard).Id, out CardModel ancientTemplate))
			{
				return true;
			}
			CardModel val = ((ICardScope)starterCard.Owner.RunState).CreateCard(ancientTemplate, starterCard.Owner);
			for (int i = 0; i < starterCard.CurrentUpgradeLevel; i++)
			{
				if (!val.IsUpgradable)
				{
					break;
				}
				CardCmd.Upgrade(val, (CardPreviewStyle)1);
			}
			if (starterCard.Enchantment != null)
			{
				EnchantmentModel val2 = (EnchantmentModel)((AbstractModel)starterCard.Enchantment).MutableClone();
				CardCmd.Enchant(val2, val, (decimal)val2.Amount);
			}
			__result = val;
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Adds mod-provided Ancient card targets to <see cref="P:MegaCrit.Sts2.Core.Models.Relics.ArchaicTooth.TranscendenceCards" /> for Dusty Tome and
