	/// <summary>
	///     <para xml:lang="en">
	///         Lets mods provide per-character Ancient card candidates for Dusty Tome before the base game chooses from
	///         unlocked cards.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         允许模组按角色为尘封之书提供先古卡牌候选项，其优先级高于游戏本体从已解锁卡牌中进行的选择。
	///     </para>
	/// </summary>
	internal sealed class DustyTomeSetupForPlayerPatch : IPatchMethod
	{
		public static string PatchId => "dusty_tome_mod_ancient_cards";

		public static string Description => "Prefer RitsuLib-registered Dusty Tome ancient card candidates";

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(DustyTome), "SetupForPlayer", new Type[1] { typeof(Player) })
			};
		}

		public static bool Prefix(DustyTome __instance, Player player)
		{
			//IL_007c: Unknown result type (might be due to invalid IL or missing references)
			if (DustyTomeCardRegistry.TryGetPreferredCards(((AbstractModel)player.Character).Id, out IReadOnlyList<CardModel> cards))
			{
				ModelId val = SelectCardId(player, cards);
				if (val != null)
				{
					__instance.AncientCard = val;
					return false;
				}
			}
			HashSet<ModelId> transcendenceCardIds = ArchaicTooth.TranscendenceCards.Select((CardModel card) => ((AbstractModel)card).Id).ToHashSet();
			CardModel[] array = player.Character.CardPool.GetUnlockedCards(player.UnlockState, player.RunState.CardMultiplayerConstraint).Where(delegate(CardModel card)
			{
				//IL_0001: Unknown result type (might be due to invalid IL or missing references)
				//IL_0007: Invalid comparison between Unknown and I4
				return (int)card.Rarity == 5 && !transcendenceCardIds.Contains(((AbstractModel)card).Id);
			}).ToArray();
			if (array.Length != 0)
			{
				ModelId val2 = SelectCardId(player, array);
				if (val2 != null)
				{
					__instance.AncientCard = val2;
					return false;
				}
			}
			CardModel[] array2 = player.Character.CardPool.AllCards.Where(delegate(CardModel card)
			{
				//IL_0001: Unknown result type (might be due to invalid IL or missing references)
				//IL_0007: Invalid comparison between Unknown and I4
				return (int)card.Rarity == 5 && !transcendenceCardIds.Contains(((AbstractModel)card).Id);
			}).ToArray();
			if (array2.Length == 0)
			{
				return true;
			}
			RitsuLibFramework.Logger.Warn($"[DustyTomeCards] {((AbstractModel)player.Character).Id} has no unlocked non-transcendence Ancient cards; " + "falling back to locked character-pool Ancient cards to avoid Dusty Tome setup failure.", 1);
			ModelId val3 = SelectCardId(player, array2);
			if (val3 == null)
			{
				return true;
			}
			__instance.AncientCard = val3;
			return false;
		}

		private static ModelId? SelectCardId(Player player, IReadOnlyList<CardModel> candidates)
		{
			CardModel obj = player.PlayerRng.Rewards.NextItem<CardModel>((IEnumerable<CardModel>)candidates);
			if (obj == null)
			{
				return null;
			}
			return ((AbstractModel)obj).Id;
		}
	}
