namespace STS2RitsuLib.Platform
{
	/// <summary>
	///     <para xml:lang="en">
	///         Preloads Linux unwind libraries with <c>RTLD_GLOBAL</c> so Harmony's native runtime can resolve their
	///         symbols. Loading is attempted once and only on Linux.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         使用 <c>RTLD_GLOBAL</c> 预加载 Linux 的栈展开库，使 Harmony 的原生运行时能够解析其符号。
	///         仅在 Linux 上尝试加载一次。
	///     </para>
	/// </summary>
	internal static class LinuxHarmonyNativePreloader
	{
		private const int RtldNow = 2;

		private const int RtldGlobal = 256;

		private const int DlopenFlags = 258;

		private static readonly Lock SyncRoot = new Lock();

		private static readonly List<nint> Handles = new List<nint>();

		private static bool _attempted;

		private static readonly string[] CandidateLibraries = new string[3] { "libgcc_s.so.1", "libunwind.so.8", "libunwind.so" };

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts the one-time preload and reports loaded libraries or failures through the supplied
		///         callbacks. It does nothing on non-Linux hosts.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试执行一次预加载，并通过提供的回调报告已加载的库或失败信息。在非 Linux 宿主上不执行任何操作。
		///     </para>
		/// </summary>
		public static void EnsureLoaded(Action<string> info, Action<string> warn)
		{
			ArgumentNullException.ThrowIfNull(info, "info");
			ArgumentNullException.ThrowIfNull(warn, "warn");
			if (!RuntimeInformation.IsOSPlatform(OSPlatform.Linux))
			{
				return;
			}
			using (SyncRoot.EnterScope())
			{
				if (!_attempted)
				{
					_attempted = true;
					TryLoadLinuxNativeLibraries(info, warn);
				}
			}
		}

		[DllImport("libdl.so.2", CharSet = CharSet.Ansi, EntryPoint = "dlopen")]
		private static extern nint Dlopen(string filename, int flags);

		[DllImport("libdl.so.2", EntryPoint = "dlerror")]
		private static extern nint Dlerror();

		private static void TryLoadLinuxNativeLibraries(Action<string> info, Action<string> warn)
		{
			List<string> list = new List<string>();
			List<string> list2 = new List<string>();
			try
			{
				string[] candidateLibraries = CandidateLibraries;
				foreach (string text in candidateLibraries)
				{
					nint num = Dlopen(text, 258);
					if (num != IntPtr.Zero)
					{
						Handles.Add(num);
						list.Add(text);
					}
					else
					{
						list2.Add(text + ": " + GetLastDlError());
					}
				}
			}
			catch (DllNotFoundException ex)
			{
				warn("Linux Harmony native preload skipped: libdl.so.2 is unavailable (" + ex.Message + ").");
				return;
			}
			catch (EntryPointNotFoundException ex2)
			{
				warn("Linux Harmony native preload skipped: libdl.so.2 is missing dlopen/dlerror (" + ex2.Message + ").");
				return;
			}
			catch (Exception ex3)
			{
				warn("Linux Harmony native preload failed unexpectedly: " + ex3.Message);
				return;
			}
			if (list.Count > 0)
			{
				info("Linux Harmony native preload loaded with RTLD_GLOBAL: " + string.Join(", ", list) + ".");
			}
			else
			{
				warn("Linux Harmony native preload could not load libgcc/libunwind candidates; Harmony may still work if the host already exports unwind symbols. Tried: " + string.Join("; ", list2));
			}
		}

		private static string GetLastDlError()
		{
			nint num = Dlerror();
			object obj;
			if (num != IntPtr.Zero)
			{
				obj = Marshal.PtrToStringAnsi(num);
				if (obj == null)
				{
					return "unknown dlopen error";
				}
			}
			else
			{
				obj = "unknown dlopen error";
			}
			return (string)obj;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Detects mobile launchers that run the PC assembly with a no-op Steam native stub and patched platform
	///         initialization. Such sessions can appear Steam-backed, but Steamworks.NET entry points and Steam
	///         transport Sidecar hooks are unsafe.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         检测使用无操作 Steam 原生桩和已修补平台初始化来运行 PC 程序集的移动端启动器。这类会话可能显示为
	///         Steam 支持，但 Steamworks.NET 入口点和 Steam 传输 Sidecar 钩子均不安全。
	///     </para>
	/// </summary>
	internal static class RitsuLibMobileSteamRuntime
	{
		/// <summary>
		///     <para xml:lang="en">Gets whether native Steam integration must be suppressed for the current mobile host.</para>
		///     <para xml:lang="zh-CN">获取当前移动端宿主是否必须禁用原生 Steam 集成。</para>
		/// </summary>
		internal static bool SuppressNativeSteamIntegration
		{
			get
			{
				if (!OperatingSystem.IsAndroid())
				{
					return OperatingSystem.IsIOS();
				}
				return true;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Logs the mobile-host Steam restrictions once startup begins.</para>
		///     <para xml:lang="zh-CN">在启动阶段记录移动端宿主的 Steam 功能限制。</para>
		/// </summary>
		internal static void LogSuppressedSteamFeaturesAtStartup()
		{
			if (SuppressNativeSteamIntegration)
			{
				RitsuLibFramework.Logger.Info("[MobileSteam] Native Steamworks calls are disabled on this mobile host. Mod data cloud sync remains available when the host provides the game's cloud save store.", 1);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Detects Steam Proton launches from the compatibility environment variables supplied to the
	///         process.
	///     </para>
	///     <para xml:lang="zh-CN">根据进程获得的兼容环境变量检测 Steam Proton 启动。</para>
	/// </summary>
	internal static class SteamCompatibilityRuntime
	{
		private static readonly bool HasSteamCompatDataPath = HasEnvironmentValue("STEAM_COMPAT_DATA_PATH");

		private static readonly bool HasSteamCompatClientInstallPath = HasEnvironmentValue("STEAM_COMPAT_CLIENT_INSTALL_PATH");

		private static readonly bool HasWinePrefix = HasEnvironmentValue("WINEPREFIX");

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether the process has the Steam compatibility-data, client-install, and Wine-prefix
		///         launch markers.
		///     </para>
		///     <para xml:lang="zh-CN">获取进程是否具有 Steam 兼容数据、客户端安装位置及 Wine 前缀启动标记。</para>
		/// </summary>
		public static bool IsProtonLaunch
		{
			get
			{
				if (HasSteamCompatDataPath && HasSteamCompatClientInstallPath)
				{
					if (!HasWinePrefix)
					{
						return RuntimeInformation.IsOSPlatform(OSPlatform.Windows);
					}
					return true;
				}
				return false;
			}
		}

		private static bool HasEnvironmentValue(string name)
		{
			return !string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable(name));
		}
	}
}
namespace STS2RitsuLib.Platform.Steam
