			private static IReadOnlyDictionary<ulong, LocalWorkshopManifest> BuildLocalManifestByWorkshopItemId()
			{
				try
				{
					Dictionary<ulong, LocalWorkshopManifest> dictionary = new Dictionary<ulong, LocalWorkshopManifest>();
					foreach (RitsuModInfo item in Sts2ModManagerCompat.BuildModInfos(null, RitsuModSource.SteamWorkshop))
					{
						ulong? workshopItemId = item.WorkshopItemId;
						if (workshopItemId.HasValue)
						{
							ulong valueOrDefault = workshopItemId.GetValueOrDefault();
							if (valueOrDefault != 0L)
							{
								dictionary.TryAdd(valueOrDefault, new LocalWorkshopManifest(item.Id, item.Name, item.Author));
							}
						}
					}
					return dictionary;
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn("[SteamWorkshopUpdate] Failed to read Workshop manifest data from ModManager: " + ex.Message, 1);
