			private static LocalWorkshopManifest TryReadLocalManifest(string? folderPath)
			{
				if (string.IsNullOrWhiteSpace(folderPath))
				{
					return default(LocalWorkshopManifest);
				}
				string key = folderPath.Trim();
				using (ManifestCacheSyncRoot.EnterScope())
				{
					if (LocalManifestCache.TryGetValue(key, out var value))
					{
						return value;
					}
				}
				try
				{
					string text = FindLocalManifestPath(key);
					if (text == null)
					{
						return Cache(default(LocalWorkshopManifest));
					}
					using JsonDocument jsonDocument = JsonDocument.Parse(File.ReadAllText(text));
					JsonElement rootElement = jsonDocument.RootElement;
					return Cache(new LocalWorkshopManifest(ReadString(rootElement, "id") ?? ReadString(rootElement, "mod_id"), ReadString(rootElement, "name") ?? ReadString(rootElement, "display_name"), ReadAuthor(rootElement)));
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn("[SteamWorkshopUpdate] Failed to read local Workshop manifest '" + key + "': " + ex.Message, 1);
					return Cache(default(LocalWorkshopManifest));
				}
				LocalWorkshopManifest Cache(LocalWorkshopManifest manifest)
				{
					using (ManifestCacheSyncRoot.EnterScope())
					{
						LocalManifestCache[key] = manifest;
						return manifest;
					}
				}
			}

			private static string? FindLocalManifestPath(string folderPath)
			{
				string text = Path.Combine(folderPath, "mod_manifest.json");
				if (!File.Exists(text))
				{
					return null;
				}
				return text;
			}

			private static string? ReadAuthor(JsonElement root)
			{
