		private static Assembly? ResolveSteamworksAssembly()
		{
			Type type = Type.GetType("Steamworks.CSteamID, Steamworks.NET", throwOnError: false);
			if (type != null)
			{
				return type.Assembly;
			}
			return AppDomain.CurrentDomain.GetAssemblies().FirstOrDefault((Assembly assembly) => assembly.GetType("Steamworks.SteamUGC", throwOnError: false) != null);
		}

		private static ItemStateFlags ResolveItemStateFlags(Assembly steamworksAssembly)
		{
			Type type = steamworksAssembly.GetType("Steamworks.EItemState", throwOnError: false);
			if (type == null)
			{
				return ItemStateFlags.Default;
			}
			return new ItemStateFlags(GetEnumFlag(type, "k_EItemStateSubscribed", ItemStateFlags.Default.Subscribed), GetEnumFlag(type, "k_EItemStateInstalled", ItemStateFlags.Default.Installed), GetEnumFlag(type, "k_EItemStateNeedsUpdate", ItemStateFlags.Default.NeedsUpdate), GetEnumFlag(type, "k_EItemStateDownloading", ItemStateFlags.Default.Downloading), GetEnumFlag(type, "k_EItemStateDownloadPending", ItemStateFlags.Default.DownloadPending));
		}

		private static uint GetEnumFlag(Type enumType, string name, uint fallback)
		{
			try
			{
				return Convert.ToUInt32(Enum.Parse(enumType, name, ignoreCase: false));
			}
			catch
			{
				return fallback;
			}
		}

		private static bool HasFlag(uint state, uint flag)
		{
			if (flag != 0)
			{
				return (state & flag) == flag;
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Identifies Steam Workshop item IDs from assembly or file paths beneath Steam's Workshop content
	///         directory.
	///     </para>
	///     <para xml:lang="zh-CN">从 Steam 创意工坊内容目录下的程序集或文件路径识别创意工坊物品 ID。</para>
	/// </summary>
	internal static class SteamWorkshopInstallSource
	{
		internal static bool IsAssemblyLoadedFromSteamWorkshop(Assembly assembly)
		{
			ArgumentNullException.ThrowIfNull(assembly, "assembly");
			ulong itemId;
			return TryGetWorkshopItemIdFromAssembly(assembly, out itemId);
		}

		internal static bool IsAssemblyLoadedFromSteamWorkshopItem(Assembly assembly, ulong itemId)
		{
			ArgumentNullException.ThrowIfNull(assembly, "assembly");
			if (TryGetWorkshopItemIdFromAssembly(assembly, out var itemId2))
			{
				return itemId2 == itemId;
			}
			return false;
		}

		internal static bool TryGetWorkshopItemIdFromAssembly(Assembly assembly, out ulong itemId)
		{
			ArgumentNullException.ThrowIfNull(assembly, "assembly");
			try
			{
				if (TryGetWorkshopItemIdFromPath(assembly.Location, out itemId))
				{
					return true;
				}
			}
			catch (NotSupportedException)
			{
			}
			try
			{
				return TryGetWorkshopItemIdFromPath(assembly.ManifestModule.FullyQualifiedName, out itemId);
			}
			catch (NotSupportedException)
			{
				itemId = 0uL;
				return false;
			}
		}

		internal static bool IsPathLoadedFromSteamWorkshop(string? path)
		{
			ulong itemId;
			return TryGetWorkshopItemIdFromPath(path, out itemId);
		}

		internal static bool IsPathLoadedFromSteamWorkshopItem(string? path, ulong itemId)
		{
			if (TryGetWorkshopItemIdFromPath(path, out var itemId2))
			{
				return itemId2 == itemId;
			}
			return false;
		}

		internal static bool TryGetWorkshopItemIdFromPath(string? path, out ulong itemId)
		{
			itemId = 0uL;
			if (string.IsNullOrWhiteSpace(path))
			{
				return false;
			}
			string text;
			try
			{
				text = Path.GetFullPath(path);
			}
			catch
			{
				text = path;
			}
			string[] array = text.Split(new char[2] { '\\', '/' }, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
			for (int i = 0; i + 4 < array.Length; i++)
			{
				if (string.Equals(array[i], "steamapps", StringComparison.OrdinalIgnoreCase) && string.Equals(array[i + 1], "workshop", StringComparison.OrdinalIgnoreCase) && string.Equals(array[i + 2], "content", StringComparison.OrdinalIgnoreCase) && ulong.TryParse(array[i + 4], out itemId))
				{
					return true;
				}
			}
			itemId = 0uL;
			return false;
		}
	}
	/// <summary>
