			RitsuLibFramework.Logger.Warn($"[SteamWorkshop] Failed to open Workshop item page for {itemId}. Error={val}.", 1);
			RitsuToastService.ShowWarning(L("ritsulib.steamWorkshop.toast.openPageFailed", "Could not open the Steam Workshop item page."), L("ritsulib.steamWorkshop.toast.title", "Steam Workshop updates"));
			return false;
		}

		public async Task<Texture2D?> LoadPreviewTextureAsync(string? previewUrl, CancellationToken cancellationToken = default(CancellationToken))
		{
			if (string.IsNullOrWhiteSpace(previewUrl))
			{
				return null;
			}
			string key = previewUrl.Trim();
			using (_previewTextureSyncRoot.EnterScope())
			{
				if (_previewTextureCache.TryGetValue(key, out Texture2D value))
				{
					return value;
				}
			}
			Texture2D texture = null;
			try
			{
				await PreviewDownloadGate.WaitAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				try
				{
					texture = CreateTexture(await PreviewHttpClient.GetByteArrayAsync(key, cancellationToken).ConfigureAwait(continueOnCapturedContext: false));
				}
				finally
				{
					PreviewDownloadGate.Release();
				}
			}
			catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
			{
				throw;
			}
			catch (Exception ex2)
			{
				RitsuLibFramework.Logger.Warn("[SteamWorkshop] Failed to load Workshop preview '" + key + "': " + ex2.Message, 1);
			}
			if (texture == null)
			{
				return null;
			}
			using (_previewTextureSyncRoot.EnterScope())
			{
				_previewTextureCache[key] = texture;
			}
			return texture;
		}

		public static bool TryExtractWorkshopItemId(string text, out ulong itemId)
		{
			itemId = 0uL;
			string text2 = text.Trim();
			if (ulong.TryParse(text2, out itemId) && itemId != 0L)
			{
				return true;
			}
			if (!Uri.TryCreate(text2, UriKind.Absolute, out Uri result))
			{
				return false;
			}
			string[] array = result.Query.TrimStart('?').Split('&', StringSplitOptions.RemoveEmptyEntries);
			for (int i = 0; i < array.Length; i++)
			{
				string[] array2 = array[i].Split('=', 2);
				if (array2.Length == 2 && string.Equals(array2[0], "id", StringComparison.OrdinalIgnoreCase) && TryParseEncodedItemId(array2[1], out itemId))
				{
					return true;
				}
			}
			return false;
		}

		public static IReadOnlyList<ulong> ParseWorkshopItemIds(string? text)
		{
			if (string.IsNullOrWhiteSpace(text))
			{
				return Array.Empty<ulong>();
			}
			List<ulong> list = new List<ulong>();
			HashSet<ulong> hashSet = new HashSet<ulong>();
			string[] array = text.Split(new char[6] { '\r', '\n', '\t', ' ', ',', ';' }, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
			for (int i = 0; i < array.Length; i++)
			{
				if (TryExtractWorkshopItemIdFromToken(array[i], out var itemId) && hashSet.Add(itemId))
				{
					list.Add(itemId);
				}
			}
			if (list.Count > 0)
			{
				return list;
			}
			list.AddRange(EnumerateDigitRunItemIds(text).Where(hashSet.Add));
			return list;
		}

		public static string FormatWorkshopItemIdList(IEnumerable<ulong> itemIds)
		{
			return string.Join('\n', itemIds.Where((ulong id) => id != 0).Distinct());
		}

		private static Texture2D? CreateTexture(byte[] bytes)
		{
			//IL_0009: Unknown result type (might be due to invalid IL or missing references)
			//IL_000f: Expected O, but got Unknown
			//IL_002e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0033: Unknown result type (might be due to invalid IL or missing references)
			//IL_0038: Unknown result type (might be due to invalid IL or missing references)
			//IL_003d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0042: Unknown result type (might be due to invalid IL or missing references)
			//IL_0047: Unknown result type (might be due to invalid IL or missing references)
			//IL_004e: Unknown result type (might be due to invalid IL or missing references)
			//IL_004d: Unknown result type (might be due to invalid IL or missing references)
			if (bytes.Length < 12)
			{
				return null;
			}
			Image val = new Image();
			try
			{
				return (Texture2D?)(object)(((int)(DetectImageFormat(bytes) switch
				{
					PreviewImageFormat.Png => val.LoadPngFromBuffer(bytes), 
					PreviewImageFormat.Jpeg => val.LoadJpgFromBuffer(bytes), 
					PreviewImageFormat.Webp => val.LoadWebpFromBuffer(bytes), 
					_ => 15, 
				}) == 0) ? ImageTexture.CreateFromImage(val) : null);
			}
			finally
			{
				((IDisposable)val)?.Dispose();
			}
		}

		private static PreviewImageFormat DetectImageFormat(byte[] bytes)
		{
			if (bytes.Length >= 8 && bytes[0] == 137 && bytes[1] == 80 && bytes[2] == 78 && bytes[3] == 71 && bytes[4] == 13 && bytes[5] == 10 && bytes[6] == 26 && bytes[7] == 10)
			{
				return PreviewImageFormat.Png;
			}
			if (bytes[0] == byte.MaxValue && bytes[1] == 216)
			{
				return PreviewImageFormat.Jpeg;
			}
			if (bytes.Length >= 12 && bytes[0] == 82 && bytes[1] == 73 && bytes[2] == 70 && bytes[3] == 70 && bytes[8] == 87 && bytes[9] == 69 && bytes[10] == 66 && bytes[11] == 80)
			{
				return PreviewImageFormat.Webp;
			}
			return PreviewImageFormat.Unknown;
		}

		private static bool TryExtractWorkshopItemIdFromToken(string token, out ulong itemId)
		{
			itemId = 0uL;
			string text = token.Trim().Trim(new char[10] { '"', '\'', '[', ']', '(', ')', '<', '>', '{', '}' });
			if (TryExtractWorkshopItemId(text, out itemId))
			{
				return true;
			}
			int num = text.IndexOf("id=", StringComparison.OrdinalIgnoreCase);
			if (num < 0)
			{
				return false;
			}
			string text2 = text.Substring(num + 3);
			int num2 = text2.IndexOfAny(new char[10] { '&', '?', '#', '"', '\'', ',', ';', ']', ')', '}' });
			if (num2 >= 0)
			{
				text2 = text2.Substring(0, num2);
			}
			return TryParseEncodedItemId(text2, out itemId);
		}

		private static bool TryParseEncodedItemId(string value, out ulong itemId)
		{
			itemId = 0uL;
			try
			{
				return ulong.TryParse(Uri.UnescapeDataString(value), out itemId) && itemId != 0;
			}
			catch (UriFormatException)
			{
				return false;
			}
		}

		private static IEnumerable<ulong> EnumerateDigitRunItemIds(string text)
		{
			StringBuilder builder = new StringBuilder();
			foreach (char c in text)
			{
				ulong itemId;
				if (char.IsDigit(c))
				{
					builder.Append(c);
				}
				else if (TryFlush(out itemId))
				{
					yield return itemId;
				}
			}
			if (TryFlush(out var itemId2))
			{
				yield return itemId2;
			}
			bool TryFlush(out ulong reference)
			{
				reference = 0uL;
				if (builder.Length == 0)
				{
					return false;
				}
				string s = builder.ToString();
				builder.Clear();
				if (ulong.TryParse(s, out reference))
				{
					return reference != 0;
				}
				return false;
			}
		}

		private static RitsuSteamWorkshopActionResult RequestSubscriptionAction(ulong itemId, string? displayName, bool subscribe)
		{
			string value = (subscribe ? "subscribe" : "unsubscribe");
			RitsuLibFramework.Logger.Info($"[SteamWorkshop] Workshop {value} requested from UI. Item={itemId}.", 1);
			if (!SteamInitializer.Initialized)
			{
				RitsuSteamWorkshopActionResult result = RitsuSteamWorkshopActionResult.Unavailable(itemId);
				RitsuToastService.ShowWarning(L("ritsulib.steamWorkshop.toast.unavailable", "Steam Workshop is not available in this session."), L("ritsulib.steamWorkshop.toast.title", "Steam Workshop updates"));
				return result;
			}
			RitsuSteamWorkshopActionResult ritsuSteamWorkshopActionResult = (subscribe ? RitsuSteamWorkshopUpdates.RequestSubscribe(itemId) : RitsuSteamWorkshopUpdates.RequestUnsubscribe(itemId));
			string title = L("ritsulib.steamWorkshop.toast.title", "Steam Workshop updates");
			if (!ritsuSteamWorkshopActionResult.Available)
			{
				RitsuToastService.ShowWarning(ritsuSteamWorkshopActionResult.ErrorMessage ?? L("ritsulib.steamWorkshop.toast.unavailable", "Steam Workshop is not available in this session."), title);
				return ritsuSteamWorkshopActionResult;
			}
			if (!ritsuSteamWorkshopActionResult.Accepted)
			{
				RitsuToastService.ShowWarning(Format(subscribe ? "ritsulib.steamWorkshop.toast.subscribeFailed" : "ritsulib.steamWorkshop.toast.unsubscribeFailed", subscribe ? "Steam did not accept the subscribe request for {0}." : "Steam did not accept the unsubscribe request for {0}.", FormatWorkshopItemName(itemId, displayName)), title);
				return ritsuSteamWorkshopActionResult;
			}
			RitsuToastService.ShowInfo(Format(subscribe ? "ritsulib.steamWorkshop.toast.subscribeRequested" : "ritsulib.steamWorkshop.toast.unsubscribeRequested", subscribe ? "Asked Steam to subscribe to {0}. Check Steam Downloads and restart after it finishes." : "Asked Steam to unsubscribe from {0}. Restart the game after Steam applies the change.", FormatWorkshopItemName(itemId, displayName)), title);
			return ritsuSteamWorkshopActionResult;
		}

		private static string FormatWorkshopItemName(ulong itemId, string? displayName)
		{
			if (string.IsNullOrWhiteSpace(displayName))
			{
				return $"Workshop item {itemId}";
			}
			return $"{displayName.Trim()} ({itemId})";
		}

		private static string L(string key, string fallback)
		{
			return ModSettingsLocalization.Get(key, fallback);
		}

		private static string Format(string key, string fallback, params object[] args)
		{
			return string.Format(L(key, fallback), args);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Coordinates manual, automatic, and subscription-triggered Steam Workshop update checks, download
	///         monitoring, and user notifications. At most one check runs at a time.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         协调手动、自动和订阅触发的 Steam 创意工坊更新检查、下载监控及用户通知。任一时刻最多运行一次检查。
	///     </para>
	/// </summary>
	internal static class SteamWorkshopUpdateCoordinator
	{
		private enum CheckSource
		{
			Auto,
			Manual,
			Subscription
		}

		private sealed class WorkshopUpdateProgressToast(CheckSource source) : IProgress<RitsuSteamWorkshopUpdateProgress>, IProgress<RitsuSteamWorkshopDownloadProgress>
		{
			private static readonly TimeSpan ProgressUpdateMinInterval = TimeSpan.FromMilliseconds(250L, 0L);

			private readonly Lock _syncRoot = new Lock();

			private bool _completed;

			private RitsuToastHandle? _handle;

			private DateTimeOffset _lastProgressUpdateAt;

			private RitsuSteamWorkshopUpdateProgress? _latestProgress;

			private bool _progressUpdateQueued;

			public void Report(RitsuSteamWorkshopDownloadProgress value)
			{
				using (_syncRoot.EnterScope())
				{
					if (_completed)
					{
						return;
					}
				}
				PostToMainLoop(delegate
				{
					using (_syncRoot.EnterScope())
					{
						if (!_completed)
						{
							_handle?.Update(BuildDownloadProgressRequest(value), resetDuration: false);
						}
					}
				});
			}

			public void Report(RitsuSteamWorkshopUpdateProgress value)
			{
				TimeSpan timeSpan;
				using (_syncRoot.EnterScope())
				{
					if (_completed)
					{
						return;
					}
					_latestProgress = value;
					if (_progressUpdateQueued)
					{
						return;
					}
					_progressUpdateQueued = true;
					timeSpan = ResolveProgressUpdateDelay();
				}
				if (timeSpan > TimeSpan.Zero)
				{
					DelayProgressUpdateAsync(timeSpan);
				}
				else
				{
					PostProgressUpdateToMainLoop();
				}
			}

			private async Task DelayProgressUpdateAsync(TimeSpan delay)
			{
				await Task.Delay(delay).ConfigureAwait(continueOnCapturedContext: false);
				PostProgressUpdateToMainLoop();
			}

			private TimeSpan ResolveProgressUpdateDelay()
			{
				if (_lastProgressUpdateAt == default(DateTimeOffset))
				{
					return TimeSpan.Zero;
				}
				TimeSpan timeSpan = DateTimeOffset.UtcNow - _lastProgressUpdateAt;
				if (!(timeSpan >= ProgressUpdateMinInterval))
				{
					return ProgressUpdateMinInterval - timeSpan;
				}
				return TimeSpan.Zero;
			}

			private void PostProgressUpdateToMainLoop()
			{
				PostToMainLoop(delegate
				{
					using (_syncRoot.EnterScope())
					{
						if (!_completed)
						{
							_progressUpdateQueued = false;
							_lastProgressUpdateAt = DateTimeOffset.UtcNow;
							RitsuSteamWorkshopUpdateProgress latestProgress = _latestProgress;
							if ((object)latestProgress != null)
							{
								UpdateNow(latestProgress);
							}
						}
					}
				});
			}

			public void Start()
			{
				PostToMainLoop(delegate
				{
					using (_syncRoot.EnterScope())
					{
						if (!_completed)
						{
							_handle = RitsuToastService.ShowTracked(BuildProgressRequest(new RitsuSteamWorkshopUpdateProgress(RitsuSteamWorkshopUpdateProgressStage.Starting, 0, 1)));
							RitsuSteamWorkshopUpdateProgress latestProgress = _latestProgress;
							if ((object)latestProgress != null)
							{
								UpdateNow(latestProgress);
							}
						}
					}
				});
			}

			public void StartDownload(IReadOnlyList<RitsuSteamWorkshopDownloadItem> items)
			{
				PostToMainLoop(delegate
				{
					using (_syncRoot.EnterScope())
					{
						if (!_completed)
						{
							int totalCount = Math.Max(1, items.Count);
							_handle = RitsuToastService.ShowTracked(BuildDownloadProgressRequest(new RitsuSteamWorkshopDownloadProgress(0, totalCount, 0uL, 0uL, items.FirstOrDefault()?.DisplayName)));
						}
					}
				});
			}

			public void Complete(RitsuSteamWorkshopUpdateResult result, bool downloadFinished)
			{
				PostToMainLoop(delegate
				{
					using (_syncRoot.EnterScope())
					{
						_completed = true;
						RitsuToastRequest ritsuToastRequest = BuildResultToastRequest(result, source, source == CheckSource.Manual, downloadFinished);
						if (ritsuToastRequest == null)
						{
							_handle?.Close();
						}
						else
						{
							ritsuToastRequest = ritsuToastRequest.WithProgress(null).Persistent(isPersistent: false);
							RitsuToastHandle? handle = _handle;
							if (handle == null || !handle.Update(ritsuToastRequest))
							{
								RitsuToastService.Show(ritsuToastRequest);
							}
						}
					}
				});
			}

			public void Dismiss()
			{
				PostToMainLoop(delegate
				{
					using (_syncRoot.EnterScope())
					{
						_completed = true;
						_handle?.Close();
					}
				});
			}

			private void UpdateNow(RitsuSteamWorkshopUpdateProgress progress)
			{
				_handle?.Update(BuildProgressRequest(progress), resetDuration: false);
			}

			private static RitsuToastRequest BuildDownloadProgressRequest(RitsuSteamWorkshopDownloadProgress progress)
			{
				string body = ((progress.BytesTotal != 0) ? Format("ritsulib.steamWorkshop.toast.progress.download", "Downloading Workshop updates: {0}/{1} item(s), {2}/{3}.\nCurrent: {4}", progress.CompletedCount, progress.TotalCount, FormatBytes(progress.BytesDownloaded), FormatBytes(progress.BytesTotal), progress.CurrentItemName ?? L("ritsulib.steamWorkshop.toast.progress.downloadUnknownItem", "unknown item")) : Format("ritsulib.steamWorkshop.toast.progress.downloadWaiting", "Downloading Workshop updates: {0}/{1} item(s). Waiting for Steam download size...\nCurrent: {2}", progress.CompletedCount, progress.TotalCount, progress.CurrentItemName ?? L("ritsulib.steamWorkshop.toast.progress.downloadUnknownItem", "unknown item")));
				float value = ((progress.BytesTotal != 0) ? Mathf.Clamp((float)progress.BytesDownloaded / (float)progress.BytesTotal, 0f, 1f) : Mathf.Clamp((float)progress.CompletedCount / (float)Math.Max(1, progress.TotalCount), 0f, 1f));
				return new RitsuToastRequest(body, L("ritsulib.steamWorkshop.toast.title", "Steam Workshop updates")).Persistent().WithDismissOnClick(dismissOnClick: false).WithProgress(value);
			}

			private static RitsuToastRequest BuildProgressRequest(RitsuSteamWorkshopUpdateProgress progress)
			{
				object body = progress.Stage switch
				{
					RitsuSteamWorkshopUpdateProgressStage.ReadingSubscriptions => Format("ritsulib.steamWorkshop.toast.progress.subscriptions", "Reading subscribed Workshop items...", progress.CompletedCount, progress.TotalCount), 
					RitsuSteamWorkshopUpdateProgressStage.RefreshingDetails => Format("ritsulib.steamWorkshop.toast.progress.details", "Refreshing Workshop details: {0}/{1}", progress.CompletedCount, progress.TotalCount), 
					RitsuSteamWorkshopUpdateProgressStage.InspectingItems => Format("ritsulib.steamWorkshop.toast.progress.inspecting", "Checking Workshop items: {0}/{1}. Updates: {2}; queued: {3}; failed: {4}.", progress.CompletedCount, progress.TotalCount, progress.NeedsUpdateCount, progress.QueuedCount + progress.AlreadyQueuedCount, progress.FailedCount), 
					_ => L("ritsulib.steamWorkshop.toast.progress.starting", "Starting Steam Workshop update check..."), 
				};
				int num = Math.Max(1, progress.TotalCount);
				float value = Mathf.Clamp((float)progress.CompletedCount / (float)num, 0f, 1f);
				return new RitsuToastRequest((string)body, L("ritsulib.steamWorkshop.toast.title", "Steam Workshop updates")).Persistent().WithDismissOnClick(dismissOnClick: false).WithProgress(value);
			}

			private static string FormatBytes(ulong bytes)
			{
				string[] array = new string[4] { "B", "KB", "MB", "GB" };
				double num = bytes;
				int num2 = 0;
				while (num >= 1024.0 && num2 < array.Length - 1)
				{
					num /= 1024.0;
					num2++;
				}
				if (num2 == 0)
				{
					return $"{bytes} {array[num2]}";
				}
				return $"{num:0.0} {array[num2]}";
			}
		}

		private sealed class AutoDownloadNotification(RitsuSteamWorkshopUpdateResult result)
		{
			private int _completionShown;

			private int _downloadFinished;

			private int _initialShown;

			public RitsuSteamWorkshopUpdateResult Result { get; } = result;

			public bool DownloadFinished => Volatile.Read(in _downloadFinished) != 0;

			public bool HasShownInitial => Volatile.Read(in _initialShown) != 0;

			public void MarkFinished()
			{
				Volatile.Write(ref _downloadFinished, 1);
			}

			public bool TryMarkInitialShown()
			{
				return Interlocked.Exchange(ref _initialShown, 1) == 0;
			}

			public bool TryMarkCompletionShown()
			{
				return Interlocked.Exchange(ref _completionShown, 1) == 0;
			}
		}

		private const double ToastDurationSeconds = 7.0;

		private const int MaxChangedItemsInToast = 10;

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Lock AutoDownloadNotificationSyncRoot = new Lock();

		private static readonly Lock SubscriptionMonitorSyncRoot = new Lock();

		private static readonly HashSet<ulong> SubscriptionMonitorItemIds = new HashSet<ulong>();

		private static AutoDownloadNotification? _autoDownloadNotification;

		private static bool _initialized;

		private static int _checkRunning;

		internal static bool CanUseSteamWorkshopUpdates()
		{
			return SteamWorkshopManager.Instance.IsAvailable;
		}

		internal static void Initialize()
		{
			using (SyncRoot.EnterScope())
			{
				if (!_initialized)
				{
					RitsuLibFramework.Logger.Info("[SteamWorkshopUpdate] Coordinator initialized.", 1);
					AutomaticUpdateCheckScheduler.Register("steam-workshop", "Steam Workshop updates", RitsuLibSettingsStore.IsSteamWorkshopUpdateCheckEnabled, delegate(CancellationToken cancellationToken)
					{
						RitsuLibFramework.Logger.Info("[SteamWorkshopUpdate] Auto check requested.", 1);
						return CheckAsync(CheckSource.Auto, deferToastToMainMenu: true, null, cancellationToken);
					});
					_initialized = true;
				}
			}
		}

		internal static void CheckNowFromSettings()
		{
			RitsuLibFramework.Logger.Info("[SteamWorkshopUpdate] Manual check requested from settings.", 1);
			CheckAsync(CheckSource.Manual, deferToastToMainMenu: false);
		}

		internal static void CheckRitsuLibNowFromSettings()
		{
			RitsuLibFramework.Logger.Info("[SteamWorkshopUpdate] Manual RitsuLib Workshop item check requested from settings.", 1);
			CheckItemAsync(3747602295uL, automatic: false);
		}

		internal static RitsuSteamWorkshopActionResult SubscribeItemFromUi(ulong itemId, string? displayName = null)
		{
			RitsuSteamWorkshopActionResult ritsuSteamWorkshopActionResult = SteamWorkshopManager.Instance.SubscribeFromUi(itemId, displayName);
			if (ritsuSteamWorkshopActionResult.Accepted)
			{
				StartSubscriptionDownloadMonitor(itemId, displayName);
			}
			return ritsuSteamWorkshopActionResult;
		}

		internal static RitsuSteamWorkshopActionResult UnsubscribeItemFromUi(ulong itemId, string? displayName = null)
		{
			return SteamWorkshopManager.Instance.UnsubscribeFromUi(itemId, displayName);
		}

		internal static Task CheckItemAsync(ulong itemId, bool automatic, bool deferToastToMainMenu = false, CancellationToken cancellationToken = default(CancellationToken))
		{
			ArgumentOutOfRangeException.ThrowIfZero(itemId, "itemId");
			return CheckAsync((!automatic) ? CheckSource.Manual : CheckSource.Auto, deferToastToMainMenu, new <>z__ReadOnlySingleElementList<ulong>(itemId), cancellationToken);
		}

		private static Task CheckAsync(CheckSource source, bool deferToastToMainMenu, IReadOnlyCollection<ulong>? itemIds = null, CancellationToken cancellationToken = default(CancellationToken))
		{
			if (Interlocked.Exchange(ref _checkRunning, 1) == 0)
			{
				return Task.Run(async delegate
				{
					WorkshopUpdateProgressToast progressToast = null;
					try
					{
						RitsuLibFramework.Logger.Info($"[SteamWorkshopUpdate] Starting {source} check. SteamInitialized={SteamInitializer.Initialized}.", 1);
						if (ShouldShowProgressToast(source, deferToastToMainMenu))
						{
							progressToast = new WorkshopUpdateProgressToast(source);
							progressToast.Start();
						}
						if (!SteamInitializer.Initialized)
						{
							RitsuLibFramework.Logger.Info($"[SteamWorkshopUpdate] {source} check skipped: Steam is not initialized.", 1);
							CompleteOrShowResult(RitsuSteamWorkshopUpdateResult.Unavailable(), source, deferToastToMainMenu, progressToast, downloadFinished: false);
						}
						else
						{
							RitsuSteamWorkshopUpdateResult result = await RitsuSteamWorkshopUpdates.TriggerMissingUpdatesAsync(progressToast, itemIds, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
							RitsuLibFramework.Logger.Info($"[SteamWorkshopUpdate] {source} check result: Available={result.Available}, Inspected={result.InspectedCount}, NeedsUpdate={result.NeedsUpdateCount}, Triggered={result.TriggeredCount}, AlreadyQueued={result.AlreadyQueuedCount}, Failed={result.FailedCount}, Error={result.ErrorMessage ?? "<none>"}.", 1);
							LogCheckSummary(source, result);
							switch (source)
							{
							case CheckSource.Manual:
								if ((object)result != null && result.Available && result.NeedsUpdateCount == 0)
								{
									AutoDownloadNotification autoDownloadNotification = TakeFinishedAutoDownloadNotification();
									if (autoDownloadNotification != null)
									{
										RitsuLibFramework.Logger.Info("[SteamWorkshopUpdate] Manual check found no missing downloads, but automatic Workshop updates completed during this session; reporting that a restart is required.", 1);
										CompleteOrShowResult(autoDownloadNotification.Result, source, deferToastToMainMenu, progressToast, downloadFinished: true);
										return;
									}
								}
								break;
							case CheckSource.Auto:
							{
								IReadOnlyList<RitsuSteamWorkshopDownloadItem> monitorItems = result.MonitorItems;
								if (monitorItems != null && monitorItems.Count > 0)
								{
									StartAutoDownloadNotification(result, deferToastToMainMenu);
									return;
								}
								break;
							}
							}
							bool downloadFinished = await MonitorTriggeredDownloadsAsync(result, progressToast, stopWhenIdle: true, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
							CompleteOrShowResult(result, source, deferToastToMainMenu, progressToast, downloadFinished);
						}
					}
					catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
					{
						progressToast?.Dismiss();
						throw;
					}
					catch (Exception ex2)
					{
						RitsuLibFramework.Logger.Warn("[SteamWorkshopUpdate] Check failed: " + ex2.Message, 1);
						CompleteOrShowResult(RitsuSteamWorkshopUpdateResult.Unavailable(ex2.Message), source, deferToastToMainMenu, progressToast, downloadFinished: false);
					}
					finally
					{
						Interlocked.Exchange(ref _checkRunning, 0);
					}
				});
			}
			RitsuLibFramework.Logger.Info($"[SteamWorkshopUpdate] {source} check skipped: another check is already running.", 1);
			if (ShouldShowCompletionToast(source))
			{
				ShowToast(L("ritsulib.steamWorkshop.toast.busy", "Another Steam Workshop update check is already running."), RitsuToastLevel.Info, deferToastToMainMenu);
			}
			return Task.CompletedTask;
		}

		private static void CompleteOrShowResult(RitsuSteamWorkshopUpdateResult result, CheckSource source, bool deferToastToMainMenu, WorkshopUpdateProgressToast? progressToast, bool downloadFinished)
		{
			if (progressToast != null)
			{
				progressToast.Complete(result, downloadFinished);
			}
			else
			{
				ShowResultToast(result, source, deferToastToMainMenu, downloadFinished);
			}
		}

		private static void ShowResultToast(RitsuSteamWorkshopUpdateResult result, CheckSource source, bool deferToastToMainMenu, bool downloadFinished)
		{
			RitsuToastRequest ritsuToastRequest = BuildResultToastRequest(result, source, forceCompletionToast: false, downloadFinished);
			if (ritsuToastRequest != null)
			{
				ShowToast(ritsuToastRequest, deferToastToMainMenu);
			}
		}

		private static RitsuToastRequest? BuildResultToastRequest(RitsuSteamWorkshopUpdateResult result, CheckSource source, bool forceCompletionToast, bool downloadFinished)
		{
			if (!result.Available)
			{
				if (!forceCompletionToast && !ShouldShowCompletionToast(source))
				{
					return null;
				}
				return ToastRequest((result.ErrorMessage == null) ? L("ritsulib.steamWorkshop.toast.unavailable", "Steam Workshop is not available in this session.") : Format("ritsulib.steamWorkshop.toast.failed", "Steam Workshop check failed: {0}", result.ErrorMessage), (result.ErrorMessage != null) ? RitsuToastLevel.Warning : RitsuToastLevel.Info);
			}
			bool flag;
			switch (source)
			{
			case CheckSource.Subscription:
				return BuildSubscriptionDownloadToast(result, downloadFinished);
			case CheckSource.Auto:
				{
					if ((object)result != null && result.NeedsUpdateCount > 0)
					{
						IReadOnlyList<RitsuSteamWorkshopChangedItem> changedItems = result.ChangedItems;
						if ((changedItems == null || changedItems.Count <= 0) && result.TriggeredCount <= 0)
						{
							flag = true;
							goto IL_009d;
						}
					}
					flag = false;
					goto IL_009d;
				}
				IL_009d:
				if (flag)
				{
					return null;
				}
				break;
			}
			if (result.FailedCount > 0)
			{
				return ToastRequest(AppendChangedItemList(Format("ritsulib.steamWorkshop.toast.partial", "Found {0} Workshop item(s) with updates. Asked Steam to download {1}; {2} failed. Check Steam Downloads and restart after Steam finishes.", result.NeedsUpdateCount, result.TriggeredCount, result.FailedCount), result.ChangedItems), RitsuToastLevel.Warning);
			}
			if (downloadFinished)
			{
				IReadOnlyList<RitsuSteamWorkshopDownloadItem> monitorItems = result.MonitorItems;
				if (monitorItems != null && monitorItems.Count > 0)
				{
					return BuildAutoDownloadFinishedToast(result);
				}
			}
			else
			{
				IReadOnlyList<RitsuSteamWorkshopDownloadItem> monitorItems = result.MonitorItems;
				if (monitorItems != null && monitorItems.Count > 0)
				{
					return null;
				}
			}
			if (result.TriggeredCount > 0)
			{
				return ToastRequest(AppendChangedItemList(Format((source == CheckSource.Auto) ? "ritsulib.steamWorkshop.toast.autoTriggered" : "ritsulib.steamWorkshop.toast.triggered", (source == CheckSource.Auto) ? "Workshop updates found for {0} item(s). Steam has been asked to queue the downloads. Check Steam Downloads and restart after Steam finishes." : "Asked Steam to download Workshop updates for {0} item(s). Check Steam Downloads and restart after Steam finishes.", result.TriggeredCount), result.ChangedItems), RitsuToastLevel.Info);
			}
			if (result.AlreadyQueuedCount > 0)
			{
				if (!forceCompletionToast && !ShouldShowCompletionToast(source))
				{
					if (source == CheckSource.Auto)
					{
						IReadOnlyList<RitsuSteamWorkshopChangedItem> changedItems = result.ChangedItems;
						if (changedItems != null && changedItems.Count > 0)
						{
							goto IL_01ac;
						}
					}
					return null;
				}
				goto IL_01ac;
			}
			if (!forceCompletionToast && !ShouldShowCompletionToast(source))
			{
				return null;
			}
			return ToastRequest(Format("ritsulib.steamWorkshop.toast.none", "Checked {0} subscribed Workshop item(s). No missing updates were found.", result.InspectedCount), RitsuToastLevel.Info);
			IL_01ac:
			return ToastRequest(AppendChangedItemList(Format("ritsulib.steamWorkshop.toast.alreadyQueued", "{0} Workshop item(s) already have downloads queued or running.", result.AlreadyQueuedCount), result.ChangedItems), RitsuToastLevel.Info);
		}

		private static RitsuToastRequest ToastRequest(string body, RitsuToastLevel level)
		{
			return new RitsuToastRequest(body, L("ritsulib.steamWorkshop.toast.title", "Steam Workshop updates"), null, level, 7.0);
		}

		private static RitsuToastRequest BuildSubscriptionDownloadToast(RitsuSteamWorkshopUpdateResult result, bool downloadFinished)
		{
			string text = FormatDownloadItemList(result.MonitorItems);
			return ToastRequest(downloadFinished ? Format("ritsulib.steamWorkshop.toast.subscribeDownloadFinished", "Steam finished downloading {0}. Restart the game to load the new files.", text) : Format("ritsulib.steamWorkshop.toast.subscribeDownloadPending", "Steam accepted the subscription for {0}. The download is still queued, running, or not reporting progress yet. Check Steam Downloads and restart after it finishes.", text), RitsuToastLevel.Info);
		}

		private static string FormatDownloadItemList(IReadOnlyList<RitsuSteamWorkshopDownloadItem>? items)
		{
			if (items == null || items.Count <= 0)
			{
				return L("ritsulib.steamWorkshop.toast.progress.downloadUnknownItem", "unknown item");
			}
			string[] array = (from item in items.Take(10)
				select item.DisplayName).ToArray();
			int num = items.Count - array.Length;
			if (num <= 0)
			{
				return string.Join(", ", array);
			}
			return $"{string.Join(", ", array)} (+{num})";
		}

		private static string AppendChangedItemList(string body, IReadOnlyList<RitsuSteamWorkshopChangedItem>? changedItems)
		{
			if (changedItems == null || changedItems.Count <= 0)
			{
				return body;
			}
			string[] array = (from item in changedItems.Take(10)
				select item.DisplayName).ToArray();
			int num = changedItems.Count - array.Length;
			string text = ((num > 0) ? $"{string.Join(", ", array)} (+{num})" : string.Join(", ", array));
			return body + "\n" + Format("ritsulib.steamWorkshop.toast.changedSinceLastCheck", "Changed since last check:\n{0}", text);
		}

		private static bool ShouldShowCompletionToast(CheckSource source)
		{
			return source == CheckSource.Manual;
		}

		private static bool ShouldShowProgressToast(CheckSource source, bool deferToastToMainMenu)
		{
			if (source != CheckSource.Manual)
			{
				return false;
			}
			if (deferToastToMainMenu)
			{
				return UpdateCheckSessionState.IsMainMenuActive;
			}
			return true;
		}

		private static async Task<bool> MonitorTriggeredDownloadsAsync(RitsuSteamWorkshopUpdateResult result, WorkshopUpdateProgressToast? progressToast, bool stopWhenIdle, CancellationToken cancellationToken)
		{
			IReadOnlyList<RitsuSteamWorkshopDownloadItem> monitorItems = result.MonitorItems;
			if (monitorItems == null || monitorItems.Count <= 0)
			{
				return false;
			}
			return await RitsuSteamWorkshopUpdates.MonitorDownloadsAsync(result.MonitorItems, progressToast, stopWhenIdle, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
		}

		private static void StartAutoDownloadNotification(RitsuSteamWorkshopUpdateResult result, bool deferToastToMainMenu)
		{
			AutoDownloadNotification autoDownloadNotification = new AutoDownloadNotification(result);
			using (AutoDownloadNotificationSyncRoot.EnterScope())
			{
				_autoDownloadNotification = autoDownloadNotification;
			}
			if (BuildResultToastRequest(result, CheckSource.Auto, forceCompletionToast: false, downloadFinished: false) != null)
			{
				QueueAutoDownloadStatusToast(autoDownloadNotification, deferToastToMainMenu);
			}
			MonitorAutoDownloadsAsync(autoDownloadNotification);
		}

		private static async Task MonitorAutoDownloadsAsync(AutoDownloadNotification notification)
		{
			bool flag;
			try
			{
				flag = await MonitorTriggeredDownloadsAsync(notification.Result, null, stopWhenIdle: false, CancellationToken.None).ConfigureAwait(continueOnCapturedContext: false);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[SteamWorkshopUpdate] Automatic download monitor failed: " + ex.Message, 1);
				return;
			}
			if (!flag)
			{
				return;
			}
			notification.MarkFinished();
			if (!notification.HasShownInitial || !UpdateCheckSessionState.IsMainMenuActive || !notification.TryMarkCompletionShown())
			{
				return;
			}
			PostToMainLoop(delegate
			{
				if (IsCurrentAutoDownloadNotification(notification))
				{
					ShowToastNow(BuildAutoDownloadFinishedToast(notification.Result));
				}
			});
		}

		private static void StartSubscriptionDownloadMonitor(ulong itemId, string? displayName)
		{
			using (SubscriptionMonitorSyncRoot.EnterScope())
			{
				if (!SubscriptionMonitorItemIds.Add(itemId))
				{
					return;
				}
			}
			Task.Run(async delegate
			{
				RitsuSteamWorkshopDownloadItem ritsuSteamWorkshopDownloadItem = new RitsuSteamWorkshopDownloadItem(itemId, FormatWorkshopItemName(itemId, displayName));
				RitsuSteamWorkshopDownloadItem[] items = new RitsuSteamWorkshopDownloadItem[1] { ritsuSteamWorkshopDownloadItem };
				RitsuSteamWorkshopUpdateResult result = new RitsuSteamWorkshopUpdateResult(Available: true, 1, 1, 1, 0, 0, null, items, items);
				WorkshopUpdateProgressToast progressToast = new WorkshopUpdateProgressToast(CheckSource.Subscription);
				bool downloadFinished = false;
				try
				{
					await Task.Delay(1500).ConfigureAwait(continueOnCapturedContext: false);
					progressToast.StartDownload(items);
					downloadFinished = await RitsuSteamWorkshopUpdates.MonitorDownloadsAsync(items, progressToast, stopWhenIdle: true, CancellationToken.None).ConfigureAwait(continueOnCapturedContext: false);
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[SteamWorkshopUpdate] Subscription download monitor failed for item {itemId}: {ex.Message}", 1);
				}
				finally
				{
					using (SubscriptionMonitorSyncRoot.EnterScope())
					{
						SubscriptionMonitorItemIds.Remove(itemId);
					}
				}
				progressToast.Complete(result, downloadFinished);
			});
		}

		private static void QueueAutoDownloadStatusToast(AutoDownloadNotification notification, bool deferToastToMainMenu)
		{
			if (!deferToastToMainMenu)
			{
				PostToMainLoop(delegate
				{
					ShowAutoDownloadStatusToast(notification);
				});
			}
			else
			{
				UpdateCheckNotificationQueue.ShowWhenMainMenu("steam-workshop", delegate
				{
					ShowAutoDownloadStatusToast(notification);
				});
			}
		}

		private static void ShowAutoDownloadStatusToast(AutoDownloadNotification notification)
		{
			if (IsCurrentAutoDownloadNotification(notification) && notification.TryMarkInitialShown())
			{
				if (notification.DownloadFinished)
				{
					notification.TryMarkCompletionShown();
				}
				RitsuToastRequest ritsuToastRequest = BuildResultToastRequest(notification.Result, CheckSource.Auto, forceCompletionToast: false, notification.DownloadFinished);
				if (ritsuToastRequest != null)
				{
					ShowToastNow(ritsuToastRequest);
				}
			}
		}

		private static bool IsCurrentAutoDownloadNotification(AutoDownloadNotification notification)
		{
			using (AutoDownloadNotificationSyncRoot.EnterScope())
			{
				return _autoDownloadNotification == notification;
			}
		}

		private static AutoDownloadNotification? TakeFinishedAutoDownloadNotification()
		{
			using (AutoDownloadNotificationSyncRoot.EnterScope())
			{
				AutoDownloadNotification autoDownloadNotification = _autoDownloadNotification;
				if (autoDownloadNotification == null || !autoDownloadNotification.DownloadFinished)
				{
					return null;
				}
				_autoDownloadNotification = null;
				return autoDownloadNotification;
			}
		}

		private static RitsuToastRequest BuildAutoDownloadFinishedToast(RitsuSteamWorkshopUpdateResult result)
		{
			return ToastRequest(AppendChangedItemList(Format("ritsulib.steamWorkshop.toast.downloadFinished", "Updated {0} Steam Workshop item(s). Restart the game to load the new files.", result.MonitorItems?.Count ?? result.TriggeredCount), result.ChangedItems), RitsuToastLevel.Info);
		}

		private static void LogCheckSummary(CheckSource source, RitsuSteamWorkshopUpdateResult result)
		{
			string value = ((source == CheckSource.Auto) ? "Auto update check" : "Manual update check");
			if (!result.Available)
			{
				RitsuLibFramework.Logger.Info($"[SteamWorkshopUpdate] {value} could not inspect Workshop updates. Error={result.ErrorMessage ?? "<none>"}.", 1);
			}
			else if (result.NeedsUpdateCount <= 0)
			{
				RitsuLibFramework.Logger.Info($"[SteamWorkshopUpdate] {value} found no Workshop item updates. Inspected={result.InspectedCount}.", 1);
			}
			else if (result.FailedCount > 0)
			{
				RitsuLibFramework.Logger.Warn($"[SteamWorkshopUpdate] {value} detected Workshop item updates but not all downloads were queued. NeedsUpdate={result.NeedsUpdateCount}, Triggered={result.TriggeredCount}, AlreadyQueued={result.AlreadyQueuedCount}, Failed={result.FailedCount}.", 1);
			}
			else if (result.TriggeredCount > 0)
			{
				string value2 = ((source == CheckSource.Auto) ? "asked Steam to queue downloads" : "queued Steam downloads");
				RitsuLibFramework.Logger.Info($"[SteamWorkshopUpdate] {value} detected Workshop item updates and {value2}. NeedsUpdate={result.NeedsUpdateCount}, Triggered={result.TriggeredCount}, AlreadyQueued={result.AlreadyQueuedCount}.", 1);
			}
			else
			{
				RitsuLibFramework.Logger.Info($"[SteamWorkshopUpdate] {value} found Workshop item updates that were already queued or downloading. NeedsUpdate={result.NeedsUpdateCount}, AlreadyQueued={result.AlreadyQueuedCount}.", 1);
			}
		}

		private static void ShowToast(string body, RitsuToastLevel level, bool deferToMainMenu)
		{
			ShowToast(ToastRequest(body, level), deferToMainMenu);
		}

		private static RitsuSteamWorkshopActionResult RequestSubscriptionAction(ulong itemId, string? displayName, bool subscribe)
		{
			string value = (subscribe ? "subscribe" : "unsubscribe");
			RitsuLibFramework.Logger.Info($"[SteamWorkshopUpdate] Workshop {value} requested from UI. Item={itemId}.", 1);
			if (!SteamInitializer.Initialized)
			{
				RitsuSteamWorkshopActionResult result = RitsuSteamWorkshopActionResult.Unavailable(itemId);
				ShowToast(L("ritsulib.steamWorkshop.toast.unavailable", "Steam Workshop is not available in this session."), RitsuToastLevel.Warning, deferToMainMenu: false);
				return result;
			}
			RitsuSteamWorkshopActionResult ritsuSteamWorkshopActionResult = (subscribe ? RitsuSteamWorkshopUpdates.RequestSubscribe(itemId) : RitsuSteamWorkshopUpdates.RequestUnsubscribe(itemId));
			string title = L("ritsulib.steamWorkshop.toast.title", "Steam Workshop updates");
			if (!ritsuSteamWorkshopActionResult.Available)
			{
				RitsuToastService.ShowWarning(ritsuSteamWorkshopActionResult.ErrorMessage ?? L("ritsulib.steamWorkshop.toast.unavailable", "Steam Workshop is not available in this session."), title);
				return ritsuSteamWorkshopActionResult;
			}
			if (!ritsuSteamWorkshopActionResult.Accepted)
			{
				RitsuToastService.ShowWarning(Format(subscribe ? "ritsulib.steamWorkshop.toast.subscribeFailed" : "ritsulib.steamWorkshop.toast.unsubscribeFailed", subscribe ? "Steam did not accept the subscribe request for {0}." : "Steam did not accept the unsubscribe request for {0}.", FormatWorkshopItemName(itemId, displayName)), title);
				return ritsuSteamWorkshopActionResult;
			}
			RitsuToastService.ShowInfo(Format(subscribe ? "ritsulib.steamWorkshop.toast.subscribeRequested" : "ritsulib.steamWorkshop.toast.unsubscribeRequested", subscribe ? "Asked Steam to subscribe to {0}. Check Steam Downloads and restart after it finishes." : "Asked Steam to unsubscribe from {0}. Restart the game after Steam applies the change.", FormatWorkshopItemName(itemId, displayName)), title);
			return ritsuSteamWorkshopActionResult;
		}

		private static string FormatWorkshopItemName(ulong itemId, string? displayName)
		{
			if (string.IsNullOrWhiteSpace(displayName))
			{
				return $"Workshop item {itemId}";
			}
			return $"{displayName.Trim()} ({itemId})";
		}

		private static void ShowToast(RitsuToastRequest request, bool deferToMainMenu)
		{
			if (deferToMainMenu)
			{
				UpdateCheckNotificationQueue.ShowWhenMainMenu("steam-workshop", delegate
				{
					ShowToastNow(request);
				});
			}
			else
			{
				PostToMainLoop(delegate
				{
					ShowToastNow(request);
				});
			}
		}

		private static void ShowToastNow(RitsuToastRequest request)
		{
			RitsuToastService.Show(request);
		}

		private static void PostToMainLoop(Action action)
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			if (Engine.GetMainLoop() is SceneTree)
			{
				Callable val = Callable.From(action);
				((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			}
			else
			{
				action();
			}
		}

		private static string L(string key, string fallback)
		{
			return ModSettingsLocalization.Get(key, fallback);
		}

		private static string Format(string key, string fallback, params object[] args)
		{
			return string.Format(L(key, fallback), args);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Identifies the current Steam update snapshot scope by Steam beta branch and game-host version.</para>
	///     <para xml:lang="zh-CN">按 Steam 测试分支和游戏宿主版本标识当前 Steam 更新快照的作用域。</para>
	/// </summary>
	internal readonly record struct SteamWorkshopUpdateScope(string Key, string DisplayName, string? BranchName)
	{
		internal static SteamWorkshopUpdateScope Current()
		{
			string text = TryGetCurrentSteamBetaName();
			string text2 = (string.IsNullOrWhiteSpace(text) ? "production" : NormalizeKeyPart(text));
			string value = Sts2HostVersion.ReleaseLabel ?? Sts2HostVersion.Numeric?.ToString();
			string text3 = (string.IsNullOrWhiteSpace(value) ? "unknown-host" : NormalizeKeyPart(value));
			string displayName = (string.IsNullOrWhiteSpace(text) ? "production" : text.Trim());
			return new SteamWorkshopUpdateScope("steam:" + text2 + ":host:" + text3, displayName, text);
		}

		private static string? TryGetCurrentSteamBetaName()
		{
			try
			{
				MethodInfo methodInfo = (from asm in AppDomain.CurrentDomain.GetAssemblies()
					select asm.GetType("Steamworks.SteamApps", throwOnError: false)).FirstOrDefault((Type type) => type != null)?.GetMethod("GetCurrentBetaName", BindingFlags.Static | BindingFlags.Public, null, new Type[2]
				{
					typeof(string).MakeByRefType(),
					typeof(int)
				}, null);
				if (methodInfo == null)
				{
					return null;
				}
				object[] array = new object[2]
				{
					string.Empty,
					128
				};
				object obj = methodInfo.Invoke(null, array);
				return (obj is bool && (bool)obj && array[0] is string text && !string.IsNullOrWhiteSpace(text)) ? text.Trim() : null;
			}
			catch
			{
				return null;
			}
		}

		private static string NormalizeKeyPart(string value)
		{
			StringBuilder stringBuilder = new StringBuilder(value.Length);
			string text = value.Trim();
			foreach (char c in text)
			{
				if (char.IsAsciiLetterOrDigit(c))
				{
					stringBuilder.Append(char.ToLowerInvariant(c));
					continue;
				}
				if ((c == '-' || c == '.' || c == '_') ? true : false)
				{
					stringBuilder.Append(c);
					continue;
				}
				if (stringBuilder.Length != 0)
				{
					if (stringBuilder[stringBuilder.Length - 1] == '-')
					{
						continue;
					}
				}
				stringBuilder.Append('-');
			}
			if (stringBuilder.Length != 0)
			{
				return stringBuilder.ToString().Trim('-');
			}
			return "unknown";
		}
	}
	/// <summary>
	///     <para xml:lang="en">Persists the last-seen Workshop item update timestamps separately for each Steam update scope.</para>
	///     <para xml:lang="zh-CN">按每个 Steam 更新作用域分别持久化最后看到的创意工坊物品更新时间戳。</para>
	/// </summary>
	internal static class SteamWorkshopUpdateSnapshotStore
	{
		private sealed class SteamWorkshopUpdateSnapshotData
		{
			[JsonPropertyName("items")]
			public Dictionary<string, SteamWorkshopUpdateSnapshotEntry> Items { get; } = new Dictionary<string, SteamWorkshopUpdateSnapshotEntry>();

			[JsonPropertyName("scopes")]
			public Dictionary<string, SteamWorkshopUpdateScopeData> Scopes { get; } = new Dictionary<string, SteamWorkshopUpdateScopeData>();
		}

		private sealed class SteamWorkshopUpdateScopeData
		{
			[JsonPropertyName("display_name")]
			public string? DisplayName { get; set; }

			[JsonPropertyName("branch_name")]
			public string? BranchName { get; set; }

			[JsonPropertyName("items")]
			public Dictionary<string, SteamWorkshopUpdateSnapshotEntry> Items { get; } = new Dictionary<string, SteamWorkshopUpdateSnapshotEntry>();
		}

		private sealed class SteamWorkshopUpdateSnapshotEntry
		{
			[JsonPropertyName("updated")]
			public uint Updated { get; init; }

			[JsonPropertyName("title")]
			public string? Title { get; init; }
		}

		private const string DataKey = "steam_workshop_update_snapshot";

		private const string FileName = "steam_workshop_update_snapshot.json";

		private static readonly Lock SyncRoot = new Lock();

		private static readonly ModDataStore Store = ModDataStore.For("com.ritsukage.sts2-RitsuLib");

		private static bool _initialized;

		internal static IReadOnlyDictionary<ulong, SteamWorkshopStoredUpdateItem> GetItems(SteamWorkshopUpdateScope scope)
		{
			EnsureInitialized();
			Dictionary<ulong, SteamWorkshopStoredUpdateItem> dictionary = new Dictionary<ulong, SteamWorkshopStoredUpdateItem>();
			SteamWorkshopUpdateSnapshotData steamWorkshopUpdateSnapshotData = Store.Get<SteamWorkshopUpdateSnapshotData>("steam_workshop_update_snapshot");
			SteamWorkshopUpdateScopeData value;
			foreach (var (s, steamWorkshopUpdateSnapshotEntry2) in steamWorkshopUpdateSnapshotData.Scopes.TryGetValue(scope.Key, out value) ? value.Items : steamWorkshopUpdateSnapshotData.Items)
			{
				if (ulong.TryParse(s, out var result))
				{
					dictionary[result] = new SteamWorkshopStoredUpdateItem(steamWorkshopUpdateSnapshotEntry2.Updated, steamWorkshopUpdateSnapshotEntry2.Title);
				}
			}
			return dictionary;
		}

		internal static void Replace(SteamWorkshopUpdateScope scope, IReadOnlyDictionary<ulong, SteamWorkshopStoredUpdateItem> items)
		{
			EnsureInitialized();
			Store.Modify("steam_workshop_update_snapshot", delegate(SteamWorkshopUpdateSnapshotData data)
			{
				SteamWorkshopUpdateScopeData orCreateScopeData = GetOrCreateScopeData(data, scope);
				orCreateScopeData.Items.Clear();
				foreach (var (num2, steamWorkshopStoredUpdateItem2) in items)
				{
					orCreateScopeData.Items[num2.ToString()] = new SteamWorkshopUpdateSnapshotEntry
					{
						Updated = steamWorkshopStoredUpdateItem2.Updated,
						Title = steamWorkshopStoredUpdateItem2.Title
					};
				}
			});
			Store.Save("steam_workshop_update_snapshot");
		}

		internal static void Merge(SteamWorkshopUpdateScope scope, IReadOnlyDictionary<ulong, SteamWorkshopStoredUpdateItem> items)
		{
			EnsureInitialized();
			Store.Modify("steam_workshop_update_snapshot", delegate(SteamWorkshopUpdateSnapshotData data)
			{
				SteamWorkshopUpdateScopeData orCreateScopeData = GetOrCreateScopeData(data, scope);
				foreach (var (num2, steamWorkshopStoredUpdateItem2) in items)
				{
					orCreateScopeData.Items[num2.ToString()] = new SteamWorkshopUpdateSnapshotEntry
					{
						Updated = steamWorkshopStoredUpdateItem2.Updated,
						Title = steamWorkshopStoredUpdateItem2.Title
					};
				}
			});
			Store.Save("steam_workshop_update_snapshot");
		}

		private static void EnsureInitialized()
		{
			using (SyncRoot.EnterScope())
			{
				if (_initialized)
				{
					return;
				}
				using (RitsuLibFramework.BeginModDataRegistration("com.ritsukage.sts2-RitsuLib", initializeProfileIfReady: false))
				{
					Store.Register("steam_workshop_update_snapshot", "steam_workshop_update_snapshot.json", SaveScope.Global, () => new SteamWorkshopUpdateSnapshotData(), autoCreateIfMissing: true);
				}
				_initialized = true;
			}
		}

		private static SteamWorkshopUpdateScopeData GetOrCreateScopeData(SteamWorkshopUpdateSnapshotData data, SteamWorkshopUpdateScope scope)
		{
			if (data.Scopes.TryGetValue(scope.Key, out SteamWorkshopUpdateScopeData value))
			{
				value.DisplayName = scope.DisplayName;
				value.BranchName = scope.BranchName;
				return value;
			}
			value = new SteamWorkshopUpdateScopeData
			{
				DisplayName = scope.DisplayName,
				BranchName = scope.BranchName
			};
			data.Scopes[scope.Key] = value;
			return value;
		}
	}
	internal readonly record struct SteamWorkshopStoredUpdateItem(uint Updated, string? Title);
}
namespace STS2RitsuLib.Platform.Patches
{
	/// <summary>
	///     <para xml:lang="en">
	///         Applies deferred Harmony patches after <see cref="M:MegaCrit.Sts2.Core.Models.ModelDb.Init(System.Type[])" />. These patches cannot resolve their
	///         targets during the first mod-load pass because resolution can trigger static initialization that
	///         depends on <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在 <see cref="M:MegaCrit.Sts2.Core.Models.ModelDb.Init(System.Type[])" /> 后应用延迟的 Harmony 补丁。这些补丁不能在首次加载模组时解析目标，
	///         因为解析可能触发依赖 <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" /> 的静态初始化。
	///     </para>
	/// </summary>
	internal sealed class RitsuLibModelDbInitPostfixPatch : IPatchMethod
	{
		private static int _applied;

		public static string PatchId => "model_db_init_apply_deferred_patches";

		public static string Description => "After ModelDb.Init, apply deferred patches whose target resolution can trigger model-dependent static init";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ModelDb), "Init")
			};
		}

		public static void Postfix()
		{
			if (Interlocked.Exchange(ref _applied, 1) != 0)
			{
				return;
			}
			try
			{
				ModPatcher frameworkPatcher = RitsuLibFramework.GetFrameworkPatcher(RitsuLibFramework.FrameworkPatcherArea.Core);
				List<ModPatchInfo> list = new List<ModPatchInfo>();
				list.AddRange(IPatchMethod.CreatePatchInfos<NDailyRunLoadScreenBeginRunMissingCharacterPatch>());
				list.AddRange(IPatchMethod.CreatePatchInfos<ModModelIdentityRunStateCreatePatch>());
				list.AddRange(IPatchMethod.CreatePatchInfos<ModRightClickCardHolderPatch>());
				list.AddRange(IPatchMethod.CreatePatchInfos<ModRightClickCardPilePatch>());
				list.AddRange(IPatchMethod.CreatePatchInfos<ModRightClickRelicPatch>());
				list.AddRange(IPatchMethod.CreatePatchInfos<ModRightClickPowerPatch>());
				list.AddRange(IPatchMethod.CreatePatchInfos<ModRightClickPotionPatch>());
				list.AddRange(IPatchMethod.CreatePatchInfos<ModRightClickOrbPatch>());
				frameworkPatcher.ApplyLateStaticPatches(new ReadOnlySpan<ModPatchInfo>(list.ToArray()));
				List<ModPatchInfo> list2 = new List<ModPatchInfo>();
				list2.AddRange(IPatchMethod.CreatePatchInfos<CharacterUnlockFilterPatch>());
				list2.AddRange(IPatchMethod.CreatePatchInfos<SharedAncientUnlockFilterPatch>());
				list2.AddRange(IPatchMethod.CreatePatchInfos<EliteEpochAfterCombatFallbackPatch>());
				RitsuLibFramework.GetFrameworkPatcher(RitsuLibFramework.FrameworkPatcherArea.Unlocks).ApplyLateStaticPatches(new ReadOnlySpan<ModPatchInfo>(list2.ToArray()));
				RitsuLibFramework.Logger.Info("[ModelDbDefer] Applied deferred patches after ModelDb.Init.", 1);
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[ModelDbDefer] Failed to apply deferred patches after ModelDb.Init: {value}");
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Suppresses the base game's runtime mod-detection callback for Workshop downloads that RitsuLib itself
	///         triggered during an update check.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         对 RitsuLib 在更新检查中自行触发的创意工坊下载，阻止原版游戏的运行时模组检测回调。
	///     </para>
	/// </summary>
	internal sealed class SteamWorkshopRuntimeInstallCallbackPatch : IPatchMethod
	{
		public static string PatchId => "steam_workshop_runtime_install_callback_ritsulib_update_guard";

		public static string Description => "Suppress vanilla runtime mod detection for Workshop downloads triggered by RitsuLib update checks";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1] { PatchTarget.OptionalMethod(typeof(ModManager), "OnSteamWorkshopItemInstalled") };
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Skips the original callback only when its event identifies a recorded RitsuLib-triggered
		///         Workshop download.
		///     </para>
		///     <para xml:lang="zh-CN">仅当事件标识出已记录的 RitsuLib 触发创意工坊下载时，才跳过原始回调。</para>
		/// </summary>
		public static bool Prefix(object[] __args)
		{
			if (__args.Length == 0)
			{
				return true;
			}
			ulong? value = TryReadItemId(__args[0]);
			if (!value.HasValue)
			{
				return true;
			}
			if (!RitsuSteamWorkshopUpdates.IsTriggeredDownloadItem(value.Value))
			{
				return true;
			}
			RitsuLibFramework.Logger.Info($"[SteamWorkshopUpdate] Suppressed vanilla runtime Workshop install handling for recorded RitsuLib-triggered item {value}.", 1);
			return false;
		}

		private static ulong? TryReadItemId(object ev)
		{
			try
			{
				object obj = ev.GetType().GetField("m_nPublishedFileId")?.GetValue(ev);
				object obj2 = obj?.GetType().GetField("m_PublishedFileId")?.GetValue(obj);
				return (obj2 == null) ? ((ulong?)null) : new ulong?(Convert.ToUInt64(obj2));
			}
			catch
			{
				return null;
			}
		}
	}
}
