	{
		/// <summary>
		///     <para xml:lang="en">Creates a target with <see cref="P:STS2RitsuLib.Patching.Models.ModPatchTarget.HarmonyMethodType" /> set to <see cref="F:HarmonyLib.MethodType.Normal" />.</para>
