		/// <inheritdoc />
		public override string ToString()
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0027: Unknown result type (might be due to invalid IL or missing references)
			string text = (((int)HarmonyMethodType != 0) ? $" [{HarmonyMethodType}]" : "");
			if (ParameterTypes == null)
			{
				return TargetType.Name + "." + MethodName + text;
			}
			string value = ((ParameterTypes.Length == 0) ? "no parameters" : string.Join(", ", ParameterTypes.Select((Type p) => p.Name)));
			return $"{TargetType.Name}.{MethodName}({value}){text}";
		}

