			TargetType = this.TargetType;
			MethodName = this.MethodName;
			ParameterTypes = this.ParameterTypes;
			IgnoreIfMissing = this.IgnoreIfMissing;
			HarmonyMethodType = (MethodType)(int)this.HarmonyMethodType;
		}
	}
