		/// <param name="patcherName">
		///     <para xml:lang="en">Optional display name included in the log prefix.</para>
		///     <para xml:lang="zh-CN">包含在日志前缀中的可选显示名称。</para>
		/// </param>
		public ModPatcher(string patcherId, Logger logger, string patcherName = "")
		{
			//IL_0027: Unknown result type (might be due to invalid IL or missing references)
			//IL_0031: Expected O, but got Unknown
			<patcherId>P = patcherId;
			<logger>P = logger;
			<patcherName>P = patcherName;
			_dynamicPatchLifetimeLeases = new Dictionary<string, IDisposable>();
			_harmony = new Harmony(<patcherId>P);
			_logPrefix = (string.IsNullOrEmpty(<patcherName>P) ? "[Patcher] " : ("[Patcher - " + <patcherName>P + "] "));
			_patchedStatus = new Dictionary<string, bool>();
			_registeredDynamicPatches = new List<DynamicPatchInfo>();
			_registeredPatches = new List<ModPatchInfo>();
			base..ctor();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a static patch. Duplicate IDs are skipped; registration after <see cref="M:STS2RitsuLib.Patching.Core.ModPatcher.PatchAll" />
