		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册静态补丁。重复的 ID 会被跳过；在 <see cref="M:STS2RitsuLib.Patching.Core.ModPatcher.PatchAll" /> 成功后注册会抛出
		///         <see cref="T:System.InvalidOperationException" />。
		///     </para>
		/// </summary>
		public void RegisterPatch(ModPatchInfo modPatchInfo)
		{
			if (IsApplied)
			{
				<logger>P.ErrorNoTrace(_logPrefix + "Cannot register patch '" + modPatchInfo.Id + "': Patches have already been applied");
				throw new InvalidOperationException("Cannot register patches after they have been applied");
			}
			if (_registeredPatches.Any((ModPatchInfo p) => p.Id == modPatchInfo.Id))
			{
				<logger>P.Warn(_logPrefix + "Patch '" + modPatchInfo.Id + "' already registered, skipping duplicate", 1);
				return;
			}
			ValidatePatchType(modPatchInfo);
			PatchLog.Bind(modPatchInfo.PatchType, <logger>P);
			_registeredPatches.Add(modPatchInfo);
			<logger>P.Debug($"{_logPrefix}Registered patch: {modPatchInfo.Id} - {modPatchInfo.Description}", 1);
		}

		/// <summary>
		///     <para xml:lang="en">Registers each patch in <paramref name="patches" />.</para>
		///     <para xml:lang="zh-CN">注册 <paramref name="patches" /> 中的每个补丁。</para>
		/// </summary>
		public void RegisterPatches(params ReadOnlySpan<ModPatchInfo> patches)
		{
			ReadOnlySpan<ModPatchInfo> readOnlySpan = patches;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				ModPatchInfo modPatchInfo = readOnlySpan[i];
				RegisterPatch(modPatchInfo);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers a dynamic patch. Duplicate IDs are skipped.</para>
		///     <para xml:lang="zh-CN">注册动态补丁。重复的 ID 会被跳过。</para>
		/// </summary>
		public void RegisterDynamicPatch(DynamicPatchInfo dynamicPatchInfo)
		{
			ArgumentNullException.ThrowIfNull(dynamicPatchInfo, "dynamicPatchInfo");
			TryRegisterDynamicPatch(dynamicPatchInfo);
		}

		private bool TryRegisterDynamicPatch(DynamicPatchInfo dynamicPatchInfo)
		{
			ArgumentNullException.ThrowIfNull(dynamicPatchInfo, "dynamicPatchInfo");
			if (_registeredDynamicPatches.Any((DynamicPatchInfo p) => p.Id == dynamicPatchInfo.Id))
			{
				<logger>P.Warn(_logPrefix + "Dynamic patch '" + dynamicPatchInfo.Id + "' already registered, skipping duplicate", 1);
				return false;
			}
			_registeredDynamicPatches.Add(dynamicPatchInfo);
			<logger>P.Debug($"{_logPrefix}Registered dynamic patch: {dynamicPatchInfo.Id} - {dynamicPatchInfo.Description}", 1);
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Registers each patch in <paramref name="dynamicPatches" />.</para>
		///     <para xml:lang="zh-CN">注册 <paramref name="dynamicPatches" /> 中的每个补丁。</para>
		/// </summary>
		public void RegisterDynamicPatches(params ReadOnlySpan<DynamicPatchInfo> dynamicPatches)
		{
			ReadOnlySpan<DynamicPatchInfo> readOnlySpan = dynamicPatches;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				DynamicPatchInfo dynamicPatchInfo = readOnlySpan[i];
				RegisterDynamicPatch(dynamicPatchInfo);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers and immediately applies previously unregistered dynamic patch IDs. Duplicate IDs are
		///         skipped. When a critical patch fails and <paramref name="rollbackOnCriticalFailure" /> is
		///         <see langword="true" />, attempts to remove all patches owned by this patcher.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册并立即应用此前未注册 ID 的动态补丁，重复 ID 会被跳过。严重补丁失败且
		///         <paramref name="rollbackOnCriticalFailure" /> 为 <see langword="true" /> 时，尝试移除此
		///         补丁器拥有的所有补丁。
		///     </para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en"><see langword="false" /> when any critical patch fails; otherwise <see langword="true" />.</para>
		///     <para xml:lang="zh-CN">任何严重补丁失败时为 <see langword="false" />；否则为 <see langword="true" />。</para>
		/// </returns>
		public bool ApplyDynamicPatches(IEnumerable<DynamicPatchInfo> dynamicPatches, bool rollbackOnCriticalFailure = false)
		{
			ArgumentNullException.ThrowIfNull(dynamicPatches, "dynamicPatches");
			DynamicPatchInfo[] array = dynamicPatches.ToArray();
			if (array.Length == 0)
			{
				return true;
			}
			DynamicPatchInfo[] array2 = array.Where(TryRegisterDynamicPatch).ToArray();
			if (array2.Length == 0)
			{
				return true;
			}
			<logger>P.Info($"{_logPrefix}Applying {array2.Length} dynamic patch(es)...", 1);
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			DynamicPatchInfo[] array3 = array2;
			foreach (DynamicPatchInfo dynamicPatchInfo in array3)
			{
				<logger>P.Debug($"{_logPrefix}[{(dynamicPatchInfo.IsCritical ? "Critical" : "Optional")}] {dynamicPatchInfo.Id} - Begin", 1);
				var (flag, value, ex) = ApplyDynamicPatch(dynamicPatchInfo);
				if (flag)
				{
					num++;
					<logger>P.Debug($"{_logPrefix}[{(dynamicPatchInfo.IsCritical ? "Critical" : "Optional")}] {dynamicPatchInfo.Id} - Success ✓", 1);
					continue;
				}
				num2++;
				if (dynamicPatchInfo.IsCritical)
				{
					num3++;
				}
				StringBuilder stringBuilder = new StringBuilder();
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder3 = stringBuilder2;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(14, 3, stringBuilder2);
				handler.AppendFormatted(_logPrefix);
				handler.AppendLiteral("[");
				handler.AppendFormatted(dynamicPatchInfo.IsCritical ? "Critical" : "Optional");
				handler.AppendLiteral("] ");
				handler.AppendFormatted(dynamicPatchInfo.Id);
				handler.AppendLiteral(" - Failed ✗");
				stringBuilder3.AppendLine(ref handler);
				if (ex != null)
				{
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder4 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(11, 1, stringBuilder2);
					handler.AppendLiteral("Exception: ");
					handler.AppendFormatted(ex);
					stringBuilder4.Append(ref handler);
				}
				else
				{
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder5 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(7, 1, stringBuilder2);
					handler.AppendLiteral("Error: ");
					handler.AppendFormatted(value);
					stringBuilder5.Append(ref handler);
				}
				<logger>P.ErrorNoTrace(stringBuilder.ToString());
			}
			<logger>P.Info($"{_logPrefix}Dynamic patch application complete: {num}/{array2.Length} succeeded", 1);
			if (num2 > 0)
			{
				<logger>P.ErrorNoTrace((num3 > 0) ? $"{_logPrefix}{num2} dynamic patch(es) failed, including {num3} critical failure(s)" : $"{_logPrefix}{num2} dynamic patch(es) failed, but no critical failures");
			}
			if (num3 == 0)
			{
				return true;
			}
			if (rollbackOnCriticalFailure)
			{
				UnpatchAll();
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Applies all registered static patches once. If a critical patch fails, calls <see cref="M:STS2RitsuLib.Patching.Core.ModPatcher.UnpatchAll" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         应用所有已注册的静态补丁一次。严重补丁失败时调用 <see cref="M:STS2RitsuLib.Patching.Core.ModPatcher.UnpatchAll" />。
		///     </para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> when no critical patch fails; otherwise <see langword="false" />.</para>
		///     <para xml:lang="zh-CN">没有严重补丁失败时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public bool PatchAll()
		{
			if (IsApplied)
			{
				<logger>P.Warn(_logPrefix + "Patches have already been applied, skipping", 1);
				return true;
			}
			<logger>P.Info($"{_logPrefix}Applying {_registeredPatches.Count} patches...", 1);
			ModPatchResult[] array = new ModPatchResult[_registeredPatches.Count];
			for (int i = 0; i < _registeredPatches.Count; i++)
			{
				array[i] = ApplyPatch(_registeredPatches[i]);
			}
			bool num = ProcessPatchResults(array);
			int num2 = array.Count((ModPatchResult result) => result.Ignored);
			int num3 = array.Count((ModPatchResult result) => !result.Success);
			if (num)
			{
				IsApplied = true;
				if (num2 == 0 && num3 == 0)
				{
					<logger>P.Info(_logPrefix + "All patches applied successfully", 1);
					return num;
				}
				if (num3 == 0)
				{
					<logger>P.Info($"{_logPrefix}All required patches applied; {num2} optional patch target(s) were ignored", 1);
					return num;
				}
				<logger>P.ErrorNoTrace(_logPrefix + "Critical patches succeeded, but some optional patches failed to apply");
				return num;
			}
			<logger>P.ErrorNoTrace(_logPrefix + "Critical patch(es) failed, rolling back all patches...");
			UnpatchAll();
			IsApplied = false;
			return num;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Applies additional static patches after <see cref="M:STS2RitsuLib.Patching.Core.ModPatcher.PatchAll" />, such as patches that must wait for
		///         <c>ModelDb.Init</c> on Android. Individual failures are logged.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <see cref="M:STS2RitsuLib.Patching.Core.ModPatcher.PatchAll" /> 之后应用额外的静态补丁，例如 Android 上必须等待
		///         <c>ModelDb.Init</c> 的补丁。单个补丁的失败会记录到日志。
		///     </para>
		/// </summary>
		public void ApplyLateStaticPatches(ReadOnlySpan<ModPatchInfo> patches)
		{
			if (!IsApplied)
			{
				throw new InvalidOperationException("PatchAll must complete before applying late static patches.");
			}
			ReadOnlySpan<ModPatchInfo> readOnlySpan = patches;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				ModPatchInfo modPatchInfo = readOnlySpan[i];
				if (!_patchedStatus.GetValueOrDefault(modPatchInfo.Id, defaultValue: false))
				{
					ModPatchResult modPatchResult = ApplyPatch(modPatchInfo);
					if (!modPatchResult.Success)
					{
						string value = (modPatchInfo.IsCritical ? "Critical" : "Optional");
						<logger>P.ErrorNoTrace($"{_logPrefix}[Late][{value}] {modPatchInfo.Id} failed: {modPatchResult.ErrorMessage}");
					}
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Removes matching Harmony patches owned by another Harmony ID from
		///         <paramref name="originalMethod" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从 <paramref name="originalMethod" /> 移除由另一个 Harmony ID 拥有且符合条件的补丁。
		///     </para>
		/// </summary>
		/// <param name="originalMethod">
		///     <para xml:lang="en">Original method whose patch list is inspected.</para>
		///     <para xml:lang="zh-CN">要检查补丁列表的原始方法。</para>
		/// </param>
		/// <param name="owner">
		///     <para xml:lang="en">Harmony owner ID to remove.</para>
		///     <para xml:lang="zh-CN">要移除的 Harmony 所有者 ID。</para>
		/// </param>
		/// <param name="patchDeclaringType">
		///     <para xml:lang="en">Optional declaring-type filter for patch methods.</para>
		///     <para xml:lang="zh-CN">可选的补丁方法声明类型筛选条件。</para>
		/// </param>
		/// <param name="patchMethodName">
		///     <para xml:lang="en">Optional patch-method name filter.</para>
		///     <para xml:lang="zh-CN">可选的补丁方法名称筛选条件。</para>
		/// </param>
		/// <param name="patchType">
		///     <para xml:lang="en">Harmony patch kind to inspect; <see cref="F:HarmonyLib.HarmonyPatchType.All" /> inspects every kind.</para>
		///     <para xml:lang="zh-CN">要检查的 Harmony 补丁类型；<see cref="F:HarmonyLib.HarmonyPatchType.All" /> 表示检查所有类型。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The number of patch methods removed.</para>
		///     <para xml:lang="zh-CN">已移除的补丁方法数量。</para>
		/// </returns>
		public int UnpatchExternalPatches(MethodBase originalMethod, string owner, Type? patchDeclaringType = null, string? patchMethodName = null, HarmonyPatchType patchType = (HarmonyPatchType)0)
		{
			//IL_0066: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(originalMethod, "originalMethod");
			ArgumentException.ThrowIfNullOrWhiteSpace(owner, "owner");
			Patches patchInfo = Harmony.GetPatchInfo(originalMethod);
			if (patchInfo == null)
			{
				<logger>P.Info(_logPrefix + "No Harmony patches found on " + FormatMethod(originalMethod), 1);
				return 0;
			}
			Patch[] array = (from patch in EnumeratePatches(patchInfo, patchType)
				where MatchesPatch(patch, owner, patchDeclaringType, patchMethodName)
				select patch).ToArray();
			Patch[] array2 = array;
			foreach (Patch val in array2)
			{
				_harmony.Unpatch(originalMethod, val.PatchMethod);
			}
			<logger>P.Info($"{_logPrefix}Removed {array.Length} external patch(es) from {FormatMethod(originalMethod)} owned by '{owner}'", 1);
			return array.Length;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves <paramref name="target" /> and removes matching external Harmony patches. A missing target
		///         can be ignored.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         解析 <paramref name="target" /> 并移除符合条件的外部 Harmony 补丁。缺失的目标可被忽略。
		///     </para>
		/// </summary>
		public int UnpatchExternalPatches(ModPatchTarget target, string owner, Type? patchDeclaringType = null, string? patchMethodName = null, HarmonyPatchType patchType = (HarmonyPatchType)0, bool ignoreIfTargetMissing = true)
		{
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(target, "target");
			MethodBase methodBase = PatchTargetMethodResolver.Resolve(target);
			if (methodBase != null)
			{
				return UnpatchExternalPatches(methodBase, owner, patchDeclaringType, patchMethodName, patchType);
			}
			string text = $"{_logPrefix}External unpatch target not found: {target}";
			if (!ignoreIfTargetMissing && !target.IgnoreIfMissing)
			{
				throw new MissingMethodException(target.TargetType.FullName, target.MethodName);
			}
			<logger>P.Info(text, 1);
			return 0;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to remove every applied patch tracked by this instance from its Harmony ID. Failed
		///         removals remain marked as applied so a later call can retry them.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试从此实例的 Harmony ID 移除其跟踪的所有已应用补丁。移除失败的补丁会继续标记为已应用，
		///         以便之后再次调用时重试。
		///     </para>
		/// </summary>
		public void UnpatchAll()
		{
			if (_registeredPatches.Count == 0 && _registeredDynamicPatches.Count == 0)
			{
				<logger>P.Debug(_logPrefix + "No patches registered, skipping unpatch", 1);
				return;
			}
			int num = _registeredPatches.Count((ModPatchInfo patchInfo) => _patchedStatus.GetValueOrDefault(patchInfo.Id, defaultValue: false)) + _registeredDynamicPatches.Count((DynamicPatchInfo patchInfo) => _patchedStatus.GetValueOrDefault(patchInfo.Id, defaultValue: false));
			if (num == 0)
			{
				<logger>P.Debug(_logPrefix + "No patches applied, skipping unpatch", 1);
				IsApplied = false;
				return;
			}
			<logger>P.Info($"{_logPrefix}Removing {num} applied patches...", 1);
			bool isApplied = IsApplied;
			int num2 = 0;
			foreach (ModPatchInfo item in _registeredPatches.Where((ModPatchInfo patchInfo) => _patchedStatus.GetValueOrDefault(patchInfo.Id, defaultValue: false)))
			{
				try
				{
					MethodBase originalMethod = GetOriginalMethod(item);
					if (originalMethod == null)
					{
						num2++;
						<logger>P.ErrorNoTrace(_logPrefix + "✗ Failed to remove patch: " + item.Id + " - original method unavailable");
					}
					else
					{
						_harmony.Unpatch(originalMethod, (HarmonyPatchType)0, _harmony.Id);
						_patchedStatus[item.Id] = false;
						<logger>P.Debug(_logPrefix + "✓ Removed patch: " + item.Id, 1);
					}
				}
				catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
				{
					num2++;
					<logger>P.ErrorNoTrace($"{_logPrefix}✗ Failed to remove patch: {item.Id} - {ex}");
				}
			}
			foreach (DynamicPatchInfo item2 in _registeredDynamicPatches.Where((DynamicPatchInfo patchInfo) => _patchedStatus.GetValueOrDefault(patchInfo.Id, defaultValue: false)))
			{
				try
				{
					_harmony.Unpatch(item2.OriginalMethod, (HarmonyPatchType)0, _harmony.Id);
					ReleaseDynamicPatchLifetime(item2.Id);
					_patchedStatus[item2.Id] = false;
					<logger>P.Debug(_logPrefix + "✓ Removed dynamic patch: " + item2.Id, 1);
				}
				catch (Exception ex2) when (RitsuLibExceptionPolicy.IsRecoverable(ex2))
				{
					num2++;
					<logger>P.ErrorNoTrace($"{_logPrefix}✗ Failed to remove dynamic patch: {item2.Id} - {ex2}");
				}
			}
			IsApplied = (num2 > 0) & isApplied;
			if (num2 == 0)
			{
				<logger>P.Info(_logPrefix + "All patches removed", 1);
				return;
			}
			<logger>P.ErrorNoTrace($"{_logPrefix}Patch removal incomplete: {num2} patch(es) remain available for retry");
		}

		private ModPatchResult ApplyPatch(ModPatchInfo modPatchInfo)
		{
			//IL_01b0: Unknown result type (might be due to invalid IL or missing references)
			//IL_01c2: Unknown result type (might be due to invalid IL or missing references)
			//IL_01d6: Unknown result type (might be due to invalid IL or missing references)
			//IL_01ea: Unknown result type (might be due to invalid IL or missing references)
			<logger>P.Debug($"{_logPrefix}[{(modPatchInfo.IsCritical ? "Critical" : "Optional")}] {modPatchInfo.Id} - Begin", 1);
			try
			{
				MethodBase originalMethod = GetOriginalMethod(modPatchInfo);
				if (originalMethod == null)
				{
					_patchedStatus[modPatchInfo.Id] = false;
					if (modPatchInfo.IgnoreIfTargetMissing)
					{
						return ModPatchResult.CreateIgnored(modPatchInfo, "Target method not found but patch is marked ignorable: " + modPatchInfo.TargetType.Name + "." + modPatchInfo.MethodName);
					}
					return ModPatchResult.CreateFailure(modPatchInfo, "Target method not found: " + modPatchInfo.TargetType.Name + "." + modPatchInfo.MethodName);
				}
				MethodInfo patchMethod = GetPatchMethod(modPatchInfo.PatchType, "Prefix");
				MethodInfo patchMethod2 = GetPatchMethod(modPatchInfo.PatchType, "Postfix");
				MethodInfo patchMethod3 = GetPatchMethod(modPatchInfo.PatchType, "Transpiler");
				MethodInfo patchMethod4 = GetPatchMethod(modPatchInfo.PatchType, "Finalizer");
				if (patchMethod == null && patchMethod2 == null && patchMethod3 == null && patchMethod4 == null)
				{
					_patchedStatus[modPatchInfo.Id] = false;
					return ModPatchResult.CreateFailure(modPatchInfo, "No valid patch methods found in " + modPatchInfo.PatchType.Name);
				}
				_harmony.Patch(originalMethod, (!(patchMethod != null)) ? ((HarmonyMethod)null) : new HarmonyMethod(patchMethod), (!(patchMethod2 != null)) ? ((HarmonyMethod)null) : new HarmonyMethod(patchMethod2), (!(patchMethod3 != null)) ? ((HarmonyMethod)null) : new HarmonyMethod(patchMethod3), (!(patchMethod4 != null)) ? ((HarmonyMethod)null) : new HarmonyMethod(patchMethod4));
				_patchedStatus[modPatchInfo.Id] = true;
				<logger>P.Debug($"{_logPrefix}[{(modPatchInfo.IsCritical ? "Critical" : "Optional")}] {modPatchInfo.Id} - Success ✓", 1);
				return ModPatchResult.CreateSuccess(modPatchInfo);
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				_patchedStatus[modPatchInfo.Id] = false;
				return ModPatchResult.CreateFailure(modPatchInfo, ex.Message, ex);
			}
		}

		private (bool Success, string ErrorMessage, Exception? Exception) ApplyDynamicPatch(DynamicPatchInfo dynamicPatchInfo)
		{
			IDisposable disposable = null;
			bool flag = false;
			try
			{
				if (!dynamicPatchInfo.HasPatchMethods)
				{
					_patchedStatus[dynamicPatchInfo.Id] = false;
					return (Success: false, ErrorMessage: "No valid patch methods found for dynamic patch '" + dynamicPatchInfo.Id + "'", Exception: null);
				}
				disposable = dynamicPatchInfo.AcquireLifetimeLease();
				if (disposable != null)
				{
					_dynamicPatchLifetimeLeases.Add(dynamicPatchInfo.Id, disposable);
					flag = true;
				}
				_harmony.Patch(dynamicPatchInfo.OriginalMethod, dynamicPatchInfo.Prefix, dynamicPatchInfo.Postfix, dynamicPatchInfo.Transpiler, dynamicPatchInfo.Finalizer);
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				if (flag && _dynamicPatchLifetimeLeases.Remove(dynamicPatchInfo.Id, out IDisposable value))
				{
					value.Dispose();
				}
				else
				{
					disposable?.Dispose();
				}
				_patchedStatus[dynamicPatchInfo.Id] = false;
				return (Success: false, ErrorMessage: ex.Message, Exception: ex);
			}
			_patchedStatus[dynamicPatchInfo.Id] = true;
			<logger>P.Debug($"{_logPrefix}[{(dynamicPatchInfo.IsCritical ? "Critical" : "Optional")}] {dynamicPatchInfo.Id} - Success ✓", 1);
			return (Success: true, ErrorMessage: string.Empty, Exception: null);
		}

		private void ReleaseDynamicPatchLifetime(string patchId)
		{
			if (_dynamicPatchLifetimeLeases.Remove(patchId, out IDisposable value))
			{
				value.Dispose();
			}
		}

		private bool ProcessPatchResults(ReadOnlySpan<ModPatchResult> results)
		{
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			int num4 = 0;
			foreach (ModPatchResult item in from r in results.ToArray()
				orderby r.Success, r.ModPatchInfo.IsCritical descending, r.ModPatchInfo.Id
				select r)
			{
				string value = (item.ModPatchInfo.IsCritical ? "Critical" : "Optional");
				if (item.Success)
				{
					num++;
					if (item.Ignored)
					{
						num2++;
					}
					if (item.Ignored)
					{
						<logger>P.Info($"{_logPrefix}[{value}] {item.ModPatchInfo.Id} - Ignored: {item.ErrorMessage}", 1);
					}
					else
					{
						<logger>P.Debug($"{_logPrefix}[{value}] {item.ModPatchInfo.Id} - Success ✓", 1);
					}
					continue;
				}
				num3++;
				if (item.ModPatchInfo.IsCritical)
				{
					num4++;
				}
				StringBuilder stringBuilder = new StringBuilder();
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder3 = stringBuilder2;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(14, 3, stringBuilder2);
				handler.AppendFormatted(_logPrefix);
				handler.AppendLiteral("[");
				handler.AppendFormatted(value);
				handler.AppendLiteral("] ");
				handler.AppendFormatted(item.ModPatchInfo.Id);
				handler.AppendLiteral(" - Failed ✗");
				stringBuilder3.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder4 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(15, 2, stringBuilder2);
				handler.AppendFormatted(_logPrefix);
				handler.AppendLiteral("  Description: ");
				handler.AppendFormatted(item.ModPatchInfo.Description);
				stringBuilder4.AppendLine(ref handler);
				stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder5 = stringBuilder2;
				handler = new StringBuilder.AppendInterpolatedStringHandler(9, 2, stringBuilder2);
				handler.AppendFormatted(_logPrefix);
				handler.AppendLiteral("  Error: ");
				handler.AppendFormatted(item.ErrorMessage);
				stringBuilder5.AppendLine(ref handler);
				if (item.Exception != null)
				{
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder6 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(13, 2, stringBuilder2);
					handler.AppendFormatted(_logPrefix);
					handler.AppendLiteral("  Exception: ");
					handler.AppendFormatted(item.Exception);
					stringBuilder6.Append(ref handler);
				}
				<logger>P.ErrorNoTrace(stringBuilder.ToString());
			}
			<logger>P.Info($"{_logPrefix}Patch application complete: {num - num2} applied, {num2} ignored, {num3} failed, {results.Length} total", 1);
			if (num3 > 0)
			{
				<logger>P.ErrorNoTrace($"{_logPrefix}{num3} patch(es) failed");
			}
			if (num4 == 0)
