				return true;
			}
			<logger>P.ErrorNoTrace($"{_logPrefix}{num4} critical patch(es) failed, mod loading blocked");
			return false;
		}

		private static MethodBase? GetOriginalMethod(ModPatchInfo modPatchInfo)
		{
