		}

		private static IEnumerable<Patch> EnumeratePatches(Patches patchInfo, HarmonyPatchType patchType)
		{
			//IL_000f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			if ((int)patchType <= 1)
			{
				foreach (Patch prefix in patchInfo.Prefixes)
				{
					yield return prefix;
				}
			}
			HarmonyPatchType val = patchType;
			if (((int)val == 0 || (int)val == 2) ? true : false)
			{
				foreach (Patch postfix in patchInfo.Postfixes)
				{
					yield return postfix;
				}
			}
			val = patchType;
			if (((int)val == 0 || (int)val == 3) ? true : false)
			{
				foreach (Patch transpiler in patchInfo.Transpilers)
				{
					yield return transpiler;
				}
			}
			val = patchType;
			if (((int)val != 0 && (int)val != 4) || 1 == 0)
			{
				yield break;
			}
			foreach (Patch finalizer in patchInfo.Finalizers)
			{
				yield return finalizer;
			}
		}

		private static bool MatchesPatch(Patch patch, string owner, Type? patchDeclaringType, string? patchMethodName)
		{
			if (patch.owner != owner)
			{
				return false;
			}
			if (patchDeclaringType != null && patch.PatchMethod.DeclaringType != patchDeclaringType)
			{
				return false;
			}
			if (!string.IsNullOrEmpty(patchMethodName))
			{
				return patch.PatchMethod.Name == patchMethodName;
			}
			return true;
		}

		private static string FormatMethod(MethodBase method)
		{
			return method.DeclaringType?.FullName + "." + method.Name;
		}

		/// <summary>
		///     <para xml:lang="en">Warns when a patch type does not implement <see cref="T:STS2RitsuLib.Patching.Models.IPatchMethod" />.</para>
		///     <para xml:lang="zh-CN">补丁类型未实现 <see cref="T:STS2RitsuLib.Patching.Models.IPatchMethod" /> 时记录警告。</para>
		/// </summary>
		private void ValidatePatchType(ModPatchInfo modPatchInfo)
		{
			Type patchType = modPatchInfo.PatchType;
			if (!patchType.GetInterfaces().Any((Type i) => i.Name == "IPatchMethod" || (i.IsGenericType && i.GetGenericTypeDefinition().GetInterfaces().Any((Type gi) => gi.Name == "IPatchMethod"))))
			{
				<logger>P.Warn(_logPrefix + "Patch type '" + patchType.Name + "' does not implement IPatchMethod interface. Consider implementing IPatchMethod interfaces for better type safety and IDE support.", 1);
			}
		}
