	/// <summary>
	///     <para xml:lang="en">Provides extensions for registering and applying patches through <see cref="T:STS2RitsuLib.Patching.Core.ModPatcher" />.</para>
	///     <para xml:lang="zh-CN">提供通过 <see cref="T:STS2RitsuLib.Patching.Core.ModPatcher" /> 注册和应用补丁的扩展方法。</para>
	/// </summary>
	public static class ModPatcherExtensions
	{
		/// <summary>
		///     <para xml:lang="en">Registers patches generated from <paramref name="rule" />.</para>
		///     <para xml:lang="zh-CN">注册由 <paramref name="rule" /> 生成的补丁。</para>
		/// </summary>
		public static void RegisterFromRule(this ModPatcher patcher, ModPatchRule rule, params ReadOnlySpan<Assembly> assemblies)
		{
			ModPatchInfo[] array = rule.GeneratePatches(assemblies);
			patcher.RegisterPatches(array);
		}

		/// <summary>
		///     <para xml:lang="en">Registers patches provided by <typeparamref name="T" />.</para>
		///     <para xml:lang="zh-CN">注册由 <typeparamref name="T" /> 提供的补丁。</para>
		/// </summary>
		public static void RegisterPatches<T>(this ModPatcher patcher) where T : IModPatches
		{
			T.AddTo(patcher);
		}

		/// <summary>
		///     <para xml:lang="en">Registers the patches declared by <typeparamref name="TPatch" />.</para>
		///     <para xml:lang="zh-CN">注册由 <typeparamref name="TPatch" /> 声明的补丁。</para>
		/// </summary>
		public static void RegisterPatch<TPatch>(this ModPatcher patcher) where TPatch : IPatchMethod
		{
			ModPatchInfo[] array = IPatchMethod.CreatePatchInfos<TPatch>();
			patcher.RegisterPatches(array);
		}

		/// <summary>
		///     <para xml:lang="en">Applies the runtime-discovered patches collected by <paramref name="builder" />.</para>
		///     <para xml:lang="zh-CN">应用 <paramref name="builder" /> 收集的运行时补丁。</para>
		/// </summary>
		public static bool ApplyDynamic(this ModPatcher patcher, DynamicPatchBuilder builder, bool rollbackOnCriticalFailure = false)
		{
			ArgumentNullException.ThrowIfNull(builder, "builder");
			return patcher.ApplyDynamicPatches(builder.Patches, rollbackOnCriticalFailure);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides a logger registry for patch types.</para>
	///     <para xml:lang="zh-CN">提供补丁类型的日志器注册表。</para>
	/// </summary>
	public static class PatchLog
	{
		private static readonly ConcurrentDictionary<Type, Logger> Registry = new ConcurrentDictionary<Type, Logger>();

		/// <summary>
		///     <para xml:lang="en">Associates <paramref name="logger" /> with <paramref name="patchType" />.</para>
		///     <para xml:lang="zh-CN">将 <paramref name="logger" /> 与 <paramref name="patchType" /> 关联。</para>
		/// </summary>
		public static void Bind(Type patchType, Logger logger)
		{
			ArgumentNullException.ThrowIfNull(patchType, "patchType");
			ArgumentNullException.ThrowIfNull(logger, "logger");
			Registry[patchType] = logger;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the logger bound to <paramref name="patchType" />, or <see cref="P:STS2RitsuLib.RitsuLibFramework.Logger" />
		///         when none is bound.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取绑定到 <paramref name="patchType" /> 的日志器；未绑定时返回
		///         <see cref="P:STS2RitsuLib.RitsuLibFramework.Logger" />。
		///     </para>
		/// </summary>
		public static Logger For(Type patchType)
		{
			ArgumentNullException.ThrowIfNull(patchType, "patchType");
			if (!Registry.TryGetValue(patchType, out Logger value))
			{
				return RitsuLibFramework.Logger;
			}
			return value;
		}

		/// <summary>
		///     <para xml:lang="en">Gets the logger for <typeparamref name="TPatch" />.</para>
		///     <para xml:lang="zh-CN">获取 <typeparamref name="TPatch" /> 的日志器。</para>
		/// </summary>
		public static Logger For<TPatch>()
		{
			return For(typeof(TPatch));
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Resolves a vanilla <see cref="T:System.Reflection.MethodBase" /> from patch-target metadata using the same semantics as
	///         <see cref="T:STS2RitsuLib.Patching.Core.ModPatcher" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         使用与 <see cref="T:STS2RitsuLib.Patching.Core.ModPatcher" /> 相同的语义，从补丁目标元数据解析原版
	///         <see cref="T:System.Reflection.MethodBase" />。
	///     </para>
	/// </summary>
	public static class PatchTargetMethodResolver
	{
		private const BindingFlags AnyDeclaredMethod = BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic;

		/// <summary>
		///     <para xml:lang="en">Resolves a target from <paramref name="modPatchInfo" />.</para>
		///     <para xml:lang="zh-CN">从 <paramref name="modPatchInfo" /> 解析目标。</para>
		/// </summary>
		public static MethodBase? Resolve(ModPatchInfo modPatchInfo)
		{
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			return Resolve(modPatchInfo.TargetType, modPatchInfo.MethodName, modPatchInfo.ParameterTypes, modPatchInfo.HarmonyMethodType);
		}

		/// <summary>
		///     <para xml:lang="en">Resolves <paramref name="target" />.</para>
		///     <para xml:lang="zh-CN">解析 <paramref name="target" />。</para>
		/// </summary>
		public static MethodBase? Resolve(ModPatchTarget target)
		{
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			return Resolve(target.TargetType, target.MethodName, target.ParameterTypes, target.HarmonyMethodType);
		}

		/// <summary>
		///     <para xml:lang="en">Resolves <paramref name="target" /> or throws <see cref="T:System.MissingMethodException" />.</para>
		///     <para xml:lang="zh-CN">解析 <paramref name="target" />；无法解析时抛出 <see cref="T:System.MissingMethodException" />。</para>
		/// </summary>
		public static MethodBase ResolveRequired(ModPatchTarget target)
		{
			//IL_003a: Unknown result type (might be due to invalid IL or missing references)
			return Resolve(target) ?? throw new MissingMethodException(target.TargetType.FullName, $"{target.MethodName} ({target.HarmonyMethodType})");
		}

		/// <summary>
		///     <para xml:lang="en">Resolves the specified target or throws <see cref="T:System.MissingMethodException" />.</para>
		///     <para xml:lang="zh-CN">解析指定目标；无法解析时抛出 <see cref="T:System.MissingMethodException" />。</para>
		/// </summary>
		public static MethodBase ResolveRequired(Type targetType, string methodName, Type[]? parameterTypes, MethodType harmonyMethodType)
		{
			//IL_0003: Unknown result type (might be due to invalid IL or missing references)
			//IL_0032: Unknown result type (might be due to invalid IL or missing references)
			return Resolve(targetType, methodName, parameterTypes, harmonyMethodType) ?? throw new MissingMethodException(targetType.FullName, $"{methodName} ({harmonyMethodType})");
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves a target method. <see cref="F:HarmonyLib.MethodType.Normal" /> uses reflection with inherited-member
		///         lookup; other method types use Harmony <see cref="T:HarmonyLib.AccessTools" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         解析目标方法。<see cref="F:HarmonyLib.MethodType.Normal" /> 使用包含继承成员的反射查找；
		///         其他方法类型使用 Harmony <see cref="T:HarmonyLib.AccessTools" />。
		///     </para>
		/// </summary>
		public static MethodBase? Resolve(Type targetType, string methodName, Type[]? parameterTypes, MethodType harmonyMethodType)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Expected I4, but got Unknown
			return (int)harmonyMethodType switch
			{
				0 => ResolveNormal(targetType, methodName, parameterTypes), 
				6 => GetAsyncStateMachineMoveNext(targetType, methodName, parameterTypes), 
				1 => GetDeclaredImplementation(AccessTools.DeclaredProperty(targetType, methodName)?.GetGetMethod(nonPublic: true)), 
				2 => GetDeclaredImplementation(AccessTools.DeclaredProperty(targetType, methodName)?.GetSetMethod(nonPublic: true)), 
				3 => AccessTools.DeclaredConstructor(targetType, parameterTypes, false), 
				5 => GetEnumeratorMoveNext(targetType, methodName, parameterTypes), 
				_ => ResolveNormal(targetType, methodName, parameterTypes), 
			};
		}

		private static MethodInfo? ResolveNormal(Type targetType, string methodName, Type[]? parameterTypes)
		{
			MethodInfo method = ((parameterTypes == null) ? targetType.GetMethod(methodName, BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic) : targetType.GetMethod(methodName, BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, null, parameterTypes, null));
			return GetDeclaredImplementation(method);
		}

		private static MethodInfo? GetAsyncStateMachineMoveNext(Type targetType, string methodName, Type[]? parameterTypes)
		{
			MethodInfo methodInfo = ResolveNormal(targetType, methodName, parameterTypes);
			if ((object)methodInfo != null)
			{
				return AccessTools.AsyncMoveNext((MethodBase)methodInfo);
			}
			return null;
		}

		private static MethodInfo? GetEnumeratorMoveNext(Type targetType, string methodName, Type[]? parameterTypes)
		{
			MethodInfo methodInfo = ResolveNormal(targetType, methodName, parameterTypes);
			if ((object)methodInfo != null)
			{
				return AccessTools.EnumeratorMoveNext((MethodBase)methodInfo);
			}
			return null;
		}

		private static MethodInfo? GetDeclaredImplementation(MethodInfo? method)
		{
			if ((object)method == null || method.IsAbstract)
			{
				return null;
			}
			Type declaringType = method.DeclaringType;
			if (declaringType == null || method.ReflectedType == declaringType)
			{
				return method;
			}
			Type[] types = (from parameter in method.GetParameters()
				select parameter.ParameterType).ToArray();
			return declaringType.GetMethod(method.Name, BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, null, types, null) ?? method;
		}
	}
}
namespace STS2RitsuLib.Patching.Compat
{
	/// <summary>
	///     <para xml:lang="en">
	///         Preserves init-only setter signatures when Harmony or MonoMod imports reflected methods into Cecil wrappers.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在 Harmony 或 MonoMod 将反射方法导入 Cecil 包装对象时，保留仅初始化 setter 的签名。
	///     </para>
	/// </summary>
	internal static class HarmonyInitSetterCompat
	{
		private sealed class ImporterAccess
		{
			public Type GenericParameterProviderType { get; }

			public Func<object, object?> GetMethodReturnType { get; }

			public Func<object, object?> GetReturnType { get; }

			public Action<object, object> SetReturnType { get; }

			public Func<object, object?> GetModule { get; }

			public Func<object, Type, object?> ImportType { get; }

			public Func<object, object?> GetElementType { get; }

			public Func<object, object?> GetModifierType { get; }

			public Func<object, string?> GetFullName { get; }

			public Func<object, object, object> CreateRequiredModifier { get; }

			public Func<object, object, object> CreateOptionalModifier { get; }

			private ImporterAccess(Type genericParameterProviderType, Func<object, object?> getMethodReturnType, Func<object, object?> getReturnType, Action<object, object> setReturnType, Func<object, object?> getModule, Func<object, Type, object?> importType, Func<object, object?> getElementType, Func<object, object?> getModifierType, Func<object, string?> getFullName, Func<object, object, object> createRequiredModifier, Func<object, object, object> createOptionalModifier)
			{
				GenericParameterProviderType = genericParameterProviderType;
				GetMethodReturnType = getMethodReturnType;
				GetReturnType = getReturnType;
				SetReturnType = setReturnType;
				GetModule = getModule;
				ImportType = importType;
				GetElementType = getElementType;
				GetModifierType = getModifierType;
				GetFullName = getFullName;
				CreateRequiredModifier = createRequiredModifier;
				CreateOptionalModifier = createOptionalModifier;
			}

			public static ImporterAccess? TryCreate(Assembly harmonyAssembly, out string error)
			{
				error = "";
				try
				{
					Type type = RequiredType(harmonyAssembly, "Mono.Cecil.ModuleDefinition");
					Type genericParameterProviderType = RequiredType(harmonyAssembly, "Mono.Cecil.IGenericParameterProvider");
					Type type2 = RequiredType(harmonyAssembly, "Mono.Cecil.MethodReference");
					Type type3 = RequiredType(harmonyAssembly, "Mono.Cecil.MethodReturnType");
					Type type4 = RequiredType(harmonyAssembly, "Mono.Cecil.TypeReference");
					Type type5 = RequiredType(harmonyAssembly, "Mono.Cecil.TypeSpecification");
					Type type6 = RequiredType(harmonyAssembly, "Mono.Cecil.RequiredModifierType");
					Type type7 = RequiredType(harmonyAssembly, "Mono.Cecil.OptionalModifierType");
					Type type8 = RequiredType(harmonyAssembly, "Mono.Cecil.IModifierType");
					Func<object, object> getMethodReturnType = CompileGetter<object>(RequiredProperty(type2, "MethodReturnType"));
					Func<object, object> getReturnType = CompileGetter<object>(RequiredProperty(type3, "ReturnType"));
					Action<object, object> setReturnType = CompileSetter(RequiredProperty(type3, "ReturnType"));
					Func<object, object> getModule = CompileGetter<object>(RequiredProperty(type2, "Module"));
					Func<object, Type, object> importType = CompileTypeInstanceMethod<object>(RequiredMethod(type, "ImportReference", BindingFlags.Instance | BindingFlags.Public, new Type[1] { typeof(Type) }), type, new Type[1] { typeof(Type) }, new object[1] { typeof(Type) });
					Func<object, object> getElementType = CompileGetter<object>(RequiredProperty(type5, "ElementType"));
					Func<object, object> getModifierType = CompileGetter<object>(RequiredProperty(type8, "ModifierType"));
					Func<object, string> getFullName = CompileGetter<string>(RequiredProperty(type4, "FullName"));
					Func<object, object, object> createRequiredModifier = CompileTwoArgConstructor(RequiredConstructor(type6, new Type[2] { type4, type4 }), type4, type4);
					Func<object, object, object> createOptionalModifier = CompileTwoArgConstructor(RequiredConstructor(type7, new Type[2] { type4, type4 }), type4, type4);
					return new ImporterAccess(genericParameterProviderType, getMethodReturnType, getReturnType, setReturnType, getModule, importType, getElementType, getModifierType, getFullName, createRequiredModifier, createOptionalModifier);
				}
				catch (Exception ex)
				{
					error = ex.GetBaseException().Message;
					return null;
				}
			}

			private static Type RequiredType(Assembly assembly, string fullName)
			{
				string text = (fullName.StartsWith("Mono.Cecil.", StringComparison.Ordinal) ? "Mono.Cecil" : assembly.GetName().Name);
				return ResolveType(assembly, text, fullName) ?? throw new TypeLoadException($"{fullName} not found in {assembly.GetName().Name} or {text}.");
			}

			private static PropertyInfo RequiredProperty(Type type, string name)
			{
				return type.GetProperty(name, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic) ?? throw new MissingMemberException(type.FullName, name);
			}

			private static MethodInfo RequiredMethod(Type type, string name, BindingFlags flags, Type[] parameters)
			{
				return type.GetMethod(name, flags, null, parameters, null) ?? throw new MissingMethodException(type.FullName, name);
			}

			private static ConstructorInfo RequiredConstructor(Type type, Type[] parameters)
			{
				return type.GetConstructor(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, parameters, null) ?? throw new MissingMethodException(type.FullName, ".ctor");
			}

			private static Func<object, TResult> CompileGetter<TResult>(PropertyInfo property)
			{
				ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "instance");
				return Expression.Lambda<Func<object, TResult>>(Expression.Convert(Expression.Property(Expression.Convert(parameterExpression, property.DeclaringType), property), typeof(TResult)), new ParameterExpression[1] { parameterExpression }).Compile();
			}

			private static Action<object, object> CompileSetter(PropertyInfo property)
			{
				ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "instance");
				ParameterExpression parameterExpression2 = Expression.Parameter(typeof(object), "value");
				return Expression.Lambda<Action<object, object>>(Expression.Assign(Expression.Property(Expression.Convert(parameterExpression, property.DeclaringType), property), Expression.Convert(parameterExpression2, property.PropertyType)), new ParameterExpression[2] { parameterExpression, parameterExpression2 }).Compile();
			}

			private static Func<object, object> CompileOneArgConstructor(ConstructorInfo constructor, Type parameterType)
			{
				ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "arg");
				return Expression.Lambda<Func<object, object>>(Expression.Convert(Expression.New(constructor, Expression.Convert(parameterExpression, parameterType)), typeof(object)), new ParameterExpression[1] { parameterExpression }).Compile();
			}

			private static Func<object, object, object> CompileTwoArgConstructor(ConstructorInfo constructor, Type firstParameterType, Type secondParameterType)
			{
				ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "first");
				ParameterExpression parameterExpression2 = Expression.Parameter(typeof(object), "second");
				return Expression.Lambda<Func<object, object, object>>(Expression.Convert(Expression.New(constructor, Expression.Convert(parameterExpression, firstParameterType), Expression.Convert(parameterExpression2, secondParameterType)), typeof(object)), new ParameterExpression[2] { parameterExpression, parameterExpression2 }).Compile();
			}

			private static Func<object, Type, object?> CompileTypeInstanceMethod<TResult>(MethodInfo method, Type instanceType, Type[] parameterTypes, object?[] fixedArguments)
			{
				ParameterExpression parameterExpression = Expression.Parameter(typeof(object), "instance");
				ParameterExpression type = Expression.Parameter(typeof(Type), "type");
				IEnumerable<Expression> arguments = parameterTypes.Select((Type parameterType) => (!(parameterType == typeof(Type))) ? ((Expression)Expression.Constant(null, parameterType)) : ((Expression)Expression.Convert(type, parameterType)));
				return Expression.Lambda<Func<object, Type, object>>(Expression.Convert(Expression.Call(Expression.Convert(parameterExpression, instanceType), method, arguments), typeof(TResult)), new ParameterExpression[2] { parameterExpression, type }).Compile();
			}
		}

		private const string IsExternalInitFullName = "System.Runtime.CompilerServices.IsExternalInit";

		private const string HarmonyId = "com.ritsukage.sts2-RitsuLib.harmony-init-setter-compat";

		private static bool _installed;

		private static bool _reportedPostfixFailure;

		private static ImporterAccess? _access;

		public static void Install()
		{
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			//IL_0019: Expected O, but got Unknown
			if (_installed)
			{
				return;
			}
			_installed = true;
			try
			{
				Harmony harmony = new Harmony("com.ritsukage.sts2-RitsuLib.harmony-init-setter-compat");
				Assembly assembly = typeof(Harmony).Assembly;
				_access = ImporterAccess.TryCreate(assembly, out string error);
				if (_access == null)
				{
					RitsuLibFramework.Logger.Warn("[HarmonyInitSetterCompat] Reflection importer accessors unavailable: " + error, 1);
					return;
				}
				int num = 0;
				num += TryPatchImporter(harmony, _access, ResolveType(assembly, "MonoMod.Utils", "MonoMod.Utils.MMReflectionImporter"), "MonoMod.Utils.MMReflectionImporter");
				num += TryPatchImporter(harmony, _access, ResolveType(assembly, "Mono.Cecil", "Mono.Cecil.DefaultReflectionImporter"), "Mono.Cecil.DefaultReflectionImporter");
				if (num == 0)
				{
					RitsuLibFramework.Logger.Warn("[HarmonyInitSetterCompat] No reflection importer entry points were patched.", 1);
					return;
				}
				RitsuLibFramework.Logger.Info($"[HarmonyInitSetterCompat] Installed on {num} reflection importer entry point(s).", 1);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[HarmonyInitSetterCompat] Install failed; continuing without init-setter import compat: " + ex.Message, 1);
			}
		}

		private static int TryPatchImporter(Harmony harmony, ImporterAccess access, Type? importerType, string displayName)
		{
			//IL_008b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0097: Expected O, but got Unknown
			if (importerType == null)
			{
				RitsuLibFramework.Logger.Warn("[HarmonyInitSetterCompat] " + displayName + " not found.", 1);
				return 0;
			}
			MethodInfo method = importerType.GetMethod("ImportReference", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, new Type[2]
			{
				typeof(MethodBase),
				access.GenericParameterProviderType
			}, null);
			if (method == null)
			{
				RitsuLibFramework.Logger.Warn("[HarmonyInitSetterCompat] " + displayName + ".ImportReference(MethodBase, IGenericParameterProvider) not found.", 1);
				return 0;
			}
			harmony.Patch((MethodBase)method, (HarmonyMethod)null, new HarmonyMethod(typeof(HarmonyInitSetterCompat), "ImportReferencePostfix", (Type[])null), (HarmonyMethod)null, (HarmonyMethod)null);
			return 1;
		}

		private static void ImportReferencePostfix(MethodBase method, object __result)
		{
			if (__result == null || !(method is MethodInfo methodInfo))
			{
				return;
			}
			Type[] requiredCustomModifiers = methodInfo.ReturnParameter.GetRequiredCustomModifiers();
			if (requiredCustomModifiers.Length == 0)
			{
				return;
			}
			Type[] optionalCustomModifiers = methodInfo.ReturnParameter.GetOptionalCustomModifiers();
			try
			{
				PreserveReturnModifiers(__result, requiredCustomModifiers, optionalCustomModifiers);
			}
			catch (Exception ex)
			{
				if (!_reportedPostfixFailure)
				{
					_reportedPostfixFailure = true;
					RitsuLibFramework.Logger.Warn("[HarmonyInitSetterCompat] ImportReference postfix failed; continuing without preserving return modifiers for this import: " + ex.GetBaseException().Message, 1);
				}
			}
		}

		private static void PreserveReturnModifiers(object methodReference, IReadOnlyList<Type> requiredModifiers, IReadOnlyList<Type> optionalModifiers)
		{
			ImporterAccess access = _access;
			if (access == null)
			{
				return;
			}
			object obj = access.GetMethodReturnType(methodReference);
			if (obj == null)
			{
				return;
			}
			object obj2 = access.GetReturnType(obj);
			if (obj2 == null)
			{
				return;
			}
			foreach (Type item in optionalModifiers.Reverse())
			{
				if (!HasModifier(access, obj2, item.FullName, required: false) && TryImportModifier(methodReference, item, out object modifierType))
				{
					obj2 = access.CreateOptionalModifier(modifierType, obj2);
				}
			}
			foreach (Type item2 in requiredModifiers.Reverse())
			{
				if (!HasModifier(access, obj2, item2.FullName, required: true) && TryImportModifier(methodReference, item2, out object modifierType2))
				{
					obj2 = access.CreateRequiredModifier(modifierType2, obj2);
				}
			}
			access.SetReturnType(obj, obj2);
		}

		private static bool TryImportModifier(object methodReference, Type modifier, out object modifierType)
		{
			modifierType = null;
			try
			{
				ImporterAccess access = _access;
				object obj = access?.GetModule(methodReference);
				modifierType = ((obj == null) ? null : access.ImportType(obj, modifier));
				return modifierType != null;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[HarmonyInitSetterCompat] Could not import return modifier " + modifier.FullName + ": " + ex.Message, 1);
				return false;
			}
		}

		private static bool HasModifier(ImporterAccess access, object type, string modifierFullName, bool required)
		{
			for (object obj = type; obj != null; obj = access.GetElementType(obj))
			{
				string fullName = obj.GetType().FullName;
				if (!(fullName == "Mono.Cecil.RequiredModifierType"))
				{
					if (!(fullName == "Mono.Cecil.OptionalModifierType"))
					{
						return false;
					}
					if (!required && GetModifierFullName(obj) == modifierFullName)
					{
						return true;
					}
				}
				else if (required && GetModifierFullName(obj) == modifierFullName)
				{
					return true;
				}
			}
			return false;
			string? GetModifierFullName(object modifierType)
			{
				object obj2 = access.GetModifierType(modifierType);
				if (obj2 == null)
				{
					return null;
				}
				return access.GetFullName(obj2);
			}
		}

		private static Type? ResolveType(Assembly fallbackAssembly, string assemblyName, string fullName)
		{
			Type type = fallbackAssembly.GetType(fullName, throwOnError: false);
			if (type != null)
			{
				return type;
			}
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly assembly in assemblies)
			{
				if (string.Equals(assembly.GetName().Name, assemblyName, StringComparison.OrdinalIgnoreCase))
				{
					type = assembly.GetType(fullName, throwOnError: false);
					if (type != null)
					{
						return type;
					}
				}
			}
			type = Type.GetType(fullName + ", " + assemblyName, throwOnError: false);
			if (type != null)
			{
				return type;
			}
			try
			{
				return Assembly.Load(new AssemblyName(assemblyName)).GetType(fullName, throwOnError: false);
			}
			catch
			{
				return null;
			}
		}
	}
	internal static class HarmonyPatchAllTypeLoadGuard
	{
		private const string HarmonyId = "OLC.STS2-RitsuLib.HarmonyPatchAllTypeLoadGuard";

		private static readonly Lock InstallLock = new Lock();

		private static readonly Lock WarnedTypesLock = new Lock();

		private static readonly HashSet<string> WarnedTypes = new HashSet<string>();

		private static Action<string>? _warn;

		private static bool _installed;

		public static void Install(Action<string>? warn = null)
		{
			//IL_00c8: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d2: Unknown result type (might be due to invalid IL or missing references)
			//IL_00dc: Expected O, but got Unknown
			using (InstallLock.EnterScope())
			{
				if (_installed)
				{
					return;
				}
				if (_warn == null)
				{
					_warn = warn;
				}
				try
				{
					MethodInfo methodInfo = AccessTools.Method(typeof(HarmonyMethodExtensions), "GetFromType", new Type[1] { typeof(Type) }, (Type[])null);
					if (methodInfo == null)
					{
						Warn("Cannot install Harmony PatchAll type-load guard: GetFromType(Type) was not found.");
						_installed = true;
						return;
					}
					Patches patchInfo = Harmony.GetPatchInfo((MethodBase)methodInfo);
					if (patchInfo != null && patchInfo.Finalizers.Any((Patch patch) => patch.owner == "OLC.STS2-RitsuLib.HarmonyPatchAllTypeLoadGuard"))
					{
						_installed = true;
						return;
					}
					MethodInfo methodInfo2 = AccessTools.Method(typeof(HarmonyPatchAllTypeLoadGuard), "Finalizer", (Type[])null, (Type[])null);
					new Harmony("OLC.STS2-RitsuLib.HarmonyPatchAllTypeLoadGuard").Patch((MethodBase)methodInfo, (HarmonyMethod)null, (HarmonyMethod)null, (HarmonyMethod)null, new HarmonyMethod(methodInfo2));
					_installed = true;
				}
				catch (Exception ex)
				{
					Warn("Cannot install Harmony PatchAll type-load guard; incompatible patch attributes may still abort PatchAll: " + ex.Message);
					_installed = true;
				}
			}
		}

		private static Exception? Finalizer(Type type, Exception? __exception, ref List<HarmonyMethod> __result)
		{
			if (__exception == null)
			{
				return null;
			}
			Exception ex = Unwrap(__exception);
			if (!(ex is TypeLoadException))
			{
				return __exception;
			}
			__result = new List<HarmonyMethod>();
			WarnOnce(type, ex);
			return null;
		}

		private static Exception Unwrap(Exception exception)
		{
			while ((exception is TargetInvocationException || exception is TypeInitializationException) ? true : false)
			{
				Exception innerException = exception.InnerException;
				if (innerException == null)
				{
					break;
				}
				exception = innerException;
			}
			return exception;
		}

		private static void WarnOnce(Type type, Exception exception)
		{
			string item = type.AssemblyQualifiedName ?? type.FullName ?? type.Name;
			using (WarnedTypesLock.EnterScope())
			{
				if (!WarnedTypes.Add(item))
				{
					return;
				}
			}
			Warn("Skipping Harmony patch type with unloadable attribute target: " + $"{type.FullName} ({exception.GetType().Name}: {exception.Message})");
		}

		private static void Warn(string message)
		{
			(_warn ?? (_warn = Console.Error.WriteLine))("[RitsuLib.HarmonyPatchAllTypeLoadGuard] " + message);
		}
	}
}
namespace STS2RitsuLib.Patching.Builders
{
	/// <summary>
	///     <para xml:lang="en">Provides a fluent builder for Harmony patches whose targets are resolved at runtime.</para>
	///     <para xml:lang="zh-CN">提供流式构建器，用于创建在运行时解析目标的 Harmony 补丁。</para>
	/// </summary>
	/// <param name="idPrefix">
	///     <para xml:lang="en">Prefix used for generated patch IDs when an overload receives no <c>patchId</c>.</para>
	///     <para xml:lang="zh-CN">重载未收到 <c>patchId</c> 时，用于生成补丁 ID 的前缀。</para>
	/// </param>
	public sealed class DynamicPatchBuilder(string idPrefix)
	{
		private readonly List<DynamicPatchInfo> _patches = new List<DynamicPatchInfo>();

		private int _counter;

		/// <summary>
		///     <para xml:lang="en">Gets the prefix used for generated patch IDs.</para>
		///     <para xml:lang="zh-CN">获取用于生成补丁 ID 的前缀。</para>
		/// </summary>
		public string IdPrefix { get; } = idPrefix;

		/// <summary>
		///     <para xml:lang="en">Gets the patches accumulated by this builder. They are not applied automatically.</para>
		///     <para xml:lang="zh-CN">获取此构建器已收集的补丁。这些补丁不会自动应用。</para>
		/// </summary>
		public IReadOnlyList<DynamicPatchInfo> Patches => _patches;

		/// <summary>
		///     <para xml:lang="en">Adds a patch for <paramref name="originalMethod" />.</para>
		///     <para xml:lang="zh-CN">添加以 <paramref name="originalMethod" /> 为目标的补丁。</para>
		/// </summary>
		public DynamicPatchBuilder Add(MethodBase originalMethod, HarmonyMethod? prefix = null, HarmonyMethod? postfix = null, HarmonyMethod? transpiler = null, HarmonyMethod? finalizer = null, bool isCritical = true, string? description = null, string? patchId = null)
		{
			ArgumentNullException.ThrowIfNull(originalMethod, "originalMethod");
			string id = patchId ?? $"{IdPrefix}_{++_counter:D3}_{originalMethod.DeclaringType?.Name}_{originalMethod.Name}";
			_patches.Add(new DynamicPatchInfo(id, originalMethod, prefix, postfix, transpiler, finalizer, isCritical, description));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Resolves <paramref name="target" /> and adds a patch for the resulting method.</para>
		///     <para xml:lang="zh-CN">解析 <paramref name="target" />，并为解析得到的方法添加补丁。</para>
		/// </summary>
		public DynamicPatchBuilder Add(ModPatchTarget target, HarmonyMethod? prefix = null, HarmonyMethod? postfix = null, HarmonyMethod? transpiler = null, HarmonyMethod? finalizer = null, bool isCritical = true, string? description = null, string? patchId = null)
		{
			ArgumentNullException.ThrowIfNull(target, "target");
			MethodBase originalMethod = PatchTargetMethodResolver.ResolveRequired(target);
			string id = patchId ?? $"{IdPrefix}_{++_counter:D3}_{target.TargetType.Name}_{target.MethodName}";
			_patches.Add(new DynamicPatchInfo(id, originalMethod, prefix, postfix, transpiler, finalizer, isCritical, description ?? $"Patch {target}"));
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Resolves a property getter on <paramref name="targetType" /> and adds a patch for it.</para>
		///     <para xml:lang="zh-CN">解析 <paramref name="targetType" /> 上的属性 getter，并为其添加补丁。</para>
		/// </summary>
		public DynamicPatchBuilder AddPropertyGetter(Type targetType, string propertyName, HarmonyMethod? prefix = null, HarmonyMethod? postfix = null, HarmonyMethod? transpiler = null, HarmonyMethod? finalizer = null, bool isCritical = true, string? description = null, string? patchId = null)
		{
			ArgumentNullException.ThrowIfNull(targetType, "targetType");
			ArgumentException.ThrowIfNullOrWhiteSpace(propertyName, "propertyName");
			MethodInfo originalMethod = FindDeclaredPropertyGetter(targetType, propertyName) ?? throw new MissingMethodException(targetType.FullName, "get_" + propertyName);
			return Add(originalMethod, prefix, postfix, transpiler, finalizer, isCritical, description ?? ("Patch property getter " + targetType.Name + "." + propertyName), patchId);
		}

		/// <summary>
		///     <para xml:lang="en">Resolves a normal method on <paramref name="targetType" /> and adds a patch for it.</para>
		///     <para xml:lang="zh-CN">解析 <paramref name="targetType" /> 上的普通方法，并为其添加补丁。</para>
		/// </summary>
		public DynamicPatchBuilder AddMethod(Type targetType, string methodName, Type[]? parameterTypes = null, HarmonyMethod? prefix = null, HarmonyMethod? postfix = null, HarmonyMethod? transpiler = null, HarmonyMethod? finalizer = null, bool isCritical = true, string? description = null, string? patchId = null)
		{
			return AddMethod(targetType, methodName, parameterTypes, prefix, postfix, transpiler, finalizer, isCritical, description, patchId, (MethodType)0);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves a method on <paramref name="targetType" /> using <paramref name="parameterTypes" /> and
		///         <paramref name="harmonyMethodType" />, then adds a patch for it.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用 <paramref name="parameterTypes" /> 和 <paramref name="harmonyMethodType" /> 解析
		///         <paramref name="targetType" /> 上的方法，并为其添加补丁。
		///     </para>
		/// </summary>
		public DynamicPatchBuilder AddMethod(Type targetType, string methodName, Type[]? parameterTypes, HarmonyMethod? prefix, HarmonyMethod? postfix, HarmonyMethod? transpiler, HarmonyMethod? finalizer, bool isCritical, string? description, string? patchId, MethodType harmonyMethodType)
		{
			//IL_0019: Unknown result type (might be due to invalid IL or missing references)
			//IL_004f: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(targetType, "targetType");
			ArgumentException.ThrowIfNullOrWhiteSpace(methodName, "methodName");
			MethodBase methodBase = PatchTargetMethodResolver.Resolve(targetType, methodName, parameterTypes, harmonyMethodType);
			if (methodBase == null)
			{
				throw new MissingMethodException(targetType.FullName, $"{methodName} ({harmonyMethodType})");
			}
			return Add(methodBase, prefix, postfix, transpiler, finalizer, isCritical, description ?? ("Patch method " + targetType.Name + "." + methodName), patchId);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to resolve and add a method patch. Returns <see langword="false" /> without modifying the builder
		///         when the target type is <see langword="null" /> or the method cannot be resolved.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试解析并添加方法补丁。目标类型为 <see langword="null" /> 或无法解析方法时返回
		///         <see langword="false" />，且不修改构建器。
		///     </para>
		/// </summary>
		public bool TryAddMethod(Type? targetType, string methodName, Type[]? parameterTypes = null, HarmonyMethod? prefix = null, HarmonyMethod? postfix = null, HarmonyMethod? transpiler = null, HarmonyMethod? finalizer = null, bool isCritical = false, string? description = null, string? patchId = null, MethodType harmonyMethodType = (MethodType)0)
		{
			//IL_0019: Unknown result type (might be due to invalid IL or missing references)
			ArgumentException.ThrowIfNullOrWhiteSpace(methodName, "methodName");
			if (targetType == null)
			{
				return false;
			}
			MethodBase methodBase = PatchTargetMethodResolver.Resolve(targetType, methodName, parameterTypes, harmonyMethodType);
			if (methodBase == null)
			{
				return false;
			}
			Add(methodBase, prefix, postfix, transpiler, finalizer, isCritical, description ?? ("Patch method " + targetType.Name + "." + methodName), patchId);
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves <paramref name="targetTypeName" /> with <see cref="M:HarmonyLib.AccessTools.TypeByName(System.String)" /> and attempts to
		///         add a method patch. Returns <see langword="false" /> when the type or method cannot be resolved.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用 <see cref="M:HarmonyLib.AccessTools.TypeByName(System.String)" /> 解析 <paramref name="targetTypeName" /> 并尝试添加方法补丁。
		///         无法解析类型或方法时返回 <see langword="false" />。
		///     </para>
		/// </summary>
		public bool TryAddMethodByName(string targetTypeName, string methodName, Type[]? parameterTypes = null, HarmonyMethod? prefix = null, HarmonyMethod? postfix = null, HarmonyMethod? transpiler = null, HarmonyMethod? finalizer = null, bool isCritical = false, string? description = null, string? patchId = null, MethodType harmonyMethodType = (MethodType)0)
		{
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			ArgumentException.ThrowIfNullOrWhiteSpace(targetTypeName, "targetTypeName");
			return TryAddMethod(AccessTools.TypeByName(targetTypeName), methodName, parameterTypes, prefix, postfix, transpiler, finalizer, isCritical, description, patchId, harmonyMethodType);
		}

		/// <summary>
		///     <para xml:lang="en">Wraps a static patch method on <paramref name="patchType" /> in a <see cref="T:HarmonyLib.HarmonyMethod" />.</para>
		///     <para xml:lang="zh-CN">将 <paramref name="patchType" /> 上的静态补丁方法包装为 <see cref="T:HarmonyLib.HarmonyMethod" />。</para>
		/// </summary>
		public static HarmonyMethod FromMethod(Type patchType, string methodName)
		{
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			//IL_0036: Expected O, but got Unknown
			ArgumentNullException.ThrowIfNull(patchType, "patchType");
			ArgumentException.ThrowIfNullOrWhiteSpace(methodName, "methodName");
			return new HarmonyMethod(patchType.GetMethod(methodName, BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic) ?? throw new MissingMethodException(patchType.FullName, methodName));
		}

		private static MethodInfo? FindDeclaredPropertyGetter(Type targetType, string propertyName)
		{
			Type type = targetType;
			while (type != null)
			{
				MethodInfo methodInfo = type.GetProperty(propertyName, BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic)?.GetMethod;
				if ((object)methodInfo != null && !methodInfo.IsAbstract)
				{
					return methodInfo;
				}
				type = type.BaseType;
			}
			return null;
		}
	}
