namespace STS2RitsuLib.Networking
{
	internal static class ContentModInventoryPayloadCodec
	{
		internal sealed record CompactEntry(string Id, string Version, string Name, string Source, ulong? WorkshopItemId, int Flags);

		private const int MaxPayloadBytes = 4194304;

		private const int MaxEncodedPayloadChars = 5592408;

		private static readonly JsonSerializerOptions JsonOptions = new JsonSerializerOptions
		{
			DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingDefault,
			PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
			WriteIndented = false
		};

		internal static string Encode(IReadOnlyList<ContentModInventoryEntry> entries)
		{
			string s = JsonSerializer.Serialize(Compact(entries), JsonOptions);
			return Convert.ToBase64String(Gzip(Encoding.UTF8.GetBytes(s)));
		}

		internal static IReadOnlyList<CompactEntry> Compact(IReadOnlyList<ContentModInventoryEntry> entries)
		{
			List<CompactEntry> list = new List<CompactEntry>();
			list.AddRange(entries.Select((ContentModInventoryEntry entry) => new CompactEntry(entry.Id, entry.Version, entry.Name, entry.Source, entry.WorkshopItemId, BuildFlags(entry))));
			return new <>z__ReadOnlyList<CompactEntry>(list);
		}

		internal static IReadOnlyList<ContentModInventoryEntry> Expand(IReadOnlyList<CompactEntry> compact)
		{
			List<ContentModInventoryEntry> list = new List<ContentModInventoryEntry>();
			list.AddRange(compact.Select((CompactEntry entry, int index) => new ContentModInventoryEntry(index, entry.Id, entry.Version, entry.Name, entry.Source, entry.WorkshopItemId, (entry.Flags & 1) != 0, (entry.Flags & 2) != 0, (entry.Flags & 4) != 0)));
			return new <>z__ReadOnlyList<ContentModInventoryEntry>(list);
		}

		internal static bool TryDecode(string? encoded, out IReadOnlyList<ContentModInventoryEntry> entries)
		{
			entries = Array.Empty<ContentModInventoryEntry>();
			if (string.IsNullOrWhiteSpace(encoded))
			{
				return false;
			}
			try
			{
				int num = 0;
				for (int i = 0; i < encoded.Length; i++)
				{
					if (!char.IsWhiteSpace(encoded[i]) && ++num > 5592408)
					{
						throw new InvalidDataException($"Encoded content mod inventory exceeds {4194304} compressed bytes.");
					}
				}
				CompactEntry[] array = JsonSerializer.Deserialize<CompactEntry[]>(Encoding.UTF8.GetString(Gunzip(Convert.FromBase64String(encoded))), JsonOptions);
				if (array == null)
				{
					return false;
				}
				entries = Expand(array);
				return true;
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[ContentModInventoryPayload] Failed to decode payload: " + ex.Message, 1);
				return false;
			}
		}

		private static int BuildFlags(ContentModInventoryEntry entry)
		{
			int num = 0;
			if (entry.IsEnabled)
			{
				num |= 1;
			}
			if (entry.AffectsGameplay)
			{
				num |= 2;
			}
			if (entry.IsDependency)
			{
				num |= 4;
			}
			return num;
		}

		private static byte[] Gzip(byte[] data)
		{
			EnsurePayloadLength(data.Length, "uncompressed");
			byte[] array = RitsuLibSidecarCompression.GzipCompress(data);
			EnsurePayloadLength(array.Length, "compressed");
			return array;
		}

		private static byte[] Gunzip(ReadOnlySpan<byte> data)
		{
			if (RitsuLibSidecarCompression.TryGunzip(data, out byte[] decompressed))
			{
				return decompressed;
			}
			throw new InvalidDataException($"Content mod inventory gzip data is invalid or exceeds {4194304} decompressed bytes.");
		}

		private static void EnsurePayloadLength(int length, string kind)
		{
			if (length > 4194304)
			{
				throw new InvalidDataException($"Content mod inventory {kind} payload exceeds {4194304} bytes.");
			}
		}
	}
	internal static class DiagnosticPopupDetailsButton
	{
		private const string AttachedMeta = "ritsu_diagnostics_details_button_attached";

		public static void Add(NErrorPopup popup, string text, Action open)
		{
			//IL_0063: Unknown result type (might be due to invalid IL or missing references)
			//IL_0079: Unknown result type (might be due to invalid IL or missing references)
			//IL_007e: Unknown result type (might be due to invalid IL or missing references)
			NVerticalPopup verticalPopup = ((Node)popup).GetNodeOrNull<NVerticalPopup>(NodePath.op_Implicit("VerticalPopup"));
			if (verticalPopup == null || ((GodotObject)popup).HasMeta(StringName.op_Implicit("ritsu_diagnostics_details_button_attached")) || ((CanvasItem)verticalPopup.NoButton).Visible)
