		private static List<StateDivergenceDiagnosticSection> BuildSections(StateDivergenceTrackedState local, StateDivergenceTrackedState remote, ulong remotePeerId, string role, StateDivergenceSupplementPayload localSupplement, StateDivergenceSupplementPayload? remoteSupplement, IReadOnlyList<ContentModInventoryEntry> localLoadedMods, IReadOnlyList<ContentModInventoryEntry> remoteLoadedMods, bool hasLocalLoadedMods, bool hasRemoteLoadedMods, bool includeMatching)
