		private static StateDivergenceDiagnosticSection BuildProtocolMaps(StateDivergenceSupplementPayload local, StateDivergenceSupplementPayload? remote, bool includeMatching)
		{
			List<StateDivergenceDiagnosticRow> list = new List<StateDivergenceDiagnosticRow>();
			if (remote == null)
			{
				list.Add(new StateDivergenceDiagnosticRow("savedProperties.supplement", L("value.present", "Present"), L("value.missing", "Missing"), L("detail.missingSupplement", "The remote peer did not include a RitsuLib state-divergence supplement payload.")));
