			else
			{
				AddOptionalSortMode(list, "modelDb.deterministicSort", local.ModelDbHashUsesDeterministicCache, remote.ModelDbHashUsesDeterministicCache, includeMatching);
				AddOptionalSortMode(list, "savedProperties.deterministicSort", local.SavedPropertyNetIdUsesDeterministicSort, remote.SavedPropertyNetIdUsesDeterministicSort, includeMatching);
				AddIfDifferent(list, "savedProperties.netIdBitSize", local.SavedPropertyNetIdBitSize, remote.SavedPropertyNetIdBitSize, includeMatching);
				AddIfDifferent(list, "savedProperties.count", local.SavedPropertyNames.Count, remote.SavedPropertyNames.Count, includeMatching);
