		private static StateDivergenceDiagnosticSection BuildLoadedMods(IReadOnlyList<ContentModInventoryEntry> local, IReadOnlyList<ContentModInventoryEntry> remote, bool hasLocal, bool hasRemote, bool includeMatching)
		{
			List<StateDivergenceDiagnosticRow> list = new List<StateDivergenceDiagnosticRow>();
			if (hasRemote)
			{
				AddIfDifferent(list, "loadedMods.count", local.Count, remote.Count, includeMatching);
				AddLoadedModSetRows(list, local, remote);
				AddLoadedModVersionRows(list, local, remote, includeMatching);
				AddLoadedModOrderRows(list, local, remote, includeMatching);
			}
			else
			{
				list.Add(new StateDivergenceDiagnosticRow("loadedMods.supplement", hasLocal ? L("value.present", "Present") : L("value.missing", "Missing"), L("value.missing", "Missing"), L("detail.missingLoadedModInventory", "The remote peer did not include the full loaded-mod inventory added by this RitsuLib version.")));
			}
			if (includeMatching)
			{
				list.Add(new StateDivergenceDiagnosticRow("loadedMods.fullList", FormatLoadedModInventory(local, hasLocal), FormatLoadedModInventory(remote, hasRemote), L("detail.loadedModsFullList", "Complete mod inventory in the game's current runtime load order.")));
			}
			return new StateDivergenceDiagnosticSection(L("section.loadedMods.title", "Loaded mods"), L("section.loadedMods.description", "Complete runtime mod inventory, plus set, version, source, and load-order differences."), StartsCollapsed: true, list, ContributesToIssueCount: false);
		}

		private static void AddLoadedModSetRows(ICollection<StateDivergenceDiagnosticRow> rows, IReadOnlyList<ContentModInventoryEntry> local, IReadOnlyList<ContentModInventoryEntry> remote)
		{
			IReadOnlyDictionary<string, ContentModInventoryEntry> remoteByKey = BuildLoadedModIdentityMap(remote);
			IReadOnlyDictionary<string, ContentModInventoryEntry> localByKey = BuildLoadedModIdentityMap(local);
			string[] array = local.Where((ContentModInventoryEntry mod) => !remoteByKey.ContainsKey(LoadedModIdentityKey(mod))).Select(FormatLoadedModLine).ToArray();
			string[] array2 = remote.Where((ContentModInventoryEntry mod) => !localByKey.ContainsKey(LoadedModIdentityKey(mod))).Select(FormatLoadedModLine).ToArray();
			if (array.Length != 0 || array2.Length != 0)
			{
				rows.Add(new StateDivergenceDiagnosticRow("loadedMods.set", JoinLinesOrNone(array), JoinLinesOrNone(array2), L("detail.loadedModSetMismatch", "Entries shown in this row are present only on that side, compared by mod id and source.")));
			}
		}

		private static void AddLoadedModVersionRows(ICollection<StateDivergenceDiagnosticRow> rows, IReadOnlyList<ContentModInventoryEntry> local, IReadOnlyList<ContentModInventoryEntry> remote, bool includeMatching)
		{
			IReadOnlyDictionary<string, ContentModInventoryEntry> readOnlyDictionary = BuildLoadedModIdentityMap(remote);
			foreach (ContentModInventoryEntry item in local)
			{
				if (readOnlyDictionary.TryGetValue(LoadedModIdentityKey(item), out var value))
				{
					string text = "loadedMods." + FormatLoadedModPath(item);
					AddIfDifferent(rows, text + ".version", FormatVersion(item.Version), FormatVersion(value.Version), includeMatching);
					AddIfDifferent(rows, text + ".name", item.Name, value.Name, includeMatching);
					AddIfDifferent(rows, text + ".workshopItemId", FormatWorkshopItemId(item.WorkshopItemId), FormatWorkshopItemId(value.WorkshopItemId), includeMatching);
					AddIfDifferent(rows, text + ".affectsGameplay", item.AffectsGameplay, value.AffectsGameplay, includeMatching);
				}
			}
		}

		private static void AddLoadedModOrderRows(ICollection<StateDivergenceDiagnosticRow> rows, IReadOnlyList<ContentModInventoryEntry> local, IReadOnlyList<ContentModInventoryEntry> remote, bool includeMatching)
		{
			string[] array = local.Select(LoadedModIdentityKey).ToArray();
			string[] array2 = remote.Select(LoadedModIdentityKey).ToArray();
			if (array.Length != array2.Length || !array.OrderBy<string, string>((string key) => key, StringComparer.Ordinal).SequenceEqual<string>(array2.OrderBy<string, string>((string key) => key, StringComparer.Ordinal), StringComparer.Ordinal))
			{
				return;
			}
			int num = -1;
			int num2 = 0;
			for (int num3 = 0; num3 < array.Length; num3++)
			{
				if (!string.Equals(array[num3], array2[num3], StringComparison.Ordinal))
				{
					if (num < 0)
					{
						num = num3;
					}
					num2++;
				}
			}
			if (includeMatching || num2 != 0)
			{
				string detail = ((num2 == 0) ? L("detail.loadedModOrderMatches", "Both sides report the same loaded-mod order.") : F("detail.loadedModOrderMismatch", "{0} loaded-mod position(s) differ; first mismatch at #{1}.", num2, num + 1));
				rows.Add(new StateDivergenceDiagnosticRow("loadedMods.order", FormatLoadedModOrder(local), FormatLoadedModOrder(remote), detail));
			}
		}

		private static IReadOnlyDictionary<string, ContentModInventoryEntry> BuildLoadedModIdentityMap(IEnumerable<ContentModInventoryEntry> mods)
		{
			return mods.GroupBy<ContentModInventoryEntry, string>(LoadedModIdentityKey, StringComparer.Ordinal).ToDictionary<IGrouping<string, ContentModInventoryEntry>, string, ContentModInventoryEntry>((IGrouping<string, ContentModInventoryEntry> group) => group.Key, (IGrouping<string, ContentModInventoryEntry> group) => group.First(), StringComparer.Ordinal);
		}

		private static string LoadedModIdentityKey(ContentModInventoryEntry mod)
		{
			return mod.Source + "\0" + mod.Id;
		}

		private static string FormatLoadedModInventory(IReadOnlyList<ContentModInventoryEntry> mods, bool available)
		{
			if (!available)
			{
				return L("value.unavailable", "<unavailable>");
			}
			if (mods.Count != 0)
			{
				return string.Join(Environment.NewLine, mods.Select(FormatLoadedModLine));
			}
			return L("value.empty", "<empty>");
		}

		private static string FormatLoadedModOrder(IReadOnlyList<ContentModInventoryEntry> mods)
		{
			if (mods.Count != 0)
			{
				return string.Join(Environment.NewLine, mods.Select((ContentModInventoryEntry mod) => $"#{mod.Index + 1:00} {mod.Source}:{mod.Id}"));
			}
			return L("value.empty", "<empty>");
		}

		private static string FormatLoadedModLine(ContentModInventoryEntry mod)
		{
			string value = ((string.IsNullOrWhiteSpace(mod.Name) || string.Equals(mod.Name, mod.Id, StringComparison.Ordinal)) ? mod.Id : (mod.Name + " (" + mod.Id + ")"));
			string value2 = (mod.WorkshopItemId.HasValue ? (" workshop=" + mod.WorkshopItemId.Value) : "");
			string value3 = (mod.AffectsGameplay ? L("value.affectsGameplay", "gameplay") : L("value.noGameplay", "non-gameplay"));
			string value4 = (mod.IsDependency ? (", " + L("value.dependency", "dependency")) : "");
			return $"#{mod.Index + 1:00} [{value3}{value4}] {value} version={FormatVersion(mod.Version)} source={mod.Source}{value2}";
		}

		private static string FormatLoadedModPath(ContentModInventoryEntry mod)
		{
			return (mod.Source + "." + mod.Id).Replace(' ', '_');
		}

		private static string FormatVersion(string? version)
		{
			if (!string.IsNullOrWhiteSpace(version))
			{
				return version.Trim();
			}
			return L("value.noVersion", "No version");
		}

		private static string FormatWorkshopItemId(ulong? itemId)
		{
			if (!itemId.HasValue)
			{
				return L("value.none", "<none>");
			}
			return itemId.Value.ToString();
		}

		private static string JoinLinesOrNone(IReadOnlyList<string> lines)
		{
			if (lines.Count != 0)
			{
				return string.Join(Environment.NewLine, lines);
			}
			return L("value.none", "<none>");
		}

		private static void AddOptionalSortMode(ICollection<StateDivergenceDiagnosticRow> rows, string path, bool? local, bool? remote, bool includeMatching)
		{
			if (local.HasValue || remote.HasValue)
			{
				string text = FormatOptionalSortMode(local);
				string text2 = FormatOptionalSortMode(remote);
				if (includeMatching || !string.Equals(text, text2, StringComparison.Ordinal))
				{
					rows.Add(new StateDivergenceDiagnosticRow(path, text, text2));
				}
			}
		}

		private static void AddSavedPropertyMapRows(ICollection<StateDivergenceDiagnosticRow> rows, IReadOnlyList<string> local, IReadOnlyList<string> remote, bool includeMatching)
		{
			int num = Math.Max(local.Count, remote.Count);
			List<string> list = new List<string>();
			List<string> list2 = new List<string>();
			for (int i = 0; i < num; i++)
			{
				string text = ((i < local.Count) ? local[i] : L("value.missing", "Missing"));
				string text2 = ((i < remote.Count) ? remote[i] : L("value.missing", "Missing"));
				if (includeMatching || !string.Equals(text, text2, StringComparison.Ordinal))
				{
					list.Add($"{i:0000}  {text}");
					list2.Add($"{i:0000}  {text2}");
				}
			}
			if (list.Count != 0)
			{
				rows.Add(new StateDivergenceDiagnosticRow("savedProperties.netIdMap", string.Join(Environment.NewLine, list), string.Join(Environment.NewLine, list2), F("detail.savedPropertyMapMismatch", "{0} SavedProperty net-id slot(s) differ.", list.Count)));
			}
		}

