		internal static string BuildExportReport(StateDivergenceDiagnosticReport report)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine(report.Title);
			stringBuilder.AppendLine(new string('=', report.Title.Length));
			stringBuilder.AppendLine();
			stringBuilder.AppendLine(report.Summary);
			stringBuilder.AppendLine(T("summary.originNote", "If you are seeing this window, the game itself has reported state divergence. This window only provides additional analysis of that state."));
			stringBuilder.AppendLine(F("footer.context", "Role: {0}  Remote peer: {1}", report.Role, report.RemotePeerId));
			stringBuilder.AppendLine();
			AppendRuntimeFrameworkVersions(stringBuilder);
			stringBuilder.AppendLine();
			AppendChecksum(stringBuilder, T("column.local", "Local"), report.LocalChecksum);
			AppendChecksum(stringBuilder, T("column.remote", "Remote"), report.RemoteChecksum);
			AppendLoadedMods(stringBuilder, T("column.local", "Local"), report.LocalLoadedMods, inventoryAvailable: true);
			AppendLoadedMods(stringBuilder, T("column.remote", "Remote"), report.RemoteLoadedMods, report.HasRemoteLoadedModInventory);
			AppendContentMods(stringBuilder, T("column.local", "Local"), report.LocalContentMods, inventoryAvailable: true);
			AppendContentMods(stringBuilder, T("column.remote", "Remote"), report.RemoteContentMods, report.HasRemoteContentModInventory);
			AppendProgress(stringBuilder, T("column.local", "Local"), report.LocalProgress);
			AppendProgress(stringBuilder, T("column.remote", "Remote"), report.RemoteProgress);
			foreach (StateDivergenceDiagnosticSection exportSection in report.ExportSections)
			{
				stringBuilder.AppendLine();
				stringBuilder.AppendLine(exportSection.Title);
				stringBuilder.AppendLine(new string('-', exportSection.Title.Length));
				stringBuilder.AppendLine(exportSection.Description);
				foreach (StateDivergenceDiagnosticRow row in exportSection.Rows)
				{
					AppendReportRow(stringBuilder, row);
				}
			}
			stringBuilder.AppendLine();
			stringBuilder.AppendLine("LOCAL STATE DUMP");
			stringBuilder.AppendLine(report.LocalStateDump);
			stringBuilder.AppendLine("REMOTE STATE DUMP");
			stringBuilder.AppendLine(report.RemoteStateDump);
			return stringBuilder.ToString();
		}

		private static void AppendRuntimeFrameworkVersions(StringBuilder builder)
		{
			builder.AppendLine(T("section.frameworkVersions", "Framework versions"));
			foreach (string item in RuntimeFrameworkVersionSummary.BuildDisplayLines(includeMissingBaseLib: false))
			{
				builder.AppendLine("  " + item);
			}
		}

		private static void AppendChecksum(StringBuilder builder, string title, StateDivergenceChecksumInfo info)
		{
			builder.AppendLine(title);
			builder.AppendLine("  " + F("checksum.id", "ID: {0}", info.Id));
			builder.AppendLine("  " + FormatChecksumLine(info));
			builder.AppendLine("  " + F("checksum.context", "Context: {0}", info.Context));
		}

		private static void AppendLoadedMods(StringBuilder builder, string peerTitle, IReadOnlyList<ContentModInventoryEntry> mods, bool inventoryAvailable)
		{
			builder.AppendLine();
			builder.AppendLine(peerTitle + " " + T("section.loadedMods.export", "all loaded mods"));
			if (!inventoryAvailable)
			{
				builder.AppendLine("  <unavailable>");
