		private static void AppendProgress(StringBuilder builder, string peerTitle, ProgressDiagnosticsSnapshot? progress)
		{
			builder.AppendLine();
			builder.AppendLine(peerTitle + " " + T("section.progress", "progress"));
			if (progress == null)
			{
				builder.AppendLine("  <unavailable>");
				return;
			}
			StringBuilder stringBuilder = builder;
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(16, 1, stringBuilder);
			handler.AppendLiteral("  schemaVersion=");
