				stringBuilder4.AppendLine(ref handler);
			}
		}

		private static void AppendReportRow(StringBuilder builder, StateDivergenceDiagnosticRow row)
		{
			if ((object)row != null && row.Kind == StateDivergenceDiagnosticRowKind.ModelList && row.ModelItems != null)
			{
				builder.AppendLine(row.Path);
				if (!string.IsNullOrWhiteSpace(row.Detail))
				{
					builder.AppendLine("  " + row.Detail);
				}
				{
					foreach (StateDivergenceDiagnosticModelListItem modelItem in row.ModelItems)
					{
						StringBuilder stringBuilder = builder;
						StringBuilder stringBuilder2 = stringBuilder;
						StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(19, 3, stringBuilder);
						handler.AppendLiteral("  ");
						handler.AppendFormatted(modelItem.Index);
						handler.AppendLiteral(": local=");
						handler.AppendFormatted(modelItem.LocalSummary);
						handler.AppendLiteral("; remote=");
						handler.AppendFormatted(modelItem.RemoteSummary);
						stringBuilder2.AppendLine(ref handler);
						foreach (StateDivergenceDiagnosticFieldDifference difference in modelItem.Differences)
						{
							stringBuilder = builder;
							StringBuilder stringBuilder3 = stringBuilder;
							handler = new StringBuilder.AppendInterpolatedStringHandler(4, 1, stringBuilder);
							handler.AppendLiteral("    ");
							handler.AppendFormatted(difference.Path);
							stringBuilder3.AppendLine(ref handler);
							stringBuilder = builder;
							StringBuilder stringBuilder4 = stringBuilder;
							handler = new StringBuilder.AppendInterpolatedStringHandler(13, 1, stringBuilder);
							handler.AppendLiteral("      local: ");
							handler.AppendFormatted(difference.LocalValue.ReplaceLineEndings(" | "));
							stringBuilder4.AppendLine(ref handler);
							stringBuilder = builder;
							StringBuilder stringBuilder5 = stringBuilder;
							handler = new StringBuilder.AppendInterpolatedStringHandler(14, 1, stringBuilder);
							handler.AppendLiteral("      remote: ");
							handler.AppendFormatted(difference.RemoteValue.ReplaceLineEndings(" | "));
							stringBuilder5.AppendLine(ref handler);
						}
					}
					return;
				}
			}
			if (!IsExpandedDetail(row))
			{
				StringBuilder stringBuilder = builder;
				StringBuilder stringBuilder6 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(17, 3, stringBuilder);
				handler.AppendFormatted(row.Path);
				handler.AppendLiteral(": local=");
				handler.AppendFormatted(row.LocalValue);
				handler.AppendLiteral("; remote=");
				handler.AppendFormatted(row.RemoteValue);
				stringBuilder6.AppendLine(ref handler);
			}
			else
			{
				builder.AppendLine(row.Path);
				if (!string.IsNullOrWhiteSpace(row.Detail))
				{
					builder.AppendLine("  " + row.Detail);
				}
				builder.AppendLine("  local:");
				AppendIndentedLines(builder, row.LocalValue, "    ");
				builder.AppendLine("  remote:");
				AppendIndentedLines(builder, row.RemoteValue, "    ");
			}
		}

		private static void AppendIndentedLines(StringBuilder builder, string text, string indent)
