		private static string FormatChecksumLine(StateDivergenceChecksumInfo info)
		{
			string text = FormatReportedSortModes(info.ModelDbHashUsesDeterministicCache, info.SavedPropertyNetIdUsesDeterministicSort);
			if (text != null)
			{
				return F("checksum.valueWithSort", "Checksum: {0}  Sort: {1}", info.Checksum, text);
			}
			return F("checksum.value", "Checksum: {0}", info.Checksum);
		}

		private static string? FormatReportedSortModes(bool? modelDbDeterministic, bool? savedPropertyDeterministic)
		{
			if (!modelDbDeterministic.HasValue && !savedPropertyDeterministic.HasValue)
			{
				return null;
			}
			if (!savedPropertyDeterministic.HasValue)
			{
				return F("value.sortModes.modelDbOnly", "ModelDb {0}", FormatCompactSortMode(modelDbDeterministic.Value));
			}
			if (!modelDbDeterministic.HasValue)
			{
				return F("value.sortModes.savedPropertyOnly", "SavedProperty {0}", FormatCompactSortMode(savedPropertyDeterministic.Value));
			}
			return F("value.sortModes.stateDivergence", "ModelDb {0} / SavedProperty {1}", FormatCompactSortMode(modelDbDeterministic.Value), FormatCompactSortMode(savedPropertyDeterministic.Value));
		}

		private static string FormatCompactSortMode(bool deterministic)
		{
			if (!deterministic)
