					string value = DateTime.Now.ToString("yyyyMMdd_HHmmss_fffffff");
					string text3 = $"{"ritsulib_state_divergence_"}{value}_checksum_{report.LocalChecksum.Id}_{report.LocalChecksum.Checksum:x8}_{Guid.NewGuid():N}";
					text = RitsuLibDataPaths.CreateTemporaryDirectory("state-divergence");
					string text4 = Path.Combine(text, "payload");
					Directory.CreateDirectory(text4);
					File.WriteAllText(Path.Combine(text4, "state-divergence-report.txt"), StateDivergenceDiagnosticsPanel.BuildExportReport(report), Utf8NoBom);
					WriteJson(Path.Combine(text4, "metadata.json"), BuildMetadata(report, localLogs, remoteLogs, trigger));
					WriteJson(Path.Combine(text4, "local-debug-log.records.json"), localLogs?.Records ?? Array.Empty<StateDivergenceLogRecord>());
					if (remoteLogs != null)
					{
						WriteJson(Path.Combine(text4, "remote-debug-log.records.json"), remoteLogs.Records);
					}
					string text5 = Path.Combine(text, text3 + ".zip");
					ZipFile.CreateFromDirectory(text4, text5, CompressionLevel.Optimal, includeBaseDirectory: false);
					ValidateBundle(text5, remoteLogs != null);
					string text6 = Path.Combine(text2, Path.GetFileName(text5));
					PublishBundle(text5, text6);
					zipPath = text6;
					zipFileName = Path.GetFileName(text6);
					PruneOldBundles(text2, text6);
					return true;
				}
				catch (Exception ex)
				{
					errorMessage = ex.Message;
					return false;
				}
				finally
				{
					if (!string.IsNullOrWhiteSpace(text) && Directory.Exists(text))
					{
						try
						{
							Directory.Delete(text, recursive: true);
						}
						catch
						{
						}
					}
				}
			}
		}

		internal static bool IsPublishedBundlePath(string path)
		{
			if (string.IsNullOrWhiteSpace(path))
			{
				return false;
			}
			try
			{
				string fullPath = Path.GetFullPath(path);
				string directoryName = Path.GetDirectoryName(fullPath);
				string fileName = Path.GetFileName(fullPath);
				StringComparison comparisonType = (OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);
				return string.Equals(directoryName, Path.GetFullPath(ResolveLogsDirectory()), comparisonType) && fileName.StartsWith("ritsulib_state_divergence_", StringComparison.Ordinal) && fileName.EndsWith(".zip", StringComparison.Ordinal);
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				return false;
			}
		}

		internal static byte[] BuildSanitizedSubmissionBundle(string sourcePath)
		{
			using (BundleWriteLock.EnterScope())
			{
				return BuildSanitizedSubmissionBundleCore(sourcePath);
			}
		}

		private static byte[] BuildSanitizedSubmissionBundleCore(string sourcePath)
		{
			using ZipArchive zipArchive = ZipFile.OpenRead(sourcePath);
			ValidateBundleEntries(zipArchive, null);
			using MemoryStream memoryStream = new MemoryStream();
			using (ZipArchive zipArchive2 = new ZipArchive(memoryStream, ZipArchiveMode.Create, leaveOpen: true))
			{
				foreach (ZipArchiveEntry entry in zipArchive.Entries)
				{
					ZipArchiveEntry zipArchiveEntry = zipArchive2.CreateEntry(entry.FullName, CompressionLevel.Optimal);
					using Stream source = entry.Open();
					using Stream destination = zipArchiveEntry.Open();
					if (entry.FullName.EndsWith(".json", StringComparison.Ordinal))
					{
						WriteSanitizedJson(source, destination);
					}
					else
					{
						WriteSanitizedText(source, destination);
					}
				}
			}
			return memoryStream.ToArray();
		}

		private static object BuildMetadata(StateDivergenceDiagnosticReport report, StateDivergenceRecentLogSnapshot? localLogs, StateDivergenceRecentLogSnapshot? remoteLogs, string trigger)
		{
			return new
			{
				generatedAtUtc = DateTimeOffset.UtcNow,
				trigger = trigger,
				ritsuLibVersion = "0.5.18",
				Role = report.Role,
				RemotePeerId = report.RemotePeerId,
				localChecksum = report.LocalChecksum,
				remoteChecksum = report.RemoteChecksum,
				localLogs = Summarize(localLogs),
				remoteLogs = Summarize(remoteLogs)
			};
		}

		private static object Summarize(StateDivergenceRecentLogSnapshot? logs)
		{
			if (logs == null)
			{
				return new
				{
					available = false
				};
			}
			return new
			{
				available = true,
				CapturedAtUtc = logs.CapturedAtUtc,
				TotalRecordCount = logs.TotalRecordCount,
				IncludedRecordCount = logs.IncludedRecordCount,
				DroppedOldRecordCount = logs.DroppedOldRecordCount
			};
		}

		private static void WriteJson(string path, object value)
		{
			File.WriteAllText(path, JsonSerializer.Serialize(value, JsonOptions), Utf8NoBom);
		}

		private static void ValidateBundle(string path, bool expectRemoteLogs)
		{
			using ZipArchive zipArchive = ZipFile.OpenRead(path);
			ValidateBundleEntries(zipArchive, expectRemoteLogs);
			foreach (ZipArchiveEntry entry in zipArchive.Entries)
			{
				using Stream stream = entry.Open();
				stream.CopyTo(Stream.Null);
			}
		}

		private static void ValidateBundleEntries(ZipArchive archive, bool? expectRemoteLogs)
		{
			Dictionary<string, ZipArchiveEntry> dictionary = archive.Entries.ToDictionary<ZipArchiveEntry, string>((ZipArchiveEntry entry) => entry.FullName, StringComparer.Ordinal);
			string[] requiredBundleEntries = RequiredBundleEntries;
			foreach (string text in requiredBundleEntries)
			{
				if (!dictionary.ContainsKey(text))
				{
					throw new InvalidDataException("The state divergence bundle is missing the required entry '" + text + "'.");
				}
			}
			bool flag = dictionary.ContainsKey("remote-debug-log.records.json");
			if (expectRemoteLogs.HasValue && flag != expectRemoteLogs.Value)
			{
				throw new InvalidDataException(expectRemoteLogs.Value ? "The state divergence bundle is missing the remote log entry." : "The state divergence bundle contains an unexpected remote log entry.");
			}
			int num2 = RequiredBundleEntries.Length + (flag ? 1 : 0);
			if (dictionary.Count != num2)
			{
				throw new InvalidDataException($"The state divergence bundle contains {dictionary.Count} entries; expected {num2}.");
			}
		}

		private static void WriteSanitizedJson(Stream source, Stream destination)
		{
			using JsonDocument jsonDocument = JsonDocument.Parse(source);
			using Utf8JsonWriter writer = new Utf8JsonWriter(destination, new JsonWriterOptions
			{
				Indented = true
			});
			WriteSanitizedJsonElement(jsonDocument.RootElement, writer);
		}

		private static void WriteSanitizedJsonElement(JsonElement element, Utf8JsonWriter writer)
		{
			switch (element.ValueKind)
			{
			case JsonValueKind.Object:
				writer.WriteStartObject();
				foreach (JsonProperty item in element.EnumerateObject())
				{
					writer.WritePropertyName(item.Name);
					WriteSanitizedJsonElement(item.Value, writer);
				}
				writer.WriteEndObject();
				break;
			case JsonValueKind.Array:
				writer.WriteStartArray();
				foreach (JsonElement item2 in element.EnumerateArray())
				{
					WriteSanitizedJsonElement(item2, writer);
				}
				writer.WriteEndArray();
				break;
			case JsonValueKind.String:
				writer.WriteStringValue(LogSanitizer.Sanitize(element.GetString() ?? ""));
				break;
			default:
				element.WriteTo(writer);
				break;
			}
		}

		private static void WriteSanitizedText(Stream source, Stream destination)
		{
			using StreamReader streamReader = new StreamReader(source, Encoding.UTF8, detectEncodingFromByteOrderMarks: true, 1024, leaveOpen: true);
			using StreamWriter streamWriter = new StreamWriter(destination, Utf8NoBom, 1024, leaveOpen: true);
			streamWriter.Write(LogSanitizer.Sanitize(streamReader.ReadToEnd()));
		}

		private static void PruneOldBundles(string logsDir, string currentZipPath)
		{
			try
			{
				string fullPath = Path.GetFullPath(currentZipPath);
				foreach (FileInfo item in (from path in Directory.EnumerateFiles(logsDir, "ritsulib_state_divergence_*.zip", SearchOption.TopDirectoryOnly)
					select new FileInfo(path) into file
					where file.Exists
					orderby file.LastWriteTimeUtc descending
					select file).ThenByDescending<FileInfo, string>((FileInfo file) => file.Name, StringComparer.OrdinalIgnoreCase).ToArray().Skip(5))
				{
					if (!string.Equals(Path.GetFullPath(item.FullName), fullPath, StringComparison.OrdinalIgnoreCase))
					{
						item.Delete();
					}
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[State divergence diagnostics] failed to prune old diagnostic bundles: " + ex.Message, 1);
			}
		}

		private static string ResolveLogsDirectory()
		{
			return Path.Combine(ResolveUserDataDirectory(), "logs");
		}

		private static void PublishBundle(string stagedZipPath, string publishedZipPath)
		{
			try
			{
				File.Copy(stagedZipPath, publishedZipPath);
			}
			catch
			{
				if (File.Exists(publishedZipPath))
				{
					File.Delete(publishedZipPath);
				}
				throw;
			}
		}

		private static string ResolveUserDataDirectory()
		{
			string userDataDir = OS.GetUserDataDir();
			if (!string.IsNullOrWhiteSpace(userDataDir))
			{
				return userDataDir;
			}
			return AppContext.BaseDirectory;
		}
	}
