				{
					return;
				}
				string text = TryReadRole(__instance);
				StateDivergenceSupplementPayload stateDivergenceSupplementPayload = StateDivergenceSupplementPayloadCodec.CreateLocalSnapshot(tracked.Checksum);
				StateDivergenceSupplementPayload stateDivergenceSupplementPayload2 = (StateDivergenceSupplementStore.TryTake(message.senderChecksum, out StateDivergenceSupplementPayload payload) ? payload : null);
				if (string.Equals(text, "Client", StringComparison.Ordinal))
				{
					StateDivergenceSupplementPayloadCodec.PrepareOutgoingSnapshot(stateDivergenceSupplementPayload);
				}
				StateDivergenceDiagnosticReport stateDivergenceDiagnosticReport = StateDivergenceDiagnosticReportBuilder.Build(tracked, message, remoteId, text, stateDivergenceSupplementPayload, stateDivergenceSupplementPayload2);
				using (StateDivergenceDiagnosticsLocalization.UseEnglish())
				{
					StateDivergenceDiagnosticReport stateDivergenceDiagnosticReport2 = StateDivergenceDiagnosticReportBuilder.Build(tracked, message, remoteId, text, stateDivergenceSupplementPayload, stateDivergenceSupplementPayload2);
					StateDivergenceLogBundleWriter.TryWrite(stateDivergenceDiagnosticReport2, stateDivergenceSupplementPayload.RecentLogs, stateDivergenceSupplementPayload2?.RecentLogs, "LogStateDivergence", out string zipPath, out string zipFileName, out string errorMessage);
					stateDivergenceDiagnosticReport = stateDivergenceDiagnosticReport with
					{
						BundleFileName = zipFileName,
						BundlePath = zipPath,
						BundleError = errorMessage
					};
					stateDivergenceDiagnosticReport2 = stateDivergenceDiagnosticReport2 with
					{
						BundleFileName = zipFileName,
						BundlePath = zipPath,
						BundleError = errorMessage
					};
					StateDivergenceDiagnosticsReports.Store(stateDivergenceDiagnosticReport, stateDivergenceDiagnosticReport2, zipPath, errorMessage);
					StateDivergenceTelemetryCollector.CaptureForAuthorizedApplicants(stateDivergenceDiagnosticReport2, zipPath, "LogStateDivergence");
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[State divergence diagnostics] failed: " + ex.Message, 1);
			}
		}

		private static bool TryReadTrackedState(object source, out StateDivergenceTrackedState tracked)
		{
			//IL_0050: Unknown result type (might be due to invalid IL or missing references)
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			//IL_008e: Unknown result type (might be due to invalid IL or missing references)
			tracked = default(StateDivergenceTrackedState);
			Type type = source.GetType();
			FieldInfo field = type.GetField("data", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			FieldInfo field2 = type.GetField("context", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			FieldInfo field3 = type.GetField("fullState", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (field?.GetValue(source) is NetChecksumData checksum)
			{
				object? obj = field3?.GetValue(source);
				NetFullCombatState val = (NetFullCombatState)((obj is NetFullCombatState) ? obj : null);
				if (val != null)
				{
					string context = (field2?.GetValue(source) as string) ?? "";
					tracked = new StateDivergenceTrackedState(checksum, context, val);
					return true;
				}
			}
			return false;
		}

		private static string TryReadRole(ChecksumTracker tracker)
		{
			//IL_002d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0032: Unknown result type (might be due to invalid IL or missing references)
			object? obj = typeof(ChecksumTracker).GetField("_netService", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(tracker);
			INetGameService val = (INetGameService)((obj is INetGameService) ? obj : null);
			if (val != null)
			{
				return ((object)val.Type/*cast due to constrained. prefix*/).ToString();
			}
			return "Unknown";
		}
	}
	internal sealed class StateDivergenceDiagnosticsPopupCreatePatch : IPatchMethod
	{
		public static string PatchId => "state_divergence_diagnostics_popup_create";

		public static bool IsCritical => false;

		public static string Description => "Attach RitsuLib state divergence diagnostics to state divergence error popups.";

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NErrorPopup), "Create", new Type[1] { typeof(NetErrorInfo) })
			};
		}

		public static void Postfix(NetErrorInfo info, NErrorPopup? __result)
		{
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_000c: Invalid comparison between Unknown and I4
			if (__result != null && (int)((NetErrorInfo)(ref info)).GetReason() == 105 && StateDivergenceDiagnosticsReports.TryGetLatest(out StateDivergenceDiagnosticReport report))
			{
				StateDivergenceDiagnosticsReports.PopupReports.Remove(__result);
				StateDivergenceDiagnosticsReports.PopupReports.Add(__result, report);
				StateDivergenceDiagnosticsReports.TryLogLatestToGameLog("error popup created");
			}
		}
	}
