		public static RitsuLibSidecarRequiredCapabilityPolicy Policy { get; set; } = RitsuLibSidecarRequiredCapabilityPolicy.Warn;

		/// <summary>
		///     <para xml:lang="en">Raised after each validation run.</para>
		///     <para xml:lang="zh-CN">每次验证运行后引发。</para>
		/// </summary>
		public static event Action<SidecarRequiredCapabilityCheckCompletedEvent>? CheckCompleted;

		/// <summary>
		///     <para xml:lang="en">Registers or replaces an evaluator for one required capability.</para>
		///     <para xml:lang="zh-CN">注册或替换一项所需能力的判定器。</para>
		/// </summary>
		public static void RegisterRequiredCapability(string capabilityKey, Func<ulong, bool> evaluator)
		{
			ArgumentException.ThrowIfNullOrEmpty(capabilityKey, "capabilityKey");
			ArgumentNullException.ThrowIfNull(evaluator, "evaluator");
			using (Gate.EnterScope())
			{
				CapabilityChecks[capabilityKey] = evaluator;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Validates required capabilities for the specified peer set.</para>
		///     <para xml:lang="zh-CN">验证指定对等端集合的所需能力。</para>
		/// </summary>
		public static bool ValidatePeers(IEnumerable<ulong> peerNetIds, out SidecarRequiredCapabilityMiss[] misses)
		{
			KeyValuePair<string, Func<ulong, bool>>[] array;
			using (Gate.EnterScope())
			{
				array = CapabilityChecks.ToArray();
			}
			List<SidecarRequiredCapabilityMiss> list = new List<SidecarRequiredCapabilityMiss>();
			foreach (ulong item in peerNetIds.Distinct())
			{
				List<string> list2 = new List<string>();
				for (int i = 0; i < array.Length; i++)
				{
					if (!array[i].Value(item))
					{
						list2.Add(array[i].Key);
					}
				}
				if (list2.Count > 0)
				{
					list.Add(new SidecarRequiredCapabilityMiss(item, list2));
				}
			}
			misses = list.ToArray();
			bool flag = misses.Length == 0 || Policy == RitsuLibSidecarRequiredCapabilityPolicy.Warn;
			CheckCompleted?.Invoke(new SidecarRequiredCapabilityCheckCompletedEvent(flag, Policy, misses));
			return flag;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Dispatches Sidecar payloads and one-shot waiters by 64-bit opcode.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         按 64 位操作码分发 Sidecar 载荷和一次性等待器。
	///     </para>
	/// </summary>
	public static class RitsuLibSidecarBus
	{
		private sealed class PendingWaiter
		{
			public required ulong Opcode { get; init; }

			public required bool ConsumeOnMatch { get; init; }

			public required Func<RitsuLibSidecarDispatchContext, bool>? Predicate { get; init; }

			public required TaskCompletionSource<RitsuLibSidecarDispatchContext> Tcs { get; init; }
		}

		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<ulong, Action<RitsuLibSidecarDispatchContext>> Handlers = new Dictionary<ulong, Action<RitsuLibSidecarDispatchContext>>();

		private static readonly List<PendingWaiter> Waiters = new List<PendingWaiter>();

		private static readonly TimeSpan MaximumSupportedWaitTimeout = TimeSpan.FromMilliseconds(4294967294L, 0L);

		/// <summary>
		///     <para xml:lang="en">
		///         Registers or replaces the handler for <paramref name="opcode" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册或替换 <paramref name="opcode" /> 对应的处理器。
		///     </para>
		/// </summary>
		public static void RegisterHandler(ulong opcode, Action<RitsuLibSidecarDispatchContext> handler)
		{
			ArgumentNullException.ThrowIfNull(handler, "handler");
			using (Gate.EnterScope())
			{
				Handlers[opcode] = handler;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Removes the handler for <paramref name="opcode" />, if present.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         移除 <paramref name="opcode" /> 对应的处理器（如存在）。
		///     </para>
		/// </summary>
		public static void UnregisterHandler(ulong opcode)
		{
			using (Gate.EnterScope())
			{
				Handlers.Remove(opcode);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Removes all registered opcode handlers.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         移除所有已注册的操作码处理器。
		///     </para>
		/// </summary>
		public static void ClearHandlers()
		{
			using (Gate.EnterScope())
			{
				Handlers.Clear();
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets a snapshot of the number of active <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBus.WaitForNextAsync(System.UInt64,System.TimeSpan,System.Func{STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDispatchContext,System.Boolean},System.Boolean,System.Threading.CancellationToken)" /> waiters.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取活动 <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBus.WaitForNextAsync(System.UInt64,System.TimeSpan,System.Func{STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDispatchContext,System.Boolean},System.Boolean,System.Threading.CancellationToken)" /> 等待器数量的快照。
		///     </para>
		/// </summary>
		public static int GetPendingWaiterCount()
		{
			using (Gate.EnterScope())
			{
				return Waiters.Count;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Removes every pending <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBus.WaitForNextAsync(System.UInt64,System.TimeSpan,System.Func{STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDispatchContext,System.Boolean},System.Boolean,System.Threading.CancellationToken)" /> waiter and completes its task as canceled.
		///         Registered opcode handlers are retained.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         移除所有待处理的 <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBus.WaitForNextAsync(System.UInt64,System.TimeSpan,System.Func{STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDispatchContext,System.Boolean},System.Boolean,System.Threading.CancellationToken)" /> 等待器，并将其任务完成为已取消。
		///         已注册的操作码处理器会保留。
		///     </para>
		/// </summary>
		public static void CancelAllPendingWaits()
		{
			List<PendingWaiter> list;
			using (Gate.EnterScope())
			{
				list = Waiters.ToList();
				Waiters.Clear();
			}
			foreach (PendingWaiter item in list)
			{
				item.Tcs.TrySetCanceled();
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Waits for the next packet matching an opcode and optional predicate.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         等待下一个与操作码及可选谓词匹配的数据包。
		///     </para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         A timeout may be <c>Timeout.InfiniteTimeSpan</c> or from <c>TimeSpan.Zero</c> through
		///         the maximum supported <see cref="M:System.Threading.Tasks.Task.Delay(System.TimeSpan,System.Threading.CancellationToken)" /> value; zero and infinite
		///         timeouts do not schedule a timeout. Caller cancellation is tracked separately. Task continuations are
		///         not marshaled to the Godot main loop; use
		///         <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarGodotMainLoopScheduling.ContinueOnGodotMainLoopAsync``1(System.Threading.Tasks.Task{``0})" /> when
		///         main-loop affinity is required. The predicate executes synchronously outside the bus lock against an
		///         opcode-matching waiter snapshot. If a candidate completes or is canceled concurrently, dispatch
		///         continues to the next still-pending matching candidate.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         超时可以是 <c>Timeout.InfiniteTimeSpan</c>，或从 <c>TimeSpan.Zero</c> 到
		///         <see cref="M:System.Threading.Tasks.Task.Delay(System.TimeSpan,System.Threading.CancellationToken)" /> 支持的最大值；零超时和无限超时均不会安排超时。
		///         调用方取消会单独处理。任务的延续不会自动切换到 Godot 主循环；需要主循环线程关联时，请使用
		///         <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarGodotMainLoopScheduling.ContinueOnGodotMainLoopAsync``1(System.Threading.Tasks.Task{``0})" />。
		///         谓词会针对操作码匹配等待器的快照在总线锁外同步执行。若候选等待器在并发情况下已完成或被取消，
		///         分发会继续检查下一个仍待处理的匹配候选。
		///     </para>
		/// </remarks>
		public static Task<RitsuLibSidecarDispatchContext> WaitForNextAsync(ulong opcode, TimeSpan timeout, Func<RitsuLibSidecarDispatchContext, bool>? predicate = null, bool consumeOnMatch = true, CancellationToken cancellationToken = default(CancellationToken))
		{
			ValidateTimeout(timeout);
			TaskCompletionSource<RitsuLibSidecarDispatchContext> taskCompletionSource = new TaskCompletionSource<RitsuLibSidecarDispatchContext>(TaskCreationOptions.RunContinuationsAsynchronously);
			PendingWaiter waiter = new PendingWaiter
			{
				Opcode = opcode,
				ConsumeOnMatch = consumeOnMatch,
				Predicate = predicate,
				Tcs = taskCompletionSource
			};
			using (Gate.EnterScope())
			{
				Waiters.Add(waiter);
			}
			if (timeout > TimeSpan.Zero)
			{
				Task.Delay(timeout, CancellationToken.None).ContinueWith(delegate
				{
					TryTimeoutWaiter(waiter);
				}, CancellationToken.None, TaskContinuationOptions.ExecuteSynchronously, TaskScheduler.Default);
			}
			if (cancellationToken.CanBeCanceled)
			{
				cancellationToken.Register(delegate
				{
					TryCancelWaiter(waiter, cancellationToken);
				});
			}
			return taskCompletionSource.Task;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Removes a still-pending waiter and faults it with <paramref name="exception" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         移除仍在等待的等待器，并使用 <paramref name="exception" /> 将其任务置为失败。
		///     </para>
		/// </summary>
		internal static bool TryFailWaitIfStillPending(Task<RitsuLibSidecarDispatchContext> waitTask, Exception exception)
		{
			PendingWaiter pendingWaiter = null;
			using (Gate.EnterScope())
			{
				for (int i = 0; i < Waiters.Count; i++)
				{
					PendingWaiter pendingWaiter2 = Waiters[i];
					if (pendingWaiter2.Tcs.Task == waitTask)
					{
						Waiters.RemoveAt(i);
						pendingWaiter = pendingWaiter2;
						break;
					}
				}
			}
			return pendingWaiter?.Tcs.TrySetException(exception) ?? false;
		}

		private static void TryTimeoutWaiter(PendingWaiter waiter)
		{
			bool flag;
			using (Gate.EnterScope())
			{
				flag = Waiters.Remove(waiter);
			}
			if (flag)
			{
				waiter.Tcs.TrySetException(new TimeoutException("Sidecar wait timed out"));
			}
		}

		private static void TryCancelWaiter(PendingWaiter waiter, CancellationToken cancellationToken)
		{
			bool flag;
			using (Gate.EnterScope())
			{
				flag = Waiters.Remove(waiter);
			}
			if (flag)
			{
				waiter.Tcs.TrySetCanceled(cancellationToken);
			}
		}

		internal static void Dispatch(in RitsuLibSidecarDispatchContext context)
		{
			RitsuLibSidecarDispatchContext dispatchContext = context;
			PendingWaiter pendingWaiter = null;
			bool flag = false;
			Action<RitsuLibSidecarDispatchContext> value;
			PendingWaiter[] array;
			using (Gate.EnterScope())
			{
				Handlers.TryGetValue(dispatchContext.Opcode, out value);
				array = Waiters.Where((PendingWaiter w) => w.Opcode == dispatchContext.Opcode).ToArray();
			}
			PendingWaiter[] array2 = array;
			foreach (PendingWaiter pendingWaiter2 in array2)
			{
				if (pendingWaiter2.Predicate != null && !pendingWaiter2.Predicate(dispatchContext))
				{
					continue;
				}
				using (Gate.EnterScope())
				{
					if (!Waiters.Remove(pendingWaiter2))
					{
						continue;
					}
					pendingWaiter = pendingWaiter2;
					flag = pendingWaiter2.ConsumeOnMatch;
					break;
				}
			}
			pendingWaiter?.Tcs.TrySetResult(dispatchContext);
			if (!flag)
			{
				value?.Invoke(dispatchContext);
			}
		}

		private static void ValidateTimeout(TimeSpan timeout)
		{
			if ((timeout == Timeout.InfiniteTimeSpan || timeout >= TimeSpan.Zero) && timeout <= MaximumSupportedWaitTimeout)
			{
				return;
			}
			throw new ArgumentOutOfRangeException("timeout", timeout, $"Timeout must be {Timeout.InfiniteTimeSpan} or between {TimeSpan.Zero} and {MaximumSupportedWaitTimeout}.");
		}
	}
	internal static class RitsuLibSidecarBuiltInHandlers
	{
		private static readonly RitsuLibSidecarChunkReassembly Chunks = new RitsuLibSidecarChunkReassembly();

		internal static void Register()
		{
			RitsuLibSidecarBus.RegisterHandler(16uL, OnHandshake);
			RitsuLibSidecarBus.RegisterHandler(17uL, OnHandshakeAck);
			RitsuLibSidecarBus.RegisterHandler(18uL, OnChunkedFrame);
			RitsuLibSidecarBus.RegisterHandler(19uL, OnChunkStreamSelectiveNack);
			RitsuLibSidecarBus.RegisterHandler(20uL, OnChunkStreamReassemblyDone);
			RitsuLibSidecarBus.RegisterHandler(21uL, OnRelayDumpRequest);
			RitsuLibSidecarBus.RegisterHandler(22uL, OnRelayDumpFanout);
		}

		private static void OnChunkStreamSelectiveNack(RitsuLibSidecarDispatchContext ctx)
		{
			if (ctx.Payload.Length < 22)
			{
				return;
			}
			try
			{
				RitsuLibSidecarChunkGapBinary.ReadSelectiveNack(ctx.Payload.Span, out ulong streamId, out ulong userOpcode, out uint count, out RitsuLibSidecarChunkGapBinary.MissingRange[] missingRanges);
				RitsuLibFramework.Logger.Debug($"[Sidecar] SelectiveNack received sender={ctx.SenderNetId}, stream={streamId}, userOpcode={userOpcode}, count={count}, rangeCount={missingRanges.Length}, payloadLen={ctx.Payload.Length}", 1);
				if (!missingRanges.Any((RitsuLibSidecarChunkGapBinary.MissingRange r) => r.Length == 0 || r.StartIndex >= count || (ulong)((long)r.StartIndex + (long)r.Length) > (ulong)count))
				{
					RitsuLibSidecarChunkOutboundRegistry.HandleSelectiveNack(RunManager.Instance, ctx.SenderNetId, streamId, userOpcode, count, missingRanges);
				}
			}
			catch (Exception ex)
			{
				RitsuLibSidecarRepeatedWarningLog.Warn($"chunk-selective-nack-exception:sender={ctx.SenderNetId}:{ex.GetType().FullName}:{ex.Message}", "[Sidecar] selective NACK: " + ex.Message);
			}
		}

		private static void OnChunkStreamReassemblyDone(RitsuLibSidecarDispatchContext ctx)
		{
			if (ctx.Payload.Length < 8)
			{
				return;
			}
			try
			{
				RitsuLibSidecarChunkGapBinary.ReadReassemblyDone(ctx.Payload.Span, out var streamId);
				RitsuLibFramework.Logger.Debug($"[Sidecar] ReassemblyDone received sender={ctx.SenderNetId}, stream={streamId}, payloadLen={ctx.Payload.Length}", 1);
				RitsuLibSidecarChunkOutboundRegistry.TryRemove(streamId);
			}
			catch (Exception ex)
			{
				RitsuLibSidecarRepeatedWarningLog.Warn($"chunk-reassembly-done-exception:sender={ctx.SenderNetId}:{ex.GetType().FullName}:{ex.Message}", "[Sidecar] chunk reassembly done: " + ex.Message);
			}
		}

		private static void OnRelayDumpRequest(RitsuLibSidecarDispatchContext ctx)
		{
			if (ctx.IsHostIngest && RitsuLibSidecarSessionManager.CanSendToPeer(ctx.SenderNetId) && RitsuLibSidecarDiagnosticRelayGate.TryValidateRequest(ctx.SenderNetId))
			{
				RitsuLibFramework.Logger.Debug($"[Sidecar] Diagnostic relay request sender={ctx.SenderNetId}, opcode={ctx.Opcode}, payloadLen={ctx.Payload.Length}", 1);
			}
		}

		private static void OnRelayDumpFanout(RitsuLibSidecarDispatchContext ctx)
		{
			if (!ctx.IsHostIngest && RitsuLibSidecarDiagnosticPayload.TryParseFanout(ctx.Payload.Span, out var session))
			{
				RunManager instance = RunManager.Instance;
				if (RitsuLibSidecarDiagnosticRelayGate.TryValidateFanout((instance != null) ? instance.NetService : null, ctx.SenderNetId, session))
				{
					RitsuLibFramework.Logger.Debug($"[Sidecar] Diagnostic relay fanout sender={ctx.SenderNetId}, originPeer={session.OriginatingSenderNetId}, checksum={session.ChecksumId}, tag={session.Tag}, payloadLen={ctx.Payload.Length}", 1);
				}
			}
		}

		private static void OnHandshake(RitsuLibSidecarDispatchContext ctx)
		{
			//IL_00d2: Unknown result type (might be due to invalid IL or missing references)
			if (ctx.Payload.Length >= 8)
			{
				RitsuLibSidecarHandshakeBinary.ReadHandshake(ctx.Payload.Span, out var wireFormatVersion, out var supportedWireFormatVersionMax, out var features);
				bool flag = wireFormatVersion == 2 && supportedWireFormatVersionMax >= 2;
				RitsuLibFramework.Logger.Debug($"[Sidecar] Handshake received sender={ctx.SenderNetId}, opcode={ctx.Opcode}, payloadLen={ctx.Payload.Length}, channel={ctx.Channel}, transferMode={ctx.TransferMode}, hostIngest={ctx.IsHostIngest}, wire={wireFormatVersion}, peerMax={supportedWireFormatVersionMax}, features={features}, ok={flag}", 1);
				if (!flag)
				{
					RitsuLibFramework.Logger.Warn($"[Sidecar] Handshake wire version {wireFormatVersion} not supported.", 1);
				}
				ushort num = (ushort)(flag ? wireFormatVersion : 2);
				RitsuLibSidecarConnectionSession.SetPeerFeatures(ctx.SenderNetId, flag ? features : RitsuLibSidecarPeerFeatures.None);
				RitsuLibSidecarSessionManager.NoteHandshakeFromPeer(ctx.SenderNetId, flag ? features : RitsuLibSidecarPeerFeatures.None, flag);
				byte[] array = new byte[7];
				RitsuLibSidecarHandshakeBinary.WriteAck(array.AsSpan(), num, flag, (RitsuLibSidecarPeerFeatures)255u);
				RunManager instance = RunManager.Instance;
				if (ctx.IsHostIngest)
				{
					RitsuLibSidecarHighLevelSend.TrySendAsHostToPeer(instance, ctx.SenderNetId, 17uL, array, RitsuLibSidecarDeliverySemantics.StableSync);
				}
				else
				{
					RitsuLibSidecarHighLevelSend.TrySendAsClient(instance, 17uL, array, RitsuLibSidecarDeliverySemantics.StableSync);
				}
				RitsuLibFramework.Logger.Debug($"[Sidecar] Handshake ack sent target={ctx.SenderNetId}, opcode={17uL}, payloadLen={array.Length}, selectedWire={num}, ok={flag}, senderFeatures={(RitsuLibSidecarPeerFeatures)255u}", 1);
			}
		}

		private static void OnHandshakeAck(RitsuLibSidecarDispatchContext ctx)
		{
			//IL_00e4: Unknown result type (might be due to invalid IL or missing references)
			if (ctx.Payload.Length >= 7)
			{
				RitsuLibSidecarHandshakeBinary.ReadAck(ctx.Payload.Span, out var selectedWireFormatVersion, out var ok, out var ackSenderFeatures);
				RitsuLibSidecarConnectionExchange.NotifyOutboundHandshakeAck(ctx.SenderNetId, ok);
				RitsuLibSidecarConnectionSession.SetPeerFeatures(ctx.SenderNetId, ackSenderFeatures);
				RitsuLibSidecarSessionManager.NoteHandshakeFromPeer(ctx.SenderNetId, ackSenderFeatures, ok);
				RitsuLibFramework.Logger.Debug($"[Sidecar] Handshake ack received sender={ctx.SenderNetId}, opcode={ctx.Opcode}, payloadLen={ctx.Payload.Length}, channel={ctx.Channel}, transferMode={ctx.TransferMode}, selectedWire={selectedWireFormatVersion}, ok={ok}, senderFeatures={ackSenderFeatures}", 1);
			}
		}

		private static void OnChunkedFrame(RitsuLibSidecarDispatchContext ctx)
		{
			//IL_031d: Unknown result type (might be due to invalid IL or missing references)
			Chunks.IncompleteStreamRetention = RitsuLibSidecarNetDiagnosticsOptions.IncompleteChunkStreamRetention;
			try
			{
				ReadOnlyMemory<byte> payload = ctx.Payload;
				RitsuLibSidecarChunkBinary.ReadFrame(payload.Span, out var userOpcode, out var streamId, out var index, out var count, out var totalPayloadSize, out var segmentCrc, out var segment);
				Logger logger = RitsuLibFramework.Logger;
				DefaultInterpolatedStringHandler defaultInterpolatedStringHandler = new DefaultInterpolatedStringHandler(110, 8);
				defaultInterpolatedStringHandler.AppendLiteral("[Sidecar] Chunk frame received sender=");
				defaultInterpolatedStringHandler.AppendFormatted(ctx.SenderNetId);
				defaultInterpolatedStringHandler.AppendLiteral(", stream=");
				defaultInterpolatedStringHandler.AppendFormatted(streamId);
				defaultInterpolatedStringHandler.AppendLiteral(", userOpcode=");
				defaultInterpolatedStringHandler.AppendFormatted(userOpcode);
				defaultInterpolatedStringHandler.AppendLiteral(", index=");
				defaultInterpolatedStringHandler.AppendFormatted(index);
				defaultInterpolatedStringHandler.AppendLiteral("/");
				defaultInterpolatedStringHandler.AppendFormatted(count);
				defaultInterpolatedStringHandler.AppendLiteral(", segmentLen=");
				defaultInterpolatedStringHandler.AppendFormatted(segment.Length);
				defaultInterpolatedStringHandler.AppendLiteral(", totalPayload=");
				defaultInterpolatedStringHandler.AppendFormatted(totalPayloadSize);
				defaultInterpolatedStringHandler.AppendLiteral(", payloadLen=");
				payload = ctx.Payload;
				defaultInterpolatedStringHandler.AppendFormatted(payload.Length);
				logger.VeryDebug(defaultInterpolatedStringHandler.ToStringAndClear(), 1);
				byte[] completed;
				if (Crc32.HashToUInt32(segment) != segmentCrc)
				{
					RitsuLibSidecarRepeatedWarningLog.Warn($"chunk-crc-mismatch:sender={ctx.SenderNetId}:stream={streamId}:op={userOpcode}", "[Sidecar] Chunk segment CRC mismatch; drop.");
				}
				else if (!Chunks.TryIngest(ctx.SenderNetId, userOpcode, streamId, index, count, totalPayloadSize, segment, out completed) || completed == null)
				{
					RitsuLibSidecarChunkGapScheduler.ScheduleGapReport(Chunks, RunManager.Instance, ctx.SenderNetId, streamId, userOpcode, count);
					RitsuLibFramework.Logger.Debug($"[Sidecar] Chunk gap report scheduled sender={ctx.SenderNetId}, stream={streamId}, index={index}/{count}", 1);
				}
				else
				{
					RitsuLibSidecarChunkGapScheduler.Cancel(ctx.SenderNetId, streamId);
					byte[] array = new byte[8];
					RitsuLibSidecarChunkGapBinary.WriteReassemblyDone(array.AsSpan(), streamId);
					RitsuLibSidecarControlPeerSend.SendToNetPeer(RunManager.Instance, ctx.SenderNetId, 20uL, array);
					RitsuLibFramework.Logger.Debug($"[Sidecar] Chunk reassembled sender={ctx.SenderNetId}, stream={streamId}, userOpcode={userOpcode}, totalPayload={completed.Length}", 1);
					RitsuLibSidecarEnvelope.ParsedEnvelope envelope = new RitsuLibSidecarEnvelope.ParsedEnvelope(ctx.Envelope.WireFormatVersion, ctx.Envelope.Flags, userOpcode, ReadOnlyMemory<byte>.Empty, completed);
					RitsuLibSidecarBus.Dispatch(new RitsuLibSidecarDispatchContext(ctx.SenderNetId, ctx.TransferMode, ctx.Channel, ctx.IsHostIngest, envelope));
				}
			}
			catch (Exception ex)
			{
				RitsuLibSidecarRepeatedWarningLog.Warn("chunk-frame-exception:" + ex.GetType().FullName + ":" + ex.Message, "[Sidecar] Chunk frame: " + ex.Message);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Binary codec for one message type and opcode.</para>
	///     <para xml:lang="zh-CN">用于一种消息类型和操作码的二进制编解码器。</para>
	/// </summary>
	public interface IRitsuLibSidecarMessageCodec<T> where T : notnull
	{
		/// <summary>
		///     <para xml:lang="en">
		///         User or control <c>ulong</c> opcode; must match the <see cref="T:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBus" />
		///         registration.
		///     </para>
