			}
			return new Subscription(delegate
			{
				using (Gate.EnterScope())
				{
					if (Registrations.TryGetValue(opcode, out RegistrationBase value) && value is Registration<T> registration)
					{
						registration.Handlers.Remove(handler);
					}
				}
			});
		}

		/// <summary>
