	/// <summary>
	///     <para xml:lang="en">
	///         Provides the entry point that prepares RitsuLib's built-in multiplayer features.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供用于准备 RitsuLib 内置多人功能的入口。
	///     </para>
	/// </summary>
	public static class RitsuLibSidecarProtocol
	{
		private static readonly Lock Gate = new Lock();

		private static int _registered;

		private static int _registering;

		/// <summary>
		///     <para xml:lang="en">
		///         Prepares RitsuLib's built-in multiplayer support, including synchronized mod interactions and
		///         optional developer-tool changes. Repeated calls are safe.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         准备 RitsuLib 的内置多人支持，包括同步的模组交互和可选的开发者工具修改；可安全重复调用。
		///     </para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         This method is safe to call repeatedly or reentrantly. A concurrent call may return before another
		///         call finishes; if preparation fails, a later call may retry.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         此方法可安全重复调用或重入调用。并发调用可能会在另一调用完成前返回；准备失败后，后续调用可再次尝试。
		///     </para>
		/// </remarks>
		public static void EnsureDefaultHandlers()
		{
			if (Volatile.Read(in _registered) != 0 || Volatile.Read(in _registering) != 0)
			{
				return;
			}
			using (Gate.EnterScope())
			{
				if (_registered != 0 || _registering != 0)
				{
					return;
				}
				Volatile.Write(ref _registering, 1);
				try
				{
					RitsuLibSidecarSessionManager.EnsureProvidersBootstrapped();
					RitsuLibSidecarBuiltInHandlers.Register();
					RitsuLibSidecarSyncMessages.RegisterBuiltInHandler();
					RitsuLibSidecarEndpointProtocol.EnsureRegistered();
					ModRightClickRegistry.RegisterBuiltInSyncDescriptors();
					RitsuDebugActionProtocol.EnsureHandlersRegistered();
					RitsuLibSidecarNetworkingLifecycle.EnsureHooksInstalled();
					RitsuLibSidecarRequiredCapabilities.RegisterRequiredCapability("ritsulib:sidecar_core_supported", RitsuLibSidecarSessionManager.CanSendToPeer);
					RitsuLibSidecarRequiredCapabilities.RegisterRequiredCapability("ritsulib:managed_net_actions", (ulong peerNetId) => RitsuLibSidecarSessionManager.TryGetPeerFeatures(peerNetId, out var features) && (features & RitsuLibSidecarPeerFeatures.ManagedNetActions) != 0);
					Volatile.Write(ref _registered, 1);
				}
				finally
				{
					Volatile.Write(ref _registering, 0);
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Sidecar demultiplexing runs inside Harmony prefixes on the host and client receive entry points.
	///         <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBus.Dispatch(STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDispatchContext@)" /> therefore uses the receive callback's threading model,
	///         which is not documented as the Godot main thread.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         Sidecar 多路分解在主机与客户端接收入口的 Harmony 前缀中运行。
	///         因此 <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBus.Dispatch(STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDispatchContext@)" /> 使用接收回调的线程模型，
	///         而该线程未被记录为 Godot 主线程。
	///     </para>
	/// </summary>
	internal static class RitsuLibSidecarReceivePipeline
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Returns <see langword="true" /> when vanilla
		///         <see cref="T:MegaCrit.Sts2.Core.Multiplayer.NetMessageBus" /> must not process this packet.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         游戏原版 <see cref="T:MegaCrit.Sts2.Core.Multiplayer.NetMessageBus" /> 不应处理此数据包时，
		///         返回 <see langword="true" />。
		///     </para>
		/// </summary>
		internal static bool ShouldSuppressVanillaDeserialize(INetGameService netService, ulong senderId, byte[] packetBytes, NetTransferMode mode, int channel, bool isHostIngest)
		{
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			RitsuLibSidecarProtocol.EnsureDefaultHandlers();
			if (!RitsuLibSidecarWire.MatchesMagic(packetBytes))
			{
				return false;
			}
			RitsuLibSidecarEnvelope.ParseOutcome parseOutcome = RitsuLibSidecarEnvelope.TryParse(packetBytes, out var parsed);
			if (parseOutcome != RitsuLibSidecarEnvelope.ParseOutcome.Ok)
			{
				RitsuLibSidecarNetTrace.WarnEnvelopeRejected(parseOutcome, packetBytes.Length, channel);
				return true;
			}
			RitsuLibSidecarDispatchContext ctx = new RitsuLibSidecarDispatchContext(senderId, mode, channel, isHostIngest, parsed);
			RitsuLibSidecarTrafficCounters.AddIncoming(packetBytes.Length, ctx.Payload.Length);
			RitsuLibSidecarChecksumDiagnostics.EnsureSubscribed();
			RitsuLibSidecarPacketLog.IncomingParsed(in ctx);
			if (RitsuLibSidecarSync.TryBufferIncoming(netService, in ctx))
			{
				return true;
			}
			RitsuLibSidecarBus.Dispatch(in ctx);
			return true;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defers work to the Godot scene-tree main loop through <see cref="M:Godot.Callable.CallDeferred(Godot.Variant[])" /> and provides
	///         continuation helpers for Sidecar <see cref="T:System.Threading.Tasks.Task" /> results.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过 <see cref="M:Godot.Callable.CallDeferred(Godot.Variant[])" /> 将处理延后到 Godot 场景树主循环，
	///         并为 Sidecar <see cref="T:System.Threading.Tasks.Task" /> 结果提供延续方法。
	///     </para>
	/// </summary>
	public static class RitsuLibSidecarGodotMainLoopScheduling
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Queues <paramref name="action" /> on the Godot main loop when a <see cref="T:Godot.SceneTree" /> is
		///         available.
		///     </para>
		///     <para xml:lang="zh-CN"><see cref="T:Godot.SceneTree" /> 可用时，将 <paramref name="action" /> 排入 Godot 主循环。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when the delegate was queued; <see langword="false" /> when the main loop is
		///         unavailable.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         委托已排队时为 <see langword="true" />；主循环不可用时为 <see langword="false" />。
		///     </para>
		/// </returns>
		public static bool TryPostToMainLoop(Action action)
		{
			//IL_001a: Unknown result type (might be due to invalid IL or missing references)
			//IL_001f: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(action, "action");
			if (!(Engine.GetMainLoop() is SceneTree))
			{
				return false;
			}
			Callable val = Callable.From(action);
			((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         After <paramref name="task" /> completes, completes the returned task on the Godot main loop when
		///         possible; otherwise completes it on the thread-pool continuation.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         <paramref name="task" /> 完成后，尽可能在 Godot 主循环上完成返回的任务；
		///         否则在线程池延续中完成。
		///     </para>
		/// </summary>
		public static Task ContinueOnGodotMainLoopAsync(this Task task)
		{
			return task.ContinueWith(delegate(Task t)
			{
				TaskCompletionSource tcs = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
				if (!TryPostToMainLoop(Complete))
				{
					Complete();
				}
				return tcs.Task;
				void Complete()
				{
					if (t.IsFaulted)
					{
						Exception ex = t.Exception?.GetBaseException() ?? t.Exception;
						if (ex != null)
						{
							tcs.TrySetException(ex);
						}
						else
						{
							tcs.TrySetException(new InvalidOperationException("Sidecar task faulted."));
						}
					}
					else if (t.IsCanceled)
					{
						tcs.TrySetCanceled();
					}
					else
					{
						tcs.TrySetResult();
					}
				}
			}, CancellationToken.None, TaskContinuationOptions.RunContinuationsAsynchronously, TaskScheduler.Default).Unwrap();
		}

		/// <inheritdoc cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarGodotMainLoopScheduling.ContinueOnGodotMainLoopAsync(System.Threading.Tasks.Task)" />
		public static Task<T> ContinueOnGodotMainLoopAsync<T>(this Task<T> task)
		{
			return task.ContinueWith(delegate(Task<T> t)
			{
				TaskCompletionSource<T> tcs = new TaskCompletionSource<T>(TaskCreationOptions.RunContinuationsAsynchronously);
				if (!TryPostToMainLoop(Complete))
				{
					Complete();
				}
				return tcs.Task;
				void Complete()
				{
					if (t.IsFaulted)
					{
						Exception ex = t.Exception?.GetBaseException() ?? t.Exception;
						if (ex != null)
						{
							tcs.TrySetException(ex);
						}
						else
						{
							tcs.TrySetException(new InvalidOperationException("Sidecar task faulted."));
						}
					}
					else if (t.IsCanceled)
					{
						tcs.TrySetCanceled();
					}
					else
					{
						tcs.TrySetResult(t.Result);
					}
				}
			}, CancellationToken.None, TaskContinuationOptions.RunContinuationsAsynchronously, TaskScheduler.Default).Unwrap();
		}
	}
