					RunLocationTargetedMessageBuffer runLocationTargetedBuffer = instance.RunLocationTargetedBuffer;
					location = ((runLocationTargetedBuffer != null) ? new RunLocation?(runLocationTargetedBuffer.CurrentLocation) : ((RunLocation?)null));
				}
			}
			RitsuLibSidecarSyncMessageContext<T> context = new RitsuLibSidecarSyncMessageContext<T>(message, senderNetId, netService, isHostIngest, location);
			InvokeHandlerAsync(descriptor.Handle, context);
			return true;
		}

		private static void HandleIncoming(RitsuLibSidecarDispatchContext context)
		{
			//IL_01d9: Unknown result type (might be due to invalid IL or missing references)
			//IL_0240: Unknown result type (might be due to invalid IL or missing references)
			//IL_0277: Unknown result type (might be due to invalid IL or missing references)
			if (!RitsuLibSidecarSync.TryReadMessagePacket(context.Payload.Span, out var packet))
			{
				RitsuLibSidecarRepeatedWarningLog.Warn($"sync-malformed-packet:sender={context.SenderNetId}:ch={context.Channel}", "[SidecarSync] Rejected malformed sync message packet.");
				return;
			}
			RegistrationBase value;
			using (Gate.EnterScope())
			{
				Registrations.TryGetValue(packet.DescriptorOpcode, out value);
			}
			if (value == null)
			{
				RitsuLibSidecarRepeatedWarningLog.Warn($"sync-missing-descriptor:opcode={packet.DescriptorOpcode}:sender={context.SenderNetId}", $"[SidecarSync] No sync message descriptor registered for opcode {packet.DescriptorOpcode}.");
				return;
			}
			if (value.LocationTargeted && !packet.LocationTargeted)
			{
				RitsuLibSidecarRepeatedWarningLog.Warn($"sync-missing-location:opcode={packet.DescriptorOpcode}:sender={context.SenderNetId}", $"[SidecarSync] Sync message opcode {packet.DescriptorOpcode} missing required location.");
				return;
			}
			if (context.IsHostIngest)
			{
				packet = packet with
				{
					OriginalSenderNetId = context.SenderNetId
				};
			}
			if (RitsuLibSidecarSync.TryDeferForLocation(packet.LocationTargeted, packet.Location, context))
			{
				return;
			}
			if (context.IsHostIngest && packet.Route == RitsuLibSidecarSyncMessageRoute.ClientToHostAndBroadcast && value.ShouldBroadcast)
			{
				RunManager instance = RunManager.Instance;
				INetGameService obj = ((instance != null) ? instance.NetService : null);
				NetHostGameService val = (NetHostGameService)(object)((obj is NetHostGameService) ? obj : null);
				if (val != null)
				{
					byte[] array = RitsuLibSidecarSync.WriteMessagePacket(packet.DescriptorOpcode, context.SenderNetId, RitsuLibSidecarSyncMessageRoute.Direct, packet.LocationTargeted, packet.Location, packet.Payload);
					if (!RitsuLibSidecarSync.TryBroadcastToPeers(val, 32uL, array, context.SenderNetId, value.BroadcastScope, context.TransferMode, context.Channel, value.FailurePolicy))
					{
						RitsuLibFramework.Logger.ErrorNoTrace($"[SidecarSync] Required relay failed for sync message {value.ModuleId}/{value.MessageKey}; local handler suppressed.");
						return;
					}
				}
			}
			value.Dispatch(packet, context);
		}

		private static bool CanSendToPeer(ulong peerNetId)
		{
			return RitsuLibSidecarSessionManager.CanSendToPeer(peerNetId);
		}

		private static bool FailUnavailablePeer<T>(ulong peerNetId, RitsuLibSidecarSyncMessageDescriptor<T> descriptor)
		{
			if (descriptor.FailurePolicy == RitsuLibSidecarSyncFailurePolicy.Required)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[SidecarSync] Required sync message {descriptor.ModuleId}/{descriptor.MessageKey} cannot reach peer {peerNetId}; send suppressed.");
			}
			return false;
		}

		private static int ResolveChannel<T>(RitsuLibSidecarSyncMessageDescriptor<T> descriptor)
		{
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			return descriptor.Channel ?? NetTransferModeExtensions.ToChannelId(descriptor.Mode);
		}

		private static void ValidateDescriptorPolicy<T>(RitsuLibSidecarSyncMessageDescriptor<T> descriptor)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			if (!Enum.IsDefined<LogLevel>(descriptor.LogLevel))
			{
				throw new ArgumentOutOfRangeException("descriptor", descriptor.LogLevel, "Invalid log level.");
			}
			if (!Enum.IsDefined<NetTransferMode>(descriptor.Mode))
			{
				throw new ArgumentOutOfRangeException("descriptor", descriptor.Mode, "Invalid transfer mode.");
			}
			int? channel = descriptor.Channel;
			if (channel.HasValue && channel.GetValueOrDefault() < 0)
			{
				throw new ArgumentOutOfRangeException("descriptor", descriptor.Channel, "Channel cannot be negative.");
			}
			if (!Enum.IsDefined(descriptor.FailurePolicy))
			{
				throw new ArgumentOutOfRangeException("descriptor", descriptor.FailurePolicy, "Invalid sync failure policy.");
			}
			if (!Enum.IsDefined(descriptor.BroadcastScope))
			{
				throw new ArgumentOutOfRangeException("descriptor", descriptor.BroadcastScope, "Invalid sync broadcast scope.");
			}
		}

		internal static bool CanSendToAllTargetPeers(NetHostGameService host, ulong? excludePeerId, RitsuLibSidecarSyncBroadcastScope scope)
		{
			return TargetPeers(host, excludePeerId, scope).All(delegate(NetClientData peer)
			{
				//IL_0000: Unknown result type (might be due to invalid IL or missing references)
				return CanSendToPeer(peer.peerId);
			});
		}

		internal static IEnumerable<NetClientData> TargetPeers(NetHostGameService host, ulong? excludePeerId, RitsuLibSidecarSyncBroadcastScope scope)
		{
			return host.ConnectedPeers.Where(delegate(NetClientData peer)
			{
				//IL_0000: Unknown result type (might be due to invalid IL or missing references)
				//IL_0029: Unknown result type (might be due to invalid IL or missing references)
				return peer.peerId != excludePeerId && (scope == RitsuLibSidecarSyncBroadcastScope.AllConnectedPeers || peer.readyForBroadcasting);
			});
		}

		private static async Task InvokeHandlerAsync<T>(Func<RitsuLibSidecarSyncMessageContext<T>, Task> handler, RitsuLibSidecarSyncMessageContext<T> context)
		{
			try
			{
				await handler(context);
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[SidecarSync] Sync message handler failed: {value}");
			}
		}

		static RitsuLibSidecarSyncMessages()
		{
			//IL_001a: Unknown result type (might be due to invalid IL or missing references)
