			Gate = new Lock();
			Registrations = new Dictionary<ulong, RegistrationBase>();
			NetworkLogger = new Logger("RitsuLibSidecarSync", (LogType)1);
		}
	}
	internal static class RitsuLibSidecarChecksumDiagnostics
	{
		private static ChecksumTracker? _tracker;

		internal static void EnsureSubscribed()
		{
			RunManager instance = RunManager.Instance;
			ChecksumTracker val = ((instance != null) ? instance.ChecksumTracker : null);
			if (val != null && _tracker != val)
			{
				Unsubscribe();
				_tracker = val;
				_tracker.StateDiverged += OnClientStateDiverged;
			}
		}

		internal static void Unsubscribe()
		{
			if (_tracker != null)
			{
				_tracker.StateDiverged -= OnClientStateDiverged;
			}
			_tracker = null;
		}

		internal static void TryTriggerHostCoordinatedDump(ulong divergentPeerId, uint checksumId)
		{
			try
			{
				RunManager instance = RunManager.Instance;
				if (((instance != null) ? instance.NetService : null) is NetHostGameService && RitsuLibSidecarDiagnosticRelayGate.TryBeginHostSession(divergentPeerId, checksumId, 1, out var session))
				{
					byte[] array = RitsuLibSidecarDiagnosticPayload.BuildFanoutPayload(session);
					RitsuLibSidecarHighLevelSend.TrySendAsHostBroadcast(instance, 22uL, array, RitsuLibSidecarDeliverySemantics.StableSync);
					RitsuLibFramework.Logger.Debug($"[Sidecar] Host divergence relay fanout sent peer={divergentPeerId}, checksum={checksumId}, tag={session.Tag}, nonce={session.Nonce}.", 1);
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Sidecar] host divergence relay failed: " + ex.Message, 1);
			}
		}

		private static void OnClientStateDiverged(ulong _, NetFullCombatState __)
		{
			try
			{
				RitsuLibSidecarProtocol.EnsureDefaultHandlers();
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Sidecar] checksum divergence relay failed: " + ex.Message, 1);
			}
		}
	}
	internal static class RitsuLibSidecarDiagnosticPayload
	{
		internal const int FanoutPayloadSize = 30;

		internal static byte[] BuildFanoutPayload(RitsuLibSidecarDiagnosticRelaySession session)
		{
			byte[] array = new byte[30];
			BinaryPrimitives.WriteUInt64BigEndian(array.AsSpan(0, 8), session.OriginatingSenderNetId);
			BinaryPrimitives.WriteUInt16BigEndian(array.AsSpan(8, 2), session.Tag);
			BinaryPrimitives.WriteUInt32BigEndian(array.AsSpan(10, 4), session.ChecksumId);
			BinaryPrimitives.WriteUInt64BigEndian(array.AsSpan(14, 8), session.Nonce);
			BinaryPrimitives.WriteInt64BigEndian(array.AsSpan(22, 8), session.IssuedUnixMilliseconds);
			return array;
		}

		internal static bool TryParseFanout(ReadOnlySpan<byte> payload, out RitsuLibSidecarDiagnosticRelaySession session)
		{
			session = default(RitsuLibSidecarDiagnosticRelaySession);
			if (payload.Length != 30)
			{
				return false;
			}
			ulong originatingSenderNetId = BinaryPrimitives.ReadUInt64BigEndian(payload.Slice(0, 8));
			ushort tag = BinaryPrimitives.ReadUInt16BigEndian(payload.Slice(8, 2));
			uint checksumId = BinaryPrimitives.ReadUInt32BigEndian(payload.Slice(10, 4));
			ulong nonce = BinaryPrimitives.ReadUInt64BigEndian(payload.Slice(14, 8));
			long issuedUnixMilliseconds = BinaryPrimitives.ReadInt64BigEndian(payload.Slice(22, 8));
			session = new RitsuLibSidecarDiagnosticRelaySession(originatingSenderNetId, checksumId, tag, nonce, issuedUnixMilliseconds);
			return true;
		}
	}
	internal readonly record struct RitsuLibSidecarDiagnosticRelaySession(ulong OriginatingSenderNetId, uint ChecksumId, ushort Tag, ulong Nonce, long IssuedUnixMilliseconds);
	internal static class RitsuLibSidecarDiagnosticRelayGate
	{
		private readonly record struct RelaySessionKey(ulong OriginatingSenderNetId, uint ChecksumId, ushort Tag);

		private readonly record struct LocalSessionKey(ulong OriginatingSenderNetId, uint ChecksumId, ushort Tag, ulong Nonce);

		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<RelaySessionKey, RitsuLibSidecarDiagnosticRelaySession> HostSessions = new Dictionary<RelaySessionKey, RitsuLibSidecarDiagnosticRelaySession>();

		private static readonly Dictionary<ulong, List<DateTime>> HostPeerStarts = new Dictionary<ulong, List<DateTime>>();

		private static readonly List<DateTime> HostGlobalStarts = new List<DateTime>();

		private static readonly Dictionary<LocalSessionKey, DateTime> LocalDumpedSessions = new Dictionary<LocalSessionKey, DateTime>();

		private static readonly List<DateTime> LocalDumpTimes = new List<DateTime>();

		internal static bool TryBeginHostSession(ulong originatingSenderNetId, uint checksumId, ushort tag, out RitsuLibSidecarDiagnosticRelaySession session)
		{
			session = default(RitsuLibSidecarDiagnosticRelaySession);
			if (!IsKnownTag(tag))
			{
				return false;
			}
			DateTime utcNow = DateTime.UtcNow;
			using (Gate.EnterScope())
			{
				Sweep_NoLock(utcNow);
				RelaySessionKey key = new RelaySessionKey(originatingSenderNetId, checksumId, tag);
				if (HostSessions.TryGetValue(key, out session))
				{
					return false;
				}
				if (IsHostRateLimited_NoLock(originatingSenderNetId, utcNow))
				{
					return false;
				}
				session = new RitsuLibSidecarDiagnosticRelaySession(originatingSenderNetId, checksumId, tag, CreateNonce(), new DateTimeOffset(utcNow).ToUnixTimeMilliseconds());
				HostSessions[key] = session;
				AddHostStart_NoLock(originatingSenderNetId, utcNow);
				return true;
			}
		}

		internal static bool TryValidateRequest(ulong senderNetId)
		{
			DateTime utcNow = DateTime.UtcNow;
			using (Gate.EnterScope())
			{
				Sweep_NoLock(utcNow);
				return HostSessions.Values.Any((RitsuLibSidecarDiagnosticRelaySession session) => session.OriginatingSenderNetId == senderNetId);
			}
		}

		internal static bool TryValidateFanout(INetGameService? netService, ulong senderNetId, RitsuLibSidecarDiagnosticRelaySession session)
		{
			NetClientGameService val = (NetClientGameService)(object)((netService is NetClientGameService) ? netService : null);
			if (val == null || senderNetId != val.HostNetId)
			{
				return false;
			}
			if (!IsKnownTag(session.Tag))
			{
				return false;
			}
			if (!TryGetIssuedUtc(session, out var issued))
			{
				return false;
			}
			DateTime utcNow = DateTime.UtcNow;
			if (issued - utcNow > RitsuLibSidecarDiagnosticPolicy.FanoutFutureTolerance)
			{
				return false;
			}
			if (utcNow - issued <= RitsuLibSidecarDiagnosticPolicy.RelaySessionTtl)
			{
				return RitsuLibSidecarSessionManager.CanSendToPeer(senderNetId);
			}
			return false;
		}

		internal static bool TryConsumeLocalDump(RitsuLibSidecarDiagnosticRelaySession session)
		{
			DateTime utcNow = DateTime.UtcNow;
			using (Gate.EnterScope())
			{
				Sweep_NoLock(utcNow);
				LocalSessionKey key = new LocalSessionKey(session.OriginatingSenderNetId, session.ChecksumId, session.Tag, session.Nonce);
				if (LocalDumpedSessions.ContainsKey(key))
				{
					return false;
				}
				if (LocalDumpTimes.Count >= 8)
				{
					RitsuLibSidecarRepeatedWarningLog.Warn("diagnostic-relay-local-dump-rate-limit", "[Sidecar] Diagnostic relay local dump suppressed by rate limit.");
					return false;
				}
				LocalDumpedSessions[key] = utcNow;
				LocalDumpTimes.Add(utcNow);
				return true;
			}
		}

		private static bool IsHostRateLimited_NoLock(ulong peerNetId, DateTime now)
		{
			if (HostGlobalStarts.Count >= 8)
			{
				RitsuLibSidecarRepeatedWarningLog.Warn("diagnostic-relay-host-global-rate-limit", "[Sidecar] Diagnostic relay host session suppressed by global rate limit.");
				return true;
			}
			if (!HostPeerStarts.TryGetValue(peerNetId, out List<DateTime> value))
			{
				return false;
			}
			if (value.Count < 2)
			{
				return false;
			}
			RitsuLibSidecarRepeatedWarningLog.Warn($"diagnostic-relay-host-peer-rate-limit:{peerNetId}", $"[Sidecar] Diagnostic relay host session suppressed by peer rate limit peer={peerNetId}.");
			return true;
		}

		private static void AddHostStart_NoLock(ulong peerNetId, DateTime now)
		{
			if (!HostPeerStarts.TryGetValue(peerNetId, out List<DateTime> value))
			{
				value = new List<DateTime>();
				HostPeerStarts[peerNetId] = value;
			}
			value.Add(now);
			HostGlobalStarts.Add(now);
		}

		private static bool IsKnownTag(ushort tag)
		{
			return tag == 1;
		}

		private static ulong CreateNonce()
		{
			Span<byte> obj = stackalloc byte[8];
			RandomNumberGenerator.Fill(obj);
			return BinaryPrimitives.ReadUInt64BigEndian(obj);
		}

		private static void Sweep_NoLock(DateTime now)
		{
			SweepList_NoLock(HostGlobalStarts, now, RitsuLibSidecarDiagnosticPolicy.RelayRateWindow);
			SweepList_NoLock(LocalDumpTimes, now, RitsuLibSidecarDiagnosticPolicy.LocalDumpRateWindow);
			KeyValuePair<ulong, List<DateTime>>[] array = HostPeerStarts.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				KeyValuePair<ulong, List<DateTime>> keyValuePair = array[i];
				var (key, list2) = keyValuePair;
				SweepList_NoLock(list2, now, RitsuLibSidecarDiagnosticPolicy.RelayRateWindow);
				if (list2.Count == 0)
				{
					HostPeerStarts.Remove(key);
				}
			}
			KeyValuePair<RelaySessionKey, RitsuLibSidecarDiagnosticRelaySession>[] array2 = HostSessions.ToArray();
			for (int i = 0; i < array2.Length; i++)
			{
				KeyValuePair<RelaySessionKey, RitsuLibSidecarDiagnosticRelaySession> keyValuePair3 = array2[i];
				var (key2, session) = keyValuePair3;
				if (!TryGetIssuedUtc(session, out var issued) || now - issued > RitsuLibSidecarDiagnosticPolicy.RelaySessionTtl)
				{
					HostSessions.Remove(key2);
				}
			}
			KeyValuePair<LocalSessionKey, DateTime>[] array3 = LocalDumpedSessions.ToArray();
			for (int i = 0; i < array3.Length; i++)
			{
				KeyValuePair<LocalSessionKey, DateTime> keyValuePair5 = array3[i];
				var (key3, dateTime2) = keyValuePair5;
				if (now - dateTime2 > RitsuLibSidecarDiagnosticPolicy.LocalDumpRateWindow)
				{
					LocalDumpedSessions.Remove(key3);
				}
			}
		}

		private static bool TryGetIssuedUtc(RitsuLibSidecarDiagnosticRelaySession session, out DateTime issued)
		{
			try
			{
				issued = DateTimeOffset.FromUnixTimeMilliseconds(session.IssuedUnixMilliseconds).UtcDateTime;
				return true;
			}
			catch (ArgumentOutOfRangeException)
			{
				issued = default(DateTime);
				return false;
			}
		}

		private static void SweepList_NoLock(List<DateTime> values, DateTime now, TimeSpan retention)
		{
			for (int num = values.Count - 1; num >= 0; num--)
			{
				if (now - values[num] > retention)
				{
					values.RemoveAt(num);
				}
			}
		}
	}
