	internal sealed class RitsuLibSidecarNativeTrailerValidationRoute : IRitsuLibSidecarCapabilityValidationRoute
	{
		public string Name => "native_trailer";

		public int Order => 50;

		public bool IsAvailable(INetGameService netService)
		{
			return true;
		}

		public void PublishLocalEvidence(INetGameService netService)
		{
		}

		public RitsuLibSidecarPeerReachability? TryResolve(INetGameService netService, ulong peerNetId)
		{
			if (!RitsuLibSidecarNativeTrailerEvidence.HasCurrentSessionEvidence(peerNetId))
			{
				return null;
			}
			return RitsuLibSidecarPeerReachability.Supported;
		}
	}
	internal sealed class RitsuLibSidecarSteamLobbyValidationRoute : IRitsuLibSidecarCapabilityValidationRoute
	{
		public string Name => "steam_lobby_member_data";

		public int Order => 100;

		public bool IsAvailable(INetGameService netService)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Invalid comparison between Unknown and I4
			if ((int)netService.Platform != 1)
			{
				return false;
			}
			if (!ulong.TryParse(netService.GetRawLobbyIdentifier(), out var result))
			{
				return false;
			}
			if (!RitsuLibSteamworks.TryGetNumLobbyMembers(result, out var count))
			{
				return false;
			}
			if (count <= 0)
			{
				return false;
			}
			bool contains;
			return RitsuLibSteamworks.TryLobbyContainsMember(result, netService.NetId, out contains) & contains;
		}

		public void PublishLocalEvidence(INetGameService netService)
		{
			if (TryGetLobbyId(netService, out var lobbyId) && RitsuLibSteamworks.CanPublishLobbyMemberData(lobbyId, netService.NetId))
			{
				RitsuLibSteamworks.TrySetLobbyMemberData(lobbyId, "ritsulib_sidecar", "1");
			}
		}

		public RitsuLibSidecarPeerReachability? TryResolve(INetGameService netService, ulong peerNetId)
		{
			if (!TryGetLobbyId(netService, out var lobbyId))
			{
				return null;
			}
			if (!RitsuLibSteamworks.TryGetLobbyMemberData(lobbyId, peerNetId, "ritsulib_sidecar", out string value))
			{
				return null;
			}
			if (string.IsNullOrEmpty(value))
			{
				return null;
			}
			return (value == "1") ? RitsuLibSidecarPeerReachability.Supported : RitsuLibSidecarPeerReachability.Unsupported;
		}

		private static bool TryGetLobbyId(INetGameService netService, out ulong lobbyId)
		{
			lobbyId = 0uL;
			if (!TryReadSteamLobbyId(netService, out var lobbyIdRaw))
			{
				return false;
			}
			lobbyId = lobbyIdRaw;
			return true;
		}

		private static bool TryReadSteamLobbyId(INetGameService netService, out ulong lobbyIdRaw)
		{
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_000b: Invalid comparison between Unknown and I4
			lobbyIdRaw = 0uL;
			if ((int)netService.Platform != 1)
			{
				return false;
			}
			if (!SteamInitializer.Initialized)
			{
				return false;
			}
			if (!ulong.TryParse(netService.GetRawLobbyIdentifier(), out lobbyIdRaw))
			{
				return false;
			}
			if (lobbyIdRaw == 0L)
			{
				return false;
			}
			if (RitsuLibSteamworks.TryGetNumLobbyMembers(lobbyIdRaw, out var count))
			{
				return count > 0;
			}
			return false;
		}
	}
	internal static class RitsuLibSidecarCapabilityHints
	{
		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<ulong, RitsuLibSidecarPeerReachability> Hints = new Dictionary<ulong, RitsuLibSidecarPeerReachability>();

		public static void SetHint(ulong peerNetId, RitsuLibSidecarPeerReachability reachability)
		{
			using (Gate.EnterScope())
			{
				Hints[peerNetId] = reachability;
			}
		}

		public static RitsuLibSidecarPeerReachability? TryGetHint(ulong peerNetId)
		{
			using (Gate.EnterScope())
			{
				RitsuLibSidecarPeerReachability valueOrDefault = Hints.GetValueOrDefault(peerNetId, RitsuLibSidecarPeerReachability.Unknown);
				if (valueOrDefault == RitsuLibSidecarPeerReachability.Unknown)
				{
					return null;
				}
				return valueOrDefault;
			}
		}
	}
	internal static class RitsuLibSidecarNativeTrailerEvidence
	{
		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<ulong, long> SupportedEpochByPeer = new Dictionary<ulong, long>();

		public static bool TryAppendLocalTrailer(ref byte[] packetBytes, ref int length)
		{
			if (length <= 0 || packetBytes.Length < length)
			{
				return false;
			}
			Span<byte> span = packetBytes.AsSpan(0, length);
			if (RitsuLibSidecarWire.MatchesMagic(span))
			{
				return false;
			}
			if (TryReadTrailer(span, out var _))
			{
				return false;
			}
			byte[] array = new byte[length + RitsuLibSidecarNativeTrailerLayout.TrailerSize];
			span.CopyTo(array);
			WriteTrailer(array.AsSpan(length), span);
			packetBytes = array;
			length = array.Length;
			return true;
		}

		public static void ObserveInbound(ulong senderId, byte[] packetBytes)
		{
			if (packetBytes.Length >= RitsuLibSidecarNativeTrailerLayout.TrailerSize && TryReadTrailer(packetBytes, out var flags) && (flags & 1) != 0)
			{
				long epoch = RitsuLibSidecarSessionManager.Epoch;
				using (Gate.EnterScope())
				{
					SupportedEpochByPeer[senderId] = epoch;
				}
				RitsuLibSidecarSessionManager.RefreshReachabilityFromProviders(senderId);
			}
		}

		public static bool HasCurrentSessionEvidence(ulong peerNetId)
		{
			long epoch = RitsuLibSidecarSessionManager.Epoch;
			using (Gate.EnterScope())
			{
				long value;
				return SupportedEpochByPeer.TryGetValue(peerNetId, out value) && value == epoch;
			}
		}

		private static void WriteTrailer(Span<byte> destination, ReadOnlySpan<byte> payload)
		{
			RitsuLibSidecarNativeTrailerLayout.HeaderSignature.CopyTo(destination.Slice(0, RitsuLibSidecarNativeTrailerLayout.SignatureSize));
			BinaryPrimitives.WriteUInt16BigEndian(destination.Slice(RitsuLibSidecarNativeTrailerLayout.VersionOffset, 2), 1);
			BinaryPrimitives.WriteUInt16BigEndian(destination.Slice(RitsuLibSidecarNativeTrailerLayout.FlagsOffset, 2), 1);
			BinaryPrimitives.WriteUInt32BigEndian(destination.Slice(RitsuLibSidecarNativeTrailerLayout.PayloadLengthOffset, 4), (uint)payload.Length);
			BinaryPrimitives.WriteUInt32BigEndian(destination.Slice(RitsuLibSidecarNativeTrailerLayout.PayloadCrc32Offset, 4), Crc32.HashToUInt32(payload));
			RitsuLibSidecarNativeTrailerLayout.FooterSignature.CopyTo(destination.Slice(RitsuLibSidecarNativeTrailerLayout.FooterSignatureOffset, RitsuLibSidecarNativeTrailerLayout.FooterSignatureSize));
		}

		private static bool TryReadTrailer(ReadOnlySpan<byte> packetBytes, out ushort flags)
		{
			flags = 0;
			if (packetBytes.Length < RitsuLibSidecarNativeTrailerLayout.TrailerSize)
			{
				return false;
			}
			if (!TryLocateTrailerStart(packetBytes, out var trailerStart))
			{
				return false;
			}
			ReadOnlySpan<byte> readOnlySpan = packetBytes.Slice(trailerStart, RitsuLibSidecarNativeTrailerLayout.TrailerSize);
			if (!readOnlySpan.Slice(0, RitsuLibSidecarNativeTrailerLayout.SignatureSize).SequenceEqual(RitsuLibSidecarNativeTrailerLayout.HeaderSignature))
			{
				return false;
			}
			if (BinaryPrimitives.ReadUInt16BigEndian(readOnlySpan.Slice(RitsuLibSidecarNativeTrailerLayout.VersionOffset, 2)) != 1)
			{
				return false;
			}
			if (!readOnlySpan.Slice(RitsuLibSidecarNativeTrailerLayout.FooterSignatureOffset, RitsuLibSidecarNativeTrailerLayout.FooterSignatureSize).SequenceEqual(RitsuLibSidecarNativeTrailerLayout.FooterSignature))
			{
				return false;
			}
			flags = BinaryPrimitives.ReadUInt16BigEndian(readOnlySpan.Slice(RitsuLibSidecarNativeTrailerLayout.FlagsOffset, 2));
			uint num = BinaryPrimitives.ReadUInt32BigEndian(readOnlySpan.Slice(RitsuLibSidecarNativeTrailerLayout.PayloadLengthOffset, 4));
			if (trailerStart != (int)num)
			{
				return false;
			}
			uint num2 = BinaryPrimitives.ReadUInt32BigEndian(readOnlySpan.Slice(RitsuLibSidecarNativeTrailerLayout.PayloadCrc32Offset, 4));
			return Crc32.HashToUInt32(packetBytes.Slice(0, trailerStart)) == num2;
		}

		private static bool TryLocateTrailerStart(ReadOnlySpan<byte> packetBytes, out int trailerStart)
		{
			trailerStart = -1;
			int footerSignatureSize = RitsuLibSidecarNativeTrailerLayout.FooterSignatureSize;
			int footerSignatureOffset = RitsuLibSidecarNativeTrailerLayout.FooterSignatureOffset;
			int num = RitsuLibSidecarNativeTrailerLayout.TrailerSize - footerSignatureSize;
			for (int num2 = packetBytes.Length - footerSignatureSize; num2 >= num; num2--)
			{
				if (packetBytes.Slice(num2, footerSignatureSize).SequenceEqual(RitsuLibSidecarNativeTrailerLayout.FooterSignature))
				{
					int num3 = num2 - footerSignatureOffset;
					if (num3 >= 0 && num3 + RitsuLibSidecarNativeTrailerLayout.TrailerSize <= packetBytes.Length)
					{
						trailerStart = num3;
						return true;
					}
				}
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Describes the terminal outcome of a bulk-stream transfer.</para>
	///     <para xml:lang="zh-CN">描述批量流传输的最终结果。</para>
	/// </summary>
	public enum RitsuLibSidecarBulkTransferStatus
	{
		/// <summary>
		///     <para xml:lang="en">The complete byte stream passed end-to-end integrity verification.</para>
		///     <para xml:lang="zh-CN">完整字节流已通过端到端完整性校验。</para>
		/// </summary>
		Completed,
		/// <summary>
		///     <para xml:lang="en">The remote endpoint declined the offered stream.</para>
		///     <para xml:lang="zh-CN">远端端点拒绝了所提供的流。</para>
		/// </summary>
		Rejected,
		/// <summary>
		///     <para xml:lang="en">The caller or remote participant canceled the transfer.</para>
		///     <para xml:lang="zh-CN">调用方或远端参与方取消了传输。</para>
		/// </summary>
		Canceled,
		/// <summary>
		///     <para xml:lang="en">The transfer exceeded its acknowledgement, retry, or idle-time limit.</para>
		///     <para xml:lang="zh-CN">传输超过了确认、重试或空闲时间限制。</para>
		/// </summary>
		TimedOut,
		/// <summary>
		///     <para xml:lang="en">The endpoint route or multiplayer session became unavailable.</para>
		///     <para xml:lang="zh-CN">端点路由或多人会话变得不可用。</para>
		/// </summary>
		Disconnected,
		/// <summary>
		///     <para xml:lang="en">The endpoint registration was disposed during the transfer.</para>
		///     <para xml:lang="zh-CN">传输期间端点注册被释放。</para>
		/// </summary>
		EndpointDisposed,
		/// <summary>
		///     <para xml:lang="en">The source stream could not supply the declared byte count.</para>
		///     <para xml:lang="zh-CN">源流无法提供声明的字节数。</para>
		/// </summary>
		SourceFailed,
		/// <summary>
		///     <para xml:lang="en">The destination stream failed while accepting data.</para>
		///     <para xml:lang="zh-CN">目标流在接收数据时失败。</para>
		/// </summary>
		DestinationFailed,
		/// <summary>
		///     <para xml:lang="en">The final SHA-256 digest did not match the received bytes.</para>
		///     <para xml:lang="zh-CN">最终 SHA-256 摘要与收到的字节不匹配。</para>
		/// </summary>
		IntegrityFailed,
		/// <summary>
		///     <para xml:lang="en">A local or remote bounded resource limit rejected the transfer.</para>
		///     <para xml:lang="zh-CN">本地或远端的有界资源限制拒绝了传输。</para>
		/// </summary>
		ResourceLimit,
		/// <summary>
		///     <para xml:lang="en">Malformed or contradictory stream frames terminated the transfer.</para>
		///     <para xml:lang="zh-CN">格式错误或相互矛盾的流帧终止了传输。</para>
		/// </summary>
		ProtocolError
	}
	/// <summary>
	///     <para xml:lang="en">Identifies the local direction reported by bulk-stream progress.</para>
	///     <para xml:lang="zh-CN">标识批量流进度所报告的本地方向。</para>
	/// </summary>
	public enum RitsuLibSidecarBulkTransferDirection
	{
		/// <summary>
		///     <para xml:lang="en">Bytes are being sent from the local source.</para>
		///     <para xml:lang="zh-CN">字节正从本地源发送。</para>
		/// </summary>
		Sending = 1,
		/// <summary>
		///     <para xml:lang="en">Bytes are being committed to the local destination.</para>
		///     <para xml:lang="zh-CN">字节正写入本地目标。</para>
		/// </summary>
		Receiving
	}
	/// <summary>
	///     <para xml:lang="en">Immutable optional metadata carried by a bulk-stream offer.</para>
	///     <para xml:lang="zh-CN">批量流提议所携带的不可变可选元数据。</para>
	/// </summary>
	public sealed class RitsuLibSidecarBulkStreamMetadata
	{
		/// <summary>
		///     <para xml:lang="en">Optional opaque display name.</para>
		///     <para xml:lang="zh-CN">可选的不透明显示名称。</para>
		/// </summary>
		public string? Name { get; }

		/// <summary>
		///     <para xml:lang="en">Optional media type such as <c>image/png</c>.</para>
		///     <para xml:lang="zh-CN">可选媒体类型，例如 <c>image/png</c>。</para>
		/// </summary>
		public string? ContentType { get; }

		/// <summary>
		///     <para xml:lang="en">Creates validated, opaque stream metadata.</para>
		///     <para xml:lang="zh-CN">创建经过验证的不透明流元数据。</para>
		/// </summary>
		/// <param name="name">
		///     <para xml:lang="en">
		///         Optional display name occupying at most 255 UTF-8 bytes. It is never interpreted as a filesystem path;
		///         receivers must choose and validate their own destination path.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选显示名称，UTF-8 长度最多为 255 字节。它绝不会被解释为文件系统路径；接收方必须自行选择并
		///         验证目标路径。
		///     </para>
		/// </param>
		/// <param name="contentType">
		///     <para xml:lang="en">Optional visible-ASCII media type occupying at most 127 UTF-8 bytes.</para>
		///     <para xml:lang="zh-CN">可选的可见 ASCII 媒体类型，UTF-8 长度最多为 127 字节。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">A value exceeds its encoded limit or contains a forbidden control character.</para>
		///     <para xml:lang="zh-CN">值超过编码限制，或包含禁止的控制字符。</para>
		/// </exception>
		public RitsuLibSidecarBulkStreamMetadata(string? name = null, string? contentType = null)
		{
			ValidateName(name, "name");
			ValidateContentType(contentType, "contentType");
			Name = (string.IsNullOrEmpty(name) ? null : name);
			ContentType = (string.IsNullOrEmpty(contentType) ? null : contentType);
		}

		private static void ValidateName(string? value, string parameterName)
		{
			if (value == null || (Encoding.UTF8.GetByteCount(value) <= 255 && !value.Any(char.IsControl)))
			{
				return;
			}
			throw new ArgumentException("Bulk stream name is too long or contains a control character.", parameterName);
		}

		private static void ValidateContentType(string? value, string parameterName)
		{
			if (value == null || (Encoding.UTF8.GetByteCount(value) <= 127 && !value.Any((char character) => (character < '!' || character > '~') ? true : false)))
			{
				return;
			}
			throw new ArgumentException("Bulk stream content type is too long or contains a non-visible ASCII character.", parameterName);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Defines bounded local resource and timeout policy for one bulk endpoint.</para>
	///     <para xml:lang="zh-CN">定义一个批量端点的本地有界资源与超时策略。</para>
	/// </summary>
	public sealed class RitsuLibSidecarBulkStreamOptions
	{
		/// <summary>
		///     <para xml:lang="en">Maximum declared length accepted or sent by this endpoint.</para>
		///     <para xml:lang="zh-CN">此端点接受或发送的声明长度上限。</para>
		/// </summary>
		public long MaxStreamBytes { get; }

		/// <summary>
		///     <para xml:lang="en">Preferred logical data bytes in each bulk data frame.</para>
		///     <para xml:lang="zh-CN">每个批量数据帧的首选逻辑数据字节数。</para>
		/// </summary>
		public int PreferredChunkBytes { get; }

		/// <summary>
		///     <para xml:lang="en">Maximum bytes accepted before cumulative acknowledgement.</para>
		///     <para xml:lang="zh-CN">发送累计确认前最多接受的字节数。</para>
		/// </summary>
		public int ReceiveWindowBytes { get; }

		/// <summary>
		///     <para xml:lang="en">Per-endpoint concurrent inbound stream limit.</para>
		///     <para xml:lang="zh-CN">单端点并发入站流上限。</para>
		/// </summary>
		public int MaxConcurrentInboundStreams { get; }

		/// <summary>
		///     <para xml:lang="en">Per-endpoint concurrent outbound stream limit.</para>
		///     <para xml:lang="zh-CN">单端点并发出站流上限。</para>
		/// </summary>
		public int MaxConcurrentOutboundStreams { get; }

		/// <summary>
		///     <para xml:lang="en">Time before retransmitting unacknowledged state.</para>
		///     <para xml:lang="zh-CN">重传未确认状态前的等待时间。</para>
		/// </summary>
		public TimeSpan AcknowledgementTimeout { get; }

		/// <summary>
		///     <para xml:lang="en">Maximum duration without valid transfer progress.</para>
		///     <para xml:lang="zh-CN">没有有效传输进度的最长持续时间。</para>
		/// </summary>
		public TimeSpan IdleTimeout { get; }

		/// <summary>
		///     <para xml:lang="en">Maximum retransmissions before timing out.</para>
		///     <para xml:lang="zh-CN">超时前的最大重传次数。</para>
		/// </summary>
		public int MaxRetransmissions { get; }

		/// <summary>
		///     <para xml:lang="en">Creates and validates bulk-stream policy.</para>
		///     <para xml:lang="zh-CN">创建并验证批量流策略。</para>
		/// </summary>
		/// <param name="maxStreamBytes">
		///     <para xml:lang="en">Maximum declared stream length; zero selects 64 MiB. The absolute limit is 1 GiB.</para>
		///     <para xml:lang="zh-CN">声明流长度上限；零表示 64 MiB，绝对上限为 1 GiB。</para>
		/// </param>
		/// <param name="preferredChunkBytes">
		///     <para xml:lang="en">Preferred data bytes per frame; zero selects 16 KiB.</para>
		///     <para xml:lang="zh-CN">每帧首选数据字节数；零表示 16 KiB。</para>
		/// </param>
		/// <param name="receiveWindowBytes">
		///     <para xml:lang="en">Maximum unacknowledged receive window; zero selects 256 KiB.</para>
		///     <para xml:lang="zh-CN">未确认接收窗口上限；零表示 256 KiB。</para>
		/// </param>
		/// <param name="maxConcurrentInboundStreams">
		///     <para xml:lang="en">Concurrent accepted inbound streams; zero selects two.</para>
		///     <para xml:lang="zh-CN">并发接受的入站流数量；零表示两个。</para>
		/// </param>
		/// <param name="maxConcurrentOutboundStreams">
		///     <para xml:lang="en">Concurrent local outbound streams; zero selects two.</para>
		///     <para xml:lang="zh-CN">本地并发出站流数量；零表示两个。</para>
		/// </param>
		/// <param name="acknowledgementTimeout">
		///     <para xml:lang="en">Wait before retransmitting an unacknowledged window; null selects two seconds.</para>
		///     <para xml:lang="zh-CN">重传未确认窗口前的等待时间；空值表示两秒。</para>
		/// </param>
		/// <param name="idleTimeout">
		///     <para xml:lang="en">Maximum period without valid stream progress; null selects thirty seconds.</para>
		///     <para xml:lang="zh-CN">没有有效流进度的最长时间；空值表示三十秒。</para>
		/// </param>
		/// <param name="maxRetransmissions">
		///     <para xml:lang="en">Maximum retransmissions for an offer, window, or completion frame.</para>
		///     <para xml:lang="zh-CN">提议、窗口或完成帧的最大重传次数。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentOutOfRangeException">
		///     <para xml:lang="en">A size, concurrency limit, timeout, or retry count is outside its documented range.</para>
		///     <para xml:lang="zh-CN">大小、并发限制、超时或重试次数超出文档范围。</para>
		/// </exception>
		public RitsuLibSidecarBulkStreamOptions(long maxStreamBytes = 0L, int preferredChunkBytes = 0, int receiveWindowBytes = 0, int maxConcurrentInboundStreams = 0, int maxConcurrentOutboundStreams = 0, TimeSpan? acknowledgementTimeout = null, TimeSpan? idleTimeout = null, int maxRetransmissions = 5)
		{
			MaxStreamBytes = ((maxStreamBytes == 0L) ? 67108864 : maxStreamBytes);
			PreferredChunkBytes = ((preferredChunkBytes == 0) ? 16384 : preferredChunkBytes);
			ReceiveWindowBytes = ((receiveWindowBytes == 0) ? 262144 : receiveWindowBytes);
			MaxConcurrentInboundStreams = ((maxConcurrentInboundStreams == 0) ? 2 : maxConcurrentInboundStreams);
			MaxConcurrentOutboundStreams = ((maxConcurrentOutboundStreams == 0) ? 2 : maxConcurrentOutboundStreams);
			AcknowledgementTimeout = acknowledgementTimeout ?? RitsuLibSidecarEndpointPolicy.DefaultBulkAcknowledgementTimeout;
			IdleTimeout = idleTimeout ?? RitsuLibSidecarEndpointPolicy.DefaultBulkIdleTimeout;
			MaxRetransmissions = maxRetransmissions;
			ArgumentOutOfRangeException.ThrowIfLessThan(MaxStreamBytes, 1L, "MaxStreamBytes");
			ArgumentOutOfRangeException.ThrowIfGreaterThan(MaxStreamBytes, 1073741824L, "MaxStreamBytes");
			ValidateRange(PreferredChunkBytes, 1024, 32768, "preferredChunkBytes");
			ValidateRange(ReceiveWindowBytes, 16384, 2097152, "receiveWindowBytes");
			if (ReceiveWindowBytes < PreferredChunkBytes)
			{
				throw new ArgumentOutOfRangeException("receiveWindowBytes", ReceiveWindowBytes, "Receive window cannot be smaller than the preferred chunk size.");
			}
			ValidateRange(MaxConcurrentInboundStreams, 1, 8, "maxConcurrentInboundStreams");
			ValidateRange(MaxConcurrentOutboundStreams, 1, 8, "maxConcurrentOutboundStreams");
			ValidateRange(AcknowledgementTimeout, RitsuLibSidecarEndpointPolicy.MinimumBulkAcknowledgementTimeout, RitsuLibSidecarEndpointPolicy.MaximumBulkAcknowledgementTimeout, "acknowledgementTimeout");
			ValidateRange(IdleTimeout, RitsuLibSidecarEndpointPolicy.MinimumBulkIdleTimeout, RitsuLibSidecarEndpointPolicy.MaximumBulkIdleTimeout, "idleTimeout");
			ValidateRange(MaxRetransmissions, 0, 12, "maxRetransmissions");
		}

		private static void ValidateRange(int value, int minimum, int maximum, string parameterName)
		{
			if (value < minimum || value > maximum)
			{
				throw new ArgumentOutOfRangeException(parameterName, value, $"Value must be between {minimum} and {maximum}.");
			}
		}

		private static void ValidateRange(TimeSpan value, TimeSpan minimum, TimeSpan maximum, string parameterName)
		{
			if (value < minimum || value > maximum)
			{
				throw new ArgumentOutOfRangeException(parameterName, value, $"Value must be between {minimum} and {maximum}.");
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Describes one inbound bulk stream before the receiver accepts it.</para>
	///     <para xml:lang="zh-CN">描述接收方接受前的一条入站批量流。</para>
	/// </summary>
	/// <param name="OriginalSenderNetId">
	///     <para xml:lang="en">Host-canonicalized session peer ID of the stream sender.</para>
	///     <para xml:lang="zh-CN">由主机规范化的流发送方会话对等 ID。</para>
	/// </param>
	/// <param name="TransferId">
	///     <para xml:lang="en">Nonzero sender-scoped transfer identifier.</para>
	///     <para xml:lang="zh-CN">非零、发送方作用域内的传输标识符。</para>
	/// </param>
	/// <param name="NegotiatedProtocolVersion">
	///     <para xml:lang="en">Application payload contract version selected for the endpoint route.</para>
	///     <para xml:lang="zh-CN">为端点路由选定的应用载荷契约版本。</para>
	/// </param>
	/// <param name="Length">
	///     <para xml:lang="en">Declared total stream length in bytes.</para>
	///     <para xml:lang="zh-CN">声明的流总字节长度。</para>
	/// </param>
	/// <param name="Metadata">
	///     <para xml:lang="en">Validated opaque metadata supplied by the sender.</para>
	///     <para xml:lang="zh-CN">发送方提供的经过验证的不透明元数据。</para>
	/// </param>
	public readonly record struct RitsuLibSidecarBulkStreamOffer(ulong OriginalSenderNetId, ulong TransferId, ushort NegotiatedProtocolVersion, long Length, RitsuLibSidecarBulkStreamMetadata Metadata);
	/// <summary>
	///     <para xml:lang="en">Reports acknowledged send progress or committed receive progress.</para>
	///     <para xml:lang="zh-CN">报告已确认的发送进度或已写入的接收进度。</para>
	/// </summary>
	/// <param name="TransferId">
	///     <para xml:lang="en">Transfer identifier.</para>
	///     <para xml:lang="zh-CN">传输标识符。</para>
	/// </param>
	/// <param name="Direction">
	///     <para xml:lang="en">Local transfer direction.</para>
	///     <para xml:lang="zh-CN">本地传输方向。</para>
	/// </param>
	/// <param name="ConfirmedBytes">
	///     <para xml:lang="en">Bytes acknowledged by the receiver or committed to the destination.</para>
	///     <para xml:lang="zh-CN">接收方已确认或已写入目标的字节数。</para>
	/// </param>
	/// <param name="TotalBytes">
	///     <para xml:lang="en">Declared total byte count.</para>
	///     <para xml:lang="zh-CN">声明的总字节数。</para>
	/// </param>
	public readonly record struct RitsuLibSidecarBulkStreamProgress(ulong TransferId, RitsuLibSidecarBulkTransferDirection Direction, long ConfirmedBytes, long TotalBytes);
	/// <summary>
	///     <para xml:lang="en">Reports the terminal state and confirmed byte count of one bulk transfer.</para>
	///     <para xml:lang="zh-CN">报告一条批量传输的最终状态和已确认字节数。</para>
	/// </summary>
	/// <param name="TransferId">
	///     <para xml:lang="en">Transfer identifier.</para>
	///     <para xml:lang="zh-CN">传输标识符。</para>
	/// </param>
	/// <param name="PeerNetId">
	///     <para xml:lang="en">Remote session peer ID.</para>
	///     <para xml:lang="zh-CN">远端会话对等 ID。</para>
	/// </param>
	/// <param name="Status">
	///     <para xml:lang="en">Terminal transfer status.</para>
	///     <para xml:lang="zh-CN">最终传输状态。</para>
	/// </param>
	/// <param name="ConfirmedBytes">
	///     <para xml:lang="en">Bytes confirmed before termination.</para>
	///     <para xml:lang="zh-CN">终止前已确认的字节数。</para>
	/// </param>
	public readonly record struct RitsuLibSidecarBulkTransferResult(ulong TransferId, ulong PeerNetId, RitsuLibSidecarBulkTransferStatus Status, long ConfirmedBytes)
	{
		/// <summary>
		///     <para xml:lang="en">Whether the stream completed with verified integrity.</para>
		///     <para xml:lang="zh-CN">流是否已通过完整性校验并完成。</para>
		/// </summary>
		public bool IsCompleted => Status == RitsuLibSidecarBulkTransferStatus.Completed;
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Supplies a caller-owned writable destination for one accepted inbound stream. RitsuLib exclusively writes
	///         to the destination until <see cref="P:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBulkReceiveTarget.Completion" /> finishes.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为一条已接受的入站流提供调用方拥有的可写目标。在 <see cref="P:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBulkReceiveTarget.Completion" /> 完成前，RitsuLib
	///         独占地写入该目标。
	///     </para>
	/// </summary>
	public sealed class RitsuLibSidecarBulkReceiveTarget
	{
		private readonly TaskCompletionSource<RitsuLibSidecarBulkTransferResult> _completion = new TaskCompletionSource<RitsuLibSidecarBulkTransferResult>(TaskCreationOptions.RunContinuationsAsynchronously);

		private int _attached;

		/// <summary>
		///     <para xml:lang="en">
		///         Completes exactly once after verification succeeds or the transfer terminates. Callback exceptions are
		///         not stored in this task.
		///     </para>
		///     <para xml:lang="zh-CN">在校验成功或传输终止后恰好完成一次；回调异常不会存入此任务。</para>
		/// </summary>
		public Task<RitsuLibSidecarBulkTransferResult> Completion => _completion.Task;

		internal Stream Destination { get; }

		internal bool LeaveOpen { get; }

		internal IProgress<RitsuLibSidecarBulkStreamProgress>? Progress { get; }

		internal CancellationToken CancellationToken { get; }

		/// <summary>
		///     <para xml:lang="en">Creates a receive target for exactly one accepted stream.</para>
		///     <para xml:lang="zh-CN">为恰好一条已接受的流创建接收目标。</para>
		/// </summary>
		/// <param name="destination">
		///     <para xml:lang="en">Writable stream positioned where incoming bytes should begin.</para>
		///     <para xml:lang="zh-CN">定位在传入字节起始写入位置的可写流。</para>
		/// </param>
		/// <param name="leaveOpen">
		///     <para xml:lang="en">Whether RitsuLib leaves the destination open after every terminal outcome.</para>
		///     <para xml:lang="zh-CN">RitsuLib 是否在任意最终结果后保持目标流打开。</para>
		/// </param>
		/// <param name="progress">
		///     <para xml:lang="en">Optional committed-byte progress observer, invoked from the stream worker.</para>
		///     <para xml:lang="zh-CN">可选的已写入字节进度观察器，由流工作线程调用。</para>
		/// </param>
		/// <param name="cancellationToken">
		///     <para xml:lang="en">Optional token that cancels the accepted transfer.</para>
		///     <para xml:lang="zh-CN">可选的令牌，用于取消已接受的传输。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="destination" /> is null.</para>
		///     <para xml:lang="zh-CN"><paramref name="destination" /> 为空。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en"><paramref name="destination" /> is not writable.</para>
		///     <para xml:lang="zh-CN"><paramref name="destination" /> 不可写。</para>
		/// </exception>
		public RitsuLibSidecarBulkReceiveTarget(Stream destination, bool leaveOpen = false, IProgress<RitsuLibSidecarBulkStreamProgress>? progress = null, CancellationToken cancellationToken = default(CancellationToken))
		{
			ArgumentNullException.ThrowIfNull(destination, "destination");
			if (!destination.CanWrite)
			{
				throw new ArgumentException("Bulk receive destination must be writable.", "destination");
			}
			Destination = destination;
			LeaveOpen = leaveOpen;
			Progress = progress;
			CancellationToken = cancellationToken;
		}

		internal bool TryAttach()
		{
			return Interlocked.Exchange(ref _attached, 1) == 0;
		}

		internal void Complete(RitsuLibSidecarBulkTransferResult result)
		{
			_completion.TrySetResult(result);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Owns one bulk-stream endpoint registration. Streams are unicast, bounded, windowed, cancelable, and
	///         end-to-end verified. Disposing the handle terminates all active transfers and withdraws the endpoint.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         拥有一个批量流端点注册。流为单播、有界、窗口式、可取消且经过端到端校验。释放句柄会终止全部活动
	///         传输并撤回端点。
	///     </para>
	/// </summary>
	public sealed class RitsuLibSidecarBulkEndpointHandle : IDisposable
	{
		private readonly RitsuLibSidecarEndpointRegistration _registration;

		/// <summary>
		///     <para xml:lang="en">Immutable routed-endpoint descriptor.</para>
		///     <para xml:lang="zh-CN">不可变的路由端点描述符。</para>
		/// </summary>
		public RitsuLibSidecarEndpointDescriptor Descriptor => _registration.Descriptor;

		/// <summary>
		///     <para xml:lang="en">Immutable local bulk-stream policy.</para>
		///     <para xml:lang="zh-CN">不可变的本地批量流策略。</para>
		/// </summary>
		public RitsuLibSidecarBulkStreamOptions Options => _registration.BulkOptions;

		/// <summary>
		///     <para xml:lang="en">Whether the registration has been disposed.</para>
		///     <para xml:lang="zh-CN">注册是否已经释放。</para>
		/// </summary>
		public bool IsDisposed => _registration.IsDisposed;

		/// <summary>
		///     <para xml:lang="en">
		///         Raised after the negotiated protocol version or compatible participant set changes. Handlers follow
		///         the descriptor dispatch mode and exceptions are isolated.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在协商协议版本或兼容参与方集合变化后引发。处理器遵循描述符的调度模式，且异常会被隔离。
		///     </para>
		/// </summary>
		public event Action<RitsuLibSidecarEndpointParticipantsChangedEvent> ParticipantsChanged
		{
			add
			{
				_registration.ParticipantsChanged += value;
			}
			remove
			{
				_registration.ParticipantsChanged -= value;
			}
		}

		internal RitsuLibSidecarBulkEndpointHandle(RitsuLibSidecarEndpointRegistration registration)
		{
			_registration = registration;
		}

		/// <summary>
		///     <para xml:lang="en">Returns an immutable snapshot of compatible route participants.</para>
		///     <para xml:lang="zh-CN">返回兼容路由参与方的不可变快照。</para>
		/// </summary>
		public IReadOnlyList<ulong> GetParticipantsSnapshot()
		{
			RitsuLibSidecarEndpointRouteDefinition? route = _registration.GetRoute();
			if (!route.HasValue)
			{
				return Array.Empty<ulong>();
			}
			return Array.AsReadOnly(route.GetValueOrDefault().ParticipantNetIds.ToArray());
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sends exactly <paramref name="length" /> bytes from <paramref name="source" /> to the host. The source
		///         remains caller-owned and must remain readable until the returned task completes.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从 <paramref name="source" /> 向主机发送恰好 <paramref name="length" /> 个字节。源流仍由调用方
		///         拥有，并且在返回任务完成前必须保持可读。
		///     </para>
		/// </summary>
		/// <param name="source">
		///     <para xml:lang="en">Readable source stream; seekability is not required.</para>
		///     <para xml:lang="zh-CN">可读源流；不要求支持定位。</para>
		/// </param>
		/// <param name="length">
		///     <para xml:lang="en">Exact number of bytes to consume from the current source position.</para>
		///     <para xml:lang="zh-CN">从源流当前位置开始消耗的确切字节数。</para>
		/// </param>
		/// <param name="metadata">
		///     <para xml:lang="en">Optional validated opaque metadata.</para>
		///     <para xml:lang="zh-CN">可选的经过验证的不透明元数据。</para>
		/// </param>
		/// <param name="progress">
		///     <para xml:lang="en">Optional cumulative acknowledgement progress observer.</para>
		///     <para xml:lang="zh-CN">可选的累计确认进度观察器。</para>
		/// </param>
		/// <param name="cancellationToken">
		///     <para xml:lang="en">Token used to cancel this transfer.</para>
		///     <para xml:lang="zh-CN">用于取消此传输的令牌。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A task that always resolves to a terminal transfer result.</para>
		///     <para xml:lang="zh-CN">始终解析为最终传输结果的任务。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="source" /> is null.</para>
		///     <para xml:lang="zh-CN"><paramref name="source" /> 为空。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en"><paramref name="source" /> is not readable.</para>
		///     <para xml:lang="zh-CN"><paramref name="source" /> 不可读。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentOutOfRangeException">
		///     <para xml:lang="en"><paramref name="length" /> is negative or exceeds the endpoint limit.</para>
		///     <para xml:lang="zh-CN"><paramref name="length" /> 为负数或超过端点限制。</para>
		/// </exception>
		public Task<RitsuLibSidecarBulkTransferResult> SendToHostAsync(Stream source, long length, RitsuLibSidecarBulkStreamMetadata? metadata = null, IProgress<RitsuLibSidecarBulkStreamProgress>? progress = null, CancellationToken cancellationToken = default(CancellationToken))
		{
			return _registration.BulkTransfers.SendAsync(RitsuLibSidecarEndpointDestination.Host, 0uL, source, length, metadata, progress, cancellationToken);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sends exactly <paramref name="length" /> bytes from <paramref name="source" /> to one compatible peer
		///         through the host. Relay-group participants may call it; for a host-authority endpoint only the host may
		///         call it. The source remains caller-owned until completion.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过主机从 <paramref name="source" /> 向一个兼容对等方发送恰好 <paramref name="length" /> 个
		///         字节。中继组参与方可以调用；主机权威端点中仅主机可以调用。源流在完成前仍由调用方拥有。
		///     </para>
		/// </summary>
		/// <param name="peerNetId">
		///     <para xml:lang="en">Nonzero destination session peer ID.</para>
		///     <para xml:lang="zh-CN">非零的目标会话对等 ID。</para>
		/// </param>
		/// <param name="source">
		///     <para xml:lang="en">Readable source stream; seekability is not required.</para>
		///     <para xml:lang="zh-CN">可读源流；不要求支持定位。</para>
		/// </param>
		/// <param name="length">
		///     <para xml:lang="en">Exact number of bytes to consume from the current source position.</para>
		///     <para xml:lang="zh-CN">从源流当前位置开始消耗的确切字节数。</para>
		/// </param>
		/// <param name="metadata">
		///     <para xml:lang="en">Optional validated opaque metadata.</para>
		///     <para xml:lang="zh-CN">可选的经过验证的不透明元数据。</para>
		/// </param>
		/// <param name="progress">
		///     <para xml:lang="en">Optional cumulative acknowledgement progress observer.</para>
		///     <para xml:lang="zh-CN">可选的累计确认进度观察器。</para>
		/// </param>
		/// <param name="cancellationToken">
		///     <para xml:lang="en">Token used to cancel this transfer.</para>
		///     <para xml:lang="zh-CN">用于取消此传输的令牌。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A task that always resolves to a terminal transfer result.</para>
		///     <para xml:lang="zh-CN">始终解析为最终传输结果的任务。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentOutOfRangeException">
		///     <para xml:lang="en">
		///         <paramref name="peerNetId" /> is zero, or <paramref name="length" /> is negative or exceeds the endpoint
		///         limit.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         <paramref name="peerNetId" /> 为零，或 <paramref name="length" /> 为负数或超过端点限制。
		///     </para>
		/// </exception>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="source" /> is null.</para>
		///     <para xml:lang="zh-CN"><paramref name="source" /> 为空。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en"><paramref name="source" /> is not readable.</para>
		///     <para xml:lang="zh-CN"><paramref name="source" /> 不可读。</para>
		/// </exception>
		public Task<RitsuLibSidecarBulkTransferResult> SendToPeerAsync(ulong peerNetId, Stream source, long length, RitsuLibSidecarBulkStreamMetadata? metadata = null, IProgress<RitsuLibSidecarBulkStreamProgress>? progress = null, CancellationToken cancellationToken = default(CancellationToken))
		{
			ArgumentOutOfRangeException.ThrowIfZero(peerNetId, "peerNetId");
			return _registration.BulkTransfers.SendAsync(RitsuLibSidecarEndpointDestination.Peer, peerNetId, source, length, metadata, progress, cancellationToken);
		}

		/// <summary>
		///     <para xml:lang="en">Cancels active transfers and withdraws this registration. Repeated calls are safe.</para>
		///     <para xml:lang="zh-CN">取消活动传输并撤回此注册；重复调用是安全的。</para>
		/// </summary>
		public void Dispose()
		{
			_registration.Dispose();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines a backend-independent delivery contract for routed endpoint messages.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义路由端点消息使用的后端无关投递契约。
	///     </para>
	/// </summary>
	public enum RitsuLibSidecarDeliveryProfile : byte
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Reliable, ordered delivery for bounded control messages. Accepted sends remain subject to disconnects
		///         and do not constitute an application-level acknowledgement.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为有界控制消息提供可靠且有序的投递。发送被接受并不构成应用层确认，断线仍可能使消息无法到达。
		///     </para>
		/// </summary>
		Control = 1,
		/// <summary>
		///     <para xml:lang="en">
		///         Unreliable, sequenced delivery for latency-sensitive datagrams. RitsuLib drops expired queued frames
		///         and stale received sequence numbers; messages are never fragmented or retransmitted by the data plane.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为延迟敏感的数据报提供不可靠、带序列的投递。RitsuLib 会丢弃队列中过期的帧和收到的旧序列号；
		///         数据平面绝不会分片或重传此类消息。
		///     </para>
		/// </summary>
		RealtimeDatagram,
		/// <summary>
		///     <para xml:lang="en">
		///         Reliable, windowed delivery for bounded byte streams such as images, files, and large snapshots.
		///         Streams use application acknowledgements, bounded retransmission, cancellation, and end-to-end
		///         SHA-256 verification. Register this profile through
		///         <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEndpoints.RegisterBulk(STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEndpointDescriptor,STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBulkStreamOptions,System.Func{STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBulkStreamOffer,STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBulkReceiveTarget})" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为图片、文件和大型快照等有界字节流提供可靠的窗口式投递。流使用应用层确认、有界重传、取消和
		///         端到端 SHA-256 校验。此档位应通过 <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEndpoints.RegisterBulk(STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEndpointDescriptor,STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBulkStreamOptions,System.Func{STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBulkStreamOffer,STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBulkReceiveTarget})" /> 注册。
		///     </para>
		/// </summary>
		BulkStream
	}
	/// <summary>
	///     <para xml:lang="en">Defines who may participate in and route messages for an endpoint.</para>
	///     <para xml:lang="zh-CN">定义哪些参与方可以加入端点并为其路由消息。</para>
	/// </summary>
	public enum RitsuLibSidecarEndpointTopology : byte
	{
		/// <summary>
		///     <para xml:lang="en">
		///         The host must register the endpoint. Clients may send only to the host; the host may send to compatible
		///         clients individually or by broadcast. RitsuLib never relays a client-originated opaque payload to
		///         another client.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         主机必须注册该端点。客户端只能向主机发送；主机可以单独或广播发送给兼容客户端。RitsuLib
		///         绝不会把源自客户端的不透明载荷中继给其他客户端。
		///     </para>
		/// </summary>
		HostAuthority = 1,
		/// <summary>
		///     <para xml:lang="en">
		///         The host may route opaque payloads between compatible participants without registering or
		///         understanding the endpoint itself.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         主机可以在兼容参与方之间路由不透明载荷，而无需自行注册或理解该端点。
		///     </para>
		/// </summary>
		RelayGroup
	}
	/// <summary>
	///     <para xml:lang="en">Defines where an endpoint receive callback executes.</para>
	///     <para xml:lang="zh-CN">定义端点接收回调的执行位置。</para>
	/// </summary>
	public enum RitsuLibSidecarEndpointDispatchMode
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Queue callbacks on the Godot main loop. This is the default and required for callbacks that access
		///         scene-tree or game state. The per-endpoint callback queue is bounded; excess deliveries are dropped and
		///         logged.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将回调排入 Godot 主循环。这是默认选项；访问场景树或游戏状态的回调必须使用此模式。
		///         每个端点的回调队列有界；超出容量的投递会被丢弃并记录日志。
		///     </para>
		/// </summary>
		GodotMainLoop,
		/// <summary>
		///     <para xml:lang="en">
		///         Execute synchronously on the transport receive callback. The callback must not block or access
		///         thread-affine game state.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在传输接收回调上同步执行。回调不得阻塞，也不得访问具有线程关联的游戏状态。
		///     </para>
		/// </summary>
		ReceiveThread,
		/// <summary>
		///     <para xml:lang="en">
		///         Execute on a bounded, endpoint-owned serial background queue that preserves callback order. Excess
		///         deliveries are dropped and logged.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在端点独占的有界串行后台队列中执行，并保持回调顺序；超出容量的投递会被丢弃并记录日志。
		///     </para>
		/// </summary>
		BackgroundSerial
	}
	/// <summary>
	///     <para xml:lang="en">Describes why a routed endpoint send was accepted or rejected locally.</para>
	///     <para xml:lang="zh-CN">描述路由端点发送在本地被接受或拒绝的原因。</para>
	/// </summary>
	public enum RitsuLibSidecarSendStatus
	{
		/// <summary>
		///     <para xml:lang="en">The frame was accepted into RitsuLib's bounded outbound queue.</para>
		///     <para xml:lang="zh-CN">帧已进入 RitsuLib 的有界出站队列。</para>
		/// </summary>
		Accepted,
		/// <summary>
		///     <para xml:lang="en">No active multiplayer session is available.</para>
		///     <para xml:lang="zh-CN">当前没有可用的多人会话。</para>
		/// </summary>
		NoSession,
		/// <summary>
		///     <para xml:lang="en">The endpoint registration has been disposed.</para>
		///     <para xml:lang="zh-CN">端点注册已被释放。</para>
		/// </summary>
		EndpointDisposed,
		/// <summary>
		///     <para xml:lang="en">No compatible negotiated route is currently available.</para>
		///     <para xml:lang="zh-CN">当前没有可用的兼容协商路由。</para>
		/// </summary>
		RouteUnavailable,
		/// <summary>
		///     <para xml:lang="en">The requested destination is not an active route participant.</para>
		///     <para xml:lang="zh-CN">请求的目标不是活动路由参与方。</para>
		/// </summary>
		DestinationUnavailable,
		/// <summary>
		///     <para xml:lang="en">The current transport cannot satisfy the endpoint's delivery profile.</para>
		///     <para xml:lang="zh-CN">当前传输无法满足端点的投递档位。</para>
		/// </summary>
		ProfileUnsupported,
		/// <summary>
		///     <para xml:lang="en">The payload exceeds the negotiated route limit.</para>
		///     <para xml:lang="zh-CN">载荷超过协商后的路由上限。</para>
		/// </summary>
		PayloadTooLarge,
		/// <summary>
		///     <para xml:lang="en">The endpoint's local outbound rate limit rejected the frame.</para>
		///     <para xml:lang="zh-CN">端点的本地出站速率限制拒绝了该帧。</para>
		///     </summary>
		RateLimited,
		/// <summary>
		///     <para xml:lang="en">The bounded outbound queue has no capacity for the frame.</para>
		///     <para xml:lang="zh-CN">有界出站队列没有足够容量容纳该帧。</para>
		/// </summary>
		QueueFull,
		/// <summary>
		///     <para xml:lang="en">The target Sidecar connection is unavailable.</para>
		///     <para xml:lang="zh-CN">目标 Sidecar 连接不可用。</para>
		/// </summary>
		TransportUnavailable,
		/// <summary>
		///     <para xml:lang="en">The requested operation is not valid for the endpoint topology or local role.</para>
		///     <para xml:lang="zh-CN">请求的操作不适用于该端点拓扑或本地角色。</para>
		/// </summary>
		InvalidOperation
	}
	/// <summary>
	///     <para xml:lang="en">Reports the local outcome of a routed endpoint send request.</para>
	///     <para xml:lang="zh-CN">报告路由端点发送请求的本地结果。</para>
	/// </summary>
	/// <param name="Status">
	///     <para xml:lang="en">The acceptance or rejection status.</para>
	///     <para xml:lang="zh-CN">接受或拒绝状态。</para>
	/// </param>
	/// <param name="QueuedRecipientCount">
	///     <para xml:lang="en">
	///         Number of physical next-hop frames accepted locally. This is not a delivery acknowledgement.
	///     </para>
	///     <para xml:lang="zh-CN">本地接受的物理下一跳帧数量；这不是投递确认。</para>
	/// </param>
	public readonly record struct RitsuLibSidecarSendResult(RitsuLibSidecarSendStatus Status, int QueuedRecipientCount)
	{
		/// <summary>
		///     <para xml:lang="en">Whether the request was accepted into the outbound queue.</para>
		///     <para xml:lang="zh-CN">请求是否已被出站队列接受。</para>
		/// </summary>
		public bool IsAccepted => Status == RitsuLibSidecarSendStatus.Accepted;
	}
	/// <summary>
	///     <para xml:lang="en">Owns one payload delivered to a registered routed endpoint.</para>
	///     <para xml:lang="zh-CN">承载投递给已注册路由端点的一份载荷。</para>
	/// </summary>
	/// <param name="OriginalSenderNetId">
	///     <para xml:lang="en">
	///         Canonical session peer ID assigned from the host's transport context. Clients cannot choose this value.
	///     </para>
	///     <para xml:lang="zh-CN">由主机依据传输上下文确定的规范会话对等方 ID；客户端无法自行指定该值。</para>
	/// </param>
	/// <param name="NegotiatedProtocolVersion">
	///     <para xml:lang="en">The protocol version selected for this route.</para>
	///     <para xml:lang="zh-CN">为此路由选择的协议版本。</para>
	/// </param>
	/// <param name="Payload">
	///     <para xml:lang="en">
	///         Owned message bytes that remain valid for the duration of the callback. Copy them before retaining.
	///     </para>
	///     <para xml:lang="zh-CN">在回调期间保持有效的独占消息字节；如需长期保留，请先复制。</para>
	/// </param>
	public readonly record struct RitsuLibSidecarEndpointMessage(ulong OriginalSenderNetId, ushort NegotiatedProtocolVersion, ReadOnlyMemory<byte> Payload);
	/// <summary>
	///     <para xml:lang="en">Reports a negotiated endpoint route or participant-set change.</para>
	///     <para xml:lang="zh-CN">报告协商后的端点路由或参与方集合发生变化。</para>
	/// </summary>
	/// <param name="ProtocolVersion">
	///     <para xml:lang="en">Selected protocol version, or zero when no route is available.</para>
	///     <para xml:lang="zh-CN">选定的协议版本；没有可用路由时为零。</para>
	/// </param>
	/// <param name="ParticipantNetIds">
	///     <para xml:lang="en">An immutable snapshot of compatible participant IDs.</para>
	///     <para xml:lang="zh-CN">兼容参与方 ID 的不可变快照。</para>
	/// </param>
	public readonly record struct RitsuLibSidecarEndpointParticipantsChangedEvent(ushort ProtocolVersion, IReadOnlyList<ulong> ParticipantNetIds);
	/// <summary>
	///     <para xml:lang="en">
	///         Defines one process-owned routed endpoint. Registration is unique by the ordinal
	///         <see cref="P:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEndpointDescriptor.OwnerId" /> and <see cref="P:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEndpointDescriptor.Name" /> pair.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义一个由当前进程拥有的路由端点。注册按区分大小写的 <see cref="P:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEndpointDescriptor.OwnerId" /> 与
	///         <see cref="P:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEndpointDescriptor.Name" /> 组合保持唯一。
	///     </para>
	/// </summary>
	public sealed class RitsuLibSidecarEndpointDescriptor
	{
		/// <summary>
		///     <para xml:lang="en">Stable mod or library owner identifier.</para>
		///     <para xml:lang="zh-CN">稳定的模组或库所有者标识符。</para>
		/// </summary>
		public string OwnerId { get; }

		/// <summary>
		///     <para xml:lang="en">Stable endpoint service name.</para>
		///     <para xml:lang="zh-CN">稳定的端点服务名称。</para>
		/// </summary>
		public string Name { get; }

		/// <summary>
		///     <para xml:lang="en">Highest supported payload contract version.</para>
		///     <para xml:lang="zh-CN">支持的最高载荷契约版本。</para>
		/// </summary>
		public ushort ProtocolVersion { get; }

		/// <summary>
		///     <para xml:lang="en">Lowest supported payload contract version.</para>
		///     <para xml:lang="zh-CN">支持的最低载荷契约版本。</para>
		/// </summary>
		public ushort MinimumCompatibleProtocolVersion { get; }

		/// <summary>
		///     <para xml:lang="en">Backend-independent delivery contract.</para>
		///     <para xml:lang="zh-CN">后端无关的投递契约。</para>
		/// </summary>
		public RitsuLibSidecarDeliveryProfile DeliveryProfile { get; }

		/// <summary>
		///     <para xml:lang="en">Routing and host-authority policy.</para>
		///     <para xml:lang="zh-CN">路由与主机权威策略。</para>
		/// </summary>
		public RitsuLibSidecarEndpointTopology Topology { get; }

		/// <summary>
		///     <para xml:lang="en">Maximum local logical payload size before route negotiation lowers it.</para>
		///     <para xml:lang="zh-CN">路由协商进一步降低之前的本地逻辑载荷大小上限。</para>
		/// </summary>
		public int MaxPayloadBytes { get; }

		/// <summary>
		///     <para xml:lang="en">Receive callback scheduling policy.</para>
		///     <para xml:lang="zh-CN">接收回调调度策略。</para>
		/// </summary>
		public RitsuLibSidecarEndpointDispatchMode DispatchMode { get; }

		/// <summary>
		///     <para xml:lang="en">Local outbound queue lifetime for realtime datagrams; zero for other profiles.</para>
		///     <para xml:lang="zh-CN">实时数据报的本地出站队列生存时间；其他档位为零。</para>
		/// </summary>
		public TimeSpan RealtimeLifetime { get; }

		/// <summary>
		///     <para xml:lang="en">Maximum locally accepted outbound packets per second.</para>
		///     <para xml:lang="zh-CN">本地每秒最多接受的出站包数。</para>
		/// </summary>
		public int MaxOutboundPacketsPerSecond { get; }

		/// <summary>
		///     <para xml:lang="en">Maximum locally accepted outbound logical payload bytes per second.</para>
		///     <para xml:lang="zh-CN">本地每秒最多接受的出站逻辑载荷字节数。</para>
		/// </summary>
		public int MaxOutboundBytesPerSecond { get; }

		/// <summary>
		///     <para xml:lang="en">Creates and validates an immutable endpoint descriptor.</para>
		///     <para xml:lang="zh-CN">创建并验证一个不可变端点描述符。</para>
		/// </summary>
		/// <param name="ownerId">
		///     <para xml:lang="en">
		///         Stable mod or library identifier. It must contain only ASCII letters, digits, dot, underscore, or
		///         hyphen and occupy at most 128 UTF-8 bytes.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         稳定的模组或库标识符。只能包含 ASCII 字母、数字、点、下划线或连字符，且 UTF-8 长度最多为
		///         128 字节。
		///     </para>
		/// </param>
		/// <param name="name">
		///     <para xml:lang="en">
		///         Stable service name. It follows the owner identifier rules and additionally permits slash.
		///     </para>
		///     <para xml:lang="zh-CN">稳定的服务名称。规则与所有者标识符相同，并额外允许斜杠。</para>
		/// </param>
		/// <param name="protocolVersion">
		///     <para xml:lang="en">Highest payload contract version this endpoint can send and receive.</para>
		///     <para xml:lang="zh-CN">此端点能够发送和接收的最高载荷契约版本。</para>
		/// </param>
		/// <param name="minimumCompatibleProtocolVersion">
		///     <para xml:lang="en">
		///         Lowest payload contract version this endpoint can send and receive. The host selects the highest
		///         version common to the largest compatible participant set.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         此端点能够发送和接收的最低载荷契约版本。主机会为最大的兼容参与方集合选择共同支持的最高版本。
		///     </para>
		/// </param>
		/// <param name="deliveryProfile">
		///     <para xml:lang="en">Backend-independent delivery contract.</para>
		///     <para xml:lang="zh-CN">后端无关的投递契约。</para>
		/// </param>
		/// <param name="topology">
		///     <para xml:lang="en">Endpoint routing and host-authority policy.</para>
		///     <para xml:lang="zh-CN">端点路由与主机权威策略。</para>
		/// </param>
		/// <param name="maxPayloadBytes">
		///     <para xml:lang="en">
		///         Maximum logical payload size. Zero selects the profile default. Negotiation may select a lower value.
		///     </para>
		///     <para xml:lang="zh-CN">逻辑载荷大小上限。零表示使用档位默认值；协商结果可能选择更低上限。</para>
		/// </param>
		/// <param name="dispatchMode">
		///     <para xml:lang="en">Receive callback scheduling policy.</para>
		///     <para xml:lang="zh-CN">接收回调调度策略。</para>
		/// </param>
		/// <param name="realtimeLifetime">
		///     <para xml:lang="en">
		///         Maximum local queue lifetime for realtime datagrams. Null selects 250 milliseconds. It is ignored for
		///         non-realtime endpoints.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         实时数据报在本地队列中的最长生存时间。空值使用 250 毫秒；非实时端点会忽略该值。
		///     </para>
		/// </param>
		/// <param name="maxOutboundPacketsPerSecond">
		///     <para xml:lang="en">Local per-endpoint packet rate; zero selects the profile default.</para>
		///     <para xml:lang="zh-CN">本地单端点包速率；零表示使用档位默认值。</para>
		/// </param>
		/// <param name="maxOutboundBytesPerSecond">
		///     <para xml:lang="en">Local per-endpoint byte rate; zero selects the profile default.</para>
		///     <para xml:lang="zh-CN">本地单端点字节速率；零表示使用档位默认值。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">An identifier is empty, too long, or contains an unsupported character.</para>
		///     <para xml:lang="zh-CN">标识符为空、过长或包含不支持的字符。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentOutOfRangeException">
		///     <para xml:lang="en">A version, enum value, payload limit, lifetime, or rate limit is invalid.</para>
		///     <para xml:lang="zh-CN">版本、枚举值、载荷限制、生存时间或速率限制无效。</para>
		/// </exception>
		public RitsuLibSidecarEndpointDescriptor(string ownerId, string name, ushort protocolVersion, ushort minimumCompatibleProtocolVersion, RitsuLibSidecarDeliveryProfile deliveryProfile, RitsuLibSidecarEndpointTopology topology, int maxPayloadBytes = 0, RitsuLibSidecarEndpointDispatchMode dispatchMode = RitsuLibSidecarEndpointDispatchMode.GodotMainLoop, TimeSpan? realtimeLifetime = null, int maxOutboundPacketsPerSecond = 0, int maxOutboundBytesPerSecond = 0)
		{
			ValidateIdentifier(ownerId, "ownerId", allowSlash: false);
			ValidateIdentifier(name, "name", allowSlash: true);
			ArgumentOutOfRangeException.ThrowIfZero(protocolVersion, "protocolVersion");
			ArgumentOutOfRangeException.ThrowIfZero(minimumCompatibleProtocolVersion, "minimumCompatibleProtocolVersion");
			if (minimumCompatibleProtocolVersion > protocolVersion)
			{
				throw new ArgumentOutOfRangeException("minimumCompatibleProtocolVersion", minimumCompatibleProtocolVersion, "The minimum compatible protocol version cannot exceed the current protocol version.");
			}
			if (!Enum.IsDefined(deliveryProfile))
			{
				throw new ArgumentOutOfRangeException("deliveryProfile", deliveryProfile, "Invalid delivery profile.");
			}
			if (!Enum.IsDefined(topology))
			{
				throw new ArgumentOutOfRangeException("topology", topology, "Invalid endpoint topology.");
			}
			if (!Enum.IsDefined(dispatchMode))
			{
				throw new ArgumentOutOfRangeException("dispatchMode", dispatchMode, "Invalid dispatch mode.");
			}
			int num = deliveryProfile switch
			{
				RitsuLibSidecarDeliveryProfile.Control => 65536, 
				RitsuLibSidecarDeliveryProfile.RealtimeDatagram => 1024, 
				RitsuLibSidecarDeliveryProfile.BulkStream => 49152, 
				_ => throw new ArgumentOutOfRangeException("deliveryProfile"), 
			};
			if (maxPayloadBytes < 0 || maxPayloadBytes > num)
			{
				throw new ArgumentOutOfRangeException("maxPayloadBytes", maxPayloadBytes, $"Payload size must be zero or between 1 and {num} bytes.");
			}
			if (deliveryProfile == RitsuLibSidecarDeliveryProfile.BulkStream && maxPayloadBytes != 0 && maxPayloadBytes < 1046)
			{
				throw new ArgumentOutOfRangeException("maxPayloadBytes", maxPayloadBytes, "Bulk payload size cannot hold the minimum data frame.");
			}
			TimeSpan timeSpan = realtimeLifetime ?? RitsuLibSidecarEndpointPolicy.DefaultRealtimeLifetime;
			if (deliveryProfile == RitsuLibSidecarDeliveryProfile.RealtimeDatagram && (timeSpan < RitsuLibSidecarEndpointPolicy.MinimumRealtimeLifetime || timeSpan > RitsuLibSidecarEndpointPolicy.MaximumRealtimeLifetime))
			{
				throw new ArgumentOutOfRangeException("realtimeLifetime", timeSpan, $"Realtime lifetime must be between {RitsuLibSidecarEndpointPolicy.MinimumRealtimeLifetime} and {RitsuLibSidecarEndpointPolicy.MaximumRealtimeLifetime}.");
			}
			ValidateRate(maxOutboundPacketsPerSecond, 1000, "maxOutboundPacketsPerSecond");
			ValidateRate(maxOutboundBytesPerSecond, 16777216, "maxOutboundBytesPerSecond");
			OwnerId = ownerId;
			Name = name;
			ProtocolVersion = protocolVersion;
			MinimumCompatibleProtocolVersion = minimumCompatibleProtocolVersion;
			DeliveryProfile = deliveryProfile;
			Topology = topology;
			MaxPayloadBytes = ((maxPayloadBytes != 0) ? maxPayloadBytes : (deliveryProfile switch
			{
				RitsuLibSidecarDeliveryProfile.Control => 16384, 
				RitsuLibSidecarDeliveryProfile.RealtimeDatagram => 1024, 
				RitsuLibSidecarDeliveryProfile.BulkStream => 16408, 
				_ => throw new ArgumentOutOfRangeException("deliveryProfile"), 
			}));
			DispatchMode = dispatchMode;
			RealtimeLifetime = ((deliveryProfile == RitsuLibSidecarDeliveryProfile.RealtimeDatagram) ? timeSpan : TimeSpan.Zero);
			MaxOutboundPacketsPerSecond = ((maxOutboundPacketsPerSecond != 0) ? maxOutboundPacketsPerSecond : (deliveryProfile switch
			{
				RitsuLibSidecarDeliveryProfile.Control => 64, 
				RitsuLibSidecarDeliveryProfile.RealtimeDatagram => 100, 
				RitsuLibSidecarDeliveryProfile.BulkStream => 128, 
				_ => throw new ArgumentOutOfRangeException("deliveryProfile"), 
			}));
			MaxOutboundBytesPerSecond = ((maxOutboundBytesPerSecond != 0) ? maxOutboundBytesPerSecond : (deliveryProfile switch
			{
				RitsuLibSidecarDeliveryProfile.Control => 262144, 
				RitsuLibSidecarDeliveryProfile.RealtimeDatagram => 131072, 
				RitsuLibSidecarDeliveryProfile.BulkStream => 2097152, 
				_ => throw new ArgumentOutOfRangeException("deliveryProfile"), 
			}));
		}

		private static void ValidateIdentifier(string value, string parameterName, bool allowSlash)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(value, parameterName);
			if (!string.Equals(value, value.Trim(), StringComparison.Ordinal))
			{
				throw new ArgumentException("Identifier cannot have leading or trailing whitespace.", parameterName);
			}
			if (Encoding.UTF8.GetByteCount(value) > 128)
			{
				throw new ArgumentException($"Identifier cannot exceed {128} UTF-8 bytes.", parameterName);
			}
			if (value.Any(delegate(char character)
			{
				bool flag;
				switch (character)
				{
				case '-':
				case '.':
				case '0':
				case '1':
				case '2':
				case '3':
				case '4':
				case '5':
				case '6':
				case '7':
				case '8':
				case '9':
				case 'A':
				case 'B':
				case 'C':
				case 'D':
				case 'E':
				case 'F':
				case 'G':
				case 'H':
				case 'I':
				case 'J':
				case 'K':
				case 'L':
				case 'M':
				case 'N':
				case 'O':
				case 'P':
				case 'Q':
				case 'R':
				case 'S':
				case 'T':
				case 'U':
				case 'V':
				case 'W':
				case 'X':
				case 'Y':
				case 'Z':
				case '_':
				case 'a':
				case 'b':
				case 'c':
				case 'd':
				case 'e':
				case 'f':
				case 'g':
				case 'h':
				case 'i':
				case 'j':
				case 'k':
				case 'l':
				case 'm':
				case 'n':
				case 'o':
				case 'p':
				case 'q':
				case 'r':
				case 's':
				case 't':
				case 'u':
				case 'v':
				case 'w':
				case 'x':
				case 'y':
				case 'z':
					flag = true;
					break;
				default:
					flag = false;
					break;
				}
				return !flag && (!allowSlash || character != '/');
			}))
			{
				throw new ArgumentException("Identifier contains an unsupported character.", parameterName);
			}
		}

		private static void ValidateRate(int value, int maximum, string parameterName)
		{
			if (value < 0 || value > maximum)
			{
				throw new ArgumentOutOfRangeException(parameterName, value, $"Rate must be zero or between 1 and {maximum}.");
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Owns one routed endpoint registration. Dispose it to withdraw the endpoint from the current and future
	///         sessions. Disposal clears queued callbacks but does not abort a callback already executing.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         拥有一个路由端点注册。释放后会从当前及未来会话撤回该端点；释放会清除排队中的回调，但不会中止已经开始执行的回调。
	///     </para>
	/// </summary>
	public sealed class RitsuLibSidecarEndpointHandle : IDisposable
	{
		private readonly RitsuLibSidecarEndpointRegistration _registration;

		/// <summary>
		///     <para xml:lang="en">Immutable descriptor supplied when the endpoint was registered.</para>
		///     <para xml:lang="zh-CN">注册端点时提供的不可变描述符。</para>
		/// </summary>
		public RitsuLibSidecarEndpointDescriptor Descriptor => _registration.Descriptor;

		/// <summary>
		///     <para xml:lang="en">Whether this registration has been disposed.</para>
		///     <para xml:lang="zh-CN">此注册是否已经释放。</para>
		/// </summary>
		public bool IsDisposed => _registration.IsDisposed;

		/// <summary>
		///     <para xml:lang="en">
		///         Raised after the negotiated protocol version or compatible participant set changes. Handlers follow
		///         the endpoint's dispatch mode and exceptions are isolated.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在协商协议版本或兼容参与方集合变化后引发。处理器遵循端点的调度模式，且异常会被隔离。
		///     </para>
		/// </summary>
		public event Action<RitsuLibSidecarEndpointParticipantsChangedEvent> ParticipantsChanged
		{
			add
			{
				_registration.ParticipantsChanged += value;
			}
			remove
			{
				_registration.ParticipantsChanged -= value;
			}
		}

		internal RitsuLibSidecarEndpointHandle(RitsuLibSidecarEndpointRegistration registration)
		{
			_registration = registration;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns an immutable snapshot of compatible route participants. An empty result means no route is
		///         currently available.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回兼容路由参与方的不可变快照。空结果表示当前没有可用路由。
		///     </para>
		/// </summary>
		public IReadOnlyList<ulong> GetParticipantsSnapshot()
		{
			RitsuLibSidecarEndpointRouteDefinition? route = _registration.GetRoute();
			if (!route.HasValue)
			{
				return Array.Empty<ulong>();
			}
			return Array.AsReadOnly(route.GetValueOrDefault().ParticipantNetIds.ToArray());
		}

		/// <summary>
		///     <para xml:lang="en">Sends one message to the host when the host participates in this route.</para>
		///     <para xml:lang="zh-CN">当主机参与此路由时，向主机发送一条消息。</para>
		/// </summary>
		/// <param name="payload">
		///     <para xml:lang="en">Logical payload copied before this method returns.</para>
		///     <para xml:lang="zh-CN">会在此方法返回前复制的逻辑载荷。</para>
		/// </param>
		public RitsuLibSidecarSendResult SendToHost(ReadOnlySpan<byte> payload)
		{
			return RitsuLibSidecarEndpointProtocol.Send(_registration, RitsuLibSidecarEndpointDestination.Host, 0uL, payload);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sends one message to every other active participant. Relay-group participants may call it; for a
		///         host-authority endpoint only the host may call it. It never echoes to the sender.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         向其他所有活动参与方发送一条消息。中继组参与方可以调用；主机权威端点中仅主机可以调用。
		///         此操作绝不会回送给发送者。
		///     </para>
		/// </summary>
		/// <param name="payload">
		///     <para xml:lang="en">Logical payload copied before this method returns.</para>
		///     <para xml:lang="zh-CN">会在此方法返回前复制的逻辑载荷。</para>
		/// </param>
		public RitsuLibSidecarSendResult Broadcast(ReadOnlySpan<byte> payload)
		{
			return RitsuLibSidecarEndpointProtocol.Send(_registration, RitsuLibSidecarEndpointDestination.Broadcast, 0uL, payload);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sends one message to another active participant through the host. Relay-group participants may call it;
		///         for a host-authority endpoint only the host may call it.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过主机向另一个活动参与方发送一条消息。中继组参与方可以调用；主机权威端点中仅主机可以调用。
		///     </para>
		/// </summary>
		/// <param name="peerNetId">
		///     <para xml:lang="en">Nonzero destination session peer ID; it cannot be the local sender.</para>
		///     <para xml:lang="zh-CN">非零的目标会话对等方 ID；不能是本地发送者自身。</para>
		/// </param>
		/// <param name="payload">
		///     <para xml:lang="en">Logical payload copied before this method returns.</para>
		///     <para xml:lang="zh-CN">会在此方法返回前复制的逻辑载荷。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentOutOfRangeException">
		///     <para xml:lang="en"><paramref name="peerNetId" /> is zero.</para>
		///     <para xml:lang="zh-CN"><paramref name="peerNetId" /> 为零。</para>
		/// </exception>
		public RitsuLibSidecarSendResult SendToPeer(ulong peerNetId, ReadOnlySpan<byte> payload)
		{
			ArgumentOutOfRangeException.ThrowIfZero(peerNetId, "peerNetId");
			return RitsuLibSidecarEndpointProtocol.Send(_registration, RitsuLibSidecarEndpointDestination.Peer, peerNetId, payload);
		}

		/// <summary>
		///     <para xml:lang="en">Withdraws this endpoint registration. Repeated calls are safe.</para>
		///     <para xml:lang="zh-CN">撤回此端点注册；重复调用是安全的。</para>
		/// </summary>
		public void Dispose()
		{
			_registration.Dispose();
		}
	}
	/// <summary>
	///     <para xml:lang="en">Registers backend-independent, host-routed Sidecar data endpoints.</para>
	///     <para xml:lang="zh-CN">注册后端无关、由主机路由的 Sidecar 数据端点。</para>
	/// </summary>
	public static class RitsuLibSidecarEndpoints
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Registers one endpoint for the process lifetime or until the returned handle is disposed. Duplicate
		///         owner/name pairs are rejected and never replace an existing registration.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册一个持续到进程结束或返回句柄被释放的端点。重复的所有者/名称组合会被拒绝，绝不会替换已有注册。
		///     </para>
		/// </summary>
		/// <param name="descriptor">
		///     <para xml:lang="en">Validated immutable endpoint contract.</para>
		///     <para xml:lang="zh-CN">经过验证的不可变端点契约。</para>
		/// </param>
		/// <param name="handler">
		///     <para xml:lang="en">
		///         Receive callback. Exceptions are logged and isolated from transport dispatch.
		///     </para>
		///     <para xml:lang="zh-CN">接收回调。异常会被记录，并与传输分发隔离。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">An owning registration handle.</para>
		///     <para xml:lang="zh-CN">拥有该注册的句柄。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">The descriptor or handler is null.</para>
		///     <para xml:lang="zh-CN">描述符或处理器为空。</para>
		/// </exception>
		/// <exception cref="T:System.InvalidOperationException">
		///     <para xml:lang="en">The endpoint is already registered or the local registration limit was reached.</para>
