		internal Task<RitsuLibSidecarBulkTransferResult> SendAsync(RitsuLibSidecarEndpointDestination destination, ulong targetNetId, Stream source, long length, RitsuLibSidecarBulkStreamMetadata? metadata, IProgress<RitsuLibSidecarBulkStreamProgress>? progress, CancellationToken cancellationToken)
		{
			ArgumentNullException.ThrowIfNull(source, "source");
			if (!source.CanRead)
			{
				throw new ArgumentException("Bulk stream source must be readable.", "source");
			}
			if (length < 0 || length > Options.MaxStreamBytes)
			{
				throw new ArgumentOutOfRangeException("length", length, $"Length must be between zero and {Options.MaxStreamBytes} bytes.");
			}
			if (Volatile.Read(in _disposed) != 0 || _registration.IsDisposed)
			{
				return Task.FromResult(new RitsuLibSidecarBulkTransferResult(0uL, 0uL, RitsuLibSidecarBulkTransferStatus.EndpointDisposed, 0L));
			}
			if (cancellationToken.IsCancellationRequested)
			{
				return Task.FromResult(new RitsuLibSidecarBulkTransferResult(0uL, 0uL, RitsuLibSidecarBulkTransferStatus.Canceled, 0L));
			}
			ulong num = ResolveRemotePeer(destination, targetNetId);
			if (num == 0L)
			{
				return Task.FromResult(new RitsuLibSidecarBulkTransferResult(0uL, 0uL, RitsuLibSidecarBulkTransferStatus.ProtocolError, 0L));
			}
			RitsuLibSidecarBulkTransferCoordinator.Lease lease = RitsuLibSidecarBulkTransferCoordinator.TryAcquireOutbound();
			if (lease == null)
			{
				return Task.FromResult(new RitsuLibSidecarBulkTransferResult(0uL, num, RitsuLibSidecarBulkTransferStatus.ResourceLimit, 0L));
			}
			OutboundTransfer state;
			using (_gate.EnterScope())
			{
				if (_disposed != 0 || _outbound.Count >= Options.MaxConcurrentOutboundStreams)
				{
					lease.Dispose();
					return Task.FromResult(new RitsuLibSidecarBulkTransferResult(0uL, num, (_disposed != 0) ? RitsuLibSidecarBulkTransferStatus.EndpointDisposed : RitsuLibSidecarBulkTransferStatus.ResourceLimit, 0L));
				}
				ulong num2 = AllocateTransferId();
				state = new OutboundTransfer(num2, num, destination, targetNetId, source, length, metadata ?? new RitsuLibSidecarBulkStreamMetadata(), progress, CancellationTokenSource.CreateLinkedTokenSource(cancellationToken), lease);
				_outbound.Add(num2, state);
			}
			Task.Run(() => RunOutboundAsync(state), CancellationToken.None);
			return state.Completion.Task;
		}

		internal void HandleMessage(RitsuLibSidecarEndpointMessage message)
		{
			if (Volatile.Read(in _disposed) == 0 && RitsuLibSidecarBulkBinary.TryReadFrame(message.Payload, out var frame))
			{
				switch (frame.Type)
				{
				case RitsuLibSidecarBulkFrameType.Offer:
					HandleOffer(message, frame);
					break;
				case RitsuLibSidecarBulkFrameType.Accept:
					HandleAccept(message.OriginalSenderNetId, frame);
					break;
				case RitsuLibSidecarBulkFrameType.Data:
					HandleData(message.OriginalSenderNetId, frame);
					break;
				case RitsuLibSidecarBulkFrameType.Acknowledge:
					HandleAcknowledge(message.OriginalSenderNetId, frame);
					break;
				case RitsuLibSidecarBulkFrameType.Complete:
					HandleComplete(message.OriginalSenderNetId, frame);
					break;
				case RitsuLibSidecarBulkFrameType.Completed:
					HandleCompleted(message.OriginalSenderNetId, frame.TransferId);
					break;
				case RitsuLibSidecarBulkFrameType.Abort:
					HandleAbort(message.OriginalSenderNetId, frame);
					break;
				}
			}
		}

		internal void Tick()
		{
			long now = Environment.TickCount64;
			InboundTransfer[] array;
			using (_gate.EnterScope())
			{
				array = _inbound.Values.Where((InboundTransfer inboundTransfer) => (double)(now - Volatile.Read(in inboundTransfer.LastActivityTick)) > Options.IdleTimeout.TotalMilliseconds).ToArray();
				InboundKey[] array2 = (from pair in _recentlyCompleted
					where pair.Value <= now
					select pair.Key).ToArray();
				foreach (InboundKey key in array2)
				{
					_recentlyCompleted.Remove(key);
				}
			}
			InboundTransfer[] array3 = array;
			foreach (InboundTransfer state in array3)
			{
				AbortInbound(state, RitsuLibSidecarBulkTransferStatus.TimedOut, notifyRemote: true);
			}
		}

		internal void RouteChanged()
		{
