			{
				AbortAll(RitsuLibSidecarBulkTransferStatus.EndpointDisposed);
			}
		}

		private async Task RunOutboundAsync(OutboundTransfer state)
		{
			_ = 6;
			try
			{
				byte[] offer = RitsuLibSidecarBulkBinary.WriteOffer(state.TransferId, state.TotalLength, Options.PreferredChunkBytes, Options.ReceiveWindowBytes, state.Metadata);
				RitsuLibSidecarBulkFrame? ritsuLibSidecarBulkFrame = await SendOfferAndWaitForAcceptAsync(state, offer).ConfigureAwait(continueOnCapturedContext: false);
				if (!ritsuLibSidecarBulkFrame.HasValue)
				{
					return;
				}
				RitsuLibSidecarBulkFrame valueOrDefault = ritsuLibSidecarBulkFrame.GetValueOrDefault();
				state.ChunkBytes = valueOrDefault.ChunkBytes;
				state.WindowBytes = valueOrDefault.WindowBytes;
				using IncrementalHash hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
				while (state.SentOffset < state.TotalLength)
				{
					if (!(await WaitForWindowSpaceAsync(state).ConfigureAwait(continueOnCapturedContext: false)))
					{
						if (!IsTerminal(state))
						{
							TrySendAbort(state, RitsuLibSidecarBulkTransferStatus.TimedOut);
							CompleteOutbound(state, RitsuLibSidecarBulkTransferStatus.TimedOut);
						}
						return;
					}
					if (IsTerminal(state))
					{
						return;
					}
					int num;
					using (state.Gate.EnterScope())
					{
						long val = state.TotalLength - state.SentOffset;
						long val2 = state.WindowBytes - (state.SentOffset - state.ConfirmedOffset);
						num = (int)Math.Min(Math.Min(val, val2), state.ChunkBytes);
					}
					if (num > 0)
					{
						byte[] data = GC.AllocateUninitializedArray<byte>(num);
						if (!(await ReadExactlyAsync(state.Source, data, state.Cancellation.Token).ConfigureAwait(continueOnCapturedContext: false)))
						{
							TrySendAbort(state, RitsuLibSidecarBulkTransferStatus.SourceFailed);
							CompleteOutbound(state, RitsuLibSidecarBulkTransferStatus.SourceFailed);
							return;
						}
						hash.AppendData(data);
						byte[] frame;
						using (state.Gate.EnterScope())
						{
							frame = RitsuLibSidecarBulkBinary.WriteData(state.TransferId, state.SentOffset, data);
							state.Unacknowledged.Add(state.SentOffset, new OutboundChunk(frame, state.SentOffset + data.Length));
							state.SentOffset += data.Length;
						}
						RitsuLibSidecarSendStatus ritsuLibSidecarSendStatus = await QueueFrameWithBackpressureAsync(state, frame).ConfigureAwait(continueOnCapturedContext: false);
						if (ritsuLibSidecarSendStatus != RitsuLibSidecarSendStatus.Accepted)
						{
							CompleteOutbound(state, MapSendStatus(ritsuLibSidecarSendStatus));
							return;
						}
					}
				}
				if (!(await WaitForAcknowledgementAsync(state, state.TotalLength).ConfigureAwait(continueOnCapturedContext: false)))
				{
					if (!IsTerminal(state))
					{
						TrySendAbort(state, RitsuLibSidecarBulkTransferStatus.TimedOut);
						CompleteOutbound(state, RitsuLibSidecarBulkTransferStatus.TimedOut);
					}
					return;
				}
				byte[] hashAndReset = hash.GetHashAndReset();
				byte[] complete = RitsuLibSidecarBulkBinary.WriteComplete(state.TransferId, state.TotalLength, hashAndReset);
				for (int attempt = 0; attempt <= Options.MaxRetransmissions; attempt++)
				{
					if (attempt > 0)
					{
						Interlocked.Increment(ref _retransmittedFrames);
					}
					RitsuLibSidecarSendStatus ritsuLibSidecarSendStatus2 = await QueueFrameWithBackpressureAsync(state, complete).ConfigureAwait(continueOnCapturedContext: false);
					if (ritsuLibSidecarSendStatus2 != RitsuLibSidecarSendStatus.Accepted)
					{
						CompleteOutbound(state, MapSendStatus(ritsuLibSidecarSendStatus2));
						return;
					}
					if (await WaitForSignalAsync(state.CompletedSignal, Options.AcknowledgementTimeout, state.Cancellation.Token).ConfigureAwait(continueOnCapturedContext: false))
					{
						CompleteOutbound(state, RitsuLibSidecarBulkTransferStatus.Completed);
						return;
					}
				}
				TrySendAbort(state, RitsuLibSidecarBulkTransferStatus.TimedOut);
				CompleteOutbound(state, RitsuLibSidecarBulkTransferStatus.TimedOut);
			}
			catch (OperationCanceledException)
			{
				if (!IsTerminal(state))
				{
					TrySendAbort(state, RitsuLibSidecarBulkTransferStatus.Canceled);
					CompleteOutbound(state, RitsuLibSidecarBulkTransferStatus.Canceled);
				}
			}
			catch (Exception ex2) when (((ex2 is IOException || ex2 is ObjectDisposedException) ? 1 : 0) != 0)
			{
				TrySendAbort(state, RitsuLibSidecarBulkTransferStatus.SourceFailed);
				CompleteOutbound(state, RitsuLibSidecarBulkTransferStatus.SourceFailed);
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[SidecarBulk] Outbound transfer failed unexpectedly for {_registration.Descriptor.OwnerId}/{_registration.Descriptor.Name}: {value}");
				TrySendAbort(state, RitsuLibSidecarBulkTransferStatus.SourceFailed);
				CompleteOutbound(state, RitsuLibSidecarBulkTransferStatus.SourceFailed);
			}
			finally
			{
				state.Cancellation.Dispose();
				state.AcknowledgementSignal.Dispose();
				state.CompletedSignal.Dispose();
			}
		}

		private async Task<RitsuLibSidecarBulkFrame?> SendOfferAndWaitForAcceptAsync(OutboundTransfer state, byte[] offer)
		{
			for (int attempt = 0; attempt <= Options.MaxRetransmissions; attempt++)
			{
				if (attempt > 0)
				{
					Interlocked.Increment(ref _retransmittedFrames);
				}
				RitsuLibSidecarSendStatus ritsuLibSidecarSendStatus = await QueueFrameWithBackpressureAsync(state, offer).ConfigureAwait(continueOnCapturedContext: false);
				if (ritsuLibSidecarSendStatus != RitsuLibSidecarSendStatus.Accepted)
				{
					CompleteOutbound(state, MapSendStatus(ritsuLibSidecarSendStatus));
					return null;
				}
				try
				{
					return await state.Accepted.Task.WaitAsync(Options.AcknowledgementTimeout, state.Cancellation.Token).ConfigureAwait(continueOnCapturedContext: false);
				}
				catch (TimeoutException) when (attempt < Options.MaxRetransmissions)
				{
				}
			}
			TrySendAbort(state, RitsuLibSidecarBulkTransferStatus.TimedOut);
			CompleteOutbound(state, RitsuLibSidecarBulkTransferStatus.TimedOut);
			return null;
		}

		private async Task<bool> WaitForWindowSpaceAsync(OutboundTransfer state)
		{
			long confirmedOffset;
			do
			{
				long sentOffset;
				using (state.Gate.EnterScope())
				{
					sentOffset = state.SentOffset;
					confirmedOffset = state.ConfirmedOffset;
				}
				if (sentOffset - confirmedOffset < state.WindowBytes)
				{
					return true;
				}
			}
			while (await WaitForAcknowledgementAsync(state, confirmedOffset + 1).ConfigureAwait(continueOnCapturedContext: false));
			return false;
		}

		private async Task<bool> WaitForAcknowledgementAsync(OutboundTransfer state, long minimumOffset)
		{
			int retransmissions = 0;
			while (!IsTerminal(state))
			{
				using (state.Gate.EnterScope())
				{
					if (state.ConfirmedOffset >= minimumOffset)
					{
						return true;
					}
				}
				if (await WaitForSignalAsync(state.AcknowledgementSignal, Options.AcknowledgementTimeout, state.Cancellation.Token).ConfigureAwait(continueOnCapturedContext: false))
				{
					continue;
				}
				if (retransmissions >= Options.MaxRetransmissions)
				{
					return false;
				}
				retransmissions++;
				byte[][] array;
				using (state.Gate.EnterScope())
				{
					array = state.Unacknowledged.Values.Select((OutboundChunk chunk) => chunk.Frame).ToArray();
				}
				byte[][] array2 = array;
				foreach (byte[] frame in array2)
				{
					Interlocked.Increment(ref _retransmittedFrames);
					RitsuLibSidecarSendStatus ritsuLibSidecarSendStatus = await QueueFrameWithBackpressureAsync(state, frame).ConfigureAwait(continueOnCapturedContext: false);
					if (ritsuLibSidecarSendStatus != RitsuLibSidecarSendStatus.Accepted)
					{
						CompleteOutbound(state, MapSendStatus(ritsuLibSidecarSendStatus));
						return false;
					}
				}
			}
			return false;
		}

		private async Task<RitsuLibSidecarSendStatus> QueueFrameWithBackpressureAsync(OutboundTransfer state, byte[] frame)
		{
			long started = Environment.TickCount64;
			while (!IsTerminal(state))
			{
				RitsuLibSidecarSendResult ritsuLibSidecarSendResult = RitsuLibSidecarEndpointProtocol.Send(_registration, state.Destination, state.TargetNetId, frame);
				if (ritsuLibSidecarSendResult.Status == RitsuLibSidecarSendStatus.Accepted)
				{
					Volatile.Write(ref state.LastActivityTick, Environment.TickCount64);
					return ritsuLibSidecarSendResult.Status;
				}
				RitsuLibSidecarSendStatus status = ritsuLibSidecarSendResult.Status;
				bool flag = (uint)(status - 7) <= 1u;
				if (!flag || (double)(Environment.TickCount64 - started) > Options.IdleTimeout.TotalMilliseconds)
				{
					return ritsuLibSidecarSendResult.Status;
				}
				await Task.Delay(10, state.Cancellation.Token).ConfigureAwait(continueOnCapturedContext: false);
			}
