		private static bool TrySelectRoute(RitsuLibSidecarEndpointKey key, IReadOnlyList<AdvertisedParticipant> allParticipants, ulong hostNetId, RitsuLibSidecarTransportProfileMask hostProfiles, IReadOnlyDictionary<RitsuLibSidecarEndpointKey, HostRouteState> previousRoutes, out RitsuLibSidecarEndpointRouteDefinition definition)
