			Action<RitsuLibSidecarEndpointParticipantsChangedEvent> handlers;
			RitsuLibSidecarEndpointParticipantsChangedEvent changed;
			using (_dispatchGate.EnterScope())
			{
				if (RoutesEquivalent(_route, route))
				{
					return;
				}
				_route = route;
				handlers = _participantsChanged;
				RitsuLibSidecarEndpointParticipantsChangedEvent ritsuLibSidecarEndpointParticipantsChangedEvent;
				if (route.HasValue)
				{
					RitsuLibSidecarEndpointRouteDefinition valueOrDefault = route.GetValueOrDefault();
					ritsuLibSidecarEndpointParticipantsChangedEvent = new RitsuLibSidecarEndpointParticipantsChangedEvent(valueOrDefault.ProtocolVersion, Array.AsReadOnly(valueOrDefault.ParticipantNetIds.ToArray()));
				}
				else
				{
					ritsuLibSidecarEndpointParticipantsChangedEvent = new RitsuLibSidecarEndpointParticipantsChangedEvent(0, Array.Empty<ulong>());
				}
				changed = ritsuLibSidecarEndpointParticipantsChangedEvent;
			}
			BulkTransfers?.RouteChanged();
			if (handlers == null)
			{
				return;
			}
			TryScheduleCallback(delegate
			{
				foreach (Action<RitsuLibSidecarEndpointParticipantsChangedEvent> handler in handlers.GetInvocationList().Cast<Action<RitsuLibSidecarEndpointParticipantsChangedEvent>>())
				{
					InvokeSafely(delegate
					{
						handler(changed);
					}, "participant-change");
				}
			}, 0);
		}

		internal void Dispatch(RitsuLibSidecarEndpointMessage message)
		{
			if (BulkTransfers != null)
			{
				BulkTransfers.HandleMessage(message);
				return;
			}
			TryScheduleCallback(delegate
			{
				InvokeSafely(delegate
				{
					_handler(message);
				}, "message");
			}, message.Payload.Length);
		}

		internal void Dispose()
		{
			if (Interlocked.Exchange(ref _disposeStarted, 1) != 0)
			{
				return;
			}
			BulkTransfers?.Dispose();
			Volatile.Write(ref _disposed, 1);
			RitsuLibSidecarOutboundScheduler.RemoveEndpoint(this);
			RitsuLibSidecarEndpointRegistry.Unregister(this);
			using (_dispatchGate.EnterScope())
			{
				_route = null;
				_participantsChanged = null;
				_backgroundActions.Clear();
				_backgroundDispatchBytes = 0;
				_mainLoopDispatchBytes = 0;
				_mainLoopDispatchMessages = 0;
			}
		}

		internal bool TryScheduleCallback(Action action, int payloadBytes)
		{
			if (Volatile.Read(in _disposeStarted) != 0)
			{
				return false;
			}
			switch (Descriptor.DispatchMode)
			{
			case RitsuLibSidecarEndpointDispatchMode.ReceiveThread:
				action();
				return true;
			case RitsuLibSidecarEndpointDispatchMode.GodotMainLoop:
				if (!TryReserveMainLoopDispatch(payloadBytes))
				{
					WarnDispatchQueueFull("main-loop");
					return false;
				}
				if (!RitsuLibSidecarGodotMainLoopScheduling.TryPostToMainLoop(delegate
				{
					try
					{
						if (!IsDisposed)
						{
							action();
						}
					}
					finally
					{
						ReleaseMainLoopDispatch(payloadBytes);
					}
				}))
				{
					ReleaseMainLoopDispatch(payloadBytes);
					RitsuLibSidecarRepeatedWarningLog.Warn("endpoint-main-loop-unavailable:" + Descriptor.OwnerId + "/" + Descriptor.Name, $"[SidecarEndpoints] Main loop unavailable; dropped callback for {Descriptor.OwnerId}/{Descriptor.Name}.");
					return false;
				}
				return true;
			case RitsuLibSidecarEndpointDispatchMode.BackgroundSerial:
				return EnqueueBackground(action, payloadBytes);
			default:
				throw new ArgumentOutOfRangeException();
			}
		}

		private bool EnqueueBackground(Action action, int payloadBytes)
		{
			using (_dispatchGate.EnterScope())
			{
				if (Volatile.Read(in _disposeStarted) != 0)
				{
					return false;
				}
				if (_backgroundActions.Count >= 512 || _backgroundDispatchBytes + payloadBytes > 2097152)
				{
					WarnDispatchQueueFull("background");
					return false;
				}
				_backgroundDispatchBytes += payloadBytes;
				_backgroundActions.Enqueue(new BackgroundAction(action, payloadBytes));
				if (_backgroundDispatchRunning)
				{
					return true;
				}
				_backgroundDispatchRunning = true;
			}
			Task.Run((Action)ProcessBackgroundQueue);
			return true;
		}

		private bool TryReserveMainLoopDispatch(int payloadBytes)
		{
			using (_dispatchGate.EnterScope())
			{
				if (IsDisposed || _mainLoopDispatchMessages >= 512 || _mainLoopDispatchBytes + payloadBytes > 2097152)
				{
					return false;
				}
				_mainLoopDispatchMessages++;
				_mainLoopDispatchBytes += payloadBytes;
				return true;
			}
		}

		private void ReleaseMainLoopDispatch(int payloadBytes)
		{
			using (_dispatchGate.EnterScope())
			{
				_mainLoopDispatchMessages = Math.Max(0, _mainLoopDispatchMessages - 1);
				_mainLoopDispatchBytes = Math.Max(0, _mainLoopDispatchBytes - payloadBytes);
			}
		}

		private void WarnDispatchQueueFull(string queueName)
		{
			RitsuLibSidecarRepeatedWarningLog.Warn($"endpoint-{queueName}-queue-full:{Descriptor.OwnerId}/{Descriptor.Name}", $"[SidecarEndpoints] {queueName} callback queue full; dropped callback for {Descriptor.OwnerId}/{Descriptor.Name}.");
		}

		private void ProcessBackgroundQueue()
		{
			while (true)
			{
				BackgroundAction backgroundAction;
				using (_dispatchGate.EnterScope())
				{
					if (IsDisposed || _backgroundActions.Count == 0)
					{
						_backgroundActions.Clear();
						_backgroundDispatchBytes = 0;
						_backgroundDispatchRunning = false;
						break;
					}
					backgroundAction = _backgroundActions.Dequeue();
					_backgroundDispatchBytes -= backgroundAction.PayloadBytes;
				}
				backgroundAction.Action();
			}
		}

		private void InvokeSafely(Action action, string operation)
		{
			try
			{
				action();
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[SidecarEndpoints] Endpoint {operation} callback failed for {Descriptor.OwnerId}/{Descriptor.Name}: {value}");
			}
		}

		private static bool RoutesEquivalent(RitsuLibSidecarEndpointRouteDefinition? left, RitsuLibSidecarEndpointRouteDefinition? right)
		{
			if (!left.HasValue || !right.HasValue)
			{
				if (!left.HasValue)
				{
					return !right.HasValue;
				}
				return false;
			}
			RitsuLibSidecarEndpointRouteDefinition value = left.Value;
			RitsuLibSidecarEndpointRouteDefinition value2 = right.Value;
			if (value.RouteId == value2.RouteId && value.Nonce == value2.Nonce && value.ProtocolVersion == value2.ProtocolVersion && value.MaxPayloadBytes == value2.MaxPayloadBytes)
			{
				return value.ParticipantNetIds.SequenceEqual(value2.ParticipantNetIds);
			}
			return false;
		}
	}
	internal static class RitsuLibSidecarEndpointRegistry
	{
		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<RitsuLibSidecarEndpointKey, RitsuLibSidecarEndpointRegistration> Registrations = new Dictionary<RitsuLibSidecarEndpointKey, RitsuLibSidecarEndpointRegistration>();

		internal static RitsuLibSidecarEndpointHandle Register(RitsuLibSidecarEndpointDescriptor descriptor, Action<RitsuLibSidecarEndpointMessage> handler)
		{
			ArgumentNullException.ThrowIfNull(descriptor, "descriptor");
			ArgumentNullException.ThrowIfNull(handler, "handler");
			if (descriptor.DeliveryProfile == RitsuLibSidecarDeliveryProfile.BulkStream)
			{
				throw new ArgumentException("Bulk-stream endpoints must be registered through RitsuLibSidecarEndpoints.RegisterBulk.", "descriptor");
			}
			RitsuLibSidecarEndpointProtocol.EnsureRegistered();
			RitsuLibSidecarEndpointRegistration ritsuLibSidecarEndpointRegistration;
			using (Gate.EnterScope())
			{
				if (Registrations.Count >= 64)
				{
					throw new InvalidOperationException($"No more than {64} routed endpoints may be registered.");
				}
				RitsuLibSidecarEndpointKey key = new RitsuLibSidecarEndpointKey(descriptor.OwnerId, descriptor.Name);
				if (Registrations.ContainsKey(key))
				{
					throw new InvalidOperationException($"Endpoint '{descriptor.OwnerId}/{descriptor.Name}' is already registered.");
				}
				ritsuLibSidecarEndpointRegistration = new RitsuLibSidecarEndpointRegistration(descriptor, handler);
				Registrations.Add(key, ritsuLibSidecarEndpointRegistration);
			}
			RitsuLibSidecarEndpointProtocol.OnLocalCatalogChanged();
			return ritsuLibSidecarEndpointRegistration.Handle;
		}

		internal static RitsuLibSidecarBulkEndpointHandle RegisterBulk(RitsuLibSidecarEndpointDescriptor descriptor, RitsuLibSidecarBulkStreamOptions options, Func<RitsuLibSidecarBulkStreamOffer, RitsuLibSidecarBulkReceiveTarget?> handler)
		{
			ArgumentNullException.ThrowIfNull(descriptor, "descriptor");
			ArgumentNullException.ThrowIfNull(options, "options");
			ArgumentNullException.ThrowIfNull(handler, "handler");
			if (descriptor.DeliveryProfile != RitsuLibSidecarDeliveryProfile.BulkStream)
			{
				throw new ArgumentException("A bulk-stream registration requires the BulkStream delivery profile.", "descriptor");
			}
			RitsuLibSidecarEndpointProtocol.EnsureRegistered();
			RitsuLibSidecarEndpointRegistration ritsuLibSidecarEndpointRegistration;
			using (Gate.EnterScope())
			{
				if (Registrations.Count >= 64)
				{
					throw new InvalidOperationException($"No more than {64} routed endpoints may be registered.");
				}
				RitsuLibSidecarEndpointKey key = new RitsuLibSidecarEndpointKey(descriptor.OwnerId, descriptor.Name);
				if (Registrations.ContainsKey(key))
				{
					throw new InvalidOperationException($"Endpoint '{descriptor.OwnerId}/{descriptor.Name}' is already registered.");
				}
				ritsuLibSidecarEndpointRegistration = new RitsuLibSidecarEndpointRegistration(descriptor, options, handler);
				Registrations.Add(key, ritsuLibSidecarEndpointRegistration);
			}
			RitsuLibSidecarEndpointProtocol.OnLocalCatalogChanged();
			return ritsuLibSidecarEndpointRegistration.BulkHandle;
		}

		internal static void Unregister(RitsuLibSidecarEndpointRegistration registration)
		{
			bool flag = false;
			using (Gate.EnterScope())
			{
				RitsuLibSidecarEndpointKey key = new RitsuLibSidecarEndpointKey(registration.Descriptor.OwnerId, registration.Descriptor.Name);
				if (Registrations.TryGetValue(key, out RitsuLibSidecarEndpointRegistration value) && value == registration)
				{
					flag = Registrations.Remove(key);
				}
			}
			if (flag)
			{
				RitsuLibSidecarEndpointProtocol.OnLocalCatalogChanged();
			}
		}

		internal static bool TryGet(RitsuLibSidecarEndpointKey key, out RitsuLibSidecarEndpointRegistration? registration)
		{
			using (Gate.EnterScope())
			{
				return Registrations.TryGetValue(key, out registration);
			}
		}

		internal static RitsuLibSidecarEndpointAdvertisement[] GetAdvertisementsSnapshot()
		{
			using (Gate.EnterScope())
			{
				return (from registration in Registrations.Values
					where !registration.IsDisposed
					select new RitsuLibSidecarEndpointAdvertisement(new RitsuLibSidecarEndpointKey(registration.Descriptor.OwnerId, registration.Descriptor.Name), registration.Descriptor.ProtocolVersion, registration.Descriptor.MinimumCompatibleProtocolVersion, registration.Descriptor.DeliveryProfile, registration.Descriptor.Topology, registration.Descriptor.MaxPayloadBytes)).ToArray();
			}
		}

		internal static RitsuLibSidecarEndpointRegistration[] GetRegistrationsSnapshot()
		{
			using (Gate.EnterScope())
			{
				return Registrations.Values.Where((RitsuLibSidecarEndpointRegistration registration) => !registration.IsDisposed).ToArray();
			}
		}

		internal static void TickBulkTransfers()
		{
			RitsuLibSidecarEndpointRegistration[] registrationsSnapshot = GetRegistrationsSnapshot();
			for (int i = 0; i < registrationsSnapshot.Length; i++)
			{
				registrationsSnapshot[i].BulkTransfers?.Tick();
			}
		}
	}
	internal sealed class RitsuLibSidecarTokenBucket
	{
		private readonly Lock _gate = new Lock();

		private readonly double _packetCapacity;

		private readonly double _byteCapacity;

		private readonly double _packetsPerMillisecond;

		private readonly double _bytesPerMillisecond;

		private readonly Func<long> _tickCount64;

		private double _packetTokens;

		private double _byteTokens;

		private long _lastRefillTickCount64;

		internal RitsuLibSidecarTokenBucket(int packetsPerSecond, int bytesPerSecond)
			: this(packetsPerSecond, bytesPerSecond, () => Environment.TickCount64)
		{
		}

		internal RitsuLibSidecarTokenBucket(int packetsPerSecond, int bytesPerSecond, Func<long> tickCount64)
		{
			ArgumentOutOfRangeException.ThrowIfLessThan(packetsPerSecond, 1, "packetsPerSecond");
			ArgumentOutOfRangeException.ThrowIfLessThan(bytesPerSecond, 1, "bytesPerSecond");
			ArgumentNullException.ThrowIfNull(tickCount64, "tickCount64");
			_packetCapacity = packetsPerSecond;
			_byteCapacity = bytesPerSecond;
			_packetsPerMillisecond = (double)packetsPerSecond / 1000.0;
			_bytesPerMillisecond = (double)bytesPerSecond / 1000.0;
			_tickCount64 = tickCount64;
			_packetTokens = _packetCapacity;
			_byteTokens = _byteCapacity;
			_lastRefillTickCount64 = _tickCount64();
		}

		internal bool TryConsume(int bytes)
		{
			ArgumentOutOfRangeException.ThrowIfNegative(bytes, "bytes");
			using (_gate.EnterScope())
			{
				Refill(_tickCount64());
				if (_packetTokens < 1.0 || _byteTokens < (double)bytes)
				{
					return false;
				}
				_packetTokens--;
				_byteTokens -= bytes;
				return true;
			}
		}

		private void Refill(long now)
		{
			long num = now - _lastRefillTickCount64;
			if (num > 0)
			{
				_packetTokens = Math.Min(_packetCapacity, _packetTokens + (double)num * _packetsPerMillisecond);
				_byteTokens = Math.Min(_byteCapacity, _byteTokens + (double)num * _bytesPerMillisecond);
				_lastRefillTickCount64 = now;
			}
		}
	}
