	internal static class RitsuLibSidecarBulkBinary
	{
		internal const byte Version = 1;

		internal const int CommonHeaderSize = 10;

		internal const int OfferHeaderSize = 28;

		internal const int AcceptFrameSize = 18;

		internal const int DataHeaderSize = 22;

		internal const int AcknowledgeFrameSize = 18;

		internal const int CompleteFrameSize = 50;

		internal const int CompletedFrameSize = 10;

		internal const int AbortFrameSize = 11;

		internal const int Sha256Size = 32;

		internal static byte[] WriteOffer(ulong transferId, long totalLength, int requestedChunkBytes, int requestedWindowBytes, RitsuLibSidecarBulkStreamMetadata metadata)
		{
			ValidateTransferId(transferId);
			ArgumentNullException.ThrowIfNull(metadata, "metadata");
			ValidateLength(totalLength);
			ValidateChunkAndWindow(requestedChunkBytes, requestedWindowBytes);
			byte[] array = EncodeOptional(metadata.Name);
			byte[] array2 = EncodeOptional(metadata.ContentType);
			if (array.Length > 255 || array2.Length > 127)
			{
				throw new ArgumentOutOfRangeException("metadata");
			}
			byte[] array3 = new byte[28 + array.Length + array2.Length];
			WriteCommon(array3, RitsuLibSidecarBulkFrameType.Offer, transferId);
			BinaryPrimitives.WriteInt64BigEndian(array3.AsSpan(10, 8), totalLength);
			BinaryPrimitives.WriteInt32BigEndian(array3.AsSpan(18, 4), requestedChunkBytes);
			BinaryPrimitives.WriteInt32BigEndian(array3.AsSpan(22, 4), requestedWindowBytes);
			array3[26] = (byte)array.Length;
			array3[27] = (byte)array2.Length;
			array.CopyTo(array3.AsSpan(28));
			array2.CopyTo(array3.AsSpan(28 + array.Length));
			return array3;
		}

		internal static byte[] WriteAccept(ulong transferId, int chunkBytes, int windowBytes)
		{
			ValidateTransferId(transferId);
			ValidateChunkAndWindow(chunkBytes, windowBytes);
			byte[] array = new byte[18];
			WriteCommon(array, RitsuLibSidecarBulkFrameType.Accept, transferId);
			BinaryPrimitives.WriteInt32BigEndian(array.AsSpan(10, 4), chunkBytes);
			BinaryPrimitives.WriteInt32BigEndian(array.AsSpan(14, 4), windowBytes);
			return array;
		}

		internal static byte[] WriteData(ulong transferId, long offset, ReadOnlySpan<byte> payload)
		{
			ValidateTransferId(transferId);
			ArgumentOutOfRangeException.ThrowIfNegative(offset, "offset");
			int length = payload.Length;
			if ((length < 1 || length > 32768) ? true : false)
			{
				throw new ArgumentOutOfRangeException("payload");
			}
			byte[] array = new byte[22 + payload.Length];
			WriteCommon(array, RitsuLibSidecarBulkFrameType.Data, transferId);
			BinaryPrimitives.WriteInt64BigEndian(array.AsSpan(10, 8), offset);
			BinaryPrimitives.WriteUInt32BigEndian(array.AsSpan(18, 4), Crc32.HashToUInt32(payload));
			payload.CopyTo(array.AsSpan(22));
			return array;
		}

		internal static byte[] WriteAcknowledge(ulong transferId, long nextOffset)
		{
			ValidateTransferId(transferId);
			ArgumentOutOfRangeException.ThrowIfNegative(nextOffset, "nextOffset");
			byte[] array = new byte[18];
			WriteCommon(array, RitsuLibSidecarBulkFrameType.Acknowledge, transferId);
			BinaryPrimitives.WriteInt64BigEndian(array.AsSpan(10, 8), nextOffset);
			return array;
		}

		internal static byte[] WriteComplete(ulong transferId, long totalLength, ReadOnlySpan<byte> sha256)
		{
			ValidateTransferId(transferId);
			ValidateLength(totalLength);
			if (sha256.Length != 32)
			{
				throw new ArgumentException($"SHA-256 digest must contain {32} bytes.", "sha256");
			}
			byte[] array = new byte[50];
			WriteCommon(array, RitsuLibSidecarBulkFrameType.Complete, transferId);
			BinaryPrimitives.WriteInt64BigEndian(array.AsSpan(10, 8), totalLength);
			sha256.CopyTo(array.AsSpan(18, 32));
			return array;
		}

		internal static byte[] WriteCompleted(ulong transferId)
		{
			ValidateTransferId(transferId);
			byte[] array = new byte[10];
			WriteCommon(array, RitsuLibSidecarBulkFrameType.Completed, transferId);
			return array;
		}

		internal static byte[] WriteAbort(ulong transferId, RitsuLibSidecarBulkAbortReason reason)
		{
			ValidateTransferId(transferId);
			if (!Enum.IsDefined(reason))
			{
				throw new ArgumentOutOfRangeException("reason", reason, "Invalid bulk abort reason.");
			}
			byte[] array = new byte[11];
			WriteCommon(array, RitsuLibSidecarBulkFrameType.Abort, transferId);
			array[10] = (byte)reason;
			return array;
		}

		internal static bool TryReadFrame(ReadOnlyMemory<byte> source, out RitsuLibSidecarBulkFrame frame)
		{
			frame = default(RitsuLibSidecarBulkFrame);
			if (source.Length < 10 || source.Span[0] != 1)
			{
				return false;
			}
			RitsuLibSidecarBulkFrameType ritsuLibSidecarBulkFrameType = (RitsuLibSidecarBulkFrameType)source.Span[1];
			ulong num = BinaryPrimitives.ReadUInt64BigEndian(source.Span.Slice(2, 8));
			if (num == 0L || !Enum.IsDefined(ritsuLibSidecarBulkFrameType))
			{
				return false;
			}
			switch (ritsuLibSidecarBulkFrameType)
			{
			case RitsuLibSidecarBulkFrameType.Offer:
				return TryReadOffer(source, num, out frame);
			case RitsuLibSidecarBulkFrameType.Accept:
				return TryReadAccept(source, num, out frame);
			case RitsuLibSidecarBulkFrameType.Data:
				return TryReadData(source, num, out frame);
			case RitsuLibSidecarBulkFrameType.Acknowledge:
				return TryReadAcknowledge(source, num, out frame);
			case RitsuLibSidecarBulkFrameType.Complete:
				return TryReadComplete(source, num, out frame);
			case RitsuLibSidecarBulkFrameType.Completed:
