				}
				break;
			case RitsuLibSidecarBulkFrameType.Abort:
				return TryReadAbort(source, num, out frame);
			}
			return false;
		}

		private static bool TryReadOffer(ReadOnlyMemory<byte> source, ulong transferId, out RitsuLibSidecarBulkFrame frame)
		{
			frame = default(RitsuLibSidecarBulkFrame);
			if (source.Length < 28)
			{
				return false;
