			ReadOnlySpan<byte> span = source.Span;
			long num = BinaryPrimitives.ReadInt64BigEndian(span.Slice(10, 8));
			int chunkBytes = BinaryPrimitives.ReadInt32BigEndian(span.Slice(18, 4));
			int windowBytes = BinaryPrimitives.ReadInt32BigEndian(span.Slice(22, 4));
			byte b = span[26];
			byte b2 = span[27];
			if (!IsValidLength(num) || !IsValidChunkAndWindow(chunkBytes, windowBytes) || b > byte.MaxValue || b2 > 127 || source.Length != 28 + b + b2)
			{
				return false;
			}
			if (!TryDecodeOptional(span.Slice(28, b), out string decoded) || !TryDecodeOptional(span.Slice(28 + b, b2), out string decoded2))
			{
				return false;
			}
			RitsuLibSidecarBulkStreamMetadata metadata;
