	///     </para>
	///     <para xml:lang="zh-CN">
	///         编码和解码 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarControlOpcodes.ChunkedFrame" /> 载荷。
	///     </para>
	/// </summary>
	public static class RitsuLibSidecarChunkBinary
	{
		/// <summary>
		///     <para xml:lang="en">
		///         The byte size of the fixed, big-endian frame header.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         采用大端序的固定帧头的字节数。
		///     </para>
		/// </summary>
		public const int FixedHeaderSize = 34;

		/// <summary>
		///     <para xml:lang="en">
		///         The default maximum segment-data size, excluding the fixed header.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         默认的分段数据大小上限，不包含固定帧头。
		///     </para>
		/// </summary>
		public const int DefaultMaxSegmentDataBytes = 16384;

		/// <summary>
		///     <para xml:lang="en">
		///         Writes one chunk frame and returns the total number of bytes written. The segment may not exceed
		///         <c>ushort.MaxValue</c> bytes, because its encoded length is 16-bit.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         写入一个分块帧，并返回写入的总字节数。由于编码后的长度为 16 位，分段不得超过
		///         <c>ushort.MaxValue</c> 字节。
		///     </para>
		/// </summary>
		public static int WriteFrame(Span<byte> destination, ulong userOpcode, ulong streamId, uint index, uint count, uint totalPayloadSize, ReadOnlySpan<byte> segment)
		{
			if (segment.Length > 65535)
			{
				throw new ArgumentOutOfRangeException("segment", segment.Length, $"A chunk segment cannot exceed {ushort.MaxValue} bytes.");
			}
			if (destination.Length < 34 + segment.Length)
			{
				throw new ArgumentException("Buffer too small", "destination");
			}
			uint value = Crc32.HashToUInt32(segment);
			BinaryPrimitives.WriteUInt64BigEndian(destination.Slice(0, 8), userOpcode);
			BinaryPrimitives.WriteUInt64BigEndian(destination.Slice(8, 8), streamId);
			BinaryPrimitives.WriteUInt32BigEndian(destination.Slice(16, 4), index);
			BinaryPrimitives.WriteUInt32BigEndian(destination.Slice(20, 4), count);
			BinaryPrimitives.WriteUInt32BigEndian(destination.Slice(24, 4), totalPayloadSize);
			BinaryPrimitives.WriteUInt16BigEndian(destination.Slice(28, 2), (ushort)segment.Length);
			BinaryPrimitives.WriteUInt32BigEndian(destination.Slice(30, 4), value);
			segment.CopyTo(destination.Slice(34));
			return 34 + segment.Length;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Reads one chunk frame from a complete <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarControlOpcodes.ChunkedFrame" />
		///         message body.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从完整的 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarControlOpcodes.ChunkedFrame" /> 消息体中读取一个分块帧。
		///     </para>
		/// </summary>
		public static void ReadFrame(ReadOnlySpan<byte> source, out ulong userOpcode, out ulong streamId, out uint index, out uint count, out uint totalPayloadSize, out uint segmentCrc32, out ReadOnlySpan<byte> segment)
		{
			if (source.Length < 34)
			{
				throw new ArgumentException("Buffer too small", "source");
			}
			userOpcode = BinaryPrimitives.ReadUInt64BigEndian(source.Slice(0, 8));
			streamId = BinaryPrimitives.ReadUInt64BigEndian(source.Slice(8, 8));
			index = BinaryPrimitives.ReadUInt32BigEndian(source.Slice(16, 4));
			count = BinaryPrimitives.ReadUInt32BigEndian(source.Slice(20, 4));
			totalPayloadSize = BinaryPrimitives.ReadUInt32BigEndian(source.Slice(24, 4));
			ushort num = BinaryPrimitives.ReadUInt16BigEndian(source.Slice(28, 2));
			segmentCrc32 = BinaryPrimitives.ReadUInt32BigEndian(source.Slice(30, 4));
			if (source.Length < 34 + num)
			{
				throw new ArgumentException("Truncated segment", "source");
			}
			segment = source.Slice(34, num);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Encodes and decodes control payloads for selective gap reports and reassembly acknowledgements.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         编解码用于选择性缺口报告和重组确认的控制载荷。
	///     </para>
	/// </summary>
	internal static class RitsuLibSidecarChunkGapBinary
	{
		public readonly record struct MissingRange(uint StartIndex, uint Length);

		public const int MaxMissingRangesPerMessage = 256;

		public const int ReassemblyDonePayloadSize = 8;

		public const int SelectiveNackHeaderSize = 22;

		public const int SelectiveNackRangeSize = 8;

		public static int WriteSelectiveNack(Span<byte> destination, ulong streamId, ulong userOpcode, uint count, ReadOnlySpan<MissingRange> missingRangesSorted)
		{
