			}
			BinaryPrimitives.WriteUInt64BigEndian(destination.Slice(0, 8), streamId);
			BinaryPrimitives.WriteUInt64BigEndian(destination.Slice(8, 8), userOpcode);
			BinaryPrimitives.WriteUInt32BigEndian(destination.Slice(16, 4), count);
			BinaryPrimitives.WriteUInt16BigEndian(destination.Slice(20, 2), (ushort)missingRangesSorted.Length);
			int num2 = 22;
			ReadOnlySpan<MissingRange> readOnlySpan = missingRangesSorted;
			for (int i = 0; i < readOnlySpan.Length; i++)
			{
				MissingRange missingRange = readOnlySpan[i];
				BinaryPrimitives.WriteUInt32BigEndian(destination.Slice(num2, 4), missingRange.StartIndex);
				BinaryPrimitives.WriteUInt32BigEndian(destination.Slice(num2 + 4, 4), missingRange.Length);
				num2 += 8;
			}
			return num2;
		}

		public static void ReadSelectiveNack(ReadOnlySpan<byte> source, out ulong streamId, out ulong userOpcode, out uint count, out MissingRange[] missingRanges)
		{
