				uint length = BinaryPrimitives.ReadUInt32BigEndian(source.Slice(num2 + 4, 4));
				missingRanges[i] = new MissingRange(startIndex, length);
				num2 += 8;
			}
		}

		public static void WriteReassemblyDone(Span<byte> destination, ulong streamId)
		{
			if (destination.Length < 8)
			{
				throw new ArgumentException("Buffer too small", "destination");
			}
			BinaryPrimitives.WriteUInt64BigEndian(destination.Slice(0, 8), streamId);
		}

		public static void ReadReassemblyDone(ReadOnlySpan<byte> source, out ulong streamId)
		{
			if (source.Length < 8)
			{
				throw new ArgumentException("Buffer too small", "source");
			}
			streamId = BinaryPrimitives.ReadUInt64BigEndian(source);
		}
	}
	internal static class RitsuLibSidecarChunkGapScheduler
	{
		private sealed class Entry
		{
			public bool Aborted;

			public SceneTreeTimer? Timer;
		}

		private const float DebounceSeconds = 0.075f;

		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<(ulong Peer, ulong StreamId), Entry> Pending = new Dictionary<(ulong, ulong), Entry>();

		internal static void ScheduleGapReport(RitsuLibSidecarChunkReassembly reassembly, RunManager? rm, ulong chunkSourceNetId, ulong streamId, ulong userOpcode, uint partCount)
		{
			if (rm == null)
			{
				return;
			}
			MainLoop mainLoop = Engine.GetMainLoop();
			SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
			if (val == null)
			{
				return;
			}
			(ulong chunkSourceNetId, ulong streamId) key = (chunkSourceNetId: chunkSourceNetId, streamId: streamId);
			using (Gate.EnterScope())
			{
				if (!Pending.TryGetValue(key, out Entry value) || value.Timer == null)
				{
					Entry e = new Entry();
					Pending[key] = e;
					e.Timer = val.CreateTimer(0.07500000298023224, true, false, false);
					e.Timer.Timeout += delegate
					{
						Flush(reassembly, rm, key, e, userOpcode, partCount);
					};
				}
			}
		}

		internal static void Cancel(ulong chunkSourceNetId, ulong streamId)
		{
			(ulong, ulong) key = (chunkSourceNetId, streamId);
			using (Gate.EnterScope())
			{
				if (Pending.TryGetValue(key, out Entry value))
				{
					value.Aborted = true;
				}
				Pending.Remove(key);
			}
		}

		private static void Flush(RitsuLibSidecarChunkReassembly reassembly, RunManager? rm, (ulong Peer, ulong StreamId) key, Entry e, ulong userOpcode, uint partCount)
		{
			try
			{
				if (e.Aborted)
				{
					return;
				}
				RitsuLibSidecarProtocol.EnsureDefaultHandlers();
				var (num, streamId) = key;
				if (reassembly.TryListMissingIndices(num, streamId, out uint[] missing) && missing != null)
				{
					Array.Sort(missing);
					List<RitsuLibSidecarChunkGapBinary.MissingRange> list = BuildRanges(missing);
					int num2;
					for (int i = 0; i < list.Count; i += num2)
					{
						num2 = Math.Min(256, list.Count - i);
						RitsuLibSidecarChunkGapBinary.MissingRange[] array = list.GetRange(i, num2).ToArray();
						byte[] array2 = GC.AllocateUninitializedArray<byte>(22 + array.Length * 8);
						RitsuLibSidecarChunkGapBinary.WriteSelectiveNack(array2.AsSpan(), streamId, userOpcode, partCount, array);
						RitsuLibSidecarControlPeerSend.SendToNetPeer(rm, num, 19uL, array2);
					}
				}
			}
			finally
			{
				using (Gate.EnterScope())
				{
					if (Pending.TryGetValue(key, out Entry value) && value == e)
					{
						Pending.Remove(key);
					}
				}
			}
		}

		private static List<RitsuLibSidecarChunkGapBinary.MissingRange> BuildRanges(uint[] sorted)
		{
			List<RitsuLibSidecarChunkGapBinary.MissingRange> list = new List<RitsuLibSidecarChunkGapBinary.MissingRange>();
			if (sorted.Length == 0)
			{
				return list;
			}
			uint num = sorted[0];
			uint num2 = sorted[0];
			for (int i = 1; i < sorted.Length; i++)
			{
				uint num3 = sorted[i];
				if (num3 == num2 + 1)
				{
					num2 = num3;
					continue;
				}
				list.Add(new RitsuLibSidecarChunkGapBinary.MissingRange(num, num2 - num + 1));
				num = num3;
				num2 = num3;
			}
			list.Add(new RitsuLibSidecarChunkGapBinary.MissingRange(num, num2 - num + 1));
			return list;
		}
	}
	internal static class RitsuLibSidecarChunkOutboundRegistry
	{
		internal sealed class OutboundChunkStream
		{
			public required ulong StreamId { get; init; }

			public required ulong UserOpcode { get; init; }

			public required int Count { get; init; }

			public required byte[][] Frames { get; init; }

			public required RitsuLibSidecarChunkSendKind Kind { get; init; }

			public required RitsuLibSidecarDeliverySemantics Semantics { get; init; }

			public ulong? UnicastClientNetId { get; init; }
		}

		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<ulong, OutboundChunkStream> Active = new Dictionary<ulong, OutboundChunkStream>();

		private static readonly TimeSpan DefaultTtl = TimeSpan.FromMinutes(2L);

		internal static void Register(OutboundChunkStream state)
		{
			using (Gate.EnterScope())
			{
				Active[state.StreamId] = state;
			}
			ScheduleTtlDrop(state, DefaultTtl);
		}

		internal static void TryRemove(ulong streamId)
		{
			using (Gate.EnterScope())
			{
				Active.Remove(streamId);
			}
		}

		private static void ScheduleTtlDrop(OutboundChunkStream state, TimeSpan ttl)
		{
			MainLoop mainLoop = Engine.GetMainLoop();
			SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
			SceneTreeTimer t;
			if (val != null)
			{
				t = val.CreateTimer((double)(float)ttl.TotalSeconds, true, false, false);
				t.Timeout += OnTtl;
			}
			void OnTtl()
			{
				t.Timeout -= OnTtl;
				using (Gate.EnterScope())
				{
					if (Active.TryGetValue(state.StreamId, out OutboundChunkStream value) && value == state)
					{
						Active.Remove(state.StreamId);
					}
				}
			}
		}

		internal static void HandleSelectiveNack(RunManager? rm, ulong nackSenderNetId, ulong streamId, ulong userOpcode, uint count, RitsuLibSidecarChunkGapBinary.MissingRange[] missingRanges)
		{
			RitsuLibSidecarProtocol.EnsureDefaultHandlers();
			OutboundChunkStream value;
			using (Gate.EnterScope())
			{
				if (!Active.TryGetValue(streamId, out value))
				{
					return;
				}
			}
			if (value.UserOpcode != userOpcode || value.Count != (int)count)
			{
				return;
			}
			switch (value.Kind)
			{
			default:
				return;
			case RitsuLibSidecarChunkSendKind.Client:
			{
				INetGameService obj = ((rm != null) ? rm.NetService : null);
				NetClientGameService val = (NetClientGameService)(object)((obj is NetClientGameService) ? obj : null);
				if (val == null || nackSenderNetId != val.HostNetId)
				{
					return;
				}
				break;
			}
			case RitsuLibSidecarChunkSendKind.HostToPeer:
				if (!(((rm != null) ? rm.NetService : null) is NetHostGameService) || value.UnicastClientNetId != nackSenderNetId)
				{
					return;
				}
				break;
			case RitsuLibSidecarChunkSendKind.HostBroadcast:
				if (!(((rm != null) ? rm.NetService : null) is NetHostGameService))
				{
					return;
				}
				break;
			}
			for (int i = 0; i < missingRanges.Length; i++)
			{
				RitsuLibSidecarChunkGapBinary.MissingRange missingRange = missingRanges[i];
				if (missingRange.Length == 0 || missingRange.StartIndex >= count)
				{
					continue;
				}
				ulong num = Math.Min(count, (ulong)missingRange.StartIndex + (ulong)missingRange.Length);
				for (ulong num2 = missingRange.StartIndex; num2 < num; num2++)
				{
					byte[] array = value.Frames[(uint)num2];
					if (value.Kind == RitsuLibSidecarChunkSendKind.Client)
					{
						RitsuLibSidecarHighLevelSend.TrySendAsClient(rm, 18uL, array, value.Semantics);
					}
					else
					{
						RitsuLibSidecarHighLevelSend.TrySendAsHostToPeer(rm, nackSenderNetId, 18uL, array, value.Semantics);
					}
				}
			}
		}
	}
	internal sealed class RitsuLibSidecarChunkReassembly
	{
		private sealed class StreamState
		{
			public ulong UserOpcode { get; init; }

			public int ExpectedCount { get; init; }

			public int TotalLogicalSize { get; init; }

			public byte[][]? Parts { get; init; }

			public int ReceivedIndices { get; set; }

			public int AccumulatedLogicalBytes { get; set; }

			public DateTime CreatedUtc { get; init; }
		}

		internal static readonly TimeSpan IncompleteStreamRetentionDefault = TimeSpan.FromMinutes(2L);

		private readonly Lock _gate = new Lock();

		private readonly Dictionary<(ulong Sender, ulong StreamId), StreamState> _streams = new Dictionary<(ulong, ulong), StreamState>();

		internal TimeSpan IncompleteStreamRetention { get; set; } = IncompleteStreamRetentionDefault;

		internal bool TryIngest(ulong sender, ulong userOpcode, ulong streamId, uint index, uint count, uint totalPayloadSize, ReadOnlySpan<byte> segment, [NotNullWhen(true)] out byte[]? completed)
		{
			completed = null;
			(ulong, ulong) key = (sender, streamId);
			RitsuLibSidecarChunkReceiveProgress? ritsuLibSidecarChunkReceiveProgress = null;
			bool flag;
			using (_gate.EnterScope())
			{
