						return false;
					}
					value = new StreamState
					{
						UserOpcode = userOpcode,
						ExpectedCount = (int)count,
						TotalLogicalSize = (int)totalPayloadSize,
						Parts = new byte[count][],
						ReceivedIndices = 0,
						AccumulatedLogicalBytes = 0,
						CreatedUtc = DateTime.UtcNow
					};
