				}
				else if (value.UserOpcode != userOpcode || value.ExpectedCount != (int)count || value.TotalLogicalSize != (int)totalPayloadSize)
				{
					RitsuLibSidecarRepeatedWarningLog.Warn($"chunk-metadata-mismatch:sender={sender}:op={userOpcode}", "[Sidecar] Chunk metadata mismatch; dropping partial stream.");
					_streams.Remove(key);
					return false;
				}
				if (index >= (uint)value.Parts.Length)
				{
					RitsuLibSidecarRepeatedWarningLog.Warn($"chunk-index-overflow:sender={sender}:op={userOpcode}", "[Sidecar] Chunk index overflow; dropping stream.");
					_streams.Remove(key);
					return false;
