					flag = TryComplete_NoLock(value, key, ref completed);
					ritsuLibSidecarChunkReceiveProgress = new RitsuLibSidecarChunkReceiveProgress(sender, streamId, value.UserOpcode, value.ReceivedIndices, value.ExpectedCount, value.AccumulatedLogicalBytes, value.TotalLogicalSize, flag);
				}
			}
			if (ritsuLibSidecarChunkReceiveProgress.HasValue)
			{
