				{
					return false;
				}
				int num = value.Parts.Count((byte[] t) => t == null);
				if (num == 0)
				{
					return false;
				}
				uint[] array = new uint[num];
				int num2 = 0;
				int num3 = 0;
				for (; num2 < value.Parts.Length; num2++)
				{
					if (value.Parts[num2] == null)
					{
						array[num3++] = (uint)num2;
					}
				}
				missing = array;
				return true;
			}
