			{
				if (list == null)
				{
					list = new List<(ulong, ulong)>();
				}
				list.Add(item.Key);
			}
			if (list == null)
			{
				return;
			}
			foreach (var item2 in list)
			{
				_streams.Remove(item2);
				RitsuLibSidecarRepeatedWarningLog.Warn($"chunk-stale-evicted:sender={item2.Item1}", $"[Sidecar] Chunk stream stale evicted ({item2}).");
			}
		}

		private bool IsReceiveBudgetExceeded_NoLock(ulong sender, uint totalPayloadSize)
