			if (count >= RitsuLibSidecarResourcePolicy.MaxChunkReassemblyStreamsGlobal || num >= RitsuLibSidecarResourcePolicy.MaxChunkReassemblyStreamsPerSender)
			{
				return true;
			}
			long num2 = ((IEnumerable<StreamState>)_streams.Values).Sum((Func<StreamState, long>)((StreamState s) => s.TotalLogicalSize));
			long num3 = _streams.Where<KeyValuePair<(ulong, ulong), StreamState>>((KeyValuePair<(ulong Sender, ulong StreamId), StreamState> kv) => kv.Key.Sender == sender).Sum((Func<KeyValuePair<(ulong, ulong), StreamState>, long>)((KeyValuePair<(ulong Sender, ulong StreamId), StreamState> kv) => kv.Value.TotalLogicalSize));
			if (num2 + totalPayloadSize <= RitsuLibSidecarResourcePolicy.MaxChunkReassemblyLogicalBytesGlobal)
			{
				return num3 + totalPayloadSize > RitsuLibSidecarResourcePolicy.MaxChunkReassemblyLogicalBytesPerSender;
			}
			return true;
		}
	}
	internal enum RitsuLibSidecarChunkSendKind
	{
		Client,
		HostToPeer,
		HostBroadcast
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Splits large user payloads into CRC-protected chunk frames and retains them for selective retransmission.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将大型用户载荷拆分为带 CRC 校验的分块帧，并保留这些帧以供选择性重传。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         This compatibility API is obsolete. New file, image, and large-snapshot transfers must use
	///         <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEndpoints.RegisterBulk(STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEndpointDescriptor,STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBulkStreamOptions,System.Func{STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBulkStreamOffer,STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBulkReceiveTarget})" />, which adds negotiation, bounded streaming,
	///         backpressure, cancellation, end-to-end integrity, and lifecycle handling.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         此兼容接口已过时。新的文件、图片和大型快照传输必须使用
	///         <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEndpoints.RegisterBulk(STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEndpointDescriptor,STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBulkStreamOptions,System.Func{STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBulkStreamOffer,STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarBulkReceiveTarget})" />；新接口提供协商、有界流式处理、背压、取消、
	///         端到端完整性校验和生命周期处理。
	///     </para>
	///     <para xml:lang="en">
	///         Frames are fully constructed and registered for retransmission before the first transport attempt. If the
	///         first attempt fails, its outbound state is removed. A later failed attempt stops the remaining sends while
	///         retaining the state for frames that may already have reached the peer.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         会在首次传输尝试前完整构造帧并注册重传状态。首次尝试失败时会移除其出站状态；之后的尝试失败时，
	///         会停止发送剩余帧，但保留已可能到达对等方的帧的重传状态。
	///     </para>
	/// </remarks>
	[Obsolete("Use RitsuLibSidecarEndpoints.RegisterBulk for bounded streaming transfers. This compatibility API will be removed after the migration window.")]
	public static class RitsuLibSidecarChunkStream
	{
		private static long _streamIdMonotonic;

		/// <summary>
		///     <para xml:lang="en">
		///         Allocates a process-local, monotonically increasing stream ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         分配进程内单调递增的流 ID。
		///     </para>
		/// </summary>
		public static ulong AllocateStreamId()
		{
			return (ulong)Interlocked.Increment(ref _streamIdMonotonic);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to send <paramref name="full" /> to the host as a chunked stream.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试将 <paramref name="full" /> 作为分块流发送到主机。
		///     </para>
		/// </summary>
		public static void TrySendToHost(RunManager? runManager, ulong userOpcode, ReadOnlyMemory<byte> full, RitsuLibSidecarDeliverySemantics semantics = RitsuLibSidecarDeliverySemantics.StableSync, int maxSegment = 16384, IProgress<RitsuLibSidecarChunkStreamSendProgress>? progress = null)
		{
			SendImpl(runManager, RitsuLibSidecarChunkSendKind.Client, null, userOpcode, full, semantics, maxSegment, progress);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to send a chunked stream from the host to one peer.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试从主机向一个对等端发送分块流。
		///     </para>
		/// </summary>
		public static void TrySendToPeer(RunManager? runManager, ulong peerNetId, ulong userOpcode, ReadOnlyMemory<byte> full, RitsuLibSidecarDeliverySemantics semantics = RitsuLibSidecarDeliverySemantics.StableSync, int maxSegment = 16384, IProgress<RitsuLibSidecarChunkStreamSendProgress>? progress = null)
		{
			SendImpl(runManager, RitsuLibSidecarChunkSendKind.HostToPeer, peerNetId, userOpcode, full, semantics, maxSegment, progress);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to broadcast a chunked stream from the host to every eligible peer.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试从主机向所有符合条件的对等端广播分块流。
		///     </para>
		/// </summary>
		public static void TrySendBroadcast(RunManager? runManager, ulong userOpcode, ReadOnlyMemory<byte> full, RitsuLibSidecarDeliverySemantics semantics = RitsuLibSidecarDeliverySemantics.StableSync, int maxSegment = 16384, IProgress<RitsuLibSidecarChunkStreamSendProgress>? progress = null)
		{
			SendImpl(runManager, RitsuLibSidecarChunkSendKind.HostBroadcast, null, userOpcode, full, semantics, maxSegment, progress);
		}

		private static void SendImpl(RunManager? runManager, RitsuLibSidecarChunkSendKind kind, ulong? peerNetId, ulong userOpcode, ReadOnlyMemory<byte> full, RitsuLibSidecarDeliverySemantics semantics, int maxSegment, IProgress<RitsuLibSidecarChunkStreamSendProgress>? progress)
		{
			RitsuLibSidecarProtocol.EnsureDefaultHandlers();
			ArgumentOutOfRangeException.ThrowIfLessThan(maxSegment, 1, "maxSegment");
			ArgumentOutOfRangeException.ThrowIfGreaterThan(maxSegment, 65535, "maxSegment");
			uint length = (uint)full.Length;
			if (length == 0)
			{
				RitsuLibSidecarRepeatedWarningLog.Warn($"chunk-send-empty:peer={peerNetId?.ToString() ?? "broadcast"}:op={userOpcode}", "[Sidecar] Chunked send empty; ignored.");
				return;
			}
			ulong streamId = AllocateStreamId();
			ReadOnlySpan<byte> span = full.Span;
			int num = (int)((uint)((int)length + maxSegment - 1) / (uint)maxSegment);
			byte[][] array = new byte[num][];
			for (int i = 0; i < num; i++)
			{
				int num2 = i * maxSegment;
				int num3 = Math.Min(maxSegment, (int)length - num2);
				ReadOnlySpan<byte> segment = span.Slice(num2, num3);
				byte[] array2 = new byte[34 + num3];
				RitsuLibSidecarChunkBinary.WriteFrame(array2.AsSpan(), userOpcode, streamId, (uint)i, (uint)num, length, segment);
				array[i] = array2;
			}
			RitsuLibSidecarChunkOutboundRegistry.Register(new RitsuLibSidecarChunkOutboundRegistry.OutboundChunkStream
			{
				StreamId = streamId,
				UserOpcode = userOpcode,
				Count = num,
				Frames = array,
				Kind = kind,
				Semantics = semantics,
				UnicastClientNetId = ((kind == RitsuLibSidecarChunkSendKind.HostToPeer) ? peerNetId : ((ulong?)null))
			});
			long num4 = 0L;
			for (int j = 0; j < array.Length; j++)
			{
				byte[] array3 = array[j];
				if (kind switch
				{
					RitsuLibSidecarChunkSendKind.Client => RitsuLibSidecarHighLevelSend.TrySendAsClient(runManager, 18uL, array3, semantics) ? 1 : 0, 
					RitsuLibSidecarChunkSendKind.HostBroadcast => RitsuLibSidecarHighLevelSend.TrySendAsHostBroadcast(runManager, 18uL, array3, semantics) ? 1 : 0, 
					_ => RitsuLibSidecarHighLevelSend.TrySendAsHostToPeer(runManager, peerNetId.Value, 18uL, array3, semantics) ? 1 : 0, 
				} == 0)
				{
					if (j == 0)
					{
						RitsuLibSidecarChunkOutboundRegistry.TryRemove(streamId);
					}
					RitsuLibSidecarRepeatedWarningLog.Warn($"chunk-send-failed:peer={peerNetId?.ToString() ?? "broadcast"}:op={userOpcode}", "[Sidecar] Chunked send failed; remaining frames were not sent.");
					break;
				}
				num4 += array3.Length - 34;
				progress?.Report(new RitsuLibSidecarChunkStreamSendProgress(j + 1, num, num4, length));
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Describes progress after an attempted segment send in a chunked sidecar stream.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         描述 sidecar 分块流尝试发送一个分段后的进度。
	///     </para>
	/// </summary>
	public readonly record struct RitsuLibSidecarChunkStreamSendProgress(int SegmentIndexZeroBased, int TotalSegments, long BytesSentIncludingCurrentSegment, long TotalLogicalBytes);
	/// <summary>
	///     <para xml:lang="en">
	///         Describes the receive-side progress of a chunked stream being reassembled.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         描述接收端重组 sidecar 分块流的进度。
	///     </para>
	/// </summary>
	public readonly record struct RitsuLibSidecarChunkReceiveProgress(ulong SenderNetId, ulong StreamId, ulong UserOpcode, int ReceivedSegmentCount, int TotalSegments, int AccumulatedLogicalBytes, int TotalLogicalBytes, bool ReassemblyCompleted);
	/// <summary>
	///     <para xml:lang="en">
	///         Exposes optional receive-progress notifications for chunked Sidecar transfers.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         公开 Sidecar 分块传输的可选接收进度通知。
	///     </para>
	/// </summary>
	public static class RitsuLibSidecarChunkTransferNotifications
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Occurs synchronously after a segment is accepted or reassembly completes. Subscriber failures are
		///         logged and do not prevent later subscribers or the transfer completion path.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在接受分段或完成重组后同步发生。订阅者失败会被记录，且不会阻止后续订阅者或传输完成路径。
		///     </para>
		/// </summary>
		public static event Action<RitsuLibSidecarChunkReceiveProgress>? ReceiveProgress;

		internal static void RaiseReceive(in RitsuLibSidecarChunkReceiveProgress progress)
		{
			Action<RitsuLibSidecarChunkReceiveProgress> receiveProgress = ReceiveProgress;
			if (receiveProgress == null)
			{
				return;
			}
			Delegate[] invocationList = receiveProgress.GetInvocationList();
			for (int i = 0; i < invocationList.Length; i++)
			{
				Action<RitsuLibSidecarChunkReceiveProgress> action = (Action<RitsuLibSidecarChunkReceiveProgress>)invocationList[i];
				try
				{
					action(progress);
				}
				catch (Exception ex)
				{
					RitsuLibSidecarRepeatedWarningLog.Warn($"chunk-receive-progress-subscriber-exception:{action.Method.DeclaringType?.FullName}:{action.Method.Name}:{ex.GetType().FullName}", "[Sidecar] Chunk receive-progress subscriber failed: " + ex.Message);
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines the delivery tag at the start of an envelope header extension created by
	///         <see cref="T:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarHighLevelSend" /> or
	///         <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecar.CreateEnvelopeWithDelivery(System.UInt64,System.ReadOnlySpan{System.Byte},STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDeliverySemantics,STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarWireFlags,System.Boolean,System.ReadOnlySpan{System.Byte})" />. Additional extension bytes follow the tag.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义由 <see cref="T:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarHighLevelSend" /> 或
	///         <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecar.CreateEnvelopeWithDelivery(System.UInt64,System.ReadOnlySpan{System.Byte},STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDeliverySemantics,STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarWireFlags,System.Boolean,System.ReadOnlySpan{System.Byte})" /> 创建的信封标头扩展起始处的投递标签。
	///         其他扩展字节位于该标签之后。
	///     </para>
	/// </summary>
	public static class RitsuLibSidecarHeaderExtension
	{
		/// <summary>
		///     <para xml:lang="en">
		///         The minimum header-extension length when explicit delivery semantics are present.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         包含显式投递语义时标头扩展的最小长度。
		///     </para>
		/// </summary>
		public const int MinBytesWithDelivery = 1;

		/// <summary>
		///     <para xml:lang="en">
		///         Reads the delivery tag, or returns <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDeliverySemantics.Unspecified" /> when
		///         the extension is empty.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         读取投递标签；扩展为空时返回
		///         <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDeliverySemantics.Unspecified" />。
		///     </para>
		/// </summary>
		public static RitsuLibSidecarDeliverySemantics GetDeliveryOrUnspecified(ReadOnlyMemory<byte> extension)
		{
			if (extension.Length != 0)
			{
				return (RitsuLibSidecarDeliverySemantics)extension.Span[0];
			}
			return RitsuLibSidecarDeliverySemantics.Unspecified;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Encodes an optional 8-byte big-endian correlation ID immediately after the delivery tag in a header
	///         extension. Optional trailing bytes follow the correlation ID.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在标头扩展的投递标签之后编解码可选的 8 字节大端序关联 ID；其他可选字节位于关联 ID 之后。
	///     </para>
	/// </summary>
	public static class RitsuLibSidecarRequestCorrelation
	{
		/// <summary>
		///     <para xml:lang="en">
		///         The size of the correlation ID in the extension.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         扩展中关联 ID 的大小。
		///     </para>
		/// </summary>
		public const int BigEndianU64Bytes = 8;

		/// <summary>
		///     <para xml:lang="en">
		///         The minimum complete header-extension length required to read a correlation ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         读取关联 ID 所需的完整标头扩展最小长度。
		///     </para>
		/// </summary>
		public const int MinHeaderExtensionBytesWithCorrelation = 9;

		private static long _nextCorrelation;

		/// <summary>
		///     <para xml:lang="en">
		///         Allocates a process-local, monotonically increasing correlation ID for request/reply matching.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为请求与回复的匹配分配一个进程内单调递增的关联 ID。
		///     </para>
		/// </summary>
		public static ulong AllocateCorrelationId()
		{
			return (ulong)Interlocked.Increment(ref _nextCorrelation);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Writes <paramref name="correlationId" /> in big-endian order to the first 8 bytes of
		///         <paramref name="destination" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将 <paramref name="correlationId" /> 以大端序写入 <paramref name="destination" /> 的前 8 字节。
		///     </para>
		/// </summary>
		public static void WriteCorrelationBigEndian(Span<byte> destination, ulong correlationId)
		{
			BinaryPrimitives.WriteUInt64BigEndian(destination, correlationId);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds additional header-extension bytes for <see cref="T:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarHighLevelSend" />: an
		///         8-byte big-endian correlation ID followed by <paramref name="tailAfterCorrelation" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <see cref="T:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarHighLevelSend" /> 构建附加标头扩展：先写入 8 字节大端序关联 ID，
		///         再写入 <paramref name="tailAfterCorrelation" />。
		///     </para>
		/// </summary>
		public static byte[] PackAdditional(ulong correlationId, ReadOnlySpan<byte> tailAfterCorrelation = default(ReadOnlySpan<byte>))
		{
			byte[] array = new byte[8 + tailAfterCorrelation.Length];
			WriteCorrelationBigEndian(array.AsSpan(0, 8), correlationId);
			tailAfterCorrelation.CopyTo(array.AsSpan(8));
			return array;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends a big-endian correlation ID and trailing bytes to <paramref name="writer" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         向 <paramref name="writer" /> 追加大端序关联 ID 和尾随字节。
		///     </para>
		/// </summary>
		public static void PackAdditionalTo(ulong correlationId, ReadOnlySpan<byte> tailAfterCorrelation, IBufferWriter<byte> writer)
		{
			Span<byte> span = writer.GetSpan(8 + tailAfterCorrelation.Length);
			WriteCorrelationBigEndian(span, correlationId);
			tailAfterCorrelation.CopyTo(span.Slice(8));
			writer.Advance(8 + tailAfterCorrelation.Length);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Reads the correlation ID from a complete header extension whose first byte is the delivery tag.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从以投递标签为首字节的完整标头扩展中读取关联 ID。
		///     </para>
		/// </summary>
		public static bool TryReadCorrelation(ReadOnlyMemory<byte> fullHeaderExtension, out ulong correlationId)
		{
			correlationId = 0uL;
			if (fullHeaderExtension.Length < 9)
			{
				return false;
			}
			correlationId = BinaryPrimitives.ReadUInt64BigEndian(fullHeaderExtension.Span.Slice(1, 8));
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns <see langword="true" /> when the header extension contains
		///         <paramref name="expected" /> as its correlation ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当标头扩展包含关联 ID <paramref name="expected" /> 时返回 <see langword="true" />。
		///     </para>
		/// </summary>
		public static bool HeaderExtensionCorrelationEquals(ReadOnlyMemory<byte> fullHeaderExtension, ulong expected)
		{
			if (TryReadCorrelation(fullHeaderExtension, out var correlationId))
			{
				return correlationId == expected;
			}
			return false;
		}
	}
