	public static class RitsuLibSidecarHandshakeBinary
	{
		/// <summary>
		///     <para xml:lang="en">
		///         The handshake payload length, including the requested version, maximum supported version, and
		///         feature flags. Multibyte values use big-endian order.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         握手载荷的长度，其中包含请求版本、支持的最高版本和功能标志；多字节值采用大端序。
		///     </para>
		/// </summary>
		public const int HandshakePayloadSize = 8;

		/// <summary>
		///     <para xml:lang="en">
		///         The acknowledgement payload length, including the selected version, acceptance byte, and sender
		///         feature flags.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         握手确认载荷的长度，其中包含选定版本、接受状态字节和发送方功能标志。
		///     </para>
		/// </summary>
		public const int AckPayloadSize = 7;

		/// <summary>
		///     <para xml:lang="en">
		///         Writes a handshake payload to <paramref name="d" />, which must be at least
		///         <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarHandshakeBinary.HandshakePayloadSize" /> bytes long.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将握手载荷写入 <paramref name="d" />；其长度不得小于 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarHandshakeBinary.HandshakePayloadSize" /> 字节。
		///     </para>
		/// </summary>
		public static void WriteHandshake(Span<byte> d, ushort wireFormatVersion, ushort supportedWireFormatVersionMax, RitsuLibSidecarPeerFeatures features)
		{
			if (d.Length < 8)
			{
				throw new ArgumentException("Buffer too small", "d");
			}
			BinaryPrimitives.WriteUInt16BigEndian(d.Slice(0, 2), wireFormatVersion);
			BinaryPrimitives.WriteUInt16BigEndian(d.Slice(2, 2), supportedWireFormatVersionMax);
			BinaryPrimitives.WriteUInt32BigEndian(d.Slice(4, 4), (uint)features);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Reads a handshake from a complete <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarControlOpcodes.Handshake" /> payload.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从完整的 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarControlOpcodes.Handshake" /> 载荷中读取握手信息。
		///     </para>
		/// </summary>
		public static void ReadHandshake(ReadOnlySpan<byte> d, out ushort wireFormatVersion, out ushort supportedWireFormatVersionMax, out RitsuLibSidecarPeerFeatures features)
		{
			if (d.Length < 8)
			{
				throw new ArgumentException("Buffer too small", "d");
			}
			wireFormatVersion = BinaryPrimitives.ReadUInt16BigEndian(d.Slice(0, 2));
			supportedWireFormatVersionMax = BinaryPrimitives.ReadUInt16BigEndian(d.Slice(2, 2));
			features = (RitsuLibSidecarPeerFeatures)BinaryPrimitives.ReadUInt32BigEndian(d.Slice(4, 4));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Writes a handshake acknowledgement to <paramref name="d" />, which must be at least
		///         <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarHandshakeBinary.AckPayloadSize" /> bytes long.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将握手确认写入 <paramref name="d" />；其长度不得小于 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarHandshakeBinary.AckPayloadSize" /> 字节。
		///     </para>
		/// </summary>
		public static void WriteAck(Span<byte> d, ushort selectedWireFormatVersion, bool ok, RitsuLibSidecarPeerFeatures ackSenderFeatures)
		{
			if (d.Length < 7)
			{
				throw new ArgumentException("Buffer too small", "d");
			}
			BinaryPrimitives.WriteUInt16BigEndian(d.Slice(0, 2), selectedWireFormatVersion);
			d[2] = (ok ? ((byte)1) : ((byte)0));
			BinaryPrimitives.WriteUInt32BigEndian(d.Slice(3, 4), (uint)ackSenderFeatures);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Reads an acknowledgement from a complete
		///         <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarControlOpcodes.HandshakeAck" /> payload.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从完整的 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarControlOpcodes.HandshakeAck" /> 载荷中读取握手确认。
		///     </para>
		/// </summary>
		public static void ReadAck(ReadOnlySpan<byte> d, out ushort selectedWireFormatVersion, out bool ok, out RitsuLibSidecarPeerFeatures ackSenderFeatures)
		{
			if (d.Length < 7)
			{
				throw new ArgumentException("Buffer too small", "d");
			}
			selectedWireFormatVersion = BinaryPrimitives.ReadUInt16BigEndian(d.Slice(0, 2));
			ok = d[2] != 0;
			ackSenderFeatures = (RitsuLibSidecarPeerFeatures)BinaryPrimitives.ReadUInt32BigEndian(d.Slice(3, 4));
		}
	}
