		public static long MaxBufferedSyncBytes => 8388608L;

		/// <summary>
		///     <para xml:lang="en">
		///         The maximum number of incomplete chunk streams retained across all senders.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         所有发送方合计最多保留的未完成分块流数。
		///     </para>
		/// </summary>
		public static int MaxChunkReassemblyStreamsGlobal => 64;

		/// <summary>
		///     <para xml:lang="en">
		///         The maximum number of incomplete chunk streams retained for one sender.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         单个发送方最多保留的未完成分块流数。
		///     </para>
		/// </summary>
		public static int MaxChunkReassemblyStreamsPerSender => 16;

		/// <summary>
		///     <para xml:lang="en">
		///         The maximum number of segments accepted for one chunk stream.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         单个分块流最多接受的分段数。
		///     </para>
		/// </summary>
		public static int MaxChunkReassemblyPartCount => 1024;

		/// <summary>
		///     <para xml:lang="en">
		///         The maximum total logical payload size reserved by incomplete chunk streams across all senders.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         所有发送方的未完成分块流最多预留的逻辑载荷总字节数。
		///     </para>
		/// </summary>
		public static long MaxChunkReassemblyLogicalBytesGlobal => 16777216L;

		/// <summary>
		///     <para xml:lang="en">
		///         The maximum total logical payload size reserved by incomplete chunk streams for one sender.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         单个发送方的未完成分块流最多预留的逻辑载荷总字节数。
		///     </para>
		/// </summary>
		public static long MaxChunkReassemblyLogicalBytesPerSender => 8388608L;
	}
	internal static class RitsuLibSidecarCompression
	{
		internal const int AutoCompressionMinPayloadBytes = 1024;

		private const int MinAutoCompressionSavingsBytes = 32;

		internal static byte[] GzipCompress(ReadOnlySpan<byte> data)
		{
			using MemoryStream memoryStream = new MemoryStream();
			using (GZipStream gZipStream = new GZipStream(memoryStream, CompressionLevel.SmallestSize, leaveOpen: true))
			{
				gZipStream.Write(data);
			}
			return memoryStream.ToArray();
		}

		internal static byte[] BrotliCompress(ReadOnlySpan<byte> data)
		{
			using MemoryStream memoryStream = new MemoryStream();
			using (BrotliStream brotliStream = new BrotliStream(memoryStream, CompressionLevel.SmallestSize, leaveOpen: true))
			{
				brotliStream.Write(data);
			}
			return memoryStream.ToArray();
		}

		internal static bool TryBrotliAutoCompress(ReadOnlySpan<byte> data, [NotNullWhen(true)] out byte[]? compressed)
		{
			compressed = null;
			if (data.Length < 1024)
			{
				return false;
			}
			byte[] array = BrotliCompress(data);
			if (array.Length + 32 >= data.Length)
			{
				return false;
			}
			compressed = array;
			return true;
		}

		internal static bool TryGunzip(ReadOnlySpan<byte> compressed, [NotNullWhen(true)] out byte[]? decompressed)
		{
			decompressed = null;
			try
			{
				using MemoryStream stream = new MemoryStream(compressed.ToArray(), writable: false);
				using GZipStream gZipStream = new GZipStream(stream, CompressionMode.Decompress);
				using MemoryStream memoryStream = new MemoryStream();
				byte[] array = new byte[8192];
				while (true)
				{
					int num = gZipStream.Read(array);
					if (num <= 0)
					{
						break;
					}
					memoryStream.Write(array, 0, num);
					if (memoryStream.Length > 4194304)
					{
						return false;
					}
				}
				decompressed = memoryStream.ToArray();
				return true;
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				return false;
			}
		}

		internal static bool TryBrotliDecompress(ReadOnlySpan<byte> compressed, [NotNullWhen(true)] out byte[]? decompressed)
		{
			decompressed = null;
			try
			{
				using MemoryStream stream = new MemoryStream(compressed.ToArray(), writable: false);
				using BrotliStream brotliStream = new BrotliStream(stream, CompressionMode.Decompress);
				using MemoryStream memoryStream = new MemoryStream();
				byte[] array = new byte[8192];
				while (true)
				{
					int num = brotliStream.Read(array);
					if (num <= 0)
					{
						break;
					}
					memoryStream.Write(array, 0, num);
					if (memoryStream.Length > 4194304)
					{
						return false;
					}
				}
				decompressed = memoryStream.ToArray();
				return true;
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				return false;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines fixed opcodes reserved for framework control messages. Opcodes returned by
	///         <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarOpcodes.For(System.String,System.String)" /> are always outside the reserved range.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义为框架控制消息保留的固定操作码。<see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarOpcodes.For(System.String,System.String)" /> 返回的操作码始终位于
	///         保留范围之外。
	///     </para>
	/// </summary>
	public static class RitsuLibSidecarControlOpcodes
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Reserved for an optional framework keepalive or latency probe.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         保留用于可选的框架保活或延迟探测。
		///     </para>
		/// </summary>
		public const ulong FrameworkPing = 1uL;

		/// <summary>
		///     <para xml:lang="en">
		///         Advertises capabilities and initiates wire-version negotiation.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         声明功能并发起线路格式版本协商。
		///     </para>
		/// </summary>
		public const ulong Handshake = 16uL;

		/// <summary>
		///     <para xml:lang="en">
		///         Acknowledges <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarControlOpcodes.Handshake" /> and reports the negotiated version and responder features.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         确认 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarControlOpcodes.Handshake" />，并报告协商后的版本和响应方功能。
		///     </para>
		/// </summary>
		public const ulong HandshakeAck = 17uL;

		/// <summary>
		///     <para xml:lang="en">
		///         Carries one segment of a chunked logical payload.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         承载分块逻辑载荷中的一个分段。
		///     </para>
		/// </summary>
		public const ulong ChunkedFrame = 18uL;

		/// <summary>
		///     <para xml:lang="en">
		///         Reports variable-length ranges of missing segments to the original chunk-stream sender.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         向原分块流发送方报告缺失分段的变长范围列表。
		///     </para>
		/// </summary>
		public const ulong ChunkStreamSelectiveNack = 19uL;

		/// <summary>
		///     <para xml:lang="en">
		///         Confirms reassembly to the original chunk-stream sender so it can discard the retained outbound
		///         frames.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         向原分块流发送方确认重组完成，使其可以丢弃保留的待发送帧。
		///     </para>
		/// </summary>
		public const ulong ChunkStreamReassemblyDone = 20uL;

		/// <summary>
		///     <para xml:lang="en">
		///         Requests that the host coordinate a combat-state diagnostic dump across all peers.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         请求主机协调所有对等端生成战斗状态诊断转储。
		///     </para>
		/// </summary>
		public const ulong DiagnosticRelayDumpRequest = 21uL;

		/// <summary>
		///     <para xml:lang="en">
		///         Carries <see cref="T:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDiagnosticPayload" /> from the host so each peer records its local
		///         state.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         由主机发送 <see cref="T:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDiagnosticPayload" />，使每个对等端记录本地状态。
		///     </para>
		/// </summary>
		public const ulong DiagnosticRelayDumpFanout = 22uL;

		/// <summary>
		///     <para xml:lang="en">Carries a peer's complete routed-endpoint capability catalog to the host.</para>
		///     <para xml:lang="zh-CN">向主机承载对等方完整的路由端点能力目录。</para>
		/// </summary>
		public const ulong EndpointCatalog = 23uL;

		/// <summary>
		///     <para xml:lang="en">Carries the host-authoritative routed-endpoint snapshot to one client.</para>
		///     <para xml:lang="zh-CN">向一个客户端承载由主机确定的路由端点快照。</para>
		/// </summary>
		public const ulong EndpointRouteSnapshot = 24uL;

		/// <summary>
		///     <para xml:lang="en">Acknowledges an atomically applied routed-endpoint snapshot.</para>
		///     <para xml:lang="zh-CN">确认已原子应用一份路由端点快照。</para>
		/// </summary>
		public const ulong EndpointRouteSnapshotAck = 25uL;

		/// <summary>
		///     <para xml:lang="en">Carries client endpoint data to the host for validation and optional relay.</para>
		///     <para xml:lang="zh-CN">将客户端端点数据送往主机，以便验证并按需中继。</para>
		/// </summary>
		public const ulong EndpointIngress = 26uL;

		/// <summary>
		///     <para xml:lang="en">
		///         Carries host-originated or host-relayed endpoint data with a host-assigned canonical sender identity.
		///     </para>
		///     <para xml:lang="zh-CN">承载主机发起或主机中继的端点数据，并包含由主机确定的规范发送方身份。</para>
		/// </summary>
		public const ulong EndpointDelivery = 27uL;
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Specifies how a sidecar payload is transported and, by convention, interpreted. When present, the
	///         first byte of the envelope header extension stores this value.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         指定 sidecar 载荷的传输方式及其约定语义。信封标头扩展存在投递标签时，其首字节存储此值。
	///     </para>
	/// </summary>
	public enum RitsuLibSidecarDeliverySemantics : byte
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Uses unreliable transport on the best-effort channel. Frames may be lost or reordered, and handlers
		///         may run as soon as a frame arrives.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用尽力而为通道上的不可靠传输。帧可能丢失或乱序，且处理器可以在帧到达后立即运行。
		///     </para>
		/// </summary>
		BestEffort = 0,
		/// <summary>
		///     <para xml:lang="en">
		///         Uses reliable transport on the sidecar synchronization channel. This does not marshal handlers to
		///         the Godot main thread or merge them into vanilla game-action serialization.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用 sidecar 同步通道上的可靠传输。这不会将处理器调度到 Godot 主线程，也不会将其并入原版游戏
		///         动作的序列化流程。
		///     </para>
		/// </summary>
		StableSync = 1,
		/// <summary>
		///     <para xml:lang="en">
		///         Omits the delivery tag when an envelope is built directly. High-level send methods treat this value
		///         as <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDeliverySemantics.StableSync" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         直接构建信封时省略投递标签；高层发送方法会将此值按 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDeliverySemantics.StableSync" /> 处理。
		///     </para>
		/// </summary>
		Unspecified = byte.MaxValue
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Parses and builds Sidecar envelopes containing magic, wire version, flags, opcode, an optional
	///         header extension, and payload.
	///     </para>
	///     <para xml:lang="zh-CN">解析和构建包含魔数、线格式版本、标志、操作码、可选头扩展和载荷的 Sidecar 信封。</para>
	/// </summary>
	public static class RitsuLibSidecarEnvelope
	{
		/// <summary>
		///     <para xml:lang="en">Specifies the outcome of parsing an on-wire envelope.</para>
		///     <para xml:lang="zh-CN">指定解析线上信封的结果。</para>
		/// </summary>
		public enum ParseOutcome
		{
			/// <summary>
			///     <para xml:lang="en">Parsing succeeded.</para>
			///     <para xml:lang="zh-CN">解析成功。</para>
			/// </summary>
			Ok,
			/// <summary>
			///     <para xml:lang="en">The packet is shorter than the minimum header.</para>
			///     <para xml:lang="zh-CN">数据包短于最小头部。</para>
			/// </summary>
			TooSmall,
			/// <summary>
			///     <para xml:lang="en">The magic value does not match.</para>
			///     <para xml:lang="zh-CN">魔数不匹配。</para>
			/// </summary>
			BadMagic,
			/// <summary>
			///     <para xml:lang="en">
			///         The wire format version is zero or exceeds
			///         <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarWire.SupportedWireFormatVersionMax" />.
			///     </para>
			///     <para xml:lang="zh-CN">线格式版本为零或超过 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarWire.SupportedWireFormatVersionMax" />。</para>
			/// </summary>
			WireVersionUnsupported,
			/// <summary>
			///     <para xml:lang="en">
			///         The declared payload length is invalid, decompression fails, or decompressed data exceeds the
			///         cap.
			///     </para>
			///     <para xml:lang="zh-CN">声明的载荷长度无效、解压失败，或解压数据超过上限。</para>
			/// </summary>
			PayloadLengthInvalid,
			/// <summary>
			///     <para xml:lang="en">The header-extension length exceeds the cap.</para>
			///     <para xml:lang="zh-CN">头扩展长度超过上限。</para>
			/// </summary>
			ExtensionLengthInvalid,
			/// <summary>
			///     <para xml:lang="en">The total packet length does not match the header fields.</para>
			///     <para xml:lang="zh-CN">数据包总长度与头部字段不匹配。</para>
			/// </summary>
			TotalLengthMismatch,
			/// <summary>
			///     <para xml:lang="en">
			///         The supplied span does not contain exactly the bytes in the array used for returned memory views.
			///     </para>
			///     <para xml:lang="zh-CN">提供的跨度与用于返回内存视图的数组内容不完全一致。</para>
			/// </summary>
			BackingMismatch
		}

		/// <summary>
		///     <para xml:lang="en">Contains decoded header fields and the logical payload.</para>
		///     <para xml:lang="zh-CN">包含已解码的头部字段和逻辑载荷。</para>
		/// </summary>
		public readonly struct ParsedEnvelope
		{
			/// <summary>
			///     <para xml:lang="en">Wire format version from the packet.</para>
			///     <para xml:lang="zh-CN">数据包中的线格式版本。</para>
			/// </summary>
			public ushort WireFormatVersion { get; }

			/// <summary>
			///     <para xml:lang="en">Decoded flags with unknown bits cleared.</para>
			///     <para xml:lang="zh-CN">未知位已清除的已解码标志。</para>
			/// </summary>
			public RitsuLibSidecarWireFlags Flags { get; }

			/// <summary>
			///     <para xml:lang="en">64-bit opcode from <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarOpcodes.For(System.String,System.String)" /> or a framework constant.</para>
			///     <para xml:lang="zh-CN">来自 <see cref="M:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarOpcodes.For(System.String,System.String)" /> 或框架常量的 64 位操作码。</para>
			/// </summary>
			public ulong Opcode { get; }

			/// <summary>
			///     <para xml:lang="en">Opaque header extension; version-1 senders typically use an empty extension.</para>
			///     <para xml:lang="zh-CN">不透明头扩展；版本 1 发送方通常使用空扩展。</para>
			/// </summary>
			public ReadOnlyMemory<byte> HeaderExtension { get; }

			/// <summary>
			///     <para xml:lang="en">Logical payload after any compression indicated by the flags is removed.</para>
			///     <para xml:lang="zh-CN">移除标志指示的任何压缩后的逻辑载荷。</para>
			/// </summary>
			public ReadOnlyMemory<byte> Payload { get; }

			/// <summary>
			///     <para xml:lang="en">Creates a parsed-envelope value.</para>
			///     <para xml:lang="zh-CN">创建已解析的信封值。</para>
			/// </summary>
			/// <param name="wireFormatVersion">
			///     <para xml:lang="en">Wire format version from the packet.</para>
			///     <para xml:lang="zh-CN">数据包中的线格式版本。</para>
			/// </param>
			/// <param name="flags">
			///     <para xml:lang="en">Decoded wire flags.</para>
			///     <para xml:lang="zh-CN">已解码的线格式标志。</para>
			/// </param>
			/// <param name="opcode">
			///     <para xml:lang="en">64-bit opcode from the packet.</para>
			///     <para xml:lang="zh-CN">数据包中的 64 位操作码。</para>
			/// </param>
			/// <param name="headerExtension">
			///     <para xml:lang="en">Optional header-extension segment.</para>
			///     <para xml:lang="zh-CN">可选头扩展段。</para>
			/// </param>
			/// <param name="payload">
			///     <para xml:lang="en">Logical payload, decompressed when required by the flags.</para>
			///     <para xml:lang="zh-CN">逻辑载荷；必要时会按标志解压。</para>
			/// </param>
			public ParsedEnvelope(ushort wireFormatVersion, RitsuLibSidecarWireFlags flags, ulong opcode, ReadOnlyMemory<byte> headerExtension, ReadOnlyMemory<byte> payload)
			{
				WireFormatVersion = wireFormatVersion;
				Flags = flags;
				Opcode = opcode;
				HeaderExtension = headerExtension;
				Payload = payload;
			}
		}

		private const RitsuLibSidecarWireFlags PayloadCompressionFlags = RitsuLibSidecarWireFlags.PayloadGzip | RitsuLibSidecarWireFlags.PayloadBrotli;

		private const uint KnownWireFlagsMask = 3u;

		/// <summary>
		///     <para xml:lang="en">Parses an envelope from the byte array that backs the returned memory views.</para>
		///     <para xml:lang="zh-CN">从返回内存视图所引用的底层字节数组解析信封。</para>
		/// </summary>
		/// <param name="packet">
		///     <para xml:lang="en">Full on-wire bytes; returned memory views reference this array.</para>
		///     <para xml:lang="zh-CN">完整线上字节；返回的内存视图引用此数组。</para>
		/// </param>
		/// <param name="parsed">
		///     <para xml:lang="en">Populated when the return value is <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEnvelope.ParseOutcome.Ok" />.</para>
		///     <para xml:lang="zh-CN">返回值为 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEnvelope.ParseOutcome.Ok" /> 时填充。</para>
		/// </param>
		public static ParseOutcome TryParse(byte[] packet, out ParsedEnvelope parsed)
		{
			return TryParse(packet.AsSpan(), packet, out parsed);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Parses an envelope only when <paramref name="packet" /> exactly contains the bytes in
		///         <paramref name="backing" />.
		///     </para>
		///     <para xml:lang="zh-CN">仅当 <paramref name="packet" /> 精确包含 <paramref name="backing" /> 中的字节时解析信封。</para>
		/// </summary>
		/// <param name="packet">
		///     <para xml:lang="en">Full on-wire bytes equal to the contents of <paramref name="backing" />.</para>
		///     <para xml:lang="zh-CN">与 <paramref name="backing" /> 内容相等的完整线上字节。</para>
		/// </param>
		/// <param name="backing">
		///     <para xml:lang="en">Array used to construct <see cref="T:System.ReadOnlyMemory`1" /> views for the extension and payload.</para>
		///     <para xml:lang="zh-CN">用于构造扩展和载荷 <see cref="T:System.ReadOnlyMemory`1" /> 视图的数组。</para>
		/// </param>
		/// <param name="parsed">
		///     <para xml:lang="en">Populated when the return value is <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEnvelope.ParseOutcome.Ok" />.</para>
		///     <para xml:lang="zh-CN">返回值为 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarEnvelope.ParseOutcome.Ok" /> 时填充。</para>
		/// </param>
		public static ParseOutcome TryParse(ReadOnlySpan<byte> packet, byte[] backing, out ParsedEnvelope parsed)
		{
			parsed = default(ParsedEnvelope);
			if (backing == null || packet.Length != backing.Length || !packet.SequenceEqual(backing))
			{
				return ParseOutcome.BackingMismatch;
			}
			if (packet.Length < RitsuLibSidecarWire.MinEnvelopeSize)
			{
				return ParseOutcome.TooSmall;
			}
			if (!RitsuLibSidecarWire.MatchesMagic(packet))
			{
				return ParseOutcome.BadMagic;
			}
			ushort num = BinaryPrimitives.ReadUInt16BigEndian(packet.Slice(RitsuLibSidecarEnvelopeLayout.WireVersionOffset, 2));
			uint num2 = BinaryPrimitives.ReadUInt32BigEndian(packet.Slice(RitsuLibSidecarEnvelopeLayout.FlagsOffset, 4));
			ulong opcode = BinaryPrimitives.ReadUInt64BigEndian(packet.Slice(RitsuLibSidecarEnvelopeLayout.OpcodeOffset, 8));
			uint num3 = BinaryPrimitives.ReadUInt32BigEndian(packet.Slice(RitsuLibSidecarEnvelopeLayout.PayloadLengthOffset, 4));
			uint num4 = BinaryPrimitives.ReadUInt32BigEndian(packet.Slice(RitsuLibSidecarEnvelopeLayout.ExtensionLengthOffset, 4));
			if ((num > 2 || num == 0) ? true : false)
			{
				return ParseOutcome.WireVersionUnsupported;
			}
			if (num3 > 4194304)
			{
				return ParseOutcome.PayloadLengthInvalid;
			}
			if (num4 > 65536)
			{
				return ParseOutcome.ExtensionLengthInvalid;
			}
			RitsuLibSidecarWireFlags ritsuLibSidecarWireFlags = (RitsuLibSidecarWireFlags)(num2 & 3);
			if (RitsuLibSidecarEnvelopeLayout.FixedHeaderSize + num4 + num3 != packet.Length)
			{
				return ParseOutcome.TotalLengthMismatch;
			}
			ReadOnlyMemory<byte> headerExtension = ((num4 == 0) ? ReadOnlyMemory<byte>.Empty : new ReadOnlyMemory<byte>(backing, RitsuLibSidecarEnvelopeLayout.FixedHeaderSize, (int)num4));
			int start = RitsuLibSidecarEnvelopeLayout.FixedHeaderSize + (int)num4;
			ReadOnlyMemory<byte> readOnlyMemory = new ReadOnlyMemory<byte>(backing, start, (int)num3);
			ReadOnlyMemory<byte> payload;
			switch (ritsuLibSidecarWireFlags & (RitsuLibSidecarWireFlags.PayloadGzip | RitsuLibSidecarWireFlags.PayloadBrotli))
			{
			case RitsuLibSidecarWireFlags.None:
				payload = readOnlyMemory;
				break;
			case RitsuLibSidecarWireFlags.PayloadGzip:
			{
				if (!RitsuLibSidecarCompression.TryGunzip(readOnlyMemory.Span, out byte[] decompressed2))
				{
					return ParseOutcome.PayloadLengthInvalid;
				}
				payload = decompressed2;
				break;
			}
			case RitsuLibSidecarWireFlags.PayloadBrotli:
			{
				if (!RitsuLibSidecarCompression.TryBrotliDecompress(readOnlyMemory.Span, out byte[] decompressed))
				{
					return ParseOutcome.PayloadLengthInvalid;
				}
				payload = decompressed;
				break;
			}
			default:
				return ParseOutcome.PayloadLengthInvalid;
			}
			parsed = new ParsedEnvelope(num, ritsuLibSidecarWireFlags, opcode, headerExtension, payload);
			return ParseOutcome.Ok;
		}

		/// <summary>
		///     <para xml:lang="en">Builds a complete on-wire envelope, optionally gzip-compressing the logical payload.</para>
		///     <para xml:lang="zh-CN">构建完整线上信封，并可选择 gzip 压缩逻辑载荷。</para>
		/// </summary>
		/// <param name="wireFormatVersion">
		///     <para xml:lang="en">Wire format version, which must be within the supported range.</para>
		///     <para xml:lang="zh-CN">必须位于支持范围内的线格式版本。</para>
		/// </param>
		/// <param name="flags">
		///     <para xml:lang="en">Wire flags; the gzip flag is controlled by <paramref name="gzipLogicalPayload" />.</para>
		///     <para xml:lang="zh-CN">线格式标志；gzip 标志由 <paramref name="gzipLogicalPayload" /> 控制。</para>
		/// </param>
		/// <param name="opcode">
		///     <para xml:lang="en">64-bit Sidecar opcode.</para>
		///     <para xml:lang="zh-CN">64 位 Sidecar 操作码。</para>
		/// </param>
		/// <param name="headerExtension">
		///     <para xml:lang="en">Optional bytes after the fixed header and before the payload.</para>
		///     <para xml:lang="zh-CN">固定头部之后、载荷之前的可选字节。</para>
		/// </param>
		/// <param name="payloadLogical">
		///     <para xml:lang="en">Uncompressed logical payload.</para>
		///     <para xml:lang="zh-CN">未压缩的逻辑载荷。</para>
		/// </param>
		/// <param name="gzipLogicalPayload">
		///     <para xml:lang="en">
		///         Whether to gzip-compress the payload and set
		///         <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarWireFlags.PayloadGzip" />.
		///     </para>
		///     <para xml:lang="zh-CN">是否 gzip 压缩载荷并设置 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarWireFlags.PayloadGzip" />。</para>
		/// </param>
		public static byte[] Build(ushort wireFormatVersion, RitsuLibSidecarWireFlags flags, ulong opcode, ReadOnlySpan<byte> headerExtension, ReadOnlySpan<byte> payloadLogical, bool gzipLogicalPayload)
		{
			return Build(wireFormatVersion, flags, opcode, headerExtension, payloadLogical, gzipLogicalPayload ? RitsuLibSidecarPayloadCompression.Gzip : RitsuLibSidecarPayloadCompression.None);
		}

		/// <summary>
		///     <para xml:lang="en">Builds a complete on-wire envelope using the requested payload compression mode.</para>
		///     <para xml:lang="zh-CN">使用请求的载荷压缩模式构建完整线上信封。</para>
		/// </summary>
		/// <param name="wireFormatVersion">
		///     <para xml:lang="en">Wire format version, which must be within the supported range.</para>
		///     <para xml:lang="zh-CN">必须位于支持范围内的线格式版本。</para>
		/// </param>
		/// <param name="flags">
		///     <para xml:lang="en">Wire flags with compression bits replaced by <paramref name="compression" />.</para>
		///     <para xml:lang="zh-CN">其压缩位会由 <paramref name="compression" /> 替换的线格式标志。</para>
		/// </param>
		/// <param name="opcode">
		///     <para xml:lang="en">64-bit Sidecar opcode.</para>
		///     <para xml:lang="zh-CN">64 位 Sidecar 操作码。</para>
		/// </param>
		/// <param name="headerExtension">
		///     <para xml:lang="en">Optional bytes after the fixed header and before the payload.</para>
		///     <para xml:lang="zh-CN">固定头部之后、载荷之前的可选字节。</para>
		/// </param>
		/// <param name="payloadLogical">
		///     <para xml:lang="en">Uncompressed logical payload.</para>
		///     <para xml:lang="zh-CN">未压缩的逻辑载荷。</para>
		/// </param>
		/// <param name="compression">
		///     <para xml:lang="en">Payload compression mode.</para>
		///     <para xml:lang="zh-CN">载荷压缩模式。</para>
		/// </param>
		public static byte[] Build(ushort wireFormatVersion, RitsuLibSidecarWireFlags flags, ulong opcode, ReadOnlySpan<byte> headerExtension, ReadOnlySpan<byte> payloadLogical, RitsuLibSidecarPayloadCompression compression)
		{
			if ((wireFormatVersion > 2 || wireFormatVersion == 0) ? true : false)
			{
				throw new ArgumentOutOfRangeException("wireFormatVersion");
			}
			if ((long)headerExtension.Length > 65536L)
			{
				throw new ArgumentOutOfRangeException("headerExtension");
			}
			if ((long)payloadLogical.Length > 4194304L)
			{
				throw new ArgumentOutOfRangeException("payloadLogical");
			}
			ReadOnlySpan<byte> readOnlySpan = payloadLogical;
			flags = (RitsuLibSidecarWireFlags)((uint)flags & 0xFFFFFFFCu);
			switch (compression)
			{
			case RitsuLibSidecarPayloadCompression.Gzip:
				readOnlySpan = RitsuLibSidecarCompression.GzipCompress(payloadLogical);
				flags |= RitsuLibSidecarWireFlags.PayloadGzip;
				break;
			case RitsuLibSidecarPayloadCompression.Brotli:
				readOnlySpan = RitsuLibSidecarCompression.BrotliCompress(payloadLogical);
				flags |= RitsuLibSidecarWireFlags.PayloadBrotli;
				break;
			case RitsuLibSidecarPayloadCompression.Auto:
			{
				if (RitsuLibSidecarCompression.TryBrotliAutoCompress(payloadLogical, out byte[] compressed))
				{
					readOnlySpan = compressed;
					flags |= RitsuLibSidecarWireFlags.PayloadBrotli;
				}
				break;
			}
			default:
				throw new ArgumentOutOfRangeException("compression");
			case RitsuLibSidecarPayloadCompression.None:
				break;
			}
			if ((long)readOnlySpan.Length > 4194304L)
			{
				throw new ArgumentOutOfRangeException("payloadLogical");
			}
			byte[] array = new byte[RitsuLibSidecarWire.MinEnvelopeSize + headerExtension.Length + readOnlySpan.Length];
			Span<byte> destination = array.AsSpan();
			RitsuLibSidecarWire.Magic.CopyTo(destination);
			BinaryPrimitives.WriteUInt16BigEndian(destination.Slice(RitsuLibSidecarEnvelopeLayout.WireVersionOffset, 2), wireFormatVersion);
			BinaryPrimitives.WriteUInt32BigEndian(destination.Slice(RitsuLibSidecarEnvelopeLayout.FlagsOffset, 4), (uint)flags);
			BinaryPrimitives.WriteUInt64BigEndian(destination.Slice(RitsuLibSidecarEnvelopeLayout.OpcodeOffset, 8), opcode);
			BinaryPrimitives.WriteUInt32BigEndian(destination.Slice(RitsuLibSidecarEnvelopeLayout.PayloadLengthOffset, 4), (uint)readOnlySpan.Length);
			BinaryPrimitives.WriteUInt32BigEndian(destination.Slice(RitsuLibSidecarEnvelopeLayout.ExtensionLengthOffset, 4), (uint)headerExtension.Length);
			int fixedHeaderSize = RitsuLibSidecarEnvelopeLayout.FixedHeaderSize;
			headerExtension.CopyTo(destination.Slice(fixedHeaderSize, headerExtension.Length));
			int start = fixedHeaderSize + headerExtension.Length;
			readOnlySpan.CopyTo(destination.Slice(start));
			return array;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Specifies the compression mode for a sidecar envelope payload.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         指定 sidecar 信封载荷的压缩模式。
	///     </para>
	/// </summary>
	public enum RitsuLibSidecarPayloadCompression
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Writes the payload without compression.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         不压缩载荷。
		///     </para>
		/// </summary>
		None,
		/// <summary>
		///     <para xml:lang="en">
		///         Compresses the payload with gzip.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用 gzip 压缩载荷。
		///     </para>
		/// </summary>
		Gzip,
		/// <summary>
		///     <para xml:lang="en">
		///         Compresses the payload with Brotli.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用 Brotli 压缩载荷。
		///     </para>
		/// </summary>
		Brotli,
		/// <summary>
		///     <para xml:lang="en">
		///         Uses Brotli only when the payload meets the size threshold and compression saves enough bytes.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         仅在载荷达到大小阈值且压缩可节省足够字节时使用 Brotli。
		///     </para>
		/// </summary>
		Auto
	}
	internal static class RitsuLibSidecarPayloadCompressionSelector
	{
		internal static RitsuLibSidecarPayloadCompression ForPeer(ulong opcode, ReadOnlySpan<byte> payload, ulong peerNetId)
		{
			if (!CanAutoCompress(opcode, payload))
			{
				return RitsuLibSidecarPayloadCompression.None;
			}
			if (!PeerSupportsBrotli(peerNetId))
			{
				return RitsuLibSidecarPayloadCompression.None;
			}
			return RitsuLibSidecarPayloadCompression.Auto;
		}

		internal static RitsuLibSidecarPayloadCompression ForPeers(ulong opcode, ReadOnlySpan<byte> payload, IEnumerable<ulong> peerNetIds)
		{
			if (!CanAutoCompress(opcode, payload))
			{
				return RitsuLibSidecarPayloadCompression.None;
			}
			bool flag = false;
			foreach (ulong peerNetId in peerNetIds)
			{
				if (RitsuLibSidecarSessionManager.CanSendToPeer(peerNetId))
				{
					flag = true;
					if (!PeerSupportsBrotli(peerNetId))
					{
						return RitsuLibSidecarPayloadCompression.None;
					}
				}
			}
			if (!flag)
			{
				return RitsuLibSidecarPayloadCompression.None;
			}
			return RitsuLibSidecarPayloadCompression.Auto;
		}

		internal static bool PeerSupportsBrotli(ulong peerNetId)
		{
			if (RitsuLibSidecarSessionManager.TryGetPeerFeatures(peerNetId, out var features))
			{
				return (features & RitsuLibSidecarPeerFeatures.BrotliPayloadCompression) != 0;
			}
			return false;
		}

		private static bool CanAutoCompress(ulong opcode, ReadOnlySpan<byte> payload)
		{
			if (payload.Length >= 1024)
			{
				return !IsControlOpcode(opcode);
			}
			return false;
		}

		private static bool IsControlOpcode(ulong opcode)
		{
			if (opcode - 16 <= 4)
			{
				return true;
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides the fixed wire-format constants for RitsuLib multiplayer sidecar envelopes.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供 RitsuLib 多人 sidecar 信封所使用的固定线路格式常量。
	///     </para>
	/// </summary>
	public static class RitsuLibSidecarWire
	{
		/// <summary>
		///     <para xml:lang="en">
		///         The recommended ENet or Steam channel for reliable sidecar traffic.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可靠 sidecar 流量使用的推荐 ENet 或 Steam 通道。
		///     </para>
		/// </summary>
		public const int RecommendedReliableChannel = 48;

		/// <summary>
		///     <para xml:lang="en">
		///         The recommended ENet or Steam channel for best-effort sidecar traffic.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尽力而为的 sidecar 流量使用的推荐 ENet 或 Steam 通道。
		///     </para>
		/// </summary>
		public const int RecommendedUnreliableChannel = 49;

		/// <summary>
		///     <para xml:lang="en">
		///         The recommended ENet channel for reliable bulk Sidecar streams. Backends without independent channels
		///         may map it to their reliable transport while retaining RitsuLib's bulk scheduling limits.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可靠 Sidecar 批量流使用的推荐 ENet 通道。不支持独立通道的后端可以映射到其可靠传输，同时保留
		///         RitsuLib 的批量调度限制。
		///     </para>
		/// </summary>
		public const int RecommendedBulkChannel = 50;

		/// <summary>
		///     <para xml:lang="en">
		///         The wire-format version written by the current library.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当前库写入的线路格式版本。
		///     </para>
		/// </summary>
		public const ushort CurrentWireFormatVersion = 2;

		/// <summary>
		///     <para xml:lang="en">
		///         The highest wire-format version accepted by this library.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当前库接受的最高线路格式版本。
		///     </para>
		/// </summary>
		public const ushort SupportedWireFormatVersionMax = 2;

		/// <summary>
		///     <para xml:lang="en">
		///         The maximum logical payload size after optional decompression.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选解压后的最大逻辑载荷大小。
		///     </para>
		/// </summary>
		public const uint MaxPayloadBytes = 4194304u;

		/// <summary>
		///     <para xml:lang="en">
		///         The maximum header-extension length.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         标头扩展的最大长度。
		///     </para>
		/// </summary>
		public const uint MaxHeaderExtensionBytes = 65536u;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the length of <see cref="P:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarWire.Magic" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 <see cref="P:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarWire.Magic" /> 的长度。
		///     </para>
		/// </summary>
		public static int MagicLength => Magic.Length;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the minimum encoded envelope size, excluding extension and payload bytes.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取不含扩展和载荷字节的最小信封编码大小。
		///     </para>
		/// </summary>
		public static int MinEnvelopeSize => MagicLength + 2 + 4 + 8 + 4 + 4;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the <c>"STS2RitsuLib"u8</c> packet prefix.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 <c>"STS2RitsuLib"u8</c> 数据包前缀。
		///     </para>
		/// </summary>
		public static ReadOnlySpan<byte> Magic => "STS2RitsuLib"u8;

		/// <summary>
		///     <para xml:lang="en">
		///         Returns <see langword="true" /> when <paramref name="packet" /> begins with <see cref="P:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarWire.Magic" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当 <paramref name="packet" /> 以 <see cref="P:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarWire.Magic" /> 开头时返回 <see langword="true" />。
		///     </para>
		/// </summary>
		public static bool MatchesMagic(ReadOnlySpan<byte> packet)
		{
			if (packet.Length >= MagicLength)
			{
				return packet.Slice(0, MagicLength).SequenceEqual(Magic);
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Tries to read the 64-bit opcode from a sufficiently long sidecar envelope prefix without validating
		///         the complete envelope.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试从长度足够的 sidecar 信封前缀读取 64 位操作码，但不验证完整信封。
		///     </para>
		/// </summary>
		public static bool TryPeekOpcode(ReadOnlySpan<byte> packet, out ulong opcode)
		{
			opcode = 0uL;
			if (packet.Length < MagicLength + 2 + 4 + 8 || !MatchesMagic(packet))
			{
				return false;
			}
			opcode = BinaryPrimitives.ReadUInt64BigEndian(packet.Slice(RitsuLibSidecarEnvelopeLayout.OpcodeOffset, 8));
			return true;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines the 32-bit, big-endian flags in a sidecar envelope. Unknown bits are cleared when read.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义 sidecar 信封中采用大端序编码的 32 位标志；读取时会清除未知位。
	///     </para>
	/// </summary>
	[Flags]
	public enum RitsuLibSidecarWireFlags : uint
	{
		/// <summary>
		///     <para xml:lang="en">
		///         No flags are set.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         不设置任何标志。
		///     </para>
		/// </summary>
		None = 0u,
		/// <summary>
		///     <para xml:lang="en">
		///         The payload uses gzip compression; handlers receive decompressed bytes.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         载荷使用 gzip 压缩；处理器接收解压后的字节。
		///     </para>
		/// </summary>
		PayloadGzip = 1u,
		/// <summary>
		///     <para xml:lang="en">
		///         The payload uses Brotli compression; handlers receive decompressed bytes.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         载荷使用 Brotli 压缩；处理器接收解压后的字节。
		///     </para>
		/// </summary>
		PayloadBrotli = 2u
	}
	/// <summary>
	///     <para xml:lang="en">Carries the state and metadata for one synchronized configuration-topic change.</para>
	///     <para xml:lang="zh-CN">携带一次同步配置主题变更的状态和元数据。</para>
	/// </summary>
	public readonly record struct SidecarConfigTopicChangedEvent(string Topic, long Revision, ulong ChangedByPeer, string Reason, string StateJson);
	internal readonly record struct ConfigStateSnapshotMessage(string Topic, long Revision, string StateJson);
	internal readonly record struct ConfigChangeRequestMessage(string Topic, string RequestId, string DeltaJson, string Reason);
	internal readonly record struct ConfigChangeDecisionMessage(string Topic, string RequestId, bool Approved, string Reason, long Revision, string StateJson);
	/// <summary>
	///     <para xml:lang="en">
	///         Provides host-authoritative Sidecar configuration synchronization. Topic-state updates are committed
	///         before <see cref="E:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarConfigSyncService.TopicChanged" /> runs; its subscribers execute synchronously.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供主机权威的 Sidecar 配置同步。主题状态更新会在运行 <see cref="E:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarConfigSyncService.TopicChanged" /> 前提交；其订阅者同步执行。
	///     </para>
	/// </summary>
	public static class RitsuLibSidecarConfigSyncService
	{
		private readonly record struct TopicState(long Revision, string StateJson, Func<ulong, string, bool> CanClientRequest, Func<string, string, DeltaApplyResult> ApplyDelta);

		private readonly record struct DeltaApplyResult(bool Succeeded, string StateJson);

		private sealed class HandlerSubscriptionGroup(IDisposable request, IDisposable snapshot, IDisposable decision) : IDisposable
		{
			public void Dispose()
			{
				decision.Dispose();
				snapshot.Dispose();
				request.Dispose();
			}
		}

		private static readonly Lock Gate = new Lock();

		private static readonly Lock HandlerGate = new Lock();

		private static readonly Dictionary<string, TopicState> Topics = new Dictionary<string, TopicState>();

		private static readonly RitsuLibSidecarMessageDescriptor<ConfigStateSnapshotMessage> SnapshotDescriptor = new RitsuLibSidecarMessageDescriptor<ConfigStateSnapshotMessage>("com.ritsukage.sts2-RitsuLib", "cfg_snapshot", (ConfigStateSnapshotMessage m) => JsonSerializer.SerializeToUtf8Bytes(m), (ReadOnlySpan<byte> payload) => JsonSerializer.Deserialize<ConfigStateSnapshotMessage>(payload));

		private static readonly RitsuLibSidecarMessageDescriptor<ConfigChangeRequestMessage> RequestDescriptor = new RitsuLibSidecarMessageDescriptor<ConfigChangeRequestMessage>("com.ritsukage.sts2-RitsuLib", "cfg_change_req", (ConfigChangeRequestMessage m) => JsonSerializer.SerializeToUtf8Bytes(m), (ReadOnlySpan<byte> payload) => JsonSerializer.Deserialize<ConfigChangeRequestMessage>(payload));

		private static readonly RitsuLibSidecarMessageDescriptor<ConfigChangeDecisionMessage> DecisionDescriptor = new RitsuLibSidecarMessageDescriptor<ConfigChangeDecisionMessage>("com.ritsukage.sts2-RitsuLib", "cfg_change_decision", (ConfigChangeDecisionMessage m) => JsonSerializer.SerializeToUtf8Bytes(m), (ReadOnlySpan<byte> payload) => JsonSerializer.Deserialize<ConfigChangeDecisionMessage>(payload));

		private static IDisposable? _handlerSubscriptions;

		/// <summary>
		///     <para xml:lang="en">Raised after a topic state is updated locally or from a remote snapshot or decision.</para>
		///     <para xml:lang="zh-CN">在主题状态从本地或远程快照、决策更新后引发。</para>
		/// </summary>
		public static event Action<SidecarConfigTopicChangedEvent>? TopicChanged;

		/// <summary>
		///     <para xml:lang="en">
		///         Registers or replaces a synchronized configuration topic with its initial state, client-request
		///         policy, and delta-application logic. Policy and delta callbacks run under the topic lock when a
		///         host processes a request.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用初始状态、客户端请求策略和增量应用逻辑注册或替换同步配置主题。主机处理请求时，策略和增量回调在主题锁内运行。
		///     </para>
		/// </summary>
		public static void RegisterTopic<TState, TDelta>(string topic, TState initialState, Func<ulong, TDelta, bool> canClientRequest, Func<TState, TDelta, TState> applyDelta)
		{
			ArgumentException.ThrowIfNullOrEmpty(topic, "topic");
			ArgumentNullException.ThrowIfNull(canClientRequest, "canClientRequest");
			ArgumentNullException.ThrowIfNull(applyDelta, "applyDelta");
			EnsureHandlers();
			using (Gate.EnterScope())
			{
				Topics[topic] = new TopicState(1L, JsonSerializer.Serialize(initialState), delegate(ulong sender, string deltaJson)
				{
					if (!TryDeserialize<TDelta>(deltaJson, out var value))
					{
						return false;
					}
					try
					{
						return canClientRequest(sender, value);
					}
					catch (Exception ex)
					{
						RitsuLibSidecarRepeatedWarningLog.Warn($"config-can-client-request:topic={topic}:sender={sender}:{ex.GetType().FullName}:{ex.Message}", $"[Sidecar] Config canClientRequest failed topic={topic}, sender={sender}: {ex}");
						return false;
					}
				}, delegate(string stateJson, string deltaJson)
				{
					if (!TryDeserialize<TState>(stateJson, out var value) || !TryDeserialize<TDelta>(deltaJson, out var value2))
					{
						return new DeltaApplyResult(Succeeded: false, stateJson);
					}
					try
					{
						return new DeltaApplyResult(Succeeded: true, JsonSerializer.Serialize(applyDelta(value, value2)));
					}
					catch (Exception ex)
					{
						RitsuLibSidecarRepeatedWarningLog.Warn($"config-apply-delta:topic={topic}:{ex.GetType().FullName}:{ex.Message}", $"[Sidecar] Config applyDelta failed topic={topic}: {ex}");
						return new DeltaApplyResult(Succeeded: false, stateJson);
					}
				});
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sends a client-side configuration-change request through a direct network-service reference. A
		///         successful result reports only local send acceptance, not host approval or state persistence.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过直接网络服务引用发送客户端配置变更请求。成功结果仅表示本地接受发送，不表示主机已批准或状态已持久化。
		///     </para>
		/// </summary>
		public static bool TryRequestClientChange<TDelta>(INetGameService? netService, string topic, TDelta delta, string reason = "")
		{
			EnsureHandlers();
			return RitsuLibSidecarTypedMessageRegistry.SendToHost(netService, RequestDescriptor, new ConfigChangeRequestMessage(topic, Guid.NewGuid().ToString("N"), JsonSerializer.Serialize(delta), reason));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sends a client-side configuration-change request through <see cref="T:MegaCrit.Sts2.Core.Runs.RunManager" />. A successful
		///         result reports only local send acceptance, not host approval or state persistence.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过 <see cref="T:MegaCrit.Sts2.Core.Runs.RunManager" /> 发送客户端配置变更请求。成功结果仅表示本地接受发送，不表示主机已批准或状态已持久化。
		///     </para>
		/// </summary>
		public static bool TryRequestClientChange<TDelta>(RunManager? runManager, string topic, TDelta delta, string reason = "")
		{
			EnsureHandlers();
			return RitsuLibSidecarTypedMessageRegistry.SendToHost(runManager, RequestDescriptor, new ConfigChangeRequestMessage(topic, Guid.NewGuid().ToString("N"), JsonSerializer.Serialize(delta), reason));
		}

		/// <summary>
		///     <para xml:lang="en">Tries to deserialize and read the cached state and revision for a topic.</para>
		///     <para xml:lang="zh-CN">尝试反序列化并读取主题的缓存状态和修订号。</para>
		/// </summary>
		public static bool TryGetTopicState<TState>(string topic, out TState? state, out long revision)
		{
			using (Gate.EnterScope())
			{
				if (!Topics.TryGetValue(topic, out var value))
				{
					state = default(TState);
					revision = 0L;
					return false;
				}
				state = JsonSerializer.Deserialize<TState>(value.StateJson);
				revision = value.Revision;
				return true;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Raises the local topic-change event and broadcasts the current host snapshot when the topic exists.
		///         It does not return the broadcast outcome.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         主题存在时引发本地主题变更事件并广播当前主机快照；该方法不返回广播结果。
		///     </para>
		/// </summary>
		public static void PublishHostState(INetGameService? netService, string topic, ulong changedBy, string reason)
		{
			TopicState value;
			using (Gate.EnterScope())
			{
				if (!Topics.TryGetValue(topic, out value))
				{
					return;
				}
			}
			TopicChanged?.Invoke(new SidecarConfigTopicChangedEvent(topic, value.Revision, changedBy, reason, value.StateJson));
			RitsuLibSidecarTypedMessageRegistry.Broadcast(netService, SnapshotDescriptor, new ConfigStateSnapshotMessage(topic, value.Revision, value.StateJson));
		}

		private static void EnsureHandlers()
		{
			if (_handlerSubscriptions != null)
			{
				return;
			}
			using (HandlerGate.EnterScope())
			{
				if (_handlerSubscriptions != null)
				{
					return;
				}
				IDisposable disposable = null;
				IDisposable disposable2 = null;
				IDisposable disposable3 = null;
				try
				{
					disposable = RitsuLibSidecarTypedMessageRegistry.Subscribe(RequestDescriptor, OnRequestMessage);
					disposable2 = RitsuLibSidecarTypedMessageRegistry.Subscribe(SnapshotDescriptor, OnSnapshotMessage);
					disposable3 = RitsuLibSidecarTypedMessageRegistry.Subscribe(DecisionDescriptor, OnDecisionMessage);
					_handlerSubscriptions = new HandlerSubscriptionGroup(disposable, disposable2, disposable3);
				}
				catch
				{
					disposable3?.Dispose();
					disposable2?.Dispose();
					disposable?.Dispose();
					throw;
				}
			}
		}

		private static void OnRequestMessage(RitsuLibSidecarTypedDispatchContext<ConfigChangeRequestMessage> ctx)
		{
			RunManager instance = RunManager.Instance;
			INetGameService val = ((instance != null) ? instance.NetService : null);
			if (!(val is NetHostGameService))
			{
				return;
			}
			bool flag;
			string reason;
			long revision;
			string stateJson;
			using (Gate.EnterScope())
			{
				if (!Topics.TryGetValue(ctx.Message.Topic, out var value))
				{
					flag = false;
					reason = "topic_not_found";
					revision = 0L;
					stateJson = string.Empty;
				}
				else if (!value.CanClientRequest(ctx.SenderNetId, ctx.Message.DeltaJson))
				{
					flag = false;
					reason = "client_request_rejected";
					revision = value.Revision;
					stateJson = value.StateJson;
				}
				else
				{
					DeltaApplyResult deltaApplyResult = value.ApplyDelta(value.StateJson, ctx.Message.DeltaJson);
					flag = deltaApplyResult.Succeeded;
					reason = ((!flag) ? "apply_delta_failed" : (string.IsNullOrWhiteSpace(ctx.Message.Reason) ? "applied" : ctx.Message.Reason));
					revision = (flag ? (value.Revision + 1) : value.Revision);
					stateJson = (flag ? deltaApplyResult.StateJson : value.StateJson);
					if (flag)
					{
						Topics[ctx.Message.Topic] = value with
						{
							Revision = revision,
							StateJson = stateJson
						};
					}
				}
			}
			RitsuLibSidecarTypedMessageRegistry.SendToPeer(val, ctx.SenderNetId, DecisionDescriptor, new ConfigChangeDecisionMessage(ctx.Message.Topic, ctx.Message.RequestId, flag, reason, revision, stateJson));
			if (flag)
			{
				PublishHostState(val, ctx.Message.Topic, ctx.SenderNetId, reason);
			}
		}

		private static void OnSnapshotMessage(RitsuLibSidecarTypedDispatchContext<ConfigStateSnapshotMessage> ctx)
		{
			using (Gate.EnterScope())
			{
				if (Topics.TryGetValue(ctx.Message.Topic, out var value) && value.Revision > ctx.Message.Revision)
				{
					return;
				}
				Topics[ctx.Message.Topic] = new TopicState(ctx.Message.Revision, ctx.Message.StateJson, (ulong _, string _) => false, (string state, string _) => new DeltaApplyResult(Succeeded: true, state));
			}
			TopicChanged?.Invoke(new SidecarConfigTopicChangedEvent(ctx.Message.Topic, ctx.Message.Revision, ctx.SenderNetId, "snapshot", ctx.Message.StateJson));
		}

		private static void OnDecisionMessage(RitsuLibSidecarTypedDispatchContext<ConfigChangeDecisionMessage> ctx)
		{
			if (!ctx.Message.Approved)
			{
				RitsuLibSidecarRepeatedWarningLog.Warn("config-rejected:topic=" + ctx.Message.Topic + ":reason=" + ctx.Message.Reason, $"[Sidecar] Config change rejected topic={ctx.Message.Topic}, request={ctx.Message.RequestId}, reason={ctx.Message.Reason}");
				return;
			}
			using (Gate.EnterScope())
			{
				Topics[ctx.Message.Topic] = new TopicState(ctx.Message.Revision, ctx.Message.StateJson, (ulong _, string _) => false, (string state, string _) => new DeltaApplyResult(Succeeded: true, state));
			}
			TopicChanged?.Invoke(new SidecarConfigTopicChangedEvent(ctx.Message.Topic, ctx.Message.Revision, ctx.SenderNetId, ctx.Message.Reason, ctx.Message.StateJson));
		}

		private static bool TryDeserialize<T>(string json, out T value)
		{
			try
			{
				T val = JsonSerializer.Deserialize<T>(json);
				if (val == null)
				{
					value = default(T);
					return false;
				}
				value = val;
				return true;
			}
			catch
			{
				value = default(T);
				return false;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Manages sidecar capability negotiation through
	///         <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarControlOpcodes.Handshake" /> messages.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarControlOpcodes.Handshake" /> 消息管理 sidecar 功能协商。
	///     </para>
	/// </summary>
	public static class RitsuLibSidecarConnectionExchange
	{
		private enum NegotiationOutboundPhase : byte
		{
			Idle,
			AwaitingAck,
			Completed
		}

		private struct HelloOutboundNegotiationState
		{
			internal long SessionEpoch;

			internal NegotiationOutboundPhase Phase;

			internal int PacketsConsumed;

			internal long NextTransportAttemptTickCount64;

			internal int TransportBackoffMilliseconds;

			internal long AckDeadlineTickCount64;

			internal bool LoggedFirstTransportFailureWarn;
		}

		private const int HelloMaxPacketAttempts = 6;

		private const int HelloAckTimeoutMilliseconds = 12000;

		private const int HelloInitialBackoffMilliseconds = 250;

		private const int HelloMaxBackoffMilliseconds = 8000;

		private const int HelloAckTimeoutRetryDeferMilliseconds = 250;

		private static readonly Lock ExchangeGate = new Lock();

		/// <remarks>
		///     <para xml:lang="en">
		///         State is cleared when <see cref="P:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarSessionManager.Epoch" /> changes. Successful
		///         negotiation remains complete until disconnection or the next epoch.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         <see cref="P:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarSessionManager.Epoch" /> 变化时会清除状态。协商成功后，该对等端在断开连接
		///         或进入下一纪元前保持完成状态。
		///     </para>
		/// </remarks>
		private static readonly Dictionary<ulong, HelloOutboundNegotiationState> NegotiationByPeer = new Dictionary<ulong, HelloOutboundNegotiationState>();

		private static long _negotiationAlignedEpoch;

		/// <summary>
		///     <para xml:lang="en">
		///         Removes outbound handshake pacing and acknowledgement state for a peer.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         移除指定对等端的出站握手节流和确认状态。
		///     </para>
		/// </summary>
		public static void RemoveNegotiationStateForPeer(ulong peerNetId)
		{
			using (ExchangeGate.EnterScope())
			{
				NegotiationByPeer.Remove(peerNetId);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Applies a received handshake acknowledgement to the matching outbound negotiation.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将收到的握手确认应用到对应的出站协商。
		///     </para>
		/// </summary>
		public static void NotifyOutboundHandshakeAck(ulong responderNetId, bool negotiationOk)
		{
			using (ExchangeGate.EnterScope())
			{
				long epoch = RitsuLibSidecarSessionManager.Epoch;
				if (!NegotiationByPeer.TryGetValue(responderNetId, out var value) || value.SessionEpoch != epoch || value.Phase != NegotiationOutboundPhase.AwaitingAck)
				{
					return;
				}
				if (!negotiationOk)
				{
					NegotiationByPeer.Remove(responderNetId);
					return;
				}
				value.Phase = NegotiationOutboundPhase.Completed;
				NegotiationByPeer[responderNetId] = value;
			}
			RitsuLibFramework.Logger.Debug($"[Sidecar] Handshake negotiation completed peer={responderNetId}, epoch={RitsuLibSidecarSessionManager.Epoch}", 1);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Removes all outbound handshake state after a multiplayer session ends.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         多人会话结束后移除所有出站握手状态。
		///     </para>
		/// </summary>
		public static void DiscardNegotiationStateAfterSessionEnds()
		{
			long epoch = RitsuLibSidecarSessionManager.Epoch;
			using (ExchangeGate.EnterScope())
			{
				NegotiationByPeer.Clear();
				_negotiationAlignedEpoch = epoch;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Processes acknowledgement timeouts for pending outbound handshakes.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         处理待定出站握手的确认超时。
		///     </para>
		/// </summary>
		public static void TickHandshakeNegotiation()
		{
			EnsureExchangeEpochAligned();
			long tickCount = Environment.TickCount64;
			ulong[] array;
			using (ExchangeGate.EnterScope())
			{
				bool flag = false;
				foreach (HelloOutboundNegotiationState value in NegotiationByPeer.Values)
				{
					if (value.Phase == NegotiationOutboundPhase.AwaitingAck)
					{
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					return;
				}
				array = NegotiationByPeer.Keys.ToArray();
			}
			ulong[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				TryProcessAckTimeout(array2[i], tickCount);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts a client handshake using the network service from <see cref="P:MegaCrit.Sts2.Core.Runs.RunManager.Instance" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用 <see cref="P:MegaCrit.Sts2.Core.Runs.RunManager.Instance" /> 中的网络服务尝试客户端握手。
		///     </para>
		/// </summary>
		public static void TrySendLocalClientHello()
		{
			RunManager instance = RunManager.Instance;
			TrySendClientHelloIfReachable((instance != null) ? instance.NetService : null);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts a sidecar handshake with peers already marked
		///         <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarPeerReachability.Supported" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         仅对已标记为 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarPeerReachability.Supported" /> 的对等端尝试 sidecar 握手。
		///     </para>
		/// </summary>
		public static void TrySendClientHelloIfReachable(INetGameService? netService)
		{
			//IL_0004: Unknown result type (might be due to invalid IL or missing references)
			//IL_000a: Invalid comparison between Unknown and I4
			if (netService == null || (int)netService.Type == 1)
			{
				return;
			}
			EnsureExchangeEpochAligned();
			NetClientGameService val = (NetClientGameService)(object)((netService is NetClientGameService) ? netService : null);
			if (val == null)
			{
				if (!(netService is NetHostGameService))
				{
					return;
				}
				{
					foreach (ulong item in RitsuLibSidecarSessionManager.GetSupportedPeersForIteration())
					{
						TrySendHelloToPeerIfReachable(netService, item);
					}
					return;
				}
			}
			TrySendHelloToPeerIfReachable(netService, val.HostNetId);
		}

		private static void EnsureExchangeEpochAligned()
		{
			long epoch = RitsuLibSidecarSessionManager.Epoch;
			if (_negotiationAlignedEpoch != epoch)
			{
				using (ExchangeGate.EnterScope())
				{
					NegotiationByPeer.Clear();
				}
				_negotiationAlignedEpoch = epoch;
			}
		}

		private static void TryProcessAckTimeout(ulong peerNetId, long nowTickCount64)
		{
			bool flag = false;
			using (ExchangeGate.EnterScope())
			{
				if (!NegotiationByPeer.TryGetValue(peerNetId, out var value))
				{
					return;
				}
				long epoch = RitsuLibSidecarSessionManager.Epoch;
				if (value.SessionEpoch != epoch || value.Phase != NegotiationOutboundPhase.AwaitingAck || nowTickCount64 < value.AckDeadlineTickCount64)
				{
					return;
				}
				if (value.PacketsConsumed >= 6)
				{
					NegotiationByPeer.Remove(peerNetId);
					flag = true;
				}
				else
				{
					value.Phase = NegotiationOutboundPhase.Idle;
					value.NextTransportAttemptTickCount64 = nowTickCount64 + 250;
					NegotiationByPeer[peerNetId] = value;
				}
			}
			if (flag)
			{
				RitsuLibSidecarSessionManager.NoteHandshakeNegotiationAborted(peerNetId, "handshake_ack_timeout");
				RitsuLibFramework.Logger.Warn($"[Sidecar] Handshake abandoned after repeated ack timeouts (packet budget exhausted) peer={peerNetId}, epoch={RitsuLibSidecarSessionManager.Epoch}", 1);
			}
		}

		private static void TrySendHelloToPeerIfReachable(INetGameService netService, ulong peerNetId)
		{
			//IL_00c8: Unknown result type (might be due to invalid IL or missing references)
			//IL_02b1: Unknown result type (might be due to invalid IL or missing references)
			//IL_0316: Unknown result type (might be due to invalid IL or missing references)
			//IL_0386: Unknown result type (might be due to invalid IL or missing references)
			if (!RitsuLibSidecarSessionManager.CanSendToPeer(peerNetId))
			{
				return;
			}
			long epoch = RitsuLibSidecarSessionManager.Epoch;
			long tickCount = Environment.TickCount64;
			bool flag;
			using (ExchangeGate.EnterScope())
			{
				GetOrResetPeerState(epoch, peerNetId, out var state);
				NegotiationOutboundPhase phase = state.Phase;
				if (phase - 1 <= NegotiationOutboundPhase.AwaitingAck || state.PacketsConsumed >= 6 || tickCount < state.NextTransportAttemptTickCount64)
				{
					return;
				}
				flag = state.PacketsConsumed == 0;
				NegotiationByPeer[peerNetId] = state;
			}
			if (flag)
			{
				RitsuLibFramework.Logger.Debug($"[Sidecar] Handshake queued peer={peerNetId}, epoch={epoch}, netType={netService.Type}", 1);
			}
			RitsuLibSidecarProtocol.EnsureDefaultHandlers();
			byte[] array = new byte[8];
			RitsuLibSidecarHandshakeBinary.WriteHandshake(array.AsSpan(), 2, 2, (RitsuLibSidecarPeerFeatures)255u);
			bool flag2 = ((netService is NetClientGameService) ? RitsuLibSidecarHighLevelSend.TrySendAsClient(netService, 16uL, array, RitsuLibSidecarDeliverySemantics.StableSync) : (netService is NetHostGameService && RitsuLibSidecarHighLevelSend.TrySendAsHostToPeer(netService, peerNetId, 16uL, array, RitsuLibSidecarDeliverySemantics.StableSync)));
			bool flag3 = flag2;
			bool flag4 = false;
			bool flag5 = false;
			bool flag6 = false;
			using (ExchangeGate.EnterScope())
			{
				if (!NegotiationByPeer.TryGetValue(peerNetId, out var value) || value.SessionEpoch != epoch)
				{
					return;
				}
				value.PacketsConsumed++;
				if (!flag3)
				{
					int num = ((value.TransportBackoffMilliseconds == 0) ? 250 : (value.TransportBackoffMilliseconds * 2));
					if (num > 8000)
					{
						num = 8000;
					}
					value.TransportBackoffMilliseconds = num;
					value.NextTransportAttemptTickCount64 = tickCount + num;
					value.Phase = NegotiationOutboundPhase.Idle;
					if (value.PacketsConsumed >= 6)
					{
						NegotiationByPeer.Remove(peerNetId);
						flag4 = true;
					}
					else
					{
						if (!value.LoggedFirstTransportFailureWarn)
						{
							value.LoggedFirstTransportFailureWarn = true;
							flag5 = true;
						}
						NegotiationByPeer[peerNetId] = value;
					}
				}
				else
				{
					value.Phase = NegotiationOutboundPhase.AwaitingAck;
					value.AckDeadlineTickCount64 = tickCount + 12000;
					value.TransportBackoffMilliseconds = 0;
					NegotiationByPeer[peerNetId] = value;
					flag6 = true;
				}
			}
			if (flag4)
			{
				RitsuLibSidecarSessionManager.NoteHandshakeNegotiationAborted(peerNetId, "handshake_transport_budget");
				RitsuLibFramework.Logger.Warn($"[Sidecar] Handshake abandoned: transport send budget exhausted peer={peerNetId}, epoch={epoch}, netType={netService.Type}", 1);
				return;
			}
			if (flag5)
			{
				RitsuLibFramework.Logger.Warn($"[Sidecar] Handshake send failed peer={peerNetId}, epoch={epoch}, netType={netService.Type}; retrying with backoff (no further transport-failure logs until negotiation ends)", 1);
			}
			if (flag6)
			{
				RitsuLibFramework.Logger.Debug($"[Sidecar] Handshake sent peer={peerNetId}, epoch={epoch}, netType={netService.Type}, opcode={16uL}, payloadLen={array.Length}", 1);
			}
		}

		private static void GetOrResetPeerState(long epochNow, ulong peerNetId, out HelloOutboundNegotiationState state)
		{
			if (!NegotiationByPeer.TryGetValue(peerNetId, out state) || state.SessionEpoch != epochNow)
			{
				state = new HelloOutboundNegotiationState
				{
					SessionEpoch = epochNow,
					Phase = NegotiationOutboundPhase.Idle,
					PacketsConsumed = 0,
					NextTransportAttemptTickCount64 = 0L,
					TransportBackoffMilliseconds = 0,
					AckDeadlineTickCount64 = 0L,
					LoggedFirstTransportFailureWarn = false
				};
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Stores the last feature flags reported by each peer through a sidecar handshake.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         存储各对等端通过 sidecar 握手报告的最新功能标志。
	///     </para>
	/// </summary>
	public static class RitsuLibSidecarConnectionSession
	{
		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<ulong, RitsuLibSidecarPeerFeatures> PeerToFeatures = new Dictionary<ulong, RitsuLibSidecarPeerFeatures>();

		/// <summary>
		///     <para xml:lang="en">
		///         Records the feature flags reported by <paramref name="remoteNetId" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         记录 <paramref name="remoteNetId" /> 报告的功能标志。
		///     </para>
		/// </summary>
		public static void SetPeerFeatures(ulong remoteNetId, RitsuLibSidecarPeerFeatures features)
		{
			using (Gate.EnterScope())
			{
				PeerToFeatures[remoteNetId] = features;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Tries to get the last feature flags recorded for <paramref name="remoteNetId" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试获取为 <paramref name="remoteNetId" /> 记录的最新功能标志。
		///     </para>
		/// </summary>
		public static bool TryGetPeerFeatures(ulong remoteNetId, out RitsuLibSidecarPeerFeatures features)
		{
			using (Gate.EnterScope())
			{
				return PeerToFeatures.TryGetValue(remoteNetId, out features);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Removes all cached peer feature flags.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         移除所有缓存的对等端功能标志。
		///     </para>
		/// </summary>
		public static void Clear()
		{
			using (Gate.EnterScope())
			{
				PeerToFeatures.Clear();
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Maintains Sidecar session state, including the current multiplayer service, peer reachability and
	///         features, and pluggable capability-validation routes.
	///     </para>
	///     <para xml:lang="zh-CN">维护 Sidecar 会话状态，包括当前多人游戏服务、对等方可达性和功能以及可插拔的能力验证路由。</para>
	/// </summary>
	public static class RitsuLibSidecarSessionManager
	{
		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<ulong, RitsuLibSidecarPeerReachability> PeerReachability = new Dictionary<ulong, RitsuLibSidecarPeerReachability>();

		private static readonly Dictionary<ulong, RitsuLibSidecarPeerFeatures> PeerFeatures = new Dictionary<ulong, RitsuLibSidecarPeerFeatures>();

		private static readonly HashSet<ulong> HandshakeNegotiationTerminalPeers = new HashSet<ulong>();

		private static readonly List<IRitsuLibSidecarCapabilityValidationRoute> ValidationRoutes = new List<IRitsuLibSidecarCapabilityValidationRoute>();

		private static IRitsuLibSidecarCapabilityValidationRoute[] _validationRoutesSnapshot = Array.Empty<IRitsuLibSidecarCapabilityValidationRoute>();

		private static ulong[] _peerIdsSnapshot = Array.Empty<ulong>();

		private static ulong[] _supportedPeerIdsSnapshot = Array.Empty<ulong>();

		private static INetGameService? _currentNetService;

		private static long _epoch;

		private static bool _providerBootstrapped;

		/// <summary>
		///     <para xml:lang="en">Current session epoch, incremented for each observed network-service switch.</para>
		///     <para xml:lang="zh-CN">当前会话纪元；每次观察到网络服务切换时递增。</para>
		/// </summary>
		public static long Epoch
		{
			get
			{
				using (Gate.EnterScope())
				{
					return _epoch;
				}
			}
		}

		internal static INetGameService? CurrentNetService
		{
			get
			{
				using (Gate.EnterScope())
				{
					return _currentNetService;
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">Raised after a non-singleplayer service has become the active session service.</para>
		///     <para xml:lang="zh-CN">在非单人游戏服务成为活动会话服务后引发。</para>
		/// </summary>
		public static event Action<SidecarSessionBoundEvent>? SessionBound;

		/// <summary>
		///     <para xml:lang="en">Raised after the session transitions to an unbound or single-player service.</para>
		///     <para xml:lang="zh-CN">在会话转换为未绑定或单人游戏服务后引发。</para>
		/// </summary>
		public static event Action<SidecarSessionUnboundEvent>? SessionUnbound;

		/// <summary>
		///     <para xml:lang="en">Raised after a peer's reachability state changes.</para>
		///     <para xml:lang="zh-CN">在对等方的可达性状态改变后引发。</para>
		/// </summary>
		public static event Action<SidecarPeerReachabilityChangedEvent>? PeerReachabilityChanged;

		/// <summary>
		///     <para xml:lang="en">Raised after accepted handshake information marks a peer as Sidecar-capable.</para>
		///     <para xml:lang="zh-CN">在已接受的握手信息将对等方标记为支持 Sidecar 后引发。</para>
		/// </summary>
		public static event Action<SidecarHandshakeCompletedEvent>? HandshakeCompleted;

		/// <summary>
		///     <para xml:lang="en">Ensures the built-in capability-validation routes are registered once.</para>
		///     <para xml:lang="zh-CN">确保内置能力验证路由只注册一次。</para>
		/// </summary>
		public static void EnsureProvidersBootstrapped()
		{
			using (Gate.EnterScope())
			{
				if (!_providerBootstrapped)
				{
					ValidationRoutes.Add(new RitsuLibSidecarManualHintValidationRoute());
					ValidationRoutes.Add(new RitsuLibSidecarNativeTrailerValidationRoute());
					if (!RitsuLibMobileSteamRuntime.SuppressNativeSteamIntegration)
					{
						ValidationRoutes.Add(new RitsuLibSidecarSteamLobbyValidationRoute());
					}
					RebuildValidationRoutesSnapshotLocked();
					_providerBootstrapped = true;
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers an additional validation route, deduplicated by concrete route type.</para>
		///     <para xml:lang="zh-CN">注册额外验证路由，并按路由具体类型去重。</para>
		/// </summary>
		public static void RegisterValidationRoute(IRitsuLibSidecarCapabilityValidationRoute route)
		{
			ArgumentNullException.ThrowIfNull(route, "route");
			EnsureProvidersBootstrapped();
			using (Gate.EnterScope())
			{
				if (!ValidationRoutes.Any((IRitsuLibSidecarCapabilityValidationRoute r) => r.GetType() == route.GetType()))
				{
					ValidationRoutes.Add(route);
					ValidationRoutes.Sort((IRitsuLibSidecarCapabilityValidationRoute a, IRitsuLibSidecarCapabilityValidationRoute b) => a.Order.CompareTo(b.Order));
					RebuildValidationRoutesSnapshotLocked();
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Observes the current network service and updates session state when its instance changes. It raises
		///         session events only after committing the new state; event subscribers run synchronously.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         观察当前网络服务，并在其实例变更时更新会话状态。仅在提交新状态后引发会话事件；事件订阅者同步运行。
		///     </para>
		/// </summary>
		public static void ObserveNetService(INetGameService? netService)
		{
			//IL_0069: Unknown result type (might be due to invalid IL or missing references)
			//IL_006f: Invalid comparison between Unknown and I4
			//IL_00a9: Unknown result type (might be due to invalid IL or missing references)
			//IL_00af: Invalid comparison between Unknown and I4
			//IL_018c: Unknown result type (might be due to invalid IL or missing references)
			EnsureProvidersBootstrapped();
			SidecarSessionBoundEvent? sidecarSessionBoundEvent = null;
			SidecarSessionUnboundEvent? sidecarSessionUnboundEvent = null;
			ulong[] array = Array.Empty<ulong>();
			using (Gate.EnterScope())
			{
				if (_currentNetService == netService)
				{
					return;
				}
				_epoch++;
				PeerReachability.Clear();
				PeerFeatures.Clear();
				HandshakeNegotiationTerminalPeers.Clear();
				_currentNetService = netService;
				if (netService == null || (int)netService.Type == 1)
				{
					sidecarSessionUnboundEvent = new SidecarSessionUnboundEvent(_epoch);
				}
				else
				{
					SeedKnownPeers(netService);
					RebuildPeerSnapshotsLocked();
					array = _peerIdsSnapshot;
					sidecarSessionBoundEvent = new SidecarSessionBoundEvent(netService, _epoch);
				}
				if (netService == null || (int)netService.Type == 1)
				{
					RebuildPeerSnapshotsLocked();
				}
			}
			if (sidecarSessionUnboundEvent.HasValue)
			{
				SidecarSessionUnboundEvent valueOrDefault = sidecarSessionUnboundEvent.GetValueOrDefault();
				Trace($"Session unbound epoch={valueOrDefault.Epoch}");
				SessionUnbound?.Invoke(valueOrDefault);
			}
			if (sidecarSessionBoundEvent.HasValue)
			{
				SidecarSessionBoundEvent valueOrDefault2 = sidecarSessionBoundEvent.GetValueOrDefault();
				DispatchPublishLocalEvidence(valueOrDefault2.NetService);
				ulong[] array2 = array;
				for (int i = 0; i < array2.Length; i++)
				{
					RefreshReachabilityFromProviders(array2[i]);
				}
				Trace($"Session bound epoch={valueOrDefault2.Epoch}, netType={valueOrDefault2.NetService.Type}, netId={valueOrDefault2.NetService.NetId}");
				SessionBound?.Invoke(valueOrDefault2);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Returns whether the peer is currently <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarPeerReachability.Supported" />.</para>
		///     <para xml:lang="zh-CN">返回该对等方当前是否为 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarPeerReachability.Supported" />。</para>
		/// </summary>
		public static bool CanSendToPeer(ulong peerNetId)
		{
			if (TryGetReachability(peerNetId, out var reachability))
			{
				return reachability == RitsuLibSidecarPeerReachability.Supported;
			}
			return false;
		}

		/// <summary>
