		/// <summary>
		///     <para xml:lang="en">Records a host-side peer connection, seeds <c>Unknown</c>, then refreshes provider verdicts.</para>
		///     <para xml:lang="zh-CN">记录主机侧对等方连接，设为 <c>Unknown</c>，然后刷新提供方判定。</para>
		/// </summary>
		public static void NotePeerConnected(ulong peerNetId)
		{
			UpdateReachability(peerNetId, RitsuLibSidecarPeerReachability.Unknown, "peer_connected");
			RefreshReachabilityFromProviders(peerNetId);
		}

		/// <summary>
		///     <para xml:lang="en">Removes reachability, feature, and handshake-negotiation state for a disconnected peer.</para>
		///     <para xml:lang="zh-CN">移除已断开对等方的可达性、功能和握手协商状态。</para>
		/// </summary>
		public static void NotePeerDisconnected(ulong peerNetId)
		{
			using (Gate.EnterScope())
			{
				if (PeerReachability.Remove(peerNetId))
				{
					RebuildPeerSnapshotsLocked();
				}
				PeerFeatures.Remove(peerNetId);
				HandshakeNegotiationTerminalPeers.Remove(peerNetId);
			}
			RitsuLibSidecarConnectionExchange.RemoveNegotiationStateForPeer(peerNetId);
			RitsuLibSidecarEndpointProtocol.NotePeerDisconnected(peerNetId);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Marks a peer terminal for outbound handshake negotiation, such as after a transport-budget or
		///         acknowledgement-timeout failure, and forces it to <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarPeerReachability.Unsupported" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将对等方标记为出站握手协商的终止状态，例如传输预算或确认超时失败后，并强制其为
		///         <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarPeerReachability.Unsupported" />。
		///     </para>
		/// </summary>
		public static void NoteHandshakeNegotiationAborted(ulong peerNetId, string reason)
		{
			using (Gate.EnterScope())
			{
				HandshakeNegotiationTerminalPeers.Add(peerNetId);
			}
			UpdateReachability(peerNetId, RitsuLibSidecarPeerReachability.Unsupported, reason);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Marks a peer terminal-unreachable for Sidecar sends after a transport failure indicates its
		///         connection is missing, preventing per-frame resend loops from repeatedly throwing.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在传输失败表明对等方连接缺失后，将其标记为 Sidecar 发送的终止不可达状态，以防逐帧重发循环反复抛出异常。
		///     </para>
		/// </summary>
		public static void NoteTransportConnectionMissing(ulong peerNetId)
		{
			using (Gate.EnterScope())
			{
				HandshakeNegotiationTerminalPeers.Add(peerNetId);
			}
			UpdateReachability(peerNetId, RitsuLibSidecarPeerReachability.Unsupported, "transport_connection_missing");
		}

		/// <summary>
		///     <para xml:lang="en">Stores handshake features and updates peer reachability from the acceptance result.</para>
		///     <para xml:lang="zh-CN">存储握手功能，并根据接受结果更新对等方可达性。</para>
		/// </summary>
		public static void NoteHandshakeFromPeer(ulong peerNetId, RitsuLibSidecarPeerFeatures features, bool accepted)
		{
			using (Gate.EnterScope())
			{
				PeerFeatures[peerNetId] = features;
				if (accepted)
				{
					HandshakeNegotiationTerminalPeers.Remove(peerNetId);
				}
				else
				{
					HandshakeNegotiationTerminalPeers.Add(peerNetId);
				}
			}
			if (!accepted)
			{
				UpdateReachability(peerNetId, RitsuLibSidecarPeerReachability.Unsupported, "handshake");
				return;
			}
			UpdateReachability(peerNetId, RitsuLibSidecarPeerReachability.Supported, "handshake");
			HandshakeCompleted?.Invoke(new SidecarHandshakeCompletedEvent(peerNetId, features, Epoch));
		}

		/// <summary>
		///     <para xml:lang="en">Tries to read the last known feature flags for a peer.</para>
		///     <para xml:lang="zh-CN">尝试读取对等方最后已知的功能标志。</para>
		/// </summary>
		public static bool TryGetPeerFeatures(ulong peerNetId, out RitsuLibSidecarPeerFeatures features)
		{
			using (Gate.EnterScope())
			{
				return PeerFeatures.TryGetValue(peerNetId, out features);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Sets a manual reachability hint, then re-evaluates provider verdicts.</para>
		///     <para xml:lang="zh-CN">设置手动可达性提示，然后重新评估提供方判定。</para>
		/// </summary>
		public static void SetPeerReachabilityHint(ulong peerNetId, RitsuLibSidecarPeerReachability reachability)
		{
			RitsuLibSidecarCapabilityHints.SetHint(peerNetId, reachability);
			RefreshReachabilityFromProviders(peerNetId);
		}

		/// <summary>
		///     <para xml:lang="en">Re-evaluates a peer through registered routes; the first non-null verdict wins.</para>
		///     <para xml:lang="zh-CN">通过已注册路由重新评估对等方；第一个非 <see langword="null" /> 的判定获胜。</para>
		/// </summary>
		public static void RefreshReachabilityFromProviders(ulong peerNetId)
		{
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0030: Invalid comparison between Unknown and I4
			EnsureProvidersBootstrapped();
			INetGameService currentNetService;
			IRitsuLibSidecarCapabilityValidationRoute[] validationRoutesSnapshot;
			using (Gate.EnterScope())
			{
				currentNetService = _currentNetService;
				validationRoutesSnapshot = _validationRoutesSnapshot;
			}
			if (currentNetService == null || (int)currentNetService.Type == 1)
			{
				return;
			}
			IRitsuLibSidecarCapabilityValidationRoute[] array = validationRoutesSnapshot;
			foreach (IRitsuLibSidecarCapabilityValidationRoute ritsuLibSidecarCapabilityValidationRoute in array)
			{
				if (!ritsuLibSidecarCapabilityValidationRoute.IsAvailable(currentNetService))
				{
					continue;
				}
				RitsuLibSidecarPeerReachability? ritsuLibSidecarPeerReachability = ritsuLibSidecarCapabilityValidationRoute.TryResolve(currentNetService, peerNetId);
				if (!ritsuLibSidecarPeerReachability.HasValue)
				{
					continue;
				}
				RitsuLibSidecarPeerReachability ritsuLibSidecarPeerReachability2 = ritsuLibSidecarPeerReachability.Value;
				using (Gate.EnterScope())
				{
					if (ritsuLibSidecarPeerReachability2 == RitsuLibSidecarPeerReachability.Supported && HandshakeNegotiationTerminalPeers.Contains(peerNetId))
					{
						ritsuLibSidecarPeerReachability2 = RitsuLibSidecarPeerReachability.Unsupported;
					}
				}
				UpdateReachability(peerNetId, ritsuLibSidecarPeerReachability2, "route:" + ritsuLibSidecarCapabilityValidationRoute.Name);
				break;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Re-evaluates all currently known peers through the registered routes.</para>
		///     <para xml:lang="zh-CN">通过已注册路由重新评估所有当前已知对等方。</para>
		/// </summary>
		public static void RefreshAllReachabilityFromProviders()
		{
			//IL_0017: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Invalid comparison between Unknown and I4
			ulong[] peerIdsSnapshot;
			using (Gate.EnterScope())
			{
				if (_currentNetService == null || (int)_currentNetService.Type == 1)
				{
					return;
				}
				peerIdsSnapshot = _peerIdsSnapshot;
			}
			ulong[] array = peerIdsSnapshot;
			for (int i = 0; i < array.Length; i++)
			{
				RefreshReachabilityFromProviders(array[i]);
			}
		}

		private static void SeedKnownPeers(INetGameService netService)
		{
			//IL_0025: Unknown result type (might be due to invalid IL or missing references)
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			NetHostGameService val = (NetHostGameService)(object)((netService is NetHostGameService) ? netService : null);
			if (val == null)
			{
				NetClientGameService val2 = (NetClientGameService)(object)((netService is NetClientGameService) ? netService : null);
				if (val2 != null)
				{
					PeerReachability[val2.HostNetId] = RitsuLibSidecarPeerReachability.Unknown;
				}
				return;
			}
			foreach (NetClientData connectedPeer in val.ConnectedPeers)
			{
				PeerReachability[connectedPeer.peerId] = RitsuLibSidecarPeerReachability.Unknown;
			}
		}

		private static void UpdateReachability(ulong peerNetId, RitsuLibSidecarPeerReachability next, string reason)
		{
			SidecarPeerReachabilityChangedEvent? sidecarPeerReachabilityChangedEvent;
			using (Gate.EnterScope())
			{
				bool flag = PeerReachability.TryGetValue(peerNetId, out var value);
				if (!flag)
				{
					value = RitsuLibSidecarPeerReachability.Unknown;
				}
				if (value == next)
				{
					PeerReachability[peerNetId] = next;
					if (!flag)
					{
						RebuildPeerSnapshotsLocked();
					}
					return;
				}
				PeerReachability[peerNetId] = next;
				RebuildPeerSnapshotsLocked();
				sidecarPeerReachabilityChangedEvent = new SidecarPeerReachabilityChangedEvent(peerNetId, value, next, reason, _epoch);
			}
			if (sidecarPeerReachabilityChangedEvent.HasValue)
			{
				SidecarPeerReachabilityChangedEvent valueOrDefault = sidecarPeerReachabilityChangedEvent.GetValueOrDefault();
				Trace($"Peer reachability changed peer={valueOrDefault.PeerNetId}, {valueOrDefault.Previous}->{valueOrDefault.Current}, reason={valueOrDefault.Reason}, epoch={valueOrDefault.Epoch}");
				PeerReachabilityChanged?.Invoke(valueOrDefault);
			}
		}

		private static void Trace(string text)
		{
			RitsuLibFramework.Logger.Info("[Sidecar] " + text, 1);
		}

		private static void DispatchPublishLocalEvidence(INetGameService netService)
		{
			IRitsuLibSidecarCapabilityValidationRoute[] validationRoutesSnapshot;
			using (Gate.EnterScope())
			{
				validationRoutesSnapshot = _validationRoutesSnapshot;
			}
			IRitsuLibSidecarCapabilityValidationRoute[] array = validationRoutesSnapshot;
			foreach (IRitsuLibSidecarCapabilityValidationRoute ritsuLibSidecarCapabilityValidationRoute in array)
			{
				if (ritsuLibSidecarCapabilityValidationRoute.IsAvailable(netService))
				{
					ritsuLibSidecarCapabilityValidationRoute.PublishLocalEvidence(netService);
				}
			}
		}

		private static void RebuildValidationRoutesSnapshotLocked()
		{
			_validationRoutesSnapshot = ValidationRoutes.ToArray();
		}

		private static void RebuildPeerSnapshotsLocked()
		{
			_peerIdsSnapshot = PeerReachability.Keys.ToArray();
			_supportedPeerIdsSnapshot = (from pair in PeerReachability
				where pair.Value == RitsuLibSidecarPeerReachability.Supported
				select pair.Key).ToArray();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Keeps the Sidecar session synchronized with framework lifecycle and network-service changes.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         使 Sidecar 会话与框架生命周期及网络服务变更保持同步。
	///     </para>
	/// </summary>
	public static class RitsuLibSidecarNetworkingLifecycle
	{
		private sealed class SubscriptionGroup : IDisposable
		{
			private readonly IDisposable _a;

			private readonly IDisposable _b;

			internal SubscriptionGroup(IDisposable a, IDisposable b)
			{
				_a = a;
				_b = b;
			}

			public void Dispose()
			{
				_a.Dispose();
				_b.Dispose();
			}
		}

		private static readonly Lock Gate = new Lock();

		private static IDisposable? _subscriptions;

		private static bool _processFrameHooked;

		/// <summary>
		///     <para xml:lang="en">
		///         Installs the lifecycle subscriptions and process-frame watcher once per process. If installation fails,
		///         acquired subscriptions are disposed before the failure is rethrown, so a later call may retry.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在每个进程中安装一次生命周期订阅和逐帧监视器。安装失败时会先释放已获取的订阅，再重新抛出失败，
		///         因此后续调用可以重试。
		///     </para>
		/// </summary>
		public static void EnsureHooksInstalled()
		{
			if (_subscriptions != null)
			{
				return;
			}
			using (Gate.EnterScope())
			{
				if (_subscriptions != null)
				{
					return;
				}
				IDisposable disposable = null;
				IDisposable disposable2 = null;
				try
				{
					disposable = RitsuLibFramework.SubscribeLifecycle((Action<GameReadyEvent>)delegate
					{
						TryAttachProcessFrameWatch();
					}, true);
					disposable2 = RitsuLibFramework.SubscribeLifecycle((Action<RunEndedEvent>)delegate
					{
						OnRunEnded();
					}, true);
					TryAttachProcessFrameWatch();
					_subscriptions = new SubscriptionGroup(disposable, disposable2);
				}
				catch (Exception item)
				{
					List<Exception> cleanupExceptions = null;
					TryDispose(disposable2);
					TryDispose(disposable);
					if (cleanupExceptions == null)
					{
						throw;
					}
					cleanupExceptions.Insert(0, item);
					throw new AggregateException("Sidecar lifecycle installation and rollback both failed.", cleanupExceptions);
					void TryDispose(IDisposable? subscription)
					{
						if (subscription == null)
						{
							return;
						}
						try
						{
							subscription.Dispose();
						}
						catch (Exception item2)
						{
							if (cleanupExceptions == null)
							{
								cleanupExceptions = new List<Exception>();
							}
							cleanupExceptions.Add(item2);
						}
					}
				}
			}
		}

		private static void TryAttachProcessFrameWatch()
		{
			if (!_processFrameHooked)
			{
				MainLoop mainLoop = Engine.GetMainLoop();
				SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
				if (val != null)
				{
					val.ProcessFrame += OnSceneProcessFrame;
					_processFrameHooked = true;
				}
			}
		}

		private static void OnSceneProcessFrame()
		{
			RunManager instance = RunManager.Instance;
			INetGameService val = ((instance != null) ? instance.NetService : null);
			if (val != null)
			{
				RitsuLibSidecarSessionManager.ObserveNetService(val);
				RitsuLibSidecarConnectionExchange.TickHandshakeNegotiation();
				RitsuLibSidecarSessionManager.RefreshAllReachabilityFromProviders();
				RitsuLibSidecarConnectionExchange.TrySendClientHelloIfReachable(val);
				RitsuLibSidecarEndpointRegistry.TickBulkTransfers();
				RitsuLibSidecarOutboundScheduler.Tick(val);
			}
		}

		private static void OnRunEnded()
		{
			RitsuLibSidecarBus.CancelAllPendingWaits();
			RitsuLibSidecarSync.Clear();
			RitsuLibSidecarConnectionSession.Clear();
			RitsuLibSidecarSessionManager.ObserveNetService(null);
			RitsuLibSidecarConnectionExchange.DiscardNegotiationStateAfterSessionEnds();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Specifies whether a remote peer can receive sidecar traffic.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         指定远程对等端能否接收 sidecar 流量。
	///     </para>
	/// </summary>
	public enum RitsuLibSidecarPeerReachability
	{
		/// <summary>
		///     <para xml:lang="en">
		///         No capability verdict is available yet.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尚无可用的功能判定。
		///     </para>
		/// </summary>
		Unknown,
		/// <summary>
		///     <para xml:lang="en">
		///         The peer is confirmed to support sidecar traffic.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         已确认该对等端支持 sidecar 流量。
		///     </para>
		/// </summary>
		Supported,
		/// <summary>
		///     <para xml:lang="en">
		///         The peer is confirmed incompatible and must not receive sidecar packets.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         已确认该对等端不兼容，不得向其发送 sidecar 数据包。
		///     </para>
		/// </summary>
		Unsupported
	}
