		private static RitsuLibSidecarDeliverySemantics Resolve(RitsuLibSidecarDeliverySemantics s)
		{
			if (s != RitsuLibSidecarDeliverySemantics.Unspecified)
			{
				return s;
			}
			return RitsuLibSidecarDeliverySemantics.StableSync;
		}

		private static byte[] CreateEnvelopeForHost(INetGameService? netService, ulong opcode, ReadOnlySpan<byte> payload, RitsuLibSidecarDeliverySemantics deliverySemantics, RitsuLibSidecarWireFlags extraFlags, bool gzip, ReadOnlySpan<byte> additionalHeaderExtension)
		{
			int num;
			if (!gzip)
			{
				NetClientGameService val = (NetClientGameService)(object)((netService is NetClientGameService) ? netService : null);
				num = (int)((val != null) ? RitsuLibSidecarPayloadCompressionSelector.ForPeer(opcode, payload, val.HostNetId) : RitsuLibSidecarPayloadCompression.None);
			}
			else
			{
				num = 1;
			}
			RitsuLibSidecarPayloadCompression compression = (RitsuLibSidecarPayloadCompression)num;
			return RitsuLibSidecar.CreateEnvelopeWithDeliveryCompressed(opcode, payload, deliverySemantics, compression, extraFlags, additionalHeaderExtension);
		}

		private static byte[] CreateEnvelopeForPeer(ulong peerNetId, ulong opcode, ReadOnlySpan<byte> payload, RitsuLibSidecarDeliverySemantics deliverySemantics, RitsuLibSidecarWireFlags extraFlags, bool gzip, ReadOnlySpan<byte> additionalHeaderExtension)
		{
			RitsuLibSidecarPayloadCompression compression = (gzip ? RitsuLibSidecarPayloadCompression.Gzip : RitsuLibSidecarPayloadCompressionSelector.ForPeer(opcode, payload, peerNetId));
			return RitsuLibSidecar.CreateEnvelopeWithDeliveryCompressed(opcode, payload, deliverySemantics, compression, extraFlags, additionalHeaderExtension);
		}

		private static byte[] CreateEnvelopeForBroadcast(INetGameService? netService, bool readyOnly, ulong opcode, ReadOnlySpan<byte> payload, RitsuLibSidecarDeliverySemantics deliverySemantics, RitsuLibSidecarWireFlags extraFlags, bool gzip, ReadOnlySpan<byte> additionalHeaderExtension)
		{
			RitsuLibSidecarPayloadCompression compression = (gzip ? RitsuLibSidecarPayloadCompression.Gzip : RitsuLibSidecarPayloadCompressionSelector.ForPeers(opcode, payload, BroadcastTargetPeerIds(netService, readyOnly)));
			return RitsuLibSidecar.CreateEnvelopeWithDeliveryCompressed(opcode, payload, deliverySemantics, compression, extraFlags, additionalHeaderExtension);
		}

		private static IEnumerable<ulong> BroadcastTargetPeerIds(INetGameService? netService, bool readyOnly)
		{
			NetHostGameService val = (NetHostGameService)(object)((netService is NetHostGameService) ? netService : null);
			if (val == null)
			{
				yield break;
			}
			foreach (NetClientData connectedPeer in val.ConnectedPeers)
			{
				if (!readyOnly || connectedPeer.readyForBroadcasting)
				{
					yield return connectedPeer.peerId;
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Maps <see cref="T:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDeliverySemantics" /> to a transport mode and channel.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将 <see cref="T:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDeliverySemantics" /> 映射到传输模式和通道。
	///     </para>
