	public static class RitsuLibSidecarNetworkMapping
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Maps <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDeliverySemantics.BestEffort" /> to unreliable transport and the
		///         best-effort channel; all other values use reliable transport and the sidecar synchronization channel.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将 <see cref="F:STS2RitsuLib.Networking.Sidecar.RitsuLibSidecarDeliverySemantics.BestEffort" /> 映射到不可靠传输和尽力而为通道；
		///         其他值均使用可靠传输和 sidecar 同步通道。
		///     </para>
		/// </summary>
		/// <param name="semantics">
		///     <para xml:lang="en">The requested delivery semantics.</para>
		///     <para xml:lang="zh-CN">请求的投递语义。</para>
		/// </param>
		/// <param name="mode">
		///     <para xml:lang="en">The resulting transport mode.</para>
		///     <para xml:lang="zh-CN">生成的传输模式。</para>
		/// </param>
		/// <param name="channel">
		///     <para xml:lang="en">The resulting channel index.</para>
		///     <para xml:lang="zh-CN">生成的通道索引。</para>
		/// </param>
		public static void GetNetworkParameters(RitsuLibSidecarDeliverySemantics semantics, out NetTransferMode mode, out int channel)
		{
			if (semantics == RitsuLibSidecarDeliverySemantics.BestEffort)
			{
				mode = (NetTransferMode)1;
				channel = 49;
			}
			else
			{
				mode = (NetTransferMode)2;
				channel = 48;
			}
		}
	}
