	/// <summary>
	///     <para xml:lang="en">
	///         Triggers a one-shot coordinated sidecar diagnostic dump when the host detects a checksum mismatch.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         当主机检测到校验和不匹配时，触发一次 sidecar 协同诊断转储。
	///     </para>
	/// </summary>
	internal sealed class RitsuLibSidecarChecksumDivergenceRelayPatch : IPatchMethod
	{
		private readonly record struct ChecksumSnapshot(uint Id, uint Checksum);

		private static readonly FieldInfo? NetChecksumDataChecksumField = typeof(NetChecksumData).GetField("checksum");

		private static readonly FieldInfo? NetChecksumDataIdField = typeof(NetChecksumData).GetField("id");

		private static readonly FieldInfo? TrackedChecksumDataField = typeof(ChecksumTracker).GetNestedType("TrackedChecksum", BindingFlags.Instance | BindingFlags.NonPublic)?.GetField("data");

		public static string PatchId => "ritsulib_sidecar_checksum_divergence_relay";

		public static bool IsCritical => false;

		public static string Description => "Host-side: when vanilla checksum mismatch occurs, trigger sidecar coordinated dump.";

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ChecksumTracker), "CompareChecksums")
			};
		}

		public static void Prefix(object localChecksum, object remoteChecksum, ulong remoteId)
		{
			if (TryReadChecksum(localChecksum, out var checksum) && TryReadChecksum(remoteChecksum, out var checksum2) && checksum.Id == checksum2.Id && checksum.Checksum != checksum2.Checksum)
			{
				RitsuLibSidecarChecksumDiagnostics.TryTriggerHostCoordinatedDump(remoteId, checksum.Id);
			}
		}

		private static bool TryReadChecksum(object source, out ChecksumSnapshot checksum)
		{
			checksum = default(ChecksumSnapshot);
			if (source == null)
			{
				return false;
			}
			if (source.GetType().Name == "TrackedChecksum" && TrackedChecksumDataField != null)
			{
				object value = TrackedChecksumDataField.GetValue(source);
				if (value != null)
				{
					return TryReadNetChecksumData(value, out checksum);
				}
				return false;
			}
			if (NetChecksumDataChecksumField == null || NetChecksumDataIdField == null || !NetChecksumDataChecksumField.DeclaringType.IsInstanceOfType(source))
			{
				return false;
			}
			return TryReadNetChecksumData(source, out checksum);
		}

		private static bool TryReadNetChecksumData(object source, out ChecksumSnapshot checksum)
		{
			checksum = default(ChecksumSnapshot);
			if (NetChecksumDataChecksumField == null || NetChecksumDataIdField == null)
			{
				return false;
			}
			object value = NetChecksumDataChecksumField.GetValue(source);
			object value2 = NetChecksumDataIdField.GetValue(source);
			if (!(value is uint checksum2) || !(value2 is uint id))
			{
				return false;
			}
			checksum = new ChecksumSnapshot(id, checksum2);
			return true;
		}
	}
