	/// <summary>
	///     <para xml:lang="en">
	///         Validates required sidecar capabilities before the host starts a run. The <c>Fail</c> policy blocks the
	///         run, while the <c>Warn</c> policy logs the missing capabilities and continues.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在主机开始一局游戏前验证所需的 sidecar 能力。<c>Fail</c> 策略会阻止游戏开始，
	///         <c>Warn</c> 策略则记录缺失的能力并继续。
	///     </para>
	/// </summary>
	internal sealed class RitsuLibSidecarPreRunCapabilityGatePatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_sidecar_pre_run_capability_gate";

		public static bool IsCritical => false;

		public static string Description => "Validates required sidecar capabilities before StartRunLobby begins run";

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(StartRunLobby), "BeginRunForAllPlayers", new Type[2]
				{
					typeof(string),
					typeof(List<ModifierModel>)
				})
			};
		}

		public static bool Prefix(StartRunLobby __instance)
		{
			INetGameService netService = __instance.NetService;
			NetHostGameService val = (NetHostGameService)(object)((netService is NetHostGameService) ? netService : null);
			if (val == null)
			{
				return true;
			}
			RitsuLibSidecarRequiredCapabilities.ValidatePeers(val.ConnectedPeers.Select(delegate(NetClientData p)
			{
				//IL_0000: Unknown result type (might be due to invalid IL or missing references)
				return p.peerId;
			}), out SidecarRequiredCapabilityMiss[] misses);
			if (misses.Length == 0)
			{
				return true;
			}
			string text = string.Join("; ", misses.Select((SidecarRequiredCapabilityMiss m) => $"peer={m.PeerNetId}, missing=[{string.Join(", ", m.MissingCapabilities)}]"));
			if (RitsuLibSidecarRequiredCapabilities.Policy == RitsuLibSidecarRequiredCapabilityPolicy.Fail)
			{
				RitsuLibFramework.Logger.Warn("[Sidecar] BeginRun blocked by required capability check: " + text, 1);
				return false;
			}
			RitsuLibFramework.Logger.Warn("[Sidecar] BeginRun continue with required capability warnings: " + text, 1);
			return true;
		}
	}
