namespace STS2RitsuLib.Networking.MessageExtensions
{
	internal static class RitsuNetMessageBusTailPatches
	{
		private static class SerializePatch<TMessage> where TMessage : INetMessage
		{
			[HarmonyPriority(0)]
			internal static void Postfix(NetMessageBus __instance, TMessage message, ref int length, ref byte[] __result)
			{
				FieldRef<NetMessageBus, PacketWriter>? writerRef = WriterRef;
				PacketWriter val = ((writerRef != null) ? writerRef.Invoke(__instance) : null) ?? throw new InvalidOperationException("NetMessageBus has no active packet writer.");
				RitsuNetMessageTailExtensions.Write(val, message);
				checked
				{
					length = (int)unchecked(checked(unchecked((long)val.BitPosition) + 8L - 1) / 8);
					__result = val.Buffer;
				}
			}
		}

		private sealed record TailOwnerRegistration(Type MessageType, string PatchId, string Description, bool IsCritical, Action? BeforeRead, Action<PacketReader> ReadTail);

		private const int ByteBits = 8;

		private static readonly FieldRef<NetMessageBus, PacketReader>? ReaderRef = TryCreateFieldRef<PacketReader>("_reader");

		private static readonly FieldRef<NetMessageBus, PacketWriter>? WriterRef = TryCreateFieldRef<PacketWriter>("_writer");

		private static readonly Lock RegistrationLock = new Lock();

		private static readonly Dictionary<Type, TailOwnerRegistration> Registrations = new Dictionary<Type, TailOwnerRegistration>();

		private static Dictionary<Type, TailOwnerRegistration> _readRegistrations = new Dictionary<Type, TailOwnerRegistration>();

		internal static void Register<TMessage>(string patchId, string description, Action? beforeRead = null, bool isCritical = false) where TMessage : INetMessage
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(patchId, "patchId");
			ArgumentException.ThrowIfNullOrWhiteSpace(description, "description");
			using (RegistrationLock.EnterScope())
			{
				if (Registrations.ContainsKey(typeof(TMessage)))
				{
					throw new InvalidOperationException("A RitsuLib message-tail owner is already registered for " + typeof(TMessage).FullName + ".");
				}
				Registrations.Add(typeof(TMessage), new TailOwnerRegistration(typeof(TMessage), patchId, description, isCritical, beforeRead, delegate(PacketReader reader)
				{
					RitsuNetMessageTailExtensions.Read<TMessage>(reader);
				}));
				Volatile.Write(ref _readRegistrations, new Dictionary<Type, TailOwnerRegistration>(Registrations));
			}
		}

		internal static bool ApplySerializePatches(ModPatcher patcher)
		{
			ArgumentNullException.ThrowIfNull(patcher, "patcher");
			if (WriterRef == null)
			{
				RitsuLibFramework.Logger.Warn("[NetMessageTailExtensions] NetMessageBus._writer is unavailable; message tails cannot be serialized.", 1);
				return true;
			}
			MethodInfo serializeDefinition = AccessTools.DeclaredMethod(typeof(NetMessageBus), "SerializeMessage", (Type[])null, (Type[])null);
			if ((object)serializeDefinition == null || !serializeDefinition.IsGenericMethodDefinition)
			{
				RitsuLibFramework.Logger.Warn("[NetMessageTailExtensions] NetMessageBus serialization surface is unavailable; message tails cannot be serialized.", 1);
				return true;
			}
			IEnumerable<DynamicPatchInfo> dynamicPatches = Volatile.Read(in _readRegistrations).Values.Select(CreatePatch);
			return patcher.ApplyDynamicPatches(dynamicPatches, rollbackOnCriticalFailure: true);
			DynamicPatchInfo CreatePatch(TailOwnerRegistration registration)
			{
				//IL_0064: Unknown result type (might be due to invalid IL or missing references)
				//IL_007c: Expected O, but got Unknown
				Type type = typeof(SerializePatch<>).MakeGenericType(registration.MessageType);
				MethodInfo methodInfo = AccessTools.DeclaredMethod(type, "Postfix", (Type[])null, (Type[])null) ?? throw new MissingMethodException(type.FullName, "Postfix");
				return new DynamicPatchInfo(registration.PatchId, serializeDefinition.MakeGenericMethod(registration.MessageType), null, new HarmonyMethod(methodInfo), null, null, registration.IsCritical, registration.Description);
			}
		}

		internal static void ValidateReaderAccess()
		{
			if (ReaderRef == null)
			{
				throw new MissingFieldException(typeof(NetMessageBus).FullName, "_reader");
			}
		}

		internal static void Read(NetMessageBus messageBus, INetMessage message)
		{
			if (Volatile.Read(in _readRegistrations).TryGetValue(((object)message).GetType(), out TailOwnerRegistration value))
			{
				value.BeforeRead?.Invoke();
				FieldRef<NetMessageBus, PacketReader>? readerRef = ReaderRef;
				PacketReader obj = ((readerRef != null) ? readerRef.Invoke(messageBus) : null) ?? throw new InvalidOperationException("NetMessageBus has no active packet reader.");
				value.ReadTail(obj);
			}
		}

		private static FieldRef<NetMessageBus, TField>? TryCreateFieldRef<TField>(string fieldName)
		{
			try
			{
				return AccessTools.FieldRefAccess<NetMessageBus, TField>(fieldName);
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				return null;
			}
		}
	}
	internal sealed class RitsuNetMessageBusTailDeserializePatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_message_tail_bus_deserialize";

		public static bool IsCritical => false;

		public static string Description => "Read RitsuLib-owned message tails at the non-inlined message-bus boundary";

		public static ModPatchTarget[] GetTargets()
		{
			RitsuNetMessageBusTailPatches.ValidateReaderAccess();
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NetMessageBus), "TryDeserializeMessage", new Type[3]
				{
					typeof(byte[]),
					typeof(INetMessage).MakeByRefType(),
					typeof(ulong?).MakeByRefType()
				})
			};
		}

		[HarmonyPriority(800)]
		private static void Postfix(NetMessageBus __instance, bool __result, INetMessage? message)
		{
			if (__result && message != null)
			{
				RitsuNetMessageBusTailPatches.Read(__instance, message);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Registers and dispatches bounded, versioned extension payloads appended to vanilla network messages.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         注册并分发追加到原版网络消息末尾的有界版本化扩展载荷。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Registrations are process-wide and case-sensitive per message type. Each extension ID may be registered
	///         only once, with at most 64 registrations per message type. Registrations remain active for the process
	///         lifetime. The owner of a message's serialization patches must call <see cref="M:STS2RitsuLib.Networking.MessageExtensions.RitsuNetMessageTailExtensions.Write``1(MegaCrit.Sts2.Core.Multiplayer.Serialization.PacketWriter,``0)" /> and
	///         <see cref="M:STS2RitsuLib.Networking.MessageExtensions.RitsuNetMessageTailExtensions.Read``1(MegaCrit.Sts2.Core.Multiplayer.Serialization.PacketReader)" /> exactly once after the vanilla body; other mods extending the same message
	///         should only register their entries. Patch a stable outer serialization boundary: small message
	///         <c>Serialize</c> and <c>Deserialize</c> methods may be inlined before Harmony can intercept them.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         注册在进程内按消息类型共享，扩展 ID 区分大小写且只能注册一次，每种消息类型最多注册 64 个扩展，
	///         并在当前进程的生命周期内持续有效。消息序列化补丁的所有者必须在原版消息体之后各调用一次
	///         <see cref="M:STS2RitsuLib.Networking.MessageExtensions.RitsuNetMessageTailExtensions.Write``1(MegaCrit.Sts2.Core.Multiplayer.Serialization.PacketWriter,``0)" /> 与 <see cref="M:STS2RitsuLib.Networking.MessageExtensions.RitsuNetMessageTailExtensions.Read``1(MegaCrit.Sts2.Core.Multiplayer.Serialization.PacketReader)" />；扩展同一消息的其他模组只应注册
	///         各自条目。补丁应放在稳定的外层序列化边界；较短的消息 <c>Serialize</c> 与
	///         <c>Deserialize</c> 方法可能在 Harmony 拦截前被内联。
	///     </para>
	/// </remarks>
	public static class RitsuNetMessageTailExtensions
	{
		private sealed record ExtensionRegistration(int Version, Func<object, byte[]?> WritePayload, Action<int, ReadOnlyMemory<byte>> ReadPayload);

		private sealed record TailEntry(string ExtensionId, int Version, byte[] Payload);

		private const string Magic = "ritsulib.net.tail";

		private const int ContainerVersion = 2;

		private const int LegacyStringContainerVersion = 1;

		private const int ByteBits = 8;

		private const int IntBits = 32;

		private const int MaxTailEntryCount = 64;

		private const int MaxTailIdentifierBytes = 256;

		private const int MaxTailPayloadBytes = 4194304;

		private const int MaxTailEncodedBytes = 8388608;

		private static readonly Encoding StrictUtf8 = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false, throwOnInvalidBytes: true);

		private static readonly ConcurrentDictionary<Type, SortedDictionary<string, ExtensionRegistration>> Registrations = new ConcurrentDictionary<Type, SortedDictionary<string, ExtensionRegistration>>();

		internal static void Register<TMessage>(string extensionId, int version, Func<TMessage, string?> writePayload, Action<int, string> readPayload)
		{
			ValidateExtensionId(extensionId);
			ArgumentNullException.ThrowIfNull(writePayload, "writePayload");
			ArgumentNullException.ThrowIfNull(readPayload, "readPayload");
			if ((version < 0 || version > 255) ? true : false)
			{
				throw new ArgumentOutOfRangeException("version", version, "Version must fit in 8 bits.");
			}
			AddRegistration<TMessage>(extensionId, new ExtensionRegistration(version, delegate(object message)
			{
				string text = writePayload((TMessage)message);
				if (string.IsNullOrWhiteSpace(text))
				{
					return (byte[]?)null;
				}
				EnsureStringLength(text, 4194304, "Payload", "payload");
				return StrictUtf8.GetBytes(text);
			}, delegate(int payloadVersion, ReadOnlyMemory<byte> payload)
			{
				readPayload(payloadVersion, DecodePayloadString(payload.Span));
			}));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a bounded binary extension for <typeparamref name="TMessage" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <typeparamref name="TMessage" /> 注册有界二进制扩展。
		///     </para>
		/// </summary>
		/// <typeparam name="TMessage">
		///     <para xml:lang="en">The vanilla network message type being extended.</para>
		///     <para xml:lang="zh-CN">要扩展的原版网络消息类型。</para>
		/// </typeparam>
		/// <param name="extensionId">
		///     <para xml:lang="en">
		///         A case-sensitive, UTF-8 ID owned by the registering mod and unique for this message type. Whitespace
		///         and control characters are not allowed; the encoded ID is limited to 256 bytes.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         归属于注册 Mod、使用 UTF-8 编码且在此消息类型中唯一并区分大小写的 ID；不得包含空白或控制
		///         字符，编码后不得超过 256 字节。
		///     </para>
		/// </param>
		/// <param name="version">
		///     <para xml:lang="en">The payload version in the range 0 through 255.</para>
		///     <para xml:lang="zh-CN">0 到 255 范围内的载荷版本。</para>
		/// </param>
		/// <param name="writePayload">
		///     <para xml:lang="en">
		///         Creates the outgoing payload; null or an empty array omits the entry. Payloads over 4 MiB are
		///         logged and omitted.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建发出载荷；返回 null 或空数组时省略此条目。超过 4 MiB 的载荷会被记录并省略。
		///     </para>
		/// </param>
		/// <param name="readPayload">
		///     <para xml:lang="en">
		///         Consumes the received payload version and read-only bytes synchronously during deserialization.
		///     </para>
		///     <para xml:lang="zh-CN">在反序列化期间同步消费接收到的载荷版本与只读字节。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">The extension ID is empty, malformed, or contains a disallowed character.</para>
		///     <para xml:lang="zh-CN">扩展 ID 为空、格式无效或包含不允许的字符。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">The extension ID or a payload callback is null.</para>
		///     <para xml:lang="zh-CN">扩展 ID 或载荷回调为 null。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentOutOfRangeException">
		///     <para xml:lang="en">The extension ID exceeds 256 encoded bytes, or the version does not fit in one byte.</para>
		///     <para xml:lang="zh-CN">扩展 ID 编码后超过 256 字节，或版本无法用一个字节表示。</para>
		/// </exception>
		/// <exception cref="T:System.InvalidOperationException">
		///     <para xml:lang="en">
		///         The same ID is already registered for this message type, or its registration limit was reached.
		///     </para>
		///     <para xml:lang="zh-CN">同一 ID 已为此消息类型注册，或此消息类型已达到注册数量上限。</para>
		/// </exception>
		public static void RegisterBytes<TMessage>(string extensionId, int version, Func<TMessage, byte[]?> writePayload, Action<int, ReadOnlyMemory<byte>> readPayload)
		{
			ValidateExtensionId(extensionId);
			ArgumentNullException.ThrowIfNull(writePayload, "writePayload");
			ArgumentNullException.ThrowIfNull(readPayload, "readPayload");
			if ((version < 0 || version > 255) ? true : false)
			{
				throw new ArgumentOutOfRangeException("version", version, "Version must fit in 8 bits.");
			}
			AddRegistration<TMessage>(extensionId, new ExtensionRegistration(version, (object message) => writePayload((TMessage)message), readPayload));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends all registered extensions for <typeparamref name="TMessage" /> after its vanilla body.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <typeparamref name="TMessage" /> 的原版消息体后追加所有已注册扩展。
		///     </para>
		/// </summary>
		/// <typeparam name="TMessage">
		///     <para xml:lang="en">The message type whose registered extensions are written.</para>
		///     <para xml:lang="zh-CN">要写入已注册扩展的消息类型。</para>
		/// </typeparam>
		/// <param name="writer">
		///     <para xml:lang="en">The writer positioned immediately after the vanilla message body.</para>
		///     <para xml:lang="zh-CN">位于原版消息体末尾之后的写入器。</para>
		/// </param>
		/// <param name="message">
		///     <para xml:lang="en">The message supplied to registered payload writers.</para>
		///     <para xml:lang="zh-CN">提供给已注册载荷写入回调的消息。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">The writer or message is null.</para>
		///     <para xml:lang="zh-CN">写入器或消息为 null。</para>
		/// </exception>
		/// <remarks>
		///     <para xml:lang="en">
		///         Call this exactly once for each serialized message. Payload writers run synchronously in ordinal ID
		///         order. Recoverable writer failures and payloads over 4 MiB are logged and omitted. If the complete
		///         tail exceeds 8 MiB, it is logged and entirely omitted. Non-recoverable exceptions propagate.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         每次序列化消息时只能调用一次。载荷写入回调按 ID 的序号顺序同步执行。可恢复的写入回调失败及
		///         超过 4 MiB 的载荷会被记录并省略；完整消息尾超过 8 MiB 时会被记录并整体省略。不可恢复异常会
		///         继续传播。
		///     </para>
		/// </remarks>
		public static void Write<TMessage>(PacketWriter writer, TMessage message)
		{
			ArgumentNullException.ThrowIfNull(writer, "writer");
			ArgumentNullException.ThrowIfNull(message, "message");
			if (!TryGetRegistrations<TMessage>(out IReadOnlyList<KeyValuePair<string, ExtensionRegistration>> registrations))
			{
				writer.WriteBool(false);
				return;
			}
			List<TailEntry> list = new List<TailEntry>();
			long num = 1L;
			num += (4 + StrictUtf8.GetByteCount("ritsulib.net.tail")) * 8;
			num += 40;
			foreach (var (text2, extensionRegistration2) in registrations)
			{
				byte[] array;
				try
				{
					array = extensionRegistration2.WritePayload(message);
				}
				catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
				{
					RitsuLibFramework.Logger.Warn($"[NetMessageTailExtensions] Writer '{text2}' failed for {typeof(TMessage).Name}: {ex.Message}", 1);
					continue;
				}
				if (array == null || array.Length <= 0)
				{
					continue;
				}
				if (array.Length > 4194304)
				{
					RitsuLibFramework.Logger.Warn($"[NetMessageTailExtensions] Writer '{text2}' payload is {array.Length} bytes; maximum is {4194304} bytes.", 1);
					continue;
				}
				if (list.Count >= 64)
				{
					RitsuLibFramework.Logger.Warn($"[NetMessageTailExtensions] Trailer for {typeof(TMessage).Name} exceeds {64} entries.", 1);
					writer.WriteBool(false);
					return;
				}
				long num2 = (long)(4 + StrictUtf8.GetByteCount(text2)) * 8L;
				num2 += 8;
				num2 += (long)(4 + array.Length) * 8L;
				if (num + num2 > 67108864)
				{
					RitsuLibFramework.Logger.Warn($"[NetMessageTailExtensions] Trailer for {typeof(TMessage).Name} exceeds the {8388608}-byte encoded budget.", 1);
					writer.WriteBool(false);
					return;
				}
				list.Add(new TailEntry(text2, extensionRegistration2.Version, array));
				num += num2;
			}
			if (list.Count == 0)
			{
				writer.WriteBool(false);
				return;
			}
			if (writer.BitPosition + num > int.MaxValue)
			{
				RitsuLibFramework.Logger.Warn("[NetMessageTailExtensions] Trailer for " + typeof(TMessage).Name + " exceeds the remaining PacketWriter capacity.", 1);
				writer.WriteBool(false);
				return;
			}
			writer.WriteBool(true);
			writer.WriteString("ritsulib.net.tail");
			writer.WriteInt(2, 8);
			writer.WriteInt(list.Count, 32);
			foreach (TailEntry item in list)
			{
				writer.WriteString(item.ExtensionId);
				writer.WriteInt(item.Version, 8);
				writer.WriteInt(item.Payload.Length, 32);
				writer.WriteBytes(item.Payload, item.Payload.Length);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Reads and dispatches all registered extensions following the vanilla
		///         <typeparamref name="TMessage" /> body.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         读取并分发原版 <typeparamref name="TMessage" /> 消息体之后的所有已注册扩展。
		///     </para>
		/// </summary>
		/// <typeparam name="TMessage">
		///     <para xml:lang="en">The message type whose registered extensions are read.</para>
		///     <para xml:lang="zh-CN">要读取已注册扩展的消息类型。</para>
		/// </typeparam>
		/// <param name="reader">
		///     <para xml:lang="en">The reader positioned immediately after the vanilla message body.</para>
		///     <para xml:lang="zh-CN">位于原版消息体末尾之后的读取器。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">The reader is null.</para>
		///     <para xml:lang="zh-CN">读取器为 null。</para>
		/// </exception>
		/// <remarks>
		///     <para xml:lang="en">
		///         Call this exactly once for each deserialized message. Unknown entries are skipped. Malformed data
		///         and recoverable reader failures are logged without escaping; non-recoverable exceptions propagate.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         每次反序列化消息时只能调用一次。未知条目会被跳过；格式错误的数据和可恢复的读取回调失败会被
		///         记录而不向外抛出，不可恢复异常则继续传播。
		///     </para>
		/// </remarks>
		public static void Read<TMessage>(PacketReader reader)
		{
			ArgumentNullException.ThrowIfNull(reader, "reader");
			if (!HasRemainingBits(reader, 1L))
			{
				return;
			}
			Dictionary<string, ExtensionRegistration> dictionary = (TryGetRegistrations<TMessage>(out IReadOnlyList<KeyValuePair<string, ExtensionRegistration>> registrations) ? registrations.ToDictionary<KeyValuePair<string, ExtensionRegistration>, string, ExtensionRegistration>((KeyValuePair<string, ExtensionRegistration> pair) => pair.Key, (KeyValuePair<string, ExtensionRegistration> pair) => pair.Value, StringComparer.Ordinal) : new Dictionary<string, ExtensionRegistration>(StringComparer.Ordinal));
			try
			{
				if (!HasRemainingBits(reader, 1L) || !reader.ReadBool())
				{
					return;
				}
				string text = ReadBoundedString(reader, 256, "Tail magic");
				if (!string.Equals(text, "ritsulib.net.tail", StringComparison.Ordinal))
				{
					RitsuLibFramework.Logger.Warn($"[NetMessageTailExtensions] Unknown trailer magic '{text}' for {typeof(TMessage).Name}.", 1);
					return;
				}
				if (!HasRemainingBits(reader, 8L))
				{
					throw new InvalidDataException("Tail container version is missing.");
				}
				int num = reader.ReadInt(8);
				if (num != 1 && num != 2)
				{
					RitsuLibFramework.Logger.Warn($"[NetMessageTailExtensions] Unsupported trailer version {num} for {typeof(TMessage).Name}.", 1);
					return;
				}
				if (!HasRemainingBits(reader, 32L))
				{
					throw new InvalidDataException("Tail entry count is missing.");
				}
				int num2 = reader.ReadInt(32);
				ValidateEntryCount(reader, num2);
				int remainingBytes = 8388608;
				ConsumeEncodedBudget(ref remainingBytes, 4 + StrictUtf8.GetByteCount(text));
				ConsumeEncodedBudget(ref remainingBytes, 5);
				for (int num3 = 0; num3 < num2; num3++)
				{
					string text2 = ReadBoundedString(reader, 256, "Tail extension ID", ref remainingBytes);
					if (!HasRemainingBits(reader, 8L))
					{
						throw new InvalidDataException("Tail entry version is missing.");
					}
					int arg = reader.ReadInt(8);
					ConsumeEncodedBudget(ref remainingBytes, 1);
					byte[] array = ((num == 1) ? StrictUtf8.GetBytes(ReadBoundedString(reader, 4194304, "Tail string payload", ref remainingBytes)) : ReadPayloadBytes(reader, ref remainingBytes));
					if (dictionary.TryGetValue(text2, out var value))
					{
						try
						{
							value.ReadPayload(arg, array);
						}
						catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
						{
							RitsuLibFramework.Logger.Warn($"[NetMessageTailExtensions] Reader '{text2}' failed for {typeof(TMessage).Name}: {ex.Message}", 1);
						}
					}
				}
			}
			catch (Exception ex2) when (RitsuLibExceptionPolicy.IsRecoverable(ex2))
			{
				RitsuLibFramework.Logger.Warn("[NetMessageTailExtensions] Failed to read trailer for " + typeof(TMessage).Name + ": " + ex2.Message, 1);
			}
		}

		private static byte[] ReadPayloadBytes(PacketReader reader)
		{
			int remainingEncodedBytes = 4194308;
			return ReadPayloadBytes(reader, ref remainingEncodedBytes);
		}

		private static byte[] ReadPayloadBytes(PacketReader reader, ref int remainingEncodedBytes)
		{
			if (!HasRemainingBits(reader, 32L))
			{
				throw new InvalidDataException("Tail payload length is missing.");
			}
			int num = reader.ReadInt(32);
			if ((num < 0 || num > 4194304) ? true : false)
			{
				throw new InvalidDataException($"Tail payload length {num} is outside the allowed range 0..{4194304}.");
			}
			ConsumeEncodedBudget(ref remainingEncodedBytes, 4 + num);
			if (!HasRemainingBits(reader, (long)num * 8L))
			{
				throw new InvalidDataException("Tail payload exceeds the remaining packet bytes.");
			}
			byte[] array = new byte[num];
			reader.ReadBytes(array, num);
			return array;
		}

		internal static void WriteLegacySingle(PacketWriter writer, string extensionId, int version, string? payload)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(extensionId, "extensionId");
			if ((version < 0 || version > 255) ? true : false)
			{
				throw new ArgumentOutOfRangeException("version", version, "Version must fit in 8 bits.");
			}
			if (string.IsNullOrWhiteSpace(payload) || !TryEnsureStringLength(payload, 4194304, "Payload"))
			{
				writer.WriteBool(false);
				return;
			}
			writer.WriteBool(true);
			writer.WriteInt(version, 8);
			writer.WriteString(payload);
		}

		internal static void WriteLegacySingleBytes(PacketWriter writer, string extensionId, int version, byte[]? payload)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(extensionId, "extensionId");
			if ((version < 0 || version > 255) ? true : false)
			{
				throw new ArgumentOutOfRangeException("version", version, "Version must fit in 8 bits.");
			}
			if (payload == null || payload.Length <= 0)
			{
				writer.WriteBool(false);
			}
			else if (payload.Length > 4194304)
			{
				RitsuLibFramework.Logger.Warn($"[NetMessageTailExtensions] Legacy payload is {payload.Length} bytes; maximum is {4194304} bytes.", 1);
