			{
				orderLists = BuildContentModOrderLists(host.ContentMods, local.ContentMods);
				return true;
			}
			if (host.GameplayMods.Count == local.GameplayMods.Count)
			{
				orderLists = BuildModOrderLists(host.GameplayMods, local.GameplayMods);
				return true;
			}
			orderLists = null;
			return false;
		}

