		private void Close()
		{
			NModalContainer instance = NModalContainer.Instance;
			if (instance != null)
			{
				instance.Clear();
			}
		}

		private void OpenSuggestedSolution(JoinFailureSuggestedSolution solution)
		{
			if (solution.Action == JoinFailureSuggestedSolutionAction.SubscribeWorkshopItem)
			{
				ulong? workshopItemId = solution.WorkshopItemId;
				if (workshopItemId.HasValue)
				{
					ulong valueOrDefault = workshopItemId.GetValueOrDefault();
					SteamWorkshopUpdateCoordinator.SubscribeItemFromUi(valueOrDefault, solution.Title);
				}
			}
			else if (solution.ModId != null)
			{
				ModSettingsOpenResult modSettingsOpenResult = ModSettingsNavigator.RequestOpenByIds(solution.ModId, solution.PageId, solution.SectionId, solution.EntryId);
				if (!modSettingsOpenResult.Success)
				{
					RitsuLibFramework.Logger.Warn("[JoinDiagnostics] Failed to open suggested solution '" + solution.Title + "': " + modSettingsOpenResult.Message, 1);
				}
				else
				{
					Close();
				}
			}
		}

		private void CopyReportToClipboard()
		{
			DisplayServer.ClipboardSet(BuildExportReport());
			ModSettingsClipboardAccess.InvalidateCache();
			RitsuToastService.ShowInfo(T("toast.reportCopied.body", "Join failure report copied to clipboard."), T("toast.reportCopied.title", "Join diagnostics"));
		}

		private void OpenLogFolder()
		{
			GameLogFolderOpener.OpenFromUi(T("toast.reportCopied.title", "Join diagnostics"), "[JoinDiagnostics]");
		}

		private string BuildExportReport()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine(_report.Title);
			stringBuilder.AppendLine(new string('=', _report.Title.Length));
			stringBuilder.AppendLine();
			stringBuilder.AppendLine(T("section.summary", "Summary"));
			stringBuilder.AppendLine(_report.Summary);
			stringBuilder.AppendLine(T("summary.originNote", "If you are seeing this window, the game itself has reported a join failure. This window only provides additional analysis of that state."));
			stringBuilder.AppendLine();
			AppendRuntimeFrameworkVersions(stringBuilder);
			stringBuilder.AppendLine();
			stringBuilder.AppendLine(F("footer.networkReason", "Network reason: {0}", _report.NetworkReason));
			if (!string.IsNullOrWhiteSpace(_report.NetworkInfo))
			{
				stringBuilder.AppendLine(F("footer.networkInfo", "Info: {0}", _report.NetworkInfo));
			}
			stringBuilder.AppendLine();
			AppendPeerSnapshot(stringBuilder, T("column.host", "Host"), _report.Host);
			AppendPeerSnapshot(stringBuilder, T("column.local", "Local"), _report.Local);
			AppendPeerGameplayMods(stringBuilder, T("column.host", "Host"), _report.Host);
			AppendPeerGameplayMods(stringBuilder, T("column.local", "Local"), _report.Local);
			AppendPeerContentMods(stringBuilder, T("column.host", "Host"), _report.Host);
			AppendPeerContentMods(stringBuilder, T("column.local", "Local"), _report.Local);
			foreach (JoinFailureIssue issue in _report.Issues)
			{
				stringBuilder.AppendLine();
				stringBuilder.AppendLine(issue.Title);
				stringBuilder.AppendLine(new string('-', issue.Title.Length));
				stringBuilder.AppendLine(issue.Description);
				foreach (JoinFailureDetailRow row in issue.Rows)
				{
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(6, 5, stringBuilder2);
					handler.AppendFormatted(row.Label);
					handler.AppendLiteral(": ");
					handler.AppendFormatted(T("column.host", "Host"));
					handler.AppendLiteral("=");
					handler.AppendFormatted(row.HostValue);
					handler.AppendLiteral("; ");
					handler.AppendFormatted(T("column.local", "Local"));
					handler.AppendLiteral("=");
					handler.AppendFormatted(row.LocalValue);
