		private static void AppendPeerSnapshot(StringBuilder builder, string title, JoinPeerSnapshot? snapshot)
		{
			builder.AppendLine(title);
			if (snapshot == null)
			{
				builder.AppendLine("  <unknown>");
				return;
			}
			builder.AppendLine("  " + F("snapshot.version", "Version: {0}", snapshot.GameVersion));
			builder.AppendLine("  " + F("snapshot.modelDb", "ModelDb: {0}", snapshot.ModelDbHash));
			builder.AppendLine("  " + F(snapshot.SavedPropertyNetIdUsesDeterministicSort.HasValue ? "snapshot.sortModes" : "snapshot.modelDbMode", snapshot.SavedPropertyNetIdUsesDeterministicSort.HasValue ? "Sort modes: {0}" : "ModelDb mode: {0}", FormatSnapshotSortModes(snapshot.ModelDbHashUsesDeterministicCache, snapshot.SavedPropertyNetIdUsesDeterministicSort)));
