		private static string FormatModLine(JoinDiagnosticsModEntry mod)
		{
			string text = (mod.WorkshopItemId.HasValue ? (" workshop=" + mod.WorkshopItemId.Value) : "");
			return FormatModName(mod) + " version=" + FormatVersion(mod.Version) + text;
		}

		private static string FormatModName(JoinDiagnosticsModEntry mod)
		{
			if (!string.IsNullOrWhiteSpace(mod.Name) && !string.Equals(mod.Name, mod.Id, StringComparison.Ordinal))
			{
				return mod.Name + " (" + mod.Id + ")";
			}
			return mod.Id;
		}

		private static string FormatGameplayModInventoryLine(JoinDiagnosticsModEntry mod)
		{
			string value = ((string.IsNullOrWhiteSpace(mod.Name) || string.Equals(mod.Name, mod.Id, StringComparison.Ordinal)) ? mod.Id : (mod.Name + " (" + mod.Id + ")"));
