			string value3 = (mod.WorkshopItemId.HasValue ? (" workshop=" + mod.WorkshopItemId.Value) : "");
			return $"#{mod.Index + 1:00} {value} version={FormatVersion(mod.Version)}{value2}{value3}";
		}

		private static string FormatContentModInventoryLine(ContentModInventoryEntry mod)
		{
			string value = (mod.IsDependency ? " dep" : "");
			string value2 = (string.IsNullOrWhiteSpace(mod.Source) ? "" : (" source=" + mod.Source));
			string value3 = (mod.WorkshopItemId.HasValue ? (" workshop=" + mod.WorkshopItemId.Value) : "");
			return $"#{mod.Index + 1:00}{value} {FormatContentModName(mod)} version={FormatVersion(mod.Version)}{value2}{value3}";
		}

		private static string FormatContentModLine(ContentModInventoryEntry mod)
		{
			string text = (string.IsNullOrWhiteSpace(mod.Source) ? "" : (" source=" + mod.Source));
			string text2 = (mod.WorkshopItemId.HasValue ? (" workshop=" + mod.WorkshopItemId.Value) : "");
