				issues.Add(new JoinFailureIssue(JoinFailureIssueKind.GameVersion, T("issue.version.title", "Game version mismatch"), T("issue.version.body", "The host and local game versions are different."), new <>z__ReadOnlySingleElementList<JoinFailureDetailRow>(new JoinFailureDetailRow(T("row.gameVersion", "Game version"), host.GameVersion, local.GameVersion))));
