		}

		private static void AddModIssues(ICollection<JoinFailureIssue> issues, JoinPeerSnapshot host, JoinPeerSnapshot local, bool suppressOrderIssueForModelDbMismatch, bool deterministicModelDbHash)
		{
			if (host.HasProcessedContentMods && local.HasProcessedContentMods && (host.ContentMods.Count > 0 || local.ContentMods.Count > 0))
			{
				AddContentModIssues(issues, host.ContentMods, local.ContentMods, suppressOrderIssueForModelDbMismatch, deterministicModelDbHash);
			}
			else
			{
				AddGameplayModIssues(issues, host.GameplayMods, local.GameplayMods, suppressOrderIssueForModelDbMismatch, deterministicModelDbHash);
			}
		}

		private static void AddGameplayModIssues(ICollection<JoinFailureIssue> issues, IReadOnlyList<JoinDiagnosticsModEntry> hostMods, IReadOnlyList<JoinDiagnosticsModEntry> localMods, bool suppressOrderIssueForModelDbMismatch, bool deterministicModelDbHash)
		{
			HashSet<string> hostKeys = hostMods.Select((JoinDiagnosticsModEntry m) => m.Key).ToHashSet<string>(StringComparer.Ordinal);
			HashSet<string> localKeys = localMods.Select((JoinDiagnosticsModEntry m) => m.Key).ToHashSet<string>(StringComparer.Ordinal);
			List<JoinDiagnosticsModEntry> list = hostMods.Where((JoinDiagnosticsModEntry m) => !localKeys.Contains(m.Key)).ToList();
			List<JoinDiagnosticsModEntry> list2 = localMods.Where((JoinDiagnosticsModEntry m) => !hostKeys.Contains(m.Key)).ToList();
			List<JoinFailureDetailRow> list3 = ExtractVersionRows(list, list2);
			if (list.Count > 0 || list2.Count > 0 || list3.Count > 0)
			{
				List<JoinFailureDetailRow> list4 = new List<JoinFailureDetailRow>();
				list4.AddRange(list3);
				list4.AddRange(list.Select((JoinDiagnosticsModEntry m) => new JoinFailureDetailRow(FormatModLabel(m), FormatModValue(m), T("value.missing", "Missing"))));
				list4.AddRange(list2.Select((JoinDiagnosticsModEntry m) => new JoinFailureDetailRow(FormatModLabel(m), T("value.missing", "Missing"), FormatModValue(m))));
				issues.Add(new JoinFailureIssue(JoinFailureIssueKind.ModSet, T("issue.modSet.title", "Gameplay mod mismatch"), T("issue.modSet.body", "The host and local gameplay mod lists are not the same."), LimitRows(list4)));
			}
			else
			{
				if (hostMods.Count != localMods.Count || hostMods.Select((JoinDiagnosticsModEntry m) => m.Key).SequenceEqual<string>(localMods.Select((JoinDiagnosticsModEntry m) => m.Key), StringComparer.Ordinal) || suppressOrderIssueForModelDbMismatch)
				{
					return;
				}
				int num = -1;
				int num2 = 0;
				for (int num3 = 0; num3 < hostMods.Count; num3++)
				{
					if (!string.Equals(hostMods[num3].Key, localMods[num3].Key, StringComparison.Ordinal))
					{
						if (num < 0)
						{
							num = num3;
						}
						num2++;
					}
				}
				issues.Add(new JoinFailureIssue(JoinFailureIssueKind.ModOrder, T("issue.modOrder.title", "Gameplay mod order differs"), GetModOrderBody(deterministicModelDbHash), new global::<>z__ReadOnlyArray<JoinFailureDetailRow>(new JoinFailureDetailRow[2]
				{
					new JoinFailureDetailRow(T("row.orderMismatchCount", "Different positions"), num2.ToString(), num2.ToString()),
					new JoinFailureDetailRow(F("row.firstDifferentPosition", "First different position: {0}", num + 1), FormatModValue(hostMods[num]), FormatModValue(localMods[num]))
				})));
