		private static void AddModelDbIssue(ICollection<JoinFailureIssue> issues, JoinPeerSnapshot host, JoinPeerSnapshot local, bool deterministicModelDbHash, bool modelDbHashModeMismatch, bool onlyVisibleModelDbHashDifferent)
		{
			if (host.ModelDbHash != local.ModelDbHash)
			{
				string modelDbMismatchTitle = GetModelDbMismatchTitle(onlyVisibleModelDbHashDifferent);
				string modelDbMismatchBody = GetModelDbMismatchBody(deterministicModelDbHash, modelDbHashModeMismatch, onlyVisibleModelDbHashDifferent);
				List<JoinFailureDetailRow> list = new List<JoinFailureDetailRow>();
				list.Add(new JoinFailureDetailRow(T("row.modelDbHash", "ModelDb hash"), host.ModelDbHash.ToString(), local.ModelDbHash.ToString()));
				list.Add(new JoinFailureDetailRow(T("row.modelDbHashMode", "ModelDb hash mode"), FormatModelDbHashMode(host.ModelDbHashUsesDeterministicCache), FormatModelDbHashMode(local.ModelDbHashUsesDeterministicCache)));
				list.AddRange(BuildModelDbHashModeDetailRows(host, local));
				list.AddRange(BuildSavedPropertyNetIdSortRows(host, local));
				issues.Add(new JoinFailureIssue(JoinFailureIssueKind.ModelDb, modelDbMismatchTitle, modelDbMismatchBody, new <>z__ReadOnlyList<JoinFailureDetailRow>(list)));
			}
		}

		private static bool IsOnlyVisibleModelDbHashDifferent(IReadOnlyCollection<JoinFailureIssue> issues, JoinPeerSnapshot host, JoinPeerSnapshot local)
		{
			if (issues.Count == 0 && host.ModelDbHash != local.ModelDbHash && host.ModelDbHashUsesDeterministicCache == local.ModelDbHashUsesDeterministicCache && host.SavedPropertyNetIdUsesDeterministicSort == local.SavedPropertyNetIdUsesDeterministicSort)
			{
				return string.Equals(NormalizeVisibleModeDetail(host.ModelDbHashModeDetail), NormalizeVisibleModeDetail(local.ModelDbHashModeDetail), StringComparison.Ordinal);
			}
			return false;
		}

		private static string GetModOrderBody(bool deterministicModelDbHash)
		{
			if (!deterministicModelDbHash)
			{
				return T("issue.modOrder.body.existing", "Both sides have the same gameplay mods, but their load order is different. Deterministic final-content hashing is not active on at least one side, so load order can still affect diagnostics through the existing initialization path.");
			}
			return T("issue.modOrder.body.deterministic", "Both sides have the same gameplay mods, but their load order is different. ModelDb hash is based on deterministic final content on both sides, so order alone should not change it.");
		}

		private static string GetModelDbMismatchTitle(bool onlyVisibleModelDbHashDifferent)
		{
			if (!onlyVisibleModelDbHashDifferent)
			{
				return T("issue.modelDb.title", "ModelDb hash mismatch");
			}
			return T("issue.modelDbHashOnly.title", "Only ModelDb hash differs");
		}

		private static string GetModelDbMismatchBody(bool deterministicModelDbHash, bool modelDbHashModeMismatch, bool onlyVisibleModelDbHashDifferent)
		{
			if (onlyVisibleModelDbHashDifferent)
			{
				return T("issue.modelDbHashOnly.body", "The visible game version, mod list, load order, and hash modes match, but the ModelDb hash is different. This suggests a non-content mod may have registered a model it should not add, or another mod may have changed the ModelDb hash calculation or result.");
			}
			if (modelDbHashModeMismatch)
			{
				return T("issue.modelDb.body.modeMismatch", "The gameplay model database is different between host and local, and only one side reports stable ModelDb sorting. Enable the same ModelDb deterministic sorting setting and use a RitsuLib version that supports reporting this mode on both sides.");
			}
			if (!deterministicModelDbHash)
			{
				return T("issue.modelDb.body.existing", "The gameplay model database is different between host and local. Deterministic final-content hashing is not active on at least one side, so also compare mod load order and any library, patch, or runtime registration differences.");
			}
			return T("issue.modelDb.body.deterministic", "The gameplay model database is different between host and local even though both sides use deterministic ModelDb hashing. If mod lists match, check runtime model registration, direct ModelDb patches, or different local mod files.");
		}

