		private static List<JoinFailureDetailRow> ExtractVersionRows(List<JoinDiagnosticsModEntry> missingOnLocal, List<JoinDiagnosticsModEntry> missingOnHost)
		{
			List<JoinFailureDetailRow> list = new List<JoinFailureDetailRow>();
			for (int num = missingOnLocal.Count - 1; num >= 0; num--)
			{
				JoinDiagnosticsModEntry hostMod = missingOnLocal[num];
				int num2 = missingOnHost.FindIndex((JoinDiagnosticsModEntry m) => !string.IsNullOrEmpty(m.Id) && string.Equals(m.Id, hostMod.Id, StringComparison.Ordinal));
				if (num2 >= 0)
				{
					JoinDiagnosticsModEntry mod = missingOnHost[num2];
					list.Add(new JoinFailureDetailRow(FormatModLabel(hostMod), FormatModValue(hostMod), FormatModValue(mod)));
					missingOnLocal.RemoveAt(num);
					missingOnHost.RemoveAt(num2);
				}
			}
			return list;
		}

		private static List<JoinFailureDetailRow> ExtractContentVersionRows(List<ContentModInventoryEntry> missingOnLocal, List<ContentModInventoryEntry> missingOnHost)
		{
			List<JoinFailureDetailRow> list = new List<JoinFailureDetailRow>();
			for (int num = missingOnLocal.Count - 1; num >= 0; num--)
			{
				ContentModInventoryEntry hostMod = missingOnLocal[num];
				int num2 = missingOnHost.FindIndex((ContentModInventoryEntry m) => !string.IsNullOrEmpty(m.Id) && string.Equals(m.Id, hostMod.Id, StringComparison.Ordinal) && string.Equals(m.Id, hostMod.Id, StringComparison.Ordinal));
				if (num2 >= 0)
				{
					ContentModInventoryEntry mod = missingOnHost[num2];
					list.Add(new JoinFailureDetailRow(FormatContentModLabel(hostMod), FormatContentModValue(hostMod), FormatContentModValue(mod)));
					missingOnLocal.RemoveAt(num);
					missingOnHost.RemoveAt(num2);
				}
			}
			return list;
		}

		private static IReadOnlyList<JoinFailureDetailRow> LimitRows(IReadOnlyList<JoinFailureDetailRow> rows)
		{
			if (rows.Count <= 24)
			{
				return rows;
			}
			List<JoinFailureDetailRow> list = rows.Take(24).ToList();
			list.Add(new JoinFailureDetailRow(F("row.more", "{0} more", rows.Count - 24), T("value.omitted", "Omitted"), T("value.omitted", "Omitted")));
			return list;
		}

		private static string FormatModLabel(JoinDiagnosticsModEntry mod)
		{
			if (!string.IsNullOrWhiteSpace(mod.Name) && !string.Equals(mod.Name, mod.Id, StringComparison.Ordinal))
			{
				return mod.Name + " (" + mod.Id + ")";
			}
			if (!string.IsNullOrWhiteSpace(mod.Id))
			{
				return mod.Id;
			}
			return mod.Key;
		}

		private static string FormatModValue(JoinDiagnosticsModEntry mod)
		{
			string text = (string.IsNullOrWhiteSpace(mod.Version) ? T("value.noVersion", "No version") : mod.Version);
			string text2 = (string.IsNullOrWhiteSpace(mod.Id) ? mod.Key : mod.Id);
			string text3 = (mod.WorkshopItemId.HasValue ? ("  workshop=" + mod.WorkshopItemId.Value) : "");
			return "#" + (mod.Index + 1) + "  " + text2 + "  version=" + text + text3;
		}

		private static string FormatContentModLabel(ContentModInventoryEntry mod)
		{
			if (!string.IsNullOrWhiteSpace(mod.Name) && !string.Equals(mod.Name, mod.Id, StringComparison.Ordinal))
			{
				return mod.Name + " (" + mod.Id + ")";
			}
			if (!string.IsNullOrWhiteSpace(mod.Id))
			{
				return mod.Id;
			}
			return ContentModIdentityKey(mod);
		}

		private static string FormatContentModValue(ContentModInventoryEntry mod)
		{
			string text = (string.IsNullOrWhiteSpace(mod.Version) ? T("value.noVersion", "No version") : mod.Version);
			string text2 = (string.IsNullOrWhiteSpace(mod.Source) ? "" : ("  source=" + mod.Source));
			string text3 = (mod.WorkshopItemId.HasValue ? ("  workshop=" + mod.WorkshopItemId.Value) : "");
			return "#" + (mod.Index + 1) + "  " + mod.Id + "  version=" + text + text2 + text3;
		}

		private static IReadOnlyDictionary<string, ContentModInventoryEntry> BuildContentModIdentityMap(IEnumerable<ContentModInventoryEntry> mods)
		{
			return mods.GroupBy<ContentModInventoryEntry, string>(ContentModIdentityKey, StringComparer.Ordinal).ToDictionary<IGrouping<string, ContentModInventoryEntry>, string, ContentModInventoryEntry>((IGrouping<string, ContentModInventoryEntry> group) => group.Key, (IGrouping<string, ContentModInventoryEntry> group) => group.First(), StringComparer.Ordinal);
		}

		private static string ContentModIdentityKey(ContentModInventoryEntry mod)
		{
			return mod.Id + "\0" + mod.Version;
		}

		private static IReadOnlyList<JoinFailureSuggestedSolution> BuildSuggestedSolutions(JoinPeerSnapshot? host, JoinPeerSnapshot local, IReadOnlyList<JoinFailureIssue> issues, JoinDiagnosticsPayload? hostPayload)
		{
			List<JoinFailureSuggestedSolution> list = new List<JoinFailureSuggestedSolution>();
			AddMissingWorkshopModSolutions(list, host, local, hostPayload);
			if (!IsOrderOnlyModelDbMismatch(host, local, issues, hostPayload))
			{
				return list;
			}
			list.Add(new JoinFailureSuggestedSolution(T("solution.sortMods.title", "Sort mod load order"), T("solution.sortMods.description", "Open content mod load order sorting. This rewrites the saved relevant mod order; restart the game before joining again."), T("solution.sortMods.button", "Open mod order sort"), JoinFailureSuggestedSolutionAction.OpenSettings, "com.ritsukage.sts2-RitsuLib", "content-mod-load-order", "content_mod_load_order_actions", "content_mod_load_order_sort"));
			list.Add(new JoinFailureSuggestedSolution(T("solution.sortModelDb.title", "Sort ModelDb for this session"), T("solution.sortModelDb.description", "Open manual ModelDb deterministic sorting. This only rebuilds the current session's ModelDb network cache and does not persist after restart."), T("solution.sortModelDb.button", "Open ModelDb sort"), JoinFailureSuggestedSolutionAction.OpenSettings, "com.ritsukage.sts2-RitsuLib", "core", "core", "modeldb_deterministic_sort_now"));
			return list;
		}

		private static void AddMissingWorkshopModSolutions(ICollection<JoinFailureSuggestedSolution> result, JoinPeerSnapshot? host, JoinPeerSnapshot local, JoinDiagnosticsPayload? hostPayload)
		{
			if (hostPayload == null || host == null)
			{
				return;
			}
			HashSet<ulong> hashSet = new HashSet<ulong>();
			if (host.HasProcessedContentMods && local.HasProcessedContentMods)
			{
				IReadOnlyDictionary<string, ContentModInventoryEntry> readOnlyDictionary = BuildContentModIdentityMap(local.ContentMods);
				{
					foreach (ContentModInventoryEntry contentMod in host.ContentMods)
					{
						if (readOnlyDictionary.ContainsKey(ContentModIdentityKey(contentMod)))
						{
							continue;
						}
						ulong? workshopItemId = contentMod.WorkshopItemId;
						if (workshopItemId.HasValue)
						{
							ulong valueOrDefault = workshopItemId.GetValueOrDefault();
							if (hashSet.Add(valueOrDefault))
							{
								result.Add(BuildWorkshopSubscribeSolution(valueOrDefault, FormatContentModLabel(contentMod), FormatWorkshopSubscribeModIdentity(contentMod)));
							}
						}
					}
					return;
				}
			}
			HashSet<string> hashSet2 = local.GameplayMods.Select((JoinDiagnosticsModEntry m) => m.Key).ToHashSet<string>(StringComparer.Ordinal);
			foreach (JoinDiagnosticsModEntry gameplayMod in host.GameplayMods)
			{
				if (hashSet2.Contains(gameplayMod.Key))
				{
					continue;
				}
				ulong? workshopItemId = gameplayMod.WorkshopItemId;
				if (workshopItemId.HasValue)
				{
					ulong valueOrDefault2 = workshopItemId.GetValueOrDefault();
					if (hashSet.Add(valueOrDefault2))
					{
						result.Add(BuildWorkshopSubscribeSolution(valueOrDefault2, FormatModLabel(gameplayMod), FormatWorkshopSubscribeModIdentity(gameplayMod)));
					}
				}
			}
		}

		private static JoinFailureSuggestedSolution BuildWorkshopSubscribeSolution(ulong workshopItemId, string modLabel, string modIdentity)
		{
			return new JoinFailureSuggestedSolution(F("solution.subscribeWorkshopMod.title", "Subscribe missing Workshop mod: {0}", modLabel), F("solution.subscribeWorkshopMod.description", "The host has {0} from Steam Workshop item {1}, but local does not. Ask Steam to subscribe, then wait for the download and restart before joining again.", modIdentity, workshopItemId), T("solution.subscribeWorkshopMod.button", "Subscribe"), JoinFailureSuggestedSolutionAction.SubscribeWorkshopItem, null, null, null, null, workshopItemId);
		}

		private static string FormatWorkshopSubscribeModIdentity(JoinDiagnosticsModEntry mod)
		{
			return F("solution.subscribeWorkshopMod.modIdentity", "{0}, version={1}", FormatModLabel(mod), FormatVersionForDisplay(mod.Version));
		}

		private static string FormatWorkshopSubscribeModIdentity(ContentModInventoryEntry mod)
		{
			return F("solution.subscribeWorkshopMod.modIdentity", "{0}, version={1}", FormatContentModLabel(mod), FormatVersionForDisplay(mod.Version));
		}

		private static string FormatVersionForDisplay(string? version)
		{
			if (!string.IsNullOrWhiteSpace(version))
			{
				return version;
			}
			return T("value.noVersion", "No version");
		}

		private static bool IsOrderOnlyModelDbMismatch(JoinPeerSnapshot? host, JoinPeerSnapshot local, IReadOnlyList<JoinFailureIssue> issues, JoinDiagnosticsPayload? hostPayload)
		{
			if (hostPayload == null || host == null || host.ModelDbHash == local.ModelDbHash || host.ModelDbHashUsesDeterministicCache || local.ModelDbHashUsesDeterministicCache)
			{
				return false;
			}
			if (issues.Count == 2 && issues.Any((JoinFailureIssue issue) => issue.Kind == JoinFailureIssueKind.ModOrder))
			{
				return issues.Any((JoinFailureIssue issue) => issue.Kind == JoinFailureIssueKind.ModelDb);
			}
			return false;
		}

		private unsafe static string LocalizeReason(NetError reason)
		{
			return T("reason." + ((object)(*(NetError*)(&reason))/*cast due to constrained. prefix*/).ToString(), ((object)(*(NetError*)(&reason))/*cast due to constrained. prefix*/).ToString());
		}

		private unsafe static string LocalizeConnectionReason(ConnectionFailureReason reason)
		{
			return T("connection." + ((object)(*(ConnectionFailureReason*)(&reason))/*cast due to constrained. prefix*/).ToString(), ((object)(*(ConnectionFailureReason*)(&reason))/*cast due to constrained. prefix*/).ToString());
		}

		private static string T(string key, string fallback)
		{
			return JoinFailureDiagnosticsLocalization.Get(key, fallback);
		}

		private static string F(string key, string fallback, params object?[] args)
		{
			return JoinFailureDiagnosticsLocalization.Format(key, fallback, args);
		}
	}
}
