namespace STS2RitsuLib.Models
{
	/// <summary>
	///     <para xml:lang="en">
	///         Convenience <see cref="T:MegaCrit.Sts2.Core.Models.SingletonModel" /> base type that can subscribe itself to run or combat hooks,
	///         avoiding repeated reflection-based hook registration in each singleton model.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         可自行订阅一局游戏或战斗钩子的便捷 <see cref="T:MegaCrit.Sts2.Core.Models.SingletonModel" /> 基类型，
	///         避免在每个单例模型中重复编写基于反射的钩子注册代码。
	///     </para>
	/// </summary>
	public abstract class HookedSingletonModel : SingletonModel
	{
		/// <summary>
		///     <para xml:lang="en">Specifies the hook stream selected for a singleton model.</para>
		///     <para xml:lang="zh-CN">指定单例模型要订阅的钩子流。</para>
		/// </summary>
		public enum HookType
		{
			/// <summary>
			///     <para xml:lang="en">Does not subscribe the singleton to run or combat hooks.</para>
			///     <para xml:lang="zh-CN">不将单例订阅到一局游戏或战斗钩子。</para>
			/// </summary>
			None,
			/// <summary>
			///     <para xml:lang="en">Subscribes the singleton to combat-state hooks.</para>
			///     <para xml:lang="zh-CN">将单例订阅到战斗状态钩子。</para>
			/// </summary>
			Combat,
			/// <summary>
			///     <para xml:lang="en">Subscribes the singleton to run-state hooks.</para>
			///     <para xml:lang="zh-CN">将单例订阅到局内状态钩子。</para>
			/// </summary>
			Run
		}

		/// <inheritdoc />
		public override bool ShouldReceiveCombatHooks { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the run state most recently supplied by a hook subscription callback.</para>
		///     <para xml:lang="zh-CN">获取钩子订阅回调最近提供的局内状态。</para>
		/// </summary>
		protected IRunState? CurrentRunState { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Gets the combat state most recently supplied by a hook subscription callback.</para>
		///     <para xml:lang="zh-CN">获取钩子订阅回调最近提供的战斗状态。</para>
		/// </summary>
		protected CombatState? CurrentCombatState { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Creates the singleton and subscribes it to one hook stream.</para>
		///     <para xml:lang="zh-CN">创建单例，并将其订阅到一个钩子流。</para>
		/// </summary>
		/// <param name="hookType">
		///     <para xml:lang="en">The hook stream to subscribe to.</para>
		///     <para xml:lang="zh-CN">要订阅的钩子流。</para>
		/// </param>
		protected HookedSingletonModel(HookType hookType)
		{
			//IL_0033: Unknown result type (might be due to invalid IL or missing references)
			//IL_003d: Expected O, but got Unknown
			//IL_0050: Unknown result type (might be due to invalid IL or missing references)
			//IL_005a: Expected O, but got Unknown
			((SingletonModel)this)..ctor();
			switch (hookType)
			{
			case HookType.Combat:
				ShouldReceiveCombatHooks = true;
				ModHelper.SubscribeForCombatStateHooks(((AbstractModel)this).Id.Entry, new CombatHookSubscriptionDelegate(CombatSubModels));
				break;
			case HookType.Run:
				ModHelper.SubscribeForRunStateHooks(((AbstractModel)this).Id.Entry, new RunHookSubscriptionDelegate(RunSubModels));
				break;
			default:
				throw new ArgumentOutOfRangeException("hookType", hookType, null);
			case HookType.None:
				break;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Updates the current run state and returns this singleton as the run-scoped hook model.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         更新当前局内状态，并将此单例作为局内作用域的钩子模型返回。
		///     </para>
		/// </summary>
		/// <param name="runState">
		///     <para xml:lang="en">The current run state.</para>
		///     <para xml:lang="zh-CN">当前局内状态。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The models to subscribe for run hooks.</para>
		///     <para xml:lang="zh-CN">要订阅局内钩子的模型。</para>
		/// </returns>
		private IEnumerable<AbstractModel> RunSubModels(RunState runState)
		{
			CurrentRunState = (IRunState?)(object)runState;
			CurrentCombatState = null;
			return new <>z__ReadOnlySingleElementList<AbstractModel>((AbstractModel)(object)this);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Updates the current combat and run states and returns this singleton as the combat-scoped hook model.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         更新当前战斗与局内状态，并将此单例作为战斗作用域的钩子模型返回。
		///     </para>
		/// </summary>
		/// <param name="combatState">
		///     <para xml:lang="en">The current combat state.</para>
		///     <para xml:lang="zh-CN">当前战斗状态。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The models to subscribe for combat hooks.</para>
		///     <para xml:lang="zh-CN">要订阅战斗钩子的模型。</para>
		/// </returns>
		private IEnumerable<AbstractModel> CombatSubModels(CombatState combatState)
		{
			CurrentCombatState = combatState;
			CurrentRunState = combatState.RunState;
			return new <>z__ReadOnlySingleElementList<AbstractModel>((AbstractModel)(object)this);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Describes one completed base-game model clone operation.</para>
	///     <para xml:lang="zh-CN">描述一次已完成的游戏原版模型复制操作。</para>
	/// </summary>
	/// <param name="Prototype">
	///     <para xml:lang="en">The model instance that was cloned.</para>
	///     <para xml:lang="zh-CN">被复制的原型模型实例。</para>
	/// </param>
	/// <param name="ClonedModel">
	///     <para xml:lang="en">The cloned model instance.</para>
	///     <para xml:lang="zh-CN">复制出的模型实例。</para>
	/// </param>
	public readonly record struct ModelCloneContext(AbstractModel Prototype, AbstractModel ClonedModel);
	/// <summary>
	///     <para xml:lang="en">Provides per-mod registration for base-game model clone listeners.</para>
	///     <para xml:lang="zh-CN">提供按模组划分的游戏原版模型复制监听器注册入口。</para>
	/// </summary>
	public sealed class ModelCloneRegistry
	{
		private sealed record ListenerEntry(string ModId, string ListenerId, Func<ModelCloneContext, bool> Predicate, Action<ModelCloneContext> Listener, long RegistrationOrder);

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, ModelCloneRegistry> Registries = new Dictionary<string, ModelCloneRegistry>(StringComparer.OrdinalIgnoreCase);

		private static readonly Dictionary<(string ModId, string ListenerId), ListenerEntry> Listeners = new Dictionary<(string, string), ListenerEntry>();

		private static long _nextRegistrationOrder;

		private readonly string _modId;

		private ModelCloneRegistry(string modId)
		{
			_modId = modId;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the singleton clone registry for <paramref name="modId" />, creating it on first use.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 <paramref name="modId" /> 对应的单例复制注册表，并在首次使用时创建。
		///     </para>
		/// </summary>
		public static ModelCloneRegistry For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (SyncRoot.EnterScope())
			{
				if (Registries.TryGetValue(modId, out ModelCloneRegistry value))
				{
					return value;
				}
				ModelCloneRegistry modelCloneRegistry = new ModelCloneRegistry(modId);
				Registries[modId] = modelCloneRegistry;
				return modelCloneRegistry;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers or replaces a listener that receives every completed
		///         <see cref="M:MegaCrit.Sts2.Core.Models.AbstractModel.MutableClone" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册或替换监听器，以接收每次完成的 <see cref="M:MegaCrit.Sts2.Core.Models.AbstractModel.MutableClone" />。
		///     </para>
		/// </summary>
		/// <param name="listenerId">
		///     <para xml:lang="en">The unique listener ID within this mod's registry.</para>
		///     <para xml:lang="zh-CN">监听器在当前模组注册表内的唯一 ID。</para>
		/// </param>
		/// <param name="listener">
		///     <para xml:lang="en">The listener invoked after the clone is created and initialized.</para>
		///     <para xml:lang="zh-CN">复制体创建并初始化后调用的监听器。</para>
		/// </param>
		public void Register(string listenerId, Action<ModelCloneContext> listener)
		{
			Register(listenerId, (ModelCloneContext _) => true, listener);
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a listener with a custom predicate.</para>
		///     <para xml:lang="zh-CN">注册或替换带有自定义谓词的监听器。</para>
		/// </summary>
		/// <param name="listenerId">
		///     <para xml:lang="en">The unique listener ID within this mod's registry.</para>
		///     <para xml:lang="zh-CN">监听器在当前模组注册表内的唯一 ID。</para>
		/// </param>
		/// <param name="predicate">
		///     <para xml:lang="en">The predicate used to select clone operations for this listener.</para>
		///     <para xml:lang="zh-CN">用于筛选此监听器所接收复制操作的谓词。</para>
		/// </param>
		/// <param name="listener">
		///     <para xml:lang="en">The listener invoked after the clone is created and initialized.</para>
		///     <para xml:lang="zh-CN">复制体创建并初始化后调用的监听器。</para>
		/// </param>
		public void Register(string listenerId, Func<ModelCloneContext, bool> predicate, Action<ModelCloneContext> listener)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(listenerId, "listenerId");
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			ArgumentNullException.ThrowIfNull(listener, "listener");
			using (SyncRoot.EnterScope())
			{
				(string, string) key = (_modId, listenerId);
				long registrationOrder = (Listeners.TryGetValue(key, out ListenerEntry value) ? value.RegistrationOrder : _nextRegistrationOrder++);
				Listeners[key] = new ListenerEntry(_modId, listenerId, predicate, listener, registrationOrder);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers or replaces a typed listener for a model family, including base-game model types.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册或替换某个模型族的类型化监听器，包括游戏原版模型类型。
		///     </para>
		/// </summary>
		/// <typeparam name="TModel">
		///     <para xml:lang="en">The model base or concrete type to listen for.</para>
		///     <para xml:lang="zh-CN">要监听的模型基类或具体类型。</para>
		/// </typeparam>
		/// <param name="listenerId">
		///     <para xml:lang="en">The unique listener ID within this mod's registry.</para>
		///     <para xml:lang="zh-CN">监听器在当前模组注册表内的唯一 ID。</para>
		/// </param>
		/// <param name="listener">
		///     <para xml:lang="en">
		///         The typed listener invoked when both the prototype and clone are
		///         <typeparamref name="TModel" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         原型和复制体均为 <typeparamref name="TModel" /> 时调用的类型化监听器。
		///     </para>
		/// </param>
		public void Register<TModel>(string listenerId, Action<TModel, TModel> listener) where TModel : AbstractModel
		{
			ArgumentNullException.ThrowIfNull(listener, "listener");
			Register(listenerId, (ModelCloneContext context) => context.Prototype is TModel && context.ClonedModel is TModel, delegate(ModelCloneContext context)
			{
				listener((TModel)(object)context.Prototype, (TModel)(object)context.ClonedModel);
			});
		}

		/// <summary>
		///     <para xml:lang="en">Removes a previously registered listener from this mod's registry.</para>
		///     <para xml:lang="zh-CN">从当前模组的注册表中移除先前注册的监听器。</para>
		/// </summary>
		/// <param name="listenerId">
		///     <para xml:lang="en">The listener ID used during registration.</para>
		///     <para xml:lang="zh-CN">注册时使用的监听器 ID。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if an entry was removed; otherwise, <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若已移除条目，则为 <see langword="true" />；否则为 <see langword="false" />。
		///     </para>
		/// </returns>
		public bool Unregister(string listenerId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(listenerId, "listenerId");
			using (SyncRoot.EnterScope())
			{
				return Listeners.Remove((_modId, listenerId));
			}
		}

		internal static void NotifyCloned(AbstractModel prototype, AbstractModel clone)
		{
			ArgumentNullException.ThrowIfNull(prototype, "prototype");
			ArgumentNullException.ThrowIfNull(clone, "clone");
			ModelCloneContext modelCloneContext = new ModelCloneContext(prototype, clone);
			ListenerEntry[] array;
			using (SyncRoot.EnterScope())
			{
				array = Listeners.Values.OrderBy((ListenerEntry entry) => entry.RegistrationOrder).ToArray();
			}
			ListenerEntry[] array2 = array;
			foreach (ListenerEntry listenerEntry in array2)
			{
				try
				{
					if (listenerEntry.Predicate(modelCloneContext))
					{
						listenerEntry.Listener(modelCloneContext);
					}
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[ModelCloneRegistry] Listener '{listenerEntry.ModId}/{listenerEntry.ListenerId}' failed for {prototype.Id}: {ex.Message}", 1);
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en"><see cref="T:MegaCrit.Sts2.Core.Localization.LocString" /> table-and-key mapping for a known model family.</para>
	///     <para xml:lang="zh-CN">已知模型族的 <see cref="T:MegaCrit.Sts2.Core.Localization.LocString" /> 表与键映射。</para>
	/// </summary>
	public sealed record ModelLocStringSource(Type ModelType, string Table, Func<AbstractModel, string> Key, Func<AbstractModel, LocString> Resolve)
	{
		/// <summary>
		///     <para xml:lang="en">Determines whether this source applies to <paramref name="model" />.</para>
		///     <para xml:lang="zh-CN">确定此来源是否适用于 <paramref name="model" />。</para>
		/// </summary>
		public bool Matches(AbstractModel model)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			return ModelType.IsInstanceOfType(model);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a <see cref="T:MegaCrit.Sts2.Core.Localization.LocString" /> from the mapped table and key without reading the model property.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         仅使用映射的表与键创建 <see cref="T:MegaCrit.Sts2.Core.Localization.LocString" />，不读取模型属性。
		///     </para>
		/// </summary>
		public LocString CreateDefault(AbstractModel model)
		{
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0023: Expected O, but got Unknown
			ArgumentNullException.ThrowIfNull(model, "model");
			return new LocString(Table, Key(model));
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Resolves display titles through registered resolvers and known base-game model families.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过已注册的解析器和已知游戏原版模型族解析显示标题。
	///     </para>
	/// </summary>
	public static class ModelTitleExtensions
	{
		private readonly record struct TitleResolverCacheKey(Type ModelType, int Generation);

		private readonly record struct TitleResolverLookup(Func<AbstractModel, LocString?>? Resolver);

		private static readonly Lock ResolverSync = new Lock();

		private static readonly Dictionary<Type, Func<AbstractModel, LocString?>> RegisteredTitleResolvers = new Dictionary<Type, Func<AbstractModel, LocString>>();

		private static readonly ConcurrentDictionary<TitleResolverCacheKey, TitleResolverLookup> TitleResolverCache = new ConcurrentDictionary<TitleResolverCacheKey, TitleResolverLookup>();

		private static int _titleResolverGeneration;

		private static readonly ModelLocStringSource[] TitleSources = new ModelLocStringSource[14]
		{
			TitleSource<CardModel>("cards", (Func<CardModel, string>)((CardModel model) => ((AbstractModel)model).Id.Entry + ".title"), (Func<CardModel, LocString>)((CardModel model) => model.TitleLocString)),
			TitleSource<PotionModel>("potions", (Func<PotionModel, string>)((PotionModel model) => ((AbstractModel)model).Id.Entry + ".title"), (Func<PotionModel, LocString>)((PotionModel model) => model.Title)),
			TitleSource<RelicModel>("relics", (Func<RelicModel, string>)((RelicModel model) => ((AbstractModel)model).Id.Entry + ".title"), (Func<RelicModel, LocString>)((RelicModel model) => model.Title)),
			TitleSource<PowerModel>("powers", (Func<PowerModel, string>)((PowerModel model) => ((AbstractModel)model).Id.Entry + ".title"), (Func<PowerModel, LocString>)((PowerModel model) => model.Title)),
			TitleSource<OrbModel>("orbs", (Func<OrbModel, string>)((OrbModel model) => ((AbstractModel)model).Id.Entry + ".title"), (Func<OrbModel, LocString>)((OrbModel model) => model.Title)),
			TitleSource<CharacterModel>("characters", (Func<CharacterModel, string>)((CharacterModel model) => ((AbstractModel)model).Id.Entry + ".title"), (Func<CharacterModel, LocString>)((CharacterModel model) => model.Title)),
			TitleSource<MonsterModel>("monsters", (Func<MonsterModel, string>)((MonsterModel model) => ((AbstractModel)model).Id.Entry + ".name"), (Func<MonsterModel, LocString>)((MonsterModel model) => model.Title)),
			TitleSource<EnchantmentModel>("enchantments", (Func<EnchantmentModel, string>)((EnchantmentModel model) => ((AbstractModel)model).Id.Entry + ".title"), (Func<EnchantmentModel, LocString>)((EnchantmentModel model) => model.Title)),
			TitleSource<AfflictionModel>("afflictions", (Func<AfflictionModel, string>)((AfflictionModel model) => ((AbstractModel)model).Id.Entry + ".title"), (Func<AfflictionModel, LocString>)((AfflictionModel model) => model.Title)),
			TitleSource<ModifierModel>("modifiers", (Func<ModifierModel, string>)((ModifierModel model) => ((AbstractModel)model).Id.Entry + ".title"), (Func<ModifierModel, LocString>)((ModifierModel model) => model.Title)),
			TitleSource<AncientEventModel>("ancients", (Func<AncientEventModel, string>)((AncientEventModel model) => ((AbstractModel)model).Id.Entry + ".title"), (Func<AncientEventModel, LocString>)((AncientEventModel model) => ((EventModel)model).Title)),
			TitleSource<EventModel>("events", (Func<EventModel, string>)((EventModel model) => ((AbstractModel)model).Id.Entry + ".title"), (Func<EventModel, LocString>)((EventModel model) => model.Title)),
			TitleSource<ActModel>("acts", (Func<ActModel, string>)((ActModel model) => ((AbstractModel)model).Id.Entry + ".title"), (Func<ActModel, LocString>)((ActModel model) => model.Title)),
			TitleSource<EncounterModel>("encounters", (Func<EncounterModel, string>)((EncounterModel model) => ((AbstractModel)model).Id.Entry + ".title"), (Func<EncounterModel, LocString>)((EncounterModel model) => model.Title))
		};

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the known title <see cref="T:MegaCrit.Sts2.Core.Localization.LocString" /> sources, ordered from more specific model families
		///         to broader ones.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取已知的标题 <see cref="T:MegaCrit.Sts2.Core.Localization.LocString" /> 来源，并按模型族由具体到宽泛排列。
		///     </para>
		/// </summary>
		public static IReadOnlyList<ModelLocStringSource> KnownTitleSources { get; } = Array.AsReadOnly(TitleSources);

		/// <summary>
		///     <para xml:lang="en">
		///         Registers or replaces the title resolver for <typeparamref name="TModel" /> and its derived types.
		///         More specific registered model types take precedence.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <typeparamref name="TModel" /> 及其派生类型注册或替换标题解析器。
		///         更具体的已注册模型类型优先。
		///     </para>
		/// </summary>
		public static void RegisterTitleResolver<TModel>(Func<TModel, LocString?> resolver) where TModel : AbstractModel
		{
			ArgumentNullException.ThrowIfNull(resolver, "resolver");
			RegisterTitleResolver(typeof(TModel), (AbstractModel model) => resolver((TModel)(object)model));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers or replaces the title resolver for <paramref name="modelType" /> and its derived types.
		///         More specific registered model types take precedence.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="modelType" /> 及其派生类型注册或替换标题解析器。
		///         更具体的已注册模型类型优先。
		///     </para>
		/// </summary>
		public static void RegisterTitleResolver(Type modelType, Func<AbstractModel, LocString?> resolver)
		{
			ArgumentNullException.ThrowIfNull(modelType, "modelType");
			ArgumentNullException.ThrowIfNull(resolver, "resolver");
			if (!modelType.IsAssignableTo(typeof(AbstractModel)))
			{
				throw new ArgumentException(modelType.FullName + " must derive from " + typeof(AbstractModel).FullName + ".", "modelType");
			}
			using (ResolverSync.EnterScope())
			{
				RegisteredTitleResolvers[modelType] = resolver;
				Interlocked.Increment(ref _titleResolverGeneration);
				TitleResolverCache.Clear();
			}
		}

		/// <summary>
		///     <para xml:lang="en">Unregisters the title resolver for exactly <typeparamref name="TModel" />.</para>
		///     <para xml:lang="zh-CN">注销仅对应 <typeparamref name="TModel" /> 的标题解析器。</para>
		/// </summary>
		public static bool UnregisterTitleResolver<TModel>() where TModel : AbstractModel
		{
			return UnregisterTitleResolver(typeof(TModel));
		}

		/// <summary>
		///     <para xml:lang="en">Unregisters the title resolver for exactly <paramref name="modelType" />.</para>
		///     <para xml:lang="zh-CN">注销仅对应 <paramref name="modelType" /> 的标题解析器。</para>
		/// </summary>
		public static bool UnregisterTitleResolver(Type modelType)
		{
			ArgumentNullException.ThrowIfNull(modelType, "modelType");
			using (ResolverSync.EnterScope())
			{
				bool flag = RegisteredTitleResolvers.Remove(modelType);
				if (!flag)
				{
					return flag;
				}
				Interlocked.Increment(ref _titleResolverGeneration);
				TitleResolverCache.Clear();
				return flag;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves a display title for <paramref name="model" />, or returns
		///         <paramref name="fallback" /> when the model has no registered resolver and its family has no
		///         known title source.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         解析 <paramref name="model" /> 的显示标题。若该模型没有已注册解析器，且所属模型族没有
		///         已知标题来源，则返回 <paramref name="fallback" />。
		///     </para>
		/// </summary>
		public static LocString ResolveTitleOr(this AbstractModel model, LocString fallback)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			ArgumentNullException.ThrowIfNull(fallback, "fallback");
			if (!model.TryResolveTitle(out LocString title))
			{
				return fallback;
			}
			return title;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to resolve a display title from a registered resolver, then from a known base-game
		///         model family.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试从已注册解析器获取显示标题；若未取得标题，再尝试已知的游戏原版模型族。
		///     </para>
		/// </summary>
		public static bool TryResolveTitle(this AbstractModel model, [NotNullWhen(true)] out LocString? title)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			LocString val = GetRegisteredTitleResolver(((object)model).GetType())?.Invoke(model);
			if (val != null)
			{
				title = val;
				return true;
			}
			if (model.TryGetTitleLocStringSource(out ModelLocStringSource source))
			{
				title = source.Resolve(model);
				return true;
			}
			title = null;
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to resolve the title <see cref="T:MegaCrit.Sts2.Core.Localization.LocString" /> source mapping for
		///         <paramref name="model" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试解析 <paramref name="model" /> 的标题 <see cref="T:MegaCrit.Sts2.Core.Localization.LocString" /> 来源映射。
		///     </para>
		/// </summary>
		public static bool TryGetTitleLocStringSource(this AbstractModel model, [NotNullWhen(true)] out ModelLocStringSource? source)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			source = TitleSources.FirstOrDefault((ModelLocStringSource modelLocStringSource) => modelLocStringSource.Matches(model));
			return source != null;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates the default title <see cref="T:MegaCrit.Sts2.Core.Localization.LocString" /> from the mapped table and key without reading
		///         model property overrides.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从映射的表与键创建默认标题 <see cref="T:MegaCrit.Sts2.Core.Localization.LocString" />，不读取模型属性重写。
		///     </para>
		/// </summary>
		public static LocString CreateDefaultTitleLocString(this AbstractModel model)
		{
			//IL_003a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0040: Expected O, but got Unknown
			ArgumentNullException.ThrowIfNull(model, "model");
			if (!model.TryGetTitleLocStringSource(out ModelLocStringSource source))
			{
				return new LocString(model.Id.Category.ToLowerInvariant(), model.Id.Entry + ".title");
			}
			return source.CreateDefault(model);
		}

		private static ModelLocStringSource TitleSource<TModel>(string table, Func<TModel, string> key, Func<TModel, LocString> resolve) where TModel : AbstractModel
		{
			return new ModelLocStringSource(typeof(TModel), table, (AbstractModel model) => key((TModel)(object)model), (AbstractModel model) => resolve((TModel)(object)model));
		}

		private static Func<AbstractModel, LocString?>? GetRegisteredTitleResolver(Type modelType)
		{
			int num;
			TitleResolverLookup orAdd;
			do
			{
				num = Volatile.Read(in _titleResolverGeneration);
				orAdd = TitleResolverCache.GetOrAdd(new TitleResolverCacheKey(modelType, num), (TitleResolverCacheKey key) => FindRegisteredTitleResolver(key.ModelType));
			}
			while (num != Volatile.Read(in _titleResolverGeneration));
			return orAdd.Resolver;
		}

		private static TitleResolverLookup FindRegisteredTitleResolver(Type modelType)
		{
			using (ResolverSync.EnterScope())
			{
				Type type = modelType;
				while (type != null && typeof(AbstractModel).IsAssignableFrom(type))
				{
					if (RegisteredTitleResolvers.TryGetValue(type, out Func<AbstractModel, LocString> value))
					{
						return new TitleResolverLookup(value);
					}
					type = type.BaseType;
				}
			}
			return default(TitleResolverLookup);
		}
	}
}
namespace STS2RitsuLib.Models.Patches
{
	/// <summary>
	///     <para xml:lang="en">
	///         Dispatches base-game model clone operations to model saved data, capabilities, and
	///         <see cref="T:STS2RitsuLib.Models.ModelCloneRegistry" /> listeners.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将游戏原版模型复制操作分发给模型保存数据、模型能力及
	///         <see cref="T:STS2RitsuLib.Models.ModelCloneRegistry" /> 监听器。
	///     </para>
	/// </summary>
	internal sealed class ModelCloneRegistryPatch : IPatchMethod
	{
		public static string PatchId => "model_clone_registry";

		public static string Description => "Notify registered listeners after vanilla model cloning";

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(AbstractModel), "MutableClone", Type.EmptyTypes)
			};
		}

		public static void Postfix(AbstractModel __instance, AbstractModel __result)
		{
			ModelSavedDataRegistry.NotifyCloned(__instance, __result);
			ModelCapabilities.NotifyCloned(__instance, __result);
			ModelCloneRegistry.NotifyCloned(__instance, __result);
		}
	}
}
namespace STS2RitsuLib.Models.Identity
{
	/// <summary>
	///     <para xml:lang="en">
	///         Runtime-only identity assigned to mutable models when they enter synchronized base-game ownership.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         可变模型进入游戏原版的同步所有关系时，为其分配的仅限运行时身份。
	///     </para>
	/// </summary>
	public readonly record struct ModModelIdentity(uint Value)
	{
		/// <summary>
		///     <para xml:lang="en">Gets whether this identity can be used to resolve a model.</para>
		///     <para xml:lang="zh-CN">获取此身份是否可用于解析模型。</para>
		/// </summary>
		public bool IsValid => Value != 0;

		/// <summary>
		///     <para xml:lang="en">Represents an empty identity.</para>
		///     <para xml:lang="zh-CN">表示空身份。</para>
		/// </summary>
		public static readonly ModModelIdentity None = new ModModelIdentity(0u);
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Wire token that resolves a model identity while validating the expected model ID.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         用于解析模型身份并验证预期模型 ID 的传输令牌。
	///     </para>
	/// </summary>
	public readonly record struct ModModelIdentityToken(ModModelIdentity Identity, ModelId ModelId)
	{
		/// <summary>
		///     <para xml:lang="en">Gets whether this token can be used to resolve a model.</para>
		///     <para xml:lang="zh-CN">获取此令牌是否可用于解析模型。</para>
		/// </summary>
		public bool IsValid => Identity.IsValid;
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Tracks runtime model identities through deterministic base-game lifecycle entry points.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过确定的游戏原版生命周期入口跟踪运行时模型身份。
	///     </para>
	/// </summary>
	internal static class ModModelIdentityRegistry
	{
		internal readonly record struct PlayerInventoryIdentitySnapshot(CardIdentitySnapshot[] DeckCards, ModelIdentitySnapshot[] Relics, ModelIdentitySnapshot[] Potions);

		internal readonly record struct CardIdentitySnapshot(ModelIdentitySnapshot Card, ModelIdentitySnapshot Affliction, ModelIdentitySnapshot Enchantment);

		internal readonly record struct ModelIdentitySnapshot(AbstractModel? Model, ModModelIdentityToken Token);

		private sealed class ReferenceComparer : IEqualityComparer<AbstractModel>
		{
			public bool Equals(AbstractModel? x, AbstractModel? y)
			{
				return x == y;
			}

			public int GetHashCode(AbstractModel obj)
			{
				return ReferenceEqualityComparer.Instance.GetHashCode(obj);
			}
		}

		private const uint FirstIdentityValue = 1u;

		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<AbstractModel, uint> ObjectToIdentity = new Dictionary<AbstractModel, uint>(new ReferenceComparer());

		private static readonly Dictionary<uint, AbstractModel> IdentityToObject = new Dictionary<uint, AbstractModel>();

		private static uint _nextIdentity = 1u;

		public static void Clear()
		{
			using (Gate.EnterScope())
			{
				ObjectToIdentity.Clear();
				IdentityToObject.Clear();
				_nextIdentity = 1u;
			}
		}

		public static ModModelIdentity EnsureRegistered(AbstractModel? model)
		{
			if (model == null || !model.IsMutable || IsLocalOnly(model))
			{
				return ModModelIdentity.None;
			}
			using (Gate.EnterScope())
			{
				if (ObjectToIdentity.TryGetValue(model, out var value))
				{
					return new ModModelIdentity(value);
				}
				uint num = _nextIdentity++;
				ObjectToIdentity[model] = num;
				IdentityToObject[num] = model;
				return new ModModelIdentity(num);
			}
		}

		public static bool TryGetToken(AbstractModel? model, out ModModelIdentityToken token)
		{
			token = default(ModModelIdentityToken);
			if (model == null || IsLocalOnly(model))
			{
				return false;
			}
			using (Gate.EnterScope())
			{
				if (!ObjectToIdentity.TryGetValue(model, out var value) || value == 0)
				{
					return false;
				}
				token = new ModModelIdentityToken(new ModModelIdentity(value), model.Id);
				return true;
			}
		}

		private static bool IsLocalOnly(AbstractModel model)
		{
			return ModelIdSerializationCacheDynamicContentPatch.IsLocalOnlyModelId(model.Id);
		}

		public static bool TryResolve(ModModelIdentityToken token, out AbstractModel model)
		{
			model = null;
			if (!token.IsValid)
			{
				return false;
			}
			using (Gate.EnterScope())
			{
				if (!IdentityToObject.TryGetValue(token.Identity.Value, out AbstractModel value))
				{
					return false;
				}
				if (value.Id != token.ModelId)
				{
					return false;
				}
				model = value;
				return true;
			}
		}

		public static void Unregister(AbstractModel? model)
		{
			if (model == null)
			{
				return;
			}
			using (Gate.EnterScope())
			{
				if (ObjectToIdentity.Remove(model, out var value) && IdentityToObject.TryGetValue(value, out AbstractModel value2) && value2 == model)
				{
					IdentityToObject.Remove(value);
				}
			}
		}

		public static void RegisterCardTree(CardModel? card)
		{
			if (card != null)
			{
				EnsureRegistered((AbstractModel?)(object)card);
				EnsureRegistered((AbstractModel?)(object)card.Affliction);
				EnsureRegistered((AbstractModel?)(object)card.Enchantment);
			}
		}

		public static void RegisterPlayerInventory(Player? player)
		{
			if (player == null)
			{
				return;
			}
			foreach (CardModel card in player.Deck.Cards)
			{
				RegisterCardTree(card);
			}
			foreach (RelicModel relic in player.Relics)
			{
				EnsureRegistered((AbstractModel?)(object)relic);
			}
			foreach (PotionModel potionSlot in player.PotionSlots)
			{
				EnsureRegistered((AbstractModel?)(object)potionSlot);
			}
		}

		public static PlayerInventoryIdentitySnapshot CapturePlayerInventory(Player player)
		{
			return new PlayerInventoryIdentitySnapshot(CaptureCards(player.Deck.Cards), CaptureModels<RelicModel>(player.Relics), CaptureModels<PotionModel>(player.PotionSlots));
		}

		public static void RestorePlayerInventory(Player player, PlayerInventoryIdentitySnapshot snapshot)
		{
			RestoreCards(snapshot.DeckCards, player.Deck.Cards);
			RestoreModels<RelicModel>((IReadOnlyList<ModelIdentitySnapshot>)snapshot.Relics, player.Relics);
			RestoreModels<PotionModel>((IReadOnlyList<ModelIdentitySnapshot>)snapshot.Potions, player.PotionSlots);
		}

		private static CardIdentitySnapshot[] CaptureCards(IReadOnlyList<CardModel> cards)
		{
			CardIdentitySnapshot[] array = new CardIdentitySnapshot[cards.Count];
			for (int i = 0; i < cards.Count; i++)
			{
				array[i] = CaptureCardTree(cards[i]);
			}
			return array;
		}

		private static ModelIdentitySnapshot[] CaptureModels<TModel>(IReadOnlyList<TModel> models) where TModel : AbstractModel
		{
			ModelIdentitySnapshot[] array = new ModelIdentitySnapshot[models.Count];
			for (int i = 0; i < models.Count; i++)
			{
				array[i] = Capture((AbstractModel?)(object)models[i]);
			}
			return array;
		}

		private static ModelIdentitySnapshot Capture(AbstractModel? model)
		{
			if (model == null || !TryGetToken(model, out var token))
			{
				return default(ModelIdentitySnapshot);
			}
			return new ModelIdentitySnapshot(model, token);
		}

		private static CardIdentitySnapshot CaptureCardTree(CardModel? card)
		{
			if (card == null)
			{
				return default(CardIdentitySnapshot);
			}
			return new CardIdentitySnapshot(Capture((AbstractModel?)(object)card), Capture((AbstractModel?)(object)card.Affliction), Capture((AbstractModel?)(object)card.Enchantment));
		}

		private static void RestoreCards(IReadOnlyList<CardIdentitySnapshot> previous, IReadOnlyList<CardModel> current)
		{
			int num = Math.Min(previous.Count, current.Count);
			for (int i = 0; i < num; i++)
			{
				RestoreCardTree(previous[i], current[i]);
			}
			for (int j = num; j < previous.Count; j++)
			{
				Unregister(previous[j]);
			}
			for (int k = num; k < current.Count; k++)
			{
				RegisterCardTree(current[k]);
			}
		}

		private static void RestoreModels<TModel>(IReadOnlyList<ModelIdentitySnapshot> previous, IReadOnlyList<TModel> current) where TModel : AbstractModel
		{
			int num = Math.Min(previous.Count, current.Count);
			for (int i = 0; i < num; i++)
			{
				Restore(previous[i], (AbstractModel?)(object)current[i]);
			}
			for (int j = num; j < previous.Count; j++)
			{
				Unregister(previous[j].Model);
			}
			for (int k = num; k < current.Count; k++)
			{
				EnsureRegistered((AbstractModel?)(object)current[k]);
			}
		}

		private static void Restore(ModelIdentitySnapshot previous, AbstractModel? current)
		{
			if (current == null)
			{
				Unregister(previous.Model);
				return;
			}
			if (previous.Token.IsValid && previous.Token.ModelId == current.Id)
			{
				BindIdentity(current, previous.Token.Identity);
				return;
			}
			Unregister(previous.Model);
			EnsureRegistered(current);
		}

		private static void RestoreCardTree(CardIdentitySnapshot previous, CardModel? current)
		{
			if (current == null)
			{
				Unregister(previous);
				return;
			}
			Restore(previous.Card, (AbstractModel?)(object)current);
			Restore(previous.Affliction, (AbstractModel?)(object)current.Affliction);
			Restore(previous.Enchantment, (AbstractModel?)(object)current.Enchantment);
		}

		private static void Unregister(CardIdentitySnapshot snapshot)
		{
			Unregister(snapshot.Card.Model);
			Unregister(snapshot.Affliction.Model);
			Unregister(snapshot.Enchantment.Model);
		}

		private static void BindIdentity(AbstractModel model, ModModelIdentity identity)
		{
			if (!identity.IsValid || !model.IsMutable)
			{
				return;
			}
			using (Gate.EnterScope())
			{
				if (ObjectToIdentity.Remove(model, out var value) && IdentityToObject.TryGetValue(value, out AbstractModel value2) && value2 == model)
				{
					IdentityToObject.Remove(value);
				}
				if (IdentityToObject.TryGetValue(identity.Value, out AbstractModel value3))
				{
					ObjectToIdentity.Remove(value3);
				}
				ObjectToIdentity[model] = identity.Value;
				IdentityToObject[identity.Value] = model;
			}
			CardModel val = (CardModel)(object)((model is CardModel) ? model : null);
			if (val != null)
			{
				RegisterCardTree(val);
			}
		}
	}
}
