	public sealed record CardOverlayContribution
	{
		/// <summary>
		///     <para xml:lang="en">Stable ID for diagnostics and ordering within the contributing capability.</para>
		///     <para xml:lang="zh-CN">用于诊断以及贡献能力内部排序的稳定 ID。</para>
		/// </summary>
		public required string Id { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Draw order among capability overlays. Larger values are added later and render above smaller
		///         values.
		///     </para>
		///     <para xml:lang="zh-CN">能力覆盖层之间的绘制顺序。数值越大越晚加入，因此显示在更上层。</para>
		/// </summary>
		public int Order { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         When <see langword="true" />, RitsuLib applies a full-rectangle layout preset after creating the
		///         overlay node.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <see langword="true" /> 时，RitsuLib 会在创建覆盖层节点后应用全矩形布局预设。
		///     </para>
		/// </summary>
		public bool FullRect { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">
		///         Packed-scene path loaded through the game's preload cache, matching base-game card-overlay creation.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过游戏预加载缓存加载的 <see cref="T:Godot.PackedScene" /> 路径，与游戏原版卡牌覆盖层的创建行为一致。
		///     </para>
		/// </summary>
		public string? ScenePath { get; init; }

		/// <summary>
		///     <para xml:lang="en">Already resolved packed scene.</para>
		///     <para xml:lang="zh-CN">已解析的 PackedScene。</para>
		/// </summary>
		public PackedScene? Scene { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Factory for creating a fresh overlay control. It must return a new node each time because one
		///         <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> can be displayed by multiple <see cref="T:MegaCrit.Sts2.Core.Nodes.Cards.NCard" /> nodes.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         用于创建全新覆盖层 <see cref="T:Godot.Control" /> 的工厂。每次必须返回新的节点，因为同一个
		///         <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> 可能同时由多个 <see cref="T:MegaCrit.Sts2.Core.Nodes.Cards.NCard" /> 节点显示。
		///     </para>
		/// </summary>
		public Func<CardOverlayContext, Control?>? Factory { get; init; }

		/// <summary>
		///     <para xml:lang="en">Creates a contribution from a packed scene path.</para>
		///     <para xml:lang="zh-CN">从 PackedScene 路径创建贡献项。</para>
		/// </summary>
		public static CardOverlayContribution FromScenePath(string id, string scenePath, int order = 0, bool fullRect = true)
		{
			return new CardOverlayContribution
			{
				Id = id,
				ScenePath = scenePath,
				Order = order,
				FullRect = fullRect
			};
		}

		/// <summary>
		///     <para xml:lang="en">Creates a contribution from an already resolved packed scene.</para>
		///     <para xml:lang="zh-CN">从已解析的 PackedScene 创建贡献项。</para>
		/// </summary>
		public static CardOverlayContribution FromScene(string id, PackedScene scene, int order = 0, bool fullRect = true)
		{
			return new CardOverlayContribution
			{
				Id = id,
				Scene = scene,
				Order = order,
				FullRect = fullRect
			};
		}

		/// <summary>
		///     <para xml:lang="en">Creates a contribution from a control factory.</para>
		///     <para xml:lang="zh-CN">从 <see cref="T:Godot.Control" /> 工厂创建贡献项。</para>
		/// </summary>
		public static CardOverlayContribution FromFactory(string id, Func<CardOverlayContext, Control?> factory, int order = 0, bool fullRect = true)
		{
			return new CardOverlayContribution
			{
				Id = id,
				Factory = factory,
				Order = order,
				FullRect = fullRect
			};
		}

		[CompilerGenerated]
		[SetsRequiredMembers]
		private CardOverlayContribution(CardOverlayContribution original)
		{
			Id = original.Id;
			Order = original.Order;
			FullRect = original.FullRect;
			ScenePath = original.ScenePath;
			Scene = original.Scene;
			Factory = original.Factory;
		}
	}
