		internal static void CarryOverTransformCapabilities(CardModel original, CardModel? replacement)
		{
			if (replacement == null || original == replacement)
			{
				return;
			}
			foreach (ICardTransformCarryOverCapability capability in GetCapabilities<ICardTransformCarryOverCapability>(original))
			{
				if (!capability.ShouldCarryOverToTransformResult(original, replacement))
				{
					continue;
				}
				IModelCapability modelCapability = capability.CreateCarryOverCapability(original, replacement);
				if (modelCapability.Owner != null)
				{
					if ((object)modelCapability.Owner != replacement)
					{
						throw new InvalidOperationException("Transform carry-over capability '" + modelCapability.CapabilityId + "' was attached to an unexpected model.");
					}
					modelCapability.Detach(isInternal: true);
				}
				((AbstractModel)(object)replacement).Capabilities().Apply(modelCapability);
			}
		}

