	/// <summary>
	///     <para xml:lang="en">
	///         Base class for model-backed capabilities. Register subclasses as model capabilities when they need a
	///         stable <see cref="T:MegaCrit.Sts2.Core.Models.ModelId" /> and persistence identity.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         基于模型的能力基类。子类需要稳定的 <see cref="T:MegaCrit.Sts2.Core.Models.ModelId" /> 和持久化身份时，应将其注册为模型能力。
	///     </para>
	/// </summary>
	public abstract class ModelCapability : AbstractModel, IModelCapability, IModelCapabilityJsonState, IModelCapabilityCloneHandler, IModelDynamicVarContributor
	{
		private const string DynamicVarsStateKey = "dynamicVars";

		private const string AdditionalStateKey = "state";

		private DynamicVarSet? _dynamicVars;

		/// <inheritdoc />
		public override bool ShouldReceiveCombatHooks
		{
			get
			{
				if (this is IModelCapabilityHookListener modelCapabilityHookListener)
				{
					return modelCapabilityHookListener.ShouldReceiveOwnerHooks;
				}
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets capability-owned dynamic variables used by localized text, gameplay commands, and card previews
		///         when the owner is a card. This set is independent of the owner's dynamic variables; read owner
		///         variables through <see cref="P:STS2RitsuLib.Models.Capabilities.ModelCapability.Owner" /> when capability behavior depends on them.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取能力自有的动态变量；这些变量可用于本地化文本、游戏指令，并在所属模型为卡牌时用于卡牌预览。
		///         此集合独立于所属模型的动态变量；能力行为依赖所属模型变量时，应通过 <see cref="P:STS2RitsuLib.Models.Capabilities.ModelCapability.Owner" /> 读取。
		///     </para>
		/// </summary>
		public DynamicVarSet DynamicVars
		{
			get
			{
				if (_dynamicVars == null)
				{
					_dynamicVars = CreateDynamicVars();
				}
				if (Owner != null)
				{
					_dynamicVars.InitializeWithOwner(Owner);
				}
				return _dynamicVars;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the capability's canonical dynamic variables. Override this property to register variables
		///         directly on the capability.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取能力的规范动态变量。重写此属性可直接在能力上注册变量。
		///     </para>
		/// </summary>
		protected virtual IEnumerable<DynamicVar> CanonicalVars => Array.Empty<DynamicVar>();

		/// <inheritdoc />
		public virtual string CapabilityId => ModelCapabilityRegistry.GetCapabilityId(((object)this).GetType()) ?? ((object)((AbstractModel)this).Id).ToString();

		/// <inheritdoc />
		public AbstractModel? Owner { get; private set; }

		/// <inheritdoc />
		public virtual string? LocStringVariableScope => null;

		/// <inheritdoc />
		public virtual void Attach(AbstractModel owner, bool isInternal = false)
		{
			ArgumentNullException.ThrowIfNull(owner, "owner");
			Owner = owner;
			if (!isInternal)
			{
				OnAttach(owner);
			}
		}

		/// <inheritdoc />
		public virtual void Detach(bool isInternal = false)
		{
			AbstractModel owner = Owner;
			if (!isInternal && owner != null)
			{
				OnDetach(owner);
			}
			Owner = null;
		}

		/// <inheritdoc />
		public virtual IModelCapability CloneFor(AbstractModel clonedOwner)
		{
			ModelCapability obj = (ModelCapability)(object)((AbstractModel)this).MutableClone();
			obj.Owner = null;
			obj._dynamicVars = CloneDynamicVars(clonedOwner);
			obj.Attach(clonedOwner, isInternal: true);
			return obj;
		}

		/// <inheritdoc />
		public JsonNode? SaveState()
		{
			JsonObject jsonObject = SaveDynamicVarState();
			JsonNode jsonNode = SaveAdditionalState();
			if (jsonObject == null && jsonNode == null)
			{
				return null;
			}
			JsonObject jsonObject2 = new JsonObject();
			if (jsonObject != null)
			{
				jsonObject2["dynamicVars"] = jsonObject;
			}
			if (jsonNode != null)
			{
				jsonObject2["state"] = jsonNode.DeepClone();
			}
			return jsonObject2;
		}

		/// <inheritdoc />
		public void LoadState(JsonNode? state, int schemaVersion)
		{
			if (!(state is JsonObject jsonObject))
			{
				LoadAdditionalState(null, schemaVersion);
				return;
			}
			LoadDynamicVarState(jsonObject["dynamicVars"]);
			LoadAdditionalState(jsonObject["state"], schemaVersion);
		}

		DynamicVarSet IModelDynamicVarContributor.GetDynamicVars(AbstractModel model)
		{
			DynamicVarSet dynamicVars = DynamicVars;
			dynamicVars.InitializeWithOwner(model);
			return dynamicVars;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Invokes <paramref name="modifier" /> and marks the owning capability set dirty even if the callback
		///         throws.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         调用 <paramref name="modifier" />；即使回调抛出异常，也会将所属能力集合标记为脏。
		///     </para>
		/// </summary>
		/// <param name="modifier">
		///     <para xml:lang="en">
		///         The mutation to apply. External callers can use it to update capability-owned
		///         <see cref="P:STS2RitsuLib.Models.Capabilities.ModelCapability.DynamicVars" /> without separately marking the owner dirty.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         要应用的修改。外部调用方可借此更新能力自有的 <see cref="P:STS2RitsuLib.Models.Capabilities.ModelCapability.DynamicVars" />，无需另行将所属模型标记为脏。
		///     </para>
		/// </param>
		public void Modify(Action<ModelCapability> modifier)
		{
			ArgumentNullException.ThrowIfNull(modifier, "modifier");
			try
			{
				modifier(this);
			}
			finally
			{
				MarkDirty();
			}
		}

		/// <summary>
		///     <para xml:lang="en">Marks the owning capability set dirty after an in-place state change.</para>
		///     <para xml:lang="zh-CN">在原地修改状态后将所属能力集合标记为脏。</para>
		/// </summary>
		protected void MarkDirty()
		{
			if (Owner != null)
			{
				ModelCapabilities.MarkDirty(Owner);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Saves capability state in addition to its dynamic variables.</para>
		///     <para xml:lang="zh-CN">保存能力动态变量之外的额外状态。</para>
		/// </summary>
		protected virtual JsonNode? SaveAdditionalState()
		{
			return null;
		}

		/// <summary>
		///     <para xml:lang="en">Loads capability state in addition to its dynamic variables.</para>
		///     <para xml:lang="zh-CN">加载能力动态变量之外的额外状态。</para>
		/// </summary>
		protected virtual void LoadAdditionalState(JsonNode? state, int schemaVersion)
		{
		}

		/// <summary>
		///     <para xml:lang="en">Resets capability-owned dynamic variables to their canonical definitions.</para>
		///     <para xml:lang="zh-CN">将能力自有的动态变量重置为规范定义。</para>
		/// </summary>
		protected void ResetDynamicVarsToCanonical()
		{
			_dynamicVars = CreateDynamicVars();
			MarkDirty();
		}

		internal void RecalculateDynamicVarsForUpgradeOrEnchant()
		{
			DynamicVars.RecalculateForUpgradeOrEnchant();
			MarkDirty();
		}

		internal void FinalizeDynamicVarUpgrade()
		{
			DynamicVars.FinalizeUpgrade();
		}

		internal void MarkDynamicVarsJustUpgraded()
		{
			foreach (DynamicVar value in DynamicVars.Values)
			{
				value.UpgradeValueBy(0m);
			}
		}

		internal void NotifyLoadedFromSave()
		{
			OnLoadedFromSave();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Removes this capability from its owner's capability set when currently attached.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当前能力已附加时，将其从所属模型的能力集合中移除。
		///     </para>
		/// </summary>
		public bool RemoveFromOwner()
		{
			AbstractModel owner = Owner;
			if (owner != null)
			{
				return ModelCapabilities.Get(owner).Remove(this);
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Called when this capability is attached.</para>
		///     <para xml:lang="zh-CN">此能力被附加时调用。</para>
		/// </summary>
		protected virtual void OnAttach(AbstractModel owner)
		{
		}

		/// <summary>
		///     <para xml:lang="en">Called when this capability is detached.</para>
		///     <para xml:lang="zh-CN">此能力被分离时调用。</para>
		/// </summary>
		protected virtual void OnDetach(AbstractModel owner)
		{
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Called after this capability's owner is restored while loading a saved run.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         读取一局游戏的存档并恢复此能力的所属模型后调用。
		///     </para>
		/// </summary>
		protected virtual void OnLoadedFromSave()
		{
		}

		private DynamicVarSet CreateDynamicVars()
		{
			//IL_0026: Unknown result type (might be due to invalid IL or missing references)
			//IL_002c: Expected O, but got Unknown
			DynamicVarSet val = new DynamicVarSet(CanonicalVars.Select(CloneDynamicVar));
			if (Owner != null)
			{
				val.InitializeWithOwner(Owner);
			}
			return val;
		}

		private JsonObject? SaveDynamicVarState()
		{
			//IL_0026: Unknown result type (might be due to invalid IL or missing references)
			//IL_002c: Expected O, but got Unknown
			DynamicVarSet val = new DynamicVarSet(CanonicalVars.Select(CloneDynamicVar));
			JsonObject jsonObject = null;
			DynamicVar defaultVar = default(DynamicVar);
			foreach (DynamicVar value2 in DynamicVars.Values)
			{
				val.TryGetValue(value2.Name, ref defaultVar);
				if (TryCreateDynamicVarState(value2, defaultVar, out JsonNode value))
				{
					if (jsonObject == null)
					{
						jsonObject = new JsonObject();
					}
					jsonObject[value2.Name] = value;
				}
			}
			return jsonObject;
		}

		private void LoadDynamicVarState(JsonNode? state)
		{
			if (!(state is JsonObject jsonObject))
			{
				return;
			}
			DynamicVarSet dynamicVars = DynamicVars;
			DynamicVar dynamicVar = default(DynamicVar);
			foreach (KeyValuePair<string, JsonNode> item in jsonObject)
			{
				if (item.Value != null && dynamicVars.TryGetValue(item.Key, ref dynamicVar))
				{
					LoadDynamicVarValue(dynamicVar, item.Value);
				}
			}
		}

		private DynamicVarSet? CloneDynamicVars(AbstractModel clonedOwner)
		{
			//IL_0035: Unknown result type (might be due to invalid IL or missing references)
			//IL_003a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0042: Expected O, but got Unknown
			if (_dynamicVars == null)
			{
				return null;
			}
			DynamicVarSet val = new DynamicVarSet(_dynamicVars.Values.Select(CloneDynamicVar));
			val.InitializeWithOwner(clonedOwner);
			return val;
		}

		private static DynamicVar CloneDynamicVar(DynamicVar dynamicVar)
		{
			DynamicVar val = dynamicVar.Clone();
			DynamicVarTooltipRegistry.CopyTo(dynamicVar, val);
			return val;
		}

		private static bool TryCreateDynamicVarState(DynamicVar dynamicVar, DynamicVar? defaultVar, out JsonNode? value)
		{
			StringVar val = (StringVar)(object)((dynamicVar is StringVar) ? dynamicVar : null);
			if (val != null)
			{
				string text = val.StringValue ?? "";
				StringVar val2 = (StringVar)(object)((defaultVar is StringVar) ? defaultVar : null);
				string b = ((val2 != null) ? (val2.StringValue ?? "") : "");
				if (string.Equals(text, b, StringComparison.Ordinal))
				{
					value = null;
					return false;
				}
				value = JsonValue.Create(text);
				return true;
			}
			if (dynamicVar.BaseValue == ((defaultVar != null) ? defaultVar.BaseValue : 0m))
			{
				value = null;
				return false;
			}
			value = JsonValue.Create(dynamicVar.BaseValue);
			return true;
		}

		private static void LoadDynamicVarValue(DynamicVar dynamicVar, JsonNode value)
		{
			StringVar val = (StringVar)(object)((dynamicVar is StringVar) ? dynamicVar : null);
			if (val != null)
			{
				val.StringValue = value.GetValue<string>() ?? "";
			}
			else
			{
				dynamicVar.BaseValue = value.GetValue<decimal>();
			}
		}
