	/// <summary>
	///     <para xml:lang="en">Card capability base that handles plays of its owning card.</para>
	///     <para xml:lang="zh-CN">处理所属卡牌打出事件的卡牌能力基类。</para>
	/// </summary>
	public abstract class CardPlayCapability : CardCapability, ICardOnPlayHookListener
	{
		/// <inheritdoc />
		public Task<bool> BeforeCardOnPlay(BeforeCardOnPlayContext context)
		{
			if (!ShouldHandleCardPlay(context.CardPlay))
			{
				return Task.FromResult(result: false);
			}
			return BeforeOwnerCardOnPlay(context.ChoiceContext, context.CardPlay);
		}

		/// <inheritdoc />
		public Task AfterCardOnPlay(AfterCardOnPlayContext context)
		{
			return NotifyOwnerCardPlayed(context.ChoiceContext, context.CardPlay, context.OriginalOnPlayRan);
		}

		internal Task NotifyOwnerCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay, bool originalOnPlayRan = true)
		{
			if (!ShouldHandleCardPlay(cardPlay))
			{
				return Task.CompletedTask;
			}
			return OnOwnerCardPlayed(choiceContext, cardPlay, originalOnPlayRan);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns <see langword="true" /> when this capability should handle <paramref name="cardPlay" />.
		///     </para>
		///     <para xml:lang="zh-CN">返回此能力是否应处理 <paramref name="cardPlay" />。</para>
		/// </summary>
		protected virtual bool ShouldHandleCardPlay(CardPlay cardPlay)
		{
			if (base.Owner != null)
			{
				return cardPlay.Card == base.Owner;
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Called after the owning card's <c>OnPlay</c> body completes.</para>
		///     <para xml:lang="zh-CN">所属卡牌的 <c>OnPlay</c> 主体完成后调用。</para>
		/// </summary>
		protected abstract Task OnOwnerCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay);

		/// <summary>
		///     <para xml:lang="en">
		///         Called after the point where the owning card's <c>OnPlay</c> body would run.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在所属卡牌的 <c>OnPlay</c> 主体原本应运行的位置之后调用。
		///     </para>
		/// </summary>
		protected virtual Task OnOwnerCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay, bool originalOnPlayRan)
		{
			if (!originalOnPlayRan)
			{
				return Task.CompletedTask;
			}
			return OnOwnerCardPlayed(choiceContext, cardPlay);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Runs before the owning card's <c>OnPlay</c> body. Return <see langword="true" /> to suppress the
		///         original body.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在所属卡牌的 <c>OnPlay</c> 主体前运行。返回 <see langword="true" /> 可阻止原始主体执行。
		///     </para>
		/// </summary>
		protected virtual Task<bool> BeforeOwnerCardOnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			return Task.FromResult(result: false);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Card capability that removes itself after the owning card is played once.</para>
	///     <para xml:lang="zh-CN">所属卡牌打出一次后自动移除自身的卡牌能力。</para>
	/// </summary>
	public abstract class OneShotCardPlayCapability : CardPlayCapability
	{
		/// <inheritdoc />
		protected sealed override async Task OnOwnerCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			try
			{
				await OnOwnerCardPlayedOnce(choiceContext, cardPlay);
			}
			finally
			{
				RemoveFromOwner();
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Called once after the owning card's <c>OnPlay</c> body completes, before the capability removes itself.
		///     </para>
		///     <para xml:lang="zh-CN">所属卡牌的 <c>OnPlay</c> 主体完成后调用一次，随后能力会移除自身。</para>
		/// </summary>
		protected abstract Task OnOwnerCardPlayedOnce(PlayerChoiceContext choiceContext, CardPlay cardPlay);
	}
	/// <summary>
	///     <para xml:lang="en">Owner-hook capability that removes itself after combat ends.</para>
	///     <para xml:lang="zh-CN">战斗结束后自动移除自身的所属模型钩子能力。</para>
	/// </summary>
	public abstract class UntilCombatEndCapability<TModel> : OwnerHookCapability<TModel> where TModel : AbstractModel
	{
		/// <inheritdoc />
		public override async Task AfterCombatEnd(CombatRoom room)
		{
			try
			{
				await OnCombatEnded(room);
			}
			finally
			{
				RemoveFromOwner();
			}
		}

		/// <summary>
		///     <para xml:lang="en">Called when combat ends, before the capability removes itself.</para>
		///     <para xml:lang="zh-CN">战斗结束时调用，随后能力会移除自身。</para>
		/// </summary>
		protected virtual Task OnCombatEnded(CombatRoom room)
		{
			return Task.CompletedTask;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Owner-hook capability with a saved turn counter that removes itself when the counter reaches
	///         zero.
	///     </para>
	///     <para xml:lang="zh-CN">保存回合计数并在计数归零后自动移除自身的所属模型钩子能力。</para>
	/// </summary>
	public abstract class TurnLimitedCapability<TModel> : OwnerHookCapability<TModel> where TModel : AbstractModel
	{
		private const string RemainingTurnsKey = "remainingTurns";

		/// <summary>
		///     <para xml:lang="en">Remaining turn ticks before this capability removes itself.</para>
		///     <para xml:lang="zh-CN">此能力移除自身前剩余的回合计数。</para>
		/// </summary>
		public int RemainingTurns { get; private set; } = 1;

		/// <summary>
		///     <para xml:lang="en">Creates a capability with one remaining turn.</para>
		///     <para xml:lang="zh-CN">创建剩余一回合的能力。</para>
		/// </summary>
		protected TurnLimitedCapability()
		{
		}

		/// <summary>
		///     <para xml:lang="en">Creates a capability with <paramref name="remainingTurns" /> remaining turns.</para>
		///     <para xml:lang="zh-CN">创建剩余 <paramref name="remainingTurns" /> 回合的能力。</para>
		/// </summary>
		protected TurnLimitedCapability(int remainingTurns)
		{
			SetRemainingTurns(remainingTurns);
		}

		/// <inheritdoc />
		protected override JsonNode SaveAdditionalState()
		{
			return new JsonObject { ["remainingTurns"] = RemainingTurns };
		}

		/// <inheritdoc />
		protected override void LoadAdditionalState(JsonNode? state, int schemaVersion)
		{
			RemainingTurns = ReadRemainingTurns(state);
		}

		/// <inheritdoc />
		public override Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			//IL_0002: Unknown result type (might be due to invalid IL or missing references)
			return AfterTurnLimitTurnEnded(choiceContext, side);
		}

		private async Task AfterTurnLimitTurnEnded(PlayerChoiceContext choiceContext, CombatSide side)
		{
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_001f: Unknown result type (might be due to invalid IL or missing references)
			if (RemainingTurns <= 0 || !ShouldTickTurnLimit(choiceContext, side))
			{
				return;
			}
			RemainingTurns--;
			MarkDirty();
			try
			{
				await OnTurnLimitTicked(choiceContext, side, RemainingTurns);
			}
			finally
			{
				if (RemainingTurns <= 0)
				{
					try
					{
						await OnTurnLimitExpired(choiceContext, side);
					}
					finally
					{
						RemoveFromOwner();
					}
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">Sets the remaining turn count and marks the capability dirty when attached.</para>
		///     <para xml:lang="zh-CN">设置剩余回合数，并在已附加时标记能力变更。</para>
		/// </summary>
		protected void SetRemainingTurns(int remainingTurns)
		{
			if (remainingTurns < 0)
			{
				throw new ArgumentOutOfRangeException("remainingTurns", remainingTurns, "Remaining turns cannot be negative.");
			}
			RemainingTurns = remainingTurns;
			MarkDirty();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns <see langword="true" /> when this turn-end hook should decrement the remaining count.
		///     </para>
		///     <para xml:lang="zh-CN">确定此回合结束钩子是否应减少剩余计数。</para>
		/// </summary>
		protected virtual bool ShouldTickTurnLimit(PlayerChoiceContext choiceContext, CombatSide side)
		{
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Called after a turn tick decrements the remaining count.</para>
		///     <para xml:lang="zh-CN">每次回合计数减少后调用。</para>
		/// </summary>
		protected virtual Task OnTurnLimitTicked(PlayerChoiceContext choiceContext, CombatSide side, int remainingTurns)
		{
			return Task.CompletedTask;
		}

		/// <summary>
		///     <para xml:lang="en">Called when the turn counter reaches zero, before the capability removes itself.</para>
		///     <para xml:lang="zh-CN">回合计数归零时调用，随后能力会移除自身。</para>
		/// </summary>
		protected virtual Task OnTurnLimitExpired(PlayerChoiceContext choiceContext, CombatSide side)
		{
			return Task.CompletedTask;
		}

		private static int ReadRemainingTurns(JsonNode? state)
		{
			if (!(state is JsonObject jsonObject) || !jsonObject.TryGetPropertyValue("remainingTurns", out JsonNode jsonNode) || jsonNode == null)
			{
				return 1;
			}
			return Math.Max(jsonNode.GetValue<int>(), 0);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Base contract for a capability attached to an <see cref="T:MegaCrit.Sts2.Core.Models.AbstractModel" /> instance.</para>
	///     <para xml:lang="zh-CN">附加到 <see cref="T:MegaCrit.Sts2.Core.Models.AbstractModel" /> 实例的能力基础契约。</para>
	/// </summary>
	public interface IModelCapability
	{
		/// <summary>
		///     <para xml:lang="en">Stable capability ID used for runtime lookup and persistence.</para>
		///     <para xml:lang="zh-CN">用于运行时查找和持久化的稳定能力 ID。</para>
		/// </summary>
		string CapabilityId { get; }

		/// <summary>
		///     <para xml:lang="en">Current owning model, or <see langword="null" /> when detached.</para>
		///     <para xml:lang="zh-CN">当前所属模型；未附加时为 <see langword="null" />。</para>
		/// </summary>
		AbstractModel? Owner { get; }

		/// <summary>
		///     <para xml:lang="en">Called when the capability is attached to a model.</para>
		///     <para xml:lang="zh-CN">当能力附加到模型时调用。</para>
		/// </summary>
		void Attach(AbstractModel owner, bool isInternal = false);

		/// <summary>
		///     <para xml:lang="en">Called when the capability is detached from a model.</para>
		///     <para xml:lang="zh-CN">当能力从模型分离时调用。</para>
		/// </summary>
		void Detach(bool isInternal = false);
	}
	/// <summary>
	///     <para xml:lang="en">Typed capability contract for capabilities that are only valid on one model family.</para>
	///     <para xml:lang="zh-CN">只适用于某个模型族的类型化能力协定。</para>
	/// </summary>
	public interface IModelCapability<out TModel> : IModelCapability where TModel : AbstractModel
	{
		/// <summary>
		///     <para xml:lang="en">Current owning model, or <see langword="null" /> when detached.</para>
		///     <para xml:lang="zh-CN">当前所属模型；未附加时为 <see langword="null" />。</para>
		/// </summary>
		new TModel? Owner { get; }
	}
	/// <summary>
	///     <para xml:lang="en">Optional provider implemented by ordinary model classes to seed their default capability list.</para>
	///     <para xml:lang="zh-CN">普通模型类可实现的可选提供器，用于填充默认能力列表。</para>
	/// </summary>
	public interface IModelCapabilitySource
	{
		/// <summary>
		///     <para xml:lang="en">Adds this model's own default capabilities to <paramref name="capabilities" />.</para>
		///     <para xml:lang="zh-CN">将此模型自身的默认能力添加到 <paramref name="capabilities" />。</para>
		/// </summary>
		void BuildDefaultCapabilities(ModelCapabilityList capabilities);
	}
	/// <summary>
	///     <para xml:lang="en">Optional capability merge behavior used by <see cref="M:STS2RitsuLib.Models.Capabilities.ModelCapabilitySet.Apply(STS2RitsuLib.Models.Capabilities.IModelCapability,STS2RitsuLib.Models.Capabilities.ApplyModelCapabilityOptions)" />.</para>
	///     <para xml:lang="zh-CN"><see cref="M:STS2RitsuLib.Models.Capabilities.ModelCapabilitySet.Apply(STS2RitsuLib.Models.Capabilities.IModelCapability,STS2RitsuLib.Models.Capabilities.ApplyModelCapabilityOptions)" /> 使用的可选能力合并行为。</para>
	/// </summary>
	public interface IModelCapabilityMergeHandler
	{
		/// <summary>
		///     <para xml:lang="en">Attempts to merge <paramref name="incoming" /> into this capability.</para>
		///     <para xml:lang="zh-CN">尝试将 <paramref name="incoming" /> 合并到此能力。</para>
		/// </summary>
		bool TryMergeWith(IModelCapability incoming, ApplyModelCapabilityOptions options, out IModelCapability? merged);

		/// <summary>
		///     <para xml:lang="en">Attempts to subtract <paramref name="incoming" /> from this capability.</para>
		///     <para xml:lang="zh-CN">尝试从此能力中减去 <paramref name="incoming" />。</para>
		/// </summary>
		bool TrySubtractiveMergeWith(IModelCapability incoming, ApplyModelCapabilityOptions options, out IModelCapability? merged);
	}
	/// <summary>
	///     <para xml:lang="en">Optional capability JSON persistence behavior.</para>
	///     <para xml:lang="zh-CN">可选能力 JSON 持久化行为。</para>
	/// </summary>
	public interface IModelCapabilityJsonState
	{
		/// <summary>
		///     <para xml:lang="en">Current schema version written for this capability's state.</para>
		///     <para xml:lang="zh-CN">此能力状态写入的当前架构版本。</para>
		/// </summary>
		int SchemaVersion => 1;

		/// <summary>
		///     <para xml:lang="en">
		///         Saves capability state. Return <see langword="null" /> for stateless capabilities.
		///     </para>
		///     <para xml:lang="zh-CN">保存能力状态。无状态能力可返回 <see langword="null" />。</para>
		/// </summary>
		JsonNode? SaveState();

		/// <summary>
		///     <para xml:lang="en">Loads capability state.</para>
		///     <para xml:lang="zh-CN">加载能力状态。</para>
		/// </summary>
		void LoadState(JsonNode? state, int schemaVersion);
	}
	/// <summary>
	///     <para xml:lang="en">Optional capability callback invoked after its owner has been cloned.</para>
	///     <para xml:lang="zh-CN">所属模型被复制后调用的可选能力回调。</para>
	/// </summary>
	public interface IModelCapabilityCloneNotification
	{
		/// <summary>
		///     <para xml:lang="en">Called on the cloned capability after it has been attached to <paramref name="clonedOwner" />.</para>
		///     <para xml:lang="zh-CN">在复制出的能力附加到 <paramref name="clonedOwner" /> 后调用。</para>
		/// </summary>
		void AfterOwnerCloned(AbstractModel originalOwner, AbstractModel clonedOwner, IModelCapability originalCapability);
	}
	/// <summary>
	///     <para xml:lang="en">Optional capability cloning behavior.</para>
	///     <para xml:lang="zh-CN">可选能力复制行为。</para>
	/// </summary>
	public interface IModelCapabilityCloneHandler
	{
		/// <summary>
		///     <para xml:lang="en">Creates the capability instance attached to a cloned owner.</para>
		///     <para xml:lang="zh-CN">创建附加到复制后所属模型的能力实例。</para>
		/// </summary>
		IModelCapability CloneFor(AbstractModel clonedOwner);
	}
	/// <summary>
	///     <para xml:lang="en">Options used while applying a capability.</para>
	///     <para xml:lang="zh-CN">应用能力时使用的选项。</para>
	/// </summary>
	public readonly record struct ApplyModelCapabilityOptions(bool AllowMerge = true, bool UseSubtractiveMerge = false, bool IsUpgrade = false, IReadOnlyDictionary<string, object?>? Extra = null)
	{
		/// <summary>
		///     <para xml:lang="en">Creates options for applying a capability as part of an owner upgrade.</para>
		///     <para xml:lang="zh-CN">创建在所属模型升级期间应用能力时使用的选项。</para>
		/// </summary>
		public static ApplyModelCapabilityOptions Upgrade(bool allowMerge = true, IReadOnlyDictionary<string, object?>? extra = null)
		{
			return new ApplyModelCapabilityOptions(allowMerge, UseSubtractiveMerge: false, IsUpgrade: true, extra);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Controls how unknown saved capability entries are handled by bulk collection operations.</para>
	///     <para xml:lang="zh-CN">控制批量集合操作如何处理未知的已保存能力条目。</para>
	/// </summary>
	public enum UnknownModelCapabilityPolicy
	{
		/// <summary>
		///     <para xml:lang="en">Keep unknown entries so future/optional capability data round-trips.</para>
		///     <para xml:lang="zh-CN">保留未知条目，以便未来或可选能力数据能继续往返保存。</para>
		/// </summary>
		Preserve,
		/// <summary>
		///     <para xml:lang="en">Remove unknown entries as well.</para>
		///     <para xml:lang="zh-CN">同时移除未知条目。</para>
		/// </summary>
		Remove
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Controls ordered insertion when the requested anchor capability is not attached.
	///     </para>
	///     <para xml:lang="zh-CN">控制有序插入时找不到锚点能力的处理方式。</para>
	/// </summary>
	public enum MissingModelCapabilityAnchorPolicy
	{
		/// <summary>
		///     <para xml:lang="en">Add the capability at the end.</para>
		///     <para xml:lang="zh-CN">添加到末尾。</para>
		/// </summary>
		Append,
		/// <summary>
		///     <para xml:lang="en">Add the capability at the beginning.</para>
		///     <para xml:lang="zh-CN">添加到开头。</para>
		/// </summary>
		Prepend,
		/// <summary>
		///     <para xml:lang="en">Do not add the capability.</para>
		///     <para xml:lang="zh-CN">不添加能力。</para>
		/// </summary>
		Skip,
		/// <summary>
		///     <para xml:lang="en">Throw an exception.</para>
		///     <para xml:lang="zh-CN">抛出异常。</para>
		/// </summary>
		Throw
	}
	/// <summary>
	///     <para xml:lang="en">Mutable list used while resolving a model's default capabilities.</para>
	///     <para xml:lang="zh-CN">解析模型默认能力时使用的可变列表。</para>
	/// </summary>
	public sealed class ModelCapabilityList
	{
		private readonly List<IModelCapability> _capabilities = new List<IModelCapability>();

		private ReadOnlyCollection<IModelCapability>? _readOnlyCapabilities;

		/// <summary>
		///     <para xml:lang="en">All capabilities in default execution order.</para>
		///     <para xml:lang="zh-CN">默认执行顺序中的所有能力。</para>
		/// </summary>
		public IReadOnlyList<IModelCapability> All => _readOnlyCapabilities ?? (_readOnlyCapabilities = _capabilities.AsReadOnly());

		/// <summary>
		///     <para xml:lang="en">Number of capabilities in the list.</para>
		///     <para xml:lang="zh-CN">列表中的能力数量。</para>
		/// </summary>
		public int Count => _capabilities.Count;

		/// <summary>
		///     <para xml:lang="en">Adds an already-created capability instance to the end of the list.</para>
		///     <para xml:lang="zh-CN">添加一个已经创建好的能力实例到列表末尾。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         Use this overload for plain, non-model-backed <see cref="T:STS2RitsuLib.Models.Capabilities.IModelCapability" /> implementations or
		///         for instances that already came from the registry. Do not call constructors for types inheriting
		///         <see cref="T:STS2RitsuLib.Models.Capabilities.ModelCapability" /> here; register the type with <c>RegisterModelCapability</c> and add
		///         it with <see cref="M:STS2RitsuLib.Models.Capabilities.ModelCapabilityList.Add``1" /> or <see cref="M:STS2RitsuLib.Models.Capabilities.ModelCapabilityList.Add(System.Type)" /> so creation goes through
		///         <c>ModelDb</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         此重载用于普通的非模型化 <see cref="T:STS2RitsuLib.Models.Capabilities.IModelCapability" /> 实现，或已由注册表创建的实例。
		///         不要在这里直接构造继承 <see cref="T:STS2RitsuLib.Models.Capabilities.ModelCapability" /> 的类型；应先用
		///         <c>RegisterModelCapability</c> 注册类型，再通过 <see cref="M:STS2RitsuLib.Models.Capabilities.ModelCapabilityList.Add``1" /> 或
		///         <see cref="M:STS2RitsuLib.Models.Capabilities.ModelCapabilityList.Add(System.Type)" /> 添加，让创建流程经过 <c>ModelDb</c>。
		///     </para>
		/// </remarks>
		public IModelCapability Add(IModelCapability capability)
		{
			ValidateCapability(capability);
			EnsureInstanceNotPresent(capability);
			_capabilities.Add(capability);
			return capability;
		}

		/// <summary>
		///     <para xml:lang="en">Creates a capability and adds it to the end of the list.</para>
		///     <para xml:lang="zh-CN">创建能力并添加到列表末尾。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         This is the preferred default-capability path for registered <see cref="T:STS2RitsuLib.Models.Capabilities.ModelCapability" /> types.
		///         Registered model-backed capabilities are created through <c>ModelDb</c>, not by direct constructors.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         这是注册过的 <see cref="T:STS2RitsuLib.Models.Capabilities.ModelCapability" /> 类型在默认能力中的首选入口。
		///         已注册的模型化能力会通过 <c>ModelDb</c> 创建，而不是直接调用构造函数。
		///     </para>
		/// </remarks>
		public TCapability Add<TCapability>() where TCapability : class, IModelCapability
		{
			TCapability val = CreateCapability<TCapability>();
			Add(val);
			return val;
		}

		/// <summary>
		///     <para xml:lang="en">Creates a capability of <paramref name="capabilityType" /> and adds it to the end of the list.</para>
		///     <para xml:lang="zh-CN">创建 <paramref name="capabilityType" /> 类型能力并添加到列表末尾。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         Use this overload when the capability type is only known at runtime. Registered
		///         <see cref="T:STS2RitsuLib.Models.Capabilities.ModelCapability" /> types are created through <c>ModelDb</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当能力类型只在运行时已知时使用此重载。已注册的 <see cref="T:STS2RitsuLib.Models.Capabilities.ModelCapability" /> 类型会通过
		///         <c>ModelDb</c> 创建。
		///     </para>
		/// </remarks>
		public IModelCapability Add(Type capabilityType)
		{
			IModelCapability modelCapability = CreateCapability(capabilityType);
			Add(modelCapability);
			return modelCapability;
		}

		/// <summary>
		///     <para xml:lang="en">Creates a registered capability and adds it to the end of the list.</para>
		///     <para xml:lang="zh-CN">创建已注册能力并添加到列表末尾。</para>
		/// </summary>
		public TCapability AddFromRegistry<TCapability>() where TCapability : class, IModelCapability
		{
			TCapability val = CreateFromRegistry<TCapability>();
			Add(val);
			return val;
		}

		/// <summary>
		///     <para xml:lang="en">Inserts a created capability at <paramref name="index" />.</para>
		///     <para xml:lang="zh-CN">创建能力并插入到 <paramref name="index" />。</para>
		/// </summary>
		public TCapability Insert<TCapability>(int index) where TCapability : class, IModelCapability
		{
			TCapability val = CreateCapability<TCapability>();
			Insert(index, val);
			return val;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a capability of <paramref name="capabilityType" /> and inserts it at
		///         <paramref name="index" />.
		///     </para>
		///     <para xml:lang="zh-CN">创建 <paramref name="capabilityType" /> 类型能力并插入到 <paramref name="index" />。</para>
		/// </summary>
		public IModelCapability Insert(int index, Type capabilityType)
		{
			IModelCapability modelCapability = CreateCapability(capabilityType);
			Insert(index, modelCapability);
			return modelCapability;
		}

		private static TCapability CreateCapability<TCapability>() where TCapability : class, IModelCapability
		{
			string capabilityId = ModelCapabilityRegistry.GetCapabilityId<TCapability>();
			if (capabilityId != null)
			{
				return CreateFromRegistry<TCapability>(capabilityId);
			}
			if (typeof(ModelCapability).IsAssignableFrom(typeof(TCapability)))
			{
				throw new InvalidOperationException("Model capability type is not registered: " + typeof(TCapability).FullName + ". Register it with RegisterModelCapability before adding it to a default capability list.");
			}
			return Activator.CreateInstance<TCapability>() ?? throw new InvalidOperationException("Capability type must have a public parameterless constructor: " + typeof(TCapability).FullName);
		}

		private static IModelCapability CreateCapability(Type capabilityType)
		{
			ArgumentNullException.ThrowIfNull(capabilityType, "capabilityType");
			if (capabilityType.ContainsGenericParameters || capabilityType.IsAbstract || capabilityType.IsInterface || !typeof(IModelCapability).IsAssignableFrom(capabilityType))
			{
				throw new ArgumentException("Type '" + capabilityType.FullName + "' must be a concrete implementation of IModelCapability.", "capabilityType");
			}
			string capabilityId = ModelCapabilityRegistry.GetCapabilityId(capabilityType);
			if (capabilityId != null)
			{
				return ModelCapabilityRegistry.Create(capabilityId);
			}
			if (typeof(ModelCapability).IsAssignableFrom(capabilityType))
			{
				throw new InvalidOperationException("Model capability type is not registered: " + capabilityType.FullName + ". Register it with RegisterModelCapability before adding it to a default capability list.");
			}
			IModelCapability modelCapability = Activator.CreateInstance(capabilityType) as IModelCapability;
			return modelCapability ?? throw new InvalidOperationException("Capability type must have a public parameterless constructor: " + capabilityType.FullName);
		}

		private static TCapability CreateFromRegistry<TCapability>(string? capabilityId = null) where TCapability : class, IModelCapability
		{
			return (capabilityId == null) ? ModelCapabilityRegistry.Create<TCapability>() : ((ModelCapabilityRegistry.Create(capabilityId) as TCapability) ?? throw new InvalidOperationException($"Registered capability '{capabilityId}' is not a '{typeof(TCapability).FullName}'."));
		}

		/// <summary>
		///     <para xml:lang="en">Adds all <paramref name="capabilities" /> to the end of the list.</para>
		///     <para xml:lang="zh-CN">将所有 <paramref name="capabilities" /> 添加到列表末尾。</para>
		/// </summary>
		public void AddRange(IEnumerable<IModelCapability> capabilities)
		{
			ArgumentNullException.ThrowIfNull(capabilities, "capabilities");
			IModelCapability[] array = capabilities.ToArray();
			HashSet<IModelCapability> hashSet = new HashSet<IModelCapability>(_capabilities, ReferenceEqualityComparer.Instance);
			IModelCapability[] array2 = array;
			foreach (IModelCapability modelCapability in array2)
			{
				ValidateCapability(modelCapability);
				if (!hashSet.Add(modelCapability))
				{
					throw new InvalidOperationException("The same capability instance cannot appear more than once: " + modelCapability.CapabilityId);
				}
			}
			_capabilities.AddRange(array);
		}

		/// <summary>
		///     <para xml:lang="en">Inserts <paramref name="capability" /> at <paramref name="index" />.</para>
		///     <para xml:lang="zh-CN">在 <paramref name="index" /> 插入 <paramref name="capability" />。</para>
		/// </summary>
		public IModelCapability Insert(int index, IModelCapability capability)
		{
			ValidateCapability(capability);
			EnsureInstanceNotPresent(capability);
			if (index < 0 || index > _capabilities.Count)
			{
				throw new ArgumentOutOfRangeException("index", index, "Index is outside the list bounds.");
			}
			_capabilities.Insert(index, capability);
			return capability;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Inserts <paramref name="capability" /> before the first capability of type
		///         <typeparamref name="TExisting" />.
		///     </para>
		///     <para xml:lang="zh-CN">将 <paramref name="capability" /> 插入到第一个 <typeparamref name="TExisting" /> 能力之前。</para>
		/// </summary>
		public IModelCapability? InsertBefore<TExisting>(IModelCapability capability, MissingModelCapabilityAnchorPolicy missingAnchorPolicy = MissingModelCapabilityAnchorPolicy.Append) where TExisting : class, IModelCapability
		{
			return InsertRelativeTo<TExisting>(capability, after: false, missingAnchorPolicy);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Inserts <paramref name="capability" /> after the first capability of type
		///         <typeparamref name="TExisting" />.
		///     </para>
		///     <para xml:lang="zh-CN">将 <paramref name="capability" /> 插入到第一个 <typeparamref name="TExisting" /> 能力之后。</para>
		/// </summary>
		public IModelCapability? InsertAfter<TExisting>(IModelCapability capability, MissingModelCapabilityAnchorPolicy missingAnchorPolicy = MissingModelCapabilityAnchorPolicy.Append) where TExisting : class, IModelCapability
		{
			return InsertRelativeTo<TExisting>(capability, after: true, missingAnchorPolicy);
		}

		/// <summary>
		///     <para xml:lang="en">Shorthand for <see cref="M:STS2RitsuLib.Models.Capabilities.ModelCapabilityList.InsertBefore``1(STS2RitsuLib.Models.Capabilities.IModelCapability,STS2RitsuLib.Models.Capabilities.MissingModelCapabilityAnchorPolicy)" />.</para>
		///     <para xml:lang="zh-CN"><see cref="M:STS2RitsuLib.Models.Capabilities.ModelCapabilityList.InsertBefore``1(STS2RitsuLib.Models.Capabilities.IModelCapability,STS2RitsuLib.Models.Capabilities.MissingModelCapabilityAnchorPolicy)" /> 的简写。</para>
		/// </summary>
		public IModelCapability? Before<TExisting>(IModelCapability capability, MissingModelCapabilityAnchorPolicy missingAnchorPolicy = MissingModelCapabilityAnchorPolicy.Append) where TExisting : class, IModelCapability
		{
			return InsertBefore<TExisting>(capability, missingAnchorPolicy);
		}

		/// <summary>
		///     <para xml:lang="en">Shorthand for <see cref="M:STS2RitsuLib.Models.Capabilities.ModelCapabilityList.InsertAfter``1(STS2RitsuLib.Models.Capabilities.IModelCapability,STS2RitsuLib.Models.Capabilities.MissingModelCapabilityAnchorPolicy)" />.</para>
		///     <para xml:lang="zh-CN"><see cref="M:STS2RitsuLib.Models.Capabilities.ModelCapabilityList.InsertAfter``1(STS2RitsuLib.Models.Capabilities.IModelCapability,STS2RitsuLib.Models.Capabilities.MissingModelCapabilityAnchorPolicy)" /> 的简写。</para>
		/// </summary>
		public IModelCapability? After<TExisting>(IModelCapability capability, MissingModelCapabilityAnchorPolicy missingAnchorPolicy = MissingModelCapabilityAnchorPolicy.Append) where TExisting : class, IModelCapability
		{
			return InsertAfter<TExisting>(capability, missingAnchorPolicy);
		}

		/// <summary>
		///     <para xml:lang="en">Removes the first capability of type <typeparamref name="TCapability" />.</para>
		///     <para xml:lang="zh-CN">移除第一个 <typeparamref name="TCapability" /> 类型能力。</para>
		/// </summary>
		public TCapability? Remove<TCapability>() where TCapability : class, IModelCapability
		{
			int num = _capabilities.FindIndex((IModelCapability capability) => capability is TCapability);
			if (num < 0)
			{
				return null;
			}
			TCapability result = (TCapability)_capabilities[num];
			_capabilities.RemoveAt(num);
			return result;
		}

		/// <summary>
		///     <para xml:lang="en">Removes every capability of type <typeparamref name="TCapability" />.</para>
		///     <para xml:lang="zh-CN">移除所有 <typeparamref name="TCapability" /> 类型能力。</para>
		/// </summary>
		public IReadOnlyList<TCapability> RemoveAll<TCapability>() where TCapability : class, IModelCapability
		{
			List<TCapability> list = new List<TCapability>();
			for (int num = _capabilities.Count - 1; num >= 0; num--)
			{
				if (_capabilities[num] is TCapability item)
				{
					_capabilities.RemoveAt(num);
					list.Add(item);
				}
			}
			list.Reverse();
			return list;
		}

		/// <summary>
		///     <para xml:lang="en">Replaces the first capability of type <typeparamref name="TCapability" />.</para>
		///     <para xml:lang="zh-CN">替换第一个 <typeparamref name="TCapability" /> 类型能力。</para>
		/// </summary>
		public bool Replace<TCapability>(IModelCapability replacement) where TCapability : class, IModelCapability
		{
			ValidateCapability(replacement);
			int index = _capabilities.FindIndex((IModelCapability capability) => capability is TCapability);
			if (index < 0)
			{
				return false;
			}
			if (_capabilities.Where((IModelCapability _, int candidateIndex) => candidateIndex != index).Any((IModelCapability candidate) => candidate == replacement))
			{
				throw new InvalidOperationException("The same capability instance cannot appear more than once: " + replacement.CapabilityId);
			}
			_capabilities[index] = replacement;
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Gets the first capability of type <typeparamref name="TCapability" />.</para>
		///     <para xml:lang="zh-CN">获取第一个 <typeparamref name="TCapability" /> 类型能力。</para>
		/// </summary>
		public TCapability? Get<TCapability>() where TCapability : class, IModelCapability
		{
			return _capabilities.OfType<TCapability>().FirstOrDefault();
		}

		/// <summary>
		///     <para xml:lang="en">Gets all capabilities of type <typeparamref name="TCapability" />.</para>
		///     <para xml:lang="zh-CN">获取所有 <typeparamref name="TCapability" /> 类型能力。</para>
		/// </summary>
		public IReadOnlyList<TCapability> GetAll<TCapability>() where TCapability : class, IModelCapability
		{
			List<TCapability> list = new List<TCapability>();
			list.AddRange(_capabilities.OfType<TCapability>());
			return new <>z__ReadOnlyList<TCapability>(list);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns <see langword="true" /> when the list contains a capability of type
		///         <typeparamref name="TCapability" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若列表包含 <typeparamref name="TCapability" /> 类型的能力，则为 <see langword="true" />；
		///         否则为 <see langword="false" />。
		///     </para>
		/// </summary>
		public bool Contains<TCapability>() where TCapability : class, IModelCapability
		{
			return _capabilities.Any((IModelCapability capability) => capability is TCapability);
		}

		private IModelCapability? InsertRelativeTo<TExisting>(IModelCapability capability, bool after, MissingModelCapabilityAnchorPolicy missingAnchorPolicy) where TExisting : class, IModelCapability
		{
			ArgumentNullException.ThrowIfNull(capability, "capability");
			int num = _capabilities.FindIndex((IModelCapability existing) => existing is TExisting);
			if (num >= 0)
			{
				return Insert(after ? (num + 1) : num, capability);
			}
			return missingAnchorPolicy switch
			{
				MissingModelCapabilityAnchorPolicy.Append => Insert(_capabilities.Count, capability), 
				MissingModelCapabilityAnchorPolicy.Prepend => Insert(0, capability), 
				MissingModelCapabilityAnchorPolicy.Skip => null, 
				MissingModelCapabilityAnchorPolicy.Throw => throw new InvalidOperationException("Cannot find capability anchor '" + typeof(TExisting).FullName + "' in the default capability list."), 
				_ => throw new ArgumentOutOfRangeException("missingAnchorPolicy", missingAnchorPolicy, "Unknown missing anchor policy."), 
			};
		}

		internal IModelCapability[] ToArray()
		{
			return _capabilities.ToArray();
		}

		internal void Restore(IReadOnlyList<IModelCapability> capabilities)
		{
			_capabilities.Clear();
			_capabilities.AddRange(capabilities);
		}

		private void EnsureInstanceNotPresent(IModelCapability capability)
		{
			if (_capabilities.Any((IModelCapability existing) => existing == capability))
			{
				throw new InvalidOperationException("The same capability instance cannot appear more than once: " + capability.CapabilityId);
			}
		}

		private static void ValidateCapability(IModelCapability capability)
		{
			ArgumentNullException.ThrowIfNull(capability, "capability");
			if (capability.Owner != null)
			{
				throw new InvalidOperationException($"Capability '{capability.CapabilityId}' is already attached to model '{capability.Owner.Id}'.");
			}
			if (capability is ModelCapability && ModelCapabilityRegistry.GetCapabilityId(capability.GetType()) == null)
			{
				throw new InvalidOperationException("Model-backed capability type is not registered: " + capability.GetType().FullName + ". Register it with RegisterModelCapability and add it by type instead of passing a constructed instance.");
			}
		}
	}
	internal static class ModelCapabilityDefaults
	{
		private readonly record struct ModelDefaultCapabilityModifierEntry(string ModId, string ModifierId, Type OwnerType, int Order, long RegistrationOrder, Action<AbstractModel, ModelCapabilityList> Modify);

		private static readonly Lock SyncRoot = new Lock();

		private static readonly List<ModelDefaultCapabilityModifierEntry> Modifiers = new List<ModelDefaultCapabilityModifierEntry>();

		private static Dictionary<Type, ModelDefaultCapabilityModifierEntry[]> _modifiersByOwnerType = new Dictionary<Type, ModelDefaultCapabilityModifierEntry[]>();

		private static long _nextOrder;

		public static void Modify<TModel>(string modId, string modifierId, Action<TModel, ModelCapabilityList> modifier, int order = 0) where TModel : AbstractModel
		{
			ArgumentNullException.ThrowIfNull(modifier, "modifier");
			Modify(modId, modifierId, typeof(TModel), delegate(AbstractModel model, ModelCapabilityList capabilities)
			{
				modifier((TModel)(object)model, capabilities);
			}, order);
		}

		public static void Modify(string modId, string modifierId, Type ownerType, Action<AbstractModel, ModelCapabilityList> modifier, int order = 0)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(modifierId, "modifierId");
			ArgumentNullException.ThrowIfNull(ownerType, "ownerType");
			ArgumentNullException.ThrowIfNull(modifier, "modifier");
			if (ownerType.ContainsGenericParameters || ownerType.IsInterface || !typeof(AbstractModel).IsAssignableFrom(ownerType))
			{
				throw new ArgumentException("Type '" + ownerType.FullName + "' must be an abstract model type or a concrete model type.", "ownerType");
			}
			using (SyncRoot.EnterScope())
			{
				if (Modifiers.Any((ModelDefaultCapabilityModifierEntry entry) => string.Equals(entry.ModId, modId, StringComparison.OrdinalIgnoreCase) && string.Equals(entry.ModifierId, modifierId, StringComparison.Ordinal)))
				{
					throw new InvalidOperationException("Default capability modifier is already registered: " + modId + "/" + modifierId);
				}
				Modifiers.Add(new ModelDefaultCapabilityModifierEntry(modId, modifierId, ownerType, order, _nextOrder++, modifier));
				Volatile.Write(ref _modifiersByOwnerType, new Dictionary<Type, ModelDefaultCapabilityModifierEntry[]>());
			}
			ModelCapabilityHookListeners.InvalidateDefaultCapabilitySourceCache();
		}

		internal static bool HasDefaultCapabilitySource(AbstractModel owner)
		{
			ArgumentNullException.ThrowIfNull(owner, "owner");
			if (owner is IModelCapabilitySource)
			{
				return true;
			}
			return GetModifiers(((object)owner).GetType()).Length != 0;
		}

		internal static IReadOnlyList<IModelCapability> Create(AbstractModel owner)
		{
			ArgumentNullException.ThrowIfNull(owner, "owner");
			ModelCapabilityList modelCapabilityList = new ModelCapabilityList();
			if (owner is IModelCapabilitySource provider)
			{
				RunProvider(provider, modelCapabilityList);
			}
			ModelDefaultCapabilityModifierEntry[] modifiers = GetModifiers(owner);
			foreach (ModelDefaultCapabilityModifierEntry modifier in modifiers)
			{
				RunModifier(owner, modifier, modelCapabilityList);
			}
			return modelCapabilityList.ToArray();
		}

		private static ModelDefaultCapabilityModifierEntry[] GetModifiers(AbstractModel owner)
		{
			return GetModifiers(((object)owner).GetType());
		}

		private static ModelDefaultCapabilityModifierEntry[] GetModifiers(Type ownerType)
		{
			Dictionary<Type, ModelDefaultCapabilityModifierEntry[]> dictionary = Volatile.Read(in _modifiersByOwnerType);
			if (dictionary.TryGetValue(ownerType, out var value))
			{
				return value;
			}
			using (SyncRoot.EnterScope())
			{
				dictionary = Volatile.Read(in _modifiersByOwnerType);
				if (dictionary.TryGetValue(ownerType, out value))
				{
					return value;
				}
				value = (from entry in Modifiers
					where entry.OwnerType.IsAssignableFrom(ownerType)
					orderby entry.Order, entry.RegistrationOrder
					select entry).ToArray();
				Dictionary<Type, ModelDefaultCapabilityModifierEntry[]> value2 = new Dictionary<Type, ModelDefaultCapabilityModifierEntry[]>(dictionary) { [ownerType] = value };
				Volatile.Write(ref _modifiersByOwnerType, value2);
				return value;
			}
		}

		private static void RunProvider(IModelCapabilitySource provider, ModelCapabilityList capabilities)
		{
			IModelCapability[] capabilities2 = capabilities.ToArray();
			try
			{
				provider.BuildDefaultCapabilities(capabilities);
			}
			catch
			{
				capabilities.Restore(capabilities2);
				throw;
			}
		}

		private static void RunModifier(AbstractModel owner, ModelDefaultCapabilityModifierEntry modifier, ModelCapabilityList capabilities)
		{
			IModelCapability[] capabilities2 = capabilities.ToArray();
			try
			{
				modifier.Modify(owner, capabilities);
			}
			catch
			{
				capabilities.Restore(capabilities2);
				throw;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Controls optional model capability diagnostic logging.</para>
	///     <para xml:lang="zh-CN">控制可选的模型能力诊断日志。</para>
	/// </summary>
	public enum ModelCapabilityConflictLogMode
	{
		/// <summary>
		///     <para xml:lang="en">Does not log conflicts between capability-provided values.</para>
		///     <para xml:lang="zh-CN">不记录能力所提供值之间的冲突。</para>
		/// </summary>
		Off,
		/// <summary>
		///     <para xml:lang="en">Logs each distinct conflict once.</para>
		///     <para xml:lang="zh-CN">每个不同冲突只记录一次。</para>
		/// </summary>
		WarnOnce,
		/// <summary>
		///     <para xml:lang="en">Logs every observed conflict.</para>
		///     <para xml:lang="zh-CN">每次观察到冲突都记录。</para>
		/// </summary>
		WarnEveryTime
	}
	/// <summary>
	///     <para xml:lang="en">Runtime diagnostics for model capabilities.</para>
	///     <para xml:lang="zh-CN">模型能力运行时诊断。</para>
	/// </summary>
	public static class ModelCapabilityDiagnostics
	{
		private static readonly Lock ConflictGate = new Lock();

		private static readonly HashSet<string> SeenConflicts = new HashSet<string>(StringComparer.Ordinal);

		/// <summary>
		///     <para xml:lang="en">
		///         Optional conflict logging for single-winner values such as card type, rarity, target type, and
		///         result pile. Defaults to <see cref="F:STS2RitsuLib.Models.Capabilities.ModelCapabilityConflictLogMode.Off" /> to avoid hot-path log spam.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选择记录卡牌类型、稀有度、目标类型及结果牌堆等仅采用一个值的冲突。
		///         默认为关闭，以免热路径产生大量日志。
		///     </para>
		/// </summary>
		public static ModelCapabilityConflictLogMode ConflictLogs { get; set; } = ModelCapabilityConflictLogMode.Off;

		internal static bool ShouldInspectConflicts => ConflictLogs != ModelCapabilityConflictLogMode.Off;

		/// <summary>
		///     <para xml:lang="en">
		///         Clears the cache of conflicts already logged by
		///         <see cref="F:STS2RitsuLib.Models.Capabilities.ModelCapabilityConflictLogMode.WarnOnce" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         清空 <see cref="F:STS2RitsuLib.Models.Capabilities.ModelCapabilityConflictLogMode.WarnOnce" /> 已记录冲突的缓存。
		///     </para>
		/// </summary>
		public static void ClearConflictLogCache()
		{
			using (ConflictGate.EnterScope())
			{
				SeenConflicts.Clear();
			}
		}

		internal static void WarnFailure(string surface, AbstractModel model, object source, Exception exception)
		{
			RitsuLibFramework.Logger.Warn($"[ModelCapabilities] Surface='{surface}' failed. {FormatModel(model)} {FormatSource(source)} Error='{exception.Message}'", 1);
		}

		internal static void WarnSurfaceConflict(string surface, AbstractModel model, object winningSource, object? winningValue, object ignoredSource, object? ignoredValue)
		{
			if (ConflictLogs == ModelCapabilityConflictLogMode.Off)
			{
				return;
			}
			<>y__InlineArray7<object> buffer = default(<>y__InlineArray7<object>);
			buffer[0] = surface;
			buffer[1] = ((object)model).GetType().FullName;
			buffer[2] = model.Id;
			buffer[3] = FormatSourceKey(winningSource);
			buffer[4] = FormatSourceKey(ignoredSource);
			buffer[5] = winningValue?.ToString() ?? "<null>";
			buffer[6] = ignoredValue?.ToString() ?? "<null>";
			string item = string.Join("|", (ReadOnlySpan<object?>)buffer);
			if (ConflictLogs == ModelCapabilityConflictLogMode.WarnOnce)
			{
				using (ConflictGate.EnterScope())
				{
					if (!SeenConflicts.Add(item))
					{
						return;
					}
				}
			}
			RitsuLibFramework.Logger.Warn($"[ModelCapabilities] Surface='{surface}' conflict. {FormatModel(model)} First=({FormatSource(winningSource)}, Value='{winningValue}') Later=({FormatSource(ignoredSource)}, Value='{ignoredValue}')", 1);
		}

		private static string FormatModel(AbstractModel model)
		{
			return $"ModelId='{model.Id}' OwnerType='{((object)model).GetType().FullName}'";
		}

		private static string FormatSource(object source)
		{
			if (source is IModelCapability modelCapability)
			{
				return $"CapabilityId='{modelCapability.CapabilityId}' CapabilityType='{source.GetType().FullName}'";
			}
			return "SourceType='" + source.GetType().FullName + "'";
		}

		private static string FormatSourceKey(object source)
		{
			string text;
			if (!(source is IModelCapability modelCapability))
			{
				text = source.GetType().FullName;
				if (text == null)
				{
					return "<unknown>";
				}
			}
			else
			{
				text = modelCapability.CapabilityId + ":" + source.GetType().FullName;
			}
			return text;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Opt-in contract for model-backed capabilities that should receive the owner's vanilla model hook callbacks.
	///         Gameplay-affecting multiplayer logic should use this path because vanilla hooks await model callbacks.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         基于模型的能力可实现此契约，以接收所属模型的游戏原版模型钩子回调。
	///         影响多人同步的游戏逻辑应使用此路径，因为游戏原版钩子会等待模型回调完成。
	///     </para>
	/// </summary>
	public interface IModelCapabilityHookListener
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Whether this capability should be inserted into the owning model's vanilla hook listener
		///         stream.
		///     </para>
		///     <para xml:lang="zh-CN">获取此能力是否应插入所属模型的游戏原版钩子监听器流。</para>
		/// </summary>
		bool ShouldReceiveOwnerHooks => true;

		/// <summary>
		///     <para xml:lang="en">
		///         Ordering relative to the owner. Negative values run before the owner, zero and positive values
		///         after.
		///     </para>
		///     <para xml:lang="zh-CN">相对所属模型的顺序。负值先于所属模型运行，零和正值在其后运行。</para>
		/// </summary>
		int OwnerHookOrder => 0;
	}
	internal static class ModelCapabilityHookListeners
	{
		private readonly record struct OwnerHookCapabilityEntry(IModelCapability Capability, AbstractModel Model, int OwnerHookOrder, int Index);

		private readonly struct OwnerHookCapabilitySnapshot
		{
			private readonly OwnerHookCapabilityEntry? _single;

			private readonly List<OwnerHookCapabilityEntry>? _multiple;

			public int Count => _multiple?.Count ?? (_single.HasValue ? 1 : 0);

			public OwnerHookCapabilityEntry this[int index]
			{
				get
				{
					if (_multiple != null)
					{
						return _multiple[index];
					}
					if (index == 0)
					{
						OwnerHookCapabilityEntry? single = _single;
						if (single.HasValue)
						{
							return single.GetValueOrDefault();
						}
					}
					throw new ArgumentOutOfRangeException("index");
				}
			}

			public OwnerHookCapabilitySnapshot(OwnerHookCapabilityEntry? single)
			{
				_single = single;
				_multiple = null;
			}

			public OwnerHookCapabilitySnapshot(List<OwnerHookCapabilityEntry> multiple)
			{
				_single = null;
				_multiple = multiple;
			}
		}

		private static readonly object NoOwnerHookCapabilitiesMarker = new object();

		private static readonly ConditionalWeakTable<AbstractModel, object> OwnersWithoutHookCapabilities = new ConditionalWeakTable<AbstractModel, object>();

		internal static void InvalidateDefaultCapabilitySourceCache()
		{
			OwnersWithoutHookCapabilities.Clear();
		}

		internal static void InvalidateOwnerHookCapabilityCache(AbstractModel owner)
		{
			OwnersWithoutHookCapabilities.Remove(owner);
		}

		internal static IEnumerable<AbstractModel> ExpandOwnerHookListeners(IEnumerable<AbstractModel> owners)
		{
			foreach (AbstractModel owner in owners)
			{
				if (owner is IModelCapability modelCapability)
				{
					if (modelCapability.Owner == null)
					{
						yield return owner;
					}
					continue;
				}
				if (OwnersWithoutHookCapabilities.TryGetValue(owner, out object _))
				{
					yield return owner;
					continue;
				}
				OwnerHookCapabilitySnapshot capabilities = GetOwnerHookCapabilities(owner);
				int index;
				for (index = 0; index < capabilities.Count && capabilities[index].OwnerHookOrder < 0; index++)
				{
					if (TryGetStillAttachedModel(capabilities[index], owner, out AbstractModel model))
					{
						yield return model;
					}
				}
				yield return owner;
				for (; index < capabilities.Count; index++)
				{
					if (TryGetStillAttachedModel(capabilities[index], owner, out AbstractModel model2))
					{
						yield return model2;
					}
				}
			}
		}

		private static OwnerHookCapabilitySnapshot GetOwnerHookCapabilities(AbstractModel owner)
		{
			if (!ModelCapabilities.TryGet(owner, out ModelCapabilitySet collection))
			{
				if (!ModelCapabilityDefaults.HasDefaultCapabilitySource(owner))
				{
					MarkOwnerWithoutHookCapabilities(owner);
					return default(OwnerHookCapabilitySnapshot);
				}
				collection = ModelCapabilities.Get(owner);
			}
			IModelCapability[] ownerHookCandidateSnapshot = collection.GetOwnerHookCandidateSnapshot();
			if (ownerHookCandidateSnapshot.Length == 0)
			{
				MarkOwnerWithoutHookCapabilities(owner);
				return default(OwnerHookCapabilitySnapshot);
			}
			OwnerHookCapabilityEntry? single = null;
			List<OwnerHookCapabilityEntry> list = null;
			for (int i = 0; i < ownerHookCandidateSnapshot.Length; i++)
			{
				IModelCapability modelCapability = ownerHookCandidateSnapshot[i];
				if (!(modelCapability is IModelCapabilityHookListener { ShouldReceiveOwnerHooks: not false } modelCapabilityHookListener))
				{
					continue;
				}
				AbstractModel val = (AbstractModel)((modelCapabilityHookListener is AbstractModel) ? modelCapabilityHookListener : null);
				if (val == null)
				{
					continue;
				}
				OwnerHookCapabilityEntry ownerHookCapabilityEntry = new OwnerHookCapabilityEntry(modelCapability, val, modelCapabilityHookListener.OwnerHookOrder, i);
				if (!single.HasValue)
				{
					single = ownerHookCapabilityEntry;
					continue;
				}
				if (list == null)
				{
					list = new List<OwnerHookCapabilityEntry>(ownerHookCandidateSnapshot.Length) { single.Value };
				}
				list.Add(ownerHookCapabilityEntry);
			}
			if (list == null)
			{
				return new OwnerHookCapabilitySnapshot(single);
			}
			list.Sort(delegate(OwnerHookCapabilityEntry left, OwnerHookCapabilityEntry right)
			{
				int num = left.OwnerHookOrder.CompareTo(right.OwnerHookOrder);
				return (num == 0) ? left.Index.CompareTo(right.Index) : num;
			});
			return new OwnerHookCapabilitySnapshot(list);
		}

		private static void MarkOwnerWithoutHookCapabilities(AbstractModel owner)
		{
			OwnersWithoutHookCapabilities.GetValue(owner, (AbstractModel _) => NoOwnerHookCapabilitiesMarker);
		}

		private static bool TryGetStillAttachedModel(OwnerHookCapabilityEntry entry, AbstractModel owner, out AbstractModel model)
		{
			model = entry.Model;
			return entry.Capability.Owner == owner;
		}
	}
	internal readonly record struct ModelCapabilityRegistration(string Id, Type CapabilityType);
	/// <summary>
	///     <para xml:lang="en">Registry for capability ids and factories.</para>
	///     <para xml:lang="zh-CN">能力 ID 与工厂的注册表。</para>
	/// </summary>
	public static class ModelCapabilityRegistry
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, Func<IModelCapability>> Factories = new Dictionary<string, Func<IModelCapability>>(StringComparer.Ordinal);

		private static readonly Dictionary<string, Type> TypesById = new Dictionary<string, Type>(StringComparer.Ordinal);

		private static readonly Dictionary<Type, string> TypeIds = new Dictionary<Type, string>();

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a capability factory.</para>
		///     <para xml:lang="zh-CN">注册或替换能力工厂。</para>
		/// </summary>
		public static void Register(string capabilityId, Type capabilityType, Func<IModelCapability> factory)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(capabilityId, "capabilityId");
			ArgumentNullException.ThrowIfNull(capabilityType, "capabilityType");
			ArgumentNullException.ThrowIfNull(factory, "factory");
			if (capabilityType.ContainsGenericParameters || !typeof(IModelCapability).IsAssignableFrom(capabilityType))
			{
				throw new ArgumentException("Capability type must be closed and implement IModelCapability.", "capabilityType");
			}
			using (SyncRoot.EnterScope())
			{
				if (TypesById.TryGetValue(capabilityId, out Type value) && value != capabilityType)
				{
					throw new InvalidOperationException("Model capability id is already registered for '" + value.FullName + "': " + capabilityId);
				}
				if (TypeIds.TryGetValue(capabilityType, out string value2) && !string.Equals(value2, capabilityId, StringComparison.Ordinal))
				{
					throw new InvalidOperationException("Model capability id is already registered: " + capabilityId);
				}
				Factories[capabilityId] = factory;
				TypesById[capabilityId] = capabilityType;
				TypeIds[capabilityType] = capabilityId;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers a capability factory.</para>
		///     <para xml:lang="zh-CN">注册能力工厂。</para>
		/// </summary>
		public static void Register<TCapability>(string capabilityId, Func<TCapability> factory) where TCapability : IModelCapability
		{
			ArgumentNullException.ThrowIfNull(factory, "factory");
			Register(capabilityId, typeof(TCapability), () => factory());
		}

		/// <summary>
		///     <para xml:lang="en">Registers a parameterless capability factory.</para>
		///     <para xml:lang="zh-CN">注册无参能力工厂。</para>
		/// </summary>
		public static void Register<TCapability>(string capabilityId) where TCapability : IModelCapability, new()
		{
			Register(capabilityId, () => new TCapability());
		}

		/// <summary>
		///     <para xml:lang="en">Creates a capability by ID.</para>
		///     <para xml:lang="zh-CN">通过 ID 创建能力。</para>
		/// </summary>
		public static bool TryCreate(string capabilityId, out IModelCapability capability)
		{
			Func<IModelCapability> value;
			Type value2;
			using (SyncRoot.EnterScope())
			{
				if (!Factories.TryGetValue(capabilityId, out value) || !TypesById.TryGetValue(capabilityId, out value2))
				{
					capability = null;
					return false;
				}
			}
			capability = value() ?? throw new InvalidOperationException("Model capability factory returned null: " + capabilityId);
			if (!value2.IsInstanceOfType(capability))
			{
				throw new InvalidOperationException($"Model capability factory for '{capabilityId}' returned '{capability.GetType().FullName}', which is not assignable to '{value2.FullName}'.");
			}
			if (!string.Equals(capability.CapabilityId, capabilityId, StringComparison.Ordinal))
			{
				throw new InvalidOperationException($"Model capability factory for '{capabilityId}' returned a capability with id '{capability.CapabilityId}'.");
			}
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Creates a capability by registered type, if a matching factory exists.</para>
		///     <para xml:lang="zh-CN">按已注册类型创建能力（如果存在匹配工厂）。</para>
		/// </summary>
		public static bool TryCreate<TCapability>(out TCapability capability) where TCapability : class, IModelCapability
		{
			string capabilityId = GetCapabilityId<TCapability>();
			if (capabilityId == null || !TryCreate(capabilityId, out IModelCapability capability2) || !(capability2 is TCapability val))
			{
				capability = null;
				return false;
			}
			capability = val;
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Creates a capability by ID or throws when no factory is registered.</para>
		///     <para xml:lang="zh-CN">通过 ID 创建能力；未注册工厂时抛出异常。</para>
		/// </summary>
		public static IModelCapability Create(string capabilityId)
		{
			if (!TryCreate(capabilityId, out IModelCapability capability))
			{
				throw new InvalidOperationException("Model capability id is not registered: " + capabilityId);
			}
			return capability;
		}

		/// <summary>
		///     <para xml:lang="en">Creates a capability by registered type or throws when no matching factory is registered.</para>
		///     <para xml:lang="zh-CN">按已注册类型创建能力；未注册匹配工厂时抛出异常。</para>
		/// </summary>
		public static TCapability Create<TCapability>() where TCapability : class, IModelCapability
		{
			string capabilityId = GetCapabilityId<TCapability>();
			if (capabilityId == null)
			{
				throw new InvalidOperationException("Model capability type is not registered: " + typeof(TCapability).FullName);
			}
			return (Create(capabilityId) as TCapability) ?? throw new InvalidOperationException($"Registered capability '{capabilityId}' is not a '{typeof(TCapability).FullName}'.");
		}

		/// <summary>
		///     <para xml:lang="en">Gets the registered capability ID for a capability type, if any.</para>
		///     <para xml:lang="zh-CN">获取能力类型已注册的能力 ID（如果存在）。</para>
		/// </summary>
		public static string? GetCapabilityId(Type capabilityType)
		{
			ArgumentNullException.ThrowIfNull(capabilityType, "capabilityType");
			using (SyncRoot.EnterScope())
			{
				return TypeIds.GetValueOrDefault(capabilityType);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets the registered capability ID for <typeparamref name="TCapability" />, if any.</para>
		///     <para xml:lang="zh-CN">获取 <typeparamref name="TCapability" /> 已注册的能力 ID（如果存在）。</para>
		/// </summary>
		public static string? GetCapabilityId<TCapability>() where TCapability : IModelCapability
		{
			return GetCapabilityId(typeof(TCapability));
		}

		/// <summary>
		///     <para xml:lang="en">Attempts to resolve the capability type registered for <paramref name="capabilityId" />.</para>
		///     <para xml:lang="zh-CN">尝试解析 <paramref name="capabilityId" /> 注册的能力类型。</para>
		/// </summary>
		public static bool TryGetCapabilityType(string capabilityId, out Type capabilityType)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(capabilityId, "capabilityId");
			using (SyncRoot.EnterScope())
			{
				return TypesById.TryGetValue(capabilityId, out capabilityType);
			}
		}

		internal static IReadOnlyList<ModelCapabilityRegistration> GetRegistrationsSnapshot()
		{
			using (SyncRoot.EnterScope())
			{
				return Array.AsReadOnly(TypesById.Select<KeyValuePair<string, Type>, ModelCapabilityRegistration>((KeyValuePair<string, Type> pair) => new ModelCapabilityRegistration(pair.Key, pair.Value)).OrderBy<ModelCapabilityRegistration, string>((ModelCapabilityRegistration registration) => registration.Id, StringComparer.Ordinal).ToArray());
			}
		}

		internal static bool IsCompatibleWith(Type capabilityType, AbstractModel owner)
		{
			ArgumentNullException.ThrowIfNull(capabilityType, "capabilityType");
			ArgumentNullException.ThrowIfNull(owner, "owner");
			Type[] array = (from candidate in capabilityType.GetInterfaces()
				where candidate.IsGenericType && candidate.GetGenericTypeDefinition() == typeof(IModelCapability<>)
				select candidate.GetGenericArguments()[0]).Distinct().ToArray();
			if (array.Length != 0)
			{
				return array.Any((Type ownerType) => ownerType.IsInstanceOfType(owner));
			}
			return true;
		}

		internal static void RegisterModelCapability(Type capabilityType, string capabilityId)
		{
			if (!typeof(ModelCapability).IsAssignableFrom(capabilityType))
			{
				throw new ArgumentException("Capability type must inherit ModelCapability.", "capabilityType");
			}
			Register(capabilityId, capabilityType, () => (IModelCapability)ModelDb.Get(capabilityType).MutableClone());
		}

		internal static string GetModelCapabilityId(Type capabilityType)
		{
			return GetCapabilityId(capabilityType) ?? throw new InvalidOperationException("Model capability type is not registered: " + capabilityType.FullName);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Represents a serializable document of model capabilities.</para>
	///     <para xml:lang="zh-CN">表示模型能力的可序列化文档。</para>
	/// </summary>
	public sealed class ModelCapabilitySaveDocument
	{
		/// <summary>
		///     <para xml:lang="en">Gets or sets capability entries in display and execution order.</para>
		///     <para xml:lang="zh-CN">获取或设置按显示与执行顺序排列的能力条目。</para>
		/// </summary>
		public List<ModelCapabilitySaveEntry> Capabilities { get; set; } = new List<ModelCapabilitySaveEntry>();
	}
	/// <summary>
	///     <para xml:lang="en">Represents the serializable state of one model capability.</para>
	///     <para xml:lang="zh-CN">表示单个模型能力的可序列化状态。</para>
	/// </summary>
	public sealed class ModelCapabilitySaveEntry
	{
		/// <summary>
		///     <para xml:lang="en">Gets or sets the stable capability ID.</para>
		///     <para xml:lang="zh-CN">获取或设置稳定的能力 ID。</para>
		/// </summary>
		public string Id { get; set; } = "";

		/// <summary>
		///     <para xml:lang="en">Gets or sets the capability-state schema version.</para>
		///     <para xml:lang="zh-CN">获取或设置能力状态的架构版本。</para>
		/// </summary>
		public int Schema { get; set; } = 1;

		/// <summary>
		///     <para xml:lang="en">Gets or sets the serialized capability state.</para>
		///     <para xml:lang="zh-CN">获取或设置序列化后的能力状态。</para>
		/// </summary>
		public JsonNode? Data { get; set; }
	}
	/// <summary>
	///     <para xml:lang="en">Represents the mutable capability set attached to one model instance.</para>
	///     <para xml:lang="zh-CN">表示附加到单个模型实例的可变能力集合。</para>
	/// </summary>
	public sealed class ModelCapabilitySet
	{
		private readonly record struct CapabilityLoadItem(IModelCapability Capability, bool IsDefault);

		private sealed class CapabilityLoadState
		{
			private readonly Dictionary<string, Queue<CapabilityLoadItem>> _queues = new Dictionary<string, Queue<CapabilityLoadItem>>(StringComparer.Ordinal);

			private readonly List<CapabilityLoadItem> _remaining = new List<CapabilityLoadItem>();

			public void Add(IModelCapability capability, bool isDefault)
			{
				CapabilityLoadItem item = new CapabilityLoadItem(capability, isDefault);
				_remaining.Add(item);
				if (!_queues.TryGetValue(capability.CapabilityId, out Queue<CapabilityLoadItem> value))
				{
					value = new Queue<CapabilityLoadItem>();
					_queues[capability.CapabilityId] = value;
				}
				value.Enqueue(item);
			}

			public bool TryTake(string capabilityId, out CapabilityLoadItem item)
			{
				item = default(CapabilityLoadItem);
				if (!_queues.TryGetValue(capabilityId, out Queue<CapabilityLoadItem> value) || value.Count == 0)
				{
					return false;
				}
				item = value.Dequeue();
				IModelCapability capability = item.Capability;
				int num = _remaining.FindIndex((CapabilityLoadItem candidate) => candidate.Capability == capability);
				if (num >= 0)
				{
					_remaining.RemoveAt(num);
				}
				return true;
			}

			public IReadOnlyList<CapabilityLoadItem> TakeRemaining()
			{
				CapabilityLoadItem[] result = _remaining.ToArray();
				_remaining.Clear();
				foreach (Queue<CapabilityLoadItem> value in _queues.Values)
				{
					value.Clear();
				}
				return result;
			}
		}

		private const string LoadSurface = "model-capability-load";

		private readonly List<IModelCapability> _capabilities = new List<IModelCapability>();

		private readonly HashSet<IModelCapability> _defaultCapabilities = new HashSet<IModelCapability>(ReferenceEqualityComparer.Instance);

		private readonly ReadOnlyCollection<IModelCapability> _readOnlyCapabilities;

		private readonly List<ModelCapabilitySaveEntry> _unknownEntries = new List<ModelCapabilitySaveEntry>();

		private IModelCapability[]? _attachedSnapshot;

		private IModelCapability[]? _ownerHookCandidateSnapshot;

		/// <summary>
		///     <para xml:lang="en">Gets the owning model.</para>
		///     <para xml:lang="zh-CN">获取所属模型。</para>
		/// </summary>
		public AbstractModel Owner { get; }

		/// <summary>
		///     <para xml:lang="en">Gets all attached capabilities in execution order.</para>
		///     <para xml:lang="zh-CN">获取按执行顺序排列的所有已附加能力。</para>
		/// </summary>
		public IReadOnlyList<IModelCapability> All => _readOnlyCapabilities;

		/// <summary>
		///     <para xml:lang="en">Gets all attached capabilities in execution order.</para>
		///     <para xml:lang="zh-CN">获取按执行顺序排列的所有已附加能力。</para>
		/// </summary>
		public IReadOnlyList<IModelCapability> Attached => _readOnlyCapabilities;

		internal bool IsDirty { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Gets the number of currently attached capabilities.</para>
		///     <para xml:lang="zh-CN">获取当前已附加能力的数量。</para>
		/// </summary>
		public int Count => _capabilities.Count;

		internal ModelCapabilitySet(AbstractModel owner)
		{
			Owner = owner;
			_readOnlyCapabilities = _capabilities.AsReadOnly();
		}

		internal IModelCapability[] GetAttachedSnapshot()
		{
			return _attachedSnapshot ?? (_attachedSnapshot = _capabilities.ToArray());
		}

		internal IModelCapability[] GetOwnerHookCandidateSnapshot()
		{
			return _ownerHookCandidateSnapshot ?? (_ownerHookCandidateSnapshot = _capabilities.Where((IModelCapability capability) => capability is IModelCapabilityHookListener modelCapabilityHookListener && modelCapabilityHookListener is AbstractModel).ToArray());
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Applies a capability, optionally merging it with an existing capability.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         应用能力，并可选择将其与已有能力合并。
		///     </para>
		/// </summary>
		public IModelCapability? Apply(IModelCapability incoming, ApplyModelCapabilityOptions options = default(ApplyModelCapabilityOptions))
		{
			ArgumentNullException.ThrowIfNull(incoming, "incoming");
			if (options.AllowMerge)
			{
				for (int i = 0; i < _capabilities.Count; i++)
				{
					IModelCapability modelCapability = _capabilities[i];
					if (modelCapability is IModelCapabilityMergeHandler modelCapabilityMergeHandler && (options.UseSubtractiveMerge ? modelCapabilityMergeHandler.TrySubtractiveMergeWith(incoming, options, out IModelCapability merged) : modelCapabilityMergeHandler.TryMergeWith(incoming, options, out merged)))
					{
						if (merged == modelCapability)
						{
							MarkDynamicVarsJustUpgraded(modelCapability, options);
							MarkDirty();
							return modelCapability;
						}
						if (merged != null)
						{
							EnsureCanAttach(merged);
						}
						string text = (_defaultCapabilities.Remove(modelCapability) ? modelCapability.CapabilityId : null);
						modelCapability.Detach();
						if (merged == null)
						{
							_capabilities.RemoveAt(i);
							InvalidateAttachedSnapshot();
							MarkDirty();
							return null;
						}
						_capabilities[i] = merged;
						InvalidateAttachedSnapshot();
						if (text != null && string.Equals(merged.CapabilityId, text, StringComparison.Ordinal))
						{
							_defaultCapabilities.Add(merged);
						}
						merged.Attach(Owner);
						MarkDynamicVarsJustUpgraded(merged, options);
						MarkDirty();
						return merged;
					}
				}
			}
			if (options.UseSubtractiveMerge)
			{
				return null;
			}
			EnsureCanAttach(incoming);
			_capabilities.Add(incoming);
			InvalidateAttachedSnapshot();
			incoming.Attach(Owner);
			MarkDynamicVarsJustUpgraded(incoming, options);
			MarkDirty();
			return incoming;
		}

		/// <summary>
		///     <para xml:lang="en">Applies a capability and returns the typed result.</para>
		///     <para xml:lang="zh-CN">应用能力并返回类型化结果。</para>
		/// </summary>
		public TCapability? Apply<TCapability>(TCapability incoming, ApplyModelCapabilityOptions options = default(ApplyModelCapabilityOptions)) where TCapability : class, IModelCapability
		{
			return Apply((IModelCapability)incoming, options) as TCapability;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Applies multiple capabilities in order. If a later operation throws, earlier applications remain.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         按顺序应用多个能力。后续操作抛出异常时，先前已应用的能力会保留。
		///     </para>
		/// </summary>
		public IReadOnlyList<IModelCapability?> ApplyRange(IEnumerable<IModelCapability> capabilities, ApplyModelCapabilityOptions options = default(ApplyModelCapabilityOptions))
		{
			ArgumentNullException.ThrowIfNull(capabilities, "capabilities");
			IModelCapability[] array = capabilities.ToArray();
			if (array.Any((IModelCapability capability) => capability == null))
			{
				throw new ArgumentException("Capability collection cannot contain null entries.", "capabilities");
			}
			if (array.Distinct(ReferenceEqualityComparer.Instance).Count() != array.Length)
			{
				throw new ArgumentException("Capability collection cannot contain the same instance more than once.", "capabilities");
			}
			List<IModelCapability> list = new List<IModelCapability>();
			list.AddRange(array.Select((IModelCapability capability) => Apply(capability, options)));
			return new <>z__ReadOnlyList<IModelCapability>(list);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Inserts <paramref name="capability" /> at <paramref name="index" /> without merging.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <paramref name="index" /> 插入 <paramref name="capability" />，不执行合并。
		///     </para>
		/// </summary>
		public IModelCapability Insert(int index, IModelCapability capability)
		{
			ArgumentNullException.ThrowIfNull(capability, "capability");
			EnsureCanAttach(capability);
			if (index < 0 || index > _capabilities.Count)
			{
				throw new ArgumentOutOfRangeException("index", index, "Index is outside the set bounds.");
			}
			_capabilities.Insert(index, capability);
			InvalidateAttachedSnapshot();
			capability.Attach(Owner);
			MarkDirty();
			return capability;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Inserts <paramref name="capability" /> at <paramref name="index" /> without merging and returns the
		///         typed capability.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <paramref name="index" /> 插入 <paramref name="capability" />，不执行合并，并返回类型化能力。
		///     </para>
		/// </summary>
		public TCapability Insert<TCapability>(int index, TCapability capability) where TCapability : class, IModelCapability
		{
			return (TCapability)Insert(index, (IModelCapability)capability);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Inserts <paramref name="capability" /> before the first attached <typeparamref name="TExisting" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将 <paramref name="capability" /> 插入到第一个已附加的 <typeparamref name="TExisting" /> 之前。
		///     </para>
		/// </summary>
		public IModelCapability? InsertBefore<TExisting>(IModelCapability capability, MissingModelCapabilityAnchorPolicy missingAnchorPolicy = MissingModelCapabilityAnchorPolicy.Append) where TExisting : class, IModelCapability
		{
			return InsertRelativeTo<TExisting>(capability, after: false, missingAnchorPolicy);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Inserts <paramref name="capability" /> after the first attached <typeparamref name="TExisting" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将 <paramref name="capability" /> 插入到第一个已附加的 <typeparamref name="TExisting" /> 之后。
		///     </para>
		/// </summary>
		public IModelCapability? InsertAfter<TExisting>(IModelCapability capability, MissingModelCapabilityAnchorPolicy missingAnchorPolicy = MissingModelCapabilityAnchorPolicy.Append) where TExisting : class, IModelCapability
		{
			return InsertRelativeTo<TExisting>(capability, after: true, missingAnchorPolicy);
		}

		/// <summary>
