		/// </summary>
		public TCapability? Remove<TCapability>() where TCapability : class, IModelCapability
		{
			int num = _capabilities.FindIndex((IModelCapability c) => c is TCapability);
			if (num < 0)
			{
				return null;
			}
			TCapability val = (TCapability)_capabilities[num];
			val.Detach();
			_capabilities.RemoveAt(num);
			InvalidateAttachedSnapshot();
			_defaultCapabilities.Remove(val);
			MarkDirty();
			return val;
		}

