		public bool Remove(IModelCapability capability)
		{
			ArgumentNullException.ThrowIfNull(capability, "capability");
			int num = _capabilities.FindIndex((IModelCapability c) => c == capability);
			if (num < 0)
			{
				return false;
			}
			_capabilities[num].Detach();
			_defaultCapabilities.Remove(_capabilities[num]);
			_capabilities.RemoveAt(num);
