	internal static class ModelCapabilityHost
	{
		private readonly record struct OrderedOrbHoverTipDescriptionFragment(string Text, int Order, int SourceIndex);

		private const string ModelHoverTipsSurface = "model display/hover-tips";

		private const string ModelAssetPathsSurface = "model asset/paths";

		private const string ModelDynamicVarsSurface = "model dynamic-var/add-to-loc-string";

		private const string OrbValueDisplaySurface = "orb display/value-labels";

		private const string OrbHoverTipDescriptionSurface = "orb display/hover-tip-description";

		private const string OrbPassiveTriggerSurface = "orb lifecycle/passive-triggered";

		private const string OrbBeforeTurnEndTriggerSurface = "orb lifecycle/before-turn-end-triggered";

		private const string OrbAfterTurnStartTriggerSurface = "orb lifecycle/after-turn-start-triggered";

		private const string OrbEvokeSurface = "orb lifecycle/evoked";

		internal static IEnumerable<IHoverTip> GetHoverTips<TModel>(TModel model) where TModel : AbstractModel
		{
			foreach (IModelCapability item in GetCapabilitySnapshot((AbstractModel)(object)model))
			{
				IModelHoverTipContributor modelHoverTipContributor = item as IModelHoverTipContributor;
				if (modelHoverTipContributor == null)
				{
					IModelHoverTipContributor<TModel> modelHoverTipContributor2 = item as IModelHoverTipContributor<TModel>;
					if (modelHoverTipContributor2 == null)
					{
						continue;
					}
					IReadOnlyList<IHoverTip> tips = Array.Empty<IHoverTip>();
					TryRun(item, (AbstractModel)(object)model, "model display/hover-tips", delegate
					{
						tips = modelHoverTipContributor2.GetHoverTips(model)?.ToArray() ?? Array.Empty<IHoverTip>();
					});
					foreach (IHoverTip item2 in tips)
					{
						yield return item2;
					}
					continue;
				}
				IReadOnlyList<IHoverTip> tips2 = Array.Empty<IHoverTip>();
				TryRun(item, (AbstractModel)(object)model, "model display/hover-tips", delegate
				{
					tips2 = modelHoverTipContributor.GetHoverTips((AbstractModel)(object)model)?.ToArray() ?? Array.Empty<IHoverTip>();
				});
				foreach (IHoverTip item3 in tips2)
				{
					yield return item3;
				}
			}
		}

		internal static IEnumerable<string> GetAssetPaths<TModel>(TModel model, ModelAssetPathContext context) where TModel : AbstractModel
		{
			foreach (IModelCapability item in GetCapabilitySnapshot((AbstractModel)(object)model))
			{
				IModelAssetPathContributor modelAssetPathContributor = item as IModelAssetPathContributor;
				if (modelAssetPathContributor == null)
				{
					IModelAssetPathContributor<TModel> modelAssetPathContributor2 = item as IModelAssetPathContributor<TModel>;
					if (modelAssetPathContributor2 == null)
					{
						continue;
					}
					IReadOnlyList<string> paths = Array.Empty<string>();
					TryRun(item, (AbstractModel)(object)model, "model asset/paths", delegate
					{
						paths = modelAssetPathContributor2.GetAssetPaths(model, context)?.ToArray() ?? Array.Empty<string>();
					});
					foreach (string item2 in paths)
					{
						yield return item2;
					}
					continue;
				}
				IReadOnlyList<string> paths2 = Array.Empty<string>();
				TryRun(item, (AbstractModel)(object)model, "model asset/paths", delegate
				{
					paths2 = modelAssetPathContributor.GetAssetPaths(context)?.ToArray() ?? Array.Empty<string>();
				});
				foreach (string item3 in paths2)
				{
					yield return item3;
				}
			}
		}

		internal static IEnumerable<TCapability> GetCapabilities<TCapability>(AbstractModel model) where TCapability : class
		{
			foreach (IModelCapability item in GetCapabilitySnapshot(model))
			{
				if (item is TCapability val)
				{
					yield return val;
				}
			}
		}

		internal static void AddDynamicVarsTo(AbstractModel model, LocString locString)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			ArgumentNullException.ThrowIfNull(locString, "locString");
			foreach (IModelCapability item in GetCapabilitySnapshot(model))
			{
				IModelDynamicVarContributor dynamicVarCapability = item as IModelDynamicVarContributor;
				if (dynamicVarCapability != null)
				{
					DynamicVarSet dynamicVars = null;
					TryRun(item, model, "model dynamic-var/add-to-loc-string", delegate
					{
						dynamicVars = dynamicVarCapability.GetDynamicVars(model);
					});
					if (dynamicVars != null)
					{
						AddDynamicVarsTo(model, item, dynamicVarCapability.LocStringVariableScope, dynamicVars, locString);
					}
				}
			}
		}

		internal static void AddDynamicVarsTo(AbstractModel model, IModelCapability capability, string? requestedScope, DynamicVarSet dynamicVars, LocString locString)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			ArgumentNullException.ThrowIfNull(capability, "capability");
			ArgumentNullException.ThrowIfNull(dynamicVars, "dynamicVars");
			ArgumentNullException.ThrowIfNull(locString, "locString");
			string energyPrefix = GetEnergyPrefix(model, locString);
			Dictionary<string, object> orCreateScopedVariables = GetOrCreateScopedVariables(locString, capability.CapabilityId, requestedScope);
			foreach (DynamicVar value in dynamicVars.Values)
			{
				EnergyVar val = (EnergyVar)(object)((value is EnergyVar) ? value : null);
				if (val != null && energyPrefix != null)
				{
					val.ColorPrefix = energyPrefix;
				}
				string variableName = ModelCapabilityDynamicVarNames.GetVariableName(value.Name);
				orCreateScopedVariables?.TryAdd(variableName, value);
				string key = value.Name.Replace(' ', '-');
				if (!locString.Variables.ContainsKey(key))
				{
					locString.Add(value);
				}
			}
		}

		private static Dictionary<string, object>? GetOrCreateScopedVariables(LocString locString, string capabilityId, string? requestedScope)
		{
			Dictionary<string, object> dictionary2;
			if (locString.Variables.TryGetValue("Capabilities", out var value))
			{
				if (!(value is Dictionary<string, object> dictionary))
				{
					return null;
				}
				dictionary2 = dictionary;
			}
			else
			{
				dictionary2 = new Dictionary<string, object>(StringComparer.Ordinal);
				locString.AddObj("Capabilities", (object)dictionary2);
			}
			string scopeName = ModelCapabilityDynamicVarNames.GetScopeName(capabilityId, requestedScope);
			if (dictionary2.TryGetValue(scopeName, out var value2))
			{
				return value2 as Dictionary<string, object>;
			}
			Dictionary<string, object> dictionary3 = new Dictionary<string, object>(StringComparer.Ordinal);
			dictionary2.Add(scopeName, dictionary3);
			return dictionary3;
		}

		private static string? GetEnergyPrefix(AbstractModel model, LocString locString)
		{
			if (locString.Variables.TryGetValue("energyPrefix", out var value) && value is string result)
			{
				return result;
			}
			if (!(model is CardModel) && !(model is EnchantmentModel) && !(model is PotionModel) && !(model is PowerModel) && !(model is RelicModel))
			{
				AfflictionModel val = (AfflictionModel)(object)((model is AfflictionModel) ? model : null);
				if (val != null)
				{
					if (val.HasCard)
					{
						return EnergyIconHelper.GetPrefix((AbstractModel)(object)val.Card);
					}
				}
				else
				{
					OrbModel val2 = (OrbModel)(object)((model is OrbModel) ? model : null);
					if (val2 != null && model.IsMutable)
					{
						return val2.Owner.Character.CardPool.Title;
					}
				}
				return null;
			}
			return EnergyIconHelper.GetPrefix(model);
		}

