		private static IReadOnlyList<IModelCapability> GetCapabilitySnapshot(AbstractModel model)
		{
			if (ModelCapabilities.TryGet(model, out ModelCapabilitySet collection))
			{
				if (collection.Count != 0)
				{
					return collection.GetAttachedSnapshot();
				}
				return Array.Empty<IModelCapability>();
			}
			if (!ModelCapabilityDefaults.HasDefaultCapabilitySource(model))
			{
				return Array.Empty<IModelCapability>();
			}
			collection = ModelCapabilities.Get(model);
			if (collection.Count != 0)
			{
				return collection.GetAttachedSnapshot();
			}
			return Array.Empty<IModelCapability>();
		}

		internal static OrbValueDisplayState ApplyOrbValueDisplay(OrbValueDisplayContext context)
		{
			OrbValueDisplayState state = new OrbValueDisplayState(context.DisplayMode, context.PassiveText, context.EvokeText);
			OrbValueDisplayContext currentContext = context;
			foreach (IOrbValueDisplayContributor capability in GetCapabilities<IOrbValueDisplayContributor>((AbstractModel)(object)context.Orb))
			{
				if (!(capability is IModelCapability capability2))
				{
					continue;
				}
				TryRun(capability2, (AbstractModel)(object)context.Orb, "orb display/value-labels", delegate
				{
					ModOrbValueDisplayMode? valueDisplayMode = capability.GetValueDisplayMode(currentContext);
					if (valueDisplayMode.HasValue)
					{
						ModOrbValueDisplayMode valueOrDefault = valueDisplayMode.GetValueOrDefault();
						state = state with
						{
							DisplayMode = valueOrDefault
						};
					}
					string passiveValueDisplayText = capability.GetPassiveValueDisplayText(currentContext);
					if (passiveValueDisplayText != null)
					{
						state = state with
						{
							PassiveText = passiveValueDisplayText
						};
					}
					string evokeValueDisplayText = capability.GetEvokeValueDisplayText(currentContext);
					if (evokeValueDisplayText != null)
					{
						state = state with
						{
							EvokeText = evokeValueDisplayText
						};
					}
				});
				currentContext = currentContext with
				{
					DisplayMode = state.DisplayMode,
					PassiveText = state.PassiveText,
					EvokeText = state.EvokeText
				};
			}
			return state;
		}

