		internal static async Task AfterOwnerOrbPassiveTriggered(OrbModel orb, PlayerChoiceContext choiceContext, Creature? target)
		{
			OrbPassiveTriggerContext context = new OrbPassiveTriggerContext(orb, choiceContext, target);
			foreach (OrbCapability capability in GetCapabilities<OrbCapability>((AbstractModel)(object)orb))
			{
				if (!IsStillAttachedToOrb(capability, orb))
				{
					continue;
				}
				await TryRunAsync(capability, (AbstractModel)(object)orb, "orb lifecycle/passive-triggered", async delegate
				{
					if (IsStillAttachedToOrb(capability, orb))
					{
						await capability.NotifyOwnerOrbPassiveTriggered(context);
					}
				});
			}
		}

