		private static bool IsStillAttachedToOrb(OrbCapability capability, OrbModel orb)
		{
			return capability.Owner == orb;
		}

		private static async Task TryRunAsync(IModelCapability capability, AbstractModel model, string surface, Func<Task> action)
		{
