				string propertyName = key;
				Dictionary<string, JsonObject> dictionary = value;
				if (dictionary.Count == 0)
				{
					continue;
				}
				JsonObject jsonObject2 = new JsonObject();
				foreach (KeyValuePair<string, JsonObject> item2 in dictionary.OrderBy<KeyValuePair<string, JsonObject>, string>((KeyValuePair<string, JsonObject> pair) => pair.Key, StringComparer.OrdinalIgnoreCase))
				{
					item2.Deconstruct(out key, out var value2);
					string propertyName2 = key;
					JsonObject jsonObject3 = value2;
