			foreach (KeyValuePair<string, Dictionary<string, JsonObject>> entry in _entries)
			{
				entry.Deconstruct(out var key, out var value);
				string modId = key;
				foreach (KeyValuePair<string, JsonObject> item in value)
				{
					item.Deconstruct(out key, out var value2);
					string key2 = key;
					JsonObject jsonObject = value2;
					modelSavedDataDocument.SetRaw(modId, key2, jsonObject.DeepClone().AsObject());
