	internal static class ModelSavedDataRegistry
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<ModelSavedDataSlotKey, IModelSavedDataSlot> Slots = new Dictionary<ModelSavedDataSlotKey, IModelSavedDataSlot>();

		private static bool _propertyNameRegistered;

		private static bool _registrationFinalized;

		internal static bool IsPropertyNameRegistered
		{
			get
			{
				using (SyncRoot.EnterScope())
				{
					return _propertyNameRegistered;
				}
			}
		}

		public static void EnsureInitialized()
		{
			using (SyncRoot.EnterScope())
			{
				EnsureInitializedLocked();
			}
		}

		public static void Register(IModelSavedDataSlot slot)
		{
			ArgumentNullException.ThrowIfNull(slot, "slot");
			using (SyncRoot.EnterScope())
			{
				if (_registrationFinalized)
				{
					throw new InvalidOperationException($"ModelSavedData slot '{slot.ModId}'::'{slot.Key}' was registered after model saved data registration finalization. Register ModelSavedData slots during mod initialization.");
				}
				EnsureInitializedLocked();
				if (!Slots.TryAdd(slot.SlotKey, slot))
				{
					throw new InvalidOperationException("ModelSavedData slot is already registered: " + slot.ModId + "::" + slot.Key);
				}
			}
		}

		public static void FinalizeRegistration()
		{
			using (SyncRoot.EnterScope())
			{
				_registrationFinalized = true;
			}
		}

		private static void EnsureInitializedLocked()
		{
			if (!_propertyNameRegistered)
			{
				if (_registrationFinalized)
				{
					throw new InvalidOperationException("ModelSavedData was initialized after model saved data registration finalization. Register ModelSavedData slots during mod initialization.");
				}
				SavedAttachedStateRegistry.RegisterPropertyName("RitsuLib_ModelSavedData");
				_propertyNameRegistered = true;
			}
		}

		public static void EnsureImported(AbstractModel model, ModelSavedDataBag bag)
		{
			if (bag.IsInitialized)
			{
				return;
			}
			bag.IsInitialized = true;
			bool shouldImportMissingEntries = bag.ShouldImportMissingEntries;
			bag.ShouldImportMissingEntries = false;
			ModelSavedDataDocument preservedDocument = bag.PreservedDocument;
			IModelSavedDataSlot[] slotsSnapshot = GetSlotsSnapshot(model);
			foreach (IModelSavedDataSlot modelSavedDataSlot in slotsSnapshot)
			{
				if (preservedDocument != null && preservedDocument.TryGetRaw(modelSavedDataSlot.ModId, modelSavedDataSlot.Key, out JsonObject entry))
				{
					modelSavedDataSlot.Import(model, entry, bag);
				}
				else if (shouldImportMissingEntries)
				{
					modelSavedDataSlot.ImportMissing(model);
				}
			}
		}

		public static string? Export(AbstractModel model)
		{
			ModelSavedDataBag bag = ModelSavedDataRuntime.GetBag(model);
			ModelSavedDataDocument modelSavedDataDocument = bag.PreservedDocument?.Clone() ?? new ModelSavedDataDocument();
			IModelSavedDataSlot[] slotsSnapshot = GetSlotsSnapshot(model);
			for (int i = 0; i < slotsSnapshot.Length; i++)
			{
				slotsSnapshot[i].Export(model, bag, modelSavedDataDocument);
			}
			if (!modelSavedDataDocument.IsEmpty)
			{
				return modelSavedDataDocument.ToJsonString();
			}
			return null;
		}

		public static void Import(AbstractModel model, string? json)
		{
			ModelSavedDataRuntime.AttachDocument(model, ModelSavedDataDocument.FromJson(json));
		}

		public static void NotifyCloned(AbstractModel prototype, AbstractModel clone)
		{
			if (ModelSavedDataRuntime.TryGetBag(prototype, out ModelSavedDataBag bag))
			{
				ModelSavedDataBag bag2 = ModelSavedDataRuntime.GetBag(clone);
				bag2.PreservedDocument = bag.PreservedDocument?.Clone();
				IModelSavedDataSlot[] slotsSnapshot = GetSlotsSnapshot(prototype);
				for (int i = 0; i < slotsSnapshot.Length; i++)
				{
					slotsSnapshot[i].Clone(prototype, clone, bag, bag2);
				}
			}
		}

		private static IModelSavedDataSlot[] GetSlotsSnapshot(AbstractModel model)
		{
			using (SyncRoot.EnterScope())
			{
				return Slots.Values.Where((IModelSavedDataSlot slot) => slot.TargetType.IsInstanceOfType(model)).ToArray();
			}
		}
	}
	internal sealed class ModelSavedDataBag
	{
		private readonly HashSet<ModelSavedDataSlotKey> _dirty = new HashSet<ModelSavedDataSlotKey>();

		private readonly Dictionary<ModelSavedDataSlotKey, object> _values = new Dictionary<ModelSavedDataSlotKey, object>();

		public ModelSavedDataDocument? PreservedDocument { get; set; }

		public bool IsInitialized { get; set; }

		public bool ShouldImportMissingEntries { get; set; }

		internal void ResetForDocument(ModelSavedDataDocument? document)
		{
			_dirty.Clear();
			_values.Clear();
			PreservedDocument = document;
			IsInitialized = false;
			ShouldImportMissingEntries = true;
		}

		public bool TryGet(ModelSavedDataSlotKey key, out object value)
		{
			return _values.TryGetValue(key, out value);
		}

		public void Set(ModelSavedDataSlotKey key, object value, bool dirty = true)
		{
			_values[key] = value;
			if (dirty)
			{
				_dirty.Add(key);
			}
		}

		public bool Remove(ModelSavedDataSlotKey key)
		{
			_dirty.Add(key);
			return _values.Remove(key);
		}

		public bool IsDirty(ModelSavedDataSlotKey key)
		{
			return _dirty.Contains(key);
		}
	}
	internal static class ModelSavedDataRuntime
	{
		internal const string SavedPropertiesName = "RitsuLib_ModelSavedData";

		private static readonly ConditionalWeakTable<AbstractModel, ModelSavedDataBag> ModelBags = new ConditionalWeakTable<AbstractModel, ModelSavedDataBag>();

		public static ModelSavedDataBag GetBag(AbstractModel model)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			ModelSavedDataBag value = ModelBags.GetValue(model, (AbstractModel _) => new ModelSavedDataBag());
			ModelSavedDataRegistry.EnsureImported(model, value);
			return value;
		}

		public static bool TryGetBag(AbstractModel model, out ModelSavedDataBag bag)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			if (!ModelBags.TryGetValue(model, out bag))
			{
				return false;
			}
			ModelSavedDataRegistry.EnsureImported(model, bag);
			return true;
		}

		public static void AttachDocument(AbstractModel model, ModelSavedDataDocument? document)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			if (!ModelCapabilityUpgradeReplayContext.TryDeferCardModelSavedDataImport(model, document))
			{
				AttachDocumentImmediate(model, document);
			}
		}

		internal static void AttachDocumentImmediate(AbstractModel model, ModelSavedDataDocument? document)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			ModelSavedDataBag value = ModelBags.GetValue(model, (AbstractModel _) => new ModelSavedDataBag());
			value.ResetForDocument(document);
			ModelSavedDataRegistry.EnsureImported(model, value);
		}
	}
	internal interface IModelSavedDataSlot
	{
		string ModId { get; }

		string Key { get; }

		Type TargetType { get; }

		ModelSavedDataOptions Options { get; }

		ModelSavedDataSlotKey SlotKey { get; }

		void Import(AbstractModel model, JsonObject entry, ModelSavedDataBag bag);

		void ImportMissing(AbstractModel model);

		void Export(AbstractModel model, ModelSavedDataBag bag, ModelSavedDataDocument document);

		void Clone(AbstractModel prototype, AbstractModel clone, ModelSavedDataBag sourceBag, ModelSavedDataBag targetBag);
	}
	internal abstract class ModelSavedDataSlot<TTarget, TPayload>(string modId, string key, Func<TPayload>? defaultFactory, ModelSavedDataOptions? options) : IModelSavedDataSlot where TTarget : AbstractModel where TPayload : class, new()
	{
		private const string SchemaPropertyName = "schema";

		private const string TargetPropertyName = "target";

		private const string DataPropertyName = "data";

		private readonly Func<TPayload> _defaultFactory = defaultFactory ?? ((Func<TPayload>)(() => new TPayload()));

		protected virtual bool ShouldPropagateImportExceptions => false;

		public string ModId { get; } = modId;

		public string Key { get; } = key;

		public Type TargetType { get; } = typeof(TTarget);

		public ModelSavedDataOptions Options { get; } = ValidateOptions(options ?? new ModelSavedDataOptions());

		public ModelSavedDataSlotKey SlotKey { get; } = new ModelSavedDataSlotKey(modId, key);

		public void Import(AbstractModel model, JsonObject entry, ModelSavedDataBag bag)
		{
			TTarget val = (TTarget)(object)((model is TTarget) ? model : null);
			if (val == null)
			{
				return;
			}
			try
			{
				ImportCore(val, entry, bag);
			}
			catch (Exception ex)
			{
				if (ShouldPropagateImportExceptions)
				{
					throw;
				}
				RitsuLibFramework.Logger.Warn($"[ModelSavedData] Failed to import '{ModId}'::{Key} for {model.Id}: {ex.Message}", 1);
			}
		}

		public void ImportMissing(AbstractModel model)
		{
			TTarget val = (TTarget)(object)((model is TTarget) ? model : null);
			if (val != null)
			{
				ImportMissingCore(val);
			}
		}

		public void Export(AbstractModel model, ModelSavedDataBag bag, ModelSavedDataDocument document)
		{
			TTarget val = (TTarget)(object)((model is TTarget) ? model : null);
			if (val == null)
			{
				return;
			}
			try
			{
				if (!TryBuildEntry(val, bag, out JsonObject entry))
				{
					if (ShouldRemovePreservedEntryWhenNotWritten(bag))
					{
						document.Remove(ModId, Key);
					}
				}
				else
				{
					document.SetRaw(ModId, Key, entry);
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[ModelSavedData] Failed to export '{ModId}'::{Key} for {model.Id}: {ex.Message}", 1);
			}
		}

		public void Clone(AbstractModel prototype, AbstractModel clone, ModelSavedDataBag sourceBag, ModelSavedDataBag targetBag)
		{
			if (!(prototype is TTarget) || !(clone is TTarget))
			{
				return;
			}
			try
			{
				switch (Options.ClonePolicy)
				{
				case ModelSavedDataClonePolicy.Drop:
					targetBag.Remove(SlotKey);
					break;
				case ModelSavedDataClonePolicy.Share:
				{
					if (sourceBag.TryGet(SlotKey, out object value3))
					{
						targetBag.Set(SlotKey, value3, sourceBag.IsDirty(SlotKey));
					}
					break;
				}
				default:
				{
					if (sourceBag.TryGet(SlotKey, out object value) && value is TPayload value2)
					{
						targetBag.Set(SlotKey, DeepClone(value2), sourceBag.IsDirty(SlotKey));
					}
					break;
				}
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[ModelSavedData] Failed to clone '{ModId}'::{Key} for {prototype.Id}: {ex.Message}", 1);
			}
		}

		public TPayload GetOrCreate(TTarget model)
		{
			ModelSavedDataBag bag = ModelSavedDataRuntime.GetBag((AbstractModel)(object)model);
			if (bag.TryGet(SlotKey, out object value) && value is TPayload result)
			{
				return result;
			}
			TPayload val = CreateDefault();
			bag.Set(SlotKey, val, dirty: false);
			return val;
		}

		public bool TryGet(TTarget model, out TPayload value)
		{
			if (ModelSavedDataRuntime.TryGetBag((AbstractModel)(object)model, out ModelSavedDataBag bag) && bag.TryGet(SlotKey, out object value2) && value2 is TPayload val)
			{
				value = val;
				return true;
			}
			value = null;
			return false;
		}

		public void Set(TTarget model, TPayload value)
		{
			ArgumentNullException.ThrowIfNull(value, "value");
			ModelSavedDataRuntime.GetBag((AbstractModel)(object)model).Set(SlotKey, value);
		}

		public void MarkDirty(TTarget model)
		{
			ModelSavedDataBag bag = ModelSavedDataRuntime.GetBag((AbstractModel)(object)model);
			if (bag.TryGet(SlotKey, out object value) && value is TPayload value2)
			{
				bag.Set(SlotKey, value2);
			}
			else
			{
				bag.Set(SlotKey, CreateDefault());
			}
		}

		public bool Remove(TTarget model)
		{
			return ModelSavedDataRuntime.GetBag((AbstractModel)(object)model).Remove(SlotKey);
		}

		protected JsonObject CreateEntry(TPayload value)
		{
			return new JsonObject
			{
				["schema"] = Options.SchemaVersion,
				["target"] = typeof(TTarget).FullName ?? typeof(TTarget).Name,
				["data"] = JsonSerializer.SerializeToNode(value, ModelSavedDataJson.Options)
			};
		}

		protected bool TryReadData(JsonObject entry, out TPayload value)
		{
			value = null;
			int schema = entry["schema"]?.GetValue<int>() ?? 1;
			if (!TryMigrate(entry, schema, out JsonObject migrated))
			{
				return false;
			}
			JsonNode? jsonNode = migrated["data"];
			TPayload val = ((jsonNode != null) ? jsonNode.Deserialize<TPayload>(ModelSavedDataJson.Options) : null);
			if (val == null)
			{
				return false;
			}
			value = val;
			return true;
		}

		protected bool ShouldWrite(ModelSavedDataBag bag, object? value)
		{
			return Options.WritePolicy switch
			{
				ModelSavedDataWritePolicy.AlwaysWhenPresent => value != null, 
				ModelSavedDataWritePolicy.WhenNonDefault => value != null && !IsDefaultValue((TPayload)value), 
				_ => bag.IsDirty(SlotKey) && value != null, 
			};
		}

		protected TPayload DeepClone(TPayload value)
		{
			JsonNode? jsonNode = JsonSerializer.SerializeToNode(value, ModelSavedDataJson.Options);
			return ((jsonNode != null) ? jsonNode.Deserialize<TPayload>(ModelSavedDataJson.Options) : null) ?? CreateDefault();
		}

		protected abstract bool TryBuildEntry(TTarget model, ModelSavedDataBag bag, out JsonObject entry);

		protected abstract void ImportCore(TTarget model, JsonObject entry, ModelSavedDataBag bag);

		protected virtual void ImportMissingCore(TTarget model)
		{
		}

		protected virtual bool ShouldRemovePreservedEntryWhenNotWritten(ModelSavedDataBag bag)
		{
			return bag.IsDirty(SlotKey);
		}

		private bool TryMigrate(JsonObject entry, int schema, out JsonObject migrated)
		{
			migrated = entry;
			if (schema == Options.SchemaVersion)
			{
				return true;
			}
			if (schema > Options.SchemaVersion)
			{
				return false;
			}
			if (Options.Migrations == null || Options.Migrations.Count == 0)
			{
				return false;
			}
			List<IMigration> migrations = (from migration in Options.Migrations
				orderby migration.FromVersion, migration.ToVersion
				select migration).ToList();
			if (!MigrationManager.TryBuildShortestMigrationPath(schema, Options.SchemaVersion, migrations, out List<IMigration> path))
			{
				return false;
			}
			migrated = entry.DeepClone().AsObject();
			int num = schema;
			foreach (IMigration item in path)
			{
				if (!item.Migrate(migrated))
				{
					return false;
				}
				num = item.ToVersion;
				migrated["schema"] = num;
			}
			return num == Options.SchemaVersion;
		}

		protected bool IsDefaultValue(TPayload value)
		{
			try
			{
				string a = JsonSerializer.SerializeToNode(value, ModelSavedDataJson.Options)?.ToJsonString();
				string b = JsonSerializer.SerializeToNode(CreateDefault(), ModelSavedDataJson.Options)?.ToJsonString();
				return string.Equals(a, b, StringComparison.Ordinal);
			}
			catch
			{
				return false;
			}
		}

		private TPayload CreateDefault()
		{
			return _defaultFactory() ?? throw new InvalidOperationException($"ModelSavedData default factory returned null for '{ModId}'::{Key}.");
		}

		private static ModelSavedDataOptions ValidateOptions(ModelSavedDataOptions options)
		{
			if (options.SchemaVersion < 1)
			{
				throw new ArgumentOutOfRangeException("options", options.SchemaVersion, "ModelSavedData schema version must be at least 1.");
			}
			IReadOnlyList<IMigration>? migrations = options.Migrations;
			if (migrations != null && migrations.Any((IMigration migration) => migration.ToVersion <= migration.FromVersion))
			{
				throw new ArgumentException("Every ModelSavedData migration must advance to a higher version.", "options");
			}
			return options;
		}
	}
	internal sealed class StoredModelSavedDataSlot<TTarget, TPayload> : ModelSavedDataSlot<TTarget, TPayload> where TTarget : AbstractModel where TPayload : class, new()
	{
		public StoredModelSavedDataSlot(string modId, string key, Func<TPayload>? defaultFactory, ModelSavedDataOptions? options)
			: base(modId, key, defaultFactory, options)
		{
		}

		protected override bool TryBuildEntry(TTarget model, ModelSavedDataBag bag, out JsonObject entry)
		{
			entry = null;
			if (!bag.TryGet(base.SlotKey, out object value) || !(value is TPayload value2) || !ShouldWrite(bag, value2))
			{
				return false;
			}
			entry = CreateEntry(value2);
			return true;
		}

		protected override void ImportCore(TTarget model, JsonObject entry, ModelSavedDataBag bag)
		{
			if (TryReadData(entry, out var value))
			{
				bag.Set(base.SlotKey, value, dirty: false);
				return;
			}
			RitsuLibFramework.Logger.Warn($"[ModelSavedData] Failed to read model data '{base.ModId}'::{base.Key}.", 1);
		}
	}
	internal sealed class ComputedModelSavedDataSlot<TTarget, TPayload>(string modId, string key, Func<TTarget, TPayload?> exporter, Action<TTarget, TPayload?> importer, Func<TPayload>? defaultFactory, ModelSavedDataOptions? options) : ModelSavedDataSlot<TTarget, TPayload>(modId, key, defaultFactory, options) where TTarget : AbstractModel where TPayload : class, new()
	{
		protected override bool ShouldPropagateImportExceptions => true;

		protected override bool TryBuildEntry(TTarget model, ModelSavedDataBag bag, out JsonObject entry)
		{
			entry = null;
			TPayload val = exporter(model);
			if (val == null || !ShouldWriteComputed(val))
			{
				return false;
			}
			entry = CreateEntry(val);
			return true;
		}

		protected override void ImportCore(TTarget model, JsonObject entry, ModelSavedDataBag bag)
		{
			importer(model, TryReadData(entry, out var value) ? value : null);
		}

		protected override void ImportMissingCore(TTarget model)
		{
			importer(model, null);
		}

		protected override bool ShouldRemovePreservedEntryWhenNotWritten(ModelSavedDataBag bag)
		{
			return true;
		}

		private bool ShouldWriteComputed(TPayload value)
		{
			if (base.Options.WritePolicy == ModelSavedDataWritePolicy.WhenNonDefault)
			{
				return !IsDefaultValue(value);
			}
			return true;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides a per-mod registry for model-saved-data slots.</para>
	///     <para xml:lang="zh-CN">提供按模组划分的模型保存数据槽位注册表。</para>
	/// </summary>
	public sealed class ModelSavedDataStore
	{
		private static readonly Lock StoresLock = new Lock();

		private static readonly Dictionary<string, ModelSavedDataStore> Stores = new Dictionary<string, ModelSavedDataStore>(StringComparer.OrdinalIgnoreCase);

		private readonly Dictionary<string, IModelSavedDataSlot> _slots = new Dictionary<string, IModelSavedDataSlot>(StringComparer.OrdinalIgnoreCase);

		/// <summary>
		///     <para xml:lang="en">Gets the ID of the mod that owns this store.</para>
		///     <para xml:lang="zh-CN">获取拥有此存储的模组 ID。</para>
		/// </summary>
		public string ModId { get; }

		private ModelSavedDataStore(string modId)
		{
			ModId = modId;
		}

		/// <summary>
		///     <para xml:lang="en">Gets the process-wide store for <paramref name="modId" />.</para>
		///     <para xml:lang="zh-CN">获取 <paramref name="modId" /> 的进程级存储。</para>
		/// </summary>
		public static ModelSavedDataStore For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (StoresLock.EnterScope())
			{
				if (Stores.TryGetValue(modId, out ModelSavedDataStore value))
				{
					return value;
				}
				value = new ModelSavedDataStore(modId);
				Stores[modId] = value;
				return value;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers saved data attached to mutable model instances.</para>
		///     <para xml:lang="zh-CN">注册附加到可变模型实例的保存数据。</para>
		/// </summary>
		public ModelSavedData<TTarget, TPayload> Register<TTarget, TPayload>(string key, Func<TPayload>? defaultFactory = null, ModelSavedDataOptions? options = null) where TTarget : AbstractModel where TPayload : class, new()
		{
			StoredModelSavedDataSlot<TTarget, TPayload> slot = new StoredModelSavedDataSlot<TTarget, TPayload>(ModId, key, defaultFactory, options);
			RegisterSlot(slot);
			return new ModelSavedData<TTarget, TPayload>(slot);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers computed saved data whose value is exported from and imported into the model directly.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册直接从模型导出值并将值导入模型的计算型保存数据。
		///     </para>
		/// </summary>
		public void RegisterComputed<TTarget, TPayload>(string key, Func<TTarget, TPayload?> exporter, Action<TTarget, TPayload?> importer, Func<TPayload>? defaultFactory = null, ModelSavedDataOptions? options = null) where TTarget : AbstractModel where TPayload : class, new()
		{
			ArgumentNullException.ThrowIfNull(exporter, "exporter");
			ArgumentNullException.ThrowIfNull(importer, "importer");
			RegisterSlot(new ComputedModelSavedDataSlot<TTarget, TPayload>(ModId, key, exporter, importer, defaultFactory, options));
		}

		private void RegisterSlot(IModelSavedDataSlot slot)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(slot.Key, "slot.Key");
			lock (_slots)
			{
				if (_slots.ContainsKey(slot.Key))
				{
					throw new InvalidOperationException("ModelSavedData key is already registered: " + ModId + "::" + slot.Key);
				}
				ModelSavedDataRegistry.Register(slot);
				_slots.Add(slot.Key, slot);
			}
		}
	}
