			public static void Postfix(CardModel __instance, ref string __result)
			{
				LocString titleLocString = __instance.TitleLocString;
				string formattedText = titleLocString.GetFormattedText();
				string upgradeSuffix = GetUpgradeSuffix(__instance);
				CardModelCapabilityHost.ApplyTitleFragments(new CardTitleContext(__instance, titleLocString, formattedText, upgradeSuffix, formattedText + upgradeSuffix), ref __result);
