	internal static class CardOverlayCapabilityPatchHelper
	{
		private const string ManagedContainerName = "RitsuLibCapabilityOverlays";

		private const string OverlaySurface = "card display/overlay";

		internal static void Refresh(NCard cardNode)
		{
			if (!GodotObject.IsInstanceValid((GodotObject)(object)cardNode))
			{
				return;
			}
			Node nodeOrNull = ((Node)cardNode).GetNodeOrNull<Node>(NodePath.op_Implicit("%OverlayContainer"));
			if (nodeOrNull == null || !GodotObject.IsInstanceValid((GodotObject)(object)nodeOrNull))
			{
				return;
			}
			RemoveManagedContainer(nodeOrNull);
			CardModel model = cardNode.Model;
			if (model == null)
			{
				return;
			}
			CardOverlayContext context = new CardOverlayContext(model, cardNode, nodeOrNull);
			CardModelCapabilityHost.OrderedCardOverlayContribution[] array = (from contribution in CardModelCapabilityHost.GetOverlayContributions(context)
				orderby contribution.Contribution.Order, contribution.SourceIndex
				select contribution).ThenBy<CardModelCapabilityHost.OrderedCardOverlayContribution, string>((CardModelCapabilityHost.OrderedCardOverlayContribution contribution) => contribution.Contribution.Id, StringComparer.Ordinal).ToArray();
			if (array.Length == 0)
			{
				return;
			}
			Control val = CreateManagedContainer();
			CardModelCapabilityHost.OrderedCardOverlayContribution[] array2 = array;
			for (int num = 0; num < array2.Length; num++)
			{
				CardModelCapabilityHost.OrderedCardOverlayContribution ordered = array2[num];
				Control val2 = TryCreateOverlay(context, ordered);
				if (val2 != null)
				{
					PrepareOverlay(val2, ordered.Contribution);
					RitsuGodotTreeCompat.AddChildSafely((Node)(object)val, (Node?)(object)val2);
				}
			}
			if (((Node)val).GetChildCount(false) == 0)
			{
				GodotTreeExtensions.QueueFreeSafely((Node)(object)val);
			}
			else
			{
				RitsuGodotTreeCompat.AddChildSafely(nodeOrNull, (Node?)(object)val);
			}
		}

		private static Control CreateManagedContainer()
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_002a: Expected O, but got Unknown
			Control val = new Control
			{
				Name = StringName.op_Implicit("RitsuLibCapabilityOverlays"),
				MouseFilter = (MouseFilterEnum)2
			};
			val.SetAnchorsAndOffsetsPreset((LayoutPreset)15, (LayoutPresetMode)0, 0);
			return val;
		}

		private static void RemoveManagedContainer(Node overlayContainer)
		{
			Control nodeOrNull = overlayContainer.GetNodeOrNull<Control>(NodePath.op_Implicit("RitsuLibCapabilityOverlays"));
			if (nodeOrNull != null && GodotObject.IsInstanceValid((GodotObject)(object)nodeOrNull))
			{
				GodotTreeExtensions.RemoveChildSafely(overlayContainer, (Node)(object)nodeOrNull);
				GodotTreeExtensions.QueueFreeSafely((Node)(object)nodeOrNull);
			}
		}

		private static Control? TryCreateOverlay(CardOverlayContext context, CardModelCapabilityHost.OrderedCardOverlayContribution ordered)
		{
			try
			{
				return CreateOverlay(context, ordered);
			}
			catch (Exception exception)
			{
				ModelCapabilityDiagnostics.WarnFailure("card display/overlay", (AbstractModel)(object)context.Card, ordered.Source, exception);
				return null;
			}
		}

		private static Control? CreateOverlay(CardOverlayContext context, CardModelCapabilityHost.OrderedCardOverlayContribution ordered)
		{
			CardOverlayContribution contribution = ordered.Contribution;
			if (string.IsNullOrWhiteSpace(contribution.Id))
			{
				WarnInvalid(context.Card, ordered.Source, contribution, "overlay id is empty");
				return null;
			}
			int num = CountCreationSources(contribution);
			if (num != 1)
			{
				WarnInvalid(context.Card, ordered.Source, contribution, $"expected exactly one creation source, found {num}");
				return null;
			}
			if (!string.IsNullOrWhiteSpace(contribution.ScenePath))
			{
				if (ContentAssetOverridePatchHelper.TryInstantiatePackedScenePathOverride(context.Card, contribution.ScenePath, "CardOverlayContribution[" + contribution.Id + "].ScenePath", out Control result))
				{
					return result;
				}
				WarnInvalid(context.Card, ordered.Source, contribution, $"scene path is not a valid {"PackedScene"} {"Control"} overlay: '{contribution.ScenePath}'");
				return null;
			}
			if (contribution.Scene != null)
			{
				if (ContentAssetOverridePatchHelper.TryInstantiatePackedSceneOverride(context.Card, contribution.Scene, "CardOverlayContribution[" + contribution.Id + "].Scene", "capability source " + FormatSource(ordered.Source), out Control result2))
				{
					return result2;
				}
				WarnInvalid(context.Card, ordered.Source, contribution, "scene is not a valid PackedScene Control overlay");
				return null;
			}
			Control obj = contribution.Factory(context);
			if (obj == null)
			{
				WarnInvalid(context.Card, ordered.Source, contribution, "factory returned null");
			}
			return obj;
		}

		private static void PrepareOverlay(Control overlay, CardOverlayContribution contribution)
		{
			overlay.MouseFilter = (MouseFilterEnum)2;
			if (contribution.FullRect)
			{
				overlay.SetAnchorsAndOffsetsPreset((LayoutPreset)15, (LayoutPresetMode)0, 0);
			}
		}

		private static int CountCreationSources(CardOverlayContribution contribution)
		{
			int num = 0;
			if (!string.IsNullOrWhiteSpace(contribution.ScenePath))
			{
				num++;
			}
			if (contribution.Scene != null)
			{
				num++;
			}
			if (contribution.Factory != null)
			{
				num++;
			}
			return num;
		}

		private static void WarnInvalid(CardModel card, object source, CardOverlayContribution contribution, string reason)
		{
			RitsuLibFramework.Logger.Warn($"[ModelCapabilities] Surface='{"card display/overlay"}' ignored invalid overlay. ModelId='{((AbstractModel)card).Id}' {FormatSource(source)} OverlayId='{contribution.Id}' Reason='{reason}'", 1);
		}

		private static string FormatSource(object source)
		{
			if (source is IModelCapability modelCapability)
			{
				return $"CapabilityId='{modelCapability.CapabilityId}' CapabilityType='{source.GetType().FullName}'";
			}
			return "SourceType='" + source.GetType().FullName + "'";
		}
	}
