		internal sealed class HookPlayerChoiceContextConstructorPatch : IPatchMethod
		{
			private static readonly FieldInfo OwnerField = AccessTools.Field(typeof(HookPlayerChoiceContext), "<Owner>k__BackingField");

			public static string PatchId => "ritsulib_model_capability_hook_choice_context";

			public static string Description => "Resolve model-capability owners when vanilla hook choice contexts are created";

			public static bool IsCritical => true;

			public static ModPatchTarget[] GetTargets()
			{
				return new ModPatchTarget[1]
				{
					new ModPatchTarget(typeof(HookPlayerChoiceContext), ".ctor", new Type[4]
					{
						typeof(AbstractModel),
						typeof(ulong),
						typeof(ICombatState),
						typeof(GameActionType)
					}, (MethodType)3)
				};
			}

			public static void Postfix(HookPlayerChoiceContext __instance, AbstractModel source, ICombatState? combatState)
			{
				if (source is IModelCapability)
				{
					OwnerField.SetValue(__instance, ResolveOwner(source, combatState));
				}
			}

			private static Player? ResolveOwner(AbstractModel source, ICombatState? combatState)
			{
				AbstractModel owner = ((IModelCapability)source).Owner;
				if (owner != null)
				{
					return HookPlayerChoiceContext.GetOwner(owner, combatState);
				}
				return null;
			}
		}
	}
