	/// <summary>
	///     <para xml:lang="en">Bridges model-saved data through <see cref="T:MegaCrit.Sts2.Core.Saves.Runs.SavedProperties" />.</para>
	///     <para xml:lang="zh-CN">通过 <see cref="T:MegaCrit.Sts2.Core.Saves.Runs.SavedProperties" /> 传递模型保存数据。</para>
	/// </summary>
	internal static class ModelSavedDataPatches
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Exports registered model-saved data after base-game model properties are serialized.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         游戏原版模型属性序列化后，导出已注册的模型保存数据。
		///     </para>
		/// </summary>
		internal sealed class SavedPropertiesFromInternalPatch : IPatchMethod
		{
			public static string PatchId => "ritsulib_model_saved_data_SavedProperties_FromInternal";

			public static string Description => "Bridge ModelSavedData through SavedProperties save -> SavedProperties.FromInternal(...)";

			public static bool IsCritical => true;

			public static ModPatchTarget[] GetTargets()
			{
				return new ModPatchTarget[1]
				{
					new ModPatchTarget(typeof(SavedProperties), "FromInternal", new Type[2]
					{
						typeof(object),
						typeof(ModelId)
					})
				};
			}

			public static void Postfix(ref SavedProperties? __result, object model, ModelId? id)
			{
				//IL_0021: Unknown result type (might be due to invalid IL or missing references)
				AbstractModel val = (AbstractModel)((model is AbstractModel) ? model : null);
				if (val != null)
				{
					string value = ModelSavedDataRegistry.Export(val);
					if (!string.IsNullOrWhiteSpace(value))
					{
						SavedProperties val2 = (SavedProperties)(((object)__result) ?? ((object)new SavedProperties()));
						SavedAttachedStateRegistry.AddToProperties(val2, "RitsuLib_ModelSavedData", value);
						__result = val2;
					}
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Imports registered model-saved data after base-game model properties are deserialized.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         游戏原版模型属性反序列化后，导入已注册的模型保存数据。
		///     </para>
		/// </summary>
		internal sealed class SavedPropertiesFillInternalPatch : IPatchMethod
		{
			public static string PatchId => "ritsulib_model_saved_data_SavedProperties_FillInternal";

			public static string Description => "Bridge ModelSavedData through SavedProperties load -> SavedProperties.FillInternal(...)";

			public static bool IsCritical => true;

			public static ModPatchTarget[] GetTargets()
			{
				return new ModPatchTarget[1]
				{
					new ModPatchTarget(typeof(SavedProperties), "FillInternal", new Type[1] { typeof(object) })
				};
			}

			public static void Postfix(SavedProperties __instance, object model)
			{
				AbstractModel val = (AbstractModel)((model is AbstractModel) ? model : null);
				if (val != null)
				{
					if (!ModelSavedDataRegistry.IsPropertyNameRegistered)
					{
						RemoveSavedData(__instance);
						return;
					}
					SavedAttachedStateRegistry.TryGetFromProperties<string>(__instance, "RitsuLib_ModelSavedData", out string value);
					ModelSavedDataRegistry.Import(val, value);
				}
			}
		}

		private static void RemoveSavedData(SavedProperties properties)
		{
			RemoveByName<int>(ref properties.ints);
			RemoveByName<bool>(ref properties.bools);
			RemoveByName<string>(ref properties.strings);
			RemoveByName<int[]>(ref properties.intArrays);
			RemoveByName<ModelId>(ref properties.modelIds);
			RemoveByName<SerializableCard>(ref properties.cards);
			RemoveByName<SerializableCard[]>(ref properties.cardArrays);
			static void RemoveByName<T>(ref List<SavedProperty<T>>? values)
			{
				if (values != null)
				{
					values.RemoveAll(delegate(SavedProperty<T> value)
					{
						//IL_0000: Unknown result type (might be due to invalid IL or missing references)
						return value.name == "RitsuLib_ModelSavedData";
					});
					if (values.Count == 0)
					{
						values = null;
					}
				}
			}
		}
	}
