		private static async Task RunBeforeTurnEndWithCapability(OrbModel orb, PlayerChoiceContext choiceContext)
		{
			await orb.BeforeTurnEndOrbTrigger(choiceContext);
			if (orb.Owner.Creature.CombatState != null)
			{
				await ModelCapabilityHost.AfterOwnerOrbBeforeTurnEndTriggered(orb, choiceContext);
			}
		}

		private static async Task RunAfterTurnStartWithCapability(OrbModel orb, PlayerChoiceContext choiceContext)
		{
			await orb.AfterTurnStartOrbTrigger(choiceContext);
			if (orb.Owner.Creature.CombatState != null)
			{
				await ModelCapabilityHost.AfterOwnerOrbAfterTurnStartTriggered(orb, choiceContext);
			}
		}

		private static async Task RunPassiveWithCapability(OrbModel orb, PlayerChoiceContext choiceContext, Creature? target)
		{
			await orb.Passive(choiceContext, target);
			if (orb.Owner.Creature.CombatState != null)
			{
				await ModelCapabilityHost.AfterOwnerOrbPassiveTriggered(orb, choiceContext, target);
			}
		}

		private static async Task AfterEvokeHook(Task originalTask, OrbModel orb, PlayerChoiceContext choiceContext, IEnumerable<Creature> targets)
		{
			await originalTask;
			await ModelCapabilityHost.AfterOwnerOrbEvoked(orb, choiceContext, targets);
		}

		private static IEnumerable<CodeInstruction> RedirectSingleAwaitedCall(IEnumerable<CodeInstruction> instructions, string operation, string patchId, MethodInfo? fromMethod, MethodInfo? wrapperMethod)
		{
			HarmonyIlRewriter harmonyIlRewriter = HarmonyIlRewriter.From(instructions);
			MethodInfo fromMethod2 = HarmonyIl.RequireMethod(fromMethod, operation + " (" + patchId + ")");
			MethodInfo requiredWrapperMethod = HarmonyIl.RequireMethod(wrapperMethod, operation + " (" + patchId + ")");
			HarmonyIlRewriteReport report = HarmonyAsyncIl.RedirectAwaitedCalls(harmonyIlRewriter, operation, fromMethod2, requiredWrapperMethod, (IReadOnlyList<CodeInstruction> code) => code.Any(HarmonyIl.IsCall(requiredWrapperMethod)));
			return harmonyIlRewriter.InstructionsChecked(report);
		}
	}
