namespace STS2RitsuLib.Localization
{
	/// <summary>
	///     <para xml:lang="en">
	///         Loads ancient-event dialogue lines from localization tables and adds them to
	///         <c>AncientDialogueSet</c> instances for modded characters.
	///     </para>
	///     <para xml:lang="zh-CN">从本地化表加载先古之民事件对话，并将其添加到模组角色的 <c>AncientDialogueSet</c> 实例中。</para>
	/// </summary>
	public static class AncientDialogueLocalization
	{
		private const string AncientLocTable = "ancients";

		private const string ArchitectKey = "THE_ARCHITECT";

		private const string ArchitectBaseKeyPrefix = "THE_ARCHITECT.talk.";

		private const string AttackKeySuffix = "-attack";

		private const string StartAttackKeySuffix = "-startattack";

		private const string EndAttackKeySuffix = "-endattack";

		private const string VisitIndexKeySuffix = "-visit";

		/// <summary>
		///     <para xml:lang="en">
		///         Builds the <c>{ancient}.talk.{character}.</c> localization-key prefix for an ancient event and
		///         character entry ID.
		///     </para>
		///     <para xml:lang="zh-CN">为先古之民事件和角色条目 ID 构建 <c>{ancient}.talk.{character}.</c> 本地化键前缀。</para>
		/// </summary>
		public static string BaseLocKey(string ancientEntry, string characterEntry)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(ancientEntry, "ancientEntry");
			ArgumentException.ThrowIfNullOrWhiteSpace(characterEntry, "characterEntry");
			return ancientEntry + ".talk." + characterEntry + ".";
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Reads the contiguous, zero-based dialogue sequences for an ancient event and character from the
		///         <c>ancients</c> localization table.
		///     </para>
		///     <para xml:lang="zh-CN">从 <c>ancients</c> 本地化表读取指定先古之民事件和角色从零开始、连续编号的对话序列。</para>
		/// </summary>
		public static List<AncientDialogue> GetDialoguesForCharacter(string ancientEntry, CharacterModel character)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(ancientEntry, "ancientEntry");
			ArgumentNullException.ThrowIfNull(character, "character");
			return GetDialoguesForKey("ancients", BaseLocKey(ancientEntry, ((AbstractModel)character).Id.Entry));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Reads dialogue sequences under <paramref name="baseKey" /> from <paramref name="locTable" />.
		///         Sequence and line indices must each be contiguous and start at zero; scanning stops at the first missing index.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从 <paramref name="locTable" /> 读取 <paramref name="baseKey" />
		///         下的对话序列。序列索引和行索引均须从零开始且连续；遇到首个缺失索引时即停止扫描。
		///     </para>
		/// </summary>
		public static List<AncientDialogue> GetDialoguesForKey(string locTable, string baseKey)
		{
			//IL_0085: Unknown result type (might be due to invalid IL or missing references)
			//IL_008a: Unknown result type (might be due to invalid IL or missing references)
			//IL_008c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0091: Unknown result type (might be due to invalid IL or missing references)
			//IL_009b: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a0: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ac: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ad: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b4: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b5: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c1: Expected O, but got Unknown
			ArgumentException.ThrowIfNullOrWhiteSpace(locTable, "locTable");
			ArgumentException.ThrowIfNullOrWhiteSpace(baseKey, "baseKey");
			List<AncientDialogue> list = new List<AncientDialogue>();
			bool isArchitect = baseKey.StartsWith("THE_ARCHITECT.talk.", StringComparison.OrdinalIgnoreCase);
			int i = 0;
			int num = 0;
			for (; DialogueExists(locTable, baseKey, i); i++)
			{
				num = ResolveVisitIndex(locTable, baseKey, i, num, isArchitect);
				List<string> list2 = new List<string>();
				for (string text = ExistingLine(locTable, baseKey, i, list2.Count); text != null; text = ExistingLine(locTable, baseKey, i, list2.Count))
				{
					list2.Add(GetSfxPath(locTable, text));
				}
				(ArchitectAttackers StartAttackers, ArchitectAttackers EndAttackers) tuple = ResolveArchitectAttackers(locTable, baseKey, i, isArchitect);
				ArchitectAttackers item = tuple.StartAttackers;
				ArchitectAttackers item2 = tuple.EndAttackers;
				AncientDialogue val = new AncientDialogue(list2.ToArray());
				val.set_VisitIndex((int?)num);
				val.set_StartAttackers(item);
				val.set_EndAttackers(item2);
				list.Add(val);
			}
			return list;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds an <see cref="T:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogueSet" /> for a modded ancient event from the <c>ancients</c>
		///         localization table. It reads the first <c>{id}.talk.firstVisitEver.*</c> sequence, all <c>{id}.talk.ANY.*</c>
		///         sequences, and sequences for each base-game character.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         根据 <c>ancients</c> 本地化表为模组先古之民事件构建 <see cref="T:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogueSet" />。该方法读取首个
		///         <c>{id}.talk.firstVisitEver.*</c> 序列、全部 <c>{id}.talk.ANY.*</c> 序列，以及每个原版角色的对话序列。
		///     </para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         Characters registered in <see cref="T:STS2RitsuLib.Content.ModContentRegistry" /> are intentionally omitted.
		///         RitsuLib's <c>PopulateLocKeys</c> prefix adds their entries once through
		///         <see cref="M:STS2RitsuLib.Localization.AncientDialogueLocalization.AppendCharacterDialogues(MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogueSet,System.String,System.Collections.Generic.IEnumerable{MegaCrit.Sts2.Core.Models.CharacterModel})" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         此处会有意跳过在 <see cref="T:STS2RitsuLib.Content.ModContentRegistry" /> 中注册的角色；RitsuLib 的 <c>PopulateLocKeys</c> 前置补丁会通过
		///         <see cref="M:STS2RitsuLib.Localization.AncientDialogueLocalization.AppendCharacterDialogues(MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogueSet,System.String,System.Collections.Generic.IEnumerable{MegaCrit.Sts2.Core.Models.CharacterModel})" /> 添加一次这些角色的条目。
		///     </para>
		/// </remarks>
		public static AncientDialogueSet BuildDialogueSetForModAncient(string ancientEntry)
		{
			//IL_0104: Unknown result type (might be due to invalid IL or missing references)
			//IL_0109: Unknown result type (might be due to invalid IL or missing references)
			//IL_0110: Unknown result type (might be due to invalid IL or missing references)
			//IL_0117: Unknown result type (might be due to invalid IL or missing references)
			//IL_0120: Expected O, but got Unknown
			ArgumentException.ThrowIfNullOrWhiteSpace(ancientEntry, "ancientEntry");
			HashSet<string> hashSet = (from c in ModContentRegistry.GetModCharacters()
				select ((AbstractModel)c).Id.Entry).ToHashSet<string>(StringComparer.Ordinal);
			List<AncientDialogue> dialoguesForKey = GetDialoguesForKey("ancients", BaseLocKey(ancientEntry, "firstVisitEver"));
			AncientDialogue firstVisitEverDialogue = ((dialoguesForKey.Count > 0) ? dialoguesForKey[0] : null);
			Dictionary<string, IReadOnlyList<AncientDialogue>> dictionary = new Dictionary<string, IReadOnlyList<AncientDialogue>>();
			foreach (CharacterModel allCharacter in ModelDb.AllCharacters)
			{
				if (!hashSet.Contains(((AbstractModel)allCharacter).Id.Entry))
				{
					List<AncientDialogue> dialoguesForKey2 = GetDialoguesForKey("ancients", BaseLocKey(ancientEntry, ((AbstractModel)allCharacter).Id.Entry));
					if (dialoguesForKey2.Count > 0)
					{
						dictionary[((AbstractModel)allCharacter).Id.Entry] = dialoguesForKey2;
					}
				}
			}
			List<AncientDialogue> dialoguesForKey3 = GetDialoguesForKey("ancients", BaseLocKey(ancientEntry, "ANY"));
			AncientDialogueSet val = new AncientDialogueSet();
			val.set_FirstVisitEverDialogue(firstVisitEverDialogue);
			val.set_CharacterDialogues(dictionary);
			val.set_AgnosticDialogues((IReadOnlyList<AncientDialogue>)dialoguesForKey3);
			return val;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends localization-defined dialogues for <paramref name="characters" /> to
		///         <paramref name="dialogueSet" /> for <paramref name="ancientEntry" />. Existing dialogues are retained; this
		///         method does not remove duplicates.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将 <paramref name="characters" /> 在 <paramref name="ancientEntry" /> 下由本地化定义的对话追加到
		///         <paramref name="dialogueSet" />。已有对话会被保留，且此方法不会移除重复项。
		///     </para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">The number of <c>AncientDialogue</c> instances appended.</para>
		///     <para xml:lang="zh-CN">追加的 <c>AncientDialogue</c> 实例数。</para>
		/// </returns>
		public static int AppendCharacterDialogues(AncientDialogueSet dialogueSet, string ancientEntry, IEnumerable<CharacterModel> characters)
		{
			ArgumentNullException.ThrowIfNull(dialogueSet, "dialogueSet");
			ArgumentException.ThrowIfNullOrWhiteSpace(ancientEntry, "ancientEntry");
			ArgumentNullException.ThrowIfNull(characters, "characters");
			int num = 0;
			foreach (CharacterModel character in characters)
			{
				if (character == null)
				{
					continue;
				}
				List<AncientDialogue> dialoguesForCharacter = GetDialoguesForCharacter(ancientEntry, character);
				if (dialoguesForCharacter.Count == 0)
				{
					continue;
				}
				string entry = ((AbstractModel)character).Id.Entry;
				IReadOnlyList<AncientDialogue> valueOrDefault = dialogueSet.CharacterDialogues.GetValueOrDefault(entry, Array.Empty<AncientDialogue>());
				Dictionary<string, IReadOnlyList<AncientDialogue>> characterDialogues = dialogueSet.CharacterDialogues;
				string key = entry;
				List<AncientDialogue> list = dialoguesForCharacter;
				int num2 = 0;
				AncientDialogue[] array = (AncientDialogue[])(object)new AncientDialogue[valueOrDefault.Count + list.Count];
				foreach (AncientDialogue item in valueOrDefault)
				{
					array[num2] = item;
					num2++;
				}
				Span<AncientDialogue> span = CollectionsMarshal.AsSpan(list);
				span.CopyTo(new Span<AncientDialogue>(array).Slice(num2, span.Length));
				num2 += span.Length;
				characterDialogues[key] = new global::<>z__ReadOnlyArray<AncientDialogue>(array);
				num += dialoguesForCharacter.Count;
			}
			return num;
		}

		private static string GetSfxPath(string locTable, string dialogueLoc)
		{
			LocString ifExists = LocString.GetIfExists(locTable, dialogueLoc + ".sfx");
			return ((ifExists != null) ? ifExists.GetRawText() : null) ?? string.Empty;
		}

		private static int ResolveVisitIndex(string locTable, string baseKey, int dialogueIndex, int currentVisitIndex, bool isArchitect)
		{
			currentVisitIndex = ((!isArchitect) ? (dialogueIndex switch
			{
				0 => 0, 
				1 => 1, 
				2 => 4, 
				_ => currentVisitIndex + 3, 
			}) : dialogueIndex);
			LocString ifExists = LocString.GetIfExists(locTable, $"{baseKey}{dialogueIndex}{"-visit"}");
			if (ifExists == null)
			{
				return currentVisitIndex;
			}
			string rawText = ifExists.GetRawText();
			if (int.TryParse(rawText, NumberStyles.Integer, CultureInfo.InvariantCulture, out var result) && result >= 0)
			{
				return result;
			}
			AncientDialogueMissingWarnings.WarnOnce($"invalid_visit:{locTable}:{ifExists.LocEntryKey}:{rawText}", $"[Ancient] Ignoring invalid visit index '{rawText}' in '{locTable}:{ifExists.LocEntryKey}'; expected a non-negative integer.");
			return currentVisitIndex;
		}

		private static (ArchitectAttackers StartAttackers, ArchitectAttackers EndAttackers) ResolveArchitectAttackers(string locTable, string baseKey, int dialogueIndex, bool isArchitect)
		{
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			//IL_000e: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ab: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ac: Unknown result type (might be due to invalid IL or missing references)
			if (!isArchitect)
			{
				return (StartAttackers: (ArchitectAttackers)0, EndAttackers: (ArchitectAttackers)0);
			}
			ArchitectAttackers attackers = (ArchitectAttackers)0;
			ArchitectAttackers attackers2 = (ArchitectAttackers)2;
			TryOverrideAttackers(locTable, $"{baseKey}{dialogueIndex}{"-attack"}", ref attackers2);
			TryOverrideAttackers(locTable, $"{baseKey}{dialogueIndex}{"-startattack"}", ref attackers);
			TryOverrideAttackers(locTable, $"{baseKey}{dialogueIndex}{"-endattack"}", ref attackers2);
			return (StartAttackers: attackers, EndAttackers: attackers2);
		}

		private static void TryOverrideAttackers(string locTable, string key, ref ArchitectAttackers attackers)
		{
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0027: Unknown result type (might be due to invalid IL or missing references)
			//IL_0029: Expected I4, but got Unknown
			LocString ifExists = LocString.GetIfExists(locTable, key);
			if (ifExists != null)
			{
				string rawText = ifExists.GetRawText();
				if (Enum.TryParse<ArchitectAttackers>(rawText, true, out ArchitectAttackers result) && Enum.IsDefined<ArchitectAttackers>(result))
				{
					attackers = (ArchitectAttackers)(int)result;
					return;
				}
				AncientDialogueMissingWarnings.WarnOnce($"invalid_attackers:{locTable}:{key}:{rawText}", $"[Ancient] Ignoring invalid Architect attackers value '{rawText}' in '{locTable}:{key}'. Expected one of: {string.Join(", ", Enum.GetNames<ArchitectAttackers>())}.");
			}
		}

		private static bool DialogueExists(string locTable, string baseKey, int index)
		{
			if (!LocString.Exists(locTable, $"{baseKey}{index}-0.ancient") && !LocString.Exists(locTable, $"{baseKey}{index}-0r.ancient") && !LocString.Exists(locTable, $"{baseKey}{index}-0.char"))
			{
				return LocString.Exists(locTable, $"{baseKey}{index}-0r.char");
			}
			return true;
		}

		private static string? ExistingLine(string locTable, string baseKey, int dialogueIndex, int lineIndex)
		{
			string text = $"{baseKey}{dialogueIndex}-{lineIndex}r.ancient";
			if (LocString.Exists(locTable, text))
			{
				return text;
			}
			text = $"{baseKey}{dialogueIndex}-{lineIndex}r.char";
			if (LocString.Exists(locTable, text))
			{
				return text;
			}
			text = $"{baseKey}{dialogueIndex}-{lineIndex}.ancient";
			if (LocString.Exists(locTable, text))
			{
				return text;
			}
			text = $"{baseKey}{dialogueIndex}-{lineIndex}.char";
			if (!LocString.Exists(locTable, text))
			{
				return null;
			}
			return text;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Emits at most one warning for each missing ancient-event dialogue key while allowing the
	///         current run to continue.
	///     </para>
	///     <para xml:lang="zh-CN">先古之民事件对话键缺失但当前局内流程仍需继续时，每个键至多发出一次警告。</para>
	/// </summary>
	internal static class AncientDialogueMissingWarnings
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly HashSet<string> WarnedKeys = new HashSet<string>();

		internal static void WarnOnce(string key, string message)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			ArgumentException.ThrowIfNullOrWhiteSpace(message, "message");
			using (SyncRoot.EnterScope())
			{
				if (!WarnedKeys.Add(key))
				{
					return;
				}
			}
			RitsuLibFramework.Logger.Warn(message, 1);
		}
	}
	internal sealed class I18NLocTable : LocTable
	{
		private I18NLocTable(string name, Dictionary<string, string> local, Dictionary<string, string> fallback)
		{
			//IL_000e: Unknown result type (might be due to invalid IL or missing references)
			((LocTable)this)..ctor(name, local, (fallback.Count == 0) ? ((LocTable)null) : new LocTable(name, fallback, (LocTable)null));
		}

		internal static I18NLocTable Create(string name, I18N i18N)
		{
			var (local, fallback) = i18N.CaptureLocTableData();
			return new I18NLocTable(name, local, fallback);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Registers virtual localization-table IDs that expose RitsuLib <see cref="T:STS2RitsuLib.Utils.I18N" /> dictionaries
	///         through the game's <c>LocString</c> and <c>LocTable</c> pipeline.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         注册虚拟本地化表 ID，使 RitsuLib 的 <see cref="T:STS2RitsuLib.Utils.I18N" /> 字典可通过游戏的 <c>LocString</c> 和 <c>LocTable</c>
	///         管线访问。
	///     </para>
	/// </summary>
	public static class I18NLocTableBridge
	{
		private static readonly ConcurrentDictionary<string, I18NLocTableRegistration> LocTables = new ConcurrentDictionary<string, I18NLocTableRegistration>(StringComparer.OrdinalIgnoreCase);

		private static readonly Lock RegistrationLock = new Lock();

		/// <summary>
		///     <para xml:lang="en">Builds a virtual localization-table ID in the standard <c>MODID_I18N_STEM</c> form.</para>
		///     <para xml:lang="zh-CN">按标准的 <c>MODID_I18N_STEM</c> 形式构建虚拟本地化表 ID。</para>
		/// </summary>
		public static string GetTableId(string modId, string stem = "DEFAULT")
		{
			return ModContentRegistry.GetCompoundId(modId, "I18N", stem);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers <paramref name="i18N" /> as the translation source for the virtual table ID
		///         <c>MODID_I18N_STEM</c>.
		///     </para>
		///     <para xml:lang="zh-CN">将 <paramref name="i18N" /> 注册为虚拟表 ID <c>MODID_I18N_STEM</c> 的翻译来源。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> if the table was registered or replaced; <see langword="false" /> if
		///         the ID already existed and <paramref name="replaceExisting" /> was <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         成功注册或替换表时为 <see langword="true" />；ID 已存在且 <paramref name="replaceExisting" /> 为
		///         <see langword="false" /> 时为 <see langword="false" />。
		///     </para>
		/// </returns>
		/// <remarks>
		///     <para xml:lang="en">
		///         The bridge owns a localization snapshot outside the game's table collection. It refreshes that
		///         snapshot after <see cref="E:STS2RitsuLib.Utils.I18N.Changed" /> and unregisters it when <paramref name="i18N" /> is disposed.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         桥接在游戏表集合之外持有本地化快照；<see cref="E:STS2RitsuLib.Utils.I18N.Changed" /> 触发后会刷新快照，且
		///         <paramref name="i18N" /> 释放时会自动注销。
		///     </para>
		/// </remarks>
		/// <exception cref="T:System.ObjectDisposedException">
		///     <para xml:lang="en"><paramref name="i18N" /> has already been disposed.</para>
		///     <para xml:lang="zh-CN"><paramref name="i18N" /> 已被释放。</para>
		/// </exception>
		public static bool TryRegister(string modId, I18N i18N, string stem = "DEFAULT", bool replaceExisting = false)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(stem, "stem");
			ArgumentNullException.ThrowIfNull(i18N, "i18N");
			string tableId = GetTableId(modId, stem);
			I18NLocTableRegistration value;
			I18NLocTableRegistration i18NLocTableRegistration;
			using (RegistrationLock.EnterScope())
			{
				if (LocTables.TryGetValue(tableId, out value) && !replaceExisting)
				{
					return false;
				}
				i18NLocTableRegistration = new I18NLocTableRegistration(tableId, i18N);
				LocTables[tableId] = i18NLocTableRegistration;
			}
			value?.Dispose();
			if (!i18N.IsDisposed)
			{
				return true;
			}
			RemoveIfCurrent(tableId, i18NLocTableRegistration);
			throw new ObjectDisposedException("i18N");
		}

		/// <summary>
		///     <para xml:lang="en">Unregisters a virtual table ID previously registered through <see cref="M:STS2RitsuLib.Localization.I18NLocTableBridge.TryRegister(System.String,STS2RitsuLib.Utils.I18N,System.String,System.Boolean)" />.</para>
		///     <para xml:lang="zh-CN">注销先前通过 <see cref="M:STS2RitsuLib.Localization.I18NLocTableBridge.TryRegister(System.String,STS2RitsuLib.Utils.I18N,System.String,System.Boolean)" /> 注册的虚拟表 ID。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> if the table was removed; otherwise, <see langword="false" />.</para>
		///     <para xml:lang="zh-CN">成功移除表时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public static bool TryUnregister(string modId, string stem = "DEFAULT")
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(stem, "stem");
			string tableId = GetTableId(modId, stem);
			I18NLocTableRegistration value;
			using (RegistrationLock.EnterScope())
			{
				if (!LocTables.TryRemove(tableId, out value))
				{
					return false;
				}
			}
			value.Dispose();
			return true;
		}

		internal static bool TryGetLocTable(string tableId, out LocTable locTable)
		{
			using (RegistrationLock.EnterScope())
			{
				if (!LocTables.TryGetValue(tableId, out I18NLocTableRegistration value))
				{
					locTable = null;
					return false;
				}
				locTable = value.CurrentTable;
				return true;
			}
		}

		internal static void RemoveIfCurrent(string tableId, I18NLocTableRegistration registration)
		{
			I18NLocTableRegistration value = null;
			using (RegistrationLock.EnterScope())
			{
				if (LocTables.TryGetValue(tableId, out I18NLocTableRegistration value2) && value2 == registration)
				{
					LocTables.TryRemove(tableId, out value);
				}
			}
			value?.Dispose();
		}
	}
	internal sealed class I18NLocTableRegistration : IDisposable
	{
		private LocTable _currentTable;

		private int _disposed;

		internal I18N I18N { get; }

		internal LocTable CurrentTable => Volatile.Read(in _currentTable);

		private string TableId { get; }

		internal I18NLocTableRegistration(string tableId, I18N i18N)
		{
			TableId = tableId;
			I18N = i18N;
			_currentTable = (LocTable)(object)I18NLocTable.Create(tableId, i18N);
			i18N.Changed += Refresh;
			i18N.Disposed += OnSourceDisposed;
			if (!i18N.IsDisposed)
			{
				return;
			}
			Dispose();
			throw new ObjectDisposedException("i18N");
		}

		public void Dispose()
		{
			if (Interlocked.Exchange(ref _disposed, 1) == 0)
			{
				I18N.Changed -= Refresh;
				I18N.Disposed -= OnSourceDisposed;
			}
		}

		private void Refresh()
		{
			if (Volatile.Read(in _disposed) == 0)
			{
				I18NLocTable value;
				try
				{
					value = I18NLocTable.Create(TableId, I18N);
				}
				catch (ObjectDisposedException)
				{
					I18NLocTableBridge.RemoveIfCurrent(TableId, this);
					return;
				}
				if (Volatile.Read(in _disposed) == 0)
				{
					Volatile.Write(ref _currentTable, (LocTable)(object)value);
				}
			}
		}

		private void OnSourceDisposed(I18N _)
		{
			I18NLocTableBridge.RemoveIfCurrent(TableId, this);
		}
	}
}
namespace STS2RitsuLib.Localization.SmartFormat
{
	/// <summary>
	///     <para xml:lang="en">
	///         Describes a registered SmartFormat extension instance, its implementation type, ordering value,
	///         and owning mod.
	///     </para>
	///     <para xml:lang="zh-CN">描述已注册的 SmartFormat 扩展实例、实现类型、排序值及所属模组。</para>
	/// </summary>
	public sealed record ModSmartFormatExtensionDefinition(string OwnerModId, SmartFormatExtensionKind Kind, Type ImplementationType, int Order, object Instance)
	{
		internal long Sequence { get; init; }

		internal ModSmartFormatExtensionDefinition(string ownerModId, SmartFormatExtensionKind kind, Type implementationType, int order, object instance, long sequence)
			: this(ownerModId, kind, implementationType, order, instance)
		{
			Sequence = sequence;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides a per-mod registry for SmartFormat selector sources and formatters used by the game's
	///         localization formatter.
	///     </para>
	///     <para xml:lang="zh-CN">提供按模组划分的注册表，用于登记游戏本地化格式化器所使用的 SmartFormat 选择器数据源和格式化器。</para>
	/// </summary>
	public sealed class ModSmartFormatExtensionRegistry
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, ModSmartFormatExtensionRegistry> Registries = new Dictionary<string, ModSmartFormatExtensionRegistry>(StringComparer.OrdinalIgnoreCase);

		private static readonly List<ModSmartFormatExtensionDefinition> Formatters = new List<ModSmartFormatExtensionDefinition>();

		private static readonly List<ModSmartFormatExtensionDefinition> Sources = new List<ModSmartFormatExtensionDefinition>();

		private static long _nextSequence;

		private static SmartFormatter? _initializedSmartFormatter;

		private readonly Logger _logger;

		/// <summary>
		///     <para xml:lang="en">Gets the ID of the mod that owns this registry.</para>
		///     <para xml:lang="zh-CN">获取此注册表所属模组的 ID。</para>
		/// </summary>
		public string ModId { get; }

		private ModSmartFormatExtensionRegistry(string modId)
		{
			ModId = modId;
			_logger = RitsuLibFramework.CreateLogger(modId, (LogType)0);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the shared registry for <paramref name="modId" />, creating it on first use. mod IDs are
		///         compared without regard to case.
		///     </para>
		///     <para xml:lang="zh-CN">获取 <paramref name="modId" /> 对应的共享注册表，并在首次使用时创建。模组 ID 比较不区分大小写。</para>
		/// </summary>
		public static ModSmartFormatExtensionRegistry For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (SyncRoot.EnterScope())
			{
				if (Registries.TryGetValue(modId, out ModSmartFormatExtensionRegistry value))
				{
					return value;
				}
				ModSmartFormatExtensionRegistry modSmartFormatExtensionRegistry = new ModSmartFormatExtensionRegistry(modId);
				Registries[modId] = modSmartFormatExtensionRegistry;
				return modSmartFormatExtensionRegistry;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers an existing SmartFormat formatter instance.</para>
		///     <para xml:lang="zh-CN">注册已有的 SmartFormat 格式化器实例。</para>
		/// </summary>
		public void Register(IFormatter formatter, int order = 0)
		{
			ArgumentNullException.ThrowIfNull(formatter, "formatter");
			RegisterCore(SmartFormatExtensionKind.Formatter, ((object)formatter).GetType(), formatter, order);
		}

		/// <summary>
		///     <para xml:lang="en">Creates and registers a SmartFormat formatter of type <typeparamref name="TFormatter" />.</para>
		///     <para xml:lang="zh-CN">创建并注册 <typeparamref name="TFormatter" /> 类型的 SmartFormat 格式化器。</para>
		/// </summary>
		public void Register<TFormatter>(int order = 0) where TFormatter : IFormatter, new()
		{
			Register((IFormatter)(object)new TFormatter(), order);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates and registers the specified SmartFormat formatter type. Invalid types or construction
		///         failures are logged and ignored.
		///     </para>
		///     <para xml:lang="zh-CN">创建并注册指定的 SmartFormat 格式化器类型。无效类型或构造失败会被记录并忽略。</para>
		/// </summary>
		public void RegisterFormatterType(Type formatterType, int order = 0)
		{
			RegisterType(formatterType, typeof(IFormatter), SmartFormatExtensionKind.Formatter, order);
		}

		/// <summary>
		///     <para xml:lang="en">Registers an existing SmartFormat selector-source instance.</para>
		///     <para xml:lang="zh-CN">注册已有的 SmartFormat 选择器数据源实例。</para>
		/// </summary>
		public void RegisterSource(ISource source, int order = 0)
		{
			ArgumentNullException.ThrowIfNull(source, "source");
			RegisterCore(SmartFormatExtensionKind.Source, ((object)source).GetType(), source, order);
		}

		/// <summary>
		///     <para xml:lang="en">Creates and registers a SmartFormat selector source of type <typeparamref name="TSource" />.</para>
		///     <para xml:lang="zh-CN">创建并注册 <typeparamref name="TSource" /> 类型的 SmartFormat 选择器数据源。</para>
		/// </summary>
		public void RegisterSource<TSource>(int order = 0) where TSource : ISource, new()
		{
			RegisterSource((ISource)(object)new TSource(), order);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates and registers the specified SmartFormat selector-source type. Invalid types or
		///         construction failures are logged and ignored.
		///     </para>
		///     <para xml:lang="zh-CN">创建并注册指定的 SmartFormat 选择器数据源类型。无效类型或构造失败会被记录并忽略。</para>
		/// </summary>
		public void RegisterSourceType(Type sourceType, int order = 0)
		{
			RegisterType(sourceType, typeof(ISource), SmartFormatExtensionKind.Source, order);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns a snapshot of all registered formatter definitions, ordered by owning mod ID, ordering
		///         value, implementation type, and registration sequence.
		///     </para>
		///     <para xml:lang="zh-CN">返回全部已注册格式化器定义的快照，依次按所属模组 ID、排序值、实现类型和注册顺序排列。</para>
		/// </summary>
		public static IReadOnlyList<ModSmartFormatExtensionDefinition> GetFormattersSnapshot()
		{
			using (SyncRoot.EnterScope())
			{
				return SortSnapshot(Formatters);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns a snapshot of all registered selector-source definitions, ordered by owning mod ID,
		///         ordering value, implementation type, and registration sequence.
		///     </para>
		///     <para xml:lang="zh-CN">返回全部已注册选择器数据源定义的快照，依次按所属模组 ID、排序值、实现类型和注册顺序排列。</para>
		/// </summary>
		public static IReadOnlyList<ModSmartFormatExtensionDefinition> GetSourcesSnapshot()
		{
			using (SyncRoot.EnterScope())
			{
				return SortSnapshot(Sources);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Finds the first registered formatter with the specified name, using the snapshot order, and
		///         returns its owning mod ID.
		///     </para>
		///     <para xml:lang="zh-CN">按快照顺序查找首个具有指定名称的已注册格式化器，并返回其所属模组 ID。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> if a matching formatter was found; otherwise, <see langword="false" />.</para>
		///     <para xml:lang="zh-CN">找到匹配的格式化器时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public static bool TryGetFormatterOwnerModId(string formatterName, out string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(formatterName, "formatterName");
			using (SyncRoot.EnterScope())
			{
				ModSmartFormatExtensionDefinition[] array = SortSnapshot(Formatters);
				foreach (ModSmartFormatExtensionDefinition modSmartFormatExtensionDefinition in array)
				{
					object instance = modSmartFormatExtensionDefinition.Instance;
					IFormatter val = (IFormatter)((instance is IFormatter) ? instance : null);
					if (val != null && StringComparer.OrdinalIgnoreCase.Equals(val.Name, formatterName))
					{
						modId = modSmartFormatExtensionDefinition.OwnerModId;
						return true;
					}
				}
			}
			modId = string.Empty;
			return false;
		}

		internal static void NotifyInitialized(SmartFormatter formatter)
		{
			ArgumentNullException.ThrowIfNull(formatter, "formatter");
			using (SyncRoot.EnterScope())
			{
				_initializedSmartFormatter = formatter;
			}
		}

		private void RegisterType(Type extensionType, Type expectedType, SmartFormatExtensionKind kind, int order)
		{
			ArgumentNullException.ThrowIfNull(extensionType, "extensionType");
			ArgumentNullException.ThrowIfNull(expectedType, "expectedType");
			if (ValidateExtensionType(extensionType, expectedType, kind))
			{
				object instance;
				try
				{
					instance = Activator.CreateInstance(extensionType);
				}
				catch (Exception ex)
				{
					_logger.ErrorNoTrace($"[SmartFormat] Failed to instantiate {kind} '{extensionType.FullName}': {ex.Message}");
					return;
				}
				RegisterCore(kind, extensionType, instance, order);
			}
		}

		private bool ValidateExtensionType(Type extensionType, Type expectedType, SmartFormatExtensionKind kind)
		{
			if (extensionType.ContainsGenericParameters)
			{
				_logger.ErrorNoTrace($"[SmartFormat] Cannot register open generic {kind} type '{extensionType.FullName}'.");
				return false;
			}
			if (extensionType.IsAbstract || extensionType.IsInterface || !expectedType.IsAssignableFrom(extensionType))
			{
				_logger.ErrorNoTrace($"[SmartFormat] Type '{extensionType.FullName}' must be a concrete implementation of '{expectedType.FullName}'.");
				return false;
			}
			if (extensionType.GetConstructor(Type.EmptyTypes) != null)
			{
				return true;
			}
			_logger.ErrorNoTrace("[SmartFormat] Type '" + extensionType.FullName + "' must have a parameterless constructor.");
			return false;
		}

		private void RegisterCore(SmartFormatExtensionKind kind, Type implementationType, object instance, int order)
		{
			ModSmartFormatExtensionDefinition modSmartFormatExtensionDefinition;
			SmartFormatter initializedSmartFormatter;
			using (SyncRoot.EnterScope())
			{
				modSmartFormatExtensionDefinition = new ModSmartFormatExtensionDefinition(ModId, kind, implementationType, order, instance, _nextSequence++);
				GetBucket(kind).Add(modSmartFormatExtensionDefinition);
				initializedSmartFormatter = _initializedSmartFormatter;
			}
			_logger.Info($"[SmartFormat] Registered {kind}: {implementationType.FullName} (order={order}).", 1);
			if (initializedSmartFormatter != null)
			{
				SmartFormatExtensionInjector.Inject(initializedSmartFormatter, modSmartFormatExtensionDefinition);
			}
		}

		private static List<ModSmartFormatExtensionDefinition> GetBucket(SmartFormatExtensionKind kind)
		{
			if (kind != SmartFormatExtensionKind.Formatter)
			{
				return Sources;
			}
			return Formatters;
		}

		private static ModSmartFormatExtensionDefinition[] SortSnapshot(IEnumerable<ModSmartFormatExtensionDefinition> definitions)
		{
			return definitions.OrderBy<ModSmartFormatExtensionDefinition, string>((ModSmartFormatExtensionDefinition def) => def.OwnerModId, StringComparer.OrdinalIgnoreCase).ThenBy((ModSmartFormatExtensionDefinition def) => def.Order).ThenBy<ModSmartFormatExtensionDefinition, string>((ModSmartFormatExtensionDefinition def) => def.ImplementationType.FullName ?? def.ImplementationType.Name, StringComparer.Ordinal)
				.ThenBy((ModSmartFormatExtensionDefinition def) => def.Sequence)
				.ToArray();
		}
	}
	/// <summary>
	///     <para xml:lang="en">Injects registered mod SmartFormat extensions into an active <c>SmartFormatter</c> instance.</para>
	///     <para xml:lang="zh-CN">将已注册的模组 SmartFormat 扩展注入正在使用的 <c>SmartFormatter</c> 实例。</para>
	/// </summary>
	public static class SmartFormatExtensionInjector
	{
		private sealed class InjectedFormatterNames
		{
			private readonly SmartFormatter _formatter;

			private readonly HashSet<string> _names = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

			private readonly Lock _syncRoot = new Lock();

			public InjectedFormatterNames(SmartFormatter formatter)
			{
				_formatter = formatter;
				foreach (IFormatter formatterExtension in formatter.GetFormatterExtensions())
				{
					if (!string.IsNullOrWhiteSpace(formatterExtension.Name))
					{
						_names.Add(formatterExtension.Name);
					}
				}
			}

			public bool TryAdd(string formatterName)
			{
				using (_syncRoot.EnterScope())
				{
					foreach (IFormatter formatterExtension in _formatter.GetFormatterExtensions())
					{
						if (!string.IsNullOrWhiteSpace(formatterExtension.Name))
						{
							_names.Add(formatterExtension.Name);
						}
					}
					return _names.Add(formatterName);
				}
			}

			public void Remove(string formatterName)
			{
				using (_syncRoot.EnterScope())
				{
					_names.Remove(formatterName);
				}
			}
		}

		private static readonly ConditionalWeakTable<SmartFormatter, InjectedFormatterNames> InjectedFormatterNamesByFormatter = new ConditionalWeakTable<SmartFormatter, InjectedFormatterNames>();

		/// <summary>
		///     <para xml:lang="en">
		///         Injects a snapshot of all registered selector sources first, followed by all registered
		///         formatters.
		///     </para>
		///     <para xml:lang="zh-CN">先注入全部已注册选择器数据源的快照，再注入全部已注册格式化器的快照。</para>
		/// </summary>
		public static void InjectAll(SmartFormatter formatter)
		{
			ArgumentNullException.ThrowIfNull(formatter, "formatter");
			foreach (ModSmartFormatExtensionDefinition item in ModSmartFormatExtensionRegistry.GetSourcesSnapshot())
			{
				Inject(formatter, item);
			}
			foreach (ModSmartFormatExtensionDefinition item2 in ModSmartFormatExtensionRegistry.GetFormattersSnapshot())
			{
				Inject(formatter, item2);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to inject one registered extension into <paramref name="formatter" />. Unsupported
		///         kinds, invalid instances, duplicate formatter names, and injection failures are logged instead of being
		///         propagated.
		///     </para>
		///     <para xml:lang="zh-CN">尝试将一个已注册扩展注入 <paramref name="formatter" />。不支持的类别、无效实例、重复的格式化器名称及注入失败均会被记录，而不会向调用方继续抛出。</para>
		/// </summary>
		public static void Inject(SmartFormatter formatter, ModSmartFormatExtensionDefinition definition)
		{
			ArgumentNullException.ThrowIfNull(formatter, "formatter");
			ArgumentNullException.ThrowIfNull(definition, "definition");
			try
			{
				switch (definition.Kind)
				{
				case SmartFormatExtensionKind.Source:
					InjectSource(formatter, definition);
					return;
				case SmartFormatExtensionKind.Formatter:
					InjectFormatter(formatter, definition);
					return;
				}
				RitsuLibFramework.Logger.Warn($"[SmartFormat] Unknown extension kind '{definition.Kind}' for '{definition.ImplementationType.FullName}'.", 1);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[SmartFormat] Failed to inject {definition.Kind} '{definition.ImplementationType.FullName}' from mod '{definition.OwnerModId}': {ex.Message}");
			}
		}

		private static void InjectSource(SmartFormatter smartFormatter, ModSmartFormatExtensionDefinition definition)
		{
			object instance = definition.Instance;
			ISource val = (ISource)((instance is ISource) ? instance : null);
			if (val == null)
			{
				RitsuLibFramework.Logger.Warn("[SmartFormat] Skipping source '" + definition.ImplementationType.FullName + "' because its instance does not implement ISource.", 1);
				return;
			}
			smartFormatter.AddExtensions((ISource[])(object)new ISource[1] { val });
		}

		private static void InjectFormatter(SmartFormatter smartFormatter, ModSmartFormatExtensionDefinition definition)
		{
			object instance = definition.Instance;
			IFormatter val = (IFormatter)((instance is IFormatter) ? instance : null);
			if (val == null)
			{
				RitsuLibFramework.Logger.Warn("[SmartFormat] Skipping formatter '" + definition.ImplementationType.FullName + "' because its instance does not implement IFormatter.", 1);
				return;
			}
			string name = val.Name;
			if (string.IsNullOrWhiteSpace(name))
			{
				RitsuLibFramework.Logger.Warn($"[SmartFormat] Skipping formatter '{definition.ImplementationType.FullName}' from mod '{definition.OwnerModId}' because its name is empty.", 1);
				return;
			}
			InjectedFormatterNames value = InjectedFormatterNamesByFormatter.GetValue(smartFormatter, (SmartFormatter currentFormatter) => new InjectedFormatterNames(currentFormatter));
			if (!value.TryAdd(name))
			{
				RitsuLibFramework.Logger.Warn($"[SmartFormat] Skipping formatter '{definition.ImplementationType.FullName}' from mod '{definition.OwnerModId}' because formatter name '{name}' is already registered.", 1);
				return;
			}
			try
			{
				smartFormatter.AddExtensions((IFormatter[])(object)new IFormatter[1] { val });
			}
			catch
			{
				value.Remove(name);
				throw;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Identifies the category of a SmartFormat extension registered through RitsuLib.</para>
	///     <para xml:lang="zh-CN">标识通过 RitsuLib 注册的 SmartFormat 扩展类别。</para>
	/// </summary>
	public enum SmartFormatExtensionKind
	{
		/// <summary>
		///     <para xml:lang="en">A SmartFormat selector source.</para>
		///     <para xml:lang="zh-CN">SmartFormat 选择器数据源。</para>
		/// </summary>
		Source,
		/// <summary>
		///     <para xml:lang="en">A SmartFormat formatter.</para>
		///     <para xml:lang="zh-CN">SmartFormat 格式化器。</para>
		/// </summary>
		Formatter
	}
}
