	/// <summary>
	///     <para xml:lang="en">Resolves random prefix selection for virtual I18N tables.</para>
	///     <para xml:lang="zh-CN">解析虚拟 I18N 表的随机前缀选择。</para>
	/// </summary>
	internal class LocStringGetRandomWithPrefixI18NBridgePatch : IPatchMethod
	{
		public static string PatchId => "loc_string_get_random_with_prefix_i18n_bridge";

		public static string Description => "Resolve LocString random prefix selection via registered I18N virtual tables";

		public static bool IsCritical => true;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(LocString), "GetRandomWithPrefix", new Type[3]
				{
					typeof(string),
					typeof(string),
					typeof(Rng)
				})
			};
		}

		[HarmonyPriority(800)]
		public static bool Prefix(string table, string keyPrefix, Rng? rng, ref LocString __result)
		{
			if (!I18NLocTableBridge.TryGetLocTable(table, out LocTable locTable))
			{
				return true;
			}
			if (rng == null)
			{
				rng = Rng.Chaotic;
			}
			__result = rng.NextItem<LocString>((IEnumerable<LocString>)locTable.GetLocStringsWithPrefix(keyPrefix));
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Injects mod-registered SmartFormat extensions after the game creates its localization
	///         formatter.
	///     </para>
	///     <para xml:lang="zh-CN">在游戏创建本地化格式化器后，注入模组注册的 SmartFormat 扩展。</para>
	/// </summary>
	internal sealed class LocManagerLoadLocFormattersPostfixPatch : IPatchMethod
	{
		public static string PatchId => "loc_manager_load_loc_formatters_register_mod_extensions";

		public static string Description => "Inject mod-registered SmartFormat IFormatter / ISource into LocManager";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(LocManager), "LoadLocFormatters")
			};
		}

		public static void Postfix(SmartFormatter ____smartFormatter)
		{
			try
			{
				SmartFormatter val = ____smartFormatter ?? Smart.Default;
				if (val == null)
				{
					RitsuLibFramework.Logger.Warn("[SmartFormat] LocManager.LoadLocFormatters completed but no SmartFormatter instance was available.", 1);
					return;
				}
				SmartFormatExtensionInjector.InjectAll(val);
				ModSmartFormatExtensionRegistry.NotifyInitialized(val);
