	internal static class LocTableCompatibilityPatchHelper
	{
		private static readonly FieldInfo? NameField = typeof(LocTable).GetField("_name", BindingFlags.Instance | BindingFlags.NonPublic);

		private static readonly Lock WarnLock = new Lock();

		private static readonly HashSet<string> WarnedMissingKeys = new HashSet<string>();

		internal static bool ShouldUsePlaceholder(LocTable table, string key, string methodName, out string tableName)
		{
			tableName = GetTableName(table);
			if (!RitsuLibSettingsStore.IsLocTableCompatEnabled())
			{
				return false;
			}
			if (table.HasEntry(key))
			{
				return false;
			}
			WarnMissingKeyOnce(tableName, key, methodName);
			return true;
		}

		internal static string GetTableName(LocTable table)
		{
			return (NameField?.GetValue(table) as string) ?? "<unknown>";
		}

		private static void WarnMissingKeyOnce(string tableName, string key, string methodName)
		{
			string item = $"{tableName}:{key}:{methodName}";
			using (WarnLock.EnterScope())
			{
				if (!WarnedMissingKeys.Add(item))
				{
					return;
				}
			}
			RitsuLibFramework.Logger.Warn($"[Localization][DebugCompat] Missing localization key '{key}' in table '{tableName}' during {methodName}. " + "Resolving to key placeholder (debug compat).", 1);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         When localization-table debug compatibility is enabled, makes <c>LocTable.GetLocString</c>
	///         return a key-preserving placeholder for missing entries and logs one <c>[Localization][DebugCompat]</c> warning
	///         per table, key, and method. Otherwise, the base game's throw-on-missing behavior is unchanged.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         启用本地化表调试兼容时，使 <c>LocTable.GetLocString</c> 为缺失条目返回保留原键的占位值，并按表、键和方法各记录一次
	///         <c>[Localization][DebugCompat]</c> 警告；否则保留原版缺失即抛异常的行为。
	///     </para>
	/// </summary>
	internal class LocTableGetLocStringCompatibilityPatch : IPatchMethod
	{
		public static string PatchId => "loc_table_get_loc_string_debug_compat";

		public static string Description => "Use key placeholder for LocTable.GetLocString missing entries in debug compatibility mode";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(LocTable), "GetLocString", new Type[1] { typeof(string) })
			};
		}

		public static bool Prefix(LocTable __instance, string key, ref LocString __result)
		{
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_001b: Expected O, but got Unknown
			if (!LocTableCompatibilityPatchHelper.ShouldUsePlaceholder(__instance, key, "GetLocString", out string tableName))
			{
				return true;
			}
			__result = new LocString(tableName, key);
			return false;
		}
	}
