	///         启用本地化表调试兼容时，使 <c>LocTable.GetRawText</c> 为缺失条目返回原始键，并按表、键和方法各记录一次
	///         <c>[Localization][DebugCompat]</c> 警告；否则保留原版缺失即抛异常的行为。
	///     </para>
	/// </summary>
	internal class LocTableGetRawTextCompatibilityPatch : IPatchMethod
	{
		public static string PatchId => "loc_table_get_raw_text_debug_compat";

		public static string Description => "Use key placeholder for LocTable.GetRawText missing entries in debug compatibility mode";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(LocTable), "GetRawText", new Type[1] { typeof(string) })
			};
		}

		public static bool Prefix(LocTable __instance, string key, ref string __result)
		{
			if (!LocTableCompatibilityPatchHelper.ShouldUsePlaceholder(__instance, key, "GetRawText", out string _))
