	/// <summary>
	///     <para xml:lang="en">
	///         Prevents THE_ARCHITECT's <c>WinRun</c> path from dereferencing a null dialogue when no
	///         <see cref="T:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogue" /> can be resolved for a registered modded character.
	///     </para>
	///     <para xml:lang="en">
	///         The fallback dialogue has an empty <see cref="P:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogue.Lines" /> collection, preserving
	///         the base game's no-dialogue options and UI path while providing an <c>EndAttackers</c> value for <c>WinRun</c>.
	///         A non-empty uninitialized dialogue would instead leave the room without buttons.
	///     </para>
	///     <para xml:lang="en">
	///         This patch applies only when both the debug-compatibility master switch and the
	///         Ancient/THE_ARCHITECT compatibility setting are enabled. Otherwise, the base-game behavior, including a
	///         possible null-reference exception after PROCEED, remains unchanged.
	///     </para>
	///     <para xml:lang="zh-CN">当已注册的模组角色无法解析出 <see cref="T:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogue" /> 时，避免 THE_ARCHITECT 的 <c>WinRun</c> 流程解引用空对话。</para>
	///     <para xml:lang="zh-CN">
	///         回退对话的 <see cref="P:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogue.Lines" /> 集合为空，因此既能保留原版无对话时的选项和界面流程，又能为 <c>WinRun</c> 提供
	///         <c>EndAttackers</c> 值。若使用包含未初始化台词的非空对话，房间反而会没有可用按钮。
	///     </para>
	///     <para xml:lang="zh-CN">此补丁仅在调试兼容总开关和 Ancient/THE_ARCHITECT 兼容设置同时启用时生效；否则保留原版行为，包括选择 PROCEED 后可能发生的空引用异常。</para>
	/// </summary>
	internal class TheArchitectLoadDialogueMissingFallbackPatch : IPatchMethod
	{
		public static string PatchId => "the_architect_load_dialogue_missing_fallback";

		public static string Description => "THE_ARCHITECT: requires debug compat master + ancient shim; registry characters only; LoadDialogue null fallback";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(TheArchitect), "LoadDialogue", Array.Empty<Type>())
			};
		}

		public static void Postfix(TheArchitect __instance)
		{
			FieldInfo fieldInfo = AccessTools.Field(typeof(TheArchitect), "_dialogue");
			if (fieldInfo == null || fieldInfo.GetValue(__instance) != null)
			{
				return;
			}
			Player owner = ((EventModel)__instance).Owner;
			CharacterModel val = ((owner != null) ? owner.Character : null);
			if (val != null && ModContentRegistry.TryGetOwnerModId(((object)val).GetType(), out string _) && RitsuLibSettingsStore.IsAncientArchitectCompatEnabled())
			{
				string entry = ((AbstractModel)val).Id.Entry;
				AncientDialogueMissingWarnings.WarnOnce("the_architect_dialogue_missing:" + entry, "[Ancient] THE_ARCHITECT has no valid dialogue for character '" + entry + "'. Continuing without lines; add ancients keys under THE_ARCHITECT.talk." + entry + ".0-0.ancient / .char (see RitsuLib Localization & Keywords).");
				AncientDialogue val2 = TryCreateEmptyLinesArchitectDialogueStub();
				if (val2 == null)
				{
					RitsuLibFramework.Logger.ErrorNoTrace("[Ancient] THE_ARCHITECT fallback dialogue could not be constructed (reflection); WinRun may still fail.");
				}
				else
				{
					fieldInfo.SetValue(__instance, val2);
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates an <see cref="T:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogue" /> without invoking its constructor, which requires at
		///         least one line, then assigns an empty <see cref="P:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogue.Lines" /> collection and
		///         <see cref="F:MegaCrit.Sts2.Core.Entities.Ancients.ArchitectAttackers.None" /> to its attacker fields.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在不调用构造函数（其要求至少一行台词）的情况下创建 <see cref="T:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogue" />，随后将
		///         <see cref="P:MegaCrit.Sts2.Core.Entities.Ancients.AncientDialogue.Lines" /> 设为空集合，并将攻击者字段设为 <see cref="F:MegaCrit.Sts2.Core.Entities.Ancients.ArchitectAttackers.None" />。
		///     </para>
		/// </summary>
		private static AncientDialogue? TryCreateEmptyLinesArchitectDialogueStub()
		{
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			//IL_0017: Expected O, but got Unknown
			Type typeFromHandle = typeof(AncientDialogue);
			AncientDialogue val = (AncientDialogue)RuntimeHelpers.GetUninitializedObject(typeFromHandle);
			FieldInfo fieldInfo = FindLinesBackingField(typeFromHandle);
			if (fieldInfo == null)
			{
				return null;
			}
			fieldInfo.SetValue(val, Array.Empty<AncientDialogueLine>());
			FieldInfo[] fields = typeFromHandle.GetFields(BindingFlags.Instance | BindingFlags.NonPublic);
			foreach (FieldInfo fieldInfo2 in fields)
			{
				if (fieldInfo2.FieldType == typeof(ArchitectAttackers))
				{
					fieldInfo2.SetValue(val, (object)(ArchitectAttackers)0);
				}
			}
			return val;
		}

		private static FieldInfo? FindLinesBackingField(Type ancientDialogueType)
		{
			FieldInfo[] fields = ancientDialogueType.GetFields(BindingFlags.Instance | BindingFlags.NonPublic);
			foreach (FieldInfo fieldInfo in fields)
			{
				if (fieldInfo.FieldType == typeof(IReadOnlyList<AncientDialogueLine>))
				{
					return fieldInfo;
				}
			}
			return ancientDialogueType.GetField("<Lines>k__BackingField", BindingFlags.Instance | BindingFlags.NonPublic);
		}
	}
}
namespace STS2RitsuLib.Lifecycle.Patches
{
	/// <summary>
	///     <para xml:lang="en">
	///         Updates multiplayer map-selection synchronization after <see cref="M:MegaCrit.Sts2.Core.Runs.RunManager.GenerateMap" /> finishes
	///         when Act-entry logic replaced the generated <see cref="T:MegaCrit.Sts2.Core.Models.ActModel" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         当章节进入逻辑替换了生成的 <see cref="T:MegaCrit.Sts2.Core.Models.ActModel" /> 时，在 <see cref="M:MegaCrit.Sts2.Core.Runs.RunManager.GenerateMap" />
	///         完成后更新多人地图选择同步状态。
	///     </para>
	/// </summary>
	internal sealed class ActEnterMapSelectionSyncPatch : IPatchMethod
	{
		public static string PatchId => "act_enter_map_selection_sync";

		public static string Description => "After RunManager.GenerateMap completes, call MapSelectionSynchronizer.BeforeMapGenerated when EnterAct replaced the act model";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(RunManager), "GenerateMap", Type.EmptyTypes)
			};
		}

		public static void Postfix(ref Task __result)
		{
			__result = LifecyclePatchTaskBridge.After(__result, (Action)BumpMapSelectionSynchronizerIfRequested);
		}

		private static void BumpMapSelectionSynchronizerIfRequested()
		{
			if (!ModContentRegistry.TryConsumeActEnterPostMapUiMapSyncBump())
			{
				return;
			}
			RunManager instance = RunManager.Instance;
			if (instance != null)
			{
				MapSelectionSynchronizer mapSelectionSynchronizer = instance.MapSelectionSynchronizer;
				if (mapSelectionSynchronizer != null)
				{
					mapSelectionSynchronizer.BeforeMapGenerated();
				}
			}
		}
	}
