	/// <summary>
	///     <para xml:lang="en">
	///         Hooks <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" /> and related initialization to freeze registries, inject models, and publish
	///         model lifecycle events.
	///     </para>
	///     <para xml:lang="zh-CN">挂接 <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" /> 及相关初始化过程，以冻结注册表、注入模型并发布模型生命周期事件。</para>
	/// </summary>
	internal class ModelRegistryLifecyclePatch : IPatchMethod
	{
		public static string PatchId => "model_registry_lifecycle";

		public static string Description => "Publish lifecycle events around ModelDb initialization phases";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[4]
			{
				new ModPatchTarget(typeof(ModelDb), "Init"),
				new ModPatchTarget(typeof(ModelIdSerializationCache), "Init"),
				new ModPatchTarget(typeof(ModelDb), "InitIds"),
				new ModPatchTarget(typeof(ModelDb), "Preload")
			};
		}

		public static void Prefix(MethodBase __originalMethod)
		{
			Type declaringType = __originalMethod.DeclaringType;
			string name = __originalMethod.Name;
			if ((object)declaringType == null)
			{
				return;
			}
			switch (name)
			{
			case "Init":
				if (declaringType == typeof(ModelDb))
				{
					ModContentRegistry.FreezeRegistrations("Init");
					ModKeywordRegistry.FreezeRegistrations("Init");
					ModCardTagRegistry.FreezeRegistrations("Init");
					ModCardPileRegistry.FreezeRegistrations("Init");
					ModTimelineRegistry.FreezeRegistrations("Init");
					ModEpochGatedContentRegistry.FreezeRegistrations("Init");
					ModUnlockRegistry.FreezeRegistrations("Init");
					RitsuLibStartupAudit.Measure("modelDb.validateCollisions", RegistrationConflictDetector.ValidateAndLogModelIdCollisions);
					ReflectionHelperModTypeCache.Refresh("ModelDb.Init");
					RitsuLibStartupAudit.Measure("modelDb.injectDynamicModels", ModContentRegistry.InjectDynamicRegisteredModels);
					RitsuLibFramework.PublishLifecycleEvent(new ModelRegistryInitializingEvent(DateTimeOffset.UtcNow), "ModelRegistryInitializingEvent");
				}
				else if (declaringType == typeof(ModelIdSerializationCache))
				{
					ReflectionHelperModTypeCache.Refresh("ModelIdSerializationCache.Init");
				}
				break;
			case "InitIds":
				if (declaringType == typeof(ModelDb))
				{
					RitsuLibFramework.PublishLifecycleEvent(new ModelIdsInitializingEvent(DateTimeOffset.UtcNow), "ModelIdsInitializingEvent");
				}
				break;
			case "Preload":
				if (declaringType == typeof(ModelDb))
				{
					RitsuLibFramework.PublishLifecycleEvent(new ModelPreloadingStartingEvent(DateTimeOffset.UtcNow), "ModelPreloadingStartingEvent");
				}
				break;
			}
		}

		public static void Postfix(MethodBase __originalMethod)
		{
			switch (__originalMethod.Name)
			{
			case "Init":
				ValidateFrozenRegistrations("Init");
				RitsuLibStartupAudit.Measure("modelDb.warmResolvedCaches", ModContentRegistry.WarmResolvedModelCaches);
				RitsuLibFramework.PublishLifecycleEvent(new ModelRegistryInitializedEvent(ModelDb.AllAbstractModelSubtypes.Length, DateTimeOffset.UtcNow), "ModelRegistryInitializedEvent");
				break;
			case "InitIds":
				RitsuLibFramework.PublishLifecycleEvent(new ModelIdsInitializedEvent(DateTimeOffset.UtcNow), "ModelIdsInitializedEvent");
				break;
			case "Preload":
				RitsuLibFramework.PublishLifecycleEvent(new ModelPreloadingCompletedEvent(DateTimeOffset.UtcNow), "ModelPreloadingCompletedEvent");
				break;
			}
		}

		private static void ValidateFrozenRegistrations(string reason)
		{
			RegistrationFreezeDiagnostics.WarnRecordedFailures(reason);
			ModContentRegistry.ValidateFrozenModelReferences();
			ModEpochGatedContentRegistry.ValidateFrozenModelReferences();
			ModUnlockRegistry.ValidateFrozenModelReferences();
			OrobasAncientUpgradeRegistry.ValidateFrozenRegistrations();
			DustyTomeCardRegistry.ValidateFrozenRegistrations();
			TrashHeapContentRegistry.ValidateFrozenRegistrations();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Clears the base-game mod-type cache at the first initialization point after mods load, before other mods
	///         such as BaseLib consume <see cref="P:MegaCrit.Sts2.Core.Helpers.ReflectionHelper.ModTypes" />.
	///     </para>
