		}
	}
	internal static class ReflectionHelperModTypeCache
	{
		private static readonly FieldInfo? ModTypesField = typeof(ReflectionHelper).GetField("_modTypes", BindingFlags.Static | BindingFlags.NonPublic);

		public static void Refresh(string phase, bool warnIfCached = false)
		{
			if ((object)ModTypesField != null)
			{
				if (warnIfCached && ModTypesField.GetValue(null) is Type[] array)
				{
					RitsuLibFramework.Logger.Warn($"[ModelDb] ReflectionHelper.ModTypes was already cached before {phase} ({array.Length} types). " + "Clearing the cache so post-mod-load scans include all loaded mod types; another mod likely accessed ReflectionHelper.ModTypes before mod loading completed.", 1);
				}
				ModTypesField.SetValue(null, null);
			}
		}
	}
