	/// <summary>
	///     <para xml:lang="en">
	///         Publishes <see cref="T:STS2RitsuLib.RunStartedEvent" /> and <see cref="T:STS2RitsuLib.RunLoadedEvent" /> for
	///         <see cref="T:MegaCrit.Sts2.Core.Runs.RunManager" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过 <see cref="T:MegaCrit.Sts2.Core.Runs.RunManager" /> 发布 <see cref="T:STS2RitsuLib.RunStartedEvent" /> 和
	///         <see cref="T:STS2RitsuLib.RunLoadedEvent" />。
	///     </para>
	/// </summary>
	internal class RunLifecyclePatch : IPatchMethod
	{
		public static string PatchId => "run_lifecycle";

		public static string Description => "Publish lifecycle events for run creation and loading";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[2]
			{
				new ModPatchTarget(typeof(RunManager), "InitializeNewRun"),
				new ModPatchTarget(typeof(RunManager), "InitializeSavedRun", new Type[1] { typeof(SerializableRun) })
			};
		}

		public static void Postfix(MethodBase __originalMethod, RunManager __instance)
		{
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_001b: Invalid comparison between Unknown and I4
			RunState state = __instance.State;
			bool isMultiplayer = __instance.NetService != null && (int)__instance.NetService.Type != 1;
			bool hasValue = __instance.DailyTime.HasValue;
			string name = __originalMethod.Name;
			if (!(name == "InitializeNewRun"))
			{
				if (name == "InitializeSavedRun" && state != null)
				{
					RitsuLibFramework.PublishLifecycleEvent(new RunLoadedEvent(state, isMultiplayer, hasValue, DateTimeOffset.UtcNow), "RunLoadedEvent");
				}
			}
			else if (state != null)
			{
				RitsuLibFramework.PublishLifecycleEvent(new RunStartedEvent(state, isMultiplayer, hasValue, DateTimeOffset.UtcNow), "RunStartedEvent");
			}
		}
	}
