			__result = LoadRunMissingCharacterBlocker.BlockStartRunAsync("Multiplayer", delegate
			{
				((NClickableControl)ConfirmRef.Invoke(__instance)).Enable();
			}, delegate
			{
				((NClickableControl)UnreadyRef.Invoke(__instance)).Enable();
			});
			return false;
		}
