			{
				CharactersRef.Invoke(__instance) = array;
				List<string> list = OptionsRef.Invoke((NPaginator)(object)__instance);
				list.Clear();
				list.AddRange(array.Select((CharacterModel character) => character.Title.GetFormattedText()));
				int num = Mathf.Clamp(CurrentIndexRef.Invoke((NPaginator)(object)__instance), 0, list.Count - 1);
				CurrentIndexRef.Invoke((NPaginator)(object)__instance) = num;
