	/// <summary>
	///     <para xml:lang="en">
	///         Lets the user preview a dropped <c>.run</c> or <c>.save</c> file on the base-game Run History screen
	///         without importing it into the saved run-history list.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         允许用户在原版游戏的游戏历史界面中预览拖入的 <c>.run</c> 或 <c>.save</c> 文件，
	///         而不将其导入已保存的历史记录列表。
	///     </para>
	/// </summary>
	internal class NRunHistoryDroppedFilePreviewPatch : IPatchMethod
	{
		public static string PatchId => "nrun_history_dropped_file_preview";

		public static string Description => "Run history: preview dropped SerializableRun or RunHistory .run/.save files in the history UI";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(FileDropHandler), "OnFilesDropped", new Type[1] { typeof(string[]) })
			};
		}

		public static bool Prefix(string[] files)
		{
			IScreenContext currentScreen = ActiveScreenContext.Instance.GetCurrentScreen();
			NRunHistory val = (NRunHistory)(object)((currentScreen is NRunHistory) ? currentScreen : null);
			if (val == null || !((CanvasItem)val).IsVisibleInTree())
			{
				return true;
			}
			if (files.Length != 1)
			{
				RitsuLibFramework.Logger.Warn("[Saves] Run history preview supports dropping exactly one .run or .save file.", 1);
				return false;
			}
			string text = files[0];
			if (!IsSupportedPreviewFile(text))
			{
				RitsuLibFramework.Logger.Warn("[Saves] Run history preview only supports .run or .save files: " + text, 1);
				return false;
			}
			TaskHelper.RunSafely(RunHistoryDroppedFilePreview.ShowDroppedFile(val, text));
			return false;
		}

		private static bool IsSupportedPreviewFile(string file)
		{
			if (!file.EndsWith(".run", StringComparison.OrdinalIgnoreCase))
			{
				return file.EndsWith(".save", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}
	}
	internal static class RunHistoryDroppedFilePreview
	{
		private static readonly MethodInfo? DisplayRunMethod = AccessTools.DeclaredMethod(typeof(NRunHistory), "DisplayRun", new Type[1] { typeof(RunHistory) }, (Type[])null);

		private static readonly FieldInfo? OutOfDateVisualField = AccessTools.DeclaredField(typeof(NRunHistory), "_outOfDateVisual");

		private static readonly FieldInfo? PrevButtonField = AccessTools.DeclaredField(typeof(NRunHistory), "_prevButton");

		private static readonly FieldInfo? NextButtonField = AccessTools.DeclaredField(typeof(NRunHistory), "_nextButton");

		private static readonly FieldInfo? IndexField = AccessTools.DeclaredField(typeof(NRunHistory), "_index");

		internal static Task ShowDroppedFile(NRunHistory screen, string file)
		{
			//IL_005f: Unknown result type (might be due to invalid IL or missing references)
			if (DisplayRunMethod == null)
			{
				RitsuLibFramework.Logger.Warn("[Saves] Run history preview failed: DisplayRun method was not found.", 1);
				return Task.CompletedTask;
			}
			FileAccess val = FileAccess.Open(file, (ModeFlags)1);
			try
			{
				if (val == null)
				{
					RitsuLibFramework.Logger.Warn($"[Saves] Run history preview could not open '{file}': {FileAccess.GetOpenError()}", 1);
					return Task.CompletedTask;
				}
				if (!TryReadRunHistory(val.GetAsText(false), out RunHistory history, out string error))
				{
					RitsuLibFramework.Logger.Warn("[Saves] Run history preview could not read '" + file + "' as RunHistory or SerializableRun: " + error, 1);
					return Task.CompletedTask;
				}
				DisplayRunMethod.Invoke(screen, new object[1] { history });
				HideOutOfDateVisual(screen);
				DisableNavigation(screen);
				ActiveScreenContext.Instance.FocusOnDefaultControl();
				RitsuLibFramework.Logger.Info("[Saves] Previewing dropped run history file: " + file, 1);
				return Task.CompletedTask;
			}
			finally
			{
				((IDisposable)val)?.Dispose();
			}
		}

		private static bool TryReadRunHistory(string json, out RunHistory history, out string error)
		{
			JsonObject jsonObject = TryParseJsonObject(json);
			if (jsonObject == null)
			{
				history = null;
				error = "File is not a JSON object.";
				return false;
			}
			bool flag = LooksLikeSerializableRun(jsonObject);
			bool flag2 = LooksLikeRunHistory(jsonObject);
			if (!flag && !flag2)
			{
				history = null;
				error = "File is not a RunHistory or SerializableRun save.";
				return false;
			}
			string error2 = "";
			string error3 = "";
			if (flag && TryReadSerializableRun(json, jsonObject, out history, out error2))
			{
				error = "";
				return true;
			}
			if ((flag2 && TryReadVanillaRunHistory(json, out history, out error3)) || (!flag && TryReadSerializableRun(json, jsonObject, out history, out error2)))
			{
				error = "";
				return true;
			}
			error = (flag ? ("SerializableRun parse: " + error2 + "; RunHistory parse: " + error3) : ("RunHistory parse: " + error3 + "; SerializableRun parse: " + error2));
			history = null;
			return false;
		}

		private static bool TryReadVanillaRunHistory(string json, out RunHistory history, out string error)
		{
			//IL_0040: Unknown result type (might be due to invalid IL or missing references)
			ReadSaveResult<RunHistory> val = JsonSerializationUtility.FromJson<RunHistory>(json);
			if (!val.Success || val.SaveData == null)
			{
				history = null;
				error = $"{val.ErrorMessage} ({val.Status})";
				return false;
			}
			history = val.SaveData;
			List<RunHistoryPlayer> players = history.Players;
			if (players != null && players.Count > 0)
			{
				RunHistory val2 = history;
				if (val2 != null && val2.MapPointHistory != null && val2.Acts != null && val2.Modifiers != null)
				{
					error = "";
					return true;
				}
			}
			history = null;
			error = "RunHistory is missing required history fields.";
			return false;
		}

		private static bool TryReadSerializableRun(string json, JsonObject? root, out RunHistory history, out string error)
		{
			//IL_0040: Unknown result type (might be due to invalid IL or missing references)
			ReadSaveResult<SerializableRun> val = JsonSerializationUtility.FromJson<SerializableRun>(json);
			if (!val.Success || val.SaveData == null)
			{
				history = null;
				error = $"{val.ErrorMessage} ({val.Status})";
				return false;
			}
			SerializableRun saveData = val.SaveData;
			if (saveData.Players == null || saveData.Players.Count == 0)
			{
				history = null;
				error = "SerializableRun has no players.";
				return false;
			}
			bool victory = ReadBool(root, "win", "victory", "is_victory") ?? (saveData.WinTime > 0);
			bool valueOrDefault = ReadBool(root, "was_abandoned", "is_abandoned", "abandoned") == true;
			history = CreatePreviewRunHistory(saveData, victory, valueOrDefault);
			error = "";
			return true;
		}

