		private static IEnumerable<SerializableBadge> GetBadgesForPlayer(SerializableRun run, SerializablePlayer player, bool won, bool isAbandoned)
		{
			if (isAbandoned)
			{
				return Array.Empty<SerializableBadge>();
			}
			try
			{
				List<SerializableBadge> list = new List<SerializableBadge>();
				list.AddRange(from badge in ScoreUtility.GetBadges(run, player.NetId, won)
					select badge.ToSerializable());
				return new <>z__ReadOnlyList<SerializableBadge>(list);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[Saves] Failed to calculate preview badges for player {player.NetId}: {ex.Message}", 1);
				return Array.Empty<SerializableBadge>();
			}
		}

		private static JsonObject? TryParseJsonObject(string json)
		{
			try
			{
				return JsonNode.Parse(json) as JsonObject;
			}
			catch
			{
				return null;
			}
		}

		private static bool LooksLikeSerializableRun(JsonObject? root)
		{
			if (root != null)
			{
				if (!root.ContainsKey("current_act_index") && !root.ContainsKey("save_time") && !root.ContainsKey("win_time"))
				{
					return root.ContainsKey("rng");
				}
				return true;
			}
			return false;
		}

		private static bool LooksLikeRunHistory(JsonObject root)
		{
			if (root.ContainsKey("win") && root.ContainsKey("players") && root.ContainsKey("map_point_history"))
			{
				if (!root.ContainsKey("build_id") && !root.ContainsKey("killed_by_encounter") && !root.ContainsKey("killed_by_event"))
				{
					return root.ContainsKey("was_abandoned");
				}
				return true;
			}
			return false;
		}

		private static bool? ReadBool(JsonObject? root, params string[] keys)
		{
			if (root == null)
			{
				return null;
			}
			foreach (string propertyName in keys)
			{
				if (root.TryGetPropertyValue(propertyName, out JsonNode jsonNode) && jsonNode is JsonValue jsonValue)
				{
					if (jsonValue.TryGetValue<bool>(out var value))
					{
						return value;
					}
					if (jsonValue.TryGetValue<string>(out string value2) && bool.TryParse(value2, out var result))
					{
						return result;
					}
				}
			}
			return null;
		}

		private static void HideOutOfDateVisual(NRunHistory screen)
		{
			object? obj = OutOfDateVisualField?.GetValue(screen);
			Control val = (Control)((obj is Control) ? obj : null);
			if (val != null)
			{
				((CanvasItem)val).Visible = false;
			}
		}

		private static void DisableNavigation(NRunHistory screen)
		{
			IndexField?.SetValue(screen, -1);
			DisableButton(PrevButtonField, screen);
			DisableButton(NextButtonField, screen);
		}

		private static void DisableButton(FieldInfo? field, NRunHistory screen)
		{
			object? obj = field?.GetValue(screen);
			NRunHistoryArrowButton val = (NRunHistoryArrowButton)((obj is NRunHistoryArrowButton) ? obj : null);
			if (val != null)
			{
				((NClickableControl)val).Disable();
				((CanvasItem)val).Visible = false;
			}
		}
	}
