	/// <summary>
	///     <para xml:lang="en">
	///         Redirects character and Act lookups on the Run History UI to <see cref="T:STS2RitsuLib.Saves.RunHistoryMissingModelSupport" />,
	///         allowing history from unavailable mods to use deprecated-model placeholders.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将游戏历史界面中的角色与章节查找重定向到 <see cref="T:STS2RitsuLib.Saves.RunHistoryMissingModelSupport" />，
	///         使来自当前不可用模组的历史记录可使用已弃用模型占位项。
	///     </para>
	/// </summary>
	internal class RunHistoryMissingModelDbGetByIdTranspilerPatch : IPatchMethod
	{
		private static readonly MethodInfo CharacterFallback = AccessTools.DeclaredMethod(typeof(RunHistoryMissingModelSupport), "CharacterForRunHistory", (Type[])null, (Type[])null);

		private static readonly MethodInfo ActFallback = AccessTools.DeclaredMethod(typeof(RunHistoryMissingModelSupport), "ActForRunHistory", (Type[])null, (Type[])null);

		public static string PatchId => "run_history_missing_model_db_getbyid_transpile";

		public static string Description => "Transpile run-history methods to use Character/Act fallbacks when ModelDb has no entry";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[7]
			{
				new ModPatchTarget(typeof(NRunHistoryPlayerIcon), "LoadRun", new Type[2]
				{
					typeof(RunHistoryPlayer),
					typeof(RunHistory)
				}),
				new ModPatchTarget(typeof(NMapPointHistory), "LoadHistory", new Type[1] { typeof(RunHistory) }),
				new ModPatchTarget(typeof(NMapPointHistoryEntry), "DoCombatAnimateInEffects", new Type[1] { typeof(RoomType) }),
				new ModPatchTarget(typeof(NRunHistory), "SelectPlayer", new Type[1] { typeof(NRunHistoryPlayerIcon) }),
				new ModPatchTarget(typeof(NRunHistory), "LoadGoldHpAndPotionInfo", new Type[1] { typeof(NRunHistoryPlayerIcon) }),
				new ModPatchTarget(typeof(NRunHistory), "LoadDeathQuote", new Type[2]
				{
					typeof(RunHistory),
					typeof(ModelId)
				}),
				new ModPatchTarget(typeof(NRunHistory), "GetDeathQuote", new Type[3]
				{
					typeof(RunHistory),
					typeof(ModelId),
					typeof(GameOverType)
				})
			};
		}

		/// <summary>
		///     <para xml:lang="en">Redirects supported <c>ModelDb.GetById</c> calls to RitsuLib fallbacks.</para>
		///     <para xml:lang="zh-CN">将受支持的 <c>ModelDb.GetById</c> 调用重定向到 RitsuLib 回退实现。</para>
		/// </summary>
		public static IEnumerable<CodeInstruction> Transpiler(IEnumerable<CodeInstruction> instructions)
		{
			HarmonyIlRewriter harmonyIlRewriter = HarmonyIlRewriter.From(instructions);
			if (!harmonyIlRewriter.FindCalls(IsSupportedModelDbGetById, "[RunHistory] Redirect ModelDb.GetById calls").Any && !harmonyIlRewriter.FindAll(IsFallbackCall, "[RunHistory] existing fallback calls").Any)
			{
				return harmonyIlRewriter.InstructionsChecked("[RunHistory] Redirect ModelDb.GetById calls");
			}
			HarmonyIlRewriteReport harmonyIlRewriteReport = harmonyIlRewriter.RedirectCalls("[RunHistory] Redirect ModelDb.GetById calls", ResolveModelDbFallback, (IReadOnlyList<CodeInstruction> code) => code.Any(IsFallbackCall));
			if (harmonyIlRewriteReport.Changed)
			{
				harmonyIlRewriteReport.RequireApplied();
			}
			return harmonyIlRewriter.InstructionsChecked("[RunHistory] Redirect ModelDb.GetById calls");
		}

		private static MethodInfo? ResolveModelDbFallback(MethodInfo called)
		{
			if (IsModelDbGetByIdFor(called, typeof(CharacterModel)))
			{
				return CharacterFallback;
			}
			if (IsModelDbGetByIdFor(called, typeof(ActModel)))
			{
				return ActFallback;
			}
			return null;
		}

		private static bool IsFallbackCall(CodeInstruction instruction)
		{
			return HarmonyIl.IsCall((MethodInfo method) => method == CharacterFallback || method == ActFallback)(instruction);
		}

		private static bool IsSupportedModelDbGetById(MethodInfo method)
		{
			if (!IsModelDbGetByIdFor(method, typeof(CharacterModel)))
			{
				return IsModelDbGetByIdFor(method, typeof(ActModel));
			}
			return true;
		}

		private static bool IsModelDbGetByIdFor(MethodInfo mi, Type typeArg)
		{
			if (!mi.IsGenericMethod || mi.DeclaringType != typeof(ModelDb))
			{
				return false;
			}
			if (mi.GetGenericMethodDefinition().Name != "GetById")
			{
				return false;
			}
			Type[] genericArguments = mi.GetGenericArguments();
			if (genericArguments.Length == 1)
			{
				return genericArguments[0] == typeArg;
			}
			return false;
		}
	}
