namespace STS2RitsuLib.Keywords
{
	/// <summary>
	///     <para xml:lang="en">
	///         Represents a declarative content-pack keyword entry that can be applied to a
	///         <see cref="T:STS2RitsuLib.Keywords.ModKeywordRegistry" /> in one call.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         表示内容包使用的声明式关键词条目，可通过一次调用应用到
	///         <see cref="T:STS2RitsuLib.Keywords.ModKeywordRegistry" />。
	///     </para>
	/// </summary>
	public sealed record KeywordRegistrationEntry
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets the keyword ID, which is trimmed during registration and compared case-insensitively.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取关键词 ID。注册时会移除其首尾空白，比较时不区分大小写。
		///     </para>
		/// </summary>
		public string Id { get; init; } = string.Empty;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the title localization table.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取标题所在的本地化表。
		///     </para>
		/// </summary>
		public string TitleTable { get; init; } = string.Empty;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the title localization key.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取标题本地化键。
		///     </para>
		/// </summary>
		public string TitleKey { get; init; } = string.Empty;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the description localization table.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取描述所在的本地化表。
		///     </para>
		/// </summary>
		public string DescriptionTable { get; init; } = string.Empty;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the description localization key.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取描述本地化键。
		///     </para>
		/// </summary>
		public string DescriptionKey { get; init; } = string.Empty;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the optional icon resource path.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取可选的图标资源路径。
		///     </para>
		/// </summary>
		public string? IconPath { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the inline keyword text's placement in card descriptions.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取内联关键词文本在卡牌描述中的插入位置。
		///     </para>
		/// </summary>
		public ModKeywordCardDescriptionPlacement CardDescriptionPlacement { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether card and template hover-tip helpers include this keyword.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取卡牌和模板的悬停提示辅助方法是否包含此关键词。
		///     </para>
		/// </summary>
		public bool IncludeInCardHoverTip { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Initializes an entry with card-description placement and hover-tip inclusion behavior.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用卡牌描述插入位置和悬停提示包含行为初始化条目。
		///     </para>
		/// </summary>
		public KeywordRegistrationEntry(string Id, string TitleTable, string TitleKey, string DescriptionTable, string DescriptionKey, string? IconPath = null, ModKeywordCardDescriptionPlacement cardDescriptionPlacement = ModKeywordCardDescriptionPlacement.None, bool includeInCardHoverTip = true)
		{
			this.Id = Id;
			this.TitleTable = TitleTable;
			this.TitleKey = TitleKey;
			this.DescriptionTable = DescriptionTable;
			this.DescriptionKey = DescriptionKey;
			this.IconPath = IconPath;
			CardDescriptionPlacement = cardDescriptionPlacement;
			IncludeInCardHoverTip = includeInCardHoverTip;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers this entry with <paramref name="registry" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将此条目注册到 <paramref name="registry" />。
		///     </para>
		/// </summary>
		public void Register(ModKeywordRegistry registry)
		{
			registry.RegisterCore(Id, TitleTable, TitleKey, DescriptionTable, DescriptionKey, IconPath, CardDescriptionPlacement, IncludeInCardHoverTip);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a <c>card_keywords</c> entry whose ID and localization-key stem are both produced by
		///         <see cref="M:STS2RitsuLib.Content.ModContentRegistry.GetQualifiedKeywordId(System.String,System.String)" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建 <c>card_keywords</c> 条目，其 ID 和本地化键前缀均由
		///         <see cref="M:STS2RitsuLib.Content.ModContentRegistry.GetQualifiedKeywordId(System.String,System.String)" /> 生成。
		///     </para>
		/// </summary>
		public static KeywordRegistrationEntry OwnedCardByLocNamespace(string modId, string localKeywordStem, string? iconPath, ModKeywordCardDescriptionPlacement cardDescriptionPlacement, bool includeInCardHoverTip)
		{
			string qualifiedKeywordId = ModContentRegistry.GetQualifiedKeywordId(modId, localKeywordStem);
			return new KeywordRegistrationEntry(qualifiedKeywordId, "card_keywords", qualifiedKeywordId + ".title", "card_keywords", qualifiedKeywordId + ".description", iconPath, cardDescriptionPlacement, includeInCardHoverTip);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates an owned <c>card_keywords</c> entry using the legacy hover-tip defaults.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用旧版悬停提示默认值创建归属当前模组的 <c>card_keywords</c> 条目。
		///     </para>
		/// </summary>
		public static KeywordRegistrationEntry OwnedCardByLocNamespace(string modId, string localKeywordStem, string? iconPath = null)
		{
			return OwnedCardByLocNamespace(modId, localKeywordStem, iconPath, ModKeywordCardDescriptionPlacement.None, includeInCardHoverTip: true);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Indicates whether <see cref="T:STS2RitsuLib.Keywords.ModKeywordRegistry" /> still accepts keyword registrations from mods.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         表示 <see cref="T:STS2RitsuLib.Keywords.ModKeywordRegistry" /> 当前是否仍接受模组注册关键词。
	///     </para>
	/// </summary>
	public enum KeywordRegistrationState
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Registrations are allowed until the framework freezes this registry alongside the other model
		///         registries.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在框架随其他模型注册表一同冻结此注册表之前，均可注册关键词。
		///     </para>
		/// </summary>
		Open,
		/// <summary>
		///     <para xml:lang="en">
		///         The global keyword registry is sealed, and further registration attempts throw.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         全局关键词注册表已封闭，继续尝试注册会抛出异常。
		///     </para>
		/// </summary>
		Frozen
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Injects registered keyword BBCode into <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> description strings according to
	///         <see cref="P:STS2RitsuLib.Keywords.ModKeywordDefinition.CardDescriptionPlacement" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         根据 <see cref="P:STS2RitsuLib.Keywords.ModKeywordDefinition.CardDescriptionPlacement" />，将已注册关键词的 BBCode
	///         注入 <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> 的描述文本。
	///     </para>
	/// </summary>
	internal static class ModKeywordCardDescriptionInjector
	{
		internal static void AppendFragments(CardModel card, ref string description)
		{
			//IL_002d: Unknown result type (might be due to invalid IL or missing references)
			if (description == null)
			{
				description = string.Empty;
			}
			if (ModKeywordRegistry.IsFrozen && !ModKeywordRegistry.HasCardDescriptionPlacements)
			{
				return;
			}
			List<ModKeywordDefinition> list = null;
			foreach (CardKeyword keyword in card.Keywords)
			{
				if (ModKeywordRegistry.TryGetByCardKeyword(keyword, out ModKeywordDefinition definition) && definition.CardDescriptionPlacement != ModKeywordCardDescriptionPlacement.None)
				{
					if (list == null)
					{
						list = new List<ModKeywordDefinition>();
					}
					list.Add(definition);
				}
			}
			if (list == null)
			{
				return;
			}
			list.Sort((ModKeywordDefinition left, ModKeywordDefinition right) => StringComparer.Ordinal.Compare(left.Id, right.Id));
			List<string> list2 = null;
			List<string> list3 = null;
			foreach (ModKeywordDefinition item in list)
			{
				switch (item.CardDescriptionPlacement)
				{
				case ModKeywordCardDescriptionPlacement.BeforeCardDescription:
					if (list2 == null)
					{
						list2 = new List<string>();
					}
					list2.Add(ModKeywordRegistry.GetCardText(item.Id));
					break;
				case ModKeywordCardDescriptionPlacement.AfterCardDescription:
					if (list3 == null)
					{
						list3 = new List<string>();
					}
					list3.Add(ModKeywordRegistry.GetCardText(item.Id));
					break;
				}
			}
			List<string> list4 = ((description.Length == 0) ? new List<string>() : description.Split('\n').ToList());
			if (list2 != null)
			{
				for (int num = list2.Count - 1; num >= 0; num--)
				{
					list4.Insert(0, list2[num]);
				}
			}
			if (list3 != null)
			{
				list4.AddRange(list3);
			}
			description = string.Join('\n', list4);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Specifies where a registered mod keyword's inline card text (gold title followed by a period) is merged
	///         into the rendered card description, following the native <c>CardKeywordOrder</c> behavior.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         指定已注册模组关键词的内联卡牌文本（金色标题及其后的句号）在渲染后卡牌描述中的插入位置；
	///         其行为遵循原版 <c>CardKeywordOrder</c>。
	///     </para>
	/// </summary>
	public enum ModKeywordCardDescriptionPlacement
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Does not inject keyword text into the card description. This is the default.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         不向卡牌描述注入关键词文本。此项为默认值。
		///     </para>
		/// </summary>
		None,
		/// <summary>
		///     <para xml:lang="en">
		///         Inserts the keyword text before the main description block, like native “before description”
		///         keywords.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将关键词文本插入主要描述文本之前，对应原版的“描述前关键词”。
		///     </para>
		/// </summary>
		BeforeCardDescription,
		/// <summary>
		///     <para xml:lang="en">
		///         Appends the keyword text after the main description block, like native “after description”
		///         keywords.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将关键词文本追加到主要描述文本之后，对应原版的“描述后关键词”。
		///     </para>
		/// </summary>
		AfterCardDescription
	}
