		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether <paramref name="card" /> currently contains the registered mod keyword identified
		///         by <paramref name="keywordId" />. An unregistered ID returns <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <paramref name="card" /> 当前是否包含 <paramref name="keywordId" /> 标识的已注册模组
		///         关键词；ID 未注册时返回 <see langword="false" />。
		///     </para>
		/// </summary>
		public static bool HasModKeyword(this CardModel card, string keywordId)
		{
			//IL_0027: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(card, "card");
			ArgumentException.ThrowIfNullOrWhiteSpace(keywordId, "keywordId");
			if (ModKeywordRegistry.TryGet(keywordId, out ModKeywordDefinition definition))
			{
				return card.Keywords.Contains(definition.CardKeywordValue);
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the target's effective runtime mod keyword IDs in stable order. For a
		///         <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" />, this reverse-maps registered minted values from the native keyword set and
		///         skips native or unregistered values.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         按确定性顺序返回目标当前生效的运行时模组关键词 ID。目标为 <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> 时，此方法
		///         会从原版关键词集合反向映射已注册的动态值，并忽略原版值和未注册值。
		///     </para>
		/// </summary>
		public static IReadOnlyList<string> GetModKeywordIds(this object target)
		{
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(target, "target");
			CardModel val = (CardModel)((target is CardModel) ? target : null);
			if (val == null)
			{
				return Array.Empty<string>();
			}
			List<string> list = new List<string>();
			foreach (CardKeyword keyword in val.Keywords)
			{
				if (ModKeywordRegistry.TryGetByCardKeyword(keyword, out ModKeywordDefinition definition))
				{
					list.Add(definition.Id);
				}
			}
			list.Sort(StringComparer.Ordinal);
			return list;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns hover tips for all effective runtime keyword IDs on <paramref name="target" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <paramref name="target" /> 上所有生效运行时关键词 ID 对应的悬停提示。
		///     </para>
		/// </summary>
		public static IEnumerable<IHoverTip> GetModKeywordHoverTips(this object target)
		{
			ArgumentNullException.ThrowIfNull(target, "target");
			return target.GetModKeywordIds().ToHoverTips();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Checks whether the sequence contains <paramref name="keywordId" />, ignoring case.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         检查序列是否包含 <paramref name="keywordId" />；比较时不区分大小写。
		///     </para>
		/// </summary>
		public static bool ContainsModKeyword(this IEnumerable<string> keywords, string keywordId)
		{
			ArgumentNullException.ThrowIfNull(keywords, "keywords");
			ArgumentException.ThrowIfNullOrWhiteSpace(keywordId, "keywordId");
			return keywords.Any((string id) => string.Equals(id?.Trim(), keywordId.Trim(), StringComparison.OrdinalIgnoreCase));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Converts each distinct, non-empty keyword ID into an <see cref="T:MegaCrit.Sts2.Core.HoverTips.IHoverTip" />. Registered mod
		///         keywords honor <see cref="P:STS2RitsuLib.Keywords.ModKeywordDefinition.IncludeInCardHoverTip" />; other resolvable values use
		///         the native hover-tip factory.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将每个不重复的非空关键词 ID 转换为 <see cref="T:MegaCrit.Sts2.Core.HoverTips.IHoverTip" />。已注册模组关键词会遵循
		///         <see cref="P:STS2RitsuLib.Keywords.ModKeywordDefinition.IncludeInCardHoverTip" />；其他可解析值使用原版悬停提示工厂。
		///     </para>
		/// </summary>
		public static IEnumerable<IHoverTip> ToHoverTips(this IEnumerable<string> keywords)
		{
			//IL_007b: Unknown result type (might be due to invalid IL or missing references)
			//IL_007e: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a4: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(keywords, "keywords");
			List<IHoverTip> list = new List<IHoverTip>();
			foreach (string item in (from id in keywords
				where !string.IsNullOrWhiteSpace(id)
				select id.Trim()).Distinct<string>(StringComparer.OrdinalIgnoreCase))
			{
				if (!ModKeywordRegistry.TryResolveCardKeyword(item, out var value) || (int)value == 0)
				{
					continue;
				}
				if (ModKeywordRegistry.TryGetByCardKeyword(value, out ModKeywordDefinition definition))
				{
					if (definition.IncludeInCardHoverTip)
					{
						list.Add(ModKeywordRegistry.CreateHoverTip(definition.Id));
					}
				}
				else
				{
					list.Add(HoverTipFactory.FromKeyword(value));
				}
			}
			return list;
		}

