	/// <summary>
	///     <para xml:lang="en">
	///         Provides a per-mod registration surface for keywords. Definitions are stored in one global map keyed by
	///         trimmed, case-insensitive IDs. Prefer <c>RegisterOwned</c> or
	///         <c>RegisterCardKeywordOwnedByLocNamespace</c> so IDs follow the same mod-qualified naming convention as
	///         fixed model entries.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供按模组划分的关键词注册入口。所有定义统一存放在全局映射中；ID 会移除首尾空白，比较时
	///         不区分大小写。应优先使用 <c>RegisterOwned</c> 或
	///         <c>RegisterCardKeywordOwnedByLocNamespace</c>，使 ID 遵循与固定模型条目相同的模组限定命名规则。
	///     </para>
	/// </summary>
	public sealed class ModKeywordRegistry
	{
		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, ModKeywordRegistry> Registries = new Dictionary<string, ModKeywordRegistry>(StringComparer.OrdinalIgnoreCase);

		private static readonly Dictionary<string, ModKeywordDefinition> Definitions = new Dictionary<string, ModKeywordDefinition>(StringComparer.OrdinalIgnoreCase);

		private static readonly Dictionary<CardKeyword, ModKeywordDefinition> DefinitionsByCardKeyword = new Dictionary<CardKeyword, ModKeywordDefinition>();

		private static int _hasCardDescriptionPlacements;

		private readonly Logger _logger;

		private readonly string _modId;

		private string? _freezeReason;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether the framework has frozen keyword registration alongside content and timeline
		///         registration during model initialization.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取框架是否已在模型初始化期间随内容和时间线注册表一同冻结关键词注册。
		///     </para>
		/// </summary>
		public static bool IsFrozen { get; private set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets <see cref="P:STS2RitsuLib.Keywords.ModKeywordRegistry.IsFrozen" /> as a <see cref="T:STS2RitsuLib.Keywords.KeywordRegistrationState" /> value.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         以 <see cref="T:STS2RitsuLib.Keywords.KeywordRegistrationState" /> 值的形式获取 <see cref="P:STS2RitsuLib.Keywords.ModKeywordRegistry.IsFrozen" /> 状态。
		///     </para>
		/// </summary>
		public static KeywordRegistrationState State
		{
			get
			{
				if (!IsFrozen)
				{
					return KeywordRegistrationState.Open;
				}
				return KeywordRegistrationState.Frozen;
			}
		}

		internal static bool HasCardDescriptionPlacements => Volatile.Read(in _hasCardDescriptionPlacements) != 0;

		private ModKeywordRegistry(string modId)
		{
			_modId = modId;
			_logger = RitsuLibFramework.CreateLogger(modId, (LogType)0);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the singleton registry for <paramref name="modId" />, creating it on first use.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 <paramref name="modId" /> 对应的单例注册表；首次使用时创建。
		///     </para>
		/// </summary>
		public static ModKeywordRegistry For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			modId = modId.Trim();
			using (SyncRoot.EnterScope())
			{
				if (Registries.TryGetValue(modId, out ModKeywordRegistry value))
				{
					return value;
				}
				ModKeywordRegistry modKeywordRegistry = new ModKeywordRegistry(modId);
				Registries[modId] = modKeywordRegistry;
				return modKeywordRegistry;
			}
		}

		internal static void FreezeRegistrations(string reason)
		{
			ModKeywordRegistry[] array;
			using (SyncRoot.EnterScope())
			{
				if (IsFrozen)
				{
					return;
				}
				IsFrozen = true;
				foreach (ModKeywordRegistry value in Registries.Values)
				{
					value._freezeReason = reason;
				}
				array = Registries.Values.ToArray();
			}
			ModKeywordRegistry[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				array2[i]._logger.Info("[Keywords] Keyword registration is now frozen (" + reason + ").", 1);
			}
		}

