		/// <summary>
		///     <para xml:lang="en">Implements keyword registration after an owned ID has been resolved.</para>
		///     <para xml:lang="zh-CN">在解析归属当前模组的 ID 后执行关键词注册。</para>
		/// </summary>
		internal ModKeywordDefinition RegisterCore(string id, string titleTable, string? titleKey, string? descriptionTable, string? descriptionKey, string? iconPath, ModKeywordCardDescriptionPlacement cardDescriptionPlacement, bool includeInCardHoverTip)
		{
			//IL_0034: Unknown result type (might be due to invalid IL or missing references)
			//IL_0039: Unknown result type (might be due to invalid IL or missing references)
			//IL_0076: Unknown result type (might be due to invalid IL or missing references)
			//IL_010f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0165: Unknown result type (might be due to invalid IL or missing references)
			//IL_0170: Expected I4, but got Unknown
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentException.ThrowIfNullOrWhiteSpace(titleTable, "titleTable");
			EnsureMutable("register keywords");
			string text = NormalizeId(id);
			CardKeyword value = DynamicEnumValueRegistry<CardKeyword>.Register(_modId, text).Value;
			ModKeywordDefinition modKeywordDefinition = new ModKeywordDefinition(_modId, text, titleTable, titleKey ?? (text + ".title"), descriptionTable ?? titleTable, descriptionKey ?? (text + ".description"), iconPath, cardDescriptionPlacement, includeInCardHoverTip)
			{
				CardKeywordValue = value
			};
			using (SyncRoot.EnterScope())
			{
				if (Definitions.TryGetValue(text, out ModKeywordDefinition value2))
				{
					if (value2 != modKeywordDefinition)
					{
						throw new InvalidOperationException($"Keyword '{text}' is already registered by mod '{value2.ModId}' with different data; ids are global and must not be reused with conflicting definitions.");
					}
					return value2;
				}
				Definitions[text] = modKeywordDefinition;
				DefinitionsByCardKeyword[value] = modKeywordDefinition;
				if (modKeywordDefinition.CardDescriptionPlacement != ModKeywordCardDescriptionPlacement.None)
				{
					Volatile.Write(ref _hasCardDescriptionPlacements, 1);
				}
			}
			_logger.Info($"[Keywords] Registered keyword: {text} (CardKeyword=0x{(int)value:X8})", 1);
			return modKeywordDefinition;
		}

