			//IL_0013: Expected I4, but got Unknown
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			try
			{
				value = (CardKeyword)(int)DynamicEnumValueRegistry<CardKeyword>.GetValue(id);
				return true;
			}
			catch (InvalidOperationException)
			{
				value = (CardKeyword)0;
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Tries to resolve a string to a <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardKeyword" />. Registered mod IDs take precedence,
		///         followed by native enum names or numeric literals; any other ID is used to compute a deterministic
		///         dynamic value.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试将字符串解析为 <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardKeyword" />。解析顺序依次为已注册的模组关键词 ID、原版枚举名称
		///         或数字字面量，最后根据其他 ID 计算确定性的动态值。
		///     </para>
		/// </summary>
		public static bool TryResolveCardKeyword(string idOrEnumName, out CardKeyword value)
		{
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			//IL_0036: Expected I4, but got Unknown
			ArgumentException.ThrowIfNullOrWhiteSpace(idOrEnumName, "idOrEnumName");
			if (!TryGet(idOrEnumName, out ModKeywordDefinition definition))
			{
				if (!Enum.TryParse<CardKeyword>(idOrEnumName.Trim(), true, out value))
				{
					return TryGetCardKeyword(idOrEnumName, out value);
				}
				return true;
			}
			value = (CardKeyword)(int)definition.CardKeywordValue;
			return true;
		}

