		///         标准 <c>{energyPrefix:energyIcons(1)}</c> 本地化表达式。
		///     </para>
		/// </summary>
		public static IHoverTip CreateHoverTip(string id)
		{
			//IL_0056: Unknown result type (might be due to invalid IL or missing references)
			ModKeywordDefinition modKeywordDefinition = Get(id);
			Texture2D val = null;
			if (!string.IsNullOrWhiteSpace(modKeywordDefinition.IconPath) && ResourceLoader.Exists(modKeywordDefinition.IconPath, ""))
			{
				val = ResourceLoader.Load<Texture2D>(modKeywordDefinition.IconPath, (string)null, (CacheMode)1);
