		private void EnsureMutable(string operation)
		{
			if (!IsFrozen)
			{
				return;
			}
			throw new InvalidOperationException($"Cannot {operation} after keyword registration has been frozen ({_freezeReason ?? "unknown"}). " + "Register keywords from your mod initializer before model initialization.");
		}

		private static string NormalizeId(string id)
		{
			return id.Trim();
		}
	}
}
