	/// <summary>
	///     <para xml:lang="en">
	///         Removes hover tips for mod keywords whose
	///         <see cref="P:STS2RitsuLib.Keywords.ModKeywordDefinition.IncludeInCardHoverTip" /> is <see langword="false" /> from the native
	///         <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.HoverTips" /> sequence. Minted mod keywords live in
	///         <c>CardModel.Keywords</c>, so the native getter already enumerates them and calls
	///         <see cref="M:MegaCrit.Sts2.Core.HoverTips.HoverTipFactory.FromKeyword(MegaCrit.Sts2.Core.Entities.Cards.CardKeyword)" />; <see cref="T:STS2RitsuLib.Keywords.Patches.HoverTipFactoryFromKeywordPatch" /> supplies the
	///         registered tip. This postfix only implements the explicit opt-out.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         从原版 <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.HoverTips" /> 结果中移除
	///         <see cref="P:STS2RitsuLib.Keywords.ModKeywordDefinition.IncludeInCardHoverTip" /> 为
	///         <see langword="false" /> 的模组关键词悬停提示。动态生成的模组关键词存放在
	///         <c>CardModel.Keywords</c> 中，因此原版属性已会逐一调用
	///         <see cref="M:MegaCrit.Sts2.Core.HoverTips.HoverTipFactory.FromKeyword(MegaCrit.Sts2.Core.Entities.Cards.CardKeyword)" />，并由
	///         <see cref="T:STS2RitsuLib.Keywords.Patches.HoverTipFactoryFromKeywordPatch" /> 提供注册的提示；此后置补丁仅实现显式排除功能。
	///     </para>
	/// </summary>
	internal sealed class CardModelHoverTipsModKeywordPatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_card_model_hover_tips_mod_keyword_exclude";

		public static string Description => "Remove mod keyword hover tips from CardModel.HoverTips when IncludeInCardHoverTip is false";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(CardModel), "HoverTips", (MethodType)1)
			};
		}

		public static void Postfix(CardModel __instance, ref IEnumerable<IHoverTip> __result)
		{
			//IL_001c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_004d: Unknown result type (might be due to invalid IL or missing references)
			HashSet<IHoverTip> toRemove = null;
			foreach (CardKeyword keyword in __instance.Keywords)
			{
				if (ModKeywordRegistry.TryGetByCardKeyword(keyword, out ModKeywordDefinition definition) && !definition.IncludeInCardHoverTip)
				{
					if (toRemove == null)
					{
						toRemove = new HashSet<IHoverTip>();
					}
					toRemove.Add(HoverTipFactory.FromKeyword(keyword));
				}
			}
			if (toRemove != null)
			{
				List<IHoverTip> list = new List<IHoverTip>();
				list.AddRange(__result.Where((IHoverTip tip) => !toRemove.Contains(tip)));
				__result = new <>z__ReadOnlyList<IHoverTip>(list);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
