	///         <see cref="M:MegaCrit.Sts2.Core.HoverTips.HoverTipFactory.FromKeyword(MegaCrit.Sts2.Core.Entities.Cards.CardKeyword)" /> 时，改由
	///         <see cref="M:STS2RitsuLib.Keywords.ModKeywordRegistry.CreateHoverTip(System.String)" /> 创建悬停提示，从而使用注册的标题、描述和
	///         图标，而不是 <c>CardKeywordExtensions.GetLocKeyPrefix</c> 为未知枚举值生成的数字本地化键。
	///         原版关键词和未注册值仍由原方法处理。
	///     </para>
	/// </summary>
	[HarmonyBefore(new string[] { "BaseLib" })]
	[HarmonyPriority(800)]
	internal sealed class HoverTipFactoryFromKeywordPatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_hover_tip_factory_from_keyword_mod_route";

		public static string Description => "Route HoverTipFactory.FromKeyword to ModKeywordRegistry for minted mod CardKeyword values";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(HoverTipFactory), "FromKeyword")
			};
		}

		public static bool Prefix(CardKeyword keyword, ref IHoverTip __result)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			if (!ModKeywordRegistry.TryGetByCardKeyword(keyword, out ModKeywordDefinition definition))
			{
				return true;
			}
			__result = ModKeywordRegistry.CreateHoverTip(definition.Id);
			return false;
		}
	}
