	/// <summary>
	///     <para xml:lang="en">
	///         Synchronizes keyed JSON documents between a <see cref="T:STS2RitsuLib.Interop.ReflectionStaticChannel" /> and an in-memory
	///         JSON tree, for uses such as ModData, RPC payloads, and replicas.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在 <see cref="T:STS2RitsuLib.Interop.ReflectionStaticChannel" /> 与内存 JSON 树之间同步键控文档，可用于 ModData、
	///         RPC 载荷和副本等场景。
	///     </para>
	/// </summary>
	public static class KeyedJsonDomTransport
	{
		/// <summary>
		///     <para xml:lang="en">Default compact serializer options aligned with ModData interop.</para>
		///     <para xml:lang="zh-CN">与 ModData 互操作保持一致的默认紧凑序列化选项。</para>
		/// </summary>
		public static JsonSerializerOptions DefaultJsonSerializerOptions { get; } = new JsonSerializerOptions
		{
			WriteIndented = false,
			DefaultIgnoreCondition = JsonIgnoreCondition.Never,
			IncludeFields = false
		};

		/// <summary>
		///     <para xml:lang="en">
		///         Pulls provider data into a cloned document tree and returns the resulting root node.
		///     </para>
		///     <para xml:lang="zh-CN">将提供方数据拉取到文档树副本中，并返回所得根节点。</para>
		/// </summary>
		/// <param name="key">
		///     <para xml:lang="en">Key passed to the provider's static methods.</para>
		///     <para xml:lang="zh-CN">传给提供方静态方法的键。</para>
		/// </param>
		/// <param name="channel">
		///     <para xml:lang="en">Bound reflection channel for the provider.</para>
		///     <para xml:lang="zh-CN">已为提供方绑定的反射通道。</para>
		/// </param>
		/// <param name="documentRoot">
		///     <para xml:lang="en">
		///         Existing in-memory root to clone before applying provider data, or <see langword="null" />
		///         to start with an empty object.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         应用提供方数据前要复制的现有内存根节点；为 <see langword="null" /> 时从空对象开始。
		///     </para>
		/// </param>
		/// <param name="pathRouting">
		///     <para xml:lang="en">
		///         Optional path routing. <see cref="P:STS2RitsuLib.Interop.KeyedJsonPathRouting.PullPaths" /> is required to use
		///         a bound node getter.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的路径路由；使用已绑定节点读取器时必须提供
		///         <see cref="P:STS2RitsuLib.Interop.KeyedJsonPathRouting.PullPaths" />。
		///     </para>
		/// </param>
		/// <param name="jsonOptions">
		///     <para xml:lang="en">
		///         Serializer options used by the object fallback. Defaults to
		///         <see cref="P:STS2RitsuLib.Interop.KeyedJsonDomTransport.DefaultJsonSerializerOptions" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         对象回退通道使用的序列化选项；默认为 <see cref="P:STS2RitsuLib.Interop.KeyedJsonDomTransport.DefaultJsonSerializerOptions" />。
		///     </para>
		/// </param>
		public static JsonNode? PullFromProviderIntoRoot(string key, ReflectionStaticChannel channel, JsonNode? documentRoot, KeyedJsonPathRouting? pathRouting, JsonSerializerOptions? jsonOptions = null)
		{
			ArgumentNullException.ThrowIfNull(channel, "channel");
			documentRoot = documentRoot?.DeepClone() ?? new JsonObject();
			JsonSerializerOptions options = jsonOptions ?? DefaultJsonSerializerOptions;
			JsonDomChannelDelegates json = channel.Json;
			if (json.GetMergePatch != null)
			{
				JsonNode jsonNode = json.GetMergePatch(key);
				if (jsonNode != null)
				{
					return JsonMergePatch.Apply(documentRoot, jsonNode);
				}
				return documentRoot;
			}
			if (json.GetJsonPatch != null)
			{
				JsonNode jsonNode2 = json.GetJsonPatch(key);
				if (jsonNode2 != null)
				{
					return JsonPatch.Apply(documentRoot, jsonNode2);
				}
				return documentRoot;
			}
			if (json.GetRootObject != null)
			{
				return (json.GetRootObject(key) ?? new JsonObject()).DeepClone();
			}
			if (json.GetNode != null)
			{
				string[] array = pathRouting?.PullPaths;
				if (array != null && array.Length > 0)
				{
					string[] array2 = array;
					for (int i = 0; i < array2.Length; i++)
					{
						string text = JsonPointer.Normalize(array2[i]);
						JsonNode jsonNode3 = json.GetNode(key, text);
						if (jsonNode3 != null)
						{
							if (JsonPointer.IsRoot(text))
							{
								documentRoot = jsonNode3.DeepClone();
							}
							else
							{
								JsonPointer.Set((documentRoot as JsonObject) ?? throw new InvalidOperationException("JSON Pointer subtree pulls require an object document root for non-root paths."), text, jsonNode3);
							}
						}
					}
					return documentRoot;
				}
			}
			if (json.GetJson != null)
			{
				return JsonNode.Parse(json.GetJson(key) ?? "{}") ?? new JsonObject();
			}
			object obj = channel.GetObject(key);
			return JsonNode.Parse((obj == null) ? "{}" : JsonSerializer.Serialize(obj, options)) ?? new JsonObject();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Pushes <paramref name="documentRoot" /> to the highest-priority operation bound by the provider.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过提供方已绑定操作中优先级最高的一项推送 <paramref name="documentRoot" />。
		///     </para>
		/// </summary>
		/// <param name="key">
		///     <para xml:lang="en">Key passed to the provider's static methods.</para>
		///     <para xml:lang="zh-CN">传给提供方静态方法的键。</para>
		/// </param>
		/// <param name="channel">
		///     <para xml:lang="en">Bound reflection channel for the provider.</para>
		///     <para xml:lang="zh-CN">已为提供方绑定的反射通道。</para>
		/// </param>
		/// <param name="documentRoot">
		///     <para xml:lang="en">
		///         In-memory document root to push, or <see langword="null" /> for an empty object.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         要推送的内存文档根节点；为 <see langword="null" /> 时使用空对象。
		///     </para>
		/// </param>
		/// <param name="pathRouting">
		///     <para xml:lang="en">
		///         Optional path routing required when using node setters or merge-at operations for selected subtrees.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的路径路由；使用节点写入器或指定位置合并操作推送选定子树时必须提供。
		///     </para>
		/// </param>
		/// <param name="jsonOptions">
		///     <para xml:lang="en">
		///         Serializer options used by the JSON-text operation. Defaults to
		///         <see cref="P:STS2RitsuLib.Interop.KeyedJsonDomTransport.DefaultJsonSerializerOptions" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         JSON 文本操作使用的序列化选项；默认为 <see cref="P:STS2RitsuLib.Interop.KeyedJsonDomTransport.DefaultJsonSerializerOptions" />。
		///     </para>
		/// </param>
		public static void PushRootToProvider(string key, ReflectionStaticChannel channel, JsonNode? documentRoot, KeyedJsonPathRouting? pathRouting, JsonSerializerOptions? jsonOptions = null)
		{
			ArgumentNullException.ThrowIfNull(channel, "channel");
			if (documentRoot == null)
			{
				documentRoot = new JsonObject();
			}
			JsonSerializerOptions options = jsonOptions ?? DefaultJsonSerializerOptions;
			JsonDomChannelDelegates json = channel.Json;
			if (json.SetRootObject != null)
			{
				JsonObject arg = (documentRoot.DeepClone() as JsonObject) ?? throw new InvalidOperationException("The configured root JSON setter only accepts a JsonObject document root.");
				json.SetRootObject(key, arg);
				return;
			}
			if (json.ApplyMergePatch != null)
			{
				json.ApplyMergePatch(key, documentRoot.DeepClone());
				return;
			}
			if (json.ApplyJsonPatch != null)
			{
				JsonArray arg2 = new JsonArray
				{
					new JsonObject
					{
						["op"] = "replace",
						["path"] = "",
						["value"] = documentRoot.DeepClone()
					}
				};
				json.ApplyJsonPatch(key, arg2);
				return;
			}
			if (json.SetNode != null)
			{
				string[] array = pathRouting?.PushPaths;
				if (array != null && array.Length > 0)
				{
					JsonObject jsonObject = documentRoot as JsonObject;
					if (jsonObject == null)
					{
						jsonObject = new JsonObject();
					}
					string[] array2 = array;
					for (int i = 0; i < array2.Length; i++)
					{
						string text = JsonPointer.Normalize(array2[i]);
						JsonNode jsonNode = JsonPointer.Get(jsonObject, text);
						json.SetNode(key, text, jsonNode?.DeepClone());
					}
					return;
				}
			}
			if (json.MergeObjectAt != null)
			{
				string[] array3 = pathRouting?.MergePushPaths;
				if (array3 != null && array3.Length > 0)
				{
					JsonObject jsonObject2 = documentRoot as JsonObject;
					if (jsonObject2 == null)
					{
						jsonObject2 = new JsonObject();
					}
					string[] array2 = array3;
					for (int i = 0; i < array2.Length; i++)
					{
						string text2 = JsonPointer.Normalize(array2[i]);
						if (JsonPointer.Get(jsonObject2, text2) is JsonObject jsonObject3)
						{
							json.MergeObjectAt(key, text2, (jsonObject3.DeepClone() as JsonObject) ?? new JsonObject());
						}
					}
					return;
				}
			}
			if (json.SetJson != null)
			{
				json.SetJson(key, JsonSerializer.Serialize(documentRoot, options));
			}
			else
			{
				channel.SetObject(key, documentRoot.DeepClone());
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Optional JSON Pointer lists used by <see cref="T:STS2RitsuLib.Interop.KeyedJsonDomTransport" /> for subtree synchronization.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         <see cref="T:STS2RitsuLib.Interop.KeyedJsonDomTransport" /> 用于同步子树的可选 JSON Pointer 列表。
	///     </para>
	/// </summary>
	/// <param name="PullPaths">
	///     <para xml:lang="en">Pointers read from the keyed provider through node getters.</para>
	///     <para xml:lang="zh-CN">通过节点读取器从键控提供方拉取数据时使用的指针。</para>
	/// </param>
	/// <param name="PushPaths">
	///     <para xml:lang="en">Pointers written through node setters when pushing document subtrees.</para>
	///     <para xml:lang="zh-CN">通过节点写入器推送文档子树时使用的指针。</para>
	/// </param>
	/// <param name="MergePushPaths">
	///     <para xml:lang="en">Pointers written through merge-at hooks when pushing object subtrees.</para>
	///     <para xml:lang="zh-CN">
	///         通过指定位置合并钩子推送对象子树时使用的指针。
	///     </para>
	/// </param>
	public sealed record KeyedJsonPathRouting(string[]? PullPaths, string[]? PushPaths, string[]? MergePushPaths);
	/// <summary>
	///     <para xml:lang="en">
	///         Marks a class whose public methods, properties, and nested <see cref="T:STS2RitsuLib.Interop.InteropClassWrapper" /> types
	///         are rewritten at runtime to invoke members in another mod's assemblies without a compile-time reference.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         标记一个类，使其公共方法、属性及嵌套 <see cref="T:STS2RitsuLib.Interop.InteropClassWrapper" /> 类型在运行时被重写，
	///         从而无需编译期引用即可调用另一个模组程序集中的成员。
	///     </para>
	/// </summary>
	/// <param name="modId">
	///     <para xml:lang="en">Manifest ID of the mod required by this interop surface.</para>
	///     <para xml:lang="zh-CN">此互操作接口所依赖模组的清单 ID。</para>
	/// </param>
	/// <param name="type">
	///     <para xml:lang="en">
	///         Default target CLR type name for members without <see cref="T:STS2RitsuLib.Interop.InteropTargetAttribute" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         未指定 <see cref="T:STS2RitsuLib.Interop.InteropTargetAttribute" /> 的成员所使用的默认目标 CLR 类型名。
	///     </para>
	/// </param>
	[AttributeUsage(AttributeTargets.Class, Inherited = false)]
	public sealed class ModInteropAttribute : Attribute
	{
		/// <summary>
		///     <para xml:lang="en">Manifest ID of the target mod required by this interop surface.</para>
		///     <para xml:lang="zh-CN">此互操作接口所依赖目标模组的清单 ID。</para>
		/// </summary>
		public string ModId { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Default remote CLR type name for members without <see cref="T:STS2RitsuLib.Interop.InteropTargetAttribute" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         未指定 <see cref="T:STS2RitsuLib.Interop.InteropTargetAttribute" /> 的成员所使用的默认远端 CLR 类型名。
		///     </para>
		/// </summary>
		public string? Type { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Marks a class whose public methods, properties, and nested <see cref="T:STS2RitsuLib.Interop.InteropClassWrapper" /> types
		///         are rewritten at runtime to invoke members in another mod's assemblies without a compile-time reference.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         标记一个类，使其公共方法、属性及嵌套 <see cref="T:STS2RitsuLib.Interop.InteropClassWrapper" /> 类型在运行时被重写，
		///         从而无需编译期引用即可调用另一个模组程序集中的成员。
		///     </para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">Manifest ID of the mod required by this interop surface.</para>
		///     <para xml:lang="zh-CN">此互操作接口所依赖模组的清单 ID。</para>
		/// </param>
		/// <param name="type">
		///     <para xml:lang="en">
		///         Default target CLR type name for members without <see cref="T:STS2RitsuLib.Interop.InteropTargetAttribute" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         未指定 <see cref="T:STS2RitsuLib.Interop.InteropTargetAttribute" /> 的成员所使用的默认目标 CLR 类型名。
		///     </para>
		/// </param>
		public ModInteropAttribute(string modId, string? type = null)
		{
			if (string.IsNullOrWhiteSpace(modId))
			{
				throw new ArgumentException("Mod ID must not be null or whitespace.", "modId");
			}
			ModId = modId.Trim();
			Type = (string.IsNullOrWhiteSpace(type) ? null : type.Trim());
			base..ctor();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Marks a class whose public methods, properties, and nested <see cref="T:STS2RitsuLib.Interop.InteropClassWrapper" /> types
	///         forward to a CLR type resolved from an assembly-qualified name, such as
	///         <c>Namespace.Type, AssemblyName</c>.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         标记一个类，使其公共方法、属性及嵌套 <see cref="T:STS2RitsuLib.Interop.InteropClassWrapper" /> 类型转发到
	///         由程序集限定名称解析的 CLR 类型，例如 <c>Namespace.Type, AssemblyName</c>。
	///     </para>
	/// </summary>
	/// <param name="type">
	///     <para xml:lang="en">
	///         Default assembly-qualified CLR type name for members without <see cref="T:STS2RitsuLib.Interop.InteropTargetAttribute" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         未指定 <see cref="T:STS2RitsuLib.Interop.InteropTargetAttribute" /> 的成员所使用的默认程序集限定 CLR 类型名。
	///     </para>
	/// </param>
	[AttributeUsage(AttributeTargets.Class, Inherited = false)]
	public sealed class AssemblyInteropAttribute(string? type = null) : Attribute
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Default assembly-qualified CLR type name for members without <see cref="T:STS2RitsuLib.Interop.InteropTargetAttribute" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         未指定 <see cref="T:STS2RitsuLib.Interop.InteropTargetAttribute" /> 的成员所使用的默认程序集限定 CLR 类型名。
		///     </para>
		/// </summary>
		public string? Type { get; } = string.IsNullOrWhiteSpace(type) ? null : type.Trim();
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Marks a method parameter as a wildcard when resolving a target overload. It matches any target
	///         parameter type regardless of assignability.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在解析目标重载时将方法参数标记为通配符；无论可赋值性如何，它都可匹配任意目标参数类型。
	///     </para>
	/// </summary>
	[AttributeUsage(AttributeTargets.Parameter)]
	public sealed class InteropAnyParamAttribute : Attribute
	{
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Overrides the target type or member name for a nested wrapper class, method, or property. With
	///         <see cref="T:STS2RitsuLib.Interop.ModInteropAttribute" />, the type is resolved inside the target mod's assemblies.
	///         With <see cref="T:STS2RitsuLib.Interop.AssemblyInteropAttribute" />, it must be an assembly-qualified CLR type name.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为嵌套包装器类、方法或属性覆盖目标类型或成员名。与 <see cref="T:STS2RitsuLib.Interop.ModInteropAttribute" />
	///         配合时，类型在目标模组的程序集中解析；与 <see cref="T:STS2RitsuLib.Interop.AssemblyInteropAttribute" />
	///         配合时，类型必须使用程序集限定的 CLR 类型名。
	///     </para>
	/// </summary>
	[AttributeUsage(AttributeTargets.Class | AttributeTargets.Method | AttributeTargets.Property, Inherited = false)]
	public sealed class InteropTargetAttribute : Attribute
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Explicit target type name, or <see langword="null" /> when inherited from the enclosing context.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         显式指定的目标类型名；从外层上下文继承时为 <see langword="null" />。
		///     </para>
		/// </summary>
		public string? Type { get; }

		/// <summary>
		///     <para xml:lang="en">Explicit remote member name, or <see langword="null" /> to use the stub name.</para>
		///     <para xml:lang="zh-CN">显式指定的远端成员名；使用存根名称时为 <see langword="null" />。</para>
		/// </summary>
		public string? Name { get; }

		/// <summary>
		///     <para xml:lang="en">Overrides the remote type and, optionally, the member name.</para>
		///     <para xml:lang="zh-CN">覆盖远端类型，并可选择覆盖成员名。</para>
		/// </summary>
		/// <param name="type">
		///     <para xml:lang="en">
		///         Target type name. Use a full type name with <see cref="T:STS2RitsuLib.Interop.ModInteropAttribute" />, or an
		///         assembly-qualified type name with <see cref="T:STS2RitsuLib.Interop.AssemblyInteropAttribute" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         目标类型名。与 <see cref="T:STS2RitsuLib.Interop.ModInteropAttribute" /> 配合时使用完整类型名；与
		///         <see cref="T:STS2RitsuLib.Interop.AssemblyInteropAttribute" /> 配合时使用程序集限定类型名。
		///     </para>
		/// </param>
		/// <param name="name">
		///     <para xml:lang="en">Remote member name when it differs from the stub member.</para>
		///     <para xml:lang="zh-CN">与存根成员名称不同时使用的远端成员名。</para>
		/// </param>
		public InteropTargetAttribute(string type, string? name)
		{
			if (string.IsNullOrWhiteSpace(type))
			{
				throw new ArgumentException("Target type must not be null or whitespace.", "type");
			}
			Type = type.Trim();
			Name = (string.IsNullOrWhiteSpace(name) ? null : name.Trim());
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Overrides only the remote member name; the type comes from the enclosing interop attribute
		///         or wrapper context.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         仅覆盖远端成员名；类型来自外层互操作特性或包装器上下文。
		///     </para>
		/// </summary>
		/// <param name="name">
		///     <para xml:lang="en">Remote member name when it differs from the stub member.</para>
		///     <para xml:lang="zh-CN">与存根成员名称不同时使用的远端成员名。</para>
		/// </param>
		public InteropTargetAttribute(string? name = null)
		{
			Name = (string.IsNullOrWhiteSpace(name) ? null : name.Trim());
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Built-in contributor that processes stubs marked with <see cref="T:STS2RitsuLib.Interop.ModInteropAttribute" /> or
	///         <see cref="T:STS2RitsuLib.Interop.AssemblyInteropAttribute" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         处理带有 <see cref="T:STS2RitsuLib.Interop.ModInteropAttribute" /> 或 <see cref="T:STS2RitsuLib.Interop.AssemblyInteropAttribute" />
	///         标记之存根的内置贡献器。
	///     </para>
	/// </summary>
	public sealed class ModInteropTypeDiscoveryContributor : IModTypeDiscoveryContributor
	{
		/// <inheritdoc />
		public void Contribute(Harmony harmony, IReadOnlyDictionary<string, Assembly> modAssembliesByManifestId, Type modType)
		{
			ModInteropEmitter.TryProcessType(harmony, modAssembliesByManifestId, modType);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Extensible post-mod-load type-discovery pipeline invoked during early localization initialization.
	///         It mirrors BaseLib's scan timing without coupling discovery to one feature.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在本地化初始化早期调用的可扩展模组加载后类型发现管线。它与 BaseLib 的扫描时机保持一致，
	///         但不会将发现流程绑定到单一功能。
	///     </para>
	/// </summary>
	public static class ModTypeDiscoveryHub
	{
		private readonly record struct AssemblyModIdMismatch(string AssemblyName, string CurrentEntryOwnerModId, string RegisteredModId);

		private readonly record struct ScanAssemblyEntry(string ModId, Assembly Assembly);

		private static readonly Lock Gate = new Lock();

		private static readonly List<IModTypeDiscoveryContributor> Contributors = new List<IModTypeDiscoveryContributor>();

		private static readonly Dictionary<string, List<Assembly>> RegisteredAssembliesByModId = new Dictionary<string, List<Assembly>>(StringComparer.Ordinal);

		private static readonly Dictionary<string, AssemblyModIdMismatch> AssemblyModIdMismatches = new Dictionary<string, AssemblyModIdMismatch>(StringComparer.Ordinal);

		private static bool _builtInsRegistered;

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a discovery contributor. Custom contributors must be registered from the mod initializer
		///         before the discovery pipeline runs; <see cref="T:STS2RitsuLib.RitsuLibFramework" /> registers built-ins.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册类型发现贡献器。自定义贡献器必须在类型发现管线运行前由模组初始化器注册；
		///         内置贡献器由 <see cref="T:STS2RitsuLib.RitsuLibFramework" /> 注册。
		///     </para>
		/// </summary>
		public static void RegisterContributor(IModTypeDiscoveryContributor contributor)
		{
			ArgumentNullException.ThrowIfNull(contributor, "contributor");
			using (Gate.EnterScope())
			{
				Contributors.Add(contributor);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Associates an assembly with a mod for the one-shot discovery pipeline. Call it from the mod
		///         initializer before <see cref="T:STS2RitsuLib.Interop.Patches.ModTypeDiscoveryPatch" /> runs. On hosts that expose mod-assembly
		///         associations, RitsuLib also forwards the association to the game after mod initialization.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为一次性类型发现管线建立程序集与模组的关联。请在模组初始化器中、且在
		///         <see cref="T:STS2RitsuLib.Interop.Patches.ModTypeDiscoveryPatch" /> 运行前调用。若宿主公开模组与程序集关联 API，
		///         RitsuLib 还会在模组初始化完成后将该关联同步给游戏。
		///     </para>
		/// </summary>
		public static void RegisterModAssembly(string modId, Assembly assembly)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentNullException.ThrowIfNull(assembly, "assembly");
			modId = modId.Trim();
			using (Gate.EnterScope())
			{
				if (!RegisteredAssembliesByModId.TryGetValue(modId, out List<Assembly> value))
				{
					value = new List<Assembly>();
					RegisteredAssembliesByModId[modId] = value;
				}
				if (!value.Contains(assembly))
				{
					value.Add(assembly);
				}
			}
			RecordAssemblyModIdMismatch(modId, assembly);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Logs the current contributor list and registered mod-to-assembly map.
		///     </para>
		///     <para xml:lang="zh-CN">将当前贡献器列表和已注册的模组到程序集映射写入 RitsuLib 日志。</para>
		/// </summary>
		public static void LogDiagnostics()
		{
			Dictionary<string, IReadOnlyList<Assembly>> source;
			IModTypeDiscoveryContributor[] array;
			using (Gate.EnterScope())
			{
				source = RegisteredAssembliesByModId.ToDictionary<KeyValuePair<string, List<Assembly>>, string, IReadOnlyList<Assembly>>((KeyValuePair<string, List<Assembly>> pair) => pair.Key, (KeyValuePair<string, List<Assembly>> pair) => new global::<>z__ReadOnlyArray<Assembly>(pair.Value.ToArray()), StringComparer.Ordinal);
				array = Contributors.ToArray();
			}
			RitsuLibFramework.Logger.Info("[ModTypeDiscoveryHub] Diagnostics:", 1);
			RitsuLibFramework.Logger.Info($"  Contributors ({array.Length}):", 1);
			IModTypeDiscoveryContributor[] array2 = array;
			foreach (IModTypeDiscoveryContributor modTypeDiscoveryContributor in array2)
			{
				RitsuLibFramework.Logger.Info("    - " + modTypeDiscoveryContributor.GetType().FullName, 1);
			}
			RitsuLibFramework.Logger.Info($"  Registered assemblies ({source.Sum((KeyValuePair<string, IReadOnlyList<Assembly>> pair) => pair.Value.Count)}):", 1);
			foreach (var (text2, source2) in source.OrderBy<KeyValuePair<string, IReadOnlyList<Assembly>>, string>((KeyValuePair<string, IReadOnlyList<Assembly>> kv) => kv.Key, StringComparer.Ordinal))
			{
				foreach (Assembly item in source2.OrderBy<Assembly, string>((Assembly assembly) => assembly.GetName().Name, StringComparer.Ordinal))
				{
					RitsuLibFramework.Logger.Info("    - " + text2 + " -> " + item.GetName().Name, 1);
				}
			}
		}

		internal static void EnsureBuiltInContributorsRegistered()
		{
			using (Gate.EnterScope())
			{
				if (!_builtInsRegistered)
				{
					Contributors.Add(new ModInteropTypeDiscoveryContributor());
					Contributors.Add(new SavedAttachedStateTypeDiscoveryContributor());
					Contributors.Add(new AttributeAutoRegistrationTypeDiscoveryContributor());
					_builtInsRegistered = true;
				}
			}
		}

		internal static void RunOnce(Harmony harmony)
		{
			Dictionary<string, IReadOnlyList<Assembly>> dictionary;
			IModTypeDiscoveryContributor[] array;
			using (Gate.EnterScope())
			{
				dictionary = new Dictionary<string, IReadOnlyList<Assembly>>(StringComparer.Ordinal);
				foreach (KeyValuePair<string, List<Assembly>> item in RegisteredAssembliesByModId)
				{
					dictionary.Add(item.Key, new global::<>z__ReadOnlyArray<Assembly>(item.Value.ToArray()));
				}
				array = Contributors.ToArray();
			}
			AlignRegisteredAssembliesWithGame(dictionary);
			IReadOnlyDictionary<string, Assembly> modAssembliesByManifestId = BuildTargetAssemblyMap(dictionary);
			Assembly[] array2 = (from kv in BuildScanAssemblyMap(dictionary).OrderBy<ScanAssemblyEntry, string>((ScanAssemblyEntry kv) => kv.ModId, StringComparer.Ordinal).ThenBy<ScanAssemblyEntry, string>((ScanAssemblyEntry kv) => kv.Assembly.GetName().Name, StringComparer.Ordinal)
				select kv.Assembly).Distinct().ToArray();
			for (int num = 0; num < array2.Length; num++)
			{
				Type[] array3 = AssemblyTypeScanHelper.GetLoadableTypes(array2[num], RitsuLibFramework.Logger).OrderBy<Type, string>((Type t) => t.FullName ?? t.Name, StringComparer.Ordinal).ToArray();
				foreach (Type modType in array3)
				{
					IModTypeDiscoveryContributor[] array4 = array;
					for (int num3 = 0; num3 < array4.Length; num3++)
					{
						array4[num3].Contribute(harmony, modAssembliesByManifestId, modType);
					}
				}
			}
		}

		internal static bool TryResolveRegisteredModId(Assembly assembly, out string modId)
		{
			ArgumentNullException.ThrowIfNull(assembly, "assembly");
			using (Gate.EnterScope())
			{
				foreach (var (text2, list2) in RegisteredAssembliesByModId)
				{
					if (list2.Contains(assembly))
					{
						modId = text2;
						return true;
					}
				}
			}
			modId = "";
			return false;
		}

		internal static IReadOnlyList<Assembly> GetKnownAssembliesForMod(string modId, Assembly? legacyFallback)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			modId = modId.Trim();
			List<Assembly> result = new List<Assembly>();
			AddRange(Sts2ModManagerCompat.GetLoadedModAssemblies(modId));
			using (Gate.EnterScope())
			{
				if (RegisteredAssembliesByModId.TryGetValue(modId, out List<Assembly> value))
				{
					AddRange(value);
				}
			}
			if (legacyFallback != null)
			{
				Add(legacyFallback);
			}
			return new global::<>z__ReadOnlyArray<Assembly>(result.ToArray());
			void Add(Assembly assembly)
			{
				if (!result.Contains(assembly))
				{
					result.Add(assembly);
				}
			}
			void AddRange(IEnumerable<Assembly> assemblies)
			{
				foreach (Assembly assembly in assemblies)
				{
					Add(assembly);
				}
			}
		}

		internal static void LogAutoRegistrationModIdMismatchSummary()
		{
			AssemblyModIdMismatch[] array;
			using (Gate.EnterScope())
			{
				array = AssemblyModIdMismatches.Values.OrderBy<AssemblyModIdMismatch, string>((AssemblyModIdMismatch mismatch) => mismatch.CurrentEntryOwnerModId, StringComparer.Ordinal).ThenBy<AssemblyModIdMismatch, string>((AssemblyModIdMismatch mismatch) => mismatch.RegisteredModId, StringComparer.Ordinal).ThenBy<AssemblyModIdMismatch, string>((AssemblyModIdMismatch mismatch) => mismatch.AssemblyName, StringComparer.Ordinal)
					.ToArray();
			}
			if (array.Length != 0)
			{
				StringBuilder stringBuilder = new StringBuilder().AppendLine().AppendLine("=== RitsuLib Auto-Registration Mod Id Mismatch Summary ===").AppendLine("RitsuLib detected assemblies whose ModManager/mod_manifest.json assembly ownership id differs from the ModTypeDiscoveryHub.RegisterModAssembly argument.")
					.AppendLine("This issue only affects RitsuLib auto-discovered types and attributes from those assemblies. Explicit content-pack registrations created with RitsuLibFramework.CreateContentPack or ModContentPackBuilder.For are not affected; attribute-driven pack helpers on auto-discovered types are affected.")
					.AppendLine("Current auto-registration owner/registry ids are resolved from ModManager/mod_manifest.json assembly ownership. This can also determine default public entries for auto-discovered models. A future major RitsuLib release is expected to use the RegisterModAssembly argument as the primary owner id instead.")
					.AppendLine("Mod authors should align their manifest id and runtime mod id, or prepare localization/save compatibility before that update.")
					.AppendLine("If a mod intentionally keeps these ids different, annotate the auto-registration source types with [RitsuLibOwnedBy(\"...\")] to pin those auto-discovered entries to a fixed owner id. For inherited auto-registration attributes, place [RitsuLibOwnedBy(\"...\")] on the type that declares the inherited registration attribute.")
					.AppendLine("Mismatches:");
				AssemblyModIdMismatch[] array2 = array;
				for (int num = 0; num < array2.Length; num++)
				{
					AssemblyModIdMismatch assemblyModIdMismatch = array2[num];
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(199, 3, stringBuilder2);
					handler.AppendLiteral("  - assembly='");
					handler.AppendFormatted(assemblyModIdMismatch.AssemblyName);
					handler.AppendLiteral("', currentAutoRegistrationOwnerId='");
					handler.AppendFormatted(assemblyModIdMismatch.CurrentEntryOwnerModId);
					handler.AppendLiteral("' ");
					handler.AppendLiteral("(source: ModManager/mod_manifest.json assembly ownership), registerModAssemblyArgument='");
					handler.AppendFormatted(assemblyModIdMismatch.RegisteredModId);
					handler.AppendLiteral("' (source: ModTypeDiscoveryHub.RegisterModAssembly argument)");
					stringBuilder2.AppendLine(ref handler);
				}
				RitsuLibFramework.Logger.Warn(stringBuilder.ToString().TrimEnd(), 1);
			}
		}

		private static IReadOnlyDictionary<string, Assembly> BuildTargetAssemblyMap(IReadOnlyDictionary<string, IReadOnlyList<Assembly>> registeredAssembliesByModId)
		{
			Dictionary<string, Assembly> dictionary = new Dictionary<string, Assembly>(Sts2ModManagerCompat.BuildLoadedModAssembliesByManifestId(), StringComparer.Ordinal);
			foreach (var (key, readOnlyList2) in registeredAssembliesByModId)
			{
				if (readOnlyList2.Count > 0)
				{
					dictionary[key] = readOnlyList2[0];
				}
			}
			return dictionary;
		}

		private static IReadOnlyList<ScanAssemblyEntry> BuildScanAssemblyMap(IReadOnlyDictionary<string, IReadOnlyList<Assembly>> registeredAssembliesByModId)
		{
			List<ScanAssemblyEntry> result = new List<ScanAssemblyEntry>();
			string key;
			IReadOnlyList<Assembly> value;
			foreach (KeyValuePair<string, IReadOnlyList<Assembly>> item in Sts2ModManagerCompat.BuildLoadedModAssemblyListsByManifestId())
			{
				item.Deconstruct(out key, out value);
				string modId = key;
				foreach (Assembly item2 in value)
				{
					Add(modId, item2);
				}
			}
			foreach (KeyValuePair<string, IReadOnlyList<Assembly>> item3 in registeredAssembliesByModId)
			{
				item3.Deconstruct(out key, out value);
				string modId2 = key;
				foreach (Assembly item4 in value)
				{
					Add(modId2, item4);
				}
			}
			return result;
			void Add(string modId3, Assembly assembly)
			{
				if (!result.Any((ScanAssemblyEntry entry) => entry.Assembly == assembly))
				{
					result.Add(new ScanAssemblyEntry(modId3, assembly));
				}
			}
		}

		private static void AlignRegisteredAssembliesWithGame(IReadOnlyDictionary<string, IReadOnlyList<Assembly>> registeredAssembliesByModId)
		{
			foreach (var (text2, readOnlyList2) in registeredAssembliesByModId)
			{
				foreach (Assembly item in readOnlyList2)
				{
					RecordAssemblyModIdMismatch(text2, item);
					Sts2ModManagerCompat.TryAssociateAssemblyWithMod(text2, item);
				}
			}
		}

		private static void RecordAssemblyModIdMismatch(string registeredModId, Assembly assembly)
		{
			if (!Sts2ModManagerCompat.TryGetLoadedModIdForAssembly(assembly, out string modId) || string.Equals(modId, registeredModId, StringComparison.Ordinal))
			{
				return;
			}
			string assemblyName = assembly.GetName().Name ?? assembly.FullName ?? "<unknown>";
			string key = $"{assembly.FullName}\0{modId}\0{registeredModId}";
			using (Gate.EnterScope())
			{
				AssemblyModIdMismatches.TryAdd(key, new AssemblyModIdMismatch(assemblyName, modId, registeredModId));
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Names of static provider methods bound by the reflection-based keyed-data channel.
	///     </para>
	///     <para xml:lang="zh-CN">由反射式键控数据通道绑定的静态提供方方法名。</para>
	/// </summary>
	public sealed class ReflectionInteropConvention
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Required static object-read method name. Its signature is <c>(string key) → object?</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         必需的静态对象读取方法名；其签名为 <c>(string key) → object?</c>。
		///     </para>
		/// </summary>
		public required string ObjectGetMethodName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Required static object-write method name. Its signature is
		///         <c>(string key, object? value) → void</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         必需的静态对象写入方法名；其签名为 <c>(string key, object? value) → void</c>。
		///     </para>
		/// </summary>
		public required string ObjectSetMethodName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional RFC 7386 JSON Merge Patch getter name:
		///         <c>(string key) → JsonObject?</c> or <c>JsonNode?</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的 RFC 7386 JSON 合并补丁读取方法名：
		///         <c>(string key) → JsonObject?</c> 或 <c>JsonNode?</c>。
		///     </para>
		/// </summary>
		public string? MergePatchGetMethodName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional RFC 7386 JSON Merge Patch application method name:
		///         <c>(string key, JsonNode? patch) → void</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的 RFC 7386 JSON 合并补丁应用方法名：
		///         <c>(string key, JsonNode? patch) → void</c>。
		///     </para>
		/// </summary>
		public string? MergePatchApplyMethodName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional RFC 6902 JSON Patch getter name:
		///         <c>(string key) → JsonArray?</c> or another <c>JsonNode?</c> subtype.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的 RFC 6902 JSON Patch 读取方法名：
		///         <c>(string key) → JsonArray?</c> 或其他 <c>JsonNode?</c> 子类型。
		///     </para>
		/// </summary>
		public string? JsonPatchGetMethodName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional RFC 6902 JSON Patch application method name:
		///         <c>(string key, JsonArray patch) → void</c> or
		///         <c>(string key, JsonNode? patch) → void</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的 RFC 6902 JSON Patch 应用方法名：
		///         <c>(string key, JsonArray patch) → void</c> 或
		///         <c>(string key, JsonNode? patch) → void</c>。
		///     </para>
		/// </summary>
		public string? JsonPatchApplyMethodName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional JSON Pointer node-read method name:
		///         <c>(string key, string jsonPointer) → JsonNode?</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的 JSON Pointer 节点读取方法名：
		///         <c>(string key, string jsonPointer) → JsonNode?</c>。
		///     </para>
		/// </summary>
		public string? NodeGetMethodName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional JSON Pointer node-write method name:
		///         <c>(string key, string jsonPointer, JsonNode? node) → void</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的 JSON Pointer 节点写入方法名：
		///         <c>(string key, string jsonPointer, JsonNode? node) → void</c>。
		///     </para>
		/// </summary>
		public string? NodeSetMethodName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional method name for merging a <see cref="T:System.Text.Json.Nodes.JsonObject" /> at a pointer:
		///         <c>(string key, string jsonPointer, JsonObject value) → void</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的指定位置对象合并方法名：
		///         <c>(string key, string jsonPointer, JsonObject value) → void</c>。
		///     </para>
		/// </summary>
		public string? ObjectMergeAtMethodName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional complete-document JSON text getter name: <c>(string key) → string?</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的完整文档 JSON 文本读取方法名：<c>(string key) → string?</c>。
		///     </para>
		/// </summary>
		public string? TypedGetJsonMethodName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional complete-document JSON text setter name:
		///         <c>(string key, string json) → void</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的完整文档 JSON 文本写入方法名：
		///         <c>(string key, string json) → void</c>。
		///     </para>
		/// </summary>
		public string? TypedSetJsonMethodName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional root-object getter name:
		///         <c>(string key) → JsonObject?</c>, or <c>(string key) → JsonNode?</c> whose returned value must
		///         be a <c>JsonObject</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的根对象读取方法名：
		///         <c>(string key) → JsonObject?</c>，或返回值必须是 <c>JsonObject</c> 的
		///         <c>(string key) → JsonNode?</c>。
		///     </para>
		/// </summary>
		public string? TypedGetJsonObjectMethodName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional root-object setter name:
		///         <c>(string key, JsonObject root) → void</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的根对象写入方法名：
		///         <c>(string key, JsonObject root) → void</c>。
		///     </para>
		/// </summary>
		public string? TypedSetJsonObjectMethodName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Convention used by <c>CreateRitsuLibModDataSchema</c> and ModData runtime interop providers.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         <c>CreateRitsuLibModDataSchema</c> 和 ModData 运行时互操作提供方使用的约定。
		///     </para>
		/// </summary>
		public static ReflectionInteropConvention ModData { get; } = new ReflectionInteropConvention
		{
			ObjectGetMethodName = "GetRitsuLibModDataValue",
			ObjectSetMethodName = "SetRitsuLibModDataValue",
			MergePatchGetMethodName = "GetRitsuLibModDataMergePatch",
			MergePatchApplyMethodName = "ApplyRitsuLibModDataMergePatch",
			JsonPatchGetMethodName = "GetRitsuLibModDataJsonPatch",
			JsonPatchApplyMethodName = "ApplyRitsuLibModDataJsonPatch",
			NodeGetMethodName = "GetRitsuLibModDataNode",
			NodeSetMethodName = "SetRitsuLibModDataNode",
			ObjectMergeAtMethodName = "MergeRitsuLibModDataObject",
			TypedGetJsonMethodName = "GetRitsuLibModDataJson",
			TypedSetJsonMethodName = "SetRitsuLibModDataJson",
			TypedGetJsonObjectMethodName = "GetRitsuLibModDataJsonObject",
			TypedSetJsonObjectMethodName = "SetRitsuLibModDataJsonObject"
		};

		/// <summary>
		///     <para xml:lang="en">
		///         Object-access convention for settings runtime interop. Optional JSON document method names remain
		///         unset for compatibility; typed Boolean, integer, floating-point, and string accessors are handled
		///         by the settings runtime mirror.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         设置运行时互操作使用的对象访问约定。为保持兼容，可选 JSON 文档方法名均未设置；
		///         布尔值、整数、浮点数和字符串的类型化访问仍由设置运行时镜像处理。
		///     </para>
		/// </summary>
		public static ReflectionInteropConvention SettingsRuntimeInterop { get; } = new ReflectionInteropConvention
		{
			ObjectGetMethodName = "GetRitsuLibSettingValue",
			ObjectSetMethodName = "SetRitsuLibSettingValue"
		};
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Reflection-bound static accessors for generic keyed data exchange, such as persistence,
	///         settings documents, and network payloads.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         用于通用键控数据交换的反射绑定静态访问器，可用于持久化、设置文档和网络载荷等场景。
	///     </para>
	/// </summary>
	public sealed class ReflectionStaticChannel
	{
		/// <summary>
		///     <para xml:lang="en">Provider type targeted by the bound delegates.</para>
		///     <para xml:lang="zh-CN">已绑定委托所指向的提供方类型。</para>
		/// </summary>
		public Type ProviderType { get; }

		/// <summary>
		///     <para xml:lang="en">Compiled object getter with the signature <c>key → object?</c>.</para>
		///     <para xml:lang="zh-CN">签名为 <c>key → object?</c> 的已编译对象读取器。</para>
		/// </summary>
		public Func<string, object?> GetObject { get; }

		/// <summary>
		///     <para xml:lang="en">Compiled object setter with the signature <c>(key, value) → void</c>.</para>
		///     <para xml:lang="zh-CN">签名为 <c>(key, value) → void</c> 的已编译对象写入器。</para>
		/// </summary>
		public Action<string, object?> SetObject { get; }

		/// <summary>
		///     <para xml:lang="en">Optional JSON document operations bound for this provider.</para>
		///     <para xml:lang="zh-CN">为此提供方绑定的可选 JSON 文档操作。</para>
		/// </summary>
		public JsonDomChannelDelegates Json { get; }

		internal ReflectionStaticChannel(Type providerType, Func<string, object?> getObject, Action<string, object?> setObject, JsonDomChannelDelegates json)
		{
			ProviderType = providerType;
			GetObject = getObject;
			SetObject = setObject;
			Json = json;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Builds <see cref="T:STS2RitsuLib.Interop.ReflectionStaticChannel" /> instances from static method naming conventions.
	///     </para>
	///     <para xml:lang="zh-CN">根据静态方法命名约定构建 <see cref="T:STS2RitsuLib.Interop.ReflectionStaticChannel" /> 实例。</para>
	/// </summary>
	public static class ReflectionStaticChannelBinder
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Binds the required object accessors and any compatible optional JSON operations described by
		///         <paramref name="convention" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         绑定 <paramref name="convention" /> 描述的必需对象访问器及所有签名兼容的可选 JSON 操作。
		///     </para>
		/// </summary>
		/// <param name="providerType">
		///     <para xml:lang="en">Static-method provider type to inspect.</para>
		///     <para xml:lang="zh-CN">要检查的静态方法提供方类型。</para>
		/// </param>
		/// <param name="convention">
		///     <para xml:lang="en">Method names for required object accessors and optional JSON operations.</para>
		///     <para xml:lang="zh-CN">必需对象访问器和可选 JSON 操作的方法名。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A channel containing the compiled delegates.</para>
		///     <para xml:lang="zh-CN">包含已编译委托的通道。</para>
		/// </returns>
		/// <exception cref="T:System.InvalidOperationException">
		///     <para xml:lang="en">The required object methods are missing or have incompatible signatures.</para>
		///     <para xml:lang="zh-CN">必需的对象方法缺失或签名不兼容。</para>
		/// </exception>
		public static ReflectionStaticChannel Bind(Type providerType, ReflectionInteropConvention convention)
		{
			ArgumentNullException.ThrowIfNull(providerType, "providerType");
			ArgumentNullException.ThrowIfNull(convention, "convention");
			ArgumentException.ThrowIfNullOrWhiteSpace(convention.ObjectGetMethodName, "convention.ObjectGetMethodName");
			ArgumentException.ThrowIfNullOrWhiteSpace(convention.ObjectSetMethodName, "convention.ObjectSetMethodName");
			string text = convention.ObjectGetMethodName.Trim();
			string text2 = convention.ObjectSetMethodName.Trim();
			MethodInfo method = providerType.GetMethod(text, BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, new Type[1] { typeof(string) });
			MethodInfo method2 = providerType.GetMethod(text2, BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, new Type[2]
			{
				typeof(string),
				typeof(object)
			});
			if (method == null || method2 == null)
			{
				throw new InvalidOperationException($"Provider {providerType.FullName} requires static {text}(string) and {text2}(string, object).");
			}
			if (method.ReturnType == typeof(void) || method.ContainsGenericParameters)
			{
				throw new InvalidOperationException($"Provider method {providerType.FullName}.{text}(string) must return a value.");
			}
			if (method2.ReturnType != typeof(void) || method2.ContainsGenericParameters)
			{
				throw new InvalidOperationException($"Provider method {providerType.FullName}.{text2}(string, object) must return void.");
			}
			MethodInfo method3 = (string.IsNullOrWhiteSpace(convention.MergePatchGetMethodName) ? null : providerType.GetMethod(convention.MergePatchGetMethodName.Trim(), BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, new Type[1] { typeof(string) }));
			MethodInfo method4 = (string.IsNullOrWhiteSpace(convention.MergePatchApplyMethodName) ? null : (providerType.GetMethod(convention.MergePatchApplyMethodName.Trim(), BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, new Type[2]
			{
				typeof(string),
				typeof(JsonNode)
			}) ?? providerType.GetMethod(convention.MergePatchApplyMethodName.Trim(), BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, new Type[2]
			{
				typeof(string),
				typeof(JsonObject)
			})));
			MethodInfo method5 = (string.IsNullOrWhiteSpace(convention.JsonPatchGetMethodName) ? null : providerType.GetMethod(convention.JsonPatchGetMethodName.Trim(), BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, new Type[1] { typeof(string) }));
			MethodInfo method6 = (string.IsNullOrWhiteSpace(convention.JsonPatchApplyMethodName) ? null : (providerType.GetMethod(convention.JsonPatchApplyMethodName.Trim(), BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, new Type[2]
			{
