	internal sealed class SavedAttachedStateTypeDiscoveryContributor : IModTypeDiscoveryContributor
	{
		public void Contribute(Harmony harmony, IReadOnlyDictionary<string, Assembly> modAssembliesByManifestId, Type modType)
		{
			if (modType.ContainsGenericParameters)
			{
				return;
			}
			FieldInfo[] fields = modType.GetFields(BindingFlags.DeclaredOnly | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			foreach (FieldInfo fieldInfo in fields)
			{
				if (IsSavedAttachedStateField(fieldInfo, modAssembliesByManifestId))
				{
					fieldInfo.GetValue(null);
				}
			}
		}

		private static bool IsSavedAttachedStateField(FieldInfo field, IReadOnlyDictionary<string, Assembly> modAssembliesByManifestId)
		{
			Type fieldType;
			try
			{
				fieldType = field.FieldType;
			}
			catch (Exception exception) when (IsFieldTypeResolutionFailure(exception))
			{
				LogFieldTypeResolutionFailure(field, modAssembliesByManifestId, exception);
				return false;
			}
			if (fieldType.ContainsGenericParameters)
			{
				return false;
			}
			if (fieldType.IsGenericType)
			{
				return fieldType.GetGenericTypeDefinition() == typeof(SavedAttachedState<, >);
			}
			return false;
		}

		private static void LogFieldTypeResolutionFailure(FieldInfo field, IReadOnlyDictionary<string, Assembly> modAssembliesByManifestId, Exception exception)
		{
			Type? declaringType = field.DeclaringType;
			Assembly assembly = declaringType?.Assembly;
			string value = ((assembly == null) ? "<unknown>" : ResolveModId(assembly, modAssembliesByManifestId));
			string value2 = assembly?.FullName ?? "<unknown assembly>";
			string value3 = ((assembly == null) ? "<unknown>" : GetAssemblyPath(assembly));
			string value4 = declaringType?.FullName ?? "<unknown type>";
			RitsuLibFramework.Logger.Warn($"[ModTypeDiscoveryHub] Skipped an unresolvable static field while discovering SavedAttachedState registrations. ModId='{value}', Assembly='{value2}', Path='{value3}', DeclaringType='{value4}', Field='{field.Name}', ResolutionFailure='{exception.GetType().Name}: {exception.Message}'", 1);
		}

		private static string ResolveModId(Assembly assembly, IReadOnlyDictionary<string, Assembly> modAssembliesByManifestId)
		{
			if (Sts2ModManagerCompat.TryGetLoadedModIdForAssembly(assembly, out string modId) || ModTypeDiscoveryHub.TryResolveRegisteredModId(assembly, out modId))
			{
				return modId;
			}
			foreach (var (result, assembly3) in modAssembliesByManifestId)
			{
				if (assembly3 == assembly)
				{
					return result;
				}
			}
			return "<unknown>";
		}

		private static string GetAssemblyPath(Assembly assembly)
		{
			if (assembly.IsDynamic)
			{
				return "<dynamic>";
			}
			string location = assembly.Location;
			if (!string.IsNullOrWhiteSpace(location))
			{
				return location;
			}
			return "<unavailable>";
		}

		private static bool IsFieldTypeResolutionFailure(Exception exception)
		{
			if (exception is TypeLoadException || exception is FileNotFoundException || exception is FileLoadException || exception is BadImageFormatException)
			{
				return true;
			}
			return false;
		}
	}
