		private static bool HasSavedProperty(Type modelType)
		{
			return modelType.GetProperties(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic).Any((PropertyInfo property) => ((MemberInfo)property).GetCustomAttribute<SavedPropertyAttribute>() != null);
		}

		private static IEnumerable<Type> GetModModelTypesWithSavedProperties()
		{
			return (from type in Enumerable.ThenBy(ModManager.GetLoadedMods().SelectMany((Mod mod) => from assembly in Sts2ModManagerCompat.GetAssemblies(mod)
					select new
					{
						ModId = (mod.manifest?.id ?? assembly.GetName().Name ?? mod.path),
						Assembly = assembly
					}).OrderBy(mod => mod.ModId, StringComparer.Ordinal), mod => mod.Assembly.FullName, StringComparer.Ordinal).SelectMany(mod => AssemblyTypeScanHelper.GetLoadableTypes(mod.Assembly, RitsuLibFramework.Logger))
				where (object)type != null && !type.IsAbstract && !type.IsInterface && typeof(AbstractModel).IsAssignableFrom(type) && HasSavedProperty(type)
				select type).Distinct().OrderBy<Type, string>((Type type) => type.Assembly.GetName().Name, StringComparer.Ordinal).ThenBy<Type, string>((Type type) => type.Assembly.FullName, StringComparer.Ordinal)
				.ThenBy<Type, string>((Type type) => type.FullName ?? type.Name, StringComparer.Ordinal);
		}

		private static int GetPropertyNameCount()
		{
			return GetNetIdToPropertyNameMap()?.Count ?? 0;
		}

		internal static bool RebuildDeterministicNetIdTableForSettings()
		{
			bool result = (UsesDeterministicNetIdTable = SortNetIdTable(requireMultipleEntries: true));
			RefreshNetIdBitSize();
			return result;
		}

		private static void RefreshNetIdBitSize()
		{
			int propertyNameCount = GetPropertyNameCount();
			int num = ((propertyNameCount > 1) ? Mathf.CeilToInt(Mathf.Log((float)propertyNameCount) / Mathf.Log(2f)) : 0);
			AccessTools.Property(typeof(ModelIdSerializationCache), "PropertyIdBitSize")?.SetValue(null, num);
		}

		private static bool SortNetIdTableIfEnabled(bool autoDetectedSavedPropertyContent)
		{
			ModelDbDeterministicSortMode modelDbDeterministicSortMode = RitsuLibSettingsStore.GetModelDbDeterministicSortMode();
			if (modelDbDeterministicSortMode == ModelDbDeterministicSortMode.Disabled || (modelDbDeterministicSortMode == ModelDbDeterministicSortMode.Auto && !autoDetectedSavedPropertyContent))
			{
				return false;
			}
			return SortNetIdTable(requireMultipleEntries: true);
		}

		private static bool SortNetIdTable(bool requireMultipleEntries)
		{
			Dictionary<string, int> propertyNameToNetIdMap = GetPropertyNameToNetIdMap();
			List<string> netIdToPropertyNameMap = GetNetIdToPropertyNameMap();
			if (propertyNameToNetIdMap == null || netIdToPropertyNameMap == null || (requireMultipleEntries && netIdToPropertyNameMap.Count <= 1))
			{
				return false;
			}
			netIdToPropertyNameMap.Sort(StringComparer.Ordinal);
			propertyNameToNetIdMap.Clear();
			for (int i = 0; i < netIdToPropertyNameMap.Count; i++)
			{
				propertyNameToNetIdMap[netIdToPropertyNameMap[i]] = i;
			}
			return true;
		}

		private static Dictionary<string, int>? GetPropertyNameToNetIdMap()
		{
			return AccessTools.DeclaredField(typeof(ModelIdSerializationCache), "_propertyNameToNetIdMap")?.GetValue(null) as Dictionary<string, int>;
		}

		private static List<string>? GetNetIdToPropertyNameMap()
		{
			return AccessTools.DeclaredField(typeof(ModelIdSerializationCache), "_netIdToPropertyNameMap")?.GetValue(null) as List<string>;
		}
	}
}
namespace STS2RitsuLib.Interop.Internal
{
	/// <summary>
	///     <para xml:lang="en">
	///         Emits Harmony transpilers that forward annotated CLR stubs to another mod or assembly.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         生成 Harmony 转译补丁，使带有互操作标记的 CLR 存根转发到另一个模组或程序集。
	///     </para>
	/// </summary>
	internal static class ModInteropEmitter
	{
		private readonly record struct TargetResolutionContext(IReadOnlyList<Assembly> ModAssemblies, bool AssemblyQualifiedOnly, string CacheKey)
		{
			public static TargetResolutionContext ForModAssemblies(IReadOnlyList<Assembly> assemblies)
			{
				Assembly[] array = assemblies.Distinct().ToArray();
				return new TargetResolutionContext(array, AssemblyQualifiedOnly: false, string.Join("|", array.Select((Assembly assembly) => assembly.FullName)));
			}

			public static TargetResolutionContext ForAssemblyQualifiedTypes()
			{
				return new TargetResolutionContext(Array.Empty<Assembly>(), AssemblyQualifiedOnly: true, "<assembly-qualified>");
			}
		}

		private const BindingFlags ValidMemberFlags = BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public;

		private static readonly FieldInfo WrappedValueField = AccessTools.DeclaredField(typeof(InteropClassWrapper), "Value");

		private static readonly List<HarmonyIlPayloadTranspilerHandle> PayloadTranspilerHandles = new List<HarmonyIlPayloadTranspilerHandle>();

		private static readonly Dictionary<(string, string), Type> TypeResolutionCache = new Dictionary<(string, string), Type>();

		internal static void TryProcessType(Harmony harmony, IReadOnlyDictionary<string, Assembly> loadedAssembliesByModId, Type t)
		{
			ModInteropAttribute customAttribute = t.GetCustomAttribute<ModInteropAttribute>();
			AssemblyInteropAttribute customAttribute2 = t.GetCustomAttribute<AssemblyInteropAttribute>();
			if (customAttribute != null && customAttribute2 != null)
			{
				RitsuLibFramework.Logger.Warn("[Interop] Type " + t.FullName + " declares both ModInterop and AssemblyInterop; skipping.", 1);
			}
			else if (customAttribute != null)
			{
				loadedAssembliesByModId.TryGetValue(customAttribute.ModId, out Assembly value);
				IReadOnlyList<Assembly> knownAssembliesForMod = ModTypeDiscoveryHub.GetKnownAssembliesForMod(customAttribute.ModId, value);
				if (knownAssembliesForMod.Count != 0)
				{
					RitsuLibFramework.Logger.Info("[ModInterop] Processing type " + t.FullName + " -> mod " + customAttribute.ModId, 1);
					GenInteropMembers(t.GetMembers(BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public), harmony, TargetResolutionContext.ForModAssemblies(knownAssembliesForMod), customAttribute.Type, requireStatic: true);
				}
			}
			else if (customAttribute2 != null)
			{
				RitsuLibFramework.Logger.Info("[AssemblyInterop] Processing type " + t.FullName, 1);
				GenInteropMembers(t.GetMembers(BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public), harmony, TargetResolutionContext.ForAssemblyQualifiedTypes(), customAttribute2.Type, requireStatic: true);
			}
		}

		private static bool GenInteropMembers(MemberInfo[] members, Harmony harmony, TargetResolutionContext targetContext, string? contextTargetType, bool requireStatic)
		{
			foreach (MemberInfo memberInfo in members)
			{
				if (!(memberInfo is PropertyInfo property))
				{
					if (!(memberInfo is MethodInfo methodInfo))
					{
						if (memberInfo is TypeInfo typeInfo && typeInfo.IsAssignableTo(typeof(InteropClassWrapper)) && !GenInteropType(harmony, targetContext, contextTargetType, typeInfo))
						{
							return false;
						}
					}
					else if ((!requireStatic || methodInfo.IsStatic) && !methodInfo.IsConstructor && methodInfo.GetCustomAttribute<CompilerGeneratedAttribute>() == null && !GenInteropMethod(harmony, targetContext, contextTargetType, methodInfo))
					{
						return false;
					}
				}
				else if ((!requireStatic || IsStaticProperty(property)) && !GenInteropPropertyOrField(harmony, targetContext, contextTargetType, property))
				{
					return false;
				}
			}
			return true;
		}

		private static bool GenInteropType(Harmony harmony, TargetResolutionContext targetContext, string? contextTargetType, TypeInfo type)
		{
			//IL_0128: Unknown result type (might be due to invalid IL or missing references)
			//IL_0132: Expected O, but got Unknown
			//IL_013e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0148: Expected O, but got Unknown
			ConstructorInfo[] constructors = type.GetConstructors();
			if (constructors.Length < 1)
			{
				throw new InvalidOperationException(type.FullName + " must have at least one public constructor");
			}
			InteropTargetAttribute customAttribute = type.GetCustomAttribute<InteropTargetAttribute>();
			string text = customAttribute?.Type ?? customAttribute?.Name ?? contextTargetType ?? throw new InvalidOperationException("No target type provided for interop type " + type.FullName);
			try
			{
				Type targetType = ResolveTargetType(text, targetContext);
				if (targetType.IsValueType)
				{
					throw new InvalidOperationException("InteropClassWrapper cannot wrap value type " + targetType.FullName + ".");
				}
				foreach (var item4 in constructors.Select(delegate(ConstructorInfo ctor)
				{
					Type[] array = (from p in ctor.GetParameters()
						select p.ParameterType).ToArray();
					ConstructorInfo constructor = targetType.GetConstructor(array);
					if ((object)constructor == null)
					{
						throw new InvalidOperationException("No matching constructor in " + targetType.FullName + " for " + FormatConstructor(ctor));
					}
					return (ctor: ctor, match: constructor, paramTypes: array);
				}).ToList())
				{
					ConstructorInfo item = item4.ctor;
					ConstructorInfo item2 = item4.match;
					Type[] item3 = item4.paramTypes;
					List<CodeInstruction> list = new List<CodeInstruction> { CodeInstruction.LoadArgument(0, false) };
					for (int num = 0; num < item3.Length; num++)
					{
						list.Add(CodeInstruction.LoadArgument(num + 1, false));
					}
					list.Add(new CodeInstruction(OpCodes.Newobj, (object)item2));
					list.Add(new CodeInstruction(OpCodes.Stfld, (object)WrappedValueField));
					PatchReturnInsertion(harmony, item, list);
				}
				RitsuLibFramework.Logger.Info("[ModInterop] Generated interop type " + type.FullName, 1);
				return GenInteropMembers(type.GetMembers(BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public), harmony, targetContext, text, requireStatic: false);
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn($"[ModInterop] {ex}", 1);
				return false;
			}
		}

		private static bool GenInteropMethod(Harmony harmony, TargetResolutionContext targetContext, string? contextTargetType, MethodInfo method)
		{
			//IL_017a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0184: Expected O, but got Unknown
			InteropTargetAttribute? customAttribute = method.GetCustomAttribute<InteropTargetAttribute>();
			string targetName = customAttribute?.Type ?? contextTargetType ?? throw new InvalidOperationException("Mod interop " + FormatMethod(method) + " does not define target type");
			string text = customAttribute?.Name ?? method.Name;
			try
			{
				Type type = ResolveTargetType(targetName, targetContext);
				ParameterInfo[] parameters = method.GetParameters();
				Type[] array = parameters.Select((ParameterInfo p) => p.ParameterType).ToArray();
				ParameterInfo[] array2 = (method.IsStatic ? parameters.Skip(1).ToArray() : parameters);
				List<MethodInfo> list = new List<MethodInfo>();
				foreach (MethodInfo declaredMethod in AccessTools.GetDeclaredMethods(type))
				{
					if (!(declaredMethod.Name != text) && !declaredMethod.ContainsGenericParameters && (!declaredMethod.IsStatic || method.IsStatic) && (declaredMethod.IsStatic || !method.IsStatic || CanUseStaticShimReceiver(parameters, type)))
					{
						ParameterInfo[] parameters2 = declaredMethod.GetParameters();
						ParameterInfo[] checkParams = (declaredMethod.IsStatic ? parameters : array2);
						if (CheckParamMatch(parameters2, checkParams))
						{
							list.Add(declaredMethod);
						}
					}
				}
				MethodInfo methodInfo = ResolveTargetMethodCandidate(method, type, text, list);
				List<CodeInstruction> list2 = new List<CodeInstruction>();
				if (methodInfo.ReturnType != typeof(void))
				{
					list2.Add(new CodeInstruction(OpCodes.Pop, (object)null));
				}
				int num = 0;
				if (!methodInfo.IsStatic)
				{
					if (method.IsStatic)
					{
						ValidateStaticShimReceiver(method, parameters, type, methodInfo);
						list2.Add(CodeInstruction.LoadArgument(0, false));
						AddTypeCoercion(list2, array[0], type);
						num = 1;
					}
					else
					{
						list2.AddRange(LoadWrappedTarget(type));
					}
				}
				ParameterInfo[] parameters3 = methodInfo.GetParameters();
				int num2 = ((!method.IsStatic) ? 1 : 0);
				for (int num3 = 0; num3 < parameters3.Length; num3++)
				{
					int num4 = num3 + num;
					list2.Add(CodeInstruction.LoadArgument(num4 + num2, false));
					AddTypeCoercion(list2, array[num4], parameters3[num3].ParameterType);
				}
				if (methodInfo.ReturnType != method.ReturnType)
				{
					throw new InvalidOperationException($"{FormatMethod(method)} → {type.FullName}.{text}: return type mismatch (stub: {method.ReturnType.Name}, target: {methodInfo.ReturnType.Name})");
				}
				list2.Add(Call(methodInfo));
				PatchReturnInsertion(harmony, method, list2);
				RitsuLibFramework.Logger.Info("[ModInterop] Generated interop method " + method.Name, 1);
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn($"[ModInterop] {ex}", 1);
				return false;
			}
			return true;
		}

		private static bool GenInteropPropertyOrField(Harmony harmony, TargetResolutionContext targetContext, string? contextTargetType, PropertyInfo property)
		{
