			//IL_035b: Expected O, but got Unknown
			//IL_0323: Unknown result type (might be due to invalid IL or missing references)
			//IL_0329: Expected O, but got Unknown
			InteropTargetAttribute? customAttribute = property.GetCustomAttribute<InteropTargetAttribute>();
			string text = customAttribute?.Type ?? contextTargetType ?? throw new InvalidOperationException($"Mod interop {property} does not define target type");
			string text2 = customAttribute?.Name ?? property.Name;
			try
			{
				Type type = ResolveTargetType(text, targetContext);
				PropertyInfo propertyInfo = AccessTools.DeclaredProperty(type, text2);
				if ((object)propertyInfo != null && propertyInfo.PropertyType == property.PropertyType)
				{
