					bool flag = ((object)setMethod != null && setMethod.IsStatic) || (propertyInfo.GetMethod?.IsStatic ?? false);
					MethodInfo? setMethod2 = property.SetMethod;
					bool flag2 = ((object)setMethod2 != null && setMethod2.IsStatic) || (property.GetMethod?.IsStatic ?? false);
					if (flag && !flag2)
					{
						throw new InvalidOperationException($"Target property {propertyInfo} is static; interop property must also be static");
					}
					if (flag2 && !flag)
					{
						throw new InvalidOperationException($"Target property {propertyInfo} is not static; interop property should not be static");
