								Call(propertyInfo.SetMethod)
							}));
						}
						else
						{
							MethodInfo? setMethod3 = property.SetMethod;
							CodeInstruction[] array = LoadWrappedTarget(type);
							int num = 0;
							CodeInstruction[] array2 = (CodeInstruction[])(object)new CodeInstruction[2 + array.Length];
							ReadOnlySpan<CodeInstruction> readOnlySpan = new ReadOnlySpan<CodeInstruction>(array);
							readOnlySpan.CopyTo(new Span<CodeInstruction>(array2).Slice(num, readOnlySpan.Length));
							num += readOnlySpan.Length;
							array2[num] = new CodeInstruction(OpCodes.Ldarg_1, (object)null);
							num++;
							array2[num] = Call(propertyInfo.SetMethod);
							PatchReturnInsertion(harmony, setMethod3, new global::<>z__ReadOnlyArray<CodeInstruction>(array2));
						}
					}
					if ((object)propertyInfo.GetMethod != null)
					{
						if ((object)property.GetMethod == null)
						{
							throw new InvalidOperationException($"Property {property} should have a getter to match target property");
						}
						if (flag)
						{
							PatchReturnInsertion(harmony, property.GetMethod, new global::<>z__ReadOnlyArray<CodeInstruction>((CodeInstruction[])(object)new CodeInstruction[2]
							{
								new CodeInstruction(OpCodes.Pop, (object)null),
								Call(propertyInfo.GetMethod)
							}));
						}
						else
						{
							MethodInfo? getMethod = property.GetMethod;
							CodeInstruction val = new CodeInstruction(OpCodes.Pop, (object)null);
							CodeInstruction[] array2 = LoadWrappedTarget(type);
							int num = 0;
							CodeInstruction[] array = (CodeInstruction[])(object)new CodeInstruction[2 + array2.Length];
							array[num] = val;
							num++;
							ReadOnlySpan<CodeInstruction> readOnlySpan = new ReadOnlySpan<CodeInstruction>(array2);
							readOnlySpan.CopyTo(new Span<CodeInstruction>(array).Slice(num, readOnlySpan.Length));
							num += readOnlySpan.Length;
							array[num] = Call(propertyInfo.GetMethod);
							PatchReturnInsertion(harmony, getMethod, new global::<>z__ReadOnlyArray<CodeInstruction>(array));
						}
					}
					RitsuLibFramework.Logger.Info("[ModInterop] Generated interop property " + property.Name, 1);
					return true;
				}
				FieldInfo fieldInfo = AccessTools.DeclaredField(type, text2);
				if ((object)fieldInfo == null || fieldInfo.FieldType != property.PropertyType)
				{
					throw new InvalidOperationException("Could not find property or field for name " + text2 + " in type " + text);
				}
				if ((object)property.SetMethod == null)
				{
					throw new InvalidOperationException($"Interop property {property} should have a setter for field {fieldInfo}");
				}
				if ((object)property.GetMethod == null)
				{
					throw new InvalidOperationException($"Interop property {property} should have a getter for field {fieldInfo}");
				}
				MethodInfo? setMethod4 = property.SetMethod;
				bool flag3 = ((object)setMethod4 != null && setMethod4.IsStatic) || (property.GetMethod?.IsStatic ?? false);
				if (fieldInfo.IsStatic && !flag3)
				{
					throw new InvalidOperationException($"Target field {fieldInfo} is static; interop property must also be static");
				}
				if (flag3 && !fieldInfo.IsStatic)
				{
					throw new InvalidOperationException($"Target field {fieldInfo} is not static; interop property should not be static");
				}
				if ((object)property.SetMethod != null)
				{
					if (fieldInfo.IsStatic)
					{
						PatchReturnInsertion(harmony, property.SetMethod, new global::<>z__ReadOnlyArray<CodeInstruction>((CodeInstruction[])(object)new CodeInstruction[2]
						{
							new CodeInstruction(OpCodes.Ldarg_0, (object)null),
							new CodeInstruction(OpCodes.Stsfld, (object)fieldInfo)
						}));
					}
					else
					{
						MethodInfo? setMethod5 = property.SetMethod;
						CodeInstruction[] array = LoadWrappedTarget(type);
						int num = 0;
						CodeInstruction[] array2 = (CodeInstruction[])(object)new CodeInstruction[2 + array.Length];
						ReadOnlySpan<CodeInstruction> readOnlySpan = new ReadOnlySpan<CodeInstruction>(array);
						readOnlySpan.CopyTo(new Span<CodeInstruction>(array2).Slice(num, readOnlySpan.Length));
						num += readOnlySpan.Length;
						array2[num] = new CodeInstruction(OpCodes.Ldarg_1, (object)null);
						num++;
						array2[num] = new CodeInstruction(OpCodes.Stfld, (object)fieldInfo);
						PatchReturnInsertion(harmony, setMethod5, new global::<>z__ReadOnlyArray<CodeInstruction>(array2));
					}
				}
				if ((object)property.GetMethod != null)
				{
					if (fieldInfo.IsStatic)
					{
						PatchReturnInsertion(harmony, property.GetMethod, new global::<>z__ReadOnlyArray<CodeInstruction>((CodeInstruction[])(object)new CodeInstruction[2]
						{
							new CodeInstruction(OpCodes.Pop, (object)null),
							new CodeInstruction(OpCodes.Ldsfld, (object)fieldInfo)
						}));
					}
					else
					{
						MethodInfo? getMethod2 = property.GetMethod;
						CodeInstruction val = new CodeInstruction(OpCodes.Pop, (object)null);
						CodeInstruction[] array2 = LoadWrappedTarget(type);
						int num = 0;
						CodeInstruction[] array = (CodeInstruction[])(object)new CodeInstruction[2 + array2.Length];
						array[num] = val;
						num++;
						ReadOnlySpan<CodeInstruction> readOnlySpan = new ReadOnlySpan<CodeInstruction>(array2);
						readOnlySpan.CopyTo(new Span<CodeInstruction>(array).Slice(num, readOnlySpan.Length));
						num += readOnlySpan.Length;
						array[num] = new CodeInstruction(OpCodes.Ldfld, (object)fieldInfo);
						PatchReturnInsertion(harmony, getMethod2, new global::<>z__ReadOnlyArray<CodeInstruction>(array));
					}
				}
				RitsuLibFramework.Logger.Info("[ModInterop] Generated interop field property " + property.Name, 1);
				return true;
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn($"[ModInterop] {ex}", 1);
				return false;
			}
		}

		private static void PatchReturnInsertion(Harmony harmony, MethodBase target, IEnumerable<CodeInstruction> payload)
		{
			HarmonyIlPayloadTranspilerHandle item = HarmonyIlPayloadTranspiler.PatchReturnInsertion(harmony, target, payload, "[ModInterop] Insert generated wrapper IL before single ret");
			PayloadTranspilerHandles.Add(item);
		}

		private static CodeInstruction[] LoadWrappedTarget(Type targetType)
		{
			//IL_003f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0045: Expected O, but got Unknown
			//IL_004d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0053: Expected O, but got Unknown
			if (targetType.IsValueType)
			{
				throw new InvalidOperationException("InteropClassWrapper cannot wrap value type " + targetType.FullName + ".");
			}
			return (CodeInstruction[])(object)new CodeInstruction[3]
			{
				CodeInstruction.LoadArgument(0, false),
				new CodeInstruction(OpCodes.Ldfld, (object)WrappedValueField),
				new CodeInstruction(OpCodes.Castclass, (object)targetType)
			};
		}

		private static void ValidateStaticShimReceiver(MethodInfo sourceMethod, ParameterInfo[] sourceParameters, Type targetType, MethodInfo targetMethod)
		{
			if (sourceParameters.Length != 0 && (IsWildcardParam(sourceParameters[0]) || targetType.IsAssignableTo(sourceParameters[0].ParameterType)))
			{
				return;
			}
			throw new InvalidOperationException($"Static shim {FormatMethod(sourceMethod)} must take target receiver {targetType.FullName} as its first parameter to match instance target {FormatMethod(targetMethod)}");
		}

		private static bool CanUseStaticShimReceiver(ParameterInfo[] sourceParameters, Type targetType)
		{
			if (!targetType.IsValueType && sourceParameters.Length != 0)
			{
				if (!IsWildcardParam(sourceParameters[0]))
				{
					return targetType.IsAssignableTo(sourceParameters[0].ParameterType);
				}
				return true;
			}
			return false;
		}

		private static MethodInfo ResolveTargetMethodCandidate(MethodInfo sourceMethod, Type targetType, string methodName, IReadOnlyList<MethodInfo> candidates)
		{
			switch (candidates.Count)
			{
			case 0:
				throw new InvalidOperationException($"{FormatMethod(sourceMethod)} → {targetType.FullName}.{methodName}: " + "no overload with matching parameters");
			case 1:
				return candidates[0];
			default:
			{
				string value = string.Join(", ", candidates.Select(FormatMethodSignature));
				throw new InvalidOperationException($"{FormatMethod(sourceMethod)} → {targetType.FullName}.{methodName}: multiple overloads match ({value}); use more specific stub parameter types");
			}
			}
		}

		private static void AddTypeCoercion(List<CodeInstruction> instructions, Type sourceType, Type targetType)
		{
			//IL_0124: Unknown result type (might be due to invalid IL or missing references)
			//IL_0117: Unknown result type (might be due to invalid IL or missing references)
			//IL_00da: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e4: Expected O, but got Unknown
			//IL_012e: Expected O, but got Unknown
			//IL_00fd: Unknown result type (might be due to invalid IL or missing references)
			//IL_0107: Expected O, but got Unknown
			if (sourceType == targetType)
			{
				return;
			}
			if (sourceType.IsByRef || targetType.IsByRef || sourceType.IsPointer || targetType.IsPointer)
			{
				throw new InvalidOperationException($"Cannot coerce interop argument from {sourceType} to {targetType}.");
			}
			if (sourceType.IsValueType)
			{
				if (targetType.IsValueType)
				{
					throw new InvalidOperationException($"Cannot coerce interop value argument from {sourceType} to {targetType}.");
				}
				instructions.Add(new CodeInstruction(OpCodes.Box, (object)sourceType));
				if (targetType != typeof(object))
				{
					instructions.Add(new CodeInstruction(OpCodes.Castclass, (object)targetType));
				}
			}
			else
			{
				instructions.Add(targetType.IsValueType ? new CodeInstruction(OpCodes.Unbox_Any, (object)targetType) : new CodeInstruction(OpCodes.Castclass, (object)targetType));
			}
		}

		private static CodeInstruction Call(MethodInfo method)
		{
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			//IL_002f: Expected O, but got Unknown
			OpCode opCode;
			if (!method.IsStatic)
			{
				Type? declaringType = method.DeclaringType;
				if ((object)declaringType == null || !declaringType.IsValueType)
				{
					opCode = OpCodes.Callvirt;
					goto IL_0028;
				}
			}
			opCode = OpCodes.Call;
			goto IL_0028;
			IL_0028:
			return new CodeInstruction(opCode, (object)method);
		}

		private static bool IsStaticProperty(PropertyInfo property)
		{
			return property.GetAccessors(nonPublic: true).Any((MethodInfo accessor) => accessor.IsStatic);
		}

		private static Type ResolveTargetType(string targetName, TargetResolutionContext targetContext)
		{
			(string, string) key = (targetName, targetContext.CacheKey);
			if (TypeResolutionCache.TryGetValue(key, out Type value))
			{
				return value;
			}
			Type type = ResolveTargetTypeCore(targetName, targetContext);
			TypeResolutionCache[key] = type;
			return type;
		}

		private static Type ResolveTargetTypeCore(string targetName, TargetResolutionContext targetContext)
		{
			if (targetContext.AssemblyQualifiedOnly)
			{
				TryResolveAssemblyQualifiedType(targetName, out Type type);
				return type ?? throw new InvalidOperationException("AssemblyInterop target type '" + targetName + "' must be an assembly-qualified CLR type name that can be resolved.");
			}
			if (IsAssemblyQualifiedTypeName(targetName))
			{
				throw new InvalidOperationException("ModInterop target type '" + targetName + "' must be a full type name inside the target mod assembly. Use AssemblyInterop for assembly-qualified CLR type names.");
			}
			foreach (Assembly modAssembly in targetContext.ModAssemblies)
			{
				Type type2 = modAssembly.GetType(targetName, throwOnError: false) ?? Type.GetType(targetName + ", " + modAssembly.FullName, throwOnError: false);
				if (type2 != null)
				{
					return type2;
				}
			}
			string text = string.Join(", ", targetContext.ModAssemblies.Select((Assembly assembly) => assembly.FullName));
			throw new InvalidOperationException("Type " + targetName + " not found in mod assemblies: " + text);
		}

		private static bool IsAssemblyQualifiedTypeName(string? targetName)
		{
			if (!string.IsNullOrWhiteSpace(targetName))
			{
				return targetName.Contains(',', StringComparison.Ordinal);
			}
			return false;
		}

		private static bool TryResolveAssemblyQualifiedType(string? targetName, out Type? type)
		{
			type = null;
			if (!IsAssemblyQualifiedTypeName(targetName))
			{
				return false;
			}
			type = Type.GetType(targetName, throwOnError: false);
			return type != null;
		}

		private static bool CheckParamMatch(ParameterInfo[] targetParams, ParameterInfo[] checkParams)
		{
			if (targetParams.Length != checkParams.Length)
			{
				return false;
			}
			return !checkParams.Where((ParameterInfo p, int i) => !IsWildcardParam(p) && !p.ParameterType.IsAssignableTo(targetParams[i].ParameterType)).Any();
		}

		private static bool IsWildcardParam(ParameterInfo p)
		{
			if (!(p.ParameterType == typeof(object)))
			{
				return p.GetCustomAttribute<InteropAnyParamAttribute>() != null;
			}
			return true;
		}

		private static string FormatMethod(MethodInfo m)
		{
			return m.DeclaringType?.FullName + "." + m.Name;
		}

		private static string FormatMethodSignature(MethodInfo method)
		{
			return method.Name + "(" + string.Join(", ", from p in method.GetParameters()
				select p.ParameterType.Name) + ")";
		}

		private static string FormatConstructor(ConstructorInfo c)
		{
			return c.DeclaringType?.FullName + ".ctor(" + string.Join(", ", from p in c.GetParameters()
				select p.ParameterType.Name) + ")";
		}
	}
}
namespace STS2RitsuLib.Interop.AutoRegistration
{
	internal static class AssemblyTypeScanHelper
	{
		public static IReadOnlyList<Type> GetLoadableTypes(Assembly assembly, Logger logger)
		{
			ArgumentNullException.ThrowIfNull(assembly, "assembly");
			ArgumentNullException.ThrowIfNull(logger, "logger");
			try
			{
				return assembly.GetTypes();
			}
			catch (ReflectionTypeLoadException ex)
			{
				foreach (Exception item in ex.LoaderExceptions.Where((Exception e) => e != null))
				{
					logger.Warn("[AutoRegister] Loader exception while scanning " + assembly.FullName + ": " + item.Message, 1);
				}
				List<Type> list = new List<Type>();
				list.AddRange(ex.Types.Where((Type t) => t != null).Cast<Type>());
				return new <>z__ReadOnlyList<Type>(list);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Built-in contributor that scans each assembly once for RitsuLib auto-registration attributes,
	///         orders the resulting operations deterministically, and dispatches them through explicit registry APIs.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         内置贡献器：对每个程序集扫描一次 RitsuLib 自动注册特性，对所得操作进行确定性排序，
	///         再通过显式注册表 API 执行。
	///     </para>
	/// </summary>
	public sealed class AttributeAutoRegistrationTypeDiscoveryContributor : IModTypeDiscoveryContributor
	{
		private readonly record struct AutoRegistrationAttributeSource(Attribute Attribute, Type DeclaringType);

		private readonly record struct AutoRegistrationInheritanceSlot(string Family, string Scope)
		{
			public override string ToString()
			{
				if (!string.IsNullOrEmpty(Scope))
				{
					return Family + "[" + Scope.Replace("\0", ", ", StringComparison.Ordinal) + "]";
				}
				return Family;
			}
		}

		private readonly record struct OperationPriority(AutoRegistrationOperation Operation) : IComparable<OperationPriority>
		{
			public int CompareTo(OperationPriority other)
			{
				return AutoRegistrationOperationComparer.CompareCore(Operation, other.Operation);
			}
		}

		private static readonly Lock Gate = new Lock();

		private static readonly HashSet<Assembly> ProcessedAssemblies = new HashSet<Assembly>();

		/// <inheritdoc />
		public void Contribute(Harmony harmony, IReadOnlyDictionary<string, Assembly> modAssembliesByManifestId, Type modType)
		{
			ArgumentNullException.ThrowIfNull(harmony, "harmony");
			ArgumentNullException.ThrowIfNull(modAssembliesByManifestId, "modAssembliesByManifestId");
			ArgumentNullException.ThrowIfNull(modType, "modType");
			Assembly assembly = modType.Assembly;
			using (Gate.EnterScope())
			{
				if (!ProcessedAssemblies.Add(assembly))
				{
					return;
				}
			}
			ProcessAssembly(assembly, modAssembliesByManifestId);
		}

		private static void ProcessAssembly(Assembly assembly, IReadOnlyDictionary<string, Assembly> modAssembliesByManifestId)
		{
			Logger logger = RitsuLibFramework.Logger;
			List<AutoRegistrationOperation> list = new List<AutoRegistrationOperation>();
			foreach (Type loadableType in AssemblyTypeScanHelper.GetLoadableTypes(assembly, logger))
			{
				if (!loadableType.IsAbstract && !loadableType.IsInterface)
				{
					try
					{
						list.AddRange(BuildOperations(loadableType, modAssembliesByManifestId));
					}
					catch (Exception ex)
					{
						logger.ErrorNoTrace($"[AutoRegister] Failed to inspect type '{loadableType.FullName}' in assembly '{assembly.FullName}': {ex.Message}");
					}
				}
			}
			if (list.Count == 0)
			{
				return;
			}
			IReadOnlyList<AutoRegistrationOperation> readOnlyList = OrderOperations(list);
			int num = 0;
			int num2 = 0;
			foreach (AutoRegistrationOperation item in readOnlyList)
			{
				try
				{
					item.Execute();
					num++;
				}
				catch (Exception ex2)
				{
					num2++;
					RegistrationFreezeDiagnostics.RecordFailure("AutoRegister", item.OwnerModId, $"{item.AttributeName} for '{item.SourceType.FullName}' (signature '{item.Signature}')", ex2);
					logger.ErrorNoTrace($"[AutoRegister] {item.AttributeName} failed for '{item.SourceType.FullName}' (mod '{item.OwnerModId}', signature '{item.Signature}'): {ex2.Message}");
				}
			}
			logger.Info($"[AutoRegister] Processed assembly '{assembly.GetName().Name}': {list.Count} operation(s), {num} succeeded, {num2} failed.", 1);
		}

		private static IEnumerable<AutoRegistrationOperation> BuildOperations(Type type, IReadOnlyDictionary<string, Assembly> modAssembliesByManifestId)
