		private static IEnumerable<AutoRegistrationAttributeSource> EnumerateEffectiveRegistrationAttributes(Type type)
		{
			ArgumentNullException.ThrowIfNull(type, "type");
			Dictionary<AutoRegistrationInheritanceSlot, Type> claimedSlots = new Dictionary<AutoRegistrationInheritanceSlot, Type>();
			Type declaringType = type;
			while (declaringType != null)
			{
				HashSet<AutoRegistrationInheritanceSlot> slotsAtLevel = new HashSet<AutoRegistrationInheritanceSlot>();
				foreach (AutoRegistrationAttribute item in declaringType.GetCustomAttributes(inherit: false).OfType<AutoRegistrationAttribute>())
				{
					if (declaringType != type && !item.Inherit)
					{
						continue;
					}
					AutoRegistrationInheritanceSlot inheritanceSlot = GetInheritanceSlot(item);
					if (!claimedSlots.ContainsKey(inheritanceSlot))
					{
						if (!slotsAtLevel.Add(inheritanceSlot))
						{
							throw new InvalidOperationException($"Type '{declaringType.FullName}' declares multiple auto-registration attributes for the same logical inheritance slot '{inheritanceSlot}'. Put only one registration in that slot; " + "use distinct target ids or scopes only for registrations that support multiple entries.");
						}
						yield return new AutoRegistrationAttributeSource(item, declaringType);
					}
				}
				foreach (AutoRegistrationInheritanceSlot item2 in slotsAtLevel)
				{
					claimedSlots[item2] = declaringType;
				}
				declaringType = declaringType.BaseType;
			}
		}

		private static AutoRegistrationInheritanceSlot GetInheritanceSlot(AutoRegistrationAttribute attribute)
		{
			ArgumentNullException.ThrowIfNull(attribute, "attribute");
			if (!(attribute is RegisterCardAttribute))
			{
				if (!(attribute is RegisterRelicAttribute))
				{
					if (!(attribute is RegisterPotionAttribute))
					{
						if (!(attribute is RegisterDefaultModelCapabilityAttribute registerDefaultModelCapabilityAttribute))
						{
							if (!(attribute is RegisterMutuallyExclusiveModifierGroupAttribute registerMutuallyExclusiveModifierGroupAttribute))
							{
								if (!(attribute is CharacterStarterRegistrationAttributeBase characterStarterRegistrationAttributeBase))
								{
									if (!(attribute is RegisterActEncounterAttribute registerActEncounterAttribute))
									{
										if (!(attribute is RegisterActEventAttribute registerActEventAttribute))
										{
											if (!(attribute is RegisterActAncientAttribute registerActAncientAttribute))
											{
												if (!(attribute is RegisterOwnedKeywordAttribute registerOwnedKeywordAttribute))
												{
													if (!(attribute is RegisterOwnedCardKeywordAttribute registerOwnedCardKeywordAttribute))
													{
														if (!(attribute is RegisterOwnedCardTagAttribute registerOwnedCardTagAttribute))
														{
															if (!(attribute is RegisterOwnedCardPileAttribute registerOwnedCardPileAttribute))
															{
																if (!(attribute is RegisterOwnedTopBarButtonAttribute registerOwnedTopBarButtonAttribute))
																{
																	if (!(attribute is RegisterNodeAttachmentAttributeBase registerNodeAttachmentAttributeBase))
																	{
																		if (!(attribute is AutoTimelineSlotAttribute) && !(attribute is AutoTimelineSlotBeforeColumnAttribute) && !(attribute is AutoTimelineSlotBeforeEpochColumnAttribute) && !(attribute is AutoTimelineSlotAfterColumnAttribute) && !(attribute is AutoTimelineSlotAfterEpochColumnAttribute) && !(attribute is AutoTimelineSlotInColumnAttribute) && !(attribute is AutoTimelineSlotInEpochColumnAttribute))
																		{
																			if (!(attribute is RegisterArchaicToothTranscendenceAttribute))
																			{
																				if (!(attribute is RegisterDustyTomeCardAttribute registerDustyTomeCardAttribute))
																				{
																					if (!(attribute is RegisterTouchOfOrobasRefinementAttribute))
																					{
																						if (!(attribute is RegisterEpochCardsAttribute))
																						{
																							if (!(attribute is RequireAllCardsInPoolAttribute requireAllCardsInPoolAttribute))
																							{
																								if (!(attribute is RegisterEpochRelicsFromPoolAttribute registerEpochRelicsFromPoolAttribute))
																								{
																									if (!(attribute is RegisterStoryEpochAttribute))
																									{
																										if (!(attribute is RequireEpochAttribute requireEpochAttribute))
																										{
																											if (attribute is CharacterEpochRegistrationAttributeBase characterEpochRegistrationAttributeBase)
																											{
																												return ScopedSlotForType(attribute.GetType(), new string[1] { TypeIdentity(characterEpochRegistrationAttributeBase.EpochType) });
																											}
																											return ExclusiveSlotForType(attribute.GetType());
																										}
																										return ScopedSlot<RequireEpochAttribute>(new string[1] { TypeIdentity(requireEpochAttribute.EpochType) });
																									}
																									return ExclusiveSlot<RegisterStoryEpochAttribute>();
																								}
																								return ScopedSlot<RegisterEpochRelicsFromPoolAttribute>(new string[1] { TypeIdentity(registerEpochRelicsFromPoolAttribute.PoolType) });
																							}
																							return ScopedSlot<RequireAllCardsInPoolAttribute>(new string[1] { TypeIdentity(requireAllCardsInPoolAttribute.PoolType) });
																						}
																						return ExclusiveSlot<RegisterEpochCardsAttribute>();
																					}
																					return ExclusiveSlot<RegisterTouchOfOrobasRefinementAttribute>();
																				}
																				return ScopedSlot<RegisterDustyTomeCardAttribute>(new string[1] { TypeIdentity(registerDustyTomeCardAttribute.CharacterType) });
																			}
																			return ExclusiveSlot<RegisterArchaicToothTranscendenceAttribute>();
																		}
																		return ExclusiveSlot<AutoTimelineSlotAttribute>();
																	}
																	return ScopedSlot<RegisterNodeAttachmentAttributeBase>(new string[2]
																	{
																		TypeIdentity(registerNodeAttachmentAttributeBase.ParentType),
																		registerNodeAttachmentAttributeBase.LocalId
																	});
																}
																return ScopedSlot<RegisterOwnedTopBarButtonAttribute>(new string[1] { registerOwnedTopBarButtonAttribute.LocalButtonStem });
															}
															return ScopedSlot<RegisterOwnedCardPileAttribute>(new string[1] { registerOwnedCardPileAttribute.LocalPileStem });
														}
														return ScopedSlot<RegisterOwnedCardTagAttribute>(new string[1] { registerOwnedCardTagAttribute.LocalCardTagStem });
													}
													return ScopedSlot<RegisterOwnedCardKeywordAttribute>(new string[1] { registerOwnedCardKeywordAttribute.LocalKeywordStem });
												}
												return ScopedSlot<RegisterOwnedKeywordAttribute>(new string[1] { registerOwnedKeywordAttribute.LocalKeywordStem });
											}
											return ScopedSlot<RegisterActAncientAttribute>(new string[1] { TypeIdentity(registerActAncientAttribute.ActType) });
										}
										return ScopedSlot<RegisterActEventAttribute>(new string[1] { TypeIdentity(registerActEventAttribute.ActType) });
									}
									return ScopedSlot<RegisterActEncounterAttribute>(new string[1] { TypeIdentity(registerActEncounterAttribute.ActType) });
								}
								return ScopedSlotForType(attribute.GetType(), new string[1] { TypeIdentity(characterStarterRegistrationAttributeBase.CharacterType) });
							}
							return ScopedSlot<RegisterMutuallyExclusiveModifierGroupAttribute>(registerMutuallyExclusiveModifierGroupAttribute.MemberTypes.Select(TypeIdentity).Order<string>(StringComparer.Ordinal).ToArray());
						}
						return ScopedSlot<RegisterDefaultModelCapabilityAttribute>(new string[2]
						{
							TypeIdentity(registerDefaultModelCapabilityAttribute.TargetModelType),
							registerDefaultModelCapabilityAttribute.ModifierId ?? "<default>"
						});
					}
					return ExclusiveSlot<RegisterPotionAttribute>();
				}
				return ExclusiveSlot<RegisterRelicAttribute>();
			}
			return ExclusiveSlot<RegisterCardAttribute>();
			static AutoRegistrationInheritanceSlot ExclusiveSlot<TAttribute>() where TAttribute : AutoRegistrationAttribute
			{
				return ExclusiveSlotForType(typeof(TAttribute));
			}
			static AutoRegistrationInheritanceSlot ExclusiveSlotForType(Type attributeType)
			{
				return new AutoRegistrationInheritanceSlot(TypeIdentity(attributeType), "");
			}
			static AutoRegistrationInheritanceSlot ScopedSlot<TAttribute>(params string[] scope) where TAttribute : notnull, AutoRegistrationAttribute
			{
				return ScopedSlotForType(typeof(TAttribute), scope);
			}
			static AutoRegistrationInheritanceSlot ScopedSlotForType(Type attributeType, params string[] scope)
			{
				return new AutoRegistrationInheritanceSlot(TypeIdentity(attributeType), string.Join("\0", scope));
			}
			static string TypeIdentity(Type value)
			{
				return value.AssemblyQualifiedName ?? value.FullName ?? value.Name;
			}
		}

		private static AutoRegistrationOperation CreateOperation(string ownerModId, Type sourceType, AutoRegistrationPhase phase, int order, string signature, string attributeName, Action execute, IReadOnlyList<string>? dependencies = null, IReadOnlyList<string>? providedKeys = null)
		{
			return new AutoRegistrationOperation(ownerModId, sourceType.Assembly, sourceType, phase, order, signature, attributeName, execute, dependencies, providedKeys);
		}

		private static IReadOnlyList<AutoRegistrationOperation> OrderOperations(IReadOnlyList<AutoRegistrationOperation> operations)
		{
			List<AutoRegistrationOperation> list = operations.OrderBy((AutoRegistrationOperation op) => op, AutoRegistrationOperationComparer.Instance).ToList();
			Dictionary<string, int> dictionary = new Dictionary<string, int>(StringComparer.Ordinal);
			for (int num = 0; num < list.Count; num++)
			{
				AutoRegistrationOperation autoRegistrationOperation = list[num];
				dictionary[autoRegistrationOperation.Signature] = num;
				IReadOnlyList<string> providedKeys = autoRegistrationOperation.ProvidedKeys;
				if (providedKeys == null)
				{
					continue;
				}
				foreach (string item in providedKeys)
				{
					dictionary[item] = num;
				}
			}
			List<int>[] array = new List<int>[list.Count];
			int[] array2 = new int[list.Count];
			for (int num2 = 0; num2 < list.Count; num2++)
			{
				array[num2] = new List<int>();
			}
			for (int num3 = 0; num3 < list.Count; num3++)
			{
				AutoRegistrationOperation autoRegistrationOperation2 = list[num3];
				if (autoRegistrationOperation2.Dependencies == null || autoRegistrationOperation2.Dependencies.Count == 0)
				{
					continue;
				}
				foreach (string dependency in autoRegistrationOperation2.Dependencies)
				{
					if (dictionary.TryGetValue(dependency, out var value) && value != num3)
					{
						array[value].Add(num3);
						array2[num3]++;
					}
				}
			}
			PriorityQueue<int, OperationPriority> priorityQueue = new PriorityQueue<int, OperationPriority>();
			for (int num4 = 0; num4 < list.Count; num4++)
			{
				if (array2[num4] == 0)
				{
					priorityQueue.Enqueue(num4, new OperationPriority(list[num4]));
				}
			}
			List<AutoRegistrationOperation> list2 = new List<AutoRegistrationOperation>(list.Count);
			while (priorityQueue.Count > 0)
			{
				int num5 = priorityQueue.Dequeue();
				list2.Add(list[num5]);
				foreach (int item2 in array[num5])
				{
					array2[item2]--;
					if (array2[item2] == 0)
					{
						priorityQueue.Enqueue(item2, new OperationPriority(list[item2]));
					}
				}
			}
			if (list2.Count != list.Count)
			{
				RitsuLibFramework.Logger.Warn($"[AutoRegister] Dependency cycle detected among {list.Count} operation(s); falling back to stable sort.", 1);
			}
			if (list2.Count != list.Count)
			{
				return list;
			}
			return list2;
		}

		private static string TypeDependencyKey(Type type)
		{
			return "RegisterType:" + type.AssemblyQualifiedName;
		}

		private static ModCardPileSpec BuildCardPileSpec(Type declaringType, RegisterOwnedCardPileAttribute attr)
		{
			//IL_0036: Unknown result type (might be due to invalid IL or missing references)
			//IL_0047: Unknown result type (might be due to invalid IL or missing references)
			//IL_001c: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c5: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d0: Unknown result type (might be due to invalid IL or missing references)
			//IL_00db: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e6: Unknown result type (might be due to invalid IL or missing references)
			//IL_0132: Unknown result type (might be due to invalid IL or missing references)
			ModCardPileAnchor anchor = ((attr.AnchorKind == ModCardPileAnchorKind.Custom) ? new ModCardPileAnchor(ModCardPileAnchorKind.Custom, new Vector2(attr.AnchorOffsetX, attr.AnchorOffsetY), new Vector2(attr.AnchorCustomX, attr.AnchorCustomY), attr.AnchorCustomPivotX, attr.AnchorCustomPivotY) : new ModCardPileAnchor(attr.AnchorKind, new Vector2(attr.AnchorOffsetX, attr.AnchorOffsetY)));
			return new ModCardPileSpec
			{
				Scope = attr.Scope,
				Style = attr.Style,
				Anchor = anchor,
				IconPath = attr.IconPath,
				Hotkeys = attr.Hotkeys,
				CardShouldBeVisible = attr.CardShouldBeVisible,
				ExtraHand = new ModCardPileExtraHandSpec
				{
					Direction = attr.ExtraHandDirection,
					Spacing = attr.ExtraHandSpacing,
					CardScale = Vector2.One * attr.ExtraHandCardScale,
					HoverScale = Vector2.One * attr.ExtraHandHoverScale,
					ShowPlayableGlow = attr.ExtraHandShowPlayableGlow,
					AllowCardPlay = attr.ExtraHandAllowCardPlay,
					Behaviors = attr.ExtraHandBehaviors
				},
				OnOpen = ResolveCardPileOpenHandler(declaringType),
				HoverTipScreenOffset = new Vector2(attr.HoverTipOffsetX, attr.HoverTipOffsetY),
				HoverTipPlacement = attr.HoverTipPlacement
			};
		}

		private static Action<ModCardPileOpenContext>? ResolveCardPileOpenHandler(Type declaringType)
		{
			if (!typeof(IModCardPileHandler).IsAssignableFrom(declaringType))
			{
				return null;
			}
			if (declaringType.GetConstructor(Type.EmptyTypes) == null)
			{
				RitsuLibFramework.Logger.Warn($"[AutoRegister] RegisterOwnedCardPile: type '{declaringType.FullName}' implements {"IModCardPileHandler"} but has no parameterless constructor — OnOpen will not be wired.", 1);
				return null;
			}
			try
			{
				return ((IModCardPileHandler)Activator.CreateInstance(declaringType)).OnOpen;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.ErrorNoTrace("[AutoRegister] RegisterOwnedCardPile: failed to instantiate handler '" + declaringType.FullName + "': " + ex.Message);
				return null;
			}
		}

		private static ModTopBarButtonSpec BuildTopBarButtonSpec(Type declaringType, RegisterOwnedTopBarButtonAttribute attr)
		{
			IModTopBarButtonHandler modTopBarButtonHandler = ResolveTopBarButtonHandler(declaringType);
			return new ModTopBarButtonSpec
			{
				IconPath = attr.IconPath,
				Order = attr.ButtonOrder,
				Offset = new Vector2(attr.OffsetX, attr.OffsetY),
				OnClick = modTopBarButtonHandler.OnClick,
				VisibleWhen = modTopBarButtonHandler.IsVisible,
				IsOpenWhen = modTopBarButtonHandler.IsOpen,
				CountProvider = modTopBarButtonHandler.GetCount
			};
		}

		private static IModTopBarButtonHandler ResolveTopBarButtonHandler(Type declaringType)
		{
			if (!typeof(IModTopBarButtonHandler).IsAssignableFrom(declaringType))
			{
				throw new InvalidOperationException($"Type '{declaringType.FullName}' must implement {"IModTopBarButtonHandler"}.");
			}
			if (declaringType.GetConstructor(Type.EmptyTypes) == null)
			{
				throw new InvalidOperationException("Type '" + declaringType.FullName + "' must provide a public parameterless constructor.");
			}
			try
			{
				return (IModTopBarButtonHandler)Activator.CreateInstance(declaringType);
			}
			catch (Exception innerException)
			{
				throw new InvalidOperationException("Failed to instantiate top-bar button handler '" + declaringType.FullName + "'.", innerException);
			}
		}

		private static Type ResolveNodeAttachmentNodeType(Type declaringType, Type? explicitNodeType)
		{
			Type? obj = explicitNodeType ?? declaringType;
			EnsureConcreteSubtype(obj, typeof(Node), "NodeType");
			return obj;
		}

		private static void RegisterFactoryNodeAttachment(string ownerModId, Type declaringType, Type nodeType, RegisterNodeAttachmentAttribute attr)
		{
			EnsureConcreteSubtype(attr.ParentType, typeof(Node), "ParentType");
			INodeAttachmentFactory factoryProvider = ResolveNodeAttachmentFactoryProvider(declaringType, nodeType, attr);
			INodeAttachmentSetup setupProvider = ResolveNodeAttachmentSetup(declaringType, nodeType);
			NodeAttachmentOptions options = BuildNodeAttachmentOptions(attr);
			ModNodeAttachmentRegistry.For(ownerModId).RegisterReadyChildUntyped(ValidateNonEmpty(attr.LocalId, "LocalId"), attr.ParentType, nodeType, delegate(Node parent)
			{
				Node val = factoryProvider?.CreateNode(parent) ?? CreateNodeByDefaultConstructor(nodeType);
				if (nodeType.IsInstanceOfType(val))
				{
					return val;
				}
				string value = ((object)val)?.GetType().FullName ?? "<null>";
				if (val != null && GodotObject.IsInstanceValid((GodotObject)(object)val))
				{
					((GodotObject)val).Free();
				}
				throw new InvalidOperationException($"Node attachment factory '{declaringType.FullName}' returned {value}, expected {nodeType.FullName}.");
			}, ComposeNodeAttachmentSetup(setupProvider), options, "attribute-factory", null);
		}

		private static void RegisterSceneNodeAttachment(string ownerModId, Type declaringType, Type nodeType, RegisterNodeAttachmentAttributeBase attr, bool convertedScene)
		{
			EnsureConcreteSubtype(attr.ParentType, typeof(Node), "ParentType");
			string text;
			if (!(attr is RegisterNodeAttachmentFromSceneAttribute registerNodeAttachmentFromSceneAttribute))
			{
				if (!(attr is RegisterNodeAttachmentFromConvertedSceneAttribute registerNodeAttachmentFromConvertedSceneAttribute))
				{
					throw new ArgumentException("Unsupported node attachment scene attribute.", "attr");
				}
				text = ValidateNonEmpty(registerNodeAttachmentFromConvertedSceneAttribute.ScenePath, "ScenePath");
			}
			else
			{
				text = ValidateNonEmpty(registerNodeAttachmentFromSceneAttribute.ScenePath, "ScenePath");
			}
			string scenePath = text;
			INodeAttachmentSetup setupProvider = ResolveNodeAttachmentSetup(declaringType, nodeType);
			NodeAttachmentOptions options = BuildNodeAttachmentOptions(attr);
			ModNodeAttachmentRegistry.For(ownerModId).RegisterReadyChildUntyped(ValidateNonEmpty(attr.LocalId, "LocalId"), attr.ParentType, nodeType, (Node _) => (!convertedScene) ? InstantiateSceneNode(nodeType, scenePath) : CreateNodeViaConvertedSceneFactory(nodeType, scenePath), ComposeNodeAttachmentSetup(setupProvider), options, convertedScene ? "attribute-converted-scene" : "attribute-scene", scenePath);
		}

		private static NodeAttachmentOptions BuildNodeAttachmentOptions(RegisterNodeAttachmentAttributeBase attr)
		{
			return new NodeAttachmentOptions
			{
				Name = attr.NodeName,
				Order = attr.Order,
				UniqueNameInOwner = attr.UniqueNameInOwner,
				IncludeDerivedParentTypes = attr.IncludeDerivedParentTypes,
				DuplicatePolicy = attr.DuplicatePolicy,
				AddMode = attr.AddMode,
				SetupTiming = attr.SetupTiming,
				ChildIndex = ((attr.ChildIndex >= 0) ? new int?(attr.ChildIndex) : ((int?)null)),
				InsertBeforeName = attr.InsertBeforeName,
				InsertAfterName = attr.InsertAfterName,
				QueueFreeReplacedNode = attr.QueueFreeReplacedNode
			};
		}

		private static INodeAttachmentFactory? ResolveNodeAttachmentFactoryProvider(Type declaringType, Type nodeType, RegisterNodeAttachmentAttribute attr)
		{
			if (!typeof(INodeAttachmentFactory).IsAssignableFrom(declaringType))
			{
				return null;
			}
			if (typeof(Node).IsAssignableFrom(declaringType) && attr.NodeType == null)
			{
				return null;
			}
			return CreateParameterless<INodeAttachmentFactory>(declaringType, "INodeAttachmentFactory");
		}

		private static INodeAttachmentSetup? ResolveNodeAttachmentSetup(Type declaringType, Type nodeType)
		{
			if (!typeof(INodeAttachmentSetup).IsAssignableFrom(declaringType) || declaringType == nodeType)
			{
				return null;
			}
			return CreateParameterless<INodeAttachmentSetup>(declaringType, "INodeAttachmentSetup");
		}

		private static Action<Node, Node> ComposeNodeAttachmentSetup(INodeAttachmentSetup? setupProvider)
		{
			if (setupProvider != null)
			{
				return delegate(Node parent, Node node)
				{
					setupProvider.Setup(parent, node);
					if (setupProvider != node && node is INodeAttachmentSetup nodeAttachmentSetup)
					{
						nodeAttachmentSetup.Setup(parent, node);
					}
				};
			}
			return delegate(Node parent, Node node)
			{
				if (node is INodeAttachmentSetup nodeAttachmentSetup)
				{
					nodeAttachmentSetup.Setup(parent, node);
				}
			};
		}

		private static T CreateParameterless<T>(Type type, string role)
		{
			if (type.GetConstructor(Type.EmptyTypes) == null)
			{
				throw new InvalidOperationException($"Node attachment {role} type '{type.FullName}' must have a public parameterless constructor.");
			}
			return (T)Activator.CreateInstance(type);
		}

		private static Node CreateNodeByDefaultConstructor(Type nodeType)
		{
			//IL_006d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0073: Expected O, but got Unknown
			if (nodeType.GetConstructor(Type.EmptyTypes) == null)
			{
				throw new InvalidOperationException($"Node attachment node type '{nodeType.FullName}' must have a public parameterless constructor or use {"INodeAttachmentFactory"}.");
			}
			return (Node)Activator.CreateInstance(nodeType);
		}

		private static Node InstantiateSceneNode(Type nodeType, string scenePath)
		{
			Node val = (ResourceLoader.Load<PackedScene>(scenePath, (string)null, (CacheMode)1) ?? throw new InvalidOperationException("Failed to load PackedScene: " + scenePath)).Instantiate((GenEditState)0) ?? throw new InvalidOperationException("PackedScene.Instantiate returned null: " + scenePath);
			if (nodeType.IsInstanceOfType(val))
			{
				return val;
			}
			((GodotObject)val).Free();
			throw new InvalidOperationException($"Scene '{scenePath}' instantiated {((object)val).GetType().FullName}, expected {nodeType.FullName}.");
		}

		private static Node CreateNodeViaConvertedSceneFactory(Type nodeType, string scenePath)
		{
			//IL_0054: Unknown result type (might be due to invalid IL or missing references)
			//IL_005a: Expected O, but got Unknown
			return (Node)typeof(RitsuGodotNodeFactories).GetMethods(BindingFlags.Static | BindingFlags.Public).Single(delegate(MethodInfo method)
			{
				if ((object)method != null && method.Name == "CreateFromScenePath" && method.IsGenericMethodDefinition)
				{
					ParameterInfo[] parameters = method.GetParameters();
					if (parameters != null && parameters.Length == 1)
					{
						ParameterInfo parameterInfo = parameters[0];
						if (parameterInfo != null)
						{
							Type parameterType = parameterInfo.ParameterType;
							return parameterType == typeof(string);
						}
					}
				}
				return false;
			}).MakeGenericMethod(nodeType)
				.Invoke(null, new object[1] { scenePath });
		}

		private static string? ResolveOwnerModId(Type type, Type attributeDeclaringType, IReadOnlyDictionary<string, Assembly> modAssembliesByManifestId)
		{
			RitsuLibOwnedByAttribute customAttribute = attributeDeclaringType.GetCustomAttribute<RitsuLibOwnedByAttribute>(inherit: false);
			if (customAttribute != null)
			{
				return customAttribute.ModId;
			}
			if (Sts2ModManagerCompat.TryGetLoadedModIdForAssembly(type.Assembly, out string modId))
			{
				return modId;
			}
			if (ModTypeDiscoveryHub.TryResolveRegisteredModId(type.Assembly, out string modId2))
			{
				return modId2;
			}
			foreach (KeyValuePair<string, Assembly> item in modAssembliesByManifestId)
			{
				if (item.Value == type.Assembly)
				{
					return item.Key;
				}
			}
			RitsuLibFramework.Logger.Warn("[AutoRegister] Skipping '" + type.FullName + "' because no owning mod id could be resolved. Register the assembly through ModTypeDiscoveryHub.RegisterModAssembly(...) or add [RitsuLibOwnedBy(\"...\")].", 1);
			return null;
		}

		private static ModelPublicEntryOptions ResolvePublicEntryOptions(ModelPublicEntryRegistrationAttributeBase attribute)
		{
			ArgumentNullException.ThrowIfNull(attribute, "attribute");
			EnsureConcreteSubtype(attribute.PoolType, typeof(AbstractModel), "PoolType");
			bool num = !string.IsNullOrWhiteSpace(attribute.StableEntryStem);
			bool flag = !string.IsNullOrWhiteSpace(attribute.FullPublicEntry);
			if (num)
			{
				if (flag)
				{
					throw new InvalidOperationException("StableEntryStem and FullPublicEntry cannot both be specified.");
				}
				return ModelPublicEntryOptions.FromStem(attribute.StableEntryStem);
			}
			return flag ? ModelPublicEntryOptions.FromFullPublicEntry(attribute.FullPublicEntry) : ModelPublicEntryOptions.FromTypeName;
		}

		private static ModelPublicEntryOptions ResolvePublicEntryOptions(RegisterModelCapabilityAttribute attribute)
		{
			ArgumentNullException.ThrowIfNull(attribute, "attribute");
			bool num = !string.IsNullOrWhiteSpace(attribute.StableEntryStem);
			bool flag = !string.IsNullOrWhiteSpace(attribute.FullPublicEntry);
			if (num)
			{
				if (flag)
				{
					throw new InvalidOperationException("StableEntryStem and FullPublicEntry cannot both be specified.");
				}
				return ModelPublicEntryOptions.FromStem(attribute.StableEntryStem);
			}
			return flag ? ModelPublicEntryOptions.FromFullPublicEntry(attribute.FullPublicEntry) : ModelPublicEntryOptions.FromTypeName;
		}

		private static string ResolveDefaultModelCapabilityModifierId(string ownerModId, Type capabilityType, Type targetModelType, string? explicitModifierId)
		{
			if (!string.IsNullOrWhiteSpace(explicitModifierId))
			{
				return explicitModifierId.Trim();
			}
			string localCapabilityStem = targetModelType.Name + "_" + capabilityType.Name;
			return ModContentRegistry.GetQualifiedModelCapabilityId(ownerModId, localCapabilityStem);
		}

		private static void EnsureConcreteSubtype(Type type, Type expectedBaseType, string paramName)
		{
			ArgumentNullException.ThrowIfNull(type, "type");
			ArgumentNullException.ThrowIfNull(expectedBaseType, "expectedBaseType");
			if (type.ContainsGenericParameters)
			{
				throw new ArgumentException("Type '" + type.FullName + "' must be closed.", paramName);
			}
			if (type.IsAbstract || type.IsInterface || !expectedBaseType.IsAssignableFrom(type))
			{
				throw new ArgumentException($"Type '{type.FullName}' must be a concrete subtype of '{expectedBaseType.FullName}'.", paramName);
			}
		}

		private static void EnsureConcreteAssignable(Type type, Type expectedType, string paramName)
		{
			ArgumentNullException.ThrowIfNull(type, "type");
			ArgumentNullException.ThrowIfNull(expectedType, "expectedType");
			if (type.ContainsGenericParameters)
			{
				throw new ArgumentException("Type '" + type.FullName + "' must be closed.", paramName);
			}
			if (type.IsAbstract || type.IsInterface || !expectedType.IsAssignableFrom(type))
			{
				throw new ArgumentException($"Type '{type.FullName}' must be a concrete implementation of '{expectedType.FullName}'.", paramName);
			}
		}

		private static void EnsureModelFamilyType(Type type, string paramName)
		{
			ArgumentNullException.ThrowIfNull(type, "type");
			if (type.IsInterface || type.ContainsGenericParameters || !typeof(AbstractModel).IsAssignableFrom(type))
			{
				throw new ArgumentException("Type '" + type.FullName + "' must be an abstract model type or a concrete model type.", paramName);
			}
		}

		private static Type[] ValidateTypeList(IReadOnlyList<Type> types, string paramName, Type expectedBaseType)
		{
			ArgumentNullException.ThrowIfNull(types, "types");
			ArgumentNullException.ThrowIfNull(expectedBaseType, "expectedBaseType");
			if (types.Count == 0)
			{
				throw new ArgumentException("At least one type must be provided.", paramName);
			}
			Type[] array = new Type[types.Count];
			for (int i = 0; i < types.Count; i++)
			{
				Type type = types[i] ?? throw new ArgumentException("Type list must not contain null entries.", paramName);
				EnsureConcreteSubtype(type, expectedBaseType, paramName);
				array[i] = type;
			}
			return array;
		}

		private static string ValidateNonEmpty(string value, string paramName)
		{
			if (!string.IsNullOrWhiteSpace(value))
			{
				return value.Trim();
			}
			throw new ArgumentException("Value must not be null or whitespace.", paramName);
		}

		private static void EnsurePositive(int value, string paramName)
		{
			if (value <= 0)
			{
				throw new ArgumentOutOfRangeException(paramName, value, "Value must be positive.");
			}
		}
	}
	internal enum AutoRegistrationPhase
	{
		ContentPrimary,
		ContentSecondary,
		AncientMappings,
		Keywords,
		CardTags,
		CardPiles,
		TopBarButtons,
		NodeAttachments,
		TimelineLayout,
		Timeline,
		Unlocks,
		Localization
	}
	internal sealed record AutoRegistrationOperation(string OwnerModId, Assembly SourceAssembly, Type SourceType, AutoRegistrationPhase Phase, int Order, string Signature, string AttributeName, Action Execute, IReadOnlyList<string>? Dependencies = null, IReadOnlyList<string>? ProvidedKeys = null);
	internal sealed class AutoRegistrationOperationComparer : IComparer<AutoRegistrationOperation>
	{
		public static AutoRegistrationOperationComparer Instance { get; } = new AutoRegistrationOperationComparer();

		public int Compare(AutoRegistrationOperation? x, AutoRegistrationOperation? y)
		{
			return CompareCore(x, y);
		}

		public static int CompareCore(AutoRegistrationOperation? x, AutoRegistrationOperation? y)
		{
			if ((object)x == y)
			{
				return 0;
			}
			if ((object)x == null)
			{
				return -1;
			}
			if ((object)y == null)
			{
				return 1;
			}
			int num = StringComparer.OrdinalIgnoreCase.Compare(x.OwnerModId, y.OwnerModId);
			if (num != 0)
			{
				return num;
			}
			num = StringComparer.Ordinal.Compare(x.SourceAssembly.FullName ?? x.SourceAssembly.GetName().Name ?? string.Empty, y.SourceAssembly.FullName ?? y.SourceAssembly.GetName().Name ?? string.Empty);
			if (num != 0)
			{
				return num;
			}
			num = x.Phase.CompareTo(y.Phase);
			if (num != 0)
			{
				return num;
			}
			num = x.Order.CompareTo(y.Order);
			if (num != 0)
			{
				return num;
			}
			num = StringComparer.Ordinal.Compare(x.SourceType.FullName ?? x.SourceType.Name, y.SourceType.FullName ?? y.SourceType.Name);
			if (num == 0)
			{
				return StringComparer.Ordinal.Compare(x.Signature, y.Signature);
			}
			return num;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Declaratively registers a mod card pile through <see cref="T:STS2RitsuLib.CardPiles.ModCardPileRegistry" />. Apply it to a
	///         concrete type in the mod assembly; that type may implement <see cref="T:STS2RitsuLib.CardPiles.IModCardPileHandler" /> to
	///         handle opening the pile.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过 <see cref="T:STS2RitsuLib.CardPiles.ModCardPileRegistry" /> 声明式注册模组牌堆。请将此特性用于模组程序集中的
	///         具体类型；该类型可实现 <see cref="T:STS2RitsuLib.CardPiles.IModCardPileHandler" /> 以处理牌堆打开操作。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Options mirror <see cref="T:STS2RitsuLib.CardPiles.ModCardPileSpec" />. The hover-tip title, description, and empty-pile
	///         message use <see cref="F:STS2RitsuLib.CardPiles.ModCardPileSpec.HoverTipLocTable" /> keys <c>"{id}.title"</c>,
	///         <c>"{id}.description"</c>, and <c>"{id}.empty"</c>, where <c>id</c> is the qualified pile ID.
	///         Add those translations to <c>static_hover_tips.json</c>.
	///     </para>
	///     <para xml:lang="en">
	///         <see cref="P:STS2RitsuLib.Interop.AutoRegistration.RegisterOwnedCardPileAttribute.AnchorKind" /> selects the placement mode. The offset and custom-coordinate properties
	///         supply its numeric values. <see cref="F:STS2RitsuLib.CardPiles.ModCardPileAnchorKind.StyleDefault" /> uses automatic
	///         same-style placement.
	///     </para>
	///     <para xml:lang="en">
	///         If the annotated type implements <see cref="T:STS2RitsuLib.CardPiles.IModCardPileHandler" />, RitsuLib creates one instance
	///         through its public parameterless constructor and assigns <see cref="M:STS2RitsuLib.CardPiles.IModCardPileHandler.OnOpen(STS2RitsuLib.CardPiles.ModCardPileOpenContext)" />
	///         to <see cref="P:STS2RitsuLib.CardPiles.ModCardPileSpec.OnOpen" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         各选项与 <see cref="T:STS2RitsuLib.CardPiles.ModCardPileSpec" /> 对应。悬停提示标题、描述和空牌堆消息分别使用
	///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileSpec.HoverTipLocTable" /> 表中的 <c>"{id}.title"</c>、
	///         <c>"{id}.description"</c> 和 <c>"{id}.empty"</c>；其中 <c>id</c> 是限定后的牌堆 ID。
	///         请在 <c>static_hover_tips.json</c> 中添加这些翻译。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         <see cref="P:STS2RitsuLib.Interop.AutoRegistration.RegisterOwnedCardPileAttribute.AnchorKind" /> 选择放置模式，偏移与自定义坐标属性提供对应数值。
	///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileAnchorKind.StyleDefault" /> 会自动排列同样式牌堆。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         如果标注类型实现 <see cref="T:STS2RitsuLib.CardPiles.IModCardPileHandler" />，RitsuLib 会通过其公共无参构造函数创建
	///         一个实例，并将 <see cref="M:STS2RitsuLib.CardPiles.IModCardPileHandler.OnOpen(STS2RitsuLib.CardPiles.ModCardPileOpenContext)" /> 赋给
	///         <see cref="P:STS2RitsuLib.CardPiles.ModCardPileSpec.OnOpen" />。
	///     </para>
	/// </remarks>
	/// <param name="localPileStem">
	///     <para xml:lang="en">Local pile stem within the owning mod's namespace.</para>
	///     <para xml:lang="zh-CN">归属模组命名空间内的本地牌堆名称。</para>
	/// </param>
	[AttributeUsage(AttributeTargets.Class, AllowMultiple = true, Inherited = false)]
	public sealed class RegisterOwnedCardPileAttribute(string localPileStem) : AutoRegistrationAttribute
	{
		private ModExtraHandBehavior _extraHandBehaviors;

		/// <summary>
		///     <para xml:lang="en">Local pile stem within the owning mod's namespace.</para>
		///     <para xml:lang="zh-CN">归属模组命名空间内的本地牌堆名称。</para>
		/// </summary>
		public string LocalPileStem { get; } = localPileStem;

		/// <summary>
		///     <para xml:lang="en">
		///         Lifetime scope. Defaults to <see cref="F:STS2RitsuLib.CardPiles.ModCardPileScope.CombatOnly" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         生命周期范围。默认为 <see cref="F:STS2RitsuLib.CardPiles.ModCardPileScope.CombatOnly" />。
		///     </para>
		/// </summary>
		public ModCardPileScope Scope { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Presentation style. Defaults to <see cref="F:STS2RitsuLib.CardPiles.ModCardPileUiStyle.Headless" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         展示样式。默认为 <see cref="F:STS2RitsuLib.CardPiles.ModCardPileUiStyle.Headless" />。
		///     </para>
		/// </summary>
		public ModCardPileUiStyle Style { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Placement mode. Defaults to <see cref="F:STS2RitsuLib.CardPiles.ModCardPileAnchorKind.StyleDefault" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         放置模式。默认为 <see cref="F:STS2RitsuLib.CardPiles.ModCardPileAnchorKind.StyleDefault" />。
		///     </para>
		/// </summary>
		public ModCardPileAnchorKind AnchorKind { get; set; }

		/// <summary>
		///     <para xml:lang="en">Additional X offset from the resolved anchor position, in pixels.</para>
		///     <para xml:lang="zh-CN">相对解析后锚点位置增加的 X 轴像素偏移。</para>
		/// </summary>
		public float AnchorOffsetX { get; set; }

		/// <summary>
		///     <para xml:lang="en">Additional Y offset from the resolved anchor position, in pixels.</para>
		///     <para xml:lang="zh-CN">相对解析后锚点位置增加的 Y 轴像素偏移。</para>
		/// </summary>
		public float AnchorOffsetY { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         X coordinate in the mount parent's local space where the point selected by
		///         <see cref="P:STS2RitsuLib.Interop.AutoRegistration.RegisterOwnedCardPileAttribute.AnchorCustomPivotX" /> and <see cref="P:STS2RitsuLib.Interop.AutoRegistration.RegisterOwnedCardPileAttribute.AnchorCustomPivotY" /> is placed.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用 <see cref="F:STS2RitsuLib.CardPiles.ModCardPileAnchorKind.Custom" /> 时，所选基准点在挂载父节点局部坐标系中的
		///         X 坐标；基准点由 <see cref="P:STS2RitsuLib.Interop.AutoRegistration.RegisterOwnedCardPileAttribute.AnchorCustomPivotX" /> 和 <see cref="P:STS2RitsuLib.Interop.AutoRegistration.RegisterOwnedCardPileAttribute.AnchorCustomPivotY" /> 指定。
		///     </para>
		/// </summary>
		public float AnchorCustomX { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Y coordinate in the mount parent's local space where the selected pivot point is placed.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用 <see cref="F:STS2RitsuLib.CardPiles.ModCardPileAnchorKind.Custom" /> 时，所选基准点在挂载父节点局部坐标系中的 Y 坐标。
		///     </para>
		/// </summary>
		public float AnchorCustomY { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Horizontal pivot fraction, normally from <c>0</c> to <c>1</c>, for
		///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileAnchorKind.Custom" />. The default <c>0</c> uses the left edge.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileAnchorKind.Custom" /> 使用的水平枢轴比例，通常为 <c>0</c> 到
		///         <c>1</c>；默认值 <c>0</c> 使用左边缘。
		///     </para>
		/// </summary>
		public float AnchorCustomPivotX { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Vertical pivot fraction, normally from <c>0</c> to <c>1</c>, for
		///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileAnchorKind.Custom" />. The default <c>0</c> uses the top edge.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileAnchorKind.Custom" /> 使用的垂直枢轴比例，通常为 <c>0</c> 到
		///         <c>1</c>；默认值 <c>0</c> 使用上边缘。
		///     </para>
		/// </summary>
		public float AnchorCustomPivotY { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Godot resource path for the pile icon (for example, <c>res://my_mod/icons/my_pile.png</c>).
		///     </para>
		///     <para xml:lang="zh-CN">
		///         牌堆图标的 Godot 资源路径（例如 <c>res://my_mod/icons/my_pile.png</c>）。
		///     </para>
		/// </summary>
		public string? IconPath { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Optional input action IDs forwarded to <c>NCardPileScreen.ShowScreen</c>. Each array element
		///         is one ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         转发给 <c>NCardPileScreen.ShowScreen</c> 的可选输入操作 ID；每个数组元素表示一个 ID。
		///     </para>
		/// </summary>
		public string[]? Hotkeys { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Only meaningful for <see cref="F:STS2RitsuLib.CardPiles.ModCardPileUiStyle.ExtraHand" />: when
		///         <see langword="true" />, cards in the pile are rendered as <c>NCard</c> nodes inside its container.
		///         <see cref="P:STS2RitsuLib.Interop.AutoRegistration.RegisterOwnedCardPileAttribute.ExtraHandAllowCardPlay" /> forces this behavior for a play-enabled extra hand.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         仅对 <see cref="F:STS2RitsuLib.CardPiles.ModCardPileUiStyle.ExtraHand" /> 有意义：为 <see langword="true" /> 时，
		///         牌堆中的卡牌会在容器内渲染为 <c>NCard</c> 节点。对于允许打出的额外手牌，
		///         <see cref="P:STS2RitsuLib.Interop.AutoRegistration.RegisterOwnedCardPileAttribute.ExtraHandAllowCardPlay" /> 会强制启用此行为。
		///     </para>
		/// </summary>
		public bool CardShouldBeVisible { get; set; }

		/// <summary>
		///     <para xml:lang="en">Built-in extra-hand arrangement direction. Defaults to the vanilla hand layout.</para>
		///     <para xml:lang="zh-CN">额外手牌的内置排列方向。默认为原版手牌布局。</para>
		/// </summary>
		public ModExtraHandLayoutDirection ExtraHandDirection { get; set; } = ModExtraHandLayoutDirection.VanillaHand;

		/// <summary>
		///     <para xml:lang="en">Horizontal or vertical extra-hand spacing in pixels. Defaults to <c>110</c>.</para>
		///     <para xml:lang="zh-CN">额外手牌的水平或垂直像素间距。默认为 <c>110</c>。</para>
		/// </summary>
		public float ExtraHandSpacing { get; set; } = 110f;

		/// <summary>
		///     <para xml:lang="en">Normal extra-hand card scale. Defaults to <c>0.65</c>.</para>
		///     <para xml:lang="zh-CN">额外手牌中卡牌的常态缩放比例。默认为 <c>0.65</c>。</para>
		/// </summary>
		public float ExtraHandCardScale { get; set; } = 0.65f;

		/// <summary>
		///     <para xml:lang="en">Focused extra-hand card scale. Defaults to <c>1</c>.</para>
		///     <para xml:lang="zh-CN">额外手牌中卡牌获得焦点时的缩放比例。默认为 <c>1</c>。</para>
		/// </summary>
		public float ExtraHandHoverScale { get; set; } = 1f;

		/// <summary>
		///     <para xml:lang="en">
		///         Whether extra-hand cards use vanilla playable-glow rules. Defaults to <see langword="true" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         额外手牌卡牌是否使用原版可打出发光规则。默认为 <see langword="true" />。
		///     </para>
		/// </summary>
		public bool ExtraHandShowPlayableGlow { get; set; } = true;

		/// <summary>
		///     <para xml:lang="en">
		///         Whether the extra-hand pile has manual-card-play capability through the vanilla pipeline,
		///         including hand-consistent cost display, validation, and payment. Play-enabled cards automatically
		///         participate in core empty-hand and playable-card queries and are represented by card nodes.
		///         This also determines each new
		///         container's initial runtime availability. Defaults to
		///         <see langword="true" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         额外手牌牌堆是否具备通过原版流程手动出牌的能力，包括与手牌一致的费用显示、验证及支付；
		///         允许打出的卡牌会自动参与核心空手及可打出卡牌查询，并由卡牌节点表示。该值也决定每个新
		///         容器的运行时可用性初始值。默认为 <see langword="true" />。
		///     </para>
		/// </summary>
		public bool ExtraHandAllowCardPlay { get; set; } = true;

		/// <summary>
		///     <para xml:lang="en">
		///         Optional base-game hand semantics applied to cards in an extra-hand pile. The default does not
		///         add semantics beyond those required by <see cref="P:STS2RitsuLib.Interop.AutoRegistration.RegisterOwnedCardPileAttribute.ExtraHandAllowCardPlay" />. Extra-hand cards
		///         never count toward the base-game maximum hand size or reduce its draw capacity.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         应用于额外手牌牌堆卡牌的可选游戏原有手牌语义。默认不添加
		///         <see cref="P:STS2RitsuLib.Interop.AutoRegistration.RegisterOwnedCardPileAttribute.ExtraHandAllowCardPlay" /> 所要求语义之外的行为。额外手牌卡牌不会计入游戏原有
		///         最大手牌数量，也不会减少其抽牌容量。
		///     </para>
		/// </summary>
		/// <exception cref="T:System.ArgumentOutOfRangeException">
		///     <para xml:lang="en">The assigned value contains an undefined behavior flag.</para>
		///     <para xml:lang="zh-CN">所赋值包含未定义的行为标志。</para>
		/// </exception>
		public ModExtraHandBehavior ExtraHandBehaviors
		{
			get
			{
				return _extraHandBehaviors;
			}
			set
			{
				if ((value & ~ModExtraHandBehavior.FullHand) != ModExtraHandBehavior.None)
				{
					throw new ArgumentOutOfRangeException("ExtraHandBehaviors", value, "The extra-hand behavior value contains an undefined flag.");
				}
				_extraHandBehaviors = value;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         X component of the screen-space offset applied after automatic hover-tip placement.
		///     </para>
		///     <para xml:lang="zh-CN">自动放置悬停提示后应用的屏幕空间 X 轴偏移。</para>
		/// </summary>
		public float HoverTipOffsetX { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         Y component of the screen-space offset applied after automatic hover-tip placement.
		///     </para>
		///     <para xml:lang="zh-CN">自动放置悬停提示后应用的屏幕空间 Y 轴偏移。</para>
		/// </summary>
		public float HoverTipOffsetY { get; set; }

		/// <summary>
		///     <para xml:lang="en">Hover-tip placement relative to the pile button.</para>
		///     <para xml:lang="zh-CN">悬停提示相对于牌堆按钮的放置位置。</para>
		/// </summary>
		public ModCardPileHoverTipPlacement HoverTipPlacement { get; set; }
	}
	/// <summary>
	///     <para xml:lang="en">Base metadata for declarations processed by the RitsuLib auto-registration pipeline.</para>
	///     <para xml:lang="zh-CN">由 RitsuLib 自动注册管线处理的声明式注册基础元数据。</para>
	/// </summary>
	public abstract class AutoRegistrationAttribute : Attribute
	{
		/// <summary>
		///     <para xml:lang="en">Local ordering within the same registration phase. Lower values run first.</para>
		///     <para xml:lang="zh-CN">同一注册阶段内的局部排序。数值越小越先运行。</para>
		/// </summary>
		public int Order { get; set; }

		/// <summary>
		///     <para xml:lang="en">
		///         When <see langword="true" /> on an attribute declared on a base type, the registration is available to concrete
		///         derived
		///         types. The nearest declaration wins per logical registration slot: a direct declaration can replace
		///         inherited configuration such as a pool, count, path, placement, or threshold, while registrations for
		///         distinct target IDs or scopes remain additive.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当基类型上声明的特性将此项设为 <see langword="true" /> 时，该注册可应用到具体派生类型。
		///         每个逻辑注册槽位采用距离派生类型最近的声明：
		///         直接声明可以替换继承的卡池、数量、路径、位置或阈值等配置，而不同目标 ID 或作用域的注册仍会累加。
		///     </para>
		/// </summary>
		public bool Inherit { get; set; }
	}
