	/// <summary>
	///     <para xml:lang="en">
	///         Handles a local right-click request before the built-in model-interface handler.
	///     </para>
	///     <para xml:lang="zh-CN">在内置的模型接口处理器之前处理本地右键请求。</para>
	/// </summary>
	public interface IModRightClickHandler
	{
		/// <summary>
		///     <para xml:lang="en">Gets the handler priority; higher-priority handlers run first.</para>
		///     <para xml:lang="zh-CN">获取处理器优先级；优先级越高，运行越早。</para>
		/// </summary>
		int Priority => 0;

		/// <summary>
		///     <para xml:lang="en">
		///         Returns <see langword="true" /> when the request was accepted and its input should be consumed.
		///     </para>
		///     <para xml:lang="zh-CN">请求已被接受且应消耗此次输入时返回 <see langword="true" />。</para>
		/// </summary>
		bool TryHandle(ModRightClickContext context);
	}
	/// <summary>
	///     <para xml:lang="en">Identifies a registered right-click binding.</para>
	///     <para xml:lang="zh-CN">标识一个已注册的右键绑定。</para>
	/// </summary>
	public readonly record struct ModRightClickBindingId(string Id)
	{
		/// <inheritdoc />
		public override string ToString()
		{
			return Id;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Describes a locally dispatched right-click request.</para>
	///     <para xml:lang="zh-CN">描述一个在本地分发的右键请求。</para>
	/// </summary>
	/// <param name="Player">
	///     <para xml:lang="en">The local player who initiated the request.</para>
	///     <para xml:lang="zh-CN">发起请求的本地玩家。</para>
	/// </param>
	/// <param name="Model">
	///     <para xml:lang="en">The model that was clicked.</para>
	///     <para xml:lang="zh-CN">被点击的模型。</para>
	/// </param>
	/// <param name="Trigger">
	///     <para xml:lang="en">Metadata about the input that triggered the request.</para>
	///     <para xml:lang="zh-CN">触发该请求的输入元数据。</para>
	/// </param>
	public readonly record struct ModRightClickContext(Player Player, AbstractModel Model, ModRightClickTrigger Trigger);
	/// <summary>
	///     <para xml:lang="en">
	///         Describes a synchronized right-click action when it reaches the action queue.
	///     </para>
	///     <para xml:lang="zh-CN">描述同步的右键操作进入行动队列时的执行状态。</para>
	/// </summary>
	/// <param name="Player">
	///     <para xml:lang="en">The player who owns the queued right-click action.</para>
	///     <para xml:lang="zh-CN">拥有队列中右键操作的玩家。</para>
	/// </param>
	/// <param name="Model">
	///     <para xml:lang="en">The model resolved at execution time.</para>
	///     <para xml:lang="zh-CN">执行时解析出的模型。</para>
	/// </param>
	/// <param name="Trigger">
	///     <para xml:lang="en">Metadata about the input that triggered the action.</para>
	///     <para xml:lang="zh-CN">触发该操作的输入元数据。</para>
	/// </param>
	/// <param name="PlayerChoiceContext">
	///     <para xml:lang="en">
	///         The queue-backed choice context available to command APIs that require <c>PlayerChoiceContext</c>.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         由队列提供的选择上下文，可供需要 <c>PlayerChoiceContext</c> 的命令 API 使用。
	///     </para>
	/// </param>
	/// <param name="Action">
	///     <para xml:lang="en">The underlying base-game action used for queue ordering.</para>
	///     <para xml:lang="zh-CN">用于队列排序的底层原版行动。</para>
	/// </param>
	public readonly record struct ModRightClickExecutionContext(Player Player, AbstractModel Model, ModRightClickTrigger Trigger, GameActionPlayerChoiceContext? PlayerChoiceContext, GameAction? Action);
	/// <summary>
	///     <para xml:lang="en">Lists the model families supported by the built-in right-click node patches.</para>
	///     <para xml:lang="zh-CN">列出内置右键节点补丁支持的模型类别。</para>
	/// </summary>
	public enum ModRightClickModelKind
	{
		/// <summary>
		///     <para xml:lang="en">A card in a supported combat UI.</para>
		///     <para xml:lang="zh-CN">受支持战斗界面中的卡牌。</para>
		/// </summary>
		Card,
		/// <summary>
		///     <para xml:lang="en">A relic.</para>
		///     <para xml:lang="zh-CN">遗物。</para>
		/// </summary>
		Relic,
		/// <summary>
		///     <para xml:lang="en">A power.</para>
		///     <para xml:lang="zh-CN">能力。</para>
		/// </summary>
		Power,
		/// <summary>
		///     <para xml:lang="en">A potion.</para>
		///     <para xml:lang="zh-CN">药水。</para>
		/// </summary>
		Potion,
		/// <summary>
		///     <para xml:lang="en">An orb in the local player's active orb queue.</para>
		///     <para xml:lang="zh-CN">本地玩家当前充能球队列中的充能球。</para>
		/// </summary>
		Orb
	}
	/// <summary>
	///     <para xml:lang="en">Registers and dispatches synchronized right-click interactions for models.</para>
	///     <para xml:lang="zh-CN">注册并分发模型的同步右键交互。</para>
	/// </summary>
	public static class ModRightClickRegistry
	{
		private sealed class BuiltInModelRightClickHandler : IModRightClickHandler
		{
			public int Priority => int.MinValue;

			public bool TryHandle(ModRightClickContext context)
			{
				List<ModRightClickBindingId> list = CollectBindingIds(context);
				if (list.Count > 0)
				{
					return TryRequestSyncedModelAction(context, list);
				}
				return false;
			}

			private static List<ModRightClickBindingId> CollectBindingIds(ModRightClickContext context)
			{
				List<LocalRightClickCandidate> list = (from binding in GetBindingsSnapshot()
					where binding.ModelType.IsInstanceOfType(context.Model)
					where TryCanHandleLocal(binding, context)
					select new LocalRightClickCandidate(binding.Id, binding.Priority, binding.Sequence)).ToList();
				if (context.Model is IModRightClickableModel rightClickable && TryCanHandleRightClickable(rightClickable, context))
				{
					list.Add(new LocalRightClickCandidate(InterfaceBindingId, int.MinValue, long.MaxValue));
				}
				AddCapabilityBindings(context, list);
				return (from candidate in list
					orderby candidate.Priority descending, candidate.Sequence
					select candidate.Id).ToList();
			}

			private static void AddCapabilityBindings(ModRightClickContext context, List<LocalRightClickCandidate> candidates)
			{
				IReadOnlyList<IModelRightClickCapability> allRightClickCapabilities = GetAllRightClickCapabilities(context.Model);
				List<SelectedRightClickCapability> list = new List<SelectedRightClickCapability>();
				int num = int.MinValue;
				for (int i = 0; i < allRightClickCapabilities.Count; i++)
				{
					IModelRightClickCapability modelRightClickCapability = allRightClickCapabilities[i];
					if (TryCanHandleCapability(modelRightClickCapability, context))
					{
						list.Add(new SelectedRightClickCapability(i, GetCapabilityId(modelRightClickCapability)));
						num = Math.Max(num, modelRightClickCapability.RightClickPriority);
					}
				}
				if (list.Count != 0)
				{
					candidates.Add(new LocalRightClickCandidate(CreateCapabilityBindingId(list), num, long.MinValue));
				}
			}

			private static bool TryCanHandleRightClickable(IModRightClickableModel rightClickable, ModRightClickContext context)
			{
				try
				{
					return rightClickable.CanHandleRightClickLocal(context);
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[RightClick] Interface preflight failed. ModelId='{context.Model.Id}' OwnerType='{((object)context.Model).GetType().FullName}' SourceType='{rightClickable.GetType().FullName}' Error='{ex.Message}'", 1);
					return false;
				}
			}

			private static bool TryCanHandleLocal(RegisteredRightClickBinding binding, ModRightClickContext context)
			{
				if (binding.CanHandleLocal == null)
				{
					return true;
				}
				try
				{
					return binding.CanHandleLocal(context);
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[RightClick] Binding preflight failed. BindingId='{binding.Id}' ModelId='{context.Model.Id}' OwnerType='{((object)context.Model).GetType().FullName}' Error='{ex.Message}'", 1);
					return false;
				}
			}
		}

