		private sealed class RegisteredRightClickBinding(ModRightClickBindingId id, Type modelType, Func<ModRightClickContext, bool>? canHandleLocal, Func<ModRightClickExecutionContext, bool>? canExecute, Func<ModRightClickExecutionContext, Task> execute, int priority, long sequence) : IDisposable
		{
			private bool _disposed;

			public ModRightClickBindingId Id { get; } = id;

			public Type ModelType { get; } = modelType;

			public Func<ModRightClickContext, bool>? CanHandleLocal { get; } = canHandleLocal;

			public Func<ModRightClickExecutionContext, bool>? CanExecute { get; } = canExecute;

			public Func<ModRightClickExecutionContext, Task> Execute { get; } = execute;

			public int Priority { get; } = priority;

			public long Sequence { get; } = sequence;

			public void Dispose()
			{
				if (_disposed)
				{
					return;
				}
				_disposed = true;
				using (Gate.EnterScope())
				{
					Bindings.Remove(this);
				}
			}
		}

