		/// <summary>
		///     <para xml:lang="en">Registers a custom local handler. Higher-priority handlers run first.</para>
		///     <para xml:lang="zh-CN">注册自定义本地处理器；优先级越高，运行越早。</para>
		/// </summary>
		public static void Register(IModRightClickHandler handler)
		{
			ArgumentNullException.ThrowIfNull(handler, "handler");
			using (Gate.EnterScope())
			{
				if (!Handlers.Any((RegisteredLocalRightClickHandler existing) => EqualityComparer<IModRightClickHandler>.Default.Equals(existing.Handler, handler)))
				{
					Handlers.Add(new RegisteredLocalRightClickHandler(handler, Interlocked.Increment(ref _nextHandlerSequence), IsBuiltIn: false));
					SortHandlers();
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a synchronized right-click binding for models of type <typeparamref name="TModel" />.
		///     </para>
		///     <para xml:lang="zh-CN">为 <typeparamref name="TModel" /> 类型的模型注册同步右键绑定。</para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">The ID of the mod that owns the binding.</para>
		///     <para xml:lang="zh-CN">拥有该绑定的模组 ID。</para>
		/// </param>
		/// <param name="localStem">
		///     <para xml:lang="en">The binding's mod-local ID stem.</para>
		///     <para xml:lang="zh-CN">该绑定在模组内部使用的 ID 主体。</para>
		/// </param>
		/// <param name="canHandle">
		///     <para xml:lang="en">
		///         The execution-time guard, invoked after each peer resolves the synchronized model. Do not use it for
		///         local-only UI filtering.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         执行阶段的判断条件，在各端解析出同步模型后调用。请勿将其用于仅限本地的界面筛选。
		///     </para>
		/// </param>
		/// <param name="execute">
		///     <para xml:lang="en">The synchronized right-click behavior.</para>
		///     <para xml:lang="zh-CN">同步执行的右键操作。</para>
		/// </param>
		/// <param name="priority">
		///     <para xml:lang="en">The binding priority; bindings with higher values run first.</para>
		///     <para xml:lang="zh-CN">绑定优先级；数值越高，运行越早。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A handle whose disposal unregisters the binding.</para>
		///     <para xml:lang="zh-CN">释放后会注销该绑定的句柄。</para>
		/// </returns>
		public static IDisposable Register<TModel>(string modId, string localStem, Func<ModRightClickContext, bool> canHandle, Func<ModRightClickExecutionContext, Task> execute, int priority = 0) where TModel : AbstractModel
		{
			ArgumentNullException.ThrowIfNull(canHandle, "canHandle");
			return Register<TModel>(modId, localStem, execute, priority, null, (ModRightClickExecutionContext context) => canHandle(new ModRightClickContext(context.Player, context.Model, context.Trigger)));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a synchronized right-click binding for models of type <typeparamref name="TModel" />.
		///     </para>
		///     <para xml:lang="zh-CN">为 <typeparamref name="TModel" /> 类型的模型注册同步右键绑定。</para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">The ID of the mod that owns the binding.</para>
		///     <para xml:lang="zh-CN">拥有该绑定的模组 ID。</para>
		/// </param>
		/// <param name="localStem">
		///     <para xml:lang="en">The binding's mod-local ID stem.</para>
		///     <para xml:lang="zh-CN">该绑定在模组内部使用的 ID 主体。</para>
		/// </param>
		/// <param name="execute">
		///     <para xml:lang="en">The synchronized right-click behavior.</para>
		///     <para xml:lang="zh-CN">同步执行的右键操作。</para>
		/// </param>
		/// <param name="priority">
		///     <para xml:lang="en">The binding priority; bindings with higher values run first.</para>
		///     <para xml:lang="zh-CN">绑定优先级；数值越高，运行越早。</para>
		/// </param>
		/// <param name="canHandleLocal">
		///     <para xml:lang="en">
		///         An optional local-only fast filter. Check only stable local UI facts here; mutable gameplay state should be
		///         checked by <paramref name="canExecute" /> or <paramref name="execute" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选且仅在本地运行的快速筛选。此处只应检查稳定的本地界面信息；可变的游戏状态应由
		///         <paramref name="canExecute" /> 或 <paramref name="execute" /> 检查。
		///     </para>
		/// </param>
		/// <param name="canExecute">
		///     <para xml:lang="en">
		///         An optional execution-time guard, invoked after each peer resolves the synchronized model.
		///     </para>
		///     <para xml:lang="zh-CN">可选的执行阶段判断条件，在各端解析出同步模型后调用。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A handle whose disposal unregisters the binding.</para>
		///     <para xml:lang="zh-CN">释放后会注销该绑定的句柄。</para>
		/// </returns>
		public static IDisposable Register<TModel>(string modId, string localStem, Func<ModRightClickExecutionContext, Task> execute, int priority = 0, Func<ModRightClickContext, bool>? canHandleLocal = null, Func<ModRightClickExecutionContext, bool>? canExecute = null) where TModel : AbstractModel
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(localStem, "localStem");
			ArgumentNullException.ThrowIfNull(execute, "execute");
			ModRightClickBindingId id = new ModRightClickBindingId(ModContentRegistry.GetQualifiedRightClickId(modId, localStem));
			RegisteredRightClickBinding registeredRightClickBinding = new RegisteredRightClickBinding(id, typeof(TModel), canHandleLocal, canExecute, execute, priority, Interlocked.Increment(ref _nextBindingSequence));
			using (Gate.EnterScope())
			{
				if (Bindings.Any((RegisteredRightClickBinding existing) => existing.Id == id))
				{
					throw new InvalidOperationException($"Right-click binding is already registered: {id}");
				}
				Bindings.Add(registeredRightClickBinding);
				SortBindings();
				return registeredRightClickBinding;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Attempts to dispatch a local right-click request.</para>
		///     <para xml:lang="zh-CN">尝试分发本地右键请求。</para>
		/// </summary>
		public static bool TryDispatch(ModRightClickContext context)
		{
			RegisteredLocalRightClickHandler[] array;
			using (Gate.EnterScope())
			{
				array = Handlers.ToArray();
			}
			RegisteredLocalRightClickHandler[] array2 = array;
			foreach (RegisteredLocalRightClickHandler registeredLocalRightClickHandler in array2)
			{
				registeredLocalRightClickHandler.Deconstruct(out IModRightClickHandler Handler, out long _, out bool IsBuiltIn);
				IModRightClickHandler modRightClickHandler = Handler;
				try
				{
					if (modRightClickHandler.TryHandle(context))
					{
						IsBuiltIn = true;
						return IsBuiltIn;
					}
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[RightClick] Local handler failed. HandlerType='{modRightClickHandler.GetType().FullName}' ModelId='{context.Model.Id}' ModelType='{((object)context.Model).GetType().FullName}' Error='{ex.Message}'", 1);
				}
			}
			return false;
		}

		internal static void RegisterBuiltInSyncDescriptors()
		{
			RitsuLibManagedNetActions.Register(CombatActionDescriptor);
			RitsuLibManagedNetActions.Register(NonCombatActionDescriptor);
		}

		private static bool TryRequestSyncedModelAction(ModRightClickContext context, IReadOnlyList<ModRightClickBindingId> bindingIds)
		{
			if (!TryCreatePayload(context, out var payload))
			{
				return false;
			}
			if (!CanRequestRightClickAction(payload))
			{
				return false;
			}
			RegisterBuiltInSyncDescriptors();
			payload = payload with
			{
				BindingIds = new global::<>z__ReadOnlyArray<ModRightClickBindingId>(bindingIds.ToArray())
			};
			RitsuLibManagedNetActionDescriptor<ModRightClickSyncPayload> descriptor = (CombatManager.Instance.IsInProgress ? CombatActionDescriptor : NonCombatActionDescriptor);
			return RitsuLibManagedNetActions.Request(RunManager.Instance, descriptor, payload, context.Player.NetId);
		}

		private static bool CanRequestRightClickAction(ModRightClickSyncPayload payload)
		{
			//IL_002d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0033: Invalid comparison between Unknown and I4
			//IL_0048: Unknown result type (might be due to invalid IL or missing references)
			//IL_004e: Invalid comparison between Unknown and I4
			RunManager instance = RunManager.Instance;
			INetGameService val = ((instance != null) ? instance.NetService : null);
			if (instance == null || val == null)
			{
				return false;
			}
			if (CombatManager.Instance.IsInProgress && (int)instance.ActionQueueSynchronizer.CombatState != 2)
			{
				return false;
			}
			if (!RequiresRightClickV2(payload))
			{
				return true;
			}
			if (val == null)
			{
				goto IL_00cc;
			}
			bool flag;
			if ((int)val.Type != 1)
			{
				NetClientGameService val2 = (NetClientGameService)(object)((val is NetClientGameService) ? val : null);
				if (val2 == null)
				{
					NetHostGameService val3 = (NetHostGameService)(object)((val is NetHostGameService) ? val : null);
					if (val3 == null)
					{
						goto IL_00cc;
					}
					flag = val3.ConnectedPeers.Where(delegate(NetClientData peer)
					{
						//IL_0000: Unknown result type (might be due to invalid IL or missing references)
						return peer.readyForBroadcasting;
					}).All(delegate(NetClientData peer)
					{
						//IL_0000: Unknown result type (might be due to invalid IL or missing references)
						return PeerSupportsRightClickV2(peer.peerId);
					});
				}
				else
				{
					flag = PeerSupportsRightClickV2(val2.HostNetId);
				}
			}
			else
			{
				flag = true;
			}
			goto IL_00cf;
			IL_00cf:
			bool num = flag;
			if (!num && Interlocked.Exchange(ref _unsupportedProtocolWarningLogged, 1) == 0)
			{
				RitsuLibFramework.Logger.Warn("[RightClick] A connected peer does not support the model-right-click v2 protocol. The request was not sent.", 1);
			}
			return num;
			IL_00cc:
			flag = false;
			goto IL_00cf;
		}

		private static bool RequiresRightClickV2(ModRightClickSyncPayload payload)
		{
			if (payload.Kind != ModRightClickModelKind.Orb)
			{
				return payload.Trigger.Source == ModRightClickSource.CombatPileCard;
			}
			return true;
		}

		private static bool PeerSupportsRightClickV2(ulong peerNetId)
		{
			if (RitsuLibSidecarSessionManager.TryGetPeerFeatures(peerNetId, out var features))
			{
				return (features & RitsuLibSidecarPeerFeatures.ModelRightClickV2) != 0;
			}
			return false;
		}

		private static bool TryCreatePayload(ModRightClickContext context, out ModRightClickSyncPayload payload)
		{
			payload = default(ModRightClickSyncPayload);
			if (!TryGetModelKind(context.Model, context.Player, out var kind))
			{
				return false;
			}
			if (!ModModelIdentityRegistry.TryGetToken(context.Model, out var token))
			{
				return false;
			}
			payload = new ModRightClickSyncPayload(context.Player.NetId, kind, token, context.Trigger, Array.Empty<ModRightClickBindingId>());
			return true;
		}

		private static bool TryGetModelKind(AbstractModel model, Player player, out ModRightClickModelKind kind)
		{
			kind = ModRightClickModelKind.Card;
			CardModel val = (CardModel)(object)((model is CardModel) ? model : null);
			if (val == null)
			{
				RelicModel val2 = (RelicModel)(object)((model is RelicModel) ? model : null);
				if (val2 == null)
				{
					PowerModel val3 = (PowerModel)(object)((model is PowerModel) ? model : null);
					if (val3 == null)
					{
						PotionModel val4 = (PotionModel)(object)((model is PotionModel) ? model : null);
						if (val4 == null)
						{
							OrbModel val5 = (OrbModel)(object)((model is OrbModel) ? model : null);
							if (val5 != null && IsOrbReachableForPlayer(val5, player))
							{
								kind = ModRightClickModelKind.Orb;
								return true;
							}
						}
						else if (val4.Owner == player)
						{
							kind = ModRightClickModelKind.Potion;
							return true;
						}
					}
					else if (IsPowerReachableForPlayer(val3, player))
					{
						kind = ModRightClickModelKind.Power;
						return true;
					}
				}
				else if (val2.Owner == player)
				{
					kind = ModRightClickModelKind.Relic;
					return true;
				}
			}
			else if (val.Owner == player)
			{
				kind = ModRightClickModelKind.Card;
				return true;
			}
			return false;
		}

		private static bool IsPowerReachableForPlayer(PowerModel power, Player player)
		{
			if (power.Owner.Player != player && power.Owner.PetOwner != player)
			{
				return power.Owner.IsEnemy;
			}
			return true;
		}

		private static bool IsOrbReachableForPlayer(OrbModel orb, Player player)
		{
			if (!orb.HasBeenRemovedFromState && orb.Owner == player)
			{
				PlayerCombatState playerCombatState = player.PlayerCombatState;
				if (playerCombatState == null)
				{
					return false;
				}
				return playerCombatState.OrbQueue.Orbs.Contains(orb);
			}
			return false;
		}

		private static byte[] SerializePayload(ModRightClickSyncPayload payload)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_000d: Expected O, but got Unknown
			//IL_012f: Unknown result type (might be due to invalid IL or missing references)
			PacketWriter val = new PacketWriter
			{
				WarnOnGrow = false
			};
			val.WriteULong(payload.OwnerNetId, 64);
			val.WriteEnum<ModRightClickModelKind>(payload.Kind);
			PacketWriterExtensions.WriteFullModelId(val, payload.Token.ModelId);
			val.WriteUInt(payload.Token.Identity.Value, 32);
			val.WriteBool(payload.Trigger.IsController);
			val.WriteBool(payload.Trigger.Metadata != null);
			if (payload.Trigger.Metadata != null)
			{
				WritePayloadString(val, payload.Trigger.Metadata, "metadata");
			}
			SerializeBindingIds(val, payload.BindingIds);
			val.WriteByte((byte)167, 8);
			val.WriteEnum<ModRightClickSource>(payload.Trigger.Source);
			val.WriteBool(payload.Trigger.ExpectedCardPile.HasValue);
			if (payload.Trigger.ExpectedCardPile.HasValue)
			{
				val.WriteEnum<PileType>(payload.Trigger.ExpectedCardPile.Value);
			}
			EnsurePayloadWithinLimit(val);
			val.ZeroByteRemainder();
			return val.Buffer.AsSpan(0, val.BytePosition).ToArray();
		}

		private static ModRightClickSyncPayload DeserializePayload(ReadOnlySpan<byte> bytes)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Expected O, but got Unknown
			PacketReader val = new PacketReader();
			val.Reset(bytes.ToArray());
			ulong ownerNetId = val.ReadULong(64);
			ModRightClickModelKind kind = val.ReadEnum<ModRightClickModelKind>();
			ModelId modelId = PacketReaderExtensions.ReadFullModelId(val);
			ModModelIdentity identity = new ModModelIdentity(val.ReadUInt(32));
			bool isController = val.ReadBool();
			string metadata = (val.ReadBool() ? ReadPayloadString(val, "metadata") : null);
			IReadOnlyList<ModRightClickBindingId> readOnlyList = DeserializeBindingIds(val);
			if (readOnlyList.Count == 0)
			{
				readOnlyList = new <>z__ReadOnlySingleElementList<ModRightClickBindingId>(InterfaceBindingId);
			}
			return new ModRightClickSyncPayload(Trigger: DeserializeTriggerExtension(val, isController, metadata), OwnerNetId: ownerNetId, Kind: kind, Token: new ModModelIdentityToken(identity, modelId), BindingIds: readOnlyList);
		}

		private static ModRightClickTrigger DeserializeTriggerExtension(PacketReader reader, bool isController, string? metadata)
		{
			//IL_0077: Unknown result type (might be due to invalid IL or missing references)
			if (reader.Buffer.Length * 8 - reader.BitPosition < 8 || reader.ReadByte(8) != 167)
			{
				return new ModRightClickTrigger(isController, metadata);
			}
			ModRightClickSource modRightClickSource = reader.ReadEnum<ModRightClickSource>();
			if (!Enum.IsDefined(modRightClickSource))
			{
				throw new InvalidOperationException($"Unknown right-click source: {modRightClickSource}");
			}
			PileType? expectedCardPile = null;
			if (reader.ReadBool())
			{
				expectedCardPile = reader.ReadEnum<PileType>();
			}
			return new ModRightClickTrigger(isController, metadata, modRightClickSource, expectedCardPile);
		}

		private static async Task ExecuteManaged(RitsuLibManagedNetActionContext<ModRightClickSyncPayload> context)
		{
			if (context.Message.OwnerNetId == context.Player.NetId)
			{
				await ExecutePayload(context.Message, context.PlayerChoiceContext, (GameAction?)(object)context.Action);
			}
		}

		private static async Task ExecutePayload(ModRightClickSyncPayload payload, GameActionPlayerChoiceContext? playerChoiceContext, GameAction? action)
		{
			if (!TryGetPlayer(payload.OwnerNetId, out Player player) || !TryResolveModel(player, payload, out AbstractModel model))
			{
				return;
			}
			ModRightClickExecutionContext executionContext = new ModRightClickExecutionContext(player, model, payload.Trigger, playerChoiceContext, action);
			bool completed = false;
			foreach (ModRightClickBindingId bindingId in payload.BindingIds)
			{
				try
				{
					if (await TryExecuteBinding(bindingId, model, executionContext))
					{
						completed = true;
					}
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn($"[RightClick] Binding execution failed. BindingId='{bindingId}' ModelId='{model.Id}' OwnerType='{((object)model).GetType().FullName}' Error='{ex.Message}'", 1);
				}
				if (!IsModelStillInState(model))
				{
					break;
				}
			}
			if (completed && IsModelStillInState(model))
			{
				model.InvokeExecutionFinished();
			}
		}

		private static bool IsModelStillInState(AbstractModel model)
		{
			try
			{
				CardModel val = (CardModel)(object)((model is CardModel) ? model : null);
				bool result;
				if (val == null)
				{
					RelicModel val2 = (RelicModel)(object)((model is RelicModel) ? model : null);
					if (val2 == null)
					{
						PowerModel val3 = (PowerModel)(object)((model is PowerModel) ? model : null);
						if (val3 == null)
						{
							PotionModel val4 = (PotionModel)(object)((model is PotionModel) ? model : null);
							if (val4 == null)
							{
								OrbModel val5 = (OrbModel)(object)((model is OrbModel) ? model : null);
								result = val5 == null || IsOrbReachableForPlayer(val5, val5.Owner);
							}
							else
							{
								result = !val4.HasBeenRemovedFromState && val4.Owner.Potions.Contains(val4);
							}
						}
						else
						{
							result = val3.Owner.Powers.Contains(val3);
						}
					}
					else
					{
						result = !val2.HasBeenRemovedFromState && val2.Owner.Relics.Contains(val2);
					}
				}
				else
				{
					result = !val.HasBeenRemovedFromState;
				}
				return result;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[RightClick] Failed to check model state before ExecutionFinished. ModelId='{model.Id}' OwnerType='{((object)model).GetType().FullName}' Error='{ex.Message}'", 1);
				return false;
			}
		}

		private static bool TryGetPlayer(ulong ownerNetId, out Player player)
		{
			RunState obj = RunManager.Instance.DebugOnlyGetState();
			player = ((obj != null) ? obj.Players.FirstOrDefault((Player p) => p.NetId == ownerNetId) : null);
			return player != null;
		}

		private static bool TryResolveModel(Player player, ModRightClickSyncPayload payload, out AbstractModel model)
		{
			model = null;
			if (!ModModelIdentityRegistry.TryResolve(payload.Token, out AbstractModel model2))
			{
				return false;
			}
			switch (payload.Kind)
			{
			case ModRightClickModelKind.Card:
			{
				CardModel val2 = (CardModel)(object)((model2 is CardModel) ? model2 : null);
				if (val2 == null || val2.Owner != player || !IsCardInExpectedLocation(val2, payload.Trigger))
				{
					return false;
				}
				model = (AbstractModel)(object)val2;
				return true;
			}
			case ModRightClickModelKind.Relic:
			{
				RelicModel val4 = (RelicModel)(object)((model2 is RelicModel) ? model2 : null);
				if (val4 == null || val4.Owner != player)
				{
					return false;
				}
				model = (AbstractModel)(object)val4;
				return true;
			}
			case ModRightClickModelKind.Power:
			{
				PowerModel val3 = (PowerModel)(object)((model2 is PowerModel) ? model2 : null);
				if (val3 == null || !IsPowerReachableForPlayer(val3, player))
				{
					return false;
				}
				model = (AbstractModel)(object)val3;
				return true;
			}
			case ModRightClickModelKind.Potion:
			{
				PotionModel val5 = (PotionModel)(object)((model2 is PotionModel) ? model2 : null);
				if (val5 == null || val5.Owner != player)
				{
					return false;
				}
				model = (AbstractModel)(object)val5;
				return true;
			}
			case ModRightClickModelKind.Orb:
			{
				OrbModel val = (OrbModel)(object)((model2 is OrbModel) ? model2 : null);
				if (val == null || !IsOrbReachableForPlayer(val, player))
				{
					return false;
				}
				model = (AbstractModel)(object)val;
				return true;
			}
			default:
				return false;
			}
		}

		private static bool IsCardInExpectedLocation(CardModel card, ModRightClickTrigger trigger)
		{
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_008c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0092: Invalid comparison between Unknown and I4
			//IL_0040: Unknown result type (might be due to invalid IL or missing references)
			//IL_0046: Invalid comparison between Unknown and I4
			//IL_005e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0063: Unknown result type (might be due to invalid IL or missing references)
			//IL_0064: Unknown result type (might be due to invalid IL or missing references)
			//IL_006e: Unknown result type (might be due to invalid IL or missing references)
			//IL_006f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0073: Unknown result type (might be due to invalid IL or missing references)
			//IL_0078: Unknown result type (might be due to invalid IL or missing references)
			CardPile pile = card.Pile;
			PileType? val = ((pile != null) ? new PileType?(pile.Type) : ((PileType?)null));
			int result;
			switch (trigger.Source)
			{
			case ModRightClickSource.HandCard:
				return (int)val.GetValueOrDefault() == 2;
			case ModRightClickSource.CombatPileCard:
			{
				PileType? expectedCardPile = trigger.ExpectedCardPile;
				if (expectedCardPile.HasValue)
				{
					PileType valueOrDefault = expectedCardPile.GetValueOrDefault();
					if (ModRightClickCardPilePolicy.IsSupported(valueOrDefault))
					{
						result = ((val == (PileType?)valueOrDefault) ? 1 : 0);
						goto IL_0087;
					}
				}
				result = 0;
				goto IL_0087;
			}
			case ModRightClickSource.Unknown:
				return (int)val.GetValueOrDefault() == 2;
			default:
				{
					return false;
				}
				IL_0087:
				return (byte)result != 0;
			}
		}

		private static async Task<bool> TryExecuteBinding(ModRightClickBindingId bindingId, AbstractModel model, ModRightClickExecutionContext context)
		{
			if (bindingId == InterfaceBindingId)
			{
				if (!(model is IModRightClickableModel modRightClickableModel))
				{
					return false;
				}
				if (!TryCanExecuteRightClickable(modRightClickableModel, context, out var canExecute))
				{
					return false;
				}
				if (!canExecute)
				{
					return false;
				}
				await modRightClickableModel.OnRightClick(context);
				return true;
			}
			if (bindingId == CapabilityBindingId)
			{
				return await TryExecuteCapabilityRightClick(model, context, null);
			}
			if (TryParseCapabilityBindingId(bindingId, out IReadOnlyList<SelectedRightClickCapability> selectedCapabilities))
			{
				return await TryExecuteCapabilityRightClick(model, context, selectedCapabilities);
			}
			RegisteredRightClickBinding registeredRightClickBinding = TryGetBinding(bindingId);
			if (registeredRightClickBinding == null || !registeredRightClickBinding.ModelType.IsInstanceOfType(model))
			{
				return false;
			}
			if (!TryCanExecute(registeredRightClickBinding, context, out var canExecute2))
			{
				return false;
			}
			if (!canExecute2)
			{
				return false;
			}
			await registeredRightClickBinding.Execute(context);
			return true;
		}

		private static bool TryCanExecuteRightClickable(IModRightClickableModel rightClickable, ModRightClickExecutionContext context, out bool canExecute)
		{
			canExecute = false;
			try
			{
				canExecute = rightClickable.CanExecuteRightClick(context);
				return true;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[RightClick] Interface execute guard failed. ModelId='{context.Model.Id}' OwnerType='{((object)context.Model).GetType().FullName}' SourceType='{rightClickable.GetType().FullName}' Error='{ex.Message}'", 1);
				return false;
			}
		}

		private static bool TryCanExecute(RegisteredRightClickBinding binding, ModRightClickExecutionContext context, out bool canExecute)
		{
			canExecute = true;
			if (binding.CanExecute == null)
			{
				return true;
			}
			try
			{
				canExecute = binding.CanExecute(context);
				return true;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[RightClick] Binding execute guard failed. BindingId='{binding.Id}' ModelId='{context.Model.Id}' OwnerType='{((object)context.Model).GetType().FullName}' Error='{ex.Message}'", 1);
				return false;
			}
		}

		private static async Task<bool> TryExecuteCapabilityRightClick(AbstractModel model, ModRightClickExecutionContext context, IReadOnlyList<SelectedRightClickCapability>? selectedCapabilities)
		{
			bool completed = false;
			foreach (IModelRightClickCapability capability in GetRightClickCapabilities(model, selectedCapabilities))
			{
				if (TryCanExecuteCapability(capability, context, out var canExecute) && canExecute)
				{
					try
					{
						await capability.OnRightClick(context);
					}
					catch (Exception exception)
					{
						ModelCapabilityDiagnostics.WarnFailure("right-click execute", model, capability, exception);
						continue;
					}
					completed = true;
					if (capability.RightClickRunMode == ModelRightClickCapabilityRunMode.Exclusive)
					{
						break;
					}
				}
			}
			return completed;
		}

		private static IReadOnlyList<IModelRightClickCapability> GetRightClickCapabilities(AbstractModel model, IReadOnlyList<SelectedRightClickCapability>? selectedCapabilities = null)
		{
			IReadOnlyList<IModelRightClickCapability> capabilities = GetAllRightClickCapabilities(model);
			if (selectedCapabilities == null)
			{
				return capabilities;
			}
			List<IModelRightClickCapability> list = new List<IModelRightClickCapability>(selectedCapabilities.Count);
			list.AddRange(selectedCapabilities.Where(delegate(SelectedRightClickCapability selectedCapability)
			{
				SelectedRightClickCapability selectedRightClickCapability = selectedCapability;
				if (selectedRightClickCapability.Index >= 0)
				{
					selectedRightClickCapability = selectedCapability;
					if (selectedRightClickCapability.Index < capabilities.Count)
					{
						IReadOnlyList<IModelRightClickCapability> readOnlyList = capabilities;
						selectedRightClickCapability = selectedCapability;
						string capabilityId = GetCapabilityId(readOnlyList[selectedRightClickCapability.Index]);
						selectedRightClickCapability = selectedCapability;
						return string.Equals(capabilityId, selectedRightClickCapability.CapabilityId, StringComparison.Ordinal);
					}
				}
				return false;
			}).Select(delegate(SelectedRightClickCapability selectedCapability)
			{
				IReadOnlyList<IModelRightClickCapability> readOnlyList = capabilities;
				SelectedRightClickCapability selectedRightClickCapability = selectedCapability;
				return readOnlyList[selectedRightClickCapability.Index];
			}));
			return list;
		}

		private static IReadOnlyList<IModelRightClickCapability> GetAllRightClickCapabilities(AbstractModel model)
		{
			if (ModelCapabilities.TryGet(model, out ModelCapabilitySet collection))
			{
				return SortRightClickCapabilities(collection.All);
			}
			if (!ModelCapabilityDefaults.HasDefaultCapabilitySource(model))
			{
				return Array.Empty<IModelRightClickCapability>();
			}
			collection = ModelCapabilities.Get(model);
			return SortRightClickCapabilities(collection.All);
		}

		private static bool TryCanHandleCapability(IModelRightClickCapability capability, ModRightClickContext context)
		{
			try
			{
				return capability.CanHandleRightClickLocal(context);
			}
			catch (Exception exception)
			{
				ModelCapabilityDiagnostics.WarnFailure("right-click preflight", context.Model, capability, exception);
				return false;
			}
		}

		private static bool TryCanExecuteCapability(IModelRightClickCapability capability, ModRightClickExecutionContext context, out bool canExecute)
		{
			canExecute = false;
			try
			{
				canExecute = capability.CanExecuteRightClick(context);
				return true;
			}
			catch (Exception exception)
			{
				ModelCapabilityDiagnostics.WarnFailure("right-click execute", context.Model, capability, exception);
				return false;
			}
		}

		private static ModRightClickBindingId CreateCapabilityBindingId(IReadOnlyList<SelectedRightClickCapability> selectedCapabilities)
		{
			List<string> list = new List<string>(2 + selectedCapabilities.Count * 2)
			{
				CapabilityBindingId.Id,
				selectedCapabilities.Count.ToString(CultureInfo.InvariantCulture)
			};
			foreach (SelectedRightClickCapability selectedCapability in selectedCapabilities)
			{
				list.Add(selectedCapability.Index.ToString(CultureInfo.InvariantCulture));
				list.Add(selectedCapability.CapabilityId);
			}
			return new ModRightClickBindingId(string.Join("\u001f", list));
		}

		private static string GetCapabilityId(IModelRightClickCapability capability)
		{
			return ((IModelCapability)capability).CapabilityId;
		}

		private static bool TryParseCapabilityBindingId(ModRightClickBindingId bindingId, out IReadOnlyList<SelectedRightClickCapability> selectedCapabilities)
		{
			selectedCapabilities = Array.Empty<SelectedRightClickCapability>();
			string value = CapabilityBindingId.Id + "\u001f";
			if (!bindingId.Id.StartsWith(value, StringComparison.Ordinal))
			{
				return false;
			}
			string[] array = bindingId.Id.Split("\u001f");
			if (array.Length < 4 || !int.TryParse(array[1], NumberStyles.None, CultureInfo.InvariantCulture, out var result) || result <= 0 || array.Length != 2 + result * 2)
			{
				return false;
			}
			List<SelectedRightClickCapability> list = new List<SelectedRightClickCapability>(result);
			for (int i = 0; i < result; i++)
			{
				string s = array[2 + i * 2];
				string text = array[3 + i * 2];
				if (!int.TryParse(s, NumberStyles.None, CultureInfo.InvariantCulture, out var result2) || string.IsNullOrWhiteSpace(text))
				{
					return false;
				}
				list.Add(new SelectedRightClickCapability(result2, text));
			}
			selectedCapabilities = list;
			return true;
		}

		private static IReadOnlyList<IModelRightClickCapability> SortRightClickCapabilities(IReadOnlyList<IModelCapability> capabilities)
		{
			List<IModelRightClickCapability> list = new List<IModelRightClickCapability>();
			list.AddRange(from entry in capabilities.Select((IModelCapability capability, int index) => new OrderedRightClickCapability(capability, index))
				where entry.Capability is IModelRightClickCapability
				orderby ((IModelRightClickCapability)entry.Capability).RightClickPriority descending, entry.Index
				select (IModelRightClickCapability)entry.Capability);
			return new <>z__ReadOnlyList<IModelRightClickCapability>(list);
		}

		private static RegisteredRightClickBinding? TryGetBinding(ModRightClickBindingId bindingId)
		{
			using (Gate.EnterScope())
			{
				return Bindings.FirstOrDefault((RegisteredRightClickBinding binding) => binding.Id == bindingId);
			}
		}

		private static RegisteredRightClickBinding[] GetBindingsSnapshot()
		{
			using (Gate.EnterScope())
			{
				return Bindings.ToArray();
			}
		}

		private static void SortBindings()
		{
			Bindings.Sort(delegate(RegisteredRightClickBinding a, RegisteredRightClickBinding b)
			{
				int num = b.Priority.CompareTo(a.Priority);
				return (num == 0) ? a.Sequence.CompareTo(b.Sequence) : num;
			});
		}

		private static void SortHandlers()
		{
			Handlers.Sort(delegate(RegisteredLocalRightClickHandler a, RegisteredLocalRightClickHandler b)
			{
				int num = b.Handler.Priority.CompareTo(a.Handler.Priority);
				if (num != 0)
				{
					return num;
				}
				return (a.IsBuiltIn != b.IsBuiltIn) ? (a.IsBuiltIn ? 1 : (-1)) : a.Sequence.CompareTo(b.Sequence);
			});
		}

		private static void SerializeBindingIds(PacketWriter writer, IReadOnlyList<ModRightClickBindingId> bindingIds)
		{
			writer.WriteInt(bindingIds.Count, 32);
			foreach (ModRightClickBindingId bindingId in bindingIds)
			{
				WritePayloadString(writer, bindingId.Id, "binding id");
			}
		}

		private static IReadOnlyList<ModRightClickBindingId> DeserializeBindingIds(PacketReader reader)
		{
			if (reader.Buffer.Length * 8 - reader.BitPosition < 32)
			{
				return Array.Empty<ModRightClickBindingId>();
			}
			int num = reader.ReadInt(32);
			if (num <= 0)
			{
				return Array.Empty<ModRightClickBindingId>();
			}
			int num2 = reader.Buffer.Length * 8 - reader.BitPosition;
			if (num > num2 / 32)
			{
				throw new InvalidOperationException($"Right-click binding count {num} exceeds the payload's minimum encoded capacity.");
			}
			List<ModRightClickBindingId> list = new List<ModRightClickBindingId>(num);
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			for (int i = 0; i < num; i++)
			{
				string text = ReadPayloadString(reader, "binding id").Trim();
				if (text.Length == 0)
				{
					throw new InvalidOperationException("Right-click binding id cannot be empty.");
				}
				if (!hashSet.Add(text))
				{
					throw new InvalidOperationException("Duplicate right-click binding id: " + text);
				}
				list.Add(new ModRightClickBindingId(text));
			}
			return list;
		}

		private static void WritePayloadString(PacketWriter writer, string value, string fieldName)
		{
			int byteCount = Encoding.UTF8.GetByteCount(value);
			if (byteCount > 65536)
			{
				throw new InvalidOperationException($"Right-click {fieldName} is {byteCount} bytes; maximum payload is {65536} bytes.");
			}
			writer.WriteString(value);
			EnsurePayloadWithinLimit(writer);
		}

		private static string ReadPayloadString(PacketReader reader, string fieldName)
		{
			if (!HasRemainingBits(reader, 32L))
			{
				throw new InvalidOperationException("Missing right-click " + fieldName + " length.");
			}
			int num = reader.ReadInt(32);
			if (num < 0 || num > 65536 || !HasRemainingBits(reader, (long)num * 8L))
			{
				throw new InvalidOperationException($"Invalid right-click {fieldName} length: {num}.");
			}
			if (num == 0)
			{
				return string.Empty;
			}
			byte[] array = new byte[num];
			reader.ReadBytes(array, num);
			return Encoding.UTF8.GetString(array);
		}

		private static void EnsurePayloadWithinLimit(PacketWriter writer)
		{
			if (writer.BytePosition > 65536)
			{
				throw new InvalidOperationException($"Right-click payload exceeds {65536} bytes.");
			}
		}

		private static bool HasRemainingBits(PacketReader reader, long bitCount)
		{
			if (bitCount >= 0 && reader.BitPosition >= 0)
			{
				return (long)reader.Buffer.Length * 8L - reader.BitPosition >= bitCount;
			}
			return false;
		}

		static ModRightClickRegistry()
		{
			int num = 1;
			List<RegisteredLocalRightClickHandler> list = new List<RegisteredLocalRightClickHandler>(num);
			CollectionsMarshal.SetCount(list, num);
			CollectionsMarshal.AsSpan(list)[0] = new RegisteredLocalRightClickHandler(new BuiltInModelRightClickHandler(), 0L, IsBuiltIn: true);
			Handlers = list;
			Bindings = new List<RegisteredRightClickBinding>();
			InterfaceBindingId = new ModRightClickBindingId(ModContentRegistry.GetQualifiedRightClickId("com.ritsukage.sts2-RitsuLib", "model_interface"));
			CapabilityBindingId = new ModRightClickBindingId(ModContentRegistry.GetQualifiedRightClickId("com.ritsukage.sts2-RitsuLib", "model_capability"));
			CombatActionDescriptor = new RitsuLibManagedNetActionDescriptor<ModRightClickSyncPayload>("ritsulib", "model_right_click_combat", SerializePayload, DeserializePayload, ExecuteManaged, (GameActionType)2);
			NonCombatActionDescriptor = new RitsuLibManagedNetActionDescriptor<ModRightClickSyncPayload>("ritsulib", "model_right_click_noncombat", SerializePayload, DeserializePayload, ExecuteManaged, (GameActionType)3);
		}
	}
