			if (val != null)
			{
				StringName action = val.Action;
				if (action == MegaInput.cancel && ((InputEvent)val).IsPressed() && !((InputEvent)val).IsEcho() && ((Control)holder).HasFocus())
				{
					TryHandle(holder, new ModRightClickTrigger(isController: true, null, source, expectedCardPile));
				}
			}
		}

