			InputEventMouseButton val = (InputEventMouseButton)(object)((inputEvent is InputEventMouseButton) ? inputEvent : null);
			if (val != null && (long)val.ButtonIndex == 2 && ((InputEvent)val).IsPressed())
			{
				TryHandle(holder, new ModRightClickTrigger(isController: false, null, source, expectedCardPile));
			}
		}

		private static void TryHandle(NCardHolder holder, ModRightClickTrigger trigger)
		{
