			if (viewport.IsInputHandled())
			{
				return;
			}
			NPlayerHand instance = NPlayerHand.Instance;
			if (instance == null || instance.InCardPlay || NTargetManager.Instance.IsInSelection)
			{
				return;
			}
			CardModel cardModel = holder.CardModel;
			if (cardModel != null)
			{
				Player me = LocalContext.GetMe(cardModel.CombatState);
				if (me != null && ModRightClickRegistry.TryDispatch(new ModRightClickContext(me, (AbstractModel)(object)cardModel, trigger)))
				{
					viewport.SetInputAsHandled();
				}
			}
		}
	}
