			CardModel card = holder.CardModel;
			if (card == null)
			{
				return true;
			}
			CardPile pile = card.Pile;
			PileType? val = ((pile != null) ? new PileType?(pile.Type) : ((PileType?)null));
			if (val.HasValue)
			{
				PileType valueOrDefault = val.GetValueOrDefault();
				if (ModRightClickCardPilePolicy.IsSupported(valueOrDefault))
				{
					Player player = LocalContext.GetMe(card.CombatState);
					if (player == null)
					{
						return true;
					}
					ModRightClickTrigger trigger = new ModRightClickTrigger(Sts2InputCompat.IsUsingController, null, ModRightClickSource.CombatPileCard, valueOrDefault);
					if (!ModRightClickInputConsumer.TryDispatchAndConsumeInput((Func<bool>)(() => ModRightClickRegistry.TryDispatch(new ModRightClickContext(player, (AbstractModel)(object)card, trigger))), (Action)viewport.SetInputAsHandled))
					{
						return true;
					}
					return false;
				}
			}
			return true;
		}

		private static bool IsPileScreenGrid(NCardGrid grid)
		{
