namespace STS2RitsuLib.Graphics
{
	/// <summary>
	///     <para xml:lang="en">Applies the configured default 2D canvas texture filter to the current Godot viewport.</para>
	///     <para xml:lang="zh-CN">将配置的默认二维画布纹理过滤模式应用到当前 Godot 视口。</para>
	/// </summary>
	internal static class RitsuCanvasTextureFilterService
	{
		private static readonly Lock InitializeGate = new Lock();

		private static IDisposable? _lifecycleSubscription;

		private static bool _initialized;

		private static bool _initializing;

		/// <summary>
		///     <para xml:lang="en">Applies the current setting and subscribes to reapply it when the game becomes ready.</para>
		///     <para xml:lang="zh-CN">应用当前设置，并订阅游戏就绪事件以重新应用该设置。</para>
		/// </summary>
		internal static void Initialize()
		{
			using (InitializeGate.EnterScope())
			{
				if (_initialized || _initializing)
				{
					return;
				}
				_initializing = true;
			}
			try
			{
				ApplyConfiguredMode();
				if (_lifecycleSubscription == null)
				{
					_lifecycleSubscription = RitsuLibFramework.SubscribeLifecycle(delegate(GameReadyEvent evt)
					{
						ApplyMode(((Node)evt.Game).GetViewport(), RitsuLibSettingsStore.GetCanvasTextureFilterMode());
					});
				}
				using (InitializeGate.EnterScope())
				{
					_initialized = true;
				}
			}
			finally
			{
				using (InitializeGate.EnterScope())
				{
					_initializing = false;
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">Applies <paramref name="mode" /> to the root viewport when it is available.</para>
		///     <para xml:lang="zh-CN">在根视口可用时将 <paramref name="mode" /> 应用于它。</para>
		/// </summary>
		internal static void ApplyMode(string? mode)
		{
			MainLoop mainLoop = Engine.GetMainLoop();
			SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
			if (val != null)
			{
				Window root = val.Root;
				if (root != null)
				{
					ApplyMode((Viewport)(object)root, mode);
					return;
				}
			}
			RitsuLibFramework.Logger.Warn("[Graphics] Cannot apply the 2D texture filter because the root viewport is unavailable.", 1);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Normalizes a configured filter name to <c>nearest</c>, <c>linear</c>, <c>nearest_mipmap</c>, or
		///         <c>linear_mipmap</c>.
		///     </para>
		///     <para xml:lang="zh-CN">将配置的过滤名称规范化为 <c>nearest</c>、<c>linear</c>、<c>nearest_mipmap</c> 或 <c>linear_mipmap</c>。</para>
		/// </summary>
		internal static string NormalizeMode(string? mode)
		{
			switch (mode?.Trim().ToLowerInvariant())
			{
			case "nearest":
				return "nearest";
			case "linear":
				return "linear";
			case "nearest_mipmap":
			case "nearest_with_mipmaps":
				return "nearest_mipmap";
			default:
				return "linear_mipmap";
			}
		}

		private static void ApplyConfiguredMode()
		{
			ApplyMode(RitsuLibSettingsStore.GetCanvasTextureFilterMode());
		}

		private static void ApplyMode(Viewport viewport, string? mode)
		{
			//IL_0034: Unknown result type (might be due to invalid IL or missing references)
			//IL_0045: Unknown result type (might be due to invalid IL or missing references)
			//IL_0039: Unknown result type (might be due to invalid IL or missing references)
			//IL_003e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0043: Unknown result type (might be due to invalid IL or missing references)
			string text = NormalizeMode(mode);
			viewport.CanvasItemDefaultTextureFilter = (DefaultCanvasItemTextureFilter)(text switch
			{
				"nearest" => 0, 
				"linear" => 1, 
				"nearest_mipmap" => 3, 
				_ => 2, 
			});
			RitsuLibFramework.Logger.Info("[Graphics] 2D texture filter applied: " + text + ".", 1);
		}
	}
