	/// <summary>
	///     <para xml:lang="en">
	///         Coordinates manual and first-main-menu Harmony patch dumps using persisted RitsuLib settings.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         根据持久化的 RitsuLib 设置协调手动转储和首次进入主菜单时的 Harmony 补丁转储。
	///     </para>
	/// </summary>
	internal static class HarmonyPatchDumpCoordinator
	{
		private static int _autoDumpIssuedForSession;

		/// <summary>
		///     <para xml:lang="en">
		///         Handles the deferred call made after
		///         <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.MainMenu.NMainMenu" /> becomes ready. When enabled, an
		///         automatic dump is attempted at most once per process.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         处理 <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.MainMenu.NMainMenu" /> 就绪后的延迟调用。启用该设置
		///         时，每个进程最多尝试一次自动转储。
		///     </para>
		/// </summary>
		internal static void TryAutoDumpOnFirstMainMenu()
		{
			(string OutputPath, bool DumpOnFirstMainMenu) harmonyPatchDumpOptions = RitsuLibSettingsStore.GetHarmonyPatchDumpOptions();
			var (rawPath, _) = harmonyPatchDumpOptions;
			if (harmonyPatchDumpOptions.DumpOnFirstMainMenu && Interlocked.CompareExchange(ref _autoDumpIssuedForSession, 1, 0) == 0)
			{
				TryDumpToConfiguredPath(rawPath, "[HarmonyDump][Auto]", showPrompt: false);
			}
		}

		internal static void TryManualDumpFromSettings()
		{
			TryDumpToConfiguredPath(RitsuLibSettingsStore.GetHarmonyPatchDumpOptions().OutputPath, "[HarmonyDump][Manual]", showPrompt: true);
		}

		private static void TryDumpToConfiguredPath(string rawPath, string logPrefix, bool showPrompt)
		{
			string title = ModSettingsLocalization.Get("ritsulib.harmonyDump.prompt.title", "Harmony patch dump");
			string text = HarmonyPatchDumpWriter.TryResolveFilesystemPath(rawPath);
			string errorMessage;
			if (string.IsNullOrEmpty(text))
			{
				RitsuLibFramework.Logger.Warn(logPrefix + " Output path is empty or invalid. Set a path in RitsuLib settings (or use Browse).", 1);
				if (showPrompt)
				{
					string message = ModSettingsLocalization.Get("ritsulib.harmonyDump.prompt.invalidPath", "Export did not run: output path is empty or invalid. Configure a valid path first.");
					ShowPrompt(title, message);
				}
			}
			else if (!HarmonyPatchDumpWriter.TryWrite(text, out errorMessage))
			{
				RitsuLibFramework.Logger.Warn(logPrefix + " Failed to write dump: " + errorMessage, 1);
				if (showPrompt)
				{
					string format = ModSettingsLocalization.Get("ritsulib.harmonyDump.prompt.failed", "Export failed: {0}");
					ShowPrompt(title, string.Format(format, errorMessage));
				}
			}
			else
			{
				RitsuLibFramework.Logger.Info(logPrefix + " Wrote Harmony patch dump to: " + text, 1);
				if (showPrompt)
				{
					string format2 = ModSettingsLocalization.Get("ritsulib.harmonyDump.prompt.success", "Export complete: {0}");
					ShowPrompt(title, string.Format(format2, NormalizePathForDisplay(text)));
				}
			}
		}

		private static void ShowPrompt(string title, string message)
		{
			try
			{
				MainLoop mainLoop = Engine.GetMainLoop();
				SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
				if (((val != null) ? val.Root : null) != null)
				{
					string dismissText = ModSettingsLocalization.Get("clipboard.pasteErrorOk", "OK");
					ModSettingsUiFactory.ShowStyledNotice((Node)(object)val.Root, title, message, dismissText);
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[HarmonyDump][Prompt] Failed to show result prompt: " + ex.Message, 1);
			}
		}

		private static string NormalizePathForDisplay(string path)
		{
			if (string.IsNullOrWhiteSpace(path))
			{
				return path;
			}
			return path.Replace('\\', Path.DirectorySeparatorChar).Replace('/', Path.DirectorySeparatorChar);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Writes a UTF-8 text report of all methods patched through Harmony.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将所有通过 Harmony 补丁的方法写入 UTF-8 文本报告。
	///     </para>
	/// </summary>
	internal static class HarmonyPatchDumpWriter
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Resolves <c>user://</c> and <c>res://</c> paths through Godot and returns an absolute filesystem path.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过 Godot 解析 <c>user://</c> 和 <c>res://</c> 路径，并返回绝对文件系统路径。
		///     </para>
		/// </summary>
		internal static string? TryResolveFilesystemPath(string rawPath)
		{
			if (string.IsNullOrWhiteSpace(rawPath))
			{
				return null;
			}
			string text = rawPath.Trim();
			try
			{
				if (text.StartsWith("user://", StringComparison.OrdinalIgnoreCase) || text.StartsWith("res://", StringComparison.OrdinalIgnoreCase))
				{
					return ProjectSettings.GlobalizePath(text);
				}
				return Path.GetFullPath(text);
			}
			catch
			{
				return null;
			}
		}

		internal static bool TryWrite(string filesystemPath, out string? errorMessage)
		{
			errorMessage = null;
			try
			{
				string directoryName = Path.GetDirectoryName(filesystemPath);
				if (!string.IsNullOrEmpty(directoryName))
				{
					Directory.CreateDirectory(directoryName);
				}
				using FileStream stream = new FileStream(filesystemPath, FileMode.Create, FileAccess.Write, FileShare.Read);
				using StreamWriter streamWriter = new StreamWriter(stream, Encoding.UTF8);
				WriteReport(streamWriter);
				return true;
			}
			catch (Exception ex)
			{
				errorMessage = ex.Message;
				return false;
			}
		}

		private static void WriteReport(StreamWriter streamWriter)
		{
			streamWriter.WriteLine("=======================================================");
			streamWriter.WriteLine("===          Harmony Patch Dump Report             ===");
			streamWriter.WriteLine("=======================================================");
			streamWriter.WriteLine($"Generated at: {DateTime.Now:O}");
			streamWriter.WriteLine("User data dir: " + OS.GetUserDataDir());
			streamWriter.WriteLine("=======================================================");
			streamWriter.WriteLine();
			List<MethodBase> list = (from m in Harmony.GetAllPatchedMethods()
				orderby m.DeclaringType?.FullName ?? "Unknown", m.Name
				select m).ToList();
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			int num4 = 0;
			int num5 = 0;
			foreach (MethodBase item5 in list)
			{
				num++;
				(int prefixes, int postfixes, int transpilers, int finalizers) tuple = LogPatchedMethodInfo(item5, streamWriter);
				int item = tuple.prefixes;
				int item2 = tuple.postfixes;
				int item3 = tuple.transpilers;
				int item4 = tuple.finalizers;
				num2 += item;
				num3 += item2;
				num4 += item3;
				num5 += item4;
				streamWriter.WriteLine();
			}
			streamWriter.WriteLine("=======================================================");
			streamWriter.WriteLine("===                   Summary                      ===");
			streamWriter.WriteLine("=======================================================");
			streamWriter.WriteLine($"Total Patched Methods:  {num}");
			streamWriter.WriteLine($"  - Prefix patches:     {num2}");
			streamWriter.WriteLine($"  - Postfix patches:    {num3}");
			streamWriter.WriteLine($"  - Transpiler patches: {num4}");
			streamWriter.WriteLine($"  - Finalizer patches:  {num5}");
			streamWriter.WriteLine($"  - Total patches:      {num2 + num3 + num4 + num5}");
			streamWriter.WriteLine("=======================================================");
		}

		private static (int prefixes, int postfixes, int transpilers, int finalizers) LogPatchedMethodInfo(MethodBase methodBase, StreamWriter streamWriter)
		{
			Patches patchInfo = Harmony.GetPatchInfo(methodBase);
			if (patchInfo == null)
			{
				return (prefixes: 0, postfixes: 0, transpilers: 0, finalizers: 0);
			}
			string text = methodBase.DeclaringType?.FullName ?? "Unknown";
			string methodSignature = GetMethodSignature(methodBase);
			string text2 = ((methodBase is MethodInfo methodInfo) ? methodInfo.ReturnType.Name : "void");
			streamWriter.WriteLine("┌─ [" + text + "]");
			streamWriter.WriteLine("│  Method: " + text2 + " " + methodSignature);
			streamWriter.WriteLine("│");
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			int num4 = 0;
			if (patchInfo.Prefixes.Count > 0)
			{
				streamWriter.WriteLine($"│  ├─ Prefixes ({patchInfo.Prefixes.Count}):");
				foreach (Patch item in from p in patchInfo.Prefixes
					orderby p.priority, p.owner
					select p)
				{
					streamWriter.WriteLine("│  │  " + FormatPatchInfo(item));
					num++;
				}
			}
			if (patchInfo.Postfixes.Count > 0)
			{
				streamWriter.WriteLine($"│  ├─ Postfixes ({patchInfo.Postfixes.Count}):");
				foreach (Patch item2 in from p in patchInfo.Postfixes
					orderby p.priority, p.owner
					select p)
				{
					streamWriter.WriteLine("│  │  " + FormatPatchInfo(item2));
					num2++;
				}
			}
			if (patchInfo.Transpilers.Count > 0)
			{
				streamWriter.WriteLine($"│  ├─ Transpilers ({patchInfo.Transpilers.Count}):");
				foreach (Patch item3 in from p in patchInfo.Transpilers
					orderby p.priority, p.owner
					select p)
				{
					streamWriter.WriteLine("│  │  " + FormatPatchInfo(item3));
					num3++;
				}
			}
			if (patchInfo.Finalizers.Count > 0)
			{
				streamWriter.WriteLine($"│  └─ Finalizers ({patchInfo.Finalizers.Count}):");
				foreach (Patch item4 in from p in patchInfo.Finalizers
					orderby p.priority, p.owner
					select p)
				{
					streamWriter.WriteLine("│     " + FormatPatchInfo(item4));
					num4++;
				}
			}
			streamWriter.WriteLine("└─────────────────────────────────────────────────────────────────");
			return (prefixes: num, postfixes: num2, transpilers: num3, finalizers: num4);
		}

		private static string GetMethodSignature(MethodBase methodBase)
		{
			ParameterInfo[] parameters = methodBase.GetParameters();
			string text = string.Join(", ", parameters.Select((ParameterInfo p) => p.ParameterType.Name + " " + p.Name));
			return methodBase.Name + "(" + text + ")";
		}

		private static string FormatPatchInfo(Patch patch)
		{
			StringBuilder stringBuilder = new StringBuilder();
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder3 = stringBuilder2;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(16, 1, stringBuilder2);
			handler.AppendLiteral("├─ [Priority: ");
			handler.AppendFormatted(patch.priority);
			handler.AppendLiteral("] ");
			stringBuilder3.Append(ref handler);
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder4 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(3, 1, stringBuilder2);
			handler.AppendLiteral("[");
			handler.AppendFormatted(patch.owner);
			handler.AppendLiteral("] ");
			stringBuilder4.Append(ref handler);
			string value = patch.PatchMethod.DeclaringType?.FullName ?? "Unknown";
			string name = patch.PatchMethod.Name;
			stringBuilder2 = stringBuilder;
			StringBuilder stringBuilder5 = stringBuilder2;
			handler = new StringBuilder.AppendInterpolatedStringHandler(1, 2, stringBuilder2);
			handler.AppendFormatted(value);
			handler.AppendLiteral(".");
			handler.AppendFormatted(name);
			stringBuilder5.Append(ref handler);
			try
			{
				string fileName = Path.GetFileName(patch.PatchMethod.Module.FullyQualifiedName);
				if (!string.IsNullOrEmpty(fileName) && fileName != "<Unknown>")
				{
					stringBuilder2 = stringBuilder;
					StringBuilder stringBuilder6 = stringBuilder2;
					handler = new StringBuilder.AppendInterpolatedStringHandler(8, 1, stringBuilder2);
					handler.AppendLiteral(" (from ");
					handler.AppendFormatted(fileName);
					handler.AppendLiteral(")");
					stringBuilder6.Append(ref handler);
				}
			}
			catch
			{
			}
			return stringBuilder.ToString();
		}
	}
	internal static class ModDataCloudManualCoordinator
