		private static async Task RunPushWithProgressAsync(ModCloudSyncScope scope)
		{
			string title = ModSettingsLocalization.Get("ritsulib.modCloud.prompt.title", "Mod data (Steam Cloud)");
			if (Interlocked.CompareExchange(ref _manualCloudBusy, 1, 0) != 0)
			{
				ShowPrompt(title, ModSettingsLocalization.Get("ritsulib.modCloud.busy", "Another mod cloud upload or download is already running."));
				return;
			}
			ModDataCloudProgressOverlay overlay = null;
			try
			{
				SceneTree tree = ResolveSceneTree();
				if (tree == null)
				{
					ShowPrompt(title, ModSettingsLocalization.Get("ritsulib.modCloud.noSceneTree", "Cannot start: game scene tree is not available."));
					return;
				}
				CloudSaveStore cloud = ModDataCloudMirror.TryGetCloudSaveStore();
				if (cloud == null)
				{
					ShowPrompt(title, ModSettingsLocalization.Get("ritsulib.modCloud.unavailableStore", "Steam Cloud is not active for this session (same requirement as vanilla cloud saves)."));
					return;
				}
				try
				{
					ProfileManager.Instance.RefreshCurrentProfile();
				}
				catch
				{
				}
				List<string> paths = await ModDataCloudMirror.CollectDistinctLocalModDataPathsAsync(tree, scope);
				string title2 = ModSettingsLocalization.Get("ritsulib.modCloud.progress.title.push", "Uploading to Steam Cloud…");
				Node root = (Node)((NGame.Instance != null) ? ((object)NGame.Instance) : ((object)tree.Root));
				overlay = ModDataCloudProgressOverlay.Attach(root, Math.Max(1, paths.Count), title2);
				overlay.SetProgress(0, Math.Max(1, paths.Count), (paths.Count > 0) ? paths[0] : null);
				await RitsuGodotAwaitSafety.AwaitProcessFrameAsync(tree, (GodotObject?)(object)overlay);
				(int, int, int) obj2 = await ModDataCloudMirror.PushPathsAsync(cloud, paths, tree, delegate(int done, int total, string? cur)
				{
					if (GodotObject.IsInstanceValid((GodotObject)(object)overlay))
					{
						overlay.SetProgress(done, total, cur);
					}
				});
				int item = obj2.Item1;
				int item2 = obj2.Item2;
				int item3 = obj2.Item3;
				string message = string.Format(ModSettingsLocalization.Get("ritsulib.modCloud.pushSummary", "Queued for upload: {0}. Skipped (no local file): {1}. Failed: {2}."), item, item2, item3);
				RitsuLibFramework.Logger.Info($"[ModCloud][ManualPush] queued={item} skipped={item2} failed={item3} scope={scope}", 1);
				ShowPrompt(title, message);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[ModCloud][ManualPush] " + ex.Message, 1);
				ShowPrompt(title, string.Format(ModSettingsLocalization.Get("ritsulib.modCloud.progressFailed", "Operation failed: {0}"), ex.Message));
			}
			finally
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)overlay))
				{
					overlay.Detach();
				}
				Interlocked.Exchange(ref _manualCloudBusy, 0);
			}
		}

		private static async Task RunPullWithProgressAsync(ModCloudSyncScope scope)
		{
			string title = ModSettingsLocalization.Get("ritsulib.modCloud.prompt.title", "Mod data (Steam Cloud)");
			if (Interlocked.CompareExchange(ref _manualCloudBusy, 1, 0) != 0)
			{
				ShowPrompt(title, ModSettingsLocalization.Get("ritsulib.modCloud.busy", "Another mod cloud upload or download is already running."));
				return;
			}
			ModDataCloudProgressOverlay overlay = null;
			try
			{
				SceneTree tree = ResolveSceneTree();
				if (tree == null)
				{
					ShowPrompt(title, ModSettingsLocalization.Get("ritsulib.modCloud.noSceneTree", "Cannot start: game scene tree is not available."));
					return;
				}
				CloudSaveStore cloud = ModDataCloudMirror.TryGetCloudSaveStore();
				if (cloud == null)
				{
					ShowPrompt(title, ModSettingsLocalization.Get("ritsulib.modCloud.unavailableStore", "Steam Cloud is not active for this session (same requirement as vanilla cloud saves)."));
					return;
				}
				try
				{
					ProfileManager.Instance.RefreshCurrentProfile();
				}
				catch
				{
				}
				List<string> paths = await ModDataCloudMirror.CollectDistinctRemoteModDataPathsForPullAsync(tree, scope);
				string title2 = ModSettingsLocalization.Get("ritsulib.modCloud.progress.title.pull", "Downloading from Steam Cloud…");
				Node root = (Node)((NGame.Instance != null) ? ((object)NGame.Instance) : ((object)tree.Root));
				overlay = ModDataCloudProgressOverlay.Attach(root, Math.Max(1, paths.Count), title2);
				overlay.SetProgress(0, Math.Max(1, paths.Count), (paths.Count > 0) ? paths[0] : null);
				await RitsuGodotAwaitSafety.AwaitProcessFrameAsync(tree, (GodotObject?)(object)overlay);
				(int, int) obj2 = await ModDataCloudMirror.PullPathsAsync(cloud, paths, tree, delegate(int done, int total, string? cur)
				{
					if (GodotObject.IsInstanceValid((GodotObject)(object)overlay))
					{
						overlay.SetProgress(done, total, cur);
					}
				});
				int item = obj2.Item1;
				int item2 = obj2.Item2;
				string message = ((item2 == 0) ? string.Format(ModSettingsLocalization.Get("ritsulib.modCloud.pullDone", "Downloaded {0} file(s) from Steam Cloud. Mod data was reloaded from disk."), item) : string.Format(ModSettingsLocalization.Get("ritsulib.modCloud.pullPartial", "Downloaded {0} file(s); {1} failed. See game log for details."), item, item2));
				RitsuLibFramework.Logger.Info($"[ModCloud][ManualPull] downloaded={item} failed={item2}", 1);
				ShowPrompt(title, message);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[ModCloud][ManualPull] " + ex.Message, 1);
				ShowPrompt(title, string.Format(ModSettingsLocalization.Get("ritsulib.modCloud.progressFailed", "Operation failed: {0}"), ex.Message));
			}
			finally
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)overlay))
				{
					overlay.Detach();
				}
				Interlocked.Exchange(ref _manualCloudBusy, 0);
			}
		}

		private static string GetScopeLabel(ModCloudSyncScope scope)
		{
			return scope switch
			{
				ModCloudSyncScope.GlobalOnly => ModSettingsLocalization.Get("ritsulib.modCloud.scope.name.global", "Global only"), 
				ModCloudSyncScope.ProfileOnly => ModSettingsLocalization.Get("ritsulib.modCloud.scope.name.profile", "This profile only"), 
				_ => ModSettingsLocalization.Get("ritsulib.modCloud.scope.name.all", "Global and this profile"), 
			};
		}

		private static SceneTree? ResolveSceneTree()
		{
			if (NGame.Instance != null)
			{
				return ((Node)NGame.Instance).GetTree();
			}
			MainLoop mainLoop = Engine.GetMainLoop();
			return (SceneTree?)(object)((mainLoop is SceneTree) ? mainLoop : null);
		}

		private static void ShowPrompt(string title, string message)
		{
			try
			{
				MainLoop mainLoop = Engine.GetMainLoop();
				SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
				if (((val != null) ? val.Root : null) != null)
				{
					string dismissText = ModSettingsLocalization.Get("clipboard.pasteErrorOk", "OK");
					ModSettingsUiFactory.ShowStyledNotice((Node)(object)val.Root, title, message, dismissText);
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[ModCloud][Prompt] Failed to show prompt: " + ex.Message, 1);
			}
		}
	}
