				_countLabel.Text = string.Format(format, Math.Min(completedSteps, num), num);
			}
			if (_pathLabel != null)
			{
				string text = (string.IsNullOrWhiteSpace(currentRelativePath) ? "…" : currentRelativePath);
				_pathLabel.Text = text;
			}
		}

