	internal static class RegistrationConflictDetector
	{
		private readonly record struct BaseLibCustomEnumEntry(Type EnumType, int Value, string Prefix, string Name)
		{
			public string DisplayName => Prefix + Name;
		}

		private readonly record struct RitsuDynamicEnumEntry(Type EnumType, int Value, string Id, string? ModId, bool Registered)
		{
			public string DisplayName
			{
				get
				{
					if (!Registered || string.IsNullOrWhiteSpace(ModId))
					{
						return Id + " (minted lookup)";
					}
					return Id + " (mod " + ModId + ")";
				}
			}
		}

		private readonly record struct DynamicEnumValueCollision(BaseLibCustomEnumEntry BaseLibEntry, RitsuDynamicEnumEntry RitsuEntry);

		private static readonly Lock IndexGate = new Lock();

		private static Dictionary<ModelId, List<Type>>? _gameModelIdIndex;

		private static bool _baseLibDynamicEnumCollisionCheckCompleted;

		private static Dictionary<ModelId, List<Type>> GetGameModelIdIndex()
		{
			using (IndexGate.EnterScope())
			{
				if (_gameModelIdIndex != null)
				{
					return _gameModelIdIndex;
				}
				Dictionary<ModelId, List<Type>> dictionary = new Dictionary<ModelId, List<Type>>();
				foreach (Type subtype in ReflectionHelper.GetSubtypes<AbstractModel>())
				{
					ModelId id = ModelDb.GetId(subtype);
					if (!dictionary.TryGetValue(id, out var value))
					{
						value = (dictionary[id] = new List<Type>());
					}
					value.Add(subtype);
				}
				_gameModelIdIndex = dictionary;
				return dictionary;
			}
		}

		internal static void InvalidateModelIdIndex()
		{
			using (IndexGate.EnterScope())
			{
				_gameModelIdIndex = null;
			}
		}

		internal static void UpdateModelIdIndex(Type type, ModelId previousId, ModelId currentId)
		{
			if (previousId == currentId)
			{
				return;
			}
			using (IndexGate.EnterScope())
			{
				if (_gameModelIdIndex == null)
				{
					return;
				}
				if (_gameModelIdIndex.TryGetValue(previousId, out List<Type> value))
				{
					value.Remove(type);
					if (value.Count == 0)
					{
						_gameModelIdIndex.Remove(previousId);
					}
				}
				if (!_gameModelIdIndex.TryGetValue(currentId, out List<Type> value2))
				{
					value2 = new List<Type>();
					_gameModelIdIndex[currentId] = value2;
				}
				if (!value2.Contains(type))
				{
					value2.Add(type);
				}
			}
		}

		internal static void ThrowIfModelIdConflicts(Type candidateType)
		{
			ArgumentNullException.ThrowIfNull(candidateType, "candidateType");
			ModelId id = ModelDb.GetId(candidateType);
			if (!GetGameModelIdIndex().TryGetValue(id, out List<Type> value))
			{
				return;
			}
			Type[] array = value.Where((Type type) => type != candidateType).ToArray();
			if (array.Length == 0)
			{
				return;
			}
			throw new InvalidOperationException($"ModelId collision detected for '{id}'. Type '{candidateType.FullName}' conflicts with: " + string.Join(", ", array.Select((Type type) => type.FullName)) + ". RitsuLib now formats registered model ids as '<modid>_<category>_<typename>', so a remaining collision usually means two registered models in the same mod/category still share the same CLR type name.");
		}

		internal static void ValidateAndLogModelIdCollisions()
		{
			InvalidateModelIdIndex();
			KeyValuePair<ModelId, List<Type>>[] array = (from pair in GetGameModelIdIndex()
				where pair.Value.Count > 1
				select pair).ToArray();
			KeyValuePair<ModelId, List<Type>>[] array2 = array;
			for (int num = 0; num < array2.Length; num++)
			{
				KeyValuePair<ModelId, List<Type>> keyValuePair = array2[num];
				RitsuLibFramework.Logger.ErrorNoTrace($"[Content] ModelId collision detected for '{keyValuePair.Key}': " + string.Join(", ", keyValuePair.Value.Select((Type type) => type.FullName)));
			}
			if (array.Length != 0)
			{
				RitsuLibFramework.Logger.ErrorNoTrace("[Content] Duplicate patched ModelIds are unsafe. RitsuLib formats registered model ids as '<modid>_<category>_<typename>', so this usually indicates two registered models still share the same mod/category/type-name combination.");
			}
			InvalidateModelIdIndex();
		}

		internal static void ValidateAndLogBaseLibDynamicEnumValueCollisions()
		{
			if (_baseLibDynamicEnumCollisionCheckCompleted)
			{
				return;
			}
			_baseLibDynamicEnumCollisionCheckCompleted = true;
			BaseLibCustomEnumEntry[] baseLibCustomEnumEntries = GetBaseLibCustomEnumEntries();
			if (baseLibCustomEnumEntries.Length == 0)
			{
				return;
			}
			Dictionary<(Type EnumType, int Value), RitsuDynamicEnumEntry[]> ritsuEntries = (from entry in GetRitsuDynamicEnumEntries()
				group entry by (EnumType: entry.EnumType, Value: entry.Value)).ToDictionary((IGrouping<(Type EnumType, int Value), RitsuDynamicEnumEntry> group) => group.Key, (IGrouping<(Type EnumType, int Value), RitsuDynamicEnumEntry> group) => group.OrderBy<RitsuDynamicEnumEntry, string>((RitsuDynamicEnumEntry entry) => entry.Id, StringComparer.Ordinal).ToArray());
			DynamicEnumValueCollision[] array = baseLibCustomEnumEntries.SelectMany((BaseLibCustomEnumEntry entry) => (!ritsuEntries.TryGetValue((entry.EnumType, entry.Value), out var value)) ? Array.Empty<DynamicEnumValueCollision>() : value.Select((RitsuDynamicEnumEntry ritsuEntry) => new DynamicEnumValueCollision(entry, ritsuEntry))).OrderBy<DynamicEnumValueCollision, string>((DynamicEnumValueCollision collision) => collision.BaseLibEntry.EnumType.FullName, StringComparer.Ordinal).ThenBy((DynamicEnumValueCollision collision) => collision.BaseLibEntry.Value)
				.ThenBy<DynamicEnumValueCollision, string>((DynamicEnumValueCollision collision) => collision.RitsuEntry.Id, StringComparer.Ordinal)
				.ToArray();
			DynamicEnumValueCollision[] array2 = array;
			for (int num = 0; num < array2.Length; num++)
			{
				DynamicEnumValueCollision dynamicEnumValueCollision = array2[num];
				RitsuLibFramework.Logger.ErrorNoTrace("[DynamicEnum] BaseLib/RitsuLib value collision detected: " + $"{dynamicEnumValueCollision.BaseLibEntry.EnumType.FullName} value 0x{dynamicEnumValueCollision.BaseLibEntry.Value:X8} " + "is used by BaseLib '" + dynamicEnumValueCollision.BaseLibEntry.DisplayName + "' and RitsuLib '" + dynamicEnumValueCollision.RitsuEntry.DisplayName + "'.");
			}
			if (array.Length != 0)
			{
				RitsuLibFramework.Logger.ErrorNoTrace("[DynamicEnum] BaseLib/RitsuLib dynamic enum value collisions are unsafe. RitsuLib does not remap minted values automatically; change the colliding RitsuLib id or the BaseLib CustomEnum field/name source.");
			}
		}

		internal static void ThrowIfEpochIdConflicts(string epochId, Type candidateType, IEnumerable<Type> knownEpochTypes)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(epochId, "epochId");
			ArgumentNullException.ThrowIfNull(candidateType, "candidateType");
			ArgumentNullException.ThrowIfNull(knownEpochTypes, "knownEpochTypes");
			Type[] array = (from type in knownEpochTypes
				where type != candidateType
				where CreateEpoch(type).Id.Equals(epochId, StringComparison.Ordinal)
				select type).ToArray();
			if (array.Length == 0)
			{
				return;
			}
			throw new InvalidOperationException($"Epoch id collision detected for '{epochId}'. Type '{candidateType.FullName}' conflicts with: " + string.Join(", ", array.Select((Type type) => type.FullName)));
		}

		internal static void ThrowIfStoryIdConflicts(string storyId, Type candidateType, IEnumerable<Type> knownStoryTypes)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(storyId, "storyId");
			ArgumentNullException.ThrowIfNull(candidateType, "candidateType");
			ArgumentNullException.ThrowIfNull(knownStoryTypes, "knownStoryTypes");
			Type[] array = (from type in knownStoryTypes
				where type != candidateType
				where GetStoryId(type).Equals(storyId, StringComparison.Ordinal)
				select type).ToArray();
			if (array.Length == 0)
			{
				return;
			}
			throw new InvalidOperationException($"Story id collision detected for '{storyId}'. Type '{candidateType.FullName}' conflicts with: " + string.Join(", ", array.Select((Type type) => type.FullName)));
		}

		private static EpochModel CreateEpoch(Type type)
		{
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_000c: Expected O, but got Unknown
			return (EpochModel)Activator.CreateInstance(type);
		}

		private static string GetStoryId(Type type)
		{
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_000c: Expected O, but got Unknown
			StoryModel obj = (StoryModel)Activator.CreateInstance(type);
			return (string)(type.GetProperty("Id", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(obj) ?? throw new InvalidOperationException("Story type '" + type.FullName + "' does not expose an Id property."));
		}

		private static BaseLibCustomEnumEntry[] GetBaseLibCustomEnumEntries()
		{
			if (!((ResolveLoadedType("BaseLib.Patches.Content.CustomEnums")?.GetField("GeneratedCustomEnumEntries", BindingFlags.Static | BindingFlags.Public))?.GetValue(null) is IDictionary dictionary))
			{
				return Array.Empty<BaseLibCustomEnumEntry>();
			}
			List<BaseLibCustomEnumEntry> list = new List<BaseLibCustomEnumEntry>();
			foreach (DictionaryEntry item in dictionary)
			{
				if (!(item.Key is Type enumType) || !(item.Value is IDictionary dictionary2))
				{
					continue;
				}
				foreach (DictionaryEntry item2 in dictionary2)
				{
					if (TryConvertToInt32(item2.Key, out var value))
					{
						var (prefix, name) = ReadBaseLibGeneratedName(item2.Value);
						list.Add(new BaseLibCustomEnumEntry(enumType, value, prefix, name));
					}
				}
			}
			return list.ToArray();
		}

		private static IEnumerable<RitsuDynamicEnumEntry> GetRitsuDynamicEnumEntries()
		{
			foreach (RitsuDynamicEnumEntry ritsuDynamicEnumEntry in GetRitsuDynamicEnumEntries<CardKeyword>())
			{
				yield return ritsuDynamicEnumEntry;
			}
			foreach (RitsuDynamicEnumEntry ritsuDynamicEnumEntry2 in GetRitsuDynamicEnumEntries<PileType>())
			{
				yield return ritsuDynamicEnumEntry2;
			}
			foreach (RitsuDynamicEnumEntry ritsuDynamicEnumEntry3 in GetRitsuDynamicEnumEntries<CardTag>())
			{
				yield return ritsuDynamicEnumEntry3;
			}
			foreach (RitsuDynamicEnumEntry ritsuDynamicEnumEntry4 in GetRitsuDynamicEnumEntries<RewardType>())
			{
				yield return ritsuDynamicEnumEntry4;
			}
			foreach (RitsuDynamicEnumEntry ritsuDynamicEnumEntry5 in GetRitsuDynamicEnumEntries<TargetType>())
			{
				yield return ritsuDynamicEnumEntry5;
			}
		}

		private static IEnumerable<RitsuDynamicEnumEntry> GetRitsuDynamicEnumEntries<TEnum>() where TEnum : struct, Enum
		{
			Dictionary<int, RitsuDynamicEnumEntry> dictionary = new Dictionary<int, RitsuDynamicEnumEntry>();
			DynamicEnumValueDefinition<TEnum>[] definitionsSnapshot = DynamicEnumValueRegistry<TEnum>.GetDefinitionsSnapshot();
			foreach (DynamicEnumValueDefinition<TEnum> dynamicEnumValueDefinition in definitionsSnapshot)
			{
				int num = Convert.ToInt32(dynamicEnumValueDefinition.Value);
				dictionary[num] = new RitsuDynamicEnumEntry(typeof(TEnum), num, dynamicEnumValueDefinition.Id, dynamicEnumValueDefinition.ModId, Registered: true);
			}
			(string, TEnum)[] mintedValuesSnapshot = DynamicEnumValueRegistry<TEnum>.GetMintedValuesSnapshot();
			for (int i = 0; i < mintedValuesSnapshot.Length; i++)
			{
				(string, TEnum) tuple = mintedValuesSnapshot[i];
				string item = tuple.Item1;
				int num2 = Convert.ToInt32(tuple.Item2);
				dictionary.TryAdd(num2, new RitsuDynamicEnumEntry(typeof(TEnum), num2, item, null, Registered: false));
			}
			return dictionary.Values;
		}

		private static Type? ResolveLoadedType(string fullTypeName)
		{
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly assembly in assemblies)
			{
				Type type = null;
				try
				{
					type = assembly.GetType(fullTypeName, throwOnError: false);
				}
				catch
				{
				}
				if (type != null)
				{
					return type;
				}
			}
			return null;
		}

		private static (string Prefix, string Name) ReadBaseLibGeneratedName(object? generatedName)
		{
			if (generatedName == null)
			{
				return (Prefix: "", Name: "<unknown>");
			}
			Type type = generatedName.GetType();
			string item = (type.GetField("Item1")?.GetValue(generatedName) as string) ?? "";
			string item2 = (type.GetField("Item2")?.GetValue(generatedName) as string) ?? "<unknown>";
			return (Prefix: item, Name: item2);
		}

		private static bool TryConvertToInt32(object key, out int value)
		{
			try
			{
				value = Convert.ToInt32(key);
				return true;
			}
			catch
			{
				value = 0;
				return false;
			}
		}
	}
	internal static class RegistrationFreezeDiagnostics
	{
		private sealed record RegistrationFailure(string System, string? ModId, string Description, string ExceptionType, string Message);

		private static readonly Lock Sync = new Lock();

		private static readonly List<RegistrationFailure> Failures = new List<RegistrationFailure>();

		private static bool _reportedFailures;

		internal static void RecordFailure(string system, string? modId, string description, Exception exception)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(system, "system");
			ArgumentException.ThrowIfNullOrWhiteSpace(description, "description");
			ArgumentNullException.ThrowIfNull(exception, "exception");
			using (Sync.EnterScope())
			{
				Failures.Add(new RegistrationFailure(system, modId, description, exception.GetType().Name, exception.Message));
			}
		}

		internal static void WarnRecordedFailures(string reason)
		{
			RegistrationFailure[] array;
			using (Sync.EnterScope())
			{
				if (_reportedFailures)
				{
					return;
				}
				_reportedFailures = true;
				array = Failures.ToArray();
			}
			RegistrationFailure[] array2 = array;
			foreach (RegistrationFailure registrationFailure in array2)
			{
				RitsuLibFramework.Logger.Warn($"[{registrationFailure.System}] Registration failed before final freeze ({reason}){FormatMod(registrationFailure.ModId)}: {registrationFailure.Description} ({registrationFailure.ExceptionType}: {registrationFailure.Message})", 1);
			}
		}

		internal static void WarnMissingModelType(string system, string? modId, string description, Type modelType, Type expectedBaseType)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(system, "system");
			ArgumentException.ThrowIfNullOrWhiteSpace(description, "description");
			ArgumentNullException.ThrowIfNull(modelType, "modelType");
			ArgumentNullException.ThrowIfNull(expectedBaseType, "expectedBaseType");
			if (!TryResolveModelType(modelType, expectedBaseType, out string note))
			{
				RitsuLibFramework.Logger.Warn($"[{system}] Registered reference was not resolved in ModelDb after final freeze{FormatMod(modId)}: {description}; type={modelType.FullName}; {note}", 1);
			}
		}

		internal static void WarnMissingModelId(string system, string? modId, string description, ModelId modelId, Type expectedBaseType)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(system, "system");
			ArgumentException.ThrowIfNullOrWhiteSpace(description, "description");
			ArgumentNullException.ThrowIfNull(expectedBaseType, "expectedBaseType");
			if (!TryResolveModelId(modelId, expectedBaseType, out string note))
			{
				RitsuLibFramework.Logger.Warn($"[{system}] Registered ModelDb id reference was not resolved after final freeze{FormatMod(modId)}: {description}; id={modelId}; {note}", 1);
			}
		}

		private static bool TryResolveModelType(Type modelType, Type expectedBaseType, out string note)
		{
			ModelId id;
			try
			{
				id = ModelDb.GetId(modelType);
			}
			catch (Exception ex)
			{
				note = "ModelDb.GetId failed: " + ex.GetType().Name + ": " + ex.Message;
				return false;
			}
			if (!TryResolveModelId(id, expectedBaseType, out note, out AbstractModel resolved))
			{
				return false;
			}
			if (resolved == null || ((object)resolved).GetType() == modelType)
			{
				return true;
			}
			note = "id resolves to '" + ((object)resolved).GetType().FullName + "', not the registered type";
			return false;
		}

		private static bool TryResolveModelId(ModelId modelId, Type expectedBaseType, out string note)
		{
			AbstractModel resolved;
			return TryResolveModelId(modelId, expectedBaseType, out note, out resolved);
		}

		private static bool TryResolveModelId(ModelId modelId, Type expectedBaseType, out string note, out AbstractModel? resolved)
		{
			try
			{
				resolved = ModelDb.GetByIdOrNull<AbstractModel>(modelId);
			}
			catch (Exception ex)
			{
				resolved = null;
				note = "ModelDb lookup failed: " + ex.GetType().Name + ": " + ex.Message;
				return false;
			}
			if (resolved == null)
			{
				note = "ModelDb returned no model for this id";
				return false;
			}
			if (expectedBaseType.IsInstanceOfType(resolved))
			{
				note = string.Empty;
				return true;
			}
			note = $"id resolves to '{((object)resolved).GetType().FullName}', not a '{expectedBaseType.FullName}'";
			return false;
		}

		private static string FormatMod(string? modId)
		{
			if (!string.IsNullOrWhiteSpace(modId))
			{
				return " (mod '" + modId + "')";
			}
			return "";
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Accumulates wall-clock durations for RitsuLib's own startup phases, including bootstrap work, patch
	///         application, and internal lifecycle hooks, and writes consolidated audit reports to the log. Time spent
	///         between these phases in the engine or other mods is excluded.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         累计 RitsuLib 自身各启动阶段的墙钟耗时，包括引导初始化、补丁应用和内部生命周期钩子，并向日志写入
	///         汇总审计报告。各阶段之间由引擎或其他模组消耗的时间不计入其中。
	///     </para>
	/// </summary>
	internal static class RitsuLibStartupAudit
	{
		private sealed class MeasureScope(string phase, MeasureScope? parent)
		{
			internal string Phase { get; } = phase;

			internal MeasureScope? Parent { get; } = parent;

			internal double ChildMilliseconds { get; private set; }

			internal void AddChild(double milliseconds)
			{
				ChildMilliseconds += milliseconds;
			}
		}

		private readonly record struct PhaseTiming(string Phase, double InclusiveMilliseconds, double ExclusiveMilliseconds);

		private static readonly Lock Gate = new Lock();

		private static readonly List<PhaseTiming> Phases = new List<PhaseTiming>();

		private static int _reportedCount;

		[ThreadStatic]
		private static MeasureScope? _currentScope;

		/// <summary>
		///     <para xml:lang="en">
		///         Measures <paramref name="action" /> and records its duration under <paramref name="phase" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         测量 <paramref name="action" /> 的耗时，并以 <paramref name="phase" /> 作为阶段名称记录。
		///     </para>
		/// </summary>
		internal static void Measure(string phase, Action action)
		{
			MeasureScope scope = PushScope(phase);
			Stopwatch stopwatch = Stopwatch.StartNew();
			try
			{
				action();
			}
			finally
			{
				stopwatch.Stop();
				PopScope(scope, stopwatch.Elapsed.TotalMilliseconds);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Measures <paramref name="func" />, records its duration under <paramref name="phase" />, and returns
		///         the function result.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         测量 <paramref name="func" /> 的耗时并以 <paramref name="phase" /> 作为阶段名称记录，然后返回函数
		///         结果。
		///     </para>
		/// </summary>
		internal static T Measure<T>(string phase, Func<T> func)
		{
			MeasureScope scope = PushScope(phase);
			Stopwatch stopwatch = Stopwatch.StartNew();
			try
			{
				return func();
			}
			finally
			{
				stopwatch.Stop();
				PopScope(scope, stopwatch.Elapsed.TotalMilliseconds);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Records a previously measured phase duration.</para>
		///     <para xml:lang="zh-CN">记录一个已测量的阶段耗时。</para>
		/// </summary>
		internal static void Record(string phase, double milliseconds)
		{
			_currentScope?.AddChild(milliseconds);
			using (Gate.EnterScope())
			{
				Phases.Add(new PhaseTiming(phase, milliseconds, milliseconds));
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Logs all RitsuLib self-time phases recorded so far as one consolidated block with an exclusive-time
		///         total.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将截至当前记录的所有 RitsuLib 自身耗时阶段作为一个汇总块写入日志，并附带独占耗时总计。
		///     </para>
		/// </summary>
		internal static void LogReport(string title)
		{
			using (Gate.EnterScope())
			{
				if (Phases.Count <= _reportedCount)
				{
					return;
				}
				double value = Phases.Sum((PhaseTiming entry) => entry.ExclusiveMilliseconds);
				StringBuilder stringBuilder = new StringBuilder().AppendLine();
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(32, 1, stringBuilder);
				handler.AppendLiteral("=== RitsuLib Startup Audit: ");
				handler.AppendFormatted(title);
				handler.AppendLiteral(" ===");
				StringBuilder stringBuilder3 = stringBuilder2.AppendLine(ref handler);
				foreach (PhaseTiming phase in Phases)
				{
					stringBuilder = stringBuilder3;
					StringBuilder stringBuilder4 = stringBuilder;
					handler = new StringBuilder.AppendInterpolatedStringHandler(7, 2, stringBuilder);
					handler.AppendLiteral("  ");
					handler.AppendFormatted(phase.Phase);
					handler.AppendLiteral(": ");
					handler.AppendFormatted(phase.ExclusiveMilliseconds, "F1");
					handler.AppendLiteral(" ms");
					stringBuilder4.Append(ref handler);
					if (Math.Abs(phase.InclusiveMilliseconds - phase.ExclusiveMilliseconds) >= 0.05)
					{
						stringBuilder = stringBuilder3;
						StringBuilder stringBuilder5 = stringBuilder;
						handler = new StringBuilder.AppendInterpolatedStringHandler(16, 1, stringBuilder);
						handler.AppendLiteral(" (inclusive ");
						handler.AppendFormatted(phase.InclusiveMilliseconds, "F1");
						handler.AppendLiteral(" ms)");
						stringBuilder5.Append(ref handler);
					}
					stringBuilder3.AppendLine();
				}
				stringBuilder = stringBuilder3.AppendLine("  ---");
				StringBuilder stringBuilder6 = stringBuilder;
				handler = new StringBuilder.AppendInterpolatedStringHandler(41, 1, stringBuilder);
				handler.AppendLiteral("  RitsuLib exclusive self-time total: ");
				handler.AppendFormatted(value, "F1");
				handler.AppendLiteral(" ms");
				stringBuilder6.Append(ref handler);
				_reportedCount = Phases.Count;
				RitsuLibFramework.Logger.Info(stringBuilder3.ToString(), 1);
			}
		}

		private static MeasureScope PushScope(string phase)
		{
			return _currentScope = new MeasureScope(phase, _currentScope);
		}

		private static void PopScope(MeasureScope scope, double inclusiveMilliseconds)
		{
			_currentScope = scope.Parent;
			scope.Parent?.AddChild(inclusiveMilliseconds);
			double exclusiveMilliseconds = Math.Max(0.0, inclusiveMilliseconds - scope.ChildMilliseconds);
			using (Gate.EnterScope())
			{
				Phases.Add(new PhaseTiming(scope.Phase, inclusiveMilliseconds, exclusiveMilliseconds));
			}
		}
	}
