				if (config == null)
				{
					return "<none>";
				}
				Type type = config.GetType();
				global::<>y__InlineArray4<string> buffer = default(global::<>y__InlineArray4<string>);
				buffer[0] = ReadConfigValue(type, config, "Id");
				buffer[1] = ReadConfigValue(type, config, "Priority");
				buffer[2] = ReadConfigValue(type, config, "Before");
				buffer[3] = ReadConfigValue(type, config, "After");
				return string.Join(", ", (ReadOnlySpan<string?>)buffer);
			}

			private static string ReadConfigValue(Type type, object config, string propertyName)
			{
				PropertyInfo property = type.GetProperty(propertyName, BindingFlags.Instance | BindingFlags.Public);
				if (property == null)
				{
					return propertyName + "=<unknown>";
				}
				try
				{
					object value = property.GetValue(config);
					return propertyName + "=" + FormatConfigValue(value);
				}
				catch
				{
					return propertyName + "=<unreadable>";
				}
			}

			private static string FormatConfigValue(object? value)
			{
				if (value == null)
				{
					return "<null>";
				}
				string text;
				if (!(value is IEnumerable enumerable) || enumerable is string)
				{
					text = value.ToString();
					if (text == null)
					{
						return "<unknown>";
					}
				}
				else
				{
					text = "[" + string.Join(", ", from object item in enumerable
						select item?.ToString()) + "]";
				}
				return text;
			}
		}

		private sealed record RuntimeDetourRiskMod(Sts2LoadedModAssemblyEntry Mod, IReadOnlyList<string> ReferencingAssemblies);

		private sealed record HarmonyPatchedMethodGroup(MethodBase OriginalMethod, IReadOnlyList<string> Patches);

		private sealed record RuntimeDetourHook(string Kind, string Target, string Config);

		private sealed record RuntimeDetourScanResult(IReadOnlyList<RuntimeDetourHarmonyConflict> Conflicts, int FailedQueryCount);

		private sealed record RuntimeDetourHarmonyConflict(HarmonyPatchedMethodGroup HarmonyPatchGroup, IReadOnlyList<RuntimeDetourHook> Hooks);

		private const string Prefix = "[RuntimeDetourCompat]";

		private static readonly string[] InfrastructureAssemblyNamePrefixes = new string[7] { "0Harmony", "HarmonyLib", "Mono.Cecil", "MonoMod.", "System.", "Microsoft.", "netstandard" };

		private static readonly Lock InitializeGate = new Lock();

		private static IDisposable? _lifecycleSubscription;

		private static int _scanIssuedForSession;

		internal static void Initialize()
		{
			using (InitializeGate.EnterScope())
			{
				if (_lifecycleSubscription == null)
				{
					_lifecycleSubscription = RitsuLibFramework.SubscribeLifecycleOnce<DeferredInitializationCompletedEvent>(delegate
					{
						RitsuLibStartupAudit.Measure("runtimeDetourCompatibilityScan", ScanAndWarn);
					});
				}
			}
		}

		private static void ScanAndWarn()
		{
			if (Interlocked.CompareExchange(ref _scanIssuedForSession, 1, 0) != 0)
			{
				return;
			}
			IReadOnlyList<RuntimeDetourRiskMod> readOnlyList = FindRuntimeDetourRiskMods();
			if (readOnlyList.Count == 0)
			{
				return;
			}
			RitsuLibFramework.Logger.Info(BuildRuntimeDetourDependencyMessage(readOnlyList), 1);
			RuntimeDetourReflectionBridge runtimeDetourReflectionBridge = RuntimeDetourReflectionBridge.TryCreate();
			if (runtimeDetourReflectionBridge == null)
			{
				RitsuLibFramework.Logger.Warn("[RuntimeDetourCompat] RuntimeDetour dependency detected, but its runtime query API is not available. RuntimeDetour/Harmony overlap cannot be checked.", 1);
				ShowCompatibilityToast(readOnlyList, Array.Empty<RuntimeDetourHarmonyConflict>(), queryIncomplete: true);
				return;
			}
			var (readOnlyList3, num2) = FindHarmonyRuntimeDetourConflicts(runtimeDetourReflectionBridge);
			if (readOnlyList3.Count == 0)
			{
				if (num2 > 0)
				{
					RitsuLibFramework.Logger.Warn($"{"[RuntimeDetourCompat]"} RuntimeDetour hook lookup failed for {num2} Harmony-patched method(s), so the overlap check is incomplete.", 1);
					ShowCompatibilityToast(readOnlyList, Array.Empty<RuntimeDetourHarmonyConflict>(), queryIncomplete: true);
				}
				else
				{
					RitsuLibFramework.Logger.Info("[RuntimeDetourCompat] RuntimeDetour dependency detected, but no RuntimeDetour hook currently overlaps a Harmony-patched method.", 1);
				}
				return;
			}
			RitsuLibFramework.Logger.Warn(BuildConflictWarning(readOnlyList3), 1);
			if (num2 > 0)
			{
				RitsuLibFramework.Logger.Warn($"{"[RuntimeDetourCompat]"} RuntimeDetour hook lookup also failed for {num2} Harmony-patched method(s); additional overlaps may exist.", 1);
			}
			ShowCompatibilityToast(readOnlyList, readOnlyList3, num2 > 0);
		}

		private static IReadOnlyList<RuntimeDetourRiskMod> FindRuntimeDetourRiskMods()
		{
			IReadOnlyList<Sts2LoadedModAssemblyEntry> source;
			try
			{
				source = Sts2ModManagerCompat.BuildLoadedModAssemblyEntries();
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[RuntimeDetourCompat] Failed to enumerate loaded mod assemblies: " + ex.Message, 1);
				return Array.Empty<RuntimeDetourRiskMod>();
			}
			List<RuntimeDetourRiskMod> list = new List<RuntimeDetourRiskMod>();
			list.AddRange(from risk in source.Select(TryBuildRiskMod)
				where risk != null
				select (risk));
			return new <>z__ReadOnlyList<RuntimeDetourRiskMod>(list);
		}

		private static RuntimeDetourRiskMod? TryBuildRiskMod(Sts2LoadedModAssemblyEntry mod)
		{
			string[] array = (from assembly in EnumerateModOwnedAssemblies(mod).Where(ReferencesRuntimeDetour)
				select assembly.GetName().Name ?? assembly.FullName ?? "<unknown>").Distinct<string>(StringComparer.OrdinalIgnoreCase).Order<string>(StringComparer.OrdinalIgnoreCase).ToArray();
			if (array.Length != 0)
			{
				return new RuntimeDetourRiskMod(mod, array);
			}
			return null;
		}

		private static IEnumerable<Assembly> EnumerateModOwnedAssemblies(Sts2LoadedModAssemblyEntry mod)
		{
			Assembly assembly = mod.Assembly;
			string modDirectory = TryGetAssemblyDirectory(assembly);
			HashSet<Assembly> yielded = new HashSet<Assembly>();
			if (ShouldInspectAssembly(assembly) && yielded.Add(assembly))
			{
				yield return assembly;
			}
			if (string.IsNullOrWhiteSpace(modDirectory))
			{
				yield break;
			}
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly assembly2 in assemblies)
			{
				if (ShouldInspectAssembly(assembly2) && yielded.Add(assembly2) && string.Equals(TryGetAssemblyDirectory(assembly2), modDirectory, StringComparison.OrdinalIgnoreCase))
				{
					yield return assembly2;
				}
			}
		}

		private static bool ShouldInspectAssembly(Assembly assembly)
		{
			string name = assembly.GetName().Name;
			if (!string.IsNullOrWhiteSpace(name))
			{
				return !IsInfrastructureAssemblyName(name);
			}
			return false;
		}

		private static bool ReferencesRuntimeDetour(Assembly assembly)
		{
			try
			{
				return assembly.GetReferencedAssemblies().Any((AssemblyName reference) => IsRuntimeDetourAssemblyName(reference.Name));
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"{"[RuntimeDetourCompat]"} Failed to inspect assembly references for {FormatAssemblyName(assembly)}: {ex.Message}", 1);
				return false;
			}
		}

		private static RuntimeDetourScanResult FindHarmonyRuntimeDetourConflicts(RuntimeDetourReflectionBridge bridge)
		{
			List<RuntimeDetourHarmonyConflict> list = new List<RuntimeDetourHarmonyConflict>();
			int num = 0;
			foreach (HarmonyPatchedMethodGroup item in BuildHarmonyPatchIndex())
			{
				IReadOnlyList<RuntimeDetourHook> runtimeDetourHooks;
				try
				{
					runtimeDetourHooks = bridge.GetRuntimeDetourHooks(item.OriginalMethod);
				}
				catch (Exception ex)
				{
					num++;
					RitsuLibFramework.Logger.Warn($"{"[RuntimeDetourCompat]"} Failed to query RuntimeDetour hooks for {FormatMethod(item.OriginalMethod)}: {ex.Message}", 1);
					continue;
				}
				if (runtimeDetourHooks.Count > 0)
				{
					list.Add(new RuntimeDetourHarmonyConflict(item, runtimeDetourHooks));
				}
			}
			List<RuntimeDetourHarmonyConflict> list2 = new List<RuntimeDetourHarmonyConflict>();
			list2.AddRange(list.OrderBy<RuntimeDetourHarmonyConflict, string>((RuntimeDetourHarmonyConflict conflict) => FormatMethod(conflict.HarmonyPatchGroup.OriginalMethod), StringComparer.Ordinal));
			return new RuntimeDetourScanResult(new <>z__ReadOnlyList<RuntimeDetourHarmonyConflict>(list2), num);
		}

		private static IReadOnlyList<HarmonyPatchedMethodGroup> BuildHarmonyPatchIndex()
		{
			List<HarmonyPatchedMethodGroup> list = new List<HarmonyPatchedMethodGroup>();
			foreach (MethodBase item in Harmony.GetAllPatchedMethods().OrderBy<MethodBase, string>((MethodBase method) => method.DeclaringType?.FullName ?? "", StringComparer.Ordinal).ThenBy<MethodBase, string>((MethodBase method) => method.Name, StringComparer.Ordinal))
			{
				Patches patchInfo = Harmony.GetPatchInfo(item);
				if (patchInfo != null)
				{
					string[] array = FormatPatches("Prefix", patchInfo.Prefixes).Concat(FormatPatches("Postfix", patchInfo.Postfixes)).Concat(FormatPatches("Transpiler", patchInfo.Transpilers)).Concat(FormatPatches("Finalizer", patchInfo.Finalizers))
						.Order<string>(StringComparer.Ordinal)
						.ToArray();
					if (array.Length != 0)
					{
						list.Add(new HarmonyPatchedMethodGroup(item, array));
					}
				}
			}
			return list;
		}

		private static IEnumerable<string> FormatPatches(string kind, IEnumerable<Patch> patches)
		{
			return from patch in patches.OrderBy((Patch patch) => patch.priority).ThenBy<Patch, string>((Patch patch) => patch.owner, StringComparer.Ordinal).ThenBy<Patch, string>((Patch patch) => FormatMethod(patch.PatchMethod), StringComparer.Ordinal)
				select $"{kind} owner={patch.owner} priority={patch.priority} method={FormatMethod(patch.PatchMethod)}";
		}

		private static string BuildRuntimeDetourDependencyMessage(IReadOnlyList<RuntimeDetourRiskMod> riskMods)
		{
			StringBuilder stringBuilder = new StringBuilder().AppendLine("[RuntimeDetourCompat] Loaded mod assemblies reference MonoMod.RuntimeDetour.").AppendLine("RitsuLib will check whether active RuntimeDetour hooks and Harmony patches currently target the same methods.").AppendLine("Referencing mods:");
			foreach (RuntimeDetourRiskMod item in riskMods.OrderBy<RuntimeDetourRiskMod, string>((RuntimeDetourRiskMod mod) => mod.Mod.Id, StringComparer.OrdinalIgnoreCase))
			{
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(17, 2, stringBuilder2);
				handler.AppendLiteral("  - ");
				handler.AppendFormatted(FormatMod(item.Mod));
				handler.AppendLiteral(" references: ");
				handler.AppendFormatted(string.Join(", ", item.ReferencingAssemblies));
				stringBuilder2.AppendLine(ref handler);
			}
			return stringBuilder.ToString().TrimEnd();
		}

		private static string BuildConflictWarning(IReadOnlyList<RuntimeDetourHarmonyConflict> conflicts)
		{
			StringBuilder stringBuilder = new StringBuilder().AppendLine("[RuntimeDetourCompat] WARNING: RuntimeDetour hooks overlap Harmony-patched methods.").AppendLine("An overlap can make behavior depend on detour installation order and whether each hook invokes the next detour. It does not by itself prove that Harmony patches are skipped.");
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(21, 1, stringBuilder);
			handler.AppendLiteral("Overlapping methods: ");
			handler.AppendFormatted(conflicts.Count);
			StringBuilder stringBuilder3 = stringBuilder2.AppendLine(ref handler);
			foreach (RuntimeDetourHarmonyConflict conflict in conflicts)
			{
				stringBuilder = stringBuilder3;
				StringBuilder stringBuilder4 = stringBuilder;
				handler = new StringBuilder.AppendInterpolatedStringHandler(4, 1, stringBuilder);
				handler.AppendLiteral("  * ");
				handler.AppendFormatted(FormatMethod(conflict.HarmonyPatchGroup.OriginalMethod));
				stringBuilder4.AppendLine(ref handler).AppendLine("    Harmony patches:");
				foreach (string patch in conflict.HarmonyPatchGroup.Patches)
				{
					stringBuilder = stringBuilder3;
					StringBuilder stringBuilder5 = stringBuilder;
					handler = new StringBuilder.AppendInterpolatedStringHandler(8, 1, stringBuilder);
					handler.AppendLiteral("      - ");
					handler.AppendFormatted(patch);
					stringBuilder5.AppendLine(ref handler);
				}
				stringBuilder3.AppendLine("    RuntimeDetour hooks:");
				foreach (RuntimeDetourHook hook in conflict.Hooks)
				{
					stringBuilder = stringBuilder3;
					StringBuilder stringBuilder6 = stringBuilder;
					handler = new StringBuilder.AppendInterpolatedStringHandler(17, 3, stringBuilder);
					handler.AppendLiteral("      - ");
					handler.AppendFormatted(hook.Kind);
					handler.AppendLiteral(" ");
					handler.AppendFormatted(hook.Target);
					handler.AppendLiteral(" config=");
					handler.AppendFormatted(hook.Config);
					stringBuilder6.AppendLine(ref handler);
				}
			}
			return stringBuilder3.ToString().TrimEnd();
		}

		private static void ShowCompatibilityToast(IReadOnlyList<RuntimeDetourRiskMod> riskMods, IReadOnlyList<RuntimeDetourHarmonyConflict> conflicts, bool queryIncomplete)
		{
			try
			{
				string title = ((conflicts.Count > 0) ? T("ritsulib.runtimeDetourCompat.toast.conflictTitle", "RuntimeDetour/Harmony interaction") : T("ritsulib.runtimeDetourCompat.toast.riskTitle", "RuntimeDetour compatibility check"));
				string body = ((conflicts.Count <= 0) ? (queryIncomplete ? T("ritsulib.runtimeDetourCompat.toast.queryUnavailableBody", "RuntimeDetour dependency detected, but hook overlap could not be fully checked. Click for details.") : T("ritsulib.runtimeDetourCompat.toast.noOverlapBody", "RuntimeDetour dependency detected. No Harmony overlap is currently known. Click for details.")) : (queryIncomplete ? L("ritsulib.runtimeDetourCompat.toast.partialConflictBody", "{0} Harmony-patched method(s) also have active RuntimeDetour hooks, and some methods could not be checked. Click to review them.", conflicts.Count) : L("ritsulib.runtimeDetourCompat.toast.conflictBody", "{0} Harmony-patched method(s) also have active RuntimeDetour hooks. Click to review them.", conflicts.Count)));
				RuntimeDetourRiskMod[] capturedRiskMods = riskMods.ToArray();
				RuntimeDetourHarmonyConflict[] capturedConflicts = conflicts.ToArray();
				RitsuToastService.Show(RitsuToastRequest.Warning(body, title).Persistent().WithClick(delegate
				{
					ShowCompatibilityDialog(capturedRiskMods, capturedConflicts, queryIncomplete);
				}));
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[RuntimeDetourCompat] Failed to show compatibility toast: " + ex.Message, 1);
			}
		}

