		private static string BuildDialogSummary(IReadOnlyList<RuntimeDetourRiskMod> riskMods, IReadOnlyList<RuntimeDetourHarmonyConflict> conflicts, bool queryIncomplete)
		{
			if (conflicts.Count > 0)
			{
				if (!queryIncomplete)
				{
					return L("ritsulib.runtimeDetourCompat.dialog.summary.conflict", "{0} mod(s) reference MonoMod.RuntimeDetour. {1} Harmony-patched method(s) also have active RuntimeDetour hooks. Review hook ordering and continuation behavior; overlap alone does not prove that Harmony patches are skipped.", riskMods.Count, conflicts.Count);
				}
				return L("ritsulib.runtimeDetourCompat.dialog.summary.partialConflict", "{0} mod(s) reference MonoMod.RuntimeDetour. At least {1} Harmony-patched method(s) also have active RuntimeDetour hooks, and some methods could not be checked. Additional overlaps may exist. Review hook ordering and continuation behavior; overlap alone does not prove that Harmony patches are skipped.", riskMods.Count, conflicts.Count);
			}
			if (!queryIncomplete)
			{
				return L("ritsulib.runtimeDetourCompat.dialog.summary.noOverlap", "{0} mod(s) reference MonoMod.RuntimeDetour. No RuntimeDetour hook currently overlaps a Harmony-patched method.", riskMods.Count);
			}
			return L("ritsulib.runtimeDetourCompat.dialog.summary.queryUnavailable", "{0} mod(s) reference MonoMod.RuntimeDetour, but active hooks could not be fully queried. RuntimeDetour/Harmony overlap is unknown.", riskMods.Count);
		}

