		private static string FormatMod(Sts2LoadedModAssemblyEntry mod)
		{
			string value = (string.IsNullOrWhiteSpace(mod.Version) ? "" : (", version=" + mod.Version));
			return $"{mod.Name} [{mod.Id}] (assembly={FormatAssemblyName(mod.Assembly)}{value})";
		}

		private static string FormatAssemblyName(Assembly assembly)
		{
			try
			{
				return assembly.GetName().Name ?? assembly.FullName ?? "<unknown>";
			}
			catch
			{
				return assembly.FullName ?? "<unknown>";
			}
		}

		private static string FormatMethod(MethodBase method)
		{
			string value = method.DeclaringType?.FullName ?? "<unknown>";
			string value2 = string.Join(", ", from parameter in method.GetParameters()
				select parameter.ParameterType.FullName ?? parameter.ParameterType.Name);
			return $"{value}.{method.Name}({value2})";
		}

		private static string? TryGetAssemblyDirectory(Assembly assembly)
		{
			try
			{
				string location = assembly.Location;
				return string.IsNullOrWhiteSpace(location) ? null : Path.GetDirectoryName(location);
			}
			catch
			{
				return null;
			}
		}

		private static bool IsInfrastructureAssemblyName(string? assemblyName)
		{
			if (!string.IsNullOrWhiteSpace(assemblyName))
			{
				return InfrastructureAssemblyNamePrefixes.Any((string prefix) => assemblyName.Equals(prefix, StringComparison.OrdinalIgnoreCase) || assemblyName.StartsWith(prefix, StringComparison.OrdinalIgnoreCase));
			}
			return false;
		}

		private static bool IsRuntimeDetourAssemblyName(string? assemblyName)
		{
			if (!string.IsNullOrWhiteSpace(assemblyName))
			{
				if (!assemblyName.Equals("MonoMod.RuntimeDetour", StringComparison.OrdinalIgnoreCase))
				{
					return assemblyName.StartsWith("MonoMod.RuntimeDetour.", StringComparison.OrdinalIgnoreCase);
				}
				return true;
			}
			return false;
		}
	}
	internal static class SelfCheckBundleCoordinator
	{
		private static int _autoRunIssuedForSession;

		internal static void TryAutoRunOnFirstMainMenu()
		{
			(string OutputFolder, bool RunOnFirstMainMenu) selfCheckOptions = RitsuLibSettingsStore.GetSelfCheckOptions();
			var (outputPath, _) = selfCheckOptions;
			if (selfCheckOptions.RunOnFirstMainMenu && Interlocked.CompareExchange(ref _autoRunIssuedForSession, 1, 0) == 0)
			{
				TryRunWithConfiguredPath(outputPath, "[SelfCheck][Auto]", showPrompt: false, revealZipOnSuccess: false, out string _, out string _);
			}
		}

		internal static void TryManualRunFromSettings()
		{
			TryRunWithConfiguredPath(RitsuLibSettingsStore.GetSelfCheckOptions().OutputFolder, "[SelfCheck][Manual]", showPrompt: true, revealZipOnSuccess: true, out string _, out string _);
		}

		internal static void TryOpenOutputFolderFromSettings()
		{
			TryOpenOutputFolderFromSettings(out string _);
		}

		internal static bool TryManualRunFromConsole(out string message)
		{
			string zipPath;
			return TryRunWithConfiguredPath(RitsuLibSettingsStore.GetSelfCheckOptions().OutputFolder, "[SelfCheck][Console]", showPrompt: false, revealZipOnSuccess: true, out zipPath, out message);
		}

		internal static bool TryOpenOutputFolderFromSettings(out string message)
		{
			//IL_0062: Unknown result type (might be due to invalid IL or missing references)
			//IL_0067: Unknown result type (might be due to invalid IL or missing references)
			//IL_0068: Unknown result type (might be due to invalid IL or missing references)
			//IL_009e: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d6: Unknown result type (might be due to invalid IL or missing references)
			string text = SelfCheckBundleWriter.TryResolveOutputDirectory(RitsuLibSettingsStore.GetSelfCheckOptions().OutputFolder);
			if (string.IsNullOrEmpty(text))
			{
				message = "Output folder is empty or invalid. Configure a valid path in RitsuLib settings.";
				RitsuLibFramework.Logger.Warn("[SelfCheck][OpenFolder] " + message, 1);
				return false;
			}
			try
			{
				Directory.CreateDirectory(text);
				Error val = OS.ShellOpen(new Uri(text + Path.DirectorySeparatorChar).AbsoluteUri);
				if ((int)val != 0)
				{
					RitsuLibFramework.Logger.Warn($"[SelfCheck][OpenFolder] Failed to open folder '{text}' (Error: {val}).", 1);
					message = $"Could not open the self-check output folder: {val}.";
					return false;
				}
				RitsuLibFramework.Logger.Info("[SelfCheck][OpenFolder] Opened output folder: " + text, 1);
				message = "Opened RitsuLib self-check output folder: " + text;
				return true;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[SelfCheck][OpenFolder] Failed to open output folder '" + text + "': " + ex.Message, 1);
				message = "Could not open the self-check output folder: " + ex.Message;
				return false;
			}
		}

		private static bool TryRunWithConfiguredPath(string outputPath, string logPrefix, bool showPrompt, bool revealZipOnSuccess, out string? zipPath, out string message)
		{
			zipPath = null;
			string title = ModSettingsLocalization.Get("ritsulib.selfCheck.prompt.title", "RitsuLib Self-check");
			string text = SelfCheckBundleWriter.TryResolveOutputDirectory(outputPath);
			if (string.IsNullOrEmpty(text))
			{
				RitsuLibFramework.Logger.Warn(logPrefix + " Output folder is empty or invalid. Configure a valid path in RitsuLib settings.", 1);
				message = ModSettingsLocalization.Get("ritsulib.selfCheck.prompt.invalidPath", "Self-check did not run: output folder is empty or invalid. Configure a valid path first.");
				if (showPrompt)
				{
					ShowCompletionPrompt(title, message);
				}
				return false;
			}
			RitsuLibFramework.Logger.Info(logPrefix + " Starting self-check bundle export...", 1);
			if (!SelfCheckBundleWriter.TryWriteBundle(text, out zipPath, out string errorMessage))
			{
				RitsuLibFramework.Logger.Warn(logPrefix + " Export failed: " + errorMessage, 1);
				string format = ModSettingsLocalization.Get("ritsulib.selfCheck.prompt.failed", "Self-check export failed: {0}");
				message = string.Format(format, errorMessage);
				if (showPrompt)
				{
					ShowCompletionPrompt(title, message);
				}
				return false;
			}
			RitsuLibFramework.Logger.Info(logPrefix + " Export complete. Zip: " + zipPath, 1);
			if (revealZipOnSuccess)
			{
				TryRevealExportedZip(zipPath, logPrefix);
			}
			string format2 = ModSettingsLocalization.Get("ritsulib.selfCheck.prompt.success", "Self-check complete. Exported zip: {0}");
			message = string.Format(format2, NormalizePathForDisplay(zipPath));
			if (showPrompt)
			{
				ShowCompletionPrompt(title, message);
			}
			return true;
		}

		private static void TryRevealExportedZip(string? zipPath, string logPrefix)
		{
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			//IL_0019: Unknown result type (might be due to invalid IL or missing references)
			//IL_0070: Unknown result type (might be due to invalid IL or missing references)
			if (string.IsNullOrWhiteSpace(zipPath))
			{
				return;
			}
			try
			{
				string text = ResolveShellPath(zipPath);
				Error val = OS.ShellShowInFileManager(text, true);
				if ((int)val == 0)
				{
					RitsuLibFramework.Logger.Info(logPrefix + " Revealed self-check zip: " + text, 1);
					return;
				}
				RitsuLibFramework.Logger.Warn($"{logPrefix} Failed to reveal self-check zip '{text}' (Error: {val}).", 1);
				TryOpenContainingFolder(text, logPrefix);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"{logPrefix} Failed to reveal self-check zip '{zipPath}': {ex.Message}", 1);
				TryOpenContainingFolder(zipPath, logPrefix);
			}
		}

		private static string ResolveShellPath(string path)
		{
			if (path.StartsWith("user://", StringComparison.OrdinalIgnoreCase) || path.StartsWith("res://", StringComparison.OrdinalIgnoreCase))
			{
				return ProjectSettings.GlobalizePath(path);
			}
			return Path.GetFullPath(path);
		}

		private static void TryOpenContainingFolder(string zipPath, string logPrefix)
		{
			//IL_0036: Unknown result type (might be due to invalid IL or missing references)
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			//IL_003c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0077: Unknown result type (might be due to invalid IL or missing references)
			try
			{
				string directoryName = Path.GetDirectoryName(zipPath);
				if (!string.IsNullOrWhiteSpace(directoryName))
				{
					Error val = OS.ShellOpen(new Uri(directoryName + Path.DirectorySeparatorChar).AbsoluteUri);
					if ((int)val != 0)
					{
						RitsuLibFramework.Logger.Warn($"{logPrefix} Failed to open self-check output folder '{directoryName}' (Error: {val}).", 1);
					}
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn(logPrefix + " Failed to open self-check output folder fallback: " + ex.Message, 1);
			}
		}

		private static void ShowCompletionPrompt(string title, string message)
		{
			try
			{
				MainLoop mainLoop = Engine.GetMainLoop();
				SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
				if (((val != null) ? val.Root : null) != null)
				{
					string dismissText = ModSettingsLocalization.Get("clipboard.pasteErrorOk", "OK");
					ModSettingsUiFactory.ShowStyledNotice((Node)(object)val.Root, title, message, dismissText);
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[SelfCheck][Prompt] Failed to show completion prompt: " + ex.Message, 1);
			}
		}

		private static string NormalizePathForDisplay(string? path)
		{
			if (string.IsNullOrWhiteSpace(path))
			{
				return path ?? string.Empty;
			}
			return path.Replace('\\', Path.DirectorySeparatorChar).Replace('/', Path.DirectorySeparatorChar);
		}
	}
	internal static class SelfCheckBundleWriter
	{
		private readonly record struct ArtifactCollectionResult(IReadOnlyList<ArtifactEntry> Artifacts, IReadOnlyList<string> Warnings);

		private readonly record struct ArtifactEntry(string EntryName, string SourcePath, long? SizeBytes, string Kind, string Note);

		private sealed class MutableModCheckCounter
		{
			internal int Fail;

			internal int Pass;

			internal int Total;

			internal int Warn;

			internal ModCheckCounter ToSnapshot(string modId)
			{
				return new ModCheckCounter(modId, Total, Pass, Warn, Fail);
			}
		}

		private readonly record struct Issue(string Level, string ModId, string Source, string Reason, string Diagnosis);

		private readonly record struct ModCheckCounter(string ModId, int Total, int Pass, int Warn, int Fail);

		private readonly record struct PerModSummary(string ModId, int RegisteredModelCount, int RegisteredKeywordCount, int TotalChecks, int PassCount, int WarnCount, int FailCount);

		private readonly record struct CheckResult
		{
			internal int Failures { get; }

			internal int Warnings { get; }

			internal IReadOnlyList<ModCheckCounter> Counters { get; }

			internal IReadOnlyList<Issue> Issues { get; }

			internal CheckResult(IReadOnlyList<Issue> issues, IReadOnlyList<ModCheckCounter> counters)
			{
				Counters = Array.Empty<ModCheckCounter>();
				Issues = Array.Empty<Issue>();
				Issues = issues;
				Counters = counters;
				Failures = issues.Count((Issue i) => i.Level == "FAIL");
				Warnings = issues.Count((Issue i) => i.Level == "WARN");
			}
		}

		private const long MaxLinuxCoreDumpBytes = 209715200L;

		private static readonly HashSet<string> TextLogExtensions = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { ".csv", ".json", ".jsonl", ".log", ".md", ".tsv", ".txt", ".xml", ".yaml", ".yml" };

		private static readonly Encoding Utf8NoBom = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false);

		private const string BundlePrefix = "ritsulib_self_check_";

		private static readonly Lock BundleWriteLock = new Lock();

		private static readonly Regex KeywordId = KeywordIdRegex();

		private static readonly Regex PublicEntry = PublicEntryRegex();

		private static ArtifactCollectionResult CollectSupportArtifacts(string bundleDir)
		{
			List<ArtifactEntry> artifacts = new List<ArtifactEntry>();
			List<string> warnings = new List<string>();
			TryCollect("active_replay_flush", delegate
			{
				TryFlushActiveReplay(warnings);
			}, warnings);
			TryCollect("logs", delegate
			{
				CopyUserLogTree(bundleDir, artifacts, warnings);
			}, warnings);
			TryCollect("crashes", delegate
			{
				CopyCrashDiagnostics(bundleDir, artifacts, warnings);
			}, warnings);
			TryCollect("saves", delegate
			{
				CopySaveTree(bundleDir, artifacts, warnings);
			}, warnings);
			TryCollect("release_info", delegate
			{
				CopyReleaseInfo(bundleDir, artifacts, warnings);
			}, warnings);
			TryCollect("screenshot", delegate
			{
				CaptureScreenshot(bundleDir, artifacts, warnings);
			}, warnings);
			TryCollect("runtime_environment", delegate
			{
				WriteRuntimeEnvironment(bundleDir, artifacts, warnings);
			}, warnings);
			TryCollect("mod_inventory", delegate
			{
				WriteModInventory(bundleDir, artifacts, warnings);
			}, warnings);
			TryCollect("loaded_assemblies", delegate
			{
				WriteLoadedAssemblyInventory(bundleDir, artifacts, warnings);
			}, warnings);
			return new ArtifactCollectionResult(artifacts, warnings);
		}

		private static void TryFlushActiveReplay(ICollection<string> warnings)
		{
			try
			{
				RunManager instance = RunManager.Instance;
				if (instance != null && instance.IsInProgress)
				{
					CombatReplayWriter combatReplayWriter = instance.CombatReplayWriter;
					if (combatReplayWriter != null && combatReplayWriter.IsRecordingReplay)
					{
						RunManager.Instance.WriteReplay(false);
					}
				}
			}
			catch (Exception ex)
			{
				warnings.Add("failed to flush active combat replay before collecting saves: " + ex.Message);
			}
		}

		private static void CopyUserLogTree(string bundleDir, ICollection<ArtifactEntry> artifacts, ICollection<string> warnings)
		{
			string userDataDirectory = GetUserDataDirectory();
			string text = Path.Combine(userDataDirectory, "logs");
			if (!Directory.Exists(text))
			{
				warnings.Add("logs source directory not found: " + SanitizeForReport(text));
				return;
			}
			foreach (string item in Directory.EnumerateFiles(text, "*", SearchOption.AllDirectories).OrderBy<string, string>((string x) => x, StringComparer.OrdinalIgnoreCase))
			{
				string entryName = NormalizeEntryName(Path.GetRelativePath(userDataDirectory, item));
				string bundlePath = GetBundlePath(bundleDir, entryName);
				if (StateDivergenceLogBundleWriter.IsPublishedBundlePath(item))
				{
					CopyStateDivergenceBundleArtifact(item, bundlePath, entryName, artifacts, warnings);
				}
				else if (IsTextLogArtifact(item))
				{
					CopyTextArtifact(item, bundlePath, entryName, "log", sanitize: true, artifacts, warnings);
				}
				else
				{
					CopyBinaryArtifact(item, bundlePath, entryName, "log", artifacts, warnings);
				}
			}
		}

		private static void CopyCrashDiagnostics(string bundleDir, ICollection<ArtifactEntry> artifacts, ICollection<string> warnings)
		{
			List<string> list = new List<string>();
			string path = Path.Combine(GetUserDataDirectory(), "sentry", "reports");
			if (Directory.Exists(path))
			{
				list.AddRange(Directory.GetFiles(path));
			}
			if (OS.GetName() == "Windows")
			{
				string path2 = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "CrashDumps");
				if (Directory.Exists(path2))
				{
					string executableName = Path.GetFileNameWithoutExtension(OS.GetExecutablePath());
					list.AddRange(from file in Directory.GetFiles(path2)
						where Path.GetFileName(file).StartsWith(executableName, StringComparison.OrdinalIgnoreCase)
						select file);
				}
			}
			string text = list.Where(File.Exists).OrderByDescending(File.GetLastWriteTimeUtc).FirstOrDefault();
			if (text != null)
			{
				DateTime lastWriteTime = File.GetLastWriteTime(text);
				string entryName = $"crashes/crash_{lastWriteTime:yyyy-MM-dd_HH-mm-ss}{Path.GetExtension(text)}";
				CopyBinaryArtifact(text, GetBundlePath(bundleDir, entryName), entryName, "crash", artifacts, warnings);
			}
			TryCollectLinuxCoreDump(bundleDir, artifacts, warnings);
		}

		private static void CopySaveTree(string bundleDir, ICollection<ArtifactEntry> artifacts, ICollection<string> warnings)
		{
			string text = ProjectSettings.GlobalizePath(ProfileManager.GetAccountRootPath());
			if (!Directory.Exists(text))
			{
				warnings.Add("account save directory not found: " + SanitizeForReport(text));
				return;
			}
			foreach (string item in Directory.EnumerateFiles(text, "*", SearchOption.AllDirectories).OrderBy<string, string>((string x) => x, StringComparer.OrdinalIgnoreCase))
			{
				string relativePath = Path.GetRelativePath(text, item);
				string entryName = NormalizeEntryName(Path.Combine("saves", relativePath));
				if (Path.GetExtension(item).Equals(".json", StringComparison.OrdinalIgnoreCase))
				{
					CopyTextArtifact(item, GetBundlePath(bundleDir, entryName), entryName, "save", sanitize: true, artifacts, warnings);
				}
				else
				{
					CopyBinaryArtifact(item, GetBundlePath(bundleDir, entryName), entryName, "save", artifacts, warnings);
				}
			}
		}

		private static void CopyReleaseInfo(string bundleDir, ICollection<ArtifactEntry> artifacts, ICollection<string> warnings)
		{
			foreach (string item in EnumerateReleaseInfoPaths())
			{
				if (File.Exists(item))
				{
					CopyTextArtifact(item, GetBundlePath(bundleDir, "release_info.json"), "release_info.json", "release-info", sanitize: true, artifacts, warnings);
					return;
				}
			}
			warnings.Add("release_info.json not found beside the game executable.");
		}

		private static void CaptureScreenshot(string bundleDir, ICollection<ArtifactEntry> artifacts, ICollection<string> warnings)
		{
			MainLoop mainLoop = Engine.GetMainLoop();
			SceneTree val = (SceneTree)(object)((mainLoop is SceneTree) ? mainLoop : null);
			if (val != null)
			{
				Window root = val.Root;
				if (root != null)
				{
					Image image = ((Texture2D)((Node)root).GetViewport().GetTexture()).GetImage();
					if (image == null || image.IsEmpty())
					{
						warnings.Add("screenshot skipped: viewport image was empty.");
						return;
					}
					string bundlePath = GetBundlePath(bundleDir, "screenshot.png");
					Directory.CreateDirectory(Path.GetDirectoryName(bundlePath));
					File.WriteAllBytes(bundlePath, image.SavePngToBuffer());
					artifacts.Add(CreateArtifact("screenshot.png", bundlePath, "screenshot", "viewport capture"));
					return;
				}
			}
			warnings.Add("screenshot skipped: no active SceneTree root.");
		}

		private static void WriteRuntimeEnvironment(string bundleDir, ICollection<ArtifactEntry> artifacts, ICollection<string> warnings)
		{
			string bundlePath = GetBundlePath(bundleDir, "diagnostics/runtime_environment.txt");
			List<string> list = new List<string>
			{
				"=== Runtime Environment ===",
				$"Generated: {DateTime.Now:O}",
				"RitsuLib Version: 0.5.18",
				"RitsuLib Informational Version: " + RitsuLibBuildInfo.InformationalVersion,
				$"RitsuLib Is Dev Build: {RitsuLibBuildInfo.IsDevBuild}",
				"Compat Branch: " + RitsuLibFramework.GetCompatBranchLabel(),
				"Host Version: " + (Sts2HostVersion.ReleaseLabel ?? Sts2HostVersion.Numeric?.ToString() ?? "unknown"),
				"Godot OS Name: " + SafeGodotString((Func<string>)OS.GetName),
				"Godot Executable Path: " + SanitizeForReport(SafeGodotString((Func<string>)OS.GetExecutablePath)),
				"Godot User Data Dir: " + SanitizeForReport(SafeGodotString((Func<string>)OS.GetUserDataDir)),
				"Godot Data Dir: " + SanitizeForReport(SafeGodotString((Func<string>)OS.GetDataDir)),
				"user://: " + SanitizeForReport(GetUserDataDirectory()),
				"Account Scoped Base Path: " + SanitizeForReport(ProjectSettings.GlobalizePath(ProfileManager.GetAccountRootPath())),
				".NET Framework: " + RuntimeInformation.FrameworkDescription,
				"OS Description: " + RuntimeInformation.OSDescription,
				$"OS Architecture: {RuntimeInformation.OSArchitecture}",
				$"Process Architecture: {RuntimeInformation.ProcessArchitecture}",
				$"Is 64-bit Process: {Environment.Is64BitProcess}",
				$"Process ID: {Environment.ProcessId}",
				$"Processor Count: {Environment.ProcessorCount}",
				"Current Directory: " + SanitizeForReport(Environment.CurrentDirectory),
				$"Proton Launch: {SteamCompatibilityRuntime.IsProtonLaunch}",
				$"STEAM_COMPAT_DATA_PATH present: {HasEnvironmentValue("STEAM_COMPAT_DATA_PATH")}",
				$"STEAM_COMPAT_CLIENT_INSTALL_PATH present: {HasEnvironmentValue("STEAM_COMPAT_CLIENT_INSTALL_PATH")}",
				$"WINEPREFIX present: {HasEnvironmentValue("WINEPREFIX")}",
				$"DOTNET_ROOT present: {HasEnvironmentValue("DOTNET_ROOT")}",
				RuntimeFrameworkVersionSummary.TryBuildBaseLibDisplayLine(out string line) ? line : "BaseLib: not detected",
				"",
				"Build Metadata:"
			};
			list.AddRange(from pair in RitsuLibBuildInfo.Metadata.OrderBy<KeyValuePair<string, string>, string>((KeyValuePair<string, string> x) => x.Key, StringComparer.OrdinalIgnoreCase)
				select "- " + pair.Key + ": " + SanitizeForReport(pair.Value));
			if (TryWriteTextFile(bundlePath, string.Join(Environment.NewLine, list) + Environment.NewLine, warnings))
			{
				artifacts.Add(CreateArtifact("diagnostics/runtime_environment.txt", bundlePath, "diagnostic", null));
			}
		}

		private static void WriteModInventory(string bundleDir, ICollection<ArtifactEntry> artifacts, ICollection<string> warnings)
		{
			string bundlePath = GetBundlePath(bundleDir, "diagnostics/mod_inventory.tsv");
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("scope\tid\tname\tversion\tstate\tsource\tworkshopId\taffectsGameplay\tassemblyName\tassemblyVersion\terrorCount\terrors");
			foreach (Sts2ModInventoryEntry item in Sts2ModManagerCompat.BuildLoadedModInventoryEntries().OrderBy<Sts2ModInventoryEntry, string>((Sts2ModInventoryEntry x) => x.Id, StringComparer.OrdinalIgnoreCase))
			{
				AppendModInventoryLine(stringBuilder, "loaded", item);
			}
			foreach (Sts2ModInventoryEntry item2 in Sts2ModManagerCompat.BuildModInventoryEntries().OrderBy<Sts2ModInventoryEntry, string>((Sts2ModInventoryEntry x) => x.Id, StringComparer.OrdinalIgnoreCase))
			{
				AppendModInventoryLine(stringBuilder, "registered", item2);
			}
			if (TryWriteTextFile(bundlePath, stringBuilder.ToString(), warnings))
			{
				artifacts.Add(CreateArtifact("diagnostics/mod_inventory.tsv", bundlePath, "diagnostic", null));
			}
		}

		private static void WriteLoadedAssemblyInventory(string bundleDir, ICollection<ArtifactEntry> artifacts, ICollection<string> warnings)
		{
			string bundlePath = GetBundlePath(bundleDir, "diagnostics/loaded_assemblies.tsv");
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("name\tversion\tinformationalVersion\tlocation");
			foreach (Assembly item in AppDomain.CurrentDomain.GetAssemblies().OrderBy<Assembly, string>((Assembly assembly) => assembly.GetName().Name, StringComparer.OrdinalIgnoreCase))
			{
				try
				{
					AssemblyName name = item.GetName();
					string value = item.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion;
					string text = (item.IsDynamic ? "<dynamic>" : item.Location);
					global::<>y__InlineArray4<string> buffer = default(global::<>y__InlineArray4<string>);
					buffer[0] = EscapeTsv(name.Name);
					buffer[1] = EscapeTsv(name.Version?.ToString());
					buffer[2] = EscapeTsv(value);
					buffer[3] = EscapeTsv(SanitizeForReport(text));
					stringBuilder.AppendLine(string.Join('\t', (ReadOnlySpan<string?>)buffer));
				}
				catch (Exception ex)
				{
					warnings.Add("failed to inspect loaded assembly: " + ex.Message);
				}
			}
			if (TryWriteTextFile(bundlePath, stringBuilder.ToString(), warnings))
			{
				artifacts.Add(CreateArtifact("diagnostics/loaded_assemblies.tsv", bundlePath, "diagnostic", null));
			}
		}

		private static void TryCollectLinuxCoreDump(string bundleDir, ICollection<ArtifactEntry> artifacts, ICollection<string> warnings)
		{
			if (OS.GetName() != "Linux")
			{
				return;
			}
			string fileName = Path.GetFileName(OS.GetExecutablePath());
			TryRunProcessText("coredumpctl", "info -1 --no-pager " + fileName, TimeSpan.FromSeconds(10L), out string output, warnings);
			if (!string.IsNullOrWhiteSpace(output))
			{
				string bundlePath = GetBundlePath(bundleDir, "crashes/coredump_info.txt");
				if (TryWriteTextFile(bundlePath, SanitizeForReport(output), warnings))
				{
					artifacts.Add(CreateArtifact("crashes/coredump_info.txt", bundlePath, "crash", "coredumpctl info"));
				}
			}
			string text = Path.Combine(RitsuLibDataPaths.EnsureTemporaryDirectory(), $"self-check-coredump-{Guid.NewGuid():N}.core");
			try
			{
				TryRunProcessText("coredumpctl", "dump -1 --no-pager -o \"" + text + "\" " + fileName, TimeSpan.FromSeconds(10L), out string _, warnings);
				if (File.Exists(text))
				{
					long length = new FileInfo(text).Length;
					if (length > 209715200)
					{
						warnings.Add($"Linux core dump skipped because it is {FormatByteCount(length)} (limit {FormatByteCount(209715200L)}).");
					}
					else
					{
						CopyBinaryArtifact(text, GetBundlePath(bundleDir, "crashes/coredump.core"), "crashes/coredump.core", "crash", artifacts, warnings);
					}
				}
			}
			finally
			{
				TryDelete(text);
			}
		}

		private static void TryRunProcessText(string fileName, string arguments, TimeSpan timeout, out string? output, ICollection<string> warnings)
		{
			output = null;
			try
			{
				using Process process = new Process();
				process.StartInfo = new ProcessStartInfo
				{
					FileName = fileName,
					Arguments = arguments,
					RedirectStandardOutput = true,
					RedirectStandardError = true,
					UseShellExecute = false
				};
				process.Start();
				Task<string> task = process.StandardOutput.ReadToEndAsync();
				Task<string> task2 = process.StandardError.ReadToEndAsync();
				if (!process.WaitForExit((int)timeout.TotalMilliseconds))
				{
					process.Kill();
					process.WaitForExit(5000);
					warnings.Add($"{fileName} timed out after {timeout.TotalSeconds:0}s.");
					return;
				}
				output = task.GetAwaiter().GetResult();
				string result = task2.GetAwaiter().GetResult();
				if (process.ExitCode != 0)
				{
					warnings.Add($"{fileName} exited with code {process.ExitCode}: {SanitizeForReport(result)}");
				}
			}
			catch (Exception ex)
			{
				warnings.Add("failed to run " + fileName + ": " + ex.Message);
			}
		}

		private static void CopyTextArtifact(string source, string target, string entryName, string kind, bool sanitize, ICollection<ArtifactEntry> artifacts, ICollection<string> warnings)
		{
			try
			{
				Directory.CreateDirectory(Path.GetDirectoryName(target));
				using FileStream stream = new FileStream(source, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
				using StreamReader streamReader = new StreamReader(stream, Encoding.UTF8, detectEncodingFromByteOrderMarks: true);
				string text = streamReader.ReadToEnd();
				if (sanitize)
				{
					text = SanitizeForReport(text);
				}
				File.WriteAllText(target, text, Utf8NoBom);
				artifacts.Add(CreateCopiedArtifact(entryName, source, target, kind, null));
			}
			catch (Exception ex)
			{
				warnings.Add("failed to copy text artifact " + SanitizeForReport(source) + ": " + ex.Message);
			}
		}

		private static void CopyBinaryArtifact(string source, string target, string entryName, string kind, ICollection<ArtifactEntry> artifacts, ICollection<string> warnings)
		{
			try
			{
				Directory.CreateDirectory(Path.GetDirectoryName(target));
				using FileStream fileStream = new FileStream(source, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
				using FileStream destination = new FileStream(target, FileMode.Create, FileAccess.Write, FileShare.None);
				fileStream.CopyTo(destination);
				artifacts.Add(CreateCopiedArtifact(entryName, source, target, kind, null));
			}
			catch (Exception ex)
			{
				warnings.Add("failed to copy binary artifact " + SanitizeForReport(source) + ": " + ex.Message);
			}
		}

