		private static void AppendModInventoryLine(StringBuilder sb, string scope, Sts2ModInventoryEntry mod)
		{
			string text = string.Join(" | ", mod.Errors.Select((LocString error) => ((object)error).ToString()));
			<>y__InlineArray12<string> buffer = default(<>y__InlineArray12<string>);
			buffer[0] = EscapeTsv(scope);
			buffer[1] = EscapeTsv(mod.Id);
			buffer[2] = EscapeTsv(mod.Name);
			buffer[3] = EscapeTsv(mod.Version);
			buffer[4] = EscapeTsv(mod.State);
			buffer[5] = EscapeTsv(mod.Source);
			buffer[6] = EscapeTsv(mod.WorkshopItemId?.ToString());
			buffer[7] = EscapeTsv(mod.AffectsGameplay.ToString());
