		private static string FormatByteCount(long? bytes)
		{
			if (!bytes.HasValue)
			{
				return "unknown";
			}
			long value = bytes.Value;
			if (value >= 1048576)
			{
				if (value >= 1073741824)
				{
					return $"{(double)value / 1073741824.0:0.##} GiB";
				}
				return $"{(double)value / 1048576.0:0.##} MiB";
			}
			if (value >= 1024)
			{
				return $"{(double)value / 1024.0:0.##} KiB";
			}
			return $"{value} B";
		}

