		internal static bool IsPublishedBundlePath(string path)
		{
			if (string.IsNullOrWhiteSpace(path))
			{
				return false;
			}
			string fileName = Path.GetFileName(path);
			if (fileName.StartsWith("ritsulib_self_check_", StringComparison.Ordinal))
			{
				return fileName.EndsWith(".zip", StringComparison.Ordinal);
