			{
				string modId = (ModContentRegistry.TryGetOwnerModId(((object)c).GetType(), out string modId2) ? modId2 : "<unknown-mod>");
				if (c is IModCharacterAssetOverrides modCharacterAssetOverrides)
				{
					Check(modId, ((AbstractModel)c).Id.Entry, "VisualsPath", modCharacterAssetOverrides.CustomVisualsPath, () => c.VisualsPath, requireResource: true);
					Check(modId, ((AbstractModel)c).Id.Entry, "EnergyCounterPath", modCharacterAssetOverrides.CustomEnergyCounterPath, () => c.EnergyCounterPath, requireResource: true);
					Check(modId, ((AbstractModel)c).Id.Entry, "IconTexturePath", modCharacterAssetOverrides.CustomIconTexturePath, () => c.IconTexturePath, requireResource: true);
					Check(modId, ((AbstractModel)c).Id.Entry, "IconOutlineTexturePath", modCharacterAssetOverrides.CustomIconOutlineTexturePath, () => c.IconOutlineTexturePath, requireResource: true);
					Check(modId, ((AbstractModel)c).Id.Entry, "CharacterSelectBg", modCharacterAssetOverrides.CustomCharacterSelectBgPath, () => c.CharacterSelectBg, requireResource: true);
					Check(modId, ((AbstractModel)c).Id.Entry, "CharacterSelectTransitionPath", modCharacterAssetOverrides.CustomCharacterSelectTransitionPath, () => c.CharacterSelectTransitionPath, requireResource: true);
					Check(modId, ((AbstractModel)c).Id.Entry, "TrailPath", modCharacterAssetOverrides.CustomTrailPath, () => c.TrailPath, requireResource: true);
					Check(modId, ((AbstractModel)c).Id.Entry, "AttackSfx", modCharacterAssetOverrides.CustomAttackSfx, () => c.AttackSfx, requireResource: false);
					Check(modId, ((AbstractModel)c).Id.Entry, "CastSfx", modCharacterAssetOverrides.CustomCastSfx, () => c.CastSfx, requireResource: false);
					Check(modId, ((AbstractModel)c).Id.Entry, "DeathSfx", modCharacterAssetOverrides.CustomDeathSfx, () => c.DeathSfx, requireResource: false);
				}
			}
			List<Issue> issues2 = issues;
			List<ModCheckCounter> list = new List<ModCheckCounter>();
			list.AddRange(counters.Select<KeyValuePair<string, MutableModCheckCounter>, ModCheckCounter>((KeyValuePair<string, MutableModCheckCounter> kvp) => kvp.Value.ToSnapshot(kvp.Key)));
			return new CheckResult(issues2, new <>z__ReadOnlyList<ModCheckCounter>(list));
			void Check(string modId3, string charId, string name, string? overrideValue, Func<string> resolveValue, bool requireResource)
			{
				if (!string.IsNullOrWhiteSpace(overrideValue))
				{
					MutableModCheckCounter mutableModCheckCounter = GetCounter(modId3);
					mutableModCheckCounter.Total++;
					string b;
					try
					{
						b = resolveValue();
					}
					catch (Exception ex)
