		private static CheckResult CheckLocalization(IReadOnlyList<ModKeywordDefinition> keywordDefinitions, IReadOnlyList<ModContentRegistry.ModContentRegisteredTypeSnapshot> modelSnapshots)
		{
			Dictionary<string, MutableModCheckCounter> counters = new Dictionary<string, MutableModCheckCounter>(StringComparer.OrdinalIgnoreCase);
			List<Issue> list = new List<Issue>();
			foreach (ModKeywordDefinition keywordDefinition in keywordDefinitions)
			{
				MutableModCheckCounter mutableModCheckCounter = GetCounter(keywordDefinition.ModId);
				mutableModCheckCounter.Total++;
				bool fail = false;
				bool warn = false;
				if (!KeywordId.IsMatch(keywordDefinition.Id))
				{
					fail = true;
					list.Add(new Issue("FAIL", keywordDefinition.ModId, "keyword:" + keywordDefinition.Id, "keyword_id_invalid_format", Diagnose("keyword_id_invalid_format")));
				}
				string qualifiedKeywordId = ModContentRegistry.GetQualifiedKeywordId(keywordDefinition.ModId, "probe_suffix");
				string text = qualifiedKeywordId;
				int length = "probe_suffix".Length;
				qualifiedKeywordId = text.Substring(0, text.Length - length);
				if (!keywordDefinition.Id.StartsWith(qualifiedKeywordId, StringComparison.Ordinal))
				{
					warn = true;
					list.Add(new Issue("WARN", keywordDefinition.ModId, "keyword:" + keywordDefinition.Id, "keyword_id_not_owned_pattern_expected_prefix=" + qualifiedKeywordId, Diagnose("keyword_id_not_owned_pattern_expected_prefix")));
				}
				if (!LocString.Exists(keywordDefinition.TitleTable, keywordDefinition.TitleKey))
				{
					fail = true;
					list.Add(new Issue("FAIL", keywordDefinition.ModId, "keyword:" + keywordDefinition.Id, "title_loc_missing table=" + keywordDefinition.TitleTable + " key=" + keywordDefinition.TitleKey, Diagnose("title_loc_missing")));
				}
				if (!LocString.Exists(keywordDefinition.DescriptionTable, keywordDefinition.DescriptionKey))
				{
					fail = true;
					list.Add(new Issue("FAIL", keywordDefinition.ModId, "keyword:" + keywordDefinition.Id, "description_loc_missing table=" + keywordDefinition.DescriptionTable + " key=" + keywordDefinition.DescriptionKey, Diagnose("description_loc_missing")));
				}
				ApplyStatus(mutableModCheckCounter, fail, warn);
			}
			foreach (ModContentRegistry.ModContentRegisteredTypeSnapshot modelSnapshot in modelSnapshots)
			{
				MutableModCheckCounter mutableModCheckCounter2 = GetCounter(modelSnapshot.ModId);
				mutableModCheckCounter2.Total++;
				bool fail2 = false;
				bool warn2 = false;
				string text2 = modelSnapshot.ModelType.FullName ?? modelSnapshot.ModelType.Name;
				if (modelSnapshot.ModelDbId == (ModelId)null)
				{
					fail2 = true;
					list.Add(new Issue("FAIL", modelSnapshot.ModId, "model:" + text2, "modeldb_id_missing", Diagnose("modeldb_id_missing")));
					ApplyStatus(mutableModCheckCounter2, fail2, warn: false);
					continue;
				}
				string entry = modelSnapshot.ModelDbId.Entry;
				if (!PublicEntry.IsMatch(entry))
				{
					fail2 = true;
					list.Add(new Issue("FAIL", modelSnapshot.ModId, "model:" + text2, "entry_invalid_format entry=" + entry, Diagnose("entry_invalid_format")));
				}
				if (!string.IsNullOrWhiteSpace(modelSnapshot.ExpectedPublicEntry) && !entry.Equals(modelSnapshot.ExpectedPublicEntry, StringComparison.Ordinal))
				{
					string reason = "entry_mismatch expected=" + modelSnapshot.ExpectedPublicEntry + " actual=" + entry;
					string diagnosis = AnalyzeEntryMismatch(modelSnapshot, entry);
					if (IsLegacyCompatibleEntryMismatch(modelSnapshot, entry))
					{
						warn2 = true;
						list.Add(new Issue("WARN", modelSnapshot.ModId, "model:" + text2, reason, diagnosis));
					}
					else
					{
						fail2 = true;
						list.Add(new Issue("FAIL", modelSnapshot.ModId, "model:" + text2, reason, diagnosis));
					}
				}
				ApplyStatus(mutableModCheckCounter2, fail2, warn2);
			}
			List<ModCheckCounter> list2 = new List<ModCheckCounter>();
			list2.AddRange(counters.Select<KeyValuePair<string, MutableModCheckCounter>, ModCheckCounter>((KeyValuePair<string, MutableModCheckCounter> kvp) => kvp.Value.ToSnapshot(kvp.Key)));
			return new CheckResult(list, new <>z__ReadOnlyList<ModCheckCounter>(list2));
			static void ApplyStatus(MutableModCheckCounter counter, bool flag, bool flag2)
			{
				if (flag)
				{
					counter.Fail++;
				}
				else if (flag2)
				{
					counter.Warn++;
				}
				else
				{
					counter.Pass++;
				}
			}
			MutableModCheckCounter GetCounter(string modId)
			{
				if (counters.TryGetValue(modId, out MutableModCheckCounter value))
				{
					return value;
				}
				MutableModCheckCounter mutableModCheckCounter3 = new MutableModCheckCounter();
				counters[modId] = mutableModCheckCounter3;
				return mutableModCheckCounter3;
			}
		}

