		private static string Diagnose(string reasonCode)
		{
			return reasonCode switch
			{
				"override_selected_but_file_missing" => "Override is selected and the target resource file is missing.", 
				"override_file_missing_fallback_to_vanilla" => "Custom resource file is missing; runtime fallback to vanilla is active.", 
				"override_not_applied_possible_patch_skip_or_overwrite" => "Resource exists but resolved value does not match override.", 
				"keyword_id_invalid_format" => "Keyword ID does not match uppercase underscore format.", 
				"keyword_id_not_owned_pattern_expected_prefix" => "Keyword ID prefix does not match this mod's ownership prefix.", 
				"title_loc_missing" => "Title localization key is not found.", 
				"description_loc_missing" => "Description localization key is not found.", 
				"modeldb_id_missing" => "Type does not have a mapped ModelDbId.", 
				"entry_invalid_format" => "ModelId.Entry does not match uppercase underscore format.", 
				"entry_mismatch" => "Actual entry is different from expected entry.", 
				_ => "Unclassified reason.", 
			};
		}

		private static bool IsLegacyCompatibleEntryMismatch(ModContentRegistry.ModContentRegisteredTypeSnapshot snapshot, string actualEntry)
		{
			if (!snapshot.HasExplicitPublicEntryOverride && !string.IsNullOrWhiteSpace(snapshot.TypeNamePublicEntry))
			{
				return actualEntry.Equals(snapshot.TypeNamePublicEntry, StringComparison.Ordinal);
			}
			return false;
		}

		private static string AnalyzeEntryMismatch(ModContentRegistry.ModContentRegisteredTypeSnapshot snapshot, string actualEntry)
		{
			List<string> list = new List<string>(6)
			{
				$"explicitOverride={snapshot.HasExplicitPublicEntryOverride}",
				"legacyTypeNameEntry=" + snapshot.TypeNamePublicEntry,
				$"legacyCompatible={IsLegacyCompatibleEntryMismatch(snapshot, actualEntry)}"
			};
			if (snapshot.ModelDbId == (ModelId)null)
			{
				return string.Join("; ", list);
			}
			Type type = TryResolveModelType(snapshot.ModelDbId, out string ownerModId);
			list.Add((type == null) ? "reverseLookupType=<null>" : ("reverseLookupType=" + type.FullName));
			list.Add("reverseLookupOwner=" + (ownerModId ?? "unknown"));
			return string.Join("; ", list);
		}

		private static Type? TryResolveModelType(ModelId modelId, out string? ownerModId)
		{
			ownerModId = null;
			try
			{
				Type type = ((object)ModelDb.GetById<AbstractModel>(modelId)).GetType();
				if (ModContentRegistry.TryGetOwnerModId(type, out string modId))
				{
					ownerModId = modId;
				}
				return type;
			}
			catch
			{
				return null;
			}
		}

		private static List<PerModSummary> BuildPerModSummary(CheckResult charCheck, CheckResult locCheck, IReadOnlyList<ModKeywordDefinition> keywordDefs, IReadOnlyList<ModContentRegistry.ModContentRegisteredTypeSnapshot> modelSnapshots)
		{
			Dictionary<string, PerModSummary> summaries = new Dictionary<string, PerModSummary>(StringComparer.OrdinalIgnoreCase);
			foreach (IGrouping<string, ModKeywordDefinition> item in keywordDefs.GroupBy<ModKeywordDefinition, string>((ModKeywordDefinition k) => k.ModId, StringComparer.OrdinalIgnoreCase))
			{
				Ensure(item.Key);
				summaries[item.Key] = summaries[item.Key]with
				{
					RegisteredKeywordCount = item.Count()
				};
			}
			foreach (IGrouping<string, ModContentRegistry.ModContentRegisteredTypeSnapshot> item2 in modelSnapshots.GroupBy<ModContentRegistry.ModContentRegisteredTypeSnapshot, string>((ModContentRegistry.ModContentRegisteredTypeSnapshot m) => m.ModId, StringComparer.OrdinalIgnoreCase))
			{
				Ensure(item2.Key);
				summaries[item2.Key] = summaries[item2.Key]with
				{
					RegisteredModelCount = item2.Count()
				};
			}
			foreach (ModCheckCounter item3 in charCheck.Counters.Concat(locCheck.Counters))
			{
				Ensure(item3.ModId);
				PerModSummary perModSummary = summaries[item3.ModId];
				summaries[item3.ModId] = perModSummary with
				{
					TotalChecks = perModSummary.TotalChecks + item3.Total,
					PassCount = perModSummary.PassCount + item3.Pass,
					WarnCount = perModSummary.WarnCount + item3.Warn,
					FailCount = perModSummary.FailCount + item3.Fail
				};
			}
			return summaries.Values.ToList();
			void Ensure(string modId)
			{
				if (!summaries.ContainsKey(modId))
				{
					summaries[modId] = new PerModSummary(modId, 0, 0, 0, 0, 0, 0);
				}
			}
		}

		private static IEnumerable<(string PropertyPath, string Value)> EnumerateCharacterAssetProfilePathFields(CharacterAssetProfile profile)
		{
			if (!string.IsNullOrWhiteSpace(profile.Scenes?.VisualsPath))
			{
				yield return (PropertyPath: "Scenes.VisualsPath", Value: profile.Scenes.VisualsPath);
			}
			if (!string.IsNullOrWhiteSpace(profile.Scenes?.EnergyCounterPath))
			{
				yield return (PropertyPath: "Scenes.EnergyCounterPath", Value: profile.Scenes.EnergyCounterPath);
			}
			if (!string.IsNullOrWhiteSpace(profile.Scenes?.MerchantAnimPath))
			{
				yield return (PropertyPath: "Scenes.MerchantAnimPath", Value: profile.Scenes.MerchantAnimPath);
