	internal static class SelfCheckIlCallGraphAnalyzer
	{
		private readonly record struct IlTarget(string DisplayName, MethodBase? Method);

		private static readonly OpCode[] SingleByteOpCodes;

		private static readonly OpCode[] MultiByteOpCodes;

		static SelfCheckIlCallGraphAnalyzer()
		{
			SingleByteOpCodes = new OpCode[256];
			MultiByteOpCodes = new OpCode[256];
			FieldInfo[] fields = typeof(OpCodes).GetFields(BindingFlags.Static | BindingFlags.Public);
			for (int i = 0; i < fields.Length; i++)
			{
				if (fields[i].GetValue(null) is OpCode opCode)
				{
					ushort num = (ushort)opCode.Value;
					if (num < 256)
					{
						SingleByteOpCodes[num] = opCode;
					}
					else if ((num & 0xFF00) == 65024)
					{
						MultiByteOpCodes[num & 0xFF] = opCode;
					}
				}
			}
		}

		internal static IReadOnlyList<string> BuildReportLines()
		{
			List<string> list = new List<string>();
			IReadOnlyList<IlTarget> targets = GetTargets();
			Dictionary<string, List<string>> dictionary = BuildCallerMap(targets);
			list.Add("IL Static Call Graph (self-check points):");
			foreach (IlTarget item in targets)
			{
				if (item.Method == null)
				{
					list.Add("- " + item.DisplayName + ": target_method_not_found");
					continue;
				}
				if (!dictionary.TryGetValue(item.DisplayName, out var value))
				{
					list.Add("- " + item.DisplayName + ": callers=0");
					continue;
				}
				list.Add($"- {item.DisplayName}: callers={value.Count}");
				list.AddRange(value.Select((string caller) => "  - " + caller));
			}
			return list;
		}

		private static Dictionary<string, List<string>> BuildCallerMap(IReadOnlyList<IlTarget> targets)
		{
			Dictionary<string, HashSet<string>> dictionary = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
			IlTarget[] array = targets.Where((IlTarget t) => t.Method != null).ToArray();
			foreach (MethodBase item2 in EnumerateCandidateMethods())
			{
				foreach (MethodBase item3 in EnumerateCalledMethods(item2))
				{
					IlTarget[] array2 = array;
					for (int num = 0; num < array2.Length; num++)
					{
						IlTarget ilTarget = array2[num];
						if (!(ilTarget.Method == null) && MethodMatches(item3, ilTarget.Method))
						{
							string item = FormatMethod(item2);
							if (!dictionary.TryGetValue(ilTarget.DisplayName, out var value))
							{
								value = new HashSet<string>(StringComparer.Ordinal);
								dictionary[ilTarget.DisplayName] = value;
							}
							value.Add(item);
						}
					}
				}
			}
			return dictionary.ToDictionary<KeyValuePair<string, HashSet<string>>, string, List<string>>((KeyValuePair<string, HashSet<string>> kvp) => kvp.Key, (KeyValuePair<string, HashSet<string>> kvp) => kvp.Value.OrderBy<string, string>((string x) => x, StringComparer.Ordinal).ToList(), StringComparer.Ordinal);
		}

		private static IReadOnlyList<IlTarget> GetTargets()
		{
			return new global::<>z__ReadOnlyArray<IlTarget>(new IlTarget[13]
			{
				new IlTarget("CharacterModel.get_VisualsPath", typeof(CharacterModel).GetMethod("get_VisualsPath", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)),
				new IlTarget("CharacterModel.get_EnergyCounterPath", typeof(CharacterModel).GetMethod("get_EnergyCounterPath", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)),
				new IlTarget("CharacterModel.get_IconTexturePath", typeof(CharacterModel).GetMethod("get_IconTexturePath", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)),
				new IlTarget("CharacterModel.get_IconOutlineTexturePath", typeof(CharacterModel).GetMethod("get_IconOutlineTexturePath", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)),
				new IlTarget("CharacterModel.get_CharacterSelectBg", typeof(CharacterModel).GetMethod("get_CharacterSelectBg", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)),
				new IlTarget("CharacterModel.get_CharacterSelectTransitionPath", typeof(CharacterModel).GetMethod("get_CharacterSelectTransitionPath", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)),
				new IlTarget("CharacterModel.get_TrailPath", typeof(CharacterModel).GetMethod("get_TrailPath", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)),
				new IlTarget("CharacterModel.get_AttackSfx", typeof(CharacterModel).GetMethod("get_AttackSfx", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)),
				new IlTarget("CharacterModel.get_CastSfx", typeof(CharacterModel).GetMethod("get_CastSfx", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)),
				new IlTarget("CharacterModel.get_DeathSfx", typeof(CharacterModel).GetMethod("get_DeathSfx", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)),
				new IlTarget("ResourceLoader.Exists(string)", typeof(ResourceLoader).GetMethod("Exists", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, new Type[1] { typeof(string) })),
				new IlTarget("LocString.Exists(string,string)", typeof(LocString).GetMethod("Exists", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic, new Type[2]
				{
					typeof(string),
					typeof(string)
				})),
				new IlTarget("ModelDb.GetById<T>(ModelId)", FindModelDbGetByIdGeneric())
			});
		}

		private static MethodInfo? FindModelDbGetByIdGeneric()
		{
			return typeof(ModelDb).GetMethods(BindingFlags.Static | BindingFlags.Public).FirstOrDefault(delegate(MethodInfo m)
			{
				if ((object)m != null && m.Name == "GetById" && m.IsGenericMethodDefinition)
				{
					ParameterInfo[] parameters = m.GetParameters();
					if (parameters != null && parameters.Length == 1)
					{
						return parameters[0].ParameterType == typeof(ModelId);
					}
				}
				return false;
			});
		}

		private static IEnumerable<MethodBase> EnumerateCandidateMethods()
		{
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly assembly in assemblies)
			{
				if (assembly.IsDynamic || !IsCandidateAssembly(assembly))
				{
					continue;
				}
				Type[] array;
				try
				{
					array = assembly.GetTypes();
				}
				catch (ReflectionTypeLoadException ex)
				{
					array = ex.Types.Where((Type t) => t != null).Cast<Type>().ToArray();
				}
				catch
				{
					continue;
				}
				Type[] array2 = array;
				foreach (Type type in array2)
				{
					MethodBase[] array6;
					try
					{
						MethodInfo[] methods = type.GetMethods(BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
						ConstructorInfo[] constructors = type.GetConstructors(BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
						int num2 = 0;
						MethodBase[] array3 = new MethodBase[methods.Length + constructors.Length];
						MethodInfo[] array4 = methods;
						foreach (MethodInfo methodInfo in array4)
						{
							array3[num2] = methodInfo;
							num2++;
						}
						ConstructorInfo[] array5 = constructors;
						foreach (ConstructorInfo constructorInfo in array5)
						{
							array3[num2] = constructorInfo;
							num2++;
						}
						array6 = array3;
					}
					catch
					{
						continue;
					}
					MethodBase[] array7 = array6;
					foreach (MethodBase methodBase in array7)
					{
						MethodBody methodBody;
						try
						{
							methodBody = methodBase.GetMethodBody();
						}
						catch
						{
							continue;
						}
						byte[] array8 = methodBody?.GetILAsByteArray();
						if (array8 != null && array8.Length > 0)
						{
							yield return methodBase;
						}
					}
				}
			}
		}

		private static bool IsCandidateAssembly(Assembly assembly)
		{
			string text = assembly.GetName().Name ?? string.Empty;
			if (!text.StartsWith("System", StringComparison.Ordinal) && !text.StartsWith("Microsoft", StringComparison.Ordinal) && !text.StartsWith("netstandard", StringComparison.Ordinal) && !text.StartsWith("mscorlib", StringComparison.Ordinal) && !text.StartsWith("Mono.", StringComparison.Ordinal) && !text.StartsWith("Godot", StringComparison.Ordinal))
			{
				return !text.StartsWith("HarmonyLib", StringComparison.Ordinal);
			}
			return false;
		}

		private static IEnumerable<MethodBase> EnumerateCalledMethods(MethodBase caller)
		{
			MethodBody methodBody;
			try
			{
				methodBody = caller.GetMethodBody();
			}
			catch
			{
				yield break;
			}
			byte[] il = methodBody?.GetILAsByteArray();
			if (il == null || il.Length == 0)
			{
				yield break;
			}
			Module module = caller.Module;
			Type[] typeArgs = caller.DeclaringType?.GetGenericArguments() ?? Type.EmptyTypes;
			Type[] methodArgs = (caller.IsGenericMethod ? caller.GetGenericArguments() : Type.EmptyTypes);
			int pos = 0;
			while (pos < il.Length)
			{
				OpCode? opCode = ReadOpCode(il, ref pos);
				if (!opCode.HasValue)
				{
					break;
				}
				if (opCode.Value.OperandType == OperandType.InlineMethod)
				{
					if (pos + 4 > il.Length)
					{
						break;
					}
					int metadataToken = BitConverter.ToInt32(il, pos);
					MethodBase methodBase = null;
					try
					{
						methodBase = module.ResolveMethod(metadataToken, typeArgs, methodArgs);
					}
					catch
					{
					}
					if (methodBase != null)
					{
						yield return methodBase;
					}
					pos += 4;
				}
				else
				{
					int operandLength = GetOperandLength(opCode.Value.OperandType, il, pos);
					if (operandLength < 0 || operandLength > il.Length - pos)
					{
						break;
					}
					pos += operandLength;
				}
			}
		}

		private static OpCode? ReadOpCode(byte[] il, ref int pos)
		{
			if (pos >= il.Length)
			{
				return null;
			}
			byte b = il[pos++];
			if (b != 254)
			{
				if (SingleByteOpCodes[b].Name != null)
				{
					return SingleByteOpCodes[b];
				}
				return null;
			}
			if (pos >= il.Length)
			{
				return null;
			}
			byte b2 = il[pos++];
			if (MultiByteOpCodes[b2].Name != null)
			{
				return MultiByteOpCodes[b2];
			}
			return null;
		}

		private static int GetOperandLength(OperandType operandType, byte[] il, int pos)
		{
			return operandType switch
			{
				OperandType.InlineNone => 0, 
				OperandType.ShortInlineBrTarget => 1, 
				OperandType.ShortInlineI => 1, 
				OperandType.ShortInlineVar => 1, 
				OperandType.InlineVar => 2, 
				OperandType.InlineI => 4, 
				OperandType.InlineBrTarget => 4, 
				OperandType.InlineField => 4, 
				OperandType.InlineMethod => 4, 
				OperandType.InlineSig => 4, 
				OperandType.InlineString => 4, 
				OperandType.InlineTok => 4, 
				OperandType.InlineType => 4, 
				OperandType.ShortInlineR => 4, 
				OperandType.InlineI8 => 8, 
				OperandType.InlineR => 8, 
				OperandType.InlineSwitch => GetSwitchLength(il, pos), 
				_ => -1, 
			};
		}

		private static int GetSwitchLength(byte[] il, int pos)
		{
			if (pos + 4 > il.Length)
			{
				return -1;
			}
			int num = BitConverter.ToInt32(il, pos);
			if (num < 0 || num > (il.Length - pos - 4) / 4)
			{
				return -1;
			}
			return 4 + num * 4;
		}

		private static bool MethodMatches(MethodBase candidate, MethodBase target)
		{
			if ((object)candidate == target)
			{
				return true;
			}
			if (candidate.Module == target.Module)
			{
				return candidate.MetadataToken == target.MetadataToken;
			}
			return false;
		}

		private static string FormatMethod(MethodBase method)
		{
			return (method.DeclaringType?.FullName ?? "<global>") + "." + method.Name;
		}
	}
	internal static class StartupModListLogger
	{
		private const string Prefix = "[ModList]";

		private static readonly Lock SyncRoot = new Lock();

		private static bool _initialized;

		private static bool _initializing;

		private static bool _logged;

		private static bool _logging;

		internal static void Initialize()
		{
			using (SyncRoot.EnterScope())
			{
				if (_initialized || _initializing)
				{
					return;
				}
				_initializing = true;
			}
			bool flag = false;
			IDisposable disposable = null;
			try
			{
				ModManager.OnModDetected += OnModDetected;
				flag = true;
				TryLogAfterInitialModLoading();
				disposable = RitsuLibFramework.SubscribeLifecycleOnce<MainMenuReadyEvent>(delegate
				{
					TryLogStartupModList();
				});
				using (SyncRoot.EnterScope())
				{
					_initialized = true;
				}
			}
			catch
			{
				disposable?.Dispose();
				if (flag)
				{
					ModManager.OnModDetected -= OnModDetected;
				}
				throw;
			}
			finally
			{
				using (SyncRoot.EnterScope())
				{
					_initializing = false;
				}
			}
		}

		private static void OnModDetected(Mod _)
		{
			TryLogAfterInitialModLoading();
		}

		private static void TryLogAfterInitialModLoading()
		{
			IReadOnlyList<Sts2ModInventoryEntry> readOnlyList;
			try
			{
				readOnlyList = Sts2ModManagerCompat.BuildModInventoryEntries();
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[ModList] Failed to inspect mod loading state: " + ex.Message, 1);
				return;
			}
			if (readOnlyList.Count != 0 && !readOnlyList.Any((Sts2ModInventoryEntry mod) => string.Equals(mod.State, "None", StringComparison.Ordinal)))
			{
				TryLogStartupModList();
			}
		}

		private static void TryLogStartupModList()
		{
			using (SyncRoot.EnterScope())
			{
				if (_logged || _logging)
				{
					return;
				}
				_logging = true;
			}
			try
			{
				IReadOnlyList<Sts2ModInventoryEntry> readOnlyList = Sts2ModManagerCompat.BuildLoadedModInventoryEntries();
				IReadOnlyList<Sts2ModInventoryEntry> readOnlyList2 = Sts2ModManagerCompat.BuildModInventoryEntries();
				string value = Sts2HostVersion.ReleaseLabel ?? Sts2HostVersion.Numeric?.ToString() ?? "unknown";
				StringBuilder stringBuilder = new StringBuilder().AppendLine().AppendLine("=== RitsuLib Mod Debug Information ===");
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(14, 1, stringBuilder);
				handler.AppendLiteral("Host Version: ");
				handler.AppendFormatted(value);
				StringBuilder stringBuilder3 = stringBuilder2.AppendLine(ref handler);
				StringBuilder stringBuilder4 = stringBuilder3;
				StringBuilder.AppendInterpolatedStringHandler handler2 = new StringBuilder.AppendInterpolatedStringHandler(9, 1, stringBuilder3);
				handler2.AppendLiteral("RitsuLib ");
				handler2.AppendFormatted(RitsuLibFramework.BuildVersionLogText());
				StringBuilder stringBuilder5 = stringBuilder4.AppendLine(ref handler2);
				if (RuntimeFrameworkVersionSummary.TryBuildBaseLibDisplayLine(out string line))
				{
					stringBuilder5.AppendLine(line);
				}
				stringBuilder = stringBuilder5;
				StringBuilder stringBuilder6 = stringBuilder;
				handler = new StringBuilder.AppendInterpolatedStringHandler(13, 1, stringBuilder);
				handler.AppendLiteral("Loaded Mods: ");
				handler.AppendFormatted(readOnlyList.Count);
				stringBuilder3 = stringBuilder6.AppendLine(ref handler);
				StringBuilder stringBuilder7 = stringBuilder3;
				handler2 = new StringBuilder.AppendInterpolatedStringHandler(17, 1, stringBuilder3);
				handler2.AppendLiteral("Registered Mods: ");
				handler2.AppendFormatted(readOnlyList2.Count);
				stringBuilder7.AppendLine(ref handler2).AppendLine("Mod List:");
				if (readOnlyList.Count == 0)
				{
					stringBuilder5.AppendLine("  <none>");
				}
				else
				{
					foreach (Sts2ModInventoryEntry item in readOnlyList)
					{
						stringBuilder5.AppendLine($"  * {FormatModName(item)} ({FormatVersion(item)})" + FormatWorkshopItemId(item));
					}
				}
				RitsuLibFramework.Logger.Info(stringBuilder5.ToString(), 1);
				using (SyncRoot.EnterScope())
				{
					_logged = true;
					_logging = false;
				}
				ModManager.OnModDetected -= OnModDetected;
			}
			catch (Exception ex)
			{
				using (SyncRoot.EnterScope())
				{
					_logging = false;
				}
				RitsuLibFramework.Logger.Warn("[ModList] Failed to print startup mod list: " + ex.Message, 1);
			}
		}

		private static string FormatModName(Sts2ModInventoryEntry mod)
		{
			string text = (string.IsNullOrWhiteSpace(mod.Name) ? mod.Id : mod.Name.Trim());
			if (!string.Equals(text, mod.Id, StringComparison.Ordinal))
			{
				return text + " [" + mod.Id + "]";
			}
			return text;
		}

		private static string FormatVersion(Sts2ModInventoryEntry mod)
		{
			if (!string.IsNullOrWhiteSpace(mod.Version))
			{
				return mod.Version.Trim();
			}
			return "unknown version";
		}

		private static string FormatWorkshopItemId(Sts2ModInventoryEntry mod)
		{
			if (!mod.WorkshopItemId.HasValue)
			{
				return "";
			}
			return $" workshopId={mod.WorkshopItemId.Value}";
		}
	}
