namespace STS2RitsuLib.Diagnostics.Patches
{
	/// <summary>
	///     <para xml:lang="en">
	///         Removes localized autocomplete suffix labels before applying a selected candidate to the input line.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将选中的候选项应用到输入行之前，移除其本地化自动补全后缀标签。
	///     </para>
	/// </summary>
	internal sealed class DevConsoleAutocompleteApplyCandidatePatch : IPatchMethod
	{
		private static readonly FieldRef<NDevConsole, TabCompletionState> TabCompletionField = AccessTools.FieldRefAccess<NDevConsole, TabCompletionState>("_tabCompletion");

		public static string PatchId => "dev_console_autocomplete_apply_candidate";

		public static bool IsCritical => false;

		public static string Description => "DevConsole autocomplete: apply canonical model entry id when candidate has a localized suffix";

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NDevConsole), "AcceptSelection")
			};
		}

		public static void Prefix(NDevConsole __instance)
		{
			if (!RitsuLibSettingsStore.IsDevConsoleAutocompleteEnhancementsEnabled())
			{
				return;
			}
			TabCompletionState val = TabCompletionField.Invoke(__instance);
			if (val.InSelectionMode)
			{
				int selectionIndex = val.SelectionIndex;
				if (selectionIndex >= 0 && selectionIndex < val.CompletionCandidates.Count)
				{
					val.CompletionCandidates[selectionIndex] = DevConsoleAutocompleteDisplay.StripLocalizedSuffix(val.CompletionCandidates[selectionIndex]);
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Applies registered developer-console autocomplete enhancements through
