	///         通过 <see cref="T:STS2RitsuLib.Diagnostics.DevConsole.DevConsoleAutocompleteRegistry" /> 应用已注册的开发者控制台自动补全增强。
	///     </para>
	/// </summary>
	internal sealed class DevConsoleAutocompleteEnhancementPatch : IPatchMethod
	{
		public static string PatchId => "dev_console_autocomplete_enhancement";

		public static bool IsCritical => false;

		public static string Description => "DevConsole autocomplete: registry-driven match and display enhancements per command argument";

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(AbstractConsoleCmd), "CompleteArgument", ignoreIfMissing: true)
