	internal sealed class RitsuLibGetLogsArchivePatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_get_logs_archive";

		public static bool IsCritical => false;

		public static string Description => "Preserve RitsuLib diagnostic archives when the game collects logs and feedback.";

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(GetLogsConsoleCmd), "ArchiveLogFile", new Type[4]
				{
					typeof(string),
					typeof(ZipArchive),
					typeof(string),
					typeof(long)
				})
			};
		}

		[HarmonyPriority(800)]
		public static bool Prefix(string file, ZipArchive archive, string entryName)
		{
			Func<string, byte[]> func = null;
			if (StateDivergenceLogBundleWriter.IsPublishedBundlePath(file))
			{
				func = StateDivergenceLogBundleWriter.BuildSanitizedSubmissionBundle;
			}
			else if (SelfCheckBundleWriter.IsPublishedBundlePath(file))
			{
				func = SelfCheckBundleWriter.ReadPublishedBundle;
			}
			if (func == null)
			{
				return true;
			}
			byte[] array;
			try
			{
				array = func(file);
			}
			catch (FileNotFoundException)
			{
				RitsuLibFramework.Logger.Warn("[Diagnostics] Diagnostic bundle disappeared before log collection: " + file, 1);
				return false;
			}
			catch (Exception ex2) when (RitsuLibExceptionPolicy.IsRecoverable(ex2))
			{
				RitsuLibFramework.Logger.Warn("[Diagnostics] Diagnostic bundle could not be collected intact and was skipped: " + file + ": " + ex2.Message, 1);
				return false;
			}
			using Stream stream = archive.CreateEntry(entryName.Replace("\\", "/"), CompressionLevel.Optimal).Open();
			stream.Write(array);
			return false;
		}
	}
