		public static void Initialize(RitsuDebugLogViewerOptions options)
		{
			using (InitLock.EnterScope())
			{
				if (_initialized)
				{
					return;
				}
				try
				{
					_queueCapacity = Math.Clamp(options.QueueCapacity, 256, 100000);
					_ring = new RitsuDebugLogRingBuffer(Math.Clamp(options.RingBufferCapacity, 512, 100000));
					CancellationTokenSource cts = new CancellationTokenSource();
					_cts = cts;
					_worker = Task.Run(() => WorkerLoopAsync(cts.Token));
					ConfigureGodotLogListener(options.MirrorGameLogs);
					if (options.Enabled)
					{
						StartServer(options);
					}
					_initialized = true;
					AppDomain.CurrentDomain.ProcessExit += OnProcessExit;
					if (_server != null)
					{
						RitsuLibFramework.Logger.Info(CreateViewerStartMessage(_server), 1);
					}
				}
				catch (Exception value)
				{
					Exception ex = CleanupAfterFailedStart();
					string value2 = ((ex == null) ? "" : $" Failed to detach the Godot log listener during cleanup: {ex}");
					RitsuLibFramework.Logger.Warn($"[DebugLogViewer] Failed to initialize log capture: {value}{value2}", 1);
				}
			}
		}

		public static void Emit(RitsuDebugLogRecord record)
		{
