		private static void StartServer(RitsuDebugLogViewerOptions options)
		{
			try
			{
				_server = new RitsuDebugLogViewerServer(options.AccessToken, options.LanAccessEnabled, Snapshot, BuildStatus, ResolveViewerAssetRoot());
				_server.Start(options.Port, options.PortFallbackCount);
				if (options.AutoOpen)
				{
					Task.Run(() => AutoOpenViewerIfNoClientAsync(_cts.Token));
				}
			}
			catch (Exception value)
			{
				_server?.Dispose();
				_server = null;
				RitsuLibFramework.Logger.Warn($"[DebugLogViewer] Failed to start viewer server: {value}", 1);
			}
		}

		public static void ReportInternalWarning(string message)
		{
			DateTimeOffset utcNow = DateTimeOffset.UtcNow;
			if (!(utcNow - _lastInternalWarning < InternalWarningInterval))
			{
				_lastInternalWarning = utcNow;
				RitsuLibFramework.Logger.Warn("[DebugLogViewer] " + message, 1);
			}
		}

		public static (bool Success, string Message) TryOpenViewerInBrowser()
		{
			//IL_001b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0020: Unknown result type (might be due to invalid IL or missing references)
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_003d: Unknown result type (might be due to invalid IL or missing references)
			string viewerUrl = ViewerUrl;
			if (string.IsNullOrWhiteSpace(viewerUrl))
			{
				return (Success: false, Message: "RitsuLib debug log viewer is not running.");
			}
			Error val = OS.ShellOpen(viewerUrl);
			if ((int)val != 0)
			{
				return (Success: false, Message: $"Error {val}: Could not open browser. URL: {viewerUrl}");
			}
			return (Success: true, Message: "Opened RitsuLib debug log viewer: " + viewerUrl);
		}

		private static string CreateViewerStartMessage(RitsuDebugLogViewerServer server)
		{
			if (!server.LanAccessEnabled)
			{
				return "[DebugLogViewer] Local debug log viewer listening at " + server.Url;
			}
			IReadOnlyList<string> lanUrls = server.LanUrls;
			if (lanUrls.Count != 0)
			{
				return "[DebugLogViewer] LAN debug log viewer listening at " + server.Url + "; LAN URLs: " + string.Join(", ", lanUrls);
			}
			return "[DebugLogViewer] LAN debug log viewer listening at " + server.Url + "; no LAN IPv4 address was found.";
		}

		private static async Task WorkerLoopAsync(CancellationToken token)
		{
			while (!token.IsCancellationRequested)
			{
				try
				{
					await QueueSignal.WaitAsync(token).ConfigureAwait(continueOnCapturedContext: false);
				}
				catch (OperationCanceledException)
				{
					break;
				}
				DrainQueue();
			}
		}

		private static void DrainQueue()
		{
			using (DrainLock.EnterScope())
			{
				RitsuDebugLogRecord result;
				while (Queue.TryDequeue(out result))
				{
					Interlocked.Decrement(ref _queued);
					_ring?.Add(result);
					_server?.Broadcast(result);
				}
			}
		}

		internal static void EmitGodotLogMessage(string message, bool error)
		{
			Emit(CreateFromGodotLog(message, error));
		}

		private static async Task AutoOpenViewerIfNoClientAsync(CancellationToken token)
		{
			try
			{
				await Task.Delay(AutoOpenDelay, token).ConfigureAwait(continueOnCapturedContext: false);
				if (!token.IsCancellationRequested && _server != null && _server.ClientCount <= 0)
				{
					var (flag, message) = TryOpenViewerInBrowser();
					if (!flag)
					{
						ReportInternalWarning(message);
					}
				}
			}
			catch (OperationCanceledException)
			{
			}
		}

		internal static void EmitGodotLogError(string function, string file, int line, string code, string rationale, int errorType, string scriptBacktrace)
		{
			string text = $"Error occurred [{errorType}]: {rationale}\n{code}\n{file}:{line} @ {function}()";
			if (!string.IsNullOrWhiteSpace(scriptBacktrace))
