		}

		private static bool TryReadBracketPrefix(string text, out string value, out string remaining)
		{
			value = "";
			remaining = text;
			if (!text.StartsWith('['))
			{
				return false;
			}
			int num = text.IndexOf(']', 1);
			if (num <= 1)
			{
				return false;
			}
			value = text.Substring(1, num - 1);
			remaining = text.Substring(num + 1);
			return true;
		}

		private static int MapSeverityNumber(LogLevel level)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_001e: Expected I4, but got Unknown
			return (int)level switch
			{
				0 => 1, 
				2 => 5, 
				1 => 9, 
				3 => 9, 
				4 => 13, 
				5 => 17, 
				_ => 9, 
			};
		}

		private static string ToUnixNanoString(DateTimeOffset timestamp)
		{
			return ((timestamp.UtcTicks - DateTimeOffset.UnixEpoch.UtcTicks) * 100).ToString();
		}

		private static string? ResolveViewerAssetRoot()
		{
			string directoryName = Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location);
			if (string.IsNullOrWhiteSpace(directoryName))
			{
				return null;
			}
			return EnumerateViewerAssetRoots(directoryName).FirstOrDefault((string candidate) => File.Exists(Path.Combine(candidate, "index.html")));
		}

		private static IEnumerable<string> EnumerateViewerAssetRoots(string assemblyDir)
		{
			yield return Path.Combine(assemblyDir, "viewer");
			DirectoryInfo parent = new DirectoryInfo(assemblyDir).Parent;
			DirectoryInfo directoryInfo = parent?.Parent;
			if (parent != null && directoryInfo != null && string.Equals(parent.Name, "lib", StringComparison.OrdinalIgnoreCase))
			{
				yield return Path.Combine(directoryInfo.FullName, "viewer");
			}
			yield return Path.Combine(AppContext.BaseDirectory, "viewer");
		}

		private static void OnProcessExit(object? sender, EventArgs e)
		{
			Shutdown();
		}

		private static void Shutdown()
		{
			using (InitLock.EnterScope())
			{
				if (_initialized)
				{
					_cts?.Cancel();
					_server?.Dispose();
					Exception ex = TryDetachGodotLogListener();
					_cts?.Dispose();
					_server = null;
					_cts = null;
					_initialized = false;
					if (ex != null)
					{
						Console.Error.WriteLine($"[RitsuLib] Failed to detach the Godot log listener during shutdown: {ex}");
					}
				}
			}
		}

		private static Exception? CleanupAfterFailedStart()
		{
			_cts?.Cancel();
			_server?.Dispose();
			Exception result = TryDetachGodotLogListener();
			_cts?.Dispose();
			_server = null;
			_cts = null;
			_ring = null;
			_initialized = false;
			RitsuDebugLogRecord result2;
			while (Queue.TryDequeue(out result2))
			{
			}
			Volatile.Write(ref _queued, 0);
			return result;
		}

		private static void ConfigureGodotLogListener(bool enabled)
		{
			if (!enabled)
			{
				Exception ex = TryDetachGodotLogListener();
				if (ex != null)
				{
					throw new InvalidOperationException("Could not disable Godot log mirroring.", ex);
				}
			}
			else if (_godotLogListener == null)
			{
				RitsuDebugGodotLogListener ritsuDebugGodotLogListener = new RitsuDebugGodotLogListener();
				OS.AddLogger((Logger)(object)ritsuDebugGodotLogListener);
				_godotLogListener = ritsuDebugGodotLogListener;
			}
		}

		private static Exception? TryDetachGodotLogListener()
		{
			RitsuDebugGodotLogListener godotLogListener = _godotLogListener;
			if (godotLogListener == null)
			{
				return null;
			}
			try
			{
				OS.RemoveLogger((Logger)(object)godotLogListener);
				_godotLogListener = null;
				return null;
			}
			catch (Exception result)
			{
				return result;
			}
		}
	}
