	internal sealed class RitsuDebugLogRingBuffer(int capacity)
	{
		private readonly RitsuDebugLogRecord[] _items = new RitsuDebugLogRecord[Math.Max(128, capacity)];

		private readonly Lock _lock = new Lock();

		private int _count;

		private int _next;

		public int Capacity => _items.Length;

		public int Count
		{
			get
			{
				using (_lock.EnterScope())
				{
					return _count;
				}
			}
		}

		public void Add(RitsuDebugLogRecord record)
		{
			using (_lock.EnterScope())
			{
				_items[_next] = record;
				_next = (_next + 1) % _items.Length;
				if (_count < _items.Length)
				{
					_count++;
				}
			}
		}

		public RitsuDebugLogRecord[] Snapshot(int limit)
		{
			using (_lock.EnterScope())
			{
				int num = ((limit <= 0) ? _count : Math.Min(_count, limit));
				RitsuDebugLogRecord[] array = new RitsuDebugLogRecord[num];
				int num2 = (_next - _count + _items.Length) % _items.Length;
				num2 = (num2 + Math.Max(0, _count - num)) % _items.Length;
				for (int i = 0; i < num; i++)
				{
					array[i] = _items[(num2 + i) % _items.Length];
				}
				return array;
			}
		}
	}
	internal sealed class RitsuDebugLogSseClient
	{
		private const int MaxPendingEvents = 512;

		private readonly ConcurrentQueue<string> _pending = new ConcurrentQueue<string>();

		private readonly SemaphoreSlim _signal = new SemaphoreSlim(0);

		private int _count;

		public void Enqueue(string json)
		{
			if (Interlocked.Increment(ref _count) > 512)
			{
				Interlocked.Decrement(ref _count);
				return;
			}
			_pending.Enqueue(json);
			_signal.Release();
		}

		public async Task<string?> DequeueAsync(TimeSpan timeout, CancellationToken cancellationToken)
		{
			try
			{
				if (!(await _signal.WaitAsync(timeout, cancellationToken).ConfigureAwait(continueOnCapturedContext: false)))
				{
					return null;
				}
			}
			catch (OperationCanceledException)
			{
				return null;
			}
			if (!_pending.TryDequeue(out string result))
			{
				return null;
			}
			Interlocked.Decrement(ref _count);
			return result;
		}
	}
	internal sealed record RitsuDebugLogViewerCommandLineOptions(int? Port, int? PortFallbackCount, IReadOnlyList<string> Warnings);
	internal static class RitsuDebugLogViewerCommandLine
	{
		private static readonly string[] PortOptionNames = new string[2] { "--ritsulib-log-viewer-port", "--ritsulib-debug-log-viewer-port" };

		private static readonly string[] PortFallbackCountOptionNames = new string[2] { "--ritsulib-log-viewer-port-fallback-count", "--ritsulib-debug-log-viewer-port-fallback-count" };

		internal static RitsuDebugLogViewerCommandLineOptions ParseCurrentProcess()
		{
			RitsuDebugLogViewerCommandLineOptions ritsuDebugLogViewerCommandLineOptions = Parse(TryGetGodotCmdlineUserArgs());
			if (ritsuDebugLogViewerCommandLineOptions.Port.HasValue || ritsuDebugLogViewerCommandLineOptions.PortFallbackCount.HasValue || ritsuDebugLogViewerCommandLineOptions.Warnings.Count > 0)
			{
				return ritsuDebugLogViewerCommandLineOptions;
			}
			RitsuDebugLogViewerCommandLineOptions ritsuDebugLogViewerCommandLineOptions2 = Parse(TryGetGodotCmdlineArgs());
			if (ritsuDebugLogViewerCommandLineOptions2.Port.HasValue || ritsuDebugLogViewerCommandLineOptions2.PortFallbackCount.HasValue || ritsuDebugLogViewerCommandLineOptions2.Warnings.Count > 0)
			{
				return ritsuDebugLogViewerCommandLineOptions2;
			}
			List<string> list = new List<string>();
			list.AddRange(Environment.GetCommandLineArgs().Skip(1));
			return Parse(new <>z__ReadOnlyList<string>(list));
		}

		internal static RitsuDebugLogViewerCommandLineOptions Parse(IReadOnlyList<string> args)
		{
			int? port = null;
			int? portFallbackCount = null;
			List<string> list = new List<string>();
			for (int i = 0; i < args.Count; i++)
			{
				string optionName2;
				string value2;
				if (TryReadOptionValue(args, ref i, PortOptionNames, out string optionName, out string value))
				{
					if (TryParsePort(value, out var port2))
					{
						port = port2;
						continue;
					}
					list.Add($"Ignoring invalid {optionName} value '{value}'; expected a port from 1 to 65535.");
				}
				else if (TryReadOptionValue(args, ref i, PortFallbackCountOptionNames, out optionName2, out value2))
				{
					if (TryParsePortFallbackCount(value2, out var portFallbackCount2))
					{
						portFallbackCount = portFallbackCount2;
						continue;
					}
					list.Add($"Ignoring invalid {optionName2} value '{value2}'; expected a number from 0 to 100.");
				}
			}
			return new RitsuDebugLogViewerCommandLineOptions(port, portFallbackCount, list);
		}

		private static bool TryReadOptionValue(IReadOnlyList<string> args, ref int index, IReadOnlyList<string> optionNames, out string optionName, out string value)
		{
			string text = args[index];
			foreach (string optionName2 in optionNames)
			{
				if (string.Equals(text, optionName2, StringComparison.OrdinalIgnoreCase))
				{
					optionName = optionName2;
					value = ((index + 1 < args.Count) ? args[++index] : "");
					return true;
				}
				if (text.StartsWith(optionName2, StringComparison.OrdinalIgnoreCase) && text.Length > optionName2.Length && text[optionName2.Length] == '=')
				{
					optionName = optionName2;
					value = text.Substring(optionName2.Length + 1);
					return true;
				}
			}
			optionName = "";
			value = "";
			return false;
		}

		private static bool TryParsePort(string value, out int port)
		{
			if (int.TryParse(value, NumberStyles.None, CultureInfo.InvariantCulture, out port))
			{
				int num = port;
				if (num >= 1)
				{
					return num <= 65535;
				}
				return false;
			}
			return false;
		}

		private static bool TryParsePortFallbackCount(string value, out int portFallbackCount)
		{
			if (int.TryParse(value, NumberStyles.None, CultureInfo.InvariantCulture, out portFallbackCount))
			{
				int num = portFallbackCount;
				if (num >= 0)
				{
					return num <= 100;
				}
				return false;
			}
			return false;
		}

		private static string[] TryGetGodotCmdlineUserArgs()
		{
			try
			{
				return OS.GetCmdlineUserArgs();
			}
			catch (Exception)
			{
				return Array.Empty<string>();
			}
		}

		private static string[] TryGetGodotCmdlineArgs()
		{
			try
			{
				return OS.GetCmdlineArgs();
			}
			catch (Exception)
			{
				return Array.Empty<string>();
			}
		}
	}
