			Success,
			ConnectionClosed,
			RequestTimeout,
			RequestLineTooLong,
			HeadersTooLarge
		}

		private const int MaxConcurrentRequests = 64;

		private const int MaxHeaderBytes = 32768;

		private const int MaxHeaderCount = 100;

		private const int MaxHeaderLineBytes = 8192;

