		public void Start(int requestedPort, int fallbackCount)
		{
			int num = Math.Clamp(requestedPort, 1, 65535);
			int num2 = Math.Min(Math.Clamp(fallbackCount + 1, 1, 100), 65536 - num);
			Exception innerException = null;
			for (int i = 0; i < num2; i++)
			{
				int port = num + i;
				try
				{
					_listener = new TcpListener(LanAccessEnabled ? IPAddress.Any : IPAddress.Loopback, port);
					_listener.Start();
