		private async Task HandleClientAsync(TcpClient client)
		{
			using (client)
			{
				_ = 14;
				try
				{
					client.NoDelay = true;
					await using NetworkStream stream = client.GetStream();
					RequestHeadReadResult requestHeadReadResult = await ReadRequestHeadAsync(stream).ConfigureAwait(continueOnCapturedContext: false);
					switch (requestHeadReadResult.Status)
					{
					case RequestHeadStatus.RequestTimeout:
						await WriteTextResponseAsync(stream, 408, "Request Timeout", "Request headers timed out.").ConfigureAwait(continueOnCapturedContext: false);
						return;
					case RequestHeadStatus.RequestLineTooLong:
						await WriteTextResponseAsync(stream, 414, "URI Too Long", "Request line is too long.").ConfigureAwait(continueOnCapturedContext: false);
						return;
					case RequestHeadStatus.HeadersTooLarge:
						await WriteTextResponseAsync(stream, 431, "Request Header Fields Too Large", "Request headers are too large.").ConfigureAwait(continueOnCapturedContext: false);
						return;
					case RequestHeadStatus.ConnectionClosed:
						return;
					}
					string[] array = requestHeadReadResult.RequestLine.Split(' ');
					if (array.Length < 2 || !string.Equals(array[0], "GET", StringComparison.OrdinalIgnoreCase))
					{
						await WriteTextResponseAsync(stream, 405, "Method Not Allowed", "Only GET is supported.").ConfigureAwait(continueOnCapturedContext: false);
						return;
					}
					string text = array[1];
					string text2 = text;
					string query = "";
					int num = text.IndexOf('?', StringComparison.Ordinal);
					if (num >= 0)
					{
						text2 = text.Substring(0, num);
						query = text.Substring(num + 1);
					}
					if (IsStaticAssetRequest(text2))
					{
						if (!(await TryWriteStaticAssetAsync(stream, text2).ConfigureAwait(continueOnCapturedContext: false)))
						{
							await WriteTextResponseAsync(stream, 404, "Not Found", "Static asset not found.").ConfigureAwait(continueOnCapturedContext: false);
						}
						return;
					}
					if (!IsAuthorized(query))
					{
						await WriteTextResponseAsync(stream, 401, "Unauthorized", "Invalid debug viewer token.").ConfigureAwait(continueOnCapturedContext: false);
						return;
					}
					switch (text2)
					{
					case "/":
						if (!(await TryWriteIndexAsync(stream).ConfigureAwait(continueOnCapturedContext: false)))
						{
							await WriteTextResponseAsync(stream, 503, "Service Unavailable", "RitsuLib debug log viewer assets are unavailable. Build and package components/viewer/index.html.").ConfigureAwait(continueOnCapturedContext: false);
						}
						break;
					case "/api/status":
						await WriteJsonResponseAsync(stream, _statusProvider()).ConfigureAwait(continueOnCapturedContext: false);
						break;
					case "/api/history":
						await WriteJsonResponseAsync(stream, _historyProvider(ParseLimit(query))).ConfigureAwait(continueOnCapturedContext: false);
						break;
					case "/api/events":
						await HandleEventsAsync(stream).ConfigureAwait(continueOnCapturedContext: false);
						break;
					default:
						await WriteTextResponseAsync(stream, 404, "Not Found", "Not found.").ConfigureAwait(continueOnCapturedContext: false);
						break;
					}
					return;
				}
				catch (OperationCanceledException) when (_shutdownToken.IsCancellationRequested)
				{
				}
				catch (Exception ex2) when (RitsuLibExceptionPolicy.IsRecoverable(ex2) && IsClientDisconnect(ex2))
				{
				}
				catch (Exception ex3) when (RitsuLibExceptionPolicy.IsRecoverable(ex3))
				{
					RitsuDebugLogPipeline.ReportInternalWarning("Client request failed: " + ex3.Message);
				}
			}
		}

		private async Task<RequestHeadReadResult> ReadRequestHeadAsync(NetworkStream stream)
		{
			using CancellationTokenSource timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(_shutdownToken);
			timeoutCts.CancelAfter(RequestHeaderTimeout);
			try
			{
				byte[] buffer = new byte[2048];
				byte[] requestLineBytes = new byte[8192];
				string requestLine = null;
				int requestLineLength = 0;
				int headerBytes = 0;
				int headerCount = 0;
				int headerLineBytes = 0;
				bool headerLineEndsWithCarriageReturn = false;
				bool readingRequestLine = true;
				while (true)
				{
					int num = await stream.ReadAsync(buffer, timeoutCts.Token).ConfigureAwait(continueOnCapturedContext: false);
					if (num == 0)
					{
						break;
					}
					for (int i = 0; i < num; i++)
					{
						byte b = buffer[i];
						if (readingRequestLine)
						{
							if (b == 10)
							{
								if (requestLineLength > 0 && requestLineBytes[requestLineLength - 1] == 13)
								{
									requestLineLength--;
								}
								requestLine = Encoding.ASCII.GetString(requestLineBytes, 0, requestLineLength);
								if (string.IsNullOrWhiteSpace(requestLine))
								{
									return new RequestHeadReadResult(RequestHeadStatus.ConnectionClosed);
								}
								readingRequestLine = false;
							}
							else
							{
								if (requestLineLength >= 8192)
								{
									return new RequestHeadReadResult(RequestHeadStatus.RequestLineTooLong);
								}
								requestLineBytes[requestLineLength++] = b;
							}
							continue;
						}
						headerBytes++;
						if (headerBytes > 32768)
						{
							return new RequestHeadReadResult(RequestHeadStatus.HeadersTooLarge);
						}
						if (b != 10)
						{
							headerLineBytes++;
							if (headerLineBytes > 8192)
							{
								return new RequestHeadReadResult(RequestHeadStatus.HeadersTooLarge);
							}
							headerLineEndsWithCarriageReturn = b == 13;
							continue;
						}
						int num2 = headerLineBytes;
						if (headerLineEndsWithCarriageReturn)
						{
							num2--;
						}
						if (num2 == 0)
						{
							return new RequestHeadReadResult(RequestHeadStatus.Success, requestLine);
						}
						headerCount++;
						if (headerCount > 100)
						{
							return new RequestHeadReadResult(RequestHeadStatus.HeadersTooLarge);
						}
						headerLineBytes = 0;
						headerLineEndsWithCarriageReturn = false;
					}
				}
				return new RequestHeadReadResult(RequestHeadStatus.ConnectionClosed);
			}
			catch (OperationCanceledException) when (!_shutdownToken.IsCancellationRequested && timeoutCts.IsCancellationRequested)
			{
				return new RequestHeadReadResult(RequestHeadStatus.RequestTimeout);
			}
		}

		private async Task HandleEventsAsync(Stream stream)
		{
			RitsuDebugLogSseClient client = new RitsuDebugLogSseClient();
			_clients.TryAdd(client, 0);
			try
			{
				await WriteUtf8Async(stream, "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream; charset=utf-8\r\nCache-Control: no-cache\r\nConnection: keep-alive\r\nX-Accel-Buffering: no\r\n\r\n").ConfigureAwait(continueOnCapturedContext: false);
				await WriteSseEventAsync(stream, "session", JsonSerializer.Serialize(_statusProvider(), JsonOptions)).ConfigureAwait(continueOnCapturedContext: false);
				await stream.FlushAsync(_shutdownToken).ConfigureAwait(continueOnCapturedContext: false);
				while (!_shutdownToken.IsCancellationRequested)
				{
					string text = await client.DequeueAsync(TimeSpan.FromSeconds(15L), _shutdownToken).ConfigureAwait(continueOnCapturedContext: false);
					if (text != null)
					{
						await WriteSseEventAsync(stream, "log", text).ConfigureAwait(continueOnCapturedContext: false);
					}
					else
					{
						await WriteUtf8Async(stream, ": keepalive\n\n").ConfigureAwait(continueOnCapturedContext: false);
					}
					await stream.FlushAsync(_shutdownToken).ConfigureAwait(continueOnCapturedContext: false);
				}
			}
			finally
			{
				_clients.TryRemove(client, out var _);
			}
		}

		private bool IsAuthorized(string query)
		{
			return string.Equals(GetQueryValue(query, "token"), _token, StringComparison.Ordinal);
		}

		private static bool IsStaticAssetRequest(string path)
		{
			if (!string.Equals(path, "/", StringComparison.Ordinal))
			{
				return !path.StartsWith("/api/", StringComparison.OrdinalIgnoreCase);
			}
			return false;
		}

		private async Task<bool> TryWriteIndexAsync(Stream stream)
		{
			if (string.IsNullOrWhiteSpace(_assetRoot))
			{
				return false;
			}
			string path = Path.Combine(_assetRoot, "index.html");
			if (!File.Exists(path))
			{
				return false;
			}
			await WriteFileResponseAsync(stream, path, "text/html; charset=utf-8").ConfigureAwait(continueOnCapturedContext: false);
			return true;
		}

		private async Task<bool> TryWriteStaticAssetAsync(Stream stream, string path)
		{
			if (string.IsNullOrWhiteSpace(_assetRoot))
			{
				return false;
			}
			string text = Uri.UnescapeDataString(path.TrimStart('/')).Replace('/', Path.DirectorySeparatorChar);
			if (text.Length == 0 || text.Split(Path.DirectorySeparatorChar).Any((string x) => x == ".."))
			{
				return false;
			}
			string fullPath = Path.GetFullPath(Path.Combine(_assetRoot, text));
			string value = Path.GetFullPath(_assetRoot).TrimEnd(new char[2]
			{
				Path.DirectorySeparatorChar,
				Path.AltDirectorySeparatorChar
			}) + Path.DirectorySeparatorChar;
			if (!fullPath.StartsWith(value, StringComparison.OrdinalIgnoreCase) || !File.Exists(fullPath))
			{
				return false;
			}
			await WriteFileResponseAsync(stream, fullPath, ResolveContentType(fullPath)).ConfigureAwait(continueOnCapturedContext: false);
			return true;
		}

		private static int ParseLimit(string query)
		{
			if (!int.TryParse(GetQueryValue(query, "limit"), out var result))
			{
				return 5000;
			}
			return Math.Clamp(result, 1, 20000);
		}

		private string BuildUrl(string host)
		{
			return $"http://{host}:{Port}/?token={Uri.EscapeDataString(_token)}";
		}

		private IReadOnlyList<string> GetLanUrls()
		{
			if (Port <= 0)
			{
				return Array.Empty<string>();
			}
			try
			{
				List<string> list = new List<string>();
				list.AddRange((from address in Dns.GetHostAddresses(Dns.GetHostName()).Where(IsUsableLanAddress)
					select BuildUrl(address.ToString())).Distinct<string>(StringComparer.OrdinalIgnoreCase));
				return new <>z__ReadOnlyList<string>(list);
			}
			catch (Exception ex) when (((ex is SocketException || ex is InvalidOperationException) ? 1 : 0) != 0)
			{
				RitsuDebugLogPipeline.ReportInternalWarning("Could not enumerate LAN addresses: " + ex.Message);
				return Array.Empty<string>();
			}
		}

		private static bool IsUsableLanAddress(IPAddress address)
		{
			if (address.AddressFamily != AddressFamily.InterNetwork || IPAddress.IsLoopback(address))
			{
				return false;
			}
			byte[] addressBytes = address.GetAddressBytes();
			if (addressBytes != null && addressBytes.Length == 4)
			{
				byte b = addressBytes[0];
				if (b != 0)
				{
					if (b != 169 || addressBytes[1] != 254)
					{
						goto IL_0052;
					}
				}
				else if (addressBytes[1] != 0 || addressBytes[2] != 0 || addressBytes[3] != 0)
				{
					goto IL_0052;
				}
				return false;
			}
			goto IL_0052;
			IL_0052:
			return true;
		}

		private static string? GetQueryValue(string query, string key)
		{
			return (from pair in query.Split('&', StringSplitOptions.RemoveEmptyEntries)
				let eq = pair.IndexOf('=', StringComparison.Ordinal)
				let rawKey = (eq >= 0) ? pair.Substring(0, eq) : pair
				where string.Equals(Uri.UnescapeDataString(rawKey), key, StringComparison.Ordinal)
				select (eq < 0) ? "" : pair.Substring(eq + 1) into rawValue
				select Uri.UnescapeDataString(rawValue.Replace("+", "%20", StringComparison.Ordinal))).FirstOrDefault();
		}

		private static Task WriteJsonResponseAsync(Stream stream, object payload)
		{
			return WriteResponseAsync(stream, 200, "OK", "application/json; charset=utf-8", JsonSerializer.Serialize(payload, JsonOptions));
		}

		private static async Task WriteFileResponseAsync(Stream stream, string path, string contentType)
		{
			await WriteBytesResponseAsync(stream, 200, "OK", contentType, await File.ReadAllBytesAsync(path).ConfigureAwait(continueOnCapturedContext: false)).ConfigureAwait(continueOnCapturedContext: false);
		}

		private static Task WriteTextResponseAsync(Stream stream, int status, string reason, string text)
		{
			return WriteResponseAsync(stream, status, reason, "text/plain; charset=utf-8", text);
		}

		private static async Task WriteResponseAsync(Stream stream, int status, string reason, string contentType, string body)
		{
			await WriteBytesResponseAsync(stream, status, reason, contentType, Encoding.UTF8.GetBytes(body)).ConfigureAwait(continueOnCapturedContext: false);
		}

		private static async Task WriteBytesResponseAsync(Stream stream, int status, string reason, string contentType, byte[] bodyBytes)
		{
			await WriteUtf8Async(stream, $"HTTP/1.1 {status} {reason}\r\nContent-Type: {contentType}\r\nContent-Length: {bodyBytes.Length}\r\n" + "Cache-Control: no-cache\r\nConnection: close\r\n\r\n").ConfigureAwait(continueOnCapturedContext: false);
			await stream.WriteAsync(bodyBytes).ConfigureAwait(continueOnCapturedContext: false);
		}

		private static string ResolveContentType(string path)
		{
			switch (Path.GetExtension(path).ToLowerInvariant())
			{
			case ".html":
				return "text/html; charset=utf-8";
			case ".js":
				return "text/javascript; charset=utf-8";
			case ".css":
				return "text/css; charset=utf-8";
			case ".json":
				return "application/json; charset=utf-8";
			case ".svg":
				return "image/svg+xml";
			case ".png":
				return "image/png";
			case ".jpeg":
			case ".jpg":
				return "image/jpeg";
			case ".webp":
				return "image/webp";
			case ".ico":
				return "image/x-icon";
			case ".woff":
				return "font/woff";
			case ".woff2":
				return "font/woff2";
			default:
				return "application/octet-stream";
			}
		}

		private static Task WriteUtf8Async(Stream stream, string text)
		{
			return stream.WriteAsync(Encoding.UTF8.GetBytes(text)).AsTask();
		}

		private static async Task WriteSseEventAsync(Stream stream, string eventName, string json)
		{
			await WriteUtf8Async(stream, "event: ").ConfigureAwait(continueOnCapturedContext: false);
			await WriteUtf8Async(stream, eventName).ConfigureAwait(continueOnCapturedContext: false);
			await WriteUtf8Async(stream, "\n").ConfigureAwait(continueOnCapturedContext: false);
			await WriteUtf8Async(stream, "data: ").ConfigureAwait(continueOnCapturedContext: false);
			await WriteUtf8Async(stream, json).ConfigureAwait(continueOnCapturedContext: false);
			await WriteUtf8Async(stream, "\n\n").ConfigureAwait(continueOnCapturedContext: false);
		}

		private static bool IsClientDisconnect(Exception ex)
		{
			if (!(ex is IOException))
			{
				if (!(ex is ObjectDisposedException))
				{
					if (ex is SocketException { SocketErrorCode: var socketErrorCode } && ((uint)(socketErrorCode - 10053) <= 1u || socketErrorCode == SocketError.Shutdown))
					{
						return true;
					}
					if (ex.InnerException != null)
					{
						return IsClientDisconnect(ex.InnerException);
					}
					return false;
				}
				return true;
			}
			return true;
		}
	}
}
namespace STS2RitsuLib.Diagnostics.DevConsole
{
	/// <summary>
	///     <para xml:lang="en">
	///         Resolves ancient-event option tokens and localized titles for developer-console autocomplete.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为开发者控制台自动补全解析先古之民事件选项标记及其本地化标题。
	///     </para>
	/// </summary>
	internal static class DevConsoleAncientChoiceAutocompleteCatalog
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Returns the display title of <paramref name="choiceToken" /> in the specified ancient event.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回指定先古之民事件中 <paramref name="choiceToken" /> 的显示标题。
		///     </para>
		/// </summary>
		public static string? TryGetDisplayTitle(string ancientEntryId, string choiceToken)
		{
			EventOption val = TryFindOption(ancientEntryId, choiceToken);
			if (val == null)
			{
				return null;
			}
			string text = val.Title.GetFormattedText()?.Trim();
			if (string.IsNullOrWhiteSpace(text))
			{
				RelicModel relic = val.Relic;
				if (relic == null)
				{
					return null;
				}
				return relic.Title.GetFormattedText()?.Trim();
			}
			return text;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether <paramref name="partial" /> matches the option title, the linked relic's ID or
		///         title, or an enabled search expansion of either title.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <paramref name="partial" /> 是否匹配选项标题、关联遗物的 ID 或标题，或两个标题的已启用搜索扩展。
		///     </para>
		/// </summary>
		public static bool MatchesLocalizedTitle(string ancientEntryId, string choiceToken, string partial)
		{
			if (string.IsNullOrWhiteSpace(partial))
			{
				return true;
			}
			EventOption val = TryFindOption(ancientEntryId, choiceToken);
			if (val == null)
			{
				return false;
			}
			string text = partial.Trim();
			if (DevConsoleAutocompleteMatchExtensions.MatchesLocalizedText(val.Title.GetFormattedText()?.Trim(), text))
			{
				return true;
			}
			if (val.Relic == null)
			{
				return false;
			}
			RelicModel relic = val.Relic;
			if (((AbstractModel)relic).Id.Entry.Contains(text, StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}
			return DevConsoleAutocompleteMatchExtensions.MatchesLocalizedText(relic.Title.GetFormattedText()?.Trim(), text);
		}

		private static EventOption? TryFindOption(string ancientEntryId, string choiceToken)
		{
			if (string.IsNullOrWhiteSpace(ancientEntryId) || string.IsNullOrWhiteSpace(choiceToken))
			{
				return null;
			}
			AncientEventModel val = TryGetAncient(ancientEntryId);
			if (val == null)
			{
				return null;
			}
			return val.AllPossibleOptions.FirstOrDefault((EventOption option) => option.TextKey.Split('.').Last().Equals(choiceToken, StringComparison.OrdinalIgnoreCase) || option.TextKey.Contains(choiceToken, StringComparison.OrdinalIgnoreCase));
		}

		private static AncientEventModel? TryGetAncient(string ancientEntryId)
		{
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_001f: Expected O, but got Unknown
			EventModel byIdOrNull = ModelDb.GetByIdOrNull<EventModel>(new ModelId(ModelDb.GetCategory(typeof(EventModel)), ancientEntryId.ToUpperInvariant()));
			return (AncientEventModel?)(object)((byIdOrNull is AncientEventModel) ? byIdOrNull : null);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides the public API for registering and applying developer-console autocomplete enhancements.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供注册和应用开发者控制台自动补全增强功能的公共 API。
	///     </para>
	/// </summary>
	public static class DevConsoleAutocomplete
	{
		/// <summary>
		///     <para xml:lang="en">Registers a command-argument autocomplete binding.</para>
		///     <para xml:lang="zh-CN">注册命令参数的自动补全绑定。</para>
		/// </summary>
		public static void Register(DevConsoleAutocompleteBinding binding)
		{
			DevConsoleAutocompleteRegistry.Register(binding);
		}

		/// <summary>
		///     <para xml:lang="en">Registers enhancements for a specific argument index of a command.</para>
		///     <para xml:lang="zh-CN">为命令的指定参数索引注册增强功能。</para>
		/// </summary>
		public static void Register(string commandName, int argumentIndex, DevConsoleAutocompleteEnhancements enhancements, Func<DevConsoleAutocompleteContext, bool>? appliesWhen = null)
		{
			DevConsoleAutocompleteRegistry.Register(commandName, argumentIndex, enhancements, appliesWhen);
		}

		/// <summary>
		///     <para xml:lang="en">Registers enhancements selected by <paramref name="appliesWhen" />.</para>
		///     <para xml:lang="zh-CN">注册由 <paramref name="appliesWhen" /> 选择的增强功能。</para>
		/// </summary>
		public static void Register(string commandName, DevConsoleAutocompleteEnhancements enhancements, Func<DevConsoleAutocompleteContext, bool> appliesWhen)
		{
			DevConsoleAutocompleteRegistry.Register(commandName, enhancements, appliesWhen);
		}

		/// <summary>
		///     <para xml:lang="en">Resolves the enhancements applicable to a completion request.</para>
		///     <para xml:lang="zh-CN">解析适用于补全请求的增强功能。</para>
		/// </summary>
		public static DevConsoleAutocompleteEnhancements Resolve(AbstractConsoleCmd command, string[] completedArgs, int argumentIndex)
		{
			return DevConsoleAutocompleteRegistry.Resolve(command, completedArgs, argumentIndex);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Builds a match-predicate chain for mod commands that call <c>CompleteArgument</c> directly.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为直接调用 <c>CompleteArgument</c> 的模组命令构建匹配谓词链。
		///     </para>
		/// </summary>
		public static Func<string, string, bool>? BuildMatchPredicate(AbstractConsoleCmd command, string[] completedArgs, Func<string, string, bool>? inner = null)
		{
			return DevConsoleAutocompleteEnhancer.BuildMatchPredicate(Resolve(command, completedArgs, completedArgs.Length), inner, completedArgs);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Applies result enhancements for a mod command that calls <c>CompleteArgument</c> directly.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为直接调用 <c>CompleteArgument</c> 的模组命令应用结果增强功能。
		///     </para>
		/// </summary>
		public static void ApplyToResult(AbstractConsoleCmd command, string[] completedArgs, ref CompletionResult result)
		{
			DevConsoleAutocompleteEnhancer.ApplyToResult(ref result, Resolve(command, completedArgs, result.ArgumentIndex), completedArgs);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Binds autocomplete enhancements to a console-command argument.</para>
	///     <para xml:lang="zh-CN">将自动补全增强功能绑定到控制台命令参数。</para>
	/// </summary>
	public sealed class DevConsoleAutocompleteBinding
	{
		/// <summary>
		///     <para xml:lang="en">The developer-console command name, such as <c>card</c>.</para>
		///     <para xml:lang="zh-CN">开发者控制台命令名称，例如 <c>card</c>。</para>
		/// </summary>
		public required string CommandName { get; init; }

		/// <summary>
		///     <para xml:lang="en">The argument index to enhance, or <see langword="null" /> for predicate-only matching.</para>
		///     <para xml:lang="zh-CN">要增强的参数索引；为 <see langword="null" /> 时仅使用谓词匹配。</para>
		/// </summary>
		public int? ArgumentIndex { get; init; }

		/// <summary>
		///     <para xml:lang="en">An optional predicate evaluated against the current completion context.</para>
		///     <para xml:lang="zh-CN">根据当前补全上下文计算的可选谓词。</para>
		/// </summary>
		public Func<DevConsoleAutocompleteContext, bool>? AppliesWhen { get; init; }

		/// <summary>
		///     <para xml:lang="en">The enhancements applied when the binding matches.</para>
		///     <para xml:lang="zh-CN">绑定匹配时应用的增强功能。</para>
		/// </summary>
		public DevConsoleAutocompleteEnhancements Enhancements { get; init; }
	}
	/// <summary>
	///     <para xml:lang="en">Provides candidate sets corresponding to the game's developer-console commands.</para>
	///     <para xml:lang="zh-CN">提供与游戏开发者控制台命令对应的候选项集合。</para>
	/// </summary>
	internal static class DevConsoleAutocompleteCandidateSources
	{
		public static IEnumerable<string> GetCardEntryIds()
		{
			return ModelDb.AllCards.Select((CardModel c) => ((AbstractModel)c).Id.Entry);
		}

		public static IEnumerable<string> GetPotionEntryIds()
		{
			return ModelDb.AllPotions.Select((PotionModel p) => ((AbstractModel)p).Id.Entry);
		}

		public static IEnumerable<string> GetRelicEntryIds()
		{
			return ModelDb.AllRelics.Select((RelicModel r) => ((AbstractModel)r).Id.Entry);
		}

		public static IEnumerable<string> GetEventEntryIds()
		{
			return (from e in ModelDb.AllEvents.Concat((IEnumerable<EventModel>)ModelDb.AllAncients)
				select ((AbstractModel)e).Id.Entry).Distinct();
		}

		public static IEnumerable<string> GetEncounterEntryIds()
		{
			return ModelDb.AllEncounters.Select((EncounterModel e) => ((AbstractModel)e).Id.Entry);
		}

		public static IEnumerable<string> GetAfflictionEntryIds()
		{
			return ModelDb.DebugAfflictions.Select((AfflictionModel a) => ((AbstractModel)a).Id.Entry);
		}

		public static IEnumerable<string> GetEnchantmentEntryIds()
		{
			return ModelDb.DebugEnchantments.Select((EnchantmentModel e) => ((AbstractModel)e).Id.Entry);
		}

		/// <summary>
		///     <para xml:lang="en">Returns the same model set used by the game's <c>power</c> command autocomplete.</para>
		///     <para xml:lang="zh-CN">返回游戏 <c>power</c> 命令自动补全所使用的同一模型集合。</para>
		/// </summary>
		public static IEnumerable<string> GetPowerEntryIds()
		{
			return from p in ModelDb.AllAbstractModelSubtypes.Where((Type t) => t.IsSubclassOf(typeof(PowerModel))).Select((Func<Type, PowerModel>)ModelDb.DebugPower)
				select ((AbstractModel)p).Id.Entry;
		}

		public static IEnumerable<string> GetMonsterEntryIds()
		{
			return ModelDb.Monsters.Select((MonsterModel m) => ((AbstractModel)m).Id.Entry);
		}

		public static IEnumerable<string> GetEpochEntryIds()
		{
			return EpochModel.AllEpochIds;
		}

		public static IEnumerable<(string EntryId, LocString Title)> EnumerateLocalizedModelTitles()
		{
			foreach (CardModel allCard in ModelDb.AllCards)
			{
				yield return GetTitleCandidate((AbstractModel)(object)allCard);
			}
			foreach (PotionModel allPotion in ModelDb.AllPotions)
			{
				yield return GetTitleCandidate((AbstractModel)(object)allPotion);
			}
			foreach (RelicModel allRelic in ModelDb.AllRelics)
			{
				yield return GetTitleCandidate((AbstractModel)(object)allRelic);
			}
			foreach (EncounterModel allEncounter in ModelDb.AllEncounters)
			{
				yield return GetTitleCandidate((AbstractModel)(object)allEncounter);
			}
			foreach (AfflictionModel debugAffliction in ModelDb.DebugAfflictions)
			{
				yield return GetTitleCandidate((AbstractModel)(object)debugAffliction);
			}
			foreach (EnchantmentModel debugEnchantment in ModelDb.DebugEnchantments)
			{
				yield return GetTitleCandidate((AbstractModel)(object)debugEnchantment);
			}
			foreach (AncientEventModel allAncient in ModelDb.AllAncients)
			{
				yield return GetTitleCandidate((AbstractModel)(object)allAncient);
			}
			foreach (EventModel allEvent in ModelDb.AllEvents)
			{
				yield return GetTitleCandidate((AbstractModel)(object)allEvent);
			}
			foreach (ActModel act in ModelDb.Acts)
			{
				yield return GetTitleCandidate((AbstractModel)(object)act);
			}
			foreach (Type item in ModelDb.AllAbstractModelSubtypes.Where((Type t) => t.IsSubclassOf(typeof(PowerModel))))
			{
				PowerModel model = ModelDb.DebugPower(item);
				yield return GetTitleCandidate((AbstractModel)(object)model);
			}
			foreach (MonsterModel monster in ModelDb.Monsters)
			{
				yield return GetTitleCandidate((AbstractModel)(object)monster);
			}
			foreach (string allEpochId in EpochModel.AllEpochIds)
			{
				yield return (EntryId: allEpochId, Title: new LocString("epochs", allEpochId + ".title"));
			}
		}

		private static (string EntryId, LocString Title) GetTitleCandidate(AbstractModel model)
		{
			return (EntryId: model.Id.Entry, Title: ResolveTitleForAutocomplete(model));
		}

		private static LocString ResolveTitleForAutocomplete(AbstractModel model, HashSet<Type>? visitedModelTypes = null)
		{
			ITemporaryPower val = (ITemporaryPower)(object)((model is ITemporaryPower) ? model : null);
			if (val == null)
			{
				return ResolveOwnTitleForAutocomplete(model);
			}
			if (visitedModelTypes == null)
			{
				visitedModelTypes = new HashSet<Type>();
			}
			if (!visitedModelTypes.Add(((object)model).GetType()))
			{
				return DefaultTitleForAutocomplete(model);
			}
			try
			{
				AbstractModel originModel = val.OriginModel;
				return (originModel == model) ? DefaultTitleForAutocomplete(model) : ResolveTitleForAutocomplete(originModel, visitedModelTypes);
			}
			catch
			{
				return DefaultTitleForAutocomplete(model);
			}
		}

		private static LocString ResolveOwnTitleForAutocomplete(AbstractModel model)
		{
			try
			{
				LocString title;
				return (LocString)(model.TryResolveTitle(out title) ? ((object)title) : ((object)DefaultTitleForAutocomplete(model)));
			}
			catch
			{
				return DefaultTitleForAutocomplete(model);
			}
		}

		private static LocString DefaultTitleForAutocomplete(AbstractModel model)
		{
			return model.CreateDefaultTitleLocString();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Describes a developer-console <see cref="M:MegaCrit.Sts2.Core.DevConsole.ConsoleCommands.AbstractConsoleCmd.CompleteArgument(System.Collections.Generic.IEnumerable{System.String},System.String[],System.String,MegaCrit.Sts2.Core.DevConsole.CompletionType,System.Func{System.String,System.String,System.Boolean})" /> invocation.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         描述开发者控制台对 <see cref="M:MegaCrit.Sts2.Core.DevConsole.ConsoleCommands.AbstractConsoleCmd.CompleteArgument(System.Collections.Generic.IEnumerable{System.String},System.String[],System.String,MegaCrit.Sts2.Core.DevConsole.CompletionType,System.Func{System.String,System.String,System.Boolean})" /> 的调用。
	///     </para>
	/// </summary>
	public sealed class DevConsoleAutocompleteContext
	{
		/// <summary>
		///     <para xml:lang="en">The console command producing completions.</para>
		///     <para xml:lang="zh-CN">生成补全结果的控制台命令。</para>
		/// </summary>
		public AbstractConsoleCmd Command { get; }

		/// <summary>
		///     <para xml:lang="en">The arguments preceding the token being completed.</para>
		///     <para xml:lang="zh-CN">待补全标记之前已有的参数。</para>
		/// </summary>
		public IReadOnlyList<string> CompletedArgs { get; }

		/// <summary>
		///     <para xml:lang="en">The zero-based index of the argument being completed.</para>
		///     <para xml:lang="zh-CN">待补全参数的从零开始索引。</para>
		/// </summary>
		public int ArgumentIndex { get; }

		/// <summary>
		///     <para xml:lang="en">The developer-console command name.</para>
		///     <para xml:lang="zh-CN">开发者控制台命令名称。</para>
		/// </summary>
		public string CommandName => Command.CmdName;

		/// <summary>
		///     <para xml:lang="en">Creates a context for an autocomplete request.</para>
		///     <para xml:lang="zh-CN">创建自动补全请求的上下文。</para>
		/// </summary>
		public DevConsoleAutocompleteContext(AbstractConsoleCmd command, string[] completedArgs, int argumentIndex)
		{
			Command = command ?? throw new ArgumentNullException("command");
			ArgumentNullException.ThrowIfNull(completedArgs, "completedArgs");
			ArgumentOutOfRangeException.ThrowIfNegative(argumentIndex, "argumentIndex");
			CompletedArgs = new global::<>z__ReadOnlyArray<string>(completedArgs.ToArray());
			ArgumentIndex = argumentIndex;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides reusable predicates for autocomplete binding registration.</para>
	///     <para xml:lang="zh-CN">提供自动补全绑定注册所需的可复用谓词。</para>
	/// </summary>
	public static class DevConsoleAutocompleteContextPredicates
	{
		/// <summary>
		///     <para xml:lang="en">Matches the first argument when no preceding arguments are present.</para>
		///     <para xml:lang="zh-CN">匹配不存在前置参数时的第一个参数。</para>
		/// </summary>
		public static bool IsFirstArgument(DevConsoleAutocompleteContext context)
		{
			if (context != null && context.ArgumentIndex == 0)
			{
				IReadOnlyList<string> completedArgs = context.CompletedArgs;
				if (completedArgs != null)
				{
					return completedArgs.Count == 0;
				}
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Matches the second argument when exactly one preceding argument is present.</para>
		///     <para xml:lang="zh-CN">匹配恰有一个前置参数时的第二个参数。</para>
		/// </summary>
		public static bool IsSecondArgument(DevConsoleAutocompleteContext context)
		{
			if (context != null && context.ArgumentIndex == 1)
			{
				IReadOnlyList<string> completedArgs = context.CompletedArgs;
				if (completedArgs != null)
				{
					return completedArgs.Count == 1;
				}
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Matches an <c>ancient</c> option token following the ancient-event ID.</para>
		///     <para xml:lang="zh-CN">匹配 <c>ancient</c> 命令中先古之民事件 ID 之后的选项标记。</para>
		/// </summary>
		public static bool IsAncientChoiceArgument(DevConsoleAutocompleteContext context)
		{
			if (!context.CommandName.Equals("ancient", StringComparison.OrdinalIgnoreCase))
			{
				return false;
			}
			if (context != null && context.ArgumentIndex == 1)
			{
				IReadOnlyList<string> completedArgs = context.CompletedArgs;
				if (completedArgs != null)
				{
					return completedArgs.Count == 1;
				}
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Matches a relic ID used alone or after <c>add</c> or <c>remove</c> in the <c>relic</c> command.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         匹配 <c>relic</c> 命令中单独使用或位于 <c>add</c>、<c>remove</c> 之后的遗物 ID。
		///     </para>
		/// </summary>
		public static bool IsRelicIdArgument(DevConsoleAutocompleteContext context)
		{
			if (IsFirstArgument(context))
			{
				return true;
			}
			if (context.ArgumentIndex != 1 || context.CompletedArgs.Count != 1)
			{
				return false;
			}
			string text = context.CompletedArgs[0];
			if (!text.Equals("add", StringComparison.OrdinalIgnoreCase))
			{
				return text.Equals("remove", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Matches trailing <c>unlock</c> arguments that identify discovery entries.</para>
		///     <para xml:lang="zh-CN">匹配用于标识解锁条目的 <c>unlock</c> 尾随参数。</para>
		/// </summary>
		public static bool IsUnlockDiscoveryIdArgument(DevConsoleAutocompleteContext context)
		{
			if (context.ArgumentIndex < 1 || context.CompletedArgs.Count < 1)
			{
				return false;
			}
			return DevConsoleUnlockAutocompleteSources.SupportsDiscoveryIds(context.CompletedArgs[0]);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Registers built-in autocomplete bindings aligned with the game's command argument positions.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         注册与游戏命令参数位置一致的内置自动补全绑定。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Commands whose completion values are not model IDs retain their original completion behavior. This
	///         includes content-type names, room types, numeric indices, fixed option lists, and subcommand selectors.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         补全值不是模型 ID 的命令会保留原有补全行为，包括内容类型名称、房间类型、数字索引、固定选项列表和
	///         子命令选择项。
	///     </para>
	/// </remarks>
	internal static class DevConsoleAutocompleteDefaults
	{
		public static void Register()
		{
			RegisterModelEntryIdFirstArgument("power", "afflict", "ancient", "card", "enchant", "event", "fight", "potion", "remove_card");
			RegisterPileNameSecondArgument("card", "remove_card");
			DevConsoleAutocompleteRegistry.Register("ancient", DevConsoleAutocompleteEnhancements.AncientChoice, DevConsoleAutocompleteContextPredicates.IsAncientChoiceArgument);
			DevConsoleAutocompleteRegistry.Register("relic", DevConsoleAutocompleteEnhancements.RitsuLibModEntryId, DevConsoleAutocompleteContextPredicates.IsRelicIdArgument);
			DevConsoleAutocompleteRegistry.Register("unlock", DevConsoleAutocompleteEnhancements.RitsuLibModEntryId, DevConsoleAutocompleteContextPredicates.IsUnlockDiscoveryIdArgument);
		}

		private static void RegisterModelEntryIdFirstArgument(params string[] commandNames)
		{
			for (int i = 0; i < commandNames.Length; i++)
			{
				DevConsoleAutocompleteRegistry.Register(commandNames[i], DevConsoleAutocompleteEnhancements.RitsuLibModEntryId, DevConsoleAutocompleteContextPredicates.IsFirstArgument);
			}
		}

		private static void RegisterPileNameSecondArgument(params string[] commandNames)
		{
			for (int i = 0; i < commandNames.Length; i++)
			{
				DevConsoleAutocompleteRegistry.Register(commandNames[i], DevConsoleAutocompleteEnhancements.PileName, DevConsoleAutocompleteContextPredicates.IsSecondArgument);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Formats developer-console autocomplete candidates with optional localized suffix labels.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为开发者控制台的自动补全候选项附加可选的本地化后缀标签。
	///     </para>
	/// </summary>
	public static class DevConsoleAutocompleteDisplay
	{
		internal const string SuffixOpener = " (";

		/// <summary>
		///     <para xml:lang="en">
		///         Appends <c> (localized-title)</c> to <paramref name="entryId" /> when its localized title is
		///         available.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若 <paramref name="entryId" /> 有本地化标题，则为其附加 <c> (localized-title)</c>。
		///     </para>
		/// </summary>
		public static string FormatCandidate(string entryId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(entryId, "entryId");
			string title = DevConsoleModelIdAutocompleteCatalog.TryGetLocalizedTitle(entryId);
			return FormatWithTitle(entryId, title);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends <c> (localized-title)</c> to <paramref name="entryId" /> when
		///         <paramref name="localizedTitle" /> is provided.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若提供了 <paramref name="localizedTitle" />，则为 <paramref name="entryId" /> 附加
		///         <c> (localized-title)</c>。
		///     </para>
		/// </summary>
		public static string FormatCandidate(string entryId, string? localizedTitle)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(entryId, "entryId");
			return FormatWithTitle(entryId, localizedTitle);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends <c> (localized-title)</c> to an ancient-event option token when a display title is available.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若先古之民事件选项令牌有显示标题，则为其附加 <c> (localized-title)</c>。
		///     </para>
		/// </summary>
		public static string FormatAncientChoiceCandidate(string ancientEntryId, string choiceToken)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(ancientEntryId, "ancientEntryId");
			ArgumentException.ThrowIfNullOrWhiteSpace(choiceToken, "choiceToken");
			string title = DevConsoleAncientChoiceAutocompleteCatalog.TryGetDisplayTitle(ancientEntryId, choiceToken);
			return FormatWithTitle(choiceToken, title);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends <c> (localized-title)</c> to a pile token when its localized title is available.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         若牌堆令牌有本地化标题，则为其附加 <c> (localized-title)</c>。
		///     </para>
		/// </summary>
		public static string FormatPileCandidate(string token)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(token, "token");
			string title = DevConsolePileNameAutocompleteCatalog.TryGetLocalizedTitle(token);
			return FormatWithTitle(token, title);
		}

		private static string FormatWithTitle(string token, string? title)
		{
			if (!string.IsNullOrWhiteSpace(title))
			{
				return token + " (" + SanitizeSuffix(title) + ")";
			}
			return token;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Removes a trailing localized suffix from a decorated autocomplete candidate.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         移除已装饰自动补全候选项末尾的本地化后缀。
		///     </para>
		/// </summary>
		public static string StripLocalizedSuffix(string candidate)
		{
			if (string.IsNullOrWhiteSpace(candidate))
			{
				return candidate;
			}
			int num = candidate.LastIndexOf(" (", StringComparison.Ordinal);
			if (num < 0 || !candidate.EndsWith(')'))
			{
				return candidate;
			}
			return candidate.Substring(0, num);
		}

		internal static string SanitizeSuffix(string title)
		{
			return title.Replace(')', '）').Trim();
		}

		internal static string ComputeCommonPrefix(IReadOnlyList<string> entryIds, string commandPrefix)
		{
			switch (entryIds.Count)
			{
			case 0:
				return string.Empty;
			case 1:
				return commandPrefix + entryIds[0] + " ";
			default:
			{
				int num = entryIds.Min((string id) => id.Length);
				string text = entryIds[0];
				int num2 = 0;
				for (int i = 0; i < num; i++)
				{
					char ch = text[i];
					if (entryIds.Any((string id) => char.ToLowerInvariant(id[i]) != char.ToLowerInvariant(ch)))
					{
						break;
					}
					num2 = i + 1;
				}
				if (num2 <= 0)
				{
					return string.Empty;
				}
				return commandPrefix + text.Substring(0, num2);
			}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Developer-console autocomplete behaviors that can be bound to individual command arguments.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         可分别绑定到各命令参数的开发者控制台自动补全行为。
	///     </para>
	/// </summary>
	[Flags]
	public enum DevConsoleAutocompleteEnhancements
	{
		/// <summary>
		///     <para xml:lang="en">No enhancements.</para>
		///     <para xml:lang="zh-CN">不启用增强。</para>
		/// </summary>
		None = 0,
		/// <summary>
		///     <para xml:lang="en">
		///         Allows candidates to be matched by localized title text as well as by entry-ID prefix.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         除条目 ID 前缀外，还允许按本地化标题文本匹配候选项。
		///     </para>
		/// </summary>
		LocalizedTitleMatch = 1,
		/// <summary>
		///     <para xml:lang="en">
		///         Appends <c> (localized-title)</c> to displayed candidates while keeping
		///         <see cref="P:MegaCrit.Sts2.Core.DevConsole.CompletionResult.CommonPrefix" /> free of display labels.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为显示的候选项附加 <c> (localized-title)</c>，同时使
		///         <see cref="P:MegaCrit.Sts2.Core.DevConsole.CompletionResult.CommonPrefix" /> 不含显示标签。
		///     </para>
		/// </summary>
		LocalizedDisplayLabels = 2,
		/// <summary>
		///     <para xml:lang="en">
		///         Enables suffix shorthand matching for RitsuLib-registered mod entry IDs when no custom matcher is
		///         supplied.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         未提供自定义匹配器时，允许使用 RitsuLib 所注册模组条目 ID 的尾部简写进行匹配。
		///     </para>
		/// </summary>
		RitsuLibOwnedIdShorthandMatch = 4,
		/// <summary>
		///     <para xml:lang="en">Removes duplicate candidates while preserving their order.</para>
		///     <para xml:lang="zh-CN">在保留顺序的同时移除重复候选项。</para>
		/// </summary>
		DeduplicateCandidates = 8,
		/// <summary>
		///     <para xml:lang="en">Adds registered mod pile IDs to pile-argument candidates.</para>
		///     <para xml:lang="zh-CN">将已注册的模组牌堆 ID 添加到牌堆参数候选项中。</para>
		/// </summary>
		IncludeModPileCandidates = 0x10,
		/// <summary>
		///     <para xml:lang="en">Allows pile tokens to be matched by localized title text.</para>
		///     <para xml:lang="zh-CN">允许按本地化标题文本匹配牌堆令牌。</para>
		/// </summary>
		PileNameLocalizedTitleMatch = 0x20,
		/// <summary>
		///     <para xml:lang="en">Appends localized pile titles in parentheses to pile-argument candidates.</para>
		///     <para xml:lang="zh-CN">在牌堆参数候选项后以括号附加本地化牌堆标题。</para>
		/// </summary>
		PileNameDisplayLabels = 0x40,
		/// <summary>
		///     <para xml:lang="en">Enables localized-title matching and display labels for model entry IDs.</para>
		///     <para xml:lang="zh-CN">为模型条目 ID 启用本地化标题匹配和显示标签。</para>
		/// </summary>
		ModelEntryId = LocalizedTitleMatch | LocalizedDisplayLabels | DeduplicateCandidates,
		/// <summary>
		///     <para xml:lang="en">
		///         Combines <see cref="F:STS2RitsuLib.Diagnostics.DevConsole.DevConsoleAutocompleteEnhancements.ModelEntryId" /> with shorthand matching for RitsuLib-owned IDs.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <see cref="F:STS2RitsuLib.Diagnostics.DevConsole.DevConsoleAutocompleteEnhancements.ModelEntryId" /> 的基础上启用 RitsuLib 所注册 ID 的简写匹配。
		///     </para>
		/// </summary>
		RitsuLibModEntryId = ModelEntryId | RitsuLibOwnedIdShorthandMatch,
		/// <summary>
		///     <para xml:lang="en">
		///         Enables complete pile-name autocomplete: mod pile IDs, localized matching and labels,
		///         RitsuLib-owned ID shorthand, and duplicate removal.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         启用完整的牌堆名称自动补全：模组牌堆 ID、本地化匹配和标签、RitsuLib 所注册 ID 的简写及去重。
		///     </para>
		/// </summary>
		PileName = RitsuLibOwnedIdShorthandMatch | DeduplicateCandidates | IncludeModPileCandidates | PileNameLocalizedTitleMatch | PileNameDisplayLabels,
		/// <summary>
		///     <para xml:lang="en">
		///         Allows ancient-event option tokens to be matched by an option or relic's localized title, or by the
		///         relic's entry ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         允许按选项或遗物的本地化标题以及遗物条目 ID 匹配先古之民事件选项令牌。
		///     </para>
		/// </summary>
		AncientChoiceLocalizedTitleMatch = 0x80,
		/// <summary>
		///     <para xml:lang="en">
		///         Appends localized option or relic titles to second-argument candidates of <c>ancient</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <c>ancient</c> 的第二个参数候选项附加本地化选项或遗物标题。
		///     </para>
		/// </summary>
		AncientChoiceDisplayLabels = 0x100,
		/// <summary>
		///     <para xml:lang="en">Adds registered secondary-resource IDs to candidate lists.</para>
		///     <para xml:lang="zh-CN">将已注册的次要资源 ID 添加到候选列表中。</para>
		/// </summary>
		IncludeSecondaryResourceCandidates = 0x200,
		/// <summary>
		///     <para xml:lang="en">
		///         Allows secondary-resource IDs to be matched by localized title text or an unambiguous local ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         允许按本地化标题文本或无歧义的本地 ID 匹配次要资源 ID。
		///     </para>
		/// </summary>
		SecondaryResourceLocalizedTitleMatch = 0x400,
		/// <summary>
		///     <para xml:lang="en">Appends localized secondary-resource titles in parentheses.</para>
		///     <para xml:lang="zh-CN">以括号附加本地化次要资源标题。</para>
		/// </summary>
		SecondaryResourceDisplayLabels = 0x800,
		/// <summary>
		///     <para xml:lang="en">
		///         Enables localized matching and display labels for <c>ancient</c> choice arguments, which often
		///         represent relic rewards.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <c>ancient</c> 的选项参数启用本地化匹配和显示标签；这些选项通常代表遗物奖励。
		///     </para>
		/// </summary>
		AncientChoice = DeduplicateCandidates | AncientChoiceLocalizedTitleMatch | AncientChoiceDisplayLabels,
		/// <summary>
		///     <para xml:lang="en">
		///         Enables complete secondary-resource ID autocomplete: registered IDs, localized matching and labels,
		///         unambiguous local-ID matching, and duplicate removal.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         启用完整的次要资源 ID 自动补全：已注册 ID、本地化匹配和标签、无歧义的本地 ID 匹配及去重。
		///     </para>
		/// </summary>
		SecondaryResourceId = DeduplicateCandidates | IncludeSecondaryResourceCandidates | SecondaryResourceLocalizedTitleMatch | SecondaryResourceDisplayLabels
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Applies registered developer-console autocomplete enhancements to match predicates and results.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将已注册的开发者控制台自动补全增强应用于匹配谓词和结果。
	///     </para>
	/// </summary>
	public static class DevConsoleAutocompleteEnhancer
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Builds a match-predicate chain for <paramref name="enhancements" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="enhancements" /> 构建匹配谓词链。
		///     </para>
		/// </summary>
		public static Func<string, string, bool>? BuildMatchPredicate(DevConsoleAutocompleteEnhancements enhancements, Func<string, string, bool>? inner = null, IReadOnlyList<string>? completedArgs = null)
		{
			if (enhancements == DevConsoleAutocompleteEnhancements.None)
			{
				return inner;
			}
			Func<string, string, bool> func = inner;
			if (enhancements.HasFlag(DevConsoleAutocompleteEnhancements.RitsuLibOwnedIdShorthandMatch) && func == null)
			{
				func = DevConsoleAutocompleteOwnedIdMatch.Match;
			}
			if (enhancements.HasFlag(DevConsoleAutocompleteEnhancements.LocalizedTitleMatch))
			{
				func = DevConsoleAutocompleteMatchExtensions.WithLocalizedModelTitleMatch(func);
			}
			if (enhancements.HasFlag(DevConsoleAutocompleteEnhancements.PileNameLocalizedTitleMatch))
			{
				func = DevConsoleAutocompleteMatchExtensions.WithLocalizedPileTitleMatch(func);
			}
			if (enhancements.HasFlag(DevConsoleAutocompleteEnhancements.SecondaryResourceLocalizedTitleMatch))
			{
				func = DevConsoleAutocompleteMatchExtensions.WithSecondaryResourceLocalizedTitleMatch(func);
			}
			if (!enhancements.HasFlag(DevConsoleAutocompleteEnhancements.AncientChoiceLocalizedTitleMatch))
			{
				return func;
			}
			string ancientEntryId = ((completedArgs != null && completedArgs.Count > 0) ? completedArgs[0] : null);
			return DevConsoleAutocompleteMatchExtensions.WithAncientChoiceLocalizedMatch(func, ancientEntryId);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Applies result-side enhancements such as localized labels and duplicate removal.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         应用本地化标签、移除重复项等结果侧增强。
		///     </para>
		/// </summary>
		public static void ApplyToResult(ref CompletionResult result, DevConsoleAutocompleteEnhancements enhancements, IReadOnlyList<string>? completedArgs = null)
		{
			if (enhancements == DevConsoleAutocompleteEnhancements.None)
			{
				return;
			}
			if (enhancements.HasFlag(DevConsoleAutocompleteEnhancements.IncludeModPileCandidates))
			{
				DevConsolePileNameAutocompleteCatalog.AppendModPileCandidates(result.Candidates);
			}
			if (enhancements.HasFlag(DevConsoleAutocompleteEnhancements.IncludeSecondaryResourceCandidates))
			{
				DevConsoleSecondaryResourceAutocompleteCatalog.AppendResourceIdCandidates(result.Candidates);
			}
			if (result.Candidates.Count != 0)
			{
				if (enhancements.HasFlag(DevConsoleAutocompleteEnhancements.LocalizedDisplayLabels))
				{
					DevConsoleAutocompleteMatchExtensions.ApplyLocalizedDisplayLabels(ref result);
				}
				if (enhancements.HasFlag(DevConsoleAutocompleteEnhancements.AncientChoiceDisplayLabels) && completedArgs != null && completedArgs.Count > 0)
				{
					DevConsoleAutocompleteMatchExtensions.ApplyAncientChoiceDisplayLabels(ref result, completedArgs[0]);
				}
				if (enhancements.HasFlag(DevConsoleAutocompleteEnhancements.PileNameDisplayLabels))
				{
					DevConsoleAutocompleteMatchExtensions.ApplyPileDisplayLabels(ref result);
				}
				if (enhancements.HasFlag(DevConsoleAutocompleteEnhancements.SecondaryResourceDisplayLabels))
				{
					DevConsoleAutocompleteMatchExtensions.ApplySecondaryResourceDisplayLabels(ref result);
				}
				if (enhancements.HasFlag(DevConsoleAutocompleteEnhancements.DeduplicateCandidates))
				{
					result.Candidates = result.Candidates.Distinct<string>(StringComparer.OrdinalIgnoreCase).ToList();
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides low-level helpers for developer-console autocomplete predicates and display formatting.
	///         Prefer <see cref="T:STS2RitsuLib.Diagnostics.DevConsole.DevConsoleAutocomplete" /> for registration and argument-slot resolution.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供开发者控制台自动补全谓词和显示格式的底层辅助方法。注册和解析参数位置时应优先使用
	///         <see cref="T:STS2RitsuLib.Diagnostics.DevConsole.DevConsoleAutocomplete" />。
	///     </para>
	/// </summary>
	public static class DevConsoleAutocompleteMatchExtensions
	{
		private const int MaximumPreparedLocalizedTexts = 8192;

		private static readonly Lock PreparedTextLock = new Lock();

		private static readonly Dictionary<string, RitsuSearchPreparedText> PreparedLocalizedTexts = new Dictionary<string, RitsuSearchPreparedText>(StringComparer.Ordinal);

		/// <summary>
		///     <para xml:lang="en">
		///         Extends <paramref name="inner" /> with localized-title and enabled search-expansion matching for
		///         model entry IDs.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <paramref name="inner" /> 基础上添加模型条目 ID 的本地化标题和已启用搜索扩展匹配。
		///     </para>
		/// </summary>
		public static Func<string, string, bool> WithLocalizedModelTitleMatch(Func<string, string, bool>? inner = null)
		{
			Func<string, string, bool> baseMatch = inner ?? new Func<string, string, bool>(DefaultPrefixMatch);
			IReadOnlyDictionary<string, string> titles = DevConsoleModelIdAutocompleteCatalog.GetTitlesSnapshot();
			return delegate(string candidate, string partial)
			{
				if (baseMatch(candidate, partial))
				{
					return true;
				}
				string key = DevConsoleAutocompleteDisplay.StripLocalizedSuffix(candidate);
				string value;
				return titles.TryGetValue(key, out value) && MatchesLocalizedText(value, partial);
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Decorates completion candidates with localized suffix labels and recomputes
		///         <see cref="P:MegaCrit.Sts2.Core.DevConsole.CompletionResult.CommonPrefix" /> from undecorated IDs.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为补全候选项添加本地化后缀标签，并根据未装饰的 ID 重新计算
		///         <see cref="P:MegaCrit.Sts2.Core.DevConsole.CompletionResult.CommonPrefix" />。
		///     </para>
		/// </summary>
		public static void ApplyLocalizedDisplayLabels(ref CompletionResult result)
		{
			if (result.Candidates.Count != 0)
			{
				IReadOnlyDictionary<string, string> titles = DevConsoleModelIdAutocompleteCatalog.GetTitlesSnapshot();
				List<string> list = result.Candidates.Select(DevConsoleAutocompleteDisplay.StripLocalizedSuffix).ToList();
				result.Candidates = list.Select((string entryId) => DevConsoleAutocompleteDisplay.FormatCandidate(entryId, titles.GetValueOrDefault(entryId))).ToList();
				result.CommonPrefix = DevConsoleAutocompleteDisplay.ComputeCommonPrefix(list, result.CommandPrefix);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Extends <paramref name="inner" /> with localized pile-title and enabled search-expansion matching.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <paramref name="inner" /> 基础上添加本地化牌堆标题和已启用搜索扩展匹配。
		///     </para>
		/// </summary>
		public static Func<string, string, bool> WithLocalizedPileTitleMatch(Func<string, string, bool>? inner = null)
		{
			Func<string, string, bool> baseMatch = inner ?? new Func<string, string, bool>(DefaultPrefixMatch);
			IReadOnlyDictionary<string, string> titles = DevConsolePileNameAutocompleteCatalog.GetTitlesSnapshot();
			return delegate(string candidate, string partial)
			{
				if (baseMatch(candidate, partial))
				{
					return true;
				}
				string key = DevConsoleAutocompleteDisplay.StripLocalizedSuffix(candidate);
				string value;
				return titles.TryGetValue(key, out value) && MatchesLocalizedText(value, partial);
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Extends <paramref name="inner" /> with localized secondary-resource title matching, enabled
		///         search-expansion matching, and unambiguous local-ID matching.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <paramref name="inner" /> 基础上添加次要资源的本地化标题、已启用搜索扩展和无歧义本地 ID 匹配。
		///     </para>
		/// </summary>
		public static Func<string, string, bool> WithSecondaryResourceLocalizedTitleMatch(Func<string, string, bool>? inner = null)
		{
			Func<string, string, bool> baseMatch = inner ?? new Func<string, string, bool>(DefaultPrefixMatch);
			return (string candidate, string partial) => baseMatch(candidate, partial) || DevConsoleSecondaryResourceAutocompleteCatalog.MatchesResourceIdOrTitle(DevConsoleAutocompleteDisplay.StripLocalizedSuffix(candidate), partial);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Extends <paramref name="inner" /> with localized ancient-event option and enabled search-expansion
		///         matching for a resolved ancient-event ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <paramref name="inner" /> 基础上，为已解析的先古之民事件 ID 添加本地化选项和已启用搜索扩展匹配。
		///     </para>
		/// </summary>
		public static Func<string, string, bool> WithAncientChoiceLocalizedMatch(Func<string, string, bool>? inner, string? ancientEntryId)
		{
			Func<string, string, bool> baseMatch = inner ?? new Func<string, string, bool>(DefaultPrefixMatch);
			return delegate(string candidate, string partial)
			{
				if (baseMatch(candidate, partial))
				{
					return true;
				}
				if (string.IsNullOrWhiteSpace(ancientEntryId))
				{
					return false;
				}
				string choiceToken = DevConsoleAutocompleteDisplay.StripLocalizedSuffix(candidate);
				return DevConsoleAncientChoiceAutocompleteCatalog.MatchesLocalizedTitle(ancientEntryId, choiceToken, partial);
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Decorates <c>ancient</c> choice candidates with localized option or relic titles.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <c>ancient</c> 的选项候选项添加本地化选项或遗物标题。
		///     </para>
		/// </summary>
		public static void ApplyAncientChoiceDisplayLabels(ref CompletionResult result, string ancientEntryId)
		{
			if (result.Candidates.Count != 0)
			{
				List<string> list = result.Candidates.Select(DevConsoleAutocompleteDisplay.StripLocalizedSuffix).ToList();
				result.Candidates = list.Select((string token) => DevConsoleAutocompleteDisplay.FormatAncientChoiceCandidate(ancientEntryId, token)).ToList();
				result.CommonPrefix = DevConsoleAutocompleteDisplay.ComputeCommonPrefix(list, result.CommandPrefix);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Decorates pile-argument candidates with localized suffix labels.</para>
		///     <para xml:lang="zh-CN">为牌堆参数候选项添加本地化后缀标签。</para>
		/// </summary>
		public static void ApplyPileDisplayLabels(ref CompletionResult result)
		{
			if (result.Candidates.Count != 0)
			{
				IReadOnlyDictionary<string, string> titles = DevConsolePileNameAutocompleteCatalog.GetTitlesSnapshot();
				List<string> list = result.Candidates.Select(DevConsoleAutocompleteDisplay.StripLocalizedSuffix).ToList();
				result.Candidates = list.Select((string token) => DevConsoleAutocompleteDisplay.FormatCandidate(token, titles.GetValueOrDefault(token))).ToList();
				result.CommonPrefix = DevConsoleAutocompleteDisplay.ComputeCommonPrefix(list, result.CommandPrefix);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Decorates secondary-resource ID candidates with localized suffix labels.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为次要资源 ID 候选项添加本地化后缀标签。
		///     </para>
		/// </summary>
		public static void ApplySecondaryResourceDisplayLabels(ref CompletionResult result)
		{
			if (result.Candidates.Count != 0)
			{
				List<string> list = result.Candidates.Select(DevConsoleAutocompleteDisplay.StripLocalizedSuffix).ToList();
				result.Candidates = list.Select((string resourceId) => DevConsoleAutocompleteDisplay.FormatCandidate(resourceId, DevConsoleSecondaryResourceAutocompleteCatalog.TryGetLocalizedTitle(resourceId))).ToList();
				result.CommonPrefix = DevConsoleAutocompleteDisplay.ComputeCommonPrefix(list, result.CommandPrefix);
			}
		}

		private static bool DefaultPrefixMatch(string candidate, string partial)
		{
			return candidate.StartsWith(partial, StringComparison.OrdinalIgnoreCase);
		}

		internal static bool MatchesLocalizedText(string? text, string partial)
		{
			if (string.IsNullOrWhiteSpace(text))
			{
				return false;
			}
			string text2 = partial.Trim();
			if (text2.Length == 0)
			{
				return true;
			}
			RitsuSearchPreparedText value;
			using (PreparedTextLock.EnterScope())
			{
				if (!PreparedLocalizedTexts.TryGetValue(text, out value))
				{
					if (PreparedLocalizedTexts.Count >= 8192)
					{
						PreparedLocalizedTexts.Clear();
					}
					value = new RitsuSearchPreparedText(text);
					PreparedLocalizedTexts.Add(text, value);
				}
			}
			return RitsuSearchMatcher.Contains(text, text2, value);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides tail-aware autocomplete matching for public-entry IDs registered through RitsuLib.</para>
	///     <para xml:lang="zh-CN">为通过 RitsuLib 注册的公共条目 ID 提供感知尾部片段的自动补全匹配。</para>
	/// </summary>
	public static class DevConsoleAutocompleteOwnedIdMatch
	{
		private sealed record OwnedIdCatalog(Dictionary<string, string> IdOwnerMap);

		private static readonly Lazy<OwnedIdCatalog> OwnedCatalog = new Lazy<OwnedIdCatalog>(BuildOwnedIdCatalog);

		/// <summary>
		///     <para xml:lang="en">Matches a full ID prefix or an owned ID's mod-qualified tail.</para>
		///     <para xml:lang="zh-CN">匹配完整 ID 的前缀，或已知所属 ID 中带模组限定的尾部片段。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         The ownership index is built on first use after content registration has been frozen.
		///     </para>
		///     <para xml:lang="zh-CN">所属关系索引会在内容注册冻结后的首次使用时构建。</para>
		/// </remarks>
		public static bool Match(string candidate, string partial)
		{
			if (string.IsNullOrWhiteSpace(partial))
			{
				return true;
			}
			string value = partial.Trim();
			string text = DevConsoleAutocompleteDisplay.StripLocalizedSuffix(candidate);
			if (text.StartsWith(value, StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}
			if (!TryGetOwnedTail(text, out string tail))
			{
				return false;
			}
			if (!tail.StartsWith(value, StringComparison.OrdinalIgnoreCase))
			{
				return tail.Contains(value, StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}

		private static bool TryGetOwnedTail(string candidate, out string tail)
		{
			tail = string.Empty;
			if (string.IsNullOrWhiteSpace(candidate))
			{
				return false;
			}
			if (!OwnedCatalog.Value.IdOwnerMap.TryGetValue(candidate.Trim(), out string value))
			{
				return false;
			}
			string text = ModContentRegistry.NormalizePublicStem(value) + "_";
			if (!candidate.StartsWith(text, StringComparison.OrdinalIgnoreCase))
			{
				return false;
			}
			if (candidate.Length <= text.Length)
			{
				return false;
			}
			tail = candidate.Substring(text.Length);
			return tail.Contains('_');
		}

		private static OwnedIdCatalog BuildOwnedIdCatalog()
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
			ModContentRegistry.ModContentRegisteredTypeSnapshot[] registeredTypeSnapshots = ModContentRegistry.GetRegisteredTypeSnapshots();
			for (int i = 0; i < registeredTypeSnapshots.Length; i++)
			{
				ModContentRegistry.ModContentRegisteredTypeSnapshot modContentRegisteredTypeSnapshot = registeredTypeSnapshots[i];
				if (modContentRegisteredTypeSnapshot.ModelDbId != (ModelId)null)
				{
					TryAddOwned(dictionary, modContentRegisteredTypeSnapshot.ModelDbId.Entry, modContentRegisteredTypeSnapshot.ModId);
				}
				if (!string.IsNullOrWhiteSpace(modContentRegisteredTypeSnapshot.ExpectedPublicEntry))
				{
					TryAddOwned(dictionary, modContentRegisteredTypeSnapshot.ExpectedPublicEntry, modContentRegisteredTypeSnapshot.ModId);
				}
			}
			ModKeywordDefinition[] definitionsSnapshot = ModKeywordRegistry.GetDefinitionsSnapshot();
			foreach (ModKeywordDefinition modKeywordDefinition in definitionsSnapshot)
			{
				TryAddOwned(dictionary, modKeywordDefinition.Id, modKeywordDefinition.ModId);
			}
			ModCardTagDefinition[] definitionsSnapshot2 = ModCardTagRegistry.GetDefinitionsSnapshot();
			foreach (ModCardTagDefinition modCardTagDefinition in definitionsSnapshot2)
			{
				TryAddOwned(dictionary, modCardTagDefinition.Id, modCardTagDefinition.ModId);
			}
			ModCardPileDefinition[] definitionsSnapshot3 = ModCardPileRegistry.GetDefinitionsSnapshot();
			foreach (ModCardPileDefinition modCardPileDefinition in definitionsSnapshot3)
			{
				TryAddOwned(dictionary, modCardPileDefinition.Id, modCardPileDefinition.ModId);
			}
			ModTopBarButtonDefinition[] definitionsSnapshot4 = ModTopBarButtonRegistry.GetDefinitionsSnapshot();
			foreach (ModTopBarButtonDefinition modTopBarButtonDefinition in definitionsSnapshot4)
			{
				TryAddOwned(dictionary, modTopBarButtonDefinition.Id, modTopBarButtonDefinition.ModId);
			}
			return new OwnedIdCatalog(dictionary);
		}

		private static void TryAddOwned(Dictionary<string, string> owned, string? id, string? modId)
		{
			if (!string.IsNullOrWhiteSpace(id) && !string.IsNullOrWhiteSpace(modId))
			{
				owned.TryAdd(id.Trim(), modId);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Stores developer-console autocomplete enhancement bindings by command.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         按命令存储开发者控制台自动补全增强绑定。
	///     </para>
	/// </summary>
	public static class DevConsoleAutocompleteRegistry
	{
		private static readonly Lock SyncRoot;

		private static readonly List<DevConsoleAutocompleteBinding> Bindings;

		private static readonly HashSet<DevConsoleAutocompleteBinding> FaultedBindings;

		private static bool _builtInRegistered;

		static DevConsoleAutocompleteRegistry()
		{
			SyncRoot = new Lock();
			Bindings = new List<DevConsoleAutocompleteBinding>();
			FaultedBindings = new HashSet<DevConsoleAutocompleteBinding>(ReferenceEqualityComparer.Instance);
			RegisterBuiltInBindings();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a binding. When multiple bindings match the same argument slot, their enhancements are
		///         combined.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册一个绑定。多个绑定匹配同一参数位置时，会合并其增强标志。
		///     </para>
		/// </summary>
		public static void Register(DevConsoleAutocompleteBinding binding)
		{
			ArgumentNullException.ThrowIfNull(binding, "binding");
			ArgumentException.ThrowIfNullOrWhiteSpace(binding.CommandName, "binding.CommandName");
			int? argumentIndex = binding.ArgumentIndex;
			if (argumentIndex.HasValue && argumentIndex.GetValueOrDefault() < 0)
			{
				throw new ArgumentOutOfRangeException("binding", binding.ArgumentIndex, "The autocomplete argument index cannot be negative.");
			}
			ValidateEnhancements(binding.Enhancements, "binding");
			binding = new DevConsoleAutocompleteBinding
			{
				CommandName = binding.CommandName.Trim(),
				ArgumentIndex = binding.ArgumentIndex,
				AppliesWhen = binding.AppliesWhen,
				Enhancements = binding.Enhancements
			};
			using (SyncRoot.EnterScope())
			{
				Bindings.Add(binding);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers enhancements for a command argument slot.</para>
		///     <para xml:lang="zh-CN">为命令的指定参数位置注册增强。</para>
		/// </summary>
		public static void Register(string commandName, int argumentIndex, DevConsoleAutocompleteEnhancements enhancements, Func<DevConsoleAutocompleteContext, bool>? appliesWhen = null)
		{
			Register(new DevConsoleAutocompleteBinding
			{
				CommandName = commandName,
				ArgumentIndex = argumentIndex,
				Enhancements = enhancements,
				AppliesWhen = appliesWhen
			});
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers enhancements that apply when <paramref name="appliesWhen" /> returns <see langword="true" />;
		///         the binding applies to every argument position.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册在 <paramref name="appliesWhen" /> 返回 <see langword="true" /> 时生效的增强；该绑定适用于所有
		///         参数位置。
		///     </para>
		/// </summary>
		public static void Register(string commandName, DevConsoleAutocompleteEnhancements enhancements, Func<DevConsoleAutocompleteContext, bool> appliesWhen)
		{
			ArgumentNullException.ThrowIfNull(appliesWhen, "appliesWhen");
			Register(new DevConsoleAutocompleteBinding
			{
				CommandName = commandName,
				Enhancements = enhancements,
				AppliesWhen = appliesWhen
			});
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves and combines all enhancements that apply to an autocomplete call.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         解析并合并适用于一次自动补全调用的所有增强。
		///     </para>
		/// </summary>
		public static DevConsoleAutocompleteEnhancements Resolve(AbstractConsoleCmd command, string[] completedArgs, int argumentIndex)
		{
			ArgumentNullException.ThrowIfNull(command, "command");
			ArgumentNullException.ThrowIfNull(completedArgs, "completedArgs");
			DevConsoleAutocompleteContext context = new DevConsoleAutocompleteContext(command, completedArgs, argumentIndex);
			DevConsoleAutocompleteEnhancements devConsoleAutocompleteEnhancements = DevConsoleAutocompleteEnhancements.None;
			DevConsoleAutocompleteBinding[] array;
			using (SyncRoot.EnterScope())
			{
				array = Bindings.ToArray();
			}
			DevConsoleAutocompleteBinding[] array2 = array;
			foreach (DevConsoleAutocompleteBinding devConsoleAutocompleteBinding in array2)
			{
				if (BindingMatches(devConsoleAutocompleteBinding, context))
				{
					devConsoleAutocompleteEnhancements |= devConsoleAutocompleteBinding.Enhancements;
				}
			}
			return devConsoleAutocompleteEnhancements;
		}

		/// <summary>
		///     <para xml:lang="en">Returns whether any enhancements apply to an autocomplete call.</para>
		///     <para xml:lang="zh-CN">返回是否有任何增强适用于一次自动补全调用。</para>
		/// </summary>
		public static bool HasEnhancements(AbstractConsoleCmd command, string[] completedArgs, int argumentIndex)
		{
			return Resolve(command, completedArgs, argumentIndex) != DevConsoleAutocompleteEnhancements.None;
		}

		private static bool BindingMatches(DevConsoleAutocompleteBinding binding, DevConsoleAutocompleteContext context)
		{
			if (!binding.CommandName.Equals(context.CommandName, StringComparison.OrdinalIgnoreCase))
			{
				return false;
			}
			int? argumentIndex = binding.ArgumentIndex;
			if (argumentIndex.HasValue)
			{
				int valueOrDefault = argumentIndex.GetValueOrDefault();
				if (valueOrDefault != context.ArgumentIndex)
				{
					return false;
				}
			}
			try
			{
				return binding.AppliesWhen?.Invoke(context) ?? true;
			}
			catch (Exception ex)
			{
				bool flag;
				using (SyncRoot.EnterScope())
				{
					flag = FaultedBindings.Add(binding);
				}
				if (flag)
				{
					RitsuLibFramework.Logger.Warn("[DevConsole] Autocomplete predicate for '" + binding.CommandName + "' failed: " + ex.Message, 1);
				}
				return false;
			}
		}

		private static void ValidateEnhancements(DevConsoleAutocompleteEnhancements enhancements, string paramName)
		{
			if ((enhancements & ~(DevConsoleAutocompleteEnhancements.PileName | DevConsoleAutocompleteEnhancements.LocalizedTitleMatch | DevConsoleAutocompleteEnhancements.LocalizedDisplayLabels | DevConsoleAutocompleteEnhancements.AncientChoiceLocalizedTitleMatch | DevConsoleAutocompleteEnhancements.AncientChoiceDisplayLabels | DevConsoleAutocompleteEnhancements.IncludeSecondaryResourceCandidates | DevConsoleAutocompleteEnhancements.SecondaryResourceLocalizedTitleMatch | DevConsoleAutocompleteEnhancements.SecondaryResourceDisplayLabels)) != DevConsoleAutocompleteEnhancements.None)
			{
				throw new ArgumentOutOfRangeException(paramName, enhancements, "The autocomplete binding contains unsupported enhancement flags.");
			}
		}

		private static void RegisterBuiltInBindings()
		{
			using (SyncRoot.EnterScope())
			{
				if (!_builtInRegistered)
				{
					DevConsoleAutocompleteDefaults.Register();
					_builtInRegistered = true;
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Maps model entry IDs to localized display titles for developer-console autocomplete.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将模型条目 ID 映射到开发者控制台自动补全所用的本地化显示标题。
	///     </para>
	/// </summary>
	internal static class DevConsoleModelIdAutocompleteCatalog
	{
		private static readonly Lock Sync;

		private static Dictionary<string, string>? _titlesByEntry;

		private static string? _builtForLanguage;

		static DevConsoleModelIdAutocompleteCatalog()
		{
			Sync = new Lock();
			RitsuLibFramework.SubscribeLifecycle((Action<ModelRegistryInitializedEvent>)delegate
			{
				Invalidate();
			}, false);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the localized title for <paramref name="entryId" />, or <see langword="null" /> when it is
		///         unknown or empty.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <paramref name="entryId" /> 的本地化标题；标题未知或为空时返回 <see langword="null" />。
		///     </para>
		/// </summary>
		public static string? TryGetLocalizedTitle(string entryId)
		{
			if (!string.IsNullOrWhiteSpace(entryId))
			{
				return GetTitlesSnapshot().GetValueOrDefault(entryId.Trim());
			}
			return null;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether <paramref name="partial" /> occurs in the localized title of
		///         <paramref name="entryId" /> or one of its enabled search expansions, ignoring case.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <paramref name="entryId" /> 的本地化标题或已启用搜索扩展是否包含
		///         <paramref name="partial" />，忽略大小写。
		///     </para>
		/// </summary>
		public static bool MatchesLocalizedTitle(string entryId, string partial)
		{
			if (string.IsNullOrWhiteSpace(partial))
			{
				return true;
			}
			return DevConsoleAutocompleteMatchExtensions.MatchesLocalizedText(GetTitlesSnapshot().GetValueOrDefault(entryId.Trim()), partial);
		}

		internal static IReadOnlyDictionary<string, string> GetTitlesSnapshot()
		{
			return EnsureBuilt();
		}

		private static Dictionary<string, string> EnsureBuilt()
		{
			string text = I18N.ResolveCurrentLanguageCode();
			using (Sync.EnterScope())
			{
				if (_titlesByEntry != null && string.Equals(_builtForLanguage, text, StringComparison.OrdinalIgnoreCase))
				{
					return _titlesByEntry;
				}
				_titlesByEntry = BuildTitles();
				_builtForLanguage = text;
				return _titlesByEntry;
			}
		}

		private static void Invalidate()
		{
			using (Sync.EnterScope())
			{
				_titlesByEntry = null;
				_builtForLanguage = null;
			}
		}

		private static Dictionary<string, string> BuildTitles()
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
			try
			{
				foreach (var (entryId, locString) in DevConsoleAutocompleteCandidateSources.EnumerateLocalizedModelTitles())
				{
					TryAddTitle(dictionary, entryId, locString);
				}
			}
			catch
			{
			}
			return dictionary;
		}

		private static void TryAddTitle(Dictionary<string, string> titles, string entryId, LocString locString)
		{
			try
			{
				string value = locString.GetFormattedText()?.Trim();
				if (!string.IsNullOrWhiteSpace(value))
				{
					titles.TryAdd(entryId, value);
				}
			}
			catch
			{
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Maps developer-console pile-argument tokens to localized display titles.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将开发者控制台的牌堆参数令牌映射到本地化显示标题。
	///     </para>
	/// </summary>
	public static class DevConsolePileNameAutocompleteCatalog
	{
		private static readonly Lock Sync = new Lock();

		private static Dictionary<string, string>? _titlesByToken;

		private static string? _builtForLanguage;

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the localized title for <paramref name="token" />, or <see langword="null" /> when it is
		///         unknown or empty.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <paramref name="token" /> 的本地化标题；标题未知或为空时返回 <see langword="null" />。
		///     </para>
		/// </summary>
		public static string? TryGetLocalizedTitle(string token)
		{
			if (!string.IsNullOrWhiteSpace(token))
			{
				return GetTitlesSnapshot().GetValueOrDefault(token.Trim());
			}
			return null;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether <paramref name="partial" /> occurs in the localized title of
		///         <paramref name="token" /> or one of its enabled search expansions, ignoring case.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <paramref name="token" /> 的本地化标题或已启用搜索扩展是否包含
		///         <paramref name="partial" />，忽略大小写。
		///     </para>
		/// </summary>
		public static bool MatchesLocalizedTitle(string token, string partial)
		{
			if (string.IsNullOrWhiteSpace(partial))
			{
				return true;
			}
			return DevConsoleAutocompleteMatchExtensions.MatchesLocalizedText(GetTitlesSnapshot().GetValueOrDefault(token.Trim()), partial);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends registered mod pile IDs that are not already present in <paramref name="candidates" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将 <paramref name="candidates" /> 中尚不存在的已注册模组牌堆 ID 追加到其中。
		///     </para>
		/// </summary>
		public static void AppendModPileCandidates(IList<string> candidates)
		{
			ArgumentNullException.ThrowIfNull(candidates, "candidates");
			ModCardPileDefinition[] definitionsSnapshot = ModCardPileRegistry.GetDefinitionsSnapshot();
			foreach (ModCardPileDefinition definition in definitionsSnapshot)
			{
				if (!candidates.Any((string c) => c.Equals(definition.Id, StringComparison.OrdinalIgnoreCase)))
				{
					candidates.Add(definition.Id);
				}
			}
		}

		private static Dictionary<string, string> EnsureBuilt()
		{
			string text = I18N.ResolveCurrentLanguageCode();
			using (Sync.EnterScope())
			{
				if (_titlesByToken != null && string.Equals(_builtForLanguage, text, StringComparison.OrdinalIgnoreCase))
				{
					return _titlesByToken;
				}
				_titlesByToken = BuildTitles();
				_builtForLanguage = text;
				return _titlesByToken;
			}
		}

		internal static IReadOnlyDictionary<string, string> GetTitlesSnapshot()
		{
			return EnsureBuilt();
		}

		private static Dictionary<string, string> BuildTitles()
		{
			//IL_0023: Unknown result type (might be due to invalid IL or missing references)
			//IL_006d: Unknown result type (might be due to invalid IL or missing references)
			Dictionary<string, string> dictionary = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
			string[] names = Enum.GetNames<PileType>();
			foreach (string text in names)
			{
				if (Enum.TryParse<PileType>(text, out PileType result) && ModCardPileRegistry.TryGetByPileType(result, out ModCardPileDefinition definition))
				{
					TryAddTitle(dictionary, text, definition.Title);
				}
			}
			ModCardPileDefinition[] definitionsSnapshot = ModCardPileRegistry.GetDefinitionsSnapshot();
			foreach (ModCardPileDefinition modCardPileDefinition in definitionsSnapshot)
			{
				TryAddTitle(dictionary, modCardPileDefinition.Id, modCardPileDefinition.Title);
				if (ModCardPileRegistry.TryGetId(modCardPileDefinition.PileType, out string id) && !id.Equals(modCardPileDefinition.Id, StringComparison.OrdinalIgnoreCase))
				{
					TryAddTitle(dictionary, id, modCardPileDefinition.Title);
				}
			}
			return dictionary;
		}

		private static void TryAddTitle(Dictionary<string, string> titles, string token, LocString locString)
		{
			try
			{
				string value = locString.GetFormattedText()?.Trim();
				if (!string.IsNullOrWhiteSpace(value))
				{
					titles.TryAdd(token, value);
				}
			}
			catch
			{
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides autocomplete candidates and localized labels for registered secondary-resource IDs.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为已注册的次要资源 ID 提供自动补全候选项和本地化标签。
	///     </para>
	/// </summary>
	public static class DevConsoleSecondaryResourceAutocompleteCatalog
	{
		/// <summary>
		///     <para xml:lang="en">Returns registered secondary-resource IDs in deterministic order.</para>
		///     <para xml:lang="zh-CN">按确定顺序返回已注册的次要资源 ID。</para>
		/// </summary>
		public static string[] GetResourceIds()
		{
			return (from definition in ModSecondaryResourceRegistry.GetDefinitionsSnapshot()
				select definition.Id).Order<string>(StringComparer.OrdinalIgnoreCase).ToArray();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends registered secondary-resource IDs to <paramref name="candidates" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将已注册的次要资源 ID 追加到 <paramref name="candidates" />。
		///     </para>
		/// </summary>
		public static void AppendResourceIdCandidates(ICollection<string> candidates)
		{
			ArgumentNullException.ThrowIfNull(candidates, "candidates");
			string[] resourceIds = GetResourceIds();
			foreach (string item in resourceIds)
			{
				candidates.Add(item);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Resolves a full resource ID or an unambiguous resource-local ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         解析完整资源 ID 或无歧义的资源本地 ID。
		///     </para>
		/// </summary>
		public static bool TryResolveResource(string input, out SecondaryResourceDefinition definition)
		{
			definition = null;
			string token = DevConsoleAutocompleteDisplay.StripLocalizedSuffix(input).Trim();
			if (string.IsNullOrWhiteSpace(token))
			{
				return false;
			}
			if (ModSecondaryResourceRegistry.TryGet(token, out definition))
			{
				return true;
			}
			SecondaryResourceDefinition[] array = (from candidate in ModSecondaryResourceRegistry.GetDefinitionsSnapshot()
				where string.Equals(candidate.LocalId, token, StringComparison.OrdinalIgnoreCase)
				select candidate).Take(2).ToArray();
			if (array.Length != 1)
			{
				return false;
			}
			definition = array[0];
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the localized title for a registered resource ID, or <see langword="null" /> when
		///         unavailable.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回已注册资源 ID 的本地化标题；无法取得时返回 <see langword="null" />。
		///     </para>
		/// </summary>
		public static string? TryGetLocalizedTitle(string resourceId)
		{
			if (!TryResolveResource(resourceId, out SecondaryResourceDefinition definition))
			{
				return null;
			}
			return TryGetLocalizedTitle(definition);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns the localized title for a registered resource, or <see langword="null" /> when unavailable.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回已注册资源的本地化标题；无法取得时返回 <see langword="null" />。
		///     </para>
		/// </summary>
		public static string? TryGetLocalizedTitle(SecondaryResourceDefinition definition)
		{
			ArgumentNullException.ThrowIfNull(definition, "definition");
			try
			{
				LocString? title = SecondaryResourceText.GetTitle(definition);
				return (title == null) ? null : title.GetFormattedText()?.Trim();
			}
			catch
			{
				return null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether <paramref name="partial" /> matches a resource ID, an unambiguous local ID, or a
		///         localized title or one of its enabled search expansions.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回 <paramref name="partial" /> 是否匹配资源 ID、无歧义的本地 ID、本地化标题或已启用搜索扩展。
		///     </para>
		/// </summary>
		public static bool MatchesResourceIdOrTitle(string resourceId, string partial)
		{
			if (!TryResolveResource(resourceId, out SecondaryResourceDefinition definition))
			{
				return false;
			}
			string text = DevConsoleAutocompleteDisplay.StripLocalizedSuffix(partial).Trim();
			if (string.IsNullOrWhiteSpace(text))
			{
				return true;
			}
			string text2 = TryGetLocalizedTitle(definition);
			if (!definition.Id.StartsWith(text, StringComparison.OrdinalIgnoreCase) && !definition.LocalId.StartsWith(text, StringComparison.OrdinalIgnoreCase))
			{
				return DevConsoleAutocompleteMatchExtensions.MatchesLocalizedText(text2, text);
			}
			return true;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides candidates for discovery-ID arguments of the <c>unlock</c> command.
	///     </para>
	///     <para xml:lang="zh-CN">
