		}

		public static bool TryGetCandidates(string discoveryType, out IReadOnlyList<string> candidates)
		{
			if (!Sources.TryGetValue(discoveryType.Trim(), out Func<IEnumerable<string>> value))
			{
				candidates = Array.Empty<string>();
				return false;
			}
			List<string> list = new List<string>();
			list.AddRange(value());
			candidates = new <>z__ReadOnlyList<string>(list);
			return true;
		}
	}
