namespace STS2RitsuLib.Diagnostics.DebugTools
{
	internal readonly record struct RitsuDebugActionFeedback(string Code, string Fallback, string[] Arguments)
	{
		private const int MaxCodeLength = 96;

		private const int MaxFallbackLength = 1024;

		private const int MaxArgumentCount = 8;

		private const int MaxArgumentLength = 256;

		private const int MaxFormattedLength = 2048;

		private const string EnumArgumentPrefix = "@enum:";

		internal static RitsuDebugActionFeedback Create(string code, string fallback, params object?[] arguments)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(code, "code");
			ArgumentException.ThrowIfNullOrWhiteSpace(fallback, "fallback");
			ArgumentNullException.ThrowIfNull(arguments, "arguments");
			if (code.Length > 96 || code.Any(delegate(char character)
			{
				bool flag = char.IsAsciiLetterOrDigit(character);
				if (!flag)
				{
					bool flag2 = ((character == '-' || character == '.') ? true : false);
					flag = flag2;
				}
				return !flag;
			}))
			{
				throw new ArgumentException("Feedback codes must be compact ASCII identifiers.", "code");
			}
			if (fallback.Length > 1024)
			{
				throw new ArgumentException("The feedback fallback is too long.", "fallback");
			}
			if (arguments.Length > 8)
			{
				throw new ArgumentException("The feedback contains too many arguments.", "arguments");
			}
			string[] array = arguments.Select(SerializeArgument).ToArray();
			if (array.Any((string argument) => argument.Length > 256))
			{
				throw new ArgumentException("A feedback argument is too long.", "arguments");
			}
			RitsuDebugActionFeedback result = new RitsuDebugActionFeedback(code, fallback, array);
			if (result.GetEnglishText().Length > 2048)
			{
				throw new ArgumentException("The formatted feedback is too long.", "arguments");
			}
			return result;
		}

		internal bool IsValid()
		{
			if (string.IsNullOrWhiteSpace(Code) || Code.Length > 96 || Code.Any(delegate(char character)
			{
				bool flag = char.IsAsciiLetterOrDigit(character);
				if (!flag)
				{
					bool flag2 = ((character == '-' || character == '.') ? true : false);
					flag = flag2;
				}
				return !flag;
			}) || string.IsNullOrWhiteSpace(Fallback) || Fallback.Length > 1024 || Arguments == null || Arguments.Length > 8 || Arguments.Any((string argument) => argument == null || argument.Length > 256))
			{
				return false;
			}
			try
			{
				return GetEnglishText().Length <= 2048;
			}
			catch (FormatException)
			{
				return false;
			}
		}

		internal string GetLocalizedText()
		{
			string format = ModSettingsLocalization.Get("ritsulib.debugTools.feedback." + Code, Fallback);
			try
			{
				return string.Format(CultureInfo.CurrentCulture, format, new ReadOnlySpan<object>(((IEnumerable<string>)Arguments).Select((Func<string, object>)((string argument) => ResolveArgument(argument, localize: true))).ToArray()));
			}
			catch (FormatException)
			{
				return GetEnglishText();
			}
		}

		internal string GetEnglishText()
		{
			return string.Format(CultureInfo.InvariantCulture, Fallback, new ReadOnlySpan<object>(((IEnumerable<string>)Arguments).Select((Func<string, object>)((string argument) => ResolveArgument(argument, localize: false))).ToArray()));
		}

		private static string SerializeArgument(object? argument)
		{
			object obj2;
			if (!(argument is Enum obj))
			{
				obj2 = Convert.ToString(argument, CultureInfo.InvariantCulture);
				if (obj2 == null)
				{
					return string.Empty;
				}
			}
			else
			{
				obj2 = $"{"@enum:"}{obj.GetType().Name}:{obj}";
			}
			return (string)obj2;
		}

		private static string ResolveArgument(string argument, bool localize)
		{
			if (!argument.StartsWith("@enum:", StringComparison.Ordinal))
			{
				return argument;
			}
			int num = argument.IndexOf(':', "@enum:".Length);
			if (num < 0 || num == argument.Length - 1)
			{
				return argument;
			}
			int length = "@enum:".Length;
			string text = argument.Substring(length, num - length);
			string text2 = argument.Substring(num + 1);
			if (!localize)
			{
				return text2;
			}
			return ModSettingsLocalization.Get("ritsulib.debugTools.enum." + text + "." + text2, text2);
		}
	}
