	internal static class RitsuDebugActionProtocol
	{
		private readonly record struct PreparedAction(RegistrationBase Registration, RitsuDebugActionContext Context, RitsuLibSidecarPeerFeatures RequiredPeerFeatures);

		private readonly record struct PendingClientRequest(string ActionId, DateTimeOffset CreatedAtUtc);

		private readonly record struct HostClientRequestKey(ulong SenderNetId, string RequestId);

		private abstract class RegistrationBase(string actionId, Type payloadType, RitsuLibSidecarPeerFeatures requiredPeerFeatures)
		{
			internal string ActionId { get; } = actionId;

			internal Type PayloadType { get; } = payloadType;

			internal RitsuLibSidecarPeerFeatures RequiredPeerFeatures { get; } = requiredPeerFeatures;

			internal abstract RitsuDebugActionCheck Validate(RitsuDebugActionContext context, string payloadJson);

			internal abstract RitsuLibSidecarPeerFeatures GetRequiredPeerFeatures(string payloadJson);

			internal abstract Task<string> Execute(RitsuDebugActionContext context, string payloadJson);
		}

		private sealed class Registration<TPayload>(string actionId, Func<RitsuDebugActionContext, TPayload, RitsuDebugActionCheck> validate, Func<RitsuDebugActionContext, TPayload, Task<string>> execute, RitsuLibSidecarPeerFeatures requiredPeerFeatures, Func<TPayload, RitsuLibSidecarPeerFeatures>? payloadPeerFeatures) : RegistrationBase(actionId, typeof(TPayload), requiredPeerFeatures)
		{
			internal override RitsuDebugActionCheck Validate(RitsuDebugActionContext context, string payloadJson)
			{
				if (!TryDeserializePayload(payloadJson, out var payload, out var feedback))
				{
					return RitsuDebugActionCheck.Fail(feedback);
				}
				return validate(context, payload);
			}

			internal override RitsuLibSidecarPeerFeatures GetRequiredPeerFeatures(string payloadJson)
			{
				if (payloadPeerFeatures == null || !TryDeserializePayload(payloadJson, out var payload, out var _))
				{
					return base.RequiredPeerFeatures;
				}
				return base.RequiredPeerFeatures | payloadPeerFeatures(payload);
			}

			internal override Task<string> Execute(RitsuDebugActionContext context, string payloadJson)
			{
				if (!TryDeserializePayload(payloadJson, out var payload, out var feedback))
				{
					throw new RitsuDebugActionExecutionException(feedback);
				}
				return execute(context, payload);
			}

			private bool TryDeserializePayload(string payloadJson, out TPayload payload, out RitsuDebugActionFeedback feedback)
			{
				try
				{
					TPayload val = JsonSerializer.Deserialize<TPayload>(payloadJson);
					if (val == null)
					{
						payload = default(TPayload);
						feedback = RitsuDebugActionFeedback.Create("protocol.missingData", "The requested change is missing required data.");
						return false;
					}
					payload = val;
					feedback = default(RitsuDebugActionFeedback);
					return true;
				}
				catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
				{
					RitsuLibFramework.Logger.Warn($"[DebugTools] Invalid data for action '{base.ActionId}' ({typeof(TPayload).Name}): {ex}", 1);
					payload = default(TPayload);
					feedback = RitsuDebugActionFeedback.Create("protocol.invalidData", "The requested change contains invalid data.");
					return false;
				}
			}
		}

