		internal static void EnsureHandlersRegistered()
		{
			if (_requestSubscription != null && _decisionSubscription != null)
			{
				return;
			}
			RitsuDebugCardActions.RegisterBuiltInActions();
			RitsuDebugPlayerActions.RegisterBuiltInActions();
			RitsuDebugInventoryActions.RegisterBuiltInActions();
			RitsuDebugOrbActions.RegisterBuiltInActions();
			RitsuDebugCombatActions.RegisterBuiltInActions();
			RitsuDebugRunActions.RegisterBuiltInActions();
			RitsuDebugSecondaryResourceActions.RegisterBuiltInActions();
			RitsuDebugCapabilityActions.RegisterBuiltInActions();
			RitsuDebugStatePresetActions.RegisterBuiltInActions();
			using (Gate.EnterScope())
			{
				if (_requestSubscription != null && _decisionSubscription != null)
				{
					return;
				}
				RitsuLibManagedNetActions.Register(ActionDescriptor);
				IDisposable disposable = null;
				IDisposable disposable2 = null;
				try
				{
					disposable = RitsuLibSidecarTypedMessageRegistry.Subscribe(RequestDescriptor, OnClientRequest);
					disposable2 = RitsuLibSidecarTypedMessageRegistry.Subscribe(DecisionDescriptor, OnHostDecision);
					_requestSubscription = disposable;
					_decisionSubscription = disposable2;
				}
				catch
				{
					disposable2?.Dispose();
					disposable?.Dispose();
					throw;
				}
			}
		}

		internal static void Register<TPayload>(string actionId, Func<RitsuDebugActionContext, TPayload, RitsuDebugActionCheck> validate, Func<RitsuDebugActionContext, TPayload, Task<string>> execute, RitsuLibSidecarPeerFeatures requiredPeerFeatures = RitsuLibSidecarPeerFeatures.DeveloperActionsV1, Func<TPayload, RitsuLibSidecarPeerFeatures>? payloadPeerFeatures = null)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(actionId, "actionId");
			ArgumentNullException.ThrowIfNull(validate, "validate");
			ArgumentNullException.ThrowIfNull(execute, "execute");
			if (actionId.Length > 64 || actionId.Any(char.IsWhiteSpace))
			{
				throw new ArgumentException("Debug action IDs must be compact non-whitespace identifiers.", "actionId");
			}
			using (Gate.EnterScope())
			{
				if (Registrations.TryGetValue(actionId, out RegistrationBase value))
				{
					if (!(value.PayloadType == typeof(TPayload)))
					{
						throw new InvalidOperationException($"Debug action '{actionId}' is already registered with payload type {value.PayloadType}.");
					}
				}
				else
				{
					Registrations[actionId] = new Registration<TPayload>(actionId, validate, execute, requiredPeerFeatures | RitsuLibSidecarPeerFeatures.DeveloperActionsV1, payloadPeerFeatures);
				}
			}
		}

		internal static RitsuDebugActionEnvelope CreateEnvelope<TPayload>(string actionId, Player requester, Player target, TPayload payload)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(actionId, "actionId");
			ArgumentNullException.ThrowIfNull(requester, "requester");
			ArgumentNullException.ThrowIfNull(target, "target");
			return new RitsuDebugActionEnvelope(1, actionId, requester.NetId, target.NetId, JsonSerializer.Serialize(payload));
		}

		internal static RitsuDebugActionSubmission Submit(Player requester, RitsuDebugActionEnvelope envelope)
		{
			//IL_008a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0090: Invalid comparison between Unknown and I4
			ArgumentNullException.ThrowIfNull(requester, "requester");
			RitsuLibSidecarProtocol.EnsureDefaultHandlers();
			EnsureHandlersRegistered();
			if (!RitsuLibSettingsStore.AreDeveloperToolsEnabled())
			{
				return RitsuDebugActionSubmission.Reject("protocol.toolsDisabled", "RitsuLib developer tools are disabled in settings.");
			}
			envelope = envelope with
			{
				RequestedByNetId = requester.NetId
			};
			if (!TryValidateEnvelope(envelope, out var prepared, out var feedback))
			{
				return RitsuDebugActionSubmission.Reject(feedback);
			}
			RunManager instance = RunManager.Instance;
			INetGameService val = ((instance != null) ? instance.NetService : null);
			if (instance == null || val == null)
			{
				return RitsuDebugActionSubmission.Reject("protocol.startRun", "Start a run before changing its state.");
			}
			if (val != null)
			{
				if ((int)val.Type == 1)
				{
					return RequestManagedAction(instance, envelope);
				}
				NetHostGameService val2 = (NetHostGameService)(object)((val is NetHostGameService) ? val : null);
				if (val2 != null)
				{
					RitsuDebugActionFeedback feedback2;
					return (!CanHostSynchronize(val2, prepared.RequiredPeerFeatures, out feedback2)) ? RitsuDebugActionSubmission.Reject(feedback2) : RequestManagedAction(instance, envelope);
				}
				NetClientGameService val3 = (NetClientGameService)(object)((val is NetClientGameService) ? val : null);
				if (val3 != null)
				{
					return SubmitClientRequest(instance, val3, requester, envelope, prepared.RequiredPeerFeatures);
				}
			}
			return RitsuDebugActionSubmission.Reject("protocol.unsupportedGameMode", "Developer tools cannot change state in the current game mode.");
		}

		internal static bool CanHostSynchronize(NetHostGameService host, RitsuLibSidecarPeerFeatures requiredPeerFeatures, out RitsuDebugActionFeedback feedback)
		{
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_0016: Unknown result type (might be due to invalid IL or missing references)
			//IL_003c: Unknown result type (might be due to invalid IL or missing references)
			foreach (NetClientData connectedPeer in host.ConnectedPeers)
			{
				if (!connectedPeer.readyForBroadcasting)
				{
					feedback = RitsuDebugActionFeedback.Create("protocol.peerNotReady", "Another player is not ready yet; no state was changed.");
					return false;
				}
				if (!PeerSupportsFeatures(connectedPeer.peerId, requiredPeerFeatures))
				{
					feedback = RitsuDebugActionFeedback.Create("protocol.connectedPlayerUnsupported", "A connected player cannot apply developer-tool changes; no state was changed.");
					return false;
				}
			}
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}

		private static RitsuDebugActionSubmission SubmitClientRequest(RunManager runManager, NetClientGameService client, Player requester, RitsuDebugActionEnvelope envelope, RitsuLibSidecarPeerFeatures requiredPeerFeatures)
		{
			if (!PeerSupportsFeatures(client.HostNetId, requiredPeerFeatures))
			{
				return RitsuDebugActionSubmission.Reject("protocol.hostUnsupported", "The host does not support these RitsuLib developer tools; no state was changed.");
			}
			string text;
			using (Gate.EnterScope())
			{
				RemoveExpiredPendingClientRequests();
				if (PendingClientRequests.Count >= 32)
				{
					return RitsuDebugActionSubmission.Reject("protocol.tooManyPending", "Too many changes are waiting for approval. Try again later.");
				}
				text = Guid.NewGuid().ToString("N");
				PendingClientRequests.Add(text, new PendingClientRequest(envelope.ActionId, DateTimeOffset.UtcNow));
			}
			if (RitsuLibSidecarTypedMessageRegistry.SendToHost(runManager, RequestDescriptor, new RitsuDebugActionRequestMessage(text, envelope)))
			{
				return RitsuDebugActionSubmission.PendingApproval("protocol.awaitingApproval", "The host will review this change. The result will appear as a notification.");
			}
			using (Gate.EnterScope())
			{
				PendingClientRequests.Remove(text);
			}
			return RitsuDebugActionSubmission.Reject("protocol.sendFailed", "The request could not be sent to the host; no state was changed.");
		}

		private static void OnClientRequest(RitsuLibSidecarTypedDispatchContext<RitsuDebugActionRequestMessage> context)
		{
			RunManager instance = RunManager.Instance;
			INetGameService obj = ((instance != null) ? instance.NetService : null);
			NetHostGameService val = (NetHostGameService)(object)((obj is NetHostGameService) ? obj : null);
			if (val == null || !context.IsHostIngest)
			{
				return;
			}
			RitsuDebugActionRequestMessage message = context.Message;
			if (IsValidRequestId(message.RequestId))
			{
				RitsuDebugActionEnvelope envelope = message.Action with
				{
					RequestedByNetId = context.SenderNetId
				};
				RitsuDebugActionSubmission ritsuDebugActionSubmission = ((!TryReserveHostClientRequest(context.SenderNetId, message.RequestId, out var feedback)) ? RitsuDebugActionSubmission.Reject(feedback) : ((!PeerSupportsDeveloperActions(context.SenderNetId)) ? RitsuDebugActionSubmission.Reject("protocol.requesterUnsupported", "The requesting player does not support these RitsuLib developer tools.") : ((!RitsuLibSettingsStore.AreDeveloperToolsEnabled()) ? RitsuDebugActionSubmission.Reject("protocol.hostToolsDisabled", "The host has not enabled RitsuLib developer tools.") : ((!RitsuLibSettingsStore.AreDeveloperToolClientRequestsAllowed()) ? RitsuDebugActionSubmission.Reject("protocol.clientRequestsDisabled", "The host does not allow other players to request state changes.") : ((!TryValidateEnvelope(envelope, out var prepared, out var feedback2)) ? RitsuDebugActionSubmission.Reject(feedback2) : (CanHostSynchronize(val, prepared.RequiredPeerFeatures, out var feedback3) ? RequestManagedAction(instance, envelope) : RitsuDebugActionSubmission.Reject(feedback3)))))));
				if (!RitsuLibSidecarTypedMessageRegistry.SendToPeer((INetGameService?)(object)val, context.SenderNetId, DecisionDescriptor, new RitsuDebugActionDecisionMessage(message.RequestId, ritsuDebugActionSubmission.Accepted, ritsuDebugActionSubmission.Feedback)))
				{
					RitsuLibFramework.Logger.Warn($"[DebugTools] Could not return request decision to client {context.SenderNetId}.", 1);
				}
			}
		}

		private static void OnHostDecision(RitsuLibSidecarTypedDispatchContext<RitsuDebugActionDecisionMessage> context)
		{
			RunManager instance = RunManager.Instance;
			INetGameService obj = ((instance != null) ? instance.NetService : null);
			NetClientGameService val = (NetClientGameService)(object)((obj is NetClientGameService) ? obj : null);
			if (val == null || context.SenderNetId != val.HostNetId)
			{
				return;
			}
			if (!IsValidRequestId(context.Message.RequestId) || (!context.Message.Accepted && !context.Message.Feedback.IsValid()))
			{
				RitsuLibFramework.Logger.Warn("[DebugTools] Ignored an invalid host decision message.", 1);
				return;
			}
			string actionId;
			using (Gate.EnterScope())
			{
				if (!PendingClientRequests.Remove(context.Message.RequestId, out var value))
				{
					return;
				}
				actionId = value.ActionId;
			}
			string title = ModSettingsLocalization.Get("ritsulib.debugTools.toastTitle", "Developer tools");
			if (context.Message.Accepted)
			{
				RitsuLibFramework.Logger.Info("[DebugTools] Host accepted client request '" + actionId + "'.", 1);
				RitsuToastService.ShowInfo(ModSettingsLocalization.Get("ritsulib.debugTools.requestApproved", "The host approved the requested change."), title);
			}
			else
			{
				RitsuDebugActionFeedback feedback = context.Message.Feedback;
				RitsuLibFramework.Logger.Warn("[DebugTools] Host rejected client request '" + actionId + "': " + feedback.GetEnglishText(), 1);
				RitsuToastService.ShowWarning(feedback.GetLocalizedText(), title);
			}
		}

		private static RitsuDebugActionSubmission RequestManagedAction(RunManager runManager, RitsuDebugActionEnvelope envelope)
		{
			if (!RitsuLibManagedNetActions.Request(runManager, ActionDescriptor, envelope))
			{
				return RitsuDebugActionSubmission.Reject("protocol.requestRejected", "The requested change could not be accepted; no state was changed.");
			}
			return RitsuDebugActionSubmission.Success;
		}

		private static async Task ExecuteManagedActionAsync(RitsuLibManagedNetActionContext<RitsuDebugActionEnvelope> managedContext)
		{
			if (!IsAuthorizedManagedActionOwner(managedContext.Player))
			{
				RitsuLibFramework.Logger.Warn($"[DebugTools] Rejected non-host action owner {managedContext.Player.NetId}.", 1);
				NotifyActionExecuted(managedContext.Message, success: false, RitsuDebugActionFeedback.Create("protocol.hostOnlyApproval", "Only the host can approve this change; no state was changed."));
				return;
			}
			if (!TryValidateEnvelope(managedContext.Message, out var prepared, out var feedback))
			{
				RitsuLibFramework.Logger.Warn("[DebugTools] Rejected synchronized action: " + feedback.GetEnglishText(), 1);
				NotifyActionExecuted(managedContext.Message, success: false, feedback);
				return;
			}
			string value;
			try
			{
				value = await prepared.Registration.Execute(prepared.Context, managedContext.Message.PayloadJson);
			}
			catch (RitsuDebugActionExecutionException ex)
			{
				NotifyActionExecuted(managedContext.Message, success: false, ex.Feedback);
				throw;
			}
			catch (Exception ex2) when (RitsuLibExceptionPolicy.IsRecoverable(ex2))
			{
				RitsuLibFramework.Logger.Warn($"[DebugTools] Unexpected failure while applying '{managedContext.Message.ActionId}': {ex2}", 1);
				NotifyActionExecuted(managedContext.Message, success: false, RitsuDebugActionFeedback.Create("protocol.executionFailed", "The requested change could not be completed. See the game log for details."));
				throw;
			}
			RitsuLibFramework.Logger.Info($"[DebugTools] Executed '{managedContext.Message.ActionId}' requestedBy={prepared.Context.Requester.NetId} target={prepared.Context.Target.NetId}: {value}", 1);
			NotifyActionExecuted(managedContext.Message, success: true, default(RitsuDebugActionFeedback));
		}

		private static void NotifyActionExecuted(RitsuDebugActionEnvelope envelope, bool success, RitsuDebugActionFeedback feedback)
		{
			if (!success)
			{
				RunManager instance = RunManager.Instance;
				ulong? obj;
				if (instance == null)
				{
					obj = null;
				}
				else
				{
					INetGameService netService = instance.NetService;
					obj = ((netService != null) ? new ulong?(netService.NetId) : ((ulong?)null));
				}
				if (obj == envelope.RequestedByNetId)
				{
					RitsuToastService.ShowError(feedback.GetLocalizedText(), ModSettingsLocalization.Get("ritsulib.debugTools.toastTitle", "Developer tools"));
				}
			}
			Action<RitsuDebugActionExecutionResult> actionExecuted = ActionExecuted;
			if (actionExecuted == null)
			{
				return;
			}
			RitsuDebugActionExecutionResult obj2 = new RitsuDebugActionExecutionResult(envelope.ActionId, envelope.RequestedByNetId, envelope.TargetPlayerNetId, envelope.PayloadJson, success, feedback);
			foreach (Action<RitsuDebugActionExecutionResult> item in actionExecuted.GetInvocationList().OfType<Action<RitsuDebugActionExecutionResult>>())
			{
				try
				{
					item(obj2);
				}
				catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
				{
					RitsuLibFramework.Logger.Warn($"[DebugTools] Execution-result subscriber failed: {ex}", 1);
				}
			}
		}

		private static bool TryValidateEnvelope(RitsuDebugActionEnvelope envelope, out PreparedAction prepared, out RitsuDebugActionFeedback feedback)
		{
			prepared = default(PreparedAction);
			if (envelope.ProtocolVersion != 1)
			{
				feedback = RitsuDebugActionFeedback.Create("protocol.incompatibleVersion", "This change requires a compatible RitsuLib version on every player.");
				return false;
			}
			if (string.IsNullOrWhiteSpace(envelope.ActionId) || envelope.ActionId.Length > 64 || envelope.ActionId.Any(char.IsWhiteSpace))
			{
				feedback = RitsuDebugActionFeedback.Create("protocol.invalidAction", "The requested change is invalid.");
				return false;
			}
			if (envelope.PayloadJson == null || envelope.PayloadJson.Length > 8192)
			{
				feedback = RitsuDebugActionFeedback.Create("protocol.excessiveData", "The requested change contains invalid or excessive data.");
				return false;
			}
			RegistrationBase value;
			using (Gate.EnterScope())
			{
				if (!Registrations.TryGetValue(envelope.ActionId, out value))
				{
					feedback = RitsuDebugActionFeedback.Create("protocol.unsupportedAction", "This RitsuLib version does not support the requested change.");
					return false;
				}
			}
			RunManager instance = RunManager.Instance;
			RunState val = ((instance != null) ? instance.DebugOnlyGetState() : null);
			if (instance == null || val == null || !instance.IsInProgress)
			{
				feedback = RitsuDebugActionFeedback.Create("run.notInProgress", "A run is not currently in progress.");
				return false;
			}
			Player val2 = val.Players.FirstOrDefault((Player player) => player.NetId == envelope.RequestedByNetId);
			if (val2 == null)
			{
				feedback = RitsuDebugActionFeedback.Create("protocol.requesterUnavailable", "The player requesting this change is no longer in the run.");
				return false;
			}
			Player val3 = val.Players.FirstOrDefault((Player player) => player.NetId == envelope.TargetPlayerNetId);
			if (val3 == null)
			{
				feedback = RitsuDebugActionFeedback.Create("protocol.targetUnavailable", "The selected player is no longer in the run.");
				return false;
			}
			RitsuDebugActionContext context = new RitsuDebugActionContext(val2, val3);
			RitsuDebugActionCheck ritsuDebugActionCheck = value.Validate(context, envelope.PayloadJson);
			if (!ritsuDebugActionCheck.Success)
			{
				feedback = ritsuDebugActionCheck.Feedback;
				return false;
			}
			prepared = new PreparedAction(value, context, value.GetRequiredPeerFeatures(envelope.PayloadJson));
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}

		private static bool IsAuthorizedManagedActionOwner(Player owner)
		{
			//IL_0016: Unknown result type (might be due to invalid IL or missing references)
			//IL_001b: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0020: Invalid comparison between Unknown and I4
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_0025: Invalid comparison between Unknown and I4
			RunManager instance = RunManager.Instance;
			INetGameService val = ((instance != null) ? instance.NetService : null);
			if (val != null)
			{
				NetGameType type = val.Type;
				if ((int)type == 1)
				{
					return owner.NetId == val.NetId;
				}
				if ((int)type == 4)
				{
					return true;
				}
				NetHostGameService val2 = (NetHostGameService)(object)((val is NetHostGameService) ? val : null);
				if (val2 != null)
				{
					return owner.NetId == val2.NetId;
				}
				NetClientGameService val3 = (NetClientGameService)(object)((val is NetClientGameService) ? val : null);
				if (val3 != null)
				{
					return owner.NetId == val3.HostNetId;
				}
			}
			return false;
		}

		private static bool PeerSupportsDeveloperActions(ulong peerNetId)
		{
			return PeerSupportsFeatures(peerNetId, RitsuLibSidecarPeerFeatures.DeveloperActionsV1);
		}

		private static bool PeerSupportsFeatures(ulong peerNetId, RitsuLibSidecarPeerFeatures requiredPeerFeatures)
		{
			if (RitsuLibSidecarSessionManager.TryGetPeerFeatures(peerNetId, out var features))
			{
				return (features & requiredPeerFeatures) == requiredPeerFeatures;
			}
			return false;
		}

		private static bool IsValidRequestId(string? requestId)
		{
			Guid result;
			if (requestId != null && requestId.Length == 32)
			{
				return Guid.TryParseExact(requestId, "N", out result);
			}
			return false;
		}

		private static void RemoveExpiredPendingClientRequests()
		{
			DateTimeOffset cutoff = DateTimeOffset.UtcNow - TimeSpan.FromSeconds(30L);
			string[] array = (from pair in PendingClientRequests
				where pair.Value.CreatedAtUtc < cutoff
				select pair.Key).ToArray();
			foreach (string key in array)
			{
				PendingClientRequests.Remove(key);
			}
		}

		private static bool TryReserveHostClientRequest(ulong senderNetId, string requestId, out RitsuDebugActionFeedback feedback)
		{
			DateTimeOffset utcNow = DateTimeOffset.UtcNow;
			DateTimeOffset rateCutoff = utcNow - TimeSpan.FromSeconds(5L);
			DateTimeOffset retentionCutoff = utcNow - TimeSpan.FromSeconds(30L);
			HostClientRequestKey key = new HostClientRequestKey(senderNetId, requestId);
			using (Gate.EnterScope())
			{
				HostClientRequestKey[] array = (from pair in RecentHostClientRequests
					where pair.Value < retentionCutoff
					select pair.Key).ToArray();
				foreach (HostClientRequestKey key2 in array)
				{
					RecentHostClientRequests.Remove(key2);
				}
				if (RecentHostClientRequests.ContainsKey(key))
				{
					feedback = RitsuDebugActionFeedback.Create("protocol.requestAlreadyHandled", "This request was already handled; no state was changed.");
					return false;
				}
				if (RecentHostClientRequests.Count >= 256 || RecentHostClientRequests.Count((KeyValuePair<HostClientRequestKey, DateTimeOffset> pair) => pair.Key.SenderNetId == senderNetId && pair.Value >= rateCutoff) >= 16)
				{
					feedback = RitsuDebugActionFeedback.Create("protocol.rateLimited", "Too many changes were requested recently. Try again in a few seconds.");
					return false;
				}
				RecentHostClientRequests.Add(key, utcNow);
			}
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}

		private static T Deserialize<T>(ReadOnlySpan<byte> payload)
		{
			T val = JsonSerializer.Deserialize<T>(payload);
			if (val == null)
			{
				throw new InvalidOperationException($"Failed to deserialize debug-tools payload {typeof(T)}.");
			}
			return val;
		}
