		internal static bool TryResolveTarget(Player target, RitsuDebugCapabilityTarget reference, out AbstractModel model, out RitsuDebugActionFeedback feedback)
		{
			model = null;
			if (!IsValidTargetReference(reference))
			{
				feedback = RitsuDebugActionFeedback.Create("capability.targetInvalid", "The selected capability target is invalid.");
				return false;
			}
			return reference.Kind switch
			{
				RitsuDebugCapabilityTargetKind.Character => TryResolveCharacter(target, reference, out model, out feedback), 
				RitsuDebugCapabilityTargetKind.Card => TryResolveCard(target, reference, out model, out feedback), 
				RitsuDebugCapabilityTargetKind.Relic => TryResolveRelic(target, reference, out model, out feedback), 
				RitsuDebugCapabilityTargetKind.Potion => TryResolvePotion(target, reference, out model, out feedback), 
				RitsuDebugCapabilityTargetKind.Power => TryResolvePower(reference, out model, out feedback), 
				RitsuDebugCapabilityTargetKind.Orb => TryResolveOrb(target, reference, out model, out feedback), 
				RitsuDebugCapabilityTargetKind.Enchantment => TryResolveCardAttachment(target, reference, enchantment: true, out model, out feedback), 
				RitsuDebugCapabilityTargetKind.Affliction => TryResolveCardAttachment(target, reference, enchantment: false, out model, out feedback), 
				RitsuDebugCapabilityTargetKind.Monster => TryResolveMonster(reference, out model, out feedback), 
				_ => FailTarget(out feedback), 
			};
		}

		internal static bool IsValidTargetReference(RitsuDebugCapabilityTarget reference)
		{
			if (!Enum.IsDefined(reference.Kind) || string.IsNullOrWhiteSpace(reference.ModelId) || reference.ModelId.Length > 128)
			{
				return false;
			}
			int result;
			PileType pileType;
			int result2;
			switch (reference.Kind)
			{
			case RitsuDebugCapabilityTargetKind.Character:
				return reference.Index == -1 && reference.Pile == null && !reference.CreatureCombatId.HasValue && reference.ContainerModelId == null;
			case RitsuDebugCapabilityTargetKind.Card:
				if (reference.Index >= 0)
				{
					string pile = reference.Pile;
					if (pile != null && !reference.CreatureCombatId.HasValue && reference.ContainerModelId == null)
					{
						result = (RitsuDebugCardActions.TryParseMutablePileType(pile, out pileType) ? 1 : 0);
						goto IL_00dd;
					}
				}
				result = 0;
				goto IL_00dd;
			case RitsuDebugCapabilityTargetKind.Relic:
			case RitsuDebugCapabilityTargetKind.Potion:
			case RitsuDebugCapabilityTargetKind.Orb:
				return reference.Index >= 0 && reference.Pile == null && !reference.CreatureCombatId.HasValue && reference.ContainerModelId == null;
			case RitsuDebugCapabilityTargetKind.Power:
				return reference.Index >= 0 && reference.Pile == null && reference.CreatureCombatId.HasValue && reference.ContainerModelId == null;
			case RitsuDebugCapabilityTargetKind.Enchantment:
			case RitsuDebugCapabilityTargetKind.Affliction:
				if (reference.Index >= 0)
				{
					string pile2 = reference.Pile;
					if (pile2 != null && !reference.CreatureCombatId.HasValue)
					{
						string containerModelId = reference.ContainerModelId;
						if (containerModelId != null && RitsuDebugCardActions.TryParseMutablePileType(pile2, out pileType) && !string.IsNullOrWhiteSpace(containerModelId))
						{
							result2 = ((containerModelId.Length <= 128) ? 1 : 0);
							goto IL_01aa;
						}
					}
				}
				result2 = 0;
				goto IL_01aa;
