		private static RitsuDebugActionCheck ValidateModify(RitsuDebugActionContext context, ModifyCapabilityPayload payload)
		{
			if (!Enum.IsDefined(payload.Operation))
			{
				return RitsuDebugActionCheck.Fail("capability.operationInvalid", "The requested capability operation is invalid.");
			}
			if (!TryResolveTarget(context.Target, payload.Target, out AbstractModel model, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			ModelCapabilitySet modelCapabilitySet = ModelCapabilities.Get(model);
			IModelCapability capability;
			return payload.Operation switch
			{
				RitsuDebugCapabilityOperation.Add => ValidateAdd(payload.CapabilityId, model, modelCapabilitySet), 
				RitsuDebugCapabilityOperation.Remove => TryResolveCapability(modelCapabilitySet, payload.CapabilityId, payload.CapabilityIndex, out capability, out feedback) ? RitsuDebugActionCheck.Ok : RitsuDebugActionCheck.Fail(feedback), 
				RitsuDebugCapabilityOperation.Clear => (modelCapabilitySet.Count == 0) ? RitsuDebugActionCheck.Fail("capability.noneAttached", "The selected model has no attached capabilities.") : RitsuDebugActionCheck.Ok, 
				_ => RitsuDebugActionCheck.Fail("capability.operationInvalid", "The requested capability operation is invalid."), 
			};
		}

		private static RitsuDebugActionCheck ValidateAdd(string? capabilityId, AbstractModel model, ModelCapabilitySet capabilities)
		{
			if (string.IsNullOrWhiteSpace(capabilityId) || capabilityId.Length > 128 || !ModelCapabilityRegistry.TryGetCapabilityType(capabilityId, out Type capabilityType))
			{
				return RitsuDebugActionCheck.Fail("capability.unknown", "Unknown capability '{0}'.", capabilityId ?? string.Empty);
			}
			if (!ModelCapabilityRegistry.IsCompatibleWith(capabilityType, model))
			{
				return RitsuDebugActionCheck.Fail("capability.incompatible", "Capability '{0}' cannot attach to the selected model.", capabilityId);
			}
			if (capabilities.Count < 256)
			{
				return RitsuDebugActionCheck.Ok;
			}
			return RitsuDebugActionCheck.Fail("capability.limit", "A model cannot have more than {0} capabilities through developer tools.", 256);
		}

		private static Task<string> ExecuteModifyAsync(RitsuDebugActionContext context, ModifyCapabilityPayload payload)
		{
			TryResolveTarget(context.Target, payload.Target, out AbstractModel model, out RitsuDebugActionFeedback _);
			ModelCapabilitySet capabilities = ModelCapabilities.Get(model);
			object result = payload.Operation switch
			{
				RitsuDebugCapabilityOperation.Add => AddCapability(capabilities, payload.CapabilityId), 
				RitsuDebugCapabilityOperation.Remove => RemoveCapability(capabilities, payload.CapabilityId, payload.CapabilityIndex), 
				RitsuDebugCapabilityOperation.Clear => ClearCapabilities(capabilities), 
				_ => throw new ArgumentOutOfRangeException("payload"), 
			};
			RequestVisualReload(context.Target, payload.Target, model);
			return Task.FromResult((string)result);
		}

		private static void RequestVisualReload(Player target, RitsuDebugCapabilityTarget reference, AbstractModel model)
		{
			CardModel val = (CardModel)(object)((model is CardModel) ? model : null);
			if (val == null)
