				if (val2 == null)
				{
					PotionModel val3 = (PotionModel)(object)((model is PotionModel) ? model : null);
					if (val3 == null)
					{
						PowerModel val4 = (PowerModel)(object)((model is PowerModel) ? model : null);
						if (val4 == null)
						{
							OrbModel val5 = (OrbModel)(object)((model is OrbModel) ? model : null);
							if (val5 != null)
							{
								val5.RequestVisualReload();
								return;
							}
							RitsuDebugCapabilityTargetKind kind = reference.Kind;
							if ((uint)(kind - 6) <= 1u)
							{
								RitsuDebugCapabilityTarget reference2 = new RitsuDebugCapabilityTarget(RitsuDebugCapabilityTargetKind.Card, reference.ContainerModelId, reference.Index, reference.Pile);
								if (TryResolveCard(target, reference2, out AbstractModel model2, out RitsuDebugActionFeedback _))
								{
									((CardModel)(object)((model2 is CardModel) ? model2 : null))?.RequestVisualReload();
								}
							}
						}
						else
						{
							val4.RequestVisualReload();
						}
					}
					else
					{
						val3.RequestVisualReload();
					}
				}
				else
				{
					val2.RequestVisualReload();
				}
			}
			else
			{
				val.RequestVisualReload();
			}
		}

		private static string AddCapability(ModelCapabilitySet capabilities, string capabilityId)
		{
			IModelCapability incoming = ModelCapabilityRegistry.Create(capabilityId);
			capabilities.Apply(incoming);
			return $"Applied capability {capabilityId} to {capabilities.Owner.Id}.";
		}

		private static string RemoveCapability(ModelCapabilitySet capabilities, string capabilityId, int capabilityIndex)
		{
			TryResolveCapability(capabilities, capabilityId, capabilityIndex, out IModelCapability capability, out RitsuDebugActionFeedback _);
			capabilities.Remove(capability);
			return $"Removed capability {capabilityId} from {capabilities.Owner.Id}.";
		}

		private static string ClearCapabilities(ModelCapabilitySet capabilities)
		{
			int count = capabilities.Count;
			capabilities.Clear();
			return $"Removed {count} capabilities from {capabilities.Owner.Id}.";
		}

		private static bool TryResolveCapability(ModelCapabilitySet capabilities, string? capabilityId, int capabilityIndex, out IModelCapability capability, out RitsuDebugActionFeedback feedback)
		{
			capability = null;
			if (string.IsNullOrWhiteSpace(capabilityId) || capabilityId.Length > 128 || capabilityIndex < 0 || capabilityIndex >= capabilities.Count)
			{
				feedback = RitsuDebugActionFeedback.Create("capability.selectionChanged", "The selected capability is no longer available.");
				return false;
			}
			IModelCapability modelCapability = capabilities.All[capabilityIndex];
			if (!string.Equals(modelCapability.CapabilityId, capabilityId, StringComparison.Ordinal))
			{
				feedback = RitsuDebugActionFeedback.Create("capability.selectionChanged", "The selected capability is no longer available.");
				return false;
			}
			capability = modelCapability;
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}

		private static bool TryResolveCharacter(Player target, RitsuDebugCapabilityTarget reference, out AbstractModel model, out RitsuDebugActionFeedback feedback)
