		internal static void RegisterBuiltInActions()
		{
			RitsuDebugActionProtocol.Register("cards.pile.modify", ValidateModifyPile, ExecuteModifyPileAsync, RitsuLibSidecarPeerFeatures.DeveloperActionsV1, (ModifyPilePayload payload) => FeaturesForPileToken(payload.Pile));
			RitsuDebugActionProtocol.Register("cards.create", ValidateCreateCard, ExecuteCreateCardAsync, RitsuLibSidecarPeerFeatures.DeveloperActionsV1, (CreateCardPayload payload) => FeaturesForPileToken(payload.Pile));
			RitsuDebugActionProtocol.Register("cards.copy", ValidateCopyCard, ExecuteCopyCardAsync, RitsuLibSidecarPeerFeatures.DeveloperActionsV1, (CopyCardPayload payload) => FeaturesForPileToken(payload.Location.Pile) | FeaturesForPileToken(payload.DestinationPile));
			RitsuDebugActionProtocol.Register("cards.move", ValidateMoveCard, ExecuteMoveCardAsync, RitsuLibSidecarPeerFeatures.DeveloperActionsV1, (MoveCardPayload payload) => FeaturesForPileToken(payload.Location.Pile) | FeaturesForPileToken(payload.DestinationPile));
			RitsuDebugActionProtocol.Register("cards.reorder", ValidateReorderCard, ExecuteReorderCardAsync, (RitsuLibSidecarPeerFeatures)128u, (ReorderCardPayload payload) => FeaturesForPileToken(payload.Location.Pile));
			RitsuDebugActionProtocol.Register("cards.set-replay", ValidateSetReplayCount, ExecuteSetReplayCountAsync, RitsuLibSidecarPeerFeatures.DeveloperActionsV1, (SetReplayCountPayload payload) => FeaturesForPileToken(payload.Location.Pile));
			RitsuDebugActionProtocol.Register("cards.remove", ValidateCardLocation, ExecuteRemoveCardAsync, RitsuLibSidecarPeerFeatures.DeveloperActionsV1, (CardLocationPayload payload) => FeaturesForPileToken(payload.Pile));
			RitsuDebugActionProtocol.Register("cards.edit", ValidateEditCard, ExecuteEditCardAsync, RitsuLibSidecarPeerFeatures.DeveloperActionsV1, (EditCardPayload payload) => FeaturesForPileToken(payload.Location.Pile));
			RitsuDebugActionProtocol.Register("cards.enchant", ValidateEnchantCard, ExecuteEnchantCardAsync, RitsuLibSidecarPeerFeatures.DeveloperActionsV1, (EnchantCardPayload payload) => FeaturesForPileToken(payload.Location.Pile));
			RitsuDebugActionProtocol.Register("cards.enchantment.clear", ValidateClearCardEnchantment, ExecuteClearCardEnchantmentAsync, RitsuLibSidecarPeerFeatures.DeveloperActionsV1, (CardLocationPayload payload) => FeaturesForPileToken(payload.Pile));
			RitsuDebugActionProtocol.Register("cards.upgrade", ValidateUpgradeCard, ExecuteUpgradeCardAsync, RitsuLibSidecarPeerFeatures.DeveloperActionsV1, (UpgradeCardPayload payload) => FeaturesForPileToken(payload.Location.Pile));
			RitsuDebugActionProtocol.Register("cards.upgrade.set", ValidateSetUpgradeLevel, ExecuteSetUpgradeLevelAsync, RitsuLibSidecarPeerFeatures.DeveloperActionsV1, (UpgradeCardPayload payload) => FeaturesForPileToken(payload.Location.Pile));
		}

