		internal static bool TryResolveEnchantment(string input, out EnchantmentModel enchantment, out RitsuDebugActionFeedback feedback)
		{
			enchantment = null;
			if (string.IsNullOrWhiteSpace(input) || input.Length > 128)
			{
				feedback = RitsuDebugActionFeedback.Create("model.enchantmentIdInvalid", "The enchantment ID is empty or too long.");
				return false;
			}
			EnchantmentModel[] array = ModelDb.DebugEnchantments.Where((EnchantmentModel candidate) => ((object)((AbstractModel)candidate).Id).ToString().Equals(input, StringComparison.OrdinalIgnoreCase)).Take(2).ToArray();
			EnchantmentModel[] array2 = ((array.Length != 0) ? array : ModelDb.DebugEnchantments.Where((EnchantmentModel candidate) => ((AbstractModel)candidate).Id.Entry.Equals(input, StringComparison.OrdinalIgnoreCase)).Take(2).ToArray());
			if (array2.Length == 1)
			{
				enchantment = array2[0];
				feedback = default(RitsuDebugActionFeedback);
				return true;
			}
			feedback = ((array2.Length == 0) ? RitsuDebugActionFeedback.Create("model.enchantmentUnknown", "Unknown enchantment '{0}'.", input) : RitsuDebugActionFeedback.Create("model.enchantmentAmbiguous", "The enchantment ID '{0}' is ambiguous; use the full model ID.", input));
			return false;
		}

		internal static bool TryParseMutablePileType(string input, out PileType pileType)
		{
			//IL_0033: Unknown result type (might be due to invalid IL or missing references)
			//IL_0039: Expected I4, but got Unknown
			if (string.IsNullOrWhiteSpace(input))
			{
				pileType = (PileType)0;
				return false;
			}
			if (Enum.TryParse<PileType>(input, true, out pileType) && Enumerable.Contains(VanillaMutablePileTypes, pileType))
			{
				return true;
			}
			if (ModCardPileRegistry.TryGet(input, out ModCardPileDefinition definition))
			{
				pileType = (PileType)(int)definition.PileType;
				return true;
			}
			pileType = (PileType)0;
			return false;
		}

		internal static string[] GetMutablePileNames()
		{
			return GetMutablePileTypes().Select(GetPileToken).ToArray();
		}

		internal static PileType[] GetMutablePileTypes()
		{
			ModCardPileDefinition[] definitionsSnapshot = ModCardPileRegistry.GetDefinitionsSnapshot();
			List<PileType> list = new List<PileType>();
			list.AddRange(VanillaMutablePileTypes.Where(delegate(PileType pileType)
			{
				//IL_0000: Unknown result type (might be due to invalid IL or missing references)
				//IL_0002: Invalid comparison between Unknown and I4
				return (int)pileType != 6;
			}));
			list.AddRange(definitionsSnapshot.Where((ModCardPileDefinition definition) => definition.Scope == ModCardPileScope.CombatOnly).Select(delegate(ModCardPileDefinition definition)
			{
				//IL_0001: Unknown result type (might be due to invalid IL or missing references)
				return definition.PileType;
			}));
			list.Add((PileType)6);
			list.AddRange(definitionsSnapshot.Where((ModCardPileDefinition definition) => definition.Scope == ModCardPileScope.RunPersistent).Select(delegate(ModCardPileDefinition definition)
			{
				//IL_0001: Unknown result type (might be due to invalid IL or missing references)
				return definition.PileType;
			}));
			return list.ToArray();
		}

		internal unsafe static string GetPileToken(PileType pileType)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			if (!ModCardPileRegistry.TryGetId(pileType, out string id))
			{
				return ((object)(*(PileType*)(&pileType))/*cast due to constrained. prefix*/).ToString();
			}
			return id;
		}

		internal static bool IsRunStatePile(PileType pileType)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0002: Invalid comparison between Unknown and I4
			//IL_0004: Unknown result type (might be due to invalid IL or missing references)
			if ((int)pileType != 6)
			{
				if (ModCardPileRegistry.TryGetByPileType(pileType, out ModCardPileDefinition definition))
				{
					return definition.Scope == ModCardPileScope.RunPersistent;
				}
				return false;
			}
			return true;
		}

		internal static CardPile? GetPile(Player player, PileType pileType)
		{
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_0017: Unknown result type (might be due to invalid IL or missing references)
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			if (!Enumerable.Contains(VanillaMutablePileTypes, pileType) && !ModCardPileRegistry.IsModPileType(pileType))
			{
				return null;
			}
			return CardPile.Get(pileType, player);
		}

		internal static CardPile? GetExistingPile(Player player, PileType pileType)
		{
			//IL_0007: Unknown result type (might be due to invalid IL or missing references)
			//IL_0008: Unknown result type (might be due to invalid IL or missing references)
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			//IL_002d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0020: Unknown result type (might be due to invalid IL or missing references)
			if (Enumerable.Contains(VanillaMutablePileTypes, pileType))
			{
				return CardPile.Get(pileType, player);
			}
			if (!ModCardPileRegistry.TryGetByPileType(pileType, out ModCardPileDefinition definition))
			{
				return null;
			}
			switch (definition.Scope)
			{
			case ModCardPileScope.CombatOnly:
			{
				PlayerCombatState playerCombatState = player.PlayerCombatState;
				if (playerCombatState != null)
				{
					return (CardPile?)(object)ModCardPileStorage.GetCombatPiles(playerCombatState).FirstOrDefault(delegate(ModCardPile pile)
					{
						//IL_0001: Unknown result type (might be due to invalid IL or missing references)
						//IL_0007: Unknown result type (might be due to invalid IL or missing references)
						return ((CardPile)pile).Type == pileType;
					});
				}
				break;
			}
			case ModCardPileScope.RunPersistent:
				return (CardPile?)(object)ModCardPileStorage.GetRunPiles(player).FirstOrDefault(delegate(ModCardPile pile)
				{
					//IL_0001: Unknown result type (might be due to invalid IL or missing references)
					//IL_0007: Unknown result type (might be due to invalid IL or missing references)
					return ((CardPile)pile).Type == pileType;
				});
			}
			return null;
		}

		internal static uint? GetCombatCardId(CardModel card)
		{
			CardPile pile = card.Pile;
			if (pile == null || !pile.IsCombatPile || !((AbstractModel)card).IsMutable)
			{
				return null;
			}
			uint value = default(uint);
			if (!NetCombatCardDb.Instance.TryGetCardId(card, ref value))
			{
				return null;
			}
			return value;
		}

		internal static bool TryResolveCanonicalCard(string cardId, out CardModel card, out RitsuDebugActionFeedback feedback)
		{
			card = null;
			if (string.IsNullOrWhiteSpace(cardId) || cardId.Length > 128)
			{
				feedback = RitsuDebugActionFeedback.Create("model.cardIdInvalid", "The card ID is empty or too long.");
				return false;
			}
			CardModel[] array = ModelDb.AllCards.Where((CardModel candidate) => ((object)((AbstractModel)candidate).Id).ToString().Equals(cardId, StringComparison.OrdinalIgnoreCase)).Take(2).ToArray();
			if (array.Length == 1)
			{
				card = array[0];
				feedback = default(RitsuDebugActionFeedback);
				return true;
			}
			CardModel[] array2 = ModelDb.AllCards.Where((CardModel candidate) => ((AbstractModel)candidate).Id.Entry.Equals(cardId, StringComparison.OrdinalIgnoreCase)).Take(2).ToArray();
			if (array2.Length == 1)
			{
				card = array2[0];
				feedback = default(RitsuDebugActionFeedback);
				return true;
			}
			feedback = ((array2.Length > 1 || array.Length > 1) ? RitsuDebugActionFeedback.Create("model.cardAmbiguous", "Card ID '{0}' is ambiguous; use the full model ID.", cardId) : RitsuDebugActionFeedback.Create("model.cardUnknown", "Card '{0}' was not found.", cardId));
			return false;
		}

		internal static RitsuDebugActionCheck ValidateModifyPile(RitsuDebugActionContext context, ModifyPilePayload payload)
		{
			//IL_0053: Unknown result type (might be due to invalid IL or missing references)
			//IL_0055: Invalid comparison between Unknown and I4
			//IL_0075: Unknown result type (might be due to invalid IL or missing references)
			//IL_008f: Unknown result type (might be due to invalid IL or missing references)
			if (!Enum.IsDefined(payload.Operation))
			{
				return RitsuDebugActionCheck.Fail("card.invalidPileOperation", "The card-pile operation is invalid.");
			}
			if (!TryParseMutablePileType(payload.Pile, out var pileType))
			{
				return RitsuDebugActionCheck.Fail("card.unsupportedPile", "Unsupported pile '{0}'.", payload.Pile);
			}
			if ((int)pileType != 6 && !TryRequireActiveCombat(context.Target, out var feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (GetPile(context.Target, pileType) == null)
			{
				return RitsuDebugActionCheck.Fail("card.pileUnavailable", "Pile '{0}' is unavailable for the selected player.", pileType);
			}
			switch (payload.Operation)
			{
			case RitsuDebugCardPileOperation.Clear:
				if (payload.Levels == 0)
				{
					return RitsuDebugActionCheck.Ok;
				}
				return RitsuDebugActionCheck.Fail("card.clearPileUpgradeLevels", "Clearing a card pile does not accept upgrade levels.");
			case RitsuDebugCardPileOperation.Upgrade:
			{
				int levels = payload.Levels;
				if (levels >= 1 && levels <= 99)
				{
					return RitsuDebugActionCheck.Ok;
				}
				return RitsuDebugActionCheck.Fail("card.upgradeLevelsRange", "Upgrade levels must be between 1 and {0}.", 99);
			}
			default:
				return RitsuDebugActionCheck.Fail("card.invalidPileOperation", "The card-pile operation is invalid.");
			}
		}

		internal static async Task<string> ExecuteModifyPileAsync(RitsuDebugActionContext context, ModifyPilePayload payload)
		{
			TryParseMutablePileType(payload.Pile, out var pileType);
			CardPile pile = GetPile(context.Target, pileType);
			CardModel[] cards = pile.Cards.ToArray();
			if (payload.Operation == RitsuDebugCardPileOperation.Clear)
			{
				if ((int)pileType == 6)
				{
					await CardPileCmd.RemoveFromDeck((IReadOnlyList<CardModel>)cards, false);
				}
				else if (!IsRunStatePile(pileType))
				{
					await CardPileCmd.RemoveFromCombat((IEnumerable<CardModel>)cards, false);
				}
				else
				{
					RemoveRunStateCards(cards);
				}
				return (cards.Length == 1) ? $"Removed 1 card from {pileType}." : $"Removed {cards.Length} cards from {pileType}.";
			}
			int num = 0;
			CardModel[] array = cards;
			foreach (CardModel val in array)
			{
				int currentUpgradeLevel = val.CurrentUpgradeLevel;
				ApplyAvailableUpgradeLevels(val, payload.Levels);
				if (val.CurrentUpgradeLevel > currentUpgradeLevel)
				{
					num++;
					val.RequestVisualReload();
				}
			}
			return (num == 1) ? $"Upgraded 1 card in {pileType}." : $"Upgraded {num} cards in {pileType}.";
		}

		internal static RitsuDebugActionCheck ValidateCreateCard(RitsuDebugActionContext context, CreateCardPayload payload)
		{
			//IL_00fa: Unknown result type (might be due to invalid IL or missing references)
			//IL_0121: Unknown result type (might be due to invalid IL or missing references)
			//IL_013b: Unknown result type (might be due to invalid IL or missing references)
			if (!TryParseMutablePileType(payload.Pile, out var pileType))
			{
				return RitsuDebugActionCheck.Fail("card.unsupportedPile", "Unsupported pile '{0}'.", payload.Pile);
			}
			if (!TryResolveCanonicalCard(payload.CardId, out CardModel card, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			int count = payload.Count;
			if ((count < 1 || count > 100) ? true : false)
			{
				return RitsuDebugActionCheck.Fail("card.createCountRange", "Card count must be between 1 and {0}.", 100);
			}
			if (payload.UpgradeLevels < 0 || payload.UpgradeLevels > card.MaxUpgradeLevel)
			{
				return RitsuDebugActionCheck.Fail("card.createUpgradeRange", "Upgrade levels for {0} must be between 0 and {1}.", ((AbstractModel)card).Id, card.MaxUpgradeLevel);
			}
			CardModel card2 = card.ToMutable();
			ApplyUpgradeLevels(card2, payload.UpgradeLevels);
			RitsuDebugActionCheck result = ValidateCardState(card2, payload.State);
			if (!result.Success)
			{
				return result;
			}
			if (!IsRunStatePile(pileType) && !TryRequireActiveCombat(context.Target, out var feedback2))
			{
				return RitsuDebugActionCheck.Fail(feedback2);
			}
			if (GetPile(context.Target, pileType) == null)
			{
				return RitsuDebugActionCheck.Fail("card.pileUnavailable", "Pile '{0}' is unavailable for the selected player.", pileType);
			}
			return RitsuDebugActionCheck.Ok;
		}

		internal static async Task<string> ExecuteCreateCardAsync(RitsuDebugActionContext context, CreateCardPayload payload)
		{
			return await ExecuteCreateCardAsync(context, payload, previewDeckAdds: true);
		}

		internal static async Task<string> ExecuteCreateCardAsync(RitsuDebugActionContext context, CreateCardPayload payload, bool previewDeckAdds)
		{
			TryParseMutablePileType(payload.Pile, out var pileType);
			TryResolveCanonicalCard(payload.CardId, out CardModel canonical, out RitsuDebugActionFeedback _);
			if (IsRunStatePile(pileType))
			{
				for (int index = 0; index < payload.Count; index++)
				{
					CardModel obj = ((ICardScope)context.Target.RunState).CreateCard(canonical, context.Target);
					ApplyUpgradeLevels(obj, payload.UpgradeLevels);
					ApplyCardState(obj, payload.State);
					CardPileAddResult val = await CardPileCmd.Add(obj, (PileType)6, (CardPilePosition)1, (AbstractModel)null, false);
					if (!val.success)
					{
						throw new RitsuDebugActionExecutionException(RitsuDebugActionFeedback.Create("card.addToDeckFailed", "The game did not add {0} to the deck.", ((AbstractModel)canonical).Id));
					}
					if (previewDeckAdds && (int)pileType == 6)
					{
						CardCmd.PreviewCardPileAdd(val, 1.2f, (CardPreviewStyle)1);
					}
				}
				string pileToken = GetPileToken(pileType);
				return (payload.Count == 1) ? $"Created {((AbstractModel)canonical).Id} in {pileToken}." : $"Created {payload.Count} copies of {((AbstractModel)canonical).Id} in {pileToken}.";
			}
			ICombatState combatState = context.Target.Creature.CombatState;
			HashSet<PileType> actualPiles = new HashSet<PileType>();
			for (int index = 0; index < payload.Count; index++)
			{
				CardModel combatCard = combatState.CreateCard(canonical, context.Target);
				ApplyUpgradeLevels(combatCard, payload.UpgradeLevels);
				ApplyCardState(combatCard, payload.State);
