		private static async Task<string> ExecuteCopyCardAsync(RitsuDebugActionContext context, CopyCardPayload payload)
		{
			TryGetLocatedCard(context.Target, payload.Location, out PileType _, out CardModel source, out RitsuDebugActionFeedback _);
			TryParseMutablePileType(payload.DestinationPile, out var destinationPile);
			CardModel[] copies = (CardModel[])(object)new CardModel[payload.Count];
			for (int i = 0; i < copies.Length; i++)
			{
				int num = i;
				object obj;
				if (!IsRunStatePile(destinationPile))
				{
					CardPile pile = source.Pile;
					obj = ((pile != null && pile.IsCombatPile) ? source.CreateClone() : context.Target.Creature.CombatState.CloneCard(source));
				}
				else
				{
					obj = ((ICardScope)context.Target.RunState).CloneCard(source);
				}
				copies[num] = (CardModel)obj;
			}
			IReadOnlyList<CardPileAddResult> readOnlyList;
			if (IsRunStatePile(destinationPile))
			{
				readOnlyList = await CardPileCmd.Add((IEnumerable<CardModel>)copies, destinationPile, (CardPilePosition)1, (AbstractModel)null, false);
				if ((int)destinationPile == 6)
				{
					CardCmd.PreviewCardPileAdd(readOnlyList, 1.2f, (CardPreviewStyle)1);
				}
			}
			else
			{
				readOnlyList = await CardPileCmd.AddGeneratedCardsToCombat((IEnumerable<CardModel>)copies, destinationPile, context.Target, (CardPilePosition)1);
			}
			List<PileType> list = new List<PileType>(payload.Count);
			for (int j = 0; j < copies.Length; j++)
			{
				if (j < readOnlyList.Count)
				{
					CardPileAddResult val = readOnlyList[j];
					if (val.success)
					{
						CardPile pile2 = val.cardAdded.Pile;
						PileType val2 = ((pile2 != null) ? pile2.Type : destinationPile);
						list.Add(val2);
						if (((int)val2 == 1 || val2 - 3 <= 1) ? true : false)
						{
							CardPile pile3 = val.cardAdded.Pile;
							if (pile3 != null)
							{
								pile3.InvokeCardAddFinished();
							}
						}
						continue;
					}
				}
				copies[j].RemoveFromState();
			}
			switch (list.Count)
			{
			case 0:
				throw new RitsuDebugActionExecutionException(RitsuDebugActionFeedback.Create("card.copyFailed", "The card could not be copied to {0}.", destinationPile));
			case 1:
				return $"Copied {((AbstractModel)source).Id} to {list[0]}.";
			default:
			{
				string value = string.Join(", ", list.GroupBy(delegate(PileType result)
				{
					//IL_0000: Unknown result type (might be due to invalid IL or missing references)
					return result;
				}).OrderBy(delegate(IGrouping<PileType, PileType> group)
				{
					//IL_0001: Unknown result type (might be due to invalid IL or missing references)
					return group.Key;
				}).Select(delegate(IGrouping<PileType, PileType> group)
				{
					//IL_000c: Unknown result type (might be due to invalid IL or missing references)
					return $"{group.Key} {group.Count()}";
				}));
				return (list.Count == payload.Count) ? $"Copied {((AbstractModel)source).Id} {payload.Count} times: {value}." : $"Copied {list.Count} of {payload.Count} requested {((AbstractModel)source).Id} cards: {value}.";
			}
			}
		}

		private static RitsuDebugActionCheck ValidateMoveCard(RitsuDebugActionContext context, MoveCardPayload payload)
		{
			//IL_0032: Unknown result type (might be due to invalid IL or missing references)
			//IL_004f: Unknown result type (might be due to invalid IL or missing references)
