			//IL_008c: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a6: Unknown result type (might be due to invalid IL or missing references)
			if (!TryGetLocatedCard(context.Target, payload.Location, out PileType pileType, out CardModel _, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (!TryParseMutablePileType(payload.DestinationPile, out var pileType2) || IsRunStatePile(pileType2))
			{
				return RitsuDebugActionCheck.Fail("card.moveCombatOnly", "Cards can be moved only between combat piles; use Copy to cross the deck boundary.");
			}
			if (IsRunStatePile(pileType))
			{
				return RitsuDebugActionCheck.Fail("card.deckMoveRequiresCopy", "Deck cards cannot be moved directly into combat; copy the card instead.");
			}
			if (pileType == pileType2)
			{
				return RitsuDebugActionCheck.Fail("card.alreadyInPile", "The card is already in the selected pile.");
			}
			if (GetPile(context.Target, pileType2) == null)
			{
				return RitsuDebugActionCheck.Fail("card.pileUnavailable", "Pile '{0}' is unavailable for the selected player.", pileType2);
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static async Task<string> ExecuteMoveCardAsync(RitsuDebugActionContext context, MoveCardPayload payload)
		{
			TryGetLocatedCard(context.Target, payload.Location, out PileType sourcePile, out CardModel card, out RitsuDebugActionFeedback _);
			TryParseMutablePileType(payload.DestinationPile, out var destinationPile);
			if (!(await CardPileCmd.Add(card, destinationPile, (CardPilePosition)1, (AbstractModel)null, false)).success)
			{
				throw new RitsuDebugActionExecutionException(RitsuDebugActionFeedback.Create("card.moveFailed", "The card could not be moved to {0}.", destinationPile));
			}
			CardPile pile = card.Pile;
			PileType val = ((pile != null) ? pile.Type : destinationPile);
			return (val == destinationPile) ? $"Moved {((AbstractModel)card).Id} from {sourcePile} to {val}." : $"Moved {((AbstractModel)card).Id} from {sourcePile} to {val} because {destinationPile} could not accept another card.";
		}

		private static RitsuDebugActionCheck ValidateReorderCard(RitsuDebugActionContext context, ReorderCardPayload payload)
		{
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			//IL_0045: Unknown result type (might be due to invalid IL or missing references)
			if (!TryGetLocatedCard(context.Target, payload.Location, out PileType pileType, out CardModel card, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			CardPile pile = GetPile(context.Target, pileType);
			if (pile == null)
			{
				return RitsuDebugActionCheck.Fail("card.pileUnavailable", "Pile '{0}' is unavailable for the selected player.", pileType);
			}
			int num = FindCardIndex(pile, card);
			if (num != payload.Location.CardIndex)
			{
				return RitsuDebugActionCheck.Fail("card.selectedMoved", "The selected card moved or is no longer available.");
			}
			if (payload.DestinationIndex < 0 || payload.DestinationIndex >= pile.Cards.Count)
			{
				return RitsuDebugActionCheck.Fail("card.reorderIndexRange", "The destination position must be between 1 and {0}.", pile.Cards.Count);
			}
			if (payload.DestinationIndex != num)
			{
				return RitsuDebugActionCheck.Ok;
			}
			return RitsuDebugActionCheck.Fail("card.alreadyAtPosition", "The card is already at the selected position.");
		}

		private static Task<string> ExecuteReorderCardAsync(RitsuDebugActionContext context, ReorderCardPayload payload)
		{
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_0083: Unknown result type (might be due to invalid IL or missing references)
			TryGetLocatedCard(context.Target, payload.Location, out PileType pileType, out CardModel card, out RitsuDebugActionFeedback _);
			CardPile? pile = GetPile(context.Target, pileType);
			int num = FindCardIndex(pile, card);
			pile.RemoveInternal(card, true);
			pile.AddInternal(card, payload.DestinationIndex, true);
			pile.InvokeContentsChanged();
			RefreshHandOrder(pile, card);
			return Task.FromResult($"Moved {((AbstractModel)card).Id} in {pileType} from position {num + 1} to {payload.DestinationIndex + 1}.");
		}

		private static int FindCardIndex(CardPile pile, CardModel card)
		{
			for (int i = 0; i < pile.Cards.Count; i++)
			{
				if (pile.Cards[i] == card)
				{
					return i;
				}
			}
			return -1;
		}

		private static void RefreshHandOrder(CardPile pile, CardModel card)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Invalid comparison between Unknown and I4
			if ((int)pile.Type != 2)
			{
				return;
			}
			NPlayerHand instance = NPlayerHand.Instance;
			if (instance == null)
			{
				return;
			}
			NCardHolder cardHolder = instance.GetCardHolder(card);
			Control cardHolderContainer = instance.CardHolderContainer;
			if ((object)((cardHolder != null) ? ((Node)cardHolder).GetParent() : null) == cardHolderContainer)
			{
				int num = 0;
				foreach (CardModel card2 in pile.Cards)
				{
					if (card2 == card)
					{
						break;
					}
					NCardHolder cardHolder2 = instance.GetCardHolder(card2);
					if ((object)((cardHolder2 != null) ? ((Node)cardHolder2).GetParent() : null) == cardHolderContainer)
					{
						num++;
					}
				}
				((Node)cardHolderContainer).MoveChild((Node)(object)cardHolder, Math.Clamp(num, 0, ((Node)cardHolderContainer).GetChildCount(false) - 1));
			}
			instance.ForceRefreshCardIndices();
		}

