		private static RitsuDebugActionCheck ValidateEditCard(RitsuDebugActionContext context, EditCardPayload payload)
		{
			if (!Enum.IsDefined(payload.Field))
			{
				return RitsuDebugActionCheck.Fail("card.invalidEditField", "The card edit field is invalid.");
			}
			if (!TryGetLocatedCard(context.Target, payload.Location, out PileType _, out CardModel card, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			int value = payload.Value;
			if ((value < 0 || value > 999999999) ? true : false)
			{
				return RitsuDebugActionCheck.Fail("card.editValueRange", "Card edit values must be between 0 and {0}.", 999999999);
			}
			switch (payload.Field)
			{
			case RitsuDebugCardEditField.Exhaust:
			case RitsuDebugCardEditField.Ethereal:
			case RitsuDebugCardEditField.Unplayable:
				value = payload.Value;
				if ((uint)value > 1u)
				{
					return RitsuDebugActionCheck.Fail("card.flagValue", "Card flag values must be 0 or 1.");
				}
				goto default;
			case RitsuDebugCardEditField.Cost:
				if (card.EnergyCost.CostsX)
				{
					return RitsuDebugActionCheck.Fail("card.xCostCannotReplace", "The base cost of an X-cost card cannot be replaced.");
				}
				goto default;
			case RitsuDebugCardEditField.DynamicVar:
				if (string.IsNullOrWhiteSpace(payload.DynamicVarKey) || payload.DynamicVarKey.Length > 64)
				{
					return RitsuDebugActionCheck.Fail("card.dynamicVarKeyRequired", "A valid dynamic-variable key is required.");
				}
				if (!card.DynamicVars.ContainsKey(payload.DynamicVarKey))
				{
					return RitsuDebugActionCheck.Fail("card.dynamicVarMissing", "Card {0} has no dynamic variable named '{1}'.", ((AbstractModel)card).Id, payload.DynamicVarKey);
				}
				break;
			default:
				if (payload.DynamicVarKey != null)
				{
					return RitsuDebugActionCheck.Fail("card.dynamicVarUnexpected", "A dynamic-variable key is valid only for DynamicVar edits.");
				}
				break;
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static Task<string> ExecuteEditCardAsync(RitsuDebugActionContext context, EditCardPayload payload)
		{
			//IL_00fd: Unknown result type (might be due to invalid IL or missing references)
			TryGetLocatedCard(context.Target, payload.Location, out PileType pileType, out CardModel card, out RitsuDebugActionFeedback _);
			switch (payload.Field)
			{
			case RitsuDebugCardEditField.Cost:
				card.EnergyCost.SetCustomBaseCost(payload.Value);
				break;
			case RitsuDebugCardEditField.Exhaust:
				SetKeyword(card, (CardKeyword)1, payload.Value != 0);
				break;
			case RitsuDebugCardEditField.Ethereal:
				SetKeyword(card, (CardKeyword)2, payload.Value != 0);
				break;
			case RitsuDebugCardEditField.Unplayable:
				SetKeyword(card, (CardKeyword)4, payload.Value != 0);
				break;
			case RitsuDebugCardEditField.DynamicVar:
				SetDynamicVar(card, payload.DynamicVarKey, payload.Value);
				break;
			default:
				throw new ArgumentOutOfRangeException("Field");
			}
			card.RequestVisualReload();
			return Task.FromResult($"Set {payload.Field} on {((AbstractModel)card).Id} in {pileType} to {payload.Value}.");
		}

		private static RitsuDebugActionCheck ValidateEnchantCard(RitsuDebugActionContext context, EnchantCardPayload payload)
		{
			//IL_0080: Unknown result type (might be due to invalid IL or missing references)
			//IL_0086: Expected O, but got Unknown
			if (!TryGetLocatedCard(context.Target, payload.Location, out PileType _, out CardModel card, out RitsuDebugActionFeedback feedback) || !TryResolveEnchantment(payload.EnchantmentId, out EnchantmentModel enchantment, out feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			int amount = payload.Amount;
			if ((amount < 1 || amount > 999999999) ? true : false)
			{
				return RitsuDebugActionCheck.Fail("card.enchantmentAmountRange", "Enchantment amount must be between 1 and {0}.", 999999999);
			}
			CardModel val = (CardModel)((AbstractModel)card).ClonePreservingMutability();
			CardCmd.ClearEnchantment(val);
			ResetCardToUpgradeLevel(val, card.CurrentUpgradeLevel);
			if (!enchantment.CanEnchant(val))
			{
				return RitsuDebugActionCheck.Fail("card.enchantmentIncompatible", "Enchantment {0} cannot be applied to {1}.", DisplayTitle(enchantment), DisplayTitle(card));
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static Task<string> ExecuteEnchantCardAsync(RitsuDebugActionContext context, EnchantCardPayload payload)
		{
			//IL_0193: Unknown result type (might be due to invalid IL or missing references)
			TryGetLocatedCard(context.Target, payload.Location, out PileType pileType, out CardModel card, out RitsuDebugActionFeedback feedback);
			TryResolveEnchantment(payload.EnchantmentId, out EnchantmentModel enchantment, out feedback);
			EnchantmentModel enchantment2 = card.Enchantment;
			EnchantmentModel val = ((enchantment2 != null) ? enchantment2.CanonicalInstance : null);
			EnchantmentModel enchantment3 = card.Enchantment;
			int num = ((enchantment3 != null) ? enchantment3.Amount : 0);
			int currentUpgradeLevel = card.CurrentUpgradeLevel;
			CardCmd.ClearEnchantment(card);
			ResetCardToUpgradeLevel(card, currentUpgradeLevel);
			try
			{
				if (CardCmd.Enchant(enchantment.ToMutable(), card, (decimal)payload.Amount) == null)
				{
					throw new RitsuDebugActionExecutionException(RitsuDebugActionFeedback.Create("card.enchantmentApplyFailed", "The game did not apply enchantment {0} to card {1}.", DisplayTitle(enchantment), DisplayTitle(card)));
				}
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				CardCmd.ClearEnchantment(card);
				ResetCardToUpgradeLevel(card, currentUpgradeLevel);
				if (val != null)
				{
					try
					{
						if (CardCmd.Enchant(val.ToMutable(), card, (decimal)num) == null)
						{
							throw new RitsuDebugActionExecutionException(RitsuDebugActionFeedback.Create("card.enchantmentRestoreFailed", "The previous enchantment {0} could not be restored to card {1}.", DisplayTitle(val), DisplayTitle(card)));
						}
					}
					catch (Exception ex2) when (RitsuLibExceptionPolicy.IsRecoverable(ex2))
					{
						throw new AggregateException("The new enchantment failed and the previous enchantment could not be restored.", ex, ex2);
					}
				}
				throw;
			}
			card.RequestVisualReload();
			return Task.FromResult($"Set {((AbstractModel)card).Id} in {pileType} to enchantment {((AbstractModel)enchantment).Id} with amount {payload.Amount}.");
		}

		private static RitsuDebugActionCheck ValidateClearCardEnchantment(RitsuDebugActionContext context, CardLocationPayload payload)
		{
			if (!TryGetLocatedCard(context.Target, payload, out PileType _, out CardModel card, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (card.Enchantment == null)
			{
				return RitsuDebugActionCheck.Fail("card.noEnchantment", "Card {0} has no enchantment.", ((AbstractModel)card).Id);
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static Task<string> ExecuteClearCardEnchantmentAsync(RitsuDebugActionContext context, CardLocationPayload payload)
		{
			//IL_007f: Unknown result type (might be due to invalid IL or missing references)
			TryGetLocatedCard(context.Target, payload, out PileType pileType, out CardModel card, out RitsuDebugActionFeedback _);
			ModelId id = ((AbstractModel)card.Enchantment).Id;
			int currentUpgradeLevel = card.CurrentUpgradeLevel;
			CardCmd.ClearEnchantment(card);
			ResetCardToUpgradeLevel(card, currentUpgradeLevel);
			card.RequestVisualReload();
			return Task.FromResult($"Cleared enchantment {id} from {((AbstractModel)card).Id} in {pileType}.");
		}

		private static RitsuDebugActionCheck ValidateUpgradeCard(RitsuDebugActionContext context, UpgradeCardPayload payload)
		{
			int levels = payload.Levels;
			if ((levels < 1 || levels > 99) ? true : false)
			{
				return RitsuDebugActionCheck.Fail("card.upgradeLevelsRange", "Upgrade levels must be between 1 and {0}.", 99);
			}
			if (!TryGetLocatedCard(context.Target, payload.Location, out PileType _, out CardModel card, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (!card.IsUpgradable)
			{
				return RitsuDebugActionCheck.Fail("card.maximumUpgrade", "Card {0} is already at its maximum upgrade level.", ((AbstractModel)card).Id);
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static Task<string> ExecuteUpgradeCardAsync(RitsuDebugActionContext context, UpgradeCardPayload payload)
		{
			//IL_007d: Unknown result type (might be due to invalid IL or missing references)
			TryGetLocatedCard(context.Target, payload.Location, out PileType pileType, out CardModel card, out RitsuDebugActionFeedback _);
			int currentUpgradeLevel = card.CurrentUpgradeLevel;
			for (int i = 0; i < payload.Levels; i++)
			{
				if (!card.IsUpgradable)
				{
					break;
				}
				CardCmd.Upgrade(card, (CardPreviewStyle)0);
			}
			card.RequestVisualReload();
			return Task.FromResult($"Upgraded {((AbstractModel)card).Id} in {pileType} from {currentUpgradeLevel} to {card.CurrentUpgradeLevel}.");
		}

		private static RitsuDebugActionCheck ValidateSetUpgradeLevel(RitsuDebugActionContext context, UpgradeCardPayload payload)
		{
			if (!TryGetLocatedCard(context.Target, payload.Location, out PileType _, out CardModel card, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (payload.Levels < 0 || payload.Levels > card.MaxUpgradeLevel)
			{
				return RitsuDebugActionCheck.Fail("card.upgradeLevelRange", "Upgrade level must be between 0 and {0}.", card.MaxUpgradeLevel);
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static Task<string> ExecuteSetUpgradeLevelAsync(RitsuDebugActionContext context, UpgradeCardPayload payload)
		{
			//IL_006f: Unknown result type (might be due to invalid IL or missing references)
			TryGetLocatedCard(context.Target, payload.Location, out PileType pileType, out CardModel card, out RitsuDebugActionFeedback _);
			int currentUpgradeLevel = card.CurrentUpgradeLevel;
			if (currentUpgradeLevel != payload.Levels)
			{
				ResetCardToUpgradeLevel(card, payload.Levels);
			}
			card.RequestVisualReload();
			return Task.FromResult($"Set {((AbstractModel)card).Id} in {pileType} from upgrade level {currentUpgradeLevel} to {card.CurrentUpgradeLevel}.");
		}

		private static void ResetCardToUpgradeLevel(CardModel card, int upgradeLevel)
		{
			card.DowngradeInternal();
			for (int i = 0; i < upgradeLevel; i++)
			{
				if (!card.IsUpgradable)
				{
					break;
				}
				CardCmd.Upgrade(card, (CardPreviewStyle)0);
			}
		}

		private static string DisplayTitle(CardModel card)
		{
			return ResolveDisplayTitle(((object)((AbstractModel)card).Id).ToString(), () => card.Title);
		}

		private static string DisplayTitle(EnchantmentModel enchantment)
		{
			return ResolveDisplayTitle(((object)((AbstractModel)enchantment).Id).ToString(), () => enchantment.Title.GetFormattedText());
		}

		private static string ResolveDisplayTitle(string fallback, Func<string> titleFactory)
		{
			try
			{
				string text = titleFactory().Trim();
				return string.IsNullOrWhiteSpace(text) ? fallback : text;
			}
			catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
			{
				return fallback;
			}
		}

		private static bool TryGetLocatedCard(Player target, CardLocationPayload payload, out PileType pileType, out CardModel card, out RitsuDebugActionFeedback feedback)
		{
			card = null;
			if (string.IsNullOrWhiteSpace(payload.ExpectedCardId) || payload.ExpectedCardId.Length > 128)
			{
				pileType = (PileType)0;
				feedback = RitsuDebugActionFeedback.Create("card.selectedInvalid", "The selected card is invalid.");
				return false;
			}
			if (!TryParseMutablePileType(payload.Pile, out pileType))
			{
				feedback = RitsuDebugActionFeedback.Create("card.unsupportedPile", "Unsupported pile '{0}'.", payload.Pile);
				return false;
			}
			if (!IsRunStatePile(pileType) && !TryRequireActiveCombat(target, out feedback))
			{
				return false;
			}
			CardPile pile = GetPile(target, pileType);
			if (pile == null)
			{
				feedback = RitsuDebugActionFeedback.Create("card.pileUnavailable", "Pile '{0}' is unavailable for the selected player.", pileType);
				return false;
			}
			if (!IsRunStatePile(pileType))
			{
				CardModel val = default(CardModel);
				if (!payload.CombatCardId.HasValue || !NetCombatCardDb.Instance.TryGetCard(payload.CombatCardId.Value, ref val) || val == null || val.Owner.NetId != target.NetId || val.Pile != pile || !((object)((AbstractModel)val).Id).ToString().Equals(payload.ExpectedCardId, StringComparison.Ordinal))
				{
					feedback = RitsuDebugActionFeedback.Create("card.selectedMoved", "The selected card moved or is no longer available.");
					return false;
				}
				card = val;
				feedback = default(RitsuDebugActionFeedback);
				return true;
			}
			if (payload.CardIndex < 0 || payload.CardIndex >= pile.Cards.Count)
			{
				feedback = RitsuDebugActionFeedback.Create("card.indexRange", "Card index {0} is outside {1}'s range 0-{2}.", payload.CardIndex, pileType, pile.Cards.Count - 1);
				return false;
			}
			card = pile.Cards[payload.CardIndex];
			if (!((object)((AbstractModel)card).Id).ToString().Equals(payload.ExpectedCardId, StringComparison.Ordinal))
			{
				feedback = RitsuDebugActionFeedback.Create("card.slotChanged", "The card at {0}[{1}] changed before the action could run.", pileType, payload.CardIndex);
				return false;
			}
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}

		private static CardLocationPayload CreateCardLocationPayload(Player target, PileType pileType, int cardIndex, string expectedCardId, uint? combatCardId)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			if (!IsRunStatePile(pileType) && !combatCardId.HasValue)
			{
				CardPile pile = GetPile(target, pileType);
				if (pile != null && cardIndex >= 0 && cardIndex < pile.Cards.Count)
				{
					combatCardId = GetCombatCardId(pile.Cards[cardIndex]);
				}
			}
			return new CardLocationPayload(GetPileToken(pileType), cardIndex, expectedCardId, combatCardId);
		}

		private static void RemoveRunStateCards(IEnumerable<CardModel> cards)
		{
			foreach (CardModel card in cards)
			{
				card.RemoveFromState();
			}
		}

		private static void SetDynamicVar(CardModel card, string key, int value)
		{
			DynamicVar obj = card.DynamicVars[key];
			obj.BaseValue = value;
			obj.ResetToBase();
			obj.PreviewValue = value;
		}

		private static void SetKeyword(CardModel card, CardKeyword keyword, bool enabled)
		{
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0004: Unknown result type (might be due to invalid IL or missing references)
			if (enabled)
			{
				card.AddKeyword(keyword);
			}
			else
			{
				card.RemoveKeyword(keyword);
			}
		}

		private static bool TryRequireActiveCombat(Player target, out RitsuDebugActionFeedback feedback)
		{
			if (!CombatManager.Instance.IsInProgress || CombatManager.Instance.IsOverOrEnding || target.PlayerCombatState == null || target.Creature.CombatState == null)
			{
				feedback = RitsuDebugActionFeedback.Create("action.activeCombatRequired", "This change requires an active combat.");
				return false;
			}
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}

		private static void ApplyUpgradeLevels(CardModel card, int levels)
		{
			for (int i = 0; i < levels; i++)
			{
				CardCmd.Upgrade(card, (CardPreviewStyle)0);
			}
		}

		internal static void ApplyAvailableUpgradeLevels(CardModel card, int levels)
		{
			for (int i = 0; i < levels; i++)
			{
				if (!card.IsUpgradable)
				{
					break;
				}
				CardCmd.Upgrade(card, (CardPreviewStyle)0);
			}
		}

		private static RitsuLibSidecarPeerFeatures FeaturesForPileToken(string pileToken)
		{
			//IL_000a: Unknown result type (might be due to invalid IL or missing references)
			if (!TryParseMutablePileType(pileToken, out var pileType) || !ModCardPileRegistry.IsModPileType(pileType))
			{
				return RitsuLibSidecarPeerFeatures.None;
			}
			return (RitsuLibSidecarPeerFeatures)64u;
		}

		static RitsuDebugCardActions()
		{
			PileType[] array = new PileType[5];
			RuntimeHelpers.InitializeArray(array, (RuntimeFieldHandle)/*OpCode not supported: LdMemberToken*/);
			VanillaMutablePileTypes = (PileType[])(object)array;
		}
