	internal static class RitsuDebugCombatActions
	{
		internal readonly record struct ModifyCreaturePayload(uint CombatId, RitsuDebugCreatureOperation Operation, int Value);

		internal readonly record struct PowerPayload(uint CombatId, string PowerId, int Amount, Dictionary<string, int>? DynamicVars);

		internal readonly record struct PowerInstancePayload(uint CombatId, int Index, string PowerId, int Offset);

		internal readonly record struct PowerInstanceValuesPayload(uint CombatId, int Index, string PowerId, int? Amount, Dictionary<string, int>? DynamicVars);

		internal readonly record struct PowerGroupPayload(uint[] CombatIds, string PowerId, int Amount, Dictionary<string, int>? DynamicVars);

		internal readonly record struct MonsterIntentPayload(uint CombatId, string MoveId);

		internal readonly record struct MonsterIntentGroupPayload(uint CombatId, string GroupId);

		internal readonly record struct MonsterActionPayload(uint CombatId);

		internal readonly record struct ConfirmedPayload(bool Confirmed);

		internal const string ModifyCreatureActionId = "combat.creature.modify";

		internal const string AddMonsterActionId = "combat.monster.add";

		internal const string AddEncounterActionId = "combat.encounter.add";

		internal const string DefeatAllEnemiesActionId = "combat.enemies.defeat-all";

		internal const string ApplyPowerActionId = "combat.power.apply";

		internal const string ApplyPowerToCreaturesActionId = "combat.power.apply-many";

		internal const string RemovePowerActionId = "combat.power.remove";

		internal const string AdjustPowerInstanceActionId = "combat.power.adjust-instance";

		internal const string EditPowerInstanceActionId = "combat.power.edit-instance";

		internal const string RemovePowerInstanceActionId = "combat.power.remove-instance";

		internal const string StunMonsterActionId = "combat.monster.stun";

		internal const string SetMonsterIntentActionId = "combat.monster.intent.set";

		internal const string RandomMonsterIntentActionId = "combat.monster.intent.random-group";

		internal const string PerformMonsterIntentActionId = "combat.monster.intent.perform";

		internal const int MaxAmount = 999999999;

		internal const int MaxCreatureTargetCount = 128;

		internal const int MaxEnemyCount = 64;

		internal static bool IsMonsterIntentActionFor(RitsuDebugActionExecutionResult result, uint combatId)
		{
			try
			{
				bool result2;
				switch (result.ActionId)
				{
				case "combat.monster.intent.set":
					result2 = JsonSerializer.Deserialize<MonsterIntentPayload>(result.PayloadJson).CombatId == combatId;
					break;
				case "combat.monster.intent.random-group":
					result2 = JsonSerializer.Deserialize<MonsterIntentGroupPayload>(result.PayloadJson).CombatId == combatId;
					break;
				case "combat.monster.intent.perform":
				case "combat.monster.stun":
					result2 = JsonSerializer.Deserialize<MonsterActionPayload>(result.PayloadJson).CombatId == combatId;
					break;
				default:
					result2 = false;
					break;
				}
				return result2;
			}
			catch (JsonException)
			{
				return false;
			}
		}

		internal static void RegisterBuiltInActions()
		{
			RitsuDebugActionProtocol.Register<ModifyCreaturePayload>("combat.creature.modify", ValidateModifyCreature, ExecuteModifyCreatureAsync);
			RitsuDebugActionProtocol.Register<RitsuDebugRunActions.ModelPayload>("combat.monster.add", ValidateAddMonster, ExecuteAddMonsterAsync);
			RitsuDebugActionProtocol.Register<RitsuDebugRunActions.ModelPayload>("combat.encounter.add", ValidateAddEncounter, ExecuteAddEncounterAsync);
			RitsuDebugActionProtocol.Register<ConfirmedPayload>("combat.enemies.defeat-all", ValidateDefeatAllEnemies, ExecuteDefeatAllEnemiesAsync);
			RitsuDebugActionProtocol.Register<PowerPayload>("combat.power.apply", ValidateApplyPower, ExecuteApplyPowerAsync);
			RitsuDebugActionProtocol.Register<PowerGroupPayload>("combat.power.apply-many", ValidateApplyPowerToCreatures, ExecuteApplyPowerToCreaturesAsync);
			RitsuDebugActionProtocol.Register<PowerPayload>("combat.power.remove", ValidateRemovePower, ExecuteRemovePowerAsync);
			RitsuDebugActionProtocol.Register<PowerInstancePayload>("combat.power.adjust-instance", ValidateAdjustPowerInstance, ExecuteAdjustPowerInstanceAsync);
			RitsuDebugActionProtocol.Register<PowerInstanceValuesPayload>("combat.power.edit-instance", ValidateEditPowerInstance, ExecuteEditPowerInstanceAsync);
			RitsuDebugActionProtocol.Register<PowerInstancePayload>("combat.power.remove-instance", ValidateRemovePowerInstance, ExecuteRemovePowerInstanceAsync);
			RitsuDebugActionProtocol.Register<MonsterActionPayload>("combat.monster.stun", ValidateStunMonster, ExecuteStunMonsterAsync, (RitsuLibSidecarPeerFeatures)32u);
			RitsuDebugActionProtocol.Register<MonsterIntentPayload>("combat.monster.intent.set", ValidateSetMonsterIntent, ExecuteSetMonsterIntentAsync, (RitsuLibSidecarPeerFeatures)32u);
			RitsuDebugActionProtocol.Register<MonsterIntentGroupPayload>("combat.monster.intent.random-group", ValidateRandomMonsterIntent, ExecuteRandomMonsterIntentAsync, (RitsuLibSidecarPeerFeatures)32u);
			RitsuDebugActionProtocol.Register<MonsterActionPayload>("combat.monster.intent.perform", ValidatePerformMonsterIntent, ExecutePerformMonsterIntentAsync, (RitsuLibSidecarPeerFeatures)32u);
			RitsuDebugCreaturePresetActions.RegisterBuiltInActions();
		}

