			}
			PowerModel[] array = ModelDb.AllPowers.Where((PowerModel candidate) => ((object)((AbstractModel)candidate).Id).ToString().Equals(input, StringComparison.OrdinalIgnoreCase)).Take(2).ToArray();
			PowerModel[] array2 = ((array.Length != 0) ? array : ModelDb.AllPowers.Where((PowerModel candidate) => ((AbstractModel)candidate).Id.Entry.Equals(input, StringComparison.OrdinalIgnoreCase)).Take(2).ToArray());
			if (array2.Length == 1)
			{
				power = array2[0];
				feedback = default(RitsuDebugActionFeedback);
				return true;
			}
			feedback = ((array2.Length == 0) ? RitsuDebugActionFeedback.Create("model.powerUnknown", "Unknown power '{0}'.", input) : RitsuDebugActionFeedback.Create("model.powerAmbiguous", "The power ID '{0}' is ambiguous; use the full model ID.", input));
			return false;
		}

