		internal static Creature? FindCreature(uint combatId)
		{
			CombatState obj = CombatManager.Instance.DebugOnlyGetState();
			if (obj == null)
			{
				return null;
			}
			return obj.Creatures.FirstOrDefault((Creature creature) => creature.CombatId == combatId);
		}

		private static RitsuDebugActionSubmission SubmitPower(Player requester, Player actionTarget, string actionId, uint combatId, string powerId, int amount, IReadOnlyDictionary<string, int>? dynamicVars = null)
		{
			RitsuDebugActionEnvelope envelope = RitsuDebugActionProtocol.CreateEnvelope(actionId, requester, actionTarget, new PowerPayload(combatId, powerId, amount, CopyOverrides(dynamicVars)));
			return RitsuDebugActionProtocol.Submit(requester, envelope);
		}

		private static Dictionary<string, int>? CopyOverrides(IReadOnlyDictionary<string, int>? values)
		{
			return values?.ToDictionary<KeyValuePair<string, int>, string, int>((KeyValuePair<string, int> pair) => pair.Key, (KeyValuePair<string, int> pair) => pair.Value, StringComparer.Ordinal);
		}

		private static RitsuDebugActionCheck ValidateModifyCreature(RitsuDebugActionContext context, ModifyCreaturePayload payload)
		{
			if (!TryRequireCombat(out var feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (!Enum.IsDefined(payload.Operation))
			{
				return RitsuDebugActionCheck.Fail("combat.invalidCreatureOperation", "The creature operation is invalid.");
			}
			Creature val = FindCreature(payload.CombatId);
			if (val == null)
			{
				return RitsuDebugActionCheck.Fail("combat.creatureUnavailable", "The selected creature is no longer available.");
			}
			if (payload.Operation == RitsuDebugCreatureOperation.Kill)
			{
				if (val.IsPlayer)
				{
					return RitsuDebugActionCheck.Fail("combat.killPlayerUnsupported", "Killing player characters is not supported.");
				}
				if (val.IsDead)
				{
					return RitsuDebugActionCheck.Fail("combat.creatureAlreadyDead", "The selected creature is already dead.");
				}
			}
			RitsuDebugCreatureOperation operation = payload.Operation;
			bool flag = ((operation == RitsuDebugCreatureOperation.Kill || operation == RitsuDebugCreatureOperation.ClearPowers) ? true : false);
			bool flag2 = !flag;
			if (flag2)
			{
				int value = payload.Value;
				bool flag3 = ((value < 0 || value > 999999999) ? true : false);
				flag2 = flag3;
			}
			if (flag2)
			{
				return RitsuDebugActionCheck.Fail("combat.amountRange", "The amount must be between 0 and {0}.", 999999999);
			}
			switch (payload.Operation)
			{
			case RitsuDebugCreatureOperation.SetCurrentHp:
				if (payload.Value > val.MaxHp)
				{
					return RitsuDebugActionCheck.Fail("combat.currentHpExceedsMax", "Current HP cannot exceed the creature's max HP ({0}).", val.MaxHp);
				}
				if (val.IsPlayer && payload.Value == 0)
				{
					return RitsuDebugActionCheck.Fail("combat.playerHpAboveZero", "A player's current HP must remain above zero.");
				}
				break;
			case RitsuDebugCreatureOperation.SetMaxHp:
				if (payload.Value < Math.Max(1, val.CurrentHp))
				{
					return RitsuDebugActionCheck.Fail("combat.maxHpBelowCurrent", "Max HP cannot be lower than the creature's current HP ({0}).", val.CurrentHp);
				}
				break;
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateAddMonster(RitsuDebugActionContext context, RitsuDebugRunActions.ModelPayload payload)
		{
			if (!TryRequireCombat(out var feedback) || !TryResolveMonster(payload.ModelId, out MonsterModel _, out feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (CombatManager.Instance.DebugOnlyGetState().Enemies.Count >= 64)
			{
				return RitsuDebugActionCheck.Fail("combat.enemyLimit", "These tools support at most {0} enemies in one combat.", 64);
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateAddEncounter(RitsuDebugActionContext context, RitsuDebugRunActions.ModelPayload payload)
		{
			if (!TryRequireCombat(out var feedback) || !RitsuDebugRunActions.TryResolveEncounter(payload.ModelId, out EncounterModel encounter, out feedback) || !TryCreateEncounterMonsters(encounter, context.Target, out MonsterModel[] monsters, out feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (CombatManager.Instance.DebugOnlyGetState().Enemies.Count + monsters.Length > 64)
			{
				return RitsuDebugActionCheck.Fail("combat.encounterWouldExceedEnemyLimit", "Adding this encounter would exceed the limit of {0} enemies in one combat.", 64);
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateDefeatAllEnemies(RitsuDebugActionContext context, ConfirmedPayload payload)
		{
			if (!payload.Confirmed)
			{
				return RitsuDebugActionCheck.Fail("combat.defeatNotConfirmed", "Defeating all enemies was not confirmed.");
			}
			if (!TryRequireCombat(out var feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (!CombatManager.Instance.DebugOnlyGetState().Enemies.Any((Creature creature) => !creature.IsDead))
			{
				return RitsuDebugActionCheck.Fail("combat.noLivingEnemies", "There are no living enemies in the current combat.");
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateApplyPower(RitsuDebugActionContext context, PowerPayload payload)
		{
			if (!TryRequireCombat(out var feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			Creature val = FindCreature(payload.CombatId);
			if (val == null)
			{
				return RitsuDebugActionCheck.Fail("combat.creatureUnavailable", "The selected creature is no longer available.");
			}
			if (!val.CanReceivePowers)
			{
				return RitsuDebugActionCheck.Fail("combat.cannotReceivePowers", "The selected creature cannot receive powers right now.");
			}
			if (!TryResolvePower(payload.PowerId, out PowerModel power, out feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			RitsuDebugActionCheck result = RitsuDebugModelValueOverrides.Validate(power.DynamicVars, payload.DynamicVars);
			if (!result.Success)
			{
				return result;
			}
			int amount = payload.Amount;
			if ((amount >= 1 && amount <= 999999999) || 1 == 0)
			{
				return RitsuDebugActionCheck.Ok;
			}
			return RitsuDebugActionCheck.Fail("combat.powerAmountRange", "Power amount must be between 1 and {0}.", 999999999);
		}

		private static RitsuDebugActionCheck ValidateApplyPowerToCreatures(RitsuDebugActionContext context, PowerGroupPayload payload)
		{
			if (!TryRequireCombat(out var feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			bool flag = payload.CombatIds == null;
			int num;
			if (!flag)
			{
				num = payload.CombatIds.Length;
				bool flag2 = ((num < 1 || num > 128) ? true : false);
				flag = flag2;
			}
			if (flag)
			{
				return RitsuDebugActionCheck.Fail("combat.powerTargetCountRange", "Select between 1 and {0} creatures.", 128);
			}
			if (payload.CombatIds.Distinct().Count() != payload.CombatIds.Length)
			{
				return RitsuDebugActionCheck.Fail("combat.duplicatePowerTargets", "A creature can appear only once in a batch Power action.");
			}
			if (!TryResolvePower(payload.PowerId, out PowerModel power, out feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			RitsuDebugActionCheck result = RitsuDebugModelValueOverrides.Validate(power.DynamicVars, payload.DynamicVars);
			if (!result.Success)
			{
				return result;
			}
			num = payload.Amount;
			if ((num < 1 || num > 999999999) ? true : false)
			{
				return RitsuDebugActionCheck.Fail("combat.powerAmountRange", "Power amount must be between 1 and {0}.", 999999999);
			}
			uint[] combatIds = payload.CombatIds;
			for (num = 0; num < combatIds.Length; num++)
			{
				Creature val = FindCreature(combatIds[num]);
				if (val == null)
				{
					return RitsuDebugActionCheck.Fail("combat.creatureUnavailable", "A selected creature is no longer available.");
				}
				if (!val.CanReceivePowers)
				{
					return RitsuDebugActionCheck.Fail("combat.cannotReceivePowers", "A selected creature cannot receive powers right now.");
				}
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateRemovePower(RitsuDebugActionContext context, PowerPayload payload)
		{
			if (!TryRequireCombat(out var feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			Creature val = FindCreature(payload.CombatId);
			if (val == null)
			{
				return RitsuDebugActionCheck.Fail("combat.creatureUnavailable", "The selected creature is no longer available.");
			}
			if (!TryResolvePower(payload.PowerId, out PowerModel canonical, out feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
