			{
				return RitsuDebugActionCheck.Fail("combat.powerMissing", "The selected creature does not have {0}.", ((AbstractModel)canonical).Id);
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateAdjustPowerInstance(RitsuDebugActionContext context, PowerInstancePayload payload)
		{
			int offset = payload.Offset;
			if ((offset < -999999999 || offset > 999999999 || offset == 0) ? true : false)
			{
				return RitsuDebugActionCheck.Fail("combat.powerOffsetRange", "Power adjustment must be between {0} and {1}, excluding zero.", -999999999, 999999999);
			}
			if (!TryResolvePowerInstance(payload, out Creature creature, out PowerModel _, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (!creature.CanReceivePowers)
			{
				return RitsuDebugActionCheck.Fail("combat.cannotReceivePowers", "The selected creature cannot receive power changes right now.");
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateRemovePowerInstance(RitsuDebugActionContext context, PowerInstancePayload payload)
		{
			if (!TryResolvePowerInstance(payload, out Creature _, out PowerModel _, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			return RitsuDebugActionCheck.Ok;
