		private static RitsuDebugActionCheck ValidateEditPowerInstance(RitsuDebugActionContext context, PowerInstanceValuesPayload payload)
		{
			if (!payload.Amount.HasValue && (payload.DynamicVars == null || payload.DynamicVars.Count == 0))
			{
				return RitsuDebugActionCheck.Fail("combat.powerEditEmpty", "Change at least one Power value before applying the edit.");
			}
			if (!TryResolvePowerInstance(new PowerInstancePayload(payload.CombatId, payload.Index, payload.PowerId, 0), out Creature creature, out PowerModel power, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			int? amount = payload.Amount;
			if (amount.HasValue)
			{
				int valueOrDefault = amount.GetValueOrDefault();
				int num = (power.AllowNegative ? (-999999999) : 0);
				if (valueOrDefault < num || valueOrDefault > 999999999)
				{
					return RitsuDebugActionCheck.Fail("combat.powerValueRange", "Power amount must be between {0} and {1}.", num, 999999999);
				}
				if (valueOrDefault != power.Amount && !creature.CanReceivePowers)
				{
					return RitsuDebugActionCheck.Fail("combat.cannotReceivePowers", "The selected creature cannot receive power changes right now.");
				}
			}
			return RitsuDebugModelValueOverrides.Validate(power.DynamicVars, payload.DynamicVars);
		}

		private static RitsuDebugActionCheck ValidateSetMonsterIntent(RitsuDebugActionContext context, MonsterIntentPayload payload)
		{
			if (!TryResolveMonsterActionTarget(payload.CombatId, out Creature creature, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (string.IsNullOrWhiteSpace(payload.MoveId) || payload.MoveId.Length > 128)
			{
				return RitsuDebugActionCheck.Fail("combat.monsterIntentIdInvalid", "The selected monster intent is invalid.");
			}
			string moveId = payload.MoveId;
			bool flag = ((moveId == "UNSET_MOVE" || moveId == "STUNNED") ? true : false);
			if (flag || !creature.Monster.MoveStateMachine.States.TryGetValue(payload.MoveId, out var value) || !(value is MoveState))
			{
				return RitsuDebugActionCheck.Fail("combat.monsterIntentUnavailable", "The selected intent is not available for this monster.");
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateStunMonster(RitsuDebugActionContext context, MonsterActionPayload payload)
		{
			if (!TryResolveMonsterActionTarget(payload.CombatId, out Creature creature, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (creature.IsStunned)
			{
				return RitsuDebugActionCheck.Fail("combat.monsterAlreadyStunned", "The selected monster is already stunned.");
			}
			if (!((MonsterState)creature.Monster.NextMove).CanTransitionAway)
			{
				return RitsuDebugActionCheck.Fail("combat.monsterIntentLocked", "The selected monster's current intent cannot be interrupted.");
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateRandomMonsterIntent(RitsuDebugActionContext context, MonsterIntentGroupPayload payload)
		{
			if (!TryResolveMonsterActionTarget(payload.CombatId, out Creature creature, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (string.IsNullOrWhiteSpace(payload.GroupId) || payload.GroupId.Length > 128)
			{
				return RitsuDebugActionCheck.Fail("combat.monsterIntentGroupInvalid", "The selected intent group is invalid.");
			}
			MonsterMoveStateMachine machine = creature.Monster.MoveStateMachine;
			if (machine.States.TryGetValue(payload.GroupId, out var value))
			{
				RandomBranchState val = (RandomBranchState)(object)((value is RandomBranchState) ? value : null);
				if (val != null)
				{
					List<StateWeight> states = val.States;
					if (states != null)
					{
						int count = states.Count;
						if (count > 0 && count <= 128 && !val.States.Any(delegate(StateWeight branch)
						{
							//IL_0000: Unknown result type (might be due to invalid IL or missing references)
							//IL_0018: Unknown result type (might be due to invalid IL or missing references)
							return string.IsNullOrWhiteSpace(branch.stateId) || !machine.States.ContainsKey(branch.stateId);
						}))
						{
							return RitsuDebugActionCheck.Ok;
						}
					}
				}
			}
			return RitsuDebugActionCheck.Fail("combat.monsterIntentGroupUnavailable", "The selected random intent group is not available for this monster.");
		}

		private static RitsuDebugActionCheck ValidatePerformMonsterIntent(RitsuDebugActionContext context, MonsterActionPayload payload)
		{
			if (!TryResolveMonsterActionTarget(payload.CombatId, out Creature creature, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (!(((MonsterState)creature.Monster.NextMove).Id == "UNSET_MOVE"))
			{
				return RitsuDebugActionCheck.Ok;
			}
			return RitsuDebugActionCheck.Fail("combat.monsterIntentUnavailable", "The selected monster does not currently have an intent to perform.");
		}

		private static async Task<string> ExecuteModifyCreatureAsync(RitsuDebugActionContext context, ModifyCreaturePayload payload)
		{
			Creature creature = FindCreature(payload.CombatId);
			switch (payload.Operation)
			{
			case RitsuDebugCreatureOperation.Kill:
				await CreatureCmd.Kill(creature, true);
				if (creature != null && creature.IsPet)
				{
					ICombatState combatState = creature.CombatState;
					if (combatState != null && combatState.ContainsCreature(creature))
					{
						CombatManager.Instance.RemoveCreature(creature);
						combatState.RemoveCreature(creature, true);
					}
				}
				break;
			case RitsuDebugCreatureOperation.Damage:
				await CreatureCmd.Damage((PlayerChoiceContext)new BlockingPlayerChoiceContext(), creature, (decimal)payload.Value, (ValueProp)4, (CardModel)null, (CardPlay)null);
				await CombatManager.Instance.CheckWinCondition();
				break;
			case RitsuDebugCreatureOperation.Heal:
				await CreatureCmd.Heal(creature, (decimal)payload.Value, true);
				break;
			case RitsuDebugCreatureOperation.GainBlock:
				await CreatureCmd.GainBlock(creature, (decimal)payload.Value, (ValueProp)4, (CardPlay)null, false);
				break;
			case RitsuDebugCreatureOperation.SetCurrentHp:
				await CreatureCmd.SetCurrentHp(creature, (decimal)payload.Value);
				break;
			case RitsuDebugCreatureOperation.SetMaxHp:
				await CreatureCmd.SetMaxHp(creature, (decimal)payload.Value);
				break;
			case RitsuDebugCreatureOperation.SetBlock:
				await SetCreatureBlockAsync(creature, payload.Value);
				break;
			case RitsuDebugCreatureOperation.ClearPowers:
			{
				PowerModel[] array = creature.Powers.ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					await PowerCmd.Remove(array[i]);
				}
				break;
			}
			default:
				throw new ArgumentOutOfRangeException("Operation");
			}
			return DescribeCreatureResult(payload.Operation);
		}

		private static Task<string> ExecuteSetMonsterIntentAsync(RitsuDebugActionContext context, MonsterIntentPayload payload)
		{
			//IL_0028: Unknown result type (might be due to invalid IL or missing references)
			//IL_002e: Expected O, but got Unknown
			MonsterModel monster = FindCreature(payload.CombatId).Monster;
			MoveState val = (MoveState)monster.MoveStateMachine.States[payload.MoveId];
			monster.SetMoveImmediate(val, true);
			return Task.FromResult("Changed the selected monster's intent to " + payload.MoveId + ".");
		}

		private static async Task<string> ExecuteStunMonsterAsync(RitsuDebugActionContext context, MonsterActionPayload payload)
		{
			Creature? obj = FindCreature(payload.CombatId);
			await CreatureCmd.Stun(obj, ((MonsterState)obj.Monster.NextMove).Id);
			return "Stunned the selected monster.";
		}

		private static Task<string> ExecuteRandomMonsterIntentAsync(RitsuDebugActionContext context, MonsterIntentGroupPayload payload)
		{
			//IL_002b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0031: Expected O, but got Unknown
			Creature val = FindCreature(payload.CombatId);
			MonsterModel monster = val.Monster;
			RandomBranchState val2 = (RandomBranchState)monster.MoveStateMachine.States[payload.GroupId];
			try
			{
				MoveState val3 = ResolveRandomGroupMove(val, val2);
				monster.SetMoveImmediate(val3, true);
				return Task.FromResult("Randomly changed the selected monster's intent to " + ((MonsterState)val3).Id + ".");
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn($"[DebugTools] Could not select an intent from group '{payload.GroupId}': {ex}", 1);
				throw new RitsuDebugActionExecutionException(RitsuDebugActionFeedback.Create("combat.monsterIntentGroupUnavailable", "The selected random intent group is not available for this monster."));
			}
		}

		private static async Task<string> ExecutePerformMonsterIntentAsync(RitsuDebugActionContext context, MonsterActionPayload payload)
		{
			Creature creature = FindCreature(payload.CombatId);
			MonsterModel monster = creature.Monster;
			string moveId = ((MonsterState)monster.NextMove).Id;
			NCombatRoom instance = NCombatRoom.Instance;
			NCreature val = ((instance != null) ? instance.GetCreatureNode(creature) : null);
			if (val != null)
			{
				await val.PerformIntent();
			}
			await monster.PerformMove();
			if (!(await CombatManager.Instance.CheckWinCondition()))
			{
				CombatState val2 = CombatManager.Instance.DebugOnlyGetState();
				if (val2 != null && val2.ContainsCreature(creature) && !creature.IsDead)
				{
					creature.PrepareForNextTurn((IEnumerable<Creature>)val2.PlayerCreatures, true);
				}
			}
			return "Performed the selected monster's current intent (" + moveId + ").";
		}

		private static async Task<string> ExecuteAddMonsterAsync(RitsuDebugActionContext context, RitsuDebugRunActions.ModelPayload payload)
		{
			TryResolveMonster(payload.ModelId, out MonsterModel canonical, out RitsuDebugActionFeedback _);
			CombatState combatState = CombatManager.Instance.DebugOnlyGetState();
			PreloadMonsterAssets(canonical);
			string slot = GetAvailableEncounterSlot((ICombatState)(object)combatState);
			await CreatureCmd.Add(canonical.ToMutable(), (ICombatState)(object)combatState, (CombatSide)2, slot);
			if (slot == null)
			{
				RepositionSlotlessEnemies((ICombatState)(object)combatState);
			}
			return $"Added monster {((AbstractModel)canonical).Id} to the current combat.";
		}

		private static async Task<string> ExecuteAddEncounterAsync(RitsuDebugActionContext context, RitsuDebugRunActions.ModelPayload payload)
		{
			RitsuDebugRunActions.TryResolveEncounter(payload.ModelId, out EncounterModel encounter, out RitsuDebugActionFeedback feedback);
			TryCreateEncounterMonsters(encounter, context.Target, out MonsterModel[] monsters, out feedback);
			MonsterModel[] array = monsters;
			for (int i = 0; i < array.Length; i++)
			{
				PreloadMonsterAssets(array[i]);
			}
			CombatState combatState = CombatManager.Instance.DebugOnlyGetState();
			bool addedWithoutSlot = false;
			MonsterModel[] array2 = monsters;
			foreach (MonsterModel obj in array2)
			{
				string availableEncounterSlot = GetAvailableEncounterSlot((ICombatState)(object)combatState);
				if (availableEncounterSlot == null)
				{
					addedWithoutSlot = true;
				}
				await CreatureCmd.Add(obj, (ICombatState)(object)combatState, (CombatSide)2, availableEncounterSlot);
			}
			if (addedWithoutSlot)
			{
				RepositionSlotlessEnemies((ICombatState)(object)combatState);
			}
			return (monsters.Length == 1) ? $"Added 1 enemy from encounter {((AbstractModel)encounter).Id}." : $"Added {monsters.Length} enemies from encounter {((AbstractModel)encounter).Id}.";
		}

