			RitsuDebugModelValueOverrides.Apply(power.DynamicVars, payload.DynamicVars);
			int? amount = payload.Amount;
			if (amount.HasValue)
			{
				int valueOrDefault = amount.GetValueOrDefault();
				if (valueOrDefault != power.Amount)
				{
					await PowerCmd.ModifyAmount((PlayerChoiceContext)new BlockingPlayerChoiceContext(), power, (decimal)(valueOrDefault - power.Amount), (Creature)null, (CardModel)null, false);
					goto IL_011c;
				}
