		}

		private static bool TryResolvePowerInstance(PowerInstancePayload payload, out Creature creature, out PowerModel power, out RitsuDebugActionFeedback feedback)
		{
			creature = null;
			power = null;
			if (!TryRequireCombat(out feedback))
			{
				return false;
			}
			creature = FindCreature(payload.CombatId);
			if (creature == null)
			{
				feedback = RitsuDebugActionFeedback.Create("combat.creatureUnavailable", "The selected creature is no longer available.");
				return false;
			}
			if (payload.Index < 0 || payload.Index >= creature.Powers.Count)
			{
				feedback = RitsuDebugActionFeedback.Create("combat.powerInstanceChanged", "The selected Power instance is no longer available.");
				return false;
			}
			power = creature.Powers[payload.Index];
			if (!string.Equals(((object)((AbstractModel)power).Id).ToString(), payload.PowerId, StringComparison.Ordinal))
			{
				feedback = RitsuDebugActionFeedback.Create("combat.powerInstanceChanged", "The selected Power instance has changed. Refresh and try again.");
				return false;
			}
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}

		private static bool TryCreateEncounterMonsters(EncounterModel canonical, Player target, out MonsterModel[] monsters, out RitsuDebugActionFeedback feedback)
		{
			try
			{
				EncounterModel val = canonical.ToMutable();
				val.GenerateMonstersWithSlots(target.RunState);
				monsters = val.MonstersWithSlots.Select<(MonsterModel, string), MonsterModel>(((MonsterModel, string) entry) => entry.Item1).Take(65).ToArray();
				int num = monsters.Length;
				if (num <= 64)
				{
					if (num == 0)
					{
						feedback = RitsuDebugActionFeedback.Create("combat.encounterEmpty", "Encounter {0} does not generate any enemies.", ((AbstractModel)canonical).Id);
						return false;
					}
					feedback = default(RitsuDebugActionFeedback);
					return true;
				}
				feedback = RitsuDebugActionFeedback.Create("combat.encounterTooLarge", "Encounter {0} generates more than {1} enemies.", ((AbstractModel)canonical).Id, 64);
				monsters = Array.Empty<MonsterModel>();
				return false;
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn($"[DebugTools] Could not generate enemies for encounter '{((AbstractModel)canonical).Id}': {ex}", 1);
				monsters = Array.Empty<MonsterModel>();
				feedback = RitsuDebugActionFeedback.Create("combat.encounterGenerationFailed", "The selected encounter could not generate enemies for the current run.");
				return false;
			}
		}

		internal static void PreloadMonsterAssets(MonsterModel monster)
		{
			foreach (string assetPath in monster.AssetPaths)
			{
				PreloadManager.Cache.GetAsset<Resource>(assetPath);
			}
		}

		internal static bool TryRequireCombat(out RitsuDebugActionFeedback feedback)
		{
			if (CombatManager.Instance.IsInProgress && !CombatManager.Instance.IsOverOrEnding && CombatManager.Instance.DebugOnlyGetState() != null)
			{
				feedback = default(RitsuDebugActionFeedback);
				return true;
			}
			feedback = RitsuDebugActionFeedback.Create("action.activeCombatRequired", "This change requires an active combat.");
			return false;
		}

