					if (entity != null && !entity.IsPlayer && entity.PetOwner == null)
					{
						return !entity.IsDead;
					}
					return false;
				}
				return false;
			}).Take(64).ToArray();
			if (array.Length == 0)
			{
				return;
			}
			EncounterModel encounter = combatState.Encounter;
			float num = ((encounter != null) ? encounter.GetCameraScaling() : 1f);
			if (!float.IsFinite(num) || num <= 0f)
			{
				num = 1f;
			}
			float num2 = 960f / num;
