			float num5 = num4 + (float)(array.Length - 1) * num3;
			float num6 = Math.Max((num2 - num5) * 0.5f, 150f);
			float num7 = 0f;
			if (num6 + num5 > num2 && array.Length > 1)
			{
				num3 = Math.Max((num2 - 150f - num4) / (float)(array.Length - 1), 5f);
				num5 = num4 + (float)(array.Length - 1) * num3;
				num6 = (num2 - num5) * 0.5f;
				if (num3 < 30f)
				{
					num7 = float.Lerp(60f, 40f, (num3 - 5f) / 25f);
				}
			}
			float num8 = num6;
			for (int num9 = 0; num9 < array.Length; num9++)
			{
				((Control)array[num9]).Position = new Vector2(num8 + array2[num9] * 0.5f, 200f - ((num9 % 2 == 0) ? 0f : num7));
				num8 += array2[num9] + num3;
			}
		}

		private static string? GetAvailableEncounterSlot(ICombatState combatState)
		{
			EncounterModel encounter = combatState.Encounter;
			string text = ((encounter != null) ? encounter.GetNextSlot(combatState) : null);
			NCombatRoom instance = NCombatRoom.Instance;
			Control val = ((instance != null) ? instance.EncounterSlots : null);
			if (string.IsNullOrEmpty(text) || val == null || !((Node)val).HasNode(NodePath.op_Implicit(text)))
			{
				return null;
			}
			return text;
		}

		internal static async Task SetCreatureBlockAsync(Creature creature, int block)
		{
			int num = block - creature.Block;
			if (num <= 0)
			{
				if (num < 0)
				{
					await CreatureCmd.LoseBlock((PlayerChoiceContext)new BlockingPlayerChoiceContext(), creature, (decimal)(-num), (Creature)null);
				}
			}
			else
			{
				await CreatureCmd.GainBlock(creature, (decimal)num, (ValueProp)4, (CardPlay)null, false);
			}
		}

		private static bool TryResolveMonsterActionTarget(uint combatId, out Creature creature, out RitsuDebugActionFeedback feedback)
		{
			creature = null;
			if (!TryRequireCombat(out feedback))
			{
				return false;
			}
			Creature val = FindCreature(combatId);
			object obj;
			if (val == null)
			{
				obj = null;
			}
			else
			{
				MonsterModel monster = val.Monster;
				obj = ((monster != null) ? monster.MoveStateMachine : null);
			}
			if (obj == null || val.IsPlayer || val.IsDead)
			{
				feedback = RitsuDebugActionFeedback.Create("combat.monsterIntentTargetRequired", "Select a living enemy monster with available intents.");
				return false;
			}
			if (!TryValidateMonsterActionTarget(val, out feedback))
			{
				return false;
			}
			creature = val;
			return true;
		}

		private static MoveState ResolveRandomGroupMove(Creature creature, RandomBranchState group)
		{
			//IL_00ea: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f0: Expected O, but got Unknown
			MonsterModel monster = creature.Monster;
			MonsterMoveStateMachine moveStateMachine = monster.MoveStateMachine;
			MonsterState val = (MonsterState)(object)group;
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			while (!(val is MoveState))
			{
				if (!hashSet.Add(val.Id) || hashSet.Count > moveStateMachine.States.Count)
				{
					throw new InvalidOperationException("Intent group '" + ((MonsterState)group).Id + "' contains a branch cycle.");
				}
				string nextState = val.GetNextState(creature, monster.RunRng.MonsterAi);
				if (string.IsNullOrWhiteSpace(nextState) || !moveStateMachine.States.TryGetValue(nextState, out var value))
				{
					throw new InvalidOperationException($"Intent group '{((MonsterState)group).Id}' resolved to unknown state '{nextState}'.");
				}
				val = value;
			}
			return (MoveState)val;
		}

		private static bool TryValidateMonsterActionTarget(Creature creature, out RitsuDebugActionFeedback feedback)
		{
			//IL_004d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0053: Invalid comparison between Unknown and I4
			if (!creature.IsPlayer)
			{
				MonsterModel monster = creature.Monster;
				if (((monster != null) ? monster.MoveStateMachine : null) != null && !creature.IsDead)
				{
					ICombatState combatState = creature.CombatState;
					if (combatState == null || (int)combatState.CurrentSide != 1 || creature.Monster.IsPerformingMove)
					{
						feedback = RitsuDebugActionFeedback.Create("combat.monsterActionPlayerTurnRequired", "Monster intent actions are available during the player turn while the monster is idle.");
						return false;
					}
					feedback = default(RitsuDebugActionFeedback);
					return true;
				}
			}
			feedback = RitsuDebugActionFeedback.Create("combat.monsterIntentTargetRequired", "Select a living enemy monster with available intents.");
			return false;
		}
	}
	internal static class RitsuDebugCreaturePresetActions
	{
		internal readonly record struct ApplyPayload(uint CombatId, RitsuDebugCreaturePreset Preset);

		internal readonly record struct PresetPayload(RitsuDebugCreaturePreset Preset);

		internal const string ApplyPresetActionId = "combat.creature-preset.apply";

		internal const string AddPresetMonsterActionId = "combat.creature-preset.add";

		internal static void RegisterBuiltInActions()
		{
			RitsuDebugActionProtocol.Register<ApplyPayload>("combat.creature-preset.apply", ValidateApplyPreset, ExecuteApplyPresetAsync);
			RitsuDebugActionProtocol.Register<PresetPayload>("combat.creature-preset.add", ValidateAddPresetMonster, ExecuteAddPresetMonsterAsync);
		}

		internal static RitsuDebugActionSubmission SubmitApplyPreset(Player requester, Player actionTarget, uint combatId, RitsuDebugCreaturePreset preset)
		{
			ArgumentNullException.ThrowIfNull(preset, "preset");
			return Submit(requester, actionTarget, "combat.creature-preset.apply", new ApplyPayload(combatId, preset.Clone()));
		}

		internal static RitsuDebugActionSubmission SubmitAddPresetMonster(Player requester, Player actionTarget, RitsuDebugCreaturePreset preset)
		{
			ArgumentNullException.ThrowIfNull(preset, "preset");
			return Submit(requester, actionTarget, "combat.creature-preset.add", new PresetPayload(preset.Clone()));
		}

		internal static RitsuDebugActionCheck ValidateStoredPreset(RitsuDebugCreaturePreset preset)
		{
			ArgumentNullException.ThrowIfNull(preset, "preset");
			string id = preset.Id;
			bool flag = id == null || id.Length != 32 || !Guid.TryParseExact(preset.Id, "N", out var _) || string.IsNullOrWhiteSpace(preset.Name) || preset.Name.Length > 80 || preset.Powers == null || preset.CurrentHp < 1;
			if (!flag)
			{
				int maxHp = preset.MaxHp;
				bool flag2 = ((maxHp < 1 || maxHp > 999999999) ? true : false);
				flag = flag2;
			}
			bool flag3 = flag || preset.CurrentHp > preset.MaxHp;
			if (!flag3)
			{
				int maxHp = preset.Block;
				bool flag2 = ((maxHp < 0 || maxHp > 999999999) ? true : false);
				flag3 = flag2;
			}
			if (flag3)
			{
				return RitsuDebugActionCheck.Fail("creaturePreset.invalid", "The creature preset is missing required data or contains unsupported values.");
			}
			if (!RitsuDebugCombatActions.TryResolveMonster(preset.MonsterId, out MonsterModel _, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (preset.Powers.Count > 128)
			{
				return RitsuDebugActionCheck.Fail("creaturePreset.powerLimit", "At most {0} powers can be stored in one creature preset.", 128);
			}
			HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
			foreach (RitsuDebugStatePresetPower power2 in preset.Powers)
			{
				flag3 = power2 == null;
				if (!flag3)
				{
					int maxHp = power2.Amount;
					flag = ((maxHp < 1 || maxHp > 999999999) ? true : false);
					flag3 = flag;
				}
				if (flag3)
				{
					return RitsuDebugActionCheck.Fail("creaturePreset.powerInvalid", "A saved Power entry is invalid or duplicated.");
				}
				if (!RitsuDebugCombatActions.TryResolvePower(power2.PowerId, out PowerModel power, out feedback))
				{
					return RitsuDebugActionCheck.Fail(feedback);
				}
				if (!hashSet.Add(((object)((AbstractModel)power).Id).ToString()))
				{
					return RitsuDebugActionCheck.Fail("creaturePreset.powerInvalid", "A saved Power entry is invalid or duplicated.");
				}
			}
			if (JsonSerializer.Serialize(preset).Length > 8192)
			{
				return RitsuDebugActionCheck.Fail("creaturePreset.dataLimit", "The creature preset contains too much data to apply.");
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionSubmission Submit<TPayload>(Player requester, Player actionTarget, string actionId, TPayload payload)
		{
			return RitsuDebugActionProtocol.Submit(requester, RitsuDebugActionProtocol.CreateEnvelope(actionId, requester, actionTarget, payload));
		}

		private static RitsuDebugActionCheck ValidateApplyPreset(RitsuDebugActionContext context, ApplyPayload payload)
		{
			RitsuDebugActionCheck result = ValidateForCombat(payload.Preset);
			if (!result.Success)
			{
				return result;
			}
			Creature val = RitsuDebugCombatActions.FindCreature(payload.CombatId);
			if (val == null)
			{
				return RitsuDebugActionCheck.Fail("combat.creatureUnavailable", "The selected creature is no longer available.");
			}
			if (val.IsPlayer)
			{
				return RitsuDebugActionCheck.Fail("creaturePreset.enemyRequired", "Creature presets can only be applied to enemies.");
			}
			if (!val.CanReceivePowers && payload.Preset.Powers.Count != 0)
			{
				return RitsuDebugActionCheck.Fail("combat.cannotReceivePowers", "The selected creature cannot receive powers right now.");
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateAddPresetMonster(RitsuDebugActionContext context, PresetPayload payload)
		{
			RitsuDebugActionCheck result = ValidateForCombat(payload.Preset);
			if (!result.Success)
			{
				return result;
			}
			if (CombatManager.Instance.DebugOnlyGetState().Enemies.Count >= 64)
			{
				return RitsuDebugActionCheck.Fail("combat.enemyLimit", "These tools support at most {0} enemies in one combat.", 64);
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateForCombat(RitsuDebugCreaturePreset preset)
		{
			if (!RitsuDebugCombatActions.TryRequireCombat(out var feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			return ValidateStoredPreset(preset);
		}

		private static async Task<string> ExecuteApplyPresetAsync(RitsuDebugActionContext context, ApplyPayload payload)
		{
			await ApplyPreset(RitsuDebugCombatActions.FindCreature(payload.CombatId), payload.Preset);
			return "Applied creature preset " + payload.Preset.Name + " to the selected enemy.";
		}

		private static async Task<string> ExecuteAddPresetMonsterAsync(RitsuDebugActionContext context, PresetPayload payload)
		{
			RitsuDebugCombatActions.TryResolveMonster(payload.Preset.MonsterId, out MonsterModel monster, out RitsuDebugActionFeedback _);
			RitsuDebugCombatActions.PreloadMonsterAssets(monster);
			CombatState combatState = CombatManager.Instance.DebugOnlyGetState();
			EncounterModel encounter = combatState.Encounter;
			string slot = ((encounter != null) ? encounter.GetNextSlot((ICombatState)(object)combatState) : null);
			if (string.IsNullOrEmpty(slot))
			{
				slot = null;
			}
			await ApplyPreset(await CreatureCmd.Add(monster.ToMutable(), (ICombatState)(object)combatState, (CombatSide)2, slot), payload.Preset);
			if (slot == null)
			{
				RitsuDebugCombatActions.RepositionSlotlessEnemies((ICombatState)(object)combatState);
			}
			return "Added creature preset " + payload.Preset.Name + " to the current combat.";
		}

		private static async Task ApplyPreset(Creature creature, RitsuDebugCreaturePreset preset)
		{
			bool currentHpSetFirst = preset.MaxHp < creature.CurrentHp;
			if (currentHpSetFirst && creature.CurrentHp != preset.CurrentHp)
			{
				await CreatureCmd.SetCurrentHp(creature, (decimal)preset.CurrentHp);
			}
			if (creature.MaxHp != preset.MaxHp)
			{
				await CreatureCmd.SetMaxHp(creature, (decimal)preset.MaxHp);
			}
			if (!currentHpSetFirst && creature.CurrentHp != preset.CurrentHp)
			{
				await CreatureCmd.SetCurrentHp(creature, (decimal)preset.CurrentHp);
			}
			await RitsuDebugCombatActions.SetCreatureBlockAsync(creature, preset.Block);
			PowerModel[] array = creature.Powers.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				await PowerCmd.Remove(array[i]);
			}
			BlockingPlayerChoiceContext choiceContext = new BlockingPlayerChoiceContext();
			foreach (RitsuDebugStatePresetPower power2 in preset.Powers)
			{
				RitsuDebugCombatActions.TryResolvePower(power2.PowerId, out PowerModel power, out RitsuDebugActionFeedback _);
				await PowerCmd.Apply((PlayerChoiceContext)(object)choiceContext, power.ToMutable(0), creature, (decimal)power2.Amount, (Creature)null, (CardModel)null, false);
			}
		}
	}
