	internal static class RitsuDebugCreaturePresetStore
	{
		internal const int MaximumPresetCount = 64;

		internal const int MaximumNameLength = 80;

		internal const string DataKey = "debug-creature-presets";

		internal const string FileName = "debug_creature_presets.json";

		private static readonly ModDataStore Store = ModDataStore.For("com.ritsukage.sts2-RitsuLib");

		internal static IReadOnlyList<RitsuDebugCreaturePreset> GetSnapshot()
		{
			RitsuLibSettingsStore.Initialize();
			return Array.AsReadOnly((from preset in (Store.Get<RitsuDebugCreaturePresetCollection>("debug-creature-presets").Presets ?? new List<RitsuDebugCreaturePreset>()).Where(IsReadable).Take(64)
				select preset.Clone()).ToArray());
		}

		internal static bool TryCapture(Creature creature, string name, out RitsuDebugCreaturePreset preset, out RitsuDebugActionFeedback feedback)
		{
			ArgumentNullException.ThrowIfNull(creature, "creature");
			preset = null;
			if (creature.IsPlayer || creature.Monster == null)
			{
				feedback = RitsuDebugActionFeedback.Create("creaturePreset.monsterRequired", "Only enemies backed by a monster model can be saved as a creature preset.");
				return false;
			}
			preset = new RitsuDebugCreaturePreset
			{
				Name = name.Trim(),
				MonsterId = ((object)((AbstractModel)creature.Monster).Id).ToString(),
				CurrentHp = creature.CurrentHp,
				MaxHp = creature.MaxHp,
				Block = creature.Block,
				Powers = creature.Powers.Select((PowerModel power) => new RitsuDebugStatePresetPower
				{
					PowerId = ((object)((AbstractModel)power).Id).ToString(),
					Amount = power.Amount
				}).ToList()
			};
			RitsuDebugActionCheck ritsuDebugActionCheck = RitsuDebugCreaturePresetActions.ValidateStoredPreset(preset);
			if (ritsuDebugActionCheck.Success)
			{
				feedback = default(RitsuDebugActionFeedback);
				return true;
			}
			preset = null;
			feedback = ritsuDebugActionCheck.Feedback;
			return false;
		}

		internal static bool TrySave(RitsuDebugCreaturePreset preset, out RitsuDebugActionFeedback feedback)
		{
			ArgumentNullException.ThrowIfNull(preset, "preset");
			RitsuDebugActionCheck ritsuDebugActionCheck = RitsuDebugCreaturePresetActions.ValidateStoredPreset(preset);
			if (!ritsuDebugActionCheck.Success)
			{
				feedback = ritsuDebugActionCheck.Feedback;
				return false;
			}
			RitsuLibSettingsStore.Initialize();
			RitsuDebugCreaturePresetCollection ritsuDebugCreaturePresetCollection = Store.Get<RitsuDebugCreaturePresetCollection>("debug-creature-presets");
			RitsuDebugCreaturePresetCollection ritsuDebugCreaturePresetCollection2 = ritsuDebugCreaturePresetCollection;
			if (ritsuDebugCreaturePresetCollection2.Presets == null)
			{
				List<RitsuDebugCreaturePreset> list = (ritsuDebugCreaturePresetCollection2.Presets = new List<RitsuDebugCreaturePreset>());
			}
			int num = ritsuDebugCreaturePresetCollection.Presets.FindIndex((RitsuDebugCreaturePreset candidate) => candidate != null && string.Equals(candidate.Id, preset.Id, StringComparison.OrdinalIgnoreCase));
			if (ritsuDebugCreaturePresetCollection.Presets.Any((RitsuDebugCreaturePreset candidate) => IsReadable(candidate) && !string.Equals(candidate.Id, preset.Id, StringComparison.OrdinalIgnoreCase) && string.Equals(candidate.Name, preset.Name.Trim(), StringComparison.OrdinalIgnoreCase)))
			{
				feedback = RitsuDebugActionFeedback.Create("creaturePreset.duplicateName", "A creature preset named '{0}' already exists.", preset.Name.Trim());
				return false;
			}
			if (num < 0 && ritsuDebugCreaturePresetCollection.Presets.Count(IsReadable) >= 64)
			{
				feedback = RitsuDebugActionFeedback.Create("creaturePreset.countLimit", "At most {0} creature presets can be stored.", 64);
				return false;
			}
			RitsuDebugCreaturePreset ritsuDebugCreaturePreset = preset.Clone();
			ritsuDebugCreaturePreset.Name = ritsuDebugCreaturePreset.Name.Trim();
			if (num < 0)
			{
				ritsuDebugCreaturePresetCollection.Presets.Add(ritsuDebugCreaturePreset);
			}
			else
			{
				ritsuDebugCreaturePresetCollection.Presets[num] = ritsuDebugCreaturePreset;
			}
			ritsuDebugCreaturePresetCollection.SchemaVersion = 1;
			Store.Save("debug-creature-presets");
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}

		internal static bool TryDelete(string presetId)
		{
			if (!IsValidId(presetId))
			{
				return false;
			}
			RitsuLibSettingsStore.Initialize();
			RitsuDebugCreaturePresetCollection ritsuDebugCreaturePresetCollection2;
			RitsuDebugCreaturePresetCollection ritsuDebugCreaturePresetCollection = (ritsuDebugCreaturePresetCollection2 = Store.Get<RitsuDebugCreaturePresetCollection>("debug-creature-presets"));
			if (ritsuDebugCreaturePresetCollection2.Presets == null)
			{
				List<RitsuDebugCreaturePreset> list = (ritsuDebugCreaturePresetCollection2.Presets = new List<RitsuDebugCreaturePreset>());
			}
			bool num = ritsuDebugCreaturePresetCollection.Presets.RemoveAll((RitsuDebugCreaturePreset candidate) => candidate != null && string.Equals(candidate.Id, presetId, StringComparison.OrdinalIgnoreCase)) > 0;
			if (num)
			{
				Store.Save("debug-creature-presets");
			}
			return num;
		}

		private static bool IsReadable(RitsuDebugCreaturePreset? preset)
		{
			if (preset != null && IsValidId(preset.Id) && !string.IsNullOrWhiteSpace(preset.Name) && preset.Name.Length <= 80 && !string.IsNullOrWhiteSpace(preset.MonsterId) && preset.Powers != null)
			{
				return preset.Powers.All((RitsuDebugStatePresetPower power) => power != null);
			}
			return false;
		}

		private static bool IsValidId(string? id)
		{
			Guid result;
			if (id != null && id.Length == 32)
			{
				return Guid.TryParseExact(id, "N", out result);
			}
			return false;
		}
	}
	internal enum RitsuDebugInventoryKind
	{
		Relics,
		Potions
	}
	internal static class RitsuDebugInventoryActions
	{
		internal readonly record struct ModelPayload(string ModelId);

		internal readonly record struct ModelValuesPayload(string ModelId, Dictionary<string, int>? DynamicVars);

		internal readonly record struct RelicValuesPayload(string ModelId, int StackCount, Dictionary<string, int>? DynamicVars);

		internal readonly record struct RelicEditPayload(string ModelId, int? RelicIndex, Dictionary<string, int> DynamicVars);

		internal readonly record struct RelicInstancePayload(string ModelId, int? RelicIndex);

		internal readonly record struct PotionSlotPayload(int SlotIndex, string ExpectedPotionId);

		internal readonly record struct PotionValuesPayload(int SlotIndex, string ExpectedPotionId, Dictionary<string, int> DynamicVars);

		internal readonly record struct ClearInventoryPayload(RitsuDebugInventoryKind Kind);

		internal const string AddRelicActionId = "inventory.relic.add";

		internal const string EditRelicActionId = "inventory.relic.edit";

		internal const string RemoveRelicActionId = "inventory.relic.remove";

		internal const string AddPotionActionId = "inventory.potion.add";

		internal const string EditPotionActionId = "inventory.potion.edit";

		internal const string DiscardPotionActionId = "inventory.potion.discard";

		internal const string ClearInventoryActionId = "inventory.clear";

		internal const int MaxRelicStackCount = 9999;

		internal static void RegisterBuiltInActions()
		{
			RitsuDebugActionProtocol.Register<RelicValuesPayload>("inventory.relic.add", ValidateAddRelic, ExecuteAddRelicAsync);
			RitsuDebugActionProtocol.Register<RelicEditPayload>("inventory.relic.edit", ValidateEditRelic, ExecuteEditRelicAsync);
			RitsuDebugActionProtocol.Register<RelicInstancePayload>("inventory.relic.remove", ValidateRemoveRelic, ExecuteRemoveRelicAsync);
			RitsuDebugActionProtocol.Register<ModelValuesPayload>("inventory.potion.add", ValidateAddPotion, ExecuteAddPotionAsync);
			RitsuDebugActionProtocol.Register<PotionValuesPayload>("inventory.potion.edit", ValidateEditPotion, ExecuteEditPotionAsync);
			RitsuDebugActionProtocol.Register<PotionSlotPayload>("inventory.potion.discard", ValidateDiscardPotion, ExecuteDiscardPotionAsync);
			RitsuDebugActionProtocol.Register<ClearInventoryPayload>("inventory.clear", ValidateClearInventory, ExecuteClearInventoryAsync);
		}

		internal static RitsuDebugActionSubmission SubmitAddRelic(Player requester, Player target, string relicId, int stackCount = 1, IReadOnlyDictionary<string, int>? dynamicVars = null)
		{
			RitsuDebugActionEnvelope envelope = RitsuDebugActionProtocol.CreateEnvelope("inventory.relic.add", requester, target, new RelicValuesPayload(relicId, stackCount, CopyOverrides(dynamicVars)));
			return RitsuDebugActionProtocol.Submit(requester, envelope);
		}

		internal static RitsuDebugActionSubmission SubmitEditRelic(Player requester, Player target, string relicId, IReadOnlyDictionary<string, int> dynamicVars, int? relicIndex = null)
		{
			ArgumentNullException.ThrowIfNull(dynamicVars, "dynamicVars");
			RitsuDebugActionEnvelope envelope = RitsuDebugActionProtocol.CreateEnvelope("inventory.relic.edit", requester, target, new RelicEditPayload(relicId, relicIndex, CopyOverrides(dynamicVars)));
			return RitsuDebugActionProtocol.Submit(requester, envelope);
		}

		internal static RitsuDebugActionSubmission SubmitRemoveRelic(Player requester, Player target, string relicId, int? relicIndex = null)
		{
			RitsuDebugActionEnvelope envelope = RitsuDebugActionProtocol.CreateEnvelope("inventory.relic.remove", requester, target, new RelicInstancePayload(relicId, relicIndex));
			return RitsuDebugActionProtocol.Submit(requester, envelope);
		}

		internal static RitsuDebugActionSubmission SubmitAddPotion(Player requester, Player target, string potionId, IReadOnlyDictionary<string, int>? dynamicVars = null)
		{
			RitsuDebugActionEnvelope envelope = RitsuDebugActionProtocol.CreateEnvelope("inventory.potion.add", requester, target, new ModelValuesPayload(potionId, CopyOverrides(dynamicVars)));
			return RitsuDebugActionProtocol.Submit(requester, envelope);
		}

		internal static RitsuDebugActionSubmission SubmitEditPotion(Player requester, Player target, int slotIndex, string expectedPotionId, IReadOnlyDictionary<string, int> dynamicVars)
		{
			ArgumentNullException.ThrowIfNull(dynamicVars, "dynamicVars");
			RitsuDebugActionEnvelope envelope = RitsuDebugActionProtocol.CreateEnvelope("inventory.potion.edit", requester, target, new PotionValuesPayload(slotIndex, expectedPotionId, CopyOverrides(dynamicVars)));
			return RitsuDebugActionProtocol.Submit(requester, envelope);
		}

		internal static RitsuDebugActionSubmission SubmitDiscardPotion(Player requester, Player target, int slotIndex, string expectedPotionId)
		{
			RitsuDebugActionEnvelope envelope = RitsuDebugActionProtocol.CreateEnvelope("inventory.potion.discard", requester, target, new PotionSlotPayload(slotIndex, expectedPotionId));
			return RitsuDebugActionProtocol.Submit(requester, envelope);
		}

		internal static RitsuDebugActionSubmission SubmitClearInventory(Player requester, Player target, RitsuDebugInventoryKind kind)
		{
			RitsuDebugActionEnvelope envelope = RitsuDebugActionProtocol.CreateEnvelope("inventory.clear", requester, target, new ClearInventoryPayload(kind));
			return RitsuDebugActionProtocol.Submit(requester, envelope);
		}

		internal static bool TryResolveRelic(string input, out RelicModel relic, out RitsuDebugActionFeedback feedback)
		{
			return TryResolveModel<RelicModel>(ModelDb.AllRelics, input, "relic", out relic, out feedback);
		}

		internal static bool TryResolvePotion(string input, out PotionModel potion, out RitsuDebugActionFeedback feedback)
		{
			return TryResolveModel<PotionModel>(ModelDb.AllPotions, input, "potion", out potion, out feedback);
		}

		private static RitsuDebugActionSubmission SubmitModel(Player requester, Player target, string actionId, string modelId)
		{
			RitsuDebugActionEnvelope envelope = RitsuDebugActionProtocol.CreateEnvelope(actionId, requester, target, new ModelPayload(modelId));
			return RitsuDebugActionProtocol.Submit(requester, envelope);
		}

		internal static RitsuDebugActionCheck ValidateAddRelic(RitsuDebugActionContext context, RelicValuesPayload payload)
		{
			if (!TryResolveRelic(payload.ModelId, out RelicModel relic, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			int stackCount = payload.StackCount;
			if ((stackCount < 1 || stackCount > 9999) ? true : false)
			{
				return RitsuDebugActionCheck.Fail("inventory.relicStackRange", "Relic stack count must be between 1 and {0}.", 9999);
			}
			if (!relic.IsStackable && payload.StackCount != 1)
			{
				return RitsuDebugActionCheck.Fail("inventory.relicNotStackable", "Relic {0} does not support multiple stacks.", ((AbstractModel)relic).Id);
			}
			RitsuDebugActionCheck result = RitsuDebugModelValueOverrides.Validate(relic.DynamicVars, payload.DynamicVars);
			if (!result.Success)
			{
				return result;
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateEditRelic(RitsuDebugActionContext context, RelicEditPayload payload)
		{
			if (payload.DynamicVars == null || payload.DynamicVars.Count == 0)
			{
				return RitsuDebugActionCheck.Fail("model.dynamicVarEditEmpty", "Change at least one model value before applying the edit.");
			}
			if (!TryResolveRelic(payload.ModelId, out RelicModel relic, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			RelicModel ownedRelic = GetOwnedRelic(context.Target, relic, payload.RelicIndex);
			if (ownedRelic != null)
			{
				return RitsuDebugModelValueOverrides.Validate(ownedRelic.DynamicVars, payload.DynamicVars);
			}
			return RitsuDebugActionCheck.Fail("inventory.relicNotOwned", "The target player does not own {0}.", ((AbstractModel)relic).Id);
		}

		private static RitsuDebugActionCheck ValidateRemoveRelic(RitsuDebugActionContext context, RelicInstancePayload payload)
		{
			if (!TryResolveRelic(payload.ModelId, out RelicModel relic, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (GetOwnedRelic(context.Target, relic, payload.RelicIndex) == null)
			{
				return RitsuDebugActionCheck.Fail("inventory.relicNotOwned", "The target player does not own {0}.", ((AbstractModel)relic).Id);
			}
			return RitsuDebugActionCheck.Ok;
		}

		internal static RitsuDebugActionCheck ValidateAddPotion(RitsuDebugActionContext context, ModelValuesPayload payload)
		{
			if (!TryResolvePotion(payload.ModelId, out PotionModel potion, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			RitsuDebugActionCheck result = RitsuDebugModelValueOverrides.Validate(potion.DynamicVars, payload.DynamicVars);
			if (!result.Success)
			{
				return result;
			}
			if (FindEmptyPotionSlot(context.Target) < 0)
			{
				return RitsuDebugActionCheck.Fail("inventory.potionBeltFull", "The target player's potion belt is full.");
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateEditPotion(RitsuDebugActionContext context, PotionValuesPayload payload)
		{
			if (payload.DynamicVars == null || payload.DynamicVars.Count == 0)
			{
				return RitsuDebugActionCheck.Fail("model.dynamicVarEditEmpty", "Change at least one model value before applying the edit.");
			}
			if (!TryResolvePotionSlot(context.Target, payload.SlotIndex, payload.ExpectedPotionId, out PotionModel potion, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			return RitsuDebugModelValueOverrides.Validate(potion.DynamicVars, payload.DynamicVars);
		}

		private static RitsuDebugActionCheck ValidateDiscardPotion(RitsuDebugActionContext context, PotionSlotPayload payload)
		{
			if (payload.SlotIndex < 0 || payload.SlotIndex >= context.Target.MaxPotionCount)
			{
				return RitsuDebugActionCheck.Fail("inventory.potionSlotRange", "Potion slot must be between 0 and {0}.", context.Target.MaxPotionCount - 1);
			}
			PotionModel potionAtSlotIndex = context.Target.GetPotionAtSlotIndex(payload.SlotIndex);
			if (potionAtSlotIndex == null)
			{
				return RitsuDebugActionCheck.Fail("inventory.potionSlotEmpty", "Potion slot {0} is empty.", payload.SlotIndex);
			}
			if (!((object)((AbstractModel)potionAtSlotIndex).Id).ToString().Equals(payload.ExpectedPotionId, StringComparison.Ordinal))
			{
				return RitsuDebugActionCheck.Fail("inventory.potionSlotChanged", "The potion in slot {0} changed before the action could run.", payload.SlotIndex);
			}
			return RitsuDebugActionCheck.Ok;
		}

		internal static RitsuDebugActionCheck ValidateClearInventory(RitsuDebugActionContext context, ClearInventoryPayload payload)
		{
			if (!Enum.IsDefined(payload.Kind))
			{
				return RitsuDebugActionCheck.Fail("inventory.invalidKind", "The inventory type is invalid.");
			}
			if (payload.Kind switch
			{
				RitsuDebugInventoryKind.Relics => (context.Target.Relics.Count > 0) ? 1 : 0, 
				RitsuDebugInventoryKind.Potions => Enumerable.Range(0, context.Target.MaxPotionCount).Any((int index) => context.Target.GetPotionAtSlotIndex(index) != null) ? 1 : 0, 
				_ => 0, 
			} == 0)
			{
				return RitsuDebugActionCheck.Fail("inventory.alreadyEmpty", "The selected inventory is already empty.");
			}
			return RitsuDebugActionCheck.Ok;
		}

		internal static async Task<string> ExecuteAddRelicAsync(RitsuDebugActionContext context, RelicValuesPayload payload)
		{
			TryResolveRelic(payload.ModelId, out RelicModel relic, out RitsuDebugActionFeedback _);
			RelicModel val = relic.ToMutable();
			RitsuDebugModelValueOverrides.Apply(val.DynamicVars, payload.DynamicVars);
			for (int i = 1; i < payload.StackCount; i++)
			{
				val.IncrementStackCount();
			}
			await RelicCmd.Obtain(val, context.Target, -1);
			return $"Added relic {((AbstractModel)relic).Id} to the selected player.";
		}

		private static Task<string> ExecuteEditRelicAsync(RitsuDebugActionContext context, RelicEditPayload payload)
		{
			TryResolveRelic(payload.ModelId, out RelicModel relic, out RitsuDebugActionFeedback _);
			RelicModel ownedRelic = GetOwnedRelic(context.Target, relic, payload.RelicIndex);
			RitsuDebugModelValueOverrides.Apply(ownedRelic.DynamicVars, payload.DynamicVars);
			((AbstractModel)ownedRelic).InvokeExecutionFinished();
			return Task.FromResult($"Updated values for relic {((AbstractModel)ownedRelic).Id}.");
		}

		private static async Task<string> ExecuteRemoveRelicAsync(RitsuDebugActionContext context, RelicInstancePayload payload)
		{
			TryResolveRelic(payload.ModelId, out RelicModel relic, out RitsuDebugActionFeedback _);
			await RelicCmd.Remove(GetOwnedRelic(context.Target, relic, payload.RelicIndex));
			return $"Removed relic {((AbstractModel)relic).Id} from the selected player.";
		}

		internal static async Task<string> ExecuteAddPotionAsync(RitsuDebugActionContext context, ModelValuesPayload payload)
		{
			return await ExecuteAddPotionAtSlotAsync(context, payload, -1);
		}

		internal static Task<string> ExecuteAddPotionAtSlotAsync(RitsuDebugActionContext context, ModelPayload payload, int slotIndex)
		{
			return ExecuteAddPotionAtSlotAsync(context, new ModelValuesPayload(payload.ModelId, null), slotIndex);
		}

		internal static async Task<string> ExecuteAddPotionAtSlotAsync(RitsuDebugActionContext context, ModelValuesPayload payload, int slotIndex)
		{
			TryResolvePotion(payload.ModelId, out PotionModel potion, out RitsuDebugActionFeedback _);
			PotionModel obj = potion.ToMutable();
			RitsuDebugModelValueOverrides.Apply(obj.DynamicVars, payload.DynamicVars);
			if (!(await PotionCmd.TryToProcure(obj, context.Target, slotIndex)).success)
			{
				throw new RitsuDebugActionExecutionException(RitsuDebugActionFeedback.Create("inventory.potionAddFailed", "The game did not add potion {0} to the selected player.", ((AbstractModel)potion).Id));
			}
			return $"Added potion {((AbstractModel)potion).Id} to the selected player.";
		}

		private static Task<string> ExecuteEditPotionAsync(RitsuDebugActionContext context, PotionValuesPayload payload)
		{
			TryResolvePotionSlot(context.Target, payload.SlotIndex, payload.ExpectedPotionId, out PotionModel potion, out RitsuDebugActionFeedback _);
			RitsuDebugModelValueOverrides.Apply(potion.DynamicVars, payload.DynamicVars);
			((AbstractModel)potion).InvokeExecutionFinished();
			return Task.FromResult($"Updated values for potion {((AbstractModel)potion).Id}.");
		}

		private static async Task<string> ExecuteDiscardPotionAsync(RitsuDebugActionContext context, PotionSlotPayload payload)
		{
			PotionModel potion = context.Target.GetPotionAtSlotIndex(payload.SlotIndex);
			await PotionCmd.Discard(potion);
			return $"Discarded potion {((AbstractModel)potion).Id} from slot {payload.SlotIndex + 1}.";
		}

		internal static async Task<string> ExecuteClearInventoryAsync(RitsuDebugActionContext context, ClearInventoryPayload payload)
		{
			if (payload.Kind == RitsuDebugInventoryKind.Relics)
			{
				RelicModel[] relics = context.Target.Relics.ToArray();
				RelicModel[] array = relics;
				for (int i = 0; i < array.Length; i++)
				{
					await RelicCmd.Remove(array[i]);
				}
				return (relics.Length == 1) ? "Removed the selected player's relic." : $"Removed all {relics.Length} relics from the selected player.";
			}
			PotionModel[] potions = Enumerable.Range(0, context.Target.MaxPotionCount).Select((Func<int, PotionModel>)context.Target.GetPotionAtSlotIndex).OfType<PotionModel>()
				.ToArray();
			PotionModel[] array2 = potions;
			for (int i = 0; i < array2.Length; i++)
			{
				await PotionCmd.Discard(array2[i]);
			}
			return (potions.Length == 1) ? "Discarded the selected player's potion." : $"Discarded all {potions.Length} potions from the selected player.";
		}

		private static int FindEmptyPotionSlot(Player player)
		{
			for (int i = 0; i < player.MaxPotionCount; i++)
			{
				if (player.GetPotionAtSlotIndex(i) == null)
				{
					return i;
				}
			}
			return -1;
		}

		private static RelicModel? GetOwnedRelic(Player player, RelicModel canonical, int? relicIndex)
		{
			if (!relicIndex.HasValue)
			{
				return player.GetRelicById(((AbstractModel)canonical).Id);
			}
			if (relicIndex.Value < 0 || relicIndex.Value >= player.Relics.Count || !(((AbstractModel)player.Relics[relicIndex.Value]).Id == ((AbstractModel)canonical).Id))
			{
				return null;
			}
			return player.Relics[relicIndex.Value];
		}

		private static bool TryResolvePotionSlot(Player player, int slotIndex, string expectedPotionId, out PotionModel potion, out RitsuDebugActionFeedback feedback)
		{
			potion = null;
			if (slotIndex < 0 || slotIndex >= player.MaxPotionCount)
			{
				feedback = RitsuDebugActionFeedback.Create("inventory.potionSlotRange", "Potion slot must be between 0 and {0}.", player.MaxPotionCount - 1);
				return false;
			}
			PotionModel potionAtSlotIndex = player.GetPotionAtSlotIndex(slotIndex);
			if (potionAtSlotIndex == null)
			{
				feedback = RitsuDebugActionFeedback.Create("inventory.potionSlotEmpty", "Potion slot {0} is empty.", slotIndex);
				return false;
			}
			if (!((object)((AbstractModel)potionAtSlotIndex).Id).ToString().Equals(expectedPotionId, StringComparison.Ordinal))
			{
				feedback = RitsuDebugActionFeedback.Create("inventory.potionSlotChanged", "The potion in slot {0} changed before the action could run.", slotIndex);
				return false;
			}
			potion = potionAtSlotIndex;
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}

		private static Dictionary<string, int>? CopyOverrides(IReadOnlyDictionary<string, int>? values)
		{
			return values?.ToDictionary<KeyValuePair<string, int>, string, int>((KeyValuePair<string, int> pair) => pair.Key, (KeyValuePair<string, int> pair) => pair.Value, StringComparer.Ordinal);
		}

		private static bool TryResolveModel<TModel>(IEnumerable<TModel> candidates, string input, string kind, out TModel model, out RitsuDebugActionFeedback feedback) where TModel : AbstractModel
		{
			model = default(TModel);
			if (string.IsNullOrWhiteSpace(input) || input.Length > 128)
			{
				feedback = RitsuDebugActionFeedback.Create("model." + kind + "IdInvalid", "The " + kind + " ID is empty or too long.");
				return false;
			}
			TModel[] source = (candidates as TModel[]) ?? candidates.ToArray();
			TModel[] array = source.Where((TModel candidate) => ((object)((AbstractModel)candidate).Id).ToString().Equals(input, StringComparison.OrdinalIgnoreCase)).Take(2).ToArray();
			TModel[] array2 = ((array.Length != 0) ? array : source.Where((TModel candidate) => ((AbstractModel)candidate).Id.Entry.Equals(input, StringComparison.OrdinalIgnoreCase)).Take(2).ToArray());
			if (array2.Length == 1)
			{
				model = array2[0];
				feedback = default(RitsuDebugActionFeedback);
				return true;
			}
			feedback = ((array2.Length == 0) ? RitsuDebugActionFeedback.Create("model." + kind + "Unknown", "Unknown " + kind + " '{0}'.", input) : RitsuDebugActionFeedback.Create("model." + kind + "Ambiguous", "The " + kind + " ID '{0}' is ambiguous; use the full model ID.", input));
			return false;
		}
	}
	internal static class RitsuDebugModelValueOverrides
	{
		internal const int MaximumDynamicVariableCount = 128;

		internal const int MaximumValue = 999999999;

		internal const int MinimumValue = -999999999;

		internal static bool IsEditable(DynamicVar dynamicVar)
		{
			ArgumentNullException.ThrowIfNull(dynamicVar, "dynamicVar");
			if (!(dynamicVar is StringVar) && dynamicVar.BaseValue == decimal.Truncate(dynamicVar.BaseValue))
			{
				decimal baseValue = dynamicVar.BaseValue;
				if (baseValue >= -999999999m)
				{
					return baseValue <= 999999999m;
				}
				return false;
			}
			return false;
		}

		internal static RitsuDebugActionCheck Validate(DynamicVarSet dynamicVars, IReadOnlyDictionary<string, int>? overrides)
		{
			ArgumentNullException.ThrowIfNull(dynamicVars, "dynamicVars");
			if (overrides == null)
			{
				return RitsuDebugActionCheck.Ok;
			}
			if (overrides.Count > 128)
			{
				return RitsuDebugActionCheck.Fail("model.dynamicVarLimit", "Model values can change at most {0} dynamic variables.", 128);
			}
			DynamicVar dynamicVar = default(DynamicVar);
			foreach (var (text2, num2) in overrides)
			{
				if (string.IsNullOrWhiteSpace(text2) || text2.Length > 64)
				{
					return RitsuDebugActionCheck.Fail("model.dynamicVarKeyRequired", "A valid dynamic-variable key is required.");
				}
				if ((num2 < -999999999 || num2 > 999999999) ? true : false)
				{
					return RitsuDebugActionCheck.Fail("model.dynamicVarRange", "Model values must be between {0} and {1}.", -999999999, 999999999);
				}
				if (!dynamicVars.TryGetValue(text2, ref dynamicVar))
				{
					return RitsuDebugActionCheck.Fail("model.dynamicVarMissing", "The selected model has no dynamic variable named '{0}'.", text2);
				}
				if (!IsEditable(dynamicVar))
				{
					return RitsuDebugActionCheck.Fail("model.dynamicVarUnsupported", "Dynamic variable '{0}' is not an editable integer value.", text2);
				}
			}
			return RitsuDebugActionCheck.Ok;
		}

		internal static void Apply(DynamicVarSet dynamicVars, IReadOnlyDictionary<string, int>? overrides)
		{
			ArgumentNullException.ThrowIfNull(dynamicVars, "dynamicVars");
			if (overrides == null)
			{
				return;
			}
			foreach (var (text2, num2) in overrides)
			{
				DynamicVar obj = dynamicVars[text2];
				obj.BaseValue = num2;
				obj.ResetToBase();
			}
		}
	}
	internal static class RitsuDebugOrbActions
	{
		internal readonly record struct OrbValuesPayload(string OrbId);

		internal readonly record struct OrbInstancePayload(int SlotIndex, string ExpectedOrbId);

		internal readonly record struct OrbReplacementPayload(int SlotIndex, string ExpectedOrbId, string ReplacementOrbId);

		internal readonly record struct OrbSlotsPayload(int Capacity);

		internal const string ChannelOrbActionId = "combat.orb.channel";

		internal const string ReplaceOrbActionId = "combat.orb.replace";

		internal const string RemoveOrbActionId = "combat.orb.remove";

		internal const string SetOrbSlotsActionId = "combat.orb-slots.set";

		internal const int MaximumOrbSlots = 10;

		internal static void RegisterBuiltInActions()
		{
			RitsuDebugActionProtocol.Register<OrbValuesPayload>("combat.orb.channel", ValidateChannelOrb, ExecuteChannelOrbAsync);
			RitsuDebugActionProtocol.Register<OrbReplacementPayload>("combat.orb.replace", ValidateReplaceOrb, ExecuteReplaceOrbAsync);
			RitsuDebugActionProtocol.Register<OrbInstancePayload>("combat.orb.remove", ValidateRemoveOrb, ExecuteRemoveOrbAsync);
			RitsuDebugActionProtocol.Register<OrbSlotsPayload>("combat.orb-slots.set", ValidateSetOrbSlots, ExecuteSetOrbSlotsAsync);
		}

		internal static RitsuDebugActionSubmission SubmitChannelOrb(Player requester, Player target, string orbId)
		{
			return Submit(requester, target, "combat.orb.channel", new OrbValuesPayload(orbId));
		}

		internal static RitsuDebugActionSubmission SubmitReplaceOrb(Player requester, Player target, int slotIndex, string expectedOrbId, string replacementOrbId)
		{
			return Submit(requester, target, "combat.orb.replace", new OrbReplacementPayload(slotIndex, expectedOrbId, replacementOrbId));
		}

		internal static RitsuDebugActionSubmission SubmitRemoveOrb(Player requester, Player target, int slotIndex, string expectedOrbId)
		{
			return Submit(requester, target, "combat.orb.remove", new OrbInstancePayload(slotIndex, expectedOrbId));
		}

		internal static RitsuDebugActionSubmission SubmitSetOrbSlots(Player requester, Player target, int capacity)
		{
			return Submit(requester, target, "combat.orb-slots.set", new OrbSlotsPayload(capacity));
		}

		internal static bool TryResolveOrb(string input, out OrbModel orb, out RitsuDebugActionFeedback feedback)
		{
			orb = null;
			if (string.IsNullOrWhiteSpace(input) || input.Length > 128)
			{
				feedback = RitsuDebugActionFeedback.Create("model.orbIdInvalid", "The orb ID is empty or too long.");
				return false;
			}
			OrbModel[] source = ModelDb.Orbs.ToArray();
			OrbModel[] array = source.Where((OrbModel candidate) => ((object)((AbstractModel)candidate).Id).ToString().Equals(input, StringComparison.OrdinalIgnoreCase)).Take(2).ToArray();
			OrbModel[] array2 = ((array.Length != 0) ? array : source.Where((OrbModel candidate) => ((AbstractModel)candidate).Id.Entry.Equals(input, StringComparison.OrdinalIgnoreCase)).Take(2).ToArray());
			if (array2.Length == 1)
			{
				orb = array2[0];
				feedback = default(RitsuDebugActionFeedback);
				return true;
			}
			feedback = ((array2.Length == 0) ? RitsuDebugActionFeedback.Create("model.orbUnknown", "Unknown orb '{0}'.", input) : RitsuDebugActionFeedback.Create("model.orbAmbiguous", "The orb ID '{0}' is ambiguous; use the full model ID.", input));
			return false;
		}

		private static RitsuDebugActionSubmission Submit<TPayload>(Player requester, Player target, string actionId, TPayload payload)
		{
			RitsuDebugActionEnvelope envelope = RitsuDebugActionProtocol.CreateEnvelope(actionId, requester, target, payload);
			return RitsuDebugActionProtocol.Submit(requester, envelope);
		}

		private static RitsuDebugActionCheck ValidateChannelOrb(RitsuDebugActionContext context, OrbValuesPayload payload)
		{
			if (!TryRequireOrbQueue(context.Target, out IReadOnlyList<OrbModel> _, out RitsuDebugActionFeedback feedback) || !TryResolveOrb(payload.OrbId, out OrbModel _, out feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateReplaceOrb(RitsuDebugActionContext context, OrbReplacementPayload payload)
		{
			if (!TryResolveOrbInstance(context.Target, payload.SlotIndex, payload.ExpectedOrbId, out OrbModel orb, out RitsuDebugActionFeedback feedback) || !TryResolveOrb(payload.ReplacementOrbId, out orb, out feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateRemoveOrb(RitsuDebugActionContext context, OrbInstancePayload payload)
		{
			if (!TryResolveOrbInstance(context.Target, payload.SlotIndex, payload.ExpectedOrbId, out OrbModel _, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateSetOrbSlots(RitsuDebugActionContext context, OrbSlotsPayload payload)
		{
			if (!TryRequireOrbQueue(context.Target, out IReadOnlyList<OrbModel> _, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			int capacity = payload.Capacity;
			if ((capacity >= 0 && capacity <= 10) || 1 == 0)
			{
				return RitsuDebugActionCheck.Ok;
			}
			return RitsuDebugActionCheck.Fail("combat.orbSlotRange", "Orb slot count must be between 0 and {0}.", 10);
		}

		private static async Task<string> ExecuteChannelOrbAsync(RitsuDebugActionContext context, OrbValuesPayload payload)
		{
			TryResolveOrb(payload.OrbId, out OrbModel canonical, out RitsuDebugActionFeedback _);
			OrbModel val = canonical.ToMutable(0);
			await OrbCmd.Channel((PlayerChoiceContext)new BlockingPlayerChoiceContext(), val, context.Target);
			return $"Channeled orb {((AbstractModel)canonical).Id}.";
		}

		private static Task<string> ExecuteReplaceOrbAsync(RitsuDebugActionContext context, OrbReplacementPayload payload)
		{
			TryResolveOrbInstance(context.Target, payload.SlotIndex, payload.ExpectedOrbId, out OrbModel orb, out RitsuDebugActionFeedback feedback);
			TryResolveOrb(payload.ReplacementOrbId, out OrbModel orb2, out feedback);
			OrbModel val = orb2.ToMutable(0);
			val.Owner = context.Target;
			OrbQueue orbQueue = context.Target.PlayerCombatState.OrbQueue;
			orbQueue.Remove(orb);
			orbQueue.Insert(payload.SlotIndex, val);
			NCombatRoom instance = NCombatRoom.Instance;
			if (instance != null)
			{
				NCreature creatureNode = instance.GetCreatureNode(context.Target.Creature);
				if (creatureNode != null)
				{
					NOrbManager orbManager = creatureNode.OrbManager;
					if (orbManager != null)
					{
						orbManager.ReplaceOrb(orb, val);
					}
				}
			}
			orb.RemoveInternal();
			return Task.FromResult($"Replaced orb {((AbstractModel)orb).Id} with {((AbstractModel)val).Id}.");
		}

		private static Task<string> ExecuteRemoveOrbAsync(RitsuDebugActionContext context, OrbInstancePayload payload)
		{
			TryResolveOrbInstance(context.Target, payload.SlotIndex, payload.ExpectedOrbId, out OrbModel orb, out RitsuDebugActionFeedback _);
			OrbQueue orbQueue = context.Target.PlayerCombatState.OrbQueue;
			NCombatRoom instance = NCombatRoom.Instance;
			if (instance != null)
			{
				NCreature creatureNode = instance.GetCreatureNode(context.Target.Creature);
				if (creatureNode != null)
				{
					NOrbManager orbManager = creatureNode.OrbManager;
					if (orbManager != null)
					{
						orbManager.EvokeOrbAnim(orb);
					}
				}
			}
			orbQueue.Remove(orb);
			orb.RemoveInternal();
			return Task.FromResult($"Removed orb {((AbstractModel)orb).Id}.");
		}

		private static async Task<string> ExecuteSetOrbSlotsAsync(RitsuDebugActionContext context, OrbSlotsPayload payload)
		{
			OrbQueue orbQueue = context.Target.PlayerCombatState.OrbQueue;
			int num = payload.Capacity - orbQueue.Capacity;
			if (num > 0)
			{
				await OrbCmd.AddSlots(context.Target, num);
			}
			else if (num < 0)
			{
				OrbCmd.RemoveSlots(context.Target, -num);
			}
			return $"Set orb slots to {payload.Capacity}.";
		}

		private static bool TryRequireOrbQueue(Player target, out IReadOnlyList<OrbModel> orbs, out RitsuDebugActionFeedback feedback)
		{
			orbs = Array.Empty<OrbModel>();
			if (!RitsuDebugCombatActions.TryRequireCombat(out feedback))
			{
				return false;
			}
			if (target.PlayerCombatState == null || target.Creature.CombatState == null)
			{
				feedback = RitsuDebugActionFeedback.Create("combat.orbQueueUnavailable", "The selected player does not have an active orb queue.");
				return false;
			}
			orbs = target.PlayerCombatState.OrbQueue.Orbs;
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}

		private static bool TryResolveOrbInstance(Player target, int slotIndex, string expectedOrbId, out OrbModel orb, out RitsuDebugActionFeedback feedback)
		{
			orb = null;
			if (!TryRequireOrbQueue(target, out IReadOnlyList<OrbModel> orbs, out feedback))
			{
				return false;
			}
			if (slotIndex < 0 || slotIndex >= orbs.Count)
			{
				feedback = RitsuDebugActionFeedback.Create("combat.orbInstanceChanged", "The selected orb is no longer available.");
				return false;
			}
			OrbModel val = orbs[slotIndex];
			if (!((object)((AbstractModel)val).Id).ToString().Equals(expectedOrbId, StringComparison.Ordinal))
			{
				feedback = RitsuDebugActionFeedback.Create("combat.orbInstanceChanged", "The selected orb has changed. Refresh and try again.");
				return false;
			}
			orb = val;
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}
	}
	internal enum RitsuDebugPlayerOperation
	{
		AddGold,
		SetGold,
		Heal,
		SetCurrentHp,
		SetMaxHp,
		GainBlock,
		AddEnergy,
		SetEnergy,
		AddStars,
		SetStars,
		SetMaxEnergy,
		SetPotionSlots,
		Draw
	}
	internal static class RitsuDebugPlayerActions
	{
		internal readonly record struct ModifyPlayerPayload(RitsuDebugPlayerOperation Operation, int Value);

		internal const string ModifyPlayerActionId = "player.modify";

		internal const int MaxGold = 999999999;

		internal const int MaxHitPoints = 999999999;

		internal const int MaxCombatResource = 999999999;

		internal const int MaxPotionSlots = 20;

		internal const int MaxDrawCount = 100;

		internal static void RegisterBuiltInActions()
		{
			RitsuDebugActionProtocol.Register<ModifyPlayerPayload>("player.modify", ValidateModifyPlayer, ExecuteModifyPlayerAsync);
		}

		internal static RitsuDebugActionSubmission Submit(Player requester, Player target, RitsuDebugPlayerOperation operation, int value)
		{
			RitsuDebugActionEnvelope envelope = RitsuDebugActionProtocol.CreateEnvelope("player.modify", requester, target, new ModifyPlayerPayload(operation, value));
			return RitsuDebugActionProtocol.Submit(requester, envelope);
		}

		internal static RitsuDebugActionCheck ValidateModifyPlayer(RitsuDebugActionContext context, ModifyPlayerPayload payload)
		{
			if (!Enum.IsDefined(payload.Operation))
			{
				return RitsuDebugActionCheck.Fail("player.invalidOperation", "The player operation is invalid.");
			}
			(int, int) tuple = payload.Operation switch
			{
				RitsuDebugPlayerOperation.AddGold => (-999999999, 999999999), 
				RitsuDebugPlayerOperation.SetGold => (0, 999999999), 
				RitsuDebugPlayerOperation.Heal => (0, 999999999), 
				RitsuDebugPlayerOperation.SetCurrentHp => (1, 999999999), 
				RitsuDebugPlayerOperation.SetMaxHp => (1, 999999999), 
				RitsuDebugPlayerOperation.GainBlock => (0, 999999999), 
				RitsuDebugPlayerOperation.AddEnergy => (0, 999999999), 
				RitsuDebugPlayerOperation.SetEnergy => (0, 999999999), 
				RitsuDebugPlayerOperation.AddStars => (0, 999999999), 
				RitsuDebugPlayerOperation.SetStars => (0, 999999999), 
				RitsuDebugPlayerOperation.SetMaxEnergy => (1, 999999999), 
				RitsuDebugPlayerOperation.SetPotionSlots => (0, 20), 
				RitsuDebugPlayerOperation.Draw => (1, 100), 
				_ => (1, 0), 
			};
			if (payload.Value < tuple.Item1 || payload.Value > tuple.Item2)
			{
				return RitsuDebugActionCheck.Fail("player.valueRange", "The value must be between {0} and {1}.", tuple.Item1, tuple.Item2);
			}
			switch (payload.Operation)
			{
			case RitsuDebugPlayerOperation.AddGold:
			{
				long num = (long)context.Target.Gold + (long)payload.Value;
				if ((num < 0 || num > 999999999) ? true : false)
				{
					return RitsuDebugActionCheck.Fail("player.goldResultRange", "The resulting gold amount must be between 0 and {0}.", 999999999);
				}
				break;
			}
			case RitsuDebugPlayerOperation.GainBlock:
			case RitsuDebugPlayerOperation.AddEnergy:
			case RitsuDebugPlayerOperation.SetEnergy:
			case RitsuDebugPlayerOperation.AddStars:
			case RitsuDebugPlayerOperation.SetStars:
			case RitsuDebugPlayerOperation.Draw:
				if (!CombatManager.Instance.IsInProgress || CombatManager.Instance.IsOverOrEnding || context.Target.PlayerCombatState == null)
				{
					return RitsuDebugActionCheck.Fail("player.activeCombatRequired", "This player operation requires an active combat.");
				}
				break;
			case RitsuDebugPlayerOperation.SetCurrentHp:
				if (payload.Value > context.Target.Creature.MaxHp)
				{
					return RitsuDebugActionCheck.Fail("player.currentHpExceedsMax", "Current HP cannot exceed the target's max HP ({0}).", context.Target.Creature.MaxHp);
				}
				break;
			case RitsuDebugPlayerOperation.SetMaxHp:
				if (payload.Value < context.Target.Creature.CurrentHp)
				{
					return RitsuDebugActionCheck.Fail("player.maxHpBelowCurrent", "Max HP cannot be lower than the target's current HP ({0}).", context.Target.Creature.CurrentHp);
				}
				break;
			}
			return RitsuDebugActionCheck.Ok;
		}

		internal static async Task<string> ExecuteModifyPlayerAsync(RitsuDebugActionContext context, ModifyPlayerPayload payload)
		{
			Player target = context.Target;
			switch (payload.Operation)
			{
			case RitsuDebugPlayerOperation.AddGold:
				if (payload.Value >= 0)
				{
					await PlayerCmd.GainGold((decimal)payload.Value, target, false);
				}
				else
				{
					await PlayerCmd.LoseGold((decimal)(-payload.Value), target, (GoldLossType)2);
				}
				break;
			case RitsuDebugPlayerOperation.SetGold:
				await PlayerCmd.SetGold((decimal)payload.Value, target);
				break;
			case RitsuDebugPlayerOperation.Heal:
				await CreatureCmd.Heal(target.Creature, (decimal)payload.Value, true);
				break;
			case RitsuDebugPlayerOperation.SetCurrentHp:
				await CreatureCmd.SetCurrentHp(target.Creature, (decimal)payload.Value);
				break;
			case RitsuDebugPlayerOperation.SetMaxHp:
				await CreatureCmd.SetMaxHp(target.Creature, (decimal)payload.Value);
				break;
			case RitsuDebugPlayerOperation.GainBlock:
				await CreatureCmd.GainBlock(target.Creature, (decimal)payload.Value, (ValueProp)4, (CardPlay)null, false);
				break;
			case RitsuDebugPlayerOperation.AddEnergy:
				await PlayerCmd.GainEnergy((decimal)payload.Value, target);
				break;
			case RitsuDebugPlayerOperation.SetEnergy:
				target.PlayerCombatState.Energy = payload.Value;
				break;
			case RitsuDebugPlayerOperation.AddStars:
				await PlayerCmd.GainStars((decimal)payload.Value, target);
				break;
			case RitsuDebugPlayerOperation.SetStars:
				target.PlayerCombatState.Stars = payload.Value;
				break;
			case RitsuDebugPlayerOperation.SetMaxEnergy:
				target.MaxEnergy = payload.Value;
				break;
			case RitsuDebugPlayerOperation.SetPotionSlots:
				await SetPotionSlotsAsync(target, payload.Value);
				break;
			case RitsuDebugPlayerOperation.Draw:
			{
				HookPlayerChoiceContext val = new HookPlayerChoiceContext(target, target.NetId, (GameActionType)1);
				await val.AssignTaskAndWaitForPauseOrCompletion((Task)CardPileCmd.Draw((PlayerChoiceContext)val, (decimal)payload.Value, target, false));
				break;
			}
			default:
				throw new ArgumentOutOfRangeException("Operation");
			}
			return DescribeResult(payload.Operation, payload.Value);
		}

		private static Task SetPotionSlotsAsync(Player player, int count)
		{
			int num = count - player.MaxPotionCount;
			if (num <= 0)
			{
				if (num < 0)
				{
					return PlayerCmd.LoseMaxPotionCount(-num, player);
				}
				return Task.CompletedTask;
			}
			return PlayerCmd.GainMaxPotionCount(num, player);
		}

		private static string DescribeOperation(RitsuDebugPlayerOperation operation)
		{
			return operation switch
			{
				RitsuDebugPlayerOperation.AddGold => "gold", 
				RitsuDebugPlayerOperation.SetGold => "gold", 
				RitsuDebugPlayerOperation.Heal => "health", 
				RitsuDebugPlayerOperation.SetCurrentHp => "current HP", 
				RitsuDebugPlayerOperation.SetMaxHp => "maximum HP", 
				RitsuDebugPlayerOperation.GainBlock => "block", 
				RitsuDebugPlayerOperation.AddEnergy => "energy", 
				RitsuDebugPlayerOperation.SetEnergy => "energy", 
				RitsuDebugPlayerOperation.AddStars => "stars", 
				RitsuDebugPlayerOperation.SetStars => "stars", 
				RitsuDebugPlayerOperation.SetMaxEnergy => "maximum energy", 
				RitsuDebugPlayerOperation.SetPotionSlots => "potion slots", 
				RitsuDebugPlayerOperation.Draw => "number of cards to draw", 
				_ => "state", 
			};
		}

		private static string DescribeResult(RitsuDebugPlayerOperation operation, int value)
		{
			return operation switch
			{
				RitsuDebugPlayerOperation.Heal => "Healed the selected player.", 
				RitsuDebugPlayerOperation.GainBlock => "Granted block to the selected player.", 
				RitsuDebugPlayerOperation.AddEnergy => "Added energy to the selected player.", 
				RitsuDebugPlayerOperation.AddStars => "Added stars to the selected player.", 
				RitsuDebugPlayerOperation.Draw => $"Drew {value} card(s) for the selected player.", 
				_ => "Updated the selected player's " + DescribeOperation(operation) + ".", 
			};
		}
	}
	internal static class RitsuDebugRunActions
	{
		internal readonly record struct RoomPayload(string RoomType);

		internal readonly record struct ModelPayload(string ModelId);

		internal readonly record struct EventPayload(string EventId, string? AncientOption);

		private const int MaxAncientOptionCount = 128;

		internal const string EnterRoomActionId = "run.room.enter";

		internal const string EnterEncounterActionId = "run.encounter.enter";

		internal const string EnterEventActionId = "run.event.enter";

		private static readonly PropertyInfo? EventOwnerProperty = typeof(EventModel).GetProperty("Owner", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);

		internal static void RegisterBuiltInActions()
		{
			RitsuDebugActionProtocol.Register<RoomPayload>("run.room.enter", ValidateEnterRoom, ExecuteEnterRoomAsync);
			RitsuDebugActionProtocol.Register<ModelPayload>("run.encounter.enter", ValidateEnterEncounter, ExecuteEnterEncounterAsync);
			RitsuDebugActionProtocol.Register<EventPayload>("run.event.enter", ValidateEnterEvent, ExecuteEnterEventAsync);
		}

		internal unsafe static RitsuDebugActionSubmission SubmitEnterRoom(Player requester, RoomType roomType)
		{
			RitsuDebugActionEnvelope envelope = RitsuDebugActionProtocol.CreateEnvelope("run.room.enter", requester, requester, new RoomPayload(((object)(*(RoomType*)(&roomType))/*cast due to constrained. prefix*/).ToString()));
