		internal static bool TryGetAvailableAncientOptions(AncientEventModel canonical, Player player, out EventOption[] options, out RitsuDebugActionFeedback feedback)
		{
			//IL_0059: Unknown result type (might be due to invalid IL or missing references)
			//IL_005f: Expected O, but got Unknown
			ArgumentNullException.ThrowIfNull(canonical, "canonical");
			ArgumentNullException.ThrowIfNull(player, "player");
			options = Array.Empty<EventOption>();
			if (EventOwnerProperty?.SetMethod == null)
			{
				feedback = RitsuDebugActionFeedback.Create("run.ancientUnsupportedVersion", "This game version cannot determine which Ancient options are available for the selected player.");
				return false;
			}
			try
			{
				AncientEventModel val = (AncientEventModel)((EventModel)canonical).ToMutable();
				EventOwnerProperty.SetValue(val, player);
				EventOption[] array = val.AllPossibleOptions.Where((EventOption option) => option != null && !option.IsLocked).Take(129).ToArray();
				if (array.Length > 128)
				{
					feedback = RitsuDebugActionFeedback.Create("run.ancientTooManyOptions", "Ancient event {0} exposes more than {1} options.", ((AbstractModel)canonical).Id, 128);
					return false;
				}
				options = array.DistinctBy<EventOption, string>(GetAncientOptionToken, StringComparer.OrdinalIgnoreCase).ToArray();
				feedback = default(RitsuDebugActionFeedback);
				return true;
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn($"[DebugTools] Could not resolve Ancient options for '{((AbstractModel)canonical).Id}': {ex}", 1);
				feedback = RitsuDebugActionFeedback.Create("run.ancientOptionsUnavailable", "Available Ancient options could not be determined for the selected player.");
				return false;
			}
		}

		private static RitsuDebugActionCheck ValidateEnterRoom(RitsuDebugActionContext context, RoomPayload payload)
		{
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			if (!TryRequireActiveRun(out var feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (!Enum.TryParse<RoomType>(payload.RoomType, true, out RoomType result) || (int)result == 0)
			{
				return RitsuDebugActionCheck.Fail("run.invalidRoomType", "Unknown or unsupported room type '{0}'.", payload.RoomType);
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateEnterEncounter(RitsuDebugActionContext context, ModelPayload payload)
		{
			if (!TryRequireActiveRun(out var feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (!TryResolveEncounter(payload.ModelId, out EncounterModel _, out feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static RitsuDebugActionCheck ValidateEnterEvent(RitsuDebugActionContext context, EventPayload payload)
		{
			if (!TryRequireActiveRun(out var feedback) || !TryResolveEvent(payload.EventId, out EventModel eventModel, out feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (payload.AncientOption == null)
			{
				return RitsuDebugActionCheck.Ok;
			}
			AncientEventModel val = (AncientEventModel)(object)((eventModel is AncientEventModel) ? eventModel : null);
			if (val == null)
			{
				return RitsuDebugActionCheck.Fail("run.ancientOptionOnly", "An Ancient option may be specified only for an Ancient event.");
			}
			if (!TryGetAvailableAncientOptions(val, context.Target, out EventOption[] options, out feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			if (!options.Any((EventOption option) => GetAncientOptionToken(option).Equals(payload.AncientOption, StringComparison.OrdinalIgnoreCase)))
			{
				return RitsuDebugActionCheck.Fail("run.ancientOptionMissing", "Ancient event {0} has no option '{1}'.", ((AbstractModel)val).Id, payload.AncientOption);
			}
			return RitsuDebugActionCheck.Ok;
		}

		private static async Task<string> ExecuteEnterRoomAsync(RitsuDebugActionContext context, RoomPayload payload)
		{
			Enum.TryParse<RoomType>(payload.RoomType, true, out RoomType roomType);
			await RunManager.Instance.EnterRoomDebug(roomType, (MapPointType)0, (AbstractModel)null, true);
			return $"Entered the selected room: {roomType}.";
		}

		private static async Task<string> ExecuteEnterEncounterAsync(RitsuDebugActionContext context, ModelPayload payload)
		{
			TryResolveEncounter(payload.ModelId, out EncounterModel canonical, out RitsuDebugActionFeedback _);
			EncounterModel val = canonical.ToMutable();
			val.DebugRandomizeRng();
			await RunManager.Instance.EnterRoomDebug((RoomType)1, (MapPointType)0, (AbstractModel)(object)val, true);
			return $"Entered encounter {((AbstractModel)canonical).Id}.";
		}

		private static async Task<string> ExecuteEnterEventAsync(RitsuDebugActionContext context, EventPayload payload)
		{
			TryResolveEvent(payload.EventId, out EventModel eventModel, out RitsuDebugActionFeedback _);
			MapPointType val = (MapPointType)((!(eventModel is AncientEventModel)) ? 1 : 8);
			string option = payload.AncientOption?.ToUpperInvariant();
			EventRoom val2 = new EventRoom(eventModel);
			val2.set_OnStart((option == null) ? null : ((Action<EventModel>)delegate(EventModel model)
			{
				//IL_0001: Unknown result type (might be due to invalid IL or missing references)
				((AncientEventModel)model).DebugOption = option;
			}));
			EventRoom val3 = val2;
			context.Target.RunState.AppendToMapPointHistory(val, (RoomType)6, ((AbstractModel)eventModel).Id);
			await RunManager.Instance.EnterRoom((AbstractRoom)(object)val3);
			return $"Entered event {((AbstractModel)eventModel).Id}.";
		}

		internal static string GetAncientOptionToken(EventOption option)
		{
			return option.TextKey.Split('.').Last();
		}

		private static bool TryRequireActiveRun(out RitsuDebugActionFeedback feedback)
		{
			if (!RunManager.Instance.IsInProgress)
			{
				feedback = RitsuDebugActionFeedback.Create("run.notInProgress", "A run is not currently in progress.");
				return false;
			}
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}

		private static bool TryResolveModel<TModel>(IEnumerable<TModel> candidates, string input, string kind, out TModel model, out RitsuDebugActionFeedback feedback) where TModel : AbstractModel
		{
			model = default(TModel);
			if (string.IsNullOrWhiteSpace(input) || input.Length > 128)
			{
				feedback = RitsuDebugActionFeedback.Create("model." + kind + "IdInvalid", "The " + kind + " ID is empty or too long.");
				return false;
			}
			TModel[] source = (candidates as TModel[]) ?? candidates.ToArray();
			TModel[] array = source.Where((TModel candidate) => ((object)((AbstractModel)candidate).Id).ToString().Equals(input, StringComparison.OrdinalIgnoreCase)).Take(2).ToArray();
			TModel[] array2 = ((array.Length != 0) ? array : source.Where((TModel candidate) => ((AbstractModel)candidate).Id.Entry.Equals(input, StringComparison.OrdinalIgnoreCase)).Take(2).ToArray());
			if (array2.Length == 1)
			{
				model = array2[0];
				feedback = default(RitsuDebugActionFeedback);
				return true;
			}
			feedback = ((array2.Length == 0) ? RitsuDebugActionFeedback.Create("model." + kind + "Unknown", "Unknown " + kind + " '{0}'.", input) : RitsuDebugActionFeedback.Create("model." + kind + "Ambiguous", "The " + kind + " ID '{0}' is ambiguous; use the full model ID.", input));
			return false;
		}
	}
	internal enum RitsuDebugSecondaryResourceOperation
	{
		Gain,
		Lose,
		Set,
		Reset,
		ResetToMax
	}
	internal static class RitsuDebugSecondaryResourceActions
	{
		internal readonly record struct ModifyPayload(string ResourceId, RitsuDebugSecondaryResourceOperation Operation, int Value);

		internal const string ModifyActionId = "secondary-resources.modify";

		internal static void RegisterBuiltInActions()
		{
			RitsuDebugActionProtocol.Register<ModifyPayload>("secondary-resources.modify", ValidateModify, ExecuteModifyAsync, (RitsuLibSidecarPeerFeatures)64u);
		}

		internal static RitsuDebugActionSubmission Submit(Player requester, Player target, string resourceId, RitsuDebugSecondaryResourceOperation operation, int value = 0)
		{
			RitsuDebugActionEnvelope envelope = RitsuDebugActionProtocol.CreateEnvelope("secondary-resources.modify", requester, target, new ModifyPayload(resourceId, operation, value));
			return RitsuDebugActionProtocol.Submit(requester, envelope);
		}

		internal static RitsuDebugActionCheck ValidateModify(RitsuDebugActionContext context, ModifyPayload payload)
		{
			if (!Enum.IsDefined(payload.Operation))
			{
				return RitsuDebugActionCheck.Fail("secondaryResource.invalidOperation", "The secondary-resource operation is invalid.");
			}
			if (string.IsNullOrWhiteSpace(payload.ResourceId) || payload.ResourceId.Length > 256 || !ModSecondaryResourceRegistry.TryGet(payload.ResourceId, out SecondaryResourceDefinition definition))
			{
				return RitsuDebugActionCheck.Fail("secondaryResource.unknown", "Secondary resource '{0}' is not registered.", payload.ResourceId);
			}
			if (!CombatManager.Instance.IsInProgress || CombatManager.Instance.IsOverOrEnding || context.Target.PlayerCombatState == null || context.Target.Creature.CombatState == null)
			{
				return RitsuDebugActionCheck.Fail("player.activeCombatRequired", "This secondary-resource operation requires an active combat.");
			}
			int num;
			switch (payload.Operation)
			{
			case RitsuDebugSecondaryResourceOperation.Gain:
			case RitsuDebugSecondaryResourceOperation.Lose:
				if (payload.Value < 1)
				{
					return RitsuDebugActionCheck.Fail("secondaryResource.positiveAmountRequired", "The amount must be a positive integer.");
				}
				break;
			case RitsuDebugSecondaryResourceOperation.Set:
				if (payload.Value < definition.MinAmount || payload.Value > definition.HardMaxAmount)
				{
					return RitsuDebugActionCheck.Fail("secondaryResource.valueRange", "The amount must be between {0} and {1}.", definition.MinAmount, definition.HardMaxAmount);
				}
				break;
			case RitsuDebugSecondaryResourceOperation.Reset:
				num = 2;
				goto IL_016b;
			case RitsuDebugSecondaryResourceOperation.ResetToMax:
				{
					num = 3;
					goto IL_016b;
				}
				IL_016b:
				if (payload.Value == 0)
				{
					if (num == 2)
					{
						break;
					}
					if (num == 3)
					{
						if (!SecondaryResourceCmd.GetMax(context.Target, definition.Id).HasValue)
						{
							return RitsuDebugActionCheck.Fail("secondaryResource.noMaximum", "Secondary resource '{0}' does not have a maximum.", definition.Id);
						}
						break;
					}
				}
				return RitsuDebugActionCheck.Fail("secondaryResource.unexpectedAmount", "Reset operations do not accept an amount.");
			}
			return RitsuDebugActionCheck.Ok;
		}

		internal static async Task<string> ExecuteModifyAsync(RitsuDebugActionContext context, ModifyPayload payload)
		{
			int value = payload.Operation switch
			{
				RitsuDebugSecondaryResourceOperation.Gain => await SecondaryResourceCmd.Gain(context.Target, payload.ResourceId, payload.Value), 
				RitsuDebugSecondaryResourceOperation.Lose => await SecondaryResourceCmd.Lose(context.Target, payload.ResourceId, payload.Value), 
				RitsuDebugSecondaryResourceOperation.Set => await SecondaryResourceCmd.Set(context.Target, payload.ResourceId, payload.Value), 
				RitsuDebugSecondaryResourceOperation.Reset => await SecondaryResourceCmd.Reset(context.Target, payload.ResourceId), 
				RitsuDebugSecondaryResourceOperation.ResetToMax => await SecondaryResourceCmd.Reset(context.Target, payload.ResourceId, toMax: true), 
				_ => throw new ArgumentOutOfRangeException("Operation"), 
			};
			return $"Set {payload.ResourceId} to {value}.";
		}
	}
	internal static class RitsuDebugStatePresetActions
	{
