			if (!TryEncodePreset(preset, out var payload, out var feedback))
			{
				return RitsuDebugActionSubmission.Reject(feedback);
			}
			return RitsuDebugActionProtocol.Submit(requester, RitsuDebugActionProtocol.CreateEnvelope("state-presets.apply", requester, target, payload));
		}

		internal static RitsuDebugActionCheck ValidateStoredPreset(RitsuDebugStatePreset preset)
		{
			//IL_00bb: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(preset, "preset");
			string id = preset.Id;
			if (id == null || id.Length != 32 || !Guid.TryParseExact(preset.Id, "N", out var _) || string.IsNullOrWhiteSpace(preset.Name) || preset.Name.Length > 80 || preset.CardPiles == null || !preset.HasAnyContent)
			{
				return RitsuDebugActionCheck.Fail("statePreset.invalid", "The preset is missing required data or exceeds a supported limit.");
			}
			HashSet<PileType> hashSet = new HashSet<PileType>();
			foreach (RitsuDebugStatePresetCardPile cardPile in preset.CardPiles)
			{
				if (cardPile == null || !Enum.IsDefined(cardPile.ApplyMode) || !RitsuDebugCardActions.TryParseMutablePileType(cardPile.Pile, out var pileType) || !hashSet.Add(pileType) || cardPile.Cards == null)
				{
					return RitsuDebugActionCheck.Fail("statePreset.cardPileInvalid", "A card-pile configuration is invalid or duplicated.");
				}
				int num = 0;
				foreach (RitsuDebugStatePresetCard card3 in cardPile.Cards)
				{
					if (card3 == null)
					{
						return RitsuDebugActionCheck.Fail("statePreset.cardInvalid", "A saved card entry is invalid.");
					}
					if (!RitsuDebugCardActions.TryResolveCanonicalCard(card3.CardId, out CardModel card, out RitsuDebugActionFeedback feedback))
					{
						return RitsuDebugActionCheck.Fail(feedback);
					}
					int count = card3.Count;
					bool flag = ((count < 1 || count > 100) ? true : false);
					if (flag || (num += card3.Count) > 100 || card3.UpgradeLevels < 0 || card3.UpgradeLevels > card.MaxUpgradeLevel)
					{
						return RitsuDebugActionCheck.Fail("statePreset.cardInvalid", "A saved card entry is invalid.");
					}
					CardModel card2 = card.ToMutable();
					RitsuDebugCardActions.ApplyAvailableUpgradeLevels(card2, card3.UpgradeLevels);
					RitsuDebugActionCheck result2 = RitsuDebugCardActions.ValidateCardState(card2, card3.ToCardState());
					if (!result2.Success)
					{
						return result2;
					}
				}
				if (cardPile != null && cardPile.ApplyMode == RitsuDebugStatePresetApplyMode.Add)
				{
					List<RitsuDebugStatePresetCard> cards = cardPile.Cards;
					if (cards != null && cards.Count == 0)
					{
						return RitsuDebugActionCheck.Fail("statePreset.emptyAddGroup", "An add-mode group must contain at least one item.");
					}
				}
			}
			RitsuDebugActionCheck result3 = ValidateRelics(preset.Relics);
			if (!result3.Success)
			{
				return result3;
			}
			RitsuDebugActionCheck result4 = ValidatePotions(preset.Potions);
			if (!result4.Success)
			{
				return result4;
			}
			RitsuDebugActionCheck result5 = ValidatePowers(preset.Powers);
			if (!result5.Success)
			{
				return result5;
			}
			RitsuDebugActionCheck result6 = ValidatePlayer(preset.Player, requireCombat: false);
			if (!result6.Success)
			{
				return result6;
			}
			RitsuDebugActionCheck result7 = ValidateSecondaryResources(preset.SecondaryResources);
			if (!result7.Success)
			{
				return result7;
			}
			RitsuDebugActionCheck result8 = ValidateCapabilityTargets(preset.CapabilityTargets);
			if (!result8.Success)
			{
				return result8;
			}
			if (!TryEncodePreset(preset, out var _, out var feedback2))
			{
				return RitsuDebugActionCheck.Fail(feedback2);
			}
			return RitsuDebugActionCheck.Ok;
		}

		internal static bool TryEncodePreset(RitsuDebugStatePreset preset, out RitsuDebugStatePresetWirePayload payload, out RitsuDebugActionFeedback feedback)
		{
			byte[] array = JsonSerializer.SerializeToUtf8Bytes(preset);
			if (array.Length > 65536)
			{
				payload = default(RitsuDebugStatePresetWirePayload);
				feedback = RitsuDebugActionFeedback.Create("statePreset.decodedDataLimit", "The preset contains too much data to apply.");
				return false;
			}
			using MemoryStream memoryStream = new MemoryStream();
			using (BrotliStream brotliStream = new BrotliStream(memoryStream, CompressionLevel.Optimal, leaveOpen: true))
			{
				brotliStream.Write(array);
			}
			payload = new RitsuDebugStatePresetWirePayload(1, Convert.ToBase64String(memoryStream.GetBuffer(), 0, (int)memoryStream.Length));
			if (JsonSerializer.Serialize(payload).Length <= 8192)
			{
				feedback = default(RitsuDebugActionFeedback);
				return true;
			}
			payload = default(RitsuDebugStatePresetWirePayload);
			feedback = RitsuDebugActionFeedback.Create("statePreset.dataLimit", "The preset contains too much data to apply.");
			return false;
		}

		private static RitsuDebugActionCheck ValidateWirePreset(RitsuDebugActionContext context, RitsuDebugStatePresetWirePayload payload)
		{
			if (!TryDecodePreset(payload, out RitsuDebugStatePreset preset, out RitsuDebugActionFeedback feedback))
			{
				return RitsuDebugActionCheck.Fail(feedback);
			}
			return ValidatePreset(context, preset);
		}

		private static async Task<string> ExecuteWirePresetAsync(RitsuDebugActionContext context, RitsuDebugStatePresetWirePayload payload)
		{
			if (!TryDecodePreset(payload, out RitsuDebugStatePreset preset, out RitsuDebugActionFeedback feedback))
			{
				throw new RitsuDebugActionExecutionException(feedback);
			}
			return await ExecutePresetAsync(context, preset);
		}

		private static RitsuLibSidecarPeerFeatures RequiredFeaturesForPresetPayload(RitsuDebugStatePresetWirePayload payload)
		{
			//IL_005b: Unknown result type (might be due to invalid IL or missing references)
			if (!TryDecodePreset(payload, out RitsuDebugStatePreset preset, out RitsuDebugActionFeedback _))
			{
				return RitsuLibSidecarPeerFeatures.None;
			}
			Dictionary<string, int> secondaryResources = preset.SecondaryResources;
			if (secondaryResources == null || secondaryResources.Count <= 0)
			{
				List<RitsuDebugStatePresetCapabilityTarget> capabilityTargets = preset.CapabilityTargets;
				if (capabilityTargets == null || capabilityTargets.Count <= 0)
				{
					foreach (RitsuDebugStatePresetCardPile cardPile in preset.CardPiles)
					{
						if (RitsuDebugCardActions.TryParseMutablePileType(cardPile.Pile, out var pileType) && ModCardPileRegistry.IsModPileType(pileType))
						{
							return (RitsuLibSidecarPeerFeatures)64u;
						}
					}
					return RitsuLibSidecarPeerFeatures.None;
				}
			}
			return (RitsuLibSidecarPeerFeatures)64u;
		}

		private static bool TryDecodePreset(RitsuDebugStatePresetWirePayload payload, out RitsuDebugStatePreset preset, out RitsuDebugActionFeedback feedback)
		{
