			}
			foreach (RitsuDebugStatePresetCardPile cardPile in preset.CardPiles)
			{
				RitsuDebugActionCheck result2 = RitsuDebugCardActions.ValidateModifyPile(context, new RitsuDebugCardActions.ModifyPilePayload(cardPile.Pile, RitsuDebugCardPileOperation.Clear, 0));
