			if (preset.Powers != null && (!CombatManager.Instance.IsInProgress || CombatManager.Instance.IsOverOrEnding || context.Target.PlayerCombatState == null || !context.Target.Creature.CanReceivePowers))
			{
				return RitsuDebugActionCheck.Fail("player.activeCombatRequired", "The saved powers require an active combat in which the target can receive powers.");
			}
