		private static async Task<string> ExecutePresetAsync(RitsuDebugActionContext context, RitsuDebugStatePreset preset)
		{
			int? num = preset.Player?.PotionSlots;
			if (num.HasValue)
			{
				int valueOrDefault = num.GetValueOrDefault();
				await SetPlayerValue(context, RitsuDebugPlayerOperation.SetPotionSlots, valueOrDefault);
			}
			foreach (RitsuDebugStatePresetCardPile pile in preset.CardPiles)
			{
				RitsuDebugCardActions.TryParseMutablePileType(pile.Pile, out var pileType);
				if (pile.ApplyMode == RitsuDebugStatePresetApplyMode.Replace)
				{
					await RitsuDebugCardActions.ExecuteModifyPileAsync(context, new RitsuDebugCardActions.ModifyPilePayload(pile.Pile, RitsuDebugCardPileOperation.Clear, 0));
				}
				foreach (RitsuDebugStatePresetCard card in pile.Cards)
				{
					await RitsuDebugCardActions.ExecuteCreateCardAsync(context, new RitsuDebugCardActions.CreateCardPayload(card.CardId, pile.Pile, card.Count, preset.ApplyInternalValues ? card.UpgradeLevels : 0, card.ToCardState(preset.ApplyInternalValues)), previewDeckAdds: false);
				}
				if ((int)pileType != 6)
				{
					continue;
				}
				CardPile pile2 = RitsuDebugCardActions.GetPile(context.Target, pileType);
				if (pile2 != null)
				{
					int num2 = pile.Cards.Sum((RitsuDebugStatePresetCard card) => card.Count);
					for (int num3 = 0; num3 < num2; num3++)
					{
						pile2.InvokeCardAddFinished();
					}
				}
			}
			if (preset.Relics != null)
			{
				await ApplyRelics(context, preset.Relics, preset.ApplyInternalValues);
			}
			if (preset.Potions != null)
			{
				await ApplyPotions(context, preset.Potions, preset.ApplyInternalValues);
			}
			if (preset.Powers != null)
			{
				await ApplyPowers(context, preset.Powers, preset.ApplyInternalValues);
			}
			if (preset.SecondaryResources != null)
			{
				foreach (var (resourceId, value) in preset.SecondaryResources)
				{
					await RitsuDebugSecondaryResourceActions.ExecuteModifyAsync(context, new RitsuDebugSecondaryResourceActions.ModifyPayload(resourceId, RitsuDebugSecondaryResourceOperation.Set, value));
				}
			}
			if (preset.Player != null)
			{
				await ApplyPlayer(context, preset.Player, potionSlotsAlreadyApplied: true);
			}
			if (preset.CapabilityTargets != null)
			{
				ApplyCapabilityTargets(context.Target, preset.CapabilityTargets);
			}
			return "Applied state preset '" + preset.Name + "'.";
		}

