		private static void ApplyCapabilityTargets(Player player, IReadOnlyList<RitsuDebugStatePresetCapabilityTarget> targets)
		{
			foreach (RitsuDebugStatePresetCapabilityTarget target in targets)
			{
				if (!RitsuDebugCapabilityActions.TryResolveTarget(player, target.Target, out AbstractModel model, out RitsuDebugActionFeedback feedback))
				{
					throw new RitsuDebugActionExecutionException(feedback);
				}
				ModelCapabilitySet modelCapabilitySet = ModelCapabilities.Get(model);
				modelCapabilitySet.Load(target.Capabilities);
				modelCapabilitySet.MarkDirty();
			}
		}

		private static async Task ApplyRelics(RitsuDebugActionContext context, RitsuDebugStatePresetInventory relics, bool applyInternalValues)
		{
			if (relics.ApplyMode == RitsuDebugStatePresetApplyMode.Replace)
			{
				await RitsuDebugInventoryActions.ExecuteClearInventoryAsync(context, new RitsuDebugInventoryActions.ClearInventoryPayload(RitsuDebugInventoryKind.Relics));
			}
			foreach (string modelId in relics.ModelIds)
			{
				RitsuDebugInventoryActions.TryResolveRelic(modelId, out RelicModel relic, out RitsuDebugActionFeedback _);
				if (context.Target.GetRelicById(((AbstractModel)relic).Id) == null)
				{
					RitsuDebugStatePresetRelicValues ritsuDebugStatePresetRelicValues = ((!applyInternalValues) ? null : relics.InternalValues?.GetValueOrDefault(modelId));
					await RitsuDebugInventoryActions.ExecuteAddRelicAsync(context, new RitsuDebugInventoryActions.RelicValuesPayload(modelId, ritsuDebugStatePresetRelicValues?.StackCount ?? 1, ritsuDebugStatePresetRelicValues?.DynamicVars));
				}
			}
		}

		private static async Task ApplyPotions(RitsuDebugActionContext context, RitsuDebugStatePresetPotions potions, bool applyInternalValues)
		{
			if (potions.ApplyMode == RitsuDebugStatePresetApplyMode.Replace)
			{
				await RitsuDebugInventoryActions.ExecuteClearInventoryAsync(context, new RitsuDebugInventoryActions.ClearInventoryPayload(RitsuDebugInventoryKind.Potions));
			}
			foreach (RitsuDebugStatePresetPotion item in potions.Items)
			{
				await RitsuDebugInventoryActions.ExecuteAddPotionAtSlotAsync(context, new RitsuDebugInventoryActions.ModelValuesPayload(item.PotionId, applyInternalValues ? item.DynamicVars : null), (potions.ApplyMode == RitsuDebugStatePresetApplyMode.Replace) ? item.SlotIndex.Value : (-1));
			}
		}

		private static async Task ApplyPowers(RitsuDebugActionContext context, RitsuDebugStatePresetPowers powers, bool applyInternalValues)
		{
			if (powers.ApplyMode == RitsuDebugStatePresetApplyMode.Replace)
			{
				PowerModel[] array = context.Target.Creature.Powers.ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					await PowerCmd.Remove(array[i]);
				}
			}
			foreach (RitsuDebugStatePresetPower item in powers.Items)
			{
				RitsuDebugCombatActions.TryResolvePower(item.PowerId, out PowerModel power, out RitsuDebugActionFeedback _);
				PowerModel val = power.ToMutable(0);
				if (applyInternalValues)
				{
					RitsuDebugModelValueOverrides.Apply(val.DynamicVars, item.DynamicVars);
				}
				await PowerCmd.Apply((PlayerChoiceContext)new BlockingPlayerChoiceContext(), val, context.Target.Creature, (decimal)((!applyInternalValues) ? 1 : item.Amount), (Creature)null, (CardModel)null, false);
			}
		}

		private static async Task ApplyPlayer(RitsuDebugActionContext context, RitsuDebugStatePresetPlayer state, bool potionSlotsAlreadyApplied)
		{
			if (state.Gold.HasValue)
			{
				await SetPlayerValue(context, RitsuDebugPlayerOperation.SetGold, state.Gold.Value);
			}
			if (state != null)
			{
				int? currentHp = state.CurrentHp;
				if (currentHp.HasValue)
				{
					int currentHp2 = currentHp.GetValueOrDefault();
					int? maxHp = state.MaxHp;
					if (maxHp.HasValue)
					{
						int maxHp2 = maxHp.GetValueOrDefault();
						if (context.Target.Creature.CurrentHp > maxHp2)
						{
							await SetPlayerValue(context, RitsuDebugPlayerOperation.SetCurrentHp, currentHp2);
						}
						if (context.Target.Creature.MaxHp != maxHp2)
						{
							await SetPlayerValue(context, RitsuDebugPlayerOperation.SetMaxHp, maxHp2);
						}
						if (context.Target.Creature.CurrentHp != currentHp2)
						{
							await SetPlayerValue(context, RitsuDebugPlayerOperation.SetCurrentHp, currentHp2);
						}
						goto IL_03cb;
					}
				}
			}
			if (state.CurrentHp.HasValue)
			{
				await SetPlayerValue(context, RitsuDebugPlayerOperation.SetCurrentHp, state.CurrentHp.Value);
			}
			else if (state.MaxHp.HasValue)
			{
				await SetPlayerValue(context, RitsuDebugPlayerOperation.SetMaxHp, state.MaxHp.Value);
			}
			goto IL_03cb;
			IL_03cb:
			if (state.MaxEnergy.HasValue)
			{
				await SetPlayerValue(context, RitsuDebugPlayerOperation.SetMaxEnergy, state.MaxEnergy.Value);
			}
			if (!potionSlotsAlreadyApplied && state.PotionSlots.HasValue)
			{
				await SetPlayerValue(context, RitsuDebugPlayerOperation.SetPotionSlots, state.PotionSlots.Value);
			}
			if (state.Energy.HasValue)
			{
				await SetPlayerValue(context, RitsuDebugPlayerOperation.SetEnergy, state.Energy.Value);
			}
			if (state.Stars.HasValue)
			{
				await SetPlayerValue(context, RitsuDebugPlayerOperation.SetStars, state.Stars.Value);
			}
			if (state.Block.HasValue && context.Target.Creature.Block != state.Block.Value)
			{
				int num = state.Block.Value - context.Target.Creature.Block;
				if (num > 0)
				{
					await CreatureCmd.GainBlock(context.Target.Creature, (decimal)num, (ValueProp)4, (CardPlay)null, false);
				}
				else
				{
					await CreatureCmd.LoseBlock((PlayerChoiceContext)new BlockingPlayerChoiceContext(), context.Target.Creature, (decimal)(-num), (Creature)null);
				}
