		public bool RecordInternalValues { get; set; }

		[JsonPropertyName("apply_internal_values")]
		[JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingDefault)]
		public bool ApplyInternalValues { get; set; }

		[JsonPropertyName("card_piles")]
		public List<RitsuDebugStatePresetCardPile> CardPiles { get; set; } = new List<RitsuDebugStatePresetCardPile>();

		[JsonPropertyName("relics")]
		[JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
		public RitsuDebugStatePresetInventory? Relics { get; set; }

		[JsonPropertyName("potions")]
		[JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
		public RitsuDebugStatePresetPotions? Potions { get; set; }

		[JsonPropertyName("powers")]
		[JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
		public RitsuDebugStatePresetPowers? Powers { get; set; }

		[JsonPropertyName("player")]
		[JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
		public RitsuDebugStatePresetPlayer? Player { get; set; }

		[JsonPropertyName("secondary_resources")]
		[JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
		public Dictionary<string, int>? SecondaryResources { get; set; }

		[JsonPropertyName("model_capabilities")]
		[JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
		public List<RitsuDebugStatePresetCapabilityTarget>? CapabilityTargets { get; set; }

		internal bool HasAnyContent
		{
			get
			{
				if (CardPiles.Count <= 0 && Relics == null && Potions == null && Powers == null)
				{
					RitsuDebugStatePresetPlayer player = Player;
					if (player == null || !player.HasAnyValue)
					{
						Dictionary<string, int> secondaryResources = SecondaryResources;
						if (secondaryResources == null || secondaryResources.Count <= 0)
						{
							List<RitsuDebugStatePresetCapabilityTarget> capabilityTargets = CapabilityTargets;
							if (capabilityTargets != null)
							{
								return capabilityTargets.Count > 0;
							}
							return false;
						}
					}
				}
				return true;
			}
		}

		internal RitsuDebugStatePreset Clone(bool assignNewId = false)
		{
			return new RitsuDebugStatePreset
			{
				Id = (assignNewId ? Guid.NewGuid().ToString("N") : Id),
				Name = Name,
				RecordInternalValues = RecordInternalValues,
				ApplyInternalValues = ApplyInternalValues,
				CardPiles = CardPiles.Select((RitsuDebugStatePresetCardPile pile) => pile.Clone()).ToList(),
				Relics = Relics?.Clone(),
				Potions = Potions?.Clone(),
				Powers = Powers?.Clone(),
				Player = Player?.Clone(),
				SecondaryResources = ((SecondaryResources == null) ? null : new Dictionary<string, int>(SecondaryResources, StringComparer.Ordinal)),
				CapabilityTargets = ((CapabilityTargets == null) ? null : CapabilityTargets.Select((RitsuDebugStatePresetCapabilityTarget target) => target.Clone()).ToList())
			};
		}
