	internal static class RitsuDebugStatePresetStore
	{
		internal const int MaximumPresetCount = 128;

		internal const int MaximumNameLength = 80;

		internal const int MaximumCardsPerPile = 100;

		internal const int MaximumRelics = 128;

		internal const int MaximumPowers = 128;

		internal const int MaximumSecondaryResources = 128;

		internal const int MaximumCapabilityTargets = 512;

		internal const string DataKey = "debug-state-presets";

		internal const string FileName = "debug_state_presets.json";

		private static readonly JsonSerializerOptions ExportOptions = new JsonSerializerOptions
		{
			PropertyNameCaseInsensitive = false,
			WriteIndented = false
		};

		private static readonly ModDataStore Store = ModDataStore.For("com.ritsukage.sts2-RitsuLib");

		internal static IReadOnlyList<RitsuDebugStatePreset> GetSnapshot()
		{
			RitsuLibSettingsStore.Initialize();
			return Array.AsReadOnly((from preset in (Store.Get<RitsuDebugStatePresetCollection>("debug-state-presets").Presets ?? new List<RitsuDebugStatePreset>()).Where(IsReadable).Take(128)
				select preset.Clone()).ToArray());
		}

		internal static bool TrySave(RitsuDebugStatePreset preset, out RitsuDebugActionFeedback feedback)
		{
			ArgumentNullException.ThrowIfNull(preset, "preset");
			RitsuDebugActionCheck ritsuDebugActionCheck = RitsuDebugStatePresetActions.ValidateStoredPreset(preset);
			if (!ritsuDebugActionCheck.Success)
			{
				feedback = ritsuDebugActionCheck.Feedback;
				return false;
			}
			RitsuLibSettingsStore.Initialize();
			RitsuDebugStatePresetCollection ritsuDebugStatePresetCollection = Store.Get<RitsuDebugStatePresetCollection>("debug-state-presets");
			RitsuDebugStatePresetCollection ritsuDebugStatePresetCollection2 = ritsuDebugStatePresetCollection;
			if (ritsuDebugStatePresetCollection2.Presets == null)
			{
				List<RitsuDebugStatePreset> list = (ritsuDebugStatePresetCollection2.Presets = new List<RitsuDebugStatePreset>());
			}
			int num = ritsuDebugStatePresetCollection.Presets.FindIndex((RitsuDebugStatePreset candidate) => candidate != null && string.Equals(candidate.Id, preset.Id, StringComparison.OrdinalIgnoreCase));
			if (ritsuDebugStatePresetCollection.Presets.Any((RitsuDebugStatePreset candidate) => IsReadable(candidate) && !string.Equals(candidate.Id, preset.Id, StringComparison.OrdinalIgnoreCase) && string.Equals(candidate.Name, preset.Name.Trim(), StringComparison.OrdinalIgnoreCase)))
			{
				feedback = RitsuDebugActionFeedback.Create("statePreset.duplicateName", "A preset named '{0}' already exists.", preset.Name.Trim());
				return false;
			}
			if (num < 0 && ritsuDebugStatePresetCollection.Presets.Count(IsReadable) >= 128)
			{
				feedback = RitsuDebugActionFeedback.Create("statePreset.countLimit", "At most {0} presets can be stored.", 128);
				return false;
			}
			RitsuDebugStatePreset ritsuDebugStatePreset = preset.Clone();
			ritsuDebugStatePreset.Name = ritsuDebugStatePreset.Name.Trim();
			if (num < 0)
			{
				ritsuDebugStatePresetCollection.Presets.Add(ritsuDebugStatePreset);
			}
			else
			{
				ritsuDebugStatePresetCollection.Presets[num] = ritsuDebugStatePreset;
			}
			ritsuDebugStatePresetCollection.SchemaVersion = 1;
			Store.Save("debug-state-presets");
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}

		internal static bool TryDelete(string presetId)
		{
			if (!IsValidId(presetId))
			{
				return false;
			}
			RitsuLibSettingsStore.Initialize();
			RitsuDebugStatePresetCollection ritsuDebugStatePresetCollection2;
			RitsuDebugStatePresetCollection ritsuDebugStatePresetCollection = (ritsuDebugStatePresetCollection2 = Store.Get<RitsuDebugStatePresetCollection>("debug-state-presets"));
			if (ritsuDebugStatePresetCollection2.Presets == null)
			{
				List<RitsuDebugStatePreset> list = (ritsuDebugStatePresetCollection2.Presets = new List<RitsuDebugStatePreset>());
			}
			bool num = ritsuDebugStatePresetCollection.Presets.RemoveAll((RitsuDebugStatePreset candidate) => candidate != null && string.Equals(candidate.Id, presetId, StringComparison.OrdinalIgnoreCase)) > 0;
			if (num)
			{
				Store.Save("debug-state-presets");
			}
			return num;
		}

		internal static string Export(RitsuDebugStatePreset preset)
		{
			ArgumentNullException.ThrowIfNull(preset, "preset");
			return JsonSerializer.Serialize(preset, ExportOptions);
		}

		internal static bool TryImport(string json, out RitsuDebugStatePreset preset, out RitsuDebugActionFeedback feedback)
		{
			preset = null;
			if (string.IsNullOrWhiteSpace(json) || json.Length > 262144)
			{
				feedback = RitsuDebugActionFeedback.Create("statePreset.importInvalid", "The imported preset is empty, malformed, or too large.");
				return false;
			}
			try
			{
				preset = JsonSerializer.Deserialize<RitsuDebugStatePreset>(json, ExportOptions);
			}
			catch (Exception ex) when (((ex is JsonException || ex is NotSupportedException) ? 1 : 0) != 0)
			{
				feedback = RitsuDebugActionFeedback.Create("statePreset.importInvalid", "The imported preset is empty, malformed, or too large.");
				return false;
			}
			if (preset == null)
			{
				feedback = RitsuDebugActionFeedback.Create("statePreset.importInvalid", "The imported preset is empty, malformed, or too large.");
				return false;
			}
			preset.Id = Guid.NewGuid().ToString("N");
			RitsuDebugActionCheck ritsuDebugActionCheck = RitsuDebugStatePresetActions.ValidateStoredPreset(preset);
			if (!ritsuDebugActionCheck.Success)
			{
				feedback = ritsuDebugActionCheck.Feedback;
				return false;
			}
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}

		private static bool IsReadable(RitsuDebugStatePreset? preset)
		{
			if (preset != null && IsValidId(preset.Id) && !string.IsNullOrWhiteSpace(preset.Name) && preset.Name.Length <= 80 && preset.CardPiles != null && preset.CardPiles.All((RitsuDebugStatePresetCardPile pile) => pile?.Cards != null && pile.Cards.All((RitsuDebugStatePresetCard card) => card != null)) && (preset.Relics == null || (preset.Relics.ModelIds != null && preset.Relics.ModelIds.All((string id) => id != null))) && (preset.Potions == null || (preset.Potions.Items != null && preset.Potions.Items.All((RitsuDebugStatePresetPotion potion) => potion != null))) && (preset.Powers == null || (preset.Powers.Items != null && preset.Powers.Items.All((RitsuDebugStatePresetPower power) => power != null))) && (preset.SecondaryResources == null || preset.SecondaryResources.Keys.All((string id) => id != null)) && (preset.CapabilityTargets == null || preset.CapabilityTargets.All((RitsuDebugStatePresetCapabilityTarget target) => target?.Capabilities?.Capabilities != null && target.Capabilities.Capabilities.All((ModelCapabilitySaveEntry capability) => capability != null))))
			{
				return preset.HasAnyContent;
			}
			return false;
		}

		private static bool IsValidId(string? id)
		{
			Guid result;
			if (id != null && id.Length == 32)
			{
				return Guid.TryParseExact(id, "N", out result);
			}
			return false;
		}
	}
	internal static class RitsuDebugToolsInterfaceStateStore
	{
		private const string DataKey = "debug_tools_interface_state";

		private const string FileName = "debug_tools_interface_state.json";

		private static ModDataStore? _store;

		private static IDisposable? _profileServicesSubscription;

		internal static event Action<bool>? StateRestored;

		internal static void Register(ModDataStore store)
		{
			ArgumentNullException.ThrowIfNull(store, "store");
			if (_store == null)
			{
				_store = store;
				store.Register("debug_tools_interface_state", "debug_tools_interface_state.json", SaveScope.Profile, () => new RitsuDebugToolsInterfaceState(), autoCreateIfMissing: true);
				store.EntryReloaded += OnEntryReloaded;
				_profileServicesSubscription = RitsuLibFramework.SubscribeLifecycle((Action<ProfileServicesInitializedEvent>)delegate
				{
					PublishRestoredState();
				}, true);
			}
		}

		internal static bool IsVisible()
		{
			if (TryGetState(out RitsuDebugToolsInterfaceState state))
			{
				return state.IsVisible;
			}
			return false;
		}

		internal static void RememberVisibility(bool isVisible)
		{
			ModDataStore store = _store;
			if (store == null || !store.IsProfileInitialized)
			{
				return;
			}
			try
			{
				if (store.Get<RitsuDebugToolsInterfaceState>("debug_tools_interface_state").IsVisible != isVisible)
				{
					store.Modify("debug_tools_interface_state", delegate(RitsuDebugToolsInterfaceState value)
					{
						value.IsVisible = isVisible;
					});
					store.Save("debug_tools_interface_state");
				}
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[DebugTools] Failed to save the developer-tools panel state: " + ex.Message, 1);
			}
		}

		private static void OnEntryReloaded(string key)
		{
			if (key.Equals("debug_tools_interface_state", StringComparison.OrdinalIgnoreCase))
			{
				PublishRestoredState();
			}
		}

		private static void PublishRestoredState()
		{
			StateRestored?.Invoke(IsVisible());
		}

		private static bool TryGetState(out RitsuDebugToolsInterfaceState state)
		{
			state = null;
			ModDataStore store = _store;
			if (store == null || !store.IsProfileInitialized)
			{
				return false;
			}
			try
			{
				state = store.Get<RitsuDebugToolsInterfaceState>("debug_tools_interface_state");
				return true;
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn("[DebugTools] Failed to load the developer-tools panel state: " + ex.Message, 1);
				return false;
			}
		}
	}
	internal sealed class RitsuDebugToolsInterfaceState
	{
		[JsonPropertyName("is_visible")]
		public bool IsVisible { get; set; }
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Supplies player selection, refresh, and page navigation to a registered developer-tools page.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         向已注册的开发者工具页面提供玩家选择、刷新与页面导航能力。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Page callbacks and controls run on Godot's main thread. The player list is an immutable snapshot taken
	///         when the page is evaluated; request a refresh before relying on later run state.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         页面回调与控件在 Godot 主线程运行。玩家列表是页面求值时取得的不可变快照；如需依赖后续游戏状态，
	///         应先请求刷新。
	///     </para>
	/// </remarks>
	public sealed class RitsuDebugToolsPageContext
	{
		private readonly Action _requestRefresh;

		private readonly Func<string, bool> _tryNavigateToPage;

		/// <summary>
		///     <para xml:lang="en">Gets the player selected by the developer-tools target control, if available.</para>
		///     <para xml:lang="zh-CN">获取开发者工具目标控件当前选中的玩家；当前没有玩家时为 null。</para>
		/// </summary>
		public Player? TargetPlayer { get; }

		/// <summary>
		///     <para xml:lang="en">Gets an immutable snapshot of players currently available to the workspace.</para>
		///     <para xml:lang="zh-CN">获取工作区当前可用玩家的不可变快照。</para>
		/// </summary>
		public IReadOnlyList<Player> Players { get; }

		internal RitsuDebugToolsPageContext(Player? targetPlayer, IReadOnlyList<Player> players, Action requestRefresh, Func<string, bool> tryNavigateToPage)
		{
			TargetPlayer = targetPlayer;
			Players = players;
			_requestRefresh = requestRefresh;
			_tryNavigateToPage = tryNavigateToPage;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Schedules a workspace refresh after the current callback or UI event completes. Repeated requests
		///         before the deferred refresh runs are coalesced.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在当前回调或界面事件完成后安排一次工作区刷新；延迟刷新执行前的重复请求会被合并。
		///     </para>
		/// </summary>
		public void RequestRefresh()
		{
			_requestRefresh();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Opens another currently available developer-tools page by its qualified
		///         <c>modId:pageId</c> identity.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         通过 <c>modId:pageId</c> 全局标识打开另一个当前可用的开发者工具页面。
		///     </para>
		/// </summary>
		/// <param name="qualifiedPageId">
		///     <para xml:lang="en">The qualified identity of the destination page.</para>
		///     <para xml:lang="zh-CN">目标页面的全局标识。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when the destination is currently available and was opened; otherwise,
		///         <see langword="false" />. Opening the current page also returns <see langword="true" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         当目标页面当前可用且已打开时返回 <see langword="true" />，否则返回 <see langword="false" />；
		///         打开当前页面同样返回 <see langword="true" />。
		///     </para>
		/// </returns>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">Thrown when <paramref name="qualifiedPageId" /> is blank.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="qualifiedPageId" /> 为空时抛出。</para>
		/// </exception>
		public bool TryNavigateToPage(string qualifiedPageId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(qualifiedPageId, "qualifiedPageId");
			return _tryNavigateToPage(qualifiedPageId);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines one independently owned page in RitsuLib's visual developer-tools dock.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         定义 RitsuLib 可视化开发者工具停靠面板中的一个独立所有权页面。
	///     </para>
	/// </summary>
	public sealed class RitsuDebugToolsPageDefinition
	{
		/// <summary>
		///     <para xml:lang="en">Gets the owning mod manifest ID.</para>
		///     <para xml:lang="zh-CN">获取所属模组的清单 ID。</para>
		/// </summary>
		public string ModId { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the stable page ID within the owning mod.</para>
		///     <para xml:lang="zh-CN">获取页面在所属模组内的稳定 ID。</para>
		/// </summary>
		public string Id { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the globally unique ID in <c>modId:pageId</c> form.</para>
		///     <para xml:lang="zh-CN">获取采用 <c>modId:pageId</c> 格式的全局唯一 ID。</para>
		/// </summary>
		public string QualifiedId => ModId + ":" + Id;

		/// <summary>
		///     <para xml:lang="en">Gets the deferred localized or literal display title.</para>
		///     <para xml:lang="zh-CN">获取延迟解析的本地化或字面显示标题。</para>
		/// </summary>
		public ModSettingsText Title { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the page order. Lower values appear first; values from -100,000 through 100,000 are accepted.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取页面顺序；数值较小的页面排在前面，允许范围为 -100,000 至 100,000。
		///     </para>
		/// </summary>
		public int SortOrder { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the preferred fraction of viewport width used by the joined dock, from 0.35 through 0.90.
		///         The host still constrains the page to the space available beside the rail. The default is 0.62.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取组合式停靠面板期望占用的视口宽度比例，范围为 0.35 至 0.90。宿主仍会将页面限制在侧边栏旁的
		///         可用空间内；默认值为 0.62。
		///     </para>
		/// </summary>
		public float PreferredWidthFraction { get; init; } = 0.62f;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets an optional side-effect-free icon factory. The host accepts an existing texture up to 2,048
		///         pixels per axis; null or invalid results use the fallback page icon. The caller retains ownership
		///         and must keep returned textures valid while the page remains registered.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取可选且无副作用的图标工厂。宿主接受单边不超过 2,048 像素的现有纹理；返回 null 或无效结果时
		///         使用页面回退图标。调用方仍持有返回纹理，并须在页面保持注册期间确保纹理有效。
		///     </para>
		/// </summary>
		public Func<Texture2D?>? IconFactory { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets an optional visibility predicate, re-evaluated when the workspace refreshes. Exceptions hide
		///         only this page and are logged once per page instance.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取可选可见性谓词；工作区刷新时重新求值。异常只会隐藏当前页面，并按页面实例记录一次日志。
		///     </para>
		/// </summary>
		public Func<RitsuDebugToolsPageContext, bool>? VisibleWhen { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the factory that creates a fresh page control.</para>
		///     <para xml:lang="zh-CN">获取用于创建全新页面控件的工厂。</para>
		/// </summary>
		public Func<RitsuDebugToolsPageContext, Control> ContentFactory { get; }

		/// <summary>
		///     <para xml:lang="en">Creates a page definition with required identity, title, and content factory.</para>
		///     <para xml:lang="zh-CN">使用必需的标识、标题和内容工厂创建页面定义。</para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">The owning manifest ID. It participates in the globally unique page identity.</para>
		///     <para xml:lang="zh-CN">所属模组的清单 ID；它会参与组成全局唯一页面标识。</para>
		/// </param>
		/// <param name="id">
		///     <para xml:lang="en">The stable page ID within <paramref name="modId" />.</para>
		///     <para xml:lang="zh-CN">页面在 <paramref name="modId" /> 内的稳定 ID。</para>
		/// </param>
		/// <param name="title">
		///     <para xml:lang="en">Deferred localized or literal text used by the rail and page header.</para>
		///     <para xml:lang="zh-CN">侧边栏与页面标题使用的延迟本地化文本或字面文本。</para>
		/// </param>
		/// <param name="contentFactory">
		///     <para xml:lang="en">
		///         Creates a new, unattached control whenever the page is rebuilt. Returning null, an invalid control,
		///         or a control that already has a parent is rejected by the host.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         页面重建时创建一个新的未挂载控件。返回 null、无效控件或已有父节点的控件会被宿主拒绝。
		///     </para>
		/// </param>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">Thrown when <paramref name="modId" /> or <paramref name="id" /> is blank.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="modId" /> 或 <paramref name="id" /> 为空时抛出。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">Thrown when <paramref name="title" /> or <paramref name="contentFactory" /> is null.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="title" /> 或 <paramref name="contentFactory" /> 为 null 时抛出。</para>
		/// </exception>
		public RitsuDebugToolsPageDefinition(string modId, string id, ModSettingsText title, Func<RitsuDebugToolsPageContext, Control> contentFactory)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentNullException.ThrowIfNull(title, "title");
			ArgumentNullException.ThrowIfNull(contentFactory, "contentFactory");
			ModId = modId.Trim();
			Id = id.Trim();
			Title = title;
			ContentFactory = contentFactory;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Registers independently owned pages for the visual developer-tools dock without replacing built-in or
	///         other mods' pages.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为可视化开发者工具停靠面板注册独立所有权页面，且不会替换内置页面或其他模组的页面。
	///     </para>
	/// </summary>
	public static class RitsuDebugToolsPageRegistry
	{
		private sealed class Registration(RitsuDebugToolsPageDefinition definition) : IDisposable
		{
			private int _disposed;

			internal RitsuDebugToolsPageDefinition Definition { get; } = definition;

			public void Dispose()
			{
				if (Interlocked.Exchange(ref _disposed, 1) != 0)
				{
					return;
				}
				bool flag = false;
				using (SyncRoot.EnterScope())
				{
					if (Pages.TryGetValue(Definition.QualifiedId, out Registration value) && value == this)
					{
						flag = Pages.Remove(Definition.QualifiedId);
					}
				}
				if (flag)
				{
					NotifyChanged();
				}
			}
		}

		private const int MaximumPageCount = 256;

		private const int MaximumIdentityLength = 128;

		private const int MaximumSortOrder = 100000;

		private static readonly Dictionary<string, Registration> Pages = new Dictionary<string, Registration>(StringComparer.OrdinalIgnoreCase);

		private static readonly HashSet<string> ReservedQualifiedIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
		{
			"com.ritsukage.sts2-RitsuLib:cards", "com.ritsukage.sts2-RitsuLib:pile-cards", "com.ritsukage.sts2-RitsuLib:relics", "com.ritsukage.sts2-RitsuLib:potions", "com.ritsukage.sts2-RitsuLib:powers", "com.ritsukage.sts2-RitsuLib:secondary-resources", "com.ritsukage.sts2-RitsuLib:players", "com.ritsukage.sts2-RitsuLib:creatures", "com.ritsukage.sts2-RitsuLib:monsters", "com.ritsukage.sts2-RitsuLib:rooms",
			"com.ritsukage.sts2-RitsuLib:encounters", "com.ritsukage.sts2-RitsuLib:events", "com.ritsukage.sts2-RitsuLib:state-presets"
		};

		private static readonly Lock SyncRoot = new Lock();

		internal static event Action? Changed;

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a page and returns an ownership handle. Disposing the handle removes only that exact
		///         registration. Duplicate qualified IDs are rejected rather than replaced.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册页面并返回所有权句柄。释放句柄时只移除该次注册；重复的全局 ID 会被拒绝而不会覆盖原页面。
		///     </para>
		/// </summary>
		/// <param name="definition">
		///     <para xml:lang="en">The immutable page definition to validate and register.</para>
		///     <para xml:lang="zh-CN">要校验并注册的不可变页面定义。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">An idempotent handle that unregisters this page when disposed.</para>
		///     <para xml:lang="zh-CN">释放时取消注册当前页面的幂等句柄。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">
		///         Thrown when identity text is malformed, the qualified ID is reserved, or it already exists.
		///     </para>
		///     <para xml:lang="zh-CN">当标识文本格式无效、全局 ID 已保留或已存在时抛出。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">Thrown when <paramref name="definition" /> is null.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="definition" /> 为 null 时抛出。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentOutOfRangeException">
		///     <para xml:lang="en">
		///         Thrown when the sort order, preferred width, or total page count exceeds its supported bound.
		///     </para>
		///     <para xml:lang="zh-CN">当排序值、期望宽度或页面总数超过支持范围时抛出。</para>
		/// </exception>
		public static IDisposable Register(RitsuDebugToolsPageDefinition definition)
		{
			ArgumentNullException.ThrowIfNull(definition, "definition");
			ValidateIdentity(definition.ModId, "ModId");
			ValidateIdentity(definition.Id, "Id");
			int sortOrder = definition.SortOrder;
			if ((sortOrder < -100000 || sortOrder > 100000) ? true : false)
			{
				throw new ArgumentOutOfRangeException("definition", definition.SortOrder, $"Developer-tools page order must be between {-100000} and {100000}.");
			}
			float preferredWidthFraction = definition.PreferredWidthFraction;
			bool flag = ((preferredWidthFraction < 0.35f || preferredWidthFraction > 0.9f) ? true : false);
			if (flag || !float.IsFinite(definition.PreferredWidthFraction))
			{
				throw new ArgumentOutOfRangeException("definition", definition.PreferredWidthFraction, "Developer-tools page width fraction must be between 0.35 and 0.90.");
			}
			if (ReservedQualifiedIds.Contains(definition.QualifiedId))
			{
				throw new ArgumentException("Developer-tools page '" + definition.QualifiedId + "' is reserved by RitsuLib.", "definition");
			}
			Registration registration = new Registration(definition);
			using (SyncRoot.EnterScope())
			{
				if (Pages.ContainsKey(definition.QualifiedId))
				{
					throw new ArgumentException("Developer-tools page '" + definition.QualifiedId + "' is already registered.", "definition");
				}
				if (Pages.Count >= 256)
				{
					throw new ArgumentOutOfRangeException("definition", Pages.Count, $"No more than {256} developer-tools pages may be registered.");
				}
				Pages.Add(definition.QualifiedId, registration);
			}
			NotifyChanged();
			return registration;
		}

		/// <summary>
		///     <para xml:lang="en">Returns an immutable, deterministically ordered snapshot of registered pages.</para>
		///     <para xml:lang="zh-CN">返回已注册页面的不可变确定顺序快照。</para>
		/// </summary>
		public static IReadOnlyList<RitsuDebugToolsPageDefinition> GetPages()
		{
			using (SyncRoot.EnterScope())
			{
				return Array.AsReadOnly((from registration in Pages.Values
					select registration.Definition into definition
					orderby definition.SortOrder
					select definition).ThenBy<RitsuDebugToolsPageDefinition, string>((RitsuDebugToolsPageDefinition definition) => definition.ModId, StringComparer.OrdinalIgnoreCase).ThenBy<RitsuDebugToolsPageDefinition, string>((RitsuDebugToolsPageDefinition definition) => definition.Id, StringComparer.OrdinalIgnoreCase).ToArray());
			}
		}

		private static void ValidateIdentity(string value, string paramName)
		{
			if (value.Length > 128)
			{
				throw new ArgumentException($"Developer-tools identity components cannot exceed {128} characters.", paramName);
			}
			if (value.Any(delegate(char character)
			{
				bool flag = char.IsAsciiLetterOrDigit(character);
				if (!flag)
				{
					bool flag2 = ((character == '-' || character == '.' || character == '_') ? true : false);
					flag = flag2;
				}
				return !flag;
			}))
			{
				throw new ArgumentException("Developer-tools identity components may contain only ASCII letters, digits, '.', '_', and '-'.", paramName);
			}
		}

		private static void NotifyChanged()
		{
			try
			{
				Changed?.Invoke();
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn($"[DebugToolsUi] Page-registry refresh callback failed: {ex}", 1);
			}
		}
	}
}
namespace STS2RitsuLib.Diagnostics.CompendiumExport
{
	/// <summary>
	///     <para xml:lang="en">
	///         Renders compendium-style relic inspection and potion-lab focus panels in an offscreen
	///         <see cref="T:Godot.SubViewport" />. Each capture attempt releases its temporary scene subtree in a
	///         <c>finally</c> path, including after capture or frame-wait failures.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在离屏 <see cref="T:Godot.SubViewport" /> 中渲染图鉴风格的遗物查看面板和药水实验室聚焦面板。每次捕获尝试都会在
	///         <c>finally</c> 路径中释放临时场景子树，包括捕获或等待帧失败后。
	///     </para>
	/// </summary>
	public static class CompendiumDetailPngExporter
	{
		private const string InspectRelicScene = "screens/inspect_relic_screen/inspect_relic_screen";

		private const string PotionScenePath = "potions/potion";

		private const float PotionLabFocusScale = 1.2f;

		private const float PotionToTipsGap = 32f;

		private const float ExportViewportFramePad = 6f;

		private const int InitialLayoutViewportSide = 4096;

		private const float RelicToHoverColumnSep = 18f;

		private const float NPotionExportMinSide = 60f;

		private const float RelicPopupBaseWidth = 864f;

		private const float RelicPopupBaseHeight = 864f;

		private const float RelicPopupHorizontalTrimEachSide = 30f;

		private const float PotionIconDownshiftPx = 10f;

		private const int FramesAfterHostAdded = 2;

		private const int FramesAfterLayout = 2;

		private const int FramesAfterRefCardVisuals = 2;

		private const int FramesAfterRenderOnce = 5;

		private const int FramesAfterSaveBeforeTeardown = 1;

		private const int FramesFlushBeforeSyncDispose = 1;

		private const int FramesAfterSyncTeardown = 2;

		private const int FramesBetweenItems = 1;

		private const int FramesBeforeRetry = 8;

		private const int MaxCaptureAttemptsPerFile = 2;

		private static int _exportInProgress;

		private static readonly Vector2 RelicInspectMinUnscaledFloor;

		private static readonly Vector2 PotionRowMinUnscaledFloor;

		/// <summary>
		///     <para xml:lang="en">
		///         Starts the requested compendium-detail batch export when no other compendium export is running.
		///     </para>
		///     <para xml:lang="zh-CN">在没有其他图鉴导出运行时启动请求的图鉴详情批量导出。</para>
		/// </summary>
		public static void BeginExport(CompendiumPngExportRequest request, Action<string>? log = null)
		{
			//IL_0053: Unknown result type (might be due to invalid IL or missing references)
			//IL_0058: Unknown result type (might be due to invalid IL or missing references)
			if (NGame.Instance == null)
			{
				log?.Invoke("Cannot export: the game is not loaded yet.");
				return;
			}
			if (Interlocked.CompareExchange(ref _exportInProgress, 1, 0) != 0)
			{
				log?.Invoke("Cannot export: another compendium detail PNG export is already running.");
				return;
			}
			CompendiumPngExportRequest req = request;
			Action<string> lg = log;
			try
			{
				Callable val = Callable.From((Action)delegate
				{
					RunExportOnMainThreadEntry(req, lg);
				});
				((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			}
			catch
			{
				Volatile.Write(ref _exportInProgress, 0);
				throw;
			}
		}

		private static async void RunExportOnMainThreadEntry(CompendiumPngExportRequest request, Action<string>? log)
		{
			try
			{
				await RunExportAsync(request, log);
			}
			catch (Exception ex)
			{
				log?.Invoke("Compendium detail export stopped: " + ex.Message);
				GD.PushError($"Compendium detail PNG export: {ex}");
			}
			finally
			{
				Volatile.Write(ref _exportInProgress, 0);
			}
		}

		private static async Task RunExportAsync(CompendiumPngExportRequest request, Action<string>? log)
		{
			if (!CardPngExporter.TryValidateExportEnvironment(out string error))
			{
				log?.Invoke(error);
				return;
			}
			if (!request.Relics && !request.Potions)
			{
				log?.Invoke("Nothing to export: enable Relics and/or Potions in the request.");
				return;
			}
			if (string.IsNullOrWhiteSpace(request.OutputDirectory))
			{
				log?.Invoke("Cannot export: choose an output folder.");
				return;
			}
			if (!double.IsFinite(request.Scale))
			{
				log?.Invoke("Cannot export: scale must be a finite number.");
				return;
			}
			float scale = Mathf.Max(0.25f, (float)request.Scale);
			string outDir = ProjectSettings.GlobalizePath(request.OutputDirectory.Trim());
			try
			{
				Directory.CreateDirectory(outDir);
			}
			catch (Exception ex)
			{
				log?.Invoke("Could not create output folder: " + ex.Message);
				return;
			}
			SceneTree tree = ((Node)NGame.Instance).GetTree();
			if (tree == null)
			{
				log?.Invoke("Scene tree is not available.");
				return;
			}
			string idFilter = (string.IsNullOrWhiteSpace(request.IdFilterSubstring) ? null : request.IdFilterSubstring.Trim());
			bool includeRelicHover = request.IncludeRelicHoverTips;
			IReadOnlyList<RelicModel> readOnlyList2;
			if (!request.Relics)
			{
				IReadOnlyList<RelicModel> readOnlyList = Array.Empty<RelicModel>();
				readOnlyList2 = readOnlyList;
			}
			else
			{
				IReadOnlyList<RelicModel> readOnlyList = BuildRelicExportList(idFilter);
				readOnlyList2 = readOnlyList;
			}
			IReadOnlyList<RelicModel> relicList = readOnlyList2;
			IReadOnlyList<PotionModel> readOnlyList4;
			if (!request.Potions)
			{
				IReadOnlyList<PotionModel> readOnlyList3 = Array.Empty<PotionModel>();
				readOnlyList4 = readOnlyList3;
			}
			else
			{
				IReadOnlyList<PotionModel> readOnlyList3 = BuildPotionExportList(idFilter);
				readOnlyList4 = readOnlyList3;
			}
			IReadOnlyList<PotionModel> potionList = readOnlyList4;
			IReadOnlyList<RelicModel> readOnlyList5;
			if (!request.Relics)
			{
				IReadOnlyList<RelicModel> readOnlyList = Array.Empty<RelicModel>();
				readOnlyList5 = readOnlyList;
			}
			else
			{
				IReadOnlyList<RelicModel> readOnlyList = BuildRelicExportList(null);
				readOnlyList5 = readOnlyList;
			}
			IReadOnlyList<RelicModel> models = readOnlyList5;
			IReadOnlyList<PotionModel> readOnlyList6;
			if (!request.Potions)
			{
				IReadOnlyList<PotionModel> readOnlyList3 = Array.Empty<PotionModel>();
				readOnlyList6 = readOnlyList3;
			}
			else
			{
				IReadOnlyList<PotionModel> readOnlyList3 = BuildPotionExportList(null);
				readOnlyList6 = readOnlyList3;
			}
			IReadOnlyList<PotionModel> models2 = readOnlyList6;
			IReadOnlyDictionary<string, string> relicFileStems = CardPngExporter.BuildSafeFileStemLookup(models, (RelicModel val) => ((AbstractModel)val).Id.Entry, delegate(RelicModel val)
			{
				LocString title2 = val.Title;
				return (!title2.Exists()) ? "" : title2.GetFormattedText();
			}, request.UseLocalizedFileNames, "relic");
			IReadOnlyDictionary<string, string> potionFileStems = CardPngExporter.BuildSafeFileStemLookup(models2, (PotionModel val) => ((AbstractModel)val).Id.Entry, delegate(PotionModel val)
			{
				LocString title2 = val.Title;
				return (!title2.Exists()) ? "" : title2.GetFormattedText();
			}, request.UseLocalizedFileNames, "potion");
			if (request.Potions && potionList.Count == 0)
			{
				var (value, value2, value3) = GetPotionModelDbDiagnostics();
				log?.Invoke("Potion export: no entries after filter (empty ModelDb or filter matched nothing). " + $"AllPotions enumerations: {value} (including deprecated {value2}), " + $"same source as the in-game potion lab; pool slot iterations: {value3}.");
			}
			if (request.Relics)
			{
				log?.Invoke($"Relic export: {relicList.Count} item(s) after filter.");
			}
			int steps = relicList.Count + potionList.Count;
			CompendiumPngExportProgressOverlay progressUi = null;
			string title = ((request.Relics && request.Potions) ? ModSettingsLocalization.Get("ritsulib.compendiumPngExport.progress.title.both", "Exporting relic and potion detail images…") : (request.Relics ? ModSettingsLocalization.Get("ritsulib.compendiumPngExport.progress.title.relics", "Exporting relic detail images…") : ModSettingsLocalization.Get("ritsulib.compendiumPngExport.progress.title.potions", "Exporting potion detail images…")));
			CompendiumPngExportSession.ResetForNewRun();
			try
			{
				progressUi = CompendiumPngExportProgressOverlay.Attach((Node)(object)NGame.Instance, Math.Max(1, steps), title);
				progressUi.SetProgress(0, null);
				await RitsuGodotAwaitSafety.AwaitProcessFrameAsync(tree, (GodotObject?)(object)progressUi);
				int done = 0;
				int saved = 0;
				int failed = 0;
				bool userStopped = false;
				if (request.Relics)
				{
					foreach (RelicModel relic in relicList)
					{
						if (CompendiumPngExportSession.IsStopRequested)
						{
							userStopped = true;
							break;
						}
						progressUi.SetProgress(done, ((AbstractModel)relic).Id.Entry);
						string fileName = relicFileStems[((AbstractModel)relic).Id.Entry] + "_relic.png";
						string path = Path.Combine(outDir, fileName);
						if (await TryCaptureRelicWithRetriesAsync(tree, relic, path, scale, includeRelicHover, log, fileName))
						{
							saved++;
							log?.Invoke("Saved " + fileName);
						}
						else
						{
							failed++;
							log?.Invoke($"Could not save {fileName} after {2} attempts.");
						}
						done++;
						progressUi.SetProgress(done, ((AbstractModel)relic).Id.Entry);
						await WaitMainThreadFrames(tree, 1);
					}
				}
				if (!userStopped && request.Potions)
				{
					if (potionList.Count > 0)
					{
						log?.Invoke($"Potion export: processing {potionList.Count} potion(s) from all potion pools.");
					}
					foreach (PotionModel potion in potionList)
					{
						if (CompendiumPngExportSession.IsStopRequested)
						{
							userStopped = true;
							break;
						}
						progressUi.SetProgress(done, ((AbstractModel)potion).Id.Entry);
						string fileName = potionFileStems[((AbstractModel)potion).Id.Entry] + "_potion.png";
						string path2 = Path.Combine(outDir, fileName);
						if (await TryCapturePotionWithRetriesAsync(tree, potion, path2, scale, log, fileName))
						{
							saved++;
							log?.Invoke("Saved " + fileName);
						}
						else
						{
							failed++;
							log?.Invoke($"Could not save {fileName} after {2} attempts.");
						}
						done++;
						progressUi.SetProgress(done, ((AbstractModel)potion).Id.Entry);
						await WaitMainThreadFrames(tree, 1);
					}
				}
				progressUi.SetProgress(Math.Max(1, steps), null);
				await RitsuGodotAwaitSafety.AwaitProcessFrameAsync(tree, (GodotObject?)(object)progressUi);
				log?.Invoke(userStopped ? ModSettingsLocalization.Get("ritsulib.compendiumPngExport.stopped", "Export stopped by user.") : $"Compendium detail export finished. {saved} file(s) saved, {failed} failed. Output: {outDir}");
			}
			finally
			{
				CompendiumPngExportSession.ResetForNewRun();
				progressUi?.Detach();
			}
		}

		private static async Task WaitMainThreadFrames(SceneTree tree, int count)
		{
			await RitsuGodotAwaitSafety.AwaitProcessFramesAsync(tree, count);
		}

		private static async Task<bool> TryCaptureRelicWithRetriesAsync(SceneTree tree, RelicModel relic, string path, float scale, bool includeRelicHover, Action<string>? log, string fileLabel)
		{
			for (int attempt = 1; attempt <= 2; attempt++)
			{
				string prefix = $"[{attempt}/{2}] ";
				if (await TryCaptureRelicAsync(tree, relic, path, scale, includeRelicHover, log, prefix, fileLabel))
				{
					return true;
				}
				if (attempt >= 2)
				{
					break;
				}
				log?.Invoke($"{prefix}Capture failed for {fileLabel}; waiting {8} frames before retry.");
				await WaitMainThreadFrames(tree, 8);
			}
			return false;
		}

		private static async Task<bool> TryCapturePotionWithRetriesAsync(SceneTree tree, PotionModel potion, string path, float scale, Action<string>? log, string fileLabel)
		{
			for (int attempt = 1; attempt <= 2; attempt++)
			{
				string prefix = $"[{attempt}/{2}] ";
				if (await TryCapturePotionAsync(tree, potion, path, scale, log, prefix, fileLabel))
				{
					return true;
				}
				if (attempt >= 2)
				{
					break;
				}
				log?.Invoke($"{prefix}Capture failed for {fileLabel}; waiting {8} frames before retry.");
				await WaitMainThreadFrames(tree, 8);
			}
			return false;
		}

