		private static async Task<bool> TryCaptureRelicAsync(SceneTree tree, RelicModel relic, string absolutePath, float scale, bool includeRelicHover, Action<string>? log, string? logLinePrefix, string logFileTag)
		{
			Control host = new Control
			{
				Name = StringName.op_Implicit("RitsuCompendiumRelicExportHost"),
				Position = new Vector2(-5000f, -5000f)
			};
			bool ok = false;
			try
			{
				_ = 2;
				try
				{
					SubViewport vp = BuildRelicInspectViewport(relic, scale, includeRelicHover, out List<NCard> refList);
					if (vp == null)
					{
						log?.Invoke(logLinePrefix + logFileTag + ": relic inspect build failed (TestMode).");
						return false;
					}
					((Node)host).AddChild((Node)(object)vp, false, (InternalMode)0);
					((Node)NGame.Instance).AddChild((Node)(object)host, false, (InternalMode)0);
					await WaitMainThreadFrames(tree, 2);
					if (GodotObject.IsInstanceValid((GodotObject)(object)host))
					{
						foreach (NCard item in ((IEnumerable<NCard>)refList).Where((Func<NCard, bool>)GodotObject.IsInstanceValid))
						{
							CompendiumDetailPngExportLayout.ApplyRefCardExportVisuals(item);
						}
					}
					await WaitMainThreadFrames(tree, 2);
					ok = await ReadViewportPngAndSaveAsync(host, vp, log, logLinePrefix, logFileTag, tree, absolutePath, RelicInspectMinUnscaledFloor);
				}
				catch (Exception ex)
				{
					log?.Invoke(logLinePrefix + logFileTag + ": " + ex.Message);
				}
			}
			finally
			{
				try
				{
					await WaitMainThreadFrames(tree, 1);
				}
				finally
				{
					if (GodotObject.IsInstanceValid((GodotObject)(object)host))
					{
						DisposeExportHost(host);
					}
				}
				await WaitMainThreadFrames(tree, 2);
			}
			return ok;
		}

