				where !(r is DeprecatedRelic)
				where idFilter == null || ((AbstractModel)r).Id.Entry.Contains(idFilter, StringComparison.OrdinalIgnoreCase)
				select r).OrderBy<RelicModel, string>((RelicModel r) => ((AbstractModel)r).Id.Entry, StringComparer.OrdinalIgnoreCase).ToList();
		}

		private static List<PotionModel> BuildPotionExportList(string? idFilter)
		{
			return (from p in ModelDb.AllPotions
				where !(p is DeprecatedPotion)
				where idFilter == null || ((AbstractModel)p).Id.Entry.Contains(idFilter, StringComparison.OrdinalIgnoreCase)
				group p by ((AbstractModel)p).Id into g
				select g.First()).OrderBy<PotionModel, string>((PotionModel p) => ((AbstractModel)p).Id.Entry, StringComparer.OrdinalIgnoreCase).ToList();
		}

