		public CompendiumPngExportProgressOverlay()
		{
		}

		public static CompendiumPngExportProgressOverlay Attach(Node root, int totalSteps, string title)
		{
			CompendiumPngExportProgressOverlay compendiumPngExportProgressOverlay = new CompendiumPngExportProgressOverlay(totalSteps, title);
			root.AddChild((Node)(object)compendiumPngExportProgressOverlay, false, (InternalMode)0);
			return compendiumPngExportProgressOverlay;
		}

		public void SetProgress(int completedSteps, string? currentId)
		{
			if (_progressBar != null)
			{
				((Range)_progressBar).Value = completedSteps;
				int num = (int)((Range)_progressBar).MaxValue;
				string text = (string.IsNullOrWhiteSpace(currentId) ? "…" : currentId);
				string format = ModSettingsLocalization.Get("ritsulib.compendiumPngExport.progress.count", "{0} / {1}");
				if (_countLabel != null)
				{
					_countLabel.Text = string.Format(format, completedSteps, num);
				}
				if (_nameLabel != null)
				{
					_nameLabel.Text = text;
				}
			}
		}

		public void Detach()
		{
			if (GodotObject.IsInstanceValid((GodotObject)(object)this))
			{
				((Node)this).QueueFree();
			}
		}

