					7 => CompleteCurrentArgument(new global::<>z__ReadOnlyArray<string>(new string[5] { "1", "2", "3", "5", "10" }), args, (CompletionType)2), 
					8 => CompletePlayerIndex(player, args), 
					_ => ((AbstractConsoleCmd)this).GetArgumentCompletions(player, args), 
				});
			}
			return CompleteCardLocationArguments(player, args, -1);
		}

		private CompletionResult CompleteUpgradeCardArguments(Player? player, string[] args)
		{
			int num = args.Length;
			if (num > 5)
			{
				return (CompletionResult)(num switch
				{
					6 => CompleteCurrentArgument(new global::<>z__ReadOnlyArray<string>(new string[3] { "1", "2", "3" }), args, (CompletionType)2), 
					7 => CompletePlayerIndex(player, args), 
					_ => ((AbstractConsoleCmd)this).GetArgumentCompletions(player, args), 
				});
			}
			return CompleteCardLocationArguments(player, args, -1);
		}

		private CompletionResult CompleteEventArguments(Player? player, string[] args)
		{
			switch (args.Length)
			{
			case 3:
				return CompleteModelIds<EventModel>(ModelDb.AllEvents.Concat((IEnumerable<EventModel>)ModelDb.AllAncients).DistinctBy((EventModel model) => ((AbstractModel)model).Id), args);
			case 4:
			{
				if (player == null || !RitsuDebugRunActions.TryResolveEvent(DevConsoleAutocompleteDisplay.StripLocalizedSuffix(args[2]), out EventModel eventModel, out RitsuDebugActionFeedback _))
				{
					break;
				}
				AncientEventModel val = (AncientEventModel)(object)((eventModel is AncientEventModel) ? eventModel : null);
				if (val != null)
				{
					IEnumerable<string> candidates = ((IPlayerCollection)player.RunState).Players.SelectMany((Player target) => GetAvailableAncientOptionTokens(val, target)).Distinct<string>(StringComparer.OrdinalIgnoreCase);
					return CompleteCurrentArgument(candidates, args, (CompletionType)2);
				}
				break;
			}
			case 5:
				return CompletePlayerIndex(player, args);
			}
			return ((AbstractConsoleCmd)this).GetArgumentCompletions(player, args);
			static IEnumerable<string> GetAvailableAncientOptionTokens(AncientEventModel ancient, Player target)
			{
				if (!RitsuDebugRunActions.TryGetAvailableAncientOptions(ancient, target, out EventOption[] options, out RitsuDebugActionFeedback _))
				{
					return Array.Empty<string>();
				}
				return options.Select(RitsuDebugRunActions.GetAncientOptionToken);
			}
		}

		private CompletionResult CompleteModelIds<TModel>(IEnumerable<TModel> models, string[] args) where TModel : AbstractModel
		{
			CompletionResult result = ((AbstractConsoleCmd)this).CompleteArgument(models.Select((TModel model) => ((AbstractModel)model).Id.Entry), args.Take(args.Length - 1).ToArray(), args[^1], (CompletionType)2, DevConsoleAutocompleteMatchExtensions.WithLocalizedModelTitleMatch());
			DevConsoleAutocompleteMatchExtensions.ApplyLocalizedDisplayLabels(ref result);
			return result;
		}

		private CompletionResult CompletePlayerIndex(Player? player, string[] args)
		{
			object obj = ((player != null) ? ((IPlayerCollection)player.RunState).Players : null);
			if (obj == null)
			{
				RunManager instance = RunManager.Instance;
				if (instance == null)
				{
					obj = null;
				}
				else
				{
					RunState obj2 = instance.DebugOnlyGetState();
					obj = ((obj2 != null) ? obj2.Players : null);
				}
				if (obj == null)
				{
					obj = Array.Empty<Player>();
				}
			}
			IReadOnlyList<Player> readOnlyList = (IReadOnlyList<Player>)obj;
			return CompleteCurrentArgument(from value in Enumerable.Range(0, readOnlyList.Count)
				select value.ToString(), args, (CompletionType)2);
		}

		private static bool TryResolveCardLocation(Player issuingPlayer, string[] args, int pileArgumentIndex, int cardIndexArgumentIndex, int playerArgumentIndex, out Player target, out PileType pileType, out int cardIndex, out string expectedCardId, out RitsuDebugActionFeedback feedback)
		{
			target = issuingPlayer;
			pileType = (PileType)0;
			cardIndex = 0;
			expectedCardId = string.Empty;
			if (!RitsuDebugCardActions.TryParseMutablePileType(args[pileArgumentIndex], out pileType))
			{
				feedback = RitsuDebugActionFeedback.Create("card.unsupportedPile", "Unsupported pile '{0}'.", args[pileArgumentIndex]);
				return false;
			}
			if (!int.TryParse(args[cardIndexArgumentIndex], out cardIndex))
			{
				feedback = RitsuDebugActionFeedback.Create("console.cardIndexInteger", "Card index must be an int, got '{0}'.", args[cardIndexArgumentIndex]);
				return false;
			}
			if (!TryResolveTargetPlayer(issuingPlayer, args, playerArgumentIndex, out target, out feedback))
			{
				return false;
			}
			CardPile pile = RitsuDebugCardActions.GetPile(target, pileType);
			if (pile == null || cardIndex < 0 || cardIndex >= pile.Cards.Count)
			{
				feedback = RitsuDebugActionFeedback.Create("console.cardIndexInvalid", "Card index {0} is invalid for {1}.", cardIndex, pileType);
				return false;
			}
			expectedCardId = ((object)((AbstractModel)pile.Cards[cardIndex]).Id).ToString();
			feedback = default(RitsuDebugActionFeedback);
			return true;
		}

		private static bool TryGetCardAt(Player player, string pileInput, string indexInput, out CardModel card)
		{
			//IL_001a: Unknown result type (might be due to invalid IL or missing references)
			card = null;
			if (!RitsuDebugCardActions.TryParseMutablePileType(pileInput, out var pileType) || !int.TryParse(indexInput, out var result))
			{
				return false;
			}
			CardPile pile = RitsuDebugCardActions.GetPile(player, pileType);
			if (pile == null || result < 0 || result >= pile.Cards.Count)
			{
				return false;
			}
			card = pile.Cards[result];
			return true;
		}

		private static bool TryParseCardEditField(string input, out RitsuDebugCardEditField field)
		{
			field = input.ToLowerInvariant() switch
			{
				"cost" => RitsuDebugCardEditField.Cost, 
				"exhaust" => RitsuDebugCardEditField.Exhaust, 
				"ethereal" => RitsuDebugCardEditField.Ethereal, 
				"unplayable" => RitsuDebugCardEditField.Unplayable, 
				"dynamic-var" => RitsuDebugCardEditField.DynamicVar, 
				_ => (RitsuDebugCardEditField)(-1), 
			};
			return Enum.IsDefined(field);
		}

		private static string[] GetCardEditFieldNames()
		{
			return new string[5] { "cost", "exhaust", "ethereal", "unplayable", "dynamic-var" };
		}

		private CompletionResult CompleteCurrentArgument(IEnumerable<string> candidates, string[] args, CompletionType completionType = (CompletionType)2)
		{
			//IL_0019: Unknown result type (might be due to invalid IL or missing references)
			return ((AbstractConsoleCmd)this).CompleteArgument(candidates, args.Take(args.Length - 1).ToArray(), args[^1], completionType, (Func<string, string, bool>)null);
		}

		private static bool TryResolveTargetPlayer(Player issuingPlayer, string[] args, int argumentIndex, out Player target, out RitsuDebugActionFeedback feedback)
		{
			target = issuingPlayer;
			feedback = default(RitsuDebugActionFeedback);
			if (args.Length <= argumentIndex)
			{
				return true;
			}
			if (!int.TryParse(args[argumentIndex], out var result))
			{
				feedback = RitsuDebugActionFeedback.Create("console.targetPlayerIndexInteger", "Target player index must be an int, got '{0}'.", args[argumentIndex]);
				return false;
			}
			IReadOnlyList<Player> players = ((IPlayerCollection)issuingPlayer.RunState).Players;
			if (result < 0 || result >= players.Count)
			{
				feedback = RitsuDebugActionFeedback.Create("console.targetPlayerIndexRange", "Target player index {0} is outside the valid range 0-{1}.", result, players.Count - 1);
				return false;
			}
			target = players[result];
			return true;
		}

		private static CmdResult ToCmdResult(RitsuDebugActionSubmission submission)
		{
			//IL_000e: Unknown result type (might be due to invalid IL or missing references)
			return new CmdResult(submission.Accepted, submission.Message);
		}

		private static CmdResult DebugFailure(RitsuDebugActionFeedback feedback)
