			return new CmdResult(false, feedback.GetLocalizedText());
		}

		private static CmdResult DebugFailure(string code, string fallback, params object?[] arguments)
		{
			//IL_0008: Unknown result type (might be due to invalid IL or missing references)
			return DebugFailure(RitsuDebugActionFeedback.Create(code, fallback, arguments));
		}

		private static string DebugUsageText()
		{
			return string.Format(ModSettingsLocalization.Get("ritsulib.debugTools.feedback.console.usage", "Usage: ritsulib debug <{0}> ...; use console completion to list actions and arguments."), string.Join('|', DebugConsoleGroups.Select((DebugConsoleGroup group) => group.Name)));
		}

		/// <inheritdoc />
		public override CompletionResult GetArgumentCompletions(Player? player, string[] args)
		{
			if (args.Length <= 1)
			{
				string text = ((args.Length == 0) ? string.Empty : args[0]);
				return ((AbstractConsoleCmd)this).CompleteArgument((IEnumerable<string>)GetRootCommands(), Array.Empty<string>(), text, (CompletionType)1, (Func<string, string, bool>)null);
			}
			if (args[0].Equals("debug", StringComparison.OrdinalIgnoreCase))
			{
				if (!RitsuLibSettingsStore.AreDeveloperToolsEnabled())
				{
					return ((AbstractConsoleCmd)this).GetArgumentCompletions(player, args);
				}
				return CompleteDebugArguments(player, args);
			}
			if (args[0].Equals("settings", StringComparison.OrdinalIgnoreCase))
			{
				return CompleteSettingsArguments(args);
			}
			if (!args[0].Equals("selfcheck", StringComparison.OrdinalIgnoreCase))
			{
				return ((AbstractConsoleCmd)this).GetArgumentCompletions(player, args);
			}
			string[] array = args.Take(args.Length - 1).ToArray();
			string text2 = args[^1];
			return ((AbstractConsoleCmd)this).CompleteArgument((IEnumerable<string>)SelfCheckActions, array, text2, (CompletionType)2, (Func<string, string, bool>)null);
		}

		/// <inheritdoc />
		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			//IL_000a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0057: Unknown result type (might be due to invalid IL or missing references)
			//IL_0042: Unknown result type (might be due to invalid IL or missing references)
			//IL_0039: Unknown result type (might be due to invalid IL or missing references)
			//IL_0077: Unknown result type (might be due to invalid IL or missing references)
			//IL_00bd: Unknown result type (might be due to invalid IL or missing references)
			//IL_009b: Unknown result type (might be due to invalid IL or missing references)
			//IL_00cb: Unknown result type (might be due to invalid IL or missing references)
			if (args.Length == 0)
			{
				return new CmdResult(false, UsageText());
			}
			string text = args[0];
			if (text.Equals("debug", StringComparison.OrdinalIgnoreCase))
			{
				if (!RitsuLibSettingsStore.AreDeveloperToolsEnabled())
				{
					return new CmdResult(false, ModSettingsLocalization.Get("ritsulib.debugTools.feedback.protocol.toolsDisabled", "RitsuLib developer tools are disabled in settings."));
				}
				return ProcessDebug(issuingPlayer, args);
			}
			if (text.Equals("settings", StringComparison.OrdinalIgnoreCase))
			{
				return ProcessSettings(args);
			}
			if (!text.Equals("selfcheck", StringComparison.OrdinalIgnoreCase) || args.Length < 2)
			{
				return new CmdResult(false, UsageText());
			}
			string message;
			if (args.Length == 2 && args[1].Equals("run", StringComparison.OrdinalIgnoreCase))
			{
				return new CmdResult(SelfCheckBundleCoordinator.TryManualRunFromConsole(out message), message);
			}
			if (args.Length != 2 || !args[1].Equals("open-output", StringComparison.OrdinalIgnoreCase))
			{
				return new CmdResult(false, UsageText());
			}
			string message2;
			return new CmdResult(SelfCheckBundleCoordinator.TryOpenOutputFolderFromSettings(out message2), message2);
		}

		private static CmdResult ProcessSettings(string[] args)
		{
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_0052: Unknown result type (might be due to invalid IL or missing references)
			if (args.Length < 3 || args.Length > 6 || !args[1].Equals("open", StringComparison.OrdinalIgnoreCase))
			{
				return new CmdResult(false, UsageText());
			}
			ModSettingsOpenResult modSettingsOpenResult = ModSettingsNavigator.RequestOpenByIds(args[2], GetOptionalArg(args, 3), GetOptionalArg(args, 4), GetOptionalArg(args, 5));
			return new CmdResult(modSettingsOpenResult.Success, modSettingsOpenResult.Message);
		}

		private CompletionResult CompleteSettingsArguments(string[] args)
		{
			string text = args[^1];
			string[] array = args.Take(args.Length - 1).ToArray();
			if (args.Length <= 2)
			{
				return ((AbstractConsoleCmd)this).CompleteArgument((IEnumerable<string>)SettingsActions, array, text, (CompletionType)1, (Func<string, string, bool>)null);
			}
			if (!args[1].Equals("open", StringComparison.OrdinalIgnoreCase))
			{
				return ((AbstractConsoleCmd)this).GetArgumentCompletions((Player)null, args);
			}
			return (CompletionResult)(args.Length switch
			{
				3 => ((AbstractConsoleCmd)this).CompleteArgument((IEnumerable<string>)GetModIdCandidates(), array, text, (CompletionType)2, (Func<string, string, bool>)null), 
				4 => ((AbstractConsoleCmd)this).CompleteArgument((IEnumerable<string>)GetPageIdCandidates(args[2]), array, text, (CompletionType)2, (Func<string, string, bool>)null), 
				5 => ((AbstractConsoleCmd)this).CompleteArgument((IEnumerable<string>)GetSectionIdCandidates(args[2], args[3]), array, text, (CompletionType)2, (Func<string, string, bool>)null), 
				6 => ((AbstractConsoleCmd)this).CompleteArgument((IEnumerable<string>)GetEntryIdCandidates(args[2], args[3], args[4]), array, text, (CompletionType)2, (Func<string, string, bool>)null), 
				_ => ((AbstractConsoleCmd)this).GetArgumentCompletions((Player)null, args), 
			});
		}

		private static string? GetOptionalArg(string[] args, int index)
		{
			if (args.Length > index && !string.IsNullOrWhiteSpace(args[index]))
			{
				return args[index];
			}
			return null;
		}

		private static string UsageText()
		{
			if (!RitsuLibSettingsStore.AreDeveloperToolsEnabled())
			{
				return "Usage: ritsulib selfcheck run|open-output OR ritsulib settings open <modId> [pageId] [sectionId] [entryId]";
			}
			return "Usage: ritsulib selfcheck run|open-output OR ritsulib settings open <modId> [pageId] [sectionId] [entryId] OR ritsulib debug <group> ...";
		}

		private static string[] GetRootCommands()
		{
			if (!RitsuLibSettingsStore.AreDeveloperToolsEnabled())
			{
				return StandardRootCommands;
			}
			string[] standardRootCommands = StandardRootCommands;
			int num = 0;
			string[] array = new string[1 + standardRootCommands.Length];
			ReadOnlySpan<string> readOnlySpan = new ReadOnlySpan<string>(standardRootCommands);
			readOnlySpan.CopyTo(new Span<string>(array).Slice(num, readOnlySpan.Length));
			num += readOnlySpan.Length;
			array[num] = "debug";
			return array;
		}

		private static string[] GetModIdCandidates()
		{
			RefreshSettingsPagesForCompletion();
			return (from page in ModSettingsRegistry.GetPages().Where(ModSettingsVisibility.IsPageVisible)
				select page.ModId).Distinct<string>(StringComparer.OrdinalIgnoreCase).Order<string>(StringComparer.OrdinalIgnoreCase).ToArray();
		}

		private static string[] GetPageIdCandidates(string modId)
		{
			RefreshSettingsPagesForCompletion();
			return (from page in (from page in ModSettingsRegistry.GetPages()
					where string.Equals(page.ModId, modId, StringComparison.OrdinalIgnoreCase)
					select page).Where(ModSettingsVisibility.IsPageVisible)
				select page.Id).Order<string>(StringComparer.OrdinalIgnoreCase).ToArray();
		}

		private static string[] GetSectionIdCandidates(string modId, string pageId)
		{
			RefreshSettingsPagesForCompletion();
			if (!ModSettingsRegistry.TryGetPage(modId, pageId, out ModSettingsPage page) || page == null || !ModSettingsVisibility.IsPageVisible(page))
			{
				return Array.Empty<string>();
			}
			return (from section in page.Sections
				where ModSettingsVisibility.IsSectionVisible(page, section)
				select section.Id).Order<string>(StringComparer.OrdinalIgnoreCase).ToArray();
		}

		private static string[] GetEntryIdCandidates(string modId, string pageId, string sectionId)
		{
			RefreshSettingsPagesForCompletion();
			if (!ModSettingsRegistry.TryGetPage(modId, pageId, out ModSettingsPage page) || page == null || !ModSettingsVisibility.IsPageVisible(page))
			{
				return Array.Empty<string>();
			}
			ModSettingsSection modSettingsSection = page.Sections.FirstOrDefault((ModSettingsSection s) => string.Equals(s.Id, sectionId, StringComparison.OrdinalIgnoreCase));
			if (modSettingsSection != null && ModSettingsVisibility.IsSectionVisible(page, modSettingsSection))
			{
				return (from entry in modSettingsSection.Entries
					where ModSettingsVisibility.IsEntryVisible(page, entry)
					select entry.Id).Order<string>(StringComparer.OrdinalIgnoreCase).ToArray();
			}
			return Array.Empty<string>();
		}

		private static void RefreshSettingsPagesForCompletion()
		{
			try
			{
				RitsuLibModSettingsBootstrap.EnsureFrameworkPagesRegistered();
				ModSettingsMirrorRegistrarBootstrap.TryRegisterMirroredPages();
				RitsuLibModSettingsBootstrap.RefreshDynamicPages();
			}
			catch (Exception ex) when (RitsuLibExceptionPolicy.IsRecoverable(ex))
			{
				RitsuLibFramework.Logger.Warn($"[Settings] Could not refresh console completion data: {ex}", 1);
			}
		}
	}
}
namespace STS2RitsuLib.Diagnostics.CardExport
{
	/// <summary>
	///     <para xml:lang="en">
	///         Specifies which surrounding interface elements to include when rendering a card to PNG.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         指定将卡牌渲染为 PNG 时包含哪些周边界面元素。
	///     </para>
	/// </summary>
	public enum CardPngExportCaptureMode
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Includes only the <c>NCard</c> control, preserving the game's card frame, portrait, and text.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         仅包含 <c>NCard</c> 控件，并保留游戏中的卡牌边框、图像和文本。
		///     </para>
		/// </summary>
		CardOnly,
		/// <summary>
		///     <para xml:lang="en">
		///         Includes the card and fixed hover-tip columns. Text tips use <c>hover_tip.tscn</c>, while referenced
		///         cards use scaled <c>NCard</c> controls.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         包含卡牌和固定布局的悬停提示列。文本提示使用 <c>hover_tip.tscn</c>，引用的卡牌则使用缩放后的
		///         <c>NCard</c> 控件。
		///     </para>
		/// </summary>
		CardWithHoverTipsPanel
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Batch-exports registered cards through offscreen <see cref="T:MegaCrit.Sts2.Core.Nodes.Cards.NCard" /> instances; it uses library
	///         models and does not require an active run. Each capture attempt releases its temporary scene subtree
	///         in a <c>finally</c> path, including after capture or frame-wait failures.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         通过离屏 <see cref="T:MegaCrit.Sts2.Core.Nodes.Cards.NCard" /> 实例批量导出已注册卡牌；使用卡牌库模型，无需存在进行中的一局游戏。每次捕获尝试都会在
	///         <c>finally</c> 路径中释放临时场景子树，包括捕获或等待帧失败后。
	///     </para>
	/// </summary>
	public static class CardPngExporter
	{
		private sealed class BuiltCaptureViewport
		{
			public required SubViewport Viewport { get; init; }

			public required Control Root { get; init; }

			public ColorRect? Background { get; init; }

			public HBoxContainer? HoverRow { get; init; }

			public NCard? MainCard { get; init; }

			public required List<NCard> RefHoverTipCards { get; init; }

			public int CardWidth { get; init; }

			public int CardHeight { get; init; }
		}

		private const float HoverTipTargetWidth = 360f;

		private const float HoverTipVerticalGap = 5f;

		private const string HoverTipScenePath = "res://scenes/ui/hover_tip.tscn";

		private const string CardHoverTipScenePath = "res://scenes/ui/card_hover_tip.tscn";

		private const string HoverTipDebuffMaterialPath = "res://materials/ui/hover_tip_debuff.tres";

		private const int HoverRowColumnSeparation = 0;

		private const int RefCardHoverTipVerticalGap = 4;

		private const float CardHoverTipSceneCardScale = 0.75f;

		private const float CardExportHalfExtentX = 190f;

		private const float CardExportHalfExtentY = 240f;

		private const float ExportViewportFramePad = 6f;

		private const int FramesAfterHostAdded = 2;

		private const int FramesAfterSyncVisualApply = 2;

		private const int FramesAfterHoverColumnLayout = 2;

		private const int FramesAfterHoverResize = 2;

		private const int FramesAfterRenderOnce = 5;

		private const int FramesAfterSaveBeforeTeardown = 1;

		private const int FramesFlushBeforeSyncDispose = 1;

		private const int FramesAfterSyncTeardown = 2;

		private const int FramesBetweenCards = 1;

		private const int FramesBetweenVariants = 1;

		private const int FramesBeforeRetry = 8;

		private const int MaxCaptureAttemptsPerFile = 2;

		private const string CardScenePath = "res://scenes/cards/card.tscn";

		private static int _exportInProgress;

		/// <summary>
		///     <para xml:lang="en">Starts the requested batch PNG export when no other card export is running.</para>
		///     <para xml:lang="zh-CN">在没有其他卡牌导出运行时启动请求的批量 PNG 导出。</para>
		/// </summary>
		public static void BeginExport(CardPngExportRequest request, Player? issuingPlayer, Action<string>? log = null)
		{
			//IL_005a: Unknown result type (might be due to invalid IL or missing references)
			//IL_005f: Unknown result type (might be due to invalid IL or missing references)
			if (NGame.Instance == null)
			{
				log?.Invoke("Cannot export: the game is not loaded yet.");
				return;
			}
			if (Interlocked.CompareExchange(ref _exportInProgress, 1, 0) != 0)
			{
				log?.Invoke("Cannot export: another card PNG export is already running.");
				return;
			}
			CardPngExportRequest req = request;
			Player player = issuingPlayer;
			Action<string> lg = log;
			try
			{
				Callable val = Callable.From((Action)delegate
				{
					RunExportOnMainThreadEntry(req, player, lg);
				});
				((Callable)(ref val)).CallDeferred(Array.Empty<Variant>());
			}
			catch
			{
				Volatile.Write(ref _exportInProgress, 0);
				throw;
			}
		}

		private static async void RunExportOnMainThreadEntry(CardPngExportRequest request, Player? issuingPlayer, Action<string>? log)
		{
			try
			{
				await RunExportAsync(request, issuingPlayer, log);
			}
			catch (Exception ex)
			{
				log?.Invoke("Export stopped: " + ex.Message);
				GD.PushError($"Card PNG export: {ex}");
			}
			finally
			{
				Volatile.Write(ref _exportInProgress, 0);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Checks whether the game is loaded and card preview nodes can be instantiated.</para>
		///     <para xml:lang="zh-CN">检查游戏是否已加载且能实例化卡牌预览节点。</para>
		/// </summary>
		public static bool TryValidateExportEnvironment(out string error)
		{
			if (NGame.Instance == null)
			{
				error = "Game is not ready. Open the main menu or enter a run, then try again.";
				return false;
			}
			if (TestMode.IsOn)
			{
				error = "Card preview cannot be created in this session.";
				return false;
			}
			error = "";
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Provides the backward-compatible validation entry point. It always sets <paramref name="runState" />
		///         and <paramref name="player" /> to <see langword="null" />; new code should call
		///         <see cref="M:STS2RitsuLib.Diagnostics.CardExport.CardPngExporter.TryValidateExportEnvironment(System.String@)" /> instead.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         提供向后兼容的验证入口。它始终将 <paramref name="runState" /> 和 <paramref name="player" /> 设为
		///         <see langword="null" />；新代码应改用 <see cref="M:STS2RitsuLib.Diagnostics.CardExport.CardPngExporter.TryValidateExportEnvironment(System.String@)" />。
		///     </para>
		/// </summary>
		public static bool TryResolveContext(Player? _, out RunState? runState, out Player? player, out string error)
		{
			runState = null;
			player = null;
			return TryValidateExportEnvironment(out error);
		}

		private static async Task RunExportAsync(CardPngExportRequest request, Player? _, Action<string>? log)
		{
			if (!TryValidateExportEnvironment(out string error))
			{
				log?.Invoke(error);
				return;
			}
			if (string.IsNullOrWhiteSpace(request.OutputDirectory))
			{
				log?.Invoke("Cannot export: choose an output folder.");
				return;
			}
			if (!float.IsFinite(request.Scale))
			{
				log?.Invoke("Cannot export: scale must be a finite number.");
				return;
			}
			if (!Enum.IsDefined(request.CaptureMode))
			{
				log?.Invoke($"Cannot export: capture mode '{request.CaptureMode}' is not supported.");
				return;
			}
			float scale = Mathf.Max(0.25f, request.Scale);
			string outDir = ProjectSettings.GlobalizePath(request.OutputDirectory.Trim());
			try
			{
				Directory.CreateDirectory(outDir);
			}
			catch (Exception ex)
			{
				log?.Invoke("Could not create output folder: " + ex.Message);
				return;
			}
			SceneTree tree = ((Node)NGame.Instance).GetTree();
			if (tree == null)
			{
				log?.Invoke("Scene tree is not available.");
				return;
			}
			string idFilter = (string.IsNullOrWhiteSpace(request.IdFilterSubstring) ? null : request.IdFilterSubstring.Trim());
			List<CardModel> list = (from c in ModelDb.AllCards
				where !(c is DeprecatedCard)
				where request.IncludeCardsHiddenFromLibrary || c.ShouldShowInCardLibrary
				select c).OrderBy<CardModel, string>((CardModel c) => ((AbstractModel)c).Id.Entry, StringComparer.OrdinalIgnoreCase).ToList();
			List<CardModel> cards = list.Where((CardModel c) => idFilter == null || ((AbstractModel)c).Id.Entry.Contains(idFilter, StringComparison.OrdinalIgnoreCase)).ToList();
			IReadOnlyDictionary<string, string> fileStems = BuildSafeFileStemLookup(list, (CardModel card) => ((AbstractModel)card).Id.Entry, (CardModel card) => (!card.TitleLocString.Exists()) ? "" : card.Title, request.UseLocalizedFileNames, "card");
			int totalSteps = CountTotalExportSteps(cards, request);
			CardPngExportProgressOverlay progressUi = null;
			try
			{
				progressUi = CardPngExportProgressOverlay.Attach((Node)(object)NGame.Instance, totalSteps);
				progressUi.SetProgress(0, null);
				await RitsuGodotAwaitSafety.AwaitProcessFrameAsync(tree, (GodotObject?)(object)progressUi);
				int exportedBase = 0;
				int savedFiles = 0;
				int failures = 0;
				int stepIndex = 0;
				foreach (CardModel canonical in cards.TakeWhile((CardModel val2) => request.MaxBaseCards <= 0 || exportedBase < request.MaxBaseCards))
				{
					try
					{
						progressUi.SetProgress(stepIndex, ((AbstractModel)canonical).Id.Entry);
						string fileStem = fileStems[((AbstractModel)canonical).Id.Entry];
						string baseName = fileStem + "_base.png";
						string absolutePath = Path.Combine(outDir, baseName);
						if (await TryCaptureWithRetriesAsync(tree, canonical, absolutePath, request, scale, log, baseName))
						{
							savedFiles++;
							log?.Invoke("Saved " + baseName);
						}
						else
						{
							failures++;
							log?.Invoke($"Could not save {baseName} after {2} attempts.");
						}
						exportedBase++;
						stepIndex++;
						progressUi.SetProgress(stepIndex, ((AbstractModel)canonical).Id.Entry);
						if (request.IncludeUpgradedVariants && canonical.IsUpgradable)
						{
							await WaitMainThreadFrames(tree, 1);
							CardModel val = canonical.ToMutable();
							val.UpgradeInternal();
							string upName = fileStem + "_upgraded.png";
							string absolutePath2 = Path.Combine(outDir, upName);
							progressUi.SetProgress(stepIndex, ((AbstractModel)canonical).Id.Entry + " (upgraded)");
							if (await TryCaptureWithRetriesAsync(tree, val, absolutePath2, request, scale, log, upName))
							{
								savedFiles++;
								log?.Invoke("Saved " + upName);
							}
							else
							{
								failures++;
								log?.Invoke($"Could not save {upName} after {2} attempts.");
							}
							stepIndex++;
							progressUi.SetProgress(stepIndex, ((AbstractModel)canonical).Id.Entry);
						}
					}
					catch (Exception ex2)
					{
						failures++;
						log?.Invoke(((AbstractModel)canonical).Id.Entry + ": " + ex2.Message);
					}
					await WaitMainThreadFrames(tree, 1);
				}
				progressUi.SetProgress(totalSteps, null);
				await RitsuGodotAwaitSafety.AwaitProcessFrameAsync(tree, (GodotObject?)(object)progressUi);
				log?.Invoke($"Finished. {savedFiles} file(s) saved, {failures} failed. Base cards: {exportedBase}. Output: {outDir}");
			}
			finally
			{
				progressUi?.Detach();
			}
		}

		private static int CountTotalExportSteps(IReadOnlyList<CardModel> cards, CardPngExportRequest request)
		{
			int num = 0;
			int num2 = 0;
			foreach (CardModel card in cards)
			{
				if (request.MaxBaseCards > 0 && num2 >= request.MaxBaseCards)
				{
					break;
				}
				num++;
				num2++;
				if (request.IncludeUpgradedVariants && card.IsUpgradable)
				{
					num++;
				}
			}
			return Math.Max(1, num);
		}

		private static async Task WaitMainThreadFrames(SceneTree tree, int count)
		{
			await RitsuGodotAwaitSafety.AwaitProcessFramesAsync(tree, count);
		}

		private static async Task<bool> TryCaptureWithRetriesAsync(SceneTree tree, CardModel card, string absolutePath, CardPngExportRequest request, float scale, Action<string>? log, string fileLabel)
		{
			for (int attempt = 1; attempt <= 2; attempt++)
			{
				string prefix = $"[{attempt}/{2}] ";
				if (await TryCaptureAsync(tree, card, absolutePath, request, scale, log, prefix, fileLabel))
				{
					return true;
				}
				if (attempt >= 2)
				{
					break;
				}
				log?.Invoke($"{prefix}Capture failed for {fileLabel}; waiting {8} frames before retry.");
				await WaitMainThreadFrames(tree, 8);
			}
			return false;
		}

		private static async Task<bool> TryCaptureAsync(SceneTree tree, CardModel card, string absolutePath, CardPngExportRequest request, float scale, Action<string>? log, string? logLinePrefix, string logFileTag)
		{
			Control host = new Control
			{
				Name = StringName.op_Implicit("RitsuCardPngExportHost"),
				Position = new Vector2(-5000f, -5000f)
			};
			bool ok = false;
			try
			{
				_ = 5;
				try
				{
					BuiltCaptureViewport viewportBuilt = BuildCaptureViewport(card, request, scale);
					((Node)host).AddChild((Node)(object)viewportBuilt.Viewport, false, (InternalMode)0);
					((Node)NGame.Instance).AddChild((Node)(object)host, false, (InternalMode)0);
					await WaitMainThreadFrames(tree, 2);
					if (GodotObject.IsInstanceValid((GodotObject)(object)host))
					{
						ApplyAllExportCardVisuals(viewportBuilt);
					}
					await WaitMainThreadFrames(tree, 2);
					if (viewportBuilt.HoverRow != null && GodotObject.IsInstanceValid((GodotObject)(object)viewportBuilt.HoverRow))
					{
						HBoxContainer hoverRow = viewportBuilt.HoverRow;
						if (GodotObject.IsInstanceValid((GodotObject)(object)hoverRow))
						{
							((Container)hoverRow).QueueSort();
						}
					}
					await WaitMainThreadFrames(tree, 2);
					if (viewportBuilt.HoverRow != null && GodotObject.IsInstanceValid((GodotObject)(object)viewportBuilt.HoverRow))
					{
						ResizeViewportToHoverRow(viewportBuilt);
					}
					await WaitMainThreadFrames(tree, 2);
					if (GodotObject.IsInstanceValid((GodotObject)(object)viewportBuilt.Viewport))
					{
						viewportBuilt.Viewport.RenderTargetUpdateMode = (UpdateMode)1;
						await WaitMainThreadFrames(tree, 5);
						if (GodotObject.IsInstanceValid((GodotObject)(object)viewportBuilt.Viewport))
						{
							ViewportTexture texture = ((Viewport)viewportBuilt.Viewport).GetTexture();
							if (texture != null)
							{
								Image imageFromTex = ((Texture2D)texture).GetImage();
								try
								{
									if (imageFromTex != null)
									{
										Resource obj = ((Resource)imageFromTex).Duplicate(false);
										Image image = (Image)(object)((obj is Image) ? obj : null);
										try
										{
											if (image != null)
											{
												Error val = image.SavePng(absolutePath);
												ok = (long)val == 0;
												if (ok)
												{
													await WaitMainThreadFrames(tree, 1);
												}
												else
												{
													log?.Invoke($"{logLinePrefix}{logFileTag}: SavePng failed ({val}, code {(int)val}).");
												}
											}
											else
											{
												log?.Invoke(logLinePrefix + logFileTag + ": duplicate image was null.");
											}
										}
										finally
										{
											((IDisposable)image)?.Dispose();
										}
									}
									else
									{
										log?.Invoke(logLinePrefix + logFileTag + ": viewport image was null.");
									}
								}
								finally
								{
									((IDisposable)imageFromTex)?.Dispose();
								}
							}
							else
							{
								log?.Invoke(logLinePrefix + logFileTag + ": viewport texture was null.");
							}
						}
						else
						{
							log?.Invoke(logLinePrefix + logFileTag + ": viewport became invalid before reading pixels.");
						}
					}
					else
					{
						log?.Invoke(logLinePrefix + logFileTag + ": viewport was freed before capture.");
					}
				}
				catch (Exception ex)
				{
					log?.Invoke(logLinePrefix + logFileTag + ": " + ex.Message);
					ok = false;
				}
			}
			finally
			{
				try
				{
					await WaitMainThreadFrames(tree, 1);
				}
				finally
				{
					if (GodotObject.IsInstanceValid((GodotObject)(object)host))
					{
						DisposeExportHost(host);
					}
				}
				await WaitMainThreadFrames(tree, 2);
			}
			return ok;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Frees a capture subtree built exclusively from non-pooled <see cref="T:MegaCrit.Sts2.Core.Nodes.Cards.NCard" /> instances. Export
		///         never uses <see cref="M:MegaCrit.Sts2.Core.Nodes.Cards.NCard.Create(MegaCrit.Sts2.Core.Models.CardModel,MegaCrit.Sts2.Core.Entities.UI.ModelVisibility)" /> or <c>NodePool</c>, so teardown cannot race the in-game card
		///         pool.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         释放仅由非池化 <see cref="T:MegaCrit.Sts2.Core.Nodes.Cards.NCard" /> 实例构成的捕获子树。导出从不使用 <see cref="M:MegaCrit.Sts2.Core.Nodes.Cards.NCard.Create(MegaCrit.Sts2.Core.Models.CardModel,MegaCrit.Sts2.Core.Entities.UI.ModelVisibility)" /> 或
		///         <c>NodePool</c>，因此拆卸不会与游戏内卡牌池发生竞争。
		///     </para>
		/// </summary>
		private static void DisposeExportHost(Control host)
		{
			if (!GodotObject.IsInstanceValid((GodotObject)(object)host))
			{
				return;
			}
			Node parent = ((Node)host).GetParent();
			if (parent != null)
			{
				GodotTreeExtensions.RemoveChildSafely(parent, (Node)(object)host);
			}
			List<Node> postOrder = new List<Node>();
			CollectPostOrder((Node)(object)host);
			foreach (Node item in ((IEnumerable<Node>)postOrder).Where((Func<Node, bool>)GodotObject.IsInstanceValid))
			{
				NCard val = (NCard)(object)((item is NCard) ? item : null);
				if (val != null)
				{
					GodotTreeExtensions.QueueFreeSafelyNoPool((Node)(object)val);
				}
				else
				{
					GodotTreeExtensions.QueueFreeSafelyNoPool(item);
				}
			}
			void CollectPostOrder(Node n)
			{
				foreach (Node child in n.GetChildren(false))
				{
					CollectPostOrder(child);
				}
				postOrder.Add(n);
			}
		}

