			foreach (NCard item in ((IEnumerable<NCard>)built.RefHoverTipCards).Where((Func<NCard, bool>)GodotObject.IsInstanceValid))
			{
				ApplyCardLibraryStyleExportVisuals(item, (PileType)6);
			}
		}

