		internal static string BuildSafeFileStem(string entry, string fallback)
		{
			string text = Path.GetInvalidFileNameChars().Aggregate(entry, (string current, char character) => current.Replace(character, '_')).TrimEnd(new char[2] { ' ', '.' });
			if (string.IsNullOrEmpty(text))
			{
				text = fallback;
			}
			if (string.Equals(text, entry, StringComparison.Ordinal))
			{
				return text;
			}
			string text2 = BuildStableDigest(entry);
			return text + "-" + text2;
		}

		internal static IReadOnlyDictionary<string, string> BuildSafeFileStemLookup<T>(IReadOnlyList<T> models, Func<T, string> getEntry, Func<T, string> getLocalizedTitle, bool useLocalizedFileNames, string fallback)
		{
			(string, string)[] source = models.Select(delegate(T model)
			{
				string text = getEntry(model);
				string text2 = text;
				try
				{
					if (useLocalizedFileNames)
					{
						text2 = getLocalizedTitle(model);
					}
				}
				catch (Exception exception) when (RitsuLibExceptionPolicy.IsRecoverable(exception))
				{
					text2 = text;
				}
				string entry = (string.IsNullOrWhiteSpace(text2) ? text : text2.Trim());
				return (Entry: text, Stem: BuildSafeFileStem(entry, fallback));
			}).ToArray();
			HashSet<string> duplicateStems = (from @group in source.GroupBy<(string, string), string>(((string Entry, string Stem) value) => value.Stem, StringComparer.OrdinalIgnoreCase)
				where @group.Count() > 1
				select @group.Key).ToHashSet<string>(StringComparer.OrdinalIgnoreCase);
			return source.ToDictionary<(string, string), string, string>(((string Entry, string Stem) value) => value.Entry, ((string Entry, string Stem) value) => (!duplicateStems.Contains(value.Stem)) ? value.Stem : (value.Stem + "-" + BuildStableDigest(value.Entry)), StringComparer.Ordinal);
		}

		private static string BuildStableDigest(string value)
		{
			return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).Substring(0, 12).ToLowerInvariant();
		}
	}
