	/// <summary>
	///     <para xml:lang="en">
	///         Specifies options for exporting <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> instances to PNG.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         指定将 <see cref="T:MegaCrit.Sts2.Core.Models.CardModel" /> 实例批量导出为 PNG 的选项。
	///     </para>
	/// </summary>
	public readonly struct CardPngExportRequest
	{
		/// <summary>
		///     <para xml:lang="en">
		///         The absolute or Godot <c>user://</c> or <c>res://</c> output directory. Invalid filename characters
		///         in card IDs are replaced.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         绝对路径或 Godot <c>user://</c>、<c>res://</c> 输出目录。卡牌 ID 中不适用于文件名的字符会被替换。
		///     </para>
		/// </summary>
		public string OutputDirectory { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         The uniform scale applied to the card and surrounding layout. Values below <c>1</c> shrink the
		///         output; values above <c>1</c> enlarge it.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         应用于卡牌及周边布局的统一缩放比例。小于 <c>1</c> 时缩小，大于 <c>1</c> 时放大。
		///     </para>
		/// </summary>
		public float Scale { get; init; }

		/// <summary>
		///     <para xml:lang="en">The capture mode.</para>
		///     <para xml:lang="zh-CN">捕获模式。</para>
		/// </summary>
		public CardPngExportCaptureMode CaptureMode { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Whether to export an additional <c>_upgraded</c> PNG for each upgradable card.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         是否为每张可升级卡牌额外导出一个 <c>_upgraded</c> PNG。
		///     </para>
		/// </summary>
		public bool IncludeUpgradedVariants { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         An optional case-insensitive substring filter applied to
		///         <see cref="P:MegaCrit.Sts2.Core.Models.ModelId.Entry" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         可选的忽略大小写子字符串筛选条件，应用于
		///         <see cref="P:MegaCrit.Sts2.Core.Models.ModelId.Entry" />。
		///     </para>
		/// </summary>
		public string? IdFilterSubstring { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         The maximum number of base cards to export when positive. Upgraded variants do not count toward this
		///         limit.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为正数时表示最多导出的基础卡牌数；升级版本不计入此限制。
		///     </para>
		/// </summary>
		public int MaxBaseCards { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Whether to include registered cards hidden from the in-game card library.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         是否包含未显示在游戏内卡牌图鉴中的已注册卡牌。
		///     </para>
		/// </summary>
		public bool IncludeCardsHiddenFromLibrary { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Whether output filenames use each card's localized title in the language active when the export
		///         starts. Missing or unusable titles fall back to the model ID, and duplicate titles receive a stable
		///         disambiguating suffix.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         输出文件名是否使用导出开始时当前语言下的卡牌标题。标题缺失或无法用于文件名时会回退到模型 ID，重复标题会附加稳定的
		///         区分后缀。
		///     </para>
		/// </summary>
		public bool UseLocalizedFileNames { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a request with scale <c>1</c>, card-only capture, and upgraded variants enabled.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建缩放比例为 <c>1</c>、仅捕获卡牌且包含升级版本的请求。
		///     </para>
		/// </summary>
		public static CardPngExportRequest CreateDefault(string outputDirectory)
		{
			return new CardPngExportRequest
			{
				OutputDirectory = outputDirectory,
				Scale = 1f,
				CaptureMode = CardPngExportCaptureMode.CardOnly,
				IncludeUpgradedVariants = true,
				MaxBaseCards = 0
			};
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Starts a card PNG export using values stored by the RitsuLib settings interface.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         使用 RitsuLib 设置界面保存的值启动卡牌 PNG 导出。
	///     </para>
	/// </summary>
	internal static class CardPngExportSettingsActions
	{
		internal static void TryBeginFromSettings(IModSettingsValueBinding<string> pathBinding, IModSettingsValueBinding<bool> includeHoverBinding, IModSettingsValueBinding<bool> includeUpgradesBinding, IModSettingsValueBinding<double> scaleBinding, IModSettingsValueBinding<string> filterBinding, IModSettingsValueBinding<bool> includeHiddenFromLibraryBinding, IModSettingsValueBinding<bool> useLocalizedFileNamesBinding)
		{
			string text = pathBinding.Read().Trim();
			if (string.IsNullOrWhiteSpace(text))
			{
				RitsuLibFramework.Logger.Warn("Card PNG export: choose an output folder first, or use Browse.", 1);
				return;
			}
			if (!CardPngExporter.TryValidateExportEnvironment(out string error))
			{
				RitsuLibFramework.Logger.Warn(error, 1);
				return;
			}
			float scale = (float)scaleBinding.Read();
			string text2 = filterBinding.Read().Trim();
			RitsuLibFramework.BeginCardPngExport(new CardPngExportRequest
			{
				OutputDirectory = text,
				CaptureMode = (includeHoverBinding.Read() ? CardPngExportCaptureMode.CardWithHoverTipsPanel : CardPngExportCaptureMode.CardOnly),
				IncludeUpgradedVariants = includeUpgradesBinding.Read(),
				IncludeCardsHiddenFromLibrary = includeHiddenFromLibraryBinding.Read(),
				UseLocalizedFileNames = useLocalizedFileNamesBinding.Read(),
				Scale = scale,
				IdFilterSubstring = (string.IsNullOrEmpty(text2) ? null : text2),
				MaxBaseCards = 0
			});
			RitsuLibFramework.Logger.Info("Card PNG export started.", 1);
		}
	}
}
namespace STS2RitsuLib.Data
{
	/// <summary>
	///     <para xml:lang="en">Provides key-based registration and access for a mod's persistent and in-memory data.</para>
	///     <para xml:lang="zh-CN">为模组的持久化数据和内存数据提供基于键的注册与访问。</para>
	/// </summary>
	public class ModDataStore
	{
		private sealed class RegistrationScope(ModDataStore store) : IDisposable
		{
			private bool _disposed;

			public void Dispose()
			{
				if (!_disposed)
				{
					_disposed = true;
					store.EndRegistrationScope();
				}
			}
		}

		private sealed class InMemoryDataEntry<T>(string key, SaveScope scope, Func<T> defaultFactory) : IRegisteredDataEntry where T : class, new()
		{
			private T _data = defaultFactory();

			public T Data
			{
				get
				{
					if (!IsInitialized)
					{
						throw new InvalidOperationException("Data entry '" + key + "' is not initialized.");
					}
					return _data;
				}
			}

			public SaveScope Scope { get; } = scope;

			public Type DataType => typeof(T);

			public bool HadExistingData => false;

			public bool IsInitialized { get; private set; }

			public void Initialize(JsonSerializerOptions jsonOptions)
			{
				if (!IsInitialized)
				{
					_data = defaultFactory();
					IsInitialized = true;
				}
			}

			public void Load()
			{
				if (!IsInitialized)
				{
					throw new InvalidOperationException("Data entry '" + key + "' is not initialized.");
				}
			}

			public void Save()
			{
			}

			public void SaveToProfilePath(int profileId)
			{
			}

			public bool ReloadIfPathChanged()
			{
				return false;
			}

			public void Modify(Action<T> modifier)
			{
				if (!IsInitialized)
				{
					throw new InvalidOperationException("Data entry '" + key + "' is not initialized.");
				}
				modifier(_data);
			}
		}

		private interface IRegisteredDataEntry
		{
			SaveScope Scope { get; }

			Type DataType { get; }

			bool HadExistingData { get; }

			bool IsInitialized { get; }

			void Initialize(JsonSerializerOptions jsonOptions);

			void Load();

			void Save();

			void SaveToProfilePath(int profileId);

			bool ReloadIfPathChanged();
		}

		private sealed class RegisteredDataEntry<T>(string modId, string key, string fileName, SaveScope scope, Func<T> defaultFactory, bool autoCreateIfMissing, MigrationManager migrationManager, Logger logger, Func<StorageContext>? contextProvider = null) : IRegisteredDataEntry where T : class, new()
		{
			private PersistentDataEntry<T>? _entry;

			private string? _lastLoadedPath;

			public T Data
			{
				get
				{
					PersistentDataEntry<T>? entry = _entry;
					return ((entry != null) ? entry.Data : null) ?? throw new InvalidOperationException("Data entry '" + key + "' is not initialized.");
				}
			}

			public SaveScope Scope { get; } = scope;

			public Type DataType => typeof(T);

			public bool HadExistingData { get; private set; }

			public bool IsInitialized => _entry != null;

			public void Initialize(JsonSerializerOptions jsonOptions)
			{
				if (_entry == null)
				{
					_entry = new PersistentDataEntry<T>(modId, fileName, Scope, defaultFactory(), jsonOptions, migrationManager, autoCreateIfMissing, contextProvider);
				}
			}

			public void Load()
			{
				if (_entry == null)
				{
					throw new InvalidOperationException("Data entry '" + key + "' is not initialized.");
				}
				HadExistingData = FileOperations.FileExists(_lastLoadedPath = _entry.FilePath);
				_entry.Load();
			}

			public bool ReloadIfPathChanged()
			{
				if (_entry == null)
				{
					throw new InvalidOperationException("Data entry '" + key + "' is not initialized.");
				}
				string filePath = _entry.FilePath;
				if (string.Equals(_lastLoadedPath, filePath, StringComparison.Ordinal))
				{
					return false;
				}
				logger.Info($"[{modId}] Data path changed for '{key}': '{_lastLoadedPath ?? "<none>"}' -> '{filePath}', reloading", 1);
				Load();
				return true;
			}

			public void Save()
			{
				_entry?.Save();
			}

			public void SaveToProfilePath(int profileId)
			{
				if (_entry != null && Scope == SaveScope.Profile)
				{
					string filePath = ProfileManager.GetFilePath(fileName, Scope, profileId, modId);
					_entry.SaveTo(filePath);
				}
			}

			public void Modify(Action<T> modifier)
			{
				if (_entry == null)
				{
					throw new InvalidOperationException("Data entry '" + key + "' is not initialized.");
				}
				_entry.Modify(modifier);
			}
		}

		private static readonly Lock StoresLock = new Lock();

		private static readonly Dictionary<string, ModDataStore> Stores = new Dictionary<string, ModDataStore>(StringComparer.OrdinalIgnoreCase);

		private readonly Dictionary<string, IRegisteredDataEntry> _entries = new Dictionary<string, IRegisteredDataEntry>(StringComparer.OrdinalIgnoreCase);

		private readonly JsonSerializerOptions _jsonOptions;

		private readonly Logger _logger;

		private bool _profileEventsSubscribed;

		private int _registrationScopeDepth;

		private bool _registrationScopeInitializeProfileIfReady;

		/// <summary>
		///     <para xml:lang="en">Gets the ID of the mod that owns this store.</para>
		///     <para xml:lang="zh-CN">获取此存储所属的模组 ID。</para>
		/// </summary>
		public string ModId { get; }

		internal static bool HasAnyProfileScopedEntries => GetStoresSnapshot().Any((ModDataStore store) => store.HasProfileScopedEntries);

		/// <summary>
		///     <para xml:lang="en">Gets whether every global entry has been initialized and loaded.</para>
		///     <para xml:lang="zh-CN">获取所有全局条目是否均已初始化并加载。</para>
		/// </summary>
		public bool IsGlobalInitialized { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Gets whether entries for the active profile have been initialized.</para>
		///     <para xml:lang="zh-CN">获取当前档案的条目是否已初始化。</para>
		/// </summary>
		public bool IsProfileInitialized { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Gets whether this store contains any <see cref="F:STS2RitsuLib.Utils.Persistence.SaveScope.Profile" /> registrations.</para>
		///     <para xml:lang="zh-CN">获取此存储是否包含任何 <see cref="F:STS2RitsuLib.Utils.Persistence.SaveScope.Profile" /> 注册。</para>
		/// </summary>
		public bool HasProfileScopedEntries => _entries.Values.Any((IRegisteredDataEntry e) => e.Scope == SaveScope.Profile);

		internal event Action<string>? EntryReloaded;

		private ModDataStore(string modId)
		{
			ModId = modId;
			_logger = RitsuLibFramework.CreateLogger(modId, (LogType)0);
			_jsonOptions = new JsonSerializerOptions
			{
				WriteIndented = true,
				DefaultIgnoreCondition = JsonIgnoreCondition.Never,
				IncludeFields = false
			};
		}

		/// <summary>
		///     <para xml:lang="en">Defers eager initialization of newly registered entries until the returned scope is disposed.</para>
		///     <para xml:lang="zh-CN">将新注册条目的立即初始化推迟到返回的作用域被释放时。</para>
		/// </summary>
		/// <param name="initializeProfileIfReady">
		///     <para xml:lang="en">Whether new profile entries should initialize at scope end when profile data is already ready.</para>
		///     <para xml:lang="zh-CN">档案数据已就绪时，是否在作用域结束时初始化新的档案条目。</para>
		/// </param>
		public IDisposable BeginRegistrationScope(bool initializeProfileIfReady = true)
		{
			_registrationScopeDepth++;
			_registrationScopeInitializeProfileIfReady |= initializeProfileIfReady;
			return new RegistrationScope(this);
		}

		/// <summary>
		///     <para xml:lang="en">Gets the process-wide store for <paramref name="modId" />.</para>
		///     <para xml:lang="zh-CN">获取 <paramref name="modId" /> 对应的进程级存储。</para>
		/// </summary>
		public static ModDataStore For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (StoresLock.EnterScope())
			{
				if (Stores.TryGetValue(modId, out ModDataStore value))
				{
					return value;
				}
				value = new ModDataStore(modId);
				Stores[modId] = value;
				return value;
			}
		}

		internal static void InitializeAllProfileScoped()
		{
			ModDataStore[] storesSnapshot = GetStoresSnapshot();
			for (int i = 0; i < storesSnapshot.Length; i++)
			{
				storesSnapshot[i].InitializeProfileScoped();
			}
		}

		internal static bool ReloadAllIfPathChanged()
		{
			return GetStoresSnapshot().Aggregate(seed: false, (bool current, ModDataStore store) => current | store.ReloadIfPathChanged());
		}

		internal static void DeleteAllProfileData(int profileId)
		{
			ModDataStore[] storesSnapshot = GetStoresSnapshot();
			foreach (ModDataStore modDataStore in storesSnapshot)
			{
				ProfileManager.DeleteProfileData(profileId, modDataStore.ModId);
			}
		}

		private static ModDataStore[] GetStoresSnapshot()
		{
			using (StoresLock.EnterScope())
			{
				return Stores.Values.ToArray();
			}
		}

		/// <summary>
		///     <para xml:lang="en">Initializes and loads every uninitialized global entry.</para>
		///     <para xml:lang="zh-CN">初始化并加载所有尚未初始化的全局条目。</para>
		/// </summary>
		public void InitializeGlobal()
		{
			foreach (IRegisteredDataEntry item in _entries.Values.Where((IRegisteredDataEntry e) => e != null && e.Scope == SaveScope.Global && !e.IsInitialized))
			{
				item.Initialize(_jsonOptions);
				item.Load();
			}
			RefreshGlobalInitializationState();
		}

		/// <summary>
		///     <para xml:lang="en">Initializes and loads profile entries, then subscribes to profile changes.</para>
		///     <para xml:lang="zh-CN">初始化并加载档案条目，然后订阅档案变更事件。</para>
		/// </summary>
		public void InitializeProfileScoped()
		{
			if (!IsGlobalInitialized)
			{
				InitializeGlobal();
			}
			ProfileManager.Instance.Initialize();
			if (!_profileEventsSubscribed)
			{
				ProfileManager.Instance.ProfileChanged += OnProfileChanged;
				_profileEventsSubscribed = true;
			}
			foreach (IRegisteredDataEntry item in _entries.Values.Where((IRegisteredDataEntry e) => e != null && !e.IsInitialized && e.Scope == SaveScope.Profile))
			{
				item.Initialize(_jsonOptions);
				item.Load();
			}
			IsProfileInitialized = _entries.Values.Where((IRegisteredDataEntry e) => e.Scope == SaveScope.Profile).All((IRegisteredDataEntry e) => e.IsInitialized);
		}

		/// <summary>
		///     <para xml:lang="en">Registers a JSON-backed data slot identified by <paramref name="key" />.</para>
		///     <para xml:lang="zh-CN">注册由 JSON 支持、以 <paramref name="key" /> 标识的数据槽。</para>
		/// </summary>
		/// <param name="key">
		///     <para xml:lang="en">The logical key used to access the data slot.</para>
		///     <para xml:lang="zh-CN">用于访问数据槽的逻辑键。</para>
		/// </param>
		/// <param name="fileName">
		///     <para xml:lang="en">The file-name segment supplied to <see cref="T:STS2RitsuLib.Utils.Persistence.ProfileManager" />.</para>
		///     <para xml:lang="zh-CN">传递给 <see cref="T:STS2RitsuLib.Utils.Persistence.ProfileManager" /> 的文件名片段。</para>
		/// </param>
		/// <param name="scope">
		///     <para xml:lang="en">The data slot's save scope.</para>
		///     <para xml:lang="zh-CN">数据槽的保存作用域。</para>
		/// </param>
		/// <param name="defaultFactory">
		///     <para xml:lang="en">An optional factory for the default value when no file exists.</para>
		///     <para xml:lang="zh-CN">文件不存在时，用于创建默认值的可选工厂。</para>
		/// </param>
		/// <param name="autoCreateIfMissing">
		///     <para xml:lang="en">Whether a missing file should be created automatically.</para>
		///     <para xml:lang="zh-CN">文件缺失时是否自动创建。</para>
		/// </param>
		/// <param name="migrationConfig">
		///     <para xml:lang="en">Optional schema-version configuration for migrations.</para>
		///     <para xml:lang="zh-CN">用于迁移的可选架构版本配置。</para>
		/// </param>
		/// <param name="migrations">
		///     <para xml:lang="en">Optional migration steps; requires <paramref name="migrationConfig" />.</para>
		///     <para xml:lang="zh-CN">可选的迁移步骤；需要同时提供 <paramref name="migrationConfig" />。</para>
		/// </param>
		public void Register<T>(string key, string fileName, SaveScope scope, Func<T>? defaultFactory = null, bool autoCreateIfMissing = false, ModDataMigrationConfig? migrationConfig = null, IEnumerable<IMigration>? migrations = null) where T : class, new()
		{
			Register(key, fileName, scope, syncToCloud: true, defaultFactory, autoCreateIfMissing, migrationConfig, migrations);
		}

		/// <summary>
		///     <para xml:lang="en">Registers a JSON-backed data slot with an explicit cloud-sync policy.</para>
		///     <para xml:lang="zh-CN">注册由 JSON 支持的数据槽，并显式指定云同步策略。</para>
		/// </summary>
		/// <param name="key">
		///     <para xml:lang="en">The logical key used to access the data slot.</para>
		///     <para xml:lang="zh-CN">用于访问数据槽的逻辑键。</para>
		/// </param>
		/// <param name="fileName">
		///     <para xml:lang="en">The file-name segment supplied to <see cref="T:STS2RitsuLib.Utils.Persistence.ProfileManager" />.</para>
		///     <para xml:lang="zh-CN">传递给 <see cref="T:STS2RitsuLib.Utils.Persistence.ProfileManager" /> 的文件名片段。</para>
		/// </param>
		/// <param name="scope">
		///     <para xml:lang="en">The data slot's save scope.</para>
		///     <para xml:lang="zh-CN">数据槽的保存作用域。</para>
		/// </param>
		/// <param name="defaultFactory">
		///     <para xml:lang="en">An optional factory for the default value when no file exists.</para>
		///     <para xml:lang="zh-CN">文件不存在时，用于创建默认值的可选工厂。</para>
		/// </param>
		/// <param name="autoCreateIfMissing">
		///     <para xml:lang="en">Whether a missing file should be created automatically.</para>
		///     <para xml:lang="zh-CN">文件缺失时是否自动创建。</para>
		/// </param>
		/// <param name="migrationConfig">
		///     <para xml:lang="en">Optional schema-version configuration for migrations.</para>
		///     <para xml:lang="zh-CN">用于迁移的可选架构版本配置。</para>
		/// </param>
		/// <param name="migrations">
		///     <para xml:lang="en">Optional migration steps; requires <paramref name="migrationConfig" />.</para>
		///     <para xml:lang="zh-CN">可选的迁移步骤；需要同时提供 <paramref name="migrationConfig" />。</para>
		/// </param>
		/// <param name="syncToCloud">
		///     <para xml:lang="en">Whether this persisted slot participates in RitsuLib's mod-data cloud sync.</para>
		///     <para xml:lang="zh-CN">此持久化数据槽是否参与 RitsuLib 的模组数据云同步。</para>
		/// </param>
		public void Register<T>(string key, string fileName, SaveScope scope, bool syncToCloud, Func<T>? defaultFactory = null, bool autoCreateIfMissing = false, ModDataMigrationConfig? migrationConfig = null, IEnumerable<IMigration>? migrations = null) where T : class, new()
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			ArgumentException.ThrowIfNullOrWhiteSpace(fileName, "fileName");
			if (_entries.ContainsKey(key))
			{
				throw new InvalidOperationException("Data key '" + key + "' is already registered.");
			}
			MigrationManager migrationManager = CreateMigrationManager<T>(migrationConfig, migrations);
			if (scope == SaveScope.InMemory)
			{
				InMemoryDataEntry<T> value = new InMemoryDataEntry<T>(key, scope, defaultFactory ?? ((Func<T>)(() => new T())));
				_entries[key] = value;
				return;
			}
			RegisteredDataEntry<T> registeredDataEntry = new RegisteredDataEntry<T>(ModId, key, fileName, scope, defaultFactory ?? ((Func<T>)(() => new T())), autoCreateIfMissing, migrationManager, _logger);
			_entries[key] = registeredDataEntry;
			if (syncToCloud)
			{
				ModCloudSyncPathRegistry.RegisterModDataSlot(ModId, fileName, scope);
			}
			if (_registrationScopeDepth <= 0 && (IsGlobalInitialized || scope != SaveScope.Global) && (IsProfileInitialized || scope != SaveScope.Profile))
			{
				registeredDataEntry.Initialize(_jsonOptions);
				registeredDataEntry.Load();
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a JSON-backed data slot using an explicit <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContext" /> provider for path
		///         resolution.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册由 JSON 支持的数据槽，并使用显式的 <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContext" /> 提供器解析路径。
		///     </para>
		/// </summary>
		public void Register<T>(string key, string fileName, SaveScope scope, Func<StorageContext> contextProvider, Func<T>? defaultFactory = null, bool autoCreateIfMissing = false, ModDataMigrationConfig? migrationConfig = null, IEnumerable<IMigration>? migrations = null) where T : class, new()
		{
			Register(key, fileName, scope, contextProvider, syncToCloud: true, defaultFactory, autoCreateIfMissing, migrationConfig, migrations);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a JSON-backed data slot using an explicit <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContext" /> provider and
		///         cloud-sync policy.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册由 JSON 支持的数据槽，并使用显式的 <see cref="T:STS2RitsuLib.Utils.Persistence.Context.StorageContext" /> 提供器和云同步策略。
		///     </para>
		/// </summary>
		/// <param name="key">
		///     <para xml:lang="en">The logical key used to access the data slot.</para>
		///     <para xml:lang="zh-CN">用于访问数据槽的逻辑键。</para>
		/// </param>
		/// <param name="fileName">
		///     <para xml:lang="en">The file-name segment supplied to path resolution.</para>
		///     <para xml:lang="zh-CN">传递给路径解析流程的文件名片段。</para>
		/// </param>
		/// <param name="scope">
		///     <para xml:lang="en">The data slot's save scope.</para>
		///     <para xml:lang="zh-CN">数据槽的保存作用域。</para>
		/// </param>
		/// <param name="contextProvider">
		///     <para xml:lang="en">The provider used to resolve the current storage context.</para>
		///     <para xml:lang="zh-CN">用于解析当前存储上下文的提供器。</para>
		/// </param>
		/// <param name="syncToCloud">
		///     <para xml:lang="en">Whether this persisted slot participates in RitsuLib's mod-data cloud sync.</para>
		///     <para xml:lang="zh-CN">此持久化数据槽是否参与 RitsuLib 的模组数据云同步。</para>
		/// </param>
		/// <param name="defaultFactory">
		///     <para xml:lang="en">An optional factory for the default value when no file exists.</para>
		///     <para xml:lang="zh-CN">文件不存在时，用于创建默认值的可选工厂。</para>
		/// </param>
		/// <param name="autoCreateIfMissing">
		///     <para xml:lang="en">Whether a missing file should be created automatically.</para>
		///     <para xml:lang="zh-CN">文件缺失时是否自动创建。</para>
		/// </param>
		/// <param name="migrationConfig">
		///     <para xml:lang="en">Optional schema-version configuration for migrations.</para>
		///     <para xml:lang="zh-CN">用于迁移的可选架构版本配置。</para>
		/// </param>
		/// <param name="migrations">
		///     <para xml:lang="en">Optional migration steps; requires <paramref name="migrationConfig" />.</para>
		///     <para xml:lang="zh-CN">可选的迁移步骤；需要同时提供 <paramref name="migrationConfig" />。</para>
		/// </param>
		public void Register<T>(string key, string fileName, SaveScope scope, Func<StorageContext> contextProvider, bool syncToCloud, Func<T>? defaultFactory = null, bool autoCreateIfMissing = false, ModDataMigrationConfig? migrationConfig = null, IEnumerable<IMigration>? migrations = null) where T : class, new()
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			ArgumentException.ThrowIfNullOrWhiteSpace(fileName, "fileName");
			ArgumentNullException.ThrowIfNull(contextProvider, "contextProvider");
			if (_entries.ContainsKey(key))
			{
				throw new InvalidOperationException("Data key '" + key + "' is already registered.");
			}
			MigrationManager migrationManager = CreateMigrationManager<T>(migrationConfig, migrations);
			if (scope == SaveScope.InMemory)
			{
				throw new InvalidOperationException("SaveScope.InMemory does not support contextProvider overload.");
			}
			RegisteredDataEntry<T> registeredDataEntry = new RegisteredDataEntry<T>(ModId, key, fileName, scope, defaultFactory ?? ((Func<T>)(() => new T())), autoCreateIfMissing, migrationManager, _logger, contextProvider);
			_entries[key] = registeredDataEntry;
			if (syncToCloud)
			{
				ModCloudSyncPathRegistry.RegisterModDataSlot(ModId, fileName, scope);
			}
			if (_registrationScopeDepth <= 0 && (IsGlobalInitialized || scope != SaveScope.Global) && (IsProfileInitialized || scope != SaveScope.Profile))
			{
				registeredDataEntry.Initialize(_jsonOptions);
				registeredDataEntry.Load();
			}
		}

		private static MigrationManager CreateMigrationManager<T>(ModDataMigrationConfig? migrationConfig, IEnumerable<IMigration>? migrations) where T : class, new()
		{
			MigrationManager migrationManager = new MigrationManager();
			if (migrationConfig != null)
			{
				migrationManager.RegisterConfig<T>(migrationConfig.CurrentDataVersion, migrationConfig.MinimumSupportedDataVersion, migrationConfig.SchemaVersionProperty);
			}
			if (migrations == null)
			{
				return migrationManager;
			}
			if (migrationConfig == null)
			{
				throw new InvalidOperationException("Migration config for type '" + typeof(T).Name + "' requires a current version.");
			}
			foreach (IMigration migration in migrations)
			{
				migrationManager.RegisterMigration<T>(migration);
			}
			return migrationManager;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the live instance for <paramref name="key" />. Profile reloads can replace the root instance;
		///         use <see cref="M:STS2RitsuLib.Data.ModDataStore.CreateCache``1(System.String)" /> for cache-aware access.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 <paramref name="key" /> 对应的实时实例。重新加载档案可能替换其根实例；需要缓存感知的访问时，
		///         请使用 <see cref="M:STS2RitsuLib.Data.ModDataStore.CreateCache``1(System.String)" />。
		///     </para>
		/// </summary>
		public T Get<T>(string key) where T : class, new()
		{
			IRegisteredDataEntry entry = GetEntry(key);
			if (!(entry is RegisteredDataEntry<T> { Data: var data }))
			{
				if (!(entry is InMemoryDataEntry<T> { Data: var data2 }))
				{
					throw new InvalidOperationException($"Data key '{key}' is registered as '{entry.DataType.Name}', not '{typeof(T).Name}'.");
				}
				return data2;
			}
			return data;
		}

		/// <summary>
		///     <para xml:lang="en">Creates a cache wrapper that invalidates itself when <paramref name="key" /> is reloaded.</para>
		///     <para xml:lang="zh-CN">创建缓存包装器，并在重新加载 <paramref name="key" /> 时自动使其失效。</para>
		/// </summary>
		public ModDataStoreCache<T> CreateCache<T>(string key) where T : class, new()
		{
			return new ModDataStoreCache<T>(this, key);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Mutates the instance for <paramref name="key" /> in place; call <see cref="M:STS2RitsuLib.Data.ModDataStore.Save(System.String)" /> to persist
		///         it.
		///     </para>
		///     <para xml:lang="zh-CN">原地修改 <paramref name="key" /> 对应的实例；调用 <see cref="M:STS2RitsuLib.Data.ModDataStore.Save(System.String)" /> 可将其持久化。</para>
		/// </summary>
		public void Modify<T>(string key, Action<T> modifier) where T : class, new()
		{
			IRegisteredDataEntry entry = GetEntry(key);
			if (!(entry is RegisteredDataEntry<T> registeredDataEntry))
			{
				if (!(entry is InMemoryDataEntry<T> inMemoryDataEntry))
				{
					throw new InvalidOperationException($"Data key '{key}' is registered as '{entry.DataType.Name}', not '{typeof(T).Name}'.");
				}
				inMemoryDataEntry.Modify(modifier);
			}
			else
			{
				registeredDataEntry.Modify(modifier);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Writes the entry for <paramref name="key" /> to disk.</para>
		///     <para xml:lang="zh-CN">将 <paramref name="key" /> 对应的条目写入磁盘。</para>
		/// </summary>
		public void Save(string key)
		{
			IRegisteredDataEntry entry = GetEntry(key);
			if (entry.Scope != SaveScope.InMemory)
			{
				entry.Save();
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether the entry's file existed when it was first loaded.</para>
		///     <para xml:lang="zh-CN">获取首次加载条目时，其文件是否已经存在。</para>
		/// </summary>
		public bool HasExistingData(string key)
		{
			return GetEntry(key).HadExistingData;
		}

		/// <summary>
		///     <para xml:lang="en">Reloads entries whose resolved path has changed, such as after a profile switch.</para>
		///     <para xml:lang="zh-CN">重新加载解析路径已发生变化的条目，例如切换档案后的条目。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> if any entry was reloaded; otherwise, <see langword="false" />.</para>
		///     <para xml:lang="zh-CN">如果重新加载了任何条目，则为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public bool ReloadIfPathChanged()
		{
			if (!IsGlobalInitialized)
			{
				return false;
			}
			bool result = false;
			foreach (var (key, registeredDataEntry2) in _entries.Where<KeyValuePair<string, IRegisteredDataEntry>>((KeyValuePair<string, IRegisteredDataEntry> pair) => pair.Value.IsInitialized))
			{
				if (registeredDataEntry2.ReloadIfPathChanged())
				{
					result = true;
					OnEntryReloaded(key);
				}
			}
			return result;
		}

		/// <summary>
		///     <para xml:lang="en">Persists every registered entry.</para>
		///     <para xml:lang="zh-CN">持久化所有已注册的条目。</para>
		/// </summary>
		public void SaveAll()
		{
			foreach (IRegisteredDataEntry value in _entries.Values)
			{
				value.Save();
			}
		}

		private void OnProfileChanged(int oldProfileId, int newProfileId)
		{
			if (!IsProfileInitialized)
			{
				return;
			}
			_logger.Info($"[{ModId}] Profile changed from {oldProfileId} to {newProfileId}, handling data transition...", 1);
			foreach (var (key, registeredDataEntry2) in _entries.Where<KeyValuePair<string, IRegisteredDataEntry>>((KeyValuePair<string, IRegisteredDataEntry> pair) => pair.Value.Scope == SaveScope.Profile))
			{
				registeredDataEntry2.SaveToProfilePath(oldProfileId);
				registeredDataEntry2.Load();
				OnEntryReloaded(key);
			}
		}

		private void OnEntryReloaded(string key)
		{
			EntryReloaded?.Invoke(key);
		}

		private IRegisteredDataEntry GetEntry(string key)
		{
			if (!_entries.TryGetValue(key, out IRegisteredDataEntry value))
			{
				throw new KeyNotFoundException("Data key '" + key + "' is not registered.");
			}
			if (value == null || value.IsInitialized || value.Scope != SaveScope.Global)
			{
				return value;
			}
			value.Initialize(_jsonOptions);
			value.Load();
			RefreshGlobalInitializationState();
			return value;
		}

		private void RefreshGlobalInitializationState()
		{
			IsGlobalInitialized = _entries.Values.Where((IRegisteredDataEntry entry) => entry.Scope == SaveScope.Global).All((IRegisteredDataEntry entry) => entry.IsInitialized);
		}

		private void EndRegistrationScope()
		{
			if (_registrationScopeDepth <= 0)
			{
				throw new InvalidOperationException("Registration scope was disposed more times than created.");
			}
			_registrationScopeDepth--;
			if (_registrationScopeDepth <= 0)
			{
				bool registrationScopeInitializeProfileIfReady = _registrationScopeInitializeProfileIfReady;
				_registrationScopeInitializeProfileIfReady = false;
				InitializeGlobal();
				if (registrationScopeInitializeProfileIfReady && IsProfileInitialized)
				{
					InitializeProfileScoped();
				}
			}
		}

		private RegisteredDataEntry<T> GetEntry<T>(string key) where T : class, new()
		{
			IRegisteredDataEntry entry = GetEntry(key);
			return (entry as RegisteredDataEntry<T>) ?? throw new InvalidOperationException($"Data key '{key}' is registered as '{entry.DataType.Name}', not '{typeof(T).Name}'.");
		}

		private InMemoryDataEntry<T> GetMemoryEntry<T>(string key) where T : class, new()
		{
			IRegisteredDataEntry entry = GetEntry(key);
			return (entry as InMemoryDataEntry<T>) ?? throw new InvalidOperationException($"Data key '{key}' is registered as '{entry.DataType.Name}', not '{typeof(T).Name}'.");
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides a lazy cache for one <see cref="T:STS2RitsuLib.Data.ModDataStore" /> key and invalidates it when the backing entry is
	///         reloaded.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为单个 <see cref="T:STS2RitsuLib.Data.ModDataStore" /> 键提供惰性缓存，并在重新加载底层条目时自动使缓存失效。
	///     </para>
	/// </summary>
	/// <typeparam name="T">
	///     <para xml:lang="en">The registered data model type.</para>
	///     <para xml:lang="zh-CN">已注册的数据模型类型。</para>
	/// </typeparam>
	public sealed class ModDataStoreCache<T> : IDisposable where T : class, new()
	{
		private readonly IDisposable _profileInvalidatedSubscription;

		private readonly ModDataStore _store;

		private readonly Lock _sync = new Lock();

		private bool _disposed;

		private T? _value;

		/// <summary>
		///     <para xml:lang="en">Gets the logical data key associated with this cache.</para>
		///     <para xml:lang="zh-CN">获取与此缓存关联的逻辑数据键。</para>
		/// </summary>
		public string Key { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the cached value, loading it from the store on first access or after invalidation.</para>
		///     <para xml:lang="zh-CN">获取缓存值；首次访问或缓存失效后会从存储中重新读取。</para>
		/// </summary>
		public T Value
		{
			get
			{
				ThrowIfDisposed();
				using (_sync.EnterScope())
				{
					return _value ?? (_value = _store.Get<T>(Key));
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether this wrapper currently holds a cached instance.</para>
		///     <para xml:lang="zh-CN">获取此包装器当前是否持有缓存实例。</para>
		/// </summary>
		public bool HasValue
		{
			get
			{
				using (_sync.EnterScope())
				{
					return _value != null;
				}
			}
		}

		internal ModDataStoreCache(ModDataStore store, string key)
		{
			ArgumentNullException.ThrowIfNull(store, "store");
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			_store = store;
			Key = key;
			_store.EntryReloaded += OnEntryReloaded;
			_profileInvalidatedSubscription = RitsuLibFramework.SubscribeLifecycle((Action<ProfileDataInvalidatedEvent>)delegate
			{
				Invalidate();
			}, false);
		}

		/// <inheritdoc />
		public void Dispose()
		{
			if (!_disposed)
			{
				_disposed = true;
				_store.EntryReloaded -= OnEntryReloaded;
				_profileInvalidatedSubscription.Dispose();
				Invalidate();
			}
		}

		/// <summary>
		///     <para xml:lang="en">Clears the cached instance so the next <see cref="P:STS2RitsuLib.Data.ModDataStoreCache`1.Value" /> access reads from the store.</para>
		///     <para xml:lang="zh-CN">清除缓存实例，使下次访问 <see cref="P:STS2RitsuLib.Data.ModDataStoreCache`1.Value" /> 时从存储中重新读取。</para>
		/// </summary>
		public void Invalidate()
		{
			using (_sync.EnterScope())
			{
				_value = null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Reloads the value from the store and returns the refreshed instance.</para>
		///     <para xml:lang="zh-CN">从存储中重新读取值，并返回刷新后的实例。</para>
		/// </summary>
		public T Refresh()
		{
			ThrowIfDisposed();
			using (_sync.EnterScope())
			{
				_value = _store.Get<T>(Key);
				return _value;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Mutates the backing store entry in place.</para>
		///     <para xml:lang="zh-CN">原地修改底层存储条目。</para>
		/// </summary>
		public void Modify(Action<T> modifier)
		{
			ThrowIfDisposed();
			ArgumentNullException.ThrowIfNull(modifier, "modifier");
			_store.Modify(Key, modifier);
		}

		/// <summary>
		///     <para xml:lang="en">Persists the backing store entry.</para>
		///     <para xml:lang="zh-CN">持久化底层存储条目。</para>
		/// </summary>
		public void Save()
		{
			ThrowIfDisposed();
			_store.Save(Key);
		}

		private void OnEntryReloaded(string key)
		{
			if (string.Equals(Key, key, StringComparison.OrdinalIgnoreCase))
			{
				Invalidate();
			}
		}

		private void ThrowIfDisposed()
		{
			ObjectDisposedException.ThrowIf(_disposed, this);
		}
	}
	internal static class RitsuLibSettingsStore
	{
		private static readonly ModDataStore Store = ModDataStore.For("com.ritsukage.sts2-RitsuLib");

		private static readonly Lock InitLock = new Lock();

		private static bool _initialized;

		private static volatile bool _initializing;

		internal static void Initialize()
		{
			using (InitLock.EnterScope())
			{
				if (_initialized || _initializing)
				{
					return;
				}
				_initializing = true;
				try
				{
					using (RitsuLibFramework.BeginModDataRegistration("com.ritsukage.sts2-RitsuLib", initializeProfileIfReady: false))
					{
						Store.Register("settings", "settings.json", SaveScope.Global, () => new RitsuLibSettings(), autoCreateIfMissing: true, new ModDataMigrationConfig
						{
							CurrentDataVersion = 17,
							MinimumSupportedDataVersion = 0
						}, new global::<>z__ReadOnlyArray<IMigration>(new IMigration[15]
						{
							new RitsuLibSettingsV0Or1ToV2Migration(),
							new RitsuLibSettingsV2ToV4Migration(),
							new RitsuLibSettingsV4ToV5Migration(),
							new RitsuLibSettingsV5ToV6Migration(),
							new RitsuLibSettingsV6ToV7Migration(),
							new RitsuLibSettingsV7ToV8Migration(),
							new RitsuLibSettingsV8ToV9Migration(),
							new RitsuLibSettingsV9ToV10Migration(),
							new RitsuLibSettingsV10ToV11Migration(),
							new RitsuLibSettingsV11ToV12Migration(),
							new RitsuLibSettingsV12ToV13Migration(),
							new RitsuLibSettingsV13ToV14Migration(),
							new RitsuLibSettingsV14ToV15Migration(),
							new RitsuLibSettingsV15ToV16Migration(),
							new RitsuLibSettingsV16ToV17Migration()
						}));
						RitsuDebugToolsInterfaceStateStore.Register(Store);
						RitsuSearchSettingsStore.Register(Store);
						Store.Register("debug-state-presets", "debug_state_presets.json", SaveScope.Global, () => new RitsuDebugStatePresetCollection(), autoCreateIfMissing: true, new ModDataMigrationConfig
						{
							CurrentDataVersion = 1,
							MinimumSupportedDataVersion = 1
						});
						Store.Register("debug-creature-presets", "debug_creature_presets.json", SaveScope.Global, () => new RitsuDebugCreaturePresetCollection(), autoCreateIfMissing: true, new ModDataMigrationConfig
						{
							CurrentDataVersion = 1,
							MinimumSupportedDataVersion = 1
						});
					}
					_initialized = true;
					RitsuShellThemeRuntime.ApplyThemeId(GetSettings().UiShellThemeId);
					LogConfigSnapshot();
				}
				finally
				{
					_initializing = false;
				}
			}
		}

		private static void LogConfigSnapshot()
		{
			RitsuLibSettings settings = GetSettings();
			bool debugCompatibilityMode = settings.DebugCompatibilityMode;
			RitsuLibFramework.Logger.Info($"[Config] Debug compatibility master is {(debugCompatibilityMode ? "enabled" : "disabled")}. Sub-flags (only when master on): LocTable={settings.DebugCompatLocTable}, UnlockEpoch={settings.DebugCompatUnlockEpoch}, AncientArchitect={settings.DebugCompatAncientArchitect}. Mod Steam cloud mirror: {(settings.SyncModDataToSteamCloud ? "enabled" : "disabled")}. Config file: {ProfileManager.GetFilePath("settings.json", SaveScope.Global, 0, "com.ritsukage.sts2-RitsuLib")}", 1);
		}

