		internal static string NormalizeModSourceHoverTipsFormat(string? value)
		{
			string text = PrepareModSourceHoverTipsFormatForEditing(value).Trim();
			if (text.Length == 0)
			{
				return "{source}";
			}
			return text;
		}

		internal static string PrepareModSourceHoverTipsFormatForEditing(string? value)
		{
			string text = (value ?? string.Empty).Replace('\r', ' ').Replace('\n', ' ');
			if (text.Length > 256)
			{
				return text.Substring(0, 256);
			}
			return text;
		}

