		internal static RitsuDebugLogViewerOptions GetDebugLogViewerOptions()
		{
			Initialize();
			RitsuLibSettings settings = GetSettings();
			RitsuDebugLogViewerCommandLineOptions ritsuDebugLogViewerCommandLineOptions = RitsuDebugLogViewerCommandLine.ParseCurrentProcess();
			bool flag = false;
			if (string.IsNullOrWhiteSpace(settings.DebugLogViewerAccessToken))
			{
				settings.DebugLogViewerAccessToken = Convert.ToHexString(RandomNumberGenerator.GetBytes(16)).ToLowerInvariant();
				flag = true;
			}
			if (flag)
			{
				Store.Save("settings");
			}
			foreach (string warning in ritsuDebugLogViewerCommandLineOptions.Warnings)
			{
				RitsuLibFramework.Logger.Warn("[DebugLogViewer] " + warning, 1);
			}
			int num = Math.Clamp(settings.DebugLogViewerPort, 1, 65535);
			int num2 = Math.Clamp(settings.DebugLogViewerPortFallbackCount, 0, 100);
			int? port = ritsuDebugLogViewerCommandLineOptions.Port;
			if (port.HasValue)
			{
				int valueOrDefault = port.GetValueOrDefault();
				num = valueOrDefault;
				num2 = ritsuDebugLogViewerCommandLineOptions.PortFallbackCount.GetValueOrDefault();
				RitsuLibFramework.Logger.Info($"[DebugLogViewer] Command line override applied: port={num}, fallbackCount={num2}.", 1);
			}
			else
			{
				port = ritsuDebugLogViewerCommandLineOptions.PortFallbackCount;
				if (port.HasValue)
				{
					int valueOrDefault2 = port.GetValueOrDefault();
					num2 = valueOrDefault2;
					RitsuLibFramework.Logger.Info($"[DebugLogViewer] Command line override applied: fallbackCount={num2}.", 1);
				}
			}
			return new RitsuDebugLogViewerOptions(settings.DebugLogViewerEnabled, settings.DebugLogViewerMirrorGameLogs, settings.DebugLogViewerAutoOpen, settings.DebugLogViewerLanAccessEnabled, num, num2, settings.DebugLogViewerAccessToken, settings.DebugLogViewerRingBufferCapacity, settings.DebugLogViewerQueueCapacity);
		}

