		internal static RitsuToastSettings GetToastSettings()
		{
			//IL_0065: Unknown result type (might be due to invalid IL or missing references)
			Initialize();
			RitsuLibSettings settings = GetSettings();
			RitsuToastAnchor anchor = ParseAnchor(settings.ToastAnchor);
			RitsuToastAnimationPreset animationPreset = ParseAnimation(settings.ToastAnimation);
			int maxVisible = Math.Clamp(settings.ToastMaxVisible, 1, 8);
			double durationSeconds = Math.Clamp(settings.ToastDurationSeconds, 0.5, 30.0);
			return new RitsuToastSettings(settings.ToastEnabled, new RitsuToastPlacement(anchor, new Vector2((float)settings.ToastOffsetX, (float)settings.ToastOffsetY)), new RitsuToastQueuePolicy(maxVisible, 12f), durationSeconds, animationPreset);
		}

		private static RitsuToastAnchor ParseAnchor(string? value)
		{
			return value?.Trim().ToLowerInvariant() switch
			{
				"topleft" => RitsuToastAnchor.TopLeft, 
				"topcenter" => RitsuToastAnchor.TopCenter, 
				"topright" => RitsuToastAnchor.TopRight, 
				"middleleft" => RitsuToastAnchor.MiddleLeft, 
				"middlecenter" => RitsuToastAnchor.MiddleCenter, 
				"middleright" => RitsuToastAnchor.MiddleRight, 
				"bottomleft" => RitsuToastAnchor.BottomLeft, 
				"bottomcenter" => RitsuToastAnchor.BottomCenter, 
				"bottomright" => RitsuToastAnchor.BottomRight, 
				_ => RitsuToastAnchor.TopRight, 
			};
		}

		private static RitsuToastAnimationPreset ParseAnimation(string? value)
		{
			string text = value?.Trim().ToLowerInvariant();
			if (!(text == "fade"))
			{
				if (text == "fadescale")
				{
					return RitsuToastAnimationPreset.FadeScale;
				}
				return RitsuToastAnimationPreset.FadeSlide;
			}
			return RitsuToastAnimationPreset.Fade;
		}

		private static ModelDbDeterministicSortMode ParseModelDbDeterministicSortMode(string? value)
		{
			switch (value?.Trim().ToLowerInvariant())
			{
			case "off":
			case "disabled":
				return ModelDbDeterministicSortMode.Disabled;
			case "force":
			case "forced":
				return ModelDbDeterministicSortMode.Force;
			default:
				return ModelDbDeterministicSortMode.Auto;
			}
		}

		private static ContentSourceDisplayStyle ParseContentSourceDisplayStyle(string? value)
		{
			string text = value?.Trim().ToLowerInvariant();
			if (!(text == "name"))
			{
				if (text == "id")
				{
					return ContentSourceDisplayStyle.Id;
				}
				return ContentSourceDisplayStyle.NameAndId;
			}
			return ContentSourceDisplayStyle.Name;
		}

		private static ContentSourcePlacement ParseContentSourcePlacement(string? value)
		{
			if (!(value?.Trim().ToLowerInvariant() == "bottom"))
			{
				return ContentSourcePlacement.Top;
			}
			return ContentSourcePlacement.Bottom;
		}
	}
	internal enum ContentSourceDisplayStyle
	{
		NameAndId,
		Name,
		Id
	}
	internal enum ContentSourcePlacement
	{
		Top,
		Bottom
	}
}
