namespace STS2RitsuLib.Content
{
	/// <summary>
	///     <para xml:lang="en">
	///         Specifies how eligible act candidates are selected when no forced candidate wins.
	///     </para>
	///     <para xml:lang="zh-CN">指定没有强制候选章节胜出时如何选择符合条件的章节。</para>
	/// </summary>
	public enum ActEnterPoolModeKind
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Selects uniformly from the act already occupying the slot and all eligible candidates.
		///     </para>
		///     <para xml:lang="zh-CN">在槽位中已有的章节与全部符合条件的候选章节之间进行均匀选择。</para>
		/// </summary>
		Uniform,
		/// <summary>
		///     <para xml:lang="en">
		///         Selects by weight from eligible candidates and the optional baseline. Candidates with
		///         non-positive weights are excluded.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         按权重从符合条件的候选章节与可选基线中选择。权重不大于零的候选章节会被排除。
		///     </para>
		/// </summary>
		Weighted
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides run state, random number generation, and unlock state to act-entry resolvers.
	///     </para>
	///     <para xml:lang="zh-CN">向章节进入解析器提供一局游戏状态、随机数生成器与解锁状态。</para>
	/// </summary>
	public readonly record struct ActEnterResolveContext(RunManager RunManager, RunState RunState, int EnteringActIndex, Rng Rng, UnlockState UnlockState, bool IsMultiplayer);
	/// <summary>
	///     <para xml:lang="en">Specifies whether a compendium pool filter is inserted before or after its anchor.</para>
	///     <para xml:lang="zh-CN">指定图鉴牌池筛选器插入到其锚点之前还是之后。</para>
	/// </summary>
	public enum CardLibraryCompendiumFilterInsertRelation
	{
		/// <summary>
		///     <para xml:lang="en">Inserts immediately before the anchor.</para>
		///     <para xml:lang="zh-CN">紧接锚点之前插入。</para>
		/// </summary>
		Before,
		/// <summary>
		///     <para xml:lang="en">Inserts immediately after the anchor.</para>
		///     <para xml:lang="zh-CN">紧接锚点之后插入。</para>
		/// </summary>
		After
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Describes one anchor-relative placement preference for a card-library compendium filter.
	///     </para>
	///     <para xml:lang="zh-CN">描述卡牌库图鉴筛选器的一项相对锚点放置偏好。</para>
	/// </summary>
	public sealed class CardLibraryCompendiumPlacementRule
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets the unique node name of a vanilla pool-filter anchor.
		///     </para>
		///     <para xml:lang="zh-CN">获取原版牌池筛选器锚点的唯一节点名称。</para>
		/// </summary>
		public string? VanillaFilterAnchorUniqueName { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets another mod character's public <c>ModelId.Entry</c> to use as the anchor.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取用作锚点的另一模组角色公共 <c>ModelId.Entry</c>。
		///     </para>
		/// </summary>
		public string? ModCharacterModelIdEntry { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the stable ID of another registered shared-pool filter to use as the anchor.
		///     </para>
		///     <para xml:lang="zh-CN">获取用作锚点的另一已注册共享牌池筛选器稳定 ID。</para>
		/// </summary>
		public string? ModSharedCompendiumFilterStableId { get; init; }

		/// <inheritdoc cref="T:STS2RitsuLib.Content.CardLibraryCompendiumFilterInsertRelation" />
		public CardLibraryCompendiumFilterInsertRelation Relation { get; init; }

		internal void ThrowIfInvalid()
		{
			if (((!string.IsNullOrWhiteSpace(VanillaFilterAnchorUniqueName)) ? 1 : 0) + ((!string.IsNullOrWhiteSpace(ModCharacterModelIdEntry)) ? 1 : 0) + ((!string.IsNullOrWhiteSpace(ModSharedCompendiumFilterStableId)) ? 1 : 0) != 1)
			{
				throw new InvalidOperationException("Each placement rule must set exactly one of VanillaFilterAnchorUniqueName, ModCharacterModelIdEntry, or ModSharedCompendiumFilterStableId.");
			}
		}

		internal static void ThrowIfInvalidRules(IReadOnlyList<CardLibraryCompendiumPlacementRule>? rules)
		{
			if (rules == null)
			{
				return;
			}
			foreach (CardLibraryCompendiumPlacementRule rule in rules)
			{
				rule.ThrowIfInvalid();
			}
		}
	}
