	internal static class CharacterTimelineDiagnostics
	{
		private static readonly Lock Gate = new Lock();

		private static readonly HashSet<Type> LoggedRuntimeTypes = new HashSet<Type>();

		internal static IEnumerable<CharacterModel> LogTimelinePolicy(IEnumerable<CharacterModel> characters)
		{
			foreach (CharacterModel character in characters)
			{
				TryLogTimelinePolicy(character);
				yield return character;
			}
		}

		private static void TryLogTimelinePolicy(CharacterModel character)
		{
			Type type = ((object)character).GetType();
			if (!ModCharacterTimelinePolicy.IsOwnedOrUsesTimelinePolicy(character))
			{
				return;
			}
			using (Gate.EnterScope())
			{
				if (!LoggedRuntimeTypes.Add(type))
				{
					return;
				}
			}
			string value = (ModCharacterTimelinePolicy.TryGetRequiresEpochAndTimeline(character, out var requires) ? requires.ToString() : "<not implemented>");
			RitsuLibFramework.Logger.Info($"[Content] Character timeline: {((AbstractModel)character).Id} {"RequiresEpochAndTimeline"}={value}", 1);
		}
	}
