	/// <summary>
	///     <para xml:lang="en">
	///         Specifies how vanilla model sequences are combined with resolved mod models.
	///     </para>
	///     <para xml:lang="zh-CN">指定如何将原版模型序列与已解析的模组模型合并。</para>
	/// </summary>
	internal enum ContentMergeMode
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Places vanilla models first, appends mod models with previously unseen IDs, and materializes
		///         the result as an array.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         原版模型在前，再追加 ID 尚未出现的模组模型，并将结果实例化为数组。
		///     </para>
		/// </summary>
		AppendDistinctById,
		/// <summary>
		///     <para xml:lang="en">
		///         Preserves the source sequence when there are no mod models; otherwise merges distinct IDs
		///         into a materialized sequence.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         没有模组模型时保留来源序列；否则按不同 ID 合并为实例化序列。
		///     </para>
		/// </summary>
		MergeDistinctById
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines a strategy for combining a model sequence with resolved mod models.
	///     </para>
	///     <para xml:lang="zh-CN">定义将模型序列与已解析模组模型合并的策略。</para>
	/// </summary>
	internal interface IContentEnumerableMergeStrategy<TModel> where TModel : AbstractModel
	{
		IEnumerable<TModel> Merge(IEnumerable<TModel> source, TModel[] additional);
	}
	/// <summary>
	///     <para xml:lang="en">Defines a strategy for combining a model list with resolved mod models.</para>
	///     <para xml:lang="zh-CN">定义将模型列表与已解析模组模型合并的策略。</para>
	/// </summary>
	internal interface IContentListMergeStrategy<TModel> where TModel : AbstractModel
	{
		IReadOnlyList<TModel> Merge(IReadOnlyList<TModel> source, TModel[] additional);
	}
	internal static class ContentMergeStrategies
	{
		internal static IContentEnumerableMergeStrategy<TModel> GetEnumerable<TModel>(ContentMergeMode mode) where TModel : AbstractModel
		{
			if (mode == ContentMergeMode.MergeDistinctById)
			{
				return MergeDistinctByIdEnumerableStrategy<TModel>.Instance;
			}
			return AppendDistinctByIdEnumerableStrategy<TModel>.Instance;
		}

		internal static IContentListMergeStrategy<TModel> GetList<TModel>() where TModel : AbstractModel
		{
			return DistinctByIdListStrategy<TModel>.Instance;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Appends items whose <see cref="P:MegaCrit.Sts2.Core.Models.AbstractModel.Id" /> is not already in
		///         <paramref name="destination" />.
		///     </para>
		///     <para xml:lang="zh-CN">追加 ID 尚未出现在 <paramref name="destination" /> 中的项。</para>
		/// </summary>
		internal static void AppendDistinctById<TModel>(List<TModel> destination, IEnumerable<TModel> items) where TModel : AbstractModel
		{
			HashSet<ModelId> known = ((destination.Count == 0) ? new HashSet<ModelId>() : destination.Select((TModel model) => ((AbstractModel)model).Id).ToHashSet());
			destination.AddRange(items.Where((TModel item) => known.Add(((AbstractModel)item).Id)));
		}
	}
	internal sealed class AppendDistinctByIdEnumerableStrategy<TModel> : IContentEnumerableMergeStrategy<TModel> where TModel : AbstractModel
	{
		internal static readonly AppendDistinctByIdEnumerableStrategy<TModel> Instance = new AppendDistinctByIdEnumerableStrategy<TModel>();

		public IEnumerable<TModel> Merge(IEnumerable<TModel> source, TModel[] additional)
		{
			if (additional.Length == 0)
			{
				return (source as TModel[]) ?? source.ToArray();
			}
			List<TModel> list = new List<TModel>();
			list.AddRange(source.Concat(additional).DistinctBy((TModel model) => ((AbstractModel)model).Id));
			return new <>z__ReadOnlyList<TModel>(list);
		}
	}
	internal sealed class MergeDistinctByIdEnumerableStrategy<TModel> : IContentEnumerableMergeStrategy<TModel> where TModel : AbstractModel
	{
		internal static readonly MergeDistinctByIdEnumerableStrategy<TModel> Instance = new MergeDistinctByIdEnumerableStrategy<TModel>();

		public IEnumerable<TModel> Merge(IEnumerable<TModel> source, TModel[] additional)
		{
			if (additional.Length != 0)
			{
				List<TModel> list = new List<TModel>();
				list.AddRange(source.Concat(additional).DistinctBy((TModel model) => ((AbstractModel)model).Id));
				return new <>z__ReadOnlyList<TModel>(list);
			}
			return source;
		}
	}
	internal sealed class DistinctByIdListStrategy<TModel> : IContentListMergeStrategy<TModel> where TModel : AbstractModel
	{
		internal static readonly DistinctByIdListStrategy<TModel> Instance = new DistinctByIdListStrategy<TModel>();

		public IReadOnlyList<TModel> Merge(IReadOnlyList<TModel> source, TModel[] additional)
		{
			if (additional.Length == 0)
			{
				return source;
			}
			List<TModel> list = new List<TModel>(source);
			ContentMergeStrategies.AppendDistinctById(list, additional);
			return list;
		}
	}
	internal static class ContentSourceHoverTipFactory
	{
		internal readonly record struct ContentSourceInfo(string Id, string DisplayName)
		{
			public static ContentSourceInfo Vanilla { get; } = new ContentSourceInfo("Vanilla", "Slay the Spire 2");

			public static ContentSourceInfo BaseLib { get; } = new ContentSourceInfo("BaseLib", "BaseLib");

			public static ContentSourceInfo Unknown { get; } = new ContentSourceInfo("Unknown", "Unknown");

			public bool IsVanilla => string.Equals(Id, Vanilla.Id, StringComparison.OrdinalIgnoreCase);

			public string Format()
			{
				return RitsuLibSettingsStore.GetModSourceHoverTipsDisplayStyle() switch
				{
					ContentSourceDisplayStyle.Name => DisplayName, 
					ContentSourceDisplayStyle.Id => Id, 
					_ => string.Equals(DisplayName, Id, StringComparison.OrdinalIgnoreCase) ? DisplayName : (DisplayName + " (" + Id + ")"), 
				};
			}

			public string FormatForBbCode()
			{
				return StringHelper.EscapeBbcodeTags(ApplyFormatTemplate(RitsuLibSettingsStore.GetModSourceHoverTipsFormat(), Format(), DisplayName, Id));
			}

			public string FormatLineForBbCode()
			{
				return $"[color={RitsuLibSettingsStore.GetModSourceHoverTipsColor()}]{FormatForBbCode()}[/color]";
			}

			private static string ApplyFormatTemplate(string template, string source, string displayName, string id)
			{
				StringBuilder stringBuilder = new StringBuilder(template.Length + source.Length);
				int num = 0;
				while (num < template.Length)
				{
					if (template.AsSpan(num).StartsWith("{source}", StringComparison.Ordinal))
					{
						stringBuilder.Append(source);
						num += "{source}".Length;
					}
					else if (template.AsSpan(num).StartsWith("{name}", StringComparison.Ordinal))
					{
						stringBuilder.Append(displayName);
						num += "{name}".Length;
					}
					else if (template.AsSpan(num).StartsWith("{id}", StringComparison.Ordinal))
					{
						stringBuilder.Append(id);
						num += "{id}".Length;
					}
					else
					{
						stringBuilder.Append(template[num]);
						num++;
					}
				}
				return stringBuilder.ToString();
			}
		}

		private static class BaseLibKeywordSourceResolver
		{
			private const string CustomKeywordsTypeName = "BaseLib.Patches.Content.CustomKeywords";

			private const string KeywordIdsFieldName = "KeywordIDs";

			private static readonly Lazy<IDictionary?> KeywordIds = new Lazy<IDictionary>(FindKeywordIds);

			internal static bool Contains(CardKeyword keyword)
			{
				//IL_0010: Unknown result type (might be due to invalid IL or missing references)
				//IL_0016: Expected I4, but got Unknown
				return KeywordIds.Value?.Contains((int)keyword) ?? false;
			}

			private static IDictionary? FindKeywordIds()
			{
				return ((from assembly in AppDomain.CurrentDomain.GetAssemblies()
					select assembly.GetType("BaseLib.Patches.Content.CustomKeywords", throwOnError: false)).FirstOrDefault((Type type) => type != null)?.GetField("KeywordIDs", BindingFlags.Static | BindingFlags.Public))?.GetValue(null) as IDictionary;
			}
		}

		private const string TitleKey = "ritsulib.modSourceHoverTip.title";

		private const string LocTableStem = "MOD_SETTINGS";

		private const string TipIdPrefix = "ritsulib:content_source:";

		private static readonly Assembly GameAssembly = typeof(AbstractModel).Assembly;

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<Type, ContentSourceInfo> SourceByModelType = new Dictionary<Type, ContentSourceInfo>();

		private static bool _registrationsFrozen;

		private static readonly Dictionary<string, ContentSourceInfo> SourceByModId = new Dictionary<string, ContentSourceInfo>(StringComparer.OrdinalIgnoreCase);

		internal static bool TryCreate(AbstractModel model, out IHoverTip tip)
		{
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			if (!TryResolve(model, out var source))
			{
				tip = null;
				return false;
			}
			tip = (IHoverTip)(object)CreateTip(source);
			return true;
		}

		internal static bool TryResolve(AbstractModel model, out ContentSourceInfo source)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			if (!RitsuLibSettingsStore.IsModSourceHoverTipsEnabled() || !IsModelSectionEnabled(model))
			{
				source = default(ContentSourceInfo);
				return false;
			}
			source = ((model is IContentSourceSupplier supplier) ? Resolve(supplier) : Resolve(((object)model).GetType()));
			return ShouldShow(source);
		}

		internal static bool ShouldShow(ContentSourceInfo source)
		{
			if (source.IsVanilla)
			{
				return RitsuLibSettingsStore.ShouldIncludeVanillaModSourceHoverTips();
			}
			return true;
		}

		private static bool IsModelSectionEnabled(AbstractModel model)
		{
			if (!(model is CardModel))
			{
				if (!(model is RelicModel))
				{
					if (!(model is PotionModel))
					{
						if (!(model is PowerModel))
						{
							if (!(model is OrbModel))
							{
								if (!(model is EnchantmentModel))
								{
									if (!(model is AfflictionModel))
									{
										if (model is MonsterModel)
										{
											return RitsuLibSettingsStore.ShouldShowCreatureModSourceHoverTips();
										}
										return true;
									}
									return RitsuLibSettingsStore.ShouldShowAfflictionModSourceHoverTips();
								}
								return RitsuLibSettingsStore.ShouldShowEnchantmentModSourceHoverTips();
							}
							return RitsuLibSettingsStore.ShouldShowOrbModSourceHoverTips();
						}
						return RitsuLibSettingsStore.ShouldShowPowerModSourceHoverTips();
					}
					return RitsuLibSettingsStore.ShouldShowPotionModSourceHoverTips();
				}
				return RitsuLibSettingsStore.ShouldShowRelicModSourceHoverTips();
			}
			return RitsuLibSettingsStore.ShouldShowCardModSourceHoverTips();
		}

		private static HoverTip CreateTip(ContentSourceInfo source)
		{
			//IL_002c: Unknown result type (might be due to invalid IL or missing references)
			HoverTip result = default(HoverTip);
			((HoverTip)(ref result))..ctor(GetTitle(), source.FormatLineForBbCode(), (Texture2D)null);
			((HoverTip)(ref result)).Id = "ritsulib:content_source:" + source.Id;
			return result;
		}

		internal static LocString GetTitle()
		{
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0030: Expected O, but got Unknown
			I18NLocTableBridge.TryRegister("com.ritsukage.sts2-RitsuLib", ModSettingsLocalization.Instance, "MOD_SETTINGS");
			return new LocString(I18NLocTableBridge.GetTableId("com.ritsukage.sts2-RitsuLib", "MOD_SETTINGS"), "ritsulib.modSourceHoverTip.title");
		}

		internal static ContentSourceInfo Resolve(Type modelType)
		{
			bool registrationsFrozen;
			using (SyncRoot.EnterScope())
			{
				registrationsFrozen = _registrationsFrozen;
				if (registrationsFrozen && SourceByModelType.TryGetValue(modelType, out var value))
				{
					return value;
				}
			}
			ContentSourceInfo contentSourceInfo = ResolveUncached(modelType, registrationsFrozen);
			if (!registrationsFrozen)
			{
				return contentSourceInfo;
			}
			using (SyncRoot.EnterScope())
			{
				SourceByModelType[modelType] = contentSourceInfo;
				return contentSourceInfo;
			}
		}

		internal static ContentSourceInfo ResolveKeyword(CardKeyword keyword)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_000e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0024: Unknown result type (might be due to invalid IL or missing references)
			if (Enum.IsDefined<CardKeyword>(keyword))
			{
				return ContentSourceInfo.Vanilla;
			}
			if (ModKeywordRegistry.TryGetByCardKeyword(keyword, out ModKeywordDefinition definition))
			{
				return ResolveMod(definition.ModId);
			}
			if (!TryResolveBaseLibKeyword(keyword, out var source))
			{
				return ContentSourceInfo.Unknown;
			}
			return source;
		}

		internal static ContentSourceInfo Resolve(IContentSourceSupplier supplier)
		{
			ContentSourceDescriptor contentSource = supplier.ContentSource;
			string text = NormalizeModId(contentSource.ModId);
			if (string.Equals(text, ContentSourceInfo.Vanilla.Id, StringComparison.OrdinalIgnoreCase))
			{
				return ContentSourceInfo.Vanilla;
			}
			string displayName = (string.IsNullOrWhiteSpace(contentSource.DisplayName) ? ModSettingsLocalization.ResolveModName(text, text) : contentSource.DisplayName);
			return new ContentSourceInfo(text, NormalizeDisplayName(displayName, text));
		}

		internal static void FreezeRegistrations()
		{
			using (SyncRoot.EnterScope())
			{
				if (!_registrationsFrozen)
				{
					SourceByModelType.Clear();
					SourceByModId.Clear();
					_registrationsFrozen = true;
				}
			}
		}

		private static ContentSourceInfo ResolveUncached(Type modelType, bool shouldCache)
		{
			Assembly assembly = modelType.Assembly;
			if (assembly == GameAssembly)
			{
				return ContentSourceInfo.Vanilla;
			}
			if (ModContentRegistry.TryGetOwnerModId(modelType, out string modId))
			{
				return ResolveMod(modId, shouldCache);
			}
			foreach (Mod item in Sts2ModManagerCompat.EnumerateModsForManifestLookup())
			{
				if (Sts2ModManagerCompat.GetAssemblies(item).Contains(assembly))
				{
					string text = NormalizeModId(item.manifest?.id, assembly);
					string displayName = NormalizeDisplayName(item.manifest?.name, text);
					return CacheModSource(new ContentSourceInfo(text, displayName), shouldCache);
				}
			}
			string? obj = assembly.GetName().Name ?? modelType.Namespace ?? modelType.Name;
			return new ContentSourceInfo(obj, obj);
		}

		private static ContentSourceInfo ResolveMod(string modId)
		{
			bool registrationsFrozen;
			using (SyncRoot.EnterScope())
			{
				registrationsFrozen = _registrationsFrozen;
				if (registrationsFrozen && SourceByModId.TryGetValue(modId, out var value))
				{
					return value;
				}
			}
			return ResolveMod(modId, registrationsFrozen);
		}

		private static ContentSourceInfo ResolveMod(string modId, bool shouldCache)
		{
			string displayName = ModSettingsLocalization.ResolveModName(modId, modId);
			return CacheModSource(new ContentSourceInfo(modId, NormalizeDisplayName(displayName, modId)), shouldCache);
		}

		private static bool TryResolveBaseLibKeyword(CardKeyword keyword, out ContentSourceInfo source)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			if (!BaseLibKeywordSourceResolver.Contains(keyword))
			{
				source = default(ContentSourceInfo);
				return false;
			}
			source = ContentSourceInfo.BaseLib;
			return true;
		}

		private static ContentSourceInfo CacheModSource(ContentSourceInfo source, bool shouldCache)
		{
			if (!shouldCache)
			{
				return source;
			}
			using (SyncRoot.EnterScope())
			{
				SourceByModId[source.Id] = source;
				return source;
			}
		}

		private static string NormalizeModId(string? modId, Assembly assembly)
		{
			if (!string.IsNullOrWhiteSpace(modId))
			{
				return NormalizeModId(modId);
			}
			return assembly.GetName().Name ?? "<unknown>";
		}

		private static string NormalizeModId(string? modId)
		{
			if (!string.IsNullOrWhiteSpace(modId))
			{
				return modId.Trim();
			}
			return "<unknown>";
		}

		private static string NormalizeDisplayName(string? displayName, string fallback)
		{
			if (!string.IsNullOrWhiteSpace(displayName))
			{
				return displayName.Trim();
			}
			return fallback;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Resolves stable content-source metadata independently of content-source hover-tip preferences.
	///     </para>
	///     <para xml:lang="zh-CN">独立于内容来源悬浮提示偏好，解析稳定的内容来源元数据。</para>
	/// </summary>
	public static class ContentSourceResolver
	{
		/// <summary>
		///     <para xml:lang="en">Resolves the source of a model, including a model-supplied override when present.</para>
		///     <para xml:lang="zh-CN">解析模型的来源；模型提供来源覆盖时优先使用该覆盖。</para>
		/// </summary>
		/// <param name="model">
		///     <para xml:lang="en">The model to inspect.</para>
		///     <para xml:lang="zh-CN">要检查的模型。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         A normalized descriptor. Unresolved sources use <c>Unknown</c> as both the ID and display name.
		///     </para>
		///     <para xml:lang="zh-CN">规范化后的描述；无法解析的来源会使用 <c>Unknown</c> 作为 ID 和显示名称。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">Thrown when <paramref name="model" /> is null.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="model" /> 为 null 时抛出。</para>
		/// </exception>
		public static ContentSourceDescriptor Resolve(AbstractModel model)
		{
			ArgumentNullException.ThrowIfNull(model, "model");
			ContentSourceHoverTipFactory.ContentSourceInfo contentSourceInfo = ((model is IContentSourceSupplier supplier) ? ContentSourceHoverTipFactory.Resolve(supplier) : ContentSourceHoverTipFactory.Resolve(((object)model).GetType()));
			return new ContentSourceDescriptor(contentSourceInfo.Id, contentSourceInfo.DisplayName);
		}

		/// <summary>
		///     <para xml:lang="en">Resolves the source associated with an <see cref="T:MegaCrit.Sts2.Core.Models.AbstractModel" /> type.</para>
		///     <para xml:lang="zh-CN">解析与 <see cref="T:MegaCrit.Sts2.Core.Models.AbstractModel" /> 类型关联的来源。</para>
		/// </summary>
		/// <param name="modelType">
		///     <para xml:lang="en">A concrete or abstract model type to inspect.</para>
		///     <para xml:lang="zh-CN">要检查的具体或抽象模型类型。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         A normalized descriptor. Unresolved sources use <c>Unknown</c> as both the ID and display name.
		///     </para>
		///     <para xml:lang="zh-CN">规范化后的描述；无法解析的来源会使用 <c>Unknown</c> 作为 ID 和显示名称。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">Thrown when <paramref name="modelType" /> is null.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="modelType" /> 为 null 时抛出。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">Thrown when <paramref name="modelType" /> is not an <see cref="T:MegaCrit.Sts2.Core.Models.AbstractModel" /> type.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="modelType" /> 不是 <see cref="T:MegaCrit.Sts2.Core.Models.AbstractModel" /> 类型时抛出。</para>
		/// </exception>
		public static ContentSourceDescriptor Resolve(Type modelType)
		{
			ArgumentNullException.ThrowIfNull(modelType, "modelType");
			if (!typeof(AbstractModel).IsAssignableFrom(modelType))
			{
				throw new ArgumentException("The type must derive from AbstractModel.", "modelType");
			}
			ContentSourceHoverTipFactory.ContentSourceInfo contentSourceInfo = ContentSourceHoverTipFactory.Resolve(modelType);
			return new ContentSourceDescriptor(contentSourceInfo.Id, contentSourceInfo.DisplayName);
		}
	}
	internal static class DynamicActContentPatcher
	{
		private const BindingFlags DeclaredInstanceFlags = BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;

		private static readonly Lock SyncRoot = new Lock();

		private static bool _patched;

		internal static void EnsurePatched()
		{
			using (SyncRoot.EnterScope())
			{
				if (!_patched)
				{
					Logger logger = RitsuLibFramework.Logger;
					Type[] array = (from type in ReflectionHelper.GetSubtypes<ActModel>().Concat(ReflectionHelper.GetSubtypesInMods<ActModel>()).Concat(ModContentRegistry.GetRegisteredActTypes())
						where (object)type != null && !type.IsAbstract && !type.IsInterface
						select type).Distinct().ToArray();
					DynamicPatchBuilder builder = new DynamicPatchBuilder("dynamic_act_content");
					HarmonyMethod postfix = DynamicPatchBuilder.FromMethod(typeof(DynamicActContentPatcher), "AllEventsPostfix");
					HarmonyMethod postfix2 = DynamicPatchBuilder.FromMethod(typeof(DynamicActContentPatcher), "AllAncientsPostfix");
					HarmonyMethod postfix3 = DynamicPatchBuilder.FromMethod(typeof(DynamicActContentPatcher), "AllEncountersPostfix");
					HarmonyMethod postfix4 = DynamicPatchBuilder.FromMethod(typeof(DynamicActContentPatcher), "BossDiscoveryOrderPostfix");
					HarmonyMethod postfix5 = DynamicPatchBuilder.FromMethod(typeof(DynamicActContentPatcher), "GetUnlockedAncientsPostfix");
					HashSet<MethodInfo> queuedMethods = new HashSet<MethodInfo>();
					Type[] array2 = array;
					foreach (Type actType in array2)
					{
						TryAddPropertyGetterPatch(builder, actType, "AllEvents", postfix, queuedMethods, logger);
						TryAddPropertyGetterPatch(builder, actType, "AllAncients", postfix2, queuedMethods, logger);
						TryAddPropertyGetterPatch(builder, actType, "BossDiscoveryOrder", postfix4, queuedMethods, logger);
						TryAddMethodPatch(builder, actType, "GenerateAllEncounters", Array.Empty<Type>(), postfix3, queuedMethods, logger);
						TryAddMethodPatch(builder, actType, "GetUnlockedAncients", new Type[1] { typeof(UnlockState) }, postfix5, queuedMethods, logger);
					}
					if (!RitsuLibFramework.GetFrameworkPatcher(RitsuLibFramework.FrameworkPatcherArea.ContentRegistry).ApplyDynamic(builder))
					{
						throw new InvalidOperationException("Failed to apply dynamic Act content patches.");
					}
					_patched = true;
					logger.Info($"[Content] Dynamic act content patching initialized for {array.Length} act type(s).", 1);
				}
			}
		}

		private static void TryAddPropertyGetterPatch(DynamicPatchBuilder builder, Type actType, string propertyName, HarmonyMethod postfix, HashSet<MethodInfo> queuedMethods, Logger logger)
		{
			MethodInfo methodInfo = FindDeclaredPropertyGetter(actType, propertyName);
			if (methodInfo == null || !queuedMethods.Add(methodInfo))
			{
				return;
			}
			try
			{
				builder.Add(methodInfo, null, postfix, null, null, isCritical: true, $"Patch {methodInfo.DeclaringType?.Name}.{propertyName} for dynamic mod content");
			}
			catch (Exception ex)
			{
				queuedMethods.Remove(methodInfo);
				logger.Warn($"[Content] Could not queue getter '{methodInfo.DeclaringType?.Name}.{propertyName}' for dynamic patching: {ex.Message}", 1);
			}
		}

		private static void TryAddMethodPatch(DynamicPatchBuilder builder, Type actType, string methodName, Type[] parameterTypes, HarmonyMethod postfix, HashSet<MethodInfo> queuedMethods, Logger logger)
		{
			MethodInfo methodInfo = FindDeclaredMethodImplementation(actType, methodName, parameterTypes);
			if (methodInfo == null || !queuedMethods.Add(methodInfo))
			{
				return;
			}
			try
			{
				builder.Add(methodInfo, null, postfix, null, null, isCritical: true, $"Patch {methodInfo.DeclaringType?.Name}.{methodName} for dynamic mod content");
			}
			catch (Exception ex)
			{
				queuedMethods.Remove(methodInfo);
				logger.Warn($"[Content] Could not queue method '{methodInfo.DeclaringType?.Name}.{methodName}' for dynamic patching: {ex.Message}", 1);
			}
		}

		private static MethodInfo? FindDeclaredPropertyGetter(Type concreteActType, string propertyName)
		{
			Type type = concreteActType;
			while (type != null && typeof(ActModel).IsAssignableFrom(type))
			{
				MethodInfo methodInfo = type.GetProperty(propertyName, BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetMethod;
				if ((object)methodInfo != null && !methodInfo.IsAbstract)
				{
					return methodInfo;
				}
				type = type.BaseType;
			}
			return null;
		}

		private static MethodInfo? FindDeclaredMethodImplementation(Type concreteActType, string methodName, Type[] parameterTypes)
		{
			Type type = concreteActType;
			while (type != null && typeof(ActModel).IsAssignableFrom(type))
			{
				MethodInfo method = type.GetMethod(methodName, BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, parameterTypes, null);
				if ((object)method != null && !method.IsAbstract)
				{
					return method;
				}
				type = type.BaseType;
			}
			return null;
		}

		private static void AllEventsPostfix(ActModel __instance, ref IEnumerable<EventModel> __result)
		{
			__result = ModelDbGetterMerge.MergeEnumerable<EventModel>(__result, (Func<IEnumerable<EventModel>, IEnumerable<EventModel>>)((IEnumerable<EventModel> source) => ModContentRegistry.AppendActEvents(__instance, source)));
		}

		private static void AllAncientsPostfix(ActModel __instance, ref IEnumerable<AncientEventModel> __result)
		{
			__result = ModelDbGetterMerge.MergeEnumerable<AncientEventModel>(__result, (Func<IEnumerable<AncientEventModel>, IEnumerable<AncientEventModel>>)((IEnumerable<AncientEventModel> source) => ModContentRegistry.AppendActAncients(__instance, source)));
		}

		private static void AllEncountersPostfix(ActModel __instance, ref IEnumerable<EncounterModel> __result)
		{
			__result = ModelDbGetterMerge.MergeEnumerable<EncounterModel>(__result, (Func<IEnumerable<EncounterModel>, IEnumerable<EncounterModel>>)((IEnumerable<EncounterModel> source) => ModEncounterActValidityFilter.FilterForAct(__instance, ModContentRegistry.AppendGlobalEncounters(ModContentRegistry.AppendActEncounters(__instance, source)))));
		}

		private static void BossDiscoveryOrderPostfix(ActModel __instance, ref IEnumerable<EncounterModel> __result)
		{
			__result = ModEncounterActValidityFilter.FilterForAct(__instance, __result);
		}

		private static void GetUnlockedAncientsPostfix(ActModel __instance, UnlockState __0, ref IEnumerable<AncientEventModel> __result)
		{
			__result = ModAncientActValidityFilter.FilterForAct(__instance, ModUnlockRegistry.FilterUnlocked<AncientEventModel>(ModelDbGetterMerge.MergeEnumerable<AncientEventModel>(__result, (Func<IEnumerable<AncientEventModel>, IEnumerable<AncientEventModel>>)((IEnumerable<AncientEventModel> source) => ModContentRegistry.AppendActAncients(__instance, source))), __0));
		}
	}
	internal static class DynamicCharacterStarterContentPatcher
	{
		private static readonly Lock SyncRoot = new Lock();

		private static bool _patched;

		internal static void EnsurePatched()
		{
			using (SyncRoot.EnterScope())
			{
				if (!_patched)
				{
					Logger logger = RitsuLibFramework.Logger;
					Type[] array = ReflectionHelper.GetSubtypes<CharacterModel>().Concat(ReflectionHelper.GetSubtypesInMods<CharacterModel>()).Distinct()
						.ToArray();
					DynamicPatchBuilder builder = new DynamicPatchBuilder("dynamic_character_starter");
					HarmonyMethod postfix = DynamicPatchBuilder.FromMethod(typeof(DynamicCharacterStarterContentPatcher), "StartingDeckPostfix");
					HarmonyMethod postfix2 = DynamicPatchBuilder.FromMethod(typeof(DynamicCharacterStarterContentPatcher), "StartingRelicsPostfix");
					HarmonyMethod postfix3 = DynamicPatchBuilder.FromMethod(typeof(DynamicCharacterStarterContentPatcher), "StartingPotionsPostfix");
					HashSet<MethodInfo> queuedGetters = new HashSet<MethodInfo>();
					Type[] array2 = array;
					foreach (Type concreteCharacterType in array2)
					{
						TryAddCharacterPropertyGetter(builder, concreteCharacterType, "StartingDeck", postfix, queuedGetters, logger);
						TryAddCharacterPropertyGetter(builder, concreteCharacterType, "StartingRelics", postfix2, queuedGetters, logger);
						TryAddCharacterPropertyGetter(builder, concreteCharacterType, "StartingPotions", postfix3, queuedGetters, logger);
					}
					if (!RitsuLibFramework.GetFrameworkPatcher(RitsuLibFramework.FrameworkPatcherArea.ContentRegistry).ApplyDynamic(builder))
					{
						throw new InvalidOperationException("Failed to apply dynamic character starter content patches.");
					}
					_patched = true;
					logger.Info($"[Content] Dynamic character starter patching initialized for {array.Length} character type(s).", 1);
				}
			}
		}

		private static void TryAddCharacterPropertyGetter(DynamicPatchBuilder builder, Type concreteCharacterType, string propertyName, HarmonyMethod postfix, HashSet<MethodInfo> queuedGetters, Logger logger)
		{
			MethodInfo methodInfo = FindDeclaredPropertyGetter(concreteCharacterType, propertyName);
			if (methodInfo == null || IsModCharacterTemplateGetter(methodInfo) || !queuedGetters.Add(methodInfo))
			{
				return;
			}
			try
			{
				builder.Add(methodInfo, null, postfix, null, null, isCritical: true, "Patch character starter merge " + methodInfo.DeclaringType?.Name + "." + propertyName);
			}
			catch (Exception ex)
			{
				queuedGetters.Remove(methodInfo);
				logger.Warn($"[Content] Could not patch '{methodInfo.DeclaringType?.Name}.{propertyName}' for starter merge: {ex.Message}", 1);
			}
		}

		private static MethodInfo? FindDeclaredPropertyGetter(Type concreteCharacterType, string propertyName)
		{
			Type type = concreteCharacterType;
			while (type != null && typeof(CharacterModel).IsAssignableFrom(type))
			{
				PropertyInfo property = type.GetProperty(propertyName, BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				if (property?.GetMethod != null)
				{
					return property.GetMethod;
				}
				type = type.BaseType;
			}
			return null;
		}

		private static bool IsModCharacterTemplateGetter(MethodInfo getter)
		{
			Type declaringType = getter.DeclaringType;
			if ((object)declaringType != null && declaringType.IsGenericType)
			{
				return declaringType.GetGenericTypeDefinition() == typeof(ModCharacterTemplate<, , >);
			}
			return false;
		}

		private static void StartingDeckPostfix(CharacterModel __instance, ref IEnumerable<CardModel> __result)
		{
			Type[] registeredCharacterStarterCards = ModContentRegistry.GetRegisteredCharacterStarterCards(((object)__instance).GetType());
			if (registeredCharacterStarterCards.Length != 0)
			{
				List<CardModel> list = new List<CardModel>();
				list.AddRange(__result);
				list.AddRange(registeredCharacterStarterCards.Select((Type t) => ModelDb.GetById<CardModel>(ModelDb.GetId(t))));
				__result = new <>z__ReadOnlyList<CardModel>(list);
			}
		}

		private static void StartingRelicsPostfix(CharacterModel __instance, ref IReadOnlyList<RelicModel> __result)
		{
			Type[] registeredCharacterStarterRelics = ModContentRegistry.GetRegisteredCharacterStarterRelics(((object)__instance).GetType());
			if (registeredCharacterStarterRelics.Length != 0)
			{
				List<RelicModel> list = new List<RelicModel>();
				list.AddRange(__result);
				list.AddRange(registeredCharacterStarterRelics.Select((Type t) => ModelDb.GetById<RelicModel>(ModelDb.GetId(t))));
				__result = new <>z__ReadOnlyList<RelicModel>(list);
			}
		}

		private static void StartingPotionsPostfix(CharacterModel __instance, ref IReadOnlyList<PotionModel> __result)
		{
			Type[] registeredCharacterStarterPotions = ModContentRegistry.GetRegisteredCharacterStarterPotions(((object)__instance).GetType());
			if (registeredCharacterStarterPotions.Length != 0)
			{
				List<PotionModel> list = new List<PotionModel>();
				list.AddRange(__result);
				list.AddRange(registeredCharacterStarterPotions.Select((Type t) => ModelDb.GetById<PotionModel>(ModelDb.GetId(t))));
				__result = new <>z__ReadOnlyList<PotionModel>(list);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Describes the source displayed for a piece of content.</para>
	///     <para xml:lang="zh-CN">描述为一项内容显示的来源。</para>
	/// </summary>
	public readonly record struct ContentSourceDescriptor
	{
		/// <summary>
		///     <para xml:lang="en">Gets the source mod ID, or <c>Vanilla</c> for base-game content.</para>
		///     <para xml:lang="zh-CN">获取来源模组 ID；原版内容使用 <c>Vanilla</c>。</para>
		/// </summary>
		public string ModId { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional source display name.</para>
		///     <para xml:lang="zh-CN">获取可选的来源显示名称。</para>
		/// </summary>
		public string? DisplayName { get; init; }

		/// <summary>
