		public static bool IsFrozen { get; private set; }

		/// <summary>
		///     <para xml:lang="en">Gets the current <see cref="T:STS2RitsuLib.Content.ContentRegistrationState" />.</para>
		///     <para xml:lang="zh-CN">获取当前的 <see cref="T:STS2RitsuLib.Content.ContentRegistrationState" />。</para>
		/// </summary>
		public static ContentRegistrationState State
		{
			get
