		/// <summary>
		///     <para xml:lang="en">Requests one multiplayer map-selection synchronization after act replacement.</para>
		///     <para xml:lang="zh-CN">请求在替换章节后执行一次多人地图选择同步。</para>
		/// </summary>
		internal static void RequestActEnterPostMapUiMapSyncBump()
		{
			Interlocked.Exchange(ref _actEnterPostMapUiMapSyncBumpPending, 1);
		}

		internal static bool TryConsumeActEnterPostMapUiMapSyncBump()
		{
			return Interlocked.Exchange(ref _actEnterPostMapUiMapSyncBumpPending, 0) != 0;
		}

		private static Action<RunState, IReadOnlyList<ActModel>> CreateRunStateActsSetter()
		{
			MethodInfo set = typeof(RunState).GetProperty("Acts", BindingFlags.Instance | BindingFlags.Public)?.GetSetMethod(nonPublic: true) ?? throw new InvalidOperationException("RunState.Acts setter not found.");
			return delegate(RunState rs, IReadOnlyList<ActModel> acts)
			{
				set.Invoke(rs, new object[1] { acts });
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a rule that replaces <paramref name="slotIndex" /> with
		///         <typeparamref name="TAct" /> when eligible. Higher priority wins, with earlier registration
		///         breaking ties.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册一条在符合条件时将 <paramref name="slotIndex" /> 替换为
		///         <typeparamref name="TAct" /> 的规则。优先级较高者胜出，同优先级时先注册者胜出。
		///     </para>
		/// </summary>
		public void RegisterActEnterForce<TAct>(int slotIndex, int priority, Func<ActEnterResolveContext, bool> eligibility) where TAct : ActModel
		{
			ArgumentOutOfRangeException.ThrowIfNegative(slotIndex, "slotIndex");
			ArgumentNullException.ThrowIfNull(eligibility, "eligibility");
			EnsureMutable($"register act enter force at slot {slotIndex}");
			EnsureModelType(typeof(TAct), typeof(ActModel), "TAct");
			using (SyncRoot.EnterScope())
			{
				int tieBreakOrder = ++_actEnterForceTieBreakSeq;
				ActEnterForces.Add(new ActEnterForceEntry(slotIndex, typeof(TAct), priority, tieBreakOrder, eligibility));
				Interlocked.Increment(ref _actEnterRegistrationCount);
			}
			_logger.Info($"[Content] Registered act enter force: slot {slotIndex} priority {priority} -> {typeof(TAct).Name}", 1);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Declares a uniform act-entry pool for <paramref name="slotIndex" />. Register this before
		///         adding candidates.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="slotIndex" /> 声明均匀章节进入池。必须先声明再添加候选章节。
		///     </para>
		/// </summary>
		public void RegisterActEnterUniformPool(int slotIndex)
		{
			ArgumentOutOfRangeException.ThrowIfNegative(slotIndex, "slotIndex");
			EnsureMutable($"register act enter uniform pool at slot {slotIndex}");
			using (SyncRoot.EnterScope())
			{
				if (ActEnterPoolModes.TryGetValue(slotIndex, out var value) && value != ActEnterPoolModeKind.Uniform)
				{
					throw new InvalidOperationException($"Act slot {slotIndex} already uses {value}; cannot register uniform pool.");
				}
				ActEnterPoolModes[slotIndex] = ActEnterPoolModeKind.Uniform;
				Interlocked.Increment(ref _actEnterRegistrationCount);
			}
			_logger.Info($"[Content] Registered act enter uniform pool: slot {slotIndex}", 1);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds an eligible candidate to the uniform pool for <paramref name="slotIndex" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="slotIndex" /> 的均匀池添加符合条件的候选章节。
		///     </para>
		/// </summary>
		public void RegisterActEnterUniformPoolCandidate<TAct>(int slotIndex, Func<ActEnterResolveContext, bool> eligibility) where TAct : ActModel
		{
			ArgumentOutOfRangeException.ThrowIfNegative(slotIndex, "slotIndex");
			ArgumentNullException.ThrowIfNull(eligibility, "eligibility");
			EnsureMutable($"register act enter uniform pool candidate at slot {slotIndex}");
			EnsureModelType(typeof(TAct), typeof(ActModel), "TAct");
			using (SyncRoot.EnterScope())
			{
				RequirePoolMode(slotIndex, ActEnterPoolModeKind.Uniform, "uniform pool candidate");
				ActEnterUniformPoolCandidates.Add(new ActEnterUniformPoolCandidateEntry(slotIndex, typeof(TAct), eligibility));
				Interlocked.Increment(ref _actEnterRegistrationCount);
			}
			_logger.Info($"[Content] Registered act enter uniform pool candidate: slot {slotIndex} -> {typeof(TAct).Name}", 1);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Declares a weighted act-entry pool for <paramref name="slotIndex" />. Register this before
		///         adding candidates or a baseline.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为 <paramref name="slotIndex" /> 声明加权章节进入池。必须先声明再添加候选章节或基线。
		///     </para>
		/// </summary>
		public void RegisterActEnterWeightedPool(int slotIndex)
		{
			ArgumentOutOfRangeException.ThrowIfNegative(slotIndex, "slotIndex");
			EnsureMutable($"register act enter weighted pool at slot {slotIndex}");
			using (SyncRoot.EnterScope())
			{
				if (ActEnterPoolModes.TryGetValue(slotIndex, out var value) && value != ActEnterPoolModeKind.Weighted)
				{
					throw new InvalidOperationException($"Act slot {slotIndex} already uses {value}; cannot register weighted pool.");
				}
				ActEnterPoolModes[slotIndex] = ActEnterPoolModeKind.Weighted;
				Interlocked.Increment(ref _actEnterRegistrationCount);
			}
			_logger.Info($"[Content] Registered act enter weighted pool: slot {slotIndex}", 1);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Adds an eligible candidate and its weight provider to a weighted act-entry pool.
		///     </para>
		///     <para xml:lang="zh-CN">向加权章节进入池添加符合条件的候选章节及其权重提供器。</para>
		/// </summary>
		public void RegisterActEnterWeightedPoolCandidate<TAct>(int slotIndex, Func<ActEnterResolveContext, bool> eligibility, Func<ActEnterResolveContext, double> weight) where TAct : ActModel
		{
			ArgumentOutOfRangeException.ThrowIfNegative(slotIndex, "slotIndex");
			ArgumentNullException.ThrowIfNull(eligibility, "eligibility");
			ArgumentNullException.ThrowIfNull(weight, "weight");
			EnsureMutable($"register act enter weighted pool candidate at slot {slotIndex}");
			EnsureModelType(typeof(TAct), typeof(ActModel), "TAct");
			using (SyncRoot.EnterScope())
			{
				RequirePoolMode(slotIndex, ActEnterPoolModeKind.Weighted, "weighted pool candidate");
				ActEnterWeightedPoolCandidates.Add(new ActEnterWeightedPoolCandidateEntry(slotIndex, typeof(TAct), eligibility, weight));
				Interlocked.Increment(ref _actEnterRegistrationCount);
			}
			_logger.Info($"[Content] Registered act enter weighted pool candidate: slot {slotIndex} -> {typeof(TAct).Name}", 1);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers the weight of the act already occupying <paramref name="slotIndex" />. Weighted
		///         pools have no implicit baseline.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册 <paramref name="slotIndex" /> 中已有章节的权重。加权池没有隐式基线。
		///     </para>
		/// </summary>
		public void RegisterActEnterWeightedPoolBaseline(int slotIndex, Func<ActEnterResolveContext, double> weight)
		{
			ArgumentOutOfRangeException.ThrowIfNegative(slotIndex, "slotIndex");
			ArgumentNullException.ThrowIfNull(weight, "weight");
			EnsureMutable($"register act enter weighted pool baseline at slot {slotIndex}");
			using (SyncRoot.EnterScope())
			{
				RequirePoolMode(slotIndex, ActEnterPoolModeKind.Weighted, "weighted pool baseline");
				ActEnterWeightedBaselines[slotIndex] = weight;
				Interlocked.Increment(ref _actEnterRegistrationCount);
			}
			_logger.Info($"[Content] Registered act enter weighted pool baseline: slot {slotIndex}", 1);
		}

		internal static void ResolveActEnterForEnterAct(RunManager runManager, RunState runState, int enteringActIndex)
		{
			//IL_0073: Unknown result type (might be due to invalid IL or missing references)
			//IL_0079: Invalid comparison between Unknown and I4
			if (!HasAnyActEnterRegistration || (uint)enteringActIndex >= (uint)runState.Acts.Count)
			{
				return;
			}
			ActEnterForceEntry[] array;
			Dictionary<int, ActEnterPoolModeKind> dictionary;
			ActEnterUniformPoolCandidateEntry[] uniformCands;
			ActEnterWeightedPoolCandidateEntry[] weightedCands;
			Dictionary<int, Func<ActEnterResolveContext, double>> weightedBaselines;
			using (SyncRoot.EnterScope())
			{
				array = ActEnterForces.ToArray();
				dictionary = new Dictionary<int, ActEnterPoolModeKind>(ActEnterPoolModes);
				uniformCands = ActEnterUniformPoolCandidates.ToArray();
				weightedCands = ActEnterWeightedPoolCandidates.ToArray();
				weightedBaselines = new Dictionary<int, Func<ActEnterResolveContext, double>>(ActEnterWeightedBaselines);
			}
			bool isMultiplayer = runManager.NetService != null && (int)runManager.NetService.Type != 1;
			ActEnterResolveContext actEnterResolveContext = new ActEnterResolveContext(runManager, runState, enteringActIndex, runState.Rng.Niche, runState.UnlockState, isMultiplayer);
			Array.Sort(array, delegate(ActEnterForceEntry a, ActEnterForceEntry b)
			{
				int num2 = b.Priority.CompareTo(a.Priority);
				return (num2 == 0) ? a.TieBreakOrder.CompareTo(b.TieBreakOrder) : num2;
			});
			ActEnterForceEntry[] array2 = array;
			for (int num = 0; num < array2.Length; num++)
			{
				ActEnterForceEntry actEnterForceEntry = array2[num];
				if (actEnterForceEntry.SlotIndex == enteringActIndex && actEnterForceEntry.Eligibility(actEnterResolveContext))
				{
					ReplaceActAtSlot(runManager, runState, enteringActIndex, actEnterForceEntry.ActType);
					return;
				}
			}
			if (dictionary.TryGetValue(enteringActIndex, out var value))
			{
				switch (value)
				{
				case ActEnterPoolModeKind.Uniform:
					ApplyUniformPool(runManager, runState, enteringActIndex, actEnterResolveContext, uniformCands);
					return;
				case ActEnterPoolModeKind.Weighted:
					ApplyWeightedPool(runManager, runState, enteringActIndex, actEnterResolveContext, weightedCands, weightedBaselines);
					return;
				}
				throw new InvalidOperationException($"Unhandled {"ActEnterPoolModeKind"}: {value}.");
			}
		}

		private static void RequirePoolMode(int slotIndex, ActEnterPoolModeKind required, string what)
		{
			if (!ActEnterPoolModes.TryGetValue(slotIndex, out var value) || value != required)
			{
				throw new InvalidOperationException($"Slot {slotIndex}: register {required} pool before adding {what}.");
			}
		}

		private static void ReplaceActAtSlot(RunManager runManager, RunState runState, int slotIndex, Type actType)
		{
			ActModel val = runState.Acts[slotIndex];
			List<ActModel> list = runState.Acts.ToList();
			ActModel val2 = ModelDb.GetById<ActModel>(ModelDb.GetId(actType)).ToMutable();
			CopySharedAncientSubset(val, val2);
			list[slotIndex] = val2;
			RunStateActsSetter(runState, list);
			InitializeRoomsForReplacedActIfNeeded(runManager, runState, slotIndex, val);
		}

		private static void ReplaceActAtSlot(RunManager runManager, RunState runState, int slotIndex, ActModel replacementMutable)
		{
			ActModel val = runState.Acts[slotIndex];
			List<ActModel> list = runState.Acts.ToList();
			CopySharedAncientSubset(val, replacementMutable);
			list[slotIndex] = replacementMutable;
			RunStateActsSetter(runState, list);
			InitializeRoomsForReplacedActIfNeeded(runManager, runState, slotIndex, val);
		}

		private static void CopySharedAncientSubset(ActModel source, ActModel target)
		{
			if (source != target)
			{
				List<AncientEventModel> list = ActSharedAncientSubsetRef.Invoke(source);
				ActSharedAncientSubsetRef.Invoke(target) = list?.ToList();
			}
		}

		private static void InitializeRoomsForReplacedActIfNeeded(RunManager runManager, RunState runState, int actIndex, ActModel actBeforeReplace)
		{
			ActModel act = runState.Acts[actIndex];
			if (act == actBeforeReplace)
			{
				return;
			}
			RequestActEnterPostMapUiMapSyncBump();
			((AbstractModel)act).AssertMutable();
			act.GenerateRooms(runState.Rng.UpFront, runState.UnlockState, runState.Players.Count > 1);
			if (runManager.ShouldApplyTutorialModifications())
			{
				act.ApplyDiscoveryOrderModifications(runState.UnlockState);
			}
			if (actIndex == runState.Acts.Count - 1 && runManager.AscensionManager.HasLevel((AscensionLevel)10))
			{
				EncounterModel secondBossEncounter = runState.Rng.UpFront.NextItem<EncounterModel>(act.AllBossEncounters.Where((EncounterModel e) => ((AbstractModel)e).Id != ((AbstractModel)act.BossEncounter).Id));
				act.SetSecondBossEncounter(secondBossEncounter);
			}
		}

		private static void ApplyUniformPool(RunManager runManager, RunState runState, int slotIndex, ActEnterResolveContext ctx, ActEnterUniformPoolCandidateEntry[] uniformCands)
		{
			ActModel item = runState.Acts[slotIndex];
			List<ActModel> list = new List<ActModel> { item };
			for (int i = 0; i < uniformCands.Length; i++)
			{
				ActEnterUniformPoolCandidateEntry actEnterUniformPoolCandidateEntry = uniformCands[i];
				if (actEnterUniformPoolCandidateEntry.SlotIndex == slotIndex && actEnterUniformPoolCandidateEntry.Eligibility(ctx))
				{
					ActModel added = ModelDb.GetById<ActModel>(ModelDb.GetId(actEnterUniformPoolCandidateEntry.CandidateActType)).ToMutable();
					if (!list.Exists((ActModel a) => ((AbstractModel)a).Id == ((AbstractModel)added).Id))
					{
						list.Add(added);
					}
				}
			}
			if (list.Count > 1)
			{
				ReplaceActAtSlot(runManager, runState, slotIndex, list[ctx.Rng.NextInt(0, list.Count)]);
			}
		}

		private static void ApplyWeightedPool(RunManager runManager, RunState runState, int slotIndex, ActEnterResolveContext ctx, ActEnterWeightedPoolCandidateEntry[] weightedCands, Dictionary<int, Func<ActEnterResolveContext, double>> weightedBaselines)
		{
			List<(ActModel, double)> list = new List<(ActModel, double)>();
			if (weightedBaselines.TryGetValue(slotIndex, out Func<ActEnterResolveContext, double> value))
			{
				double num = value(ctx);
				if (double.IsFinite(num) && num > 0.0)
				{
					list.Add((runState.Acts[slotIndex], num));
				}
			}
			for (int i = 0; i < weightedCands.Length; i++)
			{
				ActEnterWeightedPoolCandidateEntry actEnterWeightedPoolCandidateEntry = weightedCands[i];
				if (actEnterWeightedPoolCandidateEntry.SlotIndex != slotIndex || !actEnterWeightedPoolCandidateEntry.Eligibility(ctx))
				{
					continue;
				}
				double num2 = actEnterWeightedPoolCandidateEntry.Weight(ctx);
				if (double.IsFinite(num2) && !(num2 <= 0.0))
				{
					ActModel act = ModelDb.GetById<ActModel>(ModelDb.GetId(actEnterWeightedPoolCandidateEntry.CandidateActType)).ToMutable();
					if (!list.Exists(((ActModel Act, double W) t) => ((AbstractModel)t.Act).Id == ((AbstractModel)act).Id))
					{
						list.Add((act, num2));
					}
				}
			}
			double num3 = list.Sum<(ActModel, double)>(((ActModel Act, double W) t) => t.W);
			if (num3 <= 0.0 || list.Count == 0)
			{
				return;
			}
			double num4 = ctx.Rng.NextDouble() * num3;
			foreach (var item3 in list)
			{
				ActModel item = item3.Item1;
				double item2 = item3.Item2;
				num4 -= item2;
				if (num4 <= 0.0)
				{
					ReplaceActAtSlot(runManager, runState, slotIndex, item);
					return;
				}
			}
			ReplaceActAtSlot(runManager, runState, slotIndex, list[list.Count - 1].Item1);
		}

