		public void RegisterCardLibraryCompendiumSharedPoolFilter(string stableId, string iconTexturePath, Type cardPoolType, IReadOnlyList<CardLibraryCompendiumPlacementRule>? placementRules)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(stableId, "stableId");
			ArgumentException.ThrowIfNullOrWhiteSpace(iconTexturePath, "iconTexturePath");
			ArgumentNullException.ThrowIfNull(cardPoolType, "cardPoolType");
			ThrowIfInvalidCompendiumSharedPoolFilterStableId(stableId);
			EnsureModelType(cardPoolType, typeof(CardPoolModel), "cardPoolType");
			CardLibraryCompendiumPlacementRule.ThrowIfInvalidRules(placementRules);
			using (SyncRoot.EnterScope())
			{
				EnsureMutable("register card library compendium shared pool filter");
				if (!CardLibraryCompendiumSharedPoolFilterStableIds.Add(stableId))
				{
					throw new InvalidOperationException("Duplicate card library compendium shared pool filter stable id: '" + stableId + "'.");
				}
				CardLibraryCompendiumSharedPoolFilters.Add(new CardLibraryCompendiumSharedPoolFilterRegistration
				{
					OwningModId = ModId,
					StableId = stableId,
					IconTexturePath = iconTexturePath,
					CardPoolType = cardPoolType,
					PlacementRules = ((placementRules != null && placementRules.Count > 0) ? placementRules : null)
				});
			}
			_logger.Info("[Content] Registered card library compendium shared pool filter '" + stableId + "' -> " + cardPoolType.Name, 1);
		}

