		private static void ThrowIfInvalidCompendiumSharedPoolFilterStableId(string stableId)
		{
			if (stableId.Any((char c) => !char.IsAsciiLetter(c) && !char.IsAsciiDigit(c) && c != '_'))
			{
				throw new ArgumentException("Stable id must contain only ASCII letters, digits, or underscores (safe for Godot node names).", "stableId");
			}
		}

