		{
			ArgumentException.ThrowIfNullOrWhiteSpace(cardPoolEntry, "cardPoolEntry");
			string key = NormalizeOwnedModelIdEntry(cardPoolEntry);
			using (SyncRoot.EnterScope())
			{
				if (RegisteredCardPoolAssetReplacementsByEntry.TryGetValue(key, out Dictionary<string, CardPoolAssetReplacementLayer> value) && value.Count != 0)
				{
					return TryMergeCardPoolAssetReplacementLayers(value.Values, out assetProfile);
				}
				assetProfile = CardPoolAssetProfile.Empty;
				return false;
			}
		}

		private static bool TryMergeCardPoolAssetReplacementLayers(IEnumerable<CardPoolAssetReplacementLayer> layers, out CardPoolAssetProfile mergedProfile)
		{
			List<CardPoolAssetReplacementLayer> list = layers.ToList();
			if (list.Count == 0)
			{
				mergedProfile = CardPoolAssetProfile.Empty;
				return false;
			}
			list.Sort((CardPoolAssetReplacementLayer x, CardPoolAssetReplacementLayer y) => x.WriteOrder.CompareTo(y.WriteOrder));
			CardPoolAssetProfile cardPoolAssetProfile = list[0].Profile;
			for (int num = 1; num < list.Count; num++)
			{
				cardPoolAssetProfile = CardPoolAssetProfiles.Merge(cardPoolAssetProfile, list[num].Profile);
			}
			mergedProfile = cardPoolAssetProfile;
			return true;
		}

		private static long NextCardPoolAssetReplacementWriteOrder()
		{
			_cardPoolAssetReplacementWriteOrder++;
			return _cardPoolAssetReplacementWriteOrder;
		}

