		/// <summary>
		///     <para xml:lang="en">
		///         Tries to get the effective global and character-specific registry replacements without
		///         programmatic owned-visual replacements.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试获取全局与角色专用注册表替换的最终结果，不包含编程式所属视觉替换。
		///     </para>
		/// </summary>
		internal static bool TryGetRegistryOnlyEffectiveCharacterAssetReplacement(string characterEntry, out CharacterAssetProfile assetProfile)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(characterEntry, "characterEntry");
			bool flag = TryGetGlobalCharacterAssetReplacement(out CharacterAssetProfile assetProfile2);
			bool flag2 = TryGetRegisteredCharacterAssetReplacement(characterEntry, out CharacterAssetProfile assetProfile3);
			if (!flag && !flag2)
			{
				assetProfile = CharacterAssetProfile.Empty;
				return false;
			}
			assetProfile = ((flag & flag2) ? CharacterAssetProfiles.Merge(assetProfile2, assetProfile3) : (flag2 ? assetProfile3 : assetProfile2));
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Tries to get effective registry and programmatic owned-visual replacements for a character.
		///         Registry replacements take precedence on conflicts.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         尝试获取角色的最终注册表与编程式所属视觉替换。发生冲突时注册表替换优先。
		///     </para>
		/// </summary>
		internal static bool TryGetEffectiveCharacterAssetReplacement(string characterEntry, out CharacterAssetProfile assetProfile)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(characterEntry, "characterEntry");
			bool flag = TryGetRegistryOnlyEffectiveCharacterAssetReplacement(characterEntry, out CharacterAssetProfile assetProfile2);
			bool flag2 = TryBuildProgrammaticCharacterOwnedVisualProfile(characterEntry, out CharacterAssetProfile assetProfile3);
			if (!flag && !flag2)
			{
				assetProfile = CharacterAssetProfile.Empty;
				return false;
			}
			assetProfile = ((flag & flag2) ? CharacterAssetProfiles.Merge(assetProfile3, assetProfile2) : (flag ? assetProfile2 : assetProfile3));
			return true;
		}

		internal static IReadOnlyList<CharacterAssetReplacementLayerSnapshot> GetCharacterAssetReplacementLayerSnapshots()
		{
			using (SyncRoot.EnterScope())
			{
				List<CharacterAssetReplacementLayerSnapshot> list = new List<CharacterAssetReplacementLayerSnapshot>();
				string key;
				CharacterAssetReplacementLayer value;
				foreach (KeyValuePair<string, CharacterAssetReplacementLayer> item in RegisteredGlobalCharacterAssetReplacementsByMod)
				{
					item.Deconstruct(out key, out value);
					string modId = key;
					CharacterAssetReplacementLayer characterAssetReplacementLayer = value;
					list.Add(new CharacterAssetReplacementLayerSnapshot("global", "*", modId, characterAssetReplacementLayer.WriteOrder, characterAssetReplacementLayer.Profile));
				}
				foreach (KeyValuePair<string, Dictionary<string, CharacterAssetReplacementLayer>> item2 in RegisteredCharacterAssetReplacementsByEntry)
				{
					item2.Deconstruct(out key, out var value2);
					string characterEntry = key;
					foreach (KeyValuePair<string, CharacterAssetReplacementLayer> item3 in value2)
					{
						item3.Deconstruct(out key, out value);
						string modId2 = key;
						CharacterAssetReplacementLayer characterAssetReplacementLayer2 = value;
						list.Add(new CharacterAssetReplacementLayerSnapshot("character", characterEntry, modId2, characterAssetReplacementLayer2.WriteOrder, characterAssetReplacementLayer2.Profile));
					}
				}
				list.Sort((CharacterAssetReplacementLayerSnapshot x, CharacterAssetReplacementLayerSnapshot y) => x.WriteOrder.CompareTo(y.WriteOrder));
				return list;
			}
		}

		internal static IReadOnlyList<CharacterAssetReplacementResolvedPropertySnapshot> GetCharacterAssetReplacementResolvedPropertySnapshots()
		{
			using (SyncRoot.EnterScope())
			{
				List<CharacterAssetReplacementResolvedPropertySnapshot> list = new List<CharacterAssetReplacementResolvedPropertySnapshot>();
				string[] array = RegisteredCharacterAssetReplacementsByEntry.Keys.OrderBy<string, string>((string x) => x, StringComparer.OrdinalIgnoreCase).ToArray();
				foreach (string characterEntry in array)
				{
					list.AddRange(GetResolvedPropertiesForEntry(characterEntry));
				}
				return list;
			}
		}

		private static long NextCharacterAssetReplacementWriteOrder()
		{
			_characterAssetReplacementWriteOrder++;
			return _characterAssetReplacementWriteOrder;
		}

		private bool TryRemoveCharacterAssetReplacementForKey(string dictionaryKey)
		{
			if (!RegisteredCharacterAssetReplacementsByEntry.TryGetValue(dictionaryKey, out Dictionary<string, CharacterAssetReplacementLayer> value))
			{
				return false;
			}
			bool result = value.Remove(ModId);
			if (value.Count == 0)
			{
				RegisteredCharacterAssetReplacementsByEntry.Remove(dictionaryKey);
			}
			return result;
		}

		private static bool TryMergeCharacterAssetReplacementLayers(IEnumerable<CharacterAssetReplacementLayer> layers, out CharacterAssetProfile mergedProfile)
		{
			List<CharacterAssetReplacementLayer> list = layers.ToList();
			if (list.Count == 0)
			{
				mergedProfile = CharacterAssetProfile.Empty;
				return false;
			}
			list.Sort((CharacterAssetReplacementLayer x, CharacterAssetReplacementLayer y) => x.WriteOrder.CompareTo(y.WriteOrder));
			CharacterAssetProfile characterAssetProfile = list[0].Profile;
			for (int num = 1; num < list.Count; num++)
			{
				characterAssetProfile = CharacterAssetProfiles.Merge(characterAssetProfile, list[num].Profile);
			}
			mergedProfile = characterAssetProfile;
			return true;
		}

		private static List<CharacterAssetReplacementResolvedPropertySnapshot> GetResolvedPropertiesForEntry(string characterEntry)
		{
			List<CharacterAssetReplacementResolvedPropertySnapshot> list = new List<CharacterAssetReplacementResolvedPropertySnapshot>();
			RegisteredCharacterAssetReplacementsByEntry.TryGetValue(characterEntry, out Dictionary<string, CharacterAssetReplacementLayer> value);
			(string, CharacterAssetReplacementLayer)[] orderedLayers = (from kv in RegisteredGlobalCharacterAssetReplacementsByMod
				select (ModId: kv.Key, Layer: kv.Value) into x
				orderby x.Layer.WriteOrder
				select x).ToArray();
			(string, CharacterAssetReplacementLayer)[] orderedLayers2 = ((value == null) ? Array.Empty<(string, CharacterAssetReplacementLayer)>() : (from kv in value
				select (ModId: kv.Key, Layer: kv.Value) into x
				orderby x.Layer.WriteOrder
				select x).ToArray());
			CharacterAssetPathField[] characterAssetPathFields = CharacterAssetPathFields;
			foreach (CharacterAssetPathField field in characterAssetPathFields)
			{
				CharacterAssetReplacementResolvedPropertySnapshot resolved2;
				if (TryResolveFieldSource(characterEntry, field, orderedLayers2, "character", out var resolved))
				{
					list.Add(resolved);
				}
				else if (TryResolveFieldSource(characterEntry, field, orderedLayers, "global", out resolved2))
				{
					list.Add(resolved2);
				}
			}
			return list;
		}

		private static bool TryResolveFieldSource(string characterEntry, CharacterAssetPathField field, IEnumerable<(string ModId, CharacterAssetReplacementLayer Layer)> orderedLayers, string scope, out CharacterAssetReplacementResolvedPropertySnapshot resolved)
		{
			foreach (var item in orderedLayers.Reverse())
			{
				string value = field.Selector(item.Layer.Profile);
				if (!string.IsNullOrWhiteSpace(value))
				{
					resolved = new CharacterAssetReplacementResolvedPropertySnapshot(characterEntry, field.Name, value, scope, item.ModId, item.Layer.WriteOrder);
					return true;
				}
			}
			resolved = default(CharacterAssetReplacementResolvedPropertySnapshot);
			return false;
		}

