		private static ContentCatalogEntry GlobalEntry<TModel>(ContentCatalogId id, Func<IEnumerable<Type>> globalTypes, ContentMergeMode mergeMode = ContentMergeMode.AppendDistinctById) where TModel : AbstractModel
		{
			return GlobalCatalog(id, globalTypes, (IEnumerable<Type> types) => ResolvedModelCache.ResolveUncached<TModel>(types), mergeMode);
		}

		private static ContentCatalogEntry ScopedEntry<TModel>(ContentCatalogId id, Func<Dictionary<Type, HashSet<Type>>> scopedRegistry) where TModel : AbstractModel
		{
			return ScopedCatalog(id, scopedRegistry, (Dictionary<Type, HashSet<Type>> registry) => ResolvedModelCache.ResolveScopedUncached<TModel>(registry));
		}

		private static ContentCatalogEntry GlobalCatalog(ContentCatalogId id, Func<IEnumerable<Type>> globalTypes, Func<IEnumerable<Type>, object> warmGlobal, ContentMergeMode mergeMode = ContentMergeMode.AppendDistinctById)
		{
			return new ContentCatalogEntry
			{
				Id = id,
				GlobalTypes = globalTypes,
				WarmGlobal = warmGlobal,
				MergeMode = mergeMode
			};
		}

		private static ContentCatalogEntry ScopedCatalog(ContentCatalogId id, Func<Dictionary<Type, HashSet<Type>>> scopedRegistry, Func<Dictionary<Type, HashSet<Type>>, Dictionary<Type, object>> warmScoped)
		{
			return new ContentCatalogEntry
			{
				Id = id,
				ScopedRegistry = scopedRegistry,
				WarmScoped = warmScoped
			};
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Merges a source sequence with the resolved models in a global catalog.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将来源序列与全局目录中已解析的模型合并。
		///     </para>
		/// </summary>
		internal static IEnumerable<TModel> MergeGlobalCatalog<TModel>(ContentCatalogId catalogId, IEnumerable<TModel> source) where TModel : AbstractModel
		{
			ContentCatalogEntry catalog = GetCatalog(catalogId);
			TModel[] global = ResolvedModelCache.GetGlobal<TModel>(catalogId);
			return ContentMergeStrategies.GetEnumerable<TModel>(catalog.MergeMode).Merge(source, global);
		}

		/// <summary>
		///     <para xml:lang="en">Merges a source sequence with the resolved models in an act-scoped catalog.</para>
		///     <para xml:lang="zh-CN">将来源序列与章节作用域目录中已解析的模型合并。</para>
		/// </summary>
		internal static IEnumerable<TModel> MergeScopedCatalog<TModel>(ContentCatalogId catalogId, Type scopeType, IEnumerable<TModel> source) where TModel : AbstractModel
		{
			ContentCatalogEntry catalog = GetCatalog(catalogId);
			TModel[] scoped = ResolvedModelCache.GetScoped<TModel>(catalogId, scopeType);
			return ContentMergeStrategies.GetEnumerable<TModel>(catalog.MergeMode).Merge(source, scoped);
		}

		/// <summary>
		///     <para xml:lang="en">Merges a source list with the resolved models in a global catalog.</para>
		///     <para xml:lang="zh-CN">将来源列表与全局目录中已解析的模型合并。</para>
		/// </summary>
		internal static IReadOnlyList<TModel> MergeGlobalCatalogList<TModel>(ContentCatalogId catalogId, IReadOnlyList<TModel> source) where TModel : AbstractModel
		{
			TModel[] global = ResolvedModelCache.GetGlobal<TModel>(catalogId);
			return ContentMergeStrategies.GetList<TModel>().Merge(source, global);
		}

