		private static TModel[] ResolveExistingModels<TModel>(IEnumerable<Type> modelTypes) where TModel : AbstractModel
		{
			return (from type in modelTypes.OrderBy<Type, string>((Type type) => type.FullName ?? type.Name, StringComparer.Ordinal)
				select ModelDb.GetByIdOrNull<TModel>(ModelDb.GetId(type))).OfType<TModel>().ToArray();
		}

