		}

		/// <summary>
		///     <para xml:lang="en">
		///         Injects RitsuLib-registered types from <see cref="P:System.Reflection.Assembly.IsDynamic" /> assemblies into
		///         <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" /> before <c>Init</c> finishes populating <c>_contentById</c>. The game's subtype
		///         scan discovers static mod DLL types, but not Reflection.Emit placeholder types.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         在 <c>Init</c> 完成填充 <c>_contentById</c> 前，将位于 <see cref="P:System.Reflection.Assembly.IsDynamic" />
		///         程序集中的 RitsuLib 注册类型注入 <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" />。游戏的子类型扫描能够发现静态模组
		///         DLL 中的类型，但无法发现通过 Reflection.Emit 生成的占位类型。
		///     </para>
		/// </summary>
		internal static void InjectDynamicRegisteredModels()
		{
			Type[] array;
			using (SyncRoot.EnterScope())
			{
				array = (from t in RegisteredPoolContent.SelectMany<(Type, Type), Type>(((Type PoolType, Type ModelType) entry) => new Type[2] { entry.PoolType, entry.ModelType }).Concat(RegisteredCharacters).Concat(RegisteredActs)
						.Concat(RegisteredMonsters)
						.Concat(RegisteredPowers)
						.Concat(RegisteredOrbs)
						.Concat(RegisteredModelCapabilities)
						.Concat(RegisteredEnchantments)
						.Concat(RegisteredAfflictions)
						.Concat(RegisteredAchievements)
						.Concat(RegisteredSingletons)
						.Concat(RegisteredSharedCardPools)
						.Concat(RegisteredSharedRelicPools)
						.Concat(RegisteredSharedPotionPools)
						.Concat(RegisteredGoodModifiers.Select((ModifierRegistration registration) => registration.ModifierType))
						.Concat(RegisteredBadModifiers.Select((ModifierRegistration registration) => registration.ModifierType))
						.Concat(RegisteredMutuallyExclusiveModifierGroups.SelectMany((HashSet<Type> @group) => @group))
						.Concat(RegisteredSharedEvents)
						.Concat(RegisteredSharedAncients)
						.Concat(RegisteredActEncounters.Values.SelectMany((HashSet<Type> set) => set))
						.Concat(RegisteredGlobalEncounters)
						.Concat(RegisteredActEvents.Values.SelectMany((HashSet<Type> set) => set))
						.Concat(RegisteredActAncients.Values.SelectMany((HashSet<Type> set) => set))
						.Distinct()
					where t.Assembly.IsDynamic
					select t).OrderBy<Type, string>((Type t) => t.FullName ?? t.Name, StringComparer.Ordinal).ToArray();
			}
			Type[] array2 = array;
			for (int num = 0; num < array2.Length; num++)
			{
				ModelDb.Inject(array2[num]);
			}
		}

		private void RegisterPoolModel(Type poolType, Type modelType, Type expectedPoolBaseType, Type expectedModelBaseType, string contentKind, ModelPublicEntryOptions publicEntry = default(ModelPublicEntryOptions))
		{
			EnsureModelType(poolType, expectedPoolBaseType, "poolType");
			EnsureModelType(modelType, expectedModelBaseType, "modelType");
			EnsureMutable($"register {contentKind} '{modelType.Name}' into pool '{poolType.Name}'");
			PrimeOwnedType(modelType);
			ApplyFixedPublicEntryForModel(modelType, publicEntry);
			RegistrationConflictDetector.ThrowIfModelIdConflicts(poolType);
			RegistrationConflictDetector.ThrowIfModelIdConflicts(modelType);
			string value = FormatModelForLog(modelType);
			using (SyncRoot.EnterScope())
			{
				if (!RegisteredPoolContent.Add((poolType, modelType)))
				{
					_logger.Debug($"[Content] Skipping duplicate {contentKind} registration: {value} -> {poolType.Name}", 1);
					return;
				}
				RememberOwner(modelType);
			}
			ModHelper.AddModelToPool(poolType, modelType);
			_logger.Info($"[Content] Registered {contentKind}: {value} -> {poolType.Name}", 1);
		}

		private void RegisterCharacterStarterModel(Type characterType, Type modelType, Type expectedModelBaseType, CharacterStarterContentKind kind, int count, int order)
		{
			if (count <= 0)
			{
				throw new ArgumentOutOfRangeException("count", count, "Starter content count must be positive.");
			}
			EnsureModelType(characterType, typeof(CharacterModel), "characterType");
			EnsureModelType(modelType, expectedModelBaseType, "modelType");
			EnsureMutable($"register starter {kind.ToString().ToLowerInvariant()} '{modelType.Name}' for '{characterType.Name}'");
			RegistrationConflictDetector.ThrowIfModelIdConflicts(characterType);
			RegistrationConflictDetector.ThrowIfModelIdConflicts(modelType);
			string value = FormatModelForLog(modelType);
			using (SyncRoot.EnterScope())
			{
				RegisteredCharacterStarterContent.Add(new CharacterStarterRegistration(characterType, modelType, kind, count, order));
			}
			_logger.Info($"[Content] Registered starter {kind.ToString().ToLowerInvariant()}: {value} x{count} -> {characterType.Name}", 1);
		}

		private void RegisterStandaloneModel(HashSet<Type> registry, Type modelType, Type expectedBaseType, string contentKind)
		{
			EnsureModelType(modelType, expectedBaseType, "modelType");
			EnsureMutable($"register {contentKind} '{modelType.Name}'");
			PrimeOwnedType(modelType);
			RegistrationConflictDetector.ThrowIfModelIdConflicts(modelType);
			string text = FormatModelForLog(modelType);
			using (SyncRoot.EnterScope())
			{
				if (!registry.Add(modelType))
				{
					_logger.Debug("[Content] Skipping duplicate " + contentKind + " registration: " + text, 1);
					return;
				}
				RememberOwner(modelType);
			}
			_logger.Info("[Content] Registered " + contentKind + ": " + text, 1);
		}

		private void RegisterModifier(List<ModifierRegistration> registry, Type modifierType, int modifierListSortOrder, string contentKind)
		{
			EnsureModelType(modifierType, typeof(ModifierModel), "modifierType");
			EnsureMutable($"register {contentKind} '{modifierType.Name}'");
			PrimeOwnedType(modifierType);
			RegistrationConflictDetector.ThrowIfModelIdConflicts(modifierType);
			string text = FormatModelForLog(modifierType);
			using (SyncRoot.EnterScope())
			{
				if (registry.Any((ModifierRegistration entry) => entry.ModifierType == modifierType))
				{
					_logger.Debug("[Content] Skipping duplicate " + contentKind + " registration: " + text, 1);
					return;
				}
				registry.Add(new ModifierRegistration(modifierType, modifierListSortOrder));
				RememberOwner(modifierType);
			}
			_logger.Info("[Content] Registered " + contentKind + ": " + text, 1);
		}

		private void RegisterScopedModel(Dictionary<Type, HashSet<Type>> registry, Type scopeType, Type modelType, Type expectedScopeType, Type expectedModelBaseType, string contentKind)
		{
			EnsureModelType(scopeType, expectedScopeType, "scopeType");
			EnsureModelType(modelType, expectedModelBaseType, "modelType");
			EnsureMutable($"register {contentKind} '{modelType.Name}' for '{scopeType.Name}'");
			PrimeOwnedType(modelType);
			RegistrationConflictDetector.ThrowIfModelIdConflicts(scopeType);
			RegistrationConflictDetector.ThrowIfModelIdConflicts(modelType);
			string value = FormatModelForLog(modelType);
			using (SyncRoot.EnterScope())
			{
				if (!registry.TryGetValue(scopeType, out HashSet<Type> value2))
				{
					value2 = (registry[scopeType] = new HashSet<Type>());
				}
				if (!value2.Add(modelType))
				{
					_logger.Debug($"[Content] Skipping duplicate {contentKind} registration: {value} -> {scopeType.Name}", 1);
					return;
				}
				RememberOwner(modelType);
			}
			_logger.Info($"[Content] Registered {contentKind}: {value} -> {scopeType.Name}", 1);
		}

		private void EnsureMutable(string operation)
		{
			if (!IsFrozen)
			{
				return;
			}
			throw new InvalidOperationException($"Cannot {operation} after content registration has been frozen ({_freezeReason ?? "unknown"}). " + "Register content from your mod initializer before the game initializes ModelDb.");
		}

		private static void EnsureModelType(Type type, Type expectedBaseType, string paramName)
		{
			ArgumentNullException.ThrowIfNull(type, paramName);
			ArgumentNullException.ThrowIfNull(expectedBaseType, "expectedBaseType");
			if (type.IsAbstract || type.IsInterface || type.ContainsGenericParameters || !expectedBaseType.IsAssignableFrom(type))
			{
				throw new ArgumentException($"Type '{type.FullName}' must be a closed concrete subtype of '{expectedBaseType.FullName}'.", paramName);
			}
		}

		private static void EnsureModelFamilyType(Type type, string paramName)
		{
			ArgumentNullException.ThrowIfNull(type, paramName);
			if (type.IsInterface || type.ContainsGenericParameters || !typeof(AbstractModel).IsAssignableFrom(type))
			{
				throw new ArgumentException("Type '" + type.FullName + "' must be a closed abstract or concrete model type.", paramName);
			}
		}

		private static void EnsureBadgeType(Type type, string paramName)
		{
			ArgumentNullException.ThrowIfNull(type, paramName);
			if (type.IsAbstract || type.IsInterface || type.ContainsGenericParameters || !typeof(ModBadgeTemplate).IsAssignableFrom(type))
			{
				throw new ArgumentException($"Type '{type.FullName}' must be a closed concrete subtype of '{typeof(ModBadgeTemplate).FullName}'.", paramName);
			}
		}

		private static bool MatchesRegisteredStarterCharacter(Type registeredCharacterType, Type runtimeCharacterType)
		{
			if (registeredCharacterType == runtimeCharacterType)
			{
				return true;
			}
			if (!registeredCharacterType.IsAssignableFrom(runtimeCharacterType))
			{
				return false;
			}
			return registeredCharacterType != typeof(CharacterModel);
		}

		private static string FormatModelForLog(Type modelType)
		{
			if (!TryGetFixedPublicEntry(modelType, out string entry))
			{
				return modelType.Name;
			}
			return modelType.Name + " (id=" + entry + ")";
		}

		private static Type[] GetRegisteredCharacterStarterTypes(Type characterType, CharacterStarterContentKind kind)
		{
			ArgumentNullException.ThrowIfNull(characterType, "characterType");
			using (SyncRoot.EnterScope())
			{
				return (from x in RegisteredCharacterStarterContent.Select((CharacterStarterRegistration entry, int index) => new { entry, index })
					orderby x.entry.Order, x.index
					where x.entry.Kind == kind && MatchesRegisteredStarterCharacter(x.entry.CharacterType, characterType)
					select x).SelectMany(x => Enumerable.Repeat(x.entry.ModelType, x.entry.Count)).ToArray();
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Normalizes a public ID segment by replacing non-alphanumeric runs with underscores, separating acronym
		///         and camel-case boundaries, merging repeated underscores, and converting the result to uppercase.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         规范化公共 ID 段：将连续的非字母数字字符替换为下划线，拆分缩写词与驼峰命名边界，
		///         合并连续下划线，并将结果转换为大写。
		///     </para>
		/// </summary>
		public static string NormalizePublicStem(string value)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(value, "value");
			string input = NonAlphaNumericRegex().Replace(value.Trim(), "_");
			input = AcronymBoundaryRegex().Replace(input, "$1_$2");
			input = CamelBoundaryRegex().Replace(input, "$1_$2");
			input = RepeatedUnderscoreRegex().Replace(input, "_");
			return input.Trim('_').ToUpperInvariant();
		}

		private static string NormalizeFullPublicEntry(string value)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(value, "value");
			string input = NonAlphaNumericRegex().Replace(value.Trim(), "_");
			input = AcronymBoundaryRegex().Replace(input, "$1_$2");
			input = CamelBoundaryRegex().Replace(input, "$1_$2");
			input = RepeatedUnderscoreRegex().Replace(input, "_");
			return input.Trim('_').ToUpperInvariant();
		}

		private void ApplyFixedPublicEntryForModel(Type modelType, ModelPublicEntryOptions options)
		{
			if (options.Kind == ModelPublicEntryKind.FromTypeName)
			{
				return;
			}
			ModelId id = ModelDb.GetId(modelType);
			string text = options.Kind switch
			{
				ModelPublicEntryKind.Stem => $"{NormalizePublicStem(ModId)}_{NormalizePublicStem(ModelDb.GetCategory(modelType))}_{NormalizePublicStem(options.Value)}", 
				ModelPublicEntryKind.FullEntry => NormalizeFullPublicEntry(options.Value), 
				_ => throw new ArgumentOutOfRangeException("options", options.Kind, null), 
			};
			using (SyncRoot.EnterScope())
			{
				if (FixedPublicEntryOverrides.TryGetValue(modelType, out string value))
				{
					if (!string.Equals(value, text, StringComparison.Ordinal))
					{
						throw new InvalidOperationException($"Cannot change fixed public entry for '{modelType.FullName}' from '{value}' to '{text}'.");
					}
					return;
				}
				FixedPublicEntryOverrides[modelType] = text;
			}
			RegistrationConflictDetector.UpdateModelIdIndex(modelType, id, ModelDb.GetId(modelType));
		}

		private string ResolveModelCapabilityId(Type capabilityType, ModelPublicEntryOptions options)
		{
			return options.Kind switch
			{
				ModelPublicEntryKind.FromTypeName => GetQualifiedModelCapabilityId(ModId, capabilityType.Name), 
				ModelPublicEntryKind.Stem => GetQualifiedModelCapabilityId(ModId, options.Value), 
				ModelPublicEntryKind.FullEntry => NormalizeFullPublicEntry(options.Value), 
				_ => throw new ArgumentOutOfRangeException("options", options.Kind, null), 
			};
		}

