		///     <para xml:lang="zh-CN">
		///         返回由 <paramref name="modId" /> 拥有且已注册到 <paramref name="poolType" /> 的模型类型。
		///     </para>
		/// </summary>
		public static IReadOnlyList<Type> GetRegisteredModelsInPool(string modId, Type poolType)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentNullException.ThrowIfNull(poolType, "poolType");
			using (SyncRoot.EnterScope())
			{
				List<Type> list = new List<Type>();
				list.AddRange((from e in RegisteredPoolContent
					where e.PoolType == poolType && TryGetOwnerModId(e.ModelType, out string modId2) && string.Equals(modId2, modId, StringComparison.OrdinalIgnoreCase)
					select e.ModelType).Distinct());
				return new <>z__ReadOnlyList<Type>(list);
			}
		}

