	/// <summary>
	///     <para xml:lang="en">
	///         Merges RitsuLib-registered run modifiers and exclusivity groups into <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" />
	///         lists.
	///     </para>
	///     <para xml:lang="zh-CN">将 RitsuLib 注册的一局游戏修饰符与互斥组合并到 <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" /> 列表中。</para>
	/// </summary>
	internal static class ModifierContentMerge
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Inserts registered modifiers before or after <paramref name="source" /> using
		///         <see cref="P:STS2RitsuLib.Content.ModifierRegistration.ModifierListSortOrder" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         按 <see cref="P:STS2RitsuLib.Content.ModifierRegistration.ModifierListSortOrder" /> 在 <paramref name="source" />
		///         前后插入已注册修饰符。
		///     </para>
		/// </summary>
		public static IReadOnlyList<ModifierModel> InsertModifiers(IReadOnlyList<ModifierModel> source, IReadOnlyList<ModifierRegistration> registrations)
		{
			if (registrations.Count == 0)
			{
				return source;
			}
			ModifierModel[] array = ResolveSlice(registrations, negativeSortOrder: true);
			ModifierModel[] array2 = ResolveSlice(registrations, negativeSortOrder: false);
			if (array.Length == 0 && array2.Length == 0)
			{
				return source;
			}
			return ConcatDistinctByModelId(array, source, array2);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Merges registered exclusivity groups into <paramref name="source" />, combining overlapping
		///         sets.
		///     </para>
		///     <para xml:lang="zh-CN">将已注册互斥组合并到 <paramref name="source" />，并合并存在交集的集合。</para>
		/// </summary>
		public static IReadOnlyList<IReadOnlySet<ModifierModel>> MergeMutuallyExclusiveModifiers(IReadOnlyList<IReadOnlySet<ModifierModel>> source, IReadOnlyList<HashSet<Type>> registeredGroups)
		{
			List<HashSet<ModifierModel>> list = BuildExclusiveGroups(registeredGroups);
			if (list.Count == 0)
			{
				return source;
			}
			List<IReadOnlySet<ModifierModel>> list2 = new List<IReadOnlySet<ModifierModel>>();
			list2.AddRange(((IEnumerable<HashSet<ModifierModel>>)list.Aggregate(source.Select((IReadOnlySet<ModifierModel> set) => set.ToHashSet()).ToList(), delegate(List<HashSet<ModifierModel>> groups, HashSet<ModifierModel> customGroup)
			{
				List<HashSet<ModifierModel>> list3 = groups.Where((HashSet<ModifierModel> g) => g.Overlaps(customGroup)).ToList();
				HashSet<ModifierModel> hashSet = customGroup.ToHashSet();
				foreach (HashSet<ModifierModel> item in list3)
				{
					groups.Remove(item);
					hashSet.UnionWith(item);
				}
				groups.Add(hashSet);
				return groups;
			})).Select((Func<HashSet<ModifierModel>, IReadOnlySet<ModifierModel>>)((HashSet<ModifierModel> set) => set)));
			return new <>z__ReadOnlyList<IReadOnlySet<ModifierModel>>(list2);
		}

		private static ModifierModel[] ResolveSlice(IReadOnlyList<ModifierRegistration> registrations, bool negativeSortOrder)
		{
			return (from r in (from r in registrations
					where (!negativeSortOrder) ? (r.ModifierListSortOrder >= 0) : (r.ModifierListSortOrder < 0)
					orderby r.ModifierListSortOrder
					select r).ThenBy<ModifierRegistration, string>((ModifierRegistration r) => r.ModifierType.FullName ?? r.ModifierType.Name, StringComparer.Ordinal)
				select ModelDb.GetById<ModifierModel>(ModelDb.GetId(r.ModifierType))).DistinctBy((ModifierModel model) => ((AbstractModel)model).Id).ToArray();
		}

		private static List<HashSet<ModifierModel>> BuildExclusiveGroups(IReadOnlyList<HashSet<Type>> registeredGroups)
		{
			List<HashSet<ModifierModel>> list = new List<HashSet<ModifierModel>>();
			foreach (HashSet<Type> registeredGroup in registeredGroups)
			{
				HashSet<ModifierModel> members = (from t in registeredGroup.OrderBy<Type, string>((Type t) => t.FullName ?? t.Name, StringComparer.Ordinal)
					select ModelDb.GetById<ModifierModel>(ModelDb.GetId(t))).ToHashSet();
				if (members.Count < 2)
				{
					continue;
				}
				foreach (HashSet<ModifierModel> item in list.Where((HashSet<ModifierModel> g) => g.Overlaps(members)).ToList())
				{
					list.Remove(item);
					members.UnionWith(item);
				}
				list.Add(members);
			}
			return list;
		}

		private static List<ModifierModel> ConcatDistinctByModelId(ModifierModel[] before, IReadOnlyList<ModifierModel> source, ModifierModel[] after)
		{
			List<ModifierModel> list = new List<ModifierModel>(before.Length + source.Count + after.Length);
			ContentMergeStrategies.AppendDistinctById<ModifierModel>(list, (IEnumerable<ModifierModel>)before);
			ContentMergeStrategies.AppendDistinctById<ModifierModel>(list, (IEnumerable<ModifierModel>)source);
			ContentMergeStrategies.AppendDistinctById<ModifierModel>(list, (IEnumerable<ModifierModel>)after);
			return list;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Describes a registered mod run modifier and its list position.</para>
	///     <para xml:lang="zh-CN">描述已注册的模组局内修饰符及其列表位置。</para>
