		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, ModuleBuilder> ModulesByModId = new Dictionary<string, ModuleBuilder>(StringComparer.OrdinalIgnoreCase);

		private static int _typeSerial;

		internal static Type EmitCardType(string modId, in PlaceholderCardDescriptor d)
		{
			//IL_00a2: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ac: Expected I4, but got Unknown
			//IL_00b3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00bd: Expected I4, but got Unknown
			//IL_00c4: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ce: Expected I4, but got Unknown
			TypeBuilder typeBuilder = DefineType(modId, "Card", typeof(ModPlaceholderCardTemplate));
			ConstructorInfo con = RequireCtor(typeof(ModPlaceholderCardTemplate), typeof(int), typeof(CardType), typeof(CardRarity), typeof(TargetType), typeof(bool));
			ILGenerator iLGenerator = typeBuilder.DefineConstructor(MethodAttributes.Public, CallingConventions.Standard, Type.EmptyTypes).GetILGenerator();
			iLGenerator.Emit(OpCodes.Ldarg_0);
			iLGenerator.Emit(OpCodes.Ldc_I4, d.BaseCost);
			iLGenerator.Emit(OpCodes.Ldc_I4, (int)d.Type);
			iLGenerator.Emit(OpCodes.Ldc_I4, (int)d.Rarity);
			iLGenerator.Emit(OpCodes.Ldc_I4, (int)d.Target);
			iLGenerator.Emit(d.ShowInCardLibrary ? OpCodes.Ldc_I4_1 : OpCodes.Ldc_I4_0);
			iLGenerator.Emit(OpCodes.Call, con);
			iLGenerator.Emit(OpCodes.Ret);
			return typeBuilder.CreateType();
		}

		internal static Type EmitRelicType(string modId, in PlaceholderRelicDescriptor d)
		{
			//IL_00fe: Unknown result type (might be due to invalid IL or missing references)
			//IL_0108: Expected I4, but got Unknown
			TypeBuilder typeBuilder = DefineType(modId, "Relic", typeof(ModPlaceholderRelicTemplate));
			ConstructorInfo con = RequireCtor(typeof(ModPlaceholderRelicTemplate), typeof(RelicRarity), typeof(bool), typeof(bool), typeof(bool), typeof(bool), typeof(bool), typeof(bool), typeof(int), typeof(bool), typeof(int), typeof(bool), typeof(string), typeof(bool));
			ILGenerator iLGenerator = typeBuilder.DefineConstructor(MethodAttributes.Public, CallingConventions.Standard, Type.EmptyTypes).GetILGenerator();
			iLGenerator.Emit(OpCodes.Ldarg_0);
			iLGenerator.Emit(OpCodes.Ldc_I4, (int)d.Rarity);
			EmitBool(iLGenerator, d.IsUsedUp);
			EmitBool(iLGenerator, d.HasUponPickupEffect);
			EmitBool(iLGenerator, d.SpawnsPets);
			EmitBool(iLGenerator, d.IsStackable);
			EmitBool(iLGenerator, d.AddsPet);
			EmitBool(iLGenerator, d.ShowCounter);
			iLGenerator.Emit(OpCodes.Ldc_I4, d.DisplayAmount);
			EmitBool(iLGenerator, d.IncludeEnergyHoverTip);
			iLGenerator.Emit(OpCodes.Ldc_I4, d.MerchantCostOverride);
			EmitBool(iLGenerator, d.AlwaysAllowedInRun);
			iLGenerator.Emit(OpCodes.Ldstr, d.FlashSfx);
			EmitBool(iLGenerator, d.ShouldFlashOnPlayer);
			iLGenerator.Emit(OpCodes.Call, con);
			iLGenerator.Emit(OpCodes.Ret);
			return typeBuilder.CreateType();
		}

		internal static Type EmitPotionType(string modId, in PlaceholderPotionDescriptor d)
		{
			//IL_0091: Unknown result type (might be due to invalid IL or missing references)
			//IL_009b: Expected I4, but got Unknown
			//IL_00a2: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ac: Expected I4, but got Unknown
			//IL_00b3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00bd: Expected I4, but got Unknown
			TypeBuilder typeBuilder = DefineType(modId, "Potion", typeof(ModPlaceholderPotionTemplate));
			ConstructorInfo con = RequireCtor(typeof(ModPlaceholderPotionTemplate), typeof(PotionRarity), typeof(PotionUsage), typeof(TargetType), typeof(bool), typeof(bool));
			ILGenerator iLGenerator = typeBuilder.DefineConstructor(MethodAttributes.Public, CallingConventions.Standard, Type.EmptyTypes).GetILGenerator();
			iLGenerator.Emit(OpCodes.Ldarg_0);
			iLGenerator.Emit(OpCodes.Ldc_I4, (int)d.Rarity);
			iLGenerator.Emit(OpCodes.Ldc_I4, (int)d.Usage);
			iLGenerator.Emit(OpCodes.Ldc_I4, (int)d.Target);
			EmitBool(iLGenerator, d.CanBeGeneratedInCombat);
			EmitBool(iLGenerator, d.PassesCustomUsabilityCheck);
			iLGenerator.Emit(OpCodes.Call, con);
			iLGenerator.Emit(OpCodes.Ret);
			return typeBuilder.CreateType();
		}

		private static TypeBuilder DefineType(string modId, string kind, Type parent)
		{
			ModuleBuilder orCreateModule = GetOrCreateModule(modId);
			int value = Interlocked.Increment(ref _typeSerial);
			string value2 = SanitizeIdentifier(modId);
			return orCreateModule.DefineType($"STS2RitsuLib.Emit.{value2}.{kind}_{value}", TypeAttributes.Public | TypeAttributes.Sealed, parent);
		}

		private static ModuleBuilder GetOrCreateModule(string modId)
		{
			using (SyncRoot.EnterScope())
			{
				if (ModulesByModId.TryGetValue(modId, out ModuleBuilder value))
				{
					return value;
				}
				ModuleBuilder moduleBuilder = AssemblyBuilder.DefineDynamicAssembly(new AssemblyName($"STS2RitsuLib.Placeholders.{SanitizeIdentifier(modId)}_{Guid.NewGuid():N}"), AssemblyBuilderAccess.Run).DefineDynamicModule("MainModule");
				ModulesByModId[modId] = moduleBuilder;
				return moduleBuilder;
			}
		}

		private static string SanitizeIdentifier(string modId)
		{
			Span<char> span = stackalloc char[Math.Min(modId.Length, 48)];
			int num = 0;
			foreach (char c in modId)
			{
				if (num >= span.Length)
				{
					break;
				}
				span[num++] = (char.IsLetterOrDigit(c) ? c : '_');
			}
			if (num != 0)
			{
				return new string(span.Slice(0, num));
			}
			return "Mod";
		}

		private static ConstructorInfo RequireCtor(Type declaring, params Type[] signature)
		{
			return declaring.GetConstructor(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, signature, null) ?? throw new InvalidOperationException("Could not resolve constructor on '" + declaring.FullName + "' for emit signature.");
		}

		private static void EmitBool(ILGenerator il, bool value)
		{
			il.Emit(value ? OpCodes.Ldc_I4_1 : OpCodes.Ldc_I4_0);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Resolves registered model types after <see cref="M:MegaCrit.Sts2.Core.Models.ModelDb.Init(System.Type[])" /> and caches them by catalog.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在 <see cref="M:MegaCrit.Sts2.Core.Models.ModelDb.Init(System.Type[])" /> 后解析已注册模型类型，并按目录缓存。
	///     </para>
	/// </summary>
	internal static class ResolvedModelCache
	{
		private static readonly Lock Gate = new Lock();

		private static Dictionary<ContentCatalogId, ContentCatalogEntry> _catalogs = new Dictionary<ContentCatalogId, ContentCatalogEntry>();

		private static Dictionary<ContentCatalogId, object> _globalCache = new Dictionary<ContentCatalogId, object>();

		private static Dictionary<ContentCatalogId, Dictionary<Type, object>> _scopedCache = new Dictionary<ContentCatalogId, Dictionary<Type, object>>();

		private static ContentRegistryPhase _phase = ContentRegistryPhase.Open;

		internal static ContentRegistryPhase Phase
		{
			get
			{
				using (Gate.EnterScope())
				{
					return _phase;
				}
			}
		}

		internal static void Configure(IReadOnlyList<ContentCatalogEntry> catalogs)
		{
			using (Gate.EnterScope())
			{
				_catalogs = catalogs.ToDictionary((ContentCatalogEntry entry) => entry.Id);
			}
		}

		internal static void MarkFrozen()
		{
			using (Gate.EnterScope())
			{
				if (_phase == ContentRegistryPhase.Open)
				{
					_phase = ContentRegistryPhase.Frozen;
				}
			}
		}

		internal static void Warm()
		{
			ContentCatalogEntry[] array;
			using (Gate.EnterScope())
			{
				if (_phase >= ContentRegistryPhase.Resolved)
				{
					return;
				}
				array = _catalogs.Values.ToArray();
			}
			Dictionary<ContentCatalogId, object> dictionary = new Dictionary<ContentCatalogId, object>();
			Dictionary<ContentCatalogId, Dictionary<Type, object>> dictionary2 = new Dictionary<ContentCatalogId, Dictionary<Type, object>>();
			ContentCatalogEntry[] array2 = array;
			foreach (ContentCatalogEntry contentCatalogEntry in array2)
			{
				if (contentCatalogEntry.IsScoped)
				{
					dictionary2[contentCatalogEntry.Id] = contentCatalogEntry.WarmScoped(contentCatalogEntry.ScopedRegistry());
				}
				else
				{
					dictionary[contentCatalogEntry.Id] = contentCatalogEntry.WarmGlobal(contentCatalogEntry.GlobalTypes());
				}
			}
			using (Gate.EnterScope())
			{
				if (_phase < ContentRegistryPhase.Resolved)
				{
					_globalCache = dictionary;
					_scopedCache = dictionary2;
					_phase = ContentRegistryPhase.Resolved;
				}
			}
		}

		internal static TModel[] GetGlobal<TModel>(ContentCatalogId id) where TModel : AbstractModel
		{
			ContentCatalogEntry contentCatalogEntry;
			using (Gate.EnterScope())
			{
				if (_phase >= ContentRegistryPhase.Resolved && _globalCache.TryGetValue(id, out object value))
				{
					return (TModel[])value;
				}
				contentCatalogEntry = _catalogs[id];
			}
			return ResolveUncached<TModel>(contentCatalogEntry.GlobalTypes());
		}

		internal static TModel[] GetScoped<TModel>(ContentCatalogId id, Type scopeType) where TModel : AbstractModel
		{
			ArgumentNullException.ThrowIfNull(scopeType, "scopeType");
			ContentCatalogEntry contentCatalogEntry;
			using (Gate.EnterScope())
			{
				if (_phase >= ContentRegistryPhase.Resolved && _scopedCache.TryGetValue(id, out Dictionary<Type, object> value) && value.TryGetValue(scopeType, out var value2))
				{
					return (TModel[])value2;
				}
				contentCatalogEntry = _catalogs[id];
			}
			if (contentCatalogEntry.ScopedRegistry().TryGetValue(scopeType, out var value3))
			{
				return ResolveUncached<TModel>(value3);
			}
			return Array.Empty<TModel>();
		}

		internal static TModel[] ResolveUncached<TModel>(IEnumerable<Type> modelTypes) where TModel : AbstractModel
		{
			return ((IEnumerable<Type>)modelTypes.OrderBy<Type, string>((Type t) => t.FullName ?? t.Name, StringComparer.Ordinal)).Select((Func<Type, ModelId>)ModelDb.GetId).Select((Func<ModelId, TModel>)ModelDb.GetById<TModel>).ToArray();
		}

		internal static Dictionary<Type, object> ResolveScopedUncached<TModel>(Dictionary<Type, HashSet<Type>> registry) where TModel : AbstractModel
		{
			Dictionary<Type, object> dictionary = new Dictionary<Type, object>();
			foreach (var (key, modelTypes) in registry)
			{
				dictionary[key] = ResolveUncached<TModel>(modelTypes);
			}
			return dictionary;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Registration freeze and resolved-model cache lifecycle.</para>
	///     <para xml:lang="zh-CN">注册冻结与已解析模型缓存的生命周期阶段。</para>
	/// </summary>
	internal enum ContentRegistryPhase
	{
		/// <summary>
		///     <para xml:lang="en">Open for mod registration.</para>
		///     <para xml:lang="zh-CN">允许模组注册。</para>
		/// </summary>
		Open,
		/// <summary>
		///     <para xml:lang="en">Registrations are frozen before <see cref="M:MegaCrit.Sts2.Core.Models.ModelDb.Init(System.Type[])" /> runs.</para>
		///     <para xml:lang="zh-CN">在 <see cref="M:MegaCrit.Sts2.Core.Models.ModelDb.Init(System.Type[])" /> 运行前冻结注册。</para>
		/// </summary>
		Frozen,
		/// <summary>
		///     <para xml:lang="en">Resolved-model caches have been warmed.</para>
		///     <para xml:lang="zh-CN">已预热解析后的模型缓存。</para>
		/// </summary>
		Resolved
	}
	internal static class TrashHeapContentRegistry
	{
		private readonly record struct RegisteredModel(Type ModelType, string OwnerModId);

		private sealed class RegisteredModelComparer : IComparer<RegisteredModel>
		{
			internal static RegisteredModelComparer Instance { get; } = new RegisteredModelComparer();

			public int Compare(RegisteredModel x, RegisteredModel y)
			{
				int num = StringComparer.Ordinal.Compare(x.OwnerModId, y.OwnerModId);
				if (num != 0)
				{
					return num;
				}
				return StringComparer.Ordinal.Compare(x.ModelType.AssemblyQualifiedName ?? x.ModelType.FullName ?? x.ModelType.Name, y.ModelType.AssemblyQualifiedName ?? y.ModelType.FullName ?? y.ModelType.Name);
			}
		}

		private sealed class ModelComparer<TModel> : IComparer<TModel> where TModel : AbstractModel
		{
			internal static ModelComparer<TModel> Instance { get; } = new ModelComparer<TModel>();

			public int Compare(TModel? x, TModel? y)
			{
				if ((object)x == (object)y)
				{
					return 0;
				}
				if (x == null)
				{
					return -1;
				}
				if (y == null)
				{
					return 1;
				}
				int num = ((AbstractModel)x).Id.CompareTo(((AbstractModel)y).Id);
				if (num != 0)
				{
					return num;
				}
				return StringComparer.Ordinal.Compare(((object)x).GetType().AssemblyQualifiedName ?? ((object)x).GetType().FullName ?? ((object)x).GetType().Name, ((object)y).GetType().AssemblyQualifiedName ?? ((object)y).GetType().FullName ?? ((object)y).GetType().Name);
			}
		}

		private static readonly Lock SyncRoot = new Lock();

		private static readonly List<RegisteredModel> Cards = new List<RegisteredModel>();

		private static readonly List<RegisteredModel> Relics = new List<RegisteredModel>();

		internal static bool RegisterCard(Type cardType, string ownerModId)
		{
			return Register(Cards, cardType, ownerModId);
		}

		internal static bool RegisterRelic(Type relicType, string ownerModId)
		{
			return Register(Relics, relicType, ownerModId);
		}

		internal static CardModel[] AppendCards(CardModel[] vanillaCards)
		{
			ArgumentNullException.ThrowIfNull(vanillaCards, "vanillaCards");
			return AppendRegisteredModels<CardModel>(vanillaCards, (IReadOnlyList<RegisteredModel>)GetSnapshot(Cards), "card");
		}

		internal static RelicModel[] AppendRelics(RelicModel[] vanillaRelics)
		{
			ArgumentNullException.ThrowIfNull(vanillaRelics, "vanillaRelics");
			return AppendRegisteredModels<RelicModel>(vanillaRelics, (IReadOnlyList<RegisteredModel>)GetSnapshot(Relics), "relic");
		}

		internal static void ValidateFrozenRegistrations()
		{
			RegisteredModel[] snapshot = GetSnapshot(Cards);
			for (int i = 0; i < snapshot.Length; i++)
			{
				RegisteredModel registeredModel = snapshot[i];
				RegistrationFreezeDiagnostics.WarnMissingModelType("TrashHeap", registeredModel.OwnerModId, "Trash Heap card candidate", registeredModel.ModelType, typeof(CardModel));
			}
			snapshot = GetSnapshot(Relics);
			for (int i = 0; i < snapshot.Length; i++)
			{
				RegisteredModel registeredModel2 = snapshot[i];
				RegistrationFreezeDiagnostics.WarnMissingModelType("TrashHeap", registeredModel2.OwnerModId, "Trash Heap relic candidate", registeredModel2.ModelType, typeof(RelicModel));
			}
		}

		internal static void ClearForTests()
		{
			using (SyncRoot.EnterScope())
			{
				Cards.Clear();
				Relics.Clear();
			}
		}

		private static bool Register(List<RegisteredModel> registrations, Type modelType, string ownerModId)
		{
			ArgumentNullException.ThrowIfNull(modelType, "modelType");
			ArgumentException.ThrowIfNullOrWhiteSpace(ownerModId, "ownerModId");
			RegisteredModel registeredModel = new RegisteredModel(modelType, ownerModId.Trim());
			using (SyncRoot.EnterScope())
			{
				int num = registrations.FindIndex((RegisteredModel registration) => registration.ModelType == modelType);
				if (num >= 0)
				{
					RegisteredModel y = registrations[num];
					if (RegisteredModelComparer.Instance.Compare(registeredModel, y) >= 0)
					{
						return false;
					}
					registrations[num] = registeredModel;
					return true;
				}
				registrations.Add(registeredModel);
				return true;
			}
		}

		private static RegisteredModel[] GetSnapshot(List<RegisteredModel> registrations)
		{
			using (SyncRoot.EnterScope())
			{
				return registrations.ToArray();
			}
		}

		private static TModel[] AppendRegisteredModels<TModel>(TModel[] vanillaModels, IReadOnlyList<RegisteredModel> registrations, string contentKind) where TModel : AbstractModel
		{
			List<TModel> list = new List<TModel>(vanillaModels.Length + registrations.Count);
			list.AddRange(vanillaModels);
			foreach (RegisteredModel registration in registrations)
			{
				TModel byIdOrNull;
				try
				{
					byIdOrNull = ModelDb.GetByIdOrNull<TModel>(ModelDb.GetId(registration.ModelType));
				}
				catch (Exception value)
				{
					RitsuLibFramework.CreateLogger(registration.OwnerModId, (LogType)0).Warn($"[TrashHeap] Failed to resolve registered {contentKind} '{registration.ModelType.FullName}': {value}", 1);
					continue;
				}
				if (byIdOrNull != null)
				{
					list.Add(byIdOrNull);
				}
			}
			list.Sort(ModelComparer<TModel>.Instance);
			HashSet<ModelId> seenIds = new HashSet<ModelId>();
			return list.Where((TModel model) => seenIds.Add(((AbstractModel)model).Id)).ToArray();
		}
	}
}
