				int num = 0;
				IHoverTip[] array2 = (IHoverTip[])(object)new IHoverTip[1 + array3.Length];
				ReadOnlySpan<IHoverTip> readOnlySpan = new ReadOnlySpan<IHoverTip>(array3);
				readOnlySpan.CopyTo(new Span<IHoverTip>(array2).Slice(num, readOnlySpan.Length));
				num += readOnlySpan.Length;
				array2[num] = tip;
				IEnumerable<IHoverTip> enumerable = new global::<>z__ReadOnlyArray<IHoverTip>(array2);
				enumerable2 = enumerable;
