	internal sealed class ContentSourceNHoverTipSetShowPatch : IPatchMethod
	{
		private static readonly FieldInfo? CardsField = AccessTools.Field(typeof(NInspectCardScreen), "_cards");

		private static readonly FieldInfo? CardsIndexField = AccessTools.Field(typeof(NInspectCardScreen), "_index");

		private static readonly FieldInfo? RelicsField = AccessTools.Field(typeof(NInspectRelicScreen), "_relics");

		private static readonly FieldInfo? RelicsIndexField = AccessTools.Field(typeof(NInspectRelicScreen), "_index");

		public static string PatchId => "nhover_tip_set_inspect_screen_show_source";

		public static string Description => "Show content source in inspect screens, card preview hovers, and relic option hovers";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(NHoverTipSet), "CreateAndShow", new Type[3]
				{
					typeof(Control),
					typeof(IEnumerable<IHoverTip>),
					typeof(HoverTipAlignment)
				})
			};
		}

		private static void AppendModelSourceTipIfModelTipMissing(AbstractModel model, ref IEnumerable<IHoverTip> hoverTips)
		{
			IHoverTip[] array = hoverTips.ToArray();
			IHoverTip tip;
			if (array.Any((IHoverTip val2) => ((object)val2.CanonicalModel)?.GetType() == ((object)model).GetType() && val2.CanonicalModel.Id == model.Id))
			{
				hoverTips = array;
			}
			else if (ContentSourceHoverTipFactory.TryCreate(model, out tip))
			{
				IHoverTip val = tip;
				IHoverTip[] array2 = array;
				int num = 0;
				IHoverTip[] array3 = (IHoverTip[])(object)new IHoverTip[1 + array2.Length];
				array3[num] = val;
				num++;
				ReadOnlySpan<IHoverTip> readOnlySpan = new ReadOnlySpan<IHoverTip>(array2);
				readOnlySpan.CopyTo(new Span<IHoverTip>(array3).Slice(num, readOnlySpan.Length));
				num += readOnlySpan.Length;
				hoverTips = new global::<>z__ReadOnlyArray<IHoverTip>(array3);
			}
		}

		private static void AppendCardHoverTipSources(ref IEnumerable<IHoverTip> hoverTips)
		{
			IHoverTip[] array = hoverTips.ToArray();
			List<IHoverTip> list = null;
			HashSet<string> hashSet = null;
			foreach (CardHoverTip item in array.OfType<CardHoverTip>())
			{
				if (!ContentSourceHoverTipFactory.TryCreate((AbstractModel)(object)item.Card, out IHoverTip tip))
				{
					continue;
				}
				if (hashSet == null)
				{
					hashSet = new HashSet<string>();
				}
				if (hashSet.Add(tip.Id))
				{
					if (list == null)
					{
						list = new List<IHoverTip>();
					}
					list.Add(tip);
				}
			}
			if (list != null)
			{
				List<IHoverTip> list2 = list;
				IHoverTip[] array2 = array;
				int num = 0;
				IHoverTip[] array3 = (IHoverTip[])(object)new IHoverTip[list2.Count + array2.Length];
				Span<IHoverTip> span = CollectionsMarshal.AsSpan(list2);
				span.CopyTo(new Span<IHoverTip>(array3).Slice(num, span.Length));
				num += span.Length;
				ReadOnlySpan<IHoverTip> readOnlySpan = new ReadOnlySpan<IHoverTip>(array2);
				readOnlySpan.CopyTo(new Span<IHoverTip>(array3).Slice(num, readOnlySpan.Length));
				num += readOnlySpan.Length;
				hoverTips = new global::<>z__ReadOnlyArray<IHoverTip>(array3);
			}
		}

		private static void AppendTip<T>(FieldInfo? listField, FieldInfo? indexField, Control screen, ref IEnumerable<IHoverTip> hoverTips) where T : AbstractModel
		{
			if (listField == null || indexField == null)
			{
				return;
			}
			int num = (int)indexField.GetValue(screen);
			if (listField.GetValue(screen) is IReadOnlyList<T> readOnlyList && num >= 0 && num < readOnlyList.Count)
			{
				AbstractModel val = (AbstractModel)(object)readOnlyList[num];
				if (val != null)
				{
					ContentSourceHoverTipPatchHelper.Append(val, ref hoverTips);
				}
			}
		}

		public static void Prefix(Control owner, ref IEnumerable<IHoverTip> hoverTips)
		{
			if (!RitsuLibSettingsStore.IsModSourceHoverTipsEnabled())
			{
				return;
			}
			NInspectCardScreen val = (NInspectCardScreen)(object)((owner is NInspectCardScreen) ? owner : null);
			if (val == null)
			{
				NInspectRelicScreen val2 = (NInspectRelicScreen)(object)((owner is NInspectRelicScreen) ? owner : null);
				if (val2 != null)
				{
					AppendTip<RelicModel>(RelicsField, RelicsIndexField, (Control)(object)val2, ref hoverTips);
				}
			}
			else
			{
				AppendTip<CardModel>(CardsField, CardsIndexField, (Control)(object)val, ref hoverTips);
			}
			if (!RitsuLibSettingsStore.ShouldIncludeNonDetailModSourceHoverTips())
			{
				return;
			}
			NEventOptionButton val3 = (NEventOptionButton)(object)((owner is NEventOptionButton) ? owner : null);
			if (val3 != null)
			{
				EventOption option = val3.Option;
				if (option != null)
				{
					RelicModel relic = option.Relic;
					if (relic != null)
					{
						AppendModelSourceTipIfModelTipMissing((AbstractModel)(object)relic, ref hoverTips);
					}
				}
			}
			AppendCardHoverTipSources(ref hoverTips);
		}
	}
