	/// <summary>
	///     <para xml:lang="en">
	///         Prevents registered mod acts from entering vanilla act-list randomization unless they explicitly opt in.
	///     </para>
	///     <para xml:lang="zh-CN">阻止已注册模组章节默认参与原版章节列表随机选择，除非其显式加入。</para>
	/// </summary>
	internal class ActsByIndexPatch : IPatchMethod
	{
		public static string PatchId => "modeldb_acts_by_index";

		public static string Description => "Apply registered act random-list policy to ModelDb.ActsByIndex";

		public static bool IsCritical => true;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ModelDb), "ActsByIndex", (MethodType)1)
			};
		}

		[HarmonyAfter(new string[] { "BaseLib" })]
		[HarmonyPriority(0)]
		public static void Postfix(ref IReadOnlyList<IReadOnlyList<ActModel>> __result)
		{
			HashSet<Type> registeredTypes = ModContentRegistry.GetRegisteredActTypes().ToHashSet();
			bool hasRegisteredActs = registeredTypes.Count > 0;
			if (!hasRegisteredActs && !__result.Any((IReadOnlyList<ActModel> acts) => acts.Any((ActModel val) => val is IModActRandomListPolicy)))
			{
				return;
			}
			ActModel[] array = (from val in ModContentRegistry.AppendActs(Array.Empty<ActModel>())
				where val.Index >= 0
				where val is IModActRandomListPolicy modActRandomListPolicy && modActRandomListPolicy.AllowInRandomActList
				select val).ToArray();
			List<List<ActModel>> list = __result.Select((IReadOnlyList<ActModel> acts) => (from val in acts
				where !(val is IModActRandomListPolicy modActRandomListPolicy) || modActRandomListPolicy.AllowInRandomActList
				where !hasRegisteredActs || !registeredTypes.Contains(((object)val).GetType()) || (val is IModActRandomListPolicy modActRandomListPolicy && modActRandomListPolicy.AllowInRandomActList)
				select val).ToList()).ToList();
			ActModel[] array2 = array;
			foreach (ActModel act in array2)
			{
				while (list.Count <= act.Index)
				{
					list.Add(new List<ActModel>());
				}
				List<ActModel> list2 = list[act.Index];
				if (list2.All((ActModel existing) => ((AbstractModel)existing).Id != ((AbstractModel)act).Id))
				{
					list2.Add(act);
				}
			}
			while (list.Count > 0)
			{
				if (list[list.Count - 1].Count != 0)
				{
					break;
				}
				list.RemoveAt(list.Count - 1);
			}
			__result = list;
		}
	}
