	/// <summary>
	///     <para xml:lang="en">
	///         Rebuilds <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Serialization.ModelIdSerializationCache" /> in deterministic order after registered
	///         dynamic content has entered <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         已注册动态内容进入 <see cref="T:MegaCrit.Sts2.Core.Models.ModelDb" /> 后，按确定性顺序重建
	///         <see cref="T:MegaCrit.Sts2.Core.Multiplayer.Serialization.ModelIdSerializationCache" />。
	///     </para>
	/// </summary>
	internal sealed class ModelIdSerializationCacheDynamicContentPatch : IPatchMethod
	{
		internal readonly record struct ModelSortIds(int CategorySortingId, int EntrySortingId);

		private readonly record struct ModelCacheEntry(Type ModelType, ModelId Id, string OwnerModId);

		private sealed record ModelDbCacheSignature(uint Hash, int CategoryIdBitSize, int EntryIdBitSize, int EpochIdBitSize, int CategoryCount, int EntryCount, int EpochCount, uint CategoryMapHash, uint EntryMapHash, uint EpochMapHash);

		internal readonly record struct ModelDbDeterministicCacheRebuildResult(bool Applied, uint InitialHash, uint FinalHash, string? Reason)
		{
			public static ModelDbDeterministicCacheRebuildResult Rebuilt(uint initialHash, uint finalHash)
			{
				return new ModelDbDeterministicCacheRebuildResult(Applied: true, initialHash, finalHash, null);
			}

			public static ModelDbDeterministicCacheRebuildResult NotApplied(string reason)
			{
				return new ModelDbDeterministicCacheRebuildResult(Applied: false, 0u, 0u, reason);
			}
		}

		internal readonly record struct ModelDbDeterministicCacheStatus(bool IsActive, string Detail)
		{
			public static ModelDbDeterministicCacheStatus Active(string detail)
			{
				return new ModelDbDeterministicCacheStatus(IsActive: true, detail);
			}

			public static ModelDbDeterministicCacheStatus Inactive(string detail)
			{
				return new ModelDbDeterministicCacheStatus(IsActive: false, detail);
			}
		}

		private static int _staleCacheWarningLogged;

		internal static bool UsesDeterministicCache { get; private set; }

		private static ModelDbCacheSignature? AppliedDeterministicCacheSignature { get; set; }

		private static IReadOnlyDictionary<ModelId, ModelSortIds> LocalOnlyModelSortIds { get; set; } = new Dictionary<ModelId, ModelSortIds>();

		public static string PatchId => "model_id_serialization_cache_dynamic_content";

		public static string Description => "Rebuild ModelIdSerializationCache maps and hash from deterministically sorted final ModelDb content";

		public static bool IsCritical => true;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(ModelIdSerializationCache), "Init")
			};
		}

		[HarmonyPriority(800)]
		public static void Postfix()
		{
			ModelDbDeterministicSortMode modelDbDeterministicSortMode = RitsuLibSettingsStore.GetModelDbDeterministicSortMode();
			if (modelDbDeterministicSortMode == ModelDbDeterministicSortMode.Disabled)
			{
				UsesDeterministicCache = false;
				AppliedDeterministicCacheSignature = null;
				PatchLog.For<ModelIdSerializationCacheDynamicContentPatch>().Info("[ModelIdSerializationCache] Deterministic final-content cache disabled by settings.", 1);
			}
			else
			{
				LogAutomaticResult(RebuildDeterministicCache(modelDbDeterministicSortMode == ModelDbDeterministicSortMode.Force));
			}
		}

		internal static ModelDbDeterministicCacheRebuildResult RebuildDeterministicCacheForSettings()
		{
			return RebuildDeterministicCache(force: true);
		}

		internal static ModelDbDeterministicCacheStatus GetDeterministicCacheStatus()
		{
			if (!UsesDeterministicCache)
			{
				return ModelDbDeterministicCacheStatus.Inactive("Stable sorting is not active.");
			}
			ModelDbCacheSignature appliedDeterministicCacheSignature = AppliedDeterministicCacheSignature;
			if (appliedDeterministicCacheSignature == null)
			{
				return ModelDbDeterministicCacheStatus.Inactive("Stable sorting is not verifiable because no RitsuLib cache signature is available.");
			}
			ModelDbCacheSignature modelDbCacheSignature = TryCaptureCurrentCacheSignature();
			if (modelDbCacheSignature == null)
			{
				return ModelDbDeterministicCacheStatus.Inactive("Stable sorting is not verifiable because ModelIdSerializationCache internals are not available.");
			}
			if (modelDbCacheSignature == appliedDeterministicCacheSignature)
			{
				return ModelDbDeterministicCacheStatus.Active("Stable sorting");
			}
			if (Interlocked.Exchange(ref _staleCacheWarningLogged, 1) == 0)
			{
				PatchLog.For<ModelIdSerializationCacheDynamicContentPatch>().Warn($"[ModelIdSerializationCache] {"RitsuLib rebuilt the ModelIdSerializationCache, but the current cache no longer matches RitsuLib's deterministic signature. Another patch likely rewrote the cache or hash after RitsuLib."} Expected {appliedDeterministicCacheSignature}; current {modelDbCacheSignature}.", 1);
			}
			return ModelDbDeterministicCacheStatus.Inactive("RitsuLib rebuilt the ModelIdSerializationCache, but the current cache no longer matches RitsuLib's deterministic signature. Another patch likely rewrote the cache or hash after RitsuLib.");
		}

		private static ModelDbDeterministicCacheRebuildResult RebuildDeterministicCache(bool force)
		{
			UsesDeterministicCache = false;
			AppliedDeterministicCacheSignature = null;
			IDictionary modelDbContentById = GetModelDbContentById();
			if (modelDbContentById == null || modelDbContentById.Count == 0)
			{
				return ModelDbDeterministicCacheRebuildResult.NotApplied("ModelDb content is not available.");
			}
			if (!force && !HasRegisteredSerializationContent(modelDbContentById))
			{
				return ModelDbDeterministicCacheRebuildResult.NotApplied("No matching content was detected.");
			}
			Dictionary<string, int> staticField = GetStaticField<Dictionary<string, int>>(typeof(ModelIdSerializationCache), "_categoryNameToNetIdMap");
			List<string> staticField2 = GetStaticField<List<string>>(typeof(ModelIdSerializationCache), "_netIdToCategoryNameMap");
			Dictionary<string, int> staticField3 = GetStaticField<Dictionary<string, int>>(typeof(ModelIdSerializationCache), "_entryNameToNetIdMap");
			List<string> staticField4 = GetStaticField<List<string>>(typeof(ModelIdSerializationCache), "_netIdToEntryNameMap");
			Dictionary<string, int> staticField5 = GetStaticField<Dictionary<string, int>>(typeof(ModelIdSerializationCache), "_epochNameToNetIdMap");
			List<string> staticField6 = GetStaticField<List<string>>(typeof(ModelIdSerializationCache), "_netIdToEpochNameMap");
			if (staticField == null || staticField2 == null || staticField3 == null || staticField4 == null || staticField5 == null || staticField6 == null)
			{
				return ModelDbDeterministicCacheRebuildResult.NotApplied("ModelIdSerializationCache internals are not available.");
			}
			uint hash = ModelIdSerializationCache.Hash;
			ModelCacheEntry[] sortedModelEntries = GetSortedModelEntries(modelDbContentById, includeLocalOnly: false);
			ModelCacheEntry[] sortedModelEntries2 = GetSortedModelEntries(modelDbContentById, includeLocalOnly: true);
			string[] array = EpochModel.AllEpochIds.Distinct<string>(StringComparer.Ordinal).OrderBy<string, string>((string result) => result, StringComparer.Ordinal).ToArray();
			staticField.Clear();
			staticField2.Clear();
			staticField3.Clear();
			staticField4.Clear();
			staticField5.Clear();
			staticField6.Clear();
			EnsureCategory(ModelId.none.Category, staticField, staticField2);
			EnsureEntry(ModelId.none.Entry, staticField3, staticField4);
			ModelCacheEntry[] array2 = sortedModelEntries;
			foreach (ModelCacheEntry modelCacheEntry in array2)
			{
				ModelId id = modelCacheEntry.Id;
				EnsureCategory(id.Category, staticField, staticField2);
				EnsureEntry(id.Entry, staticField3, staticField4);
			}
			string[] array3 = array;
			for (int num = 0; num < array3.Length; num++)
			{
				EnsureEpoch(array3[num], staticField5, staticField6);
			}
			IReadOnlyDictionary<ModelId, ModelSortIds> readOnlyDictionary = (LocalOnlyModelSortIds = BuildLocalOnlySortIds(sortedModelEntries2, sortedModelEntries, staticField, staticField2.Count, staticField3, staticField4.Count));
			if (readOnlyDictionary.Count > 0)
			{
				PatchLog.For<ModelIdSerializationCacheDynamicContentPatch>().Info("[ModelIdSerializationCache] Assigned local-only sort IDs for " + $"{readOnlyDictionary.Count} non-gameplay ModelDb model(s); they are excluded from network maps and hash.", 1);
			}
			SetStaticProperty(typeof(ModelIdSerializationCache), "CategoryIdBitSize", GetBitSize(staticField2.Count));
			SetStaticProperty(typeof(ModelIdSerializationCache), "EntryIdBitSize", GetBitSize(staticField4.Count));
			SetStaticProperty(typeof(ModelIdSerializationCache), "EpochIdBitSize", GetBitSize(staticField6.Count));
			uint num2 = ComputeHash(sortedModelEntries, array, staticField2.Count, staticField4.Count, staticField6.Count);
			SetStaticProperty(typeof(ModelIdSerializationCache), "Hash", num2);
			UsesDeterministicCache = true;
			AppliedDeterministicCacheSignature = TryCaptureCurrentCacheSignature();
			Interlocked.Exchange(ref _staleCacheWarningLogged, 0);
			return ModelDbDeterministicCacheRebuildResult.Rebuilt(hash, num2);
		}

		private static void LogAutomaticResult(ModelDbDeterministicCacheRebuildResult result)
		{
			if (!result.Applied)
			{
				PatchLog.For<ModelIdSerializationCacheDynamicContentPatch>().Info("[ModelIdSerializationCache] Deterministic final-content cache not enabled.", 1);
				return;
			}
			PatchLog.For<ModelIdSerializationCacheDynamicContentPatch>().Info("[ModelIdSerializationCache] Deterministic final-content cache enabled. " + $"Hash: {result.InitialHash} -> {result.FinalHash}.", 1);
		}

		private static IDictionary? GetModelDbContentById()
		{
			return AccessTools.DeclaredField(typeof(ModelDb), "_contentById")?.GetValue(null) as IDictionary;
		}

		internal static bool TryGetLocalOnlySortIds(ModelId id, out ModelSortIds sortIds)
		{
			return LocalOnlyModelSortIds.TryGetValue(id, out sortIds);
		}

		internal static bool IsLocalOnlyModelId(ModelId id)
		{
			return LocalOnlyModelSortIds.ContainsKey(id);
		}

		private static bool HasRegisteredSerializationContent(IDictionary contentById)
		{
			foreach (DictionaryEntry item in contentById)
			{
				object? value = item.Value;
				AbstractModel val = (AbstractModel)((value is AbstractModel) ? value : null);
				if (val != null && ModContentRegistry.TryGetOwnerModId(((object)val).GetType(), out string _))
				{
					return true;
				}
			}
			return ModTimelineRegistry.RegisteredEpochCount() > 0;
		}

		private static ModelCacheEntry[] GetSortedModelEntries(IDictionary contentById, bool includeLocalOnly)
		{
			List<ModelCacheEntry> list = new List<ModelCacheEntry>(contentById.Count);
			foreach (DictionaryEntry item in contentById)
			{
				object key = item.Key;
				ModelId val = (ModelId)((key is ModelId) ? key : null);
				if (val == null)
				{
					continue;
				}
				object? value = item.Value;
				AbstractModel val2 = (AbstractModel)((value is AbstractModel) ? value : null);
				if (val2 != null)
				{
					Type type = ((object)val2).GetType();
					if (includeLocalOnly || Sts2ModManagerCompat.IsGameplayRelevantLoadedModType(type))
					{
						list.Add(new ModelCacheEntry(type, val, ResolveOwnerModId(type)));
					}
				}
			}
			list.Sort(CompareModelCacheEntries);
			return list.ToArray();
		}

