		}
	}
	internal sealed record ContentModInventoryEntry(int Index, string Id, string Version, string Name, string Source, ulong? WorkshopItemId, bool IsEnabled, bool AffectsGameplay, bool IsDependency);
	/// <summary>
	///     <para xml:lang="en">Defines stable framework IDs used by runtime interoperability checks.</para>
	///     <para xml:lang="zh-CN">定义运行时互操作检查使用的稳定框架 ID。</para>
	/// </summary>
	internal static class ExternalFrameworkIds
	{
		public const string BaseLib = "baselib";

		public const string BaseLibToRitsuGenerated = "baselib-to-ritsu-generated";

		public const string JmcModLib = "jmcmodlib";

		public const string ModConfig = "modconfig";
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Detects external frameworks through known type markers or registered custom detectors.
	///     </para>
	///     <para xml:lang="zh-CN">通过已知类型标记或已注册的自定义检测器判断外部框架是否存在。</para>
	/// </summary>
	internal static class ExternalFrameworkRegistry
	{
		private readonly record struct ProbeSpec(string FrameworkId, IReadOnlyList<string> TypeMarkers);

		private readonly record struct TypeResolution(Type? Type);

		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<string, Func<bool>> CustomDetectors = new Dictionary<string, Func<bool>>(StringComparer.OrdinalIgnoreCase);

		private static readonly ConcurrentDictionary<string, TypeResolution> TypeCache = new ConcurrentDictionary<string, TypeResolution>(StringComparer.Ordinal);

		private static readonly Dictionary<string, ProbeSpec> BuiltInProbes = new Dictionary<string, ProbeSpec>(StringComparer.OrdinalIgnoreCase)
		{
			["baselib"] = new ProbeSpec("baselib", new global::<>z__ReadOnlyArray<string>(new string[2] { "BaseLib.Patches.Hooks.MaxHandSizePatch", "BaseLib.Hooks.HealthBarForecastRegistry" })),
			["baselib-to-ritsu-generated"] = new ProbeSpec("baselib-to-ritsu-generated", new <>z__ReadOnlySingleElementList<string>("BaseLibToRitsu.Generated.ModConfigRegistry")),
			["jmcmodlib"] = new ProbeSpec("jmcmodlib", new global::<>z__ReadOnlyArray<string>(new string[2] { "JmcModLib.Config.ConfigManager", "JmcModLib.Core.ModRegistry" })),
			["modconfig"] = new ProbeSpec("modconfig", new <>z__ReadOnlySingleElementList<string>("ModConfig.ModConfigApi"))
		};

		private static readonly Dictionary<string, bool> PresenceCache = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase);

		/// <summary>
		///     <para xml:lang="en">Registers a custom detector, replacing any detector with the same framework ID.</para>
		///     <para xml:lang="zh-CN">注册自定义检测器，并替换框架 ID 相同的现有检测器。</para>
		/// </summary>
		public static void RegisterFrameworkDetector(string frameworkId, Func<bool> detector)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(frameworkId, "frameworkId");
			ArgumentNullException.ThrowIfNull(detector, "detector");
			using (Gate.EnterScope())
			{
				CustomDetectors[frameworkId] = detector;
				PresenceCache.Remove(frameworkId);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Returns whether the specified framework is detected.</para>
		///     <para xml:lang="zh-CN">返回是否检测到指定框架。</para>
		/// </summary>
		public static bool IsFrameworkPresent(string frameworkId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(frameworkId, "frameworkId");
			using (Gate.EnterScope())
			{
				if (PresenceCache.TryGetValue(frameworkId, out var value))
				{
					return value;
				}
				bool flag = DetectFrameworkCore(frameworkId);
				PresenceCache[frameworkId] = flag;
				return flag;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Clears cached results and detects every known framework again.</para>
		///     <para xml:lang="zh-CN">清除缓存结果，并重新检测所有已知框架。</para>
		/// </summary>
		public static void RefreshKnownFrameworkPresence(string reason)
		{
			TypeCache.Clear();
			using (Gate.EnterScope())
			{
				PresenceCache.Clear();
				foreach (string key in BuiltInProbes.Keys)
				{
					PresenceCache[key] = DetectFrameworkCore(key);
				}
				foreach (string key2 in CustomDetectors.Keys)
				{
					PresenceCache[key2] = DetectFrameworkCore(key2);
				}
			}
			RitsuLibFramework.Logger.Info("[Compat] External framework presence refreshed (" + reason + ").", 1);
		}

		/// <summary>
		///     <para xml:lang="en">Resolves <paramref name="fullTypeName" /> from loaded assemblies.</para>
		///     <para xml:lang="zh-CN">从已加载的程序集中解析 <paramref name="fullTypeName" />。</para>
		/// </summary>
		public static Type? ResolveType(string fullTypeName)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(fullTypeName, "fullTypeName");
			if (TypeCache.TryGetValue(fullTypeName, out var value))
			{
				return value.Type;
			}
			Type type = ResolveTypeCore(fullTypeName);
			return TypeCache.GetOrAdd(fullTypeName, new TypeResolution(type)).Type;
		}

		private static Type? ResolveTypeCore(string fullTypeName)
		{
			Type type = Type.GetType(fullTypeName);
			if (type != null)
			{
				return type;
			}
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			foreach (Assembly assembly in assemblies)
			{
				try
				{
					Type type2 = assembly.GetType(fullTypeName, throwOnError: false);
					if (type2 != null)
					{
						return type2;
					}
				}
				catch
				{
				}
			}
			return null;
		}

		private static bool DetectFrameworkCore(string frameworkId)
		{
			if (CustomDetectors.TryGetValue(frameworkId, out Func<bool> value))
			{
				try
				{
					return value();
				}
				catch (Exception ex)
				{
					RitsuLibFramework.Logger.Warn("[Compat] Custom framework detector '" + frameworkId + "' failed: " + ex.Message, 1);
					return false;
				}
			}
			if (BuiltInProbes.TryGetValue(frameworkId, out var value2))
			{
				return value2.TypeMarkers.Any((string typeName) => ResolveType(typeName) != null);
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Calls the parameterless <see cref="M:MegaCrit.Sts2.Core.Nodes.Combat.NCombatUi.AnimOut" /> overload on newer game versions, or
	///         <c>AnimOut(CombatRoom)</c> on older versions.
	///     </para>
	///     <para xml:lang="zh-CN">在较新游戏版本中调用无参数的 <see cref="M:MegaCrit.Sts2.Core.Nodes.Combat.NCombatUi.AnimOut" /> 重载；在较旧版本中调用 <c>AnimOut(CombatRoom)</c>。</para>
	/// </summary>
	internal static class NCombatUiAnimOutCompat
	{
		private static readonly Action<NCombatUi>? ZeroArg;

		private static readonly Action<NCombatUi, CombatRoom>? OneArg;

		static NCombatUiAnimOutCompat()
		{
			Type typeFromHandle = typeof(NCombatUi);
			MethodInfo zero = typeFromHandle.GetMethod("AnimOut", BindingFlags.Instance | BindingFlags.Public, null, Type.EmptyTypes, null);
			if (zero != null)
			{
				ZeroArg = delegate(NCombatUi ui)
				{
					zero.Invoke(ui, null);
				};
			}
			MethodInfo one = typeFromHandle.GetMethod("AnimOut", BindingFlags.Instance | BindingFlags.Public, null, new Type[1] { typeof(CombatRoom) }, null);
			if (one != null)
			{
				OneArg = delegate(NCombatUi ui, CombatRoom room)
				{
					one.Invoke(ui, new object[1] { room });
				};
			}
		}

		internal static void AnimOutForGameOver(NCombatUi ui, CombatRoom currentCombatRoom)
		{
			if (ZeroArg != null)
			{
				ZeroArg(ui);
			}
			else if (OneArg != null)
			{
				OneArg(ui, currentCombatRoom);
			}
			else
			{
				RitsuLibFramework.Logger.Warn("[Visuals] NCombatUi.AnimOut has no compatible overload; skipping combat UI AnimOut during game-over handling.", 1);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Applies skeleton overrides through either the legacy <c>Body</c> member or the newer <c>SpineBody</c>
	///         member.
	///     </para>
	///     <para xml:lang="zh-CN">通过旧版 <c>Body</c> 成员或新版 <c>SpineBody</c> 成员应用骨架覆盖。</para>
	/// </summary>
	internal static class NCreatureVisualsSpineCompat
	{
		private static readonly MethodInfo? SetSkeletonDataRes = typeof(MegaSprite).GetMethod("SetSkeletonDataRes", BindingFlags.Instance | BindingFlags.Public, null, new Type[1] { typeof(MegaSkeletonDataResource) }, null);

		internal static bool TryApplyCombatSkeletonOverride(NCreatureVisuals visuals, Resource skeletonData)
		{
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0023: Expected O, but got Unknown
			//IL_0091: Unknown result type (might be due to invalid IL or missing references)
			//IL_0096: Unknown result type (might be due to invalid IL or missing references)
			//IL_009c: Expected O, but got Unknown
			if (SetSkeletonDataRes == null || !visuals.HasSpineAnimation)
			{
				return false;
			}
			MegaSkeletonDataResource val = new MegaSkeletonDataResource(Variant.op_Implicit((GodotObject)(object)skeletonData));
			object obj = typeof(NCreatureVisuals).GetProperty("SpineBody", BindingFlags.Instance | BindingFlags.Public)?.GetValue(visuals);
			if (obj != null)
			{
				SetSkeletonDataRes.Invoke(obj, new object[1] { val });
				return true;
			}
			object? obj2 = typeof(NCreatureVisuals).GetProperty("Body", BindingFlags.Instance | BindingFlags.Public)?.GetValue(visuals);
			Node2D val2 = (Node2D)((obj2 is Node2D) ? obj2 : null);
			if (val2 == null)
			{
				return false;
			}
			MegaSprite obj3 = new MegaSprite(Variant.op_Implicit((GodotObject)(object)val2));
			SetSkeletonDataRes.Invoke(obj3, new object[1] { val });
			return true;
		}

		internal static bool HasSpineTargetForOverride(NCreatureVisuals visuals)
		{
			if (typeof(NCreatureVisuals).GetProperty("SpineBody", BindingFlags.Instance | BindingFlags.Public)?.GetValue(visuals) != null)
			{
				return true;
			}
			return typeof(NCreatureVisuals).GetProperty("Body", BindingFlags.Instance | BindingFlags.Public)?.GetValue(visuals) is Node2D;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides a stable API for querying the host's mod manager.</para>
	///     <para xml:lang="zh-CN">提供查询宿主模组管理器的稳定 API。</para>
	/// </summary>
	public static class RitsuModManager
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Returns every detected mod entry, including disabled, failed, duplicate, and runtime-added entries.
		///     </para>
		///     <para xml:lang="zh-CN">返回所有检测到的模组条目，包括已禁用、加载失败、重复及运行时新增的条目。</para>
		/// </summary>
		public static IReadOnlyList<RitsuModInfo> GetKnownMods()
		{
			return Sts2ModManagerCompat.BuildModInfos();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns detected entries for a mod ID. Use <paramref name="source" /> to distinguish local and Steam
		///         Workshop copies with the same ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回指定模组 ID 的已检测条目。可用 <paramref name="source" /> 区分 ID 相同的本地副本和
		///         Steam 创意工坊副本。
		///     </para>
		/// </summary>
		public static IReadOnlyList<RitsuModInfo> GetKnownMods(string modId, RitsuModSource? source = null)
		{
			ValidateModId(modId);
			return Sts2ModManagerCompat.BuildModInfos(modId, source);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the preferred current entry for a mod ID. Without a source filter, loaded and local entries rank
		///         ahead of disabled Steam Workshop duplicates.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取指定模组 ID 当前优先级最高的条目。未指定来源时，已加载和本地条目的优先级高于被禁用的 Steam
		///         创意工坊重复副本。
		///     </para>
		/// </summary>
		public static bool TryGetModInfo(string modId, out RitsuModInfo? info, RitsuModSource? source = null)
		{
			ValidateModId(modId);
			return Sts2ModManagerCompat.TryGetBestModInfo(modId, source, out info);
		}

		/// <summary>
		///     <para xml:lang="en">Returns whether the host detected an entry for the mod ID.</para>
		///     <para xml:lang="zh-CN">返回宿主是否检测到指定模组 ID 的条目。</para>
		/// </summary>
		public static bool ModExists(string modId, RitsuModSource? source = null)
		{
			ValidateModId(modId);
			RitsuModInfo info;
			return Sts2ModManagerCompat.TryGetBestModInfo(modId, source, out info);
		}

		/// <summary>
		///     <para xml:lang="en">Returns whether the mod is pending load or already loaded in this session.</para>
		///     <para xml:lang="zh-CN">返回该模组在本次会话中是否等待加载或已加载。</para>
		/// </summary>
		public static bool WillModLoad(string modId, RitsuModSource? source = null)
		{
			ValidateModId(modId);
			return Sts2ModManagerCompat.BuildModInfos(modId, source).Any((RitsuModInfo mod) => mod.WillLoad);
		}

		/// <summary>
		///     <para xml:lang="en">Returns whether the mod loaded successfully in this session.</para>
		///     <para xml:lang="zh-CN">返回该模组在本次会话中是否已成功加载。</para>
		/// </summary>
		public static bool IsModLoaded(string modId, RitsuModSource? source = null)
		{
			ValidateModId(modId);
			return Sts2ModManagerCompat.BuildModInfos(modId, source).Any((RitsuModInfo mod) => mod.IsLoaded);
		}

		private static void ValidateModId(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
		}
	}
	/// <summary>
	///     <para xml:lang="en">Identifies a mod source reported through RitsuLib's stable API.</para>
	///     <para xml:lang="zh-CN">标识通过 RitsuLib 稳定 API 报告的模组来源。</para>
	/// </summary>
	public enum RitsuModSource
	{
		/// <summary>
		///     <para xml:lang="en">The source could not be mapped from the host API.</para>
		///     <para xml:lang="zh-CN">无法从宿主 API 映射来源。</para>
		/// </summary>
		Unknown,
		/// <summary>
		///     <para xml:lang="en">The mod was discovered in the local mods directory.</para>
		///     <para xml:lang="zh-CN">模组来自本地 mods 目录。</para>
		/// </summary>
		ModsDirectory,
		/// <summary>
		///     <para xml:lang="en">The mod was discovered through Steam Workshop.</para>
		///     <para xml:lang="zh-CN">模组来自 Steam 创意工坊。</para>
		/// </summary>
		SteamWorkshop
	}
	/// <summary>
	///     <para xml:lang="en">Identifies a mod load state reported through RitsuLib's stable API.</para>
	///     <para xml:lang="zh-CN">标识通过 RitsuLib 稳定 API 报告的模组加载状态。</para>
	/// </summary>
	public enum RitsuModLoadState
	{
		/// <summary>
		///     <para xml:lang="en">The state could not be mapped from the host API.</para>
		///     <para xml:lang="zh-CN">无法从宿主 API 映射状态。</para>
		/// </summary>
		Unknown,
		/// <summary>
		///     <para xml:lang="en">The host detected the mod but has not attempted to load it.</para>
		///     <para xml:lang="zh-CN">宿主已检测到该模组，但尚未尝试加载。</para>
		/// </summary>
		Pending,
		/// <summary>
		///     <para xml:lang="en">The mod loaded successfully in this session.</para>
		///     <para xml:lang="zh-CN">该模组已在本次会话中成功加载。</para>
		/// </summary>
		Loaded,
		/// <summary>
		///     <para xml:lang="en">The mod was detected but failed to load.</para>
		///     <para xml:lang="zh-CN">已检测到该模组，但加载失败。</para>
		/// </summary>
		Failed,
		/// <summary>
		///     <para xml:lang="en">The mod is disabled for this session.</para>
		///     <para xml:lang="zh-CN">该模组在本次会话中被禁用。</para>
		/// </summary>
		Disabled,
		/// <summary>
		///     <para xml:lang="en">The mod was disabled because another copy with the same ID takes precedence.</para>
		///     <para xml:lang="zh-CN">该模组因另一个 ID 相同的副本优先而被禁用。</para>
		/// </summary>
		DisabledDuplicate,
		/// <summary>
		///     <para xml:lang="en">The mod was detected after startup and cannot load until a later session.</para>
		///     <para xml:lang="zh-CN">该模组在启动后才被检测到，需在之后的会话中加载。</para>
		/// </summary>
		AddedAtRuntime
	}
	/// <summary>
	///     <para xml:lang="en">Contains a stable snapshot of a detected mod entry.</para>
	///     <para xml:lang="zh-CN">包含已检测模组条目的稳定快照。</para>
	/// </summary>
	public sealed record RitsuModInfo(string Id, string Name, string? Author, string? Version, RitsuModLoadState State, RitsuModSource Source, bool AffectsGameplay, string? AssemblyName, string? AssemblyVersion, IReadOnlyList<LocString> Errors, ulong? WorkshopItemId = null)
	{
		/// <summary>
		///     <para xml:lang="en">Gets whether the mod is pending load or already loaded in this session.</para>
		///     <para xml:lang="zh-CN">获取该模组在本次会话中是否等待加载或已加载。</para>
		/// </summary>
		public bool WillLoad
		{
			get
			{
				RitsuModLoadState state = State;
				if ((uint)(state - 1) <= 1u)
				{
					return true;
				}
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether the mod loaded successfully in this session.</para>
		///     <para xml:lang="zh-CN">获取该模组在本次会话中是否已成功加载。</para>
		/// </summary>
		public bool IsLoaded => State == RitsuModLoadState.Loaded;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether this is a Steam Workshop copy disabled in favor of another copy with the same ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取此条目是否为因另一个 ID 相同副本优先而被禁用的 Steam 创意工坊副本。
		///     </para>
		/// </summary>
		public bool IsDisabledSteamWorkshopDuplicate
		{
			get
			{
				if (Source == RitsuModSource.SteamWorkshop)
				{
					return State == RitsuModLoadState.DisabledDuplicate;
				}
				return false;
			}
		}
	}
	internal static class RuntimeFrameworkVersionSummary
	{
		internal static string BuildRitsuLibDisplayLine()
		{
			string value = (RitsuLibBuildInfo.IsDevBuild ? (" [dev build: " + RitsuLibBuildInfo.InformationalVersion + "]") : "");
			return $"RitsuLib: v{"0.5.18"}{value} (compat {RitsuLibFramework.GetCompatBranchLabel()})";
		}

		internal static bool TryBuildBaseLibDisplayLine(out string line)
		{
			if (TryGetBaseLibVersionText(out string versionText))
			{
				line = "BaseLib: " + versionText;
				return true;
			}
			line = "";
			return false;
		}

		internal static string BuildUiText(bool includeMissingBaseLib)
		{
			IReadOnlyList<string> values = BuildDisplayLines(includeMissingBaseLib);
			return string.Join("\n", values);
		}

		internal static string BuildInlineUiText(bool includeMissingBaseLib)
		{
			IReadOnlyList<string> values = BuildDisplayLines(includeMissingBaseLib);
			return string.Join("  |  ", values);
		}

		internal static IReadOnlyList<string> BuildDisplayLines(bool includeMissingBaseLib)
		{
			List<string> list = new List<string> { BuildRitsuLibDisplayLine() };
			if (TryBuildBaseLibDisplayLine(out string line))
			{
				list.Add(line);
			}
			else if (includeMissingBaseLib)
			{
				list.Add("BaseLib: not detected");
			}
			return list;
		}

		private static bool TryGetBaseLibVersionText(out string versionText)
		{
			if (TryGetBaseLibModInfo(out RitsuModInfo info))
			{
				versionText = FormatVersionText(info.Version, info.AssemblyVersion);
				return true;
			}
			if (TryGetBaseLibAssemblyVersion(out string assemblyVersion))
			{
				versionText = (string.IsNullOrWhiteSpace(assemblyVersion) ? "detected, version unknown" : ("assembly " + assemblyVersion));
				return true;
			}
			versionText = "";
			return false;
		}

		private static bool TryGetBaseLibModInfo(out RitsuModInfo info)
		{
			info = null;
			try
			{
				if (RitsuModManager.TryGetModInfo("BaseLib", out RitsuModInfo info2) && info2 != null)
				{
					info = info2;
					return true;
				}
				info = RitsuModManager.GetKnownMods().Where(IsBaseLibModInfo).OrderBy(GetModInfoRank)
					.FirstOrDefault();
				return info != null;
			}
			catch
			{
				return false;
			}
		}

		private static bool IsBaseLibModInfo(RitsuModInfo info)
		{
			if (!string.Equals(info.Id, "BaseLib", StringComparison.OrdinalIgnoreCase) && !string.Equals(info.Id, "baselib", StringComparison.OrdinalIgnoreCase))
			{
				return string.Equals(info.AssemblyName, "BaseLib", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}

		private static int GetModInfoRank(RitsuModInfo info)
		{
			return info.State switch
			{
				RitsuModLoadState.Loaded => 0, 
				RitsuModLoadState.Pending => 1, 
				RitsuModLoadState.AddedAtRuntime => 2, 
				RitsuModLoadState.Failed => 3, 
				RitsuModLoadState.Disabled => 4, 
				RitsuModLoadState.DisabledDuplicate => 5, 
				_ => 6, 
			};
		}

		private static bool TryGetBaseLibAssemblyVersion(out string? assemblyVersion)
		{
			assemblyVersion = null;
			try
			{
				Assembly assembly = AppDomain.CurrentDomain.GetAssemblies().FirstOrDefault((Assembly item) => string.Equals(item.GetName().Name, "BaseLib", StringComparison.OrdinalIgnoreCase));
				if (assembly == null && !ExternalFrameworkRegistry.IsFrameworkPresent("baselib"))
				{
					return false;
				}
				if ((object)assembly == null)
				{
					assembly = AppDomain.CurrentDomain.GetAssemblies().FirstOrDefault((Assembly item) => item.GetType("BaseLib.BaseLibMain", throwOnError: false) != null);
				}
				assemblyVersion = ((assembly == null) ? null : ResolveAssemblyVersion(assembly));
				return true;
			}
			catch
			{
				return false;
			}
		}

		private static string FormatVersionText(string? manifestVersion, string? assemblyVersion)
		{
			if (!string.IsNullOrWhiteSpace(manifestVersion))
			{
				return manifestVersion.Trim();
			}
			if (!string.IsNullOrWhiteSpace(assemblyVersion))
			{
				return "assembly " + assemblyVersion.Trim();
			}
			return "detected, version unknown";
		}

		private static string? ResolveAssemblyVersion(Assembly assembly)
		{
			string text = assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion;
			if (string.IsNullOrWhiteSpace(text))
			{
				return assembly.GetName().Version?.ToString();
			}
			return text.Trim();
		}
	}
