	/// <summary>
	///     <para xml:lang="en">
	///         Resolves the running game's version on a best-effort basis from release metadata or the game assembly.
	///     </para>
	///     <para xml:lang="zh-CN">尽可能从发布元数据或游戏程序集解析当前运行游戏的版本。</para>
	/// </summary>
	internal static class Sts2HostVersion
	{
		private readonly record struct HostVersionSnapshot(Version? Numeric, string? ReleaseLabel);

		private static readonly Lazy<HostVersionSnapshot> Lazy = new Lazy<HostVersionSnapshot>(Resolve);

		/// <summary>
		///     <para xml:lang="en">Gets the parsed numeric version, or <see langword="null" /> when unavailable.</para>
		///     <para xml:lang="zh-CN">获取解析出的数字版本；无法取得时为 <see langword="null" />。</para>
		/// </summary>
		internal static Version? Numeric => Lazy.Value.Numeric;

		/// <summary>
		///     <para xml:lang="en">Gets the original release label when one was found.</para>
		///     <para xml:lang="zh-CN">获取找到的原始发布版本标签。</para>
		/// </summary>
		internal static string? ReleaseLabel => Lazy.Value.ReleaseLabel;

		private static HostVersionSnapshot Resolve()
		{
			string fallbackLabel = null;
			try
			{
				ReleaseInfo releaseInfo = ReleaseInfoManager.Instance.ReleaseInfo;
				if (TryCaptureVersionLabel((releaseInfo != null) ? releaseInfo.Version : null, ref fallbackLabel, out var snapshot))
				{
					return snapshot;
				}
			}
			catch
			{
			}
			if (TryResolvePublishedReleaseInfo(ref fallbackLabel, out var snapshot2))
			{
				return snapshot2;
			}
			if (TryResolveLauncherDownloadedReleaseInfo(ref fallbackLabel, out var snapshot3))
			{
				return snapshot3;
			}
			if (TryResolveLauncherCacheStamp(ref fallbackLabel, out var snapshot4))
			{
				return snapshot4;
			}
			Version version = typeof(SerializableRun).Assembly.GetName().Version;
			if (version != null && !IsAllZero(version))
			{
				return new HostVersionSnapshot(version, fallbackLabel);
			}
			return new HostVersionSnapshot(null, fallbackLabel);
		}

		private static bool IsAllZero(Version v)
		{
			if ((object)v != null && v.Major == 0 && v.Minor == 0 && v.Build <= 0)
			{
				return v.Revision <= 0;
			}
			return false;
		}

		private static bool TryCaptureVersionLabel(string? label, ref string? fallbackLabel, out HostVersionSnapshot snapshot)
		{
			snapshot = default(HostVersionSnapshot);
			if (string.IsNullOrWhiteSpace(label))
			{
				return false;
			}
			if (fallbackLabel == null)
			{
				fallbackLabel = label;
			}
			if (!TryParseVersionCore(label, out Version version))
			{
				return false;
			}
			snapshot = new HostVersionSnapshot(version, label);
			return true;
		}

		private static bool TryResolveLauncherDownloadedReleaseInfo(ref string? fallbackLabel, out HostVersionSnapshot snapshot)
		{
			snapshot = default(HostVersionSnapshot);
			string text = TryGetGodotDataDir();
			if (string.IsNullOrWhiteSpace(text))
			{
				return false;
			}
			return TryReadJsonVersion(Path.Combine(text, "game", "release_info.json"), "version", ref fallbackLabel, out snapshot);
		}

		private static bool TryResolvePublishedReleaseInfo(ref string? fallbackLabel, out HostVersionSnapshot snapshot)
		{
			snapshot = default(HostVersionSnapshot);
			foreach (string publishedReleaseInfoPath in GetPublishedReleaseInfoPaths())
			{
				if (TryReadJsonVersion(publishedReleaseInfoPath, "version", ref fallbackLabel, out snapshot))
				{
					return true;
				}
			}
			return false;
		}

		private static IEnumerable<string> GetPublishedReleaseInfoPaths()
		{
			string text = TryCallGodotOsString("GetExecutablePath");
			if (string.IsNullOrWhiteSpace(text))
			{
				yield break;
			}
			string executableDir = Path.GetDirectoryName(text);
			if (!string.IsNullOrWhiteSpace(executableDir))
			{
				if (string.Equals(TryCallGodotOsString("GetName"), "macOS", StringComparison.Ordinal))
				{
					yield return Path.Combine(executableDir, "..", "Resources", "release_info.json");
				}
				yield return Path.Combine(executableDir, "release_info.json");
			}
		}

		private static bool TryResolveLauncherCacheStamp(ref string? fallbackLabel, out HostVersionSnapshot snapshot)
		{
			snapshot = default(HostVersionSnapshot);
			string text = TryGetGodotDataDir();
			if (string.IsNullOrWhiteSpace(text))
			{
				return false;
			}
			string path = Path.Combine(text, ".cache_stamp");
			if (TryReadJsonVersion(path, "version", ref fallbackLabel, out snapshot))
			{
				return true;
			}
			try
			{
				if (!File.Exists(path))
				{
					return false;
				}
				using JsonDocument jsonDocument = JsonDocument.Parse(File.ReadAllText(path));
				if (!jsonDocument.RootElement.TryGetProperty("buildId", out var value))
				{
					return false;
				}
				string text2 = value.GetString();
				if (string.IsNullOrWhiteSpace(text2))
				{
					return false;
				}
				if (fallbackLabel == null)
				{
					fallbackLabel = "buildid:" + text2;
				}
			}
			catch
			{
			}
			return false;
		}

		private static bool TryReadJsonVersion(string path, string propertyName, ref string? fallbackLabel, out HostVersionSnapshot snapshot)
		{
			snapshot = default(HostVersionSnapshot);
			try
			{
				if (!File.Exists(path))
				{
					return false;
				}
				using JsonDocument jsonDocument = JsonDocument.Parse(File.ReadAllText(path));
				JsonElement value;
				return jsonDocument.RootElement.TryGetProperty(propertyName, out value) && TryCaptureVersionLabel(value.GetString(), ref fallbackLabel, out snapshot);
			}
			catch
			{
				return false;
			}
		}

		private static string? TryGetGodotDataDir()
		{
			return TryCallGodotOsString("GetDataDir");
		}

		private static string? TryCallGodotOsString(string methodName)
		{
			try
			{
				return ((Type.GetType("Godot.OS, GodotSharp", throwOnError: false) ?? Type.GetType("Godot.OS, GodotSharpEditor", throwOnError: false) ?? (from asm in AppDomain.CurrentDomain.GetAssemblies()
					select asm.GetType("Godot.OS", throwOnError: false)).FirstOrDefault((Type type) => type != null))?.GetMethod(methodName, BindingFlags.Static | BindingFlags.Public))?.Invoke(null, null) as string;
			}
			catch
			{
				return null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Parses <c>major.minor[.build[.revision]]</c> after removing a leading <c>v</c> and common semantic
		///         version suffixes.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         移除开头的 <c>v</c> 及常见语义化版本后缀后，解析
		///         <c>major.minor[.build[.revision]]</c>。
		///     </para>
		/// </summary>
		internal static bool TryParseVersionCore(string text, out Version version)
		{
			string text2 = text.Trim();
			int num = text2.IndexOf('-', StringComparison.Ordinal);
			if (num >= 0)
			{
				text2 = text2.Substring(0, num).Trim();
			}
			int num2 = text2.IndexOf('+', StringComparison.Ordinal);
			if (num2 >= 0)
			{
				text2 = text2.Substring(0, num2).Trim();
			}
			if (text2.Length >= 2 && (text2[0] == 'v' || text2[0] == 'V') && char.IsDigit(text2[1]))
			{
				text2 = text2.Substring(1);
			}
			if (Version.TryParse(text2, out Version result))
			{
				version = result;
				return true;
			}
			version = new Version(0, 0);
			return false;
		}
	}
