					{
						continue;
					}
					result = itemId2;
					goto IL_00ce;
				}
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Compat] Failed to inspect Workshop item id for a registered mod: " + ex.Message, 1);
			}
			return null;
			IL_00ce:
			return result;
		}

