			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Compat] Failed to describe a registered mod for inventory telemetry: " + ex.Message, 1);
				return null;
			}
		}

		private static IReadOnlyList<Sts2LoadedModAssemblyEntry> TryBuildLoadedModAssemblyEntries(Mod mod)
		{
			try
			{
				ModManifest manifest = ReadManifest(mod);
				Assembly[] array = ReadAssemblies(mod).Distinct().ToArray();
				if (array.Length == 0)
				{
					return Array.Empty<Sts2LoadedModAssemblyEntry>();
				}
				string text = ResolveAssemblyName(array.FirstOrDefault())?.Name ?? "<unknown>";
				string id = ((manifest == (ModManifest)null) ? text : (ReadManifestId(manifest) ?? text));
				string name = ((manifest == (ModManifest)null) ? text : (ReadManifestName(manifest) ?? text));
				List<Sts2LoadedModAssemblyEntry> list = new List<Sts2LoadedModAssemblyEntry>();
				list.AddRange(array.Select((Assembly assembly) => new Sts2LoadedModAssemblyEntry(id, name, (manifest == (ModManifest)null) ? null : ReadManifestVersion(manifest), assembly)));
				return new <>z__ReadOnlyList<Sts2LoadedModAssemblyEntry>(list);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Compat] Failed to inspect a loaded mod assembly for compatibility diagnostics: " + ex.Message, 1);
				return Array.Empty<Sts2LoadedModAssemblyEntry>();
			}
		}

		private static RitsuModInfo? TryBuildModInfo(Mod mod)
		{
			try
			{
				ModManifest val = ReadManifest(mod);
				AssemblyName assemblyName = ResolveAssemblyName(ReadAssembly(mod));
				IReadOnlyList<LocString> readOnlyList = ReadErrors(mod);
				string text = assemblyName?.Name ?? "<unknown>";
				string id = ((val == (ModManifest)null) ? text : (ReadManifestId(val) ?? text));
				string name = ((val == (ModManifest)null) ? text : (ReadManifestName(val) ?? text));
				return new RitsuModInfo(id, name, (val == (ModManifest)null) ? null : ReadManifestAuthor(val), (val == (ModManifest)null) ? null : ReadManifestVersion(val), ParseLoadState(ReadLoadState(mod, readOnlyList.Count)), ParseSource(ReadSource(mod)), val == (ModManifest)null || ReadManifestAffectsGameplay(val), assemblyName?.Name, assemblyName?.Version?.ToString(), readOnlyList, TryGetWorkshopItemId(mod));
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Compat] Failed to describe a registered mod for ModManager interop: " + ex.Message, 1);
				return null;
			}
		}

		private static RitsuModPresentationInfo? TryBuildModPresentationInfo(Mod mod)
		{
			try
			{
				ModManifest val = ReadManifest(mod);
				AssemblyName? assemblyName = ResolveAssemblyName(ReadAssembly(mod));
				IReadOnlyList<LocString> readOnlyList = ReadErrors(mod);
				string text = assemblyName?.Name ?? "<unknown>";
				string text2 = ((val == (ModManifest)null) ? text : (ReadManifestId(val) ?? text));
				string name = ((val == (ModManifest)null) ? text : (ReadManifestName(val) ?? text));
				RitsuModSource source = ParseSource(ReadSource(mod));
				RitsuModLoadState state = ParseLoadState(ReadLoadState(mod, readOnlyList.Count));
				return new RitsuModPresentationInfo(text2, name, (val == (ModManifest)null) ? null : ReadManifestAuthor(val), (val == (ModManifest)null) ? null : ReadManifestVersion(val), (val == (ModManifest)null) ? null : ReadManifestDescription(val), "res://" + text2 + "/mod_image.png", GetBestModPresentationRank(state, source));
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Compat] Failed to describe a registered mod for settings UI presentation: " + ex.Message, 1);
				return null;
			}
		}

		private static bool TryModOwnsAssembly(Mod mod, Assembly assembly)
		{
			try
			{
				return ReadAssemblies(mod).Contains(assembly);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[Compat] Failed to inspect mod assemblies for settings UI presentation: " + ex.Message, 1);
				return false;
			}
		}

		private static bool MatchesModQuery(RitsuModInfo entry, string? modId, RitsuModSource? source)
		{
			if (modId != null && !string.Equals(entry.Id, modId, StringComparison.Ordinal))
			{
				return false;
			}
			if (source.HasValue)
			{
				return entry.Source == source.Value;
			}
			return true;
		}

		private static int GetBestModInfoRank(RitsuModInfo entry)
		{
			return entry.State switch
			{
				RitsuModLoadState.Loaded => 0, 
				RitsuModLoadState.Pending => 1, 
				RitsuModLoadState.AddedAtRuntime => 2, 
				RitsuModLoadState.Failed => 3, 
				RitsuModLoadState.Disabled => 4, 
				RitsuModLoadState.DisabledDuplicate => 5, 
				_ => 6, 
			} * 10 + entry.Source switch
			{
				RitsuModSource.ModsDirectory => 0, 
				RitsuModSource.SteamWorkshop => 1, 
				_ => 2, 
			};
		}

		private static int GetBestModPresentationRank(RitsuModLoadState state, RitsuModSource source)
		{
			return state switch
			{
				RitsuModLoadState.Loaded => 0, 
				RitsuModLoadState.Pending => 1, 
				RitsuModLoadState.AddedAtRuntime => 2, 
				RitsuModLoadState.Failed => 3, 
				RitsuModLoadState.Disabled => 4, 
				RitsuModLoadState.DisabledDuplicate => 5, 
				_ => 6, 
			} * 10 + source switch
			{
				RitsuModSource.ModsDirectory => 0, 
				RitsuModSource.SteamWorkshop => 1, 
				_ => 2, 
			};
		}

		private static RitsuModSource ParseSource(string source)
		{
			if (!(source == "ModsDirectory"))
			{
				if (source == "SteamWorkshop")
				{
					return RitsuModSource.SteamWorkshop;
				}
				return RitsuModSource.Unknown;
			}
			return RitsuModSource.ModsDirectory;
		}

		private static RitsuModLoadState ParseLoadState(string state)
		{
			return state switch
			{
				"None" => RitsuModLoadState.Pending, 
				"Loaded" => RitsuModLoadState.Loaded, 
				"Failed" => RitsuModLoadState.Failed, 
				"Disabled" => RitsuModLoadState.Disabled, 
				"DisabledDuplicate" => RitsuModLoadState.DisabledDuplicate, 
				"AddedAtRuntime" => RitsuModLoadState.AddedAtRuntime, 
				_ => RitsuModLoadState.Unknown, 
			};
		}

		private static Func<Mod, ModManifest?> CreateModManifestAccessor()
		{
			if (typeof(Mod).GetField("manifest", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic) != null)
			{
				return (Mod mod) => mod.manifest;
			}
			Func<object, object?> getter = CreateUntypedMemberGetter(typeof(Mod), "manifest");
			return delegate(Mod mod)
			{
				object? obj = getter?.Invoke(mod);
				return (ModManifest?)((obj is ModManifest) ? obj : null);
			};
		}

		private static Func<Mod, IReadOnlyList<Assembly>> CreateModAssembliesAccessor()
		{
			if (typeof(Mod).GetField("assemblies", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic) != null)
			{
				return (Mod mod) => mod.assemblies;
			}
			Func<object, object?> assembliesGetter = CreateUntypedMemberGetter(typeof(Mod), "assemblies");
			if (assembliesGetter != null)
			{
				return (Mod mod) => NormalizeAssemblies(assembliesGetter(mod) as IEnumerable<Assembly>);
			}
			Func<object, object?> getter = CreateUntypedMemberGetter(typeof(Mod), "assembly");
			return (Mod mod) => (!(getter?.Invoke(mod) is Assembly item)) ? ((IReadOnlyList<Assembly>)Array.Empty<Assembly>()) : ((IReadOnlyList<Assembly>)new <>z__ReadOnlySingleElementList<Assembly>(item));
		}

		private static MethodInfo? CreateAssociateAssemblyWithModMethod()
		{
			return typeof(ModManager).GetMethod("AssociateAssemblyWithMod", BindingFlags.Static | BindingFlags.Public, null, new Type[2]
			{
				typeof(string),
				typeof(Assembly)
			}, null);
		}

		private static Func<Mod, IReadOnlyList<LocString>> CreateModErrorsAccessor()
		{
			if (typeof(Mod).GetField("errors", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic) != null)
			{
				return (Mod mod) => NormalizeErrors(mod.errors);
			}
			Func<object, object?> getter = CreateUntypedMemberGetter(typeof(Mod), "errors");
			return (Mod mod) => NormalizeErrors(getter?.Invoke(mod) as IEnumerable<LocString>);
		}

		private static Func<Mod, string> CreateModSourceAccessor()
		{
			if (typeof(Mod).GetField("modSource", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic) != null)
			{
				return (Mod mod) => ((object)Unsafe.As<ModSource, ModSource>(ref mod.modSource)/*cast due to constrained. prefix*/).ToString();
			}
			Func<object, object?> getter = CreateUntypedMemberGetter(typeof(Mod), "modSource");
			return (Mod mod) => getter?.Invoke(mod)?.ToString() ?? "None";
		}

		private static Func<Mod, string?> CreateModPathAccessor()
		{
			if (typeof(Mod).GetField("path", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic) != null)
			{
				return (Mod mod) => mod.path;
			}
			Func<object, object?> getter = CreateUntypedMemberGetter(typeof(Mod), "path");
			return (Mod mod) => getter?.Invoke(mod) as string;
		}

		private static Func<Mod, ulong?> CreateModWorkshopItemIdAccessor()
		{
			Func<object, object?> getter = CreateUntypedMemberGetter(typeof(Mod), "workshopId");
			return (Mod mod) => getter?.Invoke(mod) as ulong?;
		}

		private static Func<Mod, int, string> CreateLoadStateAccessor()
		{
			if (typeof(Mod).GetField("state", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic) != null)
			{
				return (Mod mod, int _) => ((object)Unsafe.As<ModLoadState, ModLoadState>(ref mod.state)/*cast due to constrained. prefix*/).ToString();
			}
			Func<object, object?> stateGetter = CreateUntypedMemberGetter(typeof(Mod), "state");
			Func<object, object?> wasLoadedGetter = CreateUntypedMemberGetter(typeof(Mod), "wasLoaded");
			Func<object, object?> assemblyLoadedSuccessfullyGetter = CreateUntypedMemberGetter(typeof(Mod), "assemblyLoadedSuccessfully");
			return delegate(Mod mod, int errorCount)
			{
				object obj = stateGetter?.Invoke(mod);
				if (obj != null)
				{
					return obj.ToString() ?? "None";
				}
				if (ReadBool(wasLoadedGetter, mod) == true)
				{
					return "Loaded";
				}
				return (ReadBool(assemblyLoadedSuccessfullyGetter, mod) == false || errorCount > 0) ? "Failed" : "None";
			};
		}

		private static Func<ModManifest, string?> CreateManifestStringAccessor(string memberName, Func<ModManifest, string?> directAccessor)
		{
			if (typeof(ModManifest).GetField(memberName, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic) != null)
			{
				return directAccessor;
			}
			Func<object, object?> getter = CreateUntypedMemberGetter(typeof(ModManifest), memberName);
			return (ModManifest manifest) => getter?.Invoke(manifest) as string;
		}

		private static Func<ModManifest, bool> CreateManifestBoolAccessor(string memberName, Func<ModManifest, bool> directAccessor, bool defaultValue)
		{
			if (typeof(ModManifest).GetField(memberName, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic) != null)
			{
				return directAccessor;
			}
			Func<object, object?> getter = CreateUntypedMemberGetter(typeof(ModManifest), memberName);
			return (ModManifest manifest) => ReadBool(getter, manifest).GetValueOrDefault(defaultValue);
		}

		private static AssemblyName? ResolveAssemblyName(Assembly? assembly)
		{
			if (assembly == null)
			{
				return null;
			}
			try
			{
				return assembly.GetName();
			}
			catch
			{
				return null;
			}
		}

		private static IReadOnlyList<LocString> NormalizeErrors(IEnumerable<LocString>? errors)
		{
			return errors?.Where((LocString error) => error != null).ToArray() ?? Array.Empty<LocString>();
		}

		private static IReadOnlyList<Assembly> NormalizeAssemblies(IEnumerable<Assembly>? assemblies)
		{
			return assemblies?.Where((Assembly assembly) => assembly != null).ToArray() ?? Array.Empty<Assembly>();
		}

		private static bool? ReadBool(Func<object, object?>? getter, object target)
		{
			object obj = getter?.Invoke(target);
			if (!(obj is bool))
			{
				return null;
			}
			return (bool)obj;
		}

		private static Func<object, object?>? CreateUntypedMemberGetter(Type type, string memberName)
		{
			FieldInfo field = type.GetField(memberName, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (field != null)
			{
				try
				{
					return FastMethodInvoker.CreateInstanceGetter(field);
				}
				catch
				{
					return field.GetValue;
				}
			}
			PropertyInfo property = type.GetProperty(memberName, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (property == null)
			{
				return null;
			}
			try
			{
				return FastMethodInvoker.CreateInstanceGetter(property);
			}
			catch
			{
				return property.GetValue;
			}
		}
	}
