namespace STS2RitsuLib.Combat.Ui.ExtraCornerAmountLabels
{
	internal static class ExtraCornerAmountLabelsRuntime
	{
		private sealed class AnchoredSlotHost
		{
			public Control? Label;

			public ExtraIconAmountLabelTextMode TextMode;
		}

		private sealed class PowerHostState
		{
			public readonly List<AnchoredSlotHost> Slots = new List<AnchoredSlotHost>();

			public Action? Handler;

			public ulong OwnerInstanceId;

			public PowerModel? SubscribedModel;
		}

		private sealed class RelicHostState
		{
			public readonly List<AnchoredSlotHost> Slots = new List<AnchoredSlotHost>();

			public Action? Handler;

			public ulong OwnerInstanceId;

			public RelicModel? SubscribedModel;
		}

		private sealed class IntentHostState
		{
			public readonly List<AnchoredSlotHost> Slots = new List<AnchoredSlotHost>();

			public Action? Handler;

			public ulong OwnerInstanceId;

			public AbstractIntent? SubscribedIntent;
		}

		private const string PowerSlotPrefix = "RitsuExtraPowerCornerSlot_";

		private const string RelicSlotPrefix = "RitsuExtraRelicCornerSlot_";

		private const string IntentSlotPrefix = "RitsuExtraIntentCornerSlot_";

		private static readonly FieldInfo? PowerAmountField = AccessTools.Field(typeof(NPower), "_amountLabel");

		private static readonly FieldInfo? RelicAmountField = AccessTools.Field(typeof(NRelicInventoryHolder), "_amountLabel");

		private static readonly FieldInfo? IntentValueField = AccessTools.Field(typeof(NIntent), "_valueLabel");

		private static readonly FieldInfo? IntentIntentField = AccessTools.Field(typeof(NIntent), "_intent");

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<ulong, PowerHostState> PowerStates = new Dictionary<ulong, PowerHostState>();

		private static readonly Dictionary<ulong, RelicHostState> RelicStates = new Dictionary<ulong, RelicHostState>();

		private static readonly Dictionary<ulong, IntentHostState> IntentStates = new Dictionary<ulong, IntentHostState>();

		private static readonly Lock CornerErrorSync = new Lock();

		private static readonly HashSet<string> CornerErrorOnceKeys = new HashSet<string>();

		internal static void SyncPower(NPower node)
		{
			PowerModel val = SafeReadModel(node);
			if (!(val is IPowerExtraIconAmountLabelsProvider) && !(val is IPowerExtraIconAmountLabelSpecsProvider))
			{
				ClearPower(node);
				return;
			}
			PowerHostState orCreatePowerState;
			MegaLabel amountRef;
			ExtraIconAmountLabelSpec[] specs;
			using (SyncRoot.EnterScope())
			{
				orCreatePowerState = GetOrCreatePowerState(((GodotObject)node).GetInstanceId());
				orCreatePowerState.OwnerInstanceId = ((GodotObject)node).GetInstanceId();
				ResubscribePower(orCreatePowerState, node, val, val);
				object? obj = PowerAmountField?.GetValue(node);
				amountRef = (MegaLabel)((obj is MegaLabel) ? obj : null);
				specs = SnapshotPowerSpecs(val);
			}
			SyncAnchoredSlotHosts((Control)(object)node, orCreatePowerState.Slots, "RitsuExtraPowerCornerSlot_", specs, ExtraCornerHostKind.Power, delegate(Control l)
			{
				ExtraCornerPowerAmountStyle.Apply(l, amountRef);
			});
		}

		internal static void ClearPower(NPower node)
		{
			using (SyncRoot.EnterScope())
			{
				if (PowerStates.Remove(((GodotObject)node).GetInstanceId(), out PowerHostState value))
				{
					UnsubscribePowerState(value);
					FreeAnchoredSlotHosts(value.Slots);
				}
			}
		}

		internal static void SyncRelic(NRelicInventoryHolder node)
		{
			RelicModel model = node.Relic.Model;
			if (!(model is IRelicExtraIconAmountLabelsProvider) && !(model is IRelicExtraIconAmountLabelSpecsProvider))
			{
				ClearRelic(node);
				return;
			}
			RelicHostState orCreateRelicState;
			MegaLabel amountRef;
			ExtraIconAmountLabelSpec[] specs;
			using (SyncRoot.EnterScope())
			{
				orCreateRelicState = GetOrCreateRelicState(((GodotObject)node).GetInstanceId());
				orCreateRelicState.OwnerInstanceId = ((GodotObject)node).GetInstanceId();
				ResubscribeRelic(orCreateRelicState, node, model, model);
