		private static void SyncAnchoredSlotHosts(Control host, List<AnchoredSlotHost> pool, string slotNamePrefix, ExtraIconAmountLabelSpec[] specs, ExtraCornerHostKind hostKind, Action<Control> applyHostStyle)
		{
			//IL_0059: Unknown result type (might be due to invalid IL or missing references)
			//IL_005e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0062: Unknown result type (might be due to invalid IL or missing references)
			//IL_0078: Unknown result type (might be due to invalid IL or missing references)
			//IL_007d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0081: Unknown result type (might be due to invalid IL or missing references)
			HashSet<ExtraIconAmountLabelCorner> hashSet = new HashSet<ExtraIconAmountLabelCorner>();
			int num = 0;
			for (int i = 0; i < specs.Length; i++)
			{
				ExtraIconAmountLabelSpec slot = specs[i];
				if (string.IsNullOrWhiteSpace(slot.Text))
				{
					continue;
				}
				if (!Enum.IsDefined(slot.Corner))
				{
					ReportSlotRejectedOnce(host, hostKind, in slot, "corner value is not defined");
					continue;
				}
				if (slot.Corner == ExtraIconAmountLabelCorner.Custom)
				{
					Rect2 customRect = slot.CustomRect;
					if (((Rect2)(ref customRect)).Size.X <= 0f)
					{
						continue;
					}
					customRect = slot.CustomRect;
					if (((Rect2)(ref customRect)).Size.Y <= 0f)
					{
						continue;
					}
				}
				if (slot.Corner != ExtraIconAmountLabelCorner.Custom && !hashSet.Add(slot.Corner))
				{
					ReportSlotRejectedOnce(host, hostKind, in slot, "requested preset corner is already occupied by another extra badge");
					continue;
				}
				while (pool.Count <= num)
				{
					pool.Add(new AnchoredSlotHost());
				}
				AnchoredSlotHost entry = pool[num];
				Control orCreateSlotLabel = GetOrCreateSlotLabel(host, entry, slotNamePrefix, num, slot.TextMode, applyHostStyle);
				ClearSlotColorOverrides(orCreateSlotLabel, slot.TextMode);
				applyHostStyle(orCreateSlotLabel);
				ApplySlotColorOverrides(orCreateSlotLabel, in slot);
				ExtraCornerHostLayout.ApplySlotAlignment(orCreateSlotLabel, hostKind, in slot);
				ExtraCornerHostLayout.ApplySlotBounds(orCreateSlotLabel, hostKind, in slot);
				SetSlotText(orCreateSlotLabel, in slot);
				((CanvasItem)orCreateSlotLabel).Visible = true;
				num++;
			}
			for (int j = num; j < pool.Count; j++)
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)pool[j].Label))
				{
					((CanvasItem)pool[j].Label).Visible = false;
				}
			}
		}

		private static Control GetOrCreateSlotLabel(Control host, AnchoredSlotHost entry, string slotNamePrefix, int slotIndex, ExtraIconAmountLabelTextMode textMode, Action<Control> applyHostStyle)
		{
			if (GodotObject.IsInstanceValid((GodotObject)(object)entry.Label) && entry.TextMode == textMode && LabelMatchesTextMode(entry.Label, textMode))
			{
				return entry.Label;
			}
			if (GodotObject.IsInstanceValid((GodotObject)(object)entry.Label))
			{
				((Node)entry.Label).QueueFree();
			}
			Control val = CreateSlotLabel($"{slotNamePrefix}{slotIndex}", textMode);
			applyHostStyle(val);
			((Node)host).AddChild((Node)(object)val, false, (InternalMode)0);
			((Node)host).MoveChild((Node)(object)val, ((Node)host).GetChildCount(false) - 1);
			entry.Label = val;
			entry.TextMode = textMode;
			return val;
		}

