		private static string AlignRichText(string text, ExtraIconAmountLabelCorner corner)
		{
			switch (corner)
			{
			case ExtraIconAmountLabelCorner.TopRight:
			case ExtraIconAmountLabelCorner.BottomRight:
				return "[right]" + text + "[/right]";
			case ExtraIconAmountLabelCorner.Custom:
				return "[center]" + text + "[/center]";
			default:
				return text;
			}
		}

		private static void ReportSlotRejectedOnce(Control host, ExtraCornerHostKind hostKind, in ExtraIconAmountLabelSpec slot, string reason)
		{
