			string value = slot.Text.Trim();
			string hostLogKey = GetHostLogKey(host, hostKind);
			string item = $"{hostKind}:{hostLogKey}:{slot.Corner}:{reason}";
			using (CornerErrorSync.EnterScope())
			{
				if (!CornerErrorOnceKeys.Add(item))
				{
					return;
				}
			}
			RitsuLibFramework.Logger.Warn($"[ExtraCornerAmountLabels] Rejected badge slot on {hostKind} host ({hostLogKey}, nodeId={instanceId}): corner={slot.Corner}, text='{value}', reason={reason}.", 1);
		}

		private static void ReportProviderFailureOnce(object provider, string operation, Exception exception)
		{
			string text = provider.GetType().FullName ?? provider.GetType().Name;
			string item = "provider:" + text + ":" + operation;
			using (CornerErrorSync.EnterScope())
			{
				if (!CornerErrorOnceKeys.Add(item))
				{
					return;
				}
			}
			RitsuLibFramework.Logger.ErrorNoTrace($"[ExtraCornerAmountLabels] {text} failed while supplying extra badge slots during {operation}. Its extra badges will be hidden for this refresh. {exception}");
		}

		private static string GetHostLogKey(Control host, ExtraCornerHostKind hostKind)
		{
			switch (hostKind)
			{
			case ExtraCornerHostKind.Power:
			{
				NPower val2 = (NPower)(object)((host is NPower) ? host : null);
				if (val2 != null)
				{
					PowerModel? obj2 = SafeReadModel(val2);
					return ((obj2 != null) ? ((object)((AbstractModel)obj2).Id).ToString() : null) ?? ((object)val2).GetType().FullName ?? StringName.op_Implicit(((Node)val2).Name);
				}
				break;
			}
			case ExtraCornerHostKind.Relic:
			{
				NRelicInventoryHolder val = (NRelicInventoryHolder)(object)((host is NRelicInventoryHolder) ? host : null);
				if (val != null)
				{
					return ((object)((AbstractModel)val.Relic.Model).Id).ToString();
				}
				break;
			}
			case ExtraCornerHostKind.Intent:
			{
				object? obj = IntentIntentField?.GetValue(host);
				return ((obj is AbstractIntent) ? obj : null)?.GetType().FullName ?? ((object)host).GetType().FullName ?? StringName.op_Implicit(((Node)host).Name);
			}
			}
			return ((object)host).GetType().FullName ?? StringName.op_Implicit(((Node)host).Name);
		}

		private static void FreeAnchoredSlotHosts(List<AnchoredSlotHost> pool)
