	/// <summary>
	///     <para xml:lang="en">Registers secondary combat resources owned by one mod.</para>
	///     <para xml:lang="zh-CN">注册由一个模组所有的次级战斗资源。</para>
	/// </summary>
	public sealed class ModSecondaryResourceRegistry
	{
		private sealed record CombatUiVisibilityPredicateRegistration(int Order, long Sequence, SecondaryResourceCombatUiVisibilityPredicate Predicate);

		private const string IdTypeStem = "SECONDARY_RESOURCE";

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, ModSecondaryResourceRegistry> Registries = new Dictionary<string, ModSecondaryResourceRegistry>(StringComparer.OrdinalIgnoreCase);

		private static readonly Dictionary<string, SecondaryResourceDefinition> Definitions = new Dictionary<string, SecondaryResourceDefinition>(StringComparer.OrdinalIgnoreCase);

		private static readonly Dictionary<string, List<CombatUiVisibilityPredicateRegistration>> CombatUiVisibilityPredicates = new Dictionary<string, List<CombatUiVisibilityPredicateRegistration>>(StringComparer.OrdinalIgnoreCase);

		private static long _nextVisibilityPredicateSequence;

		private readonly string _modId;

		/// <summary>
		///     <para xml:lang="en">Gets whether at least one secondary resource is registered.</para>
		///     <para xml:lang="zh-CN">获取是否至少注册了一个次级资源。</para>
		/// </summary>
		public static bool HasAny
		{
			get
			{
				using (SyncRoot.EnterScope())
				{
					return Definitions.Count > 0;
				}
			}
		}

		private ModSecondaryResourceRegistry(string modId)
		{
			_modId = modId;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the registry for <paramref name="modId" />. Leading and trailing whitespace is ignored.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 <paramref name="modId" /> 的注册表；忽略首尾空白。
		///     </para>
		/// </summary>
		public static ModSecondaryResourceRegistry For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			string text = modId.Trim();
			using (SyncRoot.EnterScope())
			{
				if (Registries.TryGetValue(text, out ModSecondaryResourceRegistry value))
				{
					return value;
				}
				ModSecondaryResourceRegistry modSecondaryResourceRegistry = new ModSecondaryResourceRegistry(text);
				Registries[text] = modSecondaryResourceRegistry;
				return modSecondaryResourceRegistry;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Builds a full resource ID from a mod ID and mod-local ID.</para>
		///     <para xml:lang="zh-CN">根据模组 ID 和模组内 ID 构建完整资源 ID。</para>
		/// </summary>
		public static string GetResourceId(string modId, string localId)
		{
			return ModContentRegistry.GetCompoundId(modId, "SECONDARY_RESOURCE", localId);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a secondary resource and returns its mod-bound definition. Repeating the same registration
		///         returns the definition registered first.
		///     </para>
		///     <para xml:lang="zh-CN">注册次级资源并返回绑定到模组后的定义；重复注册同一资源时返回最先注册的定义。</para>
		/// </summary>
		public SecondaryResourceDefinition Register(string localId, SecondaryResourceDefinition definition)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(localId, "localId");
			ArgumentNullException.ThrowIfNull(definition, "definition");
			SecondaryResourceDefinition secondaryResourceDefinition = definition.Bind(_modId, localId);
			using (SyncRoot.EnterScope())
			{
				if (Definitions.TryGetValue(secondaryResourceDefinition.Id, out SecondaryResourceDefinition value))
				{
					if (!StringComparer.OrdinalIgnoreCase.Equals(value.ModId, _modId))
					{
						throw new InvalidOperationException($"Secondary resource '{secondaryResourceDefinition.Id}' is already registered by mod '{value.ModId}'.");
					}
					return value;
				}
				Definitions[secondaryResourceDefinition.Id] = secondaryResourceDefinition;
			}
			RitsuLibFramework.Logger.Info($"[SecondaryResource] Registered {secondaryResourceDefinition.Id} (mod={secondaryResourceDefinition.ModId}).", 1);
			return secondaryResourceDefinition;
		}

		/// <summary>
		///     <para xml:lang="en">Attempts to get a registered definition by full resource ID.</para>
		///     <para xml:lang="zh-CN">尝试按完整资源 ID 获取已注册定义。</para>
		/// </summary>
		public static bool TryGet(string resourceId, out SecondaryResourceDefinition definition)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(resourceId, "resourceId");
			using (SyncRoot.EnterScope())
			{
				return Definitions.TryGetValue(resourceId.Trim(), out definition);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets a registered definition, or throws when the ID is unknown.</para>
		///     <para xml:lang="zh-CN">获取已注册定义；ID 未知时抛出异常。</para>
		/// </summary>
		public static SecondaryResourceDefinition Get(string resourceId)
		{
			if (!TryGet(resourceId, out SecondaryResourceDefinition definition))
			{
				throw new KeyNotFoundException("Secondary resource is not registered: " + resourceId);
			}
			return definition;
		}

		/// <summary>
		///     <para xml:lang="en">Returns a deterministically ordered snapshot of registered definitions.</para>
		///     <para xml:lang="zh-CN">返回按确定性顺序排列的已注册定义快照。</para>
		/// </summary>
		public static SecondaryResourceDefinition[] GetDefinitionsSnapshot()
		{
			using (SyncRoot.EnterScope())
			{
				return Definitions.Values.OrderBy<SecondaryResourceDefinition, string>((SecondaryResourceDefinition definition) => definition.Id, StringComparer.Ordinal).ToArray();
			}
		}

		/// <summary>
		///     <para xml:lang="en">Creates a localized <see cref="T:MegaCrit.Sts2.Core.HoverTips.HoverTip" /> for a registered resource.</para>
		///     <para xml:lang="zh-CN">为已注册资源创建本地化的 <see cref="T:MegaCrit.Sts2.Core.HoverTips.HoverTip" />。</para>
		/// </summary>
		/// <param name="resourceId">
		///     <para xml:lang="en">The full resource ID.</para>
		///     <para xml:lang="zh-CN">完整资源 ID。</para>
		/// </param>
		/// <param name="amount">
		///     <para xml:lang="en">The current amount exposed to localization variables.</para>
		///     <para xml:lang="zh-CN">提供给本地化变量的当前数量。</para>
		/// </param>
		/// <param name="maxAmount">
		///     <para xml:lang="en">The optional maximum exposed to localization variables.</para>
		///     <para xml:lang="zh-CN">提供给本地化变量的可选最大数量。</para>
		/// </param>
		public static HoverTip CreateHoverTip(string resourceId, int amount = 0, int? maxAmount = null)
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			if (TryGet(resourceId, out SecondaryResourceDefinition definition))
			{
				return SecondaryResourceHoverTipFactory.Create(definition, amount, maxAmount);
			}
			throw new KeyNotFoundException("Secondary resource is not registered: " + resourceId);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers an additional combat UI visibility predicate for one resource. Lower order values run
		///         first; predicates with the same order retain registration order.
		///     </para>
		///     <para xml:lang="zh-CN">为一种资源注册额外的战斗界面可见性谓词；顺序值较小的先运行，相同时保持注册顺序。</para>
		/// </summary>
		public void RegisterCombatUiAlwaysVisibleWhen(string localId, SecondaryResourceCombatUiVisibilityPredicate predicate, int order = 0)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(localId, "localId");
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			string resourceId = GetResourceId(_modId, localId);
			using (SyncRoot.EnterScope())
			{
				if (!CombatUiVisibilityPredicates.TryGetValue(resourceId, out List<CombatUiVisibilityPredicateRegistration> value))
				{
					value = new List<CombatUiVisibilityPredicateRegistration>();
					CombatUiVisibilityPredicates[resourceId] = value;
				}
				value.Add(new CombatUiVisibilityPredicateRegistration(order, _nextVisibilityPredicateSequence++, predicate));
				value.Sort(delegate(CombatUiVisibilityPredicateRegistration left, CombatUiVisibilityPredicateRegistration right)
				{
					int num = left.Order.CompareTo(right.Order);
					return (num == 0) ? left.Sequence.CompareTo(right.Sequence) : num;
				});
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Keeps a resource visible in combat UI for <typeparamref name="TCharacter" />, even at its default
		///         amount.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         对 <typeparamref name="TCharacter" /> 始终在战斗界面显示资源，即使资源处于默认数量。
		///     </para>
		/// </summary>
		public void AlwaysShowInCombatUiForCharacter<TCharacter>(string localId, int order = -1000) where TCharacter : CharacterModel
		{
			AlwaysShowInCombatUiForCharacter(localId, typeof(TCharacter), order);
		}

		/// <summary>
		///     <para xml:lang="en">Keeps a resource visible for characters assignable to the specified type.</para>
		///     <para xml:lang="zh-CN">对可赋值给指定类型的角色始终显示资源。</para>
		/// </summary>
		public void AlwaysShowInCombatUiForCharacter(string localId, Type characterType, int order = -1000)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(localId, "localId");
			ArgumentNullException.ThrowIfNull(characterType, "characterType");
			if (characterType.IsInterface || characterType.ContainsGenericParameters || !typeof(CharacterModel).IsAssignableFrom(characterType))
			{
				throw new ArgumentException("Type '" + characterType.FullName + "' must be a closed character model subtype.", "characterType");
			}
			RegisterCombatUiAlwaysVisibleWhen(localId, (SecondaryResourceCombatVisibilityContext context) => characterType.IsInstanceOfType(context.Player.Character), order);
		}

		/// <summary>
		///     <para xml:lang="en">Keeps a resource visible in combat UI for every character.</para>
		///     <para xml:lang="zh-CN">对所有角色始终在战斗界面显示资源。</para>
		/// </summary>
		public void AlwaysShowInCombatUi(string localId, int order = -1000)
		{
			RegisterCombatUiAlwaysVisibleWhen(localId, (SecondaryResourceCombatVisibilityContext _) => true, order);
		}

		internal static SecondaryResourceCombatUiVisibilityPredicate[] GetCombatUiVisibilityPredicates(string resourceId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(resourceId, "resourceId");
			using (SyncRoot.EnterScope())
			{
				List<CombatUiVisibilityPredicateRegistration> value;
				return CombatUiVisibilityPredicates.TryGetValue(resourceId.Trim(), out value) ? value.Select((CombatUiVisibilityPredicateRegistration registration) => registration.Predicate).ToArray() : Array.Empty<SecondaryResourceCombatUiVisibilityPredicate>();
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a combat UI child and its update route on <see cref="T:MegaCrit.Sts2.Core.Nodes.Combat.NCombatUi" /> through node
		///         attachments.
		///     </para>
		///     <para xml:lang="zh-CN">通过节点挂载机制，在 <see cref="T:MegaCrit.Sts2.Core.Nodes.Combat.NCombatUi" /> 上注册战斗界面子节点及其更新路径。</para>
		/// </summary>
		public NodeAttachmentDefinition RegisterCombatUi<TNode>(string localId, Func<NCombatUi, TNode> factory, Action<SecondaryResourceCombatUiContext<NCombatUi, TNode>> update, NodeAttachmentOptions? options = null) where TNode : Node
		{
			return this.RegisterCombatUi<NCombatUi, TNode>(localId, factory, update, options);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a combat UI child with update and amount-change routes on <see cref="T:MegaCrit.Sts2.Core.Nodes.Combat.NCombatUi" />.
		///     </para>
		///     <para xml:lang="zh-CN">在 <see cref="T:MegaCrit.Sts2.Core.Nodes.Combat.NCombatUi" /> 上注册带更新及数量变化处理路径的战斗界面子节点。</para>
		/// </summary>
		public NodeAttachmentDefinition RegisterCombatUi<TNode>(string localId, Func<NCombatUi, TNode> factory, Action<SecondaryResourceCombatUiContext<NCombatUi, TNode>> update, SecondaryResourceCombatUiChangedHandler<NCombatUi, TNode> changed, NodeAttachmentOptions? options = null) where TNode : Node
		{
			return this.RegisterCombatUi<NCombatUi, TNode>(localId, factory, update, changed, options);
		}

		/// <summary>
		///     <para xml:lang="en">Registers a combat UI child and its update route through node attachments.</para>
		///     <para xml:lang="zh-CN">通过节点挂载机制注册战斗界面子节点及其更新路径。</para>
		/// </summary>
		public NodeAttachmentDefinition RegisterCombatUi<TParent, TNode>(string localId, Func<TParent, TNode> factory, Action<SecondaryResourceCombatUiContext<TParent, TNode>> update, NodeAttachmentOptions? options = null) where TParent : Node where TNode : Node
		{
			ArgumentNullException.ThrowIfNull(factory, "factory");
			ArgumentNullException.ThrowIfNull(update, "update");
			return ModNodeAttachmentRegistry.For(_modId).RegisterReadyChild(localId, factory, delegate(TParent parent, TNode node)
			{
				SecondaryResourceUiRuntime.RegisterCombatUpdater(parent, node, update);
				SecondaryResourceUiRuntime.HideCombatUi((Node)(object)parent);
			}, options);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a combat UI child with update and amount-change routes through node attachments.
		///     </para>
		///     <para xml:lang="zh-CN">通过节点挂载机制注册带更新及数量变化处理路径的战斗界面子节点。</para>
		/// </summary>
		public NodeAttachmentDefinition RegisterCombatUi<TParent, TNode>(string localId, Func<TParent, TNode> factory, Action<SecondaryResourceCombatUiContext<TParent, TNode>> update, SecondaryResourceCombatUiChangedHandler<TParent, TNode> changed, NodeAttachmentOptions? options = null) where TParent : Node where TNode : Node
		{
			ArgumentNullException.ThrowIfNull(factory, "factory");
			ArgumentNullException.ThrowIfNull(update, "update");
			ArgumentNullException.ThrowIfNull(changed, "changed");
			return ModNodeAttachmentRegistry.For(_modId).RegisterReadyChild(localId, factory, delegate(TParent parent, TNode node)
			{
				SecondaryResourceUiRuntime.RegisterCombatUpdater(parent, node, update, changed);
				SecondaryResourceUiRuntime.HideCombatUi((Node)(object)parent);
			}, options);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a card UI child and its update route on <see cref="T:MegaCrit.Sts2.Core.Nodes.Cards.NCard" /> through node attachments.
		///     </para>
		///     <para xml:lang="zh-CN">通过节点挂载机制，在 <see cref="T:MegaCrit.Sts2.Core.Nodes.Cards.NCard" /> 上注册卡牌界面子节点及其更新路径。</para>
		/// </summary>
		public NodeAttachmentDefinition RegisterCardUi<TNode>(string localId, Func<NCard, TNode> factory, Action<SecondaryResourceCardUiContext<NCard, TNode>> update, NodeAttachmentOptions? options = null) where TNode : Node
		{
			return this.RegisterCardUi<NCard, TNode>(localId, factory, update, WithDefaultCardUiOptions(options));
		}

		/// <summary>
		///     <para xml:lang="en">Registers a card UI child and its update route through node attachments.</para>
		///     <para xml:lang="zh-CN">通过节点挂载机制注册卡牌界面子节点及其更新路径。</para>
		/// </summary>
		public NodeAttachmentDefinition RegisterCardUi<TParent, TNode>(string localId, Func<TParent, TNode> factory, Action<SecondaryResourceCardUiContext<TParent, TNode>> update, NodeAttachmentOptions? options = null) where TParent : Node where TNode : Node
		{
			ArgumentNullException.ThrowIfNull(factory, "factory");
			ArgumentNullException.ThrowIfNull(update, "update");
			return ModNodeAttachmentRegistry.For(_modId).RegisterReadyChild(localId, factory, delegate(TParent parent, TNode node)
			{
				SecondaryResourceUiRuntime.RegisterCardUpdater(parent, node, update);
			}, options);
		}

		/// <summary>
		///     <para xml:lang="en">Registers a secondary-resource UI child for each multiplayer player-state display.</para>
		///     <para xml:lang="zh-CN">为每个多人玩家状态栏注册次级资源界面子节点。</para>
		/// </summary>
		public NodeAttachmentDefinition RegisterMultiplayerPlayerStateUi<TNode>(string localId, Func<NMultiplayerPlayerState, TNode> factory, Action<SecondaryResourceMultiplayerPlayerStateUiContext<TNode>> update, NodeAttachmentOptions? options = null) where TNode : Node
		{
			ArgumentNullException.ThrowIfNull(factory, "factory");
			ArgumentNullException.ThrowIfNull(update, "update");
			return ModNodeAttachmentRegistry.For(_modId).RegisterReadyChild<NMultiplayerPlayerState, TNode>(localId, factory, (Action<NMultiplayerPlayerState, TNode>?)delegate(NMultiplayerPlayerState parent, TNode node)
			{
				SecondaryResourceUiRuntime.RegisterMultiplayerPlayerStateUpdater(parent, node, update);
				SecondaryResourceMultiplayerPlayerStateUiTicker.Ensure(parent);
				SecondaryResourceUiRuntime.HideMultiplayerPlayerStateUi(parent);
			}, WithDefaultMultiplayerPlayerStateOptions(options));
		}

		private static NodeAttachmentOptions WithDefaultCardUiOptions(NodeAttachmentOptions? options)
		{
			NodeAttachmentOptions nodeAttachmentOptions = options ?? NodeAttachmentOptions.Default;
			return new NodeAttachmentOptions
			{
				Name = nodeAttachmentOptions.Name,
				Order = nodeAttachmentOptions.Order,
				UniqueNameInOwner = nodeAttachmentOptions.UniqueNameInOwner,
				IncludeDerivedParentTypes = nodeAttachmentOptions.IncludeDerivedParentTypes,
				DuplicatePolicy = nodeAttachmentOptions.DuplicatePolicy,
				AddMode = nodeAttachmentOptions.AddMode,
				AttachParentSelector = (nodeAttachmentOptions.AttachParentSelector ?? new Func<Node, Node>(ResolveCardUiAttachParent)),
				SetupTiming = nodeAttachmentOptions.SetupTiming,
				ChildIndex = nodeAttachmentOptions.ChildIndex,
				InsertBeforeName = nodeAttachmentOptions.InsertBeforeName,
				InsertAfterName = nodeAttachmentOptions.InsertAfterName,
				QueueFreeReplacedNode = nodeAttachmentOptions.QueueFreeReplacedNode
			};
		}

		private static NodeAttachmentOptions WithDefaultMultiplayerPlayerStateOptions(NodeAttachmentOptions? options)
		{
			NodeAttachmentOptions nodeAttachmentOptions = options ?? NodeAttachmentOptions.Default;
			return new NodeAttachmentOptions
			{
				Name = nodeAttachmentOptions.Name,
				Order = nodeAttachmentOptions.Order,
				UniqueNameInOwner = nodeAttachmentOptions.UniqueNameInOwner,
				IncludeDerivedParentTypes = nodeAttachmentOptions.IncludeDerivedParentTypes,
				DuplicatePolicy = nodeAttachmentOptions.DuplicatePolicy,
				AddMode = nodeAttachmentOptions.AddMode,
				AttachParentSelector = (nodeAttachmentOptions.AttachParentSelector ?? new Func<Node, Node>(ResolveMultiplayerPlayerStateAttachParent)),
				SetupTiming = NodeAttachmentSetupTiming.AfterAdd,
				ChildIndex = nodeAttachmentOptions.ChildIndex,
				InsertBeforeName = nodeAttachmentOptions.InsertBeforeName,
				InsertAfterName = nodeAttachmentOptions.InsertAfterName,
				QueueFreeReplacedNode = nodeAttachmentOptions.QueueFreeReplacedNode
			};
		}

		private static Node ResolveCardUiAttachParent(Node parent)
		{
			NCard val = (NCard)(object)((parent is NCard) ? parent : null);
			if (val != null)
			{
				Control body = val.Body;
				if (body != null)
				{
					return (Node)(object)body;
				}
			}
			return parent;
		}

		private static Node ResolveMultiplayerPlayerStateAttachParent(Node parent)
		{
			NMultiplayerPlayerState val = (NMultiplayerPlayerState)(object)((parent is NMultiplayerPlayerState) ? parent : null);
			if (val != null)
			{
				HBoxContainer nodeOrNull = ((Node)val).GetNodeOrNull<HBoxContainer>(NodePath.op_Implicit("TopInfoContainer"));
				if (nodeOrNull != null)
				{
					return (Node)(object)nodeOrNull;
				}
			}
			return parent;
		}
	}
