		/// </summary>
		public Func<SecondaryResourcePaymentLine, string>? FormatCost { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the shared default style.</para>
		///     <para xml:lang="zh-CN">获取共享的默认样式。</para>
		/// </summary>
		public static SecondaryResourceCardCostUiStyle Default { get; } = new SecondaryResourceCardCostUiStyle();

		internal string Format(SecondaryResourcePaymentLine line)
		{
			object obj = FormatCost?.Invoke(line);
			if (obj == null)
			{
				if (!line.CostsX)
				{
					return line.Cost.ToString();
				}
				obj = "X";
			}
			return (string)obj;
		}
	}
