	/// <summary>
	///     <para xml:lang="en">
	///         Coordinates secondary-resource card-cost layout with the game's <see cref="T:MegaCrit.Sts2.Core.Nodes.Cards.NCard" /> layout.
	///     </para>
	///     <para xml:lang="zh-CN">协调次级资源卡牌费用与游戏 <see cref="T:MegaCrit.Sts2.Core.Nodes.Cards.NCard" /> 的布局。</para>
	/// </summary>
	public static class SecondaryResourceCardUiLayout
	{
		private const float VanillaStarCostEnchantmentOffset = 45f;

		private static readonly AttachedState<NCard, bool> ReservedVanillaStarCostSlot = new AttachedState<NCard, bool>();

		/// <summary>
		///     <para xml:lang="en">Marks the current card UI refresh as occupying the game's Stars-cost slot.</para>
		///     <para xml:lang="zh-CN">标记当前卡牌界面刷新占用了游戏的辉星费用槽。</para>
		/// </summary>
		/// <param name="card">
		///     <para xml:lang="en">The card node currently being refreshed.</para>
		///     <para xml:lang="zh-CN">当前正在刷新的卡牌节点。</para>
		/// </param>
		public static void ReserveVanillaStarCostSlot(NCard card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			ReservedVanillaStarCostSlot.Set(card, value: true);
		}

		internal static void BeginUpdate(NCard card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			ReservedVanillaStarCostSlot.Remove(card);
		}

		internal static void ApplyReservedLayout(NCard card)
		{
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			//IL_005a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0064: Unknown result type (might be due to invalid IL or missing references)
			//IL_0069: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(card, "card");
			if (ReservedVanillaStarCostSlot.TryRemove(card, out var value) && value && card.Model != null && ((CanvasItem)card.EnchantmentTab).Visible && !card.Model.HasStarCostX && card.Model.CurrentStarCost < 0)
			{
				Control enchantmentTab = card.EnchantmentTab;
				enchantmentTab.Position += Vector2.Down * 45f;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides commands that mutate registered secondary-resource amounts.</para>
	///     <para xml:lang="zh-CN">提供修改已注册次级资源数量的命令。</para>
	/// </summary>
	public static class SecondaryResourceCmd
	{
		/// <summary>
		///     <para xml:lang="en">Gets the current amount without creating state when no resources are registered.</para>
		///     <para xml:lang="zh-CN">获取当前数量；未注册资源时不会创建状态。</para>
		/// </summary>
		public static int Get(Player player, string resourceId)
		{
			return SecondaryResourceStateStore.GetAmount(player, resourceId);
		}

		/// <summary>
		///     <para xml:lang="en">Gets the current maximum, or <see langword="null" /> for an uncapped resource.</para>
		///     <para xml:lang="zh-CN">获取当前最大数量；资源没有上限时返回 <see langword="null" />。</para>
		/// </summary>
		public static int? GetMax(Player player, string resourceId)
		{
			return SecondaryResourceStateStore.GetMaxAmount(player, resourceId);
		}

		/// <summary>
		///     <para xml:lang="en">Adds a positive amount after applying gain checks and modifiers.</para>
		///     <para xml:lang="zh-CN">通过增加检查并应用修正后，增加一个正数数量。</para>
		/// </summary>
		public static async Task<int> Gain(Player player, string resourceId, int amount, AbstractModel? source = null)
		{
			if (amount <= 0 || !TryResolve(player, resourceId, out ICombatState combatState, out SecondaryResourceDefinition definition))
			{
				return Get(player, resourceId);
			}
			return await GainCore(combatState, player, definition, amount, SecondaryResourceChangeReason.Gain, source);
		}

		private static async Task<int> GainCore(ICombatState combatState, Player player, SecondaryResourceDefinition definition, int amount, SecondaryResourceChangeReason reason, AbstractModel? source)
		{
			SecondaryResourceContext context = new SecondaryResourceContext(combatState, player, definition, source);
			if (!SecondaryResourceHook.ShouldGain(context, amount))
			{
				return Get(player, definition.Id);
			}
			int num = SecondaryResourceAmountMath.FloorAndClamp(SecondaryResourceHook.ModifyGain(context, amount), 0, int.MaxValue);
			if (num <= 0)
			{
				return Get(player, definition.Id);
			}
			return await SetCore(combatState, player, definition, SecondaryResourceAmountMath.AddSaturating(Get(player, definition.Id), num), reason, source);
		}

		/// <summary>
		///     <para xml:lang="en">Subtracts a positive amount from a resource.</para>
		///     <para xml:lang="zh-CN">从资源中减去一个正数数量。</para>
		/// </summary>
		public static async Task<int> Lose(Player player, string resourceId, int amount, AbstractModel? source = null)
		{
			if (amount <= 0 || !TryResolve(player, resourceId, out ICombatState combatState, out SecondaryResourceDefinition definition))
			{
				return Get(player, resourceId);
			}
			return await SetCore(combatState, player, definition, SecondaryResourceAmountMath.SubtractSaturating(Get(player, definition.Id), amount), SecondaryResourceChangeReason.Lose, source);
		}

		/// <summary>
		///     <para xml:lang="en">Sets the current amount after applying the resource bounds.</para>
		///     <para xml:lang="zh-CN">应用资源上下限后设置当前数量。</para>
		/// </summary>
		public static async Task<int> Set(Player player, string resourceId, int amount, AbstractModel? source = null)
		{
			if (!TryResolve(player, resourceId, out ICombatState combatState, out SecondaryResourceDefinition definition))
			{
				return 0;
			}
			return await SetCore(combatState, player, definition, amount, SecondaryResourceChangeReason.Set, source);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Reduces the current amount to the current hook-adjusted maximum when it exceeds that maximum.
		///     </para>
		///     <para xml:lang="zh-CN">当前数量超过经钩子修正后的最大值时，将其降低到该最大值。</para>
		/// </summary>
		/// <param name="player">
		///     <para xml:lang="en">The player who owns the resource.</para>
		///     <para xml:lang="zh-CN">拥有该资源的玩家。</para>
		/// </param>
		/// <param name="resourceId">
		///     <para xml:lang="en">The full registered resource ID.</para>
		///     <para xml:lang="zh-CN">已注册资源的完整 ID。</para>
		/// </param>
		/// <param name="source">
		///     <para xml:lang="en">The optional model responsible for the maximum change.</para>
		///     <para xml:lang="zh-CN">引起最大值变化的可选模型。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         The resulting amount, or zero when the resource is unknown or the player is not in combat.
		///     </para>
		///     <para xml:lang="zh-CN">操作后的数量；资源未知或玩家不在战斗中时为零。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="player" /> is <see langword="null" />.</para>
		///     <para xml:lang="zh-CN"><paramref name="player" /> 为 <see langword="null" />。</para>
		/// </exception>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en"><paramref name="resourceId" /> is empty or whitespace.</para>
		///     <para xml:lang="zh-CN"><paramref name="resourceId" /> 为空或仅包含空白字符。</para>
		/// </exception>
		public static async Task<int> ClampToMax(Player player, string resourceId, AbstractModel? source = null)
		{
			if (!TryResolve(player, resourceId, out ICombatState combatState, out SecondaryResourceDefinition definition))
			{
				return 0;
			}
			int num = Get(player, definition.Id);
			int? max = GetMax(player, definition.Id);
			if (max.HasValue)
			{
				int valueOrDefault = max.GetValueOrDefault();
				if (num > valueOrDefault)
				{
					return await SetCore(combatState, player, definition, valueOrDefault, SecondaryResourceChangeReason.ClampToMax, source);
				}
			}
			return num;
		}

		/// <summary>
		///     <para xml:lang="en">Pays a positive amount after applying spend checks.</para>
		///     <para xml:lang="zh-CN">通过支付检查后支付一个正数数量。</para>
		/// </summary>
		public static async Task<bool> Spend(Player player, string resourceId, int amount, CardModel? card = null, AbstractModel? source = null)
		{
			if (amount <= 0)
			{
				return true;
			}
			if (!TryResolve(player, resourceId, out ICombatState combatState, out SecondaryResourceDefinition definition))
			{
				return false;
			}
			if (Get(player, definition.Id) < amount)
			{
				return false;
			}
			if (!SecondaryResourceHook.ShouldSpend(new SecondaryResourceSpendContext(combatState, player, definition, card, amount, source)))
			{
				return false;
			}
			return await SpendCore(player, definition, combatState, amount, card, source);
		}

		internal static async Task<bool> SpendResolvedCardPayment(Player player, string resourceId, int amount, CardModel card, AbstractModel? source = null)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			if (amount <= 0)
			{
				return true;
			}
			if (!TryResolve(player, resourceId, out ICombatState combatState, out SecondaryResourceDefinition definition))
			{
				return false;
			}
			return await SpendCore(player, definition, combatState, amount, card, source);
		}

		private static async Task<bool> SpendCore(Player player, SecondaryResourceDefinition definition, ICombatState combatState, int amount, CardModel? card, AbstractModel? source)
		{
			if (Get(player, definition.Id) < amount)
			{
				return false;
			}
			SecondaryResourceSpendContext spendContext = new SecondaryResourceSpendContext(combatState, player, definition, card, amount, source);
			int oldAmount = Get(player, definition.Id);
			if (oldAmount == await SetCore(combatState, player, definition, oldAmount - amount, SecondaryResourceChangeReason.Spend, source))
			{
				return false;
			}
			SecondaryResourceHistory.Spent(combatState, spendContext);
			await SecondaryResourceHook.AfterSpent(spendContext);
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Resets a resource to its default amount or current maximum.</para>
		///     <para xml:lang="zh-CN">将资源重置为默认数量或当前最大数量。</para>
		/// </summary>
		public static async Task<int> Reset(Player player, string resourceId, bool toMax = false, AbstractModel? source = null)
		{
			if (!TryResolve(player, resourceId, out ICombatState combatState, out SecondaryResourceDefinition definition))
			{
				return 0;
			}
			return await ResetCore(combatState, player, definition, toMax, SecondaryResourceChangeReason.Reset, source);
		}

		private static async Task<int> ResetCore(ICombatState combatState, Player player, SecondaryResourceDefinition definition, bool toMax, SecondaryResourceChangeReason reason, AbstractModel? source)
		{
			if (!SecondaryResourceHook.ShouldReset(new SecondaryResourceContext(combatState, player, definition, source)))
			{
				return Get(player, definition.Id);
			}
			int num;
			if (toMax)
			{
				int? max = GetMax(player, definition.Id);
				if (max.HasValue)
				{
					int valueOrDefault = max.GetValueOrDefault();
					num = valueOrDefault;
					goto IL_008e;
				}
			}
			num = definition.DefaultAmount;
			goto IL_008e;
			IL_008e:
			int amount = num;
			int oldAmount = Get(player, definition.Id);
			int num2 = await SetCore(combatState, player, definition, amount, reason, source, afterReset: true);
			if (oldAmount != num2)
			{
				SecondaryResourceHistory.Reset(combatState, new SecondaryResourceChangeContext(combatState, player, definition, oldAmount, num2, SecondaryResourceAmountMath.SubtractSaturating(num2, oldAmount), reason, source));
			}
			return num2;
		}

		/// <summary>
		///     <para xml:lang="en">Applies each registered resource's built-in turn-start policy.</para>
		///     <para xml:lang="zh-CN">应用各已注册资源的内置回合开始策略。</para>
		/// </summary>
		public static async Task ApplyTurnStartPolicies(Player player, AbstractModel? source = null)
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			if (ModSecondaryResourceRegistry.HasAny)
			{
				SecondaryResourceDefinition[] definitionsSnapshot = ModSecondaryResourceRegistry.GetDefinitionsSnapshot();
				foreach (SecondaryResourceDefinition definition in definitionsSnapshot)
				{
					await ApplyTurnStartPolicy(player, definition, source);
				}
			}
		}

		private static async Task ApplyTurnStartPolicy(Player player, SecondaryResourceDefinition definition, AbstractModel? source)
		{
			SecondaryResourceDefinition definition2;
			switch (definition.TurnStartPolicy)
			{
			case SecondaryResourceTurnStartPolicy.None:
				break;
			case SecondaryResourceTurnStartPolicy.ResetToMax:
			{
				if (TryResolve(player, definition.Id, out ICombatState combatState2, out definition2))
				{
					await ResetCore(combatState2, player, definition, toMax: true, SecondaryResourceChangeReason.TurnStart, source);
				}
				break;
			}
			case SecondaryResourceTurnStartPolicy.AddMaxToCurrent:
			{
				int? max = GetMax(player, definition.Id);
				if (max.HasValue)
				{
					int valueOrDefault = max.GetValueOrDefault();
					if (valueOrDefault > 0 && TryResolve(player, definition.Id, out ICombatState combatState3, out definition2))
					{
						await GainCore(combatState3, player, definition, valueOrDefault, SecondaryResourceChangeReason.TurnStart, source);
					}
				}
				break;
			}
			case SecondaryResourceTurnStartPolicy.Clear:
			{
				if (TryResolve(player, definition.Id, out ICombatState combatState, out definition2))
				{
					await SetCore(combatState, player, definition, definition.MinAmount, SecondaryResourceChangeReason.TurnStart, source);
				}
				break;
			}
			default:
				throw new ArgumentOutOfRangeException("TurnStartPolicy");
			}
		}

		private static async Task<int> SetCore(ICombatState combatState, Player player, SecondaryResourceDefinition definition, int amount, SecondaryResourceChangeReason reason, AbstractModel? source, bool afterReset = false)
		{
			SecondaryResourceState secondaryResourceState = SecondaryResourceStateStore.Get(player);
			int num = secondaryResourceState.Get(definition.Id);
			int newAmount = secondaryResourceState.Set(player, definition, amount, reason, source);
			if (num == newAmount)
			{
				return newAmount;
			}
			SecondaryResourceChangeContext context = new SecondaryResourceChangeContext(combatState, player, definition, num, newAmount, SecondaryResourceAmountMath.SubtractSaturating(newAmount, num), reason, source);
			SecondaryResourceHistory.Changed(combatState, context);
			SecondaryResourceUiRuntime.UpdateCurrentCombatUi(player);
			SecondaryResourceUiRuntime.NotifyCurrentCombatUiChanged(context);
			await SecondaryResourceHook.AfterChanged(context);
			if (afterReset)
			{
				await SecondaryResourceHook.AfterReset(context);
			}
			return newAmount;
		}

		private static bool TryResolve(Player player, string resourceId, out ICombatState combatState, out SecondaryResourceDefinition definition)
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			ArgumentException.ThrowIfNullOrWhiteSpace(resourceId, "resourceId");
			combatState = null;
			definition = null;
			if (!ModSecondaryResourceRegistry.HasAny || !ModSecondaryResourceRegistry.TryGet(resourceId, out definition))
			{
				return false;
			}
			Creature creature = player.Creature;
			combatState = ((creature != null) ? creature.CombatState : null) ?? null;
			return combatState != null;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides a developer-console command for inspecting and changing secondary resources.</para>
	///     <para xml:lang="zh-CN">提供用于查看和修改次级资源的开发者控制台命令。</para>
	/// </summary>
	public sealed class SecondaryResourceConsoleCmd : AbstractConsoleCmd
	{
		private static readonly string[] Actions = new string[7] { "get", "gain", "lose", "set", "reset", "resetmax", "list" };

		/// <inheritdoc />
		public override string CmdName => "sresource";

		/// <inheritdoc />
		public override string Args => "get <resourceId> [playerIndex] | gain|lose|set <resourceId> <amount:int> [playerIndex] | reset|resetmax <resourceId> [playerIndex] | list";

		/// <inheritdoc />
		public override string Description => "Inspect or mutate RitsuLib secondary resources.";

		/// <inheritdoc />
		public override bool IsNetworked => true;

		/// <inheritdoc />
		public override CompletionResult GetArgumentCompletions(Player? player, string[] args)
		{
			if (args.Length <= 1)
			{
				string text = ((args.Length == 0) ? string.Empty : args[0]);
				return ((AbstractConsoleCmd)this).CompleteArgument((IEnumerable<string>)Actions, Array.Empty<string>(), text, (CompletionType)1, (Func<string, string, bool>)null);
			}
			string text2 = args[0];
			if (!IsKnownAction(text2) || text2.Equals("list", StringComparison.OrdinalIgnoreCase))
			{
				return ((AbstractConsoleCmd)this).GetArgumentCompletions(player, args);
			}
			string[] array = args.Take(args.Length - 1).ToArray();
			string text3 = args[^1];
			if (args.Length == 2)
			{
				CompletionResult result = ((AbstractConsoleCmd)this).CompleteArgument((IEnumerable<string>)DevConsoleSecondaryResourceAutocompleteCatalog.GetResourceIds(), array, text3, (CompletionType)2, DevConsoleAutocompleteMatchExtensions.WithSecondaryResourceLocalizedTitleMatch());
				DevConsoleAutocompleteMatchExtensions.ApplySecondaryResourceDisplayLabels(ref result);
				return result;
			}
			if ((IsReadAction(text2) && args.Length == 3) || (IsMutationWithAmountAction(text2) && args.Length == 4))
			{
				return CompletePlayerIndex(player, array, text3);
			}
			return ((AbstractConsoleCmd)this).GetArgumentCompletions(player, args);
		}

		/// <inheritdoc />
		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			//IL_000a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			//IL_0057: Unknown result type (might be due to invalid IL or missing references)
			//IL_007b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0092: Unknown result type (might be due to invalid IL or missing references)
			//IL_00bd: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e8: Unknown result type (might be due to invalid IL or missing references)
			//IL_0100: Unknown result type (might be due to invalid IL or missing references)
			//IL_014b: Unknown result type (might be due to invalid IL or missing references)
			//IL_011f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0195: Unknown result type (might be due to invalid IL or missing references)
			//IL_0177: Unknown result type (might be due to invalid IL or missing references)
			if (args.Length == 0)
			{
				return new CmdResult(false, UsageText());
			}
			string text = args[0];
			if (text.Equals("list", StringComparison.OrdinalIgnoreCase))
			{
				return ListResources();
			}
			if (!IsKnownAction(text) || !ValidateArity(text, args.Length))
			{
				return new CmdResult(false, UsageText());
			}
			if (!TryResolveResource(args[1], out SecondaryResourceDefinition definition, out string error))
			{
				return new CmdResult(false, error);
			}
			int targetArgIndex = (IsMutationWithAmountAction(text) ? 3 : 2);
			if (!TryResolveTargetPlayer(issuingPlayer, args, targetArgIndex, out Player target, out string error2))
			{
				return new CmdResult(false, error2);
			}
			if (text.Equals("get", StringComparison.OrdinalIgnoreCase))
			{
				return GetResource(target, definition);
			}
			if (text.Equals("reset", StringComparison.OrdinalIgnoreCase))
			{
				return MutateResource(target, definition, SecondaryResourceCmd.Reset(target, definition.Id), "Reset");
			}
			if (text.Equals("resetmax", StringComparison.OrdinalIgnoreCase))
			{
				return MutateResource(target, definition, SecondaryResourceCmd.Reset(target, definition.Id, toMax: true), "Reset");
			}
			if (!int.TryParse(args[2], out var result))
			{
				return new CmdResult(false, "Amount must be an int.");
			}
			if (result < 0 && !text.Equals("set", StringComparison.OrdinalIgnoreCase))
			{
				return new CmdResult(false, "Amount cannot be negative.");
			}
			if (text.Equals("gain", StringComparison.OrdinalIgnoreCase))
			{
				return MutateResource(target, definition, SecondaryResourceCmd.Gain(target, definition.Id, result), "Gained");
			}
			if (text.Equals("lose", StringComparison.OrdinalIgnoreCase))
			{
				return MutateResource(target, definition, SecondaryResourceCmd.Lose(target, definition.Id, result), "Lost");
			}
			return MutateResource(target, definition, SecondaryResourceCmd.Set(target, definition.Id, result), "Set");
		}

		private CompletionResult CompletePlayerIndex(Player? player, string[] completedArgs, string partialArg)
		{
			string[] array = GetCombatPlayers(player).Select((Player _, int index) => index.ToString()).ToArray();
			return ((AbstractConsoleCmd)this).CompleteArgument((IEnumerable<string>)array, completedArgs, partialArg, (CompletionType)2, (Func<string, string, bool>)null);
		}

		private static CmdResult ListResources()
		{
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			//IL_0048: Unknown result type (might be due to invalid IL or missing references)
			SecondaryResourceDefinition[] definitionsSnapshot = ModSecondaryResourceRegistry.GetDefinitionsSnapshot();
			if (definitionsSnapshot.Length == 0)
			{
				return new CmdResult(true, "No secondary resources are registered.");
			}
			IEnumerable<string> values = definitionsSnapshot.Select(delegate(SecondaryResourceDefinition definition)
			{
				string text = DevConsoleSecondaryResourceAutocompleteCatalog.TryGetLocalizedTitle(definition);
				return (!string.IsNullOrWhiteSpace(text)) ? (definition.Id + " (" + text + ")") : definition.Id;
			});
			return new CmdResult(true, string.Join("\n", values));
		}

		private static CmdResult GetResource(Player target, SecondaryResourceDefinition definition)
		{
			//IL_00b5: Unknown result type (might be due to invalid IL or missing references)
			int value = SecondaryResourceCmd.Get(target, definition.Id);
			int? max = SecondaryResourceCmd.GetMax(target, definition.Id);
			string value2 = (max.HasValue ? $"/{max.Value}" : string.Empty);
			return new CmdResult(true, $"{definition.Id} for player {GetPlayerIndex(target)} = {value}{value2}.");
		}

		private static CmdResult MutateResource(Player target, SecondaryResourceDefinition definition, Task<int> task, string verb)
		{
			//IL_0059: Unknown result type (might be due to invalid IL or missing references)
			return new CmdResult((Task)task, true, $"{verb} {definition.Id} for player {GetPlayerIndex(target)}.");
		}

		private static bool TryResolveResource(string input, out SecondaryResourceDefinition definition, out string error)
		{
			if (DevConsoleSecondaryResourceAutocompleteCatalog.TryResolveResource(input, out definition))
			{
				error = string.Empty;
				return true;
			}
			error = "Secondary resource '" + DevConsoleAutocompleteDisplay.StripLocalizedSuffix(input) + "' is not registered.";
			return false;
		}

		private static bool TryResolveTargetPlayer(Player? issuingPlayer, string[] args, int targetArgIndex, out Player target, out string error)
		{
			target = null;
			if (((issuingPlayer != null) ? issuingPlayer.PlayerCombatState : null) == null)
			{
				error = "This command only works in combat.";
				return false;
			}
			if (args.Length <= targetArgIndex)
			{
				target = issuingPlayer;
				error = string.Empty;
				return true;
			}
			if (!int.TryParse(args[targetArgIndex], out var result))
			{
				error = "Target player index must be an int, got '" + args[targetArgIndex] + "'.";
				return false;
			}
			IReadOnlyList<Player> combatPlayers = GetCombatPlayers(issuingPlayer);
			if (result < 0 || result >= combatPlayers.Count)
			{
				error = $"Invalid player index {result}. Valid range: 0-{combatPlayers.Count - 1}.";
				return false;
			}
			target = combatPlayers[result];
			error = string.Empty;
			return true;
		}

		private static IReadOnlyList<Player> GetCombatPlayers(Player? player)
		{
			object obj;
			if (player == null)
			{
				obj = null;
			}
			else
			{
				Creature creature = player.Creature;
				if (creature == null)
				{
					obj = null;
				}
				else
				{
					ICombatState combatState = creature.CombatState;
					obj = ((combatState != null) ? combatState.Players : null);
				}
			}
			if (obj == null)
			{
				CombatState obj2 = CombatManager.Instance.DebugOnlyGetState();
				obj = ((obj2 != null) ? obj2.Players : null) ?? Array.Empty<Player>();
			}
			return (IReadOnlyList<Player>)obj;
		}

		private static int GetPlayerIndex(Player player)
		{
			IReadOnlyList<Player> combatPlayers = GetCombatPlayers(player);
			for (int i = 0; i < combatPlayers.Count; i++)
			{
				if (combatPlayers[i] == player)
				{
					return i;
				}
			}
			return -1;
		}

		private static bool ValidateArity(string action, int argCount)
		{
			if (action.Equals("get", StringComparison.OrdinalIgnoreCase) || action.Equals("reset", StringComparison.OrdinalIgnoreCase) || action.Equals("resetmax", StringComparison.OrdinalIgnoreCase))
			{
				if ((uint)(argCount - 2) <= 1u)
				{
					return true;
				}
				return false;
			}
			bool flag = IsMutationWithAmountAction(action);
			if (flag)
			{
				bool flag2 = (uint)(argCount - 3) <= 1u;
				flag = flag2;
			}
			return flag;
		}

		private static bool IsKnownAction(string action)
		{
			return Actions.Any((string candidate) => candidate.Equals(action, StringComparison.OrdinalIgnoreCase));
		}

		private static bool IsReadAction(string action)
		{
			if (!action.Equals("get", StringComparison.OrdinalIgnoreCase) && !action.Equals("reset", StringComparison.OrdinalIgnoreCase))
			{
				return action.Equals("resetmax", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}

		private static bool IsMutationWithAmountAction(string action)
		{
			if (!action.Equals("gain", StringComparison.OrdinalIgnoreCase) && !action.Equals("lose", StringComparison.OrdinalIgnoreCase))
			{
				return action.Equals("set", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}

		private static string UsageText()
		{
			return "Usage: sresource get <resourceId> [playerIndex] | sresource gain|lose|set <resourceId> <amount:int> [playerIndex] | sresource reset|resetmax <resourceId> [playerIndex] | sresource list";
		}
	}
