	///     <para xml:lang="zh-CN">指定卡牌附加的次级资源费用保持生效的时长。</para>
	/// </summary>
	public enum SecondaryResourceCostDuration
	{
		/// <summary>
		///     <para xml:lang="en">Persists until explicitly replaced or cleared.</para>
		///     <para xml:lang="zh-CN">持续生效，直至被显式替换或清除。</para>
		/// </summary>
		Permanent,
		/// <summary>
		///     <para xml:lang="en">Clears after the card is next played successfully.</para>
		///     <para xml:lang="zh-CN">在卡牌下一次成功打出后清除。</para>
		/// </summary>
		UntilPlayed,
		/// <summary>
		///     <para xml:lang="en">Clears at the end of the current turn.</para>
		///     <para xml:lang="zh-CN">在当前回合结束时清除。</para>
		/// </summary>
		ThisTurn,
		/// <summary>
		///     <para xml:lang="en">Lasts for the lifetime of the card's current combat instance.</para>
		///     <para xml:lang="zh-CN">在卡牌当前战斗实例的生命周期内持续生效。</para>
		/// </summary>
		ThisCombat
	}
	/// <summary>
	///     <para xml:lang="en">Describes a fixed or X cost paid with one secondary resource.</para>
	///     <para xml:lang="zh-CN">描述使用一种次级资源支付的固定费用或 X 费用。</para>
	/// </summary>
	public sealed record SecondaryResourceCost(int Amount, bool CostsX = false, int XMultiplier = 1)
	{
		/// <summary>
		///     <para xml:lang="en">Gets a fixed cost of zero.</para>
		///     <para xml:lang="zh-CN">获取数值为零的固定费用。</para>
		/// </summary>
		public static SecondaryResourceCost Free { get; } = new SecondaryResourceCost(0);

		/// <summary>
		///     <para xml:lang="en">Gets whether the descriptor represents a payment-bearing cost.</para>
		///     <para xml:lang="zh-CN">获取该描述是否表示一项需要支付的费用。</para>
		/// </summary>
		public bool IsMaterial
		{
			get
			{
				if (!CostsX)
				{
					return Amount > 0;
				}
				return true;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Creates an X-cost descriptor with the specified value multiplier.</para>
		///     <para xml:lang="zh-CN">创建一项使用指定数值倍率的 X 费用描述。</para>
		/// </summary>
		public static SecondaryResourceCost X(int multiplier = 1)
		{
			ArgumentOutOfRangeException.ThrowIfNegativeOrZero(multiplier, "multiplier");
			return new SecondaryResourceCost(0, CostsX: true, multiplier);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Stores layered secondary-resource costs attached to one card.</para>
	///     <para xml:lang="zh-CN">存储附加到一张卡牌上的分层次级资源费用。</para>
	/// </summary>
	public sealed class SecondaryResourceCostSet
	{
		private readonly Dictionary<string, List<SecondaryResourceCostLayer>> _costs = new Dictionary<string, List<SecondaryResourceCostLayer>>(StringComparer.OrdinalIgnoreCase);

		/// <summary>
		///     <para xml:lang="en">Gets whether at least one active cost can require payment.</para>
		///     <para xml:lang="zh-CN">获取是否至少有一项当前费用可能需要支付。</para>
		/// </summary>
		public bool HasCosts => _costs.Values.SelectMany((List<SecondaryResourceCostLayer> layers) => layers).Any((SecondaryResourceCostLayer layer) => layer.Cost.IsMaterial);

		/// <summary>
		///     <para xml:lang="en">Gets the resource identifiers that currently have attached cost layers.</para>
		///     <para xml:lang="zh-CN">获取当前存在附加费用层的资源标识符。</para>
		/// </summary>
		public IReadOnlyList<string> ResourceIds
		{
			get
			{
				List<string> list = new List<string>();
				list.AddRange(_costs.Keys.OrderBy<string, string>((string id) => id, StringComparer.Ordinal));
				return new <>z__ReadOnlyList<string>(list);
			}
		}

		internal bool HasLayers => _costs.Count > 0;

		internal bool HasPermanentLayers => _costs.Values.SelectMany((List<SecondaryResourceCostLayer> layers) => layers).Any((SecondaryResourceCostLayer layer) => layer.Duration == SecondaryResourceCostDuration.Permanent);

		/// <summary>
		///     <para xml:lang="en">Occurs after the attached costs change.</para>
		///     <para xml:lang="zh-CN">在附加费用发生变化后触发。</para>
		/// </summary>
		public event Action? Changed;

		/// <summary>
		///     <para xml:lang="en">Sets a persistent fixed cost for one resource.</para>
		///     <para xml:lang="zh-CN">为一种资源设置持续生效的固定费用。</para>
		/// </summary>
		public SecondaryResourceCostSet Set(string resourceId, int amount)
		{
			return Set(resourceId, new SecondaryResourceCost(Math.Max(0, amount)));
		}

		/// <summary>
		///     <para xml:lang="en">Sets a persistent cost descriptor for one resource.</para>
		///     <para xml:lang="zh-CN">为一种资源设置持续生效的费用描述。</para>
		/// </summary>
		public SecondaryResourceCostSet Set(string resourceId, SecondaryResourceCost cost)
		{
			return Set(resourceId, cost, SecondaryResourceCostDuration.Permanent);
		}

		/// <summary>
		///     <para xml:lang="en">Sets a cost descriptor for one resource at the specified duration.</para>
		///     <para xml:lang="zh-CN">为一种资源设置具有指定持续时间的费用描述。</para>
		/// </summary>
		public SecondaryResourceCostSet Set(string resourceId, SecondaryResourceCost cost, SecondaryResourceCostDuration duration)
		{
			return Set(resourceId, cost, duration, null);
		}

		/// <summary>
		///     <para xml:lang="en">Sets a persistent fixed cost whose shortfall does not prevent card play.</para>
		///     <para xml:lang="zh-CN">设置一项持续生效且费用缺口不会阻止出牌的固定费用。</para>
		/// </summary>
		public SecondaryResourceCostSet SetAllowingShortfall(string resourceId, int amount, SecondaryResourceShortfallPaymentHandler? onShortfall = null, bool spendAvailable = true, SecondaryResourceShortfallResolver? resolveShortfall = null)
		{
			return SetAllowingShortfall(resourceId, new SecondaryResourceCost(Math.Max(0, amount)), onShortfall, spendAvailable, resolveShortfall);
		}

		/// <summary>
		///     <para xml:lang="en">Sets a cost whose shortfall does not prevent card play.</para>
		///     <para xml:lang="zh-CN">设置一项费用缺口不会阻止出牌的费用。</para>
		/// </summary>
		public SecondaryResourceCostSet SetAllowingShortfall(string resourceId, SecondaryResourceCost cost, SecondaryResourceShortfallPaymentHandler? onShortfall = null, bool spendAvailable = true, SecondaryResourceShortfallResolver? resolveShortfall = null, SecondaryResourceCostDuration duration = SecondaryResourceCostDuration.Permanent)
		{
			return Set(resourceId, cost, duration, SecondaryResourceInsufficientPayment.AllowPlay(onShortfall, spendAvailable, resolveShortfall));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets a cost descriptor for one resource with the specified duration and insufficient-payment
		///         policy.
		///     </para>
		///     <para xml:lang="zh-CN">为一种资源设置具有指定持续时间及资源不足支付策略的费用描述。</para>
		/// </summary>
		public SecondaryResourceCostSet Set(string resourceId, SecondaryResourceCost cost, SecondaryResourceCostDuration duration, SecondaryResourceInsufficientPayment? insufficientPayment)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(resourceId, "resourceId");
			ArgumentNullException.ThrowIfNull(cost, "cost");
			ValidateCost(cost);
			List<SecondaryResourceCostLayer> layers = GetLayers(resourceId);
			layers.RemoveAll((SecondaryResourceCostLayer layer) => layer.Duration == duration);
			layers.Add(new SecondaryResourceCostLayer(cost, duration, insufficientPayment));
			Changed?.Invoke();
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Clears every cost layer for one resource.</para>
		///     <para xml:lang="zh-CN">清除一种资源的所有费用层。</para>
		/// </summary>
		public bool Clear(string resourceId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(resourceId, "resourceId");
			bool num = _costs.Remove(resourceId.Trim());
			if (num)
			{
				Action? action = Changed;
				if (action == null)
				{
					return num;
				}
				action();
			}
			return num;
		}

		/// <summary>
		///     <para xml:lang="en">Clears every cost layer with the specified duration.</para>
		///     <para xml:lang="zh-CN">清除所有具有指定持续时间的费用层。</para>
		/// </summary>
		public bool ClearDuration(SecondaryResourceCostDuration duration)
		{
			bool flag = false;
			string[] array = _costs.Keys.ToArray();
			foreach (string key in array)
			{
				flag |= _costs[key].RemoveAll((SecondaryResourceCostLayer layer) => layer.Duration == duration) > 0;
				if (_costs[key].Count == 0)
				{
					_costs.Remove(key);
				}
			}
			if (flag)
			{
				Changed?.Invoke();
			}
			return flag;
		}

		/// <summary>
		///     <para xml:lang="en">Gets the active cost descriptor for one resource.</para>
		///     <para xml:lang="zh-CN">获取一种资源当前生效的费用描述。</para>
		/// </summary>
		public SecondaryResourceCost Get(string resourceId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(resourceId, "resourceId");
			if (!_costs.TryGetValue(resourceId.Trim(), out List<SecondaryResourceCostLayer> value) || value.Count == 0)
			{
				return SecondaryResourceCost.Free;
			}
			List<SecondaryResourceCostLayer> list = value;
			return list[list.Count - 1].Cost;
		}

		/// <summary>
		///     <para xml:lang="en">Returns the active payment-bearing costs in deterministic resource order.</para>
		///     <para xml:lang="zh-CN">按确定的资源顺序返回当前需要支付的费用。</para>
		/// </summary>
		public IReadOnlyDictionary<string, SecondaryResourceCost> Snapshot()
		{
			return (from pair in _costs.Select<KeyValuePair<string, List<SecondaryResourceCostLayer>>, KeyValuePair<string, SecondaryResourceCost>>(delegate(KeyValuePair<string, List<SecondaryResourceCostLayer>> pair)
				{
					string key = pair.Key;
					List<SecondaryResourceCostLayer> value = pair.Value;
					return new KeyValuePair<string, SecondaryResourceCost>(key, value[value.Count - 1].Cost);
				})
				where pair.Value.IsMaterial
				select pair).OrderBy<KeyValuePair<string, SecondaryResourceCost>, string>((KeyValuePair<string, SecondaryResourceCost> pair) => pair.Key, StringComparer.Ordinal).ToDictionary<KeyValuePair<string, SecondaryResourceCost>, string, SecondaryResourceCost>((KeyValuePair<string, SecondaryResourceCost> pair) => pair.Key, (KeyValuePair<string, SecondaryResourceCost> pair) => pair.Value, StringComparer.OrdinalIgnoreCase);
		}

		internal IReadOnlyList<SecondaryResourcePlayUse> SnapshotUses()
		{
			List<SecondaryResourcePlayUse> list = new List<SecondaryResourcePlayUse>();
			list.AddRange((from use in _costs.Select<KeyValuePair<string, List<SecondaryResourceCostLayer>>, SecondaryResourcePlayUse>(delegate(KeyValuePair<string, List<SecondaryResourceCostLayer>> pair)
				{
					List<SecondaryResourceCostLayer> value = pair.Value;
					SecondaryResourceCostLayer secondaryResourceCostLayer = value[value.Count - 1];
					SecondaryResourceCost baseCost = pair.Value.LastOrDefault((SecondaryResourceCostLayer candidate) => candidate.Duration == SecondaryResourceCostDuration.Permanent)?.Cost ?? secondaryResourceCostLayer.Cost;
					return new SecondaryResourcePlayUse(pair.Key, pair.Key, secondaryResourceCostLayer.Cost, SecondaryResourceUseKind.RequiredCost)
					{
						Duration = secondaryResourceCostLayer.Duration,
						BaseCost = baseCost,
						InsufficientPayment = secondaryResourceCostLayer.InsufficientPayment
					};
				})
				where use.IsMaterial
				select use).OrderBy<SecondaryResourcePlayUse, string>((SecondaryResourcePlayUse use) => use.Id, StringComparer.Ordinal));
			return new <>z__ReadOnlyList<SecondaryResourcePlayUse>(list);
		}

		internal SecondaryResourceCostSet Clone()
		{
			SecondaryResourceCostSet secondaryResourceCostSet = new SecondaryResourceCostSet();
			foreach (var (key, source) in _costs)
			{
				secondaryResourceCostSet._costs[key] = source.ToList();
			}
			return secondaryResourceCostSet;
		}

		internal bool ResetPermanentLayersFrom(SecondaryResourceCostSet? canonicalCosts)
		{
			bool flag = false;
			string[] array = _costs.Keys.ToArray();
			foreach (string key in array)
			{
				flag |= _costs[key].RemoveAll((SecondaryResourceCostLayer layer) => layer.Duration == SecondaryResourceCostDuration.Permanent) > 0;
				if (_costs[key].Count == 0)
				{
					_costs.Remove(key);
				}
			}
			if (canonicalCosts != null)
			{
				foreach (var (key2, source) in canonicalCosts._costs)
				{
					SecondaryResourceCostLayer[] array2 = source.Where((SecondaryResourceCostLayer layer) => layer.Duration == SecondaryResourceCostDuration.Permanent).ToArray();
					if (array2.Length != 0)
					{
						if (_costs.TryGetValue(key2, out List<SecondaryResourceCostLayer> value))
						{
							value.InsertRange(0, array2);
						}
						else
						{
							_costs[key2] = array2.ToList();
						}
						flag = true;
					}
				}
			}
			if (flag)
			{
				Changed?.Invoke();
			}
			return flag;
		}

		private List<SecondaryResourceCostLayer> GetLayers(string resourceId)
		{
			string key = resourceId.Trim();
			if (_costs.TryGetValue(key, out List<SecondaryResourceCostLayer> value))
			{
				return value;
			}
			value = new List<SecondaryResourceCostLayer>();
			_costs[key] = value;
			return value;
		}

		private static void ValidateCost(SecondaryResourceCost cost)
		{
			if ((object)cost != null && cost.CostsX && cost.XMultiplier <= 0)
			{
				throw new ArgumentOutOfRangeException("cost", "An X secondary-resource cost must have a positive multiplier.");
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides access to secondary-resource costs attached to cards.</para>
	///     <para xml:lang="zh-CN">提供对卡牌附加次级资源费用的访问。</para>
	/// </summary>
	public static class SecondaryResourceCardExtensions
	{
		private static readonly AttachedState<CardModel, SecondaryResourceCostSet> CostSets = new AttachedState<CardModel, SecondaryResourceCostSet>(() => new SecondaryResourceCostSet());

		private static readonly AttachedState<CardModel, SecondaryResourcePlayUseSet> UseSets = new AttachedState<CardModel, SecondaryResourcePlayUseSet>(() => new SecondaryResourcePlayUseSet());

		/// <summary>
		///     <para xml:lang="en">Gets or creates the secondary-resource cost set attached to this card.</para>
		///     <para xml:lang="zh-CN">获取或创建附加到此卡牌的次级资源费用集合。</para>
		/// </summary>
		public static SecondaryResourceCostSet SecondaryCosts(this CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			return CostSets.GetOrCreate(card);
		}

		/// <summary>
		///     <para xml:lang="en">Tries to get the attached cost set without creating one.</para>
		///     <para xml:lang="zh-CN">尝试获取已附加的费用集合，且不会创建新集合。</para>
		/// </summary>
		public static bool TryGetSecondaryCosts(this CardModel card, out SecondaryResourceCostSet costs)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			return CostSets.TryGetValue(card, out costs);
		}

		/// <summary>
		///     <para xml:lang="en">Clears costs that last until the card is played.</para>
		///     <para xml:lang="zh-CN">清除持续到卡牌打出为止的费用。</para>
		/// </summary>
		public static bool ClearSecondaryCostsUntilPlayed(this CardModel card)
		{
			bool flag = card.TryGetSecondaryCosts(out SecondaryResourceCostSet costs) && costs.ClearDuration(SecondaryResourceCostDuration.UntilPlayed);
			return card.ClearSecondaryResourceUsesUntilPlayed() | flag;
		}

		/// <summary>
		///     <para xml:lang="en">Clears costs that last for the current turn.</para>
		///     <para xml:lang="zh-CN">清除仅在当前回合生效的费用。</para>
		/// </summary>
		public static bool ClearSecondaryCostsThisTurn(this CardModel card)
		{
			bool flag = card.TryGetSecondaryCosts(out SecondaryResourceCostSet costs) && costs.ClearDuration(SecondaryResourceCostDuration.ThisTurn);
			return card.ClearSecondaryResourceUsesThisTurn() | flag;
		}

		internal static bool HasMaterialSecondaryCosts(this CardModel card)
		{
			return card.HasMaterialSecondaryResourceWork();
		}

		internal static bool CopySecondaryCostsTo(this CardModel source, CardModel destination)
		{
			ArgumentNullException.ThrowIfNull(source, "source");
			ArgumentNullException.ThrowIfNull(destination, "destination");
			if (!source.TryGetSecondaryCosts(out SecondaryResourceCostSet costs) || !costs.HasLayers)
			{
				return false;
			}
			CostSets.Set(destination, costs.Clone());
			return true;
		}

		internal static void ResetSecondaryResourcesForDowngrade(this CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			CardModel canonical = ModelDb.GetById<CardModel>(((AbstractModel)card).Id).ToMutable();
			canonical.ResetSecondaryCostsForDowngradeFrom(card);
			canonical.ResetSecondaryResourceUsesForDowngradeFrom(card);
		}

		private static bool ResetSecondaryCostsForDowngradeFrom(this CardModel canonical, CardModel card)
		{
			ArgumentNullException.ThrowIfNull(canonical, "canonical");
			ArgumentNullException.ThrowIfNull(card, "card");
			bool flag = canonical.TryGetSecondaryCosts(out SecondaryResourceCostSet costs) && costs.HasPermanentLayers;
			if (!card.TryGetSecondaryCosts(out SecondaryResourceCostSet costs2))
			{
				if (!flag)
				{
					return false;
				}
				costs2 = CostSets.Set(card, new SecondaryResourceCostSet());
			}
			return costs2.ResetPermanentLayersFrom(flag ? costs : null);
		}

		/// <summary>
		///     <para xml:lang="en">Gets or creates the secondary-resource payment-use set attached to this card.</para>
		///     <para xml:lang="zh-CN">获取或创建附加到此卡牌的次级资源支付条款集合。</para>
		/// </summary>
		public static SecondaryResourcePlayUseSet SecondaryResourceUses(this CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			return UseSets.GetOrCreate(card);
		}

		/// <summary>
		///     <para xml:lang="en">Tries to get the attached payment-use set without creating one.</para>
		///     <para xml:lang="zh-CN">尝试获取已附加的支付条款集合，且不会创建新集合。</para>
		/// </summary>
		public static bool TryGetSecondaryResourceUses(this CardModel card, out SecondaryResourcePlayUseSet uses)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			return UseSets.TryGetValue(card, out uses);
		}

		internal static bool ClearSecondaryResourceUsesUntilPlayed(this CardModel card)
		{
			if (card.TryGetSecondaryResourceUses(out SecondaryResourcePlayUseSet uses))
			{
				return uses.ClearDuration(SecondaryResourceCostDuration.UntilPlayed);
			}
			return false;
		}

		internal static bool ClearSecondaryResourceUsesThisTurn(this CardModel card)
		{
			if (card.TryGetSecondaryResourceUses(out SecondaryResourcePlayUseSet uses))
			{
				return uses.ClearDuration(SecondaryResourceCostDuration.ThisTurn);
			}
			return false;
		}

		internal static bool HasMaterialSecondaryResourceWork(this CardModel card)
		{
			if (!ModSecondaryResourceRegistry.HasAny)
			{
				return false;
			}
			if ((!card.TryGetSecondaryCosts(out SecondaryResourceCostSet costs) || !costs.HasCosts) && (!card.TryGetSecondaryResourceUses(out SecondaryResourcePlayUseSet uses) || !uses.HasUses))
			{
				return ModelCapabilityHost.GetCapabilities<ICardSecondaryResourceUseContributor>((AbstractModel)(object)card).Any();
			}
			return true;
		}

		internal static bool CopySecondaryResourceUsesTo(this CardModel source, CardModel destination)
		{
			ArgumentNullException.ThrowIfNull(source, "source");
			ArgumentNullException.ThrowIfNull(destination, "destination");
			if (!source.TryGetSecondaryResourceUses(out SecondaryResourcePlayUseSet uses) || !uses.HasLayers)
			{
				return false;
			}
			UseSets.Set(destination, uses.Clone());
			return true;
		}

		internal static bool ResetSecondaryResourceUsesForDowngradeFrom(this CardModel canonical, CardModel card)
		{
			ArgumentNullException.ThrowIfNull(canonical, "canonical");
			ArgumentNullException.ThrowIfNull(card, "card");
			bool flag = canonical.TryGetSecondaryResourceUses(out SecondaryResourcePlayUseSet uses) && uses.HasPermanentLayers;
			if (!card.TryGetSecondaryResourceUses(out SecondaryResourcePlayUseSet uses2))
			{
				if (!flag)
				{
					return false;
				}
				uses2 = UseSets.Set(card, new SecondaryResourcePlayUseSet());
			}
			return uses2.ResetPermanentLayersFrom(flag ? uses : null);
		}
	}
	internal static class SecondaryResourceCloneBridge
	{
		private static bool _initialized;

		public static void Initialize()
		{
			if (!_initialized)
			{
				ModelCloneRegistry.For("com.ritsukage.sts2-RitsuLib").Register<CardModel>("secondary_resource_costs", (Action<CardModel, CardModel>)CopySecondaryCosts);
				_initialized = true;
			}
		}

		private static void CopySecondaryCosts(CardModel prototype, CardModel clone)
		{
			prototype.CopySecondaryCostsTo(clone);
			prototype.CopySecondaryResourceUsesTo(clone);
		}
	}
	internal sealed record SecondaryResourceCostLayer(SecondaryResourceCost Cost, SecondaryResourceCostDuration Duration, SecondaryResourceInsufficientPayment? InsufficientPayment = null);
	/// <summary>
	///     <para xml:lang="en">Describes one resolved secondary-resource payment entry in a card-play plan.</para>
	///     <para xml:lang="zh-CN">描述出牌计划中一项已解析的次级资源支付条目。</para>
	/// </summary>
	public sealed record SecondaryResourcePaymentLine(string ResourceId, SecondaryResourceDefinition Definition, int Cost, int AmountAvailable, int AmountToSpend, int Value, bool CostsX, bool IsFree)
	{
		/// <summary>
		///     <para xml:lang="en">Gets whether the entry is a preview, is free, or has enough primary resource.</para>
		///     <para xml:lang="zh-CN">获取该条目是否为预览、免费，或拥有足够的主要支付资源。</para>
		/// </summary>
		public bool IsAffordable
		{
			get
			{
				if (!IsPreview && !IsFree)
				{
					return AmountAvailable >= Cost;
				}
				return true;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets the shortfall remaining after planned replacement payments.</para>
		///     <para xml:lang="zh-CN">获取规划的替代支付完成后仍剩余的费用缺口。</para>
		/// </summary>
		public int Shortfall { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the shortfall before any replacement payment is applied.</para>
		///     <para xml:lang="zh-CN">获取应用任何替代支付前的原始费用缺口。</para>
		/// </summary>
		public int OriginalShortfall { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the amount of the original shortfall covered by replacement payments.</para>
		///     <para xml:lang="zh-CN">获取替代支付在原始费用缺口中补足的数量。</para>
		/// </summary>
		public int CoveredShortfall { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the insufficient-payment policy selected for this entry.</para>
		///     <para xml:lang="zh-CN">获取为该条目选定的资源不足支付策略。</para>
		/// </summary>
		public SecondaryResourceInsufficientPayment InsufficientPayment { get; init; } = SecondaryResourceInsufficientPayment.BlockPlay;

		/// <summary>
		///     <para xml:lang="en">Gets whether the resource-payment hooks permit this entry's planned spend.</para>
		///     <para xml:lang="zh-CN">获取资源支付钩子是否允许该条目的规划消耗。</para>
		/// </summary>
		public bool SpendAllowed { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">Gets whether this entry can execute its planned resource spend.</para>
		///     <para xml:lang="zh-CN">获取该条目是否可以执行规划的资源消耗。</para>
		/// </summary>
		public bool CanSpend
		{
			get
			{
				if (!IsPreview && !IsFree && AmountToSpend > 0)
				{
					return SpendAllowed;
				}
				return true;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether this entry cannot by itself prevent the card from being played.</para>
		///     <para xml:lang="zh-CN">获取该条目是否不会单独阻止卡牌打出。</para>
		/// </summary>
		public bool IsOptional => !BlocksPlay;

		/// <summary>
		///     <para xml:lang="en">Gets whether this entry is a repeatable extra payment.</para>
		///     <para xml:lang="zh-CN">获取该条目是否为可重复的额外支付。</para>
		/// </summary>
		public bool IsExtraSpend => Kind == SecondaryResourceUseKind.ExtraSpend;

		/// <summary>
		///     <para xml:lang="en">Gets whether this entry permits the card play to proceed.</para>
		///     <para xml:lang="zh-CN">获取该条目是否允许继续打出卡牌。</para>
		/// </summary>
		public bool CanPlay
		{
			get
			{
				if (BlocksPlay)
				{
					if (IsAffordable || IsShortfallPlayable || IsShortfallCovered)
					{
						return CanSpend;
					}
					return false;
				}
				return true;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether this required entry has a resource shortfall that its policy permits.
		///     </para>
		///     <para xml:lang="zh-CN">获取该必需条目是否存在其支付策略所允许的资源缺口。</para>
		/// </summary>
		public bool IsShortfallPlayable
		{
			get
			{
				if (BlocksPlay && Activated && Shortfall > 0)
				{
					return InsufficientPayment.AllowsPlay;
				}
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether replacement payments cover the entire original shortfall.</para>
		///     <para xml:lang="zh-CN">获取替代支付是否已补足全部原始费用缺口。</para>
		/// </summary>
		public bool IsShortfallCovered
		{
			get
			{
				if (BlocksPlay && Activated && OriginalShortfall > 0)
				{
					return CoveredShortfall >= OriginalShortfall;
				}
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets the replacement-payment plan selected for this entry.</para>
		///     <para xml:lang="zh-CN">获取为该条目选定的替代支付方案。</para>
		/// </summary>
		public SecondaryResourceShortfallResolution ShortfallResolution { get; init; } = SecondaryResourceShortfallResolution.None;

		/// <summary>
		///     <para xml:lang="en">Gets the number of complete extra-payment units bought by this entry.</para>
		///     <para xml:lang="zh-CN">获取该条目购买的完整额外支付单位数。</para>
		/// </summary>
		public int ExtraStacks { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the total resource amount spent on repeatable extra payments.</para>
		///     <para xml:lang="zh-CN">获取用于可重复额外支付的资源总量。</para>
		/// </summary>
		public int ExtraAmountToSpend { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the stable payment-use identifier represented by this entry.</para>
		///     <para xml:lang="zh-CN">获取该条目所表示的稳定支付条款标识符。</para>
		/// </summary>
		public string UseId { get; init; } = ResourceId;

		/// <summary>
		///     <para xml:lang="en">Gets the payment role of this entry.</para>
		///     <para xml:lang="zh-CN">获取该条目的支付用途。</para>
		/// </summary>
		public SecondaryResourceUseKind Kind { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets whether failure to pay this entry can prevent the card from being played.</para>
		///     <para xml:lang="zh-CN">获取该条目无法支付时是否可能阻止卡牌打出。</para>
		/// </summary>
		public bool BlocksPlay { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">Gets whether this entry is active in the current card-play plan.</para>
		///     <para xml:lang="zh-CN">获取该条目是否已在当前出牌计划中激活。</para>
		/// </summary>
		public bool Activated { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets whether this entry was resolved without an owning player for display only.</para>
		///     <para xml:lang="zh-CN">获取该条目是否在没有所属玩家的情况下解析，仅供显示使用。</para>
		/// </summary>
		public bool IsPreview { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the current unmodified fixed cost used for display-color comparison.</para>
		///     <para xml:lang="zh-CN">获取用于比较显示颜色的当前未修正固定费用。</para>
		/// </summary>
		public int BaseCost { get; init; } = Cost;

		/// <summary>
		///     <para xml:lang="en">Gets the fixed cost before the upgrade currently being previewed, if known.</para>
		///     <para xml:lang="zh-CN">获取当前预览的升级生效前的固定费用（如果已知）。</para>
		/// </summary>
		public int? UpgradePreviewBaseCost { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets whether a runtime effect participates in this entry's displayed fixed cost.</para>
		///     <para xml:lang="zh-CN">获取运行时效果是否参与计算该条目的显示固定费用。</para>
		/// </summary>
		public bool HasRuntimeCostModifier { get; init; }
	}
	/// <summary>
	///     <para xml:lang="en">Describes the resolved secondary-resource payment plan for one card play.</para>
	///     <para xml:lang="zh-CN">描述一次出牌所采用的已解析次级资源支付计划。</para>
	/// </summary>
	public sealed record SecondaryResourcePaymentPlan(CardModel Card, Player? Player, bool IsFree, IReadOnlyList<SecondaryResourcePaymentLine> Lines)
	{
		/// <summary>
		///     <para xml:lang="en">Gets whether every payment entry permits the card to be played.</para>
		///     <para xml:lang="zh-CN">获取每项支付条目是否都允许打出卡牌。</para>
		/// </summary>
		public bool IsAffordable => Lines.All((SecondaryResourcePaymentLine line) => line.CanPlay);

		/// <summary>
		///     <para xml:lang="en">Gets whether the plan contains at least one payment entry.</para>
		///     <para xml:lang="zh-CN">获取该计划是否至少包含一项支付条目。</para>
		/// </summary>
		public bool HasLines => Lines.Count > 0;

		/// <summary>
		///     <para xml:lang="en">Gets whether the plan was resolved without an owning player and cannot be committed.</para>
		///     <para xml:lang="zh-CN">获取该计划是否在没有所属玩家的情况下解析，因而无法提交。</para>
		/// </summary>
		public bool IsPreview => Player == null;

		/// <summary>
		///     <para xml:lang="en">Creates a payment plan with no secondary-resource entries.</para>
		///     <para xml:lang="zh-CN">创建一项不包含次级资源支付条目的计划。</para>
		/// </summary>
		public static SecondaryResourcePaymentPlan Empty(CardModel card, Player? player, bool isFree = false)
		{
			return new SecondaryResourcePaymentPlan(card, player, isFree, Array.Empty<SecondaryResourcePaymentLine>());
		}
	}
	internal readonly record struct SecondaryResourcePaymentFreeMode(bool FixedCostsFree, bool XCostsFree)
	{
		public static SecondaryResourcePaymentFreeMode None { get; } = new SecondaryResourcePaymentFreeMode(FixedCostsFree: false, XCostsFree: false);

		public static SecondaryResourcePaymentFreeMode AllCosts { get; } = new SecondaryResourcePaymentFreeMode(FixedCostsFree: true, XCostsFree: true);

		public static SecondaryResourcePaymentFreeMode AutoPlayCapture { get; } = new SecondaryResourcePaymentFreeMode(FixedCostsFree: true, XCostsFree: false);

		public bool IsFree
		{
			get
			{
				if (!FixedCostsFree)
				{
					return XCostsFree;
				}
				return true;
			}
		}

		public static SecondaryResourcePaymentFreeMode FromCardCostScope(FreePlayCardCostScope scope)
		{
			return new SecondaryResourcePaymentFreeMode(scope.FixedSecondaryCostsFree, scope.XSecondaryCostsFree);
		}

		public bool AppliesTo(SecondaryResourceCost cost)
		{
			if (!cost.CostsX)
			{
				return FixedCostsFree;
			}
			return XCostsFree;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Builds and commits secondary-resource payment plans for card plays.</para>
	///     <para xml:lang="zh-CN">构建并提交出牌所需的次级资源支付计划。</para>
	/// </summary>
	public static class SecondaryResourcePaymentResolver
	{
		/// <summary>
		///     <para xml:lang="en">Resolves the card's secondary-resource payment plan.</para>
		///     <para xml:lang="zh-CN">解析该卡牌的次级资源支付计划。</para>
		/// </summary>
		public static SecondaryResourcePaymentPlan Plan(CardModel card, bool isFree = false, AbstractModel? source = null)
		{
			return Plan(card, isFree ? SecondaryResourcePaymentFreeMode.AllCosts : SecondaryResourcePaymentFreeMode.None, source);
		}

		internal static SecondaryResourcePaymentPlan Plan(CardModel card, SecondaryResourcePaymentFreeMode freeMode, AbstractModel? source = null)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			return Plan(card, card.CombatState, freeMode, source);
		}

		internal static SecondaryResourcePaymentPlan PlanForCombat(CardModel card, ICombatState combatState, SecondaryResourcePaymentFreeMode freeMode, AbstractModel? source = null)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			ArgumentNullException.ThrowIfNull(combatState, "combatState");
			return Plan(card, combatState, freeMode, source);
		}

		private static SecondaryResourcePaymentPlan Plan(CardModel card, ICombatState? combatState, SecondaryResourcePaymentFreeMode freeMode, AbstractModel? source)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			Player val = TryGetOwner(card);
			if (!ModSecondaryResourceRegistry.HasAny)
			{
				return SecondaryResourcePaymentPlan.Empty(card, val, freeMode.IsFree);
			}
			IReadOnlyList<SecondaryResourcePlayUse> readOnlyList = SnapshotUses(card);
			if (readOnlyList.Count == 0)
			{
				return SecondaryResourcePaymentPlan.Empty(card, val, freeMode.IsFree);
			}
			if (val == null || combatState == null)
			{
				return PlanPreview(card, readOnlyList, freeMode);
			}
			List<SecondaryResourcePaymentLine> list = new List<SecondaryResourcePaymentLine>();
			Dictionary<string, int> dictionary = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
			foreach (SecondaryResourcePlayUse item in readOnlyList)
			{
				if (ModSecondaryResourceRegistry.TryGet(item.ResourceId, out SecondaryResourceDefinition definition))
				{
					if (!dictionary.TryGetValue(definition.Id, out var value))
					{
						value = SecondaryResourceCmd.Get(val, definition.Id);
						dictionary[definition.Id] = value;
					}
					SecondaryResourcePaymentLine secondaryResourcePaymentLine = ResolveLine(combatState, val, card, definition, item, value, freeMode, source);
					list.Add(secondaryResourcePaymentLine);
					dictionary[definition.Id] = Math.Max(0, value - secondaryResourcePaymentLine.AmountToSpend);
				}
			}
			return new SecondaryResourcePaymentPlan(card, val, freeMode.IsFree, list);
		}

		private static Player? TryGetOwner(CardModel card)
		{
			if (!((AbstractModel)card).IsCanonical)
			{
				return card.Owner;
			}
			return null;
		}

		/// <summary>
		///     <para xml:lang="en">Returns whether every secondary-resource payment permits the card to be played.</para>
		///     <para xml:lang="zh-CN">返回每项次级资源支付是否都允许打出该卡牌。</para>
		/// </summary>
		public static bool CanPay(CardModel card)
		{
			return Plan(card).IsAffordable;
		}

		/// <summary>
		///     <para xml:lang="en">Commits a still-valid resolved payment plan and returns its play ledger.</para>
		///     <para xml:lang="zh-CN">提交一项仍然有效的已解析支付计划，并返回本次出牌的支付记录。</para>
		/// </summary>
		public static async Task<SecondaryResourcePlayLedger> Commit(SecondaryResourcePaymentPlan plan, AbstractModel? source = null)
		{
			ArgumentNullException.ThrowIfNull(plan, "plan");
			ValidateCommitPlan(plan);
			if (plan.Player == null)
			{
				if (plan.HasLines)
				{
					throw new InvalidOperationException("Cannot commit secondary resource payments for " + ((AbstractModel)plan.Card).Id.Entry + " without a player owner.");
				}
				SecondaryResourcePlayLedger secondaryResourcePlayLedger = SecondaryResourcePlayLedger.Empty(plan.Card, null, plan.IsFree);
				SecondaryResourcePlayLedgerRuntime.SetPending(plan.Card, secondaryResourcePlayLedger);
				return secondaryResourcePlayLedger;
			}
			SecondaryResourcePlayLedgerBuilder builder = new SecondaryResourcePlayLedgerBuilder(plan.Card, plan.Player, plan.IsFree);
			foreach (SecondaryResourcePaymentLine line in plan.Lines)
			{
				if ((object)line != null && !line.IsFree && line.AmountToSpend > 0 && !(await SecondaryResourceCmd.SpendResolvedCardPayment(plan.Player, line.ResourceId, line.AmountToSpend, plan.Card, (AbstractModel?)(((object)source) ?? ((object)plan.Card)))))
				{
					throw new InvalidOperationException($"Secondary resource payment failed for {line.ResourceId} on {((AbstractModel)plan.Card).Id.Entry}.");
				}
				builder.Add(line);
			}
			SecondaryResourcePlayLedger ledger = builder.Build();
			SecondaryResourcePlayLedgerRuntime.SetPending(plan.Card, ledger);
			await RunShortfallPayments(plan, ledger, (AbstractModel?)(((object)source) ?? ((object)plan.Card)));
			return ledger;
		}

		private static void ValidateCommitPlan(SecondaryResourcePaymentPlan plan)
		{
			IGrouping<string, SecondaryResourcePaymentLine> grouping = plan.Lines.GroupBy<SecondaryResourcePaymentLine, string>((SecondaryResourcePaymentLine line) => line.UseId, StringComparer.OrdinalIgnoreCase).FirstOrDefault((IGrouping<string, SecondaryResourcePaymentLine> group) => group.Count() > 1);
			if (grouping != null)
			{
				throw new InvalidOperationException($"Secondary resource payment plan for {((AbstractModel)plan.Card).Id.Entry} contains duplicate use id '{grouping.Key}'.");
			}
			SecondaryResourcePaymentLine secondaryResourcePaymentLine = plan.Lines.FirstOrDefault((SecondaryResourcePaymentLine line) => !line.CanPlay);
			if (secondaryResourcePaymentLine != null)
			{
				throw new InvalidOperationException($"Cannot commit unplayable secondary resource payment for {secondaryResourcePaymentLine.ResourceId} on {((AbstractModel)plan.Card).Id.Entry}.");
			}
			if (plan.Player == null)
			{
				return;
			}
			foreach (IGrouping<string, SecondaryResourcePaymentLine> item in plan.Lines.Where((SecondaryResourcePaymentLine line) => (object)line != null && !line.IsFree && line.AmountToSpend > 0).GroupBy<SecondaryResourcePaymentLine, string>((SecondaryResourcePaymentLine line) => line.ResourceId, StringComparer.OrdinalIgnoreCase))
			{
				if (item.Aggregate(0L, (long sum, SecondaryResourcePaymentLine line) => sum + line.AmountToSpend) > SecondaryResourceCmd.Get(plan.Player, item.Key))
				{
					throw new InvalidOperationException($"Secondary resource payment plan for {((AbstractModel)plan.Card).Id.Entry} no longer has enough '{item.Key}'.");
				}
			}
		}

		private static async Task RunShortfallPayments(SecondaryResourcePaymentPlan plan, SecondaryResourcePlayLedger ledger, AbstractModel? source)
		{
			Player? player = plan.Player;
			object obj;
			if (player == null)
			{
				obj = null;
			}
			else
			{
				Creature creature = player.Creature;
				obj = ((creature != null) ? creature.CombatState : null);
			}
			if (obj == null)
			{
				return;
			}
			ICombatState combatState = plan.Player.Creature.CombatState;
			foreach (SecondaryResourcePaymentLine line in plan.Lines)
			{
				if ((object)line != null && line.Activated && line.OriginalShortfall > 0 && !line.IsFree && line.InsufficientPayment.AllowsPlay)
				{
					SecondaryResourceShortfallContext context = new SecondaryResourceShortfallContext(combatState, plan.Player, line.Definition, plan.Card, line.UseId, line.Kind, line.Cost, line.AmountAvailable, line.AmountToSpend, line.OriginalShortfall, line.CoveredShortfall, line.Shortfall, source, ledger);
					if (line.CoveredShortfall > 0)
					{
						await line.ShortfallResolution.Commit(context);
					}
					if (line.Shortfall > 0)
					{
						await line.InsufficientPayment.InvokeShortfall(context);
						await SecondaryResourceHook.AfterShortfallPayment(context);
					}
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">Creates and queues a free-play ledger without changing resource amounts.</para>
		///     <para xml:lang="zh-CN">创建并排队等待绑定一份免费出牌支付记录，不改变资源数量。</para>
		/// </summary>
		public static SecondaryResourcePlayLedger CommitFree(SecondaryResourcePaymentPlan plan)
		{
			ArgumentNullException.ThrowIfNull(plan, "plan");
			SecondaryResourcePlayLedgerBuilder secondaryResourcePlayLedgerBuilder = new SecondaryResourcePlayLedgerBuilder(plan.Card, plan.Player, isFree: true);
			foreach (SecondaryResourcePaymentLine line2 in plan.Lines)
			{
				SecondaryResourcePaymentLine line = ((line2.Kind == SecondaryResourceUseKind.OptionalSpend) ? line2 with
				{
					IsFree = true,
					AmountToSpend = 0,
					Value = 0,
					Activated = true,
					OriginalShortfall = 0,
					CoveredShortfall = 0,
					Shortfall = 0,
					ShortfallResolution = SecondaryResourceShortfallResolution.None,
					ExtraAmountToSpend = 0,
					ExtraStacks = 0
				} : line2 with
				{
					IsFree = true,
					AmountToSpend = 0,
					Activated = true,
					OriginalShortfall = 0,
					CoveredShortfall = 0,
					Shortfall = 0,
					ShortfallResolution = SecondaryResourceShortfallResolution.None,
					ExtraAmountToSpend = 0,
					ExtraStacks = 0
				});
				secondaryResourcePlayLedgerBuilder.Add(line);
			}
			SecondaryResourcePlayLedger secondaryResourcePlayLedger = secondaryResourcePlayLedgerBuilder.Build();
			SecondaryResourcePlayLedgerRuntime.SetPending(plan.Card, secondaryResourcePlayLedger);
			return secondaryResourcePlayLedger;
		}

		internal static SecondaryResourcePlayLedger CommitAutoPlayCapture(SecondaryResourcePaymentPlan plan)
		{
			ArgumentNullException.ThrowIfNull(plan, "plan");
			SecondaryResourcePlayLedgerBuilder secondaryResourcePlayLedgerBuilder = new SecondaryResourcePlayLedgerBuilder(plan.Card, plan.Player, isFree: true);
			foreach (SecondaryResourcePaymentLine line2 in plan.Lines)
			{
				SecondaryResourcePaymentLine line = line2 with
				{
					IsFree = true,
					AmountToSpend = 0,
					Value = (((object)line2 == null || line2.CostsX || line2.Kind != SecondaryResourceUseKind.OptionalSpend) ? line2.Value : 0),
					OriginalShortfall = 0,
					CoveredShortfall = 0,
					Shortfall = 0,
					ShortfallResolution = SecondaryResourceShortfallResolution.None,
					ExtraAmountToSpend = 0,
					ExtraStacks = 0
				};
				secondaryResourcePlayLedgerBuilder.Add(line);
			}
			SecondaryResourcePlayLedger secondaryResourcePlayLedger = secondaryResourcePlayLedgerBuilder.Build();
			SecondaryResourcePlayLedgerRuntime.SetPending(plan.Card, secondaryResourcePlayLedger);
			return secondaryResourcePlayLedger;
		}

		private static IReadOnlyList<SecondaryResourcePlayUse> SnapshotUses(CardModel card)
		{
			List<SecondaryResourcePlayUse> list = new List<SecondaryResourcePlayUse>();
			if (card.TryGetSecondaryCosts(out SecondaryResourceCostSet costs))
			{
				list.AddRange(costs.SnapshotUses());
			}
			if (card.TryGetSecondaryResourceUses(out SecondaryResourcePlayUseSet uses))
			{
				list.AddRange(uses.Snapshot());
			}
			list.AddRange(GetCapabilityUses(card));
			SecondaryResourcePlayUse[] array = (from use in list
				where use.IsMaterial
				orderby use.Kind switch
				{
					SecondaryResourceUseKind.RequiredCost => 0, 
					SecondaryResourceUseKind.ExtraSpend => 1, 
					_ => 2, 
				}
				select use).ThenBy<SecondaryResourcePlayUse, string>((SecondaryResourcePlayUse use) => use.Id, StringComparer.Ordinal).ToArray();
			IGrouping<string, SecondaryResourcePlayUse> grouping = array.GroupBy<SecondaryResourcePlayUse, string>((SecondaryResourcePlayUse use) => use.Id, StringComparer.OrdinalIgnoreCase).FirstOrDefault((IGrouping<string, SecondaryResourcePlayUse> group) => group.Count() > 1);
			if (grouping != null)
			{
				throw new InvalidOperationException($"Card {((AbstractModel)card).Id.Entry} has duplicate secondary-resource use id '{grouping.Key}'.");
			}
			return array;
		}

		internal static IReadOnlyList<SecondaryResourcePlayUse> SnapshotUsesForUpgradePreview(CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			return SnapshotUses(card);
		}

		private static SecondaryResourcePaymentPlan PlanPreview(CardModel card, IReadOnlyList<SecondaryResourcePlayUse> uses, SecondaryResourcePaymentFreeMode freeMode)
		{
			List<SecondaryResourcePaymentLine> list = new List<SecondaryResourcePaymentLine>();
			foreach (SecondaryResourcePlayUse use in uses)
			{
				if (ModSecondaryResourceRegistry.TryGet(use.ResourceId, out SecondaryResourceDefinition definition))
				{
					list.Add(ResolvePreviewLine(card, definition, use, freeMode));
				}
			}
			return new SecondaryResourcePaymentPlan(card, null, freeMode.IsFree, list);
		}

		private static SecondaryResourcePaymentLine ResolvePreviewLine(CardModel card, SecondaryResourceDefinition definition, SecondaryResourcePlayUse use, SecondaryResourcePaymentFreeMode freeMode)
		{
			SecondaryResourceCost cost = use.Cost;
			bool flag = freeMode.AppliesTo(cost);
			decimal num = ModifyLocalCost(card, definition, use, cost.Amount);
			int baseCost = Math.Max(0, use.BaseCost.Amount);
			int? baseCost2 = SecondaryResourceUpgradePreviewCosts.GetBaseCost(card, use);
			int num2 = SecondaryResourceAmountMath.CeilingAndClamp(num, 0, int.MaxValue);
			int cost2 = ((!flag) ? num2 : 0);
			SecondaryResourceInsufficientPayment insufficientPayment = use.InsufficientPayment ?? definition.DefaultInsufficientPayment;
			bool hasRuntimeCostModifier = (use.Duration != SecondaryResourceCostDuration.Permanent || num != (decimal)cost.Amount) | flag;
			if (!cost.CostsX)
			{
				return new SecondaryResourcePaymentLine(definition.Id, definition, cost2, 0, (!flag) ? num2 : 0, num2, CostsX: false, flag)
				{
					UseId = use.Id,
					Kind = use.Kind,
					BlocksPlay = (use.Kind == SecondaryResourceUseKind.RequiredCost),
					Activated = ((use.Kind == SecondaryResourceUseKind.RequiredCost) | flag),
					IsPreview = true,
					BaseCost = baseCost,
					UpgradePreviewBaseCost = baseCost2,
					HasRuntimeCostModifier = hasRuntimeCostModifier,
					InsufficientPayment = insufficientPayment
				};
			}
			return new SecondaryResourcePaymentLine(definition.Id, definition, num2, 0, 0, 0, CostsX: true, flag)
			{
				UseId = use.Id,
				Kind = use.Kind,
				BlocksPlay = (use.Kind == SecondaryResourceUseKind.RequiredCost),
				Activated = flag,
				IsPreview = true,
				BaseCost = baseCost,
				UpgradePreviewBaseCost = baseCost2,
				HasRuntimeCostModifier = hasRuntimeCostModifier,
				InsufficientPayment = insufficientPayment
			};
		}

		private static SecondaryResourcePaymentLine ResolveLine(ICombatState combatState, Player player, CardModel card, SecondaryResourceDefinition definition, SecondaryResourcePlayUse use, int available, SecondaryResourcePaymentFreeMode freeMode, AbstractModel? source)
		{
			SecondaryResourceCost cost = use.Cost;
			bool flag = freeMode.AppliesTo(cost);
			decimal num = ModifyLocalCost(card, definition, use, cost.Amount);
			int baseCost = Math.Max(0, use.BaseCost.Amount);
			int? baseCost2 = SecondaryResourceUpgradePreviewCosts.GetBaseCost(card, use);
			decimal num2 = SecondaryResourceHook.ModifyCost(new SecondaryResourceCostContext(combatState, player, card, definition, num), num);
			int num3 = SecondaryResourceAmountMath.CeilingAndClamp(num2, 0, int.MaxValue);
			int num4 = ((!flag) ? num3 : 0);
			bool hasRuntimeCostModifier = (use.Duration != SecondaryResourceCostDuration.Permanent || num != (decimal)cost.Amount || num2 != num) | flag;
			bool flag2 = use.Kind == SecondaryResourceUseKind.RequiredCost;
			SecondaryResourceInsufficientPayment secondaryResourceInsufficientPayment = use.InsufficientPayment ?? definition.DefaultInsufficientPayment;
			if (!cost.CostsX)
			{
				int num5 = Math.Max(0, available);
				if (use.Kind == SecondaryResourceUseKind.ExtraSpend)
				{
					return ResolveExtraSpendLine(combatState, player, card, definition, use, available, num5, num3, num4, baseCost, baseCost2, flag, source);
				}
				int num6 = ((!flag) ? Math.Max(0, num3 - num5) : 0);
				int amountToSpend = ResolveAmountToSpend(flag2, activated: true, flag, num3, num5, secondaryResourceInsufficientPayment);
				SecondaryResourceInsufficientPayment secondaryResourceInsufficientPayment2 = ResolveInsufficientPayment(combatState, player, card, definition, use, num3, available, amountToSpend, num6, source, secondaryResourceInsufficientPayment);
				SecondaryResourceShortfallResolution secondaryResourceShortfallResolution = SecondaryResourceShortfallResolution.None;
				if (flag2 && num6 > 0 && secondaryResourceInsufficientPayment2.AllowsPlay)
				{
					SecondaryResourceShortfallResolutionContext context = new SecondaryResourceShortfallResolutionContext(combatState, player, definition, card, use.Id, use.Kind, num3, available, ResolveAmountToSpend(isRequired: true, activated: true, flag, num3, num5, secondaryResourceInsufficientPayment2), num6, (AbstractModel?)(((object)source) ?? ((object)card)));
					secondaryResourceShortfallResolution = secondaryResourceInsufficientPayment2.Resolve(context);
					secondaryResourceShortfallResolution = SecondaryResourceHook.ResolveShortfall(context, secondaryResourceShortfallResolution);
				}
				int num7 = Math.Min(num6, Math.Max(0, secondaryResourceShortfallResolution.CoveredAmount));
				int num8 = num6 - num7;
				bool flag3 = flag2 && num6 > 0 && secondaryResourceInsufficientPayment2.AllowsPlay && (num8 > 0 || num7 >= num6);
				bool flag4 = (flag || num5 >= num3) | flag3;
				int num9 = ResolveAmountToSpend(flag2, flag4, flag, num3, num5, secondaryResourceInsufficientPayment2);
				bool flag5 = CanSpend(combatState, player, card, definition, num9, source);
				if (!flag2 && !flag5)
				{
					flag4 = false;
					num9 = 0;
				}
				if (!flag4)
				{
					num6 = 0;
					num7 = 0;
					num8 = 0;
					secondaryResourceShortfallResolution = SecondaryResourceShortfallResolution.None;
				}
				int value = ((flag2 || flag4) ? num3 : 0);
				return new SecondaryResourcePaymentLine(definition.Id, definition, num4, available, num9, value, CostsX: false, flag)
				{
					UseId = use.Id,
					Kind = use.Kind,
					BlocksPlay = flag2,
					Activated = flag4,
					SpendAllowed = flag5,
					BaseCost = baseCost,
					UpgradePreviewBaseCost = baseCost2,
					HasRuntimeCostModifier = hasRuntimeCostModifier,
					OriginalShortfall = num6,
					CoveredShortfall = num7,
					Shortfall = num8,
					InsufficientPayment = secondaryResourceInsufficientPayment2,
					ShortfallResolution = secondaryResourceShortfallResolution
				};
			}
			int num10 = Math.Max(0, available);
			int value2 = Hook.ModifyXValue(combatState, card, num10);
			int left = SecondaryResourceHook.ModifyXValue(new SecondaryResourceXContext(combatState, player, card, definition, num10), value2);
			if (cost.XMultiplier <= 0)
			{
				throw new InvalidOperationException($"Secondary-resource X cost '{use.Id}' on {((AbstractModel)card).Id.Entry} must have a positive multiplier.");
			}
			left = SecondaryResourceAmountMath.MultiplyNonNegativeSaturating(left, cost.XMultiplier);
			bool flag6 = (flag2 | flag) || available > 0;
			int num11 = ((!flag && flag6) ? num10 : 0);
			bool flag7 = CanSpend(combatState, player, card, definition, num11, source);
			if (!flag2 && !flag7)
			{
				flag6 = false;
				num11 = 0;
			}
			int num12 = ((!flag || flag2) ? left : 0);
			return new SecondaryResourcePaymentLine(definition.Id, definition, num3, available, num11, flag6 ? num12 : 0, CostsX: true, flag)
			{
				UseId = use.Id,
				Kind = use.Kind,
				BlocksPlay = flag2,
				Activated = flag6,
				SpendAllowed = flag7,
				BaseCost = baseCost,
				UpgradePreviewBaseCost = baseCost2,
				HasRuntimeCostModifier = hasRuntimeCostModifier,
				InsufficientPayment = secondaryResourceInsufficientPayment
			};
		}

		private static SecondaryResourcePaymentLine ResolveExtraSpendLine(ICombatState combatState, Player player, CardModel card, SecondaryResourceDefinition definition, SecondaryResourcePlayUse use, int available, int availableToSpend, int perStackAmount, int displayCost, int baseCost, int? upgradePreviewBaseCost, bool isFree, AbstractModel? source)
		{
			int val = use.MaxExtraStacks ?? int.MaxValue;
			int num = ((!isFree && perStackAmount > 0) ? Math.Min(val, availableToSpend / perStackAmount) : 0);
			int num2 = num * perStackAmount;
			bool flag = CanSpend(combatState, player, card, definition, num2, source);
			if (!flag)
			{
				num = 0;
				num2 = 0;
			}
			return new SecondaryResourcePaymentLine(definition.Id, definition, displayCost, available, num2, num, CostsX: false, isFree)
			{
				UseId = use.Id,
				Kind = use.Kind,
				BlocksPlay = false,
				Activated = (num > 0),
				SpendAllowed = flag,
				BaseCost = baseCost,
				UpgradePreviewBaseCost = upgradePreviewBaseCost,
				HasRuntimeCostModifier = (isFree || perStackAmount != baseCost),
				ExtraStacks = num,
				ExtraAmountToSpend = num2
			};
		}

		private static int ResolveAmountToSpend(bool isRequired, bool activated, bool isFree, int fixedCost, int available, SecondaryResourceInsufficientPayment insufficientPayment)
		{
			if (!activated | isFree)
			{
				return 0;
			}
			if (!isRequired || available >= fixedCost)
			{
				return fixedCost;
			}
			if ((object)insufficientPayment == null || !insufficientPayment.AllowsPlay || !insufficientPayment.SpendAvailable)
			{
				return 0;
			}
			return available;
		}

		private static SecondaryResourceInsufficientPayment ResolveInsufficientPayment(ICombatState combatState, Player player, CardModel card, SecondaryResourceDefinition definition, SecondaryResourcePlayUse use, int cost, int available, int amountToSpend, int shortfall, AbstractModel? source, SecondaryResourceInsufficientPayment payment)
		{
			if (use.Kind != SecondaryResourceUseKind.RequiredCost || shortfall <= 0)
			{
				return payment;
			}
			return SecondaryResourceHook.ModifyInsufficientPayment(new SecondaryResourceInsufficientPaymentContext(combatState, player, definition, card, use.Id, use.Kind, cost, available, amountToSpend, shortfall, (AbstractModel?)(((object)source) ?? ((object)card))), payment);
		}

		private static IEnumerable<SecondaryResourcePlayUse> GetCapabilityUses(CardModel card)
		{
			foreach (ICardSecondaryResourceUseContributor capability in ModelCapabilityHost.GetCapabilities<ICardSecondaryResourceUseContributor>((AbstractModel)(object)card))
			{
				SecondaryResourcePlayUse[] array = capability.GetSecondaryResourceUses(card)?.ToArray() ?? throw new InvalidOperationException("Secondary-resource use contributor '" + capability.GetType().FullName + "' returned null.");
				SecondaryResourcePlayUse[] array2 = array;
				for (int i = 0; i < array2.Length; i++)
				{
					ValidateCapabilityUse(array2[i]);
				}
				foreach (SecondaryResourcePlayUse item in array.Select((SecondaryResourcePlayUse use) => use with
				{
					Id = use.Id.Trim(),
					ResourceId = use.ResourceId.Trim()
				}))
				{
					if (item.IsMaterial)
					{
						yield return item;
					}
				}
			}
		}

		private static void ValidateCapabilityUse(SecondaryResourcePlayUse? use)
		{
			if (use == null)
			{
				throw new InvalidOperationException("A secondary-resource use contributor returned a null use.");
			}
			if (string.IsNullOrWhiteSpace(use.Id))
			{
				throw new InvalidOperationException("A secondary-resource use contributor returned a use without an id.");
			}
			if (string.IsNullOrWhiteSpace(use.ResourceId))
			{
				throw new InvalidOperationException("Secondary-resource use '" + use.Id + "' does not specify a resource id.");
			}
			if (use.Cost == null)
			{
				throw new InvalidOperationException("Secondary-resource use '" + use.Id + "' does not specify a cost.");
			}
			SecondaryResourceCost cost = use.Cost;
			if ((object)cost != null && cost.CostsX && cost.XMultiplier <= 0)
			{
				throw new InvalidOperationException("Secondary-resource X use '" + use.Id + "' must have a positive multiplier.");
			}
			int? maxExtraStacks = use.MaxExtraStacks;
			if (maxExtraStacks.HasValue && maxExtraStacks.GetValueOrDefault() < 0)
			{
				throw new InvalidOperationException("Secondary-resource use '" + use.Id + "' has a negative maximum stack count.");
			}
			if ((object)use != null && use.Kind == SecondaryResourceUseKind.ExtraSpend)
			{
				cost = use.Cost;
				if ((object)cost != null && cost.CostsX)
				{
					throw new InvalidOperationException("Repeatable extra secondary-resource use '" + use.Id + "' cannot have an X cost.");
				}
			}
		}

		private static decimal ModifyLocalCost(CardModel card, SecondaryResourceDefinition definition, SecondaryResourcePlayUse use, decimal cost)
		{
			decimal num = cost;
			SecondaryResourceCardCostContext context = new SecondaryResourceCardCostContext(card, definition, use, cost);
			foreach (ICardSecondaryResourceCostContributor capability in ModelCapabilityHost.GetCapabilities<ICardSecondaryResourceCostContributor>((AbstractModel)(object)card))
			{
				num = capability.ModifySecondaryResourceCost(context, num);
			}
			return num;
		}

		private static bool CanSpend(ICombatState combatState, Player player, CardModel card, SecondaryResourceDefinition definition, int amount, AbstractModel? source)
		{
			if (amount > 0)
			{
				return SecondaryResourceHook.ShouldSpend(new SecondaryResourceSpendContext(combatState, player, definition, card, amount, (AbstractModel?)(((object)source) ?? ((object)card))));
			}
			return true;
		}
	}
	internal static class SecondaryResourceUpgradePreviewCosts
	{
		private static readonly AttachedState<CardModel, Dictionary<SecondaryResourcePlayUseKey, int>> BeforeUpgrade = new AttachedState<CardModel, Dictionary<SecondaryResourcePlayUseKey, int>>();

		internal static void Capture(CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			IReadOnlyList<SecondaryResourcePlayUse> source = SecondaryResourcePaymentResolver.SnapshotUsesForUpgradePreview(card);
			BeforeUpgrade.Set(card, source.ToDictionary((SecondaryResourcePlayUse use) => SecondaryResourcePlayUseKey.From(use), (SecondaryResourcePlayUse use) => Math.Max(0, use.BaseCost.Amount)));
		}

		internal static void Clear(CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			BeforeUpgrade.Remove(card);
		}

		internal static int? GetBaseCost(CardModel card, SecondaryResourcePlayUse use)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			ArgumentNullException.ThrowIfNull(use, "use");
			if (!BeforeUpgrade.TryGetValue(card, out Dictionary<SecondaryResourcePlayUseKey, int> value) || !value.TryGetValue(SecondaryResourcePlayUseKey.From(use), out var value2))
			{
				return null;
			}
			return value2;
		}
	}
	internal readonly record struct SecondaryResourcePlayUseKey(string Id, string ResourceId, SecondaryResourceUseKind Kind)
	{
		public static SecondaryResourcePlayUseKey From(SecondaryResourcePlayUse use)
		{
			return new SecondaryResourcePlayUseKey(use.Id, use.ResourceId, use.Kind);
		}
	}
