		internal string Format(int amount, int? maxAmount)
		{
			object obj = FormatAmount?.Invoke(amount, maxAmount);
			if (obj == null)
			{
				if (!maxAmount.HasValue)
				{
					return amount.ToString();
				}
				obj = $"{amount}/{maxAmount.Value}";
			}
			return (string)obj;
