			LocTable = locTable;
			TitleKey = titleKey;
			DescriptionKey = descriptionKey;
			SmallIconPath = smallIconPath;
			LargeIconPath = largeIconPath;
		}

		/// <summary>
		///     <para xml:lang="en">Determines whether this resource is visible in combat UI for <paramref name="player" />.</para>
		///     <para xml:lang="zh-CN">判断该资源是否在 <paramref name="player" /> 的战斗界面中可见。</para>
		/// </summary>
		public bool IsVisibleInCombatUi(Player player)
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			return SecondaryResourceVisibility.IsVisibleInCombatUi(this, player);
		}

		/// <summary>
		///     <para xml:lang="en">Determines whether this resource has a payment line to show on <paramref name="card" />.</para>
		///     <para xml:lang="zh-CN">判断该资源是否有需要在 <paramref name="card" /> 上显示的支付条目。</para>
		/// </summary>
		public bool IsVisibleOnCard(CardModel card, SecondaryResourcePaymentLine? paymentLine = null)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			return paymentLine != null;
		}

		internal bool IsVisibleInCombatUiWithoutPlayer()
		{
			return false;
		}

		internal SecondaryResourceDefinition Bind(string modId, string localId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(localId, "localId");
			string modId2 = modId.Trim();
			string localId2 = localId.Trim();
			string resourceId = ModSecondaryResourceRegistry.GetResourceId(modId2, localId2);
			Validate(resourceId);
			return this with
			{
				Id = resourceId,
				ModId = modId2,
				LocalId = localId2
			};
		}

		private void Validate(string id)
		{
			if (HardMaxAmount < MinAmount)
			{
				throw new InvalidOperationException("Secondary resource '" + id + "' has HardMaxAmount below MinAmount.");
			}
			int? baseMaxAmount = BaseMaxAmount;
			if (baseMaxAmount.HasValue && baseMaxAmount.GetValueOrDefault() < 0)
			{
				throw new InvalidOperationException("Secondary resource '" + id + "' cannot have a negative base max amount.");
			}
			if (ClampToMaxAmount)
			{
				int value = BaseMaxAmount ?? throw new InvalidOperationException("Secondary resource '" + id + "' cannot clamp to a maximum without BaseMaxAmount.");
				if (Math.Clamp(DefaultAmount, MinAmount, HardMaxAmount) > Math.Clamp(value, MinAmount, HardMaxAmount))
				{
					throw new InvalidOperationException("Secondary resource '" + id + "' cannot have a default amount above its base maximum when clamping.");
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Attaches secondary-resource events to the game's combat history.</para>
	///     <para xml:lang="zh-CN">将次级资源事件附加到游戏的战斗历史。</para>
	/// </summary>
	public static class SecondaryResourceHistory
	{
		private static readonly AttachedState<CombatHistory, SecondaryResourceHistoryBag> Bags = new AttachedState<CombatHistory, SecondaryResourceHistoryBag>(() => new SecondaryResourceHistoryBag());

		/// <summary>
		///     <para xml:lang="en">Returns all attached entries without allocating storage when none exist.</para>
		///     <para xml:lang="zh-CN">返回所有附加条目；不存在条目时不会创建存储。</para>
		/// </summary>
		public static IReadOnlyList<SecondaryResourceHistoryEntry> Entries(CombatHistory history)
		{
			ArgumentNullException.ThrowIfNull(history, "history");
			if (!Bags.TryGetValue(history, out SecondaryResourceHistoryBag value))
			{
				return Array.Empty<SecondaryResourceHistoryEntry>();
			}
			return value.Entries;
		}

		/// <summary>
		///     <para xml:lang="en">Returns amount-change entries.</para>
		///     <para xml:lang="zh-CN">返回数量变化条目。</para>
		/// </summary>
		public static IEnumerable<SecondaryResourceChangedEntry> Changes(CombatHistory history)
		{
			return Entries(history).OfType<SecondaryResourceChangedEntry>();
		}

		/// <summary>
		///     <para xml:lang="en">Returns payment entries.</para>
		///     <para xml:lang="zh-CN">返回支付条目。</para>
		/// </summary>
		public static IEnumerable<SecondaryResourceSpentEntry> Spends(CombatHistory history)
		{
			return Entries(history).OfType<SecondaryResourceSpentEntry>();
		}

		/// <summary>
		///     <para xml:lang="en">Returns reset entries.</para>
		///     <para xml:lang="zh-CN">返回重置条目。</para>
		/// </summary>
		public static IEnumerable<SecondaryResourceResetEntry> Resets(CombatHistory history)
		{
			return Entries(history).OfType<SecondaryResourceResetEntry>();
		}

		internal static void Changed(ICombatState combatState, SecondaryResourceChangeContext context)
		{
			if (ModSecondaryResourceRegistry.HasAny && context.OldAmount != context.NewAmount)
			{
				Add(combatState, new SecondaryResourceChangedEntry(combatState, context));
			}
		}

		internal static void Spent(ICombatState combatState, SecondaryResourceSpendContext context)
		{
			if (ModSecondaryResourceRegistry.HasAny && context.Amount > 0)
			{
				Add(combatState, new SecondaryResourceSpentEntry(combatState, context));
			}
		}

		internal static void Reset(ICombatState combatState, SecondaryResourceChangeContext context)
		{
			if (ModSecondaryResourceRegistry.HasAny)
			{
				Add(combatState, new SecondaryResourceResetEntry(combatState, context));
			}
		}

		private static void Add(ICombatState combatState, SecondaryResourceHistoryEntry entry)
		{
			CombatManager instance = CombatManager.Instance;
			CombatHistory val = ((instance != null) ? instance.History : null);
			if (val != null)
			{
				Bags.GetOrCreate(val).Add(entry);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides shared metadata for an attached secondary-resource history entry.</para>
	///     <para xml:lang="zh-CN">提供附加次级资源历史条目的共享元数据。</para>
	/// </summary>
	public abstract class SecondaryResourceHistoryEntry
	{
		private readonly Dictionary<ulong, int> _playerTurnNumbers;

		[CompilerGenerated]
		private readonly CombatSide <CurrentSide>k__BackingField;

		/// <summary>
		///     <para xml:lang="en">Gets the player whose resource was involved.</para>
		///     <para xml:lang="zh-CN">获取涉及该资源事件的玩家。</para>
		/// </summary>
		public Player Player { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the resource definition.</para>
		///     <para xml:lang="zh-CN">获取资源定义。</para>
		/// </summary>
		public SecondaryResourceDefinition Definition { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the model that caused the event, if known.</para>
		///     <para xml:lang="zh-CN">获取引发事件的模型（如已知）。</para>
		/// </summary>
		public AbstractModel? Source { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the combat round number recorded at creation.</para>
		///     <para xml:lang="zh-CN">获取创建时记录的战斗轮数。</para>
		/// </summary>
		public int RoundNumber { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the active combat side recorded at creation.</para>
		///     <para xml:lang="zh-CN">获取创建时记录的当前行动方。</para>
		/// </summary>
		public CombatSide CurrentSide
		{
			[CompilerGenerated]
			get
			{
				//IL_0001: Unknown result type (might be due to invalid IL or missing references)
				return <CurrentSide>k__BackingField;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets a human-readable diagnostic description.</para>
		///     <para xml:lang="zh-CN">获取供诊断使用的可读说明。</para>
		/// </summary>
		public abstract string Description { get; }

		/// <summary>
		///     <para xml:lang="en">Initializes an attached history entry.</para>
		///     <para xml:lang="zh-CN">初始化附加历史条目。</para>
		/// </summary>
		protected SecondaryResourceHistoryEntry(ICombatState combatState, Player player, SecondaryResourceDefinition definition, AbstractModel? source)
		{
			//IL_0035: Unknown result type (might be due to invalid IL or missing references)
			//IL_003a: Unknown result type (might be due to invalid IL or missing references)
			_playerTurnNumbers = new Dictionary<ulong, int>();
			base..ctor();
			Player = player;
			Definition = definition;
			Source = source;
			RoundNumber = combatState.RoundNumber;
			CurrentSide = combatState.CurrentSide;
			foreach (Player player2 in combatState.Players)
			{
				if (player2.PlayerCombatState != null)
				{
					_playerTurnNumbers[player2.NetId] = player2.PlayerCombatState.TurnNumber;
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">Determines whether the entry occurred during the current player turn.</para>
		///     <para xml:lang="zh-CN">判断条目是否发生在当前玩家回合。</para>
		/// </summary>
		public bool HappenedThisTurn(ICombatState? state)
		{
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			if (state == null || RoundNumber != state.RoundNumber || CurrentSide != state.CurrentSide)
			{
				return false;
			}
			foreach (KeyValuePair<ulong, int> playerTurnNumber in _playerTurnNumbers)
			{
				playerTurnNumber.Deconstruct(out var key, out var value);
				ulong num = key;
				int num2 = value;
				Player player = state.GetPlayer(num);
				if (player != null)
				{
					PlayerCombatState playerCombatState = player.PlayerCombatState;
					int? num3 = ((playerCombatState != null) ? new int?(playerCombatState.TurnNumber) : ((int?)null));
					value = num2;
					if (num3 == value)
					{
						continue;
					}
				}
				return false;
			}
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Determines whether the entry occurred during <paramref name="player" />'s previous turn.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         判断条目是否发生在 <paramref name="player" /> 的上一回合。
		///     </para>
		/// </summary>
		public bool HappenedLastPlayerTurn(Player player)
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			if (_playerTurnNumbers.TryGetValue(player.NetId, out var value))
			{
				PlayerCombatState playerCombatState = player.PlayerCombatState;
				if (playerCombatState == null)
				{
					return false;
				}
				return playerCombatState.TurnNumber - 1 == value;
			}
			return false;
		}
	}
	/// <summary>
