	/// <summary>
	///     <para xml:lang="en">Dispatches secondary-resource hooks to model, capability, and global listeners.</para>
	///     <para xml:lang="zh-CN">将次级资源钩子分发给模型、能力和全局监听器。</para>
	/// </summary>
	public static class SecondaryResourceHook
	{
		private static readonly ModelHookListenerRegistry<ISecondaryResourceHookListener> GlobalListeners = new ModelHookListenerRegistry<ISecondaryResourceHookListener>();

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a process-wide listener. Model-owned effects should normally implement
		///         <see cref="T:STS2RitsuLib.Combat.SecondaryResources.ISecondaryResourceHookListener" /> on that model instead.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册进程级监听器。由模型承载的效果通常应让该模型直接实现
		///         <see cref="T:STS2RitsuLib.Combat.SecondaryResources.ISecondaryResourceHookListener" />。
		///     </para>
		/// </summary>
		public static void RegisterGlobalListener(ISecondaryResourceHookListener listener)
		{
			GlobalListeners.Register(listener);
		}

		/// <summary>
		///     <para xml:lang="en">Applies maximum-amount modifiers.</para>
		///     <para xml:lang="zh-CN">应用最大数量修正。</para>
		/// </summary>
		public static decimal ModifyMaxAmount(SecondaryResourceMaxContext context, decimal amount)
		{
			return IterateListeners(context.CombatState).Aggregate(amount, (decimal current, ISecondaryResourceHookListener listener) => listener.ModifyMaxSecondaryResource(context, current));
		}

		/// <summary>
		///     <para xml:lang="en">Applies gain-amount modifiers.</para>
		///     <para xml:lang="zh-CN">应用增加量修正。</para>
		/// </summary>
		public static decimal ModifyGain(SecondaryResourceContext context, decimal amount)
		{
			return IterateListeners(context.CombatState, context.Source).Aggregate(amount, (decimal current, ISecondaryResourceHookListener listener) => listener.ModifySecondaryResourceGain(context, current));
		}

		/// <summary>
		///     <para xml:lang="en">Applies normal and late cost modifiers.</para>
		///     <para xml:lang="zh-CN">应用常规和后置费用修正。</para>
		/// </summary>
		public static decimal ModifyCost(SecondaryResourceCostContext context, decimal cost)
		{
			decimal seed = IterateCostListeners(context.CombatState, (AbstractModel)context.Card).Aggregate(cost, (decimal current, ISecondaryResourceHookListener listener) => listener.ModifySecondaryResourceCost(context, current));
			return IterateCostListeners(context.CombatState, (AbstractModel)context.Card).Aggregate(seed, (decimal current, ISecondaryResourceHookListener listener) => listener.ModifySecondaryResourceCostLate(context, current));
		}

		/// <summary>
		///     <para xml:lang="en">Applies secondary X-value modifiers.</para>
		///     <para xml:lang="zh-CN">应用次级 X 值修正。</para>
		/// </summary>
		public static int ModifyXValue(SecondaryResourceXContext context, int value)
		{
			return IterateListeners(context.CombatState, (AbstractModel)context.Card).Aggregate(value, (int current, ISecondaryResourceHookListener listener) => listener.ModifySecondaryResourceXValue(context, current));
		}

		/// <summary>
		///     <para xml:lang="en">Determines whether every listener permits a resource gain.</para>
		///     <para xml:lang="zh-CN">判断所有监听器是否都允许增加资源。</para>
		/// </summary>
		public static bool ShouldGain(SecondaryResourceContext context, decimal amount)
		{
			return IterateListeners(context.CombatState, context.Source).All((ISecondaryResourceHookListener listener) => listener.ShouldGainSecondaryResource(context, amount));
		}

		/// <summary>
		///     <para xml:lang="en">Determines whether every listener permits a resource payment.</para>
		///     <para xml:lang="zh-CN">判断所有监听器是否都允许支付资源。</para>
		/// </summary>
		public static bool ShouldSpend(SecondaryResourceSpendContext context)
		{
			return IterateListeners(context.CombatState, (AbstractModel)context.Card, context.Source).All((ISecondaryResourceHookListener listener) => listener.ShouldSpendSecondaryResource(context));
		}

		/// <summary>
		///     <para xml:lang="en">Applies insufficient-payment policy modifiers.</para>
		///     <para xml:lang="zh-CN">应用资源不足支付策略修正。</para>
		/// </summary>
		public static SecondaryResourceInsufficientPayment ModifyInsufficientPayment(SecondaryResourceInsufficientPaymentContext context, SecondaryResourceInsufficientPayment payment)
		{
			return IterateListeners(context.CombatState, (AbstractModel)context.Card, context.Source).Aggregate(payment, (SecondaryResourceInsufficientPayment current, ISecondaryResourceHookListener listener) => listener.ModifySecondaryResourceInsufficientPayment(context, current) ?? throw new InvalidOperationException("Secondary-resource hook listener '" + listener.GetType().FullName + "' returned a null insufficient-payment policy."));
		}

		/// <summary>
		///     <para xml:lang="en">Applies replacement-payment planners for a shortfall.</para>
		///     <para xml:lang="zh-CN">应用缺口替代支付规划器。</para>
		/// </summary>
		public static SecondaryResourceShortfallResolution ResolveShortfall(SecondaryResourceShortfallResolutionContext context, SecondaryResourceShortfallResolution resolution)
		{
			return IterateListeners(context.CombatState, (AbstractModel)context.Card, context.Source).Aggregate(resolution, (SecondaryResourceShortfallResolution current, ISecondaryResourceHookListener listener) => listener.ResolveSecondaryResourceShortfall(context, current) ?? throw new InvalidOperationException("Secondary-resource hook listener '" + listener.GetType().FullName + "' returned a null shortfall resolution."));
		}

		/// <summary>
		///     <para xml:lang="en">Determines whether every listener permits a reset.</para>
		///     <para xml:lang="zh-CN">判断所有监听器是否都允许重置资源。</para>
		/// </summary>
		public static bool ShouldReset(SecondaryResourceContext context)
		{
			return IterateListeners(context.CombatState, context.Source).All((ISecondaryResourceHookListener listener) => listener.ShouldResetSecondaryResource(context));
		}

		/// <summary>
		///     <para xml:lang="en">Runs listeners after an amount changes.</para>
		///     <para xml:lang="zh-CN">在数量变化后运行监听器。</para>
		/// </summary>
		public static async Task AfterChanged(SecondaryResourceChangeContext context)
		{
			foreach (ISecondaryResourceHookListener item in IterateListeners(context.CombatState, context.Source))
			{
				await item.AfterSecondaryResourceChanged(context);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Runs listeners after a resource payment.</para>
		///     <para xml:lang="zh-CN">在资源支付后运行监听器。</para>
		/// </summary>
		public static async Task AfterSpent(SecondaryResourceSpendContext context)
		{
			foreach (ISecondaryResourceHookListener item in IterateListeners(context.CombatState, (AbstractModel)context.Card, context.Source))
			{
				await item.AfterSecondaryResourceSpent(context);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Runs listeners after a payment with a remaining shortfall.</para>
		///     <para xml:lang="zh-CN">在仍有缺口的支付提交后运行监听器。</para>
		/// </summary>
		public static async Task AfterShortfallPayment(SecondaryResourceShortfallContext context)
		{
			foreach (ISecondaryResourceHookListener item in IterateListeners(context.CombatState, (AbstractModel)context.Card, context.Source))
			{
				await item.AfterSecondaryResourceShortfallPayment(context);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Runs listeners after a reset.</para>
		///     <para xml:lang="zh-CN">在资源重置后运行监听器。</para>
		/// </summary>
		public static async Task AfterReset(SecondaryResourceChangeContext context)
		{
			foreach (ISecondaryResourceHookListener item in IterateListeners(context.CombatState, context.Source))
			{
				await item.AfterSecondaryResourceReset(context);
			}
		}

		private static IEnumerable<ISecondaryResourceHookListener> IterateListeners(ICombatState combatState, params AbstractModel?[] extraModels)
		{
			if (!ModSecondaryResourceRegistry.HasAny)
			{
				yield break;
			}
			AbstractModel[] combatExtraModels = GetCombatExtraModels(extraModels);
			foreach (ModelHookListener<ISecondaryResourceHookListener> item in ModelHookListenerDispatcher.FromCombat(combatState, GlobalListeners, combatExtraModels))
			{
				yield return item.Listener;
			}
		}

		private static IEnumerable<ISecondaryResourceHookListener> IterateCostListeners(ICombatState combatState, params AbstractModel?[] extraModels)
		{
			if (!ModSecondaryResourceRegistry.HasAny)
			{
				yield break;
			}
			AbstractModel[] combatExtraModels = GetCombatExtraModels(extraModels);
			foreach (ModelHookListener<ISecondaryResourceHookListener> item in ModelHookListenerDispatcher.FromCombatWithAdapters(combatState, GlobalListeners, SecondaryResourceModelHookRegistry.Bind, combatExtraModels))
			{
				yield return item.Listener;
			}
		}

		private static AbstractModel?[] GetCombatExtraModels(AbstractModel?[] models)
		{
			int num = Enumerable.Count(models, (AbstractModel model) => model != null && model.ShouldReceiveCombatHooks);
			if (num == models.Length)
			{
				return models;
			}
			if (num == 0)
			{
				return Array.Empty<AbstractModel>();
			}
			AbstractModel[] array = (AbstractModel[])(object)new AbstractModel[num];
			int num2 = 0;
			foreach (AbstractModel val in models)
			{
				if (val != null && val.ShouldReceiveCombatHooks)
				{
					array[num2++] = val;
				}
			}
			return array;
		}
	}
