	/// <summary>
	///     <para xml:lang="en">Provides the fixed secondary-resource selector to SmartFormat.</para>
	///     <para xml:lang="zh-CN">向 SmartFormat 提供固定的次级资源选择器。</para>
	/// </summary>
	public sealed class SecondaryResourceLocStringSource : ISource
	{
		/// <summary>
		///     <para xml:lang="en">
		///         The selector used by localization JSON, for example
		///         <c>{secondaryResource:secondaryResourceIcons(charge,1)}</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         本地化 JSON 使用的选择器，例如
		///         <c>{secondaryResource:secondaryResourceIcons(charge,1)}</c>。
		///     </para>
		/// </summary>
		public const string SelectorName = "secondaryResource";

		/// <inheritdoc />
		public bool TryEvaluateSelector(ISelectorInfo selectorInfo)
		{
			ArgumentNullException.ThrowIfNull(selectorInfo, "selectorInfo");
			if (selectorInfo.SelectorIndex != 0 || !StringComparer.Ordinal.Equals(selectorInfo.SelectorText, "secondaryResource"))
			{
				return false;
			}
			selectorInfo.Result = SecondaryResourceLocStringMarker.Instance;
			return true;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Formats secondary-resource rich-text icons for SmartFormat.</para>
	///     <para xml:lang="zh-CN">为 SmartFormat 格式化次级资源富文本图标。</para>
	/// </summary>
	public sealed class SecondaryResourceIconsFormatter : IFormatter
	{
		/// <inheritdoc />
		public string Name
		{
			get
			{
				return "secondaryResourceIcons";
			}
			set
			{
				throw new NotImplementedException();
			}
		}

		/// <inheritdoc />
		public bool CanAutoDetect { get; set; }

		/// <inheritdoc />
		public bool TryEvaluateFormat(IFormattingInfo formattingInfo)
		{
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			if (!TryResolve(formattingInfo, out string resourceId, out int amount, out DynamicVar dynamicVar))
			{
				return false;
			}
			if (!SecondaryResourceText.TryGetIconTag(resourceId, out string iconTag))
			{
				throw new LocException("Unknown secondary resource icon id='" + resourceId + "'");
			}
			string text = ((amount > 0 && amount < 4) ? string.Concat(Enumerable.Repeat(iconTag, amount)) : ((dynamicVar == null) ? $"{amount}{iconTag}" : (dynamicVar.ToHighlightedString(false) + iconTag)));
			formattingInfo.Write(text);
			return true;
		}

		private static bool TryResolve(IFormattingInfo formattingInfo, out string resourceId, out int amount, out DynamicVar? dynamicVar)
		{
			//IL_01f6: Unknown result type (might be due to invalid IL or missing references)
			resourceId = string.Empty;
			amount = 0;
			dynamicVar = null;
			string text = formattingInfo.FormatterOptions?.Trim() ?? string.Empty;
			object currentValue = formattingInfo.CurrentValue;
			if (!(currentValue is SecondaryResourceLocStringMarker))
			{
				if (!(currentValue is SecondaryResourceVar secondaryResourceVar))
				{
					DynamicVar val = (DynamicVar)((currentValue is DynamicVar) ? currentValue : null);
					if (val == null)
					{
						if (!(currentValue is SecondaryResourceDefinition secondaryResourceDefinition))
						{
							if (!(currentValue is string text2))
							{
								if (!(currentValue is decimal value))
								{
									if (!(currentValue is int num))
									{
										if (currentValue is SecondaryResourcePaymentLine secondaryResourcePaymentLine)
										{
											resourceId = secondaryResourcePaymentLine.ResourceId;
											amount = (secondaryResourcePaymentLine.CostsX ? secondaryResourcePaymentLine.Value : secondaryResourcePaymentLine.Cost);
											return true;
										}
										throw new LocException($"Unknown value='{formattingInfo.CurrentValue}' type={formattingInfo.CurrentValue?.GetType()}");
									}
									if (string.IsNullOrWhiteSpace(text))
									{
										return false;
									}
									resourceId = text;
									amount = num;
									return true;
								}
								if (string.IsNullOrWhiteSpace(text))
								{
									return false;
								}
								resourceId = text;
								amount = SecondaryResourceAmountMath.TruncateAndClamp(value, int.MinValue, int.MaxValue);
								return true;
							}
							resourceId = text2;
							amount = ((!TryParseAmount(text, out var amount2)) ? 1 : amount2);
							return true;
						}
						resourceId = secondaryResourceDefinition.Id;
						amount = ((!TryParseAmount(text, out var amount3)) ? 1 : amount3);
						return true;
					}
					if (string.IsNullOrWhiteSpace(text))
					{
						return false;
					}
					resourceId = text;
					amount = SecondaryResourceAmountMath.RoundAndClamp(val.PreviewValue, int.MinValue, int.MaxValue);
					dynamicVar = val;
					return true;
				}
				resourceId = secondaryResourceVar.ResourceId;
				amount = SecondaryResourceAmountMath.RoundAndClamp(((DynamicVar)secondaryResourceVar).PreviewValue, int.MinValue, int.MaxValue);
				dynamicVar = (DynamicVar?)(object)secondaryResourceVar;
				return true;
			}
			return TryResolveMarkerOptions(formattingInfo.FormatterOptions, out resourceId, out amount);
		}

		private static bool TryParseAmount(string value, out int amount)
		{
			if (int.TryParse(value, out amount))
			{
				amount = Math.Max(0, amount);
				return true;
			}
			amount = 0;
			return false;
		}

		private static bool TryResolveMarkerOptions(string? options, out string resourceId, out int amount)
		{
			resourceId = string.Empty;
			amount = 1;
			string[] array = (options ?? string.Empty).Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
			int num = array.Length;
			if ((num < 1 || num > 2) ? true : false)
			{
				return false;
			}
			resourceId = array[0];
			if (array.Length == 2)
			{
				return TryParseAmount(array[1], out amount);
			}
			return true;
		}
	}
