				ModSmartFormatExtensionRegistry modSmartFormatExtensionRegistry = ModSmartFormatExtensionRegistry.For("com.ritsukage.sts2-RitsuLib");
				modSmartFormatExtensionRegistry.RegisterSource<SecondaryResourceLocStringSource>();
				modSmartFormatExtensionRegistry.Register<SecondaryResourceIconsFormatter>();
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Registers secondary-resource cost hooks for model types that cannot implement
	///         <see cref="T:STS2RitsuLib.Combat.SecondaryResources.ISecondaryResourceHookListener" /> directly.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为无法直接实现 <see cref="T:STS2RitsuLib.Combat.SecondaryResources.ISecondaryResourceHookListener" /> 的模型类型注册次级资源费用钩子。
	///     </para>
	/// </summary>
	public static class SecondaryResourceModelHookRegistry
	{
		private readonly record struct CostHooks(Func<AbstractModel, SecondaryResourceCostContext, decimal, decimal>? ModifyCost, Func<AbstractModel, SecondaryResourceCostContext, decimal, decimal>? ModifyCostLate);

		private sealed class BoundCostHooks(AbstractModel model, CostHooks hooks) : ISecondaryResourceHookListener
		{
			public decimal ModifySecondaryResourceCost(SecondaryResourceCostContext context, decimal cost)
			{
				return hooks.ModifyCost?.Invoke(model, context, cost) ?? cost;
			}

			public decimal ModifySecondaryResourceCostLate(SecondaryResourceCostContext context, decimal cost)
			{
				return hooks.ModifyCostLate?.Invoke(model, context, cost) ?? cost;
			}
		}

		private static readonly ConcurrentDictionary<Type, CostHooks> Hooks = new ConcurrentDictionary<Type, CostHooks>(new Dictionary<Type, CostHooks>
		{
			[typeof(VoidFormPower)] = new CostHooks(null, ModifyVoidFormCostLate),
			[typeof(BrilliantScarf)] = new CostHooks(null, ModifyBrilliantScarfCostLate)
		});

		/// <summary>
		///     <para xml:lang="en">Registers or replaces cost hooks for the exact model type <typeparamref name="TModel" />.</para>
		///     <para xml:lang="zh-CN">为精确模型类型 <typeparamref name="TModel" /> 注册或替换费用钩子。</para>
		/// </summary>
		public static void RegisterCostHooks<TModel>(Func<TModel, SecondaryResourceCostContext, decimal, decimal>? modifyCost = null, Func<TModel, SecondaryResourceCostContext, decimal, decimal>? modifyCostLate = null) where TModel : AbstractModel
		{
			if (modifyCost == null && modifyCostLate == null)
			{
				throw new ArgumentException("At least one cost hook must be provided.");
			}
			RegisterCostHooks(typeof(TModel), (modifyCost == null) ? null : ((Func<AbstractModel, SecondaryResourceCostContext, decimal, decimal>)((AbstractModel model, SecondaryResourceCostContext context, decimal cost) => modifyCost((TModel)(object)model, context, cost))), (modifyCostLate == null) ? null : ((Func<AbstractModel, SecondaryResourceCostContext, decimal, decimal>)((AbstractModel model, SecondaryResourceCostContext context, decimal cost) => modifyCostLate((TModel)(object)model, context, cost))));
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces cost hooks for an exact runtime model type.</para>
		///     <para xml:lang="zh-CN">为精确的运行时模型类型注册或替换费用钩子。</para>
		/// </summary>
		public static void RegisterCostHooks(Type modelType, Func<AbstractModel, SecondaryResourceCostContext, decimal, decimal>? modifyCost = null, Func<AbstractModel, SecondaryResourceCostContext, decimal, decimal>? modifyCostLate = null)
		{
			ArgumentNullException.ThrowIfNull(modelType, "modelType");
			if (!modelType.IsAssignableTo(typeof(AbstractModel)))
			{
				throw new ArgumentException(modelType.FullName + " must derive from " + typeof(AbstractModel).FullName + ".", "modelType");
			}
			if (modifyCost == null && modifyCostLate == null)
			{
				throw new ArgumentException("At least one cost hook must be provided.");
			}
			Hooks[modelType] = new CostHooks(modifyCost, modifyCostLate);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Removes cost hooks for the exact model type <typeparamref name="TModel" />, including built-in
		///         compatibility hooks.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         移除精确模型类型 <typeparamref name="TModel" /> 的费用钩子，包括内置兼容性钩子。
		///     </para>
		/// </summary>
		public static bool UnregisterCostHooks<TModel>() where TModel : AbstractModel
		{
			return UnregisterCostHooks(typeof(TModel));
		}

		/// <summary>
		///     <para xml:lang="en">Removes cost hooks for an exact runtime model type.</para>
		///     <para xml:lang="zh-CN">移除精确运行时模型类型的费用钩子。</para>
		/// </summary>
		public static bool UnregisterCostHooks(Type modelType)
		{
			ArgumentNullException.ThrowIfNull(modelType, "modelType");
			CostHooks value;
			return Hooks.TryRemove(modelType, out value);
		}

		internal static ISecondaryResourceHookListener? Bind(AbstractModel model)
		{
			if (!Hooks.TryGetValue(((object)model).GetType(), out var value))
			{
				return null;
			}
			return new BoundCostHooks(model, value);
		}

		private static decimal ModifyVoidFormCostLate(AbstractModel model, SecondaryResourceCostContext context, decimal cost)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Expected O, but got Unknown
			VoidFormPower val = (VoidFormPower)model;
			if (context.Card.Owner.Creature != ((PowerModel)val).Owner || !IsInHandOrPlay(context.Card))
			{
				return cost;
			}
			if (((PowerModel)val).GetInternalData<Data>().cardsPlayedThisTurn >= ((PowerModel)val).Amount)
			{
				return cost;
			}
			return 0m;
		}

		private static decimal ModifyBrilliantScarfCostLate(AbstractModel model, SecondaryResourceCostContext context, decimal cost)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Expected O, but got Unknown
			BrilliantScarf val = (BrilliantScarf)model;
			if (!CombatManager.Instance.IsInProgress || context.Card.Owner.Creature != ((RelicModel)val).Owner.Creature || (decimal)((RelicModel)val).DisplayAmount != ((DynamicVar)((RelicModel)val).DynamicVars.Cards).BaseValue - 1m || !IsInHandOrPlay(context.Card))
			{
				return cost;
			}
			return 0m;
		}

		private static bool IsInHandOrPlay(CardModel card)
		{
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_002b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			//IL_0031: Unknown result type (might be due to invalid IL or missing references)
			//IL_0033: Invalid comparison between Unknown and I4
			//IL_0035: Unknown result type (might be due to invalid IL or missing references)
			//IL_0037: Invalid comparison between Unknown and I4
			CardPile pile = card.Pile;
			PileType? val = ((pile != null) ? new PileType?(pile.Type) : ((PileType?)null));
			if (val.HasValue)
			{
				PileType valueOrDefault = val.GetValueOrDefault();
				if ((int)valueOrDefault == 2 || (int)valueOrDefault == 5)
				{
					return true;
				}
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Saves and restores persistent secondary-resource state.</para>
	///     <para xml:lang="zh-CN">保存和恢复需要持久化的次级资源状态。</para>
	/// </summary>
	public static class SecondaryResourcePersistence
	{
		private const string SaveKey = "secondary_resources";

		private static readonly RunSavedData<SecondaryResourceRunSaveState> SavedData = RunSavedDataStore.For("com.ritsukage.sts2-RitsuLib").Register("secondary_resources", () => new SecondaryResourceRunSaveState(), new RunSavedDataOptions
		{
			WritePolicy = RunSavedDataWritePolicy.WhenNonDefault
		});

		private static readonly Lock InitializeGate = new Lock();

		private static bool _initialized;

		private static bool _initializing;

		/// <summary>
		///     <para xml:lang="en">Registers the combat lifecycle handlers used for persistence.</para>
		///     <para xml:lang="zh-CN">注册持久化所用的战斗生命周期处理器。</para>
		/// </summary>
		public static void Initialize()
		{
			using (InitializeGate.EnterScope())
			{
				if (_initialized || _initializing)
				{
					return;
				}
				_initializing = true;
			}
			IDisposable disposable = null;
			IDisposable disposable2 = null;
			try
			{
				disposable = RitsuLibFramework.SubscribeLifecycle<CombatStartingEvent>(OnCombatStarting);
				disposable2 = RitsuLibFramework.SubscribeLifecycle<CombatEndedEvent>(OnCombatEnded);
				using (InitializeGate.EnterScope())
				{
					_initialized = true;
				}
			}
			catch
			{
				disposable2?.Dispose();
				disposable?.Dispose();
				throw;
			}
			finally
			{
				using (InitializeGate.EnterScope())
				{
					_initializing = false;
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a serializable snapshot. Run-scoped resources are always included; combat-scoped resources
		///         are included only when <paramref name="includeCombatScoped" /> is <see langword="true" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         创建可序列化快照。始终包含一局游戏范围的资源；仅当 <paramref name="includeCombatScoped" /> 为
		///         <see langword="true" /> 时包含战斗范围资源。
		///     </para>
		/// </summary>
		public static SecondaryResourceRunSaveState CreateSnapshot(ICombatState combatState, bool includeCombatScoped)
		{
			ArgumentNullException.ThrowIfNull(combatState, "combatState");
			SecondaryResourceRunSaveState secondaryResourceRunSaveState = new SecondaryResourceRunSaveState();
			if (!ModSecondaryResourceRegistry.HasAny)
			{
				return secondaryResourceRunSaveState;
			}
			foreach (Player player in combatState.Players)
			{
				CapturePlayer(player, secondaryResourceRunSaveState, includeCombatScoped);
			}
			return secondaryResourceRunSaveState;
		}

		/// <summary>
		///     <para xml:lang="en">Restores registered run- and combat-scoped values into a combat.</para>
		///     <para xml:lang="zh-CN">将已注册的一局游戏范围与战斗范围资源值恢复到一场战斗中。</para>
		/// </summary>
		public static void RestoreSnapshot(ICombatState combatState, SecondaryResourceRunSaveState snapshot)
		{
			ArgumentNullException.ThrowIfNull(combatState, "combatState");
			ArgumentNullException.ThrowIfNull(snapshot, "snapshot");
			if (!ModSecondaryResourceRegistry.HasAny)
			{
				return;
			}
			foreach (Player player in combatState.Players)
			{
				if (snapshot.PlayerAmounts.TryGetValue(player.NetId, out Dictionary<string, int> value))
				{
					RestorePlayer(player, value);
				}
			}
		}

		internal static void SyncRunScopedToSavedData(RunState runState, ICombatState combatState)
		{
			if (!ModSecondaryResourceRegistry.HasAny)
			{
				SavedData.Remove(runState);
				return;
			}
			SecondaryResourceRunSaveState secondaryResourceRunSaveState = CreateSnapshot(combatState, includeCombatScoped: false);
			if (secondaryResourceRunSaveState.IsEmpty)
			{
				SavedData.Remove(runState);
			}
			else
			{
				SavedData.Set(runState, secondaryResourceRunSaveState);
			}
		}

		private static void OnCombatStarting(CombatStartingEvent evt)
		{
			if (ModSecondaryResourceRegistry.HasAny)
			{
				IRunState runState = evt.RunState;
				RunState val = (RunState)(object)((runState is RunState) ? runState : null);
				if (val != null && evt.CombatState != null && SavedData.TryGet(val, out SecondaryResourceRunSaveState value))
				{
					RestoreSnapshot(evt.CombatState, value);
				}
			}
		}

		private static void OnCombatEnded(CombatEndedEvent evt)
		{
			IRunState runState = evt.RunState;
			RunState val = (RunState)(object)((runState is RunState) ? runState : null);
			if (val != null && evt.CombatState != null)
			{
				SyncRunScopedToSavedData(val, evt.CombatState);
			}
		}

		private static void CapturePlayer(Player player, SecondaryResourceRunSaveState snapshot, bool includeCombatScoped)
		{
			if (!SecondaryResourceStateStore.TryGet(player, out SecondaryResourceState state))
			{
				return;
			}
			foreach (var (resourceId, amount) in state.Snapshot())
			{
				if (ModSecondaryResourceRegistry.TryGet(resourceId, out SecondaryResourceDefinition definition) && (definition.PersistencePolicy == SecondaryResourcePersistencePolicy.Run || (includeCombatScoped && definition.PersistencePolicy == SecondaryResourcePersistencePolicy.Combat)))
				{
					snapshot.Set(player.NetId, resourceId, amount);
				}
			}
		}

		private static void RestorePlayer(Player player, Dictionary<string, int> amounts)
		{
			foreach (var (resourceId, amount) in amounts)
			{
				if (ModSecondaryResourceRegistry.TryGet(resourceId, out SecondaryResourceDefinition definition))
				{
					SecondaryResourcePersistencePolicy persistencePolicy = definition.PersistencePolicy;
					if ((uint)(persistencePolicy - 1) <= 1u)
					{
						SecondaryResourceStateStore.SetFromPersistence(player, resourceId, amount);
					}
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Stores serializable secondary-resource state grouped by player network ID.</para>
	///     <para xml:lang="zh-CN">存储按玩家网络 ID 分组的可序列化次级资源状态。</para>
	/// </summary>
	public sealed class SecondaryResourceRunSaveState
	{
		/// <summary>
		///     <para xml:lang="en">Gets or sets amounts indexed first by player network ID, then by resource ID.</para>
		///     <para xml:lang="zh-CN">获取或设置先按玩家网络 ID、再按资源 ID 索引的数量。</para>
		/// </summary>
		public Dictionary<ulong, Dictionary<string, int>> PlayerAmounts { get; set; } = new Dictionary<ulong, Dictionary<string, int>>();

		/// <summary>
		///     <para xml:lang="en">Gets whether no resource amounts are stored.</para>
		///     <para xml:lang="zh-CN">获取是否未存储任何资源数量。</para>
		/// </summary>
		public bool IsEmpty
		{
			get
			{
				if (PlayerAmounts.Count != 0)
				{
					return PlayerAmounts.Values.All((Dictionary<string, int> amounts) => amounts.Count == 0);
				}
				return true;
			}
		}

		internal void Set(ulong playerNetId, string resourceId, int amount)
		{
			if (!PlayerAmounts.TryGetValue(playerNetId, out Dictionary<string, int> value))
			{
				value = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
				PlayerAmounts[playerNetId] = value;
			}
			value[resourceId] = amount;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Records the secondary-resource payments resolved for one card play.</para>
	///     <para xml:lang="zh-CN">记录一次出牌所解析的次级资源支付情况。</para>
