	/// <summary>
	///     <para xml:lang="en">Records one payment use or one resource aggregate in a card-play ledger.</para>
	///     <para xml:lang="zh-CN">记录出牌支付记录中的一项支付条款或一项资源汇总。</para>
	/// </summary>
	public sealed record SecondaryResourcePlayLedgerLine(string ResourceId, int AmountSpent, int Value, bool CostsX, bool IsFree)
	{
		/// <summary>
		///     <para xml:lang="en">Gets the stable payment-use identifier represented by this entry.</para>
		///     <para xml:lang="zh-CN">获取该条目所表示的稳定支付条款标识符。</para>
		/// </summary>
		public string UseId { get; init; } = ResourceId;

		/// <summary>
		///     <para xml:lang="en">Gets the payment role represented by this entry.</para>
		///     <para xml:lang="zh-CN">获取该条目所表示的支付用途。</para>
		/// </summary>
		public SecondaryResourceUseKind Kind { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets whether this entry was active for the card play.</para>
		///     <para xml:lang="zh-CN">获取该条目是否在本次出牌中激活。</para>
		/// </summary>
		public bool Activated { get; init; } = IsFree || AmountSpent > 0 || Value > 0;

		/// <summary>
		///     <para xml:lang="en">Gets the payment shortfall that remained after replacement payments.</para>
		///     <para xml:lang="zh-CN">获取替代支付完成后仍未补足的费用缺口。</para>
		/// </summary>
		public int Shortfall { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the original shortfall before replacement payments.</para>
		///     <para xml:lang="zh-CN">获取应用替代支付前的原始费用缺口。</para>
		/// </summary>
		public int OriginalShortfall { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the amount of the original shortfall covered by replacement payments.</para>
		///     <para xml:lang="zh-CN">获取替代支付在原始费用缺口中补足的数量。</para>
		/// </summary>
		public int CoveredShortfall { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the amount spent on the base required or optional payment.</para>
		///     <para xml:lang="zh-CN">获取用于基础必需支付或可选支付的资源数量。</para>
		/// </summary>
		public int BaseAmountSpent { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the amount spent on repeatable extra payments.</para>
		///     <para xml:lang="zh-CN">获取用于可重复额外支付的资源数量。</para>
		/// </summary>
		public int ExtraAmountSpent { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the number of complete extra-payment units bought.</para>
		///     <para xml:lang="zh-CN">获取购买的完整额外支付单位数。</para>
		/// </summary>
		public int ExtraStacks { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets whether this entry represents an optional payment.</para>
		///     <para xml:lang="zh-CN">获取该条目是否表示一项可选支付。</para>
		/// </summary>
		public bool IsOptional => Kind == SecondaryResourceUseKind.OptionalSpend;

		/// <summary>
		///     <para xml:lang="en">Gets whether this entry represents a repeatable extra payment.</para>
		///     <para xml:lang="zh-CN">获取该条目是否表示一项可重复额外支付。</para>
		/// </summary>
		public bool IsExtraSpend => Kind == SecondaryResourceUseKind.ExtraSpend;

		/// <summary>
		///     <para xml:lang="en">Gets whether any payment shortfall remains.</para>
		///     <para xml:lang="zh-CN">获取是否仍有未补足的费用缺口。</para>
		/// </summary>
		public bool HasShortfall => Shortfall > 0;
	}
	internal sealed class SecondaryResourcePlayLedgerBuilder(CardModel card, Player? player, bool isFree)
	{
		private readonly Dictionary<string, SecondaryResourcePlayLedgerLine> _useLines = new Dictionary<string, SecondaryResourcePlayLedgerLine>(StringComparer.OrdinalIgnoreCase);

		public void Add(SecondaryResourcePaymentLine line)
		{
			SecondaryResourcePlayLedgerLine value = new SecondaryResourcePlayLedgerLine(line.ResourceId, (!line.IsFree) ? line.AmountToSpend : 0, line.Value, line.CostsX, line.IsFree)
			{
				UseId = line.UseId,
				Kind = line.Kind,
				Activated = line.Activated,
				OriginalShortfall = line.OriginalShortfall,
				CoveredShortfall = line.CoveredShortfall,
				Shortfall = line.Shortfall,
				BaseAmountSpent = ((line.Kind != SecondaryResourceUseKind.ExtraSpend) ? ((!line.IsFree) ? line.AmountToSpend : 0) : 0),
				ExtraAmountSpent = line.ExtraAmountToSpend,
				ExtraStacks = line.ExtraStacks
			};
			if (!_useLines.TryAdd(line.UseId, value))
			{
				throw new InvalidOperationException("Duplicate secondary-resource use id '" + line.UseId + "' in the card-play ledger.");
			}
		}

		public SecondaryResourcePlayLedger Build()
		{
			Dictionary<string, SecondaryResourcePlayLedgerLine> dictionary = _useLines.OrderBy<KeyValuePair<string, SecondaryResourcePlayLedgerLine>, string>((KeyValuePair<string, SecondaryResourcePlayLedgerLine> pair) => pair.Key, StringComparer.Ordinal).ToDictionary<KeyValuePair<string, SecondaryResourcePlayLedgerLine>, string, SecondaryResourcePlayLedgerLine>((KeyValuePair<string, SecondaryResourcePlayLedgerLine> pair) => pair.Key, (KeyValuePair<string, SecondaryResourcePlayLedgerLine> pair) => pair.Value, StringComparer.OrdinalIgnoreCase);
			Dictionary<string, SecondaryResourcePlayLedgerLine> lines = dictionary.Values.GroupBy<SecondaryResourcePlayLedgerLine, string>((SecondaryResourcePlayLedgerLine line) => line.ResourceId, StringComparer.OrdinalIgnoreCase).OrderBy<IGrouping<string, SecondaryResourcePlayLedgerLine>, string>((IGrouping<string, SecondaryResourcePlayLedgerLine> group) => group.Key, StringComparer.Ordinal).ToDictionary<IGrouping<string, SecondaryResourcePlayLedgerLine>, string, SecondaryResourcePlayLedgerLine>((IGrouping<string, SecondaryResourcePlayLedgerLine> group) => group.Key, delegate(IGrouping<string, SecondaryResourcePlayLedgerLine> group)
			{
				SecondaryResourcePlayLedgerLine[] array = group.ToArray();
				return new SecondaryResourcePlayLedgerLine(group.Key, SumSaturating(array, (SecondaryResourcePlayLedgerLine line) => line.AmountSpent), SumSaturating(array, (SecondaryResourcePlayLedgerLine line) => line.Value), array.Any((SecondaryResourcePlayLedgerLine line) => line.CostsX), array.All((SecondaryResourcePlayLedgerLine line) => line.IsFree))
				{
					UseId = group.Key,
					Kind = ((!array.Any((SecondaryResourcePlayLedgerLine line) => line.Kind == SecondaryResourceUseKind.RequiredCost)) ? (array.Any((SecondaryResourcePlayLedgerLine line) => line.Kind == SecondaryResourceUseKind.OptionalSpend) ? SecondaryResourceUseKind.OptionalSpend : SecondaryResourceUseKind.ExtraSpend) : SecondaryResourceUseKind.RequiredCost),
					Activated = array.Any((SecondaryResourcePlayLedgerLine line) => line.Activated),
					OriginalShortfall = SumSaturating(array, (SecondaryResourcePlayLedgerLine line) => line.OriginalShortfall),
					CoveredShortfall = SumSaturating(array, (SecondaryResourcePlayLedgerLine line) => line.CoveredShortfall),
					Shortfall = SumSaturating(array, (SecondaryResourcePlayLedgerLine line) => line.Shortfall),
					BaseAmountSpent = SumSaturating(array, (SecondaryResourcePlayLedgerLine line) => line.BaseAmountSpent),
					ExtraAmountSpent = SumSaturating(array, (SecondaryResourcePlayLedgerLine line) => line.ExtraAmountSpent),
					ExtraStacks = SumSaturating(array, (SecondaryResourcePlayLedgerLine line) => line.ExtraStacks)
				};
			}, StringComparer.OrdinalIgnoreCase);
			return new SecondaryResourcePlayLedger(card, player, isFree, lines)
			{
				UseLines = dictionary
			};
		}

		private static int SumSaturating(IEnumerable<SecondaryResourcePlayLedgerLine> lines, Func<SecondaryResourcePlayLedgerLine, int> selector)
		{
			return lines.Aggregate(0, (int sum, SecondaryResourcePlayLedgerLine line) => SecondaryResourceAmountMath.AddSaturating(sum, selector(line)));
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides access to secondary-resource payment ledgers attached to <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardPlay" /> instances.
	///     </para>
	///     <para xml:lang="zh-CN">提供对附加到 <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardPlay" /> 实例的次级资源支付记录的访问。</para>
	/// </summary>
	public static class SecondaryResourcePlayExtensions
	{
		/// <summary>
		///     <para xml:lang="en">Returns this card play's attached payment ledger, or an empty ledger.</para>
		///     <para xml:lang="zh-CN">返回附加到本次出牌的支付记录；没有时返回空记录。</para>
		/// </summary>
		public static SecondaryResourcePlayLedger SecondaryResources(this CardPlay play)
		{
			ArgumentNullException.ThrowIfNull(play, "play");
			return SecondaryResourcePlayLedgerRuntime.Get(play);
		}

		/// <summary>
		///     <para xml:lang="en">Tries to get a nonempty payment ledger attached to this card play.</para>
		///     <para xml:lang="zh-CN">尝试获取附加到本次出牌的非空支付记录。</para>
		/// </summary>
		public static bool TryGetSecondaryResources(this CardPlay play, out SecondaryResourcePlayLedger ledger)
		{
			ArgumentNullException.ThrowIfNull(play, "play");
			return SecondaryResourcePlayLedgerRuntime.TryGet(play, out ledger);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Stores queued and attached card-play payment ledgers at runtime.</para>
	///     <para xml:lang="zh-CN">在运行时存储排队等待绑定及已附加的出牌支付记录。</para>
	/// </summary>
	public static class SecondaryResourcePlayLedgerRuntime
	{
		private sealed class PendingLedgerBindingScope(CardModel card, SecondaryResourcePlayLedger ledger) : IDisposable
		{
			private bool _disposed;

			public SecondaryResourcePlayLedger Ledger { get; } = ledger;

			public void Dispose()
			{
				if (_disposed)
				{
					return;
				}
				_disposed = true;
				if (ActiveBindingScopes.TryGetValue(card, out List<PendingLedgerBindingScope> value))
				{
					value.Remove(this);
					if (value.Count == 0)
					{
						ActiveBindingScopes.Remove(card);
					}
				}
			}
		}

		private static readonly AttachedState<CardPlay, SecondaryResourcePlayLedger> PlayLedgers = new AttachedState<CardPlay, SecondaryResourcePlayLedger>();

		private static readonly AttachedState<CardModel, Queue<SecondaryResourcePlayLedger>> PendingLedgers = new AttachedState<CardModel, Queue<SecondaryResourcePlayLedger>>(() => new Queue<SecondaryResourcePlayLedger>());

		private static readonly AttachedState<CardModel, List<PendingLedgerBindingScope>> ActiveBindingScopes = new AttachedState<CardModel, List<PendingLedgerBindingScope>>(() => new List<PendingLedgerBindingScope>());

		/// <summary>
		///     <para xml:lang="en">Gets the ledger attached to a card play, or an empty ledger.</para>
		///     <para xml:lang="zh-CN">获取附加到一次出牌的支付记录；没有时返回空记录。</para>
		/// </summary>
		public static SecondaryResourcePlayLedger Get(CardPlay play)
		{
			ArgumentNullException.ThrowIfNull(play, "play");
			if (!PlayLedgers.TryGetValue(play, out SecondaryResourcePlayLedger value))
			{
				return SecondaryResourcePlayLedger.Empty(play.Card, play.Card.Owner, play.IsAutoPlay);
			}
			return value;
		}

		/// <summary>
		///     <para xml:lang="en">Tries to get a nonempty ledger attached to a card play.</para>
		///     <para xml:lang="zh-CN">尝试获取附加到一次出牌的非空支付记录。</para>
		/// </summary>
		public static bool TryGet(CardPlay play, out SecondaryResourcePlayLedger ledger)
		{
			ArgumentNullException.ThrowIfNull(play, "play");
			if (PlayLedgers.TryGetValue(play, out ledger) && ledger.HasLines)
			{
				return true;
			}
			ledger = null;
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Attaches a payment ledger directly to a card play.</para>
		///     <para xml:lang="zh-CN">将支付记录直接附加到一次出牌。</para>
		/// </summary>
		public static void Attach(CardPlay play, SecondaryResourcePlayLedger ledger)
		{
			ArgumentNullException.ThrowIfNull(play, "play");
			ArgumentNullException.ThrowIfNull(ledger, "ledger");
			PlayLedgers.Set(play, ledger);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Queues a ledger for the next <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardPlay" /> created for the specified card.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将支付记录加入队列，等待附加到指定卡牌创建的下一个 <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardPlay" />。
		///     </para>
		/// </summary>
		public static void SetPending(CardModel card, SecondaryResourcePlayLedger ledger)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			ArgumentNullException.ThrowIfNull(ledger, "ledger");
			PendingLedgers.GetOrCreate(card).Enqueue(ledger);
		}

		internal static bool TryRemovePending(CardModel card, SecondaryResourcePlayLedger ledger)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			ArgumentNullException.ThrowIfNull(ledger, "ledger");
			if (!PendingLedgers.TryGetValue(card, out Queue<SecondaryResourcePlayLedger> value) || value.Count == 0)
			{
				return false;
			}
			bool flag = false;
			SecondaryResourcePlayLedger[] array = value.ToArray();
			value.Clear();
			SecondaryResourcePlayLedger[] array2 = array;
			foreach (SecondaryResourcePlayLedger secondaryResourcePlayLedger in array2)
			{
				if (!flag && (object)secondaryResourcePlayLedger == ledger)
				{
					flag = true;
				}
				else
				{
					value.Enqueue(secondaryResourcePlayLedger);
				}
			}
			if (value.Count == 0)
			{
				PendingLedgers.Remove(card);
			}
			return flag;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether the card has a queued ledger or an active binding scope.
		///     </para>
		///     <para xml:lang="zh-CN">返回该卡牌是否有排队等待绑定的支付记录或活动绑定作用域。</para>
		/// </summary>
		public static bool HasPending(CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			if (ActiveBindingScopes.TryGetValue(card, out List<PendingLedgerBindingScope> value) && value.Count > 0)
			{
				return true;
			}
			if (PendingLedgers.TryGetValue(card, out Queue<SecondaryResourcePlayLedger> value2))
			{
				return value2.Count > 0;
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Begins an <c>OnPlayWrapper</c> binding scope that reuses one queued ledger for every
		///         <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardPlay" /> created within the scope.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         开始一个 <c>OnPlayWrapper</c> 绑定作用域，使一份排队的支付记录可供作用域内创建的每个
		///         <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardPlay" /> 复用。
		///     </para>
		/// </summary>
		public static IDisposable? BeginPendingScope(CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			if (!PendingLedgers.TryGetValue(card, out Queue<SecondaryResourcePlayLedger> value) || value.Count == 0)
			{
				return null;
			}
			PendingLedgerBindingScope pendingLedgerBindingScope = new PendingLedgerBindingScope(card, value.Dequeue());
			ActiveBindingScopes.GetOrCreate(card).Add(pendingLedgerBindingScope);
			if (value.Count == 0)
			{
				PendingLedgers.Remove(card);
			}
			return pendingLedgerBindingScope;
		}

		/// <summary>
		///     <para xml:lang="en">Binds an available queued or scoped ledger to a newly created card play.</para>
		///     <para xml:lang="zh-CN">将可用的排队或作用域内支付记录绑定到新创建的出牌。</para>
		/// </summary>
		public static bool TryBindPending(CardPlay play)
		{
			ArgumentNullException.ThrowIfNull(play, "play");
			if (ActiveBindingScopes.TryGetValue(play.Card, out List<PendingLedgerBindingScope> value) && value.Count > 0)
			{
				List<PendingLedgerBindingScope> list = value;
				Attach(play, list[list.Count - 1].Ledger);
				return true;
			}
			if (!PendingLedgers.TryGetValue(play.Card, out Queue<SecondaryResourcePlayLedger> value2) || value2.Count == 0)
			{
				return false;
			}
			Attach(play, value2.Dequeue());
			if (value2.Count == 0)
			{
				PendingLedgers.Remove(play.Card);
			}
			return true;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Specifies the payment role of a secondary-resource card-play use.</para>
	///     <para xml:lang="zh-CN">指定次级资源出牌支付条款的用途。</para>
	/// </summary>
	public enum SecondaryResourceUseKind
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Represents a required payment that prevents card play when it cannot be satisfied, unless its
		///         insufficient-payment policy permits the shortfall.
		///     </para>
		///     <para xml:lang="zh-CN">表示一项必需支付；无法满足时会阻止出牌，除非资源不足支付策略允许该缺口。</para>
		/// </summary>
		RequiredCost,
		/// <summary>
		///     <para xml:lang="en">
		///         Represents an optional payment that activates when it can be paid and never prevents card play.
		///     </para>
		///     <para xml:lang="zh-CN">表示一项可选支付；可支付时激活，且永远不会阻止出牌。</para>
		/// </summary>
		OptionalSpend,
		/// <summary>
		///     <para xml:lang="en">
		///         Represents a repeatable extra payment that buys as many complete units as possible after required
		///         payments are reserved.
		///     </para>
		///     <para xml:lang="zh-CN">表示一项可重复额外支付；预留必需支付后，尽可能购买完整的额外支付单位。</para>
		/// </summary>
		ExtraSpend
	}
	/// <summary>
	///     <para xml:lang="en">Describes one secondary-resource payment use attached to a card.</para>
	///     <para xml:lang="zh-CN">描述附加到卡牌上的一项次级资源支付条款。</para>
	/// </summary>
	public sealed record SecondaryResourcePlayUse(string Id, string ResourceId, SecondaryResourceCost Cost, SecondaryResourceUseKind Kind)
	{
		/// <summary>
		///     <para xml:lang="en">Gets the duration of the active layer that produced this descriptor.</para>
		///     <para xml:lang="zh-CN">获取生成该描述的当前生效层的持续时间。</para>
		/// </summary>
		public SecondaryResourceCostDuration Duration { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the persistent baseline cost used for display-color comparison, or the active cost when no
		///         persistent layer exists.
		///     </para>
		///     <para xml:lang="zh-CN">获取用于比较显示颜色的持续生效基础费用；没有持续生效层时则为当前费用。</para>
		/// </summary>
		public SecondaryResourceCost BaseCost { get; init; } = Cost;

		/// <summary>
		///     <para xml:lang="en">Gets the optional insufficient-payment policy for this required payment use.</para>
		///     <para xml:lang="zh-CN">获取该必需支付条款专用的可选资源不足支付策略。</para>
		/// </summary>
		public SecondaryResourceInsufficientPayment? InsufficientPayment { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional maximum number of repeatable extra-payment units.</para>
		///     <para xml:lang="zh-CN">获取可重复额外支付单位数的可选上限。</para>
		/// </summary>
		public int? MaxExtraStacks { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets whether this use participates in card-play payment planning.</para>
		///     <para xml:lang="zh-CN">获取该条款是否参与出牌支付规划。</para>
		/// </summary>
		public bool IsMaterial
		{
			get
			{
				if (!Cost.IsMaterial)
				{
					return Kind == SecondaryResourceUseKind.OptionalSpend;
				}
				return true;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Stores layered secondary-resource payment uses attached to one card.</para>
	///     <para xml:lang="zh-CN">存储附加到一张卡牌上的分层次级资源支付条款。</para>
	/// </summary>
	public sealed class SecondaryResourcePlayUseSet
	{
		private readonly Dictionary<string, List<SecondaryResourcePlayUseLayer>> _uses = new Dictionary<string, List<SecondaryResourcePlayUseLayer>>(StringComparer.OrdinalIgnoreCase);

		/// <summary>
		///     <para xml:lang="en">Gets whether at least one active use participates in payment planning.</para>
		///     <para xml:lang="zh-CN">获取是否至少有一项当前条款参与支付规划。</para>
		/// </summary>
		public bool HasUses => _uses.Values.SelectMany((List<SecondaryResourcePlayUseLayer> layers) => layers).Any((SecondaryResourcePlayUseLayer layer) => layer.Use.IsMaterial);

		/// <summary>
		///     <para xml:lang="en">Gets the use identifiers that currently have attached layers.</para>
		///     <para xml:lang="zh-CN">获取当前存在附加层的支付条款标识符。</para>
		/// </summary>
		public IReadOnlyList<string> UseIds
		{
			get
			{
				List<string> list = new List<string>();
				list.AddRange(_uses.Keys.OrderBy<string, string>((string id) => id, StringComparer.Ordinal));
				return new <>z__ReadOnlyList<string>(list);
			}
		}

		internal bool HasLayers => _uses.Count > 0;

		internal bool HasPermanentLayers => _uses.Values.SelectMany((List<SecondaryResourcePlayUseLayer> layers) => layers).Any((SecondaryResourcePlayUseLayer layer) => layer.Duration == SecondaryResourceCostDuration.Permanent);

		/// <summary>
		///     <para xml:lang="en">Occurs after the attached payment uses change.</para>
		///     <para xml:lang="zh-CN">在附加支付条款发生变化后触发。</para>
		/// </summary>
		public event Action? Changed;

		/// <summary>
		///     <para xml:lang="en">Attaches a persistent required payment with a fixed cost.</para>
		///     <para xml:lang="zh-CN">附加一项具有固定费用且持续生效的必需支付。</para>
		/// </summary>
		public SecondaryResourcePlayUseSet Require(string useId, string resourceId, int amount)
		{
			return Require(useId, resourceId, new SecondaryResourceCost(Math.Max(0, amount)));
		}

		/// <summary>
		///     <para xml:lang="en">Attaches a required payment with the specified cost and duration.</para>
		///     <para xml:lang="zh-CN">附加一项具有指定费用及持续时间的必需支付。</para>
		/// </summary>
		public SecondaryResourcePlayUseSet Require(string useId, string resourceId, SecondaryResourceCost cost, SecondaryResourceCostDuration duration = SecondaryResourceCostDuration.Permanent)
		{
			return Set(useId, resourceId, cost, SecondaryResourceUseKind.RequiredCost, duration);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attaches a required payment with an explicit insufficient-payment policy.
		///     </para>
		///     <para xml:lang="zh-CN">附加一项具有显式资源不足支付策略的必需支付。</para>
		/// </summary>
		public SecondaryResourcePlayUseSet Require(string useId, string resourceId, SecondaryResourceCost cost, SecondaryResourceInsufficientPayment insufficientPayment, SecondaryResourceCostDuration duration = SecondaryResourceCostDuration.Permanent)
		{
			return Set(useId, resourceId, cost, SecondaryResourceUseKind.RequiredCost, duration, insufficientPayment);
		}

		/// <summary>
		///     <para xml:lang="en">Attaches a fixed required payment whose shortfall does not prevent card play.</para>
		///     <para xml:lang="zh-CN">附加一项费用缺口不会阻止出牌的固定必需支付。</para>
		/// </summary>
		public SecondaryResourcePlayUseSet RequireAllowingShortfall(string useId, string resourceId, int amount, SecondaryResourceShortfallPaymentHandler? onShortfall = null, bool spendAvailable = true, SecondaryResourceShortfallResolver? resolveShortfall = null)
		{
			return RequireAllowingShortfall(useId, resourceId, new SecondaryResourceCost(Math.Max(0, amount)), onShortfall, spendAvailable, resolveShortfall);
		}

		/// <summary>
		///     <para xml:lang="en">Attaches a required payment whose shortfall does not prevent card play.</para>
		///     <para xml:lang="zh-CN">附加一项费用缺口不会阻止出牌的必需支付。</para>
		/// </summary>
		public SecondaryResourcePlayUseSet RequireAllowingShortfall(string useId, string resourceId, SecondaryResourceCost cost, SecondaryResourceShortfallPaymentHandler? onShortfall = null, bool spendAvailable = true, SecondaryResourceShortfallResolver? resolveShortfall = null, SecondaryResourceCostDuration duration = SecondaryResourceCostDuration.Permanent)
		{
			return Require(useId, resourceId, cost, SecondaryResourceInsufficientPayment.AllowPlay(onShortfall, spendAvailable, resolveShortfall), duration);
		}

		/// <summary>
		///     <para xml:lang="en">Attaches a persistent fixed optional payment that activates only when payable.</para>
		///     <para xml:lang="zh-CN">附加一项持续生效的固定可选支付；仅在可以支付时激活。</para>
		/// </summary>
		public SecondaryResourcePlayUseSet SpendIfAvailable(string useId, string resourceId, int amount)
		{
			return SpendIfAvailable(useId, resourceId, new SecondaryResourceCost(Math.Max(0, amount)));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attaches an optional payment with the specified cost and duration that activates only when payable.
		///     </para>
		///     <para xml:lang="zh-CN">附加一项具有指定费用及持续时间的可选支付；仅在可以支付时激活。</para>
		/// </summary>
		public SecondaryResourcePlayUseSet SpendIfAvailable(string useId, string resourceId, SecondaryResourceCost cost, SecondaryResourceCostDuration duration = SecondaryResourceCostDuration.Permanent)
		{
			return Set(useId, resourceId, cost, SecondaryResourceUseKind.OptionalSpend, duration);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attaches a repeatable extra payment that buys complete units after required payments are reserved.
		///     </para>
		///     <para xml:lang="zh-CN">附加一项可重复额外支付；预留必需支付后按完整单位购买。</para>
		/// </summary>
		public SecondaryResourcePlayUseSet SpendExtra(string useId, string resourceId, int perStackAmount, int? maxStacks = null, SecondaryResourceCostDuration duration = SecondaryResourceCostDuration.Permanent)
		{
			ArgumentOutOfRangeException.ThrowIfNegativeOrZero(perStackAmount, "perStackAmount");
			if (maxStacks.HasValue && maxStacks.GetValueOrDefault() < 0)
			{
				throw new ArgumentOutOfRangeException("maxStacks");
			}
			return Set(useId, resourceId, new SecondaryResourceCost(perStackAmount), SecondaryResourceUseKind.ExtraSpend, duration, null, maxStacks);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets a payment-use descriptor for one use identifier at the specified duration.
		///     </para>
		///     <para xml:lang="zh-CN">为一个支付条款标识符设置具有指定持续时间的条款描述。</para>
		/// </summary>
		public SecondaryResourcePlayUseSet Set(string useId, string resourceId, SecondaryResourceCost cost, SecondaryResourceUseKind kind, SecondaryResourceCostDuration duration = SecondaryResourceCostDuration.Permanent)
		{
			return Set(useId, resourceId, cost, kind, duration, null);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets a payment-use descriptor with the specified duration and insufficient-payment policy.
		///     </para>
		///     <para xml:lang="zh-CN">设置一项具有指定持续时间及资源不足支付策略的支付条款描述。</para>
		/// </summary>
		public SecondaryResourcePlayUseSet Set(string useId, string resourceId, SecondaryResourceCost cost, SecondaryResourceUseKind kind, SecondaryResourceCostDuration duration, SecondaryResourceInsufficientPayment? insufficientPayment)
		{
			return Set(useId, resourceId, cost, kind, duration, insufficientPayment, null);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets a payment-use descriptor with explicit duration, insufficient-payment, and extra-payment
		///         settings.
		///     </para>
		///     <para xml:lang="zh-CN">设置一项具有显式持续时间、资源不足支付及额外支付配置的支付条款描述。</para>
		/// </summary>
		public SecondaryResourcePlayUseSet Set(string useId, string resourceId, SecondaryResourceCost cost, SecondaryResourceUseKind kind, SecondaryResourceCostDuration duration, SecondaryResourceInsufficientPayment? insufficientPayment, int? maxExtraStacks)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(useId, "useId");
			ArgumentException.ThrowIfNullOrWhiteSpace(resourceId, "resourceId");
			ArgumentNullException.ThrowIfNull(cost, "cost");
			if ((object)cost != null && cost.CostsX && cost.XMultiplier <= 0)
			{
				throw new ArgumentOutOfRangeException("cost", "An X secondary-resource cost must have a positive multiplier.");
			}
			if (maxExtraStacks.HasValue && maxExtraStacks.GetValueOrDefault() < 0)
			{
				throw new ArgumentOutOfRangeException("maxExtraStacks");
			}
			if (kind == SecondaryResourceUseKind.ExtraSpend && (object)cost != null && cost.CostsX)
			{
				throw new ArgumentException("Repeatable extra secondary-resource spends cannot use X costs.", "cost");
			}
			string text = useId.Trim();
			string resourceId2 = resourceId.Trim();
			List<SecondaryResourcePlayUseLayer> layers = GetLayers(text);
			layers.RemoveAll((SecondaryResourcePlayUseLayer layer) => layer.Duration == duration);
			layers.Add(new SecondaryResourcePlayUseLayer(new SecondaryResourcePlayUse(text, resourceId2, cost, kind)
			{
				Duration = duration,
				InsufficientPayment = insufficientPayment,
				MaxExtraStacks = maxExtraStacks
			}, duration));
			Changed?.Invoke();
			return this;
		}

		/// <summary>
		///     <para xml:lang="en">Clears every layer for one payment-use identifier.</para>
		///     <para xml:lang="zh-CN">清除一个支付条款标识符的所有附加层。</para>
		/// </summary>
		public bool Clear(string useId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(useId, "useId");
			bool num = _uses.Remove(useId.Trim());
			if (num)
			{
				Action? action = Changed;
				if (action == null)
				{
					return num;
				}
				action();
			}
			return num;
		}

		/// <summary>
		///     <para xml:lang="en">Clears every payment-use layer with the specified duration.</para>
		///     <para xml:lang="zh-CN">清除所有具有指定持续时间的支付条款层。</para>
		/// </summary>
		public bool ClearDuration(SecondaryResourceCostDuration duration)
		{
			bool flag = false;
			string[] array = _uses.Keys.ToArray();
			foreach (string key in array)
			{
				flag |= _uses[key].RemoveAll((SecondaryResourcePlayUseLayer layer) => layer.Duration == duration) > 0;
				if (_uses[key].Count == 0)
				{
					_uses.Remove(key);
				}
			}
			if (flag)
			{
				Changed?.Invoke();
			}
			return flag;
		}

		/// <summary>
		///     <para xml:lang="en">Returns the active payment uses in deterministic role and identifier order.</para>
		///     <para xml:lang="zh-CN">按确定的支付用途及标识符顺序返回当前生效的支付条款。</para>
		/// </summary>
		public IReadOnlyList<SecondaryResourcePlayUse> Snapshot()
		{
			List<SecondaryResourcePlayUse> list = new List<SecondaryResourcePlayUse>();
			list.AddRange((from use in _uses.Select<KeyValuePair<string, List<SecondaryResourcePlayUseLayer>>, SecondaryResourcePlayUse>(delegate(KeyValuePair<string, List<SecondaryResourcePlayUseLayer>> pair)
				{
					List<SecondaryResourcePlayUseLayer> value = pair.Value;
					SecondaryResourcePlayUseLayer secondaryResourcePlayUseLayer = value[value.Count - 1];
					SecondaryResourceCost baseCost = pair.Value.LastOrDefault((SecondaryResourcePlayUseLayer candidate) => candidate.Duration == SecondaryResourceCostDuration.Permanent)?.Use.Cost ?? secondaryResourcePlayUseLayer.Use.Cost;
					return secondaryResourcePlayUseLayer.Use with
					{
						Duration = secondaryResourcePlayUseLayer.Duration,
						BaseCost = baseCost
					};
				})
				where use.IsMaterial
				orderby use.Kind switch
				{
					SecondaryResourceUseKind.RequiredCost => 0, 
					SecondaryResourceUseKind.ExtraSpend => 1, 
					_ => 2, 
				}
				select use).ThenBy<SecondaryResourcePlayUse, string>((SecondaryResourcePlayUse use) => use.Id, StringComparer.Ordinal));
			return new <>z__ReadOnlyList<SecondaryResourcePlayUse>(list);
		}

		internal SecondaryResourcePlayUseSet Clone()
		{
			SecondaryResourcePlayUseSet secondaryResourcePlayUseSet = new SecondaryResourcePlayUseSet();
			foreach (var (key, source) in _uses)
			{
				secondaryResourcePlayUseSet._uses[key] = source.ToList();
			}
			return secondaryResourcePlayUseSet;
		}

		internal bool ResetPermanentLayersFrom(SecondaryResourcePlayUseSet? canonicalUses)
		{
			bool flag = false;
			string[] array = _uses.Keys.ToArray();
			foreach (string key in array)
			{
				flag |= _uses[key].RemoveAll((SecondaryResourcePlayUseLayer layer) => layer.Duration == SecondaryResourceCostDuration.Permanent) > 0;
				if (_uses[key].Count == 0)
				{
					_uses.Remove(key);
				}
			}
			if (canonicalUses != null)
			{
				foreach (var (key2, source) in canonicalUses._uses)
				{
					SecondaryResourcePlayUseLayer[] array2 = source.Where((SecondaryResourcePlayUseLayer layer) => layer.Duration == SecondaryResourceCostDuration.Permanent).ToArray();
					if (array2.Length != 0)
					{
						if (_uses.TryGetValue(key2, out List<SecondaryResourcePlayUseLayer> value))
						{
							value.InsertRange(0, array2);
						}
						else
						{
							_uses[key2] = array2.ToList();
						}
						flag = true;
					}
				}
			}
			if (flag)
			{
				Changed?.Invoke();
			}
			return flag;
		}

		private List<SecondaryResourcePlayUseLayer> GetLayers(string useId)
		{
			if (_uses.TryGetValue(useId, out List<SecondaryResourcePlayUseLayer> value))
			{
				return value;
			}
			value = new List<SecondaryResourcePlayUseLayer>();
			_uses[useId] = value;
			return value;
		}
	}
	internal sealed record SecondaryResourcePlayUseLayer(SecondaryResourcePlayUse Use, SecondaryResourceCostDuration Duration);
	/// <summary>
	///     <para xml:lang="en">Specifies how an underfunded required secondary-resource cost behaves.</para>
	///     <para xml:lang="zh-CN">指定必需的次级资源费用无法足额支付时的行为。</para>
	/// </summary>
	public enum SecondaryResourceInsufficientPaymentMode
	{
		/// <summary>
		///     <para xml:lang="en">Prevents the card from being played.</para>
		///     <para xml:lang="zh-CN">阻止打出卡牌。</para>
		/// </summary>
		BlockPlay,
		/// <summary>
		///     <para xml:lang="en">Allows play and reports the unpaid amount as a shortfall.</para>
		///     <para xml:lang="zh-CN">允许出牌，并将未支付数量报告为缺口。</para>
		/// </summary>
		AllowPlay
	}
	/// <summary>
	///     <para xml:lang="en">Handles a committed card payment with a remaining shortfall.</para>
	///     <para xml:lang="zh-CN">处理已提交且仍有缺口的卡牌支付。</para>
	/// </summary>
	public delegate Task SecondaryResourceShortfallPaymentHandler(SecondaryResourceShortfallContext context);
	/// <summary>
	///     <para xml:lang="en">Plans how much of a shortfall another payment source can cover.</para>
	///     <para xml:lang="zh-CN">规划其他支付来源可补足多少缺口。</para>
	/// </summary>
	public delegate SecondaryResourceShortfallResolution SecondaryResourceShortfallResolver(SecondaryResourceShortfallResolutionContext context);
	/// <summary>
	///     <para xml:lang="en">Describes a side-effect-free replacement-payment plan for a shortfall.</para>
	///     <para xml:lang="zh-CN">描述用于补足缺口的无副作用替代支付方案。</para>
	/// </summary>
	public sealed record SecondaryResourceShortfallResolution
	{
		/// <summary>
		///     <para xml:lang="en">Gets a plan that covers none of the shortfall.</para>
		///     <para xml:lang="zh-CN">获取不补足任何缺口的方案。</para>
		/// </summary>
		public static SecondaryResourceShortfallResolution None { get; } = new SecondaryResourceShortfallResolution();

		/// <summary>
		///     <para xml:lang="en">Gets the amount covered by the replacement payment.</para>
		///     <para xml:lang="zh-CN">获取替代支付补足的数量。</para>
		/// </summary>
		public int CoveredAmount { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional callback that commits the replacement payment.</para>
		///     <para xml:lang="zh-CN">获取提交替代支付的可选回调。</para>
		/// </summary>
		public SecondaryResourceShortfallPaymentHandler? OnCommit { get; init; }

		/// <summary>
		///     <para xml:lang="en">Creates a plan that covers a nonnegative amount of the shortfall.</para>
		///     <para xml:lang="zh-CN">创建补足非负缺口数量的方案。</para>
		/// </summary>
		public static SecondaryResourceShortfallResolution Cover(int amount, SecondaryResourceShortfallPaymentHandler? onCommit = null)
		{
			return new SecondaryResourceShortfallResolution
			{
				CoveredAmount = Math.Max(0, amount),
				OnCommit = onCommit
			};
		}

		internal Task Commit(SecondaryResourceShortfallContext context)
		{
			if (OnCommit == null)
			{
				return Task.CompletedTask;
			}
			return OnCommit(context) ?? throw new InvalidOperationException("A shortfall replacement-payment handler returned null.");
		}
	}
	/// <summary>
	///     <para xml:lang="en">Defines behavior for an underfunded required secondary-resource payment.</para>
	///     <para xml:lang="zh-CN">定义必需的次级资源支付无法足额完成时的行为。</para>
	/// </summary>
	public sealed record SecondaryResourceInsufficientPayment
	{
		/// <summary>
		///     <para xml:lang="en">Gets the shared policy that blocks play on a shortfall.</para>
		///     <para xml:lang="zh-CN">获取存在缺口时阻止出牌的共享策略。</para>
		/// </summary>
		public static SecondaryResourceInsufficientPayment BlockPlay { get; } = new SecondaryResourceInsufficientPayment();

		/// <summary>
		///     <para xml:lang="en">Gets the selected behavior for an unpaid amount.</para>
		///     <para xml:lang="zh-CN">获取未支付数量所采用的行为。</para>
		/// </summary>
		public SecondaryResourceInsufficientPaymentMode Mode { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets whether available resource is spent before reporting the remaining shortfall.</para>
		///     <para xml:lang="zh-CN">获取是否先支付可用资源，再报告剩余缺口。</para>
		/// </summary>
		public bool SpendAvailable { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">Gets the optional callback invoked after committing a remaining shortfall.</para>
		///     <para xml:lang="zh-CN">获取提交剩余缺口后调用的可选回调。</para>
		/// </summary>
		public SecondaryResourceShortfallPaymentHandler? OnShortfall { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional side-effect-free replacement-payment planner.</para>
		///     <para xml:lang="zh-CN">获取可选的无副作用替代支付规划器。</para>
		/// </summary>
		public SecondaryResourceShortfallResolver? ResolveShortfall { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets whether card-play checks may pass despite a shortfall.</para>
		///     <para xml:lang="zh-CN">获取存在缺口时是否仍可通过出牌检查。</para>
		/// </summary>
		public bool AllowsPlay => Mode == SecondaryResourceInsufficientPaymentMode.AllowPlay;

		/// <summary>
		///     <para xml:lang="en">Creates a policy that permits play with an underfunded required cost.</para>
		///     <para xml:lang="zh-CN">创建允许在必需费用不足时出牌的策略。</para>
		/// </summary>
		public static SecondaryResourceInsufficientPayment AllowPlay(SecondaryResourceShortfallPaymentHandler? onShortfall = null, bool spendAvailable = true, SecondaryResourceShortfallResolver? resolveShortfall = null)
		{
			return new SecondaryResourceInsufficientPayment
			{
				Mode = SecondaryResourceInsufficientPaymentMode.AllowPlay,
				SpendAvailable = spendAvailable,
				OnShortfall = onShortfall,
				ResolveShortfall = resolveShortfall
			};
		}

		/// <summary>
		///     <para xml:lang="en">Creates an allow-play policy with a synchronous shortfall callback.</para>
		///     <para xml:lang="zh-CN">创建带同步缺口回调的允许出牌策略。</para>
		/// </summary>
		public static SecondaryResourceInsufficientPayment AllowPlay(Action<SecondaryResourceShortfallContext> onShortfall, bool spendAvailable = true, SecondaryResourceShortfallResolver? resolveShortfall = null)
		{
			ArgumentNullException.ThrowIfNull(onShortfall, "onShortfall");
			return AllowPlay(delegate(SecondaryResourceShortfallContext context)
			{
				onShortfall(context);
				return Task.CompletedTask;
			}, spendAvailable, resolveShortfall);
		}

		/// <summary>
		///     <para xml:lang="en">Creates an allow-play policy that first plans a replacement payment.</para>
		///     <para xml:lang="zh-CN">创建优先规划替代支付的允许出牌策略。</para>
		/// </summary>
		public static SecondaryResourceInsufficientPayment AllowPlayWithReplacement(SecondaryResourceShortfallResolver resolveShortfall, SecondaryResourceShortfallPaymentHandler? onRemainingShortfall = null, bool spendAvailable = true)
		{
			ArgumentNullException.ThrowIfNull(resolveShortfall, "resolveShortfall");
			return AllowPlay(onRemainingShortfall, spendAvailable, resolveShortfall);
		}

		internal Task InvokeShortfall(SecondaryResourceShortfallContext context)
		{
			if (OnShortfall == null)
			{
				return Task.CompletedTask;
			}
			return OnShortfall(context) ?? throw new InvalidOperationException("A remaining-shortfall payment handler returned null.");
		}

		internal SecondaryResourceShortfallResolution Resolve(SecondaryResourceShortfallResolutionContext context)
		{
			if (ResolveShortfall == null)
			{
				return SecondaryResourceShortfallResolution.None;
			}
			return ResolveShortfall(context) ?? throw new InvalidOperationException("A shortfall replacement-payment resolver returned null.");
		}
	}
	/// <summary>
	///     <para xml:lang="en">Specifies the persistence scope of a secondary combat resource.</para>
	///     <para xml:lang="zh-CN">指定次级战斗资源的持久化范围。</para>
	/// </summary>
	public enum SecondaryResourcePersistencePolicy
	{
		/// <summary>
		///     <para xml:lang="en">Does not write the resource to run saves.</para>
		///     <para xml:lang="zh-CN">不将资源写入一局游戏的存档。</para>
		/// </summary>
		None,
		/// <summary>
		///     <para xml:lang="en">
		///         Includes the resource only in explicitly requested combat-scoped snapshots. Normal run-save
		///         synchronization excludes it.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         仅在显式请求的战斗范围快照中包含资源；常规的一局游戏存档同步会排除该资源。
		///     </para>
		/// </summary>
		Combat,
		/// <summary>
		///     <para xml:lang="en">Persists the resource across combats in the current run.</para>
		///     <para xml:lang="zh-CN">使资源在当前一局游戏中跨战斗持久化。</para>
		/// </summary>
		Run
	}
	/// <summary>
	///     <para xml:lang="en">Specifies built-in turn-start behavior for a secondary resource.</para>
	///     <para xml:lang="zh-CN">指定次级资源的内置回合开始行为。</para>
	/// </summary>
	public enum SecondaryResourceTurnStartPolicy
	{
		/// <summary>
		///     <para xml:lang="en">Leaves the current amount unchanged.</para>
		///     <para xml:lang="zh-CN">保持当前数量不变。</para>
		/// </summary>
		None,
		/// <summary>
		///     <para xml:lang="en">Sets the current amount to the hook-modified maximum.</para>
		///     <para xml:lang="zh-CN">将当前数量设为经钩子修正后的最大数量。</para>
		/// </summary>
		ResetToMax,
		/// <summary>
		///     <para xml:lang="en">Adds the hook-modified maximum to the current amount.</para>
		///     <para xml:lang="zh-CN">将经钩子修正后的最大数量加到当前数量。</para>
