	/// <summary>
	///     <para xml:lang="en">
	///         Routes runtime updates to attached secondary-resource UI nodes and isolates failures in their
	///         display-only callbacks.
	///     </para>
	///     <para xml:lang="zh-CN">将运行时更新分发到已挂载的次级资源界面节点，并隔离其纯显示回调中的错误。</para>
	/// </summary>
	public static class SecondaryResourceUiRuntime
	{
		private static readonly Lock CallbackFailureSync = new Lock();

		private static readonly HashSet<Delegate> LoggedCallbackFailures = new HashSet<Delegate>();

		private static readonly AttachedState<Node, List<Action<Player?>>> CombatUpdaters = new AttachedState<Node, List<Action<Player>>>(() => new List<Action<Player>>());

		private static readonly AttachedState<Node, List<Action<SecondaryResourceChangeContext>>> CombatChangeHandlers = new AttachedState<Node, List<Action<SecondaryResourceChangeContext>>>(() => new List<Action<SecondaryResourceChangeContext>>());

		private static readonly AttachedState<Node, List<Action>> CombatHiders = new AttachedState<Node, List<Action>>(() => new List<Action>());

		private static readonly AttachedState<Node, List<Action<CardModel, PileType, CardPreviewMode>>> CardUpdaters = new AttachedState<Node, List<Action<CardModel, PileType, CardPreviewMode>>>(() => new List<Action<CardModel, PileType, CardPreviewMode>>());

		private static readonly AttachedState<Node, List<Action>> MultiplayerPlayerStateUpdaters = new AttachedState<Node, List<Action>>(() => new List<Action>());

		private static readonly AttachedState<Node, List<Action>> MultiplayerPlayerStateHiders = new AttachedState<Node, List<Action>>(() => new List<Action>());

		private static readonly AttachedState<NMultiplayerPlayerState, bool> MultiplayerPlayerStateCombatActive = new AttachedState<NMultiplayerPlayerState, bool>();

		/// <summary>
		///     <para xml:lang="en">Updates every secondary-resource combat UI attachment under a parent node.</para>
		///     <para xml:lang="zh-CN">更新一个父节点下的所有次级资源战斗界面挂载项。</para>
		/// </summary>
		public static void UpdateCombatUi(Node parent, Player? player)
		{
			ArgumentNullException.ThrowIfNull(parent, "parent");
			if (ModSecondaryResourceRegistry.HasAny && CombatUpdaters.TryGetValue(parent, out List<Action<Player>> value))
			{
				Action<Player>[] array = value.ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					array[i](player);
				}
			}
		}

		internal static void UpdateCurrentCombatUi(Player player)
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			if (ModSecondaryResourceRegistry.HasAny && LocalContext.IsMe(player))
			{
				NCombatRoom instance = NCombatRoom.Instance;
				NCombatUi val = ((instance != null) ? instance.Ui : null);
				if (val != null && GodotObject.IsInstanceValid((GodotObject)(object)val))
				{
					UpdateCombatUi((Node)(object)val, player);
				}
			}
		}

		internal static void NotifyCurrentCombatUiChanged(SecondaryResourceChangeContext change)
		{
			if (ModSecondaryResourceRegistry.HasAny && LocalContext.IsMe(change.Player))
			{
				NCombatRoom instance = NCombatRoom.Instance;
				NCombatUi val = ((instance != null) ? instance.Ui : null);
				if (val != null && GodotObject.IsInstanceValid((GodotObject)(object)val))
				{
					NotifyCombatUiChanged((Node)(object)val, change);
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Notifies every secondary-resource combat UI attachment under a parent after an amount changes.
		///     </para>
		///     <para xml:lang="zh-CN">数量变化后通知一个父节点下的所有次级资源战斗界面挂载项。</para>
		/// </summary>
		public static void NotifyCombatUiChanged(Node parent, SecondaryResourceChangeContext change)
		{
			ArgumentNullException.ThrowIfNull(parent, "parent");
			if (ModSecondaryResourceRegistry.HasAny && CombatChangeHandlers.TryGetValue(parent, out List<Action<SecondaryResourceChangeContext>> value))
			{
				Action<SecondaryResourceChangeContext>[] array = value.ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					array[i](change);
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">Hides every secondary-resource combat UI attachment under a parent node.</para>
		///     <para xml:lang="zh-CN">隐藏一个父节点下的所有次级资源战斗界面挂载项。</para>
		/// </summary>
		public static void HideCombatUi(Node parent)
		{
			ArgumentNullException.ThrowIfNull(parent, "parent");
			if (CombatHiders.TryGetValue(parent, out List<Action> value))
			{
				Action[] array = value.ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					array[i]();
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Updates every secondary-resource card UI attachment under a parent using the default visual context.
		///     </para>
		///     <para xml:lang="zh-CN">使用默认视觉上下文更新一个父节点下的所有次级资源卡牌界面挂载项。</para>
		/// </summary>
		public static void UpdateCardUi(Node parent, CardModel card)
		{
			UpdateCardUi(parent, card, (PileType)0, (CardPreviewMode)1);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Updates every secondary-resource card UI attachment under a parent using the supplied visual
		///         context.
		///     </para>
		///     <para xml:lang="zh-CN">使用提供的视觉上下文更新一个父节点下的所有次级资源卡牌界面挂载项。</para>
		/// </summary>
		public static void UpdateCardUi(Node parent, CardModel card, PileType pileType, CardPreviewMode previewMode)
		{
			//IL_003c: Unknown result type (might be due to invalid IL or missing references)
			//IL_003d: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(parent, "parent");
			ArgumentNullException.ThrowIfNull(card, "card");
			if (ModSecondaryResourceRegistry.HasAny && CardUpdaters.TryGetValue(parent, out List<Action<CardModel, PileType, CardPreviewMode>> value))
			{
				Action<CardModel, PileType, CardPreviewMode>[] array = value.ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					array[i](card, pileType, previewMode);
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Updates every secondary-resource UI attachment on one multiplayer player-state display.
		///     </para>
		///     <para xml:lang="zh-CN">更新一个多人玩家状态栏上的所有次级资源界面挂载项。</para>
		/// </summary>
		public static void UpdateMultiplayerPlayerStateUi(NMultiplayerPlayerState parent)
		{
			ArgumentNullException.ThrowIfNull(parent, "parent");
			if (!ModSecondaryResourceRegistry.HasAny || !MultiplayerPlayerStateUpdaters.TryGetValue((Node)(object)parent, out List<Action> value))
			{
				return;
			}
			if (!MultiplayerPlayerStateCombatActive.TryGetValue(parent, out var value2) || !value2)
			{
				HideMultiplayerPlayerStateUi(parent);
				return;
			}
			Action[] array = value.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				array[i]();
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Marks whether a multiplayer player-state display is currently showing combat resources.
		///     </para>
		///     <para xml:lang="zh-CN">标记多人玩家状态栏当前是否应显示战斗资源。</para>
		/// </summary>
		public static void SetMultiplayerPlayerStateCombatActive(NMultiplayerPlayerState parent, bool active)
		{
			ArgumentNullException.ThrowIfNull(parent, "parent");
			MultiplayerPlayerStateCombatActive.Set(parent, active);
			if (!active)
			{
				HideMultiplayerPlayerStateUi(parent);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Hides every secondary-resource UI attachment on one multiplayer player-state display.
		///     </para>
		///     <para xml:lang="zh-CN">隐藏一个多人玩家状态栏上的所有次级资源界面挂载项。</para>
		/// </summary>
		public static void HideMultiplayerPlayerStateUi(NMultiplayerPlayerState parent)
		{
			ArgumentNullException.ThrowIfNull(parent, "parent");
			if (MultiplayerPlayerStateHiders.TryGetValue((Node)(object)parent, out List<Action> value))
			{
				Action[] array = value.ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					array[i]();
				}
			}
		}

		internal static void RegisterCombatUpdater<TParent, TNode>(TParent parent, TNode node, Action<SecondaryResourceCombatUiContext<TParent, TNode>> update, SecondaryResourceCombatUiChangedHandler<TParent, TNode>? changed = null) where TParent : Node where TNode : Node
		{
			SecondaryResourceCombatUiStateTracker.Ensure((Node)(object)parent);
			CombatHiders.GetOrCreate((Node)(object)parent).Add(delegate
			{
				HideNode((Node)(object)node);
			});
			CombatUpdaters.GetOrCreate((Node)(object)parent).Add(delegate(Player? player)
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)parent) && GodotObject.IsInstanceValid((GodotObject)(object)node))
				{
					SecondaryResourceDefinition[] definitionsSnapshot = ModSecondaryResourceRegistry.GetDefinitionsSnapshot();
					SecondaryResourceCombatUiContext<TParent, TNode> context = new SecondaryResourceCombatUiContext<TParent, TNode>(parent, node, player, definitionsSnapshot, SecondaryResourceVisibility.GetCombatUiDefinitions(player, retainMaterialVisibility: true));
					InvokeCallback(update, "combat UI update", delegate
					{
						update(context);
					});
				}
			});
			if (changed == null)
			{
				return;
			}
			CombatChangeHandlers.GetOrCreate((Node)(object)parent).Add(delegate(SecondaryResourceChangeContext change)
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)parent) && GodotObject.IsInstanceValid((GodotObject)(object)node))
				{
					SecondaryResourceDefinition[] definitionsSnapshot = ModSecondaryResourceRegistry.GetDefinitionsSnapshot();
					SecondaryResourceCombatUiChangeContext<TParent, TNode> context = new SecondaryResourceCombatUiChangeContext<TParent, TNode>(parent, node, change, definitionsSnapshot, SecondaryResourceVisibility.GetCombatUiDefinitions(change.Player, retainMaterialVisibility: true));
					InvokeCallback(changed, "combat UI change", delegate
					{
						changed(context);
					});
				}
			});
		}

		internal static void RegisterCardUpdater<TParent, TNode>(TParent parent, TNode node, Action<SecondaryResourceCardUiContext<TParent, TNode>> update) where TParent : Node where TNode : Node
		{
			CardUpdaters.GetOrCreate((Node)(object)parent).Add(delegate(CardModel card, PileType pileType, CardPreviewMode previewMode)
			{
				//IL_005a: Unknown result type (might be due to invalid IL or missing references)
				//IL_005b: Unknown result type (might be due to invalid IL or missing references)
				if (GodotObject.IsInstanceValid((GodotObject)(object)parent) && GodotObject.IsInstanceValid((GodotObject)(object)node))
				{
					SecondaryResourcePaymentPlan plan = SecondaryResourcePaymentResolver.Plan(card, SecondaryResourcePaymentFreeMode.FromCardCostScope(FreePlayBindingRegistry.ResolveCardCostScopeForUpcomingPlay(card)));
					SecondaryResourceDefinition[] definitionsSnapshot = ModSecondaryResourceRegistry.GetDefinitionsSnapshot();
					SecondaryResourceCardUiContext<TParent, TNode> context = new SecondaryResourceCardUiContext<TParent, TNode>(parent, node, card, plan, pileType, previewMode, definitionsSnapshot, SecondaryResourceVisibility.GetCardUiDefinitions(card, plan));
					InvokeCallback(update, "card UI update", delegate
					{
						update(context);
					});
				}
			});
		}

		internal static void RegisterMultiplayerPlayerStateUpdater<TNode>(NMultiplayerPlayerState parent, TNode node, Action<SecondaryResourceMultiplayerPlayerStateUiContext<TNode>> update) where TNode : Node
		{
			MultiplayerPlayerStateHiders.GetOrCreate((Node)(object)parent).Add(delegate
			{
				HideNode((Node)(object)node);
			});
			MultiplayerPlayerStateUpdaters.GetOrCreate((Node)(object)parent).Add(delegate
			{
				if (GodotObject.IsInstanceValid((GodotObject)(object)parent) && GodotObject.IsInstanceValid((GodotObject)(object)node))
				{
					SecondaryResourceDefinition[] definitionsSnapshot = ModSecondaryResourceRegistry.GetDefinitionsSnapshot();
					SecondaryResourceMultiplayerPlayerStateUiContext<TNode> context = new SecondaryResourceMultiplayerPlayerStateUiContext<TNode>(parent, node, parent.Player, definitionsSnapshot, SecondaryResourceVisibility.GetCombatUiDefinitions(parent.Player));
					InvokeCallback(update, "multiplayer player-state UI update", delegate
					{
						update(context);
					});
				}
			});
		}

		private static void HideNode(Node node)
		{
			if (GodotObject.IsInstanceValid((GodotObject)(object)node))
			{
				CanvasItem val = (CanvasItem)(object)((node is CanvasItem) ? node : null);
				if (val != null)
				{
					val.Visible = false;
				}
			}
		}

		private static void InvokeCallback(Delegate callback, string surface, Action action)
		{
			try
			{
				action();
			}
			catch (Exception value)
			{
				using (CallbackFailureSync.EnterScope())
				{
					if (!LoggedCallbackFailures.Add(callback))
					{
						return;
					}
				}
				RitsuLibFramework.Logger.Warn($"[SecondaryResource] Registered {surface} callback failed: {value}", 1);
			}
		}
	}
	internal class SecondaryResourceCombatUiStateTracker : Node
	{
