	/// <summary>
	///     <para xml:lang="en">Provides data for secondary-resource combat UI visibility.</para>
	///     <para xml:lang="zh-CN">提供判断次级资源战斗界面可见性时使用的数据。</para>
	/// </summary>
	public readonly record struct SecondaryResourceCombatVisibilityContext(Player Player, SecondaryResourceDefinition Definition, int Amount, int? MaxAmount);
	/// <summary>
	///     <para xml:lang="en">Provides data for secondary-resource card UI visibility.</para>
	///     <para xml:lang="zh-CN">提供判断次级资源卡牌界面可见性时使用的数据。</para>
	/// </summary>
	public readonly record struct SecondaryResourceCardVisibilityContext(CardModel Card, SecondaryResourceDefinition Definition, SecondaryResourcePaymentLine? PaymentLine);
	/// <summary>
	///     <para xml:lang="en">Determines whether a secondary resource should be visible in the combat UI.</para>
	///     <para xml:lang="zh-CN">判断次级资源是否应显示在战斗界面中。</para>
	/// </summary>
	public delegate bool SecondaryResourceCombatUiVisibilityPredicate(SecondaryResourceCombatVisibilityContext context);
	/// <summary>
	///     <para xml:lang="en">Resolves secondary-resource visibility in combat and card UI.</para>
	///     <para xml:lang="zh-CN">解析次级资源在战斗界面和卡牌界面中的可见性。</para>
	/// </summary>
	public static class SecondaryResourceVisibility
	{
		private static readonly Lock PredicateFailureSync = new Lock();

		private static readonly HashSet<SecondaryResourceCombatUiVisibilityPredicate> LoggedPredicateFailures = new HashSet<SecondaryResourceCombatUiVisibilityPredicate>();

		private static readonly AttachedState<PlayerCombatState, HashSet<string>> CombatUiSeenMaterialResources = new AttachedState<PlayerCombatState, HashSet<string>>(() => new HashSet<string>(StringComparer.OrdinalIgnoreCase));

		/// <summary>
		///     <para xml:lang="en">Returns resource definitions visible for the current combat UI update.</para>
		///     <para xml:lang="zh-CN">返回当前战斗界面更新中可见的资源定义。</para>
		/// </summary>
		public static IReadOnlyList<SecondaryResourceDefinition> GetCombatUiDefinitions(Player? player)
		{
			return GetCombatUiDefinitions(player, retainMaterialVisibility: false);
		}

		internal static IReadOnlyList<SecondaryResourceDefinition> GetCombatUiDefinitions(Player? player, bool retainMaterialVisibility)
		{
			if (!ModSecondaryResourceRegistry.HasAny)
			{
				return Array.Empty<SecondaryResourceDefinition>();
			}
			SecondaryResourceDefinition[] definitionsSnapshot = ModSecondaryResourceRegistry.GetDefinitionsSnapshot();
			if (player == null)
			{
				return Array.Empty<SecondaryResourceDefinition>();
			}
			List<SecondaryResourceDefinition> list = new List<SecondaryResourceDefinition>();
			list.AddRange(definitionsSnapshot.Where((SecondaryResourceDefinition definition) => IsVisibleInCombatUi(definition, player, retainMaterialVisibility)));
			return new <>z__ReadOnlyList<SecondaryResourceDefinition>(list);
		}

		internal static bool IsVisibleInCombatUi(SecondaryResourceDefinition definition, Player player)
		{
			return IsVisibleInCombatUi(definition, player, retainMaterialVisibility: false);
		}

		private static bool IsVisibleInCombatUi(SecondaryResourceDefinition definition, Player player, bool retainMaterialVisibility)
		{
			ArgumentNullException.ThrowIfNull(definition, "definition");
			ArgumentNullException.ThrowIfNull(player, "player");
			SecondaryResourceCombatVisibilityContext context = new SecondaryResourceCombatVisibilityContext(player, definition, SecondaryResourceCmd.Get(player, definition.Id), SecondaryResourceCmd.GetMax(player, definition.Id));
			SecondaryResourceCombatUiVisibilityPredicate[] combatUiVisibilityPredicates = ModSecondaryResourceRegistry.GetCombatUiVisibilityPredicates(definition.Id);
			foreach (SecondaryResourceCombatUiVisibilityPredicate secondaryResourceCombatUiVisibilityPredicate in combatUiVisibilityPredicates)
			{
				try
				{
					if (secondaryResourceCombatUiVisibilityPredicate(context))
					{
						return true;
					}
				}
				catch (Exception exception)
				{
					LogPredicateFailureOnce(definition.Id, secondaryResourceCombatUiVisibilityPredicate, exception);
				}
			}
			if (context.Amount > definition.DefaultAmount)
			{
				if (retainMaterialVisibility && player.PlayerCombatState != null)
				{
					CombatUiSeenMaterialResources.GetOrCreate(player.PlayerCombatState).Add(definition.Id);
				}
				return true;
			}
			if (retainMaterialVisibility && player.PlayerCombatState != null)
			{
				return CombatUiSeenMaterialResources.GetOrCreate(player.PlayerCombatState).Contains(definition.Id);
			}
			return false;
		}

		private static void LogPredicateFailureOnce(string resourceId, SecondaryResourceCombatUiVisibilityPredicate predicate, Exception exception)
		{
			using (PredicateFailureSync.EnterScope())
			{
				if (!LoggedPredicateFailures.Add(predicate))
				{
					return;
				}
			}
			RitsuLibFramework.Logger.Warn($"[SecondaryResource] Combat UI visibility predicate for '{resourceId}' failed: {exception}", 1);
		}

		/// <summary>
		///     <para xml:lang="en">Returns definitions with payment lines visible on <paramref name="card" />.</para>
		///     <para xml:lang="zh-CN">返回在 <paramref name="card" /> 上有可见支付条目的资源定义。</para>
		/// </summary>
		public static IReadOnlyList<SecondaryResourceDefinition> GetCardUiDefinitions(CardModel card, SecondaryResourcePaymentPlan plan)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			ArgumentNullException.ThrowIfNull(plan, "plan");
			if (!ModSecondaryResourceRegistry.HasAny)
			{
				return Array.Empty<SecondaryResourceDefinition>();
			}
			Dictionary<string, SecondaryResourcePaymentLine> linesByResource = plan.Lines.GroupBy<SecondaryResourcePaymentLine, string>((SecondaryResourcePaymentLine line) => line.ResourceId, StringComparer.OrdinalIgnoreCase).ToDictionary<IGrouping<string, SecondaryResourcePaymentLine>, string, SecondaryResourcePaymentLine>((IGrouping<string, SecondaryResourcePaymentLine> group) => group.Key, (IGrouping<string, SecondaryResourcePaymentLine> group) => group.First(), StringComparer.OrdinalIgnoreCase);
			List<SecondaryResourceDefinition> list = new List<SecondaryResourceDefinition>();
			list.AddRange(from definition in ModSecondaryResourceRegistry.GetDefinitionsSnapshot()
				where definition.IsVisibleOnCard(card, linesByResource.GetValueOrDefault(definition.Id))
				select definition);
			return new <>z__ReadOnlyList<SecondaryResourceDefinition>(list);
		}
	}
}
namespace STS2RitsuLib.Combat.SecondaryResources.Patches
{
	internal sealed class CardModelCanPlaySecondaryResourcesPatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_secondary_resource_can_play";

		public static string Description => "Check secondary-resource affordability in CardModel.CanPlay";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(CardModel), "CanPlay", new Type[2]
				{
					typeof(UnplayableReason).MakeByRefType(),
					typeof(AbstractModel).MakeByRefType()
				})
			};
		}

		public static void Postfix(CardModel __instance, ref bool __result, ref UnplayableReason reason)
		{
			if (__result && ModSecondaryResourceRegistry.HasAny && __instance.HasMaterialSecondaryCosts())
			{
				SecondaryResourcePaymentFreeMode freeMode = SecondaryResourcePaymentFreeMode.FromCardCostScope(FreePlayBindingRegistry.ResolveCardCostScopeForUpcomingPlay(__instance));
				if (!SecondaryResourcePaymentResolver.Plan(__instance, freeMode).IsAffordable)
				{
					reason = (UnplayableReason)((uint)reason | 8u);
					__result = false;
				}
			}
		}
	}
