		public static void Prefix(CardModel __instance, out SecondaryResourcePaymentPlan? __state)
		{
			__state = null;
			if (ModSecondaryResourceRegistry.HasAny && __instance.HasMaterialSecondaryCosts())
			{
				SecondaryResourcePaymentFreeMode freeMode = SecondaryResourcePaymentFreeMode.FromCardCostScope(FreePlayBindingRegistry.ResolveCardCostScopeForUpcomingPlay(__instance));
				SecondaryResourcePaymentPlan secondaryResourcePaymentPlan = SecondaryResourcePaymentResolver.Plan(__instance, freeMode);
				if (secondaryResourcePaymentPlan.HasLines)
				{
					__state = secondaryResourcePaymentPlan;
				}
			}
		}

		public static void Postfix(CardModel __instance, SecondaryResourcePaymentPlan? __state, ref Task<(int, int)> __result)
		{
			if ((object)__state != null && __state.HasLines)
			{
				__result = After(__instance, __state, __result);
			}
		}

		private static async Task<(int, int)> After(CardModel card, SecondaryResourcePaymentPlan plan, Task<(int, int)> original)
		{
			(int, int) resources = await original;
			await SecondaryResourcePaymentResolver.Commit(plan, (AbstractModel?)(object)card);
			return resources;
		}
	}
	internal sealed class CardModelOnPlayWrapperSecondaryResourcesPatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_secondary_resource_on_play_wrapper";

		public static string Description => "Prepare auto-play secondary-resource ledgers and clear until-played costs";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(CardModel), "OnPlayWrapper", new Type[5]
				{
					typeof(PlayerChoiceContext),
					typeof(Creature),
					typeof(bool),
					typeof(ResourceInfo),
					typeof(bool)
				})
			};
		}

		public static void Prefix(CardModel __instance, bool isAutoPlay, out IDisposable? __state)
		{
			__state = null;
			if (!ModSecondaryResourceRegistry.HasAny || !__instance.HasMaterialSecondaryCosts())
			{
				return;
			}
			if (isAutoPlay && !SecondaryResourcePlayLedgerRuntime.HasPending(__instance))
			{
				SecondaryResourcePaymentPlan secondaryResourcePaymentPlan = SecondaryResourcePaymentResolver.Plan(__instance, SecondaryResourcePaymentFreeMode.AllCosts);
				if (secondaryResourcePaymentPlan.HasLines)
				{
					SecondaryResourcePaymentResolver.CommitFree(secondaryResourcePaymentPlan);
				}
			}
			__state = SecondaryResourcePlayLedgerRuntime.BeginPendingScope(__instance);
		}

		public static void Postfix(CardModel __instance, IDisposable? __state, ref Task __result)
		{
			if (ModSecondaryResourceRegistry.HasAny)
			{
				__result = After(__instance, __state, __result);
			}
		}

		private static async Task After(CardModel card, IDisposable? pendingScope, Task original)
		{
			try
			{
				await original;
				card.ClearSecondaryCostsUntilPlayed();
			}
			finally
			{
				pendingScope?.Dispose();
			}
		}
	}
	internal sealed class CardCmdAutoPlaySecondaryResourceXCapturePatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_secondary_resource_auto_play_x_capture";

		public static string Description => "Capture secondary-resource X values during CardCmd.AutoPlay";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(CardCmd), "AutoPlay")
			};
		}

		public static void Prefix(CardModel card, bool skipXCapture, out SecondaryResourcePlayLedger? __state)
		{
			__state = null;
			if (skipXCapture || !ModSecondaryResourceRegistry.HasAny || !card.HasMaterialSecondaryCosts() || SecondaryResourcePlayLedgerRuntime.HasPending(card))
			{
				return;
			}
			object obj = card.CombatState;
			if (obj == null)
			{
				Creature creature = card.Owner.Creature;
				obj = ((creature != null) ? creature.CombatState : null);
			}
			ICombatState val = (ICombatState)obj;
			if (val != null)
			{
				SecondaryResourcePaymentPlan secondaryResourcePaymentPlan = SecondaryResourcePaymentResolver.PlanForCombat(card, val, SecondaryResourcePaymentFreeMode.AutoPlayCapture);
				if (secondaryResourcePaymentPlan.HasLines)
				{
					__state = SecondaryResourcePaymentResolver.CommitAutoPlayCapture(secondaryResourcePaymentPlan);
				}
			}
		}

		public static void Postfix(CardModel card, SecondaryResourcePlayLedger? __state, ref Task __result)
		{
			if (__state != null)
			{
				__result = After(card, __state, __result);
			}
		}

		private static async Task After(CardModel card, SecondaryResourcePlayLedger ledger, Task original)
		{
			try
			{
				await original;
			}
			finally
			{
				SecondaryResourcePlayLedgerRuntime.TryRemovePending(card, ledger);
			}
		}
	}
