	internal sealed class HookAfterSideTurnStartSecondaryResourcesPatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_secondary_resource_turn_start";

		public static string Description => "Apply secondary-resource turn-start policies";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(Hook), "AfterSideTurnStart", new Type[3]
				{
					typeof(ICombatState),
					typeof(CombatSide),
					typeof(IReadOnlyList<Creature>)
				})
			};
		}

		public static void Postfix(CombatSide side, IReadOnlyList<Creature> participants, ref Task __result)
		{
			//IL_0007: Unknown result type (might be due to invalid IL or missing references)
			//IL_0009: Invalid comparison between Unknown and I4
			if (ModSecondaryResourceRegistry.HasAny && (int)side == 1)
			{
				Player[] players = (from creature in participants
					where creature != null && creature.IsPlayer && creature.Player != null
					select creature.Player).Distinct().ToArray();
				__result = After(__result, players);
			}
		}

		private static async Task After(Task original, IReadOnlyList<Player> players)
		{
			await original;
			foreach (Player player in players)
			{
				await SecondaryResourceCmd.ApplyTurnStartPolicies(player);
			}
		}
	}
