			ArgumentNullException.ThrowIfNull(player, "player");
			ValidateMode(mode);
			List<Reward> list = rewards.ToList();
			ValidateChildren(list, player);
			LinkedRewardSet val = new LinkedRewardSet(list, player);
			LinkedRewardSetRuntime.Configure(val, mode);
