		///     <para xml:lang="en">
		///         The instance is a derived linked reward type, or its existing child collection violates the same
		///         constraints as <see cref="M:STS2RitsuLib.Combat.Rewards.LinkedRewardSets.Create(System.Collections.Generic.IEnumerable{MegaCrit.Sts2.Core.Rewards.Reward},MegaCrit.Sts2.Core.Entities.Players.Player,STS2RitsuLib.Combat.Rewards.LinkedRewardSelectionMode)" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         该实例是派生的关联奖励类型，或其现有子奖励集合违反了与 <see cref="M:STS2RitsuLib.Combat.Rewards.LinkedRewardSets.Create(System.Collections.Generic.IEnumerable{MegaCrit.Sts2.Core.Rewards.Reward},MegaCrit.Sts2.Core.Entities.Players.Player,STS2RitsuLib.Combat.Rewards.LinkedRewardSelectionMode)" /> 相同的约束。
		///     </para>
		/// </exception>
		/// <exception cref="T:System.InvalidOperationException">
		///     <para xml:lang="en">Selection has started or the set has already completed.</para>
		///     <para xml:lang="zh-CN">该集合已经开始选择或已经结算完成。</para>
		/// </exception>
		public static LinkedRewardSet Configure(LinkedRewardSet linkedRewardSet, LinkedRewardSelectionMode mode)
		{
			ArgumentNullException.ThrowIfNull(linkedRewardSet, "linkedRewardSet");
			if (((object)linkedRewardSet).GetType() != typeof(LinkedRewardSet))
			{
				throw new ArgumentException("Derived linked reward types own their selection behavior and cannot be configured.", "linkedRewardSet");
			}
			ValidateMode(mode);
			ValidateChildren(linkedRewardSet.Rewards, ((Reward)linkedRewardSet).Player, linkedRewardSet);
			LinkedRewardSetRuntime.Configure(linkedRewardSet, mode);
			return linkedRewardSet;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the configured selection mode. Unconfigured base-game sets return
		///         <see cref="F:STS2RitsuLib.Combat.Rewards.LinkedRewardSelectionMode.ChooseOne" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取已配置的选择模式。未配置的原版集合返回
		///         <see cref="F:STS2RitsuLib.Combat.Rewards.LinkedRewardSelectionMode.ChooseOne" />。
		///     </para>
		/// </summary>
		/// <param name="linkedRewardSet">
		///     <para xml:lang="en">The linked reward set to inspect.</para>
		///     <para xml:lang="zh-CN">要查询的关联奖励集合。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The configured or default selection mode.</para>
		///     <para xml:lang="zh-CN">已配置的选择模式或默认模式。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en"><paramref name="linkedRewardSet" /> is null.</para>
		///     <para xml:lang="zh-CN"><paramref name="linkedRewardSet" /> 为 null。</para>
		/// </exception>
		public static LinkedRewardSelectionMode GetSelectionMode(LinkedRewardSet linkedRewardSet)
		{
			ArgumentNullException.ThrowIfNull(linkedRewardSet, "linkedRewardSet");
			return LinkedRewardSetRuntime.GetMode(linkedRewardSet);
		}

		private static void ValidateChildren(IReadOnlyCollection<Reward> rewards, Player player, LinkedRewardSet? existingSet = null)
		{
			int count = rewards.Count;
			if ((count < 1 || count > 128) ? true : false)
			{
				throw new ArgumentException($"Linked reward sets require between 1 and {128} children.", "rewards");
			}
			HashSet<Reward> hashSet = new HashSet<Reward>(ReferenceEqualityComparer.Instance);
			foreach (Reward reward in rewards)
			{
				ArgumentNullException.ThrowIfNull(reward, "reward");
				if (!hashSet.Add(reward))
				{
					throw new ArgumentException("A linked reward child cannot appear more than once.", "rewards");
				}
				if (reward is LinkedRewardSet)
				{
					throw new ArgumentException("Linked reward sets cannot be nested.", "rewards");
				}
				if (reward.Player != player)
				{
					throw new ArgumentException("Every linked reward child must belong to the linked set's player.", "rewards");
				}
				if (reward.ParentRewardSet != null && reward.ParentRewardSet != existingSet)
				{
					throw new ArgumentException("A reward that already belongs to a linked reward set cannot be reused.", "rewards");
				}
			}
		}

		private static void ValidateMode(LinkedRewardSelectionMode mode)
		{
			if (!Enum.IsDefined(mode))
			{
				throw new ArgumentOutOfRangeException("mode", mode, "Unknown linked reward selection mode.");
			}
		}
	}
	internal static class LinkedRewardSetRuntime
	{
		private sealed class RuntimeState
		{
			internal LinkedRewardSelectionMode Mode { get; set; }

			internal Reward? PendingSelection { get; set; }

			internal bool IsResolving { get; set; }

			internal bool IsCompleted { get; set; }
		}

		private static readonly ConditionalWeakTable<LinkedRewardSet, RuntimeState> States = new ConditionalWeakTable<LinkedRewardSet, RuntimeState>();

		internal static void Configure(LinkedRewardSet linkedRewardSet, LinkedRewardSelectionMode mode)
		{
			RuntimeState value = States.GetValue(linkedRewardSet, (LinkedRewardSet _) => new RuntimeState());
			lock (value)
			{
				if (value.IsResolving || value.IsCompleted)
				{
					throw new InvalidOperationException("A linked reward set cannot be reconfigured after selection has started.");
				}
				value.Mode = mode;
			}
		}

		internal static LinkedRewardSelectionMode GetMode(LinkedRewardSet linkedRewardSet)
		{
			if (!States.TryGetValue(linkedRewardSet, out RuntimeState value))
			{
				return LinkedRewardSelectionMode.ChooseOne;
			}
			return value.Mode;
		}

		internal static bool TryPrepareSelection(LinkedRewardSet linkedRewardSet, Reward selectedReward)
		{
			if (!linkedRewardSet.Rewards.Any((Reward reward) => reward == selectedReward))
			{
				return false;
			}
			RuntimeState value = States.GetValue(linkedRewardSet, (LinkedRewardSet _) => new RuntimeState());
			lock (value)
			{
				if (value.IsResolving || value.IsCompleted)
				{
					return false;
				}
				value.PendingSelection = selectedReward;
				return true;
			}
		}

		internal static bool HasPendingSelection(LinkedRewardSet linkedRewardSet)
		{
			if (States.TryGetValue(linkedRewardSet, out RuntimeState value))
			{
				return value.PendingSelection != null;
			}
			return false;
		}

		internal static async Task<bool> ResolveSelection(LinkedRewardSet linkedRewardSet)
		{
			RuntimeState state = States.GetValue(linkedRewardSet, (LinkedRewardSet _) => new RuntimeState());
			Reward selectedReward;
			LinkedRewardSelectionMode mode;
			lock (state)
			{
				selectedReward = state.PendingSelection ?? throw new InvalidOperationException("A linked reward set was resolved without a pending child selection.");
				state.PendingSelection = null;
				state.IsResolving = true;
				mode = state.Mode;
			}
			bool completed = false;
			try
			{
				completed = mode switch
				{
					LinkedRewardSelectionMode.ChooseOne => await ResolveChooseOne(linkedRewardSet, selectedReward), 
					LinkedRewardSelectionMode.TakeAll => await ResolveTakeAll(linkedRewardSet, selectedReward), 
					_ => throw new ArgumentOutOfRangeException("mode", mode, "Unknown linked reward selection mode."), 
				};
				return completed;
			}
			finally
			{
				lock (state)
				{
					state.IsResolving = false;
					state.IsCompleted |= completed;
				}
			}
		}

		private static async Task<bool> ResolveChooseOne(LinkedRewardSet linkedRewardSet, Reward selectedReward)
		{
			if (!(await SelectDetached(linkedRewardSet, selectedReward)))
			{
				return false;
			}
			linkedRewardSet.RemoveReward(selectedReward);
			foreach (Reward reward in linkedRewardSet.Rewards)
			{
				SkipAndRemove(linkedRewardSet, reward);
			}
			return true;
		}

		private static async Task<bool> ResolveTakeAll(LinkedRewardSet linkedRewardSet, Reward selectedReward)
		{
			List<Reward> list = linkedRewardSet.Rewards.ToList();
			list.Remove(selectedReward);
			list.Insert(0, selectedReward);
			bool receivedAny = false;
			foreach (Reward reward in list)
			{
				bool flag = reward.SuccessfullySelected;
				if (!flag)
				{
					flag = await SelectDetached(linkedRewardSet, reward);
				}
				if (flag)
				{
					reward.ParentRewardSet = null;
					linkedRewardSet.RemoveReward(reward);
					receivedAny = true;
					continue;
				}
				if (!receivedAny)
				{
					return false;
				}
				SkipAndRemove(linkedRewardSet, reward);
			}
			return true;
		}

		private static async Task<bool> SelectDetached(LinkedRewardSet linkedRewardSet, Reward reward)
		{
			reward.ParentRewardSet = null;
			try
			{
				bool num = await reward.SelectUnsynchronized();
				if (!num)
				{
					reward.ParentRewardSet = linkedRewardSet;
				}
				return num;
			}
			catch
			{
				reward.ParentRewardSet = linkedRewardSet;
				throw;
			}
		}

		private static void SkipAndRemove(LinkedRewardSet linkedRewardSet, Reward reward)
		{
			reward.ParentRewardSet = null;
			if (!reward.SuccessfullySelected)
			{
				reward.OnSkipped();
			}
			linkedRewardSet.RemoveReward(reward);
		}
	}
