		private static Texture2D? TryLoadIcon(string iconPath)
		{
			try
			{
				return (Texture2D?)(object)PreloadManager.Cache.GetCompressedTexture2D(iconPath);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Debug($"[RitsuLib] Custom reward icon was not preloaded, trying ResourceLoader: {iconPath} ({ex.Message})", 1);
			}
			try
			{
				return ResourceLoader.Load<Texture2D>(iconPath, (string)null, (CacheMode)1);
			}
			catch (Exception ex2)
			{
				RitsuLibFramework.Logger.Warn("[RitsuLib] Failed to load custom reward icon '" + iconPath + "': " + ex2.Message, 1);
				return null;
			}
		}
	}
	/// <summary>
