	///     <para xml:lang="zh-CN">描述已注册的自定义奖励类型。</para>
	/// </summary>
	/// <param name="ModId">
	///     <para xml:lang="en">The ID of the owning mod, or an empty string for a global registration.</para>
	///     <para xml:lang="zh-CN">所属模组的 ID；全局注册时为空字符串。</para>
	/// </param>
	/// <param name="Id">
	///     <para xml:lang="en">The normalized reward ID.</para>
	///     <para xml:lang="zh-CN">规范化后的奖励 ID。</para>
	/// </param>
	/// <param name="RewardType">
	///     <para xml:lang="en">The dynamic or native reward type assigned to the registration.</para>
	///     <para xml:lang="zh-CN">分配给该注册项的动态或原版奖励类型。</para>
	/// </param>
	public sealed record ModRewardDefinition(string ModId, string Id, RewardType RewardType)
	{
		[CompilerGenerated]
		public void Deconstruct(out string ModId, out string Id, out RewardType RewardType)
		{
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			//IL_0018: Expected I4, but got Unknown
			ModId = this.ModId;
			Id = this.Id;
			RewardType = (RewardType)(int)this.RewardType;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Registers custom reward types for a mod. Prefer <see cref="M:STS2RitsuLib.Combat.Rewards.ModRewardRegistry.RegisterOwned(System.String,STS2RitsuLib.Combat.Rewards.ModRewardRegistry.ModRewardFactory)" /> so reward IDs follow the
	///         same <c>MODID_REWARD_LOCAL</c> convention as other RitsuLib dynamic IDs.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         为模组注册自定义奖励类型。建议使用 <see cref="M:STS2RitsuLib.Combat.Rewards.ModRewardRegistry.RegisterOwned(System.String,STS2RitsuLib.Combat.Rewards.ModRewardRegistry.ModRewardFactory)" />，使奖励 ID 与其他 RitsuLib
	///         动态 ID 一样遵循 <c>MODID_REWARD_LOCAL</c> 约定。
	///     </para>
	/// </summary>
	public sealed class ModRewardRegistry
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Rebuilds a custom reward from saved reward data and an optional mod-owned JSON payload.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         根据已保存的奖励数据和可选的模组 JSON 载荷重建自定义奖励。
		///     </para>
		/// </summary>
		/// <param name="save">
		///     <para xml:lang="en">The base game's saved reward data.</para>
		///     <para xml:lang="zh-CN">原版保存的奖励数据。</para>
		/// </param>
		/// <param name="player">
		///     <para xml:lang="en">The player who owns the reward.</para>
		///     <para xml:lang="zh-CN">拥有该奖励的玩家。</para>
		/// </param>
		/// <param name="json">
		///     <para xml:lang="en">The optional mod-owned JSON payload.</para>
		///     <para xml:lang="zh-CN">由模组维护的可选 JSON 载荷。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The rebuilt reward. The factory must not return <see langword="null" />.</para>
		///     <para xml:lang="zh-CN">重建后的奖励。工厂不得返回 <see langword="null" />。</para>
		/// </returns>
		public delegate Reward ModRewardFactory(SerializableReward save, Player player, string? json);

		/// <summary>
		///     <para xml:lang="en">
		///         Rebuilds a custom reward from saved reward data and a deserialized mod-owned payload.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         根据已保存的奖励数据和反序列化后的模组载荷重建自定义奖励。
		///     </para>
		/// </summary>
		/// <typeparam name="TPayload">
		///     <para xml:lang="en">The payload type.</para>
		///     <para xml:lang="zh-CN">载荷类型。</para>
		/// </typeparam>
		/// <param name="save">
		///     <para xml:lang="en">The base game's saved reward data.</para>
		///     <para xml:lang="zh-CN">原版保存的奖励数据。</para>
		/// </param>
		/// <param name="player">
		///     <para xml:lang="en">The player who owns the reward.</para>
		///     <para xml:lang="zh-CN">拥有该奖励的玩家。</para>
		/// </param>
		/// <param name="payload">
		///     <para xml:lang="en">
		///         The deserialized payload, or its default value when no payload was saved.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         反序列化后的载荷；未保存载荷时为该类型的默认值。
		///     </para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The rebuilt reward. The factory must not return <see langword="null" />.</para>
		///     <para xml:lang="zh-CN">重建后的奖励。工厂不得返回 <see langword="null" />。</para>
		/// </returns>
		public delegate Reward ModRewardFactory<TPayload>(SerializableReward save, Player player, TPayload? payload);

		private sealed record RewardRegistration(string? RewardId, RewardType RewardType, ModRewardFactory Factory)
		{
			[CompilerGenerated]
			public void Deconstruct(out string? RewardId, out RewardType RewardType, out ModRewardFactory Factory)
			{
				//IL_000a: Unknown result type (might be due to invalid IL or missing references)
				//IL_0010: Expected I4, but got Unknown
				RewardId = this.RewardId;
				RewardType = (RewardType)(int)this.RewardType;
				Factory = this.Factory;
			}
		}

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, ModRewardRegistry> Registries = new Dictionary<string, ModRewardRegistry>(StringComparer.OrdinalIgnoreCase);

		private static readonly Dictionary<string, ModRewardDefinition> Definitions = new Dictionary<string, ModRewardDefinition>(StringComparer.OrdinalIgnoreCase);

		private static readonly Dictionary<RewardType, ModRewardDefinition> DefinitionsByRewardType = new Dictionary<RewardType, ModRewardDefinition>();

		private static readonly Dictionary<RewardType, RewardRegistration> RegistrationsByType = new Dictionary<RewardType, RewardRegistration>();

		private readonly Logger _logger;

		private readonly string _modId;

		private ModRewardRegistry(string modId)
		{
			_modId = modId;
			_logger = RitsuLibFramework.CreateLogger(modId, (LogType)0);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the singleton registry for <paramref name="modId" />, creating it on first use.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 <paramref name="modId" /> 的单例注册表；首次使用时创建。
		///     </para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">The owning mod ID.</para>
		///     <para xml:lang="zh-CN">所属模组的 ID。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The registry for <paramref name="modId" />.</para>
		///     <para xml:lang="zh-CN"><paramref name="modId" /> 的注册表。</para>
		/// </returns>
		public static ModRewardRegistry For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (SyncRoot.EnterScope())
			{
				if (Registries.TryGetValue(modId, out ModRewardRegistry value))
				{
					return value;
				}
				ModRewardRegistry modRewardRegistry = new ModRewardRegistry(modId);
				Registries[modId] = modRewardRegistry;
				return modRewardRegistry;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a reward owned by this registry's mod, using
		///         <see cref="M:STS2RitsuLib.Content.ModContentRegistry.GetQualifiedRewardId(System.String,System.String)" /> to create its qualified ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册归属当前注册表模组的奖励，并使用 <see cref="M:STS2RitsuLib.Content.ModContentRegistry.GetQualifiedRewardId(System.String,System.String)" />
		///         创建其限定 ID。
		///     </para>
		/// </summary>
		/// <param name="localRewardStem">
		///     <para xml:lang="en">The mod-local reward ID stem.</para>
		///     <para xml:lang="zh-CN">模组内使用的奖励 ID 主体。</para>
		/// </param>
		/// <param name="factory">
		///     <para xml:lang="en">The factory used to restore the reward.</para>
		///     <para xml:lang="zh-CN">用于恢复奖励的工厂。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The registered reward definition.</para>
		///     <para xml:lang="zh-CN">已注册的奖励定义。</para>
		/// </returns>
		public ModRewardDefinition RegisterOwned(string localRewardStem, ModRewardFactory factory)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(localRewardStem, "localRewardStem");
			ArgumentNullException.ThrowIfNull(factory, "factory");
			string qualifiedRewardId = ModContentRegistry.GetQualifiedRewardId(_modId, localRewardStem);
			return RegisterCore(_modId, qualifiedRewardId, factory);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a reward owned by this registry's mod. Before calling <paramref name="factory" />,
		///         RitsuLib deserializes the mod-owned payload with source-generated JSON metadata.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册归属当前注册表模组的奖励。调用 <paramref name="factory" /> 前，RitsuLib 会使用源生成的
		///         JSON 元数据反序列化由模组维护的载荷。
		///     </para>
		/// </summary>
		/// <typeparam name="TPayload">
		///     <para xml:lang="en">The payload type.</para>
		///     <para xml:lang="zh-CN">载荷类型。</para>
		/// </typeparam>
		/// <param name="localRewardStem">
		///     <para xml:lang="en">The mod-local reward ID stem.</para>
		///     <para xml:lang="zh-CN">模组内使用的奖励 ID 主体。</para>
		/// </param>
		/// <param name="jsonTypeInfo">
		///     <para xml:lang="en">The source-generated JSON metadata for <typeparamref name="TPayload" />.</para>
		///     <para xml:lang="zh-CN"><typeparamref name="TPayload" /> 的源生成 JSON 元数据。</para>
		/// </param>
		/// <param name="factory">
		///     <para xml:lang="en">The factory used to restore the reward.</para>
		///     <para xml:lang="zh-CN">用于恢复奖励的工厂。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The registered reward definition.</para>
		///     <para xml:lang="zh-CN">已注册的奖励定义。</para>
		/// </returns>
		public ModRewardDefinition RegisterOwned<TPayload>(string localRewardStem, JsonTypeInfo<TPayload> jsonTypeInfo, ModRewardFactory<TPayload> factory)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(localRewardStem, "localRewardStem");
			ArgumentNullException.ThrowIfNull(jsonTypeInfo, "jsonTypeInfo");
			ArgumentNullException.ThrowIfNull(factory, "factory");
			return RegisterOwned(localRewardStem, (SerializableReward save, Player player, string? json) => factory(save, player, DeserializePayload(json, jsonTypeInfo)));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a reward under a raw global ID. Prefer <see cref="M:STS2RitsuLib.Combat.Rewards.ModRewardRegistry.RegisterOwned(System.String,STS2RitsuLib.Combat.Rewards.ModRewardRegistry.ModRewardFactory)" /> for mod-owned IDs.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用原始全局 ID 注册奖励。模组自有 ID 应优先使用 <see cref="M:STS2RitsuLib.Combat.Rewards.ModRewardRegistry.RegisterOwned(System.String,STS2RitsuLib.Combat.Rewards.ModRewardRegistry.ModRewardFactory)" />。
		///     </para>
		/// </summary>
		/// <param name="id">
		///     <para xml:lang="en">The global reward ID.</para>
		///     <para xml:lang="zh-CN">全局奖励 ID。</para>
		/// </param>
		/// <param name="factory">
		///     <para xml:lang="en">The factory used to restore the reward.</para>
		///     <para xml:lang="zh-CN">用于恢复奖励的工厂。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The registered reward definition.</para>
		///     <para xml:lang="zh-CN">已注册的奖励定义。</para>
		/// </returns>
		public static ModRewardDefinition Register(string id, ModRewardFactory factory)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentNullException.ThrowIfNull(factory, "factory");
			return RegisterCore(string.Empty, id, factory);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a reward under a raw global ID. Before calling <paramref name="factory" />, RitsuLib
		///         deserializes the mod-owned payload with source-generated JSON metadata.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用原始全局 ID 注册奖励。调用 <paramref name="factory" /> 前，RitsuLib 会使用源生成的
		///         JSON 元数据反序列化由模组维护的载荷。
		///     </para>
		/// </summary>
		/// <typeparam name="TPayload">
		///     <para xml:lang="en">The payload type.</para>
		///     <para xml:lang="zh-CN">载荷类型。</para>
		/// </typeparam>
		/// <param name="id">
		///     <para xml:lang="en">The global reward ID.</para>
		///     <para xml:lang="zh-CN">全局奖励 ID。</para>
		/// </param>
		/// <param name="jsonTypeInfo">
		///     <para xml:lang="en">The source-generated JSON metadata for <typeparamref name="TPayload" />.</para>
		///     <para xml:lang="zh-CN"><typeparamref name="TPayload" /> 的源生成 JSON 元数据。</para>
		/// </param>
		/// <param name="factory">
		///     <para xml:lang="en">The factory used to restore the reward.</para>
		///     <para xml:lang="zh-CN">用于恢复奖励的工厂。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The registered reward definition.</para>
		///     <para xml:lang="zh-CN">已注册的奖励定义。</para>
		/// </returns>
		public static ModRewardDefinition Register<TPayload>(string id, JsonTypeInfo<TPayload> jsonTypeInfo, ModRewardFactory<TPayload> factory)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			ArgumentNullException.ThrowIfNull(jsonTypeInfo, "jsonTypeInfo");
			ArgumentNullException.ThrowIfNull(factory, "factory");
			return Register(id, (SerializableReward save, Player player, string? json) => factory(save, player, DeserializePayload(json, jsonTypeInfo)));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers or replaces the custom reward factory for an existing <see cref="T:MegaCrit.Sts2.Core.Rewards.RewardType" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为已有的 <see cref="T:MegaCrit.Sts2.Core.Rewards.RewardType" /> 注册或替换自定义奖励工厂。
		///     </para>
		/// </summary>
		/// <param name="rewardType">
		///     <para xml:lang="en">The reward type handled by the factory.</para>
		///     <para xml:lang="zh-CN">由该工厂处理的奖励类型。</para>
		/// </param>
		/// <param name="factory">
		///     <para xml:lang="en">The factory used to restore the reward.</para>
		///     <para xml:lang="zh-CN">用于恢复奖励的工厂。</para>
		/// </param>
		public static void Register(RewardType rewardType, ModRewardFactory factory)
		{
			//IL_001b: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(factory, "factory");
			using (SyncRoot.EnterScope())
			{
				RegistrationsByType[rewardType] = new RewardRegistration(null, rewardType, factory);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Tries to get a registered reward definition by ID.</para>
		///     <para xml:lang="zh-CN">尝试按 ID 获取已注册的奖励定义。</para>
		/// </summary>
		/// <param name="id">
		///     <para xml:lang="en">The reward ID to resolve.</para>
		///     <para xml:lang="zh-CN">要解析的奖励 ID。</para>
		/// </param>
		/// <param name="definition">
		///     <para xml:lang="en">The registered definition when found.</para>
		///     <para xml:lang="zh-CN">找到时返回已注册的定义。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> when the reward is registered; otherwise, <see langword="false" />.</para>
		///     <para xml:lang="zh-CN">奖励已注册时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public static bool TryGet(string id, out ModRewardDefinition definition)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			using (SyncRoot.EnterScope())
			{
				return Definitions.TryGetValue(NormalizeId(id), out definition);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets a registered reward definition by ID.</para>
		///     <para xml:lang="zh-CN">按 ID 获取已注册的奖励定义。</para>
		/// </summary>
		/// <param name="id">
		///     <para xml:lang="en">The reward ID to resolve.</para>
		///     <para xml:lang="zh-CN">要解析的奖励 ID。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The registered reward definition.</para>
		///     <para xml:lang="zh-CN">已注册的奖励定义。</para>
		/// </returns>
		/// <exception cref="T:System.Collections.Generic.KeyNotFoundException">
		///     <para xml:lang="en">No reward is registered under <paramref name="id" />.</para>
		///     <para xml:lang="zh-CN">没有使用 <paramref name="id" /> 注册的奖励。</para>
		/// </exception>
		public static ModRewardDefinition Get(string id)
		{
			if (!TryGet(id, out ModRewardDefinition definition))
			{
				throw new KeyNotFoundException("Reward '" + NormalizeId(id) + "' is not registered.");
			}
			return definition;
		}

		/// <summary>
		///     <para xml:lang="en">Tries to get a registered reward definition by <see cref="T:MegaCrit.Sts2.Core.Rewards.RewardType" />.</para>
		///     <para xml:lang="zh-CN">尝试按 <see cref="T:MegaCrit.Sts2.Core.Rewards.RewardType" /> 获取已注册的奖励定义。</para>
		/// </summary>
		/// <param name="rewardType">
		///     <para xml:lang="en">The dynamic reward type to resolve.</para>
		///     <para xml:lang="zh-CN">要解析的动态奖励类型。</para>
		/// </param>
		/// <param name="definition">
		///     <para xml:lang="en">The registered definition when found.</para>
		///     <para xml:lang="zh-CN">找到时返回已注册的定义。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when the reward type is registered; otherwise, <see langword="false" />
		///         .
		///     </para>
		///     <para xml:lang="zh-CN">奖励类型已注册时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public static bool TryGetByRewardType(RewardType rewardType, out ModRewardDefinition definition)
		{
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			using (SyncRoot.EnterScope())
			{
				return DefinitionsByRewardType.TryGetValue(rewardType, out definition);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets a registered reward definition by <see cref="T:MegaCrit.Sts2.Core.Rewards.RewardType" />.</para>
		///     <para xml:lang="zh-CN">按 <see cref="T:MegaCrit.Sts2.Core.Rewards.RewardType" /> 获取已注册的奖励定义。</para>
		/// </summary>
		/// <param name="rewardType">
		///     <para xml:lang="en">The dynamic reward type to resolve.</para>
		///     <para xml:lang="zh-CN">要解析的动态奖励类型。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The registered reward definition.</para>
		///     <para xml:lang="zh-CN">已注册的奖励定义。</para>
		/// </returns>
		/// <exception cref="T:System.Collections.Generic.KeyNotFoundException">
		///     <para xml:lang="en"><paramref name="rewardType" /> is not a registered mod reward.</para>
		///     <para xml:lang="zh-CN"><paramref name="rewardType" /> 不是已注册的模组奖励。</para>
		/// </exception>
		public static ModRewardDefinition Get(RewardType rewardType)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			//IL_002d: Expected I4, but got Unknown
			if (!TryGetByRewardType(rewardType, out ModRewardDefinition definition))
			{
				throw new KeyNotFoundException($"RewardType '0x{(int)rewardType:X8}' is not a registered mod reward.");
			}
			return definition;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the deterministic dynamic <see cref="T:MegaCrit.Sts2.Core.Rewards.RewardType" /> for a registered or raw reward ID.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取已注册或原始奖励 ID 对应的确定性动态 <see cref="T:MegaCrit.Sts2.Core.Rewards.RewardType" />。
		///     </para>
		/// </summary>
		/// <param name="id">
		///     <para xml:lang="en">The registered or raw reward ID.</para>
		///     <para xml:lang="zh-CN">已注册或原始奖励 ID。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The dynamic reward type derived from <paramref name="id" />.</para>
		///     <para xml:lang="zh-CN">根据 <paramref name="id" /> 派生的动态奖励类型。</para>
		/// </returns>
		public static RewardType GetRewardType(string id)
		{
			//IL_002d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0032: Unknown result type (might be due to invalid IL or missing references)
			//IL_0046: Unknown result type (might be due to invalid IL or missing references)
			//IL_004c: Unknown result type (might be due to invalid IL or missing references)
			ArgumentException.ThrowIfNullOrWhiteSpace(id, "id");
			string text = NormalizeId(id);
			using (SyncRoot.EnterScope())
			{
				if (Definitions.TryGetValue(text, out ModRewardDefinition value))
