		private static ModRewardDefinition RegisterCore(string modId, string id, ModRewardFactory factory)
		{
			//IL_0014: Unknown result type (might be due to invalid IL or missing references)
			//IL_0019: Unknown result type (might be due to invalid IL or missing references)
			//IL_001c: Unknown result type (might be due to invalid IL or missing references)
			//IL_010b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0117: Unknown result type (might be due to invalid IL or missing references)
			//IL_0119: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e1: Unknown result type (might be due to invalid IL or missing references)
			//IL_017a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0185: Expected I4, but got Unknown
			string text = NormalizeId(id);
			RewardType value = DynamicEnumValueRegistry<RewardType>.RegisterWithMintKey(modId, text, GetMintKey(text)).Value;
			ModRewardDefinition modRewardDefinition = new ModRewardDefinition(modId, text, value);
			ModRewardRegistry value3;
			using (SyncRoot.EnterScope())
			{
				if (Definitions.TryGetValue(text, out ModRewardDefinition value2))
				{
					if (!string.Equals(value2.ModId, modRewardDefinition.ModId, StringComparison.OrdinalIgnoreCase))
					{
						throw new InvalidOperationException($"Reward '{text}' is already registered by mod '{value2.ModId}'; mod '{modRewardDefinition.ModId}' cannot re-register it.");
					}
					RegistrationsByType[value2.RewardType] = new RewardRegistration(value2.Id, value2.RewardType, factory);
					return value2;
				}
				Definitions[text] = modRewardDefinition;
				DefinitionsByRewardType[value] = modRewardDefinition;
				RegistrationsByType[value] = new RewardRegistration(text, value, factory);
				Registries.TryGetValue(modId, out value3);
			}
			if (!string.IsNullOrEmpty(modId) && value3 != null)
			{
				value3._logger.Info($"[Rewards] Registered reward: {text} (RewardType=0x{(int)value:X8})", 1);
			}
			return modRewardDefinition;
		}

		private static string NormalizeId(string id)
		{
			return id.Trim();
		}

		private static string GetMintKey(string normalizedId)
		{
			return "reward:" + normalizedId;
		}

		private static TPayload? DeserializePayload<TPayload>(string? json, JsonTypeInfo<TPayload> jsonTypeInfo)
		{
			if (string.IsNullOrWhiteSpace(json))
			{
				return default(TPayload);
			}
			try
			{
				return JsonSerializer.Deserialize(json, jsonTypeInfo);
			}
			catch (JsonException ex)
			{
				RitsuLibFramework.Logger.Warn("[RitsuLib] Custom reward payload JSON deserialize failed: " + ex.Message, 1);
				throw;
			}
			catch (NotSupportedException ex2)
			{
				RitsuLibFramework.Logger.Warn("[RitsuLib] Custom reward payload JSON deserialize not supported: " + ex2.Message, 1);
				throw;
			}
		}
