	///         Stores supplemental reward serialization data. Data is first associated with
	///         <see cref="T:MegaCrit.Sts2.Core.Saves.Runs.SerializableReward" /> instances through a
	///         <see cref="T:System.Runtime.CompilerServices.ConditionalWeakTable`2" />, then persisted in
	///         <see cref="P:MegaCrit.Sts2.Core.Saves.Runs.SerializableRoom.EncounterState" /> under keys prefixed by <see cref="F:STS2RitsuLib.Combat.Rewards.RewardSerializationExt.KeyPrefix" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         存储奖励的补充序列化数据。数据先通过 <see cref="T:System.Runtime.CompilerServices.ConditionalWeakTable`2" />
	///         与 <see cref="T:MegaCrit.Sts2.Core.Saves.Runs.SerializableReward" /> 实例关联，再以带有 <see cref="F:STS2RitsuLib.Combat.Rewards.RewardSerializationExt.KeyPrefix" /> 前缀的键
	///         持久化到 <see cref="P:MegaCrit.Sts2.Core.Saves.Runs.SerializableRoom.EncounterState" />。
	///     </para>
	/// </summary>
	internal static class RewardSerializationExt
	{
		internal const string KeyPrefix = "__mod_reward_ext_";

		private static readonly ConditionalWeakTable<SerializableReward, RewardExtData> ExtTable = new ConditionalWeakTable<SerializableReward, RewardExtData>();

		internal static void SetExtData(SerializableReward reward, RewardExtData data)
		{
			ExtTable.AddOrUpdate(reward, data);
		}

		internal static bool TryGetExtData(SerializableReward reward, out RewardExtData? data)
		{
			if (ExtTable.TryGetValue(reward, out data))
			{
				return true;
			}
			data = null;
			return false;
		}

		internal static string MakeKey(ulong netId, int index)
		{
			return $"{"__mod_reward_ext_"}{netId}_{index}";
		}

		internal static bool TryParseKey(string key, out ulong netId, out int index)
		{
			netId = 0uL;
			index = 0;
			if (!key.StartsWith("__mod_reward_ext_", StringComparison.Ordinal))
			{
				return false;
			}
			ReadOnlySpan<char> span = key.AsSpan("__mod_reward_ext_".Length);
			int num = span.IndexOf('_');
			if (num < 0)
			{
				return false;
			}
			if (ulong.TryParse(span.Slice(0, num), out netId))
			{
				return int.TryParse(span.Slice(num + 1), out index);
			}
			return false;
		}

		internal static string ToJson(RewardExtData data)
		{
			return JsonSerializer.Serialize(data, RewardExtJsonContext.Default.RewardExtData);
		}

		internal static RewardExtData? FromJson(string json)
		{
			try
			{
				return JsonSerializer.Deserialize(json, RewardExtJsonContext.Default.RewardExtData);
			}
			catch (JsonException ex)
			{
				RitsuLibFramework.Logger.Debug("[RitsuLib] Reward ext JSON deserialize failed: " + ex.Message, 1);
				return null;
			}
			catch (NotSupportedException ex2)
			{
				RitsuLibFramework.Logger.Debug("[RitsuLib] Reward ext JSON deserialize not supported: " + ex2.Message, 1);
				return null;
			}
		}

