		private static CardModel? TryResolveCard(string serializedId)
		{
			if (string.IsNullOrWhiteSpace(serializedId))
			{
				Log.Warn("[RitsuLib] Reward.FromSerializable: Ignoring an empty custom card id.", 2);
				return null;
			}
			try
			{
				CardModel byIdOrNull = ModelDb.GetByIdOrNull<CardModel>(ModelId.Deserialize(serializedId));
				if (byIdOrNull == null)
				{
					Log.Warn("[RitsuLib] Reward.FromSerializable: Ignoring unavailable custom card id '" + serializedId + "'.", 2);
				}
				return byIdOrNull;
			}
			catch (JsonException ex)
			{
				LogInvalidCardId(serializedId, ex);
			}
			catch (ArgumentException ex2)
			{
				LogInvalidCardId(serializedId, ex2);
			}
			catch (InvalidCastException ex3)
			{
				LogInvalidCardId(serializedId, ex3);
			}
			return null;
		}

		private static void LogInvalidCardId(string serializedId, Exception ex)
		{
			Log.Warn("[RitsuLib] Reward.FromSerializable: Ignoring invalid custom card id '" + serializedId + "': " + ex.Message, 2);
		}
	}
}
namespace STS2RitsuLib.Combat.Powers
{
	/// <summary>
	///     <para xml:lang="en">
	///         Provides an extensible temporary-power wrapper that applies an internal power and removes the applied
	///         amount when the configured turn duration expires.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         提供可扩展的临时能力包装：应用一个内部能力，并在配置的回合持续时间结束时移除已应用的数值。
	///     </para>
	/// </summary>
	public abstract class ModTemporaryPowerTemplate : ModPowerTemplate, ITemporaryPower
	{
		private delegate Task ApplyInternalPowerInvoker(PlayerChoiceContext choiceContext, Creature target, decimal amount, Creature? applier, CardModel? cardSource, bool silent);

		/// <summary>
		///     <para xml:lang="en">
		///         The reserved dynamic-variable name used to track remaining extra expiry cycles and optionally expose
		///         them to localization as <c>{ExtraTurns}</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         用于记录剩余额外到期周期的保留动态变量名；也可通过 <c>{ExtraTurns}</c> 将其用于本地化文本。
		///     </para>
		/// </summary>
		public const string ExtraTurnCyclesVarName = "ExtraTurns";

		private static readonly MethodInfo ApplyInternalPowerGenericMethod = typeof(ModTemporaryPowerTemplate).GetMethod("ApplyInternalPowerGeneric", BindingFlags.Static | BindingFlags.NonPublic);

		private ApplyInternalPowerInvoker? _cachedInternalPowerInvoker;

		private Type? _cachedInternalPowerType;

		private bool _shouldIgnoreNextInstance;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether the temporary effect applies a positive amount and is presented as a buff. Override
		///         with <see langword="false" /> to invert the applied amount and present the wrapper as a debuff.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取临时效果是否应用正数并显示为增益。重写为 <see langword="false" /> 时会反转应用数值，
		///         并将包装能力显示为减益。
		///     </para>
		/// </summary>
		protected virtual bool IsPositive => true;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether the effect expires at the end of the opposing side's turn instead of the owner's
		///         participating turn.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取效果是否在对方回合结束时到期，而不是在拥有者参与的回合结束时到期。
		///     </para>
		/// </summary>
		protected virtual bool UntilEndOfOtherSideTurn => false;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the number of additional qualifying turn ends to wait before the effect expires. A positive
		///         value also makes each application a separate power instance. Negative values are invalid.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取效果到期前额外等待的有效回合结束次数。值为正数时，每次应用还会创建独立的能力实例。
		///         负数无效。
		///     </para>
		/// </summary>
		protected virtual int LastForXExtraTurns => 0;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets additional dynamic variables for localization. The sequence and its entries must not be
		///         <see langword="null" />, and it must not define <see cref="F:STS2RitsuLib.Combat.Powers.ModTemporaryPowerTemplate.ExtraTurnCyclesVarName" /> because the
		///         template always supplies that variable.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取用于本地化的额外动态变量。序列及其中的项均不得为 <see langword="null" />，且不得定义
		///         <see cref="F:STS2RitsuLib.Combat.Powers.ModTemporaryPowerTemplate.ExtraTurnCyclesVarName" />，因为该变量始终由模板提供。
		///     </para>
		/// </summary>
		protected virtual IEnumerable<DynamicVar> AdditionalCanonicalVars => Array.Empty<DynamicVar>();

		/// <inheritdoc />
		public override PowerType Type
		{
			get
			{
				if (IsPositive)
				{
					return (PowerType)1;
				}
				return (PowerType)2;
			}
		}

		/// <inheritdoc />
		public override PowerStackType StackType => (PowerStackType)1;

		/// <inheritdoc />
		public override bool AllowNegative => true;

		/// <inheritdoc />
		public override PowerInstanceType InstanceType
		{
			get
			{
				if (ValidatedExtraTurnCycles > 0)
				{
					return (PowerInstanceType)1;
				}
				return (PowerInstanceType)0;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or sets the remaining extra expiry cycles stored in
		///         <see cref="F:STS2RitsuLib.Combat.Powers.ModTemporaryPowerTemplate.ExtraTurnCyclesVarName" />. Assigned negative values are clamped to zero.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或设置存储在 <see cref="F:STS2RitsuLib.Combat.Powers.ModTemporaryPowerTemplate.ExtraTurnCyclesVarName" /> 中的剩余额外到期周期。
		///         赋入的负数会被限制为零。
		///     </para>
		/// </summary>
		public int RemainingExtraTurnCycles
		{
			get
			{
				return (int)((PowerModel)this).DynamicVars["ExtraTurns"].BaseValue;
			}
			set
			{
				((PowerModel)this).DynamicVars["ExtraTurns"].BaseValue = Math.Max(value, 0);
			}
		}

		/// <inheritdoc />
		public override LocString Title => OriginModel.ResolveTitleOr(InternallyAppliedPower.Title);

		/// <inheritdoc />
		protected override IEnumerable<IHoverTip> AdditionalHoverTips => ResolveExtraHoverTips();

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the template-controlled canonical variables. The template always defines
		///         <see cref="F:STS2RitsuLib.Combat.Powers.ModTemporaryPowerTemplate.ExtraTurnCyclesVarName" /> and appends <see cref="P:STS2RitsuLib.Combat.Powers.ModTemporaryPowerTemplate.AdditionalCanonicalVars" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取由模板控制的规范变量。模板始终定义 <see cref="F:STS2RitsuLib.Combat.Powers.ModTemporaryPowerTemplate.ExtraTurnCyclesVarName" />，
		///         并在其后追加 <see cref="P:STS2RitsuLib.Combat.Powers.ModTemporaryPowerTemplate.AdditionalCanonicalVars" />。
		///     </para>
		/// </summary>
		protected sealed override IEnumerable<DynamicVar> CanonicalVars => BuildCanonicalVars();

		private int ValidatedExtraTurnCycles
		{
			get
			{
				int lastForXExtraTurns = LastForXExtraTurns;
				if (lastForXExtraTurns < 0)
				{
					throw new InvalidOperationException("LastForXExtraTurns cannot be negative.");
				}
				return lastForXExtraTurns;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the model that granted this temporary power. It is used to resolve the title and any supported
		///         source hover tip.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取授予该临时能力的模型，用于解析标题以及受支持的来源悬停提示。
		///     </para>
		/// </summary>
		public abstract AbstractModel OriginModel { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the internal power whose amount is applied while this temporary wrapper exists.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取在该临时包装存在期间应用其数值的内部能力。
		///     </para>
		/// </summary>
		public abstract PowerModel InternallyAppliedPower { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Suppresses the next application or amount-change callback, matching the base temporary-power
		///         behavior used when an application must not alter the internal power.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         忽略下一次应用或数值变更回调，与原版临时能力在某次应用不应改变内部能力时的行为一致。
		///     </para>
		/// </summary>
		public void IgnoreNextInstance()
		{
			_shouldIgnoreNextInstance = true;
		}

		/// <inheritdoc />
		public override async Task BeforeApplied(Creature target, decimal amount, Creature? applier, CardModel? cardSource)
		{
			if (_shouldIgnoreNextInstance)
			{
				_shouldIgnoreNextInstance = false;
				return;
			}
			if (RemainingExtraTurnCycles == 0)
			{
				RemainingExtraTurnCycles = ValidatedExtraTurnCycles;
			}
			await ApplyInternalPower((PlayerChoiceContext)new ThrowingPlayerChoiceContext(), target, SignedAmount(amount), applier, cardSource, silent: true);
		}

		/// <inheritdoc />
		public override async Task AfterPowerAmountChanged(PlayerChoiceContext choiceContext, PowerModel power, decimal amount, Creature? applier, CardModel? cardSource)
		{
			if (!(amount == (decimal)((PowerModel)this).Amount) && (object)power == this)
			{
				if (_shouldIgnoreNextInstance)
				{
					_shouldIgnoreNextInstance = false;
				}
				else
				{
					await ApplyInternalPower(choiceContext, ((PowerModel)this).Owner, SignedAmount(amount), applier, cardSource, silent: true);
				}
			}
		}

		/// <inheritdoc />
		public override async Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_001f: Unknown result type (might be due to invalid IL or missing references)
			if (UntilEndOfOtherSideTurn)
			{
				if (side == ((PowerModel)this).Owner.Side)
				{
					return;
				}
			}
			else if (!participants.Contains(((PowerModel)this).Owner))
			{
				return;
			}
			if (RemainingExtraTurnCycles > 0)
			{
				RemainingExtraTurnCycles--;
				return;
			}
			((PowerModel)this).Flash();
			await PowerCmd.Remove((PowerModel)(object)this);
			await ApplyInternalPower(choiceContext, ((PowerModel)this).Owner, -SignedAmount(((PowerModel)this).Amount), ((PowerModel)this).Owner, null);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Applies the sign selected by <see cref="P:STS2RitsuLib.Combat.Powers.ModTemporaryPowerTemplate.IsPositive" /> to <paramref name="amount" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         根据 <see cref="P:STS2RitsuLib.Combat.Powers.ModTemporaryPowerTemplate.IsPositive" /> 为 <paramref name="amount" /> 应用对应的正负号。
		///     </para>
		/// </summary>
		/// <param name="amount">
		///     <para xml:lang="en">The unsigned effect amount.</para>
		///     <para xml:lang="zh-CN">尚未确定正负号的效果数值。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The signed amount to apply to the internal power.</para>
		///     <para xml:lang="zh-CN">要应用到内部能力的带符号数值。</para>
		/// </returns>
		protected virtual decimal SignedAmount(decimal amount)
		{
			if (!IsPositive)
			{
				return -amount;
			}
			return amount;
		}

		private IEnumerable<DynamicVar> BuildCanonicalVars()
		{
			DynamicVar[] additionalVars = AdditionalCanonicalVars?.ToArray() ?? throw new InvalidOperationException("AdditionalCanonicalVars cannot be null.");
			if (additionalVars.Any((DynamicVar dynVar) => dynVar == null))
			{
				throw new InvalidOperationException("AdditionalCanonicalVars cannot contain null entries.");
			}
			if (additionalVars.Any((DynamicVar dynVar) => dynVar.Name == "ExtraTurns"))
			{
				throw new ArgumentException("'ExtraTurns' is reserved by ModTemporaryPowerTemplate. Add a differently-named var via AdditionalCanonicalVars.");
			}
			yield return (DynamicVar)new IntVar("ExtraTurns", 0m);
			DynamicVar[] array = additionalVars;
			for (int num = 0; num < array.Length; num++)
			{
				yield return array[num];
			}
		}

		private IEnumerable<IHoverTip> ResolveExtraHoverTips()
		{
			AbstractModel originModel = OriginModel;
			CardModel val = (CardModel)(object)((originModel is CardModel) ? originModel : null);
			List<IHoverTip> list2;
			if (val == null)
			{
				PotionModel val2 = (PotionModel)(object)((originModel is PotionModel) ? originModel : null);
				if (val2 == null)
				{
					RelicModel val3 = (RelicModel)(object)((originModel is RelicModel) ? originModel : null);
					if (val3 == null)
					{
						PowerModel val4 = (PowerModel)(object)((originModel is PowerModel) ? originModel : null);
						if (val4 != null)
						{
							int num = 1;
							List<IHoverTip> list = new List<IHoverTip>(num);
							CollectionsMarshal.SetCount(list, num);
							CollectionsMarshal.AsSpan(list)[0] = HoverTipFactory.FromPower(val4, (int?)null);
							list2 = list;
						}
						else
						{
							list2 = new List<IHoverTip>();
						}
					}
					else
					{
						list2 = HoverTipFactory.FromRelic(val3).ToList();
					}
				}
				else
				{
					int num = 1;
					List<IHoverTip> list3 = new List<IHoverTip>(num);
					CollectionsMarshal.SetCount(list3, num);
					CollectionsMarshal.AsSpan(list3)[0] = HoverTipFactory.FromPotion(val2);
					list2 = list3;
				}
			}
			else
			{
				int num = 1;
				List<IHoverTip> list4 = new List<IHoverTip>(num);
				CollectionsMarshal.SetCount(list4, num);
				CollectionsMarshal.AsSpan(list4)[0] = HoverTipFactory.FromCard(val, false);
				list2 = list4;
			}
			List<IHoverTip> list5 = list2;
			list5.Add(HoverTipFactory.FromPower(InternallyAppliedPower, (int?)null));
			return list5;
		}

		private Task ApplyInternalPower(PlayerChoiceContext choiceContext, Creature target, decimal amount, Creature? applier, CardModel? cardSource, bool silent = false)
		{
			Type type = ((object)InternallyAppliedPower).GetType();
			if (_cachedInternalPowerType == type && _cachedInternalPowerInvoker != null)
			{
				return _cachedInternalPowerInvoker(choiceContext, target, amount, applier, cardSource, silent);
			}
			MethodInfo methodInfo = ApplyInternalPowerGenericMethod.MakeGenericMethod(type);
			_cachedInternalPowerInvoker = methodInfo.CreateDelegate<ApplyInternalPowerInvoker>();
			_cachedInternalPowerType = type;
			return _cachedInternalPowerInvoker(choiceContext, target, amount, applier, cardSource, silent);
		}

		private static Task ApplyInternalPowerGeneric<TPower>(PlayerChoiceContext choiceContext, Creature target, decimal amount, Creature? applier, CardModel? cardSource, bool silent) where TPower : PowerModel
		{
			return PowerCmd.Apply<TPower>(choiceContext, target, amount, applier, cardSource, silent);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Binds a temporary-power wrapper to a specific origin model and internal power type.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将临时能力包装绑定到指定的来源模型和内部能力类型。
	///     </para>
	/// </summary>
	/// <typeparam name="TOriginModel">
	///     <para xml:lang="en">The model type that grants the temporary power.</para>
	///     <para xml:lang="zh-CN">授予该临时能力的模型类型。</para>
	/// </typeparam>
	/// <typeparam name="TPower">
	///     <para xml:lang="en">The internal power type to apply temporarily.</para>
	///     <para xml:lang="zh-CN">要临时应用的内部能力类型。</para>
	/// </typeparam>
	public abstract class ModTemporaryAppliedPowerTemplate<TOriginModel, TPower> : ModTemporaryPowerTemplate where TOriginModel : AbstractModel where TPower : PowerModel
	{
		/// <inheritdoc />
		public override AbstractModel OriginModel => ModelDb.GetById<AbstractModel>(ModelDb.GetId<TOriginModel>());

		/// <inheritdoc />
		public override PowerModel InternallyAppliedPower => (PowerModel)(object)ModelDb.Power<TPower>();
	}
}
namespace STS2RitsuLib.Combat.PlayerResources
{
	/// <summary>
	///     <para xml:lang="en">Defines optional gameplay hooks for built-in player resources.</para>
	///     <para xml:lang="zh-CN">定义游戏内置玩家资源的可选钩子。</para>
	/// </summary>
	public interface IPlayerResourceHookListener
	{
		/// <summary>
		///     <para xml:lang="en">Runs after the player gains energy through <c>PlayerCmd.GainEnergy</c>.</para>
		///     <para xml:lang="zh-CN">在玩家通过 <c>PlayerCmd.GainEnergy</c> 获得能量后运行。</para>
		/// </summary>
		Task AfterPlayerEnergyGained(PlayerResourceGainContext context)
		{
			return Task.CompletedTask;
		}

		/// <summary>
		///     <para xml:lang="en">Runs after the player gains stars through <c>PlayerCmd.GainStars</c>.</para>
		///     <para xml:lang="zh-CN">在玩家通过 <c>PlayerCmd.GainStars</c> 获得辉星后运行。</para>
		/// </summary>
		Task AfterPlayerStarsGained(PlayerResourceGainContext context)
		{
			return Task.CompletedTask;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides context for a successful gain of a built-in player resource.</para>
	///     <para xml:lang="zh-CN">提供玩家成功获得游戏内置资源时的上下文。</para>
	/// </summary>
	public readonly record struct PlayerResourceGainContext(ICombatState CombatState, Player Player, PlayerResourceKind Resource, int Amount, int OldAmount, int NewAmount);
	/// <summary>
	///     <para xml:lang="en">Dispatches built-in player-resource hooks to models, capabilities, and global listeners.</para>
	///     <para xml:lang="zh-CN">将游戏内置玩家资源钩子分发给模型、模型能力和全局监听器。</para>
	/// </summary>
	public static class PlayerResourceHook
	{
		private static readonly ModelHookListenerRegistry<IPlayerResourceHookListener> GlobalListeners = new ModelHookListenerRegistry<IPlayerResourceHookListener>();

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a process-wide listener. Effects owned by a model should normally implement
		///         <see cref="T:STS2RitsuLib.Combat.PlayerResources.IPlayerResourceHookListener" /> directly.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册进程级监听器。由模型持有的效果通常应直接实现 <see cref="T:STS2RitsuLib.Combat.PlayerResources.IPlayerResourceHookListener" />。
		///     </para>
		/// </summary>
		public static void RegisterGlobalListener(IPlayerResourceHookListener listener)
		{
			GlobalListeners.Register(listener);
		}

		/// <summary>
		///     <para xml:lang="en">Runs after-energy-gained hooks.</para>
		///     <para xml:lang="zh-CN">运行获得能量后的钩子。</para>
		/// </summary>
		public static async Task AfterEnergyGained(PlayerResourceGainContext context)
		{
			foreach (ModelHookListener<IPlayerResourceHookListener> item in IterateListeners(context.CombatState))
			{
				await Invoke(item, context, (IPlayerResourceHookListener listener, PlayerResourceGainContext ctx) => listener.AfterPlayerEnergyGained(ctx));
			}
		}

		/// <summary>
		///     <para xml:lang="en">Runs after-stars-gained hooks.</para>
		///     <para xml:lang="zh-CN">运行获得辉星后的钩子。</para>
		/// </summary>
		public static async Task AfterStarsGained(PlayerResourceGainContext context)
		{
			foreach (ModelHookListener<IPlayerResourceHookListener> item in IterateListeners(context.CombatState))
			{
				await Invoke(item, context, (IPlayerResourceHookListener listener, PlayerResourceGainContext ctx) => listener.AfterPlayerStarsGained(ctx));
			}
		}

		internal static async Task AfterEnergyGainedIfChanged(Player player, int oldAmount)
		{
			if (TryCreateGainContext(player, PlayerResourceKind.Energy, oldAmount, out var context))
			{
				await AfterEnergyGained(context);
			}
		}

		internal static async Task AfterStarsGainedIfChanged(Player player, int oldAmount)
		{
			if (TryCreateGainContext(player, PlayerResourceKind.Stars, oldAmount, out var context))
			{
				await AfterStarsGained(context);
			}
		}

		private static bool TryCreateGainContext(Player player, PlayerResourceKind resource, int oldAmount, out PlayerResourceGainContext context)
		{
			context = default(PlayerResourceGainContext);
			if (player.PlayerCombatState != null)
			{
				Creature creature = player.Creature;
				ICombatState val = ((creature != null) ? creature.CombatState : null);
				if (val != null)
				{
					int num = resource switch
					{
						PlayerResourceKind.Energy => player.PlayerCombatState.Energy, 
						PlayerResourceKind.Stars => player.PlayerCombatState.Stars, 
						_ => oldAmount, 
					};
					int num2 = num - oldAmount;
					if (num2 <= 0)
					{
						return false;
					}
					context = new PlayerResourceGainContext(val, player, resource, num2, oldAmount, num);
					return true;
				}
			}
			return false;
		}

		private static IEnumerable<ModelHookListener<IPlayerResourceHookListener>> IterateListeners(ICombatState combatState)
		{
			return ModelHookListenerDispatcher.FromCombat(combatState, GlobalListeners);
		}

		private static async Task Invoke(ModelHookListener<IPlayerResourceHookListener> entry, PlayerResourceGainContext context, Func<IPlayerResourceHookListener, PlayerResourceGainContext, Task> callback)
		{
			await callback(entry.Listener, context);
			AbstractModel? model = entry.Model;
			if (model != null)
			{
				model.InvokeExecutionFinished();
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Lists the built-in player combat resources supported by <see cref="T:STS2RitsuLib.Combat.PlayerResources.PlayerResourceHook" />.</para>
	///     <para xml:lang="zh-CN">列出 <see cref="T:STS2RitsuLib.Combat.PlayerResources.PlayerResourceHook" /> 支持的游戏内置玩家战斗资源。</para>
	/// </summary>
	public enum PlayerResourceKind
	{
		/// <summary>
		///     <para xml:lang="en">Player energy.</para>
		///     <para xml:lang="zh-CN">玩家能量。</para>
		/// </summary>
		Energy,
		/// <summary>
		///     <para xml:lang="en">Player stars.</para>
		///     <para xml:lang="zh-CN">玩家辉星。</para>
		/// </summary>
		Stars
	}
}
namespace STS2RitsuLib.Combat.PlayerResources.Patches
{
	internal sealed class PlayerCmdGainEnergyHookPatch : IPatchMethod
	{
		public static string PatchId => "player_resource_hook_gain_energy";

		public static string Description => "Dispatch player energy gained hooks";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(PlayerCmd), "GainEnergy", new Type[2]
				{
					typeof(decimal),
					typeof(Player)
				})
			};
		}

		[HarmonyPriority(800)]
		public static void Prefix(Player player, out int __state)
		{
			PlayerCombatState playerCombatState = player.PlayerCombatState;
			__state = ((playerCombatState != null) ? playerCombatState.Energy : 0);
		}

		[HarmonyPriority(0)]
		public static void Postfix(Player player, int __state, ref Task __result)
		{
			__result = LifecyclePatchTaskBridge.After(__result, () => PlayerResourceHook.AfterEnergyGainedIfChanged(player, __state));
		}
	}
	internal sealed class PlayerCmdGainStarsHookPatch : IPatchMethod
	{
		public static string PatchId => "player_resource_hook_gain_stars";

		public static string Description => "Dispatch player stars gained hooks";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(PlayerCmd), "GainStars", new Type[2]
				{
					typeof(decimal),
					typeof(Player)
				})
			};
		}

		[HarmonyPriority(800)]
		public static void Prefix(Player player, out int __state)
		{
			PlayerCombatState playerCombatState = player.PlayerCombatState;
			__state = ((playerCombatState != null) ? playerCombatState.Stars : 0);
		}

		[HarmonyPriority(0)]
		public static void Postfix(Player player, int __state, ref Task __result)
		{
			__result = LifecyclePatchTaskBridge.After(__result, () => PlayerResourceHook.AfterStarsGainedIfChanged(player, __state));
		}
	}
