	/// <summary>
	///     <para xml:lang="en">
	///         Bridges <see cref="M:STS2RitsuLib.Combat.HealthBars.HealthBarForecastRegistry.GetSegments(MegaCrit.Sts2.Core.Entities.Creatures.Creature)" /> to BaseLib's
	///         <c>HealthBarForecastRegistry.RegisterForeign</c> API so a single renderer can consume both libraries'
	///         forecast segments.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将 <see cref="M:STS2RitsuLib.Combat.HealthBars.HealthBarForecastRegistry.GetSegments(MegaCrit.Sts2.Core.Entities.Creatures.Creature)" /> 桥接到 BaseLib 的
	///         <c>HealthBarForecastRegistry.RegisterForeign</c> API，使同一个渲染器能够处理两个库的预测片段。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         After registration succeeds with BaseLib's current render protocol,
	///         <see cref="M:STS2RitsuLib.Combat.HealthBars.BaseLibHealthBarForecastBridge.ShouldRitsuRendererStandDown" /> prevents RitsuLib from drawing duplicate overlays.
	///         Older BaseLib protocols are imported into RitsuLib's renderer instead.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         使用 BaseLib 当前渲染协议注册成功后，<see cref="M:STS2RitsuLib.Combat.HealthBars.BaseLibHealthBarForecastBridge.ShouldRitsuRendererStandDown" /> 会阻止
	///         RitsuLib 重复绘制覆盖层。较旧的 BaseLib 协议则会由 RitsuLib 渲染器导入。
	///     </para>
	/// </remarks>
	internal static class BaseLibHealthBarForecastBridge
	{
		internal readonly record struct BaseLibImportedHealthBarForecastSegment(int Amount, Color Color, HealthBarForecastGrowthDirection Direction, int Order, long SequenceOrder, Material? OverlayMaterial, Color? OverlaySelfModulate, HealthBarForecastLeftOriginLayout LeftOriginLayout, int LeftExclusiveZGroup, bool AffectsHpLabel);

		private sealed class LegacyImportReader(Func<object, IReadOnlyList<BaseLibImportedHealthBarForecastSegment>>? read)
		{
			public static LegacyImportReader Unavailable { get; } = new LegacyImportReader(null);

			public IReadOnlyList<BaseLibImportedHealthBarForecastSegment> Read(object entries)
			{
				return read?.Invoke(entries) ?? Array.Empty<BaseLibImportedHealthBarForecastSegment>();
			}
		}

		private sealed record TypedSegmentReader<TSegment>(Func<TSegment, int> ReadAmount, Func<TSegment, Color> ReadColor, Func<TSegment, int> ReadDirection, Func<TSegment, int> ReadOrder, Func<TSegment, Material?> ReadOverlayMaterial, Func<TSegment, Color?> ReadOverlaySelfModulate, Func<TSegment, int> ReadLeftOriginLayout, Func<TSegment, int> ReadLeftExclusiveZGroup, Func<TSegment, bool> ReadAffectsHpLabel);

		private const string SourceId = "ritsulib.registry";

		private static readonly Lock Gate = new Lock();

		private static bool _registered;

		private static bool _legacyImportMode;

		private static bool _baselibSupportsForecastInterop;

		private static bool _baselibSupportsRitsuRenderProtocol;

		private static bool _loggedMissingInterop;

		private static bool _loggedMissingRegisterForeign;

		private static bool _loggedLegacyImportMode;

		private static bool _loggedMissingLegacyImport;

		private static bool _loggedLegacyImportFailure;

		private static Action<string, string, Func<Creature, IEnumerable<object>>>? _registerForeign;

		private static MethodInfo? _getSegmentsMethod;

		private static readonly ConcurrentDictionary<Type, LegacyImportReader> LegacyImportReaders = new ConcurrentDictionary<Type, LegacyImportReader>();

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether BaseLib has accepted RitsuLib's segments and RitsuLib's <c>NHealthBar</c> patches
		///         should stop drawing them.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取 BaseLib 是否已接收 RitsuLib 的片段，以及 RitsuLib 的 <c>NHealthBar</c> 补丁是否应停止绘制。
		///     </para>
		/// </summary>
		public static bool ShouldRitsuRendererStandDown()
		{
			using (Gate.EnterScope())
			{
				return _registered && _baselibSupportsForecastInterop && _baselibSupportsRitsuRenderProtocol;
			}
		}

		public static bool ShouldSuppressBaseLibRenderer()
		{
			using (Gate.EnterScope())
			{
				MethodInfo getSegments;
				return (!_registered || !_baselibSupportsForecastInterop || !_baselibSupportsRitsuRenderProtocol) && (_legacyImportMode || TryResolveLegacyImportApi(out getSegments));
			}
		}

		internal static IReadOnlyList<BaseLibImportedHealthBarForecastSegment> GetImportedSegments(Creature creature)
		{
			MethodInfo getSegments;
			using (Gate.EnterScope())
			{
				if ((_registered && _baselibSupportsForecastInterop && _baselibSupportsRitsuRenderProtocol) || !TryResolveLegacyImportApi(out getSegments))
				{
					return Array.Empty<BaseLibImportedHealthBarForecastSegment>();
				}
			}
			try
			{
				object obj = FastMethodInvoker.InvokeStatic1(getSegments, creature);
				if (obj == null)
				{
					return Array.Empty<BaseLibImportedHealthBarForecastSegment>();
				}
				return LegacyImportReaders.GetOrAdd(obj.GetType(), CreateLegacyImportReader).Read(obj);
			}
			catch (Exception value)
			{
				using (Gate.EnterScope())
				{
					if (_loggedLegacyImportFailure)
					{
						return Array.Empty<BaseLibImportedHealthBarForecastSegment>();
					}
					_loggedLegacyImportFailure = true;
				}
				RitsuLibFramework.Logger.Warn($"[HealthBarForecast] Failed to import BaseLib forecast segments: {value}", 1);
				return Array.Empty<BaseLibImportedHealthBarForecastSegment>();
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts cross-library registration from the early <c>NHealthBar._Ready</c> path.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从较早执行的 <c>NHealthBar._Ready</c> 路径尝试跨库注册。
		///     </para>
		/// </summary>
		public static void TryRegisterPrimary()
		{
			TryRegisterCore();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Retries cross-library registration from the forecast render path when the primary attempt has not
		///         succeeded.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         主要注册尝试尚未成功时，从预测渲染路径重试跨库注册。
		///     </para>
		/// </summary>
		public static void TryRegisterSecondary()
		{
			TryRegisterCore();
		}

		/// <summary>
		///     <para xml:lang="en">Calls <see cref="M:STS2RitsuLib.Combat.HealthBars.BaseLibHealthBarForecastBridge.TryRegisterPrimary" />.</para>
		///     <para xml:lang="zh-CN">调用 <see cref="M:STS2RitsuLib.Combat.HealthBars.BaseLibHealthBarForecastBridge.TryRegisterPrimary" />。</para>
		/// </summary>
		public static void TryRegister()
		{
			TryRegisterPrimary();
		}

		private static void TryRegisterCore()
		{
			using (Gate.EnterScope())
			{
				if (_registered || _legacyImportMode || !ExternalFrameworkRegistry.IsFrameworkPresent("baselib"))
				{
					return;
				}
				try
				{
					Type type = ResolveBaseLibRegistryType();
					if (type == null)
					{
						return;
					}
					MethodInfo method = type.GetMethod("RegisterForeign", BindingFlags.Static | BindingFlags.Public, null, new Type[3]
					{
						typeof(string),
						typeof(string),
						typeof(Func<Creature, IEnumerable<object>>)
					}, null);
					MethodInfo getSegments;
					if (method == null)
					{
						_baselibSupportsForecastInterop = false;
						_legacyImportMode = TryResolveLegacyImportApi(type, out getSegments);
						if (!_loggedMissingRegisterForeign)
						{
							_loggedMissingRegisterForeign = true;
							RitsuLibFramework.Logger.Warn("[HealthBarForecast] BaseLib registry type '" + type.FullName + "' does not expose RegisterForeign(string, string, Func<Creature, IEnumerable<object>>); forecast interop unavailable.", 1);
						}
						return;
					}
					if (!BaseLibSupportsRitsuRenderProtocol(type))
					{
						_baselibSupportsForecastInterop = true;
						_baselibSupportsRitsuRenderProtocol = false;
						_legacyImportMode = TryResolveLegacyImportApi(type, out getSegments);
						if (!_loggedLegacyImportMode)
						{
							_loggedLegacyImportMode = true;
							RitsuLibFramework.Logger.Info("[HealthBarForecast] BaseLib forecast registry uses the legacy render protocol; RitsuLib will import BaseLib segments and keep its own renderer active.", 1);
						}
						return;
					}
					Func<Creature, IEnumerable<object>> arg = GetSegmentsForCreature;
					if (_registerForeign == null)
					{
						_registerForeign = method.CreateDelegate<Action<string, string, Func<Creature, IEnumerable<object>>>>();
					}
					_registerForeign("com.ritsukage.sts2-RitsuLib", "ritsulib.registry", arg);
					_registered = true;
					_baselibSupportsForecastInterop = true;
					_baselibSupportsRitsuRenderProtocol = true;
					RitsuLibFramework.Logger.Info("[HealthBarForecast] Registered BaseLib bridge provider.", 1);
				}
				catch (Exception value)
				{
					RitsuLibFramework.Logger.Warn($"[HealthBarForecast] Failed to register BaseLib bridge provider: {value}", 1);
				}
			}
		}

		private static IEnumerable<object> GetSegmentsForCreature(Creature creature)
		{
			List<object> list = new List<object>();
			list.AddRange(((IEnumerable<HealthBarForecastRegistry.RegisteredHealthBarForecastSegment>)HealthBarForecastRegistry.GetSegments(creature)).Select((Func<HealthBarForecastRegistry.RegisteredHealthBarForecastSegment, object>)((HealthBarForecastRegistry.RegisteredHealthBarForecastSegment registered) => registered.Segment)));
			return new <>z__ReadOnlyList<object>(list);
		}

		private static Type? ResolveBaseLibRegistryType()
		{
			Type type = ResolveRegistryType();
			_baselibSupportsForecastInterop = type != null;
			if (!_baselibSupportsForecastInterop)
			{
				if (_loggedMissingInterop)
				{
					return null;
				}
				_loggedMissingInterop = true;
				RitsuLibFramework.Logger.Info("[HealthBarForecast] BaseLib detected but forecast interop API is unavailable.", 1);
				return null;
			}
			_loggedMissingInterop = false;
			return type;
		}

		private static bool TryResolveLegacyImportApi(out MethodInfo getSegments)
		{
			getSegments = null;
			if (_getSegmentsMethod != null)
			{
				getSegments = _getSegmentsMethod;
				return true;
			}
			Type type = ResolveRegistryType();
			if (type != null)
			{
				return TryResolveLegacyImportApi(type, out getSegments);
			}
			return false;
		}

		private static bool TryResolveLegacyImportApi(Type registryType, out MethodInfo getSegments)
		{
			getSegments = null;
			if (_getSegmentsMethod != null)
			{
				getSegments = _getSegmentsMethod;
				return true;
			}
			MethodInfo method = registryType.GetMethod("GetSegments", BindingFlags.Static | BindingFlags.NonPublic, null, new Type[1] { typeof(Creature) }, null);
			if (method == null || !typeof(IEnumerable).IsAssignableFrom(method.ReturnType))
			{
				if (_loggedMissingLegacyImport)
				{
					return false;
				}
				_loggedMissingLegacyImport = true;
				RitsuLibFramework.Logger.Warn("[HealthBarForecast] BaseLib legacy forecast registry does not expose importable GetSegments.", 1);
				return false;
			}
			_getSegmentsMethod = method;
			getSegments = method;
			return true;
		}

		private static bool BaseLibSupportsRitsuRenderProtocol(Type registryType)
		{
			Type type = registryType.Assembly.GetType("BaseLib.Hooks.HealthBarForecastSegment") ?? ExternalFrameworkRegistry.ResolveType("BaseLib.Hooks.HealthBarForecastSegment");
			_baselibSupportsRitsuRenderProtocol = type != null && HasPublicInstanceProperty(type, "LeftOriginLayout") && HasPublicInstanceProperty(type, "LeftExclusiveZGroup") && HasPublicInstanceProperty(type, "AffectsHpLabel");
			return _baselibSupportsRitsuRenderProtocol;
		}

		private static bool HasPublicInstanceProperty(Type type, string name)
		{
			return type.GetProperty(name, BindingFlags.Instance | BindingFlags.Public) != null;
		}

		private static LegacyImportReader CreateLegacyImportReader(Type collectionType)
