			}
			Func<TEntry, TSegment> readSegment = FastMethodInvoker.CreateInstanceGetter<TEntry, TSegment>(segmentProperty);
			Func<TEntry, long> readSequenceOrder = FastMethodInvoker.CreateInstanceGetter<TEntry, long>(sequenceOrderProperty);
			return new LegacyImportReader((object entries) => ImportTypedSegments((IEnumerable<TEntry>)entries, readSegment, readSequenceOrder, segmentReader));
		}

		private static IReadOnlyList<BaseLibImportedHealthBarForecastSegment> ImportTypedSegments<TEntry, TSegment>(IEnumerable<TEntry> entries, Func<TEntry, TSegment> readSegment, Func<TEntry, long> readSequenceOrder, TypedSegmentReader<TSegment> segmentReader)
		{
			List<BaseLibImportedHealthBarForecastSegment> segments = new List<BaseLibImportedHealthBarForecastSegment>();
			if (entries is IReadOnlyList<TEntry> readOnlyList)
			{
