			}
			Func<TSegment, int> readAmount = FastMethodInvoker.CreateInstanceGetter<TSegment, int>(property);
			Func<TSegment, Color> readColor = FastMethodInvoker.CreateInstanceGetter<TSegment, Color>(property2);
			Func<TSegment, int> readDirection = FastMethodInvoker.CreateInstanceGetter<TSegment, int>(property3);
