		private static Type? ResolveEnumerableElementType(Type collectionType)
		{
			if (collectionType.IsArray)
			{
				return collectionType.GetElementType();
			}
			return (from type in collectionType.GetInterfaces().Append(collectionType)
				where type.IsGenericType && type.GetGenericTypeDefinition() == typeof(IEnumerable<>)
				select type.GetGenericArguments()[0]).FirstOrDefault();
		}

		private static bool CanReadEnumOrdinal(PropertyInfo property)
		{
			if (!property.PropertyType.IsEnum)
			{
				return property.PropertyType == typeof(int);
			}
			return true;
		}

		private static HealthBarForecastGrowthDirection ToGrowthDirection(int value)
		{
			if (value != 1)
			{
				return HealthBarForecastGrowthDirection.FromRight;
			}
			return HealthBarForecastGrowthDirection.FromLeft;
		}

		private static HealthBarForecastLeftOriginLayout ToLeftOriginLayout(int value)
		{
			if (value != 1)
			{
				return HealthBarForecastLeftOriginLayout.Chained;
			}
			return HealthBarForecastLeftOriginLayout.OverlapFromOrigin;
		}

		private static Type? ResolveRegistryType()
		{
			return ExternalFrameworkRegistry.ResolveType("BaseLib.Hooks.HealthBarForecastRegistry");
		}
