		private const string SourceId = "ritsulib.visual_graft_registry";

		private static readonly Lock Gate = new Lock();

		private static bool _registered;

		private static bool _interopOk;

		private static bool _loggedMissingRegistry;

		private static bool _loggedMissingRegisterForeign;

		private static Action<string, string, Func<Creature, object>>? _registerForeign;

		public static bool ShouldRitsuGraftStandDown()
		{
			using (Gate.EnterScope())
			{
				return _registered && _interopOk;
			}
		}

		public static void TryRegisterPrimary()
		{
			TryRegisterCore();
		}

		public static void TryRegisterSecondary()
		{
			TryRegisterCore();
		}

		public static void TryRegister()
		{
			TryRegisterPrimary();
		}

		private static void TryRegisterCore()
		{
			using (Gate.EnterScope())
			{
				if (_registered || !ExternalFrameworkRegistry.IsFrameworkPresent("baselib"))
				{
					return;
				}
				try
				{
					Type type = ResolveBaseLibRegistryType();
					if (type == null)
					{
						return;
					}
					MethodInfo method = type.GetMethod("RegisterForeign", BindingFlags.Static | BindingFlags.Public, null, new Type[3]
					{
						typeof(string),
						typeof(string),
						typeof(Func<Creature, object>)
					}, null);
					if (method == null)
					{
						_interopOk = false;
						if (!_loggedMissingRegisterForeign)
						{
							_loggedMissingRegisterForeign = true;
							RitsuLibFramework.Logger.Warn("[HealthBarGraft] BaseLib registry type does not expose RegisterForeign(string, string, Func<Creature, object>).", 1);
						}
						return;
					}
					if (_registerForeign == null)
					{
						_registerForeign = method.CreateDelegate<Action<string, string, Func<Creature, object>>>();
					}
					_registerForeign("com.ritsukage.sts2-RitsuLib", "ritsulib.visual_graft_registry", Handler);
					_registered = true;
					_interopOk = true;
					RitsuLibFramework.Logger.Info("[HealthBarGraft] Registered BaseLib visual graft bridge.", 1);
				}
				catch (Exception value)
				{
					RitsuLibFramework.Logger.Warn($"[HealthBarGraft] Failed to register BaseLib bridge: {value}", 1);
				}
			}
			static object Handler(Creature c)
			{
				return HealthBarVisualGraftRegistry.Aggregate(c);
			}
		}

		private static Type? ResolveBaseLibRegistryType()
		{
			Type type = ExternalFrameworkRegistry.ResolveType("BaseLib.Hooks.HealthBarVisualGraftRegistry");
			if (type != null)
			{
				return type;
			}
			if (!_loggedMissingRegistry)
			{
				_loggedMissingRegistry = true;
				RitsuLibFramework.Logger.Info("[HealthBarGraft] BaseLib graft registry type not found.", 1);
			}
			_interopOk = false;
			return null;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Specifies the health-bar edge from which a forecast segment extends.</para>
	///     <para xml:lang="zh-CN">指定生命条预测片段从哪一侧边缘延伸。</para>
	/// </summary>
	public enum HealthBarForecastGrowthDirection
	{
		/// <summary>
		///     <para xml:lang="en">Extends inward from the current-HP edge, like Poison.</para>
		///     <para xml:lang="zh-CN">从当前生命值边缘向内延伸，与“中毒”相同。</para>
		/// </summary>
		FromRight,
		/// <summary>
		///     <para xml:lang="en">Extends inward from the empty edge, like Doom.</para>
		///     <para xml:lang="zh-CN">从空白侧边缘向内延伸，与“灾厄”相同。</para>
		/// </summary>
		FromLeft
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Specifies how <see cref="F:STS2RitsuLib.Combat.HealthBars.HealthBarForecastGrowthDirection.FromLeft" /> segments share the empty-edge
	///         origin.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         指定 <see cref="F:STS2RitsuLib.Combat.HealthBars.HealthBarForecastGrowthDirection.FromLeft" /> 片段如何共享空白侧边缘的起点。
	///     </para>
	/// </summary>
	public enum HealthBarForecastLeftOriginLayout
	{
		/// <summary>
		///     <para xml:lang="en">Connects segments end to end from the empty edge.</para>
		///     <para xml:lang="zh-CN">从空白侧边缘开始首尾相接地排列片段。</para>
		/// </summary>
		Chained,
		/// <summary>
		///     <para xml:lang="en">
		///         Starts every segment at the empty edge and gives it its own amount-capped width. Longer segments are
		///         drawn behind shorter ones; equal widths use segment order and then registration order, with later
		///         entries on top.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         每个片段都从空白侧边缘开始，并按自身数值计算不超过剩余生命值的宽度。较长片段绘制在较短片段
		///         后方；宽度相同时依次按片段顺序和注册顺序排列，较晚的项位于上层。
		///     </para>
		/// </summary>
		OverlapFromOrigin
	}
	/// <summary>
	///     <para xml:lang="en">Describes one forecast segment on a creature's health bar.</para>
	///     <para xml:lang="zh-CN">描述生物生命条上的一个预测片段。</para>
	/// </summary>
	/// <param name="Amount">
	///     <para xml:lang="en">The HP amount represented by the segment.</para>
	///     <para xml:lang="zh-CN">该片段表示的生命值数值。</para>
	/// </param>
	/// <param name="Color">
	///     <para xml:lang="en">
	///         The lethal HP-label color. When <paramref name="OverlaySelfModulate" /> is <see langword="null" />, this
	///         also becomes the forecast overlay's <see cref="P:Godot.CanvasItem.SelfModulate" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         预测致命时的生命值文本颜色。当 <paramref name="OverlaySelfModulate" /> 为
	///         <see langword="null" /> 时，也会作为预测覆盖层的 <see cref="P:Godot.CanvasItem.SelfModulate" />。
	///     </para>
	/// </param>
	/// <param name="Direction">
	///     <para xml:lang="en">The edge from which the segment extends.</para>
	///     <para xml:lang="zh-CN">片段延伸的起始边缘。</para>
	/// </param>
	/// <param name="Order">
	///     <para xml:lang="en">
	///         The primary render order. Lower values render earlier and remain closer to the selected origin edge.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         主要渲染顺序。数值较低的片段更早渲染，并更靠近所选的起始边缘。
	///     </para>
	/// </param>
	/// <param name="OverlayMaterial">
	///     <para xml:lang="en">
	///         The optional Godot material. When <see langword="null" />, only the modulation color is applied.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         可选的 Godot 材质。为 <see langword="null" /> 时只应用调制色。
	///     </para>
	/// </param>
	/// <param name="OverlaySelfModulate">
	///     <para xml:lang="en">
	///         The optional overlay <see cref="P:Godot.CanvasItem.SelfModulate" />. This does not change the lethal HP-label
	///         color supplied by <paramref name="Color" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         覆盖层可选的 <see cref="P:Godot.CanvasItem.SelfModulate" />。该值不会改变由
	///         <paramref name="Color" /> 提供的致命生命值文本颜色。
	///     </para>
	/// </param>
	/// <param name="LeftOriginLayout">
	///     <para xml:lang="en">
	///         The empty-edge layout for <see cref="F:STS2RitsuLib.Combat.HealthBars.HealthBarForecastGrowthDirection.FromLeft" /> segments. Ignored
	///         for <see cref="F:STS2RitsuLib.Combat.HealthBars.HealthBarForecastGrowthDirection.FromRight" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         <see cref="F:STS2RitsuLib.Combat.HealthBars.HealthBarForecastGrowthDirection.FromLeft" /> 片段使用的空白侧布局。
	///         对 <see cref="F:STS2RitsuLib.Combat.HealthBars.HealthBarForecastGrowthDirection.FromRight" /> 片段忽略。
	///     </para>
	/// </param>
	/// <param name="LeftExclusiveZGroup">
	///     <para xml:lang="en">
	///         The exclusive Z group for overlapping empty-edge segments. Larger groups draw above smaller groups.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         空白侧重叠片段使用的互斥 Z 组。数值较大的组绘制在数值较小的组之上。
	///     </para>
	/// </param>
	/// <param name="AffectsHpLabel">
	///     <para xml:lang="en">Whether this segment can recolor the HP label when its forecast becomes lethal.</para>
	///     <para xml:lang="zh-CN">该片段的预测致命时是否可以改变生命值文本颜色。</para>
	/// </param>
	public readonly record struct HealthBarForecastSegment(int Amount, Color Color, HealthBarForecastGrowthDirection Direction, int Order, Material? OverlayMaterial, Color? OverlaySelfModulate = null, HealthBarForecastLeftOriginLayout LeftOriginLayout = HealthBarForecastLeftOriginLayout.Chained, int LeftExclusiveZGroup = 0, bool AffectsHpLabel = true)
	{
		/// <summary>
		///     <para xml:lang="en">Initializes a segment without an overlay material or separate overlay color.</para>
		///     <para xml:lang="zh-CN">初始化不带覆盖材质或独立覆盖层颜色的片段。</para>
		/// </summary>
		public HealthBarForecastSegment(int amount, Color color, HealthBarForecastGrowthDirection direction, int order = 0)
		{
			//IL_0002: Unknown result type (might be due to invalid IL or missing references)
