	/// <summary>
	///     <para xml:lang="en">Provides forecast ordering keys relative to the active turn.</para>
	///     <para xml:lang="zh-CN">提供相对于当前行动回合的预测排序键。</para>
	/// </summary>
	public static class HealthBarForecastOrder
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets the ordering key for an effect that triggers at the start of <paramref name="triggerSide" />'s
		///         turn.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取在 <paramref name="triggerSide" /> 一方回合开始时触发的效果所用的排序键。
		///     </para>
		/// </summary>
		/// <param name="creature">
		///     <para xml:lang="en">The creature whose combat state determines the active side.</para>
		///     <para xml:lang="zh-CN">使用其战斗状态判断当前行动方的生物。</para>
		/// </param>
		/// <param name="triggerSide">
		///     <para xml:lang="en">The side whose turn-start effect is being ordered.</para>
		///     <para xml:lang="zh-CN">待排序的回合开始效果所属的一方。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <c>1</c> while <paramref name="triggerSide" /> is active; otherwise, <c>0</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         <paramref name="triggerSide" /> 为当前行动方时返回 <c>1</c>；否则返回 <c>0</c>。
		///     </para>
		/// </returns>
		public static int ForSideTurnStart(Creature creature, CombatSide triggerSide)
		{
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(creature, "creature");
			ICombatState combatState = creature.CombatState;
			return (combatState != null && combatState.CurrentSide == triggerSide) ? 1 : 0;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the ordering key for an effect that triggers at the end of <paramref name="triggerSide" />'s
		///         turn.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取在 <paramref name="triggerSide" /> 一方回合结束时触发的效果所用的排序键。
		///     </para>
		/// </summary>
		/// <param name="creature">
		///     <para xml:lang="en">The creature whose combat state determines the active side.</para>
		///     <para xml:lang="zh-CN">使用其战斗状态判断当前行动方的生物。</para>
		/// </param>
		/// <param name="triggerSide">
		///     <para xml:lang="en">The side whose turn-end effect is being ordered.</para>
		///     <para xml:lang="zh-CN">待排序的回合结束效果所属的一方。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <c>0</c> while <paramref name="triggerSide" /> is active; otherwise, <c>1</c>.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         <paramref name="triggerSide" /> 为当前行动方时返回 <c>0</c>；否则返回 <c>1</c>。
		///     </para>
		/// </returns>
		public static int ForSideTurnEnd(Creature creature, CombatSide triggerSide)
		{
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(creature, "creature");
			ICombatState combatState = creature.CombatState;
			return (combatState == null || combatState.CurrentSide != triggerSide) ? 1 : 0;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides the global registry for mod-defined health-bar forecast sources.</para>
	///     <para xml:lang="zh-CN">提供模组自定义生命条预测来源的全局注册表。</para>
	/// </summary>
	public static class HealthBarForecastRegistry
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Associates a segment with the stable source key used when
		///         <see cref="P:STS2RitsuLib.Combat.HealthBars.HealthBarForecastSegment.Order" /> values tie.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         将片段与 <see cref="P:STS2RitsuLib.Combat.HealthBars.HealthBarForecastSegment.Order" /> 相同时使用的稳定来源排序键关联。
		///     </para>
		/// </summary>
		/// <param name="Segment">
		///     <para xml:lang="en">The forecast segment.</para>
		///     <para xml:lang="zh-CN">预测片段。</para>
		/// </param>
		/// <param name="SequenceOrder">
		///     <para xml:lang="en">
		///         The monotonic source key, with creature powers ordered before globally registered sources.
		///     </para>
		///     <para xml:lang="zh-CN">单调递增的来源排序键；生物的能力排在全局注册来源之前。</para>
		/// </param>
		internal readonly record struct RegisteredHealthBarForecastSegment(HealthBarForecastSegment Segment, long SequenceOrder);

		private readonly record struct ProviderEntry(string ModId, string SourceId, IHealthBarForecastSource Source, long RegistrationOrder);

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<(string ModId, string ProviderId), ProviderEntry> Providers = new Dictionary<(string, string), ProviderEntry>(HealthBarProviderKeyComparer.Instance);

		private static long _nextRegistrationOrder;

		/// <summary>
		///     <para xml:lang="en">
		///         Creates and registers a forecast source, replacing the source with the same mod and source
		///         identifiers.
		///     </para>
		///     <para xml:lang="zh-CN">创建并注册预测来源，同时替换模组标识符和来源标识符均相同的来源。</para>
		/// </summary>
		/// <typeparam name="TSource">
		///     <para xml:lang="en">
		///         The concrete <see cref="T:STS2RitsuLib.Combat.HealthBars.IHealthBarForecastSource" /> type with a parameterless constructor.
		///     </para>
		///     <para xml:lang="zh-CN">带无参构造函数的具体 <see cref="T:STS2RitsuLib.Combat.HealthBars.IHealthBarForecastSource" /> 类型。</para>
		/// </typeparam>
		/// <param name="modId">
		///     <para xml:lang="en">The owning mod identifier. Surrounding whitespace is ignored.</para>
		///     <para xml:lang="zh-CN">所属模组的标识符；忽略首尾空白。</para>
		/// </param>
		/// <param name="sourceId">
		///     <para xml:lang="en">
		///         The optional source identifier within the mod. Defaults to the source type's full name.
		///     </para>
		///     <para xml:lang="zh-CN">来源在该模组内的可选标识符；默认使用来源类型的完整名称。</para>
		/// </param>
		public static void Register<TSource>(string modId, string? sourceId = null) where TSource : IHealthBarForecastSource, new()
		{
			Register(modId, sourceId ?? typeof(TSource).FullName ?? typeof(TSource).Name, new TSource());
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a forecast source instance, replacing the source with the same mod and source identifiers.
		///     </para>
		///     <para xml:lang="zh-CN">注册预测来源实例，同时替换模组标识符和来源标识符均相同的来源。</para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">The owning mod identifier. Surrounding whitespace is ignored.</para>
		///     <para xml:lang="zh-CN">所属模组的标识符；忽略首尾空白。</para>
		/// </param>
		/// <param name="sourceId">
		///     <para xml:lang="en">The source identifier within the mod. Surrounding whitespace is ignored.</para>
		///     <para xml:lang="zh-CN">来源在该模组内的标识符；忽略首尾空白。</para>
		/// </param>
		/// <param name="source">
		///     <para xml:lang="en">The forecast source instance.</para>
		///     <para xml:lang="zh-CN">预测来源实例。</para>
		/// </param>
		public static void Register(string modId, string sourceId, IHealthBarForecastSource source)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(sourceId, "sourceId");
			ArgumentNullException.ThrowIfNull(source, "source");
			string text = modId.Trim();
			string text2 = sourceId.Trim();
			using (SyncRoot.EnterScope())
			{
				(string, string) key = (text, text2);
				long registrationOrder = (Providers.TryGetValue(key, out var value) ? value.RegistrationOrder : _nextRegistrationOrder++);
				Providers[key] = new ProviderEntry(text, text2, source, registrationOrder);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Removes a registered forecast source.</para>
		///     <para xml:lang="zh-CN">移除已注册的预测来源。</para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">The mod identifier used during registration. Surrounding whitespace is ignored.</para>
		///     <para xml:lang="zh-CN">注册时使用的模组标识符；忽略首尾空白。</para>
		/// </param>
		/// <param name="sourceId">
		///     <para xml:lang="en">
		///         The source identifier used during registration. Surrounding whitespace is ignored.
		///     </para>
		///     <para xml:lang="zh-CN">注册时使用的来源标识符；忽略首尾空白。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> if a source was removed; otherwise, <see langword="false" />.</para>
		///     <para xml:lang="zh-CN">成功移除来源时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public static bool Unregister(string modId, string sourceId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(sourceId, "sourceId");
			using (SyncRoot.EnterScope())
			{
				return Providers.Remove((modId.Trim(), sourceId.Trim()));
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Collects segments from the creature's powers that implement <see cref="T:STS2RitsuLib.Combat.HealthBars.IHealthBarForecastSource" />
		///         and from globally registered sources.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         从该生物实现 <see cref="T:STS2RitsuLib.Combat.HealthBars.IHealthBarForecastSource" /> 的能力和全局注册来源中收集片段。
		///     </para>
		/// </summary>
		/// <param name="creature">
		///     <para xml:lang="en">The creature whose health bar is being evaluated.</para>
		///     <para xml:lang="zh-CN">待评估生命条的生物。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The positive forecast segments in stable source order.</para>
		///     <para xml:lang="zh-CN">按稳定来源顺序排列的正数预测片段。</para>
		/// </returns>
		internal static IReadOnlyList<RegisteredHealthBarForecastSegment> GetSegments(Creature creature)
		{
			ArgumentNullException.ThrowIfNull(creature, "creature");
			HealthBarForecastContext context = new HealthBarForecastContext(creature);
			List<RegisteredHealthBarForecastSegment> list = new List<RegisteredHealthBarForecastSegment>();
			long num = 0L;
			foreach (IHealthBarForecastSource item in creature.Powers.OfType<IHealthBarForecastSource>())
			{
				AppendSegments(item, item.GetType().FullName ?? item.GetType().Name, context, num++, list);
			}
			ProviderEntry[] array;
			using (SyncRoot.EnterScope())
			{
				array = Providers.Values.OrderBy((ProviderEntry entry) => entry.RegistrationOrder).ToArray();
			}
			ProviderEntry[] array2 = array;
			for (int num2 = 0; num2 < array2.Length; num2++)
			{
				ProviderEntry providerEntry = array2[num2];
				AppendSegments(providerEntry.Source, providerEntry.SourceId, context, 1000000 + providerEntry.RegistrationOrder, list, providerEntry.ModId);
			}
			return list;
		}

		private static void AppendSegments(IHealthBarForecastSource source, string sourceId, HealthBarForecastContext context, long sequenceOrder, List<RegisteredHealthBarForecastSegment> segments, string? modId = null)
		{
			try
			{
				RegisteredHealthBarForecastSegment[] collection = (from segment in source.GetHealthBarForecastSegments(context).Where(delegate(HealthBarForecastSegment segment)
					{
						HealthBarForecastSegment healthBarForecastSegment = segment;
						return healthBarForecastSegment.Amount > 0;
