	internal sealed class HealthBarProviderKeyComparer : IEqualityComparer<(string ModId, string SourceId)>
	{
		internal static HealthBarProviderKeyComparer Instance { get; } = new HealthBarProviderKeyComparer();

		public bool Equals((string ModId, string SourceId) x, (string ModId, string SourceId) y)
		{
			if (string.Equals(x.ModId, y.ModId, StringComparison.OrdinalIgnoreCase))
			{
				return string.Equals(x.SourceId, y.SourceId, StringComparison.OrdinalIgnoreCase);
			}
			return false;
		}

		public int GetHashCode((string ModId, string SourceId) obj)
		{
			return HashCode.Combine(StringComparer.OrdinalIgnoreCase.GetHashCode(obj.ModId), StringComparer.OrdinalIgnoreCase.GetHashCode(obj.SourceId));
		}
	}
