	/// <summary>
	///     <para xml:lang="en">
	///         Registers and aggregates visual health-bar extension sources from mods and creature powers.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         注册并汇总来自模组和生物能力的生命条视觉扩展来源。
	///     </para>
	/// </summary>
	public static class HealthBarVisualGraftRegistry
	{
		private readonly record struct ProviderEntry(string ModId, string SourceId, IHealthBarVisualGraftSource Source, long RegistrationOrder);

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<(string ModId, string SourceId), ProviderEntry> Providers = new Dictionary<(string, string), ProviderEntry>(HealthBarProviderKeyComparer.Instance);

		private static long _nextRegistrationOrder;

		/// <summary>
		///     <para xml:lang="en">
		///         Registers or replaces a visual extension source implemented by <typeparamref name="TSource" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册或替换由 <typeparamref name="TSource" /> 实现的视觉扩展来源。
		///     </para>
		/// </summary>
		/// <typeparam name="TSource">
		///     <para xml:lang="en">The source type with a parameterless constructor.</para>
		///     <para xml:lang="zh-CN">具有无参构造函数的来源类型。</para>
		/// </typeparam>
		/// <param name="modId">
		///     <para xml:lang="en">The owning mod ID.</para>
		///     <para xml:lang="zh-CN">所属模组的 ID。</para>
		/// </param>
		/// <param name="sourceId">
		///     <para xml:lang="en">The optional mod-local source ID; defaults to the source type name.</para>
		///     <para xml:lang="zh-CN">可选的模组内来源 ID；默认使用来源类型名称。</para>
		/// </param>
		public static void Register<TSource>(string modId, string? sourceId = null) where TSource : IHealthBarVisualGraftSource, new()
		{
			Register(modId, sourceId ?? typeof(TSource).FullName ?? typeof(TSource).Name, new TSource());
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a visual extension source instance.</para>
		///     <para xml:lang="zh-CN">注册或替换视觉扩展来源实例。</para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">The owning mod ID.</para>
		///     <para xml:lang="zh-CN">所属模组的 ID。</para>
		/// </param>
		/// <param name="sourceId">
		///     <para xml:lang="en">The source ID within the mod.</para>
		///     <para xml:lang="zh-CN">该来源在模组内的 ID。</para>
		/// </param>
		/// <param name="source">
		///     <para xml:lang="en">The source instance.</para>
		///     <para xml:lang="zh-CN">来源实例。</para>
		/// </param>
		public static void Register(string modId, string sourceId, IHealthBarVisualGraftSource source)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(sourceId, "sourceId");
			ArgumentNullException.ThrowIfNull(source, "source");
			string text = modId.Trim();
			string text2 = sourceId.Trim();
			using (SyncRoot.EnterScope())
			{
				(string, string) key = (text, text2);
				long registrationOrder = (Providers.TryGetValue(key, out var value) ? value.RegistrationOrder : _nextRegistrationOrder++);
				Providers[key] = new ProviderEntry(text, text2, source, registrationOrder);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Removes a previously registered visual extension source.</para>
		///     <para xml:lang="zh-CN">移除先前注册的视觉扩展来源。</para>
		/// </summary>
		/// <param name="modId">
		///     <para xml:lang="en">The mod ID used at registration.</para>
		///     <para xml:lang="zh-CN">注册时使用的模组 ID。</para>
		/// </param>
		/// <param name="sourceId">
		///     <para xml:lang="en">The source ID used at registration.</para>
		///     <para xml:lang="zh-CN">注册时使用的来源 ID。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> when a source was removed.</para>
		///     <para xml:lang="zh-CN">移除来源时为 <see langword="true" />。</para>
		/// </returns>
		public static bool Unregister(string modId, string sourceId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			ArgumentException.ThrowIfNullOrWhiteSpace(sourceId, "sourceId");
			using (SyncRoot.EnterScope())
			{
				return Providers.Remove((modId.Trim(), sourceId.Trim()));
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sums positive extension HP from powers and registered sources with saturation at
		///         <see cref="F:System.Int32.MaxValue" />. The first non-null modulation color and material win independently,
		///         even when supplied by a source whose HP contribution is not positive.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         汇总能力和已注册来源提供的正数扩展生命值，并在 <see cref="F:System.Int32.MaxValue" /> 处饱和。
		///         最先出现的非空调制色和材质分别生效，即使提供外观的来源没有提供正数生命值。
		///     </para>
		/// </summary>
		internal static HealthBarVisualGraftMetrics Aggregate(Creature creature)
		{
			ArgumentNullException.ThrowIfNull(creature, "creature");
			int sumHp = 0;
			Color? color = null;
			Material material = null;
			HealthBarVisualGraftContext context = new HealthBarVisualGraftContext(creature);
			foreach (IHealthBarVisualGraftSource item in creature.Powers.OfType<IHealthBarVisualGraftSource>())
			{
				try
				{
					Merge(item.GetHealthBarVisualGraft(context));
				}
				catch (Exception value)
				{
					RitsuLibFramework.Logger.Warn($"[HealthBarGraft] Power '{item.GetType().FullName}' graft failed for '{creature}': {value}", 1);
				}
			}
			ProviderEntry[] array;
			using (SyncRoot.EnterScope())
			{
				array = Providers.Values.OrderBy((ProviderEntry e) => e.RegistrationOrder).ToArray();
			}
			ProviderEntry[] array2 = array;
			for (int num = 0; num < array2.Length; num++)
			{
				ProviderEntry providerEntry = array2[num];
				try
				{
					Merge(providerEntry.Source.GetHealthBarVisualGraft(context));
				}
				catch (Exception value2)
				{
					RitsuLibFramework.Logger.Warn($"[HealthBarGraft] Source '{providerEntry.SourceId}' from mod '{providerEntry.ModId}' failed for '{creature}': {value2}", 1);
				}
			}
			return new HealthBarVisualGraftMetrics(sumHp, color, material);
			void Merge(HealthBarVisualGraftMetrics metrics)
			{
				sumHp = (int)Math.Min(2147483647L, (long)sumHp + (long)Math.Max(0, metrics.GraftHp));
				Color? val = color;
				if (!val.HasValue)
				{
					color = metrics.GraftSelfModulate;
				}
				if (material == null)
				{
					material = metrics.GraftMaterial;
				}
			}
		}
	}
