		public static void RefreshForegroundOverlay(NHealthBar healthBar)
		{
			//IL_0217: Unknown result type (might be due to invalid IL or missing references)
			//IL_028c: Unknown result type (might be due to invalid IL or missing references)
			BaseLibHealthBarForecastBridge.TryRegisterSecondary();
			BaseLibVisualGraftBridge.TryRegisterSecondary();
			if (BaseLibHealthBarForecastBridge.ShouldRitsuRendererStandDown())
			{
				HideAllCustomSegments(healthBar);
				return;
			}
			bool flag = BaseLibHealthBarForecastBridge.ShouldSuppressBaseLibRenderer();
			Creature creature = healthBar._creature;
			if (creature.CurrentHp <= 0 || creature.IsInfiniteHpDisplayed())
			{
				if (flag)
				{
					HideBaseLibForecastContainers(healthBar);
				}
				HideAllCustomSegments(healthBar);
				return;
			}
			CustomSegment[] customSegments = GetCustomSegments(creature);
			if (customSegments.Length == 0)
			{
				if (flag)
				{
					HideBaseLibForecastContainers(healthBar);
				}
				HideAllCustomSegments(healthBar);
			}
			else
			{
				if (!EnsureUiState(healthBar))
				{
					return;
				}
				HealthBarForecastUiState healthBarForecastUiState = UiStates[healthBar];
				if (healthBarForecastUiState == null)
				{
					return;
				}
				EnsureOverlayOrder(healthBar, healthBarForecastUiState);
				int right = Math.Max(0, HealthBarVisualGraftRegistry.Aggregate(creature).GraftHp);
				int visualDenom = Math.Max(creature.MaxHp, SaturatingAddNonNegative(creature.CurrentHp, right));
				float maxFgWidth = GetMaxFgWidth(healthBar);
				Control hpForeground = healthBar._hpForeground;
				int num;
