namespace STS2RitsuLib.Combat.Healing
{
	/// <summary>
	///     <para xml:lang="en">Provides context for modifying an amount of healing received by a creature.</para>
	///     <para xml:lang="zh-CN">提供修正生物所受治疗量的上下文。</para>
	/// </summary>
	public sealed class HealContext
	{
		/// <summary>
		///     <para xml:lang="en">Gets the creature receiving healing.</para>
		///     <para xml:lang="zh-CN">获取接受治疗的生物。</para>
		/// </summary>
		public Creature Creature { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the amount passed to <c>CreatureCmd.Heal</c> before RitsuLib listeners modify it.</para>
		///     <para xml:lang="zh-CN">获取 RitsuLib 监听器修正前传给 <c>CreatureCmd.Heal</c> 的数值。</para>
		/// </summary>
		public decimal OriginalAmount { get; }

		/// <summary>
		///     <para xml:lang="en">Gets whether this heal command requests the vanilla healing animation.</para>
		///     <para xml:lang="zh-CN">获取此治疗命令是否请求播放原版治疗动画。</para>
		/// </summary>
		public bool PlayAnim { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the combat containing the creature, or <see langword="null" /> outside combat.</para>
		///     <para xml:lang="zh-CN">获取生物所在的战斗；非战斗治疗时为 <see langword="null" />。</para>
		/// </summary>
		public ICombatState? CombatState { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the run associated with this healing, if available.</para>
		///     <para xml:lang="zh-CN">获取与此次治疗关联的局内状态（如果有）。</para>
		/// </summary>
		public IRunState? RunState { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the amount of HP the creature can currently recover.</para>
		///     <para xml:lang="zh-CN">获取该生物当前可恢复的生命值。</para>
		/// </summary>
		public decimal MissingHp => Math.Max(0m, Creature.MaxHp - Creature.CurrentHp);

		internal HealContext(Creature creature, decimal originalAmount, bool playAnim)
		{
			Creature = creature;
			OriginalAmount = originalAmount;
			PlayAnim = playAnim;
			CombatState = creature.CombatState;
			Player player = creature.Player;
			object obj = ((player != null) ? player.RunState : null);
			if (obj == null)
			{
				ICombatState combatState = creature.CombatState;
				obj = ((combatState != null) ? combatState.RunState : null);
			}
			RunState = (IRunState?)obj;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Dispatches healing-amount hooks to models, capabilities, and registered global listeners.</para>
	///     <para xml:lang="zh-CN">将治疗量钩子分发给模型、模型能力和已注册的全局监听器。</para>
	/// </summary>
	public static class HealHook
	{
		private readonly record struct ListenerContext(IHealHookListener Listener, HealContext Context);

		private static readonly ModelHookListenerRegistry<IHealHookListener> GlobalListeners = new ModelHookListenerRegistry<IHealHookListener>();

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a process-wide listener. Effects owned by a model should normally implement
		///         <see cref="T:STS2RitsuLib.Combat.Healing.IHealHookListener" /> directly.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册进程级监听器。由模型持有的效果通常应直接实现 <see cref="T:STS2RitsuLib.Combat.Healing.IHealHookListener" />。
		///     </para>
		/// </summary>
		public static void RegisterGlobalListener(IHealHookListener listener)
		{
			GlobalListeners.Register(listener);
		}

		/// <summary>
		///     <para xml:lang="en">Applies healing-amount hooks and clamps the result to zero or greater.</para>
		///     <para xml:lang="zh-CN">应用治疗量钩子，并将结果限制为不小于零。</para>
		/// </summary>
		public static decimal ModifyAmount(HealContext context, decimal amount)
		{
			decimal amount2 = ApplyAdditive(context, amount);
			decimal amount3 = ApplyMultiplicative(context, amount2);
			decimal val = ApplyLate(context, amount3);
			return Math.Max(0m, val);
		}

		private static decimal ApplyAdditive(HealContext context, decimal amount)
		{
			return amount + IterateListeners(context).Sum((ListenerContext listenerContext) => listenerContext.Listener.ModifyHealAdditive(context, amount));
		}

		private static decimal ApplyMultiplicative(HealContext context, decimal amount)
		{
			return IterateListeners(context).Aggregate(amount, (decimal current, ListenerContext listenerContext) => current * listenerContext.Listener.ModifyHealMultiplicative(context, amount));
		}

		private static decimal ApplyLate(HealContext context, decimal amount)
		{
			return IterateListeners(context).Aggregate(amount, (decimal current, ListenerContext listenerContext) => listenerContext.Listener.ModifyHealAmount(listenerContext.Context, current));
		}

		private static IEnumerable<ListenerContext> IterateListeners(HealContext context)
		{
			if (context.RunState != null)
			{
				foreach (ModelHookListener<IHealHookListener> item in ModelHookListenerDispatcher.FromRun(context.RunState, context.CombatState, GlobalListeners))
				{
					yield return new ListenerContext(item.Listener, context);
				}
			}
			else
			{
				if (context.CombatState == null)
				{
					yield break;
				}
				foreach (ModelHookListener<IHealHookListener> item2 in ModelHookListenerDispatcher.FromCombat(context.CombatState, GlobalListeners))
				{
					yield return new ListenerContext(item2.Listener, context);
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Defines optional hooks for modifying creature healing.</para>
	///     <para xml:lang="zh-CN">定义修正生物治疗量的可选钩子。</para>
	/// </summary>
	public interface IHealHookListener
	{
		/// <summary>
		///     <para xml:lang="en">Returns an amount to add during the additive modifier pass.</para>
		///     <para xml:lang="zh-CN">返回在加法修正阶段要增加的数值。</para>
		/// </summary>
		decimal ModifyHealAdditive(HealContext context, decimal amount)
		{
			return 0m;
		}

		/// <summary>
		///     <para xml:lang="en">Returns a multiplier for the multiplicative modifier pass.</para>
		///     <para xml:lang="zh-CN">返回乘法修正阶段使用的倍率。</para>
		/// </summary>
		decimal ModifyHealMultiplicative(HealContext context, decimal amount)
		{
			return 1m;
		}

		/// <summary>
		///     <para xml:lang="en">Modifies the healing amount after the additive and multiplicative passes.</para>
		///     <para xml:lang="zh-CN">在加法和乘法修正阶段结束后修正治疗量。</para>
		/// </summary>
		decimal ModifyHealAmount(HealContext context, decimal amount)
		{
			return amount;
		}
	}
}
namespace STS2RitsuLib.Combat.Healing.Patches
{
	/// <summary>
	///     <para xml:lang="en">Applies RitsuLib healing-amount hooks before <see cref="M:MegaCrit.Sts2.Core.Commands.CreatureCmd.Heal(MegaCrit.Sts2.Core.Entities.Creatures.Creature,System.Decimal,System.Boolean)" /> resolves.</para>
	///     <para xml:lang="zh-CN">在 <see cref="M:MegaCrit.Sts2.Core.Commands.CreatureCmd.Heal(MegaCrit.Sts2.Core.Entities.Creatures.Creature,System.Decimal,System.Boolean)" /> 结算前应用 RitsuLib 治疗量钩子。</para>
	/// </summary>
	internal sealed class CreatureCmdHealHookPatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_creature_cmd_heal_amount_hooks";

		public static string Description => "Dispatch RitsuLib heal amount hooks for CreatureCmd.Heal";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1] { PatchTarget.Method(typeof(CreatureCmd), "Heal", typeof(Creature), typeof(decimal), typeof(bool)) };
		}

		[HarmonyAfter(new string[] { "BaseLib" })]
		[HarmonyPriority(0)]
		public static void Prefix(Creature creature, ref decimal amount, bool playAnim)
		{
			if (creature != null)
			{
				if (amount <= 0m)
				{
					amount = Math.Max(0m, amount);
				}
				else
				{
					amount = HealHook.ModifyAmount(new HealContext(creature, amount, playAnim), amount);
				}
			}
		}
	}
}
namespace STS2RitsuLib.Combat.HandSize
{
	/// <summary>
	///     <para xml:lang="en">
	///         Bridges BaseLib's maximum-hand-size support by detecting its active patches, extending its calculator
	///         with RitsuLib modifiers, and using its result as the base value when available.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         桥接 BaseLib 的手牌上限支持：检测其生效中的补丁，将 RitsuLib 修正接入其计算器，并在可用时以
	///         BaseLib 的结果为基础值。
	///     </para>
	/// </summary>
	internal static class BaseLibMaxHandSizeBridge
	{
		private static readonly Lock Gate;

		private static readonly Harmony Harmony;

		[ThreadStatic]
		private static int _suppressPostfixDepth;

		private static MethodInfo? _baseLibGetMaxHandSizeMethod;

		private static MethodInfo? _baseLibGetMaxHandSizeWithBaseMethod;

		private static MethodInfo? _baseLibGetMaxHandSizeFromCardMethod;

		private static Func<Player, int>? _baseLibGetMaxHandSize;

		private static bool _postfixPatched;

		private static bool _loggedResolveFailure;

		internal static void TryInitialize()
		{
			EnsureBaseLibPostfixPatched();
		}

		internal static bool IsBaseLibHandSizePatchActive()
		{
			if (!TryResolveBaseLibGetMaxHandSizeMethod(out MethodInfo _))
			{
				return false;
			}
			if (!IsPatchedByBaseLib(new ModPatchTarget(typeof(CardPileCmd), "CheckIfDrawIsPossibleAndShowThoughtBubbleIfNot", new Type[1] { typeof(Player) })) && !IsSetupPlayerTurnPatchedByBaseLib())
			{
				return IsPatchedByBaseLib(new ModPatchTarget(typeof(CardConsoleCmd), "Process", new Type[2]
				{
					typeof(Player),
					typeof(string[])
				}));
			}
			return true;
		}

		private static bool IsSetupPlayerTurnPatchedByBaseLib()
		{
			return IsPatchedByBaseLib(new ModPatchTarget(typeof(CombatManager), "SetupPlayerTurn", new Type[3]
			{
				typeof(CombatTurnState),
				typeof(Player),
				typeof(HookPlayerChoiceContext)
			}, (MethodType)6));
		}

		internal static bool IsBaseLibBaseAmountConsumer(CodeInstruction instruction)
		{
			if (instruction.operand is MethodInfo method)
			{
				if (!IsSameMethod(method, TryResolveBaseLibGetMaxHandSizeWithBaseMethod()))
				{
					return IsSameMethod(method, TryResolveBaseLibGetMaxHandSizeFromCardMethod());
				}
				return true;
			}
			return false;
		}

		internal static bool TryGetMaxHandSizeFromBaseLib(Player player, out int amount)
		{
			amount = 0;
			if (!TryGetBaseLibGetMaxHandSizeDelegate(out Func<Player, int> getter))
			{
				return false;
			}
			EnsureBaseLibPostfixPatched();
			try
			{
				_suppressPostfixDepth++;
				amount = getter(player);
				return true;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[MaxHandSize] BaseLib bridge invocation failed: " + ex.Message, 1);
			}
			finally
			{
				_suppressPostfixDepth = Math.Max(0, _suppressPostfixDepth - 1);
			}
			return false;
		}

		private static bool IsPatchedByBaseLib(ModPatchTarget target)
		{
			MethodBase methodBase = PatchTargetMethodResolver.Resolve(target);
			if (methodBase == null)
			{
				return false;
			}
			Patches patchInfo = Harmony.GetPatchInfo(methodBase);
			if (patchInfo == null)
			{
				return false;
			}
			if (!patchInfo.Prefixes.Any((Patch p) => p.owner == "BaseLib") && !patchInfo.Postfixes.Any((Patch p) => p.owner == "BaseLib") && !patchInfo.Transpilers.Any((Patch p) => p.owner == "BaseLib"))
			{
				return patchInfo.Finalizers.Any((Patch p) => p.owner == "BaseLib");
			}
			return true;
		}

		private static void EnsureBaseLibPostfixPatched()
		{
			//IL_006a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0076: Expected O, but got Unknown
			using (Gate.EnterScope())
			{
				if (_postfixPatched)
				{
					return;
				}
				MethodInfo methodInfo = TryResolveBaseLibGetMaxHandSizeWithBaseMethod();
				if (!(methodInfo == null))
				{
					MethodInfo methodInfo2 = AccessTools.Method(typeof(BaseLibMaxHandSizeBridge), "BaseLibGetMaxHandSizePostfix", (Type[])null, (Type[])null);
					if (methodInfo2 == null)
					{
						throw new MissingMethodException(typeof(BaseLibMaxHandSizeBridge).FullName, "BaseLibGetMaxHandSizePostfix");
					}
					Harmony.Patch((MethodBase)methodInfo, (HarmonyMethod)null, new HarmonyMethod(methodInfo2), (HarmonyMethod)null, (HarmonyMethod)null);
					_postfixPatched = true;
					RitsuLibFramework.Logger.Info("[MaxHandSize] BaseLib hand-size bridge postfix installed.", 1);
				}
			}
		}

		private static bool TryGetBaseLibGetMaxHandSizeDelegate(out Func<Player, int> getter)
		{
			using (Gate.EnterScope())
			{
				if (_baseLibGetMaxHandSize != null)
				{
					getter = _baseLibGetMaxHandSize;
					return true;
				}
				if (!TryResolveBaseLibGetMaxHandSizeMethod(out MethodInfo method))
				{
					getter = null;
					return false;
				}
				_baseLibGetMaxHandSize = method.CreateDelegate<Func<Player, int>>();
				getter = _baseLibGetMaxHandSize;
				return true;
			}
		}

		private static bool TryResolveBaseLibGetMaxHandSizeMethod(out MethodInfo method)
		{
			using (Gate.EnterScope())
			{
				if (_baseLibGetMaxHandSizeMethod != null)
				{
					method = _baseLibGetMaxHandSizeMethod;
					return true;
				}
				Type type = ResolveBaseLibMaxHandSizePatchType();
				if (type == null && !ExternalFrameworkRegistry.IsFrameworkPresent("baselib"))
				{
					method = null;
					return false;
				}
				MethodInfo methodInfo = type?.GetMethod("GetMaxHandSize", BindingFlags.Static | BindingFlags.Public, null, new Type[1] { typeof(Player) }, null);
				if (methodInfo == null)
				{
					if (!_loggedResolveFailure)
					{
						_loggedResolveFailure = true;
						RitsuLibFramework.Logger.Info("[MaxHandSize] BaseLib hand-size calculator not found. Using RitsuLib-only path.", 1);
					}
					method = null;
					return false;
				}
				_baseLibGetMaxHandSizeMethod = methodInfo;
				method = methodInfo;
				return true;
			}
		}

		private static MethodInfo? TryResolveBaseLibGetMaxHandSizeWithBaseMethod()
		{
			using (Gate.EnterScope())
			{
				if (_baseLibGetMaxHandSizeWithBaseMethod != null)
				{
					return _baseLibGetMaxHandSizeWithBaseMethod;
				}
				return _baseLibGetMaxHandSizeWithBaseMethod = ResolveBaseLibMaxHandSizePatchType()?.GetMethod("GetMaxHandSize", BindingFlags.Static | BindingFlags.Public, null, new Type[2]
				{
					typeof(Player),
					typeof(int)
				}, null);
			}
		}

		private static MethodInfo? TryResolveBaseLibGetMaxHandSizeFromCardMethod()
		{
			using (Gate.EnterScope())
			{
				if (_baseLibGetMaxHandSizeFromCardMethod != null)
				{
					return _baseLibGetMaxHandSizeFromCardMethod;
				}
				return _baseLibGetMaxHandSizeFromCardMethod = ResolveBaseLibMaxHandSizePatchType()?.GetMethod("GetMaxHandSizeFromCard", BindingFlags.Static | BindingFlags.NonPublic, null, new Type[2]
				{
					typeof(CardModel),
					typeof(int)
				}, null);
			}
		}

		private static bool IsSameMethod(MethodInfo method, MethodInfo? candidate)
		{
			if (candidate != null && method.Module == candidate.Module)
			{
				return method.MetadataToken == candidate.MetadataToken;
			}
			return false;
		}

		private static Type? ResolveBaseLibMaxHandSizePatchType()
		{
			Type type = ExternalFrameworkRegistry.ResolveType("BaseLib.Patches.Hooks.MaxHandSizePatch");
			if (type != null)
			{
				return type;
			}
			return (from assembly in AppDomain.CurrentDomain.GetAssemblies()
				select assembly.GetType("BaseLib.Patches.Hooks.MaxHandSizePatch")).OfType<Type>().FirstOrDefault();
		}

		private static void BaseLibGetMaxHandSizePostfix(Player player, ref int __result)
		{
			if (_suppressPostfixDepth <= 0)
			{
				__result = MaxHandSizeCalculator.ApplyHookListenerModifiers(player, __result);
			}
		}

		static BaseLibMaxHandSizeBridge()
		{
			//IL_000f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0019: Expected O, but got Unknown
			Gate = new Lock();
			Harmony = new Harmony("com.ritsukage.sts2-RitsuLib.interop.max_hand_size");
		}
	}
	/// <summary>
	///     <para xml:lang="en">Defines extensible modifiers for calculating a player's maximum hand size.</para>
	///     <para xml:lang="zh-CN">定义用于计算玩家手牌上限的可扩展修正器。</para>
	/// </summary>
	public interface IMaxHandSizeModifier
	{
		/// <summary>
		///     <para xml:lang="en">Modifies the maximum hand size during the early pass.</para>
		///     <para xml:lang="zh-CN">在早期阶段修正手牌上限。</para>
		/// </summary>
		int ModifyMaxHandSize(Player player, int currentMaxHandSize)
		{
			return currentMaxHandSize;
		}

		/// <summary>
		///     <para xml:lang="en">Modifies the maximum hand size during the late pass.</para>
		///     <para xml:lang="zh-CN">在后期阶段修正手牌上限。</para>
		/// </summary>
		int ModifyMaxHandSizeLate(Player player, int currentMaxHandSize)
		{
			return currentMaxHandSize;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Calculates effective maximum hand sizes.</para>
	///     <para xml:lang="zh-CN">计算实际手牌上限。</para>
	/// </summary>
	public static class MaxHandSizeCalculator
	{
		private const int DefaultMaxHandSize = 10;

		/// <summary>
		///     <para xml:lang="en">
		///         Calculates the effective maximum hand size for <paramref name="player" />. Uses BaseLib's value as
		///         the base when available, then applies RitsuLib hook-listener modifiers once.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         计算 <paramref name="player" /> 的实际手牌上限。BaseLib 的值可用时以其为基础，然后应用一次
		///         RitsuLib 钩子监听器修正。
		///     </para>
		/// </summary>
		public static int Calculate(Player player)
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			if (!BaseLibMaxHandSizeBridge.TryGetMaxHandSizeFromBaseLib(player, out var amount))
			{
				return ApplyHookListenerModifiers(player, 10);
			}
			return ApplyHookListenerModifiers(player, amount);
		}

		/// <summary>
		///     <para xml:lang="en">Applies combat hook-listener modifiers to an existing base hand size.</para>
		///     <para xml:lang="zh-CN">在现有基础手牌上限上应用战斗钩子监听器修正。</para>
		/// </summary>
		public static int ApplyHookListenerModifiers(Player player, int currentMaxHandSize)
		{
			ArgumentNullException.ThrowIfNull(player, "player");
			int seed = currentMaxHandSize;
			IMaxHandSizeModifier[] hookListenerModifiers = GetHookListenerModifiers(player);
			seed = hookListenerModifiers.Aggregate(seed, (int current, IMaxHandSizeModifier modifier) => modifier.ModifyMaxHandSize(player, current));
			seed = hookListenerModifiers.Aggregate(seed, (int current, IMaxHandSizeModifier modifier) => modifier.ModifyMaxHandSizeLate(player, current));
			return Math.Max(0, seed);
		}

		internal static int CalculateFromCardOwner(CardModel? card)
		{
			Player val = ((card != null) ? card.Owner : null);
			if (val == null)
			{
				return 10;
			}
			return Calculate(val);
		}

		private static IMaxHandSizeModifier[] GetHookListenerModifiers(Player player)
		{
			Creature creature = player.Creature;
			ICombatState val = ((creature != null) ? creature.CombatState : null);
			if (val == null)
			{
				return Array.Empty<IMaxHandSizeModifier>();
			}
			return (from entry in ModelHookListenerDispatcher.FromCombat<IMaxHandSizeModifier>(val, Array.Empty<AbstractModel>())
				select entry.Listener).ToArray();
		}
	}
	/// <summary>
	///     <para xml:lang="en">Installs RitsuLib maximum-hand-size patches.</para>
	///     <para xml:lang="zh-CN">安装 RitsuLib 手牌上限补丁。</para>
	/// </summary>
	internal static class MaxHandSizePatchInstaller
	{
		private const int DefaultMaxHandSize = 10;

		private static readonly Lock Gate = new Lock();

		private static readonly List<string> RewriteFailures = new List<string>();

		private static bool _patched;

		private static int _rewriteTargetCount;

		private static int _rewriteSuccessCount;

		private static int _ritsuLibRewriteTargetCount;

		private static int _baseLibDelegatedTargetCount;

		private static int _mixedRewriteTargetCount;

		private static readonly MethodInfo GetMaxHandSizeMethod = AccessTools.Method(typeof(MaxHandSizeCalculator), "Calculate", (Type[])null, (Type[])null) ?? throw new MissingMethodException(typeof(MaxHandSizeCalculator).FullName, "Calculate");

		private static readonly MethodInfo GetMaxHandSizeFromCardMethod = AccessTools.Method(typeof(MaxHandSizeCalculator), "CalculateFromCardOwner", (Type[])null, (Type[])null) ?? throw new MissingMethodException(typeof(MaxHandSizeCalculator).FullName, "CalculateFromCardOwner");

		private static readonly MethodInfo MaxCardsInHandGetter = AccessTools.PropertyGetter(typeof(CardPile), "MaxCardsInHand") ?? throw new MissingMethodException(typeof(CardPile).FullName, "MaxCardsInHand");

		internal static void EnsurePatched()
		{
			using (Gate.EnterScope())
			{
				if (_patched)
				{
					return;
				}
				RewriteFailures.Clear();
				_rewriteTargetCount = 0;
				_rewriteSuccessCount = 0;
				_ritsuLibRewriteTargetCount = 0;
				_baseLibDelegatedTargetCount = 0;
				_mixedRewriteTargetCount = 0;
				DynamicPatchBuilder builder = new DynamicPatchBuilder("max_hand_size");
				HarmonyMethod transpiler = FromMethodAfterBaseLib("PlayerArg0Transpiler");
				HarmonyMethod transpiler2 = FromMethodAfterBaseLib("PlayerArg1Transpiler");
				HarmonyMethod transpiler3 = FromMethodAfterBaseLib("StateMachineTranspiler");
				HarmonyMethod transpiler4 = FromMethodAfterBaseLib("CardOnPlayTranspiler");
				TryAddMethodPatch(builder, typeof(CardPileCmd), "CheckIfDrawIsPossibleAndShowThoughtBubbleIfNot", new Type[1] { typeof(Player) }, transpiler);
				MethodInfo asyncMethod = AccessTools.Method(typeof(CombatManager), "SetupPlayerTurn", new Type[3]
				{
					typeof(CombatTurnState),
					typeof(Player),
					typeof(HookPlayerChoiceContext)
				}, (Type[])null);
				TryAddAsyncMoveNextPatch(builder, asyncMethod, transpiler3, "Patch CombatManager.SetupPlayerTurn state machine max-hand-size constants");
