		private static HarmonyMethod FromMethodAfterBaseLib(string methodName)
		{
			HarmonyMethod val = DynamicPatchBuilder.FromMethod(typeof(MaxHandSizePatchInstaller), methodName);
			val.after = new string[1] { "BaseLib" };
