		private static void TryAddMethodPatch(DynamicPatchBuilder builder, Type targetType, string methodName, Type[] parameterTypes, HarmonyMethod? transpiler = null, HarmonyMethod? prefix = null)
		{
			try
			{
				builder.AddMethod(targetType, methodName, parameterTypes, prefix, null, transpiler, null, isCritical: false, $"Patch {targetType.Name}.{methodName} max-hand-size constants");
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[MaxHandSize] Skipped patch '{targetType.Name}.{methodName}': {ex.Message}", 1);
			}
		}

		private static void TryAddAsyncMoveNextPatch(DynamicPatchBuilder builder, MethodInfo? asyncMethod, HarmonyMethod transpiler, string description)
		{
			if (asyncMethod == null)
			{
				RitsuLibFramework.Logger.Warn("[MaxHandSize] Skip dynamic patch: missing async method for '" + description + "'.", 1);
				return;
			}
			MethodBase methodBase;
			try
			{
				methodBase = AccessTools.AsyncMoveNext((MethodBase)asyncMethod);
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn("[MaxHandSize] Skip dynamic patch '" + description + "': resolve MoveNext failed: " + ex.Message, 1);
				return;
			}
			if (methodBase == null)
			{
				RitsuLibFramework.Logger.Warn("[MaxHandSize] Skip dynamic patch '" + description + "': MoveNext not found.", 1);
			}
			else
			{
				builder.Add(methodBase, null, null, transpiler, null, isCritical: false, description);
			}
		}

		private static bool IsMaxHandSizeToken(CodeInstruction ins)
		{
			if (!HarmonyIl.LoadsInt32(ins, 10))
			{
				return HarmonyIl.IsCall(MaxCardsInHandGetter)(ins);
			}
			return true;
		}

		private static bool IsBaseLibBaseAmountToken(IReadOnlyList<CodeInstruction> code, int index)
		{
			if (index + 1 < code.Count && IsMaxHandSizeToken(code[index]))
			{
				return BaseLibMaxHandSizeBridge.IsBaseLibBaseAmountConsumer(code[index + 1]);
			}
			return false;
		}

		private static bool IsRitsuMaxHandSizeReplacementSite(IReadOnlyList<CodeInstruction> code, int index)
		{
			if (IsMaxHandSizeToken(code[index]))
			{
				return !IsBaseLibBaseAmountToken(code, index);
			}
			return false;
		}

		private static List<CodeInstruction> RewriteMaxHandSizeLoads(IEnumerable<CodeInstruction> instructions, Func<IReadOnlyList<CodeInstruction>, int, IReadOnlyList<CodeInstruction>> buildReplacement, string operation, MethodInfo alreadyInstalledCall, MethodBase? originalMethod)
		{
			HarmonyIlRewriter harmonyIlRewriter = HarmonyIlRewriter.From(instructions);
			int baseLibDelegatedSites = CountBaseLibDelegatedSites(harmonyIlRewriter.Code);
			HarmonyIlRewriteReport report = harmonyIlRewriter.ReplaceEach(operation, IsRitsuMaxHandSizeReplacementSite, buildReplacement, (IReadOnlyList<CodeInstruction> code) => ContainsCall(code, alreadyInstalledCall));
			WarnIfRewriteUnsatisfied(report);
			RecordRewriteResult(originalMethod, report, baseLibDelegatedSites);
			return harmonyIlRewriter.InstructionsChecked(operation);
		}

		private static IEnumerable<CodeInstruction> PlayerArg0Transpiler(IEnumerable<CodeInstruction> instructions, MethodBase __originalMethod)
		{
