		private static IEnumerable<CodeInstruction> StateMachineTranspiler(IEnumerable<CodeInstruction> instructions, MethodBase __originalMethod)
		{
			HarmonyIlRewriter harmonyIlRewriter = HarmonyIlRewriter.From(instructions);
			int baseLibDelegatedSites = CountBaseLibDelegatedSites(harmonyIlRewriter.Code);
			IReadOnlyList<CodeInstruction> loadPlayer = FindStateMachinePlayerLoad(harmonyIlRewriter);
			if (loadPlayer == null)
			{
				RecordRewriteFailure(__originalMethod, "Player load pattern not found");
				RitsuLibFramework.Logger.Warn("[MaxHandSize] " + FormatMethod(__originalMethod) + " could not resolve Player load pattern; skipped replacements.", 1);
				return harmonyIlRewriter.Instructions();
			}
			HarmonyIlRewriteReport report = harmonyIlRewriter.ReplaceEach("[MaxHandSize] State-machine max-hand-size replacement", IsRitsuMaxHandSizeReplacementSite, delegate
			{
				CodeInstruction[] array = HarmonyIl.CloneAll(loadPlayer);
				int num = 0;
				CodeInstruction[] array2 = (CodeInstruction[])(object)new CodeInstruction[1 + array.Length];
				ReadOnlySpan<CodeInstruction> readOnlySpan = new ReadOnlySpan<CodeInstruction>(array);
				readOnlySpan.CopyTo(new Span<CodeInstruction>(array2).Slice(num, readOnlySpan.Length));
				num += readOnlySpan.Length;
				array2[num] = HarmonyIl.Call(GetMaxHandSizeMethod);
				return new global::<>z__ReadOnlyArray<CodeInstruction>(array2);
			}, (IReadOnlyList<CodeInstruction> code) => ContainsCall(code, GetMaxHandSizeMethod));
			WarnIfRewriteUnsatisfied(report);
			RecordRewriteResult(__originalMethod, report, baseLibDelegatedSites);
			return harmonyIlRewriter.InstructionsChecked("[MaxHandSize] State-machine max-hand-size replacement");
		}

		private static IEnumerable<CodeInstruction> CardOnPlayTranspiler(IEnumerable<CodeInstruction> instructions, MethodBase __originalMethod)
		{
			HarmonyIlRewriter harmonyIlRewriter = HarmonyIlRewriter.From(instructions);
			int baseLibDelegatedSites = CountBaseLibDelegatedSites(harmonyIlRewriter.Code);
			IReadOnlyList<CodeInstruction> loadCard = FindStateMachineCardLoad(harmonyIlRewriter);
			if (loadCard == null)
			{
				RecordRewriteFailure(__originalMethod, "CardModel load pattern not found");
				RitsuLibFramework.Logger.Warn("[MaxHandSize] " + FormatMethod(__originalMethod) + " could not resolve CardModel load pattern; skipped replacements.", 1);
				return harmonyIlRewriter.Instructions();
			}
			HarmonyIlRewriteReport report = harmonyIlRewriter.ReplaceEach("[MaxHandSize] Card OnPlay max-hand-size replacement", IsRitsuMaxHandSizeReplacementSite, delegate
			{
				CodeInstruction[] array = HarmonyIl.CloneAll(loadCard);
				int num = 0;
				CodeInstruction[] array2 = (CodeInstruction[])(object)new CodeInstruction[1 + array.Length];
				ReadOnlySpan<CodeInstruction> readOnlySpan = new ReadOnlySpan<CodeInstruction>(array);
				readOnlySpan.CopyTo(new Span<CodeInstruction>(array2).Slice(num, readOnlySpan.Length));
				num += readOnlySpan.Length;
				array2[num] = HarmonyIl.Call(GetMaxHandSizeFromCardMethod);
				return new global::<>z__ReadOnlyArray<CodeInstruction>(array2);
			}, (IReadOnlyList<CodeInstruction> code) => ContainsCall(code, GetMaxHandSizeFromCardMethod));
			WarnIfRewriteUnsatisfied(report);
			RecordRewriteResult(__originalMethod, report, baseLibDelegatedSites);
			return harmonyIlRewriter.InstructionsChecked("[MaxHandSize] Card OnPlay max-hand-size replacement");
		}

		private static int CountBaseLibDelegatedSites(IReadOnlyList<CodeInstruction> code)
		{
			int num = 0;
			for (int i = 0; i < code.Count; i++)
			{
				if (IsBaseLibBaseAmountToken(code, i))
				{
					num++;
				}
			}
			return num;
		}

		private static void RecordRewriteResult(MethodBase? originalMethod, HarmonyIlRewriteReport report, int baseLibDelegatedSites)
		{
			_rewriteTargetCount++;
			bool succeeded = report.Succeeded;
			bool flag = baseLibDelegatedSites > 0;
			if (succeeded | flag)
			{
				_rewriteSuccessCount++;
				if (succeeded & flag)
				{
					_mixedRewriteTargetCount++;
				}
				else if (succeeded)
				{
					_ritsuLibRewriteTargetCount++;
				}
				else
				{
					_baseLibDelegatedTargetCount++;
				}
				RitsuLibFramework.Logger.Debug($"[MaxHandSize] {FormatMethod(originalMethod)}: {report.Applied} replacement(s), alreadySatisfied={report.AlreadySatisfied}, baseLibDelegatedSites={baseLibDelegatedSites}.", 1);
			}
			else
			{
				RewriteFailures.Add($"{FormatMethod(originalMethod)} ({report.Matches} RitsuLib match(es), {baseLibDelegatedSites} BaseLib-delegated site(s))");
			}
		}

		private static void RecordRewriteFailure(MethodBase? originalMethod, string reason)
		{
			_rewriteTargetCount++;
			RewriteFailures.Add(FormatMethod(originalMethod) + " (" + reason + ")");
		}

		private static string FormatMethod(MethodBase? method)
		{
			if (!(method == null))
			{
				return method.DeclaringType?.Name + "." + method.Name;
			}
			return "<unknown method>";
		}

		private static IReadOnlyList<CodeInstruction>? FindStateMachinePlayerLoad(HarmonyIlRewriter rewriter)
		{
			return FindStateMachineFieldLoad(rewriter, (FieldInfo field) => field.FieldType == typeof(Player), "[MaxHandSize] state-machine Player field load");
		}

		private static IReadOnlyList<CodeInstruction>? FindStateMachineCardLoad(HarmonyIlRewriter rewriter)
		{
			return FindStateMachineFieldLoad(rewriter, (FieldInfo field) => typeof(CardModel).IsAssignableFrom(field.FieldType), "[MaxHandSize] state-machine CardModel field load");
		}

		private static IReadOnlyList<CodeInstruction>? FindStateMachineFieldLoad(HarmonyIlRewriter rewriter, Func<FieldInfo, bool> fieldPredicate, string description)
		{
			HarmonyIlPattern pattern = HarmonyIlPattern.Sequence(HarmonyIl.IsLdarg(0), HarmonyIl.IsLdfld());
			return rewriter.FindMatches(pattern, description).Items.Where(delegate(HarmonyIlMatch match)
			{
				Func<FieldInfo, bool> func = fieldPredicate;
				HarmonyIlMatch harmonyIlMatch = match;
				return func(harmonyIlMatch.GetFieldOperand(rewriter.Code, 1));
			}).Select((Func<HarmonyIlMatch, IReadOnlyList<CodeInstruction>>)delegate(HarmonyIlMatch match)
			{
				CodeInstruction[] array = new CodeInstruction[2];
				HarmonyIlMatch harmonyIlMatch = match;
				array[0] = harmonyIlMatch.InstructionAt(rewriter.Code, 0).Clone();
				harmonyIlMatch = match;
				array[1] = harmonyIlMatch.InstructionAt(rewriter.Code, 1).Clone();
				return new global::<>z__ReadOnlyArray<CodeInstruction>((CodeInstruction[])(object)array);
			}).FirstOrDefault();
		}

		private static StringName GetShortcutOrDefault(NPlayerHand hand, int idx)
		{
			StringName[] selectCardShortcuts = hand._selectCardShortcuts;
			if (idx < 0 || idx >= selectCardShortcuts.Length)
			{
				return Sts2InputCompat.CancelCardPlayAction;
			}
			return selectCardShortcuts[idx];
		}

		private static IEnumerable<CodeInstruction> StartCardPlayTranspiler(IEnumerable<CodeInstruction> instructions)
		{
			FieldInfo fieldInfo = AccessTools.Field(typeof(NPlayerHand), "_selectCardShortcuts");
			FieldInfo fieldInfo2 = AccessTools.Field(typeof(NPlayerHand), "_draggedHolderIndex");
			MethodInfo getShortcutMethod = AccessTools.Method(typeof(MaxHandSizePatchInstaller), "GetShortcutOrDefault", (Type[])null, (Type[])null);
			HarmonyIlRewriter harmonyIlRewriter = HarmonyIlRewriter.From(instructions);
			if (fieldInfo == null || fieldInfo2 == null || getShortcutMethod == null)
			{
				return harmonyIlRewriter.Instructions();
			}
			HarmonyIlPattern pattern = HarmonyIlPattern.Sequence(HarmonyIl.IsLdarg(0), HarmonyIl.IsLdfld(fieldInfo), HarmonyIl.IsLdarg(0), HarmonyIl.IsLdfld(fieldInfo2), HarmonyIl.Is(OpCodes.Ldelem_Ref));
			HarmonyIlRewriteReport report = harmonyIlRewriter.TryReplaceFirst("[MaxHandSize] StartCardPlay shortcut bounds replacement", pattern, new global::<>z__ReadOnlyArray<CodeInstruction>((CodeInstruction[])(object)new CodeInstruction[4]
			{
				HarmonyIl.Ldarg(0),
				HarmonyIl.Ldarg(0),
				HarmonyIl.Ldfld(fieldInfo2),
				HarmonyIl.Call(getShortcutMethod)
			}), (IReadOnlyList<CodeInstruction> code) => ContainsCall(code, getShortcutMethod));
			WarnIfRewriteUnsatisfied(report);
			WarnIfFirstMatchWasAmbiguous(report);
			return harmonyIlRewriter.InstructionsChecked("[MaxHandSize] StartCardPlay shortcut bounds replacement");
		}

		private static bool ContainsCall(IReadOnlyList<CodeInstruction> code, MethodInfo method)
		{
			return code.Any(HarmonyIl.IsCall(method));
		}

		private static void WarnIfRewriteUnsatisfied(HarmonyIlRewriteReport report)
		{
			if (!report.Succeeded && report.Matches != 0)
			{
				RitsuLibFramework.Logger.Warn(report.Describe(), 1);
			}
		}

		private static void WarnIfFirstMatchWasAmbiguous(HarmonyIlRewriteReport report)
		{
			if (report.Matches > 1 && report.Applied == 1)
			{
				RitsuLibFramework.Logger.Warn($"{report.Operation} found {report.Matches} matches; only the first was rewritten.", 1);
			}
		}

		private static float GetInferredHalfSpread(int handSize)
		{
			float num = (float)(Math.Min(handSize, 14) - 10) / 4f;
			num = Mathf.Clamp(num, 0f, 1f);
			return Mathf.Lerp(610f, 690f, num);
		}

		private static bool GetPositionPrefix(int handSize, int cardIndex, ref Vector2 __result)
		{
			//IL_00b5: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ba: Unknown result type (might be due to invalid IL or missing references)
			if (handSize <= 10)
			{
				return true;
			}
			if (cardIndex < 0 || cardIndex >= handSize)
			{
				throw new ArgumentOutOfRangeException("cardIndex", $"Card index {cardIndex} is outside hand size {handSize}.");
			}
			float inferredHalfSpread = GetInferredHalfSpread(handSize);
			float num = Math.Max(72f, 88f - (float)(handSize - 10) * 1.5f);
			float num2 = 2f * (float)cardIndex / ((float)handSize - 1f) - 1f;
			float num3 = inferredHalfSpread * num2;
			float num4 = Math.Min(18f, -64f + num * num2 * num2);
			__result = new Vector2(num3, num4);
			return false;
		}

		private static bool GetAnglePrefix(int handSize, int cardIndex, ref float __result)
		{
			if (handSize <= 10)
			{
				return true;
			}
			if (cardIndex < 0 || cardIndex >= handSize)
			{
				throw new ArgumentOutOfRangeException("cardIndex", $"Card index {cardIndex} is outside hand size {handSize}.");
			}
			float inferredHalfSpread = GetInferredHalfSpread(handSize);
			float num = Math.Max(72f, 88f - (float)(handSize - 10) * 1.5f);
			float num2 = 2f * (float)cardIndex / ((float)handSize - 1f) - 1f;
			float num3 = 2f * num * num2;
			float num4 = Math.Max(1f, inferredHalfSpread);
			float num5 = Mathf.RadToDeg(Mathf.Atan2(num3, num4));
			__result = Mathf.Clamp(num5, -18f, 18f);
			return false;
		}

		private static bool GetScalePrefix(int handSize, ref Vector2 __result)
		{
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_002e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0033: Unknown result type (might be due to invalid IL or missing references)
			if (handSize <= 10)
			{
				return true;
			}
			float val = 0.64f * MathF.Pow(0.95f, handSize - 11);
			__result = Vector2.One * Math.Max(0.48f, val);
			return false;
		}
	}
