	/// <summary>
	///     <para xml:lang="en">Bridges BaseLib custom-target predicates when BaseLib is loaded.</para>
	///     <para xml:lang="zh-CN">在 BaseLib 已加载时桥接其自定义目标谓词。</para>
	/// </summary>
	internal static class BaseLibTargetTypeBridge
	{
		private interface ITargetPredicateMap
		{
			bool TryGetValue(TargetType targetType, out TargetPredicate predicate);
		}

		private sealed class PlayerAwareTargetPredicateMap(IReadOnlyDictionary<TargetType, Func<Creature, Player, bool>> predicates) : ITargetPredicateMap
		{
			public bool TryGetValue(TargetType targetType, out TargetPredicate predicate)
			{
				//IL_0006: Unknown result type (might be due to invalid IL or missing references)
				if (!predicates.TryGetValue(targetType, out Func<Creature, Player, bool> value))
				{
					predicate = null;
					return false;
				}
				predicate = value.Invoke;
				return true;
			}
		}

		private sealed class LegacyTargetPredicateMap(IReadOnlyDictionary<TargetType, Func<Creature, bool>> predicates) : ITargetPredicateMap
		{
			public bool TryGetValue(TargetType targetType, out TargetPredicate predicate)
			{
				//IL_000c: Unknown result type (might be due to invalid IL or missing references)
				if (!predicates.TryGetValue(targetType, out Func<Creature, bool> resolved))
				{
					predicate = null;
					return false;
				}
				predicate = (Creature creature, Player _) => resolved(creature);
				return true;
			}
		}

		private delegate bool TargetPredicate(Creature creature, Player player);

		private const string BaseLibCustomTargetTypeName = "BaseLib.Patches.Features.CustomTargetType";

		private static readonly Lock Gate = new Lock();

		private static ITargetPredicateMap? _singleTargeting;

		private static ITargetPredicateMap? _multiTargeting;

		private static bool _loggedMissingType;

		private static bool _loggedMissingFields;

		internal static bool IsCustomSingleTargetType(TargetType targetType)
		{
			//IL_000a: Unknown result type (might be due to invalid IL or missing references)
			TargetPredicate predicate;
			if (TryGetSingleTargeting(out ITargetPredicateMap singleTargeting))
			{
				return singleTargeting.TryGetValue(targetType, out predicate);
			}
			return false;
		}

		internal static bool IsCustomMultiTargetType(TargetType targetType)
		{
			//IL_000a: Unknown result type (might be due to invalid IL or missing references)
			TargetPredicate predicate;
			if (TryGetMultiTargeting(out ITargetPredicateMap multiTargeting))
			{
				return multiTargeting.TryGetValue(targetType, out predicate);
			}
			return false;
		}

		internal static bool TryIsAllowedSingleTarget(TargetType targetType, Creature creature, Player player, out bool allowed)
		{
			//IL_0046: Unknown result type (might be due to invalid IL or missing references)
			//IL_004c: Expected I4, but got Unknown
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			allowed = false;
			if (!TryGetSingleTargeting(out ITargetPredicateMap singleTargeting) || !singleTargeting.TryGetValue(targetType, out TargetPredicate predicate))
			{
				return false;
			}
			try
			{
				allowed = predicate(creature, player);
				return true;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[CardTargeting] BaseLib single-target predicate failed for {(int)targetType}: {ex.Message}", 1);
				return false;
			}
		}

		internal static bool TryShouldIncludeMultiTarget(TargetType targetType, Creature creature, Player player, out bool include)
		{
			//IL_0046: Unknown result type (might be due to invalid IL or missing references)
			//IL_004c: Expected I4, but got Unknown
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			include = false;
			if (!TryGetMultiTargeting(out ITargetPredicateMap multiTargeting) || !multiTargeting.TryGetValue(targetType, out TargetPredicate predicate))
			{
				return false;
			}
			try
			{
				include = predicate(creature, player);
				return true;
			}
			catch (Exception ex)
			{
				RitsuLibFramework.Logger.Warn($"[CardTargeting] BaseLib multi-target predicate failed for {(int)targetType}: {ex.Message}", 1);
				return false;
			}
		}

		private static bool TryGetSingleTargeting(out ITargetPredicateMap singleTargeting)
		{
			EnsureResolved();
			singleTargeting = _singleTargeting;
			return singleTargeting != null;
		}

		private static bool TryGetMultiTargeting(out ITargetPredicateMap multiTargeting)
		{
			EnsureResolved();
			multiTargeting = _multiTargeting;
			return multiTargeting != null;
		}

		private static void EnsureResolved()
		{
			if (_singleTargeting != null && _multiTargeting != null)
			{
				return;
			}
			using (Gate.EnterScope())
			{
				if (_singleTargeting != null && _multiTargeting != null)
				{
					return;
				}
				Type type = ResolveBaseLibCustomTargetType();
				if (!(type == null))
				{
					_singleTargeting = ReadPredicateMap(type, "SingleTargeting");
					_multiTargeting = ReadPredicateMap(type, "MultiTargeting");
					if (_singleTargeting != null && _multiTargeting != null)
					{
						RitsuLibFramework.Logger.Info("[CardTargeting] BaseLib custom TargetType bridge resolved.", 1);
					}
					else if (!_loggedMissingFields)
					{
						_loggedMissingFields = true;
						RitsuLibFramework.Logger.Info("[CardTargeting] BaseLib custom TargetType registry fields were not found.", 1);
					}
				}
			}
		}

		private static Type? ResolveBaseLibCustomTargetType()
		{
			Type type = ExternalFrameworkRegistry.ResolveType("BaseLib.Patches.Features.CustomTargetType");
			if (type != null)
			{
				return type;
			}
			foreach (Mod item in Sts2ModManagerCompat.EnumerateLoadedModsWithAssembly())
			{
				foreach (Assembly assembly in Sts2ModManagerCompat.GetAssemblies(item))
				{
					Type type2 = assembly.GetType("BaseLib.Patches.Features.CustomTargetType", throwOnError: false);
					if (type2 != null)
					{
						return type2;
					}
				}
			}
			Type type3 = (from assembly in AppDomain.CurrentDomain.GetAssemblies()
				select assembly.GetType("BaseLib.Patches.Features.CustomTargetType", throwOnError: false)).OfType<Type>().FirstOrDefault();
			if (type3 != null)
			{
				return type3;
			}
			if (_loggedMissingType)
			{
				return null;
			}
			_loggedMissingType = true;
			RitsuLibFramework.Logger.Info("[CardTargeting] BaseLib custom TargetType type not found.", 1);
			return null;
		}

		private static ITargetPredicateMap? ReadPredicateMap(Type type, string fieldName)
		{
			object obj = type.GetField(fieldName, BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(null);
			if (!(obj is IReadOnlyDictionary<TargetType, Func<Creature, Player, bool>> predicates))
			{
				if (obj is IReadOnlyDictionary<TargetType, Func<Creature, bool>> predicates2)
				{
					return new LegacyTargetPredicateMap(predicates2);
				}
				return null;
			}
			return new PlayerAwareTargetPredicateMap(predicates);
		}
	}
	/// <summary>
