	public static class CardModelTargetingExtensions
	{
		/// <summary>
		///     <para xml:lang="en">Resolves targets from the card's current <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.TargetType" />.</para>
		///     <para xml:lang="zh-CN">根据卡牌当前的 <see cref="P:MegaCrit.Sts2.Core.Models.CardModel.TargetType" /> 解析目标。</para>
		/// </summary>
		/// <param name="card">
		///     <para xml:lang="en">The card whose targets are resolved.</para>
		///     <para xml:lang="zh-CN">待解析目标的卡牌。</para>
		/// </param>
		/// <param name="selectedTarget">
		///     <para xml:lang="en">
		///         The selected target for selection-based vanilla or custom single-target types. When omitted, those
		///         types resolve no targets; <see cref="F:MegaCrit.Sts2.Core.Entities.Cards.TargetType.Self" /> still resolves to the owner.
		///     </para>
		///     <para xml:lang="zh-CN">
