			//IL_0034: Unknown result type (might be due to invalid IL or missing references)
			//IL_0035: Unknown result type (might be due to invalid IL or missing references)
			//IL_005b: Expected I4, but got Unknown
			//IL_01ac: Unknown result type (might be due to invalid IL or missing references)
			//IL_0212: Unknown result type (might be due to invalid IL or missing references)
			//IL_01c7: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(card, "card");
			ICombatState combatState = card.CombatState;
			TargetType targetType = card.TargetType;
			switch ((int)targetType)
			{
			case 2:
			case 5:
			case 6:
			{
				if (selectedTarget == null)
				{
					return new List<Creature>();
				}
				if (!card.IsValidTarget(selectedTarget))
				{
					return new List<Creature>();
				}
				int num = 1;
				List<Creature> list2 = new List<Creature>(num);
				CollectionsMarshal.SetCount(list2, num);
				CollectionsMarshal.AsSpan(list2)[0] = selectedTarget;
				return list2;
			}
			case 7:
				return ((combatState != null) ? combatState.PlayerCreatures.Where((Creature c) => c.IsAlive).ToList() : null) ?? new List<Creature>();
			case 3:
				return ((combatState != null) ? combatState.HittableEnemies.ToList() : null) ?? new List<Creature>();
			case 4:
			{
				List<Creature> list3 = ((combatState != null) ? combatState.HittableEnemies.ToList() : null);
				if (list3 == null || list3.Count == 0)
				{
					return new List<Creature>();
				}
				Creature val = card.Owner.RunState.Rng.CombatTargets.NextItem<Creature>((IEnumerable<Creature>)list3);
				if (val != null)
				{
					int num = 1;
					List<Creature> list4 = new List<Creature>(num);
					CollectionsMarshal.SetCount(list4, num);
					CollectionsMarshal.AsSpan(list4)[0] = val;
					return list4;
				}
				return new List<Creature>();
			}
			case 0:
				return new List<Creature>();
			case 1:
			{
				int num = 1;
				List<Creature> list5 = new List<Creature>(num);
				CollectionsMarshal.SetCount(list5, num);
				CollectionsMarshal.AsSpan(list5)[0] = card.Owner.Creature;
				return list5;
			}
			default:
				if (CustomTargetTypeResolver.IsCustomSingleTargetType(card.TargetType))
				{
					if (selectedTarget == null)
					{
						return new List<Creature>();
					}
					if (!(CustomTargetTypeResolver.TryIsAllowedSingleTarget(card.TargetType, CustomTargetContext.ForCard(selectedTarget, card), out var allowed) & allowed))
					{
						return new List<Creature>();
					}
					int num = 1;
					List<Creature> list = new List<Creature>(num);
					CollectionsMarshal.SetCount(list, num);
					CollectionsMarshal.AsSpan(list)[0] = selectedTarget;
					return list;
				}
				if (!CustomTargetTypeResolver.IsCustomMultiTargetType(card.TargetType))
