	/// <summary>
	///     <para xml:lang="en">Stores RitsuLib custom target types and their selection predicates.</para>
	///     <para xml:lang="zh-CN">存储 RitsuLib 自定义目标类型及其选择谓词。</para>
	/// </summary>
	internal static class CustomTargetTypeRegistry
	{
		private enum CustomTargetTypeKind
		{
			Single,
			Multi
		}

		private readonly record struct CustomTargetTypeRegistration(string Id, CustomTargetTypeKind Kind);

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<TargetType, Func<CustomTargetContext, bool>> SingleTargetPredicates = new Dictionary<TargetType, Func<CustomTargetContext, bool>>();

		private static readonly Dictionary<TargetType, Func<Creature, Player, bool>> MultiTargetPredicates = new Dictionary<TargetType, Func<Creature, Player, bool>>();

		private static readonly Dictionary<TargetType, CustomTargetTypeRegistration> Registrations = new Dictionary<TargetType, CustomTargetTypeRegistration>();

		/// <summary>
		///     <para xml:lang="en">Determines whether RitsuLib registered <paramref name="type" />.</para>
		///     <para xml:lang="zh-CN">判断 RitsuLib 是否注册了 <paramref name="type" />。</para>
		/// </summary>
		internal static bool IsRitsuCustom(TargetType type)
		{
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			using (SyncRoot.EnterScope())
			{
				return Registrations.ContainsKey(type);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Determines whether <paramref name="type" /> has a single-target predicate.</para>
		///     <para xml:lang="zh-CN">判断 <paramref name="type" /> 是否具有单体目标谓词。</para>
		/// </summary>
		internal static bool IsCustomSingleTargetType(TargetType type)
		{
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			using (SyncRoot.EnterScope())
			{
				return SingleTargetPredicates.ContainsKey(type);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Determines whether <paramref name="type" /> has a multi-target predicate.</para>
		///     <para xml:lang="zh-CN">判断 <paramref name="type" /> 是否具有群体目标谓词。</para>
		/// </summary>
		internal static bool IsCustomMultiTargetType(TargetType type)
		{
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			using (SyncRoot.EnterScope())
			{
				return MultiTargetPredicates.ContainsKey(type);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Finds and evaluates a single-target predicate without source-model context.</para>
		///     <para xml:lang="zh-CN">查找并执行不含来源模型上下文的单体目标谓词。</para>
		/// </summary>
		internal static bool TryIsAllowedSingleTarget(TargetType type, Creature creature, Player player, out bool allowed)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			return TryIsAllowedSingleTarget(type, new CustomTargetContext(creature, player), out allowed);
		}

		/// <summary>
		///     <para xml:lang="en">Finds and evaluates a single-target predicate with full source context.</para>
		///     <para xml:lang="zh-CN">查找并使用完整来源上下文执行单体目标谓词。</para>
		/// </summary>
		internal static bool TryIsAllowedSingleTarget(TargetType type, CustomTargetContext context, out bool allowed)
		{
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			Func<CustomTargetContext, bool> value;
			using (SyncRoot.EnterScope())
			{
				SingleTargetPredicates.TryGetValue(type, out value);
			}
			if (value == null)
			{
				allowed = false;
				return false;
			}
			allowed = value(context);
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Finds and evaluates a multi-target predicate.</para>
		///     <para xml:lang="zh-CN">查找并执行群体目标谓词。</para>
		/// </summary>
		internal static bool TryShouldIncludeMultiTarget(TargetType type, Creature creature, Player player, out bool include)
		{
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			Func<Creature, Player, bool> value;
			using (SyncRoot.EnterScope())
			{
				MultiTargetPredicates.TryGetValue(type, out value);
			}
			if (value == null)
			{
				include = false;
				return false;
			}
			include = value(creature, player);
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a creature-only single-target predicate.</para>
		///     <para xml:lang="zh-CN">注册或替换仅接收生物的单体目标谓词。</para>
		/// </summary>
		internal static void RegisterSingleTargetType(TargetType type, Func<Creature, bool> predicate)
		{
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			RegisterSingleTargetTypeWithContext(type, (CustomTargetContext context) => predicate(context.TargetCreature));
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a player-aware single-target predicate.</para>
		///     <para xml:lang="zh-CN">注册或替换可接收玩家的单体目标谓词。</para>
		/// </summary>
		internal static void RegisterSingleTargetType(TargetType type, Func<Creature, Player, bool> predicate)
		{
