		/// <summary>
		///     <para xml:lang="en">Registers the built-in target definitions without clearing mod registrations.</para>
		///     <para xml:lang="zh-CN">注册内置目标定义，且不清除模组注册项。</para>
		/// </summary>
		internal static void RegisterBuiltIns()
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			//IL_0052: Unknown result type (might be due to invalid IL or missing references)
			//IL_007b: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a4: Unknown result type (might be due to invalid IL or missing references)
			//IL_00cd: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f6: Unknown result type (might be due to invalid IL or missing references)
			//IL_011f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0148: Unknown result type (might be due to invalid IL or missing references)
			//IL_0171: Unknown result type (might be due to invalid IL or missing references)
			//IL_019a: Unknown result type (might be due to invalid IL or missing references)
			//IL_01c3: Unknown result type (might be due to invalid IL or missing references)
			RegisterSingleTargetType(CustomTargetType.Anyone, (Creature target) => target != null && target.IsAlive && !target.IsPet);
			RegisterMultiTargetType(CustomTargetType.Everyone, (Creature target) => target != null && target.IsAlive && !target.IsPet);
			RegisterSingleTargetType(CustomTargetType.AnyAttackingEnemy, delegate(Creature target)
			{
				if (target != null && target.IsAlive && target.IsEnemy)
				{
					MonsterModel monster = target.Monster;
					if (monster != null)
					{
						return monster.IntendsToAttack;
					}
				}
				return false;
			});
			RegisterMultiTargetType(CustomTargetType.AllAttackingEnemies, delegate(Creature target)
			{
				if (target != null && target.IsAlive && target.IsEnemy)
				{
					MonsterModel monster = target.Monster;
					if (monster != null)
					{
						return monster.IntendsToAttack;
					}
				}
				return false;
			});
			RegisterSingleTargetType(CustomTargetType.AnyBlockingEnemy, (Creature target) => target != null && target.IsAlive && target.IsEnemy && target.Block > 0);
			RegisterMultiTargetType(CustomTargetType.AllBlockingEnemies, (Creature target) => target != null && target.IsAlive && target.IsEnemy && target.Block > 0);
			RegisterSingleTargetType(CustomTargetType.AnyNonBlockingEnemy, (Creature target) => target != null && target.IsAlive && target.IsEnemy && target.Block == 0);
			RegisterMultiTargetType(CustomTargetType.AllNonBlockingEnemies, (Creature target) => target != null && target.IsAlive && target.IsEnemy && target.Block == 0);
			RegisterMultiTargetType(CustomTargetType.AllLowestHpEnemies, (Creature target) => target != null && target.IsAlive && target.IsEnemy && IsEnemyHpExtremum(target, lowest: true));
			RegisterMultiTargetType(CustomTargetType.AllHighestHpEnemies, (Creature target) => target != null && target.IsAlive && target.IsEnemy && IsEnemyHpExtremum(target, lowest: false));
			RegisterSingleTargetType(CustomTargetType.AnyFullLifeEnemy, (Creature target) => target != null && target.IsAlive && target.IsEnemy && target.CurrentHp == target.MaxHp);
			RegisterMultiTargetType(CustomTargetType.AllFullLifeEnemies, (Creature target) => target != null && target.IsAlive && target.IsEnemy && target.CurrentHp == target.MaxHp);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Determines whether <paramref name="target" /> is tied for the lowest or highest current HP among
		///         living enemies.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         判断 <paramref name="target" /> 的当前生命值是否在存活敌人中并列最低或最高。
		///     </para>
		/// </summary>
		private static bool IsEnemyHpExtremum(Creature target, bool lowest)
		{
			ICombatState combatState = target.CombatState;
			List<Creature> list = ((combatState != null) ? combatState.Enemies.Where((Creature e) => e.IsAlive).ToList() : null);
			if (list == null || list.Count == 0)
			{
				return false;
			}
			int num = (lowest ? list.Min((Creature e) => e.CurrentHp) : list.Max((Creature e) => e.CurrentHp));
			return target.CurrentHp == num;
		}

		private static void Register(TargetType type, string? id, CustomTargetTypeKind kind, Delegate predicate)
		{
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a6: Expected I4, but got Unknown
			//IL_00ce: Unknown result type (might be due to invalid IL or missing references)
			//IL_00df: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ed: Unknown result type (might be due to invalid IL or missing references)
			//IL_00fe: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			using (SyncRoot.EnterScope())
			{
				string text = id;
				if (Registrations.TryGetValue(type, out var value))
				{
					if (text == null)
					{
						text = value.Id;
					}
					if (value.Kind != kind)
					{
						throw new InvalidOperationException($"TargetType '{text}' is already registered as {value.Kind}; it cannot also be registered as {kind}.");
					}
				}
				if (text == null)
				{
					text = ((int)type).ToString();
				}
				Registrations[type] = new CustomTargetTypeRegistration(text, kind);
				switch (kind)
				{
				case CustomTargetTypeKind.Single:
					SingleTargetPredicates[type] = (Func<CustomTargetContext, bool>)predicate;
					MultiTargetPredicates.Remove(type);
					break;
				case CustomTargetTypeKind.Multi:
					MultiTargetPredicates[type] = (Func<Creature, Player, bool>)predicate;
					SingleTargetPredicates.Remove(type);
					break;
				default:
					throw new ArgumentOutOfRangeException("kind", kind, null);
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Resolves custom target types from RitsuLib and compatible external registries.</para>
	///     <para xml:lang="zh-CN">从 RitsuLib 及兼容的外部注册表中解析自定义目标类型。</para>
