	internal static class CustomTargetTypeSelectionContext
	{
		private readonly record struct Source(Player Player, CardModel? Card, PotionModel? Potion);

		private sealed class Popper(NTargetManager manager) : IDisposable
		{
			private bool _disposed;

			public void Dispose()
			{
				if (!_disposed)
				{
					_disposed = true;
					Pop(manager);
				}
			}
		}

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<NTargetManager, Stack<Source>> Sources = new Dictionary<NTargetManager, Stack<Source>>();

		internal static IDisposable PushCard(NTargetManager manager, CardModel card)
		{
			return Push(manager, new Source(card.Owner, card, null));
		}

		internal static IDisposable PushPotion(NTargetManager manager, PotionModel potion)
		{
			return Push(manager, new Source(potion.Owner, null, potion));
		}

		internal static CustomTargetContext CreateContext(NTargetManager manager, Creature targetCreature, Player fallbackPlayer)
		{
			using (SyncRoot.EnterScope())
			{
				if (Sources.TryGetValue(manager, out Stack<Source> value) && value.TryPeek(out var result))
				{
					return new CustomTargetContext(targetCreature, result.Player, result.Card, result.Potion);
				}
			}
			return new CustomTargetContext(targetCreature, fallbackPlayer);
		}

		private static IDisposable Push(NTargetManager manager, Source source)
		{
			using (SyncRoot.EnterScope())
			{
				if (!Sources.TryGetValue(manager, out Stack<Source> value))
				{
					value = new Stack<Source>();
					Sources.Add(manager, value);
				}
				value.Push(source);
			}
			return new Popper(manager);
		}

		private static void Pop(NTargetManager manager)
		{
			using (SyncRoot.EnterScope())
			{
				if (Sources.TryGetValue(manager, out Stack<Source> value))
				{
					value.Pop();
					if (value.Count == 0)
					{
						Sources.Remove(manager);
					}
				}
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Resolves potion targets according to their target type.</para>
	///     <para xml:lang="zh-CN">根据药水的目标类型解析目标。</para>
	/// </summary>
	public static class PotionModelTargetingExtensions
	{
		/// <summary>
		///     <para xml:lang="en">Resolves targets from the potion's current <see cref="P:MegaCrit.Sts2.Core.Models.PotionModel.TargetType" />.</para>
		///     <para xml:lang="zh-CN">根据药水当前的 <see cref="P:MegaCrit.Sts2.Core.Models.PotionModel.TargetType" /> 解析目标。</para>
		/// </summary>
		/// <param name="potion">
		///     <para xml:lang="en">The potion whose targets are resolved.</para>
		///     <para xml:lang="zh-CN">待解析目标的药水。</para>
		/// </param>
		/// <param name="selectedTarget">
		///     <para xml:lang="en">
		///         The selected target for selection-based vanilla or custom single-target types. When omitted, those
		///         types resolve no targets; <see cref="F:MegaCrit.Sts2.Core.Entities.Cards.TargetType.Self" /> still resolves to the owner when valid.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         基于选择的原版或自定义单体目标类型所用的已选目标。省略时这些类型不解析出目标；
		///         <see cref="F:MegaCrit.Sts2.Core.Entities.Cards.TargetType.Self" /> 在有效时仍解析为药水所有者。
		///     </para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The targets resolved for the potion.</para>
		///     <para xml:lang="zh-CN">为该药水解析出的目标。</para>
		/// </returns>
		/// <remarks>
		///     <para xml:lang="en">
		///         Resolving <see cref="F:MegaCrit.Sts2.Core.Entities.Cards.TargetType.RandomEnemy" /> advances the owner's combat-target RNG.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         解析 <see cref="F:MegaCrit.Sts2.Core.Entities.Cards.TargetType.RandomEnemy" /> 会推进所有者的战斗目标随机数生成器。
		///     </para>
		/// </remarks>
		public static List<Creature> GetTargets(this PotionModel potion, Creature? selectedTarget = null)
		{
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0040: Unknown result type (might be due to invalid IL or missing references)
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
			//IL_006b: Expected I4, but got Unknown
			//IL_00ba: Unknown result type (might be due to invalid IL or missing references)
			//IL_01d5: Unknown result type (might be due to invalid IL or missing references)
			//IL_023e: Unknown result type (might be due to invalid IL or missing references)
			//IL_01f0: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(potion, "potion");
			Creature creature = potion.Owner.Creature;
			ICombatState combatState = creature.CombatState;
			TargetType targetType = potion.TargetType;
			switch ((int)targetType)
			{
			case 2:
			case 5:
			case 6:
			{
				if (selectedTarget == null)
				{
					return new List<Creature>();
				}
				if (!IsValidTarget(potion, selectedTarget))
				{
					return new List<Creature>();
				}
				int num = 1;
				List<Creature> list4 = new List<Creature>(num);
				CollectionsMarshal.SetCount(list4, num);
				CollectionsMarshal.AsSpan(list4)[0] = selectedTarget;
				return list4;
			}
			case 7:
				return ((combatState != null) ? (from c in combatState.GetCreaturesOnSide(creature.Side)
					where c.IsAlive
					select c).ToList() : null) ?? new List<Creature>();
			case 3:
				return ((combatState != null) ? combatState.HittableEnemies.ToList() : null) ?? new List<Creature>();
			case 4:
			{
				List<Creature> list2 = ((combatState != null) ? combatState.HittableEnemies.ToList() : null);
				if (list2 == null || list2.Count == 0)
				{
					return new List<Creature>();
				}
				Creature val = potion.Owner.RunState.Rng.CombatTargets.NextItem<Creature>((IEnumerable<Creature>)list2);
				if (val != null)
				{
					int num = 1;
					List<Creature> list3 = new List<Creature>(num);
					CollectionsMarshal.SetCount(list3, num);
					CollectionsMarshal.AsSpan(list3)[0] = val;
					return list3;
				}
				return new List<Creature>();
			}
			case 0:
			case 8:
				return new List<Creature>();
			case 1:
			{
				if (!IsValidTarget(potion, selectedTarget ?? creature))
				{
					return new List<Creature>();
				}
				int num = 1;
				List<Creature> list5 = new List<Creature>(num);
				CollectionsMarshal.SetCount(list5, num);
				CollectionsMarshal.AsSpan(list5)[0] = creature;
				return list5;
			}
			default:
				if (CustomTargetTypeResolver.IsCustomSingleTargetType(potion.TargetType))
				{
					if (selectedTarget == null)
					{
						return new List<Creature>();
					}
					if (!(CustomTargetTypeResolver.TryIsAllowedSingleTarget(potion.TargetType, CustomTargetContext.ForPotion(selectedTarget, potion), out var allowed) & allowed))
					{
						return new List<Creature>();
					}
					int num = 1;
					List<Creature> list = new List<Creature>(num);
					CollectionsMarshal.SetCount(list, num);
					CollectionsMarshal.AsSpan(list)[0] = selectedTarget;
					return list;
				}
				if (!CustomTargetTypeResolver.IsCustomMultiTargetType(potion.TargetType))
				{
					return new List<Creature>();
				}
				return ((combatState != null) ? combatState.Creatures.Where(delegate(Creature c)
				{
					//IL_0006: Unknown result type (might be due to invalid IL or missing references)
					bool include;
					return CustomTargetTypeResolver.TryShouldIncludeMultiTarget(potion.TargetType, c, potion.Owner, out include) & include;
				}).ToList() : null) ?? new List<Creature>();
			}
		}

		private static bool IsValidTarget(PotionModel potion, Creature? target)
		{
			return potion.IsValidTarget(target);
		}
	}
