		public static async Task AfterAttackHit(AttackHitContext context)
		{
			foreach (ListenerEntry item in IterateListeners(context.CombatState, context.Attack.ModelSource, (AbstractModel)context.CardSource))
			{
				await Invoke(context, item, (IAttackHitHookListener listener, AttackHitContext ctx) => listener.AfterAttackHit(ctx));
			}
		}

		private static async Task Invoke(AttackHitContext context, ListenerEntry entry, Func<IAttackHitHookListener, AttackHitContext, Task> callback)
		{
			if (entry.Model == null)
			{
				await callback(entry.Listener, context);
				return;
			}
			context.ChoiceContext.PushModel(entry.Model);
			try
			{
				await callback(entry.Listener, context);
				entry.Model.InvokeExecutionFinished();
			}
			finally
			{
				context.ChoiceContext.PopModel(entry.Model);
			}
		}

		private static IEnumerable<ListenerEntry> IterateListeners(ICombatState combatState, params AbstractModel?[] extraModels)
		{
			return from entry in ModelHookListenerDispatcher.FromCombat<IAttackHitHookListener>(combatState, extraModels)
				select new ListenerEntry(entry.Listener, entry.Model);
		}

		private static AttackHitContext? TryCreateContext(PlayerChoiceContext choiceContext, IReadOnlyList<Creature> targets, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource, CardPlay? cardPlay, AttackCommand attack, int hitIndex, decimal totalHitCount)
		{
			//IL_002e: Unknown result type (might be due to invalid IL or missing references)
			object obj;
			if (attack == null)
			{
				obj = null;
			}
			else
			{
				Creature attacker = attack.Attacker;
				obj = ((attacker != null) ? attacker.CombatState : null);
			}
			ICombatState val = (ICombatState)obj;
			if (attack == null || val == null)
			{
				return null;
			}
			return new AttackHitContext(val, choiceContext, attack, targets, hitIndex, totalHitCount, amount, props, dealer, cardSource, cardPlay);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Defines optional hooks for individual attack hits.</para>
	///     <para xml:lang="zh-CN">定义单次攻击命中的可选钩子。</para>
	/// </summary>
	public interface IAttackHitHookListener
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Runs before the hit's damage command. Game commands may be awaited here, and mutable inputs on
		///         <see cref="T:STS2RitsuLib.Combat.AttackHits.AttackHitContext" /> affect only this hit.
		///     </para>
		///     <para xml:lang="zh-CN">
