		///         只影响此次命中。
		///     </para>
		/// </summary>
		Task BeforeAttackHit(AttackHitContext context)
		{
			return Task.CompletedTask;
		}

		/// <summary>
		///     <para xml:lang="en">Runs after the hit's damage command resolves.</para>
		///     <para xml:lang="zh-CN">在此次命中的伤害命令结算后运行。</para>
		/// </summary>
		Task AfterAttackHit(AttackHitContext context)
		{
			return Task.CompletedTask;
		}
	}
}
namespace STS2RitsuLib.Combat.AttackHits.Patches
{
	/// <summary>
	///     <para xml:lang="en">
	///         Redirects each damage call in <see cref="M:MegaCrit.Sts2.Core.Commands.Builders.AttackCommand.Execute(MegaCrit.Sts2.Core.GameActions.Multiplayer.PlayerChoiceContext)" /> through <see cref="T:STS2RitsuLib.Combat.AttackHits.AttackHitHook" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将 <see cref="M:MegaCrit.Sts2.Core.Commands.Builders.AttackCommand.Execute(MegaCrit.Sts2.Core.GameActions.Multiplayer.PlayerChoiceContext)" /> 中每次命中的伤害调用重定向到
	///         <see cref="T:STS2RitsuLib.Combat.AttackHits.AttackHitHook" />。
	///     </para>
	/// </summary>
	internal sealed class AttackCommandExecuteHitHookPatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_attack_command_execute_hit_hooks";

		public static string Description => "Dispatch RitsuLib before/after hooks for every AttackCommand hit";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1] { PatchTarget.AsyncMethod<AttackCommand>("Execute", new Type[1] { typeof(PlayerChoiceContext) }) };
		}

		[HarmonyAfter(new string[] { "BaseLib" })]
		[HarmonyPriority(0)]
		public static IEnumerable<CodeInstruction> Transpiler(IEnumerable<CodeInstruction> instructions, MethodBase __originalMethod)
		{
			Type type = __originalMethod.DeclaringType ?? throw new InvalidOperationException("[AttackHitHook] Redirect per-hit CreatureCmd.Damage call: async state machine type could not be resolved.");
			MethodInfo fromMethod = HarmonyIl.RequireMethod(AccessTools.Method(typeof(CreatureCmd), "Damage", new Type[7]
			{
				typeof(PlayerChoiceContext),
				typeof(IEnumerable<Creature>),
				typeof(decimal),
				typeof(ValueProp),
				typeof(Creature),
				typeof(CardModel),
				typeof(CardPlay)
			}, (Type[])null), "[AttackHitHook] Redirect per-hit CreatureCmd.Damage call");
			MethodInfo wrapperMethod = HarmonyIl.RequireMethod(AccessTools.Method(typeof(AttackHitHook), "DamageWithAttackHitHooks", new Type[10]
			{
				typeof(PlayerChoiceContext),
				typeof(IEnumerable<Creature>),
				typeof(decimal),
				typeof(ValueProp),
				typeof(Creature),
				typeof(CardModel),
				typeof(CardPlay),
				typeof(AttackCommand),
				typeof(int),
				typeof(decimal)
			}, (Type[])null), "[AttackHitHook] Redirect per-hit CreatureCmd.Damage call");
			HarmonyIlRewriter harmonyIlRewriter = HarmonyIlRewriter.From(instructions);
			if (!TryResolveStateFields(type, out FieldInfo attackField, out FieldInfo hitIndexField, out FieldInfo totalHitCountField))
			{
				throw new InvalidOperationException("[AttackHitHook] Redirect per-hit CreatureCmd.Damage call: AttackCommand.Execute state fields could not be resolved on " + type.FullName + ".");
			}
			HarmonyIlRewriteReport report = HarmonyAsyncIl.ReplaceAwaitedCalls(harmonyIlRewriter, "[AttackHitHook] Redirect per-hit CreatureCmd.Damage call", fromMethod, (HarmonyAsyncAwaitSite _) => new global::<>z__ReadOnlyArray<CodeInstruction>((CodeInstruction[])(object)new CodeInstruction[7]
			{
				HarmonyIl.Ldarg(0),
				HarmonyIl.Ldfld(attackField),
				HarmonyIl.Ldarg(0),
				HarmonyIl.Ldfld(hitIndexField),
				HarmonyIl.Ldarg(0),
				HarmonyIl.Ldfld(totalHitCountField),
				HarmonyIl.Call(wrapperMethod)
			}), (IReadOnlyList<CodeInstruction> code) => code.Any((CodeInstruction instruction) => HarmonyIl.IsCallTo(instruction, wrapperMethod)));
			return harmonyIlRewriter.InstructionsChecked(report);
		}

		private static bool TryResolveStateFields(Type stateMachineType, out FieldInfo attackField, out FieldInfo hitIndexField, out FieldInfo totalHitCountField)
		{
			FieldInfo[] fields = stateMachineType.GetFields(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			attackField = fields.FirstOrDefault((FieldInfo field) => field.FieldType == typeof(AttackCommand));
			hitIndexField = fields.FirstOrDefault((FieldInfo field) => field.FieldType == typeof(int) && field.Name.Contains("<i>", StringComparison.Ordinal));
			totalHitCountField = fields.FirstOrDefault((FieldInfo field) => field.FieldType == typeof(decimal) && field.Name.Contains("<attackCount>", StringComparison.Ordinal));
			if (attackField != null && hitIndexField != null)
			{
				return totalHitCountField != null;
			}
			return false;
		}
	}
}
