		private static readonly Dictionary<string, ModCardTagDefinition> Definitions = new Dictionary<string, ModCardTagDefinition>(StringComparer.OrdinalIgnoreCase);

		private static readonly Dictionary<CardTag, ModCardTagDefinition> DefinitionsByCardTag = new Dictionary<CardTag, ModCardTagDefinition>();

		private readonly Logger _logger;

