		public static ModCardTagRegistry For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (SyncRoot.EnterScope())
			{
				if (Registries.TryGetValue(modId, out ModCardTagRegistry value))
				{
					return value;
				}
				ModCardTagRegistry modCardTagRegistry = new ModCardTagRegistry(modId);
				Registries[modId] = modCardTagRegistry;
				return modCardTagRegistry;
			}
		}

		internal static void FreezeRegistrations(string reason)
		{
			ModCardTagRegistry[] array;
			using (SyncRoot.EnterScope())
			{
				if (IsFrozen)
				{
					return;
				}
				IsFrozen = true;
				foreach (ModCardTagRegistry value in Registries.Values)
				{
					value._freezeReason = reason;
				}
				array = Registries.Values.ToArray();
			}
			ModCardTagRegistry[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				array2[i]._logger.Info("[CardTags] Card tag registration is now frozen (" + reason + ").", 1);
			}
		}

