		private ModCardTagDefinition RegisterCore(string id)
		{
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0023: Unknown result type (might be due to invalid IL or missing references)
			//IL_002b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0100: Unknown result type (might be due to invalid IL or missing references)
			//IL_0143: Unknown result type (might be due to invalid IL or missing references)
			//IL_014e: Expected I4, but got Unknown
			EnsureMutable("register card tags");
			string text = NormalizeId(id);
			CardTag value = DynamicEnumValueRegistry<CardTag>.Register(_modId, text).Value;
			ModCardTagDefinition modCardTagDefinition = new ModCardTagDefinition(_modId, text, value);
			using (SyncRoot.EnterScope())
			{
				EnsureMutable("register card tags");
				if (Definitions.TryGetValue(text, out ModCardTagDefinition value2))
				{
					if (!StringComparer.OrdinalIgnoreCase.Equals(value2.ModId, modCardTagDefinition.ModId))
					{
						throw new InvalidOperationException($"Card tag '{text}' is already registered by mod '{value2.ModId}'; mod '{modCardTagDefinition.ModId}' cannot re-register it.");
					}
					return value2;
				}
				Definitions[text] = modCardTagDefinition;
				DefinitionsByCardTag[value] = modCardTagDefinition;
			}
			_logger.Info($"[CardTags] Registered tag: {text} (CardTag=0x{(int)value:X8})", 1);
			return modCardTagDefinition;
		}

		private void EnsureMutable(string operation)
		{
			if (!IsFrozen)
			{
				return;
			}
			throw new InvalidOperationException($"Cannot {operation} after card tag registration has been frozen ({_freezeReason ?? "unknown"}). " + "Register tags from your mod initializer before model initialization.");
		}

		private static string NormalizeId(string id)
		{
			return id.Trim();
		}
	}
