	/// <summary>
	///     <para xml:lang="en">
	///         Converts <see cref="T:System.Collections.Generic.HashSet`1" /> values of <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardTag" /> to and from JSON arrays.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在 <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardTag" /> 的 <see cref="T:System.Collections.Generic.HashSet`1" /> 值与 JSON 数组之间进行转换。
	///     </para>
	/// </summary>
	public sealed class CardTagHashSetJsonConverter : JsonConverter<HashSet<CardTag>>
	{
		private static readonly CardTagJsonConverter ElementConverter = new CardTagJsonConverter();

		/// <inheritdoc />
		public override HashSet<CardTag>? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
		{
