				ElementConverter.Write(writer, item, options);
			}
			writer.WriteEndArray();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Converts card tags between JSON strings or integers and <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardTag" /> values.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         在 JSON 字符串或整数与 <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardTag" /> 值之间转换卡牌标签。
	///     </para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         Registered mod tags are written as their IDs. Named vanilla values are written as enum names,
	///         and unnamed values are written as 32-bit integers.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         已注册的模组标签写为其 ID；有名称的原版值写为枚举名，未命名值写为 32 位整数。
	///     </para>
	/// </remarks>
	public sealed class CardTagJsonConverter : JsonConverter<CardTag>
	{
		/// <inheritdoc />
		public override CardTag Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
		{
			//IL_0042: Unknown result type (might be due to invalid IL or missing references)
			switch (reader.TokenType)
			{
			case JsonTokenType.String:
			{
				string text = reader.GetString();
				if (string.IsNullOrWhiteSpace(text))
				{
					return (CardTag)0;
				}
				if (!ModCardTagRegistry.TryResolveCardTag(text, out var value))
				{
					throw new JsonException("Unknown CardTag id or name: '" + text + "'.");
				}
				return value;
			}
			case JsonTokenType.Number:
				return (CardTag)reader.GetInt32();
			default:
				throw new JsonException($"Unexpected token for CardTag: {reader.TokenType}.");
			}
		}

		/// <inheritdoc />
		public override void Write(Utf8JsonWriter writer, CardTag value, JsonSerializerOptions options)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			//IL_0025: Unknown result type (might be due to invalid IL or missing references)
			if (ModCardTagRegistry.TryGetId(value, out string id))
			{
				writer.WriteStringValue(id);
				return;
			}
			string name = Enum.GetName<CardTag>(value);
			if (name != null)
			{
				writer.WriteStringValue(name);
			}
			else
			{
				writer.WriteNumberValue(Convert.ToInt32(value));
			}
		}
	}
