			foreach (ICardTypeTextModifier source in IterateHookModifiers(card, seen))
			{
				foreach (LocString item3 in GetTypeModifiersSafely(source, card, () => source.GetTypeModifiers(card)))
				{
					yield return new ModifierEntry(item3, source);
				}
			}
		}

		private static IEnumerable<ICardTypeTextModifier> IterateHookModifiers(CardModel card, HashSet<ICardTypeTextModifier> seen)
		{
			IRunState runState = card.RunState;
			if (runState != null)
			{
				foreach (ModelHookListener<ICardTypeTextModifier> item in ModelHookListenerDispatcher.FromRun(runState, card.CombatState, GlobalModifiers))
				{
					if (seen.Add(item.Listener))
					{
						yield return item.Listener;
					}
				}
				yield break;
			}
			ICombatState combatState = card.CombatState;
			if (combatState != null)
			{
				foreach (ModelHookListener<ICardTypeTextModifier> item2 in ModelHookListenerDispatcher.FromCombat(combatState, GlobalModifiers))
				{
					if (seen.Add(item2.Listener))
					{
						yield return item2.Listener;
					}
				}
				yield break;
			}
			ICardTypeTextModifier[] array = GlobalModifiers.Snapshot();
			foreach (ICardTypeTextModifier cardTypeTextModifier in array)
			{
				if (seen.Add(cardTypeTextModifier))
				{
					yield return cardTypeTextModifier;
				}
			}
		}

		private static bool ReferencesTypeArgument(LocString modifier)
		{
			return modifier.GetRawText().Contains("{Type}", StringComparison.Ordinal);
		}

		private static IReadOnlyList<LocString> GetTypeModifiersSafely(object source, CardModel card, Func<IEnumerable<LocString>> getModifiers)
		{
			try
			{
				return getModifiers()?.Where((LocString modifier) => modifier != null).ToArray() ?? Array.Empty<LocString>();
			}
			catch (Exception exception)
			{
				WarnFailure(source, card, exception);
				return Array.Empty<LocString>();
			}
		}

		private static void WarnFailure(object source, CardModel card, Exception exception)
		{
			if (source is IModelCapability source2)
			{
				ModelCapabilityDiagnostics.WarnFailure("card display/type-text", (AbstractModel)(object)card, source2, exception);
				return;
			}
			RitsuLibFramework.Logger.Warn($"[CardTypeText] Modifier source '{source.GetType().FullName}' failed for {((AbstractModel)card).Id}: " + exception, 1);
		}
	}
}
namespace STS2RitsuLib.Cards.Transforms
{
	/// <summary>
	///     <para xml:lang="en">Describes one completed base-game card transformation.</para>
	///     <para xml:lang="zh-CN">描述一次已完成的游戏本体卡牌转化。</para>
	/// </summary>
	/// <param name="Original">
	///     <para xml:lang="en">Card that was transformed.</para>
	///     <para xml:lang="zh-CN">被转化的卡牌。</para>
	/// </param>
	/// <param name="Replacement">
	///     <para xml:lang="en">Card that replaced <paramref name="Original" /> after base-game modifiers.</para>
	///     <para xml:lang="zh-CN">经过游戏本体修正后替换 <paramref name="Original" /> 的卡牌。</para>
	/// </param>
	/// <param name="OriginalPile">
	///     <para xml:lang="en">Pile that contained <paramref name="Original" /> before the transformation.</para>
	///     <para xml:lang="zh-CN">转化前包含 <paramref name="Original" /> 的牌堆。</para>
	/// </param>
	/// <param name="OriginalPileIndex">
	///     <para xml:lang="en">
	///         Index of <paramref name="Original" /> in <paramref name="OriginalPile" /> before the
	///         transformation.
	///     </para>
	///     <para xml:lang="zh-CN">转化前 <paramref name="Original" /> 在 <paramref name="OriginalPile" /> 中的索引。</para>
	/// </param>
	public readonly record struct ModCardTransformContext(CardModel Original, CardModel Replacement, CardPile OriginalPile, int OriginalPileIndex);
	/// <summary>
	///     <para xml:lang="en">Provides per-mod registration for base-game card-transformation listeners.</para>
	///     <para xml:lang="zh-CN">提供按模组注册游戏本体卡牌转化监听器的功能。</para>
	/// </summary>
	public sealed class ModCardTransformRegistry
	{
		private sealed record ListenerEntry(string ModId, string ListenerId, Func<ModCardTransformContext, bool> Predicate, Func<ModCardTransformContext, Task> Listener, long RegistrationOrder);

		private static readonly Lock SyncRoot = new Lock();

		private static readonly Dictionary<string, ModCardTransformRegistry> Registries = new Dictionary<string, ModCardTransformRegistry>(StringComparer.OrdinalIgnoreCase);

		private static readonly Dictionary<(string ModId, string ListenerId), ListenerEntry> Listeners = new Dictionary<(string, string), ListenerEntry>();

		private static long _nextRegistrationOrder;

		private readonly string _modId;

		private ModCardTransformRegistry(string modId)
		{
			_modId = modId;
		}

		/// <summary>
		///     <para xml:lang="en">Gets the transformation registry for <paramref name="modId" />, creating it on first use.</para>
		///     <para xml:lang="zh-CN">获取 <paramref name="modId" /> 的转化注册表，并在首次使用时创建。</para>
		/// </summary>
		public static ModCardTransformRegistry For(string modId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(modId, "modId");
			using (SyncRoot.EnterScope())
			{
				if (Registries.TryGetValue(modId, out ModCardTransformRegistry value))
				{
					return value;
				}
				ModCardTransformRegistry modCardTransformRegistry = new ModCardTransformRegistry(modId);
				Registries[modId] = modCardTransformRegistry;
				return modCardTransformRegistry;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a listener for every completed base-game card transformation.</para>
		///     <para xml:lang="zh-CN">注册或替换监听器，以接收每次已完成的游戏本体卡牌转化。</para>
		/// </summary>
		public void Register(string listenerId, Action<ModCardTransformContext> listener)
		{
			ArgumentNullException.ThrowIfNull(listener, "listener");
			Register(listenerId, (ModCardTransformContext _) => true, delegate(ModCardTransformContext context)
			{
				listener(context);
				return Task.CompletedTask;
			});
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers or replaces an asynchronous listener for every completed base-game card
		///         transformation.
		///     </para>
		///     <para xml:lang="zh-CN">注册或替换异步监听器，以接收每次已完成的游戏本体卡牌转化。</para>
		/// </summary>
		public void Register(string listenerId, Func<ModCardTransformContext, Task> listener)
		{
			ArgumentNullException.ThrowIfNull(listener, "listener");
			Register(listenerId, (ModCardTransformContext _) => true, listener);
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a listener with a custom predicate.</para>
		///     <para xml:lang="zh-CN">注册或替换带自定义谓词的监听器。</para>
		/// </summary>
		public void Register(string listenerId, Func<ModCardTransformContext, bool> predicate, Action<ModCardTransformContext> listener)
		{
			ArgumentNullException.ThrowIfNull(listener, "listener");
			Register(listenerId, predicate, delegate(ModCardTransformContext context)
			{
				listener(context);
				return Task.CompletedTask;
			});
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces an asynchronous listener with a custom predicate.</para>
		///     <para xml:lang="zh-CN">注册或替换带自定义谓词的异步监听器。</para>
		/// </summary>
		public void Register(string listenerId, Func<ModCardTransformContext, bool> predicate, Func<ModCardTransformContext, Task> listener)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(listenerId, "listenerId");
			ArgumentNullException.ThrowIfNull(predicate, "predicate");
			ArgumentNullException.ThrowIfNull(listener, "listener");
			using (SyncRoot.EnterScope())
			{
				(string, string) key = (_modId, listenerId);
				long registrationOrder = (Listeners.TryGetValue(key, out ListenerEntry value) ? value.RegistrationOrder : _nextRegistrationOrder++);
				Listeners[key] = new ListenerEntry(_modId, listenerId, predicate, listener, registrationOrder);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a typed listener for an original and replacement card pair.</para>
		///     <para xml:lang="zh-CN">注册或替换针对原卡牌与替换卡牌类型组合的监听器。</para>
		/// </summary>
		public void Register<TOriginal, TReplacement>(string listenerId, Action<TOriginal, TReplacement> listener) where TOriginal : CardModel where TReplacement : CardModel
		{
			ArgumentNullException.ThrowIfNull(listener, "listener");
			Register(listenerId, (ModCardTransformContext context) => context.Original is TOriginal && context.Replacement is TReplacement, delegate(ModCardTransformContext context)
			{
				listener((TOriginal)(object)context.Original, (TReplacement)(object)context.Replacement);
				return Task.CompletedTask;
			});
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a typed asynchronous listener for an original and replacement card pair.</para>
		///     <para xml:lang="zh-CN">注册或替换针对原卡牌与替换卡牌类型组合的异步监听器。</para>
		/// </summary>
		public void Register<TOriginal, TReplacement>(string listenerId, Func<TOriginal, TReplacement, Task> listener) where TOriginal : CardModel where TReplacement : CardModel
		{
			ArgumentNullException.ThrowIfNull(listener, "listener");
			Register(listenerId, (ModCardTransformContext context) => context.Original is TOriginal && context.Replacement is TReplacement, (ModCardTransformContext context) => listener((TOriginal)(object)context.Original, (TReplacement)(object)context.Replacement));
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a listener for cards transformed from <typeparamref name="TOriginal" />.</para>
		///     <para xml:lang="zh-CN">注册或替换监听器，以处理从 <typeparamref name="TOriginal" /> 转化而来的卡牌。</para>
		/// </summary>
		public void RegisterFrom<TOriginal>(string listenerId, Action<TOriginal, CardModel> listener) where TOriginal : CardModel
		{
			ArgumentNullException.ThrowIfNull(listener, "listener");
			Register(listenerId, (ModCardTransformContext context) => context.Original is TOriginal, delegate(ModCardTransformContext context)
			{
				listener((TOriginal)(object)context.Original, context.Replacement);
				return Task.CompletedTask;
			});
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers or replaces an asynchronous listener for cards transformed from
		///         <typeparamref name="TOriginal" />.
		///     </para>
		///     <para xml:lang="zh-CN">注册或替换异步监听器，以处理从 <typeparamref name="TOriginal" /> 转化而来的卡牌。</para>
		/// </summary>
		public void RegisterFrom<TOriginal>(string listenerId, Func<TOriginal, CardModel, Task> listener) where TOriginal : CardModel
		{
			ArgumentNullException.ThrowIfNull(listener, "listener");
			Register(listenerId, (ModCardTransformContext context) => context.Original is TOriginal, (ModCardTransformContext context) => listener((TOriginal)(object)context.Original, context.Replacement));
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers or replaces a listener for cards transformed into
		///         <typeparamref name="TReplacement" />.
		///     </para>
		///     <para xml:lang="zh-CN">注册或替换监听器，以处理转化为 <typeparamref name="TReplacement" /> 的卡牌。</para>
		/// </summary>
		public void RegisterTo<TReplacement>(string listenerId, Action<CardModel, TReplacement> listener) where TReplacement : CardModel
		{
			ArgumentNullException.ThrowIfNull(listener, "listener");
			Register(listenerId, (ModCardTransformContext context) => context.Replacement is TReplacement, delegate(ModCardTransformContext context)
			{
				listener(context.Original, (TReplacement)(object)context.Replacement);
				return Task.CompletedTask;
			});
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers or replaces an asynchronous listener for cards transformed into
		///         <typeparamref name="TReplacement" />.
		///     </para>
		///     <para xml:lang="zh-CN">注册或替换异步监听器，以处理转化为 <typeparamref name="TReplacement" /> 的卡牌。</para>
		/// </summary>
		public void RegisterTo<TReplacement>(string listenerId, Func<CardModel, TReplacement, Task> listener) where TReplacement : CardModel
		{
			ArgumentNullException.ThrowIfNull(listener, "listener");
			Register(listenerId, (ModCardTransformContext context) => context.Replacement is TReplacement, (ModCardTransformContext context) => listener(context.Original, (TReplacement)(object)context.Replacement));
		}

		/// <summary>
		///     <para xml:lang="en">Removes a listener registered by this mod.</para>
		///     <para xml:lang="zh-CN">移除此模组注册的监听器。</para>
		/// </summary>
		public bool Unregister(string listenerId)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(listenerId, "listenerId");
			using (SyncRoot.EnterScope())
			{
				return Listeners.Remove((_modId, listenerId));
			}
		}

		internal static async Task NotifyTransformedAsync(CardModel original, CardModel replacement, CardPile originalPile, int originalPileIndex)
		{
			ArgumentNullException.ThrowIfNull(original, "original");
			ArgumentNullException.ThrowIfNull(replacement, "replacement");
			ArgumentNullException.ThrowIfNull(originalPile, "originalPile");
			ModCardTransformContext context = new ModCardTransformContext(original, replacement, originalPile, originalPileIndex);
			ListenerEntry[] array;
			using (SyncRoot.EnterScope())
			{
				array = Listeners.Values.OrderBy((ListenerEntry listenerEntry) => listenerEntry.RegistrationOrder).ToArray();
			}
			ListenerEntry[] array2 = array;
			foreach (ListenerEntry entry in array2)
			{
				try
				{
					if (entry.Predicate(context))
					{
						await entry.Listener(context);
					}
				}
				catch (Exception value)
				{
					RitsuLibFramework.Logger.Warn($"[ModCardTransformRegistry] Listener '{entry.ModId}/{entry.ListenerId}' failed for {((AbstractModel)original).Id}: {value}", 1);
					throw;
				}
			}
		}
	}
}
namespace STS2RitsuLib.Cards.Transforms.Patches
{
	internal sealed class CardCmdTransformPatch : IPatchMethod
	{
		internal readonly record struct TransformSnapshot(CardModel Original, CardPile? Pile, int PileIndex, int InputIndex);

		internal sealed class TransformCaptureState
		{
			public TransformSnapshot[] Snapshots { get; set; } = Array.Empty<TransformSnapshot>();
		}

		public static string PatchId => "ritsulib_card_cmd_transform";

		public static string Description => "Notify registered listeners after CardCmd.Transform";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(CardCmd), "Transform", new Type[3]
				{
					typeof(IEnumerable<CardTransformation>),
					typeof(Rng),
					typeof(CardPreviewStyle)
				})
			};
		}

		public static void Prefix(ref IEnumerable<CardTransformation> transformations, out TransformCaptureState __state)
		{
			__state = new TransformCaptureState();
			transformations = Capture(transformations, __state);
		}

		public static void Postfix(TransformCaptureState __state, ref Task<IEnumerable<CardPileAddResult>> __result)
		{
			__result = LifecyclePatchTaskBridge.After(__result, (IEnumerable<CardPileAddResult> results) => NotifyAsync(__state.Snapshots, results));
		}

		private static async Task NotifyAsync(TransformSnapshot[] originals, IEnumerable<CardPileAddResult> results)
		{
			CardPileAddResult[] resultsArray = results.ToArray();
			int count = Math.Min(originals.Length, resultsArray.Length);
			for (int i = 0; i < count; i++)
			{
				CardPileAddResult val = resultsArray[i];
				if (val.success && val.cardAdded != null)
				{
					TransformSnapshot transformSnapshot = originals[i];
					if (transformSnapshot.Pile != null)
					{
						await ModCardTransformRegistry.NotifyTransformedAsync(transformSnapshot.Original, val.cardAdded, transformSnapshot.Pile, transformSnapshot.PileIndex);
					}
				}
			}
		}

		private static TransformSnapshot[] CaptureSortedOriginals(IReadOnlyList<CardTransformation> transformations)
		{
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0022: Unknown result type (might be due to invalid IL or missing references)
			TransformSnapshot[] array = new TransformSnapshot[transformations.Count];
			Dictionary<CardPile, List<CardModel>> dictionary = new Dictionary<CardPile, List<CardModel>>(ReferenceEqualityComparer.Instance);
			for (int i = 0; i < transformations.Count; i++)
			{
				CardTransformation val = transformations[i];
				CardModel original = ((CardTransformation)(ref val)).Original;
				CardPile pile = original.Pile;
				int num = -1;
				if (pile != null)
				{
					if (!dictionary.TryGetValue(pile, out var value))
					{
						value = (dictionary[pile] = pile.Cards.ToList());
					}
					num = IndexOf(value, original);
					if (num >= 0)
					{
						value.RemoveAt(num);
					}
				}
				array[i] = new TransformSnapshot(original, pile, num, i);
			}
			Array.Sort(array, Compare);
			return array;
		}

		private static IEnumerable<CardTransformation> Capture(IEnumerable<CardTransformation> transformations, TransformCaptureState state)
		{
			ArgumentNullException.ThrowIfNull(transformations, "transformations");
			List<CardTransformation> captured = new List<CardTransformation>();
			foreach (CardTransformation transformation in transformations)
			{
				captured.Add(transformation);
				yield return transformation;
			}
			state.Snapshots = CaptureSortedOriginals(captured);
		}

		private static int Compare(TransformSnapshot x, TransformSnapshot y)
		{
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			//IL_0035: Unknown result type (might be due to invalid IL or missing references)
			//IL_003f: Unknown result type (might be due to invalid IL or missing references)
			if (x.Pile == null || y.Pile == null)
			{
				return x.InputIndex.CompareTo(y.InputIndex);
			}
			int num = ((Enum)x.Pile.Type/*cast due to constrained. prefix*/).CompareTo((object?)y.Pile.Type);
			if (num == 0)
			{
				return x.PileIndex.CompareTo(y.PileIndex);
			}
			return num;
		}

		private static int IndexOf(IReadOnlyList<CardModel> cards, CardModel card)
		{
			for (int i = 0; i < cards.Count; i++)
			{
				if (cards[i] == card)
				{
					return i;
				}
			}
			return -1;
		}
	}
}
namespace STS2RitsuLib.Cards.Patches
