	internal sealed class CardOnPlayHookPatch : IPatchMethod
	{
		public static string PatchId => "ritsulib_card_on_play_hook";

		public static string Description => "Dispatch RitsuLib card OnPlay hooks from CardModel.OnPlayWrapper";

		public static bool IsCritical => true;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1] { PatchTarget.AsyncMethod(typeof(CardModel), "OnPlayWrapper", typeof(PlayerChoiceContext), typeof(Creature), typeof(bool), typeof(ResourceInfo), typeof(bool)) };
		}

		public static IEnumerable<CodeInstruction> Transpiler(IEnumerable<CodeInstruction> instructions)
		{
			MethodInfo onPlayMethod = HarmonyIl.RequireMethod(AccessTools.Method(typeof(CardModel), "OnPlay", new Type[2]
			{
				typeof(PlayerChoiceContext),
				typeof(CardPlay)
			}, (Type[])null), "[CardOnPlayHook] OnPlayWrapper injection");
			MethodInfo wrapperMethod = HarmonyIl.RequireMethod(AccessTools.Method(typeof(CardOnPlayHook), "RunCardOnPlayHooks", (Type[])null, (Type[])null), "[CardOnPlayHook] OnPlayWrapper injection");
			HarmonyIlRewriter harmonyIlRewriter = HarmonyIlRewriter.From(instructions);
			HarmonyIlRewriteReport report = harmonyIlRewriter.RedirectCalls("[CardOnPlayHook] OnPlayWrapper injection", (MethodInfo called) => (!(called == onPlayMethod)) ? null : wrapperMethod, (IReadOnlyList<CodeInstruction> code) => code.Any(HarmonyIl.IsCall(wrapperMethod)));
			return harmonyIlRewriter.InstructionsChecked(report);
		}
	}
	/// <summary>
