		public static void Postfix(CardModel __instance, ref IEnumerable<IHoverTip> __result)
		{
			IHoverTip[] array = __instance.DynamicVars.Values.Select(DynamicVarTooltipRegistry.Create).OfType<IHoverTip>().ToArray();
			if (array.Length != 0)
