namespace STS2RitsuLib.Cards.FreePlay
{
	/// <summary>
	///     <para xml:lang="en">Provides free-play helpers whose duration differs from the game's default behavior.</para>
	///     <para xml:lang="zh-CN">提供持续时间不同于游戏默认行为的免费出牌辅助方法。</para>
	/// </summary>
	public static class CardModelFreePlayExtensions
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Makes the card's fixed base costs free for the rest of the current turn, including every subsequent
		///         play of that card during the turn.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使卡牌的固定基础费用在当前回合剩余时间内免费，包括该牌在本回合内的后续每次打出。
		///     </para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">
		///         Unlike <see cref="M:MegaCrit.Sts2.Core.Models.CardModel.SetToFreeThisTurn" />, this state is not removed after the card is played.
		///         It expires during end-of-turn cleanup. X costs retain their normal game behavior.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         与 <see cref="M:MegaCrit.Sts2.Core.Models.CardModel.SetToFreeThisTurn" /> 不同，此状态不会在卡牌打出后移除，而是在回合结束清理时
		///         失效。X 费用保持游戏的正常行为。
		///     </para>
		/// </remarks>
		/// <param name="card">
		///     <para xml:lang="en">Card whose fixed energy, star, and registered secondary-resource costs become free.</para>
		///     <para xml:lang="zh-CN">固定能量、星星和已注册次级资源费用将变为免费的卡牌。</para>
		/// </param>
		public static void SetToFreeForRestOfTurn(this CardModel card)
		{
			//IL_0019: Unknown result type (might be due to invalid IL or missing references)
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0025: Unknown result type (might be due to invalid IL or missing references)
			//IL_002c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0038: Expected O, but got Unknown
			ArgumentNullException.ThrowIfNull(card, "card");
			card.EnergyCost.SetThisTurn(0, false);
			card.AddTemporaryStarCost(new TemporaryCardCost
			{
				Cost = 0,
				ClearsWhenTurnEnds = true,
				ClearsWhenCardIsPlayed = false
			});
			FreePlayBindingRegistry.MarkCardBaseCostsFreeForRestOfTurn(card);
			FreePlayCardVisuals.Refresh(card);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Describes which detection sources marked a card play as free.</para>
	///     <para xml:lang="zh-CN">描述哪些检测来源将一次出牌标记为免费。</para>
	/// </summary>
	public sealed record FreePlayResolution(bool IsAutoPlayNoSpend, bool IsCardBindingFree, bool IsRegisteredDetectorFree)
	{
		/// <summary>
		///     <para xml:lang="en">Gets whether any detection source marks this play as free.</para>
		///     <para xml:lang="zh-CN">获取是否有任一检测来源将本次出牌标记为免费。</para>
		/// </summary>
		public bool IsFree
		{
			get
			{
				if (!IsAutoPlayNoSpend && !IsCardBindingFree)
				{
					return IsRegisteredDetectorFree;
				}
				return true;
			}
		}
	}
	internal readonly record struct FreePlayCardCostScope(bool FixedSecondaryCostsFree, bool XSecondaryCostsFree)
	{
		public bool IsFree
		{
			get
			{
				if (!FixedSecondaryCostsFree)
				{
					return XSecondaryCostsFree;
				}
				return true;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides an extensible registry for determining whether a card play is free.</para>
	///     <para xml:lang="zh-CN">提供可扩展注册表，用于判断一次出牌是否免费。</para>
	/// </summary>
	public static class FreePlayBindingRegistry
	{
		private sealed class CardFreeBindingState
		{
			public int BaseCostsFreeNextPlayCharges { get; set; }

			public int BaseCostsFreeThisTurnCharges { get; set; }

			public int BaseCostsFreeForRestOfTurnCharges { get; set; }

			public ICombatState? BaseCostsFreeThisCombatState { get; set; }
		}

		private sealed class PlayFreeBindingState
		{
			public bool IsResolved { get; set; }

			public FreePlayResolution Resolution { get; set; } = new FreePlayResolution(IsAutoPlayNoSpend: false, IsCardBindingFree: false, IsRegisteredDetectorFree: false);
		}

		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<string, Func<CardPlay, bool>> RegisteredDetectors = new Dictionary<string, Func<CardPlay, bool>>();

		private static readonly AttachedState<CardModel, CardFreeBindingState> CardStates = new AttachedState<CardModel, CardFreeBindingState>(() => new CardFreeBindingState());

		private static readonly AttachedState<CardPlay, PlayFreeBindingState> PlayStates = new AttachedState<CardPlay, PlayFreeBindingState>(() => new PlayFreeBindingState());

		/// <summary>
		///     <para xml:lang="en">
		///         Registers an additional free-play detector. The detector should return <see langword="true" /> when
		///         mod-defined rules consider the specified <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardPlay" /> free.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         注册额外的免费出牌检测器。模组规则将指定 <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardPlay" /> 视为免费时，检测器应返回
		///         <see langword="true" />。
		///     </para>
		/// </summary>
		/// <param name="bindingId">
		///     <para xml:lang="en">Stable unique ID used for replacement and diagnostics.</para>
		///     <para xml:lang="zh-CN">用于替换和诊断的稳定唯一 ID。</para>
		/// </param>
		/// <param name="detector">
		///     <para xml:lang="en">Predicate that determines whether a play is free.</para>
		///     <para xml:lang="zh-CN">判断一次出牌是否免费的谓词。</para>
		/// </param>
		public static void Register(string bindingId, Func<CardPlay, bool> detector)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(bindingId, "bindingId");
			ArgumentNullException.ThrowIfNull(detector, "detector");
			using (Gate.EnterScope())
			{
				RegisteredDetectors[bindingId] = detector;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Marks the card's base costs as free for its next play.</para>
		///     <para xml:lang="zh-CN">将卡牌下一次打出时的基础费用标记为免费。</para>
		/// </summary>
		/// <param name="card">
		///     <para xml:lang="en">Card receiving a single-use base-cost-free charge.</para>
		///     <para xml:lang="zh-CN">获得一次性基础费用免费次数的卡牌。</para>
		/// </param>
		public static void MarkCardFreeNextPlay(CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			CardStates.Update(card, delegate(CardFreeBindingState state)
			{
				state.BaseCostsFreeNextPlayCharges++;
				return state;
			});
		}

		/// <summary>
		///     <para xml:lang="en">Marks the card's base costs as free until the end of the turn or its next play.</para>
		///     <para xml:lang="zh-CN">将卡牌的基础费用标记为免费，直至回合结束或该牌下一次打出。</para>
		/// </summary>
		/// <param name="card">
		///     <para xml:lang="en">Card receiving a current-turn base-cost-free charge.</para>
		///     <para xml:lang="zh-CN">获得本回合基础费用免费次数的卡牌。</para>
		/// </param>
		public static void MarkCardFreeThisTurn(CardModel card)
		{
			MarkCardBaseCostsFreeThisTurn(card);
		}

		internal static void MarkCardBaseCostsFreeThisTurn(CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			CardStates.Update(card, delegate(CardFreeBindingState state)
			{
				state.BaseCostsFreeThisTurnCharges++;
				return state;
			});
		}

		internal static void MarkCardBaseCostsFreeForRestOfTurn(CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			CardStates.Update(card, delegate(CardFreeBindingState state)
			{
				state.BaseCostsFreeForRestOfTurnCharges++;
				return state;
			});
		}

		internal static void MarkCardBaseCostsFreeThisCombat(CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			CardStates.Update(card, delegate(CardFreeBindingState state)
			{
				state.BaseCostsFreeThisCombatState = ResolveCombatState(card);
				return state;
			});
		}

		/// <summary>
		///     <para xml:lang="en">Marks the card's base costs as free for the current combat.</para>
		///     <para xml:lang="zh-CN">将卡牌在当前战斗中的基础费用标记为免费。</para>
		/// </summary>
		/// <param name="card">
		///     <para xml:lang="en">Card receiving a combat-duration base-cost-free state.</para>
		///     <para xml:lang="zh-CN">获得持续整场战斗基础费用免费状态的卡牌。</para>
		/// </param>
		public static void MarkCardFreeThisCombat(CardModel card)
		{
			MarkCardBaseCostsFreeThisCombat(card);
		}

		/// <summary>
		///     <para xml:lang="en">Immediately marks the current <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardPlay" /> as free.</para>
		///     <para xml:lang="zh-CN">立即将当前 <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardPlay" /> 标记为免费。</para>
		/// </summary>
		/// <param name="play">
		///     <para xml:lang="en">Play instance to mark.</para>
		///     <para xml:lang="zh-CN">要标记的出牌实例。</para>
		/// </param>
		public static void MarkCurrentPlayFree(CardPlay play)
		{
			ArgumentNullException.ThrowIfNull(play, "play");
			PlayStates.Update(play, delegate(PlayFreeBindingState state)
			{
				state.Resolution = (state.IsResolved ? state.Resolution with
				{
					IsCardBindingFree = true
				} : new FreePlayResolution(play.IsAutoPlay, IsCardBindingFree: true, IsRegisteredDetectorFree: false));
				state.IsResolved = true;
				return state;
			});
		}

		/// <summary>
		///     <para xml:lang="en">Resolves the free-play sources for this <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardPlay" />.</para>
		///     <para xml:lang="zh-CN">解析此 <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardPlay" /> 的免费出牌来源。</para>
		/// </summary>
		/// <param name="play">
		///     <para xml:lang="en">Play instance to evaluate.</para>
		///     <para xml:lang="zh-CN">要求值的出牌实例。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A result indicating which sources marked the play as free.</para>
		///     <para xml:lang="zh-CN">指示哪些来源将本次出牌标记为免费的结果。</para>
		/// </returns>
		public static FreePlayResolution Resolve(CardPlay play)
		{
			ArgumentNullException.ThrowIfNull(play, "play");
			PlayFreeBindingState orCreate = PlayStates.GetOrCreate(play);
			if (orCreate.IsResolved)
			{
				return orCreate.Resolution;
			}
			FreePlayResolution freePlayResolution = BuildResolution(play);
			PlayStates.Set(play, new PlayFreeBindingState
			{
				IsResolved = true,
				Resolution = freePlayResolution
			});
			return freePlayResolution;
		}

		/// <summary>
		///     <para xml:lang="en">Returns whether any source marks the play as free.</para>
		///     <para xml:lang="zh-CN">返回是否有任一来源将本次出牌标记为免费。</para>
		/// </summary>
		/// <param name="play">
		///     <para xml:lang="en">Play instance to evaluate.</para>
		///     <para xml:lang="zh-CN">要求值的出牌实例。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> when any free-play source applies.</para>
		///     <para xml:lang="zh-CN">有任一免费出牌来源适用时为 <see langword="true" />。</para>
		/// </returns>
		public static bool IsFreeForPlay(CardPlay play)
		{
			return Resolve(play).IsFree;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Returns whether the card is marked free before a <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardPlay" /> exists, without consuming a
		///         next-play charge.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         返回卡牌在 <see cref="T:MegaCrit.Sts2.Core.Entities.Cards.CardPlay" /> 创建前是否已被标记为免费，且不消耗下一次出牌的免费次数。
		///     </para>
		/// </summary>
		public static bool IsCardFreeForUpcomingPlay(CardModel card)
		{
			return ResolveCardCostScopeForUpcomingPlay(card).IsFree;
		}

		internal static FreePlayCardCostScope ResolveCardCostScopeForUpcomingPlay(CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			if (!CardStates.TryGetValue(card, out CardFreeBindingState value))
			{
				return new FreePlayCardCostScope(FixedSecondaryCostsFree: false, XSecondaryCostsFree: false);
			}
			ICombatState val = ResolveCombatState(card);
			return new FreePlayCardCostScope(value.BaseCostsFreeNextPlayCharges > 0 || value.BaseCostsFreeThisTurnCharges > 0 || value.BaseCostsFreeForRestOfTurnCharges > 0 || (value.BaseCostsFreeThisCombatState != null && value.BaseCostsFreeThisCombatState == val), XSecondaryCostsFree: false);
		}

		/// <summary>
		///     <para xml:lang="en">Clears current-turn free-play charges that were not consumed by playing the card.</para>
		///     <para xml:lang="zh-CN">清除未因打出卡牌而消耗的本回合免费出牌次数。</para>
		/// </summary>
		/// <param name="card">
		///     <para xml:lang="en">Card receiving end-of-turn cleanup.</para>
		///     <para xml:lang="zh-CN">正在执行回合结束清理的卡牌。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> when any current-turn free-play charge was cleared.</para>
		///     <para xml:lang="zh-CN">清除了任一本回合免费出牌次数时为 <see langword="true" />。</para>
		/// </returns>
		public static bool ClearCardFreeThisTurn(CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			bool changed = false;
			CardStates.Update(card, delegate(CardFreeBindingState state)
			{
				changed = state.BaseCostsFreeThisTurnCharges > 0 || state.BaseCostsFreeForRestOfTurnCharges > 0;
				state.BaseCostsFreeThisTurnCharges = 0;
				state.BaseCostsFreeForRestOfTurnCharges = 0;
				return state;
			});
			return changed;
		}

		/// <summary>
		///     <para xml:lang="en">Clears free-play bindings that expire after the card is played.</para>
		///     <para xml:lang="zh-CN">清除在卡牌打出后失效的免费出牌绑定。</para>
		/// </summary>
		/// <param name="card">
		///     <para xml:lang="en">Card receiving after-play cleanup.</para>
		///     <para xml:lang="zh-CN">正在执行打出后清理的卡牌。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> when any after-play binding was cleared or consumed.</para>
		///     <para xml:lang="zh-CN">清除或消耗了任一打出后失效的绑定时为 <see langword="true" />。</para>
		/// </returns>
		public static bool ClearCardFreeAfterPlayed(CardModel card)
		{
			ArgumentNullException.ThrowIfNull(card, "card");
			bool changed = false;
			CardStates.Update(card, delegate(CardFreeBindingState state)
			{
				changed = state.BaseCostsFreeNextPlayCharges > 0 || state.BaseCostsFreeThisTurnCharges > 0;
				state.BaseCostsFreeNextPlayCharges = Math.Max(0, state.BaseCostsFreeNextPlayCharges - 1);
				state.BaseCostsFreeThisTurnCharges = 0;
				return state;
			});
			return changed;
		}

		private static FreePlayResolution BuildResolution(CardPlay play)
		{
			if (play.IsAutoPlay)
			{
				return new FreePlayResolution(IsAutoPlayNoSpend: true, IsCardBindingFree: false, IsRegisteredDetectorFree: false);
			}
			bool isCardBindingFree = EvaluateCardBindings(play);
			bool isRegisteredDetectorFree = EvaluateRegisteredDetectors(play);
			return new FreePlayResolution(IsAutoPlayNoSpend: false, isCardBindingFree, isRegisteredDetectorFree);
		}

		private static bool EvaluateCardBindings(CardPlay play)
		{
			CardModel card = play.Card;
			CardFreeBindingState orCreate = CardStates.GetOrCreate(card);
			ICombatState val = ResolveCombatState(card);
			if (orCreate.BaseCostsFreeThisCombatState != null && orCreate.BaseCostsFreeThisCombatState == val)
			{
				return true;
			}
			if (orCreate.BaseCostsFreeThisTurnCharges > 0)
			{
				return true;
			}
			if (orCreate.BaseCostsFreeForRestOfTurnCharges > 0)
			{
				return true;
			}
			return orCreate.BaseCostsFreeNextPlayCharges > 0;
		}

		private static bool EvaluateRegisteredDetectors(CardPlay play)
		{
			KeyValuePair<string, Func<CardPlay, bool>>[] array;
			using (Gate.EnterScope())
			{
				array = RegisteredDetectors.ToArray();
			}
			KeyValuePair<string, Func<CardPlay, bool>>[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				KeyValuePair<string, Func<CardPlay, bool>> keyValuePair = array2[i];
				var (value, func2) = keyValuePair;
				try
				{
					if (func2(play))
					{
						return true;
					}
				}
				catch (Exception value2)
				{
					RitsuLibFramework.Logger.Warn($"[FreePlay] Detector '{value}' failed for card '{((AbstractModel)play.Card).Id}': {value2}", 1);
					throw;
				}
			}
			return false;
		}

		private static ICombatState? ResolveCombatState(CardModel card)
		{
			ICombatState combatState = card.CombatState;
			if (combatState == null)
			{
				if (!((AbstractModel)card).IsMutable)
				{
					return null;
				}
				combatState = card.Owner.Creature.CombatState;
			}
			return combatState;
		}
	}
}
namespace STS2RitsuLib.Cards.FreePlay.Patches
{
	/// <summary>
	///     <para xml:lang="en">Records game-level <c>SetToFree</c> calls in <see cref="T:STS2RitsuLib.Cards.FreePlay.FreePlayBindingRegistry" />.</para>
	///     <para xml:lang="zh-CN">将游戏层的 <c>SetToFree</c> 调用记录到 <see cref="T:STS2RitsuLib.Cards.FreePlay.FreePlayBindingRegistry" />。</para>
	/// </summary>
	internal sealed class CardModelSetToFreeThisTurnBindingPatch : IPatchMethod
	{
		public static string PatchId => "card_model_set_to_free_this_turn_binding";

		public static string Description => "Bind CardModel.SetToFreeThisTurn calls to FreePlayBindingRegistry markers";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(CardModel), "SetToFreeThisTurn")
			};
		}

		public static void Postfix(CardModel __instance)
		{
			FreePlayBindingRegistry.MarkCardBaseCostsFreeThisTurn(__instance);
			FreePlayCardVisuals.Refresh(__instance);
		}
	}
	internal sealed class CardModelFreeThisTurnEndCleanupPatch : IPatchMethod
	{
		public static string PatchId => "card_model_free_this_turn_end_cleanup";

		public static string Description => "Clear CardModel.SetToFreeThisTurn bindings during CardModel.EndOfTurnCleanup";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(CardModel), "EndOfTurnCleanup")
			};
		}

		public static void Postfix(CardModel __instance)
		{
			if (FreePlayBindingRegistry.ClearCardFreeThisTurn(__instance))
			{
				FreePlayCardVisuals.Refresh(__instance);
			}
		}
	}
	internal sealed class CardModelFreeAfterPlayedCleanupPatch : IPatchMethod
	{
		public static string PatchId => "card_model_free_after_played_cleanup";

		public static string Description => "Clear CardModel free-play bindings after CardModel.OnPlayWrapper";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(CardModel), "OnPlayWrapper", new Type[5]
				{
					typeof(PlayerChoiceContext),
					typeof(Creature),
					typeof(bool),
					typeof(ResourceInfo),
					typeof(bool)
				})
			};
		}

		public static void Postfix(CardModel __instance, ref Task __result)
		{
			__result = After(__instance, __result);
		}

		private static async Task After(CardModel card, Task original)
		{
			try
			{
				await original;
			}
			finally
			{
				if (FreePlayBindingRegistry.ClearCardFreeAfterPlayed(card))
				{
					FreePlayCardVisuals.Refresh(card);
				}
			}
		}
	}
	internal sealed class CardModelSetToFreeThisCombatBindingPatch : IPatchMethod
	{
		public static string PatchId => "card_model_set_to_free_this_combat_binding";

		public static string Description => "Bind CardModel.SetToFreeThisCombat calls to FreePlayBindingRegistry markers";

		public static bool IsCritical => false;

		public static ModPatchTarget[] GetTargets()
		{
			return new ModPatchTarget[1]
			{
				new ModPatchTarget(typeof(CardModel), "SetToFreeThisCombat")
			};
		}

		public static void Postfix(CardModel __instance)
		{
			FreePlayBindingRegistry.MarkCardBaseCostsFreeThisCombat(__instance);
			FreePlayCardVisuals.Refresh(__instance);
		}
	}
	internal static class FreePlayCardVisuals
	{
		public static void Refresh(CardModel card)
		{
			//IL_0023: Unknown result type (might be due to invalid IL or missing references)
			if (card.Pile != null)
			{
				NCard obj = NCard.FindOnTable(card, (PileType?)null);
				if (obj != null)
				{
					obj.UpdateVisuals(card.Pile.Type, (CardPreviewMode)1);
				}
			}
		}
	}
}
namespace STS2RitsuLib.Cards.DynamicVars
{
	/// <summary>
	///     <para xml:lang="en">Represents a <see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.DynamicVar" /> whose displayed value is computed by delegates.</para>
	///     <para xml:lang="zh-CN">表示显示值由委托计算的 <see cref="T:MegaCrit.Sts2.Core.Localization.DynamicVars.DynamicVar" />。</para>
	/// </summary>
	public sealed class ComputedDynamicVar : DynamicVar, IComputedDynamicVar
	{
		private readonly ComputedDynamicVarEvaluator _evaluator;

		/// <summary>
		///     <para xml:lang="en">Creates a computed variable with optional preview-specific evaluation.</para>
		///     <para xml:lang="zh-CN">创建可指定预览求值逻辑的计算变量。</para>
		/// </summary>
		/// <param name="name">
		///     <para xml:lang="en">Dynamic-variable key.</para>
		///     <para xml:lang="zh-CN">动态变量键。</para>
		/// </param>
		/// <param name="baseValue">
		///     <para xml:lang="en">
		///         Initial stored base value. The evaluator does not return it automatically.
		///     </para>
		///     <para xml:lang="zh-CN">初始存储的基础值；求值器不会自动返回此值。</para>
		/// </param>
		/// <param name="currentValueFactory">
		///     <para xml:lang="en">Computes the current value from the owning card, which may be <see langword="null" />.</para>
		///     <para xml:lang="zh-CN">根据所属卡牌计算当前值；卡牌可能为 <see langword="null" />。</para>
		/// </param>
		/// <param name="previewValueFactory">
		///     <para xml:lang="en">Optional preview evaluator; when omitted, <paramref name="currentValueFactory" /> is used.</para>
		///     <para xml:lang="zh-CN">可选的预览求值器；省略时使用 <paramref name="currentValueFactory" />。</para>
		/// </param>
		public ComputedDynamicVar(string name, decimal baseValue, Func<CardModel?, decimal> currentValueFactory, Func<CardModel?, CardPreviewMode, Creature?, bool, decimal>? previewValueFactory = null)
			: this(name, baseValue, (CardModel? card, Creature? _) => currentValueFactory(card), previewValueFactory)
		{
			ArgumentNullException.ThrowIfNull(currentValueFactory, "currentValueFactory");
		}

		/// <summary>
		///     <para xml:lang="en">Creates a computed variable with target-aware evaluation.</para>
		///     <para xml:lang="zh-CN">创建支持目标感知求值的计算变量。</para>
		/// </summary>
		/// <param name="name">
		///     <para xml:lang="en">Dynamic-variable key.</para>
		///     <para xml:lang="zh-CN">动态变量键。</para>
		/// </param>
		/// <param name="baseValue">
		///     <para xml:lang="en">
		///         Initial stored base value. The evaluator does not return it automatically.
		///     </para>
		///     <para xml:lang="zh-CN">初始存储的基础值；求值器不会自动返回此值。</para>
		/// </param>
		/// <param name="currentValueFactory">
		///     <para xml:lang="en">Computes the current value from the owning card and current target.</para>
		///     <para xml:lang="zh-CN">根据所属卡牌和当前目标计算当前值。</para>
		/// </param>
		/// <param name="previewValueFactory">
		///     <para xml:lang="en">Optional preview evaluator; when omitted, <paramref name="currentValueFactory" /> is used.</para>
		///     <para xml:lang="zh-CN">可选的预览求值器；省略时使用 <paramref name="currentValueFactory" />。</para>
		/// </param>
		public ComputedDynamicVar(string name, decimal baseValue, Func<CardModel?, Creature?, decimal> currentValueFactory, Func<CardModel?, CardPreviewMode, Creature?, bool, decimal>? previewValueFactory = null)
			: base(name, baseValue)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(name, "name");
			ArgumentNullException.ThrowIfNull(currentValueFactory, "currentValueFactory");
			_evaluator = new ComputedDynamicVarEvaluator(currentValueFactory, previewValueFactory);
		}

		/// <summary>
		///     <para xml:lang="en">Creates a computed variable from a context-aware evaluator.</para>
		///     <para xml:lang="zh-CN">使用上下文感知求值器创建计算变量。</para>
		/// </summary>
		public ComputedDynamicVar(string name, ComputedDynamicVarFactory contextFactory, decimal baseValue = 0m)
			: this(name, baseValue, contextFactory)
		{
		}

		internal ComputedDynamicVar(string name, decimal baseValue, ComputedDynamicVarFactory contextFactory)
			: base(name, baseValue)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(name, "name");
			ArgumentNullException.ThrowIfNull(contextFactory, "contextFactory");
			_evaluator = new ComputedDynamicVarEvaluator(contextFactory);
		}

		/// <summary>
		///     <para xml:lang="en">Computes the value for the owning card, if any, and <paramref name="target" />.</para>
		///     <para xml:lang="zh-CN">计算当前所属卡牌（若有）和 <paramref name="target" /> 对应的值。</para>
		/// </summary>
		public decimal Calculate(Creature? target)
		{
			return _evaluator.Calculate((DynamicVar)(object)this, base._owner, target);
		}

		/// <summary>
		///     <para xml:lang="en">Computes the value for the owning card, if any, without a target.</para>
		///     <para xml:lang="zh-CN">计算当前所属卡牌（若有）在没有目标时的值。</para>
		/// </summary>
		public decimal Calculate()
		{
			return Calculate(null);
		}

		/// <inheritdoc />
		public override void UpdateCardPreview(CardModel card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks)
		{
			//IL_000f: Unknown result type (might be due to invalid IL or missing references)
			((DynamicVar)this).PreviewValue = _evaluator.CalculatePreview((DynamicVar)(object)this, base._owner, card, previewMode, target, runGlobalHooks);
		}

		/// <inheritdoc />
		protected override decimal GetBaseValueForIConvertible()
		{
			return Calculate(null);
		}

		/// <summary>
		///     <para xml:lang="en">Returns the computed value as a string.</para>
		///     <para xml:lang="zh-CN">以字符串形式返回计算值。</para>
		/// </summary>
		public override string ToString()
		{
			return Calculate(null).ToString();
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides input to a context-aware computed dynamic-variable evaluator.</para>
	///     <para xml:lang="zh-CN">为上下文感知的计算型动态变量求值器提供输入。</para>
	/// </summary>
	public sealed class ComputedDynamicVarContext
	{
		private static readonly AsyncLocal<HashSet<DynamicVar>?> EvaluationStack = new AsyncLocal<HashSet<DynamicVar>>();

		/// <summary>
		///     <para xml:lang="en">Gets the dynamic variable currently being evaluated.</para>
		///     <para xml:lang="zh-CN">获取当前正在求值的动态变量。</para>
		/// </summary>
		public DynamicVar Variable { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the model assigned through <see cref="M:MegaCrit.Sts2.Core.Localization.DynamicVars.DynamicVar.SetOwner(MegaCrit.Sts2.Core.Models.AbstractModel)" />.</para>
		///     <para xml:lang="zh-CN">获取通过 <see cref="M:MegaCrit.Sts2.Core.Localization.DynamicVars.DynamicVar.SetOwner(MegaCrit.Sts2.Core.Models.AbstractModel)" /> 指定的模型。</para>
		/// </summary>
		public AbstractModel? ModelOwner { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the effective card for this evaluation. During an enchantment preview, this may differ from
		///         <see cref="P:STS2RitsuLib.Cards.DynamicVars.ComputedDynamicVarContext.ModelOwner" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取此次求值使用的有效卡牌。在附魔预览期间，它可能不同于 <see cref="P:STS2RitsuLib.Cards.DynamicVars.ComputedDynamicVarContext.ModelOwner" />。
		///     </para>
		/// </summary>
		public CardModel? Card { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the current preview or explicit calculation target.</para>
		///     <para xml:lang="zh-CN">获取当前预览目标或显式计算目标。</para>
		/// </summary>
		public Creature? Target { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the preview mode, or <see langword="null" /> during current-value evaluation.</para>
		///     <para xml:lang="zh-CN">获取预览模式；计算当前值时为 <see langword="null" />。</para>
		/// </summary>
		public CardPreviewMode? PreviewMode { get; }

		/// <summary>
		///     <para xml:lang="en">Gets whether global hooks should participate in this preview evaluation.</para>
		///     <para xml:lang="zh-CN">获取此次预览求值是否应运行全局钩子。</para>
		/// </summary>
		public bool RunGlobalHooks { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the variable name.</para>
		///     <para xml:lang="zh-CN">获取变量名称。</para>
		/// </summary>
		public string Name => Variable.Name;

		/// <summary>
		///     <para xml:lang="en">Gets the variable's stored, mutable base value.</para>
		///     <para xml:lang="zh-CN">获取变量存储的可变基础值。</para>
		/// </summary>
		public decimal BaseValue => Variable.BaseValue;

		/// <summary>
		///     <para xml:lang="en">Gets whether this invocation is evaluating a card preview.</para>
		///     <para xml:lang="zh-CN">获取此次调用是否正在计算卡牌预览值。</para>
		/// </summary>
		public bool IsPreview => PreviewMode.HasValue;

		/// <summary>
		///     <para xml:lang="en">Gets whether this invocation is evaluating the current value.</para>
		///     <para xml:lang="zh-CN">获取此次调用是否正在计算当前值。</para>
		/// </summary>
		public bool IsCurrentValue => !IsPreview;

		/// <summary>
		///     <para xml:lang="en">Gets whether this is a normal card preview.</para>
		///     <para xml:lang="zh-CN">获取此次调用是否为普通卡牌预览。</para>
		/// </summary>
		public bool IsNormalPreview
		{
			get
			{
				//IL_0009: Unknown result type (might be due to invalid IL or missing references)
				//IL_000f: Invalid comparison between Unknown and I4
				return (int)PreviewMode.GetValueOrDefault() == 1;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether an effective card is available.</para>
		///     <para xml:lang="zh-CN">获取是否存在有效卡牌。</para>
		/// </summary>
		[MemberNotNullWhen(true, "Card")]
		public bool HasCard
		{
			[MemberNotNullWhen(true, "Card")]
			get
			{
				return Card != null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether a target is available.</para>
		///     <para xml:lang="zh-CN">获取是否存在目标。</para>
		/// </summary>
		[MemberNotNullWhen(true, "Target")]
		public bool HasTarget
		{
			[MemberNotNullWhen(true, "Target")]
			get
			{
				return Target != null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether the effective card is mutable.</para>
		///     <para xml:lang="zh-CN">获取有效卡牌是否为可变实例。</para>
		/// </summary>
		[MemberNotNullWhen(true, "Card")]
		public bool IsMutableCard
		{
			[MemberNotNullWhen(true, "Card")]
			get
			{
				CardModel card = Card;
				if (card != null)
				{
					return ((AbstractModel)card).IsMutable;
				}
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether the effective card is canonical.</para>
		///     <para xml:lang="zh-CN">获取有效卡牌是否为规范实例。</para>
		/// </summary>
		[MemberNotNullWhen(true, "Card")]
		public bool IsCanonicalCard
		{
			[MemberNotNullWhen(true, "Card")]
			get
			{
				CardModel card = Card;
				if (card != null)
				{
					return ((AbstractModel)card).IsCanonical;
				}
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether the effective card is upgraded.</para>
		///     <para xml:lang="zh-CN">获取有效卡牌是否已升级。</para>
		/// </summary>
		[MemberNotNullWhen(true, "Card")]
		public bool IsUpgraded
		{
			[MemberNotNullWhen(true, "Card")]
			get
			{
				CardModel? card = Card;
				if (card == null)
				{
					return false;
				}
				return card.IsUpgraded;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether the effective card is an enchantment preview.</para>
		///     <para xml:lang="zh-CN">获取有效卡牌是否为附魔预览。</para>
		/// </summary>
		[MemberNotNullWhen(true, "Card")]
		public bool IsEnchantmentPreview
		{
			[MemberNotNullWhen(true, "Card")]
			get
			{
				CardModel? card = Card;
				if (card == null)
				{
					return false;
				}
				return card.IsEnchantmentPreview;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether this is an upgrade preview.</para>
		///     <para xml:lang="zh-CN">获取此次调用是否为升级预览。</para>
		/// </summary>
		public bool IsUpgradePreview
		{
			get
			{
				//IL_0009: Unknown result type (might be due to invalid IL or missing references)
				//IL_000f: Invalid comparison between Unknown and I4
				return (int)PreviewMode.GetValueOrDefault() == 2;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether this is a multi-creature targeting preview.</para>
		///     <para xml:lang="zh-CN">获取此次调用是否为多生物目标预览。</para>
		/// </summary>
		public bool IsMultiTargetPreview
		{
			get
			{
				//IL_0009: Unknown result type (might be due to invalid IL or missing references)
				//IL_000f: Invalid comparison between Unknown and I4
				return (int)PreviewMode.GetValueOrDefault() == 3;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether this preview should apply global hooks.</para>
		///     <para xml:lang="zh-CN">获取此次预览是否应应用全局钩子。</para>
		/// </summary>
		public bool ShouldRunGlobalHooks
		{
			get
			{
				if (IsPreview)
				{
					return RunGlobalHooks;
				}
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the player who owns the effective mutable card. For canonical cards, returns
		///         <see langword="null" /> without invoking the guarded <c>Owner</c> getter.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取有效可变卡牌的所属玩家。对于规范卡牌，不调用受保护的 <c>Owner</c> getter，而是返回
		///         <see langword="null" />。
		///     </para>
		/// </summary>
		public Player? Player
		{
			get
			{
				CardModel card = Card;
				if (card == null || !((AbstractModel)card).IsMutable)
				{
					return null;
				}
				return Card.Owner;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether a player owner is available.</para>
		///     <para xml:lang="zh-CN">获取是否存在所属玩家。</para>
		/// </summary>
		[MemberNotNullWhen(true, "Player")]
		public bool HasPlayer
		{
			[MemberNotNullWhen(true, "Player")]
			get
			{
				return Player != null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets the creature that owns or uses the effective card, if available.</para>
		///     <para xml:lang="zh-CN">获取拥有或使用有效卡牌的生物（如果有）。</para>
		/// </summary>
		public Creature? SourceCreature
		{
			get
			{
				Player? player = Player;
				if (player == null)
				{
					return null;
				}
				return player.Creature;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether a source creature is available.</para>
		///     <para xml:lang="zh-CN">获取是否存在来源生物。</para>
		/// </summary>
		[MemberNotNullWhen(true, "SourceCreature")]
		public bool HasSourceCreature
		{
			[MemberNotNullWhen(true, "SourceCreature")]
			get
			{
				return SourceCreature != null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets the run containing the effective card, if available.</para>
		///     <para xml:lang="zh-CN">获取有效卡牌所属的一局游戏（如果有）。</para>
		/// </summary>
		public IRunState? RunState
		{
			get
			{
				CardModel? card = Card;
				if (card == null)
				{
					return null;
				}
				return card.RunState;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether a run state is available.</para>
		///     <para xml:lang="zh-CN">获取是否存在局内状态。</para>
		/// </summary>
		[MemberNotNullWhen(true, "RunState")]
		public bool HasRunState
		{
			[MemberNotNullWhen(true, "RunState")]
			get
			{
				return RunState != null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the active combat associated with the card or its owner. For cards outside combat piles, this
		///         falls back to the owner's combat.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取与卡牌或其拥有者关联的当前战斗。卡牌不在战斗牌堆中时，回退到拥有者的战斗。
		///     </para>
		/// </summary>
		public ICombatState? CombatState
		{
			get
			{
				CardModel? card = Card;
				object obj = ((card != null) ? card.CombatState : null);
				if (obj == null)
				{
					Creature? sourceCreature = SourceCreature;
					if (sourceCreature == null)
					{
						return null;
					}
					obj = sourceCreature.CombatState;
				}
				return (ICombatState?)obj;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether a combat state is available.</para>
		///     <para xml:lang="zh-CN">获取是否存在战斗状态。</para>
		/// </summary>
		[MemberNotNullWhen(true, "CombatState")]
		public bool HasCombatState
		{
			[MemberNotNullWhen(true, "CombatState")]
			get
			{
				return CombatState != null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets the lowest-level scope reported by the card.</para>
		///     <para xml:lang="zh-CN">获取卡牌报告的最小作用域。</para>
		/// </summary>
		public ICardScope? CardScope
		{
			get
			{
				CardModel? card = Card;
				if (card == null)
				{
					return null;
				}
				return card.CardScope;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether a card scope is available.</para>
		///     <para xml:lang="zh-CN">获取是否存在卡牌作用域。</para>
		/// </summary>
		[MemberNotNullWhen(true, "CardScope")]
		public bool HasCardScope
		{
			[MemberNotNullWhen(true, "CardScope")]
			get
			{
				return CardScope != null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether the card belongs to a run.</para>
		///     <para xml:lang="zh-CN">获取卡牌是否属于一局游戏。</para>
		/// </summary>
		[MemberNotNullWhen(true, "RunState")]
		public bool IsInRun
		{
			[MemberNotNullWhen(true, "RunState")]
			get
			{
				return HasRunState;
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether the card owner is currently in combat. This may be <see langword="true" /> for a card in
		///         a non-combat pile such as the deck.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取卡牌拥有者当前是否处于战斗。即使卡牌位于牌组等非战斗牌堆中，此值也可能为
		///         <see langword="true" />。
		///     </para>
		/// </summary>
		[MemberNotNullWhen(true, "CombatState")]
		public bool IsInCombat
		{
			[MemberNotNullWhen(true, "CombatState")]
			get
			{
				return HasCombatState;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether the card itself currently reports a combat state.</para>
		///     <para xml:lang="zh-CN">获取卡牌自身当前是否报告战斗状态。</para>
		/// </summary>
		[MemberNotNullWhen(true, "Card")]
		public bool IsCardInCombat
		{
			[MemberNotNullWhen(true, "Card")]
			get
			{
				CardModel? card = Card;
				return ((card != null) ? card.CombatState : null) != null;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets the effective card's dynamic variables, if available.</para>
		///     <para xml:lang="zh-CN">获取有效卡牌的动态变量（如果有）。</para>
		/// </summary>
		public DynamicVarSet? CardVars
		{
			get
			{
				CardModel? card = Card;
				if (card == null)
				{
					return null;
				}
				return card.DynamicVars;
			}
		}

		internal ComputedDynamicVarContext(DynamicVar variable, AbstractModel? modelOwner, CardModel? card, Creature? target, CardPreviewMode? previewMode, bool runGlobalHooks)
		{
			Variable = variable;
			ModelOwner = modelOwner;
			Card = card;
			Target = target;
			PreviewMode = previewMode;
			RunGlobalHooks = runGlobalHooks;
		}

		/// <summary>
		///     <para xml:lang="en">Attempts to get a dynamic variable from <see cref="P:STS2RitsuLib.Cards.DynamicVars.ComputedDynamicVarContext.CardVars" />.</para>
		///     <para xml:lang="zh-CN">尝试从 <see cref="P:STS2RitsuLib.Cards.DynamicVars.ComputedDynamicVarContext.CardVars" /> 获取动态变量。</para>
		/// </summary>
		public bool TryGetCardVar(string name, [MaybeNullWhen(false)] out DynamicVar dynamicVar)
		{
			ArgumentException.ThrowIfNullOrWhiteSpace(name, "name");
			DynamicVarSet cardVars = CardVars;
			if (cardVars != null && cardVars.TryGetValue(name, ref dynamicVar))
			{
				return true;
			}
			dynamicVar = null;
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to get a dynamic variable of type <typeparamref name="TVar" /> from
		///         <see cref="P:STS2RitsuLib.Cards.DynamicVars.ComputedDynamicVarContext.CardVars" />.
		///     </para>
		///     <para xml:lang="zh-CN">尝试从 <see cref="P:STS2RitsuLib.Cards.DynamicVars.ComputedDynamicVarContext.CardVars" /> 获取 <typeparamref name="TVar" /> 类型的动态变量。</para>
		/// </summary>
		public bool TryGetCardVar<TVar>(string name, [MaybeNullWhen(false)] out TVar dynamicVar) where TVar : DynamicVar
		{
