			}
			HashSet<DynamicVar> hashSet = ((value == null) ? new HashSet<DynamicVar>(ReferenceEqualityComparer.Instance) : new HashSet<DynamicVar>(value, ReferenceEqualityComparer.Instance));
			hashSet.Add(dynamicVar);
			EvaluationStack.Value = hashSet;
