			{
				CardPreviewMode? previewMode = PreviewMode;
				if (previewMode.HasValue)
				{
					CardPreviewMode valueOrDefault = previewMode.GetValueOrDefault();
					if (Card != null)
					{
						dynamicVar.UpdateCardPreview(Card, valueOrDefault, Target, RunGlobalHooks);
						return dynamicVar.PreviewValue;
					}
				}
				return (dynamicVar is IComputedDynamicVar computedDynamicVar) ? computedDynamicVar.Calculate(Target) : dynamicVar.BaseValue;
			}
			finally
			{
				EvaluationStack.Value = value;
			}
		}
