		{
			ArgumentException.ThrowIfNullOrWhiteSpace(titleTable, "titleTable");
			ArgumentException.ThrowIfNullOrWhiteSpace(titleKey, "titleKey");
			string resolvedDescriptionTable = descriptionTable ?? titleTable;
			string resolvedDescriptionKey = descriptionKey ?? titleKey.Replace(".title", ".description", StringComparison.Ordinal);
			return dynamicVar.WithTooltip(delegate(DynamicVar var)
