		/// <summary>
		///     <para xml:lang="en">Attempts to get a dynamic variable of type <typeparamref name="TVar" />.</para>
		///     <para xml:lang="zh-CN">尝试获取 <typeparamref name="TVar" /> 类型的动态变量。</para>
		/// </summary>
		public static bool TryGet<TVar>(this DynamicVarSet dynamicVars, string key, [MaybeNullWhen(false)] out TVar value) where TVar : DynamicVar
		{
			ArgumentNullException.ThrowIfNull(dynamicVars, "dynamicVars");
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			DynamicVar val = default(DynamicVar);
			if (dynamicVars.TryGetValue(key, ref val))
			{
				TVar val2 = (TVar)(object)((val is TVar) ? val : null);
				if (val2 != null)
				{
					value = val2;
					return true;
				}
			}
			value = default(TVar);
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Gets a required dynamic variable of type <typeparamref name="TVar" />.</para>
		///     <para xml:lang="zh-CN">获取必需的 <typeparamref name="TVar" /> 类型动态变量。</para>
		/// </summary>
		public static TVar GetRequired<TVar>(this DynamicVarSet dynamicVars, string key) where TVar : DynamicVar
		{
			if (dynamicVars.TryGet<TVar>(key, out var value))
			{
				return value;
			}
			throw new KeyNotFoundException($"Dynamic var '{key}' was missing or was not a {typeof(TVar).Name}.");
		}

