		/// <summary>
		///     <para xml:lang="en">Attempts to compute a RitsuLib computed dynamic variable.</para>
		///     <para xml:lang="zh-CN">尝试计算 RitsuLib 计算型动态变量。</para>
		/// </summary>
		public static bool TryComputeValue(this DynamicVarSet dynamicVars, string key, out decimal value, Creature? target = null)
		{
			ArgumentNullException.ThrowIfNull(dynamicVars, "dynamicVars");
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			DynamicVar val = default(DynamicVar);
			if (dynamicVars.TryGetValue(key, ref val) && val is IComputedDynamicVar computedDynamicVar)
			{
				value = computedDynamicVar.Calculate(target);
				return true;
			}
			value = 0m;
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Computes a required RitsuLib computed dynamic variable.</para>
		///     <para xml:lang="zh-CN">计算必需的 RitsuLib 计算型动态变量。</para>
		/// </summary>
		public static decimal GetComputedValue(this DynamicVarSet dynamicVars, string key, Creature? target = null)
		{
			if (dynamicVars.TryComputeValue(key, out var value, target))
			{
				return value;
			}
			throw new KeyNotFoundException($"Dynamic var '{key}' was missing or did not implement {"IComputedDynamicVar"}.");
		}

