		///         计算计算型变量；对于普通变量则读取基础值。变量不存在时返回 <paramref name="defaultValue" />。
		///     </para>
		/// </summary>
		public static decimal EvaluateValueOrDefault(this DynamicVarSet dynamicVars, string key, decimal defaultValue = 0m, Creature? target = null)
		{
			ArgumentNullException.ThrowIfNull(dynamicVars, "dynamicVars");
			ArgumentException.ThrowIfNullOrWhiteSpace(key, "key");
			DynamicVar val = default(DynamicVar);
			if (!dynamicVars.TryGetValue(key, ref val))
			{
				return defaultValue;
			}
			if (!(val is IComputedDynamicVar computedDynamicVar))
			{
				return val.BaseValue;
			}
			return computedDynamicVar.Calculate(target);
		}

