		private static decimal CalculateDamagePreview(CardModel? card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks, Func<CardModel?, CardPreviewMode, Creature?, bool, decimal> previewBaseValueFactory, Func<CardModel, Creature?> dealerFactory, ValueProp props)
		{
			//IL_0003: Unknown result type (might be due to invalid IL or missing references)
			//IL_0081: Unknown result type (might be due to invalid IL or missing references)
			//IL_0091: Unknown result type (might be due to invalid IL or missing references)
			//IL_004f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			decimal num = previewBaseValueFactory(card, previewMode, target, runGlobalHooks);
			if (card == null)
			{
				return Math.Max(num, 0m);
			}
			if (runGlobalHooks)
			{
				IRunState runState = card.RunState;
				if (runState != null)
				{
					ICombatState val = card.CombatState ?? card.Owner.Creature.CombatState;
					IEnumerable<AbstractModel> enumerable = default(IEnumerable<AbstractModel>);
					return Math.Max(Hook.ModifyDamage(runState, val, target, dealerFactory(card), num, props, card, (CardPlay)null, (ModifyDamageHookType)14, previewMode, ref enumerable), 0m);
				}
			}
			EnchantmentModel enchantment = card.Enchantment;
			if (enchantment == null)
			{
				return Math.Max(num, 0m);
			}
			num += enchantment.EnchantDamageAdditive(num, props);
			num *= enchantment.EnchantDamageMultiplicative(num, props);
			return Math.Max(num, 0m);
		}

		private static decimal CalculateDamagePreview(ComputedDynamicVarContext context, decimal value, Func<ComputedDynamicVarContext, Creature?> dealerFactory, ValueProp props)
		{
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			//IL_003e: Unknown result type (might be due to invalid IL or missing references)
			//IL_004d: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ab: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b0: Unknown result type (might be due to invalid IL or missing references)
			CardPreviewMode? previewMode = context.PreviewMode;
			if (previewMode.HasValue)
			{
				CardPreviewMode valueOrDefault = previewMode.GetValueOrDefault();
				CardModel card = context.Card;
				if (card != null)
				{
					decimal num = value;
					EnchantmentModel enchantment = card.Enchantment;
					if (enchantment != null)
					{
						num += enchantment.EnchantDamageAdditive(num, props);
						num *= enchantment.EnchantDamageMultiplicative(num, props);
						if (!context.IsEnchantmentPreview)
						{
							context.Variable.EnchantedValue = num;
						}
					}
					if (context.RunGlobalHooks)
					{
						IRunState runState = context.RunState;
						if (runState != null)
						{
							ICombatState combatState = context.CombatState;
							if (combatState != null)
							{
								IEnumerable<AbstractModel> enumerable = default(IEnumerable<AbstractModel>);
								return Math.Max(Hook.ModifyDamage(runState, combatState, context.Target, dealerFactory(context), value, props, card, (CardPlay)null, (ModifyDamageHookType)14, valueOrDefault, ref enumerable), 0m);
							}
						}
					}
					return Math.Max(num, 0m);
				}
			}
			return Math.Max(value, 0m);
		}

		private static decimal CalculatePowerAmountGivenPreview<T>(CardModel? card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks, Func<CardModel?, CardPreviewMode, Creature?, bool, decimal> previewBaseValueFactory) where T : PowerModel
