		private static decimal CalculateBlockPreview(CardModel? card, CardPreviewMode previewMode, Creature? target, bool runGlobalHooks, Func<CardModel?, CardPreviewMode, Creature?, bool, decimal> previewBaseValueFactory, Func<CardModel, Creature> blockTargetFactory, ValueProp props)
