							{
								IEnumerable<AbstractModel> enumerable = default(IEnumerable<AbstractModel>);
								return Hook.ModifyBlock(combatState, val, value, props, card, (CardPlay)null, ref enumerable);
							}
						}
					}
					return num;
				}
			}
			return value;
		}
