	/// <summary>
	///     <para xml:lang="en">
	///         Reflows visible bottom-row mod card-pile buttons without moving controls that use
	///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileAnchorKind.Custom" />.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         重新排列战斗界面底部行中可见的模组卡牌牌堆按钮，但不移动使用
	///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileAnchorKind.Custom" /> 的控件。
	///     </para>
	/// </summary>
	internal static class ModCardPileCombatLayout
	{
		private const float BottomLeftStackDeltaX = 100f;

		private const float BottomRightStackDeltaX = -100f;

		public static void Relayout(NCombatPilesContainer? container)
		{
			if (container == null || !((Node)container).IsInsideTree())
			{
				return;
			}
			NDrawPileButton drawPile = container.DrawPile;
			if (drawPile == null)
			{
				return;
			}
			NDiscardPileButton discardPile = container.DiscardPile;
			if (discardPile != null)
			{
				NExhaustPileButton exhaustPile = container.ExhaustPile;
				if (exhaustPile != null)
				{
					List<NModCardPileButton> buttons = ((IEnumerable)((Node)container).GetChildren(false)).OfType<NModCardPileButton>().ToList();
					RelayoutLeft((Control)(object)drawPile, (Control)(object)discardPile, buttons);
					RelayoutRight((Control)(object)exhaustPile, buttons);
				}
			}
		}

		private static void RelayoutLeft(Control draw, Control discard, IReadOnlyList<NModCardPileButton> buttons)
		{
			//IL_00b6: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ca: Unknown result type (might be due to invalid IL or missing references)
			//IL_00cf: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d6: Unknown result type (might be due to invalid IL or missing references)
			//IL_00db: Unknown result type (might be due to invalid IL or missing references)
			//IL_007f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0093: Unknown result type (might be due to invalid IL or missing references)
			//IL_0098: Unknown result type (might be due to invalid IL or missing references)
			//IL_009f: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a4: Unknown result type (might be due to invalid IL or missing references)
			List<NModCardPileButton> list = buttons.Where(TakesLeftAutoSlot).OrderBy<NModCardPileButton, string>((NModCardPileButton b) => b.Definition.Id, StringComparer.Ordinal).ToList();
			int num = 0;
			int num2 = 0;
			foreach (NModCardPileButton item in list)
			{
				ModCardPileAnchor anchor = item.Definition.Anchor;
				if (anchor.Kind == ModCardPileAnchorKind.BottomLeftSecondary)
				{
					((Control)item).Position = discard.Position + new Vector2(100f * (float)(num2 + 1), 0f) + anchor.Offset;
					num2++;
				}
				else
				{
					((Control)item).Position = draw.Position + new Vector2(100f * (float)(num + 1), 0f) + anchor.Offset;
					num++;
				}
			}
		}

		private static void RelayoutRight(Control exhaust, IReadOnlyList<NModCardPileButton> buttons)
		{
			//IL_00eb: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ff: Unknown result type (might be due to invalid IL or missing references)
			//IL_0104: Unknown result type (might be due to invalid IL or missing references)
			//IL_010b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0110: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b1: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c7: Unknown result type (might be due to invalid IL or missing references)
			//IL_00cc: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00d8: Unknown result type (might be due to invalid IL or missing references)
			List<NModCardPileButton> list = buttons.Where(TakesRightAutoSlot).OrderBy<NModCardPileButton, string>((NModCardPileButton b) => b.Definition.Id, StringComparer.Ordinal).ToList();
			int num = Math.Max(1, list.Count((NModCardPileButton button) => button.Definition.Anchor.Kind != ModCardPileAnchorKind.BottomRightSecondary));
			int num2 = 0;
			int num3 = 0;
			foreach (NModCardPileButton item in list)
			{
				ModCardPileAnchor anchor = item.Definition.Anchor;
				if (anchor.Kind == ModCardPileAnchorKind.BottomRightSecondary)
				{
					((Control)item).Position = exhaust.Position + new Vector2(-100f * (float)(num + num3 + 1), 0f) + anchor.Offset;
					num3++;
				}
				else
				{
					((Control)item).Position = exhaust.Position + new Vector2(-100f * (float)(num2 + 1), 0f) + anchor.Offset;
					num2++;
				}
			}
		}

		private static bool TakesLeftAutoSlot(NModCardPileButton button)
		{
			ModCardPileDefinition definition = button.Definition;
			if ((object)definition == null)
			{
				return false;
			}
			if (definition.Style != ModCardPileUiStyle.BottomLeft)
			{
				return false;
			}
			if (definition.Anchor.Kind != ModCardPileAnchorKind.Custom)
			{
				return ((CanvasItem)button).Visible;
			}
			return false;
		}

		private static bool TakesRightAutoSlot(NModCardPileButton button)
		{
			ModCardPileDefinition definition = button.Definition;
			if ((object)definition == null)
			{
				return false;
			}
			if (definition.Style != ModCardPileUiStyle.BottomRight)
			{
				return false;
			}
			if (definition.Anchor.Kind != ModCardPileAnchorKind.Custom)
			{
				return ((CanvasItem)button).Visible;
			}
			return false;
		}
	}
