		/// </summary>
		public static void InjectCombatButtons(NCombatPilesContainer container)
		{
			ModCardPileDefinition[] definitionsByStyle = ModCardPileRegistry.GetDefinitionsByStyle(ModCardPileUiStyle.BottomLeft);
			ModCardPileDefinition[] definitionsByStyle2 = ModCardPileRegistry.GetDefinitionsByStyle(ModCardPileUiStyle.BottomRight);
			if (definitionsByStyle.Length != 0 || definitionsByStyle2.Length != 0)
			{
				MountBottomLeftButtons(container, definitionsByStyle);
