			ModCardPileDefinition[] definitionsByStyle = ModCardPileRegistry.GetDefinitionsByStyle(ModCardPileUiStyle.TopBarDeck);
			if (definitionsByStyle.Length == 0)
			{
				return;
			}
			ModCardPileDefinition[] array = definitionsByStyle;
			foreach (ModCardPileDefinition obj in array)
			{
				NModCardPileButton nModCardPileButton = NModTopBarPileButton.Create(obj);
				GodotTreeExtensions.AddChildSafely((Node)(object)topBar, (Node)(object)nModCardPileButton);
				ModCardPileAnchor anchor = obj.Anchor;
				switch (anchor.Kind)
				{
				case ModCardPileAnchorKind.Custom:
					((Control)nModCardPileButton).Position = ModCardPileCustomMountGeometry.ControlTopLeftFromAuthoring(anchor, ModCardPileUiStyle.TopBarDeck);
					break;
				case ModCardPileAnchorKind.TopBarAfterDeck:
					ModTopBarLayout.PlaceAfterDeck(topBar, nModCardPileButton, anchor.Offset);
					break;
				case ModCardPileAnchorKind.TopBarBeforeModifiers:
					ModTopBarLayout.PlaceBeforeModifiers(topBar, nModCardPileButton, anchor.Offset);
					break;
				default:
					ModTopBarLayout.Place(topBar, nModCardPileButton, anchor.Offset);
					break;
				}
			}
		}

