				if (val2 != null && ((Node)val2).IsInsideTree())
				{
					return ControlToGlobalScreenPoint(val2, val);
				}
				break;
			}
			}
			return val;
		}

		private static Vector2 ControlToGlobalScreenPoint(Control host, Vector2 localPoint)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Unknown result type (might be due to invalid IL or missing references)
			return ((CanvasItem)host).GetGlobalTransformWithCanvas() * localPoint;
		}

		private static Vector2 ApplyCardNodeOffset(Vector2 centerPosition, NCard? node)
		{
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Unknown result type (might be due to invalid IL or missing references)
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			//IL_0016: Unknown result type (might be due to invalid IL or missing references)
			//IL_0003: Unknown result type (might be due to invalid IL or missing references)
			if (node == null)
			{
				return centerPosition;
			}
			return centerPosition - ((Control)node).Size * 0.5f;
		}

		private static Vector2 FallbackPosition()
		{
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0036: Unknown result type (might be due to invalid IL or missing references)
			//IL_0009: Unknown result type (might be due to invalid IL or missing references)
			NGame instance = NGame.Instance;
			if (instance == null)
			{
				return Vector2.Zero;
			}
			Rect2 viewportRect = ((CanvasItem)instance).GetViewportRect();
			Vector2 size = ((Rect2)(ref viewportRect)).Size;
			return new Vector2(size.X * 0.5f, size.Y * 0.5f);
		}
	}
	/// <summary>
