		internal ModCardPileOpenContext(ModCardPileDefinition definition, ModCardPile pile, Player player, NModCardPileButton? button)
		{
			Definition = definition;
			Pile = pile;
			Player = player;
			Button = button;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Opens the current pile in the vanilla <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.NCardPileScreen" />, using the registered
		///         hotkeys when present.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用原版 <see cref="T:MegaCrit.Sts2.Core.Nodes.Screens.NCardPileScreen" /> 打开当前牌堆，并在已注册快捷键时使用这些快捷键。
		///     </para>
		/// </summary>
		public void ShowDefaultPileScreen()
		{
			NCardPileScreen.ShowScreen((CardPile)(object)Pile, Definition.Hotkeys ?? Array.Empty<string>());
