		{
			using (SyncRoot.EnterScope())
			{
				return Definitions.Values.Where((ModCardPileDefinition def) => def.Style == style).OrderBy<ModCardPileDefinition, string>((ModCardPileDefinition def) => def.Id, StringComparer.Ordinal).ToArray();
