		private ModCardPileDefinition RegisterCore(string id, ModCardPileSpec spec)
		{
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0023: Unknown result type (might be due to invalid IL or missing references)
			//IL_002b: Unknown result type (might be due to invalid IL or missing references)
			//IL_007b: Unknown result type (might be due to invalid IL or missing references)
			//IL_018e: Unknown result type (might be due to invalid IL or missing references)
			//IL_01d6: Unknown result type (might be due to invalid IL or missing references)
			//IL_01e1: Expected I4, but got Unknown
			EnsureMutable("register card piles");
			string text = NormalizeId(id);
			PileType value = DynamicEnumValueRegistry<PileType>.Register(_modId, text).Value;
			string modId = _modId;
			ModCardPileScope scope = spec.Scope;
			ModCardPileUiStyle style = spec.Style;
			ModCardPileAnchor anchor = spec.Anchor;
			string? iconPath = spec.IconPath;
			string[]? hotkeys = spec.Hotkeys;
			int cardShouldBeVisible;
			if (!spec.CardShouldBeVisible)
			{
				if ((object)spec != null && spec.Style == ModCardPileUiStyle.ExtraHand)
				{
					ModCardPileExtraHandSpec extraHand = spec.ExtraHand;
					if ((object)extraHand != null)
					{
						cardShouldBeVisible = (extraHand.AllowCardPlay ? 1 : 0);
						goto IL_0074;
					}
				}
				cardShouldBeVisible = 0;
			}
			else
			{
				cardShouldBeVisible = 1;
			}
			goto IL_0074;
			IL_0074:
			ModCardPileDefinition modCardPileDefinition = new ModCardPileDefinition(modId, text, value, scope, style, anchor, iconPath, hotkeys, (byte)cardShouldBeVisible != 0, spec.OnOpen, spec.HoverTipScreenOffset, spec.HoverTipPlacement, spec.VisibleWhen, spec.FlightTargetPositionResolver, spec.FlightStartPositionResolver, spec.View, spec.ExtraHand);
			using (SyncRoot.EnterScope())
			{
				EnsureMutable("register card piles");
				if (Definitions.TryGetValue(text, out ModCardPileDefinition value2))
				{
					if ((object)value2.ModId != modCardPileDefinition.ModId && !StringComparer.OrdinalIgnoreCase.Equals(value2.ModId, modCardPileDefinition.ModId))
					{
						throw new InvalidOperationException($"Card pile '{text}' is already registered by mod '{value2.ModId}'; mod '{modCardPileDefinition.ModId}' cannot re-register it.");
					}
					return value2;
				}
				Definitions[text] = modCardPileDefinition;
				DefinitionsByPileType[value] = modCardPileDefinition;
				RebuildDefinitionSnapshotsLocked();
			}
			_logger.Info($"[CardPiles] Registered pile: {text} (PileType=0x{(int)value:X8}, Style={spec.Style}, Scope={spec.Scope})", 1);
			return modCardPileDefinition;
		}

		private static void RebuildDefinitionSnapshotsLocked()
		{
			ModCardPileDefinition[] array = Definitions.Values.OrderBy<ModCardPileDefinition, string>((ModCardPileDefinition definition) => definition.Id, StringComparer.Ordinal).ToArray();
			Volatile.Write(ref _definitionsSnapshot, array);
			Volatile.Write(ref _combatDefinitionsSnapshot, array.Where((ModCardPileDefinition definition) => definition.Scope == ModCardPileScope.CombatOnly).ToArray());
		}

		private void EnsureMutable(string operation)
		{
			if (!IsFrozen)
			{
				return;
			}
			throw new InvalidOperationException($"Cannot {operation} after pile registration has been frozen ({_freezeReason ?? "unknown"}). " + "Register piles from your mod initializer before model initialization.");
		}

		private static string NormalizeId(string id)
		{
			return id.Trim();
		}
	}
	/// <summary>
	///     <para xml:lang="en">Specifies the lifetime and storage owner of a mod card pile.</para>
	///     <para xml:lang="zh-CN">指定模组卡牌牌堆的生命周期与存储主体。</para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileScope.CombatOnly" /> piles are attached to <c>PlayerCombatState</c>, participate in
	///         <c>PlayerCombatState.AllPiles</c> and <c>IsCombatPile</c>, and are discarded with that combat.
	///     </para>
	///     <para xml:lang="en">
	///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileScope.RunPersistent" /> piles live on <c>Player</c> and persist across combats (much like
	///         <c>Player.Deck</c>). They participate in <c>Player.Piles</c> after they have been resolved and
	///         are serialized through RitsuLib run-saved data.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileScope.CombatOnly" /> 牌堆附加到 <c>PlayerCombatState</c>，参与
	///         <c>PlayerCombatState.AllPiles</c> 与 <c>IsCombatPile</c>，并随该场战斗一同丢弃。
	///     </para>
	///     <para xml:lang="zh-CN">
	///         <see cref="F:STS2RitsuLib.CardPiles.ModCardPileScope.RunPersistent" /> 牌堆附加到 <c>Player</c>，并像 <c>Player.Deck</c> 一样
	///         跨战斗保留。解析后它们会参与 <c>Player.Piles</c>，并通过 RitsuLib
	///         跑局保存数据序列化。
	///     </para>
	/// </remarks>
	public enum ModCardPileScope
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Creates the pile lazily for each <c>PlayerCombatState</c> and discards it when combat ends.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         为每个 <c>PlayerCombatState</c> 延迟创建牌堆，并在战斗结束时丢弃。
		///     </para>
		/// </summary>
		CombatOnly,
		/// <summary>
		///     <para xml:lang="en">Attaches the pile to a <c>Player</c> and saves it with the run.</para>
		///     <para xml:lang="zh-CN">将牌堆附加到 <c>Player</c>，并随跑局保存。</para>
		/// </summary>
		RunPersistent
	}
