		}

		private static readonly ModCardPileSortOption[] DefaultSortOptions = new ModCardPileSortOption[4]
		{
			ModCardPileSortOption.Obtained,
			ModCardPileSortOption.Type,
			ModCardPileSortOption.Cost,
			ModCardPileSortOption.Alphabetical
		};

		internal IReadOnlyList<ModCardPileSortOption> GetSortOptions()
		{
			IReadOnlyList<ModCardPileSortOption> sortOptions = SortOptions;
			if (sortOptions == null || sortOptions.Count <= 0)
			{
				return DefaultSortOptions;
			}
			return SortOptions;
		}

		internal List<SortingOrders> CreateDefaultSorting()
		{
			IReadOnlyList<SortingOrders> defaultSorting = DefaultSorting;
			if (defaultSorting == null || defaultSorting.Count <= 0)
			{
				int num = 1;
				List<SortingOrders> list = new List<SortingOrders>(num);
				CollectionsMarshal.SetCount(list, num);
				CollectionsMarshal.AsSpan(list)[0] = (SortingOrders)8;
				return list;
			}
			return DefaultSorting.ToList();
		}
	}
