	internal static class ModExtraHandHandView
	{
		private static readonly FieldRef<CardPile, List<CardModel>> RawCards = AccessTools.FieldRefAccess<CardPile, List<CardModel>>("_cards");

		private static readonly FieldRef<PlayerCombatState, Player> CombatStatePlayer = AccessTools.FieldRefAccess<PlayerCombatState, Player>("_player");

		internal static CardPile GetForQueries(PileType pileType, Player player)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			return Get(pileType, player, IsCardPlayEnabled);
		}

		internal static CardPile GetQueryHand(PlayerCombatState state)
		{
			return Get((PileType)2, CombatStatePlayer.Invoke(state), IsCardPlayEnabled);
		}

		internal static IReadOnlyList<CardModel> GetCardsForQueries(CardPile pile)
		{
			Player val = FindHandOwner(pile);
			if (val != null)
			{
				return Get((PileType)2, val, IsCardPlayEnabled).Cards;
			}
			return pile.Cards;
		}

		internal static CardPile GetForTurnEnd(PileType pileType, Player player)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			return Get(pileType, player, ModExtraHandBehavior.ApplyHandTurnEndRules);
		}

		internal static CardPile GetForFlush(PileType pileType, Player player)
		{
			//IL_0000: Unknown result type (might be due to invalid IL or missing references)
			return Get(pileType, player, ModExtraHandBehavior.FlushWithHand);
		}

		internal static CardModel[] GetExtraCards(Player player, ModExtraHandBehavior behavior)
		{
			return (from card in (from pile in GetExistingPiles(player)
					where pile.Definition.Style == ModCardPileUiStyle.ExtraHand && pile.Definition.ExtraHand.Behaviors.HasFlag(behavior)
					select pile).OrderBy<ModCardPile, string>((ModCardPile pile) => pile.Definition.Id, StringComparer.Ordinal).SelectMany((ModCardPile pile) => ((CardPile)pile).Cards)
				where card.Owner == player
				select card).ToArray();
		}

		private static CardPile Get(PileType pileType, Player player, ModExtraHandBehavior behavior)
		{
			//IL_000d: Unknown result type (might be due to invalid IL or missing references)
			return Get(pileType, player, (ModCardPile pile) => pile.Definition.ExtraHand.Behaviors.HasFlag(behavior));
		}

		private static CardPile Get(PileType pileType, Player player, Func<ModCardPile, bool> includePile)
		{
			//IL_0014: Unknown result type (might be due to invalid IL or missing references)
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_0023: Invalid comparison between Unknown and I4
			//IL_00ae: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b4: Expected O, but got Unknown
			CardPile pile = PileTypeExtensions.GetPile(pileType, player);
			if ((int)pileType != 2)
			{
				return pile;
			}
			CardModel[] array = (from card in (from candidate in GetExistingPiles(player)
					where candidate.Definition.Style == ModCardPileUiStyle.ExtraHand && includePile(candidate)
					select candidate).OrderBy<ModCardPile, string>((ModCardPile candidate) => candidate.Definition.Id, StringComparer.Ordinal).SelectMany((ModCardPile candidate) => ((CardPile)candidate).Cards)
				where card.Owner == player
				select card).ToArray();
			if (array.Length == 0)
			{
				return pile;
			}
			CardPile val = new CardPile((PileType)2);
			List<CardModel> list = RawCards.Invoke(val);
			list.AddRange(pile.Cards);
			CardModel[] array2 = array;
			foreach (CardModel item in array2)
			{
				if (!list.Contains(item))
				{
					list.Add(item);
				}
			}
			return val;
		}

		private static bool IsCardPlayEnabled(ModCardPile pile)
		{
			if (!pile.Definition.ExtraHand.AllowCardPlay)
			{
				return false;
			}
			return ModCardPileButtonRegistry.TryGetExtraHand(pile.Definition)?.CardPlayEnabled ?? true;
		}

		private static Player? FindHandOwner(CardPile pile)
		{
			CombatState obj = CombatManager.Instance.DebugOnlyGetState();
			if (obj == null)
			{
				return null;
			}
			return obj.Players.FirstOrDefault(delegate(Player candidate)
			{
				PlayerCombatState playerCombatState = candidate.PlayerCombatState;
				return ((playerCombatState != null) ? playerCombatState.Hand : null) == pile;
			});
		}

		private static IEnumerable<ModCardPile> GetExistingPiles(Player player)
		{
			PlayerCombatState playerCombatState = player.PlayerCombatState;
			if (playerCombatState != null)
			{
				foreach (ModCardPile combatPile in ModCardPileStorage.GetCombatPiles(playerCombatState))
				{
					yield return combatPile;
				}
			}
			foreach (ModCardPile runPile in ModCardPileStorage.GetRunPiles(player))
			{
				yield return runPile;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Specifies a built-in card arrangement for an extra-hand pile.</para>
	///     <para xml:lang="zh-CN">指定额外手牌牌堆的内置卡牌排列方式。</para>
	/// </summary>
	public enum ModExtraHandLayoutDirection
	{
		/// <summary>
		///     <para xml:lang="en">Arranges cards from left to right.</para>
		///     <para xml:lang="zh-CN">从左向右排列卡牌。</para>
		/// </summary>
		Horizontal,
		/// <summary>
		///     <para xml:lang="en">Arranges cards from top to bottom.</para>
		///     <para xml:lang="zh-CN">从上向下排列卡牌。</para>
		/// </summary>
		Vertical,
		/// <summary>
		///     <para xml:lang="en">
		///         Uses the base-game hand's fan, scale, rotation, and focused-card displacement rules.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         使用游戏原有手牌的扇形、缩放、旋转与焦点卡牌让位规则。
		///     </para>
		/// </summary>
		VanillaHand
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Coordinates playable extra-hand cards with the vanilla hand-based manual-play flow.
	///     </para>
	///     <para xml:lang="zh-CN">协调可打出的额外手牌卡牌与原版基于手牌的手动打牌流程。</para>
	/// </summary>
	/// <remarks>
	///     <para xml:lang="en">
	///         The card remains in its extra-hand pile while targeting and queued. The vanilla manual-play checks
	///         treat that pile as hand-compatible only inside the patched play path. Canceling targeting or the
	///         queued action returns the same card node to the extra hand without changing model ownership.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         目标选择及排队期间，卡牌会保留在额外手牌堆中。仅在修补后的出牌路径内，原版手动出牌检查会将该牌堆
	///         视为与手牌兼容。取消目标选择或已排队动作时，同一个卡牌节点会退回额外手牌，且不改变模型归属。
	///     </para>
	/// </remarks>
	internal static class ModExtraHandPlayCoordinator
	{
		private sealed class PlayOrigin(NModExtraHand container, NHandCardHolder holder, CardModel card, CardPile sourcePile)
		{
			public NModExtraHand Container { get; } = container;

			public NHandCardHolder Holder { get; } = holder;

			public CardModel Card { get; } = card;

			public CardPile SourcePile { get; } = sourcePile;

			public NCardPlay? CardPlay { get; set; }

			public Action<CardModel>? SourceCardRemoved { get; set; }

			public bool Closed { get; set; }
		}

		private const float MousePlayZoneScreenProportion = 0.75f;

		private const float MousePlayZoneStartOffset = 100f;

		private static readonly Action<NPlayerHand, NHandCardHolder, bool> StartVanillaCardPlay = PrivateAccess.DeclaredMethodDelegate<NPlayerHand, Action<NPlayerHand, NHandCardHolder, bool>>("StartCardPlay", new Type[2]
		{
			typeof(NHandCardHolder),
			typeof(bool)
		});

		private static readonly FieldRef<NPlayerHand, NCardPlay?> CurrentCardPlayRef = PrivateAccess.FieldRef<NPlayerHand, NCardPlay>("_currentCardPlay");

		private static readonly FieldRef<NPlayerHand, StringName[]> SelectCardShortcutsRef = PrivateAccess.FieldRef<NPlayerHand, StringName[]>("_selectCardShortcuts");

		private static readonly FieldRef<NMouseCardPlay, float> MouseDragStartYRef = PrivateAccess.FieldRef<NMouseCardPlay, float>("_dragStartYPosition");

		private static readonly Dictionary<CardModel, PlayOrigin> PendingOrigins = new Dictionary<CardModel, PlayOrigin>();

		private static PlayOrigin? _active;

		internal static bool IsPlaying => _active != null;

		internal static bool IsActiveHolder(NHandCardHolder? holder)
		{
			if (holder != null)
			{
				return _active?.Holder == holder;
			}
			return false;
		}

		internal static void CancelActiveTargeting()
		{
			NCardPlay val = _active?.CardPlay;
			if (val != null && GodotObject.IsInstanceValid((GodotObject)(object)val))
			{
				if (NTargetManager.Instance.IsInSelection)
				{
					NTargetManager.Instance.CancelTargeting();
				}
				val.CancelPlayCard();
			}
		}

		internal static void CancelActiveTargeting(NModExtraHand container)
		{
			if (_active?.Container == container)
			{
				CancelActiveTargeting();
			}
		}

		internal static bool TryBegin(NModExtraHand container, NHandCardHolder holder)
		{
			//IL_0024: Unknown result type (might be due to invalid IL or missing references)
			//IL_002f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0115: Unknown result type (might be due to invalid IL or missing references)
			//IL_011b: Unknown result type (might be due to invalid IL or missing references)
			if (_active == null)
			{
				CardModel cardModel = ((NCardHolder)holder).CardModel;
				if (cardModel != null)
				{
					CardPile pile = cardModel.Pile;
					if (pile == null || pile.Type != container.Definition.PileType)
					{
						return false;
					}
					NPlayerHand instance = NPlayerHand.Instance;
					if (instance == null)
					{
						return false;
					}
					PlayOrigin origin = new PlayOrigin(container, holder, cardModel, pile);
					try
					{
						PendingOrigins[cardModel] = origin;
						origin.SourceCardRemoved = delegate(CardModel removed)
						{
							OnSourceCardRemoved(origin, removed);
						};
						pile.CardRemoved += origin.SourceCardRemoved;
						_active = origin;
						((Node)holder).Reparent((Node)(object)instance.CardHolderContainer, true);
						StartVanillaCardPlayWithExtraHandShortcut(instance, holder);
						NCardPlay val = CurrentCardPlayRef.Invoke(instance);
						if (val == null || !GodotObject.IsInstanceValid((GodotObject)(object)val) || val.Holder != holder)
						{
							throw new InvalidOperationException("Vanilla hand did not create a card-play node for the extra-hand holder.");
						}
						origin.CardPlay = val;
						NMouseCardPlay val2 = (NMouseCardPlay)(object)((val is NMouseCardPlay) ? val : null);
						if (val2 != null)
						{
							NormalizeMouseDragStart(val2);
						}
						holder.SetIndexLabel(0);
						((GodotObject)val).Connect(SignalName.Finished, Callable.From<bool>((Action<bool>)delegate(bool success)
						{
							OnTargetingFinished(origin, success);
						}), 0u);
						return true;
					}
					catch (Exception ex)
					{
