		internal static NHandCardHolder ReturnCancelledQueuedCard(NPlayerHand hand, NCard cardNode, int index)
		{
			CardModel model = cardNode.Model;
			if (model == null || !PendingOrigins.TryGetValue(model, out PlayOrigin value))
			{
				return hand.Add(cardNode, index);
