					instance.ForceRefreshCardIndices();
				}
			}
		}

		private static void OnTargetingFinished(PlayOrigin origin, bool success)
		{
			if (success)
			{
				origin.Container.ReleaseHolderForQueuedPlay(origin.Card);
			}
			if (!origin.Closed)
			{
				if (_active == origin)
				{
					_active = null;
				}
				if (!success)
				{
					RollBackTargeting(origin);
				}
			}
		}

		private static void NormalizeMouseDragStart(NMouseCardPlay cardPlay)
		{
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			//IL_000b: Unknown result type (might be due to invalid IL or missing references)
			//IL_000e: Unknown result type (might be due to invalid IL or missing references)
			Rect2 visibleRect = ((Node)cardPlay).GetViewport().GetVisibleRect();
			float num = ((Rect2)(ref visibleRect)).Size.Y * 0.75f;
			ref float reference = ref MouseDragStartYRef.Invoke(cardPlay);
			if (reference <= num)
			{
				reference = num + 100f;
			}
		}

		private static void StartVanillaCardPlayWithExtraHandShortcut(NPlayerHand hand, NHandCardHolder holder)
		{
			int index = ((Node)holder).GetIndex(false);
			if (index < 0)
			{
				throw new InvalidOperationException("Extra-hand holder is not mounted in the vanilla hand container.");
			}
			ref StringName[] reference = ref SelectCardShortcutsRef.Invoke(hand);
			StringName[] array = reference;
			StringName[] array2 = (StringName[])(object)new StringName[Math.Max(array.Length, index + 1)];
			array.CopyTo(array2, 0);
			array2[index] = MegaInput.cancel;
			reference = array2;
			try
			{
				StartVanillaCardPlay(hand, holder, arg3: false);
			}
			finally
			{
				reference = array;
			}
		}

		private static void RollBackTargeting(PlayOrigin origin)
		{
			if (!origin.Closed)
			{
				if (_active == origin)
				{
					_active = null;
				}
				ClearOrigin(origin);
				origin.Container.RestoreCancelledPlay(origin.Card, origin.Holder);
				NPlayerHand instance = NPlayerHand.Instance;
				if (instance != null)
				{
					instance.ForceRefreshCardIndices();
				}
			}
		}

		private static void OnSourceCardRemoved(PlayOrigin origin, CardModel removed)
		{
			if (origin.Card == removed)
			{
				ClearOrigin(origin);
			}
		}

		private static void ClearOrigin(PlayOrigin origin)
		{
			if (_active == origin)
			{
				_active = null;
			}
			if (!origin.Closed)
			{
				origin.Closed = true;
				PendingOrigins.Remove(origin.Card);
				if (origin.SourceCardRemoved != null)
				{
					origin.SourcePile.CardRemoved -= origin.SourceCardRemoved;
				}
				origin.SourceCardRemoved = null;
			}
		}
	}
	internal static class ModExtraHandSemanticContext
	{
		private sealed class State(CardModel card, State? previous)
		{
			public CardModel Card { get; } = card;

			public State? Previous { get; } = previous;
		}

		private sealed class Scope(State? previous) : IDisposable
		{
			private State? _previous = previous;

			private bool _disposed;

			public void Dispose()
			{
				if (!_disposed)
				{
					_disposed = true;
					Current.Value = _previous;
					_previous = null;
				}
			}
		}

		private static readonly AsyncLocal<State?> Current = new AsyncLocal<State>();

		internal static IDisposable? EnterPlayEvaluation(CardModel card)
		{
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			if (IsActive(card))
			{
				return null;
			}
			CardPile pile = card.Pile;
			if (pile == null || !ModCardPileRegistry.TryGetByPileType(pile.Type, out ModCardPileDefinition definition) || definition.Style != ModCardPileUiStyle.ExtraHand || !definition.ExtraHand.AllowCardPlay)
			{
				return null;
			}
			State value = Current.Value;
			Current.Value = new State(card, value);
			return new Scope(value);
		}

		internal static bool IsActive(CardModel card)
		{
			for (State state = Current.Value; state != null; state = state.Previous)
			{
				if (state.Card == card)
				{
					return true;
				}
			}
			return false;
		}
	}
