		///         <see cref="T:STS2RitsuLib.CardPiles.ModCardPile" />；操作模式会初始化回调上下文和显示状态。
		///     </para>
		/// </summary>
		public void Initialize(Player player)
		{
			//IL_0045: Unknown result type (might be due to invalid IL or missing references)
			//IL_008f: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(player, "player");
			_player = player;
			if (ActionDefinition != null)
			{
				TryReplaceCountLabelWithVanillaDeckClone();
				if (string.IsNullOrWhiteSpace(ActionDefinition.IconPath))
				{
					TryReplaceIconWithVanillaDeckClone();
				}
				_hoverTip = ModTopBarButtonHoverTipFactory.Create(ActionDefinition);
				PollActionCount(force: true);
				RefreshActionOpenState(immediate: true);
				return;
			}
			if (UsesCombatBottomChrome())
			{
				TryReplaceCountLabelWithVanillaCombatPileTemplate();
			}
			else
			{
				TryReplaceCountLabelWithVanillaDeckClone();
			}
			if (!(Definition == null))
			{
				AttachPile(ModCardPileStorage.Resolve(Definition.PileType, player));
				if (Definition.VisibleWhen != null)
				{
					RefreshPileButtonVisibility();
				}
			}
		}

		/// <inheritdoc />
		public override void _EnterTree()
		{
			((Node)this)._EnterTree();
			if (Definition != null)
			{
				ModCardPileButtonRegistry.RegisterButton(Definition, this);
			}
		}

		/// <inheritdoc />
		public override void _ExitTree()
		{
			((Node)this)._ExitTree();
			if (Definition != null)
			{
				ModCardPileButtonRegistry.UnregisterButton(Definition, this);
			}
			DetachPile();
			NHoverTipSet.Remove((Control)(object)this);
			Tween? bumpTween = _bumpTween;
			if (bumpTween != null)
			{
				bumpTween.Kill();
			}
			Tween? openStateTween = _openStateTween;
			if (openStateTween != null)
			{
				openStateTween.Kill();
			}
		}

		/// <inheritdoc />
		public override void _Process(double delta)
		{
			((Node)this)._Process(delta);
			if (ActionDefinition != null)
			{
				RefreshActionVisibility();
				PollActionCount(force: false);
				RefreshActionOpenState();
				return;
			}
			RefreshCombatScopedTopBarPile();
			if (Definition?.VisibleWhen != null)
			{
				RefreshPileButtonVisibility();
			}
		}

		/// <inheritdoc />
		public override void _GuiInput(InputEvent @event)
		{
			//IL_000b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0012: Invalid comparison between Unknown and I8
			InputEventMouseButton val = (InputEventMouseButton)(object)((@event is InputEventMouseButton) ? @event : null);
			if (val == null || (long)val.ButtonIndex != 1)
			{
				return;
			}
			if (val.Pressed)
			{
				if (!_pressed)
				{
					_pressed = true;
					OnPress();
				}
			}
			else if (_pressed)
			{
				_pressed = false;
				OnRelease();
			}
		}

