namespace STS2RitsuLib.Audio
{
	/// <summary>
	///     <para xml:lang="en">
	///         Tracks adaptive music plans and switches their room, combat, and victory tracks in response to
	///         run lifecycle events.
	///     </para>
	///     <para xml:lang="zh-CN">跟踪自适应音乐方案，并响应跑局生命周期事件切换其房间、战斗和胜利曲目。</para>
	/// </summary>
	public sealed class AudioAdaptiveMusicDirector : IDisposable
	{
		private readonly ConcurrentDictionary<AudioAdaptiveMusicHandle, AudioAdaptiveMusicPlan> _active = new ConcurrentDictionary<AudioAdaptiveMusicHandle, AudioAdaptiveMusicPlan>();

		private readonly IDisposable _combatEndedSubscription;

		private readonly IDisposable _combatStartingSubscription;

		private readonly IDisposable _combatVictorySubscription;

		private readonly IDisposable _roomEnteredSubscription;

		private readonly IDisposable _runEndedSubscription;

		private readonly IDisposable _runLoadedSubscription;

		private readonly IDisposable _runStartedSubscription;

		/// <summary>
		///     <para xml:lang="en">Gets the shared adaptive music director.</para>
		///     <para xml:lang="zh-CN">获取共享的自适应音乐调度器。</para>
		/// </summary>
		public static AudioAdaptiveMusicDirector Shared { get; } = new AudioAdaptiveMusicDirector();

		private AudioAdaptiveMusicDirector()
		{
			_runStartedSubscription = RitsuLibFramework.SubscribeLifecycle((Action<RunStartedEvent>)delegate
			{
				RefreshRoomState();
			}, true);
			_runLoadedSubscription = RitsuLibFramework.SubscribeLifecycle((Action<RunLoadedEvent>)delegate
			{
				RefreshRoomState();
			}, true);
			_roomEnteredSubscription = RitsuLibFramework.SubscribeLifecycle((Action<RoomEnteredEvent>)delegate
			{
				RefreshRoomState();
			}, true);
			_combatStartingSubscription = RitsuLibFramework.SubscribeLifecycle((Action<CombatStartingEvent>)delegate
			{
				SwitchCombatState();
			}, true);
			_combatVictorySubscription = RitsuLibFramework.SubscribeLifecycle((Action<CombatVictoryEvent>)delegate
			{
				SwitchVictoryState();
			}, true);
			_combatEndedSubscription = RitsuLibFramework.SubscribeLifecycle((Action<CombatEndedEvent>)delegate
			{
				RestoreAfterCombat();
			}, true);
			_runEndedSubscription = RitsuLibFramework.SubscribeLifecycle((Action<RunEndedEvent>)delegate
			{
				ClearAll(restoreVanillaMusic: false);
			}, true);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Disposes this director's lifecycle subscriptions without stopping or detaching its currently
		///         tracked handles.
		///     </para>
		///     <para xml:lang="zh-CN">释放此调度器的生命周期订阅，但不会停止或分离当前跟踪的句柄。</para>
		/// </summary>
		public void Dispose()
		{
			_runStartedSubscription.Dispose();
			_runLoadedSubscription.Dispose();
			_roomEnteredSubscription.Dispose();
			_combatStartingSubscription.Dispose();
			_combatVictorySubscription.Dispose();
			_combatEndedSubscription.Dispose();
			_runEndedSubscription.Dispose();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attaches an adaptive plan, immediately applies its room state, and returns its controlling
		///         handle.
		///     </para>
		///     <para xml:lang="zh-CN">附加自适应方案，立即应用其房间状态，并返回控制该方案的句柄。</para>
		/// </summary>
		/// <param name="plan">
		///     <para xml:lang="en">The lifecycle-driven music plan to track.</para>
		///     <para xml:lang="zh-CN">要跟踪的生命周期驱动音乐方案。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A handle that can stop the current override or dispose the attachment.</para>
		///     <para xml:lang="zh-CN">可停止当前覆盖或释放该附加关系的句柄。</para>
		/// </returns>
		public AudioAdaptiveMusicHandle Attach(AudioAdaptiveMusicPlan plan)
		{
			AudioAdaptiveMusicHandle audioAdaptiveMusicHandle = new AudioAdaptiveMusicHandle(plan);
			_active[audioAdaptiveMusicHandle] = plan;
			RefreshRoomState(audioAdaptiveMusicHandle, plan);
			return audioAdaptiveMusicHandle;
		}

		/// <summary>
		///     <para xml:lang="en">Removes a handle from lifecycle tracking without stopping its current music.</para>
		///     <para xml:lang="zh-CN">从生命周期跟踪中移除句柄，但不停止其当前音乐。</para>
		/// </summary>
		/// <param name="handle">
		///     <para xml:lang="en">The handle to detach.</para>
		///     <para xml:lang="zh-CN">要分离的句柄。</para>
		/// </param>
		public void Detach(AudioAdaptiveMusicHandle handle)
		{
			_active.TryRemove(handle, out AudioAdaptiveMusicPlan _);
		}

		private void RefreshRoomState()
		{
			foreach (KeyValuePair<AudioAdaptiveMusicHandle, AudioAdaptiveMusicPlan> item in _active)
			{
				RefreshRoomState(item.Key, item.Value);
			}
		}

		private static void RefreshRoomState(AudioAdaptiveMusicHandle handle, AudioAdaptiveMusicPlan plan)
		{
			if ((object)plan.RoomSource == null)
			{
				handle.Stop(restoreVanillaMusic: false);
				if (plan.RefreshVanillaRoomStateOnRoomEnter)
				{
					AudioVanillaBridge.RefreshTrackAndAmbience();
				}
			}
			else
			{
				AudioMusicHandle handle2 = GameFmod.Playback.PlayMusic(plan.RoomSource, plan.RoomOptions);
				handle.SwitchTo(handle2);
			}
		}

		private void SwitchCombatState()
		{
			foreach (KeyValuePair<AudioAdaptiveMusicHandle, AudioAdaptiveMusicPlan> item in _active)
			{
				if ((object)item.Value.CombatSource != null)
				{
					AudioMusicHandle handle = GameFmod.Playback.PlayMusic(item.Value.CombatSource, item.Value.CombatOptions);
					item.Key.SwitchTo(handle);
				}
			}
		}

		private void SwitchVictoryState()
		{
			foreach (KeyValuePair<AudioAdaptiveMusicHandle, AudioAdaptiveMusicPlan> item in _active)
			{
				if ((object)item.Value.VictorySource != null)
				{
					AudioMusicHandle handle = GameFmod.Playback.PlayMusic(item.Value.VictorySource, item.Value.VictoryOptions);
					item.Key.SwitchTo(handle);
				}
			}
		}

		private void RestoreAfterCombat()
		{
			foreach (KeyValuePair<AudioAdaptiveMusicHandle, AudioAdaptiveMusicPlan> item in _active)
			{
				if (item.Value.RestoreVanillaMusicOnCombatEnd)
				{
					item.Key.Stop();
				}
				else
				{
					RefreshRoomState(item.Key, item.Value);
				}
			}
		}

		private void ClearAll(bool restoreVanillaMusic)
		{
			foreach (AudioAdaptiveMusicHandle key in _active.Keys)
			{
				key.Stop(restoreVanillaMusic);
			}
			_active.Clear();
		}
	}
	/// <summary>
	///     <para xml:lang="en">Controls one adaptive music-plan attachment and the music handle currently selected for it.</para>
	///     <para xml:lang="zh-CN">控制一个自适应音乐方案附加关系及其当前选中的音乐句柄。</para>
	/// </summary>
	public sealed class AudioAdaptiveMusicHandle : IDisposable
	{
		private readonly AudioAdaptiveMusicPlan _plan;

		private AudioMusicHandle? _current;

		private int _disposed;

		internal AudioAdaptiveMusicHandle(AudioAdaptiveMusicPlan plan)
		{
			_plan = plan;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Stops the current override, applies the plan's stop-restoration policy, and permanently
		///         detaches this handle from the shared director.
		///     </para>
		///     <para xml:lang="zh-CN">停止当前覆盖，应用方案的停止恢复策略，并将此句柄永久从共享调度器中分离。</para>
		/// </summary>
		public void Dispose()
		{
			if (Interlocked.Exchange(ref _disposed, 1) == 0)
			{
				StopCore(restoreVanillaMusic: true);
				AudioAdaptiveMusicDirector.Shared.Detach(this);
			}
		}

		internal void SwitchTo(AudioMusicHandle? handle)
		{
			if (handle == null)
			{
				return;
			}
			if (Volatile.Read(in _disposed) != 0)
			{
				handle.Dispose();
				return;
			}
			Interlocked.Exchange(ref _current, handle)?.Dispose();
			if (Volatile.Read(in _disposed) != 0)
			{
				Interlocked.Exchange(ref _current, null)?.Dispose();
			}
		}

		internal void RefreshVolume(float volume)
		{
			Volatile.Read(in _current)?.TrySetVolume(volume);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Stops the current override without detaching the plan, allowing a later lifecycle event to
		///         start it again.
		///     </para>
		///     <para xml:lang="zh-CN">停止当前覆盖但不分离方案，因此后续生命周期事件仍可再次启动该方案。</para>
		/// </summary>
		/// <param name="restoreVanillaMusic">
		///     <para xml:lang="en">
		///         Whether to request restoration of run music when the plan's
		///         <see cref="P:STS2RitsuLib.Audio.AudioAdaptiveMusicPlan.RestoreVanillaMusicOnStop" /> policy permits it.
		///     </para>
		///     <para xml:lang="zh-CN">在方案的 <see cref="P:STS2RitsuLib.Audio.AudioAdaptiveMusicPlan.RestoreVanillaMusicOnStop" /> 策略允许时，是否请求恢复跑局音乐。</para>
		/// </param>
		public void Stop(bool restoreVanillaMusic = true)
		{
			if (Volatile.Read(in _disposed) == 0)
			{
				StopCore(restoreVanillaMusic);
			}
		}

		private void StopCore(bool restoreVanillaMusic)
		{
			Interlocked.Exchange(ref _current, null)?.Dispose();
			if (restoreVanillaMusic && _plan.RestoreVanillaMusicOnStop)
			{
				AudioVanillaBridge.RefreshRunMusic();
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Defines the room, combat, and victory music states driven by
	///         <see cref="T:STS2RitsuLib.Audio.AudioAdaptiveMusicDirector" />.
	///     </para>
	///     <para xml:lang="zh-CN">定义由 <see cref="T:STS2RitsuLib.Audio.AudioAdaptiveMusicDirector" /> 驱动的房间、战斗和胜利音乐状态。</para>
	/// </summary>
	public sealed class AudioAdaptiveMusicPlan
	{
		/// <summary>
		///     <para xml:lang="en">Gets or initializes the music source applied when room state is refreshed outside combat.</para>
		///     <para xml:lang="zh-CN">获取或初始化在非战斗房间状态刷新时应用的音乐源。</para>
		/// </summary>
		public AudioSource? RoomSource { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the music source applied when combat starts.</para>
		///     <para xml:lang="zh-CN">获取或初始化战斗开始时应用的音乐源。</para>
		/// </summary>
		public AudioSource? CombatSource { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the optional music source applied when combat victory is reported.</para>
		///     <para xml:lang="zh-CN">获取或初始化战斗胜利事件发生时应用的可选音乐源。</para>
		/// </summary>
		public AudioSource? VictorySource { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets or initializes whether a stop request may refresh the game's normal run music.</para>
		///     <para xml:lang="zh-CN">获取或初始化停止请求是否可以刷新游戏的正常跑局音乐。</para>
		/// </summary>
		public bool RestoreVanillaMusicOnStop { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes whether combat end stops the adaptive override instead of returning to
		///         <see cref="P:STS2RitsuLib.Audio.AudioAdaptiveMusicPlan.RoomSource" />. Normal run music is refreshed only when
		///         <see cref="P:STS2RitsuLib.Audio.AudioAdaptiveMusicPlan.RestoreVanillaMusicOnStop" /> is also enabled.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或初始化战斗结束时是否停止自适应覆盖，而不是返回 <see cref="P:STS2RitsuLib.Audio.AudioAdaptiveMusicPlan.RoomSource" />。
		///         仅当 <see cref="P:STS2RitsuLib.Audio.AudioAdaptiveMusicPlan.RestoreVanillaMusicOnStop" /> 也启用时才会刷新正常跑局音乐。
		///     </para>
		/// </summary>
		public bool RestoreVanillaMusicOnCombatEnd { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes whether room-state refreshes update the game's normal track and ambience
		///         when <see cref="P:STS2RitsuLib.Audio.AudioAdaptiveMusicPlan.RoomSource" /> is absent.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化在缺少 <see cref="P:STS2RitsuLib.Audio.AudioAdaptiveMusicPlan.RoomSource" /> 时，房间状态刷新是否更新游戏的正常曲目和环境音。</para>
		/// </summary>
		public bool RefreshVanillaRoomStateOnRoomEnter { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the playback options used to start <see cref="P:STS2RitsuLib.Audio.AudioAdaptiveMusicPlan.RoomSource" />.</para>
		///     <para xml:lang="zh-CN">获取或初始化启动 <see cref="P:STS2RitsuLib.Audio.AudioAdaptiveMusicPlan.RoomSource" /> 时使用的播放选项。</para>
		/// </summary>
		public AudioPlaybackOptions RoomOptions { get; init; } = new AudioPlaybackOptions
		{
			Scope = AudioLifecycleScope.Room
		};

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the playback options used to start <see cref="P:STS2RitsuLib.Audio.AudioAdaptiveMusicPlan.CombatSource" />.</para>
		///     <para xml:lang="zh-CN">获取或初始化启动 <see cref="P:STS2RitsuLib.Audio.AudioAdaptiveMusicPlan.CombatSource" /> 时使用的播放选项。</para>
		/// </summary>
		public AudioPlaybackOptions CombatOptions { get; init; } = new AudioPlaybackOptions
		{
			Scope = AudioLifecycleScope.Combat
		};

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the playback options used to start <see cref="P:STS2RitsuLib.Audio.AudioAdaptiveMusicPlan.VictorySource" />.</para>
		///     <para xml:lang="zh-CN">获取或初始化启动 <see cref="P:STS2RitsuLib.Audio.AudioAdaptiveMusicPlan.VictorySource" /> 时使用的播放选项。</para>
		/// </summary>
		public AudioPlaybackOptions VictoryOptions { get; init; } = new AudioPlaybackOptions
		{
			Scope = AudioLifecycleScope.Combat
		};
	}
	/// <summary>
	///     <para xml:lang="en">Provides factory methods for common adaptive music-plan patterns.</para>
	///     <para xml:lang="zh-CN">提供常见自适应音乐方案模式的工厂方法。</para>
	/// </summary>
	public static class AudioAdaptivePlans
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Creates a combat override with optional room and victory sources and caller-supplied playback
		///         options.
		///     </para>
		///     <para xml:lang="zh-CN">创建战斗音乐覆盖，并可指定房间与胜利音乐源以及调用方提供的播放选项。</para>
		/// </summary>
		/// <param name="combatSource">
		///     <para xml:lang="en">The music source applied when combat starts.</para>
		///     <para xml:lang="zh-CN">战斗开始时应用的音乐源。</para>
		/// </param>
		/// <param name="roomSource">
		///     <para xml:lang="en">The optional source applied outside combat; when absent, normal room music is refreshed.</para>
		///     <para xml:lang="zh-CN">在战斗外应用的可选音乐源；未提供时会刷新正常房间音乐。</para>
		/// </param>
		/// <param name="victorySource">
		///     <para xml:lang="en">The optional source applied after combat victory.</para>
		///     <para xml:lang="zh-CN">战斗胜利后应用的可选音乐源。</para>
		/// </param>
		/// <param name="combatOptions">
		///     <para xml:lang="en">The combat playback options, or null to use combat-scoped defaults.</para>
		///     <para xml:lang="zh-CN">战斗播放选项；为 <see langword="null" /> 时使用战斗作用域默认值。</para>
		/// </param>
		/// <param name="roomOptions">
		///     <para xml:lang="en">The room playback options, or null to use room-scoped defaults.</para>
		///     <para xml:lang="zh-CN">房间播放选项；为 <see langword="null" /> 时使用房间作用域默认值。</para>
		/// </param>
		/// <param name="victoryOptions">
		///     <para xml:lang="en">The victory playback options, or null to use combat-scoped defaults.</para>
		///     <para xml:lang="zh-CN">胜利播放选项；为 <see langword="null" /> 时使用战斗作用域默认值。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The configured adaptive music plan.</para>
		///     <para xml:lang="zh-CN">配置完成的自适应音乐方案。</para>
		/// </returns>
		public static AudioAdaptiveMusicPlan CombatOverride(AudioSource combatSource, AudioSource? roomSource = null, AudioSource? victorySource = null, AudioPlaybackOptions? combatOptions = null, AudioPlaybackOptions? roomOptions = null, AudioPlaybackOptions? victoryOptions = null)
		{
			return new AudioAdaptiveMusicPlan
			{
				RoomSource = roomSource,
				CombatSource = combatSource,
				VictorySource = victorySource,
				RoomOptions = (roomOptions ?? new AudioPlaybackOptions
				{
					Scope = AudioLifecycleScope.Room
				}),
				CombatOptions = (combatOptions ?? new AudioPlaybackOptions
				{
					Scope = AudioLifecycleScope.Combat
				}),
				VictoryOptions = (victoryOptions ?? new AudioPlaybackOptions
				{
					Scope = AudioLifecycleScope.Combat
				})
			};
		}

		/// <summary>
		///     <para xml:lang="en">Creates a run-wide room and combat override that returns to its room source after combat.</para>
		///     <para xml:lang="zh-CN">创建覆盖整场跑局房间与战斗音乐，并在战斗后返回其房间音乐源的方案。</para>
		/// </summary>
		/// <param name="roomSource">
		///     <para xml:lang="en">The music source applied outside combat.</para>
		///     <para xml:lang="zh-CN">在战斗外应用的音乐源。</para>
		/// </param>
		/// <param name="combatSource">
		///     <para xml:lang="en">The music source applied when combat starts.</para>
		///     <para xml:lang="zh-CN">战斗开始时应用的音乐源。</para>
		/// </param>
		/// <param name="victorySource">
		///     <para xml:lang="en">The optional source applied after combat victory.</para>
		///     <para xml:lang="zh-CN">战斗胜利后应用的可选音乐源。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The configured adaptive music plan.</para>
		///     <para xml:lang="zh-CN">配置完成的自适应音乐方案。</para>
		/// </returns>
		public static AudioAdaptiveMusicPlan FullRunOverride(AudioSource roomSource, AudioSource combatSource, AudioSource? victorySource = null)
		{
			return new AudioAdaptiveMusicPlan
			{
				RoomSource = roomSource,
				CombatSource = combatSource,
				VictorySource = victorySource,
				RestoreVanillaMusicOnCombatEnd = false,
				RoomOptions = new AudioPlaybackOptions
				{
					Scope = AudioLifecycleScope.Room
				},
				CombatOptions = new AudioPlaybackOptions
				{
					Scope = AudioLifecycleScope.Combat
				},
				VictoryOptions = new AudioPlaybackOptions
				{
					Scope = AudioLifecycleScope.Combat
				}
			};
		}
	}
	/// <summary>
	///     <para xml:lang="en">Specifies how a named audio channel handles a claim while another handle owns it.</para>
	///     <para xml:lang="zh-CN">指定已有句柄占用命名音频通道时如何处理新的占用请求。</para>
	/// </summary>
	public enum AudioChannelMode
	{
		/// <summary>
		///     <para xml:lang="en">Keeps the current owner and rejects the new claim.</para>
		///     <para xml:lang="zh-CN">保留当前占用者并拒绝新的占用请求。</para>
		/// </summary>
		KeepExisting,
		/// <summary>
		///     <para xml:lang="en">Stops and releases the current owner, replacing it only when release succeeds.</para>
		///     <para xml:lang="zh-CN">停止并释放当前占用者，并且仅在释放成功时用新句柄替换。</para>
		/// </summary>
		ReplaceExisting
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Tracks case-sensitive named channels and tag groups for playback replacement and bulk stop
	///         operations.
	///     </para>
	///     <para xml:lang="zh-CN">跟踪区分大小写的命名通道和标签组，用于替换播放与批量停止操作。</para>
	/// </summary>
	public sealed class AudioChannelRegistry
	{
		private sealed class ReferenceEqualityComparer : IEqualityComparer<IAudioHandle>
		{
			public static ReferenceEqualityComparer Instance { get; } = new ReferenceEqualityComparer();

			public bool Equals(IAudioHandle? x, IAudioHandle? y)
			{
				return x == y;
			}

			public int GetHashCode(IAudioHandle obj)
			{
				return RuntimeHelpers.GetHashCode(obj);
			}
		}

		private readonly ConcurrentDictionary<string, IAudioHandle> _channels = new ConcurrentDictionary<string, IAudioHandle>(StringComparer.Ordinal);

		private readonly ConcurrentDictionary<string, ConcurrentDictionary<IAudioHandle, byte>> _tags = new ConcurrentDictionary<string, ConcurrentDictionary<IAudioHandle, byte>>(StringComparer.Ordinal);

		/// <summary>
		///     <para xml:lang="en">Gets the shared channel and tag registry.</para>
		///     <para xml:lang="zh-CN">获取共享的通道与标签注册表。</para>
		/// </summary>
		public static AudioChannelRegistry Shared { get; } = new AudioChannelRegistry();

		private AudioChannelRegistry()
		{
		}

		/// <summary>
		///     <para xml:lang="en">Attempts to assign a handle to a named channel according to the requested collision policy.</para>
		///     <para xml:lang="zh-CN">按照指定的冲突策略尝试将句柄分配到命名通道。</para>
		/// </summary>
		/// <param name="channel">
		///     <para xml:lang="en">The case-sensitive channel name.</para>
		///     <para xml:lang="zh-CN">区分大小写的通道名称。</para>
		/// </param>
		/// <param name="handle">
		///     <para xml:lang="en">The handle that should own the channel.</para>
		///     <para xml:lang="zh-CN">应占用该通道的句柄。</para>
		/// </param>
		/// <param name="mode">
		///     <para xml:lang="en">How to handle an existing owner.</para>
		///     <para xml:lang="zh-CN">已有占用者的处理方式。</para>
		/// </param>
		/// <param name="allowFadeOut">
		///     <para xml:lang="en">Whether a replaced owner may fade out when stopped.</para>
		///     <para xml:lang="zh-CN">停止被替换的占用者时是否允许淡出。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when the handle already owns or successfully claims the channel;
		///         <see langword="false" /> when an existing owner is kept.
		///     </para>
		///     <para xml:lang="zh-CN">句柄已占用或成功占用该通道时为 <see langword="true" />；保留已有占用者时为 <see langword="false" />。</para>
		/// </returns>
		public bool TryClaimChannel(string channel, IAudioHandle handle, AudioChannelMode mode, bool allowFadeOut)
		{
			while (true)
			{
				if (_channels.TryGetValue(channel, out IAudioHandle value))
				{
					if (value == handle)
					{
						return true;
					}
					if (mode == AudioChannelMode.KeepExisting)
					{
						return false;
					}
					value.TryStop(allowFadeOut);
					if (!value.TryRelease())
					{
						return false;
					}
					if (_channels.TryUpdate(channel, handle, value))
					{
						return true;
					}
				}
				else if (_channels.TryAdd(channel, handle))
				{
					break;
				}
			}
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Removes a handle from every named channel it currently owns without stopping it.</para>
		///     <para xml:lang="zh-CN">从该句柄当前占用的所有命名通道中移除它，但不停止播放。</para>
		/// </summary>
		/// <param name="handle">
		///     <para xml:lang="en">The channel owner to remove.</para>
		///     <para xml:lang="zh-CN">要移除的通道占用者。</para>
		/// </param>
		public void ReleaseChannel(IAudioHandle handle)
		{
			foreach (KeyValuePair<string, IAudioHandle> channel in _channels)
			{
				if (channel.Value == handle)
				{
					_channels.TryRemove(channel.Key, out IAudioHandle _);
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">Adds a handle by reference identity to a tag group for later bulk stopping.</para>
		///     <para xml:lang="zh-CN">按引用标识将句柄添加到标签组，以便之后批量停止。</para>
		/// </summary>
		/// <param name="tag">
		///     <para xml:lang="en">The case-sensitive tag name.</para>
		///     <para xml:lang="zh-CN">区分大小写的标签名称。</para>
		/// </param>
		/// <param name="handle">
		///     <para xml:lang="en">The handle to add.</para>
		///     <para xml:lang="zh-CN">要添加的句柄。</para>
		/// </param>
		public void AttachTag(string tag, IAudioHandle handle)
		{
			_tags.GetOrAdd(tag, (string _) => new ConcurrentDictionary<IAudioHandle, byte>(ReferenceEqualityComparer.Instance)).TryAdd(handle, 0);
		}

		/// <summary>
		///     <para xml:lang="en">Removes a handle from all tracked channels and tag groups without stopping it.</para>
		///     <para xml:lang="zh-CN">从所有跟踪的通道和标签组中移除句柄，但不停止播放。</para>
		/// </summary>
		/// <param name="handle">
		///     <para xml:lang="en">The handle to detach.</para>
		///     <para xml:lang="zh-CN">要分离的句柄。</para>
		/// </param>
		public void Detach(IAudioHandle handle)
		{
			ReleaseChannel(handle);
			foreach (KeyValuePair<string, ConcurrentDictionary<IAudioHandle, byte>> tag in _tags)
			{
				tag.Value.TryRemove(handle, out var _);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to stop and release every handle in a tag group, retaining entries whose release
		///         fails.
		///     </para>
		///     <para xml:lang="zh-CN">尝试停止并释放标签组中的所有句柄，并保留释放失败的条目。</para>
		/// </summary>
		/// <param name="tag">
		///     <para xml:lang="en">The case-sensitive tag name.</para>
		///     <para xml:lang="zh-CN">区分大小写的标签名称。</para>
		/// </param>
		/// <param name="allowFadeOut">
		///     <para xml:lang="en">Whether stopped handles may fade out.</para>
		///     <para xml:lang="zh-CN">停止句柄时是否允许淡出。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when at least one handle was found and every release completed;
		///         otherwise <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">找到至少一个句柄且所有释放均已完成时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public bool StopTag(string tag, bool allowFadeOut = true)
		{
			if (!_tags.TryGetValue(tag, out ConcurrentDictionary<IAudioHandle, byte> value))
			{
				return false;
			}
			return StopHandles(value, allowFadeOut, allowEmpty: false);
		}

		internal bool TryClearTag(string tag, bool allowFadeOut)
		{
			if (_tags.TryGetValue(tag, out ConcurrentDictionary<IAudioHandle, byte> value))
			{
				return StopHandles(value, allowFadeOut, allowEmpty: true);
			}
			return true;
		}

		private static bool StopHandles(ConcurrentDictionary<IAudioHandle, byte> handles, bool allowFadeOut, bool allowEmpty)
		{
			bool flag = false;
			bool flag2 = true;
			IAudioHandle[] array = handles.Keys.ToArray();
			foreach (IAudioHandle audioHandle in array)
			{
				flag = true;
				audioHandle.TryStop(allowFadeOut);
				if (!audioHandle.TryRelease())
				{
					flag2 = false;
				}
				else
				{
					handles.TryRemove(audioHandle, out var _);
				}
			}
			if (flag2)
			{
				return flag | allowEmpty;
			}
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to stop and release the handle assigned to a named channel, removing it only when
		///         release succeeds.
		///     </para>
		///     <para xml:lang="zh-CN">尝试停止并释放分配到命名通道的句柄，并且仅在释放成功时移除它。</para>
		/// </summary>
		/// <param name="channel">
		///     <para xml:lang="en">The case-sensitive channel name.</para>
		///     <para xml:lang="zh-CN">区分大小写的通道名称。</para>
		/// </param>
		/// <param name="allowFadeOut">
		///     <para xml:lang="en">Whether the stopped handle may fade out.</para>
		///     <para xml:lang="zh-CN">停止句柄时是否允许淡出。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when an assigned handle was found and released; otherwise
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">找到并成功释放已分配句柄时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public bool StopChannel(string channel, bool allowFadeOut = true)
		{
			if (!_channels.TryGetValue(channel, out IAudioHandle value))
			{
				return false;
			}
			value.TryStop(allowFadeOut);
			if (!value.TryRelease())
			{
				return false;
			}
			_channels.TryRemove(new KeyValuePair<string, IAudioHandle>(channel, value));
			return true;
		}
	}
