	///         lifecycle boundaries.
	///     </para>
	///     <para xml:lang="zh-CN">按内置生命周期作用域或手动令牌跟踪音频句柄，并在对应的生命周期边界清理它们。</para>
	/// </summary>
	public sealed class AudioLifecycleRegistry : IDisposable
	{
		private readonly IDisposable _combatEndedSubscription;

		private readonly IDisposable _roomExitedSubscription;

		private readonly IDisposable _runEndedSubscription;

		private readonly ConcurrentDictionary<AudioLifecycleScope, ConcurrentDictionary<IAudioHandle, byte>> _scopeHandles = new ConcurrentDictionary<AudioLifecycleScope, ConcurrentDictionary<IAudioHandle, byte>>();

		private readonly ConcurrentDictionary<AudioScopeToken, ConcurrentDictionary<IAudioHandle, byte>> _tokenHandles = new ConcurrentDictionary<AudioScopeToken, ConcurrentDictionary<IAudioHandle, byte>>();

		/// <summary>
		///     <para xml:lang="en">Gets the shared lifecycle registry.</para>
		///     <para xml:lang="zh-CN">获取共享的生命周期注册表。</para>
		/// </summary>
		public static AudioLifecycleRegistry Shared { get; } = new AudioLifecycleRegistry();

		private AudioLifecycleRegistry()
		{
			_combatEndedSubscription = RitsuLibFramework.SubscribeLifecycle((Action<CombatEndedEvent>)delegate
			{
				StopScope(AudioLifecycleScope.Combat);
			}, true);
			_roomExitedSubscription = RitsuLibFramework.SubscribeLifecycle((Action<RoomExitedEvent>)delegate
			{
				StopScope(AudioLifecycleScope.Room);
			}, true);
			_runEndedSubscription = RitsuLibFramework.SubscribeLifecycle((Action<RunEndedEvent>)delegate
			{
				StopScope(AudioLifecycleScope.Run);
			}, true);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Disposes this registry's lifecycle subscriptions without stopping or detaching currently
		///         tracked handles.
		///     </para>
		///     <para xml:lang="zh-CN">释放此注册表的生命周期订阅，但不会停止或分离当前跟踪的句柄。</para>
		/// </summary>
		public void Dispose()
		{
			_combatEndedSubscription.Dispose();
			_roomExitedSubscription.Dispose();
			_runEndedSubscription.Dispose();
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Tracks a handle under an active manual token when present, or under the handle's built-in scope otherwise. A
		///         handle that races with token disposal is disposed immediately; if release fails, its built-in scope retains
		///         it for a later cleanup attempt.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         设置了活动的手动令牌时按该令牌跟踪句柄，否则按句柄的内置作用域跟踪。与令牌释放发生竞争的句柄会立即尝试释放；
		///         如果释放失败，则由其内置作用域保留，以便之后重试清理。
		///     </para>
		/// </summary>
		/// <param name="handle">
		///     <para xml:lang="en">The handle to track.</para>
		///     <para xml:lang="zh-CN">要跟踪的句柄。</para>
		/// </param>
		/// <param name="options">
		///     <para xml:lang="en">The playback options that may provide an active manual scope token.</para>
		///     <para xml:lang="zh-CN">可提供活动手动作用域令牌的播放选项。</para>
		/// </param>
		public void Attach(IAudioHandle handle, AudioPlaybackOptions? options)
		{
			TryAttach(handle, options);
		}

		internal bool TryAttach(IAudioHandle handle, AudioPlaybackOptions? options)
		{
			AudioScopeToken audioScopeToken = options?.ScopeToken;
			if (audioScopeToken == null)
			{
				TrackByScope(handle);
				return true;
			}
			if (audioScopeToken.IsClosing)
			{
				DisposeOrRetainByScope(handle);
				return false;
			}
			ConcurrentDictionary<IAudioHandle, byte> orAdd = _tokenHandles.GetOrAdd(audioScopeToken, (AudioScopeToken _) => new ConcurrentDictionary<IAudioHandle, byte>());
			orAdd.TryAdd(handle, 0);
			if (audioScopeToken.IsClosing && orAdd.TryRemove(handle, out var _))
			{
				DisposeOrRetainByScope(handle);
				return false;
			}
			return true;
		}

		/// <summary>
		///     <para xml:lang="en">Removes a handle from every tracked scope and token without stopping it.</para>
		///     <para xml:lang="zh-CN">从所有跟踪的作用域和令牌中移除句柄，但不停止播放。</para>
		/// </summary>
		/// <param name="handle">
		///     <para xml:lang="en">The handle to detach.</para>
		///     <para xml:lang="zh-CN">要分离的句柄。</para>
		/// </param>
		public void Detach(IAudioHandle handle)
		{
			byte value;
			foreach (KeyValuePair<AudioLifecycleScope, ConcurrentDictionary<IAudioHandle, byte>> scopeHandle in _scopeHandles)
			{
				scopeHandle.Value.TryRemove(handle, out value);
			}
			foreach (KeyValuePair<AudioScopeToken, ConcurrentDictionary<IAudioHandle, byte>> tokenHandle in _tokenHandles)
			{
				tokenHandle.Value.TryRemove(handle, out value);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to stop and release every handle tracked under a built-in scope, retaining entries
		///         whose release fails.
		///     </para>
		///     <para xml:lang="zh-CN">尝试停止并释放内置作用域下跟踪的所有句柄，并保留释放失败的条目。</para>
		/// </summary>
		/// <param name="scope">
		///     <para xml:lang="en">The built-in lifecycle scope to clean up.</para>
		///     <para xml:lang="zh-CN">要清理的内置生命周期作用域。</para>
		/// </param>
		/// <param name="allowFadeOut">
		///     <para xml:lang="en">Whether stopped event handles may fade out.</para>
		///     <para xml:lang="zh-CN">停止事件句柄时是否允许淡出。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when at least one handle was found and every release completed;
		///         otherwise <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">找到至少一个句柄且所有释放均已完成时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public bool StopScope(AudioLifecycleScope scope, bool allowFadeOut = true)
		{
			if (!_scopeHandles.TryGetValue(scope, out ConcurrentDictionary<IAudioHandle, byte> value))
			{
				return false;
			}
			bool flag = false;
			bool flag2 = true;
			IAudioHandle[] array = value.Keys.ToArray();
			foreach (IAudioHandle audioHandle in array)
			{
				flag = true;
				audioHandle.TryStop(allowFadeOut);
				if (!audioHandle.TryRelease())
				{
					flag2 = false;
				}
				else
				{
					value.TryRemove(audioHandle, out var _);
				}
			}
			return flag & flag2;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to stop and release every handle tracked under a manual token, retaining entries whose
		///         release fails.
		///     </para>
		///     <para xml:lang="zh-CN">尝试停止并释放手动令牌下跟踪的所有句柄，并保留释放失败的条目。</para>
		/// </summary>
		/// <param name="token">
		///     <para xml:lang="en">The manual scope token to clean up.</para>
		///     <para xml:lang="zh-CN">要清理的手动作用域令牌。</para>
		/// </param>
		/// <param name="allowFadeOut">
		///     <para xml:lang="en">Whether stopped event handles may fade out.</para>
		///     <para xml:lang="zh-CN">停止事件句柄时是否允许淡出。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when at least one handle was found and every release completed;
		///         otherwise <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">找到至少一个句柄且所有释放均已完成时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public bool StopScope(AudioScopeToken token, bool allowFadeOut = true)
		{
			if (!_tokenHandles.TryGetValue(token, out ConcurrentDictionary<IAudioHandle, byte> value))
			{
				return false;
			}
			bool flag = false;
			bool flag2 = true;
			IAudioHandle[] array = value.Keys.ToArray();
			foreach (IAudioHandle audioHandle in array)
			{
				flag = true;
				audioHandle.TryStop(allowFadeOut);
				if (!audioHandle.TryRelease())
				{
					flag2 = false;
				}
				else
				{
					value.TryRemove(audioHandle, out var _);
				}
			}
			return flag & flag2;
		}

		internal bool TryDisposeScope(AudioScopeToken token, bool allowFadeOut = true)
		{
			if (!_tokenHandles.TryGetValue(token, out ConcurrentDictionary<IAudioHandle, byte> value))
			{
				return true;
			}
			bool flag = true;
			IAudioHandle[] array = value.Keys.ToArray();
			foreach (IAudioHandle audioHandle in array)
			{
				audioHandle.TryStop(allowFadeOut);
				if (!audioHandle.TryRelease())
				{
					flag = false;
				}
				else
				{
					value.TryRemove(audioHandle, out var _);
				}
			}
			if (!flag || !value.IsEmpty)
			{
				return false;
			}
			_tokenHandles.TryRemove(new KeyValuePair<AudioScopeToken, ConcurrentDictionary<IAudioHandle, byte>>(token, value));
			return true;
		}

		private void DisposeOrRetainByScope(IAudioHandle handle)
		{
			handle.Dispose();
			if (!handle.IsReleased)
			{
				TrackByScope(handle);
			}
		}

		private void TrackByScope(IAudioHandle handle)
		{
			_scopeHandles.GetOrAdd(handle.Scope, (AudioLifecycleScope _) => new ConcurrentDictionary<IAudioHandle, byte>()).TryAdd(handle, 0);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Identifies a built-in lifecycle bucket used to group audio handles for cleanup.</para>
	///     <para xml:lang="zh-CN">标识用于将音频句柄分组清理的内置生命周期作用域。</para>
	/// </summary>
	public enum AudioLifecycleScope
	{
		/// <summary>
		///     <para xml:lang="en">No lifecycle event cleans up this scope automatically; callers manage it explicitly.</para>
		///     <para xml:lang="zh-CN">没有生命周期事件会自动清理此作用域；由调用方显式管理。</para>
		/// </summary>
		Manual,
		/// <summary>
		///     <para xml:lang="en">Cleaned up when combat ends.</para>
		///     <para xml:lang="zh-CN">在战斗结束时清理。</para>
		/// </summary>
		Combat,
		/// <summary>
		///     <para xml:lang="en">Cleaned up when the current room is exited.</para>
		///     <para xml:lang="zh-CN">在离开当前房间时清理。</para>
		/// </summary>
		Room,
		/// <summary>
		///     <para xml:lang="en">Cleaned up when the run ends.</para>
		///     <para xml:lang="zh-CN">在跑局结束时清理。</para>
		/// </summary>
		Run,
		/// <summary>
		///     <para xml:lang="en">Reserved for screen-scoped flows and currently requires explicit cleanup.</para>
		///     <para xml:lang="zh-CN">保留给界面作用域流程，目前需要显式清理。</para>
		/// </summary>
		Screen
	}
	/// <summary>
	///     <para xml:lang="en">A typed audio handle for loop-oriented playback with restart support.</para>
	///     <para xml:lang="zh-CN">用于循环型播放并支持重新启动的类型化音频句柄。</para>
	/// </summary>
	/// <param name="source">
	///     <para xml:lang="en">The logical audio source represented by the instance.</para>
	///     <para xml:lang="zh-CN">该实例所代表的逻辑音频源。</para>
	/// </param>
	/// <param name="scope">
	///     <para xml:lang="en">The lifecycle scope associated with the handle.</para>
	///     <para xml:lang="zh-CN">与句柄关联的生命周期作用域。</para>
	/// </param>
	/// <param name="rawInstance">
	///     <para xml:lang="en">The underlying FMOD Godot object, or null to create an invalid handle.</para>
	///     <para xml:lang="zh-CN">底层 FMOD Godot 对象；为 <see langword="null" /> 时创建无效句柄。</para>
	/// </param>
	public sealed class AudioLoopHandle : AudioHandleBase
	{
		/// <summary>
		///     <para xml:lang="en">A typed audio handle for loop-oriented playback with restart support.</para>
		///     <para xml:lang="zh-CN">用于循环型播放并支持重新启动的类型化音频句柄。</para>
		/// </summary>
		/// <param name="source">
		///     <para xml:lang="en">The logical audio source represented by the instance.</para>
		///     <para xml:lang="zh-CN">该实例所代表的逻辑音频源。</para>
		/// </param>
		/// <param name="scope">
		///     <para xml:lang="en">The lifecycle scope associated with the handle.</para>
		///     <para xml:lang="zh-CN">与句柄关联的生命周期作用域。</para>
		/// </param>
		/// <param name="rawInstance">
		///     <para xml:lang="en">The underlying FMOD Godot object, or null to create an invalid handle.</para>
		///     <para xml:lang="zh-CN">底层 FMOD Godot 对象；为 <see langword="null" /> 时创建无效句柄。</para>
		/// </param>
		public AudioLoopHandle(AudioSource source, AudioLifecycleScope scope, GodotObject? rawInstance)
			: base(source, scope, rawInstance)
		{
		}

		/// <summary>
		///     <para xml:lang="en">Attempts to restart playback by stopping the current instance and then starting it again.</para>
		///     <para xml:lang="zh-CN">尝试先停止当前实例，再重新启动播放。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> when both stop and start complete; otherwise <see langword="false" />.</para>
		///     <para xml:lang="zh-CN">停止和启动均执行完成时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public bool TryRestart()
		{
			if (TryStop())
			{
				return TryPlay();
			}
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">A typed handle for long-lived music playback with transactional replacement support.</para>
	///     <para xml:lang="zh-CN">用于长期音乐播放并支持事务式替换的类型化句柄。</para>
	/// </summary>
	/// <param name="source">
	///     <para xml:lang="en">The logical audio source represented by the instance.</para>
	///     <para xml:lang="zh-CN">该实例所代表的逻辑音频源。</para>
	/// </param>
	/// <param name="scope">
	///     <para xml:lang="en">The lifecycle scope associated with the handle.</para>
	///     <para xml:lang="zh-CN">与句柄关联的生命周期作用域。</para>
	/// </param>
	/// <param name="rawInstance">
	///     <para xml:lang="en">The underlying FMOD Godot object, or null to create an invalid handle.</para>
	///     <para xml:lang="zh-CN">底层 FMOD Godot 对象；为 <see langword="null" /> 时创建无效句柄。</para>
	/// </param>
	public sealed class AudioMusicHandle : AudioHandleBase
	{
		/// <summary>
		///     <para xml:lang="en">A typed handle for long-lived music playback with transactional replacement support.</para>
		///     <para xml:lang="zh-CN">用于长期音乐播放并支持事务式替换的类型化句柄。</para>
		/// </summary>
		/// <param name="source">
		///     <para xml:lang="en">The logical audio source represented by the instance.</para>
		///     <para xml:lang="zh-CN">该实例所代表的逻辑音频源。</para>
		/// </param>
		/// <param name="scope">
		///     <para xml:lang="en">The lifecycle scope associated with the handle.</para>
		///     <para xml:lang="zh-CN">与句柄关联的生命周期作用域。</para>
		/// </param>
		/// <param name="rawInstance">
		///     <para xml:lang="en">The underlying FMOD Godot object, or null to create an invalid handle.</para>
		///     <para xml:lang="zh-CN">底层 FMOD Godot 对象；为 <see langword="null" /> 时创建无效句柄。</para>
		/// </param>
		public AudioMusicHandle(AudioSource source, AudioLifecycleScope scope, GodotObject? rawInstance)
			: base(source, scope, rawInstance)
		{
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Starts replacement music and disposes this handle, discarding the returned replacement-handle
		///         reference.
		///     </para>
		///     <para xml:lang="zh-CN">启动替代音乐并释放此句柄，同时丢弃返回的替代句柄引用。</para>
		/// </summary>
		/// <param name="nextSource">
		///     <para xml:lang="en">The music source to start as the replacement.</para>
		///     <para xml:lang="zh-CN">要作为替代项启动的音乐源。</para>
		/// </param>
		/// <param name="options">
		///     <para xml:lang="en">The replacement playback options, or null to use defaults with this handle's lifecycle scope.</para>
		///     <para xml:lang="zh-CN">替代播放选项；为 <see langword="null" /> 时使用带当前句柄生命周期作用域的默认值。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when replacement starts and this handle releases successfully;
		///         otherwise <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">替代音乐成功启动且此句柄成功释放时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public bool TrySwitchTo(AudioSource nextSource, AudioPlaybackOptions? options = null)
		{
			AudioMusicHandle replacement;
			return TrySwitchTo(nextSource, out replacement, options);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Starts replacement music and returns its handle only after this handle releases successfully. If release
		///         fails, the replacement is disposed and the switch reports failure.
		///     </para>
		///     <para xml:lang="zh-CN">启动替代音乐；仅当此句柄成功释放后才返回替代句柄。释放失败时会释放替代项并报告切换失败。</para>
		/// </summary>
		/// <param name="nextSource">
		///     <para xml:lang="en">The music source to start as the replacement.</para>
		///     <para xml:lang="zh-CN">要作为替代项启动的音乐源。</para>
		/// </param>
		/// <param name="replacement">
		///     <para xml:lang="en">Receives the replacement handle on success; otherwise null.</para>
		///     <para xml:lang="zh-CN">成功时接收替代句柄；否则为 <see langword="null" />。</para>
		/// </param>
		/// <param name="options">
		///     <para xml:lang="en">The replacement playback options, or null to use defaults with this handle's lifecycle scope.</para>
		///     <para xml:lang="zh-CN">替代播放选项；为 <see langword="null" /> 时使用带当前句柄生命周期作用域的默认值。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when replacement starts and this handle releases successfully;
		///         otherwise <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">替代音乐成功启动且此句柄成功释放时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public bool TrySwitchTo(AudioSource nextSource, out AudioMusicHandle? replacement, AudioPlaybackOptions? options = null)
		{
			AudioMusicHandle audioMusicHandle = GameFmod.Playback.PlayMusic(nextSource, options ?? new AudioPlaybackOptions
			{
				Scope = base.Scope
			});
			if (audioMusicHandle == null)
			{
				replacement = null;
				return false;
			}
			Dispose();
			if (base.IsReleased)
			{
				replacement = audioMusicHandle;
				return true;
			}
			audioMusicHandle.Dispose();
			replacement = null;
			return false;
		}
	}
	/// <summary>
	///     <para xml:lang="en">An immutable snapshot of named numeric parameters for high-level playback requests.</para>
	///     <para xml:lang="zh-CN">用于高级播放请求的命名数值参数不可变快照。</para>
	/// </summary>
	public sealed class AudioParameterSet
	{
		/// <summary>
		///     <para xml:lang="en">Gets the shared empty parameter set.</para>
		///     <para xml:lang="zh-CN">获取共享的空参数集。</para>
		/// </summary>
		public static AudioParameterSet Empty { get; } = new AudioParameterSet(new ReadOnlyDictionary<string, float>(new Dictionary<string, float>()));

		/// <summary>
		///     <para xml:lang="en">Gets the read-only parameter snapshot.</para>
		///     <para xml:lang="zh-CN">获取只读参数快照。</para>
		/// </summary>
		public IReadOnlyDictionary<string, float> Values { get; }

		private AudioParameterSet(IReadOnlyDictionary<string, float> values)
		{
			Values = values;
		}

		/// <summary>
		///     <para xml:lang="en">Copies a parameter dictionary into an immutable set.</para>
		///     <para xml:lang="zh-CN">将参数字典复制为不可变参数集。</para>
		/// </summary>
		/// <param name="values">
		///     <para xml:lang="en">The values to copy; null or empty returns <see cref="P:STS2RitsuLib.Audio.AudioParameterSet.Empty" />.</para>
		///     <para xml:lang="zh-CN">要复制的值；为 <see langword="null" /> 或空时返回 <see cref="P:STS2RitsuLib.Audio.AudioParameterSet.Empty" />。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The immutable parameter snapshot.</para>
		///     <para xml:lang="zh-CN">不可变参数快照。</para>
		/// </returns>
		public static AudioParameterSet From(IReadOnlyDictionary<string, float>? values)
		{
			if (values == null || values.Count == 0)
			{
				return Empty;
			}
			return new AudioParameterSet(new ReadOnlyDictionary<string, float>(new Dictionary<string, float>(values)));
		}

		/// <summary>
		///     <para xml:lang="en">Returns a copy with one named parameter added or replaced.</para>
		///     <para xml:lang="zh-CN">返回添加或替换一个命名参数后的副本。</para>
		/// </summary>
		/// <param name="name">
		///     <para xml:lang="en">The case-sensitive parameter name.</para>
		///     <para xml:lang="zh-CN">区分大小写的参数名称。</para>
		/// </param>
		/// <param name="value">
		///     <para xml:lang="en">The parameter value.</para>
		///     <para xml:lang="zh-CN">参数值。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A new immutable parameter set.</para>
		///     <para xml:lang="zh-CN">新的不可变参数集。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">Thrown when <paramref name="name" /> is null.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="name" /> 为 <see langword="null" /> 时抛出。</para>
		/// </exception>
		public AudioParameterSet With(string name, float value)
		{
			return new AudioParameterSet(new ReadOnlyDictionary<string, float>(new Dictionary<string, float>(Values) { [name] = value }));
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Configures initial backend values, lifecycle ownership, throttling, and higher-level routing
	///         for a playback request.
	///     </para>
	///     <para xml:lang="zh-CN">配置播放请求的初始后端值、生命周期归属、节流和高级路由。</para>
	/// </summary>
	public sealed class AudioPlaybackOptions
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes the numeric FMOD parameters applied when the selected playback path
		///         supports them.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化所选播放路径支持时应用的数值型 FMOD 参数。</para>
		/// </summary>
		public AudioParameterSet? Parameters { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the unclamped linear volume passed to the backend.</para>
		///     <para xml:lang="zh-CN">获取或初始化传递给后端的未钳制线性音量。</para>
		/// </summary>
		public float Volume { get; init; } = 1f;

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the unclamped pitch multiplier applied when supported.</para>
		///     <para xml:lang="zh-CN">获取或初始化后端支持时应用的未钳制音高倍率。</para>
		/// </summary>
		public float Pitch { get; init; } = 1f;

		/// <summary>
		///     <para xml:lang="en">Gets or initializes whether a newly created controllable handle starts immediately.</para>
		///     <para xml:lang="zh-CN">获取或初始化新创建的可控制句柄是否立即开始播放。</para>
		/// </summary>
		public bool AutoPlay { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes whether a newly created controllable handle requests a paused initial
		///         state.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化新创建的可控制句柄是否请求以暂停状态开始。</para>
		/// </summary>
		public bool StartPaused { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets or initializes whether disposal and higher-level stop flows may use FMOD fade-out.</para>
		///     <para xml:lang="zh-CN">获取或初始化释放及高级停止流程是否可使用 FMOD 淡出。</para>
		/// </summary>
		public bool AllowFadeOutOnStop { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes the playback cooldown in milliseconds; zero or a negative value disables
		///         throttling.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化播放冷却时间（毫秒）；零或负值会禁用节流。</para>
		/// </summary>
		public int CooldownMs { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the built-in lifecycle scope used when <see cref="P:STS2RitsuLib.Audio.AudioPlaybackOptions.ScopeToken" /> is absent.</para>
		///     <para xml:lang="zh-CN">获取或初始化未设置 <see cref="P:STS2RitsuLib.Audio.AudioPlaybackOptions.ScopeToken" /> 时使用的内置生命周期作用域。</para>
		/// </summary>
		public AudioLifecycleScope Scope { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes the active manual token that overrides <see cref="P:STS2RitsuLib.Audio.AudioPlaybackOptions.Scope" /> for handle
		///         grouping and cleanup; closing or disposed tokens reject playback.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化用于覆盖 <see cref="P:STS2RitsuLib.Audio.AudioPlaybackOptions.Scope" /> 并对句柄进行分组清理的活动手动令牌；正在释放或已释放的令牌会使播放请求失败。</para>
		/// </summary>
		public AudioScopeToken? ScopeToken { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes whether Studio event-path one-shots use the game's native audio-manager
		///         route.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化 Studio 事件路径单次播放是否使用游戏原生音频管理器路径。</para>
		/// </summary>
		public bool UseVanillaRouting { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes whether Studio loop playback applies the game's <c>loop = 0</c> parameter
		///         convention.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化 Studio 循环播放是否应用游戏的 <c>loop = 0</c> 参数约定。</para>
		/// </summary>
		public bool UsesLoopParameter { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes the optional cooldown-group key; the source representation is used when
		///         absent.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化可选的冷却分组键；未设置时使用音频源的字符串表示。</para>
		/// </summary>
		public string? DebugName { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the optional named-channel and tag-group routing rules.</para>
		///     <para xml:lang="zh-CN">获取或初始化可选的命名通道与标签组路由规则。</para>
		/// </summary>
		public AudioRoutingOptions? Routing { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the configured read-only parameter dictionary, or the shared empty dictionary when none is
		///         configured.
		///     </para>
		///     <para xml:lang="zh-CN">获取已配置的只读参数字典；未配置时返回共享空字典。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">The parameter dictionary used by playback dispatch.</para>
		///     <para xml:lang="zh-CN">播放分派使用的参数字典。</para>
		/// </returns>
		public IReadOnlyDictionary<string, float> GetParameters()
		{
			return Parameters?.Values ?? FmodParameterMap.Empty();
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Describes the status, optional controllable handle, and diagnostic message produced by a
	///         playback request.
	///     </para>
	///     <para xml:lang="zh-CN">描述播放请求产生的状态、可选可控制句柄和诊断消息。</para>
	/// </summary>
	public sealed class AudioPlayResult
	{
		/// <summary>
		///     <para xml:lang="en">Gets the playback outcome category.</para>
		///     <para xml:lang="zh-CN">获取播放结果类别。</para>
		/// </summary>
		public AudioPlayStatus Status { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets the controllable handle created for the request, or null for handleless playback and
		///         failures.
		///     </para>
		///     <para xml:lang="zh-CN">获取为请求创建的可控制句柄；无句柄播放和失败结果中为 <see langword="null" />。</para>
		/// </summary>
		public IAudioHandle? Handle { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the optional diagnostic message.</para>
		///     <para xml:lang="zh-CN">获取可选诊断消息。</para>
		/// </summary>
		public string? Message { get; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets whether <see cref="P:STS2RitsuLib.Audio.AudioPlayResult.Status" /> is <see cref="F:STS2RitsuLib.Audio.AudioPlayStatus.Started" />, independently of
		///         whether a handle exists.
		///     </para>
		///     <para xml:lang="zh-CN">获取 <see cref="P:STS2RitsuLib.Audio.AudioPlayResult.Status" /> 是否为 <see cref="F:STS2RitsuLib.Audio.AudioPlayStatus.Started" />，与是否存在句柄无关。</para>
		/// </summary>
		public bool Succeeded => Status == AudioPlayStatus.Started;

		private AudioPlayResult(AudioPlayStatus status, IAudioHandle? handle, string? message)
		{
			Status = status;
			Handle = handle;
			Message = message;
		}

		/// <summary>
		///     <para xml:lang="en">Creates a successful result for controllable or handleless playback.</para>
		///     <para xml:lang="zh-CN">为可控制或无句柄播放创建成功结果。</para>
		/// </summary>
		/// <param name="handle">
		///     <para xml:lang="en">The optional controllable handle.</para>
		///     <para xml:lang="zh-CN">可选的可控制句柄。</para>
		/// </param>
		/// <param name="message">
		///     <para xml:lang="en">The optional diagnostic message.</para>
		///     <para xml:lang="zh-CN">可选诊断消息。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A result whose status is <see cref="F:STS2RitsuLib.Audio.AudioPlayStatus.Started" />.</para>
		///     <para xml:lang="zh-CN">状态为 <see cref="F:STS2RitsuLib.Audio.AudioPlayStatus.Started" /> 的结果。</para>
		/// </returns>
		public static AudioPlayResult Started(IAudioHandle? handle = null, string? message = null)
		{
			return new AudioPlayResult(AudioPlayStatus.Started, handle, message);
		}

		/// <summary>
		///     <para xml:lang="en">Creates a handleless failed result.</para>
		///     <para xml:lang="zh-CN">创建不带句柄的失败结果。</para>
		/// </summary>
		/// <param name="status">
		///     <para xml:lang="en">The non-success outcome category.</para>
		///     <para xml:lang="zh-CN">非成功结果类别。</para>
		/// </param>
		/// <param name="message">
		///     <para xml:lang="en">The optional diagnostic message.</para>
		///     <para xml:lang="zh-CN">可选诊断消息。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A failed result with no handle.</para>
		///     <para xml:lang="zh-CN">不带句柄的失败结果。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentOutOfRangeException">
		///     <para xml:lang="en">Thrown when <paramref name="status" /> is <see cref="F:STS2RitsuLib.Audio.AudioPlayStatus.Started" />.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="status" /> 为 <see cref="F:STS2RitsuLib.Audio.AudioPlayStatus.Started" /> 时抛出。</para>
		/// </exception>
		public static AudioPlayResult Fail(AudioPlayStatus status, string? message = null)
		{
			if (status == AudioPlayStatus.Started)
			{
				throw new ArgumentOutOfRangeException("status", status, "A failed result cannot use Started.");
			}
			return new AudioPlayResult(status, null, message);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Identifies the outcome category of a high-level audio playback request.</para>
	///     <para xml:lang="zh-CN">标识高级音频播放请求的结果类别。</para>
	/// </summary>
	public enum AudioPlayStatus
	{
		/// <summary>
		///     <para xml:lang="en">Playback started successfully.</para>
		///     <para xml:lang="zh-CN">播放已成功启动。</para>
		/// </summary>
		Started,
		/// <summary>
		///     <para xml:lang="en">The supplied source type is invalid for the requested operation.</para>
		///     <para xml:lang="zh-CN">提供的音频源类型不适用于所请求的操作。</para>
		/// </summary>
		InvalidSource,
		/// <summary>
		///     <para xml:lang="en">The FMOD server was unavailable.</para>
		///     <para xml:lang="zh-CN">FMOD 服务器不可用。</para>
		/// </summary>
		MissingServer,
		/// <summary>
		///     <para xml:lang="en">The game's native audio manager was unavailable.</para>
		///     <para xml:lang="zh-CN">游戏原生音频管理器不可用。</para>
		/// </summary>
		MissingManager,
		/// <summary>
		///     <para xml:lang="en">A controllable backend playback instance could not be created.</para>
		///     <para xml:lang="zh-CN">无法创建可控制的后端播放实例。</para>
		/// </summary>
		MissingInstance,
		/// <summary>
		///     <para xml:lang="en">Playback was skipped because its cooldown group is still throttled.</para>
		///     <para xml:lang="zh-CN">播放所属冷却分组仍处于节流期，因此已跳过播放。</para>
		/// </summary>
		SkippedCooldown,
		/// <summary>
		///     <para xml:lang="en">Playback failed for another reason.</para>
		///     <para xml:lang="zh-CN">播放因其他原因失败。</para>
		/// </summary>
		Failed,
		/// <summary>
		///     <para xml:lang="en">The requested operation does not support the supplied source type.</para>
		///     <para xml:lang="zh-CN">所请求的操作不支持提供的音频源类型。</para>
		/// </summary>
		NotSupported
	}
	/// <summary>
	///     <para xml:lang="en">Configures optional named-channel ownership and tag-group membership for a playback handle.</para>
	///     <para xml:lang="zh-CN">配置播放句柄可选的命名通道归属和标签组成员关系。</para>
	/// </summary>
	public sealed class AudioRoutingOptions
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes the optional case-sensitive channel name; null, empty, or whitespace
		///         disables channel routing.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化可选且区分大小写的通道名称；为 <see langword="null" />、空或空白时禁用通道路由。</para>
		/// </summary>
		public string? Channel { get; init; }

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes the optional case-sensitive tag name; null, empty, or whitespace disables
		///         tag routing.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化可选且区分大小写的标签名称；为 <see langword="null" />、空或空白时禁用标签路由。</para>
		/// </summary>
		public string? Tag { get; init; }

		/// <summary>
		///     <para xml:lang="en">Gets or initializes the collision policy used when <see cref="P:STS2RitsuLib.Audio.AudioRoutingOptions.Channel" /> already has an owner.</para>
		///     <para xml:lang="zh-CN">获取或初始化 <see cref="P:STS2RitsuLib.Audio.AudioRoutingOptions.Channel" /> 已有占用者时使用的冲突策略。</para>
		/// </summary>
		public AudioChannelMode ChannelMode { get; init; } = AudioChannelMode.ReplaceExisting;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes whether channel and tag-group replacement cleanup may fade out previous
		///         handles.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化清理被通道或标签组替换的旧句柄时是否允许淡出。</para>
		/// </summary>
		public bool AllowFadeOutOnReplace { get; init; } = true;

		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes whether existing handles in <see cref="P:STS2RitsuLib.Audio.AudioRoutingOptions.Tag" /> must all release before the new handle
		///         is attached. Incomplete cleanup causes routing to fail.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         获取或初始化在附加新句柄前是否必须释放 <see cref="P:STS2RitsuLib.Audio.AudioRoutingOptions.Tag" /> 中的所有现有句柄；清理未完成会导致路由失败。
		///     </para>
		/// </summary>
		public bool ReplaceTaggedGroup { get; init; }
	}
	/// <summary>
	///     <para xml:lang="en">A caller-owned identity token that groups audio handles for explicit bulk cleanup.</para>
	///     <para xml:lang="zh-CN">由调用方持有、用于将音频句柄分组并显式批量清理的标识令牌。</para>
	/// </summary>
	public sealed class AudioScopeToken : IDisposable
	{
		private int _disposeState;

		/// <summary>
		///     <para xml:lang="en">Gets the caller-provided display name.</para>
		///     <para xml:lang="zh-CN">获取调用方提供的显示名称。</para>
		/// </summary>
		public string Name { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the lifecycle scope recorded on handles attached through this token.</para>
		///     <para xml:lang="zh-CN">获取通过此令牌附加的句柄所记录的生命周期作用域。</para>
		/// </summary>
		public AudioLifecycleScope Scope { get; }

		/// <summary>
		///     <para xml:lang="en">Gets whether disposal completed after every tracked handle released successfully.</para>
		///     <para xml:lang="zh-CN">获取是否已在所有跟踪句柄均成功释放后完成令牌释放。</para>
		/// </summary>
		public bool IsDisposed => Volatile.Read(in _disposeState) == 2;

		internal bool IsClosing => Volatile.Read(in _disposeState) != 0;

		internal AudioScopeToken(string name, AudioLifecycleScope scope)
		{
			Name = name;
			Scope = scope;
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to stop and release all attached handles, marking the token disposed only after
		///         complete cleanup; failed cleanup can be retried.
		///     </para>
		///     <para xml:lang="zh-CN">尝试停止并释放所有附加句柄；仅在清理全部完成后将令牌标记为已释放，失败的清理可再次尝试。</para>
		/// </summary>
		public void Dispose()
		{
			if (Interlocked.CompareExchange(ref _disposeState, 1, 0) == 0)
			{
				if (AudioLifecycleRegistry.Shared.TryDisposeScope(this))
				{
					Volatile.Write(ref _disposeState, 2);
				}
				else
				{
					Volatile.Write(ref _disposeState, 0);
				}
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Attempts to stop and release all handles currently attached to this token without changing its
		///         disposed state.
		///     </para>
		///     <para xml:lang="zh-CN">尝试停止并释放当前附加到此令牌的所有句柄，但不更改令牌的释放状态。</para>
		/// </summary>
		/// <param name="allowFadeOut">
		///     <para xml:lang="en">Whether stopped event handles may fade out.</para>
		///     <para xml:lang="zh-CN">停止事件句柄时是否允许淡出。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when at least one handle was found and every release completed;
		///         otherwise <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">找到至少一个句柄且所有释放均已完成时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public bool StopAll(bool allowFadeOut = true)
		{
			return AudioLifecycleRegistry.Shared.StopScope(this, allowFadeOut);
		}
	}
	/// <summary>
	///     <para xml:lang="en">A typed audio handle for an active FMOD Studio snapshot instance.</para>
	///     <para xml:lang="zh-CN">用于活动 FMOD Studio 快照实例的类型化音频句柄。</para>
	/// </summary>
	/// <param name="source">
	///     <para xml:lang="en">The logical snapshot source represented by the instance.</para>
	///     <para xml:lang="zh-CN">该实例所代表的逻辑快照源。</para>
	/// </param>
	/// <param name="scope">
	///     <para xml:lang="en">The lifecycle scope associated with the handle.</para>
	///     <para xml:lang="zh-CN">与句柄关联的生命周期作用域。</para>
	/// </param>
	/// <param name="rawInstance">
	///     <para xml:lang="en">The underlying FMOD Godot object, or null to create an invalid handle.</para>
	///     <para xml:lang="zh-CN">底层 FMOD Godot 对象；为 <see langword="null" /> 时创建无效句柄。</para>
	/// </param>
	public sealed class AudioSnapshotHandle : AudioHandleBase
	{
		/// <summary>
		///     <para xml:lang="en">A typed audio handle for an active FMOD Studio snapshot instance.</para>
		///     <para xml:lang="zh-CN">用于活动 FMOD Studio 快照实例的类型化音频句柄。</para>
		/// </summary>
		/// <param name="source">
		///     <para xml:lang="en">The logical snapshot source represented by the instance.</para>
		///     <para xml:lang="zh-CN">该实例所代表的逻辑快照源。</para>
		/// </param>
		/// <param name="scope">
		///     <para xml:lang="en">The lifecycle scope associated with the handle.</para>
		///     <para xml:lang="zh-CN">与句柄关联的生命周期作用域。</para>
		/// </param>
		/// <param name="rawInstance">
		///     <para xml:lang="en">The underlying FMOD Godot object, or null to create an invalid handle.</para>
		///     <para xml:lang="zh-CN">底层 FMOD Godot 对象；为 <see langword="null" /> 时创建无效句柄。</para>
		/// </param>
		public AudioSnapshotHandle(AudioSource source, AudioLifecycleScope scope, GodotObject? rawInstance)
			: base(source, scope, rawInstance)
		{
		}
	}
	/// <summary>
	///     <para xml:lang="en">Base record for the source descriptors dispatched by the high-level playback API.</para>
	///     <para xml:lang="zh-CN">高级播放 API 所分派音频源描述符的基础记录类型。</para>
	/// </summary>
	public abstract record AudioSource
	{
