	/// <summary>
	///     <para xml:lang="en">Provides guarded entry points for refreshing the game's native run-music controller.</para>
	///     <para xml:lang="zh-CN">提供带状态检查的游戏原生跑局音乐控制器刷新入口。</para>
	/// </summary>
	public static class AudioVanillaBridge
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Requests native updates for act music selection, room-progress track state, and ambience while
		///         a run is active.
		///     </para>
		///     <para xml:lang="zh-CN">跑局进行中时，请求原生控制器更新章节音乐选择、房间进度曲目状态和环境音。</para>
		/// </summary>
		public static void RefreshRunMusic()
		{
			NRunMusicController instance = NRunMusicController.Instance;
			if (instance != null && RunManager.Instance.IsInProgress)
			{
				instance.UpdateMusic();
				instance.UpdateTrack();
				instance.UpdateAmbience();
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Requests native updates for room-progress track state and ambience without reevaluating act
		///         music selection.
		///     </para>
		///     <para xml:lang="zh-CN">请求原生控制器更新房间进度曲目状态和环境音，但不重新评估章节音乐选择。</para>
		/// </summary>
		public static void RefreshTrackAndAmbience()
		{
			NRunMusicController instance = NRunMusicController.Instance;
			if (instance != null && RunManager.Instance.IsInProgress)
			{
				instance.UpdateTrack();
				instance.UpdateAmbience();
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         A lightweight value wrapper for an FMOD Studio event or snapshot path such as
	///         <c>event:/sfx/block_gain</c>.
	///     </para>
	///     <para xml:lang="zh-CN">FMOD Studio 事件或快照路径的轻量值包装，例如 <c>event:/sfx/block_gain</c>。</para>
	/// </summary>
	/// <param name="Value">
	///     <para xml:lang="en">The raw FMOD Studio path; a default value may contain null at runtime.</para>
	///     <para xml:lang="zh-CN">原始 FMOD Studio 路径；默认值在运行时可能包含 <see langword="null" />。</para>
	/// </param>
	public readonly record struct FmodEventPath(string Value)
	{
		/// <summary>
		///     <para xml:lang="en">Gets whether <see cref="P:STS2RitsuLib.Audio.FmodEventPath.Value" /> is null or empty; whitespace alone is not considered empty.</para>
		///     <para xml:lang="zh-CN">获取 <see cref="P:STS2RitsuLib.Audio.FmodEventPath.Value" /> 是否为 <see langword="null" /> 或空；仅含空白不视为空。</para>
		/// </summary>
		public bool IsEmpty => string.IsNullOrEmpty(Value);

		/// <summary>
		///     <para xml:lang="en">Converts a wrapped path to its raw value, using an empty string for a default null value.</para>
		///     <para xml:lang="zh-CN">将包装路径转换为其原始值；默认值中的 <see langword="null" /> 会转换为空字符串。</para>
		/// </summary>
		/// <param name="path">
		///     <para xml:lang="en">The wrapped path.</para>
		///     <para xml:lang="zh-CN">已包装的路径。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The raw path, or an empty string when the stored value is null.</para>
		///     <para xml:lang="zh-CN">原始路径；存储值为 <see langword="null" /> 时返回空字符串。</para>
		/// </returns>
		public static implicit operator string(FmodEventPath path)
		{
			return path.Value ?? string.Empty;
		}

		/// <summary>
		///     <para xml:lang="en">Wraps a raw string without validating or normalizing it.</para>
		///     <para xml:lang="zh-CN">包装原始字符串，不进行验证或规范化。</para>
		/// </summary>
		/// <param name="value">
		///     <para xml:lang="en">The raw value to wrap.</para>
		///     <para xml:lang="zh-CN">要包装的原始值。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The wrapped FMOD Studio path.</para>
		///     <para xml:lang="zh-CN">包装后的 FMOD Studio 路径。</para>
		/// </returns>
		public static implicit operator FmodEventPath(string value)
		{
			return new FmodEventPath(value);
		}

		/// <summary>
		///     <para xml:lang="en">Returns <see cref="P:STS2RitsuLib.Audio.FmodEventPath.Value" />, using an empty string for a default null value.</para>
		///     <para xml:lang="zh-CN">返回 <see cref="P:STS2RitsuLib.Audio.FmodEventPath.Value" />；默认值中的 <see langword="null" /> 会转换为空字符串。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">The raw path, or an empty string when the stored value is null.</para>
		///     <para xml:lang="zh-CN">原始路径；存储值为 <see langword="null" /> 时返回空字符串。</para>
		/// </returns>
		public override string ToString()
		{
			return Value ?? string.Empty;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides mutable dictionary and immutable-set factories for named FMOD parameter values.</para>
	///     <para xml:lang="zh-CN">提供命名 FMOD 参数值的可变字典和不可变参数集工厂。</para>
	/// </summary>
	public static class FmodParameterMap
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Creates an immutable parameter set from name/value tuples, with later duplicate names replacing
		///         earlier values.
		///     </para>
		///     <para xml:lang="zh-CN">根据名称/值元组创建不可变参数集；后出现的同名项会替换先前值。</para>
		/// </summary>
		/// <param name="pairs">
		///     <para xml:lang="en">The parameter tuples to copy.</para>
		///     <para xml:lang="zh-CN">要复制的参数元组。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The immutable parameter set, or <see cref="P:STS2RitsuLib.Audio.AudioParameterSet.Empty" /> for no tuples.</para>
		///     <para xml:lang="zh-CN">不可变参数集；没有元组时返回 <see cref="P:STS2RitsuLib.Audio.AudioParameterSet.Empty" />。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">Thrown when <paramref name="pairs" /> or one of its names is null.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="pairs" /> 或其中任一名称为 <see langword="null" /> 时抛出。</para>
		/// </exception>
		public static AudioParameterSet Set(params (string Name, float Value)[] pairs)
		{
			return AudioParameterSet.From(Of(pairs));
		}

		/// <summary>
		///     <para xml:lang="en">Creates a new empty mutable parameter dictionary.</para>
		///     <para xml:lang="zh-CN">创建新的空可变参数字典。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">A new empty dictionary.</para>
		///     <para xml:lang="zh-CN">新的空字典。</para>
		/// </returns>
		public static Dictionary<string, float> Empty()
		{
			return new Dictionary<string, float>();
		}

		/// <summary>
		///     <para xml:lang="en">Creates a new mutable dictionary containing one named parameter.</para>
		///     <para xml:lang="zh-CN">创建包含一个命名参数的新可变字典。</para>
		/// </summary>
		/// <param name="name">
		///     <para xml:lang="en">The case-sensitive parameter name.</para>
		///     <para xml:lang="zh-CN">区分大小写的参数名称。</para>
		/// </param>
		/// <param name="value">
		///     <para xml:lang="en">The parameter value.</para>
		///     <para xml:lang="zh-CN">参数值。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A new one-entry dictionary.</para>
		///     <para xml:lang="zh-CN">新的单条目字典。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">Thrown when <paramref name="name" /> is null.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="name" /> 为 <see langword="null" /> 时抛出。</para>
		/// </exception>
		public static Dictionary<string, float> Single(string name, float value)
		{
			return new Dictionary<string, float> { [name] = value };
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Creates a new mutable dictionary from name/value tuples, with later duplicate names replacing
		///         earlier values.
		///     </para>
		///     <para xml:lang="zh-CN">根据名称/值元组创建新的可变字典；后出现的同名项会替换先前值。</para>
		/// </summary>
		/// <param name="pairs">
		///     <para xml:lang="en">The parameter tuples to copy.</para>
		///     <para xml:lang="zh-CN">要复制的参数元组。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A new case-sensitive parameter dictionary.</para>
		///     <para xml:lang="zh-CN">新的区分大小写参数字典。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">Thrown when <paramref name="pairs" /> or one of its names is null.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="pairs" /> 或其中任一名称为 <see langword="null" /> 时抛出。</para>
		/// </exception>
		public static Dictionary<string, float> Of(params (string Name, float Value)[] pairs)
		{
			ArgumentNullException.ThrowIfNull(pairs, "pairs");
			if (pairs.Length == 0)
			{
				return new Dictionary<string, float>();
			}
			Dictionary<string, float> dictionary = new Dictionary<string, float>(pairs.Length);
			for (int i = 0; i < pairs.Length; i++)
			{
				(string Name, float Value) tuple = pairs[i];
				string item = tuple.Name;
				float item2 = tuple.Value;
				dictionary[item] = item2;
			}
			return dictionary;
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         A thread-safe in-memory path pool that randomly avoids selecting the same entry index twice in
	///         succession.
	///     </para>
	///     <para xml:lang="zh-CN">线程安全的内存路径池；随机选择时避免连续两次选中同一条目索引。</para>
	/// </summary>
	public sealed class FmodPathRoundRobinPool
	{
		private readonly List<string> _entries;

		private readonly Lock _gate = new Lock();

		private readonly Random _rng = new Random();

		private int _lastIndex = -1;

		/// <summary>
		///     <para xml:lang="en">Gets the read-only snapshot of configured path entries.</para>
		///     <para xml:lang="zh-CN">获取已配置路径条目的只读快照。</para>
		/// </summary>
		public IReadOnlyList<string> Entries { get; }

		/// <summary>
		///     <para xml:lang="en">Copies the supplied path sequence into a fixed internal list.</para>
		///     <para xml:lang="zh-CN">将提供的路径序列复制到固定的内部列表。</para>
		/// </summary>
		/// <param name="paths">
		///     <para xml:lang="en">The paths to copy; the sequence may be empty and is enumerated once.</para>
		///     <para xml:lang="zh-CN">要复制的路径；序列可以为空，并且只枚举一次。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">Thrown when <paramref name="paths" /> is null.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="paths" /> 为 <see langword="null" /> 时抛出。</para>
		/// </exception>
		public FmodPathRoundRobinPool(IEnumerable<string> paths)
		{
			ArgumentNullException.ThrowIfNull(paths, "paths");
			_entries = paths.ToList();
			Entries = new ReadOnlyCollection<string>(_entries);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Tries to pick a random entry, excluding the previously selected index when at least two entries
		///         exist.
		///     </para>
		///     <para xml:lang="zh-CN">尝试随机选择条目；存在至少两个条目时排除上次选中的索引。</para>
		/// </summary>
		/// <param name="path">
		///     <para xml:lang="en">Receives the selected path, or an empty string when the pool is empty.</para>
		///     <para xml:lang="zh-CN">接收选中的路径；池为空时接收空字符串。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> when an entry is selected; otherwise <see langword="false" />.</para>
		///     <para xml:lang="zh-CN">选中条目时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public bool TryPickNext(out string path)
		{
			using (_gate.EnterScope())
			{
				path = "";
				switch (_entries.Count)
				{
				case 0:
					return false;
				case 1:
					path = _entries[0];
					return true;
				}
				int num;
				do
				{
					num = _rng.Next(_entries.Count);
				}
				while (num == _lastIndex);
				_lastIndex = num;
				path = _entries[num];
				return true;
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides thread-safe, case-sensitive per-key cooldown gates measured with monotonic
	///         <see cref="T:System.Diagnostics.Stopwatch" /> timestamps.
	///     </para>
	///     <para xml:lang="zh-CN">提供线程安全且区分大小写的逐键冷却门控，并使用单调递增的 <see cref="T:System.Diagnostics.Stopwatch" /> 时间戳计时。</para>
	/// </summary>
	public static class FmodPlaybackThrottle
	{
		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<string, long> LastTicks = new Dictionary<string, long>(StringComparer.Ordinal);

		/// <summary>
		///     <para xml:lang="en">Attempts to enter a cooldown group, recording the current timestamp only when accepted.</para>
		///     <para xml:lang="zh-CN">尝试进入冷却分组，并且仅在请求通过时记录当前时间戳。</para>
		/// </summary>
		/// <param name="key">
		///     <para xml:lang="en">The case-sensitive cooldown-group key.</para>
		///     <para xml:lang="zh-CN">区分大小写的冷却分组键。</para>
		/// </param>
		/// <param name="cooldownMs">
		///     <para xml:lang="en">
		///         The cooldown duration in milliseconds; zero or a negative value always passes without recording
		///         state.
		///     </para>
		///     <para xml:lang="zh-CN">冷却时长（毫秒）；零或负值始终通过且不记录状态。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when the gate is disabled or the prior cooldown has elapsed; otherwise
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">门控被禁用或上次冷却已经结束时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">Thrown for a null <paramref name="key" /> when <paramref name="cooldownMs" /> is positive.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="cooldownMs" /> 为正数且 <paramref name="key" /> 为 <see langword="null" /> 时抛出。</para>
		/// </exception>
		public static bool TryEnter(string key, int cooldownMs)
		{
			if (cooldownMs <= 0)
			{
				return true;
			}
			long timestamp = Stopwatch.GetTimestamp();
			long num = (long)((double)(cooldownMs * Stopwatch.Frequency) / 1000.0);
			using (Gate.EnterScope())
			{
				if (LastTicks.TryGetValue(key, out var value) && timestamp - value < num)
				{
					return false;
				}
				LastTicks[key] = timestamp;
				return true;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Removes the recorded timestamp for one key so its next positive-cooldown entry may pass.</para>
		///     <para xml:lang="zh-CN">移除一个键已记录的时间戳，使其下一次正冷却时长请求可以通过。</para>
		/// </summary>
		/// <param name="key">
		///     <para xml:lang="en">The case-sensitive cooldown-group key to clear.</para>
		///     <para xml:lang="zh-CN">要清除的区分大小写冷却分组键。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentNullException">
		///     <para xml:lang="en">Thrown when <paramref name="key" /> is null.</para>
		///     <para xml:lang="zh-CN">当 <paramref name="key" /> 为 <see langword="null" /> 时抛出。</para>
		/// </exception>
		public static void Clear(string key)
		{
			using (Gate.EnterScope())
			{
				LastTicks.Remove(key);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Clears every recorded cooldown timestamp.</para>
		///     <para xml:lang="zh-CN">清除所有已记录的冷却时间戳。</para>
		/// </summary>
		public static void ClearAll()
		{
			using (Gate.EnterScope())
			{
				LastTicks.Clear();
			}
		}
	}
