		///     <para xml:lang="zh-CN">注册音频库路径以供下一次延迟刷新加载；空白路径和去除首尾空白后的重复值会被忽略。</para>
		/// </summary>
		/// <param name="resourcePath">
		///     <para xml:lang="en">The Godot resource path of the FMOD Studio bank.</para>
		///     <para xml:lang="zh-CN">FMOD Studio 音频库的 Godot 资源路径。</para>
		/// </param>
		/// <remarks>
		///     <para xml:lang="en">
		///         If deferred initialization has already completed, lifecycle replay starts the flush
		///         synchronously. A failed path remains pending until a later registration triggers another flush.
		///     </para>
		///     <para xml:lang="zh-CN">如果延迟初始化已经完成，生命周期回放会同步开始刷新。加载失败的路径会继续保留，直到后续注册再次触发刷新。</para>
		/// </remarks>
		public static void RegisterBank(string resourcePath)
		{
			if (!string.IsNullOrWhiteSpace(resourcePath))
			{
				using (Gate.EnterScope())
				{
					PendingBanks.Add(resourcePath.Trim());
				}
				EnsureFlushHookRegistered();
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Registers a GUID mapping file for <see cref="M:STS2RitsuLib.Audio.FmodStudioServer.TryLoadStudioGuidMappings(System.String)" />
		///         during the next deferred flush.
		///     </para>
		///     <para xml:lang="zh-CN">注册 GUID 映射文件，以便在下一次延迟刷新中通过 <see cref="M:STS2RitsuLib.Audio.FmodStudioServer.TryLoadStudioGuidMappings(System.String)" /> 加载。</para>
		/// </summary>
		/// <param name="guidMapResourcePath">
		///     <para xml:lang="en">
		///         The Godot resource path of a <c>GUIDs.txt</c>-style mapping file; blank paths and duplicate
		///         trimmed values are ignored.
		///     </para>
		///     <para xml:lang="zh-CN"><c>GUIDs.txt</c> 格式映射文件的 Godot 资源路径；空白路径和去除首尾空白后的重复值会被忽略。</para>
		/// </param>
		/// <remarks>
		///     <para xml:lang="en">
		///         If deferred initialization has already completed, lifecycle replay starts the flush
		///         synchronously. A failed path remains pending until a later registration triggers another flush.
		///     </para>
		///     <para xml:lang="zh-CN">如果延迟初始化已经完成，生命周期回放会同步开始刷新。加载失败的路径会继续保留，直到后续注册再次触发刷新。</para>
		/// </remarks>
		public static void RegisterStudioGuidMappings(string guidMapResourcePath)
		{
			if (!string.IsNullOrWhiteSpace(guidMapResourcePath))
			{
				using (Gate.EnterScope())
				{
					PendingGuidFiles.Add(guidMapResourcePath.Trim());
				}
				EnsureFlushHookRegistered();
			}
		}

		private static void EnsureFlushHookRegistered()
		{
			using (Gate.EnterScope())
			{
				if (_flushHookRegistered)
				{
					return;
				}
				_flushHookRegistered = true;
			}
			try
			{
				RitsuLibFramework.SubscribeLifecycleOnce<DeferredInitializationCompletedEvent>(delegate
				{
					using (Gate.EnterScope())
					{
						_flushHookRegistered = false;
					}
					FlushPending();
				});
			}
			catch
			{
				using (Gate.EnterScope())
				{
					_flushHookRegistered = false;
				}
				throw;
			}
		}

		private static void FlushPending()
		{
			using (FlushGate.EnterScope())
			{
				FlushPendingCore();
			}
		}

		private static void FlushPendingCore()
		{
			if (FmodStudioServer.TryGet() == null)
			{
				RitsuLibFramework.Logger.Warn("[Audio] deferred FMOD: FmodServer singleton missing; pending banks/GUID files kept for a later flush.", 1);
				return;
			}
			List<string> list;
			List<string> list2;
			using (Gate.EnterScope())
			{
				list = PendingBanks.ToList();
				list2 = PendingGuidFiles.ToList();
				PendingBanks.Clear();
				PendingGuidFiles.Clear();
			}
			if (list.Count == 0 && list2.Count == 0)
			{
				return;
			}
			List<string> list3 = new List<string>();
			List<string> list4 = new List<string>();
			foreach (string item in list)
			{
				if (!FmodStudioServer.TryLoadBank(item))
				{
					list3.Add(item);
				}
			}
			foreach (string item2 in list2)
			{
				if (!FmodStudioServer.TryLoadStudioGuidMappings(item2))
				{
					list4.Add(item2);
				}
			}
			if (list3.Count < list.Count || list4.Count < list2.Count)
			{
				FmodStudioServer.TryWaitForAllLoads();
			}
			if (list3.Count > 0 || list4.Count > 0)
			{
				using (Gate.EnterScope())
				{
					PendingBanks.UnionWith(list3);
					PendingGuidFiles.UnionWith(list4);
				}
			}
			RitsuLibFramework.Logger.Info($"[Audio] deferred FMOD flush complete (banks={list.Count - list3.Count}/{list.Count}, guid files={list2.Count - list4.Count}/{list2.Count}).", 1);
			if (list3.Count > 0 || list4.Count > 0)
			{
				RitsuLibFramework.Logger.Warn($"[Audio] deferred FMOD flush retained {list3.Count} bank(s) and {list4.Count} GUID file(s) for retry.", 1);
			}
		}
	}
