			//IL_013a: Unknown result type (might be due to invalid IL or missing references)
			//IL_013f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0150: Unknown result type (might be due to invalid IL or missing references)
			//IL_0094: Unknown result type (might be due to invalid IL or missing references)
			//IL_0099: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a7: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ac: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b1: Unknown result type (might be due to invalid IL or missing references)
			ArgumentNullException.ThrowIfNull(parameters, "parameters");
			if (!TryGetMappedEventParameterNames(eventPath, out HashSet<string> names))
			{
				return false;
			}
			GodotObject val = FmodStudioEventInstances.TryCreate(eventPath);
			if (val == null)
			{
				return false;
			}
			try
			{
				if (!val.HasMethod(SetVolume) || !val.HasMethod(Start))
				{
					return false;
				}
				foreach (KeyValuePair<string, float> parameter in parameters)
				{
					if (names == null || names.Contains(parameter.Key))
					{
