					}
				}
				val.Call(SetVolume, (Variant[])(object)new Variant[1] { Variant.op_Implicit(linearVolume) });
				val.Call(Start, Array.Empty<Variant>());
				return true;
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[Audio] FMOD mapped path one-shot: {value}");
				return false;
			}
			finally
			{
				FmodStudioEventInstances.TryRelease(val);
			}
		}

		private static bool TryGetMappedEventParameterNames(string eventPath, out HashSet<string>? names)
		{
			//IL_0042: Unknown result type (might be due to invalid IL or missing references)
			//IL_0047: Unknown result type (might be due to invalid IL or missing references)
			//IL_004a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0052: Invalid comparison between Unknown and I8
			//IL_006d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0072: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a6: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ab: Unknown result type (might be due to invalid IL or missing references)
			names = null;
			if (!FmodStudioGuidPathTable.TryGetStudioGuidForEventPath(eventPath, out string guid))
			{
				return true;
			}
			names = new HashSet<string>(StringComparer.Ordinal);
			GodotObject val = FmodStudioServer.TryGetEventDescriptionFromGuid(guid);
			if (val == null)
			{
				return true;
			}
			if (!val.HasMethod(GetParameters))
			{
				return false;
			}
			try
			{
				Variant val2 = val.Call(GetParameters, Array.Empty<Variant>());
				if ((long)((Variant)(ref val2)).VariantType != 28)
				{
					return false;
				}
				foreach (Variant item in ((Variant)(ref val2)).AsGodotArray())
				{
					Variant current = item;
					GodotObject val3 = ((Variant)(ref current)).AsGodotObject();
					if (val3 != null && GodotObject.IsInstanceValid(val3) && val3.HasMethod(GetName))
					{
						HashSet<string>? obj = names;
						Variant val4 = val3.Call(GetName, Array.Empty<Variant>());
						obj.Add(((Variant)(ref val4)).AsString());
					}
				}
				return true;
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[Audio] FMOD mapped event parameter inspection: {value}");
				return false;
			}
		}

		static FmodStudioDirectOneShots()
		{
			//IL_0005: Unknown result type (might be due to invalid IL or missing references)
			//IL_000f: Expected O, but got Unknown
			//IL_0014: Unknown result type (might be due to invalid IL or missing references)
			//IL_001e: Expected O, but got Unknown
			//IL_0023: Unknown result type (might be due to invalid IL or missing references)
			//IL_002d: Expected O, but got Unknown
			//IL_0032: Unknown result type (might be due to invalid IL or missing references)
			//IL_003c: Expected O, but got Unknown
			//IL_0041: Unknown result type (might be due to invalid IL or missing references)
