		/// </returns>
		public static bool TrySetDspBufferSize(int bufferLength, int bufferCount)
		{
			//IL_0023: Unknown result type (might be due to invalid IL or missing references)
			//IL_0028: Unknown result type (might be due to invalid IL or missing references)
			//IL_002b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0033: Invalid comparison between Unknown and I8
			//IL_007f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0084: Unknown result type (might be due to invalid IL or missing references)
			//IL_0089: Unknown result type (might be due to invalid IL or missing references)
			//IL_009e: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a3: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a8: Unknown result type (might be due to invalid IL or missing references)
			//IL_00bc: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c1: Unknown result type (might be due to invalid IL or missing references)
			if (bufferLength <= 0 || bufferCount <= 0)
			{
				return false;
			}
			try
			{
				if (!ClassDB.CanInstantiate(DspSettingsClass))
				{
					return false;
				}
				Variant val = ClassDB.Instantiate(DspSettingsClass);
				if ((long)((Variant)(ref val)).VariantType != 24)
				{
					return false;
				}
				GodotObject val2 = ((Variant)(ref val)).AsGodotObject();
				if (val2 == null || !GodotObject.IsInstanceValid(val2) || !val2.HasMethod(SetDspBufferSize) || !val2.HasMethod(SetDspBufferCount))
				{
					return false;
				}
				val2.Call(SetDspBufferSize, (Variant[])(object)new Variant[1] { Variant.op_Implicit(bufferLength) });
				val2.Call(SetDspBufferCount, (Variant[])(object)new Variant[1] { Variant.op_Implicit(bufferCount) });
				return FmodStudioGateway.TryCall(FmodStudioMethodNames.SetSystemDspBufferSize, Variant.op_Implicit(val2));
