		{
			return FmodStudioGateway.TryGetServer();
		}

		/// <summary>
		///     <para xml:lang="en">Attempts to load and retain an FMOD Studio bank from a Godot resource path.</para>
		///     <para xml:lang="zh-CN">尝试从 Godot 资源路径加载并保留 FMOD Studio 音频库。</para>
		/// </summary>
		/// <param name="resourcePath">
		///     <para xml:lang="en">The existing Godot resource path of the bank file.</para>
		///     <para xml:lang="zh-CN">现有音频库文件的 Godot 资源路径。</para>
		/// </param>
		/// <param name="mode">
		///     <para xml:lang="en">The bank-loading mode passed to <c>FmodServer.load_bank</c>.</para>
		///     <para xml:lang="zh-CN">传递给 <c>FmodServer.load_bank</c> 的音频库加载模式。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when loading returns a valid retained bank object or a compatible
		///         boolean success result; otherwise <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">加载返回可保留的有效音频库对象或兼容的布尔成功结果时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public static bool TryLoadBank(string resourcePath, FmodStudioLoadBankMode mode = FmodStudioLoadBankMode.Normal)
		{
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			//IL_005a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0062: Unknown result type (might be due to invalid IL or missing references)
			//IL_0067: Unknown result type (might be due to invalid IL or missing references)
			//IL_0098: Unknown result type (might be due to invalid IL or missing references)
			//IL_009d: Unknown result type (might be due to invalid IL or missing references)
			//IL_009e: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a1: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a4: Invalid comparison between Unknown and I8
			//IL_00a6: Unknown result type (might be due to invalid IL or missing references)
			//IL_00aa: Invalid comparison between Unknown and I8
			//IL_0134: Unknown result type (might be due to invalid IL or missing references)
			//IL_01bd: Unknown result type (might be due to invalid IL or missing references)
			if (string.IsNullOrWhiteSpace(resourcePath))
			{
				RitsuLibFramework.Logger.Warn("[Audio] FMOD load_bank: empty path.", 1);
				return false;
			}
			if (!FileAccess.FileExists(resourcePath))
			{
				RitsuLibFramework.Logger.Warn("[Audio] FMOD load_bank: file not found: " + resourcePath + "; " + DescribeResourceForDiagnostics(resourcePath), 1);
				return false;
			}
			if (!FmodStudioGateway.TryCall(out var result, FmodStudioMethodNames.LoadBank, Variant.op_Implicit(resourcePath), Variant.op_Implicit((int)mode)))
			{
				RitsuLibFramework.Logger.Warn("[Audio] FMOD load_bank call failed: " + resourcePath + "; " + DescribeResourceForDiagnostics(resourcePath), 1);
				return false;
			}
			Type variantType = ((Variant)(ref result)).VariantType;
			if ((int)variantType != 0)
			{
				if ((long)variantType != 1)
				{
					if ((long)variantType == 24)
					{
						GodotObject val = ((Variant)(ref result)).AsGodotObject();
						if (val == null || !GodotObject.IsInstanceValid(val))
						{
							RitsuLibFramework.Logger.Warn($"[Audio] FMOD load_bank returned invalid {((Variant)(ref result)).VariantType}: {resourcePath}; {DescribeResourceForDiagnostics(resourcePath)}", 1);
							return false;
						}
						using (LoadedBankPinsGate.EnterScope())
						{
							LoadedBankPins[resourcePath] = val;
						}
						return true;
					}
					RitsuLibFramework.Logger.Warn($"[Audio] FMOD load_bank returned unsupported {((Variant)(ref result)).VariantType}: {resourcePath}; {DescribeResourceForDiagnostics(resourcePath)}", 1);
					return false;
				}
				if (((Variant)(ref result)).AsBool())
				{
					return true;
				}
				RitsuLibFramework.Logger.Warn("[Audio] FMOD load_bank returned false: " + resourcePath + "; " + DescribeResourceForDiagnostics(resourcePath), 1);
				return false;
			}
			RitsuLibFramework.Logger.Warn("[Audio] FMOD load_bank returned nil: " + resourcePath + "; " + DescribeResourceForDiagnostics(resourcePath), 1);
			return false;
		}

		/// <summary>
		///     <para xml:lang="en">Logs Godot-side file, resource, hash, header, and globalized-path facts for a bank path.</para>
		///     <para xml:lang="zh-CN">记录音频库路径在 Godot 侧的文件、资源、哈希、文件头和全局化路径信息。</para>
		/// </summary>
		/// <param name="resourcePath">
