		/// <summary>
		///     <para xml:lang="en">
		///         Logs up to forty event paths reported by an already-loaded bank's <c>get_description_list</c>
		///         result.
		///     </para>
		///     <para xml:lang="zh-CN">记录已加载音频库通过 <c>get_description_list</c> 报告的最多四十个事件路径。</para>
		/// </summary>
		/// <param name="bankResourcePath">
		///     <para xml:lang="en">The exact Godot resource path of the loaded bank; blank paths are ignored.</para>
		///     <para xml:lang="zh-CN">已加载音频库的准确 Godot 资源路径；空白路径会被忽略。</para>
		/// </param>
		/// <remarks>
		///     <para xml:lang="en">
		///         Unreadable or missing banks and banks with no events produce warnings. The method does not
		///         report global cache totals.
		///     </para>
		///     <para xml:lang="zh-CN">无法读取、未找到或不含事件的音频库会产生警告。此方法不报告全局缓存总数。</para>
		/// </remarks>
		public static void TryLogLoadedStudioBankEvents(string bankResourcePath)
		{
			if (string.IsNullOrWhiteSpace(bankResourcePath))
			{
				return;
			}
			List<string> list = TryCollectLoadedBankEventPaths(bankResourcePath);
			if (list == null)
			{
				RitsuLibFramework.Logger.Warn("[Audio] FMOD bank not loaded or unreadable: " + bankResourcePath, 1);
				return;
			}
			if (list.Count == 0)
			{
				RitsuLibFramework.Logger.Warn("[Audio] FMOD bank has no events — rebuild banks from FMOD Studio or verify the exported .bank.", 1);
				return;
			}
			StringBuilder stringBuilder = new StringBuilder(256);
			int num = Math.Min(list.Count, 40);
			for (int i = 0; i < num; i++)
			{
				if (i > 0)
				{
					stringBuilder.Append(", ");
				}
				stringBuilder.Append(list[i]);
			}
			if (list.Count > 40)
			{
				stringBuilder.Append(" … (+").Append(list.Count - 40).Append(" more)");
			}
			RitsuLibFramework.Logger.Info($"[Audio] FMOD bank {bankResourcePath} ({list.Count} event{((list.Count == 1) ? "" : "s")}): {stringBuilder}", 1);
		}

