		private static bool TryCallNativeGuidInject(string resourcePath)
		{
			//IL_0034: Unknown result type (might be due to invalid IL or missing references)
			//IL_0039: Unknown result type (might be due to invalid IL or missing references)
			//IL_003e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0043: Unknown result type (might be due to invalid IL or missing references)
			//IL_0047: Unknown result type (might be due to invalid IL or missing references)
			//IL_004e: Invalid comparison between Unknown and I8
			GodotObject val = FmodStudioGateway.TryGetServer();
			if (val == null)
			{
				return false;
			}
			StringName[] guidMappingInjectCandidates = GuidMappingInjectCandidates;
			foreach (StringName val2 in guidMappingInjectCandidates)
			{
				if (!val.HasMethod(val2))
				{
					continue;
				}
				try
				{
					Variant val3 = val.Call(val2, (Variant[])(object)new Variant[1] { Variant.op_Implicit(resourcePath) });
					if ((long)((Variant)(ref val3)).VariantType == 1 && !((Variant)(ref val3)).AsBool())
					{
						continue;
					}
					return true;
				}
				catch (Exception value)
				{
					RitsuLibFramework.Logger.ErrorNoTrace($"[Audio] FMOD guid inject {val2}: {value}");
				}
			}
			return false;
		}

		private static string DescribeResourceForDiagnostics(string resourcePath)
		{
			List<string> list = new List<string>
			{
				$"fileExists={FileAccess.FileExists(resourcePath)}",
				$"resourceExists={ResourceLoader.Exists(resourcePath, "")}"
			};
			try
			{
				byte[] fileAsBytes = FileAccess.GetFileAsBytes(resourcePath);
				list.Add($"bytes={fileAsBytes.Length}");
				if (fileAsBytes.Length != 0)
				{
					list.Add("sha256=" + Convert.ToHexString(SHA256.HashData(fileAsBytes)).ToLowerInvariant());
					list.Add("head=" + DescribeHead(fileAsBytes));
				}
			}
			catch (Exception value)
			{
				list.Add($"readError={value}");
			}
			try
			{
				Resource val = ResourceLoader.Load<Resource>(resourcePath, (string)null, (CacheMode)1);
				list.Add((val == null) ? "resourceType=<null>" : ("resourceType=" + ((GodotObject)val).GetClass() + "; resourcePath=" + val.ResourcePath));
			}
			catch (Exception value2)
			{
				list.Add($"resourceLoadError={value2}");
			}
			try
			{
				string text = ProjectSettings.GlobalizePath(resourcePath);
				if (!string.IsNullOrWhiteSpace(text) && !string.Equals(text, resourcePath, StringComparison.Ordinal))
				{
					list.Add("globalized=" + text);
				}
			}
			catch (Exception value3)
			{
				list.Add($"globalizeError={value3}");
			}
			list.Add("nativeResult=unavailable-from-managed-wrapper");
			return string.Join("; ", list);
		}

		private static string DescribeHead(byte[] bytes)
		{
			int num = Math.Min(bytes.Length, 16);
			string text = Convert.ToHexString(bytes, 0, num).ToLowerInvariant();
			char[] array = new char[num];
			for (int i = 0; i < num; i++)
			{
				int num2 = i;
				byte b = bytes[i];
				array[num2] = (char)((b >= 32 && b <= 126) ? bytes[i] : 46);
			}
			return text + "/" + new string(array);
		}

