		/// <summary>
		///     <para xml:lang="en">Attempts to unload a snapshot of every path currently tracked by this helper.</para>
		///     <para xml:lang="zh-CN">尝试卸载此辅助类当前跟踪的所有路径快照。</para>
		/// </summary>
		/// <remarks>
		///     <para xml:lang="en">Failed unloads and paths added concurrently after the snapshot remain tracked.</para>
		///     <para xml:lang="zh-CN">卸载失败的路径，以及生成快照后并发加入的路径，仍会继续保留在跟踪表中。</para>
		/// </remarks>
		public static void TryUnloadAllTracked()
		{
			string[] array = Loaded.Keys.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				TryUnloadFile(array[i]);
			}
		}

		private static bool TryResolveSupportedPath(string path, out string resolvedPath)
		{
			resolvedPath = string.Empty;
			if (string.IsNullOrWhiteSpace(path))
			{
				RitsuLibFramework.Logger.ErrorNoTrace("[Audio] FMOD file playback requires a non-empty path.");
				return false;
			}
			if (path.StartsWith("user://", StringComparison.OrdinalIgnoreCase))
			{
				resolvedPath = ProjectSettings.GlobalizePath(path);
				if (!Path.IsPathRooted(resolvedPath))
				{
					RitsuLibFramework.Logger.ErrorNoTrace("[Audio] FMOD file playback requires an absolute path: " + path);
					return false;
				}
				if (File.Exists(resolvedPath))
				{
					return true;
				}
				RitsuLibFramework.Logger.ErrorNoTrace("[Audio] FMOD file playback file not found: " + resolvedPath);
				return false;
			}
			if (path.StartsWith("res://", StringComparison.OrdinalIgnoreCase))
			{
				if (FileAccess.FileExists(path))
				{
					resolvedPath = path;
					return true;
				}
				if (ResourceLoader.Exists(path, ""))
				{
					RitsuLibFramework.Logger.Warn("[Audio] FMOD file playback: path resolves only as imported/packed resource, not as a raw file for FileAccess. Avoid default import for assets you stream through FMOD: use the Import dock \"Keep File (No Import)\" (or ship a loose file / FMOD Studio bank). Path: " + path, 1);
					return false;
				}
				RitsuLibFramework.Logger.ErrorNoTrace("[Audio] FMOD file playback file not found: " + path);
				return false;
			}
			resolvedPath = path;
			if (!Path.IsPathRooted(resolvedPath))
			{
				RitsuLibFramework.Logger.ErrorNoTrace("[Audio] FMOD file playback requires an absolute path: " + path);
				return false;
			}
			if (File.Exists(resolvedPath))
			{
				return true;
			}
			RitsuLibFramework.Logger.ErrorNoTrace("[Audio] FMOD file playback file not found: " + resolvedPath);
			return false;
		}

		private static bool CheckLoadedKind(string path, LoadedKind actual, LoadedKind requested)
		{
			if (actual == requested)
			{
				return true;
			}
			RitsuLibFramework.Logger.Warn($"[Audio] FMOD file is already loaded as {actual} and cannot also be loaded as {requested}: {path}", 1);
			return false;
		}

		private static GodotObject? TryCreateLoadedInstance(string resolvedPath)
		{
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_0025: Unknown result type (might be due to invalid IL or missing references)
			//IL_002d: Invalid comparison between Unknown and I8
			if (!FmodStudioGateway.TryCall(out var result, FmodStudioMethodNames.CreateSoundInstance, Variant.op_Implicit(resolvedPath)))
			{
				return null;
			}
			if ((long)((Variant)(ref result)).VariantType != 24)
			{
				return null;
			}
			GodotObject val = ((Variant)(ref result)).AsGodotObject();
			if (val == null || !GodotObject.IsInstanceValid(val))
			{
				return null;
			}
			return val;
		}

		private static bool TryLoadFile(StringName method, string resolvedPath)
		{
			//IL_000c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			//IL_001f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0027: Invalid comparison between Unknown and I8
			if (!FmodStudioGateway.TryCall(out var result, method, Variant.op_Implicit(resolvedPath)) || (long)((Variant)(ref result)).VariantType != 24)
			{
				return false;
			}
			GodotObject val = ((Variant)(ref result)).AsGodotObject();
			if (val != null)
			{
				return GodotObject.IsInstanceValid(val);
			}
			return false;
		}

		private static bool TryConfigureAndPlay(GodotObject? sound, float volume, float pitch, string sourceKind)
		{
			//IL_0067: Unknown result type (might be due to invalid IL or missing references)
			//IL_006c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0071: Unknown result type (might be due to invalid IL or missing references)
			//IL_0086: Unknown result type (might be due to invalid IL or missing references)
			//IL_008b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0090: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a1: Unknown result type (might be due to invalid IL or missing references)
			if (sound == null || !GodotObject.IsInstanceValid(sound))
			{
				return false;
			}
			bool flag = false;
			try
			{
				if (!sound.HasMethod(SetVolume) || !sound.HasMethod(SetPitch) || !sound.HasMethod(Play))
				{
					RitsuLibFramework.Logger.Warn("[Audio] FMOD play " + sourceKind + ": sound instance is missing a required method.", 1);
					return false;
				}
				sound.Call(SetVolume, (Variant[])(object)new Variant[1] { Variant.op_Implicit(volume) });
				sound.Call(SetPitch, (Variant[])(object)new Variant[1] { Variant.op_Implicit(pitch) });
				sound.Call(Play, Array.Empty<Variant>());
				flag = true;
				return true;
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[Audio] FMOD play {sourceKind}: {value}");
				return false;
			}
			finally
			{
				if (!flag)
				{
					FmodStudioEventInstances.TryRelease(sound);
				}
			}
		}

		static FmodStudioStreamingFiles()
		{
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0028: Expected O, but got Unknown
			//IL_002d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0037: Expected O, but got Unknown
			//IL_003c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0046: Expected O, but got Unknown
			Loaded = new ConcurrentDictionary<string, LoadedKind>(StringComparer.Ordinal);
			LoadedGate = new Lock();
			SetVolume = new StringName("set_volume");
			SetPitch = new StringName("set_pitch");
			Play = new StringName("play");
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Implements <see cref="P:STS2RitsuLib.Audio.GameFmod.Playback" /> with typed handles, playback options, routing, and
	///         lifecycle ownership.
	///     </para>
	///     <para xml:lang="zh-CN">使用类型化句柄、播放选项、路由和生命周期归属实现 <see cref="P:STS2RitsuLib.Audio.GameFmod.Playback" />。</para>
	/// </summary>
	public sealed class GameAudioService : IGameAudio
	{
		/// <summary>
		///     <para xml:lang="en">Gets the shared playback service.</para>
		///     <para xml:lang="zh-CN">获取共享播放服务。</para>
		/// </summary>
		public static GameAudioService Shared { get; } = new GameAudioService();

		private GameAudioService()
		{
		}

		/// <inheritdoc />
		public AudioPlayResult Play(AudioSource source, AudioPlaybackOptions? options = null)
		{
			if (options == null)
			{
				options = new AudioPlaybackOptions();
			}
			AudioScopeToken scopeToken = options.ScopeToken;
			if (scopeToken != null && scopeToken.IsClosing)
			{
				return AudioPlayResult.Fail(AudioPlayStatus.Failed, "The audio scope token is disposed.");
			}
			if (!TryEnterCooldown(source, options))
			{
				return AudioPlayResult.Fail(AudioPlayStatus.SkippedCooldown);
			}
			return PlayCore(source, options);
		}

		/// <inheritdoc />
		public AudioPlayResult PlayOneShot(AudioSource source, AudioPlaybackOptions? options = null)
		{
			if (options == null)
			{
				options = new AudioPlaybackOptions();
			}
			AudioScopeToken scopeToken = options.ScopeToken;
			if (scopeToken != null && scopeToken.IsClosing)
			{
				return AudioPlayResult.Fail(AudioPlayStatus.Failed, "The audio scope token is disposed.");
			}
			if (!TryEnterCooldown(source, options))
			{
				return AudioPlayResult.Fail(AudioPlayStatus.SkippedCooldown);
			}
			if (!(source is StudioEventSource source2))
			{
				if (!(source is StudioGuidSource source3))
				{
					if (!(source is SoundFileSource source4))
					{
						if (source is ResourceSoundFileSource source5)
						{
							return PlayResourceSoundFile(source5, options);
						}
						return AudioPlayResult.Fail(AudioPlayStatus.NotSupported);
					}
					return PlaySoundFile(source4, options);
				}
				return PlayStudioGuid(source3, options);
			}
			if (options.UseVanillaRouting)
			{
				return PlayVanillaOneShot(source2, options);
			}
			return PlayStudioEvent(source2, options);
		}

		/// <inheritdoc />
		public AudioLoopHandle? PlayLoop(AudioSource source, AudioPlaybackOptions? options = null)
		{
			if (options == null)
			{
				options = new AudioPlaybackOptions();
			}
			AudioScopeToken scopeToken = options.ScopeToken;
			if (scopeToken != null && scopeToken.IsClosing)
			{
				return null;
			}
			if (!TryEnterCooldown(source, options))
			{
				return null;
			}
			AudioPlayResult audioPlayResult = ((source is StudioEventSource source2) ? PlayStudioLoop(source2, options) : ((source is StudioGuidSource source3) ? PlayStudioLoopFromGuid(source3, options) : ((source is StreamingMusicSource source4) ? PlayStreamingMusic(source4, options) : ((!(source is StreamingResourceMusicSource source5)) ? AudioPlayResult.Fail(AudioPlayStatus.NotSupported) : PlayStreamingResourceMusic(source5, options)))));
			return audioPlayResult.Handle as AudioLoopHandle;
		}

		/// <inheritdoc />
		public AudioMusicHandle? PlayMusic(AudioSource source, AudioPlaybackOptions? options = null)
		{
			if (options == null)
			{
				options = new AudioPlaybackOptions();
			}
			AudioScopeToken scopeToken = options.ScopeToken;
			if (scopeToken != null && scopeToken.IsClosing)
			{
				return null;
			}
			if (!TryEnterCooldown(source, options))
			{
				return null;
			}
			AudioPlayResult audioPlayResult = ((source is StudioEventSource source2) ? PlayStudioEvent(source2, options, asMusic: true) : ((source is StudioGuidSource source3) ? PlayStudioEventFromGuid(source3, options, asMusic: true) : ((source is StreamingMusicSource source4) ? PlayStreamingMusic(source4, options, asMusic: true) : ((!(source is StreamingResourceMusicSource source5)) ? AudioPlayResult.Fail(AudioPlayStatus.NotSupported) : PlayStreamingResourceMusic(source5, options, asMusic: true)))));
			return audioPlayResult.Handle as AudioMusicHandle;
		}

		/// <inheritdoc />
		public AudioAdaptiveMusicHandle FollowAdaptiveMusic(AudioAdaptiveMusicPlan plan)
		{
			return AudioAdaptiveMusicDirector.Shared.Attach(plan);
		}

		/// <inheritdoc />
		public AudioScopeToken CreateManualScope(string name)
		{
			return new AudioScopeToken(name, AudioLifecycleScope.Manual);
		}

		/// <inheritdoc />
		public bool StopScope(AudioScopeToken scope, bool allowFadeOut = true)
		{
			return AudioLifecycleRegistry.Shared.StopScope(scope, allowFadeOut);
		}

		/// <inheritdoc />
		public bool StopChannel(string channel, bool allowFadeOut = true)
		{
			return AudioChannelRegistry.Shared.StopChannel(channel, allowFadeOut);
		}

		/// <inheritdoc />
		public bool StopTag(string tag, bool allowFadeOut = true)
		{
			return AudioChannelRegistry.Shared.StopTag(tag, allowFadeOut);
		}

		private static AudioPlayResult PlayCore(AudioSource source, AudioPlaybackOptions options)
		{
			if (!(source is StudioEventSource source2))
			{
				if (!(source is StudioGuidSource source3))
				{
					if (!(source is SoundFileSource source4))
					{
						if (!(source is ResourceSoundFileSource source5))
						{
							if (!(source is StreamingMusicSource source6))
							{
								if (!(source is StreamingResourceMusicSource source7))
								{
									if (source is SnapshotSource source8)
									{
										return PlaySnapshot(source8, options);
									}
									return AudioPlayResult.Fail(AudioPlayStatus.InvalidSource);
								}
								return PlayStreamingResourceMusic(source7, options);
							}
							return PlayStreamingMusic(source6, options);
						}
						return PlayResourceSoundFile(source5, options);
					}
					return PlaySoundFile(source4, options);
				}
				return PlayStudioEventFromGuid(source3, options);
			}
			return PlayStudioEvent(source2, options);
		}

		private static AudioPlayResult PlayVanillaOneShot(StudioEventSource source, AudioPlaybackOptions options)
		{
			if (!((options.GetParameters().Count == 0) ? GameFmodAudioService.Shared.TryPlayOneShot(source.Path, options.Volume) : GameFmodAudioService.Shared.TryPlayOneShot(source.Path, options.GetParameters(), options.Volume)))
			{
				return AudioPlayResult.Fail(AudioPlayStatus.MissingManager);
			}
			return AudioPlayResult.Started();
		}

		private static AudioPlayResult PlayStudioGuid(StudioGuidSource source, AudioPlaybackOptions options)
		{
			return PlayStudioEventFromGuid(source, options);
		}

		private static AudioPlayResult PlayStudioLoop(StudioEventSource source, AudioPlaybackOptions options)
		{
			GodotObject val = FmodStudioEventInstances.TryCreate(source.Path);
			if (val != null)
			{
				return AttachStudioLoop(source, val, options);
			}
			return AudioPlayResult.Fail(AudioPlayStatus.MissingInstance);
		}

		private static AudioPlayResult PlayStudioLoopFromGuid(StudioGuidSource source, AudioPlaybackOptions options)
		{
			GodotObject val = FmodStudioEventInstances.TryCreateFromGuid(source.Value);
			if (val != null)
			{
				return AttachStudioLoop(source, val, options);
			}
			return AudioPlayResult.Fail(AudioPlayStatus.MissingInstance);
		}

		private static AudioPlayResult AttachStudioLoop(AudioSource source, GodotObject instance, AudioPlaybackOptions options)
		{
			return AttachAndConfigure(new AudioLoopHandle(source, ResolveScope(options), instance), options, options.UsesLoopParameter);
		}

		private static AudioPlayResult PlayStudioEvent(StudioEventSource source, AudioPlaybackOptions options, bool asMusic = false)
		{
			GodotObject val = FmodStudioEventInstances.TryCreate(source.Path);
			if (val != null)
			{
				return AttachStudioPlayback(source, val, options, asMusic);
			}
			return AudioPlayResult.Fail(AudioPlayStatus.MissingInstance);
		}

		private static AudioPlayResult PlayStudioEventFromGuid(StudioGuidSource source, AudioPlaybackOptions options, bool asMusic = false)
		{
			GodotObject val = FmodStudioEventInstances.TryCreateFromGuid(source.Value);
			if (val != null)
			{
				return AttachStudioPlayback(source, val, options, asMusic);
			}
			return AudioPlayResult.Fail(AudioPlayStatus.MissingInstance);
		}

		private static AudioPlayResult AttachStudioPlayback(AudioSource source, GodotObject instance, AudioPlaybackOptions options, bool asMusic)
		{
			return AttachAndConfigure(asMusic ? ((AudioHandleBase)new AudioMusicHandle(source, ResolveScope(options), instance)) : ((AudioHandleBase)new AudioEventHandle(source, ResolveScope(options), instance)), options);
		}

		private static AudioPlayResult PlaySoundFile(SoundFileSource source, AudioPlaybackOptions options)
		{
			GodotObject val = FmodStudioStreamingFiles.TryCreateSoundInstance(source.AbsolutePath);
			if (val == null)
			{
				return AudioPlayResult.Fail(AudioPlayStatus.MissingInstance);
			}
			return AttachAndConfigure(new AudioFileHandle(source, ResolveScope(options), val), options);
		}

		private static AudioPlayResult PlayResourceSoundFile(ResourceSoundFileSource source, AudioPlaybackOptions options)
		{
			GodotObject val = FmodStudioStreamingFiles.TryCreateResourceSoundInstance(source.ResourcePath);
			if (val == null)
			{
				return AudioPlayResult.Fail(AudioPlayStatus.MissingInstance);
			}
			return AttachAndConfigure(new AudioFileHandle(source, ResolveScope(options), val), options);
		}

		private static AudioPlayResult PlayStreamingMusic(StreamingMusicSource source, AudioPlaybackOptions options, bool asMusic = false)
		{
			GodotObject val = FmodStudioStreamingFiles.TryCreateStreamingMusicInstance(source.AbsolutePath);
			if (val == null)
			{
				return AudioPlayResult.Fail(AudioPlayStatus.MissingInstance);
			}
			return AttachAndConfigure(asMusic ? ((AudioHandleBase)new AudioMusicHandle(source, ResolveScope(options), val)) : ((AudioHandleBase)new AudioLoopHandle(source, ResolveScope(options), val)), options);
		}

		private static AudioPlayResult PlayStreamingResourceMusic(StreamingResourceMusicSource source, AudioPlaybackOptions options, bool asMusic = false)
		{
			GodotObject val = FmodStudioStreamingFiles.TryCreateResourceStreamingMusicInstance(source.ResourcePath);
			if (val == null)
			{
				return AudioPlayResult.Fail(AudioPlayStatus.MissingInstance);
			}
			return AttachAndConfigure(asMusic ? ((AudioHandleBase)new AudioMusicHandle(source, ResolveScope(options), val)) : ((AudioHandleBase)new AudioLoopHandle(source, ResolveScope(options), val)), options);
		}

		private static AudioPlayResult PlaySnapshot(SnapshotSource source, AudioPlaybackOptions options)
		{
			GodotObject val = FmodStudioEventInstances.TryCreate(source.Path);
			if (val == null)
			{
				return AudioPlayResult.Fail(AudioPlayStatus.MissingInstance);
			}
			return AttachAndConfigure(new AudioSnapshotHandle(source, ResolveScope(options), val), options);
		}

		private static AudioPlayResult AttachAndConfigure(AudioHandleBase handle, AudioPlaybackOptions options, bool applyLoopParameter = false)
		{
			handle.AllowFadeOutOnStop = options.AllowFadeOutOnStop;
			if (!AudioLifecycleRegistry.Shared.TryAttach(handle, options))
			{
				return AudioPlayResult.Fail(AudioPlayStatus.Failed, "The audio scope token is disposed.");
			}
			if (!TryApplyRouting(handle, options))
			{
				return FailHandle(handle, "Audio routing could not be applied.");
			}
			if (!handle.TrySetVolume(options.Volume))
			{
				return FailHandle(handle, "The initial volume could not be applied.");
			}
			if (!handle.TrySetPitch(options.Pitch))
			{
				return FailHandle(handle, "The initial pitch could not be applied.");
			}
			foreach (KeyValuePair<string, float> parameter in options.GetParameters())
			{
				if (!handle.TrySetParameter(parameter.Key, parameter.Value))
				{
					return FailHandle(handle, "The initial parameter '" + parameter.Key + "' could not be applied.");
				}
			}
			if (applyLoopParameter && !handle.TrySetParameter("loop", 0f))
			{
				return FailHandle(handle, "The initial loop parameter could not be applied.");
			}
			if (options.AutoPlay && !handle.TryPlay())
			{
				return FailHandle(handle, "Playback could not be started.");
			}
			if (options.StartPaused && !handle.TryPause())
			{
				return FailHandle(handle, "The initial paused state could not be applied.");
			}
			return AudioPlayResult.Started(handle);
		}

		private static AudioPlayResult FailHandle(AudioHandleBase handle, string message)
		{
			handle.Dispose();
			return AudioPlayResult.Fail(AudioPlayStatus.Failed, message);
		}

		private static bool TryApplyRouting(IAudioHandle handle, AudioPlaybackOptions options)
		{
			AudioRoutingOptions routing = options.Routing;
			if (routing == null)
			{
				return true;
			}
			if (string.IsNullOrWhiteSpace(routing.Tag))
			{
				if (!string.IsNullOrWhiteSpace(routing.Channel))
				{
					return AudioChannelRegistry.Shared.TryClaimChannel(routing.Channel, handle, routing.ChannelMode, routing.AllowFadeOutOnReplace);
				}
				return true;
			}
			if (routing.ReplaceTaggedGroup && !AudioChannelRegistry.Shared.TryClearTag(routing.Tag, routing.AllowFadeOutOnReplace))
			{
				return false;
			}
			AudioChannelRegistry.Shared.AttachTag(routing.Tag, handle);
			if (!string.IsNullOrWhiteSpace(routing.Channel))
			{
				return AudioChannelRegistry.Shared.TryClaimChannel(routing.Channel, handle, routing.ChannelMode, routing.AllowFadeOutOnReplace);
			}
			return true;
		}

		private static AudioLifecycleScope ResolveScope(AudioPlaybackOptions options)
		{
			return options.ScopeToken?.Scope ?? options.Scope;
		}

		private static bool TryEnterCooldown(AudioSource source, AudioPlaybackOptions options)
		{
			if (options.CooldownMs <= 0 || (object)source == null)
			{
				return true;
			}
			return FmodPlaybackThrottle.TryEnter(options.DebugName ?? source.ToString() ?? source.GetType().Name, options.CooldownMs);
		}
	}
	/// <summary>
	///     <para xml:lang="en">Provides native-routed and handle-based entry points for FMOD playback.</para>
	///     <para xml:lang="zh-CN">提供使用原生路由和基于句柄的 FMOD 播放入口。</para>
	/// </summary>
	public static class GameFmod
	{
		/// <summary>
		///     <para xml:lang="en">Gets the <see cref="T:MegaCrit.Sts2.Core.Nodes.Audio.NAudioManager" />-routed API.</para>
		///     <para xml:lang="zh-CN">获取经由 <see cref="T:MegaCrit.Sts2.Core.Nodes.Audio.NAudioManager" /> 路由的 API。</para>
		/// </summary>
		public static IGameFmodAudio Studio => GameFmodAudioService.Shared;

		/// <summary>
		///     <para xml:lang="en">Gets the high-level playback API with typed handles, routing, and lifecycle scopes.</para>
		///     <para xml:lang="zh-CN">获取带有类型化句柄、路由和生命周期作用域的高级播放 API。</para>
		/// </summary>
		public static IGameAudio Playback => GameAudioService.Shared;
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Forwards the native-style audio surface to <see cref="T:MegaCrit.Sts2.Core.Nodes.Audio.NAudioManager" />, preserving the game's
	///         routing and runtime-mode checks.
	///     </para>
	///     <para xml:lang="zh-CN">将原生风格的音频接口转发到 <see cref="T:MegaCrit.Sts2.Core.Nodes.Audio.NAudioManager" />，保留游戏的路由与运行模式检查。</para>
	/// </summary>
	public sealed class GameFmodAudioService : IGameFmodAudio, IFmodOneShotPlayback, IFmodLoopPlayback, IFmodMusicPlayback, IFmodMixerVolumes
	{
		/// <summary>
		///     <para xml:lang="en">Gets the shared service provided by <see cref="P:STS2RitsuLib.Audio.GameFmod.Studio" />.</para>
		///     <para xml:lang="zh-CN">获取 <see cref="P:STS2RitsuLib.Audio.GameFmod.Studio" /> 提供的共享服务。</para>
		/// </summary>
		public static GameFmodAudioService Shared { get; } = new GameFmodAudioService();

		private static NAudioManager? Manager => NAudioManager.Instance;

		internal static bool IsAvailable => Manager != null;

		private GameFmodAudioService()
		{
		}

		/// <inheritdoc />
		public void PlayOneShot(string eventPath, float volume = 1f)
		{
			TryPlayOneShot(eventPath, volume);
		}

		/// <inheritdoc />
		public void PlayOneShot(string eventPath, IReadOnlyDictionary<string, float> parameters, float volume = 1f)
		{
			TryPlayOneShot(eventPath, parameters, volume);
		}

		/// <inheritdoc />
		public void PlayLoop(string eventPath, bool usesLoopParam = true)
		{
			NAudioManager? manager = Manager;
			if (manager != null)
			{
				manager.PlayLoop(eventPath, usesLoopParam);
			}
		}

		/// <inheritdoc />
		public void StopLoop(string eventPath)
		{
			NAudioManager? manager = Manager;
			if (manager != null)
			{
				manager.StopLoop(eventPath);
			}
		}

		/// <inheritdoc />
		public void SetLoopParameter(string eventPath, string parameterName, float value)
		{
			NAudioManager? manager = Manager;
			if (manager != null)
			{
				manager.SetParam(eventPath, parameterName, value);
			}
		}

		/// <inheritdoc />
		public void StopAllLoops()
		{
			NAudioManager? manager = Manager;
			if (manager != null)
			{
				manager.StopAllLoops();
			}
		}

		/// <inheritdoc />
		public void PlayMusic(string eventPath)
		{
			NAudioManager? manager = Manager;
			if (manager != null)
			{
				manager.PlayMusic(eventPath);
			}
		}

		/// <inheritdoc />
		public void StopMusic()
		{
			NAudioManager? manager = Manager;
			if (manager != null)
			{
				manager.StopMusic();
			}
		}

		/// <inheritdoc />
		public void UpdateMusicParameter(string parameterName, string labelValue)
		{
			NAudioManager? manager = Manager;
			if (manager != null)
			{
				manager.UpdateMusicParameter(parameterName, labelValue);
			}
		}

		/// <inheritdoc />
		public void SetMasterVolume(float linear01)
		{
			NAudioManager? manager = Manager;
			if (manager != null)
			{
				manager.SetMasterVol(linear01);
			}
		}

		/// <inheritdoc />
		public void SetSfxVolume(float linear01)
		{
			NAudioManager? manager = Manager;
			if (manager != null)
			{
				manager.SetSfxVol(linear01);
			}
		}

		/// <inheritdoc />
		public void SetAmbienceVolume(float linear01)
		{
			NAudioManager? manager = Manager;
			if (manager != null)
			{
				manager.SetAmbienceVol(linear01);
			}
		}

		/// <inheritdoc />
		public void SetBgmVolume(float linear01)
		{
			NAudioManager? manager = Manager;
			if (manager != null)
			{
				manager.SetBgmVol(linear01);
			}
		}

		internal bool TryPlayOneShot(string eventPath, float volume)
		{
			NAudioManager manager = Manager;
			if (manager == null)
			{
				return false;
			}
			manager.PlayOneShot(eventPath, volume);
			return true;
		}

		internal bool TryPlayOneShot(string eventPath, IReadOnlyDictionary<string, float> parameters, float volume)
		{
			NAudioManager manager = Manager;
			if (manager == null)
			{
				return false;
			}
			if (parameters.Count == 0)
			{
				manager.PlayOneShot(eventPath, volume);
				return true;
			}
			manager.PlayOneShot(eventPath, ToManagedDictionary(parameters), volume);
			return true;
		}

		private static Dictionary<string, float> ToManagedDictionary(IReadOnlyDictionary<string, float> parameters)
		{
			Dictionary<string, float> dictionary = new Dictionary<string, float>(parameters.Count);
			foreach (KeyValuePair<string, float> parameter in parameters)
			{
				dictionary[parameter.Key] = parameter.Value;
			}
			return dictionary;
		}
	}
	/// <summary>
	///     <para xml:lang="en">Represents caller-controllable playback backed by an FMOD object available through Godot.</para>
	///     <para xml:lang="zh-CN">表示由 Godot 提供的 FMOD 对象支撑、可由调用方控制的播放。</para>
	/// </summary>
	public interface IAudioHandle : IDisposable
	{
		/// <summary>
		///     <para xml:lang="en">Gets the logical source represented by this handle.</para>
		///     <para xml:lang="zh-CN">获取此句柄所代表的逻辑音频源。</para>
		/// </summary>
		AudioSource Source { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the built-in lifecycle scope recorded on this handle.</para>
		///     <para xml:lang="zh-CN">获取此句柄记录的内置生命周期作用域。</para>
		/// </summary>
		AudioLifecycleScope Scope { get; }

		/// <summary>
		///     <para xml:lang="en">Gets whether the handle is unreleased and its backend object reports a usable instance.</para>
		///     <para xml:lang="zh-CN">获取句柄是否尚未释放，且其后端对象是否报告实例可用。</para>
		/// </summary>
		bool IsValid { get; }

		/// <summary>
		///     <para xml:lang="en">Gets whether backend release has completed or the backend object was already invalid.</para>
		///     <para xml:lang="zh-CN">获取后端释放是否已完成，或后端对象是否原本已经无效。</para>
		/// </summary>
		bool IsReleased { get; }

		/// <summary>
		///     <para xml:lang="en">Gets the backend Godot object for advanced interop, or null after release.</para>
		///     <para xml:lang="zh-CN">获取用于高级互操作的后端 Godot 对象；释放后为 <see langword="null" />。</para>
		/// </summary>
		GodotObject? RawInstance { get; }

		/// <summary>
		///     <para xml:lang="en">Attempts to start playback through the backend's supported <c>play</c> or <c>start</c> method.</para>
		///     <para xml:lang="zh-CN">尝试通过后端支持的 <c>play</c> 或 <c>start</c> 方法开始播放。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when a supported start method completes; otherwise
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">受支持的启动方法执行完成时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		bool TryPlay();

		/// <summary>
		///     <para xml:lang="en">Attempts to stop playback using the call shape supported by the backend instance.</para>
		///     <para xml:lang="zh-CN">尝试使用后端实例支持的调用形式停止播放。</para>
		/// </summary>
		/// <param name="allowFadeOut">
		///     <para xml:lang="en">Whether an FMOD event instance may fade out; file-backed instances ignore this value.</para>
		///     <para xml:lang="zh-CN">FMOD 事件实例是否可以淡出；文件型实例会忽略此值。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when the supported stop method completes; otherwise
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">受支持的停止方法执行完成时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		bool TryStop(bool allowFadeOut = true);

		/// <summary>
		///     <para xml:lang="en">Attempts to pause playback through <c>set_paused</c>.</para>
		///     <para xml:lang="zh-CN">尝试通过 <c>set_paused</c> 暂停播放。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when the backend supports and completes the call; otherwise
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">后端支持且完成该调用时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		bool TryPause();

		/// <summary>
		///     <para xml:lang="en">Attempts to resume playback through <c>set_paused</c>.</para>
		///     <para xml:lang="zh-CN">尝试通过 <c>set_paused</c> 恢复播放。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when the backend supports and completes the call; otherwise
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">后端支持且完成该调用时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		bool TryResume();

		/// <summary>
		///     <para xml:lang="en">Attempts to set the backend instance's linear volume value.</para>
		///     <para xml:lang="zh-CN">尝试设置后端实例的线性音量值。</para>
		/// </summary>
		/// <param name="volume">
		///     <para xml:lang="en">The volume value passed to the backend.</para>
		///     <para xml:lang="zh-CN">传递给后端的音量值。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when the backend supports and completes the call; otherwise
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">后端支持且完成该调用时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		bool TrySetVolume(float volume);

		/// <summary>
		///     <para xml:lang="en">Attempts to set the backend instance's pitch multiplier.</para>
		///     <para xml:lang="zh-CN">尝试设置后端实例的音高倍率。</para>
		/// </summary>
		/// <param name="pitch">
		///     <para xml:lang="en">The pitch value passed to the backend.</para>
		///     <para xml:lang="zh-CN">传递给后端的音高值。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when the backend supports and completes the call; otherwise
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">后端支持且完成该调用时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		bool TrySetPitch(float pitch);

		/// <summary>
		///     <para xml:lang="en">Attempts to set a numeric FMOD event parameter by name.</para>
		///     <para xml:lang="zh-CN">尝试按名称设置数值型 FMOD 事件参数。</para>
		/// </summary>
		/// <param name="name">
		///     <para xml:lang="en">The FMOD parameter name.</para>
		///     <para xml:lang="zh-CN">FMOD 参数名称。</para>
		/// </param>
		/// <param name="value">
		///     <para xml:lang="en">The parameter value.</para>
		///     <para xml:lang="zh-CN">参数值。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when the backend supports and completes the call; otherwise
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">后端支持且完成该调用时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		bool TrySetParameter(string name, float value);

		/// <summary>
		///     <para xml:lang="en">Attempts to release backend resources and detach registry ownership.</para>
		///     <para xml:lang="zh-CN">尝试释放后端资源并解除注册表归属。</para>
		/// </summary>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when resources are released or the backend was already invalid;
		///         otherwise <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">资源已释放或后端原本已无效时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		bool TryRelease();
	}
	/// <summary>
	///     <para xml:lang="en">Controls path-keyed looping events through the game's native loop queue.</para>
	///     <para xml:lang="zh-CN">通过游戏的原生循环队列控制按路径分组的循环事件。</para>
	/// </summary>
	public interface IFmodLoopPlayback
	{
		/// <summary>
		///     <para xml:lang="en">Creates and starts another loop instance under an event path.</para>
		///     <para xml:lang="zh-CN">在事件路径下创建并启动另一个循环实例。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The FMOD Studio event path.</para>
		///     <para xml:lang="zh-CN">FMOD Studio 事件路径。</para>
		/// </param>
		/// <param name="usesLoopParam">
		///     <para xml:lang="en">Whether stopping uses the game's <c>loop = 1</c> convention instead of an immediate event stop.</para>
		///     <para xml:lang="zh-CN">停止时是否使用游戏的 <c>loop = 1</c> 约定，而不是立即停止事件。</para>
		/// </param>
		void PlayLoop(string eventPath, bool usesLoopParam = true);

		/// <summary>
		///     <para xml:lang="en">Stops the oldest queued loop instance under an event path.</para>
		///     <para xml:lang="zh-CN">停止事件路径下队列中最早的循环实例。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The FMOD Studio event path used to group the loop.</para>
		///     <para xml:lang="zh-CN">用于对循环分组的 FMOD Studio 事件路径。</para>
		/// </param>
		void StopLoop(string eventPath);

		/// <summary>
		///     <para xml:lang="en">Sets a numeric parameter on the oldest queued loop instance under an event path.</para>
		///     <para xml:lang="zh-CN">为事件路径下队列中最早的循环实例设置数值参数。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The FMOD Studio event path used to find the loop.</para>
		///     <para xml:lang="zh-CN">用于查找循环的 FMOD Studio 事件路径。</para>
		/// </param>
		/// <param name="parameterName">
		///     <para xml:lang="en">The FMOD parameter name.</para>
		///     <para xml:lang="zh-CN">FMOD 参数名称。</para>
		/// </param>
		/// <param name="value">
		///     <para xml:lang="en">The numeric parameter value.</para>
		///     <para xml:lang="zh-CN">数值参数值。</para>
		/// </param>
		void SetLoopParameter(string eventPath, string parameterName, float value);

		/// <summary>
		///     <para xml:lang="en">Stops every loop instance currently held by the game's native loop queue.</para>
		///     <para xml:lang="zh-CN">停止游戏原生循环队列当前持有的所有循环实例。</para>
		/// </summary>
		void StopAllLoops();
	}
	/// <summary>
	///     <para xml:lang="en">Applies the game's squared settings-volume curve to its native FMOD buses.</para>
	///     <para xml:lang="zh-CN">将游戏设置使用的平方音量曲线应用到原生 FMOD 总线。</para>
	/// </summary>
	public interface IFmodMixerVolumes
	{
		/// <summary>
		///     <para xml:lang="en">Sets the master-bus volume from a settings-scale input.</para>
		///     <para xml:lang="zh-CN">根据设置刻度输入设置主总线音量。</para>
		/// </summary>
		/// <param name="linear01">
		///     <para xml:lang="en">The unclamped input, normally from 0 to 1; the game squares it before writing the bus volume.</para>
		///     <para xml:lang="zh-CN">通常为 0 到 1 的未钳制输入；游戏会先对其平方，再写入总线音量。</para>
		/// </param>
		void SetMasterVolume(float linear01);

		/// <summary>
		///     <para xml:lang="en">Sets the sound-effects-bus volume from a settings-scale input.</para>
		///     <para xml:lang="zh-CN">根据设置刻度输入设置音效总线音量。</para>
		/// </summary>
		/// <param name="linear01">
		///     <para xml:lang="en">The unclamped input, normally from 0 to 1; the game squares it before writing the bus volume.</para>
		///     <para xml:lang="zh-CN">通常为 0 到 1 的未钳制输入；游戏会先对其平方，再写入总线音量。</para>
		/// </param>
		void SetSfxVolume(float linear01);

		/// <summary>
		///     <para xml:lang="en">Sets the ambience-bus volume from a settings-scale input.</para>
		///     <para xml:lang="zh-CN">根据设置刻度输入设置环境音总线音量。</para>
		/// </summary>
		/// <param name="linear01">
		///     <para xml:lang="en">The unclamped input, normally from 0 to 1; the game squares it before writing the bus volume.</para>
		///     <para xml:lang="zh-CN">通常为 0 到 1 的未钳制输入；游戏会先对其平方，再写入总线音量。</para>
		/// </param>
		void SetAmbienceVolume(float linear01);

		/// <summary>
		///     <para xml:lang="en">Sets the music-bus volume from a settings-scale input.</para>
		///     <para xml:lang="zh-CN">根据设置刻度输入设置音乐总线音量。</para>
		/// </summary>
		/// <param name="linear01">
		///     <para xml:lang="en">The unclamped input, normally from 0 to 1; the game squares it before writing the bus volume.</para>
		///     <para xml:lang="zh-CN">通常为 0 到 1 的未钳制输入；游戏会先对其平方，再写入总线音量。</para>
		/// </param>
		void SetBgmVolume(float linear01);
	}
	/// <summary>
	///     <para xml:lang="en">Controls the single music instance owned by the game's native audio proxy.</para>
	///     <para xml:lang="zh-CN">控制游戏原生音频代理持有的单个音乐实例。</para>
	/// </summary>
	public interface IFmodMusicPlayback
	{
		/// <summary>
		///     <para xml:lang="en">Starts a valid path-based music event after stopping the current one.</para>
		///     <para xml:lang="zh-CN">停止当前音乐后，启动有效的路径型音乐事件。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The FMOD Studio music-event path.</para>
		///     <para xml:lang="zh-CN">FMOD Studio 音乐事件路径。</para>
		/// </param>
		void PlayMusic(string eventPath);

		/// <summary>
		///     <para xml:lang="en">Stops and releases the current native music instance, if any.</para>
		///     <para xml:lang="zh-CN">停止并释放当前原生音乐实例（如果存在）。</para>
		/// </summary>
		void StopMusic();

		/// <summary>
		///     <para xml:lang="en">Sets a labeled parameter on the current native music instance.</para>
		///     <para xml:lang="zh-CN">为当前原生音乐实例设置标签型参数。</para>
		/// </summary>
		/// <param name="parameterName">
		///     <para xml:lang="en">The FMOD parameter name.</para>
		///     <para xml:lang="zh-CN">FMOD 参数名称。</para>
		/// </param>
		/// <param name="labelValue">
		///     <para xml:lang="en">The FMOD parameter label.</para>
		///     <para xml:lang="zh-CN">FMOD 参数标签。</para>
		/// </param>
		void UpdateMusicParameter(string parameterName, string labelValue);
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Plays FMOD Studio one-shots through the game's
	///         <see cref="T:MegaCrit.Sts2.Core.Nodes.Audio.NAudioManager" /> route.
	///     </para>
	///     <para xml:lang="zh-CN">通过游戏的 <see cref="T:MegaCrit.Sts2.Core.Nodes.Audio.NAudioManager" /> 路由播放 FMOD Studio 单次事件。</para>
	/// </summary>
	public interface IFmodOneShotPlayback
	{
		/// <summary>
		///     <para xml:lang="en">Plays a path-based event once at the supplied linear volume.</para>
		///     <para xml:lang="zh-CN">以指定的线性音量单次播放路径型事件。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The FMOD Studio event path resolved by the game's audio proxy.</para>
		///     <para xml:lang="zh-CN">由游戏音频代理解析的 FMOD Studio 事件路径。</para>
		/// </param>
		/// <param name="volume">
		///     <para xml:lang="en">The unclamped linear instance volume.</para>
		///     <para xml:lang="zh-CN">未钳制的实例线性音量。</para>
		/// </param>
		void PlayOneShot(string eventPath, float volume = 1f);

		/// <summary>
		///     <para xml:lang="en">Plays a path-based event once with initial numeric parameters and linear volume.</para>
		///     <para xml:lang="zh-CN">使用初始数值参数和线性音量单次播放路径型事件。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The FMOD Studio event path resolved by the game's audio proxy.</para>
		///     <para xml:lang="zh-CN">由游戏音频代理解析的 FMOD Studio 事件路径。</para>
		/// </param>
		/// <param name="parameters">
		///     <para xml:lang="en">The initial parameter values; the native proxy skips names absent from the event description.</para>
		///     <para xml:lang="zh-CN">初始参数值；原生代理会跳过事件描述中不存在的参数名。</para>
		/// </param>
		/// <param name="volume">
		///     <para xml:lang="en">The unclamped linear instance volume.</para>
		///     <para xml:lang="zh-CN">未钳制的实例线性音量。</para>
		/// </param>
		void PlayOneShot(string eventPath, IReadOnlyDictionary<string, float> parameters, float volume = 1f);
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides typed playback, handle-based control, lifecycle ownership, routing, and adaptive
	///         music.
	///     </para>
	///     <para xml:lang="zh-CN">提供类型化播放、基于句柄的控制、生命周期归属、路由和自适应音乐。</para>
	/// </summary>
	public interface IGameAudio
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Dispatches a supported source and reports whether backend creation and requested initialization
		///         completed.
		///     </para>
		///     <para xml:lang="zh-CN">分派受支持的音频源，并报告后端创建及所请求的初始化是否完成。</para>
		/// </summary>
		/// <param name="source">
		///     <para xml:lang="en">The typed audio source to play.</para>
		///     <para xml:lang="zh-CN">要播放的类型化音频源。</para>
		/// </param>
		/// <param name="options">
		///     <para xml:lang="en">Optional initial values, lifecycle ownership, cooldown, and routing rules.</para>
		///     <para xml:lang="zh-CN">可选的初始值、生命周期归属、冷却和路由规则。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The structured playback result, including a controllable handle when that route creates one.</para>
		///     <para xml:lang="zh-CN">结构化播放结果；所选路径创建可控制句柄时，结果中会包含该句柄。</para>
		/// </returns>
		AudioPlayResult Play(AudioSource source, AudioPlaybackOptions? options = null);

		/// <summary>
		///     <para xml:lang="en">Plays a Studio event or fully loaded sound-file source once.</para>
		///     <para xml:lang="zh-CN">单次播放 Studio 事件或完整加载的声音文件源。</para>
		/// </summary>
		/// <param name="source">
		///     <para xml:lang="en">A Studio path, Studio GUID, absolute sound file, or Godot-resource sound file.</para>
		///     <para xml:lang="zh-CN">Studio 路径、Studio GUID、绝对路径声音文件或 Godot 资源声音文件。</para>
		/// </param>
		/// <param name="options">
		///     <para xml:lang="en">
		///         Optional playback settings. A path-based Studio event uses the native manager when
		///         <see cref="P:STS2RitsuLib.Audio.AudioPlaybackOptions.UseVanillaRouting" /> is enabled.
		///     </para>
		///     <para xml:lang="zh-CN">可选的播放设置。启用 <see cref="P:STS2RitsuLib.Audio.AudioPlaybackOptions.UseVanillaRouting" /> 时，路径型 Studio 事件使用原生管理器。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         The playback result; unsupported source kinds return
		///         <see cref="F:STS2RitsuLib.Audio.AudioPlayStatus.NotSupported" />.
		///     </para>
		///     <para xml:lang="zh-CN">播放结果；不受支持的音频源类型返回 <see cref="F:STS2RitsuLib.Audio.AudioPlayStatus.NotSupported" />。</para>
		/// </returns>
		AudioPlayResult PlayOneShot(AudioSource source, AudioPlaybackOptions? options = null);

		/// <summary>
		///     <para xml:lang="en">Plays a Studio event or streaming-music source as a controllable loop.</para>
		///     <para xml:lang="zh-CN">将 Studio 事件或流式音乐源作为可控制循环播放。</para>
		/// </summary>
		/// <param name="source">
		///     <para xml:lang="en">The loop-capable source.</para>
		///     <para xml:lang="zh-CN">支持循环的音频源。</para>
		/// </param>
		/// <param name="options">
		///     <para xml:lang="en">Optional initial values, lifecycle ownership, cooldown, and routing rules.</para>
		///     <para xml:lang="zh-CN">可选的初始值、生命周期归属、冷却和路由规则。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The initialized loop handle, or null when the source is unsupported or playback fails.</para>
		///     <para xml:lang="zh-CN">已初始化的循环句柄；音频源不受支持或播放失败时为 <see langword="null" />。</para>
		/// </returns>
		AudioLoopHandle? PlayLoop(AudioSource source, AudioPlaybackOptions? options = null);

		/// <summary>
		///     <para xml:lang="en">Plays a Studio event or streaming-music source through a controllable music handle.</para>
		///     <para xml:lang="zh-CN">通过可控制的音乐句柄播放 Studio 事件或流式音乐源。</para>
		/// </summary>
		/// <param name="source">
		///     <para xml:lang="en">The music-capable source.</para>
		///     <para xml:lang="zh-CN">支持音乐播放的音频源。</para>
		/// </param>
		/// <param name="options">
		///     <para xml:lang="en">Optional initial values, lifecycle ownership, cooldown, and routing rules.</para>
		///     <para xml:lang="zh-CN">可选的初始值、生命周期归属、冷却和路由规则。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">The initialized music handle, or null when the source is unsupported or playback fails.</para>
		///     <para xml:lang="zh-CN">已初始化的音乐句柄；音频源不受支持或播放失败时为 <see langword="null" />。</para>
		/// </returns>
		AudioMusicHandle? PlayMusic(AudioSource source, AudioPlaybackOptions? options = null);

		/// <summary>
		///     <para xml:lang="en">Attaches an adaptive music plan to room, combat, and victory lifecycle transitions.</para>
		///     <para xml:lang="zh-CN">将自适应音乐方案附加到房间、战斗和胜利生命周期转换。</para>
		/// </summary>
		/// <param name="plan">
		///     <para xml:lang="en">The adaptive music plan to follow.</para>
		///     <para xml:lang="zh-CN">要遵循的自适应音乐方案。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A caller-owned handle that controls the attached plan.</para>
		///     <para xml:lang="zh-CN">用于控制已附加方案、由调用方持有的句柄。</para>
		/// </returns>
		AudioAdaptiveMusicHandle FollowAdaptiveMusic(AudioAdaptiveMusicPlan plan);

		/// <summary>
		///     <para xml:lang="en">Creates a caller-owned token for grouping playback and retryable cleanup.</para>
		///     <para xml:lang="zh-CN">创建由调用方持有的令牌，用于对播放分组并执行可重试清理。</para>
		/// </summary>
		/// <param name="name">
		///     <para xml:lang="en">The display name recorded on the token.</para>
		///     <para xml:lang="zh-CN">记录在令牌上的显示名称。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">A new manual lifecycle token.</para>
		///     <para xml:lang="zh-CN">新的手动生命周期令牌。</para>
		/// </returns>
		AudioScopeToken CreateManualScope(string name);

		/// <summary>
		///     <para xml:lang="en">Attempts to stop and release every handle attached to a manual scope token.</para>
		///     <para xml:lang="zh-CN">尝试停止并释放附加到手动作用域令牌的所有句柄。</para>
		/// </summary>
		/// <param name="scope">
		///     <para xml:lang="en">The manual scope token to clean up.</para>
		///     <para xml:lang="zh-CN">要清理的手动作用域令牌。</para>
		/// </param>
		/// <param name="allowFadeOut">
		///     <para xml:lang="en">Whether stopped event handles may fade out.</para>
		///     <para xml:lang="zh-CN">停止事件句柄时是否允许淡出。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when at least one handle was found and every release completed;
		///         otherwise <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">找到至少一个句柄且所有释放均已完成时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		bool StopScope(AudioScopeToken scope, bool allowFadeOut = true);

		/// <summary>
		///     <para xml:lang="en">Attempts to stop and release the current owner of a named channel.</para>
		///     <para xml:lang="zh-CN">尝试停止并释放命名通道的当前占用者。</para>
		/// </summary>
		/// <param name="channel">
		///     <para xml:lang="en">The case-sensitive channel name.</para>
		///     <para xml:lang="zh-CN">区分大小写的通道名称。</para>
		/// </param>
		/// <param name="allowFadeOut">
		///     <para xml:lang="en">Whether the stopped event handle may fade out.</para>
		///     <para xml:lang="zh-CN">停止事件句柄时是否允许淡出。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when an owner was found and released; otherwise
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">找到并释放占用者时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		bool StopChannel(string channel, bool allowFadeOut = true);

		/// <summary>
		///     <para xml:lang="en">Attempts to stop and release every handle attached to a tag group.</para>
		///     <para xml:lang="zh-CN">尝试停止并释放附加到标签组的所有句柄。</para>
		/// </summary>
		/// <param name="tag">
		///     <para xml:lang="en">The case-sensitive tag name.</para>
		///     <para xml:lang="zh-CN">区分大小写的标签名称。</para>
		/// </param>
		/// <param name="allowFadeOut">
		///     <para xml:lang="en">Whether stopped event handles may fade out.</para>
		///     <para xml:lang="zh-CN">停止事件句柄时是否允许淡出。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when at least one handle was found and every release completed;
		///         otherwise <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">找到至少一个句柄且所有释放均已完成时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		bool StopTag(string tag, bool allowFadeOut = true);
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Combines the mod-facing playback and mixer operations routed through
	///         <see cref="T:MegaCrit.Sts2.Core.Nodes.Audio.NAudioManager" />.
