	///     <para xml:lang="zh-CN">组合经由 <see cref="T:MegaCrit.Sts2.Core.Nodes.Audio.NAudioManager" /> 路由、面向模组的播放与混音操作。</para>
	/// </summary>
	public interface IGameFmodAudio : IFmodOneShotPlayback, IFmodLoopPlayback, IFmodMusicPlayback, IFmodMixerVolumes
	{
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Provides sound-effect helpers with the same non-interactive and combat-ending guards as
	///         <see cref="T:MegaCrit.Sts2.Core.Commands.SfxCmd" />.
	///     </para>
	///     <para xml:lang="zh-CN">提供与 <see cref="T:MegaCrit.Sts2.Core.Commands.SfxCmd" /> 相同、受非交互状态和战斗结束状态保护的音效辅助方法。</para>
	/// </summary>
	public static class Sts2SfxAlignedFmod
	{
		/// <summary>
		///     <para xml:lang="en">Plays a guarded one-shot through <see cref="M:MegaCrit.Sts2.Core.Commands.SfxCmd.Play(System.String,System.Single)" />.</para>
		///     <para xml:lang="zh-CN">通过 <see cref="M:MegaCrit.Sts2.Core.Commands.SfxCmd.Play(System.String,System.Single)" /> 播放受保护的单次音效。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The FMOD Studio event path.</para>
		///     <para xml:lang="zh-CN">FMOD Studio 事件路径。</para>
		/// </param>
		/// <param name="volume">
		///     <para xml:lang="en">The unclamped linear instance volume.</para>
		///     <para xml:lang="zh-CN">未钳制的实例线性音量。</para>
		/// </param>
		public static void PlayOneShot(string eventPath, float volume = 1f)
		{
			SfxCmd.Play(eventPath, volume);
		}

		/// <summary>
		///     <para xml:lang="en">Plays a guarded one-shot with one initial numeric parameter through <see cref="T:MegaCrit.Sts2.Core.Commands.SfxCmd" />.</para>
		///     <para xml:lang="zh-CN">通过 <see cref="T:MegaCrit.Sts2.Core.Commands.SfxCmd" /> 播放带一个初始数值参数的受保护单次音效。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The FMOD Studio event path.</para>
		///     <para xml:lang="zh-CN">FMOD Studio 事件路径。</para>
		/// </param>
		/// <param name="parameterName">
		///     <para xml:lang="en">The initial FMOD parameter name.</para>
		///     <para xml:lang="zh-CN">初始 FMOD 参数名称。</para>
		/// </param>
		/// <param name="parameterValue">
		///     <para xml:lang="en">The initial parameter value.</para>
		///     <para xml:lang="zh-CN">初始参数值。</para>
		/// </param>
		/// <param name="volume">
		///     <para xml:lang="en">The unclamped linear instance volume.</para>
		///     <para xml:lang="zh-CN">未钳制的实例线性音量。</para>
		/// </param>
		public static void PlayOneShot(string eventPath, string parameterName, float parameterValue, float volume = 1f)
		{
			SfxCmd.Play(eventPath, parameterName, parameterValue, volume);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Plays a parameterized one-shot through <see cref="P:STS2RitsuLib.Audio.GameFmod.Studio" /> after applying the same
		///         guards as <see cref="M:MegaCrit.Sts2.Core.Commands.SfxCmd.Play(System.String,System.Single)" />.
		///     </para>
		///     <para xml:lang="zh-CN">
		///         应用与 <see cref="M:MegaCrit.Sts2.Core.Commands.SfxCmd.Play(System.String,System.Single)" /> 相同的保护条件后，通过 <see cref="P:STS2RitsuLib.Audio.GameFmod.Studio" />
		///         播放带参数的单次音效。
		///     </para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The FMOD Studio event path.</para>
		///     <para xml:lang="zh-CN">FMOD Studio 事件路径。</para>
		/// </param>
		/// <param name="parameters">
		///     <para xml:lang="en">The initial numeric parameter values.</para>
		///     <para xml:lang="zh-CN">初始数值参数。</para>
		/// </param>
		/// <param name="volume">
		///     <para xml:lang="en">The unclamped linear instance volume.</para>
		///     <para xml:lang="zh-CN">未钳制的实例线性音量。</para>
		/// </param>
		public static void PlayOneShot(string eventPath, IReadOnlyDictionary<string, float> parameters, float volume = 1f)
		{
			if (!NonInteractiveMode.IsActive && !CombatManager.Instance.IsEnding)
			{
				GameFmod.Studio.PlayOneShot(eventPath, parameters, volume);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Starts a loop through <see cref="M:MegaCrit.Sts2.Core.Commands.SfxCmd.PlayLoop(System.String,System.Boolean)" />, which skips playback in
		///         non-interactive mode.
		///     </para>
		///     <para xml:lang="zh-CN">通过 <see cref="M:MegaCrit.Sts2.Core.Commands.SfxCmd.PlayLoop(System.String,System.Boolean)" /> 启动循环；非交互模式下会跳过播放。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The FMOD Studio event path.</para>
		///     <para xml:lang="zh-CN">FMOD Studio 事件路径。</para>
		/// </param>
		/// <param name="usesLoopParam">
		///     <para xml:lang="en">Whether stopping uses the game's <c>loop = 1</c> convention.</para>
		///     <para xml:lang="zh-CN">停止时是否使用游戏的 <c>loop = 1</c> 约定。</para>
		/// </param>
		public static void PlayLoop(string eventPath, bool usesLoopParam = true)
		{
			SfxCmd.PlayLoop(eventPath, usesLoopParam);
		}

		/// <summary>
		///     <para xml:lang="en">Stops the oldest loop under an event path through <see cref="M:MegaCrit.Sts2.Core.Commands.SfxCmd.StopLoop(System.String)" />.</para>
		///     <para xml:lang="zh-CN">通过 <see cref="M:MegaCrit.Sts2.Core.Commands.SfxCmd.StopLoop(System.String)" /> 停止事件路径下最早的循环。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The FMOD Studio event path used to group the loop.</para>
		///     <para xml:lang="zh-CN">用于对循环分组的 FMOD Studio 事件路径。</para>
		/// </param>
		public static void StopLoop(string eventPath)
		{
			SfxCmd.StopLoop(eventPath);
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Sets a numeric parameter on the oldest loop under an event path through
		///         <see cref="M:MegaCrit.Sts2.Core.Commands.SfxCmd.SetParam(System.String,System.String,System.Single)" />.
		///     </para>
		///     <para xml:lang="zh-CN">通过 <see cref="M:MegaCrit.Sts2.Core.Commands.SfxCmd.SetParam(System.String,System.String,System.Single)" /> 为事件路径下最早的循环设置数值参数。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The FMOD Studio event path used to find the loop.</para>
		///     <para xml:lang="zh-CN">用于查找循环的 FMOD Studio 事件路径。</para>
		/// </param>
		/// <param name="parameterName">
		///     <para xml:lang="en">The FMOD parameter name.</para>
		///     <para xml:lang="zh-CN">FMOD 参数名称。</para>
		/// </param>
		/// <param name="value">
		///     <para xml:lang="en">The numeric parameter value.</para>
		///     <para xml:lang="zh-CN">数值参数值。</para>
		/// </param>
		public static void SetLoopParameter(string eventPath, string parameterName, float value)
		{
			SfxCmd.SetParam(eventPath, parameterName, value);
		}
	}
	/// <summary>
	///     <para xml:lang="en">
	///         Maps FMOD-style event paths to Godot audio resources for compatibility with native game call sites. Virtual
	///         events use RitsuLib file playback and lifecycle tracking, but are not Studio events and do not join the FMOD
	///         DSP graph or follow later bus-volume changes.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         将 FMOD 风格的事件路径映射到 Godot 音频资源，以兼容游戏的原生调用位置。虚拟事件使用 RitsuLib
	///         的文件播放和生命周期跟踪，但不属于 Studio 事件，也不会加入 FMOD DSP 图或跟随之后的总线音量变化。
	///     </para>
	/// </summary>
	public static class VirtualFmodEventRegistry
	{
		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<string, VirtualFmodEventDefinition> Definitions = new Dictionary<string, VirtualFmodEventDefinition>(StringComparer.Ordinal);

		private static readonly Dictionary<string, int> VariantIndexes = new Dictionary<string, int>(StringComparer.Ordinal);

		private static readonly Dictionary<string, Queue<IAudioHandle>> Loops = new Dictionary<string, Queue<IAudioHandle>>(StringComparer.Ordinal);

		private static IAudioHandle? _music;

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a one-shot event backed by one Godot audio resource.</para>
		///     <para xml:lang="zh-CN">注册或替换由单个 Godot 音频资源支撑的单次事件。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The case-sensitive virtual event path.</para>
		///     <para xml:lang="zh-CN">区分大小写的虚拟事件路径。</para>
		/// </param>
		/// <param name="resourcePath">
		///     <para xml:lang="en">The packed, imported, or raw Godot audio-resource path.</para>
		///     <para xml:lang="zh-CN">打包、导入或原始 Godot 音频资源路径。</para>
		/// </param>
		/// <param name="busPath">
		///     <para xml:lang="en">The bus whose current volume is sampled when playback starts.</para>
		///     <para xml:lang="zh-CN">开始播放时采样当前音量的总线路径。</para>
		/// </param>
		/// <param name="volume">
		///     <para xml:lang="en">The finite, non-negative event-volume multiplier.</para>
		///     <para xml:lang="zh-CN">有限且非负的事件音量倍率。</para>
		/// </param>
		/// <param name="pitch">
		///     <para xml:lang="en">The finite, positive pitch multiplier.</para>
		///     <para xml:lang="zh-CN">有限且为正的音高倍率。</para>
		/// </param>
		public static void RegisterOneShot(string eventPath, string resourcePath, string busPath = "bus:/master/sfx", float volume = 1f, float pitch = 1f)
		{
			Register(new VirtualFmodEventDefinition(eventPath, resourcePath, VirtualFmodEventKind.OneShot, busPath, volume, pitch));
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces one-shot events from an event-path-to-resource-path map.</para>
		///     <para xml:lang="zh-CN">根据事件路径到资源路径的映射注册或替换多个单次事件。</para>
		/// </summary>
		/// <param name="eventResourcePaths">
		///     <para xml:lang="en">The case-sensitive event paths and their Godot audio resources.</para>
		///     <para xml:lang="zh-CN">区分大小写的事件路径及其 Godot 音频资源。</para>
		/// </param>
		/// <param name="busPath">
		///     <para xml:lang="en">The bus whose current volume is sampled for each playback.</para>
		///     <para xml:lang="zh-CN">每次播放时采样当前音量的总线路径。</para>
		/// </param>
		/// <param name="volume">
		///     <para xml:lang="en">The finite, non-negative event-volume multiplier.</para>
		///     <para xml:lang="zh-CN">有限且非负的事件音量倍率。</para>
		/// </param>
		/// <param name="pitch">
		///     <para xml:lang="en">The finite, positive pitch multiplier.</para>
		///     <para xml:lang="zh-CN">有限且为正的音高倍率。</para>
		/// </param>
		public static void RegisterOneShots(IReadOnlyDictionary<string, string> eventResourcePaths, string busPath = "bus:/master/sfx", float volume = 1f, float pitch = 1f)
		{
			ArgumentNullException.ThrowIfNull(eventResourcePaths, "eventResourcePaths");
			foreach (var (eventPath, resourcePath) in eventResourcePaths)
			{
				RegisterOneShot(eventPath, resourcePath, busPath, volume, pitch);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a one-shot event backed by multiple resource variants.</para>
		///     <para xml:lang="zh-CN">注册或替换由多个资源变体支撑的单次事件。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The case-sensitive virtual event path.</para>
		///     <para xml:lang="zh-CN">区分大小写的虚拟事件路径。</para>
		/// </param>
		/// <param name="resourcePaths">
		///     <para xml:lang="en">The non-empty variant list, copied in enumeration order.</para>
		///     <para xml:lang="zh-CN">非空的变体列表；注册时按枚举顺序复制。</para>
		/// </param>
		/// <param name="selection">
		///     <para xml:lang="en">How a resource is selected for each playback.</para>
		///     <para xml:lang="zh-CN">每次播放时选择资源的方式。</para>
		/// </param>
		/// <param name="busPath">
		///     <para xml:lang="en">The bus whose current volume is sampled when playback starts.</para>
		///     <para xml:lang="zh-CN">开始播放时采样当前音量的总线路径。</para>
		/// </param>
		/// <param name="volume">
		///     <para xml:lang="en">The finite, non-negative event-volume multiplier.</para>
		///     <para xml:lang="zh-CN">有限且非负的事件音量倍率。</para>
		/// </param>
		/// <param name="pitch">
		///     <para xml:lang="en">The finite, positive pitch multiplier.</para>
		///     <para xml:lang="zh-CN">有限且为正的音高倍率。</para>
		/// </param>
		public static void RegisterOneShotVariants(string eventPath, IReadOnlyList<string> resourcePaths, VirtualFmodVariantSelection selection = VirtualFmodVariantSelection.Random, string busPath = "bus:/master/sfx", float volume = 1f, float pitch = 1f)
		{
			if (!Enum.IsDefined(selection))
			{
				throw new ArgumentOutOfRangeException("selection", selection, null);
			}
			IReadOnlyList<string> readOnlyList = ValidateResourcePaths(resourcePaths, "resourcePaths");
			Register(new VirtualFmodEventDefinition(eventPath, readOnlyList[0], VirtualFmodEventKind.OneShot, busPath, volume, pitch)
			{
				ResourcePaths = readOnlyList,
				VariantSelection = selection
			});
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces variant-backed one-shot events from a map.</para>
		///     <para xml:lang="zh-CN">根据映射注册或替换多个由变体支撑的单次事件。</para>
		/// </summary>
		/// <param name="eventResourcePaths">
		///     <para xml:lang="en">The case-sensitive event paths and their non-empty resource-variant lists.</para>
		///     <para xml:lang="zh-CN">区分大小写的事件路径及其非空资源变体列表。</para>
		/// </param>
		/// <param name="selection">
		///     <para xml:lang="en">How a resource is selected for each playback.</para>
		///     <para xml:lang="zh-CN">每次播放时选择资源的方式。</para>
		/// </param>
		/// <param name="busPath">
		///     <para xml:lang="en">The bus whose current volume is sampled for each playback.</para>
		///     <para xml:lang="zh-CN">每次播放时采样当前音量的总线路径。</para>
		/// </param>
		/// <param name="volume">
		///     <para xml:lang="en">The finite, non-negative event-volume multiplier.</para>
		///     <para xml:lang="zh-CN">有限且非负的事件音量倍率。</para>
		/// </param>
		/// <param name="pitch">
		///     <para xml:lang="en">The finite, positive pitch multiplier.</para>
		///     <para xml:lang="zh-CN">有限且为正的音高倍率。</para>
		/// </param>
		public static void RegisterOneShotVariants(IReadOnlyDictionary<string, IReadOnlyList<string>> eventResourcePaths, VirtualFmodVariantSelection selection = VirtualFmodVariantSelection.Random, string busPath = "bus:/master/sfx", float volume = 1f, float pitch = 1f)
		{
			ArgumentNullException.ThrowIfNull(eventResourcePaths, "eventResourcePaths");
			foreach (var (eventPath, resourcePaths) in eventResourcePaths)
			{
				RegisterOneShotVariants(eventPath, resourcePaths, selection, busPath, volume, pitch);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a streaming loop event backed by a Godot audio resource.</para>
		///     <para xml:lang="zh-CN">注册或替换由 Godot 音频资源支撑的流式循环事件。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The case-sensitive virtual event path.</para>
		///     <para xml:lang="zh-CN">区分大小写的虚拟事件路径。</para>
		/// </param>
		/// <param name="resourcePath">
		///     <para xml:lang="en">The packed, imported, or raw Godot audio-resource path.</para>
		///     <para xml:lang="zh-CN">打包、导入或原始 Godot 音频资源路径。</para>
		/// </param>
		/// <param name="busPath">
		///     <para xml:lang="en">The bus whose current volume is sampled when playback starts.</para>
		///     <para xml:lang="zh-CN">开始播放时采样当前音量的总线路径。</para>
		/// </param>
		/// <param name="volume">
		///     <para xml:lang="en">The finite, non-negative event-volume multiplier.</para>
		///     <para xml:lang="zh-CN">有限且非负的事件音量倍率。</para>
		/// </param>
		/// <param name="pitch">
		///     <para xml:lang="en">The finite, positive pitch multiplier.</para>
		///     <para xml:lang="zh-CN">有限且为正的音高倍率。</para>
		/// </param>
		/// <param name="stream">
		///     <para xml:lang="en">
		///         Must be <see langword="true" /> because the bundled backend supports looping only for streaming
		///         music files.
		///     </para>
		///     <para xml:lang="zh-CN">必须为 <see langword="true" />，因为随游戏提供的后端仅支持流式音乐文件循环播放。</para>
		/// </param>
		/// <exception cref="T:System.ArgumentException">
		///     <para xml:lang="en">
		///         Thrown when <paramref name="stream" /> is <see langword="false" /> or another definition value
		///         is invalid.
		///     </para>
		///     <para xml:lang="zh-CN">当 <paramref name="stream" /> 为 <see langword="false" /> 或其他定义值无效时抛出。</para>
		/// </exception>
		public static void RegisterLoop(string eventPath, string resourcePath, string busPath = "bus:/master/sfx", float volume = 1f, float pitch = 1f, bool stream = true)
		{
			Register(new VirtualFmodEventDefinition(eventPath, resourcePath, VirtualFmodEventKind.Loop, busPath, volume, pitch, stream));
		}

		/// <summary>
		///     <para xml:lang="en">Registers or replaces a streaming music event backed by a Godot audio resource.</para>
		///     <para xml:lang="zh-CN">注册或替换由 Godot 音频资源支撑的流式音乐事件。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The case-sensitive virtual event path.</para>
		///     <para xml:lang="zh-CN">区分大小写的虚拟事件路径。</para>
		/// </param>
		/// <param name="resourcePath">
		///     <para xml:lang="en">The packed, imported, or raw Godot audio-resource path.</para>
		///     <para xml:lang="zh-CN">打包、导入或原始 Godot 音频资源路径。</para>
		/// </param>
		/// <param name="busPath">
		///     <para xml:lang="en">The bus whose current volume is sampled when playback starts.</para>
		///     <para xml:lang="zh-CN">开始播放时采样当前音量的总线路径。</para>
		/// </param>
		/// <param name="volume">
		///     <para xml:lang="en">The finite, non-negative event-volume multiplier.</para>
		///     <para xml:lang="zh-CN">有限且非负的事件音量倍率。</para>
		/// </param>
		/// <param name="pitch">
		///     <para xml:lang="en">The finite, positive pitch multiplier.</para>
		///     <para xml:lang="zh-CN">有限且为正的音高倍率。</para>
		/// </param>
		public static void RegisterMusic(string eventPath, string resourcePath, string busPath = "bus:/master/music", float volume = 1f, float pitch = 1f)
		{
			Register(new VirtualFmodEventDefinition(eventPath, resourcePath, VirtualFmodEventKind.Music, busPath, volume, pitch, Stream: true));
		}

		/// <summary>
		///     <para xml:lang="en">Validates, snapshots, and registers or replaces a virtual event definition.</para>
		///     <para xml:lang="zh-CN">验证并快照虚拟事件定义，然后注册或替换该定义。</para>
		/// </summary>
		/// <param name="definition">
		///     <para xml:lang="en">The definition to register. Replacing an event resets its round-robin position.</para>
		///     <para xml:lang="zh-CN">要注册的定义。替换事件时会重置其轮询位置。</para>
		/// </param>
		public static void Register(VirtualFmodEventDefinition definition)
		{
			ArgumentNullException.ThrowIfNull(definition, "definition");
			if (string.IsNullOrWhiteSpace(definition.EventPath))
			{
				throw new ArgumentException("Virtual FMOD event path must be non-empty.", "definition");
			}
			if (string.IsNullOrWhiteSpace(definition.ResourcePath))
			{
				throw new ArgumentException("Virtual FMOD event resource path must be non-empty.", "definition");
			}
			if (!Enum.IsDefined(definition.Kind))
			{
				throw new ArgumentOutOfRangeException("definition", definition.Kind, "Virtual FMOD event kind is not defined.");
			}
			if (!Enum.IsDefined(definition.VariantSelection))
			{
				throw new ArgumentOutOfRangeException("definition", definition.VariantSelection, "Virtual FMOD variant selection mode is not defined.");
			}
			if (!float.IsFinite(definition.Volume) || definition.Volume < 0f)
			{
				throw new ArgumentOutOfRangeException("definition", definition.Volume, "Virtual FMOD event volume must be finite and non-negative.");
			}
			if (!float.IsFinite(definition.Pitch) || definition.Pitch <= 0f)
			{
				throw new ArgumentOutOfRangeException("definition", definition.Pitch, "Virtual FMOD event pitch must be finite and positive.");
			}
			if ((object)definition != null && definition.Kind == VirtualFmodEventKind.Loop && !definition.Stream)
			{
				throw new ArgumentException("Virtual FMOD loops require streaming playback because the bundled backend does not loop fully loaded sounds.", "definition");
			}
			IReadOnlyList<string> readOnlyList = ValidateResourcePaths(definition.ResourcePaths, "definition");
			if (definition.Kind != VirtualFmodEventKind.OneShot && readOnlyList.Count > 1)
			{
				throw new ArgumentException("Only one-shot virtual FMOD events can use resource variants.", "definition");
			}
			definition = definition with
			{
				ResourcePath = readOnlyList[0],
				ResourcePaths = readOnlyList
			};
			using (Gate.EnterScope())
			{
				Definitions[definition.EventPath] = definition;
				VariantIndexes.Remove(definition.EventPath);
			}
		}

		/// <summary>
		///     <para xml:lang="en">
		///         Removes a virtual event definition and its round-robin position without stopping active
		///         playback.
		///     </para>
		///     <para xml:lang="zh-CN">移除虚拟事件定义及其轮询位置，但不停止正在进行的播放。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The case-sensitive virtual event path.</para>
		///     <para xml:lang="zh-CN">区分大小写的虚拟事件路径。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en"><see langword="true" /> when a definition was removed; otherwise <see langword="false" />.</para>
		///     <para xml:lang="zh-CN">成功移除定义时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public static bool Unregister(string eventPath)
		{
			using (Gate.EnterScope())
			{
				VariantIndexes.Remove(eventPath);
				return Definitions.Remove(eventPath);
			}
		}

		/// <summary>
		///     <para xml:lang="en">Gets whether an exact event path is registered as a virtual event.</para>
		///     <para xml:lang="zh-CN">获取准确事件路径是否已注册为虚拟事件。</para>
		/// </summary>
		/// <param name="eventPath">
		///     <para xml:lang="en">The case-sensitive event path to test.</para>
		///     <para xml:lang="zh-CN">要测试的区分大小写事件路径。</para>
		/// </param>
		/// <returns>
		///     <para xml:lang="en">
		///         <see langword="true" /> when a nonblank exact path is registered; otherwise
		///         <see langword="false" />.
		///     </para>
		///     <para xml:lang="zh-CN">非空白的准确路径已注册时为 <see langword="true" />；否则为 <see langword="false" />。</para>
		/// </returns>
		public static bool IsRegistered(string? eventPath)
		{
			if (string.IsNullOrWhiteSpace(eventPath))
			{
				return false;
			}
			using (Gate.EnterScope())
			{
				return Definitions.ContainsKey(eventPath);
			}
		}

		internal static bool TryPlayOneShot(string eventPath, float volume, IReadOnlyDictionary<string, float>? parameters = null)
		{
			if (!TryGetDefinition(eventPath, out VirtualFmodEventDefinition definition))
			{
				return false;
			}
			if (definition.Kind != VirtualFmodEventKind.OneShot)
			{
				return false;
			}
			WarnIgnoredParameters(eventPath, parameters);
			return FmodStudioStreamingFiles.TryPlayResourceSound(SelectResourcePath(definition), ResolveVolume(definition, volume), definition.Pitch);
		}

		internal static bool TryPlayLoop(string eventPath)
		{
			if (!TryGetDefinition(eventPath, out VirtualFmodEventDefinition definition))
			{
				return false;
			}
			if (definition.Kind != VirtualFmodEventKind.Loop)
			{
				return false;
			}
			AudioSource source = (definition.Stream ? ((AudioSource)AudioSource.StreamingResourceMusic(definition.ResourcePath)) : ((AudioSource)AudioSource.ResourceFile(definition.ResourcePath)));
			AudioPlayResult audioPlayResult = GameFmod.Playback.Play(source, BuildOptions(definition, 1f, null, AudioLifecycleScope.Room));
			if (audioPlayResult.Succeeded)
			{
				IAudioHandle handle = audioPlayResult.Handle;
				if (handle != null && handle.IsValid)
				{
					using (Gate.EnterScope())
					{
						if (!Loops.TryGetValue(eventPath, out Queue<IAudioHandle> value))
						{
							value = new Queue<IAudioHandle>();
							Loops[eventPath] = value;
						}
						value.Enqueue(audioPlayResult.Handle);
					}
					return true;
				}
			}
			return false;
		}

		internal static bool TryStopLoop(string eventPath)
		{
			using (Gate.EnterScope())
			{
				if (!Loops.TryGetValue(eventPath, out Queue<IAudioHandle> value) || value.Count == 0)
				{
					return false;
				}
				IAudioHandle audioHandle = value.Peek();
				audioHandle.Dispose();
				if (!audioHandle.IsReleased)
				{
					return false;
				}
				value.Dequeue();
				if (value.Count == 0)
				{
					Loops.Remove(eventPath);
				}
				return true;
			}
		}

		internal static void StopAllLoops()
		{
			using (Gate.EnterScope())
			{
				string[] array = Loops.Keys.ToArray();
				foreach (string key in array)
				{
					Queue<IAudioHandle> queue = Loops[key];
					Queue<IAudioHandle> queue2 = new Queue<IAudioHandle>();
					foreach (IAudioHandle item in queue)
					{
						item.Dispose();
						if (!item.IsReleased)
						{
							queue2.Enqueue(item);
						}
					}
					if (queue2.Count == 0)
					{
						Loops.Remove(key);
					}
					else
					{
						Loops[key] = queue2;
					}
				}
			}
		}

		internal static bool TryPlayMusic(string eventPath)
		{
			if (!TryGetDefinition(eventPath, out VirtualFmodEventDefinition definition))
			{
				return false;
			}
			if (definition.Kind != VirtualFmodEventKind.Music)
			{
				return false;
			}
			if (!StopMusic())
			{
				return false;
			}
			AudioMusicHandle audioMusicHandle = GameFmod.Playback.PlayMusic(AudioSource.StreamingResourceMusic(definition.ResourcePath), BuildOptions(definition, 1f, "virtual-music", AudioLifecycleScope.Run));
			if (audioMusicHandle == null || !audioMusicHandle.IsValid)
			{
				return false;
			}
			using (Gate.EnterScope())
			{
				_music = audioMusicHandle;
			}
			return true;
		}

		internal static bool StopMusic()
		{
			using (Gate.EnterScope())
			{
				if (_music == null)
				{
					return true;
				}
				_music.Dispose();
				if (!_music.IsReleased)
				{
					return false;
				}
				_music = null;
				return true;
			}
		}

		internal static bool HasActiveMusic()
		{
			using (Gate.EnterScope())
			{
				return _music?.IsValid ?? false;
			}
		}

		internal static bool TrySetParameter(string eventPath, string parameter, float value)
		{
			return IsRegistered(eventPath);
		}

		private static bool TryGetDefinition(string eventPath, out VirtualFmodEventDefinition definition)
		{
			using (Gate.EnterScope())
			{
				return Definitions.TryGetValue(eventPath, out definition);
			}
		}

		private static string SelectResourcePath(VirtualFmodEventDefinition definition)
		{
			if (definition.ResourcePaths.Count == 1)
			{
				return definition.ResourcePaths[0];
			}
			int index = definition.VariantSelection switch
			{
				VirtualFmodVariantSelection.Random => Random.Shared.Next(definition.ResourcePaths.Count), 
				VirtualFmodVariantSelection.RoundRobin => NextRoundRobinIndex(definition.EventPath, definition.ResourcePaths.Count), 
				_ => 0, 
			};
			return definition.ResourcePaths[index];
		}

		private static int NextRoundRobinIndex(string eventPath, int count)
		{
			using (Gate.EnterScope())
			{
				int valueOrDefault = VariantIndexes.GetValueOrDefault(eventPath, 0);
				VariantIndexes[eventPath] = (valueOrDefault + 1) % count;
				return valueOrDefault;
			}
		}

		private static IReadOnlyList<string> ValidateResourcePaths(IReadOnlyList<string>? resourcePaths, string parameterName)
		{
			if (resourcePaths == null || resourcePaths.Count == 0)
			{
				throw new ArgumentException("Virtual FMOD event resource paths must be non-empty.", parameterName);
			}
			string[] array = new string[resourcePaths.Count];
			for (int i = 0; i < resourcePaths.Count; i++)
			{
				string text = resourcePaths[i];
				if (string.IsNullOrWhiteSpace(text))
				{
					throw new ArgumentException("Virtual FMOD event resource paths must be non-empty.", parameterName);
				}
				array[i] = text;
			}
			return new ReadOnlyCollection<string>(array);
		}

		private static AudioPlaybackOptions BuildOptions(VirtualFmodEventDefinition definition, float callVolume, string? channel, AudioLifecycleScope scope)
		{
			return new AudioPlaybackOptions
			{
				Volume = ResolveVolume(definition, callVolume),
				Pitch = definition.Pitch,
				Scope = scope,
				Routing = (string.IsNullOrWhiteSpace(channel) ? null : new AudioRoutingOptions
				{
					Channel = channel,
					ChannelMode = AudioChannelMode.ReplaceExisting
				})
			};
		}

		private static float ResolveVolume(VirtualFmodEventDefinition definition, float callVolume)
		{
			return definition.Volume * callVolume * ResolveBusVolume(definition.BusPath);
		}

		private static float ResolveBusVolume(string? busPath)
		{
			if (string.IsNullOrWhiteSpace(busPath))
			{
				return 1f;
			}
			if (FmodStudioServer.TryCheckBusPath(busPath) != true)
			{
				return 1f;
			}
			return Math.Max(0f, FmodStudioBusAccess.TryGetVolume(busPath));
		}

		private static void WarnIgnoredParameters(string eventPath, IReadOnlyDictionary<string, float>? parameters)
		{
			if (parameters != null && parameters.Count > 0)
			{
				RitsuLibFramework.Logger.Warn($"[Audio] virtual FMOD event ignores Studio parameters: {eventPath} ({parameters.Count} parameter(s)).", 1);
			}
		}
	}
	/// <summary>
	///     <para xml:lang="en">Defines an FMOD-style virtual event backed by one or more Godot audio resources.</para>
	///     <para xml:lang="zh-CN">定义由一个或多个 Godot 音频资源支撑的 FMOD 风格虚拟事件。</para>
	/// </summary>
	/// <param name="EventPath">
	///     <para xml:lang="en">The case-sensitive virtual event path.</para>
	///     <para xml:lang="zh-CN">区分大小写的虚拟事件路径。</para>
	/// </param>
	/// <param name="ResourcePath">
	///     <para xml:lang="en">The primary packed, imported, or raw Godot audio-resource path.</para>
	///     <para xml:lang="zh-CN">主要的打包、导入或原始 Godot 音频资源路径。</para>
	/// </param>
	/// <param name="Kind">
	///     <para xml:lang="en">The playback role supported by the event.</para>
	///     <para xml:lang="zh-CN">事件支持的播放用途。</para>
	/// </param>
	/// <param name="BusPath">
	///     <para xml:lang="en">The bus whose current volume is sampled when playback starts.</para>
	///     <para xml:lang="zh-CN">开始播放时采样当前音量的总线路径。</para>
	/// </param>
	/// <param name="Volume">
	///     <para xml:lang="en">The finite, non-negative event-volume multiplier.</para>
	///     <para xml:lang="zh-CN">有限且非负的事件音量倍率。</para>
	/// </param>
	/// <param name="Pitch">
	///     <para xml:lang="en">The finite, positive pitch multiplier.</para>
	///     <para xml:lang="zh-CN">有限且为正的音高倍率。</para>
	/// </param>
	/// <param name="Stream">
	///     <para xml:lang="en">
	///         Whether file playback uses the streaming, looping backend mode. Registered loops require this
	///         to be <see langword="true" />.
	///     </para>
	///     <para xml:lang="zh-CN">文件播放是否使用流式循环后端模式。注册循环事件时必须为 <see langword="true" />。</para>
	/// </param>
	public sealed record VirtualFmodEventDefinition(string EventPath, string ResourcePath, VirtualFmodEventKind Kind, string BusPath = "bus:/master/sfx", float Volume = 1f, float Pitch = 1f, bool Stream = false)
	{
		/// <summary>
		///     <para xml:lang="en">
		///         Gets or initializes the resource variants used by a one-shot event; loops and music require
		///         exactly one.
		///     </para>
		///     <para xml:lang="zh-CN">获取或初始化单次事件使用的资源变体；循环和音乐事件必须恰好使用一个资源。</para>
		/// </summary>
		public IReadOnlyList<string> ResourcePaths { get; init; } = new <>z__ReadOnlySingleElementList<string>(ResourcePath);

		/// <summary>
		///     <para xml:lang="en">Gets or initializes how one-shot resource variants are selected.</para>
		///     <para xml:lang="zh-CN">获取或初始化单次事件资源变体的选择方式。</para>
		/// </summary>
		public VirtualFmodVariantSelection VariantSelection { get; init; }
	}
	/// <summary>
	///     <para xml:lang="en">Specifies how a one-shot virtual event selects a resource variant.</para>
	///     <para xml:lang="zh-CN">指定单次虚拟事件选择资源变体的方式。</para>
	/// </summary>
	public enum VirtualFmodVariantSelection
	{
		/// <summary>
		///     <para xml:lang="en">Selects a resource independently through <see cref="P:System.Random.Shared" /> for each playback.</para>
		///     <para xml:lang="zh-CN">每次播放时通过 <see cref="P:System.Random.Shared" /> 独立随机选择资源。</para>
		/// </summary>
		Random,
		/// <summary>
		///     <para xml:lang="en">Cycles through resources in registration order, restarting after registration or replacement.</para>
		///     <para xml:lang="zh-CN">按注册顺序轮询资源；注册或替换后从头开始。</para>
		/// </summary>
		RoundRobin
	}
	/// <summary>
	///     <para xml:lang="en">Specifies the playback role of a virtual FMOD event.</para>
	///     <para xml:lang="zh-CN">指定虚拟 FMOD 事件的播放用途。</para>
	/// </summary>
	public enum VirtualFmodEventKind
	{
		/// <summary>
		///     <para xml:lang="en">A fully loaded sound played once.</para>
		///     <para xml:lang="zh-CN">完整加载并单次播放的音效。</para>
		/// </summary>
		OneShot,
		/// <summary>
		///     <para xml:lang="en">A streaming, looping sound tracked in the room lifecycle scope.</para>
		///     <para xml:lang="zh-CN">在房间生命周期作用域中跟踪的流式循环音效。</para>
		/// </summary>
		Loop,
		/// <summary>
		///     <para xml:lang="en">A streaming music track that replaces the current virtual music channel.</para>
		///     <para xml:lang="zh-CN">替换当前虚拟音乐通道的流式音乐轨道。</para>
		/// </summary>
		Music
	}
}
namespace STS2RitsuLib.Audio.Patches
{
	/// <summary>
	///     <para xml:lang="en">
	///         Patches <see cref="T:MegaCrit.Sts2.Core.Nodes.Audio.NAudioManager" /> so <c>event:/…</c> paths present in <c>guids.txt</c> and mod banks,
	///         but absent from a strings bank, follow the native one-shot, loop, and music entry points.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         修补 <see cref="T:MegaCrit.Sts2.Core.Nodes.Audio.NAudioManager" />，使存在于 <c>guids.txt</c> 和模组音频库、但不存在于 strings bank
	///         中的 <c>event:/…</c> 路径能够沿用原生的单次、循环和音乐入口。
	///     </para>
	/// </summary>
	internal static class NAudioManagerGuidMappedStudioEventsPatches
	{
		/// <summary>
		///     <para xml:lang="en">Routes mapped and virtual one-shot paths before the native path table is consulted.</para>
		///     <para xml:lang="zh-CN">在查询原生路径表前路由已映射和虚拟的单次事件路径。</para>
		/// </summary>
		internal sealed class PlayOneShot : IPatchMethod
		{
			public static string PatchId => "naudio_guid_mapped_play_one_shot";

			public static bool IsCritical => false;

			public static string Description => "GUID-backed PlayOneShot when event path is listed in guids.txt";

			public static ModPatchTarget[] GetTargets()
			{
				return new ModPatchTarget[1]
				{
					new ModPatchTarget(typeof(NAudioManager), "PlayOneShot", new Type[3]
					{
						typeof(string),
						typeof(Dictionary<string, float>),
						typeof(float)
					})
				};
			}

			public static bool Prefix(NAudioManager __instance, string path, Dictionary<string, float> parameters, float volume)
			{
				if (TestMode.IsOn)
				{
					return true;
				}
				if (string.IsNullOrWhiteSpace(path))
				{
					return false;
				}
				if (VirtualFmodEventRegistry.IsRegistered(path))
				{
					if (!VirtualFmodEventRegistry.TryPlayOneShot(path, volume, parameters))
					{
						RitsuLibFramework.Logger.Warn("[Audio] Virtual FMOD event is not a playable one-shot: " + path, 1);
					}
					return false;
				}
				if (!FmodStudioGuidPathTable.TryGetStudioGuidForEventPath(path, out string guid))
				{
					LogMissingStudioPathOnce("PlayOneShot", path);
					return true;
				}
				if (FmodStudioDirectOneShots.TryFireOneShotForMappedEventPath(path, volume, parameters))
				{
					return false;
				}
				RitsuLibFramework.Logger.Warn("[Audio] Mapped FMOD one-shot failed. " + FmodStudioMappedOneShotDiagnostics.BuildMappedOneShotFailureDetail(path, guid), 1);
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Routes mapped and virtual loop paths through their retained loop queues.</para>
		///     <para xml:lang="zh-CN">通过对应的保留循环队列路由已映射和虚拟的循环路径。</para>
		/// </summary>
		internal sealed class PlayLoop : IPatchMethod
		{
			public static string PatchId => "naudio_guid_mapped_play_loop";

			public static bool IsCritical => false;

			public static string Description => "GUID-backed PlayLoop when event path is listed in guids.txt";

			public static ModPatchTarget[] GetTargets()
			{
				return new ModPatchTarget[1]
				{
					new ModPatchTarget(typeof(NAudioManager), "PlayLoop", new Type[2]
					{
						typeof(string),
						typeof(bool)
					})
				};
			}

			public static bool Prefix(NAudioManager __instance, string path, bool usesLoopParam)
			{
				if (TestMode.IsOn)
				{
					return true;
				}
				if (string.IsNullOrWhiteSpace(path))
				{
					return false;
				}
				if (VirtualFmodEventRegistry.IsRegistered(path))
				{
					if (!VirtualFmodEventRegistry.TryPlayLoop(path))
					{
						RitsuLibFramework.Logger.Warn("[Audio] Virtual FMOD event is not a playable loop: " + path, 1);
					}
					return false;
				}
				if (!GuidMappedNaudioStudioProxy.IsMappedPath(path))
				{
					LogMissingStudioPathOnce("PlayLoop", path);
					return true;
				}
				if (GuidMappedNaudioStudioProxy.TryEnqueueMappedLoop(path, usesLoopParam))
				{
					return false;
				}
				if (FmodStudioGuidPathTable.TryGetStudioGuidForEventPath(path, out string guid))
				{
					RitsuLibFramework.Logger.Warn("[Audio] Mapped PlayLoop failed. " + FmodStudioMappedOneShotDiagnostics.BuildMappedOneShotFailureDetail(path, guid), 1);
				}
				return false;
			}
		}

		/// <summary>
		///     <para xml:lang="en">Stops the oldest retained mapped or virtual loop for a path.</para>
		///     <para xml:lang="zh-CN">停止路径下最早保留的映射或虚拟循环。</para>
		/// </summary>
		internal sealed class StopLoop : IPatchMethod
		{
			public static string PatchId => "naudio_guid_mapped_stop_loop";

			public static bool IsCritical => false;

			public static string Description => "Stop mapped PlayLoop instances keyed by guids.txt paths";

			public static ModPatchTarget[] GetTargets()
			{
				return new ModPatchTarget[1]
				{
					new ModPatchTarget(typeof(NAudioManager), "StopLoop", new Type[1] { typeof(string) })
				};
			}

			public static bool Prefix(NAudioManager __instance, string path)
			{
				if (TestMode.IsOn)
				{
					return true;
				}
