		/// <summary>
		///     <para xml:lang="en">
		///         Switches between native, mapped, and virtual music without leaving the previous custom instance
		///         active.
		///     </para>
		///     <para xml:lang="zh-CN">在原生、映射和虚拟音乐之间切换，并确保先前的自定义实例不再活动。</para>
		/// </summary>
		internal sealed class PlayMusic : IPatchMethod
		{
			public static string PatchId => "naudio_guid_mapped_play_music";

			public static bool IsCritical => false;

			public static string Description => "GUID-backed PlayMusic when event path is listed in guids.txt";

			public static ModPatchTarget[] GetTargets()
			{
				return new ModPatchTarget[1]
				{
					new ModPatchTarget(typeof(NAudioManager), "PlayMusic", new Type[1] { typeof(string) })
				};
			}

			public static bool Prefix(NAudioManager __instance, string music)
			{
				if (TestMode.IsOn)
				{
					return true;
				}
				if (string.IsNullOrWhiteSpace(music))
				{
					return false;
				}
				if (VirtualFmodEventRegistry.IsRegistered(music))
				{
					if (!TryStopCustomMusic())
					{
						return false;
					}
					__instance.StopMusic();
					if (!VirtualFmodEventRegistry.TryPlayMusic(music))
					{
						RitsuLibFramework.Logger.Warn("[Audio] Virtual FMOD event is not playable as music: " + music, 1);
					}
					return false;
				}
				if (!GuidMappedNaudioStudioProxy.IsMappedPath(music))
				{
					if (!TryStopCustomMusic())
					{
						return false;
					}
					LogMissingStudioPathOnce("PlayMusic", music);
					return true;
				}
				if (!TryStopCustomMusic())
				{
					return false;
				}
				__instance.StopMusic();
				if (GuidMappedNaudioStudioProxy.TryStartMappedMusic(music))
				{
					return false;
				}
				if (FmodStudioGuidPathTable.TryGetStudioGuidForEventPath(music, out string guid))
				{
					RitsuLibFramework.Logger.Warn("[Audio] Mapped PlayMusic failed. " + FmodStudioMappedOneShotDiagnostics.BuildMappedOneShotFailureDetail(music, guid), 1);
				}
				return false;
			}
		}

