		private static void LogMissingStudioPathOnce(string operation, string path)
		{
			if (!path.StartsWith("event:/", StringComparison.Ordinal) || VirtualFmodEventRegistry.IsRegistered(path) || FmodStudioServer.TryCheckEventPath(path) != false)
			{
				return;
			}
			string item = operation + "\0" + path;
			using (MissingStudioPathWarningGate.EnterScope())
			{
				if (!MissingStudioPathWarningLoggedKeys.Add(item))
				{
					return;
				}
			}
			RitsuLibFramework.Logger.Warn($"[Audio] FMOD event was not found in GUID mappings or loaded Studio events. operation={operation}; path={path}; guidMapEventCount={FmodStudioGuidPathTable.EventMappingCount}; loadedBankCount={FmodStudioServer.TryGetLoadedBankCount()}; loadedEventDescriptionCount={FmodStudioServer.TryGetLoadedEventDescriptionCount()}; banksStillLoading={FmodStudioServer.TryBanksStillLoading()?.ToString() ?? "?"}", 1);
		}
	}
