		{
			ReadOnlySpan<char> input = stored.AsSpan().Trim();
			if (input.Length >= 3 && input[0] == '{')
			{
				if (input[input.Length - 1] == '}')
				{
					if (Guid.TryParse(input.Slice(1, input.Length - 1 - 1), out parsed))
					{
						return true;
					}
				}
			}
			return Guid.TryParse(input, out parsed);
		}

		internal static IReadOnlyList<KeyValuePair<string, string>> SnapshotEventMappings()
		{
