	internal static class FmodStudioMappedOneShotDiagnostics
	{
		internal static string BuildMappedOneShotFailureDetail(string eventPath, string mappedGuidBraced)
		{
			try
			{
				StringBuilder stringBuilder = new StringBuilder(768);
				stringBuilder.Append("path=").Append(eventPath).Append("; guidsTxtGuid=")
					.Append(mappedGuidBraced);
				string text = TryServerString(FmodStudioMethodNames.GetEventGuid, eventPath);
				stringBuilder.Append("; FMOD_get_event_guid(path)=");
				AppendGuidOrNone(stringBuilder, text);
				if (FmodStudioGuidInterop.TryNormalizeForAddon(mappedGuidBraced, out string bracedLowercase))
				{
					string text2 = TryServerString(FmodStudioMethodNames.GetEventPath, bracedLowercase);
					stringBuilder.Append("; FMOD_get_event_path(guidsTxtGuid)=");
					stringBuilder.Append(string.IsNullOrEmpty(text2) ? "(none — GUID not in loaded banks)" : text2);
				}
				if (!string.IsNullOrEmpty(text) && !IsZeroLikeGuidString(text) && GuidStringsEqualLoose(text, mappedGuidBraced) == false)
				{
					stringBuilder.Append("; path→GUID mismatch: runtime cache maps this path to a different GUID than guids.txt — rebuild guids.txt from the same .bank files you ship.");
				}
				stringBuilder.Append("; banks[eventCount]: ");
				stringBuilder.Append(SummarizeLoadedBanks());
				string text3 = LastPathSegment(eventPath);
				if (!string.IsNullOrEmpty(text3))
				{
					stringBuilder.Append("; cache scan paths containing '");
					stringBuilder.Append(text3);
					stringBuilder.Append("': ");
					stringBuilder.Append(ScanDescriptionsContaining(text3));
				}
				stringBuilder.Append("; banks_still_loading=").Append(FmodStudioServer.TryBanksStillLoading()?.ToString() ?? "?");
				return stringBuilder.ToString();
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[Audio] Mapped one-shot diagnostics failed: {value}");
				return $"diagnostics failed: {value}";
			}
		}

		private static void AppendGuidOrNone(StringBuilder sb, string? guidFromServer)
		{
			if (string.IsNullOrEmpty(guidFromServer) || IsZeroLikeGuidString(guidFromServer))
			{
				sb.Append("(none — path not in FMOD string table / no loaded description for path)");
			}
			else
			{
				sb.Append(guidFromServer);
			}
		}

		private static bool IsZeroLikeGuidString(string s)
		{
			ReadOnlySpan<char> s2 = s.AsSpan().Trim();
			if (s2.Length >= 2 && s2[0] == '{')
			{
				if (s2[s2.Length - 1] == '}')
				{
					s2 = s2.Slice(1, s2.Length - 1 - 1);
				}
			}
			if (Guid.TryParse(s2, CultureInfo.InvariantCulture, out var result))
			{
				return result == Guid.Empty;
			}
			return false;
		}

		private static bool? GuidStringsEqualLoose(string a, string b)
		{
			if (!Guid.TryParse(a.Trim().TrimStart('{').TrimEnd('}'), CultureInfo.InvariantCulture, out var result))
			{
				return null;
			}
			if (!Guid.TryParse(b.Trim().TrimStart('{').TrimEnd('}'), CultureInfo.InvariantCulture, out var result2))
			{
				return null;
			}
			return result.Equals(result2);
		}

		private static string? TryServerString(StringName method, string arg)
		{
