		private static string LastPathSegment(string eventPath)
		{
			if (string.IsNullOrEmpty(eventPath))
			{
				return string.Empty;
			}
			string text = eventPath.TrimEnd('/');
			int num = text.LastIndexOf('/');
			if (num < 0 || num + 1 >= text.Length)
			{
				return text;
			}
			return text.Substring(num + 1);
		}

