		private static string ScanDescriptionsContaining(string needle)
		{
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0025: Invalid comparison between Unknown and I8
			//IL_0047: Unknown result type (might be due to invalid IL or missing references)
			//IL_004c: Unknown result type (might be due to invalid IL or missing references)
			//IL_004f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0057: Invalid comparison between Unknown and I8
			//IL_008a: Unknown result type (might be due to invalid IL or missing references)
			//IL_008f: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ab: Unknown result type (might be due to invalid IL or missing references)
			//IL_00b0: Unknown result type (might be due to invalid IL or missing references)
			if (needle.Length == 0 || !FmodStudioGateway.TryCall(out var result, FmodStudioMethodNames.GetAllEventDescriptions) || (long)((Variant)(ref result)).VariantType != 28)
			{
				return "(unavailable)";
			}
			List<string> list = new List<string>(6);
			foreach (Variant item in ((Variant)(ref result)).AsGodotArray())
			{
				Variant current = item;
				if ((long)((Variant)(ref current)).VariantType != 24)
				{
					continue;
				}
				GodotObject val = ((Variant)(ref current)).AsGodotObject();
				if (val != null && GodotObject.IsInstanceValid(val))
				{
					string text;
					string text2;
					try
					{
						Variant val2 = val.Call(StringName.op_Implicit("get_path"), Array.Empty<Variant>());
						text = ((Variant)(ref val2)).AsString();
						val2 = val.Call(StringName.op_Implicit("get_guid"), Array.Empty<Variant>());
						text2 = ((Variant)(ref val2)).AsString();
					}
					catch (Exception value)
					{
						RitsuLibFramework.Logger.ErrorNoTrace($"[Audio] Failed to inspect an FMOD event description during mapped one-shot diagnostics: {value}");
						continue;
					}
					if (text.Contains(needle, StringComparison.OrdinalIgnoreCase))
					{
						list.Add(text + "→" + text2);
					}
					if (list.Count >= 5)
					{
