	/// <summary>
	///     <para xml:lang="en">
	///         Mirrors the loop, music, and run-audio ownership used by <c>audio_manager_proxy.gd</c> for
	///         <c>event:/…</c> paths available through <c>guids.txt</c> and mod banks but absent from a strings bank.
	///     </para>
	///     <para xml:lang="zh-CN">
	///         对可通过 <c>guids.txt</c> 和模组音频库访问、但不存在于 strings bank 中的 <c>event:/…</c>
	///         路径，复现 <c>audio_manager_proxy.gd</c> 使用的循环、音乐和局内音频归属管理。
	///     </para>
	/// </summary>
	internal static class GuidMappedNaudioStudioProxy
	{
		private sealed record LoopSlot(GodotObject Instance, bool UsesLoopParam, bool ReleaseScheduled);

		private static readonly Lock Gate = new Lock();

		private static readonly Dictionary<string, List<LoopSlot>> LoopQueues = new Dictionary<string, List<LoopSlot>>(StringComparer.Ordinal);

		private static GodotObject? _musicInstance;

		private static GodotObject? _runMusicInstance;

		private static GodotObject? _runAmbienceInstance;

		private static string? _runMusicPath;

		private static string? _runAmbiencePath;

		internal static bool IsMappedPath(string? path)
		{
			string guid;
			if (!string.IsNullOrEmpty(path))
			{
				return FmodStudioGuidPathTable.TryGetStudioGuidForEventPath(path, out guid);
			}
			return false;
		}

		internal static void StopAllMappedLoops()
		{
			using (Gate.EnterScope())
			{
				string[] array = LoopQueues.Keys.ToArray();
				foreach (string key in array)
				{
					List<LoopSlot> list = LoopQueues[key];
					list.RemoveAll((LoopSlot slot) => StopSlot(slot));
					if (list.Count == 0)
					{
						LoopQueues.Remove(key);
					}
				}
			}
		}

		internal static bool TryEnqueueMappedLoop(string path, bool usesLoopParam)
		{
			GodotObject val = FmodStudioEventInstances.TryCreate(path);
			if (val == null)
			{
				return false;
			}
			if (!FmodStudioEventInstances.TryStart(val))
			{
				DisposeUnownedInstance(path, val);
				return false;
			}
			bool releaseScheduled = FmodStudioEventInstances.TryScheduleRelease(val);
			using (Gate.EnterScope())
			{
				if (!LoopQueues.TryGetValue(path, out List<LoopSlot> value))
				{
					value = new List<LoopSlot>();
					LoopQueues[path] = value;
				}
				value.Add(new LoopSlot(val, usesLoopParam, releaseScheduled));
			}
			return true;
		}

		internal static bool TryStopMappedLoop(string path)
		{
			using (Gate.EnterScope())
			{
				return StopMappedLoopCore(path);
			}
		}

		private static bool StopMappedLoopCore(string path)
		{
			if (!LoopQueues.TryGetValue(path, out List<LoopSlot> value) || value.Count == 0)
			{
				return false;
			}
			if (!StopSlot(value[0]))
			{
				return false;
			}
			value.RemoveAt(0);
			if (value.Count == 0)
			{
				LoopQueues.Remove(path);
			}
			return true;
		}

		private static bool StopSlot(LoopSlot slot)
		{
			//IL_0076: Unknown result type (might be due to invalid IL or missing references)
			//IL_007b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0080: Unknown result type (might be due to invalid IL or missing references)
			//IL_0035: Unknown result type (might be due to invalid IL or missing references)
			//IL_003f: Expected O, but got Unknown
			//IL_003a: Unknown result type (might be due to invalid IL or missing references)
			//IL_003f: Unknown result type (might be due to invalid IL or missing references)
			//IL_004b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0050: Unknown result type (might be due to invalid IL or missing references)
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			if (!GodotObject.IsInstanceValid(slot.Instance))
			{
				return true;
			}
			try
			{
				if (slot.UsesLoopParam)
				{
					slot.Instance.Call(StringName.op_Implicit("set_parameter_by_name"), (Variant[])(object)new Variant[2]
					{
						Variant.op_Implicit(new StringName("loop")),
						Variant.op_Implicit(1f)
					});
				}
				else
				{
					slot.Instance.Call(StringName.op_Implicit("stop"), (Variant[])(object)new Variant[1] { Variant.op_Implicit(1) });
				}
			}
			catch (Exception value)
			{
				RitsuLibFramework.Logger.ErrorNoTrace($"[Audio] mapped StopLoop: {value}");
				return false;
			}
			if (!slot.ReleaseScheduled)
			{
				return FmodStudioEventInstances.TryScheduleRelease(slot.Instance);
			}
			return true;
		}

